window.TURATH_DATA.hadith.push(...[{"num":4586,"demo":false,"sanad":"","matn":["عن عائشة: أنّ حمزة بن عمرو الأسلميّ، قال لرسول اللّٰه ﷺ: أأصومُ في السفر؟ وكان كثير الصيام، فقال له رسول اللّٰه ﷺ:","(( إن شئتَ فصُمْ، وإن شئت فأفطر ))."],"takhrij":"متفق عليه: رواه مالك (في رواية أبي مصعب الزهري - ٧٩٤)، والبخاري (١٩٤٣)، ومسلم (١١٢١).","grade":"متفق عليه","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (in the narration of Abu Musʿab al-Zuhri, 794), al-Bukhari (1943), and Muslim (1121).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah reported that Hamzah ibn ʿAmr al-Aslami said to the Messenger of Allah ﷺ: Shall I fast while traveling? He used to fast often. The Messenger of Allah ﷺ said to him:","“If you wish, then fast, and if you wish, then break the fast.”"]},"intro":{"ar":["قال الله تعالى: ( أَيَّامًا مَعْدُودَاتٍ فَمَن كَانَ مِنكُم مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ ) [سورة البقرة: ١٨٤].","وقال تعالى: ( فَمَن شَهِدَ مِنكُمُ الشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ ) [سورة البقرة: ١٨٥].","قوله: (( فمن أخذ بها فحسن )) فيه إشارة إلى تفضيل الفطر في السفر على الصيام.","قال ابن عبد البر: (( وفي هذا الحديث التخيير للصائم في رمضان إن شاء أن يصوم في سفره، وإن شاء أن يفطر. وهو أمر مجمع عليه من جماعة فقهاء الأمصار، وهو الصحيح في هذا الباب )). “التمهيد” (١٤٧/٢٢)."],"en":["Allah the Exalted said: “For a limited number of days. So whoever among you is ill or on a journey, then an equal number of other days.” [al-Baqarah 2:184]","And He said: “So whoever among you witnesses the month must fast it, and whoever is ill or on a journey, then an equal number of other days. Allah intends ease for you and does not intend hardship for you.” [al-Baqarah 2:185]","His phrase, “Whoever takes it, that is good,” indicates that breaking the fast while traveling is preferable to fasting.","Ibn ʿAbd al-Barr said: “This hadith gives the fasting person in Ramadan a choice: if he wishes he may fast during his journey, and if he wishes he may break the fast. This is a matter agreed upon by the leading jurists of the major cities, and it is the correct view in this chapter.” Al-Tamhid (22/147)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":794},{"key":"bukhari","label":"البخاري","number":1943},{"key":"muslim","label":"مسلم","number":1121}]},{"num":4587,"demo":false,"sanad":"","matn":["عن حمزة بن عمرو الأسلميّ، قال: يا رسول اللّٰه أجدُ بي قوّةً على الصيام في السفر، فهل عليَّ جناحٌ؟ فقال رسولُ الله ﷺ:","(( هي رخصةٌ من الله، فمَنْ أخذَ بها فحسنٌ، ومَنْ أحبَّ أن يصوم فلا جناحَ عليه ))."],"takhrij":"صحيح: رواه مسلم (١١٢١:١٠٧).","grade":"صحيح","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1121 no. 107).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Hamzah ibn ʿAmr al-Aslami said: O Messenger of Allah, I find in myself the strength to fast while traveling, so is there any blame upon me? The Messenger of Allah ﷺ said:","“It is a concession from Allah. Whoever takes it, that is good, and whoever prefers to fast, there is no blame upon him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1121}]},{"num":4588,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أنه قال: سافرنا مع رسول اللّٰه ﷺ في رمضان، فلم يَعِب الصَّائمُ على المفطر، ولا المفطر على الصّائم."],"takhrij":"متفق عليه: رواه مالك (٢٣)، والبخاريّ (١٩٤٧)، ومسلم (١١١٨).","grade":"متفق عليه","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (23), al-Bukhari (1947), and Muslim (1118).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Malik said: We traveled with the Messenger of Allah ﷺ in Ramadan, and the fasting one did not criticize the one who broke the fast, nor did the one who broke the fast criticize the fasting one."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":23},{"key":"bukhari","label":"البخاريّ","number":1947},{"key":"muslim","label":"مسلم","number":1118}]},{"num":4589,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس قال: لا تعبْ على من صام، ولا على من أفطر، فقد صام رسول اللّٰه ﷺ في السفر وأفطر."],"takhrij":"صحيح: رواه مسلم (١١١٣:٨٩).","grade":"صحيح","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1113 no. 89).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: Do not criticize the one who fasted, nor the one who broke the fast, for the Messenger of Allah ﷺ fasted while traveling and also broke the fast."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1113}]},{"num":4590,"demo":false,"sanad":"","matn":["عن أبي الدرداء، قال: خرجنا مع رسول اللّٰه ﷺ في شهر رمضان في حرِّ شديد، حتّى إن كان أحدُنا ليضعُ يدَه على رأسه من شدّة الحرِّ، وما فينا صائمٌ إلا رسول اللّٰه ﷺ وعبد الله بن رواحة."],"takhrij":"متفق عليه: رواه البخاريّ (١٩٤٥)، ومسلم (١١٢٢). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1945) and Muslim (1122). The wording is that of Muslim.","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abu al-Darda’ said: We went out with the Messenger of Allah ﷺ in the month of Ramadan during intense heat, to the point that one of us would place his hand on his head because of the severity of the heat. None of us was fasting except the Messenger of Allah ﷺ and ʿAbdullah ibn Rawahah."]},"buhuth":{"ar":["ولفظ البخاري: خرجنا مع النبيّ ﷺ في بعض أسفاره في يوم حار حتى يضع الرجل يده على رأسه من شدة الحر، وما فينا صائم إلا ما كان من النبي ﷺ وابن رواحة."],"en":["Al-Bukhari’s wording is: We went out with the Prophet ﷺ on one of his journeys on a hot day until a man would place his hand on his head because of the extreme heat, and none of us was fasting except the Prophet ﷺ and Ibn Rawahah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1945},{"key":"muslim","label":"مسلم","number":1122}]},{"num":4591,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: (( غزونا مع رسول اللّٰه ﷺ لست عشرة مضت من رمضان، فمنّا من صام، ومنّا من أفطر، فلم يَعِب الصَّائم على المُفطر، ولا المفطر على الصَّائم ))."],"takhrij":"صحيح: رواه مسلم (١١١٦).","grade":"صحيح","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1116).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: “We went out on an expedition with the Messenger of Allah ﷺ when sixteen days of Ramadan had passed. Some of us fasted and some of us broke the fast, and the fasting one did not criticize the one who broke the fast, nor did the one who broke the fast criticize the fasting one.”"]},"buhuth":{"ar":["ووقع في رواية له: (( لثمانَ عشرةَ خلتْ )). وفي رواية: (( في ثِنْتَي عشرة )). وفي رواية: (( لسبعَ عشرة أو تسع عشرة ))."],"en":["In another narration of Muslim it says: “when eighteen days had passed.” In another narration: “on the twelfth.” And in another: “on the seventeenth or nineteenth.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1116}]},{"num":4592,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، وجابر بن عبدالله، قالا: (( سافرنا مع رسول اللّٰه ﷺ، فيصوم الصَّائمُ ويفطرُ المفطر، فلا يعيبُ بعضُهم على بعض ))."],"takhrij":"صحيح: رواه مسلم (١١١٧).","grade":"صحيح","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1117).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Abu Saʿid al-Khudri and Jabir ibn ʿAbdullah said: “We traveled with the Messenger of Allah ﷺ, and the fasting person would fast while the one breaking the fast would break it, and they would not criticize one another.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1117}]},{"num":4593,"demo":false,"sanad":"","matn":["عن عمران بن حصين، قال: كان النبيّ ﷺ يمشي حافياً وناعلاً، ويشرب قائماً وقاعداً، وينفتل عن يمينه وعن يساره، ويصوم في السفر ويفطر."],"takhrij":"حسن: رواه البزار - كشف الأستار (٩٩٣).","grade":"حسن","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Bazzar in Kashf al-Astar (993).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["ʿImran ibn Husayn said: The Prophet ﷺ used to walk barefoot and with sandals, drink standing and sitting, turn away to his right and to his left, and fast while traveling and also break the fast."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":993},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":993,"n":994}]},{"num":4594,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عمرو بن العاص قال: رأيت رسول اللّٰه ﷺ يصلي حافياً وناعلاً، ويصوم في السفر ويُفطر، ويشرب قائما وقاعدا، وينصرف عن يمينه وعن شماله."],"takhrij":"حسن: رواه أحمد (٧٠١٢، ٦٩٢٨، ٦٦٧٩).","grade":"حسن","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (7012, 6928, 6679).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs said: I saw the Messenger of Allah ﷺ pray barefoot and with sandals, fast while traveling and break the fast, drink standing and sitting, and turn away to his right and to his left."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":6679,"n":6679}]},{"num":4595,"demo":false,"sanad":"","matn":["عن أنس، قال: إن رسول اللّٰه ﷺ كان في سفر ومعه أصحابه، فشقَّ عليهم الصوم، فدعا رسول اللّٰه ﷺ بإناء فيه ماء فشرب - وهو على راحلته -، والناس ينظرون إليه."],"takhrij":"حسن: رواه ابن خزيمة (٢٠٣٩)، والطحاوي (٣١٥٦).","grade":"حسن","chapter_ar":"باب تخيير المسافر بين الصيام والإفطار","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Khuzaymah (2039) and al-Tahawi (3156).","chapter_en":"Giving the traveler the choice between fasting and breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ was on a journey with his Companions, and fasting became difficult for them. So the Messenger of Allah ﷺ called for a vessel containing water and drank while on his riding animal, and the people were watching him."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2039},{"key":"الطحاوی","label":"الطحاوي","number":3156}]},{"num":4596,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ رسول اللّٰه ﷺ خرج إلى مكة عام الفتح في رمضان، فصام حتّى بلغ الكديد، ثم أفطر فأفطر الناسُ، وكانوا يأخذون بالأحدث فالأحدث من أمر رسول اللّٰه ﷺ."],"takhrij":"صحيح: رواه مالك (٢١)، والبخاري (١٩٤٤)، ومسلم (١١١٣).","grade":"صحيح","chapter_ar":"باب من قال بنسخ الصوم في السفر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Malik (21), al-Bukhari (1944), and Muslim (1113).","chapter_en":"Those who held that fasting while traveling was abrogated","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbas reported that the Messenger of Allah ﷺ went out to Makkah in the year of the Conquest during Ramadan. He fasted until he reached al-Kadid, then he broke his fast, and the people also broke their fast. And they used to follow the latest of the latest commands of the Messenger of Allah ﷺ."]},"intro":{"ar":["قال الله تعالى: ( وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ ) [البقرة: ١٨٥].","أي فرض المسافر عدّة أيام من أيام أخر."],"en":["Allah the Exalted said: “And whoever is ill or on a journey, then an equal number of other days.” [al-Baqarah 2:185]","Meaning: the traveler is required to make up an equal number of other days."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":21},{"key":"bukhari","label":"البخاري","number":1944},{"key":"muslim","label":"مسلم","number":1113}]},{"num":4597,"demo":false,"sanad":"","matn":["عن محمد بن كعب أنه قال: أتيت أنس بن مالك في رمضان وهو يريد سفراً، وقد رُحلتْ له راحلته، ولبس ثياب السّفر، فدعا بطعام فأكل. فقلت له: سنة؟ قال: سنة، ثم ركب."],"takhrij":"حسن: رواه الترمذي (٧٩٩)، والدارميّ (١٧٥٤)، والإمام أحمد (٢٧٢٣١)، وابن خزيمة (٢٠٤٠).","grade":"حسن","chapter_ar":"باب من قال: إن المسافر يفطر في بيته قبل أن يخرج","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (799), al-Darimi (1754), Imam Ahmad (27231), and Ibn Khuzaymah (2040).","chapter_en":"Those who said that the traveler may break the fast in his home before departing","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":16,"content":{"translation":{"en":["Muhammad ibn Kaʿb said: I came to Anas ibn Malik in Ramadan while he intended to travel. His riding animal had already been prepared for him, and he had put on his travel clothes. He called for food and ate. I said to him: Is this the Sunnah? He said: The Sunnah. Then he mounted."]},"intro":{"ar":["وبهذا قال الإمام أحمد في رواية. وقال جمهور أهل العلم منهم مالك وأبو حنيفة والشافعي وأحمد في رواية: من لا يفارق العمران إلا بعد الفجر فليس له الفطر في ذلك اليوم؛ لأنه ممن شهد الشهر وهو مقيم فيجب عليه أن يصوم؛ لأنّ النبيّ ﷺ لم يخرج من المدينة في شهر رمضان مفطراً، وإنما أفطر في الطريق.","وأما إن سافرَ المقيمُ بالليل، وفارقَ عمرانَ البلد قبل الفجر فله أن يفطر بلا خلاف.","وهذا الذي يُفهم من الآية الكريمة: ( أَوْ عَلَىٰ سَفَرٍ ) [البقرة: ١٨٤].","ومَنْ غربتْ عليه الشمسُ، فأفطرَ على الأرض، ثم أقلعتْ به الطائرةُ فرأى الشمسَ في السماء، لم يلزمه الإمساكُ لأنه أتمَّ صيامَه.","وأما إذا أقلعتْ به الطائرةُ قبلَ غروب الشمس، وأرادَ إتمامَ صيامَ ذلك اليوم وهو مسافر فلا يُفطر إلا إذا غربت الشمسُ.","ومَنْ سافرَ من بلدٍ إلى بلدٍ وهم متأخّرون يومًا أو يومين في الصوم، وقد أكمل صومَه ثلاثين يومًا، ففي أصح أقوال أهل العلم أنه لا يصوم، لقول النبيّ ﷺ: (( الصوم هكذا وهكذا )) أي تسعًا وعشرين يوماً أو ثلاثين يومًا فقط. وإنما يُفْطِرُ سراً.","وإذا كان المسلمون في بلدٍ فيه النهارُ أربع وعشرون ساعةً، فيصومون بحسب أقربِ البلدان إليهم التي فيها الليل والنهار يتميّزان. والله تعالى أعلم بالصواب."],"en":["This is also one narration from Imam Ahmad. But the majority of the scholars, including Malik, Abu Hanifah, al-Shafiʿi, and one narration from Ahmad, said: whoever does not leave the inhabited area until after dawn does not have the right to break the fast that day, because he is one of those who witnessed the month while resident, so he must fast, since the Prophet ﷺ did not leave Madinah in Ramadan already breaking the fast; rather, he broke it on the road.","As for the resident who travels by night and leaves the inhabited area before dawn, then he may break the fast without disagreement.","This is what is understood from the noble verse: “or on a journey.” [al-Baqarah 2:184]","Whoever the sun sets for while he is on the ground and he breaks his fast, then the airplane takes off and he sees the sun in the sky, he is not required to refrain again, because he has completed his fast.","But if the airplane takes off before sunset, and he wants to complete the fast of that day while traveling, then he must not break the fast until the sun has set.","Whoever travels from one country to another where they are one or two days behind in fasting, and he has already completed thirty days of fasting, then according to the strongest view of the scholars he does not continue fasting, because the Prophet ﷺ said: “The month is like this and like this,” meaning only twenty-nine or thirty days. However, he should break the fast privately.","If Muslims are in a land where the daytime lasts twenty-four hours, then they fast according to the nearest lands to them where night and day are distinct. And Allah knows best what is correct."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":799},{"key":"darimi","label":"الدارميّ","number":1754},{"key":"الامام_احمد","label":"الإمام أحمد","number":27231},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2040}]},{"num":4598,"demo":false,"sanad":"","matn":["عن أبي سعيد، قال: أتى رسول اللّٰه ﷺ على نهر من السماء، والناس صيام في يوم صائف مشاة، ونبي اللّٰه ﷺ على بغلة له، فقال: (( اشربوا أيّها النّاس )). قال: فأبوا. قال: (( إني لست مثلكم، إني أيسركم، إني راكب )) فأبوا. فثنى رسول اللّٰه ﷺ فخذه فنزل فشرب، وشرب الناس، وما كان يريد أن يشرب."],"takhrij":"صحيح: رواه أحمد (١١٤٢٣)، وأبو يعلى (١٢١٤)، وابن خزيمة (١٩٦٦)، وابن حبان (٣٥٥٦، ٣٥٥٠).","grade":"صحيح","chapter_ar":"باب يجوز للمسافر الإفطار بعد أن شرع في الصوم بلا عذر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (11423), Abu Yaʿla (1214), Ibn Khuzaymah (1966), and Ibn Hibban (3550, 3556).","chapter_en":"It is permissible for the traveler to break the fast after having started fasting without a specific excuse","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":17,"content":{"translation":{"en":["Abu Saʿid said: The Messenger of Allah ﷺ came upon a flow of rainwater while the people were fasting on a hot summer day and walking, while the Prophet of Allah ﷺ was on his mule. He said: “Drink, O people.” They refused. He said: “I am not like you; I am in easier circumstances than you, for I am riding.” They still refused. So the Messenger of Allah ﷺ bent his thigh, dismounted, and drank, and the people drank, though he had not intended to drink."]},"intro":{"ar":["قوله: “نهر من السماء” أي ماء المطر."],"en":["His phrase, “a river from the sky,” means rainwater."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":1214},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":1966},{"key":"ibnhibban","label":"ابن حبان","number":3556},{"key":"ahmad","label":"مسند الإمام أحمد","number":11423,"n":11423},{"key":"sh12520","label":"مسند أبي يعلى","number":1214,"n":1212}]},{"num":4599,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: كنّا مع النبيّ ﷺ في السَّفر، فمنّا الصّائم ومنا المفطر، قال: فنزلنا منزلاً في يوم حارّ، أكثرنا ظلاً صاحب الكساء، ومِنّا من يتّقي الشّمس بيده.","قال: فسقط الصُّوّام، وقام المفطرون، فضربوا الأبنية وسقوا الرُّكاب، فقال رسول اللّٰه ﷺ:","(( ذهب المفطرون اليوم بالأجر ))."],"takhrij":"متفق عليه: رواه البخاريّ (٢٨٩٠)، ومسلم (١١١٩). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب استحباب الإفطار في السفر لأجل التَّقَوِّي على القتال وخدمة الرفقاء ونحو ذلك","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2890) and Muslim (1119). The wording is that of Muslim.","chapter_en":"The recommendation to break the fast while traveling in order to gain strength for fighting, serving companions, and similar needs","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Malik said: We were with the Prophet ﷺ on a journey. Some of us were fasting and some of us had broken the fast. We stopped at a place on a hot day. The one with a cloak had the most shade, while some of us shielded themselves from the sun with their hands.","He said: The fasting ones fell down from exhaustion, while the ones who had broken the fast stood up, put up the tents, and watered the riding animals. So the Messenger of Allah ﷺ said:","“Today the ones who broke the fast have taken all the reward.”"]},"intro":{"ar":["وقوله: (( أولئك العصاة، أولئك العصاة )). قال ابن حبان في “صحيحه” (٣١٨/٨): (( إنّما أطلق عليهم هذه اللفظة بتركهم الأمر الذي أمرهم به، وهو الإفطار، لا أنّهم صاروا عصاة بصومهم في السّفر )).","وقال الشافعي: معنى قوله: (( أولئك العصاة )) هذا إذا لم يحتمل قلبُه قبول رخصة الله، فأما من رأى الفطر مباحاً وصام وقوي على ذلك، فهو أعجب إليَّ)). ذكره الترمذي (٧١٠).","قوله: (( مكثور عليه )) أي عنده كثيرون من الناس."],"en":["Regarding his statement, “Those are the disobedient ones,” Ibn Hibban said in his Sahih (8/318): “He only described them with this term because they abandoned the instruction he gave them, which was to break the fast, not because they became sinful merely by fasting while traveling.”","Al-Shafiʿi said: The meaning of his statement, “Those are the disobedient ones,” is when a person’s heart does not accept the concession of Allah. But as for the one who believes that breaking the fast is permissible and yet fasts while having the strength for it, then that is more pleasing to me. This was mentioned by al-Tirmidhi (710).","His phrase, “many were gathered around him,” means that many people were with him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2890},{"key":"muslim","label":"مسلم","number":1119}]},{"num":4600,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: خرج رسول اللّٰه ﷺ من المدينة إلى مكة، فصام حتى بلغ عسفان، ثم دعا بماء، فرفعه إلى يديه يُريه الناس، فأفطر حتى قدم مكة. وذلك في رمضان.","فكان ابن عباس يقول: قد صام رسول اللّه ﷺ وأفطر، فمن شاء صام، ومن شاء أفطر."],"takhrij":"متفق عليه: رواه البخاري (١٩٤٨)، ومسلم (١١١٣).","grade":"متفق عليه","chapter_ar":"باب استحباب الإفطار في السفر لأجل التَّقَوِّي على القتال وخدمة الرفقاء ونحو ذلك","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1948) and Muslim (1113).","chapter_en":"The recommendation to break the fast while traveling in order to gain strength for fighting, serving companions, and similar needs","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ set out from Madinah to Makkah and fasted until he reached ʿUsfan. Then he called for water, raised it in his hands so the people could see it, and broke his fast until he reached Makkah. That was in Ramadan.","So Ibn ʿAbbas used to say: The Messenger of Allah ﷺ both fasted and broke the fast, so whoever wishes may fast, and whoever wishes may break the fast."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1948},{"key":"muslim","label":"مسلم","number":1113}]},{"num":4601,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أنّ رسول اللّٰه ﷺ خرج عام الفتح إلى مكة في رمضان، فصام حتى بلغ كراع الغميم، فصام الناس، ثم دعا بقدح من ماء، فرفعه، حتى نظر الناسُ إليه، ثم شرب، فقيل له بعد ذلك: إنّ بعض الناس قد صام؟ فقال:","(( أولئك العُصاة، أولئك العصاة )).","وزاد في رواية: (( إنّ الناس قد شقَّ عليهم الصيام، وإنّما ينظرون فيما فعلت، فدعا بقدح من ماء بعد العصر ))."],"takhrij":"صحيح: رواه مسلم (١١١٤).","grade":"صحيح","chapter_ar":"باب استحباب الإفطار في السفر لأجل التَّقَوِّي على القتال وخدمة الرفقاء ونحو ذلك","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1114).","chapter_en":"The recommendation to break the fast while traveling in order to gain strength for fighting, serving companions, and similar needs","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Jabir ibn ʿAbdullah reported that the Messenger of Allah ﷺ went out in the year of the Conquest to Makkah in Ramadan, and he fasted until he reached Kuraʿ al-Ghamim. The people also fasted. Then he called for a cup of water and raised it so the people looked at it, then he drank. Later he was told: Some people are still fasting. He said:","“Those are the disobedient ones, those are the disobedient ones.”","And in another narration it adds: “The fasting has become difficult for the people, and they are only waiting to see what you do.” So he called for a cup of water after the afternoon prayer."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1114}]},{"num":4602,"demo":false,"sanad":"","matn":["عن قزعة، قال: أتيت أبا سعيد الخدري رضي اللّٰه عنه وهو مكثور عليه، فلما تفرّق الناسُ عنه، قلتُ: إنّي لا أسألك عمّا يسألك هؤلاء عنه. سألته عن الصّوم في السفر؟ فقال: سافرنا مع رسول اللّه ﷺ إلى مكّة ونحن صيام. قال: فنزلنا منزلاً، فقال رسول اللّٰه ﷺ:","(( إنّكم قد دنوتم من عدوّكم والفطرُ أقوى لكم )).","فكانت رخصة، فمنّا من صام، ومنّا من أفطر. ثم نزلنا منزلا آخر، فقال:","(( إنَّكم مُصَبِّحُوا عدوّكم، والفطرُ أقوى لكم، فأفطروا )).","وكانت عَزْمةً، فأفطرنا. ثم قال: لقد رأيتنا نصوم مع رسول اللّٰه ﷺ بعد ذلك في السّفر."],"takhrij":"صحيح: رواه مسلم (١١٢٠).","grade":"صحيح","chapter_ar":"باب استحباب الإفطار في السفر لأجل التَّقَوِّي على القتال وخدمة الرفقاء ونحو ذلك","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1120).","chapter_en":"The recommendation to break the fast while traveling in order to gain strength for fighting, serving companions, and similar needs","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Qazaʿah said: I came to Abu Saʿid al-Khudri, may Allah be pleased with him, while many people were gathered around him. When the people had left, I said: I am not going to ask you what those people asked you about. I asked him about fasting during travel. He said: We traveled with the Messenger of Allah ﷺ to Makkah while we were fasting. We stopped at a place, and the Messenger of Allah ﷺ said:","“You have drawn near to your enemy, and breaking the fast will make you stronger.”","So it was a concession. Some of us fasted, and some of us broke the fast. Then we stopped at another place, and he said:","“You will meet your enemy in the morning, and breaking the fast will make you stronger, so break the fast.”","And this was a firm instruction, so we broke the fast. Then he said: We later saw ourselves fasting with the Messenger of Allah ﷺ after that while traveling."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1120}]},{"num":4603,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب، قال: غزونا مع رسول اللّٰه ﷺ في رمضان غزوتين: يوم بدر والفتح، فأفطرنا فيهما."],"takhrij":"حسن: رواه الترمذي (٧١٤)، والإمام أحمد (١٤٢).","grade":"حسن","chapter_ar":"باب استحباب الإفطار في السفر لأجل التَّقَوِّي على القتال وخدمة الرفقاء ونحو ذلك","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (714) and Imam Ahmad (142).","chapter_en":"The recommendation to break the fast while traveling in order to gain strength for fighting, serving companions, and similar needs","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: We fought alongside the Messenger of Allah ﷺ during Ramadan in two campaigns: the Day of Badr and the Conquest, and we broke the fast in both of them."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":714},{"key":"الامام_احمد","label":"الإمام أحمد","number":142},{"key":"ahmad","label":"مسند الإمام أحمد","number":142,"n":142}]},{"num":4604,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: أتى النبيّ ﷺ بطعام بمرّ الظهران، فقال لأبي بكر وعمر: (( ادنيا فكلا )). فقالا: إنّا صائمان. فقال: (( ارحلوا لصاحبيكم، واعملوا لصاحبيكم ))."],"takhrij":"صحيح: رواه النسائي (٢٢٦٤)، والإمام أحمد (٨٤٣٦)، وصحّحه ابن خزيمة (٢٠٣١).","grade":"صحيح","chapter_ar":"باب استحباب الفطر في السفر إذا عجز عن خدمة نفسه","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2264), Imam Ahmad (8436), and authenticated by Ibn Khuzaymah (2031).","chapter_en":"The recommendation to break the fast while traveling if one cannot take care of himself","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Abu Hurairah said: Food was brought to the Prophet ﷺ at Marr al-Zahran, and he said to Abu Bakr and ʿUmar: “Come near and eat.” They said: We are fasting. He said: “Then saddle up for your two companions and work for your two companions.”"]},"intro":{"ar":["وقوله: (( ادنيا )) أي قرِّبا أنفسكما إليَّ أو إلى الطعام، وفي بعض نسخ مسند أحمد: (( أذنوا )) أي اقتربا.","وقوله: (( ارحلوا )) أي شدّوا الرحل لهما على البعير."],"en":["His phrase, “Come near,” means: bring yourselves near to me or to the food. In some copies of Musnad Ahmad it appears as “Come close.”","And his phrase, “Saddle up,” means: fasten the saddle for them on the camel."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2264},{"key":"الامام_احمد","label":"الإمام أحمد","number":8436},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2031},{"key":"ahmad","label":"مسند الإمام أحمد","number":8436,"n":8436}]},{"num":4605,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: كنّا مع النبيّ ﷺ في السَّفر، فمنّا الصّائم ومنا المفطر، قال: فنزلنا منزلاً في يوم حارّ، أكثرنا ظلاً صاحب الكساء، ومِنّا من يتّقي الشّمس بيده.","قال: فسقط الصّوّام، وقام المفطرون، فضربوا الأبنية وسقوا الرُّكاب، فقال رسول اللّٰه ﷺ:","(( ذهب المفطرون اليوم بالأجر ))."],"takhrij":"متفق عليه: رواه البخاريّ (٢٨٩٠)، ومسلم (١١١٩) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب المفطر أعظم أجرا من الصائم إذا تولى عملاً","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2890) and Muslim (1119), and the wording is that of Muslim.","chapter_en":"The one who breaks the fast has greater reward than the fasting one when he takes on work","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":20,"content":{"translation":{"en":["Anas ibn Malik said: We were with the Prophet ﷺ on a journey. Some of us were fasting and some were not. We stopped at a place on a hot day. The one with a cloak had the most shade, and some of us shielded ourselves from the sun with the hand.","He said: The fasting ones dropped from exhaustion, and the ones who had broken the fast stood up, set up the shelters, and watered the riding animals. So the Messenger of Allah ﷺ said:","“Today the ones who broke the fast have taken all the reward.”"]},"buhuth":{"ar":["وفي رواية عند مسلم: (( فتحزّم المفطرون وعملوا )) أي شدّوا أوساطهم وعملوا للصائمين."],"en":["In another narration in Muslim: “The ones who had broken the fast tied up their waistcloths and worked,” meaning they prepared themselves and worked for those who were fasting."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2890},{"key":"muslim","label":"مسلم","number":1119}]},{"num":4606,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، قال: كنا نغزو مع رسول اللّٰه ﷺ في رمضان، فمنا الصّائم، ومنا المفطر. فلا يجد الصائم على المفطر، ولا المفطر على الصائم. يرون أنّ من وجد قوّة فصام، فإنّ ذلك حسن، ويرون أن من وجد ضعفاً فأفطر فإنّ ذلك حسن."],"takhrij":"صحيح: رواه مسلم (١١١٦:٩٦).","grade":"صحيح","chapter_ar":"باب الصوم في السفر لمن قوي عليه، والفطر لمن ضعف عنه","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1116 no. 96).","chapter_en":"Fasting during travel for the one able to do it, and breaking the fast for the one weakened by it","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":21,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: We used to go out on military expeditions with the Messenger of Allah ﷺ in Ramadan. Some of us were fasting and some of us had broken the fast. The fasting one did not object to the one who broke the fast, and the one who broke the fast did not object to the fasting one. They held that whoever had strength and fasted, that was good, and whoever felt weakness and broke the fast, that was also good."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1116}]},{"num":4607,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: كان رسولُ اللّٰه ﷺ في سفر، فرأى زحاماً ورجلاً قد ظلّل عليه، فقال: (( ما هذا؟ )). فقالوا: صائم. فقال: (( ليس من البرِّ الصومُ في السّفر ))."],"takhrij":"متفق عليه: رواه البخاري (١٩٤٦)، ومسلم (١١١٥). وزاد مسلم في رواية: (( عليكم برخصة الله الذي رخّص لكم )).","grade":"متفق عليه","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1946) and Muslim (1115). In another narration in Muslim there is the addition: “Hold to the concession of Allah that He has granted you.”","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ was on a journey and saw a crowd around a man who had been shaded. He said: “What is this?” They said: He is fasting. He said: “It is not righteousness to fast while traveling.”"]},"intro":{"ar":["وخلاصة القول في صوم المسافر كما أفتت به اللجنة الدائمة: “يجوز للمسافر سفر قصر أن يُفطر في سفره سواء كان ماشياً أو راكباً، وسواء كان ركوبُه بالسيارة أو الطائرة وغيرهما، وسواء تعب في سفره تعباً لا يتحمل معه الصوم أم لم يتعب، اعتراه جوعٌ أو عطشٌ أم لم يُصِبْه شيءٌ من ذلك؛ لأن الشرع أطلق الرخصة للمسافر سفر قصر في الفطر، وقصر الصلاة ونحوهما من رخص السفر، ولم يقيد ذلك بنوع من المركوب، ولا خشية التعب أو الجوع أو العطش، وقد كان أصحاب رسول اللّٰه ﷺ يسافرون معه في غزوة في شهر رمضان، فمنهم من يصوم، ومنهم من يُفطر، ولم يعب بعضهم على بعض، لكن يتأكد على المسافر الفطرُ في شهر رمضان إذا شقَّ عليه الصومُ؛ لشدة حر، أو وعورة مسلك، أو بعد شقة، وتتابع سير ونحو ذلك”."],"en":["The summary regarding the fasting of the traveler, as stated by the Permanent Committee, is: “It is permissible for a traveler on a journey that allows shortening the prayer to break the fast during that journey, whether he is walking or riding, whether his travel is by car, airplane, or otherwise, whether he becomes extremely tired or not, and whether hunger or thirst affects him or not. This is because the lawgiver gave the concession to the traveler on a journey of shortened prayer to break the fast, shorten the prayer, and other travel concessions, without restricting that to a specific type of transportation or to fear of fatigue, hunger, or thirst. The Companions of the Messenger of Allah ﷺ used to travel with him on expeditions in Ramadan, and some of them fasted while some broke the fast, and they did not criticize one another. However, it is more strongly emphasized for the traveler to break the fast in Ramadan when fasting becomes difficult due to intense heat, rough roads, long distance, continuous travel, and the like.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1946},{"key":"muslim","label":"مسلم","number":1115}]},{"num":4608,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله، أن النبيّ ﷺ سافر في رمضان، فاشتدّ الصوم على رجل من أصحابه، فجعلتْ ناقته تهيم به تحت ظلال الشجر. فأُخبر النبيّ ﷺ فأمره فأفطر، ثم دعا رسول اللّٰه ﷺ بإناء فيه ماء فوضعه على يده، فلما رآه الناس شرب فشربوا."],"takhrij":"حسن: رواه أبو يعلى (١٧٨٠)، وابن حبان (٣٥٦٥).","grade":"حسن","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Yaʿla (1780) and Ibn Hibban (3565).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Jabir ibn ʿAbdullah reported that the Prophet ﷺ traveled in Ramadan, and fasting became very hard on one of his Companions. His she-camel wandered with him beneath the shade of the trees. The Prophet ﷺ was informed, so he ordered him to break the fast. Then the Messenger of Allah ﷺ called for a vessel containing water, placed it in his hand, and when the people saw him drink, they also drank."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":1780},{"key":"sh12520","label":"مسند أبي يعلى","number":1780,"n":1779},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5422,"n":5418}]},{"num":4609,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: كُنَّا مَعَ النَّبِيِّ ﷺ فِي غَزْوَةٍ غَزاها، وَذَلِكَ فِي رَمَضَانَ، فَصَامَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ ﷺ فَضَعُفَ ضَعْفًا شَدِيدًا، وَكَادَ الْعَطَشُ أَنْ يَقْتُلَهُ، وَجَعَلَتْ نَاقَتُهُ تَدْخُلُ تَحْتَ العِضَاهِ، فَأُخْبِرَ بِهِ النَّبِيُّ ﷺ فَقَالَ: (( ائتوني به ))، فَأُتِيَ بِهِ، فَقَالَ: (( ألستَ في سبيلِ الله ومع رسولِ الله؟ أفطرْ ))، فَأَفْطَرَ."],"takhrij":"حسن: رواه أحمد (١٤٥٢٩)، وأبو يعلى (٢٢٥٢).","grade":"حسن","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (14529) and Abu Yaʿla (2252).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: We were with the Prophet ﷺ on an expedition during Ramadan. One of the Prophet’s Companions fasted, then became extremely weak, and thirst nearly killed him. His she-camel kept going under the thorny trees. The Prophet ﷺ was informed about him and said: “Bring him to me.” He was brought, and the Prophet ﷺ said: “Are you not in the path of Allah and with the Messenger of Allah? Break your fast.” So he broke the fast."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":2252},{"key":"ahmad","label":"مسند الإمام أحمد","number":14529,"n":14529},{"key":"sh12520","label":"مسند أبي يعلى","number":2252,"n":2255}]},{"num":4610,"demo":false,"sanad":"","matn":["عن كعب بن عاصم الأشعريّ المخزومي، قال: قال رسول اللّٰه ﷺ: (( ليس من البرّ الصِّيام في السّفر ))."],"takhrij":"صحيح: رواه النسائي (٢٢٥٥)، وابن ماجه (١٦٦٤)، والإمام أحمد (٢٣٦٨١، ٢٣٦٨٠، ٢٣٦٧٩).","grade":"صحيح","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2255), Ibn Majah (1664), and Imam Ahmad (23679, 23680, 23681).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Kaʿb ibn ʿAsim al-Ashʿari al-Makhzumi said: The Messenger of Allah ﷺ said: “It is not righteousness to fast while traveling.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2255},{"key":"ibnmajah","label":"ابن ماجه","number":1664},{"key":"الامام_احمد","label":"الإمام أحمد","number":23681},{"key":"ahmad","label":"مسند الإمام أحمد","number":23681,"n":23681}]},{"num":4611,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عمر، قال: قال رسول اللّٰه ﷺ: (( ليس من البرّ الصيام في السّفر ))."],"takhrij":"صحيح: رواه ابن ماجه (١٦٦٥)، وصححه ابن حبان (٣٥٤٨)، والطحاوي (٣١٣٦).","grade":"صحيح","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (1665), authenticated by Ibn Hibban (3548), and al-Tahawi (3136).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ said: “It is not righteousness to fast while traveling.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1665},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":3548},{"key":"الطحاوی","label":"الطحاوي","number":3136},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4189,"n":4185}]},{"num":4612,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عمرو، قال: سار رسول اللّٰه ﷺ فنزل بأصحابه، وإذا ناس قد جعلوا فريشاً على صاحبهم، وهو صائم، فمرَّ به رسول اللّٰه ﷺ فقال: (( ما شأن صاحبكم؟ أوجع؟ )). قالوا: لا يا رسول اللّه، ولكنه صائم. وذلك في يوم حرور. فقال رسول اللّٰه ﷺ: (( لا برَّ أن يُصام في سفر ))."],"takhrij":"حسن: رواه الطبراني في “الكبير” (١٣/١٤، ١٠٩).","grade":"حسن","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Kabir (13/14, 109).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ was traveling and stopped among his Companions. Some people had spread a covering over one of them while he was fasting. The Messenger of Allah ﷺ passed by him and said: “What is the matter with your companion? Is he ill?” They said: No, O Messenger of Allah, but he is fasting. That was on an intensely hot day. So the Messenger of Allah ﷺ said: “It is not righteousness to fast on a journey.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في “الكبير”","number":13}]},{"num":4613,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، أنّ رسول اللّٰه ﷺ قال: (( ليس من البر الصيام في السفر ))."],"takhrij":"صحيح: رواه البزار - كشف الأستار (٩٨٥)، والطبراني في الكبير (١١/١٨٧).","grade":"صحيح","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bazzar in Kashf al-Astar (985) and al-Tabarani in al-Kabir (11/187).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that the Messenger of Allah ﷺ said: “It is not righteousness to fast while traveling.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":985},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":11},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":985,"n":986}]},{"num":4614,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قال رسول اللّٰه ﷺ: (( إنّ اللّٰه يحبُّ أن تُؤتى رُخصه كما يحبُّ أن تُؤتى عزائمُه ))."],"takhrij":"حسن: رواه الطبراني في الكبير (١١/٣٢٣)، والبزار - كشف الأستار (٩٩٠)، وصححه ابن حبان (٣٥٤).","grade":"حسن","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Kabir (11/323), al-Bazzar in Kashf al-Astar (990), and authenticated by Ibn Hibban (354).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ said: “Allah loves that His concessions be taken just as He loves that His firm commands be carried out.”"]},"buhuth":{"ar":["وكان ابن عباس يقول: (( الإفطار في السّفر عزيمة )). رواه البزار - كشف الأستار (٩٨٦)."],"en":["And Ibn ʿAbbas used to say: “Breaking the fast during travel is a firm ruling.” Narrated by al-Bazzar in Kashf al-Astar (986)."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":11},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":990},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":354},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":989,"n":990},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4769,"n":4765}]},{"num":4615,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: قال رسول اللّٰه ﷺ: (( إنّ اللّٰه يحبُّ أن تُؤتى رُخصه كما يكره أن تُؤتى معصيتُه ))."],"takhrij":"حسن: رواه الإمام أحمد (٥٨٧٣)، والبزار - كشف الأستار (٩٨٨)، وصححه ابن خزيمة (١٩٥٠).","grade":"حسن","chapter_ar":"باب الإفطار أفضل لمن شقّ عليه الصّوم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (5873), al-Bazzar in Kashf al-Astar (988), and authenticated by Ibn Khuzaymah (1950).","chapter_en":"Breaking the fast is better for the one whom fasting is difficult for","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":22,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Allah loves that His concessions be acted upon just as He hates that His disobedience be committed.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":5873},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":988},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":1950},{"key":"ahmad","label":"مسند الإمام أحمد","number":5873,"n":5873},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":988,"n":989}]},{"num":4616,"demo":false,"sanad":"","matn":["عن أنس بن مالك القشيري الكعبيّ، أنه أتى النبيّ ﷺ بالمدينة وهو يتغدّى. فقال له النبيّ ﷺ: (( هلمَّ إلى الغداء )). فقال: إنّي صائم. فقال له النبيُّ ﷺ: (( إنّ اللّٰه عزّ وجلّ وضع للمسافر الصوم وشطر الصلاة، وعن الحبلى والمرضع ))."],"takhrij":"حسن: رواه النسائي (٢٣١٥)، والبيهقي (٢٣١/٤).","grade":"حسن","chapter_ar":"باب ما جاء في إفطار الحامل والمرضع","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2315) and al-Bayhaqi (4/231).","chapter_en":"What has been reported regarding the pregnant and nursing woman breaking the fast","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik al-Qushayri al-Kaʿbi reported that he came to the Prophet ﷺ in Madinah while he was eating lunch. The Prophet ﷺ said to him: “Come to the meal.” He said: I am fasting. The Prophet ﷺ said to him: “Allah, Mighty and Majestic, has lifted fasting and half of the prayer from the traveler, and also from the pregnant woman and the nursing woman.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2315},{"key":"البیہقی","label":"البيهقي","number":231}]},{"num":4617,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر، قالت: أفطرنا على عهد النبيّ ﷺ يوم غيم، ثم طلعت الشمس. قيل لهشام: فأُمروا بالقضاء؟ قال: بدٌّ من قضاء. وقال معمر: سمعت هشاماً يقول: لا أدري أقضوا أم لا."],"takhrij":"صحيح: رواه البخاريّ (١٩٥٩).","grade":"صحيح","chapter_ar":"باب إذا أفطر الصائم ظانًا غروب الشمس ثم طلعت الشمس، هل يجب عليه قضاء ذلك اليوم أو لا؟","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1959).","chapter_en":"If a fasting person breaks the fast thinking the sun has set, then the sun appears, must he make up that day or not?","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":24,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: We broke our fast during the time of the Prophet ﷺ on a cloudy day, then the sun appeared. Hisham was asked: Were they ordered to make it up? He said: There must be a make-up. But Maʿmar said: I heard Hisham say: I do not know whether they made it up or not."]},"intro":{"ar":["قول هشام: (( بدٌّ من قضاء )) هذا اجتهاد منه، بدليل قوله: (( لا أدري أقضوا أم لا؟ ))."],"en":["Hisham’s statement, “There must be a make-up,” was his own legal reasoning, as shown by his saying, “I do not know whether they made it up or not.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1959}]},{"num":4618,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: قال النبيُّ ﷺ: (( أليس إذا حاضتْ لم تصلِّ ولم تصم، فذلك نقصان دينها ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٩٥١)، ومسلم (٨٠).","grade":"متفق عليه","chapter_ar":"باب الحائض يجب عليها الفطرُ والقضاءُ معًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1951) and Muslim (80).","chapter_en":"The menstruating woman must both break the fast and make it up","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":25,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Prophet ﷺ said: “Is it not the case that when she menstruates she neither prays nor fasts? That is part of the deficiency in her religion.”"]},"intro":{"ar":["اتفق أهل العلم على أن الحائض والنفساء يجب عليهما الفطرُ، وإذا صامتا لا يصحّ صومُهما، وعليهما قضاء ما فاتهما.","مسائل النساء في رمضان:","إذا انقطع الدمُ عن المرأة في آخر الليل من رمضان، يصحّ لها أن تتسحّر، وتنوي الصيام، وكذلك من انقطع دمُها وقتَ طلوع الفجر أو قبله بقليل، صحَّ صومُها، ولو لم تغتسلْ حتى أصبح الصبح.","إلا إذا طهرت المرأة في أثناء النهار من الحيض أو النفاس فإنها تُمسك بقية ذلك اليوم لحرمة الشهر، وتقضي ذلك اليوم.","وسُئل سماحة الشيخ ابن باز عن المرأة التي عادتها الشهرية تتراوح ما بين سبعة إلى ثمانية أيام، وفي بعض الأحيان في اليوم السابع لا ترى دماً، ولا ترى طهراً، فأجاب: لا تعجلي حتى ترى القَصّةَ البيضاء التي يعرفها النساء، وهي علامة الطهر، فتوقف الدم ليس هو الطهر، وإنما ذلك برؤية علامة الطهر، وانقضاء المدة المعتادة.","وسُئلت اللجنة الدائمة عن المرأة الحامل، إذا رأت الدمَ قبل الولادة بأيام، ولم تر علامة على قرب الوضع بالمخاض، وهو الطلق، فليس بدم حيض ولا نفاس، بل دمُ فساد على الصحيح، وعلى ذلك لا تترك العبادات، بل تصوم وتُصلّي، وإذا رأت الدم مع أمارات قرب وضع الحمل من الطلق ونحوه، فهو دم نفاس، تدع من أجله الصلاة والصوم، ثم إذا طهرت منه بعد الولادة، قضت الصوم دون الصلاة.","وأما استعمال الحبوب في رمضان لمنع الدورة الشهرية، فالمرأة تختلف عن المرأة، فإذا استعملت، ولم تجد ضرراً، وأرادت اغتنام الفرصة من فضيلة شهر رمضان مثل قراءة القرآن، وقيام ليل رمضان، وأداء العمرة وغيرها، فلا بأس بذلك، بخلاف المرأة التي تجد ضرراً وحرجاً من استعمال الحبوب، فعليها أن تتجنب استعمالها، وترضى بقدر اللّٰه وقضائه، فإن اللّٰه كتب هذا على بنات آدم لحكمة بالغة.","وأما استعمال الكحل والقطرة في العين، فقال كثيرٌ من أهل العلم إنه يُؤثّر على الصوم، لأنه يتسرّب إلى الحلق، وكلُّ شيءٍ يتسرّب إلى الحلق من أي منفذ لا يجوز استعماله."],"en":["The scholars are agreed that the menstruating woman and the postpartum woman must break the fast, and if they fast, their fasting is not valid, and they must make up what they missed.","Issues related to women in Ramadan:","If a woman’s bleeding stops at the end of the night in Ramadan, it is valid for her to take the pre-dawn meal and intend the fast. Likewise, if her bleeding stops right at dawn or shortly before it, her fast is valid, even if she does not bathe until morning.","But if a woman becomes pure during the daytime from menstruation or postpartum bleeding, then she refrains for the rest of that day out of respect for the month, and she makes up that day later.","Shaykh Ibn Baz was asked about a woman whose monthly cycle ranges from seven to eight days, and sometimes on the seventh day she sees no blood but also does not see the clear sign of purity. He replied: Do not be hasty until you see the white discharge known to women, which is the sign of purity. The stopping of blood alone is not purity; rather, purity is known by seeing its sign and the end of the usual period.","The Permanent Committee was asked about a pregnant woman who sees blood some days before childbirth, without labor pains or signs of impending delivery. This is not menstrual blood or postpartum blood; rather, according to the sounder view it is irregular bleeding. Therefore she should not leave acts of worship, but should fast and pray. However, if she sees blood together with signs of imminent delivery, such as labor pains and the like, then it is postpartum blood, and she leaves prayer and fasting because of it. When she becomes pure after childbirth, she makes up the fasting but not the prayer.","As for using pills in Ramadan to prevent the monthly cycle, women differ. If a woman uses them and suffers no harm, and wants to make use of the virtue of Ramadan such as reciting the Qur’an, praying at night, performing ʿumrah, and similar acts, then there is no harm in that. But if another woman is harmed or placed in hardship by using such pills, she should avoid them and be content with Allah’s decree, for Allah has written this for the daughters of Adam with profound wisdom.","As for using kohl and eye drops, many scholars held that this affects the fast because it reaches the throat, and anything that reaches the throat from any opening should not be used."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1951},{"key":"muslim","label":"مسلم","number":80}]},{"num":4619,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، عن رسول اللّٰه ﷺ أنه قال: (( تمكث الليالي ما تُصلي، وتفطر في رمضان، فهذا نقصان الدين ))."],"takhrij":"صحيح: رواه مسلم (٧٩).","grade":"صحيح","chapter_ar":"باب الحائض يجب عليها الفطرُ والقضاءُ معًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (79).","chapter_en":"The menstruating woman must both break the fast and make it up","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":25,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar reported that the Messenger of Allah ﷺ said: “She remains for nights without praying, and she breaks the fast in Ramadan; this is the deficiency in religion.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":79}]},{"num":4620,"demo":false,"sanad":"","matn":["عن معاذة، قالت: سألت عائشة، فقلت: ما بالُ الحائض تقضي الصومَ ولا تقضي الصلاة؟ فقالت: أحرورية أنتِ؟ قلت: لستُ بحرورية، ولكني أسأل، قالت: يصيبنا ذلك فنؤمر بقضاء الصوم، ولا نؤمر بقضاء الصلاة."],"takhrij":"متفق عليه: رواه البخاري (٣٢١)، ومسلم (٣٣٥) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الحائض يجب عليها الفطرُ والقضاءُ معًا","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (321) and Muslim (335), and the wording is that of Muslim.","chapter_en":"The menstruating woman must both break the fast and make it up","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":25,"content":{"translation":{"en":["Muʿadhah said: I asked ʿA’ishah and said: Why does a menstruating woman make up the fast but not the prayer? She said: Are you a Haruriyyah? I said: I am not a Haruriyyah, but I am only asking. She said: That used to happen to us, and we were commanded to make up the fast, but we were not commanded to make up the prayer."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":321},{"key":"muslim","label":"مسلم","number":335}]},{"num":4621,"demo":false,"sanad":"","matn":["عن عائشة، قالت: إن كان ليكون عليَّ الصِّيامُ من رمضان، فما أستطيع أصومُه حتى يأتي شعبان."],"takhrij":"متفق عليه: رواه مالك (٥٤)، والبخاريّ (١٩٥٠)، ومسلم (١١٤٦).","grade":"متفق عليه","chapter_ar":"باب تأخير قضاء رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (54), al-Bukhari (1950), and Muslim (1146).","chapter_en":"Delaying the make-up of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":26,"content":{"translation":{"en":["ʿA’ishah said: There would be days of fasting from Ramadan due upon me, and I would not be able to fast them until Shaʿban came."]},"intro":{"ar":["قال تعالى: ( وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ ) [البقرة: ١٨٥]."],"en":["Allah the Exalted said: “And whoever is ill or on a journey, then an equal number of other days.” [al-Baqarah 2:185]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":54},{"key":"bukhari","label":"البخاريّ","number":1950},{"key":"muslim","label":"مسلم","number":1146}]},{"num":4622,"demo":false,"sanad":"","matn":["عن عائشة، قالت: ما كنتُ أقضي ما يكون عليَّ من رمضان إلا في شعبان، حتى توفي رسول اللّٰه ﷺ."],"takhrij":"حسن: رواه الترمذي (٧٨٣)، والإمام أحمد (٢٤٩٢٨)، وابن خزيمة (٢٠٥٠).","grade":"حسن","chapter_ar":"باب تأخير قضاء رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (783), Imam Ahmad (24928), and Ibn Khuzaymah (2050).","chapter_en":"Delaying the make-up of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":26,"content":{"translation":{"en":["ʿA’ishah said: I would not make up what I owed from Ramadan except in Shaʿban, until the Messenger of Allah ﷺ passed away."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":783},{"key":"الامام_احمد","label":"الإمام أحمد","number":24928},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2050},{"key":"ahmad","label":"مسند الإمام أحمد","number":24928,"n":24928}]},{"num":4623,"demo":false,"sanad":"","matn":["عن عائشة، أنّ رسول اللّٰه ﷺ قال: (( من مات وعليه صيام، صام عنه وليُّه ))."],"takhrij":"متفق عليه: رواه البخاري (١٩٥٢)، ومسلم (١١٤٧).","grade":"متفق عليه","chapter_ar":"باب قضاء الصيام عن الميت","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1952) and Muslim (1147).","chapter_en":"Making up fasting on behalf of the deceased","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":27,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ said: “Whoever dies while owing fasting, his guardian should fast on his behalf.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1952},{"key":"muslim","label":"مسلم","number":1147}]},{"num":4624,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: جاء رجلٌ إلى النبيّ ﷺ، فقال: يا رسول الله، إنَّ أمي ماتت وعليها صومُ شهر، أفاقضيه عنها؟ فقال: (( لو كان على أمّك دَيْن أكنتَ قاضيه عنها؟ )) قال: نعم.","قال: (( فدَيْن اللّٰه أحقُّ أن يُقضى )).","قال سليمان: فقال الحكم، وسلمة بن كهيل جميعاً - ونحن جلوسُ حين حدَّث مسلمٌ بهذا الحديث - فقالا: سمعنا مجاهداً يذكرُ هذا عن ابن عباس."],"takhrij":"متفق عليه: رواه البخاريّ (١٩٥٣)، ومسلم (١٥٥:١١٤٨).","grade":"متفق عليه","chapter_ar":"باب قضاء الصيام عن الميت","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1953) and Muslim (1148 no. 155).","chapter_en":"Making up fasting on behalf of the deceased","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":27,"content":{"translation":{"en":["Ibn ʿAbbas said: A man came to the Prophet ﷺ and said: O Messenger of Allah, my mother died owing a month of fasting. Should I make it up on her behalf? He said: “If your mother had a debt, would you pay it off for her?” He said: Yes.","He said: “Then the debt owed to Allah has more right to be fulfilled.”","Sulayman said: Al-Hakam and Salamah ibn Kuhayl both said — while we were sitting when Muslim narrated this hadith —: We heard Mujahid narrate this from Ibn ʿAbbas."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1953},{"key":"muslim","label":"مسلم","number":155}]},{"num":4625,"demo":false,"sanad":"","matn":["عن عبدالله بن بريدة، عن أبيه، قال: بينا أنا جالسٌ عند رسول اللّٰه ﷺ إذ أتته امرأة، فقالت: إني تصدّقت على أمّي بجاريةٍ، وإنّها ماتتْ. قال: فقال: (( وجب أجْرُك، وردَّها عليكِ الميراث )).","قالت: يا رسول الله، إنه كان عليها صوم شهر. أفأصومُ عنها؟ قال: (( صومي عنها )).","قالت: إنّها لم تحجَّ قطّ، أفأحجُّ عنها؟ قال: (( حُجِّي عنها )).","وفي رواية: (( صوم شهرين ))."],"takhrij":"صحيح: رواه مسلم (١١٤٩).","grade":"صحيح","chapter_ar":"باب قضاء الصيام عن الميت","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1149).","chapter_en":"Making up fasting on behalf of the deceased","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":27,"content":{"translation":{"en":["ʿAbdullah ibn Buraydah, from his father, said: While I was sitting with the Messenger of Allah ﷺ, a woman came and said: I gave a slave-girl in charity to my mother, and now she has died. He said: “Your reward has been confirmed, and inheritance has returned her to you.”","She said: O Messenger of Allah, she owed a month of fasting. Should I fast on her behalf? He said: “Fast on her behalf.”","She said: She never performed pilgrimage. Should I perform pilgrimage on her behalf? He said: “Perform pilgrimage on her behalf.”","In another narration: “Two months of fasting.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1149}]},{"num":4626,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول اللٰه ﷺ: (( قال الله: كلُّ عمل ابن آدم له إلا الصيام، فإنّه لي وأنا أجزي به، والصيام جُنّة، وإذا كان يوم صوم أحدكم فلا يرفث ولا يصخب، فإن سبَّه أحدٌ أو قاتله فليقل: إنّي امرؤٌ صائم، والذي نفس محمد بيده لخلوف فم الصائم أطيب عند الله من ريح المسك، للصائم فرحتان يفرحهما: إذا أفطر فرح، وإذا لقي ربّه فرح بصومه ))."],"takhrij":"متفق عليه: رواه البخاري (١٩٠٤)، ومسلم (١٦٣:١١٥١)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الترهيب من الغيبة والرّفث وقول الزّور للصّائم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1904) and Muslim (1151 no. 163), and the wording is that of al-Bukhari.","chapter_en":"Warning the fasting person against backbiting, indecent speech, and falsehood","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":28,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Allah said: Every deed of the son of Adam is for him except fasting; it is for Me, and I reward for it. Fasting is a shield. So when it is the day of one of you fasting, he should not speak indecently or raise his voice in argument. If someone insults him or fights him, let him say: ‘I am a fasting person.’ By the One in whose hand is the soul of Muhammad, the smell coming from the mouth of the fasting person is more pleasant to Allah than the fragrance of musk. The fasting person has two joys: when he breaks his fast, he rejoices, and when he meets his Lord, he rejoices in his fasting.”"]},"intro":{"ar":["وقوله: (( فليقل: إني صائم )) أي نطقاً وجهراً، ولا يخوض معه حتى لا يحبط أجر صومه.","قوله: (( قول الزور )) أي الكذب.","(( والجهل )) أي السّفه.","(( والعمل به )) أي بمقتضاه."],"en":["His saying, “Let him say: I am fasting,” means that he says it aloud and clearly, and does not get drawn into arguing with the other person, so that the reward of his fast is not ruined.","His phrase, “false speech,” means lying.","“And ignorant behavior,” means foolish and reckless conduct.","“Acting upon it,” means acting according to that falsehood."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1904},{"key":"muslim","label":"مسلم","number":163}]},{"num":4627,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ النبيّ ﷺ قال: (( الصيام جُنَّة، فإذا كان أحدكم صائماً فلا يرفث ولا يجهل، فإن امرؤ قاتله أو شاتمه فليقل: إنّي صائم، إني صائم ))."],"takhrij":"متفق عليه: رواه مالك (٥٩)، والبخاري (١٨٩٤)، ومسلم (١١٥١).","grade":"متفق عليه","chapter_ar":"باب الترهيب من الغيبة والرّفث وقول الزّور للصّائم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (59), al-Bukhari (1894), and Muslim (1151).","chapter_en":"Warning the fasting person against backbiting, indecent speech, and falsehood","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":28,"content":{"translation":{"en":["Abu Hurairah reported that the Prophet ﷺ said: “Fasting is a shield. So when one of you is fasting, he should not speak indecently or behave ignorantly. If someone fights him or insults him, let him say: ‘I am fasting, I am fasting.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":59},{"key":"bukhari","label":"البخاري","number":1894},{"key":"muslim","label":"مسلم","number":1151}]},{"num":4628,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبيّ ﷺ قال: (( لا تسابَّ وأنتَ صائم، وإن سابّك أحدٌ فقل: إنّي صائم، وإنْ كنتَ قائماً فاجلسْ ))."],"takhrij":"حسن: رواه ابن خزيمة (١٩٩٤)، وعنه ابن حبان (٣٤٨٣)، والإمام أحمد (٩٥٣٢).","grade":"حسن","chapter_ar":"باب الترهيب من الغيبة والرّفث وقول الزّور للصّائم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Khuzaymah (1994), by Ibn Hibban from him (3483), and Imam Ahmad (9532).","chapter_en":"Warning the fasting person against backbiting, indecent speech, and falsehood","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":28,"content":{"translation":{"en":["Abu Hurairah reported that the Prophet ﷺ said: “Do not trade insults while you are fasting. If someone insults you, then say: ‘I am fasting,’ and if you are standing, then sit down.”"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":1994},{"key":"عنہ_ابن_حبان","label":"عنه ابن حبان","number":3483},{"key":"الامام_احمد","label":"الإمام أحمد","number":9532},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1169,"n":1166},{"key":"ahmad","label":"مسند الإمام أحمد","number":9532,"n":9532}]},{"num":4629,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول اللّٰه ﷺ: (( من لم يدع قول الزّور والعملَ به، فليس لله حاجة في أن يدع طعامه وشرابه )).","وزاد في رواية: (( والجهل ))."],"takhrij":"صحيح: رواه البخاري (١٩٠٣) و(٦٠٥٧).","grade":"صحيح","chapter_ar":"باب الترهيب من الغيبة والرّفث وقول الزّور للصّائم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1903) and (6057).","chapter_en":"Warning the fasting person against backbiting, indecent speech, and falsehood","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":28,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever does not abandon false speech and acting upon it, Allah has no need for him to leave his food and drink.”","In another narration there is the addition: “and ignorant behavior.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1903},{"key":"و","label":"و","number":6057}]},{"num":4630,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول اللّٰه ﷺ: (( ربّ صائم ليس له من صيامه إلا الجوع، وربّ قائم ليس له من قيامه إلا السّهر ))."],"takhrij":"حسن: رواه ابن ماجه (١٦٩٠)، والإمام أحمد (٩٦٨٥)، وابن حبان (٣٤٨١)، وأبو يعلى (٦٥٥١).","grade":"حسن","chapter_ar":"باب الترهيب من الغيبة والرّفث وقول الزّور للصّائم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (1690), Imam Ahmad (9685), Ibn Hibban (3481), and Abu Yaʿla (6551).","chapter_en":"Warning the fasting person against backbiting, indecent speech, and falsehood","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":28,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “There may be a fasting person who gets nothing from his fasting except hunger, and there may be one standing in prayer at night who gets nothing from his standing except sleeplessness.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1690},{"key":"الامام_احمد","label":"الإمام أحمد","number":9685},{"key":"ibnhibban","label":"ابن حبان","number":3481},{"key":"ابو_یعلی","label":"أبو يعلى","number":6551},{"key":"ahmad","label":"مسند الإمام أحمد","number":9685,"n":9685}]},{"num":4631,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول اللّٰه ﷺ: (( ليس الصيام من الأكل والشرب، إنما الصيام من اللغو والرفث. فإن سابّك أحدٌ أو جهل عليك، فلتقل: إني صائم، إني صائم ))."],"takhrij":"صحيح: رواه ابن خزيمة (١٩٩٦)، وابن حبان (٣٤٧٩)، والحاكم (٤٣١-٤٣٠/١).","grade":"صحيح","chapter_ar":"باب الترهيب من الغيبة والرّفث وقول الزّور للصّائم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Khuzaymah (1996), Ibn Hibban (3479), and al-Hakim (1/430–431).","chapter_en":"Warning the fasting person against backbiting, indecent speech, and falsehood","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":28,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Fasting is not merely from food and drink. Rather, fasting is from idle talk and indecency. If someone insults you or behaves foolishly toward you, then say: ‘I am fasting, I am fasting.’”"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":1996},{"key":"ibnhibban","label":"ابن حبان","number":3479},{"key":"hakim","label":"المستدرك على الصحيحين","number":1570,"n":1559}]},{"num":4632,"demo":false,"sanad":"","matn":["عن المقدام بن معد يكرب الكندي قال: سمعت رسول اللّٰه ﷺ يقول: (( ما ملأ ابن آدم وعاءً شراً من بطنٍ، حسب ابن آدم أكلات يُقِمن صُلبه، فإن كان لا محالة، فثلث لطعامٍ، وثلث لشرابٍ، وثلث لنَفَسه ))."],"takhrij":"صحيح: رواه الترمذي (٢٣٨٠)، وأحمد (١٧١٨٦)، وصحّحه ابن حبان (٥٢٣٦)، والحاكم (٣٣١/٤).","grade":"صحيح","chapter_ar":"باب كراهية الإكثار من الطعام في رمضان وغيره","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (2380), Ahmad (17186), and authenticated by Ibn Hibban (5236) and al-Hakim (4/331).","chapter_en":"The dislike of excessive eating in Ramadan and otherwise","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":29,"content":{"translation":{"en":["Al-Miqdam ibn Maʿdi Karib al-Kindi said: I heard the Messenger of Allah ﷺ say: “The son of Adam fills no vessel worse than his stomach. A few bites that keep his back straight are enough for the son of Adam. But if he must do more, then a third for food, a third for drink, and a third for his breath.”"]},"intro":{"ar":["وفيه تحذير من كثرة الأكل عموما، وفي ليالي رمضان خصوصا، لأنها للعبادة وقراءة القرآن، لقول النبيّ ﷺ: (( من قام رمضان إيمانا واحتسابا غفر له ما تقدم من ذنبه ))، ولكنّ الناس أحدثوا أنواعا من الطعام لم تكن معروفة من قبل، وتفنّنوا في إحضار الأطباق على حساب العبادة وقراءة القرآن."],"en":["This contains a warning against overeating in general, and especially during the nights of Ramadan, because those nights are meant for worship and recitation of the Qur’an, due to the saying of the Prophet ﷺ: “Whoever stands in prayer in Ramadan with faith and seeking reward will be forgiven for his previous sins.” Yet people have introduced many kinds of food that were not known before, and they have become creative in preparing dishes at the expense of worship and recitation of the Qur’an."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2380},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5236},{"key":"hakim","label":"الحاكم","number":331},{"key":"ahmad","label":"مسند الإمام أحمد","number":17186,"n":17186}]},{"num":4633,"demo":false,"sanad":"","matn":["عن أبي بكر بن عبدالرحمن بن الحارث بن هشام، عن بعض أصحاب رسول اللّٰه ﷺ، أنّ رسول اللّٰه ﷺ أمر الناس في سفره عام الفتح بالفطر، وقال: (( تقوّوا لعدوّكم )) وصام رسول اللّٰه ﷺ.","قال أبو بكر: قال الذي حدّثني: لقد رأيتُ رسول اللّٰه ﷺ بالعَرْج يصُبُّ الماء على رأسه من العطش أو من الحر. ثم قيل لرسول اللّٰه ﷺ: يا رسول الله، إنّ طائفةً من الناس قد صاموا حين صُمتَ. قال: فلما كان رسول اللّٰه ﷺ بالكَديد دعا بقَدَح فشرب، فأفطر النّاسُ."],"takhrij":"صحيح: رواه مالك (٢٢)، وأبو داود (٢٣٦٥)، والنسائي في الكبرى (٣٠١٧)، وأحمد (١٥٩٠٣).","grade":"صحيح","chapter_ar":"باب الصائم يصبّ الماء على رأسه من الحرّ والعطش","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Malik (22), Abu Dawud (2365), al-Nasa’i in al-Kubra (3017), and Ahmad (15903).","chapter_en":"The fasting person pouring water over his head because of heat and thirst","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":31,"content":{"translation":{"en":["Abu Bakr ibn ʿAbd al-Rahman ibn al-Harith ibn Hisham narrated from some of the Companions of the Messenger of Allah ﷺ that the Messenger of Allah ﷺ ordered the people during his journey in the year of the Conquest to break the fast, and he said: “Strengthen yourselves against your enemy.” Yet the Messenger of Allah ﷺ fasted.","Abu Bakr said: The one who narrated to me said: I certainly saw the Messenger of Allah ﷺ at al-ʿArj pouring water over his head because of thirst or because of heat. Then it was said to the Messenger of Allah ﷺ: O Messenger of Allah, a group of people have kept fasting because you fasted. So when the Messenger of Allah ﷺ reached al-Kadid, he called for a cup and drank, and the people broke their fast."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":22},{"key":"abudawud","label":"أبو داود","number":2365},{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":3017},{"key":"ahmad","label":"مسند الإمام أحمد","number":15903,"n":15903}]},{"num":4634,"demo":false,"sanad":"","matn":["عن لقيط بن صبرة، قال: قلت: يا رسول الله، أخبرني عن الوضوء؟ قال: (( أسبغ الوضوء وخلِّل الأصابع، وبالغ في الاستنشاق إلا أن تكون صائماً ))."],"takhrij":"صحيح: رواه أبو داود (٢٣٦٦)، والترمذي (٧٨٨)، والنسائي (٨٧)، وابن ماجه (٤٠٧). قال الترمذي: (( حسن صحيح )).","grade":"صحيح","chapter_ar":"باب كراهية المبالغة في الاستنشاق للصائم","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2366), al-Tirmidhi (788), al-Nasa’i (87), and Ibn Majah (407). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The dislike of exaggerating in sniffing water into the nose for the fasting person","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما يباح للصائم وما لا يباح له","group_en":"Chapters on what is permissible for the fasting person and what is not permissible","part_no":15,"group_no":4,"chapter_no":32,"content":{"translation":{"en":["Laqit ibn Sabirah said: I said: O Messenger of Allah, tell me about ablution. He said: “Perform ablution thoroughly, run between the fingers, and exaggerate in sniffing water into the nose, unless you are fasting.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2366},{"key":"tirmidhi","label":"الترمذي","number":788},{"key":"nasai","label":"النسائي","number":87},{"key":"ibnmajah","label":"ابن ماجه","number":407}]},{"num":4635,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: إنّ رسول اللّٰه ﷺ قال: (( من قام رمضان إيماناً واحتساباً غفر له ما تقدّم من ذنبه ))."],"takhrij":"متفق عليه: رواه البخاريُّ (٣٧)، ومسلم (٧٥٩).","grade":"متفق عليه","chapter_ar":"باب الترغيب في قيام الليل في رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (37) and Muslim (759).","chapter_en":"Encouragement for standing in prayer at night in Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever stands in prayer during Ramadan with faith and seeking reward will be forgiven for his previous sins.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريُّ","number":37},{"key":"muslim","label":"مسلم","number":759}]},{"num":4636,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول اللّٰه ﷺ: (( من صام رمضان إيماناً واحتساباً غفر له ما تقدم من ذنبه، ومن قام ليلة القدر إيماناً واحتساباً غفر له ما تقدم من ذنبه ))."],"takhrij":"متفق عليه: رواه البخاري (١٩٠١)، ومسلم (٧٦٠).","grade":"متفق عليه","chapter_ar":"باب الترغيب في قيام الليل في رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1901) and Muslim (760).","chapter_en":"Encouragement for standing in prayer at night in Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever fasts Ramadan with faith and seeking reward will be forgiven for his previous sins, and whoever stands in prayer on the Night of Decree with faith and seeking reward will be forgiven for his previous sins.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1901},{"key":"muslim","label":"مسلم","number":760}]},{"num":4637,"demo":false,"sanad":"","matn":["عن أبي هريرة:","أن رسول الله ﷺ كان يرغّب في قيام رمضان من غير أن يأمر بعزيمة، فيقول:","«مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».","قال ابن شهاب:","فتوفي رسول الله ﷺ والأمر على ذلك، ثم كان الأمر على ذلك في خلافة أبي بكر، وصدرًا من خلافة عمر."],"takhrij":"صحيح: رواه مالك (٢)، ومسلم (٧٥٩/١٧٤).","grade":"صحيح","chapter_ar":"باب الترغيب في قيام الليل في رمضان من غير عزيمة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (2) and Muslim (759/174).","chapter_en":"Encouragement for night prayer in Ramadan without making it an obligation","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah reported:","The Messenger of Allah ﷺ used to encourage standing in prayer during Ramadan without commanding it as a binding obligation. He would say:","“Whoever stands in prayer during Ramadan with faith and seeking reward will have his previous sins forgiven.”","Ibn Shihāb said:","The Messenger of Allah ﷺ died while the matter remained in this state. It remained so throughout the caliphate of Abū Bakr and during the early part of the caliphate of ʿUmar."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2},{"key":"muslim","label":"مسلم","number":759}]},{"num":4638,"demo":false,"sanad":"","matn":["عن عائشة قالت:","إن رسول الله ﷺ كان يرغّب الناس في قيام رمضان من غير أن يأمرهم بعزيمة أمر فيه، فيقول:","«مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».","وفي رواية:","خرج في جوف الليل يصلي في المسجد، فصلى بالناس.","وجاء فيها:","«كَانَ يُرَغِّبُهُمْ فِي قِيَامِ رَمَضَانَ مِنْ غَيْرِ أَنْ يَأْمُرَهُمْ بِعَزِيمَةٍ، وَيَقُولُ: مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ».","قال:","فتوفي رسول الله ﷺ والأمر على ذلك."],"takhrij":"صحيح: رواه النسائي (٢١٩٢، ٢١٩٣، ٢١٩٥)، وصححه ابن خزيمة (٢٢٠٧)، وابن حبان (٢٥٤٣).","grade":"صحيح","chapter_ar":"باب الترغيب في قيام الليل في رمضان من غير عزيمة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (2192, 2193, 2195), and authenticated by Ibn Khuzaymah (2207) and Ibn Ḥibbān (2543).","chapter_en":"Encouragement for night prayer in Ramadan without making it an obligation","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["ʿĀʾishah reported:","The Messenger of Allah ﷺ used to encourage the people to stand in prayer during Ramadan without commanding them to do so as a binding obligation. He would say:","“Whoever stands in prayer during Ramadan with faith and seeking reward will have his previous sins forgiven.”","In another narration:","He went out in the middle of the night and prayed in the mosque, and the people prayed behind him.","It also states:","“He used to encourage them to stand in prayer during Ramadan without commanding it as a binding obligation, and he would say:","‘Whoever stands in prayer on the Night of Decree with faith and seeking reward will have his previous sins forgiven.’”","Then the Messenger of Allah ﷺ died while the matter remained in that state."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2192},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2207},{"key":"ibnhibban","label":"ابن حبان","number":2543}]},{"num":4639,"demo":false,"sanad":"","matn":["عن عائشة أن رسول الله ﷺ خرج ليلةً من جوف الليل، فصلّى في المسجد، وصلّى رجالٌ بصلاته، فأصبح الناس، فتحدّثوا، فاجتمع أكثر منهم، فصلّى فصلّوا معه، فأصبح الناس تحدّثوا، فكثر أهل المسجد من الليلة الثالثة، فخرج رسول الله ﷺ فصلّى فصلّوا بصلاته، فلمّا كانت الليلة الرابعة، عجز المسجد عن أهله، حتى خرج لصلاة الصبح، فلمّا قضى الفجر، أقبل على الناس فتشهّد، ثم قال: (( أما بعد، فإنه لم يخف عليّ مكانكم، ولكنّي خشيت أن تُفرض عليكم، فتعجزوا عنها )). فتوفي رسول الله ﷺ والأمر على ذلك."],"takhrij":"متفق عليه: رواه البخاري (٢٠١٢)، ومسلم (١٧٨:٧٦١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في عدم استمرار رسول الله ﷺ في صلاة التراويح بالجماعة خشية أن تفرض على الأمة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2012) and Muslim (761 no. 178).","chapter_en":"What has been reported regarding the Messenger of Allah ﷺ not continuing Tarāwīḥ in congregation for fear that it would be made obligatory upon the Ummah","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ went out one night in the middle of the night and prayed in the mosque, and some men prayed with his prayer. In the morning the people spoke about it, so more gathered the next night, and he prayed and they prayed with him. In the morning the people spoke again, so the people in the mosque increased on the third night. He came out and prayed, and they prayed with his prayer. But on the fourth night, the mosque could not contain its people, until he came out only for the dawn prayer. When he finished dawn, he turned to the people, said the testimony, then said: “As for what follows, your place was not hidden from me, but I feared that it would be made obligatory upon you, and then you would be unable to do it.” Then the Messenger of Allah ﷺ passed away while the matter remained like that."]},"intro":{"ar":["وسمّى السحور بالفلاح لأن بقاء الصوم به، والسحور يُعين على إتمام الصوم.","كان شهر رمضان في تلك السنة ثلاثين يومًا.","فقوله: (( حتى بقي سبع قام )) أي ليلة الثالث والعشرين.","وقوله: (( لم يقم في السادسة )) أي ليلة الرابع والعشرين.","وقوله: (( فلما كانت الخامسة قام )) أي ليلة الخامس والعشرين.","وقوله: (( فلما كانت الثالثة جمع أهله ونساءه فقام )) أي ليلة السابع والعشرين."],"en":["He called the pre-dawn meal success because fasting continues through it, and the pre-dawn meal helps one complete the fast.","Ramadan in that year was thirty days.","So his statement, “until seven remained, he led us,” means the night of the twenty-third.","And “he did not lead us on the sixth,” means the night of the twenty-fourth.","And “when the fifth remained, he led us,” means the night of the twenty-fifth.","And “when the third remained, he gathered his family and wives and led us,” means the night of the twenty-seventh."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2012},{"key":"muslim","label":"مسلم","number":178}]},{"num":4640,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ قالت: كان الناس يصلون في مسجد رسول اللّٰه ﷺ في رمضان باللّيل أوزاعاً، يكون مع الرّجل شيء من القرآن فيكون معه النفر الخمسة أو الستة أو أقل من ذلك أو أكثر فيصلون بصلاته. قالت: فأمرني رسول اللّٰه ﷺ ليلة من ذلك أن أنصب له حصيراً على باب حجرتي ففعلت، فخرج إليه رسول اللّٰه ﷺ بعد أن صلى العشاء الآخرة. قالت: فاجتمع إليه من في المسجد فصلى بهم رسول اللّٰه ﷺ ليلاً طويلاً، ثم انصرف رسول اللّٰه ﷺ فدخل وترك الحصير على حاله، فلما أصبح الناس تحدّثوا بصلاة رسول اللّٰه ﷺ بمن كان معه في المسجد تلك الليلة. قالت: وأمسى المسجد راجَّه بالناس، فصلى بهم رسول اللّٰه ﷺ العشاء الآخرة، ثم دخل بيته وثبت الناس. قالت: فقال لي رسول اللّٰه ﷺ: (( ما شأن الناس يا عائشة؟ )). قالت: فقلت له: يا رسول اللّٰه، سمع الناس بصلاتك البارحة بمن كان في المسجد، فحشدوا لذلك لتصلّي بهم. قالت: فقال: (( اطوِ عنا حصيرك يا عائشة )). قالت: ففعلت، وبات رسول اللّٰه ﷺ غير غافل، وثبت الناس مكانهم حتى خرج رسول اللّٰه ﷺ إلى الصبح. فقال: (( أيها الناس، أما والله ما بتُّ - والحمد لله - ليلتي هذه غافلاً، وما خفي عليّ مكانكم، ولكني تخوفت أن يُفرض عليكم فاكلفوا من الأعمال ما تطيقون، فإن الله لا يمل حتى تملوا )).","قالت: وكانت عائشة تقول: إن أحبّ الأعمال إلى اللّٰه أدومها وإن قلّ."],"takhrij":"حسن: رواه الإمام أحمد (٢٦٣٠٧)، والطبراني في الأوسط (٥٢٧٧).","grade":"حسن","chapter_ar":"باب ما جاء في عدم استمرار رسول الله ﷺ في صلاة التراويح بالجماعة خشية أن تفرض على الأمة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (26307) and al-Tabarani in al-Awsat (5277).","chapter_en":"What has been reported regarding the Messenger of Allah ﷺ not continuing Tarāwīḥ in congregation for fear that it would be made obligatory upon the Ummah","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: The people used to pray in the mosque of the Messenger of Allah ﷺ during the nights of Ramadan in scattered groups. A man would have some Qur’an with him, so five or six people or fewer or more would pray behind him. One night the Messenger of Allah ﷺ told me to spread out a mat for him at the door of my room, and I did so. The Messenger of Allah ﷺ came out to it after praying the night prayer. Those in the mosque gathered around him, and he led them in a long prayer during the night. Then the Messenger of Allah ﷺ left and entered, leaving the mat as it was. In the morning the people spoke about the prayer of the Messenger of Allah ﷺ with those who were with him in the mosque that night. By evening the mosque was crowded with people, and he led them in the night prayer, then entered his house while the people remained in place. He said to me: “What is the matter with the people, O ʿA’ishah?” I said: O Messenger of Allah, the people heard about your prayer last night with those in the mosque, so they gathered hoping you would pray with them. She said: He replied: “Fold away your mat from us, O ʿA’ishah.” I did so, and the Messenger of Allah ﷺ spent that night not neglectful, while the people remained in their places until he came out for dawn. Then he said: “O people, by Allah, I did not spend this night unaware — all praise is for Allah — nor was your place hidden from me, but I feared that it might be made obligatory upon you. So take on deeds that you are able to bear, for Allah does not tire until you tire.”","ʿA’ishah used to say: The most beloved deeds to Allah are those that are most constant, even if small."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":26307},{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":5277},{"key":"ahmad","label":"مسند الإمام أحمد","number":26307,"n":26307}]},{"num":4641,"demo":false,"sanad":"","matn":["عن أبي ذرّ، قال: صُمنا مع رسول اللّٰه ﷺ رمضان، فلم يقم بنا شيئاً من الشّهر، حتى بقي سبعٌ، فقام بنا حتى ذهب ثلث الليل، فلما كانت السادسة لم يقم بنا، فلما كانت الخامسةُ قام بنا حتى ذهب شطر الليل. فقلت: يا رسول الله، لو نفلتنا قيام هذه الليلة؟ قال: فقال: (( إن الرجل إذا صلّى مع الإمام حتى ينصرف حُسب له قيام ليلة )).","قال: فلما كانت الرابعة لم يقم، فلما كانت الثالثة جمع أهله ونساءه والناس، فقام بنا حتى خشينا أن يفوتنا الفلاح. قال: قلت: وما الفلاح؟ قال: السَّحور، ثم لم يقم بنا بقية الشّهر."],"takhrij":"صحيح: رواه أبو داود (١٣٧٥)، والترمذي (٨٠٦)، والنسائي (١٦٠٥، ١٣٦٤)، وابن ماجه (١٣٢٧). وقال الترمذي: (( حسن صحيح )).","grade":"صحيح","chapter_ar":"باب ما جاء في عدم استمرار رسول الله ﷺ في صلاة التراويح بالجماعة خشية أن تفرض على الأمة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1375), al-Tirmidhi (806), al-Nasa’i (1364, 1605), and Ibn Majah (1327). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What has been reported regarding the Messenger of Allah ﷺ not continuing Tarāwīḥ in congregation for fear that it would be made obligatory upon the Ummah","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abu Dharr said: We fasted Ramadan with the Messenger of Allah ﷺ, and he did not lead us in night prayer during any of the month until seven nights remained. Then he led us until one-third of the night had passed. When the sixth night remained, he did not lead us. When the fifth night remained, he led us until half the night had passed. I said: O Messenger of Allah, if only you would give us extra prayer for the rest of this night. He said: “If a man prays with the imam until he finishes, it is recorded for him as the prayer of an entire night.”","He said: When the fourth night remained, he did not lead us. When the third night remained, he gathered his family, his wives, and the people, and led us until we feared we would miss success. I said: What is success? He said: the pre-dawn meal. Then he did not lead us for the rest of the month."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1375},{"key":"tirmidhi","label":"الترمذي","number":806},{"key":"nasai","label":"النسائي","number":1605},{"key":"ibnmajah","label":"ابن ماجه","number":1327}]},{"num":4642,"demo":false,"sanad":"","matn":["عن نعيم بن زياد، قال: سمعتُ النّعمان بن بشير على منبر حمص يقول: قمنا مع رسول اللّٰه ﷺ في شهر رمضان ليلة ثلاث وعشرين إلى ثُلث الليل الأوّل، ثم قمنا معه ليلة خمس وعشرين إلى نصف الليل، ثم قمنا معه ليلة سبع وعشرين حتى ظنّنا أن لا ندرك الفلاح، وكانوا يسمونه السُّحور."],"takhrij":"حسن: رواه النسائي (١٦٠٦)، وأحمد (١٨٤٠٢)، وصحّحه ابن خزيمة (٢٢٠٤)، والحاكم (٤٤٠/١).","grade":"حسن","chapter_ar":"باب ما جاء في عدم استمرار رسول الله ﷺ في صلاة التراويح بالجماعة خشية أن تفرض على الأمة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (1606), Ahmad (18402), and authenticated by Ibn Khuzaymah (2204) and al-Hakim (1/440).","chapter_en":"What has been reported regarding the Messenger of Allah ﷺ not continuing Tarāwīḥ in congregation for fear that it would be made obligatory upon the Ummah","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Nuʿaym ibn Ziyad said: I heard al-Nuʿman ibn Bashir saying from the pulpit of Hims: We stood in prayer with the Messenger of Allah ﷺ in Ramadan on the night of the twenty-third until the first third of the night, then we stood with him on the night of the twenty-fifth until half the night, then we stood with him on the night of the twenty-seventh until we thought we would not catch success, and they used to call it the pre-dawn meal."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":1606},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2204},{"key":"ahmad","label":"مسند الإمام أحمد","number":18402,"n":18402},{"key":"hakim","label":"المستدرك على الصحيحين","number":1608,"n":1597}]},{"num":4643,"demo":false,"sanad":"","matn":["عن أنس، أنّ النبيِّ ﷺ كان يصلى بالليل في رمضان، فجاء قومٌ فقاموا خلفه، فصلّى فكان يخفَّف، ثم يدخل بيته فيصلي، ثم يخرُج ويخفِّف. فلما أصبح، قالوا: يا رسول الله، قمنا خلفك الليلة، فكنتَ تدخلُ بيتك ثم تخرج؟ فقال: (( إنّما فعلتُ ذلك من أجلكم ))."],"takhrij":"صحيح: رواه الطبراني في الأوسط (٨٢٠٤).","grade":"صحيح","chapter_ar":"باب ما جاء في عدم استمرار رسول الله ﷺ في صلاة التراويح بالجماعة خشية أن تفرض على الأمة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Tabarani in al-Awsat (8204).","chapter_en":"What has been reported regarding the Messenger of Allah ﷺ not continuing Tarāwīḥ in congregation for fear that it would be made obligatory upon the Ummah","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ used to pray at night in Ramadan. Some people came and stood behind him, so he prayed and would lighten the prayer, then enter his house and pray, then come out and lighten it. In the morning they said: O Messenger of Allah, we stood behind you last night, but you kept entering your house and then coming out. He said: “I only did that because of you.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":8204},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":8208,"n":8193}]},{"num":4644,"demo":false,"sanad":"","matn":["عن عبدالرحمن بن عبد القاري أنه قال: خرجتُ مع عمر بن الخطاب في رمضان إلى المسجد، فإذا الناسُ أوزاعٌ متفرِّقون، يصلّي الرجلُ لنفسه، ويصلي الرجل فيصلّي بصلاته الرَّهْط. فقال عمر: والله إنّي لأراني لو جمعتُ هؤلاء على قارئ واحد لكان أمثل، فجمعهم على أُبيّ بن كعب.","قال: ثم خرجتُ معه ليلة أخرى والناسُ يصلُّون بصلاة قارئهم. فقال عمر: نعمتِ البدعةُ هذه، والتي تنامون عنها أفضل من التي تقومون يعني آخر الليل، وكان الناسُ يقومون أوله."],"takhrij":"صحيح: رواه مالك (٣)، والبخاري (٢٠١٠).","grade":"صحيح","chapter_ar":"باب صلاة التراويح مُفرقًا في صدر خلافة عمر قبل جمعهم على إمام واحد","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Malik (3) and al-Bukhari (2010).","chapter_en":"Tarawih being prayed separately in the early part of ʿUmar’s caliphate before he gathered them behind one imam","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["ʿAbd al-Rahman ibn ʿAbd al-Qari said: I went out with ʿUmar ibn al-Khattab in Ramadan to the mosque, and the people were scattered in separate groups. A man would pray by himself, and another man would pray with a small group praying behind him. So ʿUmar said: “By Allah, I think that if I gathered these people behind one reciter, that would be better.” So he gathered them behind Ubayy ibn Kaʿb.","Then I went out with him another night and the people were praying behind their reciter. ʿUmar said: “What an excellent innovation this is, and the prayer they sleep through is better than the one they are performing,” meaning the prayer at the end of the night, while the people were praying at its beginning."]},"intro":{"ar":["وقول عمر: (( نعمت البدعة هذه )) البدعة هنا بمعناها اللغويّ.","وأمّا في الشّرع فهي بمقابل السنة، وإنّما مدحها عمر لأنّها ليست ببدعة شرعاً، بل هي سنّة لإقرار النبيّ ﷺ من صلّى معه في بعض ليالي رمضان، وإن كان كره ذلك لهم خشية أن تفترض عليهم، فلما مات النبيّ ﷺ حصل الأمن من ذلك. ولذلك قال ابن بطال: قيام رمضان سنة؛ لأنّ عمر إنما أخذه من فعل النبيّ ﷺ، وإنّما تركه النبيّ خشية الافتراض. انظر: فتح الباري (٢٥٢/٤)."],"en":["ʿUmar’s statement, “What an excellent innovation this is,” uses the word innovation in its linguistic sense.","As for its meaning in religious law, it is the opposite of the Sunnah. ʿUmar praised it only because it was not a religious innovation; rather, it was a Sunnah, since the Prophet ﷺ approved of those who prayed with him during some nights of Ramadan, although he disliked continuing it for them out of fear that it would be made obligatory on them. When the Prophet ﷺ died, that fear no longer remained. For this reason Ibn Battal said: Prayer in Ramadan is a Sunnah, because ʿUmar only took it from the action of the Prophet ﷺ, and the Prophet only left it out of fear that it would be made obligatory. See: Fath al-Bari (4/252)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":3},{"key":"bukhari","label":"البخاري","number":2010}]},{"num":4645,"demo":false,"sanad":"","matn":["عن أبي سلمة بن عبدالرحمن بن عوف، أنه سأل عائشة، زوج النبيّ ﷺ: كيف كانتْ صلاةُ رسول اللّٰه ﷺ في رمضان؟ فقالت: ما كان رسول اللٰه ﷺ يزيدُ في رمضان ولا في غيره على إحدى عشرة ركعة. يصلي أربعاً، فلا تسأل عن حُسنهنّ وطولهنَّ. ثم يصلي أربعاً فلا تسألْ عن حسنهنَّ وطولهنَّ. ثم يصلي ثلاثاً. فقالت عائشة: فقلتُ: يا رسول الله، أتنامُ قبل أن توتِر؟ فقال: (( يا عائشة، إنَّ عيْنيَّ تنامان، ولا ينام قلبي ))."],"takhrij":"متفق عليه: رواه مالك (٩) والبخاري (٢٠١٣)، ومسلم (١٢٥:٧٣٨).","grade":"متفق عليه","chapter_ar":"باب بيان عدد الركعات في قيام الليل في رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (9), al-Bukhari (2013), and Muslim (738 no. 125).","chapter_en":"Clarifying the number of units in the night prayer during Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Abu Salamah ibn ʿAbd al-Rahman ibn ʿAwf said that he asked ʿA’ishah, the wife of the Prophet ﷺ: How was the prayer of the Messenger of Allah ﷺ in Ramadan? She said: The Messenger of Allah ﷺ would not exceed eleven units in Ramadan or outside of it. He would pray four, and do not ask about their beauty and length. Then he would pray four, and do not ask about their beauty and length. Then he would pray three. ʿA’ishah said: I said: O Messenger of Allah, do you sleep before praying the odd-numbered prayer? He said: “O ʿA’ishah, my eyes sleep, but my heart does not sleep.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"bukhari","label":"البخاري","number":2013},{"key":"muslim","label":"مسلم","number":125}]},{"num":4646,"demo":false,"sanad":"","matn":["عن أبي سلمة، قال: أتيتُ عائشة، فقلتُ: أي أمه أخبرني عن صلاة رسول اللّٰه ﷺ فقالت: كانت صلاته في شهر رمضان وغيره ثلاث عشرة ركعة بالليل، منها ركعتا الفجر."],"takhrij":"متفق عليه: رواه مسلم (١٢٧:٧٣٨) والبخاريّ (١١٤٠).","grade":"متفق عليه","chapter_ar":"باب بيان عدد الركعات في قيام الليل في رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Muslim (738 no. 127) and al-Bukhari (1140).","chapter_en":"Clarifying the number of units in the night prayer during Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Abu Salamah said: I came to ʿA’ishah and said: O mother, tell me about the prayer of the Messenger of Allah ﷺ. She said: His prayer in Ramadan and outside of it was thirteen units at night, including the two units of dawn."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":127},{"key":"bukhari","label":"البخاريّ","number":1140}]},{"num":4647,"demo":false,"sanad":"","matn":["عن السّائب بن يزيد أنه قال: أمر عمر بن الخطاب أبيَّ بنَ كعب وتميما الدّاريَّ أن يقوما للناس بإحدى عشرة ركعة. قال: وقد كان القارئُ يقرأَ بالمئين، حتى كنّا نعتمدُ على العصيُّ من طول القيام، وما كنّا ننصرف إلا في فروع الفجر."],"takhrij":"صحيح: رواه مالك (٤).","grade":"صحيح","chapter_ar":"باب بيان عدد الركعات في قيام الليل في رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Malik (4).","chapter_en":"Clarifying the number of units in the night prayer during Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Al-Sa’ib ibn Yazid said: ʿUmar ibn al-Khattab ordered Ubayy ibn Kaʿb and Tamim al-Dari to lead the people in prayer with eleven units. He said: The reciter would recite by the hundreds of verses, until we would lean on sticks because of the length of standing, and we would not leave until the early parts of dawn."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4}]},{"num":4648,"demo":false,"sanad":"","matn":["عن السائب بن يزيد:","أن عمر جمع الناس في رمضان على أُبيّ بن كعب، وعلى تميم الداري، على إحدى وعشرين ركعة، يقرؤون بالمئين، وينصرفون عند فروع الفجر."],"takhrij":"صحيح: رواه عبد الرزاق (٧٧٣٠).","grade":"صحيح","chapter_ar":"باب بيان عدد الركعات في قيام الليل في رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzāq (7730).","chapter_en":"Clarifying the number of units in the night prayer during Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Al-Sāʾib ibn Yazīd reported:","ʿUmar gathered the people during Ramadan behind Ubayy ibn Kaʿb and Tamīm al-Dārī for twenty-one rakʿahs. They would recite surahs containing hundreds of verses and would finish around the beginning of dawn."]},"buhuth":{"ar":["وكان أُبيّ بن كعب يصلي بالرجال، وكان تميم الداري يصلي بالنساء، كما رواه سعيد بن منصور من طريق عروة. وذكر محمد بن نصر في كتاب قيام الليل أن إمام النساء سليمان بن أبي حثمة، فقال ابن رجب:","«لعل ذلك كان في وقتين».","وفيه دليل على حضور النساء في المساجد لأداء صلاة التراويح إذا لم يكن في حضورهن فتنة.","والأمر بعشرين ركعة يعود إلى أنه لما رأى عمر طول القيام، وشعر بمشقة الناس، وفيهم الكبير والضعيف، أمر بتخفيف القراءة وإكثار الركوع والسجود؛ لأن صلاة التراويح من الصلوات النافلة، فيجوز فيها الزيادة، وعليه تدل الآثار الآتية عن عمر بن الخطاب وغيره."],"en":["Ubayy ibn Kaʿb would lead the men in prayer, while Tamīm al-Dārī would lead the women, as Saʿīd ibn Manṣūr narrated through ʿUrwah. Muḥammad ibn Naṣr mentioned in Qiyām al-Layl that Sulaymān ibn Abī Ḥathmah led the women. Ibn Rajab said:","“Perhaps this occurred at two different times.”","This also indicates that women may attend the mosques to perform Tarāwīḥ when their attendance does not involve temptation or fitnah.","The instruction to perform twenty rakʿahs is explained by ʿUmar seeing the length of the standing and recognizing the hardship it caused for the people, including the elderly and weak. He therefore instructed that the recitation be shortened while increasing the number of bowings and prostrations. Since Tarāwīḥ is a voluntary prayer, its number may be increased, as is also indicated by the subsequent reports from ʿUmar ibn al-Khaṭṭāb and others."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":7730},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":7973,"n":7972}]},{"num":4649,"demo":false,"sanad":"","matn":["عن أبي ذر، عن النبي ﷺ قال:","«إِنَّ الرَّجُلَ إِذَا صَلَّى مَعَ الْإِمَامِ حَتَّى يَنْصَرِفَ، حُسِبَ لَهُ قِيَامُ لَيْلَةٍ»."],"takhrij":"صحيح: رواه أبو داود (١٣٧٥)، والترمذي (٨٠٦)، والنسائي (١٣٦٤)، وابن ماجه (١٣٢٧).","grade":"صحيح","chapter_ar":"باب من صلّى مع الإمام حتى ينصرف حُسِبَ له قيام ليلة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1375), al-Tirmidhī (806), al-Nasāʾī (1364), and Ibn Mājah (1327).","chapter_en":"Whoever prays with the imam until he finishes is credited with standing in prayer for an entire night","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في قيام الليل في رمضان","group_en":"Collected chapters regarding the night prayer in Ramadan","part_no":15,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Abū Dharr reported that the Prophet ﷺ said:","“When a man prays with the imam until the imam finishes, it is counted for him as standing in prayer for an entire night.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1375},{"key":"tirmidhi","label":"الترمذي","number":806},{"key":"nasai","label":"النسائي","number":1364},{"key":"ibnmajah","label":"ابن ماجه","number":1327}]},{"num":4650,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبيّ ﷺ قال: (( من صام رمضان إيماناً واحتساباً غُفر له ما تقدّم من ذنبه، ومن قام ليلة القدر إيماناً واحتساباً غفر له ما تقدّم من ذنبه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠١٤)، ومسلم (٧٦٠).","grade":"متفق عليه","chapter_ar":"باب فضل قيام ليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2014) and Muslim (760).","chapter_en":"The virtue of standing in prayer on Laylat al-Qadr","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah reported from the Prophet ﷺ that he said: “Whoever fasts Ramadan with faith and seeking reward will be forgiven for his previous sins, and whoever stands in prayer on the Night of Decree with faith and seeking reward will be forgiven for his previous sins.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2014},{"key":"muslim","label":"مسلم","number":760}]},{"num":4651,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ، قالت: كان النبيّ ﷺ إذا دخل العشرُ أحيا اللّيل وأيقظ أهله وجدَّ وشدّ المئزر."],"takhrij":"متفق عليه: رواه البخاري (٢٠٢٤)، ومسلم (١١٧٤). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب اجتهاد النبي ﷺ في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2024) and Muslim (1174), and the wording is that of Muslim.","chapter_en":"The Prophet’s striving in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: When the last ten nights began, the Prophet ﷺ would enliven the night, wake his family, strive hard, and tighten his waist-wrapper."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2024},{"key":"muslim","label":"مسلم","number":1174}]},{"num":4652,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ، قالت: كان رسول اللّٰه ﷺ يجتهد في العشر الأواخر ما لا يجتهد في غيره."],"takhrij":"صحيح: رواه مسلم (١١٧٥).","grade":"صحيح","chapter_ar":"باب اجتهاد النبي ﷺ في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1175).","chapter_en":"The Prophet’s striving in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ would strive in the last ten nights in a way that he would not strive in other times."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1175}]},{"num":4653,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، قال: كان النبيُّ ﷺ إذا كان العشر الأواخر من رمضان شدَّ المئزر، واعتزل النساء."],"takhrij":"حسن: رواه البيهقي في “الكبرى” (٣١٤/٤)، وفي “فضائل الأوقات” (٧٥).","grade":"حسن","chapter_ar":"باب اجتهاد النبي ﷺ في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Bayhaqi in al-Kubra (4/314) and in Fada’il al-Awqat (75).","chapter_en":"The Prophet’s striving in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: When the last ten nights of Ramadan came, the Prophet ﷺ would tighten his waist-wrapper and keep away from women."]}},"tuhfa":{},"refs":[{"key":"البیہقی/الکبری","label":"البيهقي في “الكبرى”","number":314},{"key":"وفی_فضایل_الاوقات","label":"وفي “فضائل الأوقات”","number":75}]},{"num":4654,"demo":false,"sanad":"","matn":["عن علي ، أنّ النبيّ ﷺ كان يوقظ أهله في العشر الأواخر من رمضان."],"takhrij":"حسن: رواه الترمذي (٧٩٥). قال الترمذي: (( حسن صحيح )).","grade":"حسن","chapter_ar":"باب اجتهاد النبي ﷺ في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (795). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prophet’s striving in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["ʿAli reported that the Prophet ﷺ used to wake his family in the last ten nights of Ramadan."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":795}]},{"num":4655,"demo":false,"sanad":"","matn":["عن زرّ بن حبيش يقول: سألت أُبَيَّ بن كعب رضي اللّٰه عنه، فقلت: إنّ أخاك ابن مسعود يقول: مَنْ يَقُم الحوْلَ يُصِبْ ليلةَ القَدْر؟ فقال: رحمه اللّٰه أراد أن لا يتكل الناس، أما إن قد علم أنها في رمضان، وأنّها في العشر الأواخر، وأنّها ليلة سبع وعشرين - ثم حلف لا يستثني - أنها ليلة سبع وعشرين. فقلت: بأيِّ شيء تقول ذلك يا أبا المنذر؟ قال: بالعلامة أو بالآية التي أخبرنا رسول اللّٰه ﷺ: (( أنّها تطلعُ يومئذٍ لا شعاع لها ))."],"takhrij":"صحيح: رواه مسلم (٧٦٢/٢٢٠).","grade":"صحيح","chapter_ar":"باب ما جاء من علامات ليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (762 no. 220).","chapter_en":"What has been reported regarding the signs of the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Zirr ibn Hubaysh said: I asked Ubayy ibn Kaʿb, may Allah be pleased with him, and said: Your brother Ibn Masʿud says: Whoever stands in prayer the whole year will find the Night of Decree. He said: May Allah have mercy on him; he wanted the people not to become reliant and lazy. But he certainly knew that it is in Ramadan, that it is in the last ten nights, and that it is the night of the twenty-seventh — then he swore without making an exception — that it is the night of the twenty-seventh. I said: By what do you say that, O Abu al-Mundhir? He said: By the sign or indication that the Messenger of Allah ﷺ told us: “The sun rises on its morning without rays.”"]},"intro":{"ar":["وفي سنن أبي داود (١٣٧٨) وغيره: (( تصبح الشمس صبيحة تلك الليلة مثل الطَّست، ليس لها شعاع حتى ترتفع )).","والطَّست أي مظلمة لا ضوء لها."],"en":["And in Sunan Abi Dawud (1378) and elsewhere: “The sun on the morning after that night rises like a basin, without rays until it rises higher.”","The comparison means that it appears dim, without brightness."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":762}]},{"num":4656,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أُتيتُ وأنا نائم في رمضان، فقيل لي: إنّ الليلة ليلة القدر، فقمتُ وأنا ناعس، فتعلّقتُ ببعض أطناب فسطاط رسول اللّٰه ﷺ، فأتيتُ رسول اللّٰه ﷺ وهو يصلّي، فنظرتُ في الليلة فإذا هي ليلة ثلاث وعشرين. قال ابن عباس: إنّ الشيطان يطلع مع الشمس كلَّ يوم إلا ليلة القدر، وذلك أنها تطلع يومئذٍ ولا شعاع لها."],"takhrij":"حسن: رواه البيهقيّ في “فضائل الأوقات” (١٠٤)، والإمام أحمد (٢٣٠٢).","grade":"حسن","chapter_ar":"باب ما جاء من علامات ليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Bayhaqi in Fada’il al-Awqat (104) and Ahmad (2302).","chapter_en":"What has been reported regarding the signs of the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas said: While I was asleep in Ramadan, I was told: Tonight is the Night of Decree. So I got up while still drowsy and held onto one of the ropes of the tent of the Messenger of Allah ﷺ. I came to the Messenger of Allah ﷺ while he was praying, and I looked into that night and found that it was the twenty-third night. Ibn ʿAbbas said: Satan rises with the sun every day except on the Night of Decree, and on that morning it rises without rays."]}},"tuhfa":{},"refs":[{"key":"البیہقی/فضایل_الاوقات","label":"البيهقيّ في “فضائل الأوقات”","number":104},{"key":"الامام_احمد","label":"الإمام أحمد","number":2302},{"key":"ahmad","label":"مسند الإمام أحمد","number":2302,"n":2302}]},{"num":4657,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: قال رسول اللٰه ﷺ: (( إني كنتُ أُريتُ ليلة القدر، ثم نُسِّيتُها، وهي في العشر الأواخر من ليلتها، وهي ليلة طلقة بلجة، لا حارّة ولا باردة )).","وفي رواية: (( كأنّ فيها قمراً يفضح كواكبها )). وقالا: (( لا يخرج شيطانُها حتى يضيء فجرها ))."],"takhrij":"حسن: رواه ابن خزيمة (٢١٩٠)، وعنه ابن حبان (٣٦٨٨).","grade":"حسن","chapter_ar":"باب ما جاء من علامات ليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Khuzaymah (2190), and by Ibn Hibban from him (3688).","chapter_en":"What has been reported regarding the signs of the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: The Messenger of Allah ﷺ said: “I was shown the Night of Decree, then I was made to forget it. It is in the last ten nights, and it is a calm, bright night, neither hot nor cold.”","In another wording: “It is as though there is a moon in it that outshines its stars.” And in another report: “Its devil does not come out until its dawn becomes bright.”"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2190},{"key":"عنہ_ابن_حبان","label":"عنه ابن حبان","number":3688},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4222,"n":4218}]},{"num":4658,"demo":false,"sanad":"","matn":["عن عائشة، قالت: قلتُ: يا رسول الله، أرأيتَ إن علمتُ ليلة القدر ما أقول فيها؟ قال: (( قولي: اللهمّ إنّك عفوٌّ تحبُّ العفوَ فاعفُ عنّي ))."],"takhrij":"صحيح: رواه النسائي في الكبرىٰ (١٠٦٤٧).","grade":"صحيح","chapter_ar":"باب ما يقال إذا وافق ليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i in al-Sunan al-Kubra (10647).","chapter_en":"What should be said if one attains the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: I said: O Messenger of Allah, if I know which night is the Night of Decree, what should I say in it? He said: “Say: O Allah, You are Pardoning, You love pardon, so pardon me.”"]}},"tuhfa":{},"refs":[{"key":"nasai/الکبری","label":"النسائي في الكبرىٰ","number":10647}]},{"num":4659,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول اللّٰه ﷺ قال: (( أُريتُ ليلة القدر، ثم أيقظني بعضُ أهلي، فُنُسِّيتُها، فالتمسوها في العشر الغوابر ))."],"takhrij":"صحيح: رواه مسلم (١١٦٦).","grade":"صحيح","chapter_ar":"باب ما جاء في ليلة القدر أنها في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1166).","chapter_en":"What has been reported that the Night of Decree is in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah reported that the Messenger of Allah ﷺ said: “I was shown the Night of Decree, then one of my family woke me and I was made to forget it, so seek it in the remaining last ten nights.”"]},"buhuth":{"ar":["قوله: (( الغوابر )) يعني البواقي، وهي الأواخر."],"en":["The word “the remaining” here means the nights that are left, meaning the last nights."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1166}]},{"num":4660,"demo":false,"sanad":"","matn":["عن ابن عمر رضي الله عنهما، أن رجالاً من أصحاب النبي ﷺ أُروا ليلة القدر في المنام في السبع الأواخر، فقال رسول الله ﷺ: (( أرى رؤياكم قد تواطأت في السبع الأواخر، فمن كان متحريها فليتحرها في السبع الأواخر ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠١٥)، ومسلم (١١٦٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء في ليلة القدر أنها في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2015) and Muslim (1165).","chapter_en":"What has been reported that the Night of Decree is in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, both, reported that some men among the Companions of the Prophet ﷺ were shown the Night of Decree in their dreams during the last seven nights. The Messenger of Allah ﷺ said: “I see that your dreams agree concerning the last seven nights, so whoever seeks it should seek it in the last seven nights.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2015},{"key":"muslim","label":"مسلم","number":1165}]},{"num":4661,"demo":false,"sanad":"","matn":["عن ابن عمر، عن النبيّ ﷺ قال: (( من كان مُلتمسها، فليلتمسها في العشر الأواخر ))."],"takhrij":"صحيح: رواه مسلم (١١٦٥/٢١٠).","grade":"صحيح","chapter_ar":"باب ما جاء في ليلة القدر أنها في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1165 no. 210).","chapter_en":"What has been reported that the Night of Decree is in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar reported from the Prophet ﷺ that he said: “Whoever seeks it should seek it in the last ten nights.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1165}]},{"num":4662,"demo":false,"sanad":"","matn":["عن الفلتان بن عاصم، قال: قال رسول الله ﷺ: (( إني رأيت ليلة القدر، ثم أُنسيتُها، ورأيتُ مسيح الضلالة، ورأيت رجلين يتلاحيان، فحجزت بينهما، فأنسيتُهما. فأمّا ليلة القدر فاطلبوها في العشر الأواخر. وأما مسيح الضلالة فرجل أجلى الجبهة، ممسوح العين اليسرى، عريض النحر، فيه دفأ، كأنه فلان بن عبد العزّى، أو عبد العزى بن فلان ))."],"takhrij":"حسن: رواه أبو بكر بن أبي شيبة في “مسنده” - المطالب العالية (١١١٥).","grade":"حسن","chapter_ar":"باب ما جاء في ليلة القدر أنها في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Bakr ibn Abi Shaybah in his Musnad — al-Matalib al-ʿAliyah (1115).","chapter_en":"What has been reported that the Night of Decree is in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Al-Faltan ibn ʿAsim said: The Messenger of Allah ﷺ said: “I saw the Night of Decree, then I was made to forget it. I also saw the false messiah of misguidance, and I saw two men arguing, so I separated them, and because of that I was made to forget them. As for the Night of Decree, seek it in the last ten nights. As for the false messiah of misguidance, he is a man with a broad forehead, his left eye effaced, broad-necked, with a stoop, as though he were such-and-such son of ʿAbd al-ʿUzza, or ʿAbd al-ʿUzza son of so-and-so.”"]}},"tuhfa":{},"refs":[{"key":"ابو_بکر_بن_ابی_شیبہ/مسندہ_المطالب_العالیہ","label":"أبو بكر بن أبي شيبة في “مسنده” - المطالب العالية","number":1115}]},{"num":4663,"demo":false,"sanad":"","matn":["عن جابر بن سمرة، أنّ النبي ﷺ قال: (( التمسوا ليلة القدر في العشر الأواخر ))."],"takhrij":"حسن: رواه الإمام أحمد (٢٠٨٠٩)، وابن أبي شيبة (٢/٥١٣).","grade":"حسن","chapter_ar":"باب ما جاء في ليلة القدر أنها في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Imam Ahmad (20809) and Ibn Abi Shaybah (2/513).","chapter_en":"What has been reported that the Night of Decree is in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn Samurah reported that the Prophet ﷺ said: “Seek the Night of Decree in the last ten nights.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":20809},{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":2},{"key":"ahmad","label":"مسند الإمام أحمد","number":20809,"n":20809}]},{"num":4664,"demo":false,"sanad":"","matn":["عن معاذ بن جبل، أنّ رسول اللّٰه ﷺ سئل عن ليلة القدر، فقال: (( هي في العشر الأواخر، أو في الخامسة، أو في الثالثة ))."],"takhrij":"حسن: رواه أحمد (٢٢٠٤٣)، والطبراني في “الكبير” (٢٠/٩٢).","grade":"حسن","chapter_ar":"باب ما جاء في ليلة القدر أنها في العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (22043) and al-Tabarani in al-Kabir (20/92).","chapter_en":"What has been reported that the Night of Decree is in the last ten nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Muʿadh ibn Jabal reported that the Messenger of Allah ﷺ was asked about the Night of Decree, and he said: “It is in the last ten nights, or in the fifth, or in the third.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في “الكبير”","number":20},{"key":"ahmad","label":"مسند الإمام أحمد","number":22043,"n":22043}]},{"num":4665,"demo":false,"sanad":"","matn":["عن عائشة، أنّ رسول اللّه ﷺ قال: (( تحرّوا ليلة القدر في الوتر من العشر الأواخر من رمضان ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠١٧)، ومسلم (١١٦٩).","grade":"متفق عليه","chapter_ar":"باب تحرّي ليلة القدر في أوتار العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2017) and Muslim (1169).","chapter_en":"Seeking the Night of Decree in the odd nights of the last ten","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ said: “Seek the Night of Decree in the odd nights of the last ten of Ramadan.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2017},{"key":"muslim","label":"مسلم","number":1169}]},{"num":4666,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ أنه قال: كان رسولُ اللّٰه ﷺ يعتكفُ العشر الوسط من رمضان، فاعتكف عاماً، حتى إذا كان ليلة إحدى وعشرين، وهي التي يخرجُ فيها من صبحها من اعتكافه، قال: (( من اعتكف معي فليعتكف العشر الأواخر. وقد رأيت هذه الليلة، ثم أُنسيتُها، وقد رأيتني أسجدُ من صبحها في ماء وطين. فالتمسوها في العشر الأواخر، والتمسوها في كلّ وتر )).","قال أبو سعيد: فأمطرت السماءُ تلك الليلة، وكان المسجدُ على عريشٍ، فوكف المسجدُ. قال أبو سعيد: فأبصرتْ عينايَ رسولَ اللّٰه ﷺ انصرف وعلى جبهته وأنفه أثرُ الماء والطين من صبح ليلة إحدى وعشرين."],"takhrij":"متفق عليه: رواه مالك (٩)، والبخاري (٢٠٢٧)، ومسلم (١١٦٧/٢١٦).","grade":"متفق عليه","chapter_ar":"باب تحرّي ليلة القدر في أوتار العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (9), al-Bukhari (2027), and Muslim (1167 no. 216).","chapter_en":"Seeking the Night of Decree in the odd nights of the last ten","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ used to observe spiritual retreat in the middle ten nights of Ramadan. Then one year he did so until the night of the twenty-first — the night after whose morning he would leave his retreat — and he said: “Whoever made retreat with me should continue retreating in the last ten nights. I was shown this night, then I was made to forget it, and I saw myself prostrating in water and mud on its morning. So seek it in the last ten nights, and seek it in every odd night.”","Abu Saʿid said: The sky rained that night, and the mosque had a roof of palm branches, so the mosque leaked. Abu Saʿid said: My eyes saw the Messenger of Allah ﷺ leave, with traces of water and mud on his forehead and nose on the morning of the twenty-first night."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"bukhari","label":"البخاري","number":2027},{"key":"muslim","label":"مسلم","number":1167}]},{"num":4667,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: رأى رجلٌ أنّ ليلة القدر ليلة سبع وعشرين. فقال النبيُّ ﷺ: (( أرى رؤياكم في العشر الأواخر، فاطلبوها في الوتر منها ))."],"takhrij":"صحيح: رواه مسلم (١١٦٥/٢٠٧). ورواه البخاريّ في التعبير (٦٩٩١) بلفظ: أنّ ناساً أُروا ليلة القدر في السبع الأواخر، وأنّ أناساً أُروا أنها في العشر الأواخر، فقال النبيّ ﷺ: (( التمسوها في السبع الأواخر )).","grade":"صحيح","chapter_ar":"باب تحرّي ليلة القدر في أوتار العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1165 no. 207). Al-Bukhari also narrated it in the chapter on dreams (6991) with the wording that some people were shown in dreams that the Night of Decree was in the last seven, and others were shown it was in the last ten, so the Prophet ﷺ said: “Seek it in the last seven.”","chapter_en":"Seeking the Night of Decree in the odd nights of the last ten","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar said: A man saw that the Night of Decree was the night of the twenty-seventh. So the Prophet ﷺ said: “I see your dreams concerning the last ten nights, so seek it in the odd nights among them.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1165},{"key":"ورواہ_البخاری/التعبیر","label":". ورواه البخاريّ في التعبير","number":6991}]},{"num":4668,"demo":false,"sanad":"","matn":["عن أبي بكرة، قال: سمعتُ رسول اللّٰه ﷺ يقول: (( التمسوها في تسع بقين، أو سبع بقين، أو خمس بقين، أو في ثلاث أواخر ليلة ))."],"takhrij":"حسن: رواه الترمذي (٧٩٤)، والإمام أحمد (٢٠٣٧٦)، وأبو داود الطيالسي (٩٢٢)، وصحّحه ابن خزيمة (٢١٧٥)، وزاد بعضهم في آخر الحديث: (( فكان لا يصلي في العشرين إلا كصلاته في سائر السنة، فإذا دخل العشر اجتهد )).","grade":"حسن","chapter_ar":"باب تحرّي ليلة القدر في أوتار العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (794), Ahmad (20376), Abu Dawud al-Tayalisi (922), and authenticated by Ibn Khuzaymah (2175). Some narrations add at the end: “During the first twenty nights, he would not pray except as he normally prayed throughout the year, but when the last ten entered, he strove hard.”","chapter_en":"Seeking the Night of Decree in the odd nights of the last ten","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Abu Bakrah said: I heard the Messenger of Allah ﷺ say: “Seek it when nine remain, or seven remain, or five remain, or in the last three nights.”"]},"buhuth":{"ar":["قال الترمذي: (( حسن صحيح ))."],"en":["Al-Tirmidhi said: “Hasan Sahih.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":794},{"key":"الامام_احمد","label":"الإمام أحمد","number":20376},{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسي","number":922},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2175},{"key":"ahmad","label":"مسند الإمام أحمد","number":20376,"n":20376}]},{"num":4669,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، قال: سئل النبيّ ﷺ عن ليلة القدر، فقال: (( كنتُ أُعلمتُها، ثم انفلتت مني، فالتمسوها في سبعٍ يبقين، أو ثلاثٍ يبقين ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٠٢٨).","grade":"حسن","chapter_ar":"باب تحرّي ليلة القدر في أوتار العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Bazzar in Kashf al-Astar (1028).","chapter_en":"Seeking the Night of Decree in the odd nights of the last ten","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The Prophet ﷺ was asked about the Night of Decree, and he said: “I had been informed of it, then it slipped away from me, so seek it when seven remain, or when three remain.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1028},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1028,"n":1029}]},{"num":4670,"demo":false,"sanad":"","matn":["عن عمر، قال: قال رسول اللّٰه ﷺ: (( التمسوا ليلة القدر في العشر الأواخر من رمضان )).","وزاد البزار: (( وتراً ))."],"takhrij":"حسن: رواه أبو يعلى (١٦٥)، والبزار - كشف الأستار (١٠٢٧).","grade":"حسن","chapter_ar":"باب تحرّي ليلة القدر في أوتار العشر الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Abu Yaʿla (165) and al-Bazzar in Kashf al-Astar (1027).","chapter_en":"Seeking the Night of Decree in the odd nights of the last ten","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["ʿUmar said: The Messenger of Allah ﷺ said: “Seek the Night of Decree in the last ten nights of Ramadan.”","Al-Bazzar added: “in the odd-numbered nights.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":165},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1027},{"key":"sh12520","label":"مسند أبي يعلى","number":165,"n":163}]},{"num":4671,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: كان رسول اللّٰه ﷺ يجاور في رمضان العشر التي في وسط الشهر، فإذا كان حين يمسي من عشرين ليلة تمضي ويستقبل إحدى وعشرين رجع إلى مسكنه، ورجع من كان يجاور معه. وأنه أقام في شهر جاور فيه الليلة التي كان يرجع فيها، فخطب الناس فأمرهم ما شاء اللّٰه، ثم قال: (( كنت أجاور هذه العشر، ثم قد بدا لي أن أجاور هذه العشر الأواخر. فمن كان اعتكف معي فليثبت في معتكفه. وقد أُريت هذه الليلة ثم أُنسيتُها، فابتغوها في العشر الأواخر، وابتغوها في كل وتر، وقد رأيتني أسجد في ماء وطين )).","فاستهلت السماء في تلك الليلة فأمطرت، فوكف المسجد في مصلى النبي ﷺ ليلة إحدى وعشرين، فأبصرت عيني رسول اللّه ﷺ ونظرت إليه انصرف من الصبح ووجهه ممتلئٌ طيناً وماءً."],"takhrij":"متفق عليه: رواه البخاريّ (٢٠١٨)، ومسلم (١١٦٧/٢١٣). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في ليلة القدر أنها كانت ليلة إحدى وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2018) and Muslim (1167 no. 213), and the wording is that of al-Bukhari.","chapter_en":"What has been reported that the Night of Decree was the twenty-first night","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ used to stay in retreat during Ramadan in the middle ten nights of the month. When the evening of the twentieth came and the twenty-first began, he would return to his dwelling, and those with him would also return. Then in one month he stayed in retreat during the night on which he would usually return, and he addressed the people and instructed them as Allah willed, then said: “I had been observing retreat in these ten nights, but it has now become clear to me that I should observe retreat in these last ten nights. So whoever has been in retreat with me should remain in his retreat. I was shown this night, then I was made to forget it, so seek it in the last ten nights, and seek it in every odd night. I also saw myself prostrating in water and mud.”","Then the sky became cloudy that night and it rained, and the mosque leaked in the place where the Prophet ﷺ prayed on the night of the twenty-first. My eyes saw the Messenger of Allah ﷺ, and I looked at him as he left after the dawn prayer with his face covered in mud and water."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2018},{"key":"muslim","label":"مسلم","number":1167}]},{"num":4672,"demo":false,"sanad":"","matn":["عن عبدالله بن أُنيس، أنّ رسولَ اللّٰه ﷺ قال: (( أُريتُ ليلة القدر ثم أُنسيتُها، وأراني صُبحَها أسجدُ في ماء وطين )). قال: فمطرنا ليلة ثلاثٍ وعشرين، فصلّى بنا رسولُ اللّٰه ﷺ، فانصرف وإنَّ أثر الماءِ والطين على جبهته وأنفه. قال: وكان عبدالله بن أُنيس يقول: ثلاثٍ وعشرين."],"takhrij":"صحيح: رواه مسلم (١١٦٨).","grade":"صحيح","chapter_ar":"باب ما جاء في ليلة القدر أنها كانت ليلة ثلاث وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1168).","chapter_en":"What has been reported that the Night of Decree was the twenty-third night","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullah ibn Unays reported that the Messenger of Allah ﷺ said: “I was shown the Night of Decree, then I was made to forget it, and I was shown that on its morning I would prostrate in water and mud.” He said: It rained on the night of the twenty-third, and the Messenger of Allah ﷺ led us in prayer, then left while traces of water and mud were on his forehead and nose. ʿAbdullah ibn Unays used to say: It was the twenty-third."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1168}]},{"num":4673,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أتيتُ وأنا نائم في رمضان، فقيل لي: إنّ الليلة ليلة القدر. قال: فقمتُ وأنا ناعس، فتعلقتُ ببعض أطناب فسطاط رسول اللّٰه ﷺ، فأتيتُ رسول اللّه ﷺ فإذا هو يصلي. قال: فنظرتُ في تلك الليلة، فإذا هي ليلة ثلاث وعشرين."],"takhrij":"حسن: رواه الإمام أحمد (٢٥٤٧، ٢٣٠٢)، والطبراني في الكبير (١١/٢٩٢-٢٩٣).","grade":"حسن","chapter_ar":"باب ما جاء في ليلة القدر أنها كانت ليلة ثلاث وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (2547, 2302) and al-Tabarani in al-Kabir (11/292–293).","chapter_en":"What has been reported that the Night of Decree was the twenty-third night","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas said: While I was asleep in Ramadan, I was told: Tonight is the Night of Decree. So I got up while drowsy and held onto one of the ropes of the tent of the Messenger of Allah ﷺ. I came to the Messenger of Allah ﷺ and found him praying. Then I looked into that night and found that it was the twenty-third night."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":2547},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":11},{"key":"ahmad","label":"مسند الإمام أحمد","number":2547,"n":2547}]},{"num":4674,"demo":false,"sanad":"","matn":["عن عبد اللّٰه أنّ النبيّ ﷺ قال: (( التمسوها في العشر الأواخر من رمضان، ليلة القدر في تاسعة تبقى، في سابعة تبقى، في خامسة تبقى )).","وفي رواية: (( هي في العشر الأواخر، في تسع يمضين، أو في سبع يبقين ))."],"takhrij":"صحيح: رواه البخاريّ (٢٠٢١). والرواية الثانية (٢٠٢٢).","grade":"صحيح","chapter_ar":"باب في ليلة القدر أنها في إحدى وعشرين وثلاث وعشرين وخمس وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2021), and the second wording in (2022).","chapter_en":"What has been reported that the Night of Decree may be the twenty-first, twenty-third, or twenty-fifth","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullah reported that the Prophet ﷺ said: “Seek it in the last ten nights of Ramadan — the Night of Decree when nine remain, when seven remain, when five remain.”","And in another wording: “It is in the last ten nights, when nine have passed, or when seven remain.”"]},"intro":{"ar":["وقوله: (( فرُفعت )) أي رُفع علم تلك الليلة بعد أن علمها النبي ﷺ وأراد أن يخبر بها أصحابه، ولذا قال: (( فالتمسوها في كذا وكذا )). ولا يصح من قال: رفعت ليلة القدر إلى الأبد ولا تعود."],"en":["The phrase “it was lifted” means that knowledge of that specific night was lifted after the Prophet ﷺ had known it and intended to tell his Companions, which is why he said: “So seek it in such-and-such nights.” It is not correct to say that the Night of Decree itself was removed forever and will never return."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2021},{"key":"والروایہ_الثانیہ","label":". والرواية الثانية","number":2022}]},{"num":4675,"demo":false,"sanad":"","matn":["عن عُبادة بن الصّامت، قال: خرج النبيّ ﷺ ليخبرنا بليلة القدر، فتلاحى رجلان من المسلمين، فقال: (( خرجتُ لأخبركم بليلة القدر، فتلاحى فلانٌ وفلانٌ، فرُفعت، وعسى أن يكون خيراً لكم، فالتمسوها في التاسعة، والسابعة، والخامسة ))."],"takhrij":"صحيح: رواه البخاري (٢٠٢٣). ورواه أبو داود الطيالسي (٥٧٧) بلفظ: (( فاختُلجت مني، فالتمسوها في العشر الأواخر، في سابعة تبقى، أو تاسعة تبقى، أو خامسة تبقى )).","grade":"صحيح","chapter_ar":"باب في ليلة القدر أنها في إحدى وعشرين وثلاث وعشرين وخمس وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2023). Abu Dawud al-Tayalisi narrated it with the wording: “It was pulled away from me, so seek it in the last ten nights, when seven remain, or when nine remain, or when five remain.”","chapter_en":"What has been reported that the Night of Decree may be the twenty-first, twenty-third, or twenty-fifth","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["ʿUbadah ibn al-Samit said: The Prophet ﷺ came out to inform us about the Night of Decree, but two Muslim men argued, so he said: “I came out to inform you about the Night of Decree, but so-and-so and so-and-so argued, so its knowledge was lifted, and perhaps that is better for you. So seek it in the ninth, the seventh, and the fifth.”"]},"buhuth":{"ar":["قوله: (( فتلاحى فلان وفلان )) من الملاحاة، وهي المشاجرة، ورفع الأصوات والمراجعة بالقول الذي لا يصلح على حال الغضب، وذلك شؤم.","قوله: (( فرفعت )) فيه إشارةٌ إلى أنها لم ترفع أصلاً، وإنما الذي رُفع هو علمُ ليلة القدر فقط في تلك السنة.","وقوله: (( فعسى أن يكون خيراً )) وذلك بأن يقوم المسلم العشرَ الأواخرَ كلها، ويجتهد فيها ليدرك ليلة القدر."],"en":["The phrase “two men argued” refers to quarreling, raising voices, and exchanging words in anger, and that is something blameworthy.","The phrase “its knowledge was lifted” indicates that the night itself was not removed; rather, knowledge of its exact identity for that year was removed.","And “perhaps that is better for you” means that a Muslim will then strive throughout all the last ten nights and thus attain the Night of Decree."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2023},{"key":"ورواہ_ابو_داود_الطیالسی","label":". ورواه أبو داود الطيالسي","number":577}]},{"num":4676,"demo":false,"sanad":"","matn":["عن أنس، أنّ النبيَّ ﷺ خرج علينا في رمضان، فقال: (( إنّي أُريتُ هذه الليلة في رمضان، حتى تلاحى رجلان، فرُفعت، فالتمسوها في التاسعة والسابعة والخامسة ))."],"takhrij":"صحيح: رواه مالك (١٣).","grade":"صحيح","chapter_ar":"باب في ليلة القدر أنها في إحدى وعشرين وثلاث وعشرين وخمس وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Malik (13).","chapter_en":"What has been reported that the Night of Decree may be the twenty-first, twenty-third, or twenty-fifth","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ came out to us in Ramadan and said: “I was shown this night in Ramadan, then two men argued, so knowledge of it was lifted. Therefore seek it in the ninth, the seventh, and the fifth.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":13}]},{"num":4677,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، قال: قال رسول اللّٰه ﷺ: (( التمسوها في العشر الأواخر من رمضان، والتمسوها في التاسعة، والسابعة، والخامسة )). قال: قلت: يا أبا سعيد، إنكم أعلم بالعد منا. قال: أجل، نحن أحقّ بذلك منكم. قال: قلت: ما التاسعة والسابعة والخامسة؟ قال: إذا مضت واحدة وعشرون فالتي تليها التاسعة، فإذا مضت ثلاث وعشرون فالتي تليها السابعة، فإذا مضت خمس وعشرون فالتي تليها الخامسة."],"takhrij":"صحيح: رواه مسلم (١١٦٧/٢١٧)، وأبو داود (١٣٨٣)، واللفظ له.","grade":"صحيح","chapter_ar":"باب في ليلة القدر أنها في إحدى وعشرين وثلاث وعشرين وخمس وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1167 no. 217) and Abu Dawud (1383), and the wording is that of Abu Dawud.","chapter_en":"What has been reported that the Night of Decree may be the twenty-first, twenty-third, or twenty-fifth","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ said: “Seek it in the last ten nights of Ramadan, and seek it in the ninth, the seventh, and the fifth.” I said: O Abu Saʿid, you know the counting better than we do. He said: Yes, we have more right to that than you. I said: What is the ninth, the seventh, and the fifth? He said: When twenty-one have passed, then the night after is the ninth remaining. When twenty-three have passed, then the night after is the seventh remaining. And when twenty-five have passed, then the night after is the fifth remaining."]},"buhuth":{"ar":["وأما لفظ مسلم ففي أوله ذكر الاعتكاف."],"en":["As for the wording in Muslim, it begins with mention of spiritual retreat."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1167},{"key":"abudawud","label":"أبو داود","number":1383}]},{"num":4678,"demo":false,"sanad":"","matn":["عن عبدالله بن مسعود، قال: سئل النبيّ ﷺ عن ليلة القدر، فقال: (( كنتُ أعلمتها، ثم انفلتت مني، فاطلبوها في سبعٍ يبقين، أو ثلاثٍ يبقين ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٠٢٨).","grade":"حسن","chapter_ar":"باب إنّها في ثلاث وعشرين أو سبع وعشرين","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by al-Bazzar in Kashf al-Astar (1028).","chapter_en":"What has been reported that it may be the twenty-third or the twenty-seventh","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: The Prophet ﷺ was asked about the Night of Decree, and he said: “I had known it, then it slipped away from me, so seek it when seven remain, or when three remain.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1028},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1028,"n":1029}]},{"num":4679,"demo":false,"sanad":"","matn":["عن ابن عمر:","أن رجالًا من أصحاب رسول الله ﷺ أُروا ليلة القدر في المنام في السبع الأواخر، فقال رسول الله ﷺ:","«إِنِّي أَرَى رُؤْيَاكُمْ قَدْ تَوَاطَأَتْ فِي السَّبْعِ الْأَوَاخِرِ، فَمَنْ كَانَ مُتَحَرِّيَهَا فَلْيَتَحَرَّهَا فِي السَّبْعِ الْأَوَاخِرِ»."],"takhrij":"متفق عليه: رواه مالك (١٤)، والبخاري (٢٠١٥)، ومسلم (١١٦٥/٢٠٥).","grade":"متفق عليه","chapter_ar":"باب تحرّي ليلة القدر في السّبع الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (14), al-Bukhārī (2015), and Muslim (1165/205).","chapter_en":"Seeking the Night of Decree in the last seven nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar reported:","Some men among the Companions of the Messenger of Allah ﷺ were shown in their dreams that Laylat al-Qadr was among the last seven nights.","The Messenger of Allah ﷺ said:","“I see that your dreams agree concerning the last seven nights. Therefore, whoever seeks it should seek it during the last seven nights.”"]},"buhuth":{"ar":["وقوله: «السبع الأواخر» الظاهر أن المراد به أواخر الشهر، وأن ليلة القدر تكون في العشر الأواخر، ولا سيما أوتارها، من غير تعيين ليلة واحدة بعينها. فقد تكون وقعت في عهد النبي ﷺ في ليلة من ليالي الوتر في العشر الأواخر، ولا يلزم من ذلك أن تبقى في تلك الليلة نفسها إلى يوم القيامة."],"en":["The expression “the last seven nights” apparently refers to the final part of the month. Laylat al-Qadr is sought within the last ten nights, especially their odd nights, without permanently specifying one particular night. It may have occurred during the Prophet’s ﷺ lifetime on a particular odd night of the last ten, but this does not necessarily mean that it remains fixed on that exact night until the Day of Resurrection."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14},{"key":"bukhari","label":"البخاري","number":2015},{"key":"muslim","label":"مسلم","number":1165}]},{"num":4680,"demo":false,"sanad":"","matn":["عن بلال مؤذن النبيّ ﷺ أنه قال: (( إنّها في السبع في العشر الأواخر ))."],"takhrij":"صحيح: رواه البخاريّ (٤٤٧٠).","grade":"صحيح","chapter_ar":"باب تحرّي ليلة القدر في السّبع الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (4470).","chapter_en":"Seeking the Night of Decree in the last seven nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Bilal, the Prophet’s caller to prayer, said: “It is within the seven among the last ten nights.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4470}]},{"num":4681,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، قال: قال رسول اللّه ﷺ: (( اطلبوا ليلة القدر في العشر الأواخر، فإن غُلِبتم فلا تُغلبوا على السبع البواقي ))."],"takhrij":"حسن: رواه عبد اللّه بن أحمد (١١١١).","grade":"حسن","chapter_ar":"باب تحرّي ليلة القدر في السّبع الأواخر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by ʿAbdullah ibn Ahmad (1111).","chapter_en":"Seeking the Night of Decree in the last seven nights","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ said: “Seek the Night of Decree in the last ten nights, and if you are overcome, then do not allow yourselves to be overcome regarding the last seven remaining nights.”"]}},"tuhfa":{},"refs":[{"key":"عبد_اللہ_بن_احمد","label":"عبد اللّه بن أحمد","number":1111},{"key":"ahmad","label":"مسند الإمام أحمد","number":1111,"n":1111}]},{"num":4682,"demo":false,"sanad":"","matn":["عن زرّ بن حُبيش قال: سألت أُبَيَّ بن كعب رضي اللّٰه عنه، فقلت: إنَّ أخاك ابن مسعود يقول: من يَقُم الحوْلَ يُصِبْ ليلة القدر. فقال: رحمه الله، أراد أن لا يتكل الناس. أما إنّه قد علم أنها في رمضان، وأنّها في العشر الأواخر، وأنّها ليلة سبع وعشرين. ثم حلف لا يستثني أنّها ليلةُ سبع وعشرين. فقلتُ: بأيّ شيء تقول ذلك يا أبا المنذر؟ قال: بالعلامة أو بالآية التي أخبرنا رسول اللّٰه ﷺ أنها تطلع يومئذ لا شعاعَ لها."],"takhrij":"صحيح: رواه مسلم (٧٦٢/٢٢٠).","grade":"صحيح","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (762 no. 220).","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Zirr ibn Hubaysh said: I asked Ubayy ibn Kaʿb, may Allah be pleased with him, and said: Your brother Ibn Masʿud says: Whoever stands through the whole year will attain the Night of Decree. He said: May Allah have mercy on him; he wanted the people not to become complacent. But he certainly knew that it is in Ramadan, that it is in the last ten nights, and that it is the night of the twenty-seventh. Then he swore, without making an exception, that it is the night of the twenty-seventh. I said: By what do you say that, O Abu al-Mundhir? He said: By the sign or indication that the Messenger of Allah ﷺ told us, that on its morning the sun rises without rays."]},"intro":{"ar":["وقوله: (( شِقِّ جفنة )) الشق: هو النصف، والجفنة: القصعة. قال القاضي عياض: فيه إشارة إلى أنها تكون في أواخر الشهر؛ لأنّ القمر لا يكون كذلك عند طلوعه إلا في أواخر الشهر.","وقوله: (( عليك بالسابعة )) أي بعد مضي سبع وعشرين."],"en":["The phrase “half of a bowl” means half of it, and the bowl here means a large dish. Al-Qadi ʿIyad said: This indicates that it is in the latter part of the month, because the moon only appears in that form at its rising near the end of the month.","The phrase “hold to the seventh” means the seventh remaining night after the twenty-seventh."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":762}]},{"num":4683,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: تذاكرنا ليلة القدر عند رسول اللّٰه ﷺ، فقال: (( أيكم يذكرُ حين طلع القمرُ، وهو مثلُ شِقِّ جفنة ))."],"takhrij":"صحيح: رواه مسلم (١١٧٠).","grade":"صحيح","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1170).","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Hurairah said: We were discussing the Night of Decree in the presence of the Messenger of Allah ﷺ, and he said: “Which of you remembers when the moon rose, and it was like half of a bowl?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1170}]},{"num":4684,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن رسول اللّٰه ﷺ قال في ليلة القدر: (( إنّها ليلة سابعة أو ليلة تاسعة وعشرين، وإنّ الملائكة تلك الليلة في الأرض أكثر من عدد الحصى ))."],"takhrij":"حسن: رواه أحمد (١٠٧٣٤)، وأبو داود الطيالسي (٢٦٦٨)، والبزار - كشف الأستار (١٠٣٠).","grade":"حسن","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (10734), Abu Dawud al-Tayalisi (2668), and al-Bazzar in Kashf al-Astar (1030).","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Hurairah reported that the Messenger of Allah ﷺ said concerning the Night of Decree: “It is the twenty-seventh night, or the twenty-ninth night, and the angels on that night on the earth are more numerous than the pebbles.”"]}},"tuhfa":{},"refs":[{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسي","number":2668},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1030},{"key":"ahmad","label":"مسند الإمام أحمد","number":10734,"n":10734},{"key":"tayalisi","label":"مسند أبي داود الطيالسي","number":2668,"n":2668}]},{"num":4685,"demo":false,"sanad":"","matn":["عن رجل من أصحاب النبي ﷺ، عن النبيّ ﷺ قال: (( نظرتُ إلى القمر صبيحةَ ليلة القدر، فرأيته كأنه فِلْقُ جفنة ))."],"takhrij":"صحيح: رواه أحمد (٢٣١٢٩).","grade":"صحيح","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (23129).","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ reported from the Prophet ﷺ that he said: “I looked at the moon on the morning after the Night of Decree, and I saw it as though it were half of a bowl.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23129,"n":23129}]},{"num":4686,"demo":false,"sanad":"","matn":["عن معاوية، عن النبيّ ﷺ في ليلة القدر، قال: (( ليلة القدر ليلة سبع وعشرين ))."],"takhrij":"صحيح: رواه أبو داود (١٣٨٦).","grade":"صحيح","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1386).","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Muʿawiyah reported from the Prophet ﷺ concerning the Night of Decree that he said: “The Night of Decree is the night of the twenty-seventh.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1386}]},{"num":4687,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: قال رسول اللّٰه ﷺ: (( من كان متحريها، فليتحرَّها ليلة سبع وعشرين )).","وقال: (( تحرّوها ليلة سبع وعشرين )) يعني ليلة القدر."],"takhrij":"صحيح: رواه الإمام أحمد (٤٨٠٨)، وأبو داود الطيالسي (٢٠٠٠). ورواه مالك، ومن طريقه مسلم (١١٦٥/٢٠٦) ولفظه: (( تحروا ليلة القدر في السبع الأواخر )).","grade":"صحيح","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (4808) and Abu Dawud al-Tayalisi (2000). Malik also narrated it, and through him Muslim (1165 no. 206), with the wording: “Seek the Night of Decree in the last seven nights.”","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Whoever seeks it should seek it on the night of the twenty-seventh.”","And he also said: “Seek it on the night of the twenty-seventh,” meaning the Night of Decree."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":4808},{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسي","number":2000},{"key":"ومن_طریقہ_مسلم","label":"ومن طريقه مسلم","number":1165},{"key":"ahmad","label":"مسند الإمام أحمد","number":4808,"n":4808}]},{"num":4688,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ رجلاً أتى النبيَّ ﷺ فقال: يا نبي الله، إنّي شيخ كبير عليل يشقّ عليّ القيام، فأمرني بليلة لعلّ اللّٰه يوفقني فيها ليلة القدر. قال: (( عليك بالسابعة ))."],"takhrij":"صحيح: رواه أحمد (٢١٤٩)، والطبراني في الكبير (١١/٣١١)، والبيهقي (٤/٣١٣).","grade":"صحيح","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (2149), al-Tabarani in al-Kabir (11/311), and al-Bayhaqi (4/313).","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas reported that a man came to the Prophet ﷺ and said: O Prophet of Allah, I am an elderly sick man, and standing in prayer is difficult for me, so direct me to a night in which perhaps Allah will allow me to attain the Night of Decree. He said: “You should hold to the seventh.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":11},{"key":"البیہقی","label":"البيهقي","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":2149,"n":2149}]},{"num":4689,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، قال: كان عمر يدعوني مع أصحاب محمد ﷺ، فيقول لي: لا نتكلم حتى يتكلموا. قال: فدعاهم، فسألهم عن ليلة القدر، فقال: أرأيتم قول رسول اللّٰه ﷺ: (( التمسوها في العشر الأواخر ))، أيَّ ليلة ترونها؟ فقال بعضهم: ليلة إحدى، وقال بعضهم: ليلة ثلاث، وقال آخر: خمس، وأنا ساكت. قال: فقال: ما لك لا تتكلم؟ قال: قلت: إن أذنت لي يا أمير المؤمنين تكلمت. قال: فقال: ما أرسلتُ إليك إلا لتتكلم. قال: فقلت: أحدثكم برأيي؟ قال: من ذلك نسألك. قال: فقلت: السبع. رأيتُ اللّٰه عزّ وجلّ ذكر سبع سماوات، ومن الأرض سبعاً، وخلق الإنسان من سبع، ونبت الأرض سبع. قال: فقال: هذا أخبرتني ما أعلم، أرأيت ما لا أعلم، معنى قولك: نبت الأرض من سبع؟ قال: فقلت: إنّ اللّٰه يقول: ( ثُمَّ شَقَقْنَا الْأَرْضَ شَقًّا ۝ فَأَنْبَتْنَا فِيهَا حَبًّا ۝ وَعِنَبًا وَقَضْبًا ۝ وَزَيْتُونًا وَنَخْلًا ۝ وَحَدَائِقَ غُلْبًا ۝ وَفَاكِهَةً وَأَبًّا ) [سورة عبس: ٢٦-٣١]. والأب: نبت الأرض مما تأكله الدواب ولا يأكله الناس. قال: فقال عمر: أعجزتم أن تقولوا كما قال هذا الفتى الذي لم تجتمع شؤون رأسه بعد؟ إني والله ما أرى القول إلا كما قلت. وقال: قد كنتُ أمرتُك أن لا نتكلم حتى يتكلموا، وإني آمرك أن تتكلم معهم."],"takhrij":"حسن: رواه أحمد (٨٥)، والبزار (٢١٠)، وأبو يعلى (١٦٥)، وصححه ابن خزيمة (٢١٧٢)، والسياق لابن خزيمة.","grade":"حسن","chapter_ar":"باب من قال: ليلة القدر في السابع والعشرين من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (85), al-Bazzar (210), Abu Yaʿla (165), and authenticated by Ibn Khuzaymah (2172), and the wording is from Ibn Khuzaymah.","chapter_en":"Those who said that the Night of Decree is the twenty-seventh of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب ما جاء في فضل ليلة القدر واجتهاد النبي ﷺ فيها","group_en":"Collected chapters on what has been reported regarding the virtue of Laylat al-Qadr and the Prophet’s striving in it","part_no":15,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: ʿUmar used to call me together with the Companions of Muhammad ﷺ, and he would say to me: We will not speak until they speak. He said: He called them and asked them about the Night of Decree. He said: What do you think about the statement of the Messenger of Allah ﷺ, “Seek it in the last ten nights” — which night do you think it is? Some of them said: the first, others said: the third, and another said: the fifth, while I remained silent. Then he said: Why are you not speaking? I said: If you permit me, O Commander of the Believers, I will speak. He said: I only sent for you so that you would speak. I said: Shall I tell you my view? He said: That is what we are asking you for. I said: It is the seventh. I saw that Allah, the Mighty and Exalted, mentioned seven heavens, and from the earth seven, and created man from seven, and caused the earth to grow seven things. He said: This you have told me is something I know, but what about what I do not know — what do you mean by the earth growing seven things? I said: Allah says: “Then We split the earth in clefts, and caused grain to grow in it, and grapes and herbage, and olives and palm trees, and dense gardens, and fruits and pasture” [Surah ʿAbasa: 26–31]. And pasture means the vegetation of the earth that animals eat and people do not eat. Then ʿUmar said: Were you unable to say as this young man said, whose hair has not yet fully matured? By Allah, I see the view only as you said. And he said: I had told you not to speak until they spoke, but now I order you to speak with them."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"أحمد","number":85},{"key":"البزار","label":"البزار","number":210},{"key":"ابو_یعلی","label":"أبو يعلى","number":165},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2172}]},{"num":4690,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ رسول اللّٰه ﷺ كان إذا اعتكف طرح له فراشُه وسريره إلى أسطوانة التوبة مما يلي القبلة، ثم يستند إليها."],"takhrij":"حسن: رواه ابن خزيمة (٢٢٣٦)، والطبراني في “الكبير” (١٢/٣٨٥)، و”الأوسط” (٨٠٧١).","grade":"حسن","chapter_ar":"باب اعتكاف النبي ﷺ عند أسطوانة التوبة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Khuzaymah (2236), al-Tabarani in al-Kabir (12/385), and al-Awsat (8071).","chapter_en":"The Prophet’s spiritual retreat near the Pillar of Repentance","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar reported that when the Messenger of Allah ﷺ went into spiritual retreat, his bedding and couch would be placed for him near the Pillar of Repentance on the side facing the direction of prayer, and he would lean against it."]},"intro":{"ar":["وأسطوانة التوبة: هي التي شدّ أبو لبابة بن عبد المنذر عليها، وهي على غير القبلة، كما قاله ابن خزيمة."],"en":["The Pillar of Repentance is the pillar to which Abu Lubabah ibn ʿAbd al-Mundhir tied himself, and it is not directly on the side of the direction of prayer, as Ibn Khuzaymah stated."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2236},{"key":"الطبرانی/الکبیر","label":"الطبراني في “الكبير”","number":12},{"key":"الاوسط","label":"”الأوسط”","number":8071}]},{"num":4691,"demo":false,"sanad":"","matn":["عن أبي سلمة قال: انطلقتُ إلى أبي سعيد الخدري، فقلت: ألا تخرج بنا إلى النخل نتحدث؟ فخرج، فقال: قلت: حدّثني ما سمعتَ من النبيِّ ﷺ في ليلة القدر؟ قال: اعتكف رسولُ اللّٰه ﷺ العشر الأول من رمضان، واعتكفنا معه، فأتاه جبريل، فقال: إنّ الذي تطلب أمامك. فاعتكف العشر الأوسط، فاعتكفنا معه، فأتاه جبريل فقال: إنّ الذي تطلب أمامك. فقام النبيُّ ﷺ خطيباً صبيحة عشرين من رمضان، فقال: (( من اعتكف مع النبيّ ﷺ فليرجع، فإنّي أُريتُ ليلة القدر وإني نُسِّيتها، وإنّها في العشر الأواخر في وتر، وإنّي رأيتُ كأني أسجُد في طين وماء )). وكان سقفُ المسجد جريد النخل، وما نرى في السماء شيئاً، فجاءت قزعةٌ فأُمطرنا، فصلّى بنا النبيُّ ﷺ حتى رأيتُ أثر الطين والماء على جبهة رسول اللّٰه ﷺ وأرنبته، تصديقَ رؤياه."],"takhrij":"متفق عليه: رواه البخاريّ (٨١٣)، ومسلم (١١٦٧/٢١٦).","grade":"متفق عليه","chapter_ar":"باب اعتكاف النبي ﷺ شهر رمضان كاملاً طلباً لليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (813) and Muslim (1167 no. 216).","chapter_en":"The Prophet’s retreat through Ramadan seeking the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abu Salamah said: I went to Abu Saʿid al-Khudri and said: Will you come out with us to the date palms so we may talk? So he came out, and I said: Tell me what you heard from the Prophet ﷺ concerning the Night of Decree. He said: The Messenger of Allah ﷺ observed spiritual retreat during the first ten of Ramadan, and we observed retreat with him. Then Jibril came to him and said: What you are seeking is ahead of you. So he observed retreat in the middle ten, and we observed retreat with him. Then Jibril came to him and said: What you are seeking is ahead of you. Then the Prophet ﷺ stood and addressed the people on the morning of the twentieth of Ramadan and said: “Whoever has been in retreat with the Prophet ﷺ should return, for I was shown the Night of Decree and then made to forget it. It is in the last ten nights, in an odd-numbered night, and I saw myself prostrating in mud and water.” The roof of the mosque was made of palm branches, and there was nothing visible in the sky. Then a cloud came and it rained on us, and the Prophet ﷺ led us in prayer until I saw traces of mud and water on the forehead and nose-tip of the Messenger of Allah ﷺ, confirming his vision."]},"intro":{"ar":["قوله: (( أُريتُ ليلة القدر )) فيه إشارة إلى الرؤية المنامية.","وقد تحققت الرؤية في تلك السنة في ليلة الحادية والعشرين كما ذكر أبو سعيد الخدري رضي اللّٰه عنه.","قوله: (( في قبّة تركية )) منسوبة إلى الترك، وهي قبة صغيرة.","وقوله: (( على سُدَّتها )) السدة قيل: هي ظلة على الباب لتقيه من المطر، وقيل: هي الباب نفسه، وقيل: هي الساحة."],"en":["His statement “I was shown the Night of Decree” indicates a dream vision.","That vision was fulfilled in that year on the twenty-first night, as Abu Saʿid al-Khudri, may Allah be pleased with him, mentioned.","The phrase “in a Turkish-style tent” means a small dome-like tent attributed to that people.","And “at its doorway” has been explained as a shade over the door to protect from rain, or the door itself, or the open entrance area."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":813},{"key":"muslim","label":"مسلم","number":1167}]},{"num":4692,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، قال: إن رسول اللّٰه ﷺ اعتكف العشر الأول من رمضان، ثم اعتكف العشر الأوسط في قبّة تركية على سُدَّتها حصير. قال: فأخذ الحصير بيده فنحّاها في ناحية القبة، ثم أطلع رأسه فكلّم الناس فدنوا منه، فقال: (( إنّي أعتكف العشر الأول ألتمس هذه الليلة، ثم اعتكفت العشر الأوسط، ثم أُتيتُ فقيل لي: إنّها في العشر الأواخر، فمن أحبّ منكم أن يعتكف فليعتكف )).","فاعتكف الناس معه. قال: (( وإنّي أُريتُها ليلة وتر، وإنّي أسجُد صبيحتها في طين وماء )). فأصبح من ليلة إحدى وعشرين، وقد قام إلى الصبح، فمطرت السماء، فوكف المسجد، فأبصرتُ الطين والماء. فخرج حين فرغ من صلاة الصبح وجبينه وروثة أنفه فيهما الطين والماء، وإذا هي ليلة إحدى وعشرين من العشر الأواخر."],"takhrij":"صحيح: رواه مسلم (١١٦٧/٢١٥).","grade":"صحيح","chapter_ar":"باب اعتكاف النبي ﷺ شهر رمضان كاملاً طلباً لليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1167 no. 215).","chapter_en":"The Prophet’s retreat through Ramadan seeking the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ observed retreat during the first ten of Ramadan, then observed retreat during the middle ten in a small Turkish-style tent whose doorway was covered with a mat. He said: He took the mat in his hand and moved it to the side of the tent, then he put his head out and spoke to the people, and they came near him. He said: “I observed retreat during the first ten seeking this night, then I observed retreat during the middle ten, then I was told that it is in the last ten. So whoever among you wishes to observe retreat, let him do so.”","So the people observed retreat with him. He said: “I was shown that it is an odd-numbered night, and that I would prostrate on its morning in mud and water.” Then morning came after the twenty-first night, and he had stood for the dawn prayer. The sky rained and the mosque leaked. I saw the mud and water, and he came out after finishing the dawn prayer with mud and water on his forehead and the tip of his nose. And that was the twenty-first night of the last ten."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1167}]},{"num":4693,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، أنه قال: كان رسولُ اللّٰه ﷺ يعتكفُ العشر الوسط من رمضان، فاعتكف عاماً، حتى إذا كان ليلة إحدى وعشرين، وهي الليلة التي يخرج فيها من صبحها من اعتكافه، قال: (( من اعتكف معي فليعتكف العشر الأواخر، وقد رأيتُ هذه الليلة ثم أُنسيتُها، وقد رأيتُني أسجُد من صبحها في ماء وطين. فالتمسوها في العشر الأواخر، والتمسوها في كلّ وتر )).","قال أبو سعيد: فأمطرت السماءُ تلك الليلة، وكان المسجدُ على عريش، فوكف المسجدُ. قال أبو سعيد: فأبصرتْ عينايّ رسولَ اللّٰه ﷺ انصرف وعلى جبهته وأنفه أثرُ الماء والطين من صبح ليلة إحدى وعشرين."],"takhrij":"متفق عليه: رواه مالك (٩)، والبخاريّ (٢٠٢٧) و(٨١٣)، ومسلم (١١٦٧/٢١٦).","grade":"متفق عليه","chapter_ar":"باب اعتكاف العشرين الأخيرة طلباً لليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (9), al-Bukhari (2027 and 813), and Muslim (1167 no. 216).","chapter_en":"Retreating in the last twenty nights seeking the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ used to observe retreat in the middle ten of Ramadan. Then one year he observed retreat until the night of the twenty-first — the night after whose morning he would leave his retreat — and he said: “Whoever has been in retreat with me should remain in retreat during the last ten. I saw this night, then I was made to forget it, and I saw myself prostrating on its morning in mud and water. So seek it in the last ten nights, and seek it in every odd night.”","Abu Saʿid said: The sky rained that night, and the mosque had a roof of palm branches, so the mosque leaked. Abu Saʿid said: My eyes saw the Messenger of Allah ﷺ leave while traces of water and mud were on his forehead and nose on the morning of the twenty-first night."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"bukhari","label":"البخاريّ","number":2027},{"key":"و","label":"و","number":813},{"key":"muslim","label":"مسلم","number":1167}]},{"num":4694,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: كان رسول اللّٰه ﷺ يجاور في رمضان العشر التي في وسط الشهر، فإذا كان حين يُمسي من عشرين ليلة تمضي ويستقبل إحدى وعشرين، رجع إلى مسكنه، ورجع من كان يجاور معه، وأنه أقام في شهرٍ جاور فيه الليلة التي كان يرجع فيها، فخطب الناس، فأمرهم ما شاء الله، ثم قال: (( كنتُ أجاور هذه العشر، ثم قد بدا لي أن أجاور هذه العشر الأواخر، فمن كان اعتكف معي فليثبت في معتكفه، وقد أُريتُ هذه الليلة، ثم أُنسيتها، فابتغوها في كلّ وتر، وقد رأيتُني أسجُد في ماء وطين )).","فاستهلت السماء في تلك الليلة فأمطرت، فوكف المسجدُ في مصلّى النبيّ ﷺ ليلة إحدى وعشرين. فأبصرتْ عيني رسولَ الله ﷺ ونظرتُ إليه انصرف من الصبح ووجهه ممتلئٌ طيناً وماء."],"takhrij":"متفق عليه: رواه البخاري (٢٠١٨)، ومسلم (١١٦٧/٢١٤). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الاعتكاف في العشر الوسط، ثم نقله إلى العشر الأواخر من أجل طلب ليلة القدر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2018) and Muslim (1167 no. 214), and the wording is that of al-Bukhari.","chapter_en":"Retreat in the middle ten, then moving it to the last ten in search of the Night of Decree","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: The Messenger of Allah ﷺ used to stay in retreat in Ramadan during the ten nights in the middle of the month. When the evening of the twentieth came and the twenty-first began, he returned to his dwelling, and those who had remained with him also returned. Then in one month he stayed in retreat during the night on which he would normally have returned, and he addressed the people and instructed them as Allah willed, then said: “I used to remain in retreat during these ten, but it has now become clear to me that I should remain in retreat during these last ten. So whoever has observed retreat with me should remain in his place of retreat. I was shown this night, then I was made to forget it, so seek it in every odd night, and I saw myself prostrating in mud and water.”","Then the sky became clouded that night and it rained, and the mosque leaked in the place where the Prophet ﷺ prayed on the night of the twenty-first. My eyes saw the Messenger of Allah ﷺ and I looked at him as he left after dawn with his face covered in mud and water."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2018},{"key":"muslim","label":"مسلم","number":1167}]},{"num":4695,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر، قال: كان رسول اللّٰه ﷺ يعتكف العشر الأواخر من رمضان. قال نافع: وقد أراني عبد الله رضي اللّٰه عنه المكان الذي كان يعتكف فيه رسول اللّٰه ﷺ من المسجد."],"takhrij":"متفق عليه: رواه البخاري (٢٠٢٥)، ومسلم (١١٧١/٢).","grade":"متفق عليه","chapter_ar":"باب اعتكاف العشر الأواخر من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2025) and Muslim (1171 no. 2).","chapter_en":"Retreat in the last ten nights of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ used to observe retreat during the last ten of Ramadan. Nafiʿ said: ʿAbdullah showed me the place in the mosque where the Messenger of Allah ﷺ used to observe retreat."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2025},{"key":"muslim","label":"مسلم","number":1171}]},{"num":4696,"demo":false,"sanad":"","matn":["عن عائشة، أنّ النبيَّ ﷺ كان يعتكف العشر الأواخر من رمضان حتى توفّاه اللّٰه تعالى، ثم اعتكف أزواجُه من بعده."],"takhrij":"متفق عليه: رواه البخاريّ (٢٠٢٦)، ومسلم (١١٧٢/٥).","grade":"متفق عليه","chapter_ar":"باب اعتكاف العشر الأواخر من رمضان","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2026) and Muslim (1172 no. 5).","chapter_en":"Retreat in the last ten nights of Ramadan","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah reported that the Prophet ﷺ used to observe retreat during the last ten of Ramadan until Allah the Exalted took his soul, then his wives observed retreat after him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2026},{"key":"muslim","label":"مسلم","number":1172}]},{"num":4697,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: كان النبيُّ ﷺ يعتكفُ في كلِّ رمضان عشرة أيام، فلما كان العام الذي قُبض فيه اعتكف عشرين يوماً."],"takhrij":"صحيح: رواه البخاريّ (٢٠٤٤).","grade":"صحيح","chapter_ar":"باب ضمّ العشر الوسط إلى الأخير لزيادة الأجر","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2044).","chapter_en":"Joining the middle ten to the last ten for increased reward","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abu Hurairah said: The Prophet ﷺ used to observe retreat for ten days in every Ramadan, but in the year in which he passed away, he observed retreat for twenty days."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2044}]},{"num":4698,"demo":false,"sanad":"","matn":["عن عائشة: أنّ رسول اللّٰه ﷺ ذكر أن يعتكف العشر الأواخر من رمضان، فاستأذنته عائشة فأذن لها. وسألتْ حفصةُ عائشةَ أن تستأذن لها، ففعلت. فلما رأت ذلك زينب بنت جحش أمرتْ ببناء فبُني لها. قالت: وكان رسول اللّٰه ﷺ إذا صلّى انصرف إلى بنائه، فبصر بالأبنية فقال: (( ما هذا؟ )). قالوا: بناء عائشة وحفصة وزينب. فقال رسول اللّٰه ﷺ: (( آلبر أردن بهذا؟ ما أنا بمعتكف )). فرجع، فلما أفطر اعتكف عشراً من شوال."],"takhrij":"متفق عليه: رواه البخاريّ (٢٠٤٥)، ومسلم (١١٧٢/٦). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب قضاء النبي اعتكاف رمضان في شوال","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2045) and Muslim (1172 no. 6), and the wording is that of al-Bukhari.","chapter_en":"The Prophet making up his Ramadan retreat in Shawwal","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ intended to observe retreat during the last ten of Ramadan. ʿA’ishah sought his permission, and he gave her permission. Then Hafsah asked ʿA’ishah to seek permission for her, and she did so. When Zaynab bint Jahsh saw that, she ordered a structure to be built for her, and it was built. ʿA’ishah said: When the Messenger of Allah ﷺ prayed, he would go to his place of retreat, then he saw the structures and said: “What is this?” They said: The structures of ʿA’ishah, Hafsah, and Zaynab. The Messenger of Allah ﷺ said: “Is it righteousness that they intended by this? I am not going into retreat.” So he returned, and when Ramadan ended, he observed retreat for ten days in Shawwal."]},"buhuth":{"ar":["وفي رواية لمسلم: (( حتى اعتكف في العشر الأوّل من شوال ))."],"en":["In a narration of Muslim: “until he observed retreat during the first ten of Shawwal.”"]},"intro":{"ar":["وليس في الحديث ما يدل على وجوب القضاء على من خرج من الاعتكاف وكان متطوعاً، بخلاف النذر أو شيء أوجبه على نفسه فعليه القضاء. والنبيُّ ﷺ كان من عادته إذا عمل شيئاً داوم عليه، فلما لم يتمكن من الاعتكاف هذا العام من أجل كثرة أبنية النساء في المسجد اعتكف في شوال."],"en":["There is nothing in this hadith to indicate that making it up is obligatory for someone who leaves a voluntary retreat. That is different from a vow or something a person has made binding upon himself, in which case he must make it up. The Prophet ﷺ had the habit that when he did an act of worship, he continued it regularly. So when he was unable to complete the retreat that year because of the many structures of the women in the mosque, he observed it in Shawwal."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2045},{"key":"muslim","label":"مسلم","number":1172}]},{"num":4699,"demo":false,"sanad":"","matn":["عن أُبي بن كعب، أنّ رسول اللّٰه ﷺ كان يعتكف في العشر الأواخر من رمضان، فسافر ولم يعتكف، فلما كان من العام المقبل اعتكف عشرين يوماً."],"takhrij":"صحيح: رواه أبو داود (٢٤٦٣)، وابن ماجه (١٧٧٠)، وأحمد (٢١٢٧٧)، وصحّحه ابن خزيمة (٢٢٢٥).","grade":"صحيح","chapter_ar":"باب قضاء الاعتكاف بضمّه للعام المقبل","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2463), Ibn Majah (1770), Ahmad (21277), and authenticated by Ibn Khuzaymah (2225).","chapter_en":"Making up retreat by adding it to the following year","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Ubayy ibn Kaʿb reported that the Messenger of Allah ﷺ used to observe retreat in the last ten of Ramadan. Then he traveled and did not observe retreat, so when the following year came, he observed retreat for twenty days."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2463},{"key":"ibnmajah","label":"ابن ماجه","number":1770},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2225},{"key":"ahmad","label":"مسند الإمام أحمد","number":21277,"n":21277}]},{"num":4700,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: كان النبيّ ﷺ يعتكف في العشر الأواخر من رمضان، فلم يعتكف عاماً، فلما كان العام المقبل اعتكف عشرين."],"takhrij":"صحيح: رواه الترمذي (٨٠٣)، وابن خزيمة (٢٢٢٧، ٢٢٢٦). قال الترمذي: حسن صحيح.","grade":"صحيح","chapter_ar":"باب قضاء الاعتكاف بضمّه للعام المقبل","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (803) and Ibn Khuzaymah (2227, 2226). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Making up retreat by adding it to the following year","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ used to observe retreat in the last ten of Ramadan, then one year he did not observe retreat, so in the following year he observed retreat for twenty days."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":803},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2227}]},{"num":4701,"demo":false,"sanad":"","matn":["عن أم المؤمنين عائشة، قالت: كان رسول اللّٰه ﷺ إذا أراد أن يعتكف، صلّى الفجر، ثم دخل معتكفه."],"takhrij":"متفق عليه: رواه البخاري (٢٠٤١)، ومسلم (١١٧٢/٦) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب دخول الاعتكاف بعد صلاة الصبح","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2041) and Muslim (1172 no. 6), and the wording is that of Muslim.","chapter_en":"Entering the place of retreat after the dawn prayer","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["The Mother of the Believers, ʿA’ishah, said: When the Messenger of Allah ﷺ intended to observe retreat, he would pray the dawn prayer, then enter his place of retreat."]},"intro":{"ar":["وقولها: (( إذا صلى الفجر )) أي فجر يوم العشرين؛ لأن النهار هو محل الصوم، فكان اعتكافه في العشر الأواخر من النهار في حال الصوم. وهو ردٌّ على من قال: بعد غروب الشمس أي ليلة عشرين؛ لأن الليلة داخلة في العشر الأواخر، ولذا أوّل هؤلاء حديث عائشة على أنه دخل من أول الليل، ولكن إنما يخلو بنفسه في المكان الذي أعدّه للاعتكاف بعد صلاة الصبح. انظر: “نيل الأوطار” (٣/٢٥١)."],"en":["Her statement “after he prayed dawn” means the dawn of the twentieth day, because the daytime is the time of fasting, so his retreat for the last ten was during the days while fasting. This is an answer to those who said that it begins after sunset on the night of the twentieth, since that night is part of the last ten. For this reason, such scholars interpreted the hadith of ʿA’ishah to mean that he entered from the beginning of the night, but only secluded himself in the place prepared for retreat after the dawn prayer. See Nayl al-Awtar (3/251)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2041},{"key":"muslim","label":"مسلم","number":1172}]},{"num":4702,"demo":false,"sanad":"","matn":["عن أم المؤمنين عائشة، قالت: إنّ النبيّ ﷺ كان يعتكف العشر الأواخر من رمضان حتى توفاه الله، ثم اعتكف أزواجه من بعده."],"takhrij":"متفق عليه: رواه البخاري (٢٠٢٦)، ومسلم (١١٧٢/٥).","grade":"متفق عليه","chapter_ar":"باب اعتكاف النساء في المسجد","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2026) and Muslim (1172 no. 5).","chapter_en":"Women observing retreat in the mosque","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["The Mother of the Believers, ʿA’ishah, said: The Prophet ﷺ used to observe retreat in the last ten of Ramadan until Allah took his soul, then his wives observed retreat after him."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَلَا تُبَاشِرُوهُنَّ وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ ) [سورة البقرة: ١٨٧].","وقولها: (( ثم اعتكف أزواجه من بعده )) اعتكفن في المساجد لما ثبت في صحيح مسلم (٢٩٧) أنها قالت: ( إن كنتُ لأدخل البيت للحاجة والمريض فيه، فما أسأل عنه إلا وأنا مارّة ).","فقولها: (( إن كنتُ لأدخل البيت )) فيه دليل على أنها كانت تعتكف في المسجد.","وفي الباب دليل على جواز اعتكاف النساء في المسجد؛ لأنّ النبيّ ﷺ لم يمنعهنّ من الاعتكاف في المسجد، بل أذن لعائشة وحفصة رضي اللّٰه عنهما في أول الأمر، ثم لما ضربت زينب رضي اللّٰه عنها قبّتها منعهنّ لأجل كثرة القباب حتى لا يضيق المسجد بالمصلين.","ولا يجوز مباشرة النساء في حال الاعتكاف ولو كان ذلك ليلاً؛ لأن الجماع، وكذلك إنزال المني بشهوة من غير جماع كالاستمناء، أو مباشرة الزوجة في غير الفرج من مبطلات الاعتكاف."],"en":["Allah the Exalted said: “And do not approach them while you are in retreat in the mosques” [Surah al-Baqarah: 187].","Her statement “then his wives observed retreat after him” means that they observed retreat in the mosques, because it is established in Sahih Muslim (297) that she said: “I would enter the house for a need, and if a sick person was there, I would not ask about him except while passing by.”","Her statement “I would enter the house” shows that she had been in retreat in the mosque.","This chapter contains evidence for the permissibility of women observing retreat in the mosque, because the Prophet ﷺ did not stop them from observing retreat there. Rather, he gave permission to ʿA’ishah and Hafsah, may Allah be pleased with them, at first. Then when Zaynab, may Allah be pleased with her, put up her tent, he stopped them because of the large number of tents so that the mosque would not become crowded for the worshippers.","It is not permissible to have intimate relations with women while in retreat, even at night, because intercourse — and likewise the emission of semen through desire without intercourse, such as self-stimulation, or intimate touching of one’s wife outside intercourse — invalidates the retreat."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2026},{"key":"muslim","label":"مسلم","number":1172}]},{"num":4703,"demo":false,"sanad":"","matn":["عن عائشة: أنّ رسول اللّٰه ﷺ ذكر أن يعتكف العشر الأواخر من رمضان، فاستأذنته عائشة فأذن لها. وسألتْ حفصةُ عائشةَ أن تستأذن لها، ففعلت. فلما رأت ذلك زينب بنت جحش أمرتْ ببناء فبُني لها. قالت: وكان رسول اللّٰه ﷺ إذا صلّى انصرف إلى بنائه فبصر بالأبنية فقال: (( ما هذا؟ )). قالوا: بناء عائشة وحفصة وزينب. فقال رسول اللّٰه ﷺ: (( آلبر أردن بهذا؟ ما أنا بمعتكف )). فرجع، فلما أفطر اعتكف عشراً من شوال."],"takhrij":"متفق عليه: رواه البخاريّ (٢٠٤٥)، ومسلم (١١٧٢/٦). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب اعتكاف النساء في المسجد","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2045) and Muslim (1172 no. 6), and the wording is that of al-Bukhari.","chapter_en":"Women observing retreat in the mosque","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ intended to observe retreat during the last ten of Ramadan. ʿA’ishah asked his permission and he gave her permission. Hafsah then asked ʿA’ishah to seek permission for her, and she did so. When Zaynab bint Jahsh saw that, she ordered a structure to be built for her, and it was built. She said: When the Messenger of Allah ﷺ prayed, he would go to his place of retreat, then he saw the structures and said: “What is this?” They said: The structures of ʿA’ishah, Hafsah, and Zaynab. The Messenger of Allah ﷺ said: “Is it righteousness that they intended by this? I am not going into retreat.” So he returned, and when Ramadan ended, he observed retreat for ten days in Shawwal."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2045},{"key":"muslim","label":"مسلم","number":1172}]},{"num":4704,"demo":false,"sanad":"","matn":["عن عائشة، قالت: اعتكفت مع رسولِ اللّٰه ﷺ امرأةٌ مستحاضة من أزواجه، فكانت ترى الحمرة والصُّفرة، فربّما وضعنا الطَّسْت تحتها وهي تصلّي."],"takhrij":"صحيح: رواه البخاري (٢٠٣٧).","grade":"صحيح","chapter_ar":"باب اعتكاف المستحاضة","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2037).","chapter_en":"The retreat of a woman with irregular bleeding","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["ʿA’ishah said: A woman from the wives of the Messenger of Allah ﷺ who had irregular bleeding observed retreat with the Messenger of Allah ﷺ. She would see reddish and yellowish discharge, and at times we would place a basin beneath her while she prayed."]},"intro":{"ar":["هذا بخلاف الحيض والنفاس فإنهما من مبطلات الاعتكاف لعدم جواز مكثهما في المساجد."],"en":["This is different from menstruation and postnatal bleeding, because both invalidate retreat since it is not permissible for such a woman to remain in the mosque."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2037}]},{"num":4705,"demo":false,"sanad":"","matn":["عن عائشة، أنّ النبيَّ ﷺ ترك الاعتكاف في شهر رمضان حتى اعتكف في العشر الأوّل من شوال."],"takhrij":"متفق عليه: رواه البخاري (٢٠٣٣)، ومسلم (١١٧٢/٦) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب هل يُشترط الصوم في الاعتكاف","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2033) and Muslim (1172 no. 6), and the wording is that of Muslim.","chapter_en":"Is fasting a condition for retreat?","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["ʿA’ishah reported that the Prophet ﷺ left off retreat in Ramadan until he observed retreat in the first ten of Shawwal."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2033},{"key":"muslim","label":"مسلم","number":1172}]},{"num":4706,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ عمر سأل النبيَّ ﷺ قال: كنتُ نذرتُ في الجاهلية أن أعتكف ليلةً في المسجد الحرام. قال: (( أوفِ بنذرك )). وفي رواية عند البخاري: (( فاعتكف ليلة ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٣٢)، ومسلم (١٦٥٦). والرواية الثانية عند البخاري (٢٠٤٢).","grade":"متفق عليه","chapter_ar":"باب هل يُشترط الصوم في الاعتكاف","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2032) and Muslim (1656). The second wording is also in al-Bukhari (2042).","chapter_en":"Is fasting a condition for retreat?","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar reported that ʿUmar asked the Prophet ﷺ and said: I had vowed in the pre-Islamic period that I would observe retreat for one night in al-Masjid al-Haram. He said: “Fulfill your vow.” And in a narration in al-Bukhari: “So he observed retreat for one night.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2032},{"key":"muslim","label":"مسلم","number":1656},{"key":"والروایہ_الثانیہ_عند_البخاری","label":". والرواية الثانية عند البخاري","number":2042}]},{"num":4707,"demo":false,"sanad":"","matn":["عن عائشة، أنّها قالت: كان رسولُ اللّٰه ﷺ، إذا اعتكف يُدني إليَّ رأسَه فأرجِّلُه، وكان لا يدخلُ البيتَ إلا لحاجة الإنسان."],"takhrij":"متفق عليه: رواه مالك (١)، ومسلم (٢٩٧/٦)، والبخاري (٢٠٢٩).","grade":"متفق عليه","chapter_ar":"باب خروج المعتكف من المسجد لقضاء حوائجه دون غيرها، من زيارة المريض واتباع الجنازة ونحوها","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (1), Muslim (297 no. 6), and al-Bukhari (2029).","chapter_en":"The person in retreat leaving the mosque for necessary needs only, not for visiting the sick, following a funeral, and similar matters","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah said: When the Messenger of Allah ﷺ was in retreat, he would bring his head near to me and I would comb his hair, and he would not enter the house except for a person’s necessary need."]},"intro":{"ar":["يُستفاد من أحاديث الباب عدم الخروج من المسجد عمدًا بدون حاجة؛ لأنه بذلك يفوت غاية الاعتكاف، وهو التفرّغ للعبادة: من الصلاة والذكر والدعاء والتوبة والاستغفار وقراءة القرآن ونحو ذلك من الطاعات التي تُقرّبه إلى اللّٰه تعالى.","ويباح له الخروج من المسجد لما لا بدَّ منه مثل الحصول على الطعام والشراب، والخروج لقضاء الحاجة، والوضوء والاغتسال من الجنابة، ومن أجل يوم الجمعة.","وكذلك يباح له أن يزوره بعضُ أقاربه، ويطمئنّ على صحته، ويزوّده ما يحتاج إليه من الطعام والشراب والملابس والأدوية والكتب الدينية، ويتحدّث إليه ساعةً من الزمن، وله أن يخرج من معتكفه لتوديعه."],"en":["What is understood from the hadiths of this chapter is that a person in retreat should not leave the mosque intentionally without a need, because that would defeat the purpose of retreat, which is to devote oneself to worship: prayer, remembrance, supplication, repentance, seeking forgiveness, recitation of the Qur’an, and similar acts of obedience that bring one near to Allah the Exalted.","It is permissible for him to leave the mosque for what is necessary, such as obtaining food and drink, relieving himself, making ablution, bathing from major ritual impurity, and for the Friday prayer.","It is also permissible for some of his relatives to visit him, check on his condition, bring him what he needs of food, drink, clothing, medicine, and religious books, and speak with him for a short while. He may also leave his place of retreat to bid them farewell."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"muslim","label":"مسلم","number":297},{"key":"bukhari","label":"البخاري","number":2029}]},{"num":4708,"demo":false,"sanad":"","matn":["عن عائشة زوج النبيّ ﷺ قالت: إن كنتُ لأدخل البيتَ للحاجة والمريضُ فيه، فما أسألُ عنه إلا وأنا مارّة. وإن كان رسولُ اللّٰه ﷺ ليدخلُ عليَّ رأسَه وهو في المسجد فأرجِّله، وكان لا يدخلُ البيتَ إلا لحاجةٍ إذا كان معتكفاً."],"takhrij":"صحيح: رواه البخاري (٢٠٢٩)، ومسلم (٢٩٧/٧).","grade":"صحيح","chapter_ar":"باب خروج المعتكف من المسجد لقضاء حوائجه دون غيرها، من زيارة المريض واتباع الجنازة ونحوها","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2029) and Muslim (297 no. 7).","chapter_en":"The person in retreat leaving the mosque for necessary needs only, not for visiting the sick, following a funeral, and similar matters","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: I would enter the house for a need, and if a sick person was there, I would not ask about him except while passing by. And the Messenger of Allah ﷺ would put his head into my room while he was in the mosque and I would comb his hair. He would not enter the house except for a need when he was in retreat."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2029},{"key":"muslim","label":"مسلم","number":297}]},{"num":4709,"demo":false,"sanad":"","matn":["عن علي بن الحسين: أنّ صفية زوج النبيّ ﷺ أخبرته أنها جاءتْ إلى رسول اللّه ﷺ تزورُه في اعتكافه في المسجد في العشر الأواخر من رمضان، فتحدّثتْ عنده ساعةً، ثم قامتْ تنقلبُ، فقام النبيُّ ﷺ معها يقلبها، حتى إذا بلغتْ باب المسجد عند باب أمّ سلمة مرَّ رجلان من الأنصار فسلّما على رسول اللّٰه ﷺ، فقال لهما النبيُّ ﷺ: (( على رِسْلِكما، إنّما هي صفية بنت حُييّ )). قالا: سبحان الله يا رسول الله. وكبر عليهما، فقال النبيُّ ﷺ: (( إنّ الشيطان يبلغُ من ابن آدم مبلغ الدم، وإني خشيتُ أن يقذف في قلوبكما شيئاً ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٣٥)، ومسلم (٢١٧٥/٢٥).","grade":"متفق عليه","chapter_ar":"باب زيارة المعتكف في اعتكافه","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2035) and Muslim (2175 no. 25).","chapter_en":"Visiting the person in retreat during his retreat","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["ʿAli ibn al-Husayn reported that Safiyyah, the wife of the Prophet ﷺ, told him that she came to visit the Messenger of Allah ﷺ while he was in retreat in the mosque during the last ten of Ramadan. She spoke with him for a while, then she got up to leave, and the Prophet ﷺ stood and went with her to escort her back. When she reached the gate of the mosque near the door of Umm Salamah, two men from the Ansar passed by and greeted the Messenger of Allah ﷺ. The Prophet ﷺ said to them: “Take it calmly; she is only Safiyyah bint Huyayy.” They said: Glory be to Allah, O Messenger of Allah. That was difficult for them, so the Prophet ﷺ said: “Indeed, Satan reaches the son of Adam just as the blood reaches him, and I feared that he might cast something into your hearts.”"]},"intro":{"ar":["قوله: (( على رِسْلِكما )) بفتح الراء وكسرها، وقيل بالكسر: التؤدة، وبالفتح الرفق واللين، والمعنى متقارب، وأصله السير البطيء."],"en":["The phrase “Take it calmly” has been read with both a fathah and a kasrah on the letter ra. It was said that with the kasrah it means calmness and deliberateness, and with the fathah it means gentleness and ease. The meaning is close in both cases, and its original sense refers to slow movement."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2035},{"key":"muslim","label":"مسلم","number":2175}]},{"num":4710,"demo":false,"sanad":"","matn":["عن أنس، أنّ النبيَّ ﷺ كان مع إحدى نسائه، فمرَّ به رجلٌ، فدعاه، فجاء، فقال: (( يا فلان، هذه زوجتي فلانة )). فقال: يا رسول الله، من كنتُ أظنُّ به فلم أكن أظنُّ بك. فقال رسولُ الله ﷺ: (( إنَّ الشيطانَ يجري من الإنسانِ مجرى الدمِ ))."],"takhrij":"صحيح: رواه مسلم (٢١٧٤/٢٣).","grade":"صحيح","chapter_ar":"باب زيارة المعتكف في اعتكافه","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (2174 no. 23).","chapter_en":"Visiting the person in retreat during his retreat","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ was with one of his wives when a man passed by. He called him, and he came. Then he said: “O so-and-so, this is my wife, so-and-so.” The man said: O Messenger of Allah, if I would suspect anyone, I would never suspect you. The Messenger of Allah ﷺ said: “Indeed, Satan runs through the human being as blood runs through him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2174}]},{"num":4711,"demo":false,"sanad":"","matn":["عن البياضي، أنّ رسول اللّه ﷺ خرج على الناس وهم يصلون، وقد علتْ أصواتهم بالقرآن، فقال: (( إنّ المصلي يناجي ربَّه، فلينظر بما يناجيه به، ولا يجهر بعضكم على بعض بالقرآن ))."],"takhrij":"صحيح: رواه مالك (٣١)، والإمام أحمد (١٩٠٢٢).","grade":"صحيح","chapter_ar":"باب كراهية رفع الصوت بالقرآن في الليل والناس معتكفون","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Malik (31) and Ahmad (19022).","chapter_en":"The dislike of raising the voice with Qur’an recitation at night while people are in retreat","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Al-Bayadi reported that the Messenger of Allah ﷺ came out to the people while they were praying, and their voices had become raised with Qur’an recitation. He said: “The one who is praying is privately conversing with his Lord, so let him consider what he converses with Him through, and let none of you raise his voice over another with the Qur’an.”"]},"intro":{"ar":["وكان أصل هذا الحديث في صلاة رمضان، كما جاء في رواية: (( إنَّ ذلك في رمضان )). رواه ابن عبد البر في “التمهيد” (٢٣/٣١٦-٣١٧) عن محمد بن إبراهيم، عن أبي حازم مولى الأنصار، أنّ رسول اللّٰه ﷺ كان معتكفاً في رمضان في قبة، على بابها حصير، قال: وكان الناس يصلون عصباً عصباً، قال: فلما كان ذات ليلة رفع باب القبة، فأطلع رأسه، فلما رآه الناس أنصتوا، فقال: (( إن المصلي يناجي ربَّه، فلينظر أحدكم ما يناجي به ربَّه، ولا يجهر بعضكم على بعض بالقرآن ))."],"en":["The original setting of this hadith was in the prayer of Ramadan, as it came in another narration: “That was in Ramadan.” Ibn ʿAbd al-Barr narrated it in al-Tamhid (23/316–317) through Muhammad ibn Ibrahim, from Abu Hazim, the freedman of the Ansar, that the Messenger of Allah ﷺ was in retreat during Ramadan in a tent whose doorway was covered with a mat. The people were praying in separate groups. Then one night he lifted the covering of the tent and put out his head. When the people saw him, they became silent, and he said: “The one who is praying is privately conversing with his Lord, so let each of you consider what he converses with his Lord through, and let none of you raise his voice over another with the Qur’an.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":31},{"key":"الامام_احمد","label":"الإمام أحمد","number":19022},{"key":"ahmad","label":"مسند الإمام أحمد","number":19022,"n":19022}]},{"num":4712,"demo":false,"sanad":"","matn":["عن أبي سعيد، قال: اعتكف رسول اللّٰه ﷺ في المسجد، فسمعهم يجهرون بالقرآن، فكشف الستر، فقال: (( ألا إنّ كلّكم مناجٍ ربَّه، فلا يؤذينّ بعضكم بعضاً، ولا يرفع بعضكم على بعض في القراءة )). أو قال: (( في الصلاة ))."],"takhrij":"صحيح: رواه أبو داود (١٣٣٢)، والإمام أحمد (١١٨٩٦)، وعبد الرزاق (٤٢١٦)، وصحّحه ابن خزيمة (١١٦٢).","grade":"صحيح","chapter_ar":"باب كراهية رفع الصوت بالقرآن في الليل والناس معتكفون","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1332), Ahmad (11896), ʿAbd al-Razzaq (4216), and authenticated by Ibn Khuzaymah (1162).","chapter_en":"The dislike of raising the voice with Qur’an recitation at night while people are in retreat","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Abu Saʿid said: The Messenger of Allah ﷺ was in retreat in the mosque, and he heard them reciting the Qur’an loudly. So he lifted the curtain and said: “Indeed, every one of you is privately conversing with his Lord, so let none of you harm another, and let none of you raise his voice over another in recitation.” Or he said: “in prayer.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1332},{"key":"الامام_احمد","label":"الإمام أحمد","number":11896},{"key":"عبد_الرزاق","label":"عبد الرزاق","number":4216},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":1162},{"key":"ahmad","label":"مسند الإمام أحمد","number":11896,"n":11896}]},{"num":4713,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر، أنّ النبيَّ ﷺ اعتكف، وخطب النّاس، فقال: (( أما إنّ أحدكم إذا قام في الصلاة فإنه يناجي ربَّه، فليعلم أحدكم ما يناجي ربَّه، ولا يجهر بعضكم على بعض بالقراءة في الصلاة ))."],"takhrij":"صحيح: رواه الإمام أحمد (٤٩٢٨)، والطبراني في الكبير (١٢/٤٢٨).","grade":"صحيح","chapter_ar":"باب كراهية رفع الصوت بالقرآن في الليل والناس معتكفون","chapter_ur":"","part_ar":"كتاب الصيام","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (4928) and al-Tabarani in al-Kabir (12/428).","chapter_en":"The dislike of raising the voice with Qur’an recitation at night while people are in retreat","part_en":"The Book of Fasting","group_ar":"جموع أبواب الاعتكاف","group_en":"Collection of chapters regarding spiritual retreat","part_no":15,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar reported that the Prophet ﷺ was in retreat and addressed the people, saying: “Indeed, when one of you stands in prayer, he is privately conversing with his Lord. So let each of you know what he is conversing with his Lord through, and let none of you raise his voice over another in recitation during prayer.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":4928},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":12},{"key":"ahmad","label":"مسند الإمام أحمد","number":4928,"n":4928}]},{"num":4714,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: قال رسول اللّٰه ﷺ: (( بُني الإسلام على خمس: شهادة أن لا إله إلا الله، وأنّ محمّداً رسول الله، وإقام الصّلاة، وإيتاء الزّكاة، والحجّ، وصوم رمضان ))."],"takhrij":"متفق عليه: رواه البخاريّ (٨)، ومسلم (١٦/٢٢)، واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب في إثبات فرض الحج، وأنه مرة واحدة، وما بعده فهو تطوّع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (8) and Muslim (22 no. 16). The wording is that of al-Bukhari.","chapter_en":"Establishing that pilgrimage is obligatory, that it is required once, and that anything beyond that is voluntary","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ said: “Islam is built upon five: testifying that there is no god but Allah and that Muhammad is the Messenger of Allah ﷺ, establishing prayer, giving zakah, pilgrimage, and fasting Ramadan.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿ وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًا ﴾ [آل عمران: ٩٧]."],"en":["Allah the Exalted said: “And pilgrimage to the House is a duty owed to Allah by people, for whoever is able to find a way to it.” [Aal ʿImran: 97]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":8},{"key":"muslim","label":"مسلم","number":16}]},{"num":4715,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب، قال: بينما نحن عند رسول اللّٰه ﷺ ذات يوم إذ طلع علينا رجل شديد بياض الثياب، شديد سواد الشعر، لا يُرى عليه أثر السفر، ولا يعرفه منا أحد، حتى جلس إلى النبيّ ﷺ، فأسند ركبتيه إلى ركبتيه، ووضع كفّيه على فخذيه، وقال: يا محمد، أخبرني عن الإسلام؟ فقال رسول اللّٰه ﷺ: (( الإسلام أن تشهد أن لا إله إلا الله وأنّ محمداً رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحجّ البيت إن استطعت إليه سبيلاً )). قال: صدقت. … الحديث بتمامه."],"takhrij":"صحيح: رواه مسلم (٨).","grade":"صحيح","chapter_ar":"باب في إثبات فرض الحج، وأنه مرة واحدة، وما بعده فهو تطوّع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (8).","chapter_en":"Establishing that pilgrimage is obligatory, that it is required once, and that anything beyond that is voluntary","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khattab reported: While we were sitting with the Messenger of Allah ﷺ one day, there suddenly appeared before us a man with intensely white clothes and intensely black hair. No sign of travel could be seen on him, and none of us knew him. He sat before the Prophet ﷺ, placed his knees against his knees, placed his hands on his thighs, and said: O Muhammad, tell me about Islam. The Messenger of Allah ﷺ said: “Islam is that you testify that there is no god but Allah and that Muhammad is the Messenger of Allah ﷺ, establish prayer, give zakah, fast Ramadan, and perform pilgrimage to the House if you are able to find a way to it.” He said: You have spoken the truth. … the full hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":8}]},{"num":4716,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: خطبنا رسول اللّٰه ﷺ فقال: (( أيها الناس قد فرض اللّٰه عليكم الحجّ فحجّوا )). فقال رجل: أكلَّ عام يا رسول الله؟ فسكت حتى قالها ثلاثاً، فقال رسول اللّٰه ﷺ: (( لو قلت نعم لوجبت، ولما استطعتم )). ثم قال: (( ذروني ما تركتكم، فإنما هلك من كان قبلكم بكثرة سؤالهم، واختلافهم على أنبيائهم، فإذا أمرتكم بشيء فأتوا منه ما استطعتم، وإذا نهيتكم عن شيء فدعوه ))."],"takhrij":"صحيح: رواه مسلم (١٣٣٧)، والبخاريّ (٧٢٨٨).","grade":"صحيح","chapter_ar":"باب في إثبات فرض الحج، وأنه مرة واحدة، وما بعده فهو تطوّع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1337) and al-Bukhari (7288).","chapter_en":"Establishing that pilgrimage is obligatory, that it is required once, and that anything beyond that is voluntary","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ addressed us and said: “O people, Allah has made pilgrimage obligatory upon you, so perform pilgrimage.” A man said: Every year, O Messenger of Allah ﷺ? He remained silent until the man said it three times. Then the Messenger of Allah ﷺ said: “Had I said yes, it would have become obligatory, and you would not have been able to do it.” Then he said: “Leave me with what I leave you with. Those before you were only destroyed because of their many questions and their disagreement with their prophets. So when I command you with something, do of it what you are able, and when I forbid you from something, then leave it.”"]},"buhuth":{"ar":["وقوله: (( لو قلت نعم لوجبت )) فيه دليل على أن النبيّ ﷺ كان مفوضًا في شرع الأحكام."],"en":["His saying, “Had I said yes, it would have become obligatory,” contains evidence that the Prophet ﷺ was granted delegated authority regarding the legislation of rulings."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1337},{"key":"bukhari","label":"البخاريّ","number":7288}]},{"num":4717,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: إنّ الأقرع بن حابس سأل النبيّ ﷺ، فقال: يا رسول الله، الحجّ في كلّ سنة أو مرة واحدة؟ قال: (( بل مرة واحدة، فمن زاد فهو تطوّع ))."],"takhrij":"صحيح: رواه أبو داود (١٧٢١)، وابن ماجه (٢٨٨٦)، والإمام أحمد (٣٣٠٣).","grade":"صحيح","chapter_ar":"باب في إثبات فرض الحج، وأنه مرة واحدة، وما بعده فهو تطوّع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1721), Ibn Majah (2886), and Ahmad (3303).","chapter_en":"Establishing that pilgrimage is obligatory, that it is required once, and that anything beyond that is voluntary","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas reported that al-Aqraʿ ibn Habis asked the Prophet ﷺ: O Messenger of Allah ﷺ, is pilgrimage every year or once only? He said: “Rather, once only. Whoever does more than that, it is voluntary.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1721},{"key":"ibnmajah","label":"ابن ماجه","number":2886},{"key":"الامام_احمد","label":"الإمام أحمد","number":3303},{"key":"ahmad","label":"مسند الإمام أحمد","number":3303,"n":3303}]},{"num":4718,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: قالوا: يا رسول الله، الحجّ في كل عام؟ قال: (( لو قلت نعم لوجبت، ولو وجبت لم تقوموا بها، ولو لم تقوموا بها عذّبتم ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٨٨٥).","grade":"صحيح","chapter_ar":"باب في إثبات فرض الحج، وأنه مرة واحدة، وما بعده فهو تطوّع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2885).","chapter_en":"Establishing that pilgrimage is obligatory, that it is required once, and that anything beyond that is voluntary","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik reported: They said: O Messenger of Allah ﷺ, pilgrimage every year? He said: “Had I said yes, it would have become obligatory. If it had become obligatory, you would not have been able to fulfill it, and if you failed to fulfill it, you would have been punished.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2885}]},{"num":4719,"demo":false,"sanad":"","matn":["عن أبي أمامة الباهليّ، قال: قام رسول اللّٰه ﷺ في الناس، فقال: (( كُتب عليكم الحجّ )). فقام رجلٌ من الأعراب فقال: أفي كلّ عام؟ قال: فغلق كلام رسول اللّٰه ﷺ، وأسكت واستغضب ومكث طويلاً، ثم تكلّم فقال: (( من السائل؟ )). فقال الأعرابي: أنا ذا. فقال: (( ويحك، ماذا يؤمنك أن أقول: نعم، والله لو قلت: نعم لوجبت، ولو وجبت لكفرتم، ألا إنه إنّما أهلك الذين من قبلكم أئمة الحرج، والله لو أني أحللت لكم جميع ما في الأرض، وحرّمت عليكم منها موضع خفّ لوقعتم به )). قال: فأنزل اللّٰه عند ذلك: ﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ ﴾ آخر الآية [سورة المائدة: ١٠١]."],"takhrij":"حسن: رواه الطبراني في الكبير (٨/١٨٦-١٨٧)، وابن جرير في تفسيره (٩/٢١)، واللفظ لابن جرير.","grade":"حسن","chapter_ar":"باب في إثبات فرض الحج، وأنه مرة واحدة، وما بعده فهو تطوّع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Kabir (8/186–187) and Ibn Jarir in his Tafsir (9/21). The wording is that of Ibn Jarir.","chapter_en":"Establishing that pilgrimage is obligatory, that it is required once, and that anything beyond that is voluntary","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah al-Bahili reported: The Messenger of Allah ﷺ stood before the people and said: “Pilgrimage has been prescribed upon you.” A Bedouin man stood up and said: Every year? The Messenger of Allah ﷺ stopped speaking, fell silent, and became upset, remaining that way for a long time. Then he spoke and said: “Who is the questioner?” The Bedouin said: It is I. He said: “Woe to you. What makes you feel safe that I might say yes? By Allah, if I said yes, it would become obligatory, and if it became obligatory, you would disbelieve. Those before you were only destroyed by leading people into hardship. By Allah, if I made lawful for you everything on earth and prohibited for you from it only the space of a hoof, you would still fall into it.” Then Allah revealed regarding that: “O you who believe, do not ask about things which, if made clear to you, would distress you” to the end of the verse. [al-Ma’idah: 101]"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":8},{"key":"ابن_جریر/تفسیرہ","label":"ابن جرير في تفسيره","number":9}]},{"num":4720,"demo":false,"sanad":"","matn":["عن ابن عباس قال: لما أنزلت آية الحجّ نادى النبيّ ﷺ في الناس، فقال: (( يا أيها الناس إنّ اللّٰه قد كتب عليكم الحجّ فحجّوا )) فقالوا: يا رسول اللّٰه، أعاماً واحداً، أم كلّ عام؟ فقال: (( لا، بل عاماً واحداً، ولو قلت: كل عام لوجبت، ولو وجبت لكفرتم )) فأنزل اللّٰه تعالى ذكره: ﴿ يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ ﴾ [سورة المائدة: ١٠١]. قال: سألوا النبي ﷺ عن أشياء فوعظهم، فانتهوا."],"takhrij":"حسن بالشواهد: رواه ابن جرير في تفسيره (٩/٢١).","grade":"حسن بالشواهد","chapter_ar":"باب في إثبات فرض الحج، وأنه مرة واحدة، وما بعده فهو تطوّع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan by supporting narrations: narrated by Ibn Jarir in his Tafsir (9/21).","chapter_en":"Establishing that pilgrimage is obligatory, that it is required once, and that anything beyond that is voluntary","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbas said: When the verse of pilgrimage was revealed, the Prophet ﷺ called out among the people and said: “O people, Allah has prescribed pilgrimage upon you, so perform pilgrimage.” They said: O Messenger of Allah ﷺ, one year only or every year? He said: “No, rather one year only. Had I said every year, it would have become obligatory, and if it had become obligatory, you would have disbelieved.” So Allah the Exalted revealed: “O you who believe, do not ask about things which, if made clear to you, would distress you.” [al-Ma’idah: 101] He said: They had asked the Prophet ﷺ about certain things, so he admonished them, and they stopped."]}},"tuhfa":{},"refs":[{"key":"ابن_جریر/تفسیرہ","label":"ابن جرير في تفسيره","number":9}]},{"num":4721,"demo":false,"sanad":"","matn":["عن أبي واقد الليثيّ، قال: سمعت رسول اللّٰه ﷺ يقول لأزواجه في حجّة الوداع: (( هذه، ثم ظهور الحُصُر ))."],"takhrij":"حسن: رواه أبو داود (١٧٢٢)، والإمام أحمد (٢١٩٠٥).","grade":"حسن","chapter_ar":"باب ما جاء في استحباب لزوم المرأة بيتها بعد قضاء فرض الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1722) and Ahmad (21905).","chapter_en":"What has come regarding the recommendation that a woman remain in her home after completing the obligatory pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Waqid al-Laythi reported: I heard the Messenger of Allah ﷺ say to his wives during the Farewell Pilgrimage: “This pilgrimage, then afterward remain at home upon your mats.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1722},{"key":"الامام_احمد","label":"الإمام أحمد","number":21905},{"key":"ahmad","label":"مسند الإمام أحمد","number":21905,"n":21905}]},{"num":4722,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول اللّٰه ﷺ لما حجّ بنسائه قال: (( إنّما هذه الحجّة، ثم الزمن ظهور الحُصُر ))."],"takhrij":"حسن: رواه أحمد (٩٧٦٥)، وأبو يعلى (٧١٥٨)، والطيالسي (١٧٥٢)، والبيهقيّ (٥/٢٢٨).","grade":"حسن","chapter_ar":"باب ما جاء في استحباب لزوم المرأة بيتها بعد قضاء فرض الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (9765), Abu Yaʿla (7158), al-Tayalisi (1752), and al-Bayhaqi (5/228).","chapter_en":"What has come regarding the recommendation that a woman remain in her home after completing the obligatory pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that when the Messenger of Allah ﷺ performed pilgrimage with his wives, he said: “This pilgrimage only; then afterward remain at home upon your mats.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":7158},{"key":"الطیالسی","label":"الطيالسي","number":1752},{"key":"البیہقی","label":"البيهقيّ","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":9765,"n":9765}]},{"num":4723,"demo":false,"sanad":"","matn":["عن أم سلمة، قالت: قال رسول اللّٰه ﷺ لنا في حجّة الوداع: (( إنّما هي هذه الحجّة، ثم الجلوس على ظهور الحُصُر في البيوت ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٢٣/٣١٣)، وأبو يعلى (٦٨٨٥).","grade":"حسن","chapter_ar":"باب ما جاء في استحباب لزوم المرأة بيتها بعد قضاء فرض الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Kabir (23/313) and Abu Yaʿla (6885).","chapter_en":"What has come regarding the recommendation that a woman remain in her home after completing the obligatory pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Umm Salamah reported: The Messenger of Allah ﷺ said to us during the Farewell Pilgrimage: “This pilgrimage only, then sitting upon the mats in your homes.”"]},"buhuth":{"ar":["وأما معنى الحديث فكما قال البيهقيّ: ( في حجّ عائشة وغيرها من أمهات المؤمنين بعد رسول اللّٰه ﷺ دلالة على أن المراد من هذا الخبر وجوب الحج عليهن مرّة واحدة كما بين وجوبه على الرجال مرة لا المنع من الزيادة عليه ).","وقوله: (( الحُصُر )) بضم الحاء والصاد، جمع حصير يُبسط في البيوت، وفيه إشارة إلى لزوم البيت وترك حجّ النفل بعد أن تيسر لهن الحج مع النبي ﷺ، لا النهي عن الحج كليًا تطوعًا بعد أداء الفريضة، وقد صحّ من فعل أزواج النبي ﷺ أنهن حججن بعده ﷺ في عهد عمر بن الخطاب كما سيأتي."],"en":["As for the meaning of the hadith, al-Bayhaqi said: “In the pilgrimage of ʿA’ishah and the other Mothers of the Believers after the Messenger of Allah ﷺ there is proof that what is meant by this report is that pilgrimage was obligatory upon them once, just as it was made obligatory upon men once, not that they were prohibited from doing more than that.”","His phrase “the mats” is the plural of a mat spread in homes. It points to remaining in the home and leaving off voluntary pilgrimage after pilgrimage had been made easy for them with the Prophet ﷺ. It does not mean a complete prohibition of voluntary pilgrimage after fulfilling the obligation. It is authentically established from the actions of the Prophet ﷺ’s wives that they performed pilgrimage after him during the caliphate of ʿUmar ibn al-Khattab, as will come later."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":23},{"key":"ابو_یعلی","label":"أبو يعلى","number":6885},{"key":"sh12520","label":"مسند أبي يعلى","number":6885,"n":6891}]},{"num":4724,"demo":false,"sanad":"","matn":["عن عمرو بن العاص، قال: فلما جعل اللّٰه الإسلام في قلبي أتيت النبيّ ﷺ فقلت: ابسط يمينك فلأبايعك، فبسط يمينه. قال: فقبضت يدي. قال: (( ما لك يا عمرو؟ )) قال: قلت: أردت أن أشترط. قال: (( تشترط بماذا؟ )) قلت: أن يُغفر لي. قال: (( أما علمت أن الإسلام يهدم ما كان قبله، وأن الهجرة تهدم ما كان قبلها، وأن الحجّ يهدم ما كان قبله )). الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١).","grade":"صحيح","chapter_ar":"باب ما جاء أن الحج يهدم ما كان قبله","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (121).","chapter_en":"What has come regarding pilgrimage erasing what came before it","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn al-ʿAs reported: When Allah placed Islam in my heart, I came to the Prophet ﷺ and said: Stretch out your right hand so that I may pledge allegiance to you. So he stretched out his right hand. He said: Then I withdrew my hand. He said: “What is the matter, O ʿAmr?” I said: I wanted to make a condition. He said: “A condition concerning what?” I said: That I be forgiven. He said: “Do you not know that Islam erases what came before it, that migration erases what came before it, and that pilgrimage erases what came before it?” The hadith continues."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":121}]},{"num":4725,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: سُئِلَ النبيُّ ﷺ أيُّ الأعمال أفضل؟ قال: (( إيمانٌ بالله ورسوله )). قيل: ثم ماذا؟ قال: (( جهادٌ في سبيل الله )). قيل: ثم ماذا؟ قال: (( حجٌّ مبرورٌ ))."],"takhrij":"متفق عليه: رواه البخاري (١٥١٩)، ومسلم (٨٣).","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1519) and Muslim (83).","chapter_en":"What has come regarding the virtue of pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported: The Prophet ﷺ was asked: Which deeds are best? He said: “Faith in Allah and His Messenger.” It was said: Then what? He said: “Striving in the path of Allah.” It was said: Then what? He said: “A righteous pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1519},{"key":"muslim","label":"مسلم","number":83}]},{"num":4726,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول اللّٰه ﷺ قال: (( العُمْرَةُ إلى العُمْرَةِ كفّارةٌ لما بينهما، والحجُّ المبرورُ ليس له جزاءٌ إلا الجنّةُ ))."],"takhrij":"متفق عليه: رواه مالك (٦٥)، والبخاريّ (١٧٧٣)، ومسلم (١٣٤٩).","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (65), al-Bukhari (1773), and Muslim (1349).","chapter_en":"What has come regarding the virtue of pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “One ʿumrah to the next is an expiation for what is between them, and an accepted pilgrimage has no reward except Paradise.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":65},{"key":"bukhari","label":"البخاريّ","number":1773},{"key":"muslim","label":"مسلم","number":1349}]},{"num":4727,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: سمعتُ النبيّ ﷺ يقول: (( من حجَّ لله فلم يرفثْ، ولم يفسقْ، رجع كيوم ولدته أمُّه ))."],"takhrij":"متفق عليه: رواه البخاري (١٥٢١)، ومسلم (١٣٥٠)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1521) and Muslim (1350). The wording is that of al-Bukhari.","chapter_en":"What has come regarding the virtue of pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: I heard the Prophet ﷺ say: “Whoever performs pilgrimage for Allah and does not engage in sexual speech or sinful conduct will return like the day his mother gave birth to him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1521},{"key":"muslim","label":"مسلم","number":1350}]},{"num":4728,"demo":false,"sanad":"","matn":["عن عائشة أنها قالت: يا رسول الله، ترى الجهاد أفضل العمل، أفلا نجاهد؟ قال: (( لا، لكنَّ أفضلَ الجهادِ حجٌّ مبرورٌ ))."],"takhrij":"صحيح: رواه البخاريّ (١٥٢٠).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1520).","chapter_en":"What has come regarding the virtue of pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: O Messenger of Allah ﷺ, you regard striving in battle as the best deed, so should we not strive in battle? He said: “No, rather the best striving is a righteous pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1520}]},{"num":4729,"demo":false,"sanad":"","matn":["عن ماعز، عن النبيّ ﷺ أنّه سُئل أيُّ الأعمال أفضل؟ قال: (( إيمانٌ بالله وحده، ثم الجهاد، ثم حجّةٌ برّةٌ تفضل سائر العمل كما بين مطلع الشمس إلى مغربها ))."],"takhrij":"صحيح: رواه الإمام أحمد (١٩٠١٠)، وعنه الطبراني في الكبير (٢٠/٢٤٤).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (19010), and from him al-Tabarani in al-Kabir (20/244).","chapter_en":"What has come regarding the virtue of pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["From Maʿiz, from the Prophet ﷺ, that he was asked which deeds are best. He said: “Faith in Allah alone, then striving in battle, then a righteous pilgrimage which surpasses all other deeds like the distance between the rising of the sun and its setting.”"]},"buhuth":{"ar":["قوله: (( حجٌّ مبرورٌ )) قال النووي: ( الأصح الأشهر أنّ المبرور هو الذي لا يخالطه إثم، مأخوذ من البر وهو الطاعة، وقيل: هو المقبول، ومن علامة القبول أن يرجع خيراً مما كان، وقيل: هو الذي لا رياء فيه، وقيل: الذي لا يعقبه معصية، وهما داخلان فيما قبلهما ) شرح صحيح مسلم (٩/١١٨).","وقال أبو العباس القرطبي في “المفهم” (٣/٤٦٣) في الأقوال التي ذكرت في تفسير الحج المبرور: ( كلّها متقاربة المعنى، وهو أنّ الحجّ الذي وُفّيت أحكامه، ووقع موافقاً لما طُلب من المكلّف على الوجه الأكمل ) اهـ."],"en":["Regarding the phrase “a righteous pilgrimage,” al-Nawawi said: “The strongest and most well-known view is that it is the one not mixed with sin, taken from righteousness, which means obedience. It was also said that it means accepted, and one sign of acceptance is that a person returns better than before. It was also said that it is the one free of showing off, and it was also said that it is the one not followed by disobedience. Both of these are included in what came before.” Sharh Sahih Muslim (9/118).","Abu al-ʿAbbas al-Qurtubi said in al-Mufhim (3/463) about the statements mentioned in explaining the righteous pilgrimage: “All of them are close in meaning, namely that it is the pilgrimage whose rulings are fulfilled and which is carried out in accordance with what was required of the legally responsible person in the most complete manner.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":19010},{"key":"عنہ_الطبرانی/الکبیر","label":"عنه الطبراني في الكبير","number":20},{"key":"ahmad","label":"مسند الإمام أحمد","number":19010,"n":19010}]},{"num":4730,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( ثلاثة في ضمان اللّٰه عز وجل: رجلٌ خرج من بيته إلى مسجدٍ من مساجد اللّٰه عزّ وجلّ، ورجلٌ خرج غازيًا في سبيل اللّٰه عزّ وجلّ، ورجلٌ خرج حاجًّا ))."],"takhrij":"صحيح: رواه الحميدي في مسنده (١٠٩٠)، وابن أبي عمر العدني في مسنده، كما في إتحاف الخيرة المهرة (٩٧٧).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Humaydi in his Musnad (1090), and Ibn Abi ʿUmar al-ʿAdani in his Musnad, as cited in Ithaf al-Khayrah al-Maharah (977).","chapter_en":"What has come regarding the virtue of pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Three are under the guarantee of Allah, Mighty and Majestic: a man who leaves his home for one of the mosques of Allah, a man who goes out as a fighter in the path of Allah, and a man who goes out as a pilgrim.”"]}},"tuhfa":{},"refs":[{"key":"الحمیدی/مسندہ","label":"الحميدي في مسنده","number":1090},{"key":"کما/اتحاف_الخیرہ_المہرہ","label":"كما في إتحاف الخيرة المهرة","number":977},{"key":"humaydi","label":"مسند الحميدي","number":1121,"n":1142}]},{"num":4731,"demo":false,"sanad":"","matn":["عن عائشة، قالت: استأذنت النبيّ ﷺ في الجهاد فقال: (( جهادُكنّ الحجّ ))."],"takhrij":"صحيح: رواه البخاريّ (٢٨٧٥). وفي رواية: (( نعم، الجهادُ الحجُّ )). رواه البخاريّ (٢٨٧٦).","grade":"صحيح","chapter_ar":"باب أن جهاد الضعفاء والنساء الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2875). In another wording: “Yes, striving is pilgrimage.” Narrated by al-Bukhari (2876).","chapter_en":"That the striving of the weak and women is pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah reported: I sought permission from the Prophet ﷺ to go out in battle, and he said: “Your striving is pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2875},{"key":"رواہ_البخاری","label":". رواه البخاريّ","number":2876}]},{"num":4732,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول اللّٰه ﷺ قال: (( جهادُ الكبيرِ والصغيرِ والضعيفِ والمرأةِ الحجُّ والعمرةُ ))."],"takhrij":"صحيح: رواه النسائيّ (٢٦٢٦)، والبيهقيّ (٤/٣٥٠).","grade":"صحيح","chapter_ar":"باب أن جهاد الضعفاء والنساء الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2626) and al-Bayhaqi (4/350).","chapter_en":"That the striving of the weak and women is pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The striving of the elderly, the young, the weak, and the woman is pilgrimage and ʿumrah.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2626},{"key":"البیہقی","label":"البيهقيّ","number":4}]},{"num":4733,"demo":false,"sanad":"","matn":["عن الحسين بن علي، قال: جاء رجلٌ إلى النبيّ ﷺ فقال: إني جبان، وإني ضعيف. قال: (( هلُمَّ إلى جهادٍ لا شوكةَ فيه: الحجّ ))."],"takhrij":"صحيح: رواه عبد الرزاق (٨٨٠٩)، والطبرانيّ في الكبير (٣/١٤٧).","grade":"صحيح","chapter_ar":"باب أن جهاد الضعفاء والنساء الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by ʿAbd al-Razzaq (8809) and al-Tabarani in al-Kabir (3/147).","chapter_en":"That the striving of the weak and women is pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Al-Husayn ibn ʿAli reported: A man came to the Prophet ﷺ and said: I am cowardly and weak. He said: “Come to a striving in which there is no weapon: pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":8809},{"key":"الطبرانی/الکبیر","label":"الطبرانيّ في الكبير","number":3}]},{"num":4734,"demo":false,"sanad":"","matn":["عن صفوان بن عبد الله بن صفوان - وكانت تحته ابنة أبي الدرداء - قال: قدمتُ الشام فأتيت أبا الدرداء في منزله فلم أجده ووجدت أم الدرداء، فقالت: أتريد الحجّ العام؟ فقلت: نعم. قالت: فادعُ اللّٰه لنا بخير، فإنّ النبيّ ﷺ كان يقول: (( دعوةُ المرءِ المسلمِ لأخيه بظهر الغيب مستجابةٌ، عند رأسه مَلَكٌ موكَّلٌ، كلّما دعا لأخيه بخيرٍ قال المَلَكُ الموكلُ به: آمين، ولك بمثل )).","قال: فخرجت إلى السوق فلقيت أبا الدرداء فقال لي مثل ذلك يرويه عن النبيّ ﷺ."],"takhrij":"صحيح: رواه مسلم (٢٧٣٣).","grade":"صحيح","chapter_ar":"باب في طلب الدعاء من الحاج والمعتمر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (2733).","chapter_en":"Seeking supplication from the pilgrim and the one performing ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Safwan ibn ʿAbdullah ibn Safwan — whose wife was the daughter of Abu al-Darda’ — said: I came to Syria and went to Abu al-Darda’ at his home, but I did not find him and found Umm al-Darda’. She said: Are you intending pilgrimage this year? I said: Yes. She said: Then supplicate to Allah for good for us, for the Prophet ﷺ used to say: “The supplication of a Muslim for his brother in his absence is answered. At his head is an appointed angel. Whenever he supplicates for good for his brother, the appointed angel says: Amen, and for you the same.”","He said: Then I went out to the market and met Abu al-Darda’, and he said to me the same thing, narrating it from the Prophet ﷺ."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2733}]},{"num":4735,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( اللهم اغفر للحاجّ، ولمن استغفر له الحاجّ ))."],"takhrij":"حسن: رواه البزار (٩٧٢٦)، وابن خزيمة (٢٥١٦)، والحاكم (١٦١٢)، والبيهقيّ (٥/٢٦١).","grade":"حسن","chapter_ar":"باب في طلب الدعاء من الحاج والمعتمر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by al-Bazzar (9726), Ibn Khuzaymah (2516), al-Hakim (1612), and al-Bayhaqi (5/261).","chapter_en":"Seeking supplication from the pilgrim and the one performing ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “O Allah, forgive the pilgrim and whoever the pilgrim seeks forgiveness for.”"]}},"tuhfa":{},"refs":[{"key":"البزار","label":"البزار","number":9726},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2516},{"key":"البیہقی","label":"البيهقيّ","number":5},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1155,"n":1155},{"key":"hakim","label":"المستدرك على الصحيحين","number":1612,"n":1601}]},{"num":4736,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، قال: قال رسول اللّٰه ﷺ: (( تابعوا بين الحجّ والعمرة، فإنّهما ينفيان الفقر والذنوب كما ينفي الكير خبث الحديد والذهب والفضة، وليس للحجّة المبرورة ثوابٌ إلا الجنة ))."],"takhrij":"حسن: رواه الترمذي (٨١٠)، والنسائي (٢٦٣١)، وأحمد (٣٦٦٩)، قال الترمذي: (( حسن صحيح غريب )).","grade":"حسن","chapter_ar":"باب فضل المتابعة بين الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (810), al-Nasa’i (2631), and Ahmad (3669). Al-Tirmidhi said: “Hasan sahih gharib.”","chapter_en":"The virtue of following one pilgrimage and ʿumrah with another","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud reported that the Messenger of Allah ﷺ said: “Perform pilgrimage and ʿumrah consecutively, for they remove poverty and sins just as the bellows removes impurity from iron, gold, and silver. And a righteous pilgrimage has no reward except Paradise.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":810},{"key":"nasai","label":"النسائي","number":2631},{"key":"ahmad","label":"مسند الإمام أحمد","number":3669,"n":3669}]},{"num":4737,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قال رسول اللّٰه ﷺ: (( تابعوا بين الحجّ والعمرة فإنهما ينفيان الفقر والذنوب كما ينفي الكير خبث الحديد ))."],"takhrij":"حسن: رواه النسائيّ (٢٦٣٠).","grade":"حسن","chapter_ar":"باب فضل المتابعة بين الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by al-Nasa’i (2630).","chapter_en":"The virtue of following one pilgrimage and ʿumrah with another","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbas reported that the Messenger of Allah ﷺ said: “Follow pilgrimage and ʿumrah one after another, for they remove poverty and sins just as the bellows removes impurity from iron.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2630}]},{"num":4738,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: قال رسول اللّٰه ﷺ: (( من أراد الحجّ فليتعجّل )).","وزاد في رواية: (( فإنّه قد يمرض المريض، وتضلّ الضّالة، وتعرض الحاجة ))."],"takhrij":"حسن: رواه أبو داود (١٧٣٢)، وأحمد (١٩٧٣)، وصحّحه الحاكم (١/٤٤٨).","grade":"حسن","chapter_ar":"باب تعجيل الحج لمن قدر عليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1732), Ahmad (1973), and authenticated by al-Hakim (1/448).","chapter_en":"Hastening to perform pilgrimage for the one who is able","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that the Messenger of Allah ﷺ said: “Whoever intends pilgrimage should hasten to it.”","In another wording there is an addition: “For a sick person may fall ill, a mount may be lost, and a need may arise.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1732},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":1},{"key":"ahmad","label":"مسند الإمام أحمد","number":1973,"n":1973}]},{"num":4739,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: سمعتُ النبيَّ ﷺ يخطب يقول: (( لا يخلونّ رجل بامرأة إلا ومعها ذو محرم، ولا تسافر المرأة إلا مع ذي محرم )). فقام رجل فقال: يا رسول الله، إنّ امرأتي خرجت حاجّةً، وإني اكتُتبتُ في غزوة كذا وكذا؟ قال: (( انطلق فحجَّ مع أهلك ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٨٦٢)، ومسلم (١٣٤١)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1862) and Muslim (1341). The wording is that of Muslim.","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbas said: I heard the Prophet ﷺ delivering a sermon saying: “A man must not be alone with a woman unless she has a mahram with her, and a woman must not travel except with a mahram.” A man stood and said: O Messenger of Allah, my wife has gone out for pilgrimage, and I have been enlisted for such-and-such battle. He said: “Go and perform pilgrimage with your wife.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1862},{"key":"muslim","label":"مسلم","number":1341}]},{"num":4740,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول اللّٰه ﷺ قال: (( لا يحلّ لامرأة تؤمن بالله واليوم الآخر تسافر مسيرة يوم وليلة إلا مع ذي محرم منها ))."],"takhrij":"متفق عليه: رواه مالك (٣٧)، ومسلم (١٣٣٩)، والبخاريّ (١٠٨٨).","grade":"متفق عليه","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (37), Muslim (1339), and al-Bukhari (1088).","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “It is not lawful for a woman who believes in Allah and the Last Day to travel the distance of a day and a night except with a mahram from her family.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":37},{"key":"muslim","label":"مسلم","number":1339},{"key":"bukhari","label":"البخاريّ","number":1088}]},{"num":4741,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ رسول اللّٰه ﷺ قال: (( لا تسافر المرأة ثلاثاً إلا ومعها ذو محرم ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٠٨٧)، ومسلم (١٣٣٨).","grade":"متفق عليه","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1087) and Muslim (1338).","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ said: “A woman must not travel for three days unless she has a mahram with her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1087},{"key":"muslim","label":"مسلم","number":1338}]},{"num":4742,"demo":false,"sanad":"","matn":["عن قزعة مولى زياد، قال: سمعت أبا سعيد — وقد غزا مع النبيّ ﷺ اثنتي عشرة غزوة — قال: أربعٌ سمعتُهن من رسول اللّٰه ﷺ — أو قال: أحدّثهن عن النبيّ ﷺ — فأعجبنني وأنقنني:","(( أن لا تسافر امرأة مسيرة يومين ليس معها زوجها أو ذو محرم، ولا صوم يومين: الفطر والأضحى، ولا صلاة بعد صلاتين: بعد العصر حتى تغرب الشمس، وبعد الصبح حتى تطلع الشمس، ولا تُشدّ الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي، والمسجد الأقصى ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٨٦٤)، ومسلم (٨٢٧)، واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1864) and Muslim (827). The wording is that of al-Bukhari.","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Qazaʿah, the freedman of Ziyad, said: I heard Abu Saʿid — who had gone on twelve expeditions with the Prophet ﷺ — say: There are four things I heard from the Messenger of Allah ﷺ — or he said: I narrate them from the Prophet ﷺ — that pleased me and impressed me:","“A woman must not travel the distance of two days unless her husband or a mahram is with her. There is no fasting on two days: the Day of Breaking the Fast and the Day of Sacrifice. There is no prayer after two prayers: after ʿAsr until the sun sets, and after Fajr until the sun rises. And no journey is to be undertaken except to three mosques: the Sacred Mosque, this mosque of mine, and al-Masjid al-Aqsa.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1864},{"key":"muslim","label":"مسلم","number":827}]},{"num":4743,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: سمعت رسول اللّٰه ﷺ يقول: (( لا تسافر المرأة يومين إلا ومعها زوجها أو ذو محرم ))."],"takhrij":"متفق عليه: رواه البخاري (١١٩٧)، ومسلم (٨٢٧).","grade":"متفق عليه","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1197) and Muslim (827).","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu Saʿid al-Khudri reported: I heard the Messenger of Allah ﷺ say: “A woman must not travel for two days unless her husband or a mahram is with her.”"]},"buhuth":{"ar":["ورواه مسلم (١٣٤٠) وفيه: (( لا يحلّ لامرأة تؤمن بالله واليوم الآخر أن تسافر سفرًا يكون ثلاثة أيام فصاعدًا إلا ومعها أبوها أو ابنها أو زوجها أو أخوها أو ذو محرم منها ))."],"en":["Muslim also narrated (1340): “It is not lawful for a woman who believes in Allah and the Last Day to travel a journey of three days or more unless her father, son, husband, brother, or some mahram from her family is with her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1197},{"key":"muslim","label":"مسلم","number":827}]},{"num":4744,"demo":false,"sanad":"","matn":["عن ابن عباس قال: جاء رجلٌ إلى المدينة، فقال النبي ﷺ: (( أين نزلت؟ )) قال: على فلانة. قال: (( أغلقت عليك بابها؟ لا تحجّن امرأة إلا ومعها ذو محرم ))."],"takhrij":"صحيح: رواه الدارقطني (٢/٢٢٢-٢٢٣)، وأبو عوانة — كما في الإتحاف (٩٠٢٦).","grade":"صحيح","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Daraqutni (2/222–223) and Abu ʿAwanah, as cited in al-Ithaf (9026).","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbas reported: A man came to Madinah, and the Prophet ﷺ said: “Where are you staying?” He said: With such-and-such woman. He said: “Has she closed her door upon you? No woman should perform pilgrimage except with a mahram.”"]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطني","number":2},{"key":"ابو_عوانہ_کما/الاتحاف","label":"أبو عوانة — كما في الإتحاف","number":9026},{"key":"sh9771","label":"سنن الدارقطني","number":2440,"n":2447}]},{"num":4745,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو بن العاص، أنّ النبي ﷺ استند إلى الكعبة، فوعظ الناس وذكّرهم، ثم قال: (( لا يصلين أحد بعد العصر حتى الليل، ولا بعد الصبح حتى تطلع الشمس، ولا تسافر امرأة إلا مع ذي محرم ثلاثة أيام ))."],"takhrij":"حسن: رواه عبد الرزاق في المصنف (١٠٧٥٠)، وأحمد (٦٧١٢).","grade":"حسن","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by ʿAbd al-Razzaq in al-Musannaf (10750) and Ahmad (6712).","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs reported that the Prophet ﷺ leaned against the Kaʿbah, admonished the people, and reminded them, then said: “No one should pray after ʿAsr until night comes, nor after Fajr until the sun rises, and no woman should travel for three days except with a mahram.”"]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق/المصنف","label":"عبد الرزاق في المصنف","number":10750},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":11598,"n":11692},{"key":"ahmad","label":"مسند الإمام أحمد","number":6712,"n":6712}]},{"num":4746,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب أنه أَذِنَ لأزواجِ النبيِّ ﷺ في آخرِ حجَّةٍ حججنها، فبعث معهنَّ عثمانَ بنَ عفانَ وعبدَ الرحمنِ بنَ عوفٍ."],"takhrij":"صحيح: رواه البخاريّ (١٨٦٠).","grade":"صحيح","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1860).","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["ʿUmar ibn al-Khattab permitted the wives of the Prophet ﷺ on the last pilgrimage they performed, and he sent with them ʿUthman ibn ʿAffan and ʿAbd al-Rahman ibn ʿAwf."]},"buhuth":{"ar":["تنبيه: فإن قيل إن عثمان وعبد الرحمن رضي اللّٰه عنهما ليسا محرمين لأزواج النبي ﷺ، فكيف خرجن إلى الحج معهما؟","الجواب: إن المؤمنين كلّهم محارم لهنّ من حيث النكاح؛ لأن اللّٰه حرّم ذلك إلى الأبد بقوله تعالى: (وَلَا أَن تَنكِحُوا أَزْوَاجَهُ مِن بَعْدِهِ أَبَدًا) [الأحزاب: ٥٣]، ولأنهن أمهات المؤمنين لقوله تعالى: (النَّبِيُّ أَوْلَىٰ بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ وَأَزْوَاجُهُ أُمَّهَاتُهُمْ) [الأحزاب: ٦]، وذلك في تعظيمهن واحترامهن كالأمهات، لا في جواز الخلوة بهن وعدم تزويج بناتهن. فإذا أُمِنت الفتنة، وهيّأ لهن خليفة المسلمين أسباب السفر مثل المركب والمأكل والمشرب ورفقة النساء الثقات مع أزواجهن، جاز لهن الخروج في سفر الحج، كما فعلن في زمن عمر. وكما أنهن استأذنّ أيضًا عثمانَ في الحج، فقال: أنا أحجّ بكن، فحججن جميعًا إلا زينب؛ كانت ماتت، وإلا سودة فإنها لم تخرج من بيتها بعد النبي ﷺ."],"en":["Note: If it is asked, “ʿUthman and ʿAbd al-Rahman, may Allah be pleased with them, were not legal unmarriageable relatives of the Prophet’s wives, so how did they travel for pilgrimage with them?”","The answer is: All the believers are permanently prohibited from marrying them, because Allah forbade that forever in His saying: “And never marry his wives after him.” [al-Ahzab: 53] And because they are the Mothers of the Believers, as Allah said: “The Prophet is closer to the believers than their own selves, and his wives are their mothers.” [al-Ahzab: 6] This means honoring and respecting them like mothers, not that private seclusion with them is allowed or that their daughters become unmarriageable. So if temptation is not feared, and the Muslim ruler provides the means of travel such as transport, food, drink, and trustworthy women companions with their husbands, then it is permissible for them to go out for pilgrimage travel, as they did in the time of ʿUmar. They also later sought permission from ʿUthman for pilgrimage, and he said: “I will perform pilgrimage with you,” so they all performed pilgrimage except Zaynab, who had already died, and Sawdah, who did not leave her home after the Prophet ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1860}]},{"num":4747,"demo":false,"sanad":"","matn":["عن ابن عمر، عن رسول اللّٰه ﷺ في امرأةٍ لها زوجها، ولها مالٌ ولا يأذن زوجها في الحجّ، قال: (( ليس لها أن تنطلق إلا بإذن زوجها ))."],"takhrij":"حسن: رواه الطبراني في الأوسط (٤٢٥٩)، مجمع البحرين (١٦٦٩)، والدارقطني (٢٤٤١).","grade":"حسن","chapter_ar":"باب وجود الزوج أو المحرم مع المرأة في السفر إلى الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by al-Tabarani in al-Awsat (4259), Majmaʿ al-Bahrayn (1669), and al-Daraqutni (2441).","chapter_en":"The requirement of a husband or a mahram accompanying a woman on travel for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar reported from the Messenger of Allah ﷺ regarding a woman who has a husband and wealth, but whose husband does not permit her to go for pilgrimage. He said: “She may not go out except with her husband’s permission.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":4259},{"key":"مجمع_البحرین","label":"مجمع البحرين","number":1669},{"key":"الدارقطنی","label":"الدارقطني","number":2441},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":4247,"n":4232},{"key":"sh9771","label":"سنن الدارقطني","number":2441,"n":2448}]},{"num":4748,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: كان أهلُ اليمن يحجّون ولا يتزوّدون، ويقولون: نحن المتوكّلون، فإذا قدموا مكة سألوا الناس، فأنزل اللّٰه تعالى: (وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَىٰ)."],"takhrij":"صحيح: رواه البخاريّ في الحجّ (١٥٢٣).","grade":"صحيح","chapter_ar":"باب أخذ الزاد في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari in the Book of Pilgrimage (1523).","chapter_en":"Taking provisions for pilgrimage and ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbas said: The people of Yemen used to perform pilgrimage without taking provisions, saying, “We are those who trust in Allah.” Then when they arrived in Makkah, they would ask people for help. So Allah revealed: “Take provisions, for indeed the best provision is mindfulness of Allah.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَىٰ) [سورة البقرة: ١٩٧]."],"en":["Allah the Exalted said: “Take provisions, for indeed the best provision is mindfulness of Allah.” [al-Baqarah: 197]"]}},"tuhfa":{},"refs":[{"key":"bukhari/الحج","label":"البخاريّ في الحجّ","number":1523}]},{"num":4749,"demo":false,"sanad":"","matn":["عن أبي لاس الخزاعيّ، قال: حملنا رسولُ اللّٰه ﷺ على إبلٍ من إبل الصدقة للحجّ، فقلنا: يا رسول اللّٰه ﷺ ما نرى أن تحملنا هذه؟ قال: (( ما من بعيرٍ لنا إلا في ذِروتِه شيطانٌ، فاذكروا اسمَ اللّٰه عليها إذا ركبتموها كما أمركم، ثم امتهنوها لأنفسكم، فإنما يحملُ اللّٰه عزّ وجلّ ))."],"takhrij":"حسن: رواه الإمام أحمد (١٧٩٣٨)، والطبرانيّ في الكبير (٢٢/٨٣٧).","grade":"حسن","chapter_ar":"باب جواز الحج على إبل الصدقة إذا أجازه الإمام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (17938) and al-Tabarani in al-Kabir (22/837).","chapter_en":"The permissibility of riding the camels of charity for pilgrimage if the ruler permits it","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Las al-Khuzaʿi reported: The Messenger of Allah ﷺ mounted us on some of the camels of charity for pilgrimage. We said: O Messenger of Allah ﷺ, we do not think these should carry us. He said: “There is no camel of ours except that on the top of its hump there is a devil. So mention the name of Allah over it when you ride it, as He commanded you, then make use of it for yourselves, for it is only Allah, Mighty and Majestic, who truly carries.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":17938},{"key":"الطبرانی/الکبیر","label":"الطبرانيّ في الكبير","number":22},{"key":"ahmad","label":"مسند الإمام أحمد","number":17938,"n":17938}]},{"num":4750,"demo":false,"sanad":"","matn":["عن ثمامة بن عبد اللّٰه بن أنس، قال: حجَّ أنسٌ على رَحلٍ ولم يكن شحيحًا، وحدّث أنَّ رسول اللّٰه ﷺ حجَّ على رحلٍ وكانت زاملتَه."],"takhrij":"صحيح: رواه البخاريّ (١٥١٧) تعليقًا، ووصله البيهقي (٤/٣٣٤).","grade":"صحيح","chapter_ar":"باب أداء الحج والعمرة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1517) in suspended form, and connected by al-Bayhaqi (4/334).","chapter_en":"Performing pilgrimage and ʿumrah riding and on foot","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Thumamah ibn ʿAbdullah ibn Anas said: Anas performed pilgrimage on a saddle, and he was not a miser. He narrated that the Messenger of Allah ﷺ performed pilgrimage on a saddle, and it was also his baggage mount."]},"buhuth":{"ar":["قوله: (( وكانت زاملته )) أي الراحلة التي ركبها، والزاملة البعير الذي يحمل عليه الطعام والمتاع من الزمل وهو الحمل. والمراد أنه لم تكن معه زاملة تحمل طعامه ومتاعه، بل كان ذلك محمولًا معه على راحلته، فكانت هي الراحلة والزاملة. انظر: فتح الباري (٣/٣٨١)."],"en":["His statement “and it was his baggage mount” means the riding animal he rode. The baggage mount is the camel used to carry food and belongings. The meaning is that he did not have a separate camel for carrying provisions and luggage. Rather, those were carried on the same animal he rode, so it served both as his ride and as his load animal."]},"intro":{"ar":["قال اللّٰه تعالى: (وَأَذِّن فِي النَّاسِ بِالْحَجِّ يَأْتُوكَ رِجَالًا وَعَلَىٰ كُلِّ ضَامِرٍ يَأْتِينَ مِن كُلِّ فَجٍّ عَمِيقٍ) [سورة الحج: ٢٧]."],"en":["Allah the Exalted said: “And proclaim the pilgrimage to the people. They will come to you on foot and on every lean camel, coming from every distant pass.” [al-Hajj: 27]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1517},{"key":"وصلہ_البیہقی","label":"وصله البيهقي","number":4},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":8651,"n":8726}]},{"num":4751,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: حجَّ النبيُّ ﷺ على رحلٍ رثٍّ، وقطيفةٍ تساوي أربعةَ دراهمَ أو لا تساوي. ثم قال: (( اللّهم حجّةً لا رياء فيها ولا سُمعة ))."],"takhrij":"حسن: رواه ابن ماجه (٢٨٩٠)، والترمذي في الشمائل (٣٣٤)، وابن أبي شيبة (٤/١٠٦).","grade":"حسن","chapter_ar":"باب أداء الحج والعمرة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (2890), al-Tirmidhi in al-Shama’il (334), and Ibn Abi Shaybah (4/106).","chapter_en":"Performing pilgrimage and ʿumrah riding and on foot","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ performed pilgrimage on a worn saddle, with a cloak worth four dirhams or not even that much. Then he said: “O Allah, a pilgrimage in which there is no showing off and no seeking reputation.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2890},{"key":"tirmidhi/الشمایل","label":"الترمذي في الشمائل","number":334},{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":4}]},{"num":4752,"demo":false,"sanad":"","matn":["عن عائشة، أنها قالت: يا رسول اللّٰه ﷺ اعتمرتُم ولم أعتمر؟ فقال: (( يا عبد الرحمن، اذهب بأختك فأعمرها من التنعيم )) فأحقبها على ناقة، فاعتمرت."],"takhrij":"متفق عليه: رواه البخاريّ (١٥١٨)، ومسلم (١٢١١)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب أداء الحج والعمرة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1518) and Muslim (1211), with the wording of al-Bukhari.","chapter_en":"Performing pilgrimage and ʿumrah riding and on foot","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["ʿA’ishah said: O Messenger of Allah ﷺ, you performed ʿumrah while I did not. He said: “O ʿAbd al-Rahman, take your sister and let her enter into ʿumrah from al-Tanʿim.” So he seated her behind him on a she-camel, and she performed ʿumrah."]},"buhuth":{"ar":["وحديث مسلم بسياق أطول، وفيه: (( فأمر عبد الرحمن بن أبي بكر فأردفني على جمله ))."],"en":["Muslim’s longer version includes: “He ordered ʿAbd al-Rahman ibn Abi Bakr to let me ride behind him on his camel.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1518},{"key":"muslim","label":"مسلم","number":1211}]},{"num":4753,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، أنَّ رسولَ اللّٰه ﷺ مرَّ بوادي الأزرق فقال: (( أيُّ وادٍ هذا؟ )) فقالوا: هذا وادي الأزرق. قال: (( كأني أنظر إلى موسى عليه السلام هابطًا من الثنية له جؤارٌ إلى اللّٰه بالتلبية ))، ثم أتى على ثنية هرشى فقال: (( أيُّ ثنيةٍ هذه؟ )) قالوا: ثنية هرشى. قال: (( كأني أرى يونس بن متى عليه السلام على ناقةٍ حمراءَ جعدةٍ عليه جبةٌ من صوفٍ، خطام ناقته خُلبةٌ، وهو يلبي ))."],"takhrij":"صحيح: رواه مسلم (١٦٦).","grade":"صحيح","chapter_ar":"باب أداء الحج والعمرة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (166).","chapter_en":"Performing pilgrimage and ʿumrah riding and on foot","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that the Messenger of Allah ﷺ passed by the Valley of al-Azraq and said: “Which valley is this?” They said: This is the Valley of al-Azraq. He said: “It is as though I am looking at Musa, peace be upon him, descending from the mountain pass, raising his voice to Allah with the talbiyah.” Then he came to the mountain pass of Harsha and said: “Which pass is this?” They said: The pass of Harsha. He said: “It is as though I see Yunus ibn Matta, peace be upon him, on a red sturdy she-camel, wearing a wool cloak, with the halter of his camel made of fiber, and he is reciting the talbiyah.”"]},"buhuth":{"ar":["وقوله: (( جؤار )) من جأر يجأر جؤارًا: رفع صوته، ويقال: جأر إلى الله، أي تضرع واستغاث. وقوله: (( خُلبة )) الليف، كما جاء في حلية الأولياء (٣/٩٦): خطامها من ليف."],"en":["The word “juār” means raising the voice. It is said that a person raises his voice to Allah in humble plea and supplication. The word “khulbah” means fiber, meaning the camel’s halter was made from fiber."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":166}]},{"num":4754,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، أنَّ رجلًا كان مع النبيِّ ﷺ فوقصته ناقته وهو محرم، فقال رسول اللّٰه ﷺ: (( اغسلوه بماءٍ وسدرٍ، وكفّنوه في ثوبيه، ولا تمسّوه بطيبٍ، ولا تخمّروا رأسه؛ فإنه يُبعث يوم القيامة ملبّيًا )).","وفي رواية: (( ولا تخمّروا رأسه ولا وجهه، فإنه يبعث يوم القيامة ملبّيًا ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٨٥١)، ومسلم (١٢٠٦). والرواية الثانية عند مسلم.","grade":"متفق عليه","chapter_ar":"باب فضل من مات محرمًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1851) and Muslim (1206). The second narration is in Muslim.","chapter_en":"The virtue of the one who dies in a state of ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that a man was with the Prophet ﷺ when his she-camel threw him down and killed him while he was in ihram. The Messenger of Allah ﷺ said: “Wash him with water and lote leaves, shroud him in his two garments, do not apply perfume to him, and do not cover his head, for he will be resurrected on the Day of Resurrection reciting the talbiyah.”","In another narration: “Do not cover his head or his face, for he will be resurrected on the Day of Resurrection reciting the talbiyah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1851},{"key":"muslim","label":"مسلم","number":1206}]},{"num":4755,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر، أنه قال حين خرج إلى مكة معتمرًا في الفتنة: إن صُدِدتُ عن البيت صنعنا كما صنعنا مع رسول اللّٰه ﷺ، فأهلَّ بعمرةٍ من أجل أنَّ رسول اللّٰه ﷺ أهلَّ بعمرةٍ عام الحديبية. ثم قال: ما أمرهما إلا واحد، ثم التفت إلى أصحابه فقال: ما أمرهما إلا واحد، أشهدكم أني قد أوجبت الحجَّ مع العمرة. ثم نفذ حتى جاء البيت فطاف طوافًا واحدًا، ورأى ذلك مجزئًا عنه، وأهدى."],"takhrij":"متفق عليه: رواه مالك (٩٩)، والبخاري (١٨٠٦)، ومسلم (١٢٣٠).","grade":"متفق عليه","chapter_ar":"باب الإحصار في الحج أو العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (99), al-Bukhari (1806), and Muslim (1230).","chapter_en":"Being prevented from completing pilgrimage or ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said, when he set out to Makkah for ʿumrah during a time of turmoil: If I am prevented from reaching the House, we will do just as we did with the Messenger of Allah ﷺ. So he entered into ihram for ʿumrah, because the Messenger of Allah ﷺ had entered ihram for ʿumrah in the year of al-Hudaybiyah. Then he said: They are only one matter. Then he turned to his companions and said: They are only one matter. Bear witness that I have bound myself to Hajj along with ʿumrah. Then he continued until he reached the House and made one circuit, and he regarded that as sufficient for him, and he offered a sacrificial animal."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":99},{"key":"bukhari","label":"البخاري","number":1806},{"key":"muslim","label":"مسلم","number":1230}]},{"num":4756,"demo":false,"sanad":"","matn":["عن نافع، أنّ عبيد اللّٰه بن عبد اللّٰه، وسالم بن عبد اللّٰه أخبراه أنهما كلّما عبدَ اللّٰه بن عمر ليالي نزل الجيش بابن الزبير، فقالا: لا يضرّك أن لا تحج العام، وإنا نخاف أن يحال بينك وبين البيت. فقال: خرجنا مع رسول اللّٰه ﷺ فحال كفّار قريش دون البيت، فنحر النبيُّ ﷺ هديه وحلق رأسه، وأشهدكم أني قد أوجبت العمرة، إن شاء اللّٰه أنطلق، فإن خُلِّي بيني وبين البيت طفت، وإن حيل بيني وبينه فعلت كما فعل النبيُّ ﷺ وأنا معه. فأهلَّ بالعمرة من ذي الحليفة، ثم سار ساعة، ثم قال: إنما شأنهما واحد، أشهدكم أني قد أوجبت حجّةً مع عمرتي. فلم يحلّ منهما حتى حلّ يوم النحر، وأهدى. وكان يقول: لا يحلّ حتى يطوف طوافًا واحدًا يوم يدخل مكة."],"takhrij":"متفق عليه: رواه البخاريّ (١٨٠٧)، ومسلم (١٢٣٠).","grade":"متفق عليه","chapter_ar":"باب الإحصار في الحج أو العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1807) and Muslim (1230).","chapter_en":"Being prevented from completing pilgrimage or ʿumrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Nafiʿ reported that ʿUbaydullah ibn ʿAbdullah and Salim ibn ʿAbdullah informed him that they spoke to ʿAbdullah ibn ʿUmar on the nights when the army came down against Ibn al-Zubayr. They said: It will not harm you if you do not perform pilgrimage this year, and we fear that you may be prevented from the House. He said: We went out with the Messenger of Allah ﷺ, and the disbelievers of Quraysh stood between us and the House, so the Prophet ﷺ slaughtered his sacrificial animal and shaved his head. I bear witness that I have committed myself to ʿumrah. If Allah wills, I will proceed. If the way to the House is opened for me, I will perform tawaf. If I am prevented from it, I will do as the Prophet ﷺ did while I was with him. So he entered ihram for ʿumrah from Dhu al-Hulayfah, then traveled for a while and said: These two matters are one. Bear witness that I have committed myself to pilgrimage together with my ʿumrah. And he did not exit from either of them until the Day of Sacrifice came, and he offered a sacrificial animal. He used to say: He does not exit until he makes one tawaf on the day he enters Makkah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1807},{"key":"muslim","label":"مسلم","number":1230}]},{"num":4757,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر، قال: أليس حسبكم سنّة رسول اللّٰه ﷺ؟ إن حُبس أحدكم عن الحجّ طاف بالبيت وبالصفا والمروة، ثم حلّ من كل شيء حتى يحجّ عامًا قابلًا، فيهدي أو يصوم إن لم يجد هديًا."],"takhrij":"صحيح: رواه البخاريّ (١٨١٠)، ومسلم (١٢٣٠).","grade":"صحيح","chapter_ar":"باب الصوم على المحصر إذا لم يجد هديًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1810) and Muslim (1230).","chapter_en":"Fasting for the one prevented, if he cannot find a sacrificial animal","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: Is not the Sunnah of the Messenger of Allah ﷺ enough for you? If one of you is prevented from pilgrimage, he performs tawaf of the House and between al-Safa and al-Marwah, then exits from all restrictions until he performs pilgrimage the following year. Then he offers a sacrificial animal, or fasts if he cannot find one."]},"intro":{"ar":["قال اللّٰه تعالى: (وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ) [سورة البقرة: ١٩٦]."],"en":["Allah the Exalted said: “Complete the pilgrimage and the ʿumrah for Allah. But if you are prevented, then offer whatever sacrificial animal is easy to obtain.” [al-Baqarah: 196]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1810},{"key":"muslim","label":"مسلم","number":1230}]},{"num":4758,"demo":false,"sanad":"","matn":["عن ميمون بن مهران قال: خرجت معتمرًا عام حاصر أهل الشام ابن الزبير بمكة، وبعث معي رجالٌ من قومي بهدي، فلما انتهينا إلى أهل الشام منعونا أن ندخل الحرم، فنحرتُ الهدي مكاني، ثم أحللتُ ثم رجعت. فلما كان من العام المقبل خرجتُ لأقضي عمرتي، فأتيت ابنَ عباس فسألته فقال: أبدل الهدي، فإن رسول اللّٰه ﷺ أمر أصحابه أن يبدلوا الهدي الذي نحروا عام الحديبية في عمرة القضاء."],"takhrij":"حسن: رواه أبو داود (١٨٦٤)، وصحّحه الحاكم (١٧٨٦).","grade":"حسن","chapter_ar":"باب إبدال الهدي في الإحصار","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1864), and authenticated by al-Hakim (1786).","chapter_en":"Replacing the sacrificial animal in the case of being prevented","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Maymun ibn Mihran said: I went out to perform ʿumrah in the year when the people of Syria besieged Ibn al-Zubayr in Makkah. Men from my people sent a sacrificial animal with me. When we reached the Syrian forces, they prevented us from entering the sanctuary, so I slaughtered the sacrificial animal where I was, then exited ihram and returned. In the following year, I went out to make up my ʿumrah and came to Ibn ʿAbbas and asked him. He said: Replace the sacrificial animal, for the Messenger of Allah ﷺ ordered his companions to replace the sacrificial animals they had slaughtered in the year of al-Hudaybiyah during the compensatory ʿumrah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1864},{"key":"hakim","label":"المستدرك على الصحيحين","number":1786,"n":1776}]},{"num":4759,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، قال: قد أُحصِر رسولُ اللّٰه ﷺ فحلق رأسه، وجامع نساءه، ونحر هديه، حتى اعتمر عامًا قابلًا."],"takhrij":"صحيح: رواه البخاريّ (١٨٠٩).","grade":"صحيح","chapter_ar":"باب هل على المحصر قضاء؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1809).","chapter_en":"Is make-up required for the one who is prevented?","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas said: The Messenger of Allah ﷺ was prevented, so he shaved his head, approached his wives, and slaughtered his sacrificial animal, until he performed ʿumrah the following year."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1809}]},{"num":4760,"demo":false,"sanad":"","matn":["عن الحجاج بن عمرو الأنصاريّ، قال: قال رسول اللّٰه ﷺ: (( من كُسِر أو عَرِج حلَّ وعليه الحجُّ من قابل ))."],"takhrij":"صحيح: رواه أبو داود (١٨٦٣)، والترمذيّ (٩٤٠)، والنسائي (٢٨٦١)، وابن ماجه (٣٠٧٧).","grade":"صحيح","chapter_ar":"باب هل على المحصر قضاء؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1863), al-Tirmidhi (940), al-Nasa’i (2861), and Ibn Majah (3077).","chapter_en":"Is make-up required for the one who is prevented?","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Al-Hajjaj ibn ʿAmr al-Ansari reported that the Messenger of Allah ﷺ said: “Whoever suffers a broken limb or becomes lame may exit ihram, and he must perform pilgrimage the following year.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1863},{"key":"tirmidhi","label":"الترمذيّ","number":940},{"key":"nasai","label":"النسائي","number":2861},{"key":"ibnmajah","label":"ابن ماجه","number":3077}]},{"num":4761,"demo":false,"sanad":"","matn":["عن ابن عباس، أن امرأةً من جهينة جاءت إلى النبي ﷺ فقالت: إن أمي نذرت أن تحج فلم تحج حتى ماتت، أفأحج عنها؟ قال: (( نعم، حُجِّي عنها، أرأيتِ لو كان على أمكِ دينٌ أكنتِ قاضيته؟ اقضوا الله، فالله أحق بالوفاء ))."],"takhrij":"صحيح: رواه البخاري (١٨٥٢).","grade":"صحيح","chapter_ar":"باب الحج عن الميت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1852).","chapter_en":"Hajj on behalf of the deceased","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas reported that a woman from Juhaynah came to the Prophet ﷺ and said: “My mother had vowed to perform Hajj, but she did not perform Hajj until she died. Should I perform Hajj on her behalf?” He said: “Yes, perform Hajj on her behalf. Tell me, if your mother had a debt, would you pay it off? Fulfill what is owed to Allah, for Allah has more right to be fulfilled.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1852}]},{"num":4762,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أتى رجلٌ النبي ﷺ فقال له: إن أختي قد نذرت أن تحج وإنها ماتت. فقال النبي ﷺ: (( لو كان عليها دينٌ أكنتَ قاضيه؟ )) قال: نعم. قال: (( فاقضِ الله، فهو أحق بالقضاء ))."],"takhrij":"صحيح: رواه البخاريّ (٦٦٩٩).","grade":"صحيح","chapter_ar":"باب الحج عن الميت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6699).","chapter_en":"Hajj on behalf of the deceased","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas reported: A man came to the Prophet ﷺ and said to him: “My sister had vowed to perform Hajj, then she died.” The Prophet ﷺ said: “If she had a debt, would you pay it off?” He said: “Yes.” He said: “Then fulfill what is owed to Allah, for He has more right to be repaid.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":6699}]},{"num":4763,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أمرت امرأةُ سنان بن سلمة الجهني أن يسأل رسول الله ﷺ أن أمها ماتت ولم تحج، أفيجزئ عن أمها أن تحج عنها؟ قال: (( نعم، لو كان على أمها دينٌ فقضته عنها ألم يكن يجزئ عنها؟ فلتحج عن أمها ))."],"takhrij":"صحيح: رواه النسائيّ (٢٦٣٣).","grade":"صحيح","chapter_ar":"باب الحج عن الميت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (2633).","chapter_en":"Hajj on behalf of the deceased","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas reported that a woman instructed Sinan ibn Salamah al-Juhani to ask the Messenger of Allah ﷺ: “Her mother died without having performed Hajj. Will it count for her mother if she performs Hajj on her behalf?” He said: “Yes. If her mother had a debt and she paid it off for her, would that not count for her? Then let her perform Hajj on behalf of her mother.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2633}]},{"num":4764,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: جاء رجل إلى النبي ﷺ فقال: إن أبي مات ولم يحج، أفأحج عنه؟ قال: (( أرأيت لو كان على أبيك دين أكنت قاضيه؟ )) قال: نعم. قال: (( فدين الله عز وجل أحق، حج عنه ))."],"takhrij":"صحيح: رواه الطحاوي في شرح المشكل (٢٥٤٢)، وابن حبان (٣٩٩٢)، والطبراني (١٥/١٣).","grade":"صحيح","chapter_ar":"باب الحج عن الميت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tahawi in Sharh al-Mushkil (2542), Ibn Hibban (3992), and al-Tabarani (15/13).","chapter_en":"Hajj on behalf of the deceased","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas reported: A man came to the Prophet ﷺ and said: “My father died and did not perform Hajj. Should I perform Hajj on his behalf?” He said: “Tell me, if your father had a debt, would you pay it off?” He said: “Yes.” He said: “The debt owed to Allah, the Mighty and Majestic, has more right to be fulfilled. Perform Hajj on his behalf.”"]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرح_المشکل","label":"الطحاوي في شرح المشكل","number":2542},{"key":"الطبرانی","label":"الطبراني","number":15},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4358,"n":4354}]},{"num":4765,"demo":false,"sanad":"","matn":["عن بريدة، قال: بينا أنا جالس عند رسول الله ﷺ إذ أتته امرأة فقالت: إنها — تعني أمها — ماتت ولم تحج قط، أفأحج عنها؟ قال: (( حجي عنها ))."],"takhrij":"صحيح: رواه مسلم (١١٤٩).","grade":"صحيح","chapter_ar":"باب الحج عن الميت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1149).","chapter_en":"Hajj on behalf of the deceased","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Buraydah reported: While I was sitting with the Messenger of Allah ﷺ, a woman came to him and said, meaning her mother had died, “She never performed Hajj at all. Should I perform Hajj on her behalf?” He said: “Perform Hajj on her behalf.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1149}]},{"num":4766,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: جاء رجل إلى النبي ﷺ فقال: إن أبي مات ولم يحج حجة الإسلام. فقال رسول الله ﷺ: (( أرأيت لو كان على أبيك دين أكنت تقضيه عنه؟ )) قال: نعم. قال: (( فإنه دين عليه فاقضه ))."],"takhrij":"حسن: رواه البزّار (١١٤٥ - كشف الأستار) والطّبراني في الكبير (٧٤٨)، والأوسط (١٠٠). واللفظ للبزار.","grade":"حسن","chapter_ar":"باب الحج عن الميت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar (1145, Kashf al-Astar), al-Tabarani in al-Kabir (748), and al-Awsat (100). The wording is that of al-Bazzar.","chapter_en":"Hajj on behalf of the deceased","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Anas ibn Malik reported: A man came to the Prophet ﷺ and said: “My father died without performing the obligatory Hajj of Islam.” The Messenger of Allah ﷺ said: “Tell me, if your father had a debt, would you pay it off on his behalf?” He said: “Yes.” He said: “Then it is a debt upon him, so fulfill it.”"]},"buhuth":{"ar":["ولفظ الطبراني: (( حجّ عن أبيك))."],"en":["And al-Tabarani’s wording is: “Perform Hajj on behalf of your father.”"]}},"tuhfa":{},"refs":[{"key":"البزار","label":"البزّار","number":1145},{"key":"الطبرانی/الکبیر","label":"الطّبراني في الكبير","number":748},{"key":"الاوسط","label":"الأوسط","number":100}]},{"num":4767,"demo":false,"sanad":"","matn":["عن الفضل بن عباس، أن امرأة من خثعم قالت: يا رسول الله، إن أبي شيخ كبير عليه فريضة الله في الحج، وهو لا يستطيع أن يستوي على ظهر بعيره. فقال النبي ﷺ: (( فحجي عنه ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٨٥٣)، ومسلم (١٣٣٥) ، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الحجّ عن العاجز لهرم وزمانة ونحوها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1853) and Muslim (1335). The wording is that of Muslim.","chapter_en":"Hajj on behalf of one unable due to old age, chronic disability, and similar reasons","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Al-Fadl ibn Abbas reported that a woman from Khath‘am said: “O Messenger of Allah ﷺ, my father is an old man, and the obligation of Hajj from Allah is due upon him, but he is unable to remain seated firmly on the back of his camel.” The Prophet ﷺ said: “Then perform Hajj on his behalf.”"]},"buhuth":{"ar":["وقوله: (( حُجّي عنه ) فيه دليل على حجّ المرأة عن الرجل، وبه بوّبه النسائي (٢٦٤٣)، وابن خزيمة (٣٠٣٣)، وذكرا فيه هذا الحديث."],"en":["His statement, “Perform Hajj on his behalf,” is evidence that a woman may perform Hajj on behalf of a man. Al-Nasa’i (2643) and Ibn Khuzaymah (3033) placed this hadith under that heading."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1853},{"key":"muslim","label":"مسلم","number":1335}]},{"num":4768,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: كان الفضل بن عباس رديف رسول الله ﷺ، فجاءته امرأة من خثعم تستفتيه، فجعل الفضل ينظر إليها وتنظر إليه، فجعل رسول الله ﷺ يصرف وجه الفضل إلى الشق الآخر، فقالت: يا رسول الله، إن فريضة الله في الحج أدركت أبي شيخًا كبيرًا لا يستطيع أن يثبت على الراحلة، أفأحج عنه؟ قال: (( نعم )). وذلك في حجة الوداع."],"takhrij":"متفق عليه: رواه مالك (٩٧) والبخاريّ (١٨٥٥)، ومسلم (١٣٣٤).","grade":"متفق عليه","chapter_ar":"باب الحجّ عن العاجز لهرم وزمانة ونحوها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (97), al-Bukhari (1855), and Muslim (1334).","chapter_en":"Hajj on behalf of one unable due to old age, chronic disability, and similar reasons","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abdullah ibn Abbas reported: Al-Fadl ibn Abbas was riding behind the Messenger of Allah ﷺ when a woman from Khath‘am came to ask him a ruling. Al-Fadl began looking at her, and she looked at him, so the Messenger of Allah ﷺ kept turning al-Fadl’s face to the other side. She said: “O Messenger of Allah ﷺ, the obligation of Hajj from Allah has come upon my father while he is an old man who cannot remain firm on the riding animal. May I perform Hajj on his behalf?” He said: “Yes.” And that was during the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":97},{"key":"bukhari","label":"البخاريّ","number":1855},{"key":"muslim","label":"مسلم","number":1334}]},{"num":4769,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: جاء رجل إلى النبي ﷺ فقال: أحج عن أبي؟ قال: (( نعم، حج عن أبيك، فإن لم تزده خيرًا لم تزده شرًّا ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٩٠٤).","grade":"صحيح","chapter_ar":"باب الحجّ عن العاجز لهرم وزمانة ونحوها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2904).","chapter_en":"Hajj on behalf of one unable due to old age, chronic disability, and similar reasons","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Ibn Abbas said: A man came to the Prophet ﷺ and said, “Should I perform Hajj on behalf of my father?” He said, “Yes, perform Hajj on behalf of your father. If you do not add good for him, you will not add harm to him.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2904}]},{"num":4770,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أن رجلًا سأل النبي ﷺ: إن أبي أدركه الحج وهو شيخ كبير لا يثبت على راحلته، فإن شددته خشيت أن يموت، أفأحج عنه؟ قال: (( أرأيت لو كان عليه دين فقضيته أكان مجزئًا؟ )) قال: نعم. قال: (( فحج عن أبيك ))."],"takhrij":"صحيح: رواه النسائيّ (٥٣٩٣ ،٢٦٤٠).","grade":"صحيح","chapter_ar":"باب الحجّ عن العاجز لهرم وزمانة ونحوها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5393, 2640).","chapter_en":"Hajj on behalf of one unable due to old age, chronic disability, and similar reasons","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abdullah ibn Abbas reported that a man asked the Prophet ﷺ, “My father has become so old that he cannot remain firm on his riding animal, and if I tie him onto it, I fear he may die. Should I perform Hajj on his behalf?” He said, “Tell me, if your father had a debt and you paid it off, would that suffice?” He said, “Yes.” He said, “Then perform Hajj on behalf of your father.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":5393}]},{"num":4771,"demo":false,"sanad":"","matn":["عن أبي رزين — رجل من بني عامر — أنه قال: يا رسول الله، إن أبي شيخ كبير لا يستطيع الحج ولا العمرة ولا الظعن. قال: (( حج عن أبيك واعتمر ))."],"takhrij":"صحيح: رواه أبو داود (١٨١٠)، والترمذي (٩٣٠)، والنسائي (٢٦٣٧)، وابن ماجه (٢٩٠٦).","grade":"صحيح","chapter_ar":"باب الحجّ عن العاجز لهرم وزمانة ونحوها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1810), al-Tirmidhi (930), al-Nasa’i (2637), and Ibn Majah (2906).","chapter_en":"Hajj on behalf of one unable due to old age, chronic disability, and similar reasons","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abu Razin, a man from Banu Amir, said: “O Messenger of Allah ﷺ, my father is a very old man and is unable to perform Hajj, nor Umrah, nor travel.” He said, “Perform Hajj on behalf of your father, and perform Umrah.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1810},{"key":"tirmidhi","label":"الترمذي","number":930},{"key":"nasai","label":"النسائي","number":2637},{"key":"ibnmajah","label":"ابن ماجه","number":2906}]},{"num":4772,"demo":false,"sanad":"","matn":["عن عبد الله بن الزبير، قال: جاء رجل من خثعم إلى رسول الله ﷺ فقال: إن أبي شيخ كبير لا يستطيع الركوب، وأدركته فريضة الله في الحج، فهل يجزئ أن أحج عنه؟ قال: (( أنت أكبر ولده؟ )) قال: نعم. قال: (( أرأيت لو كان عليه دين أكنت تقضيه؟ )) قال: نعم. قال: (( فحج عنه ))."],"takhrij":"حسن: رواه النسائيّ (٢٦٣٨).","grade":"حسن","chapter_ar":"باب الحجّ عن العاجز لهرم وزمانة ونحوها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (2638).","chapter_en":"Hajj on behalf of one unable due to old age, chronic disability, and similar reasons","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abdullah ibn al-Zubayr said: A man from Khath‘am came to the Messenger of Allah ﷺ and said: “My father is an old man who cannot ride, and the obligation of Hajj from Allah has come upon him. Will it be sufficient if I perform Hajj on his behalf?” He said, “Are you his eldest child?” He said, “Yes.” He said, “Tell me, if he had a debt, would you repay it?” He said, “Yes.” He said, “Then perform Hajj on his behalf.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2638}]},{"num":4773,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أن النبي ﷺ سمع رجلًا يقول: لبيك عن شبرمة. قال: (( من شبرمة؟ )) قال: أخ لي أو قريب لي. قال: (( حججت عن نفسك؟ )) قال: لا. قال: (( حج عن نفسك، ثم حج عن شبرمة ))."],"takhrij":"صحيح: رواه أبو داود (١٨١١)، وابن ماجه (٢٩٠٣)، وصححه ابن خزيمة (٣٠٣٩)، وابن حبان (٣٩٨٨).","grade":"صحيح","chapter_ar":"باب النهي أن يحج عن الميت من لم يحج عن نفسه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1811), Ibn Majah (2903), and authenticated by Ibn Khuzaymah (3039) and Ibn Hibban (3988).","chapter_en":"Prohibition of performing Hajj on behalf of the deceased before performing Hajj for oneself","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Abdullah ibn Abbas reported that the Prophet ﷺ heard a man saying: “Labbayka on behalf of Shubrumah.” He said, “Who is Shubrumah?” He said, “A brother of mine, or a relative of mine.” He said, “Have you performed Hajj on your own behalf?” He said, “No.” He said, “Perform Hajj for yourself first, then perform Hajj on behalf of Shubrumah.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1811},{"key":"ibnmajah","label":"ابن ماجه","number":2903},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":3039},{"key":"ibnhibban","label":"ابن حبان","number":3988}]},{"num":4774,"demo":false,"sanad":"","matn":["عن ابن عباس، أن رسول الله ﷺ مر بامرأة وهي في محفتها، فقيل لها: هذا رسول الله. فأخذت بضبعي صبي كان معها فقالت: ألهذا حج يا رسول الله؟ قال: (( نعم، ولك أجر ))."],"takhrij":"صحيح: رواه مالك (٢٤٤). ورواه مسلم (١٣٣٦) بلفظ: أن النبي ﷺ لقي ركبًا بالروحاء فقال: (( من القوم؟ )) قالوا: المسلمون. فقالوا: من أنت؟ قال: (( رسول الله )). فرفعت إليه امرأة صبيًّا فقالت: ألهذا حج؟ قال: (( نعم، ولك أجر )).","grade":"صحيح","chapter_ar":"باب حجّ الصّبي وأجره لمن حجّ به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (244). Muslim (1336) also narrated it with the wording: The Prophet ﷺ met a caravan at al-Rawha’ and said, “Who are these people?” They said, “The Muslims.” They said, “Who are you?” He said, “The Messenger of Allah ﷺ.” Then a woman lifted a child up to him and said, “Does this child have a Hajj?” He said, “Yes, and you will have a reward.”","chapter_en":"The Hajj of a child and the reward for the one who takes him for Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Ibn Abbas reported that the Messenger of Allah ﷺ passed by a woman while she was in her howdah. It was said to her, “This is the Messenger of Allah ﷺ.” So she lifted up a child who was with her by his upper arms and said, “Does this count as Hajj for him, O Messenger of Allah ﷺ?” He said, “Yes, and you will have a reward.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":244},{"key":"ورواہ_مسلم","label":". ورواه مسلم","number":1336}]},{"num":4775,"demo":false,"sanad":"","matn":["عن الجعيد بن عبد الرحمن، قال: سمعت عمر بن عبد العزيز يقول للسائب بن يزيد وكان قد حُجَّ به في ثَقَلِ النَّبِيِّ ﷺ."],"takhrij":"صحيح: رواه البخاري (١٨٥٩). ورواه أيضًا (١٨٥٨) وفيه: (( حُجَّ بي مع رسول الله ﷺ وأنا ابن سبع سنين )).","grade":"صحيح","chapter_ar":"باب حجّ الصّبي وأجره لمن حجّ به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1859), and he also narrated it in (1858), in which it says: “I was taken for Hajj with the Messenger of Allah ﷺ when I was seven years old.”","chapter_en":"The Hajj of a child and the reward for the one who takes him for Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Al-Ju‘ayd ibn Abd al-Rahman said: I heard Umar ibn Abd al-Aziz speaking to al-Sa’ib ibn Yazid, and he had been taken for Hajj with the baggage train of the Prophet ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1859},{"key":"ورواہ_ایضا","label":". ورواه أيضًا","number":1858}]},{"num":4776,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: رفعت امرأة صبيًّا لها إلى رسول الله ﷺ فقالت: يا رسول الله، ألهذا حج؟ قال: (( نعم، ولك أجر ))."],"takhrij":"صحيح: رواه الترمذي (٩٢٤)، وابن ماجه (٢٩١٠)، والبيهقي (١٥٦/٥).","grade":"صحيح","chapter_ar":"باب حجّ الصّبي وأجره لمن حجّ به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (924), Ibn Majah (2910), and al-Bayhaqi (5/156).","chapter_en":"The Hajj of a child and the reward for the one who takes him for Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في وجوب الحجّ وفضله وشروطه","group_en":"Sections on the obligation of pilgrimage, its virtue, and its conditions","part_no":16,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Jabir ibn Abdullah said: A woman lifted up her child to the Messenger of Allah ﷺ and said, “O Messenger of Allah ﷺ, does this child have a Hajj?” He said, “Yes, and you will have a reward.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":924},{"key":"ibnmajah","label":"ابن ماجه","number":2910},{"key":"البیہقی","label":"البيهقي","number":156},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":9709,"n":9791}]},{"num":4777,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خرجنا مع رسول الله ﷺ مهلين بالحج في أشهر الحج، وفي حرم الحج، وليالي الحج حتى نزلنا بسرف... الحديث."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٦٠)، ومسلم (١٢٣ :١٢١١).","grade":"متفق عليه","chapter_ar":"باب المواقيت الزمانية في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1560) and Muslim (1211/123).","chapter_en":"The temporal boundaries for Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Aishah said: We set out with the Messenger of Allah ﷺ declaring the intention for Hajj during the months of Hajj, in the sacred state of Hajj, and in the nights of Hajj, until we came down at Sarif… the hadith continues."]},"buhuth":{"ar":["قوله: « وحُرُم الحج » بضم الحاء المهملة والرّاء أي أزمنته وأمكنته وحالاته، ورُوي بفتح الراء «حَرَم» جمع حُرمة أي ممنوعات الحج ومحرماته. انظر: فتح الباري (٤٢١/٣)."],"en":["His statement, “the sacred state of Hajj,” with the letters read with a rounded pronunciation, means its times, places, and conditions. It was also narrated with an open pronunciation meaning “sanctities,” the plural of sanctity, that is, the prohibitions and forbidden matters of Hajj. See Fath al-Bari (3/421)."]},"intro":{"ar":["قال اله تعالى: ( يَكُونَكَ عَنِ الأَهِلَّةِ قُلْ هِيَ مَوَاقِيتُ لِلنَّاس وَالْحَجِّ [سورة البقرة: ١٨٩ ].","قال ابن جرير الطبريّ: (( وجعلها أيضاً ميقاتاً لحجُّكم تعرفون بها وقت مناسككم وحجُّكم)». تفسيره (٢٨٣ (٣).","قال اللّه تعالى: ( الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ} [البقرة: ١٩٧].","أجمع العلماء على أنّ المراد بأشهر الحجّ ثلاثة: شوال، وذو القعدة، وذو الحجة، لكن اختلفوا هل هي ثلاثة بكم إلها، أو شهران وبعض الثالث.","فقال بعضهم: يعني بالأشهر المعلومات: شوالاً، وذا القعدة، وعشراً من ذي الحجة، هكذا ذكره البخاري عن ابن عمر معلقا عقب حديث رقم (١٥٥٩)، ونقله ابن جرير الطبري في تفسيره عن جماعة من الصحابة وغيرهم.","وقال بعضهم: بل يعني بذلك شوالا، وذا القعدة، وذا الحجة كلَّه","قال ابن عباس: “ من السنة ألا تحرم بالحج إلا في أشهر الحج “ ذكره البخاري معلقا عقب حديث رقم (١٥٥٩)، ونقله ابن جرير في تفسيره عن جماعة من التابعين أيضًا.","يعني لا يجوز نية الإحرام بالحج إلا في أشهر معلومات، بخلاف العمرة فإنها تجوز في السنة كلها."],"en":["Allah the Exalted said: “They ask you about the new moons. Say: They are markers of time for people and for Hajj.” [Surah al-Baqarah: 189]","Ibn Jarir al-Tabari said: “He also made them a time marker for your pilgrimage, by which you know the timing of your rites and your Hajj.” Tafsir (3/283).","Allah the Exalted said: “Hajj is during well-known months.” [al-Baqarah: 197]","The scholars agreed that what is meant by the months of Hajj are three: Shawwal, Dhu al-Qi’dah, and Dhu al-Hijjah. But they differed over whether they are three full months, or two months and part of the third.","Some of them said that the well-known months are Shawwal, Dhu al-Qi’dah, and the first ten days of Dhu al-Hijjah. This is how al-Bukhari mentioned it from Ibn Umar in a suspended report after hadith number (1559), and Ibn Jarir al-Tabari also reported it in his Tafsir from a group of Companions and others.","And some of them said: rather, it means Shawwal, Dhu al-Qi’dah, and all of Dhu al-Hijjah.","Ibn Abbas said: “It is from the Sunnah that one should not enter into Hajj except during the months of Hajj.” Al-Bukhari mentioned it in a suspended report after hadith number (1559), and Ibn Jarir also reported it in his Tafsir from a group of the Successors.","This means that intending consecration for Hajj is not valid except during the known months, unlike Umrah, which is allowed throughout the entire year."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1560},{"key":"muslim","label":"مسلم","number":123}]},{"num":4778,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أن رسول الله ﷺ قال: (( يهل أهل المدينة من ذي الحليفة، وأهل الشام من الجحفة، ويهل أهل نجد من قرن )). قال عبد الله بن عمر: وبلغني أن رسول الله ﷺ قال: (( ويهل أهل اليمن من يلملم ))."],"takhrij":"متفق عليه: رواه مالك (٢٢) والبخاريّ (١٥٢٥)، ومسلم (١٣ :١١٨٢).","grade":"متفق عليه","chapter_ar":"باب ميقات أهل المدينة والشام ونجد واليمن","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (22), al-Bukhari (1525), and Muslim (1182/13).","chapter_en":"The boundary points for the people of Madinah, the Levant, Najd, and Yemen","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Umar narrated that the Messenger of Allah ﷺ said: “The people of Madinah enter into consecration from Dhu al-Hulayfah, the people of the Levant from al-Juhfah, and the people of Najd from Qarn.” Abdullah ibn Umar said: And it reached me that the Messenger of Allah ﷺ also said: “And the people of Yemen enter into consecration from Yalamlam.”"]},"buhuth":{"ar":["ورواه مالك أيضًا (٢٣): (( أمر رسول الله ﷺ أهل المدينة أن يهلوا من ذي الحليفة، وأهل الشام من الجحفة، وأهل نجد من قرن )). قال عبد الله بن عمر: أما هؤلاء الثلاث فسمعتهن من رسول الله ﷺ، وبلغني أن رسول الله ﷺ قال: (( ويهل أهل اليمن من يلملم )). رواه البخاري (١٥٢٨)، ومسلم (١١٨٢/١٤)."],"en":["Malik also narrated (23): “The Messenger of Allah ﷺ instructed the people of Madinah to enter into consecration from Dhu al-Hulayfah, the people of the Levant from al-Juhfah, and the people of Najd from Qarn.” Abdullah ibn Umar said: As for these three, I heard them from the Messenger of Allah ﷺ, and I was informed that the Messenger of Allah ﷺ said: “And the people of Yemen enter into consecration from Yalamlam.” Narrated by al-Bukhari (1528) and Muslim (1182/14)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":22},{"key":"bukhari","label":"البخاريّ","number":1525},{"key":"muslim","label":"مسلم","number":13}]},{"num":4779,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أنه قال: بيداؤكم هذه التي تكذبون على رسول الله ﷺ فيها؛ ما أهل رسول الله ﷺ إلا من عند المسجد، يعني مسجد ذي الحليفة."],"takhrij":"متفق عليه: رواه مالك (٣٠) والبخاريّ (١٥٤١)، ومسلم (١١٨٦).","grade":"متفق عليه","chapter_ar":"باب ميقات أهل المدينة والشام ونجد واليمن","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (30), al-Bukhari (1541), and Muslim (1186).","chapter_en":"The boundary points for the people of Madinah, the Levant, Najd, and Yemen","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Umar said: “This desert plain of yours, regarding which you wrongly attribute things to the Messenger of Allah ﷺ, the Messenger of Allah ﷺ only entered into consecration from beside the mosque,” meaning the mosque of Dhu al-Hulayfah."]},"buhuth":{"ar":["قوله: (( بيداؤكم ) البيداء: أرض واسعة عند نهاية ذي الحليفة في الاتجاه إلى مكة."],"en":["His statement, “your desert plain”: al-Bayda’ is a wide open land at the end of Dhu al-Hulayfah in the direction of Makkah."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":30},{"key":"bukhari","label":"البخاريّ","number":1541},{"key":"muslim","label":"مسلم","number":1186}]},{"num":4780,"demo":false,"sanad":"","matn":["عن زيد بن جبير، أنه أتى عبد الله بن عمر في منزله — وله فسطاط وسرادق — فسأله: من أين يجوز أن أعتمر؟ قال: فرضها رسول الله ﷺ لأهل نجد قرنًا، ولأهل المدينة ذا الحليفة، ولأهل الشام الجحفة."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٢٢) ومسلم (١١٨٢).","grade":"متفق عليه","chapter_ar":"باب ميقات أهل المدينة والشام ونجد واليمن","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1522) and Muslim (1182).","chapter_en":"The boundary points for the people of Madinah, the Levant, Najd, and Yemen","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Zayd ibn Jubayr reported that he came to Abdullah ibn Umar in his home, where he had a tent and an enclosure, and asked him: From where may I enter into Umrah? He said: The Messenger of Allah ﷺ designated Qarn for the people of Najd, Dhu al-Hulayfah for the people of Madinah, and al-Juhfah for the people of the Levant."]},"buhuth":{"ar":["قوله: (( وله فسطاط وسرادق ) المراد بالفسطاط: الخيمة، وهو أيضاً مما يغطى به صحن الدار من الشمس وغيرها. والسّرادق: هو ما أحاط بالشيء، ومنه قوله تعالى: ( إِنَّا أَعْتَدْنَا لِلظَّالِمِينَ نَارًا أَحَاطَ بِهِمْ سُرَادِقُهَا ) [الكهف: ٢٩]."],"en":["His statement, “and he had a tent and an enclosure”: what is meant by a tent is a shelter, and it may also refer to something used to cover the courtyard of a house from the sun and other things. An enclosure means that which surrounds a thing. From this is the saying of Allah: “We have prepared for the wrongdoers a fire whose walls will surround them.” [al-Kahf: 29]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1522},{"key":"muslim","label":"مسلم","number":1182}]},{"num":4781,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: وقت رسول الله ﷺ لأهل المدينة ذا الحليفة، ولأهل الشام الجحفة، ولأهل نجد قرن المنازل، ولأهل اليمن يلملم، فهن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة، فمن كان دونهن فمهله من أهله، وكذلك حتى أهل مكة يهلون منها."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٢٦)، ومسلم (١١ :١١٨١).","grade":"متفق عليه","chapter_ar":"باب ميقات أهل المدينة والشام ونجد واليمن","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1526) and Muslim (1181/11).","chapter_en":"The boundary points for the people of Madinah, the Levant, Najd, and Yemen","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ fixed Dhu al-Hulayfah for the people of Madinah, al-Juhfah for the people of the Levant, Qarn al-Manazil for the people of Najd, and Yalamlam for the people of Yemen. These are for them and for anyone who comes through them from elsewhere intending Hajj or Umrah. Whoever is within these boundaries, then his place of entering into consecration is from where he lives, and likewise the people of Makkah enter into consecration from there."]},"buhuth":{"ar":["وقوله: «ممن أراد الحج والعمرة» فيه بيان أن الإحرام من هذه المواقيت إنما يجب على من كان مروره بها قاصدًا حجًّا أو عمرة دون من لم يرد شيئًا منهما، فلو أن مدنيًّا مرّ بذي الحليفة وهو لا يريد حجًّا ولا عمرة فسار حتى قرب من الحرم، فأراد الحج أو العمرة، فإنه يحرم من حيث حضرته النية ولا يجب عليه دم كما يجب على من خرج من بيته يريد الحجّ أو العمرة فطوى الميقات وأحرم بعد ما جاوزه. أفاده الخطابي.","قوله: “فمن كان دونهن فمهله من أهله” أي ميقاته منزله وبيته ولا يجاوزه من غير إحرام إن أراد الحج والعمرة، وأما أهل مكة فإن أرادوا الحج فيهل من بيته، وإن أراد العمرة فيخرج إلى الحل، ويحرم منه."],"en":["His statement, “for whoever intends Hajj and Umrah,” shows that entering into consecration from these appointed places is only required for the one passing through them intending Hajj or Umrah, not for one who intends neither. So if a man from Madinah passes by Dhu al-Hulayfah not intending Hajj or Umrah, then later, near the sanctuary, he decides to perform Hajj or Umrah, he enters into consecration from the place where the intention came to him, and no sacrificial penalty is due from him, unlike the one who left his home intending Hajj or Umrah, passed the appointed place, and only entered into consecration after going beyond it. This was taken from al-Khattabi.","His statement, “Whoever is within them, then his place of entering into consecration is from his family,” means his appointed place is his home and residence, and he should not go beyond it without entering into consecration if he intends Hajj or Umrah. As for the people of Makkah, if they intend Hajj, they enter into consecration from their homes; and if they intend Umrah, they go out to the area outside the sanctuary and enter into consecration from there."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1526},{"key":"muslim","label":"مسلم","number":11}]},{"num":4782,"demo":false,"sanad":"","matn":["عن أبي الزبير أنه سمع جابر بن عبد الله رضي الله عنهما يسأل عن المهل، فقال: سمعت — أحسبه رفع إلى النبي ﷺ — فقال: (( مهل أهل المدينة من ذي الحليفة، والطريق الآخر الجحفة، ومهل أهل العراق من ذات عرق، ومهل أهل نجد من قرن، ومهل أهل اليمن من يلملم ))."],"takhrij":"صحيح: رواه مسلم (١١٨٣).","grade":"صحيح","chapter_ar":"باب من قال: إن النبيّ وقت لأهل العراق ذات عرق","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1183).","chapter_en":"Those who said that the Prophet ﷺ designated Dhat Irq for the people of Iraq","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abu al-Zubayr reported that he heard Jabir ibn Abdullah, may Allah be pleased with them both, being asked about the place of entering into consecration. He said — and I think he raised it to the Prophet ﷺ —: “The place of entering into consecration for the people of Madinah is Dhu al-Hulayfah, and the other route is al-Juhfah; for the people of Iraq it is Dhat Irq, for the people of Najd it is Qarn, and for the people of Yemen it is Yalamlam.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1183}]},{"num":4783,"demo":false,"sanad":"","matn":["عن عائشة، قالت: وقت رسول الله ﷺ لأهل المدينة ذا الحليفة، ولأهل الشام ومصر الجحفة، ولأهل العراق ذات عرق، ولأهل نجد قرنًا، ولأهل اليمن يلملم."],"takhrij":"صحيح: رواه النسائي (٢٦٥٦).","grade":"صحيح","chapter_ar":"باب من قال: إن النبيّ وقت لأهل العراق ذات عرق","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (2656).","chapter_en":"Those who said that the Prophet ﷺ designated Dhat Irq for the people of Iraq","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ appointed Dhu al-Hulayfah for the people of Madinah, al-Juhfah for the people of the Levant and Egypt, Dhat Irq for the people of Iraq, Qarn for the people of Najd, and Yalamlam for the people of Yemen."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2656}]},{"num":4784,"demo":false,"sanad":"","matn":["عن ابن عمر، عن رسول الله ﷺ أنه وقت لأهل المدينة ذا الحليفة، ولأهل الشام الجحفة، ولأهل نجد قرنًا، ولأهل العراق ذات عرق، ولأهل اليمن يلملم."],"takhrij":"صحيح: رواه الإمام أحمد ( ٥٤٩٢).","grade":"صحيح","chapter_ar":"باب من قال: إن النبيّ وقت لأهل العراق ذات عرق","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (5492).","chapter_en":"Those who said that the Prophet ﷺ designated Dhat Irq for the people of Iraq","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar narrated from the Messenger of Allah ﷺ that he appointed Dhu al-Hulayfah for the people of Madinah, al-Juhfah for the people of the Levant, Qarn for the people of Najd, Dhat Irq for the people of Iraq, and Yalamlam for the people of Yemen."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":5492},{"key":"ahmad","label":"مسند الإمام أحمد","number":5492,"n":5492}]},{"num":4785,"demo":false,"sanad":"","matn":["عن الحارث بن عمرو السهمي، قال: أتيت رسول الله ﷺ وهو بمنى أو بعرفات وقد أطاف به الناس، قال: فتجيء الأعراب فإذا رأوا وجهه قالوا: هذا وجه مبارك. قال: ووقت ذات عرق لأهل العراق."],"takhrij":"حسن: رواه أبو داود ( ١٧٤٢).","grade":"حسن","chapter_ar":"باب من قال: إن النبيّ وقت لأهل العراق ذات عرق","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1742).","chapter_en":"Those who said that the Prophet ﷺ designated Dhat Irq for the people of Iraq","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Al-Harith ibn Amr al-Sahmi said: I came to the Messenger of Allah ﷺ while he was in Mina or in Arafat, and the people were gathered around him. The desert Arabs would come, and when they saw his face they would say, “This is a blessed face.” He said: And he appointed Dhat Irq for the people of Iraq."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1742}]},{"num":4786,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: لما فتح هذان المصران أتوا عمر فقالوا: يا أمير المؤمنين، إن رسول الله ﷺ حد لأهل نجد قرنًا، وهو جور عن طريقنا، وإنا إن أردنا قرنًا شق علينا. قال: فانظروا حذوها من طريقكم. فحد لهم ذات عرق."],"takhrij":"صحيح: رواه البخاري (١٥٣١) .","grade":"صحيح","chapter_ar":"باب أنّ أمير المؤمنين عمر بن الخطاب وقت لأهل العراق ذات عرق","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1531).","chapter_en":"That the Commander of the Believers, Umar ibn al-Khattab, appointed Dhat Irq for the people of Iraq","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Umar said: When these two garrison cities were opened, the people came to Umar and said: “O Commander of the Believers, the Messenger of Allah ﷺ fixed Qarn for the people of Najd, but it is off our route, and if we go to Qarn it is difficult for us.” He said: “Then look for a place in line with it on your route.” So he fixed Dhat Irq for them."]},"buhuth":{"ar":["قوله: ((المصران)) تثنية مصر، والمراد بها الكوفة والبصرة وهما بالعراق."],"en":["His statement, “the two garrison cities,” is the dual form of a settlement, and what is meant by them here is Kufah and Basrah, both in Iraq."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1531}]},{"num":4787,"demo":false,"sanad":"","matn":["عن أنس، أن رسول الله ﷺ دخل مكة عام الفتح وعلى رأسه المغفر، فلما نزعه جاء رجل فقال له: يا رسول الله، ابن خطل متعلق بأستار الكعبة. فقال رسول الله ﷺ: (( اقتلوه ))."],"takhrij":"متفق عليه: رواه مالك (٢٤٧)، والبخاريّ (١٨٤٦)، ومسلم (١٣٥٧).","grade":"متفق عليه","chapter_ar":"باب جواز دخول مكة بغير إحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (247), al-Bukhari (1846), and Muslim (1357).","chapter_en":"The permissibility of entering Makkah without consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ entered Makkah in the year of the Conquest while wearing a metal helmet on his head. When he removed it, a man said to him: “O Messenger of Allah ﷺ, Ibn Khatal is clinging to the curtains of the Ka’bah.” So the Messenger of Allah ﷺ said: “Kill him.”"]},"buhuth":{"ar":["قوله: (( المغفر) هو ما يلبس على الرأس من درع الحديد مثل القلنسوة."],"en":["His statement, “helmet,” means what is worn on the head from iron armor, like a protective cap."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":247},{"key":"bukhari","label":"البخاريّ","number":1846},{"key":"muslim","label":"مسلم","number":1357}]},{"num":4788,"demo":false,"sanad":"","matn":["عن جابر، أن رسول الله ﷺ دخل مكة وعليه عمامة سوداء بغير إحرام. وفي لفظ: أن النبي ﷺ دخل يوم فتح مكة وعليه عمامة سوداء."],"takhrij":"صحيح: رواه مسلم (١٣٥٨).","grade":"صحيح","chapter_ar":"باب جواز دخول مكة بغير إحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1358).","chapter_en":"The permissibility of entering Makkah without consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Jabir reported that the Messenger of Allah ﷺ entered Makkah wearing a black turban, without being in consecration. In another wording: The Prophet ﷺ entered on the day of the Conquest of Makkah wearing a black turban."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1358}]},{"num":4789,"demo":false,"sanad":"","matn":["عن عمرو بن حريث، قال: (( كأني أنظر إلى رسول الله ﷺ على المنبر وعليه عمامة سوداء قد أرخى طرفيها بين كتفيه ))."],"takhrij":"صحيح: رواه مسلم (١٣٥٩).","grade":"صحيح","chapter_ar":"باب جواز دخول مكة بغير إحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1359).","chapter_en":"The permissibility of entering Makkah without consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب المواقيت","group_en":"Sections on the appointed boundaries","part_no":16,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Amr ibn Hurayth said: It is as though I can still see the Messenger of Allah ﷺ on the pulpit, wearing a black turban, with its two ends hanging between his shoulders."]},"buhuth":{"ar":["وفيه دليل لمن يقول: إنه لا يجب الإحرام إلا على من دخل مكة لأحد النسكين، وأما من أراد مجرد الدخول فليس عليه الإحرام على الأصح من أقوال أهل العلم."],"en":["In this is evidence for those who say that consecration is only required for one entering Makkah for one of the two rites. As for the one who only intends entry itself, consecration is not required from him according to the strongest view among the scholars."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1359}]},{"num":4790,"demo":false,"sanad":"","matn":["عن عائشة قالت: نَفِسَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ بِمُحَمَّدِ بْنِ أَبِي بَكْرٍ بِالشَّجَرَةِ، فَأَمَرَ رَسُولُ اللَّهِ ﷺ أَبَا بَكْرٍ يَأْمُرُهَا أَنْ تَغْتَسِلَ وَتُهِلَّ."],"takhrij":"صحيح: رواه مسلم (١٢٠٩).","grade":"صحيح","chapter_ar":"باب الغسل للإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1209).","chapter_en":"Bathing for entering ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Aisha said: Asma bint Umays gave birth to Muhammad ibn Abi Bakr at al-Shajarah, so the Messenger of Allah ﷺ instructed Abu Bakr to tell her to bathe and enter ihram."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1209}]},{"num":4791,"demo":false,"sanad":"","matn":["عن عائشة، قالت: كان رسولُ اللَّهِ ﷺ إذا أراد أن يُحْرِمَ غسل رأسه بخِطْمِيٍّ وأُشْنَانٍ، ودَهَنَهُ بشيءٍ من زيتٍ غيرِ كثير."],"takhrij":"حسن: رواه أحمد (٢٤٤٩٠)، والبزار - كشف الأستار (١٠٨٥)، والدارقطني (٢٤٥١)، واللفظ للبزار والدارقطني.","grade":"حسن","chapter_ar":"باب الغسل للإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (24490), al-Bazzar in Kashf al-Astar (1085), and al-Daraqutni (2451). This wording is that of al-Bazzar and al-Daraqutni.","chapter_en":"Bathing for entering ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Aisha said: When the Messenger of Allah ﷺ intended to enter ihram, he would wash his head with marshmallow and ushnaan, and apply a small amount of oil to it."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1085},{"key":"الدارقطنی","label":"الدارقطني","number":2451},{"key":"ahmad","label":"مسند الإمام أحمد","number":24490,"n":24490},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1085,"n":1086},{"key":"sh9771","label":"سنن الدارقطني","number":2451,"n":2458}]},{"num":4792,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: فَخَرَجْنَا مَعَهُ حَتَّى أَتَيْنَا ذَا الحُلَيْفَةِ، فَوَلَدَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ مُحَمَّدَ بْنَ أَبِي بَكْرٍ، فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ ﷺ: كَيْفَ أَصْنَعُ؟ قَالَ: (( اغْتَسِلِي، وَاسْتَثْفِرِي بِثَوْبٍ، وَأَحْرِمِي ))."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب الغسل للإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Bathing for entering ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: We went out with him until we reached Dhu al-Hulayfah, and Asma bint Umays gave birth to Muhammad ibn Abi Bakr. She sent to the Messenger of Allah ﷺ asking, “What should I do?” He said, “Bathe, bind yourself with a cloth, and enter ihram.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":4793,"demo":false,"sanad":"","matn":["عن ابن عباس: أَنَّ النَّبِيَّ ﷺ قَالَ: (( الحَائِضُ وَالنُّفَسَاءُ إِذَا أَتَتَا عَلَى الْوَقْتِ تَغْتَسِلَانِ، وَتُحْرِمَانِ، وَتَقْضِيَانِ الْمَنَاسِكَ كُلَّهَا غَيْرَ الطَّوَافِ بِالْبَيْتِ )).","قَالَ أَبُو مَعْمَرٍ فِي حَدِيثِهِ: (( حَتَّى تَطْهُرَ )).","وروى ابن عيسى من رواية حماد، قال: عن عطاء، عن ابن عباس.","وقال ابن عيسى: (( كُلَّهَا )). قال: (( الْمَنَاسِكَ إِلَّا الطَّوَافَ بِالْبَيْتِ ))."],"takhrij":"حسن: رواه أبو داود (١٧٤٤)، والترمذي (٩٤٥). قال الترمذي: هذا حديث حسن غريب.","grade":"حسن","chapter_ar":"باب الغسل للإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1744) and al-Tirmidhi (945). Al-Tirmidhi said: This is a Hasan gharib hadith.","chapter_en":"Bathing for entering ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas reported that the Prophet ﷺ said: “When a menstruating woman or a woman in postnatal bleeding reaches the appointed place, she should bathe, enter ihram, and perform all the rites except circling the House.”","Abu Ma‘mar said in his narration: “until she becomes pure.”","Ibn Isa also narrated it through Hammad, saying: from Ata, from Ibn Abbas.","And Ibn Isa said: “all of them,” meaning: “all the rites except circling the House.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1744},{"key":"tirmidhi","label":"الترمذي","number":945}]},{"num":4794,"demo":false,"sanad":"","matn":["عن زيد بن ثابت، أنه رأى النبيَّ ﷺ تجرَّد لإهلاله واغتسل."],"takhrij":"حسن بالمتابعة: رواه الترمذي (٨٣٠)، والدارقطني (٢٤٣٤).","grade":"حسن بالمتابعة","chapter_ar":"باب الغسل للإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan through corroborating reports: Narrated by al-Tirmidhi (830) and al-Daraqutni (2434).","chapter_en":"Bathing for entering ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Zayd ibn Thabit reported that he saw the Prophet ﷺ disrobe for entering ihram and bathe."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":830},{"key":"الدارقطنی","label":"الدارقطني","number":2434}]},{"num":4795,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: من السنة أن يغتسل الرجل إذا أراد أن يُحرم، وإذا أراد أن يدخل مكة."],"takhrij":"صحيح: رواه الدارقطني (٢٤٣٣)، والحاكم (٤٤٧/١)، والبيهقي (٣٣/٥)، والبزار - كشف الأستار (١٠٨٤). وقول ابن عمر: (( من السنة )) أي من المرفوع، كما قال جمهور أهل العلم.","grade":"صحيح","chapter_ar":"باب الغسل للإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Daraqutni (2433), al-Hakim (1/447), al-Bayhaqi (5/33), and al-Bazzar in Kashf al-Astar (1084). Ibn Umar’s phrase, “from the Sunnah,” means it has the ruling of a prophetic report, as the majority of scholars stated.","chapter_en":"Bathing for entering ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Umar said: It is from the Sunnah that a man should bathe when he intends to enter ihram, and when he intends to enter Makkah."]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطني","number":2433},{"key":"البیہقی","label":"البيهقي","number":33},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1084},{"key":"sh9771","label":"سنن الدارقطني","number":2433,"n":2440},{"key":"hakim","label":"المستدرك على الصحيحين","number":1639,"n":1628},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":8946,"n":9025},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1084,"n":1085}]},{"num":4796,"demo":false,"sanad":"","matn":["عن عائشة زوج النبيِّ ﷺ، أنها قالت: كنتُ أُطيِّبُ رسولَ اللَّهِ ﷺ لإحرامه قبل أن يُحرم، ولحلِّه قبل أن يطوف بالبيت."],"takhrij":"متفق عليه: رواه مالك (١٧)، والبخاري (١٥٣٩)، ومسلم (٣٣: ١١٨٩).","grade":"متفق عليه","chapter_ar":"باب استعمال الطيب والأدهان عند الإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (1539), and Muslim (1189/33).","chapter_en":"Using perfume and oils at the time of ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Aisha, the wife of the Prophet ﷺ, said: I used to apply perfume to the Messenger of Allah ﷺ for his ihram before he entered it, and for his release from ihram before he circled the House."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"bukhari","label":"البخاري","number":1539},{"key":"muslim","label":"مسلم","number":33}]},{"num":4797,"demo":false,"sanad":"","matn":["عن عائشة زوج النبيِّ ﷺ قالت: كأنّي أنظر إلى وَبيصِ الطِّيب في مَفْرِقِ رسولِ اللَّهِ ﷺ وهو مُحْرِمٌ."],"takhrij":"متفق عليه: رواه البخاري (١٥٣٨)، ومسلم (٣٩: ١١٩٠)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب استعمال الطيب والأدهان عند الإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1538) and Muslim (1190/39). This wording is that of Muslim.","chapter_en":"Using perfume and oils at the time of ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Aisha, the wife of the Prophet ﷺ, said: It is as though I can still see the glimmer of perfume in the parting of the Messenger of Allah ﷺ’s hair while he was in ihram."]},"buhuth":{"ar":["وقولها: (( وبيص الطيب )) وفي رواية أخرى: (( وبيص المسك )) أي بريقه. يقال: وَبَصَ الشيءُ يَبِصُ وَبْصًا إذا برق. ذكره الخطابي. وفي الحديث دليل على أن الطيب لو بقي أثره على المحرم في حال إحرامه لا يضره، خلافًا لمن كره استعمال الطيب عند الإحرام، أو لمن كره بقاء أثره بعد الإحرام."],"en":["Her phrase, “the glimmer of perfume,” and in another narration, “the glimmer of musk,” means its shine. It is said: something glimmered when it shone. Al-Khattabi mentioned this. The hadith shows that if the trace of perfume remains on a person after entering ihram, it does not harm him, contrary to those who disliked using perfume at the time of ihram or disliked its remaining trace after ihram begins."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1538},{"key":"muslim","label":"مسلم","number":39}]},{"num":4798,"demo":false,"sanad":"","matn":["عن عائشة، قالت: كُنَّا نَخْرُجُ مَعَ النَّبِيِّ ﷺ إِلَى مَكَّةَ، فَنُضَمِّدُ جِبَاهَنَا بِالسُّكِّ المُطَيَّبِ عِنْدَ الإِحْرَامِ، فَإِذَا عَرِقَتْ إِحْدَانَا سَالَ عَلَى وَجْهِهَا، فَيَرَاهُ النَّبِيُّ ﷺ فَلا يَنْهَاهَا."],"takhrij":"صحيح: رواه أبو داود (١٨٣٠).","grade":"صحيح","chapter_ar":"باب استعمال الطيب والأدهان عند الإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1830).","chapter_en":"Using perfume and oils at the time of ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Aisha said: We used to go out with the Prophet ﷺ to Makkah, and we would apply perfumed sukk to our foreheads at the time of ihram. When one of us perspired, it would run down onto her face, and the Prophet ﷺ would see it and not forbid her."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1830}]},{"num":4799,"demo":false,"sanad":"","matn":["عن إبراهيم بن محمد بن المنتشر، عن أبيه، قال: سَأَلْتُ عبدَ اللَّهِ بنَ عمر رضي اللَّه عنهما عن الرجلِ يَتَطَيَّبُ، ثم يُصبحُ مُحْرِمًا؟ فقال: ما أُحِبُّ أن أُصبحَ مُحْرِمًا أَنْضَخُ طيبًا، ولأن أَطَّلِيَ بِقَطِرَانٍ أَحَبُّ إليَّ من أن أفعل ذلك. قال: فدخلتُ على عائشة رضي اللَّه عنها فأخبرتُها أن ابن عمر قال: ما أُحِبُّ أن أُصبحَ مُحْرِمًا أَنْضَخُ طيبًا، ولأن أَطَّلِيَ بِقَطِرَانٍ أَحَبُّ إليَّ من أن أفعل ذلك. فقالت عائشة: أنا طيَّبْتُ رسولَ اللَّهِ ﷺ عند إحرامه، ثم طاف في نسائه، ثم أصبح مُحْرِمًا."],"takhrij":"صحيح: رواه البخاري (٢٧٠)، ومسلم (٤٧: ١١٩٢)، واللفظ لمسلم.","grade":"صحيح","chapter_ar":"باب استعمال الطيب والأدهان عند الإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (270) and Muslim (1192/47). This wording is that of Muslim.","chapter_en":"Using perfume and oils at the time of ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Ibrahim ibn Muhammad ibn al-Muntashir narrated from his father: I asked Abdullah ibn Umar about a man who applies perfume and then reaches the morning in ihram. He said: I do not like to wake up in ihram while giving off perfume; and for me to smear myself with tar is more beloved than doing that. He said: Then I went to Aisha and informed her that Ibn Umar had said this. Aisha replied: I myself perfumed the Messenger of Allah ﷺ at the time of his ihram, then he went around among his wives, then he reached the morning in ihram."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":270},{"key":"muslim","label":"مسلم","number":47}]},{"num":4800,"demo":false,"sanad":"","matn":["عن نافع، قال: كان ابن عمر رضي اللَّه عنهما إذا أراد الخروج إلى مكة ادَّهَنَ بدهنٍ ليس له رائحةٌ طيبة، ثم يأتي مسجد ذي الحليفة فيصلي، ثم يركب، وإذا استوت به راحلته قائمةً أَحْرَم، ثم قال: (( هكذا رأيتُ النبيَّ ﷺ يفعل ))."],"takhrij":"صحيح: رواه البخاري (١٥٥٤).","grade":"صحيح","chapter_ar":"باب استعمال الطيب والأدهان عند الإحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1554).","chapter_en":"Using perfume and oils at the time of ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Nafi said: When Ibn Umar intended to leave for Makkah, he would apply an oil that had no pleasant fragrance, then come to the mosque of Dhu al-Hulayfah and pray. Then he would mount his ride, and once it stood upright with him upon it, he would enter ihram. Then he said: “This is how I saw the Prophet ﷺ do.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1554}]},{"num":4801,"demo":false,"sanad":"","matn":["عن يعلى بن أمية، أنه كان يقول لعمر بن الخطاب رضي اللَّه عنه: ليتني أرى نبيَّ اللَّهِ ﷺ حين يُنزل عليه. فلما كان النبيُّ ﷺ بالجِعْرانة، وعليه ثوبٌ قد أُظِلَّ به عليه، ومعه ناسٌ من أصحابه فيهم عمر، إذ جاءه رجلٌ عليه جُبَّةُ صوفٍ متضمخ بطيب، فقال: يا رسول الله، كيف ترى في رجلٍ أحرم بعمرةٍ في جبةٍ بعدما تضمخ بطيب؟ فنظر إليه النبيُّ ﷺ ساعةً، ثم سكت، فجاءه الوحي، فأشار عمر بيده إلى يعلى بن أمية: تعال. فجاء يعلى فأدخل رأسه، فإذا النبيُّ ﷺ مُحْمَرُّ الوجه يَغِطُّ ساعةً، ثم سُرِّي عنه، فقال: (( أين الذي سألني عن العمرة آنفًا؟ )) فالتمس الرجل، فجيء به، فقال النبيُّ ﷺ: (( أما الطيبُ الذي بك فاغسله ثلاث مرات، وأما الجبة فانزعها، ثم اصنع في عمرتك ما تصنع في حجك ))."],"takhrij":"متفق عليه: رواه البخاري (١٥٣٦)، ومسلم (٨: ١١٨٠)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب فيما لا يلبس المحرم من الثياب وأن من لم يجد النعلين فليلبس الخفين وليقطعهما أسفل من الكعبين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1536) and Muslim (1180/8). This wording is that of Muslim.","chapter_en":"What the person in ihram may not wear, and that whoever does not find sandals may wear leather socks and cut them below the ankles","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Ya‘la ibn Umayyah said that he used to say to Umar ibn al-Khattab: I wish I could see the Prophet of Allah ﷺ when revelation comes down upon him. When the Prophet ﷺ was at al-Ji‘ranah, shaded by a garment, and with him were some of his Companions including Umar, a man came wearing a wool robe and scented with perfume. He said: O Messenger of Allah ﷺ, what do you say about a man who entered ihram for umrah while wearing a robe after applying perfume? The Prophet ﷺ looked at him for a while and then remained silent. Then revelation came to him. Umar gestured with his hand to Ya‘la ibn Umayyah, “Come.” So Ya‘la came and put his head in, and the Prophet ﷺ’s face was red and he was breathing heavily for a while. Then it was lifted from him, and he said: “Where is the one who asked me about umrah just now?” The man was sought and brought, and the Prophet ﷺ said: “As for the perfume on you, wash it off three times. As for the robe, remove it. Then do in your umrah what you do in your hajj.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1536},{"key":"muslim","label":"مسلم","number":8}]},{"num":4802,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أن رجلاً سأل رسولَ اللَّهِ ﷺ ما يلبس المحرم من الثياب؟ فقال رسول الله ﷺ: (( لا تلبسوا القُمُصَ، ولا العمائم، ولا السراويلات، ولا البرانس، ولا الخفاف، إلا أحدٌ لا يجد نعلين فليلبس خفين وليقطعهما أسفل من الكعبين، ولا تلبسوا من الثياب شيئًا مسَّه الزعفران ولا الورس ))."],"takhrij":"متفق عليه: رواه مالك (٨)، والبخاري (١٥٤٢)، ومسلم (١١٧٧).","grade":"متفق عليه","chapter_ar":"باب فيما لا يلبس المحرم من الثياب وأن من لم يجد النعلين فليلبس الخفين وليقطعهما أسفل من الكعبين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (8), al-Bukhari (1542), and Muslim (1177).","chapter_en":"What the person in ihram may not wear, and that whoever does not find sandals may wear leather socks and cut them below the ankles","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Umar reported that a man asked the Messenger of Allah ﷺ, “What clothes may a person in ihram wear?” The Messenger of Allah said: “Do not wear shirts, turbans, trousers, hooded cloaks, or leather socks. But whoever cannot find sandals may wear leather socks and cut them below the ankles. And do not wear any garment touched by saffron or wars.”"]},"buhuth":{"ar":["قوله: (( الورس )) نبت أصفر طيب الريح يصبغ به. قال ابن العربي: (( ليس الورس بطيب، ولكنه نبَّه به على اجتناب الطيب وما يشبهه في ملاءمة الشم، فيؤخذ منه تحريم أنواع الطيب على المحرم فيما يُقصد به التطيب )). فتح الباري (٤٠٤/٣). وقوله: (( ولا تلبسوا من الثياب شيئًا … )) فيه دليل على أن المحرم ممنوع عن استعمال الطيب في بدنه وثيابه رجلاً كان أو امرأة. وكذلك لا يجوز له أن يشم شيئًا من نبات الأرض مما يُعد طيبًا كالورد والزعفران والورس.","ويجوز للمحرم الادهان إذا لم يكن فيه خلطٌ من الطيب."],"en":["The word “wars” refers to a yellow plant with a pleasant scent used for dyeing. Ibn al-Arabi said: “Wars itself is not perfume, but it was mentioned to indicate avoiding perfume and anything similar that appeals to the sense of smell. From this is taken the prohibition of all kinds of fragrance for the person in ihram when the purpose is beautification with scent.” Fath al-Bari (3/404). And his words, “Do not wear any garment…” show that a person in ihram is prohibited from using perfume on his body or clothing, whether man or woman. Likewise, he should not deliberately smell fragrant plants such as roses, saffron, and wars.","It is permissible for the person in ihram to use oil if no perfume is mixed into it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":8},{"key":"bukhari","label":"البخاري","number":1542},{"key":"muslim","label":"مسلم","number":1177}]},{"num":4803,"demo":false,"sanad":"","matn":["عن ابن عمر قال: نهى رسولُ اللَّهِ ﷺ أن يلبس المحرم ثوبًا مصبوغًا بوَرْسٍ أو زعفران، وقال: (( من لم يجد نعلين فليلبس خفين وليقطعهما أسفل من الكعبين ))."],"takhrij":"متفق عليه: رواه مالك (٩)، والبخاري (١٥٤٢)، ومسلم (٣: ١١٧٧).","grade":"متفق عليه","chapter_ar":"باب فيما لا يلبس المحرم من الثياب وأن من لم يجد النعلين فليلبس الخفين وليقطعهما أسفل من الكعبين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (9), al-Bukhari (1542), and Muslim (1177/3).","chapter_en":"What the person in ihram may not wear, and that whoever does not find sandals may wear leather socks and cut them below the ankles","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ forbade the person in ihram from wearing a garment dyed with wars or saffron, and he said: “Whoever does not find sandals may wear leather socks and cut them below the ankles.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"bukhari","label":"البخاري","number":1542},{"key":"muslim","label":"مسلم","number":3}]},{"num":4804,"demo":false,"sanad":"","matn":["عن ابن عمر، أنه وجد البرد فقال: ألقِ عليَّ ثوبًا يا نافع، فألقى عليه بُرنسًا، فقال: ألقِ عني هذا، وقد نهى رسولُ اللَّهِ ﷺ أن يلبسه المحرم."],"takhrij":"صحيح: رواه أبو داود (١٨٢٨)، والإمام أحمد (٦٢٦٦).","grade":"صحيح","chapter_ar":"باب فيما لا يلبس المحرم من الثياب وأن من لم يجد النعلين فليلبس الخفين وليقطعهما أسفل من الكعبين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1828) and Imam Ahmad (6266).","chapter_en":"What the person in ihram may not wear, and that whoever does not find sandals may wear leather socks and cut them below the ankles","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar felt cold and said: Put a garment over me, O Nafi. So he placed a hooded cloak over him. Ibn Umar said: Remove this from me, for the Messenger of Allah ﷺ forbade the person in ihram from wearing it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1828},{"key":"الامام_احمد","label":"الإمام أحمد","number":6266},{"key":"ahmad","label":"مسند الإمام أحمد","number":6266,"n":6266}]},{"num":4805,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: خطبنا النبيُّ ﷺ بعرفات فقال: (( من لم يجد الإزار فليلبس السراويل، ومن لم يجد النعلين فليلبس الخفين ))."],"takhrij":"متفق عليه: رواه البخاري (١٨٤١)، ومسلم (١١٧٨)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب جواز لبس الخفين من غير قطع، والسراويل من غير فتق لمن لم يجد النعلين والإزار","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1841) and Muslim (1178). This wording is that of al-Bukhari.","chapter_en":"The permissibility of wearing leather socks without cutting them, and trousers without tearing them, for the one who cannot find sandals or a waist-wrapper","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Prophet ﷺ addressed us at Arafat and said: “Whoever cannot find a waist-wrapper may wear trousers, and whoever cannot find sandals may wear leather socks.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1841},{"key":"muslim","label":"مسلم","number":1178}]},{"num":4806,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: قال رسولُ اللَّهِ ﷺ: (( من لم يجد نعلين فليلبس خفين، ومن لم يجد إزارًا فليلبس سراويل ))."],"takhrij":"صحيح: رواه مسلم (١١٧٩).","grade":"صحيح","chapter_ar":"باب جواز لبس الخفين من غير قطع، والسراويل من غير فتق لمن لم يجد النعلين والإزار","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1179).","chapter_en":"The permissibility of wearing leather socks without cutting them, and trousers without tearing them, for the one who cannot find sandals or a waist-wrapper","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “Whoever cannot find sandals may wear leather socks, and whoever cannot find a waist-wrapper may wear trousers.”"]},"buhuth":{"ar":["واختلف أهل العلم في الجمع بين حديث ابن عمر في قطع الخفين، وحديث ابن عباس فإنه لم يذكر فيه قطع. فذهب جمهور أهل العلم منهم الإمام أحمد إلى أن حديث ابن عباس عام، وحديث ابن عمر خاص ومقيَّد، وحمل المطلق على المقيَّد معروف في الشرع. وللعلماء توجيهات أخرى ذكرتها في “المنة الكبرى” (٤/٣٠) بالتفصيل، فراجعه تجد فيه ما يغنيك عن المطولات."],"en":["The scholars differed on how to reconcile Ibn Umar’s hadith about cutting the leather socks with Ibn Abbas’s hadith, which does not mention cutting. The majority of scholars, including Imam Ahmad, held that Ibn Abbas’s hadith is general while Ibn Umar’s hadith is specific and restrictive, and applying an unrestricted text in light of a restricted one is a recognized method in Islamic law. Scholars also gave other explanations, which I detailed in al-Minnah al-Kubra (4/30)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1179}]},{"num":4807,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أن رجلاً كان مع النبيِّ ﷺ فَوَقَصَتْهُ ناقته وهو مُحرم فمات، فقال رسولُ اللَّهِ ﷺ: (( اغسلوه بماءٍ وسدر، وكفِّنوه في ثوبيه، ولا تمسُّوه بطيب، ولا تُخمِّروا رأسه، فإنه يُبعث يوم القيامة مُلبِّيًا )).","وفي رواية: (( ولا تخمِّروا رأسه ولا وجهه، فإنه يبعث يوم القيامة مُلبِّيًا ))."],"takhrij":"متفق عليه: رواه البخاري (١٨٥١)، ومسلم (٩٩: ١٢٠٦). والرواية الثانية عند مسلم.","grade":"متفق عليه","chapter_ar":"باب حكم تغطية المحرم رأسه ووجهه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1851) and Muslim (1206/99). The second narration is in Muslim.","chapter_en":"The ruling on a person in ihram covering his head and face","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abdullah ibn Abbas reported that a man was with the Prophet ﷺ when his camel threw him while he was in ihram and he died. The Messenger of Allah ﷺ said: “Wash him with water and lotus leaves, shroud him in his two garments, do not apply perfume to him, and do not cover his head, for he will be raised on the Day of Resurrection reciting the talbiyah.”","In another narration: “Do not cover his head or his face, for he will be raised on the Day of Resurrection reciting the talbiyah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1851},{"key":"muslim","label":"مسلم","number":99}]},{"num":4808,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: قام رجل فقال: يا رسول الله، ماذا تأمرنا أن نلبس من الثياب في الإحرام؟ فقال النبيُّ ﷺ: (( لا تلبسوا القميص، ولا السراويلات، ولا العمائم، ولا البرانس، إلا أن يكون أحدٌ ليست له نعلان فليلبس الخفين وليقطع أسفل من الكعبين، ولا تلبسوا ثوبًا مسَّه زعفران ولا الورس، ولا تنتقب المرأة المحرمة، ولا تلبس القفازين ))."],"takhrij":"صحيح: رواه البخاري (١٨٣٨).","grade":"صحيح","chapter_ar":"باب ما تلبس المرأة المحرمة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1838).","chapter_en":"What a woman in ihram may wear","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abdullah ibn Umar said: A man stood and said: O Messenger of Allah ﷺ, what do you command us to wear in ihram? The Prophet ﷺ said: “Do not wear a shirt, trousers, turbans, or hooded cloaks. If someone has no sandals, he may wear leather socks and cut them below the ankles. Do not wear any garment touched by saffron or wars. And the woman in ihram must not wear a face veil or gloves.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1838}]},{"num":4809,"demo":false,"sanad":"","matn":["عن ابن عمر، أنه سمع رسولَ اللَّهِ ﷺ نهى النساء في إحرامهن عن القفازين والنقاب، وما مسَّ الورس والزعفران من الثياب، ولتلبس بعد ذلك ما أحبَّتْ من ألوان الثياب: مُعَصْفَرًا أو خزًّا أو حُلِيًّا أو سراويل أو قميصًا أو خفًّا."],"takhrij":"حسن: رواه أبو داود (١٨٢٧).","grade":"حسن","chapter_ar":"باب ما تلبس المرأة المحرمة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1827).","chapter_en":"What a woman in ihram may wear","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Ibn Umar reported that he heard the Messenger of Allah ﷺ forbid women in their ihram from gloves, face veils, and garments touched by wars or saffron. After that, they may wear whatever colors of clothing they wish: dyed garments, silk-blend, jewelry, trousers, a shirt, or leather footwear."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1827}]},{"num":4810,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله، أن عبد الله - يعني ابن عمر - كان يصنع ذلك، يعني يقطع الخفين للمرأة المحرمة، ثم حدثته صفية بنت أبي عبيد أن عائشة حدثتها أن رسولَ اللَّهِ ﷺ قد كان رخَّص للنساء في الخفين، فترك ذلك."],"takhrij":"حسن: رواه أبو داود (١٨٣١)، والإمام أحمد (٤٨٣٦).","grade":"حسن","chapter_ar":"باب ما تلبس المرأة المحرمة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1831) and Imam Ahmad (4836).","chapter_en":"What a woman in ihram may wear","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Salim ibn Abdullah reported that Abdullah, meaning Ibn Umar, used to do that, meaning he used to cut the leather socks for the woman in ihram. Then Safiyyah bint Abi Ubayd told him that Aisha had told her that the Messenger of Allah ﷺ had allowed women to wear leather socks, so he stopped doing that."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1831},{"key":"الامام_احمد","label":"الإمام أحمد","number":4836},{"key":"ahmad","label":"مسند الإمام أحمد","number":4836,"n":4836}]},{"num":4811,"demo":false,"sanad":"","matn":["عن فاطمة بنت المنذر قالت: كنا نخمِّر وجوهنا ونحن محرمات، ونحن مع أسماء بنت أبي بكر الصديق."],"takhrij":"صحيح: رواه مالك (١٨).","grade":"صحيح","chapter_ar":"باب إباحة تغطية المحرمة وجهها من الرجال","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (18).","chapter_en":"The permissibility of a woman in ihram covering her face from men","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Fatimah bint al-Mundhir said: We used to cover our faces while in ihram, and we were with Asma bint Abi Bakr al-Siddiq."]},"buhuth":{"ar":["قلت: وفعلهن هذا بحضرة أسماء بنت أبي بكر مشعر بأن هذا العمل كان مستمرًا من عهد النبيِّ ﷺ، كما تدل عليه رواية أسماء، قالت: (( كنا نغطي وجوهنا من الرجال، وكنا نمتشط قبل ذلك )). رواه ابن خزيمة (٢٦٩٠).","ورواه الحاكم (٤٥٤/١) من وجه آخر عن أسماء بنت أبي بكر قالت: (( كنا نغطي وجوهنا من الرجال، وكنا نمتشط قبل ذلك في الإحرام ))."],"en":["I say: Their doing this in the presence of Asma bint Abi Bakr suggests that this practice continued from the time of the Prophet ﷺ, as is also shown by the narration of Asma, who said: “We used to cover our faces from men, and we used to comb our hair before that.” Narrated by Ibn Khuzaymah (2690).","Al-Hakim also narrated it (1/454) through another route from Asma bint Abi Bakr, who said: “We used to cover our faces from men, and we used to comb our hair before that while in ihram.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":18}]},{"num":4812,"demo":false,"sanad":"","matn":["عن أمِّ الحُصَيْنِ، قالت: حَجَجْتُ مَعَ رَسُولِ اللَّهِ ﷺ حَجَّةَ الوَدَاعِ، فَرَأَيْتُ أُسَامَةَ وَبِلَالًا، وَأَحَدُهُمَا آخِذٌ بِخِطَامِ نَاقَةِ النَّبِيِّ ﷺ، وَالآخَرُ رَافِعٌ ثَوْبَهُ يَسْتُرُهُ مِنَ الحَرِّ، حَتَّى رَمَى جَمْرَةَ العَقَبَةِ."],"takhrij":"صحيح: رواه مسلم (١٢٩٨: ٣١٢).","grade":"صحيح","chapter_ar":"باب ما جاء في تظليل المحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1298:312).","chapter_en":"What has been reported regarding shading the muhrim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Umm al-Husayn said: I performed Hajj with the Messenger of Allah ﷺ during the Farewell Pilgrimage, and I saw Usamah and Bilal. One of them was holding the reins of the Prophet’s ﷺ camel, and the other was raising his garment to shade him from the heat, until he stoned Jamrat al-Aqabah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1298}]},{"num":4813,"demo":false,"sanad":"","matn":["عن إبراهيم بن عبد اللَّه بن حُنَيْن، عن أبيه: أَنَّ عبدَ اللَّهِ بنَ عباسٍ وَالمِسْوَرَ بنَ مَخْرَمَةَ اخْتَلَفَا بِالأَبْوَاءِ، فَقَالَ عبدُ اللَّهِ بنُ عباسٍ: يَغْسِلُ المُحْرِمُ رَأْسَهُ. وَقَالَ المِسْوَرُ بنُ مَخْرَمَةَ: لا يَغْسِلُ المُحْرِمُ رَأْسَهُ.","قال: فَأَرْسَلَنِي عبدُ اللَّهِ بنُ عباسٍ إِلَى أَبِي أَيُّوبَ الأَنْصَارِيِّ، فَوَجَدْتُهُ يَغْتَسِلُ بَيْنَ القَرْنَيْنِ، وَهُوَ يُسْتَتَرُ بِثَوْبٍ، فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: مَنْ هَذَا؟ فَقُلْتُ: أَنَا عبدُ اللَّهِ بنُ حُنَيْنٍ، أَرْسَلَنِي إِلَيْكَ عبدُ اللَّهِ بنُ عباسٍ، أَسْأَلُكَ كَيْفَ كَانَ رَسُولُ اللَّهِ ﷺ يَغْسِلُ رَأْسَهُ وَهُوَ مُحْرِمٌ؟","قال: فَوَضَعَ أَبُو أَيُّوبَ يَدَهُ عَلَى الثَّوْبِ فَطَأْطَأَهُ حَتَّى بَدَا لِي رَأْسُهُ، ثُمَّ قَالَ لِإِنْسَانٍ يَصُبُّ عَلَيْهِ: اصْبُبْ. فَصَبَّ عَلَى رَأْسِهِ، ثُمَّ حَرَّكَ رَأْسَهُ بِيَدَيْهِ، فَأَقْبَلَ بِهِمَا وَأَدْبَرَ، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ﷺ يَفْعَلُ."],"takhrij":"متفق عليه: رواه مالك (٤)، والبخاري (١٨٤٠)، ومسلم (١٢٠٥).","grade":"متفق عليه","chapter_ar":"باب في جواز غسل المحرم شعر رأسه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (4), al-Bukhari (1840), and Muslim (1205).","chapter_en":"The permissibility of the muhrim washing the hair of his head","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Ibrahim ibn Abdullah ibn Hunayn narrated from his father: Abdullah ibn Abbas and al-Miswar ibn Makhramah disagreed at al-Abwa. Abdullah ibn Abbas said: The muhrim may wash his head. Al-Miswar ibn Makhramah said: The muhrim should not wash his head.","He said: So Abdullah ibn Abbas sent me to Abu Ayyub al-Ansari. I found him bathing between the two posts while screened by a cloth. I greeted him, and he said: Who is this? I said: I am Abdullah ibn Hunayn. Abdullah ibn Abbas sent me to ask you how the Messenger of Allah ﷺ used to wash his head while in ihram.","He said: Abu Ayyub placed his hand on the cloth and lowered it until I could see his head. Then he said to a man pouring water over him: Pour. So he poured water over his head, then Abu Ayyub rubbed his head with both hands, moving them forward and backward, and then said: This is how I saw the Messenger of Allah ﷺ do it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4},{"key":"bukhari","label":"البخاري","number":1840},{"key":"muslim","label":"مسلم","number":1205}]},{"num":4814,"demo":false,"sanad":"","matn":["عن حفصة أمِّ المؤمنين أنها قالت لرسولِ اللَّهِ ﷺ: ما شأنُ الناسِ حَلُّوا وَلَمْ تَحِلَّ أَنْتَ مِنْ عُمْرَتِكَ؟ فقال: (( إِنِّي لَبَّدْتُ رَأْسِي، وَقَلَّدْتُ هَدْيِي، فَلا أَحِلُّ حَتَّى أَنْحَرَ ))."],"takhrij":"متفق عليه: رواه مالك (١٨٠)، والبخاري (١٥٦٦)، ومسلم (١٢٢٩).","grade":"متفق عليه","chapter_ar":"باب ما جاء في التلبيد","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (180), al-Bukhari (1566), and Muslim (1229).","chapter_en":"What has been reported regarding matting the hair","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Hafsah, the Mother of the Believers, said to the Messenger of Allah ﷺ: Why have the people exited ihram while you have not exited from your umrah? He said: “I have matted my hair and garlanded my sacrificial animal, so I will not exit ihram until I slaughter.”"]},"buhuth":{"ar":["وتلبيد الشعر قد يكون بالصمغ، وقد يكون بالعسل، وإنما يفعل ذلك بالشعر ليجتمع ويتلبد، فلا يتخلله الغبار، ولا يصيبه الشعث، ولا يقع فيه الدبيب. قاله الخطابي."],"en":["Matting the hair may be done with gum or with honey. It is done so the hair will stay gathered and firm, so dust does not enter it, it does not become disheveled, and insects do not get into it. This was stated by al-Khattabi."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":180},{"key":"bukhari","label":"البخاري","number":1566},{"key":"muslim","label":"مسلم","number":1229}]},{"num":4815,"demo":false,"sanad":"","matn":["عن عبد اللَّه بن عمر، قال: سمعتُ رسولَ اللَّهِ ﷺ يُهِلُّ مُلَبِّدًا."],"takhrij":"متفق عليه: رواه البخاري (١٥٤٠)، ومسلم (١١٨٤: ٢١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في التلبيد","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1540) and Muslim (1184:21).","chapter_en":"What has been reported regarding matting the hair","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Abdullah ibn Umar said: I heard the Messenger of Allah ﷺ begin his talbiyah while his hair was matted."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1540},{"key":"muslim","label":"مسلم","number":1184}]},{"num":4816,"demo":false,"sanad":"","matn":["عن عبد اللَّه بن عباس، أنَّ النبيَّ ﷺ احتجم وهو مُحْرِمٌ."],"takhrij":"متفق عليه: رواه مسلم (١٢٠٢)، والبخاري (١٨٣٥).","grade":"متفق عليه","chapter_ar":"باب في جواز الحجامة للمحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1202) and al-Bukhari (1835).","chapter_en":"The permissibility of cupping for the muhrim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Abdullah ibn Abbas reported that the Prophet ﷺ underwent cupping while he was in ihram."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1202},{"key":"bukhari","label":"البخاري","number":1835}]},{"num":4817,"demo":false,"sanad":"","matn":["عن ابن بُحَيْنَةَ، أنَّ النبيَّ ﷺ احتجم بطريق مكة وهو مُحْرِمٌ، وسطَ رأسِه."],"takhrij":"متفق عليه: رواه البخاري (١٨٣٦)، ومسلم (١٢٠٣)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب في جواز الحجامة للمحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1836) and Muslim (1203). This wording is that of Muslim.","chapter_en":"The permissibility of cupping for the muhrim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Ibn Buhaynah reported that the Prophet ﷺ underwent cupping on the road to Makkah while in ihram, in the middle of his head."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1836},{"key":"muslim","label":"مسلم","number":1203}]},{"num":4818,"demo":false,"sanad":"","matn":["عن أنس، أنَّ رسولَ اللَّهِ ﷺ احتجم وهو مُحْرِمٌ على ظهرِ القدمِ من وجعٍ كان به."],"takhrij":"صحيح: رواه أبو داود (١٨٣٧)، والنسائي (٢٨٤٩)، والترمذي في الشمائل (٣٥٨)، وابن خزيمة (٢٦٥٨).","grade":"صحيح","chapter_ar":"باب في جواز الحجامة للمحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1837), al-Nasa’i (2849), al-Tirmidhi in al-Shama’il (358), and Ibn Khuzaymah (2658).","chapter_en":"The permissibility of cupping for the muhrim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ underwent cupping while in ihram on the top of his foot because of pain he had there."]},"buhuth":{"ar":["وقوله: (( على ظهر القدم )) يُحمل على التعدد كما هو معروف في مثل هذه الحالة، وإليه جنح ابن خزيمة، وعليه فلا تعارض بين حديثي ابن عباس وأنس."],"en":["His words, “on the top of the foot,” are understood as referring to a separate occasion, as is well known in such cases. Ibn Khuzaymah inclined to this view, so there is no contradiction between the reports of Ibn Abbas and Anas."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1837},{"key":"nasai","label":"النسائي","number":2849},{"key":"tirmidhi/الشمایل","label":"الترمذي في الشمائل","number":358},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2658}]},{"num":4819,"demo":false,"sanad":"","matn":["عن جابر: أنَّ رسولَ اللَّهِ ﷺ احتجم وهو مُحْرِمٌ من وَثْءٍ كان بِوَرِكِهِ أو ظهرِهِ."],"takhrij":"حسن: رواه أحمد (١٤٨٥٧، ١٤٢٨٠)، وأبو داود (٣٨٦٣)، وصححه ابن خزيمة (٢٦٦٠).","grade":"حسن","chapter_ar":"باب في جواز الحجامة للمحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14857, 14280) and Abu Dawud (3863), and authenticated by Ibn Khuzaymah (2660).","chapter_en":"The permissibility of cupping for the muhrim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Jabir reported that the Messenger of Allah ﷺ underwent cupping while in ihram because of a sprain or pain in his hip or his back."]},"buhuth":{"ar":["ورواه ابن ماجه (٣٠٨٢) من وجه آخر وفيه: (( أنَّ النبيَّ ﷺ احتجم وهو مُحْرِمٌ من رَهْقَةٍ أخذته ))، أي الوهن.","وقوله: (( وَثْء )) بفتح الواو وسكون الثاء وآخره همزة: وجعٌ يصيب اللحم ولا يبلغ العظم."],"en":["Ibn Majah also narrated it (3082) through another chain, and in it: “The Prophet ﷺ underwent cupping while in ihram due to exhaustion that affected him,” meaning weakness.","The word “wath’” means a pain that affects the flesh but does not reach the bone."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3863},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2660},{"key":"ahmad","label":"مسند الإمام أحمد","number":14857,"n":14857}]},{"num":4820,"demo":false,"sanad":"","matn":["عن كعب بن عجرة، قال: أتى عليَّ النبيُّ ﷺ زمنَ الحديبية والقملُ يتناثرُ على وجهي، فقال: (( أيؤذيكَ هوامُّ رأسِكَ؟ )) قلتُ: نعم. قال: (( فاحلقْ، وصُمْ ثلاثةَ أيامٍ، أو أطعمْ ستةَ مساكينَ، أو انْسُكْ نسيكةً )).","قال أيوب: لا أدري بأيِّ هذا بدأ."],"takhrij":"متفق عليه: رواه البخاري (٤١٩٠)، ومسلم (١٢٠١: ٨٠)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب في جواز حلق المحرم رأسه إذا كان به أذى مع وجوب الفدية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4190) and Muslim (1201:80). This wording is that of al-Bukhari.","chapter_en":"The permissibility of the muhrim shaving his head if he has an ailment, with the obligation of compensation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Ka‘b ibn Ujrah said: The Prophet ﷺ came to me at the time of al-Hudaybiyah while lice were falling over my face, and he said: “Are the insects of your head harming you?” I said: Yes. He said: “Then shave, and fast three days, or feed six needy people, or slaughter a sacrifice.”","Ayyub said: I do not know with which of these he began."]},"buhuth":{"ar":["ورواه البخاري (٤١٩١): (( كنا مع رسولِ اللَّهِ ﷺ بالحديبية ونحن مُحْرِمون… ))."],"en":["Al-Bukhari also narrated (4191): “We were with the Messenger of Allah ﷺ at al-Hudaybiyah while in ihram…”"]},"intro":{"ar":["قال اللَّه تعالى: ( وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ ٱلْهَدْيُ مَحِلَّهُ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِ أَذًى مِّن رَّأْسِهِ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ ) [سورة البقرة: ١٩٦]."],"en":["Allah the Exalted said: “And do not shave your heads until the sacrificial animal reaches its place of slaughter. But whoever among you is ill or has an ailment of the scalp must offer a compensation of fasting, charity, or sacrifice.” [Surat al-Baqarah: 196]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4190},{"key":"muslim","label":"مسلم","number":1201}]},{"num":4821,"demo":false,"sanad":"","matn":["عن كعب بن عجرة، أنَّ رسولَ اللَّهِ ﷺ قال له: (( لعلَّكَ آذاكَ هوامُّكَ؟ )) فقلتُ: نعم يا رسول الله. فقال رسولُ اللَّهِ ﷺ: (( احلقْ رأسَكَ، وصُمْ ثلاثةَ أيامٍ، أو أطعمْ ستةَ مساكينَ، أو انْسُكْ بشاةٍ ))."],"takhrij":"متفق عليه: رواه مالك (٢٣٨)، والبخاري (١٨١٤) و(١٨١٥)، ومسلم (١٢٠١).","grade":"متفق عليه","chapter_ar":"باب في جواز حلق المحرم رأسه إذا كان به أذى مع وجوب الفدية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (238), al-Bukhari (1814, 1815), and Muslim (1201).","chapter_en":"The permissibility of the muhrim shaving his head if he has an ailment, with the obligation of compensation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Ka‘b ibn Ujrah reported that the Messenger of Allah ﷺ said to him: “Perhaps the insects have harmed you?” I said: Yes, O Messenger of Allah ﷺ. So the Messenger of Allah ﷺ said: “Shave your head, and fast three days, or feed six needy people, or sacrifice a sheep.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":238},{"key":"bukhari","label":"البخاري","number":1814},{"key":"و","label":"و","number":1815},{"key":"muslim","label":"مسلم","number":1201}]},{"num":4822,"demo":false,"sanad":"","matn":["عن نُبَيْه بن وهب، قال: خرجنا مع أبان بن عثمان، حتى إذا كنا بِمَلَلٍ اشتكى عمرُ بنُ عبيدِ اللَّهِ عينَيْهِ، فلما كنا بالرَّوْحاء اشتدَّ وجعُه، فأرسل إلى أبان بن عثمان يسأله، فأرسل إليه أن اضمدهما بالصَّبِرِ، فإنَّ عثمان رضي اللَّه عنه حدَّث عن رسول اللَّهِ ﷺ في الرجل إذا اشتكى عينَيْهِ وهو مُحْرِمٌ ضمَّدَهُما بالصَّبِرِ."],"takhrij":"صحيح: رواه مسلم (١٢٠٤).","grade":"صحيح","chapter_ar":"باب علاج المحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1204).","chapter_en":"Treating the muhrim medically","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["Nubayh ibn Wahb said: We went out with Aban ibn Uthman, and when we were at Malal, Umar ibn Ubayd Allah complained of pain in his eyes. When we reached al-Rawha, the pain became severe, so he sent to Aban ibn Uthman asking him. He sent back saying: Apply aloe to them, for Uthman reported from the Messenger of Allah ﷺ concerning a man who had trouble with his eyes while in ihram, that he treated them with aloe."]},"buhuth":{"ar":["والصَّبِر: عصارة شجرٍ مُرٍّ، مفرده صَبِرَة، والجمع: صُبور.","قال الترمذي: العمل على هذا عند أهل العلم، لا يرون بأسًا أن يتداوى المحرم بدواء ما لم يكن فيه طيب."],"en":["Aloe here means the extract of a bitter plant. Its singular form is sabirah, and its plural is subur.","Al-Tirmidhi said: The practice of the scholars is in accordance with this. They saw no problem in the muhrim treating himself with medicine so long as it does not contain perfume."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1204}]},{"num":4823,"demo":false,"sanad":"","matn":["عن عائشة، قالت: دَخَلَ رَسُولُ اللَّهِ ﷺ عَلَى ضُبَاعَةَ بِنْتِ الزُّبَيْرِ، فقال لها: (( لَعَلَّكِ أَرَدْتِ الحَجَّ؟ )) قالت: واللَّه لا أجدني إلا وجِعةً. فقال لها: (( حُجِّي، وَاشْتَرِطِي، وَقُولِي: اللَّهُمَّ مَحِلِّي حَيْثُ حَبَسْتَنِي )). وكانت تحت المقداد بن الأسود."],"takhrij":"متفق عليه: رواه البخاري (٥٠٨٩)، ومسلم (١٢٠٧: ١٠٤).","grade":"متفق عليه","chapter_ar":"باب في جواز اشتراط المحرم على ربّه عز وجل التَّحلل بعذر المرض ونحوه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5089) and Muslim (1207:104).","chapter_en":"The permissibility of the muhrim stipulating to his Lord that he may exit ihram due to illness or a similar excuse","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Aisha said: The Messenger of Allah ﷺ entered upon Duba‘ah bint al-Zubayr and said to her: “Perhaps you intended Hajj?” She said: By Allah, I find myself only ill. He said to her: “Perform Hajj and make a condition, saying: O Allah, my place of release is wherever You restrain me.” She was married to al-Miqdad ibn al-Aswad."]},"buhuth":{"ar":["قوله: (( مَحِلِّي )) بكسر الحاء، اسم مكان، أي موضع خروجي من الإحرام."],"en":["The phrase “mahilli” means the place where I come out of ihram."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5089},{"key":"muslim","label":"مسلم","number":1207}]},{"num":4824,"demo":false,"sanad":"","matn":["عن عبد اللَّه بن عباس، أنَّ ضُبَاعَةَ بِنْتَ الزُّبَيْرِ بْنِ عبدِ المطلب رضي اللَّه عنها أَتَتْ رَسُولَ اللَّهِ ﷺ فقالت: إني امرأةٌ ثقيلة، وإني أريد الحج، فما تأمرني؟ قال: (( أَهِلِّي بالحجِّ واشترطي: أنَّ مَحِلِّي حيثُ حبستني )). قال: فأدركت."],"takhrij":"صحيح: رواه مسلم (١٢٠٨).","grade":"صحيح","chapter_ar":"باب في جواز اشتراط المحرم على ربّه عز وجل التَّحلل بعذر المرض ونحوه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1208).","chapter_en":"The permissibility of the muhrim stipulating to his Lord that he may exit ihram due to illness or a similar excuse","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Abdullah ibn Abbas reported that Duba‘ah bint al-Zubayr ibn Abd al-Muttalib came to the Messenger of Allah ﷺ and said: I am a heavy woman, and I intend to perform Hajj, so what do you command me? He said: “Enter ihram for Hajj and stipulate: My place of release is wherever You restrain me.” He said: So she completed it."]},"buhuth":{"ar":["قوله: (( فأدركت )) أي أدركت الحج ولم تتحلل حتى فرغت منه."],"en":["The phrase “so she completed it” means she completed the Hajj and did not exit ihram before finishing it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1208}]},{"num":4825,"demo":false,"sanad":"","matn":["عن ضُباعة بنت الزبير، أنَّ النبيَّ ﷺ قال لها: (( حُجِّي واشترطي ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٣٣٦/٢٤)، والبيهقي (٢٢٢/٥).","grade":"حسن","chapter_ar":"باب في جواز اشتراط المحرم على ربّه عز وجل التَّحلل بعذر المرض ونحوه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (24/336) and al-Bayhaqi (5/222).","chapter_en":"The permissibility of the muhrim stipulating to his Lord that he may exit ihram due to illness or a similar excuse","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Duba‘ah bint al-Zubayr reported that the Prophet ﷺ said to her: “Perform Hajj and make the stipulation.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":336},{"key":"البیہقی","label":"البيهقي","number":222},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10116,"n":10204}]},{"num":4826,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر، أو سُعدى بنت عوف، أن رسولَ اللَّهِ ﷺ دخل على ضُباعة بنت عبد المطلب، فقال: (( ما يمنعك يا ابنةَ عمِّي من الحج؟ )) فقالت: أنا امرأة سقيمة، وأنا أخاف الحبس. قال: (( فأحرمي، واشترطي أنَّ مَحِلَّكِ حيثُ حُبِسْتِ ))."],"takhrij":"حسن: رواه ابن ماجه (٢٩٣٦)، والإمام أحمد (٢٦٩٥٣) من هذا الوجه.","grade":"حسن","chapter_ar":"باب في جواز اشتراط المحرم على ربّه عز وجل التَّحلل بعذر المرض ونحوه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2936) and Imam Ahmad (26953) through this chain.","chapter_en":"The permissibility of the muhrim stipulating to his Lord that he may exit ihram due to illness or a similar excuse","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Asma bint Abi Bakr, or Su‘da bint Awf, reported that the Messenger of Allah ﷺ entered upon Duba‘ah bint Abd al-Muttalib and said: “What is preventing you, O daughter of my uncle, from Hajj?” She said: I am a sick woman, and I fear being prevented. He said: “Then enter ihram and stipulate that your place of release is wherever you are restrained.”"]},"buhuth":{"ar":["وقوله: (( يا ابنة عمي )) هو الصواب، وأما بعض النسخ ففيها: (( يا عمتاه )) وهو غير صحيح هنا."],"en":["The correct wording is “O daughter of my uncle.” Some copies have “O my aunt,” but that is not correct here."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2936},{"key":"الامام_احمد","label":"الإمام أحمد","number":26953},{"key":"ahmad","label":"مسند الإمام أحمد","number":26953,"n":26953}]},{"num":4827,"demo":false,"sanad":"","matn":["عن جابر، أنَّ رسولَ اللّٰه ﷺ قال لضُباعة بنت الزبير: (( حُجِّي واشترطي أنَّ مَحِلِّي حيثُ حبستني ))."],"takhrij":"حسن: رواه الطبراني في الأوسط (٢٥٤٧)، والبيهقي (٢٢٢/٥).","grade":"حسن","chapter_ar":"باب في جواز اشتراط المحرم على ربّه عز وجل التَّحلل بعذر المرض ونحوه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (2547) and al-Bayhaqi (5/222).","chapter_en":"The permissibility of the muhrim stipulating to his Lord that he may exit ihram due to illness or a similar excuse","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Jabir reported that the Messenger of Allah ﷺ said to Duba‘ah bint al-Zubayr: “Perform Hajj and stipulate that my place of release is wherever You restrain me.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":2547},{"key":"البیہقی","label":"البيهقي","number":222},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":2547,"n":2537},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10115,"n":10203}]},{"num":4828,"demo":false,"sanad":"","matn":["عن الصعب بن جثامة الليثي، أنَّه أهدى لرسولِ اللّٰه ﷺ حمارًا وحشيًّا، وهو بالأبواء أو بودَّان، فردَّه عليه رسولُ اللّٰه ﷺ، قال: فلما رأى رسولُ اللّٰه ﷺ ما في وجهي قال: (( إنَّا لم نردَّه عليك إلا أنَّا حُرُمٌ ))."],"takhrij":"متفق عليه: رواه مالك (٨٣)، والبخاري (١٨٢٥)، ومسلم (١١٩٣).","grade":"متفق عليه","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (83), al-Bukhari (1825), and Muslim (1193).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Al-Sa‘b ibn Jaththamah al-Laythi reported that he presented a wild donkey to the Messenger of Allah ﷺ while he was at al-Abwa or Waddan, and the Messenger of Allah ﷺ returned it to him. He said: When the Messenger of Allah ﷺ saw what was on my face, he said: “We only returned it to you because we are in ihram.”"]},"intro":{"ar":["قال اللّٰه تعالى: ( يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْتُلُوا الصَّيْدَ وَأَنْتُمْ حُرُمٌ ) [المائدة: ٩٥].","وقال تعالى: ( وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَرِّ مَا دُمْتُمْ حُرُمًا ) [المائدة: ٩٦].","لا خلاف بين أهل العلم في تحريم الصيد على المحرم، وفي تحريم ما صِيد من أجله، ولذا ردَّ النبيُّ ﷺ صيدَ الصعب بن جثامة الليثي؛ لأنه صاده للنبي ﷺ وأصحابه، ولم يردَّ صيدَ أبي قتادة؛ لأنه صاده لنفسه كما سيأتي.","ثم أحلَّ اللّٰه صيد البحر، وحرَّم صيد البر، وقيل: إن الحكمة في ذلك أن المسافر في البحر قد لا يجد طعامًا غير صيد البحر، بخلاف المسافر في البر فإنه يجد طعامًا، ولذا حُرِّم عليه صيد البر."],"en":["Allah the Exalted said: “O you who believe, do not kill game while you are in a state of ihram.” [Surat al-Ma’idah: 95]","And He said: “And forbidden to you is the game of the land as long as you are in a state of ihram.” [Surat al-Ma’idah: 96]","There is no disagreement among the scholars regarding the prohibition of hunting for the muhrim, and the prohibition of game hunted specifically for him. That is why the Prophet ﷺ refused the game of al-Sa‘b ibn Jaththamah al-Laythi, because he had hunted it for the Prophet ﷺ and his Companions, while he did not refuse the game of Abu Qatadah, because he hunted it for himself, as will come later.","Then Allah made sea game lawful and land game unlawful. It has been said that the wisdom in this is that a traveler at sea may not find food other than sea game, unlike the traveler on land, who can find other food. For this reason, land game was forbidden to him."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":83},{"key":"bukhari","label":"البخاري","number":1825},{"key":"muslim","label":"مسلم","number":1193}]},{"num":4829,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، قال: أهدى الصعبُ بنُ جثامة إلى النبيِّ ﷺ حمارَ وحشٍ وهو مُحرِمٌ، فردَّه عليه، وقال: (( لولا أنَّا مُحرمون لقبلناه منك ))."],"takhrij":"صحيح: رواه مسلم (١١٩٤).","grade":"صحيح","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1194).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abdullah ibn Abbas said: Al-Sa‘b ibn Jaththamah gave a wild donkey to the Prophet ﷺ while he was in ihram, so he returned it to him and said: “Had we not been in ihram, we would have accepted it from you.”"]},"buhuth":{"ar":["وفي رواية: (( رجلُ حمارِ وحشٍ )). وفي رواية: (( عَجُزُ حمارِ وحشٍ يقطر دمًا )). وفي رواية: (( شِقُّ حمارِ وحشٍ ))."],"en":["In one narration: “the leg of a wild donkey.” In another narration: “the hind part of a wild donkey dripping with blood.” In another narration: “a side portion of a wild donkey.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1194}]},{"num":4830,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قَدِمَ زيدُ بنُ أرقم، فقال له عبدُ اللّٰه بنُ عباسٍ يستذكره: كيف أخبرتني عن لحم صيدٍ أُهدي إلى رسولِ اللّٰه ﷺ وهو حرام؟ قال: قال: أُهدي له عضوٌ من لحم صيدٍ فردَّه، فقال: (( إنَّا لا نأكلُه، إنَّا حُرُمٌ ))."],"takhrij":"صحيح: رواه مسلم (١١٩٥).","grade":"صحيح","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1195).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Ibn Abbas said: Zayd ibn Arqam came, and Abdullah ibn Abbas asked him to remind him: How did you tell me about the meat of game that was presented to the Messenger of Allah ﷺ while he was in ihram? He said: A piece of hunted meat was presented to him, and he returned it, saying: “We do not eat it; we are in ihram.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1195}]},{"num":4831,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن عامر بن ربيعة، قال: رأيتُ عثمانَ بنَ عفانَ بالعَرج وهو مُحرِمٌ في يومٍ صائفٍ، قد غطَّى وجهَه بقطيفةٍ أرجوان، ثم أُتي بلحم صيدٍ فقال لأصحابه: كُلوا. فقالوا: أوَلا تأكلُ أنت؟ فقال: إنِّي لستُ كهيئتكم، إنَّما صِيدَ من أجلي."],"takhrij":"صحيح: رواه مالك (٨٧). قال مالك: (( في الرجل المحرم يُصاد من أجله صيدٌ، فيُصنع له ذلك الصيد، فيأكل منه وهو يعلم أنه صِيد من أجله، فإن عليه جزاء ذلك الصيد كله )).","grade":"صحيح","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (87). Malik said: “If game is hunted for a muhrim, and that game is prepared for him, and he eats from it knowing that it was hunted for his sake, then the full compensation for that game is due from him.”","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abd al-Rahman ibn Amir ibn Rabi‘ah said: I saw Uthman ibn Affan at al-‘Arj while he was in ihram on a hot day, covering his face with a purple cloth. Then some game meat was brought, and he said to his companions: Eat. They said: Will you not eat? He said: I am not like you; it was only hunted because of me."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":87}]},{"num":4832,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن الحارث - وكان الحارثُ خليفةَ عثمانَ على الطائف - فصنع لعثمانَ طعامًا فيه من الحَجَلِ واليَعاقيبِ ولحمِ الوحش، قال: فبعث إلى عليِّ بن أبي طالب، فجاءه الرسولُ وهو يَخبط لأبعِرٍ له، فجاء وهو ينفض الخبطَ عن يديه. فقالوا له: كُلْ. فقال: أطعِموه قومًا حلالًا، فإنَّا حُرُمٌ. فقال عليٌّ رضي اللّٰه عنه: أَنشُدُ اللّٰهَ من كان هاهنا من أشجعَ، أتعلمون أنَّ رسولَ اللّٰه ﷺ أُهدي إليه رجلُ حمارِ وحشٍ وهو مُحرِمٌ فأبى أن يأكله؟ قالوا: نعم."],"takhrij":"حسن: رواه أبو داود (١٨٤٩).","grade":"حسن","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1849).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abdullah ibn al-Harith — and al-Harith had been appointed by Uthman over al-Ta’if — prepared food for Uthman containing francolins, partridges, and wild game meat. He said: So he sent for Ali ibn Abi Talib. The messenger came to him while he was beating down leaves for his camels, and he came while shaking the leaves from his hands. They said to him: Eat. He said: Feed it to people who are not in ihram, for we are in ihram. Then Ali, may Allah be pleased with him, said: I adjure by Allah those of Ashja‘ who are here: Do you know that a portion of wild donkey was presented to the Messenger of Allah ﷺ while he was in ihram, and he refused to eat it? They said: Yes."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1849}]},{"num":4833,"demo":false,"sanad":"","matn":["عن عائشة، قالت: أُهدي لرسولِ اللّٰه ﷺ وَشيقةُ ظبيٍ وهو مُحرِمٌ، فلم يأكلْه."],"takhrij":"صحيح: رواه الإمام أحمد (٢٥٨٨٢) عن عبد الرزاق - وهو في مصنفه (٨٣٢٤).","grade":"صحيح","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (25882) through Abd al-Razzaq — and it is also in his Musannaf (8324).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Aisha said: A prepared portion of gazelle meat was presented to the Messenger of Allah ﷺ while he was in ihram, and he did not eat it."]},"buhuth":{"ar":["وقوله: (( وشيقةُ ظبي )) الوشيقةُ: اللحمُ يُغلى قليلًا ثم يُتزوَّد به في الأسفار. ولعلَّ النبيَّ ﷺ لم يأكله لأنه صِيد له."],"en":["The phrase “washiqat zabiy” means meat that is lightly cooked and then carried as travel provision. It appears that the Prophet ﷺ did not eat it because it had been hunted for him."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":25882},{"key":"عن_عبد_الرزاق_وہو/مصنفہ","label":"عن عبد الرزاق - وهو في مصنفه","number":8324},{"key":"ahmad","label":"مسند الإمام أحمد","number":25882,"n":25882}]},{"num":4834,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن أبي قتادة، قال: انطلق أبي مع رسولِ اللّٰه ﷺ عامَ الحديبية، فأحرم أصحابُه ولم يُحرِم، وحُدِّث رسولُ اللّٰه ﷺ أنَّ عدوًّا بغَيْقَةَ، فانطلق رسولُ اللّٰه ﷺ. قال: فبينا أنا مع أصحابِه يضحك بعضُهم إلى بعض، إذ نظرتُ فإذا أنا بحمارٍ وحشيٍّ، فحملتُ عليه فعقرتُه، ونَهَيتُهم أن يُعينوني، فأكلنا من لحمِه، وخشينا أن نُقتطع، فانطلقتُ أطلبُ رسولَ اللّٰه ﷺ، أرفع فرسي شأوًا وأسير شأوًا، فلقيتُ رجلًا من بني غفار في جوف الليل، فقلتُ: أين لقيتَ رسولَ اللّٰه ﷺ؟ فقال: تركتُه بتَعْهُنَ وهو قائلُ السقيا. فأتيتُ رسولَ اللّٰه ﷺ فقلتُ: يا رسولَ اللّٰه، إنَّ أصحابَك يقرؤون عليك السلام ورحمةَ اللّٰه، وإنهم قد خشوا أن يُقتطعوا دونك، فانتظرهم. فقلتُ: يا رسولَ اللّٰه، إني أصبتُ حمارًا وحشيًّا، ومعي منه فاضلة. فقال النبيُّ ﷺ للقوم: (( كُلُوا )) وهم مُحرِمون."],"takhrij":"متفق عليه: رواه البخاري (١٨٢١)، ومسلم (١١٩٦: ٥٩)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1821) and Muslim (1196:59). This wording is that of Muslim.","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abdullah ibn Abi Qatadah said: My father went out with the Messenger of Allah ﷺ in the year of al-Hudaybiyah. His companions entered ihram, but he did not. The Messenger of Allah ﷺ was informed that there was an enemy at Ghayqah, so the Messenger of Allah ﷺ set out. He said: While I was with his companions and some of them were smiling to one another, I looked and there was a wild donkey. I charged at it and killed it, and I told them not to help me. Then we ate from its meat, and we feared that we might be cut off, so I set out seeking the Messenger of Allah ﷺ, urging my horse forward at times and going at a normal pace at times. In the middle of the night I met a man from Banu Ghifar and said: Where did you leave the Messenger of Allah ﷺ? He said: I left him at Ta‘hun, intending to rest at al-Suqya. So I came to the Messenger of Allah ﷺ and said: O Messenger of Allah ﷺ, your companions convey to you greetings and the mercy of Allah, and they fear they may be cut off before reaching you, so wait for them. Then I said: O Messenger of Allah ﷺ, I hunted a wild donkey, and I still have some left from it. Then the Prophet ﷺ said to the people: “Eat,” while they were in ihram."]},"buhuth":{"ar":["قوله: (( بغيقة )) موضعٌ من بلاد بني غفار بين مكة والمدينة. وقوله: (( وخشينا أن نُقتطع )) أي يقطعنا العدو عن النبي ﷺ. وقوله: (( أرفع فرسي شأوًا )) أي أكلفه السير السريع، والشأو: الغاية والأمد. وقوله: (( وهو قائلُ السقيا )) أي في عزمه أن يقيل بالسقيا، و(( تعهن )) و(( السقيا )) موضعان. وقوله: (( أصبتُ )) أي اصطدتُ.","ورواه البخاري في الصيد (١٨٢٤)، ومسلم (١١٩٦: ٦٠) من طريق آخر، وفيه فقال: (( هل منكم أحدٌ أمره أو أشار إليه بشيء؟ )) قالوا: لا. قال: (( فكلوا ما بقي من لحمها ))."],"en":["“Ghayqah” is a place in the land of Banu Ghifar between Makkah and Madinah. “We feared that we might be cut off” means that the enemy might separate us from the Prophet ﷺ. “I urged my horse forward at times” means I drove it to travel quickly; shā’w means distance or extent. “He was resting at al-Suqya” means he intended to rest there. Ta‘hun and al-Suqya are both place names. “I caught” here means “I hunted.”","Al-Bukhari also narrated it in the Book of Hunting (1824), and Muslim (1196:60) through another chain, and in it he said: “Did any one of you command him or point it out to him in any way?” They said: No. He said: “Then eat what remains of its meat.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1821},{"key":"muslim","label":"مسلم","number":1196}]},{"num":4835,"demo":false,"sanad":"","matn":["عن أبي قتادة، أنه كان مع رسولِ اللّٰه ﷺ حتى إذا كانوا ببعض طريق مكة تخلَّف مع أصحابٍ له مُحرِمين، وهو غير مُحرِم، فرأى حمارًا وحشيًّا، فاستوى على فرسه، فسأل أصحابَه أن يناولوه سوطَه، فأبوا عليه، فسألهم رمحَه، فأبوا، فأخذَه، ثم شدَّ على الحمار فقتله، فأكل منه بعضُ أصحابِ رسولِ اللّٰه ﷺ، وأبى بعضُهم، فلما أدركوا رسولَ اللّٰه ﷺ سألوه عن ذلك، فقال: (( إنما هي طُعمةٌ أطعمكموها اللّٰه ))."],"takhrij":"متفق عليه: رواه مالك (٧٦)، والبخاري (٢٩١٤)، ومسلم (١١٩٦: ٥٧، ٥٨).","grade":"متفق عليه","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (76), al-Bukhari (2914), and Muslim (1196:57, 58).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Qatadah reported that he was with the Messenger of Allah ﷺ until they were on part of the road to Makkah. He remained behind with some companions who were in ihram, while he himself was not in ihram. He saw a wild donkey and mounted his horse. He asked his companions to hand him his whip, but they refused. Then he asked them for his spear, but they refused, so he took it himself, then attacked the donkey and killed it. Some of the Companions of the Messenger of Allah ﷺ ate from it, while others refused. When they caught up with the Messenger of Allah ﷺ, they asked him about that, and he said: “It is only food Allah fed you.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":76},{"key":"bukhari","label":"البخاري","number":2914},{"key":"muslim","label":"مسلم","number":1196}]},{"num":4836,"demo":false,"sanad":"","matn":["عن أبي قتادة، قال: أنهم خرجوا مع رسولِ اللّٰه ﷺ وهم محرمون، وأبو قتادة حلال، وساق الحديث، وفيه فقال: (( هل معكم منه شيء؟ )) قالوا: معنا رِجلُه. قال: فأخذها رسولُ اللَّهِ ﷺ فأكلها."],"takhrij":"متفق عليه: رواه البخاري (٢٨٥٤)، ومسلم (١١٩٦: ٦٣).","grade":"متفق عليه","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2854) and Muslim (1196:63).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Qatadah said: They went out with the Messenger of Allah ﷺ while they were in ihram, and Abu Qatadah was not in ihram. Then he mentioned the narration, and in it he said: “Do you have any of it left with you?” They said: We have one of its legs. So the Messenger of Allah ﷺ took it and ate it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2854},{"key":"muslim","label":"مسلم","number":1196}]},{"num":4837,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن عثمان التيمي، قال: كنا مع طلحةَ بنِ عبيدِ اللَّه ونحن حُرُم، فأُهدي له طيرٌ وطلحةُ راقدٌ، فمنَّا من أكل، ومنَّا من تورَّع، فلما استيقظ طلحةُ وفَّق من أكله، وقال: أكلناه مع رسولِ اللّٰه ﷺ."],"takhrij":"صحيح: رواه مسلم (١١٩٧).","grade":"صحيح","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1197).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abd al-Rahman ibn Uthman al-Taymi said: We were with Talhah ibn Ubayd Allah while we were in ihram, and a bird was presented to him while Talhah was sleeping. Some of us ate, and some of us refrained. When Talhah awoke, he approved of those who had eaten it and said: We ate it with the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1197}]},{"num":4838,"demo":false,"sanad":"","matn":["عن عُمير بن سلمة الضمري، عن البهزي؛ أنَّ رسولَ اللَّهِ ﷺ خرج يريد مكة وهو مُحرِم، حتى إذا كان بالرَّوحاء إذا حمارٌ وحشيٌّ عقير، فذُكر ذلك لرسولِ اللّٰه ﷺ، فقال: (( دعوه، فإنَّه يُوشك أن يأتي صاحبُه )). فجاء البهزي - وهو صاحبُه - إلى النبيِّ ﷺ فقال: يا رسولَ اللَّه، شأنُكم بهذا الحمار، فأمر رسولُ اللَّه ﷺ أبا بكرٍ فقسمه بين الرفاق، ثم مضى حتى إذا كان بالأثاية بين الرُّويثة والعَرج إذا ظبيٌ حاقفٌ في ظلٍّ فيه سهمٌ، فزعم أنَّ رسولَ اللَّه ﷺ أمر رجلًا أن يقف عنده لا يريبه أحدٌ من الناس حتى يجاوزوه."],"takhrij":"صحيح: رواه مالك (٧٩).","grade":"صحيح","chapter_ar":"باب ما يحلّ للمحرم أكله من الصيد وما لا يحلّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (79).","chapter_en":"What is lawful for the muhrim to eat from hunted game and what is not lawful","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Umayr ibn Salamah al-Damri narrated from al-Bahzi that the Messenger of Allah ﷺ set out for Makkah while in ihram, and when he was at al-Rawha there was a wounded wild donkey. This was mentioned to the Messenger of Allah ﷺ, and he said: “Leave it, for its owner will soon come.” Then al-Bahzi — who was its owner — came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, do with this donkey as you wish. So the Messenger of Allah ﷺ ordered Abu Bakr to divide it among the travelers. Then he continued until, when he was at al-Athayah between al-Ruwaythah and al-‘Arj, there was a gazelle lying in the shade with an arrow in it, and he said that the Messenger of Allah ﷺ ordered a man to stand by it so that no one among the people would disturb it until they passed by."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":79}]},{"num":4839,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: سألتُ رسولَ اللّٰه ﷺ عن الضبع؟ فقال: (( هو صيد )). ويُجعلُ فيه كبشٌ إذا صاده المُحرِمُ."],"takhrij":"صحيح: رواه أبو داود (٣٨٠١)، وابن ماجه (٣٠٨٥)، وصححه ابن خزيمة (٢٦٤٥)، وابن حبان (٣٩٦٤).","grade":"صحيح","chapter_ar":"باب ما جاء في جزاء الصيد إذا قتله المحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3801), Ibn Majah (3085), and authenticated by Ibn Khuzaymah (2645) and Ibn Hibban (3964).","chapter_en":"What has been reported regarding compensation for game if the muhrim kills it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["Jabir ibn Abdullah said: I asked the Messenger of Allah ﷺ about the hyena, and he said: “It is game.” A ram is required as compensation if a person in ihram hunts it."]},"intro":{"ar":["قال اللّٰه تعالى: ( يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقْتُلُوا الصَّيْدَ وَأَنْتُمْ حُرُمٌ وَمَن قَتَلَهُ مِنكُم مُّتَعَمِّدًا فَجَزَاءٌ مِّثْلُ مَا قَتَلَ مِنَ النَّعَمِ يَحْكُمُ بِهِ ذَوَا عَدْلٍ مِنكُمْ هَدْيًا بَالِغَ الْكَعْبَةِ أَوْ كَفَّارَةٌ طَعَامُ مَسَاكِينَ أَوْ عَدْلُ ذَٰلِكَ صِيَامًا لِّيَذُوقَ وَبَالَ أَمْرِهِ ) [سورة المائدة: ٩٥]."],"en":["Allah the Exalted said: “O you who believe, do not kill game while you are in ihram. Whoever among you kills it deliberately, the compensation is an equivalent from grazing livestock, judged by two just men among you, as an offering brought to the Ka‘bah, or an expiation of feeding needy people, or the equivalent of that in fasting, so that he may taste the consequence of his deed.” [Surat al-Ma’idah: 95]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3801},{"key":"ibnmajah","label":"ابن ماجه","number":3085},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2645},{"key":"ibnhibban","label":"ابن حبان","number":3964}]},{"num":4840,"demo":false,"sanad":"","matn":["عن جابر، أنه قال: قضى عمر بن الخطاب في الضبع بكبش، وفي الغزال بعنز، وفي الأرنب بعناق، وفي الجربوع بجفرة."],"takhrij":"صحيح: رواه مالك في الموطأ لأبي مصعب (١٢٤٤)، والشافعي (٥٠٣).","grade":"صحيح","chapter_ar":"باب ما جاء في جزاء الصيد إذا قتله المحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik in al-Muwatta’ through the recension of Abu Mus‘ab (1244), and by al-Shafi‘i (503).","chapter_en":"What has been reported regarding compensation for game if the muhrim kills it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["Jabir said: Umar ibn al-Khattab ruled that the compensation for a hyena is a ram, for a gazelle a she-goat, for a rabbit a young she-goat, and for a jerboa a young she-goat that has reached a suitable age."]},"buhuth":{"ar":["قال الشافعي: (( وبهذا كله نأخذ؛ لأن هذا مثلُه من النعم ))."],"en":["Al-Shafi‘i said: “This is what we adopt in all of this, because these are their equivalents from livestock.”"]}},"tuhfa":{},"refs":[{"key":"malik/الموطا_لابی_مصعب","label":"مالك في الموطأ لأبي مصعب","number":1244},{"key":"الشافعی","label":"الشافعي","number":503}]},{"num":4841,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، قال: يا زيدَ بنَ أرقم، هل علمتَ أنَّ رسولَ اللّٰه ﷺ أُهدي له بيضاتُ نعامٍ وهو حرامٌ فردَّهُنَّ؟ قال: نعم."],"takhrij":"حسن: رواه ابن خزيمة (٢٦٤٤)، والحاكم (٤٥٢/١).","grade":"حسن","chapter_ar":"باب ما جاء في بيض الصيد","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (2644) and al-Hakim (1/452).","chapter_en":"What has been reported regarding the eggs of game","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Abdullah ibn Abbas said: O Zayd ibn Arqam, do you know that ostrich eggs were presented to the Messenger of Allah ﷺ while he was in ihram, and he returned them? He said: Yes."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2644},{"key":"hakim","label":"المستدرك على الصحيحين","number":1660,"n":1650}]},{"num":4842,"demo":false,"sanad":"","matn":["عن ابن عمر، أنَّ رسولَ اللَّهِ ﷺ قال: (( خَمْسٌ مِنَ الدَّوَابِّ لَيْسَ عَلَى المُحْرِمِ فِي قَتْلِهِنَّ جُنَاحٌ: الغُرَابُ، وَالْحِدَأَةُ، وَالْعَقْرَبُ، وَالْفَأْرَةُ، وَالْكَلْبُ العَقُورُ ))."],"takhrij":"متفق عليه: رواه مالك (٨٨)، والبخاري (١٨٢٦)، ومسلم (١١٩٩: ٧٦).","grade":"متفق عليه","chapter_ar":"باب ما يجوز للمحرم قتله من الدواب في الحل والحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (88), al-Bukhari (1826), and Muslim (1199:76).","chapter_en":"What the muhrim is allowed to kill from harmful creatures inside and outside the sanctuary","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “There is no blame on the muhrim for killing five kinds of creatures: the crow, the kite, the scorpion, the mouse, and the vicious dog.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":88},{"key":"bukhari","label":"البخاري","number":1826},{"key":"muslim","label":"مسلم","number":1199}]},{"num":4843,"demo":false,"sanad":"","matn":["عن حفصة زوج النبيِّ ﷺ قالت: قال رسولُ اللَّهِ ﷺ: (( خَمْسٌ مِنَ الدَّوَابِّ كُلُّهُنَّ فَواسِقُ، لا حرج على من قتلهن: العقرب، والغراب، والحدأة، والفأرة، والكلب العقور ))."],"takhrij":"متفق عليه: رواه البخاري (١٨٢٨)، ومسلم (١٢٠٠)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما يجوز للمحرم قتله من الدواب في الحل والحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1828) and Muslim (1200). This wording is that of Muslim.","chapter_en":"What the muhrim is allowed to kill from harmful creatures inside and outside the sanctuary","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Hafsah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ said: “Five creatures are all harmful creatures; there is no blame upon one who kills them: the scorpion, the crow, the kite, the mouse, and the vicious dog.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1828},{"key":"muslim","label":"مسلم","number":1200}]},{"num":4844,"demo":false,"sanad":"","matn":["عن عائشة، أنَّ رسولَ اللَّهِ ﷺ قال: (( خَمْسٌ مِنَ الدَّوَابِّ كُلُّهُنَّ فَواسِقُ، يُقْتَلْنَ فِي الحَرَمِ: الغُرَابُ، وَالْحِدَأَةُ، وَالْعَقْرَبُ، وَالْفَأْرَةُ، وَالْكَلْبُ العَقُورُ ))."],"takhrij":"متفق عليه: رواه البخاري (١٨٢٩)، ومسلم (١١٩٨: ٧١)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما يجوز للمحرم قتله من الدواب في الحل والحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1829) and Muslim (1198:71). This wording is that of al-Bukhari.","chapter_en":"What the muhrim is allowed to kill from harmful creatures inside and outside the sanctuary","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Aisha reported that the Messenger of Allah ﷺ said: “Five creatures are all harmful and may be killed even within the sanctuary: the crow, the kite, the scorpion, the mouse, and the vicious dog.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1829},{"key":"muslim","label":"مسلم","number":1198}]},{"num":4845,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، قال: بينما نحن مع النبيِّ ﷺ في غارٍ بِمِنى إذ نزلت عليه: ( وَالْمُرْسَلَاتِ عُرْفًا ) [سورة المرسلات: ١]، وإنه ليتلوها، وإني لأتلقاها من فيه، وإن فاه لرطبٌ بها، إذ وثبت علينا حيَّةٌ، فقال النبيُّ ﷺ: (( اقتلوها )). فابتدرناها فذهبت، فقال النبيُّ ﷺ: (( وُقِيَتْ شَرَّكُمْ كما وُقيتُم شرَّها ))."],"takhrij":"متفق عليه: رواه البخاري (١٨٣٠)، ومسلم (٢٢٣٤)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما يجوز للمحرم قتله من الدواب في الحل والحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1830) and Muslim (2234). This wording is that of al-Bukhari.","chapter_en":"What the muhrim is allowed to kill from harmful creatures inside and outside the sanctuary","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abdullah ibn Mas‘ud said: While we were with the Prophet ﷺ in a cave at Mina, the verse “By those sent forth in succession” [Surat al-Mursalat: 1] was revealed to him. He was reciting it, and I was receiving it directly from his mouth, and his mouth was still moist with it, when suddenly a snake sprang upon us. The Prophet ﷺ said: “Kill it.” So we rushed toward it, but it escaped. Then the Prophet ﷺ said: “It was protected from your harm just as you were protected from its harm.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1830},{"key":"muslim","label":"مسلم","number":2234}]},{"num":4846,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسولَ اللّٰه ﷺ قال: (( خَمْسٌ قَتْلُهُنَّ حَلالٌ فِي الحَرَمِ: الحَيَّةُ، وَالعَقْرَبُ، وَالحُدَيَّا، وَالفَأْرَةُ، وَالكَلْبُ العَقُورُ ))."],"takhrij":"حسن: رواه أبو داود (١٨٤٧).","grade":"حسن","chapter_ar":"باب ما يجوز للمحرم قتله من الدواب في الحل والحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1847).","chapter_en":"What the muhrim is allowed to kill from harmful creatures inside and outside the sanctuary","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ, said: “Five may lawfully be killed in the Sacred Precinct: the snake, the scorpion, the kite, the mouse, and the vicious dog.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1847}]},{"num":4847,"demo":false,"sanad":"","matn":["عن نُبَيْه بن وهب - أخي بني عبد الدار -: أَنَّ عُمَرَ بْنَ عُبَيْدِ اللّٰهِ أَرْسَلَ إِلَى أَبَانَ بْنِ عُثْمَانَ - وَأَبَانُ يَوْمَئِذٍ أَمِيرُ الحَاجِّ - وَهُمَا مُحْرِمَانِ: إِنِّي قَدْ أَرَدْتُ أَنْ أُنْكِحَ طَلْحَةَ بْنَ عُمَرَ بْنَتَ شَيْبَةَ بْنِ جُبَيْرٍ، وَأَرَدْتُ أَنْ تَحْضُرَ. فَأَنْكَرَ ذَلِكَ عَلَيْهِ أَبَانُ، قَالَ: سَمِعْتُ عُثْمَانَ بْنَ عَفَّانَ يَقُولُ: قَالَ رَسُولُ اللّٰهِ ﷺ: (( لا يَنْكِحُ المُحْرِمُ، وَلا يُنْكِحُ، وَلا يَخْطُبُ ))."],"takhrij":"صحيح: رواه مالك (٧٠)، ومسلم (١٤٠٩).","grade":"صحيح","chapter_ar":"باب تحريم نكاح المحرم وخطبته","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (70) and Muslim (1409).","chapter_en":"the prohibition of marriage and proposing marriage for a person in ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Nubayh ibn Wahb, a man from Banu Abd al-Dar, reported that Umar ibn Ubayd Allah sent word to Aban ibn Uthman, while Aban was the leader of the pilgrims and both were in ihram, saying: “I want to marry Talhah ibn Umar to the daughter of Shaybah ibn Jubayr, and I want you to attend.” Aban objected to that and said: “I heard Uthman ibn Affan say that the Messenger of Allah ﷺ, said: ‘A person in ihram must not marry, give another in marriage, or make a marriage proposal.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":70},{"key":"muslim","label":"مسلم","number":1409}]},{"num":4848,"demo":false,"sanad":"","matn":["عن ابن عمر، عن النبي ﷺ قال: (( المُحْرِمُ لا يَنْكِحُ، وَلا يُنْكِحُ، وَلا يَخْطُبُ ))."],"takhrij":"حسن: رواه الدارقطني (٣٦٥٠).","grade":"حسن","chapter_ar":"باب تحريم نكاح المحرم وخطبته","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (3650).","chapter_en":"the prohibition of marriage and proposing marriage for a person in ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Ibn Umar reported from the Prophet ﷺ, that he said: “A person in ihram must not marry, give another in marriage, or make a marriage proposal.”"]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطني","number":3650},{"key":"sh9771","label":"سنن الدارقطني","number":3650,"n":3662}]},{"num":4849,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ النبيَّ ﷺ تزوّج ميمونةَ وهو مُحْرِمٌ."],"takhrij":"متفق عليه: رواه البخاري (٥١١٤)، ومسلم (٤٦: ١٤١٠).","grade":"متفق عليه","chapter_ar":"باب زواج النبي ﷺ من ميمونة هل كان حلالًا أو محرمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5114) and Muslim (1410).","chapter_en":"the marriage of the Prophet ﷺ, to Maymunah: was he in a lawful state or in ihram?","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Ibn Abbas reported that the Prophet ﷺ, married Maymunah while he was in ihram."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5114},{"key":"muslim","label":"مسلم","number":46}]},{"num":4850,"demo":false,"sanad":"","matn":["عن عائشة، قالت: تزوّج النبيُّ ﷺ بعضَ نسائه وهو مُحْرِمٌ، واحتجم وهو مُحْرِمٌ."],"takhrij":"صحيح: رواه ابن حبان (٤١٣٢)، والطحاوي في “مشكله” (٥٧٩٨)، و”معانيه” (٢٦٩/٢).","grade":"صحيح","chapter_ar":"باب زواج النبي ﷺ من ميمونة هل كان حلالًا أو محرمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4132), and by al-Tahawi in Mushkil al-Athar (5798) and Sharh Maʻani al-Athar (2/269).","chapter_en":"the marriage of the Prophet ﷺ, to Maymunah: was he in a lawful state or in ihram?","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Aishah said: The Prophet ﷺ, married one of his wives while in ihram, and he was cupped while in ihram."]}},"tuhfa":{},"refs":[{"key":"الطحاوی/مشکلہ","label":"الطحاوي في “مشكله”","number":5798},{"key":"معانیہ","label":"”معانيه”","number":269},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":6576,"n":6574}]},{"num":4851,"demo":false,"sanad":"","matn":["عن يزيد بن الأصم قال: حدّثتني ميمونة بنت الحارث؛ أنّ رسولَ اللّٰه ﷺ تزوّجها وهو حلال. قال: وكانت خالتي وخالةَ ابنِ عباس."],"takhrij":"صحيح: رواه مسلم (١٤١١).","grade":"صحيح","chapter_ar":"باب زواج النبي ﷺ من ميمونة هل كان حلالًا أو محرمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1411).","chapter_en":"the marriage of the Prophet ﷺ, to Maymunah: was he in a lawful state or in ihram?","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Yazid ibn al-Asamm said: Maymunah bint al-Harith told me that the Messenger of Allah ﷺ, married her while he was not in ihram. He said: She was my maternal aunt and the maternal aunt of Ibn Abbas."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1411}]},{"num":4852,"demo":false,"sanad":"","matn":["عن ميمونة، قالت: تزوّجني رسولُ اللّٰه ﷺ وأنا حلالٌ، بعد ما رجعنا من مكة."],"takhrij":"صحيح: رواه أحمد (٢٦٨١٥). ورواه أبو داود (١٨٣٩) وفيه: تزوّجني النبيُّ ﷺ ونحن حلالان بسَرِف.","grade":"صحيح","chapter_ar":"باب زواج النبي ﷺ من ميمونة هل كان حلالًا أو محرمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (26815). Abu Dawud (1839) also narrated it with the wording: “The Prophet ﷺ, married me while we were both not in ihram at Sarif.”","chapter_en":"the marriage of the Prophet ﷺ, to Maymunah: was he in a lawful state or in ihram?","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Maymunah said: The Messenger of Allah ﷺ, married me while I was not in ihram, after we had returned from Makkah."]},"buhuth":{"ar":["قولها: (( تزوّجني رسولُ اللّٰه ﷺ … بعدما رجعنا من مكة )) أي: بنى بها."],"en":["Her statement, “The Messenger of Allah ﷺ married me … after we returned from Makkah,” means that he consummated the marriage then."]}},"tuhfa":{},"refs":[{"key":"ورواہ_ابو_داود","label":". ورواه أبو داود","number":1839},{"key":"ahmad","label":"مسند الإمام أحمد","number":26815,"n":26815}]},{"num":4853,"demo":false,"sanad":"","matn":["عن أبي رافع، قال: تزوّج رسولُ اللّٰه ﷺ ميمونةَ وهو حلال، وبنى بها وهو حلال، وكنتُ أنا الرسولَ فيما بينهما."],"takhrij":"حسن: رواه الترمذي (٨٤١) وحسّنه، وأحمد (٢٧١٩٧)، وصحّحه ابن حبان (٤١٣٠).","grade":"حسن","chapter_ar":"باب زواج النبي ﷺ من ميمونة هل كان حلالًا أو محرمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (841), who graded it Hasan, and by Ahmad (27197); Ibn Hibban (4130) graded it authentic.","chapter_en":"the marriage of the Prophet ﷺ, to Maymunah: was he in a lawful state or in ihram?","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Abu Rafi said: The Messenger of Allah ﷺ, married Maymunah while he was not in ihram, and consummated the marriage while he was not in ihram, and I was the messenger between them."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":841},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4130},{"key":"ahmad","label":"مسند الإمام أحمد","number":27197,"n":27197}]},{"num":4854,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: كانت عُكاظُ، ومَجَنَّةُ، وذو المَجازِ أسواقًا في الجاهلية، فلمّا كان الإسلامُ فكأنهم تأثّموا فيه، فنزلت: ( لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ ) في مواسم الحجّ، قرأها ابن عباس."],"takhrij":"صحيح: رواه البخاري (٢٠٥٠).","grade":"صحيح","chapter_ar":"باب التجارة في الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2050).","chapter_en":"trade during Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":22,"content":{"translation":{"en":["Abdullah ibn Abbas said: Ukaz, Majannah, and Dhu al-Majaz were marketplaces in the pre-Islamic period. When Islam came, it was as though the people felt uneasy about trading there, so the verse was revealed: “There is no sin upon you in seeking bounty from your Lord” during the Hajj seasons. Ibn Abbas recited it this way."]},"intro":{"ar":["قال اللّٰه تعالى: ( لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللّٰهَ عِنْدَ المَشْعَرِ الحَرَامِ وَاذْكُرُوهُ كَمَا هَدَاكُمْ وَإِنْ كُنْتُمْ مِنْ قَبْلِهِ لَمِنَ الضَّالِّينَ ) [سورة البقرة: ١٩٨]."],"en":["Allah Most High said: “There is no sin upon you in seeking bounty from your Lord. Then when you depart from Arafat, remember Allah at al-Mashar al-Haram, and remember Him as He guided you, though before that you were surely among those astray.” [Surat al-Baqarah: 198]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2050}]},{"num":4855,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عباس، قال: (( إنّ الناسَ في أوّلِ الحجِّ كانوا يتبايعون بمنىً وعرفةَ وسوقِ ذي المجازِ ومواسمِ الحجِّ، فخافوا البيعَ وهم حُرُمٌ، فأنزل اللّٰه سبحانه: ( لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ ) في مواسم الحجِّ )). قال: فحدّثني عبيدُ بن عمير أنّه كان يقرؤها في المصحف."],"takhrij":"حسن: رواه أبو داود (١٧٣٤).","grade":"حسن","chapter_ar":"باب التجارة في الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1734).","chapter_en":"trade during Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":22,"content":{"translation":{"en":["Abdullah ibn Abbas said: In the early days, people used to trade in Mina, Arafah, the market of Dhu al-Majaz, and the Hajj seasons. Then they became afraid to trade while they were in ihram, so Allah, Glorified be He, revealed: “There is no sin upon you in seeking bounty from your Lord” during the Hajj seasons. He said: Ubayd ibn Umayr told me that he used to read it that way in the written text."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1734}]},{"num":4856,"demo":false,"sanad":"","matn":["عن أبي أُمامة التيمي، قال: كنتُ رجلًا أُكْرِي في هذا الوجه، وكان ناسٌ يقولون لي: إنّه ليس لك حجٌّ. فلقيتُ ابن عمر، فقلتُ: يا أبا عبد الرحمن، إنّي رجلٌ أُكْرِي في هذا الوجه، وإنّ ناسًا يقولون لي: إنّه ليس لك حجٌّ؟ فقال ابن عمر: أليس تُحْرِمُ، وتُلَبِّي، وتطوفُ بالبيت، وتُفيضُ من عرفات، وترمي الجمار؟ قال: قلتُ: بلى. قال: فإنّ لك حجًّا. جاء رجلٌ إلى النبيِّ ﷺ فسأله عن مثلِ ما سألتني عنه، فسكت عنه رسولُ اللّٰه ﷺ فلم يُجِبْه حتى نزلت هذه الآية: ( لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ ). فأرسل إليه رسولُ اللّٰه ﷺ وقرأ عليه هذه الآية وقال: (( لك حجٌّ ))."],"takhrij":"حسن: رواه أبو داود (١٧٣٣).","grade":"حسن","chapter_ar":"باب التجارة في الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1733).","chapter_en":"trade during Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":22,"content":{"translation":{"en":["Abu Umamah al-Taymi said: I was a man who hired out my riding service on this route, and some people would tell me: “You have no Hajj.” So I met Ibn Umar and said: “O Abu Abd al-Rahman, I am a man who hires out my riding service on this route, and some people say I have no Hajj.” Ibn Umar said: “Do you not enter ihram, recite the talbiyah, circumambulate the House, depart from Arafah, and stone the pillars?” I said: “Yes.” He said: “Then you do have Hajj.” A man came to the Prophet ﷺ, and asked him the same as what you asked me. The Messenger of Allah ﷺ did not answer him until this verse was revealed: “There is no sin upon you in seeking bounty from your Lord.” Then the Messenger of Allah ﷺ sent for him, recited this verse to him, and said: “You do have Hajj.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1733}]},{"num":4857,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسولُ اللّٰه ﷺ: (( من حجَّ هذا البيتَ، فلم يرفثْ، ولم يفسقْ، رجعَ كما ولدته أمُّه ))."],"takhrij":"متفق عليه: رواه البخاري (١٨١٩)، ومسلم (١٣٥٠)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن الرفث والفسوق في الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1819) and Muslim (1350), and this wording is from al-Bukhari.","chapter_en":"the prohibition of sexual speech and sinful conduct during Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":23,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, said: “Whoever performs Hajj to this House and does not engage in sexual speech or sinful conduct returns as on the day his mother gave birth to him.”"]},"buhuth":{"ar":["قوله: (( فلم يرفث )) المراد بالرّفث الجماع، ويطلق على التعريض به، وعلى الفحش في القول. وقوله: (( ولم يفسق )) أي لم يأتِ بسيئةٍ ولا معصية. فتح الباري (٣/٣٨٢)."],"en":["His statement, “does not engage in sexual speech,” means intercourse, and it is also used for speaking suggestively about it and for obscene speech. His statement, “and does not commit sinful conduct,” means that he does not commit any sin or act of disobedience. Fath al-Bari (3/382)."]},"intro":{"ar":["قال اللّٰه تعالى: ( الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ فَمَنْ فَرَضَ فِيهِنَّ الحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الحَجِّ ) [البقرة: ١٩٧]."],"en":["Allah Most High said: “Hajj is in well-known months, so whoever undertakes Hajj in them, then there is to be no sexual speech, no sinful conduct, and no arguing during Hajj.” [Surat al-Baqarah: 197]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1819},{"key":"muslim","label":"مسلم","number":1350}]},{"num":4858,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر، قالت: خرجنا مع رسولِ اللّٰه ﷺ حُجّاجًا، حتى إذا كنّا بالعَرْجِ نزل رسولُ اللّٰه ﷺ، ونزلنا، فجلستْ عائشةُ رضي اللّٰه عنها إلى جنب رسولِ اللّٰه ﷺ، وجلستُ إلى جنب أبي، وكانت زِمالةُ أبي بكرٍ وزِمالةُ رسولِ اللّٰه ﷺ واحدةً مع غلامٍ لأبي بكر، فجلس أبو بكرٍ ينتظر أن يطلع عليه، فطلع وليس معه بعيرُه، قال: أين بعيرُك؟ قال: أضللتُه البارحة. قال: فقال أبو بكر: بعيرٌ واحدٌ تُضِلُّه! قال: فطفق يضربه، ورسولُ اللّٰه ﷺ يتبسّم ويقول: (( انظروا إلى هذا المُحْرِمِ ما يصنع )) ويتبسّم."],"takhrij":"حسن: رواه أبو داود (١٨١٨) - واللفظ له -، وابن ماجه (٢٩٣٣).","grade":"حسن","chapter_ar":"باب في المحرم يؤدّب غلامه ومن تحت يده","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1818), and this is his wording, and Ibn Majah (2933).","chapter_en":"a person in ihram disciplining his servant and those under his authority","part_en":"The Book of Pilgrimage","group_ar":"جموع ما يباح للمحرم وما يحرم عليه","group_en":"Chapters on what is permissible for the person in ihram and what is forbidden to him","part_no":16,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Asma bint Abi Bakr said: We went out with the Messenger of Allah ﷺ, as pilgrims, until when we reached al-Arj, the Messenger of Allah ﷺ halted and we also halted. Aishah, may Allah be pleased with her, sat beside the Messenger of Allah ﷺ, and I sat beside my father. The travel provisions of Abu Bakr and the travel provisions of the Messenger of Allah ﷺ were together with a servant of Abu Bakr. Abu Bakr sat waiting for him to appear, and he came without his camel. He said: “Where is your camel?” He said: “I lost it last night.” Abu Bakr said: “One camel, and you lose it!” Then he started striking him, while the Messenger of Allah ﷺ, smiled and said: “Look at this person in ihram and what he is doing,” and he smiled."]},"buhuth":{"ar":["وقوله: (( زِمالة )) بكسر الزاي، أي أدوات السفر وآلاته مما يتعلّق به."],"en":["The word “zimalah” with a kasrah on the zay means travel equipment and supplies connected to the journey."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1818},{"key":"ibnmajah","label":"ابن ماجه","number":2933}]},{"num":4859,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ، قالت: خرجنا مع رسولِ اللّٰه ﷺ لخمسِ ليالٍ بقين من ذي القعدة … الحديث."],"takhrij":"متفق عليه: رواه مالك (١٧٩)، والبخاري في الحج (١٧٠٩)، ومسلم في الحج (١٢٥: ١٢١١).","grade":"متفق عليه","chapter_ar":"باب وقت خروج النبيّ وأصحابه من المدينة عام حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (179), al-Bukhari in the Book of Hajj (1709), and Muslim in the Book of Hajj (1211).","chapter_en":"the time when the Prophet ﷺ and his Companions left Madinah in the year of the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Aishah, the wife of the Prophet ﷺ, said: We went out with the Messenger of Allah ﷺ with five nights remaining of Dhu al-Qadah … the hadith."]},"buhuth":{"ar":["ورواه البخاري (١٧٨٣)، ومسلم (١١٥: ١٢١١) عن عائشة، قالت: (( خرجنا مع رسول اللّٰه ﷺ في حجّة الوداع موافين لهلال ذي الحجة )) الحديث.","فقوله: (( موافين لهلال ذي الحجة )) أي قرب طلوعه، والخمس قريبة من آخر الشهر، وقد وافاهم هلال ذي الحجة وهم في الطريق؛ لأنهم دخلوا مكة في الرابع من ذي الحجة، كما في حديث ابن عباس الآتي."],"en":["Al-Bukhari (1783) and Muslim (1211) also narrated from Aishah that she said: “We went out with the Messenger of Allah ﷺ in the Farewell Pilgrimage, arriving around the sighting of the crescent of Dhu al-Hijjah” … the hadith.","Her statement, “arriving around the sighting of the crescent of Dhu al-Hijjah,” means near its appearance. Five nights remained from the end of the month, and the crescent of Dhu al-Hijjah appeared while they were on the road, because they entered Makkah on the fourth of Dhu al-Hijjah, as will come in the narration of Ibn Abbas."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":179},{"key":"bukhari/الحج","label":"البخاري في الحج","number":1709},{"key":"muslim/الحج","label":"مسلم في الحج","number":125}]},{"num":4860,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: انطلق النبيُّ ﷺ من المدينة … وذلك لخمسٍ بقين من ذي القعدة، فقدم مكة لأربعِ ليالٍ خَلَوْن من ذي الحجة … الحديث."],"takhrij":"صحيح: رواه البخاري (١٥٤٥).","grade":"صحيح","chapter_ar":"باب وقت خروج النبيّ وأصحابه من المدينة عام حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1545).","chapter_en":"the time when the Prophet ﷺ and his Companions left Madinah in the year of the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Prophet ﷺ, departed from Madinah … and that was with five nights remaining of Dhu al-Qadah, and he arrived in Makkah after four nights of Dhu al-Hijjah had passed … the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1545}]},{"num":4861,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: إنَّ رسولَ اللّٰه ﷺ مكث تسعَ سنينَ لم يحجَّ، ثم أذَّن في الناس في العاشرة أن رسولَ اللّٰه ﷺ حاجٌّ … الحديث بطوله."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب وقت خروج النبيّ وأصحابه من المدينة عام حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"the time when the Prophet ﷺ and his Companions left Madinah in the year of the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ, remained for nine years without performing Hajj. Then in the tenth year, it was announced to the people that the Messenger of Allah ﷺ would perform Hajj … the full hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":4862,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: كانوا يرون أن العمرة في أشهر الحج من أفجر الفجور في الأرض، ويجعلون المحرَّم صفراً، ويقولون: إذا برأ الدبر، وعفا الأثر، وانسلخ صفر، حلّت العمرة لمن اعتمر. قدم النبيُّ ﷺ وأصحابه صبيحة رابعةٍ مهلّين بالحج، فأمرهم أن يجعلوها عمرةً، فتعاظم ذلك عندهم، فقالوا: يا رسول اللّٰه، أيُّ الحلِّ؟ قال: (( حِلٌّ كُلُّهُ ))."],"takhrij":"متفق عليه: رواه البخاري (١٥٦٤)، ومسلم (١٩٨: ١٢٤٠).","grade":"متفق عليه","chapter_ar":"باب وقت دخول النبي ﷺ إلى مكة عام حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1564) and Muslim (1240).","chapter_en":"the time when the Prophet ﷺ, entered Makkah in the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Ibn Abbas said: The people used to think that performing Umrah during the months of Hajj was among the gravest sins on earth. They used to shift the sacred months and say: “When the camel sores have healed, the traces have faded, and Safar has ended, then Umrah becomes lawful for the one who wants to perform it.” The Prophet ﷺ, and his Companions arrived on the morning of the fourth day, entering ihram for Hajj, and he ordered them to make it Umrah. That seemed very great to them, and they said: “O Messenger of Allah ﷺ, what kind of release?” He said: “A complete release.”"]},"buhuth":{"ar":["وفي رواية عند مسلم (١٩٩): (( فقدم لأربعٍ مضين من ذي الحجة ))."],"en":["In another narration in Muslim (199): “He arrived after four days of Dhu al-Hijjah had passed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1564},{"key":"muslim","label":"مسلم","number":198}]},{"num":4863,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: انطلق النبيُّ ﷺ من المدينة … وذلك لخمسٍ بقين من ذي القعدة، فقدم مكة لأربعِ ليالٍ خَلَوْن من ذي الحجة … الحديث."],"takhrij":"صحيح: رواه البخاري (١٥٤٥).","grade":"صحيح","chapter_ar":"باب وقت دخول النبي ﷺ إلى مكة عام حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1545).","chapter_en":"the time when the Prophet ﷺ, entered Makkah in the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Prophet ﷺ, departed from Madinah … and that was with five nights remaining of Dhu al-Qadah, and he arrived in Makkah after four nights of Dhu al-Hijjah had passed … the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1545}]},{"num":4864,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ رسولَ اللّٰه ﷺ كان ينزل بذي طُوًى ويبيت به حتى يصلّي الصبح حين يقدم مكة، ومصلّى رسولِ اللّٰه ﷺ ذلك على أكمةٍ غليظةٍ، ليس في المسجد الذي بُنيَ ثمَّ، ولكن أسفل من ذلك على أكمةٍ غليظةٍ."],"takhrij":"متفق عليه: رواه البخاري (٤٩١)، ومسلم (٢٢٨: ١٢٥٩)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب نزول النبي ﷺ بذي طوى والمبيت بها حتى يصبح إذا دخل مكة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (491) and Muslim (1259), and this wording is from Muslim.","chapter_en":"The Prophet ﷺ staying at Dhū Ṭuwā and spending the night there until morning when entering Makkah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ, used to stay at Dhu Tuwa and spend the night there until he prayed Fajr when entering Makkah. The place where the Messenger of Allah ﷺ prayed was on a thick mound, not in the mosque that was later built there, but lower than that on a thick mound."]},"buhuth":{"ar":["قوله: (( بذي طُوًى )) بضم الطاء المهملة بعدها واو، وآخره ألف مقصورة، هو اسم وادٍ بين مقبرة الجُحون بالمعلاة وبين ريع الكحل المسمّى بالثنية الخضراء، في محلة “جرول” الآن."],"en":["The phrase “at Dhu Tuwa,” with the letter ta pronounced with a dammah and followed by a waw, ending with a shortened alif, is the name of a valley between the al-Juhun cemetery in al-Maʻlah and Riʻ al-Kahl, known as al-Thaniyyah al-Khadra, in the area now called Jarwal."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":491},{"key":"muslim","label":"مسلم","number":228}]},{"num":4865,"demo":false,"sanad":"","matn":["عن نافعٍ، أنَّ عبدَ الله بنَ عمرَ أخبره: أنَّ رسولَ الله ﷺ كان ينزل بذي الحليفة حين يَعتمر، وفي حجته حين حجَّ تحت سَمُرةٍ في موضع المسجد الذي بذي الحليفة، وكان إذا رجع من غزوٍ كان في تلك الطريق، أو حجٍّ أو عمرةٍ، هبط من بطن وادٍ، فإذا ظهر من بطن وادٍ أناخ بالبطحاء التي على شفير الوادي الشرقية، فَعَرَّسَ ثمَّ حتى يُصبح، ليس عند المسجد الذي بحجارة، ولا على الأكمة التي عليها المسجد، كان ثمَّ خليجٌ يُصلّي عبدُ الله عنده، في بطنه كثيبٌ، كان رسولُ الله ﷺ ثمَّ يُصلّي، فدحا السيل فيه بالبطحاء حتى دفن ذلك المكان الذي كان عبدُ الله يُصلّي فيه.","وأنَّ عبدَ الله بنَ عمرَ حدَّثه أنَّ النبيَّ ﷺ صلَّى حيث المسجدُ الصغيرُ الذي دون المسجد الذي بشرف الروحاء، وقد كان عبدُ الله يعلم المكان الذي كان صلّى فيه النبيُّ ﷺ، يقول: ثمَّ عن يمينك حين تقوم في المسجد تُصلّي، وذلك المسجد على حافة الطريق اليمنى وأنت ذاهبٌ إلى مكة، بينه وبين المسجد الأكبر رميةٌ بحجر أو نحو ذلك.","وأنَّ ابنَ عمرَ كان يُصلّي إلى العِرْق الذي عند منصرف الروحاء، وذلك العِرْقُ انتهاءُ طرفِه على حافة الطريق دون المسجد الذي بينه وبين المنصرف، وأنت ذاهبٌ إلى مكة، وقد ابتُنِيَ ثمَّ مسجدٌ، فلم يكن عبدُ الله بنُ عمرَ يُصلّي في ذلك المسجد، كان يتركه عن يساره ووراءه، ويُصلّي أمامه إلى العِرْق نفسه. وكان عبدُ الله يروح من الروحاء، فلا يُصلّي الظهر حتى يأتي ذلك المكان، فيصلّي فيه الظهر، وإذا أقبل من مكة، فإن مرَّ به قبل الصبح بساعةٍ أو من آخر السحر، عرَّس حتى يُصلّي بها الصبح.","وأنَّ عبدَ الله حدَّثه أنَّ النبيَّ ﷺ كان ينزل تحت سَرْحةٍ ضخمةٍ دون الرويثة، عن يمين الطريق، ووجاه الطريق، في مكانٍ بطحٍ سهلٍ، حتى يُفضي من أكمةٍ دوين بريد الرويثة بميلين، وقد انكسر أعلاها، فانثنى في جوفها وهي قائمةٌ على ساقٍ، وفي ساقها كثبٌ كثيرة.","وأنَّ عبدَ الله بنَ عمرَ حدَّثه أنَّ النبيَّ ﷺ صلَّى في طرف تلعةٍ من وراء العرج، وأنت ذاهبٌ إلى هضبةٍ، عند ذلك المسجد قبران أو ثلاثةٌ، على القبور رَضْمٌ من حجارة، عن يمين الطريق عند سلمات الطريق، بين أولئك السلمات، كان عبدُ الله يروح من العرج بعد أن تميل الشمس بالهاجرة، فيصلّي الظهر في ذلك المسجد.","وأنَّ عبدَ الله بنَ عمرَ حدَّثه أنَّ رسولَ الله ﷺ نزل عند سَرَحاتٍ عن يسار الطريق، في مَسيلٍ دون هَرْشى، ذلك المسيل لاصقٌ بكُراع هَرْشى، بينه وبين الطريق قريبٌ من غلوةٍ، وكان عبدُ الله يُصلّي إلى سَرْحةٍ هي أقربُ السرحات إلى الطريق، وهي أطولهنَّ.","وأنَّ عبدَ الله بنَ عمرَ حدَّثه أنَّ النبيَّ ﷺ كان ينزل في المسيل الذي في أدنى مَرِّ الظهران قِبَلَ المدينة، حين يهبط من الصَّفراوات، ينزل في بطن ذلك المسيل عن يسار الطريق، وأنت ذاهبٌ إلى مكة، ليس بين منزل رسول الله ﷺ وبين الطريق إلا رميةٌ بحجر.","وأنَّ عبدَ الله بنَ عمرَ حدَّثه أنَّ النبيَّ ﷺ كان ينزل بذي طُوًى ويبيت حتى يُصبح، يُصلّي الصبح حين يقدم مكة، ومصلّى رسول الله ﷺ ذلك على أكمةٍ غليظةٍ، ليس في المسجد الذي بُني ثمَّ، ولكن أسفلَ من ذلك على أكمةٍ غليظةٍ.","وأنَّ عبدَ الله بنَ عمرَ حدَّثه أنَّ النبيَّ ﷺ استقبل فَرْضَتَيِ الجبل الذي بينه وبين الجبل الطويل نحو الكعبة، فجعل المسجد الذي بُني ثمَّ يسارَ المسجد بطرف الأكمة، ومصلّى النبيِّ ﷺ أسفلَ منه على الأكمة السوداء، تدع من الأكمة عشرة أذرعٍ أو نحوها، ثم تُصلّي مستقبل الفرضتين من الجبل الذي بينك وبين الكعبة."],"takhrij":"متفق عليه: رواه البخاري (٤٩٢-٤٨٤)، ومسلم (٢٨:١٢٦٠، ٢٨:١٢٥٩). والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب نزول النبي ﷺ بذي طوى والمبيت بها حتى يصبح إذا دخل مكة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (484–492) and Muslim (1259, 1260). The wording here is that of al-Bukhari.","chapter_en":"The Prophet ﷺ staying at Dhū Ṭuwā and spending the night there until morning when entering Makkah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Nafi reported that Abdullah ibn Umar told him that the Messenger of Allah ﷺ, used to stop at Dhu al-Hulayfah when setting out for Umrah, and during his Hajj when he performed Hajj, beneath an acacia tree at the place of the mosque that is at Dhu al-Hulayfah. When he returned from a military expedition by that route, or from Hajj or Umrah, he would descend from the bottom of a valley, and when he emerged from the valley floor, he would make his camel kneel at the broad gravel plain on the eastern edge of the valley, and he would rest there at night until morning. This was not near the mosque built with stones, nor on the hill upon which the mosque stood. There was a small channel there where Abdullah used to pray, and in its bed there was a sand mound. The Messenger of Allah ﷺ, used to pray there. Then the flood spread across that plain until it buried the place where Abdullah used to pray.","And Abdullah ibn Umar also told him that the Prophet ﷺ, prayed where the small mosque is that is below the mosque at the high ground of al-Rawha. Abdullah knew the exact place where the Prophet ﷺ had prayed, and he would say: It is there, to your right, when you stand in the mosque praying. That mosque is on the right edge of the road as you head toward Makkah, and between it and the larger mosque is about the distance of a stone’s throw, or something close to that.","And Ibn Umar used to pray facing the ridge at the end of al-Rawha’s departure point. The end of that ridge was on the edge of the road before the mosque that lay between it and the turning point, as you headed toward Makkah. A mosque was later built there, but Abdullah ibn Umar would not pray in that mosque; instead he would leave it to his left and behind him, and pray in front of it, facing the ridge itself. Abdullah would depart from al-Rawha and would not pray Dhuhr until he reached that place, and then he would pray Dhuhr there. When he came from Makkah and passed by it about an hour before dawn or in the last part of the pre-dawn time, he would rest there until he prayed Fajr there.","And Abdullah told him that the Prophet ﷺ, used to stop beneath a large tree below al-Ruwaythah, on the right side of the road and facing it, in a broad and level place, until it opened out from a hillock just before the al-Ruwaythah milestone by about two miles. The upper part of the tree had broken and bent into its hollow, though it was still standing on its trunk, and around its trunk were many mounds of sand.","And Abdullah ibn Umar told him that the Prophet ﷺ, prayed at the edge of a rising valley path beyond al-Arj, as you head toward a hill. Near that mosque were two or three graves, with stones heaped over them, on the right side of the road near the marked rock formations of the road, between those formations. Abdullah used to leave al-Arj after the sun had declined in the midday heat, and then he would pray Dhuhr in that mosque.","And Abdullah ibn Umar told him that the Messenger of Allah ﷺ, stopped by some trees on the left side of the road, in a watercourse below Harsha. That watercourse was attached to the edge of Harsha, and between it and the road was a distance close to the range of an arrow shot. Abdullah used to pray facing a tree that was the nearest of those trees to the road, and it was the tallest of them.","And Abdullah ibn Umar told him that the Prophet ﷺ, used to stop in the watercourse at the lower end of Marr al-Zahran toward Madinah, when descending from al-Safrawat. He would stop in the bed of that watercourse on the left side of the road as you traveled to Makkah, and there was only about a stone’s throw between the stopping place of the Messenger of Allah ﷺ and the road.","And Abdullah ibn Umar told him that the Prophet ﷺ, used to stop at Dhu Tuwa and remain there overnight until morning, praying Fajr when he arrived at Makkah. The place where the Messenger of Allah ﷺ prayed was on a thick hill, not inside the mosque that was later built there, but lower than that on a thick hill.","And Abdullah ibn Umar told him that the Prophet ﷺ, faced the two mountain passes of the mountain that lay between him and the long mountain in the direction of the Ka’bah. The mosque that was later built stood to the left of that prayer place at the edge of the hill, while the Prophet’s prayer place was below it on the dark hill. You leave about ten cubits or something like that of the hill, then pray facing the two mountain passes of the mountain between you and the Ka’bah."]},"buhuth":{"ar":["معاني الألفاظ الغريبة:","(سمرة) شجرة ذات شوكٍ.","(بطن واد) وادي العقيق.","(بالبطحاء) المسيل الواسع المجتمع فيه صغار الحصى من سيل الماء.","(شفير) طرف.","(فعرَّس ثم) نزل آخر الليل ليستريح ونام هناك.","(الأكمة) الموضع المرتفع عما حوله.","(خليج) وادٍ له عمق.","(كثب) جمع كثيب، وهو رملٌ مجتمع.","(فدحا السيل) دفع فيه من الدحو، وهو البسط.","(العرق) الجبل الصغير أو اسم لوادٍ معروفٍ بعرق الظبية.","(منصرف الروحاء) آخرها.","(السحر) وقت ما بين الفجر الكاذب والفجر الصادق.","(سرحة) شجرة.","(الرويثة) قرية على طريق مكة من المدينة.","(وجاه الطريق) مقابلها.","(بطح) واسع.","(دوين الرويثة) تصغير دون، تحتها أو قريبٌ منها.","(تلعة) أرض مرتفعة عريضة يتردد فيها السيل، والتلعة أيضًا مجرى السيل من أعلى الوادي وما انهبط من الأرض.","(العرج) قرية على الطريق بين مكة والمدينة.","(هضبة) فوق الكثيب في الارتفاع دون الجبل.","(رضم) صخور بعضها فوق بعض.","(سلمات) صخرات، وبفتح اللام: شجرات يدبغ بورقها الجلد.","(هرشى) جبل على ملتقى طريق المدينة والشام، قريب من الجحفة، وهي اليوم رابغ.","(بكراع) بطرف.","(غلوة) غاية بلوغ السهم.","(مرّ الظهران) وادٍ تسميه العامة بطن مرّ، قريب من عرفة.","(الصَّفراوات) جمع صفراء، وهي الأودية أو الجبال التي بعد مرّ الظهران.","(بذي طوى) اسم موضع بمكة.","(فَرْضَتَي) مثنى فرضة، وهي مدخل الطريق إلى الجبل."],"en":["Meanings of uncommon terms:","“Samurah”: a thorny tree.","“Bottom of a valley”: the valley of al-Aqiq.","“Al-batha”: a broad watercourse where small pebbles gather from the flow of water.","“Shafir”: edge.","“Fa’arrasa thamma”: he stopped at the end of the night to rest and slept there.","“Akamah”: an elevated piece of land higher than what surrounds it.","“Khalij”: a channel or valley with depth.","“Kuthub”: plural of kathib, meaning gathered sand or a sand mound.","“Fa datha al-sayl”: the flood spread over it and pushed through it.","“Al-irq”: a small mountain, or the name of a known valley called Irq al-Zabyah.","“The departure point of al-Rawha”: its far end.","“Al-sahar”: the time between the false dawn and the true dawn.","“Sarhah”: a tree.","“Al-Ruwaythah”: a village on the road from Madinah to Makkah.","“Facing the road”: directly opposite it.","“Bathah”: broad and open.","“Duwayn al-Ruwaythah”: slightly below it or near it.","“Tal’ah”: a broad elevated ground through which floodwater passes; it can also mean the watercourse descending from the upper part of a valley and the sloping ground.","“Al-Arj”: a village on the road between Makkah and Madinah.","“Hadbah”: a raised mound higher than a sand hill but lower than a mountain.","“Radm”: stones piled on top of one another.","“Salamat”: rocks; with a different pronunciation it can also refer to trees whose leaves are used for tanning leather.","“Harsha”: a mountain at the meeting point of the Madinah and Syria roads, near al-Juhfah, which today is Rabigh.","“Bi-kura’”: at the edge or extremity.","“Ghalwah”: the furthest distance an arrow can reach.","“Marr al-Zahran”: a valley commonly called Batn Marr, near Arafah.","“Al-Safrawat”: plural of Safra; referring to valleys or mountains beyond Marr al-Zahran.","“At Dhu Tuwa”: the name of a place in Makkah.","“Farḍatay”: dual of farḍah, meaning the entryway or pass of the road into the mountain."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":492},{"key":"muslim","label":"مسلم","number":28}]},{"num":4866,"demo":false,"sanad":"","matn":["عن موسى بن عقبة قال: رأيتُ سالم بن عبد الله يتحرّى أماكن من الطريق، فيصلّي فيها، ويُحدِّث أنَّ أباه كان يُصلّي فيها، وأنه رأى النبيَّ ﷺ يُصلّي في تلك الأمكنة، وحدَّثني نافعٌ، عن ابن عمر، أنه كان يُصلّي في تلك الأمكنة، وسألتُ سالمًا فلا أعلمُه إلا وافق نافعًا في الأمكنة كلها إلا أنهما اختلفا في مسجدٍ بشرف الروحاء."],"takhrij":"صحيح: رواه البخاري (٤٨٣).","grade":"صحيح","chapter_ar":"باب نزول النبي ﷺ بذي طوى والمبيت بها حتى يصبح إذا دخل مكة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (483).","chapter_en":"The Prophet ﷺ staying at Dhū Ṭuwā and spending the night there until morning when entering Makkah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Musa ibn Uqbah said: I saw Salim ibn Abdullah carefully seeking out places along the road and praying in them, and he would report that his father used to pray in them, and that he had seen the Prophet ﷺ, praying in those places. Nafi also told me, from Ibn Umar, that he used to pray in those places. I asked Salim, and I do not know of him differing from Nafi regarding any of those places except that they differed about a mosque at the high ground of al-Rawha."]},"buhuth":{"ar":["قوله: اختلفا في مسجدٍ بشرف الروحاء، أي: اختلف سالم مع نافع في تعيين موضع مسجدٍ بشرف الروحاء، والروحاء من الفرع، بينهما وبين المدينة مرحلتان، وفي صحيح مسلم عقب الحديث (٣٨٨): هي من المدينة ستة وثلاثون ميلًا."],"en":["His statement, “they differed about a mosque at the high ground of al-Rawha,” means that Salim and Nafi differed in identifying the exact location of the mosque at the high ground of al-Rawha. Al-Rawha is part of al-Far’, and between it and Madinah are two travel stages. In Sahih Muslim after the hadith (388), it states that it is thirty-six miles from Madinah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":483}]},{"num":4867,"demo":false,"sanad":"","matn":["عن نافع، قال: كان ابنُ عمر إذا دخل أدنى الحرم أمسك عن التلبية، ثم يبيت بذي طُوى، ثم يُصلّي به الصبح، ويغتسل، ويُحدِّث أنَّ نبيَّ الله ﷺ كان يفعل ذلك."],"takhrij":"متفق عليه: رواه البخاري (١٥٧٣)، ومسلم (١٢٥٩). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الاغتسال ودخول مكة بالنهار","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1573) and Muslim (1259). The wording is that of al-Bukhari.","chapter_en":"Bathing and entering Makkah during the daytime","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Nafi said: When Ibn Umar entered the nearest boundary of the Sacred Precinct, he would stop reciting the talbiyah. Then he would spend the night at Dhu Tuwa, pray Fajr there, bathe, and narrate that the Prophet of Allah ﷺ used to do that."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1573},{"key":"muslim","label":"مسلم","number":1259}]},{"num":4868,"demo":false,"sanad":"","matn":["عن مُحَرِّش الكعبيِّ: أنَّ النبيَّ ﷺ خرج من الجِعرانة ليلًا معتمرًا، فدخل مكة ليلًا، فقضى عمرته، ثم خرج من ليلته فأصبح بالجعرانة كبائتٍ، فلما زالت الشمس من الغد خرج من بطن سَرِفَ حتى جاء مع الطريق طريق جمعٍ ببطن سَرِفَ، فمن أجل ذلك خفيت عمرته على الناس."],"takhrij":"حسن: رواه النسائي (٢٨٦٣)، والترمذي (٩٣٥) وحسّنه، وأحمد (١٥٥١٣).","grade":"حسن","chapter_ar":"باب دخول النبي ﷺ مكة ليلًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (2863), al-Tirmidhi (935), who graded it Hasan, and Ahmad (15513).","chapter_en":"The Prophet ﷺ entering Makkah at night","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Muharrish al-Ka’bi reported that the Prophet ﷺ, left al-Ji’ranah at night to perform Umrah, entered Makkah at night and completed his Umrah, then left that same night and by morning was back at al-Ji’ranah as though he had spent the night there. When the sun passed its zenith the next day, he left through the valley of Sarif until he joined the road at Sarif. Because of this, his Umrah was hidden from the people."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2863},{"key":"tirmidhi","label":"الترمذي","number":935},{"key":"ahmad","label":"مسند الإمام أحمد","number":15513,"n":15513}]},{"num":4869,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر: أنَّ رسولَ الله ﷺ كان يخرج من طريق الشجرة ويدخل من طريق المُعَرَّس، وإذا دخل مكة دخل من الثنية العليا، ويخرج من الثنية السفلى."],"takhrij":"متفق عليه: رواه البخاري (١٥٧٦)، ومسلم (١٢٥٧). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب دخول النبي ﷺ مكة من أعلاها، وخروجه من أسفلها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1576) and Muslim (1257). The wording is that of Muslim.","chapter_en":"The Prophet ﷺ entering Makkah from its upper side and leaving from its lower side","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ, used to leave by the route of al-Shajarah and enter by the route of al-Mu’arras. When he entered Makkah, he entered from the upper mountain pass and left from the lower mountain pass."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1576},{"key":"muslim","label":"مسلم","number":1257}]},{"num":4870,"demo":false,"sanad":"","matn":["عن عائشة: أنَّ النبيَّ ﷺ لما جاء إلى مكة دخل من أعلاها، وخرج من أسفلها."],"takhrij":"متفق عليه: رواه البخاري (١٥٧٧)، ومسلم (٢٢٤:١٢٥٨).","grade":"متفق عليه","chapter_ar":"باب دخول النبي ﷺ مكة من أعلاها، وخروجه من أسفلها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1577) and Muslim (1258).","chapter_en":"The Prophet ﷺ entering Makkah from its upper side and leaving from its lower side","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Aishah reported that when the Prophet ﷺ, came to Makkah, he entered from its upper side and left from its lower side."]},"buhuth":{"ar":["ورواه البخاري أيضًا (١٥٧٨)، ومسلم (٢٢٥:١٢٥٨) عن عائشة: أنَّ رسولَ الله ﷺ دخل عام الفتح من كَدَاء، وخرج من كُدًى من أعلى مكة. والسياق للبخاري.","قوله: (كَدَاء) يفتح الكاف والمدّ، هي الثنية التي ينزل منها إلى المعلّى، مقبرة أهل مكة، وهي التي يقال لها الحَجُون.","وقوله: (وخرج من كُدًى) بضم الكاف والقصر، هي عند باب شُبَيْكة، وكان بناء هذا الباب عليها في القرن السابع.","قوله: (( من أعلى مكة )) قال الحافظ في الفتح (٣/٤٣٧): (( الصواب: دخل من كَدَاء من أعلى مكة ))."],"en":["Al-Bukhari (1578) and Muslim (1258) also narrated from Aishah that the Messenger of Allah ﷺ, entered in the year of the Conquest through Kada’ from the upper side of Makkah, and exited through Kuda. The wording here is that of al-Bukhari.","The word “Kada’” is pronounced with an open kaf and a long vowel. It is the mountain pass by which one descends to al-Ma’la, the cemetery of the people of Makkah, and it is what is called al-Hajun.","The phrase “and he exited through Kuda” is pronounced with a dammah on the kaf and a short ending. It is located near Bab Shubaykah, and that gate was built there in the seventh century.","His statement, “from the upper side of Makkah,” al-Hafiz said in Fath al-Bari (3/437): “The correct wording is: he entered through Kada’ from the upper side of Makkah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1577},{"key":"muslim","label":"مسلم","number":224}]},{"num":4871,"demo":false,"sanad":"","matn":["عن عبد الله مولى أسماء بنت أبي بكر حدَّثه؛ أنه كان يسمع أسماء تقول كلما مرّت بالحَجُونِ: صلّى الله على رسولِه محمدٍ، لقد نزلنا معه هاهنا، ونحن يومئذٍ خفافُ الحقائب، قليلُ ظهرنا، قليلةٌ أزوادُنا، فاعتمرتُ أنا وأختي عائشةُ والزبيرُ وفلانٌ وفلانٌ، فلمّا مسحنا البيت أحللنا، ثم أهللنا من العشيِّ بالحجِّ."],"takhrij":"متفق عليه: رواه البخاري (١٧٩٦)، ومسلم (١٢٣٧). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب مكان نزول النبي ﷺ بمكة في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1796) and Muslim (1237). The wording is that of Muslim.","chapter_en":"Where the Prophet ﷺ stayed in Makkah during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Abdullah, the freed servant of Asma bint Abi Bakr, narrated that he used to hear Asma say whenever she passed by al-Hajun: May Allah send blessings upon His Messenger Muhammad. We truly stayed here with him, and at that time our loads were light, our riding animals were few, and our provisions were limited. I performed Umrah, as did my sister Aishah, al-Zubayr, and so-and-so and so-and-so. Then when we had completed the circumambulation of the House, we came out of ihram, and later in the evening we entered ihram again for Hajj."]},"buhuth":{"ar":["قولها: (( الحجون )) بحاءٍ مهملةٍ مفتوحة، بعدها جيمٌ مضمومة: ثنيةٌ بأعلى مكة، وهي لا تزال معروفةً بهذا الاسم، إلا أن العامة ينطقونها “الحُجُون” بضم المهملة، وبها مقبرة أهل مكة التي تسمى مقبرة المعلّى."],"en":["Her statement, “al-Hajun,” with an open ha and a joined jim, refers to a mountain pass at the upper side of Makkah. It is still known by this name, though common people pronounce it “al-Hujun.” It contains the cemetery of the people of Makkah, known as the cemetery of al-Ma’la."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1796},{"key":"muslim","label":"مسلم","number":1237}]},{"num":4872,"demo":false,"sanad":"","matn":["عن عائشة قالت: نزولُ الأبطح ليس بسنة، إنما نزله رسولُ الله ﷺ لأنه كان أسمح لخروجه إذا خرج."],"takhrij":"متفق عليه: رواه البخاري (١٧٦٥)، ومسلم (١٣١١). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب مكان نزول النبي ﷺ بمكة في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1765) and Muslim (1311). The wording is that of Muslim.","chapter_en":"Where the Prophet ﷺ stayed in Makkah during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Aishah said: Stopping at al-Abtah is not a Sunnah. The Messenger of Allah ﷺ, only stopped there because it made his departure easier when he left."]},"buhuth":{"ar":["قوله: (( الأبطح )) أي البطحاء التي بين مكة ومنى، وهي ما انبطح من الوادي واتسع، وهي التي يقال لها: المُحَصَّب، والمُعَرَّس، وحدُّها ما بين الجبلين إلى المقبرة. والمحصَّب، والأبطح، وخيف بني كنانة اسمٌ لشيءٍ واحد."],"en":["The word “al-Abtah” means the broad valley floor between Makkah and Mina, the open flat part of the valley. It is also called al-Muhassab and al-Mu’arras, and its boundary stretches from between the two mountains to the cemetery. Al-Muhassab, al-Abtah, and Khayf Bani Kinanah are all names for the same place."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1765},{"key":"muslim","label":"مسلم","number":1311}]},{"num":4873,"demo":false,"sanad":"","matn":["عن ابن عباس قال: ليس التَّحصيبُ بشيء، إنما هو منزلٌ نزله رسولُ الله ﷺ."],"takhrij":"متفق عليه: رواه البخاري (١٧٦٦)، ومسلم (١٣١٢).","grade":"متفق عليه","chapter_ar":"باب مكان نزول النبي ﷺ بمكة في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1766) and Muslim (1312).","chapter_en":"Where the Prophet ﷺ stayed in Makkah during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Ibn Abbas said: Staying at al-Muhassab is not a prescribed rite in itself. It was only a place where the Messenger of Allah ﷺ, stayed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1766},{"key":"muslim","label":"مسلم","number":1312}]},{"num":4874,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: فقدم مكة لأربع ليالٍ خَلَوْن من ذي الحجة، فطاف بالبيت وسعى بين الصفا والمروة، ولم يحلَّ من أجل بُدْنِه؛ لأنه قلّدها، ثم نزل بأعلى مكة عند الحَجُونِ وهو مُهِلٌّ بالحجِّ … الحديث."],"takhrij":"صحيح: رواه البخاري (١٥٤٥).","grade":"صحيح","chapter_ar":"باب مكان نزول النبي ﷺ بمكة في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1545).","chapter_en":"Where the Prophet ﷺ stayed in Makkah during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Abdullah ibn Abbas said: He arrived in Makkah after four nights of Dhu al-Hijjah had passed. He circumambulated the House and went between al-Safa and al-Marwah, but he did not come out of ihram because of his sacrificial animals, for he had garlanded them. Then he stayed at the upper side of Makkah near al-Hajun while still in ihram for Hajj … the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1545}]},{"num":4875,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال لنا رسولُ الله ﷺ - ونحن بمنى -: (( نحن نازلون غدًا بخيف بني كنانة، حيث تقاسموا على الكفر - وذلك أن قريشًا وبني كنانة تحالفت على بني هاشم وبني عبد المطلب - أو بني المطلب - ألا يُناكحوهم ولا يُبايعوهم حتى يُسلموا إليهم رسولَ الله ﷺ )) - يعني بذلك المُحَصَّبَ."],"takhrij":"متفق عليه: رواه البخاري (١٥٩٠)، ومسلم (٣٤٤:١٣١٤). واللفظ لمسلم، ولفظ البخاري نحوه، وزاد في أوله: (( قال النبي ﷺ من الغد يوم النحر وهو بمنى… )) إلخ. وفي رواية للبخاري (٤٢٨٤)، ومسلم: (( منزلنا إن شاء الله، إذا فتح الله، الخيف، حيث تقاسموا على الكفر )).","grade":"متفق عليه","chapter_ar":"باب مكان نزول النبي ﷺ بمكة في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1590) and Muslim (1314). The wording is that of Muslim. Al-Bukhari has a similar version and adds at its beginning: “The Prophet ﷺ said on the next day, the Day of Sacrifice, while he was in Mina…” and so on. In another narration in al-Bukhari (4284) and Muslim: “Our stopping place, if Allah wills and grants victory, will be at the khayf, where they pledged themselves to disbelief.”","chapter_en":"Where the Prophet ﷺ stayed in Makkah during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, said to us while we were in Mina: “Tomorrow we will stop at Khayf Bani Kinanah, where they pledged themselves to disbelief.” This refers to the alliance of Quraysh and Banu Kinanah against Banu Hashim and Banu Abd al-Muttalib, or Banu al-Muttalib, that they would neither marry them nor trade with them until they handed over the Messenger of Allah ﷺ. He meant by that al-Muhassab."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1590},{"key":"muslim","label":"مسلم","number":344},{"key":"الخ_وفی_روایہ_للبخاری","label":"إلخ. وفي رواية للبخاري","number":4284}]},{"num":4876,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر: أنَّ النبيَّ ﷺ وأبا بكرٍ وعمرَ كانوا ينزلون الأبطح."],"takhrij":"متفق عليه: رواه مسلم (٣٣٧:١٣١٠)، والبخاري (١٧٦٨).","grade":"متفق عليه","chapter_ar":"باب مكان نزول النبي ﷺ بمكة في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1310) and al-Bukhari (1768).","chapter_en":"Where the Prophet ﷺ stayed in Makkah during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Prophet ﷺ, along with Abu Bakr and Umar, used to stop at al-Abtah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":337},{"key":"bukhari","label":"البخاري","number":1768}]},{"num":4877,"demo":false,"sanad":"","matn":["عن أبي رافع، قال: لم يأمرني رسولُ الله ﷺ أن أنزل الأبطح حين خرج من منى، ولكنِّي جئتُ فضربتُ فيه قبته، فجاء فنزل."],"takhrij":"صحيح: رواه مسلم (١٣١٣). وزاد في رواية: (( عن أبي رافع، وكان على ثقل النبيِّ ﷺ )).","grade":"صحيح","chapter_ar":"باب مكان نزول النبي ﷺ بمكة في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1313). Another narration adds: “from Abu Rafi, who was in charge of the baggage of the Prophet ﷺ.”","chapter_en":"Where the Prophet ﷺ stayed in Makkah during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب في خروج النبي ﷺ من المدينة إلى مكة لأداء فريضة الحج","group_en":"Combined chapters on the departure of the Prophet ﷺ, from Madinah to Makkah to perform the obligatory Hajj","part_no":16,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Abu Rafi said: The Messenger of Allah ﷺ, did not command me to camp at al-Abtah when he left Mina, but I came and pitched his tent there, and then he came and stayed there."]},"buhuth":{"ar":["والثِّقَل: العيال، وما يثقل حملُه من الأمتعة."],"en":["“Al-thiql” refers to one’s dependents and heavy belongings and baggage that are carried."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1313}]},{"num":4878,"demo":false,"sanad":"","matn":["عن حاتم بن إسماعيل المدني، عن جعفر بن محمد، عن أبيه، قال: دَخَلْنَا عَلَى جَابِرِ بْنِ عَبْدِ الله، فَسَأَلَ عَنِ الْقَوْمِ حَتَّى انْتَهَى إِلَيَّ، فَقُلْتُ: أَنَا مُحَمَّدُ بْنُ عَلِيِّ بْنِ حُسَيْنٍ، فَأَهْوَى بِيَدِهِ إِلَى رَأْسِي، فَنَزَعَ زِرِّي الأَعْلَى، ثُمَّ نَزَعَ زِرِّي الأَسْفَلَ، ثُمَّ وَضَعَ كَفَّهُ بَيْنَ ثَدْيَيَّ، وَأَنَا يَوْمَئِذٍ غُلَامٌ شَابٌّ، فَقَالَ: مَرْحَبًا بِكَ يَا ابْنَ أَخِي، سَلْ عَمَّا شِئْتَ. فَسَأَلْتُهُ وَهُوَ أَعْمَى، وَحَضَرَ وَقْتُ الصَّلَاةِ، فَقَامَ فِي نِسَاجَةٍ مُلْتَحِفًا بِهَا، كُلَّمَا وَضَعَهَا عَلَى مَنْكِبَيْهِ رَجَعَ طَرَفَاهَا إِلَيْهِ مِنْ صِغَرِهَا، وَرِدَاؤُهُ إِلَى جَنْبِهِ عَلَى الْمِشْجَبِ، فَصَلَّى بِنَا، فَقُلْتُ: أَخْبِرْنِي عَنْ حَجَّةِ رَسُولِ الله ﷺ. فَقَالَ بِيَدِهِ فَعَقَدَ تِسْعًا، فَقَالَ: إِنَّ رَسُولَ الله ﷺ مَكَثَ تِسْعَ سِنِينَ لَمْ يَحُجَّ، ثُمَّ أَذَّنَ فِي النَّاسِ فِي الْعَاشِرَةِ أَنَّ رَسُولَ الله ﷺ حَاجٌّ، فَقَدِمَ الْمَدِينَةَ بَشَرٌ كَثِيرٌ، كُلُّهُمْ يَلْتَمِسُ أَنْ يَأْتَمَّ بِرَسُولِ الله ﷺ وَيَعْمَلَ مِثْلَ عَمَلِهِ، فَخَرَجْنَا مَعَهُ حَتَّى أَتَيْنَا ذَا الْحُلَيْفَةِ، فَوَلَدَتْ أَسْمَاءُ بِنْتُ عُمَيْسٍ مُحَمَّدَ بْنَ أَبِي بَكْرٍ، فَأَرْسَلَتْ إِلَى رَسُولِ الله ﷺ: كَيْفَ أَصْنَعُ؟ قَالَ: (( اغْتَسِلِي، وَاسْتَثْفِرِي بِثَوْبٍ، وَأَحْرِمِي )). فَصَلَّى رَسُولُ الله ﷺ فِي الْمَسْجِدِ، ثُمَّ رَكِبَ الْقَصْوَاءَ، حَتَّى إِذَا اسْتَوَتْ بِهِ نَاقَتُهُ عَلَى الْبَيْدَاءِ، نَظَرْتُ إِلَى مَدَّ بَصَرِي بَيْنَ يَدَيْهِ مِنْ رَاكِبٍ وَمَاشٍ، وَعَنْ يَمِينِهِ مِثْلَ ذَلِكَ، وَعَنْ يَسَارِهِ مِثْلَ ذَلِكَ، وَمِنْ خَلْفِهِ مِثْلَ ذَلِكَ، وَرَسُولُ الله ﷺ بَيْنَ أَظْهُرِنَا، وَعَلَيْهِ يَنْزِلُ الْقُرْآنُ، وَهُوَ يَعْرِفُ تَأْوِيلَهُ، وَمَا عَمِلَ بِهِ مِنْ شَيْءٍ عَمِلْنَا بِهِ، فَأَهَلَّ بِالتَّوْحِيدِ: (( لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لا شَرِيكَ لَكَ )). وَأَهَلَّ النَّاسُ بِهَذَا الَّذِي يُهِلُّونَ بِهِ، فَلَمْ يَرُدَّ رَسُولُ الله ﷺ عَلَيْهِمْ شَيْئًا مِنْهُ، وَلَزِمَ رَسُولُ الله ﷺ تَلْبِيَتَهُ.","قَالَ جَابِرٌ رضي الله عنه: لَسْنَا نَنْوِي إِلَّا الْحَجَّ، لَسْنَا نَعْرِفُ الْعُمْرَةَ، حَتَّى إِذَا أَتَيْنَا الْبَيْتَ مَعَهُ اسْتَلَمَ الرُّكْنَ، فَرَمَلَ ثَلَاثًا وَمَشَى أَرْبَعًا، ثُمَّ نَفَذَ إِلَى مَقَامِ إِبْرَاهِيمَ عليه السلام، فَقَرَأَ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى} [البقرة: ١٢٥]، فَجَعَلَ الْمَقَامَ بَيْنَهُ وَبَيْنَ الْبَيْتِ، فَكَانَ أَبِي يَقُولُ - وَلا أَعْلَمُهُ ذَكَرَهُ إِلَّا عَنِ النَّبِيِّ ﷺ -: كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ: {قُلْ هُوَ اللَّهُ أَحَدٌ} و{قُلْ يَا أَيُّهَا الْكَافِرُونَ}. ثُمَّ رَجَعَ إِلَى الرُّكْنِ فَاسْتَلَمَهُ، ثُمَّ خَرَجَ مِنَ الْبَابِ إِلَى الصَّفَا، فَلَمَّا دَنَا مِنَ الصَّفَا قَرَأَ: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ} [البقرة: ١٥٨]، (( أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ )). فَبَدَأَ بِالصَّفَا، فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَوَحَّدَ اللَّهَ وَكَبَّرَهُ، وَقَالَ: (( لا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الأَحْزَابَ وَحْدَهُ )). ثُمَّ دَعَا بَيْنَ ذَلِكَ، قَالَ مِثْلَ هَذَا ثَلَاثَ مَرَّاتٍ، ثُمَّ نَزَلَ إِلَى الْمَرْوَةِ، حَتَّى إِذَا انْصَبَّتْ قَدَمَاهُ فِي بَطْنِ الْوَادِي سَعَى، حَتَّى إِذَا صَعِدَتَا مَشَى، حَتَّى أَتَى الْمَرْوَةَ، فَفَعَلَ عَلَى الْمَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا، حَتَّى إِذَا كَانَ آخِرُ طَوَافِهِ عَلَى الْمَرْوَةِ قَالَ: (( لَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ لَمْ أَسُقِ الْهَدْيَ، وَجَعَلْتُهَا عُمْرَةً، فَمَنْ كَانَ مِنْكُمْ لَيْسَ مَعَهُ هَدْيٌ فَلْيَحِلَّ، وَلْيَجْعَلْهَا عُمْرَةً )). فَقَامَ سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ فَقَالَ: يَا رَسُولَ الله، أَلِعَامِنَا هَذَا أَمْ لِأَبَدٍ؟ فَشَبَّكَ رَسُولُ الله ﷺ أَصَابِعَهُ وَاحِدَةً فِي الأُخْرَى، وَقَالَ: (( دَخَلَتِ الْعُمْرَةُ فِي الْحَجِّ )) مَرَّتَيْنِ، (( لا، بَلْ لِأَبَدِ أَبَدٍ )).","وَقَدِمَ عَلِيٌّ مِنَ الْيَمَنِ بِبُدْنِ النَّبِيِّ ﷺ، فَوَجَدَ فَاطِمَةَ رضي الله عنها مِمَّنْ حَلَّ، وَلَبِسَتْ ثِيَابًا صَبِيغًا، وَاكْتَحَلَتْ، فَأَنْكَرَ ذَلِكَ عَلَيْهَا، فَقَالَتْ: إِنَّ أَبِي أَمَرَنِي بِهَذَا. قَالَ: فَكَانَ عَلِيٌّ رضي الله عنه يَقُولُ بِالْعِرَاقِ: فَذَهَبْتُ إِلَى رَسُولِ الله ﷺ مُحَرِّشًا عَلَى فَاطِمَةَ لِلَّذِي صَنَعَتْ، مُسْتَفْتِيًا لِرَسُولِ الله ﷺ فِيمَا ذَكَرَتْ عَنْهُ، فَأَخْبَرْتُهُ أَنِّي أَنْكَرْتُ ذَلِكَ عَلَيْهَا، فَقَالَ: (( صَدَقَتْ، صَدَقَتْ، مَاذَا قُلْتَ حِينَ فَرَضْتَ الْحَجَّ؟ )) قَالَ: قُلْتُ: اللَّهُمَّ إِنِّي أُهِلُّ بِمَا أَهَلَّ بِهِ رَسُولُكَ. قَالَ: (( فَإِنَّ مَعِيَ الْهَدْيَ، فَلَا تَحِلُّ )). قَالَ: فَكَانَ جِمَاعَةُ الْهَدْيِ الَّذِي قَدِمَ بِهِ عَلِيٌّ مِنَ الْيَمَنِ، وَالَّذِي أَتَى بِهِ النَّبِيُّ ﷺ مِائَةً. قَالَ: فَحَلَّ النَّاسُ كُلُّهُمْ وَقَصَّرُوا إِلَّا النَّبِيَّ ﷺ وَمَنْ كَانَ مَعَهُ هَدْيٌ. فَلَمَّا كَانَ يَوْمُ التَّرْوِيَةِ تَوَجَّهُوا إِلَى مِنًى، فَأَهَلُّوا بِالْحَجِّ، وَرَكِبَ رَسُولُ الله ﷺ، فَصَلَّى بِهَا الظُّهْرَ، وَالْعَصْرَ، وَالْمَغْرِبَ، وَالْعِشَاءَ، وَالْفَجْرَ، ثُمَّ مَكَثَ قَلِيلًا حَتَّى طَلَعَتِ الشَّمْسُ، وَأَمَرَ بِقُبَّةٍ مِنْ شَعَرٍ تُضْرَبُ لَهُ بِنَمِرَةَ، فَسَارَ رَسُولُ الله ﷺ، وَلَا تَشُكُّ قُرَيْشٌ إِلَّا أَنَّهُ وَاقِفٌ عِنْدَ الْمَشْعَرِ الْحَرَامِ كَمَا كَانَتْ قُرَيْشٌ تَصْنَعُ فِي الْجَاهِلِيَّةِ، فَأَجَازَ رَسُولُ الله ﷺ حَتَّى أَتَى عَرَفَةَ، فَوَجَدَ الْقُبَّةَ قَدْ ضُرِبَتْ لَهُ بِنَمِرَةَ، فَنَزَلَ بِهَا، حَتَّى إِذَا زَاغَتِ الشَّمْسُ أَمَرَ بِالْقَصْوَاءِ، فَرُحِلَتْ لَهُ، فَأَتَى بَطْنَ الْوَادِي، فَخَطَبَ النَّاسَ، وَقَالَ: (( إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ حَرَامٌ عَلَيْكُمْ، كَحُرْمَةِ يَوْمِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا، أَلَا كُلُّ شَيْءٍ مِنْ أَمْرِ الْجَاهِلِيَّةِ تَحْتَ قَدَمَيَّ مَوْضُوعٌ، وَدِمَاءُ الْجَاهِلِيَّةِ مَوْضُوعَةٌ، وَإِنَّ أَوَّلَ دَمٍ أَضَعُ مِنْ دِمَائِنَا دَمُ ابْنِ رَبِيعَةَ بْنِ الْحَارِثِ - كَانَ مُسْتَرْضَعًا فِي بَنِي سَعْدٍ فَقَتَلَتْهُ هُذَيْلٌ - وَرِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ، وَأَوَّلُ رِبًا أَضَعُ رِبَانَا، رِبَا عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، فَإِنَّهُ مَوْضُوعٌ كُلُّهُ، فَاتَّقُوا اللَّهَ فِي النِّسَاءِ، فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانِ اللَّهِ، وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ، وَلَكُمْ عَلَيْهِنَّ أَنْ لا يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ، فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ، وَلَهُنَّ عَلَيْكُمْ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ، وَقَدْ تَرَكْتُ فِيكُمْ مَا لَنْ تَضِلُّوا بَعْدَهُ إِنِ اعْتَصَمْتُمْ بِهِ: كِتَابَ اللَّهِ، وَأَنْتُمْ تُسْأَلُونَ عَنِّي، فَمَا أَنْتُمْ قَائِلُونَ؟ )) قَالُوا: نَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ وَأَدَّيْتَ وَنَصَحْتَ. فَقَالَ بِإِصْبَعِهِ السَّبَّابَةِ يَرْفَعُهَا إِلَى السَّمَاءِ وَيَنْكُتُهَا إِلَى النَّاسِ: (( اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ )) ثَلَاثَ مَرَّاتٍ. ثُمَّ أَذَّنَ، ثُمَّ أَقَامَ، فَصَلَّى الظُّهْرَ، ثُمَّ أَقَامَ، فَصَلَّى الْعَصْرَ، وَلَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا، ثُمَّ رَكِبَ رَسُولُ الله ﷺ حَتَّى أَتَى الْمَوْقِفَ، فَجَعَلَ بَطْنَ نَاقَتِهِ الْقَصْوَاءِ إِلَى الصَّخَرَاتِ، وَجَعَلَ حَبْلَ الْمُشَاةِ بَيْنَ يَدَيْهِ، وَاسْتَقْبَلَ الْقِبْلَةَ، فَلَمْ يَزَلْ وَاقِفًا حَتَّى غَرَبَتِ الشَّمْسُ، وَذَهَبَتِ الصُّفْرَةُ قَلِيلًا حَتَّى غَابَ الْقُرْصُ، وَأَرْدَفَ أُسَامَةَ خَلْفَهُ، وَدَفَعَ رَسُولُ الله ﷺ، وَقَدْ شَنَقَ لِلْقَصْوَاءِ الزِّمَامَ حَتَّى إِنَّ رَأْسَهَا لَيُصِيبُ مَوْرِكَ رَحْلِهِ، وَيَقُولُ بِيَدِهِ الْيُمْنَى: (( أَيُّهَا النَّاسُ، السَّكِينَةَ السَّكِينَةَ )). كُلَّمَا أَتَى حَبْلًا مِنَ الْحِبَالِ أَرْخَى لَهَا قَلِيلًا حَتَّى تَصْعَدَ، حَتَّى أَتَى الْمُزْدَلِفَةَ، فَصَلَّى بِهَا الْمَغْرِبَ وَالْعِشَاءَ بِأَذَانٍ وَاحِدٍ وَإِقَامَتَيْنِ، وَلَمْ يُسَبِّحْ بَيْنَهُمَا شَيْئًا، ثُمَّ اضْطَجَعَ رَسُولُ الله ﷺ حَتَّى طَلَعَ الْفَجْرُ، وَصَلَّى الْفَجْرَ حِينَ تَبَيَّنَ لَهُ الصُّبْحُ بِأَذَانٍ وَإِقَامَةٍ، ثُمَّ رَكِبَ الْقَصْوَاءَ، حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَدَعَاهُ، وَكَبَّرَهُ، وَهَلَّلَهُ، وَوَحَّدَهُ، فَلَمْ يَزَلْ وَاقِفًا حَتَّى أَسْفَرَ جِدًّا، فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ، وَأَرْدَفَ الْفَضْلَ بْنَ عَبَّاسٍ، وَكَانَ رَجُلًا حَسَنَ الشَّعْرِ، أَبْيَضَ وَسِيمًا، فَلَمَّا دَفَعَ رَسُولُ الله ﷺ مَرَّتْ بِهِ ظُعُنٌ يَجْرِينَ، فَطَفِقَ الْفَضْلُ يَنْظُرُ إِلَيْهِنَّ، فَوَضَعَ رَسُولُ الله ﷺ يَدَهُ عَلَى وَجْهِ الْفَضْلِ، فَحَوَّلَ الْفَضْلُ وَجْهَهُ إِلَى الشِّقِّ الْآخَرِ يَنْظُرُ، فَحَوَّلَ رَسُولُ الله ﷺ يَدَهُ مِنَ الشِّقِّ الْآخَرِ عَلَى وَجْهِ الْفَضْلِ، يَصْرِفُ وَجْهَهُ مِنَ الشِّقِّ الْآخَرِ يَنْظُرُ، حَتَّى أَتَى بَطْنَ مُحَسِّرٍ، فَحَرَّكَ قَلِيلًا، ثُمَّ سَلَكَ الطَّرِيقَ الْوُسْطَى الَّتِي تَخْرُجُ عَلَى الْجَمْرَةِ الْكُبْرَى، حَتَّى أَتَى الْجَمْرَةَ الَّتِي عِنْدَ الشَّجَرَةِ، فَرَمَاهَا بِسَبْعِ حَصَيَاتٍ، يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ مِنْهَا، مِثْلِ حَصَى الْخَذْفِ، رَمَى مِنْ بَطْنِ الْوَادِي، ثُمَّ انْصَرَفَ إِلَى الْمَنْحَرِ، فَنَحَرَ ثَلَاثًا وَسِتِّينَ بِيَدِهِ، ثُمَّ أَعْطَى عَلِيًّا فَنَحَرَ مَا غَبَرَ، وَأَشْرَكَهُ فِي هَدْيِهِ، ثُمَّ أَمَرَ مِنْ كُلِّ بَدَنَةٍ بِبَضْعَةٍ، فَجُعِلَتْ فِي قِدْرٍ، فَطُبِخَتْ، فَأَكَلَا مِنْ لَحْمِهَا، وَشَرِبَا مِنْ مَرَقِهَا، ثُمَّ رَكِبَ رَسُولُ الله ﷺ فَأَفَاضَ إِلَى الْبَيْتِ، فَصَلَّى بِمَكَّةَ الظُّهْرَ، فَأَتَى بَنِي عَبْدِ الْمُطَّلِبِ يَسْقُونَ عَلَى زَمْزَمَ، فَقَالَ: (( انْزِعُوا بَنِي عَبْدِ الْمُطَّلِبِ، فَلَوْلا أَنْ يَغْلِبَكُمُ النَّاسُ عَلَى سِقَايَتِكُمْ لَنَزَعْتُ مَعَكُمْ )). فَنَاوَلُوهُ دَلْوًا، فَشَرِبَ مِنْهُ."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب صفة حجّة النبي ﷺ كما رواها جابر بن عبد الله","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The description of the Prophet’s Hajj as narrated by Jābir ibn ʿAbd Allāh","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Hatim ibn Ismaʿil al-Madani narrated from Jaʿfar ibn Muhammad, from his father, who said: We entered upon Jābir ibn ʿAbd Allāh, and he asked about the people until he came to me. I said, “I am Muhammad ibn ʿAli ibn Husayn.” He reached his hand toward my head, undid my upper button, then my lower button, then placed his palm between my chest, and I was a young boy at that time. He said, “Welcome, my nephew. Ask whatever you wish.” So I asked him while he was blind. When the prayer time came, he stood wrapped in a woven garment; whenever he placed it over his shoulders, its ends slipped back because it was small, and his cloak was hanging to the side on a clothes rack. He led us in prayer. Then I said, “Tell me about the Hajj of the Messenger of Allah ﷺ.”","He counted nine with his hand and said: The Messenger of Allah ﷺ remained for nine years without performing Hajj. Then in the tenth year it was announced to the people that the Messenger of Allah ﷺ was going to perform Hajj. So a great number of people came to Madinah, all seeking to follow the Messenger of Allah ﷺ and do as he did. We set out with him until we came to Dhul-Hulayfah. There Asmāʾ bint ʿUmays gave birth to Muhammad ibn Abi Bakr, so she sent word to the Messenger of Allah ﷺ asking, “What should I do?” He said, “Wash yourself, bind yourself with a cloth, and enter into consecration.”","The Messenger of Allah ﷺ prayed in the mosque, then mounted al-Qaswāʾ. When his she-camel stood upright upon al-Baydāʾ, I looked as far as my eye could see: riders and walkers were before him, and likewise on his right, on his left, and behind him. The Messenger of Allah ﷺ was among us, revelation was descending upon him, and he knew its meaning. Whatever he did, we did. He proclaimed the declaration of devotion, saying: “Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Surely all praise, favor, and dominion are Yours. You have no partner.” The people also proclaimed with these words, and the Messenger of Allah ﷺ did not object to any of their words, but he himself adhered to his own formula.","Jābir said: We intended only the pilgrimage; we did not know of combining it with a lesser pilgrimage. When we came to the House with him, he touched the Corner, trotted for three circuits, and walked for four. Then he went to the Station of Abraham and recited: “And take the Station of Abraham as a place of prayer.” He placed the Station between himself and the House. My father used to say, and I only know him to have related it from the Prophet ﷺ, that he recited in the two units: “Say: He is Allah, One,” and “Say: O disbelievers.” Then he returned to the Corner and touched it. Then he went out through the gate to al-Safā. As he approached al-Safā he recited: “Indeed al-Safā and al-Marwah are among the symbols of Allah,” and said, “I begin with what Allah began with.” So he began with al-Safā, climbed it until he saw the House, faced the direction of prayer, declared Allah’s oneness, magnified Him, and said: “There is no god but Allah alone, without partner. To Him belongs the dominion and to Him belongs all praise, and He has power over all things. There is no god but Allah alone. He fulfilled His promise, gave victory to His servant, and defeated the confederates alone.” Then he supplicated between that, repeating this three times. Then he descended toward al-Marwah. When his feet reached the bottom of the valley, he hastened; when he climbed, he walked until he came to al-Marwah, and there he did as he had done on al-Safā.","When he reached the final round on al-Marwah, he said: “If I had known beforehand what I came to know later, I would not have brought sacrificial animals, and I would have made it a lesser pilgrimage. So whoever among you does not have a sacrificial animal with him should come out of consecration and make it a lesser pilgrimage.” Then Surāqah ibn Mālik ibn Juʿshum stood and said, “Messenger of Allah, is this only for this year of ours, or forever?” The Messenger of Allah ﷺ interlaced his fingers and said twice, “The lesser pilgrimage has entered into the pilgrimage.” Then he said, “No, rather forever, forever.”","ʿAli came from Yemen with the sacrificial animals of the Prophet ﷺ and found Fāṭimah among those who had come out of consecration. She was wearing dyed clothes and had applied kohl. He objected to that, and she said, “My father commanded me to do this.” ʿAli later said in Iraq: I went to the Messenger of Allah ﷺ upset with Fāṭimah for what she had done, seeking the ruling from the Messenger of Allah ﷺ regarding what she mentioned from him. I told him that I had objected to her conduct, and he said, “She has spoken the truth, she has spoken the truth. What did you say when you entered into consecration for the pilgrimage?” He said, “I said: O Allah, I enter consecration with that by which Your Messenger entered consecration.” He said, “I have the sacrificial animals with me, so do not come out of consecration.” The total number of sacrificial animals that ʿAli brought from Yemen and that the Prophet ﷺ brought was one hundred.","So all the people came out of consecration and shortened their hair except the Prophet ﷺ and those who had sacrificial animals with them. When the Day of Tarwiyah came, they headed to Mina and entered consecration for the pilgrimage. The Messenger of Allah ﷺ rode and prayed there the noon, afternoon, sunset, night, and dawn prayers. Then he remained a little while until the sun rose. He ordered that a tent of haircloth be pitched for him at Namirah. The Messenger of Allah ﷺ set out, and Quraysh had no doubt that he would stop at the Sacred Monument as they used to do in the time before Islam. But the Messenger of Allah ﷺ passed on until he came to ʿArafah and found the tent pitched for him at Namirah, so he stayed there.","When the sun had passed its zenith, he ordered that al-Qaswāʾ be saddled for him, and he came to the bottom of the valley and addressed the people, saying: “Your blood and your wealth are sacred to you as the sacredness of this day of yours, in this month of yours, in this land of yours. Truly, everything from the practices of the time before Islam is beneath my feet and abolished. The blood claims of the time before Islam are abolished, and the first blood claim I abolish from our blood claims is that of Ibn Rabīʿah ibn al-Harith, who had been nursed among Banū Saʿd and whom Hudhayl killed. The usury of the time before Islam is abolished, and the first usury I abolish is our usury, that of al-ʿAbbās ibn ʿAbd al-Muṭṭalib; all of it is abolished. Fear Allah concerning women, for you have taken them by the trust of Allah and made lawful their private relations by the word of Allah. Your right over them is that they do not admit onto your bedding anyone you dislike. If they do that, then discipline them in a way that is not severe. And their right over you is that you provide for them and clothe them properly. I have left among you that by which you will never go astray if you hold fast to it: the Book of Allah. And you will be asked about me, so what will you say?” They said, “We testify that you conveyed, fulfilled, and sincerely advised.” Then he raised his forefinger toward the sky and pointed it toward the people, saying three times: “O Allah, bear witness, O Allah, bear witness.”","Then Bilāl called the prayer, then he gave the call to commence, and the Prophet ﷺ prayed the noon prayer. Then he gave the call again and prayed the afternoon prayer, without praying anything between them. Then the Messenger of Allah ﷺ rode until he came to the standing place. He made the belly of al-Qaswāʾ face the rocks, with the path of the walkers before him, and faced the direction of prayer. He remained standing until the sun had set, the yellow afterglow had almost disappeared, and the disk had gone down. He seated Usāmah behind him and moved on, having tightened the rein of al-Qaswāʾ until her head almost touched the front of the saddle, saying with his right hand, “People, calmness, calmness.” Whenever he came to a rise among the dunes, he loosened the rein a little so she could climb.","He came to Muzdalifah and prayed the sunset and night prayers there with one call to prayer and two commencements, without any prayer between them. Then the Messenger of Allah ﷺ lay down until dawn. He prayed the dawn prayer when the morning became clear, with a call to prayer and a commencement. Then he mounted al-Qaswāʾ until he came to the Sacred Monument, faced the direction of prayer, supplicated to his Lord, magnified Him, proclaimed His oneness, and continued standing until the daylight had become very bright. Then he departed before the sun rose, seating al-Faḍl ibn ʿAbbās behind him. Al-Faḍl was a handsome, fair, good-looking man. As the Messenger of Allah ﷺ moved on, some women in litters passed by, and al-Faḍl began looking at them. The Messenger of Allah ﷺ placed his hand on al-Faḍl’s face. Al-Faḍl turned his face to the other side to look, and the Messenger of Allah ﷺ moved his hand to that side also, turning al-Faḍl’s face away. Then he came to the valley of Muḥassir and quickened the pace a little. Then he took the middle road that comes out at the major pillar. He came to the pillar near the tree and threw seven pebbles, saying “Allah is greatest” with each pebble. They were like small sling stones, and he threw them from the bottom of the valley.","Then he went to the place of sacrifice and slaughtered sixty-three animals with his own hand. Then he gave the remainder to ʿAli, who slaughtered what was left and shared with him in his sacrificial animals. Then he ordered that a piece from each animal be placed in a pot. It was cooked, and they both ate from its meat and drank from its broth. Then the Messenger of Allah ﷺ rode to the House and prayed the noon prayer in Makkah. Then he came to Banū ʿAbd al-Muṭṭalib, who were drawing water at Zamzam, and said: “Draw water, sons of ʿAbd al-Muṭṭalib. Were it not that people might overwhelm you in your duty of giving drink, I would draw with you.” So they handed him a bucket, and he drank from it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":4879,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: رأيتُ رسولَ اللّٰه ﷺ ركب راحلتَه بذي الحليفة، ثم يُهِلُّ حين تستوي به قائمة."],"takhrij":"متفق عليه: رواه البخاريّ (١٥١٤)، ومسلم (٢٩ :١١٨٧).","grade":"متفق عليه","chapter_ar":"باب ما جاء من أين أهلَّ النبي ﷺ ومتى؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1514) and Muslim (1187/29).","chapter_en":"Reports on from where and when the Prophet ﷺ began his consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar said: I saw the Messenger of Allah ﷺ mount his riding animal at Dhul-Hulayfah, then begin his consecration when it stood upright with him on it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1514},{"key":"muslim","label":"مسلم","number":29}]},{"num":4880,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: بيداؤكم هذه التي تكذبون على رسول اللّٰه ﷺ فيها، ما أهلَّ رسولُ الله ﷺ إلا من عند المسجد، يعني ذا الحليفة.","وفي رواية: كان ابن عمر إذا قيل له: الإحرام من البيداء؟ قال: (( البيداء التي تكذبون فيها على رسول اللّٰه ﷺ، ما أهلَّ رسول اللّٰه ﷺ إلا من عند الشجرة حين قام بعيره ))."],"takhrij":"متفق عليه: رواه مالك (٣٢)، ومسلم (١١٨٦)، والبخاريّ (١٥٤١). والرواية الثانية عند مسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء من أين أهلَّ النبي ﷺ ومتى؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (32), Muslim (1186), and al-Bukhari (1541). The second wording is in Muslim.","chapter_en":"Reports on from where and when the Prophet ﷺ began his consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["ʿAbd Allāh ibn ʿUmar said: This desert plain of yours, about which you falsely attribute things to the Messenger of Allah ﷺ, is not where he began his consecration. The Messenger of Allah ﷺ only began his consecration from near the mosque, meaning Dhul-Hulayfah.","In another narration: When Ibn ʿUmar was asked, “Was the consecration from al-Baydāʾ?” he said: “It is about this al-Baydāʾ that you falsely attribute things to the Messenger of Allah ﷺ. The Messenger of Allah ﷺ only began his consecration from near the tree, when his camel stood up with him.”"]},"buhuth":{"ar":["وقوله: (( تكذبون على رسول اللّٰه )) أي تقولون: إنّه أحرم من البيداء، والصحيح أنه لم يحرم من البيداء، وإنما أحرم قبلها من عند مسجد ذي الحليفة، ومن عند الشجرة التي كانت هناك."],"en":["His statement, “You falsely attribute this to the Messenger of Allah ﷺ,” means: you claim that he entered consecration from al-Baydāʾ, whereas the correct account is that he did not enter consecration from al-Baydāʾ. Rather, he entered consecration before that, from near the mosque of Dhul-Hulayfah and from near the tree that was there."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":32},{"key":"muslim","label":"مسلم","number":1186},{"key":"bukhari","label":"البخاريّ","number":1541}]},{"num":4881,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: صلّى النبيُّ ﷺ بالمدينة أربعًا، وبذي الحليفة ركعتين، ثم بات حتى أصبح بذي الحليفة، فلما ركب راحلته واستوت به أهلَّ."],"takhrij":"صحيح: رواه البخاريّ (١٥٤٦)، ورواه أيضًا (١٥٥١) وفيه: (( حتى استوت به على البيداء حمد الله، وسبّح، وكبّر، ثم أهلَّ بحجّ وعمرة، وأهلَّ الناس بهما )). ورواه مسلم (٦٩٠).","grade":"صحيح","chapter_ar":"باب ما جاء من أين أهلَّ النبي ﷺ ومتى؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1546). He also narrated it in (1551), in which it says: “When it stood upright with him upon al-Baydāʾ, he praised Allah, glorified Him, magnified Him, then began consecration for both pilgrimage and lesser pilgrimage, and the people did the same.” It was also narrated by Muslim (690).","chapter_en":"Reports on from where and when the Prophet ﷺ began his consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ prayed four units in Madinah and two units at Dhul-Hulayfah. Then he stayed the night there until morning. When he mounted his riding animal and it stood upright with him, he began his consecration."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1546},{"key":"ایضا","label":"أيضًا","number":1551},{"key":"ورواہ_مسلم","label":". ورواه مسلم","number":690}]},{"num":4882,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: إنّ إهلال رسول اللّٰه ﷺ من ذي الحليفة حين استوت به راحلته."],"takhrij":"صحيح: رواه البخاريّ (١٥١٥).","grade":"صحيح","chapter_ar":"باب ما جاء من أين أهلَّ النبي ﷺ ومتى؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1515).","chapter_en":"Reports on from where and when the Prophet ﷺ began his consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn ʿAbd Allāh said: The Messenger of Allah ﷺ began his consecration from Dhul-Hulayfah when his riding animal stood upright with him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1515}]},{"num":4883,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: انطلق النبيُّ ﷺ من المدينة بعد ما ترجّل وادّهن ولبس إزاره ورداءه هو وأصحابه، فلم ينهَ عن شيءٍ من الأردية والأزر تُلبس إلا المزعفرة التي تردع على الجلد، فأصبح بذي الحليفة، ركب راحلته حتى استوى على البيداء أهلَّ هو وأصحابه، وقلّد بدنته، وذلك لخمس بقين من ذي القعدة، فقدم مكة لأربع ليال خلون من ذي الحجة، فطاف بالبيت، وسعى بين الصفا والمروة، ولم يحلَّ من أجل بُدْنِه لأنه قلّدها، ثم نزل بأعلى مكة عند الحجون وهو مهلٌّ بالحج، ولم يقرب الكعبة بعد طوافه بها حتى رجع من عرفة، وأمر أصحابه أن يطوفوا بالبيت وبين الصفا والمروة، ثم يُقصروا من رؤوسهم ثم يَحِلّوا، وذلك لمن لم يكن معه بدنة قلّدها، ومن كانت معه امرأته فهي له حلال، والطيب والثياب."],"takhrij":"صحيح: رواه البخاريّ (١٥٤٥).","grade":"صحيح","chapter_ar":"باب ما جاء من أين أهلَّ النبي ﷺ ومتى؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1545).","chapter_en":"Reports on from where and when the Prophet ﷺ began his consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["ʿAbd Allāh ibn ʿAbbās said: The Prophet ﷺ set out from Madinah after combing his hair, applying oil, and putting on his waistcloth and upper cloth, and his companions did likewise. He did not forbid any kind of upper or lower garment except those dyed with safflower that leave color on the skin. He reached Dhul-Hulayfah in the morning, then mounted his riding animal, and when he reached al-Baydāʾ he began consecration, and so did his companions. He also garlanded his sacrificial camel. This was with five nights remaining in Dhu al-Qaʿdah. He arrived in Makkah after four nights of Dhu al-Hijjah had passed. He circumambulated the House and went between al-Safā and al-Marwah, but he did not come out of consecration because of his sacrificial camels, since he had garlanded them. Then he stayed at the upper part of Makkah near al-Hajun while remaining in consecration for the pilgrimage. He did not approach the Kaʿbah again after his circumambulation until he returned from ʿArafah. He ordered his companions to circumambulate the House and go between al-Safā and al-Marwah, then shorten their hair and come out of consecration. This applied to those who did not have a sacrificial animal garlanded with them. Whoever had his wife with him could then be with her lawfully, as well as perfume and clothing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1545}]},{"num":4884,"demo":false,"sanad":"","matn":["عن أنس، قال: صلّى رسولُ اللّٰه ﷺ ونحن معه بالمدينة الظهر أربعًا، والعصر بذي الحليفة ركعتين، ثم بات بها حتى أصبح، ثم ركب حتى استوت به على البيداء، حمد الله وسبّح وكبّر، ثم أهلَّ بحجٍّ وعمرةٍ، وأهلَّ الناس بهما، فلما قدمنا أمر الناس فحلّوا، حتى كان يوم التروية أهلّوا بالحج. قال: ونحر النبي ﷺ بَدَناتٍ بيده قيامًا، وذبح رسول الله ﷺ بالمدينة كبشين أملحين."],"takhrij":"صحيح: رواه البخاريّ (١٥٥١)، ومسلم (٦٩٠) واللفظ للبخاريّ.","grade":"صحيح","chapter_ar":"باب استحباب التحميد والتسبيح والتكبير قبل الإهلال بالحج والعمرة عند الركوب","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1551) and Muslim (690), and this wording is from al-Bukhari.","chapter_en":"The recommendation of praising Allah, glorifying Him, and magnifying Him before beginning consecration for pilgrimage and lesser pilgrimage upon mounting","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ prayed the noon prayer with us in Madinah as four units, and the afternoon prayer at Dhul-Hulayfah as two units. Then he stayed there overnight until morning. Then he mounted, and when his riding animal stood upright with him upon al-Baydāʾ, he praised Allah, glorified Him, magnified Him, and then began consecration for pilgrimage and lesser pilgrimage, and the people did the same. When we arrived, he ordered the people to come out of consecration, until on the Day of Tarwiyah they entered consecration again for the pilgrimage. Anas said: The Prophet ﷺ slaughtered sacrificial camels with his own hand while they were standing, and the Messenger of Allah ﷺ slaughtered two white rams with black markings in Madinah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1551},{"key":"muslim","label":"مسلم","number":690}]},{"num":4885,"demo":false,"sanad":"","matn":["عن نافع، قال: كان ابن عمر رضي اللّٰه عنهما إذا صلّى الغداة بذي الحليفة أمر براحلته فرُحِّلت، ثم ركب، فإذا استوت به استقبل القبلة قائمًا، ثم يُلبّي حتى يبلغ الحرم، ثم يُمسك حتى إذا جاء ذا طُوى بات به حتى يُصبح، فإذا صلّى الغداة اغتسل، وزعم أن رسول اللّٰه ﷺ فعل ذلك."],"takhrij":"صحيح: رواه البخاريّ (١٥٥٣)، ومسلم (٢٨، ٢٧ :١١٨٧). واللفظ للبخاريّ.","grade":"صحيح","chapter_ar":"باب الإهلال بالحج أو العمرة مستقبل القبلة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1553) and Muslim (1187/27–28), and this wording is from al-Bukhari.","chapter_en":"Beginning consecration for pilgrimage or lesser pilgrimage while facing the direction of prayer","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Nāfiʿ said: When Ibn ʿUmar prayed the dawn prayer at Dhul-Hulayfah, he would order his riding animal to be prepared. Then he would mount it, and when it stood upright with him, he would face the direction of prayer while standing and begin the talbiyah until he reached the sacred boundary. Then he would stop until he came to Dhū Ṭuwā, where he would spend the night until morning. After praying dawn, he would wash, and he claimed that the Messenger of Allah ﷺ did this."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1553},{"key":"muslim","label":"مسلم","number":28}]},{"num":4886,"demo":false,"sanad":"","matn":["عن أنس، قال: صلى النبيُّ ﷺ بالمدينة الظّهر أربعاً، والعصر بذي الحليفة ركعتين، وسمعتهم يصرخون بهما جميعاً."],"takhrij":"صحيح: رواه البخاريّ (١٥٤٨)، ومسلم (٦٩٠). واللفظ للبخاريّ.","grade":"صحيح","chapter_ar":"باب رفع الصوت بالإهلال بالحج أو بالعمرة أو بهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1548) and Muslim (690). The wording is that of al-Bukhari.","chapter_en":"Raising the voice in entering into ihram for Hajj, or for Umrah, or for both","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Anas said: The Prophet ﷺ prayed Ẓuhr in Madinah as four rak‘ahs, and ‘Aṣr at Dhul-Hulayfah as two rak‘ahs, and I heard them raising their voices with both Hajj and Umrah together."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1548},{"key":"muslim","label":"مسلم","number":690}]},{"num":4887,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب، قال: سَمِعْتُ النَّبِيَّ ﷺ بِوَادِي الْعَقِيقِ يَقُولُ: (( أَتَانِي اللَّيْلَةَ آتٍ مِنْ رَبِّي، فَقَالَ: صَلِّ فِي هَذَا الْوَادِي الْمُبَارَكِ، وَقُلْ: عُمْرَةٌ فِي حَجَّةٍ ))."],"takhrij":"صحيح: رواه البخاريّ (١٥٣٤).","grade":"صحيح","chapter_ar":"باب صلاة النبي ﷺ في ذي الحليفة بوادي العقيق عند الذهاب إلى الحجّ أو العمرة والرجوع منهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1534).","chapter_en":"The prayer of the Prophet ﷺ at Dhul-Hulayfah in Wadi al-‘Aqiq when going for Hajj or Umrah and when returning from them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["‘Umar ibn al-Khattab said: I heard the Prophet ﷺ in Wadi al-‘Aqiq saying: “Tonight a visitor from my Lord came to me and said: Pray in this blessed valley and say: ‘Umrah within Hajj.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1534}]},{"num":4888,"demo":false,"sanad":"","matn":["عن ابن عمر: أَنَّ رَسُولَ اللَّهِ ﷺ أَنَاخَ بِالْبَطْحَاءِ الَّتِي بِذِي الْحُلَيْفَةِ فَصَلَّى بِهَا. قَالَ نَافِعٌ: وكان عبد الله بن عمر يفعل ذلك."],"takhrij":"متفق عليه: رواه مالك (٢٠٦)، والبخاريّ (١٥٣٢)، ومسلم (٤٣٠ : ١٢٥٧).","grade":"متفق عليه","chapter_ar":"باب صلاة النبي ﷺ في ذي الحليفة بوادي العقيق عند الذهاب إلى الحجّ أو العمرة والرجوع منهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (206), al-Bukhari (1532), and Muslim (1257/430).","chapter_en":"The prayer of the Prophet ﷺ at Dhul-Hulayfah in Wadi al-‘Aqiq when going for Hajj or Umrah and when returning from them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ halted at the gravel plain that is at Dhul-Hulayfah and prayed there. Nafi‘ said: And ‘Abdullah ibn ‘Umar used to do that."]},"buhuth":{"ar":["ورواه البخاريّ أيضاً (١٥٣٣) وفيه: أنّ رسول اللّٰه ﷺ كان يخرج من طريق الشجرة، ويدخل من طريق المعرَّس، وأنّ رسول اللّٰه ﷺ كان إذا خرج إلى مكة يصلي في مسجد الشجرة، وإذا رجع صلى بذي الحليفة ببطن الوادي، وبات حتى يصبح."],"en":["Al-Bukhari also narrated it (1533), and in it is: that the Messenger of Allah ﷺ used to depart by the route of al-Shajarah and return by the route of al-Mu‘arras; and that when he went out to Makkah he prayed in the Mosque of al-Shajarah, and when he returned he prayed at Dhul-Hulayfah in the bottom of the valley and stayed there overnight until morning."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":206},{"key":"bukhari","label":"البخاريّ","number":1532},{"key":"muslim","label":"مسلم","number":430}]},{"num":4889,"demo":false,"sanad":"","matn":["عن ابن عمر: أَنَّ تَلْبِيَةَ رَسُولِ اللَّهِ ﷺ: (( لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لا شَرِيكَ لَكَ )). قَالَ: وَكَانَ عبد الله بن عمر يزيد فيها: لَبَّيْكَ لَبَّيْكَ، لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ بِيَدَيْكَ، لَبَّيْكَ وَالرَّغْبَاءُ إِلَيْكَ وَالْعَمَلُ."],"takhrij":"متفق عليه: رواه مالك (٢٨)، والبخاري (١٥٤٩)، ومسلم (١٩ : ١١٨٤).","grade":"متفق عليه","chapter_ar":"باب في صيغة تلبية رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (28), al-Bukhari (1549), and Muslim (1184/19).","chapter_en":"Concerning the wording of the talbiyah of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Umar reported that the talbiyah of the Messenger of Allah ﷺ was: “Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Truly all praise, favor, and dominion belong to You. You have no partner.” He said: And ‘Abdullah ibn ‘Umar used to add to it: “Here I am, here I am. Here I am and at Your service. All good is in Your hands. Here I am, and all longing and deeds are directed to You.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":28},{"key":"bukhari","label":"البخاري","number":1549},{"key":"muslim","label":"مسلم","number":19}]},{"num":4890,"demo":false,"sanad":"","matn":["عن عائشة، قالت: إنّي لأعلمُ كيف كان النبيُّ ﷺ يُلبِّي: (( لبيك اللهمَّ لبيك، لبيك لا شريك لك لبيك، إنَّ الحمد والنّعمة لك ))."],"takhrij":"صحيح: رواه البخاري (١٥٥٠).","grade":"صحيح","chapter_ar":"باب في صيغة تلبية رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (1550).","chapter_en":"Concerning the wording of the talbiyah of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah said: I certainly know how the Prophet ﷺ used to recite the talbiyah: “Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Truly all praise and favor are Yours.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1550}]},{"num":4891,"demo":false,"sanad":"","matn":["عن جابر، قال: فَأَهَلَّ بِالتَّوْحِيدِ: (( لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لا شَرِيكَ لَكَ ))."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب في صيغة تلبية رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1218).","chapter_en":"Concerning the wording of the talbiyah of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Jabir said: So he began the talbiyah with pure monotheism: “Here I am, O Allah, here I am. Here I am, You have no partner, here I am. Truly all praise, favor, and dominion belong to You. You have no partner.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":4892,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: كان المشركون يقولون: لَبَّيْكَ لا شَرِيكَ لَكَ. قال: فيقول رسولُ اللَّهِ ﷺ: (( وَيْلَكُمْ! قَدْ قَدْ )). فيقولون: إلا شريكًا هو لك، تملكه وما ملك. يقولون هذا وهم يطوفون بالبيت."],"takhrij":"صحيح: رواه مسلم (١١٨٥).","grade":"صحيح","chapter_ar":"باب في صيغة تلبية رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1185).","chapter_en":"Concerning the wording of the talbiyah of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["ʿAbd Allāh ibn ʿAbbās said: The polytheists used to say: “Here I am, You have no partner.” He said: Then the Messenger of Allah ﷺ would say: “Woe to you! Enough, enough!” But they would say: “Except for a partner who belongs to You; You own him and whatever he owns.” They used to say this while circling the House."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1185}]},{"num":4893,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول اللّٰه ﷺ قال في تلبيته: (( لبيك إله الحقّ لبيك ))."],"takhrij":"صحيح: رواه النسائيّ (٢٧٥٢)، وابن ماجه (٢٩٢٠)، وصححه ابن خزيمة (٢٦٢٤)، وابن حبان.","grade":"صحيح","chapter_ar":"باب في صيغة تلبية رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (2752) and Ibn Majah (2920), and authenticated by Ibn Khuzaymah (2624) and Ibn Hibban.","chapter_en":"Concerning the wording of the talbiyah of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said in his talbiyah: “Here I am, O God of truth, here I am.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2752},{"key":"ibnmajah","label":"ابن ماجه","number":2920},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2624}]},{"num":4894,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: سمعت رسول اللّٰه ﷺ يلبّي: (( لبيك حقًّا حقًّا، تعبّدًا ورقًّا ))."],"takhrij":"صحيح: رواه الخطيب في تاريخه (٢١٥/١٤).","grade":"صحيح","chapter_ar":"باب في صيغة تلبية رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Khatib in his Tarikh (14/215).","chapter_en":"Concerning the wording of the talbiyah of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Malik said: I heard the Messenger of Allah ﷺ reciting the talbiyah: “Here I am in truth, in truth, in worship and servitude.”"]}},"tuhfa":{},"refs":[{"key":"الخطیب/تاریخہ","label":"الخطيب في تاريخه","number":215}]},{"num":4895,"demo":false,"sanad":"","matn":["عن عبدالله بن عباس، قال: سِرْنَا مَعَ رَسُولِ اللَّهِ ﷺ بَيْنَ مَكَّةَ وَالْمَدِينَةِ فَمَرَرْنَا بِوَادٍ، فَقَالَ: (( أَيُّ وَادٍ هَذَا؟ )). فَقَالُوا: وَادِي الأَزْرَقِ. فَقَالَ: (( كَأَنِّي أَنْظُرُ إِلَى مُوسَى ﷺ - فَذَكَرَ مِنْ لَوْنِهِ وَشَعْرِهِ شَيْئًا لَمْ يَحْفَظْهُ دَاوُدُ - وَاضِعًا إِصْبَعَيْهِ فِي أُذُنَيْهِ لَهُ جُؤَارٌ إِلَى اللَّهِ بِالتَّلْبِيَةِ مَارًّا بِهَذَا الْوَادِي )).","قَالَ: ثُمَّ سِرْنَا حَتَّى أَتَيْنَا عَلَى ثَنِيَّةٍ، فَقَالَ: (( أَيُّ ثَنِيَّةٍ هَذِهِ؟ )). قَالُوا: هَرْشَى أَوْ لِفْتٌ. فَقَالَ: (( كَأَنِّي أَنْظُرُ إِلَى يُونُسَ عَلَى نَاقَةٍ حَمْرَاءَ، عَلَيْهِ جُبَّةُ صُوفٍ، خِطَامُ نَاقَتِهِ لِيفٌ خُلْبَةٌ، مَارًّا بِهَذَا الْوَادِي مُلَبِّيًا ))."],"takhrij":"صحيح: رواه مسلم (١٦٦ : ٢٦٩).","grade":"صحيح","chapter_ar":"باب في استحباب رفع الصوت بالتلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (269/166).","chapter_en":"On the recommendation of raising the voice in the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas said: We traveled with the Messenger of Allah ﷺ between Makkah and Madinah, and we passed by a valley. He said: “Which valley is this?” They said: Wadi al-Azraq. He said: “It is as though I am looking at Musa ﷺ” — and he mentioned something about his color and hair that Dawud did not preserve — “placing his fingers in his ears, calling out loudly to Allah with the talbiyah while passing through this valley.”","He said: Then we continued until we came to a mountain pass. He said: “Which pass is this?” They said: Harsha or Lift. He said: “It is as though I am looking at Yunus on a red she-camel, wearing a wool cloak, with the halter of his camel made of palm fiber, passing through this valley reciting the talbiyah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":166}]},{"num":4896,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدريّ، قال: خَرَجْنَا مَعَ رَسُولِ اللَّهِ ﷺ نَصْرُخُ بِالْحَجِّ صُرَاخًا، فَلَمَّا قَدِمْنَا مَكَّةَ أَمَرَنَا أَنْ نَجْعَلَهَا عُمْرَةً إِلَّا مَنْ سَاقَ الْهَدْيَ، فَلَمَّا كَانَ يَوْمُ التَّرْوِيَةِ وَرُحْنَا إِلَى مِنًى أَهَلَلْنَا بِالْحَجِّ."],"takhrij":"صحيح: رواه مسلم (١٢٤٧).","grade":"صحيح","chapter_ar":"باب في استحباب رفع الصوت بالتلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1247).","chapter_en":"On the recommendation of raising the voice in the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: We went out with the Messenger of Allah ﷺ crying out loudly with Hajj. When we arrived in Makkah, he ordered us to make it into an Umrah, except for the one who had brought sacrificial animals. Then when the Day of Tarwiyah came and we set out to Mina, we entered into ihram for Hajj."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1247}]},{"num":4897,"demo":false,"sanad":"","matn":["عن جابر وأبي سعيد الخدريّ، قالا: قَدِمْنَا مَعَ النَّبِيِّ ﷺ وَنَحْنُ نَصْرُخُ بِالْحَجِّ صُرَاخًا."],"takhrij":"صحيح: رواه مسلم (١٢٤٨).","grade":"صحيح","chapter_ar":"باب في استحباب رفع الصوت بالتلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1248).","chapter_en":"On the recommendation of raising the voice in the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Jabir and Abu Sa‘id al-Khudri said: We came with the Prophet ﷺ while crying out loudly with Hajj."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1248}]},{"num":4898,"demo":false,"sanad":"","matn":["عن السائب بن خلاد بن سويد الأنصاريّ، أنَّ رَسُولَ اللَّهِ ﷺ قَالَ: (( أَتَانِي جِبْرِيلُ، فَأَمَرَنِي أَنْ آمُرَ أَصْحَابِي - أَوْ مَنْ مَعِي - أَنْ يَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ أَوْ بِالإِهْلَالِ )) يُرِيدُ أَحَدَهُمَا."],"takhrij":"صحيح: رواه مالك (٣٤)، وأبو داود (١٨١٤)، والترمذيّ (٨٢٩) وصحّحه، والنسائي (٢٧٥٣)، وابن ماجه (٢٩٢٢).","grade":"صحيح","chapter_ar":"باب في استحباب رفع الصوت بالتلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Malik (34), Abu Dawud (1814), al-Tirmidhi (829), who authenticated it, al-Nasa’i (2753), and Ibn Majah (2922).","chapter_en":"On the recommendation of raising the voice in the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Al-Sa’ib ibn Khallad ibn Suwayd al-Ansari reported that the Messenger of Allah ﷺ said: “Jibril came to me and ordered me to command my companions — or those with me — to raise their voices with the talbiyah or with the ihram proclamation,” meaning one of the two expressions."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":34},{"key":"abudawud","label":"أبو داود","number":1814},{"key":"tirmidhi","label":"الترمذيّ","number":829},{"key":"nasai","label":"النسائي","number":2753},{"key":"ibnmajah","label":"ابن ماجه","number":2922}]},{"num":4899,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول اللّٰه ﷺ قال: (( إن جبريل أتاني، فأمرني أن أعلن بالتلبية ))."],"takhrij":"حسن: رواه أحمد (٢٩٥٠)، والبخاري في تاريخه (١٨٧/٢).","grade":"حسن","chapter_ar":"باب في استحباب رفع الصوت بالتلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (2950), and by al-Bukhari in his Tarikh (2/187).","chapter_en":"On the recommendation of raising the voice in the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Jibril came to me and commanded me to proclaim the talbiyah openly.”"]}},"tuhfa":{},"refs":[{"key":"bukhari/تاریخہ","label":"البخاري في تاريخه","number":187},{"key":"ahmad","label":"مسند الإمام أحمد","number":2950,"n":2950}]},{"num":4900,"demo":false,"sanad":"","matn":["عن زيد بن خالد الجهني، قال: قال رسول اللّٰه ﷺ: (( جاءني جبريل فقال: يا محمد، مُرْ أَصْحَابَكَ فليرفعوا أصواتهم بالتلبية، فإنها من شعائر الحج ))."],"takhrij":"حسن: رواه ابن ماجه (٢٩٢٣)، وابن خزيمة (٢٦٢٨)، وابن حبان (٣٨٠٣)، والحاكم (٤٥٠/١).","grade":"حسن","chapter_ar":"باب في استحباب رفع الصوت بالتلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (2923), Ibn Khuzaymah (2628), Ibn Hibban (3803), and al-Hakim (1/450).","chapter_en":"On the recommendation of raising the voice in the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: The Messenger of Allah ﷺ said: “Jibril came to me and said: ‘O Muhammad, command your companions to raise their voices with the talbiyah, for it is among the rites of Hajj.’”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2923},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2628},{"key":"ibnhibban","label":"ابن حبان","number":3803},{"key":"hakim","label":"الحاكم","number":450}]},{"num":4901,"demo":false,"sanad":"","matn":["عن سهل بن سعد، قال: قال رسول اللّٰه ﷺ: (( مَا مِنْ مُسْلِمٍ يُلَبِّي إِلَّا لَبَّى مَنْ عَنْ يَمِينِهِ أَوْ عَنْ شِمَالِهِ مِنْ حَجَرٍ أَوْ شَجَرٍ أَوْ مَدَرٍ، حَتَّى تَنْقَطِعَ الأَرْضُ مِنْ هَاهُنَا وَهَاهُنَا ))."],"takhrij":"حسن: رواه الترمذيّ (٨٢٨)، وابن ماجه (٢٩٢١).","grade":"حسن","chapter_ar":"باب ما جاء في فضل التلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (828) and Ibn Majah (2921).","chapter_en":"What has been reported regarding the virtue of the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Sahl ibn Sa‘d said: The Messenger of Allah ﷺ said: “There is no Muslim who recites the talbiyah except that whatever is on his right and left — stones, trees, or clods of earth — also recites it, until the land ends in this direction and that direction.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":828},{"key":"ibnmajah","label":"ابن ماجه","number":2921}]},{"num":4902,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، قال: قال رسول اللّه ﷺ: (( أفضل الحجّ: العَجُّ والثَّجُّ )). فأما العجّ فالتلبية، وأما الثجّ فنحر البُدن."],"takhrij":"حسن: رواه أبو يعلى (٥٠٨٢)، وأبو بكر بن أبي شيبة كما في المطالب العالية (١٢٧٣).","grade":"حسن","chapter_ar":"باب ما جاء في فضل التلبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Abu Ya‘la (5082), and by Abu Bakr ibn Abi Shaybah as cited in al-Matalib al-‘Aliyah (1273).","chapter_en":"What has been reported regarding the virtue of the talbiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: The Messenger of Allah ﷺ said: “The best Hajj is al-‘ajj and al-thajj.” As for al-‘ajj, it means the talbiyah; and as for al-thajj, it means slaughtering the sacrificial camels."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":5082},{"key":"ابو_بکر_بن_ابی_شیبہ_کما/المطالب_العالیہ","label":"أبو بكر بن أبي شيبة كما في المطالب العالية","number":1273},{"key":"sh12520","label":"مسند أبي يعلى","number":5086,"n":5091}]},{"num":4903,"demo":false,"sanad":"","matn":["عن نافع، قال: كان ابن عمر رضي اللّٰه عنهما إِذَا دَخَلَ أَدْنَى الْحَرَمِ أَمْسَكَ عَنِ التَّلْبِيَةِ، ثُمَّ يَبِيتُ بِذِي طُوًى، ثُمَّ يُصَلِّي بِهِ الصُّبْحَ وَيَغْتَسِلُ، وَيُحَدِّثُ أَنَّ نَبِيَّ اللَّهِ ﷺ كَانَ يَفْعَلُ ذَلِكَ."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٧٣)، ومسلم (١٢٥٩). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب من قال بقطع التلبية عند دخول مكة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1573) and Muslim (1259). The wording is that of al-Bukhari.","chapter_en":"Those who held that the talbiyah is stopped upon entering Makkah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Nafi‘ said: When Ibn ‘Umar, may Allah be pleased with them both, entered the nearest part of the sanctuary, he would stop the talbiyah. Then he would spend the night at Dhi Tuwa, pray Fajr there, bathe, and relate that the Prophet of Allah ﷺ used to do that."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1573},{"key":"muslim","label":"مسلم","number":1259}]},{"num":4904,"demo":false,"sanad":"","matn":["عن أسامة بن زيد، قال: رَدِفْتُ رَسُولَ اللَّهِ ﷺ مِنْ عَرَفَاتٍ، فَلَمَّا بَلَغَ رَسُولُ اللَّهِ ﷺ الشِّعْبَ الأَيْسَرَ الَّذِي دُونَ الْمُزْدَلِفَةِ أَنَاخَ، فَبَالَ، ثُمَّ جَاءَ فَصَبَبْتُ عَلَيْهِ الْوَضُوءَ، فَتَوَضَّأَ وُضُوءًا خَفِيفًا، فَقُلْتُ: الصَّلَاةُ يَا رَسُولَ اللَّهِ؟ قَالَ: (( الصَّلاةُ أَمَامَكَ )). فَرَكِبَ رَسُولُ اللَّهِ ﷺ حَتَّى أَتَى الْمُزْدَلِفَةَ فَصَلَّى، ثُمَّ رَدِفَ الْفَضْلُ رَسُولَ اللَّهِ ﷺ غَدَاةَ جَمْعٍ.","قَالَ كُرَيْبٌ: فَأَخْبَرَنِي عبد الله بن عباس رضي اللّٰه عنهما، عَنِ الْفَضْلِ أَنَّ رَسُولَ اللَّهِ ﷺ لَمْ يَزَلْ يُلَبِّي حَتَّى بَلَغَ الْجَمْرَةَ."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٦٩)، ومسلم (١٢٨٠).","grade":"متفق عليه","chapter_ar":"باب استحباب الاستدامة على التلبية في الحج إلى رمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1669) and Muslim (1280).","chapter_en":"The recommendation of continuing the talbiyah during Hajj until stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Usamah ibn Zayd said: I rode behind the Messenger of Allah ﷺ from ‘Arafat. When the Messenger of Allah ﷺ reached the left mountain pass below Muzdalifah, he made his camel kneel, urinated, then came back and I poured water for his ablution, so he performed a light ablution. I said: The prayer, O Messenger of Allah? He said: “The prayer is ahead of you.” So the Messenger of Allah ﷺ rode until he came to Muzdalifah and prayed. Then al-Fadl rode behind the Messenger of Allah ﷺ on the morning of Jam‘.","Kurayb said: Then ‘Abdullah ibn ‘Abbas, may Allah be pleased with them both, informed me from al-Fadl that the Messenger of Allah ﷺ continued reciting the talbiyah until he reached the Jamrah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1669},{"key":"muslim","label":"مسلم","number":1280}]},{"num":4905,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس أن النبيّ ﷺ أردف الفضل، فأخبر الفضل أنه لم يزل يُلبّي حتى رمى الجمرة."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٨٥)، ومسلم (١٢٨١).","grade":"متفق عليه","chapter_ar":"باب استحباب الاستدامة على التلبية في الحج إلى رمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1685) and Muslim (1281).","chapter_en":"The recommendation of continuing the talbiyah during Hajj until stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas reported that the Prophet ﷺ had al-Fadl ride behind him, and al-Fadl reported that he continued reciting the talbiyah until he stoned the Jamrah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1685},{"key":"muslim","label":"مسلم","number":1281}]},{"num":4906,"demo":false,"sanad":"","matn":["عن الفضل بن عباس - وكان رديف رسول الله ﷺ - أنه قال في عشية عرفة وغداة جمع للناس حين دفعوا: (( عليكم بالسكينة )). وهو كافٌّ ناقته حتى دخل مُحَسِّرًا - وهو من منى - قال: (( عليكم بحصى الخذف الذي يُرمى به الجمرة )). وقال: لم يزل رسول اللّٰه ﷺ يُلبّي حتى رمى الجمرة."],"takhrij":"صحيح: رواه مسلم (١٢٨٢).","grade":"صحيح","chapter_ar":"باب استحباب الاستدامة على التلبية في الحج إلى رمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1282).","chapter_en":"The recommendation of continuing the talbiyah during Hajj until stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Al-Fadl ibn ‘Abbas — who was riding behind the Messenger of Allah ﷺ — said that on the evening of ‘Arafah and the morning of Jam‘, when the people moved on, he said: “Maintain calmness.” And he was restraining his camel until he entered Muhassir — which is part of Mina. He said: “Use pebbles the size of those used in finger-flicking for stoning the Jamrah.” And he said: The Messenger of Allah ﷺ continued reciting the talbiyah until he stoned the Jamrah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1282}]},{"num":4907,"demo":false,"sanad":"","matn":["عن عكرمة قال: أفضتُ مع الحسين بن علي من المزدلفة فلم أزل أسمعه يُلبِّي حتى رمى جمرة العقبة، فسألته فقال: أفضتُ مع أبي من المزدلفة فلم أزل أسمعه يُلبِّي حتى رمى جمرة العقبة، فسألته فقال: أفضتُ مع النبيّ ﷺ من المزدلفة فلم أزل أسمعه يُلبِّي حتى رمى جمرة العقبة."],"takhrij":"حسن: رواه أحمد (٩١٥)، وأبو يعلى (٣٢١)، والطحاوي في شرح المشكل (٣٩٢١).","grade":"حسن","chapter_ar":"باب استحباب الاستدامة على التلبية في الحج إلى رمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (915), Abu Ya‘la (321), and al-Tahawi in Sharh al-Mushkil (3921).","chapter_en":"The recommendation of continuing the talbiyah during Hajj until stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["‘Ikrimah said: I departed from Muzdalifah with al-Husayn ibn ‘Ali, and I kept hearing him reciting the talbiyah until he stoned Jamrat al-‘Aqabah. So I asked him, and he said: I departed from Muzdalifah with my father, and I kept hearing him reciting the talbiyah until he stoned Jamrat al-‘Aqabah. So I asked him, and he said: I departed from Muzdalifah with the Prophet ﷺ, and I kept hearing him reciting the talbiyah until he stoned Jamrat al-‘Aqabah."]},"buhuth":{"ar":["وقولُه: (( حتى رمى الجمرة )) يُفهم منه الانتهاء من رمي جمرة العقبة سبع حصيات، وقد جاء مُصرَّحًا به في الحديث الآتي."],"en":["His statement, “until he stoned the Jamrah,” indicates finishing the stoning of Jamrat al-‘Aqabah with seven pebbles, and this is stated explicitly in the following hadith."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":321},{"key":"الطحاوی/شرح_المشکل","label":"الطحاوي في شرح المشكل","number":3921},{"key":"ahmad","label":"مسند الإمام أحمد","number":915,"n":915}]},{"num":4908,"demo":false,"sanad":"","matn":["عن الفضل بن عباس قال: أفضتُ مع النبيّ ﷺ في عرفات، فلم يزل يُلبّي حتى رمى جمرة العقبة، يكبِّر مع كل حصاةٍ، ثم قطع التلبية مع آخرها حصاةً."],"takhrij":"حسن: رواه ابنُ خزيمة (٢٨٨٧).","grade":"حسن","chapter_ar":"باب استحباب الاستدامة على التلبية في الحج إلى رمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Khuzaymah (2887).","chapter_en":"The recommendation of continuing the talbiyah during Hajj until stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Al-Fadl ibn ‘Abbas said: I departed with the Prophet ﷺ at ‘Arafat, and he continued reciting the talbiyah until he stoned Jamrat al-‘Aqabah, saying the takbir with each pebble, then he stopped the talbiyah with the last pebble."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابنُ خزيمة","number":2887}]},{"num":4909,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن يزيد أن عبد الله - هو ابن مسعود - لبّى حين أفاض من جمع. قيل: أعرابيٌّ هذا؟ فقال عبدُ الله: أنسيَ الناسُ أم ضلّوا؟ سمعتُ الذي أُنزلتْ عليه سورة البقرة يقول في هذا المكان: (( لبيك اللهم لبّيك ))."],"takhrij":"صحيح: رواه مسلم في الحج (١٢٨٣).","grade":"صحيح","chapter_ar":"باب استحباب الاستدامة على التلبية في الحج إلى رمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim in the Book of Hajj (1283).","chapter_en":"The recommendation of continuing the talbiyah during Hajj until stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["‘Abd al-Rahman ibn Yazid reported that ‘Abdullah — meaning Ibn Mas‘ud — recited the talbiyah when he departed from Jam‘. It was said: Is this an act of a Bedouin? So ‘Abdullah said: Have the people forgotten or gone astray? I heard the one upon whom Surat al-Baqarah was revealed saying in this place: “Here I am, O Allah, here I am.”"]}},"tuhfa":{},"refs":[{"key":"muslim/الحج","label":"مسلم في الحج","number":1283}]},{"num":4910,"demo":false,"sanad":"","matn":["عن ابن سَخْبَرَة قال: غدوتُ مع عبد الله بن مسعود من منى إلى عرفات، فكان يُلبِّي، قال: وكان عبد الله رجلاً آدم له ضفيرتان عليه مِسحةُ أهلِ البادية، فاجتمع عليه غوغاءُ من غوغاء الناس، قالوا: يا أعرابي، إن هذا ليس يوم تلبية، وإنما هو يومُ تكبير. قال: فعند ذلك التفتَ إليَّ فقال: أجهل الناسُ أم نسوا؟ والذي بعث محمدًا ﷺ بالحق لقد خرجتُ مع رسول الله ﷺ فما ترك التلبية حتى رمى جمرة العقبة، إلا أن يخلطها بتكبير، أو تهليل."],"takhrij":"حسن: رواه أحمد (٣٩٦١)، وابنُ خزيمة (٢٨٠٦)، والحاكم (٤٦١-٤٦٢/١)، وعنه البيهقي (١٣٨/٥).","grade":"حسن","chapter_ar":"باب استحباب الاستدامة على التلبية في الحج إلى رمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (3961), Ibn Khuzaymah (2806), al-Hakim (1/461–462), and from him al-Bayhaqi (5/138).","chapter_en":"The recommendation of continuing the talbiyah during Hajj until stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Ibn Sakhbarah said: I set out with ‘Abdullah ibn Mas‘ud from Mina to ‘Arafat, and he was reciting the talbiyah. He said: And ‘Abdullah was a dark-complexioned man with two braids, bearing the appearance of the desert people. Then the rabble of the people gathered around him and said: O Bedouin, this is not a day for talbiyah; it is only a day for takbir. At that he turned to me and said: Are the people ignorant, or have they forgotten? By the One who sent Muhammad ﷺ with the truth, I went out with the Messenger of Allah ﷺ and he did not stop the talbiyah until he stoned Jamrat al-‘Aqabah, except that he would mix it with takbir or tahlil."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابنُ خزيمة","number":2806},{"key":"عنہ_البیہقی","label":"عنه البيهقي","number":138},{"key":"ahmad","label":"مسند الإمام أحمد","number":3961,"n":3961},{"key":"hakim","label":"المستدرك على الصحيحين","number":1696,"n":1686},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":9605,"n":9685}]},{"num":4911,"demo":false,"sanad":"","matn":["عن عائشة، أنّها قالت: خَرَجْنَا مَعَ رَسُولِ اللَّهِ ﷺ مُوَافِينَ هِلالَ ذِي الْحِجَّةِ، فَلَمَّا كَانَ بِذِي الْحُلَيْفَةِ، قَالَ: (( مَنْ شَاءَ أَنْ يُهِلَّ بِحَجٍّ فَلْيُهِلَّ، وَمَنْ شَاءَ أَنْ يُهِلَّ بِعُمْرَةٍ فَلْيُهِلَّ بِعُمْرَةٍ )).","قَالَ مُوسَى فِي حَدِيثِ وُهَيْبٍ: (( فَإِنِّي لَوْلَا أَنِّي أَهْدَيْتُ لأَهْلَلْتُ بِعُمْرَةٍ )). وَقَالَ فِي حَدِيثِ حَمَّادِ بْنِ سَلَمَةَ: (( وَأَمَّا أَنَا فَأُهِلُّ بِالْحَجِّ فَإِنَّ مَعِيَ الْهَدْيَ )).","ثُمَّ اتَّفَقُوا: (( فَكُنْتُ فِيمَنْ أَهَلَّ بِعُمْرَةٍ، فَلَمَّا كَانَ فِي الطَّرِيقِ حِضْتُ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ﷺ وَأَنَا أَبْكِي، فَقَالَ: (( مَا يُبْكِيكِ؟ )). قُلْتُ: وَدِدْتُ أَنِّي لَمْ أَكُنْ خَرَجْتُ الْعَامَ. قَالَ: (( ارْفُضِي عُمْرَتَكِ، وَانْقُضِي رَأْسَكِ، وَامْتَشِطِي )).","قَالَ مُوسَى: (( وَأَهِلِّي بِالْحَجِّ )). وَقَالَ سُلَيْمَانُ: (( وَاصْنَعِي مَا يَصْنَعُ الْمُسْلِمُونَ فِي حَجِّهِمْ )).","فَلَمَّا كَانَ لَيْلَةُ الصَّدَرِ أَمَرَ - يَعْنِي رَسُولَ اللَّهِ ﷺ - عَبْدَ الرَّحْمَنِ، فَذَهَبَ بِهَا إِلَى التَّنْعِيمِ. زَادَ مُوسَى: (( فَأَهَلَّتْ بِعُمْرَةٍ مَكَانَ عُمْرَتِهَا، وَطَافَتْ بِالْبَيْتِ، فَقَضَى اللَّهُ عُمْرَتَهَا وَحَجَّهَا ))."],"takhrij":"صحيح: رواه أبو داود (١٧٧٨)، والنسائيّ (٢٧١٧)، وابن خزيمة (٢٦٠٤)، وابن حبان (٣٧٩٢).","grade":"صحيح","chapter_ar":"باب تخيير النبيّ ﷺ في ذي الحليفة بالإفراد أو بالتمتع لمن لم يسق الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1778), al-Nasa’i (2717), Ibn Khuzaymah (2604), and Ibn Hibban (3792).","chapter_en":"The Prophet’s giving the choice at Dhul-Hulayfah between ifrad and tamattu‘ for the one who did not bring sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah said: We went out with the Messenger of Allah ﷺ near the sighting of the crescent of Dhu al-Hijjah. When he reached Dhul-Hulayfah, he said: “Whoever wishes to enter ihram for Hajj, let him do so; and whoever wishes to enter ihram for Umrah, let him do so for Umrah.”","Musa said in the narration of Wuhaib: “As for me, had I not brought sacrificial animals, I would have entered ihram for Umrah.” And in the narration of Hammad ibn Salamah: “But as for me, I am entering ihram for Hajj, for I have the sacrificial animals with me.”","Then they agreed on the wording: “So I was among those who entered ihram for Umrah. Then on the way I menstruated. The Messenger of Allah ﷺ came to me while I was crying, and he said: ‘What makes you cry?’ I said: I wish I had not gone out this year. He said: ‘Set aside your Umrah, undo your hair, and comb it.’”","Musa said: “And enter ihram for Hajj.” Sulayman said: “And do what the Muslims do in their Hajj.”","Then when the night of departure came, he — meaning the Messenger of Allah ﷺ — ordered ‘Abd al-Rahman, and he took her to al-Tan‘im. Musa added: “So she entered ihram for an Umrah in place of her earlier Umrah, and she circumambulated the House, and Allah completed her Umrah and her Hajj.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1778},{"key":"nasai","label":"النسائيّ","number":2717},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2604},{"key":"ibnhibban","label":"ابن حبان","number":3792}]},{"num":4912,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خَرَجْنَا مَعَ رَسُولِ اللَّهِ ﷺ مُهِلِّينَ بِالْحَجِّ فِي أَشْهُرِ الْحَجِّ، وَفِي حُرُمِ الْحَجِّ، وَلَيَالِي الْحَجِّ، حَتَّى نَزَلْنَا بِسَرِفَ، فَخَرَجَ إِلَى أَصْحَابِهِ فَقَالَ: (( مَنْ لَمْ يَكُنْ مَعَهُ مِنْكُمْ هَدْيٌ، فَأَحَبَّ أَنْ يَجْعَلَهَا عُمْرَةً فَلْيَفْعَلْ، وَمَنْ كَانَ مَعَهُ هَدْيٌ فَلَا ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٦٠)، ومسلم (١٢٣ :١٢١١).","grade":"متفق عليه","chapter_ar":"باب ترغيب النبي ﷺ بسَرِف بالتمتع لمن ليس معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1560) and Muslim (1211/123).","chapter_en":"The Prophet’s encouragement at Sarif to perform tamattu‘ for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah said: We went out with the Messenger of Allah ﷺ entering ihram for Hajj during the months of Hajj, during the nights of Hajj, and within the sacred bounds of Hajj, until we came to Sarif. Then he went out to his Companions and said: “Whoever among you does not have sacrificial animals and would like to make it an Umrah, let him do so. But whoever has sacrificial animals with him, then no.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1560},{"key":"muslim","label":"مسلم","number":123}]},{"num":4913,"demo":false,"sanad":"","matn":["عن أم المؤمنين عائشة، قالت: خَرَجْنَا مَعَ النَّبِيِّ ﷺ وَلا نُرَى إِلَّا أَنَّهُ الْحَجُّ، فَلَمَّا قَدِمْنَا تَطَوَّفْنَا بِالْبَيْتِ، أَمَرَ النَّبِيُّ ﷺ مَنْ لَمْ يَكُنْ سَاقَ الْهَدْيَ أَنْ يَحِلَّ، فَحَلَّ مَنْ لَمْ يَكُنْ سَاقَ الْهَدْيَ، وَنِسَاؤُهُ لَمْ يَسُقْنَ، فَأَحْلَلْنَ."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٦١)، ومسلم (١٢٨ :١٢١١).","grade":"متفق عليه","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1561) and Muslim (1211/128).","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["The Mother of the Believers, ‘A’ishah, said: We went out with the Prophet ﷺ not thinking it was anything but Hajj. Then when we arrived, we circled the House. The Prophet ﷺ ordered whoever had not brought sacrificial animals to come out of ihram, so those who had not brought sacrificial animals came out of ihram. And his wives had not brought sacrificial animals, so they too came out of ihram."]},"buhuth":{"ar":["وفي رواية عند مسلم (١٣٠)، عن عائشة، قالت: قَدِمَ رَسُولُ اللَّهِ ﷺ لِأَرْبَعٍ مَضَيْنَ مِنْ ذِي الْحِجَّةِ أَوْ خَمْسٍ، فَدَخَلَ عَلَيَّ وَهُوَ غَضْبَانُ، فَقُلْتُ: مَنْ أَغْضَبَكَ يَا رَسُولَ اللَّهِ؟ أَدْخَلَهُ اللَّهُ النَّارَ. قَالَ: (( أَوَمَا شَعَرْتِ أَنِّي أَمَرْتُ النَّاسَ بِأَمْرٍ، فَإِذَا هُمْ يَتَرَدَّدُونَ؟ )) قَالَ الْحَكَمُ: كَأَنَّهُمْ يَتَرَدَّدُونَ. أَحْسِبُ. (( وَلَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ، مَا سُقْتُ الْهَدْيَ مَعِي حَتَّى أَشْتَرِيَهُ، ثُمَّ أَحِلُّ كَمَا حَلُّوا ))."],"en":["And in a narration in Muslim (130), from ‘A’ishah, she said: The Messenger of Allah ﷺ arrived on the fourth or fifth of Dhu al-Hijjah, and he entered upon me while angry. So I said: Who angered you, O Messenger of Allah ﷺ? May Allah enter him into the Fire. He said: “Have you not realized that I commanded the people with a matter, yet they are hesitating?” Al-Hakam said: It is as though they were hesitating — I think so. “Had I known beforehand what I came to know later, I would not have brought the sacrificial animals with me until I bought them here, and then I would have come out of ihram as they did.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1561},{"key":"muslim","label":"مسلم","number":128}]},{"num":4914,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خَرَجْنَا مَعَ رَسُولِ اللَّهِ ﷺ لا نَذْكُرُ إِلَّا الْحَجَّ، حَتَّى جِئْنَا سَرِفَ فَطَمِثْتُ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ﷺ وَأَنَا أَبْكِي، فَقَالَ: (( مَا يُبْكِيكِ؟ )). فَقُلْتُ: وَاللَّهِ لَوَدِدْتُ أَنِّي لَمْ أَكُنْ خَرَجْتُ الْعَامَ. قَالَ: (( مَا لَكِ؟ لَعَلَّكِ نَفِسْتِ؟ )). قُلْتُ: نَعَمْ. قَالَ: (( هَذَا شَيْءٌ كَتَبَهُ اللَّهُ عَلَى بَنَاتِ آدَمَ، افْعَلِي مَا يَفْعَلُ الْحَاجُّ، غَيْرَ أَنْ لا تَطُوفِي بِالْبَيْتِ حَتَّى تَطْهُرِي )). قَالَتْ: فَلَمَّا قَدِمْتُ مَكَّةَ، قَالَ رَسُولُ اللَّهِ ﷺ لِأَصْحَابِهِ: (( اجْعَلُوهَا عُمْرَةً )). فَأَحَلَّ النَّاسُ إِلَّا مَنْ كَانَ مَعَهُ الْهَدْيُ."],"takhrij":"صحيح: رواه مسلم (١٢٠ :١٢١١).","grade":"صحيح","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1211/120).","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["‘A’ishah said: We went out with the Messenger of Allah ﷺ thinking only of Hajj, until we came to Sarif and I menstruated. The Messenger of Allah ﷺ entered upon me while I was crying, and he said: “What makes you cry?” I said: By Allah, I wish I had not gone out this year. He said: “What is the matter? Perhaps you have begun menstruating?” I said: Yes. He said: “This is something Allah has decreed upon the daughters of Adam. Do what the pilgrim does, except that you must not circumambulate the House until you become pure.” She said: Then when I came to Makkah, the Messenger of Allah ﷺ said to his Companions: “Make it an Umrah.” So the people came out of ihram, except for those who had sacrificial animals with them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":120}]},{"num":4915,"demo":false,"sanad":"","matn":["عن أنس بن مالك، قال: قَدِمَ عَلِيٌّ رضي اللَّه عنه مِنَ الْيَمَنِ، فَقَالَ لَهُ النَّبِيُّ ﷺ: (( بِمَ أَهْلَلْتَ؟ ))، قَالَ: بِمَا أَهَلَّ بِهِ النَّبِيُّ ﷺ. قَالَ: (( لَوْلَا أَنَّ مَعِيَ الْهَدْيَ لأَحْلَلْتُ ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٥٨)، ومسلم (١٢٥٠).","grade":"متفق عليه","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1558) and Muslim (1250).","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Malik said: ‘Ali, may Allah be pleased with him, arrived from Yemen, and the Prophet ﷺ said to him: “With what did you enter ihram?” He said: With what the Prophet ﷺ entered ihram for. He said: “Were it not that I have the sacrificial animals with me, I would have come out of ihram.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1558},{"key":"muslim","label":"مسلم","number":1250}]},{"num":4916,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري، قال: قَدِمْتُ عَلَى رَسُولِ اللَّهِ ﷺ وَهُوَ مُنِيخٌ بِالْبَطْحَاءِ، فَقَالَ: (( بِمَ أَهْلَلْتَ؟ )). قَالَ: قُلْتُ: أَهْلَلْتُ بِإِهْلَالِ النَّبِيِّ ﷺ. قَالَ: (( هَلْ سُقْتَ مِنْ هَدْيٍ؟ )). قُلْتُ: لا. قَالَ: (( فَطُفْ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، ثُمَّ حِلَّ )). فَطُفْتُ بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، ثُمَّ أَتَيْتُ امْرَأَةً مِنْ قَوْمِي فَمَشَطَتْنِي وَغَسَلَتْ رَأْسِي، فَكُنْتُ أُفْتِي النَّاسَ بِذَلِكَ فِي إِمَارَةِ أَبِي بَكْرٍ وَإِمَارَةِ عُمَرَ، فَبَيْنَا أَنَا بِالْمَوْسِمِ إِذْ جَاءَنِي رَجُلٌ فَقَالَ: إِنَّكَ لا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي شَأْنِ النُّسُكِ. فَقُلْتُ: يَا أَيُّهَا النَّاسُ، مَنْ كُنَّا أَفْتَيْنَاهُ بِشَيْءٍ فَلْيَتَّئِدْ، فَهَذَا أَمِيرُ الْمُؤْمِنِينَ قَادِمٌ عَلَيْكُمْ، فَبِهِ فَأْتَمُّوا. فَلَمَّا قَدِمَ قُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ، مَا هَذَا الَّذِي أَحْدَثْتَ فِي شَأْنِ النُّسُكِ؟ قَالَ: إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ: (وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ)، وَإِنْ نَأْخُذْ بِسُنَّةِ نَبِيِّنَا ﷺ فَإِنَّ النَّبِيَّ ﷺ لَمْ يَحِلَّ حَتَّى نَحَرَ الْهَدْيَ."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٥٩)، ومسلم (١٥٥ :١٢٢١)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1559) and Muslim (1221/155). The wording is that of Muslim.","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: I came to the Messenger of Allah ﷺ while he was camped at al-Batha’, and he said: “With what did you enter ihram?” I said: I entered ihram with the same ihram as the Prophet ﷺ. He said: “Did you bring any sacrificial animals?” I said: No. He said: “Then circumambulate the House and go between al-Safa and al-Marwah, then come out of ihram.” So I circumambulated the House and went between al-Safa and al-Marwah, then I went to a woman from my people and she combed my hair and washed my head. I used to give legal verdicts to the people with that during the caliphate of Abu Bakr and during the caliphate of ‘Umar. Then while I was in the pilgrimage season, a man came to me and said: You do not know what the Commander of the Believers has newly decided regarding the rites. So I said: O people, whoever we have given a ruling to about something, let him wait, for here is the Commander of the Believers coming to you, so follow him in this matter. Then when he came, I said: O Commander of the Believers, what is this that you have newly decided regarding the rites? He said: If we follow the Book of Allah, then Allah the Mighty and Majestic has said, “Complete the Hajj and Umrah for Allah.” And if we follow the Sunnah of our Prophet ﷺ, then the Prophet ﷺ did not come out of ihram until he slaughtered the sacrificial animals."]},"buhuth":{"ar":["وفي رواية لمسلم أيضاً (١٢٢٢) عن أبي موسى؛ أنه كان يفتي بالمتعة، فقال له رجل: (( رُوَيْدَكَ بَعْضَ فُتْيَاكَ، فَإِنَّكَ لا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي النُّسُكِ بَعْدُ )). حَتَّى لَقِيَهُ بَعْدُ، فَسَأَلَهُ، فَقَالَ عُمَرُ: قَدْ عَلِمْتُ أَنَّ النَّبِيَّ ﷺ قَدْ فَعَلَهُ وَأَصْحَابُهُ، وَلَكِنْ كَرِهْتُ أَنْ يَظَلُّوا مُعَرِّسِينَ بِهِنَّ فِي الْأَرَاكِ، ثُمَّ يَرُوحُونَ فِي الْحَجِّ تَقْطُرُ رُؤُوسُهُمْ."],"en":["And in another narration in Muslim (1222), from Abu Musa: that he used to give verdicts allowing tamattu‘, so a man said to him: “Slow down concerning some of your rulings, for you do not know what the Commander of the Believers has newly decided concerning the rites after that.” Then later he met him and asked him, and ‘Umar said: I knew that the Prophet ﷺ had done it, and his Companions as well, but I disliked that they should remain with their wives under the arak trees, then go out for Hajj while water still dripped from their heads."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1559},{"key":"muslim","label":"مسلم","number":155}]},{"num":4917,"demo":false,"sanad":"","matn":["عن بكر - هو ابن عبد الله المزني - أَنَّهُ ذَكَرَ لابْنِ عُمَرَ أَنَّ أَنَسًا حَدَّثَهُمْ أَنَّ النَّبِيَّ ﷺ أَهَلَّ بِعُمْرَةٍ وَحَجَّةٍ، فَقَالَ: أَهَلَّ النَّبِيُّ ﷺ بِالْحَجِّ، وَأَهْلَلْنَا بِهِ مَعَهُ، فَلَمَّا قَدِمْنَا مَكَّةَ، قَالَ: (( مَنْ لَمْ يَكُنْ مَعَهُ هَدْيٌ فَلْيَجْعَلْهَا عُمْرَةً )). وَكَانَ مَعَ النَّبِيِّ ﷺ هَدْيٌ، فَقَدِمَ عَلَيْنَا عَلِيُّ بْنُ أَبِي طَالِبٍ مِنَ الْيَمَنِ حَاجًّا، فَقَالَ لَهُ النَّبِيُّ ﷺ: (( بِمَ أَهْلَلْتَ؟ )) قَالَ: بِمَا أَهَلَّ بِهِ النَّبِيُّ ﷺ."],"takhrij":"صحيح: رواه البخاري (٤٣٥٤، ٤٣٥٣).","grade":"صحيح","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (4354, 4353).","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Bakr — meaning Ibn ‘Abdullah al-Muzani — reported that he mentioned to Ibn ‘Umar that Anas had told them that the Prophet ﷺ entered ihram for Umrah and Hajj together. So he said: The Prophet ﷺ entered ihram for Hajj, and we entered ihram for it with him. Then when we came to Makkah, he said: “Whoever among you does not have sacrificial animals, let him make it an Umrah.” And the Prophet ﷺ had sacrificial animals with him. Then ‘Ali ibn Abi Talib came to us from Yemen as a pilgrim, and the Prophet ﷺ said to him: “With what did you enter ihram?” He said: With what the Prophet ﷺ entered ihram for."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4354}]},{"num":4918,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر، قالت: خَرَجْنَا مُحْرِمِينَ، فَقَالَ رَسُولُ اللَّهِ ﷺ: (( مَنْ كَانَ مَعَهُ هَدْيٌ فَلْيُقِمْ عَلَى إِحْرَامِهِ، وَمَنْ لَمْ يَكُنْ مَعَهُ هَدْيٌ فَلْيَحْلِلْ )). فَلَمْ يَكُنْ مَعِي هَدْيٌ فَحَلَلْتُ، وَكَانَ مَعَ الزُّبَيْرِ هَدْيٌ فَلَمْ يَحِلَّ. قَالَتْ: فَلَبِسْتُ ثِيَابِي، ثُمَّ خَرَجْتُ فَجَلَسْتُ إِلَى الزُّبَيْرِ، فَقَالَ: قُومِي عَنِّي."],"takhrij":"صحيح: رواه مسلم (١٢٣٦).","grade":"صحيح","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1236).","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: We went out in ihram, and the Messenger of Allah ﷺ said: “Whoever has sacrificial animals with him should remain in his ihram, and whoever does not have sacrificial animals with him should come out of ihram.” I did not have sacrificial animals with me, so I came out of ihram, while al-Zubayr had sacrificial animals with him, so he did not come out of ihram. She said: So I put on my clothes, then I went out and sat beside al-Zubayr, and he said: Move away from me."]},"buhuth":{"ar":["وروى ابن أبي شيبة في مصنفه (١٠٣/٤) قال عبد الله بن الزبير: أفردوا الحجّ، ودعوا قول أعمىكم هذا! قال عبد الله بن عباس: إن الذي أعمى الله قلبه لأنت، ألا تسأل أمك عن هذا؟! فأرسل إليها، فقالت: صَدَقَ ابن عباس، خرجنا مع رسول اللّٰه ﷺ حجاجًا، فجعلناها عمرة، فحللنا الإحلال كلَّه حتى سطعت المجامر بين الرجال والنساء.","وقوله: (( سطعت )) أي ارتفعت، أي تداولوها بينهم للتبخّر بها."],"en":["Ibn Abi Shaybah narrated in his Musannaf (4/103) that ‘Abdullah ibn al-Zubayr said: Make Hajj alone, and leave the statement of this blind man of yours. ‘Abdullah ibn ‘Abbas said: Rather, you are the one whose heart Allah has blinded. Why do you not ask your mother about this? So he sent to her, and she said: Ibn ‘Abbas spoke the truth. We went out with the Messenger of Allah ﷺ as pilgrims, then we made it Umrah, and we came out of ihram completely, until incense burners were raised among the men and women.","His statement, “sat‘at,” means they were raised up, meaning the incense burners were passed around among them for perfuming themselves."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1236}]},{"num":4919,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: كَانُوا يَرَوْنَ أَنَّ الْعُمْرَةَ فِي أَشْهُرِ الْحَجِّ مِنْ أَفْجَرِ الْفُجُورِ فِي الأَرْضِ، وَيَجْعَلُونَ الْمُحَرَّمَ صَفَرًا، وَيَقُولُونَ: إِذَا بَرَأَ الدَّبَرُ، وَعَفَا الأَثَرُ، وَانْسَلَخَ صَفَرُ، حَلَّتِ الْعُمْرَةُ لِمَنِ اعْتَمَرَ. فَقَدِمَ النَّبِيُّ ﷺ وَأَصْحَابُهُ صَبِيحَةَ رَابِعَةٍ مُهِلِّينَ بِالْحَجِّ، فَأَمَرَهُمْ أَنْ يَجْعَلُوهَا عُمْرَةً، فَتَعَاظَمَ ذَلِكَ عِنْدَهُمْ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أَيُّ الْحِلِّ؟ قَالَ: (( حِلٌّ كُلُّهُ ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٦٤)، ومسلم (١٢٤٠).","grade":"متفق عليه","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1564) and Muslim (1240).","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["Ibn ‘Abbas said: They used to regard Umrah during the months of Hajj as one of the gravest sins on earth, and they used to make Muharram into Safar, saying: When the camel sores heal, the traces disappear, and Safar has passed, then Umrah becomes lawful for the one who wishes to perform it. Then the Prophet ﷺ and his Companions arrived on the morning of the fourth, entering ihram for Hajj, and he ordered them to make it Umrah. That seemed very serious to them, so they said: O Messenger of Allah ﷺ, what kind of coming out of ihram? He said: “A complete coming out of ihram.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1564},{"key":"muslim","label":"مسلم","number":1240}]},{"num":4920,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: قَدِمَ النَّبِيُّ ﷺ وَأَصْحَابُهُ لِصُبْحِ رَابِعَةٍ يُلَبُّونَ بِالْحَجِّ، فَأَمَرَهُمْ أَنْ يَجْعَلُوهَا عُمْرَةً إِلَّا مَنْ مَعَهُ الْهَدْيُ."],"takhrij":"متفق عليه: رواه البخاري (١٠٨٥)، ومسلم (٢٠٢ :١٢٤٠). واللفظ للبخاري، ولفظ مسلم: (( أن يحوّلوا إحرامهم بعمرة إلا من كان معه الهدي )).","grade":"متفق عليه","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1085) and Muslim (1240/202). The wording is that of al-Bukhari. The wording of Muslim is: “That they should change their ihram into an Umrah, except for the one who had sacrificial animals with him.”","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas said: The Prophet ﷺ and his Companions arrived on the morning of the fourth while reciting the talbiyah for Hajj, and he ordered them to make it Umrah, except for those who had sacrificial animals with them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1085},{"key":"muslim","label":"مسلم","number":202}]},{"num":4921,"demo":false,"sanad":"","matn":["عن عكرمة، عن ابن عباس رضي الله عنهما، أنه سُئِلَ عن متعة الحج، فقال: أَهَلَّ الْمُهَاجِرُونَ وَالأَنْصَارُ وَأَزْوَاجُ النَّبِيِّ ﷺ فِي حَجَّةِ الْوَدَاعِ، وَأَهْلَلْنَا، فَلَمَّا قَدِمْنَا مَكَّةَ قَالَ رَسُولُ اللَّهِ ﷺ: (( اجْعَلُوا إِهْلالَكُمْ بِالْحَجِّ عُمْرَةً إِلَّا مَنْ قَلَّدَ الْهَدْيَ )). فَطُفْنَا بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، وَأَتَيْنَا النِّسَاءَ، وَلَبِسْنَا الثِّيَابَ، وَقَالَ: (( مَنْ قَلَّدَ الْهَدْيَ، فَإِنَّهُ لا يَحِلُّ لَهُ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ )). ثُمَّ أَمَرَنَا عَشِيَّةَ التَّرْوِيَةِ أَنْ نُهِلَّ بِالْحَجِّ، فَإِذَا فَرَغْنَا مِنَ الْمَنَاسِكِ جِئْنَا فَطُفْنَا بِالْبَيْتِ وَبِالصَّفَا وَالْمَرْوَةِ، فَقَدْ تَمَّ حَجُّنَا وَعَلَيْنَا الْهَدْيُ، كَمَا قَالَ اللَّهُ تَعَالَى: (فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ) إِلَى أَمْصَارِكُمْ. الشَّاةُ تُجْزِئُ، فَجَمَعُوا نُسُكَيْنِ فِي عَامٍ بَيْنَ الْحَجِّ وَالْعُمْرَةِ، فَإِنَّ اللَّهَ تَعَالَى أَنْزَلَهُ فِي كِتَابِهِ، وَسَنَّهُ نَبِيُّهُ ﷺ، وَأَبَاحَهُ لِلنَّاسِ غَيْرَ أَهْلِ مَكَّةَ. قَالَ اللَّهُ: (ذَٰلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ). وَأَشْهُرُ الْحَجِّ الَّتِي ذَكَرَ اللَّهُ تَعَالَى فِي كِتَابِهِ: شَوَّالٌ، وَذُو الْقَعْدَةِ، وَذُو الْحِجَّةِ، فَمَنْ تَمَتَّعَ فِي هَذِهِ الأَشْهُرِ فَعَلَيْهِ دَمٌ أَوْ صَوْمٌ، وَالرَّفَثُ: الْجِمَاعُ، وَالْفُسُوقُ: الْمَعَاصِي، وَالْجِدَالُ: الْمِرَاءُ."],"takhrij":"صحيح: ذكره البخاري (١٥٧٢) تعليقًا، ووصله أبو بكر الإسماعيلي - كما ذكر الحافظ في تغليق التعليق (٣/٦٢).","grade":"صحيح","chapter_ar":"باب أمر النبي ﷺ بمكة بفسخ الحج لمن لم يكن معه الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: mentioned by al-Bukhari (1572) in a suspended form, and connected by Abu Bakr al-Isma‘ili, as cited by al-Hafiz in Taghliq al-Ta‘liq (3/62).","chapter_en":"The Prophet’s command in Makkah to change Hajj into Umrah for whoever did not have sacrificial animals","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["‘Ikrimah narrated from Ibn ‘Abbas, may Allah be pleased with them both, that he was asked about tamattu‘ in Hajj, so he said: The Emigrants, the Helpers, and the wives of the Prophet ﷺ entered ihram in the Farewell Pilgrimage, and we entered ihram as well. Then when we came to Makkah, the Messenger of Allah ﷺ said: “Make your ihram for Hajj into an Umrah, except for the one who has garlanded the sacrificial animal.” So we circumambulated the House and went between al-Safa and al-Marwah, we went to our women, and we wore regular clothes. And he said: “Whoever has garlanded the sacrificial animal, it is not lawful for him to come out of ihram until the sacrificial animal reaches its place of slaughter.” Then on the evening before the Day of Tarwiyah he ordered us to enter ihram for Hajj. Then when we finished the rites, we came and circumambulated the House and went between al-Safa and al-Marwah, and our Hajj was complete, and the sacrificial offering was due from us, just as Allah Most High said: “Then whatever can be obtained with ease of sacrificial animals; and whoever cannot find one, then fasting three days during Hajj and seven when you return” to your homelands. One sheep suffices. Thus they combined two rites in one year: Hajj and Umrah. Allah Most High revealed it in His Book, His Prophet ﷺ established it as Sunnah, and He permitted it for the people other than the people of Makkah. Allah said: “That is for the one whose family are not residents near the Sacred Mosque.” And the months of Hajj that Allah mentioned in His Book are Shawwal, Dhu al-Qa‘dah, and Dhu al-Hijjah. So whoever performs tamattu‘ in these months must offer a sacrifice or fast. And “obscene speech” means sexual intercourse, “sinfulness” means acts of disobedience, and “argumentation” means disputation."]}},"tuhfa":{},"refs":[{"key":"ذکرہ_البخاری","label":"ذكره البخاري","number":1572},{"key":"وصلہ_ابو_بکر_الاسماعیلی_کما_ذکر_الحافظ/تغلیق_التعلیق","label":"وصله أبو بكر الإسماعيلي - كما ذكر الحافظ في تغليق التعليق","number":3}]},{"num":4922,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قال رسول اللّٰه ﷺ: (( هذه عمرةٌ استمتعنا بها، فمن لم يكن عنده الهدي فليحلَّ الحلَّ كلَّه، فإنَّ العمرة قد دخلت في الحجِّ إلى يوم القيامة ))."],"takhrij":"صحيح: رواه مسلم (١٢٤١).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1241).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said: “This is an Umrah that we have combined with Hajj. Whoever does not have a sacrificial animal with him should come out of ihram completely, for Umrah has entered into Hajj until the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1241}]},{"num":4923,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أَهَلَّ النبيُّ ﷺ بعمرةٍ، وأهلَّ أصحابُه بحجٍّ، فلم يَحِلَّ النبيُّ ﷺ ولا مَن ساق الهديَ من أصحابه، وحلَّ بقيتُهم، فكان طلحةُ بن عبيد الله ممَّن ساق الهدي فلم يَحِلَّ."],"takhrij":"صحيح: رواه مسلم (١٢٣٩).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1239).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ entered ihram for Umrah, and his Companions entered ihram for Hajj. The Prophet ﷺ did not come out of ihram, nor did those among his Companions who had brought sacrificial animals, while the rest of them did come out of ihram. Talhah ibn ‘Ubayd Allah was among those who had brought sacrificial animals, so he did not come out of ihram."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1239}]},{"num":4924,"demo":false,"sanad":"","matn":["عن ابن عباس، أنه كان يقول: لا يطوفُ بالبيت حاجٌّ ولا غيرُ حاجٍّ إلا حلَّ. قلتُ (أي ابن جريج) لعطاء: مِن أين يقول ذلك؟ قال: مِن قولِ الله تعالى: { ثُمَّ مَحِلُّهَا إِلَى الْبَيْتِ الْعَتِيقِ }. قال: قلتُ: فإنَّ ذلك بعدَ المُعَرَّفِ؟ فقال: كان ابن عباس يقول: هو بعد المُعَرَّفِ وقبلَهُ. وكان يأخذ ذلك من أمرِ النبيِّ ﷺ حين أمرهم أن يحلُّوا في حجَّة الوداع."],"takhrij":"متفق عليه: رواه البخاريّ (٤٣٩٦)، ومسلم (١٢٤٥). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4396) and Muslim (1245). The wording is that of Muslim.","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Abbas used to say: No one, whether a pilgrim or otherwise, circles the House except that he comes out of ihram. Ibn Jurayj said: I asked ‘Ata’: From where did he say that? He said: From the saying of Allah Most High: “Then their place of sacrifice is at the Ancient House.” I said: But is that not after standing at ‘Arafah? He said: Ibn ‘Abbas used to say: It is after standing at ‘Arafah and before it. And he took that from the command of the Prophet ﷺ when he ordered them to come out of ihram during the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4396},{"key":"muslim","label":"مسلم","number":1245}]},{"num":4925,"demo":false,"sanad":"","matn":["عن كريب مولى عبد الله بن عباس، عن عبد الله بن عباس، قال: قلت له: يا أبا العباس، أرأيتَ قولَك: ما حجَّ رجلٌ لم يسقِ الهديَ معه ثم طاف بالبيت إلا حلَّ بعمرة، وما طاف بها حاجٌّ قد ساق معه الهدي إلا اجتمعت له عمرةٌ وحجَّةٌ، والناس لا يقولون هذا؟ فقال: ويحك، إنَّ رسول اللّٰه ﷺ خرج ومَن معه من أصحابه لا يذكرون إلا الحج، فأمر رسول اللّٰه ﷺ من لم يكن معه الهدي أن يطوف بالبيت ويحلَّ بعمرة، فجعل الرجل منهم يقول: يا رسول الله، إنما هو الحج؟ فيقول رسول اللّٰه ﷺ: (( إنَّه ليس بالحج، ولكنها عمرة ))."],"takhrij":"حسن: رواه أحمد (٢٣٦٠).","grade":"حسن","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (2360).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Kurayb, the freedman of ‘Abdullah ibn ‘Abbas, narrated from ‘Abdullah ibn ‘Abbas that he said: I said to him: O Abu al-‘Abbas, what about your statement that no man who performs Hajj without bringing a sacrificial animal and then circumambulates the House except that he comes out of ihram as an Umrah pilgrim, and that no pilgrim who has brought a sacrificial animal circumambulates it except that Umrah and Hajj are joined together for him, while the people do not say this? He said: Woe to you. The Messenger of Allah ﷺ went out, and those with him among his Companions mentioned only Hajj. Then the Messenger of Allah ﷺ commanded whoever did not have a sacrificial animal with him to circumambulate the House and come out of ihram as an Umrah pilgrim. Then one of them would say: O Messenger of Allah ﷺ, it is only Hajj. So the Messenger of Allah ﷺ would say: “It is not Hajj only; rather, it is an Umrah.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":2360,"n":2360}]},{"num":4926,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: قدمنا مع رسول اللّٰه ﷺ ونحن نقول: لبيك اللهم لبيك بالحج، فأمرنا رسولُ اللّٰه ﷺ فجعلناها عمرةً."],"takhrij":"متفق عليه: رواه البخاري (١٥٧٠)، ومسلم (١٢١٦)، واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (1570) and Muslim (1216). The wording is that of al-Bukhari.","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: We arrived with the Messenger of Allah ﷺ saying: “Here I am, O Allah, here I am,” for Hajj. Then the Messenger of Allah ﷺ commanded us, and we made it into an Umrah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1570},{"key":"muslim","label":"مسلم","number":1216}]},{"num":4927,"demo":false,"sanad":"","matn":["عن جابر، قال: قدم النبيُّ ﷺ وأصحابُه صبحَ رابعةٍ من ذي الحجة مُهِلِّين بالحج لا يخلطهم شيء، فلما قدمنا أمرنا فجعلناها عمرةً، وأن نحلَّ إلى نسائنا، ففشت في ذلك القالة. قال عطاء: فقال جابر: فيروح أحدنا إلى منى وذكرُه يقطر منيًّا. فقال جابر بكفِّه. فبلغ ذلك النبيَّ ﷺ، فقام خطيبًا فقال: (( بلغني أنَّ أقوامًا يقولون كذا وكذا، واللهِ لأنا أبرُّ وأتقى لله منهم، ولو أني استقبلتُ من أمري ما استدبرتُ ما أهديتُ، ولولا أن معي الهدي لأحللتُ )). فقام سراقة بن مالك بن جعشم، فقال: يا رسول الله، هي لنا أو للأبد؟ فقال: (( لا، بل للأبد ))."],"takhrij":"صحيح: رواه البخاريّ (٢٥٠٥).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2505).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Jabir said: The Prophet ﷺ and his Companions arrived on the morning of the fourth of Dhu al-Hijjah entering ihram for Hajj alone, mixed with nothing else. When we arrived, he ordered us to make it into an Umrah and to come out of ihram for our wives, and talk about that spread among the people. ‘Ata’ said: Jabir said: One of us would go out to Mina while his private part was dripping semen. Jabir gestured with his hand. That reached the Prophet ﷺ, so he stood and addressed the people, saying: “It has reached me that some people are saying such-and-such. By Allah, I am more righteous and more mindful of Allah than they are. Had I known beforehand what I came to know later, I would not have brought sacrificial animals. And were it not that I have sacrificial animals with me, I would have come out of ihram.” Then Suraqah ibn Malik ibn Ju‘shum stood and said: O Messenger of Allah ﷺ, is this only for us, or forever? He said: “No, rather, it is forever.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2505}]},{"num":4928,"demo":false,"sanad":"","matn":["عن عطاء بن أبي رباح قال: سمعتُ جابر بن عبد الله في أناسٍ معه، قال: أَهْلَلْنَا أصحابَ رسولِ الله ﷺ في الحجِّ خالصًا ليس معه عمرةٌ. قال عطاء: قال جابر: فقدم النبيُّ ﷺ صبحَ رابعةٍ مضت من ذي الحجة، فلما قدمنا أمرنا النبيُّ ﷺ أن نحلَّ، وقال: (( أحلُّوا، وأصيبوا من النساء )). قال عطاء: قال جابر: ولم يعزم عليهم، ولكن أحلَّهُنَّ لهم. فبلغَهُ أنّا نقول: لما لم يكن بيننا وبين عرفة إلا خمسٌ أمرنا أن نحلَّ إلى نسائنا، فنأتي عرفة تقطر مذاكيرُنا المذيَ. قال: ويقول جابر بيده هكذا وحرَّكها. فقام رسولُ الله ﷺ فقال: (( قد علمتم أنّي أتقاكم لله، وأصدقكم، وأبرُّكم، ولولا هديي لحللتُ كما تحلُّون، فحلُّوا، فلو استقبلتُ من أمري ما استدبرتُ ما أهديتُ )). فحللنا وسمعنا وأطعنا.","وزاد مسلم: قال عطاء: قال جابر: فقدم عليٌّ من سعايته، فقال: (( بِمَ أَهْلَلْتَ؟ )). قال: بما أهلَّ به النبيُّ ﷺ. فقال له رسولُ الله ﷺ: (( فأهدِ وامكثْ حرامًا )). قال: وأهدى له عليٌّ هديًا، فقال سراقة بن مالك بن جعشم: يا رسول الله، ألعامِنا هذا أم لأبد؟ فقال: (( لأبد ))."],"takhrij":"متفق عليه: رواه البخاري (٧٣٦٧)، ومسلم (١٤١ :١٢١٦).","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (7367) and Muslim (1216/141).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["‘Ata’ ibn Abi Rabah said: I heard Jabir ibn ‘Abdullah among a group with him say: We, the Companions of the Messenger of Allah ﷺ, entered ihram for Hajj alone, with no Umrah joined to it. ‘Ata’ said: Jabir said: The Prophet ﷺ arrived on the morning of the fourth that had passed of Dhu al-Hijjah. When we arrived, the Prophet ﷺ ordered us to come out of ihram, and he said: “Come out of ihram and have relations with your wives.” ‘Ata’ said: Jabir said: He did not impose it on them as an obligation, but he made them lawful for them. Then it reached him that we were saying: Since there remain only five days between us and ‘Arafah, he orders us to come out of ihram for our wives, then we go to ‘Arafah while our private parts drip with madhy. Jabir motioned with his hand like this and moved it. Then the Messenger of Allah ﷺ stood and said: “You know that I am the most mindful of Allah among you, the most truthful among you, and the most righteous among you. Were it not for my sacrificial animals, I would have come out of ihram just as you do. So come out of ihram. If I had known beforehand what I came to know later, I would not have brought sacrificial animals.” So we came out of ihram, listened, and obeyed.","And Muslim adds: ‘Ata’ said: Jabir said: Then ‘Ali came from his assignment, and he said: “With what did you enter ihram?” He said: With what the Prophet ﷺ entered ihram for. The Messenger of Allah ﷺ said to him: “Then offer a sacrificial animal and remain in ihram.” He said: And ‘Ali brought a sacrificial animal for him. Then Suraqah ibn Malik ibn Ju‘shum said: O Messenger of Allah ﷺ, is this for this year of ours only or forever? He said: “Forever.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7367},{"key":"muslim","label":"مسلم","number":141}]},{"num":4929,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ حفصة زوج النبيِّ ﷺ قالت: يا رسول الله، ما شأنُ الناس حلُّوا ولم تحللْ أنتَ من عمرتك؟ قال: (( إنّي لبَّدتُ رأسي، وقلَّدتُ هديي، فلا أحلُّ حتى أنحر ))."],"takhrij":"متفق عليه: رواه مالك (١٨٠) والبخاري (١٥٦٦) ومسلم (١٢٢٩).","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (180), al-Bukhari (1566), and Muslim (1229).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Umar narrated that Hafsah, the wife of the Prophet ﷺ, said: O Messenger of Allah ﷺ, why is it that the people have come out of ihram while you have not come out of ihram from your Umrah? He said: “I have matted my hair and garlanded my sacrificial animals, so I will not come out of ihram until I slaughter.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":180},{"key":"bukhari","label":"البخاري","number":1566},{"key":"muslim","label":"مسلم","number":1229}]},{"num":4930,"demo":false,"sanad":"","matn":["عن أبي سعيد، قال: خرجنا مع رسولِ اللّٰه ﷺ نصرخ بالحجِّ صراخًا، فلما قدمنا مكة أمرنا أن نجعلها عمرةً إلا من ساق الهدي، فلما كان يوم التروية ورحنا إلى منى أهللنا بالحجِّ."],"takhrij":"صحيح: رواه مسلم (١٢٤٧).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1247).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Abu Sa‘id said: We went out with the Messenger of Allah ﷺ loudly proclaiming Hajj. When we arrived in Makkah, he ordered us to make it into an Umrah, except for the one who had brought sacrificial animals. Then when the Day of Tarwiyah came and we went to Mina, we entered ihram for Hajj."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1247}]},{"num":4931,"demo":false,"sanad":"","matn":["عن سراقة بن جُعشم، قال: قام رسولُ اللّٰه ﷺ خطيبًا في هذا الوادي فقال: (( ألا إنَّ العمرة قد دخلتْ في الحجِّ إلى يوم القيامة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٩٧٧)، والنسائي (٢٨٠٦)، واللفظ لابن ماجه.","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2977) and al-Nasa’i (2806). The wording is that of Ibn Majah.","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Suraqah ibn Ju‘shum said: The Messenger of Allah ﷺ stood addressing the people in this valley and said: “Indeed, Umrah has entered into Hajj until the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2977},{"key":"nasai","label":"النسائي","number":2806}]},{"num":4932,"demo":false,"sanad":"","matn":["عن الرَّبيع بن سبرة، عن أبيه، قال: خرجنا مع رسولِ اللّٰه ﷺ حتى إذا كان بعُسفان قال له سراقة بن مالك المُدلجي: يا رسول الله، اقضِ لنا قضاءَ قومٍ كأنما وُلِدوا اليوم. فقال: (( إنَّ الله تعالى قد أدخل عليكم في حجِّكم هذا عمرةً، فإذا قدمتم فمَن تطوَّف بالبيت وبين الصفا والمروة فقد حلَّ، إلا مَن كان معه هديٌ ))."],"takhrij":"صحيح: رواه أبو داود (١٨٠١)، وعبد الرزاق (١٤٠٤١)، والإمام أحمد (١٥٣٤٥).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (1801), ‘Abd al-Razzaq (14041), and Ahmad (15345).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Al-Rabi‘ ibn Sabrah narrated from his father, who said: We went out with the Messenger of Allah ﷺ until, when we were at ‘Usfan, Suraqah ibn Malik al-Mudliji said to him: O Messenger of Allah ﷺ, give us a ruling like the ruling for a people as though they were born today. So he said: “Allah the Exalted has entered an Umrah into this Hajj of yours. So when you arrive, whoever circumambulates the House and goes between al-Safa and al-Marwah has come out of ihram, except for the one who has a sacrificial animal with him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1801},{"key":"عبد_الرزاق","label":"عبد الرزاق","number":14041},{"key":"الامام_احمد","label":"الإمام أحمد","number":15345},{"key":"ahmad","label":"مسند الإمام أحمد","number":15345,"n":15345}]},{"num":4933,"demo":false,"sanad":"","matn":["عن البراء بن عازب قال: كُنْتُ مَعَ عَلِيٍّ حِينَ أَمَّرَهُ رَسُولُ اللّٰهِ ﷺ عَلَى الْيَمَنِ، قَالَ: فَأَصَبْتُ مَعَهُ أَوَاقِيَ، فَلَمَّا قَدِمَ عَلِيٌّ مِنَ الْيَمَنِ عَلَى رَسُولِ اللّٰهِ ﷺ قَالَ: وَجَدْتُ فَاطِمَةَ رَضِيَ اللّٰهُ عَنْهَا قَدْ لَبِسَتْ ثِيَابًا صَبِيغًا، وَقَدْ نَضَحَتِ الْبَيْتَ بِنَضُوحٍ، فَقَالَتْ: مَا لَكَ؟ فَإِنَّ رَسُولَ اللّٰهِ ﷺ قَدْ أَمَرَ أَصْحَابَهُ فَأَحَلُّوا.","قَالَ: قُلْتُ لَهَا: إِنِّي أَهْلَلْتُ بِإِهْلَالِ النَّبِيِّ ﷺ.","قَالَ: فَأَتَيْتُ النَّبِيَّ ﷺ فَقَالَ لِي: (( كَيْفَ صَنَعْتَ؟ )).","فَقَالَ: قُلْتُ: أَهْلَلْتُ بِإِهْلَالِ النَّبِيِّ ﷺ.","قَالَ: (( فَإِنِّي قَدْ سُقْتُ الْهَدْيَ وَقَرَنْتُ )).","قَالَ: فَقَالَ لِي: (( انْحَرْ مِنَ الْبُدْنِ سَبْعًا وَسِتِّينَ أَوْ سِتًّا وَسِتِّينَ، وَأَمْسِكْ لِنَفْسِكَ ثَلَاثًا وَثَلَاثِينَ أَوْ أَرْبَعًا وَثَلَاثِينَ، وَأَمْسِكْ لِي مِنْ كُلِّ بَدَنَةٍ مِنْهَا بَضْعَةً ))."],"takhrij":"حسن: رواه أبو داود (١٧٩٧)، والنسائيّ (٢٧٤٥).","grade":"حسن","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1797) and al-Nasa’i (2745).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: I was with ‘Ali when the Messenger of Allah ﷺ appointed him over Yemen. He said: I acquired some awqiyah with him. When ‘Ali came from Yemen to the Messenger of Allah ﷺ, he said: I found Fatimah, may Allah be pleased with her, wearing dyed clothes and having perfumed the house. She said: What is the matter with you? The Messenger of Allah ﷺ had commanded his companions to exit ihram, and they did so.","He said: I told her, “I entered ihram with the same intention as the Prophet ﷺ.”","He said: So I came to the Prophet ﷺ, and he said to me, “What did you do?”","He said: I replied, “I entered ihram with the same intention as the Prophet ﷺ.”","He said: “I have brought the sacrificial animals and have combined Hajj and Umrah.”","He said: Then he said to me: “Slaughter sixty-seven or sixty-six of the camels, keep thirty-three or thirty-four for yourself, and keep for me a piece from each camel.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1797},{"key":"nasai","label":"النسائيّ","number":2745}]},{"num":4934,"demo":false,"sanad":"","matn":["عن عمران بن حصين، قال: أُنزِلَتْ آيَةُ الْمُتْعَةِ فِي كِتَابِ اللَّهِ فَفَعَلْنَاهَا مَعَ رَسُولِ اللَّهِ ﷺ، وَلَمْ يُنْزَلْ قُرْآنٌ يُحَرِّمُهُ، وَلَمْ يَنْهَ عَنْهَا حَتَّى مَاتَ، قَالَ رَجُلٌ بِرَأْيِهِ مَا شَاءَ."],"takhrij":"متفق عليه: رواه البخاريّ (٤٥١٨)، ومسلم (١٧٢:١٢٢٦)، واللفظ للبخاريّ. وفي لفظ مسلم: (( ثُمَّ لَمْ تَنْزِلْ آيَةٌ تَنْسَخُ آيَةَ مُتْعَةِ الْحَجِّ )). وفي الصحيحين أيضًا: البخاري (١٥٧١)، ومسلم (١٧:١٢٢٦)، عن عمران بن حصين، قال: (( تَمَتَّعْنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ﷺ، فَنَزَلَ الْقُرْآنُ، قَالَ رَجُلٌ بِرَأْيِهِ مَا شَاءَ )).","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4518) and Muslim (1226:172), and this wording is that of al-Bukhari. In the wording of Muslim: “Then no verse was revealed abrogating the verse of tamattu‘ in Hajj.” In the two Sahihs as well: al-Bukhari (1571) and Muslim (1226:17), from ‘Imran ibn Husayn, who said: “We performed tamattu‘ during the time of the Messenger of Allah ﷺ, and the Qur’an was revealed; then a man said whatever he wished based on his own opinion.”","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["‘Imran ibn Husayn said: The verse of tamattu‘ was revealed in the Book of Allah, and we practiced it with the Messenger of Allah ﷺ. No Qur’an was revealed to forbid it, and he did not forbid it until he died. Then a man said whatever he wished based on his own opinion."]},"buhuth":{"ar":["وقوله: (( قال رجل برأيه ما شاء )) يقصد به عمر بن الخطاب، فإنه كان ينهى عن المتعة اجتهادًا."],"en":["His statement, “Then a man said whatever he wished based on his own opinion,” refers to ‘Umar ibn al-Khattab, for he used to discourage tamattu‘ as a matter of juristic judgment."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4518},{"key":"muslim","label":"مسلم","number":172},{"key":"bukhari","label":"البخاري","number":1571},{"key":"muslim","label":"مسلم","number":17}]},{"num":4935,"demo":false,"sanad":"","matn":["عن مروان بن الحكم، قال: شَهِدْتُ عُثْمَانَ وَعَلِيًّا رَضِيَ اللَّهُ عَنْهُمَا، وَعُثْمَانُ يَنْهَى عَنِ الْمُتْعَةِ وَأَنْ يُجْمَعَ بَيْنَهُمَا، فَلَمَّا رَأَى عَلِيٌّ أَهَلَّ بِهِمَا: لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ، قَالَ: مَا كُنْتُ لِأَدَعَ سُنَّةَ النَّبِيِّ ﷺ لِقَوْلِ أَحَدٍ."],"takhrij":"متفق عليه: رواه البخاري (١٥٦٣) والبخاري أيضًا (١٥٦٩)، ومسلم (١٢٢٣). وفيه: اجتمع عليٌّ وعثمان رضي اللّٰه عنهما بعسفان، فكان عثمان ينهى عن المتعة أو العمرة. فقال عليٌّ: ما تريد إلى أمر فعله رسول الله ﷺ تنهى عنه؟! فقال عثمان: دعنا منك. فقال: إني لا أستطيع أن أدعك. فلما أن رأى عليٌّ ذلك أهلَّ بهما جميعًا. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1563), also by al-Bukhari (1569), and Muslim (1223). In it: ‘Ali and ‘Uthman, may Allah be pleased with them, met at ‘Usfan, and ‘Uthman was discouraging tamattu‘ or Umrah. ‘Ali said: “Why do you oppose something the Messenger of Allah ﷺ did?” ‘Uthman said: “Leave us alone.” ‘Ali said: “I cannot leave you alone.” When ‘Ali saw that, he entered ihram for both together. This is the wording of Muslim.","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Marwan ibn al-Hakam said: I witnessed ‘Uthman and ‘Ali, may Allah be pleased with them both, while ‘Uthman was discouraging tamattu‘ and combining the two rites. When ‘Ali saw that, he entered ihram for both, saying: “Here I am for Umrah and Hajj.” He said: “I would never abandon the Sunnah of the Prophet ﷺ for the statement of anyone.”"]},"buhuth":{"ar":["ورواه مسلم أيضًا وفيه: كان عثمان ينهى عن المتعة، وكان عليٌّ يأمر بها، فقال عثمان لعليّ كلمة، ثم قال عليٌّ: لقد علمتَ أنّا قد تمتعنا مع رسول اللّٰه ﷺ؟ فقال: أجل، ولكنّا كنّا خائفين."],"en":["Muslim also narrated that ‘Uthman was discouraging tamattu‘ while ‘Ali used to command it. Then ‘Uthman said something to ‘Ali, and ‘Ali replied: “You certainly know that we performed tamattu‘ with the Messenger of Allah ﷺ.” He said: “Yes, but at that time we were afraid.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1563},{"key":"البخاری_ایضا","label":"البخاري أيضًا","number":1569},{"key":"muslim","label":"مسلم","number":1223}]},{"num":4936,"demo":false,"sanad":"","matn":["عن نصر بن عمران أبي جمرة الضُّبَعي، قال: تَمَتَّعْتُ فَنَهَانِي نَاسٌ عَنْ ذَلِكَ، فَأَتَيْتُ ابْنَ عَبَّاسٍ فَسَأَلْتُهُ عَنْ ذَلِكَ فَأَمَرَنِي بِهَا.","قَالَ: ثُمَّ انْطَلَقْتُ إِلَى الْبَيْتِ فَنِمْتُ، فَأَتَانِي آتٍ فِي مَنَامِي، فَقَالَ: عُمْرَةٌ مُتَقَبَّلَةٌ وَحَجٌّ مَبْرُورٌ.","قَالَ: فَأَتَيْتُ ابْنَ عَبَّاسٍ فَأَخْبَرْتُهُ بِالَّذِي رَأَيْتُ، فَقَالَ: اللَّهُ أَكْبَرُ! اللَّهُ أَكْبَرُ! سُنَّةُ أَبِي الْقَاسِمِ ﷺ."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٦٧)، ومسلم (١٢٤٢). واللفظ لمسلم، ولفظ البخاري نحوه، وزاد: (( فقال لي: أَقِمْ عندي فأجعل لك سهمًا من مالي )). قال شعبة: فقلتُ: لِمَ؟ فقال: للرؤيا التي رأيتُ.","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1567) and Muslim (1242). This wording is that of Muslim. The wording of al-Bukhari is similar, with the addition: “He said to me: Stay with me and I will assign you a share from my wealth.” Shu‘bah said: I asked, “Why?” He replied: “Because of the dream that you saw.”","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Nasr ibn ‘Imran Abu Jamrah al-Duba‘i said: I performed tamattu‘, and some people forbade me from doing that. So I went to Ibn ‘Abbas and asked him about it, and he instructed me to do it.","He said: Then I went to the House and slept, and someone came to me in my dream and said: “An accepted Umrah and a blessed Hajj.”","He said: So I went to Ibn ‘Abbas and informed him of what I had seen, and he said: “Allah is the Greatest! Allah is the Greatest! This is the Sunnah of Abu al-Qasim ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1567},{"key":"muslim","label":"مسلم","number":1242}]},{"num":4937,"demo":false,"sanad":"","matn":["عن مسلم القُرِّيِّ، قال: سَأَلْتُ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا عَنْ مُتْعَةِ الْحَجِّ، فَرَخَّصَ فِيهَا، وَكَانَ ابْنُ الزُّبَيْرِ يَنْهَى عَنْهَا، فَقَالَ: هَذِهِ أُمُّ ابْنِ الزُّبَيْرِ تُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ﷺ رَخَّصَ فِيهَا، فَادْخُلُوا عَلَيْهَا فَاسْأَلُوهَا.","قَالَ: فَدَخَلْنَا عَلَيْهَا، فَإِذَا امْرَأَةٌ ضَخْمَةٌ عَمْيَاءُ، فَقَالَتْ: قَدْ رَخَّصَ رَسُولُ اللَّهِ ﷺ فِيهَا."],"takhrij":"صحيح: رواه مسلم (١٢٣٨).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (1238).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Muslim al-Qurri said: I asked Ibn ‘Abbas, may Allah be pleased with them both, about tamattu‘ in Hajj, and he allowed it, while Ibn al-Zubayr used to forbid it. So he said: “This is the mother of Ibn al-Zubayr narrating that the Messenger of Allah ﷺ permitted it. Go in to her and ask her.”","He said: So we went in to her, and there she was, a large blind woman, and she said: “The Messenger of Allah ﷺ did indeed permit it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1238}]},{"num":4938,"demo":false,"sanad":"","matn":["عن غُنَيْمِ بْنِ قَيْسٍ، قال: سَأَلْتُ سَعْدَ بْنَ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ عَنِ الْمُتْعَةِ؟ فَقَالَ: فَعَلْنَاهَا وَهَذَا يَوْمَئِذٍ كَافِرٌ بِالْعُرُشِ - يَعْنِي بُيُوتَ مَكَّةَ -."],"takhrij":"صحيح: رواه مسلم (١٢٢٥).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Sahih: Narrated by Muslim (1225).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Ghunaym ibn Qays said: I asked Sa‘d ibn Abi Waqqas, may Allah be pleased with him, about tamattu‘. He said: “We did it while this man at that time was still a disbeliever among the shelters,” meaning the houses of Makkah."]},"buhuth":{"ar":["قوله: (( عن المتعة )) يعني المتعة في الحج - كما في رواية -، والمراد بالحج هنا: العمرة؛ لأنهم كانوا يطلقون الحج على العمرة.","وقوله: (( وهذا يومئذ كافر بالعُرُش )) العُرُش - بضم العين والراء -: وهي بيوت مكة كما فُسِّر في الرواية.","قال أبو عبيد: (( سُمِّيَتْ بُيُوتُ مَكَّةَ عُرُوشًا؛ لِأَنَّهَا عِيدَانٌ تُنْصَبُ وَتُظَلَّلُ )).","قال النووي: (( والإشارة بهذا إلى معاوية بن أبي سفيان، والمراد: أنّا تمتعنا ومعاوية يومئذ كافر على دين الجاهلية مقيم بمكة. والمراد بالمتعة العمرة التي كانت سنة سبع من الهجرة، وهي عمرة القضاء، وكان معاوية يومئذ كافرًا، وإنما أسلم بعد ذلك عام الفتح سنة ثمان، وقيل: إنه أسلم بعد عمرة القضاء سنة سبع، والصحيح الأول. وأما غير هذه العمرة من عمر النبي ﷺ فلم يكن معاوية فيها كافرًا ولا مقيمًا بمكة، بل كان معه ﷺ )). قال: (( وفي هذا الحديث جواز المتعة في الحج )). انظر شرح مسلم (٨/٢٠٣-٢٠٤)."],"en":["His statement, “about tamattu‘,” means tamattu‘ in Hajj, as mentioned in another narration; here, however, Hajj refers to Umrah, because they would sometimes use the word Hajj to refer to Umrah.","His statement, “while this man at that time was still a disbeliever among the shelters,” means the houses of Makkah, as explained in the narration.","Abu ‘Ubayd said: “The houses of Makkah were called ‘urush because they were made of poles that were erected and shaded over.”","Al-Nawawi said: “The reference here is to Mu‘awiyah ibn Abi Sufyan. The meaning is: we performed tamattu‘ while Mu‘awiyah at that time was still a disbeliever upon the religion of the pre-Islamic period and residing in Makkah. What is meant by tamattu‘ here is the Umrah that occurred in the seventh year after migration, namely the make-up Umrah. Mu‘awiyah was a disbeliever at that time, and he only accepted Islam later in the year of the Conquest, year eight. It was also said that he accepted Islam after the make-up Umrah in year seven, but the first view is the correct one. As for the other ‘umrahs of the Prophet ﷺ, Mu‘awiyah was neither a disbeliever nor residing in Makkah during them; rather, he was with the Prophet ﷺ.” He also said: “This hadith proves the permissibility of tamattu‘ in Hajj.” See Sharh Muslim (8/203–204)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1225}]},{"num":4939,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبيِّ ﷺ قال: (( وَالَّذِي نَفْسِي بِيَدِهِ! لَيُهِلَّنَّ ابْنُ مَرْيَمَ بِفَجِّ الرَّوْحَاءِ حَاجًّا أَوْ مُعْتَمِرًا أَوْ لَيَثْنِيَنَّهُمَا ))."],"takhrij":"صحيح: رواه مسلم (١٢٥٢).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة للناس جميعًا إلى يوم القيامة لمن لم يسق الهدي، وأنه لم يُنسخ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1252).","chapter_en":"Those who said that changing Hajj into Umrah applies to all people until the Day of Resurrection for whoever did not bring sacrificial animals, and that it was not abrogated","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “By the One in whose Hand is my soul, the son of Mary will certainly enter the mountain pass of al-Rawha’ proclaiming the pilgrimage, or the lesser pilgrimage, or he will combine the two.”"]},"buhuth":{"ar":["قوله: (( لَيَثْنِيَنَّهُمَا )) هو بفتح الياء في أوله، معناه: يقرن بينهما، وهذا يكون بعد نزول عيسى عليه السلام من السماء في آخر الزمان. وأما فَجُّ الرَّوحاء فبفتح الفاء وتشديد الجيم، قال الحافظ أبو بكر الحازمي: موضع بين مكة والمدينة، قال: وكان طريق رسول الله ﷺ إلى بدر وإلى مكة عام الفتح، وعام حجة الوداع. انظر: شرح النووي على مسلم (٨/٢٣٣)."],"en":["His statement, “or he will combine the two,” means that he will combine the pilgrimage and the lesser pilgrimage together. This will happen after Jesus, peace be upon him, descends from heaven near the end of time. As for the pass of al-Rawha’, it is a place between Mecca and Medina. Abu Bakr al-Hazimi said it was on the route of the Messenger of Allah ﷺ to Badr, to Mecca in the year of the Conquest, and in the Farewell Pilgrimage. See al-Nawawi’s commentary on Muslim (8/233)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1252}]},{"num":4940,"demo":false,"sanad":"","matn":["عن محمد بن عبد الرحمن بن نوفل القرشي، أنه سأل عروة بن الزبير، فقال: قَدْ حَجَّ النَّبِيُّ ﷺ فَأَخْبَرَتْنِي عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا أَنَّهُ أَوَّلُ شَيْءٍ بَدَأَ بِهِ حِينَ قَدِمَ أَنَّهُ تَوَضَّأَ ثُمَّ طَافَ بِالْبَيْتِ، ثُمَّ لَمْ تَكُنْ عُمْرَةً، ثُمَّ حَجَّ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ فَكَانَ أَوَّلَ شَيْءٍ بَدَأَ بِهِ الطَّوَافُ بِالْبَيْتِ، ثُمَّ لَمْ تَكُنْ عُمْرَةً، ثُمَّ عُمَرُ رَضِيَ اللَّهُ عَنْهُ مِثْلُ ذَلِكَ، ثُمَّ حَجَّ عُثْمَانُ رَضِيَ اللَّهُ عَنْهُ فَرَأَيْتُهُ أَوَّلَ شَيْءٍ بَدَأَ بِهِ الطَّوَافُ بِالْبَيْتِ، ثُمَّ لَمْ تَكُنْ عُمْرَةً، ثُمَّ مُعَاوِيَةُ وَعَبْدُ اللَّهِ بْنُ عُمَرَ، ثُمَّ حَجَجْتُ مَعَ أَبِي الزُّبَيْرِ بْنِ الْعَوَّامِ فَكَانَ أَوَّلَ شَيْءٍ بَدَأَ بِهِ الطَّوَافُ بِالْبَيْتِ، ثُمَّ لَمْ تَكُنْ عُمْرَةً، ثُمَّ رَأَيْتُ الْمُهَاجِرِينَ وَالْأَنْصَارَ يَفْعَلُونَ ذَلِكَ، ثُمَّ لَمْ تَكُنْ عُمْرَةً، ثُمَّ آخِرُ مَنْ رَأَيْتُ فَعَلَ ذَلِكَ ابْنُ عُمَرَ، ثُمَّ لَمْ يَنْقُضْهَا عُمْرَةً، وَهَذَا ابْنُ عُمَرَ عِنْدَهُمْ فَلَا يَسْأَلُونَهُ، وَلَا أَحَدٌ مِمَّنْ مَضَى مَا كَانُوا يَبْدَؤُونَ بِشَيْءٍ حَتَّى يَضَعُوا أَقْدَامَهُمْ مِنَ الطَّوَافِ بِالْبَيْتِ، ثُمَّ لَا يَحِلُّونَ، وَقَدْ رَأَيْتُ أُمِّي وَخَالَتِي حِينَ تَقْدَمَانِ لَا تَبْتَدِئَانِ بِشَيْءٍ أَوَّلَ مِنَ الْبَيْتِ تَطُوفَانِ بِهِ، ثُمَّ إِنَّهُمَا لَا تَحِلَّانِ، وَقَدْ أَخْبَرَتْنِي أُمِّي أَنَّهَا أَهَلَّتْ هِيَ وَأُخْتُهَا وَالزُّبَيْرُ وَفُلَانٌ وَفُلَانٌ بِعُمْرَةٍ، فَلَمَّا مَسَحُوا الرُّكْنَ حَلُّوا."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٤١)، ومسلم (١٢٣٥). وهذا لفظ البخاريّ.","grade":"متفق عليه","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة كان خاصًّا لأصحاب رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1641) and Muslim (1235). This is the wording of al-Bukhari.","chapter_en":"Those who said that changing Hajj into ʿUmrah was specific to the Companions of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Muhammad ibn ‘Abd al-Rahman ibn Nawfal al-Qurashi reported that he asked ‘Urwah ibn al-Zubayr, and he said: The Prophet ﷺ performed the pilgrimage, and ‘A’ishah, may Allah be pleased with her, informed me that the first thing he began with when he arrived was that he performed ablution, then circled the House, and that was not a lesser pilgrimage. Then Abu Bakr, may Allah be pleased with him, performed the pilgrimage, and the first thing he began with was circling the House, and that was not a lesser pilgrimage. Then ‘Umar, may Allah be pleased with him, did the same. Then ‘Uthman, may Allah be pleased with him, performed the pilgrimage, and I saw that the first thing he began with was circling the House, and that was not a lesser pilgrimage. Then Mu‘awiyah and ‘Abd Allah ibn ‘Umar did the same. Then I performed the pilgrimage with my father al-Zubayr ibn al-‘Awwam, and the first thing he began with was circling the House, and that was not a lesser pilgrimage. Then I saw the Emigrants and the Helpers doing that, and that was not a lesser pilgrimage. Then the last person I saw doing that was Ibn ‘Umar, and he did not turn it into a lesser pilgrimage. And here is Ibn ‘Umar among them, yet they do not ask him. No one from those who passed before would begin with anything before placing their feet in the circling of the House, then they would not exit the state of consecration. I also saw my mother and my aunt, when they arrived, not begin with anything before the House, circling it, and then they did not exit the state of consecration. My mother informed me that she, her sister, al-Zubayr, and so-and-so and so-and-so had entered consecration for the lesser pilgrimage, and when they touched the Corner, they exited the state of consecration."]},"intro":{"ar":["قال تعالى: ( وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ) [سورة البقرة: ١٩٦].","فالله تعالى يأمر بإتمام الحج والعمرة، وثبت من السنة المتواترة أن النبي ﷺ أمر بفسخ الحج إلى العمرة، فدفعًا للتعارض بين الآية وقول النبي ﷺ قالوا: هذا خاصٌّ لأصحاب النبي ﷺ، ويبقى إتمام الحج والعمرة لغيرهم إلى يوم القيامة، ويدل عليه عمل الخلفاء الراشدين غير علي بن أبي طالب، ومن بعدهم من التابعين ومن تبعهم إلى يوم الدين. وقالوا: إن السبب في ذلك أنهم كانوا في الجاهلية يعتقدون أن التمتع بالعمرة إلى الحج من أفجر الفجور، فأمرهم النبي ﷺ بفسخ الحج إلى العمرة ليبيّن جواز العمرة في أشهر الحج، وقد حصلت معرفة ذلك، فلا حاجة بعد ذلك إلى الفسخ. ولكن التمتع رخصة للمبتدئ بها توفيقًا بين أقاويل الصحابة. ولولا علمهم بأن ذلك خاصٌّ بالركب الذين كانوا مع النبي ﷺ لم يقدموا على تغيير حكم الشريعة، ولم يطاوعهم المسلمون على ذلك، ولا يجوز لمسلم أن يظن بهم ذلك. انظر: “شرح العمدة” (١/٤٩٦)."],"en":["Allah Most High said: “Complete the pilgrimage and the lesser pilgrimage for Allah.” [Surat al-Baqarah: 196]","Allah commands the completion of the pilgrimage and the lesser pilgrimage, and it is established by widely transmitted prophetic reports that the Prophet ﷺ ordered people to change the pilgrimage into the lesser pilgrimage. To reconcile the verse with the statement of the Prophet ﷺ, some scholars said that this was specific to the Companions of the Prophet ﷺ, while completing the pilgrimage and the lesser pilgrimage remains the rule for others until the Day of Resurrection. They cited as evidence the practice of the Rightly Guided Caliphs other than ‘Ali ibn Abi Talib, and those after them among the Followers and those who followed them. They also said that the reason was that in the pre-Islamic period people believed that combining the lesser pilgrimage with the pilgrimage in the pilgrimage months was one of the gravest wrongs, so the Prophet ﷺ ordered them to change the pilgrimage into the lesser pilgrimage in order to show that the lesser pilgrimage during the pilgrimage months is permissible. Once that became well known, there was no longer a need for that change. But beginning with the lesser pilgrimage and then continuing to the pilgrimage remains a concession, in order to harmonize the different statements of the Companions. Had they not known that this was specific to the group that was with the Prophet ﷺ, they would not have ventured to alter a ruling of the Sacred Law, nor would the Muslims have followed them in that. It is not permissible for a Muslim to think ill of them in that regard. See “Sharh al-‘Umdah” (1/496)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1641},{"key":"muslim","label":"مسلم","number":1235}]},{"num":4941,"demo":false,"sanad":"","matn":["عن أبي ذرٍّ قال: كانت المتعة في الحجِّ لأصحاب محمد ﷺ خاصّةً."],"takhrij":"صحيح: رواه مسلم (١٢٢٤).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة كان خاصًّا لأصحاب رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1224).","chapter_en":"Those who said that changing Hajj into ʿUmrah was specific to the Companions of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Abu Dharr said: The concession connected to combining the lesser pilgrimage with the pilgrimage was specifically for the Companions of Muhammad ﷺ."]},"buhuth":{"ar":["قوله: (( كانت المتعة في الحج )) أي فسخ الحج إلى العمرة، وإلا فأصل المتعة في كتاب الله.","قال الأثرم في “سنته”: وذكر لنا أحمد بن حنبل أن عبد الرحمن بن مهدي حدّثه عن سفيان، عن الأعمش، عن إبراهيم التيمي، عن أبيه، عن أبي ذرٍّ: (( كانت لنا خاصّةً )). فقال أحمد بن حنبل: رحم الله أبا ذر، هي في كتاب الله: ( فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ ) [سورة البقرة: ١٩٦]. انظر: “زاد المعاد” (٢/١٩٤)."],"en":["His statement, “the concession connected to the pilgrimage,” means changing the pilgrimage into the lesser pilgrimage. Otherwise, the basis of beginning with the lesser pilgrimage and then continuing to the pilgrimage is found in the Book of Allah.","Al-Athram said in his “Sunan”: Ahmad ibn Hanbal told us that ‘Abd al-Rahman ibn Mahdi narrated to him from Sufyan, from al-A‘mash, from Ibrahim al-Taymi, from his father, from Abu Dharr: “It was specifically for us.” Ahmad ibn Hanbal then said: “May Allah have mercy on Abu Dharr. It is in the Book of Allah: ‘Whoever enjoys the lesser pilgrimage until the pilgrimage…’” [Surat al-Baqarah: 196]. See “Zad al-Ma‘ad” (2/194)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1224}]},{"num":4942,"demo":false,"sanad":"","matn":["عن أبي ذرٍّ الغفاري، قال: لا تصلح المتعتان إلا لنا خاصّةً - يعني متعة الحجِّ ومتعة النساء -."],"takhrij":"صحيح: رواه مسلم (١٦٢:١٢٢٤).","grade":"صحيح","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة كان خاصًّا لأصحاب رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1224:162).","chapter_en":"Those who said that changing Hajj into ʿUmrah was specific to the Companions of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Abu Dharr al-Ghifari said: The two temporary permissions were only suitable for us specifically — meaning the temporary combining in pilgrimage and temporary marriage."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":162}]},{"num":4943,"demo":false,"sanad":"","matn":["عن أبي نضرة، قال: كَانَ ابْنُ عَبَّاسٍ يَأْمُرُ بِالْمُتْعَةِ، وَكَانَ ابْنُ الزُّبَيْرِ يَنْهَى عَنْهَا. قَالَ: فَذَكَرْتُ ذَلِكَ لِجَابِرِ بْنِ عَبْدِ اللَّهِ، فَقَالَ: عَلَى يَدَيَّ دَارَ الْحَدِيثُ، تَمَتَّعْنَا مَعَ رَسُولِ اللَّهِ ﷺ، فَلَمَّا قَامَ عُمَرُ قَالَ: إِنَّ اللَّهَ كَانَ يُحِلُّ لِرَسُولِهِ مَا شَاءَ بِمَا شَاءَ، وَإِنَّ الْقُرْآنَ قَدْ نَزَلَ مَنَازِلَهُ، فَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ كَمَا أَمَرَكُمُ اللَّهُ، وَأَبِتُّوا نِكَاحَ هَذِهِ النِّسَاءِ، فَلَنْ أُوتَى بِرَجُلٍ نَكَحَ امْرَأَةً إِلَى أَجَلٍ إِلَّا رَجَمْتُهُ بِالْحِجَارَةِ."],"takhrij":"ورواه مسلم أيضاً (١٢٤٩) عن أبي نضرة، قال: كنت عند جابر بن عبد الله، فأتاه آتٍ فقال: إن ابن عباس وابن الزبير اختلفا في المتعتين، فقال جابر: فعلناهما مع رسول الله ﷺ، ثم نهانا عنهما عمر فلم نعد لهما.","grade":"","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة كان خاصًّا لأصحاب رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1217).","chapter_en":"Those who said that changing Hajj into ʿUmrah was specific to the Companions of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Abu Nadrah said: Ibn ‘Abbas used to command the temporary combining connected to pilgrimage, while Ibn al-Zubayr used to forbid it. He said: I mentioned that to Jabir ibn ‘Abd Allah, and he said: The discussion passed through my own hands. We did it with the Messenger of Allah ﷺ. Then when ‘Umar took office, he said: “Allah used to permit for His Messenger whatever He willed in whatever way He willed, and the Qur’an has now taken its settled place, so complete the pilgrimage and the lesser pilgrimage for Allah as Allah commanded you, and make the marriages of these women definite and binding. If I am brought a man who married a woman for a fixed term, I will stone him.”","Muslim also narrated (1249) from Abu Nadrah, who said: I was with Jabir ibn ‘Abd Allah when someone came to him and said: Ibn ‘Abbas and Ibn al-Zubayr differed concerning the two temporary permissions. Jabir said: We did both of them with the Messenger of Allah ﷺ, then ‘Umar forbade us from them, so we did not return to them.","In a narration recorded by Imam Ahmad (369), Jabir said: We practiced this with the Messenger of Allah ﷺ and with Abu Bakr. Then when ‘Umar ibn al-Khattab became leader, he addressed the people and said: “The Qur’an is the Qur’an, and the Messenger of Allah ﷺ is the Messenger, and there were two temporary permissions during the time of the Messenger of Allah ﷺ: one was the temporary combining in pilgrimage, and the other was temporary marriage.”"]},"buhuth":{"ar":["وفي رواية عند الإمام أحمد (٣٦٩) قال جابر: تمتعنا مع رسول الله ﷺ ومع أبي بكر، فلما ولي عمر بن الخطاب خطب الناس فقال: إن القرآن هو القرآن، وإن رسول الله ﷺ هو الرسول، وإنهما كانتا متعتان على عهد رسول الله ﷺ: إحداهما متعة الحج، والأخرى متعة النساء.","صحيح: رواه مسلم (١٢١٧).","قوله: (( المتعتين )) أي متعة الحج ومتعة النساء.","قال شيخ الإسلام ابن تيمية رحمه الله: ومعلوم أن التمتع بالعمرة إلى الحج لا يكره بالاتفاق، فيجب حمل نهيهم على متعة الفسخ، ورخصة المتعة المبتدأة، توفيقًا بين أقاويلهم."],"en":["His statement, “the two temporary permissions,” means the temporary combining in pilgrimage and temporary marriage.","Shaykh al-Islam Ibn Taymiyyah, may Allah have mercy on him, said: It is well known that beginning with the lesser pilgrimage and then continuing to the pilgrimage is not disliked by agreement, so their discouragement must be understood as referring to changing the pilgrimage into the lesser pilgrimage and to the particular concession attached to that beginning form, in order to reconcile their statements."]}},"tuhfa":{},"refs":[{"key":"مسلم_ایضا","label":"مسلم أيضاً","number":1249}]},{"num":4944,"demo":false,"sanad":"","matn":["عن عروة بن الزبير: أنه أتى ابن عباس، فقال: يا ابن عباس، طالما أضللتَ الناس! قال: وما ذاك يا عُرَيَّةُ؟ قال: الرجل يخرج محرماً بحجٍّ أو عمرةٍ، فإذا طاف زعمتَ أنه قد حلَّ، فقد كان أبو بكر وعمر ينهيان عن ذلك. فقال: أَهُمَا - ويحكَ - آثَرُ عندك أم ما في كتاب الله وما سنَّ رسول الله ﷺ في أصحابه وفي أمته؟ فقال عروة: هما كانا أعلم بكتاب الله وما سنَّ رسول الله مني ومنك. قال ابن أبي مليكة: فخصمه عروة."],"takhrij":"حسن: رواه الطبراني في الأوسط (٢١).","grade":"حسن","chapter_ar":"باب من قال: إنّ فسخ الحجّ إلى العمرة كان خاصًّا لأصحاب رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (21).","chapter_en":"Those who said that changing Hajj into ʿUmrah was specific to the Companions of the Messenger of Allah ﷺ","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["‘Urwah ibn al-Zubayr came to Ibn ‘Abbas and said: O Ibn ‘Abbas, how often you have led people astray! He said: What is that, O little ‘Urwah? He said: A man leaves in consecration for pilgrimage or lesser pilgrimage, then once he circles the House you claim that he has exited consecration, while Abu Bakr and ‘Umar used to forbid that. So he said: “Are those two — woe to you — more deserving to be followed in your view than what is in the Book of Allah and what the Messenger of Allah ﷺ established among his Companions and his community?” ‘Urwah said: Those two were more knowledgeable than me and you regarding the Book of Allah and what the Messenger of Allah ﷺ established. Ibn Abi Mulaykah said: ‘Urwah overcame him in the debate."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":21},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":21,"n":21}]},{"num":4945,"demo":false,"sanad":"","matn":["عن أبي عمران أسلم، أنه قال: حججتُ مع موالي، فدخلتُ على أمِّ سلمة زوج النبيِّ ﷺ فقلتُ: أأعتمر قبل أن أحجَّ؟ قالت: إن شئتَ فاعتمر قبل أن تحجَّ، وإن شئتَ بعد أن تحجَّ. قال: فقلتُ: إنهم يقولون: من كان صَرُورةً فلا يصلح أن يعتمر قبل أن يحجَّ. قال: فسألتُ أمهات المؤمنين، فقلن مثل ما قالت، فرجعتُ إليها فأخبرتُها بقولهن، فقالت: نعم، وأنا أُشفيك، سمعتُ رسول الله ﷺ يقول: (( أَهِلُّوا يَا آلَ مُحَمَّدٍ بِعُمْرَةٍ فِي حَجٍّ ))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٦٥٤٨)، والطبراني في الكبير (٢٣/٣٤١)، والبيهقيّ (٤/٣٥٥).","grade":"صحيح","chapter_ar":"باب استحباب إهلال المرء بالتمتع إلى الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (26548), al-Tabarani in al-Kabir (23/341), and al-Bayhaqi (4/355).","chapter_en":"The recommendation of entering consecration for beginning with the lesser pilgrimage and then continuing to the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":17,"content":{"translation":{"en":["Abu ‘Imran Aslam said: I performed the pilgrimage with my patrons, then I entered upon Umm Salamah, the wife of the Prophet ﷺ, and said: Should I perform the lesser pilgrimage before the pilgrimage? She said: If you wish, perform the lesser pilgrimage before the pilgrimage, and if you wish, after the pilgrimage. He said: I said: They say that whoever has never performed the pilgrimage before should not perform the lesser pilgrimage before the pilgrimage. He said: So I asked the Mothers of the Believers, and they said the same as she had said. Then I returned to her and informed her of what they had said. She said: Yes, and I will settle it for you fully: I heard the Messenger of Allah ﷺ say, “O family of Muhammad, enter consecration for a lesser pilgrimage within a pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":26548},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":23},{"key":"البیہقی","label":"البيهقيّ","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":26548,"n":26548}]},{"num":4946,"demo":false,"sanad":"","matn":["عن بكر، عن أنس، قال: سَمِعْتُ النَّبِيَّ ﷺ يُلَبِّي بِالْحَجِّ وَالْعُمْرَةِ جَمِيعًا. قال بكر: فحدّثتُ بذلك ابنَ عمر، فقال: لبَّى بالحجِّ وحده. فلقيتُ أنسًا فحدّثتُه بقول ابن عمر، فقال أنس: ما تعدُّوننا إلا صبيانًا! سمعتُ رسول الله ﷺ يقول: (( لَبَّيْكَ عُمْرَةً وَحَجًّا ))."],"takhrij":"متفق عليه: رواه مسلم (١٨٥:١٢٣٢) والبخاريّ (٤٣٥٤، ٤٣٥٣).","grade":"متفق عليه","chapter_ar":"باب من قال: حجّ النبيُّ ﷺ قارنًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1232:185) and al-Bukhari (4354, 4353).","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage combining both rites","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Bakr narrated from Anas, who said: I heard the Prophet ﷺ proclaiming the pilgrimage and the lesser pilgrimage together. Bakr said: I mentioned that to Ibn ‘Umar, and he said: He proclaimed the pilgrimage alone. Then I met Anas and mentioned to him what Ibn ‘Umar had said, so Anas said: You treat us as if we were only children! I heard the Messenger of Allah ﷺ say: “Here I am for a lesser pilgrimage and a pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":185},{"key":"bukhari","label":"البخاريّ","number":4354}]},{"num":4947,"demo":false,"sanad":"","matn":["عن أنس، قال: صَلَّى رَسُولُ اللَّهِ ﷺ وَنَحْنُ مَعَهُ بِالْمَدِينَةِ الظُّهْرَ أَرْبَعًا، وَالْعَصْرَ بِذِي الْحُلَيْفَةِ رَكْعَتَيْنِ، ثُمَّ بَاتَ بِهَا حَتَّى أَصْبَحَ، ثُمَّ رَكِبَ حَتَّى اسْتَوَتْ بِهِ عَلَى الْبَيْدَاءِ، حَمِدَ اللَّهَ وَسَبَّحَ وَكَبَّرَ، ثُمَّ أَهَلَّ بِحَجٍّ وَعُمْرَةٍ، وَأَهَلَّ النَّاسُ بِهِمَا."],"takhrij":"صحيح: رواه البخاريّ (١٥٥١) ومسلم (٦٩٠).","grade":"صحيح","chapter_ar":"باب من قال: حجّ النبيُّ ﷺ قارنًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1551) and Muslim (690).","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage combining both rites","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ prayed the noon prayer with us in Medina as four units, and the afternoon prayer at Dhu al-Hulayfah as two units. Then he stayed there overnight until morning. Then he mounted, and when his mount stood upright with him upon al-Bayda’, he praised Allah, glorified Him, and declared His greatness, then he proclaimed both a pilgrimage and a lesser pilgrimage, and the people proclaimed both with him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1551},{"key":"muslim","label":"مسلم","number":690}]},{"num":4948,"demo":false,"sanad":"","matn":["عن أنس، قال: سمعتُ رسولَ الله ﷺ أهلَّ بهما جميعًا: (( لَبَّيْكَ عُمْرَةً وَحَجًّا، لَبَّيْكَ عُمْرَةً وَحَجًّا ))."],"takhrij":"صحيح: رواه مسلم (١٢٥١).","grade":"صحيح","chapter_ar":"باب من قال: حجّ النبيُّ ﷺ قارنًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1251).","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage combining both rites","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Anas said: I heard the Messenger of Allah ﷺ enter consecration for both together, saying: “Here I am for a lesser pilgrimage and a pilgrimage, here I am for a lesser pilgrimage and a pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1251}]},{"num":4949,"demo":false,"sanad":"","matn":["عن أنس: أنَّ رسولَ الله ﷺ قرن بين الحجِّ والعمرة، وقرن القوم معه."],"takhrij":"صحيح: رواه ابن حبان (٣٩٣١) والنسائي (٢٧٥٦، ٢٦٦٢).","grade":"صحيح","chapter_ar":"باب من قال: حجّ النبيُّ ﷺ قارنًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (3931) and al-Nasa’i (2756, 2662).","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage combining both rites","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ combined the pilgrimage and the lesser pilgrimage, and the people combined them with him."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2756},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":6555,"n":6553}]},{"num":4950,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله أنه سمع رجلاً من أهل الشام، وهو يسأل عبد الله بن عمر عن التمتع بالعمرة إلى الحج؟ فقال عبد الله بن عمر: هي حلال. فقال الشامي: إن أباك قد نهى عنها؟ فقال عبد الله بن عمر: أرأيتَ إن كان أبي نهى عنها، وصنعها رسول الله ﷺ، أأمر أبي نتبع أم أمر رسول الله؟ فقال الرجل: بل أمر رسول الله ﷺ. فقال: لقد صنعها رسول الله ﷺ."],"takhrij":"صحيح: رواه الترمذيّ (٨٢٤).","grade":"صحيح","chapter_ar":"باب من قال: حجّ النبيُّ ﷺ قارنًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (824).","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage combining both rites","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["Salim ibn ‘Abd Allah said that he heard a man from the people of Syria asking ‘Abd Allah ibn ‘Umar about beginning with the lesser pilgrimage and then continuing to the pilgrimage. ‘Abd Allah ibn ‘Umar said: It is lawful. The Syrian man said: But your father forbade it. ‘Abd Allah ibn ‘Umar said: Tell me — if my father forbade it, while the Messenger of Allah ﷺ did it, should the command of my father be followed or the command of the Messenger of Allah ﷺ? The man said: Rather, the command of the Messenger of Allah ﷺ. He said: The Messenger of Allah ﷺ indeed did it."]},"buhuth":{"ar":["التمتع هنا بمعنى القران، أي أنه ﷺ أتى بعمل العمرة غير الحلق والتقصير، ثم حجَّ، وهو القِران، ثم صار التمتع في الاصطلاح: من أتى بنسكين في سفر واحد مستقلين."],"en":["Here, this beginning form means combining both rites, meaning that he ﷺ performed the actions of the lesser pilgrimage except shaving or cutting the hair, then continued with the pilgrimage, and that is the combined form. Later, in juristic usage, the term came to mean performing two rites in one journey as two distinct acts."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":824}]},{"num":4951,"demo":false,"sanad":"","matn":["عن عائشة أنها قالت: خَرَجْنَا مَعَ رَسُولِ اللَّهِ ﷺ عَامَ حَجَّةِ الْوَدَاعِ، فَمِنَّا مَنْ أَهَلَّ بِعُمْرَةٍ، وَمِنَّا مَنْ أَهَلَّ بِحَجَّةٍ وَعُمْرَةٍ، وَمِنَّا مَنْ أَهَلَّ بِالْحَجِّ، وَأَهَلَّ رَسُولُ اللَّهِ ﷺ بِالْحَجِّ، فَأَمَّا مَنْ أَهَلَّ بِعُمْرَةٍ فَحَلَّ، وَأَمَّا مَنْ أَهَلَّ بِحَجٍّ أَوْ جَمَعَ الْحَجَّ وَالْعُمْرَةَ فَلَمْ يَحِلُّوا حَتَّى كَانَ يَوْمُ النَّحْرِ."],"takhrij":"متفق عليه: رواه مالك (٣٦) والبخاريّ (١٥٦٢)، ومسلم (١١٨:١٢١١).","grade":"متفق عليه","chapter_ar":"باب من قال: حجَّ النبيُّ ﷺ مفردًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (36), al-Bukhari (1562), and Muslim (1211:118).","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage alone","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["‘A’ishah said: We set out with the Messenger of Allah ﷺ in the year of the Farewell Pilgrimage. Some of us entered consecration for the lesser pilgrimage, some for both the pilgrimage and the lesser pilgrimage, and some for the pilgrimage alone. The Messenger of Allah ﷺ entered consecration for the pilgrimage. As for those who entered consecration for the lesser pilgrimage, they exited consecration; and as for those who entered consecration for the pilgrimage, or combined the pilgrimage and the lesser pilgrimage, they did not exit consecration until the Day of Sacrifice."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":36},{"key":"bukhari","label":"البخاريّ","number":1562},{"key":"muslim","label":"مسلم","number":118}]},{"num":4952,"demo":false,"sanad":"","matn":["عن بكر - وهو ابن عبد الله المزني - أنه ذكر لابن عمر أن أنسًا حدَّثهم أن النبيَّ ﷺ أهلَّ بعمرةٍ وحجّةٍ. فقال: أهلَّ النبيُّ ﷺ بالحجِّ، وأهللنا به معه، فلمَّا قدمنا مكة قال: (( مَنْ لَمْ يَكُنْ مَعَهُ هَدْيٌ فَلْيَجْعَلْهَا عُمْرَةً )). وكان مع النبيِّ ﷺ هَدْيٌ، فقدم علينا عليُّ بن أبي طالب من اليمن حاجًّا، فقال النبيُّ ﷺ: (( بِمَ أَهْلَلْتَ؟ فَإِنَّ مَعَنَا هَدْيًا )). قال: أهللتُ بما أهلَّ به النبيُّ ﷺ. قال: (( فَأَمْسِكْ، فَإِنَّ مَعَنَا هَدْيًا ))."],"takhrij":"صحيح: رواه البخاريّ (٤٣٥٤، ٤٣٥٣) ومسلم (١٢٣٢).","grade":"صحيح","chapter_ar":"باب من قال: حجَّ النبيُّ ﷺ مفردًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4354, 4353) and Muslim (1232).","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage alone","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Bakr — who is Ibn ‘Abd Allah al-Muzani — mentioned to Ibn ‘Umar that Anas had told them that the Prophet ﷺ entered consecration for a lesser pilgrimage and a pilgrimage. Ibn ‘Umar said: The Prophet ﷺ entered consecration for the pilgrimage, and we entered consecration for it with him. When we arrived in Mecca, he said: “Whoever among you does not have a sacrificial animal with him should make it a lesser pilgrimage.” The Prophet ﷺ had sacrificial animals with him. Then ‘Ali ibn Abi Talib came to us from Yemen as a pilgrim, and the Prophet ﷺ said: “For what did you enter consecration? For we have sacrificial animals with us.” He said: I entered consecration for what the Prophet ﷺ entered consecration for. He said: “Then remain in consecration, for we have sacrificial animals with us.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4354},{"key":"muslim","label":"مسلم","number":1232}]},{"num":4953,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: (( أَهْلَلْنَا مَعَ رَسُولِ اللَّهِ ﷺ بِالْحَجِّ مُفْرَدًا ))."],"takhrij":"صحيح: رواه مسلم (١٢٣١). قال مسلم: وفي رواية ابن عون: (( أن رسول الله ﷺ أهلَّ بالحجِّ مُفْرَدًا )).","grade":"صحيح","chapter_ar":"باب من قال: حجَّ النبيُّ ﷺ مفردًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1231). Muslim said: In the narration of Ibn ‘Awn: “The Messenger of Allah ﷺ entered consecration for the pilgrimage alone.”","chapter_en":"Those who said that the Prophet ﷺ performed the pilgrimage alone","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: We entered consecration with the Messenger of Allah ﷺ for the pilgrimage alone."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1231}]},{"num":4954,"demo":false,"sanad":"","matn":["عن الصُّبَيِّ بنِ مَعْبَدٍ قال: كُنْتُ رَجُلًا أَعْرَابِيًّا نَصْرَانِيًّا فَأَسْلَمْتُ، فَأَتَيْتُ رَجُلًا مِنْ عَشِيرَتِي يُقَالُ لَهُ هُدَيْمُ بْنُ قُرْمُلَةَ فَقُلْتُ لَهُ: يَا هَنَاهُ، إِنِّي حَرِيصٌ عَلَى الْجِهَادِ، وَإِنِّي وَجَدْتُ الْحَجَّ وَالْعُمْرَةَ مَكْتُوبَيْنِ عَلَيَّ، فَكَيْفَ لِي بِأَنْ أَجْمَعَهُمَا؟ قَالَ: اجْمَعْهُمَا، وَاذْبَحْ مَا اسْتَيْسَرَ مِنَ الْهَدْيِ. فَأَهْلَلْتُ بِهِمَا جَمِيعًا. فَلَمَّا أَتَيْتُ الْعُذَيْبَ لَقِيَنِي سَلْمَانُ بْنُ رَبِيعَةَ وَزَيْدُ بْنُ صُوحَانَ - وَأَنَا أُهِلُّ بِهِمَا جَمِيعًا - فَقَالَ أَحَدُهُمَا لِلْآخَرِ: مَا هَذَا بِأَفْقَهَ مِنْ بَعِيرِهِ. قَالَ: فَكَأَنَّمَا أُلْقِيَ عَلَيَّ جَبَلٌ، حَتَّى أَتَيْتُ عُمَرَ بْنَ الْخَطَّابِ فَقُلْتُ لَهُ: يَا أَمِيرَ الْمُؤْمِنِينَ، إِنِّي كُنْتُ رَجُلًا أَعْرَابِيًّا نَصْرَانِيًّا، وَإِنِّي أَسْلَمْتُ وَأَنَا حَرِيصٌ عَلَى الْجِهَادِ، وَإِنِّي وَجَدْتُ الْحَجَّ وَالْعُمْرَةَ مَكْتُوبَيْنِ عَلَيَّ، فَأَتَيْتُ رَجُلًا مِنْ قَوْمِي فَقَالَ لِي: اجْمَعْهُمَا وَاذْبَحْ مَا اسْتَيْسَرَ مِنَ الْهَدْيِ، وَإِنِّي أَهْلَلْتُ بِهِمَا مَعًا. فَقَالَ لِي عُمَرُ رَضِيَ اللَّهُ عَنْهُ: (( هُدِيتَ لِسُنَّةِ نَبِيِّكَ ﷺ ))."],"takhrij":"صحيح: رواه أبو داود (١٧٩٩) - واللفظ له -، والنسائيّ (٢٧١٩)، وابن حبان (٣٩٧٠).","grade":"صحيح","chapter_ar":"باب جواز القِران بدون سوق الهدي من الميقات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1799) — this is his wording — al-Nasa’i (2719), and Ibn Hibban (3970).","chapter_en":"The permissibility of combining both rites without bringing sacrificial animals from the appointed boundary","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["Al-Subayyi‘ ibn Ma‘bad said: I was a desert Arab and a Christian, then I accepted Islam. I came to a man from my clan named Hudaym ibn Qarmalah and said to him: O my good man, I am eager for striving in the path of Allah, and I have found that the pilgrimage and the lesser pilgrimage are both prescribed upon me, so how can I combine them? He said: Combine them, and slaughter whatever sacrificial animal is easy for you. So I entered consecration for both together. When I came to al-‘Udhayb, Salman ibn Rabi‘ah and Zayd ibn Suhan met me while I was entering consecration for both together, and one of them said to the other: This man is no more knowledgeable than his camel. He said: It was as if a mountain had been cast upon me, until I came to ‘Umar ibn al-Khattab and said to him: O Commander of the Believers, I was a desert Arab and a Christian, then I accepted Islam while eager for striving in the path of Allah, and I found that the pilgrimage and the lesser pilgrimage are both prescribed upon me, so I came to a man from my people and he said to me: Combine them and slaughter whatever sacrificial animal is easy for you. So I entered consecration for both together. Then ‘Umar, may Allah be pleased with him, said to me: “You have been guided to the Sunnah of your Prophet ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1799},{"key":"nasai","label":"النسائيّ","number":2719},{"key":"ibnhibban","label":"ابن حبان","number":3970}]},{"num":4955,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أنه قال حين خرج إلى مكة معتمرًا في الفتنة: إِنْ صُدِدْتُ عَنِ الْبَيْتِ صَنَعْنَا كَمَا صَنَعْنَا مَعَ رَسُولِ اللَّهِ ﷺ، فَأَهَلَّ بِعُمْرَةٍ مِنْ أَجْلِ أَنَّ رَسُولَ اللَّهِ ﷺ أَهَلَّ بِعُمْرَةٍ عَامَ الْحُدَيْبِيَةِ، ثُمَّ إِنَّ عَبْدَ اللَّهِ نَظَرَ فِي أَمْرِهِ فَقَالَ: مَا أَمْرُهُمَا إِلَّا وَاحِدٌ، ثُمَّ الْتَفَتَ إِلَى أَصْحَابِهِ فَقَالَ: مَا أَمْرُهُمَا إِلَّا وَاحِدٌ، أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ الْحَجَّ مَعَ الْعُمْرَةِ، ثُمَّ نَفَذَ حَتَّى جَاءَ الْبَيْتَ فَطَافَ طَوَافًا وَاحِدًا وَرَأَى ذَلِكَ مُجْزِئًا عَنْهُ وَأَهْدَى."],"takhrij":"متفق عليه: رواه مالك (٩٩) والبخاريّ (١٨١٣)، ومسلم (١٢٣٠) إلا أن مسلمًا قال: (( فخرج حتى إذا جاء البيت طاف به سبعًا وبين الصفا والمروة سبعًا لم يزد عليه… )).","grade":"متفق عليه","chapter_ar":"باب من حوّل نيته من التمتع إلى القِران قبل الشروع في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (99), al-Bukhari (1813), and Muslim (1230), except that Muslim said: “He went on until he came to the House, then circumambulated it seven times and went between al-Safa and al-Marwah seven times, and did not add more than that…”","chapter_en":"One who changed his intention from beginning with the lesser pilgrimage and then continuing to the pilgrimage to combining both rites before starting the circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":21,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said, when he set out to Mecca for the lesser pilgrimage during the time of unrest: “If I am prevented from reaching the House, we will do as we did with the Messenger of Allah ﷺ.” So he entered consecration for a lesser pilgrimage because the Messenger of Allah ﷺ had entered consecration for a lesser pilgrimage in the year of al-Hudaybiyah. Then ‘Abd Allah reconsidered the matter and said: “The ruling of the two is only one.” Then he turned to his companions and said: “The ruling of the two is only one. I call you to witness that I have now joined the pilgrimage with the lesser pilgrimage.” Then he went on until he came to the House, and he performed one circumambulation, and considered that sufficient for him, and he offered a sacrificial animal."]},"buhuth":{"ar":["ورواه البخاريّ (١٦٩٣)، ومسلم (١٨٣:١٢٣٠)."],"en":["It was also narrated by al-Bukhari (1693) and Muslim (1230:183)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":99},{"key":"bukhari","label":"البخاريّ","number":1813},{"key":"muslim","label":"مسلم","number":1230}]},{"num":4956,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خَرَجْنَا مَعَ رَسُولِ اللَّهِ ﷺ عَامَ حَجَّةِ الْوَدَاعِ فَأَهْلَلْنَا بِعُمْرَةٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ ﷺ: (( مَنْ كَانَ مَعَهُ هَدْيٌ فَلْيُهِلَّ بِالْحَجِّ مَعَ الْعُمْرَةِ، ثُمَّ لَا يَحِلُّ حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا )). قالت: فَقَدِمْتُ مَكَّةَ وَأَنَا حَائِضٌ فَلَمْ أَطُفْ بِالْبَيْتِ وَلَا بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَشَكَوْتُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ﷺ فَقَالَ: (( انْقُضِي رَأْسَكِ وَامْتَشِطِي وَأَهِلِّي بِالْحَجِّ وَدَعِي الْعُمْرَةَ )). قالت: فَفَعَلْتُ، فَلَمَّا قَضَيْنَا الْحَجَّ أَرْسَلَنِي رَسُولُ اللَّهِ ﷺ مَعَ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ إِلَى التَّنْعِيمِ فَاعْتَمَرْتُ، فَقَالَ: (( هَذَا مَكَانُ عُمْرَتِكِ )).","فَطَافَ الَّذِينَ أَهَلُّوا بِالْعُمْرَةِ بِالْبَيْتِ وَبَيْنَ الصَّفَا وَالْمَرْوَةِ، ثُمَّ حَلُّوا مِنْهَا، ثُمَّ طَافُوا طَوَافًا آخَرَ بَعْدَ أَنْ رَجَعُوا مِنْ مِنًى لِحَجِّهِمْ. وَأَمَّا الَّذِينَ كَانُوا أَهَلُّوا بِالْحَجِّ أَوْ جَمَعُوا الْحَجَّ وَالْعُمْرَةَ فَإِنَّمَا طَافُوا طَوَافًا وَاحِدًا."],"takhrij":"متفق عليه: رواه مالك (٢٢٣) والبخاريّ (١٥٥٦)، ومسلم (١١١:١٢١١).","grade":"متفق عليه","chapter_ar":"باب أنّ المرأة المتمتعة إذا حاضت قبل الطواف صارت مفردةً أو قارنةً","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (223), al-Bukhari (1556), and Muslim (1211:111).","chapter_en":"If a woman who intended beginning with the lesser pilgrimage and then continuing to the pilgrimage menstruates before circumambulation, she becomes one performing only the pilgrimage or one combining both rites","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["‘A’ishah said: We set out with the Messenger of Allah ﷺ in the year of the Farewell Pilgrimage and entered consecration for the lesser pilgrimage. Then the Messenger of Allah ﷺ said: “Whoever has a sacrificial animal with him should enter consecration for the pilgrimage together with the lesser pilgrimage, then he should not come out of consecration until he comes out of both together.” She said: I arrived in Mecca while menstruating, so I did not circumambulate the House nor go between al-Safa and al-Marwah. I complained about that to the Messenger of Allah ﷺ, and he said: “Undo your hair, comb it, enter consecration for the pilgrimage, and leave the lesser pilgrimage.” She said: So I did that. Then when we completed the pilgrimage, the Messenger of Allah ﷺ sent me with ‘Abd al-Rahman ibn Abi Bakr al-Siddiq to al-Tan‘im, and I performed the lesser pilgrimage. He then said: “This is in place of your lesser pilgrimage.”","Those who had entered consecration for the lesser pilgrimage circumambulated the House and went between al-Safa and al-Marwah, then came out of consecration. Then they performed another circumambulation after returning from Mina for their pilgrimage. As for those who had entered consecration for the pilgrimage, or had combined the pilgrimage and the lesser pilgrimage, they only performed one circumambulation."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":223},{"key":"bukhari","label":"البخاريّ","number":1556},{"key":"muslim","label":"مسلم","number":111}]},{"num":4957,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: بَعَثَنِي أَبُو بَكْرٍ الصِّدِّيقُ فِي الْحَجَّةِ الَّتِي أَمَّرَهُ عَلَيْهَا رَسُولُ اللَّهِ ﷺ قَبْلَ حَجَّةِ الْوَدَاعِ فِي رَهْطٍ يُؤَذِّنُونَ فِي النَّاسِ يَوْمَ النَّحْرِ: (( لَا يَحُجُّ بَعْدَ الْعَامِ مُشْرِكٌ وَلَا يَطُوفُ بِالْبَيْتِ عُرْيَانٌ ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٢٢)، ومسلم (١٣٤٧)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب وجوب ستر العورة في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1622) and Muslim (1347), and this is the wording of Muslim.","chapter_en":"The obligation of covering the private parts during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah said: Abu Bakr al-Siddiq sent me during the pilgrimage in which the Messenger of Allah ﷺ appointed him leader, before the Farewell Pilgrimage, among a group announcing to the people on the Day of Sacrifice: “After this year, no idolater shall perform pilgrimage, and no one shall circumambulate the House naked.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1622},{"key":"muslim","label":"مسلم","number":1347}]},{"num":4958,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: بَعَثَنِي أَبُو بَكْرٍ فِي تِلْكَ الْحَجَّةِ فِي مُؤَذِّنِينَ بَعَثَهُمْ يَوْمَ النَّحْرِ يُؤَذِّنُونَ بِمِنًى: (( أَنْ لَا يَحُجَّ بَعْدَ الْعَامِ مُشْرِكٌ وَلَا يَطُوفَ بِالْبَيْتِ عُرْيَانٌ )).","قَالَ حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ: ثُمَّ أَرْدَفَ رَسُولُ اللَّهِ ﷺ بِعَلِيِّ بْنِ أَبِي طَالِبٍ وَأَمَرَهُ أَنْ يُؤَذِّنَ بِبَرَاءَةَ.","قَالَ أَبُو هُرَيْرَةَ: فَأَذَّنَ مَعَنَا عَلِيٌّ يَوْمَ النَّحْرِ فِي أَهْلِ مِنًى بِبَرَاءَةَ، وَأَنْ لَا يَحُجَّ بَعْدَ الْعَامِ مُشْرِكٌ وَلَا يَطُوفَ بِالْبَيْتِ عُرْيَانٌ."],"takhrij":"صحيح: رواه البخاريّ (٤٦٥٥).","grade":"صحيح","chapter_ar":"باب وجوب ستر العورة في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4655).","chapter_en":"The obligation of covering the private parts during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah said: Abu Bakr sent me during that pilgrimage among callers whom he sent on the Day of Sacrifice, announcing in Mina: “After this year, no idolater shall perform pilgrimage, and no one shall circumambulate the House naked.”","Humayd ibn ‘Abd al-Rahman said: Then the Messenger of Allah ﷺ sent ‘Ali ibn Abi Talib after him and commanded him to proclaim Surat Bara’ah.","Abu Hurayrah said: ‘Ali proclaimed with us on the Day of Sacrifice among the people of Mina the message of Bara’ah, and that after this year no idolater should perform pilgrimage and no one should circumambulate the House naked."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4655}]},{"num":4959,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: كَانَتِ الْمَرْأَةُ تَطُوفُ بِالْبَيْتِ وَهِيَ عُرْيَانَةٌ، فَتَقُولُ: مَنْ يُعِيرُنِي تِطْوَافًا، تَجْعَلُهُ عَلَى فَرْجِهَا، وَتَقُولُ:","الْيَوْمَ يَبْدُو بَعْضُهُ أَوْ كُلُّهُ","فَمَا بَدَا مِنْهُ فَلَا أُحِلُّهُ","فَنَزَلَتْ هَذِهِ الْآيَةُ: ( خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ ) [سورة الأعراف: ٣١]."],"takhrij":"صحيح: رواه مسلم في التفسير (٣٠٢٨).","grade":"صحيح","chapter_ar":"باب وجوب ستر العورة في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the section of commentary (3028).","chapter_en":"The obligation of covering the private parts during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["Ibn ‘Abbas said: A woman used to circumambulate the House while naked, saying: “Who will lend me a wrap for circumambulation?” and she would place it over her private part and say:","“Today part of it or all of it may appear,","but whatever appears of it, I do not make lawful.”","Then this verse was revealed: “Take your adornment at every place of prayer.” [Surat al-A‘raf: 31]"]},"buhuth":{"ar":["وقوله: (( تِطْوَافًا )) هو ثوب تلبسه المرأة تطوف به.","ابتدعت قريش - قبل حادثة الفيل أو بعدها - ألَّا يطوف بالبيت أحد من غيرهم إلا بثياب أحدهم، فإن لم يجد طاف عريانًا، فإن خالف وطاف بثيابه ألقاها إذا فرغ، ولا يأخذها أبدًا، وتُداس بالأرجل، فجاء الإسلام بهدم هذه العادة الجاهلية.","وقوله: (( تقول … إلخ )) أي تطوف عريانة وتنشد هذا الشعر، وحاصله: اليوم يظهر بعض الفرج أو كله، وعلى التقديرين فلا أُبيح لأحد أن ينظر إليه قصدًا. تريد أنها كشفت الفرج لضرورة الطواف، لا لإباحة النظر إليه والاستمتاع به، فليس لأحد أن يفعل ذلك. قاله السيوطي في شرح النسائي.","فجاء الإسلام وأمر الله بستر العورة، فقال تعالى: ( يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ )، وقال النبي ﷺ: (( لا يطوف بالبيت عريان ))."],"en":["His statement, “a wrap for circumambulation,” means a garment worn by the woman while circling the House.","Quraysh had introduced, before or after the incident of the Elephant, that no one from outside them should circumambulate the House except in garments belonging to one of them. If a person could not find such garments, he would circumambulate naked. If someone disobeyed and circumambulated in his own garments, he would throw them away when finished and never take them back, and they would be trampled underfoot. Islam came and destroyed this pre-Islamic custom.","Her statement in the lines of verse means that she circumambulated naked while reciting this poetry, whose sense is: today part or all of the private part may appear, but in either case I do not permit anyone to look at it intentionally. She meant that she uncovered it out of necessity for the circumambulation, not to make looking at it or seeking enjoyment from it lawful. So no one had the right to do that. This was mentioned by al-Suyuti in his commentary on al-Nasa’i.","Then Islam came, and Allah commanded that the private parts be covered. Allah Most High said: “O children of Adam, take your adornment at every place of prayer,” and the Prophet ﷺ said: “No one is to circumambulate the House naked.”"]}},"tuhfa":{},"refs":[{"key":"muslim/التفسیر","label":"مسلم في التفسير","number":3028}]},{"num":4960,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: أَقْبَلَ رَسُولُ اللَّهِ ﷺ فَدَخَلَ مَكَّةَ، فَأَقْبَلَ رَسُولُ اللَّهِ ﷺ إِلَى الْحَجَرِ فَاسْتَلَمَهُ، ثُمَّ طَافَ بِالْبَيْتِ، ثُمَّ أَتَى الصَّفَا فَعَلَاهُ حَيْثُ يَنْظُرُ إِلَى الْبَيْتِ، فَرَفَعَ يَدَيْهِ، فَجَعَلَ يَذْكُرُ اللَّهَ مَا شَاءَ أَنْ يَذْكُرَهُ وَيَدْعُوهُ. قَالَ: وَالْأَنْصَارُ تَحْتَهُ. قَالَ هَاشِمٌ: فَدَعَا وَحَمِدَ اللَّهَ وَدَعَا بِمَا شَاءَ أَنْ يَدْعُوَ."],"takhrij":"صحيح: رواه أبو داود (١٨٧٢)، والإمام أحمد (١٠٩٤٨).","grade":"صحيح","chapter_ar":"باب أنّ الداخل إلى الحرم أول ما يفعل استلام الحجر ثم الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1872) and Imam Ahmad (10948).","chapter_en":"The one entering the Sacred Precinct begins first by touching the Black Stone and then circumambulating","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":25,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ came and entered Mecca. Then the Messenger of Allah ﷺ went to the Black Stone and touched it, then circumambulated the House. Then he came to al-Safa and climbed it where he could look toward the House. Then he raised his hands and began remembering Allah as much as he wished and supplicating to Him. He said: The Helpers were below him. Hashim said: Then he supplicated, praised Allah, and supplicated with whatever he wished to supplicate."]},"buhuth":{"ar":["ورواه أبو داود (١٨٧١) أيضًا وزاد فيه: (( وصلَّى ركعتين خلف المقام )) بعد قوله: (( لما دخل مكة طاف بالبيت ))."],"en":["Abu Dawud (1871) also narrated it with the addition: “And he prayed two units behind the Station,” after the words: “When he entered Mecca, he circumambulated the House.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1872},{"key":"الامام_احمد","label":"الإمام أحمد","number":10948},{"key":"ahmad","label":"مسند الإمام أحمد","number":10948,"n":10948}]},{"num":4961,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قال رسول اللّٰه ﷺ: (( نَزَلَ الْحَجَرُ الْأَسْوَدُ مِنَ الْجَنَّةِ، وَهُوَ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، فَسَوَّدَتْهُ خَطَايَا بَنِي آدَمَ ))."],"takhrij":"صحيح: رواه الترمذيّ (٨٧٧) وقال: (( حسن صحيح ))، والنسائيّ (٢٩٣٥)، وأحمد (٢٧٩٥).","grade":"صحيح","chapter_ar":"باب في فضل الحجر الأسود والمقام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (877), who said: “Hasan Sahih,” and by al-Nasa’i (2935) and Ahmad (2795).","chapter_en":"The virtue of the Black Stone and the Station of Abraham","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":26,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said: “The Black Stone came down from Paradise, and it was whiter than milk, but the sins of the children of Adam made it black.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":877},{"key":"nasai","label":"النسائيّ","number":2935},{"key":"ahmad","label":"مسند الإمام أحمد","number":2795,"n":2795}]},{"num":4962,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص قال: قال رسول اللّٰه ﷺ: (( الرُّكْنُ وَالْمَقَامُ يَاقُوتَتَانِ مِنْ يَاقُوتِ الْجَنَّةِ، طَمَسَ اللَّهُ نُورَهُمَا، وَلَوْلَا ذَلِكَ لَأَضَاءَتَا مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ ))."],"takhrij":"حسن: رواه ابن خزيمة (٢٧٣١)، والحاكم (١٦٧٧)، والبيهقيّ (٥/٧٥).","grade":"حسن","chapter_ar":"باب في فضل الحجر الأسود والمقام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (2731), al-Hakim (1677), and al-Bayhaqi (5/75).","chapter_en":"The virtue of the Black Stone and the Station of Abraham","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":26,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As said: The Messenger of Allah ﷺ said: “The Corner and the Station are two rubies from the rubies of Paradise. Allah erased their light, and had He not done so, they would have illuminated everything between the east and the west.”"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2731},{"key":"البیہقی","label":"البيهقيّ","number":5},{"key":"hakim","label":"المستدرك على الصحيحين","number":1677,"n":1667}]},{"num":4963,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ النبيَّ ﷺ قال: (( مَسْحُ الْحَجَرِ وَالرُّكْنِ الْيَمَانِيِّ يَحُطُّ الْخَطَايَا حَطًّا ))."],"takhrij":"صحيح: رواه الإمام أحمد (٥٦٢١)، وابن حبان (٣٦٩٨)، وعبد الرزاق في مصنفه (٨٨٧٧).","grade":"صحيح","chapter_ar":"باب ذكر حطّ الخطايا باستلام الركنين اليمانيين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (5621), Ibn Hibban (3698), and ‘Abd al-Razzaq in his Musannaf (8877).","chapter_en":"Mention of sins being removed by touching the two Yemeni corners","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":27,"content":{"translation":{"en":["Ibn ‘Umar reported that the Prophet ﷺ said: “Wiping the Black Stone and the Yemeni Corner causes sins to fall away completely.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":5621},{"key":"عبد_الرزاق/مصنفہ","label":"عبد الرزاق في مصنفه","number":8877},{"key":"ahmad","label":"مسند الإمام أحمد","number":5621,"n":5621},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":297,"n":297}]},{"num":4964,"demo":false,"sanad":"","matn":["عن المنكدر بن عبد الله قال: قال رسول اللّه ﷺ: (( مَنْ طَافَ حَوْلَ الْبَيْتِ أُسْبُوعًا لَا يَلْغُو فِيهِ كَانَ كَعَدْلِ رَقَبَةٍ يَعْتِقُهَا ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٢٠/٣٦٠)، وعنه أبو نعيم في “معرفة الصحابة” (٥/٢٦٠١).","grade":"حسن","chapter_ar":"باب ما جاء في فضل الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (20/360), and from him Abu Nu‘aym in “Ma‘rifat al-Sahabah” (5/2601).","chapter_en":"What has come regarding the virtue of circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":28,"content":{"translation":{"en":["Al-Munkadir ibn ‘Abd Allah said: The Messenger of Allah ﷺ said: “Whoever circumambulates the House seven times, not engaging in vain talk during it, will have the reward equal to freeing a slave.”"]},"intro":{"ar":["قال تعالى: ( وَطَهِّرْ بَيْتِيَ لِلطَّائِفِينَ ) [سورة الحج: ٢٦].","وقال: ( وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ ) [سورة الحج: ٢٩].","العتيق يعني القديم، يدل عليه قوله تعالى: ( إِنَّ أَوَّلَ بَيْتٍ وُضِعَ لِلنَّاسِ لَلَّذِي بِبَكَّةَ مُبَارَكًا وَهُدًى لِلْعَالَمِينَ ) [سورة آل عمران: ٩٦]."],"en":["Allah Most High said: “And purify My House for those who circumambulate.” [Surat al-Hajj: 26]","And He said: “And let them circumambulate the Ancient House.” [Surat al-Hajj: 29]","The word “Ancient” here means old and ancient, as shown by His saying: “Indeed, the first House established for mankind was the one at Bakkah, blessed and a guidance for all people.” [Surat Al ‘Imran: 96]"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":20},{"key":"عنہ_ابو_نعیم/معرفہ_الصحابہ","label":"عنه أبو نعيم في “معرفة الصحابة”","number":5}]},{"num":4965,"demo":false,"sanad":"","matn":["عن عبد الله بن عبيد بن عمير، أنَّ رجلًا قال: يا أبا عبد الرحمن، ما أراك تستلم إلا هذين الركنين؟ قال: إنِّي سمعتُ رسولَ اللّٰه ﷺ يقول: (( إِنَّ مَسْحَهُمَا يَحُطَّانِ الْخَطِيئَةَ )).","وسمعتُه يقول: (( مَنْ طَافَ سَبْعًا فَهُوَ كَعِدْلِ رَقَبَةٍ ))."],"takhrij":"صحيح: رواه النسائيّ (٢٩١٩).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (2919).","chapter_en":"What has come regarding the virtue of circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":28,"content":{"translation":{"en":["‘Abd Allah ibn ‘Ubayd ibn ‘Umayr narrated that a man said: O Abu ‘Abd al-Rahman, I see you touching only these two corners. He replied: I heard the Messenger of Allah ﷺ say: “Touching them removes sins.”","And I heard him say: “Whoever circumambulates seven times, it is like freeing a slave.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2919}]},{"num":4966,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: سمعتُ رسول اللّٰه ﷺ يقول: (( مَنْ طَافَ بِهَذَا الْبَيْتِ أُسْبُوعًا فَأَحْصَاهُ كَانَ كَعِتْقِ رَقَبَةٍ )).","وسمعته يقول: (( لَا يَضَعُ قَدَمًا وَلَا يَرْفَعُ أُخْرَى إِلَّا حَطَّ اللَّهُ عَنْهُ خَطِيئَةً وَكَتَبَ لَهُ بِهَا حَسَنَةً ))."],"takhrij":"صحيح: رواه الترمذيّ (٩٥٩)، والحاكم (١٧٩٩)، وابن حبان (٣٦٩٧).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (959), al-Hakim (1799), and Ibn Hibban (3697).","chapter_en":"What has come regarding the virtue of circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":28,"content":{"translation":{"en":["Ibn ‘Umar said: I heard the Messenger of Allah ﷺ say: “Whoever circumambulates this House seven times and completes it carefully, it is like freeing a slave.”","And I heard him say: “He does not place one foot down nor raise the other except that Allah removes a sin from him and writes for him a good deed because of it.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":959},{"key":"ibnhibban","label":"ابن حبان","number":3697},{"key":"hakim","label":"المستدرك على الصحيحين","number":1799,"n":1789}]},{"num":4967,"demo":false,"sanad":"","matn":["عن عمر أنه جاء إلى الحجر الأسود فقبله فقال: إِنِّي أَعْلَمُ أَنَّكَ حَجَرٌ لَا تَضُرُّ وَلَا تَنْفَعُ، وَلَوْلَا أَنِّي رَأَيْتُ النَّبِيَّ ﷺ يُقَبِّلُكَ مَا قَبَّلْتُكَ."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٩٧)، ومسلم (٢٥١:١٢٧٠).","grade":"متفق عليه","chapter_ar":"باب استحباب تقبيل الحجر الأسود أو استلامه بشيء وتقبيله، أو الإشارة إليه عند كل شوط في الطواف مع التكبير","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1597) and Muslim (1270:251).","chapter_en":"The recommendation of kissing the Black Stone, or touching it with something and kissing that, or pointing to it during each circuit of circumambulation along with saying “Allah is the Greatest”","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":29,"content":{"translation":{"en":["‘Umar came to the Black Stone and kissed it, then said: “I certainly know that you are only a stone. You neither harm nor benefit. Had I not seen the Prophet ﷺ kissing you, I would not have kissed you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1597},{"key":"muslim","label":"مسلم","number":251}]},{"num":4968,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب، قال للركن: أَمَا وَاللَّهِ إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ لَا تَضُرُّ وَلَا تَنْفَعُ، وَلَوْلَا أَنِّي رَأَيْتُ النَّبِيَّ ﷺ اسْتَلَمَكَ مَا اسْتَلَمْتُكَ. فَاسْتَلَمَهُ، ثُمَّ قَالَ: فَمَا لَنَا وَلِلرَّمَلِ؟ إِنَّمَا كُنَّا رَاءَيْنَا بِهِ الْمُشْرِكِينَ وَقَدْ أَهْلَكَهُمُ اللَّهُ. ثُمَّ قَالَ: شَيْءٌ صَنَعَهُ النَّبِيُّ ﷺ فَلَا نُحِبُّ أَنْ نَتْرُكَهُ."],"takhrij":"صحيح: رواه البخاريّ (١٦٠٥).","grade":"صحيح","chapter_ar":"باب استحباب تقبيل الحجر الأسود أو استلامه بشيء وتقبيله، أو الإشارة إليه عند كل شوط في الطواف مع التكبير","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1605).","chapter_en":"The recommendation of kissing the Black Stone, or touching it with something and kissing that, or pointing to it during each circuit of circumambulation along with saying “Allah is the Greatest”","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":29,"content":{"translation":{"en":["‘Umar ibn al-Khattab said to the Corner: “By Allah, I certainly know that you are only a stone. You neither harm nor benefit. Had I not seen the Prophet ﷺ touch you, I would not have touched you.” Then he touched it and said: “What concern do we have with brisk walking? We only used to do it to show strength before the idolaters, and Allah has destroyed them.” Then he said: “It is something the Prophet ﷺ did, and we do not like to leave it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1605}]},{"num":4969,"demo":false,"sanad":"","matn":["عن سويد بن غفلة، قال: رأيتُ عمر قبَّل الحجر والتزمه، وقال: رأيتُ رسولَ اللّٰه ﷺ بك حفيًّا."],"takhrij":"صحيح: رواه مسلم (١٢٧١).","grade":"صحيح","chapter_ar":"باب استحباب تقبيل الحجر الأسود أو استلامه بشيء وتقبيله، أو الإشارة إليه عند كل شوط في الطواف مع التكبير","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1271).","chapter_en":"The recommendation of kissing the Black Stone, or touching it with something and kissing that, or pointing to it during each circuit of circumambulation along with saying “Allah is the Greatest”","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":29,"content":{"translation":{"en":["Suwayd ibn Ghaflah said: I saw ‘Umar kiss the Stone and cling to it, and he said: “I saw the Messenger of Allah ﷺ showing you special care.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1271}]},{"num":4970,"demo":false,"sanad":"","matn":["عن الزبير بن عربيّ قال: سأل رجلٌ ابنَ عمر رضي الله عنهما عن استلام الحجر؟ فقال: رأيتُ رسولَ اللّٰه ﷺ يستلمه ويقبّله. قال: قلتُ: أرأيتَ إن زُحِمتُ، أرأيتَ إن غُلِبتُ؟ قال: اجعلْ أَرَأَيْتَ باليمن! رأيتُ رسولَ اللّٰه ﷺ يستلمه ويقبّله."],"takhrij":"صحيح: رواه البخاريّ (١٦١١).","grade":"صحيح","chapter_ar":"باب استحباب تقبيل الحجر الأسود أو استلامه بشيء وتقبيله، أو الإشارة إليه عند كل شوط في الطواف مع التكبير","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1611).","chapter_en":"The recommendation of kissing the Black Stone, or touching it with something and kissing that, or pointing to it during each circuit of circumambulation along with saying “Allah is the Greatest”","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":29,"content":{"translation":{"en":["Al-Zubayr ibn ‘Arabi said: A man asked Ibn ‘Umar, may Allah be pleased with them both, about touching the Stone. He said: I saw the Messenger of Allah ﷺ touch it and kiss it. The man said: What if I am crowded out? What if I am overpowered? He said: Leave your “what if” in Yemen. I saw the Messenger of Allah ﷺ touch it and kiss it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1611}]},{"num":4971,"demo":false,"sanad":"","matn":["عن قدامة بن عبد الله قال: رأيتُ رسولَ اللَّهِ ﷺ على ناقةٍ يستلم الحجر بمحجنه."],"takhrij":"حسن: رواه أحمد (١٥٤١٤)، وأبو يعلى (٩٢٨)، والطبراني في الكبير (١٩/٨٠)، وفي الأوسط (٨٠٢٤).","grade":"حسن","chapter_ar":"باب استحباب تقبيل الحجر الأسود أو استلامه بشيء وتقبيله، أو الإشارة إليه عند كل شوط في الطواف مع التكبير","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (15414), Abu Ya‘la (928), al-Tabarani in al-Kabir (19/80), and in al-Awsat (8024).","chapter_en":"The recommendation of kissing the Black Stone, or touching it with something and kissing that, or pointing to it during each circuit of circumambulation along with saying “Allah is the Greatest”","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":29,"content":{"translation":{"en":["Qudamah ibn ‘Abd Allah said: I saw the Messenger of Allah ﷺ on a she-camel touching the Stone with his crooked staff."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":928},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":19},{"key":"وفی_الاوسط","label":"وفي الأوسط","number":8024},{"key":"ahmad","label":"مسند الإمام أحمد","number":15414,"n":15414},{"key":"sh12520","label":"مسند أبي يعلى","number":928,"n":926}]},{"num":4972,"demo":false,"sanad":"","matn":["عن عبيد بن جريج أنه قال لعبد الله بن عمر: يا أبا عبد الرحمن، رأيتُك تصنع أربعًا لم أرَ أحدًا من أصحابك يصنعها! قال: وما هنَّ يا ابن جريج؟ قال: رأيتُك لا تمسُّ من الأركان إلا اليمانيين، ورأيتُك تلبس النعال السِّبتية، ورأيتُك تصبغ بالصُّفرة، ورأيتُك إذا كنتَ بمكة أهلَّ الناسُ إذا رأوا الهلال ولم تُهِلَّ أنت حتى يكون يوم التروية؟ فقال عبد الله بن عمر: أمّا الأركان فإني لم أرَ رسول الله ﷺ يمسُّ إلا اليمانيين، وأمّا النعال السِّبتية فإني رأيتُ رسول الله ﷺ يلبس النعال التي ليس فيها شعر ويتوضأ فيها، فأنا أحب أن ألبسها، وأمّا الصُّفرة فإني رأيتُ رسول الله ﷺ يصبغ بها فأنا أحب أن أصبغ بها، وأمّا الإهلال فإني لم أرَ رسول الله ﷺ يُهِلُّ حتى تنبعث به راحلته."],"takhrij":"متفق عليه: رواه مالك (٣١) والبخاريّ (١٦٦)، ومسلم (١١٨٧).","grade":"متفق عليه","chapter_ar":"باب استحباب استلام الركن اليماني ومسحه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (31), al-Bukhari (166), and Muslim (1187).","chapter_en":"The recommendation of touching and wiping the Yemeni Corner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":30,"content":{"translation":{"en":["‘Ubayd ibn Jurayj said to ‘Abd Allah ibn ‘Umar: O Abu ‘Abd al-Rahman, I saw you doing four things that I have not seen any of your companions doing. He said: What are they, O Ibn Jurayj? He said: I saw you not touch any of the corners except the two Yemeni corners. I saw you wearing hairless leather sandals. I saw you dyeing with yellow color. And I saw that when you were in Mecca, the people entered consecration when they saw the new moon, while you did not enter consecration until the Day of Tarwiyah. So ‘Abd Allah ibn ‘Umar said: As for the corners, I never saw the Messenger of Allah ﷺ touch any except the two Yemeni corners. As for the hairless leather sandals, I saw the Messenger of Allah ﷺ wear sandals that had no hair on them and make ablution in them, so I like to wear them. As for the yellow dye, I saw the Messenger of Allah ﷺ dye with it, so I like to dye with it. As for entering consecration, I never saw the Messenger of Allah ﷺ enter consecration until his mount set out with him."]},"buhuth":{"ar":["قوله: (( إلا اليمانيين )) قال النوويّ في شرح مسلم (٩٣/٨): (( والمراد بالركنين اليمانيين: الركن اليماني والركن الذي فيه الحجر الأسود… ويقال لهما اليمانيان تغليبًا لأحد الاسمين… فاليمانيان باقيان على قواعد إبراهيم بخلاف الشاميين؛ فلهذا لم يُستَلَما واستُلِم اليمانيان… قال القاضي عياض: وقد اتفق أئمة الأمصار والفقهاء اليوم على أن الركنين الشاميين لا يُستلمان، وإنما كان الخلاف في ذلك العصر الأول من بعض الصحابة وبعض التابعين، ثم ذهب ))."],"en":["His statement, “except the two Yemeni corners”: al-Nawawi said in his commentary on Muslim (8/93): “What is meant by the two Yemeni corners is the Yemeni corner and the corner in which the Black Stone is set. They are both called the two Yemeni corners by predominance of one of the two names. These two remain upon the foundations of Abraham, unlike the two Syrian corners. For that reason the two Yemeni corners were touched, while the two Syrian corners were not. Al-Qadi ‘Iyad said: The leading scholars of the regions and the jurists today are agreed that the two Syrian corners are not to be touched. The disagreement about that only existed in the earliest period among some of the Companions and some of the Followers, then it disappeared.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":31},{"key":"bukhari","label":"البخاريّ","number":166},{"key":"muslim","label":"مسلم","number":1187}]},{"num":4973,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: ما تركتُ استلام هذين الركنين اليماني والحجر منذ رأيتُ رسولَ اللّٰه ﷺ يستلمهما في شدّةٍ ولا رخاءٍ."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٠٦)، ومسلم (١٢٦٨). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب استحباب استلام الركن اليماني ومسحه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1606) and Muslim (1268). This is the wording of Muslim.","chapter_en":"The recommendation of touching and wiping the Yemeni Corner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":30,"content":{"translation":{"en":["Ibn ‘Umar said: I have never left touching these two corners, the Yemeni Corner and the Black Stone, since I saw the Messenger of Allah ﷺ touching them, in hardship or in ease."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1606},{"key":"muslim","label":"مسلم","number":1268}]},{"num":4974,"demo":false,"sanad":"","matn":["عن ابن عمر، أنه قال: لم أرَ رسولَ اللّٰه ﷺ يمسحُ من البيت إلا الركنين اليمانيين."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٠٩)، ومسلم (١٢٦٧).","grade":"متفق عليه","chapter_ar":"باب استحباب استلام الركن اليماني ومسحه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1609) and Muslim (1267).","chapter_en":"The recommendation of touching and wiping the Yemeni Corner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":30,"content":{"translation":{"en":["Ibn ‘Umar said: I did not see the Messenger of Allah ﷺ wipe any part of the House except the two Yemeni corners."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1609},{"key":"muslim","label":"مسلم","number":1267}]},{"num":4975,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: كان رسولُ اللّٰه ﷺ لا يدع أن يستلم الركن اليماني، والحجر في كلّ طواف."],"takhrij":"حسن: رواه أبو داود (١٨٧٦)، والنسائيّ (٢٩٥٠)، وأحمد (٤٦٨٦)، وصحّحه ابن خزيمة (٢٧٢٣).","grade":"حسن","chapter_ar":"باب استحباب استلام الركن اليماني ومسحه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1876), al-Nasa’i (2950), Ahmad (4686), and authenticated by Ibn Khuzaymah (2723).","chapter_en":"The recommendation of touching and wiping the Yemeni Corner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":30,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ would not leave off touching the Yemeni Corner and the Black Stone in every circumambulation."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1876},{"key":"nasai","label":"النسائيّ","number":2950},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2723},{"key":"ahmad","label":"مسند الإمام أحمد","number":4686,"n":4686}]},{"num":4976,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، قال: لم أرَ رسولَ اللّٰه ﷺ يستلم غير الركنين اليمانيين."],"takhrij":"صحيح: رواه مسلم (١٢٦٩).","grade":"صحيح","chapter_ar":"باب استحباب استلام الركن اليماني ومسحه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1269).","chapter_en":"The recommendation of touching and wiping the Yemeni Corner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":30,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas said: I did not see the Messenger of Allah ﷺ touch any corners other than the two Yemeni corners."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1269}]},{"num":4977,"demo":false,"sanad":"","matn":["عن أبي الطفيل، قال: كنتُ مع ابن عباس، ومعاويةُ لا يمرّ بركنٍ إلا استلمه، فقال له ابنُ عباس: إنّ النبيَّ ﷺ لم يكن يستلم إلا الحجر الأسود، والركن اليماني.","فقال معاوية: ليس شيءٌ من البيت مهجورًا."],"takhrij":"صحيح: رواه الترمذيّ (٨٥٨)، والإمام أحمد (٣٠٧٤)، وعبد الرزاق في مصنفه (٨٩٤٤).","grade":"صحيح","chapter_ar":"باب استحباب استلام الركن اليماني ومسحه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (858), Imam Ahmad (3074), and ‘Abd al-Razzaq in his Musannaf (8944).","chapter_en":"The recommendation of touching and wiping the Yemeni Corner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":30,"content":{"translation":{"en":["Abu al-Tufayl said: I was with Ibn ‘Abbas, and Mu‘awiyah would not pass by any corner without touching it. So Ibn ‘Abbas said to him: The Prophet ﷺ only used to touch the Black Stone and the Yemeni Corner.","Mu‘awiyah replied: No part of the House is to be neglected."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":858},{"key":"الامام_احمد","label":"الإمام أحمد","number":3074},{"key":"عبد_الرزاق/مصنفہ","label":"عبد الرزاق في مصنفه","number":8944},{"key":"ahmad","label":"مسند الإمام أحمد","number":3074,"n":3074}]},{"num":4978,"demo":false,"sanad":"","matn":["عن عائشة، أنّ النبيّ ﷺ قال: (( أَلَمْ تَرَيْ أَنَّ قَوْمَكِ حِينَ بَنَوْا الْكَعْبَةَ اقْتَصَرُوا عَنْ قَوَاعِدِ إِبْرَاهِيمَ؟ )) قالت: فقلتُ: يا رسولَ اللّٰه، أفلا تردّها على قواعد إبراهيم؟ فقال رسولُ اللّٰه ﷺ: (( لولا حِدْثَانُ قومِكِ بالكفر لفعلتُ )).","قال: فقال عبدُ اللّٰه بنُ عمر: لئن كانت عائشةُ سمعتْ هذا من رسولِ اللّٰه ﷺ، ما أرى رسولَ اللّٰه ﷺ ترك استلام الركنين اللذين يليان الحِجر إلا أن البيت لم يُتمَّمْ على قواعد إبراهيم."],"takhrij":"متفق عليه: رواه مالك (١٠٩)، والبخاريّ (١٥٨٣)، ومسلم (١٣٣٣:٣٩٩).","grade":"متفق عليه","chapter_ar":"باب ترك استلام الركنين اللذين يليان الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (109), al-Bukhari (1583), and Muslim (1333:399).","chapter_en":"Leaving the touching of the two corners adjacent to the enclosure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":31,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ said: “Do you not see that your people, when they built the Ka‘bah, fell short of the foundations of Abraham?” She said: I said: O Messenger of Allah ﷺ, will you not return it to the foundations of Abraham? The Messenger of Allah ﷺ said: “Were it not for the fact that your people have only recently left disbelief, I would have done so.”","Then ‘Abd Allah ibn ‘Umar said: If ‘A’ishah heard this from the Messenger of Allah ﷺ, then I do not think the Messenger of Allah ﷺ left touching the two corners next to the enclosure except because the House was not completed upon the foundations of Abraham."]},"buhuth":{"ar":["والحِجر - بكسر الجيم - هو الموضع المسمّى بالحطيم."],"en":["The enclosure, with the letter pronounced with a kasrah, is the place known as al-Hatim."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":109},{"key":"bukhari","label":"البخاريّ","number":1583},{"key":"muslim","label":"مسلم","number":1333}]},{"num":4979,"demo":false,"sanad":"","matn":["عن ابن عمر، أنه أُخبر بقول عائشة رضي اللّٰه عنها: إنّ الحِجر بعضه من البيت. فقال ابن عمر: واللهِ إنِّي لأظنُّ عائشةَ إن كانت سمعتْ هذا من رسولِ اللّٰه ﷺ، إنِّي لأظنّ رسولَ اللّٰه ﷺ لم يترك استلامهما إلا أنهما ليسا على قواعد البيت، ولا طاف الناس وراء الحِجر إلا لذلك."],"takhrij":"صحيح: رواه أبو داود (١٨٧٥).","grade":"صحيح","chapter_ar":"باب ترك استلام الركنين اللذين يليان الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1875).","chapter_en":"Leaving the touching of the two corners adjacent to the enclosure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":31,"content":{"translation":{"en":["Ibn ‘Umar was informed of the statement of ‘A’ishah, may Allah be pleased with her, that the enclosure is part of the House. Ibn ‘Umar said: By Allah, if ‘A’ishah indeed heard this from the Messenger of Allah ﷺ, then I believe the Messenger of Allah ﷺ only left touching those two corners because they are not upon the foundations of the House, and the people only circumambulate outside the enclosure because of that."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1875}]},{"num":4980,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، قال: ما طاف رسولُ اللّٰه ﷺ بشيءٍ إلا وهو من البيت."],"takhrij":"صحيح: رواه أبو يعلى (٢٥٦٦).","grade":"صحيح","chapter_ar":"باب ترك استلام الركنين اللذين يليان الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Ya‘la (2566).","chapter_en":"Leaving the touching of the two corners adjacent to the enclosure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":31,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas said: The Messenger of Allah ﷺ did not circumambulate anything except that it was part of the House."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":2566},{"key":"sh12520","label":"مسند أبي يعلى","number":2566,"n":2570}]},{"num":4981,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: الحِجر من البيت؛ لأنّ رسولَ اللّٰه ﷺ طاف بالبيت من ورائه، وقال اللّٰه: ( وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ ) [سورة الحج: ٢٩]."],"takhrij":"حسن: رواه ابن خزيمة (٢٧٤٠).","grade":"حسن","chapter_ar":"باب ترك استلام الركنين اللذين يليان الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (2740).","chapter_en":"Leaving the touching of the two corners adjacent to the enclosure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":31,"content":{"translation":{"en":["Ibn ‘Abbas said: The enclosure is part of the House, because the Messenger of Allah ﷺ circumambulated the House from outside it, and Allah said: “And let them circumambulate the Ancient House.” [Surat al-Hajj: 29]"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2740}]},{"num":4982,"demo":false,"sanad":"","matn":["عن يعلى قال: طُفتُ مع عمر بن الخطاب، فلما كنتُ عند الركن الذي يلي الباب مما يلي الحِجر، أخذتُ بيده ليستلمه، فقال: أما طفتَ مع رسولِ اللّٰه ﷺ؟ قلت: بلى. قال: فهل رأيتَه يستلمه؟ قلت: لا. قال: فانفذْ عنك، فإنّ لك في رسولِ اللّٰه ﷺ أسوةً حسنةً."],"takhrij":"صحيح: رواه الإمام أحمد (٢٥٣)، وأبو يعلى (١٨٢).","grade":"صحيح","chapter_ar":"باب ترك استلام الركنين اللذين يليان الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (253) and Abu Ya‘la (182).","chapter_en":"Leaving the touching of the two corners adjacent to the enclosure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":31,"content":{"translation":{"en":["Ya‘la said: I circumambulated with ‘Umar ibn al-Khattab, and when I came to the corner near the door, the one by the enclosure, I took his hand so that he might touch it. He said: Did you not circumambulate with the Messenger of Allah ﷺ? I said: Yes. He said: Did you see him touch it? I said: No. He said: Then move on, for you have in the Messenger of Allah ﷺ an excellent example."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":253},{"key":"ابو_یعلی","label":"أبو يعلى","number":182},{"key":"ahmad","label":"مسند الإمام أحمد","number":253,"n":253},{"key":"sh12520","label":"مسند أبي يعلى","number":182,"n":180}]},{"num":4983,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن السائب، قال: سمعتُ رسولَ اللّٰه ﷺ يقول ما بين الركنين: ( رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ) [سورة البقرة: ٢٠١]."],"takhrij":"حسن: رواه أبو داود (١٨٩٢)، وصحّحه ابن خزيمة (٢٧٢١)، والحاكم (١٦٧٣).","grade":"حسن","chapter_ar":"باب ما يدعو به بين الركن اليماني والحجر الأسود","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1892), authenticated by Ibn Khuzaymah (2721), and al-Hakim (1673).","chapter_en":"What is supplicated between the Yemeni Corner and the Black Stone","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":32,"content":{"translation":{"en":["‘Abd Allah ibn al-Sa’ib said: I heard the Messenger of Allah ﷺ say between the two corners: “Our Lord, grant us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.” [Surat al-Baqarah: 201]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1892},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2721},{"key":"hakim","label":"المستدرك على الصحيحين","number":1673,"n":1663}]},{"num":4984,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قال رسولُ اللّٰه ﷺ في الحجر: (( وَاللّٰهِ لَيَبْعَثَنَّهُ اللَّهُ يَوْمَ الْقِيَامَةِ، لَهُ عَيْنَانِ يُبْصِرُ بِهِمَا، وَلِسَانٌ يَنْطِقُ بِهِ، يَشْهَدُ عَلَى مَنِ اسْتَلَمَهُ بِحَقٍّ ))."],"takhrij":"حسن: رواه الترمذيّ (٩٦١)، وابن ماجه (٢٩٤٤)، وأحمد (٢٦٤٣، ٢٣٩٨، ٢٢١٥)، وصحّحه ابن خزيمة (٢٧٣٥).","grade":"حسن","chapter_ar":"باب إنّ الحجر الأسود يشهد يوم القيامة لمن استلمه بحق","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (961), Ibn Majah (2944), Ahmad (2643, 2398, 2215), and authenticated by Ibn Khuzaymah (2735).","chapter_en":"The Black Stone will testify on the Day of Resurrection for the one who touched it rightly","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":33,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said concerning the Stone: “By Allah, Allah will surely raise it on the Day of Resurrection, and it will have two eyes by which it sees and a tongue by which it speaks, testifying in favor of the one who touched it with truth.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":961},{"key":"ibnmajah","label":"ابن ماجه","number":2944},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2735},{"key":"ahmad","label":"مسند الإمام أحمد","number":2643,"n":2643}]},{"num":4985,"demo":false,"sanad":"","matn":["عن جعفر بن عبد اللّٰه بن عثمان، قال: رأيتُ محمدَ بنَ عبادِ بنِ جعفرٍ يستلم الحجر ثم يُقبِّلُه ويسجدُ عليه، فقلتُ له: ما هذا؟ فقال: رأيتُ خالكَ عبدَ اللّٰه بن عباسٍ يفعله. ثم قال: رأيتُ عمرَ فعله. ثم قال: إنِّي لأعلمُ أنّكَ حجرٌ، ولكنِّي رأيتُ رسولَ اللّٰه ﷺ يفعل هذا."],"takhrij":"حسن: رواه الدارميّ (١٩٠٧)، وابن خزيمة (٢٧١٤)، والبزار - كشف الأستار (١١١٤).","grade":"حسن","chapter_ar":"باب السجود على الحجر الأسود","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (1907), Ibn Khuzaymah (2714), and al-Bazzar in Kashf al-Astar (1114).","chapter_en":"Prostrating on the Black Stone","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":34,"content":{"translation":{"en":["Ja‘far ibn ‘Abd Allah ibn ‘Uthman said: I saw Muhammad ibn ‘Abbad ibn Ja‘far touch the Stone, then kiss it and prostrate upon it. I said to him: What is this? He said: I saw your maternal uncle, ‘Abd Allah ibn ‘Abbas, doing it. Then he said: I saw ‘Umar ibn al-Khattab doing it. Then he said: I certainly know that you are a stone, but I saw the Messenger of Allah ﷺ do this."]}},"tuhfa":{},"refs":[{"key":"darimi","label":"الدارميّ","number":1907},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2714},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1114}]},{"num":4986,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن عوف، قال: قال لي النبيُّ ﷺ: (( كيف صنعتَ في استلام الحجر؟ )) فقلتُ: استلمتُ وتركتُ. قال النبيُّ ﷺ: (( أصبتَ ))."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (٣٨٢٣)، والبزار (١١١٣)، والطبراني في الصغير (٦٥٠).","grade":"صحيح","chapter_ar":"باب في ترك استلام الحجر الأسود عند الزحام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban in his Sahih (3823), al-Bazzar (1113), and al-Tabarani in al-Saghir (650).","chapter_en":"Leaving the touching of the Black Stone when there is crowding","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":35,"content":{"translation":{"en":["‘Abd al-Rahman ibn ‘Awf said: The Prophet ﷺ said to me: “How did you act regarding touching the Stone?” I said: I touched it sometimes and left it sometimes. The Prophet ﷺ said: “You did the right thing.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":3823},{"key":"البزار","label":"البزار","number":1113},{"key":"الطبرانی/الصغیر","label":"الطبراني في الصغير","number":650},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5857,"n":5854},{"key":"sh13068","label":"المعجم الصغير للطبراني","number":650,"n":650}]},{"num":4987,"demo":false,"sanad":"","matn":["عن عروة بن الزبير، قال: أخبرتني عائشة رضي اللّٰه عنها: أَنَّ أَوَّلَ شَيْءٍ بَدَأَ بِهِ حِينَ قَدِمَ النَّبِيُّ ﷺ أَنَّهُ تَوَضَّأَ، ثُمَّ طَافَ، ثُمَّ لَمْ تَكُنْ عُمْرَةً، ثُمَّ حَجَّ أَبُو بَكْرٍ وَعُمَرُ رضي اللّٰه عنهما مِثْلَهُ، ثُمَّ حَجَجْتُ مَعَ أَبِي: الزُّبَيْرِ رضي اللّٰه عنه، فَأَوَّلُ شَيْءٍ بَدَأَ بِهِ الطَّوَافُ، ثُمَّ رَأَيْتُ الْمُهَاجِرِينَ وَالْأَنْصَارَ يَفْعَلُونَهُ، وَقَدْ أَخْبَرَتْنِي أُمِّي أَنَّهَا أَهَلَّتْ هِيَ وَأُخْتُهَا وَالزُّبَيْرُ وَفُلَانٌ وَفُلَانٌ بِعُمْرَةٍ، فَلَمَّا مَسَحُوا الرُّكْنَ حَلُّوا."],"takhrij":"متفق عليه: رواه البخاريّ (١٦١٤)، ومسلم (١٢٣٥)، والسياق للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب في طواف القدوم في الحجّ والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1614) and Muslim (1235), and the wording is that of al-Bukhari.","chapter_en":"The arrival circumambulation in the pilgrimage and the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":36,"content":{"translation":{"en":["‘Urwah ibn al-Zubayr said: ‘A’ishah, may Allah be pleased with her, told me that the first thing the Prophet ﷺ began with when he arrived was that he made ablution, then circumambulated. Then it was not a lesser pilgrimage. Then Abu Bakr and ‘Umar performed pilgrimage in the same way. Then I performed pilgrimage with my father al-Zubayr, and the first thing he began with was circumambulation. Then I saw the Emigrants and the Helpers doing that. And my mother told me that she, her sister, al-Zubayr, and this one and that one had entered consecration for a lesser pilgrimage, and when they had touched the Corner, they came out of consecration."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1614},{"key":"muslim","label":"مسلم","number":1235}]},{"num":4988,"demo":false,"sanad":"","matn":["عن ابن عمر: أنّ رسولَ اللّٰه ﷺ كان إذا طاف في الحجّ أو العمرة أوّل ما يقدم، سعى ثلاثة أطوافٍ، ومشى أربعةً، ثم سجد سجدتين، ثم يطوف بين الصفا والمروة."],"takhrij":"متفق عليه: رواه البخاريّ (١٦١٦)، ومسلم (١٢٦١:٢٣١).","grade":"متفق عليه","chapter_ar":"باب في طواف القدوم في الحجّ والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1616) and Muslim (1261:231).","chapter_en":"The arrival circumambulation in the pilgrimage and the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":36,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Messenger of Allah ﷺ circumambulated in pilgrimage or lesser pilgrimage upon first arrival, he would hasten in three circuits and walk in four, then pray two units, then go between al-Safa and al-Marwah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1616},{"key":"muslim","label":"مسلم","number":1261}]},{"num":4989,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن أبي أوفى، قال: اعتمرَ رسولُ اللّٰه ﷺ واعتمرنا معه، فلما دخل مكة طاف وطفنا معه، وأتى الصفا والمروة وأتيناها معه، وكنا نستره من أهل مكة أن يرميه أحد.","قال له صاحبٌ لي: أكان دخل الكعبة؟ قال: لا."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٩١)، ومسلم (١٣٣٢).","grade":"متفق عليه","chapter_ar":"باب في طواف القدوم في الحجّ والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1791) and Muslim (1332).","chapter_en":"The arrival circumambulation in the pilgrimage and the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":36,"content":{"translation":{"en":["‘Abd Allah ibn Abi Awfa said: The Messenger of Allah ﷺ performed the lesser pilgrimage, and we performed it with him. When he entered Mecca, he circumambulated, and we circumambulated with him. He came to al-Safa and al-Marwah, and we came with him, and we were shielding him from the people of Mecca lest anyone throw something at him.","A companion of mine said to him: Did he enter the Ka‘bah? He said: No."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1791},{"key":"muslim","label":"مسلم","number":1332}]},{"num":4990,"demo":false,"sanad":"","matn":["عن وَبَرَة، قال: كُنْتُ جَالِسًا عِنْدَ ابْنِ عُمَرَ، فَجَاءَهُ رَجُلٌ فَقَالَ: أَيَصْلُحُ لِي أَنْ أَطُوفَ بِالْبَيْتِ قَبْلَ أَنْ آتِيَ الْمَوْقِفَ؟ فَقَالَ: نَعَمْ. فَقَالَ: فَإِنَّ ابْنَ عَبَّاسٍ يَقُولُ: لا تَطُفْ بِالْبَيْتِ حَتَّى تَأْتِيَ الْمَوْقِفَ؟ فَقَالَ ابْنُ عُمَرَ: فَقَدْ حَجَّ رَسُولُ الله ﷺ، فَطَافَ بِالْبَيْتِ قَبْلَ أَنْ يَأْتِيَ الْمَوْقِفَ، فَبِقَوْلِ رَسُولِ الله ﷺ أَحَقُّ أَنْ تَأْخُذَ أَوْ بِقَوْلِ ابْنِ عَبَّاسٍ إِنْ كُنْتَ صَادِقًا؟!"],"takhrij":"صحيح: رواه مسلم (١٢٣٣). ورواه أيضًا قال: سَأَلَ رَجُلٌ ابْنَ عُمَرَ رضي اللّٰه عنهما: أَطُوفُ بِالْبَيْتِ وَأَنَا أَهَلْتُ بِالْحَجِّ؟ فَقَالَ: فَمَا يَمْنَعُكَ؟ قَالَ: إِنِّي رَأَيْتُ ابْنَ فُلَانٍ يَكْرَهُهُ، وَأَنْتَ أَحَبُّ إِلَيْنَا مِنْهُ. رَأَهُ فَتَنَتْهُ الدُّنْيَا. فَقَالَ: وَأَيُّنَا أَوْ أَيُّكُمْ لَمْ تَفْتِنْهُ الدُّنْيَا؟ ثُمَّ قَالَ: رَأَيْنَا رَسُولَ اللّٰه ﷺ أَحْرَمَ بِالْحَجِّ، وَطَافَ بِالْبَيْتِ، وَسَعَى بَيْنَ الصَّفَا وَالْمَرْوَةِ؛ فَسُنَّةُ اللّٰهِ وَسُنَّةُ رَسُولِهِ ﷺ أَحَقُّ أَنْ تُتَّبَعَ مِنْ سُنَّةِ فُلَانٍ إِنْ كُنْتَ صَادِقًا.","grade":"صحيح","chapter_ar":"باب في طواف القدوم في الحجّ والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1233). It was also narrated that a man asked Ibn ‘Umar, may Allah be pleased with them both, “May I circumambulate the House while I have entered into pilgrimage?” He said, “What is preventing you?” He said, “I saw so-and-so disliking it, and you are more beloved to us than him. The world tested him.” He said, “Which of us, or which of you, has not been tested by the world?” Then he said, “We saw the Messenger of Allah ﷺ enter into pilgrimage, circumambulate the House, and go between al-Safa and al-Marwah. So the way of Allah and the way of His Messenger ﷺ are more deserving to be followed than the way of so-and-so, if you are truthful.”","chapter_en":"The arrival circumambulation in the pilgrimage and the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":36,"content":{"translation":{"en":["Wabarah said: I was sitting with Ibn ‘Umar when a man came to him and said, “Is it valid for me to circumambulate the House before I go to the standing place?” He said, “Yes.” The man said, “But Ibn ‘Abbas says: Do not circumambulate the House until you go to the standing place.” Ibn ‘Umar said, “The Messenger of Allah ﷺ performed pilgrimage, and he circumambulated the House before he went to the standing place. So whose statement is more deserving to be followed: the statement of the Messenger of Allah ﷺ or the statement of Ibn ‘Abbas, if you are truthful?”"]},"buhuth":{"ar":["قلت: وما نسبه السائل لابن عباس، فالظاهر منه أنه يريد بالطواف طواف الإفاضة؛ لأنه لا يخفى على السائل أن رسول الله ﷺ طاف بالبيت أول قدومه إلى مكة في حجة الوداع، وقد كان طاف معه كما في الصحيحين."],"en":["I say: What the questioner attributed to Ibn ‘Abbas apparently refers to the main circumambulation of the pilgrimage, because it would not have been hidden from the questioner that the Messenger of Allah ﷺ circumambulated the House when he first arrived in Mecca during the Farewell Pilgrimage, and he had circumambulated with him, as reported in the two Sahihs."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1233}]},{"num":4991,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه قال: طُفْتُ مَعَ عبد الله بن عمرو بن العاص، فَلَمَّا جِئْنَا دُبُرَ الْكَعْبَةِ قُلْتُ: أَلَا تَتَعَوَّذُ؟ قَالَ: نَعُوذُ بِاللَّهِ مِنَ النَّارِ. ثُمَّ مَضَى حَتَّى اسْتَلَمَ الْحَجَرَ، وَأَقَامَ بَيْنَ الرُّكْنِ وَالْبَابِ، فَوَضَعَ صَدْرَهُ وَوَجْهَهُ وَذِرَاعَيْهِ وَكَفَّيْهِ هَكَذَا، وَبَسَطَهُمَا بَسْطًا، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللّٰهِ ﷺ يَفْعَلُهُ."],"takhrij":"حسن: رواه أبو داود (١٨٩٩)، وابن ماجه (٢٩٦٢)، واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ما جاء في الوقوف عند الملتزم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1899) and Ibn Majah (2962), and the wording is that of Abu Dawud.","chapter_en":"What has been narrated about standing at the Multazam","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":37,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, said: I circumambulated with ‘Abd Allah ibn ‘Amr ibn al-‘As. When we reached the back of the Ka‘bah, I said, “Will you not seek refuge?” He said, “We seek refuge in Allah from the Fire.” Then he went on until he touched the Stone, and stood between the Corner and the Door. Then he placed his chest, his face, his forearms, and his palms like this, spreading them out, then said, “This is how I saw the Messenger of Allah ﷺ do it.”"]},"buhuth":{"ar":["وفي لفظ ابن ماجه، قال: طُفْتُ مَعَ عبد الله بن عمرو، فلما فرغنا من السبع ركعنا في دبر الكعبة، فقلت: (فذكره)."],"en":["In the wording of Ibn Majah, he said: I circumambulated with ‘Abd Allah ibn ‘Amr, and when we finished the seven circuits, we prayed behind the Ka‘bah, and I said: then he mentioned it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1899},{"key":"ibnmajah","label":"ابن ماجه","number":2962}]},{"num":4992,"demo":false,"sanad":"","matn":["عن عائشة، قالت: سَأَلْتُ رَسُولَ الله ﷺ عَن الْجَدْرِ أَمِنَ الْبَيْتِ هُوَ؟ قَالَ: (( نَعَمْ )). قُلْتُ: فَلِمَ لَمْ يُدْخِلُوهُ فِي الْبَيْتِ؟ قَالَ: (( إِنَّ قَوْمَكِ قَصَّرَتْ بِهِمُ النَّفَقَةُ )). قُلْتُ: فَمَا شَأْنُ بَابِهِ مُرْتَفِعًا؟ قَالَ: (( فَعَلَ ذَلِكِ قَوْمُكِ لِيُدْخِلُوا مَنْ شَاءُوا وَيَمْنَعُوا مَنْ شَاءُوا، وَلَوْلَا أَنَّ قَوْمَكِ حَدِيثٌ عَهْدُهُمْ فِي الْجَاهِلِيَّةِ، فَأَخَافُ أَنْ تُنْكِرَ قُلُوبُهُمْ، لَنَظَرْتُ أَنْ أُدْخِلَ الْجَدْرَ فِي الْبَيْتِ، وَأَنْ أُلْزِقَ بَابَهُ بِالْأَرْضِ ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٨٤)، ومسلم (١٣٣٣ : ٤٠٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1584) and Muslim (1333:405).","chapter_en":"What has been narrated about the enclosure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":38,"content":{"translation":{"en":["‘A’ishah said: I asked the Messenger of Allah ﷺ about the wall enclosure: “Is it part of the House?” He said, “Yes.” I said, “Then why did they not include it in the House?” He said, “Your people fell short in funds.” I said, “Then why is its door raised?” He said, “Your people did that so they could admit whom they wished and prevent whom they wished. Were it not that your people are newly removed from the time of ignorance, and I fear their hearts would reject it, I would have included the enclosure in the House and placed its door level with the ground.”"]},"buhuth":{"ar":["والجدر: هو حِجْر الكعبة، كما عند مسلم: (( سألتُ رسولَ اللّٰه ﷺ عن الحِجْرِ ))."],"en":["The word al-jadr here means the enclosure of the Ka‘bah, as found in Muslim: “I asked the Messenger of Allah ﷺ about the enclosure.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1584},{"key":"muslim","label":"مسلم","number":1333}]},{"num":4993,"demo":false,"sanad":"","matn":["عن سعيد بن ميناء، قال: سمعتُ ابن الزبير يقول وهو على المنبر حين أراد أن يهدم الكعبة ويبنيها: حدّثتني عائشة خالتي، أنَّ رسولَ اللّٰه ﷺ قال لها: (( يَا عَائِشَةُ، لَوْلَا أَنَّ قَوْمَكِ حَدِيثُو عَهْدٍ بِشِرْكٍ، لَهَدَمْتُ الْكَعْبَةَ فَأَلْزَقْتُهَا بِالْأَرْضِ، وَجَعَلْتُ لَهَا بَابَيْنِ: بَابًا شَرْقِيًّا وَبَابًا غَرْبِيًّا، وَزِدْتُ فِيهَا سِتَّةَ أَذْرُعٍ مِنَ الْحِجْرِ، فَإِنَّ قُرَيْشًا اقْتَصَرَتْهَا حَيْثُ بَنَتِ الْكَعْبَةَ ))."],"takhrij":"صحيح: رواه مسلم (١٣٣٣ : ٤٠١).","grade":"صحيح","chapter_ar":"باب نقض الكعبة وبنائها على قواعد إبراهيم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1333:401).","chapter_en":"Demolishing the Kaʿbah and rebuilding it upon the foundations of Ibrahim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":40,"content":{"translation":{"en":["Sa‘id ibn Mina’ said: I heard Ibn al-Zubayr saying from the pulpit, when he intended to demolish the Ka‘bah and rebuild it: My maternal aunt ‘A’ishah narrated to me that the Messenger of Allah ﷺ said to her: “O ‘A’ishah, were it not that your people have only recently left idolatry, I would have demolished the Ka‘bah, placed it level with the ground, made for it two doors, one eastern and one western, and added six cubits from the enclosure to it, for Quraysh reduced it when they built the Ka‘bah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1333}]},{"num":4994,"demo":false,"sanad":"","matn":["عن عطاء قال: لما احْتَرَقَ الْبَيْتُ زَمَنَ يَزِيدَ بْنِ مُعَاوِيَةَ حِينَ غَزَاهَا أَهْلُ الشَّامِ، فَكَانَ مِنْ أَمْرِهِ مَا كَانَ، تَرَكَهُ ابْنُ الزُّبَيْرِ حَتَّى قَدِمَ النَّاسُ الْمَوْسِمَ، يُرِيدُ أَنْ يُجَرِّئَهُمْ - أَوْ يُحَرِّبَهُمْ - عَلَى أَهْلِ الشَّامِ، فَلَمَّا صَدَرَ النَّاسُ، قَالَ: يَا أَيُّهَا النَّاسُ، أَشِيرُوا عَلَيَّ فِي الْكَعْبَةِ، أَنْقُضُهَا ثُمَّ أَبْنِي بِنَاءَهَا أَوْ أُصْلِحُ مَا وَهَى مِنْهَا؟ قَالَ ابْنُ عَبَّاسٍ: فَإِنِّي قَدْ فُرِقَ لِي رَأْيٌ فِيهَا، أَرَى أَنْ تُصْلِحَ مَا وَهَى مِنْهَا وَتَدَعَ بَيْتًا أَسْلَمَ النَّاسُ عَلَيْهِ، وَأَحْجَارًا أَسْلَمَ النَّاسُ عَلَيْهَا، وَبُعِثَ عَلَيْهَا النَّبِيُّ ﷺ. فَقَالَ ابْنُ الزُّبَيْرِ: لَوْ كَانَ أَحَدُكُمْ احْتَرَقَ بَيْتُهُ مَا رَضِيَ حَتَّى يُجِدَّهُ، فَكَيْفَ بَيْتُ رَبِّكُمْ؟! إِنِّي مُسْتَخِيرٌ رَبِّي ثَلاثًا، ثُمَّ عَازِمٌ عَلَى أَمْرِي. فَلَمَّا مَضَى الثَّلاثُ أَجْمَعَ رَأْيَهُ عَلَى أَنْ يَنْقُضَهَا، فَتَحَامَاهُ النَّاسُ أَنْ يَنْزِلَ بِأَوَّلِ النَّاسِ يَصْعَدُ فِيهِ أَمْرٌ مِنَ السَّمَاءِ، حَتَّى صَعِدَهُ رَجُلٌ فَأَلْقَى مِنْهُ حِجَارَةً، فَلَمَّا لَمْ يَرَهُ النَّاسُ أَصَابَهُ شَيْءٌ تَتَابَعُوا فَنَقَضُوهُ حَتَّى بَلَغُوا بِهِ الْأَرْضَ، فَجَعَلَ ابْنُ الزُّبَيْرِ أَعْمِدَةً فَسَتَّرَ عَلَيْهَا السُّتُورَ حَتَّى ارْتَفَعَ بِنَاؤُهُ. وَقَالَ ابْنُ الزُّبَيْرِ: إِنِّي سَمِعْتُ عَائِشَةَ تَقُولُ: إِنَّ النَّبِيَّ ﷺ قَالَ: (( لَوْلَا أَنَّ النَّاسَ حَدِيثُ عَهْدِهِمْ بِكُفْرٍ، وَلَيْسَ عِنْدِي مِنَ النَّفَقَةِ مَا يُقَوِّي عَلَى بِنَائِهِ، لَكُنْتُ أَدْخَلْتُ فِيهِ مِنَ الْحِجْرِ خَمْسَةَ أَذْرُعٍ، وَلَجَعَلْتُ لَهَا بَابًا يَدْخُلُ النَّاسُ مِنْهُ، وَبَابًا يَخْرُجُونَ مِنْهُ )). قَالَ: فَأَنَا الْيَوْمَ أَجِدُ مَا أُنْفِقُ، وَلَسْتُ أَخَافُ النَّاسَ. قَالَ: فَزَادَ فِيهِ خَمْسَةَ أَذْرُعٍ مِنَ الْحِجْرِ، حَتَّى أَبْدَى أُسًّا نَظَرَ النَّاسُ إِلَيْهِ، فَبَنَى عَلَيْهِ الْبِنَاءَ. وَكَانَ طُولُ الْكَعْبَةِ ثَمَانِيَ عَشْرَةَ ذِرَاعًا، فَلَمَّا زَادَ فِيهِ اسْتَقْصَرَهُ، فَزَادَ فِي طُولِهِ عَشْرَ أَذْرُعٍ، وَجَعَلَ لَهَا بَابَيْنِ، أَحَدُهُمَا يُدْخَلُ مِنْهُ وَالْآخَرُ يُخْرَجُ مِنْهُ. فَلَمَّا قُتِلَ ابْنُ الزُّبَيْرِ، كَتَبَ الْحَجَّاجُ إِلَى عَبْدِ الْمَلِكِ بْنِ مَرْوَانَ يُخْبِرُهُ بِذَلِكَ، وَيُخْبِرُهُ أَنَّ ابْنَ الزُّبَيْرِ قَدْ وَضَعَ الْبِنَاءَ عَلَى أُسٍّ نَظَرَ إِلَيْهِ الْعُدُولُ مِنْ أَهْلِ مَكَّةَ، فَكَتَبَ إِلَيْهِ عَبْدُ الْمَلِكِ: إِنَّا لَسْنَا مِنْ تَلْطِيخِ ابْنِ الزُّبَيْرِ فِي شَيْءٍ، أَمَّا مَا زَادَ فِي طُولِهِ فَأَقِرَّهُ، وَأَمَّا مَا زَادَ فِيهِ مِنَ الْحِجْرِ فَرُدَّهُ إِلَى بِنَائِهِ، وَسُدَّ الْبَابَ الَّذِي فَتَحَهُ، فَنَقَضَهُ وَأَعَادَهُ إِلَى بِنَائِهِ."],"takhrij":"صحيح: رواه مسلم (١٣٣٣ : ٤٠٢).","grade":"صحيح","chapter_ar":"باب نقض الكعبة وبنائها على قواعد إبراهيم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1333:402).","chapter_en":"Demolishing the Kaʿbah and rebuilding it upon the foundations of Ibrahim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":40,"content":{"translation":{"en":["‘Ata’ said: When the House was burned during the time of Yazid ibn Mu‘awiyah, when the people of Syria attacked it, and what happened happened, Ibn al-Zubayr left it as it was until the pilgrimage season came and the people arrived. He wanted either to embolden them against the people of Syria or stir them against them. When the people departed, he said: O people, advise me regarding the Ka‘bah. Should I demolish it and rebuild it, or should I repair what has become weak in it? Ibn ‘Abbas said: An opinion has been made clear to me regarding it. I think you should repair what has become weak in it and leave a House upon which the people accepted Islam, and stones upon which the people accepted Islam, and upon which the Prophet ﷺ was sent. Ibn al-Zubayr said: If the house of one of you burned, he would not be satisfied until he rebuilt it, so what about the House of your Lord? I will seek guidance from my Lord three times, then I will proceed with my decision. When the three days passed, he resolved to demolish it. The people were hesitant for fear that some heavenly punishment might strike the first one to climb it, until a man climbed it and cast down some stones from it. When the people saw that nothing happened to him, they followed and demolished it until they reached the ground. Ibn al-Zubayr then set up pillars and hung curtains over them until its rebuilding rose.","Ibn al-Zubayr said: I heard ‘A’ishah say that the Prophet ﷺ said: “Were it not that the people are newly removed from disbelief, and were it not that I do not have enough funds to strengthen its rebuilding, I would have incorporated into it five cubits from the enclosure, and I would have made for it a door through which people enter and a door through which they exit.”","He said: Today I have what I can spend, and I do not fear the people. So he added five cubits from the enclosure until he exposed a foundation the people could see, and he built upon it. The Ka‘bah had been eighteen cubits high, and when he added to it, he considered it too short, so he added ten cubits to its height. He made for it two doors, one by which people enter and one by which they exit. Then when Ibn al-Zubayr was killed, al-Hajjaj wrote to ‘Abd al-Malik ibn Marwan informing him of that and informing him that Ibn al-Zubayr had set the structure upon a foundation that trustworthy men from the people of Mecca had seen. ‘Abd al-Malik wrote back: We want nothing to do with Ibn al-Zubayr’s alteration. As for what he added to its height, leave it. But as for what he added from the enclosure, return it to its former structure, and close the door he opened. So he demolished that part and returned it to its previous construction."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1333}]},{"num":4995,"demo":false,"sanad":"","matn":["عن عبد الله بن عبيدِ قال: وَفَدَ الحارثُ بْنُ عبدِ الله عَلَى عبد الملك بن مروان في خلافته، فقال عبد الملك: ما أظن أبا خبيب - يعني ابن الزبير - سمع من عائشة ما كان يزعم أنه سمعه منها! قال الحارث: بلى، أنا سمعته منها. قال: سمعتها تقول ماذا؟ قال: قالت: قال رسولُ اللّٰه ﷺ: (( إِنَّ قَوْمَكِ اسْتَقْصَرُوا مِنْ بُنْيَانِ الْبَيْتِ، وَلَوْلَا حَدَاثَةُ عَهْدِهِمْ بِالشِّرْكِ أَعَدْتُ مَا تَرَكُوا مِنْهُ، فَإِنْ بَدَا لِقَوْمِكِ مِنْ بَعْدِي أَنْ يَبْنُوهُ فَهَلُمِّي لِأُرِيَكِ مَا تَرَكُوا مِنْهُ )). فَأَرَاهَا قَرِيبًا مِنْ سَبْعَةِ أَذْرُعٍ.","وهذا حديث عبد الله بن عبيد، وزاد عليه الوليد بن عطاء قال النبيّ ﷺ: (( وَلَجَعَلْتُ لَهَا بَابَيْنِ مَوْضُوعَيْنِ فِي الْأَرْضِ شَرْقِيًّا وَغَرْبِيًّا. وَهَلْ تَدْرِينَ لِمَ كَانَ قَوْمُكِ رَفَعُوا بَابَهَا؟ )) قالت: قلت: لا. قال: (( تَعَزُّزًا أَلَّا يَدْخُلَهَا إِلَّا مَنْ أَرَادُوا، فَكَانَ الرَّجُلُ إِذَا هُوَ أَرَادَ أَنْ يَدْخُلَهَا يَدَعُونَهُ يَرْتَقِي، حَتَّى إِذَا كَادَ أَنْ يَدْخُلَهَا دَفَعُوهُ فَسَقَطَ )). قال عبد الملك للحارث: أَنْتَ سَمِعْتَهَا تَقُولُ هَذَا؟ قال: نعم. قال: فنكت ساعةً بعصاه ثم قال: وَدِدْتُ أَنِّي تَرَكْتُهُ وَمَا تَحَمَّلَ."],"takhrij":"صحيح: رواه مسلم (١٣٣٣ : ٤٠٣).","grade":"صحيح","chapter_ar":"باب نقض الكعبة وبنائها على قواعد إبراهيم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1333:403).","chapter_en":"Demolishing the Kaʿbah and rebuilding it upon the foundations of Ibrahim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":40,"content":{"translation":{"en":["‘Abd Allah ibn ‘Ubayd said: Al-Harith ibn ‘Abd Allah came to ‘Abd al-Malik ibn Marwan during his rule, and ‘Abd al-Malik said: I do not think Abu Khubayb — meaning Ibn al-Zubayr — heard from ‘A’ishah what he used to claim he heard from her. Al-Harith said: Rather, I myself heard it from her. He said: What did you hear her say? He said: She said: The Messenger of Allah ﷺ said: “Your people reduced the structure of the House, and were it not for the fact that they were newly removed from idolatry, I would have restored what they left out of it. If your people decide after me to rebuild it, then come and I will show you what they left out of it.” Then he showed her approximately seven cubits.","This is the narration of ‘Abd Allah ibn ‘Ubayd, and al-Walid ibn ‘Ata’ added to it that the Prophet ﷺ said: “And I would have made for it two doors set at ground level, one eastern and one western. Do you know why your people raised its door?” She said: I said: No. He said: “Out of pride, so that none would enter it except those whom they wished. When a man wanted to enter it, they would let him climb up, and when he was about to enter, they would push him and he would fall.”","Then ‘Abd al-Malik said to al-Harith: You heard her say this? He said: Yes. He then tapped the ground with his stick for a while and said: I wish I had left it as it was and what he had undertaken."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1333}]},{"num":4996,"demo":false,"sanad":"","matn":["عن أبي قَزَعَةَ أَنَّ عبد الملك بن مروان بَيْنَمَا هُوَ يَطُوفُ بِالْبَيْتِ إِذْ قَالَ: قَاتَلَ اللّه ابْنَ الزُّبَيْرِ حَيْثُ يَكْذِبُ عَلَى أُمِّ الْمُؤْمِنِينَ، يَقُولُ سَمِعْتُهَا تَقُولُ: قَالَ رَسُولُ اللّٰه ﷺ: (( يَا عَائِشَةُ، لَوْلَا حِدْثَانُ قَوْمِكِ بِالْكُفْرِ لَنَقَضْتُ الْبَيْتَ حَتَّى أَزِيدَ فِيهِ مِنَ الْحِجْرِ، فَإِنَّ قَوْمَكِ قَصَّرُوا فِي الْبِنَاءِ )).","فَقَالَ الحارث بن عبد الله بن أبي ربيعة: لا تَقُلْ هَذَا يَا أَمِيرَ الْمُؤْمِنِينَ، فَأَنَا سَمِعْتُ أُمَّ الْمُؤْمِنِينَ تُحَدِّثُ هَذَا. قال: لَوْ كُنْتُ سَمِعْتُهُ قَبْلَ أَنْ أَهْدِمَهُ لَتَرَكْتُهُ عَلَى مَا بَنَى ابْنُ الزُّبَيْرِ."],"takhrij":"صحيح: رواه مسلم (١٣٣٣ : ٤٠٤).","grade":"صحيح","chapter_ar":"باب نقض الكعبة وبنائها على قواعد إبراهيم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1333:404).","chapter_en":"Demolishing the Kaʿbah and rebuilding it upon the foundations of Ibrahim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":40,"content":{"translation":{"en":["Abu Qaza‘ah narrated that while ‘Abd al-Malik ibn Marwan was circumambulating the House, he said: May Allah fight Ibn al-Zubayr, how he lies against the Mother of the Believers, saying: I heard her say that the Messenger of Allah ﷺ said: “O ‘A’ishah, were it not that your people are recently removed from disbelief, I would have demolished the House and added to it from the enclosure, for your people reduced it in its construction.”","Then al-Harith ibn ‘Abd Allah ibn Abi Rabi‘ah said: Do not say this, O Commander of the Believers, for I heard the Mother of the Believers narrate this. He said: If I had heard this before demolishing it, I would have left it as Ibn al-Zubayr built it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1333}]},{"num":4997,"demo":false,"sanad":"","matn":["عن أبي السَّفَرِ قال: سمعتُ ابنَ عباسٍ رضي اللّٰه عنهما يقول: يَا أَيُّهَا النَّاسُ، اسْمَعُوا مِنِّي مَا أَقُولُ لَكُمْ، وَأَسْمِعُونِي مَا تَقُولُونَ، وَلَا تَذْهَبُوا فَتَقُولُوا: قَالَ ابْنُ عَبَّاسٍ، قَالَ ابْنُ عَبَّاسٍ. مَنْ طَافَ بِالْبَيْتِ فَلْيَطُفْ مِنْ وَرَاءِ الْحِجْرِ، وَلَا تَقُولُوا: الْحَطِيمُ، فَإِنَّ الرَّجُلَ فِي الْجَاهِلِيَّةِ كَانَ يَحْلِفُ، فَيُلْقِي سَوْطَهُ أَوْ نَعْلَهُ أَوْ قَوْسَهُ."],"takhrij":"صحيح: رواه البخاري (٣٨٤٨).","grade":"صحيح","chapter_ar":"باب نقض الكعبة وبنائها على قواعد إبراهيم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3848).","chapter_en":"Demolishing the Kaʿbah and rebuilding it upon the foundations of Ibrahim","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":40,"content":{"translation":{"en":["Abu al-Safar said: I heard Ibn ‘Abbas, may Allah be pleased with them both, say: O people, listen to what I say to you, and let me hear what you say. Do not go away saying: Ibn ‘Abbas said, Ibn ‘Abbas said. Whoever circumambulates the House must circumambulate from outside the enclosure, and do not call it al-Hatim, for in the time of ignorance a man would swear an oath and then throw there his whip, his sandal, or his bow."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3848}]},{"num":4998,"demo":false,"sanad":"","matn":["عن ابن عمر، أَنَّ النَّبِيَّ ﷺ كَانَ إِذَا طَافَ بِالْبَيْتِ الطَّوَافَ الْأَوَّلَ يَخُبُّ ثَلاثَةَ أَطْوَافٍ، وَيَمْشِي أَرْبَعَةً، وَأَنَّهُ كَانَ يَسْعَى بَطْنَ الْمَسِيلِ إِذَا طَافَ بَيْنَ الصَّفَا وَالْمَرْوَةِ."],"takhrij":"متفق عليه: رواه البخاريّ (١٦١٧)، ومسلم (١٢٦١ : ٢٣٠). واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1617) and Muslim (1261:230). This is the wording of al-Bukhari.","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Prophet ﷺ performed the first circumambulation of the House, he would hasten in three circuits and walk in four. And he used to move swiftly through the bottom of the valley when going between al-Safa and al-Marwah."]},"buhuth":{"ar":["وفي رواية عند البخاريّ (١٦٠٤): (( سعى النبيُّ ﷺ ثلاثة أشواط، ومشى أربعة في الحجّ والعمرة )).","وفي رواية أخرى عند مسلم (١٢٦٢): (( رَمَلَ رسولُ اللّٰه ﷺ من الحجر إلى الحجر ثلاثًا، ومشى أربعًا ))."],"en":["In another narration in al-Bukhari (1604): “The Prophet ﷺ hastened in three circuits and walked in four in both the pilgrimage and the lesser pilgrimage.”","And in another narration in Muslim (1262): “The Messenger of Allah ﷺ performed brisk walking from the Black Stone back to the Black Stone for three circuits, and walked four.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1617},{"key":"muslim","label":"مسلم","number":1261}]},{"num":4999,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: رَمَلَ رسولُ الله ﷺ من الحجر إلى الحجر ثلاثًا، ومشى أربعًا."],"takhrij":"صحيح: رواه مسلم (١٢٦٢).","grade":"صحيح","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1262).","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: The Messenger of Allah ﷺ performed brisk walking from the Black Stone to the Black Stone for three circuits, and walked four."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1262}]},{"num":5000,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: رأيتُ رسولَ اللّٰه ﷺ رَمَلَ مِنَ الحجر الأسود حتى انتهى إليه ثلاثة أطواف."],"takhrij":"صحيح: رواه مالك (١٠٧)، ومسلم (١٢٦٣).","grade":"صحيح","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (107) and Muslim (1263).","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I saw the Messenger of Allah ﷺ perform brisk walking from the Black Stone until he returned to it for three circuits."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":107},{"key":"muslim","label":"مسلم","number":1263}]},{"num":5001,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قَدِمَ رسولُ الله ﷺ وَأَصْحَابُهُ مَكَّةَ وَقَدْ وَهَنَتْهُمْ حُمَّى يَثْرِبَ، قَالَ الْمُشْرِكُونَ: إِنَّهُ يَقْدَمُ عَلَيْكُمْ غَدًا قَوْمٌ قَدْ وَهَنَتْهُمُ الْحُمَّى، وَلَقُوا مِنْهَا شِدَّةً، فَجَلَسُوا مِمَّا يَلِي الْحِجْرَ، وَأَمَرَهُمُ النَّبِيُّ ﷺ أَنْ يَرْمُلُوا ثَلاثَةَ أَشْوَاطٍ، وَيَمْشُوا مَا بَيْنَ الرُّكْنَيْنِ؛ لِيَرَى الْمُشْرِكُونَ جَلَدَهُمْ. فَقَالَ الْمُشْرِكُونَ: هَؤُلاءِ الَّذِينَ زَعَمْتُمْ أَنَّ الْحُمَّى قَدْ وَهَنَتْهُمْ؟ هَؤُلَاءِ أَجْلَدُ مِنْ كَذَا وَكَذَا.","قَالَ ابْنُ عَبَّاسٍ: وَلَمْ يَمْنَعْهُ أَنْ يَأْمُرَهُمْ أَنْ يَرْمُلُوا الْأَشْوَاطَ كُلَّهَا إِلَّا الْإِبْقَاءُ عَلَيْهِمْ."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٠٢)، ومسلم (١٢٦٦)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1602) and Muslim (1266). This is the wording of Muslim.","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ and his Companions came to Mecca after the fever of Yathrib had weakened them. The idolaters said: Tomorrow there will come to you people whom the fever has weakened, and they have suffered severely from it. So they sat on the side near the enclosure. The Prophet ﷺ ordered his Companions to perform brisk walking in three circuits and to walk between the two corners, so that the idolaters might see their strength. The idolaters then said: Are these the ones about whom you claimed that the fever had weakened them? These are stronger than this and that.","Ibn ‘Abbas said: What prevented him from ordering them to perform brisk walking in all the circuits was his mercy toward them."]},"buhuth":{"ar":["قوله: (( ويمشوا ما بين الركنين )) أي حيث لا تقع عليهم أعين المشركين، فإنهم ما كانوا في تلك الجهة."],"en":["His statement, “and walk between the two corners,” means in the place where the eyes of the idolaters would not fall upon them, because they were not positioned on that side."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1602},{"key":"muslim","label":"مسلم","number":1266}]},{"num":5002,"demo":false,"sanad":"","matn":["عن أبي الطُّفَيْلِ، قال: قُلْتُ لابْنِ عَبَّاسٍ: أَرَأَيْتَ هَذَا الرَّمَلَ بِالْبَيْتِ ثَلَاثَةَ أَطْوَافٍ، وَمَشْيَ أَرْبَعَةِ أَطْوَافٍ، أَسُنَّةٌ هُوَ؟ فَإِنَّ قَوْمَكَ يَزْعُمُونَ أَنَّهُ سُنَّةٌ. قَالَ: فَقَالَ: صَدَقُوا وَكَذَبُوا. قَالَ: قُلْتُ: مَا قَوْلُكَ: صَدَقُوا وَكَذَبُوا؟ قَالَ: إِنَّ رَسُولَ اللّٰهِ ﷺ قَدِمَ مَكَّةَ، فَقَالَ الْمُشْرِكُونَ: إِنَّ مُحَمَّدًا وَأَصْحَابَهُ لا يَسْتَطِيعُونَ أَنْ يَطُوفُوا بِالْبَيْتِ مِنَ الْهُزَالِ، وَكَانُوا يَحْسُدُونَهُ. قَالَ: فَأَمَرَهُمْ رَسُولُ اللّٰهِ ﷺ أَنْ يَرْمُلُوا ثَلَاثًا وَيَمْشُوا أَرْبَعًا. قَالَ: قُلْتُ لَهُ: أَخْبِرْنِي عَنِ الطَّوَافِ بَيْنَ الصَّفَا وَالْمَرْوَةِ رَاكِبًا، أَسُنَّةٌ هُوَ؟ فَإِنَّ قَوْمَكَ يَزْعُمُونَ أَنَّهُ سُنَّةٌ. قَالَ: صَدَقُوا وَكَذَبُوا. قَالَ: قُلْتُ: وَمَا قَوْلُكَ: صَدَقُوا وَكَذَبُوا؟ قَالَ: إِنَّ رَسُولَ اللّٰهِ ﷺ كَثُرَ عَلَيْهِ النَّاسُ، يَقُولُونَ: هَذَا مُحَمَّدٌ، هَذَا مُحَمَّدٌ، حَتَّى خَرَجَ الْعَوَاتِقُ مِنَ الْبُيُوتِ. قَالَ: وَكَانَ رَسُولُ اللّٰهِ ﷺ لا يُضْرَبُ النَّاسُ بَيْنَ يَدَيْهِ، فَلَمَّا كَثُرَ عَلَيْهِ رَكِبَ، وَالْمَشْيُ وَالسَّعْيُ أَفْضَلُ."],"takhrij":"صحيح: رواه مسلم (١٢٦٤).","grade":"صحيح","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1264).","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["Abu al-Tufayl said: I said to Ibn ‘Abbas, “Tell me about this brisk walking around the House for three circuits and walking for four circuits — is it a Sunnah? Your people claim that it is a Sunnah.” He said, “They are right and they are wrong.” I said, “What do you mean by: they are right and they are wrong?” He said, “The Messenger of Allah ﷺ came to Mecca, and the polytheists said: Muhammad and his companions are too weakened by emaciation to circle the House. They envied him. So the Messenger of Allah ﷺ ordered them to walk briskly for three circuits and walk normally for four.” I said to him, “Tell me about going between al-Safa and al-Marwah while riding — is that a Sunnah? Your people claim that it is a Sunnah.” He said, “They are right and they are wrong.” I said, “What do you mean by: they are right and they are wrong?” He said, “The Messenger of Allah ﷺ was surrounded by many people, saying: This is Muhammad, this is Muhammad, until even young women came out from the houses. The Messenger of Allah ﷺ would not have the people struck away from in front of him, so when the crowd became too great, he rode. Walking and sa‘y are better.”"]},"buhuth":{"ar":["وقوله: (( صَدَقُوا وَكَذَبُوا )) يعني: صدقوا في أن النبيَّ ﷺ رَمَلَ بالبيت ثلاثًا، وكذبوا في قولهم: إنه سُنَّةٌ مقصودةٌ متأكدة؛ لأن النبيَّ ﷺ لم يجعله سُنَّةً مطلوبةً دائمًا على تكرار السنين، وإنما أمر به تلك السنة لإظهار القوة عند الكفار، وقد زال ذلك المعنى. هذا معنى كلام ابن عباس، وهو مذهبه بأن الرَّمَل ليس بسنة، والجمهور من الصحابة والتابعين ومن بعدهم ذهبوا إلى أن الرَّمَل سنة مستحبة، يصح الطواف بدونه، ولكنه تفوته الفضيلة ولا دم عليه.","وإليه يشير قول عمر بن الخطاب رضي اللّٰه عنه: (( شيءٌ فعله رسولُ اللّٰهِ ﷺ ولا نحبُّ أن نتركه )).","وقد جاء عن ابن عباس خلاف هذا بأن الرَّمَل سنة، وهو ما يأتي:"],"en":["His statement, “They are right and they are wrong,” means: they are right that the Prophet ﷺ did perform brisk walking around the House for three circuits, and they are wrong in claiming that it is a specifically intended and strongly emphasized Sunnah in itself, because the Prophet ﷺ did not establish it as a constantly intended practice repeated every year. Rather, he ordered it that year to show strength before the disbelievers, and that reason later ceased. This is the meaning of Ibn ‘Abbas’s statement, and it was his view that brisk walking was not a Sunnah. The majority of the Companions, the Followers, and those after them held that brisk walking is a recommended Sunnah; the circumambulation is valid without it, but its virtue is missed and no compensatory sacrifice is due.","This is also indicated by the saying of ‘Umar ibn al-Khattab, may Allah be pleased with him: “It is something the Messenger of Allah ﷺ did, and we do not like to leave it.” A contrary report also came from Ibn ‘Abbas stating that brisk walking is a Sunnah, and that is what comes next."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1264}]},{"num":5003,"demo":false,"sanad":"","matn":["عن ابن عباس: أن رسولَ اللّٰهِ ﷺ لَمَّا نَزَلَ مَرَّ الظَّهْرَانِ فِي عُمْرَتِهِ، بَلَغَ أَصْحَابَ رَسُولِ اللّٰهِ ﷺ أَنَّ قُرَيْشًا تَقُولُ: مَا يَتَبَاعَثُونَ مِنَ الْعَجَفِ. فَقَالَ أَصْحَابُهُ: لَوِ انْتَحَرْنَا مِنْ ظَهْرِنَا فَأَكَلْنَا مِنْ لَحْمِهِ وَحَسَوْنَا مِنْ مَرَقِهِ، أَصْبَحْنَا غَدًا حِينَ نَدْخُلُ عَلَى الْقَوْمِ وَبِنَا جَمَامَةٌ. قَالَ: (( لا تَفْعَلُوا، وَلَكِنِ اجْمَعُوا لِي مِنْ أَزْوَادِكُمْ )). فَجَمَعُوا لَهُ، وَبَسَطُوا الْأَنْطَاعَ، فَأَكَلُوا حَتَّى تَوَلَّوْا، وَحَثَا كُلُّ وَاحِدٍ مِنْهُمْ فِي جِرَابِهِ، ثُمَّ أَقْبَلَ رَسُولُ اللّٰهِ ﷺ حَتَّى دَخَلَ الْمَسْجِدَ، وَقَعَدَتْ قُرَيْشٌ نَحْوَ الْحِجْرِ، فَاضْطَبَعَ بِرِدَائِهِ، ثُمَّ قَالَ: (( لا يَرَى الْقَوْمُ فِيكُمْ غَمِيزَةً )). فَاسْتَلَمَ الرُّكْنَ، ثُمَّ دَخَلَ، حَتَّى إِذَا تَغَيَّبَ بِالرُّكْنِ الْيَمَانِيِّ مَشَى إِلَى الرُّكْنِ الْأَسْوَدِ. فَقَالَتْ قُرَيْشٌ: مَا يَرْضَوْنَ بِالْمَشْيِ، إِنَّهُمْ لَيَنْقُزُونَ نَقْزَ الظِّبَاءِ. فَفَعَلَ ذَلِكَ ثَلَاثَةَ أَطْوَافٍ، فَكَانَتْ سُنَّةً.","قال أبو الطفيل: وأخبرني ابن عباس: أن النبيَّ ﷺ فعل ذلك في حجة الوداع."],"takhrij":"حسن: رواه الإمام أحمد (٢٧٨٢).","grade":"حسن","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (2782).","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["Ibn ‘Abbas reported that when the Messenger of Allah ﷺ came down at Marr al-Zahran during his ‘Umrah, the companions of the Messenger of Allah ﷺ learned that Quraysh was saying: They can hardly move from weakness. His companions said: If we slaughtered some of our riding animals and ate from their meat and drank from their broth, then tomorrow when we enter upon the people we would have strength and fullness. He said: “Do not do that, but gather for me from your provisions.” So they gathered them for him and spread out leather cloths, and they ate until they were satisfied, and each one of them then scooped some back into his bag. Then the Messenger of Allah ﷺ came forward until he entered the mosque, while Quraysh sat near the enclosure. He tucked his cloak under one arm and over the other shoulder, then said: “Let the people not see any weakness in you.” He touched the Corner, then proceeded, and when he was hidden at the Yemeni Corner he walked until the Black Stone. Quraysh said: They are not content just to walk; they are springing like gazelles. He did that for three circuits, and it became a Sunnah.","Abu al-Tufayl said: Ibn ‘Abbas also told me that the Prophet ﷺ did that in the Farewell Pilgrimage."]},"buhuth":{"ar":["فقوله: (( فكانت سنة )) لعلّه رجع عن قوله الأول لما تبيَّن له، وأبو الطفيل سمع منه في المرة الأولى الإنكار، ثم سمع منه الإقرار، فروى على وجهين، والله تعالى أعلم. ثم قصة ابن عباس كانت في عمرة القضاء، وحديث جابر وابن عمر وغيرهما كان في حجة الوداع، وهو متأخر.","وقوله فيما مضى: (( إلا الإبقاء عليهم )) أي إن النبيَّ ﷺ لم يمنعهم من الرمل في الأشواط الثلاثة إلا استمرارًا لما فعله هو وأصحابه في عمرة القضاء، وهذا التفسير يكون موافقًا لقوله: (( فكانت سنة )).","وقول أبي الطفيل: وأخبرني ابن عباس: (( أن النبيَّ ﷺ فعل ذلك في حجة الوداع أيضًا )) أي أن النبيَّ ﷺ أعاد الرمل في حجة الوداع أيضًا. وفيه إشارة إلى استمراره، وإن كان السبب الذي من أجله رَمَلَ قد انتهى، وهذا القول الثاني من ابن عباس كان موافقًا لجمهور أهل العلم بأن الرَّمَل في الأشواط الثلاثة سنة."],"en":["His statement, “and it became a Sunnah,” may indicate that he later revised his first view after the matter became clear to him. Abu al-Tufayl heard from him first the disapproval, then later heard the affirmation, so he narrated both forms, and Allah knows best. Also, the incident reported by Ibn ‘Abbas was during the Compensatory ‘Umrah, while the reports of Jabir, Ibn ‘Umar, and others were from the Farewell Pilgrimage, which came later.","His earlier words, “except out of mercy toward them,” mean that the Prophet ﷺ only refrained from commanding them to do brisk walking in all the circuits in order to preserve their strength, while still continuing what he and his companions had done in the Compensatory ‘Umrah. This explanation agrees with his statement, “and it became a Sunnah.” Abu al-Tufayl’s words, “Ibn ‘Abbas told me that the Prophet ﷺ did that in the Farewell Pilgrimage as well,” mean that the Prophet ﷺ repeated the brisk walking in the Farewell Pilgrimage too. This indicates its continuance even though the original reason for it had ended. This second statement from Ibn ‘Abbas agrees with the majority of the scholars that brisk walking in the first three circuits is a Sunnah."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":2782},{"key":"ahmad","label":"مسند الإمام أحمد","number":2782,"n":2782}]},{"num":5004,"demo":false,"sanad":"","matn":["عن أسلم مولى عمر، أنَّ عمر بن الخطاب رضي اللّٰه عنه قال للرُّكنِ: أَمَا وَاللّٰهِ إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ لا تَضُرُّ وَلا تَنْفَعُ، وَلَوْلَا أَنِّي رَأَيْتُ النَّبِيَّ ﷺ اسْتَلَمَكَ مَا اسْتَلَمْتُكَ. فَاسْتَلَمَهُ، ثُمَّ قَالَ: فَمَا لَنَا وَلِلرَّمَلِ؟ إِنَّمَا كُنَّا رَاءَيْنَا بِهِ الْمُشْرِكِينَ، وَقَدْ أَهْلَكَهُمُ اللّٰهُ. ثُمَّ قَالَ: شَيْءٌ صَنَعَهُ النَّبِيُّ ﷺ فَلَا نُحِبُّ أَنْ نَتْرُكَهُ."],"takhrij":"صحيح: رواه البخاريّ (١٦٠٥).","grade":"صحيح","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1605).","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["Aslam, the freed servant of ‘Umar, narrated that ‘Umar ibn al-Khattab, may Allah be pleased with him, said to the Corner: By Allah, I know that you are only a stone; you neither harm nor benefit. Had I not seen the Prophet ﷺ touch you, I would not have touched you. Then he touched it and said: What have we to do with brisk walking? We only used to display strength by it before the polytheists, and Allah has destroyed them. Then he said: It is something the Prophet ﷺ did, and we do not like to leave it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1605}]},{"num":5005,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب، قال: فِيمَ الرَّمَلَانُ الْيَوْمَ، وَالْكَشْفُ عَنِ الْمَنَاكِبِ، وَقَدْ أَطَّأَ اللّٰهُ الْإِسْلَامَ وَنَفَى الْكُفْرَ وَأَهْلَهُ؟! مَعَ ذَلِكَ لا نَدَعُ شَيْئًا كُنَّا نَفْعَلُهُ عَلَى عَهْدِ رَسُولِ اللّٰهِ ﷺ."],"takhrij":"حسن: رواه أبو داود (١٨٨٧)، وأحمد في مسنده (٣١٧)، وابن ماجه (٢٩٥٢)، وصححه ابن خزيمة (٢٧٠٨).","grade":"حسن","chapter_ar":"باب استحباب الرَّمَل في الأشواط الثلاثة الأولى في طواف العمرة، وفي الطواف الأول في الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1887), Ahmad in his Musnad (317), and Ibn Majah (2952). Ibn Khuzaymah graded it authentic (2708).","chapter_en":"The recommendation of brisk walking in the first three circuits of the lesser pilgrimage circumambulation and in the first circumambulation of the pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":41,"content":{"translation":{"en":["‘Umar ibn al-Khattab said: Why should there still be brisk walking today and uncovering of the shoulders, when Allah has firmly established Islam and removed disbelief and its people? Even so, we do not leave anything that we used to do during the time of the Messenger of Allah ﷺ."]},"buhuth":{"ar":["قال ابن خزيمة: (( إنّ السنة قد كان يسنّها النبيّ ﷺ لعلّة حادثة، فتزول العلة، وتبقى السنة إلى الأبد، إذ النبيُّ ﷺ رَمَلَ في الابتداء، واضطبع ليُري المشركين قوته وقوة أصحابه، فبقي الاضطباع والرمل سنتين إلى الأبد ))."],"en":["Ibn Khuzaymah said: A Sunnah may be established by the Prophet ﷺ for a particular cause, then the cause disappears while the Sunnah remains forever. The Prophet ﷺ first performed brisk walking and uncovered his shoulder to show the polytheists his strength and the strength of his companions, and so the practices of uncovering the shoulder and brisk walking remained as enduring Sunnahs."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1887},{"key":"ahmad/مسندہ","label":"أحمد في مسنده","number":317},{"key":"ibnmajah","label":"ابن ماجه","number":2952},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2708},{"key":"ahmad","label":"مسند الإمام أحمد","number":317,"n":317}]},{"num":5006,"demo":false,"sanad":"","matn":["عن ابن عباس، أَنَّ النَّبِيَّ ﷺ اضْطَبَعَ، فَاسْتَلَمَ وَكَبَّرَ، ثُمَّ رَمَلَ ثَلَاثَةَ أَطْوَافٍ، وَكَانُوا إِذَا بَلَغُوا الرُّكْنَ الْيَمَانِيَّ وَتَغَيَّبُوا مِنْ قُرَيْشٍ مَشَوْا، ثُمَّ يَطَّلِعُونَ عَلَيْهِمْ يَرْمُلُونَ، تَقُولُ قُرَيْشٌ: كَأَنَّهُمُ الْغِزْلَانُ. قَالَ ابْنُ عَبَّاسٍ: فَكَانَتْ سُنَّةً."],"takhrij":"حسن: رواه أبو داود (١٨٨٩)، وابن ماجه (٢٩٥٣)، واللفظ لأبي داود. وفي لفظ لابن ماجه: قال النبيُّ ﷺ لأصحابه حين أرادوا دخول مكة في عمرته بعد الحديبية: (( إنَّ قومَكم غدًا سيرونكم، فليرَوْنَكم جَلَدًا )).","grade":"حسن","chapter_ar":"باب ما جاء في الاضطباع في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1889) and Ibn Majah (2953), and the wording is that of Abu Dawud. In the wording of Ibn Majah, the Prophet ﷺ said to his companions when they intended to enter Mecca in his ‘Umrah after al-Hudaybiyah: “Your people will see you tomorrow, so let them see strength in you.”","chapter_en":"What has been narrated about uncovering the shoulder during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":42,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ uncovered his shoulder, touched the Stone, said the takbir, then performed brisk walking for three circuits. When they reached the Yemeni Corner and were hidden from Quraysh, they walked normally, then when they came back into view they again performed brisk walking. Quraysh would then say: They are like gazelles. Ibn ‘Abbas said: So it became a Sunnah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1889},{"key":"ibnmajah","label":"ابن ماجه","number":2953}]},{"num":5007,"demo":false,"sanad":"","matn":["عن يعلى بن أميّة، قال: طافَ النَّبيُّ ﷺ مُضْطَبِعًا بِبُرْدٍ."],"takhrij":"حسن: رواه أبو داود (١٨٨٣)، والترمذيّ (٨٥٩)، وابن ماجه (٢٩٥٤). قال الترمذي: حديث حسن.","grade":"حسن","chapter_ar":"باب ما جاء في الاضطباع في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1883), al-Tirmidhi (859), and Ibn Majah (2954). Al-Tirmidhi said: It is a Hasan hadith.","chapter_en":"What has been narrated about uncovering the shoulder during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":42,"content":{"translation":{"en":["Ya‘la ibn Umayyah said: The Prophet ﷺ circumambulated while having one shoulder uncovered with a cloak wrapped in that manner."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1883},{"key":"tirmidhi","label":"الترمذيّ","number":859},{"key":"ibnmajah","label":"ابن ماجه","number":2954}]},{"num":5008,"demo":false,"sanad":"","matn":["عن أمِّ سلمة زوج النبيّ ﷺ أنها قالت: شَكَوْتُ إِلَى رَسُولِ اللّٰهِ ﷺ أَنِّي أَشْتَكِي، فَقَالَ: (( طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ )). قَالَتْ: فَطُفْتُ رَاكِبَةً بَعِيرِي، وَرَسُولُ اللّٰهِ ﷺ حِينَئِذٍ يُصَلِّي إِلَى جَانِبِ الْبَيْتِ وَهُوَ يَقْرَأُ بِـ{وَالطُّورِ * وَكِتَابٍ مَسْطُورٍ}."],"takhrij":"متفق عليه: رواه مالك (١٢٣)، والبخاريّ (١٦٣٣)، ومسلم (١٢٧٦).","grade":"متفق عليه","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (123), al-Bukhari (1633), and Muslim (1276).","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: I complained to the Messenger of Allah ﷺ that I was unwell, so he said: “Circumambulate behind the people while you are riding.” She said: So I circumambulated while riding my camel, while the Messenger of Allah ﷺ at that time was praying beside the House, reciting: “By the Mount, and by a written Book.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":123},{"key":"bukhari","label":"البخاريّ","number":1633},{"key":"muslim","label":"مسلم","number":1276}]},{"num":5009,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس: أن رسولَ اللّٰهِ ﷺ طافَ في حجّة الوداع على بعير، يستلمُ الرُّكنَ بِمِحْجَنٍ."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٠٧)، ومسلم (١٢٧٢). ورواه البخاريّ (١٦٣٢) وزاد: (( وكبَّر )).","grade":"متفق عليه","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1607) and Muslim (1272). Al-Bukhari also narrated it (1632) with the addition: “and he said the takbir.”","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas reported that the Messenger of Allah ﷺ circumambulated during the Farewell Pilgrimage while on a camel, touching the Corner with a crook."]},"buhuth":{"ar":["قوله: (( بمحجن )) المحجن: عصا معوجة الرأس."],"en":["His statement, “with a crook,” means a stick with a curved end."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1607},{"key":"muslim","label":"مسلم","number":1272},{"key":"ورواہ_البخاری","label":". ورواه البخاريّ","number":1632}]},{"num":5010,"demo":false,"sanad":"","matn":["عن جابر، قال: طافَ رسولُ اللّٰهِ ﷺ بالبيتِ في حجّة الوداع على راحلته، يستلمُ الحجرَ بمحجنه؛ لأن يراه الناس، وليُشرف، وليسألوه؛ فإنَّ الناسَ غشوه."],"takhrij":"صحيح: رواه مسلم (١٢٧٣).","grade":"صحيح","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1273).","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ circumambulated the House during the Farewell Pilgrimage while riding his mount, touching the Stone with his crook, so that the people could see him, so that he would be visible above them, and so that they could ask him, because the people had crowded around him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1273}]},{"num":5011,"demo":false,"sanad":"","matn":["عن أبي الطفيل عامر بن واثلة، قال: رأيتُ رسولَ اللّٰهِ ﷺ يطوفُ بالبيتِ ويستلمُ الرُّكنَ بمحجنٍ معه، ويقبِّلُ المحجنَ."],"takhrij":"صحيح: رواه مسلم (١٢٧٥).","grade":"صحيح","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1275).","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["Abu al-Tufayl ‘Amir ibn Wathilah said: I saw the Messenger of Allah ﷺ circumambulating the House and touching the Corner with a crook he had with him, and then kissing the crook."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1275}]},{"num":5012,"demo":false,"sanad":"","matn":["عن عائشة، قالت: طافَ النبيُّ ﷺ في حجّة الوداع حول الكعبة على بعيره، يستلمُ الرُّكنَ، كراهيةَ أن يُضربَ عنه الناسُ."],"takhrij":"صحيح: رواه مسلم (١٢٧٤).","grade":"صحيح","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1274).","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ circumambulated the Ka‘bah during the Farewell Pilgrimage on his camel, touching the Corner, because he disliked that the people should be pushed away from him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1274}]},{"num":5013,"demo":false,"sanad":"","matn":["عن صفيّة بنت شيبة، قالت: لما اطمأنَّ رسولُ اللّٰهِ ﷺ بمكة عام الفتح، طاف على بعير، يستلمُ الرُّكنَ بمحجنٍ في يده. قالت: وأنا أنظرُ إليه."],"takhrij":"حسن: رواه أبو داود (١٨٧٨)، وابن ماجه (٢٩٤٧).","grade":"حسن","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1878) and Ibn Majah (2947).","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["Safiyyah bint Shaybah said: When the Messenger of Allah ﷺ had settled in Mecca in the year of the Conquest, he circumambulated on a camel, touching the Corner with a crook in his hand. She said: And I was looking at him."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1878},{"key":"ibnmajah","label":"ابن ماجه","number":2947}]},{"num":5014,"demo":false,"sanad":"","matn":["عن قدامة بن عبد الله، قال: رأيتُ رسولَ اللّٰهِ ﷺ على ناقةٍ يستلمُ الحجرَ بمحجنه."],"takhrij":"حسن: رواه أحمد (١٥٤١٤)، وأبو يعلى (٩٢٨)، والطبراني في الكبير (١٩/٨٠)، وفي الأوسط (٨٠٢٤).","grade":"حسن","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (15414), Abu Ya‘la (928), al-Tabarani in al-Kabir (19/80), and in al-Awsat (8024).","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["Qudamah ibn ‘Abd Allah said: I saw the Messenger of Allah ﷺ on a she-camel touching the Stone with his crook."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":928},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":19},{"key":"وفی_الاوسط","label":"وفي الأوسط","number":8024},{"key":"ahmad","label":"مسند الإمام أحمد","number":15414,"n":15414},{"key":"sh12520","label":"مسند أبي يعلى","number":928,"n":926}]},{"num":5015,"demo":false,"sanad":"","matn":["عن ابن عمر قال: طافَ رسولُ اللّٰهِ ﷺ على راحلته القصواء يوم الفتح، واستلمَ الرُّكنَ بمحجنه، وما وجد لها مناخًا في المسجد حتى أُخرجتْ إلى بطن الوادي فأنيخت، ثم حمد اللّٰه وأثنى عليه، ثم قال: (( أَمَّا بَعْدُ، أَيُّهَا النَّاسُ، فَإِنَّ اللّٰهَ قَدْ أَذْهَبَ عَنْكُمْ عُبِّيَّةَ الْجَاهِلِيَّةِ، يَا أَيُّهَا النَّاسُ، إِنَّمَا النَّاسُ رَجُلَانِ: بَرٌّ تَقِيٌّ كَرِيمٌ عَلَى رَبِّهِ، وَفَاجِرٌ شَقِيٌّ هَيِّنٌ عَلَى رَبِّهِ ))، ثم تلا: {يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنْثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا} [الحجرات: ١٣] حتى قرأ الآية، ثم قال: (( أقول هذا وأستغفر اللّٰه لي ولكم ))."],"takhrij":"صحيح: رواه ابن حبان (٣٨٢٨) - واللفظ له -، وابن خزيمة (٢٧٨١).","grade":"صحيح","chapter_ar":"باب جواز الطواف راكبًا لمرض أو عذر، واستلام الحجر بمحجن وغيره، وتقبيله أو الإشارة إليه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (3828) — and this is his wording — and Ibn Khuzaymah (2781).","chapter_en":"The permissibility of circumambulating while riding due to illness or an excuse, and touching the Stone with a crook or something similar, then kissing it or pointing to it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":43,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ circumambulated on his she-camel al-Qaswa’ on the day of the Conquest, and touched the Corner with his crook. He did not find a place for it to kneel in the mosque until it was taken out to the bottom of the valley and made to kneel there. Then he praised Allah and extolled Him and said: “To proceed: O people, Allah has removed from you the arrogance of the age of ignorance. O people, mankind are only of two kinds: a righteous, Allah-fearing person who is noble before his Lord, and a wicked, miserable person who is insignificant before his Lord.” Then he recited: “O mankind, We created you from a male and a female and made you peoples and tribes so that you may know one another” [49:13], until he completed the verse, then said: “I say this and seek Allah’s forgiveness for me and for you.”"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2781},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":6433,"n":6431}]},{"num":5016,"demo":false,"sanad":"","matn":["عن ابن عباس، أنَّ النبيَّ ﷺ مَرَّ وهو يطوفُ بالكعبةِ بإنسانٍ ربطَ يدَه إلى إنسانٍ آخرَ بسيرٍ أو بخيطٍ أو بشيءٍ غير ذلك، فقطعه النبيُّ ﷺ بيده، ثم قال: (( قُدْهُ بيده ))."],"takhrij":"صحيح: رواه البخاريّ (١٦٢٠). ورواه أيضًا (٦٧٠٣)، وفيه: (( يقود إنسانًا بخِزامةٍ في أنفه )).","grade":"صحيح","chapter_ar":"باب جواز الكلام المباح والأمر بالمعروف والنهي عن المنكر في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1620). He also narrated it (6703), in which it says: “He was leading a man by a nose-rope placed in his nose.”","chapter_en":"The permissibility of lawful speech, enjoining what is right, and forbidding what is wrong during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":44,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ passed by, while circumambulating the Ka‘bah, a man whose hand had been tied to another man with a strap, a string, or something else. The Prophet ﷺ cut it with his own hand and then said: “Lead him by his hand.”"]},"buhuth":{"ar":["والخِزامة: حلقة من شعر أو وبر تُجعل في الحاجز الذي بين منخري البعير، يُشدّ فيها الزمام ليسهل انقياده."],"en":["A khizamah is a ring-like loop made of hair or wool placed in the partition between a camel’s nostrils, in which the rein is tied so that it can be led easily."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1620},{"key":"ورواہ_ایضا","label":". ورواه أيضًا","number":6703}]},{"num":5017,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أن النبيَّ ﷺ قال: (( الطَّوَافُ حَوْلَ الْبَيْتِ مِثْلُ الصَّلاةِ، إِلَّا أَنَّكُمْ تَتَكَلَّمُونَ فِيهِ، فَمَنْ تَكَلَّمَ فِيهِ فَلَا يَتَكَلَّمَنَّ إِلَّا بِخَيْرٍ ))."],"takhrij":"حسن: رواه الترمذيّ (٩٦٠)، وصححه ابن خزيمة (٢٧٣٩).","grade":"حسن","chapter_ar":"باب جواز الكلام المباح والأمر بالمعروف والنهي عن المنكر في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (960), and Ibn Khuzaymah graded it authentic (2739).","chapter_en":"The permissibility of lawful speech, enjoining what is right, and forbidding what is wrong during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":44,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas reported that the Prophet ﷺ said: “Circumambulation around the House is like prayer, except that you speak in it. So whoever speaks in it should speak only good.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":960},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2739}]},{"num":5018,"demo":false,"sanad":"","matn":["عن ابن جريج، قال: أخبرني عطاء إذ منع ابن هشام النساءَ الطوافَ مع الرجال، قال: كيف يمنعهنَّ وقد طاف نساءُ النبيِّ ﷺ مع الرجال؟! قلتُ: أَبَعْدَ الحجابِ أو قبلُ؟ قال: إي لعمري، لقد أدركته بعد الحجاب. قلتُ: كيف يخالطن الرجال؟ قال: لم يكنَّ يخالطن، كانت عائشة رضي اللّٰه عنها تطوفُ حَجْرَةً من الرجال لا تخالطهم. فقالت امرأةٌ: انطلقي نستلم يا أم المؤمنين. قالت: انطلقي عنكِ، وأبتْ. يخرجن متنكراتٍ بالليل فيطفن مع الرجال، ولكنهن كن إذا دخلن البيت قُمْنَ حتى يدخلن، وأُخرج الرجال. وكنتُ آتي عائشة أنا وعبيد بن عمير وهي مجاورةٌ في جوف ثبير. قلت: وما حجابها؟ قال: هي في قبةٍ تركيةٍ لها غشاء، وما بيننا وبينها غير ذلك، ورأيتُ عليها درعًا مورّدًا."],"takhrij":"صحيح: رواه البخاريّ (١٦١٨).","grade":"صحيح","chapter_ar":"باب طواف النساء مع الرجال من غير اختلاط ما أمكن","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1618).","chapter_en":"Women circumambulating with men without mixing, as much as possible","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":45,"content":{"translation":{"en":["Ibn Jurayj said: ‘Ata’ informed me that when Ibn Hisham prevented women from circumambulating with men, he said: How can he prevent them when the wives of the Prophet ﷺ circumambulated with men? I said: Was that after the command of veiling or before it? He said: Yes, by my life, I witnessed it after veiling. I said: How did they mix with men? He said: They did not mix. ‘A’ishah, may Allah be pleased with her, would circumambulate separately from the men and would not mix with them. A woman said to her: Let us go touch the Stone, O Mother of the Believers. She said: Go yourself, and she refused. They would go out disguised at night and circumambulate with the men, but when they intended to enter the House, they would wait until the men had entered and been taken out. I used to come to ‘A’ishah with ‘Ubayd ibn ‘Umayr while she was staying in devotion in the interior of Thabir. I said: What was her screen? He said: She was in a Turkish tent with a covering, and there was nothing between us and her except that. And I saw a pink cover on her."]},"buhuth":{"ar":["وقوله: (( ابن هشام )) هو إبراهيم أو أخوه محمد بن هشام المخزومي، وكان ذلك في خلافة هشام بن عبد الملك بن مروان.","وقوله: (( حَجْرَة )) بفتح الحاء المهملة، وسكون الجيم بعدها راء، أي: ناحية.","وفي رواية: (( حَجْزَة )) بالزاي بدل الراء، يعني: محجوزًا بينها وبين الرجال بثوب."],"en":["His statement, “Ibn Hisham,” refers to Ibrahim or his brother Muhammad ibn Hisham al-Makhzumi, and that occurred during the caliphate of Hisham ibn ‘Abd al-Malik ibn Marwan.","The word hajrah here means a side or separate area.","In another narration it is read as hajzah with a zay instead of a ra’, meaning that a cloth barrier separated her from the men."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1618}]},{"num":5019,"demo":false,"sanad":"","matn":["عن أمِّ سلمة زوج النبيِّ ﷺ أنها قالت: شَكَوْتُ إِلَى رَسُولِ اللّٰهِ ﷺ أَنِّي أَشْتَكِي، فَقَالَ: (( طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ )). قَالَتْ: فَطُفْتُ رَاكِبَةً بَعِيرِي وَرَسُولُ اللّٰهِ ﷺ حِينَئِذٍ يُصَلِّي إِلَى جَانِبِ الْبَيْتِ وَهُوَ يَقْرَأُ: {وَالطُّورِ * وَكِتَابٍ مَسْطُورٍ}."],"takhrij":"متفق عليه: رواه مالك (١٢٣)، والبخاري (١٦٢٦)، ومسلم (١٢٧٦).","grade":"متفق عليه","chapter_ar":"باب جواز طواف المرأة عند إقامة الصلاة لعذر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (123), al-Bukhari (1626), and Muslim (1276).","chapter_en":"The permissibility of a woman performing tawaf when the prayer is established due to an excuse","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":46,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: I complained to the Messenger of Allah ﷺ that I was ill, so he said: “Perform tawaf behind the people while you are riding.” She said: So I performed tawaf riding my camel, while the Messenger of Allah ﷺ was praying beside the House and reciting: “By the Mount, and by a written Book.”"]},"buhuth":{"ar":["وفي رواية: (( إذا أُقِيمَتْ صلاةُ الصُّبحِ فَطُوفي على بعيرِكِ والنَّاسُ يُصلُّون ))."],"en":["In another narration: “When the dawn prayer is established, then perform tawaf on your camel while the people are praying.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":123},{"key":"bukhari","label":"البخاري","number":1626},{"key":"muslim","label":"مسلم","number":1276}]},{"num":5020,"demo":false,"sanad":"","matn":["عن عائشة، قالت: قَدِمْتُ مَكَّةَ وَأَنَا حَائِضٌ، وَلَمْ أَطُفْ بِالْبَيْتِ وَلَا بَيْنَ الصَّفَا وَالْمَرْوَةِ، فَشَكَوْتُ ذَلِكَ إِلَى رَسُولِ اللّٰهِ ﷺ، فَقَالَ: (( افْعَلِي كَمَا يَفْعَلُ الحَاجُّ، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ حَتَّى تَطْهُرِي ))."],"takhrij":"متفق عليه: رواه البخاري (١٦٥٠)، ومسلم (١١٩: ١٢١١).","grade":"متفق عليه","chapter_ar":"باب أن الحائض تفعل كلَّ ما يفعله الحاج غير أنها لا تطوف بالبيت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1650) and Muslim (1211:119).","chapter_en":"A menstruating woman does everything that the pilgrim does except that she does not circumambulate the House","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":47,"content":{"translation":{"en":["Aisha said: I arrived in Mecca while menstruating, and I did not circumambulate the House nor go between al-Safa and al-Marwah. I complained of that to the Messenger of Allah ﷺ, and he said: “Do as the pilgrim does, except that you must not circumambulate the House until you become pure.”"]},"buhuth":{"ar":["ورواه البخاري (٢٩٤)، ومسلم (١١٩: ١٢١١) قالت عائشة: (( خَرَجْنَا لا نَرَى إِلَّا الحَجَّ، فَلَمَّا كُنَّا بِسَرِفَ حِضْتُ، فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ﷺ وَأَنَا أَبْكِي، فَقَالَ: مَا لَكِ أَنَفِسْتِ؟ قُلْتُ: نَعَمْ. قَالَ: إِنَّ هَذَا أَمْرٌ كَتَبَهُ اللَّهُ عَلَى بَنَاتِ آدَمَ، فَاقْضِي مَا يَقْضِي الحَاجُّ، غَيْرَ أَنْ لَا تَطُوفِي بِالْبَيْتِ )). قَالَتْ: (( وَضَحَّى رَسُولُ اللّٰهِ ﷺ عَنْ نِسَائِهِ بِالْبَقَرِ )).","ورواه البخاري (٣٠٥)، ومسلم (١٢٠: ١٢١١) وفيه: (( فافعلي ما يفعل الحاج غير أن لا تطوفي بالبيت حتى تطهري ))."],"en":["Aisha also said, in a narration recorded by al-Bukhari (294) and Muslim (1211:119): “We set out considering only Hajj. When we were at Sarif, I menstruated. The Messenger of Allah ﷺ came to me while I was crying and said: ‘What is the matter? Have you begun menstruating?’ I said: Yes. He said: ‘This is something Allah has decreed upon the daughters of Adam, so do what the pilgrim does, except that you do not circumambulate the House.’” She said: “And the Messenger of Allah ﷺ slaughtered cattle on behalf of his wives.”","Al-Bukhari (305) and Muslim (1211:120) also narrated in it: “So do what the pilgrim does, except that you do not circumambulate the House until you become pure.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1650},{"key":"muslim","label":"مسلم","number":119}]},{"num":5021,"demo":false,"sanad":"","matn":["عن حفصة، قالت: كُنَّا نَمْنَعُ عَوَاتِقَنَا أَنْ يَخْرُجْنَ، فَقَدِمَتِ امْرَأَةٌ فَنَزَلَتْ قَصْرَ بَنِي خَلَفٍ، فَحَدَّثَتْ أَنَّ أُخْتَهَا كَانَتْ تَحْتَ رَجُلٍ مِنْ أَصْحَابِ رَسُولِ اللّٰهِ ﷺ، قَدْ غَزَا مَعَ رَسُولِ اللّٰهِ ﷺ ثِنْتَيْ عَشْرَةَ غَزْوَةً، وَكَانَتْ أُخْتِي مَعَهُ فِي سِتِّ غَزَوَاتٍ، قَالَتْ: كُنَّا نُدَاوِي الْكَلْمَى وَنَقُومُ عَلَى المَرْضَى، فَسَأَلَتْ أُخْتِي رَسُولَ اللّٰهِ ﷺ، فَقَالَتْ: هَلْ عَلَى إِحْدَانَا بَأْسٌ إِنْ لَمْ يَكُنْ لَهَا جِلْبَابٌ أَنْ لَا تَخْرُجَ؟ قَالَ: (( لِتُلْبِسْهَا صَاحِبَتُهَا مِنْ جِلْبَابِهَا، وَلْتَشْهَدِ الخَيْرَ وَدَعْوَةَ المُؤْمِنِينَ )). فَلَمَّا قَدِمَتْ أُمُّ عَطِيَّةَ رَضِيَ اللَّهُ عَنْهَا سَأَلْنَهَا — أَوْ قَالَتْ: سَأَلْنَاهَا — فَقَالَتْ — وَكَانَتْ لَا تَذْكُرُ رَسُولَ اللَّهِ ﷺ أَبَدًا إِلَّا قَالَتْ: بِأَبِي — فَقُلْنَا: أَسَمِعْتِ رَسُولَ اللَّهِ ﷺ يَقُولُ كَذَا وَكَذَا؟ قَالَتْ: نَعَمْ بِأَبِي، فَقَالَ: (( لِتَخْرُجِ العَوَاتِقُ ذَوَاتُ الخُدُورِ — أَوِ العَوَاتِقُ وَذَوَاتُ الخُدُورِ — وَالحُيَّضُ، فَيَشْهَدْنَ الخَيْرَ وَدَعْوَةَ المُسْلِمِينَ، وَيَعْتَزِلُ الحُيَّضُ المُصَلَّى )). فَقُلْتُ: الحائضُ؟ فَقَالَتْ: أَوَلَيْسَ تَشْهَدُ عَرَفَةَ، وَتَشْهَدُ كَذَا، وَتَشْهَدُ كَذَا؟!"],"takhrij":"متفق عليه: رواه البخاري (١٦٥٢)، ومسلم (٨٩٠).","grade":"متفق عليه","chapter_ar":"باب أن الحائض تفعل كلَّ ما يفعله الحاج غير أنها لا تطوف بالبيت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1652) and Muslim (890).","chapter_en":"A menstruating woman does everything that the pilgrim does except that she does not circumambulate the House","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":47,"content":{"translation":{"en":["Hafsah said: We used to keep our young women from going out. Then a woman came and stayed at the palace of Banu Khalaf, and she related that her sister had been married to one of the companions of the Messenger of Allah ﷺ, who had gone out with the Messenger of Allah ﷺ in twelve military expeditions, and my sister had gone with him in six expeditions. She said: We used to tend the wounded and care for the sick. My sister asked the Messenger of Allah ﷺ, saying: Is there any blame upon one of us if she does not have a jilbab and therefore does not go out? He said: “Let her companion lend her one of her jilbabs so that she may witness the good and the supplication of the believers.” Then when Umm ‘Atiyyah, may Allah be pleased with her, came, we asked her — or she said: we asked her — and she said — and she would never mention the Messenger of Allah ﷺ except that she would say, “May my father be sacrificed for him” — so we said: Did you hear the Messenger of Allah ﷺ say such-and-such? She said: Yes, may my father be sacrificed for him. He said: “Let the young women in seclusion, and the women in their private quarters, and the menstruating women go out so that they may witness the good and the supplication of the Muslims, but the menstruating women must keep away from the prayer area.” I said: Even the menstruating woman? She said: Does she not attend ‘Arafah, and attend such-and-such, and attend such-and-such?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1652},{"key":"muslim","label":"مسلم","number":890}]},{"num":5022,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: أَهَلَّ النَّبِيُّ ﷺ هُوَ وَأَصْحَابُهُ بِالحَجِّ … وَحَاضَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا، فَنَسَكَتِ المَنَاسِكَ كُلَّهَا غَيْرَ أَنَّهَا لَمْ تَطُفْ بِالْبَيْتِ، فَلَمَّا طَهُرَتْ طَافَتْ بِالْبَيْتِ. قَالَتْ: يَا رَسُولَ اللَّهِ، تَنْطَلِقُونَ بِحَجَّةٍ وَعُمْرَةٍ، وَأَنْطَلِقُ بِحَجٍّ؟! فَأَمَرَ عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ أَنْ يَخْرُجَ مَعَهَا إِلَى التَّنْعِيمِ، فَاعْتَمَرَتْ بَعْدَ الحَجِّ."],"takhrij":"صحيح: رواه البخاري (١٦٥١).","grade":"صحيح","chapter_ar":"باب أن الحائض تفعل كلَّ ما يفعله الحاج غير أنها لا تطوف بالبيت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1651).","chapter_en":"A menstruating woman does everything that the pilgrim does except that she does not circumambulate the House","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":47,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ and his companions entered into ihram for Hajj … and Aisha, may Allah be pleased with her, menstruated, so she performed all the rites except that she did not circumambulate the House. When she became pure, she circumambulated the House. She said: O Messenger of Allah ﷺ, you are returning with Hajj and ‘Umrah while I return with only Hajj? So he ordered ‘Abd al-Rahman ibn Abi Bakr to go out with her to al-Tan‘im, and she performed ‘Umrah after Hajj."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1651}]},{"num":5023,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: أَقْبَلْنَا مُهِلِّينَ مَعَ رَسُولِ اللّٰهِ ﷺ بِحَجٍّ مُفْرَدٍ، ثُمَّ دَخَلَ رَسُولُ اللّٰهِ ﷺ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَوَجَدَهَا تَبْكِي، فَقَالَ: (( مَا شَأْنُكِ؟ )). قَالَتْ: شَأْنِي أَنِّي حِضْتُ، وَقَدْ حَلَّ النَّاسُ وَلَمْ أَحْلِلْ، وَلَمْ أَطُفْ بِالْبَيْتِ، وَالنَّاسُ يَذْهَبُونَ إِلَى الحَجِّ الآنَ؟ فَقَالَ: (( إِنَّ هَذَا أَمْرٌ كَتَبَهُ اللَّهُ عَلَى بَنَاتِ آدَمَ، فَاغْتَسِلِي ثُمَّ أَهِلِّي بِالحَجِّ )). فَفَعَلَتْ، وَوَقَفَتِ المَوَاقِفَ، حَتَّى إِذَا طَهُرَتْ طَافَتْ بِالْكَعْبَةِ وَالصَّفَا وَالمَرْوَةِ. ثُمَّ قَالَ: (( قَدْ حَلَلْتِ مِنْ حَجِّكِ وَعُمْرَتِكِ جَمِيعًا )). فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي أَجِدُ فِي نَفْسِي أَنِّي لَمْ أَطُفْ بِالْبَيْتِ حَتَّى حَجَجْتُ. قَالَ: (( فَاذْهَبْ بِهَا يَا عَبْدَ الرَّحْمَنِ، فَأَعْمِرْهَا مِنَ التَّنْعِيمِ )). وَذَلِكَ لَيْلَةَ الحَصْبَةِ."],"takhrij":"صحيح: رواه مسلم (١٢١٣).","grade":"صحيح","chapter_ar":"باب أن الحائض تفعل كلَّ ما يفعله الحاج غير أنها لا تطوف بالبيت","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1213).","chapter_en":"A menstruating woman does everything that the pilgrim does except that she does not circumambulate the House","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":47,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We came entering ihram with the Messenger of Allah ﷺ for Hajj alone. Then the Messenger of Allah ﷺ entered upon Aisha, may Allah be pleased with her, and found her crying. He said: “What is the matter with you?” She said: My situation is that I have menstruated, while the people have exited ihram and I have not exited ihram, and I have not circumambulated the House, while the people are now heading to Hajj. He said: “This is something Allah has decreed upon the daughters of Adam, so bathe and then enter ihram for Hajj.” So she did that and stood at the standing places, until when she became pure, she circumambulated the Ka‘bah and al-Safa and al-Marwah. Then he said: “You have now exited from both your Hajj and your ‘Umrah together.” She said: O Messenger of Allah ﷺ, I still feel uneasy that I did not circumambulate the House until after I had done Hajj. He said: “Take her, O ‘Abd al-Rahman, and let her perform ‘Umrah from al-Tan‘im.” And that was on the night of al-Hasbah."]},"buhuth":{"ar":["قوله: (( حتى طهرت طافت بالكعبة، والصفا والمروة )) فيه إشارة إلى أن عائشة رضي الله عنها لم تسعَ حتى طافت طواف الإفاضة، بل قد صرّحت كما في قولها: (( قدمت مكة وأنا حائض ولم أطف بالبيت ولا بين الصفا والمروة ))."],"en":["His words, “until when she became pure, she circumambulated the Ka‘bah and al-Safa and al-Marwah,” indicate that Aisha, may Allah be pleased with her, did not perform sa‘y until after she had performed the Tawaf al-Ifadah. She herself explicitly stated: “I arrived in Mecca while menstruating, and I did not circumambulate the House nor go between al-Safa and al-Marwah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1213}]},{"num":5024,"demo":false,"sanad":"","matn":["عن جابر، قال: قال رسولُ اللّٰهِ ﷺ: (( الِاسْتِجْمَارُ وَتْرٌ، وَرَمْيُ الجِمَارِ وَتْرٌ، وَالسَّعْيُ بَيْنَ الصَّفَا وَالمَرْوَةِ وَالطَّوَافُ وَتْرٌ، وَإِذَا اسْتَجْمَرَ أَحَدُكُمْ فَلْيَسْتَجْمِرْ بِوِتْرٍ ))."],"takhrij":"صحيح: رواه مسلم (١٣٠٠).","grade":"صحيح","chapter_ar":"باب ما جاء أن الطواف وتر والسعي وتر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1300).","chapter_en":"What has been narrated that tawaf is an odd-numbered rite and sa‘y is an odd-numbered rite","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":48,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Cleaning oneself with stones is done in odd numbers, the stoning of the pillars is in odd numbers, sa‘y between al-Safa and al-Marwah and tawaf are in odd numbers, and when one of you cleans himself with stones, let him do so in an odd number.”"]},"buhuth":{"ar":["قوله: (( وتر )) الوتر: بفتح الواو وكسرها، وهو الفرد."],"en":["His statement, “witr,” means an odd number."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1300}]},{"num":5025,"demo":false,"sanad":"","matn":["عن ابن عمر: أنَّ رَسُولَ اللَّهِ ﷺ كَانَ إِذَا طَافَ فِي الحَجِّ وَالْعُمْرَةِ أَوَّلَ مَا يَقْدَمُ، فَإِنَّهُ يَسْعَى ثَلَاثَةَ أَطْوَافٍ بِالْبَيْتِ، ثُمَّ يَمْشِي أَرْبَعَةً، ثُمَّ يُصَلِّي سَجْدَتَيْنِ، ثُمَّ يَطُوفُ بَيْنَ الصَّفَا وَالْمَرْوَةِ."],"takhrij":"متفق عليه: رواه البخاري (١٦١٦)، ومسلم (٢٣١: ١٢٦١)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب لكل سبعة أشواط ركعتان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1616) and Muslim (1261:231), and the wording is that of Muslim.","chapter_en":"For every seven circuits there are two rak‘ahs","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":49,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Messenger of Allah ﷺ performed tawaf in Hajj or ‘Umrah on first arriving, he would walk briskly for three circuits around the House, then walk normally for four, then pray two rak‘ahs, then go between al-Safa and al-Marwah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1616},{"key":"muslim","label":"مسلم","number":231}]},{"num":5026,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: قَدِمَ النَّبِيُّ ﷺ، فَطَافَ بِالْبَيْتِ سَبْعًا، وَصَلَّى خَلْفَ المَقَامِ رَكْعَتَيْنِ، ثُمَّ خَرَجَ إِلَى الصَّفَا، وَقَدْ قَالَ اللَّهُ تَعَالَى: {لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ} [سورة الأحزاب: ٢١]."],"takhrij":"متفق عليه: رواه البخاري (١٦٢٧) و(١٦٤٤، ١٦٢٣)، ومسلم (١٨٩: ١٢٣٤) من طريق سفيان بن عيينة، عن عمرو بن دينار، قال: سألنا ابن عمر رضي الله عنهما عن رجل طاف بالبيت في عمرة ولم يطف بين الصفا والمروة، أأن يأتي امرأته؟ فقال: (فذكره). وزاد البخاري: وسألنا جابر بن عبد الله رضي الله عنهما، فقال: (( لا يقربنها حتى يطوف بين الصفا والمروة )).","grade":"متفق عليه","chapter_ar":"باب استحباب صلاة ركعتي الطواف خلف المقام، والقراءة فيهما بـ {قُلْ هُوَ اللَّهُ أَحَدٌ} و{قُلْ يَا أَيُّهَا الْكَافِرُونَ}","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1627), also (1644, 1623), and Muslim (1234:189) through Sufyan ibn ‘Uyaynah, from ‘Amr ibn Dinar, who said: We asked Ibn ‘Umar, may Allah be pleased with them both, about a man who circumambulated the House in ‘Umrah but did not go between al-Safa and al-Marwah — may he go to his wife? So he mentioned this hadith. Al-Bukhari added: We also asked Jabir ibn ‘Abd Allah, may Allah be pleased with them both, and he said: “He must not go near her until he has gone between al-Safa and al-Marwah.”","chapter_en":"The recommendation of praying the two rak‘ahs of tawaf behind the Maqam, and reciting in them “Say: He is Allah, One” and “Say: O disbelievers”","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":50,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ arrived, circumambulated the House seven times, prayed two rak‘ahs behind the Maqam, then went out to al-Safa. Allah Most High has said: “Indeed, in the Messenger of Allah ﷺ you have an excellent example.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1627},{"key":"و","label":"و","number":1644},{"key":"muslim","label":"مسلم","number":189}]},{"num":5027,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: ثم نَفَذَ — يعني رسولَ اللّٰهِ ﷺ — إلى مقامِ إبراهيمَ عليه السلام، فقرأ: {وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى}، فجعل المقام بينه وبين البيت — فكان أبي يقول: ولا أعلمه ذكره إلا عن النبي ﷺ — كان يقرأ في الركعتين: {قُلْ هُوَ اللَّهُ أَحَدٌ} و{قُلْ يَا أَيُّهَا الْكَافِرُونَ}، ثم رجع إلى الركن فاستلمه."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب استحباب صلاة ركعتي الطواف خلف المقام، والقراءة فيهما بـ {قُلْ هُوَ اللَّهُ أَحَدٌ} و{قُلْ يَا أَيُّهَا الْكَافِرُونَ}","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The recommendation of praying the two rak‘ahs of tawaf behind the Maqam, and reciting in them “Say: He is Allah, One” and “Say: O disbelievers”","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":50,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: Then he went forward — meaning the Messenger of Allah ﷺ — to the Maqam of Ibrahim, peace be upon him, and recited: “And take the standing place of Ibrahim as a place of prayer.” He placed the Maqam between himself and the House — and my father used to say, and I only know that he mentioned it from the Prophet ﷺ — that he used to recite in the two rak‘ahs: “Say: He is Allah, One” and “Say: O disbelievers.” Then he returned to the Corner and touched it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5028,"demo":false,"sanad":"","matn":["عن جبير بن مطعم، قال: قال رسولُ اللّٰهِ ﷺ: (( يَا بَنِي عَبْدِ مَنَافٍ، لا تَمْنَعُوا أَحَدًا طَافَ بِهَذَا الْبَيْتِ وَصَلَّى أَيَّ سَاعَةٍ شَاءَ مِنْ لَيْلٍ أَوْ نَهَارٍ ))."],"takhrij":"حسن: رواه أبو داود (١٨٩٤)، والترمذي (٨٦٨)، والنسائي (٢٩٢٤)، وابن ماجه (١٢٥٤)، وصححه ابن خزيمة (١٢٨٠)، وابن حبان (١٥٥٢)، والحاكم (٤٤٨/١). وقال الترمذي: (( حديث حسن صحيح )).","grade":"حسن","chapter_ar":"باب الطواف بعد الصبح والعصر، وأداء ركعتي الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1894), al-Tirmidhi (868), al-Nasa’i (2924), and Ibn Majah (1254). It was graded authentic by Ibn Khuzaymah (1280), Ibn Hibban (1552), and al-Hakim (1/448). Al-Tirmidhi said: “A Hasan Sahih hadith.”","chapter_en":"Performing tawaf after dawn and after ‘Asr, and praying the two rak‘ahs of tawaf","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":51,"content":{"translation":{"en":["Jubayr ibn Mut‘im said: The Messenger of Allah ﷺ said: “O Banu ‘Abd Manaf, do not prevent anyone who circumambulates this House and prays at any hour he wishes, by night or by day.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1894},{"key":"tirmidhi","label":"الترمذي","number":868},{"key":"nasai","label":"النسائي","number":2924},{"key":"ibnmajah","label":"ابن ماجه","number":1254},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":1280},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2185,"n":2182},{"key":"hakim","label":"المستدرك على الصحيحين","number":1643,"n":1632}]},{"num":5029,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي ﷺ أنها قالت: شَكَوْتُ إِلَى رَسُولِ اللّٰهِ ﷺ أَنِّي أَشْتَكِي، فقال: (( طُوفي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ )).","وفي رواية: (( إذا أُقِيمَتْ صلاةُ الصُّبحِ فَطُوفي على بعيرِكِ والنَّاسُ يُصلُّون )). ففعلتْ ذلك، فلم تُصَلِّ حتى خرجت."],"takhrij":"متفق عليه: رواه مالك (١٢٣)، والبخاري (١٦٣٣)، ومسلم (١٢٧٦). والرواية الثانية: رواها البخاري (١٦٢٦).","grade":"متفق عليه","chapter_ar":"باب من طاف بعد الصبح ولم يصل ركعتي الطواف حتى طلعت الشمس وأداؤهما خارج المسجد الحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (123), al-Bukhari (1633), and Muslim (1276). The second narration was narrated by al-Bukhari (1626).","chapter_en":"Whoever performs tawaf after dawn and does not pray its two rak‘ahs until the sun rises, and praying them outside al-Masjid al-Haram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":52,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: I complained to the Messenger of Allah ﷺ that I was ill, so he said: “Perform tawaf behind the people while you are riding.”","In another narration: “When the dawn prayer is established, then perform tawaf on your camel while the people are praying.” So she did that, and she did not pray until she had gone out."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":123},{"key":"bukhari","label":"البخاري","number":1633},{"key":"muslim","label":"مسلم","number":1276},{"key":"رواہا_البخاری","label":"رواها البخاري","number":1626}]},{"num":5030,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: فجعل — يعني النبيَّ ﷺ — المقامَ بينه وبين البيت، فكان أبي يقول — ولا أعلمه ذكره إلا عن النبي ﷺ — كان يقرأ في الركعتين: {قُلْ هُوَ اللَّهُ أَحَدٌ} و{قُلْ يَا أَيُّهَا الْكَافِرُونَ}، ثم رجع إلى الركن فاستلمه."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب استحباب الرجوع إلى الحجر الأسود لاستلامه بعد ركعتي الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The recommendation of returning to the Black Stone to touch it after the two rak‘ahs of tawaf","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":53,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: He — meaning the Prophet ﷺ — placed the Maqam between himself and the House. My father used to say — and I only know that he mentioned it from the Prophet ﷺ — that he used to recite in the two rak‘ahs: “Say: He is Allah, One” and “Say: O disbelievers,” then he returned to the Corner and touched it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5031,"demo":false,"sanad":"","matn":["عن عروة، قال: قلتُ لعائشة أم المؤمنين — وأنا يومئذٍ حديث السن —: أرأيتِ قولَ الله تبارك وتعالى: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ فَمَنْ حَجَّ البَيْتَ أَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا} [البقرة: ١٥٨]، فما على الرجل شيء أن لا يطوف بهما؟ فقالت عائشة: كلا! لو كان كما تقول، لكانت: فلا جناح عليه أن لا يطوف بهما. إنما أُنزلت هذه الآية في الأنصار، كانوا يُهِلُّونَ لمناة، وكانت مناة حذوَ قُدَيْد، وكانوا يتحرجون أن يطوفوا بين الصفا والمروة، فلما جاء الإسلام سألوا رسول الله ﷺ عن ذلك، فأنزل الله تبارك وتعالى: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ فَمَنْ حَجَّ البَيْتَ أَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا}."],"takhrij":"متفق عليه: رواه مالك (١٢٩)، والبخاري (١٧٩٠)، ومسلم (٢٥٩: ١٢٧٧).","grade":"متفق عليه","chapter_ar":"باب وجوب السعي بين الصفا والمروة في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (129), al-Bukhari (1790), and Muslim (1277:259).","chapter_en":"The obligation of sa‘y between al-Safa and al-Marwah in Hajj and ‘Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":54,"content":{"translation":{"en":["‘Urwah said: I said to Aisha, the Mother of the Believers — and I was young at that time — “What do you think about the statement of Allah, Blessed and Most High: ‘Indeed, al-Safa and al-Marwah are among the symbols of Allah, so whoever performs Hajj of the House or performs ‘Umrah, there is no blame upon him that he goes between them’ — does that mean there is no issue if a person does not go between them?” Aisha said: No. If it were as you say, then it would have said: ‘there is no blame upon him if he does not go between them.’ Rather, this verse was revealed concerning the Ansar. They used to enter ihram for Manat, and Manat was near Qudayd, and they used to feel uneasy about going between al-Safa and al-Marwah. So when Islam came, they asked the Messenger of Allah ﷺ about that, and Allah, Blessed and Most High, revealed: ‘Indeed, al-Safa and al-Marwah are among the symbols of Allah, so whoever performs Hajj of the House or performs ‘Umrah, there is no blame upon him that he goes between them.’”"]},"buhuth":{"ar":["ورواه ابن خزيمة (٢٧٦٩) وفيه قالت عائشة: فلعمري ما أتمَّ الله حجَّ من لم يطف بين الصفا والمروة؛ لأنَّ الله تعالى يقول: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ} فهما من شعائر الله."],"en":["Ibn Khuzaymah also narrated it (2769), in which Aisha said: By my life, Allah has not completed the Hajj of the one who does not go between al-Safa and al-Marwah, because Allah Most High says: “Indeed, al-Safa and al-Marwah are among the symbols of Allah,” and they are among the symbols of Allah."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":129},{"key":"bukhari","label":"البخاري","number":1790},{"key":"muslim","label":"مسلم","number":259}]},{"num":5032,"demo":false,"sanad":"","matn":["عن عاصم، قال: قلتُ لأنس بن مالك: أكنتم تكرهون السعي بين الصفا والمروة؟ قال: نعم، لأنها كانت من شعائر الجاهلية، حتى أنزل الله: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ فَمَنْ حَجَّ البَيْتَ أَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا}."],"takhrij":"متفق عليه: رواه البخاري (١٦٤٨)، ومسلم (١٢٧٨)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب وجوب السعي بين الصفا والمروة في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1648) and Muslim (1278), and the wording is that of al-Bukhari.","chapter_en":"The obligation of sa‘y between al-Safa and al-Marwah in Hajj and ‘Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":54,"content":{"translation":{"en":["‘Asim said: I said to Anas ibn Malik, “Did you use to dislike sa‘y between al-Safa and al-Marwah?” He said: “Yes, because it had been among the rites of the age of ignorance, until Allah revealed: ‘Indeed, al-Safa and al-Marwah are among the symbols of Allah, so whoever performs Hajj of the House or performs ‘Umrah, there is no blame upon him that he goes between them.’”"]},"buhuth":{"ar":["قوله تعالى: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ} يدلّ على أن السعي بينهما أمر حتم لا بدّ منه؛ لأن شعائر الله عظيمة لا يجوز التهاون بها."],"en":["The statement of Allah Most High, “Indeed, al-Safa and al-Marwah are among the symbols of Allah,” indicates that going between them is a binding rite that cannot be omitted, because the symbols of Allah are great matters that must not be treated lightly."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1648},{"key":"muslim","label":"مسلم","number":1278}]},{"num":5033,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، أنه رأى رسولَ اللّٰه ﷺ يسعى بين الصفا والمروة في المسعى كاشفًا عن ثوبه، قد بلغ إلى ركبتيه."],"takhrij":"حسن: رواه عبد اللّٰه بن أحمد من زياداته على المسند (٥٩٧)، والبزار - كشف الأستار (١١١٧).","grade":"حسن","chapter_ar":"باب كيف السعي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by ‘Abdullah ibn Ahmad in his additions to al-Musnad (597), and al-Bazzar in Kashf al-Astar (1117).","chapter_en":"How the sa‘y is performed","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":55,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported that he saw the Messenger of Allah ﷺ performing sa‘y between al-Safa and al-Marwah in the place of sa‘y, with his garment lifted, reaching up to his knees."]}},"tuhfa":{},"refs":[{"key":"عبد_اللہ_بن_احمد_من_زیاداتہ_علی_المسند","label":"عبد اللّٰه بن أحمد من زياداته على المسند","number":597},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1117}]},{"num":5034,"demo":false,"sanad":"","matn":["عن حبيبة بنت أبي تجراة، قالت: دَخَلْنَا دَارَ أَبِي حُسَيْنٍ فِي نِسْوَةٍ مِنْ قُرَيْشٍ، وَالنَّبِيُّ ﷺ يَطُوفُ بَيْنَ الصَّفَا وَالْمَرْوَةِ، قالت: وهو يَسْعَى يَدُورُ بِهِ إِزَارُهُ مِنْ شِدَّةِ السَّعْيِ، وهو يقول لأصحابه: (( اسْعَوْا فَإِنَّ اللّٰهَ كَتَبَ عَلَيْكُمُ السَّعْيَ ))."],"takhrij":"حسن: رواه أحمد (٢٧٣٦٧) - واللفظ له -، والطبراني (٢٢٧/٢٤)، والدارقطني (٢٥٨٤).","grade":"حسن","chapter_ar":"باب كيف السعي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27367) — and this is his wording — al-Tabarani (24/227), and al-Daraqutni (2584).","chapter_en":"How the sa‘y is performed","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":55,"content":{"translation":{"en":["Habibah bint Abi Tajrah said: We entered the house of Abu Husayn along with some women of Quraysh while the Prophet ﷺ was going between al-Safa and al-Marwah. She said: He was moving quickly, and his lower garment was turning about him because of the intensity of his sa‘y, and he was saying to his companions: “Perform sa‘y, for Allah has prescribed sa‘y upon you.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی","label":"الطبراني","number":227},{"key":"الدارقطنی","label":"الدارقطني","number":2584},{"key":"ahmad","label":"مسند الإمام أحمد","number":27367,"n":27367}]},{"num":5035,"demo":false,"sanad":"","matn":["عن سعيد بن جبير، قال: رأيتُ ابنَ عمر يمشي بين الصفا والمروة، ثم قال: إنْ أمشِ فقد رأيتُ رسولَ الله ﷺ يمشي، وإنْ أسعَ فقد رأيتُ رسولَ اللّٰه ﷺ يسعى."],"takhrij":"صحيح: رواه النسائي (٢٩٧٧)، والإمام أحمد (٦٣٩٣).","grade":"صحيح","chapter_ar":"باب كيف السعي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (2977) and Imam Ahmad (6393).","chapter_en":"How the sa‘y is performed","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":55,"content":{"translation":{"en":["Sa‘id ibn Jubayr said: I saw Ibn ‘Umar walking between al-Safa and al-Marwah. Then he said: If I walk, I have seen the Messenger of Allah ﷺ walk; and if I move quickly, I have seen the Messenger of Allah ﷺ move quickly."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2977},{"key":"الامام_احمد","label":"الإمام أحمد","number":6393},{"key":"ahmad","label":"مسند الإمام أحمد","number":6393,"n":6393}]},{"num":5036,"demo":false,"sanad":"","matn":["عن ابن عمر، أنَّ رسولَ اللّٰه ﷺ كان إذا طاف بالبيت الطواف الأول خَبَّ ثلاثًا ومشى أربعًا، وكان يسعى ببطن المسيل إذا طاف بين الصفا والمروة.","وكان ابن عمر يفعل ذلك."],"takhrij":"متفق عليه: رواه البخاري (١٦١٧)، ومسلم (١٢٦١/٢٣٠).","grade":"متفق عليه","chapter_ar":"باب السعي في بطن المسيل بشدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1617) and Muslim (1261/230).","chapter_en":"Moving quickly in the bottom of the valley","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":56,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Messenger of Allah ﷺ performed the first tawaf around the House, he would move briskly for three circuits and walk for four, and he would move quickly in the bottom of the valley when he went between al-Safa and al-Marwah.","And Ibn ‘Umar used to do that."]},"buhuth":{"ar":["وقوله: (( بطن المسيل )) وهو المكان الذي يجتمع فيه ماء السيل، وهو الآن يُعرف بين العَلَمَيْن الأخضرين."],"en":["His statement, “the bottom of the valley,” means the place where the floodwater gathers, and it is now known as the area between the two green markers."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1617},{"key":"muslim","label":"مسلم","number":1261}]},{"num":5037,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: إنما سعى رسولُ اللّٰه ﷺ بالبيت وبين الصفا والمروة لِيُرِيَ المشركين قوته."],"takhrij":"متفق عليه: رواه البخاري (١٦٤٩)، ومسلم (١٢٦٥/٢٤١).","grade":"متفق عليه","chapter_ar":"باب السعي في بطن المسيل بشدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1649) and Muslim (1265/241).","chapter_en":"Moving quickly in the bottom of the valley","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":56,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ only moved quickly around the House and between al-Safa and al-Marwah in order to show the idolaters his strength."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1649},{"key":"muslim","label":"مسلم","number":1265}]},{"num":5038,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله: أنَّ رسولَ اللّٰه ﷺ كان إذا نزل من الصفا إلى المروة مشى، حتى إذا انصبت قدماه في بطن الوادي سعى حتى يخرج منه."],"takhrij":"صحيح: رواه مالك (١٣١)، ومسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب السعي في بطن المسيل بشدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (131) and Muslim (1218).","chapter_en":"Moving quickly in the bottom of the valley","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":56,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that when the Messenger of Allah ﷺ descended from al-Safa toward al-Marwah, he would walk until his feet reached the bottom of the valley, then he would move quickly until he came out of it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":131},{"key":"muslim","label":"مسلم","number":1218}]},{"num":5039,"demo":false,"sanad":"","matn":["عن صفية بنت شيبة، عن امرأة قالت: رأيتُ رسولَ اللّٰه ﷺ يسعى في بطن المسيل ويقول: (( لا يُقطعُ الوادي إلا شدًّا ))."],"takhrij":"صحيح: رواه النسائي (٢٩٨٠)، والإمام أحمد (٢٧٢٨١)، والبيهقي (٩٨/٥).","grade":"صحيح","chapter_ar":"باب السعي في بطن المسيل بشدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (2980), Imam Ahmad (27281), and al-Bayhaqi (5/98).","chapter_en":"Moving quickly in the bottom of the valley","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":56,"content":{"translation":{"en":["Safiyyah bint Shaybah narrated from a woman, who said: I saw the Messenger of Allah ﷺ performing sa‘y in the bottom of the valley and saying: “The valley is not crossed except with vigorous movement.”"]},"buhuth":{"ar":["وهذا خاص بالرجال دون النساء."],"en":["This applies specifically to men and not to women."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2980},{"key":"الامام_احمد","label":"الإمام أحمد","number":27281},{"key":"البیہقی","label":"البيهقي","number":98},{"key":"ahmad","label":"مسند الإمام أحمد","number":27281,"n":27281}]},{"num":5040,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: … ثم خرج من الباب إلى الصفا، فلما دنا من الصفا قرأ: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ} [البقرة: ١٥٨]، (( أبدأ بما بدأ الله به )). فبدأ بالصفا فرقي عليه… حتى إذا كان آخر طوافه على المروة قال: (( لو أني استقبلت من أمري ما استدبرت، لم أسق الهدي، وجعلتها عمرة، فمن كان منكم ليس معه هدي فليحل، وليجعلها عمرة )) … الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب أن السعي سبعة أشواط يبدأ بالصفا وينتهي بالمروة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The sa‘y is seven circuits, beginning at al-Safa and ending at al-Marwah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":57,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: … Then he went out through the door to al-Safa, and when he came near al-Safa he recited: “Indeed, al-Safa and al-Marwah are among the symbols of Allah,” and said: “I begin with what Allah began with.” So he began with al-Safa and climbed it … until when his final circuit ended at al-Marwah, he said: “If I had known beforehand what I came to know later, I would not have brought the sacrificial animals, and I would have made it an ‘Umrah. So whoever among you does not have a sacrificial animal with him, let him exit ihram and make it an ‘Umrah.” … the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5041,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: قدم النبيُّ ﷺ مكة، فطاف وسعى بين الصفا والمروة، ولم يقرب الكعبة بعد طوافه بها حتى رجع من عرفة."],"takhrij":"صحيح: رواه البخاري (١٦٢٥).","grade":"صحيح","chapter_ar":"باب بقي النبي في منزله بعد الطواف والسعي ولم يرجع إلى الكعبة إلا لطواف الإفاضة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1625).","chapter_en":"The Prophet ﷺ remained at his lodging after tawaf and sa‘y and did not return to the Ka‘bah except for Tawaf al-Ifadah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":58,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas said: The Prophet ﷺ came to Mecca, performed tawaf and sa‘y between al-Safa and al-Marwah, and did not approach the Ka‘bah again after that tawaf until he returned from ‘Arafah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1625}]},{"num":5042,"demo":false,"sanad":"","matn":["عن عائشة، عن النبيِّ ﷺ قال: (( إنما جُعل رمي الجمار والسعي بين الصفا والمروة لإقامة ذكر الله ))."],"takhrij":"حسن: رواه أبو داود (١٨٨٨)، والترمذي (٩٠٢) وقال: (( حديث حسن صحيح )).","grade":"حسن","chapter_ar":"باب ما شُرِعَ رمي الجمار والسعي إلا لإقامة ذكر الله","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1888) and al-Tirmidhi (902), who said: “A Hasan Sahih hadith.”","chapter_en":"The stoning of the pillars and the sa‘y were only prescribed for the establishment of the remembrance of Allah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":59,"content":{"translation":{"en":["‘Aishah reported from the Prophet ﷺ that he said: “The stoning of the pillars and the sa‘y between al-Safa and al-Marwah were only prescribed for the establishment of the remembrance of Allah.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1888},{"key":"tirmidhi","label":"الترمذي","number":902}]},{"num":5043,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: (( … وجعلت أم إسماعيل تُرضع إسماعيل وتشرب من ذلك الماء، حتى إذا نفد ما في السقاء عطشت وعطش ابنها، وجعلت تنظر إليه يتلوى - أو قال: يتلبط - فانطلقت كراهية أن تنظر إليه، فوجدت الصفا أقرب جبل في الأرض يليها، فقامت عليه، ثم استقبلت الوادي تنظر هل ترى أحدًا، فلم تر أحدًا، فهبطت من الصفا حتى إذا بلغت الوادي رفعت طرف درعها، ثم سعت سعي الإنسان المجهود حتى جاوزت الوادي، ثم أتت المروة فقامت عليها ونظرت هل ترى أحدًا، فلم تر أحدًا، ففعلت ذلك سبع مرات )).","قال ابن عباس: قال النبي ﷺ: (( فذلك سعي الناس بينهما ))."],"takhrij":"صحيح: رواه البخاري (٣٣٦٤).","grade":"صحيح","chapter_ar":"باب في بيان سبب السعي بين الصفا والمروة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3364).","chapter_en":"Clarifying the reason for sa‘y between al-Safa and al-Marwah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":60,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas said: “… The mother of Isma‘il began nursing Isma‘il and drinking from that water, until when what was in the waterskin was exhausted, she became thirsty and her son became thirsty. She began looking at him writhing — or he said: tossing — so she went off, disliking to keep looking at him. She found al-Safa to be the nearest hill on the land beside her, so she stood upon it, then faced the valley to see whether she could see anyone, but she saw no one. Then she came down from al-Safa until when she reached the valley, she lifted the edge of her garment and ran with the running of an exhausted person until she crossed the valley. Then she came to al-Marwah and stood upon it and looked whether she could see anyone, but she saw no one. She did that seven times.”","Ibn ‘Abbas said: The Prophet ﷺ said: “That is the sa‘y of the people between them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3364}]},{"num":5044,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: طاف النبيُّ ﷺ في حجة الوداع على راحلته بالبيت، وبين الصفا والمروة، ليراه الناس وليُشرف وليَسألوه، فإن الناس غشوه."],"takhrij":"صحيح: رواه مسلم (١٢٧٣/٢٥٥).","grade":"صحيح","chapter_ar":"باب في جواز السعي بين الصفا والمروة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1273/255).","chapter_en":"The permissibility of performing sa‘y between al-Safa and al-Marwah riding or walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":61,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ performed tawaf in the Farewell Pilgrimage on his mount around the House and between al-Safa and al-Marwah, so that the people could see him, and so that he could be elevated above them, and so that they could ask him, for the people had crowded around him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1273}]},{"num":5045,"demo":false,"sanad":"","matn":["عن جابر، أنَّ رسولَ الله ﷺ كان إذا نزل من الصفا والمروة مشى، حتى إذا انصبت قدماه في بطن الوادي سعى حتى يخرج منه."],"takhrij":"صحيح: رواه مالك (١٣١). وفي رواية للنسائي (٢٩٧٤): (( ثم نزل ماشيًا حتى تصوبت قدماه في بطن المسيل )).","grade":"صحيح","chapter_ar":"باب في جواز السعي بين الصفا والمروة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (131). In a narration of al-Nasa’i (2974): “Then he descended walking until his feet sloped into the bottom of the watercourse.”","chapter_en":"The permissibility of performing sa‘y between al-Safa and al-Marwah riding or walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":61,"content":{"translation":{"en":["Jabir reported that when the Messenger of Allah ﷺ descended from al-Safa toward al-Marwah, he would walk, and when his feet sloped down into the bottom of the valley he would move quickly until he came out of it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":131},{"key":"وفی_روایہ_للنسایی","label":". وفي رواية للنسائي","number":2974}]},{"num":5046,"demo":false,"sanad":"","matn":["عن أبي الطفيل، قال: قلت لابن عباس: أخبرني عن الطواف بين الصفا والمروة راكبًا، أسنّة هو؟ فإن قومك يزعمون أنه سنة. قال: صدقوا وكذبوا! قلت: وما قولك: صدقوا وكذبوا؟ قال: إن رسول الله ﷺ كثر عليه الناس يقولون: هذا محمد، هذا محمد، حتى خرج العواتق من البيوت. قال: وكان رسول الله ﷺ لا يُضرَب الناس بين يديه، فلما كثر عليه ركب، والمشي والسعي أفضل."],"takhrij":"صحيح: رواه مسلم (١٢٦٤).","grade":"صحيح","chapter_ar":"باب في جواز السعي بين الصفا والمروة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1264).","chapter_en":"The permissibility of performing sa‘y between al-Safa and al-Marwah riding or walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":61,"content":{"translation":{"en":["Abu al-Tufayl said: I said to Ibn ‘Abbas: Tell me about going between al-Safa and al-Marwah while riding — is that a Sunnah? For your people claim that it is a Sunnah. He said: They are right and they are wrong. I said: What do you mean by saying they are right and they are wrong? He said: The Messenger of Allah ﷺ had many people crowd around him, saying: This is Muhammad, this is Muhammad, until even the young women came out from the houses. And the Messenger of Allah ﷺ was not one before whom people were struck aside. So when the crowd increased around him, he rode, while walking and moving quickly on foot is better."]},"buhuth":{"ar":["قوله: (( صدقوا وكذبوا )) قال النووي: يعني صدقوا في أنه طاف راكبًا، وكذبوا في أن الركوب أفضل، بل المشي أفضل."],"en":["His statement, “They are right and they are wrong,” was explained by al-Nawawi as meaning: they are right that he performed it while riding, and wrong in claiming that riding is better; rather, walking is better."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1264}]},{"num":5047,"demo":false,"sanad":"","matn":["عن أبي الطفيل، قال: قلت لابن عباس: أُراني قد رأيتُ رسولَ اللّٰه ﷺ. قال: فصفه لي. قال: قلت: رأيته عند المروة على ناقة وقد كثر الناس عليه. قال: فقال ابن عباس: (( ذاك رسول الله ﷺ، إنهم كانوا لا يُدَعُّون عنه ولا يُكرهون ))."],"takhrij":"صحيح: رواه مسلم (١٢٦٥).","grade":"صحيح","chapter_ar":"باب في جواز السعي بين الصفا والمروة راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1265).","chapter_en":"The permissibility of performing sa‘y between al-Safa and al-Marwah riding or walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":61,"content":{"translation":{"en":["Abu al-Tufayl said: I said to Ibn ‘Abbas: I think I may have seen the Messenger of Allah ﷺ. He said: Then describe him to me. He said: I said: I saw him at al-Marwah on a she-camel, while many people had gathered around him. Ibn ‘Abbas then said: “That was the Messenger of Allah ﷺ. They did not drive people away from him, nor were they harsh with them.”"]},"buhuth":{"ar":["مشى أولًا، فلما كثر عليه الناس ركب، كما في روايات مسلم.","ويستفاد من أحاديث الباب أن النبي ﷺ جمع بين المشي والركوب في سعيه في حجة الوداع."],"en":["He first walked, then when the crowd around him increased, he rode, as is found in the narrations of Muslim.","What is understood from the hadiths of this chapter is that the Prophet ﷺ combined both walking and riding in his sa‘y during the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1265}]},{"num":5048,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: … وأقبل رسولُ اللّٰه ﷺ حتى أقبل إلى الحجر فاستلمه، ثم طاف بالبيت، قال: فأتى على صنم إلى جنب البيت كانوا يعبدونه، قال: وفي يد رسول الله ﷺ قوس، وهو آخذ بسية القوس، فلما أتى على الصنم جعل يطعنه في عينه ويقول: {جَاءَ الحَقُّ وَزَهَقَ البَاطِلُ}. قال: فلما فرغ من طوافه أتى الصفا فعلا عليه حتى نظر إلى البيت، ورفع يديه فجعل يحمد الله ويدعو… الحديث."],"takhrij":"صحيح: رواه مسلم (١٧٨٠).","grade":"صحيح","chapter_ar":"باب استحباب الصعود على الصفا والمروة واستقبال الكعبة والتكبير والتهليل والدعاء عليهما مع رفع اليدين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1780).","chapter_en":"The recommendation of ascending al-Safa and al-Marwah, facing the Ka‘bah, saying takbir and tahlil, and making supplication upon them while raising the hands","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":62,"content":{"translation":{"en":["Abu Hurayrah said: … The Messenger of Allah ﷺ came until he came to the Black Stone and touched it, then he circumambulated the House. He then came upon an idol beside the House which they used to worship. In the hand of the Messenger of Allah ﷺ was a bow, and he was holding it by its curved end. When he came to the idol, he began striking at its eye and saying: “Truth has come, and falsehood has vanished.” Then when he finished his tawaf, he went to al-Safa and climbed it until he looked toward the House, and he raised his hands and began praising Allah and supplicating … the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1780}]},{"num":5049,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: فلما دنا من الصفا قرأ: {إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ}، (( أبدأ بما بدأ الله به )). فبدأ بالصفا، فرقي عليه حتى رأى البيت، فاستقبل القبلة، فوحد الله وكبره، وقال: (( لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا إله إلا الله وحده، أنجز وعده، ونصر عبده، وهزم الأحزاب وحده )). ثم دعا بين ذلك، قال مثل هذا ثلاث مرات، ثم نزل إلى المروة حتى إذا انصبت قدماه في بطن الوادي سعى، حتى إذا صعدتا مشى، حتى أتى المروة ففعل على المروة كما فعل على الصفا."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب استحباب الصعود على الصفا والمروة واستقبال الكعبة والتكبير والتهليل والدعاء عليهما مع رفع اليدين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The recommendation of ascending al-Safa and al-Marwah, facing the Ka‘bah, saying takbir and tahlil, and making supplication upon them while raising the hands","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":62,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: When he came near al-Safa, he recited: “Indeed, al-Safa and al-Marwah are among the symbols of Allah,” and said: “I begin with what Allah began with.” So he began with al-Safa and climbed it until he could see the House. He then faced the qiblah, declared Allah’s oneness, magnified Him, and said: “There is no god but Allah alone, with no partner. To Him belongs all dominion and all praise, and He has power over all things. There is no god but Allah alone. He fulfilled His promise, granted victory to His servant, and defeated the confederates alone.” Then he supplicated between that. He said this same statement three times. Then he descended toward al-Marwah, and when his feet went down into the bottom of the valley, he moved quickly; when they rose, he walked, until he came to al-Marwah and did upon al-Marwah as he had done upon al-Safa."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5050,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: تمتع رسولُ اللّٰه ﷺ في حجة الوداع بالعمرة إلى الحج، وأهدى فساق معه الهدي من ذي الحليفة، وبدأ رسولُ اللّٰه ﷺ فأهلَّ بالعمرة، ثم أهلَّ بالحج، فتمتع الناس مع النبي ﷺ بالعمرة إلى الحج، فكان من الناس من أهدى فساق الهدي، ومنهم من لم يُهدِ، فلما قدم النبي ﷺ مكة قال للناس: (( من كان منكم أهدى، فإنه لا يحل لشيء حرم منه حتى يقضي حجَّه، ومن لم يكن منكم أهدى، فليطف بالبيت وبالصفا والمروة وليقصِّر وليحلِل، ثم ليُهِلَّ بالحج، فمن لم يجد هديًا فليصم ثلاثة أيام في الحج وسبعة إذا رجع إلى أهله ))."],"takhrij":"متفق عليه: رواه البخاري (١٦٩١) - واللفظ له -، ومسلم (١٢٢٧).","grade":"متفق عليه","chapter_ar":"باب أن المتمتع يتحلل من عمرته بتقصير شعره وعليه هدي التمتع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1691) — and this is his wording — and Muslim (1227).","chapter_en":"The one performing tamattu‘ exits from his ‘Umrah by shortening his hair, and the sacrificial offering of tamattu‘ is due upon him","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":63,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ performed tamattu‘ in the Farewell Pilgrimage by doing ‘Umrah before Hajj, and he brought a sacrificial offering and drove it with him from Dhu al-Hulayfah. The Messenger of Allah ﷺ began by entering ihram for ‘Umrah, then entered ihram for Hajj. The people also performed tamattu‘ with the Prophet ﷺ from ‘Umrah into Hajj. Among the people were those who had sacrificial animals and drove them along, and among them were those who did not. When the Prophet ﷺ came to Mecca, he said to the people: “Whoever among you has brought a sacrificial animal, then nothing that he entered into prohibition becomes lawful for him until he completes his Hajj. And whoever among you has not brought a sacrificial animal, let him circumambulate the House and go between al-Safa and al-Marwah, then shorten his hair and exit ihram, then enter ihram for Hajj. And whoever cannot find a sacrificial animal must fast three days during Hajj and seven when he returns to his family.”"]},"buhuth":{"ar":["قوله: (( وليقصِّر )) أي من شعره، وإنما أُمروا بالتقصير لقربهم من الإهلال بالحج، وليتمكنوا من الحلق في الحج، وهو أفضل من التقصير."],"en":["His statement, “let him shorten,” means from his hair. They were instructed to shorten because they were close to entering ihram for Hajj again, so that they would still be able to shave their heads during Hajj, and shaving is better than shortening."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1691},{"key":"muslim","label":"مسلم","number":1227}]},{"num":5051,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أنه حج مع النبيِّ ﷺ يوم ساق البدن معه، وقد أهلوا بالحج مفردًا، فقال لهم: (( أَحِلُّوا من إحرامكم بطواف البيت وبين الصفا والمروة، وقصِّروا، ثم أقيموا حلالًا حتى إذا كان يوم التروية فأهلوا بالحج، واجعلوا التي قدمتم بها متعة )). فقالوا: كيف نجعلها متعة وقد سمينا الحج؟ فقال: (( افعلوا ما أمرتكم، فلولا أني سقت الهدي لفعلت مثل الذي أمرتكم، ولكن لا يحل مني حرام حتى يبلغ الهدي محله )). ففعلوا."],"takhrij":"متفق عليه: رواه البخاري (١٥٦٨)، ومسلم (١٢١٦/١٤٣). وفي رواية أخرى عند البخاري (١٦٥١) بلفظ: (( فأمر النبي ﷺ أصحابه أن يجعلوها عمرة ويطوفوا، ثم يقصِّروا ويحلّوا إلا من كان معه الهدي… )).","grade":"متفق عليه","chapter_ar":"باب أن المتمتع يتحلل من عمرته بتقصير شعره وعليه هدي التمتع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1568) and Muslim (1216/143). In another narration in al-Bukhari (1651): “The Prophet ﷺ ordered his companions to make it an ‘Umrah, to perform tawaf, then shorten their hair and exit ihram, except those who had a sacrificial animal with them…”","chapter_en":"The one performing tamattu‘ exits from his ‘Umrah by shortening his hair, and the sacrificial offering of tamattu‘ is due upon him","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":63,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that he performed Hajj with the Prophet ﷺ on the day he had brought the sacrificial camels with him, while they had entered ihram for Hajj alone. So he said to them: “Exit from your ihram by circumambulating the House and going between al-Safa and al-Marwah, and shorten your hair, then remain in a lawful state until, when the Day of Tarwiyah comes, enter ihram for Hajj, and make what you first came with into tamattu‘.” They said: How can we make it tamattu‘ when we have named Hajj? He said: “Do what I have commanded you. If I had not brought the sacrificial animal, I would have done as I commanded you. But nothing prohibited in ihram becomes lawful for me until the sacrificial animal reaches its place.” So they did that."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1568},{"key":"muslim","label":"مسلم","number":1216},{"key":"وفی_روایہ_اخری_عند_البخاری","label":". وفي رواية أخرى عند البخاري","number":1651}]},{"num":5052,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: حتى إذا كان آخر طوافه على المروة قال: (( لو أني استقبلت من أمري ما استدبرت، لم أسق الهدي، وجعلتها عمرة، فمن كان منكم ليس معه هدي فليحل، وليجعلها عمرة )). … قال: فحلَّ الناس كلهم وقصَّروا إلا النبي ﷺ ومن كان معه هدي."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب أن المتمتع يتحلل من عمرته بتقصير شعره وعليه هدي التمتع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The one performing tamattu‘ exits from his ‘Umrah by shortening his hair, and the sacrificial offering of tamattu‘ is due upon him","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":63,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: When his final circuit ended at al-Marwah, he said: “If I had known beforehand what I came to know later, I would not have brought the sacrificial animal, and I would have made it an ‘Umrah. So whoever among you does not have a sacrificial animal with him, let him exit ihram and make it an ‘Umrah.” … He said: So all the people exited ihram and shortened their hair except the Prophet ﷺ and those who had a sacrificial animal with them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5053,"demo":false,"sanad":"","matn":["عن عمرو بن دينار، قال: سألنا ابن عمر عن رجل قدم بعمرة فطاف بالبيت ولم يطف بين الصفا والمروة، أيأتي امرأته؟ فقال: قدم النبيُّ ﷺ فطاف بالبيت سبعًا، وصلى خلف المقام ركعتين، ثم خرج إلى الصفا، وقد قال الله تعالى: {لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ} [سورة الأحزاب: ٢١]."],"takhrij":"متفق عليه: رواه البخاري (١٦٤٤، ١٦٢٣)، ومسلم (١٢٣٤/١٨٩). وزاد البخاري (١٦٢٤، ١٦٤٥): وسألنا جابر بن عبد الله رضي الله عنهما، فقال: (( لا يقربنها حتى يطوف بين الصفا والمروة )).","grade":"متفق عليه","chapter_ar":"باب أن التحلل من العمرة لا يكون إلا بعد السعي بين الصفا والمروة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1644, 1623) and Muslim (1234/189). Al-Bukhari added (1624, 1645): We also asked Jabir ibn ‘Abd Allah, may Allah be pleased with them both, and he said: “He must not go near her until he has gone between al-Safa and al-Marwah.”","chapter_en":"Exiting ihram from ‘Umrah does not occur until after sa‘y between al-Safa and al-Marwah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":64,"content":{"translation":{"en":["‘Amr ibn Dinar said: We asked Ibn ‘Umar about a man who arrived for ‘Umrah, circumambulated the House, but did not go between al-Safa and al-Marwah — may he go to his wife? He said: The Prophet ﷺ arrived and circumambulated the House seven times, prayed two rak‘ahs behind the Maqam, then went out to al-Safa. Allah Most High has said: “Indeed, in the Messenger of Allah you have an excellent example.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1644},{"key":"muslim","label":"مسلم","number":1234},{"key":"وزاد_البخاری","label":". وزاد البخاري","number":1624}]},{"num":5054,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خرجنا مع رسولِ الله ﷺ لخمس بقين من ذي القعدة لا نرى إلا الحج، فدنونا من مكة، أمر رسولُ الله ﷺ من لم يكن معه هدي إذا طاف وسعى بين الصفا والمروة أن يحل."],"takhrij":"متفق عليه: رواه البخاري (١٧٠٩)، ومسلم (١٢١١/١٢٥).","grade":"متفق عليه","chapter_ar":"باب أن التحلل من العمرة لا يكون إلا بعد السعي بين الصفا والمروة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1709) and Muslim (1211/125).","chapter_en":"Exiting ihram from ‘Umrah does not occur until after sa‘y between al-Safa and al-Marwah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":64,"content":{"translation":{"en":["‘Aishah said: We went out with the Messenger of Allah ﷺ with five nights remaining in Dhu al-Qa‘dah, seeing nothing but Hajj. When we drew near to Mecca, the Messenger of Allah ﷺ ordered those who did not have a sacrificial animal with them to exit ihram once they had performed tawaf and sa‘y between al-Safa and al-Marwah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1709},{"key":"muslim","label":"مسلم","number":1211}]},{"num":5055,"demo":false,"sanad":"","matn":["عن ابن عباس، أنه سُئِلَ عن متعة الحج؟ فقال: أهلَّ المهاجرون والأنصار وأزواجُ النبيِّ ﷺ في حجة الوداع، وأهللنا، فلما قدمنا مكة، قال رسولُ اللّٰه ﷺ: (( اجعلوا إهلالكم بالحج عمرة إلا من قلَّد الهدي )). فطفنا بالبيت وبالصفا والمروة وأتينا النساء ولبسنا الثياب… الحديث."],"takhrij":"صحيح: علَّقه البخاري في الحج (١٥٧٢). قال الحافظ في “الفتح” (٤٣٤/٣): (( وصله الإسماعيلي )).","grade":"صحيح","chapter_ar":"باب أن التحلل من العمرة لا يكون إلا بعد السعي بين الصفا والمروة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Al-Bukhari mentioned it in suspended form in the Book of Hajj (1572). Al-Hafiz said in al-Fath (3/434): “Al-Isma‘ili connected its chain.”","chapter_en":"Exiting ihram from ‘Umrah does not occur until after sa‘y between al-Safa and al-Marwah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":64,"content":{"translation":{"en":["Ibn ‘Abbas was asked about tamattu‘ in Hajj, so he said: The Muhajirun, the Ansar, and the wives of the Prophet ﷺ entered ihram in the Farewell Pilgrimage, and we also entered ihram. When we came to Mecca, the Messenger of Allah ﷺ said: “Make your ihram for Hajj into an ‘Umrah, except for the one who has garlanded the sacrificial animal.” So we circumambulated the House, went between al-Safa and al-Marwah, approached our wives, and wore clothes … the hadith."]}},"tuhfa":{},"refs":[{"key":"علقہ_البخاری/الحج","label":"علَّقه البخاري في الحج","number":1572},{"key":"قال_الحافظ/الفتح","label":". قال الحافظ في “الفتح”","number":434}]},{"num":5056,"demo":false,"sanad":"","matn":["عن عائشة، أنها قالت: خرجنا مع النبيِّ ﷺ في حجة الوداع فأهللنا بعمرة، ثم قال النبيُّ ﷺ: (( من كان معه هدي فليُهِلَّ بالحج مع العمرة، ثم لا يحل حتى يحل منهما جميعًا )). قالت: فقدمت مكة وأنا حائض ولم أطف بالبيت ولا بين الصفا والمروة، فشكوت ذلك إلى النبي ﷺ فقال: (( انقضي رأسك وامتشطي وأهلي بالحج ودعي العمرة )). قالت: ففعلت، فلما قضينا الحج أرسلني النبي ﷺ مع عبد الرحمن بن أبي بكر إلى التنعيم فاعتمرت، فقال: (( هذه مكان عمرتك )). قالت: فطاف الذين أهلوا بالعمرة بالبيت وبين الصفا والمروة ثم حلوا، ثم طافوا طوافًا آخر بعد أن رجعوا من منى لحجهم، وأما الذين جمعوا الحج والعمرة فإنما طافوا طوافًا واحدًا."],"takhrij":"متفق عليه: رواه البخاري (١٥٥٦)، ومسلم (١٢١١/١١١).","grade":"متفق عليه","chapter_ar":"باب هل على القارن سعي واحد أو سعيان؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1556) and Muslim (1211/111).","chapter_en":"Is one saʿy sufficient for the qarin, or are two required?","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":65,"content":{"translation":{"en":["‘Aishah said: We went out with the Prophet ﷺ in the Farewell Pilgrimage and entered ihram for ‘Umrah. Then the Prophet ﷺ said: “Whoever has a sacrificial animal with him should enter ihram for Hajj along with ‘Umrah, then he should not exit ihram until he exits from both of them together.” She said: I came to Mecca while menstruating, so I did not circumambulate the House nor go between al-Safa and al-Marwah. I complained of that to the Prophet ﷺ, and he said: “Undo your hair, comb it, enter ihram for Hajj, and leave the ‘Umrah.” She said: So I did that. When we completed the Hajj, the Prophet ﷺ sent me with ‘Abd al-Rahman ibn Abi Bakr to al-Tan‘im, and I performed ‘Umrah. He then said: “This is in place of your ‘Umrah.” She said: Those who had entered ihram for ‘Umrah circumambulated the House and went between al-Safa and al-Marwah, then exited ihram. Then they performed another tawaf after returning from Mina for their Hajj. But those who combined Hajj and ‘Umrah performed only one tawaf."]},"buhuth":{"ar":["قلت: والمقصود بالطواف هنا السعي الذي كان قبل الحج كما قال البيهقي وغيره، كما في حديث جابر."],"en":["I say: What is intended by “one tawaf” here is the sa‘y that occurred before Hajj, as was explained by al-Bayhaqi and others, as in the hadith of Jabir."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1556},{"key":"muslim","label":"مسلم","number":1211}]},{"num":5057,"demo":false,"sanad":"","matn":["عن عائشة، أنها حاضت بسرف فتطهرت بعرفة، فقال لها رسولُ اللّٰه ﷺ: (( يُجزئ عنكِ طوافُكِ بالصفا والمروة عن حجكِ وعمرتكِ ))."],"takhrij":"صحيح: رواه مسلم (١٢١١/١٣٣). وفي رواية عنده: قال لها النبي ﷺ: (( إن هذا أمر كتبه الله على بنات آدم، فاغتسلي ثم أهلي بالحج )). ففعلت، ووقفت المواقف حتى إذا طهرت طافت بالكعبة والصفا والمروة، ثم قال لها: (( قد حللتِ من حجكِ وعمرتكِ جميعًا )). وفي رواية عنده: (( يسعكِ طوافكِ لحجكِ وعمرتكِ )).","grade":"صحيح","chapter_ar":"باب هل على القارن سعي واحد أو سعيان؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1211/133). In another narration with him, the Prophet ﷺ said to her: “This is something Allah has decreed upon the daughters of Adam, so bathe and then enter ihram for Hajj.” So she did that, and she stood at the standing places until, when she became pure, she circumambulated the Ka‘bah and went between al-Safa and al-Marwah. Then he said to her: “You have now exited from both your Hajj and your ‘Umrah together.” And in another narration with him: “Your tawaf is sufficient for your Hajj and your ‘Umrah.”","chapter_en":"Is one saʿy sufficient for the qarin, or are two required?","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":65,"content":{"translation":{"en":["‘Aishah menstruated at Sarif, then became pure at ‘Arafah, so the Messenger of Allah ﷺ said to her: “Your going between al-Safa and al-Marwah will suffice for both your Hajj and your ‘Umrah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1211}]},{"num":5058,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أنه قال حين خرج إلى مكة معتمرًا في الفتنة: إنْ صُدِدْتُ عَنِ الْبَيْتِ صَنَعْنَا كَمَا صَنَعْنَا مَعَ رَسُولِ الله ﷺ، فأهلَّ بعمرة من أجل أن رسولَ الله ﷺ أهلَّ بعمرة عام الحديبية، ثم إن عبد الله نظر في أمره فقال: ما أمرهما إلا واحد، ثم التفت إلى أصحابه فقال: ما أمرهما إلا واحد، أُشهدكم أنّي قد أوجبتُ الحجَّ مع العمرة، ثم نفذ حتى جاء البيت، فطاف طوافًا واحدًا، ورأى ذلك مجزئًا عنه، وأهدى."],"takhrij":"متفق عليه: رواه مالك (٩٩) والبخاري (١٨١٣)، ومسلم (١٢٣٠ : ١٨٠). وفي لفظ مسلم: (( فخرج حتى إذا جاء البيت طاف به سبعًا، وبين الصفا والمروة سبعًا لم يزد عليه، ورأى أنه مجزئ عنه… )).","grade":"متفق عليه","chapter_ar":"باب أنّ القارن والمفرد لا يتحللان بعد طوافهما الأوّل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (99), al-Bukhari (1813), and Muslim (1230:180). In the wording of Muslim: “He went on until he came to the House, then he circumambulated it seven times, and went between al-Safa and al-Marwah seven times, without adding anything to that, and he considered that sufficient for himself…”","chapter_en":"The one combining pilgrimage and lesser pilgrimage, and the one performing pilgrimage alone, do not exit ihram after their first circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":67,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said, when he set out for Mecca to perform the lesser pilgrimage during the time of turmoil: “If I am prevented from reaching the House, we will do as we did with the Messenger of Allah ﷺ.” So he entered ihram for a lesser pilgrimage because the Messenger of Allah ﷺ had entered ihram for a lesser pilgrimage in the year of al-Hudaybiyah. Then ‘Abd Allah reflected on the matter and said: “The ruling of both is only one.” Then he turned to his companions and said: “The ruling of both is only one. Bear witness that I have now made pilgrimage obligatory upon myself together with the lesser pilgrimage.” Then he continued until he came to the House and made one circumambulation, and he considered that sufficient for himself, and he offered a sacrificial animal."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":99},{"key":"bukhari","label":"البخاري","number":1813},{"key":"muslim","label":"مسلم","number":1230}]},{"num":5059,"demo":false,"sanad":"","matn":["عن نافع: أن ابن عمر أراد الحجَّ عام نزل الحجاج بابن الزبير، فقيل له: إن الناس كائن بينهم قتال، وإنا نخاف أن يصدوك، فقال: ( لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ) [الأحزاب: ٢١]، أصنع كما صنع رسول الله ﷺ، إني أشهدكم أني قد أوجبتُ عمرةً، ثم خرج حتى إذا كان بظاهر البيداء قال: ما شأن الحج والعمرة إلا واحد، اشهدوا ـ قال ابن رمح: أُشهدكم ـ أني قد أوجبتُ حجًّا مع عمرتي. وأهدى هديًا اشتراه بقديد، ثم انطلق يهلُّ بهما جميعًا حتى قدم مكة، فطاف بالبيت وبالصفا والمروة، ولم يزد على ذلك، ولم ينحر ولم يحلق ولم يقصر ولم يحلل من شيء حرم منه، حتى كان يوم النحر فنحر وحلق، ورأى أن قد قضى طواف الحج والعمرة بطوافه الأول. وقال ابن عمر: كذلك فعل رسول الله ﷺ."],"takhrij":"متفق عليه: رواه البخاري (١٦٤٠)، ومسلم (١٢٣٠ : ١٨٢) واللفظ له. وقول ابن عمر: (( كذلك فعل رسول الله ﷺ )) دليل على رفع ما فعله ابن عمر إلى النبي ﷺ بأن ليس على القارن إلا سعي واحد.","grade":"متفق عليه","chapter_ar":"باب أنّ القارن والمفرد لا يتحللان بعد طوافهما الأوّل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1640) and Muslim (1230:182), and this is Muslim’s wording. Ibn ‘Umar’s statement, “This is how the Messenger of Allah ﷺ did,” shows that what Ibn ‘Umar did is attributed back to the Prophet ﷺ, namely that the one combining both rites only has one sa‘y.","chapter_en":"The one combining pilgrimage and lesser pilgrimage, and the one performing pilgrimage alone, do not exit ihram after their first circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":67,"content":{"translation":{"en":["Nafi‘ reported that Ibn ‘Umar intended to perform pilgrimage in the year when al-Hajjaj besieged Ibn al-Zubayr. It was said to him: “There will be fighting among the people, and we fear they may prevent you.” He replied: “Indeed, you have in the Messenger of Allah ﷺ an excellent example.” He then said: “I will do as the Messenger of Allah ﷺ did. I call you to witness that I have made a lesser pilgrimage obligatory upon myself.” Then he set out, and when he reached the outer part of al-Bayda’, he said: “The matter of pilgrimage and the lesser pilgrimage is only one. Bear witness” — Ibn Rumh said: “I call you to witness” — “that I have made pilgrimage obligatory upon myself together with my lesser pilgrimage.” He offered a sacrificial animal that he had bought at Qudayd, then proceeded entering into both together until he came to Mecca. He circumambulated the House and went between al-Safa and al-Marwah, and did not add anything beyond that. He did not slaughter, shave, trim, or exit from any of the restrictions of ihram until the Day of Sacrifice, when he slaughtered and shaved. He held that he had fulfilled the circumambulation of both pilgrimage and lesser pilgrimage with his first circumambulation. And Ibn ‘Umar said: “This is how the Messenger of Allah ﷺ did.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1640},{"key":"muslim","label":"مسلم","number":1230}]},{"num":5060,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: قال رسول الله ﷺ: (( مَنْ أَحْرَمَ بِالْحَجِّ وَالْعُمْرَةِ أَجْزَأَهُ طَوَافٌ وَاحِدٌ وَسَعْيٌ وَاحِدٌ عَنْهُمَا حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا ))."],"takhrij":"حسن: رواه الترمذي (٩٤٨)، وابن ماجه (٢٩٧٥)، وأحمد (٥٣٥٠)، قال الترمذي: (( حسن صحيح غريب )).","grade":"حسن","chapter_ar":"باب أنّ القارن والمفرد لا يتحللان بعد طوافهما الأوّل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (948), Ibn Majah (2975), and Ahmad (5350). Al-Tirmidhi said: “Hasan Sahih Gharib.”","chapter_en":"The one combining pilgrimage and lesser pilgrimage, and the one performing pilgrimage alone, do not exit ihram after their first circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":67,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Whoever enters ihram for pilgrimage and the lesser pilgrimage together, one circumambulation and one sa‘y are sufficient for both until he exits from them together.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":948},{"key":"ibnmajah","label":"ابن ماجه","number":2975},{"key":"ahmad","label":"مسند الإمام أحمد","number":5350,"n":5350}]},{"num":5061,"demo":false,"sanad":"","matn":["عن جابر قال: لم يطف النبي ﷺ ولا أصحابه بين الصفا والمروة إلا طوافًا واحدًا، طوافَه الأول."],"takhrij":"صحيح: رواه مسلم (١٢٧٩)، و(١٢١٥). قوله: (( طوافه الأول )) يعني سعيه الأول الذي كان عقب طواف القدوم.","grade":"صحيح","chapter_ar":"باب أنّ القارن والمفرد لا يتحللان بعد طوافهما الأوّل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1279) and (1215). His statement, “their first going,” means their first sa‘y, which took place after the arrival circumambulation.","chapter_en":"The one combining pilgrimage and lesser pilgrimage, and the one performing pilgrimage alone, do not exit ihram after their first circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":67,"content":{"translation":{"en":["Jabir said: The Prophet ﷺ and his Companions did not go between al-Safa and al-Marwah except once, their first going."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1279},{"key":"و","label":"و","number":1215}]},{"num":5062,"demo":false,"sanad":"","matn":["عن ابن عباس: أن رسول الله ﷺ طاف طوافًا واحدًا لحجته وعمرته."],"takhrij":"حسن: رواه الدارقطني (٢٦١٩).","grade":"حسن","chapter_ar":"باب أنّ القارن والمفرد لا يتحللان بعد طوافهما الأوّل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (2619).","chapter_en":"The one combining pilgrimage and lesser pilgrimage, and the one performing pilgrimage alone, do not exit ihram after their first circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":67,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ made one circumambulation for his pilgrimage and his lesser pilgrimage."]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطني","number":2619},{"key":"sh9771","label":"سنن الدارقطني","number":2619,"n":2626}]},{"num":5063,"demo":false,"sanad":"","matn":["عن محمد بن عبد الرحمن، أن رجلًا من أهل العراق قال له: سَلْ لي عروةَ بن الزبير عن رجل يهلُّ بالحج فإذا طاف بالبيت أيحلُّ أم لا؟ فإن قال لك: لا يحل، فقل له إن رجلًا يقول ذلك. قال: فسألته، فقال: لا يحل من أهل بالحج إلا بالحج. قلت: فإن رجلًا كان يقول ذلك. قال: بئس ما قال! قال: فتصداني الرجل فسألني فحدثته، فقال: فقل له: فإن رجلًا كان يخبر أن رسول الله ﷺ قد فعل ذلك، وما شأن أسماء والزبير قد فعلا ذلك؟ قال: فجئته فذكرت له ذلك، فقال: من هذا؟ فقلت: لا أدري. قال: فما باله لا يأتيني بنفسه يسألني؟ أظنه عراقيًا؟! قلت: لا أدري. قال: فإنه قد كذب، قد حج رسول الله ﷺ فأخبرتني عائشة رضي الله عنها أن أول شيء بدأ به حين قدم مكة أنه توضأ ثم طاف بالبيت، ثم حج أبو بكر فكان أول شيء بدأ به الطواف بالبيت ثم لم يكن غيره، ثم عمر مثل ذلك، ثم حج عثمان فرأيته أول شيء بدأ به الطواف بالبيت ثم لم يكن غيره، ثم معاوية وعبد الله بن عمر، ثم حججت مع أبي الزبير بن العوام فكان أول شيء بدأ به الطواف بالبيت، ثم لم يكن غيره، ثم رأيت المهاجرين والأنصار يفعلون ذلك ثم لم يكن غيره، ثم آخر من رأيت فعل ذلك ابن عمر، ثم لم ينقضها بعمرة، وهذا ابن عمر عندهم أفلا يسألونه؟ ولا أحد ممن مضى ما كانوا يبدؤون بشيء حين يضعون أقدامهم أولَ من الطواف بالبيت، ثم لا يحلون، وقد رأيت أمي وخالتي حين تقدمان لا تبدآن بشيء أول من البيت تطوفان به ثم لا تحلان، وقد أخبرتني أمي أنها أقبلت هي وأختها والزبير وفلان وفلان بعمرة فقط، فلما مسحوا الركن حلوا، وقد كذب فيما ذكر من ذلك."],"takhrij":"متفق عليه: رواه البخاري (١٦٤١)، ومسلم (١٢٣٥)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب أنّ القارن والمفرد لا يتحللان بعد طوافهما الأوّل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1641) and Muslim (1235), and this is Muslim’s wording.","chapter_en":"The one combining pilgrimage and lesser pilgrimage, and the one performing pilgrimage alone, do not exit ihram after their first circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":67,"content":{"translation":{"en":["Muhammad ibn ‘Abd al-Rahman reported that a man from Iraq said to him: “Ask ‘Urwah ibn al-Zubayr for me about a man who enters ihram for pilgrimage, then when he circumambulates the House, does he become lawful or not? If he says to you, ‘He does not become lawful,’ then tell him that a man says otherwise.” He said: So I asked him, and he said: “The one who enters ihram for pilgrimage does not become lawful except by completing pilgrimage.” I said: “But there is a man who says that.” He replied: “What a bad thing he said!” He said: Then that man came to me and asked me, so I informed him. He said: “Then tell him that a man used to report that the Messenger of Allah ﷺ had done that, and what about Asma’ and al-Zubayr, who also did that?” He said: So I came back to him and mentioned that to him. He said: “Who is this?” I said: “I do not know.” He said: “Why does he not come to me himself and ask me? I think he is Iraqi!” I said: “I do not know.” He said: “Then he has lied. The Messenger of Allah ﷺ performed pilgrimage, and ‘Aishah, may Allah be pleased with her, informed me that the first thing he did when he came to Mecca was to perform ablution, then circumambulate the House. Then Abu Bakr performed pilgrimage, and the first thing he did was circumambulate the House, and there was nothing else after that. Then ‘Umar did the same. Then ‘Uthman performed pilgrimage, and I saw that the first thing he did was circumambulate the House, and there was nothing else after that. Then Mu‘awiyah and ‘Abd Allah ibn ‘Umar. Then I performed pilgrimage with al-Zubayr ibn al-‘Awwam, and the first thing he did was circumambulate the House, and there was nothing else after that. Then I saw the Emigrants and the Helpers doing that, and there was nothing else after that. Then the last person I saw doing that was Ibn ‘Umar, yet he did not turn it into a lesser pilgrimage. And here is Ibn ‘Umar among them — will they not ask him? And no one from those before used to begin with anything when they set foot there before circumambulating the House, and then they would not exit ihram. And I saw my mother and my aunt when they arrived: they began with nothing before the House, circumambulating it, and then they would not exit ihram. My mother also informed me that she, her sister, al-Zubayr, and so-and-so and so-and-so came for a lesser pilgrimage only, and when they had touched the corner, they exited ihram. So he has lied in what he mentioned of that.”"]},"buhuth":{"ar":["قوله: (( ثم إنهما لا تحلان )) أي سواء كان إحرامهما بالحج وحده أو بالقران خلافًا لمن قال: إن من أحرم مفردًا فطاف حلّ كما جاء عن ابن عباس. انظر: الفتح (٣/٤٩٧)."],"en":["His statement, “then they would not exit ihram,” means whether their ihram was for pilgrimage alone or for combining both rites, contrary to those who said that whoever entered ihram for pilgrimage alone and then circumambulated became lawful, as is narrated from Ibn ‘Abbas. See al-Fath (3/497)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1641},{"key":"muslim","label":"مسلم","number":1235}]},{"num":5064,"demo":false,"sanad":"","matn":["عن عطاء قال: كان ابن عباس يقول: لا يطوف بالبيت حاجٌّ ولا غير حاجٍّ إلا حلّ. قلت لعطاء: من أين يقول ذلك؟ قال: من قول الله تعالى: ( ثُمَّ مَحِلُّهَا إِلَى الْبَيْتِ الْعَتِيقِ )، قلت: فإن ذلك بعد المعرَّف. فقال: كان ابن عباس يقول: هو بعد المعرَّف وقبله، وكان يأخذ ذلك من أمر النبي ﷺ حين أمرهم أن يحلّوا في حجة الوداع."],"takhrij":"متفق عليه: رواه البخاري (٤٣٩٦)، ومسلم (١٢٤٥)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب من قال: إن الحاج المفرد يتحلل إذا طاف بالبيت للقدوم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4396) and Muslim (1245), and this is Muslim’s wording.","chapter_en":"Those who said that the pilgrim performing pilgrimage alone exits ihram after the arrival circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":68,"content":{"translation":{"en":["‘Ata’ said: Ibn ‘Abbas used to say: “No pilgrim or non-pilgrim circumambulates the House except that he becomes lawful.” I said to ‘Ata’: “From where did he say that?” He said: “From the statement of Allah Most High: ‘Then their place of sacrifice is at the Ancient House.’” I said: “But that is after standing at ‘Arafah.” He replied: Ibn ‘Abbas used to say: “It is after standing at ‘Arafah and before it.” And he took that from the command of the Prophet ﷺ when he ordered them to exit ihram during the Farewell Pilgrimage."]},"buhuth":{"ar":["قوله: (( بعد المعرَّف )) أي بعد الوقوف بعرفة."],"en":["His statement, “after standing at ‘Arafah,” means after the standing at ‘Arafah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4396},{"key":"muslim","label":"مسلم","number":1245}]},{"num":5065,"demo":false,"sanad":"","matn":["عن أبي حسان الأعرج، قال: قال رجل من بني الهُجيم لابن عباس: ما هذا الفتيا التي قد تشغَّفت ـ أو تشغَّبت ـ بالناس، أن من طاف بالبيت فقد حل؟ فقال: سنة نبيكم ﷺ وإن رغمتم."],"takhrij":"صحيح: رواه مسلم (١٢٤٤).","grade":"صحيح","chapter_ar":"باب من قال: إن الحاج المفرد يتحلل إذا طاف بالبيت للقدوم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1244).","chapter_en":"Those who said that the pilgrim performing pilgrimage alone exits ihram after the arrival circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":68,"content":{"translation":{"en":["Abu Hassan al-A‘raj said: A man from Banu al-Hujaym said to Ibn ‘Abbas: “What is this legal opinion that has taken hold of — or spread among — the people, that whoever circumambulates the House has exited ihram?” He replied: “It is the Sunnah of your Prophet ﷺ, even if you dislike it.”"]},"buhuth":{"ar":["قوله: (( قد تشغفت )) أي علقت بقلوب الناس وشغفوا بها. وقوله: (( تشغَّبت بالناس )) أي خلطت عليهم أمرهم. ورويت: (( تشعَّبت )) بالعين المهملة أي فرّقت مذاهب الناس وأوقعت الخلاف بينهم.","قال أهل العلم: هذا الذي ذكره ابن عباس هو مذهبه، وهو خلاف مذهب الجمهور من السلف والخلف، فلا أدري هل رجع عنه أم لم يرجع، فإن الحاج لا يتحلل بمجرد طواف القدوم، بل لا يتحلل حتى يقف بعرفة ويرمي ويحلق ويطوف طواف الزيارة، فحينئذ يحصل له التحللان."],"en":["His statement, “has taken hold,” means that it became attached to the hearts of the people and they became drawn to it. And his statement, “has spread among the people,” means that it confused the matter for them. It is also narrated as “has branched out,” meaning that it divided people into differing views and caused disagreement among them.","The scholars said: What Ibn ‘Abbas mentioned here was his legal view, and it is contrary to the view of the majority of the early and later scholars. I do not know whether he later retracted it or not. The pilgrim does not exit ihram merely by the arrival circumambulation; rather, he does not exit ihram until he stands at ‘Arafah, stones the pillars, shaves or trims, and performs the circumambulation of visitation. At that point, the two stages of release occur."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1244}]},{"num":5066,"demo":false,"sanad":"","matn":["عن حفصة أم المؤمنين، أنها قالت لرسول الله ﷺ: ما شأن الناس حلُّوا ولم تحلل أنت من عمرتك؟ فقال: (( إني لبدت رأسي وقلدت هديي فلا أحل حتى أنحر ))."],"takhrij":"متفق عليه: رواه مالك (١٨٠) والبخاري (١٥٦٦)، ومسلم (١٢٢٩ : ١٧٦).","grade":"متفق عليه","chapter_ar":"باب أنّ القارن الذي ساق الهدي لا يتحلل حتى ينحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (180), al-Bukhari (1566), and Muslim (1229:176).","chapter_en":"The one combining both rites who brought a sacrificial animal does not exit ihram until he slaughters","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":69,"content":{"translation":{"en":["Hafsah, the Mother of the Believers, said to the Messenger of Allah ﷺ: “Why is it that the people exited ihram while you did not exit from your lesser pilgrimage?” He said: “I have matted my hair and garlanded my sacrificial animal, so I will not exit ihram until I slaughter.”"]},"intro":{"ar":["قال الله تعالى: ( وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ ) [سورة البقرة: ١٩٦].","قال ابن كثير في تفسيره (١/٥٣٨): (( قوله: ( وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ ) معطوف على قوله: ( وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ) وليس معطوفًا على قوله: ( فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ ) كما زعمه ابن جرير ))."],"en":["Allah Most High said: “Complete the pilgrimage and the lesser pilgrimage for Allah. But if you are prevented, then offer whatever sacrificial animal is easy to obtain. And do not shave your heads until the sacrificial animal reaches its place of slaughter.” [Surat al-Baqarah: 196]","Ibn Kathir said in his commentary (1/538): “His statement, ‘And do not shave your heads until the sacrificial animal reaches its place of slaughter,’ is connected to His statement, ‘Complete the pilgrimage and the lesser pilgrimage for Allah,’ and is not connected to His statement, ‘But if you are prevented, then offer whatever sacrificial animal is easy to obtain,’ as Ibn Jarir claimed.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":180},{"key":"bukhari","label":"البخاري","number":1566},{"key":"muslim","label":"مسلم","number":1229}]},{"num":5067,"demo":false,"sanad":"","matn":["عن عبيد بن جريج أنه قال لعبد الله بن عمر: يا أبا عبد الرحمن، رأيتك تصنع أربعًا لم أر أحدًا من أصحابك يصنعها! قال: وما هن يا ابن جريج؟ قال: رأيتك لا تمس من الأركان إلا اليمانيين، ورأيتك تلبس النعال السبتية، ورأيتك تصبغ بالصفرة، ورأيتك إذا كنت بمكة أهلَّ الناس إذا رأوا الهلال ولم تُهِلَّ أنت حتى يكون يوم التروية. فقال عبد الله بن عمر: أما الأركان فإني لم أر رسول الله ﷺ يمس إلا اليمانيين، وأما النعال السبتية فإني رأيت رسول الله ﷺ يلبس النعال التي ليس فيها شعر ويتوضأ فيها فأنا أحب أن ألبسها، وأما الصفرة فإني رأيت رسول الله ﷺ يصبغ بها فأنا أحب أن أصبغ بها، وأما الإهلال فإني لم أر رسول الله ﷺ يُهِلُّ حتى تنبعث به راحلته."],"takhrij":"متفق عليه: رواه مالك (٣١) والبخاري (١٦٦)، ومسلم (١١٨٧).","grade":"متفق عليه","chapter_ar":"باب إهلال المكّي والمتمتع بالحج في يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (31), al-Bukhari (166), and Muslim (1187).","chapter_en":"The resident of Mecca and the one performing tamattu‘ enter ihram for pilgrimage on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":70,"content":{"translation":{"en":["‘Ubayd ibn Jurayj said to ‘Abd Allah ibn ‘Umar: “Abu ‘Abd al-Rahman, I have seen you do four things that I have not seen any of your companions doing.” He said: “What are they, Ibn Jurayj?” He said: “I saw that you do not touch any of the corners except the two Yemeni corners. I saw that you wear leather sandals without hair. I saw that you dye with yellow coloring. And I saw that when you were in Mecca, the people entered ihram when they saw the new moon, while you did not enter ihram until the Day of Tarwiyah.” ‘Abd Allah ibn ‘Umar said: “As for the corners, I did not see the Messenger of Allah ﷺ touch any except the two Yemeni corners. As for the leather sandals without hair, I saw the Messenger of Allah ﷺ wear sandals that had no hair on them and make ablution in them, so I like to wear them. As for the yellow coloring, I saw the Messenger of Allah ﷺ dye with it, so I like to dye with it. And as for entering ihram, I did not see the Messenger of Allah ﷺ enter ihram until his mount set out with him.”"]},"buhuth":{"ar":["قوله: (( يوم التروية )) أي يوم الثامن من ذي الحجة، وسمي التروية لأنهم كانوا يروون فيه إبلهم ويتروون من الماء؛ لأن تلك الأماكن لم تكن إذ ذاك فيها آبار ولا عيون. الفتح (٣/٥٠٧)."],"en":["His statement, “the Day of Tarwiyah,” means the eighth day of Dhu al-Hijjah. It was called the Day of Tarwiyah because they used to water their camels on that day and take enough water themselves, since those places at that time had neither wells nor springs. See al-Fath (3/507)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":31},{"key":"bukhari","label":"البخاري","number":166},{"key":"muslim","label":"مسلم","number":1187}]},{"num":5068,"demo":false,"sanad":"","matn":["عن أنس، قال: صلّى رسول الله ﷺ ونحن معه بالمدينة الظهر أربعًا، والعصر بذي الحليفة ركعتين، ثم بات بها حتى أصبح، ثم ركب حتى استوت به على البيداء، فحمد الله وسبح وكبر، ثم أهلَّ بحج وعمرة، وأهلَّ الناس بهما، فلما قدمنا أمر الناس فحلوا حتى كان يوم التروية أهلوا بالحج. قال: ونحر النبي ﷺ بدنات بيده قيامًا، وذبح رسول الله ﷺ بالمدينة كبشين أملحين."],"takhrij":"صحيح: رواه البخاري (١٥٥١)، ومسلم (٦٩٠). واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب إهلال المكّي والمتمتع بالحج في يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1551) and Muslim (690). This is the wording of al-Bukhari.","chapter_en":"The resident of Mecca and the one performing tamattu‘ enter ihram for pilgrimage on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":70,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ prayed the noon prayer with us in Madinah as four units, and the afternoon prayer at Dhu al-Hulayfah as two units. Then he stayed there overnight until morning. Then he mounted, and when his mount rose with him upon al-Bayda’, he praised Allah, glorified Him, and magnified Him, then entered ihram for pilgrimage and the lesser pilgrimage, and the people entered ihram for both with him. When we arrived, he ordered the people, and they exited ihram until the Day of Tarwiyah, when they entered ihram for pilgrimage. He said: The Prophet ﷺ slaughtered sacrificial camels with his own hand while they were standing, and the Messenger of Allah ﷺ slaughtered two white rams marked with black in Madinah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1551},{"key":"muslim","label":"مسلم","number":690}]},{"num":5069,"demo":false,"sanad":"","matn":["عن جابر، قال: … فقال لهم (يعني النبي ﷺ): (( أحلوا من إحرامكم بطواف البيت وبين الصفا والمروة وقصروا، ثم أقيموا حلالًا حتى إذا كان يوم التروية فأهلوا بالحج ))."],"takhrij":"متفق عليه: رواه البخاري (١٥٦٨)، ومسلم (١٢١٦).","grade":"متفق عليه","chapter_ar":"باب إهلال المكّي والمتمتع بالحج في يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1568) and Muslim (1216).","chapter_en":"The resident of Mecca and the one performing tamattu‘ enter ihram for pilgrimage on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":70,"content":{"translation":{"en":["Jabir said: … Then he said to them — meaning the Prophet ﷺ —: “Exit from your ihram by circumambulating the House and going between al-Safa and al-Marwah, and shorten your hair, then remain in a lawful state until, when the Day of Tarwiyah comes, enter ihram for pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1568},{"key":"muslim","label":"مسلم","number":1216}]},{"num":5070,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: … فلما كان يوم التروية توجهوا إلى منى، فأهلوا بالحج … الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨). وفي رواية له (١٢١٣): (( ثم أهللنا يوم التروية )).","grade":"صحيح","chapter_ar":"باب إهلال المكّي والمتمتع بالحج في يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218). In another narration by him (1213): “Then we entered ihram on the Day of Tarwiyah.”","chapter_en":"The resident of Mecca and the one performing tamattu‘ enter ihram for pilgrimage on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":70,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: … Then when the Day of Tarwiyah came, they headed toward Mina and entered ihram for pilgrimage … the hadith."]},"buhuth":{"ar":["وفي رواية له (١٢١٤): (( أمرنا النبي ﷺ لما أحللنا أن نُحرم إذا توجهنا إلى منى. قال: فأهللنا من الأبطح )).","وفي رواية له (١٢١٦ : ١٤٢): (( حتى إذا كان يوم التروية وجعلنا مكة بظهر أهللنا بالحج ))."],"en":["And in another narration by him (1214): “The Prophet ﷺ ordered us, after we had exited ihram, to enter ihram when we set out for Mina.” He said: “So we entered ihram from al-Abtah.”","And in another narration by him (1216:142): “Then when the Day of Tarwiyah came, and we had put Mecca behind our backs, we entered ihram for pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218},{"key":"وفی_روایہ_لہ","label":". وفي رواية له","number":1213}]},{"num":5071,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، قال: خرجنا مع رسول الله ﷺ نصرخ بالحج صراخًا، فلما قدمنا مكة أمرنا أن نجعلها عمرة إلا من ساق الهدي، فلما كان يوم التروية رحنا إلى منى فأهللنا بالحج."],"takhrij":"صحيح: رواه مسلم (١٢٤٧).","grade":"صحيح","chapter_ar":"باب إهلال المكّي والمتمتع بالحج في يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1247).","chapter_en":"The resident of Mecca and the one performing tamattu‘ enter ihram for pilgrimage on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":70,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: We set out with the Messenger of Allah ﷺ loudly proclaiming pilgrimage openly. Then when we arrived in Mecca, he ordered us to make it a lesser pilgrimage except for the one who had brought a sacrificial animal. Then when the Day of Tarwiyah came, we went on to Mina and entered ihram for pilgrimage."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1247}]},{"num":5072,"demo":false,"sanad":"","matn":["عن عبد العزيز بن رفيع، قال: سألت أنس بن مالك، قلت: أخبرني عن شيء عقلته عن رسول الله ﷺ: أين صلّى الظهر يوم التروية؟ قال: بمنى. قلت: فأين صلّى العصر يوم النفر؟ قال: بالأبطح. ثم قال: افعل ما يفعل أمراؤك."],"takhrij":"متفق عليه: رواه البخاري (١٦٥٣)، ومسلم (١٣٠٩).","grade":"متفق عليه","chapter_ar":"باب استحباب أداء الصلوات الخمس بمنى يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1653) and Muslim (1309).","chapter_en":"The recommendation of performing the five prayers in Mina on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":72,"content":{"translation":{"en":["‘Abd al-‘Aziz ibn Rafi‘ said: I asked Anas ibn Malik, and I said: Tell me about something you understood from the Messenger of Allah ﷺ. Where did he pray the noon prayer on the Day of Tarwiyah? He said: In Mina. I said: Then where did he pray the afternoon prayer on the day of departure? He said: At al-Abtah. Then he said: Do as your leaders do."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1653},{"key":"muslim","label":"مسلم","number":1309}]},{"num":5073,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: … فلما كان يوم التروية توجّهوا إلى منى فأهلّوا بالحج، وركب رسول الله ﷺ فصلّى بها الظهر والعصر والمغرب والعشاء والفجر … الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب استحباب أداء الصلوات الخمس بمنى يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The recommendation of performing the five prayers in Mina on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":72,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: … Then when the Day of Tarwiyah came, they headed to Mina and entered into pilgrimage, and the Messenger of Allah ﷺ mounted and prayed there the noon prayer, the afternoon prayer, the sunset prayer, the night prayer, and the dawn prayer … the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5074,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: صلّى رسول الله ﷺ الظهر يوم التروية، والفجر يوم عرفة بمنى."],"takhrij":"صحيح: رواه أبو داود (١٩١١) - واللفظ له -، والترمذي (٨٨٠).","grade":"صحيح","chapter_ar":"باب استحباب أداء الصلوات الخمس بمنى يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1911), and this is his wording, and al-Tirmidhi (880).","chapter_en":"The recommendation of performing the five prayers in Mina on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":72,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ prayed the noon prayer on the Day of Tarwiyah and the dawn prayer on the Day of ‘Arafah in Mina."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1911},{"key":"tirmidhi","label":"الترمذي","number":880}]},{"num":5075,"demo":false,"sanad":"","matn":["عن ابن عمر، أنه كان يحب إذا استطاع أن يصلّي الظهر بمنى من يوم التروية، وذلك أن رسول الله ﷺ صلّى الظهر بمنى."],"takhrij":"حسن: رواه الإمام أحمد (٦١٣١).","grade":"حسن","chapter_ar":"باب استحباب أداء الصلوات الخمس بمنى يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (6131).","chapter_en":"The recommendation of performing the five prayers in Mina on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":72,"content":{"translation":{"en":["Ibn ‘Umar used to like, whenever he was able, to pray the noon prayer in Mina on the Day of Tarwiyah, and that was because the Messenger of Allah ﷺ prayed the noon prayer in Mina."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":6131},{"key":"ahmad","label":"مسند الإمام أحمد","number":6131,"n":6131}]},{"num":5076,"demo":false,"sanad":"","matn":["عن عبد الله بن الزبير قال: من سنة الحج أن يصلّي الإمام الظهر والعصر والمغرب والعشاء الآخرة والصبح بمنى … الحديث."],"takhrij":"صحيح: رواه ابن خزيمة (٢٨٠٠).","grade":"صحيح","chapter_ar":"باب استحباب أداء الصلوات الخمس بمنى يوم التروية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (2800).","chapter_en":"The recommendation of performing the five prayers in Mina on the Day of Tarwiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":72,"content":{"translation":{"en":["‘Abd Allah ibn al-Zubayr said: It is from the practice of pilgrimage that the leader prays the noon prayer, the afternoon prayer, the sunset prayer, the late evening prayer, and the dawn prayer in Mina … the hadith."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2800}]},{"num":5077,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: صليت مع النبي ﷺ بمنى ركعتين، وأبي بكر وعمر، ومع عثمان صدرًا من إمارته، ثم أتمها."],"takhrij":"متفق عليه: رواه البخاري (١٠٨٢)، ومسلم (٦٩٤).","grade":"متفق عليه","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1082) and Muslim (694).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: I prayed with the Prophet ﷺ in Mina as two units, and with Abu Bakr and ‘Umar, and with ‘Uthman during the early part of his rule, then he completed them as four."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1082},{"key":"muslim","label":"مسلم","number":694}]},{"num":5078,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: صلّى النبي ﷺ بمنى صلاة المسافر، وأبو بكر وعمر وعثمان ثماني سنين أو قال ست سنين. قال حفص: وكان ابن عمر يصلّي بمنى ركعتين، ثم يأتي فراشه، فقلت: أي عم، لو صلّيت بعدها ركعتين. قال: لو فعلت لأتممت الصلاة."],"takhrij":"صحيح: رواه مسلم (٦٩٤ : ١٨).","grade":"صحيح","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (694:18).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ prayed in Mina the prayer of a traveler, and so did Abu Bakr, ‘Umar, and ‘Uthman for eight years — or he said six years. Hafs said: Ibn ‘Umar used to pray two units in Mina, then come to his resting place. So I said: Uncle, if only you prayed two units after that. He said: If I did that, I would have completed the prayer."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":694}]},{"num":5079,"demo":false,"sanad":"","matn":["عن حارثة بن وهب، قال: صليت مع رسول الله ﷺ بمنى آمنَ ما كان الناس وأكثرَه ركعتين."],"takhrij":"متفق عليه: رواه البخاري (١٠٨٣)، ومسلم (٦٩٦).","grade":"متفق عليه","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1083) and Muslim (696).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["Harithah ibn Wahb said: I prayed with the Messenger of Allah ﷺ in Mina, at a time when the people were most secure and most numerous, as two units."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1083},{"key":"muslim","label":"مسلم","number":696}]},{"num":5080,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن يزيد قال: صلّى بنا عثمان بن عفان رضي الله عنه بمنى أربع ركعات، فقيل ذلك لعبد الله بن مسعود رضي الله عنه فاسترجع، ثم قال: صليت مع رسول الله ﷺ بمنى ركعتين، وصليت مع أبي بكر الصديق رضي الله عنه بمنى ركعتين، وصليت مع عمر بن الخطاب رضي الله عنه بمنى ركعتين، فليت حظي من أربع ركعات ركعتان متقبَّلتان."],"takhrij":"متفق عليه: رواه البخاري (١٠٨٤)، ومسلم (٦٩٥).","grade":"متفق عليه","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1084) and Muslim (695).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["‘Abd al-Rahman ibn Yazid said: ‘Uthman ibn ‘Affan, may Allah be pleased with him, led us in Mina in four units. That was mentioned to ‘Abd Allah ibn Mas‘ud, may Allah be pleased with him, so he said the words of return to Allah, then said: I prayed with the Messenger of Allah ﷺ in Mina as two units, and I prayed with Abu Bakr al-Siddiq, may Allah be pleased with him, in Mina as two units, and I prayed with ‘Umar ibn al-Khattab, may Allah be pleased with him, in Mina as two units. If only my share from four units were two accepted ones."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1084},{"key":"muslim","label":"مسلم","number":695}]},{"num":5081,"demo":false,"sanad":"","matn":["عن عائشة قالت: الصلاة أول ما فرضت ركعتين، فأقرّت صلاة السفر، وأتمّت صلاة الحضر. قال الزهري: فقلت لعروة: ما بال عائشة تتم؟ قال: تأوّلت ما تأوّل عثمان."],"takhrij":"متفق عليه: رواه البخاري (١٠٩٠)، ومسلم (٦٨٥ : ٣).","grade":"متفق عليه","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1090) and Muslim (685:3).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["‘A’ishah said: Prayer was first made obligatory as two units. Then the prayer of travel remained as it was, while the prayer of residence was completed. Al-Zuhri said: I said to ‘Urwah: Then why did ‘A’ishah pray it complete? He said: She interpreted it as ‘Uthman interpreted it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1090},{"key":"muslim","label":"مسلم","number":685}]},{"num":5082,"demo":false,"sanad":"","matn":["عن عباد بن عبد الله بن الزبير، قال: لما قدم علينا معاوية حاجًّا قدمنا معه مكة، قال: فصلّى بنا الظهر ركعتين، ثم انصرف إلى دار الندوة. قال: وكان عثمان حين أتم الصلاة إذا قدم مكة صلّى بها الظهر والعصر والعشاء الآخرة أربعًا أربعًا، فإذا خرج إلى منى وعرفات قصر الصلاة، فإذا فرغ من الحج وأقام بمنى أتم الصلاة حتى يفرغ من مكة. فلما صلّى بنا الظهر ركعتين نهض إليه مروان بن الحكم وعمرو بن عثمان فقالا له: ما عاب أحدٌ ابنَ عمّك بأقبحَ ما عبتَه به! فقال لهما: وما ذاك؟ فقالا: ألم تعلم أنّه أتم الصلاة بمكة؟ فقال لهما: ويحكما، وهل كان غير ما صنعت؟ قد صلّيتهما مع رسول الله ﷺ ومع أبي بكر وعمر رضي الله عنهما. قالا: فإن ابن عمك قد كان فعل ذلك، وإن خلافك إياه له عيب. قال: فخرج معاوية إلى العصر فصلّاها بنا أربعًا."],"takhrij":"حسن: رواه الإمام أحمد (١٦٨٥٧)، والطبراني في الكبير (٣٣٣/١٩). واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (16857) and al-Tabarani in al-Kabir (19/333). This is the wording of Ahmad.","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["‘Abbad ibn ‘Abd Allah ibn al-Zubayr said: When Mu‘awiyah came to us as a pilgrim, we arrived with him in Mecca. He said: He led us in the noon prayer as two units, then went to Dar al-Nadwah. He said: When ‘Uthman would complete the prayer, whenever he came to Mecca he would pray the noon prayer, the afternoon prayer, and the late evening prayer there as four each. Then when he went out to Mina and ‘Arafat, he would shorten the prayer. Then when he finished the pilgrimage and stayed in Mina, he would complete the prayer until he departed from Mecca. So when Mu‘awiyah led us in the noon prayer as two units, Marwan ibn al-Hakam and ‘Amr ibn ‘Uthman got up and said to him: No one has found greater fault with your cousin than the way you have faulted him. He said to them: What is that? They said: Did you not know that he completed the prayer in Mecca? He said to them: Shame on you both. Was anything done other than what I have done? I prayed them this way with the Messenger of Allah ﷺ and with Abu Bakr and ‘Umar, may Allah be pleased with them. They said: But your cousin did do that, and your going against him will be counted as a criticism of him. He said: Then Mu‘awiyah went out for the afternoon prayer and led us in it as four units."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":16857},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":333},{"key":"ahmad","label":"مسند الإمام أحمد","number":16857,"n":16857}]},{"num":5083,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أنه قال: صليت مع رسول الله ﷺ بمنى، ومع أبي بكر وعمر ركعتين، ومع عثمان ركعتين صدرًا من إمارته."],"takhrij":"حسن: رواه النسائي (١٤٤٧)، والإمام أحمد (١٢٤٦٤).","grade":"حسن","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (1447) and Imam Ahmad (12464).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["Anas ibn Malik said: I prayed with the Messenger of Allah ﷺ in Mina, and with Abu Bakr and ‘Umar as two units, and with ‘Uthman as two units during the early part of his rule."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":1447},{"key":"الامام_احمد","label":"الإمام أحمد","number":12464},{"key":"ahmad","label":"مسند الإمام أحمد","number":12464,"n":12464}]},{"num":5084,"demo":false,"sanad":"","matn":["عن أبي جحيفة، قال: صليت مع النبي ﷺ بمنى الظهر ركعتين، ثم لم يزل يصلّي ركعتين حتى رجع إلى المدينة."],"takhrij":"صحيح: رواه أبو بكر بن أبي شيبة (٢/٤٤٨)، والطبراني في الكبير (٢٢/١٠٢).","grade":"صحيح","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Bakr ibn Abi Shaybah (2/448) and al-Tabarani in al-Kabir (22/102).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["Abu Juhayfah said: I prayed the noon prayer with the Prophet ﷺ in Mina as two units, and he continued praying two units until he returned to Madinah."]}},"tuhfa":{},"refs":[{"key":"ابو_بکر_بن_ابی_شیبہ","label":"أبو بكر بن أبي شيبة","number":2},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":22}]},{"num":5085,"demo":false,"sanad":"","matn":["عن عمران بن حصين عن صلاة المسافر فقال: حججت مع رسول الله ﷺ فصلّى ركعتين، وحججت مع أبي بكر فصلّى ركعتين، ومع عمر فصلّى ركعتين، ومع عثمان ست سنين من خلافته أو ثماني سنين فصلّى ركعتين، ثم إن عثمان صلّى بعد ذلك أربعًا."],"takhrij":"حسن: رواه الترمذي (٥٤٥) - واللفظ له -، وأبو داود (١٢٢٩)، والإمام أحمد (١٩٨٦٥).","grade":"حسن","chapter_ar":"باب قصر الصلاة بمنى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (545), and this is his wording, Abu Dawud (1229), and Imam Ahmad (19865).","chapter_en":"Shortening the prayer in Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":73,"content":{"translation":{"en":["‘Imran ibn Husayn, speaking about the prayer of the traveler, said: I performed pilgrimage with the Messenger of Allah ﷺ and he prayed two units, and I performed pilgrimage with Abu Bakr and he prayed two units, and with ‘Umar and he prayed two units, and with ‘Uthman for six years of his caliphate, or eight years, and he prayed two units. Then after that, ‘Uthman prayed four."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":545},{"key":"abudawud","label":"أبو داود","number":1229},{"key":"الامام_احمد","label":"الإمام أحمد","number":19865},{"key":"ahmad","label":"مسند الإمام أحمد","number":19865,"n":19865}]},{"num":5086,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: فلما كان يوم التروية توجهوا إلى منى فأهلوا بالحج، وركب رسول الله ﷺ فصلّى بها الظهر والعصر والمغرب والعشاء والفجر، ثم مكث قليلاً حتى طلعت الشمس، وأمر بقبة من شعر تضرب له بنمرة، فسار رسول الله ﷺ ولا تشك قريش إلا أنه واقف عند المشعر الحرام - كما كانت قريش تصنع في الجاهلية - فأجاز رسول الله ﷺ حتى أتى عرفة، فوجد القبة قد ضُربت له بنمرة، فنزل بها."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب استحباب الخروج من منى إلى نمرة إذا طلعت الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The recommendation of leaving Mina for Namirah after sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":74,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: Then when the Day of Tarwiyah came, they headed to Mina and entered into pilgrimage. The Messenger of Allah ﷺ mounted and prayed there the noon prayer, the afternoon prayer, the sunset prayer, the night prayer, and the dawn prayer. Then he stayed a little until the sun rose, and he ordered that a tent of hair be set up for him at Namirah. So the Messenger of Allah ﷺ proceeded, while Quraysh had no doubt that he would stop at the Sacred Monument, as Quraysh used to do in the pre-Islamic period. But the Messenger of Allah ﷺ passed on until he came to ‘Arafah and found the tent set up for him at Namirah, so he stayed there."]},"buhuth":{"ar":["قوله: (( نمرة )) هي موضع بجنب عرفات وليس من عرفات. أما قوله: (( حتى أتى عرفة، فوجد القبة قد ضُربت له بنمرة )) ففيه تجوّز، والمراد قارب عرفات. شرح مسلم."],"en":["His statement, “Namirah,” refers to a place beside ‘Arafat and not part of ‘Arafat. As for the wording, “until he came to ‘Arafah and found the tent set up for him at Namirah,” this is figurative speech, and what is meant is that he came near ‘Arafah. Sharh Muslim."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5087,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: غدا رسول الله ﷺ من منى حين صلّى الصبح صبيحة يوم عرفة حتى أتى عرفة، فنزل بنمرة وهي منزل الإمام الذي ينزل فيه بعرفة، حتى إذا كان عند صلاة الظهر راح رسول الله ﷺ مهجّرًا، فجمع بين الظهر والعصر، ثم خطب الناس، ثم راح فوقف على الموقف من عرفة."],"takhrij":"حسن: رواه أبو داود (١٩١٣)، وأحمد (٦١٣٠).","grade":"حسن","chapter_ar":"باب استحباب الخروج من منى إلى نمرة إذا طلعت الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1913) and Ahmad (6130).","chapter_en":"The recommendation of leaving Mina for Namirah after sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":74,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ set out from Mina after praying the dawn prayer on the morning of the Day of ‘Arafah, until he came to ‘Arafah. He stayed at Namirah, which is the place where the leader stays at ‘Arafah. Then when it was time for the noon prayer, the Messenger of Allah ﷺ went out early in the heat of midday, and he combined the noon and afternoon prayers, then addressed the people, then went on and stood at the standing place in ‘Arafah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1913},{"key":"ahmad","label":"مسند الإمام أحمد","number":6130,"n":6130}]},{"num":5088,"demo":false,"sanad":"","matn":["عن محمد بن أبي بكر الثقفي، أنه سأل أنس بن مالك - وهما غاديان من منى إلى عرفة -: كيف كنتم تصنعون في هذا اليوم مع رسول الله ﷺ؟ قال: كان يهلّ المهلُّ منا فلا يُنكر عليه، ويكبر المكبر منا فلا يُنكر عليه."],"takhrij":"متفق عليه: رواه مالك (٤٣)، والبخاري (١٦٥٩)، ومسلم (١٢٨٥).","grade":"متفق عليه","chapter_ar":"باب استحباب التلبية والتكبير عند الخروج من منى إلى عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (43), al-Bukhari (1659), and Muslim (1285).","chapter_en":"The recommendation of reciting the talbiyah and saying the takbir when leaving Mina for ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":75,"content":{"translation":{"en":["Muhammad ibn Abi Bakr al-Thaqafi asked Anas ibn Malik, while the two of them were going from Mina to ‘Arafah: How did you used to act on this day with the Messenger of Allah ﷺ? He said: The one among us who recited the talbiyah would do so and no one objected to him, and the one among us who said the takbir would do so and no one objected to him."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":43},{"key":"bukhari","label":"البخاري","number":1659},{"key":"muslim","label":"مسلم","number":1285}]},{"num":5089,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: غدونا مع رسول الله ﷺ من منى إلى عرفات، منا الملبّي ومنا المكبّر."],"takhrij":"صحيح: رواه مسلم (١٢٨٤).","grade":"صحيح","chapter_ar":"باب استحباب التلبية والتكبير عند الخروج من منى إلى عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1284).","chapter_en":"The recommendation of reciting the talbiyah and saying the takbir when leaving Mina for ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":75,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: We went out with the Messenger of Allah ﷺ from Mina to ‘Arafat. Some of us were reciting the talbiyah and some of us were saying the takbir."]},"buhuth":{"ar":["ورواه مسلم بلفظ: (( كنّا مع رسول الله ﷺ في غداة عرفة، فمنّا المكبّر، ومنّا المهلّل، فأما نحن فنكبّر )).","قال: قلت: والله لعجبًا منكم، كيف لم تقولوا له: ماذا رأيت رسول الله ﷺ يصنع؟!"],"en":["Muslim also narrated it with the wording: “We were with the Messenger of Allah ﷺ on the morning of ‘Arafah. Some of us were saying the takbir and some of us were reciting the talbiyah. As for us, we were saying the takbir.”","He said: I said: By Allah, it is strange about you — why did you not say to him: What did you see the Messenger of Allah ﷺ doing?"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1284}]},{"num":5090,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله أنه قال: كتب عبد الملك بن مروان إلى الحجاج بن يوسف: أن لا تخالف عبد الله بن عمر في شيء من أمر الحج. قال: فلما كان يوم عرفة، جاءه عبد الله بن عمر حين زالت الشمس وأنا معه، فصاح به عند سرادقه: أين هذا؟ فخرج عليه الحجاج وعليه ملحفة معصفرة، فقال: ما لك يا أبا عبد الرحمن؟ فقال: الرواح إن كنت تريد السنة. فقال: أهذه الساعة؟ قال: نعم. قال: فأنظرني حتى أفيض عليّ ماءً ثم أخرج. فنزل عبد الله حتى خرج الحجاج، فسار بيني وبين أبي، فقلت له: إن كنت تريد أن تصيب السنة اليوم فاقصر الخطبة وعجّل الصلاة. قال: فجعل ينظر إلى عبد الله بن عمر كيما يسمع ذلك منه، فلما رأى ذلك عبد الله قال: صدق سالم."],"takhrij":"صحيح: رواه مالك (١٩٤)، والبخاري (١٦٦٠).","grade":"صحيح","chapter_ar":"باب قصر الخطبة وتعجيل الصلاة يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (194) and al-Bukhari (1660).","chapter_en":"Shortening the sermon and hastening the prayer on the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":76,"content":{"translation":{"en":["Salim ibn ‘Abd Allah said: ‘Abd al-Malik ibn Marwan wrote to al-Hajjaj ibn Yusuf telling him not to oppose ‘Abd Allah ibn ‘Umar in anything related to pilgrimage. He said: Then when it was the Day of ‘Arafah, ‘Abd Allah ibn ‘Umar came to him after the sun had passed its zenith, and I was with him, and he called out to him at the entrance of his tent: Where is this man? Al-Hajjaj came out to him wearing a saffron-colored wrap, and said: What is it, Abu ‘Abd al-Rahman? He said: It is time to depart, if you want the Sunnah. He said: At this hour? He said: Yes. He said: Then give me time until I pour water over myself, then I will come out. So ‘Abd Allah got down and waited until al-Hajjaj came out. Then he walked between me and my father, and I said to him: If you want to attain the Sunnah today, then shorten the sermon and hasten the prayer. He began looking toward ‘Abd Allah ibn ‘Umar so that he could hear that from him. When ‘Abd Allah saw that, he said: Salim has spoken the truth."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":194},{"key":"bukhari","label":"البخاري","number":1660}]},{"num":5091,"demo":false,"sanad":"","matn":["عن جابر قال: فخطب الناس وقال - فذكر خطبته ﷺ - … ثم أذّن، ثم أقام فصلّى الظهر، ثم أقام فصلّى العصر، ولم يصلِّ بينهما شيئًا … الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب الجمع بين الصلاتين في عرفة بأذان وإقامتين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Combining the two prayers in ‘Arafah with one call to prayer and two calls to commence prayer","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":77,"content":{"translation":{"en":["Jabir said: Then he addressed the people and said — and he mentioned the Prophet’s sermon ﷺ — … then the call to prayer was made, then the call to commence prayer was made, and he prayed the noon prayer. Then the call to commence prayer was made again, and he prayed the afternoon prayer, and he did not pray anything between them … the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5092,"demo":false,"sanad":"","matn":["عن عائشة، قالت: كانت قريش ومن دان دينها يقفون بالمزدلفة، وكانوا يسمَّون الحمس، وكان سائر العرب يقفون بعرفات، فلما جاء الإسلام أمر الله نبيه ﷺ أن يأتي عرفات ثم يقف بها، ثم يفيض منها، فذلك قوله تعالى: (ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ) [البقرة: ١٩٩]."],"takhrij":"متفق عليه: رواه البخاري (٤٥٢٠)، ومسلم (١٢١٩).","grade":"متفق عليه","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4520) and Muslim (1219).","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["‘A’ishah said: Quraysh and those who followed their religion used to stand at Muzdalifah, and they were called al-Hums, while the rest of the Arabs used to stand at ‘Arafat. Then when Islam came, Allah commanded His Prophet ﷺ to go to ‘Arafat and stand there, then depart from there. That is the meaning of His statement, Most High: “Then depart from where the people depart.” [al-Baqarah: 199]"]},"intro":{"ar":["قال الله تعالى: (ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ) [سورة البقرة: ١٩٩]."],"en":["Allah Most High said: “Then depart from where the people depart, and seek forgiveness from Allah. Surely Allah is Ever-Forgiving, Most Merciful.” [Surat al-Baqarah: 199]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4520},{"key":"muslim","label":"مسلم","number":1219}]},{"num":5093,"demo":false,"sanad":"","matn":["عن عروة قال: كانت العرب تطوف بالبيت عراة إلا الحمس - والحمس: قريش وما ولدت - كانوا يطوفون عراة إلا أن تعطيهم الحمس ثيابًا، فيعطي الرجال الرجال، والنساء النساء، وكانت الحمس لا يخرجون من المزدلفة، وكان الناس كلهم يبلغون عرفات. قال هشام: فحدثني أبي عن عائشة رضي الله عنها قالت: الحمس هم الذين أنزل الله فيهم: (ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ)، قالت: كان الناس يفيضون من عرفات، وكان الحمس يفيضون من المزدلفة، يقولون: لا نفيض إلا من الحرم، فلما نزلت: (ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ) رجعوا إلى عرفات."],"takhrij":"متفق عليه: رواه البخاري (١٦٦٥)، ومسلم (١٢١٩ : ١٥٢)، واللفظ لمسلم. ولفظ البخاري قريب منه، وفيه: (( فدفعوا إلى عرفات )) أي أمروا أن يتوجهوا إلى عرفات ليقفوا بها ثم يفيضوا منها.","grade":"متفق عليه","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1665) and Muslim (1219:152), and this is the wording of Muslim. The wording of al-Bukhari is close to it, and contains: “So they went on to ‘Arafat,” meaning that they were commanded to go to ‘Arafat, stand there, and then depart from it.","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["‘Urwah said: The Arabs used to circumambulate the House naked, except for al-Hums — and al-Hums were Quraysh and their offspring. They used to circumambulate clothed only if al-Hums gave them clothes: men would give men, and women would give women. Al-Hums would not go beyond Muzdalifah, while all the other people would go as far as ‘Arafat. Hisham said: My father told me from ‘A’ishah, may Allah be pleased with her, that she said: Al-Hums are the ones concerning whom Allah revealed: “Then depart from where the people depart.” She said: The people used to depart from ‘Arafat, while al-Hums used to depart from Muzdalifah, saying: We do not depart except from the Sacred Precinct. Then when “Then depart from where the people depart” was revealed, they returned to ‘Arafat."]},"buhuth":{"ar":["والحمس: بضم الحاء، وسكون الميم بعدها سين مهملة.","وتفسيره كما روى إبراهيم الحربي في “غريب الحديث” من طريق ابن جريج، عن مجاهد، قال: (( الحمس قريش ومن كان يأخذ قريش مأخذها من القبائل كالأوس والخزرج وخزاعة وثقيف وغزوان وبني عامر بن صعصعة وبني كنانة إلا بني بكر، والأحمس في كلام العرب: الشديد، سموا بذلك لما شددوا على أنفسهم، وكانوا إذا أهلوا بحج أو عمرة لا يأكلون لحمًا ولا يضربون وبرًا ولا شعرًا، وإذا قدموا مكة وضعوا ثيابهم التي كانت عليهم )).","وروى إبراهيم أيضًا من طريق عبد العزيز بن عمران المدني قال: (( سموا حمسًا بالكعبة؛ لأنها حَمْساء، حجرها أبيض يضرب إلى السواد )). وقال أبو عبيدة معمر بن المثنى: (( تحمّس: تشدّد، ومنه حمس الوغى إذا اشتد ))."],"en":["Al-Hums is pronounced with a dammah on the letter ha’, a sukun on the letter mim, followed by sin.","Its explanation, as Ibrahim al-Harbi narrated in “Gharib al-Hadith” through Ibn Jurayj from Mujahid, is: “Al-Hums were Quraysh and those tribes that took the same path as Quraysh, such as al-Aws, al-Khazraj, Khuza‘ah, Thaqif, Ghazwan, Banu ‘Amir ibn Sa‘sa‘ah, and Banu Kinanah except Banu Bakr. In Arabic, al-ahmas means severe or strict. They were called that because they imposed strictness upon themselves. When they entered into pilgrimage or the lesser pilgrimage, they would not eat meat, nor use wool or hair coverings. When they arrived in Mecca, they would remove the clothes they had been wearing.”","Ibrahim also narrated through ‘Abd al-‘Aziz ibn ‘Imran al-Madani: “They were called Hums in relation to the Ka‘bah because it was darkish in color, its stones being white inclining toward blackness.” Abu ‘Ubaydah Ma‘mar ibn al-Muthanna said: “Tahammusa means to be strict; from it comes the phrase ‘the battle became fierce’ when it intensified.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1665},{"key":"muslim","label":"مسلم","number":1219}]},{"num":5094,"demo":false,"sanad":"","matn":["عن جبير بن مطعم، قال: أضللت بعيرًا لي، فذهبت أطلبه يوم عرفة، فرأيت رسول الله ﷺ واقفًا مع الناس بعرفة، فقلت: والله، إن هذا لمن الحمس، فما شأنه ههنا؟ وكانت قريش تعد من الحمس."],"takhrij":"متفق عليه: رواه البخاري (١٦٦٤)، ومسلم (١٢٢٠).","grade":"متفق عليه","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1664) and Muslim (1220).","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["Jubayr ibn Mut‘im said: I lost a camel of mine, so I went looking for it on the Day of ‘Arafah, and I saw the Messenger of Allah ﷺ standing with the people at ‘Arafah. So I said: By Allah, this man is certainly one of al-Hums, so what is he doing here? Quraysh were counted among al-Hums."]},"buhuth":{"ar":["والتحقيق في هذا أن قصة جبير بن مطعم مع رسول الله ﷺ وقعت في الجاهلية، وأسلم جبير بن مطعم يوم الفتح، وكان ذهابه إلى عرفة ليطلب بعيره الشارد لا ليقف بها.","ويؤكد هذا ما رواه ابن خزيمة في صحيحه كما في الحديث الآتي."],"en":["The correct understanding here is that the story of Jubayr ibn Mut‘im with the Messenger of Allah ﷺ took place before Islam. Jubayr embraced Islam on the day of the Conquest, and his going to ‘Arafah was to look for his lost camel, not to stand there for pilgrimage.","This is confirmed by what Ibn Khuzaymah narrated in his Sahih, as in the following hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1664},{"key":"muslim","label":"مسلم","number":1220}]},{"num":5095,"demo":false,"sanad":"","matn":["عن جبير بن مطعم قال: كانت قريش إنما تدفع من المزدلفة ويقولون: نحن الحمس فلا نخرج من الحرم، وقد تركوا الموقف على عرفة. قال: فرأيت رسول الله ﷺ في الجاهلية يقف مع الناس بعرفة على جمل له، ثم يصبح مع قومه بالمزدلفة، فيقف معهم ويدفع إذا دفعوا."],"takhrij":"حسن: رواه ابن خزيمة (٢٨٢٣). ورواه أيضًا (٣٠٥٧) من وجه آخر فيه: (( لقد رأيت رسول الله ﷺ قبل أن ينزل عليه، وإنه لواقف على بعير له بعرفات مع الناس، يدفع معهم منها، وما ذاك إلا توفيقًا من الله )).","grade":"حسن","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (2823). He also narrated it (3057) through another chain containing: “I certainly saw the Messenger of Allah ﷺ before revelation came to him, standing on a camel of his at ‘Arafat with the people, departing with them from there, and that was nothing but guidance granted by Allah.”","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["Jubayr ibn Mut‘im said: Quraysh used to depart only from Muzdalifah and would say: We are al-Hums, so we do not go outside the Sacred Precinct. They had abandoned the standing place at ‘Arafah. He said: Then I saw the Messenger of Allah ﷺ in the pre-Islamic period standing with the people at ‘Arafah on a camel of his. Then in the morning he would be with his people at Muzdalifah, standing with them and departing when they departed."]},"buhuth":{"ar":["قوله: (( قبل أن ينزل عليه )) أي قوله تعالى: (ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ)، فالنبي ﷺ كان يقف بعرفات قبل نزول الآية. وفيه دليل لقوله: (( وما ذاك إلا توفيقًا من الله )) أي تقريرًا من الله سبحانه وتعالى لفعل النبي ﷺ.","قال جبير بن مطعم: (( فلما أسلمت علمت أن الله وفقه لذلك )). هكذا رواه إسحاق بن راهويه: أن جبير بن مطعم قال: (( أضللت حمارًا لي في الجاهلية فوجدته بعرفة، فرأيت رسول الله ﷺ واقفًا بعرفات مع الناس، فلما أسلمت علمت أن الله وفقه لذلك )). انظر الفتح (٣/٥١٦)."],"en":["His statement, “before revelation came to him,” means before the revelation of the verse: “Then depart from where the people depart.” So the Prophet ﷺ used to stand at ‘Arafat before this verse was revealed. In it is evidence for the statement, “and that was nothing but guidance granted by Allah,” meaning that Allah, Glorified and Exalted, confirmed the Prophet ﷺ’s action.","Jubayr ibn Mut‘im said: “When I embraced Islam, I came to know that Allah had guided him to that.” This is how Ishaq ibn Rahuyah narrated it: Jubayr ibn Mut‘im said: “I lost a donkey of mine in the pre-Islamic period and found it at ‘Arafah. There I saw the Messenger of Allah ﷺ standing at ‘Arafat with the people. When I embraced Islam, I came to know that Allah had guided him to that.” See al-Fath (3/516)."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2823},{"key":"ورواہ_ایضا","label":". ورواه أيضًا","number":3057}]},{"num":5096,"demo":false,"sanad":"","matn":["عن ابن عباس قال: يطوف الرجل بالبيت ما كان حلالًا حتى يهل بالحج، فإذا ركب إلى عرفة فمن تيسّر له هدية من الإبل أو البقر أو الغنم، ما تيسّر له من ذلك، أيَّ ذلك شاء، غير أنه إن لم يتيسر له فعليه ثلاثة أيام في الحج، وذلك قبل يوم عرفة، فإن كان آخر يوم من الأيام الثلاثة يوم عرفة فلا جناح عليه، ثم لينطلق حتى يقف بعرفات من صلاة العصر إلى أن يكون الظلام، ثم ليدفعوا من عرفات إذا أفاضوا منها حتى يبلغوا جمعًا الذي يبيتون به، ثم ليذكروا الله كثيرًا، وأكثروا التكبير والتهليل قبل أن تصبحوا، ثم أفيضوا فإن الناس كانوا يفيضون، وقال الله تعالى: (ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ) [البقرة: ١٩٩] حتى ترموا الجمرة."],"takhrij":"صحيح: رواه البخاري (٤٥٢١).","grade":"صحيح","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4521).","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["Ibn ‘Abbas said: A man may circumambulate the House while still lawful until he enters into pilgrimage. Then when he rides toward ‘Arafah, if he can obtain an offering from camels, cattle, or sheep, then whatever is easy for him of that — whichever he chooses. But if he cannot obtain one, then he must fast three days during the pilgrimage, and that must be before the Day of ‘Arafah. If the last of those three days is the Day of ‘Arafah, then there is no harm in that. Then let him proceed until he stands at ‘Arafat from the afternoon prayer until it becomes dark. Then let them depart from ‘Arafat when they depart from it, until they reach Muzdalifah where they spend the night. Then let them remember Allah much, and increase in saying the takbir and the declaration of His oneness before morning. Then depart, for the people used to depart, and Allah Most High said: “Then depart from where the people depart, and seek forgiveness from Allah. Surely Allah is Ever-Forgiving, Most Merciful.” [al-Baqarah: 199] — until you stone the pillar."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4521}]},{"num":5097,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن يعمر الديلي، قال: أتيت النبي ﷺ وهو بعرفة، فجاء ناس أو نفر من أهل نجد، فأمروا رجلًا فنادى رسولَ الله ﷺ: كيف الحج؟ فأمر رسول الله ﷺ رجلًا، فنادى: (( الحج يوم عرفة، من جاء قبل صلاة الصبح من ليلة جمع فتم حجه، أيام منى ثلاثة: (فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ) )). قال: ثم أردف رجلًا خلفه فجعل ينادي بذلك."],"takhrij":"صحيح: رواه أبو داود (١٩٤٩)، والترمذي (٨٨٩)، والنسائي (٣٠٤٧، ٣٠١٠)، وابن ماجه (٣٠١٥)، واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1949), al-Tirmidhi (889), al-Nasa’i (3047, 3010), and Ibn Majah (3015), and this is the wording of Abu Dawud.","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["‘Abd al-Rahman ibn Ya‘mar al-Dayli said: I came to the Prophet ﷺ while he was at ‘Arafah. Then some people, or a group from Najd, came and told a man to call out to the Messenger of Allah ﷺ: How is pilgrimage performed? So the Messenger of Allah ﷺ ordered a man, and he called out: “Pilgrimage is the Day of ‘Arafah. Whoever arrives before the dawn prayer on the night of Muzdalifah, his pilgrimage is complete. The days of Mina are three: ‘Whoever hastens in two days, there is no sin upon him, and whoever delays, there is no sin upon him.’” He said: Then he seated a man behind him, and he continued calling this out."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1949},{"key":"tirmidhi","label":"الترمذي","number":889},{"key":"nasai","label":"النسائي","number":3047},{"key":"ibnmajah","label":"ابن ماجه","number":3015}]},{"num":5098,"demo":false,"sanad":"","matn":["عن عروة بن مُضَرِّس الطائي قال: أتيت رسولَ اللّٰه ﷺ بالموقف - يعني بجمع - فقلت: جئت يا رسولَ اللّٰه من جبل طيّء، أكللتُ مطيّتي وأتعبتُ نفسي، واللّٰه ما تركتُ من حبلٍ إلا وقفتُ عليه، فهل لي من حجّ؟ فقال رسولُ اللّٰه ﷺ: (( من أدرك معنا هذه الصلاة، وأتى عرفات قبل ذلك ليلاً أو نهاراً، فقد تمّ حجُّه وقضى تفثه ))."],"takhrij":"صحيح: رواه أبو داود (١٩٥٠)، والترمذيّ (٨٩١)، والنسائيّ (٣٠٣٩)، وابن ماجه (٣٠١٦).","grade":"صحيح","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1950), al-Tirmidhi (891), al-Nasa’i (3039), and Ibn Majah (3016).","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["‘Urwah ibn Mudarris al-Ta’i said: I came to the Messenger of Allah ﷺ at the standing place — meaning at Muzdalifah — and said: I have come, O Messenger of Allah ﷺ, from Mount Tayy’, I have exhausted my riding animal and worn myself out. By Allah, I did not leave any hill but that I stood upon it. So do I have a pilgrimage? The Messenger of Allah ﷺ said: “Whoever joins us in this prayer, and had come to ‘Arafat before that, by night or by day, then his pilgrimage is complete and he has completed his rites of cleansing.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1950},{"key":"tirmidhi","label":"الترمذيّ","number":891},{"key":"nasai","label":"النسائيّ","number":3039},{"key":"ibnmajah","label":"ابن ماجه","number":3016}]},{"num":5099,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسولُ اللّٰه ﷺ: (( من أدرك عرفات فوقف بها والمزدلفة فقد تمّ حجُّه، ومن فاتته عرفات فقد فاته الحج، فليحلَّ بعمرةٍ وعليه الحجّ من قابل ))."],"takhrij":"حسن: رواه الدارقطنيّ (٢٥١٩)، والبيهقيّ (١٧٤/٥).","grade":"حسن","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (2519) and al-Bayhaqi (5/174).","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said: “Whoever reaches ‘Arafat and stands there, and reaches Muzdalifah, then his pilgrimage is complete. And whoever misses ‘Arafat has missed the pilgrimage, so let him exit the state of consecration with an ‘umrah, and he must perform pilgrimage the following year.”"]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطنيّ","number":2519},{"key":"البیہقی","label":"البيهقيّ","number":174}]},{"num":5100,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس قال: قال رسولُ اللّٰه ﷺ: (( من أدرك عرفة قبل أن يطلع الفجر فقد أدرك الحجّ ))."],"takhrij":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (١٧٥٩)، وعنه أبو نعيم في الحلية (١١٦/٥).","grade":"حسن","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat — Majma‘ al-Bahrayn (1759), and Abu Nu‘aym narrated it from him in al-Hilyah (5/116).","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas said: The Messenger of Allah ﷺ said: “Whoever reaches ‘Arafah before dawn rises has reached the pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":1759},{"key":"عنہ_ابو_نعیم/الحلیہ","label":"عنه أبو نعيم في الحلية","number":116}]},{"num":5101,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال النبي ﷺ: (( الحجُّ عرفةُ ))."],"takhrij":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (١٧٥٧).","grade":"حسن","chapter_ar":"باب وجوب الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat — Majma‘ al-Bahrayn (1757).","chapter_en":"The obligation of standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":78,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ said: “The pilgrimage is ‘Arafah.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":1757}]},{"num":5102,"demo":false,"sanad":"","matn":["عن جابر أنّ رسولَ اللّٰه ﷺ قال: (( نحرتُ ههنا، ومنى كلُّها منحر، فانحروا في رحالكم، ووقفتُ ههنا، وعرفةُ كلُّها موقف، ووقفتُ ههنا، وجمعٌ كلُّها موقف ))."],"takhrij":"صحيح: رواه مسلم (١٢١٨ : ١٤٩).","grade":"صحيح","chapter_ar":"باب ما جاء في أنّ عرفة كلّها موقف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218:149).","chapter_en":"What has been narrated that all of ‘Arafah is a place of standing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":79,"content":{"translation":{"en":["Jabir reported that the Messenger of Allah ﷺ said: “I sacrificed here, and all of Mina is a place of sacrifice, so sacrifice in your camps. And I stood here, and all of ‘Arafah is a place of standing. And I stood here, and all of Muzdalifah is a place of standing.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5103,"demo":false,"sanad":"","matn":["عن عليّ بن أبي طالب، قال: وقف رسولُ اللّٰه ﷺ بعرفة فقال: (( هذه عرفة، وهذا هو الموقف، وعرفة كلُّها موقف )). ثم أفاض حين غربت الشمس، وأردف أسامة بن زيد، وجعل يشير بيده على هينته، والناس يضربون يميناً وشمالاً، يلتفت إليهم ويقول: (( أيها الناس! عليكم السكينة )). ثم أتى جمعاً فصلّى بهم الصلاتين جميعاً، فلما أصبح أتى قُزَح فوقف عليه، وقال: (( هذا قزح، وهو الموقف، وجمعٌ كلُّها موقف )). ثم أفاض حتى انتهى إلى وادي مُحَسِّر فقرع ناقته فخبّت حتى جاوز الوادي، فوقف وأردف الفضل، ثم أتى الجمرة فرماها، ثم أتى المنحر، فقال: (( هذا المنحر، ومنى كلُّها منحر )). واستفتته جارية شابّة من خثعم فقالت: إنّ أبي شيخٌ كبير قد أدركته فريضةُ اللّٰه في الحج، أفيجزئ أن أحجّ عنه؟ قال: (( حُجِّي عن أبيك )). قال: ولوى عنق الفضل، فقال العباس: يا رسول اللّٰه، لم لويتَ عنقَ ابن عمّك؟ قال: (( رأيتُ شابًّا وشابّةً فلم آمن الشيطان عليهما )). ثم أتاه رجل فقال: يا رسولَ اللّٰه، إنّي أفضت قبل أن أحلق؟ قال: (( احلق أو قصّر ولا حرج )). قال: وجاء آخر فقال: يا رسولَ اللّٰه، إنّي ذبحت قبل أن أرمي؟ قال: (( ارمِ ولا حرج )). قال: ثم أتى البيت فطاف به، ثم أتى زمزم فقال: (( يا بني عبد المطلب، لولا أن يغلبكم الناس عنه لنزعتُ ))."],"takhrij":"حسن: رواه الترمذيّ (٨٨٥)، وأبو داود (١٩٣٥، ١٩٢٢)، قال الترمذي: (( حسن صحيح )).","grade":"حسن","chapter_ar":"باب ما جاء في أنّ عرفة كلّها موقف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (885) and Abu Dawud (1935, 1922). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What has been narrated that all of ‘Arafah is a place of standing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":79,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ stood at ‘Arafah and said: “This is ‘Arafah, and this is the standing place, and all of ‘Arafah is a standing place.” Then he departed when the sun had set, and he had Usamah ibn Zayd ride behind him. He kept gesturing with his hand calmly while the people were rushing right and left, turning to them and saying: “O people, remain calm.” Then he came to Muzdalifah and led them in the two prayers together. When morning came, he went to Quzah and stood upon it, and said: “This is Quzah, and it is the standing place, and all of Muzdalifah is a standing place.” Then he departed until he reached the valley of Muhassir, and he urged his she-camel on so that it hastened until it crossed the valley. Then he stopped and had al-Fadl ride behind him. Then he came to the pillar and stoned it, then he came to the place of sacrifice and said: “This is the place of sacrifice, and all of Mina is a place of sacrifice.” A young woman from Khath‘am asked him for a ruling and said: My father is an old man upon whom the obligation of pilgrimage has come — will it suffice if I perform pilgrimage on his behalf? He said: “Perform pilgrimage on behalf of your father.” He said: Then he turned al-Fadl’s neck away, so al-‘Abbas said: O Messenger of Allah ﷺ, why did you turn your cousin’s neck away? He said: “I saw a young man and a young woman, and I did not feel safe from Satan concerning them.” Then a man came to him and said: O Messenger of Allah ﷺ, I departed before shaving. He said: “Shave or shorten, and there is no harm.” Another came and said: O Messenger of Allah ﷺ, I sacrificed before stoning. He said: “Stone, and there is no harm.” Then he came to the House and circumambulated it, then he came to Zamzam and said: “O sons of ‘Abd al-Muttalib, were it not that the people might overpower you and drive you away from it, I would have drawn water.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":885},{"key":"abudawud","label":"أبو داود","number":1935}]},{"num":5104,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسولُ اللّٰه ﷺ: (( عرفةُ كلُّها موقف، وارفعوا عن بطن عُرَنَة، والمزدلفةُ كلُّها موقف، وارفعوا عن بطن مُحَسِّر، وشعابُ منى كلُّها منحر ))."],"takhrij":"حسن: رواه الطحاوي في شرح مشكل الآثار (١١٩٤).","grade":"حسن","chapter_ar":"باب ما جاء في أنّ عرفة كلّها موقف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Sharh Mushkil al-Athar (1194).","chapter_en":"What has been narrated that all of ‘Arafah is a place of standing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":79,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said: “All of ‘Arafah is a standing place, but keep away from the bottom of ‘Uranah. All of Muzdalifah is a standing place, but keep away from the bottom of Muhassir. And all the mountain passes of Mina are places of sacrifice.”"]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرح_مشکل_الاثار","label":"الطحاوي في شرح مشكل الآثار","number":1194}]},{"num":5105,"demo":false,"sanad":"","matn":["عن يزيد بن شيبان، قال: كنّا وقوفاً بعرفة مكاناً بعيداً من الموقف، فأتانا ابنُ مِرْبَع الأنصاري، فقال: إنّي رسولُ رسولِ اللّٰه ﷺ إليكم، يقول: (( كونوا على مشاعركم، فإنكم على إرثٍ من إرث أبيكم إبراهيم عليه السلام ))."],"takhrij":"صحيح: رواه أبو داود (١٩١٩)، والترمذيّ (٨٨٣)، والنسائيّ (٣٠١٤)، وابن ماجه (٣٠١١).","grade":"صحيح","chapter_ar":"باب تنبيه الحجاج على عدم الوقوف خارج حدود عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1919), al-Tirmidhi (883), al-Nasa’i (3014), and Ibn Majah (3011).","chapter_en":"Warning the pilgrims against standing outside the boundaries of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":80,"content":{"translation":{"en":["Yazid ibn Shayban said: We were standing in ‘Arafah at a place far from the standing place, then Ibn Mirba‘ al-Ansari came to us and said: I am the messenger of the Messenger of Allah ﷺ to you. He says: “Remain at your sacred sites, for you are upon an inheritance from the inheritance of your father Ibrahim, peace be upon him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1919},{"key":"tirmidhi","label":"الترمذيّ","number":883},{"key":"nasai","label":"النسائيّ","number":3014},{"key":"ibnmajah","label":"ابن ماجه","number":3011}]},{"num":5106,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسولُ اللّٰه ﷺ: (( ارفعوا عن بطن عُرَنَة، ارفعوا عن بطن مُحَسِّر ))."],"takhrij":"حسن: رواه ابن خزيمة (٢٨١٦)، والحاكم (٤٦٢/١)، وعنه البيهقيّ (١١٥/٥).","grade":"حسن","chapter_ar":"باب تنبيه الحجاج على عدم الوقوف خارج حدود عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (2816), al-Hakim (1/462), and from him al-Bayhaqi (5/115).","chapter_en":"Warning the pilgrims against standing outside the boundaries of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":80,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said: “Keep away from the bottom of ‘Uranah. Keep away from the bottom of Muhassir.”"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2816},{"key":"hakim","label":"الحاكم","number":462},{"key":"عنہ_البیہقی","label":"عنه البيهقيّ","number":115}]},{"num":5107,"demo":false,"sanad":"","matn":["عن عائشة أن رسولَ اللّٰه ﷺ قال: (( ما من يومٍ أكثرَ من أن يُعتقَ اللّٰه فيه عبداً من النار من يوم عرفة، وإنّه ليدنو ثم يباهي بهم الملائكة فيقول: ما أراد هؤلاء؟ ))."],"takhrij":"صحيح: رواه مسلم (١٣٤٨).","grade":"صحيح","chapter_ar":"باب فضل يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1348).","chapter_en":"The virtue of the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":81,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ said: “There is no day on which Allah frees more servants from the Fire than the Day of ‘Arafah. He draws near, then boasts of them before the angels and says: What do these people want?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1348}]},{"num":5108,"demo":false,"sanad":"","matn":["عن طارق بن شهاب: أنّ أناساً من اليهود قالوا: لو نزلت هذه الآية فينا لاتخذنا ذلك اليوم عيداً. فقال عمر: أيّة آية؟ فقالوا: ( الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلَامَ دِينًا ) [المائدة: ٣]. فقال عمر: إنّي لأعلم أيّ مكان أُنزلت: أُنزلت ورسولُ اللّٰه ﷺ واقفٌ بعرفة."],"takhrij":"متفق عليه: رواه البخاريّ (٤٤٠٧)، ومسلم (٣٠١٧).","grade":"متفق عليه","chapter_ar":"باب فضل يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4407) and Muslim (3017).","chapter_en":"The virtue of the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":81,"content":{"translation":{"en":["Tariq ibn Shihab said: Some Jews said: If this verse had been revealed to us, we would have taken that day as a festival. ‘Umar said: Which verse? They said: “Today I have perfected for you your religion, completed My favor upon you, and approved Islam for you as your religion.” [Surat al-Ma’idah: 3] So ‘Umar said: I certainly know the place where it was revealed. It was revealed while the Messenger of Allah ﷺ was standing at ‘Arafah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4407},{"key":"muslim","label":"مسلم","number":3017}]},{"num":5109,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسولُ اللّٰه ﷺ: (( ما من أيامٍ أفضل عند اللّٰه من أيام عشر ذي الحجّة )). قال: فقال رجل: يا رسولَ اللّٰه، هنّ أفضل أم عدّتهنّ جهاداً في سبيل اللّٰه؟ قال: (( هنّ أفضل من عدّتهنّ جهاداً في سبيل اللّٰه. وما من يومٍ أفضل عند اللّٰه من يوم عرفة؛ ينزل اللّٰه إلى السماء الدنيا فيباهي بأهل الأرض أهل السماء فيقول: انظروا إلى عبادي شعثاً غبراً ضاحين، جاؤوا من كل فجٍّ عميق، يرجون رحمتي ولم يروا عذابي، فلم يُرَ يومٌ أكثر عتقاً من النار من يوم عرفة ))."],"takhrij":"حسن: رواه ابن حبان (٣٨٥٣)، وأبو يعلى (٢٠٩٠)، والبزّار - كشف الأستار (١١٢٨).","grade":"حسن","chapter_ar":"باب فضل يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (3853), Abu Ya‘la (2090), and al-Bazzar in Kashf al-Astar (1128).","chapter_en":"The virtue of the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":81,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “There are no days more virtuous before Allah than the first ten days of Dhu al-Hijjah.” A man said: O Messenger of Allah ﷺ, are they better, or an equal number of days of striving in the path of Allah? He said: “They are better than an equal number of days of striving in the path of Allah. And there is no day more virtuous before Allah than the Day of ‘Arafah. Allah descends to the lowest heaven and boasts of the people of the earth before the people of heaven, saying: Look at My servants, disheveled, dusty, and exposed to the sun. They have come from every distant mountain path, hoping for My mercy though they have not seen My punishment. So there is no day on which more people are freed from the Fire than the Day of ‘Arafah.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":2090},{"key":"البزار_کشف_الاستار","label":"البزّار - كشف الأستار","number":1128},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":302,"n":302},{"key":"sh12520","label":"مسند أبي يعلى","number":2090,"n":2092}]},{"num":5110,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسولُ اللّٰه ﷺ: (( إنّ اللّٰه عزّ وجلّ يباهي الملائكةَ بأهل عرفات، يقول: انظروا إلى عبادي شعثاً غبراً ))."],"takhrij":"حسن: رواه الإمام أحمد (٨٠٤٧)، وصحّحه ابن خزيمة (٢٨٣٩)، وابن حبان (٣٨٥٢)، والحاكم (٤٦٥/١).","grade":"حسن","chapter_ar":"باب فضل يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (8047). It was authenticated by Ibn Khuzaymah (2839), Ibn Hibban (3852), and al-Hakim (1/465).","chapter_en":"The virtue of the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":81,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, boasts to the angels about the people of ‘Arafat, saying: Look at My servants, disheveled and dusty.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":8047},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2839},{"key":"ibnhibban","label":"ابن حبان","number":3852},{"key":"hakim","label":"الحاكم","number":465},{"key":"ahmad","label":"مسند الإمام أحمد","number":8047,"n":8047}]},{"num":5111,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو بن العاص، أنّ النبيّ ﷺ كان يقول: (( إنّ اللّٰه عزّ وجلّ يباهي ملائكته عشيةَ عرفة بأهل عرفة، فيقول: انظروا إلى عبادي، أتوني شعثاً غبراً ))."],"takhrij":"حسن: رواه أحمد (٧٠٨٩).","grade":"حسن","chapter_ar":"باب فضل يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (7089).","chapter_en":"The virtue of the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":81,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As reported that the Prophet ﷺ used to say: “Allah, Mighty and Majestic, boasts to His angels on the evening of ‘Arafah about the people of ‘Arafah, saying: Look at My servants; they have come to Me disheveled and dusty.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":7089,"n":7089}]},{"num":5112,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: ثم أقبل رسولُ اللّٰه ﷺ على الأنصاري فقال: (( إن شئتَ أخبرتُك عمّا جئت تسأل، وإن شئتَ سألتني فأخبرتُك )). فقال: لا يا نبيَّ اللّٰه، أخبرني عمّا جئتُ أسألك. قال: (( جئتَ تسألني عن الحاجّ ما له حين يخرجُ من بيته، وما له حين يقوم بعرفات، وما له حين يرمي الجمار، وما له حين يحلق رأسه، وما له حين يقضي آخر طوافٍ بالبيت )). فقال: يا نبيَّ اللّٰه، والذي بعثك بالحق ما أخطأتَ مما كان في نفسي شيئاً! قال: (( فإنّ له حين يخرج من بيته أنّ راحلته لا تخطو خطوةً إلا كتب الله له بها حسنةً أو حطّ عنه بها خطيئةً، فإذا وقف بعرفة فإنّ اللّٰه عزّ وجلّ ينزل إلى السماء الدنيا فيقول: انظروا إلى عبادي شعثاً غبراً، اشهدوا أنّي قد غفرتُ لهم ذنوبهم وإن كانت عدد قطر السماء ورمل عالج. وإذا رمى الجمار لا يدري أحدٌ ما له حتى يوفّاه يوم القيامة. وإذا حلق رأسه فله بكل شعرةٍ سقطت من رأسه نورٌ يوم القيامة. وإذا قضى آخر طوافه بالبيت خرج من ذنوبه كيوم ولدته أمه… ))."],"takhrij":"حسن: رواه ابن حبان (١٨٨٧)، والبيهقي في دلائل النبوة (٦/٢٩٤)، والبزار - كشف الأستار (١٠٨٢).","grade":"حسن","chapter_ar":"باب فضل يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (1887), al-Bayhaqi in Dala’il al-Nubuwwah (6/294), and al-Bazzar in Kashf al-Astar (1082).","chapter_en":"The virtue of the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":81,"content":{"translation":{"en":["Ibn ‘Umar said: Then the Messenger of Allah ﷺ turned to an Ansari man and said: “If you wish, I can tell you what you came to ask about, and if you wish, ask me and I will tell you.” He said: No, O Prophet of Allah ﷺ, tell me about what I came to ask you. He said: “You came to ask me about the pilgrim: what he receives when he leaves his house, what he receives when he stands at ‘Arafat, what he receives when he stones the pillars, what he receives when he shaves his head, and what he receives when he completes his final circumambulation of the House.” He said: O Prophet of Allah ﷺ, by the One who sent you with the truth, you did not miss anything that was in my mind. He said: “When he leaves his house, his mount does not take a single step except that Allah writes for him by it a good deed or removes from him by it a sin. When he stands at ‘Arafat, Allah, Mighty and Majestic, descends to the lowest heaven and says: Look at My servants, disheveled and dusty. Bear witness that I have forgiven them their sins, even if they were as many as the raindrops of the sky and the sands of ‘Alij. When he stones the pillars, no one knows what reward he has until it is fully given to him on the Day of Resurrection. When he shaves his head, for every hair that falls from his head he will have a light on the Day of Resurrection. And when he completes his final circumambulation of the House, he comes out of his sins as on the day his mother gave birth to him…”"]}},"tuhfa":{},"refs":[{"key":"البیہقی/دلایل_النبوہ","label":"البيهقي في دلائل النبوة","number":6},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1082},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4098,"n":4094}]},{"num":5113,"demo":false,"sanad":"","matn":["عن أبي أيوب، أن رسولَ اللّٰه ﷺ قال: (( من قال: لا إله إلا اللّٰه وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، عشر مرات، كان كمن أعتق أربعة أنفس من ولد إسماعيل ))."],"takhrij":"متفق عليه: رواه البخاريّ (٦٤٠٤)، ومسلم (٢٦٩٣).","grade":"متفق عليه","chapter_ar":"باب الترغيب في قول: لا إله إلا الله وحده لا شريك له","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6404) and Muslim (2693).","chapter_en":"Encouragement to say: None has the right to be worshipped except Allah alone, with no partner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":82,"content":{"translation":{"en":["Abu Ayyub reported that the Messenger of Allah ﷺ said: “Whoever says: None has the right to be worshipped except Allah alone, with no partner, to Him belongs the dominion and to Him belongs all praise, and He is over all things capable, ten times, it is as if he freed four persons from the descendants of Isma‘il.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":6404},{"key":"muslim","label":"مسلم","number":2693}]},{"num":5114,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: قال رسولُ اللّٰه ﷺ: (( أفضلُ ما قلتُ أنا والنبيون قبلي عشية عرفة: لا إله إلا اللّٰه وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير ))."],"takhrij":"حسن: رواه الطبراني في الدعاء (٨٧٤).","grade":"حسن","chapter_ar":"باب الترغيب في قول: لا إله إلا الله وحده لا شريك له","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Du‘a’ (874).","chapter_en":"Encouragement to say: None has the right to be worshipped except Allah alone, with no partner","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":82,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ said: “The best of what I and the prophets before me said on the evening of ‘Arafah is: None has the right to be worshipped except Allah alone, with no partner, to Him belongs the dominion and to Him belongs all praise, and He is over all things capable.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الدعا","label":"الطبراني في الدعاء","number":874},{"key":"sh13016","label":"الدعاء للطبراني","number":874,"n":858}]},{"num":5115,"demo":false,"sanad":"","matn":["عن أم الفضل بنت الحارث: أنّ ناساً تمارَوا عندها يوم عرفة في صيام رسول اللّٰه ﷺ، فقال بعضهم: هو صائم، وقال بعضهم: ليس بصائم، فأرسلتُ إليه بقدح لبنٍ وهو واقف على بعيره، فشرب."],"takhrij":"متفق عليه: رواه مالك (١٣٢)، والبخاريّ (١٦٦١)، ومسلم (١١٠ : ١١٢٣).","grade":"متفق عليه","chapter_ar":"باب استحباب الفطر للحاج يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (132), al-Bukhari (1661), and Muslim (1123:110).","chapter_en":"The recommendation that the pilgrim not fast on the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":83,"content":{"translation":{"en":["Umm al-Fadl bint al-Harith reported that some people disputed in her presence on the Day of ‘Arafah about whether the Messenger of Allah ﷺ was fasting. Some said: He is fasting. Others said: He is not fasting. So she sent to him a cup of milk while he was standing on his riding animal, and he drank it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":132},{"key":"bukhari","label":"البخاريّ","number":1661},{"key":"muslim","label":"مسلم","number":110}]},{"num":5116,"demo":false,"sanad":"","matn":["عن ميمونة زوج النبيّ ﷺ أنها قالت: إنّ الناس شكّوا في صيام رسول اللّٰه ﷺ يوم عرفة، فأرسلتُ إليه بحِلابٍ وهو واقف في الموقف، فشرب منه والناس ينظرون."],"takhrij":"متفق عليه: رواه البخاريّ (١٩٨٩)، ومسلم (١١٢٤).","grade":"متفق عليه","chapter_ar":"باب استحباب الفطر للحاج يوم عرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1989) and Muslim (1124).","chapter_en":"The recommendation that the pilgrim not fast on the Day of ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":83,"content":{"translation":{"en":["Maymunah, the wife of the Prophet ﷺ, said: The people doubted whether the Messenger of Allah ﷺ was fasting on the Day of ‘Arafah, so I sent him a vessel of milk while he was standing at the place of standing, and he drank from it while the people were watching."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1989},{"key":"muslim","label":"مسلم","number":1124}]},{"num":5117,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: ثم ركب رسولُ اللّٰه ﷺ حتى أتى الموقف، فجعل بطن ناقته القصواء إلى الصخرات، وجعل حبل المشاة بين يديه، واستقبل القبلة… الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب استحباب الدعاء في عرفة واستقبال القبلة بذلك","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The recommendation of supplication at ‘Arafah and facing the qiblah for it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":84,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: Then the Messenger of Allah ﷺ rode until he came to the standing place, and he placed the belly of his she-camel al-Qaswa’ toward the rocks, and placed the path of the walkers before him, and faced the qiblah… the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5118,"demo":false,"sanad":"","matn":["عن أسامة بن زيد قال: كنتُ رديف النبيّ ﷺ بعرفات، فرفع يديه يدعو، فمالت به ناقته فسقط خطامها، فتناول الخطام بإحدى يديه وهو رافع يده الأخرى."],"takhrij":"حسن: رواه النسائيّ (٣٠١١)، وأحمد (٢١٨٢١)، وصحّحه ابن خزيمة (٢٨٢٤).","grade":"حسن","chapter_ar":"باب رفع اليدين في الدعاء عند الوقوف بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3011) and Ahmad (21821), and authenticated by Ibn Khuzaymah (2824).","chapter_en":"Raising the hands in supplication while standing at ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":85,"content":{"translation":{"en":["Usamah ibn Zayd said: I was riding behind the Prophet ﷺ at ‘Arafat, and he raised his hands in supplication. Then his she-camel leaned and its rein fell, so he took hold of the rein with one hand while the other hand remained raised."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":3011},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2824},{"key":"ahmad","label":"مسند الإمام أحمد","number":21821,"n":21821}]},{"num":5119,"demo":false,"sanad":"","matn":["عن أم الفضل بنت الحارث: أنّ ناساً تمارَوا عندها يوم عرفة في صيام رسول اللّٰه ﷺ، فقال بعضهم: هو صائم، وقال بعضهم: ليس بصائم، فأرسلتُ إليه بقدح لبنٍ وهو واقف على بعيره، فشرب."],"takhrij":"متفق عليه: رواه مالك (١٣٢)، والبخاريّ (١٦٦١)، ومسلم (١١٠ : ١١٢٣).","grade":"متفق عليه","chapter_ar":"باب جواز الوقوف على الدابة ونحوها بعرفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (132), al-Bukhari (1661), and Muslim (1123:110).","chapter_en":"The permissibility of standing at ‘Arafah on a riding animal and the like","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":86,"content":{"translation":{"en":["Umm al-Fadl bint al-Harith reported that some people disputed in her presence on the Day of ‘Arafah about whether the Messenger of Allah ﷺ was fasting. Some said: He was fasting, and others said: He was not fasting. So she sent him a cup of milk while he was standing on his camel, and he drank."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":132},{"key":"bukhari","label":"البخاريّ","number":1661},{"key":"muslim","label":"مسلم","number":110}]},{"num":5120,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: فلم يزل (يعني النبيَّ ﷺ) واقفاً حتى غربت الشمس وذهبت الصفرة قليلاً حتى غاب القرص… الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب الإفاضة من عرفات بعد غروب الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Departing from ‘Arafah after sunset","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":87,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: He — meaning the Prophet ﷺ — remained standing until the sun had set, and the yellow glow had faded somewhat, until the disk disappeared… the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5121,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: وقف رسولُ اللّٰه ﷺ بعرفة، ثم أفاض حين غابت الشمس، وأردف أسامة بن زيد."],"takhrij":"حسن: رواه أبو داود (١٩٣٥، ١٩٢٢)، والترمذيّ (٨٨٥)، وابن ماجه (٣٠١٠)، وصحّحه ابن خزيمة (٢٨٣٧).","grade":"حسن","chapter_ar":"باب الإفاضة من عرفات بعد غروب الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1935, 1922), al-Tirmidhi (885), and Ibn Majah (3010), and authenticated by Ibn Khuzaymah (2837).","chapter_en":"Departing from ‘Arafah after sunset","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":87,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ stood at ‘Arafah, then departed when the sun had set, and he had Usamah ibn Zayd ride behind him."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1935},{"key":"tirmidhi","label":"الترمذيّ","number":885},{"key":"ibnmajah","label":"ابن ماجه","number":3010},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2837}]},{"num":5122,"demo":false,"sanad":"","matn":["عن أسامة، قال: كنتُ رِدْف النبيّ ﷺ، فلما وقعت الشمس دفع رسولُ اللّٰه ﷺ."],"takhrij":"حسن: رواه أبو داود (١٩٢٤).","grade":"حسن","chapter_ar":"باب الإفاضة من عرفات بعد غروب الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1924).","chapter_en":"Departing from ‘Arafah after sunset","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":87,"content":{"translation":{"en":["Usamah said: I was riding behind the Prophet ﷺ, and when the sun had set the Messenger of Allah ﷺ departed."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1924}]},{"num":5123,"demo":false,"sanad":"","matn":["عن عروة بن مُضَرِّس الطائي قال: أتيت رسولَ اللّٰه ﷺ بالموقف - يعني بجمع - قلت: جئت يا رسول اللّٰه من جبل طيّء، أكللتُ مطيّتي وأتعبتُ نفسي، واللّٰه ما تركتُ من حبلٍ إلا وقفتُ عليه، فهل لي من حجّ؟ فقال رسولُ اللّٰه ﷺ: (( من أدرك معنا هذه الصلاة، وأتى عرفات قبل ذلك ليلاً أو نهاراً فقد تمّ حجُّه وقضى تفثه ))."],"takhrij":"صحيح: رواه أبو داود (١٩٥٠)، والترمذيّ (٨٩١)، والنسائيّ (٣٠٤١)، وابن ماجه (٣٠١٦). قال الترمذي: (( هذا حديث حسن صحيح )).","grade":"صحيح","chapter_ar":"باب الإفاضة من عرفات بعد غروب الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1950), al-Tirmidhi (891), al-Nasa’i (3041), and Ibn Majah (3016). Al-Tirmidhi said: “This is a Hasan Sahih hadith.”","chapter_en":"Departing from ‘Arafah after sunset","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":87,"content":{"translation":{"en":["‘Urwah ibn Mudarris al-Ta’i said: I came to the Messenger of Allah ﷺ at the standing place — meaning at Muzdalifah — and said: I have come, O Messenger of Allah ﷺ, from Mount Tayy’, I have exhausted my riding animal and worn myself out. By Allah, I did not leave any hill but that I stood upon it. So do I have a pilgrimage? The Messenger of Allah ﷺ said: “Whoever joins us in this prayer, and had come to ‘Arafat before that by night or by day, then his pilgrimage is complete and he has completed his rites.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1950},{"key":"tirmidhi","label":"الترمذيّ","number":891},{"key":"nasai","label":"النسائيّ","number":3041},{"key":"ibnmajah","label":"ابن ماجه","number":3016}]},{"num":5124,"demo":false,"sanad":"","matn":["عن عروة بن الزبير، أنه قال: سُئل أسامة بن زيد وأنا جالس معه: كيف كان يسير رسولُ اللّٰه ﷺ في حجّة الوداع حين دفع؟ قال: كان يسير العنق، فإذا وجد فجوةً نصَّ.","قال مالك: قال هشام: والنصُّ فوق العنق."],"takhrij":"متفق عليه: رواه مالك (١٧٦)، والبخاريّ (١٦٦٦)، ومسلم (١٢٨٦ : ٢٨٣-٢٨٤).","grade":"متفق عليه","chapter_ar":"باب السير في هدوء عند الإفاضة من عرفات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (176), al-Bukhari (1666), and Muslim (1286:283-284).","chapter_en":"Moving calmly when departing from ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":88,"content":{"translation":{"en":["‘Urwah ibn al-Zubayr reported that Usamah ibn Zayd was asked while I was sitting with him: How did the Messenger of Allah ﷺ travel in the Farewell Pilgrimage when he departed? He said: He moved at a moderate pace, and when he found an open space he hastened.","Malik said: Hisham said: Hastening is faster than the moderate pace."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":176},{"key":"bukhari","label":"البخاريّ","number":1666},{"key":"muslim","label":"مسلم","number":1286}]},{"num":5125,"demo":false,"sanad":"","matn":["عن ابن عباس، أنه دفع مع النبيّ ﷺ يوم عرفة، فسمع النبيّ ﷺ وراءه زجراً شديداً، وضرباً وصوتاً للإبل، فأشار بسوطه إليهم وقال: (( أيها الناس، عليكم بالسكينة، فإن البرّ ليس بالإيضاع ))."],"takhrij":"صحيح: رواه البخاريّ (١٦٧١).","grade":"صحيح","chapter_ar":"باب السير في هدوء عند الإفاضة من عرفات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1671).","chapter_en":"Moving calmly when departing from ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":88,"content":{"translation":{"en":["Ibn ‘Abbas reported that he departed with the Prophet ﷺ on the Day of ‘Arafah, and the Prophet ﷺ heard behind him loud rebuking, striking, and shouting at the camels. So he pointed to them with his whip and said: “O people, remain calm, for righteousness is not in rushing.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1671}]},{"num":5126,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: ودفع رسولُ اللّٰه ﷺ وقد شنق للقصواء الزمام، حتى إنّ رأسها ليصيب مورك رحله، ويقول بيده اليمنى: (( أيها الناس، السكينةَ السكينةَ ))… الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب السير في هدوء عند الإفاضة من عرفات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Moving calmly when departing from ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":88,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ departed while holding al-Qaswa’ with a shortened rein, to the point that her head almost touched the front part of his saddle, and he was saying with his right hand: “O people, calmness, calmness…” the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5127,"demo":false,"sanad":"","matn":["عن الفضل بن عباس - وكان رديف رسول اللّٰه ﷺ - أنه قال في عشية عرفة وغداة جمع للناس حين دفعوا: (( عليكم بالسكينة ))، وهو كافٌّ ناقته."],"takhrij":"صحيح: رواه مسلم (١٢٨٢).","grade":"صحيح","chapter_ar":"باب السير في هدوء عند الإفاضة من عرفات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1282).","chapter_en":"Moving calmly when departing from ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":88,"content":{"translation":{"en":["Al-Fadl ibn ‘Abbas — who was riding behind the Messenger of Allah ﷺ — reported that on the evening of ‘Arafah and the morning of Muzdalifah he said to the people when they departed: “Remain calm,” while he was restraining his camel."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1282}]},{"num":5128,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ رسولَ اللّٰه ﷺ أفاض من عرفة، وأسامةُ رديفُه. قال أسامة: فما زال يسير على هيئته حتى أتى جمعاً."],"takhrij":"صحيح: رواه مسلم (١٢٨٦ : ٢٨٢).","grade":"صحيح","chapter_ar":"باب السير في هدوء عند الإفاضة من عرفات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1286:282).","chapter_en":"Moving calmly when departing from ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":88,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ departed from ‘Arafah, with Usamah riding behind him. Usamah said: He continued moving in the same calm manner until he came to Muzdalifah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1286}]},{"num":5129,"demo":false,"sanad":"","matn":["عن أسامة أنّ رسولَ اللّٰه ﷺ أفاض من عرفة، ورديفُه أسامة، فجعل يكبح راحلته حتى إنّ ذِفراها لتكاد أن تمسّ - وربما قال حماد: أن تصيب - قادمةَ الرحل، وهو يقول: (( يا أيها الناس، عليكم بالسكينة والوقار، فإن البرّ ليس في إيضاع الإبل ))."],"takhrij":"صحيح: رواه النسائيّ (٣٠١٨)، وأحمد (٢١٧٥٦)، والبيهقيّ (١١٩/٥).","grade":"صحيح","chapter_ar":"باب السير في هدوء عند الإفاضة من عرفات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3018), Ahmad (21756), and al-Bayhaqi (5/119).","chapter_en":"Moving calmly when departing from ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":88,"content":{"translation":{"en":["Usamah reported that the Messenger of Allah ﷺ departed from ‘Arafah with Usamah riding behind him. He kept restraining his mount until the area behind its ears nearly touched — or, as Hammad said, struck — the front of the saddle, and he was saying: “O people, keep calm and dignified, for righteousness is not in making the camels rush.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":3018},{"key":"البیہقی","label":"البيهقيّ","number":119},{"key":"ahmad","label":"مسند الإمام أحمد","number":21756,"n":21756}]},{"num":5130,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، قال: ثم أردف أسامة، فجعل يُعنِق على ناقته، والناس يضربون الإبل يميناً وشمالاً، ويلتفت إليهم ويقول: (( السكينة أيها الناس ))، ودفع حين غابت الشمس."],"takhrij":"حسن: رواه أبو داود (١٩٢٢)، والترمذيّ (٨٨٥).","grade":"حسن","chapter_ar":"باب السير في هدوء عند الإفاضة من عرفات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1922) and al-Tirmidhi (885).","chapter_en":"Moving calmly when departing from ‘Arafah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":88,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: Then he had Usamah ride behind him, and he made his she-camel move at a moderate pace, while the people were driving the camels right and left. He turned toward them and said: “Calmness, O people,” and he departed when the sun had set."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1922},{"key":"tirmidhi","label":"الترمذيّ","number":885}]},{"num":5131,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر: أنّ رسولَ اللّٰه ﷺ صلّى المغرب والعشاء بالمزدلفة جميعاً."],"takhrij":"متفق عليه: رواه مالك (١٩٦)، ومسلم (٧٠٣ : ٢٨٦)، والبخاريّ (١٦٧٣).","grade":"متفق عليه","chapter_ar":"باب الجمع بين الصلاتين بالمزدلفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (196), Muslim (703:286), and al-Bukhari (1673).","chapter_en":"Combining the two prayers at Muzdalifah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":89,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar reported that the Messenger of Allah ﷺ prayed Maghrib and ‘Isha together at Muzdalifah."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":196},{"key":"muslim","label":"مسلم","number":703},{"key":"bukhari","label":"البخاريّ","number":1673}]},{"num":5132,"demo":false,"sanad":"","matn":["عن أبي أيوب الأنصاريّ، أنّه صلّى مع رسول اللّٰه ﷺ في حجّة الوداع المغرب والعشاء بالمزدلفة جميعاً."],"takhrij":"متفق عليه: رواه مالك (١٩٨)، والبخاريّ (٤٤١٤)، ومسلم (١٢٨٧).","grade":"متفق عليه","chapter_ar":"باب الجمع بين الصلاتين بالمزدلفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (198), al-Bukhari (4414), and Muslim (1287).","chapter_en":"Combining the two prayers at Muzdalifah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":89,"content":{"translation":{"en":["Abu Ayyub al-Ansari reported that he prayed Maghrib and ‘Isha together at Muzdalifah with the Messenger of Allah ﷺ in the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":198},{"key":"bukhari","label":"البخاريّ","number":4414},{"key":"muslim","label":"مسلم","number":1287}]},{"num":5133,"demo":false,"sanad":"","matn":["عن أسامة بن زيد، أنّ رسولَ اللّٰه ﷺ لما أفاض من عرفة عدل إلى الشعب، فقضى حاجته. قال أسامة بن زيد: فجعلتُ أصبّ عليه ويتوضأ. فقلت: يا رسول اللّٰه، أتصلي؟ فقال: (( الصلاة أمامك ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٨١)، ومسلم (١٢٨٠).","grade":"متفق عليه","chapter_ar":"باب الجمع بين الصلاتين بالمزدلفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1681) and Muslim (1280).","chapter_en":"Combining the two prayers at Muzdalifah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":89,"content":{"translation":{"en":["Usamah ibn Zayd reported that when the Messenger of Allah ﷺ departed from ‘Arafah, he turned toward the mountain pass and relieved himself. Usamah ibn Zayd said: Then I poured water for him while he performed ablution. I said: O Messenger of Allah ﷺ, will you pray now? He said: “The prayer is ahead of you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1681},{"key":"muslim","label":"مسلم","number":1280}]},{"num":5134,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: حتى أتى المزدلفة، فصلّى بها المغرب والعشاء بأذانٍ واحدٍ وإقامتين، ولم يسبّح بينهما شيئاً، ثم اضطجع رسولُ اللّٰه ﷺ حتى طلع الفجر… الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب الجمع بين صلاتي المغرب والعشاء في مزدلفة بأذان واحد وإقامتين، ولا يتنفّل بينهما ولا على إثرهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Combining Maghrib and ‘Isha at Muzdalifah with one call to prayer and two commencement calls, and not offering voluntary prayer between them or immediately after them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":90,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: Then he came to Muzdalifah and prayed Maghrib and ‘Isha there with one call to prayer and two commencement calls, and he did not glorify Allah with any voluntary prayer between them. Then the Messenger of Allah ﷺ lay down until dawn broke… the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5135,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: جمع النبيُّ ﷺ بين المغرب والعشاء بجمع، كلُّ واحدةٍ منهما بإقامة، ولم يسبّح بينهما ولا على إثر كلّ واحدةٍ منهما."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٧٣)، ومسلم (١٢٨٨ : ٢٨٧).","grade":"متفق عليه","chapter_ar":"باب الجمع بين صلاتي المغرب والعشاء في مزدلفة بأذان واحد وإقامتين، ولا يتنفّل بينهما ولا على إثرهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1673) and Muslim (1288:287).","chapter_en":"Combining Maghrib and ‘Isha at Muzdalifah with one call to prayer and two commencement calls, and not offering voluntary prayer between them or immediately after them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":90,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ combined Maghrib and ‘Isha at Muzdalifah, each one of them with its own commencement call, and he did not perform voluntary prayer between them nor after either of them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1673},{"key":"muslim","label":"مسلم","number":1288}]},{"num":5136,"demo":false,"sanad":"","matn":["عن سعيد بن جبير، أنه صلّى المغرب بجمع، والعشاء بإقامة، ثم حدّث عن ابن عمر أنّه صلّى مثل ذلك، وحدّث ابن عمر أنّ النبيَّ ﷺ صنع مثل ذلك."],"takhrij":"صحيح: رواه مسلم (١٢٨٨ : ٢٨٨).","grade":"صحيح","chapter_ar":"باب الجمع بين صلاتي المغرب والعشاء في مزدلفة بأذان واحد وإقامتين، ولا يتنفّل بينهما ولا على إثرهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1288:288).","chapter_en":"Combining Maghrib and ‘Isha at Muzdalifah with one call to prayer and two commencement calls, and not offering voluntary prayer between them or immediately after them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":90,"content":{"translation":{"en":["Sa‘id ibn Jubayr reported that he prayed Maghrib at Muzdalifah and ‘Isha with a commencement call, then narrated from Ibn ‘Umar that he prayed in that way, and Ibn ‘Umar narrated that the Prophet ﷺ had done the same."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1288}]},{"num":5137,"demo":false,"sanad":"","matn":["عن عبد الله بن مالك، أن ابن عمر صلّى بجمع، فجمع بين الصلاتين بإقامة، وقال: رأيتُ رسولَ اللّٰه ﷺ فعل مثل هذا في هذا المكان."],"takhrij":"حسن: رواه الترمذيّ (٨٨٧)، وأبو داود (١٩٢٩)، واللفظ للترمذي. وقال: (( هذا حديث حسن صحيح )).","grade":"حسن","chapter_ar":"باب الجمع بين صلاتي المغرب والعشاء في مزدلفة بأذان واحد وإقامتين، ولا يتنفّل بينهما ولا على إثرهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (887) and Abu Dawud (1929), and the wording is that of al-Tirmidhi. He said: “This is a Hasan Sahih hadith.”","chapter_en":"Combining Maghrib and ‘Isha at Muzdalifah with one call to prayer and two commencement calls, and not offering voluntary prayer between them or immediately after them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":90,"content":{"translation":{"en":["‘Abd Allah ibn Malik reported that Ibn ‘Umar prayed at Muzdalifah and combined the two prayers with a commencement call, and said: I saw the Messenger of Allah ﷺ do the same in this place."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":887},{"key":"abudawud","label":"أبو داود","number":1929}]},{"num":5138,"demo":false,"sanad":"","matn":["عن ابن عمر قال: إنّه صلّى مع رسول اللّٰه ﷺ بالمزدلفة المغرب والعشاء بإقامةٍ واحدةٍ جمع بينهما."],"takhrij":"صحيح: رواه أبو داود (١٩٢٧)، وأحمد (٦٤٧٣).","grade":"صحيح","chapter_ar":"باب الجمع بين صلاتي المغرب والعشاء في مزدلفة بأذان واحد وإقامتين، ولا يتنفّل بينهما ولا على إثرهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1927) and Ahmad (6473).","chapter_en":"Combining Maghrib and ‘Isha at Muzdalifah with one call to prayer and two commencement calls, and not offering voluntary prayer between them or immediately after them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":90,"content":{"translation":{"en":["Ibn ‘Umar said: He prayed Maghrib and ‘Isha with the Messenger of Allah ﷺ at Muzdalifah with one commencement call, combining the two together."]},"buhuth":{"ar":["وقال أبو داود: قال أحمد: قال وكيع: (( صلّى كلَّ صلاةٍ بإقامة )). إلا أنّ هذا لم يذكره أحد."],"en":["Abu Dawud said: Ahmad said: Waki‘ said: “He prayed each prayer with its own commencement call,” though no one else mentioned that wording."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1927},{"key":"ahmad","label":"مسند الإمام أحمد","number":6473,"n":6473}]},{"num":5139,"demo":false,"sanad":"","matn":["عن أشعث بن سليم، عن أبيه قال: أقبلتُ مع ابن عمر من عرفات إلى المزدلفة، فلم يكن يفتر من التكبير والتهليل حتى أتينا المزدلفة، فأذّن وأقام - أو أمر إنساناً فأذّن وأقام - فصلّى بنا المغرب ثلاث ركعات، ثم التفت إلينا فقال: الصلاة، فصلّى بنا العشاء ركعتين، ثم دعا بعشائه."],"takhrij":"صحيح: رواه أبو داود (١٩٣٣).","grade":"صحيح","chapter_ar":"باب الجمع بين صلاتي المغرب والعشاء في مزدلفة بأذان واحد وإقامتين، ولا يتنفّل بينهما ولا على إثرهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1933).","chapter_en":"Combining Maghrib and ‘Isha at Muzdalifah with one call to prayer and two commencement calls, and not offering voluntary prayer between them or immediately after them","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":90,"content":{"translation":{"en":["Ash‘ath ibn Sulaym, from his father, said: I came with Ibn ‘Umar from ‘Arafat to Muzdalifah, and he did not cease making takbir and tahlil until we reached Muzdalifah. Then he gave the call to prayer and the commencement call — or he ordered someone to do so — and led us in Maghrib with three units. Then he turned to us and said: The prayer. Then he led us in ‘Isha with two units, and then he called for his evening meal."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1933}]},{"num":5140,"demo":false,"sanad":"","matn":["عن أسامة بن زيد أنه قال: دفع رسولُ اللّٰه ﷺ من عرفة، حتى إذا كان بالشِّعْبِ نزل فبال فتوضأ، فلم يسبغ الوضوء، فقلت له: الصلاة يا رسول الله؟ فقال: (( الصلاة أمامك )). فركب، فلما جاء المزدلفة نزل فتوضأ فأسبغ الوضوء، ثم أقيمت الصلاة فصلى المغرب، ثم أناخ كلُّ إنسان بعيره في منزله، ثم أقيمت العشاء فصلاها ولم يصلِّ بينهما شيئًا."],"takhrij":"متفق عليه: رواه مالك (١٩٧)، والبخاريّ (١٦٧٢)، ومسلم (٢٧٦ : ١٢٨٠).","grade":"متفق عليه","chapter_ar":"باب من قال: يجمع بينهما بإقامتين فقط بدون أذان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (197), al-Bukhārī (1672), and Muslim (1280:276).","chapter_en":"Those who said that the two prayers are combined with two iqāmahs only, without an adhān","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":91,"content":{"translation":{"en":["Usāmah ibn Zayd said: The Messenger of Allah ﷺ departed from ‘Arafah, and when he reached the mountain pass he stopped, urinated, and performed ablution, but he did not do it thoroughly. I said to him, “The prayer, O Messenger of Allah ﷺ?” He said, “The prayer is ahead of you.” Then he rode on. When he came to Muzdalifah, he dismounted and performed ablution thoroughly. Then the iqāmah was given and he prayed Maghrib. After that, each person made his camel kneel at his place. Then the iqāmah for ‘Ishā’ was given, and he prayed it, and he did not pray anything between them."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":197},{"key":"bukhari","label":"البخاريّ","number":1672},{"key":"muslim","label":"مسلم","number":276}]},{"num":5141,"demo":false,"sanad":"","matn":["عن أبي إسحاق قال: سمعت عبد الرحمن بن يزيد يقول: حجَّ عبدُ الله رضي اللّٰه عنه، فأتينا المزدلفة حين الأذان بالعتمة أو قريبًا من ذلك، فأمر رجلًا فأذَّن وأقام، ثم صلى المغرب، وصلّى بعدها ركعتين، ثم دعا بعشائه فتعشَّى، ثم أمر - أرى - فأذَّن وأقام.","قال عمرو: لا أعلم الشك إلا من زهير.","ثم صلى العشاء ركعتين، فلما طلع الفجر قال: إنّ النبيَّ ﷺ كان لا يصلي هذه الساعة إلا هذه الصلاة في هذا المكان من هذا اليوم. ثم قال عبد الله: هما صلاتان تحوَّلان عن وقتهما: صلاة المغرب بعد ما يأتي الناس المزدلفة، والفجر حين يبزغ الفجر. قال: رأيت النبيَّ ﷺ يفعله."],"takhrij":"صحيح: رواه البخاريّ (١٦٧٥).","grade":"صحيح","chapter_ar":"باب من أذَّن وأقام لكلّ واحدة منهما","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1675).","chapter_en":"Those who gave an adhān and an iqāmah for each of the two prayers","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":92,"content":{"translation":{"en":["Abū Isḥāq said: I heard ‘Abd al-Raḥmān ibn Yazīd say: ‘Abdullāh, may Allah be pleased with him, performed Hajj, and we came to Muzdalifah around the time of the call for ‘Ishā’, or close to that. He ordered a man, who then gave the adhān and iqāmah, and then he prayed Maghrib. After it, he prayed two rak‘ahs, then he called for his supper and ate. Then he ordered — I think — and another adhān and iqāmah were given.","‘Amr said: I do not know that the uncertainty came from anyone except Zuhayr.","Then he prayed ‘Ishā’ as two rak‘ahs. When dawn came, he said: The Prophet ﷺ would not pray at this hour except this prayer, in this place, on this day. Then ‘Abdullāh said: These are two prayers shifted from their normal times: Maghrib after the people come to Muzdalifah, and Fajr when dawn first breaks. He said: I saw the Prophet ﷺ do this."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1675}]},{"num":5142,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: ما رأيتُ النبيَّ ﷺ صلّى صلاةً بغير ميقاتها إلا صلاتين: جمعَ بين المغرب والعشاء، وصلّى الفجر قبل ميقاتها."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٨٢)، ومسلم (١٢٨٩).","grade":"متفق عليه","chapter_ar":"باب صلاة الصبح يوم النحر بالمزدلفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1682) and Muslim (1289).","chapter_en":"The Fajr prayer on the Day of Sacrifice at Muzdalifah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":93,"content":{"translation":{"en":["Ibn Mas‘ūd said: I did not see the Prophet ﷺ pray any prayer outside its usual time except two prayers: he combined Maghrib and ‘Ishā’, and he prayed Fajr before its usual time."]},"buhuth":{"ar":["قوله في الحديث: (( وصلى الفجر قبل ميقاتها )) ليس معناه أنه أوقع الفجر قبل طلوعه، وإنما أراد أنها وقعت قبل الوقت المعتاد فعلها فيه في الحضر. انظر: فتح الباري (٥٢٥/٣)."],"en":["His statement in the hadith, “He prayed Fajr before its usual time,” does not mean that he prayed it before dawn had entered. Rather, it means that he prayed it earlier than the normal time at which it was usually prayed in residence. See: Fatḥ al-Bārī (3/525)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1682},{"key":"muslim","label":"مسلم","number":1289}]},{"num":5143,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: ثم ركب (يعني النبيَّ ﷺ) القصواء حتى أتى المشعر الحرام، فاستقبل القبلة، فدعاه وكبَّره وهلَّله، ووحَّده، فلم يزل واقفًا حتى أسفر جدًّا… الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب إتيان المشعر الحرام والوقوف به للدعاء والذكر بعد صلاة الصبح إلى أن يُسفر الفجر جدًّا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Going to al-Mash‘ar al-Ḥarām and standing there for supplication and remembrance after Fajr until the morning becomes very bright","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":94,"content":{"translation":{"en":["Jābir ibn ‘Abdullāh said: Then he — meaning the Prophet ﷺ — mounted al-Qaṣwā’ until he came to al-Mash‘ar al-Ḥarām. He faced the qiblah, supplicated to Allah, magnified Him, uttered the tahlil, affirmed His oneness, and he remained standing until the morning became very bright… the hadith."]},"intro":{"ar":["قال اللّٰه تعالى: ( فَإِذَا أَفَضْتُم مِّنْ عَرَفَاتٍ فَاذْكُرُوا اللَّهَ عِندَ الْمَشْعَرِ الْحَرَامِ ) [البقرة: ١٩٨]."],"en":["Allah the Most High said: “Then when you depart from ‘Arafāt, remember Allah at al-Mash‘ar al-Ḥarām.” [Al-Baqarah: 198]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5144,"demo":false,"sanad":"","matn":["عن عمرو بن ميمون يقول: شهدت عمر رضي الله عنه صلّى بجمع الصبح، ثم وقف فقال: إنّ المشركين كانوا لا يفيضون حتى تطلع الشمس، ويقولون: أَشْرِقْ ثَبِيرُ، وإنّ النبيَّ ﷺ خالفهم، ثم أفاض قبل أن تطلع الشمس."],"takhrij":"صحيح: رواه البخاريّ (١٦٨٤).","grade":"صحيح","chapter_ar":"باب الدفع من مزدلفة قبل طلوع الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1684).","chapter_en":"Departing from Muzdalifah before sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":95,"content":{"translation":{"en":["‘Amr ibn Maymūn said: I witnessed ‘Umar, may Allah be pleased with him, pray Fajr at Jam‘, then he stood and said: The polytheists would not depart until the sun had risen, and they would say: “O Thabīr, shine!” But the Prophet ﷺ opposed them, and so he departed before the sun rose."]},"buhuth":{"ar":["وقوله: (( أشرق ثبير )) أي ادخل أيها الجبل في الشروق. و(( ثبير )) بفتح الثاء وكسر الباء، جبلٌ بالمزدلفة على يسار الذاهب إلى منى. وقيل: هو أعظم جبال مكة."],"en":["His statement, “Ashriq Thabīr,” means: O mountain, enter into the sunrise. “Thabīr” — with the thā’ fatḥah and the bā’ kasrah — is a mountain at Muzdalifah on the left side of the one going to Minā. It is also said that it is the greatest of the mountains of Makkah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1684}]},{"num":5145,"demo":false,"sanad":"","matn":["عن جابر قال: فلم يزل (يعني النبيَّ ﷺ) واقفًا حتى أسفر جدًّا، فدفع قبل أن تطلع الشمس، وأردف الفضل بن عباس… الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب الدفع من مزدلفة قبل طلوع الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Departing from Muzdalifah before sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":95,"content":{"translation":{"en":["Jābir said: He — meaning the Prophet ﷺ — continued standing until the morning became very bright, then he departed before the sun rose, and he had al-Faḍl ibn ‘Abbās ride behind him… the hadith."]},"buhuth":{"ar":["من السنة أن يدفع الحاج من المزدلفة قبل طلوع الشمس، قال طاوس: كان أهل الجاهلية يدفعون من عرفة قبل أن تغيب الشمس، ومن المزدلفة بعد أن تطلع الشمس، فأخَّر الله هذه، وقدَّم هذه."],"en":["It is from the Sunnah that the pilgrim depart from Muzdalifah before sunrise. Ṭāwūs said: The people of Jāhiliyyah used to depart from ‘Arafah before sunset, and from Muzdalifah after sunrise. So Allah delayed this and brought forward that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5146,"demo":false,"sanad":"","matn":["عن ابن عباس، أن رسول اللّٰه ﷺ وقف بجمع، فلما أضاء كل شيء قبل أن تطلع الشمس أفاض."],"takhrij":"حسن بالمتابعة: رواه أحمد (٣٠٢٠)، والترمذي (٨٩٥)، وأحمد (٢٠٥١). قال الترمذي: (( حسن صحيح )).","grade":"حسن بالمتابعة","chapter_ar":"باب الدفع من مزدلفة قبل طلوع الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan due to supporting chains: Narrated by Aḥmad (3020, 2051) and al-Tirmidhī (895). Al-Tirmidhī said: “Hasan Sahih.”","chapter_en":"Departing from Muzdalifah before sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":95,"content":{"translation":{"en":["Ibn ‘Abbās reported that the Messenger of Allah ﷺ stood at Jam‘, and when everything became bright before the sun rose, he departed."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":895},{"key":"ahmad","label":"مسند الإمام أحمد","number":3020,"n":3020},{"key":"ahmad","label":"مسند الإمام أحمد","number":2051,"n":2051}]},{"num":5147,"demo":false,"sanad":"","matn":["عن الفضل بن عباس - وكان رديف رسول اللّٰه ﷺ - أنه قال في عشيّة عرفة وغداة جمع للناس حين دفعوا: (( عليكم بالسكينة )) وهو كافٌّ ناقته."],"takhrij":"صحيح: رواه مسلم (١٢٨٢).","grade":"صحيح","chapter_ar":"باب السير في هدوء عند الدفع من المزدلفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1282).","chapter_en":"Moving calmly when departing from Muzdalifah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":96,"content":{"translation":{"en":["Al-Faḍl ibn ‘Abbās — and he was riding behind the Messenger of Allah ﷺ — said that on the evening of ‘Arafah and the morning of Jam‘, when the people departed, he said: “Remain calm,” while restraining his camel."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1282}]},{"num":5148,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: إنما كان بدء الإيضاع من قبل أهل البادية، كانوا يقفون حافَّتَي الناس حتى يعلِّقوا العِصيَّ والجِعابَ والقِعابَ، فإذا نفروا، تقعقعت تلك، فنفروا بالناس، وقال: ولقد رُئي رسولُ اللّٰه ﷺ وإنّ ذِفْرَى ناقته ليمسُّ حاركها، وهو يقول بيده: (( يا أيها الناس، عليكم بالسكينة، يا أيها الناس، عليكم بالسكينة ))."],"takhrij":"حسن: رواه أحمد (٢١٩٣)، وابن خزيمة (٢٨٦٣)، والحاكم (٤٦٥/١).","grade":"حسن","chapter_ar":"باب السير في هدوء عند الدفع من المزدلفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (2193), Ibn Khuzaymah (2863), and al-Ḥākim (1/465).","chapter_en":"Moving calmly when departing from Muzdalifah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":96,"content":{"translation":{"en":["Ibn ‘Abbās said: The beginning of rushing came from the desert people. They would stand along the two sides of the people until they hung up the sticks, quivers, and bowls. When they set off, those things rattled, and so they caused the people to rush. He said: The Messenger of Allah ﷺ was seen while the area behind his she-camel’s ear nearly touched her withers, and he was saying with his hand: “O people, remain calm. O people, remain calm.”"]},"buhuth":{"ar":["وقوله: (( الإيضاع )) هو حمل البعير ونحوه على الإسراع."],"en":["His statement, “al-īḍā‘,” means urging the camel and the like to move quickly."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2863},{"key":"hakim","label":"الحاكم","number":465},{"key":"ahmad","label":"مسند الإمام أحمد","number":2193,"n":2193}]},{"num":5149,"demo":false,"sanad":"","matn":["عن جابر، قال: حتى أتى بطن محسِّر، فحرَّك قليلًا، ثم سلك الطريق الوسطى."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب الإسراع في المشي وتحريك الراكب دابته ونحوها في وادي محسِّر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Hastening on foot, and the rider urging his mount and the like in Wādī Muḥassir","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":97,"content":{"translation":{"en":["Jābir said: When he came to the bottom of Muḥassir, he hastened a little, then took the middle road."]},"buhuth":{"ar":["قوله: (( بطن مُحَسِّر )) بضم الميم وفتح الحاء وكسر السين المشددة، سُمِّي بذلك لأن فيل أصحاب الفيل حَسَر فيه، أي أعيا وكلَّ. شرح النووي (١٨٩/٨)."],"en":["His statement, “the bottom of Muḥassir,” with the mīm ḍammah, the ḥā’ fatḥah, and the sīn with shaddah and kasrah, was named so because the elephant of the People of the Elephant grew exhausted and wearied there. Sharḥ al-Nawawī (8/189)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5150,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، قال: لما أفاض النبيُّ ﷺ من جمع، وانتهى إلى وادي محسِّر، قرع ناقته فخبَّتْ حتى جاوز الوادي."],"takhrij":"حسن: رواه الترمذيّ (٨٨٥). قال الترمذي: (( حسن صحيح )).","grade":"حسن","chapter_ar":"باب الإسراع في المشي وتحريك الراكب دابته ونحوها في وادي محسِّر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (885). Al-Tirmidhī said: “Hasan Sahih.”","chapter_en":"Hastening on foot, and the rider urging his mount and the like in Wādī Muḥassir","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":97,"content":{"translation":{"en":["‘Alī ibn Abī Ṭālib said: When the Prophet ﷺ departed from Jam‘ and reached Wādī Muḥassir, he urged his she-camel, and it moved briskly until it passed the valley."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":885}]},{"num":5151,"demo":false,"sanad":"","matn":["عن أسامة بن زيد أنه قال: رَدِفْتُ رسولَ اللّٰه ﷺ من عرفات، فلما بلغ رسولُ اللّٰه ﷺ الشِّعْبَ الأيسر الذي دون المزدلفة أناخ فبال، ثم جاء فصببتُ عليه الوضوء فتوضأ وضوءًا خفيفًا، فقلت: الصلاة يا رسول الله؟ قال: (( الصلاة أمامك )). فركب رسولُ اللّٰه ﷺ حتى أتى المزدلفة فصلّى، ثم ردف الفضلُ رسولَ اللّٰه ﷺ غداة جمع. قال كريب: فأخبرني عبد الله بن عباس رضي اللّٰه عنهما، عن الفضل: أنّ رسولَ اللّٰه ﷺ لم يزل يلبّي حتى بلغ الجمرة."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٦٩)، ومسلم (١٢٨٠).","grade":"متفق عليه","chapter_ar":"باب استحباب التلبية عند الدفع من المزدلفة إلى أن يرمي جمرة العقبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1669) and Muslim (1280).","chapter_en":"The recommendation of continuing the talbiyah when departing from Muzdalifah until stoning Jamrat al-‘Aqabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":98,"content":{"translation":{"en":["Usāmah ibn Zayd said: I rode behind the Messenger of Allah ﷺ from ‘Arafāt. When the Messenger of Allah ﷺ reached the left pass below Muzdalifah, he made his camel kneel, urinated, then came back and I poured water for his ablution, and he made a light ablution. I said: “The prayer, O Messenger of Allah ﷺ?” He said: “The prayer is ahead of you.” So the Messenger of Allah ﷺ rode until he came to Muzdalifah and prayed. Then al-Faḍl rode behind the Messenger of Allah ﷺ on the morning of Jam‘. Kurayb said: Then ‘Abdullāh ibn ‘Abbās, may Allah be pleased with them both, informed me from al-Faḍl that the Messenger of Allah ﷺ continued making the talbiyah until he reached the Jamrah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1669},{"key":"muslim","label":"مسلم","number":1280}]},{"num":5152,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن يزيد، أنّ عبد الله لبّى حين أفاض من جمع، فقيل: أعرابيٌّ هذا؟ فقال عبد الله: أنسي الناسُ أم ضلّوا؟ سمعتُ الذي أُنزلت عليه سورة البقرة يقول في هذا المكان: (( لبيك اللهم لبيك ))."],"takhrij":"صحيح: رواه مسلم (١٢٨٣).","grade":"صحيح","chapter_ar":"باب استحباب التلبية عند الدفع من المزدلفة إلى أن يرمي جمرة العقبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1283).","chapter_en":"The recommendation of continuing the talbiyah when departing from Muzdalifah until stoning Jamrat al-‘Aqabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":98,"content":{"translation":{"en":["‘Abd al-Raḥmān ibn Yazīd reported that ‘Abdullāh made the talbiyah when he departed from Jam‘, so it was said: “Is this a Bedouin?” ‘Abdullāh replied: “Have the people forgotten, or have they gone astray? I heard the one upon whom Sūrat al-Baqarah was revealed saying in this place: ‘Labbayka Allāhumma labbayk.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1283}]},{"num":5153,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن معاذ التيمي قال: خطبنا رسولُ اللّٰه ﷺ ونحن بمنى، ففُتحت أسماعُنا حتى كنّا نسمع ما يقول ونحن في منازلنا، فطفق يعلمهم مناسكهم حتى بلغ الجمار، فوضع إصبعيه السبابتين، ثم قال: (( بحصى الخذف )). ثم أمر المهاجرين فنزلوا في مقدَّم المسجد، وأمر الأنصار فنزلوا من وراء المسجد، ثم نزل الناس بعد ذلك."],"takhrij":"صحيح: رواه أبو داود (١٩٥٧)، والنسائي (٢٩٩٦)، وأحمد (١٦٥٨٩)، والبيهقي (١٢٧/٥).","grade":"صحيح","chapter_ar":"باب نزول النبيّ المهاجرين والأنصار بمنى بعد عودته من المزدلفة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1957), al-Nasā’ī (2996), Aḥmad (16589), and al-Bayhaqī (5/127).","chapter_en":"The Prophet’s settling the Muhājirūn and the Anṣār in Minā after returning from Muzdalifah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":99,"content":{"translation":{"en":["‘Abd al-Raḥmān ibn Mu‘ādh al-Taymī said: The Messenger of Allah ﷺ addressed us while we were in Minā, and our hearing became so open that we could hear what he was saying while we were in our camps. He began teaching them their rites until he reached the topic of the pebbles, then he placed his two index fingers together and said: “Like the pebbles used in slinging.” Then he ordered the Muhājirūn to settle in front of the mosque, and ordered the Anṣār to settle behind the mosque, and then the people settled after that."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1957},{"key":"nasai","label":"النسائي","number":2996},{"key":"البیہقی","label":"البيهقي","number":127},{"key":"ahmad","label":"مسند الإمام أحمد","number":16589,"n":16589},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":9608,"n":9688}]},{"num":5154,"demo":false,"sanad":"","matn":["عن عائشة أنها قالت: استأذنتْ سودةُ رسولَ اللّٰه ﷺ ليلة المزدلفة تدفع قبله وقبل حَطْمةِ الناسِ - وكانت امرأةً ثَبِطةً (يقول القاسم: والثبطة الثقيلة) - قال: فأذن لها، فخرجت قبل دفعه، وحبسنا حتى أصبحنا فدفعنا بدفعه. ولأن أكون استأذنتُ رسولَ اللّٰه ﷺ كما استأذنته سودة، أكون أدفع بإذنه أحبُّ إليَّ من مفروحٍ به."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٨١)، ومسلم (٢٩٣ : ١٢٩٠) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الرخصة للضعفة من النساء وغيرهن في الدفع من مزدلفة إلى منى في آخر الليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1681) and Muslim (1290:293), and this is the wording of Muslim.","chapter_en":"The concession for weak women and others to depart from Muzdalifah to Minā in the latter part of the night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":100,"content":{"translation":{"en":["‘Ā’ishah said: Sawdah asked the Messenger of Allah ﷺ on the night of Muzdalifah for permission to leave before him and before the crush of people — and she was a heavy woman. Al-Qāsim said: “Al-thabiṭah” means heavy. She said: So he permitted her, and she left before he did, while he kept us until morning, and we departed with his departure. And if I had asked the Messenger of Allah ﷺ for permission just as Sawdah had asked him, so that I could depart by his permission, that would have been more beloved to me than something over which one rejoices greatly."]},"buhuth":{"ar":["وقوله: (( قبل حَطْمة الناس )) أي قبل زحمة الناس وازدحامهم بعضهم على بعض."],"en":["His statement, “before the ḥaṭmah of the people,” means before the crowding and crushing of people against one another."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1681},{"key":"muslim","label":"مسلم","number":293}]},{"num":5155,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أنا ممّن قدَّم النبيُّ ﷺ ليلة المزدلفة في ضعفة أهله."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٧٨)، ومسلم (١٢٩٣)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الرخصة للضعفة من النساء وغيرهن في الدفع من مزدلفة إلى منى في آخر الليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1678) and Muslim (1293), and the wording is that of al-Bukhārī.","chapter_en":"The concession for weak women and others to depart from Muzdalifah to Minā in the latter part of the night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":100,"content":{"translation":{"en":["Ibn ‘Abbās said: I was among those whom the Prophet ﷺ sent ahead on the night of Muzdalifah with the weak members of his household."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1678},{"key":"muslim","label":"مسلم","number":1293}]},{"num":5156,"demo":false,"sanad":"","matn":["عن عطاء، عن ابن عباس، قال: بعث بي رسولُ اللّٰه ﷺ بسَحَرٍ من جمعٍ في ثقل نبيِّ اللّٰه ﷺ.","قلت: أبلغك أن ابن عباس قال: بعث بي بليل طويل؟ قال: لا، إلا كذلك، بسحر. قلت له: فقال ابن عباس: رمينا الجمرة قبل الفجر؟ وأين صلى الفجر؟ قال: لا، إلا كذلك."],"takhrij":"صحيح: رواه مسلم (١٢٩٤).","grade":"صحيح","chapter_ar":"باب الرخصة للضعفة من النساء وغيرهن في الدفع من مزدلفة إلى منى في آخر الليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1294).","chapter_en":"The concession for weak women and others to depart from Muzdalifah to Minā in the latter part of the night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":100,"content":{"translation":{"en":["‘Aṭā’ reported from Ibn ‘Abbās, who said: The Messenger of Allah ﷺ sent me at dawn from Jam‘ with the baggage and family of the Prophet ﷺ.","Ibn Jurayj said: I asked him, “Has it reached you that Ibn ‘Abbas said: He sent me in the latter part of the night?” He said: “No, only as stated: at dawn.” I asked him: “Did Ibn ‘Abbas say: We stoned the Jamrah before dawn? And where did he pray Fajr?” He said: “No, only as stated.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1294}]},{"num":5157,"demo":false,"sanad":"","matn":["عن سالم بن شوّال - مولى أم حبيبة - أنه دخل على أم حبيبة فأخبرته، أنّ النبيَّ ﷺ بعث بها من جمعٍ بليل."],"takhrij":"صحيح: رواه مسلم (١٢٩٢). ورواه أيضًا عن أم حبيبة قالت: (( كنا نفعله على عهد النبيّ ﷺ، نُغَلِّس من جمعٍ إلى منى )).","grade":"صحيح","chapter_ar":"باب الرخصة للضعفة من النساء وغيرهن في الدفع من مزدلفة إلى منى في آخر الليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1292). Muslim also narrated from Umm Ḥabībah that she said: “We used to do that during the time of the Prophet ﷺ, departing in the darkness before dawn from Jam‘ to Minā.”","chapter_en":"The concession for weak women and others to depart from Muzdalifah to Minā in the latter part of the night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":100,"content":{"translation":{"en":["Sālim ibn Shawwāl — the freedman of Umm Ḥabībah — reported that he entered upon Umm Ḥabībah, and she informed him that the Prophet ﷺ had sent her from Jam‘ at night."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1292}]},{"num":5158,"demo":false,"sanad":"","matn":["عن الفضل: أنّ النبيَّ ﷺ أمر ضعفةَ بني هاشم أن ينفروا من جمعٍ بليل."],"takhrij":"حسن: رواه النسائيّ (٣٠٣٧)، وأحمد (١٨١١)، وأبو يعلى (٦٧٣٤).","grade":"حسن","chapter_ar":"باب الرخصة للضعفة من النساء وغيرهن في الدفع من مزدلفة إلى منى في آخر الليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (3037), Aḥmad (1811), and Abū Ya‘lā (6734).","chapter_en":"The concession for weak women and others to depart from Muzdalifah to Minā in the latter part of the night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":100,"content":{"translation":{"en":["Al-Faḍl reported that the Prophet ﷺ instructed the weak among Banū Hāshim to depart from Jam‘ at night."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":3037},{"key":"ابو_یعلی","label":"أبو يعلى","number":6734},{"key":"ahmad","label":"مسند الإمام أحمد","number":1811,"n":1811},{"key":"sh12520","label":"مسند أبي يعلى","number":6725,"n":6731}]},{"num":5159,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر، أنّ النبيَّ ﷺ أذن لضعفة الناس من المزدلفة بليل."],"takhrij":"صحيح: رواه أحمد (٤٨٩٢)، والنسائي في الكبرى (٤٠٣٧).","grade":"صحيح","chapter_ar":"باب الرخصة للضعفة من النساء وغيرهن في الدفع من مزدلفة إلى منى في آخر الليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (4892) and al-Nasā’ī in al-Kubrā (4037).","chapter_en":"The concession for weak women and others to depart from Muzdalifah to Minā in the latter part of the night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":100,"content":{"translation":{"en":["‘Abdullāh ibn ‘Umar reported that the Prophet ﷺ gave permission to the weak among the people to leave Muzdalifah at night."]}},"tuhfa":{},"refs":[{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":4037},{"key":"ahmad","label":"مسند الإمام أحمد","number":4892,"n":4892}]},{"num":5160,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: رمى رسولُ اللّٰه ﷺ الجمرة يوم النحر ضحى، وأما بعد فإذا زالت الشمس."],"takhrij":"صحيح: رواه مسلم (٣١٤ : ١٢٩٩).","grade":"صحيح","chapter_ar":"باب الوقت المختار لرمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1299:314).","chapter_en":"The preferred time for stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":101,"content":{"translation":{"en":["Jābir ibn ‘Abdullāh said: The Messenger of Allah ﷺ stoned the Jamrah on the Day of Sacrifice in the forenoon, and after that, it was when the sun had passed the zenith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":314}]},{"num":5161,"demo":false,"sanad":"","matn":["عن أم الحصين، قالت: حججتُ مع رسول اللّٰه ﷺ حجّة الوداع، فرأيتُ أسامة وبلالًا، وأحدهما آخذٌ بخطام ناقة النبيّ ﷺ، والآخر رافعٌ ثوبه يستره من الحرِّ، حتى رمى جمرة العقبة."],"takhrij":"صحيح: رواه مسلم (٣١٢ : ١٢٩٨).","grade":"صحيح","chapter_ar":"باب الوقت المختار لرمي جمرة العقبة يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1298:312).","chapter_en":"The preferred time for stoning Jamrat al-‘Aqabah on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":101,"content":{"translation":{"en":["Umm al-Ḥuṣayn said: I performed Hajj with the Messenger of Allah ﷺ in the Farewell Pilgrimage, and I saw Usāmah and Bilāl: one of them was holding the rein of the Prophet’s camel, and the other was raising his garment to shade him from the heat, until he stoned Jamrat al-‘Aqabah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":312}]},{"num":5162,"demo":false,"sanad":"","matn":["عن عبد الله مولى أسماء، قال: قالت لي أسماء - وهي عند دار المزدلفة -: هل غاب القمر؟ قلت: لا. فصلّت ساعة، ثم قالت: يا بنيّ، هل غاب القمر؟ قلت: نعم. قالت: ارحل بي. فارتحلنا حتى رمت الجمرة، ثم صلّت في منزلها. فقلت لها: أي هنتاه، لقد غلَّسنا! قالت: كلا أي بنيّ، إنّ النبيَّ ﷺ أذن للظُّعُن."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٧٩)، ومسلم (١٢٩١)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الرخصة للضعفة أن يرموا في آخر الليل قبل طلوع الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1679) and Muslim (1291), and the wording is that of Muslim.","chapter_en":"The concession for the weak to stone in the latter part of the night before sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":102,"content":{"translation":{"en":["‘Abdullāh, the freedman of Asmā’, said: Asmā’ said to me while she was at the house in Muzdalifah: “Has the moon set?” I said: No. So she prayed for a while, then said: “My son, has the moon set?” I said: Yes. She said: “Then saddle up for me.” So we set out until she stoned the Jamrah, then she prayed in her lodging. I said to her: “O my aunt, we have come very early in darkness!” She said: “No, my son. The Prophet ﷺ gave permission to the women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1679},{"key":"muslim","label":"مسلم","number":1291}]},{"num":5163,"demo":false,"sanad":"","matn":["عن ابن شهاب، أنّ سالم بن عبد الله أخبره: أنّ عبد الله بن عمر كان يقدِّم ضعفة أهله، فيقفون عند المشعر الحرام بالمزدلفة بالليل، فيذكرون الله ما بدا لهم، ثم يدفعون قبل أن يقف الإمام، وقبل أن يدفع. فمنهم من يقدُم منى لصلاة الفجر، ومنهم من يقدُم بعد ذلك، فإذا قدموا رموا الجمرة. وكان ابن عمر يقول: أرخص في أولئك رسولُ اللّٰه ﷺ."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٧٦)، ومسلم (١٢٩٥)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الرخصة للضعفة أن يرموا في آخر الليل قبل طلوع الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1676) and Muslim (1295), and the wording is that of Muslim.","chapter_en":"The concession for the weak to stone in the latter part of the night before sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":102,"content":{"translation":{"en":["Ibn Shihāb reported that Sālim ibn ‘Abdullāh informed him that ‘Abdullāh ibn ‘Umar used to send forward the weak members of his family. They would stand at al-Mash‘ar al-Ḥarām in Muzdalifah during the night, remembering Allah as much as they wished, then they would depart before the imam stood there and before he departed. Some of them would arrive at Minā in time for the Fajr prayer, and some would arrive after that. When they arrived, they would stone the Jamrah. Ibn ‘Umar used to say: The Messenger of Allah ﷺ gave concession to those people."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1676},{"key":"muslim","label":"مسلم","number":1295}]},{"num":5164,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أرسلني رسولُ اللّٰه ﷺ في ضعفة أهله، فصلّينا الفجر بمنى ورمينا الجمرة."],"takhrij":"صحيح: رواه النسائيّ (٣٠٤٨)، وأحمد (٢٤٦٠).","grade":"صحيح","chapter_ar":"باب الرخصة للضعفة أن يرموا في آخر الليل قبل طلوع الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3048) and Aḥmad (2460).","chapter_en":"The concession for the weak to stone in the latter part of the night before sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":102,"content":{"translation":{"en":["Ibn ‘Abbās said: The Messenger of Allah ﷺ sent me with the weak members of his household, and we prayed Fajr in Minā and stoned the Jamrah."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":3048},{"key":"ahmad","label":"مسند الإمام أحمد","number":2460,"n":2460}]},{"num":5165,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أنّ النبيَّ ﷺ قدَّم ضعفة أهله وقال: (( لا ترموا الجمرة حتى تطلع الشمس ))."],"takhrij":"حسن: رواه الترمذيّ (٨٩٣). قال الترمذي: (( حسن صحيح )).","grade":"حسن","chapter_ar":"باب من كره الرمي قبل طلوع الشمس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (893). Al-Tirmidhī said: “Hasan Sahih.”","chapter_en":"Those who disliked stoning before sunrise","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":103,"content":{"translation":{"en":["‘Abdullāh ibn ‘Abbās reported that the Prophet ﷺ sent forward the weak members of his household and said: “Do not stone the Jamrah until the sun rises.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":893}]},{"num":5166,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: سئل النبيُّ ﷺ فقال: رميتُ بعد ما أمسيتُ؟ فقال: (( لا حرج ))."],"takhrij":"صحيح: رواه البخاريّ (١٧٢٣).","grade":"صحيح","chapter_ar":"باب جواز الرمي مساءً","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1723).","chapter_en":"The permissibility of stoning in the evening","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":104,"content":{"translation":{"en":["Ibn ‘Abbās said: The Prophet ﷺ was asked, “I stoned after evening had come,” and he said: “There is no harm.”"]},"buhuth":{"ar":["فيه نقل وقت الرمي المختار إلى وقت الجواز. والظاهر من السؤال أنه كان في يوم النحر؛ لأنّ الوقت المختار هو قبل الزوال، فرفع النبيُّ ﷺ الحرج عمّن رماه مساءً، ويقاس عليه من رماه ليلًا لاشتراك جزء من المساء في الليل."],"en":["This indicates a transfer from the preferred time of stoning to a merely permissible time. The apparent meaning of the question is that it was on the Day of Sacrifice, because the preferred time is before the sun declines. So the Prophet ﷺ removed hardship from the one who stoned in the evening, and by analogy the same applies to one who stones at night, since part of the evening belongs to the night."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1723}]},{"num":5167,"demo":false,"sanad":"","matn":["عن الفضل بن عباس - وكان رديفَ رسول اللّٰه ﷺ - أنه قال في عشيّة عرفة وغداة جمع للناس حين دفعوا: (( عليكم بالسكينة )) وهو كافٌّ ناقته، حتى دخل محسِّرًا - وهو من منى - قال: (( عليكم بحصى الخذف الذي يُرمى به الجمرة )). وقال: لم يزل رسولُ اللّٰه ﷺ يلبّي حتى رمى الجمرة."],"takhrij":"صحيح: رواه مسلم (١٢٨٢).","grade":"صحيح","chapter_ar":"باب التقاط الحصى لرمي الجمرات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1282).","chapter_en":"Picking up the pebbles for stoning the pillars","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":105,"content":{"translation":{"en":["Al-Faḍl ibn ‘Abbās — and he was riding behind the Messenger of Allah ﷺ — said that on the evening of ‘Arafah and the morning of Jam‘, as the people departed, he said: “Remain calm,” while restraining his camel, until he entered Muḥassir — which is part of Minā — and then said: “Use the pebbles of slinging with which the Jamrah is stoned.” And he said: The Messenger of Allah ﷺ continued making the talbiyah until he stoned the Jamrah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1282}]},{"num":5168,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس قال: قال لي رسولُ اللّٰه ﷺ غداة العقبة وهو على راحلته: (( هاتِ، الْقُطْ لي )). فلقطتُ له حصياتٍ هنَّ حصى الخذف، فلما وضعتهن في يده قال: (( بأمثال هؤلاء، وإيّاكم والغلوَّ في الدين، فإنما أهلك من كان قبلكم الغلوُّ في الدين ))."],"takhrij":"صحيح: رواه النسائيّ (٣٠٥٧)، وابن ماجه (٣٠٢٩)، وصحّحه ابن خزيمة (٢٨٦٧)، وابن حبان (٣٨٧١).","grade":"صحيح","chapter_ar":"باب التقاط الحصى لرمي الجمرات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3057) and Ibn Mājah (3029), and authenticated by Ibn Khuzaymah (2867) and Ibn Ḥibbān (3871).","chapter_en":"Picking up the pebbles for stoning the pillars","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":105,"content":{"translation":{"en":["‘Abdullāh ibn ‘Abbās said: The Messenger of Allah ﷺ said to me on the morning of al-‘Aqabah while he was on his mount: “Come, pick some pebbles for me.” So I picked up for him pebbles that were like the pebbles used in slinging. When I placed them in his hand, he said: “Like these. And beware of excessiveness in religion, for those before you were only destroyed by excessiveness in religion.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":3057},{"key":"ibnmajah","label":"ابن ماجه","number":3029},{"key":"صححہ_ابن_خزیمہ","label":"صحّحه ابن خزيمة","number":2867},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5470,"n":5466}]},{"num":5169,"demo":false,"sanad":"","matn":["عن ابن عباس، عن الفضل بن عباس - وكان رديف رسول الله ﷺ - أنه قال في عشيّة عرفة وغداة جمع للناس حين دفعوا: (( عليكم بالسكينة ))، وهو كافٌّ ناقته حتى دخل محسِّرًا - وهو من منى - قال: (( عليكم بحصى الخذف الذي يرمى به الجمرة )). وقال: لم يزل رسول الله ﷺ يلبي حتى رمى الجمرة."],"takhrij":"صحيح: رواه مسلم (١٢٨٢).","grade":"صحيح","chapter_ar":"باب بيان أنّ حصى الجمار مثل حصى الخذف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1282).","chapter_en":"Clarifying that the pebbles for stoning the pillars are like the pebbles used for slinging","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":106,"content":{"translation":{"en":["Ibn Abbas narrated from al-Fadl ibn Abbas — and he was riding behind the Messenger of Allah ﷺ — that he said on the evening of Arafah and the morning of Muzdalifah, when the people set out: “Remain calm,” while he was holding back his camel, until he entered Muhassir — which is part of Mina — then he said: “Use pebbles like the pebbles used for slinging, which are used to stone the pillar.” And he said: The Messenger of Allah ﷺ continued reciting the talbiyah until he stoned the pillar."]},"buhuth":{"ar":["قوله: (( بحصى الخذف )) وهي نحو حبّة الباقلاء، والخذف أن يجعل الحصاة بين الإبهام والسبابة ثم يقذفها بالإبهام."],"en":["His statement, “with pebbles of slinging,” means pebbles about the size of a broad bean. Slinging means placing the pebble between the thumb and forefinger, then flicking it with the thumb."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1282}]},{"num":5170,"demo":false,"sanad":"","matn":["عن جابر قال: رأيتُ النبيَّ ﷺ يرمي الجمرة بمثل حصى الخذف."],"takhrij":"صحيح: رواه مسلم (١٢٩٩).","grade":"صحيح","chapter_ar":"باب بيان أنّ حصى الجمار مثل حصى الخذف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1299).","chapter_en":"Clarifying that the pebbles for stoning the pillars are like the pebbles used for slinging","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":106,"content":{"translation":{"en":["Jabir said: I saw the Prophet ﷺ stone the pillar with pebbles like the pebbles used for slinging."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1299}]},{"num":5171,"demo":false,"sanad":"","matn":["عن أمِّ جندب الأزديّة، أنّها سمعت النبيَّ ﷺ حيث أفاض قال: (( يا أيُّها الناس، عليكم بالسكينة والوقار، وعليكم بمثل حصى الخذف ))."],"takhrij":"حسن: رواه الإمام أحمد (٢٣٢١٩)، وأبو داود (١٩٦٨، ١٩٦٧، ١٩٦٦)، وابن ماجه (٣٠٢٨).","grade":"حسن","chapter_ar":"باب بيان أنّ حصى الجمار مثل حصى الخذف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (23219), Abu Dawud (1968, 1967, 1966), and Ibn Majah (3028).","chapter_en":"Clarifying that the pebbles for stoning the pillars are like the pebbles used for slinging","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":106,"content":{"translation":{"en":["Umm Jundub al-Azdiyyah narrated that she heard the Prophet ﷺ, when he departed, say: “O people, keep to calmness and dignity, and use pebbles like the pebbles used for slinging.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":23219},{"key":"abudawud","label":"أبو داود","number":1968},{"key":"ibnmajah","label":"ابن ماجه","number":3028},{"key":"ahmad","label":"مسند الإمام أحمد","number":23219,"n":23219}]},{"num":5172,"demo":false,"sanad":"","matn":["عن الهرماس بن زياد، قال: رأيت النبيَّ ﷺ وأنا رديف أبي، وهو على ناقته العضباء يوم الأضحى والناس حوله. فقلت لأبي: ما يقول رسول الله ﷺ؟ قال: يقول: (( ارموا الجمار بمثل حصى الخذف ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٢٢/٢٠٣).","grade":"حسن","chapter_ar":"باب بيان أنّ حصى الجمار مثل حصى الخذف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (22/203).","chapter_en":"Clarifying that the pebbles for stoning the pillars are like the pebbles used for slinging","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":106,"content":{"translation":{"en":["Al-Hirmas ibn Ziyad said: I saw the Prophet ﷺ while I was riding behind my father, and he was on his she-camel al-‘Adba’ on the Day of Sacrifice, with the people around him. I said to my father: What is the Messenger of Allah ﷺ saying? He said: He is saying: “Stone the pillars with pebbles like the pebbles used for slinging.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":22}]},{"num":5173,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن عثمان التيميّ، قال: أمرنا رسول الله ﷺ أن نرمي الجمار بمثل حصى الخذف في حجّة الوداع."],"takhrij":"حسن: رواه الدارمي (١٩٣٩)، وابن أبي عاصم في الآحاد والمثاني (٦٧٥)، وابن قانع في معجم الصحابة (٦٣٦).","grade":"حسن","chapter_ar":"باب بيان أنّ حصى الجمار مثل حصى الخذف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (1939), Ibn Abi Asim in al-Ahad wa al-Mathani (675), and Ibn Qani‘ in Mu‘jam al-Sahabah (636).","chapter_en":"Clarifying that the pebbles for stoning the pillars are like the pebbles used for slinging","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":106,"content":{"translation":{"en":["Abd al-Rahman ibn Uthman al-Taymi said: The Messenger of Allah ﷺ commanded us in the Farewell Pilgrimage to stone the pillars with pebbles like the pebbles used for slinging."]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_عاصم/الاحاد_والمثانی","label":"ابن أبي عاصم في الآحاد والمثاني","number":675},{"key":"ابن_قانع/معجم_الصحابہ","label":"ابن قانع في معجم الصحابة","number":636},{"key":"darimi","label":"سنن الدارمي","number":1843,"n":1843}]},{"num":5174,"demo":false,"sanad":"","matn":["عن الأعمش، قال: سمعت الحجاج بن يوسف يقول - وهو يخطب على المنبر -: ألّفوا القرآن كما ألّفه جبريل: السورة التي يُذكر فيها البقرة، والسورة التي يُذكر فيها النساء، والسورة التي يُذكر فيها آل عمران.","قال: فلقيتُ إبراهيم فأخبرته بقوله، فسبَّه وقال: حدّثني عبد الرحمن بن يزيد أنه كان مع عبد الله بن مسعود، فأتى جمرة العقبة، فاستبطن الوادي، فاستعرضها، فرماها من بطن الوادي بسبع حصيات يكبّر مع كل حصاة. قال: فقلت: يا أبا عبد الرحمن، إنّ الناس يرمونها من فوقها؟ فقال: هذا والذي لا إله غيره مقام الذي أُنزلت عليه سورة البقرة."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٥٠)، ومسلم (١٢٩٦/٣٠٦)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب بيان أن الجمار تُرمى بسبع حصيات يكبّر مع كلّ حصاة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1750) and Muslim (1296/306), and the wording is Muslim’s.","chapter_en":"Clarifying that the pillars are stoned with seven pebbles, saying “Allah is the Greatest” with each pebble","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":107,"content":{"translation":{"en":["Al-A‘mash said: I heard al-Hajjaj ibn Yusuf say while he was preaching from the pulpit: “Arrange the Qur’an as Jibril arranged it: the chapter in which the cow is mentioned, the chapter in which women are mentioned, and the chapter in which the family of Imran is mentioned.”","He said: Then I met Ibrahim and informed him of what he had said, so he insulted him and said: Abd al-Rahman ibn Yazid narrated to me that he was with Abd Allah ibn Mas‘ud, and he came to Jamrat al-‘Aqabah, went into the valley, positioned himself facing it, and stoned it from the bottom of the valley with seven pebbles, saying “Allah is the Greatest” with each pebble. I said: O Abu Abd al-Rahman, people stone it from above it. He said: By the One besides whom there is no god, this is the place of the one upon whom Surat al-Baqarah was sent down."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1750},{"key":"muslim","label":"مسلم","number":1296}]},{"num":5175,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: حتى أتى الجمرة التي عند الشجرة، فرماها بسبع حصيات، يكبّر مع كلِّ حصاةٍ منها… الحديث."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب بيان أن الجمار تُرمى بسبع حصيات يكبّر مع كلّ حصاة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Clarifying that the pillars are stoned with seven pebbles, saying “Allah is the Greatest” with each pebble","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":107,"content":{"translation":{"en":["Jabir ibn Abd Allah said: Then he came to the pillar that was by the tree and stoned it with seven pebbles, saying “Allah is the Greatest” with each pebble from them… the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5176,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن يزيد، أنه حجّ مع ابن مسعود رضي الله عنه فرآه يرمي الجمرة الكبرى بسبع حصيات، فجعل البيت عن يساره ومنى عن يمينه، ثم قال: هذا مقام الذي أُنزلت عليه سورة البقرة ﷺ."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٤٩)، ومسلم (١٢٩٦/٣٠٥).","grade":"متفق عليه","chapter_ar":"باب استقبال جمرة العقبة عند الرمي وجعل الكعبة عن اليسار ومنى عن اليمين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1749) and Muslim (1296/305).","chapter_en":"Facing Jamrat al-‘Aqabah when stoning, with the Ka‘bah to the left and Mina to the right","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":108,"content":{"translation":{"en":["Abd al-Rahman ibn Yazid narrated that he performed Hajj with Ibn Mas‘ud, may Allah be pleased with him, and saw him stone the large pillar with seven pebbles. He placed the House to his left and Mina to his right, then said: This is the place of the one upon whom Surat al-Baqarah was sent down ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1749},{"key":"muslim","label":"مسلم","number":1296}]},{"num":5177,"demo":false,"sanad":"","matn":["عن جابر قال: رأيتُ النبيَّ ﷺ يرمي على راحلته يوم النحر ويقول: (( لتأخذوا مناسككم، فإنّي لا أدري لعلّي لا أحجُّ بعد حجّتي هذه ))."],"takhrij":"صحيح: رواه مسلم (١٢٩٧).","grade":"صحيح","chapter_ar":"باب رمي الجمار راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1297).","chapter_en":"Stoning the pillars while riding and while walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":109,"content":{"translation":{"en":["Jabir said: I saw the Prophet ﷺ stoning while on his mount on the Day of Sacrifice, and he was saying: “Take your rites from me, for I do not know; perhaps I will not perform Hajj after this Hajj of mine.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1297}]},{"num":5178,"demo":false,"sanad":"","matn":["عن يحيى بن حصين، عن جدّته أمّ الحصين، قال: سمعتها تقول: حججتُ مع رسول الله ﷺ حجّة الوداع، فرأيته حين رمى جمرة العقبة وانصرف وهو على راحلته، ومعه بلال وأسامة، أحدهما يقود به راحلته، والآخر رافعٌ ثوبه على رأس رسول الله ﷺ من الشمس. قالت: فقال رسول الله ﷺ قولًا كثيرًا، ثم سمعته يقول: (( إنْ أُمِّر عليكم عبدٌ مُجدَّعٌ - حسبتها قالت: أسود - يقودكم بكتاب الله تعالى، فاسمعوا له وأطيعوا ))."],"takhrij":"صحيح: رواه مسلم (١٢٩٨).","grade":"صحيح","chapter_ar":"باب رمي الجمار راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1298).","chapter_en":"Stoning the pillars while riding and while walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":109,"content":{"translation":{"en":["Yahya ibn Husayn narrated from his grandmother Umm al-Husayn that she said: I heard her say: I performed Hajj with the Messenger of Allah ﷺ in the Farewell Pilgrimage, and I saw him when he stoned Jamrat al-‘Aqabah and departed while on his mount. Bilal and Usamah were with him, one of them leading his mount and the other holding up his garment over the head of the Messenger of Allah ﷺ from the sun. She said: The Messenger of Allah ﷺ spoke many words, then I heard him say: “If a mutilated slave — I think she said: a black slave — is appointed over you and leads you by the Book of Allah, then listen to him and obey him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1298}]},{"num":5179,"demo":false,"sanad":"","matn":["عن قدامة بن عبد الله، قال: رأيت النبيَّ ﷺ يرمي الجمار على ناقة. وفي رواية: على ناقةٍ له صهباء، ليس ضربٌ ولا طردٌ، ولا إليك إليك."],"takhrij":"حسن: رواه الترمذيّ (٩٠٣)، والنسائيّ (٣٠٦١)، وابن ماجه (٣٠٣٥). قال الترمذي: (( حسن صحيح )).","grade":"حسن","chapter_ar":"باب رمي الجمار راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (903), al-Nasa’i (3061), and Ibn Majah (3035). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"Stoning the pillars while riding and while walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":109,"content":{"translation":{"en":["Qudamah ibn Abd Allah said: I saw the Prophet ﷺ stone the pillars while on a she-camel. In another narration: on a reddish she-camel of his. There was no striking, no driving away, and no shouting, “Move aside, move aside.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":903},{"key":"nasai","label":"النسائيّ","number":3061},{"key":"ibnmajah","label":"ابن ماجه","number":3035}]},{"num":5180,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ النبيَّ ﷺ كان إذا رمى الجمار مشى إليها ذاهبًا وراجعًا."],"takhrij":"صحيح: رواه الترمذيّ (٩٠٠) وقال: (( حسن صحيح )).","grade":"صحيح","chapter_ar":"باب رمي الجمار راكبًا وماشيًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (900), who said: “Hasan Sahih.”","chapter_en":"Stoning the pillars while riding and while walking","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":109,"content":{"translation":{"en":["Ibn Umar narrated that the Prophet ﷺ, when he stoned the pillars, would walk to them going and returning."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":900}]},{"num":5181,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله: أنّ عبد الله بن عمر رضي الله عنهما كان يرمي الجمرة الدنيا بسبع حصيات، ثم يكبِّر على إثر كلّ حصاة، ثم يتقدم فيُسهل، فيقوم مستقبل القبلة قيامًا طويلًا فيدعو ويرفع يديه، ثم يرمي الجمرة الوسطى كذلك، فيأخذ ذات الشمال فيُسهل، ويقوم مستقبل القبلة قيامًا طويلًا فيدعو ويرفع يديه، ثم يرمي جمرة ذات العقبة من بطن الوادي ولا يقف عندها ويقول: هكذا رأيت رسول الله ﷺ يفعل."],"takhrij":"صحيح: رواه البخاريّ (١٧٥٢).","grade":"صحيح","chapter_ar":"باب رفع اليدين بالدعاء عند الجمرتين الدنيا والوسطى دون جمرة العقبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1752).","chapter_en":"Raising the hands in supplication at the first and middle pillars, but not at Jamrat al-‘Aqabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":110,"content":{"translation":{"en":["Salim ibn Abd Allah narrated that Abd Allah ibn Umar, may Allah be pleased with them both, used to stone the first pillar with seven pebbles, then say “Allah is the Greatest” after each pebble. Then he would go forward to open ground and stand facing the qiblah for a long time, supplicating and raising his hands. Then he would stone the middle pillar in the same way, then go to the left side into open ground, and stand facing the qiblah for a long time, supplicating and raising his hands. Then he would stone Jamrat al-‘Aqabah from the bottom of the valley and would not stop there, and he would say: “This is how I saw the Messenger of Allah ﷺ do.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1752}]},{"num":5182,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسول الله ﷺ: (( إذا رميت الجمار كان لك نورًا يوم القيامة ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١١٤٠).","grade":"حسن","chapter_ar":"باب ما جاء في فضل الرمي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1140).","chapter_en":"What has been reported regarding the virtue of stoning","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":111,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “When you stone the pillars, it will be a light for you on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1140},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1140,"n":1140}]},{"num":5183,"demo":false,"sanad":"","matn":["عن أبي الطفيل قال: قلت لابن عباس: يزعم قومُك أن رسول الله ﷺ رمل بالبيت وأنّ ذلك سنّة؟ فقال: صدقوا وكذبوا! قلت: وما صدقوا وكذبوا؟ قال: صدقوا، رمل رسول الله ﷺ بالبيت، وكذبوا، ليس بسنّة؛ إن قريشًا قالت زمن الحديبية: دعوا محمدًا وأصحابه حتى يموتوا موت النغف، فلما صالحوه على أن يقدموا من العام المقبل ويقيموا بمكة ثلاثة أيام، فقدم رسول الله ﷺ والمشركون من قبل قعيقعان، فقال رسول الله ﷺ لأصحابه: (( ارملوا بالبيت ثلاثًا )) وليس بسنّة.","قلت: ويزعم قومك أنه طاف بين الصفا والمروة على بعير وأنّ ذلك سنّة؟ فقال: صدقوا وكذبوا! فقلت: وما صدقوا وكذبوا؟ فقال: صدقوا، قد طاف بين الصفا والمروة على بعير، وكذبوا، ليست بسنّة؛ كان الناس لا يُدفعون عن رسول الله ﷺ ولا يُصرفون عنه، فطاف على بعير ليسمعوا كلامه، ولا تناله أيديهم.","قلت: ويزعم قومك أنّ رسول الله ﷺ سعى بين الصفا والمروة وأنّ ذلك سنّة؟ قال: صدقوا؛ إن إبراهيم لما أُمر بالمناسك عرض له الشيطان عند المسعى فسابقه فسبقه إبراهيم، ثم ذهب به جبريل إلى جمرة العقبة فعرض له شيطان - قال يونس: الشيطان - فرماه بسبع حصيات حتى ذهب، ثم عرض له عند الجمرة الوسطى فرماه بسبع حصيات. قال: قد تله للجبين - قال يونس: ثم تله للجبين - وعلى إسماعيل قميصٌ أبيض، وقال: يا أبتِ، إنّه ليس لي ثوب تكفّنني فيه غيره، فاخلعه حتى تكفّنني فيه.","فعالجه ليخلعه، فنودي من خلفه: ( أَن يَا إِبْرَاهِيمُ ۝ قَدْ صَدَّقْتَ الرُّؤْيَا ) [الصافات: ١٠٤-١٠٥].","فالتفت إبراهيم فإذا هو بكبش أبيض أقرن أعين.","قال ابن عباس: لقد رأيتُنا نتتبّع هذا الضرب من الكباش. قال: ثم ذهب به جبريل إلى الجمرة القصوى فعرض له الشيطان فرماه بسبع حصيات حتى ذهب، ثم ذهب به جبريل إلى منى، قال: هذا منى - قال يونس: هذا مناخ الناس - ثم أتى به جمعًا، فقال: هذا المشعر الحرام، ثم ذهب به إلى عرفة.","فقال ابن عباس: هل تدري لِمَ سميت عرفة؟ قلت: لا. قال: إن جبريل قال لإبراهيم: عرفت؟ - قال يونس: هل عرفت؟ - قال: نعم. قال ابن عباس: فمن ثم سميت عرفة. ثم قال: هل تدري كيف كانت التلبية؟ قلت: وكيف كانت؟ قال: إن إبراهيم لما أُمر أن يؤذّن في الناس بالحج خفضت له الجبال رؤوسها، ورُفعت له القرى، فأذّن في الناس بالحج."],"takhrij":"حسن: رواه الإمام أحمد (٢٧٠٧)، وأبو داود الطيالسيّ (٢٨٢٠).","grade":"حسن","chapter_ar":"باب ما جاء في سبب رمي الجمرات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (2707) and Abu Dawud al-Tayalisi (2820).","chapter_en":"What has been reported regarding the reason for stoning the pillars","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":112,"content":{"translation":{"en":["Abu al-Tufayl said: I said to Ibn Abbas: Your people claim that the Messenger of Allah ﷺ performed ramal around the House and that this is a Sunnah. He said: They spoke the truth and they were mistaken. I said: What do you mean by that? He said: They spoke the truth that the Messenger of Allah ﷺ performed ramal around the House, and they were mistaken in saying it is an established Sunnah. Quraysh said at the time of al-Hudaybiyah: Leave Muhammad and his companions until they die the death of infestation. Then when they made peace with him, allowing him to come the following year and stay in Makkah for three days, the Messenger of Allah ﷺ came while the polytheists were on the side of Qu‘ayqi‘an, so the Messenger of Allah ﷺ said to his companions: “Perform ramal around the House for three circuits,” and it was not a permanent Sunnah.","I said: And your people claim that he went between al-Safa and al-Marwah on a camel and that this is a Sunnah? He said: They spoke the truth and they were mistaken. I said: What do you mean? He said: They spoke the truth that he did go between al-Safa and al-Marwah on a camel, and they were mistaken that it is a Sunnah. The people would not be pushed away from the Messenger of Allah ﷺ, nor turned back from him, so he went on a camel so they could hear his words and their hands could not reach him.","I said: And your people claim that the Messenger of Allah ﷺ performed sa‘y between al-Safa and al-Marwah and that this is a Sunnah? He said: They spoke the truth. When Ibrahim was commanded with the rites, Satan confronted him at the place of sa‘y, so he raced him and Ibrahim outran him. Then Jibril took him to Jamrat al-‘Aqabah, and a devil appeared to him — Yunus said: Satan — so he stoned him with seven pebbles until he went away. Then he appeared to him at the middle pillar, and he stoned him with seven pebbles. He said: Then he laid him down on his forehead — Yunus said: then he laid him down on his forehead — and Isma‘il wore a white shirt and said: “My father, I have no garment other than this in which I may be shrouded, so remove it until you shroud me in it.”","So he began trying to remove it, and then he was called from behind: “O Abraham, you have fulfilled the vision.” [al-Saffat 104–105]","Then Ibrahim turned and saw a white horned ram with dark eyes.","Ibn Abbas said: I remember us searching for this kind of ram. Then Jibril took him to the furthest pillar, and Satan appeared to him there, so he stoned him with seven pebbles until he went away. Then Jibril took him to Mina and said: This is Mina — Yunus said: this is where the people camp — then he brought him to Muzdalifah and said: This is the Sacred Monument, then he took him to Arafah.","Then Ibn Abbas said: Do you know why Arafah was named Arafah? I said: No. He said: Jibril said to Ibrahim: “Have you recognized it?” — Yunus said: “Did you recognize it?” — He said: Yes. Ibn Abbas said: That is why it was named Arafah. Then he said: Do you know how the talbiyah began? I said: How was it? He said: When Ibrahim was commanded to proclaim the pilgrimage among the people, the mountains lowered their heads for him and the towns were raised for him, so he proclaimed the pilgrimage to the people."]},"buhuth":{"ar":["قوله: (( النغف )) بالتحريك، دودٌ يكون في أنوف الإبل والغنم، واحدتها نغفة. النهاية (٨٧/٥)."],"en":["His statement, “al-naghaf,” with vowelization, refers to worms that are found in the noses of camels and sheep. Its singular is naghafah. Al-Nihayah (5/87)."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":2707},{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسيّ","number":2820},{"key":"ahmad","label":"مسند الإمام أحمد","number":2707,"n":2707}]},{"num":5184,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أنّ رسول الله ﷺ قال: (( إنّ جبريل ذهب بإبراهيم إلى جمرة العقبة، فعرض له الشيطان فرماه بسبع حصيات، فساخ، ثم أتى به الجمرة الوسطى، فعرض له الشيطان فرماه بسبع حصيات فساخ، ثم أتى به الجمرة القصوى فعرض له الشيطان فرماه بسبع حصيات فساخ، فلما أراد إبراهيم أن يذبح ابنه إسحاق قال لأبيه: يا أبتِ، أوثقني لا أضطرب فينتضح عليك من دمي إذا ذبحتني فشدّه، فلما أخذ الشفرة فأراد أن يذبحه نودي من خلفه: ( أَن يَا إِبْرَاهِيمُ ۝ قَدْ صَدَّقْتَ الرُّؤْيَا ) [الصافات: ١٠٤-١٠٥] ))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٧٩٤).","grade":"صحيح","chapter_ar":"باب ما جاء في سبب رمي الجمرات","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (2794).","chapter_en":"What has been reported regarding the reason for stoning the pillars","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":112,"content":{"translation":{"en":["Abd Allah ibn Abbas narrated that the Messenger of Allah ﷺ said: “Jibril took Ibrahim to Jamrat al-‘Aqabah, and Satan appeared to him, so he stoned him with seven pebbles and he sank. Then he brought him to the middle pillar, and Satan appeared to him, so he stoned him with seven pebbles and he sank. Then he brought him to the furthest pillar, and Satan appeared to him, so he stoned him with seven pebbles and he sank. Then when Ibrahim intended to sacrifice his son Ishaq, he said to his father: ‘My father, tie me firmly so that I do not move and my blood does not splash on you when you slaughter me,’ so he tied him. Then when he took the blade and intended to slaughter him, he was called from behind: ‘O Abraham, you have fulfilled the vision.’” [al-Saffat 104–105]"]},"buhuth":{"ar":["وفي قوله: (( إسحاق )) دليل على عدم ضبط الراوي اسمَ الذبيح؛ لأنّ الصحيح الثابت عند جمهور أهل العلم أن الذبيح هو إسماعيل عليه السلام، وعليه يدلّ مفهوم القرآن في اسم الذبيح.","وقد فصّلتُ القول في كتابي: \"الدراسات في اليهودية والمسيحية وأديان الهند\" فراجعْه، فإنك تجد فيه ما لم تجد في مكان آخر."],"en":["And in his saying, “Ishaq,” there is evidence that the narrator did not precisely preserve the name of the intended sacrifice, because the sound and established position held by the majority of the scholars is that the intended sacrifice was Isma‘il, peace be upon him, and the implication of the Qur’an indicates this.","I have discussed this matter in detail in my book “Studies in Judaism, Christianity, and the Religions of India”; refer to it, for you will find there what you will not find elsewhere."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":2794},{"key":"ahmad","label":"مسند الإمام أحمد","number":2794,"n":2794}]},{"num":5185,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أنّ رسول الله ﷺ لما حلق رأسه كان أبو طلحة أوّل من أخذ من شعره."],"takhrij":"متفق عليه: رواه البخاري (١٧١)، ومسلم (١٣٠٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء في حلق رسول الله ﷺ رأسه في حجّة الوداع، وتقسيم شعره بين الناس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (171) and Muslim (1305).","chapter_en":"What has been reported about the Messenger of Allah ﷺ shaving his head in the Farewell Pilgrimage and distributing his hair among the people","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":113,"content":{"translation":{"en":["Anas ibn Malik narrated that when the Messenger of Allah ﷺ shaved his head, Abu Talhah was the first to take some of his hair."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":171},{"key":"muslim","label":"مسلم","number":1305}]},{"num":5186,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: إنّ رسول الله ﷺ حلق رأسه في حجّة الوداع."],"takhrij":"متفق عليه: رواه البخاريّ (٤٤١٠)، ومسلم (١٣٠٤). ورواه ابن خزيمة (٢٩٣٠)، وزاد فيه: (( وزعموا أن الذي حلق النبي ﷺ معمر بن عبد الله بن نضلة بن عوف بن عبيد بن عويج بن عدي بن كعب )).","grade":"متفق عليه","chapter_ar":"باب ما جاء في حلق رسول الله ﷺ رأسه في حجّة الوداع، وتقسيم شعره بين الناس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4410) and Muslim (1304). Ibn Khuzaymah also narrated it (2930), adding: “And they claimed that the one who shaved the Prophet ﷺ was Ma‘mar ibn Abd Allah ibn Nadlah ibn ‘Awf ibn ‘Ubayd ibn ‘Uwayj ibn ‘Adi ibn Ka‘b.”","chapter_en":"What has been reported about the Messenger of Allah ﷺ shaving his head in the Farewell Pilgrimage and distributing his hair among the people","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":113,"content":{"translation":{"en":["Abd Allah ibn Umar said: The Messenger of Allah ﷺ shaved his head in the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4410},{"key":"muslim","label":"مسلم","number":1304},{"key":"ورواہ_ابن_خزیمہ","label":". ورواه ابن خزيمة","number":2930}]},{"num":5187,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أنّ رسول الله ﷺ رمى جمرة العقبة، ثم انصرف إلى البُدن فنحرها، والحجّام جالس وقال بيده عن رأسه، فحلق شقَّه الأيمن فقسمه فيمن يليه، ثم قال: (( احلق الشق الآخر )). فقال: (( أين أبو طلحة؟ )) فأعطاه إيّاه."],"takhrij":"صحيح: رواه مسلم (١٣٠٥)، والبخاريّ (١٧١).","grade":"صحيح","chapter_ar":"باب ما جاء في حلق رسول الله ﷺ رأسه في حجّة الوداع، وتقسيم شعره بين الناس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1305) and al-Bukhari (171).","chapter_en":"What has been reported about the Messenger of Allah ﷺ shaving his head in the Farewell Pilgrimage and distributing his hair among the people","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":113,"content":{"translation":{"en":["Anas ibn Malik narrated that the Messenger of Allah ﷺ stoned Jamrat al-‘Aqabah, then turned to the sacrificial camels and slaughtered them, while the barber was sitting. He gestured with his hand toward his head, so he shaved the right side of it and distributed it among those nearest to him. Then he said: “Shave the other side.” Then he said: “Where is Abu Talhah?” and gave it to him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1305},{"key":"bukhari","label":"البخاريّ","number":171}]},{"num":5188,"demo":false,"sanad":"","matn":["عن معمر بن عبد الله قال: كنت أرحل لرسول الله ﷺ في حجّة الوداع. قال: فقال لي ليلة من الليالي: (( يا معمر، لقد وجدت الليلة في أنساعي اضطرابًا )). قال: فقلت: أما والذي بعثك بالحق لقد شددتها كما كنت أشدُّها، ولكنه أرخاها من قد كان نَفِسَ عليَّ مكاني منك، لتستبدل بي غيري. قال: فقال: (( أما إنّي غير فاعل )). قال: فلما نحر رسول الله ﷺ هديه بمنى أمرني أن أحلقه. قال: فأخذت الموسى فقمت على رأسه. قال: فنظر رسول الله ﷺ في وجهي وقال لي: (( يا معمر، أمكنك رسول الله ﷺ من شحمة أذنه وفي يدك الموسى؟! )). قال: فقلت: أما والله يا رسول الله إنّ ذلك لمن نعمة الله عليَّ ومنِّه. قال: فقال: (( أجلْ إذًا أقِرّ لك )). قال: ثم حلقت رسول الله ﷺ."],"takhrij":"حسن: رواه الإمام أحمد (٢٧٢٤٩)، والطبرانيّ في الكبير (٢٠/٤٤٧-٤٤٨).","grade":"حسن","chapter_ar":"باب ما جاء في حلق رسول الله ﷺ رأسه في حجّة الوداع، وتقسيم شعره بين الناس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (27249) and al-Tabarani in al-Kabir (20/447–448).","chapter_en":"What has been reported about the Messenger of Allah ﷺ shaving his head in the Farewell Pilgrimage and distributing his hair among the people","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":113,"content":{"translation":{"en":["Ma‘mar ibn Abd Allah said: I used to saddle the mount for the Messenger of Allah ﷺ in the Farewell Pilgrimage. He said: One night he said to me: “O Ma‘mar, tonight I found looseness in my straps.” I said: By the One who sent you with the truth, I fastened them just as I used to fasten them, but someone who envied my place with you loosened them so that you might replace me with someone else. He said: “As for me, I will not do that.” Then when the Messenger of Allah ﷺ slaughtered his offering in Mina, he ordered me to shave his head. I took the razor and stood over his head. The Messenger of Allah ﷺ looked into my face and said to me: “O Ma‘mar, the Messenger of Allah ﷺ has enabled you to hold the lobe of his ear while the razor is in your hand?!” I said: By Allah, O Messenger of Allah ﷺ, that is indeed among Allah’s blessings and favors upon me. He said: “Yes, then let it be affirmed for you.” Then I shaved the Messenger of Allah ﷺ."]},"buhuth":{"ar":["وقوله: (( أنساعي )) جمع نِسعة - بكسر النون، وسكون السين - وهي التي تُنسج عريضة ليربط على عجز البعير.","وقوله: (( نَفِس )) بكسر الفاء - كعَلِم - من نَفِسْتُ عليه بالشيء إذا رأيته له أهلًا. أفاده السنديّ."],"en":["His statement, “ansā‘ī,” is the plural of nis‘ah — with the nūn carrying kasrah and the sīn being still — and it means broad woven straps used to tie onto the rear of the camel.","His statement, “nafisa,” with the fa’ carrying kasrah, is from the expression meaning to envy someone for something when you think him worthy of it. This was mentioned by al-Sindi."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":27249},{"key":"الطبرانی/الکبیر","label":"الطبرانيّ في الكبير","number":20},{"key":"ahmad","label":"مسند الإمام أحمد","number":27249,"n":27249}]},{"num":5189,"demo":false,"sanad":"","matn":["عن أنس، قال: لما أراد رسول الله ﷺ أن يحلق الحجام رأسه، أخذ أبو طلحة بشعر أحد شقّي رأسه بيده، فأخذ شعره، فجاء به إلى أمّ سليم. قال: فكانت أمّ سليم تدوفه في طيبها."],"takhrij":"صحيح: رواه الإمام أحمد (١٢٤٨٣).","grade":"صحيح","chapter_ar":"باب ما جاء في حلق رسول الله ﷺ رأسه في حجّة الوداع، وتقسيم شعره بين الناس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (12483).","chapter_en":"What has been reported about the Messenger of Allah ﷺ shaving his head in the Farewell Pilgrimage and distributing his hair among the people","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":113,"content":{"translation":{"en":["Anas said: When the Messenger of Allah ﷺ wanted the barber to shave his head, Abu Talhah took in his hand the hair from one side of his head, then took it and brought it to Umm Sulaym. He said: Umm Sulaym used to mix it into her perfume."]},"buhuth":{"ar":["وقوله: (( تدوفه في طيبها )) أي تخلطه فيه، يقال: دافه بماء يدوفه ويديفه إذا بلّه به وخلطه."],"en":["His statement, “she mixed it into her perfume,” means that she blended it into it. It is said: he mixed it with water, meaning he moistened it with it and blended it."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":12483},{"key":"ahmad","label":"مسند الإمام أحمد","number":12483,"n":12483}]},{"num":5190,"demo":false,"sanad":"","matn":["عن أنس قال: رأيت رسول الله ﷺ والحلاق يحلقه، وقد أطاف به أصحابه، ما يريدون أن تقع شعرة إلا في يد رجل."],"takhrij":"صحيح: رواه مسلم (٢٣٢٥).","grade":"صحيح","chapter_ar":"باب ما جاء في حلق رسول الله ﷺ رأسه في حجّة الوداع، وتقسيم شعره بين الناس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2325).","chapter_en":"What has been reported about the Messenger of Allah ﷺ shaving his head in the Farewell Pilgrimage and distributing his hair among the people","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":113,"content":{"translation":{"en":["Anas said: I saw the Messenger of Allah ﷺ while the barber was shaving him, and his companions had surrounded him, wanting that not a single hair should fall except into the hand of one of the men."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2325}]},{"num":5191,"demo":false,"sanad":"","matn":["عن محمد بن عبد الله بن زيد، أنّ أباه حدّثه: أنه شهد النبيَّ ﷺ عند المنحر، ورجلٌ من قريش، وهو يقسم أضاحي، فلم يصبه منها شيءٌ ولا صاحبَه، فحلق رسولُ الله ﷺ رأسه في ثوبه، فأعطاه فقسم منه على رجال، وقلّم أظفاره فأعطاه صاحبه. قال: فإنه لعندنا مخضوبٌ بالحناء والكتم يعني شعره."],"takhrij":"صحيح: رواه أحمد (١٦٤٧٥، ١٦٤٧٤)، وابن خزيمة (٢٩٣١)، والحاكم (١٧٤٤).","grade":"صحيح","chapter_ar":"باب ما جاء في حلق رسول الله ﷺ رأسه في حجّة الوداع، وتقسيم شعره بين الناس","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (16475, 16474), Ibn Khuzaymah (2931), and al-Hakim (1744).","chapter_en":"What has been reported about the Messenger of Allah ﷺ shaving his head in the Farewell Pilgrimage and distributing his hair among the people","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":113,"content":{"translation":{"en":["Muhammad ibn Abd Allah ibn Zayd narrated that his father told him that he witnessed the Prophet ﷺ at the place of sacrifice, and there was a man from Quraysh while he was distributing sacrificial animals. Neither he nor his companion received any of them. Then the Messenger of Allah ﷺ shaved his head into his garment and gave it to him, so he distributed some of it among men. Then he clipped his nails and gave them to his companion. He said: It is still with us dyed with henna and katam, meaning his hair."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2931},{"key":"hakim","label":"الحاكم","number":1744},{"key":"ahmad","label":"مسند الإمام أحمد","number":16475,"n":16475}]},{"num":5192,"demo":false,"sanad":"","matn":["عن ابن عمر، أنّ رسول الله ﷺ قال: (( اللهمّ ارحم المحلّقين )). قالوا: والمقصّرين يا رسول الله؟ قال: (( اللهمّ ارحم المحلّقين )). قالوا: والمقصّرين يا رسول الله؟ قال: (( والمقصّرين ))."],"takhrij":"متفق عليه: رواه مالك (١٨٤)، والبخاريّ (١٧٢٧)، ومسلم (١٣٠١/٣١٧).","grade":"متفق عليه","chapter_ar":"باب دعاء النبي ﷺ للمحلّقين بالرّحمة ثلاث مرّات وللمقصّرين مرة واحدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (184), al-Bukhari (1727), and Muslim (1301/317).","chapter_en":"The Prophet’s supplication for mercy upon those who shave three times, and upon those who shorten once","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":114,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ said: “O Allah, have mercy on those who shave.” They said: And those who shorten, O Messenger of Allah? He said: “O Allah, have mercy on those who shave.” They said: And those who shorten, O Messenger of Allah? He said: “And those who shorten.”"]},"buhuth":{"ar":["ورواه مسلم بلفظ: (( رحم الله المحلّقين )). قالوا: والمقصّرين يا رسول الله؟ قال: (( رحم الله المحلّقين )). قالوا: والمقصّرين يا رسول الله؟ قال: (( رحم الله المحلّقين )). قالوا: والمقصّرين يا رسول الله؟ قال: (( والمقصّرين ))."],"en":["Muslim also narrated it with the wording: “May Allah have mercy on those who shave.” They said: And those who shorten, O Messenger of Allah? He said: “May Allah have mercy on those who shave.” They said: And those who shorten, O Messenger of Allah? He said: “May Allah have mercy on those who shave.” They said: And those who shorten, O Messenger of Allah? He said: “And those who shorten.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":184},{"key":"bukhari","label":"البخاريّ","number":1727},{"key":"muslim","label":"مسلم","number":1301}]},{"num":5193,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: حلق النبيُّ ﷺ وطائفةٌ من أصحابه، وقصَّر بعضهم."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٢٩)، ومسلم (١٣٠١). وزاد: قال عبد الله بن عمر: إنَّ رسول الله ﷺ قال: (( رحم الله المحلِّقين )) مرة أو مرتين، ثم قال: (( والمقصِّرين )).","grade":"متفق عليه","chapter_ar":"باب دعاء النبي ﷺ للمحلّقين بالرّحمة ثلاث مرّات وللمقصّرين مرة واحدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1729) and Muslim (1301). It also adds: Abdullah ibn Umar said: The Messenger of Allah ﷺ said, “May Allah have mercy on those who shave,” once or twice, then he said, “and those who shorten.”","chapter_en":"The Prophet’s supplication for mercy upon those who shave three times, and upon those who shorten once","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":114,"content":{"translation":{"en":["Abdullah ibn Umar said: The Prophet ﷺ shaved his head, and a group of his companions shaved their heads, while some of them only shortened their hair."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1729},{"key":"muslim","label":"مسلم","number":1301}]},{"num":5194,"demo":false,"sanad":"","matn":["عن ابن عمر، أنَّ النبيَّ ﷺ قال يوم الحديبية: (( اللهم اغفر للمحلِّقين )). فقال رجل: والمقصِّرين؟ فقال: (( اللهم اغفر للمحلِّقين )). فقال: والمقصِّرين؟ قال: حتى قالها ثلاثًا أو أربعًا، قال: (( وللمقصِّرين ))."],"takhrij":"صحيح: رواه الإمام أحمد (٦٣٨٤، ٤٨٩٧). ورواه ابن أبي شيبة (١٤/٤٥٢) من وجه آخر عن ابن عمر ضمن قصة الحديبية، وفيه تصريحٌ بأنه ﷺ قال ذلك يوم الحديبية. كما قال ذلك أيضًا في حجّة الوداع.","grade":"صحيح","chapter_ar":"باب دعاء النبي ﷺ للمحلّقين بالرّحمة ثلاث مرّات وللمقصّرين مرة واحدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (6384, 4897). Ibn Abi Shaybah also narrated it (14/452) through another route from Ibn Umar within the story of al-Hudaybiyah, and it explicitly states that he ﷺ said this on the Day of al-Hudaybiyah. He also said it in the Farewell Pilgrimage.","chapter_en":"The Prophet’s supplication for mercy upon those who shave three times, and upon those who shorten once","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":114,"content":{"translation":{"en":["Ibn Umar narrated that the Prophet ﷺ said on the Day of al-Hudaybiyah: “O Allah, forgive those who shave.” A man said: And those who shorten? So he said: “O Allah, forgive those who shave.” He said: And those who shorten? He said that after saying it three or four times, he said: “And those who shorten.”"]},"buhuth":{"ar":["ولا منافاة بينهما؛ ولذا لا يحتاج إلى الإنكار في إثبات كونه قال ذلك أيضًا يوم الحديبية؛ لأنّ من أنكر ذلك أسند إلى عدم علمه به، وعدم العلم ليس بعلم كما يقال، فإن الصحيح الثابت الذي عليه المحقِّقون أنه قال ذلك أولًا في الحديبية، ثم أعاده في حجّة الوداع كما جاء مصرّحًا أيضًا في حديث أم الحصين الأسلمية الآتي."],"en":["There is no contradiction between the two reports, so there is no need to reject that he also said this on the Day of al-Hudaybiyah. Whoever denies that bases his denial on not knowing it, and lack of knowledge is not knowledge, as is said. The sound and established view held by the verifying scholars is that he first said this at al-Hudaybiyah, then repeated it during the Farewell Pilgrimage, as is also explicitly stated in the upcoming hadith of Umm al-Husayn al-Aslamiyyah."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":6384},{"key":"ورواہ_ابن_ابی_شیبہ","label":". ورواه ابن أبي شيبة","number":14},{"key":"ahmad","label":"مسند الإمام أحمد","number":6384,"n":6384}]},{"num":5195,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله ﷺ: (( اللهم اغفر للمحلِّقين )). قالوا: يا رسول الله، وللمقصِّرين؟ قال: (( اللهم اغفر للمحلِّقين )). قالوا: يا رسول الله، وللمقصِّرين؟ قال: (( اللهم اغفر للمحلِّقين )). قالوا: يا رسول الله، وللمقصِّرين؟ قال: (( وللمقصِّرين ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٢٨)، ومسلم (١٣٠٢). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب دعاء النبي ﷺ للمحلّقين بالرّحمة ثلاث مرّات وللمقصّرين مرة واحدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1728) and Muslim (1302), and the wording is Muslim’s.","chapter_en":"The Prophet’s supplication for mercy upon those who shave three times, and upon those who shorten once","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":114,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “O Allah, forgive those who shave.” They said: O Messenger of Allah, and those who shorten? He said: “O Allah, forgive those who shave.” They said: O Messenger of Allah, and those who shorten? He said: “O Allah, forgive those who shave.” They said: O Messenger of Allah, and those who shorten? He said: “And those who shorten.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1728},{"key":"muslim","label":"مسلم","number":1302}]},{"num":5196,"demo":false,"sanad":"","matn":["عن أم الحصين الأسلمية، أنها سمعت النبيَّ ﷺ في حجّة الوداع دعا للمحلِّقين ثلاثًا، وللمقصِّرين مرّة."],"takhrij":"صحيح: رواه مسلم (١٣٠٣).","grade":"صحيح","chapter_ar":"باب دعاء النبي ﷺ للمحلّقين بالرّحمة ثلاث مرّات وللمقصّرين مرة واحدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1303).","chapter_en":"The Prophet’s supplication for mercy upon those who shave three times, and upon those who shorten once","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":114,"content":{"translation":{"en":["Umm al-Husayn al-Aslamiyyah narrated that she heard the Prophet ﷺ during the Farewell Pilgrimage supplicate three times for those who shaved, and once for those who shortened."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1303}]},{"num":5197,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس قال: حلق رجالٌ يوم الحديبية وقصَّر آخرون، فقال رسول الله ﷺ: (( يرحم الله المحلِّقين )). قالوا: يا رسول الله، والمقصِّرين؟ قال: (( يرحم الله المحلِّقين )). قالوا: يا رسول الله، والمقصِّرين؟ قال: (( يرحم الله المحلِّقين )). قالوا: يا رسول الله، والمقصِّرين؟ قال: (( والمقصِّرين )).","قالوا: فما بالُ المحلِّقين يا رسول الله ظاهرتَ لهم الرحمة؟ قال: (( لم يشكُّوا )). قال: فانصرف رسول الله ﷺ."],"takhrij":"حسن: رواه الإمام أحمد (٣٣١١)، واللفظ له، والطحاويّ في شرح معانيه (٤٠٥٧)، وابن ماجه (٣٠٤٥).","grade":"حسن","chapter_ar":"باب دعاء النبي ﷺ للمحلّقين بالرّحمة ثلاث مرّات وللمقصّرين مرة واحدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (3311), and this is his wording, also by al-Tahawi in Sharh Ma‘anihi (4057), and Ibn Majah (3045).","chapter_en":"The Prophet’s supplication for mercy upon those who shave three times, and upon those who shorten once","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":114,"content":{"translation":{"en":["Abdullah ibn Abbas said: Some men shaved on the Day of al-Hudaybiyah, while others shortened their hair. So the Messenger of Allah ﷺ said: “May Allah have mercy on those who shave.” They said: O Messenger of Allah, and those who shorten? He said: “May Allah have mercy on those who shave.” They said: O Messenger of Allah, and those who shorten? He said: “May Allah have mercy on those who shave.” They said: O Messenger of Allah, and those who shorten? He said: “And those who shorten.”","They said: Why is it, O Messenger of Allah ﷺ, that you singled out those who shave with repeated mercy? He said: “Because they did not doubt.” Then the Messenger of Allah ﷺ departed."]},"buhuth":{"ar":["وقوله: (( ظاهرتَ لهم الرحمة )) أي جمعتَ وكررتَ لهم الرحمة.","وقوله: (( لم يشكُّوا )) أي لم يعاملوا معاملة من يشك في جواز التحلُّل؛ أي من قصَّر فكأنه شكَّ في جواز التحلُّل حتى اقتصر في التحلُّل على بعضه، وأما من حلق فلا شكَّ منه؛ أي لم يعاملوا معاملة من يشك في أن الاتباع أحسن، وأما من قصَّر فقد عامله معاملة الشاك في ذلك حيث ترك الأفضل. قاله السنديّ في حاشية المسند."],"en":["His saying, “you singled them out with repeated mercy,” means that you gathered and repeated mercy for them.","His saying, “they did not doubt,” means that they did not act like one who doubts whether it is permissible to exit the state of consecration. The one who shortened his hair acted as though he hesitated about full completion, so he limited his release to only part of it. As for the one who shaved, there was no doubt from him; meaning he did not act like one who doubts that the more complete following is better. But the one who shortened was treated like someone uncertain in that regard, because he left what was more complete. This was mentioned by al-Sindi in his commentary on the Musnad."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":3311},{"key":"الطحاوی/شرح_معانیہ","label":"الطحاويّ في شرح معانيه","number":4057},{"key":"ibnmajah","label":"ابن ماجه","number":3045},{"key":"ahmad","label":"مسند الإمام أحمد","number":3311,"n":3311}]},{"num":5198,"demo":false,"sanad":"","matn":["عن مالك بن ربيعة، أنه سمع رسول الله ﷺ يقول: (( اللهم اغفر للمحلِّقين )). قال: يقول رجلٌ من القوم: والمقصِّرين؟ فقال رسول الله ﷺ في الثالثة أو في الرابعة: (( والمقصِّرين )). ثم قال: وأنا يومئذٍ محلوق الرأس، فما يسرُّني بحلق رأسي حمر النعم أو خطرٌ عظيم."],"takhrij":"حسن: رواه الإمام أحمد (١٧٥٩٨)، والطبراني في الكبير (٩/٢٧٥)، وفي الأوسط كما في مجمع البحرين (١٧٧٧).","grade":"حسن","chapter_ar":"باب دعاء النبي ﷺ للمحلّقين بالرّحمة ثلاث مرّات وللمقصّرين مرة واحدة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (17598), al-Tabarani in al-Kabir (9/275), and in al-Awsat as cited in Majma‘ al-Bahrayn (1777).","chapter_en":"The Prophet’s supplication for mercy upon those who shave three times, and upon those who shorten once","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":114,"content":{"translation":{"en":["Malik ibn Rabi‘ah narrated that he heard the Messenger of Allah ﷺ say: “O Allah, forgive those who shave.” A man from the people said: And those who shorten? Then the Messenger of Allah ﷺ, on the third or fourth time, said: “And those who shorten.” Then he said: On that day I myself had my head shaved, and I would not have been pleased to trade my shaving for red camels or for a great wealth."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":17598},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":9},{"key":"وفی_الاوسط_کما/مجمع_البحرین","label":"وفي الأوسط كما في مجمع البحرين","number":1777},{"key":"ahmad","label":"مسند الإمام أحمد","number":17598,"n":17598}]},{"num":5199,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: قال رسول الله ﷺ: (( ليس على النساء حلق، إنما على النساء التقصير ))."],"takhrij":"صحيح: رواه أبو داود (١٩٨٥)، والدارقطني (٢٦٦٦)، والبيهقيّ (٥/١٠٤).","grade":"صحيح","chapter_ar":"باب ليس على النساء حلق","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1985), al-Daraqutni (2666), and al-Bayhaqi (5/104).","chapter_en":"Women are not required to shave their heads","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":115,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Messenger of Allah ﷺ said: “Women are not required to shave; rather, women are only required to shorten their hair.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1985},{"key":"الدارقطنی","label":"الدارقطني","number":2666},{"key":"البیہقی","label":"البيهقيّ","number":5},{"key":"sh9771","label":"سنن الدارقطني","number":2666,"n":2673}]},{"num":5200,"demo":false,"sanad":"","matn":["عن أنس بن مالك: أن رسول الله ﷺ أتى منى، فأتى الجمرة فرماها، ثم أتى منزله بمنى، ونحر، ثم قال للحلاق: (( خذ ))، وأشار إلى جانبه الأيمن، ثم الأيسر، ثم جعل يعطيه الناس.","وفي رواية: وأشار بيده إلى الجانب الأيمن هكذا، فقسم شعره بين من يليه. قال: ثم أشار إلى الحلاق إلى الجانب الأيسر، فحلقه، فأعطاه أمَّ سليم.","وفي رواية: فبدأ بالشق الأيمن، فوزَّعه الشعرة والشعرتين بين الناس. ثم قال بالأيسر، فصنع به مثل ذلك، ثم قال: (( ههنا أبو طلحة؟ )) فدفعه إلى أبي طلحة.","وفي رواية: وقال بيده عن رأسه، فحلق شقَّه الأيمن فقسمه فيمن يليه، ثم قال: (( احلق الشق الآخر )). فقال: (( أين أبو طلحة؟ ))، فأعطاه إيّاه.","وفي رواية: ناول الحالق شقَّه الأيمن فحلقه، ثم دعا أبا طلحة الأنصاري فأعطاه إيّاه، ثم ناول الشق الأيسر فقال: (( احلق )). فحلقه، فأعطاه أبا طلحة فقال: (( اقسمه بين الناس ))."],"takhrij":"صحيح: رواه مسلم (١٣٠٥/٣٢٣، ٣٢٤، ٣٢٥، ٣٢٦)، والبخاريّ (١٧١).","grade":"صحيح","chapter_ar":"باب من السنة ترتيب أعمال الحج يوم النحر: أن يرمي، ثم ينحر، ثم يحلق، ثم يطوف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1305/323, 324, 325, 326) and al-Bukhari (171).","chapter_en":"It is from the Sunnah to perform the rites of the Day of Sacrifice in order: first stoning, then slaughtering, then shaving, then circumambulating","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":116,"content":{"translation":{"en":["Anas ibn Malik narrated that the Messenger of Allah ﷺ came to Mina, then came to the pillar and stoned it, then came to his lodging in Mina and slaughtered. Then he said to the barber: “Take,” and he pointed to his right side, then the left, then he began giving it to the people.","In another narration: He pointed with his hand to the right side like this, and his hair was distributed among those nearest to him. Then he pointed the barber to the left side, and he shaved it, and he gave it to Umm Sulaym.","In another narration: He began with the right side and distributed one hair and two hairs among the people. Then he said regarding the left side, and the same was done with it. Then he said: “Is Abu Talhah here?” and he handed it to Abu Talhah.","In another narration: He pointed with his hand to his head, so the right side of it was shaved and distributed among those near him. Then he said: “Shave the other side.” Then he said: “Where is Abu Talhah?” and gave it to him.","In another narration: He handed the barber the right side of his head and it was shaved, then he called Abu Talhah al-Ansari and gave it to him. Then he handed over the left side and said: “Shave,” so he shaved it, then he gave it to Abu Talhah and said: “Distribute it among the people.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1305},{"key":"bukhari","label":"البخاريّ","number":171}]},{"num":5201,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص، أنه قال: وقف رسول الله ﷺ للناس بمنى والناس يسألونه، فجاءه رجلٌ فقال له: يا رسول الله، لم أشعر فحلقت قبل أن أنحر؟ فقال رسول الله ﷺ: (( انحر ولا حرج )). ثم جاءه آخر فقال: يا رسول الله، لم أشعر فنحرت قبل أن أرمي؟ قال: (( ارمِ ولا حرج )). قال: فما سُئل رسول الله ﷺ عن شيء قُدِّم ولا أُخِّر إلا قال: (( افعل ولا حرج ))."],"takhrij":"متفق عليه: رواه مالك (٢٤٢)، والبخاريّ (١٧٣٦)، ومسلم (١٣٠٦/٣٢٧).","grade":"متفق عليه","chapter_ar":"باب جواز تقديم بعض أعمال الحجّ على بعض يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (242), al-Bukhari (1736), and Muslim (1306/327).","chapter_en":"The permissibility of advancing some rites of Hajj before others on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":117,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-‘As said: The Messenger of Allah ﷺ stood for the people in Mina while they were asking him questions. A man came and said: O Messenger of Allah ﷺ, I did not realize, so I shaved before slaughtering. The Messenger of Allah ﷺ said: “Slaughter, and there is no harm.” Then another came and said: O Messenger of Allah ﷺ, I did not realize, so I slaughtered before stoning. He said: “Stone, and there is no harm.” He said: The Messenger of Allah ﷺ was not asked about anything done earlier or later except that he said: “Do it, and there is no harm.”"]},"buhuth":{"ar":["وعندهما: البخاري (١٧٣٧) ومسلم: أنه شهد النبيَّ ﷺ يخطب يوم النحر، فقام إليه رجل فقال: كنت أحسب أن كذا قبل كذا. ثم قام آخر فقال: كنت أحسب أن كذا قبل كذا، حلقت قبل أن أنحر، ونحرت قبل أن أرمي، وأشباه ذلك، فقال النبي ﷺ: (( افعل ولا حرج )) لهنَّ كلِّهنَّ، فما سُئل يومئذٍ عن شيء إلا قال: (( افعل ولا حرج )). واللفظ للبخاري.","وعند مسلم: إني حلقت قبل أن أرمي، فقال: (( ارمِ ولا حرج )). وأتاه آخر فقال: إني ذبحت قبل أن أرمي، فقال: (( ارمِ ولا حرج )). وأتاه آخر فقال: إني أفضت إلى البيت قبل أن أرمي، فقال: (( ارمِ ولا حرج ))."],"en":["Both al-Bukhari (1737) and Muslim also narrated that he witnessed the Prophet ﷺ giving a sermon on the Day of Sacrifice, when a man stood and said: I thought such-and-such came before such-and-such. Then another stood and said: I thought such-and-such came before such-and-such: I shaved before slaughtering, and I slaughtered before stoning, and matters like that. So the Prophet ﷺ said regarding all of them: “Do it, and there is no harm.” He was not asked that day about anything except that he said: “Do it, and there is no harm.” The wording is al-Bukhari’s.","And in Muslim: One said, I shaved before stoning, and he said: “Stone, and there is no harm.” Another came and said: I slaughtered before stoning, and he said: “Stone, and there is no harm.” Another came and said: I went on to the House before stoning, and he said: “Stone, and there is no harm.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":242},{"key":"bukhari","label":"البخاريّ","number":1736},{"key":"muslim","label":"مسلم","number":1306}]},{"num":5202,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله: أنَّ رجلًا قال: يا رسول الله، ذبحتُ قبل أن أرمي. قال: (( ارمِ ولا حرج )). قال رجلٌ: يا رسول الله، حلقتُ قبل أن أذبح؟ قال: (( اذبح ولا حرج ))."],"takhrij":"صحيح: رواه الإمام أحمد (١٥١٣٣)، وابن حبان (٣٨٧٨)، والبيهقيّ (٥/١٤٣).","grade":"صحيح","chapter_ar":"باب جواز تقديم بعض أعمال الحجّ على بعض يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (15133), Ibn Hibban (3878), and al-Bayhaqi (5/143).","chapter_en":"The permissibility of advancing some rites of Hajj before others on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":117,"content":{"translation":{"en":["Jabir ibn Abd Allah narrated that a man said: O Messenger of Allah ﷺ, I slaughtered before stoning. He said: “Stone, and there is no harm.” Another man said: O Messenger of Allah ﷺ, I shaved before slaughtering. He said: “Slaughter, and there is no harm.”"]},"buhuth":{"ar":["ورواه ابن ماجه (٣٠٥٢)، والإمام أحمد (١٤٤٩٨)، بلفظ: قعد رسول الله ﷺ بمنى يوم النحر للناس، فجاءه رجل فقال: يا رسول الله، إني حلقت قبل أن أذبح؟ قال: (( لا حرج )). ثم جاءه آخر فقال: يا رسول الله، إني نحرت قبل أن أرمي؟ قال: (( لا حرج )). فما سُئل يومئذٍ عن شيء قُدِّم قبل شيء إلا قال: (( لا حرج )). واللفظ لابن ماجه.","وزاد أحمد: (( عرفة كلُّها موقف، والمزدلفة كلُّها موقف… ))."],"en":["Ibn Majah (3052) and Imam Ahmad (14498) also narrated it with the wording: The Messenger of Allah ﷺ sat in Mina on the Day of Sacrifice for the people, then a man came and said: O Messenger of Allah ﷺ, I shaved before slaughtering. He said: “There is no harm.” Then another came and said: O Messenger of Allah ﷺ, I slaughtered before stoning. He said: “There is no harm.” He was not asked that day about anything done before something else except that he said: “There is no harm.” This is the wording of Ibn Majah.","Ahmad added: “All of Arafah is a place of standing, and all of Muzdalifah is a place of standing…”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":15133},{"key":"البیہقی","label":"البيهقيّ","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":15133,"n":15133},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5781,"n":5778}]},{"num":5203,"demo":false,"sanad":"","matn":["عن أسامة بن شريك، قال: خرجتُ مع النبيِّ ﷺ حاجًّا، فكان الناس يأتونه، فمن قال: يا رسول الله، سعيتُ قبل أن أطوف؟ أو قدَّمتُ شيئًا أو أخَّرتُ شيئًا؟ فكان يقول: (( لا حرج، لا حرج، إلا على رجلٍ اقترض عرضَ رجلٍ مسلمٍ وهو ظالم، فذلك الذي حرج وهلك ))."],"takhrij":"صحيح: رواه أبو داود (٢٠١٥)، ومن طريقه البيهقيّ (٥/١٤٦)، وصححه ابن خزيمة (٢٧٧٤).","grade":"صحيح","chapter_ar":"باب جواز تقديم بعض أعمال الحجّ على بعض يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2015), and through him by al-Bayhaqi (5/146), and authenticated by Ibn Khuzaymah (2774).","chapter_en":"The permissibility of advancing some rites of Hajj before others on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":117,"content":{"translation":{"en":["Usamah ibn Sharik said: I went out with the Prophet ﷺ for Hajj, and people would come to him. One would say: O Messenger of Allah ﷺ, I did the sa‘y before circumambulating, or I advanced something, or delayed something. He would say: “There is no harm, there is no harm, except for a man who wrongfully violates the honor of a Muslim. That is the one who has committed wrong and perished.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2015},{"key":"ومن_طریقہ_البیہقی","label":"ومن طريقه البيهقيّ","number":5},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2774}]},{"num":5204,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أنَّ النبيَّ ﷺ قيل له: في الذبح، والحلق، والرمي، والتقديم والتأخير. فقال: (( لا حرج )).","وفي رواية: كان النبيُّ ﷺ يُسأل يوم النحر بمنى فيقول: (( لا حرج )). فسأله رجلٌ فقال: حلقتُ قبل أن أذبح؟ قال: (( اذبح ولا حرج )). وقال: رميتُ بعد ما أمسيت؟ فقال: (( لا حرج )).","وفي رواية: قال رجل للنبيِّ ﷺ: زرتُ قبل أن أرمي؟ قال: (( لا حرج )). قال: حلقتُ قبل أن أذبح؟ قال: (( لا حرج )). قال: ذبحتُ قبل أن أرمي؟ قال: (( لا حرج ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٣٤)، ومسلم (١٣٠٧).","grade":"متفق عليه","chapter_ar":"باب جواز تقديم بعض أعمال الحجّ على بعض يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1734) and Muslim (1307).","chapter_en":"The permissibility of advancing some rites of Hajj before others on the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":117,"content":{"translation":{"en":["Abdullah ibn Abbas narrated that the Prophet ﷺ was asked about slaughtering, shaving, stoning, and doing things earlier or later, and he said: “There is no harm.”","In another narration: The Prophet ﷺ used to be asked on the Day of Sacrifice in Mina, and he would say: “There is no harm.” A man asked him and said: I shaved before slaughtering. He said: “Slaughter, and there is no harm.” Another said: I stoned after evening came. He said: “There is no harm.”","In another narration: A man said to the Prophet ﷺ: I made the visit before stoning. He said: “There is no harm.” He said: I shaved before slaughtering. He said: “There is no harm.” He said: I slaughtered before stoning. He said: “There is no harm.”"]},"buhuth":{"ar":["والرواية الثانية عند البخاريّ (١٧٣٥)، والرواية الثالثة عند البخاريّ أيضًا (١٧٢٢).","قوله: (( زرتُ )) أي طواف الزيارة، وهو طواف الإفاضة."],"en":["The second narration is in al-Bukhari (1735), and the third narration is also in al-Bukhari (1722).","His statement, “I made the visit,” means the visit-circumambulation, which is the circumambulation of al-Ifadah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1734},{"key":"muslim","label":"مسلم","number":1307}]},{"num":5205,"demo":false,"sanad":"","matn":["عن حفصة أم المؤمنين، أنها قالت لرسول الله ﷺ: ما شأن الناس حلُّوا، ولم تحللْ أنت من عمرتك؟ فقال: (( إنّي لبدتُ رأسي، وقلدتُ هديي، فلا أحلُّ حتى أنحر ))."],"takhrij":"متفق عليه: رواه مالك (١٨٠)، والبخاريّ (١٥٦٦)، ومسلم (١٢٢٩/١٧٦).","grade":"متفق عليه","chapter_ar":"باب أنَّ من ساق الهدي لا يحلق رأسه حتى ينحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (180), al-Bukhari (1566), and Muslim (1229/176).","chapter_en":"One who has brought sacrificial animals with him does not shave his head until he slaughters","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":118,"content":{"translation":{"en":["Hafsah, Mother of the Believers, said to the Messenger of Allah ﷺ: Why is it that the people have exited consecration, while you have not exited from your ‘umrah? He said: “I matted my hair and garlanded my sacrificial animals, so I will not exit consecration until I slaughter.”"]},"buhuth":{"ar":["وهذا خاصٌّ بالقارن الذي ساق الهدي، بخلاف المتمتّع والمفرد إن أراد الذبح، أو القارن الذي لم يسق الهدي، فهم مخيَّرون في التقديم والتأخير كما جاء في الأحاديث الصحيحة: (( افعل ولا حرج )).","وقيل: إنَّ قوله ﷺ: (( افعل ولا حرج )) يشمل جميع الحالات تيسيرًا من الله وتخفيفًا منه."],"en":["This is specific to the one performing combined Hajj and ‘umrah who brought the sacrificial animal with him. As for the one doing tamattu‘, the one doing ifrad who wishes to slaughter, or the one doing qiran without bringing the sacrificial animal, they are given leeway regarding order, as stated in the authentic hadiths: “Do it, and there is no harm.”","And it was also said that the Prophet’s statement, “Do it, and there is no harm,” includes all such cases as a facilitation and easing from Allah."]},"intro":{"ar":["قال الله تعالى: ( وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ الْهَدْيُ مَحِلَّهُ ) [البقرة: ١٩٦]."],"en":["Allah the Exalted said: “And do not shave your heads until the sacrificial animal reaches its place of slaughter.” [al-Baqarah: 196]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":180},{"key":"bukhari","label":"البخاريّ","number":1566},{"key":"muslim","label":"مسلم","number":1229}]},{"num":5206,"demo":false,"sanad":"","matn":["عن نافع أنَّ ابن عمر أراد الحجَّ عام نزل الحجاج بابن الزبير، فقيل له: إنَّ الناس كائن بينهم قتال، وإنَّا نخاف أن يصدُّوك. فقال: ( لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ )، أصنع كما صنع رسول الله ﷺ. إني أشهدكم أني قد أوجبت عمرة. ثم خرج حتى إذا كان بظاهر البيداء قال: ما شأن الحج والعمرة إلا واحد. اشهدوا - قال ابن رمح: أُشهدكم - أني قد أوجبت حجًّا مع عمرتي. وأهدى هديًا اشتراه بقديد، ثم انطلق يهلُّ بهما جميعًا، حتى قدم مكة فطاف بالبيت وبالصفا والمروة، ولم يزد على ذلك، ولم ينحر، ولم يحلق، ولم يقصِّر، ولم يحلل من شيءٍ حرم منه، حتى كان يوم النحر، فنحر وحلق، ورأى أن قد قضى طواف الحج والعمرة بطوافه الأول.","وقال ابن عمر: كذلك فعل رسول الله ﷺ."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٤٠)، ومسلم (١٢٣٠/١٨٢)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب أنَّ من ساق الهدي لا يحلق رأسه حتى ينحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1640) and Muslim (1230/182), and the wording is Muslim’s.","chapter_en":"One who has brought sacrificial animals with him does not shave his head until he slaughters","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":118,"content":{"translation":{"en":["Nafi‘ narrated that Ibn Umar intended Hajj in the year when al-Hajjaj came against Ibn al-Zubayr, and it was said to him: The people are in fighting among themselves, and we fear they may prevent you. He said: “There has certainly been for you in the Messenger of Allah ﷺ an excellent example.” I will do as the Messenger of Allah ﷺ did. I make you witness that I have made ‘umrah binding upon myself. Then he went out, until when he reached the outer part of al-Bayda’, he said: The matter of Hajj and ‘umrah is one and the same. Witness — Ibn Rumh said: I make you witness — that I have made Hajj binding together with my ‘umrah. He offered a sacrificial animal that he bought at Qudayd, then he set out reciting the talbiyah for both together, until he came to Makkah and circumambulated the House and went between al-Safa and al-Marwah, and did not add to that. He did not slaughter, shave, shorten, or exit from anything that had become prohibited to him until the Day of Sacrifice. Then he slaughtered and shaved, and he held that his first circumambulation had sufficed for both the Hajj and the ‘umrah.","And Ibn Umar said: The Messenger of Allah ﷺ did likewise."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1640},{"key":"muslim","label":"مسلم","number":1230}]},{"num":5207,"demo":false,"sanad":"","matn":["عن عائشة قالت: كنتُ أطيِّب رسولَ الله ﷺ لإحرامه قبل أن يحرم، ولحلِّه قبل أن يطوف بالبيت."],"takhrij":"متفق عليه: رواه مالك (١٧)، والبخاريّ (١٥٣٩)، ومسلم (١١٨٩/٣٣).","grade":"متفق عليه","chapter_ar":"باب بماذا يحصل التحلُّل الأول","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (1539), and Muslim (1189/33).","chapter_en":"By what the first stage of release from consecration is attained","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":119,"content":{"translation":{"en":["Aishah said: I used to perfume the Messenger of Allah ﷺ for his consecration before he entered it, and for his release before he circumambulated the House."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"bukhari","label":"البخاريّ","number":1539},{"key":"muslim","label":"مسلم","number":1189}]},{"num":5208,"demo":false,"sanad":"","matn":["عن عائشة، قالت: طيَّبتُ رسول الله ﷺ لحُرمِه حين أحرم، ولحلِّه بعدما رمى جمرة العقبة، قبل أن يطوف."],"takhrij":"صحيح: رواه النسائيّ (٢٦٨٧).","grade":"صحيح","chapter_ar":"باب بماذا يحصل التحلُّل الأول","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (2687).","chapter_en":"By what the first stage of release from consecration is attained","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":119,"content":{"translation":{"en":["Aishah said: I perfumed the Messenger of Allah ﷺ for his consecration when he entered consecration, and for his release after he stoned Jamrat al-‘Aqabah, before he circumambulated."]},"buhuth":{"ar":["ورواه الإمام أحمد (٢٦٠٧٨) من وجه آخر عن عائشة قالت: (( طيَّبتُ رسول الله ﷺ بيدي بذَريرةٍ لحجة الوداع للحلِّ والإحرام، حين أحرم، وحين رمى جمرة العقبة يوم النحر قبل أن يطوف بالبيت )).","فقول عائشة: (( بعدما رمى جمرة العقبة قبل أن يطوف بالبيت )) يحمل على بعد ما رمى وذبح وحلق، واستثني منه الطواف فقط؛ لأن هذا هو الترتيب الذي عمل به النبي ﷺ يوم النحر، وعليه يُحمل قولها أيضًا: (( لحلِّه قبل أن يطوف )) أي بعد رميه الجمرة والذبح والحلق، قبل الطواف، كما بيَّن ذلك ابن عمر، وكما فسَّره بذلك ابن خزيمة."],"en":["Imam Ahmad (26078) also narrated through another route from Aishah, who said: “I perfumed the Messenger of Allah ﷺ with my own hand using powdered perfume in the Farewell Pilgrimage for both consecration and release: when he entered consecration, and when he stoned Jamrat al-‘Aqabah on the Day of Sacrifice before he circumambulated the House.”","So Aishah’s statement, “after he stoned Jamrat al-‘Aqabah before he circumambulated the House,” is understood to mean after he had stoned, slaughtered, and shaved, with only the circumambulation remaining. That is because this is the order the Prophet ﷺ followed on the Day of Sacrifice. Her statement, “for his release before he circumambulated,” is likewise understood in this way: after stoning the pillar, slaughtering, and shaving, but before circumambulation, as Ibn Umar clarified and Ibn Khuzaymah explained."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2687}]},{"num":5209,"demo":false,"sanad":"","matn":["عن عائشة قالت: كنتُ أطيِّب النبيَّ ﷺ بعد ما يرمي الجمرة قبل أن يفيض إلى البيت.","قال سالم: فسنَّة رسول الله ﷺ أحقُّ أن نأخذ بها من قول عمر."],"takhrij":"حسن: رواه الإمام أحمد (٢٤٧٥٠).","grade":"حسن","chapter_ar":"باب بماذا يحصل التحلُّل الأول","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (24750).","chapter_en":"By what the first stage of release from consecration is attained","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":119,"content":{"translation":{"en":["Aishah said: I used to perfume the Prophet ﷺ after he stoned the pillar, before he went on to the House.","Salim said: So the Sunnah of the Messenger of Allah ﷺ is more deserving of being followed than the opinion of Umar."]},"buhuth":{"ar":["وقول سالم: (( سنة رسول الله ﷺ أحق أن نأخذ بها من قول عمر )) لأن عمر بن الخطاب رضي الله عنه كان يقول: (( إذا رميتم الجمرة وذبحتم فقد حلَّ لكم كل شيءٍ حرم عليكم إلا النساء والطيب )).","قال ابن خزيمة: (( وقول عائشة: (( طيَّبتُ رسول الله ﷺ لحلِّه قبل أن يطوف بالبيت )) دلالةٌ على أنه إذا رمى الجمرة وذبح وحلق كان حلالًا قبل أن يطوف بالبيت، خلا ما زُجر عنه من وطء النساء، الذي لم يخالف العلماء فيه أنه ممنوع من وطء النساء حتى يطوف طواف الزيارة ))."],"en":["Salim’s statement, “The Sunnah of the Messenger of Allah ﷺ is more deserving of being followed than the opinion of Umar,” is because Umar ibn al-Khattab, may Allah be pleased with him, used to say: “Once you have stoned the pillar and slaughtered, everything prohibited to you becomes lawful except women and perfume.”","Ibn Khuzaymah said: “Aishah’s statement, ‘I perfumed the Messenger of Allah ﷺ for his release before he circumambulated the House,’ indicates that when he had stoned the pillar, slaughtered, and shaved, he had entered release before circumambulating the House, except for intercourse with women. The scholars did not differ that intercourse with women remains prohibited until the circumambulation of visitation is performed.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":24750},{"key":"ahmad","label":"مسند الإمام أحمد","number":24750,"n":24750}]},{"num":5210,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: ثم لم يحلل من شيءٍ حرم منه حتى قضى حجَّه، ونحر هديه يوم النحر، وطاف بالبيت، ثم حلَّ من كل شيءٍ حرم منه. وفعل مثل ما فعل رسول الله ﷺ من أهدى وساق الهدي من الناس."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٩١)، ومسلم (١٢٢٧).","grade":"متفق عليه","chapter_ar":"باب بماذا يحصل التحلُّل الأول","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1691) and Muslim (1227).","chapter_en":"By what the first stage of release from consecration is attained","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":119,"content":{"translation":{"en":["Ibn Umar said: Then he did not exit from anything that had been prohibited to him until he completed his Hajj, slaughtered his sacrificial animal on the Day of Sacrifice, and circumambulated the House. Then he exited from everything that had been prohibited to him. And the people who had brought and driven sacrificial animals did as the Messenger of Allah ﷺ had done."]},"buhuth":{"ar":["وقوله: (( وطاف بالبيت )) يقصد به التحلُّل الثاني."],"en":["His statement, “and circumambulated the House,” refers to the second and complete release from consecration."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1691},{"key":"muslim","label":"مسلم","number":1227}]},{"num":5211,"demo":false,"sanad":"","matn":["عن عبد الله بن الزبير قال: من سنَّة الحجِّ أن يصلِّي الإمام الظهر والعصر والمغرب والعشاء الآخرة والصبح بمنى، ثم يغدو إلى عرفة فيقيل حيث قُضي له حتى إذا زالت الشمس خطب الناس، ثم صلّى الظهر والعصر جميعًا، ثم وقف بعرفات حتى تغيب الشمس، ثم يفيض فيصلِّي بالمزدلفة أو حيث قضى الله، ثم يقف بجمع حتى إذا أسفر دفع قبل طلوع الشمس، فإذا رمى الجمرة الكبرى حلَّ له كلُّ شيءٍ حرم عليه إلا النساء والطيب حتى يزور البيت."],"takhrij":"صحيح: رواه ابن خزيمة (٢٨٠٠، ٢٨٠١)، والحاكم (١٦٩٥)، والبيهقيّ (٥/١٢٢).","grade":"صحيح","chapter_ar":"باب بماذا يحصل التحلُّل الأول","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (2800, 2801), al-Hakim (1695), and al-Bayhaqi (5/122).","chapter_en":"By what the first stage of release from consecration is attained","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":119,"content":{"translation":{"en":["Abdullah ibn al-Zubayr said: From the Sunnah of Hajj is that the imam prays Zuhr, Asr, Maghrib, Isha, and Fajr in Mina, then goes out early to Arafah and rests where it is decreed for him until the sun declines. Then he gives a sermon to the people, then prays Zuhr and Asr together, then stands at Arafat until the sun sets, then proceeds and prays in Muzdalifah or wherever Allah decrees, then stands at Muzdalifah until it becomes very bright, then departs before sunrise. When he has stoned the large pillar, everything that had been prohibited to him becomes lawful except women and perfume, until he visits the House."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2800},{"key":"البیہقی","label":"البيهقيّ","number":5},{"key":"hakim","label":"المستدرك على الصحيحين","number":1695,"n":1685}]},{"num":5212,"demo":false,"sanad":"","matn":["عن عائشة، قالت: حججنا مع النبيِّ ﷺ فأفضنا يوم النحر."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٣٣)، ورواه مسلم (١٢١١/١٢٠)، وفيه قالت عائشة: (( فلما كان يوم النحر طهرتُ، فأمرني رسول الله ﷺ فأفضت )).","grade":"متفق عليه","chapter_ar":"باب طواف الإفاضة يوم النحر، وهل من لم يطف يوم النحر يعود محرِمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1733), and Muslim also narrated it (1211/120), in which Aishah said: “Then when the Day of Sacrifice came, I became pure, so the Messenger of Allah ﷺ instructed me, and I made the al-Ifadah.”","chapter_en":"The circumambulation of al-Ifadah on the Day of Sacrifice, and whether one who does not circumambulate on that day returns to the state of consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":120,"content":{"translation":{"en":["Aishah said: We performed Hajj with the Prophet ﷺ, and we made the al-Ifadah on the Day of Sacrifice."]},"intro":{"ar":["قال الله تعالى: ( ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ ) [سورة الحج: ٢٩]. وهذا الطواف يسمى طواف الإفاضة، ويسمى أيضًا طواف الحج والزيارة، وهو لا يكون إلا بعد الوقوف بعرفة والمبيت بمزدلفة، وهذا لا خلاف فيه، وعليه يدل ظاهر القرآن."],"en":["Allah the Exalted said: “Then let them complete what is required of them, fulfill their vows, and circumambulate the Ancient House.” [Surat al-Hajj: 29] This circumambulation is called the circumambulation of al-Ifadah. It is also called the circumambulation of Hajj and the circumambulation of visitation. It only takes place after standing at Arafah and spending the night at Muzdalifah. There is no disagreement about this, and the plain meaning of the Qur’an indicates it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1733},{"key":"muslim","label":"مسلم","number":1211}]},{"num":5213,"demo":false,"sanad":"","matn":["عن ابن عمر: أنَّ رسول الله ﷺ أفاض يوم النحر، ثم رجع فصلّى الظهر بمنى.","قال نافع: فكان ابن عمر يفيض يوم النحر، ثم يرجع فيصلّي الظهر بمنى، ويذكر أن النبيَّ ﷺ فعله."],"takhrij":"صحيح: رواه مسلم (١٣٠٨).","grade":"صحيح","chapter_ar":"باب طواف الإفاضة يوم النحر، وهل من لم يطف يوم النحر يعود محرِمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1308).","chapter_en":"The circumambulation of al-Ifadah on the Day of Sacrifice, and whether one who does not circumambulate on that day returns to the state of consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":120,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ made the al-Ifadah on the Day of Sacrifice, then returned and prayed Zuhr in Mina.","Nafi‘ said: Ibn Umar used to make the al-Ifadah on the Day of Sacrifice, then return and pray Zuhr in Mina, and he would mention that the Prophet ﷺ did this."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1308}]},{"num":5214,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال:","ثم ركب رسول الله ﷺ، فأفاض إلى البيت، فصلى بمكة الظهر، فأتى بني عبد المطلب يسقون على زمزم، فقال:","«انْزِعُوا بَنِي عَبْدِ الْمُطَّلِبِ، فَلَوْلَا أَنْ يَغْلِبَكُمُ النَّاسُ عَلَى سِقَايَتِكُمْ لَنَزَعْتُ مَعَكُمْ».","فناولوه دلوًا فشرب منه."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب طواف الإفاضة يوم النحر، وهل من لم يطف يوم النحر يعود محرِمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The circumambulation of al-Ifadah on the Day of Sacrifice, and whether one who does not circumambulate on that day returns to the state of consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":120,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported:","Then the Messenger of Allah ﷺ mounted and proceeded to the House, where he performed the Ṭawāf of Ifāḍah. He prayed Ẓuhr in Makkah, then came to Banū ʿAbd al-Muṭṭalib while they were drawing water from Zamzam. He said:","“Draw water, O Banū ʿAbd al-Muṭṭalib. Were it not that the people might overpower you in your right of providing water, I would draw water together with you.”","They handed him a bucket, and he drank from it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5215,"demo":false,"sanad":"","matn":["عن عائشة قالت:","أفاض رسول الله ﷺ من آخر يومه حين صلى الظهر، ثم رجع إلى منى، فمكث بها ليالي أيام التشريق، يرمي الجمرة إذا زالت الشمس، كل جمرة بسبع حصيات، يكبر مع كل حصاة، ويقف عند الأولى والثانية، فيطيل القيام ويتضرع، ويرمي الثالثة ولا يقف عندها."],"takhrij":"حسن: رواه أبو داود (١٩٧٣)، وابن حبان (٣٨٦٨).","grade":"حسن","chapter_ar":"باب طواف الإفاضة يوم النحر، وهل من لم يطف يوم النحر يعود محرِمًا؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1973) and Ibn Ḥibbān (3868).","chapter_en":"The circumambulation of al-Ifadah on the Day of Sacrifice, and whether one who does not circumambulate on that day returns to the state of consecration","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":120,"content":{"translation":{"en":["ʿĀʾishah reported:","The Messenger of Allah ﷺ performed the Ṭawāf of Ifāḍah toward the latter part of the day after he had prayed Ẓuhr. He then returned to Minā and remained there during the nights of the Days of Tashrīq.","He would stone the Jamarāt after the sun had passed its zenith, throwing seven pebbles at each Jamrah and saying “Allāhu Akbar” with every pebble. He would stop after the first and second Jamarah, prolong his standing and supplicate humbly. He would then stone the third Jamarah and would not stop there."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1973},{"key":"ibnhibban","label":"ابن حبان","number":3868}]},{"num":5216,"demo":false,"sanad":"","matn":["عن ابن عباس:","أن النبي ﷺ لم يرمل في السبع الذي أفاض فيه."],"takhrij":"صحيح: رواه أبو داود (٢٠٠١)، وابن ماجه (٣٠٦٠)، وابن خزيمة في صحيحه (٢٩٤٣)، والحاكم (١٧٤٦).","grade":"صحيح","chapter_ar":"باب ترك الرمل في طواف الزيارة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2001), Ibn Mājah (3060), Ibn Khuzaymah in his Ṣaḥīḥ (2943), and al-Ḥākim (1746).","chapter_en":"Leaving off ramal in the Ṭawāf of al-Ziyārah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":121,"content":{"translation":{"en":["Ibn ʿAbbās reported:","The Prophet ﷺ did not perform ramal—the brisk walk—in the seven circuits of the Ṭawāf in which he performed the Ifāḍah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2001},{"key":"ibnmajah","label":"ابن ماجه","number":3060},{"key":"ابن_خزیمہ/صحیحہ","label":"ابن خزيمة في صحيحه","number":2943},{"key":"hakim","label":"المستدرك على الصحيحين","number":1746,"n":1736}]},{"num":5217,"demo":false,"sanad":"","matn":["عن أبي ذرّ، قال: قال لي رسولُ اللّٰه ﷺ: (( متى كنتَ ههنا؟ )). قال: قلت: قد كنتُ ههنا منذ ثلاثين بين ليلةٍ ويومٍ. قال: (( فمن كان يطعمك؟ )). قال: قلت: ما كان لي طعام إلا ماء زمزم، فسمنتُ حتى تكسّرت عُكَنُ بطني، وما أجد على كبدي سخفةَ جوع! قال: (( إنّها مباركة، إنّها طعامُ طُعْمٍ ))."],"takhrij":"صحيح: رواه مسلم (٢٤٧٣).","grade":"صحيح","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2473).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Abu Dharr said: The Messenger of Allah ﷺ said to me, “How long have you been here?” He said: I replied: I have been here for thirty days and nights. He said: “Who was feeding you?” He said: I replied: I had no food except Zamzam water, and I became so well nourished that the folds of my belly bent and creased from fatness, and I felt no weakness of hunger in my liver. He said: “It is blessed; it is nourishing food.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2473}]},{"num":5218,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: ثم ركب رسولُ اللّٰه ﷺ فأفاض إلى البيت، فصلّى بمكة الظهر، فأتى بني عبد المطلب يسقون على زمزم، فقال: (( انزعوا بني عبد المطلب، فلولا أن يغلبكم الناسُ على سقايتكم لنزعتُ معكم )). فناولوه دلوًا فشرب منه."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Jabir ibn Abd Allah said: Then the Messenger of Allah ﷺ mounted and proceeded to the House, and he prayed Zuhr in Makkah. Then he came to Banu Abd al-Muttalib while they were drawing water from Zamzam, and he said: “Draw, O Banu Abd al-Muttalib. Were it not that people might overpower you concerning your duty of giving water, I would have drawn with you.” So they handed him a bucket and he drank from it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5219,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله: أنَّ النبيَّ ﷺ ذهب إلى زمزم، فشرب منها، وصبَّ على رأسه."],"takhrij":"حسن: رواه الإمام أحمد (١٥٢٤٣).","grade":"حسن","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (15243).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Jabir ibn Abd Allah narrated that the Prophet ﷺ went to Zamzam, drank from it, and poured it over his head."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":15243},{"key":"ahmad","label":"مسند الإمام أحمد","number":15243,"n":15243}]},{"num":5220,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: سمعتُ رسولَ اللّٰه ﷺ يقول: (( ماءُ زمزم لِما شُرب له ))."],"takhrij":"حسن: رواه ابن ماجه (٣٠٦٢)، وأحمد (١٤٨٤٩)، والبيهقي (٥/١٤٨).","grade":"حسن","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3062), Ahmad (14849), and al-Bayhaqi (5/148).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Jabir ibn Abd Allah said: I heard the Messenger of Allah ﷺ say: “The water of Zamzam is for whatever it is drunk for.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3062},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":14849,"n":14849}]},{"num":5221,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: سقيتُ رسولَ اللّٰه ﷺ من زمزم فشرب قائمًا، واستسقى وهو عند البيت."],"takhrij":"صحيح: رواه البخاري (١٦٣٧)، ومسلم (٢٠٢٧/١٢٠). واللفظ لمسلم.","grade":"صحيح","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1637) and Muslim (2027/120). The wording is that of Muslim.","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Ibn Abbas said: I gave the Messenger of Allah ﷺ Zamzam water to drink, and he drank while standing, and he asked for water while he was by the House."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1637},{"key":"muslim","label":"مسلم","number":2027}]},{"num":5222,"demo":false,"sanad":"","matn":["عن ابن عباس: أن رسولَ اللّٰه ﷺ جاء إلى السقاية فاستسقى، فقال العباس: يا فضل، اذهب إلى أمك فأتِ رسولَ اللّٰه ﷺ بشراب من عندها. فقال: (( اسقني )). قال: يا رسول اللّٰه، إنهم يجعلون أيديهم فيه! قال: (( اسقني )). فشرب منه، ثم أتى زمزم وهم يسقون ويعملون فيها، فقال: (( اعملوا، فإنكم على عمل صالح )). ثم قال: (( لولا أن تُغلبوا لنزلتُ حتى أضع الحبل على هذه )) يعني عاتقه، وأشار إلى عاتقه."],"takhrij":"صحيح: رواه البخاري (١٦٣٥).","grade":"صحيح","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1635).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ came to the place of giving water and asked for a drink. Al-Abbas said: O Fadl, go to your mother and bring the Messenger of Allah ﷺ a drink from her. He said: “Give me to drink.” Al-Abbas said: O Messenger of Allah ﷺ, they put their hands in it. He said: “Give me to drink.” So he drank from it. Then he came to Zamzam while they were drawing water and working there, and he said: “Continue your work, for you are doing a righteous deed.” Then he said: “Were it not that you might be overpowered, I would come down and place the rope upon this,” meaning his shoulder, and he pointed to his shoulder."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1635}]},{"num":5223,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قال رسولُ اللّٰه ﷺ: (( إن الحمى من فيح جهنم، فأبردوها بماء زمزم ))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٦٤٩)، وصححه ابن حبان (٦٠٢٨)، والحاكم (٨٢٢٨).","grade":"صحيح","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (2649), authenticated by Ibn Hibban (6028), and al-Hakim (8228).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “Fever is from the heat of Hellfire, so cool it with Zamzam water.”"]},"buhuth":{"ar":["ورواه البخاري (٣٢٦١) وفيه: إن رسولَ اللّٰه ﷺ قال: (( الحمى من فيح جهنم، فأبردوها بالماء، أو قال: بماء زمزم ))."],"en":["Al-Bukhari (3261) also narrated it with the wording: “Fever is from the heat of Hellfire, so cool it with water,” or he said, “with Zamzam water.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":2649},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":6028},{"key":"ahmad","label":"مسند الإمام أحمد","number":2649,"n":2649},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1002,"n":999},{"key":"hakim","label":"المستدرك على الصحيحين","number":8228,"n":8235}]},{"num":5224,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: قال رسولُ اللّٰه ﷺ: (( خيرُ ماءٍ على وجه الأرض ماءُ زمزم، فيه طعامٌ من الطُّعم، وشفاءٌ من السُّقم. وشرُّ ماءٍ على وجه الأرض ماءٌ بوادي برهوت بحضرموت، عليه كرجل الجراد من الهوام، يصبح يتدفق ويمسي لا بلال فيه ))."],"takhrij":"حسن: رواه الطبراني في الكبير (١١/٩٨)، والفاكهي في أخبار مكة (٢/٤١).","grade":"حسن","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (11/98) and al-Fakihi in Akhbar Makkah (2/41).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “The best water on the face of the earth is Zamzam water. In it is nourishment and healing from illness. And the worst water on the face of the earth is the water in the valley of Barhut in Hadramawt. Around it are insects like swarms of locusts; in the morning it flows, and by evening there is no moisture in it.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":11},{"key":"الفاکہی/اخبار_مکہ","label":"الفاكهي في أخبار مكة","number":2}]},{"num":5225,"demo":false,"sanad":"","matn":["عن محمد بن عبد الرحمن بن أبي بكر، قال: كنتُ عند ابن عباس جالسًا، فجاءه رجلٌ فقال: من أين جئتَ؟ قال: من زمزم. قال: فشربتَ منها كما ينبغي؟ قال: وكيف؟ قال: إذا شربتَ منها فاستقبل القبلة، واذكر اسم الله، وتنفس ثلاثًا، وتضلَّع منها. فإذا فرغت فاحمد الله عز وجل، فإن رسولَ اللّٰه ﷺ قال: (( إن آيةَ ما بيننا وبين المنافقين أنهم لا يتضلَّعون من زمزم ))."],"takhrij":"حسن: رواه ابن ماجه (٣٠٦١)، والبيهقي (٥/١٤٧)، والحاكم (١٧٣٨).","grade":"حسن","chapter_ar":"باب ما جاء في شرب ماء زمزم وصبه على الرأس للحاج والمعتمر وغيرهما وأنه ماء مبارك، ويستشفى به","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3061), al-Bayhaqi (5/147), and al-Hakim (1738).","chapter_en":"What has been narrated regarding drinking Zamzam water and pouring it over the head for the pilgrim and the one performing ʿUmrah and others, and that it is blessed water used for healing","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":122,"content":{"translation":{"en":["Muhammad ibn Abd al-Rahman ibn Abi Bakr said: I was sitting with Ibn Abbas when a man came to him. He said: Where have you come from? He said: From Zamzam. He said: Did you drink from it as one should? He said: How is that? He said: When you drink from it, face the qiblah, mention the name of Allah, breathe three times, and drink deeply from it. Then when you finish, praise Allah. For the Messenger of Allah ﷺ said: “The sign between us and the hypocrites is that they do not drink deeply from Zamzam.”"]},"buhuth":{"ar":["والتضلّع: هو الإكثار من الشرب حتى يتمدّد جنبه وأضلاعه."],"en":["Drinking deeply means to drink abundantly until one’s sides and ribs expand."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3061},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"hakim","label":"المستدرك على الصحيحين","number":1738,"n":1728}]},{"num":5226,"demo":false,"sanad":"","matn":["عن أبي الزبير، قال: كنا عند جابر بن عبد الله فتحدثنا، فحضرت صلاة العصر، فقام فصلّى بنا في ثوبٍ واحد قد تلبَّب به، ورداؤه موضوع، ثم أُتي بماءٍ من زمزم فشرب. فقالوا: ما هذا؟ قال: هذا ماء زمزم. وقال فيه رسولُ اللّٰه ﷺ: (( ماء زمزم لما شرب له )). قال: ثم أرسل النبيُّ ﷺ وهو بالمدينة قبل أن تُفتح مكة إلى سهيل بن عمرو: (( أن أهدِ لنا من ماء زمزم ولا تترك )). قال: فبعث إليه بمزادتين."],"takhrij":"حسن: رواه البيهقي (٥/٢٠٢).","grade":"حسن","chapter_ar":"باب ما جاء في حمل ماء زمزم وإهدائه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (5/202).","chapter_en":"What has been reported about carrying Zamzam water and gifting it","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":123,"content":{"translation":{"en":["Abu al-Zubayr said: We were with Jabir ibn Abd Allah and were speaking together when the time for Asr prayer came. He stood and led us in prayer in a single garment wrapped around him, while his cloak was laid aside. Then Zamzam water was brought, and he drank from it. They said: What is this? He said: This is Zamzam water. The Messenger of Allah ﷺ said concerning it: “The water of Zamzam is for whatever it is drunk for.” He then said: Before Makkah was opened, the Prophet ﷺ, while in Madinah, sent to Suhayl ibn Amr: “Send us some Zamzam water, and do not leave it.” So he sent to him two water-skins."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":5},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":9987,"n":10075}]},{"num":5227,"demo":false,"sanad":"","matn":["عن ابن عباس: أن النبيَّ ﷺ شرب ماءً في الطواف."],"takhrij":"حسن: رواه ابن خزيمة (٢٧٥٠)، وابن حبان (٣٨٣٧)، والحاكم (١٦٨٩)، والبيهقي (٥/٨٦).","grade":"حسن","chapter_ar":"باب الشرب في الطواف","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (2750), Ibn Hibban (3837), al-Hakim (1689), and al-Bayhaqi (5/86).","chapter_en":"Drinking during circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":124,"content":{"translation":{"en":["Ibn Abbas narrated that the Prophet ﷺ drank water during circumambulation."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2750},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5463,"n":5459},{"key":"hakim","label":"المستدرك على الصحيحين","number":1689,"n":1679},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":9297,"n":9376}]},{"num":5228,"demo":false,"sanad":"","matn":["عن بكر بن عبد الله المزني، قال: كنتُ جالسًا مع ابن عباس عند الكعبة، فأتاه أعرابيٌّ فقال: ما لي أرى بني عمّكم يسقون العسل واللبن، وأنتم تسقون النبيذ؟ أمِن حاجةٍ بكم أم من بخل؟ فقال ابن عباس: الحمد لله، ما بنا من حاجةٍ ولا بخل. قدم النبيُّ ﷺ على راحلته وخلفه أسامة، فاستسقى، فأتيناه بإناءٍ من نبيذ، فشرب وسقى فضلَه أسامة، وقال: (( أحسنتم وأجملتم، كذا فاصنعوا )). فلا نريد تغيير ما أمر به رسولُ اللّٰه ﷺ."],"takhrij":"صحيح: رواه مسلم (١٣١٦).","grade":"صحيح","chapter_ar":"باب ما جاء في سقاية النبيذ وغيره للحجاج والمعتمرين","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1316).","chapter_en":"What has been reported about giving nabidh and other drinks to pilgrims for Hajj and Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":125,"content":{"translation":{"en":["Bakr ibn Abd Allah al-Muzani said: I was sitting with Ibn Abbas near the Ka‘bah when a Bedouin came to him and said: Why do I see your cousins serving honey and milk while you serve nabidh? Is it because of need or miserliness? Ibn Abbas said: Praise be to Allah, we are neither in need nor miserly. The Prophet ﷺ came riding, with Usamah behind him, and he asked for something to drink. So we brought him a vessel of nabidh. He drank and gave the remainder to Usamah to drink, and said: “You have done well and acted excellently; keep doing this.” So we do not wish to change what the Messenger of Allah ﷺ commanded."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1316}]},{"num":5229,"demo":false,"sanad":"","matn":["عن عائشة، قالت: فطاف الذين أهلُّوا بالعمرة بالبيت، وبالصفا والمروة، ثم حلُّوا، ثم طافوا طوافًا آخر بعد أن رجعوا من منى لحجهم. وأما الذين كانوا جمعوا الحجَّ والعمرة، فإنما طافوا طوافًا واحدًا… الحديث."],"takhrij":"متفق عليه: رواه البخاري (١٥٥٦)، ومسلم (١٢١١/١١١).","grade":"متفق عليه","chapter_ar":"باب وجوب السعي على المتمتع بعد طواف الإفاضة بخلاف القارن فإن عليه سعيًا واحدًا","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1556) and Muslim (1211/111).","chapter_en":"The obligation of sa‘i upon the one doing tamattu‘ after the circumambulation of al-Ifadah, unlike the one doing qiran, for whom one sa‘i is sufficient","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":126,"content":{"translation":{"en":["Aishah said: Those who entered consecration for Umrah circumambulated the House and went between al-Safa and al-Marwah, then they exited consecration. Then they did another circumambulation after returning from Mina for their Hajj. As for those who had combined Hajj and Umrah, they only performed one circumambulation … the hadith."]},"buhuth":{"ar":["وقولها: (( فإنما طافوا طوافًا واحدًا )) أي سعيًا واحدًا، والطواف هنا المقصود به السعي."],"en":["Her statement, “they only performed one circumambulation,” means one sa‘i; here the intended meaning of circumambulation is sa‘i."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1556},{"key":"muslim","label":"مسلم","number":1211}]},{"num":5230,"demo":false,"sanad":"","matn":["عن ابن عمر أنه كان يرمي الجمرة الدنيا بسبع حصيات، يكبِّر على إثر كل حصاة، ثم يتقدم حتى يسهل، فيقوم مستقبل القبلة، فيقوم طويلًا، ويدعو ويرفع يديه، ثم يرمي الوسطى، ثم يأخذ ذات الشمال فيستهل، ويقوم مستقبل القبلة، فيقوم طويلًا، ويدعو ويرفع يديه، ويقوم طويلًا، ثم يرمي جمرة ذات العقبة من بطن الوادي، ولا يقف عندها، ثم ينصرف، ويقول: هكذا رأيتُ النبيَّ ﷺ يفعله."],"takhrij":"صحيح: رواه البخاري (١٧٥١).","grade":"صحيح","chapter_ar":"باب رمي الجمار الثلاثة أيام التشريق وكيفية ذلك والوقت المختار له","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1751).","chapter_en":"Stoning the three pillars during the Days of Tashriq, how it is done, and its preferred time","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":127,"content":{"translation":{"en":["Ibn Umar used to stone the first pillar with seven pebbles, saying Allahu Akbar after each pebble. Then he would go forward to an open place and stand facing the qiblah for a long time, supplicating and raising his hands. Then he would stone the middle pillar, then move to the left side to an open place and stand facing the qiblah for a long time, supplicating and raising his hands. Then he would stone Jamrat al-‘Aqabah from the bottom of the valley and would not stop there. Then he would leave, saying: This is how I saw the Prophet ﷺ do it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1751}]},{"num":5231,"demo":false,"sanad":"","matn":["عن وبرة، قال: سألتُ ابن عمر رضي اللّٰه عنهما: متى أرمي الجمار؟ قال: إذا رمى إمامُك فارمِه. فأعدتُ عليه المسألة، قال: كنا نتحيَّن، فإذا زالت الشمس رمينا."],"takhrij":"صحيح: رواه البخاري (١٧٤٦).","grade":"صحيح","chapter_ar":"باب رمي الجمار الثلاثة أيام التشريق وكيفية ذلك والوقت المختار له","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1746).","chapter_en":"Stoning the three pillars during the Days of Tashriq, how it is done, and its preferred time","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":127,"content":{"translation":{"en":["Wabrah said: I asked Ibn Umar, may Allah be pleased with them both: When should I stone the pillars? He said: When your imam stones them, then stone. I repeated the question to him, and he said: We used to wait attentively, and when the sun had passed its zenith, we stoned them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1746}]},{"num":5232,"demo":false,"sanad":"","matn":["عن جابر، قال: رمى رسولُ اللّٰه ﷺ الجمرة يوم النحر ضحًى، وأما بعدُ فإذا زالت الشمس."],"takhrij":"صحيح: رواه مسلم (١٢٩٩/٣١٤).","grade":"صحيح","chapter_ar":"باب رمي الجمار الثلاثة أيام التشريق وكيفية ذلك والوقت المختار له","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1299/314).","chapter_en":"Stoning the three pillars during the Days of Tashriq, how it is done, and its preferred time","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":127,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ stoned the pillar on the Day of Sacrifice in the forenoon, but after that, it was done when the sun passed its zenith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1299}]},{"num":5233,"demo":false,"sanad":"","matn":["عن عائشة قالت:","أفاض رسول الله ﷺ من آخر يومه حين صلى الظهر، ثم رجع إلى منى، فمكث بها ليالي أيام التشريق، يرمي الجمرة إذا زالت الشمس، كل جمرة بسبع حصيات، يكبر مع كل حصاة، ويقف عند الأولى والثانية، فيطيل القيام، ويتضرع، ويرمي الثالثة، ولا يقف عندها."],"takhrij":"حسن: رواه أبو داود (١٩٧٣)، وأحمد (٢٤٥٩٢)، وصححه ابن خزيمة (٢٩٥٦)، وابن حبان (٣٨٦٨).","grade":"حسن","chapter_ar":"باب رمي الجمار الثلاثة أيام التشريق وكيفية ذلك والوقت المختار له","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1973) and Aḥmad (24592), and authenticated by Ibn Khuzaymah (2956) and Ibn Ḥibbān (3868).","chapter_en":"Stoning the three pillars during the Days of Tashriq, how it is done, and its preferred time","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":127,"content":{"translation":{"en":["ʿĀʾishah reported:","The Messenger of Allah ﷺ performed the Ṭawāf of Ifāḍah toward the latter part of the day after he had prayed Ẓuhr. He then returned to Minā and remained there during the nights of the Days of Tashrīq.","He would stone the Jamarāt after the sun had passed its zenith, throwing seven pebbles at each Jamrah and saying “Allāhu Akbar” with every pebble.","He would stop after the first and second Jamarah, prolong his standing and supplicate humbly. He would stone the third Jamarah and would not stop there."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1973},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2956},{"key":"ibnhibban","label":"ابن حبان","number":3868},{"key":"ahmad","label":"مسند الإمام أحمد","number":24592,"n":24592}]},{"num":5234,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر: أن العباس استأذن النبيَّ ﷺ ليبيت بمكة ليالي منى من أجل سقايته، فأذن له."],"takhrij":"متفق عليه: رواه البخاري (١٧٤٥)، ومسلم (١٣١٥).","grade":"متفق عليه","chapter_ar":"باب المبيت بمنى أيام التشريق والرخصة لأصحاب السقاية في المبيت بمكة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1745) and Muslim (1315).","chapter_en":"Spending the nights at Mina during the Days of Tashriq, and the concession for those responsible for providing water to spend the night in Makkah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":128,"content":{"translation":{"en":["Abdullah ibn Umar narrated that al-Abbas asked the Prophet ﷺ for permission to spend the nights of Mina in Makkah because of his duty of providing water, and he gave him permission."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1745},{"key":"muslim","label":"مسلم","number":1315}]},{"num":5235,"demo":false,"sanad":"","matn":["عن عاصم بن عديّ: أن رسولَ اللّٰه ﷺ رخَّص لرعاء الإبل في البيتوتة خارجين عن منى، يرمون يوم النحر، ثم يرمون الغد، ومن بعد الغد ليومين، ثم يرمون يوم النفر."],"takhrij":"صحيح: رواه مالك (٢١٨)، وأبو داود (١٩٧٥)، والترمذي (٩٥٥)، والنسائي (٣٠٦٩)، وابن ماجه (٣٠٣٧).","grade":"صحيح","chapter_ar":"باب الرخصة لرعاة الإبل أن يؤخروا رمي اليوم الحادي عشر إلى الثاني عشر وأن يرموا بالليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (218), Abu Dawud (1975), al-Tirmidhi (955), al-Nasa’i (3069), and Ibn Majah (3037).","chapter_en":"The concession for camel herders to delay the stoning of the eleventh day until the twelfth, and to stone at night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":129,"content":{"translation":{"en":["Asim ibn Adiyy narrated that the Messenger of Allah ﷺ gave camel herders a concession to spend the night outside Mina. They were to stone on the Day of Sacrifice, then stone the next day, and the day after that for two days together, then stone on the Day of Departure."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":218},{"key":"abudawud","label":"أبو داود","number":1975},{"key":"tirmidhi","label":"الترمذي","number":955},{"key":"nasai","label":"النسائي","number":3069},{"key":"ibnmajah","label":"ابن ماجه","number":3037}]},{"num":5236,"demo":false,"sanad":"","matn":["عن ابن عمر: أن رسولَ اللّٰه ﷺ رخَّص لرعاء الإبل أن يرموا بالليل."],"takhrij":"حسن: رواه البزار - كشف الأستار (١١٣٩)، والبيهقي (٥/١٥١).","grade":"حسن","chapter_ar":"باب الرخصة لرعاة الإبل أن يؤخروا رمي اليوم الحادي عشر إلى الثاني عشر وأن يرموا بالليل","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1139) and al-Bayhaqi (5/151).","chapter_en":"The concession for camel herders to delay the stoning of the eleventh day until the twelfth, and to stone at night","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":129,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ gave camel herders a concession to stone at night."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1139},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1139,"n":1139}]},{"num":5237,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: أُمِرَ النَّاسُ أَنْ يَكُونَ آخِرُ عَهْدِهِمْ بِالْبَيْتِ، إِلَّا أَنَّهُ خُفِّفَ عَنِ الْحَائِضِ."],"takhrij":"متفق عليه: رواه البخاري (١٧٥٥)، ومسلم (١٣٢٨/٣٨٠).","grade":"متفق عليه","chapter_ar":"باب ما جاء في طواف الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1755) and Muslim (1328/380).","chapter_en":"What has been reported concerning the Farewell Circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":130,"content":{"translation":{"en":["Abdullah ibn Abbas said: The people were commanded that their last act should be at the House, except that this was lightened for the menstruating woman."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1755},{"key":"muslim","label":"مسلم","number":1328}]},{"num":5238,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: كان الناس ينصرفون في كل وجه، فقال رسول الله ﷺ: (( لا ينفرنَّ أحدٌ حتى يكون آخرَ عهده بالبيت ))."],"takhrij":"صحيح: رواه مسلم (١٣٢٧).","grade":"صحيح","chapter_ar":"باب ما جاء في طواف الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1327).","chapter_en":"What has been reported concerning the Farewell Circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":130,"content":{"translation":{"en":["Abdullah ibn Abbas said: The people used to depart in every direction, so the Messenger of Allah ﷺ said: “No one should depart until his last act is at the House.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1327}]},{"num":5239,"demo":false,"sanad":"","matn":["عن عائشة، أنها قالت لرسول الله ﷺ: يا رسول الله، إن صفية بنت حيي قد حاضت. قال رسول الله ﷺ: (( لعلها تحبسنا، ألم تكن طافت معكن؟ )) فقالوا: بلى. قال: (( فاخرجي ))."],"takhrij":"متفق عليه: رواه مالك (٢٢٦)، والبخاري (٣٢٨) و(١٥٦١)، ومسلم (١٢١١/١٢٨).","grade":"متفق عليه","chapter_ar":"باب ما جاء في طواف الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (226), al-Bukhari (328, 1561), and Muslim (1211/128).","chapter_en":"What has been reported concerning the Farewell Circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":130,"content":{"translation":{"en":["Aishah said to the Messenger of Allah ﷺ: O Messenger of Allah ﷺ, Safiyyah bint Huyayy has begun menstruating. The Messenger of Allah ﷺ said: “Perhaps she will hold us back. Did she not perform tawaf with you?” They said: Yes. He said: “Then go out.”"]},"buhuth":{"ar":["وفي آخره عند مسلم قالت صفية: (( ما أُراني إلا حابستكم؟ )) قال: (( عقرى حلقى، أوما كنتِ طفتِ يوم النحر؟ )) قالت: بلى. قال: (( لا بأس، انفري )).","قوله: (( عقرى حلقى )) قيل: يعني أصابها الله بوجعٍ وعقر."],"en":["And in the ending of Muslim’s version, Safiyyah said: “I think I will only hold you back.” He said: “May distress and trouble be upon you. Did you not perform tawaf on the Day of Sacrifice?” She said: Yes. He said: “Then there is no problem. Depart.”","His statement, “Aqra halqa,” has been explained as an expression meaning: may she be afflicted with pain and distress."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":226},{"key":"bukhari","label":"البخاري","number":328},{"key":"و","label":"و","number":1561},{"key":"muslim","label":"مسلم","number":1211}]},{"num":5240,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خرجنا مع رسول الله ﷺ في ليالي الحج، وذكرت الحديث، قالت: حتى نفرنا من منى، فنزلنا المحصَّب، فدعا عبد الرحمن، فقال: (( اخرج بأختك من الحرم، فلْتُهِلَّ بعمرة، ثم افرغا من طوافكما، أنتظركما هاهنا )). فأتينا في جوف الليل، فقال: (( فرغتما؟ )) قلت: نعم. فآذن بالرحيل في أصحابه، فخرج فمرَّ بالبيت، فطاف به قبل صلاة الصبح، ثم خرج إلى المدينة."],"takhrij":"متفق عليه: رواه البخاري (١٧٨٨)، ومسلم (١٢١١/١٢٣). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في طواف الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1788) and Muslim (1211/123). The wording is that of Muslim.","chapter_en":"What has been reported concerning the Farewell Circumambulation","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":130,"content":{"translation":{"en":["Aishah said: We went out with the Messenger of Allah ﷺ during the nights of Hajj, and she mentioned the hadith. She said: Then when we departed from Mina, we stopped at al-Muhassab. He called Abd al-Rahman and said: “Take your sister out of the sanctuary so that she may enter ihram for Umrah, then both of you complete your tawaf, and I will wait for you here.” We came back in the depth of the night, and he said: “Have you both finished?” I said: Yes. Then he announced departure to his companions. He went out, passed by the House, and performed tawaf before the Fajr prayer, then departed to Madinah."]},"buhuth":{"ar":["وفي صحيح ابن خزيمة (٢٩٩٨) من طريق أفلح بن حميد: فارتحل الناس، فمرَّ بالبيت قبل صلاة الصبح، فطاف به، ثم خرج فركب، ثم انصرف متوجهاً إلى المدينة.","وأما لو أخَّر الإنسان طواف الإفاضة، فإذا عزم على السفر طاف عند سفره بعد ما رمى الجمار وانتهى من كل شيء، فإن طواف الإفاضة يجزئه عن طواف الوداع إذا نوى بطوافه عنهما جميعاً."],"en":["In Sahih Ibn Khuzaymah (2998), by the route of Aflah ibn Humayd: The people set out, and he passed by the House before the Fajr prayer, performed tawaf, then went out, mounted, and departed toward Madinah.","As for the one who delays the Tawaf of Ifadah, then when he intends to travel he may perform tawaf at the time of his departure after finishing the stoning of the pillars and everything else. In that case, the Tawaf of Ifadah is sufficient in place of the Farewell Tawaf if he intends both with that tawaf."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1788},{"key":"muslim","label":"مسلم","number":1211}]},{"num":5241,"demo":false,"sanad":"","matn":["عن عائشة، أنها قالت لرسول الله ﷺ: يا رسول الله، إن صفية بنت حيي قد حاضت؟ قال رسول الله ﷺ: (( لعلها تحبسنا، ألم تكن طافت معكن؟ )) فقالوا: بلى. قال: (( فاخرجي ))."],"takhrij":"متفق عليه: رواه مالك (٢٢٦)، والبخاري (٣٢٨) و(١٥٦١)، ومسلم (١٢١١/١٢٨).","grade":"متفق عليه","chapter_ar":"باب سقوط طواف الوداع عن الحائض إلا الإفاضة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (226), al-Bukhari (328, 1561), and Muslim (1211/128).","chapter_en":"The dropping of the Farewell Tawaf for the menstruating woman, except the Tawaf of Ifadah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":131,"content":{"translation":{"en":["Aishah said to the Messenger of Allah ﷺ: O Messenger of Allah ﷺ, Safiyyah bint Huyayy has menstruated. The Messenger of Allah ﷺ said: “Perhaps she will hold us back. Did she not perform tawaf with you?” They said: Yes. He said: “Then go out.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":226},{"key":"bukhari","label":"البخاري","number":328},{"key":"و","label":"و","number":1561},{"key":"muslim","label":"مسلم","number":1211}]},{"num":5242,"demo":false,"sanad":"","matn":["عن عكرمة: أن أهل المدينة سألوا ابن عباس رضي الله عنهما عن امرأة طافت ثم حاضت؟ فقال لهم: تنفر. قالوا: لا نأخذ بقولك وندع قول زيد. قال: إذا قدمتم المدينة فسلوا. فقدموا المدينة فسألوا، فكان فيمن سألوا أم سليم، فذكرت حديث صفية."],"takhrij":"متفق عليه: رواه البخاري (١٧٥٨، ١٧٥٩)، ومسلم (١٣٢٨/٣٨١).","grade":"متفق عليه","chapter_ar":"باب سقوط طواف الوداع عن الحائض إلا الإفاضة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1758, 1759) and Muslim (1328/381).","chapter_en":"The dropping of the Farewell Tawaf for the menstruating woman, except the Tawaf of Ifadah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":131,"content":{"translation":{"en":["Ikrimah said: The people of Madinah asked Ibn Abbas, may Allah be pleased with them both, about a woman who had performed tawaf and then menstruated. He said to them: She may depart. They said: We will not leave the statement of Zayd for your statement. He said: Then when you reach Madinah, ask. So they came to Madinah and asked, and among those they asked was Umm Sulaym, and she mentioned the hadith of Safiyyah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1758},{"key":"muslim","label":"مسلم","number":1328}]},{"num":5243,"demo":false,"sanad":"","matn":["عن طاوس بن كيسان، قال: سمعت ابن عمر يقول: إنها لا تنفر. ثم سمعته يقول بعدُ: إن النبيَّ ﷺ رخَّص لهن."],"takhrij":"صحيح: رواه البخاري (١٧٦٠، ١٧٦١).","grade":"صحيح","chapter_ar":"باب سقوط طواف الوداع عن الحائض إلا الإفاضة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1760, 1761).","chapter_en":"The dropping of the Farewell Tawaf for the menstruating woman, except the Tawaf of Ifadah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":131,"content":{"translation":{"en":["Tawus ibn Kaysan said: I heard Ibn Umar say: She should not depart. Then later I heard him say: The Prophet ﷺ gave them permission."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1760}]},{"num":5244,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: من حج البيت فليكن آخر عهده بالبيت إلا الحيض، رخَّص لهن رسول الله ﷺ."],"takhrij":"صحيح: رواه الترمذي (٩٤٤)، وابن خزيمة (٣٠٠٠)، وابن حبان (٣٨٩٩). قال الترمذي: هذا حديث حسن صحيح.","grade":"صحيح","chapter_ar":"باب سقوط طواف الوداع عن الحائض إلا الإفاضة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (944), Ibn Khuzaymah (3000), and Ibn Hibban (3899). Al-Tirmidhi said: This is a Hasan Sahih hadith.","chapter_en":"The dropping of the Farewell Tawaf for the menstruating woman, except the Tawaf of Ifadah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":131,"content":{"translation":{"en":["Ibn Umar said: Whoever performs pilgrimage to the House, let his last act be at the House, except for menstruating women; the Messenger of Allah ﷺ gave them a concession."]},"buhuth":{"ar":["وأما المرأة التي حاضت اليوم العاشر أو قبله من شهر ذي الحجة ولم تتمكن من طواف الإفاضة، فهي لا تخلو من حالين:","إحداهما: أنها من سكان مكة أو ما جاورها من المدن، وتستطيع أن تعود إلى مكة بعد طهرها لطواف الإفاضة، فلها أن ترحل إلى بيتها، وتبقى على إحرامها حتى تطهر، ثم ترجع إلى مكة فتطوف طواف الإفاضة؛ لأن التحلل الكامل لا يتم إلا بطواف الإفاضة، على أن لا تؤخره عن نهاية شهر ذي الحجة، الذي هو آخر أشهر الحج في أصح أقوال أهل العلم. قال الله تعالى: {الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ} [البقرة: ١٩٧]، يعني: شوال، وذو القعدة، وذو الحجة.","الثانية: أنها تكون من بلاد بعيدة، وهي مرتبطة بمواعيد الرحلات وضرورة المغادرة مع الجملة، ولا تستطيع أن تجلس في مكة حتى تطهر وتطوف، أو أن ترجع إلى مكة بعد طهرها، فلها أن تغتسل كما تغتسل للإحرام، وتستثفر كما تستثفر المستحاضة، وتطوف طواف الإفاضة، وتجبر ذلك بدم كما قال به بعض الفقهاء؛ لأن الطهارة في الطواف ليست فرضاً ولا شرطاً، وإنما هي واجبة، وترك الواجب يجبر بالدم.","وذهب شيخ الإسلام ابن تيمية رحمه الله تعالى إلى صحة طوافها، فلا يلزمها دم؛ لأنها ليست مفرِّطة، ولا كفارة عليها فيما لا تفريط فيه.","وبه أفتى كثير من أهل العلم في المملكة العربية السعودية، والشام، ومصر وغيرها.","ومن شدد في ذلك فقد ذهل عن مقاصد الشريعة وهي رفع الحرج، قال الله تعالى: {وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ} [الحج: ٧٨].","وأي حرج يكون أعظم من أن تؤمر الحائض أن تبقى في مكة حتى تطهر وتطوف طواف الإفاضة، ولو فاتتها المغادرة مع الرفقاء، وترتب على ذلك إلغاء حجوزاتها الجوية أو البحرية أو البرية؟ والله المستعان."],"en":["As for the woman who menstruates on the tenth day of Dhu al-Hijjah or before it and cannot perform the Tawaf of Ifadah, her case falls into one of two situations:","The first is that she is from Makkah or a nearby city and can return to Makkah after becoming pure to perform the Tawaf of Ifadah. In that case, she may go back to her home and remain in her ihram until she becomes pure, then return to Makkah and perform the Tawaf of Ifadah, because complete release from ihram is not attained except by the Tawaf of Ifadah, provided that she does not delay it beyond the end of Dhu al-Hijjah, which is the last of the months of Hajj according to the strongest view of the scholars. Allah Most High said: {Hajj is during well-known months} [al-Baqarah: 197], meaning Shawwal, Dhu al-Qadah, and Dhu al-Hijjah.","The second is that she is from a distant land and is bound by travel schedules and the necessity of departing with her group, and she cannot remain in Makkah until she becomes pure and performs tawaf, nor can she return to Makkah after becoming pure. In that case, she may bathe as one bathes for ihram, bind herself as a woman with continuous bleeding does, and perform the Tawaf of Ifadah, compensating for that with a sacrifice, as some jurists held. This is because purity in tawaf is not an absolute pillar or condition according to this view, but rather an obligation, and leaving an obligation is compensated by a sacrifice.","Shaykh al-Islam Ibn Taymiyyah, may Allah have mercy on him, held that her tawaf is valid, so no sacrifice is required of her, because she is not negligent, and there is no expiation for what involves no negligence.","This is the fatwa given by many scholars in Saudi Arabia, Greater Syria, Egypt, and elsewhere.","Whoever is overly strict in this has overlooked the objectives of the Sacred Law, among which is the removal of hardship. Allah Most High said: {He has not placed upon you in the religion any hardship} [al-Hajj: 78].","What hardship could be greater than commanding a menstruating woman to remain in Makkah until she becomes pure and performs the Tawaf of Ifadah, even if she misses departure with her companions and this leads to the cancellation of her air, sea, or land travel arrangements? Allah is the One whose help is sought."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":944},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":3000},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5887,"n":5884}]},{"num":5245,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: بعثني أبو بكر رضي الله عنه فيمن يؤذِّن يوم النحر بمنى: (( لا يحج بعد العام مشرك، ولا يطوف بالبيت عريان )). ويوم الحج الأكبر يوم النحر. وإنما قيل الأكبر من أجل قول الناس: الحج الأصغر. فنبذ أبو بكر إلى الناس في ذلك العام، فلم يحج عام حجة الوداع الذي حج فيه النبي ﷺ مشرك."],"takhrij":"متفق عليه: رواه البخاري (٣١٧٧) و(٤٦٥٧)، ومسلم (١٣٤٧).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الحج الأكبر بأنه يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3177, 4657) and Muslim (1347).","chapter_en":"What has been reported that the Greater Pilgrimage is the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":132,"content":{"translation":{"en":["Abu Hurayrah said: Abu Bakr, may Allah be pleased with him, sent me among those who proclaimed on the Day of Sacrifice at Mina: “No polytheist shall perform pilgrimage after this year, and no naked person shall circumambulate the House.” And the Day of the Greater Pilgrimage is the Day of Sacrifice. It was only called greater because people used to say “the lesser pilgrimage.” So Abu Bakr announced this to the people that year, and no polytheist performed pilgrimage in the year of the Farewell Pilgrimage in which the Prophet ﷺ performed Hajj."]},"intro":{"ar":["قال الله تعالى: {وَأَذَانٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى النَّاسِ يَوْمَ الْحَجِّ الْأَكْبَرِ} [سورة التوبة: ٣]."],"en":["Allah Most High said: {And a proclamation from Allah and His Messenger to the people on the Day of the Greater Pilgrimage} [Surat al-Tawbah: 3]."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3177},{"key":"و","label":"و","number":4657},{"key":"muslim","label":"مسلم","number":1347}]},{"num":5246,"demo":false,"sanad":"","matn":["عن ابن عمر، أن النبيَّ ﷺ وقف يوم النحر بين الجمرات في الحجة التي حج، فقال: (( أي يوم هذا؟ )) قالوا: يوم النحر. قال: (( هذا يوم الحج الأكبر ))."],"takhrij":"صحيح: رواه أبو داود (١٩٤٥)، وابن ماجه (٣٠٥٨)، وصححه الحاكم (٣٢٧٦). واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب ما جاء في الحج الأكبر بأنه يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1945), Ibn Majah (3058), and authenticated by al-Hakim (3276). The wording is that of Abu Dawud.","chapter_en":"What has been reported that the Greater Pilgrimage is the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":132,"content":{"translation":{"en":["Ibn Umar narrated that the Prophet ﷺ stood on the Day of Sacrifice between the pillars during the pilgrimage he performed and said: “What day is this?” They said: The Day of Sacrifice. He said: “This is the Day of the Greater Pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1945},{"key":"ibnmajah","label":"ابن ماجه","number":3058},{"key":"hakim","label":"المستدرك على الصحيحين","number":3276,"n":3263}]},{"num":5247,"demo":false,"sanad":"","matn":["عن رجل من أصحاب النبي ﷺ قال: خطبنا رسول الله ﷺ يوم النحر على ناقة له حمراء مخضرمة، فقال: (( هذا يوم النحر، وهذا يوم الحج الأكبر ))."],"takhrij":"صحيح: رواه الإمام أحمد (١٥٨٨).","grade":"صحيح","chapter_ar":"باب ما جاء في الحج الأكبر بأنه يوم النحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (1588).","chapter_en":"What has been reported that the Greater Pilgrimage is the Day of Sacrifice","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":132,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: The Messenger of Allah ﷺ addressed us on the Day of Sacrifice while on a reddish she-camel of his whose ear-tip had been cut, saying: “This is the Day of Sacrifice, and this is the Day of the Greater Pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":1588},{"key":"ahmad","label":"مسند الإمام أحمد","number":15886,"n":15886}]},{"num":5248,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: فأجاز رسول الله ﷺ حتى أتى عرفة، فوجد القبة قد ضُربت له بنمرة فنزل بها، حتى إذا زاغت الشمس أمر بالقصواء فرُحلت له، فأتى بطن الوادي، فخطب الناس وقال: (( إن دماءكم وأموالكم حرام عليكم كحرمة يومكم هذا في شهركم هذا في بلدكم هذا. ألا كل شيء من أمر الجاهلية تحت قدمي موضوع، ودماء الجاهلية موضوعة، وإن أول دم أضع من دمائنا دم ابن ربيعة بن الحارث - كان مسترضعاً في بني سعد فقتلته هذيل - وربا الجاهلية موضوع، وأول ربا أضع ربانا ربا عباس بن عبد المطلب، فإنه موضوع كله. فاتقوا الله في النساء، فإنكم أخذتموهن بأمان الله، واستحللتم فروجهن بكلمة الله، ولكم عليهن ألا يوطئن فرشكم أحداً تكرهونه، فإن فعلن ذلك فاضربوهن ضرباً غير مبرح، ولهن عليكم رزقهن وكسوتهن بالمعروف. وقد تركت فيكم ما لن تضلوا بعده إن اعتصمتم به: كتاب الله، وأنتم تُسألون عني، فما أنتم قائلون؟ )) قالوا: نشهد أنك قد بلغت وأديت ونصحت. فقال بإصبعه السبابة يرفعها إلى السماء وينكتها إلى الناس: (( اللهم اشهد، اللهم اشهد )) ثلاث مرات. ثم أذَّن، ثم أقام فصلّى الظهر، ثم أقام فصلّى العصر، ولم يصل بينهما شيئاً."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ continued until he came to Arafah, and he found that a tent had been pitched for him at Namirah, so he stayed there. When the sun passed the zenith, he ordered that al-Qaswa’ be saddled for him. Then he came to the middle of the valley and addressed the people, saying: “Indeed, your blood and your wealth are sacred to you, as sacred as this day of yours, in this month of yours, in this land of yours. Truly, everything belonging to the pre-Islamic age is placed beneath my feet and abolished. The blood claims of the pre-Islamic age are abolished, and the first blood claim I abolish of our own is the blood of Ibn Rabiah ibn al-Harith — he was being nursed among Banu Sad and Hudhayl killed him. And the usury of the pre-Islamic age is abolished, and the first usury I abolish is our own usury, the usury of al-Abbas ibn Abd al-Muttalib; it is all abolished. So fear Allah regarding women, for you took them by the trust of Allah, and made their private parts lawful by the word of Allah. Your right over them is that they should not allow anyone you dislike to sit upon your bedding. If they do that, then discipline them with a strike that is not severe. And their right over you is provision and clothing according to what is right. I have left among you that by which you will never go astray after me if you hold firmly to it: the Book of Allah. And you will be asked about me, so what will you say?” They said: We bear witness that you conveyed, fulfilled, and gave sincere counsel. So he raised his forefinger toward the sky and pointed it toward the people, saying: “O Allah, bear witness. O Allah, bear witness,” three times. Then the call to prayer was given, then the iqamah was given and he prayed Zuhr, then the iqamah was given and he prayed Asr, and he prayed nothing between them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5249,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: قال رسول الله ﷺ في حجته: (( أيُّ يوم أعظم حرمة؟ )) قالوا: يومنا هذا. قال: (( فأيُّ شهر أعظم حرمة؟ )) قالوا: شهرنا هذا. قال: (( فأيُّ بلد أعظم حرمة؟ )) قالوا: بلدنا هذا. قال: (( فإن دماءكم وأموالكم عليكم حرام كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا ))."],"takhrij":"صحيح: رواه الإمام أحمد (١٤٣٦٥). ورواه أيضاً (١٤٩٩٠) وفيه: (( فإن دماءكم وأموالكم عليكم حرام كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا. هل بلغت؟ )) قالوا: نعم. قال: (( اللهم اشهد )).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (14365). He also narrated it (14990) with the wording: “Indeed your blood and your wealth are sacred to you like the sacredness of this day of yours, in this land of yours, in this month of yours. Have I conveyed?” They said: Yes. He said: “O Allah, bear witness.”","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ said during his pilgrimage: “What day is greatest in sacredness?” They said: This day of ours. He said: “What month is greatest in sacredness?” They said: This month of ours. He said: “What land is greatest in sacredness?” They said: This land of ours. He said: “Then indeed your blood and your wealth are sacred to you like the sacredness of this day of yours, in this month of yours, in this land of yours.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":14365},{"key":"ورواہ_ایضا","label":". ورواه أيضاً","number":14990},{"key":"ahmad","label":"مسند الإمام أحمد","number":14365,"n":14365}]},{"num":5250,"demo":false,"sanad":"","matn":["عن أبي بكرة، قال: خطبنا النبيُّ ﷺ يوم النحر، قال: (( أتدرون أيُّ يوم هذا؟ )) قلنا: الله ورسوله أعلم. فسكت حتى ظننا أنه سيسميه بغير اسمه. قال: (( أليس يوم النحر؟ )) قلنا: بلى. قال: (( أيُّ شهر هذا؟ )) قلنا: الله ورسوله أعلم. فسكت حتى ظننا أنه سيسميه بغير اسمه. فقال: (( أليس ذو الحجة؟ )) قلنا: بلى. قال: (( أيُّ بلد هذا؟ )) قلنا: الله ورسوله أعلم. فسكت حتى ظننا أنه سيسميه بغير اسمه. قال: (( أليست بالبلدة الحرام؟ )) قلنا: بلى. قال: (( فإن دماءكم وأموالكم عليكم حرام كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا، إلى يوم تلقون ربكم. ألا هل بلغت؟ )) قالوا: نعم. قال: (( اللهم اشهد. فليبلِّغ الشاهد الغائب، فربَّ مبلَّغ أوعى من سامع. فلا ترجعوا بعدي كفاراً يضرب بعضكم رقاب بعض ))."],"takhrij":"متفق عليه: رواه البخاري (١٧٤١)، ومسلم (١٦٧٩/٣١). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1741) and Muslim (1679/31). The wording is that of al-Bukhari.","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu Bakrah said: The Prophet ﷺ addressed us on the Day of Sacrifice and said: “Do you know what day this is?” We said: Allah and His Messenger know best. He remained silent until we thought he would name it with some other name. He said: “Is it not the Day of Sacrifice?” We said: Yes. He said: “What month is this?” We said: Allah and His Messenger know best. He remained silent until we thought he would name it with some other name. Then he said: “Is it not Dhu al-Hijjah?” We said: Yes. He said: “What land is this?” We said: Allah and His Messenger know best. He remained silent until we thought he would call it by another name. He said: “Is it not the sacred city?” We said: Yes. He said: “Then indeed your blood and your wealth are sacred to you like the sacredness of this day of yours, in this month of yours, in this land of yours, until the day you meet your Lord. Have I conveyed?” They said: Yes. He said: “O Allah, bear witness. So let the one present convey to the one absent, for perhaps the one to whom it is conveyed may understand it better than the one who heard it. Do not return after me as disbelievers, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1741},{"key":"muslim","label":"مسلم","number":1679}]},{"num":5251,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص، قال: إن النبيَّ ﷺ بينما هو واقف يخطب يوم النحر، فقام إليه رجل فقال: ما كنت أحسب يا رسول الله أن كذا وكذا قبل كذا وكذا. ثم جاء آخر فقال: يا رسول الله، كنت أحسب أن كذا قبل كذا وكذا، لهؤلاء الثلاث. قال: (( افعل ولا حرج ))."],"takhrij":"متفق عليه: رواه البخاري (١٧٣٧)، ومسلم (١٣٠٦).","grade":"متفق عليه","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1737) and Muslim (1306).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As said: While the Prophet ﷺ was standing and delivering a sermon on the Day of Sacrifice, a man stood up to him and said: O Messenger of Allah ﷺ, I did not think that such-and-such was before such-and-such. Then another came and said: O Messenger of Allah ﷺ, I thought that such-and-such came before such-and-such, regarding these three matters. He said: “Do it, and there is no harm.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1737},{"key":"muslim","label":"مسلم","number":1306}]},{"num":5252,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جدّه، قال: كانت العرب يجعلون عاماً شهراً، وعامين شهرين، فلا يصيبون الحج في أيام الحج إلا في خمسٍ وعشرين سنة مرة، وهو النسيء الذي ذكره الله في كتابه. فلما حج أبو بكر بالناس وافق العام الحج، فسمّاه الله الحج الأكبر، وحج رسول الله ﷺ من العام المقبل، فاستقبل الناس الأهلة. فقال رسول الله ﷺ: (( إن الزمان قد استدار كهيئته يوم خلق الله السماوات والأرض ))."],"takhrij":"حسن: رواه الطحاوي في شرح مشكل الآثار (١٤٥٧).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Sharh Mushkil al-Athar (1457).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Amr ibn Shuayb, from his father, from his grandfather, said: The Arabs used to make one year into a month and two years into two months, so the pilgrimage would only coincide with its proper days once every twenty-five years. This is the postponement mentioned by Allah in His Book. So when Abu Bakr led the people in pilgrimage, that year coincided with the proper time of Hajj, and Allah called it the Greater Pilgrimage. Then the Messenger of Allah ﷺ performed Hajj the following year, and the people faced the moons in their proper order. So the Messenger of Allah ﷺ said: “Time has returned to its original order as it was the day Allah created the heavens and the earth.”"]},"buhuth":{"ar":["قال بعض أهل العلم: إنما أخَّر النبي ﷺ الحج ليوافق أهل الحساب، فلما استدار الزمان كهيئته حجَّ النبي ﷺ ليوافق حجُّ الناس بعده إلى يوم القيامة."],"en":["Some scholars said: The Prophet ﷺ only delayed Hajj so that it would match the correct reckoning, and when time returned to its original order, the Prophet ﷺ performed Hajj so that the pilgrimage of the people after him would continue in its proper time until the Day of Resurrection."]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرح_مشکل_الاثار","label":"الطحاوي في شرح مشكل الآثار","number":1457}]},{"num":5253,"demo":false,"sanad":"","matn":["عن ابن عباس: أنَّ رسولَ اللَّهِ ﷺ خطب الناس يوم النحر فقال: (( يا أيها الناس، أيُّ يومٍ هذا؟ )) قالوا: يومٌ حرام. قال: (( فأيُّ بلدٍ هذا؟ )) قالوا: بلدٌ حرام. قال: (( فأيُّ شهرٍ هذا؟ )) قالوا: شهرٌ حرام. قال: (( فإنَّ دماءكم، وأموالكم، وأعراضكم عليكم حرام، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا )). فأعادها مرارًا، ثم رفع رأسه فقال: (( اللهم هل بلَّغت؟ اللهم هل بلَّغت؟ اللهم هل بلَّغت؟ )). قال ابن عباس رضي الله عنهما: فوالذي نفسي بيده، إنها لوصيته إلى أمته: (( فليبلِّغ الشاهدُ الغائب، لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض ))."],"takhrij":"صحيح: رواه البخاريّ (١٧٣٩).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1739).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ addressed the people on the Day of Sacrifice and said: “O people, what day is this?” They said: A sacred day. He said: “What land is this?” They said: A sacred land. He said: “What month is this?” They said: A sacred month. He said: “Then indeed your blood, your wealth, and your honor are sacred to you, like the sacredness of this day of yours, in this land of yours, in this month of yours.” He repeated it several times, then raised his head and said: “O Allah, have I conveyed? O Allah, have I conveyed? O Allah, have I conveyed?” Ibn Abbas, may Allah be pleased with them both, said: By the One in whose hand is my soul, this was his instruction to his nation: “So let the one present convey to the one absent. Do not return after me as disbelievers, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1739}]},{"num":5254,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: خطب النبيُّ ﷺ في حجة الوداع فقال: (( إنَّ الزمان قد استدار كهيئته يوم خلق الله السماوات والأرض، وإنَّ السنة اثنا عشر شهرًا، منها أربعة حرم، ثلاثةٌ وَلاء: ذو القعدة، وذو الحجة، والمحرم، والآخر رجب بين جمادى وشعبان ))."],"takhrij":"حسن: رواه الطحاوي في شرح مشكل الآثار (١٤٥٤).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Sharh Mushkil al-Athar (1454).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Ibn Abbas said: The Prophet ﷺ delivered a sermon during the Farewell Pilgrimage and said: “Time has returned to its original order as it was on the day Allah created the heavens and the earth. The year is twelve months, of which four are sacred: three consecutive months — Dhu al-Qadah, Dhu al-Hijjah, and al-Muharram — and the fourth is Rajab, which comes between Jumada and Shaban.”"]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرح_مشکل_الاثار","label":"الطحاوي في شرح مشكل الآثار","number":1454}]},{"num":5255,"demo":false,"sanad":"","matn":["عن يحيى بن حصين، عن جدته أم الحصين، قال: سمعتها تقول: حججتُ مع رسول الله ﷺ حجة الوداع، فرأيته حين رمى جمرة العقبة وانصرف وهو على راحلته، ومعه بلال وأسامة، أحدهما يقود به راحلته، والآخر رافع ثوبه على رأس رسول الله ﷺ من الشمس. قالت: فقال رسول الله ﷺ قولًا كثيرًا، ثم سمعته يقول: (( إنْ أُمِّرَ عليكم عبدٌ مُجَدَّعٌ - حسبتها قالت: أسود - يقودكم بكتاب الله تعالى، فاسمعوا له وأطيعوا ))."],"takhrij":"صحيح: رواه مسلم (١٢٩٨) و(١٨٣٨).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1298, 1838).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Yahya ibn Husayn narrated from his grandmother Umm al-Husayn that she said: I performed Hajj with the Messenger of Allah ﷺ during the Farewell Pilgrimage. I saw him when he stoned Jamrat al-Aqabah and then departed while riding his mount, with Bilal and Usamah beside him. One of them was leading his mount, and the other was holding up a cloth above the head of the Messenger of Allah ﷺ to shield him from the sun. She said: The Messenger of Allah ﷺ said many things, then I heard him say: “If a mutilated servant — I think she said: a black servant — is placed in authority over you and leads you by the Book of Allah, then listen to him and obey.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1298},{"key":"و","label":"و","number":1838}]},{"num":5256,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: قال النبيُّ ﷺ بمنى: (( أتدرون أيَّ يومٍ هذا؟ )) قالوا: الله ورسوله أعلم. قال: (( فإنَّ هذا يومٌ حرام، أفتدرون أيُّ بلدٍ هذا؟ )) قالوا: الله ورسوله أعلم. قال: (( بلدٌ حرام، أفتدرون أيُّ شهرٍ هذا؟ )) قالوا: الله ورسوله أعلم. قال: (( شهرٌ حرام )). قال: (( فإنَّ الله حرَّم عليكم دماءكم وأموالكم وأعراضكم، كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٤٢) و(٦١٦٦)، ومسلم (٦٦).","grade":"متفق عليه","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1742, 6166) and Muslim (66).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Ibn Umar said: The Prophet ﷺ said at Mina: “Do you know what day this is?” They said: Allah and His Messenger know best. He said: “This is a sacred day. Do you know what land this is?” They said: Allah and His Messenger know best. He said: “A sacred land. Do you know what month this is?” They said: Allah and His Messenger know best. He said: “A sacred month.” Then he said: “Indeed Allah has made your blood, your wealth, and your honor sacred to you, like the sacredness of this day of yours, in this month of yours, in this land of yours.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1742},{"key":"و","label":"و","number":6166},{"key":"muslim","label":"مسلم","number":66}]},{"num":5257,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: كنا نتحدث بحجة الوداع، والنبيُّ ﷺ بين أظهرنا، ولا ندري ما حجة الوداع، فحمد الله وأثنى عليه، ثم ذكر المسيح الدجال، فأطنب في ذكره، وقال: (( ما بعث الله من نبيٍّ إلا أنذر أمته، أنذره نوح والنبيون من بعده، وإنه يخرج فيكم، فما خفي عليكم من شأنه فليس يخفى عليكم: أن ربكم ليس على ما يخفى عليكم - ثلاثًا - إن ربكم ليس بأعور، وإنه أعور عين اليمنى، كأن عينه عنبة طافية.","ألا إنَّ الله حرَّم عليكم دماءكم وأموالكم، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا، ألا هل بلغت؟ )). قالوا: نعم. قال: (( اللهم اشهد )) ثلاثًا. (( ويلكم - أو ويحكم - لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض ))."],"takhrij":"صحيح: رواه البخاريّ (٤٤٠٢-٤٤٠٣).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4402–4403).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Ibn Umar said: We used to speak about the Farewell Pilgrimage while the Prophet ﷺ was still among us, and we did not know what the Farewell Pilgrimage meant. He praised Allah and glorified Him, then mentioned the False Messiah and spoke at length about him. He said: “Allah has not sent any prophet except that he warned his nation about him. Noah warned against him, and the prophets after him also warned against him. He will emerge among you, and whatever may be hidden from you about him, this will not be hidden from you: your Lord is not one-eyed” — three times — “whereas he is one-eyed in the right eye, and his eye is like a floating grape.","Indeed Allah has made your blood and your wealth sacred to you, like the sacredness of this day of yours, in this land of yours, in this month of yours. Have I conveyed?” They said: Yes. He said: “O Allah, bear witness,” three times. “Woe to you — or alas for you — do not return after me as disbelievers, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4402}]},{"num":5258,"demo":false,"sanad":"","matn":["عن ابن عمر، أنَّ رسول الله ﷺ وقف يوم النحر بين الجمرات في الحجة التي حج فيها، فقال النبيُّ ﷺ: (( أيُّ يومٍ هذا؟ )) قالوا: يوم النحر. قال: (( فأيُّ بلدٍ هذا؟ )) قالوا: هذا بلد الله الحرام. قال: (( فأيُّ شهرٍ هذا؟ )) قالوا: شهر الله الحرام. قال: (( هذا يوم الحج الأكبر؛ دماؤكم وأموالكم وأعراضكم عليكم حرام كحرمة هذا البلد، في هذا الشهر، في هذا اليوم )). ثم قال: (( هل بلَّغت؟ )) قالوا: نعم. فطفق النبي ﷺ يقول: (( اللهم اشهد )). ثم ودَّع الناس، فقالوا: هذه حجة الوداع."],"takhrij":"صحيح: رواه ابن ماجه (٣٠٥٨)، والحاكم (٣٢٧٦)، والبيهقي (١٣٩/٥).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3058), al-Hakim (3276), and al-Bayhaqi (5/139).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ stood on the Day of Sacrifice between the pillars during the pilgrimage that he performed, and the Prophet ﷺ said: “What day is this?” They said: The Day of Sacrifice. He said: “What land is this?” They said: This is Allah’s sacred land. He said: “What month is this?” They said: Allah’s sacred month. He said: “This is the Day of the Greater Pilgrimage. Your blood, your wealth, and your honor are sacred to you like the sacredness of this land, in this month, on this day.” Then he said: “Have I conveyed?” They said: Yes. Then the Prophet ﷺ kept saying: “O Allah, bear witness.” Then he bade the people farewell, and they said: This is the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3058},{"key":"البیہقی","label":"البيهقي","number":139},{"key":"hakim","label":"المستدرك على الصحيحين","number":3276,"n":3263},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":9613,"n":9693}]},{"num":5259,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: كان رسولُ الله ﷺ إذا كان قبل يوم التروية بيوم خطب الناس، وأخبرهم بمناسكهم."],"takhrij":"حسن: رواه ابن خزيمة (٢٧٩٣)، والحاكم (٤٦١/١)، وعنه البيهقي (١١١/٥).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (2793), al-Hakim (1/461), and by al-Bayhaqi from him (5/111).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Ibn Umar said: When it was the day before the Day of Tarwiyah, the Messenger of Allah ﷺ would address the people and inform them of their rites."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2793},{"key":"hakim","label":"الحاكم","number":461},{"key":"عنہ_البیہقی","label":"عنه البيهقي","number":111}]},{"num":5260,"demo":false,"sanad":"","matn":["عن جرير البجلي، قال: قال لي النبيُّ ﷺ في حجة الوداع: (( استنصت الناس )) ثم قال: (( لا ترجعوا بعدي كفارًا يضرب بعضكم رقاب بعض ))."],"takhrij":"متفق عليه: رواه البخاريّ (٤٤٠٥)، ومسلم (٦٥). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4405) and Muslim (65). The wording is that of Muslim.","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Jarir al-Bajali said: The Prophet ﷺ said to me during the Farewell Pilgrimage: “Tell the people to be silent and listen.” Then he said: “Do not return after me as disbelievers, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4405},{"key":"muslim","label":"مسلم","number":65}]},{"num":5261,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: خطبنا رسولُ الله ﷺ فقال: (( أيها الناس، قد فرض الله عليكم الحج فحجوا )). فقال رجل: أكلَّ عام يا رسول الله؟ فسكت حتى قالها ثلاثًا، فقال رسول الله ﷺ: (( لو قلت نعم لوجبت، ولما استطعتم )). ثم قال: (( ذروني ما تركتكم، فإنما هلك من كان قبلكم بكثرة سؤالهم، واختلافهم على أنبيائهم، فإذا أمرتكم بشيء فأتوا منه ما استطعتم، وإذا نهيتكم عن شيء فدعوه ))."],"takhrij":"صحيح: رواه مسلم (١٣٣٧).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1337).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ addressed us and said: “O people, Allah has made Hajj obligatory upon you, so perform Hajj.” A man said: Every year, O Messenger of Allah ﷺ? He remained silent until the man repeated it three times. Then the Messenger of Allah ﷺ said: “Had I said yes, it would have become obligatory, and you would not have been able.” Then he said: “Leave me with what I have left you. Those before you were only destroyed because of their excessive questioning and their disagreement with their prophets. So when I command you to do something, do of it what you are able, and when I forbid you from something, then leave it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1337}]},{"num":5262,"demo":false,"sanad":"","matn":["عن رجلين من بني بكر، قالا: رأينا رسول الله ﷺ يخطب بين أوسط أيام التشريق، ونحن عند راحلته، وهي خطبة النبي ﷺ التي خطب بمنى."],"takhrij":"صحيح: رواه أبو داود (١٩٥٢).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1952).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Two men from Banu Bakr said: We saw the Messenger of Allah ﷺ delivering a sermon during the middle of the Days of Tashriq while we were near his mount, and it was the sermon that he delivered at Mina."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1952}]},{"num":5263,"demo":false,"sanad":"","matn":["عن الهرماس بن زياد الباهلي، قال: رأيتُ النبيَّ ﷺ يخطب الناس على ناقته العضباء يوم الأضحى بمنى."],"takhrij":"حسن: رواه أبو داود (١٩٥٤)، ورواه الإمام أحمد (١٥٩٦٨)، وصححه ابن خزيمة (٢٩٥٣)، وابن حبان (٣٨٧٥).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1954), Imam Ahmad (15968), and authenticated by Ibn Khuzaymah (2953) and Ibn Hibban (3875).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Al-Hirmas ibn Ziyad al-Bahili said: I saw the Prophet ﷺ addressing the people while upon his she-camel al-Adba on the Day of Sacrifice at Mina."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1954},{"key":"الامام_احمد","label":"الإمام أحمد","number":15968},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2953},{"key":"ibnhibban","label":"ابن حبان","number":3875},{"key":"ahmad","label":"مسند الإمام أحمد","number":15968,"n":15968}]},{"num":5264,"demo":false,"sanad":"","matn":["عن سلمة بن نبيط، عن أبيه - وكان قد حج مع النبي ﷺ - قال: رأيته يخطب يوم عرفة على بعيره."],"takhrij":"صحيح: رواه الإمام أحمد (١٨٧٢١).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (18721).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Salamah ibn Nubayt narrated from his father — who had performed Hajj with the Prophet ﷺ — that he said: I saw him delivering a sermon on the Day of Arafah while on his camel."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":18721},{"key":"ahmad","label":"مسند الإمام أحمد","number":18721,"n":18721}]},{"num":5265,"demo":false,"sanad":"","matn":["عن رجل من أصحاب النبي ﷺ قال: قام فينا رسول الله ﷺ على ناقة حمراء مخضرمة، فقال: (( أتدرون أيَّ يومكم هذا؟ )) قال: قلنا: يوم النحر. قال: (( صدقتم، يوم الحج الأكبر. أتدرون أيُّ شهرٍ شهركم هذا؟ )) قلنا: ذو الحجة. قال: (( صدقتم، شهر الله الأصم. أتدرون أيُّ بلدٍ بلدكم هذا؟ )) قال: قلنا: المشعر الحرام. قال: (( صدقتم )). قال: (( فإنَّ دماءكم وأموالكم عليكم حرام، كحرمة يومكم هذا في شهركم هذا في بلدكم هذا )) أو قال: (( كحرمة يومكم هذا، وشهركم هذا، وبلدكم هذا. ألا وإني فرطكم على الحوض، أنظركم، وإني مكاثر بكم الأمم، فلا تسوِّدوا وجهي. ألا وقد رأيتموني وسمعتم مني وستُسألون عني، فمن كذب عليَّ فليتبوأ مقعده من النار. ألا وإني مستنقذ رجالًا - أو ناسًا - ومستَنقَذٌ مني آخرون، فأقول: يا رب أصحابي. فيقال: إنك لا تدري ما أحدثوا بعدك ))."],"takhrij":"صحيح: رواه أحمد (٢٣٤٩٧) و(١٥٨٨٦).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23497, 15886).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: The Messenger of Allah ﷺ stood among us upon a reddish she-camel whose ear-tip had been cut and said: “Do you know what day this day of yours is?” We said: The Day of Sacrifice. He said: “You have spoken the truth. It is the Day of the Greater Pilgrimage. Do you know what month this month of yours is?” We said: Dhu al-Hijjah. He said: “You have spoken the truth. It is Allah’s sacred month. Do you know what land this land of yours is?” We said: The Sacred Precinct. He said: “You have spoken the truth.” Then he said: “Indeed your blood and your wealth are sacred to you, like the sacredness of this day of yours in this month of yours in this land of yours,” or he said, “like the sacredness of this day of yours, this month of yours, and this land of yours. Indeed I will precede you to the Pond and await you there. I will boast of your great number before the nations, so do not blacken my face. You have seen me and heard from me, and you will be asked about me; whoever lies about me, let him take his seat in the Fire. Indeed some men — or some people — will be rescued through me, while others will be taken away from me, and I will say: My Lord, my companions. It will be said: You do not know what they introduced after you.”"]}},"tuhfa":{},"refs":[{"key":"و","label":"و","number":15886},{"key":"ahmad","label":"مسند الإمام أحمد","number":23497,"n":23497}]},{"num":5266,"demo":false,"sanad":"","matn":["عن رافع بن عمرو المزني، قال: رأيتُ رسول الله ﷺ يخطب الناس بمنى حين ارتفع الضحى على بغلة شهباء، وعلي رضي الله عنه يعبِّر عنه، والناس بين قاعد وقائم."],"takhrij":"صحيح: رواه أبو داود (١٩٥٦)، والنسائي في الكبرى (٤٠٩٤).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1956) and al-Nasai in al-Kubra (4094).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Rafi ibn Amr al-Muzani said: I saw the Messenger of Allah ﷺ addressing the people at Mina when the morning had risen high, while on a gray mule, and Ali, may Allah be pleased with him, was conveying his words for him, while the people were both sitting and standing."]},"buhuth":{"ar":["قوله: (( وعلي يعبِّر عنه )) أي يُسمع الناس ما قد يخفى عليهم لبعدهم عن رسول الله ﷺ."],"en":["His statement, “And Ali was conveying for him,” means that he was making the Prophet ﷺ’s words heard to the people when some of them could not hear due to their distance from the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1956},{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":4094}]},{"num":5267,"demo":false,"sanad":"","matn":["عن أبي أمامة الباهلي، قال: سمعت رسول الله ﷺ في خطبته عام حجة الوداع يقول: (( إن الله قد أعطى كلَّ ذي حقٍّ حقَّه، فلا وصية لوارث، والولد للفراش، وللعاهر الحجر، وحسابهم على الله، ومن ادعى إلى غير أبيه أو انتمى إلى غير مواليه، فعليه لعنة الله التابعة إلى يوم القيامة، لا تُنفق المرأة شيئًا من بيتها إلا بإذن زوجها )). فقيل: يا رسول الله، ولا الطعام؟ قال: (( ذاك أفضل أموالنا )). قال: ثم قال رسول الله ﷺ: (( العارية مؤداة، والمنحة مردودة، والدين مقضي، والزعيم غارم ))."],"takhrij":"حسن: رواه أبو داود (٣٥٦٥)، والترمذي (٦٧٠) وحسّنه، وابن ماجه (٢٢٩٥)، وأحمد (٢٢٢٩٤)، واللفظ له.","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3565), al-Tirmidhi (670), who graded it Hasan, Ibn Majah (2295), and Ahmad (22294). The wording is that of Ahmad.","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu Umamah al-Bahili said: I heard the Messenger of Allah ﷺ say in his sermon during the Farewell Pilgrimage: “Allah has given every person with a right his due right, so there is no bequest for an heir. The child belongs to the lawful marriage bed, and the adulterer gets the stone. Their reckoning is with Allah. Whoever claims to belong to someone other than his father, or attributes himself to other than his patrons, upon him is the continuous curse of Allah until the Day of Resurrection. A woman must not spend anything from her household except with her husband’s permission.” It was said: O Messenger of Allah ﷺ, not even food? He said: “That is the best of our wealth.” Then the Messenger of Allah ﷺ said: “A borrowed item must be returned, a gift of use must be restored, a debt must be repaid, and the guarantor is liable.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3565},{"key":"tirmidhi","label":"الترمذي","number":670},{"key":"ibnmajah","label":"ابن ماجه","number":2295},{"key":"ahmad","label":"مسند الإمام أحمد","number":22294,"n":22294}]},{"num":5268,"demo":false,"sanad":"","matn":["عن أبي أمامة، قال: سمعت رسول الله ﷺ يخطب في حجة الوداع فقال: (( اتقوا الله ربكم، وصلُّوا خمسكم، وصوموا شهركم، وأدُّوا زكاة أموالكم، وأطيعوا ذا أمركم، تدخلوا جنة ربكم ))."],"takhrij":"صحيح: رواه الترمذي (٦١٦)، وأحمد (٢٢١٦١)، وصححه ابن حبان (٤٥٦٣).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (616), Ahmad (22161), and authenticated by Ibn Hibban (4563).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu Umamah said: I heard the Messenger of Allah ﷺ delivering a sermon during the Farewell Pilgrimage and saying: “Fear Allah your Lord, pray your five prayers, fast your month, give the zakah of your wealth, and obey those placed in authority over you; you will enter the Paradise of your Lord.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":616},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4563},{"key":"ahmad","label":"مسند الإمام أحمد","number":22161,"n":22161}]},{"num":5269,"demo":false,"sanad":"","matn":["عن أبي قتيلة، أن رسول الله ﷺ قام في الناس في حجة الوداع، فقال: (( لا نبيَّ بعدي، ولا أمة بعدكم، فاعبدوا ربكم، وأقيموا خمسكم، وصوموا شهركم، وأطيعوا ولاة أمركم، تدخلوا جنة ربكم ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٢٢/٣١٦)، وأبو نعيم في معرفة الصحابة (٦/٢٩٩٤).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (22/316) and Abu Nuaym in Marifat al-Sahabah (6/2994).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu Qatilah narrated that the Messenger of Allah ﷺ stood among the people during the Farewell Pilgrimage and said: “There is no prophet after me, and there is no nation after you. So worship your Lord, establish your five prayers, fast your month, and obey your rulers; you will enter the Paradise of your Lord.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":22},{"key":"ابو_نعیم/معرفہ_الصحابہ","label":"أبو نعيم في معرفة الصحابة","number":6},{"key":"sh10490","label":"معرفة الصحابة لأبي نعيم","number":6962,"n":7095}]},{"num":5270,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن معاذ التيمي، قال: خطبنا رسول الله ﷺ ونحن بمنى، ففُتحت أسماعنا حتى كنا نسمع ما يقول ونحن في منازلنا، فطفق يعلمهم مناسكهم حتى بلغ الجمار، فوضع إصبعيه السبابتين ثم قال: (( بحصى الخذف )). ثم أمر المهاجرين فنزلوا في مقدم المسجد، وأمر الأنصار فنزلوا من وراء المسجد، ثم نزل الناس بعد ذلك."],"takhrij":"صحيح: رواه أبو داود (١٩٥٧)، وأحمد (١٦٥٨٩).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1957) and Ahmad (16589).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abd al-Rahman ibn Muadh al-Taymi said: The Messenger of Allah ﷺ addressed us while we were at Mina, and our hearing became so open that we could hear what he was saying while we were in our camps. He began teaching them their rites until he reached the matter of the pebbles, then he held up his two forefingers and said: “Like the pebbles used for flicking.” Then he ordered the Emigrants to settle in front of the mosque, and ordered the Helpers to settle behind the mosque, and then the people settled after that."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1957},{"key":"ahmad","label":"مسند الإمام أحمد","number":16589,"n":16589}]},{"num":5271,"demo":false,"sanad":"","matn":["عن أبي نضرة، حدثني من سمع خطبة رسول الله ﷺ في وسط أيام التشريق، فقال: (( يا أيها الناس، ألا إنَّ ربكم واحد، وإنَّ أباكم واحد، ألا لا فضل لعربي على أعجمي، ولا لعجمي على عربي، ولا لأحمر على أسود، ولا أسود على أحمر إلا بالتقوى، أبلَّغت؟ )). قالوا: بلَّغ رسول الله ﷺ. ثم قال: (( أيُّ يومٍ هذا؟ )) قالوا: يوم حرام. ثم قال: (( أيُّ شهرٍ هذا؟ )) قالوا: شهر حرام. ثم قال: (( أيُّ بلدٍ هذا؟ )) قالوا: بلد حرام. قال: (( فإنَّ الله قد حرَّم بينكم دماءكم وأموالكم )) قال: ولا أدري قال: (( أو أعراضكم )) أم لا؟ (( كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا. أبلَّغت؟ )) قالوا: بلَّغ رسول الله ﷺ. قال: (( ليبلِّغ الشاهد الغائب ))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٣٤٨٩).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (23489).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu Nadrah said: Someone who heard the sermon of the Messenger of Allah ﷺ during the middle of the Days of Tashriq told me that he said: “O people, indeed your Lord is One, and your father is one. There is no superiority of an Arab over a non-Arab, nor of a non-Arab over an Arab, nor of a red person over a black person, nor of a black person over a red person, except through piety. Have I conveyed?” They said: The Messenger of Allah ﷺ has conveyed. Then he said: “What day is this?” They said: A sacred day. Then he said: “What month is this?” They said: A sacred month. Then he said: “What land is this?” They said: A sacred land. He said: “Then indeed Allah has made your blood and your wealth” — he said: and I do not know whether he also said, “and your honor” or not — “sacred among you, like the sacredness of this day of yours, in this month of yours, in this land of yours. Have I conveyed?” They said: The Messenger of Allah ﷺ has conveyed. He said: “Let the one present convey to the one absent.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":23489},{"key":"ahmad","label":"مسند الإمام أحمد","number":23489,"n":23489}]},{"num":5272,"demo":false,"sanad":"","matn":["عن أبي سعيد، قال: قال رسول الله ﷺ في حجة الوداع: (( ألا إنَّ أحرم الأيام يومكم هذا، ألا وإنَّ دماءكم وأموالكم عليكم حرام كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا، ألا هل بلَّغت؟ )). قالوا: نعم. قال: (( اللهم اشهد ))."],"takhrij":"صحيح: رواه ابن ماجه (٣٩٣١)، وأحمد (١١٧٦٢).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3931) and Ahmad (11762).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu Said said: The Messenger of Allah ﷺ said during the Farewell Pilgrimage: “Indeed, the most sacred of days is this day of yours. Indeed, your blood and your wealth are sacred to you like the sacredness of this day of yours, in this month of yours, in this land of yours. Have I conveyed?” They said: Yes. He said: “O Allah, bear witness.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3931},{"key":"ahmad","label":"مسند الإمام أحمد","number":11762,"n":11762}]},{"num":5273,"demo":false,"sanad":"","matn":["عن فضالة بن عبيد الأنصاري، عن رسول الله ﷺ أنه قال في حجة الوداع: (( هذا يومٌ حرام، وبلدٌ حرام، فدماؤكم وأموالكم وأعراضكم عليكم حرام، مثل هذا اليوم، وهذه البلدة، إلى يوم تلقونه. وحتى دفعةٌ دفعها مسلمٌ مسلمًا يريد بها سوءًا حرامًا. وسأخبركم من المسلم: من سلم المسلمون من لسانه ويده، والمؤمن من أمِنه الناس على أموالهم وأنفسهم، والمهاجر من هجر الخطايا والذنوب، والمجاهد من جاهد نفسه في طاعة الله ))."],"takhrij":"صحيح: رواه البزار في مسنده (٣٧٥٢)، وأحمد (٢٣٩٥٨)، والطبراني (١٢/٣٠٩). واللفظ للبزار.","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar in his Musnad (3752), Ahmad (23958), and al-Tabarani (12/309). The wording is that of al-Bazzar.","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Fadalah ibn Ubayd al-Ansari narrated from the Messenger of Allah ﷺ that he said during the Farewell Pilgrimage: “This is a sacred day and a sacred land, so your blood, your wealth, and your honor are sacred to you, like this day and this town, until the day you meet Him. Even a single push by which a Muslim intends evil toward another Muslim is forbidden. And I will tell you who the Muslim is: the one from whose tongue and hand the Muslims are safe. The believer is the one whom people trust regarding their wealth and their lives. The emigrant is the one who abandons sins and wrongdoings. And the fighter in Allah’s cause is the one who strives against his own soul in obedience to Allah.”"]}},"tuhfa":{},"refs":[{"key":"البزار/مسندہ","label":"البزار في مسنده","number":3752},{"key":"الطبرانی","label":"الطبراني","number":12},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1143,"n":1143},{"key":"ahmad","label":"مسند الإمام أحمد","number":23958,"n":23958}]},{"num":5274,"demo":false,"sanad":"","matn":["عن أبي الغادية الجهنيّ، قال: خطبنا رسولُ الله ﷺ يوم العقبة، فقال: (( يا أيُّها الناس، إنَّ دماءكم وأموالكم عليكم حرام إلى أن تلقوا ربَّكم، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا، ألا هل بلَّغت؟ )). قالوا: نعم. قال: (( اللهم هل بلَّغت؟ ))."],"takhrij":"حسن: رواه الإمام أحمد (١٦٦٩٩).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (16699).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Abu al-Ghadiyah al-Juhani said: The Messenger of Allah ﷺ delivered a sermon to us on the Day of al-Aqabah and said: “O people, your blood and your wealth are sacred to you until you meet your Lord, like the sanctity of this day of yours, in this land of yours, in this month of yours. Have I conveyed?” They said: Yes. He said: “O Allah, have I conveyed?”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":16699},{"key":"ahmad","label":"مسند الإمام أحمد","number":16699,"n":16699}]},{"num":5275,"demo":false,"sanad":"","matn":["عن وَابِصَةَ بنِ مَعْبَدٍ الجهنيّ، أنه كان يقوم في الناس يوم الأضحى، أو يوم الفطر، فيقول: إني شهدتُ رسولَ الله ﷺ في حجة الوداع، وهو يقول: (( أيُّ يومٍ هذا؟ )). قال الناس: يوم النحر. قال: (( فأيُّ شهرٍ هذا؟ )) ثم قال: (( أيُّ بلدٍ هذا؟ )). قالوا: هذه البلدة. قال: (( فإنَّ دماءكم وأموالكم وأعراضكم حرام عليكم كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا إلى يوم تلقونه )). ثم قال: (( اللهم هل بلغت؟ يبلِّغ الشاهدُ الغائب )). قال وابصة: نُشهد عليكم كما أَشهد علينا."],"takhrij":"حسن: رواه أبو يعلى (١٥٩٠، ١٥٨٩)، والطبراني في الأوسط (مجمع البحرين) (١٧٨٣).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yala (1590, 1589) and al-Tabarani in al-Awsat (Majma al-Bahrayn, 1783).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Wabisah ibn Mabad al-Juhani used to stand before the people on the Day of Sacrifice, or on the Day of Breaking the Fast, and say: I witnessed the Messenger of Allah ﷺ during the Farewell Pilgrimage saying: “What day is this?” The people said: The Day of Sacrifice. He said: “What month is this?” Then he said: “What land is this?” They said: This land. He said: “Indeed your blood, your wealth, and your honor are sacred to you like the sanctity of this day of yours, in this month of yours, in this land of yours, until the day you meet Him.” Then he said: “O Allah, have I conveyed? Let the one present convey to the one absent.” Wabisah said: We make you witnesses, just as he made us witnesses."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":1590},{"key":"sh12520","label":"مسند أبي يعلى","number":1589,"n":1588}]},{"num":5276,"demo":false,"sanad":"","matn":["عن الحارث بن عمرو، أنه لقي رسولَ الله ﷺ في حجة الوداع، فقلت: بأبي أنت يا رسول الله، استغفر لي. قال: (( غفر الله لكم )). قال: وهو على ناقته العضباء. قال: فاشتددتُ له من الشق الآخر أرجو أن يخصّني دون القوم، فقلت: استغفر لي. قال: (( غفر الله لكم )). قال رجل: يا رسول الله، الفرائع والعتائر؟ قال: (( من شاء فرَّع، ومن شاء لم يفرِّع، ومن شاء عتَر، ومن شاء لم يعتِر، في الغنم أضحية )). ثم قال: (( ألا إنَّ دماءكم وأموالكم عليكم حرام كحرمة يومكم هذا، في بلدكم هذا ))."],"takhrij":"حسن: رواه الإمام أحمد (١٥٩٧٢) واللفظ له، والنسائي (٤٢٢٧، ٤٢٢٦)، والطبراني في الكبير (٣٣٥١).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (15972), and this is his wording, al-Nasai (4227, 4226), and al-Tabarani in al-Kabir (3351).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Al-Harith ibn Amr said: I met the Messenger of Allah ﷺ during the Farewell Pilgrimage and said: May my father be sacrificed for you, O Messenger of Allah ﷺ, ask forgiveness for me. He said: “May Allah forgive you all.” He was upon his she-camel al-Adba. I hurried around to his other side hoping that he would single me out apart from the people, and I said: Ask forgiveness for me. He said: “May Allah forgive you all.” A man said: O Messenger of Allah ﷺ, what about the first-born offering and the sacrificial offering of Rajab? He said: “Whoever wishes may offer the first-born animal, and whoever wishes may leave it. Whoever wishes may offer the Rajab sacrifice, and whoever wishes may leave it. And for sheep there is the sacrificial offering.” Then he said: “Indeed your blood and your wealth are sacred to you like the sanctity of this day of yours, in this land of yours.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":15972},{"key":"nasai","label":"النسائي","number":4227},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":3351},{"key":"ahmad","label":"مسند الإمام أحمد","number":15972,"n":15972}]},{"num":5277,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: إني لتحت ناقة رسول الله ﷺ يسيل عليَّ لُعابُها، فسمعته يقول: (( إنَّ الله جعل لكلِّ ذي حقٍّ حقَّه، ألا لا وصية لوارث، الولد للفراش، وللعاهر الحجر، ألا لا يتولَّى رجلٌ غير مواليه، ولا يدَّعي إلى غير أبيه، فمن فعل ذلك فعليه لعنة الله متتابعة إلى يوم القيامة، ألا لا تُنفقنَّ امرأة من بيتها إلا بإذن زوجها )). فقال رجل: إلا الطعام يا رسول الله؟ فقال: (( وهل أفضلُ أموالنا إلا الطعام؟! ألا إنَّ العارية مؤدَّاة، والمنِيحة مردودة، والدَّين مقضيّ، والزعيم غارم ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٧١٤)، وأبو عمرو المديني في حجة الوداع (٣٩)، والطبراني في مسند الشاميين (٦٢١) واللفظ له، وأبو داود (٥١١٥).","grade":"صحيح","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2714), Abu Amr al-Madini in Hajjat al-Wada (39), al-Tabarani in Musnad al-Shamiyyin (621), and this is his wording, and Abu Dawud (5115).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Anas ibn Malik said: I was beneath the she-camel of the Messenger of Allah ﷺ and its saliva was dripping upon me, and I heard him say: “Indeed Allah has given every person with a right his due. There is no bequest for an heir. The child belongs to the marriage bed, and the adulterer gets the stone. No man is to ally himself with other than his own patrons, and no one is to claim descent from other than his father. Whoever does that, upon him is the continuous curse of Allah until the Day of Resurrection. A woman must not spend anything from her house except with her husband’s permission.” A man said: Not even food, O Messenger of Allah ﷺ? He said: “And what wealth of ours is better than food? Indeed, a borrowed item must be returned, a loaned animal or thing of benefit must be restored, a debt must be paid, and the guarantor is liable.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2714},{"key":"ابو_عمرو_المدینی/حجہ_الوداع","label":"أبو عمرو المديني في حجة الوداع","number":39},{"key":"الطبرانی/مسند_الشامیین","label":"الطبراني في مسند الشاميين","number":621},{"key":"abudawud","label":"أبو داود","number":5115},{"key":"sh13162","label":"مسند الشاميين للطبراني","number":621,"n":621}]},{"num":5278,"demo":false,"sanad":"","matn":["عن العدّاء بن خالد الكلابي قال: رأيتُ رسولَ الله ﷺ يوم عرفة وهو قائم على الركابين ينادي بأعلى صوته: (( يا أيها الناس، أيُّ يومٍ يومكم هذا؟ )). قالوا: الله ورسوله أعلم. قال: (( فأيُّ شهرٍ شهركم هذا؟ )). قالوا: الله ورسوله أعلم. قال: (( فأيُّ بلدٍ بلدكم هذا؟ )). قالوا: الله ورسوله أعلم. قال: (( يومكم يومٌ حرام، وشهركم شهرٌ حرام، وبلدكم بلدٌ حرام )). قال: ثم قال: (( ألا إنَّ دماءكم وأموالكم عليكم حرام، كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا، إلى يوم تلقون ربكم فيسألكم عن أعمالكم )). قال: ثم رفع يديه إلى السماء فقال: (( اللهم اشهد عليهم، اللهم اشهد عليهم )) ذكرها مرارًا، فلا أدري كم ذكر."],"takhrij":"حسن: رواه الإمام أحمد (٢٠٣٣٦).","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (20336).","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Al-Adda ibn Khalid al-Kilabi said: I saw the Messenger of Allah ﷺ on the Day of Arafah while standing in the stirrups and calling out in his loudest voice: “O people, what day is your day today?” They said: Allah and His Messenger know best. He said: “What month is your month now?” They said: Allah and His Messenger know best. He said: “What land is your land now?” They said: Allah and His Messenger know best. He said: “Your day is a sacred day, your month is a sacred month, and your land is a sacred land.” Then he said: “Indeed your blood and your wealth are sacred to you like the sanctity of this day of yours, in this month of yours, in this land of yours, until the day you meet your Lord and He asks you about your deeds.” Then he raised his hands to the sky and said: “O Allah, bear witness over them, O Allah, bear witness over them,” repeating it many times, and I do not know how many times he repeated it."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":20336},{"key":"ahmad","label":"مسند الإمام أحمد","number":20336,"n":20336}]},{"num":5279,"demo":false,"sanad":"","matn":["عن جبير بن مطعم، قال: سمعتُ رسولَ الله ﷺ وهو يخطب الناس بالخيف: (( نضَّر الله عبدًا سمع مقالتي فوعاها، ثم أدّاها إلى من لم يسمعها، فربَّ حامل فقهٍ لا فقه له، وربَّ حامل فقهٍ إلى من هو أفقه منه. ثلاثٌ لا يُغَلُّ عليهن قلبُ مؤمن: إخلاص العمل، وطاعة ذوي الأمر، ولزوم الجماعة، فإنَّ دعوتهم تكون من ورائه ))."],"takhrij":"حسن: رواه الإمام أحمد (١٦٧٥٤)، والبزار في مسنده (٣٤١٦)، واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب خطب النبي ﷺ في حجة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (16754) and al-Bazzar in his Musnad (3416), and the wording is that of Ahmad.","chapter_en":"The sermons of the Prophet ﷺ during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":133,"content":{"translation":{"en":["Jubayr ibn Mutim said: I heard the Messenger of Allah ﷺ while he was addressing the people at al-Khayf saying: “May Allah brighten the face of a servant who hears my statement, understands it well, and then conveys it to one who did not hear it. Perhaps a bearer of knowledge does not fully understand it himself, and perhaps a bearer of knowledge conveys it to one more understanding than himself. Three things do not allow the heart of a believer to harbor betrayal: sincerity in deeds, obedience to those in authority, and clinging to the community, for their supplication surrounds those behind them.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":16754},{"key":"البزار/مسندہ","label":"البزار في مسنده","number":3416},{"key":"ahmad","label":"مسند الإمام أحمد","number":16754,"n":16754}]},{"num":5280,"demo":false,"sanad":"","matn":["عن زيد بن أرقم: أنَّ النبيَّ ﷺ غزا تسع عشرة غزوة، وأنه حجَّ بعد ما هاجر حجةً واحدة لم يحجَّ بعدها، حجة الوداع."],"takhrij":"متفق عليه: رواه البخاري (٤٤٠٤)، ومسلم (١٢٥٤)، واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في عدد حجّات النبي ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4404) and Muslim (1254), and the wording is that of al-Bukhari.","chapter_en":"What has been narrated regarding the number of times the Prophet ﷺ performed Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":134,"content":{"translation":{"en":["Zayd ibn Arqam narrated that the Prophet ﷺ took part in nineteen military expeditions, and that after migrating he performed one Hajj only, after which he did not perform another: the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4404},{"key":"muslim","label":"مسلم","number":1254}]},{"num":5281,"demo":false,"sanad":"","matn":["عن قتادة، قال: سألتُ أنسًا: كم حجَّ رسولُ الله ﷺ؟ قال: حجةً واحدة، واعتمر أربع عُمَر."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٧٨)، ومسلم (١٢٥٣)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في عدد حجّات النبي ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1778) and Muslim (1253), and the wording is that of Muslim.","chapter_en":"What has been narrated regarding the number of times the Prophet ﷺ performed Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":134,"content":{"translation":{"en":["Qatadah said: I asked Anas: How many times did the Messenger of Allah ﷺ perform Hajj? He said: One Hajj, and he performed four Umrahs."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1778},{"key":"muslim","label":"مسلم","number":1253}]},{"num":5282,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله، أنَّ النبيَّ ﷺ حجَّ ثلاث حجج: حجتين قبل أن يهاجر، وحجةً بعدما هاجر، ومعها عمرة. فساق ثلاثًا وستين بدنة، وجاء عليٌّ من اليمن ببقيتها، فيها جملٌ لأبي جهل في أنفه بُرَةٌ من فضة، فنحرها رسول الله ﷺ، وأمر رسول الله ﷺ من كل بدنة ببضعة، فطُبخت، وشرب من مرقها."],"takhrij":"صحيح: رواه الترمذي (٨١٥)، وابن ماجه (٣٠٧٦)، وصححه ابن خزيمة (٣٠٥٦).","grade":"صحيح","chapter_ar":"باب ما جاء في عدد حجّات النبي ﷺ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (815), Ibn Majah (3076), and authenticated by Ibn Khuzaymah (3056).","chapter_en":"What has been narrated regarding the number of times the Prophet ﷺ performed Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":134,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Prophet ﷺ performed Hajj three times: two pilgrimages before he migrated, and one pilgrimage after he migrated, and with it an Umrah. He drove sixty-three sacrificial camels, and Ali came from Yemen with the rest. Among them was a camel belonging to Abu Jahl with a silver nose-ring. The Messenger of Allah ﷺ slaughtered them, and he ordered that a piece from each camel be taken, then they were cooked, and he drank from their broth."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":815},{"key":"ibnmajah","label":"ابن ماجه","number":3076},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":3056}]},{"num":5283,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول الله ﷺ أنه قال: (( ننزل غدًا إن شاء الله بخيف بني كنانة، حيث تقاسموا على الكفر ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٨٩)، ومسلم (١٣١٤)، واللفظ لمسلم. وزاد البخاري في أول الحديث: (( حين أراد قدوم مكة )) أي حين رجوعه من منى.","grade":"متفق عليه","chapter_ar":"باب مكان نزول النبي ﷺ مكة بعد رجوعه من منى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1589) and Muslim (1314), and the wording is that of Muslim. Al-Bukhari added at the beginning of the narration: “when he intended to come to Makkah,” meaning when he was returning from Mina.","chapter_en":"The place where the Prophet ﷺ stayed in Makkah after returning from Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":135,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Tomorrow, if Allah wills, we will stay at the valley of Banu Kinanah, where they swore together upon disbelief.”"]},"buhuth":{"ar":["الخيف: هو ما ارتفع عن مجرى السيل، وانحدر عن غلظ الجبل، ومسجد منى يسمى مسجد الخيف، لأنه في سفح جبلها."],"en":["Al-Khayf is the area that rises above the course of floodwater and slopes down from the side of a mountain. The mosque of Mina is called Masjid al-Khayf because it lies at the foot of its mountain."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1589},{"key":"muslim","label":"مسلم","number":1314}]},{"num":5284,"demo":false,"sanad":"","matn":["عن أسامة بن زيد، قال: قلت: يا رسول الله، أين ننزل غدًا في حجته؟ فقال: (( وهل ترك لنا عقيل منزلًا؟ )). ثم قال: (( نحن نازلون غدًا بخيف بني كنانة، المحصَّب، حيث قاسمت قريشٌ على الكفر )). وذلك أن بني كنانة حالفت قريشًا على بني هاشم: ألا يناكحوهم ولا يبايعوهم ولا يؤووهم. قال الزهري: والخيف: الوادي."],"takhrij":"متفق عليه: رواه البخاريّ (٣٠٥٨)، ومسلم (٤٤٠ : ١٣٥١).","grade":"متفق عليه","chapter_ar":"باب مكان نزول النبي ﷺ مكة بعد رجوعه من منى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3058) and Muslim (1351/440).","chapter_en":"The place where the Prophet ﷺ stayed in Makkah after returning from Mina","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":135,"content":{"translation":{"en":["Usamah ibn Zayd said: I said: O Messenger of Allah ﷺ, where will we stay tomorrow during his pilgrimage? He said: “Has Aqil left us any house to stay in?” Then he said: “Tomorrow we will stay at the valley of Banu Kinanah, al-Muhassab, where Quraysh swore together upon disbelief.” That was because Banu Kinanah formed an alliance with Quraysh against Banu Hashim: that they would not intermarry with them, trade with them, or shelter them. Al-Zuhri said: al-Khayf means the valley."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":3058},{"key":"muslim","label":"مسلم","number":440}]},{"num":5285,"demo":false,"sanad":"","matn":["عن عبد العزيز بن رفيع، قال: سألتُ أنس بن مالك: أخبرني بشيء عقلته عن النبي ﷺ: أين صلَّى الظهر يوم التروية؟ قال: بمنى. قلت: فأين صلَّى العصر يوم النفر؟ قال: بالأبطح، ثم قال: افعل كما يفعل أمراؤك."],"takhrij":"متفق عليه: رواه البخاري (١٧٦٣)، ومسلم (١٣٠٩).","grade":"متفق عليه","chapter_ar":"باب أداء النبي ﷺ الصلوات في مكان نزوله بالمحصَّب يوم النَّفر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1763) and Muslim (1309).","chapter_en":"The Prophet’s performance of the prayers at the place where he stayed in al-Muhassab on the Day of Departure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":136,"content":{"translation":{"en":["Abd al-Aziz ibn Rafi said: I asked Anas ibn Malik: Tell me something you understood and retained from the Prophet ﷺ. Where did he pray the noon prayer on the Day of Tarwiyah? He said: At Mina. I said: Then where did he pray the afternoon prayer on the Day of Departure? He said: At al-Abtah. Then he said: Do as your leaders do."]},"buhuth":{"ar":["والأبطح يقال له أيضًا: المحصَّب، وهو موضع بين مكة ومنى، وهو إلى منى أقرب. وكان رسول الله ﷺ نزل به لأنه أسمح لخروجه كما قالت عائشة، ومنه ذهب إلى البيت لطواف الوداع، ثم خرج إلى المدينة.","قال الشافعي: (( نزول النبي ﷺ بالأبطح ليس من النسك في شيء، إنما هو منزل نزله النبي ﷺ ))."],"en":["Al-Abtah is also called al-Muhassab. It is a place between Makkah and Mina, and it is closer to Mina. The Messenger of Allah ﷺ stayed there because it was easier for his departure, as Aishah said, and from there he went to the House for the Farewell Tawaf, then departed to Madinah.","Al-Shafii said: “The Prophet ﷺ’s staying at al-Abtah is not one of the rites at all; it was simply a place where the Prophet ﷺ stayed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1763},{"key":"muslim","label":"مسلم","number":1309}]},{"num":5286,"demo":false,"sanad":"","matn":["عن أنس: أنَّ النبيَّ ﷺ صلَّى الظهر والعصر والمغرب والعشاء، ثم رقد رقدةً بالمحصَّب، ثم ركب إلى البيت فطاف به."],"takhrij":"صحيح: رواه البخاريّ (١٧٥٦).","grade":"صحيح","chapter_ar":"باب أداء النبي ﷺ الصلوات في مكان نزوله بالمحصَّب يوم النَّفر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1756).","chapter_en":"The Prophet’s performance of the prayers at the place where he stayed in al-Muhassab on the Day of Departure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":136,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ prayed the noon, afternoon, sunset, and night prayers, then rested for a while at al-Muhassab, then rode to the House and performed tawaf around it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1756}]},{"num":5287,"demo":false,"sanad":"","matn":["عن نافع، أنَّ ابن عمر كان يرى التحصيب سنة، وكان يصلِّي الظهر يوم النفر بالحصبة. قال نافع: قد حصَّب رسول الله ﷺ والخلفاء بعده."],"takhrij":"صحيح: رواه مسلم (٣٣٨ :١٣١٠)، والبخاري (١٧٦٨).","grade":"صحيح","chapter_ar":"باب أداء النبي ﷺ الصلوات في مكان نزوله بالمحصَّب يوم النَّفر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1310/338) and al-Bukhari (1768).","chapter_en":"The Prophet’s performance of the prayers at the place where he stayed in al-Muhassab on the Day of Departure","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":136,"content":{"translation":{"en":["Nafi narrated that Ibn Umar considered staying at al-Muhassab to be a Sunnah, and he used to pray the noon prayer on the Day of Departure at al-Hasbah. Nafi said: The Messenger of Allah ﷺ stayed at al-Muhassab, and the caliphs after him did so as well."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":338},{"key":"bukhari","label":"البخاري","number":1768}]},{"num":5288,"demo":false,"sanad":"","matn":["عن عائشة، قالت: نزول الأبطح ليس بسنة، إنما نزله رسولُ الله ﷺ لأنه كان أسمح لخروجه إذا خرج."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٦٥)، ومسلم (١٣١١)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب نزول النبي ﷺ بالمحصَّب ليس من السنة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1765) and Muslim (1311), and the wording is that of Muslim.","chapter_en":"The Prophet’s stay at al-Muhassab is not from the Sunnah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":137,"content":{"translation":{"en":["Aishah said: Staying at al-Abtah is not a Sunnah. The Messenger of Allah ﷺ only stayed there because it was easier for his departure when he left."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1765},{"key":"muslim","label":"مسلم","number":1311}]},{"num":5289,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: ليس التحصيب بشيء، إنما هو منزل نزله رسول الله ﷺ."],"takhrij":"متفق عليه: رواه البخاريّ في الحج (١٧٦٦)، ومسلم في الحج (١٣١٢).","grade":"متفق عليه","chapter_ar":"باب نزول النبي ﷺ بالمحصَّب ليس من السنة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in the Book of Hajj (1766) and Muslim in the Book of Hajj (1312).","chapter_en":"The Prophet’s stay at al-Muhassab is not from the Sunnah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":137,"content":{"translation":{"en":["Ibn Abbas said: Staying at al-Muhassab is not anything binding; it was only a place where the Messenger of Allah ﷺ stayed."]},"buhuth":{"ar":["والتحصيب: نزول الأبطح، كما قال الترمذي."],"en":["Al-Tahsib means staying at al-Abtah, as al-Tirmidhi said."]}},"tuhfa":{},"refs":[{"key":"bukhari/الحج","label":"البخاريّ في الحج","number":1766},{"key":"muslim/الحج","label":"مسلم في الحج","number":1312}]},{"num":5290,"demo":false,"sanad":"","matn":["عن أبي رافع، قال: لم يأمرني رسولُ الله ﷺ أن أنزل الأبطح حين خرج من منى، ولكن جئتُ فضربتُ فيه قبته، فجاء فنزل."],"takhrij":"صحيح: رواه مسلم (١٣١٣).","grade":"صحيح","chapter_ar":"باب نزول النبي ﷺ بالمحصَّب ليس من السنة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1313).","chapter_en":"The Prophet’s stay at al-Muhassab is not from the Sunnah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":137,"content":{"translation":{"en":["Abu Rafi said: The Messenger of Allah ﷺ did not command me to stay at al-Abtah when he left Mina, but I went there and pitched his tent there, then he came and stayed."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1313}]},{"num":5291,"demo":false,"sanad":"","matn":["عن نافع، أنَّ ابن عمر كان يرى التحصيب سنة، وكان يصلِّي الظهر يوم النفر بالحصبة. قال نافع: قد حصَّب رسول الله ﷺ والخلفاء بعده."],"takhrij":"صحيح: رواه مسلم (٣٣٨/١٣١٠).","grade":"صحيح","chapter_ar":"باب من قال: إن النزول بالمحصَّب من السنة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1310/338).","chapter_en":"Those who said that staying at al-Muhassab is from the Sunnah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":138,"content":{"translation":{"en":["Nafi narrated that Ibn Umar considered staying at al-Muhassab to be a Sunnah, and he used to pray the noon prayer on the Day of Departure at al-Hasbah. Nafi said: The Messenger of Allah ﷺ stayed at al-Muhassab, and the caliphs after him did so as well."]},"buhuth":{"ar":["ورواه أيضًا من وجه آخر: أن النبي ﷺ وأبا بكر وعمر كانوا ينزلون الأبطح."],"en":["It was also narrated through another route that the Prophet ﷺ, Abu Bakr, and Umar used to stay at al-Abtah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":338}]},{"num":5292,"demo":false,"sanad":"","matn":["عن عمر، قال: من السنة النزول بالأبطح عشية النفر."],"takhrij":"حسن: رواه الطبراني في الأوسط (٣٥٠٧).","grade":"حسن","chapter_ar":"باب من قال: إن النزول بالمحصَّب من السنة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (3507).","chapter_en":"Those who said that staying at al-Muhassab is from the Sunnah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":138,"content":{"translation":{"en":["Umar said: It is from the Sunnah to stay at al-Abtah on the evening of departure."]},"buhuth":{"ar":["والمراد بالسنة هنا مطلق التأسي بفعل النبي ﷺ، لا أنه من مستحبات الحج، ونزول الخلفاء بعد النبي ﷺ في هذا المكان هو للسبب نفسه الذي ذكرته عائشة رضي الله عنها."],"en":["What is meant by Sunnah here is general imitation of the Prophet ﷺ’s action, not that it is one of the recommended rites of Hajj. The caliphs staying there after the Prophet ﷺ was for the same reason mentioned by Aishah, may Allah be pleased with her."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":3507},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":3483,"n":3469}]},{"num":5293,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ قالت: أدلج رسولُ الله ﷺ ليلة النفر من البطحاء إدلاجًا."],"takhrij":"صحيح: رواه ابن ماجه (٣٠٦٨)، والإمام أحمد (٢٤٤٩٣)، واللفظ لابن ماجه. وصححه ابن خزيمة (٢٩٩٧).","grade":"صحيح","chapter_ar":"باب الإدلاج من المحصَّب","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (3068) and Imam Ahmad (24493), and the wording is that of Ibn Majah. It was authenticated by Ibn Khuzaymah (2997).","chapter_en":"Setting out at night from al-Muhassab","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":139,"content":{"translation":{"en":["Aishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ set out by night from al-Batha on the night of departure."]},"buhuth":{"ar":["قالت عائشة: (( لقيتُ رسولَ الله ﷺ مُدْلِجًا من الأبطح، وهو يهبط وأنا أصعد، أو ينزل وأنا أصعد )).","وقوله: إدلاجًا — بتشديد الدال — هو السير في آخر الليل وقت السَّحر، وهو المراد هنا. وقيل: بسكون الدال، وهو السير في أول الليل، وكلاهما صحيح. فإن كان الأول فالمراد سير النبي ﷺ من البطحاء إلى البيت الحرام لأداء طواف الوداع، وإن كان الثاني فالمراد سير عائشة في أول الليل مع أخيها للاعتمار من التنعيم."],"en":["Aishah said: “I met the Messenger of Allah ﷺ coming by night from al-Abtah while he was descending and I was ascending.”","The word idlajan, with a doubled dal, means traveling in the last part of the night at dawn, and that is what is intended here. It was also said with a still dal, meaning traveling in the first part of the night, and both are correct. If the first meaning is intended, then it refers to the Prophet’s travel from al-Batha to the Sacred House to perform the Farewell Tawaf. If the second is intended, then it refers to Aishah’s travel in the early night with her brother to perform Umrah from al-Tanim."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3068},{"key":"الامام_احمد","label":"الإمام أحمد","number":24493},{"key":"اللفظ_لابن_ماجہ_وصححہ_ابن_خزیمہ","label":"اللفظ لابن ماجه. وصححه ابن خزيمة","number":2997},{"key":"ahmad","label":"مسند الإمام أحمد","number":24493,"n":24493}]},{"num":5294,"demo":false,"sanad":"","matn":["عن ابن عمر، أنَّ رسولَ الله ﷺ كان إذا قفل من غزو أو حجٍّ أو عمرة، يكبِّر على كل شرفٍ من الأرض ثلاث تكبيرات، ثم يقول: (( لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، آيبون تائبون عابدون ساجدون لربنا حامدون، صدق الله وعده، ونصر عبده، وهزم الأحزاب وحده ))."],"takhrij":"متفق عليه: رواه مالك (٢٤٣)، والبخاري (١٧٩٧)، ومسلم (١٣٤٤).","grade":"متفق عليه","chapter_ar":"باب ما يقال إذا رجع من الحج أو العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (243), al-Bukhari (1797), and Muslim (1344).","chapter_en":"What is said when returning from Hajj or Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":140,"content":{"translation":{"en":["Ibn Umar narrated that when the Messenger of Allah ﷺ returned from a military expedition, or from Hajj, or from Umrah, he would say the takbir three times upon every elevated place of the land, then he would say: “There is no god but Allah alone, with no partner. To Him belongs the dominion and to Him belongs all praise, and He is over all things powerful. We return, repent, worship, prostrate, and praise our Lord. Allah fulfilled His promise, granted victory to His servant, and defeated the confederates alone.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":243},{"key":"bukhari","label":"البخاري","number":1797},{"key":"muslim","label":"مسلم","number":1344}]},{"num":5295,"demo":false,"sanad":"","matn":["عن ابن عمر، أنَّ رسولَ الله ﷺ أناخ بالبطحاء التي بذي الحليفة، فصلّى بها. قال نافع: وكان عبد الله بن عمر يفعل ذلك."],"takhrij":"متفق عليه: رواه مالك (٢١٩)، ومسلم (٤٣٠ :١٢٥٧)، والبخاريّ (١٧٦٧).","grade":"متفق عليه","chapter_ar":"باب نزول النبي ﷺ بذي الحليفة والصلاة بها لما رجع من مكة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (219), Muslim (1257/430), and al-Bukhari (1767).","chapter_en":"The Prophet’s stay at Dhu al-Hulayfah and praying there when he returned from Makkah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":141,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ made his camel kneel at the open stony ground that was at Dhu al-Hulayfah and prayed there. Nafi said: Abdullah ibn Umar used to do that as well."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":219},{"key":"muslim","label":"مسلم","number":430},{"key":"bukhari","label":"البخاريّ","number":1767}]},{"num":5296,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، عن النبيّ ﷺ أنه رُئي وهو في مُعَرَّسٍ بذي الحليفة ببطن الوادي، فقيل له: إنك ببطحاء مباركة."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٣٥)، ومسلم (٤٣٣ :١٣٤٦). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب نزول النبي ﷺ بذي الحليفة والصلاة بها لما رجع من مكة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1535) and Muslim (1346/433). The wording is that of al-Bukhari.","chapter_en":"The Prophet’s stay at Dhu al-Hulayfah and praying there when he returned from Makkah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":141,"content":{"translation":{"en":["Abdullah ibn Umar narrated from the Prophet ﷺ that he was seen while resting at the stopping place in Dhu al-Hulayfah, in the bottom of the valley, and it was said to him: “You are in a blessed stony plain.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1535},{"key":"muslim","label":"مسلم","number":433}]},{"num":5297,"demo":false,"sanad":"","matn":["عن العلاء بن الحضرميّ، قال: قال رسول الله ﷺ: (( يقيم المهاجر بمكة بعد قضاء نسكه ثلاثًا ))."],"takhrij":"متفق عليه: رواه البخاريّ (٣٩٣٣)، ومسلم (٤٤٢ :١٣٥٢). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب جواز الإقامة بمكة للمهاجر منها بعد قضاء نسكه ثلاث ليال","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3933) and Muslim (1352/442). The wording is that of Muslim.","chapter_en":"The permissibility for one who migrated from Makkah to stay there for three nights after completing the pilgrimage rites","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":142,"content":{"translation":{"en":["Al-Ala ibn al-Hadrami said: The Messenger of Allah ﷺ said: “The emigrant may stay in Makkah for three nights after completing his rites.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":3933},{"key":"muslim","label":"مسلم","number":442}]},{"num":5298,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال النبيّ ﷺ: (( صلاة في مسجدي هذا خير من ألف صلاة فيما سواه، إلا المسجد الحرام ))."],"takhrij":"متفق عليه: رواه مالك (٩)، والبخاري (١١٩٠)، ومسلم (١٣٩٤).","grade":"متفق عليه","chapter_ar":"باب فضيلة الصلاة في المسجد الحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (9), al-Bukhari (1190), and Muslim (1394).","chapter_en":"The virtue of prayer in al-Masjid al-Haram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":143,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “One prayer in this mosque of mine is better than a thousand prayers elsewhere, except for al-Masjid al-Haram.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"bukhari","label":"البخاري","number":1190},{"key":"muslim","label":"مسلم","number":1394}]},{"num":5299,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: قال رسول الله ﷺ: (( صلاة في مسجدي هذا أفضل من ألف صلاة فيما سواه إلا المسجد الحرام ))."],"takhrij":"صحيح: رواه مسلم (١٣٩٥).","grade":"صحيح","chapter_ar":"باب فضيلة الصلاة في المسجد الحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1395).","chapter_en":"The virtue of prayer in al-Masjid al-Haram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":143,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “One prayer in this mosque of mine is better than a thousand prayers elsewhere, except for al-Masjid al-Haram.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1395}]},{"num":5300,"demo":false,"sanad":"","matn":["عن ابن عباس قال: إن امرأةً اشتكت شكوى، فقالت: إن شفاني الله لأخرجن فلأصلينَّ في بيت المقدس. فبرأت، ثم تجهزت تريد الخروج، فجاءت ميمونة زوج النبي ﷺ تسلِّم عليها، فأخبرتها ذلك، فقالت: اجلسي، فكلي ما صنعتِ، وصلِّي في مسجد رسول الله ﷺ، فإني سمعت رسول الله ﷺ يقول: (( صلاة فيه أفضل من ألف صلاة فيما سواه من المساجد إلا مسجد الكعبة ))."],"takhrij":"صحيح: رواه مسلم في الحج (٥١٠ :١٣٩٦).","grade":"صحيح","chapter_ar":"باب فضيلة الصلاة في المسجد الحرام","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Hajj (1396/510).","chapter_en":"The virtue of prayer in al-Masjid al-Haram","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":143,"content":{"translation":{"en":["Ibn Abbas said: A woman became ill and said: “If Allah heals me, I will go out and pray in Bayt al-Maqdis.” She recovered and then prepared to leave. She then came to Maimunah, the wife of the Prophet ﷺ, to greet her and told her that. Maimunah said: “Sit down, eat what you have prepared, and pray in the mosque of the Messenger of Allah ﷺ, for I heard the Messenger of Allah ﷺ say: ‘One prayer in it is better than a thousand prayers in any other mosque, except the Mosque of the Kaabah.’”"]},"buhuth":{"ar":["وقد صح عن جابر وغيره: (( صلاة في مسجدي أفضل من ألف صلاة فيما سواه إلا المسجد الحرام، وصلاة في المسجد الحرام أفضل من مائة ألف صلاة فيما سواه )). والمراد بالمسجد الحرام مكة كلها، كما أن المراد بالصلاة جميع الصلوات من الفرائض والنوافل والجنائز وغيرها، على أصح أقوال العلماء."],"en":["It is authentically reported from Jabir and others: “One prayer in my mosque is better than a thousand prayers elsewhere except al-Masjid al-Haram, and one prayer in al-Masjid al-Haram is better than one hundred thousand prayers elsewhere.” What is meant by al-Masjid al-Haram is all of Makkah, and what is meant by prayer includes all prayers: obligatory prayers, voluntary prayers, funeral prayers, and others, according to the strongest view of the scholars."]}},"tuhfa":{},"refs":[{"key":"muslim/الحج","label":"مسلم في الحج","number":510}]},{"num":5301,"demo":false,"sanad":"","matn":["عن ابن عمر، أن رسول الله ﷺ دخل الكعبة هو وأسامة وبلال وعثمان بن طلحة الحجبي، فأغلقها عليه، ثم مكث فيها. قال ابن عمر: فسألت بلالًا حين خرج: ما صنع رسول الله ﷺ؟ قال: جعل عمودين عن يساره، وعمودًا عن يمينه، وثلاثة أعمدة وراءه، وكان البيت يومئذ على ستة أعمدة، ثم صلى."],"takhrij":"متفق عليه: رواه مالك (٢٠٦)، والبخاريّ (٥٠٥)، ومسلم (١٣٢٩).","grade":"متفق عليه","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (206), al-Bukhari (505), and Muslim (1329).","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ entered the Kaabah along with Usamah, Bilal, and Uthman ibn Talhah al-Hajabi. Then it was closed behind him, and he remained inside for some time. Ibn Umar said: I asked Bilal when he came out: What did the Messenger of Allah ﷺ do? He said: “He placed two pillars to his left, one pillar to his right, and three pillars behind him.” At that time the House had six pillars. Then he prayed."]},"buhuth":{"ar":["وكان ذلك في عام الفتح كما جاء التصريح عند البخاري (٤٤٠٠، ٤٢٨٩)، ومسلم (٣٨٩، ٣٩٠)."],"en":["This occurred in the year of the Conquest, as is explicitly mentioned in al-Bukhari (4400, 4289) and Muslim (389, 390)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":206},{"key":"bukhari","label":"البخاريّ","number":505},{"key":"muslim","label":"مسلم","number":1329}]},{"num":5302,"demo":false,"sanad":"","matn":["عن مجاهد، يقول: أُتي ابن عمر في منزله فقيل له: هذا رسول الله ﷺ قد دخل الكعبة. قال: فأقبلتُ فأجد رسول الله ﷺ قد خرج، وأجد بلالًا قائمًا بين البابين. فسألت بلالًا، فقلت: أصلّى النبي ﷺ في الكعبة؟ قال: نعم، ركعتين بين الساريتين اللتين على يساره إذا دخلت، ثم خرج فصلّى في وجه الكعبة ركعتين."],"takhrij":"صحيح: رواه البخاريّ (٣٩٧) و(١١٦٧).","grade":"صحيح","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (397) and (1167).","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Mujahid said: Ibn Umar was informed in his house: “This is the Messenger of Allah ﷺ, and he has entered the Kaabah.” He said: I hurried there and found that the Messenger of Allah ﷺ had already come out, and I found Bilal standing between the two doors. I asked Bilal: Did the Prophet ﷺ pray inside the Kaabah? He said: “Yes, two units of prayer between the two pillars that are on your left when you enter.” Then he came out and prayed two units facing the Kaabah."]},"buhuth":{"ar":["وفي رواية عند ابن خزيمة (٣٠١٦): (( ثم خرج فصلى ركعتين بين الحجر والباب ))."],"en":["In a narration recorded by Ibn Khuzaymah (3016): “Then he came out and prayed two units between the enclosure and the door.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":397},{"key":"و","label":"و","number":1167}]},{"num":5303,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: دخل رسول الله ﷺ يوم الفتح وهو على ناقة لأسامة، حتى أناخ بفناء الكعبة، ثم دعا عثمان بن طلحة بالمفتاح، فذهب إلى أمه فأبت أن تعطيه، فقال: لتُعطينه أو ليخرجن السيف من صلبي. فدفعته إليه، ففتح الباب، فدخل النبي ﷺ ودخل معه عثمان وبلال وأسامة، فأجافوا الباب مليًا. قال ابن عمر: وكنت رجلًا شابًا قويًا، فبدرت الناس فبدرتهم، فوجدت بلالًا قائمًا على الباب. قال: يا بلال، أين صلى رسول الله ﷺ؟ قال: بين العمودين المقدَّمين. ونسيت أن أسأله كم صلى."],"takhrij":"صحيح: رواه ابن خزيمة (٣٠١٠)، ومسلم (٣٩٠ :١٣٢٩).","grade":"صحيح","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (3010) and Muslim (1329/390).","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Ibn Umar said: On the Day of the Conquest, the Messenger of Allah ﷺ entered while riding Usamah’s camel until he made it kneel in the courtyard of the Kaabah. Then he called for Uthman ibn Talhah to bring the key. He went to his mother, but she refused to give it to him. He said: “You must give it, or the sword will come out from my side.” So she handed it over to him. He opened the door, and the Prophet ﷺ entered, and Uthman, Bilal, and Usamah entered with him. Then they closed the door for a while. Ibn Umar said: I was a young, strong man, so I rushed ahead of the people and found Bilal standing at the door. I said: O Bilal, where did the Messenger of Allah ﷺ pray? He said: “Between the two front pillars.” And I forgot to ask him how much he prayed."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":3010},{"key":"muslim","label":"مسلم","number":390}]},{"num":5304,"demo":false,"sanad":"","matn":["عن سماك الحنفي، قال: سمعت ابن عمر يقول: إن رسول الله ﷺ صلى في البيت، وستأتون من ينهاكم عنه فتسمعون منه - يعني ابن عباس. قال حجاج: فتسمعون من قوله. قال ابن جعفر: وابن عباس جالس قريبًا منه."],"takhrij":"صحيح: رواه الإمام أحمد (٥٠٥٣)، وابن حبان (٣٢٠٠)، والبيهقي (٣٢٨/٢).","grade":"صحيح","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (5053), Ibn Hibban (3200), and al-Bayhaqi (2/328).","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Simak al-Hanafi said: I heard Ibn Umar say: The Messenger of Allah ﷺ prayed inside the House, and you will come to people who will forbid you from it, and you will listen to them — meaning Ibn Abbas. One narrator said: “You will listen to his statement.” Another said: And Ibn Abbas was sitting nearby."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":5053},{"key":"ibnhibban","label":"ابن حبان","number":3200},{"key":"البیہقی","label":"البيهقي","number":328},{"key":"ahmad","label":"مسند الإمام أحمد","number":5053,"n":5053}]},{"num":5305,"demo":false,"sanad":"","matn":["عن أبي الشعثاء، قال: خرجت حاجًّا فدخلت البيت، فلما كنت عند الساريتين مضيتُ حتى لزقت بالحائط. قال: وجاء ابن عمر حتى قام إلى جنبي، فصلى أربعًا. قال: فلما صلى قلت له: أين صلى رسول الله ﷺ من البيت؟ قال: فقال: هاهنا. أخبرني أسامة بن زيد أنه صلى. قال: قلت: فكم صلى؟ قال: على هذا أجدني ألوم نفسي أن مكثت معه عمرًا ثم لم أسأله كم صلى. فلما كان العام المقبل، قال: خرجت حاجًّا، قال: فجئت في مقامه، قال: فجاء ابن الزبير حتى قام إلى جنبي، فلم يزل يزاحمني حتى أخرجني منه، ثم صلى فيه أربعًا."],"takhrij":"صحيح: رواه الإمام أحمد (٢١٧٨٠)، والبزار (٢٥٦٢)، والطبراني في الكبير (١٢٨/١)، وصححه ابن حبان (٣٢٠٥).","grade":"صحيح","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (21780), al-Bazzar (2562), al-Tabarani in al-Kabir (1/128), and authenticated by Ibn Hibban (3205).","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Abu al-Shatha said: I went out for Hajj and entered the House. When I was by the two pillars, I pressed myself against the wall. Then Ibn Umar came and stood beside me and prayed four units. When he finished, I asked him: Where in the House did the Messenger of Allah ﷺ pray? He said: “Here. Usamah ibn Zayd informed me that he prayed.” I said: How much did he pray? He said: For this reason I blame myself: I stayed with him for a long time, yet I did not ask him how much he prayed. Then, in the following year, I went for Hajj again and came to that same spot. Then Ibn al-Zubayr came and stood beside me and kept pressing me until he moved me away from it, then he prayed there four units."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":21780},{"key":"البزار","label":"البزار","number":2562},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":128},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":3205},{"key":"ahmad","label":"مسند الإمام أحمد","number":21780,"n":21780}]},{"num":5306,"demo":false,"sanad":"","matn":["عن أشعث بن أبي الشعثاء، عن أبيه، قال: سمعت ابن عمر يقول: جاء النبي ﷺ يمشي بين أسامة بن زيد وبلال حتى دخل الكعبة، وفيها خشبة معترضة، فلما خرج بلال سألته: كيف صنع رسول الله ﷺ؟ قال: ترك من الخشبة ثلثها عن يمينه، وصلى في الثلث الباقي. قال: قلت: كم صلى؟ قال: لم أسأل بلالًا عنها."],"takhrij":"صحيح: رواه عبد الرزاق (٩٠٧١)، والطبراني في الكبير (٣٢٦/١).","grade":"صحيح","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abd al-Razzaq (9071) and al-Tabarani in al-Kabir (1/326).","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Ashath ibn Abi al-Shatha narrated from his father that he heard Ibn Umar say: The Prophet ﷺ came walking between Usamah ibn Zayd and Bilal until he entered the Kaabah, and in it there was a cross beam. When Bilal came out, I asked him: How did the Messenger of Allah ﷺ pray? He said: “He left one-third of the beam to his right and prayed in the remaining third.” I said: How much did he pray? He said: I did not ask Bilal about that."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":9071},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":326},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":9393,"n":9391}]},{"num":5307,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: كان النبي ﷺ يصلي وبينه وبين القبلة مقدار ثلاثة أذرع."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (٣٢٠١).","grade":"صحيح","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban in his Sahih (3201).","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Abdullah ibn Umar said: The Prophet ﷺ used to pray with a distance of about three cubits between him and the wall of the Kaabah in front of him."]}},"tuhfa":{},"refs":[{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":3201},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":6827,"n":6826}]},{"num":5308,"demo":false,"sanad":"","matn":["عن بلال: أن النبي ﷺ صلّى في جوف الكعبة."],"takhrij":"صحيح: رواه الترمذيّ (٨٧٤)، وصححه ابن خزيمة (٣٠٠٨). قال الترمذي: (( حسن صحيح )).","grade":"صحيح","chapter_ar":"باب الصلاة في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (874), and authenticated by Ibn Khuzaymah (3008). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"Prayer inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":144,"content":{"translation":{"en":["Bilal narrated that the Prophet ﷺ prayed inside the interior of the Kaabah."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":874},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":3008}]},{"num":5309,"demo":false,"sanad":"","matn":["عن عطاء قال:","سمعت ابن عباس يقول:","إنما أُمرتم بالطواف، ولم تؤمروا بدخوله.","قال: لم يكن ينهى عن دخوله، ولكني سمعته يقول:","أخبرني أسامة بن زيد أن النبي ﷺ لما دخل البيت دعا في نواحيه كلها، ولم يصلِّ فيه حتى خرج، فلما خرج ركع في قُبل البيت ركعتين، وقال:","«هَذِهِ الْقِبْلَةُ».","قلت له:","ما نواحيها؟ أفي زواياها؟","قال:","بل في كل قبلة من البيت."],"takhrij":"صحيح: رواه مسلم (١٣٣٠)، والبخاري (٣٩٨).","grade":"صحيح","chapter_ar":"باب من قال: لم يصلِّ النبي ﷺ في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1330) and al-Bukhārī (398).","chapter_en":"Those who said that the Prophet ﷺ did not pray inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":145,"content":{"translation":{"en":["ʿAṭāʾ said:","I heard Ibn ʿAbbās say:","“You were only commanded to perform Ṭawāf around it; you were not commanded to enter it.”","He said:","He did not forbid entering it, but I heard him say:","Usāmah ibn Zayd informed me that when the Prophet ﷺ entered the House, he supplicated in all of its sides and did not pray inside it until he came out.","When he came out, he performed two rakʿahs facing the front of the House and said:","“This is the Qiblah.”","I asked him:","“What does ‘its sides’ mean? Did he mean its corners?”","He replied:","“Rather, every side of the House.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1330},{"key":"bukhari","label":"البخاري","number":398}]},{"num":5310,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: إن رسول الله ﷺ لما قدم أبى أن يدخل البيت، وفيه الآلهة، فأمر بها فأخرجت، فأخرجوا صورة إبراهيم وإسماعيل في أيديهما الأزلام. فقال رسول الله ﷺ: (( قاتلهم الله! أما والله قد علموا أنهما لم يستقسما بها قط )). فدخل البيت، فكبّر في نواحيه، ولم يصلِّ فيه."],"takhrij":"صحيح: رواه البخاريّ (١٦٠١).","grade":"صحيح","chapter_ar":"باب من قال: لم يصلِّ النبي ﷺ في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1601).","chapter_en":"Those who said that the Prophet ﷺ did not pray inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":145,"content":{"translation":{"en":["Abdullah ibn Abbas said: When the Messenger of Allah ﷺ arrived, he refused to enter the House while idols were in it. So he ordered that they be removed. They then brought out an image of Ibrahim and Ismail with divining arrows in their hands. The Messenger of Allah ﷺ said: “May Allah destroy them! By Allah, they knew full well that those two never used divining arrows.” Then he entered the House, said the takbir in its different sides, and did not pray inside it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1601}]},{"num":5311,"demo":false,"sanad":"","matn":["عن ابن عباس، أن النبي ﷺ دخل الكعبة وفيها ست سوارٍ، فقام عند سارية، فدعا ولم يصلِّ."],"takhrij":"صحيح: رواه مسلم (١٣٣١). ورواه ابن حبان في صحيحه (٣٢٠٧)، وفيه: (( فقام عند كل سارية ودعا ولم يصلِّ )).","grade":"صحيح","chapter_ar":"باب من قال: لم يصلِّ النبي ﷺ في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1331). Ibn Hibban also narrated it in his Sahih (3207), and in that wording: “He stood by each pillar, supplicated, and did not pray.”","chapter_en":"Those who said that the Prophet ﷺ did not pray inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":145,"content":{"translation":{"en":["Ibn Abbas narrated that the Prophet ﷺ entered the Kaabah when there were six pillars in it. He stood by a pillar, supplicated, and did not pray."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1331},{"key":"ورواہ_ابن_حبان/صحیحہ","label":". ورواه ابن حبان في صحيحه","number":3207}]},{"num":5312,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: حدثني أخي الفضل بن عباس، وكان معه حين دخل البيت، أن رسول الله ﷺ لم يصلِّ في الكعبة، ولكنه لما خرج فنزل ركع ركعتين عند باب الكعبة."],"takhrij":"صحيح: رواه الإمام أحمد (١٨١٩)، وعبد الرزاق في مصنفه (٩٠٥٧).","grade":"صحيح","chapter_ar":"باب من قال: لم يصلِّ النبي ﷺ في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (1819) and Abd al-Razzaq in his Musannaf (9057).","chapter_en":"Those who said that the Prophet ﷺ did not pray inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":145,"content":{"translation":{"en":["Ibn Abbas said: My brother al-Fadl ibn Abbas informed me — and he was with him when he entered the House — that the Messenger of Allah ﷺ did not pray in the Kaabah, but when he came out and descended, he prayed two units at the door of the Kaabah."]},"buhuth":{"ar":["ورواه الإمام أحمد أيضًا (١٨٣٠، ١٧٩٥) من طريق آخر عن الفضل بن عباس: أن رسول الله ﷺ قام في الكعبة فسبَّح وكبَّر، ودعا الله عز وجل واستغفر، ولم يركع ولم يسجد."],"en":["Imam Ahmad also narrated it (1830, 1795) through another chain from al-Fadl ibn Abbas: that the Messenger of Allah ﷺ stood in the Kaabah, glorified Allah, declared His greatness, supplicated to Allah the Mighty and Majestic, and sought His forgiveness, but did not bow or prostrate."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":1819},{"key":"عبد_الرزاق/مصنفہ","label":"عبد الرزاق في مصنفه","number":9057},{"key":"ahmad","label":"مسند الإمام أحمد","number":1819,"n":1819}]},{"num":5313,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: حدثني أخي الفضل بن عباس وكان معه حين دخل البيت: أن رسول الله ﷺ لم يصلِّ في الكعبة، ولكنه لما دخلها وقع ساجدًا بين العمودين، ثم جلس يدعو."],"takhrij":"حسن: رواه أحمد (١٨٠١)، والطبراني (٢٧٠/١٨)، وصححه ابن خزيمة (٣٠٠٧).","grade":"حسن","chapter_ar":"باب من قال: لم يصلِّ النبي ﷺ في الكعبة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (1801) and al-Tabarani (18/270), and authenticated by Ibn Khuzaymah (3007).","chapter_en":"Those who said that the Prophet ﷺ did not pray inside the Kaabah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":145,"content":{"translation":{"en":["Ibn Abbas said: My brother al-Fadl ibn Abbas informed me — and he was with him when he entered the House — that the Messenger of Allah ﷺ did not pray in the Kaabah, but when he entered it he fell in prostration between the two pillars, then sat supplicating."]},"buhuth":{"ar":["ويجمع بين حديث بلال وبين حديث أسامة بن زيد والفضل بن عباس بأن الزيادة مقبولة، والمثبت مقدّم على النافي إذا رواه أهل الثبت. فقيل: إن أسامة بن زيد انشغل بالدعاء فلم ير النبي ﷺ يصلي، ورآه بلال. وقيل: لعله خرج لحاجة ثم رجع، وقد صلى النبي ﷺ فلم يره. وقيل: إنه بعد إغلاق البيت تكون فيه الظلمة فلم يره أسامة، ورآه بلال لقربه."],"en":["The way to reconcile the narration of Bilal with the narration of Usamah ibn Zayd and al-Fadl ibn Abbas is that the additional report is accepted, and the one affirming something is given precedence over the one denying it when both are narrated by reliable people. It was said that Usamah ibn Zayd was occupied with supplication and did not see the Prophet ﷺ pray, while Bilal did. It was also said that he may have gone out for a need and then returned, and the Prophet ﷺ had prayed without him seeing it. It was also said that after the House was closed, it became dark inside, so Usamah did not see him, while Bilal did because he was closer."]}},"tuhfa":{},"refs":[{"key":"الطبرانی","label":"الطبراني","number":270},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":3007},{"key":"ahmad","label":"مسند الإمام أحمد","number":1801,"n":1801}]},{"num":5314,"demo":false,"sanad":"","matn":["عن إسماعيل بن أبي خالد، قال: قلت لعبد الله بن أبي أوفى صاحب رسول الله ﷺ: أدخل النبي ﷺ في عمرته؟ قال: لا."],"takhrij":"متفق عليه: رواه مسلم (١٣٣٢)، والبخاريّ (١٦٠٠).","grade":"متفق عليه","chapter_ar":"باب إنَّ النبي ﷺ لم يدخل البيت في عمرته","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1332) and al-Bukhari (1600).","chapter_en":"The Prophet ﷺ did not enter the House during his Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":146,"content":{"translation":{"en":["Ismail ibn Abi Khalid said: I said to Abdullah ibn Abi Awfa, the companion of the Messenger of Allah ﷺ: Did the Prophet ﷺ enter the House during his Umrah? He said: No."]},"buhuth":{"ar":["وذلك في عمرة القضاء كما تدل عليه رواية البخاريّ (٤١٨٨) بقوله: (( فكنا نستره من أهل مكة لا يرميه أحد بشيء ))."],"en":["This was during the Umrah of Compensation, as indicated in al-Bukhari (4188): “We were shielding him from the people of Makkah so that no one would throw anything at him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1332},{"key":"bukhari","label":"البخاريّ","number":1600}]},{"num":5315,"demo":false,"sanad":"","matn":["عن عائشة، أنها قالت: كنت أحب أن أدخل البيت فأصلي فيه، فأخذ رسول الله ﷺ بيدي فأدخلني في الحجر وقال لي: (( صلِّي في الحجر إذا أردت دخول البيت، فإنما هو قطعة من البيت، ولكن قومك استقصروا حين بنوا الكعبة، فأخرجوه من البيت ))."],"takhrij":"حسن: رواه أبو داود (٢٠٢٨)، والنسائيّ (٢٩١٢)، والترمذيّ (٨٧٦)، والإمام أحمد (٢٤٣٨٤).","grade":"حسن","chapter_ar":"باب الصلاة في الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2028), al-Nasai (2912), al-Tirmidhi (876), and Imam Ahmad (24384).","chapter_en":"Prayer in the Hijr","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":147,"content":{"translation":{"en":["Aishah said: I used to love to enter the House and pray inside it. So the Messenger of Allah ﷺ took me by the hand and brought me into the Hijr and said to me: “Pray in the Hijr if you wish to enter the House, for it is only a part of the House. But your people ran short of funds when they built the Kaabah, so they left it outside the House.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2028},{"key":"nasai","label":"النسائيّ","number":2912},{"key":"tirmidhi","label":"الترمذيّ","number":876},{"key":"الامام_احمد","label":"الإمام أحمد","number":24384},{"key":"ahmad","label":"مسند الإمام أحمد","number":24384,"n":24384}]},{"num":5316,"demo":false,"sanad":"","matn":["عن عائشة، قالت: قلت: يا رسول الله، ألا أدخل البيت؟ قال: (( ادخلي الحجر فإنه من البيت ))."],"takhrij":"صحيح: رواه النسائيّ (٢٩١١).","grade":"صحيح","chapter_ar":"باب الصلاة في الحِجر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasai (2911).","chapter_en":"Prayer in the Hijr","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":147,"content":{"translation":{"en":["Aishah said: I said: O Messenger of Allah ﷺ, should I not enter the House? He said: “Enter the Hijr, for it is part of the House.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2911}]},{"num":5317,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول الله ﷺ: (( لا تُشدُّ الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجد رسول الله ﷺ، والمسجد الأقصى ))."],"takhrij":"متفق عليه: رواه البخاريّ (١١٨٩)، ومسلم (١٣٩٧).","grade":"متفق عليه","chapter_ar":"باب استحباب زيارة المدينة للصلاة في مسجد النبي ﷺ، ثم من أتى المدينة يستحب له إتيان قبر النبي ﷺ وصاحبيه، وقبور شهداء أحد والبقيع للسلام عليهم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1189) and Muslim (1397).","chapter_en":"The recommendation of visiting Madinah to pray in the Prophet’s Mosque, and that whoever comes to Madinah is recommended to visit the grave of the Prophet ﷺ and his two companions, and the graves of the martyrs of Uhud and al-Baqi to greet them with peace","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":148,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Mounts are not to be specially prepared for travel except to three mosques: al-Masjid al-Haram, the Mosque of the Messenger of Allah ﷺ, and al-Masjid al-Aqsa.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1189},{"key":"muslim","label":"مسلم","number":1397}]},{"num":5318,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن رسول الله ﷺ قال: (( ما من أحدٍ يسلِّم عليَّ إلا ردَّ الله عليَّ روحي حتى أردَّ عليه السلام ))."],"takhrij":"حسن: رواه أبو داود (٢٠٤١)، والإمام أحمد (١٠٨١٥)، والبيهقي في الكبرى (٢٤٥/٥).","grade":"حسن","chapter_ar":"باب استحباب زيارة المدينة للصلاة في مسجد النبي ﷺ، ثم من أتى المدينة يستحب له إتيان قبر النبي ﷺ وصاحبيه، وقبور شهداء أحد والبقيع للسلام عليهم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2041), Imam Ahmad (10815), and al-Bayhaqi in al-Kubra (5/245).","chapter_en":"The recommendation of visiting Madinah to pray in the Prophet’s Mosque, and that whoever comes to Madinah is recommended to visit the grave of the Prophet ﷺ and his two companions, and the graves of the martyrs of Uhud and al-Baqi to greet them with peace","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":148,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “No one sends peace upon me except that Allah returns my soul to me so that I may return peace to him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2041},{"key":"الامام_احمد","label":"الإمام أحمد","number":10815},{"key":"البیہقی/الکبری","label":"البيهقي في الكبرى","number":245},{"key":"ahmad","label":"مسند الإمام أحمد","number":10815,"n":10815},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10270,"n":10358}]},{"num":5319,"demo":false,"sanad":"","matn":["عن أبي هريرة، قال: قال رسول اللّٰه ﷺ: (( لا تجعلوا بيوتكم قبورًا، ولا تجعلوا قبري عيدًا، وصلّوا عليَّ، فإنّ صلاتكم تبلغني حيث كنتم ))."],"takhrij":"حسن: رواه أبو داود (٢٠٤٢)، والإمام أحمد (٨٨٠٤).","grade":"حسن","chapter_ar":"باب استحباب زيارة المدينة للصلاة في مسجد النبي ﷺ، ثم من أتى المدينة يستحب له إتيان قبر النبي ﷺ وصاحبيه، وقبور شهداء أحد والبقيع للسلام عليهم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2042) and Imam Ahmad (8804).","chapter_en":"The recommendation of visiting Madinah to pray in the Prophet’s Mosque, and that whoever comes to Madinah is recommended to visit the grave of the Prophet ﷺ and his two companions, and the graves of the martyrs of Uhud and al-Baqi to greet them with peace","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":148,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Do not turn your houses into graves, and do not turn my grave into a place of recurring gathering. Send blessings upon me, for your blessings reach me wherever you are.”"]},"buhuth":{"ar":["وقوله: (( عيدًا )) أي لا تجعلوه مجمعًا كالأعياد التي يقصد الناس الاجتماع إليها للصلاة، بل يزار قبره صلوات الله وسلامه عليه كما كان يزوره الصحابة رضوان الله عليهم على الوجه الذي يرضاه ويحبه صلوات الله وسلامه عليه. قاله ابن القيم في “تهذيب السنن” (٤٤٧/٢)."],"en":["His saying, “a recurring gathering,” means: do not make it a place of assembly like festival gatherings that people repeatedly intend for congregating. Rather, his grave is to be visited in the manner the Companions visited it, in the way he would be pleased with and love. This was stated by Ibn al-Qayyim in Tahdhib al-Sunan (2/447)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2042},{"key":"الامام_احمد","label":"الإمام أحمد","number":8804},{"key":"ahmad","label":"مسند الإمام أحمد","number":8804,"n":8804}]},{"num":5320,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، قال: قال رسول اللّٰه ﷺ: (( إنّ لله ملائكةً سيّاحين في الأرض، يبلّغونني من أمّتي السلام ))."],"takhrij":"صحيح: رواه النسائيّ (١٢٨٢)، وفي “اليوم والليلة” (٦٦)، والإمام أحمد (٣٦٦٦)، وصححه ابن حبان (٩١٤).","grade":"صحيح","chapter_ar":"باب استحباب زيارة المدينة للصلاة في مسجد النبي ﷺ، ثم من أتى المدينة يستحب له إتيان قبر النبي ﷺ وصاحبيه، وقبور شهداء أحد والبقيع للسلام عليهم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (1282), in al-Yawm wa al-Laylah (66), and by Imam Ahmad (3666). It was authenticated by Ibn Hibban (914).","chapter_en":"The recommendation of visiting Madinah to pray in the Prophet’s Mosque, and that whoever comes to Madinah is recommended to visit the grave of the Prophet ﷺ and his two companions, and the graves of the martyrs of Uhud and al-Baqi to greet them with peace","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":148,"content":{"translation":{"en":["Abdullah ibn Masud said: The Messenger of Allah ﷺ said: “Allah has angels who travel throughout the earth, conveying to me the greetings of peace from my community.”"]},"buhuth":{"ar":["وكان ابن عمر إذا قدم من السفر أتى القبر، فقال: « السلام عليك يا رسول الله، السلام عليك يا أبا بكر، السلام عليك يا أبتاه ». ولا يقف عند القبر للدعاء لنفسه؛ لأنّ أحدًا من الصحابة لم يكن يفعله، ولكن كانوا يستقبلون القبلة."],"en":["When Ibn Umar returned from travel, he would come to the grave and say: “Peace be upon you, O Messenger of Allah ﷺ. Peace be upon you, O Abu Bakr. Peace be upon you, O my father.” He would not stand at the grave to supplicate for himself, because none of the Companions used to do that. Rather, they would face the direction of prayer."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":1282},{"key":"وفی_الیوم_واللیلہ","label":"وفي “اليوم والليلة”","number":66},{"key":"الامام_احمد","label":"الإمام أحمد","number":3666},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":914},{"key":"ahmad","label":"مسند الإمام أحمد","number":3666,"n":3666}]},{"num":5321,"demo":false,"sanad":"","matn":["عن ربيعة بن الهدير، قال: ما سمعت طلحة بن عبيد الله يحدّث عن رسول الله ﷺ حديثًا قط غير حديث واحد، قال: (( خرجنا مع رسول الله ﷺ يريد قبور الشهداء، حتى إذا أشرفنا على حرّة واقم، فلما تدلّينا منها وإذا قبورٌ بمُحنية، قال: قلنا: يا رسول الله، أقبور إخواننا هذه؟ قال: قبور أصحابنا. فلما جئنا قبور الشهداء، قال: هذه قبور إخواننا ))."],"takhrij":"حسن: رواه أبو داود (٢٠٤٣)، وأحمد (١٣٨٧)، والبزار - كشف الأستار (٩٥٥).","grade":"حسن","chapter_ar":"باب استحباب زيارة المدينة للصلاة في مسجد النبي ﷺ، ثم من أتى المدينة يستحب له إتيان قبر النبي ﷺ وصاحبيه، وقبور شهداء أحد والبقيع للسلام عليهم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2043), Ahmad (1387), and al-Bazzar in Kashf al-Astar (955).","chapter_en":"The recommendation of visiting Madinah to pray in the Prophet’s Mosque, and that whoever comes to Madinah is recommended to visit the grave of the Prophet ﷺ and his two companions, and the graves of the martyrs of Uhud and al-Baqi to greet them with peace","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":148,"content":{"translation":{"en":["Rabi‘ah ibn al-Hudayr said: I never heard Talhah ibn Ubayd Allah narrate from the Messenger of Allah ﷺ any hadith except one. He said: “We went out with the Messenger of Allah ﷺ intending the graves of the martyrs, until when we came to overlook Harrah Waqim, and we descended from it, there were graves at a bend in the ground. We said: O Messenger of Allah ﷺ, are these the graves of our brothers? He said: ‘These are the graves of our companions.’ Then when we came to the graves of the martyrs, he said: ‘These are the graves of our brothers.’”"]},"buhuth":{"ar":["وقوله: (( حرّة واقم )) هي الحرّة التي كانت بها الوقعة التي أوقعها بهم مسلم بن عقبة أيام يزيد بن معاوية، وهي إحدى حرّتي المدينة، وهي الشرقية. والحرّة الغربية يقال لها: (( وبرة ))."],"en":["“Harrah Waqim” is the lava plain where the well-known incident took place during the days of Yazid ibn Mu‘awiyah. It is one of the two lava plains of Madinah, specifically the eastern one. The western lava plain is called Wabrah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2043},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":955},{"key":"ahmad","label":"مسند الإمام أحمد","number":1387,"n":1387}]},{"num":5322,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: كان النبي ﷺ يأتي قباء راكبًا وماشيًا."],"takhrij":"متفق عليه: رواه البخاريّ (١١٩٤)، ومسلم (١٣٩٩). وفي رواية: (( فيصلي فيه ركعتين )).","grade":"متفق عليه","chapter_ar":"باب إتيان مسجد قباء للصلاة فيه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1194) and Muslim (1399). In another wording: “and he would pray two units there.”","chapter_en":"Going to the Mosque of Quba to pray there","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":149,"content":{"translation":{"en":["Abdullah ibn Umar said: The Prophet ﷺ used to go to Quba, riding and walking."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1194},{"key":"muslim","label":"مسلم","number":1399}]},{"num":5323,"demo":false,"sanad":"","matn":["عن سهل بن حنيف، قال: قال رسول الله ﷺ: (( من تطهّر في بيته، ثم أتى مسجد قباء، فصلّى فيه صلاةً، كان له كأجر عمرة ))."],"takhrij":"حسن: رواه النسائيّ (٢/٣٧)، وابن ماجه (١٤١٢)، وصحّحه الحاكم (٣/١٢).","grade":"حسن","chapter_ar":"باب إتيان مسجد قباء للصلاة فيه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (2/37) and Ibn Majah (1412), and authenticated by al-Hakim (3/12).","chapter_en":"Going to the Mosque of Quba to pray there","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":149,"content":{"translation":{"en":["Sahl ibn Hunayf said: The Messenger of Allah ﷺ said: “Whoever purifies himself in his home, then comes to the Mosque of Quba and prays in it, will have a reward like that of an Umrah.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائيّ","number":2},{"key":"ibnmajah","label":"ابن ماجه","number":1412},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":3}]},{"num":5324,"demo":false,"sanad":"","matn":["عن عائشة، قالت: إنّ رسول الله ﷺ قال: (( إذا قضى أحدكم حجّه، فليعجّل الرحلة إلى أهله، فإنّه أعظم لأجره ))."],"takhrij":"حسن: رواه الدارقطنيّ (٢٧٩٠)، والحاكم (٤٧٧/١)، والبيهقيّ (٢٥٩/٥).","grade":"حسن","chapter_ar":"باب التعجيل في الرجوع إلى البلد بعد انقضاء مناسك الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (2790), al-Hakim (1/477), and al-Bayhaqi (5/259).","chapter_en":"Hastening to return home after completing the rites of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع ما جاء في صفة حجّة النبي ﷺ كما رواها جابر وغيره، وما جاء فيه من الأحكام","group_en":"Sections on the description of the Prophet’s Hajj as narrated by Jābir and others, and the rulings derived from it","part_no":16,"group_no":5,"chapter_no":150,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ said: “When one of you completes his Hajj, let him hasten in returning to his family, for that is greater for his reward.”"]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطنيّ","number":2790},{"key":"hakim","label":"الحاكم","number":477},{"key":"البیہقی","label":"البيهقيّ","number":259}]},{"num":5325,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: تمتّع رسول الله ﷺ في حجّة الوداع بالعمرة إلى الحج، وأهدى، فساق معه الهدي من ذي الحليفة، وبدأ رسول الله ﷺ فأهلّ بالعمرة، ثم أهلّ بالحج. وتمتّع الناس مع رسول الله ﷺ بالعمرة إلى الحج، فكان من الناس من أهدى فساق الهدي، ومنهم من لم يهدِ. فلما قدم رسول الله ﷺ مكة، قال للناس: (( من كان منكم أهدى، فإنه لا يحلّ من شيء حرم منه حتى يقضي حجّه. ومن لم يكن منكم أهدى، فليطف بالبيت وبالصفا والمروة، وليقصّر وليحلل، ثم ليهلّ بالحج، وليهدِ. فمن لم يجد هديًا، فليصم ثلاثة أيام في الحج وسبعة إذا رجع إلى أهله ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٩١)، ومسلم (١٢٢٧).","grade":"متفق عليه","chapter_ar":"باب وجوب الهدي على المتمتع والقارن، والصوم لمن لم يجد الهدي ثلاثة أيام في الحج وسبعة إذا رجع إلى أهله","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1691) and Muslim (1227).","chapter_en":"The obligation of an offering upon the one doing the combined pilgrimage with a break between rites and the one combining both rites together, and fasting for whoever does not find an offering: three days during Hajj and seven when he returns to his family","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Umar said: The Messenger of Allah ﷺ performed the pilgrimage of farewell combining the lesser pilgrimage with the greater pilgrimage, and he brought an offering with him from Dhu al-Hulayfah. The Messenger of Allah ﷺ began by entering the lesser pilgrimage, then entered the greater pilgrimage. The people also did the same with the Messenger of Allah ﷺ. Some people brought an offering and drove it with them, and some did not. When the Messenger of Allah ﷺ arrived in Makkah, he said to the people: “Whoever among you has brought an offering must not come out of the state of consecration from anything that became forbidden to him until he completes his pilgrimage. Whoever among you has not brought an offering should circle the House, go between al-Safa and al-Marwah, shorten his hair, come out of the state of consecration, then enter the pilgrimage, and offer a sacrifice. Whoever cannot find an offering must fast three days during the pilgrimage and seven when he returns to his family.”"]},"intro":{"ar":["قال الله تعالى: ( فَمَن تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ ۚ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ ۗ تِلْكَ عَشَرَةٌ كَامِلَةٌ ۗ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُ حَاضِرِي الْمَسْجِدِ الْحَرَامِ ) [سورة البقرة: ١٩٦].","وفيه نسخ وجوب ما كان قبل الإسلام من سوق الهدي في الحج والعمرة، ولذا ساق النبي ﷺ في عمرة الحديبية، وانحصر وجوب الهدي على المتمتع والقارن، وبقي استحبابه على المفرد والمعتمر."],"en":["Allah Most High said: “Whoever enjoys the lesser pilgrimage before the greater pilgrimage must offer whatever offering is easy to obtain. But whoever cannot find one must fast three days during the pilgrimage and seven when you return. That makes ten complete. That is for the one whose family does not live near the Sacred Mosque.” [al-Baqarah: 196]","This contains the abrogation of what had been obligatory before Islam regarding bringing an offering in the pilgrimage and the lesser pilgrimage. For that reason, the Prophet ﷺ brought an offering in the Umrah of al-Hudaybiyah. The obligation of the offering then remained only upon the pilgrim doing the combined pilgrimage with a break between rites and the one combining both rites together, while it remained recommended for the pilgrim doing only the greater pilgrimage and the one doing only the lesser pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1691},{"key":"muslim","label":"مسلم","number":1227}]},{"num":5326,"demo":false,"sanad":"","matn":["عن عروة بن الزبير، أنّ عائشة زوج النبيّ ﷺ أخبرته عن رسول الله ﷺ في تمتّعه بالعمرة إلى الحج، فتمتّع الناس معه."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٩٢)، ومسلم (١٢٢٨).","grade":"متفق عليه","chapter_ar":"باب وجوب الهدي على المتمتع والقارن، والصوم لمن لم يجد الهدي ثلاثة أيام في الحج وسبعة إذا رجع إلى أهله","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1692) and Muslim (1228).","chapter_en":"The obligation of an offering upon the one doing the combined pilgrimage with a break between rites and the one combining both rites together, and fasting for whoever does not find an offering: three days during Hajj and seven when he returns to his family","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Urwah ibn al-Zubayr narrated that Aishah, the wife of the Prophet ﷺ, informed him about the Messenger of Allah ﷺ regarding his combining the lesser pilgrimage with the greater pilgrimage, and that the people did the same with him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1692},{"key":"muslim","label":"مسلم","number":1228}]},{"num":5327,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: ثم انصرف إلى المنحر، فنحر ثلاثًا وستين بيده، ثم أعطى عليًّا فنحر ما غبر، وأشركه في هديه."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب ما جاء في هدايا رسول الله ﷺ في حجّة الوداع والحديبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"What has been narrated regarding the offerings of the Messenger of Allah ﷺ in the Farewell Pilgrimage and at al-Hudaybiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn Abdullah said: Then he turned to the place of sacrifice and slaughtered sixty-three with his own hand. Then he gave Ali the remainder, and he slaughtered what was left, and he made him share in his offering."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5328,"demo":false,"sanad":"","matn":["عن ابن عباس:","أن رسول الله ﷺ أهدى عام الحديبية في هدايا رسول الله ﷺ جملًا كان لأبي جهل، في رأسه بُرَةٌ من فضة.","وفي لفظ:","«لِيَغِيظَ بِذَلِكَ الْمُشْرِكِينَ»."],"takhrij":"حسن: رواه أبو داود (١٧٤٩)، وأحمد (٢٣٦٢).","grade":"حسن","chapter_ar":"باب ما جاء في هدايا رسول الله ﷺ في حجّة الوداع والحديبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1749) and Aḥmad (2362).","chapter_en":"What has been narrated regarding the offerings of the Messenger of Allah ﷺ in the Farewell Pilgrimage and at al-Hudaybiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās reported:","During the year of al-Ḥudaybiyah, the Messenger of Allah ﷺ included among his sacrificial animals a camel that had belonged to Abū Jahl, with a silver ring on its head.","In another wording:","“So that by doing so he might anger the polytheists.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1749},{"key":"ahmad","label":"مسند الإمام أحمد","number":2362,"n":2362}]},{"num":5329,"demo":false,"sanad":"","matn":["عن جابر، قال: نحر رسول الله ﷺ عن نسائه بقرة في حجّته."],"takhrij":"صحيح: رواه مسلم (٣٥٧ :١٣١٩).","grade":"صحيح","chapter_ar":"باب ما جاء في ذبح النبيّ ﷺ بقرة عن نسائه في حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1319/357).","chapter_en":"What has been narrated regarding the Prophet ﷺ slaughtering a cow on behalf of his wives during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ slaughtered a cow on behalf of his wives during his pilgrimage."]},"buhuth":{"ar":["وقوله: (( عن نسائه )) يعني ذبح بقرةً عن كل واحدة من أزواجه ممن اعتمرن، كما سيأتي ذكره."],"en":["His saying, “on behalf of his wives,” means that he slaughtered a cow on behalf of each of his wives who had performed the lesser pilgrimage, as will be mentioned later."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":357}]},{"num":5330,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: ذبح رسول الله ﷺ عن عائشة بقرة يوم النحر."],"takhrij":"صحيح: رواه مسلم (١٣١٩).","grade":"صحيح","chapter_ar":"باب ما جاء في ذبح النبيّ ﷺ بقرة عن نسائه في حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1319).","chapter_en":"What has been narrated regarding the Prophet ﷺ slaughtering a cow on behalf of his wives during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ slaughtered a cow on behalf of Aishah on the Day of Sacrifice."]},"buhuth":{"ar":["وتخصيص عائشة بالذكر من باب ذكر بعض أفراد العموم للأهمية."],"en":["Mentioning Aishah specifically is an example of mentioning one individual from a general group for emphasis."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1319}]},{"num":5331,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خرجنا مع النبي ﷺ، ولا نرى إلا الحج، حتى إذا كنا بسَرِف أو قريبًا منها، حضتُ. فدخل عليَّ النبي ﷺ وأنا أبكي، فقال: (( أنفستِ؟ )) يعني الحيضة. قالت: قلت: نعم. قال: (( إنّ هذا شيء كتبه الله على بنات آدم، فاقضي ما يقضي الحاج، غير أن لا تطوفي بالبيت حتى تغتسلي )). قالت: وضحّى رسول الله ﷺ عن نسائه بالبقر."],"takhrij":"متفق عليه: رواه البخاريّ (٢٩٤)، ومسلم (١١٩ :١٢١١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في ذبح النبيّ ﷺ بقرة عن نسائه في حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (294) and Muslim (1211/119).","chapter_en":"What has been narrated regarding the Prophet ﷺ slaughtering a cow on behalf of his wives during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Aishah said: We went out with the Prophet ﷺ thinking of nothing but the pilgrimage. Then when we were at Sarif or near it, I began menstruating. The Prophet ﷺ came to me while I was crying and said: “Have you begun your monthly bleeding?” She said: I replied: Yes. He said: “This is something Allah has decreed for the daughters of Adam, so do what the pilgrim does, except do not circle the House until you wash.” She said: The Messenger of Allah ﷺ offered cattle on behalf of his wives."]},"buhuth":{"ar":["ورواه مسلم أيضًا (١٢٠) بسياق أطول، وفيه: (( فلما كان يوم النحر طهرت، فأمرني رسول الله ﷺ فأفضت )). قالت: فأُتينا بلحم بقر، فقلت: ما هذا؟ فقالوا: أهدى رسول الله ﷺ عن نسائه البقر… الحديث."],"en":["Muslim also narrated it (120) in a longer wording, in which it says: “When the Day of Sacrifice came, I became pure, so the Messenger of Allah ﷺ instructed me and I went forth.” She said: Then beef was brought to us, and I said: What is this? They said: The Messenger of Allah ﷺ offered cattle on behalf of his wives… and the rest of the hadith follows."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":294},{"key":"muslim","label":"مسلم","number":119}]},{"num":5332,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ، أن رسول الله ﷺ نحر عن آل محمد في حجّة الوداع بقرةً واحدة."],"takhrij":"صحيح: رواه أبو داود (١٧٥٠)، وابن ماجه (٣١٣٥).","grade":"صحيح","chapter_ar":"باب ما جاء في ذبح النبيّ ﷺ بقرة عن نسائه في حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1750) and Ibn Majah (3135).","chapter_en":"What has been narrated regarding the Prophet ﷺ slaughtering a cow on behalf of his wives during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Aishah, the wife of the Prophet ﷺ, narrated that the Messenger of Allah ﷺ slaughtered one cow on behalf of the family of Muhammad in the Farewell Pilgrimage."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1750},{"key":"ibnmajah","label":"ابن ماجه","number":3135}]},{"num":5333,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول الله ﷺ ذبح عمّن اعتمر من نسائه بقرةً بينهن."],"takhrij":"صحيح: رواه أبو داود (١٧٥١)، وابن ماجه (٣١٣٣)، وصححه ابن خزيمة (٢٩٠٣)، والحاكم (١٧١٧).","grade":"صحيح","chapter_ar":"باب ما جاء في ذبح النبيّ ﷺ بقرة عن نسائه في حجّة الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1751) and Ibn Majah (3133), and authenticated by Ibn Khuzaymah (2903) and al-Hakim (1717).","chapter_en":"What has been narrated regarding the Prophet ﷺ slaughtering a cow on behalf of his wives during the Farewell Pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ slaughtered one cow to be shared among those of his wives who had performed the lesser pilgrimage."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1751},{"key":"ibnmajah","label":"ابن ماجه","number":3133},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2903},{"key":"hakim","label":"الحاكم","number":1717}]},{"num":5334,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: نحرنا مع رسول الله ﷺ عام الحديبية البدنة عن سبعة، والبقرة عن سبعة."],"takhrij":"صحيح: رواه مالك (٩)، ومسلم (٣٥٠ :١٣١٨).","grade":"صحيح","chapter_ar":"باب الاشتراك في الهدي: سبعة في كل بدنة أو بقرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (9) and Muslim (1318/350).","chapter_en":"Sharing in the offering: seven people in each camel or cow","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn Abdullah said: In the year of al-Hudaybiyah, we slaughtered with the Messenger of Allah ﷺ one camel for seven people and one cow for seven people."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"muslim","label":"مسلم","number":350}]},{"num":5335,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: خرجنا مع رسول الله ﷺ مهلّين بالحج، فأمرنا رسول الله ﷺ أن نشترك في الإبل والبقر، كل سبعة منا في بدنة."],"takhrij":"صحيح: رواه مسلم (٣٥١ :١٣١٨).","grade":"صحيح","chapter_ar":"باب الاشتراك في الهدي: سبعة في كل بدنة أو بقرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1318/351).","chapter_en":"Sharing in the offering: seven people in each camel or cow","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn Abdullah said: We went out with the Messenger of Allah ﷺ entering the pilgrimage, and the Messenger of Allah ﷺ commanded us to share in camels and cows, with every seven of us sharing in one camel."]},"buhuth":{"ar":["وفي رواية: اشتركنا مع النبي ﷺ في الحج والعمرة، كل سبعة في بدنة. فقال رجل لجابر: أيشترك في الجزور؟ قال: ما هي إلا من البدن.","وفي رواية: كنا نتمتع مع رسول الله ﷺ بالعمرة، فنذبح البقرة عن سبعة نشترك فيها."],"en":["In another wording: We shared with the Prophet ﷺ in the pilgrimage and the lesser pilgrimage, every seven in one camel. A man said to Jabir: Can people share in a slaughtered camel? He said: It is nothing but one of the camels used for offering.","In another wording: We used to perform the combined pilgrimage with a break between rites with the Messenger of Allah ﷺ, and we would slaughter one cow shared by seven of us."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":351}]},{"num":5336,"demo":false,"sanad":"","matn":["عن حذيفة بن اليمان، أن رسول الله ﷺ أشرك بين المسلمين البقرة عن سبعة."],"takhrij":"حسن: رواه الإمام أحمد (٢٣٤٥٣، ٢٣٤٤٦).","grade":"حسن","chapter_ar":"باب الاشتراك في الهدي: سبعة في كل بدنة أو بقرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (23453, 23446).","chapter_en":"Sharing in the offering: seven people in each camel or cow","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Hudhayfah ibn al-Yaman narrated that the Messenger of Allah ﷺ allowed the Muslims to share one cow among seven people."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":23453},{"key":"ahmad","label":"مسند الإمام أحمد","number":23453,"n":23453}]},{"num":5337,"demo":false,"sanad":"","matn":["عن حفصة أم المؤمنين، أنها قالت لرسول الله ﷺ: ما شأن الناس حلّوا ولم تحلل أنت من عمرتك؟ فقال: (( إنّي لبّدت رأسي، وقلّدت هديي، فلا أحلّ حتى أنحر ))."],"takhrij":"متفق عليه: رواه مالك (١٨٠)، والبخاريّ (١٥٦٦)، ومسلم (١٧٦ :١٢٢٩).","grade":"متفق عليه","chapter_ar":"باب تقليد الهدي وإشعاره","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (180), al-Bukhari (1566), and Muslim (1229/176).","chapter_en":"Garland-marking the offering and marking it by incision","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Hafsah, the Mother of the Believers, said to the Messenger of Allah ﷺ: Why is it that the people have come out of the state of consecration while you have not come out of yours from your Umrah? He said: “I have matted my hair and garland-marked my offering, so I will not come out of the state of consecration until I slaughter.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":180},{"key":"bukhari","label":"البخاريّ","number":1566},{"key":"muslim","label":"مسلم","number":176}]},{"num":5338,"demo":false,"sanad":"","matn":["عن المسور بن مخرمة، ومروان بن الحكم، قالا: خرج النبي ﷺ من المدينة في بضع عشرة مائة من أصحابه، حتى إذا كانوا بذي الحليفة قلّد النبي ﷺ الهدي وأشعر، وأحرم بالعمرة."],"takhrij":"صحيح: رواه البخاريّ (١٦٩٥، ١٦٩٤).","grade":"صحيح","chapter_ar":"باب تقليد الهدي وإشعاره","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1695, 1694).","chapter_en":"Garland-marking the offering and marking it by incision","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Al-Miswar ibn Makhramah and Marwan ibn al-Hakam said: The Prophet ﷺ left Madinah with one thousand and several hundred of his Companions. When they reached Dhu al-Hulayfah, the Prophet ﷺ garland-marked the offering, marked it by incision, and entered the lesser pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1695}]},{"num":5339,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، قال: صلى رسول الله ﷺ الظهر بذي الحليفة، ثم دعا بناقته فأشعرها في صفحة سنامها الأيمن، وسلت الدم، وقلّدها نعلين، ثم ركب راحلته، فلما استوت به على البيداء أهلّ بالحج."],"takhrij":"صحيح: رواه مسلم (١٢٤٣).","grade":"صحيح","chapter_ar":"باب تقليد الهدي وإشعاره","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1243).","chapter_en":"Garland-marking the offering and marking it by incision","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Messenger of Allah ﷺ prayed the noon prayer at Dhu al-Hulayfah, then called for his she-camel and marked it by incision on the right side of its hump, wiped away the blood, and garlanded it with two sandals. Then he mounted his riding animal, and when it rose with him upon al-Bayda, he entered the pilgrimage."]},"buhuth":{"ar":["وقوله: (( فأشعرها )) الإشعار هو أن يجرحها في صفحة سنامها اليمنى بحديدة أو سكين ونحوه، ثم يسلت الدم عنها. وأصل الإشعار والشعور الإعلام والعلامة، وإشعار الهدي لكونه علامةً له، ليعلم أنه هدي، فإن ضلّ ردّه واجده، ولا يختلط بغيره."],"en":["His saying, “he marked it by incision,” means that he made a cut on the right side of its hump with iron, a knife, or the like, then wiped away the blood from it. The root meaning of this marking is notification and sign. Marking the sacrificial animal serves as a visible sign so that it is known to be an offering. If it is lost, the one who finds it returns it, and it does not get mixed with other animals."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1243}]},{"num":5340,"demo":false,"sanad":"","matn":["عن عائشة، قالت: أهدى النبيّ ﷺ مرةً غنمًا."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٠١، ١٦٩٥)، ومسلم (٣٦٧ : ١٣٢١)، واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تقليد الغنم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1701, 1695) and Muslim (1321/367). The wording is that of al-Bukhari.","chapter_en":"What has been narrated regarding garland-marking sheep","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Aishah said: The Prophet ﷺ once sent sheep as an offering."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1701},{"key":"muslim","label":"مسلم","number":367}]},{"num":5341,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ النبيّ ﷺ قسم غنمًا يوم النحر في أصحابه، وقال: (( اذبحوها لعمرتكم، فإنها تجزئ عنكم )). فأصاب سعد بن أبي وقاص تيسًا."],"takhrij":"صحيح: رواه أحمد (٢٨٠٢).","grade":"صحيح","chapter_ar":"باب ما جاء في تفرقة الهدي","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2802).","chapter_en":"What has been narrated regarding distributing the sacrificial offering","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Ibn Abbas narrated that the Prophet ﷺ distributed sheep among his Companions on the Day of Sacrifice and said: “Slaughter them for your Umrah, for they will suffice for you.” Sa‘d ibn Abi Waqqas received a male goat."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":2802,"n":2802}]},{"num":5342,"demo":false,"sanad":"","matn":["عن نافع، قال: أراد ابن عمر رضي الله عنهما الحجّ عام حجّة الحرورية في عهد ابن الزبير رضي الله عنهما، فقيل له: إنّ الناس كائنٌ بينهم قتال، ونخاف أن يصدّوك. فقال: ( لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ) [سورة الأحزاب: ٢١]، إذا أصنع كما صنع، أشهدكم أن أوجبتُ عمرةً. حتى إذا كان بظاهر البيداء قال: ما شأن الحجّ والعمرة إلا واحد، أشهدكم أنّي جمعتُ حجّةً مع عمرة. وأهدى هديًا مقلّدًا اشتراه، حتى قدم فطاف بالبيت وبالصفا، ولم يزد على ذلك، ولم يحلل من شيء حرم منه حتى يوم النحر، فحلق ونحر، ورأى أن قد قضى طوافه للحجّ والعمرة بطوافه الأول. ثم قال: كذلك صنع النبيّ ﷺ."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٠٨)، ومسلم (١٢٣٠).","grade":"متفق عليه","chapter_ar":"باب شراء الهدي في الطريق وتقليده","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1708) and Muslim (1230).","chapter_en":"Buying the offering on the way and garland-marking it","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Nafi said: Ibn Umar, may Allah be pleased with them both, intended to perform Hajj during the year of the conflict with the Kharijites in the time of Ibn al-Zubayr, and it was said to him: There is fighting among the people, and we fear they may prevent you. He said: “There has certainly been for you in the Messenger of Allah ﷺ an excellent example.” [al-Ahzab: 21] So I will do as he did. I bear witness before you that I have made the lesser pilgrimage binding upon myself. Then when he reached the outskirts of al-Bayda, he said: The matter of the greater pilgrimage and the lesser pilgrimage is one and the same. I bear witness before you that I have joined a pilgrimage with a lesser pilgrimage. He then dedicated a garland-marked offering that he had bought. When he arrived, he circled the House and went between al-Safa and al-Marwah, and did no more than that. He did not come out of the consecrated state from anything that had become forbidden to him until the Day of Sacrifice. Then he shaved and slaughtered, and considered that his first circuiting had sufficed for both his pilgrimage and his lesser pilgrimage. Then he said: Thus did the Prophet ﷺ do."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1708},{"key":"muslim","label":"مسلم","number":1230}]},{"num":5343,"demo":false,"sanad":"","matn":["عن عمرة بنت عبد الرحمن، أنّ زياد بن أبي سفيان كتب إلى عائشة زوج النبيّ ﷺ: إنّ عبد الله بن عباس قال: من أهدى هديًا حرم عليه ما يحرم على الحاج حتى ينحر الهدي، وقد بعثتُ بهديي، فاكتبي إليَّ بأمرك، أو مُري صاحب الهدي. قالت عمرة: فقالت عائشة: ليس كما قال ابن عباس! أنا فتلتُ قلائد هدي رسول الله ﷺ بيديّ، ثم قلّدها رسول الله ﷺ بيده، ثم بعث بها رسول الله ﷺ مع أبي، فلم يحرم على رسول الله ﷺ شيء أحلّه الله له حتى نُحر الهدي."],"takhrij":"متفق عليه: رواه مالك (٥١)، والبخاري (١٧٠٠)، ومسلم (٣٦٩ : ١٣٢١).","grade":"متفق عليه","chapter_ar":"باب تقليد الهدي لا يوجب إحرامًا لمن بعث بها إلى الحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (51), al-Bukhari (1700), and Muslim (1321/369).","chapter_en":"Garland-marking an offering does not place one into the consecrated state if one sends it to the Sacred Precinct","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Amrah bint Abd al-Rahman narrated that Ziyad ibn Abi Sufyan wrote to Aishah, the wife of the Prophet ﷺ: Abdullah ibn Abbas has said, “Whoever sends an offering becomes forbidden from what is forbidden to a pilgrim until the offering is slaughtered.” I have sent my offering, so write to me with your instruction, or instruct the one carrying the offering. Amrah said: Aishah replied: It is not as Ibn Abbas said. I myself twisted the garlands for the offering of the Messenger of Allah ﷺ with my own hands, then the Messenger of Allah ﷺ placed the garlands on them with his own hand, then sent them with my father, and nothing that Allah had made lawful became forbidden to the Messenger of Allah ﷺ until the offering was slaughtered."]},"buhuth":{"ar":["وفي رواية: أنّ عائشة قالت: كان رسول الله ﷺ يُهدي من المدينة، فأفتل قلائد هديه، ثم لا يجتنب شيئًا مما يجتنبه المحرم. البخاريّ (١٦٩٨)، ومسلم (٣٥٩ : ١٣٢١)."],"en":["In another narration, Aishah said: The Messenger of Allah ﷺ would send offerings from Madinah, and I would twist the garlands for his offering, then he would not avoid anything that a person in the consecrated state avoids. Narrated by al-Bukhari (1698) and Muslim (1321/359)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":51},{"key":"bukhari","label":"البخاري","number":1700},{"key":"muslim","label":"مسلم","number":369}]},{"num":5344,"demo":false,"sanad":"","matn":["عن أم المؤمنين عائشة، قالت: أنا فتلتُ تلك القلائد من عِهْنٍ كان عندنا، فأصبح بنا رسول الله ﷺ حلالًا، يأتي ما يأتي الحلال من أهله، أو يأتي ما يأتي الرجل من أهله."],"takhrij":"متفق عليه: رواه البخاري (١٧٠٥)، ومسلم (٣٦٤ : ١٣٢١)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تقليد الهدي لا يوجب إحرامًا لمن بعث بها إلى الحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1705) and Muslim (1321/364). The wording is that of Muslim.","chapter_en":"Garland-marking an offering does not place one into the consecrated state if one sends it to the Sacred Precinct","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["The Mother of the Believers, Aishah, said: I twisted those garlands from dyed wool that we had, and the Messenger of Allah ﷺ entered the morning among us in a lawful state, doing what a lawful husband does with his family."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1705},{"key":"muslim","label":"مسلم","number":364}]},{"num":5345,"demo":false,"sanad":"","matn":["عن عائشة، قالت: لقد رأيتني أفتل قلائد هدي رسول الله ﷺ من الغنم، فيبعث به، ثم يقيم فينا حلالًا."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٠٣)، ومسلم (٣٦٥ : ١٣٢١).","grade":"متفق عليه","chapter_ar":"باب تقليد الهدي لا يوجب إحرامًا لمن بعث بها إلى الحرم","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1703) and Muslim (1321/365).","chapter_en":"Garland-marking an offering does not place one into the consecrated state if one sends it to the Sacred Precinct","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Aishah said: I clearly remember myself twisting the garlands of the Messenger of Allah ﷺ’s sheep offering, then he would send it while he remained among us in a lawful state."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1703},{"key":"muslim","label":"مسلم","number":365}]},{"num":5346,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول الله ﷺ رأى رجلًا يسوق بدنة، فقال: (( اركبها )). فقال: يا رسول الله، إنّها بدنة. فقال: (( اركبها، ويلك )) في الثانية أو الثالثة."],"takhrij":"متفق عليه: رواه مالك (١٣٩)، والبخاريّ (١٦٨٩)، ومسلم (٣٧١ : ١٣٢٢).","grade":"متفق عليه","chapter_ar":"باب جواز ركوب البدنة المُهداة إذا لم يجد مركوبًا غيرها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (139), al-Bukhari (1689), and Muslim (1322/371).","chapter_en":"The permissibility of riding an offered camel if one finds no other mount","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ saw a man driving an offering camel and said: “Ride it.” The man said: O Messenger of Allah ﷺ, it is an offering camel. He said: “Ride it, woe to you,” on the second or third time."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":139},{"key":"bukhari","label":"البخاريّ","number":1689},{"key":"muslim","label":"مسلم","number":371}]},{"num":5347,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ نبيَّ الله ﷺ رأى رجلًا يسوق بدنة، قال: (( اركبها )). قال: إنّها بدنة. قال: (( اركبها )). قال: فلقد رأيته راكبها يساير النبيَّ ﷺ، والنعل في عنقها."],"takhrij":"متفق عليه: رواه البخاري (١٧٠٦)، ومسلم (١٣٢٢).","grade":"متفق عليه","chapter_ar":"باب جواز ركوب البدنة المُهداة إذا لم يجد مركوبًا غيرها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1706) and Muslim (1322).","chapter_en":"The permissibility of riding an offered camel if one finds no other mount","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet of Allah ﷺ saw a man driving an offering camel and said: “Ride it.” He said: It is an offering camel. He said: “Ride it.” Abu Hurayrah said: I indeed saw him riding it, going along beside the Prophet ﷺ, while the sandal garland was hanging from its neck."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1706},{"key":"muslim","label":"مسلم","number":1322}]},{"num":5348,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أنّ النبيَّ ﷺ رأى رجلًا يسوق بدنة، فقال: (( اركبها )). قال: إنها بدنة. قال: (( اركبها )). قال: إنها بدنة. قال: (( اركبها )) ثلاثًا."],"takhrij":"متفق عليه: رواه البخاريّ (١٦٩٠)، ومسلم (١٣٢٣).","grade":"متفق عليه","chapter_ar":"باب جواز ركوب البدنة المُهداة إذا لم يجد مركوبًا غيرها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1690) and Muslim (1323).","chapter_en":"The permissibility of riding an offered camel if one finds no other mount","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik narrated that the Prophet ﷺ saw a man driving an offering camel and said: “Ride it.” The man said: It is an offering camel. He said: “Ride it.” The man again said: It is an offering camel. He said: “Ride it,” three times."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1690},{"key":"muslim","label":"مسلم","number":1323}]},{"num":5349,"demo":false,"sanad":"","matn":["عن جابر، أنّه سئل عن ركوب الهدي، فقال: سمعتُ النبيَّ ﷺ يقول: (( اركبها بالمعروف إذا أُلجئتَ إليها حتى تجد ظهرًا ))."],"takhrij":"صحيح: رواه مسلم (١٣٢٤).","grade":"صحيح","chapter_ar":"باب جواز ركوب البدنة المُهداة إذا لم يجد مركوبًا غيرها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1324).","chapter_en":"The permissibility of riding an offered camel if one finds no other mount","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Jabir was asked about riding the sacrificial offering, and he said: I heard the Prophet ﷺ say: “Ride it in a proper manner when you are compelled to do so, until you find another mount.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1324}]},{"num":5350,"demo":false,"sanad":"","matn":["عن موسى بن سلمة الهذلي، قال: انطلقتُ أنا وسنان بن سلمة معتمرين. قال: وانطلق سنان معه ببدنة يسوقها، فأزحفت عليه بالطريق، فعيي بشأنها إن هي أبدعت كيف يأتي بها. فقال: لئن قدمت البلد لأستحفينّ عن ذلك. قال: فأضحيت. فلما نزلنا البطحاء قال: انطلق إلى ابن عباس نتحدث إليه. قال: فذكر له شأن بدنته، فقال: على الخبير سقطت. بعث رسول الله ﷺ بست عشرة بدنة مع رجل وأمّره فيها. قال: فمضى ثم رجع، فقال: يا رسول الله، كيف أصنع بما أبدع عليّ منها؟ قال: (( انحرها، ثم اصبغ نعليها في دمها، ثم اجعله على صفحتها، ولا تأكل منها أنت ولا أحد من أهل رفقتك ))."],"takhrij":"صحيح: رواه مسلم (١٣٢٥).","grade":"صحيح","chapter_ar":"باب الهدي إذا عطب في الطريق وخشي عليه الموت ماذا يفعل به؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1325).","chapter_en":"If the offering becomes disabled on the road and one fears it may die, what should be done with it?","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Musa ibn Salamah al-Hudhali said: Sinaan ibn Salamah and I set out for Umrah. Sinaan had with him an offering camel that he was driving. On the road it became exhausted, and he became distressed over what to do with it if it broke down completely. He said: When I reach the town, I will surely ask about that. When we reached al-Batha, he said: Go to Ibn Abbas so we may speak with him. He mentioned to him the matter of his camel, and Ibn Abbas said: You have come to one who knows well. The Messenger of Allah ﷺ sent sixteen camels with a man and put him in charge of them. The man went, then returned and said: O Messenger of Allah ﷺ, what should I do with one that becomes disabled for me? He said: “Slaughter it, then dip its sandal-garland in its blood, then mark its side with it, and neither you nor anyone from your traveling companions should eat from it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1325}]},{"num":5351,"demo":false,"sanad":"","matn":["عن ذؤيب أبي قبيصة الخزاعيّ، أنّ رسول الله ﷺ كان يبعث معه بالبدن، ثم يقول: (( إن عطب منها شيء، فخشيتَ عليه موتًا، فانحرها، ثم اغمس نعلها في دمها، ثم اضرب به صفحتها، ولا تطعمها أنت ولا أحدٌ من أهل رفقتك ))."],"takhrij":"صحيح: رواه مسلم (١٣٢٦).","grade":"صحيح","chapter_ar":"باب الهدي إذا عطب في الطريق وخشي عليه الموت ماذا يفعل به؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1326).","chapter_en":"If the offering becomes disabled on the road and one fears it may die, what should be done with it?","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Dhu’ayb Abu Qabisah al-Khuza‘i narrated that the Messenger of Allah ﷺ used to send sacrificial camels with him, then say: “If any of them becomes disabled, and you fear it may die, then slaughter it, dip its sandal-garland in its blood, then strike its side with it, and neither you nor any of your traveling companions should eat from it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1326}]},{"num":5352,"demo":false,"sanad":"","matn":["عن ناجية الأسلمي، أنّ رسول الله ﷺ بعث معه ببدن، قال: (( إن عطب منها شيء فانحره، ثم اصبغ نعله في دمه، ثم خلِّ بينه وبين الناس )).","وفي رواية: (( وخلِّ بين الناس وبينه فليأكلوه )).","وفي رواية: (( اغمس نعله في دمه، واضرب صفحته ))."],"takhrij":"صحيح: رواه أبو داود (١٧٦٢)، والترمذي (٩١٠) وصححه، وابن ماجه (٣١٠٦)، وأحمد (٨٩٤٢).","grade":"صحيح","chapter_ar":"باب الهدي إذا عطب في الطريق وخشي عليه الموت ماذا يفعل به؟","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1762), al-Tirmidhi (910), who authenticated it, Ibn Majah (3106), and Ahmad (8942).","chapter_en":"If the offering becomes disabled on the road and one fears it may die, what should be done with it?","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Najiyah al-Aslami narrated that the Messenger of Allah ﷺ sent sacrificial camels with him and said: “If any of them becomes disabled, then slaughter it, dye its sandal-garland in its blood, then leave it for the people.”","In another narration: “Leave it for the people so that they may eat it.”","In another narration: “Dip its sandal-garland in its blood and strike its side.”"]},"buhuth":{"ar":["وقال الخطابي: يُشبه أن يكون معناه حرم عليه ذلك وعلى أصحابه ليحسم عنهم باب النهمة.","وقوله: (( عطب )) أي قارب الهلاك. وقوله: (( نعله )) أي قلادته."],"en":["Al-Khattabi said: It appears that the meaning is that it was forbidden for him and his companions so as to block for them the door of greed.","His saying, “became disabled,” means: it came close to perishing. And his saying, “its sandal,” means: its garland."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1762},{"key":"tirmidhi","label":"الترمذي","number":910},{"key":"ibnmajah","label":"ابن ماجه","number":3106},{"key":"ahmad","label":"أحمد","number":8942}]},{"num":5353,"demo":false,"sanad":"","matn":["عن زياد بن جبير، أنّ ابن عمر أتى على رجل وهو ينحر بدنته باركة، فقال: ابعثها قيامًا مقيّدة، سنّة نبيّكم ﷺ."],"takhrij":"متفق عليه: رواه البخاريّ (١٧١٣)، ومسلم (١٣٢٠)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب نحر الإبل قيامًا غير معقولة، أو معقولة اليسرى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1713) and Muslim (1320). The wording is that of Muslim.","chapter_en":"Slaughtering camels while standing, unbound or with the left leg bound","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Ziyad ibn Jubayr narrated that Ibn Umar passed by a man while he was slaughtering his camel as it was kneeling, and he said: Make it stand while bound, for that is the practice of your Prophet ﷺ."]},"intro":{"ar":["قال الله تعالى:","( وَالْبُدْنَ جَعَلْنَاهَا لَكُم مِّن شَعَائِرِ اللَّهِ لَكُمْ فِيهَا خَيْرٌ ۖ فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا صَوَافَّ ) [الحج: ٣٦].","قال ابن عباس: ( صَوَافَّ ) قيامًا. علّقه البخاريّ ووصله ابن جرير في تفسيره (١٦/٥٥٦)، وزاد: (( على ثلاثة قوائم معقولة ))."],"en":["Allah Most High said:","“And the sacrificial camels We have made for you among the symbols of Allah; in them there is good for you. So mention the name of Allah over them while they stand in rows.” [al-Hajj: 36]","Ibn Abbas said regarding “while they stand in rows”: standing. Al-Bukhari cited it without full chain, and Ibn Jarir connected it in his commentary (16/556), adding: “on three legs, with one tied.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1713},{"key":"muslim","label":"مسلم","number":1320}]},{"num":5354,"demo":false,"sanad":"","matn":["عن أنس، قال: صلّى رسول الله ﷺ ونحن معه بالمدينة الظهر أربعًا، والعصر بذي الحليفة ركعتين، ثم بات بها حتى أصبح، ثم ركب حتى استوت به على البيداء… الحديث. وفيه: ونحر النبيّ ﷺ بدنات بيده قيامًا."],"takhrij":"صحيح: رواه البخاريّ (١٥٥١)، ومسلم (٦٩٠). وعند البخاريّ (١٧١٤): أنّ النبي ﷺ نحر سبع بدن قيامًا.","grade":"صحيح","chapter_ar":"باب نحر الإبل قيامًا غير معقولة، أو معقولة اليسرى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1551) and Muslim (690). In al-Bukhari (1714), it states that the Prophet ﷺ slaughtered seven camels standing.","chapter_en":"Slaughtering camels while standing, unbound or with the left leg bound","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ prayed the noon prayer with us in Madinah as four units, and the afternoon prayer at Dhu al-Hulayfah as two units, then spent the night there until morning, then mounted until he rose upon al-Bayda’… In it is: The Prophet ﷺ slaughtered camels with his own hand while they were standing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1551},{"key":"muslim","label":"مسلم","number":690},{"key":"وعند_البخاری","label":". وعند البخاريّ","number":1714}]},{"num":5355,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أنّ النبيّ ﷺ وأصحابه كانوا ينحرون البدنة معقولة اليسرى، قائمة على ما بقي من قوائمها."],"takhrij":"حسن: رواه أبو داود (١٧٦٧).","grade":"حسن","chapter_ar":"باب نحر الإبل قيامًا غير معقولة، أو معقولة اليسرى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1767).","chapter_en":"Slaughtering camels while standing, unbound or with the left leg bound","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Prophet ﷺ and his Companions used to slaughter the camel while its left leg was tied, standing upon its remaining legs."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1767}]},{"num":5356,"demo":false,"sanad":"","matn":["عن عبد الله بن قرط، عن النبيّ ﷺ قال: (( إن أعظم الأيام عند الله تبارك وتعالى يوم النحر، ثم يوم القرّ )). وهو اليوم الثاني.","قال: وقرّب لرسول الله ﷺ بدنات خمس أو ست، فطفقن يزدلفن إليه بأيّتهن يبدأ، فلما وجبت جنوبها قال: فتكلّم بكلمة خفية لم أفهمها. فقلت: ما قال؟ قال: (( من شاء اقتطع ))."],"takhrij":"صحيح: رواه أبو داود (١٧٦٥)، وأحمد (١٩٠٧٥)، وصححه ابن خزيمة (٢٨٦٦، ٢٩١٧).","grade":"صحيح","chapter_ar":"باب نحر الإبل قيامًا غير معقولة، أو معقولة اليسرى","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1765) and Ahmad (19075), and authenticated by Ibn Khuzaymah (2866, 2917).","chapter_en":"Slaughtering camels while standing, unbound or with the left leg bound","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Abdullah ibn Qurt narrated from the Prophet ﷺ that he said: “The greatest of days with Allah, Blessed and Exalted, is the Day of Sacrifice, then the Day of Remaining.” That is the second day. He said: Five or six camels were brought near to the Messenger of Allah ﷺ, and they began drawing close to him, each wanting him to begin with it. When their sides fell to the ground, he said a quiet phrase I did not understand. I asked: What did he say? He said: “Whoever wishes may take.”"]},"buhuth":{"ar":["وقوله: (( يزدلفن )) أي يقتربن.","وقوله: (( من شاء اقتطع )) فيه جواز هبة المشاع، وليس هو من النهب المنهي عنه."],"en":["His saying, “they drew close,” means: they came near.","His saying, “whoever wishes may take,” indicates the permissibility of gifting an undivided share, and this is not from the forbidden looting."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1765},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2866},{"key":"ahmad","label":"مسند الإمام أحمد","number":19075,"n":19075}]},{"num":5357,"demo":false,"sanad":"","matn":["عن جابر، قال: كنا نتزوّد لحوم الأضاحي على عهد النبيّ ﷺ إلى المدينة."],"takhrij":"متفق عليه: رواه البخاري (٢٩٨٠)، ومسلم (١٩٧٢/٣٢).","grade":"متفق عليه","chapter_ar":"باب استحباب الأكل من الهدي والتزوّد منه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2980) and Muslim (1972/32).","chapter_en":"The recommendation to eat from the offering and take provisions from it","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Jabir said: We used to take the meat of the sacrifices as provisions back to Madinah during the time of the Prophet ﷺ."]},"buhuth":{"ar":["ورواه البخاري (١٧١٩)، ومسلم (١٩٧٢/٣٠) عن جابر بن عبد الله، يقول: كنا لا نأكل من لحوم بدننا فوق ثلاث منى، فرخّص لنا النبيّ ﷺ فقال: (( كلوا وتزوّدوا ))."],"en":["Al-Bukhari (1719) and Muslim (1972/30) also narrated from Jabir ibn Abdullah that he said: We would not eat from the meat of our sacrificial camels for more than three days in Mina, then the Prophet ﷺ gave us permission and said: “Eat and take provisions.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2980},{"key":"muslim","label":"مسلم","number":1972}]},{"num":5358,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: ثم أمر — يعني النبيّ ﷺ — من كل بدنة ببضعة، فجُعلت في قدر، فطُبخت، فأكلا من لحمها، وشربا من مرقها."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب استحباب الأكل من الهدي والتزوّد منه","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The recommendation to eat from the offering and take provisions from it","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn Abdullah said: Then he — meaning the Prophet ﷺ — ordered that a piece be taken from every camel, and it was put into a cooking pot and cooked, and the two of them ate from its meat and drank from its broth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5359,"demo":false,"sanad":"","matn":["عن علي، قال: أهدى النبيّ ﷺ مائة بدنة، فأمرني بلحومها فقسمتها، ثم أمرني بجلالها فقسمتها، ثم بجلودها فقسمتها."],"takhrij":"متفق عليه: رواه البخاريّ (١٧١٨)، ومسلم (٣٤٩ : ١٣١٧)، واللفظ للبخاريّ. وزاد مسلم في رواية: (( في المساكين، ولا يُعطي في جزارتها منها شيئًا )).","grade":"متفق عليه","chapter_ar":"باب التصدق بلحوم الهدي وجلودها وجلالها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1718) and Muslim (1317/349). The wording is that of al-Bukhari. Muslim added in one narration: “among the poor, and that nothing from it should be given to the butcher as payment.”","chapter_en":"Giving the meat, hides, and coverings of the offering in charity","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Ali said: The Prophet ﷺ offered one hundred camels, then commanded me regarding their meat, so I distributed it. Then he commanded me regarding their coverings, so I distributed them. Then regarding their hides, so I distributed them."]},"buhuth":{"ar":["قوله: (( بجلالها )) الجلال جمع جُل، وهو ما يطرح على ظهر البعير من كساء ونحوه."],"en":["His saying, “their coverings,” refers to the cloths or wraps placed over the backs of the camels and the like."]},"intro":{"ar":["قال الله تعالى: ( لِيَشْهَدُوا مَنَافِعَ لَهُمْ وَيَذْكُرُوا اسْمَ اللَّهِ فِي أَيَّامٍ مَعْلُومَاتٍ عَلَىٰ مَا رَزَقَهُم مِّن بَهِيمَةِ الْأَنْعَامِ فَكُلُوا مِنْهَا وَأَطْعِمُوا الْبَائِسَ الْفَقِيرَ ) [الحج: ٢٨].","وقال تعالى: ( وَالْبُدْنَ جَعَلْنَاهَا لَكُم مِّن شَعَائِرِ اللَّهِ لَكُمْ فِيهَا خَيْرٌ فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا صَوَافَّ فَإِذَا وَجَبَتْ جُنُوبُهَا فَكُلُوا مِنْهَا وَأَطْعِمُوا الْقَانِعَ وَالْمُعْتَرَّ ) [الحج: ٣٦]."],"en":["Allah Most High said: “That they may witness benefits for themselves and mention the name of Allah during known days over what He has provided them of grazing livestock. So eat from them and feed the miserable poor.” [al-Hajj: 28]","And He said: “And the sacrificial camels We have made for you among the symbols of Allah; in them there is good for you. So mention the name of Allah over them while they stand in rows. Then when their sides fall, eat from them and feed the one who is content and the one who asks.” [al-Hajj: 36]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1718},{"key":"muslim","label":"مسلم","number":349}]},{"num":5360,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: كنا لا نأكل من لحوم بدننا فوق ثلاث منى، فرخّص لنا النبيّ ﷺ، فقال: (( كلوا وتزوّدوا )). فأكلنا وتزوّدنا. قلت لعطاء: أقال: حتى جئنا المدينة؟ قال: لا."],"takhrij":"متفق عليه: رواه البخاريّ (١٧١٩)، ومسلم (١٩٧٢). واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب التصدق بلحوم الهدي وجلودها وجلالها","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1719) and Muslim (1972). The wording is that of al-Bukhari.","chapter_en":"Giving the meat, hides, and coverings of the offering in charity","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Jabir ibn Abdullah said: We used not to eat from the meat of our sacrificial camels for more than three days in Mina, then the Prophet ﷺ permitted us and said: “Eat and take provisions.” So we ate and took provisions. I said to Ata’: Did he say: until we reached Madinah? He said: No."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1719},{"key":"muslim","label":"مسلم","number":1972}]},{"num":5361,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، قال: أمرني رسول الله ﷺ أن أقوم على بدنه، وأن أتصدق بلحمها وجلودها وأجلّتها، وأن لا أعطي الجزار منها. قال: نحن نعطيه من عندنا."],"takhrij":"متفق عليه: رواه البخاريّ (١٧١٦)، ومسلم (٣٤٨ : ١٣١٧)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب لا يُعطى الجزار من الهدي عوضًا عن أجرته","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1716) and Muslim (1317/348). The wording is that of Muslim.","chapter_en":"The butcher is not to be given anything from the offering as payment for his wage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["Ali ibn Abi Talib said: The Messenger of Allah ﷺ commanded me to supervise his camels, and to give their meat, hides, and coverings in charity, and not to give the butcher anything from them. He said: “We will pay him from our own wealth.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1716},{"key":"muslim","label":"مسلم","number":348}]},{"num":5362,"demo":false,"sanad":"","matn":["عن نافع، أن ابن عمر رضي الله عنهما كان يبعث بهديه من جمع من آخر الليل، حتى يُدخل به منحر النبيّ ﷺ مع حجّاج فيهم الحر والمملوك."],"takhrij":"صحيح: رواه البخاريّ (١٧١١).","grade":"صحيح","chapter_ar":"باب ما جاء أن منى كلها منحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1711).","chapter_en":"What has been narrated that all of Mina is a place for slaughter","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Nafi narrated that Ibn Umar, may Allah be pleased with them both, used to send his offering from Muzdalifah in the latter part of the night, until it would be brought into the place where the Prophet ﷺ slaughtered, along with pilgrims among whom were the free and the enslaved."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1711}]},{"num":5363,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أنّ رسول اللّٰه ﷺ قال: (( نحرتُ ههنا، ومِنى كلُّها منحر، فانحروا في رحالكم ))."],"takhrij":"صحيح: رواه مسلم (١٤٩ : ١٢١٨).","grade":"صحيح","chapter_ar":"باب ما جاء أن منى كلها منحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218/149).","chapter_en":"What has been narrated that all of Mina is a place for slaughter","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Jabir ibn Abd Allah narrated that the Messenger of Allah ﷺ said: “I slaughtered here, and all of Mina is a place of slaughter, so slaughter in your camps.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":149}]},{"num":5364,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، قال: ثم أتى — يعني النبيّ ﷺ — المنحر، فقال: (( هذا المنحر، ومِنى كلُّها منحر )). الحديث."],"takhrij":"حسن: رواه الترمذيّ (٨٨٥)، وأبو داود (١٩٣٥، ١٩٢٢)، وابن ماجه (٣٠١٠). قال الترمذي: (( حسن صحيح )).","grade":"حسن","chapter_ar":"باب ما جاء أن منى كلها منحر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (885), Abu Dawud (1935, 1922), and Ibn Majah (3010). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What has been narrated that all of Mina is a place for slaughter","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Ali ibn Abi Talib said: Then he — meaning the Prophet ﷺ — came to the place of slaughter and said: “This is the place of slaughter, and all of Mina is a place of slaughter.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذيّ","number":885},{"key":"abudawud","label":"أبو داود","number":1935},{"key":"ibnmajah","label":"ابن ماجه","number":3010}]},{"num":5365,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، قال: قال رسول اللّٰه ﷺ: (( كلُّ عرفة موقف، وكلُّ مِنًى منحر، وكلُّ المزدلفة موقف، وكلُّ فجاج مكة طريق ومنحر ))."],"takhrij":"حسن: رواه أبو داود (١٩٣٧)، وابن ماجه (٣٠٤٨)، وصححه ابن خزيمة (٢٧٨٧).","grade":"حسن","chapter_ar":"باب ما جاء أنّ فجاج مكة كلّها منحر وأيام التشريق كلّها ذبح","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1937), Ibn Majah (3048), and authenticated by Ibn Khuzaymah (2787).","chapter_en":"What has been narrated that all the mountain passes of Makkah are places of slaughter and all the Days of Tashriq are days for slaughter","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في الهدي وأحكامه","group_en":"Sections on what has been narrated regarding sacrificial offerings and their rulings","part_no":16,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ said: “All of Arafah is a place of standing, all of Mina is a place of slaughter, all of Muzdalifah is a place of standing, and all the mountain passes of Makkah are pathways and places of slaughter.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1937},{"key":"ibnmajah","label":"ابن ماجه","number":3048},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":2787}]},{"num":5366,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أنّه قال — حين خرج إلى مكة معتمرًا في الفتنة —: إنْ صُدِدْتُ عن البيت صنعنا كما صنعنا مع رسول الله ﷺ. فأهلَّ بعمرة من أجل أن رسول الله ﷺ أهلَّ بعمرة عام الحديبية. ثم إنّ عبد الله نظر في أمره فقال: ما أمرهما إلا واحد، ثم التفت إلى أصحابه فقال: ما أمرهما إلا واحد، أشهدكم أنّي قد أوجبتُ الحجَّ مع العمرة. ثم طاف لهما طوافًا واحدًا، ورأى ذلك مجزئًا عنه، وأهدى."],"takhrij":"متفق عليه: رواه مالك (٩٩)، والبخاري (١٨٠٦)، ومسلم (١٢٣٠).","grade":"متفق عليه","chapter_ar":"باب ما جاء في إيجاب العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (99), al-Bukhari (1806), and Muslim (1230).","chapter_en":"What has been narrated regarding the obligation of the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Umar said — when he set out to Makkah for Umrah during the time of unrest —: If I am prevented from the House, we will do as we did with the Messenger of Allah ﷺ. So he entered into the lesser pilgrimage because the Messenger of Allah ﷺ had entered into the lesser pilgrimage in the year of al-Hudaybiyah. Then Abdullah reflected on the matter and said: The ruling of the two is but one. Then he turned to his companions and said: The ruling of the two is but one. Bear witness that I have made the greater pilgrimage binding together with the lesser pilgrimage. Then he performed one circuiting for both and considered that sufficient for him, and he offered a sacrifice."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ) [سورة البقرة: ١٩٦].","وقال ابن عمر: ليس أحدٌ إلا عليه حجّة وعمرة.","وقال ابن عباس: إنّها لقرينتها في كتاب الله.","ذكرهما البخاريّ معلّقًا (٣/٥٩٧)."],"en":["Allah Most High said: “And complete the greater pilgrimage and the lesser pilgrimage for Allah.” [al-Baqarah: 196]","Ibn Umar said: There is no one except that a pilgrimage and a lesser pilgrimage are due from him.","Ibn Abbas said: It is joined to it in the Book of Allah.","Al-Bukhari cited both reports without full chains (3/597)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":99},{"key":"bukhari","label":"البخاري","number":1806},{"key":"muslim","label":"مسلم","number":1230}]},{"num":5367,"demo":false,"sanad":"","matn":["عن أبي رزين — رجل من بني عامر — أنه قال: يا رسول الله، إنّ أبي شيخ كبير لا يستطيع الحجّ ولا العمرة ولا الظعن؟ قال: (( حجَّ عن أبيك واعتمر ))."],"takhrij":"صحيح: رواه أبو داود (١٨١٠)، والترمذيّ (٩٣٠)، والنسائيّ (٢٦٢١)، وابن ماجه (٢٩٠٦).","grade":"صحيح","chapter_ar":"باب ما جاء في إيجاب العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1810), al-Tirmidhi (930), al-Nasa’i (2621), and Ibn Majah (2906).","chapter_en":"What has been narrated regarding the obligation of the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu Razin, a man from Banu Amir, said: O Messenger of Allah ﷺ, my father is a very old man and cannot perform the pilgrimage, the lesser pilgrimage, or travel. He said: “Perform the pilgrimage and the lesser pilgrimage on behalf of your father.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1810},{"key":"tirmidhi","label":"الترمذيّ","number":930},{"key":"nasai","label":"النسائيّ","number":2621},{"key":"ibnmajah","label":"ابن ماجه","number":2906}]},{"num":5368,"demo":false,"sanad":"","matn":["عن سمرة بن جندب، قال: قال رسول اللّٰه ﷺ: (( أقيموا الصلاة، وآتوا الزكاة، وحجّوا، واعتمروا، واستقيموا يُستقم بكم ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٧/٢٦١)، وفي الأوسط كما في مجمع البحرين (٤٢).","grade":"حسن","chapter_ar":"باب ما جاء في إيجاب العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (7/261), and in al-Awsat as quoted in Majma al-Bahrayn (42).","chapter_en":"What has been narrated regarding the obligation of the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “Establish the prayer, give the alms, perform the pilgrimage, perform the lesser pilgrimage, and be upright, and matters will be set right for you.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":7},{"key":"وفی_الاوسط_کما/مجمع_البحرین","label":"وفي الأوسط كما في مجمع البحرين","number":42}]},{"num":5369,"demo":false,"sanad":"","matn":["عن عائشة رضي الله عنها، قالت: يا رسول الله، هل على النساء جهاد؟ قال: (( نعم، عليهنّ جهاد لا قتال فيه: الحجّ والعمرة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٩٠١)، وابن خزيمة (٣٠٧٤).","grade":"صحيح","chapter_ar":"باب ما جاء في إيجاب العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2901) and Ibn Khuzaymah (3074).","chapter_en":"What has been narrated regarding the obligation of the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Aishah, may Allah be pleased with her, said: O Messenger of Allah ﷺ, is there jihad upon women? He said: “Yes, upon them is a jihad in which there is no fighting: the pilgrimage and the lesser pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2901},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":3074}]},{"num":5370,"demo":false,"sanad":"","matn":["عن أبي هريرة، أنّ رسول اللّٰه ﷺ قال: (( العمرة إلى العمرة كفارة لما بينهما، والحجّ المبرور ليس له جزاء إلا الجنّة ))."],"takhrij":"متفق عليه: رواه مالك في الحج (٦٥) عن سميّ مولى أبي بكر بن عبد الرحمن، عن أبي صالح السمان، عن أبي هريرة. ورواه البخاري في العمرة (١٧٧٣)، ومسلم في الحج (١٣٤٩)، كلاهما من طريق مالك.","grade":"متفق عليه","chapter_ar":"باب فضل العمرة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik in the chapter of Hajj (65) through Sumayy, the freedman of Abu Bakr ibn Abd al-Rahman, from Abu Salih al-Samman, from Abu Hurayrah. Also narrated by al-Bukhari in the chapter of Umrah (1773) and Muslim in the chapter of Hajj (1349), both through Malik.","chapter_en":"The virtue of the lesser pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “One lesser pilgrimage to the next is an expiation for what lies between them, and an accepted pilgrimage has no reward except Paradise.”"]}},"tuhfa":{},"refs":[{"key":"malik/الحج","label":"مالك في الحج","number":65},{"key":"عن_ابی_ہریرہ_ورواہ_البخاری/العمرہ","label":"عن أبي هريرة. ورواه البخاري في العمرة","number":1773},{"key":"muslim/الحج","label":"مسلم في الحج","number":1349}]},{"num":5371,"demo":false,"sanad":"","matn":["عن ابن عباس، أنّ النبيّ ﷺ قال لامرأة من الأنصار يقال لها: أم سنان: (( ما منعك أن تكوني حججتِ معنا؟ )). قالت: ناضحان كانا لأبي فلان — زوجها — حجّ هو وابنه على أحدهما، وكان الآخر يسقي غلامنا. قال: (( فعمرة في رمضان تقضي حجّةً أو حجّةً معي ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٨٦٣)، ومسلم (٢٢٢ : ١٢٥٦)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب فضل العمرة في رمضان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1863) and Muslim (1256/222). The wording is that of Muslim.","chapter_en":"The virtue of the lesser pilgrimage in Ramadan","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Ibn Abbas narrated that the Prophet ﷺ said to a woman from the Ansar called Umm Sinan: “What prevented you from making pilgrimage with us?” She said: Two water-carrying camels belonged to Abu so-and-so — meaning her husband. He and his son performed the pilgrimage on one of them, and the other was used to carry water for our servant. He said: “Then a lesser pilgrimage in Ramadan equals a pilgrimage, or a pilgrimage with me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1863},{"key":"muslim","label":"مسلم","number":222}]},{"num":5372,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: أراد رسول اللّٰه ﷺ الحجّ، فقالت امرأة لزوجها: أحججني مع رسول الله ﷺ على جملك. فقال: ما عندي ما أحجّك عليه. قالت: أحججني على جملك فلان. قال: ذاك حبيس في سبيل الله عز وجل. فأتى رسول الله ﷺ فقال: إنّ امرأتي تقرأ عليك السلام ورحمة الله، وإنها سألتني الحجّ معك، قالت: أحججني مع رسول الله ﷺ. فقلت: ما عندي ما أحجّك عليه. فقالت: أحججني على جملك فلان. فقلت: ذاك حبيس في سبيل الله. فقال رسول الله ﷺ: (( أمّا إنّك لو أحججتها عليه كان في سبيل الله )). قال: وإنها أمرتني أن أسألك ما يعدل حجّةً معك؟ فقال رسول الله ﷺ: (( أقرئها السلام ورحمة الله وبركاته، وأخبرها أنّ عمرةً في رمضان تعدل حجّةً معي ))."],"takhrij":"حسن: رواه أبو داود (١٩٩٠)، وصححه ابن خزيمة (٣٠٧٧).","grade":"حسن","chapter_ar":"باب فضل العمرة في رمضان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1990), and authenticated by Ibn Khuzaymah (3077).","chapter_en":"The virtue of the lesser pilgrimage in Ramadan","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ intended to perform the pilgrimage, and a woman said to her husband: Let me perform pilgrimage with the Messenger of Allah ﷺ on your camel. He said: I have nothing on which I can send you for pilgrimage. She said: Let me go on your camel named so-and-so. He said: That one has been set aside in the path of Allah, the Mighty and Majestic. Then the husband came to the Messenger of Allah ﷺ and said: My wife conveys to you peace and the mercy of Allah. She asked me to let her perform pilgrimage with you, saying: Let me perform pilgrimage with the Messenger of Allah ﷺ. I said: I have nothing on which I can send you for pilgrimage. She said: Let me go on your camel named so-and-so. I said: That one has been set aside in the path of Allah. The Messenger of Allah ﷺ said: “If you had sent her for pilgrimage on it, that would have been in the path of Allah.” He said: She also instructed me to ask you what equals a pilgrimage with you. The Messenger of Allah ﷺ said: “Convey to her peace and the mercy of Allah and His blessings, and inform her that an Umrah in Ramadan equals a pilgrimage with me.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1990},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":3077}]},{"num":5373,"demo":false,"sanad":"","matn":["عن أم معقل الأسدية، أنّها قالت: يا رسول الله، إني أريد الحج، فعجزت، فما تأمرني؟ قال: (( اعتمري في رمضان، فإنّ عمرةً في رمضان تعدل حجّة ))."],"takhrij":"صحيح: رواه أحمد (٢٧٢٨٥)، وأبو داود (١٩٨٨)، والترمذي (٩٣٩)، وابن ماجه (٢٩٩٣).","grade":"صحيح","chapter_ar":"باب فضل العمرة في رمضان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (27285), Abu Dawud (1988), al-Tirmidhi (939), and Ibn Majah (2993).","chapter_en":"The virtue of the lesser pilgrimage in Ramadan","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Umm Ma‘qil al-Asadiyyah said: O Messenger of Allah ﷺ, I want to perform the pilgrimage, but I was unable. What do you command me? He said: “Perform a lesser pilgrimage in Ramadan, for a lesser pilgrimage in Ramadan equals a pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1988},{"key":"tirmidhi","label":"الترمذي","number":939},{"key":"ibnmajah","label":"ابن ماجه","number":2993},{"key":"ahmad","label":"مسند الإمام أحمد","number":27285,"n":27285}]},{"num":5374,"demo":false,"sanad":"","matn":["عن أبي طليق، أنّ امرأته أم طليق أتته فقالت له: حضر الحج يا أبا طليق، وكان له جمل وناقة، يحج على الناقة، ويغزو على الجمل، فسألته أن يعطيها الجمل تحجّ عليه. قال: ألم تعلمي أنّي حبسته في سبيل الله؟ قالت: إنّ الحجّ من سبل الله، فأعطنيه يرحمك الله. قال: ما أريد أن أعطيك. قالت: فأعطني ناقتك، وحجّ أنت على الجمل. قال: لا أوثرك بها على نفسي. قالت: فأعطني من نفقتك. قال: ما عندي فضل عني وعن عيالي ما أخرج به، وما أُنزل لكم. قالت: إنك لو أعطيتني أخلفكها الله. قال: فلما أبيتُ عليها قالت: فإذا أتيتَ رسول الله ﷺ فأقرئه مني السلام، وأخبره بالذي قلتُ لك. قال: فأتيتُ رسول الله ﷺ فأقرأتُه منها السلام، وأخبرتُه بالذي قالت أم طليق. قال: (( صدقت أم طليق، لو أعطيتها الجمل كان في سبيل الله، ولو أعطيتها ناقتك كانت وكنتَ في سبيل الله، ولو أعطيتها من نفقتك أخلفها الله )). قال: وإنها تسألك يا رسول الله ما يعدل الحج؟ قال: (( عمرة في رمضان ))."],"takhrij":"حسن: رواه الدولابي في الكنى (١/٤١) — والسياق له —، والبزار مختصرًا في كشف الأستار (١١٥١)، وأبو يعلى في مسنده كما في المطالب العالية (١١٤٨)، والطبراني في الكبير (٢٢/٣٢٤).","grade":"حسن","chapter_ar":"باب فضل العمرة في رمضان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Dawlabi in al-Kuna (1/41) — this is his wording —, al-Bazzar in Kashf al-Astar (1151), Abu Ya‘la in his Musnad as cited in al-Matalib al-‘Aliyah (1148), and al-Tabarani in al-Kabir (22/324).","chapter_en":"The virtue of the lesser pilgrimage in Ramadan","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abu Taliq narrated that his wife Umm Taliq came to him and said: The season of pilgrimage has arrived, Abu Taliq. He had a camel and a she-camel, using the she-camel for pilgrimage and the camel for military expeditions. She asked him to give her the camel so she could perform pilgrimage on it. He said: Do you not know that I have devoted it to the path of Allah? She said: Pilgrimage is among the paths of Allah, so give it to me, may Allah have mercy on you. He refused. She said: Then give me your she-camel, and you perform pilgrimage on the camel. He said: I do not prefer you over myself with it. She said: Then give me from your provisions. He said: I have no extra beyond what I need for myself and my family. She said: If you gave me, Allah would replace it for you. When he persisted in refusing, she said: When you come to the Messenger of Allah ﷺ, convey my peace to him and tell him what I said to you. He said: So I came to the Messenger of Allah ﷺ, conveyed her peace to him, and informed him of what Umm Taliq had said. He said: “Umm Taliq has spoken the truth. If you had given her the camel, it would have been in the path of Allah. If you had given her your she-camel, it and you would have been in the path of Allah. If you had given her from your provisions, Allah would have replaced it for you.” He said: She also asks you, O Messenger of Allah ﷺ, what equals a pilgrimage? He said: “A lesser pilgrimage in Ramadan.”"]}},"tuhfa":{},"refs":[{"key":"الدولابی/الکنی","label":"الدولابي في الكنى","number":1},{"key":"البزار_مختصرا/کشف_الاستار","label":"البزار مختصرًا في كشف الأستار","number":1151},{"key":"ابو_یعلی/مسندہ_کما_فی_المطالب_العالیہ","label":"أبو يعلى في مسنده كما في المطالب العالية","number":1148},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":22}]},{"num":5375,"demo":false,"sanad":"","matn":["عن جابر، أنّ النبيّ ﷺ قال: (( عمرة في رمضان تعدل حجّة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٩٩٥)، وأحمد (١٤٨٨٢، ١٤٧٩٥).","grade":"صحيح","chapter_ar":"باب فضل العمرة في رمضان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2995) and Ahmad (14882, 14795).","chapter_en":"The virtue of the lesser pilgrimage in Ramadan","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Jabir narrated that the Prophet ﷺ said: “A lesser pilgrimage in Ramadan equals a pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2995},{"key":"ahmad","label":"مسند الإمام أحمد","number":14882,"n":14882}]},{"num":5376,"demo":false,"sanad":"","matn":["عن وهب بن خنبش، قال: قال رسول اللّٰه ﷺ: (( عمرة في رمضان تعدل حجّة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٩٩١)، وأحمد (١٧٦٦١).","grade":"صحيح","chapter_ar":"باب فضل العمرة في رمضان","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2991) and Ahmad (17661).","chapter_en":"The virtue of the lesser pilgrimage in Ramadan","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Wahb ibn Khanbash said: The Messenger of Allah ﷺ said: “A lesser pilgrimage in Ramadan equals a pilgrimage.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2991},{"key":"ahmad","label":"مسند الإمام أحمد","number":17661,"n":17661}]},{"num":5377,"demo":false,"sanad":"","matn":["عن عكرمة بن خالد، أنه سأل ابن عمر رضي الله عنهما عن العمرة قبل الحجّ؟ فقال: لا بأس. قال عكرمة: قال ابن عمر: اعتمر النبيّ ﷺ قبل أن يحجّ."],"takhrij":"صحيح: رواه البخاريّ (١٧٧٤).","grade":"صحيح","chapter_ar":"باب جواز الاعتمار قبل الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1774).","chapter_en":"The permissibility of performing the lesser pilgrimage before the greater pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Ikrimah ibn Khalid asked Ibn Umar, may Allah be pleased with them both, about performing the lesser pilgrimage before the greater pilgrimage. He said: There is no harm in it. Ikrimah said: Ibn Umar said: The Prophet ﷺ performed the lesser pilgrimage before he performed the greater pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1774}]},{"num":5378,"demo":false,"sanad":"","matn":["عن ابن عباس قال:","كانوا يرون أن العمرة في أشهر الحج من أفجر الفجور في الأرض، ويجعلون المحرم صفرًا، ويقولون:","إذا برأ الدَّبر، وعفا الأثر، وانسلخ صفر، حلت العمرة لمن اعتمر.","قدم النبي ﷺ وأصحابه صبيحة رابعةٍ مهلِّين بالحج، فأمرهم أن يجعلوها عمرة، فتعاظم ذلك عندهم، فقالوا:","يا رسول الله، أيُّ الحل؟","قال:","«حِلٌّ كُلُّهُ»."],"takhrij":"متفق عليه: رواه البخاري (١٥٦٤)، ومسلم (١٢٤٠/١٩٨).","grade":"متفق عليه","chapter_ar":"باب العمرة في أشهر الحجّ","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1564) and Muslim (1240/198).","chapter_en":"The lesser pilgrimage during the months of the greater pilgrimage","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās reported:","They used to regard performing ʿUmrah during the months of Ḥajj as one of the gravest acts of wickedness on earth. They would treat Muḥarram as Ṣafar and would say:","“When the wounds on the backs of the camels have healed, the tracks have disappeared, and Ṣafar has passed, then ʿUmrah becomes lawful for whoever wishes to perform it.”","The Prophet ﷺ and his Companions arrived on the morning of the fourth day while having entered iḥrām for Ḥajj. He instructed them to turn it into an ʿUmrah.","That seemed very serious to them, so they asked:","“O Messenger of Allah ﷺ, what kind of release from iḥrām?”","He replied:","“A complete release.”"]},"buhuth":{"ar":["وفي رواية عند مسلم (١٩٩):","«فَقَدِمَ لِأَرْبَعٍ مَضَيْنَ مِنْ ذِي الْحِجَّةِ».","وقوله: «برأ الدبر» أي: ما كان يحصل بظهور الإبل من الحمل عليها ومشقة السفر، فإنه كان يبرأ بعد انصرافهم من الحج.","وقوله: «عفا الأثر» أي: درس، والمراد أثر الإبل وغيرها في سيرها."],"en":["In another narration of Muslim (199):","“He arrived after four days of Dhū al-Ḥijjah had passed.”","The expression “when the wounds have healed” refers to the injuries caused on the backs of camels by carrying loads and enduring the hardship of travel; these would heal after the pilgrims returned from Ḥajj.","“And the tracks have disappeared” means that the tracks left by the camels and other travelers had faded away."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1564},{"key":"muslim","label":"مسلم","number":1240}]},{"num":5379,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أنّ رسول الله ﷺ اعتمر أربع عمر، كلّهنّ في ذي القعدة إلا التي مع حجّته: عمرة من الحديبية — أو زمن الحديبية — في ذي القعدة، وعمرة من العام المقبل في ذي القعدة، وعمرة من الجعرانة حيث قسم غنائم حنين في ذي القعدة، وعمرة مع حجّته."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٧٨)، ومسلم (١٢٥٣). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1778) and Muslim (1253). The wording is that of Muslim.","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Malik narrated that the Messenger of Allah ﷺ performed four lesser pilgrimages, all of them in Dhu al-Qi‘dah except the one joined with his pilgrimage: the lesser pilgrimage of al-Hudaybiyah — or during the time of al-Hudaybiyah — in Dhu al-Qi‘dah, the lesser pilgrimage of the following year in Dhu al-Qi‘dah, the lesser pilgrimage from al-Ji‘ranah when he distributed the spoils of Hunayn in Dhu al-Qi‘dah, and the lesser pilgrimage joined with his pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1778},{"key":"muslim","label":"مسلم","number":1253}]},{"num":5380,"demo":false,"sanad":"","matn":["عن مجاهد، قال: دخلت أنا وعروة بن الزبير المسجد، فإذا عبد الله بن عمر جالس إلى حجرة عائشة، والناس يصلّون الضحى في المسجد. فسألناه عن صلاتهم؟ فقال: بدعة. فقال له عروة: يا أبا عبد الرحمن، كم اعتمر رسول الله ﷺ؟ فقال: أربع عمر، إحداهنّ في رجب. فكرهنا أن نكذّبه ونردّ عليه، وسمعنا استنان عائشة في الحجرة. فقال عروة: ألا تسمعين يا أم المؤمنين إلى ما يقول أبو عبد الرحمن؟ فقالت: وما يقول؟ قال: يقول: اعتمر النبيّ ﷺ أربع عمر، إحداهنّ في رجب. فقالت: يرحم الله أبا عبد الرحمن، ما اعتمر رسول الله ﷺ إلا وهو معه، وما اعتمر في رجب قط."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٧٦، ١٧٧٥)، ومسلم (٢٢ : ١٢٥٥).","grade":"متفق عليه","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1776, 1775) and Muslim (1255/22).","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Mujahid said: I entered the mosque with Urwah ibn al-Zubayr and found Abdullah ibn Umar sitting beside Aishah’s room while the people were praying the forenoon prayer in the mosque. We asked him about their prayer and he said: It is an innovation. Then Urwah said to him: Abu Abd al-Rahman, how many lesser pilgrimages did the Messenger of Allah ﷺ perform? He said: Four, one of them in Rajab. We disliked to reject him directly. Then we heard Aishah brushing her teeth in the room. Urwah said: Mother of the Believers, do you not hear what Abu Abd al-Rahman is saying? She said: What is he saying? He said: He says the Prophet ﷺ performed four lesser pilgrimages, one of them in Rajab. She said: May Allah have mercy on Abu Abd al-Rahman. The Messenger of Allah ﷺ never performed a lesser pilgrimage except that he was with him, and he never performed a lesser pilgrimage in Rajab at all."]},"buhuth":{"ar":["وزاد مسلم: (( وابن عمر يسمع، فما قال: لا، ولا نعم، وسكت )).","وأما قول ابن عمر: (( إحداهن في رجب )) فهو وهم منه رضي الله عنه، ولذا لما استدركته عائشة سكت."],"en":["Muslim added: “Ibn Umar was listening, and he said neither yes nor no, and remained silent.”","As for Ibn Umar’s statement, “one of them was in Rajab,” that was a mistaken recollection from him, may Allah be pleased with him. That is why he remained silent when Aishah corrected him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1776},{"key":"muslim","label":"مسلم","number":22}]},{"num":5381,"demo":false,"sanad":"","matn":["عن البراء بن عازب، قال: اعتمر رسول الله ﷺ في ذي القعدة قبل أن يحجّ مرّتين."],"takhrij":"صحيح: رواه البخاريّ (١٧٨١).","grade":"صحيح","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1781).","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Al-Bara’ ibn Azib said: The Messenger of Allah ﷺ performed the lesser pilgrimage in Dhu al-Qi‘dah twice before he performed the greater pilgrimage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1781}]},{"num":5382,"demo":false,"sanad":"","matn":["عن البراء بن عازب، قال: اعتمر رسول الله ﷺ قبل أن يحجّ، واعتمر قبل أن يحجّ. فقالت عائشة: لقد علم أنّه اعتمر أربع عمر بعمرته التي حجّ فيها."],"takhrij":"صحيح: رواه أحمد (١٨٦٢٩).","grade":"صحيح","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (18629).","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Al-Bara’ ibn Azib said: The Messenger of Allah ﷺ performed the lesser pilgrimage before he performed the greater pilgrimage, and he performed the lesser pilgrimage before he performed the greater pilgrimage. Aishah said: He certainly knew that the Prophet ﷺ performed four lesser pilgrimages, including the one joined with his pilgrimage."]},"buhuth":{"ar":["وقوله: (( مرتين )) أراد بهما العمرة المفردة المستقلة، وهما اثنتان حقًّا: عمرة القضاء، وعمرته من الجعرانة."],"en":["His saying, “twice,” refers to the two separate independent lesser pilgrimages, and they were indeed two: the lesser pilgrimage of making up the missed pilgrimage and the lesser pilgrimage from al-Ji‘ranah."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":18629,"n":18629}]},{"num":5383,"demo":false,"sanad":"","matn":["عن ابن عباس، قال: اعتمر رسول الله ﷺ أربع عمر: عمرة الحديبية، والثانية حيث تواطؤوا على عمرة من قابل، والثالثة من الجعرانة، والرابعة التي قرن مع حجّته."],"takhrij":"صحيح: رواه أبو داود (١٩٩٣)، والترمذيّ (٨١٦) وحسنه، وابن ماجه (٣٠٠٣)، وأحمد (٢٢١١).","grade":"صحيح","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1993), al-Tirmidhi (816), who graded it Hasan, Ibn Majah (3003), and Ahmad (2211).","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ performed four lesser pilgrimages: the lesser pilgrimage of al-Hudaybiyah, the second when they agreed to make it up the following year, the third from al-Ji‘ranah, and the fourth which he joined with his pilgrimage."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1993},{"key":"tirmidhi","label":"الترمذيّ","number":816},{"key":"ibnmajah","label":"ابن ماجه","number":3003},{"key":"ahmad","label":"مسند الإمام أحمد","number":2211,"n":2211}]},{"num":5384,"demo":false,"sanad":"","matn":["عن جابر، أنّ النبيّ ﷺ اعتمر ثلاث عمر، كلّها في ذي القعدة: إحداهنّ زمن الحديبية، والأخرى في صلح قريش، والأخرى مرجعه من الطائف من الجعرانة."],"takhrij":"حسن: رواه البزار في كشف الأستار (١١٤٩)، والطبراني في الأوسط — مجمع البحرين (١٧٩٠).","grade":"حسن","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1149), and al-Tabarani in al-Awsat — Majma al-Bahrayn (1790).","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Jabir narrated that the Prophet ﷺ performed three lesser pilgrimages, all of them in Dhu al-Qi‘dah: one during the time of al-Hudaybiyah, another during the truce with Quraysh, and the third on his return from al-Ta’if from al-Ji‘ranah."]}},"tuhfa":{},"refs":[{"key":"البزار/کشف_الاستار","label":"البزار في كشف الأستار","number":1149},{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط — مجمع البحرين","number":1790},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1149,"n":1149}]},{"num":5385,"demo":false,"sanad":"","matn":["عن عائشة، قالت: لم يعتمر رسول الله ﷺ عمرة إلا في ذي القعدة."],"takhrij":"صحيح: رواه ابن ماجه (٢٩٩٧).","grade":"صحيح","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2997).","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ never performed a lesser pilgrimage except in Dhu al-Qi‘dah."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2997}]},{"num":5386,"demo":false,"sanad":"","matn":["عن عائشة:","أن رسول الله ﷺ اعتمر عمرتين:","عمرةً في ذي القعدة، وعمرةً في شوال."],"takhrij":"صحيح: رواه أبو داود (١٩٩١).","grade":"صحيح","chapter_ar":"باب بيان عدد عمرات النبي ﷺ وزمانها وأنها كانت كلها في أشهر الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1991).","chapter_en":"The number and timing of the Prophet’s ﷺ ʿUmrahs, and that all of them were during the months of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah reported:","The Messenger of Allah ﷺ performed two independent ʿUmrahs:","one ʿUmrah in Dhū al-Qiʿdah and one ʿUmrah in Shawwāl."]},"buhuth":{"ar":["إلا أن قولها: «شوال» لا بد من تأويله، أي: في آخر شوال وأوائل ذي القعدة، كأنها تقصد أنه أحرم في آخر شوال، وكانت عمرته في ذي القعدة، كما قال أنس وغيره؛ لأن الثابت في الأحاديث الصحيحة أن النبي ﷺ اعتمر في ذي القعدة.","وقولها: «عمرتين» تعني مستقلتين.","وروى البيهقي (٤/٣٤٦) عن عائشة أنها قالت:","«اعْتَمَرَ رَسُولُ اللَّهِ ﷺ ثَلَاثَ عُمَرٍ: عُمْرَةً فِي شَوَّالٍ، وَعُمْرَتَيْنِ فِي ذِي الْقَعْدَةِ».","وتقصد بذلك غير عمرته التي كانت في الحج."],"en":["Her statement “in Shawwāl” must be interpreted as referring to the end of Shawwāl and the beginning of Dhū al-Qiʿdah. It is as though she meant that he entered iḥrām at the end of Shawwāl, while the actual ʿUmrah occurred in Dhū al-Qiʿdah, as Anas and others reported, because the authentic narrations establish that the Prophet ﷺ performed ʿUmrah in Dhū al-Qiʿdah.","Her statement “two ʿUmrahs” means two independent ʿUmrahs.","Al-Bayhaqī (4/346) also narrated from ʿĀʾishah that she said:","“The Messenger of Allah ﷺ performed three ʿUmrahs: one ʿUmrah in Shawwāl and two ʿUmrahs in Dhū al-Qiʿdah.”","She meant apart from the ʿUmrah that was part of his Ḥajj."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1991}]},{"num":5387,"demo":false,"sanad":"","matn":["عن يعلى بن أمية، أنه كان يقول لعمر بن الخطاب رضي الله عنه: ليتني أرى نبيَّ الله ﷺ حين ينزل عليه. فلما كان النبي ﷺ بالجعرانة، وعلى النبي ﷺ ثوب قد أظلّ به عليه، ومعه ناس من أصحابه فيهم عمر، إذ جاءه رجل عليه جبة صوف متضمخ بطيب، فقال: يا رسول الله، كيف ترى في رجل أحرم بعمرة في جبة بعدما تضمخ بطيب؟ فنظر النبي ﷺ ساعة، ثم سكت، فجاءه الوحي، فأشار عمر بيده إلى يعلى بن أمية: تعال. فجاء يعلى، فأدخل رأسه، فإذا النبي ﷺ محمر الوجه، يغطّ ساعة، ثم سُرِّي عنه، فقال: (( أين الذي سألني عن العمرة آنفًا؟ )) فالتمس الرجل، فجيء به، فقال النبي ﷺ: (( أما الطيب الذي بك فاغسله ثلاث مرات، وأما الجبة فانزعها، ثم اصنع في عمرتك ما تصنع في حجك ))."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٣٦)، ومسلم (١١٨٠/٨).","grade":"متفق عليه","chapter_ar":"باب محظورات العمرة كمحظورات الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1536) and Muslim (1180/8).","chapter_en":"The prohibitions of ʿUmrah are the same as the prohibitions of Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Ya‘la ibn Umayyah said that he used to say to Umar ibn al-Khattab, may Allah be pleased with him: I wish I could see the Prophet of Allah ﷺ when revelation comes down to him. When the Prophet ﷺ was at al-Ji‘ranah, and a cloth was shading him, with a group of his Companions including Umar, a man came wearing a wool cloak and heavily perfumed, and said: O Messenger of Allah ﷺ, what do you say regarding a man who entered into ihram for Umrah while wearing a cloak after applying perfume? The Prophet ﷺ looked for a while, then remained silent. Then revelation came to him. Umar signaled with his hand to Ya‘la ibn Umayyah: Come. So Ya‘la came and put his head in, and the Prophet ﷺ was red in the face and breathing heavily for a while. Then it was lifted from him and he said: “Where is the one who asked me about Umrah just now?” The man was sought and brought, and the Prophet ﷺ said: “As for the perfume on you, wash it off three times. As for the cloak, remove it. Then do in your Umrah what you do in your Hajj.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1536},{"key":"muslim","label":"مسلم","number":1180}]},{"num":5388,"demo":false,"sanad":"","matn":["عن عائشة، أنها قالت: يا رسول الله، يصدر الناس بنسكين، وأصدر بنسك؟ فقال لها: (( انتظري، فإذا طهرتِ فاخرجي إلى التنعيم فأهلي، ثم ائتينا بمكان كذا، ولكنها على قدر نفقتك أو نصبك ))."],"takhrij":"متفق عليه: رواه البخاري (١٧٨٧)، ومسلم (١٢٦ : ١٢١١).","grade":"متفق عليه","chapter_ar":"باب أجر الحج والعمرة على قدر التعب والنفقة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1787) and Muslim (1211/126).","chapter_en":"The reward of the greater and lesser pilgrimage is according to the amount of hardship and spending","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Aishah said: O Messenger of Allah ﷺ, the people are leaving with two rites, while I am leaving with only one? He said to her: “Wait. When you become pure, then go out to al-Tan‘im and enter into ihram, then come meet us at such-and-such a place. But its reward is according to your spending or your hardship.”"]},"buhuth":{"ar":["قوله: (( على قدر نفقتك أو نصبك )) قال النووي: (( هذا ظاهر في أنّ الثواب والفضل في العبادة يكثر بكثرة النصب والنفقة، والمراد النصب الذي لا يذمّه الشرع، وكذا النفقة ))."],"en":["His statement, “according to your spending or your hardship,” was explained by al-Nawawi, who said: “This clearly shows that reward and merit in worship increase with increased hardship and spending, so long as the hardship is not something condemned by the Sacred Law, and likewise for spending.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1787},{"key":"muslim","label":"مسلم","number":126}]},{"num":5389,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن أبي بكر الصديق، أنّ النبي ﷺ أمره أن يردف عائشة فيعمرها من التنعيم."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٨٤)، ومسلم (١٢١٢).","grade":"متفق عليه","chapter_ar":"باب الاعتمار من التنعيم للمرأة التي لم تعتمر قبل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1784) and Muslim (1212).","chapter_en":"Performing Umrah from al-Tan‘im for the woman who did not perform Umrah before Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Abd al-Rahman ibn Abi Bakr al-Siddiq narrated that the Prophet ﷺ instructed him to take Aishah behind him and let her perform Umrah from al-Tan‘im."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1784},{"key":"muslim","label":"مسلم","number":1212}]},{"num":5390,"demo":false,"sanad":"","matn":["عن عائشة، قالت: خرجنا مع رسول الله ﷺ عام حجة الوداع… فلما قضينا الحج أرسلني رسول الله ﷺ مع عبد الرحمن بن أبي بكر إلى التنعيم، فاعتمرت."],"takhrij":"متفق عليه: رواه البخاريّ (١٥٥٦)، ومسلم (١١١ : ١٢١١).","grade":"متفق عليه","chapter_ar":"باب الاعتمار من التنعيم للمرأة التي لم تعتمر قبل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1556) and Muslim (1211/111).","chapter_en":"Performing Umrah from al-Tan‘im for the woman who did not perform Umrah before Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Aishah said: We went out with the Messenger of Allah ﷺ in the year of the Farewell Pilgrimage… Then when we completed the Hajj, the Messenger of Allah ﷺ sent me with Abd al-Rahman ibn Abi Bakr to al-Tan‘im, and I performed Umrah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1556},{"key":"muslim","label":"مسلم","number":111}]},{"num":5391,"demo":false,"sanad":"","matn":["عن حفصة بنت عبد الرحمن بن أبي بكر، عن أبيها، أنّ رسول الله ﷺ قال لعبد الرحمن: (( يا عبد الرحمن، أردف أختك عائشة فأعمرها من التنعيم، فإذا هبطت بها من الأكمة فلتحرم، فإنها عمرة متقبلة ))."],"takhrij":"صحيح: رواه أبو داود (١٩٩٥)، وأحمد (١٧١٠)، والحاكم (٦٠١٧)، والبيهقي (٤/٣٥٧-٣٥٨).","grade":"صحيح","chapter_ar":"باب الاعتمار من التنعيم للمرأة التي لم تعتمر قبل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1995), Ahmad (1710), al-Hakim (6017), and al-Bayhaqi (4/357–358).","chapter_en":"Performing Umrah from al-Tan‘im for the woman who did not perform Umrah before Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Hafsah bint Abd al-Rahman ibn Abi Bakr narrated from her father that the Messenger of Allah ﷺ said to Abd al-Rahman: “Abd al-Rahman, let your sister Aishah ride behind you and let her perform Umrah from al-Tan‘im. When you descend with her from the hill, then let her enter ihram, for it is an accepted Umrah.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1995},{"key":"البیہقی","label":"البيهقي","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":1710,"n":1710},{"key":"hakim","label":"المستدرك على الصحيحين","number":6017,"n":6014},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":8798,"n":8876}]},{"num":5392,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أنّ النبي ﷺ أهلّ وأصحابه بالحجّ… وأن عائشة حاضت، فنسكت المناسك كلها غير أنها لم تطف بالبيت. قال: فلما طهرت وطافت قالت: يا رسول الله، أتنطلقون بعمرة وحجة، وأنطلق بالحج؟ فأمر عبد الرحمن بن أبي بكر أن يخرج معها إلى التنعيم، فاعتمرت بعد الحج في ذي الحجة."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٨٥)، ومسلم (١٢١٦).","grade":"متفق عليه","chapter_ar":"باب الاعتمار من التنعيم للمرأة التي لم تعتمر قبل الحج","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1785) and Muslim (1216).","chapter_en":"Performing Umrah from al-Tan‘im for the woman who did not perform Umrah before Hajj","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Jabir ibn Abd Allah narrated that the Prophet ﷺ and his Companions entered ihram for Hajj… and that Aishah menstruated, so she performed all the rites except that she did not circumambulate the House. Then when she became pure and performed tawaf, she said: O Messenger of Allah ﷺ, will you all return having done an Umrah and a Hajj while I return with only a Hajj? So he instructed Abd al-Rahman ibn Abi Bakr to go out with her to al-Tan‘im, and she performed Umrah after Hajj in Dhu al-Hijjah."]},"buhuth":{"ar":["ورواه مسلم (١٢١٣) ولفظه: (( … فقالت: يا رسول الله، إني أجد في نفسي أني لم أطُف بالبيت حتى حججت. قال: فاذهب بها يا عبد الرحمن، فأعمرها من التنعيم )). وذلك ليلة الحصبة.","وكان إذن النبي ﷺ لعائشة تطييبًا لخاطرها، وإلا فيكره الخروج من مكة لعمرة تطوع؛ لأن النبي ﷺ لم يفعله ولا أصحابه، لا في رمضان ولا في غيره، والطواف بالبيت أفضل من الخروج اتفاقًا. علمًا بأن النبي ﷺ لم يأمر عبد الرحمن بن أبي بكر أن يعتمر مع عائشة. وأما الإنسان إذا اعتمر لنفسه ثم تحلل منها، ثم أراد أن يعتمر لأبيه ميتًا أو عاجزًا، وكذا لأمه، فلا بأس أن يخرج إلى الحل كالتنعيم ويحرم منه بالعمرة، ولا يجب عليه السفر إلى الميقات. وبه أفتت اللجنة الدائمة."],"en":["And Muslim also narrated it (1213) with the wording: “…She said: O Messenger of Allah ﷺ, I still feel uneasy that I did not circumambulate the House until after I had performed Hajj. He said: ‘Take her, Abd al-Rahman, and let her perform Umrah from al-Tan‘im.’” And that was on the night of al-Hasbah.","The Prophet ﷺ’s permission for Aishah was to comfort her heart. Otherwise, going out from Makkah merely for a voluntary Umrah is considered disliked, because the Prophet ﷺ did not do that, nor did his Companions, neither in Ramadan nor at other times, and circumambulation of the House is better than going out for that by agreement. It is also worth noting that the Prophet ﷺ did not instruct Abd al-Rahman ibn Abi Bakr to perform Umrah along with Aishah. As for a person who already performed Umrah for himself and then exited from it, and later wanted to perform Umrah on behalf of his deceased or incapable father, and likewise his mother, there is no harm in going out to the area outside the sanctuary such as al-Tan‘im and entering ihram for Umrah from there, and he does not need to travel all the way to the original miqat. This was also the ruling given by the Permanent Committee."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1785},{"key":"muslim","label":"مسلم","number":1216}]},{"num":5393,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أن رسول الله ﷺ اعتمر أربع عمر، كلّهنّ في ذي القعدة إلا التي مع حجّته: عمرة من الحديبية — أو زمن الحديبية — في ذي القعدة، وعمرة من العام المقبل في ذي القعدة، وعمرة من الجعرانة حيث قسم غنائم حنين في ذي القعدة، وعمرة مع حجته."],"takhrij":"متفق عليه: رواه البخاري (١٧٧٨)، ومسلم (١٢٥٣).","grade":"متفق عليه","chapter_ar":"باب الاعتمار من الجعرانة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1778) and Muslim (1253).","chapter_en":"Performing Umrah from al-Ji‘ranah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Malik narrated that the Messenger of Allah ﷺ performed four Umrahs, all of them in Dhu al-Qi‘dah except the one joined with his Hajj: the Umrah of al-Hudaybiyah — or during the time of al-Hudaybiyah — in Dhu al-Qi‘dah, the Umrah of the following year in Dhu al-Qi‘dah, the Umrah from al-Ji‘ranah where he distributed the spoils of Hunayn in Dhu al-Qi‘dah, and the Umrah joined with his Hajj."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1778},{"key":"muslim","label":"مسلم","number":1253}]},{"num":5394,"demo":false,"sanad":"","matn":["عن أبي هريرة في قوله تعالى: ( بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ ) [التوبة: ١] قال: ما قفل النبي ﷺ من حنين اعتمر من الجعرانة، ثم أمّر أبا بكر على تلك الحجة."],"takhrij":"صحيح: رواه ابن خزيمة (٣٠٧٨)، وعنه ابن حبان (٣٧٠٧).","grade":"صحيح","chapter_ar":"باب الاعتمار من الجعرانة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (3078), and from him Ibn Hibban (3707).","chapter_en":"Performing Umrah from al-Ji‘ranah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah, regarding the verse, “A declaration of disavowal from Allah and His Messenger” [al-Tawbah: 1], said: When the Prophet ﷺ returned from Hunayn, he performed Umrah from al-Ji‘ranah, then he appointed Abu Bakr over that pilgrimage."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":3078},{"key":"عنہ_ابن_حبان","label":"عنه ابن حبان","number":3707},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5482,"n":5478}]},{"num":5395,"demo":false,"sanad":"","matn":["عن معاوية، قال: قصرتُ عن رسول الله ﷺ بمشقص."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٣٠)، ومسلم (٢١٠ : ١٢٤٦).","grade":"متفق عليه","chapter_ar":"باب تقصير النبي ﷺ في عمرته من الجعرانة","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1730) and Muslim (1246/210).","chapter_en":"The Prophet’s shortening of his hair in his Umrah from al-Jiʿranah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Muawiyah said: I shortened the hair of the Messenger of Allah ﷺ with a broad arrowhead."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1730},{"key":"muslim","label":"مسلم","number":210}]},{"num":5396,"demo":false,"sanad":"","matn":["عن البراء بن عازب، قال: لما اعتمر النبي ﷺ في ذي القعدة، أبى أهل مكة أن يدعوه يدخل مكة حتى قاضاهم على أن يقيم بها ثلاثة أيام. فلما كتبوا الكتاب، كتبوا: هذا ما قاضى عليه محمد رسول الله. قالوا: لا نقر لك بهذا، لو نعلم أنك رسول الله ما منعناك شيئًا، ولكن أنت محمد بن عبد الله. فقال: (( أنا رسول الله وأنا محمد بن عبد الله )). ثم قال لعلي بن أبي طالب رضي الله عنه: (( امحُ رسول الله )). قال علي: لا والله لا أمحوك أبدًا. فأخذ رسول الله ﷺ الكتاب — وليس يحسن يكتب — فكتب: (( هذا ما قاضى عليه محمد بن عبد الله: لا يدخل مكة السلاح إلا السيف في القراب، وأن لا يخرج من أهلها بأحد إن أراد أن يتبعه، وأن لا يمنع من أصحابه أحدًا إن أراد أن يقيم بها )). فلما دخلها ومضى الأجل، أتوا عليًا فقالوا: قل لصاحبك اخرج عنا، فقد مضى الأجل. فخرج النبي ﷺ، فتبعته ابنة حمزة تنادي: يا عم يا عم. فتناولها علي، فأخذ بيدها، وقال لفاطمة: دونك ابنة عمك. فاختصم فيها علي وزيد وجعفر. قال علي: أنا أخذتها وهي ابنة عمي. وقال جعفر: ابنة عمي وخالتها تحتي. وقال زيد: ابنة أخي. فقضى بها النبي ﷺ لخالتها، وقال: (( الخالة بمنزلة الأم )). وقال لعلي: (( أنت مني وأنا منك )). وقال لجعفر: (( أشبهت خلقي وخُلقي )). وقال لزيد: (( أنت أخونا ومولانا )). وقال علي: ألا تتزوج ابنة حمزة؟ قال: (( إنها ابنة أخي من الرضاعة ))."],"takhrij":"متفق عليه: رواه البخاريّ (٤٢٥١)، ومسلم (١٧٨٣/٩٢).","grade":"متفق عليه","chapter_ar":"باب ما جاء في أمر الحديبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4251) and Muslim (1783/92).","chapter_en":"What has been narrated concerning the affair of al-Hudaybiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Al-Bara’ ibn Azib said: When the Prophet ﷺ came for Umrah in Dhu al-Qi‘dah, the people of Makkah refused to let him enter Makkah until he concluded a treaty with them that he would stay there for three days. When they wrote the document, they wrote: “This is what Muhammad, the Messenger of Allah ﷺ, has agreed upon.” They said: We do not affirm this for you. If we knew that you were the Messenger of Allah ﷺ, we would not have prevented you from anything. Rather, you are Muhammad ibn Abd Allah. So he said: “I am the Messenger of Allah ﷺ, and I am Muhammad ibn Abd Allah.” Then he said to Ali ibn Abi Talib, may Allah be pleased with him: “Erase ‘Messenger of Allah ﷺ.’” Ali said: No, by Allah, I will never erase you. So the Messenger of Allah ﷺ took the document — and he did not write well — and wrote: “This is what Muhammad ibn Abd Allah has agreed upon: that he will not enter Makkah with weapons except swords in their sheaths, that he will not take out anyone from its people if that person wants to follow him, and that he will not prevent any of his Companions from staying there if one of them wishes to remain.” When he entered it and the agreed period expired, they came to Ali and said: Tell your companion to leave us, for the term has expired. So the Prophet ﷺ departed. Then Hamzah’s daughter followed him, calling: Uncle, uncle! Ali took hold of her hand and said to Fatimah: Here is your cousin’s daughter. Then Ali, Zayd, and Ja‘far disputed over her. Ali said: I took her, and she is my cousin’s daughter. Ja‘far said: She is my cousin’s daughter, and her maternal aunt is my wife. Zayd said: She is my brother’s daughter. The Prophet ﷺ ruled that she should go to her maternal aunt and said: “The maternal aunt is in the place of the mother.” He said to Ali: “You are from me and I am from you.” He said to Ja‘far: “You resemble me in appearance and character.” And he said to Zayd: “You are our brother and our freedman.” Ali then said: Will you not marry Hamzah’s daughter? He said: “She is the daughter of my milk-brother.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4251},{"key":"muslim","label":"مسلم","number":1783}]},{"num":5397,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر: أنّ رسول الله ﷺ خرج معتمرًا، فحال كفار قريش بينه وبين البيت، فنحر هديه وحلق رأسه بالحديبية، وقاضاهم على أن يعتمر العام المقبل، ولا يحمل سلاحًا عليهم إلا سيوفًا، ولا يقيم بها إلا ما أحبوا. فاعتمر من العام المقبل، فدخلها كما كان صالحهم، فلما أقام بها ثلاثًا أمروه أن يخرج فخرج."],"takhrij":"صحيح: رواه البخاريّ (٤٢٥٢).","grade":"صحيح","chapter_ar":"باب ما جاء في أمر الحديبية","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4252).","chapter_en":"What has been narrated concerning the affair of al-Hudaybiyah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Umar narrated that the Messenger of Allah ﷺ went out for Umrah, but the disbelievers of Quraysh prevented him from the House. So he slaughtered his sacrificial animal and shaved his head at al-Hudaybiyah, and made an agreement with them that he would perform Umrah the following year, would carry no weapons against them except swords, and would stay there only as long as they wished. So he performed Umrah the following year and entered it according to the terms of their agreement. When he had stayed there for three days, they ordered him to leave, so he left."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4252}]},{"num":5398,"demo":false,"sanad":"","matn":["عن عبد الله بن أبي أوفى، قال: اعتمر رسول الله ﷺ واعتمرنا معه، فلما دخل مكة طاف وطفنا معه، وأتى الصفا والمروة وأتيناها معه، وكنا نستره من أهل مكة أن يرميه أحد. فقال له صاحب لي: أكان دخل الكعبة؟ قال: لا."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٩١)، ومسلم (١٣٣٢).","grade":"متفق عليه","chapter_ar":"باب متى يحل المعتمر","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1791) and Muslim (1332).","chapter_en":"When the one performing Umrah exits the state of ihram","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Abdullah ibn Abi Awfa said: The Messenger of Allah ﷺ performed Umrah, and we performed Umrah with him. When he entered Makkah, he performed tawaf and we performed tawaf with him. He came to al-Safa and al-Marwah, and we came with him, and we were shielding him from the people of Makkah lest anyone throw something at him. A companion of mine said to him: Did he enter the Ka‘bah? He said: No."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1791},{"key":"muslim","label":"مسلم","number":1332}]},{"num":5399,"demo":false,"sanad":"","matn":["عن البراء، قال: فأقام بها ثلاثة أيام، فلما أن كان يوم الثالث، قالوا لعلي: هذا آخر يوم من شرط صاحبك، فمره فليخرج. فأخبره بذلك فقال: (( نعم )). فخرج."],"takhrij":"متفق عليه: رواه البخاريّ (٤٢٥١)، ومسلم (١٧٨٣/٩٢).","grade":"متفق عليه","chapter_ar":"باب مدة قيام النبي ﷺ في عمرة القضاء","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4251) and Muslim (1783/92).","chapter_en":"The length of the Prophet’s stay during the make-up Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Al-Bara’ said: He stayed there for three days. Then when it was the third day, they said to Ali: This is the last day according to your companion’s agreement, so tell him to leave. He informed him of that, and he said: “Yes.” So he left."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":4251},{"key":"muslim","label":"مسلم","number":1783}]},{"num":5400,"demo":false,"sanad":"","matn":["عن ابن عمر، قال: فاعتمر رسول الله ﷺ من العام المقبل، فدخلها كما كان صالحهم، فلما أقام بها ثلاثًا أمروه أن يخرج فخرج."],"takhrij":"صحيح: رواه البخاريّ (٢٧٠١).","grade":"صحيح","chapter_ar":"باب مدة قيام النبي ﷺ في عمرة القضاء","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2701).","chapter_en":"The length of the Prophet’s stay during the make-up Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ performed Umrah the following year and entered it according to the agreement he had made with them. Then when he had stayed there for three days, they ordered him to leave, so he left."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2701}]},{"num":5401,"demo":false,"sanad":"","matn":["عن ابن عباس: أنّ رسول الله ﷺ أقام في عمرة القضاء ثلاثًا."],"takhrij":"حسن: رواه أبو داود (١٩٩٧)، وابن هشام (٢/٣٧٢).","grade":"حسن","chapter_ar":"باب مدة قيام النبي ﷺ في عمرة القضاء","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1997) and Ibn Hisham (2/372).","chapter_en":"The length of the Prophet’s stay during the make-up Umrah","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":16,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ stayed for three days during the make-up Umrah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1997},{"key":"ابن_ہشام","label":"ابن هشام","number":2}]},{"num":5402,"demo":false,"sanad":"","matn":["عن عائشة، قالت: نزل رسول الله ﷺ المحصب، فدعا عبد الرحمن بن أبي بكر فقال: (( اخرج بأختك من الحرم، فلتهلّ بعمرة، ثم لتطف بالبيت، فإني أنتظركما ههنا )). قالت: فخرجنا، فأهللت، ثم طفت بالبيت وبين الصفا والمروة، فجئنا رسول الله ﷺ وهو في منزله من جوف الليل، فقال: (( هل فرغتِ؟ )) قلت: نعم، فأذن في أصحابه بالرحيل، فخرج فمرّ بالبيت فطاف به قبل صلاة الصبح، ثم خرج إلى المدينة."],"takhrij":"متفق عليه: رواه البخاريّ (١٧٨٨)، ومسلم (١٢٣ : ١٢١١).","grade":"متفق عليه","chapter_ar":"باب في إجزاء طواف العمرة عن الوداع","chapter_ur":"","part_ar":"كتاب الحج","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1788) and Muslim (1211/123).","chapter_en":"That the tawaf of Umrah can suffice for the farewell tawaf","part_en":"The Book of Pilgrimage","group_ar":"جموع أبواب ما جاء في العمرة","group_en":"Collection of chapters on what has been narrated regarding the lesser pilgrimage","part_no":16,"group_no":7,"chapter_no":17,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ stopped at al-Muhassab and called Abd al-Rahman ibn Abi Bakr and said: “Take your sister out of the sanctuary so that she may enter ihram for Umrah, then let her perform tawaf of the House. I will wait for both of you here.” She said: So we went out, and I entered ihram, then I circumambulated the House and went between al-Safa and al-Marwah. Then we came back to the Messenger of Allah ﷺ while he was in his lodging in the middle of the night. He said: “Have you finished?” I said: Yes. Then he announced departure to his Companions, so he went out and passed by the House and performed tawaf before the dawn prayer, then departed for Madinah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":1788},{"key":"muslim","label":"مسلم","number":123}]},{"num":5403,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: إنكم تقولون: إن أبا هريرة يكثر الحديث عن رسول الله ﷺ، وتقولون: ما بال المهاجرين والأنصار لا يحدّثون عن رسول الله ﷺ بمثل حديث أبي هريرة؟! وإن إخوتي من المهاجرين كان يشغلهم صفقٌ بالأسواق، وكنت ألزم رسول الله ﷺ على ملء بطني، فأشهد إذا غابوا، وأحفظ إذا نسوا، وكان يشغل إخوتي من الأنصار عمل أموالهم، وكنت امرأً مسكينًا من مساكين الصفة، أعي حين ينسون، وقد قال رسول الله ﷺ في حديث يحدثه: (( إنه لن يبسط أحد ثوبه حتى أقضي مقالتي هذه، ثم يجمع إليه ثوبه، إلا وعى ما أقول )). فبسطت نمرةً عليَّ، حتى إذا قضى رسول الله ﷺ مقالته جمعتها إلى صدري، فما نسيت من مقالة رسول الله ﷺ تلك من شيء."],"takhrij":"صحيح: رواه البخاريّ (٢٠٤٧) ومسلم (٢٤٩٢). واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب ما جاء في مشروعية البيع والتجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2047) and Muslim (2492). The wording is that of al-Bukhari.","chapter_en":"What has been narrated regarding the lawfulness of sale and trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: You say that Abu Hurayrah narrates many reports from the Messenger of Allah ﷺ, and you say: Why is it that the Emigrants and the Helpers do not narrate from the Messenger of Allah ﷺ like the reports of Abu Hurayrah? My brothers from the Emigrants were occupied with buying and selling in the marketplaces, while I stayed close to the Messenger of Allah ﷺ so long as my stomach was filled. So I was present when they were absent, and I remembered when they forgot. And my brothers from the Helpers were occupied with working on their wealth, while I was a poor man from among the poor people of the bench, so I retained what they forgot. And the Messenger of Allah ﷺ once said in a report he delivered: “No one will spread out his garment until I finish this statement of mine, then gather it to himself, except that he will retain what I say.” So I spread out a striped cloth over myself, and when the Messenger of Allah ﷺ finished his statement, I gathered it to my chest, and after that I forgot nothing from that statement of the Messenger of Allah ﷺ."]},"buhuth":{"ar":["ورواه البخاري (١١٨) عن أبي هريرة قال: “إن الناس يقولون: أكثر أبو هريرة، ولولا آيتان في كتاب الله ما حدثت حديثًا”، ثم يتلو: ( إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ أُولَٰئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ ۝ إِلَّا الَّذِينَ تَابُوا وَأَصْلَحُوا وَبَيَّنُوا فَأُولَٰئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا التَّوَّابُ الرَّحِيمُ ) [سورة البقرة: ١٥٩-١٦٠]، إن إخواننا من المهاجرين كان يشغلهم الصفق في الأسواق، وإن إخواننا من الأنصار كان يشغلهم العمل في أموالهم، وإن أبا هريرة كان يلزم رسول الله ﷺ بشبع بطنه، ويحضر ما لا يحضرون، ويحفظ ما لا يحفظون."],"en":["Al-Bukhari also narrated (118) from Abu Hurayrah that he said: “People say: Abu Hurayrah narrates too much. Were it not for two verses in the Book of Allah, I would not narrate any report,” then he recited: “Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Book — those are cursed by Allah and cursed by those who curse, except those who repent, correct themselves, and make it clear. Those — I will accept their repentance, and I am the Acceptor of repentance, the Merciful.” [Surat al-Baqarah: 159–160] He then said: My brothers from the Emigrants were occupied with trade in the markets, and my brothers from the Helpers were occupied with working on their wealth, while Abu Hurayrah stayed with the Messenger of Allah ﷺ with only enough to fill his stomach, attending what they did not attend and preserving what they did not preserve."]},"intro_kitab":{"ar":["جموع ما جاء في أحكام البيوع والتجارات"],"en":["A collection of what has been narrated regarding the rulings of sales and trade"]},"intro":{"ar":["قال الله تعالى: ( وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا ) [سورة البقرة: ٢٧٥].","وقال تعالى: ( لَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ بَيْنَكُمْ ) [سورة النساء: ٢٩]."],"en":["Allah the Exalted said: “Allah has made trade lawful and has forbidden usury.” [Surat al-Baqarah: 275]","And He said: “Do not consume one another’s wealth unjustly, except that it be trade conducted by mutual consent among you.” [Surat al-Nisa’: 29]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاريّ","number":2047},{"key":"muslim","label":"مسلم","number":2492}]},{"num":5404,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: قدم عبد الرحمن بن عوف المدينة، فآخى النبي ﷺ بينه وبين سعد بن الربيع الأنصاري، وكان سعد ذا غنى، فقال لعبد الرحمن: أقاسمك مالي نصفين وأزوجك… فقال: بارك الله لك في أهلك ومالك، دلوني على السوق… الحديث."],"takhrij":"صحيح: رواه البخاري (٢٠٤٩).","grade":"صحيح","chapter_ar":"باب ما جاء في مشروعية البيع والتجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2049).","chapter_en":"What has been narrated regarding the lawfulness of sale and trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: Abd al-Rahman ibn Awf came to Madinah, and the Prophet ﷺ established brotherhood between him and Sa‘d ibn al-Rabi‘ al-Ansari. Sa‘d was a wealthy man, and he said to Abd al-Rahman: I will divide my wealth with you in two equal parts, and I will arrange a marriage for you… But he replied: “May Allah bless your family and your wealth for you. Show me the market.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2049}]},{"num":5405,"demo":false,"sanad":"","matn":["عن ابن عباس قال: كانت عكاظ، ومجنة، وذو المجاز، أسواقًا في الجاهلية، فلما كان الإسلام فكأنهم تأثموا فيه، فنزلت: ( لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَبْتَغُوا فَضْلًا مِنْ رَبِّكُمْ ) في مواسم الحج، قرأها ابن عباس."],"takhrij":"صحيح: رواه البخاري (٢٠٥٠).","grade":"صحيح","chapter_ar":"باب ما جاء في مشروعية البيع والتجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2050).","chapter_en":"What has been narrated regarding the lawfulness of sale and trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas said: Ukaz, Majannah, and Dhu al-Majaz were marketplaces in the pre-Islamic period. Then when Islam came, it was as though the people felt guilty about conducting trade there, so the verse was revealed: “There is no sin upon you in seeking bounty from your Lord,” referring to the seasons of pilgrimage. Ibn Abbas recited it in that way."]},"buhuth":{"ar":["وقوله: (( عكاظ )) — بضم أوله، وآخره ظاء معجمة — اسم سوق من أسواق العرب في الجاهلية، وكانت قبائل العرب تجتمع فيها في كل سنة، ويفاخرون فيها، ويحضرها شعراؤهم وأدباؤهم، وهو من قولهم: “عكظ الرجل صاحبه” إذا فاخره وغلبه بالمفاخرة.","وقوله: (( مجنة )) — بميم مفتوحة، وجيم معجمة، ونون مشددة مفتوحة — وهي من أسواق العرب في الجاهلية، وكانت مجنة بمر الظهران، قرب جبل يقال له الأصفر، وهو بأسفل مكة على قدر بريد منها، قال الأصمعي. ويقال: مجنة عند عرفة.","وقوله: (( ذو المجاز )) هو أيضًا سوق من أسواق العرب، قريب من عرفات. قال ابن الأثير: عكاظ، وذو المجاز، ومجنة، أسواق تجتمع بها العرب كل عام، إذا حضر الموسم، فيأمن بعضهم بعضًا حتى تنقضي أيامها. وكانت مجنة بالظهران، وكانت عكاظ بين نخلة والطائف، وكان ذو المجاز بالجانب الأيسر إذا وقفت على الموقف."],"en":["As for the word “Ukaz” — with a rounded vowel at the beginning and the letter zha at the end — it is the name of one of the well-known marketplaces of the Arabs in the pre-Islamic period. The Arab tribes used to gather there every year, boasting before one another, and their poets and men of letters would attend it. The name is related to their expression meaning that one man outdid another in boasting and overcame him in rivalry.","And “Majannah” — with an open letter mim, a jim, and a doubled open nun — was also one of the Arab marketplaces in the pre-Islamic period. It was located at Marr al-Zahran near a mountain called al-Asfar, below Makkah at about the distance of one postal stage from it, according to al-Asma‘i. It is also said that Majannah was near Arafah.","And “Dhu al-Majaz” was likewise one of the marketplaces of the Arabs, near Arafat. Ibn al-Athir said: Ukaz, Dhu al-Majaz, and Majannah were annual markets where the Arabs gathered during the pilgrimage season, and they would feel safe with one another until those days ended. Majannah was at al-Zahran, Ukaz was between Nakhlah and al-Ta’if, and Dhu al-Majaz was on the left side when one stood at the place of standing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2050}]},{"num":5406,"demo":false,"sanad":"","matn":["عن المقدام، عن رسول اللّٰه ﷺ قال: (( ما أكل أحدٌ طعاماً قطّ خيراً من أن يأكل من عمل يده، وإنّ نبيّ اللّٰه داود عليه السلام كان يأكل من عمل يده))."],"takhrij":"صحيح: رواه البخاري (٢٠٧٢).","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2072).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Al-Miqdam narrated from the Messenger of Allah ﷺ: “No one has ever eaten food better than that earned from the work of his own hands, and indeed the Prophet of Allah Dawud, peace be upon him, used to eat from the work of his own hands.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2072}]},{"num":5407,"demo":false,"sanad":"","matn":["عن المقدام بن معد يكرب الزبيدي، عن رسول اللّٰه ﷺ قال: (( ما كسب الرجل كسباً أطيب من عمل يده، وما أنفق الرجل على نفسه، وأهله وولده، وخادمه فهو صدقة))."],"takhrij":"حسن: رواه ابن ماجه (٢١٣٨). ورواه أحمد (١٧١٩٠) من وجه آخر بلفظ: (( ما أكل أحدكم طعاماً في الدنيا خيراً له من أن يأكل من عمل يده)). وفي رواية: (( ما أكل أحد منكم طعاماً أحب إلى الله عز وجل من عمل يده)). رواه أحمد (١٧١٨١).","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2138). Ahmad also narrated it (17190) through another route with the wording: “None of you eats any food in this world better for him than what he eats from the work of his own hand.” In another narration: “None of you eats any food more beloved to Allah the Mighty and Majestic than what he earns from the work of his own hand.” Narrated by Ahmad (17181).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Al-Miqdam ibn Ma‘di Karib al-Zubaydi narrated that the Messenger of Allah ﷺ said: “No man ever earns anything purer than what he earns by the work of his own hand. And whatever a man spends on himself, his family, his children, and his servant is charity.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2138},{"key":"ورواہ_احمد","label":". ورواه أحمد","number":17190},{"key":"رواہ_احمد","label":". رواه أحمد","number":17181}]},{"num":5408,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: بينما نحن جلوس مع رسول الله ﷺ إذ طلع علينا شاب من الثنية، فلما رأيناه بأبصارنا قلنا: لو أن هذا الشاب جعل شبابه ونشاطه وقوته في سبيل الله. فسمع مقالَتَنا رسولُ الله ﷺ فقال: (( وما سبيل الله إلا من قُتل؟ من سعى على والديه فهو في سبيل الله، ومن سعى على عياله فهو في سبيل الله، ومن سعى على نفسه ليعفها فهو في سبيل الله، ومن سعى على التكاثر فهو في سبيل الشيطان))."],"takhrij":"حسن: أخرجه البزار - كشف الأستار (١٨٧١)، والطبراني في الأوسط (٤٣٧٢)، والبيهقي (٢٥/٩).","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Reported by al-Bazzar in Kashf al-Astar (1871), al-Tabarani in al-Awsat (4372), and al-Bayhaqi (9/25).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: While we were sitting with the Messenger of Allah ﷺ, a young man came up toward us from the mountain path. When we saw him, we said: If only this young man would devote his youth, energy, and strength to the cause of Allah. The Messenger of Allah ﷺ heard what we said and replied: “Is the cause of Allah only for the one who is killed? Whoever strives for his parents is in the cause of Allah. Whoever strives for his dependents is in the cause of Allah. Whoever strives for himself in order to keep himself chaste is in the cause of Allah. And whoever strives for accumulation is in the cause of Satan.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1871},{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":4372},{"key":"البیہقی","label":"البيهقي","number":25},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1871,"n":1872},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17824,"n":17982}]},{"num":5409,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول اللّٰه ﷺ: (( أن داود عليه السلام كان لا يأكل إلا من عمل يده))."],"takhrij":"صحيح: رواه البخاري (٢٠٧٣).","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2073).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Messenger of Allah ﷺ: “Dawud, peace be upon him, used to eat only from the work of his own hands.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2073}]},{"num":5410,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( ما بعث الله نبياً إلا رعى الغنم)). فقال أصحابه: وأنت؟ فقال: (( نعم، كنت أرعاها على قراريط لأهل مكة))."],"takhrij":"صحيح: رواه البخاري (٢٢٦٢).","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2262).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Allah did not send any prophet except that he herded sheep.” His companions said: Even you? He said: “Yes, I used to herd them for some qirats for the people of Makkah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2262}]},{"num":5411,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( كان زكريا نجاراً ))."],"takhrij":"صحيح: رواه مسلم (٢٣٧٩).","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2379).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Zakariyya was a carpenter.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2379}]},{"num":5412,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن رسول اللّٰه ﷺ قال: (( والذي نفسي بيده لأن يأخذ أحدكم حبله فيحتطب على ظهره خير له من أن يأتي رجلاً أعطاه الله من فضله فيسأله، أعطاه أو منعه ))."],"takhrij":"متفق عليه: رواه مالك (٦٠) والبخاري (١٤٧٠)، ومسلم (١٠٤٢).","grade":"متفق عليه","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (60), al-Bukhari (1470), and Muslim (1042).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “By the One in Whose hand is my soul, for one of you to take his rope and gather firewood on his back is better for him than going to a man whom Allah has given from His bounty and asking him, whether he gives him or refuses him.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":60},{"key":"bukhari","label":"البخاري","number":1470},{"key":"muslim","label":"مسلم","number":1042}]},{"num":5413,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( بينما أيوب يغتسل عرياناً خرَّ عليه رجل جراد من ذهب، فجعل يحثي في ثوبه، فنادى ربه: يا أيوب! ألم أكن أغنيتك عما ترى؟ قال: بلى يا رب، ولكن لا غنى لي عن بركتك))."],"takhrij":"صحيح: رواه البخاري (٣٣٩١).","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3391).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “While Ayyub was bathing unclothed, a swarm of golden locusts fell upon him, and he began gathering them into his garment. Then his Lord called out to him: O Ayyub, did I not make you free of need from what you see? He replied: Yes, my Lord, but I can never do without Your blessing.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3391}]},{"num":5414,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: (( خير الكسب كسب يد العامل إذا نصح))."],"takhrij":"حسن: رواه الإمام أحمد (٨٦٩١، ٨٤١٢).","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (8691, 8412).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “The best earning is the earning of a worker’s own hand when he is sincere.”"]},"buhuth":{"ar":["وقوله: (( إذا نصح )) أي إذا أخلص في عمله. ويدخل في هذا البناؤون والكتّاب."],"en":["The phrase “when he is sincere” means when he is honest and sincere in his work. This includes builders and scribes."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":8691},{"key":"ahmad","label":"مسند الإمام أحمد","number":8691,"n":8691}]},{"num":5415,"demo":false,"sanad":"","matn":["عن الزبير بن العوام، عن النبي ﷺ قال:","«لَأَنْ يَأْخُذَ أَحَدُكُمْ حَبْلَهُ، فَيَأْتِيَ بِحُزْمَةِ حَطَبٍ عَلَى ظَهْرِهِ فَيَبِيعَهَا، فَيَكُفَّ اللَّهُ بِهَا وَجْهَهُ، خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ، أَعْطَوْهُ أَوْ مَنَعُوهُ»."],"takhrij":"صحيح: رواه البخاري (١٤٧١).","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1471).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Al-Zubayr ibn al-ʿAwwām reported that the Prophet ﷺ said:","“For one of you to take his rope, bring a bundle of firewood upon his back and sell it, thereby allowing Allah to preserve his dignity, is better for him than asking people, whether they give him or refuse him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1471}]},{"num":5416,"demo":false,"sanad":"","matn":["عن عائشة قالت: كان أصحاب رسول اللّٰه ﷺ عُمّال أنفسهم، وكان يكون لهم أرواح، فقيل لهم: (( لو اغتسلتم ))."],"takhrij":"صحيح: رواه البخاري (٢٠٧١) ومسلم (٨٤٧/٦).","grade":"صحيح","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2071) and Muslim (847).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Aishah said: The companions of the Messenger of Allah ﷺ used to do their own labor, and they would come with the smell of perspiration. So it was said to them: “If only you would wash yourselves.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2071},{"key":"muslim","label":"مسلم","number":847}]},{"num":5417,"demo":false,"sanad":"","matn":["عن معاذ بن عبد الله بن خبيب، عن أبيه، عن عمه، قال: كنا في مجلس، فجاء النبي ﷺ وعلى رأسه أثر ماء، فقال له بعضنا: نراك اليوم طيب النفس. فقال: (( أجل، والحمد لله )). ثم أفاض القوم في ذكر الغنى، فقال: (( لا بأس بالغنى لمن اتقى، والصحة لمن اتقى خير من الغنى، وطيب النفس من النعيم ))."],"takhrij":"حسن: رواه ابن ماجه (٢١٤١) واللفظ له، وأحمد (٢٣١٥٨) والحاكم (٢١٣١).","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2141), and this is his wording; also by Ahmad (23158) and al-Hakim (2131).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Mu‘adh ibn Abdullah ibn Khubayb narrated from his father, from his uncle, who said: We were sitting in a gathering when the Prophet ﷺ came, and there was a trace of water on his head. Some of us said to him: We see that you are in good spirits today. He said: “Yes, and praise be to Allah.” Then the people began discussing wealth, and he said: “There is no harm in wealth for the one who is mindful of Allah, and good health for the one who is mindful of Allah is better than wealth, and contentment of the soul is part of bliss.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2141},{"key":"ahmad","label":"مسند الإمام أحمد","number":23158,"n":23158},{"key":"hakim","label":"المستدرك على الصحيحين","number":2131,"n":2122}]},{"num":5418,"demo":false,"sanad":"","matn":["عن ابن عمر قال: سئل رسول اللّٰه ﷺ عن أطيب الكسب؟ فقال: (( عمل الرجل بيده، وكل بيع مبرور ))."],"takhrij":"حسن: رواه الطبراني في الأوسط (٢١٦١).","grade":"حسن","chapter_ar":"باب في الحث على كسب الرجل وطلب الحلال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (2161).","chapter_en":"Encouragement for a man to earn and seek what is lawful","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ was asked about the purest earning, and he said: “A man’s work with his own hand, and every righteous sale.”"]},"buhuth":{"ar":["وقوله: (( بيع مبرور )) أي بيع لم يخالطه إثم، ولا حلف كاذب ونحوه."],"en":["The phrase “every righteous sale” means a sale not mixed with sin, false oaths, or the like."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":2161},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":2140,"n":2132}]},{"num":5419,"demo":false,"sanad":"","matn":["عن أم المؤمنين عائشة، عن النبي ﷺ قال: (( ولد الرجل من كسبه، من أطيب كسبه، فكلوا من أموالهم ))."],"takhrij":"حسن: رواه أبو داود (٣٥٢٩)، وأحمد (٢٤٩٥١)، والحاكم (٤٦، ٤٥/٢).","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3529), Ahmad (24951), and al-Hakim (2/45–46).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["The Mother of the Believers Aishah narrated that the Prophet ﷺ said: “A man’s child is from his earnings, from the best of his earnings, so eat from their wealth.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3529},{"key":"ahmad","label":"مسند الإمام أحمد","number":24951,"n":24951},{"key":"hakim","label":"المستدرك على الصحيحين","number":2294,"n":2286}]},{"num":5420,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص قال: أتى أعرابي رسول اللّٰه ﷺ فقال: إن أبي يريد أن يجتاح مالي. قال: (( أنت ومالك لأبيك، إن أطيب ما أكلتم من كسبكم، وإن أموال أولادكم من كسبكم، فكلوه هنيئاً ))."],"takhrij":"حسن: رواه أحمد (٦٦٧٨)، وابن الجارود في المنتقى (٩٩٥)، والبيهقي (٤٨٠/٧)، وأبو داود (٣٥٣٠).","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6678), Ibn al-Jarud in al-Muntaqa (995), al-Bayhaqi (7/480), and Abu Dawud (3530).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As said: A Bedouin came to the Messenger of Allah ﷺ and said: My father wants to take all my wealth. He said: “You and your wealth belong to your father. Indeed, the best of what you eat is from your own earnings, and the wealth of your children is from your earnings, so consume it with ease.”"]}},"tuhfa":{},"refs":[{"key":"ابن_الجارود/المنتقی","label":"ابن الجارود في المنتقى","number":995},{"key":"البیہقی","label":"البيهقي","number":480},{"key":"abudawud","label":"أبو داود","number":3530},{"key":"ahmad","label":"مسند الإمام أحمد","number":6678,"n":6678}]},{"num":5421,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن رجلاً قال: يا رسول الله، إن لي مالاً وولداً، وإن أبي يريد أن يجتاح مالي، فقال: (( أنت ومالك لأبيك ))."],"takhrij":"حسن: رواه ابن ماجه (٢٢٩١).","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2291).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that a man said: O Messenger of Allah ﷺ, I have wealth and children, and my father wants to take my wealth, so he said: “You and your wealth belong to your father.”"]},"buhuth":{"ar":["وقوله: (( أنت ومالك لأبيك )) أي أنه إذا احتاج إلى مالك أخذ منه قدر حاجته، لا أن له أن يجتاح جميع ماله على الوجه الصحيح أو غير الصحيح، فهذا لم يقل به أحد من أهل الاجتهاد. وقال البيهقي في الكبرى (٤٨١/٧): “من زعم أن مال الولد لأبيه احتج بظاهر هذا الحديث، ومن زعم أن له من ماله ما يكفيه إذا احتاج إليه، فإذا استغنى عنه لم يكن للأب من ماله شيء، احتج بالأخبار التي وردت في تحريم مال الغير، وأنه لو مات وله ابن، لم يكن للأب من ماله إلا السدس، ولو كان الأب يملك مال ابنه لحازه كله”."],"en":["The phrase “You and your wealth belong to your father” means that if the father needs his son’s wealth, he may take from it according to his need. It does not mean that he may consume all of it absolutely, rightly or wrongly. No qualified scholar said that. Al-Bayhaqi said in al-Kubra (7/481): Whoever claimed that the child’s wealth fully belongs to the father relied on the outward wording of this hadith. But whoever held that the father may take only what suffices him when he is in need, and that if he has no need then he has no right to any of it, relied on the reports prohibiting unlawful consumption of another’s wealth, and on the fact that if a person dies and leaves a father and a son, the father receives only one-sixth. If the father truly owned all of his son’s wealth, he would take all of it."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2291}]},{"num":5422,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسولُ اللّٰه ﷺ: (( الولدُ من كسبِ الوالدِ ))."],"takhrij":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (٢١٩٣).","grade":"حسن","chapter_ar":"باب أنَّ الولدَ من كسب أبيه، فله أن يأخذ من ماله ما يحتاج إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat, as cited in Majma‘ al-Bahrayn (2193).","chapter_en":"The child is from the earnings of his father, so the father may take from his child’s wealth what he needs","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “The child is from the earnings of the parent.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":2193}]},{"num":5423,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أن رسول اللّٰه ﷺ قال: (( رحم الله رجلاً سمحاً إذا باع، وإذا اشترى، وإذا اقتضى ))."],"takhrij":"صحيح: رواه البخاري (٢٠٧٦).","grade":"صحيح","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2076).","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Messenger of Allah ﷺ said: “May Allah have mercy on a man who is easygoing when he sells, when he buys, and when he asks for what is due to him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2076}]},{"num":5424,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول اللّٰه ﷺ: (( غفر الله لرجل كان قبلكم كان سهلاً إذا باع، وسهلاً إذا اشترى، وسهلاً إذا اقتضى ))."],"takhrij":"حسن: رواه الترمذي (١٣٢٠) والبيهقي (٥/٣٥٧-٣٥٨). قال الترمذي: حسن صحيح.","grade":"حسن","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1320) and al-Bayhaqi (5/357–358). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Allah forgave a man who lived before you because he was easygoing when he sold, easygoing when he bought, and easygoing when he sought his due.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1320},{"key":"البیہقی","label":"البيهقي","number":5}]},{"num":5425,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص قال: قال رسول اللّٰه ﷺ: (( دخل رجل الجنة بسماحته بائعاً ومبتاعاً ومقتضياً ))."],"takhrij":"حسن: رواه أحمد (٦٩٦٣).","grade":"حسن","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6963).","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As said: The Messenger of Allah ﷺ said: “A man entered Paradise because of his lenience when selling, buying, and collecting what was owed to him.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":6963,"n":6963}]},{"num":5426,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسول اللّٰه ﷺ: (( اسمح يُسمح لك ))."],"takhrij":"صحيح: رواه أحمد (٢٢٣٣)، والطبراني في الصغير (١١٦٩)، والقضاعي في مسند الشهاب (٦٤٨).","grade":"صحيح","chapter_ar":"باب السماحة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2233), al-Tabarani in al-Saghir (1169), and al-Quda‘i in Musnad al-Shihab (648).","chapter_en":"Gentleness and ease in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “Be easy with others, and ease will be shown to you.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الصغیر","label":"الطبراني في الصغير","number":1169},{"key":"القضاعی/مسند_الشہاب","label":"القضاعي في مسند الشهاب","number":648},{"key":"ahmad","label":"مسند الإمام أحمد","number":2233,"n":2233},{"key":"sh13068","label":"المعجم الصغير للطبراني","number":1169,"n":1163}]},{"num":5427,"demo":false,"sanad":"","matn":["عن حكيم بن حزام قال: قال رسول اللّٰه ﷺ: (( البيّعان بالخيار ما لم يتفرّقا، فإن صدقا وبينا بورك لهما في بيعهما، وإن كتما وكذبا مُحقت بركة بيعهما ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٧٩)، ومسلم (١٥٣٢).","grade":"متفق عليه","chapter_ar":"باب النصح والصدق في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2079) and Muslim (1532).","chapter_en":"Sincerity and truthfulness in buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Hakim ibn Hizam said: The Messenger of Allah ﷺ said: “The buyer and seller retain the choice as long as they have not separated. If they are truthful and make things clear, their sale will be blessed for them. But if they conceal and lie, the blessing of their sale will be erased.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2079},{"key":"muslim","label":"مسلم","number":1532}]},{"num":5428,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر أن رجلاً ذكر لرسول اللّٰه ﷺ أنه يُخدع في البيوع، فقال رسول الله ﷺ: (( إذا بايعت فقل: لا خلابة )). قال: فكان الرجل إذا بايع يقول: لا خلابة."],"takhrij":"متفق عليه: رواه مالك (٩٨) والبخاري (٢١١٧) ومسلم (١٥٣٣).","grade":"متفق عليه","chapter_ar":"باب فيمن يُخدع في البيع والشراء ماذا يقول؟","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (98), al-Bukhari (2117), and Muslim (1533).","chapter_en":"What one who is deceived in buying and selling should say","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abdullah ibn Umar narrated that a man mentioned to the Messenger of Allah ﷺ that he was being deceived in transactions. So the Messenger of Allah ﷺ said: “When you make a sale, say: No deception.” So whenever that man entered into a sale, he would say: “No deception.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":98},{"key":"bukhari","label":"البخاري","number":2117},{"key":"muslim","label":"مسلم","number":1533}]},{"num":5429,"demo":false,"sanad":"","matn":["عن أنس أن رجلاً على عهد رسول اللّٰه ﷺ كان يبتاع، وفي عقدته ضعف، فأتى أهله نبيّ الله ﷺ فقالوا: يا نبي الله، احجر على فلان؛ فإنه يبتاع، وفي عقدته ضعف. فدعاه النبي ﷺ فنهاه عن البيع، فقال: يا نبي الله، إني لا أصبر عن البيع. فقال رسول اللّٰه ﷺ: (( إن كنت غير تارك البيع فقل: هاء وهاء، ولا خلابة ))."],"takhrij":"حسن: رواه أبو داود (٣٥٠١)، وابن الجارود في المنتقى (٥٦٨)، وابن حبان (٥٠٤٩)، وأحمد (١٣٢٧٦).","grade":"حسن","chapter_ar":"باب فيمن يُخدع في البيع والشراء ماذا يقول؟","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3501), Ibn al-Jarud in al-Muntaqa (568), Ibn Hibban (5049), and Ahmad (13276).","chapter_en":"What one who is deceived in buying and selling should say","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Anas narrated that during the time of the Messenger of Allah ﷺ, a man used to buy and sell, but he had weakness in his judgment. His family came to the Prophet ﷺ and said: O Prophet of Allah, restrict so-and-so from trade, because he buys and sells while his judgment is weak. So the Prophet ﷺ called him and forbade him from trading. The man said: O Prophet of Allah, I cannot be patient without trade. So the Messenger of Allah ﷺ said: “If you cannot leave trade, then say: Hand to hand, and no deception.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3501},{"key":"ابن_الجارود/المنتقی","label":"ابن الجارود في المنتقى","number":568},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":6189,"n":6187},{"key":"ahmad","label":"مسند الإمام أحمد","number":13276,"n":13276}]},{"num":5430,"demo":false,"sanad":"","matn":["عن محمد بن يحيى بن حبان قال: هو جدّي منقذ بن عمرو - وكان رجلاً قد أصابته آمَّةٌ في رأسه فكسرت لسانه - وكان لا يدع على ذلك التجارة، وكان لا يزال يُغبن، فأتى النبي ﷺ فذكر ذلك له، فقال له: (( إذا أنت بايعت فقل: لا خلابة، ثم أنت في كل سلعة ابتعتها بالخيار ثلاث ليال، فإن رضيت فأمسك، وإن سخطت فارددها على صاحبها ))."],"takhrij":"حسن: رواه ابن ماجه (٢٣٥٥).","grade":"حسن","chapter_ar":"باب فيمن يُخدع في البيع والشراء ماذا يقول؟","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2355).","chapter_en":"What one who is deceived in buying and selling should say","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Muhammad ibn Yahya ibn Hibban said: He was my grandfather Munqidh ibn Amr — and he was a man who had received an injury to his head which affected his tongue. Even so, he would not leave trade, and he would continually be cheated. So he came to the Prophet ﷺ and mentioned that to him, and he said to him: “When you make a purchase, say: No deception. Then for every item you buy, you have the choice for three nights. If you are pleased, keep it, and if you are displeased, return it to its seller.”"]},"buhuth":{"ar":["وقوله: (( لا خلابة )) أي لا خديعة، يقال: خلبت الرجل إذا خدعته خلباً وخِلابة بكسر الخاء. وفي الحديث دليل على أن المحجور كالصبي لا ينفذ بيعه؛ فإن قول النبي ﷺ له: (( لا خلابة )) بمقام المحجور إذا غبن، وأراد أهله الرجوع عن البيع والشراء. وقول النبي ﷺ: (( قل لا خلابة )) وإن كان خاصاً به، ولكن يقاس عليه كل متخلّف عقلاً. إلا أن أكثر الفقهاء ذهبوا إلى أن العقود بين المتبايعين إذا صدرا عن رضا، وكانا عاقلين غير محجورين، فغبن أحدهما فلا يرجع فيه. ذكر ذلك الخطابي في “المعالم”."],"en":["The phrase “No deception” means no fraud or trickery. In Arabic, khalaba means to deceive someone. This hadith indicates protection for one who is weak in judgment, similar to one under legal restriction. Although this wording was specific to him, others with similar mental weakness may be compared to him. However, most jurists held that when two legally competent people transact willingly, then mere unfairness in price does not by itself allow the contract to be undone. Al-Khattabi mentioned this in al-Ma‘alim."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2355}]},{"num":5431,"demo":false,"sanad":"","matn":["عن حصين بن قيس أنه حمل طعاماً إلى المدينة فلقي رسول اللّٰه ﷺ فقال: (( ماذا تحمل يا أعرابي؟ )). قال: قمحاً. قال: (( ما أردت به أو ما تريد به؟ )). قال: أردت بيعه. فمسح رأسي، وقال: (( أحسنوا مبايعة الأعرابي ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٤/٣٥)، والبزار - كشف الأستار (١٢٧٣).","grade":"حسن","chapter_ar":"باب الإحسان إلى من لا يعرف البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (4/35) and al-Bazzar in Kashf al-Astar (1273).","chapter_en":"Showing kindness to one who does not know buying and selling","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Husayn ibn Qays narrated that he brought food to Madinah and met the Messenger of Allah ﷺ, who said: “What are you carrying, O Bedouin?” He said: Wheat. He said: “What did you intend with it, or what do you want with it?” He said: I intended to sell it. So he wiped my head and said: “Treat the Bedouin well in buying and selling.”"]},"buhuth":{"ar":["قوله: (( أحسنوا مبايعة الأعرابي )) أي لا تغشّوهم لأنهم قليل المعرفة بالأسواق التجارية."],"en":["The phrase “Treat the Bedouin well in buying and selling” means: do not cheat them, because they generally know less about market dealings."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":4},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1273}]},{"num":5432,"demo":false,"sanad":"","matn":["عن المقدام بن معديكرب، عن النبي ﷺ قال: (( كِيلوا طعامكم يبارك لكم ))."],"takhrij":"صحيح: رواه البخاري (٢١٢٨).","grade":"صحيح","chapter_ar":"باب الحثّ على استعمال الكيل لحصول البركة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2128).","chapter_en":"Encouragement to use measurement so that blessing may be attained","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Al-Miqdam ibn Ma‘di Karib narrated from the Prophet ﷺ: “Measure your food, and blessing will be given to you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2128}]},{"num":5433,"demo":false,"sanad":"","matn":["عن عبد الله بن بسر المازني قال: سمعت رسول اللّٰه ﷺ يقول: (( كيلوا طعامكم يبارك لكم فيه ))."],"takhrij":"حسن: رواه ابن ماجه (٢٢٣١).","grade":"حسن","chapter_ar":"باب الحثّ على استعمال الكيل لحصول البركة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2231).","chapter_en":"Encouragement to use measurement so that blessing may be attained","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abdullah ibn Busr al-Mazini said: I heard the Messenger of Allah ﷺ say: “Measure your food, and it will be blessed for you.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2231}]},{"num":5434,"demo":false,"sanad":"","matn":["عن عثمان قال: كنت أبتاع التمر من بطنٍ من اليهود يقال لهم: بنو قينقاع، فأبيعه بربح، فبلغ ذلك رسول اللّٰه ﷺ، فقال: (( يا عثمان، إذا اشتريت فاكتل، وإذا بعت فكل ))."],"takhrij":"حسن: رواه الإمام أحمد (٤٤٤)، وابن ماجه (٢٢٣٠)، وعبد بن حميد (٥٢)، والبيهقي (٥/٣١٥).","grade":"حسن","chapter_ar":"باب الحثّ على استعمال الكيل لحصول البركة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (444), Ibn Majah (2230), Abd ibn Humayd (52), and al-Bayhaqi (5/315).","chapter_en":"Encouragement to use measurement so that blessing may be attained","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Uthman said: I used to buy dates from a group of Jews called Banu Qaynuqa‘, then sell them at a profit. News of that reached the Messenger of Allah ﷺ, and he said: “O Uthman, when you buy, have it measured for you, and when you sell, measure it out.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":444},{"key":"ibnmajah","label":"ابن ماجه","number":2230},{"key":"عبد_بن_حمید","label":"عبد بن حميد","number":52},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":444,"n":444}]},{"num":5435,"demo":false,"sanad":"","matn":["عن ابن عباس قال: لما قدم النبي ﷺ المدينة كانوا من أخبث الناس كيلاً، فأنزل الله سبحانه وتعالى: (وَيْلٌ لِلْمُطَفِّفِينَ) فأحسنوا الكيل بعد ذلك."],"takhrij":"حسن: رواه ابن ماجه (٢٢٢٣)، وابن حبان (٤٩١٩)، والحاكم (٢٢٤٠)، والبيهقي (٦/٣٢).","grade":"حسن","chapter_ar":"باب التوقي في الكيل والميزان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2223), Ibn Hibban (4919), al-Hakim (2240), and al-Bayhaqi (6/32).","chapter_en":"Being careful and just in measurement and weight","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Ibn Abbas said: When the Prophet ﷺ came to Madinah, they were among the worst people in measurement. So Allah, Glorified and Exalted, revealed: “Woe to those who give less in measure,” and after that they improved their measuring."]},"intro":{"ar":["قال الله تعالى: (وَيْلٌ لِلْمُطَفِّفِينَ ١ الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ ٢ وَإِذَا كَالُوهُمْ أَوْ وَزَنُوهُمْ يُخْسِرُونَ) [سورة المطففين: ١-٣].","وقال تعالى: (فَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ) [سورة الأعراف: ٨٥].","وقال تعالى: (وَأَوْفُوا الْكَيْلَ إِذَا كِلْتُمْ وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ) [سورة الإسراء: ٣٥].","وقال تعالى: (وَلَا تَنْقُصُوا الْمِكْيَالَ وَالْمِيزَانَ) [سورة هود: ٨٤]."],"en":["Allah Most High said: “Woe to those who give less in measure, those who, when they take a measure from people, take in full, but when they give by measure or by weight to them, they cause loss.” [Surat al-Mutaffifin, 1–3]","And He said: “So give full measure and weight, and do not deprive people of their things.” [Surat al-A‘raf, 85]","And He said: “Give full measure when you measure, and weigh with a straight balance.” [Surat al-Isra’, 35]","And He said: “Do not reduce the measure and the weight.” [Surat Hud, 84]"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2223},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4321,"n":4317},{"key":"hakim","label":"المستدرك على الصحيحين","number":2240,"n":2232},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11165,"n":11264}]},{"num":5436,"demo":false,"sanad":"","matn":["عن سويد بن قيس قال: جلبت أنا ومخرفة العبدي بزّاً من هجر، فجاءنا النبي ﷺ فساومنا بسراويل، وعندي وزّان يزن بالأجر، فقال النبي ﷺ للوزّان: (( زن، وأرجح ))."],"takhrij":"حسن: رواه أبو داود (٣٣٣٦)، والترمذي (١٣٠٥)، والنسائي (٤٥٩٢)، وابن ماجه (٢٢٢٠)، وأحمد (١٩٠٩٨).","grade":"حسن","chapter_ar":"باب الرجحان في الوزن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3336), al-Tirmidhi (1305), al-Nasa’i (4592), Ibn Majah (2220), and Ahmad (19098).","chapter_en":"Giving extra in weight","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Suwayd ibn Qays said: Makhrafah al-Abdi and I brought cloth from Hajar. The Prophet ﷺ came to bargain with us for some trousers. I had with me a weigher who weighed for payment, and the Prophet ﷺ said to the weigher: “Weigh, and give extra.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3336},{"key":"tirmidhi","label":"الترمذي","number":1305},{"key":"nasai","label":"النسائي","number":4592},{"key":"ibnmajah","label":"ابن ماجه","number":2220},{"key":"ahmad","label":"مسند الإمام أحمد","number":19098,"n":19098}]},{"num":5437,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قال رسول اللّٰه ﷺ: (( إذا وزنتم فأرجحوا ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٢٢٢)، وأبو عوانة (٣/٢٥٥)، والقضاعي في مسند الشهاب (٧٥٩).","grade":"صحيح","chapter_ar":"باب الرجحان في الوزن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2222), Abu Awanah (3/255), and al-Quda‘i in Musnad al-Shihab (759).","chapter_en":"Giving extra in weight","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “When you weigh, then give extra.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2222},{"key":"ابو_عوانہ","label":"أبو عوانة","number":3},{"key":"القضاعی/مسند_الشہاب","label":"القضاعي في مسند الشهاب","number":759}]},{"num":5438,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول اللّٰه ﷺ: (( الوزن وزن أهل مكة، والمكيال مكيال أهل المدينة ))."],"takhrij":"صحيح: رواه أبو داود (٣٣٤٠)، والنسائي (٤٥٩٤، ٢٥٢١)، والبيهقي (٦/٣١)، وعبد بن حميد (٨٠٣).","grade":"صحيح","chapter_ar":"باب الوزن وزن أهل مكة، والمكيال مكيال أهل المدينة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3340), al-Nasa’i (4594, 2521), al-Bayhaqi (6/31), and Abd ibn Humayd (803).","chapter_en":"The standard weight is the weight of the people of Makkah, and the standard measure is the measure of the people of Madinah","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “The standard for weight is the weight of the people of Makkah, and the standard for dry measure is the measure of the people of Madinah.”"]},"buhuth":{"ar":["ومعنى الحديث باختصار أن إخراج الزكاة من الذهب والفضة ينظر إلى ميزان أهل مكة الذي عُدل في عهد عبد الملك بن مروان لما أراد ضرب الدنانير والدراهم، فكان النصاب الذي تجب فيه الزكاة مائتي درهم، وعلى هذا يقاس جميع الدراهم في البلدان المختلفة، وإن كانت أوزانها تختلف من بلد إلى بلد.","وأما ما يتعلق بوجوب الكفارات، وإخراج صدقة الفطر، وتقدير النفقات، وما في معناه، فينظر إلى مكيال أهل المدينة، وهو ما يسمى بالصاع. وصاع أهل المدينة يختلف عن صاع أهل العراق، فصاع أهل المدينة خمسة أرطال وثلث بالعراقي، وصاع أهل العراق ثمانية أرطال.","وأما في المعاملات فيحمل على الصاع المتعارف عند أهل بلده، وإذا كان الأمر يتعلق بالشريعة وأحكامها فهو صاع أهل المدينة."],"en":["The meaning of this hadith, briefly, is that the zakah threshold for gold and silver is judged according to the weight standard of the people of Makkah, which was formalized in the time of Abd al-Malik ibn Marwan when coinage was standardized. Thus, the nisab on silver was two hundred dirhams, and other dirhams in different lands are compared against that standard even if their local weights differ.","As for matters like expiations, the charity of breaking the fast, maintenance amounts, and similar rulings, these are judged according to the measuring standard of the people of Madinah, which is the sa‘. The sa‘ of the people of Madinah differs from the sa‘ of the people of Iraq. The Madinan sa‘ equals five and one-third Iraqi ratls, while the Iraqi sa‘ equals eight ratls.","As for ordinary transactions, the customary local measure of the people of that land is followed. But when the matter concerns Sacred Law and its rulings, then the sa‘ of the people of Madinah is the standard."]},"intro":{"ar":["ومعنى الحديث باختصار أن إخراج الزكاة من الذهب والفضة ينظر إلى ميزان أهل مكة الذي عُدل في عهد عبد الملك بن مروان لما أراد ضرب الدنانير والدراهم، فكان النصاب الذي تجب فيه الزكاة مائتي درهم، وعلى هذا يقاس جميع الدراهم في البلدان المختلفة، وإن كانت أوزانها تختلف من بلد إلى بلد.","وأما ما يتعلق بوجوب الكفارات، وإخراج صدقة الفطر، وتقدير النفقات، وما في معناه، فينظر إلى مكيال أهل المدينة، وهو ما يسمى بالصاع. وصاع أهل المدينة يختلف عن صاع أهل العراق، فصاع أهل المدينة خمسة أرطال وثلث بالعراقي، وصاع أهل العراق ثمانية أرطال.","وأما في المعاملات فيحمل على الصاع المتعارف عند أهل بلده، وإذا كان الأمر يتعلق بالشريعة وأحكامها فهو صاع أهل المدينة."],"en":["The meaning of this hadith, briefly, is that the zakah threshold for gold and silver is judged according to the weight standard of the people of Makkah, which was formalized in the time of Abd al-Malik ibn Marwan when coinage was standardized. Thus, the nisab on silver was two hundred dirhams, and other dirhams in different lands are compared against that standard even if their local weights differ.","As for matters like expiations, the charity of breaking the fast, maintenance amounts, and similar rulings, these are judged according to the measuring standard of the people of Madinah, which is the sa‘. The sa‘ of the people of Madinah differs from the sa‘ of the people of Iraq. The Madinan sa‘ equals five and one-third Iraqi ratls, while the Iraqi sa‘ equals eight ratls.","As for ordinary transactions, the customary local measure of the people of that land is followed. But when the matter concerns Sacred Law and its rulings, then the sa‘ of the people of Madinah is the standard."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3340},{"key":"nasai","label":"النسائي","number":4594},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"عبد_بن_حمید","label":"عبد بن حميد","number":803},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":7717,"n":7780}]},{"num":5439,"demo":false,"sanad":"","matn":["عن حكيم بن حزام قال: قال رسول اللّٰه ﷺ: (( البيعان بالخيار ما لم يتفرقا - أو قال: حتى يتفرقا -، فإن صدقا، وبينا بورك لهما في بيعهما، وإن كتما، وكذبا محقت بركة بيعهما ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٧٩)، ومسلم (٤٧ :١٥٣٢).","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2079) and Muslim (1532:47).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Hakim ibn Hizam said: The Messenger of Allah ﷺ said: “The buyer and seller retain the choice so long as they have not separated — or he said: until they separate. If they are truthful and clear, their sale will be blessed for them. But if they conceal and lie, the blessing of their sale will be erased.”"]},"intro":{"ar":["فقه الباب: يستفاد من هذه الأحاديث بأن المراد بالتفرق هو التفرق بالأبدان، كما فهمه ابن عمر، وابن عباس، وغيرهما."],"en":["Understanding of this section: These hadiths indicate that the intended meaning of separation is physical separation of the bodies, as understood by Ibn Umar, Ibn Abbas, and others."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2079},{"key":"muslim","label":"مسلم","number":47}]},{"num":5440,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر أن رسول اللّٰه ﷺ قال: (( المتبايعان كل واحد منهما بالخيار على صاحبه ما لم يتفرقا إلا بيع الخيار ))."],"takhrij":"متفق عليه: رواه مالك (٧٩) والبخاري (٢١١١)، ومسلم (٤٣:١٥٣١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (79), al-Bukhari (2111), and Muslim (1531:43).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Umar narrated that the Messenger of Allah ﷺ said: “The two parties to a sale each retain the option against the other as long as they have not separated, except in a sale with an agreed option.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":79},{"key":"bukhari","label":"البخاري","number":2111},{"key":"muslim","label":"مسلم","number":43}]},{"num":5441,"demo":false,"sanad":"","matn":["عن ابن عمر، عن رسول اللّٰه ﷺ أنه قال: (( إذا تبايع الرجلان فكل واحد منهما بالخيار ما لم يتفرقا، وكانا جميعاً، أو يخير أحدهما الآخر، فتبايعا على ذلك، فقد وجب البيع. وإن تفرقا بعد أن يتبايعا، ولم يترك واحد منهما البيع فقد وجب البيع ))."],"takhrij":"متفق عليه: رواه البخاري (٢١١٢)، ومسلم (٤٤ :١٥٣١). ورواه مسلم (٤٥ :١٥٣١) من طريق آخر وزاد: قال نافع: فكان - يعني ابن عمر - إذا بايع رجلاً، فأراد أن لا يُقيله قام فمشى هنيهة، ثم رجع إليه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2112) and Muslim (1531:44). Muslim also narrated it (1531:45) through another route and added: Nafi‘ said: Ibn Umar, when he sold to a man and wanted not to revoke the sale, would stand up, walk a short distance, then return to him.","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ said: “When two men conduct a sale, each of them retains the option as long as they have not separated while they are together, unless one of them gives the other the choice and they transact on that basis, in which case the sale becomes binding. And if they separate after the sale and neither of them has cancelled it, then the sale becomes binding.”"]},"buhuth":{"ar":["وفيه دليل على أن ابن عمر كان يرى أن المراد بالتفرق هو التفرق بالأبدان، لا بالأقوال."],"en":["This indicates that Ibn Umar understood “separation” to mean physical separation of bodies, not merely separation in speech."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2112},{"key":"muslim","label":"مسلم","number":44},{"key":"ورواہ_مسلم","label":". ورواه مسلم","number":45}]},{"num":5442,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال النبي ﷺ: (( البيعان بالخيار ما لم يتفرقا، أو يقول أحدهما لصاحبه: اختر، وربما قال: أو يكون بيع خيار ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٠٩) ومسلم (٤٧ :١٥٣١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2109) and Muslim (1531:47).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn Umar said: The Prophet ﷺ said: “The buyer and seller retain the choice as long as they have not separated, unless one of them says to the other: Choose, or it is a sale with an agreed option.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2109},{"key":"muslim","label":"مسلم","number":47}]},{"num":5443,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: بعتُ من أمير المؤمنين عثمان بن عفان رضي الله عنه مالاً بالوادي بمال له بخيبر، فلما تبايعنا رجعت على عقبي حتى خرجت من بيته خشية أن يُرادّني البيع، وكانت السنة أن المتبايعين بالخيار حتى يتفرقا.","قال عبد الله: فلما وجب بيعي وبيعه رأيت أني قد غبنته بأني سُقته إلى أرض ثمود بثلاث ليال، وساقني إلى المدينة بثلاث ليال.","صحيح على البخاري، وقال الحافظ ابن حجر: وصله الإسماعيلي، والبيهقي (٥/٣٧١).","وقوله: (( مالاً )) أي أرضاً أو عقاراً."],"takhrij":"","grade":"","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic according to the standard of al-Bukhari. Ibn Hajar said: al-Isma‘ili connected its chain, and al-Bayhaqi narrated it (5/371).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Umar said: I sold to the Commander of the Believers Uthman ibn Affan, may Allah be pleased with him, some property in the valley in exchange for property of his in Khaybar. When we completed the sale, I walked backward until I exited his house, fearing that he might wish to revoke the sale, because the established practice was that the two parties to a sale retained the option until they physically separated.","Abdullah said: When my sale and his sale became binding, I thought that I had actually gotten the better of him, because I had led him to land in Thamud, three nights away, while he had led me to Madinah, three nights away."]},"buhuth":{"en":["The word “property” here means land or real estate."]}},"tuhfa":{},"refs":[]},{"num":5444,"demo":false,"sanad":"","matn":["عن ابن عباس، وابن عمر، عن النبي ﷺ قال: (( من ابتاع بيعاً فوجب له فهو فيه بالخيار على صاحبه ما لم يفارقه، إن شاء أخذ، وإن شاء ترك. فإن فارقه فلا خيار له ))."],"takhrij":"حسن: رواه ابن حبان (٤٩١٥، ٤٩١٤)، والحاكم (٢/١٤)، والبيهقي (٥/٢٧٠).","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4914, 4915), al-Hakim (2/14), and al-Bayhaqi (5/270).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Ibn Abbas and Ibn Umar narrated from the Prophet ﷺ that he said: “Whoever purchases something and the deal is concluded for him still retains the option against the other party so long as he has not parted from him. If he wishes, he may take it, and if he wishes, he may leave it. But once he parts from him, he no longer has that option.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":2},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4060,"n":4056}]},{"num":5445,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص أن رسول اللّٰه ﷺ قال: (( المتبايعان بالخيار ما لم يتفرقا إلا أن تكون صفقة خيار، ولا يحل له أن يفارق صاحبه خشية أن يستقيله ))."],"takhrij":"حسن: رواه أبو داود (٣٤٥٦)، والترمذي (١٢٤٧) وحسّنه، والنسائي (٤٤٨٢)، وأحمد (٦٧٢١).","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3456), al-Tirmidhi (1247), who graded it Hasan, al-Nasa’i (4482), and Ahmad (6721).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As narrated that the Messenger of Allah ﷺ said: “The buyer and seller retain the option as long as they have not separated, unless it is a sale with an agreed option. And it is not lawful for one of them to part from the other out of fear that he may ask to revoke the sale.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3456},{"key":"tirmidhi","label":"الترمذي","number":1247},{"key":"nasai","label":"النسائي","number":4482},{"key":"ahmad","label":"مسند الإمام أحمد","number":6721,"n":6721}]},{"num":5446,"demo":false,"sanad":"","matn":["عن سمرة بن جندب قال: قال رسول اللّٰه ﷺ: (( البيعان بالخيار ما لم يتفرقا ))."],"takhrij":"صحيح: رواه ابن ماجه (٢١٨٣) وأحمد (٢٠٢٤١)، والنسائي (٤٤٨١-٤٤٨٢)، والبيهقي (٥/٢٧١).","grade":"صحيح","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2183), Ahmad (20241), al-Nasa’i (4481–4482), and al-Bayhaqi (5/271).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “The buyer and seller retain the option as long as they have not separated.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2183},{"key":"nasai","label":"النسائي","number":4481},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":20241,"n":20241}]},{"num":5447,"demo":false,"sanad":"","matn":["عن أبي برزة أن رسول اللّٰه ﷺ قال: (( البيعان بالخيار ما لم يتفرقا ))."],"takhrij":"صحيح: رواه أبو داود (٣٤٥٧)، وابن ماجه (٢١٨٢)، وأحمد (١٩٨١٣).","grade":"صحيح","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3457), Ibn Majah (2182), and Ahmad (19813).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Barzah narrated that the Messenger of Allah ﷺ said: “The buyer and seller retain the option as long as they have not separated.”"]},"buhuth":{"ar":["وذكر أبو داود قصة، فقال: غزونا غزوة لنا، فنزلنا منزلاً، فباع صاحب لنا فرساً بغلام، ثم أقاما بقية يومهما وليلتهما، فلما أصبحا من الغد حضر الرحيل، فقام إلى فرسه يسرجه، فندم، فأتى الرجل وأخذه بالبيع، فأبى الرجل أن يدفعه إليه، فقال: بيني وبينك أبو برزة صاحب النبي ﷺ. فأتيا أبا برزة في ناحية العسكر، فقالا له هذه القصة، فقال: أترضيان أن أقضي بينكما بقضاء رسول الله ﷺ؟ فذكر الحديث. وإسناده صحيح."],"en":["Abu Dawud also mentioned a story: We were on a military expedition and stopped at a camp. One of our companions sold a horse for a slave. They remained for the rest of that day and night. When morning came and departure time arrived, the seller stood to saddle his horse and regretted the sale. He came to the man and demanded the sale be undone, but the man refused to return it. So he said: Let Abu Barzah, a companion of the Prophet ﷺ, judge between us. They came to Abu Barzah in one corner of the camp and told him the story. He said: Are you both satisfied that I judge between you with the judgment of the Messenger of Allah ﷺ? Then he mentioned this hadith. Its chain is authentic."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3457},{"key":"ibnmajah","label":"ابن ماجه","number":2182},{"key":"ahmad","label":"مسند الإمام أحمد","number":19813,"n":19813}]},{"num":5448,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن النبي ﷺ خيّر أعرابياً بعد البيع."],"takhrij":"حسن: رواه الترمذي (١٢٤٩)، وابن ماجه (٢١٨٤)، والحاكم (٢/٤٨-٤٩)، واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1249), Ibn Majah (2184), and al-Hakim (2/48–49). This is the wording of al-Tirmidhi.","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Prophet ﷺ gave a Bedouin the choice after the sale."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1249},{"key":"ibnmajah","label":"ابن ماجه","number":2184},{"key":"hakim","label":"الحاكم","number":2}]},{"num":5449,"demo":false,"sanad":"","matn":["عن أبي هريرة يقول: قال رسول اللّٰه ﷺ: (( لا يفترقن اثنان إلا عن تراض ))."],"takhrij":"حسن: رواه أبو داود (٣٤٥٨)، والترمذي (١٢٤٨)، والبيهقي (٥/٢٧١).","grade":"حسن","chapter_ar":"باب ما جاء في خيار المجلس للمتبايعين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3458), al-Tirmidhi (1248), and al-Bayhaqi (5/271).","chapter_en":"What has come regarding the option of the session for the buyer and seller","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Two people should not part except upon mutual satisfaction.”"]},"buhuth":{"ar":["فقه الباب: يستفاد من هذه الأحاديث بأن المراد بالتفرق هو التفرق بالأبدان، كما فهمه ابن عمر، وابن عباس، وغيرهما."],"en":["Understanding of this section: These hadiths indicate that the intended meaning of separation is physical separation of the bodies, as understood by Ibn Umar, Ibn Abbas, and others."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3458},{"key":"tirmidhi","label":"الترمذي","number":1248},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10446,"n":10534}]},{"num":5450,"demo":false,"sanad":"","matn":["عن عبد المجيد بن وهب قال: قال لي العداء بن خالد بن هوذة: ألا أقرئك كتاباً كتبه لي رسول اللّٰه ﷺ؟ قال: قلت: بلى. فأخرج إلي كتاباً: (( هذا ما اشترى العداء بن خالد بن هوذة من محمد رسول اللّٰه ﷺ، اشترى منه عبداً أو أمة، لا داء، ولا غائلة، ولا خَبْثَة، بيع المسلم للمسلم ))."],"takhrij":"حسن: رواه الترمذي (١٢١٦)، وابن ماجه (٢٢٥١)، والبيهقي (٣٢٧/٥).","grade":"حسن","chapter_ar":"باب ما جاء في البيع على البراءة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1216), Ibn Majah (2251), and al-Bayhaqi (5/327).","chapter_en":"What has come regarding sale on disclaimer","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abd al-Majid ibn Wahb said: Al-‘Adda’ ibn Khalid ibn Hawdhah said to me: Shall I read to you a document that the Messenger of Allah ﷺ wrote for me? I said: Yes. So he brought out a document for me which read: “This is what al-‘Adda’ ibn Khalid ibn Hawdhah purchased from Muhammad, the Messenger of Allah ﷺ. He purchased from him a male slave or a female slave, free of disease, free of concealed defect, and free of bad conduct — the sale of one Muslim to another Muslim.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1216},{"key":"ibnmajah","label":"ابن ماجه","number":2251},{"key":"البیہقی","label":"البيهقي","number":327},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10782,"n":10874}]},{"num":5451,"demo":false,"sanad":"","matn":["عن ابن عمر قال: كنا مع النبي ﷺ في سفر، فكنت على بكر صعب لعمر، فكان يغلبني، فيتقدم أمام القوم، فيزجره عمر ويرده، ثم يتقدم فيزجره عمر ويرده. فقال النبي ﷺ لعمر: (( بعنيه )). قال: هو لك يا رسول الله. فقال رسول اللّٰه ﷺ: (( بعنيه )). فباعه من رسول اللّٰه ﷺ، فقال النبي ﷺ: (( هو لك يا عبد الله بن عمر، تصنع به ما شئت ))."],"takhrij":"صحيح: رواه البخاري (٢١١٥) و(٢٦١٠).","grade":"صحيح","chapter_ar":"باب إذا اشترى شيئاً فوهبه من ساعته قبل أن يتفرق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2115) and (2610).","chapter_en":"If someone buys something, then gifts it immediately before the two parties separate","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Ibn Umar said: We were with the Prophet ﷺ on a journey, and I was riding a difficult young camel that belonged to Umar. It kept overpowering me and moving ahead of the people, so Umar would scold it and bring it back. Then it would go forward again, and Umar would scold it and bring it back again. So the Prophet ﷺ said to Umar: “Sell it to me.” Umar said: It is yours, O Messenger of Allah ﷺ. But the Messenger of Allah ﷺ said: “Sell it to me.” So he sold it to the Messenger of Allah ﷺ. Then the Prophet ﷺ said: “It is yours, O Abdullah ibn Umar. Do with it whatever you wish.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2115},{"key":"و","label":"و","number":2610}]},{"num":5452,"demo":false,"sanad":"","matn":["عن أنس قال: قال النبي ﷺ: (( يا بني النجار، ثامنوني بحائطكم، وفيه خِرَب ونخل ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٠٦)، ومسلم (٥٢٤:٩). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب صاحب السلعة أحق بالتثمين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2106) and Muslim (524:9). The wording is that of al-Bukhari.","chapter_en":"The owner of the merchandise has the greater right to set the price","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Anas said: The Prophet ﷺ said: “O Banu al-Najjar, name a price for your garden,” and in it were ruined areas and date-palms."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2106},{"key":"muslim","label":"مسلم","number":524}]},{"num":5453,"demo":false,"sanad":"","matn":["عن ابن عمر أن عائشة رضي اللّٰه عنها ساومت بريرة، فخرج النبي ﷺ إلى الصلاة، فلما جاء قالت: إنهم أبوا أن يبيعوها إلا أن يشترطوا الولاء. فقال النبي ﷺ: (( إنما الولاء لمن أعتق )). قلت لنافع: حراً كان زوجها أو عبداً؟ فقال: ما يدريني."],"takhrij":"صحيح: رواه البخاري (٢١٥٦).","grade":"صحيح","chapter_ar":"باب البيع والشراء مع النساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2156).","chapter_en":"Buying and selling with women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Ibn Umar narrated that Aisha, may Allah be pleased with her, bargained for Barirah. Then the Prophet ﷺ went out for prayer, and when he returned she said: They refused to sell her unless they stipulated the right of wala’. So the Prophet ﷺ said: “The right of wala’ belongs only to the one who frees.” I said to Nafi‘: Was her husband free or a slave? He said: How would I know?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2156}]},{"num":5454,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن أبي بكر قال: كنا مع النبي ﷺ، ثم جاء رجل مشرك مُشعان طويل بغنم يسوقها، فقال النبي ﷺ: (( بيعاً أم عطية — أو قال — أم هبة؟ )). قال: لا، بل بيع، فاشترى منه شاة."],"takhrij":"صحيح: رواه البخاري (٢٢١٦).","grade":"صحيح","chapter_ar":"باب البيع والشراء مع المشركين، وأهل الحرب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2216).","chapter_en":"Buying and selling with polytheists and people at war","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Abd al-Rahman ibn Abi Bakr said: We were with the Prophet ﷺ when a tall, disheveled polytheist came driving some sheep. The Prophet ﷺ said: “Is it for sale, or a gift — or did he say — or a donation?” He said: No, rather it is a sale. So he bought a sheep from him."]},"buhuth":{"ar":["قوله: (( مُشعان )) أي طويل شعث الرأس.","قال ابن بطال: معاملة الكفار جائزة إلا بيع ما يستعين به أهل الحرب على المسلمين."],"en":["The word “mush‘an” means tall and disheveled in hair.","Ibn Battal said: Dealing with disbelievers is permissible, except selling them what the people of war would use against the Muslims."]},"intro":{"ar":["قوله: (( مُشعان )) أي طويل شعث الرأس.","قال ابن بطال: معاملة الكفار جائزة إلا بيع ما يستعين به أهل الحرب على المسلمين."],"en":["The word “mush‘an” means tall and disheveled in hair.","Ibn Battal said: Dealing with disbelievers is permissible, except selling them what the people of war would use against the Muslims."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2216}]},{"num":5455,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن رجلاً أعتق غلاماً له عن دبر، فاحتاج، فأخذه النبي ﷺ، قال: (( من يشتريه مني؟ )). فاشتراه نعيم بن عبد الله بكذا وكذا، فدفعه إليه."],"takhrij":"متفق عليه: رواه البخاري (٢١٤١)، ومسلم (٩٩٧).","grade":"متفق عليه","chapter_ar":"باب بيع المدبر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2141) and Muslim (997).","chapter_en":"Selling a slave who was declared to be freed after the owner’s death","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that a man declared his slave to be freed after his death, but then he fell into need. So the Prophet ﷺ took him and said: “Who will buy him from me?” Nu‘aym ibn Abdullah bought him for such-and-such an amount, and the Prophet ﷺ handed him over to him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2141},{"key":"muslim","label":"مسلم","number":997}]},{"num":5456,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال النبي ﷺ: (( إذا زنت الأمة فتبين زناها فليجلدها ولا يُثَرّب، ثم إن زنت فليجلدها ولا يُثَرّب، ثم إن زنت الثالثة فليبعها ولو بحبل من شعر ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٥٢)، ومسلم (١٧٠٣).","grade":"متفق عليه","chapter_ar":"باب بيع الأمة الزانية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2152) and Muslim (1703).","chapter_en":"Selling a slave-woman who commits fornication","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “If a slave-woman commits fornication and her fornication becomes clear, then let her be flogged and not rebuked. Then if she commits fornication again, let her be flogged and not rebuked. Then if she commits fornication a third time, let her be sold, even for a rope of hair.”"]},"buhuth":{"ar":["وقوله: (( فليبعها )) أي مع بيان عيبها؛ لأن كتمان العيوب لا يجوز من عموم الأدلة."],"en":["The phrase “then let her be sold” means while making her defect known, because concealing defects is not allowed according to the general evidence."]},"intro":{"ar":["وقوله: (( فليبعها )) أي مع بيان عيبها؛ لأن كتمان العيوب لا يجوز من عموم الأدلة."],"en":["The phrase “then let her be sold” means while making her defect known, because concealing defects is not allowed according to the general evidence."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2152},{"key":"muslim","label":"مسلم","number":1703}]},{"num":5457,"demo":false,"sanad":"","matn":["عن أبي هريرة، وزيد بن خالد الجهني أن رسول اللّٰه ﷺ سئل عن الأمة إذا زنت، ولم تُحصن؟ قال: (( إن زنت فاجلدوها، ثم إن زنت فاجلدوها، ثم إن زنت فاجلدوها، ثم بيعوها ولو بضفير )). قال ابن شهاب الزهري: لا أدري أبعد الثالثة، أو الرابعة."],"takhrij":"متفق عليه: رواه مالك (١٤) والبخاري (٢١٥٤)، ومسلم (١٧٠٤).","grade":"متفق عليه","chapter_ar":"باب بيع الأمة الزانية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), al-Bukhari (2154), and Muslim (1704).","chapter_en":"Selling a slave-woman who commits fornication","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah and Zayd ibn Khalid al-Juhani narrated that the Messenger of Allah ﷺ was asked about a slave-woman if she committed fornication before being married. He said: “If she commits fornication, then flog her. Then if she commits fornication, flog her. Then if she commits fornication, flog her. Then sell her, even for a braided rope.” Ibn Shihab al-Zuhri said: I do not know whether that was after the third or the fourth time."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14},{"key":"bukhari","label":"البخاري","number":2154},{"key":"muslim","label":"مسلم","number":1704}]},{"num":5458,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: إن خياطاً دعا رسول اللّٰه ﷺ لطعام صنعه. قال أنس: ذهبت مع رسول اللّٰه ﷺ إلى ذلك الطعام، فقرب إليه خبزاً من شعير ومرقاً فيه دباء وقديد.","قال أنس: فرأيت النبي ﷺ يتتبع الدباء من حوالي القصعة، فلم أزل أحب الدباء بعد ذلك اليوم."],"takhrij":"متفق عليه: رواه مالك (٥١) والبخاري (٢٠٩٢)، ومسلم (٢٠٤١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الخياطة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (51), al-Bukhari (2092), and Muslim (2041).","chapter_en":"What has come regarding the profession of tailoring","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Malik said: A tailor invited the Messenger of Allah ﷺ to food he had prepared. Anas said: I went with the Messenger of Allah ﷺ to that meal. He presented to him barley bread and broth containing gourd and dried meat.","Anas said: I saw the Prophet ﷺ picking out the gourd from around the dish, and I have loved gourd ever since that day."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":51},{"key":"bukhari","label":"البخاري","number":2092},{"key":"muslim","label":"مسلم","number":2041}]},{"num":5459,"demo":false,"sanad":"","matn":["عن سهل بن سعد قال:","جاءت امرأة ببردة. قال: أتدرون ما البردة؟ فقيل له: نعم، هي الشملة منسوج في حاشيتها.","قالت:","يا رسول الله، إني نسجت هذه بيدي أكسوكها.","فأخذها النبي ﷺ محتاجًا إليها، فخرج إلينا وإنها إزاره.","فقال رجل من القوم:","يا رسول الله، اكسنيها.","فقال:","«نَعَمْ».","فجلس النبي ﷺ في المجلس، ثم رجع، فطواها، ثم أرسل بها إليه.","فقال له القوم:","ما أحسنت، سألتها إياه وقد علمت أنه لا يرد سائلًا.","فقال الرجل:","والله ما سألته إلا لتكون كفني يوم أموت.","قال سهل:","فكانت كفنه."],"takhrij":"صحيح: رواه البخاري (٢٠٩٣).","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة النساجة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2093).","chapter_en":"What has come regarding the profession of weaving","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Sahl ibn Saʿd reported:","A woman brought a mantle. He said, “Do you know what a burdah is?” They replied, “Yes, it is a wrap woven with a border.”","She said:","“O Messenger of Allah ﷺ, I wove this with my own hands so that I could clothe you with it.”","The Prophet ﷺ took it because he was in need of it, and later came out to us wearing it as his lower garment.","A man among the people said:","“O Messenger of Allah ﷺ, give it to me to wear.”","He replied:","“Yes.”","The Prophet ﷺ remained seated in the gathering for a while, then returned, folded the garment, and sent it to the man.","The people said to him:","“You did not do well. You asked him for it even though you knew that he never turns away anyone who asks him.”","The man replied:","“By Allah, I only asked him for it so that it might be my shroud on the day I die.”","Sahl said:","And it became his shroud."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2093}]},{"num":5460,"demo":false,"sanad":"","matn":["عن أبي حازم قال:","أتى رجال إلى سهل بن سعد يسألونه عن المنبر، فقال:","بعث رسول الله ﷺ إلى فلانة - امرأة قد سماها سهل -:","«أَنْ مُرِي غُلَامَكِ النَّجَّارَ يَعْمَلْ لِي أَعْوَادًا أَجْلِسُ عَلَيْهِنَّ إِذَا كَلَّمْتُ النَّاسَ».","فأمرته يعملها من طرفاء الغابة، ثم جاء بها، فأرسلت إلى رسول الله ﷺ بها، فأمر بها فوضعت، فجلس عليه."],"takhrij":"متفق عليه: رواه البخاري (٢٠٩٤)، ومسلم (٥٤٤)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة النجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2094) and Muslim (544). This is the wording of al-Bukhārī.","chapter_en":"What has come regarding the profession of carpentry","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Abū Ḥāzim reported:","Some men came to Sahl ibn Saʿd asking him about the pulpit. He said:","The Messenger of Allah ﷺ sent word to a certain woman, whom Sahl named:","“Tell your carpenter servant to make some pieces of wood for me upon which I can sit when I address the people.”","She instructed him to do so, and he made it from tamarisk wood from al-Ghābah. He then brought it, and she sent it to the Messenger of Allah ﷺ.","He ordered that it be placed in position, and he sat upon it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2094},{"key":"muslim","label":"مسلم","number":544}]},{"num":5461,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن امرأة من الأنصار قالت لرسول اللّٰه ﷺ: يا رسول الله، ألا أجعل لك شيئاً تقعد عليه، فإن لي غلاماً نجاراً؟ قال: (( إن شئتِ )). قال: فعملت له المنبر… الحديث"],"takhrij":"صحيح: رواه البخاري (٢٠٩٥).","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة النجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2095).","chapter_en":"What has come regarding the profession of carpentry","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that a woman from the Ansar said to the Messenger of Allah ﷺ: O Messenger of Allah ﷺ, shall I make something for you to sit upon, for I have a servant who is a carpenter? He said: “If you wish.” So she made the pulpit for him…"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2095}]},{"num":5462,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( كان زكريا نجاراً ))."],"takhrij":"صحيح: رواه مسلم (٢٣٧٩).","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة النجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2379).","chapter_en":"What has come regarding the profession of carpentry","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Zakariyya was a carpenter.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2379}]},{"num":5463,"demo":false,"sanad":"","matn":["عن خباب قال: كنت قيناً في الجاهلية، وكان لي على العاص بن وائل دين، فأتيته أتقاضاه. قال: لا أعطيك حتى تكفر بمحمد. فقلت: لا أكفر حتى يميتك الله، ثم تبعث. قال: دعني حتى أموت وأبعث، فسأوتى مالاً وولداً فأقضيك، فنزلت: (أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لَأُوتَيَنَّ مَالًا وَوَلَدًا ۝ أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِندَ الرَّحْمَنِ عَهْدًا) [سورة مريم: ٧٧-٧٨]."],"takhrij":"متفق عليه: رواه البخاري (٢٠٩١)، ومسلم (٢٧٩٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الحدادة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2091) and Muslim (2795).","chapter_en":"What has come regarding the profession of blacksmithing","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Khabbab said: I was a blacksmith in the time of ignorance, and al-‘As ibn Wa’il owed me a debt. I came to him to demand it. He said: I will not pay you until you disbelieve in Muhammad. So I said: I will not disbelieve until Allah causes you to die and then resurrects you. He said: Leave me until I die and am resurrected, and then I will be given wealth and children, and I will repay you. Then this was revealed: “Have you seen the one who disbelieved in Our signs and said: I will surely be given wealth and children? Has he looked into the unseen, or has he taken a covenant with the Most Merciful?” [Surat Maryam, 77–78]"]},"buhuth":{"ar":["قوله: (( كنت قيناً )) قال ابن دريد: أصل القين الحداد، ثم صار كل صائغ عند العرب قيناً. وقال الزجاج: القين الذي يصلح الأسنة، والقين أيضاً الحداد."],"en":["The phrase “I was a qayn” means: I was a blacksmith. Ibn Durayd said: the original meaning of qayn is blacksmith, then it later came to be used among the Arabs for any craftsman of metalwork. Al-Zajjaj said: a qayn is one who repairs spearheads, and also a blacksmith."]},"intro":{"ar":["قوله: (( كنت قيناً )) قال ابن دريد: أصل القين الحداد، ثم صار كل صائغ عند العرب قيناً. وقال الزجاج: القين الذي يصلح الأسنة، والقين أيضاً الحداد."],"en":["The phrase “I was a qayn” means: I was a blacksmith. Ibn Durayd said: the original meaning of qayn is blacksmith, then it later came to be used among the Arabs for any craftsman of metalwork. Al-Zajjaj said: a qayn is one who repairs spearheads, and also a blacksmith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2091},{"key":"muslim","label":"مسلم","number":2795}]},{"num":5464,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري قال: قال رسول اللّٰه ﷺ: (( مثل الجليس الصالح والجليس السوء كمثل صاحب المسك وكير الحداد، لا يعدمك من صاحب المسك: إما تشتريه، أو تجد ريحه. وكير الحداد يحرق بدنك أو ثوبك، أو تجد منه ريحاً خبيثة ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٠١)، ومسلم (٢٦٢٨).","grade":"متفق عليه","chapter_ar":"باب ما جاء في العطارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2101) and Muslim (2628).","chapter_en":"What has come regarding the perfume trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said: “The example of a righteous companion and an evil companion is like the seller of musk and the blacksmith’s bellows. From the seller of musk, you will at least not miss one of these: either you buy from him, or you enjoy his fragrance. But the blacksmith’s bellows may burn your body or your clothes, or you will find from it a foul smell.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2101},{"key":"muslim","label":"مسلم","number":2628}]},{"num":5465,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: كانت لي شارف من نصيبي من المغنم، وكان النبي ﷺ أعطاني شارفاً من الخمس، فلما أردت أن أبتني بفاطمة بنت رسول اللّٰه ﷺ واعدت رجلاً صواغاً من بني قينقاع أن يرتحل معي فنأتي بإذخر أردت أن أبيعه من الصواغين، وأستعين به في وليمة عرسي."],"takhrij":"متفق عليه: رواه البخاري (٢٠٨٩)، ومسلم (١٩٧٩).","grade":"متفق عليه","chapter_ar":"باب ما جاء في مهنة الصياغة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2089) and Muslim (1979).","chapter_en":"What has come regarding the profession of goldsmithing","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["Ali ibn Abi Talib said: I had a she-camel from my share of the war booty, and the Prophet ﷺ had also given me a she-camel from the khums. When I intended to marry Fatimah, the daughter of the Messenger of Allah ﷺ, I made an arrangement with a goldsmith from Banu Qaynuqa‘ to travel with me so that we could bring idhkhir grass. I intended to sell it to the goldsmiths and use the proceeds to help with the wedding feast of my marriage."]},"buhuth":{"ar":["قوله: (( رجلاً صواغاً )) وفي مسلم: (( ومعي صائغ )). والصائغ من حرفته الصياغة، وهي عمل الحلي من فضة وذهب ونحوهما."],"en":["The phrase “a goldsmith” means one whose trade is working jewelry from silver, gold, and the like."]},"intro":{"ar":["قوله: (( رجلاً صواغاً )) وفي مسلم: (( ومعي صائغ )). والصائغ من حرفته الصياغة، وهي عمل الحلي من فضة وذهب ونحوهما."],"en":["The phrase “a goldsmith” means one whose trade is working jewelry from silver, gold, and the like."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2089},{"key":"muslim","label":"مسلم","number":1979}]},{"num":5466,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: احتجم رسول اللّٰه ﷺ، حجمه أبو طيبة، فأمر له رسول اللّٰه ﷺ بصاع من تمر، وأمر أهله أن يخففوا عنه من خراجه."],"takhrij":"صحيح: رواه مالك (٢٦) والبخاري (٢١٠٢) ومسلم (٦٤:١٥٧٧).","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة الحجامة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (26), al-Bukhari (2102), and Muslim (1577:64).","chapter_en":"What has come regarding the profession of cupping","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ underwent cupping, and Abu Taybah performed the cupping for him. So the Messenger of Allah ﷺ ordered that he be given one sa‘ of dates, and he ordered his masters to reduce the amount of tax or earnings they required from him."]},"buhuth":{"ar":["ورواه مسلم (٦٢) من طريق آخر عن حميد قال: سئل أنس بن مالك عن كسب الحجام؟ فقال: احتجم رسول اللّٰه ﷺ، حجمه أبو طيبة، فأمر له بصاعين من طعام، وكلم أهله، فوضعوا عنه من خراجه، وقال: (( إن أفضل ما تداويتم به الحجامة، أو هو من أمثل دوائكم ))."],"en":["Muslim also narrated it (1577:62) through another route from Humayd, who said: Anas ibn Malik was asked about the earnings of the cupper, and he said: The Messenger of Allah ﷺ underwent cupping, and Abu Taybah cupped him. He ordered that he be given two sa‘s of food, spoke to his masters, and they reduced his dues. He also said: “Among the best treatments you use is cupping,” or “it is among the best of your remedies.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":26},{"key":"bukhari","label":"البخاري","number":2102},{"key":"muslim","label":"مسلم","number":64}]},{"num":5467,"demo":false,"sanad":"","matn":["عن ابن عباس قال: احتجم النبي ﷺ، وأعطى الذي حجمه، ولو كان حراماً لم يعطه."],"takhrij":"صحيح: رواه البخاري (٢١٠٣)، ومسلم (٦٥:١٢٠٢).","grade":"صحيح","chapter_ar":"باب ما جاء في مهنة الحجامة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2103) and Muslim (1202:65).","chapter_en":"What has come regarding the profession of cupping","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Ibn Abbas said: The Prophet ﷺ underwent cupping and gave payment to the one who cupped him. If it had been unlawful, he would not have paid him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2103},{"key":"muslim","label":"مسلم","number":65}]},{"num":5468,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، عن رسول اللّٰه ﷺ أنه قال: (( بينما ثلاثة نفر يتمشون أخذهم المطر، فأووا إلى غار في جبل، فانحطت على فم غارهم صخرة من الجبل، فانطبقت عليهم، فقال بعضهم لبعض: انظروا أعمالاً عملتموها صالحة لله، فادعوا اللّٰه تعالى بها، لعل اللّٰه يفرجها عنكم.","فقال أحدهم: اللهم إنه كان لي والدان شيخان كبيران، وامرأتي، ولي صبية صغار أرعى عليهم، فإذا أرحت عليهم حلبت، فبدأت بوالديّ، فسقيتهما قبل بنيّ، وأنه نأى بي ذات يوم الشجر، فلم آت حتى أمسيت، فوجدتهما قد ناما، فحلبت كما كنت أحلب، فجئت بالحلاب، فقمت عند رؤوسهما أكره أن أوقظهما من نومهما، وأكره أن أسقي الصبية قبلهما، والصبية يتضاغون عند قدمي، فلم يزل ذلك دأبي ودأبهم حتى طلع الفجر، فإن كنت تعلم أني فعلت ذلك ابتغاء وجهك فافرج لنا منها فرجة نرى منها السماء. ففرج اللّٰه منها فرجة، فرأوا منها السماء.","وقال الآخر: اللهم إنه كانت لي ابنة عم أحببتها كأشد ما يحب الرجال النساء، وطلبت إليها نفسها فأبت حتى آتيها بمائة دينار، فتعبت حتى جمعت مائة دينار، فجئتها بها، فلما وقعت بين رجليها قالت: يا عبد الله، اتق الله، ولا تفتح الخاتم إلا بحقه، فقمت عنها، فإن كنت تعلم أني فعلت ذلك ابتغاء وجهك فافرج لنا منها فرجة، ففرج لهم.","وقال الآخر: اللهم إني كنت استأجرت أجيراً بفرق أرز، فلما قضى عمله قال: أعطني حقي، فعرضت عليه فرقه، فرغب عنه. فلم أزل أزرعه حتى جمعت منه بقراً ورعاءها، فجاءني، فقال: اتق الله، ولا تظلمني حقي. قلت: اذهب إلى تلك البقر ورعائها فخذها. فقال: اتق الله، ولا تستهزئ بي. قلت: إني لا أستهزئ بك، خذ ذلك البقر ورعاءها، فأخذه، فذهب به، فإن كنت تعلم أني فعلت ذلك ابتغاء وجهك، فافرج لنا ما بقي، ففرج اللّٰه ما بقي ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢١٥)، ومسلم (٢٧٤٣).","grade":"متفق عليه","chapter_ar":"باب من اتجر بمال غيره فرضي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2215) and Muslim (2743).","chapter_en":"One who invested another person’s property and grew it for him","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["Abdullah ibn Umar narrated from the Messenger of Allah ﷺ that he said: “Three men were walking when rain overtook them, so they took shelter in a cave in a mountain. Then a rock fell from the mountain over the mouth of their cave and sealed them in. They said to one another: Look to righteous deeds that you did for Allah and call upon Allah by means of them, perhaps Allah will relieve you from this.","One of them said: O Allah, I had elderly parents, a wife, and small children. I used to graze for them, and when I returned I would milk the animals and begin with my parents, giving them drink before my children. One day the trees kept me far away, so I did not return until evening. I found them asleep, so I milked as I used to milk and came with the milk vessel and stood by their heads, disliking to wake them from sleep and disliking to give the children drink before them, while the children were crying at my feet. That remained my state and theirs until dawn broke. If You know that I did that seeking Your Face, then open for us an opening through which we can see the sky. So Allah opened for them an opening through which they saw the sky.","Another said: O Allah, I had a female cousin whom I loved as intensely as a man can love a woman. I sought her for myself, but she refused until I brought her one hundred dinars. I worked hard until I gathered one hundred dinars, then I brought them to her. When I sat between her legs, she said: O servant of Allah, fear Allah and do not break the seal except by its right. So I stood up and left her. If You know that I did that seeking Your Face, then open for us from it an opening. So He opened for them further.","Another said: O Allah, I hired a laborer for a measure of rice. When he finished his work, he said: Give me my due. I offered him his measure, but he declined it. I continued investing it until I gathered from it cattle and their shepherds. Then he came back to me and said: Fear Allah and do not wrong me regarding my right. I said: Go to those cattle and their shepherds and take them. He said: Fear Allah and do not mock me. I said: I am not mocking you. Take those cattle and their shepherds. So he took them and went away. If You know that I did that seeking Your Face, then relieve for us what remains. So Allah relieved what remained.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2215},{"key":"muslim","label":"مسلم","number":2743}]},{"num":5469,"demo":false,"sanad":"","matn":["عن موسى بن طلحة، عن أبيه قال: مررت مع رسول اللّٰه ﷺ بقوم على رؤوس النخل، فقال: (( ما يصنع هؤلاء؟ )). فقالوا: يُلقّحونه، يجعلون الذكر في الأنثى فيتلقح. فقال رسول اللّٰه ﷺ: (( ما أظن يغني ذلك شيئاً )). قال: فأخبروا بذلك فتركوه، فأخبر رسول اللّٰه ﷺ بذلك، فقال: (( إن كان ينفعهم ذلك فليصنعوه؛ فإني إنما ظننت ظناً، فلا تؤاخذوني بالظن، ولكن إذا حدثتكم عن اللّٰه شيئاً فخذوا به؛ فإني لن أكذب على اللّٰه عز وجل ))."],"takhrij":"صحيح: رواه مسلم (٢٣٦١).","grade":"صحيح","chapter_ar":"باب ما جاء في تلقيح النخل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2361).","chapter_en":"What has come regarding pollinating date-palms","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Musa ibn Talhah narrated from his father, who said: I passed with the Messenger of Allah ﷺ by some people at the tops of date-palms. He said: “What are these people doing?” They said: They are pollinating them, placing the male into the female so it becomes pollinated. The Messenger of Allah ﷺ said: “I do not think that will help at all.” They were informed of that and so they stopped doing it. Then the Messenger of Allah ﷺ was informed of that, and he said: “If it benefits them, then let them do it. I only made an assumption, so do not take me to task over an assumption. But when I tell you something from Allah, then take it, for I will never lie about Allah, Mighty and Majestic.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2361}]},{"num":5470,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال: قدم نبي اللّٰه ﷺ المدينة وهم يأبرون النخل، يقولون: يُلقّحون النخل. فقال: (( ما تصنعون؟ )) قالوا: كنا نصنعه. قال: (( لعلكم لو لم تفعلوا كان خيراً )). فتركوه، فنفضت، أو فنقصت. قال: فذكروا ذلك له، فقال: (( إنما أنا بشر، إذا أمرتكم بشيء من دينكم فخذوا به، وإذا أمرتكم بشيء من رأيي فإنما أنا بشر )). قال عكرمة: أو نحو هذا."],"takhrij":"صحيح: رواه مسلم (٢٣٦٢).","grade":"صحيح","chapter_ar":"باب ما جاء في تلقيح النخل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2362).","chapter_en":"What has come regarding pollinating date-palms","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Rafi‘ ibn Khadij said: The Prophet of Allah ﷺ came to Madinah while they were fertilizing the date-palms — meaning pollinating them. He said: “What are you doing?” They said: We have always done it. He said: “Perhaps if you did not do it, it might be better.” So they left it, and the crop fell off, or decreased. They mentioned that to him, and he said: “I am only a human being. If I command you regarding something of your religion, then take it. But if I command you regarding something from my own opinion, then I am only a human being.” Ikrimah said: Or words similar to this."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2362}]},{"num":5471,"demo":false,"sanad":"","matn":["عن عائشة، وأنس أن النبي ﷺ مر بقوم يلقحون، فقال: (( لو لم يفعلوا لصلح )). قال: فخرج شيصاً، فمر بهم، فقال: (( ما لنخلكم؟ )) قالوا: قلت كذا وكذا. قال: (( أنتم أعلم بأمر دنياكم ))."],"takhrij":"صحيح: رواه مسلم (٢٣٦٣).","grade":"صحيح","chapter_ar":"باب ما جاء في تلقيح النخل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2363).","chapter_en":"What has come regarding pollinating date-palms","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Aisha and Anas narrated that the Prophet ﷺ passed by people pollinating date-palms and said: “If they did not do this, it might turn out well.” Then the fruit came out inferior. Later he passed by them and said: “What happened to your palms?” They said: You said such-and-such. He said: “You are more knowledgeable about the matters of your worldly life.”"]},"buhuth":{"ar":["قوله: (( شيصاً )) هو البسر الرديء الذي إذا يبس صار حشفاً."],"en":["The word “shaysan” means poor-quality dates which, when dried, become inferior dry dates."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2363}]},{"num":5472,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( من باع نخلاً قد أُبِّر، فثمرها للبائع إلا أن يشترط المبتاع ))."],"takhrij":"متفق عليه: رواه مالك (٩) والبخاري (٢٢٠٤)، ومسلم (٧٧ :١٥٤٣).","grade":"متفق عليه","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (9), al-Bukhari (2204), and Muslim (1543:77).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ said: “Whoever sells date-palms after they have been pollinated, then their fruit belongs to the seller unless the buyer makes it a condition.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"bukhari","label":"البخاري","number":2204},{"key":"muslim","label":"مسلم","number":77}]},{"num":5473,"demo":false,"sanad":"","matn":["عن ابن عمر قال: سمعت رسول اللّٰه ﷺ يقول: (( من ابتاع نخلاً بعد أن تؤبر فثمرتها للذي باعها إلا أن يشترط المبتاع، ومن ابتاع عبداً فماله للذي باعه إلا أن يشترط المبتاع ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٧٩)، ومسلم (٨٠ :١٥٤٣).","grade":"متفق عليه","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2379) and Muslim (1543:80).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar said: I heard the Messenger of Allah ﷺ say: “Whoever purchases date-palms after they have been pollinated, then their fruit belongs to the one who sold them unless the buyer makes it a condition. And whoever purchases a slave, then his wealth belongs to the one who sold him unless the buyer makes it a condition.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2379},{"key":"muslim","label":"مسلم","number":80}]},{"num":5474,"demo":false,"sanad":"","matn":["عن ابن عمر، وجابر أن رسول اللّٰه ﷺ قال: (( من ابتاع عبداً وله مال فماله للبائع إلا أن يشترط المبتاع، ومن أبر نخلاً فباعه بعد تأبيره فله ثمره إلا أن يشترط المبتاع ))."],"takhrij":"حسن: رواه ابن حبان (٤٩٢٤)، والبيهقي (٣٢٦-٣٢٥/٥).","grade":"حسن","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4924) and al-Bayhaqi (5/325–326).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar and Jabir narrated that the Messenger of Allah ﷺ said: “Whoever buys a slave who has wealth, then his wealth belongs to the seller unless the buyer makes it a condition. And whoever pollinates date-palms and then sells them after pollination, then their fruit belongs to him unless the buyer makes it a condition.”"]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":326},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4066,"n":4062}]},{"num":5475,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول اللّٰه ﷺ: (( من اشترى نخلاً بعد ما أبرت، ولم يشترط ثمرها فلا شيء له، ومن اشترى عبداً، ولم يشترط ماله فلا شيء له ))."],"takhrij":"صحيح: رواه علي بن الجعد (٢٨٧٥)، وابن حبان (٤٩٢١).","grade":"صحيح","chapter_ar":"باب من باع نخلاً قد أُبِّر، وعبداً له مال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ali ibn al-Ja‘d (2875) and Ibn Hibban (4921).","chapter_en":"One who sells pollinated date-palms, or a slave who possesses wealth","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “Whoever buys date-palms after they have been pollinated and does not stipulate their fruit, then he has no right to it. And whoever buys a slave and does not stipulate his wealth, then he has no right to it.”"]}},"tuhfa":{},"refs":[{"key":"علی_بن_الجعد","label":"علي بن الجعد","number":2875},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4063,"n":4059}]},{"num":5476,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( من أقال مسلماً أقاله اللّٰه عثرته )). وفي رواية: (( يوم القيامة ))."],"takhrij":"صحيح: رواه أبو داود (٣٤٦٠)، وابن ماجه (٢١٩٩)، وصححه ابن حبان (٥٠٣٠).","grade":"صحيح","chapter_ar":"باب فضل الإقالة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3460), Ibn Majah (2199), and authenticated by Ibn Hibban (5030).","chapter_en":"The virtue of canceling a sale by mutual agreement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever releases a Muslim from a sale, Allah will relieve his slip.” In another narration: “on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3460},{"key":"ibnmajah","label":"ابن ماجه","number":2199},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":5030}]},{"num":5477,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول اللّٰه ﷺ: (( الخراج بالضمان ))."],"takhrij":"حسن: رواه الشافعي في مسنده (١٢٠٣)، وأبو داود (٣٥٠٨)، والنسائي (٤٥٠٢)، والترمذي (١٢٨٥)، وابن ماجه (٢٤٤٢)، وصححه ابن حبان (٤٩٢٨)، قال الترمذي: حسن صحيح.","grade":"حسن","chapter_ar":"باب الخراج بالضمان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Shafi‘i in his Musnad (1203), Abu Dawud (3508), al-Nasa’i (4502), al-Tirmidhi (1285), Ibn Majah (2442), and authenticated by Ibn Hibban (4928). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Benefit belongs to the one who bears liability","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Aisha said: The Messenger of Allah ﷺ said: “Profit goes with liability.”"]},"buhuth":{"ar":["ومعنى الحديث: أن المبيع إذا كان مما له دخل وغلة، فإن مالك الرقبة - الذي هو ضامن الأصل - يملك الخراج بضمان الأصل. فإذا ابتاع الرجل أرضاً فأشغلها، أو ماشية فنتجها، أو دابة فركبها، أو عبداً فاستخدمه، ثم وجد به عيباً فله أن يرد الرقبة، ولا شيء عليه فيما انتفع به؛ لأنها لو تلفت ما بين مدة العقد والفسخ لكانت من ضمان المشتري، فوجب أن يكون الخراج من حقه. أفاده الخطابي."],"en":["The meaning of the hadith is that if the sold item is something that produces yield or benefit, then the owner of the principal asset — the one who bears its liability — is entitled to its revenue because he bears the risk of the principal. So if a man buys land and uses it, or livestock and it produces offspring, or an animal and he rides it, or a slave and he employs him, then later finds a defect in it, he may return the principal item, and nothing is due from him for the benefit he enjoyed. That is because if it had perished during the period between the contract and rescission, it would have been under the liability of the buyer, so the yield rightly belongs to him. This was explained by al-Khattabi."]}},"tuhfa":{},"refs":[{"key":"الشافعی/مسندہ","label":"الشافعي في مسنده","number":1203},{"key":"abudawud","label":"أبو داود","number":3508},{"key":"nasai","label":"النسائي","number":4502},{"key":"tirmidhi","label":"الترمذي","number":1285},{"key":"ibnmajah","label":"ابن ماجه","number":2442},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4928}]},{"num":5478,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، عن رسول اللّٰه ﷺ قال: (( إذا اختلف البيعان، وليس بينهما بينة فهو ما يقول رب السلعة، أو يتتاركان ))."],"takhrij":"حسن: رواه أبو داود (٣٥١١)، والنسائي (٤٦٥٢)، والحاكم (٤٥ /٢)، والبيهقي (٣٣٢/٥).","grade":"حسن","chapter_ar":"باب البيعان يختلفان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3511), al-Nasa’i (4652), al-Hakim (2/45), and al-Bayhaqi (5/332).","chapter_en":"When the seller and buyer disagree","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":33,"content":{"translation":{"en":["Abdullah ibn Mas‘ud narrated from the Messenger of Allah ﷺ that he said: “If the two parties in a sale disagree, and neither has evidence, then the statement is according to the owner of the merchandise, or they cancel the sale.”"]},"buhuth":{"ar":["وظاهر الحديث يدل على أن البائع والمشتري إذا اختلفا في أمر من الأمور المتعلقة بالعقد، فالقول قول البائع، أو يخير المشتري بين أخذ السلعة بالثمن الذي يقوله البائع وبين تركه."],"en":["The apparent meaning of the hadith indicates that if the seller and buyer disagree regarding a matter related to the contract, then the seller’s statement is accepted, or the buyer is given the choice between taking the item at the price claimed by the seller or leaving it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3511},{"key":"nasai","label":"النسائي","number":4652},{"key":"البیہقی","label":"البيهقي","number":332},{"key":"hakim","label":"المستدرك على الصحيحين","number":2293,"n":2285},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10812,"n":10905}]},{"num":5479,"demo":false,"sanad":"","matn":["عن سمرة بن جندب أن رسول اللّٰه ﷺ قال: (( أيما امرأة زوجها وليان فهي للأول منهما، ومن باع بيعاً من رجلين فهو للأول منهما ))."],"takhrij":"صحيح: رواه الترمذي (١١١٠) قال الترمذي: حديث حسن. وأحمد (٢٠٠٨٥)، وابن ماجه (٢١٩٠).","grade":"صحيح","chapter_ar":"باب إذا باع المجيزان فهو للأول","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1110), who said: A Hasan hadith, and by Ahmad (20085) and Ibn Majah (2190).","chapter_en":"If something is sold twice, it belongs to the first purchaser","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":37,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Messenger of Allah ﷺ said: “Any woman whom two guardians marry off, she belongs to the first of the two. And whoever sells something to two men, it belongs to the first of them.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1110},{"key":"حدیث_حسن_واحمد","label":"حديث حسن. وأحمد","number":20085},{"key":"ibnmajah","label":"ابن ماجه","number":2190},{"key":"ahmad","label":"مسند الإمام أحمد","number":20085,"n":20085}]},{"num":5480,"demo":false,"sanad":"","matn":["عن أبي بكر - في قصة الهجرة - أنه مر على راعي غنم يسوق غنمه إلى الصخرة، فسأله: لمن أنت يا غلام؟ قال: لرجل من قريش سماه، فعرفه، فقال: هل في غنمك لبن؟ قال: نعم. فقال: هل أنت حالب لنا؟ قال: نعم. فحلب له، فأتى به رسول اللّٰه ﷺ، فشرب منه."],"takhrij":"صحيح: رواه البخاري (٣٦٥٢).","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3652).","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["Abu Bakr, in the story of the migration, passed by a shepherd driving his sheep toward the rock. He asked: Whose servant are you, boy? He said: I belong to a man from Quraysh, naming him, and Abu Bakr recognized him. He said: Is there milk among your sheep? He said: Yes. He said: Will you milk for us? He said: Yes. So he milked for him and brought it to the Messenger of Allah ﷺ, and he drank from it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3652}]},{"num":5481,"demo":false,"sanad":"","matn":["عن سمرة بن جندب أن النبي ﷺ قال: (( إذا أتى أحدكم على ماشية، فإن كان فيها صاحبها فليستأذنه، فإن أذن له فليحتلب وليشرب. وإن لم يكن فيها أحد فليصوت ثلاثاً، فإن أجابه أحد فليستأذنه، فإن لم يجبه أحد فليحتلب وليشرب، ولا يحمل ))."],"takhrij":"صحيح: رواه أبو داود (٢٦١٩)، والترمذي (١٢٩٦) وقال الترمذي: حسن غريب.","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2619), and al-Tirmidhi (1296), who said: Hasan Gharib.","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “If one of you comes upon livestock, and its owner is present, then let him seek his permission. If he permits him, let him milk and drink. If no one is there, then let him call out three times. If someone answers him, let him seek permission. If no one answers him, let him milk and drink, but he must not carry any away.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2619},{"key":"tirmidhi","label":"الترمذي","number":1296}]},{"num":5482,"demo":false,"sanad":"","matn":["عن عباد بن شرحبيل قال: أصابني سنة، فدخلت حائطاً من حيطان المدينة، ففركت سنبلاً، فأكلت، وحملت في ثوبي، فجاء صاحبه، فضربني، وأخذ ثوبي، فأتيت رسول اللّٰه ﷺ، فقال له: (( ما علمت إذ كان جاهلاً، ولا أطعمت إذ كان جائعاً أو قال: ساغباً )). وأمره فرد علي ثوبي، وأعطاني وسقاً، أو نصف وسق من طعام."],"takhrij":"صحيح: رواه أبو داود (٢٦٣٠)، والنسائي (٥٤٠٩)، وابن ماجه (٢٢٩٨)، وأحمد (١٧٥٢١).","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2630), al-Nasa’i (5409), Ibn Majah (2298), and Ahmad (17521).","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["‘Abbad ibn Sharhabil said: A year of hardship struck me, so I entered one of the gardens of Madinah and rubbed an ear of grain, ate from it, and carried some in my garment. Then the owner came, struck me, and took my garment. So I went to the Messenger of Allah ﷺ, and he said to him: “You neither taught him when he was ignorant, nor fed him when he was hungry” — or he said — “starving.” He ordered him to return my garment to me, and he gave me a wasq, or half a wasq, of food."]},"buhuth":{"ar":["وقوله: (( ساغباً )) أي جائعاً."],"en":["The word “saghiban” means hungry."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2630},{"key":"nasai","label":"النسائي","number":5409},{"key":"ibnmajah","label":"ابن ماجه","number":2298},{"key":"ahmad","label":"مسند الإمام أحمد","number":17521,"n":17521}]},{"num":5483,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، عن النبي ﷺ قال:","«إِذَا أَتَيْتَ عَلَى رَاعٍ فَنَادِ ثَلَاثَ مَرَّاتٍ، فَإِنْ أَجَابَكَ وَإِلَّا فَاشْرَبْ فِي غَيْرِ أَنْ تُفْسِدَ، وَإِذَا أَتَيْتَ عَلَى حَائِطِ بُسْتَانٍ فَنَادِ صَاحِبَ الْبُسْتَانِ ثَلَاثَ مَرَّاتٍ، فَإِنْ أَجَابَكَ وَإِلَّا فَكُلْ فِي أَنْ لَا تُفْسِدَ»."],"takhrij":"صحيح: رواه ابن ماجه (٢٣٠٠) واللفظ له، وأحمد (١١١٥٩)، وصححه ابن حبان (٥٢٨١).","grade":"صحيح","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (2300), and this is his wording; also by Aḥmad (11159), and authenticated by Ibn Ḥibbān (5281).","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that the Prophet ﷺ said:","“If you come upon a shepherd, call out three times. If he answers you, then proceed accordingly; otherwise, drink without causing damage.","And if you come upon a walled garden, call its owner three times. If he answers you, then proceed accordingly; otherwise, eat without causing damage.”"]},"buhuth":{"ar":["وزادا:","«الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ، فَمَا زَادَ فَهُوَ صَدَقَةٌ»."],"en":["They additionally narrated:","“Hospitality is for three days, and whatever exceeds that is charity.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2300},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":5281},{"key":"ahmad","label":"مسند الإمام أحمد","number":11159,"n":11159}]},{"num":5484,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول اللّٰه ﷺ سئل عن التمر المعلق، قال: (( من أصاب منه من ذي حاجة غير متخذ خُبنة فلا شيء عليه ))."],"takhrij":"حسن: رواه أبو داود (١٧١٠)، والنسائي (٤٩٥٨)، والترمذي (١٢٨٩) وحسنه. واللفظ للترمذي.","grade":"حسن","chapter_ar":"باب يجوز لابن السبيل أن يأكل من التمر، ويشرب من اللبن إذا مر به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1710), al-Nasa’i (4958), and al-Tirmidhi (1289), who graded it Hasan. The wording is that of al-Tirmidhi.","chapter_en":"It is permissible for a stranded traveler to eat dates and drink milk when passing by","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, from his grandfather, narrated that the Messenger of Allah ﷺ was asked about hanging dates, and he said: “Whoever takes from them out of need, without gathering any into his garment, then there is nothing against him.”"]},"buhuth":{"ar":["وقوله: (( خُبنة )) أي لا يجعل شيئاً في ثوبه."],"en":["The word “khubnah” means that he should not put anything into his garment."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1710},{"key":"nasai","label":"النسائي","number":4958},{"key":"tirmidhi","label":"الترمذي","number":1289}]},{"num":5485,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر:","أن رسول الله ﷺ قال:","«لَا يَحْتَلِبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ بِغَيْرِ إِذْنِهِ، أَيُحِبُّ أَحَدُكُمْ أَنْ تُؤْتَى مَشْرُبَتُهُ فَتُكْسَرَ خِزَانَتُهُ فَيُنْتَقَلَ طَعَامُهُ؟ وَإِنَّمَا تَخْزُنُ لَهُمْ ضُرُوعُ مَوَاشِيهِمْ أَطْعِمَتَهُمْ، فَلَا يَحْتَلِبَنَّ أَحَدٌ مَاشِيَةَ أَحَدٍ إِلَّا بِإِذْنِهِ»."],"takhrij":"متفق عليه: رواه مالك (١٧)، والبخاري (٢٤٣٥)، ومسلم (١٧٢٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن حلب ماشية الغير بغير إذنه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (17), al-Bukhārī (2435), and Muslim (1726).","chapter_en":"The prohibition of milking another person’s livestock without permission","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":39,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar reported that the Messenger of Allah ﷺ said:","“None of you should milk another person’s livestock without his permission.","Would one of you like someone to come to his storeroom, break open his store, and carry away his food?","The udders of their livestock are what store their food for them. Therefore, no one should milk another person’s livestock except with his permission.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"bukhari","label":"البخاري","number":2435},{"key":"muslim","label":"مسلم","number":1726}]},{"num":5486,"demo":false,"sanad":"","matn":["عن أم هانئ، أن النبي ﷺ قال لها: (( اتخذي غنماً؛ فإن فيها بركة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٣٠٤)، وأحمد (٢٣٧٨١).","grade":"صحيح","chapter_ar":"باب استحباب التجارة بالغنم وغيرها من المواشي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2304) and Ahmad (23781).","chapter_en":"Recommendation to trade in sheep and other livestock","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":40,"content":{"translation":{"en":["Umm Hani’ narrated that the Prophet ﷺ said to her: “Keep sheep, for there is blessing in them.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2304},{"key":"ahmad","label":"أحمد","number":23781}]},{"num":5487,"demo":false,"sanad":"","matn":["عن عروة البارقي يرفعه قال: (( الإبل عز لأهلها، والغنم بركة، والخير معقود في نواصي الخيل إلى يوم القيامة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٣٠٥)، وابن أبي عاصم في الآحاد والمثاني (٣٦٢/٤)، والطبراني في الكبير (١٥٦/١٧).","grade":"صحيح","chapter_ar":"باب استحباب التجارة بالغنم وغيرها من المواشي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2305), Ibn Abi ‘Asim in al-Ahad wa al-Mathani (4/362), and al-Tabarani in al-Kabir (17/156).","chapter_en":"Recommendation to trade in sheep and other livestock","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":40,"content":{"translation":{"en":["‘Urwah al-Bariqi narrated it as a raised report: “Camels are honor for their people, sheep are blessing, and goodness is tied to the forelocks of horses until the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2305},{"key":"ابن_ابی_عاصم/الاحاد_والمثانی","label":"ابن أبي عاصم في الآحاد والمثاني","number":362},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":156}]},{"num":5488,"demo":false,"sanad":"","matn":["عن عائشة قالت: كان على رسول اللّٰه ﷺ ثوبان قطريان غليظان، فكان إذا قعد فعرق ثقلا عليه، فقدم بَزٌّ من الشام لفلان اليهودي، فقلت: لو بعثت إليه، فاشتريت منه ثوبين إلى الميسرة، فأرسل إليه، فقال: قد علمت ما يريد، إنما يريد أن يذهب بمالي أو بدراهمي. فقال رسول اللّٰه ﷺ: (( كذب، قد علم أني من أتقاهم لله وآداهم للأمانة ))."],"takhrij":"صحيح: رواه الترمذي (١٢١٣)، والنسائي (٤٦٢٨)، وصححه الحاكم (٢٤-٢٣/٢).","grade":"صحيح","chapter_ar":"باب الشراء إلى أجل معلوم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1213), al-Nasa’i (4628), and authenticated by al-Hakim (2/23–24).","chapter_en":"Buying on deferred payment to a known term","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":41,"content":{"translation":{"en":["Aisha said: The Messenger of Allah ﷺ had two thick Qatari garments, and when he sat and perspired, they weighed heavily on him. Then some cloth from Syria arrived for a certain Jewish man, so I said: If only you would send to him and buy from him two garments on deferred payment until ease comes. So he sent to him, and the man said: I know what he wants; he only wants to take away my property — or my money. So the Messenger of Allah ﷺ said: “He has lied. He certainly knows that I am the most Allah-fearing of them and the most faithful in fulfilling trusts.”"]},"buhuth":{"ar":["وقوله: (( إلى الميسرة )) أي إلى أجل معلوم يكون فيه يسر، وإلا فجهالة الأجل مفسدة للبيع."],"en":["The phrase “until ease comes” means to a known term at which payment becomes manageable. Otherwise, an unknown term invalidates the sale."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1213},{"key":"nasai","label":"النسائي","number":4628},{"key":"صححہ_الحاکم","label":"صححه الحاكم","number":24}]},{"num":5489,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: كان بالمدينة فزع، فاستعار النبي ﷺ فرساً من أبي طلحة يقال له: المندوب، فركب، فلما رجع قال: (( ما رأينا من شيء، وإن وجدناه لبحراً ))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٢٧)، ومسلم (٢٣٠٧).","grade":"متفق عليه","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2627) and Muslim (2307).","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Anas ibn Malik said: There was an alarm in Madinah, so the Prophet ﷺ borrowed a horse from Abu Talhah called al-Mandub and rode it. When he returned, he said: “We did not see anything, and we found it to be like a sea,” meaning very swift."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2627},{"key":"muslim","label":"مسلم","number":2307}]},{"num":5490,"demo":false,"sanad":"","matn":["عن أنس قال: سمعت رسول اللّٰه ﷺ يقول: (( العارية مؤداة، والمنحة مردودة ))."],"takhrij":"حسن: رواه ابن ماجه (٢٣٩٩).","grade":"حسن","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2399).","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Anas said: I heard the Messenger of Allah ﷺ say: “A borrowed item is to be returned, and a manihah (an animal lent for its milk) is to be returned.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2399}]},{"num":5491,"demo":false,"sanad":"","matn":["عن أبي أمامة يقول: سمعت رسول اللّٰه ﷺ يقول: (( العارية مؤداة، والمنحة مردودة ))."],"takhrij":"حسن: رواه ابن ماجه (٢٣٩٨)، والترمذي (١٢٦٥)، وأبو داود (٣٥٦٥)، وأحمد (٢٢٢٩٤) واللفظ لابن ماجه.","grade":"حسن","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2398), al-Tirmidhi (1265), Abu Dawud (3565), and Ahmad (22294). The wording is that of Ibn Majah.","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Abu Umamah said: I heard the Messenger of Allah ﷺ say: “A borrowed item is to be returned, and a manihah (an animal lent for its milk) is to be returned.”"]},"buhuth":{"ar":["ولفظ أبي داود: (( إن اللّٰه عز وجل قد أعطى كل ذي حق حقه، فلا وصية لوارث، ولا تنفق المرأة شيئاً من بيتها إلا بإذن زوجها )). فقيل: يا رسول الله، ولا الطعام؟ قال: (( ذاك أفضل أموالنا )). ثم قال: (( العارية مؤداة، والمنحة مردودة، والدين مقضي، والزعيم غارم )). وقال الترمذي: حسن غريب."],"en":["The wording in Abu Dawud is: “Allah, Mighty and Majestic, has given every person with a right his due right, so there is no bequest for an heir, and a woman must not spend anything from her house except with her husband’s permission.” It was said: O Messenger of Allah ﷺ, not even food? He said: “That is the best of our wealth.” Then he said: “A borrowed item is to be returned, a manihah (an animal lent for its milk) is to be returned, a debt is to be paid, and the guarantor is liable.” Al-Tirmidhi said: Hasan Gharib."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2398},{"key":"tirmidhi","label":"الترمذي","number":1265},{"key":"abudawud","label":"أبو داود","number":3565},{"key":"ahmad","label":"مسند الإمام أحمد","number":22294,"n":22294}]},{"num":5492,"demo":false,"sanad":"","matn":["عن سمرة بن جندب، عن النبي ﷺ قال: (( على اليد ما أخذت حتى تؤدي ))."],"takhrij":"صحيح: رواه أبو داود (٣٥٦١)، والترمذي (١٢٦٦)، قال الترمذي: حسن صحيح.","grade":"صحيح","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3561), and al-Tirmidhi (1266), who said: Hasan Sahih.","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “The hand is responsible for what it takes until it returns it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3561},{"key":"tirmidhi","label":"الترمذي","number":1266}]},{"num":5493,"demo":false,"sanad":"","matn":["عن يعلى بن أمية قال: قال لي رسول اللّٰه ﷺ: (( إذا أتتك رسلي فأعطهم ثلاثين درعاً، وثلاثين بعيراً )). قال: فقلت: يا رسول الله، أعارية مضمونة، أو عارية مؤداة؟ قال: (( بل عارية مؤداة ))."],"takhrij":"صحيح: رواه أبو داود (٣٥٦٦)، وأحمد (١٧٩٥٠)، والدارقطني (٣٩/٣)، وصححه ابن حبان (٤٧٢٠).","grade":"صحيح","chapter_ar":"باب ما جاءت به العارية بأنها مؤداة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3566), Ahmad (17950), al-Daraqutni (3/39), and authenticated by Ibn Hibban (4720).","chapter_en":"What has come regarding a borrowed item being returned","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Ya‘la ibn Umayyah said: The Messenger of Allah ﷺ said to me: “When my messengers come to you, give them thirty coats of armor and thirty camels.” I said: O Messenger of Allah ﷺ, is it a guaranteed loan or a borrowed item to be returned? He said: “Rather, it is a borrowed item to be returned.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3566},{"key":"الدارقطنی","label":"الدارقطني","number":39},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4720},{"key":"ahmad","label":"مسند الإمام أحمد","number":17950,"n":17950}]},{"num":5494,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أن رسول اللّٰه ﷺ سار إلى حنين. فذكر الحديث. وفيه: ثم بعث رسول اللّٰه ﷺ إلى صفوان بن أمية فسأله أدراعاً عنده مائة درع وما يصلحها من عدتها. فقال: أغصباً يا محمد؟ فقال: (( بل عارية مضمونة حتى نؤديها إليك ))."],"takhrij":"حسن: رواه الحاكم (٤٩-٤٨/٣)، والبيهقي (٨٩/٦).","grade":"حسن","chapter_ar":"باب ما جاء في تضمين العارية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (3/48–49) and al-Bayhaqi (6/89).","chapter_en":"What has come regarding liability for borrowed items","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":43,"content":{"translation":{"en":["Jabir ibn Abdullah narrated that the Messenger of Allah ﷺ marched to Hunayn. In the hadith it states: Then the Messenger of Allah ﷺ sent to Safwan ibn Umayyah and asked him for one hundred coats of armor that he had, along with their equipment. Safwan said: Is this by force, O Muhammad? He said: “Rather, it is a guaranteed loan until we return it to you.”"]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":89},{"key":"hakim","label":"المستدرك على الصحيحين","number":4369,"n":4360},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11477,"n":11582}]},{"num":5495,"demo":false,"sanad":"","matn":["عن عمرو بن تغلب قال: قال رسول اللّٰه ﷺ: (( إن من أشراط الساعة أن يفشو المال ويكثر، وتفشو التجارة، ويظهر العلم، ويبيع الرجل البيع، فيقول: لا حتى أستأمر تاجر بني فلان، ويلتمس في الحي العظيم الكاتب فلا يوجد ))."],"takhrij":"صحيح: رواه النسائي (٤٤٥٦)، والحاكم (٧/٢). واللفظ للنسائي.","grade":"صحيح","chapter_ar":"باب من أشراط الساعة كثرة المال وفشو التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4456) and al-Hakim (2/7). The wording is that of al-Nasa’i.","chapter_en":"Among the signs of the Hour are abundance of wealth and the spread of trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["‘Amr ibn Taghlib said: The Messenger of Allah ﷺ said: “Among the signs of the Hour are that wealth will become widespread and abundant, trade will become widespread, knowledge will appear, a man will make a sale and then say: No, not until I consult the merchant of Banu so-and-so, and in a large tribe a scribe will be sought but not found.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4456},{"key":"hakim","label":"الحاكم","number":7}]},{"num":5496,"demo":false,"sanad":"","matn":["عن طارق بن شهاب قال: كنا عند عبد اللّٰه جلوساً، فجاء آذنه، فقال: قد قامت الصلاة، فقام وقمنا معه، فدخلنا المسجد، فرأى الناس ركوعاً في مقدم المسجد، فكبر وركع، ومشينا وفعلنا مثل ما فعل، فمر رجل يسرع، فقال: عليكم السلام يا أبا عبد الرحمن، فقال: صدق الله، وبلغ رسوله. فلما صلينا رجع، فولج على أهله، وجلسنا في مكاننا ننتظره حتى يخرج، فقال بعضنا لبعض: أيكم يسأله؟ قال طارق: أنا أسأله، فسأله، فقال: عن النبي ﷺ قال: (( بين يدي الساعة تسليم الخاصة، وفشو التجارة حتى تعين المرأة زوجها على التجارة، وقطع الأرحام، وفشو القلم، وظهور الشهادة بالزور، وكتمان شهادة الحق ))."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (١٠٤٩)، وأحمد (٣٩٨٢)، والطحاوي في مشكله (١٥٩٠).","grade":"حسن","chapter_ar":"باب من أشراط الساعة كثرة المال وفشو التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhari in al-Adab al-Mufrad (1049), Ahmad (3982), and al-Tahawi in Mushkil al-Athar (1590).","chapter_en":"Among the signs of the Hour are abundance of wealth and the spread of trade","part_en":"The Book of Sales","group_ar":"جموع ما جاء في أحكام البيوع والتجارات","group_en":"A collection of what has been narrated regarding the rulings of sales and trade","part_no":17,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Tariq ibn Shihab said: We were sitting with Abdullah when his caller came and said: The prayer has begun. So he stood, and we stood with him. We entered the mosque, and he saw the people already bowing in the front of the mosque, so he said the opening takbir and bowed, and we walked and did as he did. Then a man passed by hurriedly and said: Peace be upon you, O Abu Abd al-Rahman. He replied: Allah has spoken the truth, and His Messenger conveyed it. When we had prayed, he returned and entered upon his family, and we sat in our place waiting for him to come out. Some of us said to one another: Which of you will ask him? Tariq said: I will ask him. So he asked him, and he said: From the Prophet ﷺ: “Before the Hour there will be greetings given only to select people, trade will become widespread to the point that a woman helps her husband in trade, family ties will be cut, writing will become widespread, false testimony will appear, and true testimony will be concealed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":1049},{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":1590},{"key":"adab","label":"الأدب المفرد","number":1049,"n":1049},{"key":"ahmad","label":"مسند الإمام أحمد","number":3982,"n":3982}]},{"num":5497,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قدم النبي ﷺ المدينة، وهم يسلفون في الثمار السنة والسنتين، فقال: (( من أسلف في ثمر فليسلف في كيل معلوم، ووزن معلوم، إلى أجل معلوم ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢٤٠)، ومسلم (١٢٧ :١٦٠٤). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب السلم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2240) and Muslim (1604:127). The wording is that of Muslim.","chapter_en":"Forward sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas said: The Prophet ﷺ came to Madinah while they used to pay in advance for fruits one year and two years ahead. So he said: “Whoever pays in advance for fruit, let him pay in advance for a known measure, a known weight, and a known term.”"]},"buhuth":{"ar":["قوله: (( السلف )) وهو لغة الحجاز، والسلم لغة العراق. والسلف له معنيان في المعاملات:","أحدهما: القرض الذي لا منفعة فيه للمقرض، وعلى المستقرض رده كما أخذه.","والثاني: هو السلم المعهود، وهو تسليم مال عاجل بمقابلة موصوف في الذمة. ويقال: سلفت، وأسلفت، وأسلمت بمعنى واحد.","قوله: (( في ثمر )) قال النووي في شرحه: هكذا هو في أكثر الأصول: (( ثمر )) بالمثلثة، وهو أعم.","وفي الحديث دليل على جواز السلف في الطعام والثياب وغير ذلك من أنواع التجارة مما يعرف جنسه، وصفته."],"en":["The word salaf is the Hijazi term, while salam is the Iraqi term. In transactions, salaf has two meanings:","The first is a loan in which the lender takes no benefit, and the borrower must return it as he received it.","The second is the well-known forward sale, which is paying present money in exchange for a specified item owed in liability. The expressions saliftu, aslaftu, and aslamtu are all used with the same meaning.","The phrase “for fruit” appears in most of the manuscripts in this broad form. Al-Nawawi said this wording is more general.","The hadith proves the permissibility of forward sale in food, clothing, and other kinds of merchandise whose type and description are known."]},"intro":{"ar":["قال اللّٰه تعالى: { يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰ أَجَلٍ مُّسَمًّى فَاكْتُبُوهُ } [البقرة: ٢٨٢].","قال ابن عباس: أشهد أن السلف المضمون إلى أجل مسمى قد أحله اللّٰه في كتابه، وأذن فيه. ثم قرأ هذه الآية. أخرجه عبد الرزاق (١٤٠٦٤)."],"en":["Allah the Exalted said: “O you who believe, when you contract a debt for a fixed term, write it down.” [Al-Baqarah: 282]","Ibn Abbas said: I bear witness that guaranteed forward sale to a fixed term has been made lawful by Allah in His Book and permitted by Him. Then he recited this verse. Narrated by Abd al-Razzaq (14064)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2240},{"key":"muslim","label":"مسلم","number":127}]},{"num":5498,"demo":false,"sanad":"","matn":["عن أبي البختري قال: سألت ابن عمر رضي اللّٰه عنهما عن السلم في النخل، فقال: نهى عن بيع النخل حتى يصلح، وعن بيع الورِق نَساءً بناجز.","وسألت ابن عباس عن السلم في النخل، فقال: نهى النبي ﷺ عن بيع النخل حتى يأكل منه، وحتى يوزن."],"takhrij":"صحيح: رواه البخاري (٢٢٤٨-٢٢٤٧)، ومسلم (١٥٣٧). واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب السلم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2247–2248) and Muslim (1537). The wording is that of al-Bukhari.","chapter_en":"Forward sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu al-Bakhtari said: I asked Ibn Umar, may Allah be pleased with them both, about forward sale involving date-palms, and he said: He forbade selling date-palms until they become sound, and he forbade selling silver for gold on credit.","And I asked Ibn Abbas about forward sale involving date-palms, and he said: The Prophet ﷺ forbade selling date-palms until one can eat from them and until they are weighed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2248},{"key":"muslim","label":"مسلم","number":1537}]},{"num":5499,"demo":false,"sanad":"","matn":["عن محمد بن أبي المجالد قال: بعثني عبد اللّٰه بن شداد، وأبو بردة إلى عبد اللّٰه بن أبي أوفى، فقالا: سله هل كان أصحاب النبي ﷺ في عهد النبي ﷺ يسلفون في الحنطة؟ قال عبد اللّٰه: كنا نسلف نبيط أهل الشام في الحنطة والشعير والزيت في كيل معلوم إلى أجل معلوم. قلت: إلى من كان أصله عنده؟ قال: ما كنا نسألهم عن ذلك. ثم بعثاني إلى عبد الرحمن بن أبزى، فسألته، فقال: كان أصحاب النبي ﷺ يسلفون على عهد النبي ﷺ، ولم نسألهم ألهم حرث أم لا."],"takhrij":"صحيح: رواه البخاري (٢٢٤٥-٢٢٤٤).","grade":"صحيح","chapter_ar":"باب السلم إلى من ليس عنده أصل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2244–2245).","chapter_en":"Forward sale to one who does not presently possess the source goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Muhammad ibn Abi al-Mujalid said: Abdullah ibn Shaddad and Abu Burdah sent me to Abdullah ibn Abi Awfa and said: Ask him whether the Companions of the Prophet ﷺ used to engage in forward sale for wheat during the lifetime of the Prophet ﷺ. Abdullah said: We used to make forward contracts with the Nabateans of Syria for wheat, barley, and oil in a known measure to a known term. I said: With people who had the goods with them? He said: We did not ask them about that. Then they sent me to Abd al-Rahman ibn Abza, and I asked him, and he said: The Companions of the Prophet ﷺ used to engage in forward sale during the time of the Prophet ﷺ, and we did not ask them whether they had crops or not."]},"buhuth":{"ar":["وفي رواية عنده: (( على عهد النبي ﷺ وأبي بكر وعمر للحنطة والشعير والزبيب والتمر )). وفي مسند أحمد: (( وما هو عندهم، أو ما نراه عندهم )).","وقوله: (( ما كنا نسألهم عن ذلك )) يستفاد منه جواز بيع السلم في عموم التجارة من الزراعة وغيرها بالشروط المذكورة من الوصف والنوع والمدة وغيرها قطعاً للنزاع.","وقوله: (( نبيط )) ويقال لهم: النبط. وهم قوم من العرب دخلوا في العجم والروم، واختلطت أنسابهم وفسدت ألسنتهم، فالذين اختلطوا بالروم نزلوا في بوادي الشام، وهم الذين صاروا زراعاً."],"en":["In another narration in al-Bukhari: “During the time of the Prophet ﷺ, Abu Bakr, and Umar, for wheat, barley, raisins, and dates.” In Musnad Ahmad: “Even when it was not with them, or when we did not see it with them.”","From the phrase “We did not ask them about that,” it is understood that forward sale is permissible in general merchandise, whether agricultural or otherwise, so long as the required conditions are met, such as clear description, type, term, and similar details, in order to prevent dispute.","The word Nabit is also said as Nabat. They were a people of Arab origin who mixed with the non-Arabs and the Romans, so their lineages became mixed and their language became corrupted. Those who mixed with the Romans settled in the rural lands of Syria, and they became farmers."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2245}]},{"num":5500,"demo":false,"sanad":"","matn":["عن الأعمش قال: تذاكرنا عند إبراهيم الرهن في السلف، فقال: حدّثني الأسود، عن عائشة: أنّ النبيَّ ﷺ اشترى من يهوديٍّ طعامًا إلى أجلٍ معلوم، وارتهن منه درعًا من حديد."],"takhrij":"متفق عليه: رواه البخاري (٢٢٥٢)، ومسلم (١٢٦: ١٦٠٣). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الرهن في السلم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2252) and Muslim (1603:126). The wording is al-Bukhari’s.","chapter_en":"Collateral in a forward sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Al-A‘mash said: We were discussing collateral in forward transactions in the presence of Ibrahim, and he said: Al-Aswad narrated to me from Aisha that the Prophet ﷺ bought food from a Jew on a fixed term and gave him a coat of armor made of iron as collateral."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2252},{"key":"muslim","label":"مسلم","number":126}]},{"num":5501,"demo":false,"sanad":"","matn":["عن ابن عمر قال: كان أهل الجاهلية يتبايعون لحم الجزور إلى حَبَلِ الحَبَلَةِ. وحَبَلُ الحَبَلَةِ: أن تنتج الناقة، ثم تحمل التي نتجت. فنهى رسولُ الله ﷺ عن ذلك."],"takhrij":"متفق عليه: رواه البخاري (٢٢٥٦)، ومسلم (٦: ١٥١٤). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب عدم جواز السلم إلى أجل غير معلوم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2256) and Muslim (1514:6). The wording is Muslim’s.","chapter_en":"The impermissibility of a forward sale with an unknown term","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في السلم","group_en":"Collection of chapters on what has come regarding forward sales","part_no":17,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ibn Umar said: The people of the pre-Islamic period used to trade camel meat until “the pregnancy of the offspring’s offspring.” And “the pregnancy of the offspring’s offspring” means that the she-camel gives birth, then the one born from her becomes pregnant. So the Messenger of Allah ﷺ forbade that."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2256},{"key":"muslim","label":"مسلم","number":6}]},{"num":5502,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قضى النبي ﷺ بالشفعة في كل ما لم يقسم، فإذا وقعت الحدود وصرفت الطرق فلا شفعة."],"takhrij":"صحيح: رواه البخاري (٢٢٥٧).","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2257).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Prophet ﷺ ruled that preemption applies in everything that has not been divided. But when the boundaries are fixed and the roads are laid out, then there is no preemption."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2257}]},{"num":5503,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول الله ﷺ: (( من كان له شريك في رَبْعَةٍ، أو نخل، فليس له أن يبيع حتى يؤذن شريكه، فإن رضي أخذ، وإن كره ترك ))."],"takhrij":"صحيح: رواه مسلم (١٦٠٨).","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1608).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Whoever has a partner in a dwelling, or in date-palms, then he has no right to sell until he informs his partner. If he is pleased, he may take it, and if he dislikes it, he may leave it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1608}]},{"num":5504,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قال رسول الله ﷺ: (( الشفعة في كل شرك، في أرض، أو رَبْع، أو حائط، لا يصلح أن يبيع حتى يعرض على شريكه، فيأخذ أو يدع، فإن أبى فشريكه أحق به حتى يؤذنه ))."],"takhrij":"صحيح: رواه مسلم (١٣٥: ١٦٠٨). وفي رواية عنده: (( قضى رسول الله ﷺ بالشفعة في كل شركة لم تقسم: رَبْعَة أو حائط، لا يحل له أن يبيع حتى يؤذن شريكه، فإن شاء أخذ، وإن شاء ترك، فإذا باع ولم يؤذنه فهو أحق به )).","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1608:135). In another narration with him: “The Messenger of Allah ﷺ ruled with preemption in every undivided partnership: a dwelling or a garden. It is not lawful for him to sell until he informs his partner. If he wishes, he takes it, and if he wishes, he leaves it. If he sells and did not inform him, then he is more entitled to it.”","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “Preemption applies in every shared property, whether land, a dwelling, or a garden. It is not proper for one to sell until he offers it to his partner. He either takes it or leaves it. If he refuses, then his partner is more entitled to it until he informs him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":135}]},{"num":5505,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قال رسول الله ﷺ: (( من كانت له نخل أو أرض فلا يبعها حتى يعرضها على شريكه ))."],"takhrij":"صحيح: رواه النسائي (٤٧٠٠)، وابن ماجه (٢٤٩٢)، وأحمد (١٤٢٩٢).","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4700), Ibn Majah (2492), and Ahmad (14292).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “Whoever has date-palms or land, let him not sell it until he offers it to his partner.”"]},"buhuth":{"ar":["ورواه عبد الرزاق (١٤٤٠٣)، وزاد فيه: (( فإن شاء أخذ، وإن شاء تركه ))."],"en":["Abd al-Razzaq (14403) also narrated it and added: “If he wishes, he takes it, and if he wishes, he leaves it.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4700},{"key":"ibnmajah","label":"ابن ماجه","number":2492},{"key":"ahmad","label":"مسند الإمام أحمد","number":14292,"n":14292}]},{"num":5506,"demo":false,"sanad":"","matn":["عن أبي هريرة أنّ رسول الله ﷺ قضى بالشفعة فيما لم يقسم، فإذا وقعت الحدود فلا شفعة."],"takhrij":"صحيح: رواه ابن ماجه (٢٤٩٧)، وابن حبان في صحيحه (٥١٨٥).","grade":"صحيح","chapter_ar":"باب الشفعة فيما لم يقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2497) and Ibn Hibban in his Sahih (5185).","chapter_en":"Preemption in property that has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ ruled with preemption in what has not been divided, and when the boundaries are fixed, then there is no preemption."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2497},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":5185}]},{"num":5507,"demo":false,"sanad":"","matn":["عن عمرو بن الشريد قال: وقفت على سعد بن أبي وقاص، فجاء المسور بن مخرمة، فوضع يده على إحدى منكبي، إذ جاء أبو رافع مولى النبي ﷺ، فقال: يا سعد، ابتع مني بيتيَّ في دارك. فقال سعد: والله ما أبتاعهما. فقال المسور: والله لتبتاعنهما. فقال سعد: والله لا أزيدك على أربعة آلاف منجَّمة أو مقطَّعة. قال أبو رافع: لقد أعطيت بها خمس مئة دينار، ولولا أنّي سمعت النبي ﷺ يقول: (( الجار أحق بسَقَبِه )) ما أعطيتكها بأربعة آلاف، وأنا أعطى بها خمس مئة دينار، فأعطاها إياه."],"takhrij":"صحيح: رواه البخاري (٢٢٥٨).","grade":"صحيح","chapter_ar":"باب من قال بثبوت الشفعة بالجوار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2258).","chapter_en":"Those who held that preemption is established by neighboring rights","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Amr ibn al-Sharid said: I was standing with Sa‘d ibn Abi Waqqas when al-Miswar ibn Makhramah came and placed his hand on one of my shoulders. Then Abu Rafi‘, the freed slave of the Prophet ﷺ, came and said: O Sa‘d, buy my two houses in your courtyard from me. Sa‘d said: By Allah, I will not buy them. Al-Miswar said: By Allah, you will buy them. Sa‘d said: By Allah, I will not give you more than four thousand in installments. Abu Rafi‘ said: I was offered five hundred dinars for them, and had I not heard the Prophet ﷺ say, “The neighbor is more entitled to his adjoining property,” I would not have given them to you for four thousand while I was being offered five hundred dinars. So he gave them to him."]},"buhuth":{"ar":["قوله: (( منجَّمة أو مقطَّعة )) شك من الراوي، والمراد مؤجلة على أقسام معلومة."],"en":["The wording “munajjaman or muqatta‘an” reflects uncertainty from the narrator. Both indicate payment deferred in known portions."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2258}]},{"num":5508,"demo":false,"sanad":"","matn":["عن الشريد بن سويد قال: قلت: يا رسول الله، أرض ليس فيها لأحد قسم ولا شِرْك إلا الجوار؟ قال: (( الجار أحق بسَقَبِه ))."],"takhrij":"حسن: رواه النسائي (٤٧٠٣)، وابن ماجه (٢٤٩٦)، وأحمد (١٩٤٦١).","grade":"حسن","chapter_ar":"باب من قال بثبوت الشفعة بالجوار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4703), Ibn Majah (2496), and Ahmad (19461).","chapter_en":"Those who held that preemption is established by neighboring rights","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Al-Sharid ibn Suwayd said: I said: O Messenger of Allah ﷺ, there is land in which no one has any share or partnership except neighboring rights. He said: “The neighbor is more entitled to his adjoining property.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4703},{"key":"ibnmajah","label":"ابن ماجه","number":2496},{"key":"ahmad","label":"مسند الإمام أحمد","number":19461,"n":19461}]},{"num":5509,"demo":false,"sanad":"","matn":["عن سمرة بن جندب، عن النبي ﷺ قال: (( جار الدار أحق بدار الجار أو الأرض ))."],"takhrij":"صحيح: رواه أبو داود (٣٥١٧)، والترمذي (١٣٦٨)، وابن الجارود (٦٤٤)، وأحمد (٢٠٠٨٨).","grade":"صحيح","chapter_ar":"باب من قال بثبوت الشفعة بالجوار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3517), al-Tirmidhi (1368), Ibn al-Jarud (644), and Ahmad (20088). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Those who held that preemption is established by neighboring rights","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشفعة","group_en":"Collection of chapters on preemption","part_no":17,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Samurah ibn Jundub narrated from the Prophet ﷺ that he said: “The neighbor of a house has more right to the house of his neighbor, or the land.”"]},"buhuth":{"ar":["قال الترمذي: حسن صحيح.","وقوله: (( السقب )) القرب، ويقال بالسين والصاد جميعًا.","قال الشافعي: قوله: (( الجار أحق بسقبه )) لا يحتمل إلا معنيين لا ثالث لهما: إما أن يكون أراد أن الشفعة لكل جار، أو أراد بعض الجيران دون بعض، وقد ثبت عن رسول الله ﷺ أنه لا شفعة فيما قسم، فدل على أن الشفعة للجار الذي لم يقاسم دون الجار المقاسم."],"en":["The word saqab means nearness or adjacency, and it is pronounced with either the letter sin or sad.","Al-Shafi‘i said: His statement, “The neighbor is more entitled to his adjoining property,” carries only two possible meanings: either he intended preemption for every neighbor, or he intended some neighbors and not others. Since it is established from the Messenger of Allah ﷺ that there is no preemption in property that has been divided, this indicates that preemption is for the neighboring co-owner who has not yet divided the property, not for the separate neighbor whose property is already distinct."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3517},{"key":"tirmidhi","label":"الترمذي","number":1368},{"key":"ابن_الجارود","label":"ابن الجارود","number":644},{"key":"ahmad","label":"مسند الإمام أحمد","number":20088,"n":20088}]},{"num":5510,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري قال: قال النبي ﷺ:","«الْخَازِنُ الْأَمِينُ الَّذِي يُؤَدِّي مَا أُمِرَ بِهِ طَيِّبَةً نَفْسُهُ أَحَدُ الْمُتَصَدِّقِينَ»."],"takhrij":"متفق عليه: رواه البخاري (٢٢٦٠)، ومسلم (١٠٢٣).","grade":"متفق عليه","chapter_ar":"باب استئجار الرجل الصالح الأمين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2260) and Muslim (1023).","chapter_en":"Hiring a righteous and trustworthy person","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī reported that the Prophet ﷺ said:","“The trustworthy treasurer who carries out what he has been commanded to do with a willing heart is one of those who give charity.”"]},"buhuth":{"ar":["فائدة: قال الكرماني: دخول هذا الحديث في باب الإجارة للإشارة إلى أن خازن مال الغير كالأجير لصاحب المال."],"en":["Benefit: Al-Kirmānī said that the inclusion of this hadith in the chapter on hiring indicates that the keeper of another person’s wealth is like an employee of the owner of that wealth."]},"intro":{"ar":["قال الله تعالى: { قَالَتْ إِحْدَاهُمَا يَا أَبَتِ اسْتَأْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ } [القصص: ٢٦]."],"en":["Allah the Exalted said: “One of the two women said: O my father, hire him. Indeed, the best one you can hire is the strong and trustworthy one.” [Al-Qasas: 26]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2260},{"key":"muslim","label":"مسلم","number":1023}]},{"num":5511,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( ما بعث الله نبيًّا إلا رعى الغنم )). فقال أصحابه: وأنت؟ فقال: (( نعم، كنت أرعاها على قراريط لأهل مكة ))."],"takhrij":"صحيح: رواه البخاري (٢٢٦٢).","grade":"صحيح","chapter_ar":"باب الاستئجار على الرضاعة، وسقي الماء، ورعي الغنم، وغيرها من الخدمات","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2262).","chapter_en":"Hiring for breastfeeding, drawing water, shepherding sheep, and other services","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Allah did not send any prophet except that he shepherded sheep.” His companions said: Even you? He said: “Yes, I used to shepherd them for the people of Makkah for a few qirats.”"]},"intro":{"ar":["قال الله تعالى: { فَجَاءَتْهُ إِحْدَاهُمَا تَمْشِي عَلَى اسْتِحْيَاءٍ قَالَتْ إِنَّ أَبِي يَدْعُوكَ لِيَجْزِيَكَ أَجْرَ مَا سَقَيْتَ لَنَا } [القصص: ٢٥].\\n\\nوقال الله تعالى: { فَإِنْ أَرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ } [الطلاق: ٦].\\n\\nوقال تعالى: { فَانْطَلَقَا حَتَّى إِذَا أَتَيَا أَهْلَ قَرْيَةٍ اسْتَطْعَمَا أَهْلَهَا فَأَبَوْا أَنْ يُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ فَأَقَامَهُ قَالَ لَوْ شِئْتَ لَاتَّخَذْتَ عَلَيْهِ أَجْرًا } [الكهف: ٧٧]."],"en":["Allah the Exalted said: “Then one of the two women came to him, walking modestly. She said: Indeed, my father invites you so that he may reward you for having watered for us.” [Al-Qasas: 25]\\n\\nAnd Allah the Exalted said: “Then if they breastfeed for you, give them their wages.” [Al-Talaq: 6]\\n\\nAnd He said: “So they went on until, when they came to the people of a town, they asked its people for food, but they refused to offer them hospitality. Then they found there a wall about to collapse, so he restored it. He said: If you wished, you could have taken payment for it.” [Al-Kahf: 77]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2262}]},{"num":5512,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( قال الله تعالى: ثلاثة أنا خصمهم يوم القيامة: رجل أعطى بي ثم غدر، ورجل باع حرًّا فأكل ثمنه، ورجل استأجر أجيرًا فاستوفى منه ولم يعطه أجره ))."],"takhrij":"صحيح: رواه البخاري (٢٢٧٠).","grade":"صحيح","chapter_ar":"باب الترهيب من منع الأجير أجره، والأمر بتعجيل إعطائه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2270).","chapter_en":"Warning against withholding a worker’s wages and the command to pay promptly","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Allah the Exalted said: There are three whose opponent I will be on the Day of Resurrection: a man who gave his pledge by Me and then betrayed it, a man who sold a free person and consumed his price, and a man who hired a laborer, fully took his work from him, and did not give him his wages.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2270}]},{"num":5513,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( أعطوا الأجير أجره قبل أن يجف عرقه ))."],"takhrij":"حسن: رواه الطحاوي في مشكله (١٤٢/٤)، وابن عدي في الكامل (٢٢٣٥/٦)، والبيهقي في الكبرى (١٢١/٦).","grade":"حسن","chapter_ar":"باب الترهيب من منع الأجير أجره، والأمر بتعجيل إعطائه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Mushkil al-Athar (4/142), Ibn ‘Adi in al-Kamil (6/2235), and al-Bayhaqi in al-Kubra (6/121).","chapter_en":"Warning against withholding a worker’s wages and the command to pay promptly","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Give the worker his wages before his sweat dries.”"]}},"tuhfa":{},"refs":[{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":142},{"key":"ابن_عدی/الکامل","label":"ابن عدي في الكامل","number":2235},{"key":"البیہقی/الکبری","label":"البيهقي في الكبرى","number":121},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11659,"n":11766}]},{"num":5514,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر بن الخطاب رضي الله عنهما أن رسول الله ﷺ قال: (( إنما مثلكم واليهود والنصارى كرجل استعمل عمّالًا، فقال: من يعمل لي إلى نصف النهار على قيراط قيراط؟ فعملت اليهود على قيراط قيراط، ثم عملت النصارى على قيراط قيراط، ثم أنتم الذين تعملون من صلاة العصر إلى مغارب الشمس على قيراطين قيراطين، فغضبت اليهود والنصارى، وقالوا: نحن أكثر عملًا وأقل عطاءً. قال: هل ظلمتكم من حقكم شيئًا؟ قالوا: لا. فقال: فذلك فضلي أوتيه من أشاء ))."],"takhrij":"صحيح: رواه البخاري (٢٢٦٩).","grade":"صحيح","chapter_ar":"باب الإجارة على عمل لمدة نصف يوم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2269).","chapter_en":"Hiring for work lasting half a day","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Abdullah ibn Umar ibn al-Khattab, may Allah be pleased with them both, narrated that the Messenger of Allah ﷺ said: “Your example and that of the Jews and Christians is like a man who hired workers and said: Who will work for me until midday for one qirat each? So the Jews worked for one qirat each. Then the Christians worked for one qirat each. Then you are the ones who work from the afternoon prayer until sunset for two qirats each. So the Jews and Christians became angry and said: We did more work and received less pay. He said: Have I wronged you in any of your due? They said: No. He said: That is My favor; I give it to whom I will.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2269}]},{"num":5515,"demo":false,"sanad":"","matn":["عن أبي موسى، عن النبي ﷺ قال: (( مثل المسلمين واليهود والنصارى كمثل رجل استأجر قومًا يعملون له عملًا يومًا إلى الليل على أجر معلوم، فعملوا له نصف النهار، فقالوا: لا حاجة لنا إلى أجرك الذي شرطت لنا، وما عملنا باطل. فقال لهم: لا تفعلوا، أكملوا بقية عملكم وخذوا أجركم كاملًا. فأبوا وتركوا. واستأجر آخرين بعدهم، فقال لهم: أكملوا بقية يومكم هذا، ولكم الذي شرطت لهم من الأجر، فعملوا حتى إذا كان حين صلاة العصر قالوا: لك ما عملنا باطل، ولك الأجر الذي جعلت لنا فيه. فقال لهم: أكملوا بقية عملكم، فإن ما بقي من النهار شيء يسير. فأبوا، فاستأجر قومًا أن يعملوا له بقية يومهم، فعملوا بقية يومهم حتى غابت الشمس، واستكملوا أجر الفريقين كليهما، فذلك مثلهم ومثل ما قبلوا من هذا النور ))."],"takhrij":"صحيح: رواه البخاري (٢٢٧١).","grade":"صحيح","chapter_ar":"باب الإجارة على عمل لمدة يوم كامل","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2271).","chapter_en":"Hiring for work lasting a full day","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Abu Musa narrated from the Prophet ﷺ that he said: “The example of the Muslims, Jews, and Christians is like a man who hired people to work for him for a day until nightfall for a known wage. They worked for him until midday, then said: We have no need for the wage you stipulated for us, and what we have done is worthless. He said to them: Do not do that. Complete the rest of your work and take your full wage. But they refused and left. Then he hired others after them and said to them: Complete the rest of this day, and you shall have the wage that I had stipulated for them. So they worked until the time of the afternoon prayer, then said: What we did is worthless for you, and you may keep the wage you assigned to us. He said to them: Complete the rest of your work, for what remains of the day is only a little. But they refused. Then he hired another people to work the remainder of the day, and they worked until the sun set, and they took the wages of both groups in full. That is their example and the example of what they accepted from this light.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2271}]},{"num":5516,"demo":false,"sanad":"","matn":["عن يعلى بن أمية قال: غزوت مع النبي ﷺ جيش العسرة، فكان من أوثق أعمالي في نفسي، فكان لي أجير، فقاتل إنسانًا، فعض أحدهما إصبع صاحبه، فانتزع إصبعه، فأندر ثنيته، فسقطت، فانطلق إلى النبي ﷺ، فأهدر ثنيته، وقال: (( أفيَدَع إصبعه في فيك تقضمها - قال: أحسبه قال: - كما يقضم الفحل؟ ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢٦٥)، ومسلم (٢٣: ١٦٧٤). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب اتخاذ الأجير في الغزو","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2265) and Muslim (1674:23). The wording is al-Bukhari’s.","chapter_en":"Taking an employee along in military expeditions","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Ya‘la ibn Umayyah said: I went out with the Prophet ﷺ in the Army of Hardship, and that was among the most dependable of my deeds in my own sight. I had an employee with me. He fought a man, and one of them bit the finger of the other. The man pulled his finger away, and the other man’s incisor tooth fell out. He went to the Prophet ﷺ, but he ruled the tooth loss as uncompensated and said: “Should he leave his finger in your mouth for you to chew on it — he said: I think he said — like a stallion bites?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2265},{"key":"muslim","label":"مسلم","number":23}]},{"num":5517,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ قالت: واستأجر رسول الله ﷺ وأبو بكر رجلًا من بني الديل هاديًا خِرِّيتًا، وهو على دين كفار قريش، فدفعا إليه راحلتيهما، وواعداه غار ثور بعد ثلاث ليال، فأتاهما براحلتيهما صبح ثلاث."],"takhrij":"صحيح: رواه البخاري (٢٢٦٤).","grade":"صحيح","chapter_ar":"باب استئجار الكافر عند الحاجة إليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2264).","chapter_en":"Hiring a disbeliever when there is need for him","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Aisha, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ and Abu Bakr hired a man from Banu al-Dil as a guide who was highly skilled in navigation, while he was still upon the religion of the disbelievers of Quraysh. They entrusted their two riding animals to him and arranged to meet him at the Cave of Thawr after three nights. He came to them with their riding animals on the morning of the third day."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2264}]},{"num":5518,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: انطلق نفر من أصحاب النبي ﷺ في سفرة سافروها حتى نزلوا على حي من أحياء العرب، فاستضافوهم، فأبوا أن يضيفوهم، فلدغ سيد ذلك الحي، فسعوا له بكل شيء لا ينفعه شيء. فقال بعضهم: لو أتيتم هؤلاء الرهط الذين نزلوا، لعله أن يكون عند بعضهم شيء. فأتوهم، فقالوا: يا أيها الرهط، إن سيدنا لُدغ، وسعينا له بكل شيء لا ينفعه، فهل عند أحد منكم من شيء؟ فقال بعضهم: نعم، والله إني لأرقي، ولكن والله لقد استضفناكم فلم تضيفونا، فما أنا براقٍ لكم حتى تجعلوا لنا جُعلًا. فصالحوهم على قطيع من الغنم، فانطلق يتفل عليه ويقرأ: { الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ }، فكأنما نُشِط من عقال، فانطلق يمشي وما به قلبة. قال: فأوفوهم جُعلهم الذي صالحوهم عليه. فقال بعضهم: اقسموا. فقال الذي رقى: لا تفعلوا حتى نأتي النبي ﷺ، فنذكر له الذي كان، فننظر ما يأمرنا. فقدموا على رسول الله ﷺ، فذكروا له، فقال: (( وما يدريك أنها رقية؟ )) ثم قال: (( قد أصبتم، اقسموا، واضربوا لي معكم سهمًا )). فضحك النبي ﷺ."],"takhrij":"متفق عليه: رواه البخاري (٢٢٧٦)، ومسلم (٦٥: ٢٢٠١). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب أخذ الأجرة على تعليم القرآن والرقية به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2276) and Muslim (2201:65). The wording is al-Bukhari’s.","chapter_en":"Taking payment for teaching the Quran and for healing by it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: A group of the Companions of the Prophet ﷺ set out on a journey until they came to one of the Arab tribes. They asked them for hospitality, but they refused to host them. Then the chief of that tribe was stung, and they tried everything for him, but nothing helped. Some of them said: Go to those people who have camped here; perhaps one of them has something. So they came to them and said: O people, our chief has been stung, and we have tried everything for him but nothing has benefited him. Does any one of you have anything? One of them said: Yes, by Allah, I do healing recitation, but by Allah, we asked you for hospitality and you did not host us, so I will not recite for you unless you assign us a payment. So they agreed on a flock of sheep. Then he went and spat lightly while reciting: “All praise is for Allah, Lord of the worlds,” and it was as if the man had been released from a rope. He got up walking, and there was nothing wrong with him. They then gave them the payment they had agreed on. Some of them said: Divide it. But the one who recited said: Do not do that until we go to the Prophet ﷺ and mention to him what happened, then we will see what he commands us. So they came to the Messenger of Allah ﷺ and mentioned it to him. He said: “How did you know that it is a healing recitation?” Then he said: “You did right. Divide it, and give me a share with you.” Then the Prophet ﷺ laughed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2276},{"key":"muslim","label":"مسلم","number":65}]},{"num":5519,"demo":false,"sanad":"","matn":["عن ابن عباس أن نفرًا من أصحاب رسول الله ﷺ مروا بماء فيهم لديغ - أو سليم - فعرض لهم رجل من أهل الماء، فقال: هل فيكم من راقٍ؟ إن في الماء رجلًا لديغًا - أو سليمًا - فانطلق رجل منهم، فقرأ بفاتحة الكتاب على شاء، فبرأ، فجاء بالشاء إلى أصحابه، فكرهوا ذلك، وقالوا: أخذت على كتاب الله أجرًا، حتى قدموا المدينة، فقالوا: يا رسول الله، أخذ على كتاب الله أجرًا؟ فقال رسول الله ﷺ: (( إن أحق ما أخذتم عليه أجرًا كتاب الله ))."],"takhrij":"صحيح: رواه البخاري (٥٧٣٧).","grade":"صحيح","chapter_ar":"باب أخذ الأجرة على تعليم القرآن والرقية به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5737).","chapter_en":"Taking payment for teaching the Quran and for healing by it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Ibn Abbas narrated that a group of the Companions of the Messenger of Allah ﷺ passed by a place of water where there was a man who had been stung — or bitten by something poisonous. A man from the people of the water came to them and said: Is there anyone among you who can perform healing recitation? At the water there is a man who has been stung — or bitten. So one of them went and recited Surat al-Fatihah over him in exchange for a sheep, and the man recovered. He then came with the sheep to his companions, but they disliked that and said: You took payment for the Book of Allah. When they came to Madinah they said: O Messenger of Allah ﷺ, he took payment for the Book of Allah. So the Messenger of Allah ﷺ said: “The most rightful thing for which you may take payment is the Book of Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5737}]},{"num":5520,"demo":false,"sanad":"","matn":["عن خارجة بن الصلت، عن عمه:","أنه مر بقوم، فأتوه، فقالوا:","إنك جئت من عند هذا الرجل بخير، فارق لنا هذا الرجل.","فأتوه برجل معتوه في القيود، فرقاه بأم القرآن ثلاثة أيام غدوة وعشية، وكلما ختمها جمع بزاقه ثم تفل، فكأنما أُنْشِط من عقال.","فأعطوه شيئًا، فأتى النبي ﷺ فذكره له، فقال النبي ﷺ:","«كُلْ، فَلَعَمْرِي لَمَنْ أَكَلَ بِرُقْيَةِ بَاطِلٍ، لَقَدْ أَكَلْتَ بِرُقْيَةِ حَقٍّ».","وفي رواية:","فأعطوه مائة شاة."],"takhrij":"حسن: رواه أبو داود (٣٩٠١، ٣٨٩٧، ٣٨٩٦، ٣٤٢٠)، وابن ماجه (٢١٥٦)، وأحمد (٢١٨٣٥)، وصححه ابن حبان (٦١١٠)، والحاكم (١/٥٥٩-٥٦٠).","grade":"حسن","chapter_ar":"باب أخذ الأجرة على تعليم القرآن والرقية به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3901, 3897, 3896, 3420), Ibn Mājah (2156), and Aḥmad (21835), and authenticated by Ibn Ḥibbān (6110) and al-Ḥākim (1/559–560).","chapter_en":"Taking payment for teaching the Quran and for healing by it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["Khārijah ibn al-Ṣalt narrated from his uncle that he passed by some people. They came to him and said:","“You have come from this man with something good, so perform a healing recitation for this man.”","They brought him a mentally afflicted man who was restrained in chains. He recited Umm al-Qurʾān over him for three days, morning and evening. Whenever he completed the recitation, he gathered his saliva and lightly blew upon him. The man then became as though he had been released from a restraint.","They gave him something in payment, so he came to the Prophet ﷺ and mentioned it to him. The Prophet ﷺ said:","“Eat it. By my life, there are those who consume wealth through false incantations, but you have earned through a true healing recitation.”","In another narration:","“They gave him one hundred sheep.”"]},"buhuth":{"ar":["فقه هذا الباب: أحاديث هذا الباب تدل على جواز أخذ الأجرة على تعليم القرآن وجواز شرطه. وفيه دليل على جواز الرقية بالقرآن؛ لأن القراءة والرقية من الأعمال المباحة، وقد أباح له أخذ الأجرة، كأخذ الطبيب ما يفعله من قول أو فعل.","وكان بالمدينة ثلاثة معلمين يعلمون الصبيان، وكان عمر بن الخطاب يرزق كل واحد منهم خمسة عشر درهمًا كل شهر. رواه أبو بكر بن أبي شيبة (٤/٣٤٦ رقم ٢٠٢٨)."],"en":["The jurisprudence of this chapter: These hadiths establish the permissibility of taking payment for teaching the Qurʾān and of stipulating such payment. They also establish the permissibility of ruqyah with the Qurʾān, because recitation and ruqyah are lawful acts, and taking payment for them was permitted, just as a physician may take payment for treatment by word or deed.","There were three teachers in Madinah who taught children, and ʿUmar ibn al-Khaṭṭāb used to allocate fifteen dirhams each month to each of them. Narrated by Abū Bakr ibn Abī Shaybah (4/346, no. 2028)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3901},{"key":"ibnmajah","label":"ابن ماجه","number":2156},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":6110},{"key":"hakim","label":"الحاكم","number":1},{"key":"ahmad","label":"مسند الإمام أحمد","number":21835,"n":21835}]},{"num":5521,"demo":false,"sanad":"","matn":["عن عبادة بن الصامت قال: كان رسول الله ﷺ يُشْغَلُ، فإذا قدم رجل مهاجر على رسول الله ﷺ دفعه إلى رجل منا يعلمه القرآن، فدفع إليَّ رسول الله ﷺ رجلًا، فكان معي في البيت، أعشِّيه عشاء أهل البيت، فكنت أقرئه القرآن، فانصرف انصرافةً إلى أهله، فرأى أن عليه حقًّا، فأهدى إليَّ قوسًا لم أر أجود منها عودًا، ولا أحسن منها عِطفًا، فأتيت رسول الله ﷺ، فقلت: ما ترى يا رسول الله فيها؟ قال: (( جمرة بين كتفيك تقلّدتها، أو تعلّقتها ))."],"takhrij":"حسن بالمتابعة: رواه أبو داود (٣٤١٦، ٣٤١٧)، وأحمد (٢٢٧٦٦)، والحاكم (٣٥٦/٣)، واللفظ لأحمد.","grade":"حسن بالمتابعة","chapter_ar":"باب من كره أخذ الأجرة على تعليم القرآن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan by corroboration: Narrated by Abu Dawud (3416, 3417), Ahmad (22766), and al-Hakim (3/356). The wording is Ahmad’s.","chapter_en":"Those who disliked taking payment for teaching the Quran","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Ubadah ibn al-Samit said: The Messenger of Allah ﷺ would be occupied, and when a migrant came to the Messenger of Allah ﷺ, he would hand him over to one of us to teach him the Quran. So the Messenger of Allah ﷺ entrusted a man to me, and he stayed with me in the house. I would feed him as the family of the house ate, and I would teach him the Quran. Then he returned to his family for a time and felt that he owed me something, so he gave me a bow as a gift. I had never seen a bow better in wood nor finer in curve than it. So I came to the Messenger of Allah ﷺ and said: What do you think of it, O Messenger of Allah ﷺ? He said: “It is a live coal between your shoulders that you have hung there,” or “that you have fastened there.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3416},{"key":"hakim","label":"الحاكم","number":356},{"key":"ahmad","label":"مسند الإمام أحمد","number":22766,"n":22766}]},{"num":5522,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن شبل قال: سمعت رسول الله ﷺ يقول: (( اقرؤوا القرآن، ولا تغلوا فيه، ولا تجفوا عنه، ولا تأكلوا به، ولا تستكثروا به ))."],"takhrij":"صحيح: رواه الإمام أحمد (١٥٥٢٩)، والمستغفري في فضائل القرآن (٥).","grade":"صحيح","chapter_ar":"باب من كره أخذ الأجرة على تعليم القرآن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (15529) and al-Mustaghfiri in Fada’il al-Quran (5).","chapter_en":"Those who disliked taking payment for teaching the Quran","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abd al-Rahman ibn Shibl said: I heard the Messenger of Allah ﷺ say: “Recite the Quran, but do not go to excess concerning it, do not turn away from it, do not consume by means of it, and do not seek abundance through it.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":15529},{"key":"المستغفری/فضایل_القران","label":"المستغفري في فضائل القرآن","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":15529,"n":15529}]},{"num":5523,"demo":false,"sanad":"","matn":["عن أبي الدرداء أن رسول الله ﷺ قال: (( من أخذ قوسًا على تعليم القرآن قلّده الله قوسًا من نار ))."],"takhrij":"حسن: رواه البيهقي (١٢٦/٦).","grade":"حسن","chapter_ar":"باب من كره أخذ الأجرة على تعليم القرآن","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (6/126).","chapter_en":"Those who disliked taking payment for teaching the Quran","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abu al-Darda narrated that the Messenger of Allah ﷺ said: “Whoever takes a bow as payment for teaching the Quran, Allah will collar him with a bow of fire.”"]},"buhuth":{"ar":["فقه هذا الباب: أحاديث هذا الباب تدل على كراهة أخذ الأجرة على تعليم القرآن.","واختلف أهل العلم في بعض الصور دون الأخرى:","فمنهم من جعل الكراهة إذا اشترط بذلك. ومنهم من جعل الكراهة إذا كان عمل حسبة لله، فليس له أن يأخذ عليه أجرًا؛ لأن الأجر منافٍ للحسبة. وأما إن لم يطلب ولم يشترط عليه الأجرة فجائز كما في حديث ابن عباس في الباب السابق. ومنهم من قال: إذا لم يوجد في المسلمين من يعلم القرآن إلا شخص واحد فعليه أن يعلمهم، ولا يأخذ عليه أجرًا؛ لأن تعليمه إياهم صار عليه فرض عين، بخلاف إذا كان فيهم غيره، فجاز له أخذ الأجرة.","أما إذا كان هذا الأجر من الحاكم الذي هو الراعي لمصلحة الأمة فلا كراهة في ذلك بالاتفاق؛ لأن تحديد الأجر منه يساعد على إدارة شؤون البلاد، وهذا الذي جرى عليه العمل منذ الخلفاء الراشدين إلى يومنا هذا."],"en":["The understanding of this chapter is that its hadiths indicate the dislike of taking payment for teaching the Quran.","The scholars differed regarding some situations and not others:","Among them were those who held that the dislike applies if payment is made a condition. Others said the dislike applies when the work is done purely for Allah’s sake as a religious service, so he should not take wages for it, because payment conflicts with that intention. But if he neither asked for nor stipulated payment, then it is permissible, as in the hadith of Ibn Abbas in the previous chapter. Others said that if there is no one among the Muslims to teach the Quran except one person, then he must teach them and should not take payment, because teaching them becomes a personal obligation on him. But if there are others besides him, then taking payment is permissible.","As for when this payment comes from the ruler, who oversees the interests of the community, then there is no dislike in that by agreement, because setting such wages helps in managing the affairs of the land. This has been the established practice from the Rightly Guided Caliphs until today."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":126},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11685,"n":11792}]},{"num":5524,"demo":false,"sanad":"","matn":["عن ابن عمر أن عمر بن الخطاب أجلى اليهود والنصارى من أرض الحجاز، وأن رسول الله ﷺ لما ظهر على خيبر أراد إخراج اليهود منها. وكانت الأرض حين ظهر عليها لله ولرسوله وللمسلمين، فأراد إخراج اليهود منها، فسألت اليهود رسول الله ﷺ أن يتركهم بها على أن يكفوا عملها، ولهم نصف الثمر. فقال لهم رسول الله ﷺ: (( نقركم بها على ذلك ما شئنا )). فقرّوا بها حتى أجلاهم عمر إلى تيماء وأريحاء."],"takhrij":"متفق عليه: رواه البخاري (٢٣٣٨)، ومسلم (٦/١٥٥١).","grade":"متفق عليه","chapter_ar":"باب يجوز للإمام فسخ المعاهدة مع الكفار إذا اشترط عليهم أنه يقرهم إلى متى شاء وهم قد رضوا بذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2338) and Muslim (1551:6).","chapter_en":"It is permissible for the ruler to terminate a treaty with disbelievers if he stipulated that he would let them remain only as long as he wished and they agreed to that","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الإجارة","group_en":"Collection of what has come regarding hiring and wages","part_no":17,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["Ibn Umar narrated that Umar ibn al-Khattab expelled the Jews and Christians from the land of the Hijaz. When the Messenger of Allah ﷺ gained victory over Khaybar, he wanted to expel the Jews from it. The land, when he gained control over it, belonged to Allah, His Messenger, and the Muslims. So he intended to remove the Jews from it, but the Jews asked the Messenger of Allah ﷺ to leave them there on the condition that they would do the labor on it and receive half of the produce. So the Messenger of Allah ﷺ said to them: “We will let you remain there upon that for as long as we wish.” So they remained there until Umar expelled them to Tayma and Ariha."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2338},{"key":"muslim","label":"مسلم","number":6}]},{"num":5525,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول الله ﷺ أنه ذكر رجلًا من بني إسرائيل، سأل بعض بني إسرائيل أن يسلفه ألف دينار، فقال: ائتني بالشهداء أشهدهم. فقال: كفى بالله شهيدًا. قال: فأتني بالكفيل. قال: كفى بالله كفيلًا. قال: صدقت. فدفعها إليه على أجل مسمى، فخرج في البحر، فقضى حاجته، ثم التمس مركبًا يركبها يقدم عليه للأجل الذي أجله، فلم يجد مركبًا، فأخذ خشبة، فنقرها، فأدخل فيها ألف دينار وصحيفة منه إلى صاحبه، ثم زجج موضعها، ثم أتى بها إلى البحر، فقال: اللهم إنك تعلم أني كنت تسلفت فلانًا ألف دينار، فسألني كفيلًا، فقلت: كفى بالله كفيلًا، فرضي بك. وسألني شهيدًا، فقلت: كفى بالله شهيدًا، فرضي بك. وإني جهدت أن أجد مركبًا أبعث إليه الذي له فلم أقدر، وإني أستودعكها. فرمى بها في البحر حتى ولجت فيه، ثم انصرف، وهو في ذلك يلتمس مركبًا يخرج إلى بلده. فخرج الرجل الذي كان أسلفه ينظر لعل مركبًا قد جاء بماله، فإذا بالخشبة التي فيها المال، فأخذها لأهله حطبًا، فلما نشرها وجد المال والصحيفة، ثم قدم الذي كان أسلفه، فأتى بالألف دينار، فقال: والله ما زلت جاهدًا في طلب مركب لآتيك بمالك، فما وجدت مركبًا قبل الذي أتيت فيه. قال: هل كنت بعثت إلي بشيء؟ قال: أخبرك أني لم أجد مركبًا قبل الذي جئت فيه. قال: فإن الله قد أدى عنك الذي بعثت في الخشبة، فانصرف بالألف الدينار راشدًا ))."],"takhrij":"صحيح: رواه البخاري (٢٢٩١).","grade":"صحيح","chapter_ar":"باب مشروعية الكفالة في القروض والديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2291).","chapter_en":"The legality of surety in loans and debts","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated from the Messenger of Allah ﷺ that he mentioned a man from the Children of Israel who asked another man from the Children of Israel to lend him one thousand dinars. He said: Bring me witnesses so I may have them witness it. He said: Allah is sufficient as a witness. He said: Then bring me a guarantor. He said: Allah is sufficient as a guarantor. He said: You have spoken the truth. So he gave it to him for a fixed term. Then the borrower traveled by sea and fulfilled his need. Afterward he looked for a vessel on which he could travel to return the money by the appointed time, but he found none. So he took a piece of wood, hollowed it out, placed in it the one thousand dinars and a letter to its owner, then sealed it, brought it to the sea, and said: O Allah, You know that I borrowed one thousand dinars from so-and-so. He asked me for a guarantor and I said: Allah is sufficient as a guarantor, and he was satisfied with You. He asked me for a witness and I said: Allah is sufficient as a witness, and he was satisfied with You. I have tried hard to find a vessel to send him what belongs to him, but I could not, so I entrust it to You. Then he threw it into the sea until it entered it, and he went away, while still looking for a vessel to travel to his land. The man who had given the loan went out, hoping that a ship might have arrived with his money, and he found the piece of wood containing the money. He took it home as firewood. When he split it open, he found the money and the letter. Later, the borrower arrived carrying the one thousand dinars and said: By Allah, I kept striving to find a vessel to bring you your money, but I found none before the one by which I have now come. The lender said: Did you send me anything? He said: I am telling you that I found no vessel before the one by which I came. He said: Allah has delivered on your behalf what you sent in the wood, so return with your thousand dinars, rightly guided."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2291}]},{"num":5526,"demo":false,"sanad":"","matn":["عن ابن عباس أن رجلًا لزم غريمًا له بعشرة دنانير، فقال: والله لا أفارقك حتى تقضيني، أو تأتيني بحميل. فتحمّل بها النبي ﷺ، فأتاه بقدر ما وعده، فقال له النبي ﷺ: (( من أين أصبت هذا الذهب؟ )) قال: من معدن. قال: (( لا حاجة لنا فيها، وليس فيها خير )). فقضاه عنه رسول الله ﷺ."],"takhrij":"حسن: رواه أبو داود (٣٣٢٨)، وابن ماجه (٢٤٠٦)، وعبد بن حميد (٥٩٦)، والحاكم (٢١٦١)، واللفظ لأبي داود. وفي لفظ غيره: فقال له النبي ﷺ: (( كم تستنظره؟ )) فقال: شهرًا. فقال رسول الله ﷺ: (( فأنا أحمل له )).","grade":"حسن","chapter_ar":"باب مشروعية الكفالة في القروض والديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3328), Ibn Majah (2406), Abd ibn Humayd (596), and al-Hakim (2161). The wording is Abu Dawud’s. In another wording: the Prophet ﷺ said to him, “How long will you give him?” He said: One month. So the Messenger of Allah ﷺ said: “Then I will stand surety for him.”","chapter_en":"The legality of surety in loans and debts","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas narrated that a man pressed a debtor of his for ten dinars and said: By Allah, I will not leave you until you pay me or bring me a surety. Then the Prophet ﷺ guaranteed it for him. Later the debtor came with the amount he had promised, and the Prophet ﷺ said to him: “From where did you get this gold?” He said: From a mine. He said: “We have no need of it, and there is no good in it.” Then the Messenger of Allah ﷺ paid it off on his behalf."]},"buhuth":{"ar":["وقوله: (( لا حاجة لنا فيها )) لأنه تحمل عنه دنانير مضروبة كانت تحمل إليهم من بلاد الروم؛ لأنه أول من وضع السكة في الإسلام وضرب الدنانير عبد الملك بن مروان، كما هو معروف. والذي جاء به ذهبٌ غير مضروب، فتنزّه النبي ﷺ عن القبول."],"en":["His statement, “We have no need of it,” was because the Prophet ﷺ had guaranteed coined dinars that used to be brought to them from the Roman lands, since the first person to establish Islamic minting and strike dinars was Abd al-Malik ibn Marwan, as is well known. What the man brought was unminted gold, so the Prophet ﷺ refrained from accepting it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3328},{"key":"ibnmajah","label":"ابن ماجه","number":2406},{"key":"عبد_بن_حمید","label":"عبد بن حميد","number":596},{"key":"hakim","label":"المستدرك على الصحيحين","number":2161,"n":2152}]},{"num":5527,"demo":false,"sanad":"","matn":["عن سلمة بن الأكوع:","أن النبي ﷺ أُتي بجنازة ليصلي عليها، فقال:","«هَلْ عَلَيْهِ مِنْ دَيْنٍ؟»","قالوا: لا.","فصلى عليه.","ثم أُتي بجنازة أخرى، فقال:","«هَلْ عَلَيْهِ مِنْ دَيْنٍ؟»","قالوا: نعم.","قال:","«صَلُّوا عَلَى صَاحِبِكُمْ».","قال أبو قتادة:","عليَّ دينه يا رسول الله.","فصلى عليه."],"takhrij":"صحيح: رواه البخاري (٢٢٩٥).","grade":"صحيح","chapter_ar":"باب ما جاء في الضمان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2295).","chapter_en":"What has come regarding guarantee","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ reported:","A deceased person was brought to the Prophet ﷺ so that he might perform the funeral prayer over him. He asked:","“Does he owe any debt?”","They replied:","“No.”","So he prayed over him.","Then another deceased person was brought. He asked:","“Does he owe any debt?”","They replied:","“Yes.”","He said:","“Pray over your companion.”","Abū Qatādah said:","“O Messenger of Allah ﷺ, I will take responsibility for his debt.”","So the Prophet ﷺ prayed over him."]},"intro":{"ar":["قال الله تعالى: { قَالُوا نَفْقِدُ صُوَاعَ الْمَلِكِ وَلِمَن جَاءَ بِهِ حِمْلُ بَعِيرٍ وَأَنَا بِهِ زَعِيمٌ } [يوسف: ٧٢].","والزعيم والحميل والكفيل بمعنى واحد، فالزعيم لغة أهل المدينة، والحميل لغة أهل مضر، والكفيل لغة أهل العراق، أي أن من تكفّل دينًا عن الغير عليه الغرم، وهو الضمان."],"en":["Allah the Exalted said: “They said: We have lost the king’s measuring cup, and whoever brings it shall have a camel-load, and I am a guarantor for it.” [Yusuf: 72]","The words guarantor, surety, and sponsor all carry one meaning. “Zaim” is the term used by the people of Madinah, “hamil” by the people of Mudar, and “kafil” by the people of Iraq. The meaning is that whoever takes responsibility for another person’s debt becomes liable for it. This is guarantee."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2295}]},{"num":5528,"demo":false,"sanad":"","matn":["عن أبي أمامة الباهلي قال: سمعت رسول الله ﷺ يقول: (( الزعيم غارم، والدين مقضي ))."],"takhrij":"حسن: رواه أبو داود (٣٥٦٥)، والترمذي (١٢٦٥)، وابن ماجه (٢٤٠٥)، والبيهقي (١٧٢/٦)، وأحمد (٢٢٢٩٤).","grade":"حسن","chapter_ar":"باب ما جاء في الضمان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3565), al-Tirmidhi (1265), Ibn Majah (2405), al-Bayhaqi (6/172), and Ahmad (22294).","chapter_en":"What has come regarding guarantee","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Umamah al-Bahili said: I heard the Messenger of Allah ﷺ say: “The guarantor is liable, and the debt must be paid.”"]},"buhuth":{"ar":["وهو حديث طويل ذُكرت أجزاؤه مفرقة في كتب السنة، وكامله - كما ذكر أحمد وغيره - أن النبي ﷺ خطب عام حجة الوداع، فقال: (( إن الله قد أعطى كل ذي حق حقه؛ فلا وصية لوارث، والولد للفراش وللعاهر الحجر، وحسابهم على الله، ومن ادعى إلى غير أبيه أو انتمى إلى غير مواليه فعليه لعنة الله التابعة إلى يوم القيامة. لا تنفق المرأة شيئًا من بيتها إلا بإذن زوجها )). قيل: يا رسول الله، ولا الطعام؟ قال: (( ذلك أفضل أموالنا )). ثم قال: (( العارية مؤداة، والمنحة مردودة، والدين مقضي، والزعيم غارم )). قال الترمذي: حسن غريب."],"en":["This is part of a long hadith whose portions are scattered throughout the books of Sunnah. Its full wording — as mentioned by Ahmad and others — is that the Prophet ﷺ gave a sermon during the Farewell Pilgrimage and said: “Allah has given every person with a right his due, so there is no bequest for an heir. The child belongs to the marriage bed, and the adulterer gets the stone, and their reckoning is with Allah. Whoever claims lineage to someone other than his father or attaches himself to other than his patrons, then upon him is the continuous curse of Allah until the Day of Resurrection. A woman must not spend anything from her house except with the permission of her husband.” It was said: O Messenger of Allah ﷺ, not even food? He said: “That is the best of our wealth.” Then he said: “A borrowed item must be returned, a granted loaned animal must be returned, the debt must be paid, and the guarantor is liable.” Al-Tirmidhi said: Hasan Gharib."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3565},{"key":"tirmidhi","label":"الترمذي","number":1265},{"key":"ibnmajah","label":"ابن ماجه","number":2405},{"key":"البیہقی","label":"البيهقي","number":172},{"key":"ahmad","label":"مسند الإمام أحمد","number":22294,"n":22294}]},{"num":5529,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال: (( مطل الغني ظلم، وإذا أُتبع أحدكم على مليء فليتبع ))."],"takhrij":"متفق عليه: رواه مالك (٨٤)، والبخاري (٢٢٨٧)، ومسلم (١٥٦٤).","grade":"متفق عليه","chapter_ar":"باب قبول الحوالة إذا أحيل على مليء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (84), al-Bukhari (2287), and Muslim (1564).","chapter_en":"Accepting a transfer of debt when one is transferred to a solvent person","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الكفالة والضمان والحوالة","group_en":"Collection of chapters on surety, guarantee, and transfer of debt","part_no":17,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “The delay of a wealthy person in paying is injustice, and if one of you is referred to a solvent person, then let him follow that transfer.”"]},"buhuth":{"ar":["قوله: (( مطل الغني )) أصل المطل المد، يقال: مطلت الحديدة إذا مددتها لتطول. والمراد تأخير ما استحق بلا عذر. ومعناه إذا أحيل أحدكم على مليء فليتبع، فقال بعض أهل العلم: إذا أحيل الرجل على مليء فاحتاله، فقد برئ المحيل، وليس له أن يرجع على المحيل، وهو قول الشافعي، وأحمد، وإسحاق. ذكره الترمذي (١٣٠٨)."],"en":["The phrase “the delay of a wealthy person” comes from a root meaning stretching or prolonging, such as when metal is stretched to make it longer. The intended meaning here is delaying payment of what is due without excuse. Its meaning is that if one of you is transferred to a solvent debtor, he should accept the transfer. Some scholars said that if a person is transferred to a solvent debtor and accepts the transfer, then the original debtor is cleared, and he cannot go back to the original debtor. This is the view of al-Shafi‘i, Ahmad, and Ishaq. Al-Tirmidhi mentioned this (1308)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":84},{"key":"bukhari","label":"البخاري","number":2287},{"key":"muslim","label":"مسلم","number":1564}]},{"num":5530,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: وكّلني رسول الله ﷺ بحفظ زكاة رمضان، فأتاني آتٍ، فجعل يحثو من الطعام، فأخذته، وقلت: والله لأرفعنك إلى رسول الله ﷺ. قال: إني محتاج، وعلي عيال، ولي حاجة شديدة. قال: فخليت عنه، فأصبحت، فقال النبي ﷺ: (( يا أبا هريرة، ما فعل أسيرك البارحة؟ )) قال: قلت: يا رسول الله، شكا حاجة شديدة وعيالًا، فرحمته، فخليت سبيله. قال: (( أما إنه قد كذبك، وسيعود )). فعرفت أنه سيعود لقول رسول الله ﷺ: إنه سيعود، فرصدته، فجاء يحثو من الطعام، فأخذته، فقلت: لأرفعنك إلى رسول الله ﷺ. قال: دعني؛ فإني محتاج، وعلي عيال، لا أعود. فرحمته، فخليت سبيله، فأصبحت، فقال لي رسول الله ﷺ: (( يا أبا هريرة، ما فعل أسيرك؟ )) قلت: يا رسول الله، شكا حاجة شديدة وعيالًا، فرحمته، فخليت سبيله. قال: (( أما إنه قد كذبك، وسيعود )). فرصدته الثالثة، فجاء يحثو من الطعام، فأخذته، فقلت: لأرفعنك إلى رسول الله ﷺ، وهذا آخر ثلاث مرات أنك تزعم لا تعود، ثم تعود. قال: دعني أعلمك كلمات ينفعك الله بها. قلت: ما هو؟ قال: إذا أويت إلى فراشك، فاقرأ آية الكرسي: { اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ } حتى تختم الآية، فإنك لن يزال عليك من الله حافظ، ولا يقربنك شيطان حتى تصبح. فخليت سبيله، فأصبحت، فقال لي رسول الله ﷺ: (( ما فعل أسيرك البارحة؟ )) قلت: يا رسول الله، زعم أنه يعلمني كلمات ينفعني الله بها، فخليت سبيله. قال: (( ما هي؟ )) قلت: قال لي: إذا أويت إلى فراشك فاقرأ آية الكرسي من أولها حتى تختم الآية: { اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ }، وقال لي: لن يزال عليك من الله حافظ، ولا يقربك شيطان حتى تصبح. وكانوا أحرص شيء على الخير. فقال النبي ﷺ: (( أما إنه قد صدقك وهو كذوب. تعلم من تخاطب منذ ثلاث ليال يا أبا هريرة؟ )) قال: لا. قال: (( ذاك شيطان ))."],"takhrij":"صحيح: رواه البخاري (٢٣١١) تعليقًا، ووصله النسائي في الكبرى (١٠٧٢٩)، وابن خزيمة (٢٤٢٤).","grade":"صحيح","chapter_ar":"باب الوكالة على حفظ زكاة رمضان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2311) in suspended form, and connected by al-Nasa’i in al-Kubra (10729) and Ibn Khuzaymah (2424).","chapter_en":"Agency in guarding the Zakat of Ramadan","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ entrusted me with guarding the Zakat of Ramadan. Then someone came and began scooping up from the food, so I seized him and said: By Allah, I will take you to the Messenger of Allah ﷺ. He said: I am needy, I have dependents, and I am in severe need. So I let him go. In the morning the Prophet ﷺ said: “O Abu Hurayrah, what happened to your captive last night?” I said: O Messenger of Allah ﷺ, he complained of severe need and dependents, so I had mercy on him and let him go. He said: “Indeed, he lied to you, and he will return.” So I knew he would return because of the statement of the Messenger of Allah ﷺ that he would return. I lay in wait for him, and he came again scooping from the food, so I seized him and said: I will take you to the Messenger of Allah ﷺ. He said: Leave me, for I am needy and have dependents; I will not return. So I had mercy on him and let him go. In the morning the Messenger of Allah ﷺ said to me: “O Abu Hurayrah, what happened to your captive?” I said: O Messenger of Allah ﷺ, he complained of severe need and dependents, so I had mercy on him and let him go. He said: “Indeed, he lied to you, and he will return.” So I lay in wait for him a third time. He came scooping from the food, so I seized him and said: I will take you to the Messenger of Allah ﷺ, and this is the last of three times that you claim you will not return, yet you return. He said: Leave me, and I will teach you words by which Allah will benefit you. I said: What are they? He said: When you go to your bed, recite Ayat al-Kursi, “Allah, there is no god but Him, the Ever-Living, the Sustainer,” until you finish the verse. Then there will remain over you from Allah a guardian, and no devil will come near you until morning. So I let him go. In the morning the Messenger of Allah ﷺ said to me: “What happened to your captive last night?” I said: O Messenger of Allah ﷺ, he claimed that he would teach me words by which Allah would benefit me, so I let him go. He said: “What are they?” I said: He told me, when you go to your bed, recite Ayat al-Kursi from its beginning until you complete the verse, “Allah, there is no god but Him, the Ever-Living, the Sustainer.” And he told me: There will remain over you from Allah a guardian, and no devil will come near you until morning. And they were very eager for good. So the Prophet ﷺ said: “Indeed, he told you the truth though he is a great liar. Do you know whom you have been speaking to for the last three nights, O Abu Hurayrah?” He said: No. He said: “That was a devil.”"]},"intro":{"ar":["قال الله تعالى: { إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا } [سورة التوبة: ٦٠]."],"en":["Allah the Exalted said: “Charities are only for the poor, the needy, and those employed to collect and distribute them.” [Al-Tawbah: 60]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2311},{"key":"وصلہ_النسایی/الکبری","label":"وصله النسائي في الكبرى","number":10729},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2424},{"key":"kubranasai","label":"السنن الكبرى للنسائي","number":10729,"n":10723}]},{"num":5531,"demo":false,"sanad":"","matn":["عن عروة البارقي أن النبي ﷺ أعطاه دينارًا يشتري له به شاة، فاشترى له به شاتين، فباع إحداهما بدينار، وجاءه بدينار وشاة، فدعا له بالبركة في بيعه، وكان لو اشترى التراب لربح فيه."],"takhrij":"صحيح: رواه البخاري (٣٦٤٢).","grade":"صحيح","chapter_ar":"باب الوكالة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3642).","chapter_en":"Agency in buying and selling","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Urwah al-Bariqi narrated that the Prophet ﷺ gave him one dinar to buy a sheep for him. So he bought two sheep with it, then sold one of them for one dinar, and came back to him with one dinar and one sheep. So he supplicated for blessing in his trade, and he would have made profit even if he had bought dust."]},"intro":{"ar":["قال الله تعالى: { فَابْعَثُوا أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِ إِلَى الْمَدِينَةِ فَلْيَنظُرْ أَيُّهَا أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ } [سورة الكهف: ١٩]."],"en":["Allah the Exalted said: “So send one of you with this silver coin of yours to the city, and let him look which food is purest, then let him bring you provision from it.” [Al-Kahf: 19]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3642}]},{"num":5532,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أنه قال: أردت الخروج إلى خيبر، فأتيت رسول الله ﷺ فسلمت عليه، وقلت له: إني أردت الخروج إلى خيبر، فقال: (( إذا أتيت وكيلي فخذ منه خمسة عشر وسقًا، فإن ابتغى منك آية فضع يدك على ترقوته ))."],"takhrij":"صحيح: رواه أبو داود (٣٦٣٢)، وعنه البيهقي (٨٠/٦)، والدارقطني (١٥٤/٤).","grade":"صحيح","chapter_ar":"باب الوكالة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3632), and also by al-Bayhaqi (6/80) and al-Daraqutni (4/154).","chapter_en":"Agency in buying and selling","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Jabir ibn Abd Allah said: I wanted to go out to Khaybar, so I came to the Messenger of Allah ﷺ, greeted him, and said to him: I intend to go to Khaybar. He said: “When you come to my agent, take fifteen wasqs from him, and if he asks you for a sign, then place your hand on his collarbone.”"]},"buhuth":{"ar":["وقوله: (( على ترقوته )) بفتح التاء، العظم الذي بين ثغرة النحر، والعاتق. وهما ترقوتان من الجانبين."],"en":["His statement, “on his collarbone,” refers to the bone between the hollow of the throat and the shoulder. A person has two collarbones, one on each side."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3632},{"key":"عنہ_البیہقی","label":"عنه البيهقي","number":80},{"key":"الدارقطنی","label":"الدارقطني","number":154},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11432,"n":11536}]},{"num":5533,"demo":false,"sanad":"","matn":["عن عبد الله الهوزني قال: لقيت بلالًا مؤذن رسول الله ﷺ بحلب، فقلت: يا بلال، حدّثني كيف كانت نفقة رسول الله ﷺ؟ قال: ما كان له شيء. كنت أنا الذي ألي ذلك منه منذ بعثه الله إلى أن توفي، وكان إذا أتاه الإنسان مسلمًا فرآه عاريًا يأمرني، فانطلق فأستقرض، فأشتري له البردة، فأكسوه، وأطعمه. حتى اعترضني رجل من المشركين، فقال: يا بلال، إن عندي سعة فلا تستقرض من أحد إلا مني، ففعلت. فلما أن كان ذات يوم توضأت، ثم قمت لأؤذن بالصلاة، فإذا المشرك قد أقبل في عصابة من التجار، فلما أن رآني قال: يا حبشي. قلت: يا لباه. فتجهّمني، وقال لي قولًا غليظًا، وقال لي: أتدري كم بينك وبين الشهر؟ قال: قلت: قريب. قال: إنما بينك وبينه أربع، فآخذك بالذي عليك، فأردك ترعى الغنم كما كنت قبل ذلك. فأخذ في نفسي ما يأخذ في أنفس الناس، حتى إذا صليت العتمة رجع رسول الله ﷺ إلى أهله، فاستأذنت عليه، فأذن لي، فقلت: يا رسول الله، بأبي أنت وأمي، إن المشرك الذي كنت أتدين منه قال لي كذا وكذا، وليس عندك ما تقضي عني ولا عندي، وهو فاضحي، فأذن لي أن آبق إلى بعض هؤلاء الأحياء الذين قد أسلموا حتى يرزق الله رسوله ﷺ ما يقضي عني. فخرجت حتى إذا أتيت منزلي، فجعلت سيفي وجرابي ونعلي ومجني عند رأسي، حتى إذا انشق عمود الصبح الأول أردت أن أنطلق، فإذا إنسان يسعى يدعو: يا بلال، أجب رسول الله ﷺ. فانطلقت حتى أتيته، فإذا أربع ركائب مناخات عليهن أحمالهن، فاستأذنت، فقال لي رسول الله ﷺ: (( أبشر، فقد جاءك الله بقضائك )). ثم قال: (( ألم تر الركائب المناخات الأربع؟ )) فقلت: بلى. فقال: (( إن لك رقابهن وما عليهن، فإن عليهن كسوة وطعامًا أهداهن إلي عظيم فدك، فاقبضهن، واقض دينك )). ففعلت، فذكر الحديث. ثم انطلقت إلى المسجد، فإذا رسول الله ﷺ قاعد في المسجد، فسلمت عليه، فقال: (( ما فعل ما قبلك؟ )) قلت: قد قضى الله كل شيء كان على رسول الله ﷺ، فلم يبق شيء. قال: (( أَفَضَلَ شيء؟ )) قلت: نعم. قال: (( انظر أن تريحني منه، فإني لست بداخل على أحد من أهلي حتى تريحني منه )). فلما صلى رسول الله ﷺ العتمة دعاني، فقال: (( ما فعل الذي قبلك؟ )) قال: قلت: هو معي لم يأتنا أحد. فبات رسول الله ﷺ في المسجد، وقص الحديث. قال: حتى إذا صلى العتمة - يعني من الغد - دعاني قال: (( ما فعل الذي قبلك؟ )) قال: قلت: قد أراحك الله منه يا رسول الله. فكبر، وحمد الله شفقًا من أن يدركه الموت، وعنده ذلك. ثم اتبعته حتى إذا جاء أزواجه فسلم على امرأة امرأة، حتى أتى مبيته. فهذا الذي سألتني عنه."],"takhrij":"صحيح: رواه أبو داود (٣٠٥٥)، وصححه ابن حبان (٦٣٥١)، والبيهقي (٨٠/٦).","grade":"صحيح","chapter_ar":"باب الوكالة في البيع والشراء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3055), authenticated by Ibn Hibban (6351), and narrated by al-Bayhaqi (6/80).","chapter_en":"Agency in buying and selling","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الوكالة","group_en":"Collection of chapters on agency","part_no":17,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abd Allah al-Hawzani said: I met Bilal, the caller to prayer of the Messenger of Allah ﷺ, in Aleppo, and I said: O Bilal, tell me how the spending of the Messenger of Allah ﷺ used to be. He said: He had nothing. I was the one in charge of that for him from the time Allah sent him until he passed away. Whenever a Muslim came to him and he saw him unclothed, he would command me, and I would go borrow something and buy a cloak for him, clothe him, and feed him. Then a man from the polytheists approached me and said: O Bilal, I have wealth, so do not borrow from anyone except me. So I did that. Then one day I made wudu and stood to call the prayer, and suddenly that polytheist came with a group of merchants. When he saw me he said: O Abyssinian. I said: At your service. He frowned at me, spoke harshly to me, and said: Do you know how much time remains between you and the month? I said: It is near. He said: Only four days remain, then I will seize you for what you owe and return you to herding sheep as you used to do before. That affected me the way such words affect people, until after I prayed the night prayer and the Messenger of Allah ﷺ returned to his family, I sought permission to enter upon him and he permitted me. I said: O Messenger of Allah ﷺ, may my father and mother be sacrificed for you, the polytheist from whom I used to borrow said this and this to me. Neither you nor I have what can pay off my debt, and he is going to disgrace me, so permit me to flee to one of these clans who have accepted Islam until Allah provides His Messenger ﷺ with what can settle my debt. I left until I reached my home and placed my sword, my bag, my sandals, and my shield by my head. Then when the first light of dawn broke, I intended to depart, but suddenly a man came running and calling: O Bilal, answer the Messenger of Allah ﷺ. So I went to him, and there were four kneeling camels loaded with goods. I sought permission to enter, and the Messenger of Allah ﷺ said to me: “Rejoice, for Allah has brought you what will settle your debt.” Then he said: “Did you not see the four loaded camels kneeling there?” I said: Yes. He said: “They, and what is on them, are for you, for they carry clothing and food gifted to me by the chief of Fadak, so take them and pay your debt.” So I did so. Then I went to the mosque and found the Messenger of Allah ﷺ sitting there. I greeted him and he said: “What happened to what was due from you?” I said: Allah has settled everything that was due from the Messenger of Allah ﷺ, and nothing remains. He said: “Is anything left over?” I said: Yes. He said: “See that you relieve me of it, for I will not enter upon any of my family until you relieve me of it.” Then after the Messenger of Allah ﷺ prayed the night prayer, he called me and said: “What happened to what remained with you?” I said: It is still with me; no one has come to us. So the Messenger of Allah ﷺ spent the night in the mosque. He continued the story and said: Then after he prayed the night prayer the next day, he called me and said: “What happened to what remained with you?” I said: Allah has relieved you of it, O Messenger of Allah ﷺ. So he said the takbir and praised Allah, fearing that death might reach him while that wealth was still with him. Then I followed him until he came to his wives, greeting each woman one by one, until he reached his sleeping place. This is what you asked me about."]},"buhuth":{"ar":["وقوله: (( يالباه )) يريد لبيك. وقوله: (( تجهمني )) أي تلقاني بوجه كريه. وقوله: (( مجني )) من المجن - بكسر الميم، وفتح الجيم، وتشديد النون - الترس. وقوله: (( شفقًا )) - بفتح الشين والفاء - الخوف."],"en":["His saying “yalabbah” means “here I am” or “at your service.” His saying “he frowned at me” means he met me with an unpleasant face. “My shield” comes from “mijan,” meaning a shield. And “shafaqan” here means fear."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3055},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":6351},{"key":"البیہقی","label":"البيهقي","number":80},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":6096,"n":6094},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11435,"n":11539}]},{"num":5534,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: قال رسول الله ﷺ: (( ما من مسلم يغرس غرسًا أو يزرع زرعًا، فيأكل منه طير أو إنسان أو بهيمة إلا كان له به صدقة ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٢٠)، ومسلم (١٢:١٥٥٣).","grade":"متفق عليه","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2320) and Muslim (1553:12).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “No Muslim plants a tree or sows a crop, and then a bird, a person, or an animal eats from it, except that it is counted for him as charity.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2320},{"key":"muslim","label":"مسلم","number":12}]},{"num":5535,"demo":false,"sanad":"","matn":["عن أنس أن النبي ﷺ دخل نخلًا لأم مبشر امرأة من الأنصار، فقال رسول الله ﷺ: (( من غرس هذا النخل؟ أمسلم أم كافر؟ )) قالوا: مسلم. فقال: (( لا يغرس مسلم غرسًا، فيأكل منه إنسان أو طير أو دابة إلا كانت له صدقة ))."],"takhrij":"صحيح: رواه مسلم (١٣:١٥٥٣)، والبخاري (٢٣٢٠).","grade":"صحيح","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1553:13) and al-Bukhari (2320).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ entered a date-palm grove belonging to Umm Mubashshir, a woman from the Ansar, and the Messenger of Allah ﷺ said: “Who planted these palm trees? Was it a Muslim or a disbeliever?” They said: A Muslim. He said: “No Muslim plants a tree, and then a person, a bird, or an animal eats from it, except that it is charity for him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":13},{"key":"bukhari","label":"البخاري","number":2320}]},{"num":5536,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: قال رسول الله ﷺ: (( إن قامت على أحدكم القيامة، في يده فسيلة فليغرسها ))."],"takhrij":"حسن: رواه الإمام أحمد (١٢٩٠٢)، والبزار - كشف الأستار (١٢٥١)، والبخاري في الأدب المفرد (٤٧٩).","grade":"حسن","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (12902), al-Bazzar in Kashf al-Astar (1251), and al-Bukhari in al-Adab al-Mufrad (479).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ said: “If the Final Hour comes while one of you has a small palm shoot in his hand, then let him plant it.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":12902},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1251},{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":479},{"key":"ahmad","label":"مسند الإمام أحمد","number":12902,"n":12902}]},{"num":5537,"demo":false,"sanad":"","matn":["عن جابر أن النبي ﷺ دخل على أم مبشر الأنصارية في نخل لها، فقال لها النبي ﷺ: (( من غرس هذا النخل؟ أمسلم أم كافر؟ )) فقالت: بل مسلم. فقال: (( لا يغرس مسلم غرسًا، ولا يزرع زرعًا، فيأكل منه إنسان ولا دابة ولا شيء إلا كانت له صدقة ))."],"takhrij":"صحيح: رواه مسلم (٨:١٥٥٢).","grade":"صحيح","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1552:8).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Jabir narrated that the Prophet ﷺ entered upon Umm Mubashshir al-Ansariyyah in a grove of hers and said to her: “Who planted these palm trees? Was it a Muslim or a disbeliever?” She said: Rather, a Muslim. He said: “No Muslim plants a tree or sows a crop, and then a person, an animal, or anything else eats from it, except that it is charity for him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":8}]},{"num":5538,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: دخل النبي ﷺ على أم معبد حائطًا، فقال: (( يا أم معبد، من غرس هذا النخل؟ أمسلم أم كافر؟ )) فقالت: بل مسلم. قال: (( فلا يغرس المسلم غرسًا، فيأكل منه إنسان، ولا دابة، ولا طير إلا كان له صدقة إلى يوم القيامة ))."],"takhrij":"صحيح: رواه مسلم (١٠:١٥٥٢).","grade":"صحيح","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1552:10).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Prophet ﷺ entered a garden belonging to Umm Mabd and said: “O Umm Mabd, who planted these palm trees? Was it a Muslim or a disbeliever?” She said: Rather, a Muslim. He said: “No Muslim plants a tree, and then a person, an animal, or a bird eats from it, except that it will be charity for him until the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":10}]},{"num":5539,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول الله ﷺ: (( ما من مسلم يغرس غرسًا إلا كان ما أكل منه له صدقة، وما سُرق منه له صدقة، وما أكل السبع منه فهو له صدقة، وما أكلت الطير فهو له صدقة، ولا يرزؤه أحد إلا كان له صدقة ))."],"takhrij":"صحيح: رواه مسلم (٧:١٥٥٢).","grade":"صحيح","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1552:7).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “No Muslim plants a tree except that whatever is eaten from it is charity for him, whatever is stolen from it is charity for him, whatever a wild beast eats from it is charity for him, whatever birds eat from it is charity for him, and no one diminishes it in any way except that it is charity for him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":7}]},{"num":5540,"demo":false,"sanad":"","matn":["عن السائب بن خلاد قال: قال رسول الله ﷺ: (( من زرع زرعًا، فأكل منه الطير أو العافية كان له به صدقة ))."],"takhrij":"حسن: رواه الإمام أحمد (١٦٥٥٨).","grade":"حسن","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (16558).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Al-Sa’ib ibn Khallad said: The Messenger of Allah ﷺ said: “Whoever sows a crop, and birds or creatures seeking provision eat from it, it will be charity for him.”"]},"buhuth":{"ar":["وقوله: (( العافية )) هو كل طالب للرزق."],"en":["The word “al-afiyah” here means every creature that seeks provision."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":16558},{"key":"ahmad","label":"مسند الإمام أحمد","number":16558,"n":16558}]},{"num":5541,"demo":false,"sanad":"","matn":["عن أبي الدرداء أن رجلًا مر به وهو يغرس غرسًا بدمشق، فقال له: أتفعل هذا وأنت صاحب رسول الله ﷺ؟ فقال: لا تعجل عليَّ، سمعت رسول الله ﷺ يقول: (( من غرس غرسًا لم يأكل منه آدمي ولا خلق من خلق الله عز وجل إلا كان له صدقة ))."],"takhrij":"حسن: رواه أحمد (٢٧٥٠٦).","grade":"حسن","chapter_ar":"باب فضل غرس المسلم وزرعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27506).","chapter_en":"The virtue of a Muslim planting and sowing","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abu al-Darda said that a man passed by him while he was planting something in Damascus and said to him: Are you doing this while you are a Companion of the Messenger of Allah ﷺ? He said: Do not be hasty with me. I heard the Messenger of Allah ﷺ say: “Whoever plants a tree, and no human or any creature from Allah’s creation eats from it except that it is charity for him.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":27506,"n":27506}]},{"num":5542,"demo":false,"sanad":"","matn":["عن أبي أمامة الباهلي قال - ورأى سكة وشيئًا من آلة الحرث - فقال: سمعت النبي ﷺ يقول: (( لا يدخل هذا بيت قوم إلا أدخله الله الذل ))."],"takhrij":"صحيح: رواه البخاري (٢٣٢١).","grade":"صحيح","chapter_ar":"باب الاقتصاد في الزراعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2321).","chapter_en":"Moderation in farming","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Abu Umamah al-Bahili said — when he saw a plowshare and some farming tools —: I heard the Prophet ﷺ say: “This does not enter the house of a people except that Allah causes humiliation to enter it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2321}]},{"num":5543,"demo":false,"sanad":"","matn":["عن زيد بن أسلم، عن أبيه قال: قال عمر: “لولا آخر المسلمين ما فتحت قرية إلا قسمتها بين أهلها، كما قسم النبي ﷺ خيبر”."],"takhrij":"صحيح: رواه البخاري (٢٣٣٤).","grade":"صحيح","chapter_ar":"باب تقسيم الإمام الأرض المفتوحة عنوة على الفاتحين للزراعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2334).","chapter_en":"The ruler’s distribution of land conquered by force among the conquerors for cultivation","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Aslam narrated from his father that Umar said: “Were it not for the later Muslims, I would not conquer any town except that I would divide it among those who conquered it, just as the Prophet ﷺ divided Khaybar.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2334}]},{"num":5544,"demo":false,"sanad":"","matn":["عن جابر قال: كانت لرجال منا فضول أرضين، فقالوا: نؤاجرها بالثلث والربع والنصف. فقال النبي ﷺ: (( من كانت له أرض فليزرعها أو ليمنحها أخاه، فإن أبى فليمسك أرضه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٣٢، ٢٣٤٠)، ومسلم (٨٩:١٥٣٦)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2632, 2340) and Muslim (1536:89). The wording is al-Bukhari’s.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Jabir said: Some men among us had extra plots of land, and they said: We will lease them out for one-third, one-fourth, or one-half. So the Prophet ﷺ said: “Whoever has land should cultivate it himself or grant it to his brother. If he refuses, then let him keep his land.”"]},"buhuth":{"ar":["ولفظ مسلم: (( من كانت له فضل أرض فليزرعها أو ليمنحها أخاه، فإن أبى فليمسك أرضه )).","وإليكم هذه الألفاظ التي رواها مسلم في صحيحه:","(( من كانت له أرض فليهبها، أو ليزرعها )).","(( من كانت له أرض فليزرعها أو ليحرثها أخاه، وإلا فليدعها )).","(( من كانت له أرض فليزرعها، فإن لم يزرعها فليمنحها أخاه، فإن لم يمنحها أخاه فليمسكها )).","(( نهى رسول الله ﷺ عن بيع السنين أو ثلاثًا )).","(( نهى رسول الله ﷺ عن المحاقلة، والمزابنة، والمعاومة، والمخابرة، وعن الثنيا، ورخص في العرايا )).","(( من كانت له أرض فليزرعها أو ليزرعها أخاه، ولا يكرها )).","(( من كانت له أرض فليزرعها، فإن لم يستطع أن يزرعها، وعجز عنها فليمنحها أخاه المسلم، ولا يؤاجرها إياه )).","(( من كانت له أرض فليزرعها، فإن لم يزرعها فليزرعها أخاه )).","(( نهى رسول الله ﷺ أن يؤخذ للأرض أجر أو حظ )).","(( أن النبي ﷺ نهى عن كراء الأرض )).","(( إن النبي ﷺ نهى عن كراء الأرض )).","(( نهى النبي ﷺ عن بيع السنين )).","(( إن رسول الله ﷺ ينهى عن المزابنة والمحاقلة )). قال جابر: المزابنة الثمر بالتمر، والمحاقلة كراء الأرض.","(( من كانت له أرض فليزرعها أو ليزرعها رجلًا )).","(( أن النبي ﷺ نهى عن المخابرة )).","وخلاصة القول أن حديث جابر بن عبد الله في النهي عن كراء الأرض محمول على التنزيه، وليس على التحريم؛ لأن الهبة والإعارة والمنحة ليست بواجبة، ولكن تصرف بعض الرواة، فرووه بالمعنى، فاختلفت ألفاظهم حتى أن بعض الناس ظنوا فيه التحريم، فرووه بلفظ: (( من لم يذر المخابرة فليأذن بحرب من الله ورسوله )). رواه أبو داود (٣٤٠٦)، وهو غريب."],"en":["In Muslim’s wording: “Whoever has surplus land should cultivate it or grant it to his brother. If he refuses, then let him keep his land.”","Here are the wordings narrated by Muslim in his Sahih:","“Whoever has land should gift it, or let it be cultivated.”","“Whoever has land should cultivate it or let his brother cultivate it, otherwise let him leave it.”","“Whoever has land should cultivate it. If he does not cultivate it, let him grant it to his brother. If he does not grant it to his brother, then let him keep it.”","“The Messenger of Allah ﷺ forbade selling produce for years ahead, for two or three years.”","“The Messenger of Allah ﷺ forbade muhaqalah, muzabanah, muagwamah, mukhabarah, and exception clauses, but permitted araya sales.”","“Whoever has land should cultivate it or let his brother cultivate it, and should not rent it out.”","“Whoever has land should cultivate it. If he cannot cultivate it and is unable to do so, then let him grant it to his Muslim brother, and not lease it to him.”","“Whoever has land should cultivate it, and if he does not cultivate it, then let his brother cultivate it.”","“The Messenger of Allah ﷺ forbade that land should have a rent or assigned share taken for it.”","“The Prophet ﷺ forbade renting out land.”","“Indeed the Prophet ﷺ forbade renting out land.”","“The Prophet ﷺ forbade selling for future years.”","“The Messenger of Allah ﷺ forbids muzabanah and muhaqalah.” Jabir said: Muzabanah is selling fresh fruit for dried dates, and muhaqalah is renting land.","“Whoever has land should cultivate it or let another man cultivate it.”","“The Prophet ﷺ forbade mukhabarah.”","The conclusion is that Jabir ibn Abd Allah’s hadith regarding the prohibition of renting out land is understood as discouragement, not strict prohibition, because gifting, lending, and granting land are not obligatory. But some narrators narrated by meaning, so their wordings differed, until some people thought it meant prohibition and narrated it with the wording: “Whoever does not abandon mukhabarah, then let him be warned of war from Allah and His Messenger.” Narrated by Abu Dawud (3406), and it is uncommon."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2632},{"key":"muslim","label":"مسلم","number":89}]},{"num":5545,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( من كانت له أرض فليزرعها، أو ليمنحها أخاه، فإن أبى فليمسك أرضه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٤١)، ومسلم (١٥٤٤).","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2341) and Muslim (1544).","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever has land should cultivate it, or grant it to his brother. If he refuses, then let him keep his land.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2341},{"key":"muslim","label":"مسلم","number":1544}]},{"num":5546,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول الله ﷺ عن المحاقلة والمزابنة."],"takhrij":"صحيح: رواه مسلم (١٥٤٥).","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1545).","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade muhaqalah and muzabanah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1545}]},{"num":5547,"demo":false,"sanad":"","matn":["عن نافع أن ابن عمر كان يكري مزارعه على عهد رسول الله ﷺ، وفي إمارة أبي بكر وعمر وعثمان وصدرًا من خلافة معاوية، حتى بلغه في آخر خلافة معاوية أن رافع بن خديج يحدّث فيها بنهي عن النبي ﷺ، فدخل عليه - وأنا معه -، فسأله، فقال: كان رسول الله ﷺ ينهى عن كراء المزارع، فتركها ابن عمر بعد. وكان إذا سئل عنها بعد قال: زعم رافع بن خديج أن رسول الله ﷺ نهى عنها."],"takhrij":"متفق عليه: رواه البخاري (٢٣٤٤-٢٣٤٣)، ومسلم (١٥٤٧:١٠٩). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2344–2343) and Muslim (1547:109). The wording is Muslim’s.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Nafi narrated that Ibn Umar used to lease out his farmlands during the time of the Messenger of Allah ﷺ, and during the rule of Abu Bakr, Umar, Uthman, and the early part of Muawiyah’s caliphate, until near the end of Muawiyah’s rule he learned that Rafi ibn Khadij was narrating concerning it a prohibition from the Prophet ﷺ. So he went to him — and I was with him — and asked him. He said: The Messenger of Allah ﷺ used to forbid leasing out farmlands. So Ibn Umar stopped doing it after that. Whenever he was asked about it later, he would say: Rafi ibn Khadij claimed that the Messenger of Allah ﷺ forbade it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2344},{"key":"muslim","label":"مسلم","number":1547}]},{"num":5548,"demo":false,"sanad":"","matn":["عن نافع أن ابن عمر كان يؤاجر الأرض، قال: فنبئ حديثًا عن رافع بن خديج. قال: فانطلق بي معه إليه. قال: فذكر عن بعض عمومته ذكر فيه عن النبي ﷺ أنه نهى عن كراء الأرض. قال: فتركه ابن عمر، ولم يؤاجرها."],"takhrij":"صحيح: رواه مسلم (١٥٤٧:١١١). قلت: تركه كان تنزيهًا، لا تحريمًا، وعليه قول ابن عباس، كما سيأتي.","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1547:111). I say: His leaving it was out of caution and dislike, not because of absolute prohibition, and this is also the view of Ibn Abbas, as will come later.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Nafi narrated that Ibn Umar used to lease out land. Then he was informed of a hadith from Rafi ibn Khadij. He said: So he took me with him to go to him. He then mentioned from some of his paternal uncles a report from the Prophet ﷺ that he forbade leasing land. So Ibn Umar left it and did not lease it out."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1547}]},{"num":5549,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله:","أن عبد الله بن عمر كان يكري أرضيه، حتى بلغه أن رافع بن خديج الأنصاري كان ينهى عن كراء الأرض، فلقيه عبد الله، فقال:","يا ابن خديج، ماذا تحدث عن رسول الله ﷺ في كراء الأرض؟","قال رافع بن خديج لعبد الله:","سمعت عميَّ - وكانا قد شهدا بدرًا - يحدثان أهل الدار أن رسول الله ﷺ نهى عن كراء الأرض.","قال عبد الله:","لقد كنت أعلم في عهد رسول الله ﷺ أن الأرض تكرى.","ثم خشي عبد الله أن يكون رسول الله ﷺ أحدث في ذلك شيئًا لم يكن علمه، فترك كراء الأرض."],"takhrij":"متفق عليه: رواه البخاري (٢٣٤٥)، ومسلم (١٥٤٧/١١٢)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2345) and Muslim (1547/112). This is Muslim’s wording.","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Sālim ibn ʿAbdullāh reported:","ʿAbdullāh ibn ʿUmar used to lease out his lands until he learned that Rāfiʿ ibn Khadīj al-Anṣārī prohibited the leasing of land.","ʿAbdullāh met him and asked:","“O Ibn Khadīj, what do you narrate from the Messenger of Allah ﷺ concerning the leasing of land?”","Rāfiʿ ibn Khadīj said to ʿAbdullāh:","“I heard my two paternal uncles—both of whom had participated in Badr—telling the people of the household that the Messenger of Allah ﷺ prohibited leasing land.”","ʿAbdullāh said:","“I certainly knew during the lifetime of the Messenger of Allah ﷺ that land was leased.”","Then ʿAbdullāh feared that the Messenger of Allah ﷺ might subsequently have issued a ruling concerning it of which he had not been aware, so he stopped leasing land."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2345},{"key":"muslim","label":"مسلم","number":1547}]},{"num":5550,"demo":false,"sanad":"","matn":["عن نافع قال: ذهبت مع ابن عمر إلى رافع بن خديج حتى أتاه بالبلاط، فأخبره أن رسول الله ﷺ نهى عن كراء المزارع."],"takhrij":"صحيح: رواه مسلم (١٥٤٦:١١٠).","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض من باب الإرشاد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1546:110).","chapter_en":"The prohibition of renting out land as guidance and counsel","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["Nafi said: I went with Ibn Umar to Rafi ibn Khadij until he came to him at al-Bilat, and he informed him that the Messenger of Allah ﷺ had forbidden leasing out farmlands."]},"buhuth":{"ar":["والبلاط مكان معروف بالمدينة مبلط بالحجارة، وهو بقرب مسجد رسول الله ﷺ."],"en":["Al-Bilat was a known place in Madinah paved with stones, near the mosque of the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1546}]},{"num":5551,"demo":false,"sanad":"","matn":["عن ظهير بن رافع قال: لقد نهانا رسول الله ﷺ عن أمر كان بنا رافقًا. قلت: ما قال رسول الله ﷺ فهو حق. قال: دعاني رسول الله ﷺ قال: (( ما تصنعون بمحاقلكم؟ )). قلت: نؤاجرها على الربيع، وعلى الأوسق من التمر والشعير. قال: (( لا تفعلوا، ازرعوها، أو أزرعوها، أو أمسكوها )). قال رافع: قلت: سمعًا وطاعة."],"takhrij":"متفق عليه: رواه البخاري (٢٣٣٩)، ومسلم (١٥٤٨:١١٤). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2339) and Muslim (1548:114). The wording is al-Bukhari’s.","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Zuhayr ibn Rafi said: The Messenger of Allah ﷺ forbade us from something that had been beneficial for us. I said: Whatever the Messenger of Allah ﷺ said is the truth. He said: The Messenger of Allah ﷺ called me and said, “What do you do with your cultivated lands?” I said: We lease them out for the produce by the watercourse, or for measured amounts of dates and barley. He said: “Do not do that. Cultivate them yourselves, let others cultivate them, or keep them unused.” Rafi said: I said: We hear and obey."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2339},{"key":"muslim","label":"مسلم","number":1548}]},{"num":5552,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال: كنا نحاقل الأرض على عهد رسول الله ﷺ، فنكريها بالثلث والربع والطعام المسمى، فجاءنا ذات يوم رجل من عمومتي، فقال: نهانا رسول الله ﷺ عن أمر كان لنا نافعًا، وطواعية الله ورسوله أنفع لنا، نهانا أن نحاقل بالأرض، فنكريها على الثلث والربع والطعام المسمى، وأمر رب الأرض أن يزرعها، أو يُزرعها، وكره كراءها وما سوى ذلك."],"takhrij":"صحيح: رواه مسلم (١٥٤٨:١١٣).","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1548:113).","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Rafi ibn Khadij said: We used to practice crop-sharing with land during the time of the Messenger of Allah ﷺ, leasing it out for one-third, one-fourth, or specified food. Then one day a man from my paternal uncles came to us and said: The Messenger of Allah ﷺ forbade us from something that had been beneficial for us, but obedience to Allah and His Messenger is more beneficial for us. He forbade us from leasing land for one-third, one-fourth, or specified food, and he instructed the owner of the land to cultivate it himself or let it be cultivated, and he disliked leasing it out and other such arrangements."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1548}]},{"num":5553,"demo":false,"sanad":"","matn":["عن أسيد بن ظهير ابن أخي رافع بن خديج قال: كان أحدنا إذا استغنى عن أرضه أعطاها بالثلث والربع والنصف، ويشترط ثلاث جداول والقصارة وما يسقي الربيع، وكان العيش إذ ذاك شديدًا، وكان يُعمل فيها بالحديد وما شاء الله، ويصيب منها منفعة، فأتانا رافع بن خديج فقال: إن رسول الله ﷺ ينهاكم عن أمر كان لكم نافعًا، وطاعة الله وطاعة رسوله ﷺ أنفع لكم. إن النبي ﷺ ينهاكم عن الحقل، ويقول: (( من استغنى عن أرضه فليمنحها أخاه، أو ليدع )). وينهاكم عن المزابنة. والمزابنة أن يكون الرجل له المال العظيم من النخل، فيأتيه الرجل، فيقول: قد أخذته بكذا وكذا وسقًا من تمر."],"takhrij":"صحيح: رواه أحمد (١٥٨١٥)، وعبد الرزاق في مصنفه (١٤٤٦٣)، وابن ماجه (٢٤٦٠).","grade":"صحيح","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15815), Abd al-Razzaq in his Musannaf (14463), and Ibn Majah (2460).","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Usayd ibn Zuhayr, the nephew of Rafi ibn Khadij, said: One of us, if he had no need for his land, would give it out for one-third, one-fourth, or one-half, while stipulating three irrigation channels, the leftover gleanings, and what the spring waters irrigated. Life at that time was hard, and the land was worked with iron tools and whatever Allah willed, and some benefit would be gained from it. Then Rafi ibn Khadij came to us and said: The Messenger of Allah ﷺ forbids you from something that had been beneficial for you, but obedience to Allah and obedience to His Messenger ﷺ are more beneficial for you. The Prophet ﷺ forbids you from field-renting, and says: “Whoever has no need of his land, let him grant it to his brother or leave it.” And he forbids you from muzabanah. Muzabanah is that a man has a large amount of palm produce, and another man comes to him and says: I take it for such-and-such measured amount of dried dates."]},"buhuth":{"ar":["وقوله: (( ثلاث جداول )) أي ثلاث حصص من الجداول. والجدول: النهر الصغير، أي ما يخرج على أطرافها.","وقوله: (( القُصارة )) بالضم، ما يبقى من الحب في السنبل مما لا يتخلص منه بعد ما يداس.","وقوله: (( وما يسقي الربيع )) هو النهر الصغير، كأنهم يجعلون قطعة من الأرض يسقيها الربيع."],"en":["His saying, “three irrigation channels,” means three allotted shares from the small water channels. A jadwal is a small stream, meaning portions of land near its edges.","The word “al-qusarah,” with a dammah, means what remains of grain in the ear and is not fully separated after threshing.","And “what the spring waters irrigate” refers to a small stream, meaning they would assign a piece of land irrigated by that spring flow."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق/مصنفہ","label":"عبد الرزاق في مصنفه","number":14463},{"key":"ibnmajah","label":"ابن ماجه","number":2460},{"key":"ahmad","label":"مسند الإمام أحمد","number":15815,"n":15815}]},{"num":5554,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري أن رسول الله ﷺ نهى عن المزابنة والمحاقلة. والمزابنة اشتراء الثمر بالتمر في رؤوس النخل. والمحاقلة كراء الأرض بالحنطة."],"takhrij":"متفق عليه: رواه مالك (٢٤)، والبخاري (٢١٨٦)، ومسلم (١٥٤٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن كراء الأرض بالطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (24), al-Bukhari (2186), and Muslim (1546).","chapter_en":"The prohibition of renting land in exchange for food","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Abu Said al-Khudri narrated that the Messenger of Allah ﷺ forbade muzabanah and muhaqalah. Muzabanah is purchasing fruit on the trees in exchange for dried dates, and muhaqalah is renting land in exchange for wheat."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":24},{"key":"bukhari","label":"البخاري","number":2186},{"key":"muslim","label":"مسلم","number":1546}]},{"num":5555,"demo":false,"sanad":"","matn":["عن حنظلة بن قيس، عن رافع بن خديج قال: حدثني عماي أنهم كانوا يكرون الأرض على عهد النبي ﷺ بما ينبت على الأربعاء، أو شيء يستثنيه صاحب الأرض، فنهى النبي ﷺ عن ذلك.","فقلت لرافع: فكيف هي بالدينار والدرهم؟ فقال رافع: ليس بها بأس بالدينار والدرهم."],"takhrij":"صحيح: رواه البخاري (٢٣٤٦).","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2346).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Hanzalah ibn Qays narrated from Rafi ibn Khadij, who said: My two paternal uncles told me that they used to lease land during the time of the Prophet ﷺ in exchange for what grew on the small channels or for some portion that the landowner excluded for himself, and the Prophet ﷺ forbade that. I said to Rafi: What about leasing it for dinars and dirhams? Rafi said: There is no harm in that with dinars and dirhams."]},"buhuth":{"ar":["وقوله: (( الأربعاء )) جمع الربيع، وهو النهر الصغير."],"en":["The word “al-arbia” is the plural of “ربيع” here, meaning a small stream or irrigation channel."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2346}]},{"num":5556,"demo":false,"sanad":"","matn":["عن رافع بن خديج أن رسول الله ﷺ نهى عن كراء المزارع. قال حنظلة: فسألت رافع بن خديج بالذهب والورق؟ فقال: أما بالذهب والورق فلا بأس به."],"takhrij":"صحيح: رواه مالك (١)، ومسلم (١٥٤٧:١١٥).","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (1) and Muslim (1547:115).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Rafi ibn Khadij narrated that the Messenger of Allah ﷺ forbade leasing out farmlands. Hanzalah said: So I asked Rafi ibn Khadij about gold and silver. He said: As for gold and silver, there is no harm in that."]},"buhuth":{"ar":["ورواه مسلم أيضًا (١٥٤٧:١١٦) من طريق حنظلة بن قيس الأنصاري قال: سألت رافع بن خديج عن كراء الأرض بالذهب والورق؟ فقال: لا بأس به، إنما كان الناس يؤاجرون على عهد النبي ﷺ على الماذيانات، وأقبال الجداول، وأشياء من الزرع، فيهلك هذا ويسلم هذا، ويسلم هذا ويهلك هذا. فلم يكن للناس كراء إلا هذا، فلذلك زجر عنه، فأما شيء معلوم مضمون فلا بأس به.","وفي لفظ: أن الناس كانوا يكرون المزارع في زمان رسول الله ﷺ بالماذيانات، وما سقى الربيع، وشيء من التبن، فكره رسول الله ﷺ كرى المزارع بهذا، ونهى عنها. قال رافع: لا بأس بكرائها بالدراهم والدنانير.","رواه الإمام أحمد (١٥٨٠٩).","وقوله: (( الماذيانات )) - بكسر الذال - وهي الأنهار، وهي ليست بعربية، ومعناه: ما ينبت على حافتيها لرب الأرض.","والأقبال جمع قبل، ومعنى أقبال الجداول أوائلها ورؤوسها. والجداول جمع جدول، وهو النهر الصغير."],"en":["Muslim also narrated it (1547:116) through Hanzalah ibn Qays al-Ansari, who said: I asked Rafi ibn Khadij about leasing land for gold and silver, and he said: There is no harm in it. The people in the time of the Prophet ﷺ used to lease based on the portions by the water channels, the fronts of the irrigation streams, and selected parts of the crops, so one part would be ruined while another would remain safe, or one would remain safe while the other would be ruined. The people had no leasing except this kind, so that is why it was forbidden. But as for something fixed and guaranteed, there is no harm in it.","In another wording: The people used to lease farmlands in the time of the Messenger of Allah ﷺ by the portions near the water channels, what the spring waters irrigated, and some of the straw. So the Messenger of Allah ﷺ disliked leasing farmland in this way and forbade it. Rafi said: There is no harm in leasing it for dirhams and dinars.","Narrated by Imam Ahmad (15809).","The word “al-madhiyanat,” with the dhal pronounced with kasrah, means streams or water channels, and it is not originally Arabic. It refers to what grows along their edges for the landowner.","“And aqbal al-jadawil” means the beginnings and heads of the irrigation streams. Jadawil is the plural of jadwal, which means a small stream."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"muslim","label":"مسلم","number":1547}]},{"num":5557,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال: كنا أكثر أهل المدينة مزروعًا، كنا نكري الأرض بالناحية منها مسمى لسيد الأرض. قال: فمما يصاب ذلك، وتسلم الأرض، ومما تصاب الأرض، ويسلم ذلك، فنهينا. وأما الذهب والورق فلم يكن يومئذ."],"takhrij":"صحيح: رواه البخاري (٢٣٢٧).","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2327).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Rafi ibn Khadij said: We were the people of Madinah with the most cultivated land. We used to lease land out with a certain portion of it specified for the owner of the land. Sometimes that specified portion would be damaged while the rest of the land remained safe, and sometimes the land would be damaged while that specified portion remained safe, so we were forbidden from that. As for renting land for gold and silver, that was not practiced then."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2327}]},{"num":5558,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال: كنا أكثر الأنصار حقلاً. قال: كنا نكري الأرض على أن لنا هذه ولهم هذه، فربما أخرجت هذه ولم تخرج هذه، فنهانا عن ذلك. وأما الورق فلم ينهنا."],"takhrij":"متفق عليه: رواه البخاري (٢٣٣٢)، ومسلم (١٥٤٧:١١٧). وهذا لفظ مسلم. ولفظ البخاري: كنا أكثر أهل المدينة حقلاً، وكان أحدنا يكري أرضه، فيقول: هذه القطعة لي، وهذه لك. فربما أخرجت هذه ولم تخرج هذه، فنهاهم النبي ﷺ.","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2332) and Muslim (1547:117). This is the wording of Muslim. Al-Bukhari’s wording says: We were the people of Madinah with the most farmland, and one of us would lease his land saying: this plot is mine and that plot is yours. So sometimes this one would produce and the other would not, so the Prophet ﷺ forbade them from that.","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Rafi ibn Khadij said: We were the Ansar with the most farmland. We used to lease out land on the basis that one section would be for us and another for them. Sometimes this section would produce while that one would not, so he forbade us from that. But as for silver money, he did not forbid us from it."]},"buhuth":{"ar":["وفي لفظ عنده: فربما أخرجت هذه ولم تخرج هذه، فنهينا عن ذلك، ولم ننه عن الورق. رواه في الشروط عن مالك بن إسماعيل، حدثنا ابن عيينة بإسناده.","وقوله: (( أما الورق )) الظاهر من جميع الروايات أن هذا من قول رافع اجتهادًا منه؛ لأنه فهم أن المنهي عن كراء الأرض سببه الجهالة، فإذا انتفت الجهالة صح."],"en":["In another wording with him: Sometimes this one produced and the other did not, so we were forbidden from that, but we were not forbidden from silver currency.","His statement, “As for silver currency,” appears from all the narrations to be Rafi’s own legal understanding, because he understood that the reason for forbidding land rental was uncertainty, so when the uncertainty is removed, it becomes permissible."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2332},{"key":"muslim","label":"مسلم","number":1547}]},{"num":5559,"demo":false,"sanad":"","matn":["عن ابن عمر قال: عامل النبي ﷺ خيبر بشطر ما يخرج منها من ثمر أو زرع."],"takhrij":"متفق عليه: رواه البخاري (٢٣٣٠)، ومسلم (١٥٥١)، كلاهما من حديث يحيى - وهو القطان -، عن عبيد الله، أخبرني نافع، عن ابن عمر. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2330) and Muslim (1551), both through Yahya al-Qattan, from Ubayd Allah, from Nafi, from Ibn Umar. The wording is al-Bukhari’s.","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Ibn Umar said: The Prophet ﷺ made an agreement with the people of Khaybar for half of whatever came out of it of fruits or crops."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2330},{"key":"muslim","label":"مسلم","number":1551}]},{"num":5560,"demo":false,"sanad":"","matn":["عن ابن عمر قال: أعطى رسول الله ﷺ خيبر بشطر ما يخرج من ثمر أو زرع، فكان يعطي أزواجه كل سنة مائة وسق: ثمانين وسقًا من تمر، وعشرين وسقًا من شعير. فلما ولي عمر قسم خيبر، خير أزواج النبي ﷺ أن يقطع لهن الأرض والماء، أو يضمن لهن الأوساق كل عام، فاختلفن، فمنهن من اختار الأرض والماء، ومنهن من اختار الأوساق كل عام، فكانت عائشة وحفصة ممن اختارتا الأرض والماء."],"takhrij":"متفق عليه: رواه البخاري (٢٣٢٨)، ومسلم (١٥٥١:٢). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2328) and Muslim (1551:2). The wording is Muslim’s.","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ gave Khaybar on the basis of half of what came out of it in fruits or crops. He used to give his wives each year one hundred wasqs: eighty wasqs of dates and twenty wasqs of barley. Then when Umar took charge, he divided Khaybar and gave the wives of the Prophet ﷺ the choice between allotting to them land and water rights, or guaranteeing them fixed wasqs every year. They differed; some chose land and water, and some chose the yearly wasqs. Aishah and Hafsah were among those who chose land and water."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2328},{"key":"muslim","label":"مسلم","number":1551}]},{"num":5561,"demo":false,"sanad":"","matn":["عن ابن عمر أن عمر بن الخطاب أجلى اليهود والنصارى من أرض الحجاز، وأن رسول الله ﷺ لما ظهر على خيبر أراد إخراج اليهود منها، وكانت الأرض حين ظهر عليها لله ولرسوله وللمسلمين، فأراد إخراج اليهود منها، فسألت اليهود رسول الله ﷺ أن يقرهم بها على أن يكفوا عملها، ولهم نصف الثمر. فقال لهم رسول الله ﷺ: (( نقركم بها على ذلك ما شئنا )). فقروا بها حتى أجلاهم عمر إلى تيماء وأريحاء."],"takhrij":"متفق عليه: رواه البخاري (٢٣٣٨)، ومسلم (١٥٥١:٦).","grade":"متفق عليه","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2338) and Muslim (1551:6).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Ibn Umar narrated that Umar ibn al-Khattab expelled the Jews and Christians from the land of the Hijaz, and that when the Messenger of Allah ﷺ gained victory over Khaybar, he wanted to expel the Jews from it. The land, when he conquered it, belonged to Allah, His Messenger, and the Muslims. So he intended to expel the Jews from it, but the Jews asked the Messenger of Allah ﷺ to let them remain there on the condition that they would do its labor and have half the fruit. So the Messenger of Allah ﷺ said to them: “We will allow you to remain there on that basis as long as we wish.” So they remained there until Umar expelled them to Tayma and Ariha."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2338},{"key":"muslim","label":"مسلم","number":1551}]},{"num":5562,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: لما افتتحت خيبر سألت يهود رسول الله ﷺ أن يقرهم فيها على أن يعملوا على نصف ما خرج منها من الثمر والزرع، فقال رسول الله ﷺ: (( أقركم فيها على ذلك ما شئنا )).","وفيه: وكان الثمر يقسم على السهمان من نصف خيبر، فيأخذ رسول الله ﷺ الخمس."],"takhrij":"صحيح: رواه مسلم (١٥٥١:٤).","grade":"صحيح","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1551:4).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Abd Allah ibn Umar said: When Khaybar was conquered, the Jews asked the Messenger of Allah ﷺ to let them remain there on the condition that they would work it in return for half of whatever came out of it in fruits and crops. So the Messenger of Allah ﷺ said: “We will allow you to remain there on that basis as long as we wish.”","And in it: The fruit used to be divided according to the allotted shares from half of Khaybar, and the Messenger of Allah ﷺ would take the one-fifth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1551}]},{"num":5563,"demo":false,"sanad":"","matn":["عن ابن عباس قال: افتتح رسول الله ﷺ خيبر، واشترط أن له الأرض وكل صفراء وبيضاء. قال أهل خيبر: نحن أعلم بالأرض منكم، فأعطناها على أن لكم نصف الثمرة، ولنا نصف. فزعم أنه أعطاهم على ذلك، فلما كان حين يصرم النخل بعث إليهم عبد الله بن رواحة، فحزر عليهم النخل، وهو الذي يسميه أهل المدينة الخرص، فقال: في ذه كذا وكذا. قالوا: أكثرت علينا يا ابن رواحة، فقال: فأنا ألي حزر النخل، وأعطيكم نصف الذي قلت. قالوا: هذا الحق، وبه تقوم السماء والأرض، قد رضينا أن نأخذه بالذي قلت."],"takhrij":"حسن: رواه أبو داود (٣٤١٠)، وابن ماجه (١٨٢٠).","grade":"حسن","chapter_ar":"باب جواز كراء الأرض بالذهب والفضة، وبشطر ما يخرج من الأرض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3410) and Ibn Majah (1820).","chapter_en":"The permissibility of leasing land for gold and silver, and for half of what the land produces","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ conquered Khaybar and stipulated that the land and all its gold and silver would belong to him. The people of Khaybar said: We know the land better than you do, so give it to us on the basis that you will have half the fruit and we will have half. He claimed that he gave it to them on that basis. Then when the time came for estimating the date harvest, he sent Abd Allah ibn Rawahah to them, and he estimated the palms for them — what the people of Madinah call khars. He said: This much and this much is in it. They said: You have estimated too much against us, O Ibn Rawahah. So he said: Then I will do the estimate and give you half of what I have said. They said: This is justice, and by this the heavens and the earth stand. We are satisfied to take it according to what you said."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3410},{"key":"ibnmajah","label":"ابن ماجه","number":1820}]},{"num":5564,"demo":false,"sanad":"","matn":["عن طاوس أنه كان يخابر. قال عمرو (هو ابن دينار): فقلت له: يا أبا عبد الرحمن، لو تركت هذه المخابرة؛ فإنهم يزعمون أن النبي ﷺ نهى عن المخابرة، فقال: أي عمرو، أخبرني أعلمهم بذلك - يعني ابن عباس - أن النبي ﷺ لم ينه عنها، إنما قال: (( يمنح أحدكم أخاه خير له من أن يأخذ عليها خرجا معلوما ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٣٠)، ومسلم (١٢١ :١٥٥٠). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جواز المزارعة إذا لم تكن فيه الشروط الفاسدة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2330) and Muslim (1550:121). The wording is Muslim’s.","chapter_en":"What has been reported regarding the permissibility of sharecropping when it does not contain invalid conditions","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Tawus used to engage in crop-sharing. Amr — meaning Ibn Dinar — said: I said to him, “O Abu Abd al-Rahman, if only you would leave this crop-sharing, for they claim that the Prophet ﷺ forbade crop-sharing.” He said: “O Amr, the one most knowledgeable among them about that — meaning Ibn Abbas — informed me that the Prophet ﷺ did not forbid it. He only said: ‘For one of you to grant it to his brother is better for him than taking a fixed payment for it.’”"]},"buhuth":{"ar":["وفي رواية عند البخاري (٢٦٣٤) عن عمرو بن دينار أن النبي ﷺ خرج إلى أرض تهتز زرعا، فقال: (( لمن هذه؟ )) فقالوا: اكتراها فلان. فقال: (( أما إنه لو منحها إياه كان خيرا له من أن يأخذ عليها أجرا معلوما ))."],"en":["In a narration in al-Bukhari (2634), from Amr ibn Dinar, the Prophet ﷺ went out to land with crops swaying, and said: “Whose is this?” They said: “So-and-so rented it.” He said: “If he had granted it to him, that would have been better for him than taking a fixed wage for it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2330},{"key":"muslim","label":"مسلم","number":121}]},{"num":5565,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول اللّٰه ﷺ لم يحرم المزارعة، ولكن أمر أن يرفق بعضهم بعضا."],"takhrij":"حسن: رواه الترمذي (١٣٨٥). قال الترمذي: “هذا حديث حسن صحيح”.","grade":"حسن","chapter_ar":"باب ما جاء في جواز المزارعة إذا لم تكن فيه الشروط الفاسدة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1385). Al-Tirmidhi said: “This is a hasan sahih hadith.”","chapter_en":"What has been reported regarding the permissibility of sharecropping when it does not contain invalid conditions","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ did not make sharecropping unlawful, but rather instructed people to treat one another with kindness and lenience."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1385}]},{"num":5566,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن السائب قال: دخلنا على عبد اللّٰه بن معقل، فسألناه عن المزارعة، فقال: زعم ثابت أن رسول اللّٰه ﷺ نهى عن المزارعة، وأمر بالمؤاجرة، وقال: (( لا بأس بها ))."],"takhrij":"صحيح: رواه مسلم (١١٩:١٥٤٩).","grade":"صحيح","chapter_ar":"باب ما جاء في جواز المزارعة إذا لم تكن فيه الشروط الفاسدة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1549:119).","chapter_en":"What has been reported regarding the permissibility of sharecropping when it does not contain invalid conditions","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Abdullah ibn al-Saib said: We entered upon Abdullah ibn Maqil and asked him about sharecropping. He said: “Thabit claimed that the Messenger of Allah ﷺ forbade sharecropping and commanded leasing instead,” and he said: “There is no harm in it.”"]},"buhuth":{"ar":["قوله: (( المؤاجرة )) أي الإجارة، وهي تمليك منفعة بعوض لمدة معلومة."],"en":["His statement, “al-mu’ajarah,” means leasing or hiring, which is granting a benefit in return for compensation for a known period."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":119}]},{"num":5567,"demo":false,"sanad":"","matn":["عن جابر أن رسول الله ﷺ نهى عن المحاقلة، والمزابنة، والمخابرة، والثنيا، إلا أن تعلم."],"takhrij":"حسن: رواه أبو داود (٣٤٠٥)، والترمذي (١٢٩٠)، والنسائي (٣٩١١)، قال الترمذي: “حسن صحيح”.","grade":"حسن","chapter_ar":"باب النهي عن الثنيا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3405), al-Tirmidhi (1290), and al-Nasa’i (3911). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The prohibition of making an unspecified exception in a sale","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Jabir narrated that the Messenger of Allah ﷺ forbade muhaqalah, muzabanah, mukhabarah, and thunya, unless it is known."]},"buhuth":{"ar":["والثنيا من الاستثناء المجهول؛ لأنه يؤدي إلى النزاع. أما إذا علم فلا حرج فيه مثل أن يبيع ثمر الحائط، ويستثني منه شيئا معلوما كالثلث والربع ونحوه، فهذا جائز. بخلاف لو استثنى منه جزءا غير معلوم، فيبطل البيع؛ لأن البيع حينئذ يكون مجهولا."],"en":["Thunya means an unspecified exception in the sale, because it leads to dispute. If it is known, then there is no problem, such as when someone sells the fruit of an orchard and excludes a known portion like one-third or one-fourth. That is permissible. But if he excludes an unknown portion, the sale becomes invalid because the sale then becomes uncertain."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3405},{"key":"tirmidhi","label":"الترمذي","number":1290},{"key":"nasai","label":"النسائي","number":3911}]},{"num":5568,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال: قال رسول اللّٰه ﷺ: (( من زرع في أرض قوم بغير إذنهم فليس له من الزرع شيء، وله نفقته ))."],"takhrij":"حسن: رواه أبو داود (٣٤٠٣)، والترمذي (١٣٦٦) وحسّنه، وابن ماجه (٢٤٦٦)، وأحمد (١٥٨٢١).","grade":"حسن","chapter_ar":"باب فيمن زرع في أرض قوم بغير إذنهم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3403), al-Tirmidhi (1366), who graded it hasan, Ibn Majah (2466), and Ahmad (15821).","chapter_en":"About one who plants in the land of others without their permission","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Rafi ibn Khadij said: The Messenger of Allah ﷺ said: “Whoever plants in the land of a people without their permission has no right to any of the crop, but he is entitled to his expenses.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3403},{"key":"tirmidhi","label":"الترمذي","number":1366},{"key":"ibnmajah","label":"ابن ماجه","number":2466},{"key":"ahmad","label":"مسند الإمام أحمد","number":15821,"n":15821}]},{"num":5569,"demo":false,"sanad":"","matn":["عن أبي جعفر الخطمي قال:","بعثني عمي أنا وغلامًا له إلى سعيد بن المسيب.","قال: فقلنا له:","شيء بلغنا عنك في المزارعة؟","قال:","كان ابن عمر لا يرى بأسًا بها حتى بلغه عن رافع بن خديج، فأتاه، فأخبره رافع أن رسول الله ﷺ أتى بني حارثة، فرأى زرعًا في أرض ظهير، فقال:","«مَا أَحْسَنَ زَرْعَ ظُهَيْرٍ!»","قالوا:","ليس لظهير.","قال:","«أَلَيْسَ أَرْضَ ظُهَيْرٍ؟»","قالوا:","بلى، ولكنه زرع فلان.","قال:","«فَخُذُوا زَرْعَكُمْ، وَرُدُّوا عَلَيْهِ النَّفَقَةَ».","قال رافع:","فأخذنا زرعنا، ورددنا إليه النفقة.","قال سعيد:","أفقر أخاك أو أكره بالدراهم."],"takhrij":"صحيح: رواه أبو داود (٣٣٩٩)، والنسائي (٣٨٨٩)، والبيهقي (٦/١٣٦).","grade":"صحيح","chapter_ar":"باب فيمن زرع في أرض قوم بغير إذنهم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3399), al-Nasāʾī (3889), and al-Bayhaqī (6/136).","chapter_en":"About one who plants in the land of others without their permission","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Abū Jaʿfar al-Khaṭmī said:","My uncle sent me and one of his servants to Saʿīd ibn al-Musayyib.","We said to him:","“Something has reached us from you regarding sharecropping.”","He said:","“Ibn ʿUmar saw nothing wrong with it until a report from Rāfiʿ ibn Khadīj reached him, so he went to him. Rāfiʿ informed him that the Messenger of Allah ﷺ came to Banū Ḥārithah and saw crops growing on the land of Ẓuhayr. He said:","‘How excellent are the crops of Ẓuhayr!’","They said:","‘They do not belong to Ẓuhayr.’","He asked:","‘Is it not the land of Ẓuhayr?’","They replied:","‘Yes, but so-and-so planted it.’","He said:","‘Take your crop and reimburse him for his expenses.’”","Rāfiʿ said:","“So we took our crop and reimbursed him for his expenses.”","Saʿīd said:","“Lend the land to your brother for his use, or rent it out for dirhams.”"]},"buhuth":{"ar":["وقوله: «أفقر أخاك، أو أكره بالدراهم» ومعنى «أفقر أخاك»: أي أعره إياها، وأصل الإفقار في إعارة الظهر، يقال: أفقرت الرجل إذا أعرته ظهرًا للركوب."],"en":["The expression “lend it to your brother” means to allow him to use the land without charge. The original usage of ifqār referred to lending someone the back of a riding animal so that he could ride it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3399},{"key":"nasai","label":"النسائي","number":3889},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11745,"n":11853}]},{"num":5570,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن الزبير أنه حدثه أن رجلا من الأنصار خاصم الزبير عند النبي ﷺ في شراج الحرة التي يسقون بها النخل، فقال الأنصاري: سرح الماء يمر، فأبى عليه، فاختصما عند النبي ﷺ، فقال رسول اللّٰه ﷺ للزبير: (( اسق يا زبير، ثم أرسل الماء إلى جارك )). فغضب الأنصاري، فقال: أن كان ابن عمتك. فتلون وجه رسول اللّٰه ﷺ، ثم قال: (( اسق يا زبير، ثم احبس الماء حتى يرجع إلى الجدر )). فقال الزبير: والله إني لأحسب هذه الآية نزلت في ذلك: ( فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ) [سورة النساء: ٦٥]."],"takhrij":"متفق عليه: رواه البخاري (٢٣٥٩)، ومسلم (٢٣٥٧).","grade":"متفق عليه","chapter_ar":"باب الترتيب في السقي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2359) and Muslim (2357).","chapter_en":"The order of irrigation","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Abdullah ibn al-Zubayr narrated to him that a man from the Ansar disputed with al-Zubayr before the Prophet ﷺ concerning the irrigation channels of al-Harrah by which they watered the palm trees. The Ansari said: “Let the water pass through.” But al-Zubayr refused. They disputed before the Prophet ﷺ, so the Messenger of Allah ﷺ said to al-Zubayr: “Water your land, O Zubayr, then let the water pass to your neighbor.” The Ansari became angry and said: “Because he is your aunt’s son?” The face of the Messenger of Allah ﷺ changed color, then he said: “Water your land, O Zubayr, then hold back the water until it returns to the walls.” Al-Zubayr said: By Allah, I think this verse was revealed about that: “But no, by your Lord, they do not truly believe until they make you judge concerning what has arisen between them.” [al-Nisa: 65]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2359},{"key":"muslim","label":"مسلم","number":2357}]},{"num":5571,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال:","«ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ وَلَا يَنْظُرُ إِلَيْهِمْ: رَجُلٌ حَلَفَ عَلَى سِلْعَةٍ لَقَدْ أُعْطِيَ بِهَا أَكْثَرَ مِمَّا أُعْطِيَ وَهُوَ كَاذِبٌ، وَرَجُلٌ حَلَفَ عَلَى يَمِينٍ كَاذِبَةٍ بَعْدَ الْعَصْرِ لِيَقْتَطِعَ بِهَا مَالَ رَجُلٍ مُسْلِمٍ، وَرَجُلٌ مَنَعَ فَضْلَ مَائِهِ، فَيَقُولُ اللَّهُ: الْيَوْمَ أَمْنَعُكَ فَضْلِي كَمَا مَنَعْتَ فَضْلَ مَا لَمْ تَعْمَلْ يَدَاكَ»."],"takhrij":"متفق عليه: رواه البخاري (٢٣٦٩)، ومسلم (١٠٨: ١٧٤).","grade":"متفق عليه","chapter_ar":"باب كراهية منع فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2369) and Muslim (108:174).","chapter_en":"The dislike of withholding excess water","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said:","“There are three whom Allah will neither speak to on the Day of Resurrection nor look at: a man who swears concerning merchandise that he was offered more for it than he actually was, while he is lying; a man who swears a false oath after ʿAṣr in order to wrongfully take the wealth of a Muslim; and a man who withholds surplus water.","Allah will say: ‘Today I will withhold My bounty from you just as you withheld the surplus of something that your own hands did not produce.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2369},{"key":"muslim","label":"مسلم","number":108}]},{"num":5572,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال النبي ﷺ: (( يرحم اللّٰه أم إسماعيل، لو تركت زمزم - أو قال: لو لم تغرف من الماء - لكانت عينا معينا، وأقبل جرهم، فقالوا: أتأذنين أن ننزل عندك؟ قالت: نعم، ولا حق لكم في الماء. قالوا: نعم ))."],"takhrij":"صحيح: رواه البخاري (٢٣٦٨).","grade":"صحيح","chapter_ar":"باب كراهية منع فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2368).","chapter_en":"The dislike of withholding excess water","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Ibn Abbas said: The Prophet ﷺ said: “May Allah have mercy on the mother of Ismail. Had she left Zamzam — or he said: had she not scooped from the water — it would have become a flowing spring. Then Jurhum came and said: ‘Do you permit us to settle near you?’ She said: ‘Yes, but you have no right in the water.’ They said: ‘Yes.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2368}]},{"num":5573,"demo":false,"sanad":"","matn":["عن عائشة، عن النبي ﷺ قال: (( من أعمر أرضا ليست لأحد فهو أحق )). قال عروة: قضى به عمر رضي اللّٰه عنه في خلافته."],"takhrij":"صحيح: رواه البخاري (٢٣٣٥).","grade":"صحيح","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2335).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Aishah narrated from the Prophet ﷺ: “Whoever cultivates or revives land that belongs to no one has the greatest right to it.” Urwah said: Umar ruled by this during his caliphate."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2335}]},{"num":5574,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، عن النبي ﷺ قال: (( من أحيا أرضا ميتة فهي له ))."],"takhrij":"صحيح: رواه الترمذي (١٣٧٩). قال الترمذي: “حسن صحيح”. وصحّحه ابن حبان (٥٢٠٥)، وزاد في آخره: (( وما أكلت العوافي منها فهو له صدقة )). والعوافي: جمع عافية، وهو يطلق على كل من يطلب الرزق من الطير وغير ذلك.","grade":"صحيح","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1379). Al-Tirmidhi said: “Hasan Sahih.” Ibn Hibban also authenticated it (5205), and added at the end: “And whatever is eaten from it by roaming creatures is charity for him.” Al-awafi is the plural of afiyah and refers to any creature seeking provision, including birds and others.","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn Abd Allah narrated that the Prophet ﷺ said: “Whoever revives dead land, it belongs to him.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1379},{"key":"حسن_صحیح_وصححہ_ابن_حبان","label":"“حسن صحيح”. وصحّحه ابن حبان","number":5205}]},{"num":5575,"demo":false,"sanad":"","matn":["عن فضالة بن عبيد قال: قال رسول اللّٰه ﷺ: (( الأرض أرض الله، والعباد عباد الله، من أحيا مواتا فهي له ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٣١٨/١٨)، وفي مسند الشاميين (٢٨٨).","grade":"حسن","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (18/318) and in Musnad al-Shamiyyin (288).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Fadalah ibn Ubayd said: The Messenger of Allah ﷺ said: “The land is Allah’s land, and the servants are Allah’s servants. Whoever revives dead land, it belongs to him.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":318},{"key":"وفی_مسند_الشامیین","label":"وفي مسند الشاميين","number":288}]},{"num":5576,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو قال: قال رسول اللّٰه ﷺ: (( من أحيا أرضا ميتة فهي له، وليس لعرق ظالم حق ))."],"takhrij":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (٢١٨٠).","grade":"حسن","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat — Majma al-Bahrayn (2180).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Abdullah ibn Amr said: The Messenger of Allah ﷺ said: “Whoever revives dead land, it belongs to him, and no unjust claimant has any right.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":2180}]},{"num":5577,"demo":false,"sanad":"","matn":["عن سمرة بن جندب قال: قال رسول اللّٰه ﷺ: (( من أحاط حائطا على أرض فهي له ))."],"takhrij":"صحيح: رواه أحمد (٢٠١٣٠)، وأبو داود (٣٠٧٧)، وابن أبي شيبة (٧٦/٧)، والطبراني في الكبير (٦٨٦٥).","grade":"صحيح","chapter_ar":"باب من أحيا أرضا مواتا فهي له","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20130), Abu Dawud (3077), Ibn Abi Shaybah (7/76), and al-Tabarani in al-Kabir (6865).","chapter_en":"Whoever revives dead land, it belongs to him","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “Whoever encloses land with a wall, it belongs to him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3077},{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":76},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":6865},{"key":"ahmad","label":"مسند الإمام أحمد","number":20130,"n":20130}]},{"num":5578,"demo":false,"sanad":"","matn":["عن أنس قال: أراد رسول اللّٰه ﷺ أن يُقطع من البحرين، فقالت الأنصار: حتى تقطع لإخواننا من المهاجرين مثل الذي تقطع لنا. قال: (( سترون بعدي أثرة فاصبروا حتى تلقوني ))."],"takhrij":"صحيح: رواه البخاري (٢٣٧٦).","grade":"صحيح","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2376).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ intended to allot land from Bahrain. The Ansar said: “Not until you allot to our brothers from the Muhajirun the same as you allot to us.” He said: “You will see favoritism after me, so be patient until you meet me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2376}]},{"num":5579,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر قالت: كنت أنقل النوى من أرض الزبير التي أقطعه رسول اللّٰه ﷺ على رأسي."],"takhrij":"متفق عليه: رواه البخاري (٣١١٥)، ومسلم (٢١٨٢).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3115) and Muslim (2182).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Asma bint Abi Bakr said: I used to carry date-stones on my head from the land of al-Zubayr which the Messenger of Allah ﷺ had granted him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3115},{"key":"muslim","label":"مسلم","number":2182}]},{"num":5580,"demo":false,"sanad":"","matn":["عن علقمة بن وائل، عن أبيه أن رسول اللّٰه ﷺ أقطعه أرضا. قال: فأرسل معي معاوية أن أعطها إياه - أو قال: أعلمه إياها - قال: فقال لي معاوية: أردفني خلفك. فقلت: لا تكون من أرداف الملوك. قال: فقال: أعطني نعلك. فقلت: انتعل ظل الناقة. قال: فلما استخلف معاوية أتيته، فأقعدني معه على السرير، فذكرني الحديث، فقال سماك: فقال: وددت أني كنت حملته بين يدي."],"takhrij":"حسن: رواه أبو داود (٣٠٥٨)، والترمذي (١٣٨١)، والدارمي (٢٦٥١).","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3058), al-Tirmidhi (1381), and al-Darimi (2651).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Alqamah ibn Wail narrated from his father that the Messenger of Allah ﷺ granted him land. He said: Then he sent Muawiyah with me to hand it over to him — or he said: to show it to him. Muawiyah said to me: “Let me ride behind you.” I said: “That is not for the followers of kings.” He then said: “Then give me your sandals.” I said: “Walk in the shade of the she-camel.” Then when Muawiyah became caliph, I went to him, and he seated me with him on the couch, and reminded me of that incident. Simak said: He then said: “I wish I had carried him before me.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3058},{"key":"tirmidhi","label":"الترمذي","number":1381},{"key":"darimi","label":"الدارمي","number":2651}]},{"num":5581,"demo":false,"sanad":"","matn":["عن أبيض بن حمال أنه وفد إلى رسول اللّٰه ﷺ، فاستقطعه، فأقطعه الملح، فلما أدبر قال رجل: يا رسول الله، أتدري ما أقطعته؟ إنما أقطعته الماء العِدَّ، قال: فرجع فيه. وقال: سألته عما يحمى من الأراك، فقال: (( ما لم تبلغه أخفاف الإبل ))."],"takhrij":"حسن: رواه أبو داود (٣٠٦٤)، والترمذي (١٣٨٠)، وابن حبان (٤٤٩٩)، والدارقطني (٢٢١/٤).","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3064), al-Tirmidhi (1380), Ibn Hibban (4499), and al-Daraqutni (4/221).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abyad ibn Hammal came as a delegate to the Messenger of Allah ﷺ and asked him for a land grant, so he granted him a salt deposit. When he turned away, a man said: “O Messenger of Allah ﷺ, do you know what you have granted him? You have only granted him a never-ending supply like flowing water.” So he took it back from him. He said: I asked him about what may be reserved from arak trees, and he said: “As long as the camels’ hooves do not reach it.”"]},"buhuth":{"ar":["وقوله: (( الماء العد )) هو الدائم الذي لا ينقطع مثل ماء العين وماء البئر، شبه به الملح لعدم انقطاعه وحصوله بغير كد ولا عناء."],"en":["The phrase “al-ma al-idd” means water that is constant and does not run out, such as spring water or well water. Salt was compared to that because of its continuous supply and because it is obtained without ongoing effort."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3064},{"key":"tirmidhi","label":"الترمذي","number":1380},{"key":"الدارقطنی","label":"الدارقطني","number":221},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":6213,"n":6211}]},{"num":5582,"demo":false,"sanad":"","matn":["عن أبيض بن حمال أنه سأل رسول اللّٰه ﷺ عن حمى الأراك، فقال رسول اللّٰه ﷺ: (( لا حمى في الأراك )). فقال: أراكة في حظاري. فقال النبي ﷺ: (( لا حمى في الأراك ))."],"takhrij":"حسن: رواه أبو داود (٣٠٦٦).","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3066).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abyad ibn Hammal asked the Messenger of Allah ﷺ about reserving arak trees, and the Messenger of Allah ﷺ said: “There is no exclusive reserve in arak.” He said: “An arak tree in my enclosure?” The Prophet ﷺ said: “There is no exclusive reserve in arak.”"]},"buhuth":{"ar":["قال الخطابي: “يشبه أن تكون هذه الأراكة يوم إحياء الأرض، وحظر عليها قائمة فيها، فملك الأرض بالإحياء، ولم يملك الأراكة إذ كانت مرعى للسارحة. فأما الأراك إذا نبت في ملك رجل فإنه محمي لصاحبه غير محظور عليه تملكه والتصرف فيه، ولا فرق بينه وبين سائر الشجر الذي يتخذه الناس في أراضيهم”."],"en":["Al-Khattabi said: It appears that this arak tree was already standing there when the land was revived and enclosed, so he gained ownership of the land by reviving it, but not ownership of the arak tree because it was grazing land for passing animals. But if arak grows in a person’s owned land, then it is protected for its owner, and there is no restriction on his ownership or disposal of it, and it is no different from other trees people have in their lands."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3066}]},{"num":5583,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس أنه قال: أعطى النبي ﷺ بلال بن الحارث المزني المعادن القبلية جَلسيَّها وغَوريَّها، وحيث يصلح الزرع من قدس."],"takhrij":"حسن: رواه ابن زنجويه في كتاب الأموال (١٢٦٥). ورواه أبو داود (٣٠٦٢)، وأحمد (٢٧٨٦)، والبيهقي (١٤٥/٦).","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Zanjawayh in Kitab al-Amwal (1265). It was also narrated by Abu Dawud (3062), Ahmad (2786), and al-Bayhaqi (6/145).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Prophet ﷺ granted Bilal ibn al-Harith al-Muzani the Qabaliyyah mines, their highlands and lowlands, and the cultivable land of Quds."]},"buhuth":{"ar":["وقوله: (( معادن القبلية من ناحية الفرع )) الفرع بفتح الفاء، قرب سويقة في ديار جهينة.","وقوله: (( جلسيها )) يريد نجديها، ويقال لنجد جلس. قال الأصمعي: وكل مرتفع جلس.","وقوله: (( الغور )) هو ما انخفض من الأرض. يريد أنه أقطعه وهادها ورباها.","وقوله: (( قدس )) بضم القاف، وسكون الدال، جبل معروف. وقيل: هو الموضع المرتفع الذي يصلح للزراعة."],"en":["The phrase “the Qabaliyyah mines from the area of al-Far” — al-Far, with a fathah on the fa, is near Suwayqah in the lands of Juhaynah.","“Jalsiyyiha” means its elevated highlands. Najd is also called jals. Al-Asmai said: Every elevated place is called jals.","“Al-ghawr” means the low-lying parts of the land. The meaning is that he granted him both its valleys and its raised parts.","“Quds,” with a dammah on the qaf and sukun on the dal, is a known mountain. It was also said that it means elevated land suitable for cultivation."]}},"tuhfa":{},"refs":[{"key":"ابن_زنجویہ/کتاب_الاموال","label":"ابن زنجويه في كتاب الأموال","number":1265},{"key":"ورواہ_ابو_داود","label":". ورواه أبو داود","number":3062},{"key":"ahmad","label":"أحمد","number":2786},{"key":"البیہقی","label":"البيهقي","number":145}]},{"num":5584,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: لما قدم النبي ﷺ المدينة أقطع الدور، وأقطع ابن مسعود فيمن أقطع، فقال له أصحابه: يا رسول الله، نكِّبه عنا، قال: (( فلم بعثني الله إذا؟ إن الله عز وجل لا يقدس أمة لا يعطون الضعيف منهم حقه ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٢٧٤/١٠).","grade":"حسن","chapter_ar":"باب ما جاء في الإقطاع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (10/274).","chapter_en":"What has been reported regarding land grants","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Ibn Masud said: When the Prophet ﷺ came to Madinah, he allotted residential plots, and Ibn Masud was among those to whom he gave land. His companions said to him: “O Messenger of Allah ﷺ, move him away from us.” He said: “Then why did Allah send me? Allah does not purify a people who do not give the weak among them their due right.”"]},"buhuth":{"ar":["وقوله: (( نكِّبه عنا )) أي نحِّه عنا. يقال: نكَّب عن الطريق إذا عدل عنه، ونكّب غيره."],"en":["His statement, “move him away from us,” means: keep him apart from us. In Arabic, nakkaba means to turn away from a path, or to move someone else aside."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":274}]},{"num":5585,"demo":false,"sanad":"","matn":["عن سَبْرة بن عبد العزيز بن الربيع الجهني، عن أبيه، عن جده أن النبي ﷺ نزل في موضع المسجد تحت دَومة، فأقام ثلاثًا، ثم خرج إلى تبوك، وإن جهينة لحقوه بالرَّحْبَة، فقال لهم: (( من أهل ذي المروة؟ )) فقالوا: بنو رفاعة من جهينة. فقال: (( قد أقطعتها لبني رفاعة )). فاقتسموها، فمنهم من باع، ومنهم من أمسك فعمل، ثم سألت أباه عبد العزيز عن هذا الحديث، فحدثني بعضه، ولم يحدثني به كله."],"takhrij":"حسن: رواه أبو داود (٣٠٦٨). وقوله: (( الرحبة )) بفتح الراء وسكون الحاء، الأرض الواسعة.","grade":"حسن","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3068).","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Sabrah ibn Abd al-Aziz ibn al-Rabi al-Juhani narrated from his father, from his grandfather, that the Prophet ﷺ stopped at the place of the mosque beneath Dumah, stayed there three days, then departed for Tabuk. Juhaynah later caught up with him at al-Rahbah, and he said to them: “Who are the people of Dhu al-Marwah?” They said: “Banu Rifaah from Juhaynah.” He said: “I have granted it to Banu Rifaah.” So they divided it among themselves. Some of them sold their shares, while others kept them and cultivated them. Later, I asked his father Abd al-Aziz about this report, and he told me part of it, but not all of it."]},"buhuth":{"ar":["وقوله: (( ذو المروة )) قرية بوادي القرى، وهي بين المدينة والشام."],"en":["The word “al-Rahbah” means a wide open land.","“Dhu al-Marwah” is a village in Wadi al-Qura, between Madinah and Syria."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3068}]},{"num":5586,"demo":false,"sanad":"","matn":["عن الصعب بن جثامة قال: مرَّ بي النبي ﷺ بالأبواء أو بودان - وسئل عن أهل الدار يُبَيَّتُون من المشركين، فيصاب من نسائهم وذراريهم، قال: (( هم منهم ))، وسمعته يقول: (( لا حمى إلا لله ولرسوله ))."],"takhrij":"صحيح: رواه البخاري (٣٠١٢)، ومسلم (١٧٤٥). واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (3012) and Muslim (1745). The wording is al-Bukhari’s.","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Al-Sab ibn Jaththamah said: The Prophet ﷺ passed by me at al-Abwa or Waddan, and he was asked about the polytheists who are attacked by night and whose women and children may also be harmed. He said: “They are from them.” And I heard him say: “There is no protected reserve except for Allah and His Messenger.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3012},{"key":"muslim","label":"مسلم","number":1745}]},{"num":5587,"demo":false,"sanad":"","matn":["عن الصعب بن جثامة قال: إن رسول اللّٰه ﷺ قال: (( لا حمى إلا لله ولرسوله ))."],"takhrij":"صحيح: رواه البخاري (٢٣٧٠).","grade":"صحيح","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2370).","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Al-Sab ibn Jaththamah said: The Messenger of Allah ﷺ said: “There is no protected reserve except for Allah and His Messenger.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2370}]},{"num":5588,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( لا حمى إلا لله ولرسوله ))."],"takhrij":"صحيح: رواه ابن حبان (٤٦٨٥).","grade":"صحيح","chapter_ar":"باب جواز منع الرعي في أرض مخصوصة للمصلحة العامة إذا رأى الإمام ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4685).","chapter_en":"The permissibility of restricting grazing in a specific land for the public interest when the ruler sees fit","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “There is no protected reserve except for Allah and His Messenger.”"]},"buhuth":{"ar":["وقوله: (( لا حمى إلا لله ولرسوله )) أي لا يجوز لأحد أن يحمي شيئًا لنفسه، كما كان أهل الجاهلية يفعلون؛ فإن الرجل العزيز أو رئيس العشيرة كان يحمي لنفسه ما يشاء، ويمنع الناس منه.","وقوله: (( إلا لله ولرسوله )) أي إن الله ورسوله، وبعد الرسول من يقوم مقامه، وهم الخلفاء والملوك وولاة الأقاليم بإذن من الملك لهم، أن يحموا للمسلمين ما يشاؤون حسب المصلحة العامة."],"en":["The statement “There is no protected reserve except for Allah and His Messenger” means that no one may reserve land for himself the way people in the pre-Islamic period used to do, when a powerful man or tribal chief would set aside whatever he wished for himself and keep others away from it.","The exception “except for Allah and His Messenger” means that Allah and His Messenger, and after the Messenger those who take his place such as caliphs, kings, and regional governors by lawful authority, may reserve land for the Muslims according to the public interest."]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2674,"n":2671}]},{"num":5589,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ:","«مَنْ أَمْسَكَ كَلْبًا فَإِنَّهُ يَنْقُصُ كُلَّ يَوْمٍ مِنْ عَمَلِهِ قِيرَاطٌ، إِلَّا كَلْبَ حَرْثٍ أَوْ مَاشِيَةٍ»."],"takhrij":"متفق عليه: رواه البخاري (٢٣٢٢)، ومسلم (١٥٧٥/٥٩).","grade":"متفق عليه","chapter_ar":"باب جواز اقتناء الكلب للحرث والزرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2322) and Muslim (1575/59).","chapter_en":"The permissibility of keeping a dog for plowing and crops","part_en":"The Book of Sales","group_ar":"جموع أبواب المزارعة، والمساقاة","group_en":"Collection of chapters on sharecropping and orchard-tending","part_no":17,"group_no":7,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said:","“Whoever keeps a dog will have one qīrāṭ deducted from his deeds every day, except a dog kept for farming or livestock.”"]},"buhuth":{"ar":["ورواه مسلم (٥٨) من طريق آخر بلفظ:","«مَنِ اتَّخَذَ كَلْبًا إِلَّا كَلْبَ مَاشِيَةٍ أَوْ صَيْدٍ أَوْ زَرْعٍ انْتَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ قِيرَاطٌ»."],"en":["Muslim also narrated through another route:","“Whoever keeps a dog, except a dog for livestock, hunting, or crops, will have one qīrāṭ deducted from his reward every day.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2322},{"key":"muslim","label":"مسلم","number":1575}]},{"num":5590,"demo":false,"sanad":"","matn":["عن كعب بن مالك أنه تقاضى ابن أبي حَدرد دينًا كان له عليه في المسجد، فارتفعت أصواتهما، حتى سمعها رسول اللّٰه ﷺ - وهو في بيته -، فخرج إليهما حتى كشف سِجف حجرته، فنادى: (( يا كعب )). قال: لبيك يا رسول الله. قال: (( ضع من دينك هذا ))، وأومأ إليه أي الشطر. قال: لقد فعلت يا رسول الله. قال: (( قم فاقضه ))."],"takhrij":"متفق عليه: رواه البخاري (٤٥٧)، ومسلم (١٥٥٨).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (457) and Muslim (1558).","chapter_en":"What has been reported regarding reconciliation and settlement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Kab ibn Malik was demanding a debt owed to him by Ibn Abi Hadrad in the mosque, and their voices rose until the Messenger of Allah ﷺ heard them while he was in his house. He came out to them and lifted the curtain of his room, then called: “O Kab.” He said: “At your service, O Messenger of Allah ﷺ.” He said: “Reduce some of your debt,” indicating half of it. Kab said: “I have done so, O Messenger of Allah ﷺ.” He then said: “Get up and pay him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":457},{"key":"muslim","label":"مسلم","number":1558}]},{"num":5591,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( الصلح جائز بين المسلمين ))."],"takhrij":"حسن: رواه أبو داود (٣٥٩٤).","grade":"حسن","chapter_ar":"باب ما جاء في الصلح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3594).","chapter_en":"What has been reported regarding reconciliation and settlement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Settlement is permissible among Muslims.”"]},"buhuth":{"ar":["قال أبو داود: زاد أحمد بن عبد الوهاب: (( إلا صلحًا أحل حرامًا، أو حرَّم حلالًا ))."],"en":["Abu Dawud said: Ahmad ibn Abd al-Wahhab added: “Except a settlement that makes the unlawful lawful or makes the lawful unlawful.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3594}]},{"num":5592,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( اشترى رجل من رجل عقارًا له، فوجد الرجل الذي اشترى العقار في عقاره جرة فيها ذهب، فقال له الذي اشترى العقار: خذ ذهبك مني، إنما اشتريت منك الأرض، ولم أبتع منك الذهب. فقال الذي شرى الأرض: إنما بعتك الأرض وما فيها. فتحاكما إلى رجل، فقال الذي تحاكما إليه: ألكما ولد؟ قال أحدهما: لي غلام. وقال الآخر: لي جارية. قال: أنكحوا الغلام الجارية، وأنفقوا على أنفسكما منه، وتصدقا ))."],"takhrij":"متفق عليه: رواه البخاري (٣٤٧٢)، ومسلم (١٧٢١).","grade":"متفق عليه","chapter_ar":"باب استعمال الحكمة في الصلح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3472) and Muslim (1721).","chapter_en":"Using wisdom in settlement","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A man bought a piece of land from another man, then the buyer found in that land a jar containing gold. The buyer said to the seller: ‘Take your gold from me. I only bought the land from you, I did not buy the gold.’ The seller said: ‘I sold you the land and whatever was in it.’ So they brought their case to a man for judgment. He asked them: ‘Do either of you have children?’ One of them said: ‘I have a boy.’ The other said: ‘I have a girl.’ He said: ‘Marry the boy to the girl, spend from it on yourselves, and give charity.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3472},{"key":"muslim","label":"مسلم","number":1721}]},{"num":5593,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن الزبير أن رجلًا من الأنصار خاصم الزبير عند رسول اللّٰه ﷺ في شراج الحرة التي يسقون بها النخل، فقال الأنصاري: سرح الماء يمر، فأبى عليه، فاختصما عند النبي ﷺ، فقال رسول اللّٰه ﷺ: (( اسق يا زبير، ثم أرسل الماء إلى جارك )). فغضب الأنصاري، فقال: أن كان ابن عمتك. فتلون وجه رسول اللّٰه ﷺ، ثم قال: (( اسق يا زبير، ثم احبس الماء حتى يرجع إلى الجدر )). فقال الزبير: والله إن لأحسب هذه الآية نزلت في ذلك: ( فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ) [سورة النساء: ٦٥]."],"takhrij":"متفق عليه: رواه البخاري (٢٣٦٠ ،٢٣٥٩)، ومسلم (٢٣٥٧).","grade":"متفق عليه","chapter_ar":"باب الصلح في ماء السقي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2359, 2360) and Muslim (2357).","chapter_en":"Settlement regarding irrigation water","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn al-Zubayr narrated that a man from the Ansar disputed with al-Zubayr before the Messenger of Allah ﷺ over the irrigation channels of al-Harrah from which they watered the palm trees. The Ansari said: “Let the water pass through.” But al-Zubayr refused. So they brought their dispute to the Prophet ﷺ, and the Messenger of Allah ﷺ said: “Water your land, O Zubayr, then let the water pass to your neighbor.” The Ansari became angry and said: “Because he is your aunt’s son?” The face of the Messenger of Allah ﷺ changed color, then he said: “Water your land, O Zubayr, then hold back the water until it returns to the boundary wall.” Al-Zubayr said: By Allah, I believe this verse was revealed concerning that: “But no, by your Lord, they do not truly believe until they make you judge concerning what has arisen between them.” [al-Nisa: 65]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2360},{"key":"muslim","label":"مسلم","number":2357}]},{"num":5594,"demo":false,"sanad":"","matn":["عن الزبير:","أنه خاصم رجلًا من الأنصار قد شهد بدرًا إلى رسول الله ﷺ في شراج من الحرة، كانا يسقيان به كلاهما.","فقال رسول الله ﷺ للزبير:","«اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلْ إِلَى جَارِكَ».","فغضب الأنصاري، فقال:","يا رسول الله، أن كان ابن عمتك؟","فتلون وجه رسول الله ﷺ، ثم قال:","«اسْقِ، ثُمَّ احْبِسْ حَتَّى يَبْلُغَ الْجَدْرَ».","فاستوعى رسول الله ﷺ حينئذ حقه للزبير، وكان رسول الله ﷺ قبل ذلك أشار على الزبير برأي سعة له وللأنصاري، فلما أحفظ الأنصاري رسول الله ﷺ استوعى للزبير حقه في صريح الحكم.","قال عروة: قال الزبير:","والله ما أحسب هذه الآية نزلت إلا في ذلك:","{فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ}."],"takhrij":"صحيح: رواه البخاري (٢٧٠٨).","grade":"صحيح","chapter_ar":"باب الصلح في ماء السقي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2708).","chapter_en":"Settlement regarding irrigation water","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الصلح","group_en":"Collected chapters on what has been reported regarding reconciliation and settlement","part_no":17,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Al-Zubayr reported:","He disputed with a man from the Anṣār who had participated in Badr, and they brought their dispute before the Messenger of Allah ﷺ concerning an irrigation channel in al-Ḥarrah from which both of them watered their land.","The Messenger of Allah ﷺ said to al-Zubayr:","“Water your land, O Zubayr, then let the water pass on to your neighbor.”","The Anṣārī became angry and said:","“O Messenger of Allah ﷺ, is it because he is your aunt’s son?”","The face of the Messenger of Allah ﷺ changed color. Then he said:","“Water your land, then hold back the water until it reaches the boundary wall.”","At that point, the Messenger of Allah ﷺ granted al-Zubayr his full legal right. Before that, he had advised al-Zubayr to follow a lenient arrangement that would accommodate both him and the Anṣārī. But when the Anṣārī angered the Messenger of Allah ﷺ, he granted al-Zubayr his full right according to the explicit judgment.","ʿUrwah said that al-Zubayr said:","“By Allah, I think this verse was revealed concerning this incident:","‘But no, by your Lord, they will not truly believe until they make you judge concerning what has arisen between them.’”"]},"buhuth":{"ar":["وقوله: «فلما أحفظ» أي: أغضب."],"en":["The expression “when he angered him” means when he provoked the Messenger of Allah ﷺ to anger."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2708}]},{"num":5595,"demo":false,"sanad":"","matn":["عن عائشة أن رسول اللّٰه ﷺ كان يدعو في الصلاة، ويقول: (( اللهم إني أعوذ بك من المأثم والمغرم )). فقال له قائل: ما أكثر ما تستعيذ - يا رسول الله - من المغرم! قال: (( إن الرجل إذا غرم حدث فكذب، ووعد فأخلف ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٩٧)، ومسلم (٥٨٩). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الاستعاذة من الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2397) and Muslim (589). The wording is al-Bukhari’s.","chapter_en":"Seeking refuge from debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Aishah narrated that the Messenger of Allah ﷺ used to supplicate in prayer and say: “O Allah, I seek refuge in You from sin and debt.” Someone said to him: “How often you seek refuge, O Messenger of Allah ﷺ, from debt.” He said: “When a man falls into debt, he speaks and lies, and he promises and breaks his promise.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2397},{"key":"muslim","label":"مسلم","number":589}]},{"num":5596,"demo":false,"sanad":"","matn":["عن ابن عمر قال: سمعت رسول اللّٰه ﷺ يقول: (( من حالت شفاعته دون حد من حدود الله عز وجل فقد ضاد الله في أمره. ومن مات وعليه دين فليس بالدينار ولا بالدرهم، ولكنها الحسنات والسيئات. ومن خاصم في باطل - وهو يعلمه - لم يزل في سخط الله حتى ينزع. ومن قال في مؤمن ما ليس فيه أسكنه الله ردغة الخبال حتى يخرج مما قال ))."],"takhrij":"صحيح: رواه الإمام أحمد (٥٣٨٥)، وصححه الحاكم (٢٧/٢)، والبيهقي (٨٢/٦).","grade":"صحيح","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (5385), authenticated by al-Hakim (2/27), and by al-Bayhaqi (6/82).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Ibn Umar said: I heard the Messenger of Allah ﷺ say: “Whoever intercedes to prevent one of the prescribed punishments of Allah has opposed Allah in His command. Whoever dies while owing a debt, then repayment there will not be in gold coins or silver coins, but rather in good deeds and bad deeds. Whoever argues for falsehood while knowing it remains under the anger of Allah until he stops. And whoever says about a believer what is not true, Allah will make him dwell in the foul mire until he comes out of what he said.”"]},"buhuth":{"ar":["وقوله: (( أسكنه الله في ردغة الخبال )) الردغة طين ووحل كثير، جمعه ردغ ورداغ.","والخبال في الأصل الفساد، ويكون في الأفعال، والأبدان، والعقول. وقد ورد تفسيره في الحديث أنه عصارة أهل النار."],"en":["The phrase “Allah will make him dwell in the foul mire” means thick mud and filth.","The word refers originally to corruption and ruin, whether in actions, bodies, or minds. It has also been explained in hadith as the discharge of the people of Hell."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":5385},{"key":"صححہ_الحاکم","label":"صححه الحاكم","number":27},{"key":"البیہقی","label":"البيهقي","number":82},{"key":"ahmad","label":"مسند الإمام أحمد","number":5385,"n":5385},{"key":"hakim","label":"المستدرك على الصحيحين","number":2222,"n":2214},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17617,"n":17775}]},{"num":5597,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( نفس المؤمن معلقة ما كان عليه دين ))."],"takhrij":"حسن: رواه أحمد (١٠١٥٦ ،٩٦٧٩)، والدارمي (٢٦٣٣)، والبيهقي (٧٦/٦).","grade":"حسن","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (10156, 9679), al-Darimi (2633), and al-Bayhaqi (6/76).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “The soul of the believer remains suspended as long as a debt remains upon him.”"]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":76},{"key":"ahmad","label":"مسند الإمام أحمد","number":10156,"n":10156},{"key":"darimi","label":"سنن الدارمي","number":2511,"n":2511},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11412,"n":11516}]},{"num":5598,"demo":false,"sanad":"","matn":["عن ثوبان قال: قال رسول اللٰه ﷺ: (( من فارق الروح الجسد وهو بريء من ثلاث: الكنز، والغلول، والدين دخل الجنة ))."],"takhrij":"صحيح: رواه الترمذي (١٥٧٢)، وابن ماجه (٢٤١٢)، وأحمد (٢٢٤٢٧)، وابن حبان (١٩٨).","grade":"صحيح","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1572), Ibn Majah (2412), Ahmad (22427), and Ibn Hibban (198).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Thawban said: The Messenger of Allah ﷺ said: “Whoever departs from this world free of three things — hoarded wealth, betrayal of public trust, and debt — enters Paradise.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1572},{"key":"ibnmajah","label":"ابن ماجه","number":2412},{"key":"ibnhibban","label":"ابن حبان","number":198},{"key":"ahmad","label":"مسند الإمام أحمد","number":22427,"n":22427}]},{"num":5599,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول اللّٰه ﷺ: (( من مات وعليه دينار أو درهم قضي من حسناته، ليس ثم دينار ولا درهم ))."],"takhrij":"حسن: رواه ابن ماجه (٢٤١٤).","grade":"حسن","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2414).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ said: “Whoever dies owing a dinar or a dirham, it will be taken from his good deeds, for there will be no dinar or dirham there.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2414}]},{"num":5600,"demo":false,"sanad":"","matn":["عن عقبة بن عامر يقول: إن رسول اللّٰه ﷺ يقول: (( لا تخيفوا أنفسكم بعد أمنها )). قالوا: وما ذاك يا رسول الله؟ قال: (( الدين ))."],"takhrij":"حسن: رواه أحمد (١٧٤٠٧ ،١٧٣٢٠)، والطبراني في الكبير (٣٢٨/١٧)، وأبو يعلى (١٧٣٩)، والحاكم (٢٦/٢).","grade":"حسن","chapter_ar":"باب التشديد في الدين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17407, 17320), al-Tabarani in al-Kabir (17/328), Abu Yala (1739), and al-Hakim (2/26).","chapter_en":"The stern warning regarding debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Uqbah ibn Amir said: The Messenger of Allah ﷺ said: “Do not frighten yourselves after having been safe.” They said: “What is that, O Messenger of Allah ﷺ?” He said: “Debt.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":328},{"key":"ابو_یعلی","label":"أبو يعلى","number":1739},{"key":"hakim","label":"الحاكم","number":26},{"key":"ahmad","label":"مسند الإمام أحمد","number":17407,"n":17407}]},{"num":5601,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن أبي قتادة، عن أبي قتادة أنه سمعه يحدث عن رسول اللّٰه ﷺ: أنه قام فيهم، فذكر لهم: (( أن الجهاد في سبيل اللّٰه والإيمان بالله أفضل الأعمال )). فقام رجل، فقال: يا رسول الله، أرأيت إن قتلت في سبيل اللّٰه تكفر عني خطاياي؟ فقال له رسول اللّٰه ﷺ: (( نعم، إن قتلت في سبيل اللّٰه وأنت صابر محتسب مقبل غير مدبر )). ثم قال رسول اللّٰه ﷺ: (( كيف قلت؟ )). قال: أرأيت إن قتلت في سبيل اللّٰه أتكفر عني خطاياي؟ فقال رسول اللّٰه ﷺ: (( نعم، وأنت صابر محتسب مقبل غير مدبر إلا الدَّين، فإن جبريل عليه السلام قال لي ذلك ))."],"takhrij":"صحيح: رواه مسلم (١٨٨٥).","grade":"صحيح","chapter_ar":"باب من قتل في سبيل الله كفرت خطاياه إلا الدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1885).","chapter_en":"The one who is killed in the path of Allah has his sins expiated except debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Abi Qatadah narrated from Abu Qatadah that he heard him narrating from the Messenger of Allah ﷺ that he stood among them and mentioned to them: “Jihad in the path of Allah and faith in Allah are the best deeds.” A man stood and said: “O Messenger of Allah ﷺ, if I am killed in the path of Allah, will my sins be expiated for me?” The Messenger of Allah ﷺ said to him: “Yes, if you are killed in the path of Allah while being patient, seeking reward, advancing and not retreating.” Then the Messenger of Allah ﷺ said: “What did you say?” He said: “If I am killed in the path of Allah, will my sins be expiated for me?” The Messenger of Allah ﷺ said: “Yes, while you are patient, seeking reward, advancing and not retreating, except debt, for Jibril, peace be upon him, told me that.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1885}]},{"num":5602,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو أن رسول اللّٰه ﷺ قال: (( يغفر للشهيد كل ذنب إلا الدين ))."],"takhrij":"صحيح: رواه مسلم (١٨٨٦). وفي رواية عنده: (( القتل في سبيل اللّٰه يكفر كل شيء إلا الدين )).","grade":"صحيح","chapter_ar":"باب من قتل في سبيل الله كفرت خطاياه إلا الدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1886). In another wording with him: “Being killed in the path of Allah expiates everything except debt.”","chapter_en":"The one who is killed in the path of Allah has his sins expiated except debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Amr narrated that the Messenger of Allah ﷺ said: “Every sin of the martyr is forgiven except debt.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1886}]},{"num":5603,"demo":false,"sanad":"","matn":["عن جابر أنه أخبره أن أباه توفي وترك عليه ثلاثين وسقًا لرجل من اليهود، فاستنظره جابر، فأبى أن ينظره، فكلم جابر رسول اللّٰه ﷺ؛ ليشفع له إليه، فجاء رسول اللّٰه ﷺ، فكلم اليهودي ليأخذ ثمر نخله بالذي له، فأبى، فدخل رسول اللّٰه ﷺ النخل، فمشى فيها، ثم قال لجابر: (( جُدَّ له، فأوفِ له الذي له )). فجده بعدما رجع رسول اللّٰه ﷺ، فأوفاه ثلاثين وسقًا، وفضلت له سبعة عشر وسقًا، فجاء جابر رسول اللّٰه ﷺ ليخبره بالذي كان، فوجده يصلي العصر، فلما انصرف أخبره بالفضل، فقال: (( أخبر ذلك ابن الخطاب )). فذهب جابر إلى عمر، فأخبره، فقال له عمر: لقد علمت حين مشى فيها رسول اللّٰه ﷺ ليباركن فيها."],"takhrij":"صحيح: رواه البخاري (٢٣٩٦).","grade":"صحيح","chapter_ar":"باب قضاء الدين عن الميت","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2396).","chapter_en":"Paying the debt of the deceased","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Jabir narrated that his father died and left behind a debt of thirty wasqs owed to a Jewish man. Jabir asked him to grant time, but he refused. So Jabir spoke to the Messenger of Allah ﷺ to intercede for him. The Messenger of Allah ﷺ came and spoke to the Jew so that he would take the produce of his palm trees for what was owed to him, but he refused. Then the Messenger of Allah ﷺ entered the orchard and walked through it, then said to Jabir: “Harvest it and pay him what is owed to him.” So Jabir harvested it after the Messenger of Allah ﷺ returned, paid him the thirty wasqs, and seventeen wasqs remained extra. Jabir came to the Messenger of Allah ﷺ to tell him what had happened and found him praying Asr. When he finished, Jabir told him about the surplus, and he said: “Inform Ibn al-Khattab of that.” Jabir went to Umar and informed him, and Umar said to him: I knew when the Messenger of Allah ﷺ walked through it that blessing would be placed in it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2396}]},{"num":5604,"demo":false,"sanad":"","matn":["عن سعد بن الأطول أن أخاه مات، وترك ثلاثمائة درهم، وترك عيالًا، فأردت أن أنفقها على عياله. فقال النبي ﷺ: (( إن أخاك محتبس بدينه، فاقض عنه )). فقال: يا رسول الله، قد أديت عنه إلا دينارين ادعتهما امرأة، وليس لها بينة. قال: (( فأعطها فإنها محقة ))."],"takhrij":"حسن: رواه ابن ماجه (٢٤٣٣)، وأحمد (٢٠٠٧٧ ،٢٠٠٧٦ ،١٧٢٢٧).","grade":"حسن","chapter_ar":"باب قضاء الدين عن الميت","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2433) and Ahmad (20077, 20076, 17227).","chapter_en":"Paying the debt of the deceased","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Sad ibn al-Atwal said that his brother died and left three hundred dirhams and left dependents behind. I wanted to spend that money on his dependents. The Prophet ﷺ said: “Your brother is being held back by his debt, so pay it off for him.” He said: “O Messenger of Allah ﷺ, I have paid it except for two dinars that a woman claims, but she has no proof.” He said: “Give them to her, for she is truthful.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2433},{"key":"ahmad","label":"مسند الإمام أحمد","number":20076,"n":20076}]},{"num":5605,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( لو كان عندي أُحُد ذهبًا لأحببت أن لا يأتي عليَّ ثلاث، وعندي منه دينار - ليس شيء أرصده في دين علي - أجد من يقبله ))."],"takhrij":"متفق عليه: رواه البخاري (٧٢٢٨)، ومسلم (٩٩١). وقوله: (( أرصده )) أي أعده.","grade":"متفق عليه","chapter_ar":"باب الترغيب في قضاء الديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7228) and Muslim (991).","chapter_en":"Encouragement to repay debts","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “If I had Uhud mountain in gold, I would not like three nights to pass while a single dinar remained with me — except something I set aside for a debt upon me — until I found someone to take it.”"]},"buhuth":{"en":["The phrase “I set aside” means: I reserve it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7228},{"key":"muslim","label":"مسلم","number":991}]},{"num":5606,"demo":false,"sanad":"","matn":["عن أبي ذر قال: قال رسول اللّٰه ﷺ: (( ما يسرني أن عندي مثل أحد هذا ذهبًا تمضي عليَّ ثالثة، وعندي منه دينار إلا شيئًا أرصده لدين، إلا أن أقول به في عباد اللّٰه هكذا وهكذا وهكذا، عن يمينه، وعن شماله، ومن خلفه ))."],"takhrij":"متفق عليه: رواه البخاري (٦٤٤٤)، ومسلم (٩٩٢).","grade":"متفق عليه","chapter_ar":"باب الترغيب في قضاء الديون","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6444) and Muslim (992).","chapter_en":"Encouragement to repay debts","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Dharr said: The Messenger of Allah ﷺ said: “It would not please me to have the like of this mountain of Uhud in gold and for three nights to pass while I still had a dinar of it, except something I reserve for a debt, unless I were to distribute it among the servants of Allah like this, and this, and this,” to his right, to his left, and behind him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6444},{"key":"muslim","label":"مسلم","number":992}]},{"num":5607,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( من أخذ أموال الناس يريد أداءها أدَّى اللّٰه عنه، ومن أخذ يريد إتلافها أتلفه اللّٰه ))."],"takhrij":"صحيح: رواه البخاري (٢٣٨٧).","grade":"صحيح","chapter_ar":"باب من استدان دينا وهو ينوي قضاءه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2387).","chapter_en":"The one who borrows while intending repayment","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “Whoever takes people’s wealth intending to repay it, Allah will repay it on his behalf; and whoever takes it intending to destroy it, Allah will destroy him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2387}]},{"num":5608,"demo":false,"sanad":"","matn":["عن ميمونة زوج النبي ﷺ أنها استدانت، فقيل لها: يا أم المؤمنين، تستدينين وليس عندك وفاء؟ قالت: إني سمعت رسول اللّٰه ﷺ يقول: (( من أخذ دينا وهو يريد أن يؤديه أعانه اللّٰه عز وجل ))."],"takhrij":"حسن: رواه النسائي (٤٦٨٦ ،٤٦٨٧)، وابن ماجه (٢٤٠٨)، وعبد بن حميد (١٥٤٩)، وابن حبان (٥٠٤١).","grade":"حسن","chapter_ar":"باب من استدان دينا وهو ينوي قضاءه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasai (4686, 4687), Ibn Majah (2408), Abd ibn Humayd (1549), and Ibn Hibban (5041).","chapter_en":"The one who borrows while intending repayment","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Maymunah, the wife of the Prophet ﷺ, once borrowed money. It was said to her: “O Mother of the Believers, you borrow while you do not have means to repay?” She said: I heard the Messenger of Allah ﷺ say: “Whoever takes a debt while intending to repay it, Allah the Mighty and Majestic will help him.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4686},{"key":"ibnmajah","label":"ابن ماجه","number":2408},{"key":"عبد_بن_حمید","label":"عبد بن حميد","number":1549},{"key":"ibnhibban","label":"ابن حبان","number":5041}]},{"num":5609,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن جعفر قال: قال رسول اللّٰه ﷺ: (( إن اللّٰه مع الدائن حتى يقضي دينه ما لم يكن فيما يكره اللّٰه ))."],"takhrij":"حسن: رواه ابن ماجه (٢٤٠٩)، والدارمي (٢٦٣٧)، والحاكم (٢٣/٢)، والبيهقي (٣٥٥/٥).","grade":"حسن","chapter_ar":"باب من استدان دينا وهو ينوي قضاءه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2409), al-Darimi (2637), al-Hakim (2/23), and al-Bayhaqi (5/355).","chapter_en":"The one who borrows while intending repayment","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abdullah ibn Jafar said: The Messenger of Allah ﷺ said: “Allah is with the debtor until he pays his debt, so long as it was not incurred in something Allah dislikes.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2409},{"key":"البیہقی","label":"البيهقي","number":355},{"key":"darimi","label":"سنن الدارمي","number":2515,"n":2515},{"key":"hakim","label":"المستدرك على الصحيحين","number":2205,"n":2198},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10960,"n":11054}]},{"num":5610,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رجلًا أتى النبي ﷺ يتقاضاه بعيرًا، قال: فقال رسول اللّٰه ﷺ: (( أعطوه )). فقالوا: لا نجد إلا سنًّا أفضل من سنه. فقال الرجل: أوفيتني أوفاك الله. فقال رسول اللّٰه ﷺ: (( أعطوه؛ فإن من خيار الناس أحسنهم قضاءً ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٩٢)، ومسلم (١٢٢ :١٦٠١). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2392) and Muslim (1601:122). The wording is al-Bukhari’s.","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abu Hurairah narrated that a man came to the Prophet ﷺ demanding a camel that he was owed. The Messenger of Allah ﷺ said: “Give it to him.” They said: “We only find one better in age than his.” The man said: “You have fulfilled my due — may Allah fulfill yours.” The Messenger of Allah ﷺ said: “Give it to him, for the best of people are those best in repayment.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2392},{"key":"muslim","label":"مسلم","number":122}]},{"num":5611,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: كان لرجل على رسول اللّٰه ﷺ حق، فأغلظ له، فهمَّ به أصحاب النبي ﷺ، فقال النبي ﷺ: (( إن لصاحب الحق مقالًا، اشتروا له سنًّا فأعطوه إياه )). فقالوا: إنا لا نجد إلا سنًّا هو خير من سنه. قال: (( فاشتروا فأعطوه إياه؛ فإن من خيركم - أو خيركم - أحسنكم قضاءً ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٠٦)، ومسلم (١٢٠ :١٦٠١). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2306) and Muslim (1601:120). The wording is Muslim’s.","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abu Hurairah said: A man had a claim against the Messenger of Allah ﷺ, and he spoke harshly to him. The companions of the Prophet ﷺ intended to deal with him, but the Prophet ﷺ said: “The one who has a right may speak. Buy for him a camel of the proper age and give it to him.” They said: “We only find one better than his.” He said: “Then buy it and give it to him, for among the best of you — or the best of you — are those best in repayment.”"]},"buhuth":{"ar":["وعند البخاري في أوله: (( دعوه؛ فإن لصاحب الحق مقالًا … ))."],"en":["In al-Bukhari the beginning reads: “Leave him, for the one who has a right may speak.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2306},{"key":"muslim","label":"مسلم","number":120}]},{"num":5612,"demo":false,"sanad":"","matn":["عن أبي هريرة قال:","أتى النبي ﷺ رجل يتقاضاه، قد استسلف منه شطر وسق، فأعطاه وسقًا، فقال:","«نِصْفُ وَسْقٍ لَكَ، وَنِصْفُ وَسْقٍ لَكَ مِنْ عِنْدِي».","ثم جاء صاحب الوسق يتقاضاه، فأعطاه وسقين، فقال رسول الله ﷺ:","«وَسْقٌ لَكَ، وَوَسْقٌ مِنْ عِنْدِي»."],"takhrij":"حسن: رواه البزار في كشف الأستار (١٣٠٦).","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (1306).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah reported:","A man came to the Prophet ﷺ seeking repayment of half a wasq that the Prophet ﷺ had borrowed from him. He gave him a full wasq and said:","“Half a wasq is what is due to you, and the other half wasq is a gift from me.”","Then another man to whom a full wasq was owed came seeking repayment. The Prophet ﷺ gave him two wasqs and said:","“One wasq is what is due to you, and one wasq is from me.”"]}},"tuhfa":{},"refs":[{"key":"البزار/کشف_الاستار","label":"البزار في كشف الأستار","number":1306},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1306,"n":1307}]},{"num":5613,"demo":false,"sanad":"","matn":["عن أبي رافع مولى رسول اللّٰه ﷺ أنه قال: استسلف رسول اللّٰه ﷺ بكرًا فجاءته إبل من الصدقة. قال أبو رافع: فأمرني رسول اللّٰه ﷺ أن أقضي الرجل بكره، فقلت: لم أجد في الإبل إلا جملا خيارًا رباعيًّا، فقال رسول اللّٰه ﷺ: (( أعطه إياه؛ فإن خيار الناس أحسنهم قضاءً ))."],"takhrij":"صحيح: رواه مالك (٨٩)، ومسلم (١١٨ :١٦٠٠).","grade":"صحيح","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (89) and Muslim (1600:118).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abu Rafi, the freed slave of the Messenger of Allah ﷺ, said: The Messenger of Allah ﷺ borrowed a young camel. Then camels from charity arrived. Abu Rafi said: The Messenger of Allah ﷺ ordered me to repay the man his camel. I said: “I found among the camels only an excellent mature camel.” The Messenger of Allah ﷺ said: “Give it to him, for the best of people are those best in repayment.”"]},"buhuth":{"ar":["قال مالك: “لا بأس بأن يقبض من أسلف شيئًا من الذهب أو الورق أو الطعام أو الحيوان ممن أسلفه ذلك أفضل مما أسلفه إذا لم يكن ذلك على شرط منهما أو عادة، فإن كان ذلك على شرط أو وعد أو عادة فذلك مكروه، ولا خير فيه”.","وقوله: (( أو وعد )) أي وعد سابق."],"en":["Malik said: There is no harm in a person receiving, from one to whom he loaned gold, silver, food, or animals, something better than what he loaned, so long as it was not stipulated between them and was not a customary expectation. If it was a condition, a promise, or an established habit, then it is disliked and not good.","The word “or a promise” means: a prior promise."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":89},{"key":"muslim","label":"مسلم","number":118}]},{"num":5614,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: كان لي على النبي ﷺ دين، فقضاني، وزادني، ودخلت عليه المسجد، فقال لي: (( صل ركعتين ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٩٤)، ومسلم (٧١ :٧١٥) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2394) and Muslim (715:71). The wording is Muslim’s.","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Prophet ﷺ owed me a debt, and he repaid me and gave me extra. Then I entered upon him in the mosque and he said to me: “Pray two units of prayer.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2394},{"key":"muslim","label":"مسلم","number":71}]},{"num":5615,"demo":false,"sanad":"","matn":["عن إسماعيل بن إبراهيم بن عبد اللّٰه بن أبي ربيعة المخزومي، عن أبيه، عن جده أن النبي ﷺ استسلف منه حين غزا حنين ثلاثين أو أربعين ألفًا، فلما قدم قضاها إياه. ثم قال له النبي ﷺ: (( بارك اللّٰه لك في أهلك ومالك. إنما جزاء السلف الوفاء والحمد ))."],"takhrij":"حسن: رواه النسائي (٤٦٨٣)، وابن ماجه (٢٤٢٤)، وأحمد (١٦٤١٠)، والبيهقي (٣٥٥/٥).","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasai (4683), Ibn Majah (2424), Ahmad (16410), and al-Bayhaqi (5/355).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Ismail ibn Ibrahim ibn Abdullah ibn Abi Rabiah al-Makhzumi narrated from his father, from his grandfather, that the Prophet ﷺ borrowed from him thirty or forty thousand during the campaign of Hunayn. When he returned, he repaid him. Then the Prophet ﷺ said to him: “May Allah bless your family and your wealth. The reward for a loan is repayment and gratitude.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4683},{"key":"ibnmajah","label":"ابن ماجه","number":2424},{"key":"البیہقی","label":"البيهقي","number":355},{"key":"ahmad","label":"مسند الإمام أحمد","number":16410,"n":16410}]},{"num":5616,"demo":false,"sanad":"","matn":["عن العرباض بن سارية يقول: كنت عند النبي ﷺ، فقال أعرابي: اقضني بكري. فأعطاه بعيرًا مسنًّا، فقال الأعرابي: يا رسول الله، هذا أسن من بعيري، فقال رسول اللّٰه ﷺ: (( خير الناس خيرهم قضاءً ))."],"takhrij":"حسن: رواه النسائي (٤٦١٩)، وابن ماجه (٢٢٨٦)، وأحمد (١٧١٤٩)، والحاكم (٣٠/٢)، والبيهقي (٣٥١/٥).","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasai (4619), Ibn Majah (2286), Ahmad (17149), al-Hakim (2/30), and al-Bayhaqi (5/351).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Al-Irbad ibn Sariyah said: I was with the Prophet ﷺ when a Bedouin said: “Repay me my young camel.” So he gave him an older camel. The Bedouin said: “O Messenger of Allah ﷺ, this is older than my camel.” The Messenger of Allah ﷺ said: “The best of people are those best in repayment.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4619},{"key":"ibnmajah","label":"ابن ماجه","number":2286},{"key":"hakim","label":"الحاكم","number":30},{"key":"البیہقی","label":"البيهقي","number":351},{"key":"ahmad","label":"مسند الإمام أحمد","number":17149,"n":17149}]},{"num":5617,"demo":false,"sanad":"","matn":["عن عائشة قالت:","ابتاع رسول الله ﷺ من رجل من الأعراب جزورًا - أو جزائر - بوسق من تمر الذخرة، وتمر الذخرة العجوة.","فرجع به رسول الله ﷺ إلى بيته، فالتمس له التمر فلم يجده، فخرج إليه رسول الله ﷺ فقال له:","«يَا عَبْدَ اللَّهِ، إِنَّا قَدِ ابْتَعْنَا مِنْكَ جَزُورًا - أَوْ جَزَائِرَ - بِوَسْقٍ مِنْ تَمْرِ الذَّخِرَةِ، فَالْتَمَسْنَاهُ فَلَمْ نَجِدْهُ».","فقال الأعرابي:","واغدراه!","قالت: فنهمه الناس وقالوا:","قاتلك الله، أيغدر رسول الله ﷺ؟","فقال رسول الله ﷺ:","«دَعُوهُ؛ فَإِنَّ لِصَاحِبِ الْحَقِّ مَقَالًا».","ثم عاد له رسول الله ﷺ فقال:","«يَا عَبْدَ اللَّهِ، إِنَّا ابْتَعْنَا مِنْكَ جَزَائِرَكَ، وَنَحْنُ نَظُنُّ أَنَّ عِنْدَنَا مَا سَمَّيْنَا لَكَ، فَالْتَمَسْنَاهُ فَلَمْ نَجِدْهُ».","فقال الأعرابي:","واغدراه!","فنهمه الناس وقالوا:","قاتلك الله، أبغدر رسول الله ﷺ؟","فقال رسول الله ﷺ:","«دَعُوهُ؛ فَإِنَّ لِصَاحِبِ الْحَقِّ مَقَالًا».","فردد ذلك رسول الله ﷺ مرتين أو ثلاثًا.","فلما رآه لا يفقه عنه قال لرجل من أصحابه:","«اذْهَبْ إِلَى خُوَيْلَةَ بِنْتِ حَكِيمِ بْنِ أُمَيَّةَ، فَقُلْ لَهَا: رَسُولُ اللَّهِ ﷺ يَقُولُ لَكِ: إِنْ كَانَ عِنْدَكِ وَسْقٌ مِنْ تَمْرِ الذَّخِرَةِ فَأَسْلِفِينَاهُ حَتَّى نُؤَدِّيَهُ إِلَيْكِ إِنْ شَاءَ اللَّهُ».","فذهب إليها الرجل، ثم رجع فقال:","قالت: نعم، هو عندي يا رسول الله، فابعث من يقبضه.","فقال رسول الله ﷺ للرجل:","«اذْهَبْ بِهِ فَأَوْفِهِ الَّذِي لَهُ».","فذهب به فأوفاه الذي له.","قالت:","فمر الأعرابي برسول الله ﷺ وهو جالس في أصحابه، فقال:","جزاك الله خيرًا؛ فقد أوفيت وأطيبت.","فقال رسول الله ﷺ:","«أُولَئِكَ خِيَارُ عِبَادِ اللَّهِ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ، الْمُوفُونَ الْمُطَيِّبُونَ»."],"takhrij":"حسن: رواه أحمد (٢٦٣١٢)، والبزار في كشف الأستار (١٣٠٩).","grade":"حسن","chapter_ar":"باب ما جاء في حسن القضاء بالزيادة وغيرها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26312) and al-Bazzār in Kashf al-Astār (1309).","chapter_en":"What has been reported regarding excellence in repayment through giving extra and similar manners","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah reported:","The Messenger of Allah ﷺ purchased from a Bedouin a camel—or several camels—for one wasq of al-dhakhīrah dates, and al-dhakhīrah dates were ʿajwah dates.","The Messenger of Allah ﷺ returned home with the animal and searched for the dates to pay the man, but he could not find them. He went out to the Bedouin and said:","“O servant of Allah, we purchased from you a camel—or camels—for one wasq of al-dhakhīrah dates, but we looked for them and could not find them.”","The Bedouin exclaimed:","“What treachery!”","The people rebuked him and said:","“May Allah deal with you! Would the Messenger of Allah ﷺ betray anyone?”","The Messenger of Allah ﷺ said:","“Leave him, for the person who possesses a right is entitled to speak.”","Then the Messenger of Allah ﷺ repeated to him:","“O servant of Allah, we purchased your camels while thinking that we possessed what we had specified for you. We searched for it, but we could not find it.”","The Bedouin again exclaimed:","“What treachery!”","The people rebuked him and said:","“May Allah deal with you! Would the Messenger of Allah ﷺ betray anyone?”","The Messenger of Allah ﷺ said:","“Leave him, for the person who possesses a right is entitled to speak.”","The Messenger of Allah ﷺ repeated this two or three times.","When he saw that the man did not understand, he said to one of his Companions:","“Go to Khuwaylah bint Ḥakīm ibn Umayyah and say to her: ‘The Messenger of Allah ﷺ says to you: If you have one wasq of al-dhakhīrah dates, lend it to us until we repay you, if Allah wills.’”","The man went to her and then returned, saying:","“She says: Yes, I have it, O Messenger of Allah ﷺ. Send someone to collect it.”","The Messenger of Allah ﷺ said to the man:","“Take it to him and give him in full what is owed to him.”","So he took it and paid the Bedouin his full due.","ʿĀʾishah said:","The Bedouin later passed by the Messenger of Allah ﷺ while he was sitting among his Companions and said:","“May Allah reward you with good. You have paid in full and dealt generously.”","The Messenger of Allah ﷺ said:","“Those are the best servants of Allah in the sight of Allah on the Day of Resurrection: those who fulfill what they owe and do so graciously.”"]}},"tuhfa":{},"refs":[{"key":"البزار/کشف_الاستار","label":"البزار في كشف الأستار","number":1309},{"key":"ahmad","label":"مسند الإمام أحمد","number":26312,"n":26312}]},{"num":5618,"demo":false,"sanad":"","matn":["عن ابن عمر، وعائشة أن رسول اللّٰه ﷺ قال: (( من طلب حقًا فليطلب في عفاف وافٍ، أو غير وافٍ ))."],"takhrij":"حسن: رواه ابن ماجه (٢٤٢١)، وصححه ابن حبان (٥٠٨٠)، والحاكم (٣٢/٢)، والبيهقي (٣٥٨/٥).","grade":"حسن","chapter_ar":"باب حسن المطالبة، وأخذ الحق في عفاف","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2421), authenticated by Ibn Hibban (5080), al-Hakim (2/32), and al-Bayhaqi (5/358).","chapter_en":"Properly seeking repayment and taking one’s right with dignity","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Ibn Umar and Aishah narrated that the Messenger of Allah ﷺ said: “Whoever seeks his right should seek it with dignity, whether it is fully paid or not fully paid.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2421},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":5080},{"key":"البیہقی","label":"البيهقي","number":358},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1823,"n":1820},{"key":"hakim","label":"المستدرك على الصحيحين","number":2238,"n":2230},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10980,"n":11074}]},{"num":5619,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال لصاحب الحق: (( خذ حقك في عفاف وافٍ، أو غير وافٍ ))."],"takhrij":"حسن: رواه ابن ماجه (٢٤٢٢).","grade":"حسن","chapter_ar":"باب حسن المطالبة، وأخذ الحق في عفاف","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2422).","chapter_en":"Properly seeking repayment and taking one’s right with dignity","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said to the one who had a claim: “Take your right with dignity, whether fully or not fully.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2422}]},{"num":5620,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال:","«مَطْلُ الْغَنِيِّ ظُلْمٌ، وَإِذَا أُتْبِعَ أَحَدُكُمْ عَلَى مَلِيءٍ فَلْيَتَّبِعْ»."],"takhrij":"متفق عليه: رواه مالك (٨٤)، والبخاري (٢٢٨٧)، ومسلم (١٥٦٤).","grade":"متفق عليه","chapter_ar":"باب عدم جواز تأخير الوفاء بالدين لمن قدر عليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (84), al-Bukhārī (2287), and Muslim (1564).","chapter_en":"The impermissibility of delaying repayment of debt for one who is able","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said:","“Delay in payment by one who is able to pay is injustice. If one of you is referred for payment to a solvent person, then let him accept the transfer.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":84},{"key":"bukhari","label":"البخاري","number":2287},{"key":"muslim","label":"مسلم","number":1564}]},{"num":5621,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أن أباه قتل يوم أحد شهيدًا وعليه دين، فاشتد الغرماء في حقوقهم، فأتيت النبي ﷺ، فسألهم أن يقبلوا تمر حائطي، ويحللوا أبي، فأبوا، فلم يعطهم النبي ﷺ حائطي، وقال: (( سنغدو عليك )). فغدا علينا حين أصبح، فطاف في النخل، ودعا في ثمرها بالبركة، فجددتها فقضيتهم، وبقي لنا من تمرها."],"takhrij":"صحيح: رواه البخاري (٢٣٩٥).","grade":"صحيح","chapter_ar":"باب تأخير يوم أو نحوه لا يعد مطلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2395).","chapter_en":"Delaying for a day or the like is not considered procrastination","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Jabir ibn Abdullah said: My father was killed as a martyr on the Day of Uhud and he had debts. The creditors pressed strongly for their rights, so I came to the Prophet ﷺ and asked him to request that they accept the dates of my orchard and release my father, but they refused. The Prophet ﷺ did not hand over my orchard to them and said: “We will come to you in the morning.” So he came to us in the morning, walked through the palm trees, and supplicated for blessing in their fruit. Then I harvested the dates, repaid the creditors, and some of the dates remained for us."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2395}]},{"num":5622,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: غزوت مع النبي ﷺ، فقال: (( كيف ترى بعيرك؟ أتبيعه؟ )) قلت: نعم، فبعته إياه، فلما قدم المدينة غدوت إليه بالبعير، فأعطاني ثمنه."],"takhrij":"متفق عليه: رواه البخاري (٢٣٨٥)، ومسلم (١١ :٧١٥) واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب جواز الشراء بالدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2385) and Muslim (715:11). The wording is al-Bukhari’s.","chapter_en":"The permissibility of purchasing on credit","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn Abdullah said: I went on a campaign with the Prophet ﷺ, and he said: “How do you find your camel? Will you sell it?” I said: Yes. So I sold it to him. When we arrived in Madinah, I brought the camel to him in the morning, and he gave me its price."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2385},{"key":"muslim","label":"مسلم","number":11}]},{"num":5623,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول اللّٰه ﷺ أنه ذكر: (( أن رجلا من بني إسرائيل سأل بعض بني إسرائيل أن يسلفه ألف دينار، قال: ائتني بشهداء أشهدهم. قال: كفى بالله شهيدا. قال: ائتني بالكفيل. قال: كفى بالله كفيلا. قال: صدقت. فدفعها إليه إلى أجل مسمى )). الحديث."],"takhrij":"صحيح: رواه أحمد (٨٥٨٧) والبخاري (٢٤٠٤) تعليقا.","grade":"صحيح","chapter_ar":"باب الدَّين إلى أجل مسمى","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (8587), and al-Bukhari (2404) in suspended form.","chapter_en":"Debt to a specified term","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ mentioned: “A man from the Children of Israel asked another man from the Children of Israel to lend him one thousand dinars. He said: ‘Bring me witnesses so I may have them witness it.’ He said: ‘Allah is sufficient as a witness.’ He said: ‘Bring me a guarantor.’ He said: ‘Allah is sufficient as a guarantor.’ He said: ‘You have spoken truthfully.’ So he gave it to him until a specified term.” The rest of the hadith follows."]},"intro":{"ar":["قال اللّٰه تعالى: ( يَاأَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنْتُم بِدَيْنٍ إِلَى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ ) [البقرة: ٢٨٢]."],"en":["Allah the Exalted said: “O you who believe, when you contract a debt for a specified term, write it down.” [al-Baqarah: 282]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2404},{"key":"ahmad","label":"مسند الإمام أحمد","number":8587,"n":8587}]},{"num":5624,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( كان تاجر يداين الناس، فإذا رأى معسرا قال لفتيانه: تجاوزوا عنه، لعل اللّٰه أن يتجاوز عنا، فتجاوز اللّٰه عنه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٧٨)، ومسلم (١٥٦٢).","grade":"متفق عليه","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2078) and Muslim (1562).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “There was a merchant who used to lend people money. Whenever he saw someone in hardship, he would say to his servants: ‘Overlook him, perhaps Allah will overlook us.’ So Allah overlooked him.”"]},"intro":{"ar":["قال اللّٰه تعالى: ( فَنَظِرَةٌ إِلَى مَيْسَرَةٍ ) [سورة البقرة: ٢٨٠] أي يسار."],"en":["Allah the Exalted said: “Then let there be postponement until ease.” [al-Baqarah: 280] Meaning: until the debtor has means."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2078},{"key":"muslim","label":"مسلم","number":1562}]},{"num":5625,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( من نفس عن مؤمن كربة من كرب الدنيا نفس اللّٰه عنه كربة من كرب يوم القيامة، ومن يسر على معسر يسر اللّٰه عليه في الدنيا والآخرة ))."],"takhrij":"صحيح: رواه مسلم (٢٦٩٩).","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2699).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever relieves a believer of a hardship from the hardships of this world, Allah will relieve him of a hardship from the hardships of the Day of Resurrection. And whoever makes matters easy for one in hardship, Allah will make matters easy for him in this world and the Hereafter.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2699}]},{"num":5626,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( من أنظر معسرا أو وضع له أظله اللّٰه في ظل عرشه يوم القيامة ))."],"takhrij":"صحيح: رواه الترمذي (١٣٠٦)، وأحمد (٨٧١١). وقال الترمذي: “حديث حسن صحيح”.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1306) and Ahmad (8711). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “Whoever grants respite to one in hardship, or reduces what he owes, Allah will shade him under the shade of His Throne on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1306},{"key":"ahmad","label":"مسند الإمام أحمد","number":8711,"n":8711}]},{"num":5627,"demo":false,"sanad":"","matn":["عن حذيفة بن اليمان قال: قال رسول اللّٰه ﷺ: (( تلقت الملائكة روح رجل ممن كان قبلكم، فقالوا: أعملت من الخير شيئا؟ قال: لا. قالوا: تذكر. قال: كنت أداين الناس، فآمر فتياني أن ينظروا المعسر، ويتجوزوا عن الموسر. قال: قال اللّٰه عز وجل: تجوزوا عنه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٧٧)، ومسلم (١٥٦٠)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2077) and Muslim (1560). The wording is Muslim’s.","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Hudhayfah ibn al-Yaman said: The Messenger of Allah ﷺ said: “The angels received the soul of a man from those before you and said: ‘Did you do any good?’ He said: ‘No.’ They said: ‘Remember.’ He said: ‘I used to deal with people in debt, and I would order my young servants to give respite to the one in hardship and to be lenient with the one who had means.’ Allah the Mighty and Majestic said: ‘Overlook him.’”"]},"buhuth":{"ar":["وقوله: (( يتجوزوا )) من التجاوز، والتجوز معناه المسامحة في الاقتضاء والاستيفاء، وقبول ما فيه نقص."],"en":["The phrase “be lenient” means to show forbearance in collecting and settling the debt, and to accept a lesser or easier return."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2077},{"key":"muslim","label":"مسلم","number":1560}]},{"num":5628,"demo":false,"sanad":"","matn":["عن أبي مسعود قال: قال رسول اللّٰه ﷺ: (( حوسب رجل ممن كان قبلكم، فلم يوجد له من الخير شيء إلا أنه كان يخالط الناس، وكان موسرا، فكان يأمر غلمانه أن يتجاوزوا عن المعسر. قال: قال اللّٰه عز وجل: نحن أحق بذلك منه، تجاوزوا عنه ))."],"takhrij":"صحيح: رواه مسلم (٣٠ :١٥٦١).","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1561:30).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Masud said: The Messenger of Allah ﷺ said: “A man from those before you was brought to account, and no good was found for him except that he used to mix with people and was wealthy, and he would order his servants to overlook the debtor in hardship. Allah the Mighty and Majestic said: ‘We are more deserving of that than he was. Overlook him.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":30}]},{"num":5629,"demo":false,"sanad":"","matn":["عن أبي اليسر قال: قال رسول اللّٰه ﷺ: (( من أنظر معسرا أو وضع عنه أظله اللّٰه في ظله ))."],"takhrij":"صحيح: رواه مسلم (٣٠٠٦).","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3006).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu al-Yusr said: The Messenger of Allah ﷺ said: “Whoever gives respite to one in hardship, or remits part of what he owes, Allah will shade him in His shade.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":3006}]},{"num":5630,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن أبي قتادة أن أبا قتادة طلب غريما له، فتوارى عنه، ثم وجده، فقال: إني معسر. فقال: آلله؟ قال: آلله. قال: فإني سمعت رسول اللّٰه ﷺ يقول: (( من سره أن ينجيه اللّٰه من كرب يوم القيامة فلينفس عن معسر أو يضع عنه ))."],"takhrij":"صحيح: رواه مسلم (١٥٦٣).","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1563).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Abi Qatadah narrated that Abu Qatadah was seeking a debtor of his, but the man hid from him. Then he found him, and the man said: “I am in hardship.” He said: “By Allah?” He said: “By Allah.” He said: I heard the Messenger of Allah ﷺ say: “Whoever would be pleased that Allah saves him from the distress of the Day of Resurrection, let him give respite to one in hardship or waive part of it for him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1563}]},{"num":5631,"demo":false,"sanad":"","matn":["عن أبي قتادة قال: سمعت رسول اللّٰه ﷺ يقول: (( من نفس عن غريمه أو محا عنه كان في ظل العرش يوم القيامة ))."],"takhrij":"صحيح: رواه أحمد (٢٢٥٥٩)، والدارمي (٢٦٣١)، والبغوي في شرح السنة (٢١٤٣).","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (22559), al-Darimi (2631), and al-Baghawi in Sharh al-Sunnah (2143).","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Abu Qatadah said: I heard the Messenger of Allah ﷺ say: “Whoever gives relief to his debtor, or wipes away part of the debt for him, will be under the shade of the Throne on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"البغوی/شرح_السنہ","label":"البغوي في شرح السنة","number":2143},{"key":"ahmad","label":"مسند الإمام أحمد","number":22559,"n":22559},{"key":"darimi","label":"سنن الدارمي","number":2509,"n":2509},{"key":"sharhsunna","label":"شرح السنة للبغوي","number":2143,"n":2144}]},{"num":5632,"demo":false,"sanad":"","matn":["عن بريدة بن الحصيب قال: سمعت رسول اللّٰه ﷺ يقول: (( من أنظر معسرا فله كل يوم مثله صدقة )). قال: ثم سمعته يقول: (( من أنظر معسرا فله بكل يوم مثليه صدقة )). قلت: سمعتك يا رسول اللّٰه تقول: (( من أنظر معسرا فله بكل يوم مثله صدقة )). ثم سمعتك تقول: (( من أنظر معسرا فله بكل يوم مثليه صدقة )). قال: (( له بكل يوم صدقة قبل أن يحل الدين، فإذا حل الدين فأنظره فله بكل يوم مثليه صدقة ))."],"takhrij":"صحيح: رواه أحمد (٢٣٠٤٦) والحاكم (٢٩/٢)، واللفظ لأحمد.","grade":"صحيح","chapter_ar":"باب فضل إنظار المعسر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23046) and al-Hakim (2/29). The wording is Ahmad’s.","chapter_en":"The virtue of giving respite to one in hardship","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: I heard the Messenger of Allah ﷺ say: “Whoever gives respite to one in hardship will have the equivalent of it in charity each day.” Then I heard him say: “Whoever gives respite to one in hardship will have double its equivalent in charity each day.” I said: “I heard you, O Messenger of Allah ﷺ, say: ‘Whoever gives respite to one in hardship will have the equivalent of it in charity each day,’ then I heard you say: ‘Whoever gives respite to one in hardship will have double its equivalent in charity each day.’” He said: “He has charity for each day before the debt becomes due, and when the debt becomes due and he still grants respite, then he has double its equivalent in charity for each day.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":29},{"key":"ahmad","label":"مسند الإمام أحمد","number":23046,"n":23046}]},{"num":5633,"demo":false,"sanad":"","matn":["عن كعب بن مالك أنه تقاضى ابن أبي حَدرد دينا كان له عليه في المسجد، فارتفعت أصواتهما، حتى سمعها رسول اللّٰه ﷺ - وهو في بيته -، فخرج إليهما حتى كشف سجف حجرته، فنادى: (( يا كعب )). قال: لبيك يا رسول الله. قال: (( ضع من دينك هذا )). وأومأ إليه أي الشطر. قال: لقد فعلت يا رسول الله. قال: (( قم فاقضه ))."],"takhrij":"متفق عليه: رواه البخاري (٤٥٧)، ومسلم (١٥٥٨).","grade":"متفق عليه","chapter_ar":"باب استحباب الوضع من الدَّين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (457) and Muslim (1558).","chapter_en":"The recommendation of reducing a debt","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["Kab ibn Malik was demanding from Ibn Abi Hadrad a debt owed to him in the mosque, and their voices rose until the Messenger of Allah ﷺ heard them while he was in his house. He came out to them and lifted the curtain of his room, then called out: “O Kab.” He said: “At your service, O Messenger of Allah ﷺ.” He said: “Reduce some of your debt,” and he indicated half of it. Kab said: “I have done so, O Messenger of Allah ﷺ.” He said: “Then stand and pay him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":457},{"key":"muslim","label":"مسلم","number":1558}]},{"num":5634,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال:","أصيب رجل في عهد رسول الله ﷺ في ثمار ابتاعها، فكثر دينه، فقال رسول الله ﷺ:","«تَصَدَّقُوا عَلَيْهِ».","فتصدق الناس عليه، فلم يبلغ ذلك وفاء دينه.","فقال رسول الله ﷺ لغرمائه:","«خُذُوا مَا وَجَدْتُمْ، وَلَيْسَ لَكُمْ إِلَّا ذَلِكَ»."],"takhrij":"صحيح: رواه مسلم (١٥٥٦).","grade":"صحيح","chapter_ar":"باب قسمة مال المفلس بين الغرماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1556).","chapter_en":"Dividing the wealth of the bankrupt among the creditors","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported:","A man during the lifetime of the Messenger of Allah ﷺ suffered a loss in fruits that he had purchased, and his debts became numerous.","The Messenger of Allah ﷺ said:","“Give charity to him.”","The people gave charity to him, but what they gave was not enough to discharge his debt fully.","The Messenger of Allah ﷺ then said to his creditors:","“Take whatever you find, and you are entitled to nothing beyond that.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1556}]},{"num":5635,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( من أدرك ماله بعينه عند رجل - أو إنسان - قد أفلس فهو أحق به من غيره ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٠٢)، ومسلم (٢٢ :١٥٥٩).","grade":"متفق عليه","chapter_ar":"باب من وجد ماله بعينه عند مفلس فهو أحق به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2402) and Muslim (1559:22).","chapter_en":"Whoever finds his property itself with a bankrupt person has more right to it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever finds his property itself with a man — or a person — who has become bankrupt, he has more right to it than anyone else.”"]},"buhuth":{"ar":["ورواه مسلم (٢٤) من وجه آخر بلفظ: (( إذا أفلس الرجل فوجد الرجل متاعه بعينه فهو أحق به )). وفي رواية أخرى: (( فهو أحق به من الغرماء ))."],"en":["Muslim also narrated it by another route with the wording: “If a man becomes bankrupt and another man finds his goods themselves, then he has more right to them.” In another wording: “then he has more right to it than the creditors.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2402},{"key":"muslim","label":"مسلم","number":22}]},{"num":5636,"demo":false,"sanad":"","matn":["عن سمرة بن جندب قال: قال رسول اللّٰه ﷺ: (( من وجد عين ماله عند رجل فهو أحق به ))."],"takhrij":"صحيح: رواه أبو داود (٣٥٣١)، وفي المراسيل (١٨١)، والنسائي (٤٦٨١)، وأحمد (٢٠١٤٨).","grade":"صحيح","chapter_ar":"باب ما جاء في الرجل يجد ماله المسروق أو المفقود عند رجل فهو أحق به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3531), in al-Marasil (181), al-Nasai (4681), and Ahmad (20148).","chapter_en":"What has been reported regarding a man finding his stolen or lost property with another man; he is more entitled to it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “Whoever finds the very property of his own with a man is more entitled to it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3531},{"key":"وفی_المراسیل","label":"وفي المراسيل","number":181},{"key":"nasai","label":"النسائي","number":4681},{"key":"ahmad","label":"مسند الإمام أحمد","number":20148,"n":20148}]},{"num":5637,"demo":false,"sanad":"","matn":["عن أسيد بن ظهير الأنصاري أنه كان عاملا على اليمامة، وأن مروان كتب إليه أن معاوية كتب إلي: أيما رجل سرق منه سرقة فهو أحق بها حيث وجدها. قال: وكتب بذلك مروان إلي، فكتبت إلى مروان: أن النبي ﷺ قضى بأنه إذا كان الذي ابتاعها من الذي سرقها غير متهم يخير سيدها، فإن شاء أخذ الذي سرقت منه بثمنه، وإن شاء اتبع سارقه. ثم قضى بذلك بعد أبو بكر وعمر وعثمان. قال: فبعث مروان بكتابي إلى معاوية. قال: فكتب معاوية إلى مروان: إنك لست أنت ولا أسيد بن ظهير بقاضيين علي، ولكني أقضي فيما وليت عليكما، فأنفذ لما أمرتك به. فبعث مروان إلي كتاب معاوية، فقلت: لا أقضي به ما وليت، يعني بقول معاوية."],"takhrij":"صحيح: أخرجه عبد الرزاق (١٧٩٨٦ ،١٨٨٢٩)، وأبو داود في المراسيل (١٨٠)، والنسائي (٤٦٨٠).","grade":"صحيح","chapter_ar":"باب ما جاء في الرجل يجد ماله المسروق أو المفقود عند رجل فهو أحق به","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Related by Abd al-Razzaq (17986, 18829), Abu Dawud in al-Marasil (180), and al-Nasai (4680).","chapter_en":"What has been reported regarding a man finding his stolen or lost property with another man; he is more entitled to it","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Usayd ibn Zuhayr al-Ansari was an official over al-Yamamah, and Marwan wrote to him that Muawiyah had written to him: Any man from whom something was stolen is more entitled to it wherever he finds it. He said: Marwan wrote that to me, so I wrote back to Marwan that the Prophet ﷺ had judged that if the one who bought it from the thief was not accused of wrongdoing, then its owner is given a choice: if he wishes, he takes back what was stolen from him and pays its price, and if he wishes, he may pursue the thief. Then Abu Bakr, Umar, and Uthman also judged by that. He said: Marwan sent my letter to Muawiyah. Muawiyah then wrote to Marwan: Neither you nor Usayd ibn Zuhayr are to judge over me; rather I judge in what I have authority over you, so carry out what I ordered you. Marwan sent me Muawiyah’s letter, and I said: I will not judge by it while I remain in authority — meaning by Muawiyah’s opinion."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":17986},{"key":"abudawud/المراسیل","label":"أبو داود في المراسيل","number":180},{"key":"nasai","label":"النسائي","number":4680},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":20031,"n":20141}]},{"num":5638,"demo":false,"sanad":"","matn":["عن الشريد بن سويد الثقفي قال: قال رسول اللّٰه ﷺ: (( لَيُّ الواجدِ يُحِلُّ عِرضَه وعقوبته ))."],"takhrij":"حسن: رواه أبو داود (٣٦٢٨)، والنسائي (٤٦٩٠ ،٤٦٨٩)، وابن ماجه (٢٤٢٧)، وأحمد (١٧٩٤٦).","grade":"حسن","chapter_ar":"باب الحبس في الدَّين والملازمة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3628), al-Nasai (4689, 4690), Ibn Majah (2427), and Ahmad (17946).","chapter_en":"Imprisonment for debt and holding the debtor to account","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":19,"content":{"translation":{"en":["Al-Sharid ibn Suwayd al-Thaqafi said: The Messenger of Allah ﷺ said: “The delay of one who has means makes his honor lawful to speak against and makes punishment lawful.”"]},"buhuth":{"ar":["وقوله: (( ليُّ الواجد )) بفتح اللام وتشديد الياء: التأخر. والواجد: القادر على أداء ما عليه من الدين.","وقوله: (( عرضه )) أي شكايته. وقوله: (( وعقوبته )) سجنه. قاله علي الطنافسي شيخ ابن ماجه."],"en":["The phrase “delay of one who has means” means postponement by a person able to repay his debt.","“His honor” means: complaint against him.","“And his punishment” means: imprisonment. This was explained by Ali al-Tanafisi, the teacher of Ibn Majah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3628},{"key":"nasai","label":"النسائي","number":4690},{"key":"ibnmajah","label":"ابن ماجه","number":2427},{"key":"ahmad","label":"مسند الإمام أحمد","number":17946,"n":17946}]},{"num":5639,"demo":false,"sanad":"","matn":["عن ابن أذنان قال: أسلفت علقمة ألفي درهم، فلما خرج عطاؤه قلت له: اقضني. قال: أخّرني إلى قابل، فأبيت عليه فأخذتها. قال: فأتيته بعدُ قال: برحتَ بي وقد منعتني. فقلت: نعم، هو عملك. قال: وما شأني؟ قلت: إنك حدثتني عن ابن مسعود أن النبي ﷺ قال: (( إن السلف يجري مجرى شطر الصدقة )). قال: نعم، فهو كذاك. قال: فخذ الآن."],"takhrij":"حسن: رواه أحمد (٣٩١١) وأبو يعلى (٥٣٦٦)، وابن ماجه (٢٤٣٠).","grade":"حسن","chapter_ar":"باب ما جاء في الدَّين وإن أجره كأجر الصدقة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (3911), Abu Ya‘la (5366), and Ibn Majah (2430).","chapter_en":"What has been reported regarding lending and that its reward is like the reward of charity","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الاستقراض والتفليس","group_en":"Collected chapters on what has been reported regarding borrowing and insolvency","part_no":17,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["Ibn Adhnan said: I lent Alqamah two thousand dirhams. When his stipend came out, I said to him: “Pay me.” He said: “Delay me until next year.” I insisted and took it. Later he said to me: “You pressed me hard and withheld ease from me.” I said: “Yes, that was your own doing.” He said: “What do you mean?” I said: “You narrated to me from Ibn Masud that the Prophet ﷺ said: ‘A loan runs in place of half of charity.’” He said: “Yes, that is so.” Then he said: “Take it now.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":5366},{"key":"ibnmajah","label":"ابن ماجه","number":2430},{"key":"ahmad","label":"مسند الإمام أحمد","number":3911,"n":3911},{"key":"sh12520","label":"مسند أبي يعلى","number":5366,"n":5371}]},{"num":5640,"demo":false,"sanad":"","matn":["عن ابن عمر قال: عُرضتُ على النبي ﷺ يوم أُحد وأنا ابن أربع عشرة سنة فلم يجزني، وعرضت عليه يوم الخندق وأنا ابن خمس عشرة سنة فأجازني."],"takhrij":"متفق عليه: رواه البخاري (٢٦٦٤)، ومسلم (١٨٦٨).","grade":"متفق عليه","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2664) and Muslim (1868).","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Ibn Umar said: I was presented to the Prophet ﷺ on the Day of Uhud when I was fourteen years old, and he did not permit me. Then I was presented to him on the Day of al-Khandaq when I was fifteen years old, and he permitted me."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2664},{"key":"muslim","label":"مسلم","number":1868}]},{"num":5641,"demo":false,"sanad":"","matn":["عن عطية القرظي قال: عُرضنا على النبي ﷺ يوم قريظة، فكان من أنبت قتل، ومن لم ينبت خُلِّي سبيله، فكنت فيمن لم ينبت، فخُلِّي سبيلي."],"takhrij":"صحيح: رواه أبو داود (٤٤٠٥)، والترمذي (١٥٨٤)، والنسائي (٤٩٨١)، وابن ماجه (٢٥٤١)، وأحمد (١٨٧٧٦). وقال الترمذي: “حسن صحيح”.","grade":"صحيح","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4405), al-Tirmidhi (1584), al-Nasai (4981), Ibn Majah (2541), and Ahmad (18776). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Atiyyah al-Qurazi said: We were presented to the Prophet ﷺ on the Day of Qurayzah. Those who had grown pubic hair were killed, and those who had not were let go. I was among those who had not grown it, so my way was left open."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4405},{"key":"tirmidhi","label":"الترمذي","number":1584},{"key":"nasai","label":"النسائي","number":4981},{"key":"ibnmajah","label":"ابن ماجه","number":2541},{"key":"ahmad","label":"مسند الإمام أحمد","number":18776,"n":18776}]},{"num":5642,"demo":false,"sanad":"","matn":["عن سمرة بن جندب قال: قال رسول اللّٰه ﷺ: (( اقتلوا شيوخ المشركين واستبقوا شرخهم ))."],"takhrij":"حسن: رواه أبو داود (٢٦٧٠) وسعيد بن منصور في سننه (٢٦٢٤).","grade":"حسن","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2670) and Sa‘id ibn Mansur in his Sunan (2624).","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Samurah ibn Jundub said: The Messenger of Allah ﷺ said: “Kill the elder polytheists and spare their young.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2670},{"key":"سعید_بن_منصور/سننہ","label":"سعيد بن منصور في سننه","number":2624},{"key":"sh13122","label":"سنن سعيد بن منصور","number":2624,"n":2587}]},{"num":5643,"demo":false,"sanad":"","matn":["عن عائشة أم المؤمنين، عن النبي ﷺ قال: (( لا يقبل اللّٰه صلاة حائض إلا بخمار ))."],"takhrij":"صحيح: رواه أبو داود (٦٤١)، والترمذي (٣٧٧)، وابن ماجه (٦٥٥)، وصححه ابن خزيمة (٧٧٥).","grade":"صحيح","chapter_ar":"باب علامات البلوغ في الرجال والنساء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (641), al-Tirmidhi (377), Ibn Majah (655), and authenticated by Ibn Khuzaymah (775).","chapter_en":"The signs of maturity in men and women","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Aishah, the Mother of the Believers, narrated from the Prophet ﷺ that he said: “Allah does not accept the prayer of a mature woman except with a head covering.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":641},{"key":"tirmidhi","label":"الترمذي","number":377},{"key":"ibnmajah","label":"ابن ماجه","number":655},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":775}]},{"num":5644,"demo":false,"sanad":"","matn":["عن عوف بن مالك بن الطفيل - وهو ابن الحارث، وهو ابن أخت عائشة زوج النبي ﷺ لأمها - أن عائشة حدَّثت أن عبد الله بن الزبير قال في بيع أو عطاء أعطته عائشة: والله لتنتهينَّ عائشة أو لأحجرنَّ عليها. فقالت: أهو قال هذا؟ قالوا: نعم. قالت: هو لله عليَّ نذر أن لا أكلم ابن الزبير أبداً. فاستشفع ابن الزبير إليها حين طالت الهجرة، فقالت: لا والله، لا أشفع فيه أبداً، ولا أتحنث إلى نذري. فلما طال ذلك على ابن الزبير كلَّم المسور بن مخرمة وعبد الرحمن بن الأسود بن عبد يغوث - وهما من بني زهرة -، وقال لهما: أنشدكما بالله لما أدخلتماني على عائشة؛ فإنها لا يحل لها أن تنذر قطيعتي. فأقبل به المسور وعبد الرحمن مشتملين بأرديتهما حتى استأذنا على عائشة، فقالا: السلام عليك ورحمة الله وبركاته، أندخل؟ قالت عائشة: ادخلوا. قالوا: كلنا؟ قالت: نعم، ادخلوا كلكم، ولا تعلم أن معهما ابن الزبير. فلما دخلوا دخل ابن الزبير الحجاب، فاعتنق عائشة، وطفق يناشدها، ويبكي، وطفق المسور وعبد الرحمن يناشدانها إلا ما كلمته، وقبلت منه، ويقولان: إن النبي ﷺ نهى عما قد علمتِ من الهجرة، فإنه لا يحل لمسلم أن يهجر أخاه فوق ثلاث ليال. فلما أكثروا على عائشة من التذكرة والتحريج طفقت تذكرهما، وتبكي، وتقول: إني نذرت، والنذر شديد. فلم يزالا بها حتى كلمت ابن الزبير، وأعتقت في نذرها ذلك أربعين رقبة، وكانت تذكر نذرها بعد ذلك، فتبكي حتى تبل دموعها خمارها."],"takhrij":"صحيح: رواه البخاري (٦٠٧٣، ٦٠٧٤، ٦٠٧٥).","grade":"صحيح","chapter_ar":"باب الحجر على البالغ إذا كان سفيها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6073, 6074, 6075).","chapter_en":"Restricting an adult if he is foolish in financial conduct","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Awf ibn Malik ibn al-Tufayl — who was the son of al-Harith, and the son of the sister of Aishah, the wife of the Prophet ﷺ through her mother — narrated that Aishah said that Abdullah ibn al-Zubayr remarked concerning a sale or gift that Aishah had given: “By Allah, Aishah must stop, or I will place restrictions on her.” She said: “Did he really say this?” They said: Yes. She said: “Then for Allah upon me is a vow that I will never speak to Ibn al-Zubayr again.” Ibn al-Zubayr later sought intercession with her after the estrangement had become long, but she said: “No, by Allah, I will never intercede for him, nor will I break my vow.” When that became difficult for Ibn al-Zubayr, he asked al-Miswar ibn Makhramah and Abd al-Rahman ibn al-Aswad ibn Abd Yaghuth — both from Banu Zuhrah — and said to them: “I ask you by Allah to get me admitted to Aishah, for it is not lawful for her to vow to cut me off.” So al-Miswar and Abd al-Rahman came with him wrapped in their cloaks until they sought permission from Aishah. They said: “Peace be upon you, and the mercy of Allah and His blessings. May we enter?” Aishah said: “Enter.” They said: “All of us?” She said: “Yes, all of you may enter,” not realizing that Ibn al-Zubayr was with them. When they entered, Ibn al-Zubayr slipped behind the curtain, embraced Aishah, and began pleading with her and weeping. Al-Miswar and Abd al-Rahman also pleaded with her to speak to him and accept from him, saying: “The Prophet ﷺ forbade the kind of estrangement you already know. It is not lawful for a Muslim to abandon his brother for more than three nights.” When they repeatedly reminded and pressed her, she began recalling that and weeping, saying: “I made a vow, and a vow is serious.” They continued until she spoke to Ibn al-Zubayr, and she freed forty slaves as expiation for that vow. After that, whenever she remembered her vow, she would weep until her tears soaked her head covering."]},"buhuth":{"ar":["وهذا الحجر على عائشة لم يكن في محله؛ لأنها لم تكن سفيهة؛ فإن تصرفها كان صحيحاً، ولذا لم ترض بحجر ابن الزبير، بل شددت عليه بأن لا تكلمه أبداً."],"en":["This proposed restriction against Aishah was not appropriate, because she was not foolish in judgment. Her financial conduct was sound, and that is why she did not accept Ibn al-Zubayr’s attempt to restrict her, but instead became firm in refusing to speak to him."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَلَا تُؤْتُوا السُّفَهَاءَ أَمْوَالَكُمُ الَّتِي جَعَلَ اللَّهُ لَكُمْ قِيَامًا ) [سورة النساء: ٥].","وقال تعالى: ( فَإِن كَانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهًا أَوْ ضَعِيفًا ) الآية [سورة البقرة: ٢٨٢].","فأثبت الولاية على السفيه، كما أثبتها على الضعيف.","ومعنى السفيه راجع إلى الكبير البالغ، ومعنى الضعيف راجع إلى الصغير.","وقال سبحانه وتعالى: ( وَابْتَلُوا الْيَتَامَى حَتَّىٰ إِذَا بَلَغُوا النِّكَاحَ فَإِنْ آنَسْتُم مِّنْهُمْ رُشْدًا فَادْفَعُوا إِلَيْهِمْ أَمْوَالَهُمْ ) [سورة النساء: ٦]. فشرط في دفع المال إليهم شيئين: الاحتلام والرشد.","والحكم إذا كان وجوبه معلقا بشيئين لم يجب إلا بورودهما معا.","قاله الخطابي في معالمه (٤/١٥٢-١٥٣).","وهذا الحجر على عائشة لم يكن في محله؛ لأنها لم تكن سفيهة؛ فإن تصرفها كان صحيحاً، ولذا لم ترض بحجر ابن الزبير، بل شددت عليه بأن لا تكلمه أبداً."],"en":["Allah the Exalted said: “Do not give the foolish your wealth which Allah has made a means of support for you.” [al-Nisa: 5]","And He said: “If the one upon whom the obligation is due is foolish or weak…” [al-Baqarah: 282]","So He established guardianship over the foolish person just as He established it over the weak one.","The meaning of “foolish” here refers to the adult of unsound financial judgment, while the meaning of “weak” refers to the minor.","And He, Glorified and Exalted, said: “Test the orphans until they reach marriageable age; then if you perceive in them sound judgment, hand over to them their wealth.” [al-Nisa: 6] Thus He made two conditions for handing wealth over to them: puberty and sound judgment.","A ruling whose obligation is tied to two conditions does not become due unless both are present together.","This was stated by al-Khattabi in Ma‘alim al-Sunan (4/152–153).","This proposed restriction against Aishah was not appropriate, because she was not foolish in judgment. Her financial conduct was sound, and that is why she did not accept Ibn al-Zubayr’s attempt to restrict her, but instead became firm in refusing to speak to him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6073}]},{"num":5645,"demo":false,"sanad":"","matn":["عن حنظلة يقول: قال رسول اللّٰه ﷺ: (( لا يُتْمَ بعد احتلام، ولا يُتْمَ على جارية إذا هي حاضت ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٤/١٦).","grade":"حسن","chapter_ar":"باب متى ينقطع اليتم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (4/16).","chapter_en":"When orphanhood ends","part_en":"The Book of Sales","group_ar":"جموع ما جاء في الحجر على الصغير والبالغين في السفه","group_en":"Collection of reports regarding restriction over minors and over adults due to foolishness","part_no":17,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Hanzalah said: The Messenger of Allah ﷺ said: “There is no orphanhood after puberty, and there is no orphanhood for a girl once she menstruates.”"]},"buhuth":{"ar":["قال الخطابي: ظاهر هذا الحديث يوجب انقطاع أحكام اليتم عنه بالاحتلام، وحدوث أحكام البالغين له، فيكون للمحتلم أن يبيع ويشتري ويتصرف في ماله ويعقد النكاح لنفسه، وإن كانت امرأة فلا تزوج إلا بإذنها. ولكن المحتلم إذا لم يكن رشيداً لم يفك الحجر عنه، وقد يحظر الشيء بسببين، فلا يرتفع بارتفاع أحدهما مع بقاء السبب الآخر، وقد أمر اللّٰه تعالى بالحجر على السفيه، فقال: ( وَلَا تُؤْتُوا السُّفَهَاءَ أَمْوَالَكُمُ الَّتِي جَعَلَ اللَّهُ لَكُمْ قِيَامًا ) [سورة النساء: ٥]."],"en":["Al-Khattabi said: The apparent meaning of this hadith indicates that the rulings of orphanhood end upon puberty, and the rulings of adulthood begin. Thus, a person who has reached puberty may buy, sell, manage his wealth, and contract marriage for himself; and if it is a woman, she is not married off except with her permission. However, if the person who has reached puberty is not sound in judgment, then the restriction over him is not lifted. A thing may be restricted for two reasons, and it does not become unrestricted just because one reason is gone while the other remains. Allah the Exalted commanded restriction over the foolish person, saying: “Do not give the foolish your wealth which Allah has made a means of support for you.” [al-Nisa: 5]"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":4}]},{"num":5646,"demo":false,"sanad":"","matn":["عن عائشة أن النبي ﷺ اشترى من يهودي طعاماً إلى أجل، ورهنه درعه."],"takhrij":"متفق عليه: رواه البخاري (٢٥٠٩)، ومسلم (١٢٦ :١٦٠٣).","grade":"متفق عليه","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2509) and Muslim (1603:126).","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Aishah narrated that the Prophet ﷺ bought food from a Jew on deferred payment and pledged his armor to him."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَإِنْ كُنْتُمْ عَلَى سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَقْبُوضَةٌ ) [سورة البقرة: ٢٨٣]."],"en":["Allah the Exalted said: “And if you are on a journey and cannot find a scribe, then let there be a pledge taken in possession.” [al-Baqarah: 283]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2509},{"key":"muslim","label":"مسلم","number":126}]},{"num":5647,"demo":false,"sanad":"","matn":["عن أنس قال: ولقد رهن رسول اللّٰه ﷺ درعه بشعير، ومشيت إلى النبي ﷺ بخبز شعير وإهالة سنخة، ولقد سمعته يقول: (( ما أصبح لآل محمد ﷺ إلا صاع، ولا أمسى، وإنهم لتسعة أبيات ))."],"takhrij":"صحيح: رواه البخاري (٢٥٠٨).","grade":"صحيح","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2508).","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ pledged his armor for barley, and I went to the Prophet ﷺ with barley bread and stale melted fat. I heard him say: “The family of Muhammad ﷺ does not have as much as one sa of food in the morning nor in the evening, though they are nine households.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2508}]},{"num":5648,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس أن رسول اللّٰه ﷺ مات ودرعه رهن عند يهودي بثلاثين صاعاً من شعير، أخذها رزقاً لعياله."],"takhrij":"صحيح: رواه الترمذي (١٢١٤)، والنسائي (٤٦٥١)، وأحمد (٢١٠٩، ٣٤٠٩)، وقال: “حسن صحيح”.","grade":"صحيح","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1214), al-Nasai (4651), and Ahmad (2109, 3409). He said: “Hasan Sahih.”","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Abbas narrated that the Messenger of Allah ﷺ died while his armor was pledged with a Jew for thirty sa of barley, which he had taken as provision for his family."]},"buhuth":{"ar":["وزاد أحمد في أول الحديث: أن النبي ﷺ التفت إلى أحد، فقال: (( والذي نفس محمد بيده، ما يسرني أن أحداً يحول لآل محمد ذهباً أنفقه في سبيل الله، أموت يوم أموت أدع منه دينارين إلا دينارين أعدهما لدين إن كان )). فمات وما ترك ديناراً ولا درهماً، ولا عبداً ولا وليدة، وترك درعه مرهونة عند يهودي … الحديث."],"en":["Ahmad added at the beginning of the hadith that the Prophet ﷺ looked toward Uhud and said: “By the One in whose hand is Muhammad’s soul, it would not please me that the family of Muhammad had gold equal to Uhud which I spent in the path of Allah, then on the day I die I would leave behind from it two dinars — except two dinars set aside for a debt, if there were one.” So he died leaving behind neither dinar nor dirham, nor a male slave nor a female slave, and he left his armor pledged with a Jew … the hadith."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1214},{"key":"nasai","label":"النسائي","number":4651},{"key":"ahmad","label":"مسند الإمام أحمد","number":2109,"n":2109}]},{"num":5649,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول اللّٰه ﷺ: (( من لكعب بن الأشرف؛ فإنه قد آذى الله ورسوله ﷺ؟ )) قال محمد بن مسلمة: أنا. فأتاه، فقال: أردنا أن تسلفنا وسقاً أو وسقين. فقال: ارهنوني نساءكم. قالوا: كيف نرهنك نساءنا وأنت أجمل العرب؟ قال: فارهنوني أبناءكم. قالوا: كيف نرهنك أبناءنا فيسب أحدهم، فيقال: رهن بوسق أو وسقين، هذا عار علينا، ولكنا نرهنك اللأمة. قال سفيان: يعني السلاح. فوعده أن يأتيه، فقتلوه، ثم أتوا النبي ﷺ، فأخبروه."],"takhrij":"متفق عليه: رواه البخاري (٢٥١٠)، ومسلم (١٨٠١)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب مشروعية الرهن وجوازه في السفر والحضر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2510) and Muslim (1801). The wording here is al-Bukhari’s.","chapter_en":"The legislation of pledges and their permissibility in travel and residence","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Who will deal with Kab ibn al-Ashraf, for he has harmed Allah and His Messenger ﷺ?” Muhammad ibn Maslamah said: I will. He went to him and said: “We want you to lend us one or two wasqs.” He said: “Pledge your women to me.” They said: “How can we pledge our women to you when you are the most handsome of the Arabs?” He said: “Then pledge your sons to me.” They said: “How can we pledge our sons to you, and one of them would be insulted and it would be said that he was pledged for one or two wasqs? That would be a disgrace for us. But we can pledge you the la’mah.” Sufyan said: meaning weapons. So he promised to come to him, then they killed him, and afterward they came to the Prophet ﷺ and informed him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2510},{"key":"muslim","label":"مسلم","number":1801}]},{"num":5650,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( الظهر يركب بنفقته إذا كان مرهوناً، ولبن الدر يشرب بنفقته إذا كان مرهوناً، وعلى الذي يركب ويشرب النفقة ))."],"takhrij":"صحيح: رواه البخاري (٢٥١٢).","grade":"صحيح","chapter_ar":"باب أن المرتهن يركب، ويحلب، وعليه نفقته","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2512).","chapter_en":"The pledge-holder may ride and milk the pledged animal, and he must bear its maintenance","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A pledged riding animal may be ridden in return for its maintenance if it has been pledged, and the milk of a pledged milking animal may be drunk in return for its maintenance if it has been pledged, and the one who rides and drinks must bear the maintenance.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2512}]},{"num":5651,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( لا يُغلق الرهن، له غنمه، وعليه غرمه ))."],"takhrij":"حسن: رواه الدارقطني (٣/٣٤).","grade":"حسن","chapter_ar":"باب أن المرتهن لا يستحق الرهن إذا تأخر الراهن عن الوفاء بالدين الذي عليه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (3/34).","chapter_en":"The pledge-holder does not become owner of the pledge merely because the pledger delays repayment","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الرهن","group_en":"Collection of reports regarding pledges and collateral","part_no":17,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A pledge is not forfeited; its gain belongs to its owner, and its liability is upon him.”"]},"buhuth":{"ar":["وقوله: (( لا يُغلق الرهن )) معناه لا يستغلق بحيث لا يعود إلى الراهن، بل متى أدى الحق المرهون به عاد إلى الراهن.","وقوله: (( له غنمه )) أي الزوائد التي تحصل منه تكون للراهن.","وقوله: (( وعليه غرمه )) إذا هلك في يد المرتهن يكون من ضمان الراهن."],"en":["The phrase “a pledge is not forfeited” means that it does not become permanently closed off so that it can never return to the pledger. Rather, whenever the debt for which it was pledged is paid, it returns to the pledger.","“its gain belongs to its owner” means that any increase or benefit arising from it belongs to the pledger.","“its liability is upon him” means that if it perishes while in the hand of the pledge-holder, its loss remains upon the pledger."]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطني","number":3},{"key":"sh9771","label":"سنن الدارقطني","number":2923,"n":2931}]},{"num":5652,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أنه قال: بعث رسول اللّٰه ﷺ بعثاً قبل الساحل، فأمَّر عليهم أبا عبيدة بن الجراح، وهم ثلاثمائة. قال: وأنا فيهم. فخرجنا حتى إذا كنا ببعض الطريق فني الزاد، فأمر أبو عبيدة بأزواد ذلك الجيش، فجمع ذلك كله، فكان مزودي تمر. قال: فكان يقوتنا كل يوم قليلاً قليلاً حتى فني، فلم يكن يصيبنا إلا تمرة تمرة. فقلت: وما تغني تمرة؟ فقال: لقد وجدنا فقدها حين فنيت. قال: ثم انتهينا إلى البحر فإذا حوت مثل الظرب، فأكل منه ذلك الجيش ثماني عشرة ليلة، ثم أمر أبو عبيدة بضلعين من أضلاعه، فنصبا، ثم أمر براحلة فرحلت، ثم مرت تحتهما، فلم تصبهما."],"takhrij":"متفق عليه: رواه مالك (٢٤)، والبخاري (٢٤٨٣)، ومسلم (٢١ :١٩٣٥).","grade":"متفق عليه","chapter_ar":"باب الشركة في الطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (24), al-Bukhari (2483), and Muslim (1935:21).","chapter_en":"Partnership in food","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ sent an expedition toward the coast and appointed Abu Ubaydah ibn al-Jarrah over them, and they were three hundred men. I was among them. We set out until, at some point on the road, the provisions ran out. Abu Ubaydah ordered the provisions of that army to be gathered together, and all of it was collected; our provision consisted of dates. He would then give us a little each day until it was exhausted, until all we received was one date each. I said: “What good is one date?” He replied: “We truly realized its value once it was gone.” Then we reached the sea, and there was a huge fish like a hill. That army ate from it for eighteen nights. Then Abu Ubaydah ordered two of its ribs to be raised upright, then ordered a riding camel to be saddled, and it passed beneath them without touching them."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":24},{"key":"bukhari","label":"البخاري","number":2483},{"key":"muslim","label":"مسلم","number":21}]},{"num":5653,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري قال: قال النبي ﷺ: (( إن الأشعريين إذا أرملوا في الغزو، أو قل طعام عيالهم بالمدينة جمعوا ما كان عندهم في ثوب واحد، ثم اقتسموه بينهم في إناء واحد بالسوية، فهم مني، وأنا منهم ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٨٦)، ومسلم (٢٥٠٠).","grade":"متفق عليه","chapter_ar":"باب الشركة في الطعام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2486) and Muslim (2500).","chapter_en":"Partnership in food","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Abu Musa al-Ashari said: The Prophet ﷺ said: “When the Asharis become short of provisions during a campaign, or the food of their families in Madinah becomes scarce, they gather what they have into one cloth, then divide it equally among themselves in one vessel. They are from me, and I am from them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2486},{"key":"muslim","label":"مسلم","number":2500}]},{"num":5654,"demo":false,"sanad":"","matn":["عن جبلة قال: كنا بالمدينة، فأصابتنا سنة، فكان ابن الزبير يرزقنا التمر، وكان ابن عمر يمر بنا، فيقول: لا تقرنوا؛ فإن النبي ﷺ نهى عن القِران إلا أن يستأذن الرجل منكم أخاه."],"takhrij":"متفق عليه: رواه البخاري (٢٤٨٩، ٢٤٩٠)، ومسلم (١٥٠ :٢٠٤٥)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب لا يأكل أحد تمرتين في لقمة إذا كان بين الشركاء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2489, 2490) and Muslim (2045:150). The wording here is al-Bukhari’s.","chapter_en":"No one should eat two dates in one mouthful when food is jointly shared","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Jabalah said: We were in Madinah when a time of hardship struck us, and Ibn al-Zubayr used to provide us with dates. Ibn Umar would pass by us and say: “Do not combine two together, for the Prophet ﷺ forbade combining two dates together unless a man seeks permission from his companions.”"]},"buhuth":{"ar":["ورواه البخاري (٢٤٨٩) من طريق آخر بلفظ: “نهى النبي ﷺ أن يقرن الرجل بين التمرتين جميعاً حتى يستأذن أصحابه”."],"en":["Al-Bukhari also narrated by another route: “The Prophet ﷺ forbade a man from combining two dates together until he seeks permission from his companions.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2489},{"key":"muslim","label":"مسلم","number":150}]},{"num":5655,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( من أعتق شركاً له في عبد، فكان له مال يبلغ ثمن العبد قُوِّم عليه قيمة العدل، فأعطى شركاءه حصصهم، وعتق عليه العبد، وإلا فقد عتق منه ما عتق ))."],"takhrij":"متفق عليه: رواه مالك (١)، والبخاري (٢٥٢٢)، ومسلم (١ :١٥٠١).","grade":"متفق عليه","chapter_ar":"باب الشركة في العبد المملوك، وكيف يقوم إذا أعتق بعض الشركاء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (2522), and Muslim (1501:1).","chapter_en":"Partnership in a slave, and how he is valued when one partner frees his share","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Ibn Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees a share of his in a slave, and he has enough wealth to cover the price of the slave, the slave is fairly valued against him, then he gives his partners their shares, and the slave is fully freed on his behalf. Otherwise, only the portion that he freed is freed.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":2522},{"key":"muslim","label":"مسلم","number":1}]},{"num":5656,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: (( من أعتق شِقصاً من مملوكه فعليه خلاصه في ماله، فإن لم يكن له مال قوِّم المملوك قيمة عدل، ثم استسعي غير مشقوق عليه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٩٢)، ومسلم (١٥٠٣).","grade":"متفق عليه","chapter_ar":"باب الشركة في العبد المملوك، وكيف يقوم إذا أعتق بعض الشركاء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2492) and Muslim (1503).","chapter_en":"Partnership in a slave, and how he is valued when one partner frees his share","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “Whoever frees a share of his slave must complete his emancipation from his own wealth. If he does not have wealth, then the slave is fairly valued and then made to earn the remainder without being overburdened.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2492},{"key":"muslim","label":"مسلم","number":1503}]},{"num":5657,"demo":false,"sanad":"","matn":["عن جابر قال: نحرنا مع رسول اللّٰه ﷺ عام الحديبية البدنة عن سبعة، والبقرة عن سبعة."],"takhrij":"صحيح: رواه مالك (٩)، ومسلم (٣٥٠ :١٣١٨).","grade":"صحيح","chapter_ar":"باب الاشتراك في الهدي في الحج","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (9) and Muslim (1318:350).","chapter_en":"Sharing in sacrificial animals during Hajj","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Jabir said: We sacrificed with the Messenger of Allah ﷺ in the year of al-Hudaybiyah: one camel for seven people, and one cow for seven people."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":9},{"key":"muslim","label":"مسلم","number":350}]},{"num":5658,"demo":false,"sanad":"","matn":["عن جابر قال: خرجنا مع رسول اللّٰه ﷺ مهلين بالحج، فأمرنا رسول اللّٰه ﷺ أن نشترك في الإبل والبقر، كل سبعة منا في بدنة."],"takhrij":"صحيح: رواه مسلم (٣٥١ :١٣١٨).","grade":"صحيح","chapter_ar":"باب الاشتراك في الهدي في الحج","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1318:351).","chapter_en":"Sharing in sacrificial animals during Hajj","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Jabir said: We went out with the Messenger of Allah ﷺ declaring the intention for Hajj, and the Messenger of Allah ﷺ ordered us to share in camels and cows, with every seven of us sharing in one camel."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":351}]},{"num":5659,"demo":false,"sanad":"","matn":["عن أنس بن مالك:","أن أبا بكر رضي الله عنه كتب له فريضة الصدقة التي فرض رسول الله ﷺ، قال:","«وَمَا كَانَ مِنْ خَلِيطَيْنِ فَإِنَّهُمَا يَتَرَاجَعَانِ بَيْنَهُمَا بِالسَّوِيَّةِ»."],"takhrij":"صحيح: رواه البخاري (٢٤٨٧).","grade":"صحيح","chapter_ar":"باب الشركة في الصدقة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2487).","chapter_en":"Partnership in zakah livestock","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik reported:","Abū Bakr, may Allah be pleased with him, wrote for him the ordinance of zakat prescribed by the Messenger of Allah ﷺ. It stated:","“Whatever belongs to two partners whose livestock are mixed together, they shall settle between themselves equally.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2487}]},{"num":5660,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: قال رسول اللّٰه ﷺ: (( من كان له شريك في ربعة أو نخل فليس له أن يبيع حتى يؤذن شريكه، فإن رضي أخذ، وإن كره ترك ))."],"takhrij":"صحيح: رواه مسلم (١٣٣ :١٦٠٨).","grade":"صحيح","chapter_ar":"باب الشركاء في الدور والأراضي وغيرها، وأنه لا يبيع أحد حتى يستأذن شركاءه إذا لم تقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1608:133).","chapter_en":"Partners in houses, lands, and other property, and that one should not sell until consulting the other partners when it has not been divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ said: “Whoever has a partner in a dwelling or in date-palms, it is not lawful for him to sell until he informs his partner. If the partner is pleased, he takes it, and if he dislikes it, he leaves it.”"]},"buhuth":{"ar":["ولفظ ابن جريج: (( قضى رسول اللّٰه ﷺ بالشفعة في كل شركة لم تقسم ربعة أو حائط، لا يحل له أن يبيع حتى يؤذن شريكه، فإن شاء أخذ، وإن شاء ترك، فإذا باع ولم يؤذنه فهو أحق به ))."],"en":["In the wording of Ibn Jurayj: “The Messenger of Allah ﷺ ruled with preemption in every undivided partnership in a house or a garden. It is not lawful for him to sell until he informs his partner. If he wishes, he takes it, and if he wishes, he leaves it. If he sells without informing him, then the partner has more right to it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":133}]},{"num":5661,"demo":false,"sanad":"","matn":["عن رويفع بن ثابت الأنصاري أنه غزا مع رسول اللّٰه ﷺ قال: وكان أحدنا يأخذ الناقة على النصف مما يغنم حتى إن لأحدنا القدح، وللآخر النصل والريش."],"takhrij":"حسن: رواه الإمام أحمد (١٦٩٩٤).","grade":"حسن","chapter_ar":"باب الشركة في الغنيمة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (16994).","chapter_en":"Partnership in war booty","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في الشركة","group_en":"Collection of reports regarding partnership","part_no":17,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Ruwayfi ibn Thabit al-Ansari said that he went on campaign with the Messenger of Allah ﷺ, and one of us would take a camel in exchange for half of what was taken as booty, so much so that one of us would have the wooden shaft while another would have the metal point and the feathers."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":16994},{"key":"ahmad","label":"مسند الإمام أحمد","number":16994,"n":16994}]},{"num":5662,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: سمعت رسول اللّٰه ﷺ يقول - وأهوى النعمان بإصبعيه إلى أذنيه -: (( إن الحلال بيّن، وإن الحرام بيّن، وبينهما مشتبهات لا يعلمهن كثير من الناس، فمن اتقى الشبهات استبرأ لدينه وعرضه، ومن وقع فى الشبهات وقع فى الحرام، كالراعي يرعى حول الحمى يوشك أن يرتع فيه. ألا وإن لكل ملك حمى، ألا وإن حمى اللّٰه محارمه، ألا وإن فى الجسد مضغة إذا صلحت صلح الجسد كله، وإذا فسدت فسد الجسد كله، ألا وهي القلب ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٥١)، ومسلم (١٥٩٩/١٠٧)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2051) and Muslim (1599/107). The wording is Muslim’s.","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Al-Nu‘man ibn Bashir said: I heard the Messenger of Allah ﷺ say — and al-Nu‘man pointed with his two fingers to his ears —: “The lawful is clear, and the unlawful is clear, and between them are doubtful matters that many people do not know. Whoever avoids the doubtful matters has protected his religion and his honor. Whoever falls into doubtful matters falls into the unlawful, like a shepherd grazing around a protected boundary, soon to graze within it. Indeed, every king has a protected boundary, and indeed the protected boundary of Allah is His prohibitions. Indeed, in the body there is a morsel of flesh: if it is sound, the whole body is sound; and if it is corrupt, the whole body is corrupt. Truly, it is the heart.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2051},{"key":"muslim","label":"مسلم","number":1599}]},{"num":5663,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول اللّٰه ﷺ قال: (( الحلال بيّن، والحرام بيّن، وبين ذلك شبهات، فمن أوقع بهن فهو قمين أن يأثم، ومن اجتنبهن فهو أوفر لدينه، كمرتع إلى جنب حمى أوشك أن يقع فيه، ولكل ملك حمى، وحمى اللّٰه الحرام ))."],"takhrij":"حسن: رواه الطبراني في الكبير (١٠/٤٠٤)، وابن عساكر في تاريخ دمشق (١/٧).","grade":"حسن","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (10/404) and Ibn Asakir in Tarikh Dimashq (1/7).","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas narrated that the Messenger of Allah ﷺ said: “The lawful is clear and the unlawful is clear, and between them are doubtful matters. Whoever falls into them is likely to sin, and whoever avoids them better protects his religion, like one grazing near a protected boundary, soon to fall into it. Every king has a protected boundary, and the protected boundary of Allah is what He has made unlawful.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":10},{"key":"ابن_عساکر/تاریخ_دمشق","label":"ابن عساكر في تاريخ دمشق","number":1}]},{"num":5664,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( ليأتين على الناس زمان لا يبالي المرء بما أخذ المال، أمن الحلال أم من الحرام؟ ))."],"takhrij":"صحيح: رواه البخاري (٢٠٨٣).","grade":"صحيح","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2083).","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he said: “A time will surely come upon the people when a man will not care how he acquires wealth, whether from lawful sources or unlawful ones.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2083}]},{"num":5665,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله:","أن رسول الله ﷺ وأصحابه مروا بامرأة، فذبحت لهم شاة، واتخذت لهم طعامًا.","فلما رجع قالت:","يا رسول الله، إنا اتخذنا لكم طعامًا، فادخلوا فكلوا.","فدخل رسول الله ﷺ وأصحابه، وكانوا لا يبدؤون حتى يبتدئ النبي ﷺ.","فأخذ النبي ﷺ لقمة فلم يستطع أن يسيغها، فقال النبي ﷺ:","«هَذِهِ شَاةٌ ذُبِحَتْ بِغَيْرِ إِذْنِ أَهْلِهَا».","فقالت المرأة:","يا نبي الله، إنا لا نحتشم من آل سعد بن معاذ، ولا يحتشمون منا، نأخذ منهم ويأخذون منا."],"takhrij":"صحيح: رواه أحمد (١٤٧٨٥)، والحاكم (٧٥٧٩).","grade":"صحيح","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (14785) and al-Ḥākim (7579).","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported:","The Messenger of Allah ﷺ and his Companions passed by a woman. She slaughtered a sheep for them and prepared food.","When they returned, she said:","“O Messenger of Allah ﷺ, we have prepared food for you, so come in and eat.”","The Messenger of Allah ﷺ and his Companions entered. They would not begin eating until the Prophet ﷺ began.","The Prophet ﷺ took a morsel but was unable to swallow it. He said:","“This sheep was slaughtered without the permission of its owners.”","The woman said:","“O Prophet of Allah, there is no formality between us and the family of Saʿd ibn Muʿādh, nor between them and us. We take from them, and they take from us.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":14785,"n":14785},{"key":"hakim","label":"المستدرك على الصحيحين","number":7579,"n":7583}]},{"num":5666,"demo":false,"sanad":"","matn":["عن رجلٍ من الأنصار أخبره قال: خرجنا مع رسول اللّٰه ﷺ في جنازة، فلما رجعنا لقينا داعي امرأة من قريش، فقال: يا رسول اللّٰه، إن فلانة تدعوك ومن معك إلى طعام. فانصرف ﷺ، وانصرفنا معه، فجلسنا مجالس الغلمان من آبائهم بين أيديهم، ثم جيء بالطعام، فوضع رسول اللّٰه ﷺ يده، ووضع القوم أيديهم، ففطن له القوم، وهو يلوك لقمته لا يجيزها، فرفعوا أيديهم، وغفلوا عنا، ثم ذكروا فأخذوا بأيدينا، فجعل الرجل يضرب اللقمة بيده حتى تسقط، ثم أمسكوا بأيدينا ينظرون ما يصنع رسول اللّٰه ﷺ، فلفظها فألقاها، فقال: (( أجد لحم شاة أُخذت بغير إذن أهلها )). فقامت المرأة فقالت: يا رسول اللّٰه، إنه كان في نفسي أن أجمعك ومن معك على طعام، فأرسلت إلى البقيع فلم أجد شاة تباع، وكان عامر بن أبي وقاص ابتاع شاة أمس من البقيع، فأرسلت إليه أن ابتع لي شاة من البقيع فلم توجد، فذكر لي أنك اشتريت شاة فأرسل بها إليَّ، فلم يجدْه الرسول، ووجد أهله، فدفعوها إلى رسولي، فقال رسول اللّٰه ﷺ: (( أطعموها الأسارى ))."],"takhrij":"حسن: رواه أبو داود (٣٣٣٢)، وأحمد (٢٢٥٠٩)، والسياق لأحمد.","grade":"حسن","chapter_ar":"باب النهي عن المحرمات والشبهات في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3332) and Ahmad (22509). This wording is Ahmad’s.","chapter_en":"Prohibition of unlawful and doubtful matters in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["A man from the Ansar reported: We went out with the Messenger of Allah ﷺ in a funeral procession. When we returned, the messenger of a woman from Quraysh met us and said: “O Messenger of Allah ﷺ, so-and-so invites you and those with you to a meal.” So he turned aside, and we turned aside with him. We sat as children sit before their fathers. Then the food was brought. The Messenger of Allah ﷺ placed his hand in it, and the people also put their hands in it. Then the people noticed that he was chewing his morsel without being able to swallow it. So they withdrew their hands, though they forgot about us at first, then remembered and took our hands back. The man began knocking the morsel from his hand until it fell, and they kept holding our hands, watching what the Messenger of Allah ﷺ would do. Then he spat it out and said: “I find this to be the meat of a sheep taken without the permission of its owners.” The woman then stood and said: “O Messenger of Allah ﷺ, I wished to gather you and those with you for a meal, so I sent to al-Baqi, but I did not find a sheep for sale. Amir ibn Abi Waqqas had bought a sheep yesterday from al-Baqi, so I sent to him that he should buy one for me from al-Baqi, but none was found. Then I was told that you had bought a sheep, so I sent for it, but the messenger did not find him; he found his family, and they handed it to my messenger.” The Messenger of Allah ﷺ said: “Feed it to the prisoners.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3332},{"key":"ahmad","label":"مسند الإمام أحمد","number":22509,"n":22509}]},{"num":5667,"demo":false,"sanad":"","matn":["عن كاتب المغيرة بن شعبة قال: كتب معاوية إلى المغيرة بن شعبة أن اكتب إليَّ بشيء سمعته من النبي ﷺ، فكتب إليه: سمعت النبي ﷺ يقول: (( إن اللّٰه كره لكم ثلاثاً: قيل وقال، وإضاعة المال، وكثرة السؤال ))."],"takhrij":"متفق عليه: رواه البخاري (١٤٧٧)، ومسلم (٥٩٣/١٣).","grade":"متفق عليه","chapter_ar":"باب النهي عن إضاعة المال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1477) and Muslim (593/13).","chapter_en":"Prohibition of wasting wealth","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["The scribe of al-Mughirah ibn Shu‘bah said: Muawiyah wrote to al-Mughirah ibn Shu‘bah: “Write to me something you heard from the Prophet ﷺ.” So he wrote to him: I heard the Prophet ﷺ say: “Allah dislikes for you three things: gossiping back and forth, wasting wealth, and asking too much.”"]},"buhuth":{"ar":["وفي رواية: (( إن اللّٰه حرم ثلاثاً، ونهى عن ثلاث: حرم عقوق الوالدين، ووأد البنات، ولا وهات. ونهى عن ثلاث: قيل وقال، وكثرة السؤال، وإضاعة المال )). وفي رواية: (( ومنعاً وهات )).","وقوله: (( ولا وهات )) أي حرم قول: لا، يعني الامتناع عن أداء ما تجب عليه من الحقوق، ويقول فيما ليس له فيه حق: أعط."],"en":["In another wording: “Allah has made three things unlawful and forbidden three things: He made unlawful disobedience to parents, burying daughters alive, and saying ‘don’t give’ while demanding ‘give me.’ And He forbade three things: gossiping back and forth, excessive questioning, and wasting wealth.” In another wording: “withholding and demanding.”","The phrase means refusing to give what one is obliged to give, while demanding what one has no right to demand."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1477},{"key":"muslim","label":"مسلم","number":593}]},{"num":5668,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( إن اللّه يرضى لكم ثلاثاً، ويكره لكم ثلاثاً، فيرضى لكم أن تعبدوه، ولا تشركوا به شيئاً، وأن تعتصموا بحبل اللّٰه جميعاً، ولا تفرقوا. ويكره لكم قيل وقال، وكثرة السؤال، وإضاعة المال ))."],"takhrij":"صحيح: رواه مسلم (١٧١٥).","grade":"صحيح","chapter_ar":"باب النهي عن إضاعة المال","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1715).","chapter_en":"Prohibition of wasting wealth","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Allah is pleased for you with three things and dislikes for you three things. He is pleased that you worship Him and associate nothing with Him, that you hold firmly together to the rope of Allah and do not become divided. And He dislikes for you gossiping back and forth, asking too much, and wasting wealth.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1715}]},{"num":5669,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: قال رسول اللّٰه ﷺ: (( لا ضررَ ولا ضِرَارَ ))."],"takhrij":"حسن: رواه مالك في الأقضية (٣٣)، والدارقطني (٣٠٧٩)، والحاكم (٢٣٤٥)، والبيهقي (٦/٦٩).","grade":"حسن","chapter_ar":"باب لا ضررَ ولا ضِرَارَ","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Malik in al-Aqdiyah (33), al-Daraqutni (3079), al-Hakim (2345), and al-Bayhaqi (6/69).","chapter_en":"No harm and no reciprocating harm","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said: “There should be neither harm nor reciprocating harm.”"]}},"tuhfa":{},"refs":[{"key":"malik/الاقضیہ","label":"مالك في الأقضية","number":33},{"key":"الدارقطنی","label":"الدارقطني","number":3079},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"sh9771","label":"سنن الدارقطني","number":3079,"n":3092},{"key":"hakim","label":"المستدرك على الصحيحين","number":2345,"n":2336}]},{"num":5670,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ مر على صبرة طعام، فأدخل يده فيها، فنالت أصابعه بللاً، فقال: (( ما هذا يا صاحب الطعام؟ )). قال: أصابته السماء، يا رسول الله. قال: (( أفلا جعلته فوق الطعام كي يراه الناس؟ من غش فليس مني ))."],"takhrij":"صحيح: رواه مسلم (١٠٢).","grade":"صحيح","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (102).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ passed by a heap of food and put his hand into it. His fingers touched dampness, so he said: “What is this, O owner of the food?” He said: “Rain fell on it, O Messenger of Allah ﷺ.” He said: “Why did you not put it on top of the food so people could see it? Whoever deceives is not from me.”"]},"buhuth":{"ar":["ورواه أحمد (٧٢٩٢)، وأبو داود (٣٤٩٢)، وجاء فيه: فأوحي إليه: أدخل يدك فيه، فأدخل يده، فإذا هو مبلول، فقال رسول اللّٰه ﷺ: (( ليس منا من غش ))."],"en":["Ahmad (7292) and Abu Dawud (3492) also narrated it, and in one wording: he was inspired to put his hand into it, and when he found it wet, the Messenger of Allah ﷺ said: “He is not from us who deceives.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":102}]},{"num":5671,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( من حمل علينا السلاح فليس منا، ومن غشنا فليس منا ))."],"takhrij":"صحيح: رواه مسلم (١٠١).","grade":"صحيح","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (101).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “Whoever bears arms against us is not from us, and whoever deceives us is not from us.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":101}]},{"num":5672,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسول اللّٰه ﷺ: (( من غشنا فليس منا، ومن رمانا بالليل فليس منا ))."],"takhrij":"حسن: رواه الطبراني في الكبير (١١/٢٢١).","grade":"حسن","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (11/221).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “Whoever deceives us is not from us, and whoever attacks us at night is not from us.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":11}]},{"num":5673,"demo":false,"sanad":"","matn":["عن عقبة بن عامر قال: سمعت رسول اللّٰه ﷺ يقول: (( المسلم أخو المسلم، ولا يحل لمسلم باع من أخيه بيعاً فيه عيب إلا بيَّنه له ))."],"takhrij":"حسن: رواه ابن ماجه (٢٢٤٦)، والحاكم (٢١٥٢)، والبيهقي (٥/٣٢٠).","grade":"حسن","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2246), al-Hakim (2152), and al-Bayhaqi (5/320).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Uqbah ibn Amir said: I heard the Messenger of Allah ﷺ say: “A Muslim is the brother of a Muslim, and it is not lawful for a Muslim who sells something to his brother while it has a defect except that he must make it clear to him.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2246},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"hakim","label":"المستدرك على الصحيحين","number":2152,"n":2143},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10734,"n":10824}]},{"num":5674,"demo":false,"sanad":"","matn":["عن عائشة أن النبي ﷺ قال: (( من غشنا فليس منا ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٢٥٦).","grade":"حسن","chapter_ar":"باب تحريم الغش في البيوع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1256).","chapter_en":"The prohibition of deceit in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Aishah narrated that the Prophet ﷺ said: “Whoever deceives us is not from us.”"]},"buhuth":{"ar":["وأما قوله: (( من غشنا فليس منا )) فمعناه أنه ليس على سيرتنا وهدينا، وهي الصدق والوفاء."],"en":["As for the saying, “Whoever deceives us is not from us,” it means that he is not following our way and guidance, which are truthfulness and faithfulness."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1256},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1256,"n":1257}]},{"num":5675,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: سمعت رسول اللّٰه ﷺ يقول: (( الحلف منفقة للسلعة، ممحقة للبركة ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٨٧)، ومسلم (١٦٠٦)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2087) and Muslim (1606). The wording is al-Bukhari’s.","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah said: I heard the Messenger of Allah ﷺ say: “Swearing may make the goods sell, but it wipes out the blessing.”"]},"buhuth":{"ar":["قوله: (( منفقة )) بفتح الميم والفاء، بينهما نون ساكنة، من النفاق، وهو الرواج ضد الكساد."],"en":["The word means that it causes the goods to move and sell, the opposite of stagnation."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2087},{"key":"muslim","label":"مسلم","number":1606}]},{"num":5676,"demo":false,"sanad":"","matn":["عن أبي هريرة يقول: قال رسول اللّٰه ﷺ: (( ثلاثة لا ينظر اللّٰه إليهم يوم القيامة ولا يزكيهم ولهم عذاب أليم: رجل كان له فضل ماء بالطريق فمنعه من ابن السبيل، ورجل بايع إماماً لا يبايعه إلا لدنيا، فإن أعطاه منها رضي، وإن لم يعطه منها سخط، ورجل أقام سلعته بعد العصر، فقال: واللّه الذي لا إله غيره لقد أُعطيت بها كذا وكذا فصدقه رجل )) ثم قرأ هذه الآية: ( إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًا قَلِيلًا ) [آل عمران: ٧٧]."],"takhrij":"متفق عليه: رواه البخاري (٢٣٥٨)، ومسلم (١٠٨).","grade":"متفق عليه","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2358) and Muslim (108).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “There are three whom Allah will not look at on the Day of Resurrection, nor purify them, and they will have a painful punishment: a man who has excess water on the road but withholds it from a traveler; a man who gives allegiance to a leader only for worldly gain — if he is given something from it he is pleased, and if he is not given he is angered; and a man who displays his goods after the Asr prayer and says: ‘By Allah, besides whom there is no god, I was offered such-and-such for it,’ and a man believes him.” Then he recited the verse: “Indeed, those who trade away the covenant of Allah and their oaths for a small price…” [Al Imran: 77]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2358},{"key":"muslim","label":"مسلم","number":108}]},{"num":5677,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( أربعة يبغضهم اللّٰه عز وجل: البياع الحلاف، والفقير المختال، والشيخ الزاني، والإمام الجائر ))."],"takhrij":"صحيح: رواه النسائي (٢٥٧٦).","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasai (2576).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, hates four people: the merchant who swears frequently, the arrogant poor man, the old man who commits fornication, and the unjust ruler.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2576}]},{"num":5678,"demo":false,"sanad":"","matn":["عن أبي ذر، عن النبي ﷺ قال: (( ثلاثة لا يكلمهم اللّٰه يوم القيامة ولا ينظر إليهم ولا يزكيهم ولهم عذاب أليم )). قال: فقرأها رسول اللٰه ﷺ ثلاث مرار. قال أبو ذر: خابوا وخسروا، من هم يا رسول الله؟ قال: (( المسبل، والمنان، والمنفق سلعته بالحلف الكاذب ))."],"takhrij":"صحيح: رواه مسلم (١٠٦).","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (106).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Dharr narrated from the Prophet ﷺ that he said: “There are three whom Allah will not speak to on the Day of Resurrection, nor look at, nor purify, and they will have a painful punishment.” The Messenger of Allah ﷺ repeated it three times. Abu Dharr said: “They are ruined and lost — who are they, O Messenger of Allah ﷺ?” He said: “The one who lets his garment hang below his ankles, the one who reminds others of his favors, and the one who sells his goods by false oaths.”"]},"buhuth":{"ar":["وفي رواية: (( والمنفق سلعته بالحلف الفاجر، والمسبل إزاره )).","والمنفِّق بالتشديد من النفاق، وهو ضد الكساد."],"en":["In another wording: “the one who promotes his goods by wicked oaths, and the one who lets his garment hang low.”","Here it means the one who makes his goods sell and circulate, the opposite of goods remaining unsold."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":106}]},{"num":5679,"demo":false,"sanad":"","matn":["عن مطرف بن عبد اللّٰه بن الشخير قال: بلغني عن أبي ذر حديث، فكنت أحب أن ألقاه، فلقيته، فقلت له: يا أبا ذر، بلغني عنك حديث، فكنت أحب أن ألقاك فأسألك عنه. فقال: قد لقيت فاسأل. قال: قلت: بلغني أنك تقول: سمعت رسول اللّٰه ﷺ يقول: (( ثلاثة يحبهم الله، وثلاثة يبغضهم اللّه )). قال: نعم، فما إخالك أكذب على خليلي محمد ﷺ - ثلاثاً يقولها - قال: قلت: من الثلاثة الذين يحبهم اللّٰه عز وجل؟ قال: (( رجل غزا في سبيل الله، فلقي العدو مجاهداً محتسباً، فقاتل حتى قتل، وأنتم تجدون في كتاب اللّٰه عز وجل: ( إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَاتِلُونَ فِي سَبِيلِهِ صَفًّا ) [الصف: ٤]، ورجل له جار يؤذيه، فيصبر على أذاه ويحتسبه حتى يكفيه الله إياه بموت أو حياة، ورجل يكون مع قوم فيسيرون حتى يشق عليهم الكرى أو النعاس، فينزلون في آخر الليل، فيقوم إلى وضوئه وصلاته )).","قال: قلت: من الثلاثة الذين يبغضهم اللّٰه؟ قال: (( الفخور المختال، وأنتم تجدون في كتاب اللّٰه عز وجل: ( إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ ) [لقمان: ١٨]، والبخيل المنان، والتاجر - أو البياع - الحلاف )). قال: قلت: يا أبا ذر، ما المال؟ قال: فِرَقٌ لنا وذودٌ - يعني غنماً يسيرة -. قال: قلت: لست عن هذا أسأل، إنما أسألك عن صامت المال. قال: ما أصبح لا أمسى، وما أمسى لا أصبح. قال: قلت: يا أبا ذر، ما لك ولإخوتك قريش؟ قال: والله لا أسألهم دنيا، ولا أستفتيهم عن دين اللّٰه حتى ألقى اللّٰه ورسوله. ثلاثاً يقولها."],"takhrij":"صحيح: رواه أحمد (٢١٥٣٠)، والطبراني في الكبير (٢/١٦١)، والحاكم (٢/٨٨-٨٩)، واللفظ لأحمد.","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (21530), al-Tabarani in al-Kabir (2/161), and al-Hakim (2/88–89). The wording is Ahmad’s.","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Mutarrif ibn Abdullah ibn al-Shikhkhir said: A hadith from Abu Dharr reached me, and I wished to meet him. When I met him, I said: “O Abu Dharr, a hadith from you reached me, and I wanted to meet you to ask you about it.” He said: “You have met me, so ask.” I said: “I heard that you say: I heard the Messenger of Allah ﷺ say, ‘Three are loved by Allah, and three are hated by Allah.’” He said: “Yes, and I do not think I would lie about my beloved Muhammad ﷺ” — repeating that three times. I said: “Who are the three whom Allah loves?” He said: “A man who goes out fighting in the way of Allah, meets the enemy striving and seeking reward, and fights until he is killed — and you find in the Book of Allah: ‘Indeed, Allah loves those who fight in His cause in ranks’ [al-Saff: 4]; a man who has a neighbor who harms him, yet he remains patient over his harm seeking reward until Allah relieves him of him, whether by death or by life; and a man who is traveling with people until drowsiness and sleep become hard on them, so they camp at the end of the night, and he gets up for his ablution and prayer.”","I said: “Who are the three whom Allah hates?” He said: “The boastful arrogant one — and you find in the Book of Allah: ‘Indeed, Allah does not love every self-deluded boaster’ [Luqman: 18] — the stingy one who reminds others of his favors, and the trader — or seller — who swears frequently.”","I said: “O Abu Dharr, what is wealth?” He said: “A small flock and a few camels for us,” meaning a little livestock. I said: “That is not what I mean; I mean stored wealth.” He said: “What is with me in the morning does not remain till evening, and what is with me in the evening does not remain till morning.” I said: “O Abu Dharr, what is there between you and your brothers from Quraysh?” He said: “By Allah, I do not ask them for worldly things, nor do I seek legal opinions from them in the religion of Allah until I meet Allah and His Messenger.” He said that three times."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":2},{"key":"hakim","label":"الحاكم","number":2},{"key":"ahmad","label":"مسند الإمام أحمد","number":21530,"n":21530}]},{"num":5680,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن أبي أوفى أن رجلاً أقام سلعة وهو في السوق، فحلف بالله لقد أُعطي بها ما لم يُعط؛ ليوقع فيها رجلاً من المسلمين، فنزلت: ( إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ ٱللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًا قَلِيلًا ) [آل عمران: ٧٧]."],"takhrij":"صحيح: رواه البخاري (٢٠٨٨).","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2088).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abdullah ibn Abi Awfa said: A man displayed goods in the market and swore by Allah that he had been offered for them what he had not actually been offered, intending to deceive a Muslim into buying them. Then the verse was revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” [Al Imran: 77]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2088}]},{"num":5681,"demo":false,"sanad":"","matn":["عن أبي قتادة الأنصاري:","أنه سمع رسول الله ﷺ يقول:","«إِيَّاكُمْ وَكَثْرَةَ الْحَلِفِ فِي الْبَيْعِ؛ فَإِنَّهُ يُنَفِّقُ، ثُمَّ يَمْحَقُ»."],"takhrij":"صحيح: رواه مسلم (١٦٠٧).","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1607).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abū Qatādah al-Anṣārī reported that he heard the Messenger of Allah ﷺ say:","“Beware of excessive swearing in transactions, for it may make the merchandise sell, but afterward it erases the blessing.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1607}]},{"num":5682,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن شبل قال: قال رسول اللّٰه ﷺ: (( إنَّ التُّجَّارَ هُمُ الفُجَّارُ )). قيل: يا رسولَ اللّٰه، أوَليس قد أحلَّ اللّٰه البيعَ؟ قال: (( بلى، ولكنهم يُحدِّثون فيكذبون، ويَحلفون فيأثمون ))."],"takhrij":"صحيح: رواه أحمد (١٥٥٣٠)، والحاكم (٧-٦/٢)، والبيهقي في شعب الإيمان (٢١٨/٤).","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15530), al-Hakim (2/6–7), and al-Bayhaqi in Shu‘ab al-Iman (4/218).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abd al-Rahman ibn Shibl reported that the Messenger of Allah ﷺ said: “Merchants are the sinful ones.” It was said: “Messenger of Allah ﷺ, has Allah not made trade lawful?” He said: “Yes, but they speak and lie, and they swear oaths and thereby sin.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":7},{"key":"البیہقی/شعب_الایمان","label":"البيهقي في شعب الإيمان","number":218},{"key":"ahmad","label":"مسند الإمام أحمد","number":15530,"n":15530}]},{"num":5683,"demo":false,"sanad":"","matn":["عن سلمان قال: قال رسول اللّٰه ﷺ: (( ثلاثةٌ لا ينظرُ اللّٰهُ إليهم يوم القيامة: أُشَيْمِطُ زانٍ، وعائلٌ مستكبرٌ، ورجلٌ جعل اللّٰهُ له بضاعةً لا يشتري إلا بيمينِه، ولا يبيع إلا بيمينِه ))."],"takhrij":"صحيح: رواه الطبراني في الكبير (٣٠١/٦).","grade":"صحيح","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Mu‘jam al-Kabir (6/301).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Salman reported that the Messenger of Allah ﷺ said: “There are three to whom Allah will not look on the Day of Resurrection: an old man who commits fornication, a poor man who is arrogant, and a man whose trade is such that he does not buy except by swearing an oath and does not sell except by swearing an oath.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":301}]},{"num":5684,"demo":false,"sanad":"","matn":["عن أبي سعيد قال: مرَّ أعرابيٌّ بشاة، فقلتُ: تبيعنيها بثلاثة دراهم؟ قال: لا واللّٰه، ثم باعنيها، فذكرتُ ذلك لرسول اللّٰه ﷺ فقال: (( باع آخرتَه بدُنياه ))."],"takhrij":"حسن: رواه ابن حبان (٤٩٠٩).","grade":"حسن","chapter_ar":"باب النهي عن الحلف في البيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4909).","chapter_en":"Prohibition of swearing in sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Abu Sa‘id reported: A desert Arab passed by with a sheep, and I said, “Will you sell it to me for three dirhams?” He said, “No, by Allah,” then he sold it to me. I mentioned that to the Messenger of Allah ﷺ, and he said: “He sold his Hereafter for his worldly gain.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2903,"n":2900}]},{"num":5685,"demo":false,"sanad":"","matn":["عن قيس بن أبي غَرَزَة قال: كنّا في عهد رسول اللّٰه ﷺ نُسمَّى السماسرة، فمرَّ بنا رسول اللّٰه ﷺ فسمّانا باسمٍ هو أحسن، فقال: (( يا معشرَ التُّجّارِ، إنَّ البيعَ يحضره اللغوُ والحلفُ، فشوبوه بالصدقة ))."],"takhrij":"صحيح: رواه أبو داود (٣٣٢٦)، والترمذي (١٢٠٨)، والنسائي (٣٧٩٧)، وابن ماجه (٢١٤٥)، وأحمد (١٦١٣٤).","grade":"صحيح","chapter_ar":"باب التوقِّي في التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3326), al-Tirmidhi (1208), al-Nasa’i (3797), Ibn Majah (2145), and Ahmad (16134).","chapter_en":"Caution and restraint in trade","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":6,"content":{"translation":{"en":["Qays ibn Abi Gharazah said: During the time of the Messenger of Allah ﷺ, we were called brokers. The Messenger of Allah ﷺ passed by us and gave us a better name. He said: “O merchants, trade is attended by idle talk and oaths, so mix it with charity.”"]},"buhuth":{"ar":["وقوله: (( كنّا نُسمَّى السماسرة )) جمع سمسار، وهو اسمٌ للتاجر الوسيط. وقوله: (( فشوبوه بالصدقة )) أي اخلطوا تجارتكم بالصدقة لتكفِّر ما قد يقع فيها من اللغو والحلف ونحو ذلك."],"en":["His statement, “We were called brokers,” means intermediaries in trade. And his statement, “Mix it with charity,” means: accompany your trade with charity so that it may expiate what may occur in it of idle speech, swearing, and similar matters."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3326},{"key":"tirmidhi","label":"الترمذي","number":1208},{"key":"nasai","label":"النسائي","number":3797},{"key":"ibnmajah","label":"ابن ماجه","number":2145},{"key":"ahmad","label":"مسند الإمام أحمد","number":16134,"n":16134}]},{"num":5686,"demo":false,"sanad":"","matn":["عن البراء بن عازب قال: قال: أتانا رسول اللّٰه ﷺ إلى البقيع، فقال: (( يا معشرَ التُّجّارِ ))، حتى إذا أشرأبُّوا قال: (( إنَّ التُّجّارَ يُحشرون يوم القيامة فُجّارًا إلا من اتّقى وبرَّ وصدق ))."],"takhrij":"حسن: رواه البيهقي في شعب الإيمان (٤٥٠٧).","grade":"حسن","chapter_ar":"باب التوقِّي في التجارة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi in Shu‘ab al-Iman (4507).","chapter_en":"Caution and restraint in trade","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":6,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib reported: The Messenger of Allah ﷺ came to us at al-Baqi‘ and said: “O merchants.” When they raised their heads to listen, he said: “Merchants will be raised on the Day of Resurrection as sinful people, except those who fear Allah, act righteously, and speak truthfully.”"]}},"tuhfa":{},"refs":[{"key":"البیہقی/شعب_الایمان","label":"البيهقي في شعب الإيمان","number":4507}]},{"num":5687,"demo":false,"sanad":"","matn":["عن عطاء بن يسار قال: لقيتُ عبدَ اللّٰه بن عمرو بن العاص، قلتُ: أخبرني عن صفة رسول اللّٰه ﷺ في التوراة. قال: أجل، واللّٰه، إنّه لموصوفٌ في التوراة ببعض صفته في القرآن: {يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِدًا وَمُبَشِّرًا وَنَذِيرًا} [الأحزاب: ٤٥]، وحرزًا للأميين، أنت عبدي ورسولي، سمّيتُك المتوكّل، ليس بفظٍّ ولا غليظٍ ولا سخّابٍ في الأسواق، ولا يدفع بالسيئة السيئة، ولكن يعفو ويغفر، ولن يقبضه اللّٰه حتى يقيم به الملّة العوجاء بأن يقولوا: لا إله إلا اللّٰه، ويفتح بها أعينًا عميًا، وآذانًا صمًّا، وقلوبًا غلفًا."],"takhrij":"صحيح: رواه البخاري (٢١٢٥).","grade":"صحيح","chapter_ar":"باب كراهية السَّخَب ورفع الصوت في الأسواق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2125).","chapter_en":"The dislike of shouting and raising the voice in marketplaces","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":7,"content":{"translation":{"en":["‘Ata’ ibn Yasar said: I met Abdullah ibn ‘Amr ibn al-‘As and said, “Tell me about the description of the Messenger of Allah ﷺ in the Torah.” He said: “Yes, by Allah, he is described in the Torah with some of the description found in the Quran: ‘O Prophet, We have sent you as a witness, a bringer of good news, and a warner.’ He is a protection for the unlettered people. You are My servant and My messenger. I have named you the Reliant One. He is neither harsh nor hard-hearted nor loud and quarrelsome in the marketplaces. He does not repay evil with evil, but rather pardons and forgives. Allah will not take him until He straightens through him the crooked religion, so that they say: There is no god but Allah, and through him He opens blind eyes, deaf ears, and sealed hearts.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2125}]},{"num":5688,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جدّه أن رسول اللّٰه ﷺ نهى عن الشراء والبيع في المسجد، وأن تُنشد فيه ضالّة، وأن يُنشد فيه شعر، ونهى عن التحلّق قبل الصلاة يوم الجمعة."],"takhrij":"حسن: رواه أبو داود (١٠٧٩)، والترمذي (٣٢٢)، والنسائي (٧١٦)، وصححه ابن خزيمة (١٣٠٦).","grade":"حسن","chapter_ar":"باب في كراهية البيع والشراء في المساجد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1079), al-Tirmidhi (322), al-Nasa’i (716), and authenticated by Ibn Khuzaymah (1306).","chapter_en":"The dislike of buying and selling in mosques","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":8,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ forbade buying and selling in the mosque, announcing lost property in it, reciting poetry in it, and sitting in circles before the Friday prayer."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1079},{"key":"tirmidhi","label":"الترمذي","number":322},{"key":"nasai","label":"النسائي","number":716},{"key":"صححہ_ابن_خزیمہ","label":"صححه ابن خزيمة","number":1306}]},{"num":5689,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال النبي ﷺ: (( أدِّ الأمانةَ إلى من ائتمنك، ولا تخنْ من خانك ))."],"takhrij":"حسن: رواه أبو داود (٣٥٣٥)، والترمذي (١٢٦٤) وحسّنه، والدارقطني (٣٥/٣)، والحاكم (٤٦/٢).","grade":"حسن","chapter_ar":"باب النهي عن خيانة من خانك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3535), al-Tirmidhi (1264), who graded it Hasan, al-Daraqutni (3/35), and al-Hakim (2/46).","chapter_en":"The prohibition of betraying one who has betrayed you","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet said: “Return the trust to the one who entrusted you, and do not betray the one who betrayed you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3535},{"key":"tirmidhi","label":"الترمذي","number":1264},{"key":"الدارقطنی","label":"الدارقطني","number":35},{"key":"sh9771","label":"سنن الدارقطني","number":2936,"n":2944},{"key":"hakim","label":"المستدرك على الصحيحين","number":2296,"n":2288}]},{"num":5690,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( اجتنبوا السبع الموبقات )). قالوا: يا رسول اللّٰه، وما هن؟ قال: (( الشرك باللّٰه، والسحر، وقتل النفس التي حرّم اللّٰه إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولّي يوم الزحف، وقذف المحصنات المؤمنات الغافلات ))."],"takhrij":"متفق عليه: رواه البخاري (٢٧٦٦)، ومسلم (٨٩).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2766) and Muslim (89).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet said: “Avoid the seven destructive sins.” They said: “Messenger of Allah ﷺ, what are they?” He said: “Associating partners with Allah, sorcery, killing a soul that Allah has forbidden except with right, consuming usury, consuming the property of an orphan, fleeing on the day of battle, and accusing chaste, believing, unsuspecting women.”"]},"intro":{"ar":["قال اللّٰه تعالى: {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنْتُمْ مُؤْمِنِينَ ۝ فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللَّهِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ ۝ وَإِنْ كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ ۝ وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ} [البقرة: ٢٧٨-٢٨١].","وقال تعالى: {الَّذِينَ يَأْكُلُونَ الرِّبَا لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ…} [البقرة: ٢٧٥-٢٧٦].","والربا في اللغة: الزيادة. وفي الشرع: الزيادة في المال، ويكون في الفضل وفي الأجل."],"en":["Allah the Exalted said: “O you who believe, fear Allah and give up what remains of usury, if you are truly believers. But if you do not, then be informed of a war from Allah and His Messenger. And if you repent, then you may have your principal sums; you do not wrong, nor are you wronged. And if someone is in hardship, then let there be postponement until ease. But if you remit it as charity, that is better for you, if only you knew. And fear a Day on which you will be returned to Allah; then every soul will be paid in full for what it earned, and they will not be wronged.” [al-Baqarah: 278–281]","And He said: “Those who consume usury will not stand except as one stands who has been struck by Satan into madness…” [al-Baqarah: 275–276]","In language, usury means increase. In sacred law, it means an unlawful increase in wealth, whether through excess in exchange or through delay in repayment."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2766},{"key":"muslim","label":"مسلم","number":89}]},{"num":5691,"demo":false,"sanad":"","matn":["عن عون بن أبي جحيفة قال: رأيتُ أبي اشترى عبدًا حجّامًا، فأمر بمحاجمه فكسرت، فسألته، فقال: نهى النبي ﷺ عن ثمن الكلب، وثمن الدم، ونهى عن الواشمة والموشومة، وآكل الربا ومؤكله، ولعن المصوّر."],"takhrij":"صحيح: رواه البخاري (٢٢٣٨).","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2238).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["‘Awn ibn Abi Juhayfah said: I saw my father buy a slave who performed cupping, and he ordered his instruments to be broken. I asked him, and he said: The Prophet forbade the price of a dog and the price of blood, forbade the tattooer and the one tattooed, forbade the consumer of usury and the one who pays it, and he cursed the image-maker."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2238}]},{"num":5692,"demo":false,"sanad":"","matn":["عن سمرة بن جندب قال: قال النبي ﷺ: (( رأيت الليلة رجلين أتياني، فأخرجاني إلى أرضٍ مقدّسة… حتى أتينا على نهرٍ من دم، فيه رجل قائم، وعلى وسط النهر رجل بين يديه حجارة… فقلت: ما هذا؟ فقال: الذي رأيتَه في النهر آكل الربا ))."],"takhrij":"صحيح: رواه البخاري (٢٠٨٥)، ومسلم (٢٢٧٥)، واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2085) and Muslim (2275). The wording is that of al-Bukhari.","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Prophet said: “Last night I saw two men who came to me and took me out to a sacred land… until we came upon a river of blood, in which there was a man standing, and in the middle of the river there was another man before whom were stones… I said: What is this? They said: The one you saw in the river is the consumer of usury.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2085},{"key":"muslim","label":"مسلم","number":2275}]},{"num":5693,"demo":false,"sanad":"","matn":["عن جابر قال: لعن رسول اللّٰه ﷺ آكلَ الربا، وموكله، وكاتبه، وشاهديه. وقال: (( هم سواء ))."],"takhrij":"صحيح: رواه مسلم (١٥٩٨).","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1598).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Jabir reported: The Messenger of Allah ﷺ cursed the one who consumes usury, the one who pays it, the one who records it, and its two witnesses. And he said: “They are all alike.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1598}]},{"num":5694,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مسعود قال: لعن رسول اللّٰه ﷺ آكلَ الربا، وموكله. قال: قلت: وكاتبه وشاهديه؟ قال: إنما نحدّث بما سمعنا."],"takhrij":"صحيح: رواه مسلم (١٥٩٧).","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1597).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Abdullah ibn Mas‘ud reported: The Messenger of Allah ﷺ cursed the one who consumes usury and the one who pays it. I said: “And the one who records it and its two witnesses?” He said: “We only narrate what we heard.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1597}]},{"num":5695,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مسعود، عن النبي ﷺ قال: (( ما أحدٌ أكثر من الربا إلا كان عاقبةُ أمره إلى قِلّة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٢٧٩).","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2279).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Abdullah ibn Mas‘ud reported that the Prophet said: “No one increases in usury except that the final outcome of his affair will be loss and decrease.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2279}]},{"num":5696,"demo":false,"sanad":"","matn":["عن ابن عباس قال: آخر آية نزلت على النبي ﷺ آية الربا."],"takhrij":"صحيح: رواه البخاري (٤٥٤٤).","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4544).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Abbas said: The last verse revealed to the Prophet was the verse about usury."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4544}]},{"num":5697,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب قال: إن آخر ما نزل من القرآن آية الربا، وإن رسول اللّٰه ﷺ قبض ولم يفسرها، فدعوا الربا والريبة."],"takhrij":"حسن: رواه ابن ماجه (٢٢٧٦)، وأحمد (٢٤٦).","grade":"حسن","chapter_ar":"باب ما جاء في الزجر عن أكل الربا وبيعه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2276) and Ahmad (246).","chapter_en":"Warnings against consuming usury and dealing in it","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["Umar ibn al-Khattab said: The last part of the Quran to be revealed was the verse about usury, and the Messenger of Allah ﷺ passed away before explaining it in detail, so leave usury and whatever causes doubt."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2276},{"key":"ahmad","label":"مسند الإمام أحمد","number":246,"n":246}]},{"num":5698,"demo":false,"sanad":"","matn":["عن مالك بن أوس بن الحدثان النصري: أنه التمس صرفًا بمائة دينار. قال: فدعاني طلحة بن عبيد الله، فتراوضنا حتى اصطرف مني، وأخذ الذهب يقلبها في يده، ثم قال: حتى يأتيني خازني من الغابة، وعمر بن الخطاب يسمع، فقال عمر: والله لا تفارقه حتى تأخذ منه. ثم قال: قال رسول الله ﷺ: (( الذهب بالورق ربا إلا هاء وهاء، والبر بالبر ربا إلا هاء وهاء، والتمر بالتمر ربا إلا هاء وهاء، والشعير بالشعير ربا إلا هاء وهاء ))."],"takhrij":"متفق عليه: رواه مالك (٣٨) والبخاري (٢١٧٤) ومسلم (١٥٨٦).","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (38), al-Bukhari (2174), and Muslim (1586).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Malik ibn Aws ibn al-Hadathan al-Nasri reported that he sought to exchange one hundred dinars. Talhah ibn Ubayd Allah called him, and they negotiated until Talhah agreed to exchange with him. Talhah took the gold and turned it in his hand, then said, “Wait until my treasurer comes from the forest area.” Umar ibn al-Khattab was listening and said, “By Allah, you must not leave him until you take it from him.” Then he said: The Messenger of Allah ﷺ said, “Gold for silver is usury unless it is hand to hand, wheat for wheat is usury unless it is hand to hand, dates for dates is usury unless it is hand to hand, and barley for barley is usury unless it is hand to hand.”"]},"buhuth":{"ar":["قوله: (( فتراوضنا )) أي تجارينا الكلام في قدر العوض بالزيادة والنقص، كأن كلا منهما كان يروض صاحبه، ويسهل خلقه. وقيل: المراوضة هنا المواصفة بالسلعة، وهي أن يصف كل منهما سلعته لرفيقه.","وقوله: (( إلا هاء وهاء )) أي خذ وهات، والمعنى إلا يدًا بيد، يعني مقابضة في المجلس."],"en":["Its meaning: “We negotiated” means they discussed the amount of exchange, with increase and decrease, as each tried to gently persuade the other. It was also said that here it means describing the goods, with each one describing his item to the other.","Its meaning: “Except hand to hand” means: take and give. The meaning is that it must be exchanged on the spot, with both sides taking possession in the same sitting."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":38},{"key":"bukhari","label":"البخاري","number":2174},{"key":"muslim","label":"مسلم","number":1586}]},{"num":5699,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري أن رسول الله ﷺ قال: (( لا تبيعوا الذهب بالذهب إلا مثلًا بمثل، ولا تشفوا بعضها على بعض، ولا تبيعوا الورق بالورق إلا مثلًا بمثل، ولا تشفوا بعضها على بعض، ولا تبيعوا منها شيئًا غائبًا بناجز ))."],"takhrij":"متفق عليه: رواه مالك (٣٠) والبخاري (٢١٧٧)، ومسلم (١٥٨٤).","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (30), al-Bukhari (2177), and Muslim (1584).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Saeed al-Khudri reported that the Messenger of Allah ﷺ said: “Do not sell gold for gold except equal for equal, and do not make some of it exceed some of it. Do not sell silver for silver except equal for equal, and do not make some of it exceed some of it. And do not sell any delayed amount of it for what is present and immediate.”"]},"buhuth":{"ar":["قوله: (( ولا تشفوا )) أي لا تفضلوا، وهو رباعي من أشف، والشف - بالكسر - الزيادة، وتطلق على النقص."],"en":["Its meaning: “Do not make some of it exceed some of it” means do not give one side more than the other. The word refers to increase, and it can also be used for deficiency."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":30},{"key":"bukhari","label":"البخاري","number":2177},{"key":"muslim","label":"مسلم","number":1584}]},{"num":5700,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: قال رسول الله ﷺ: (( الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح مثلًا بمثل، يدًا بيد، فمن زاد أو استزاد فقد أربى، الآخذ والمعطي فيه سواء ))."],"takhrij":"صحيح: رواه مسلم (١٥٨٤).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1584).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Saeed al-Khudri reported that the Messenger of Allah ﷺ said: “Gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, and salt for salt must be equal for equal and hand to hand. Whoever gives more or asks for more has engaged in usury. The taker and the giver are the same in that.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1584}]},{"num":5701,"demo":false,"sanad":"","matn":["عن أبي بكرة قال: قال رسول الله ﷺ: (( لا تبيعوا الذهب بالذهب إلا سواء بسواء، والفضة بالفضة إلا سواء بسواء، وبيعوا الذهب بالفضة، والفضة بالذهب كيف شئتم ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٧٥)، ومسلم (١٥٩٠).","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2175) and Muslim (1590).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Bakrah reported that the Messenger of Allah ﷺ said: “Do not sell gold for gold except equal for equal, and do not sell silver for silver except equal for equal. But sell gold for silver, and silver for gold, however you wish.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2175},{"key":"muslim","label":"مسلم","number":1590}]},{"num":5702,"demo":false,"sanad":"","matn":["عن أبي المنهال قال: باع شريك لي ورقًا بنسيئة إلى الموسم، أو إلى الحج، فجاء إليَّ فأخبرني، فقلت: هذا أمر لا يصلح. قال: قد بعته في السوق، فلم ينكر ذلك علي أحد. فأتيت البراء بن عازب، فسألته، فقال: قدم النبي ﷺ المدينة ونحن نبيع هذا البيع، فقال: (( ما كان يدًا بيد فلا بأس به، وما كان نسيئة فهو ربا )). وائت زيد بن أرقم؛ فإنه أعظم تجارة مني. فأتيته، فسألته، فقال مثل ذلك."],"takhrij":"متفق عليه: رواه مسلم (١٥٨٩: ٧٨، ٨٦) والبخاري (٢١٨٠، ٢١٨١).","grade":"متفق عليه","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Muslim (1589, nos. 78 and 86) and al-Bukhari (2180, 2181).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu al-Minhal reported: A partner of mine sold silver on delayed payment until the season, or until the pilgrimage. He came and told me, and I said, “This is not right.” He said, “I sold it in the market, and no one objected to me.” So I went to al-Bara ibn Azib and asked him. He said: The Prophet came to Madinah while we used to make this type of sale, and he said, “Whatever is hand to hand is permissible, and whatever is delayed is usury.” Then he said: “Go to Zayd ibn Arqam, for he is greater than me in trade.” So I went to him and asked him, and he said the same."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1589},{"key":"bukhari","label":"البخاري","number":2180}]},{"num":5703,"demo":false,"sanad":"","matn":["عن عبادة بن الصامت قال: قال رسول الله ﷺ: (( الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح مثلًا بمثل، سواء بسواء، يدًا بيد، فإذا اختلفت هذه الأصناف فبيعوا كيف شئتم إذا كان يدًا بيد ))."],"takhrij":"صحيح: رواه مسلم (١٥٨٧: ٨١).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1587, no. 81).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Ubadah ibn al-Samit reported that the Messenger of Allah ﷺ said: “Gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, and salt for salt must be equal for equal, exact and equal, hand to hand. If these categories differ, then sell as you wish, so long as it is hand to hand.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1587}]},{"num":5704,"demo":false,"sanad":"","matn":["عن أبي قلابة قال: كنت بالشام في حلقة فيها مسلم بن يسار، فجاء أبو الأشعث، قال: قالوا: أبو الأشعث، أبو الأشعث. فجلس، فقلت له: حدِّث أخانا حديث عبادة بن الصامت. قال: نعم، غزونا غزاة وعلى الناس معاوية، فغنمنا غنائم كثيرة، فكان فيما غنمنا آنية من فضة، فأمر معاوية رجلًا أن يبيعها في أعطيات الناس، فتسارع الناس في ذلك، فبلغ عبادة بن الصامت، فقام، فقال: إني سمعت رسول الله ﷺ ينهى عن بيع الذهب بالذهب، والفضة بالفضة، والبر بالبر، والشعير بالشعير، والتمر بالتمر، والملح بالملح إلا سواء بسواء، عينًا بعين. فمن زاد أو ازداد فقد أربى. فرد الناس ما أخذوا، فبلغ ذلك معاوية، فقام خطيبًا، فقال: ألا ما بال رجال يتحدثون عن رسول الله ﷺ أحاديث قد كنا نشهده ونصحبه، فلم نسمعها منه. فقام عبادة بن الصامت، فأعاد القصة، ثم قال: لنحدثن بما سمعنا من رسول الله ﷺ وإن كره معاوية - أو قال: وإن رغم -، ما أبالي أن لا أصحبه في جنده ليلة سوداء."],"takhrij":"صحيح: رواه مسلم (١٥٨٧: ٨٠).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1587, no. 80).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Qilabah reported: I was in Syria in a circle that included Muslim ibn Yasar, when Abu al-Ashath came. People said, “Abu al-Ashath, Abu al-Ashath.” He sat down, and I said to him, “Tell our brother the hadith of Ubadah ibn al-Samit.” He said: Yes. We went on a military expedition while Muawiyah was over the people, and we obtained much war booty. Among what we captured were silver vessels. Muawiyah ordered a man to sell them among the people as part of their stipends, so the people rushed to that. News of this reached Ubadah ibn al-Samit, so he stood and said: “I heard the Messenger of Allah ﷺ forbid selling gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, and salt for salt except equal for equal, item for item. Whoever gives more or takes more has dealt in usury.” So the people returned what they had taken. This reached Muawiyah, and he stood to speak and said: “What is the matter with some men narrating hadiths from the Messenger of Allah ﷺ when we were with him and accompanied him, yet we did not hear these from him?” Then Ubadah ibn al-Samit stood up, repeated the story, and said: “We will certainly narrate what we heard from the Messenger of Allah ﷺ even if Muawiyah dislikes it, or despite him. I do not care if I never accompany him in his army on a dark night.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1587}]},{"num":5705,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال: (( الدينار بالدينار، والدرهم بالدرهم لا فضل بينهما ))."],"takhrij":"صحيح: رواه مالك (٢٩) ومسلم (١٥٨٨: ٨٥).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Malik (29) and Muslim (1588, no. 85).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “A dinar for a dinar, and a dirham for a dirham, with no excess between them.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":29},{"key":"muslim","label":"مسلم","number":1588}]},{"num":5706,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( التمر بالتمر، والحنطة بالحنطة، والشعير بالشعير، والملح بالملح مثلًا بمثل، يدًا بيد، فمن زاد أو استزاد فقد أربى إلا ما اختلفت ألوانه ))."],"takhrij":"صحيح: رواه مسلم (١٥٨٨: ٨٣).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1588, no. 83).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Dates for dates, wheat for wheat, barley for barley, and salt for salt must be equal for equal and hand to hand. Whoever gives more or asks for more has committed usury, except when their types differ.”"]},"buhuth":{"ar":["قوله: (( ألوانه )) يعني أجناسه."],"en":["Its meaning: “Their types differ” means their different categories or kinds."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1588}]},{"num":5707,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( الذهب بالذهب وزنًا بوزن، مثلًا بمثل، والفضة بالفضة وزنًا بوزن، مثلًا بمثل، فمن زاد أو استزاد فهو ربا ))."],"takhrij":"صحيح: رواه مسلم (١٥٨٨: ٨٤).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1588, no. 84).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Gold for gold must be weight for weight, equal for equal, and silver for silver must be weight for weight, equal for equal. Whoever gives more or asks for more, that is usury.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1588}]},{"num":5708,"demo":false,"sanad":"","matn":["عن عثمان بن عفان أن رسول الله ﷺ قال: (( لا تبيعوا الدينار بالدينارين، ولا الدرهم بالدرهمين ))."],"takhrij":"صحيح: رواه مسلم (١٥٨٥).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1585).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Uthman ibn Affan reported that the Messenger of Allah ﷺ said: “Do not sell one dinar for two dinars, nor one dirham for two dirhams.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1585}]},{"num":5709,"demo":false,"sanad":"","matn":["عن مجاهد أنه قال: كنت مع عبد الله بن عمر، فجاءه صائغ، فقال له: يا أبا عبد الرحمن، إني أصوغ الذهب، ثم أبيع الشيء من ذلك بأكثر من وزنه، فأستفضل من ذلك قدر عمل يدي، فنهى عبد الله عن ذلك، فجعل الصائغ يردد عليه المسألة، وعبد الله ينهاه حتى انتهى إلى باب المسجد أو إلى دابة يريد أن يركبها، ثم قال عبد الله بن عمر: الدينار بالدينار، والدرهم بالدرهم، لا فضل بينهما، هذا عهد نبينا إلينا، وعهدنا إليكم."],"takhrij":"صحيح: رواه مالك (٣١).","grade":"صحيح","chapter_ar":"باب جريان ربا الفضل والنسيئة في الأصناف الربوية","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Malik (31).","chapter_en":"The applicability of usury of excess and usury of delay in usurious categories","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Mujahid reported: I was with Abdullah ibn Umar when a goldsmith came to him and said: “Abu Abd al-Rahman, I work gold, then I sell what I make for more than its weight, taking the extra amount in return for the work of my hand.” Abdullah forbade him from that. The goldsmith kept repeating the question, and Abdullah kept forbidding him until he reached the door of the mosque, or his riding animal which he intended to mount. Then Abdullah ibn Umar said: “A dinar for a dinar, and a dirham for a dirham, with no excess between them. This is the covenant of our Prophet ﷺ to us, and our covenant to you.”"]},"buhuth":{"ar":["وقول ابن عمر: (( هذا عهد نبينا إلينا )) وهو يريد أصحاب النبي ﷺ بعد ما ثبت له ذلك عن النبي ﷺ في حديث أبي سعيد الخدري وغيره، لأنه ثبت أن ابن عمر كان يقول مثل كلام ابن عباس في الصرف حتى حدثه أبو سعيد الخدري أن النبي ﷺ نهى عن بيع الذهب بالذهب إلا مثلًا بمثل، فأخذ به ورجع إليه."],"en":["Ibn Umar’s statement, “This is the covenant of our Prophet ﷺ to us,” means the Companions of the Prophet ﷺ, after this ruling had become established for him from the Prophet ﷺ through the hadith of Abu Saeed al-Khudri and others. It is established that Ibn Umar had once held the same view as Ibn Abbas regarding currency exchange, until Abu Saeed al-Khudri informed him that the Prophet ﷺ forbade selling gold for gold except equal for equal, so he accepted it and returned to that ruling."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":31}]},{"num":5710,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، وعن أبي هريرة أن رسول الله ﷺ استعمل رجلًا على خيبر، فجاءه بتمر جنيب، فقال له رسول الله ﷺ: (( أكل تمر خيبر هكذا؟ )) فقال: لا، والله يا رسول الله، إنا لنأخذ الصاع من هذا بالصاعين، والصاعين بالثلاثة. فقال رسول الله ﷺ: (( لا تفعل، بع الجمع بالدراهم، ثم ابتع بالدراهم جنيبًا ))."],"takhrij":"متفق عليه: رواه مالك (٢١) والبخاري (٢٢٠١)، ومسلم (١٥٩٣: ٩٥).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (21), al-Bukhari (2201), and Muslim (1593, no. 95).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Saeed al-Khudri and Abu Hurayrah reported that the Messenger of Allah ﷺ appointed a man over Khaybar, and he came with fine quality dates. The Messenger of Allah ﷺ said to him: “Are all the dates of Khaybar like this?” He said: “No, by Allah, Messenger of Allah ﷺ. We take one measure of this in exchange for two measures, and two for three.” The Messenger of Allah ﷺ said: “Do not do that. Sell the mixed dates for silver coins, then buy the fine dates with those coins.”"]},"buhuth":{"ar":["وفي رواية عنهما: أن رسول الله ﷺ بعث أخا بني عدي الأنصاري واستعمله على خيبر، فقدم بتمر جنيب، فقال له رسول الله ﷺ: (( أكل تمر خيبر هكذا؟ )) قال: لا والله يا رسول الله، إنا لنشتري الصاع بالصاعين من الجمع. فقال رسول الله ﷺ: (( لا تفعلوا، ولكن مثلًا بمثل، أو بيعوا هذا، واشتروا بثمنه من هذا، وكذلك الميزان ))."],"en":["In another narration in both collections: The Messenger of Allah ﷺ appointed a man from Banu Adi of the Ansar over Khaybar, and he came with fine dates. The Messenger of Allah ﷺ said to him: “Are all the dates of Khaybar like this?” He said: “No, by Allah, Messenger of Allah ﷺ. We buy one measure of these for two measures of mixed dates.” The Messenger of Allah ﷺ said: “Do not do that. Rather, equal for equal, or sell this and buy from that with its price, and the same applies to weight.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":21},{"key":"bukhari","label":"البخاري","number":2201},{"key":"muslim","label":"مسلم","number":1593}]},{"num":5711,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: كنا نرزق تمر الجمع - وهو الخلط من التمر - وكنا نبيع صاعين بصاع، فقال النبي ﷺ: (( لا صاعين بصاع، ولا درهمين بدرهم ))."],"takhrij":"متفق عليه: رواه البخاري (٢٠٨٠)، ومسلم (١٥٩٥).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2080) and Muslim (1595).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Saeed al-Khudri reported: We used to be given mixed dates, and we used to sell two measures for one measure. Then the Prophet ﷺ said: “Not two measures for one measure, and not two dirhams for one dirham.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2080},{"key":"muslim","label":"مسلم","number":1595}]},{"num":5712,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: جاء بلال إلى النبي ﷺ بتمر برني، فقال له النبي ﷺ: (( من أين هذا؟ )) قال بلال: كان عندي تمر رديء، فبعت منه صاعين بصاع لنطعم النبي ﷺ، فقال النبي ﷺ عند ذلك: (( أوه، أوه، عين الربا، لا تفعل، ولكن إذا أردت أن تشتري فبع التمر ببيع آخر، ثم اشتر به ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣١٢)، ومسلم (١٥٩٤).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2312) and Muslim (1594).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Saeed al-Khudri reported: Bilal brought some high-quality dates to the Prophet ﷺ, and the Prophet ﷺ said to him: “Where is this from?” Bilal said: “I had some poor-quality dates, so I sold two measures of them for one measure so that we could feed the Prophet ﷺ.” At that the Prophet ﷺ said: “Oh, oh, this is the essence of usury. Do not do that. Rather, when you want to buy, sell the dates in a separate sale, then buy with that price.”"]},"buhuth":{"ar":["قوله: (( أوه، أوه )) كلمة تقال عند التوجع."],"en":["Its meaning: “Oh, oh” is an expression said when showing pain or strong warning."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2312},{"key":"muslim","label":"مسلم","number":1594}]},{"num":5713,"demo":false,"sanad":"","matn":["عن أبي صالح أن رجلًا من أصحاب النبي ﷺ قال: يا رسول الله، إنا لا نجد الصيحاني، ولا العذق بجمع التمر حتى نزيدهم، فقال رسول الله ﷺ: (( بعه بالورق، ثم اشتر به ))."],"takhrij":"صحيح: رواه النسائي (٤٥٥٢).","grade":"صحيح","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Nasa’i (4552).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Abu Salih reported that a man from the Companions of the Prophet ﷺ said: “Messenger of Allah ﷺ, we cannot obtain al-Sayhani dates or al-‘Idhq dates for the same amount of mixed dates unless we give them extra.” So the Messenger of Allah ﷺ said: “Sell it for silver, then buy with that.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4552}]},{"num":5714,"demo":false,"sanad":"","matn":["عن بريدة بن الحصيب، أن النبي ﷺ اشتهى تمرًا، فأرسل بعض أزواجه - ولا أراها إلا أم سلمة - بصاعين من تمر، فأتوا بصاع من عجوة، فلما رآه النبي ﷺ أنكره، فقال: (( من أين لكم هذا؟ )) قالوا: بعثنا بصاعين فأتينا بصاع، فقال: (( ردوه، فلا حاجة لي فيه ))."],"takhrij":"حسن: رواه الطحاوي في شرح معاني الآثار (٤/٦٦)، والطبراني في الأوسط - مجمع البحرين (٢٠٢٦).","grade":"حسن","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi in Sharh Ma‘ani al-Athar (4/66), and al-Tabarani in al-Awsat as cited in Majma‘ al-Bahrayn (2026).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Buraydah ibn al-Husayb reported that the Prophet ﷺ desired some dates, so one of his wives, and I think it was Umm Salamah, sent out two measures of dates, and they brought back one measure of fine dates. When the Prophet ﷺ saw it, he disapproved and said: “Where did you get this?” They said: “We sent two measures and brought back one.” He said: “Return it. I have no need for it.”"]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرح_معانی_الاثار","label":"الطحاوي في شرح معاني الآثار","number":4},{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":2026}]},{"num":5715,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن رسول الله ﷺ أُتي بتمر ريان، فقال: (( أنى لكم هذا؟ )) فقالوا: كان عندنا تمر بعل، فبعنا صاعين بصاع، فقال رسول الله ﷺ: (( ردوه على صاحبه، فبيعوه بعين، ثم ابتاعوا التمر ))."],"takhrij":"حسن: رواه البزار (٦٨٨٦)، والطبراني في الأوسط - مجمع البحرين (٢٠٢٧).","grade":"حسن","chapter_ar":"باب النهي عن بيع التمر بالتمر أو الطعام بالطعام متفاضلًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar (6886), and al-Tabarani in al-Awsat as cited in Majma‘ al-Bahrayn (2027).","chapter_en":"The Prohibition of Selling Dates for Dates or Food for Food with Inequality","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ was brought well-watered, plump dates, and he said: “How did you get this?” They said: “We had ba‘l dates from palms that did not require ordinary irrigation, so we sold two measures for one measure.” The Messenger of Allah ﷺ said: “Return it to its owner. Sell the other dates for money, then buy the dates.”"]}},"tuhfa":{},"refs":[{"key":"البزار","label":"البزار","number":6886},{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":2027}]},{"num":5716,"demo":false,"sanad":"","matn":["عن معمر بن عبد الله أنه أرسل غلامه بصاع قمح، فقال: بعه، ثم اشتر به شعيرًا. فذهب الغلام، فأخذ صاعًا وزيادة بعض صاع، فلما جاء معمرًا أخبره بذلك، فقال له معمر: لم فعلت ذلك؟ انطلق، فرده، ولا تأخذن إلا مثلًا بمثل؛ فإني كنت أسمع رسول الله ﷺ يقول: (( الطعام بالطعام مثلًا بمثل )). قال: وكان طعامنا يومئذ الشعير. قيل له: فإنه ليس بمثله. قال: إني أخاف أن يضارع."],"takhrij":"صحيح: رواه مسلم (١٥٩٢).","grade":"صحيح","chapter_ar":"باب من يرى أن البر والشعير صنفًا واحدًا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1592).","chapter_en":"The View of Those Who Consider Wheat and Barley to Be One Category","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Ma‘mar ibn Abdullah sent his servant with one measure of wheat and said: “Sell it, then buy barley with it.” The servant went and took one measure plus some extra. When he came back and informed Ma‘mar, Ma‘mar said: “Why did you do that? Go and return it, and do not take except equal for equal, for I used to hear the Messenger of Allah ﷺ say: ‘Food for food must be equal for equal.’” He said: Their food at that time was barley. It was said to him: “But it is not the same as wheat.” He said: “I fear that it is similar enough to fall under the same ruling.”"]},"buhuth":{"ar":["قوله: (( يضارع )) أي يشابه. معناه: أخاف أن يكون في معنى المثل."],"en":["Its meaning: “Is similar” means resembles it. The meaning is: I fear that it may fall under the same legal meaning as its like."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1592}]},{"num":5717,"demo":false,"sanad":"","matn":["عن أسامة بن زيد أن رسول الله ﷺ قال: (( لا ربا فيما كان يدًا بيد ))."],"takhrij":"صحيح: رواه مسلم (١٥٩٦: ١٠٣).","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1596, no. 103).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Usamah ibn Zayd reported that the Messenger of Allah ﷺ said: “There is no usury when it is hand to hand.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1596}]},{"num":5718,"demo":false,"sanad":"","matn":["عن أبي صالح قال: سمعت أبا سعيد الخدري يقول: الدينار بالدينار والدرهم بالدرهم مثلًا بمثل، من زاد أو ازداد فقد أربى. فقلت له: إن ابن عباس يقول غير هذا. فقال: لقد لقيت ابن عباس، فقلتُ: أرأيت هذا الذي تقول أشيء سمعته من رسول اللّٰه ﷺ، أو وجدته في كتاب اللّٰه عز وجل؟ فقال: لم أسمعه من رسول اللّٰه ﷺ، ولم أجده في كتاب الله، ولكن حدثني أسامة بن زيد أن النبي ﷺ قال: (( الربا في النسيئة ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٧٨-٢١٧٩)، ومسلم (١٥٩٦: ١٠١). واللفظ لمسلم. وفي لفظ للبخاري قال: (( لا ربا إلا في النسيئة )).","grade":"متفق عليه","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2178–2179) and Muslim (1596, no. 101). The wording here is from Muslim. In a wording in al-Bukhari: “There is no usury except in delayed exchange.”","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu Salih reported: I heard Abu Saeed al-Khudri say, “A dinar for a dinar and a dirham for a dirham must be equal for equal. Whoever gives more or takes more has engaged in usury.” I said to him, “Ibn Abbas says something different from this.” He said, “I met Ibn Abbas and said to him: Is this statement of yours something you heard from the Messenger of Allah ﷺ, or something you found in the Book of Allah, the Mighty and Majestic? He replied: I did not hear it from the Messenger of Allah ﷺ, nor did I find it in the Book of Allah, but Usamah ibn Zayd told me that the Prophet ﷺ said: ‘Usury is in delayed exchange.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2178},{"key":"muslim","label":"مسلم","number":1596}]},{"num":5719,"demo":false,"sanad":"","matn":["عن عطاء بن أبي رباح أن أبا سعيد الخدري لقي ابن عباس، فقال له: أرأيت قولك في الصرف؟ أشيئًا سمعته من رسول اللّٰه ﷺ، أم شيئًا وجدته في كتاب اللّٰه عز وجل؟ فقال ابن عباس: كلا، لا أقول. أما رسول اللّٰه ﷺ فأنتم أعلم به مني، وأما كتاب اللّٰه فلا أعلمه، ولكن حدثني أسامة بن زيد أن رسول اللّٰه ﷺ قال: (( ألا إنما الربا في النسيئة ))."],"takhrij":"صحيح: رواه مسلم (١٥٩٦: ١٠٤).","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1596, no. 104).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Ata ibn Abi Rabah reported that Abu Saeed al-Khudri met Ibn Abbas and said to him: “This opinion of yours regarding currency exchange, is it something you heard from the Messenger of Allah ﷺ, or something you found in the Book of Allah, the Mighty and Majestic?” Ibn Abbas replied: “Neither. I do not claim that. As for the Messenger of Allah ﷺ, you know more about him than I do, and as for the Book of Allah, I do not know it there. But Usamah ibn Zayd told me that the Messenger of Allah ﷺ said: ‘Indeed, usury is only in delayed exchange.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1596}]},{"num":5720,"demo":false,"sanad":"","matn":["عن أبي نضرة قال: سألت ابن عمر وابن عباس عن الصرف، فلم يريا به بأسًا، فإني لقاعد عند أبي سعيد الخدري، فسألته عن الصرف، فقال: ما زاد فهو ربا. فأنكرت ذلك لقولهما، فقال: لا أحدثك إلا ما سمعت رسول اللّٰه ﷺ، جاءه صاحب نخله بصاع من تمر طيب، وكان تمر النبي ﷺ هذا اللون. فقال له النبي ﷺ: (( أنى لك هذا؟ )). قال: انطلقت بصاعين، فاشتريت به هذا الصاع، فإن سعر هذا في السوق كذا، وسعر هذا كذا. فقال رسول اللّٰه ﷺ: (( ويلك أربيت! إذا أردت ذلك فبع تمرك بسلعة، ثم اشتر بسلعتك أي تمر شئت )). قال أبو سعيد: فالتمر بالتمر أحق أن يكون ربا أم الفضة بالفضة؟ قال فأتيت ابن عمر بعد، فنهاني، ولم آت ابن عباس. قال: فحدثني أبو الصهباء أنه سأل ابن عباس عنه بمكة، فكرهه."],"takhrij":"صحيح: رواه مسلم (١٥٩٤: ١٠٠).","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1594, no. 100).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu Nadrah reported: I asked Ibn Umar and Ibn Abbas about currency exchange, and they saw no problem with it. Then while I was sitting with Abu Saeed al-Khudri, I asked him about exchange, and he said, “Any excess is usury.” I found that strange because of what those two had said. He replied, “I will tell you only what I heard from the Messenger of Allah ﷺ. The owner of a date orchard came to him with one measure of fine dates, and the dates of the Prophet ﷺ were not of that kind. So the Prophet ﷺ said to him: ‘How did you get this?’ He said: I went with two measures and bought this one measure, because the price of this kind in the market is such-and-such, and the price of that kind is such-and-such. The Messenger of Allah ﷺ said: ‘Woe to you, you have dealt in usury! If you want that, then sell your dates for another commodity, then buy whichever dates you wish with that commodity.’” Abu Saeed then said: “If dates for dates are usury, then silver for silver is even more deserving of being called usury.” So afterwards I went to Ibn Umar, and he forbade me from it, and I did not go to Ibn Abbas. Then Abu al-Sahba told me that he asked Ibn Abbas about it in Makkah, and he also disliked it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1594}]},{"num":5721,"demo":false,"sanad":"","matn":["عن أبي نضرة قال: سألت ابن عباس عن الصرف، فقال: أيدًا بيد؟ قلت: نعم. قال: فلا بأس به. فأخبرت أبا سعيد، فقلت: إني سألت ابن عباس عن الصرف، فقال: أيدًا بيد؟ قلت: نعم. قال: فلا بأس به. قال: أو قال ذلك؟! إنا سنكتب إليه فلا يفتيكموه. قال: فو الله لقد جاء بعض فتيان رسول اللّٰه ﷺ بتمر، فأنكره، فقال: (( كأن هذا ليس من تمر أرضنا )). قال: كان في تمر أرضنا - أو في تمرنا - العام بعض الشيء، فأخذت هذا، وزدت بعض الزيادة. فقال: (( أضعفت؟ أربيت؟ لا تقربن هذا، إذا رابك من تمرك شيء فبعه، ثم اشتر الذي تريد من التمر ))."],"takhrij":"صحيح: رواه مسلم (١٥٩٤: ٩٩).","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1594, no. 99).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu Nadrah reported: I asked Ibn Abbas about exchange, and he said, “Is it hand to hand?” I said, “Yes.” He said, “Then there is no problem with it.” I informed Abu Saeed and said, “I asked Ibn Abbas about exchange, and he said: Is it hand to hand? I said yes. He said: Then there is no problem with it.” Abu Saeed said, “Did he really say that? We will write to him so that he does not continue giving you that ruling.” Then he said: “By Allah, one of the young men of the Messenger of Allah ﷺ once brought dates, and he disapproved of them and said: ‘It seems this is not from the dates of our land.’ The man said: There was something wrong with our land’s dates this year, so I took these and added some extra. The Prophet ﷺ said: ‘You doubled it? You have engaged in usury? Do not come near this. If something about your dates troubles you, then sell them, and then buy whatever kind of dates you want.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1594}]},{"num":5722,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر أن أبا سعيد الخدري حدثه مثل ذلك حديثًا عن رسول اللّٰه ﷺ، فلقيه عبد اللّٰه بن عمر، فقال: يا أبا سعيد، ما هذا الذي تحدث عن رسول اللّٰه ﷺ؟ فقال أبو سعيد: في الصرف؟ سمعت رسول اللّٰه ﷺ يقول: (( الذهب بالذهب مثلًا بمثل، والورق بالورق مثلًا بمثل ))."],"takhrij":"صحيح: رواه البخاري (٢١٧٦).","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2176).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abdullah ibn Umar reported that Abu Saeed al-Khudri narrated to him a similar hadith from the Messenger of Allah ﷺ. Then Abdullah ibn Umar met him and said: “Abu Saeed, what is this that you narrate from the Messenger of Allah ﷺ?” Abu Saeed replied: “About exchange? I heard the Messenger of Allah ﷺ say: ‘Gold for gold must be equal for equal, and silver for silver must be equal for equal.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2176}]},{"num":5723,"demo":false,"sanad":"","matn":["عن أبي الجوزاء قال: سمعت ابن عباس يفتي بالصرف. قال: فأفتيت به زمانًا. قال: ثم لقيته، فرجع عنه. قال: فقلت له: ولِمَ؟ فقال: إنما هو رأي رأيته. حدثني أبو سعيد الخدري أن رسول اللّٰه ﷺ نهى عنه."],"takhrij":"صحيح: رواه الإمام أحمد (١١٤٤٧). ورواه أيضًا (١١٤٧٩) وجاء فيه: سألت ابن عباس عن الصرف يدًا بيد، فقال: لا بأس بذلك، اثنين بواحد، أكثر من ذلك وأقل. قال: ثم حججت مرة أخرى، والشيخ حي، فأتيته، فسألته عن الصرف، فقال: وزنًا بوزن. قال: فقلت: إنك قد أفتيتني اثنين بواحد، فلم أزل أفتي به منذ أفتيتني. فقال: إن ذلك كان عن رأيي، وهذا أبو سعيد الخدري يحدث عن رسول اللّٰه ﷺ، فتركت رأيي إلى حديث رسول اللّٰه ﷺ. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Imam Ahmad (11447). Ahmad also narrated it (11479) with the wording: “I asked Ibn Abbas about hand-to-hand exchange, and he said: there is no problem with two for one, more than that or less. Then I performed Hajj another time while the shaykh was still alive, and I came to him and asked him about exchange, and he said: weight for weight. I said: You had given me the ruling of two for one, and I kept giving verdicts with it since you told me that. He said: That was from my own opinion, but now Abu Saeed al-Khudri narrates from the Messenger of Allah ﷺ, so I abandoned my opinion for the hadith of the Messenger of Allah ﷺ.” Its chain is authentic.","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu al-Jawza reported: I heard Ibn Abbas giving legal rulings allowing currency exchange in that way, and I gave verdicts with it for some time. Then I met him again, and he had gone back from that view. I said to him: “Why?” He replied: “It was only an opinion I had formed. Abu Saeed al-Khudri informed me that the Messenger of Allah ﷺ forbade it.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":11447},{"key":"ورواہ_ایضا","label":". ورواه أيضًا","number":11479},{"key":"ahmad","label":"مسند الإمام أحمد","number":11447,"n":11447}]},{"num":5724,"demo":false,"sanad":"","matn":["عن أبي الزبير المكي قال: سمعت أبا أسيد الساعدي وابن عباس يفتي الدينار بالدينارين، فقال له أبو أسيد الساعدي وأغلظ له، قال: فقال ابن عباس: ما كنت أظن أن أحدًا يعرف قرابتي من رسول اللّٰه ﷺ يقول لي مثل هذا يا أبا أسيد. فقال أبو أسيد: أشهد لسمعت من رسول اللّٰه ﷺ يقول: (( الدينار بالدينار، والدرهم بالدرهم، وصاع حنطة بصاع حنطة، وصاع شعير بصاع شعير، وصاع ملح بصاع ملح، لا فضل بينهما في شيء من ذلك )). فقال ابن عباس: إنما هذا شيء كنت أقوله ولم أسمع فيه بشيء."],"takhrij":"حسن: رواه ابن أبي خيثمة في التاريخ الكبير (٣٤٤٤)، والطبراني في الكبير (١٩/٢٦٨)، والحاكم (٢١٩٣).","grade":"حسن","chapter_ar":"باب من قال: إنما الربا في النسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Khaythamah in al-Tarikh al-Kabir (3444), al-Tabarani in al-Kabir (19/268), and al-Hakim (2193).","chapter_en":"Those Who Said That Usury Applies Only in Delayed Exchange","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["Abu al-Zubayr al-Makki reported: I heard Abu Usayd al-Saidi while Ibn Abbas was giving the ruling that one dinar may be exchanged for two dinars. Abu Usayd spoke sternly to him. Ibn Abbas then said: “I never expected that anyone who knew my closeness to the Messenger of Allah ﷺ would speak to me like this, Abu Usayd.” Abu Usayd said: “I testify that I heard from the Messenger of Allah ﷺ: ‘A dinar for a dinar, a dirham for a dirham, one measure of wheat for one measure of wheat, one measure of barley for one measure of barley, and one measure of salt for one measure of salt, with no excess in any of that.’” So Ibn Abbas said: “This was only something I used to say, and I had heard nothing on it.”"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_خیثمہ/التاریخ_الکبیر","label":"ابن أبي خيثمة في التاريخ الكبير","number":3444},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":19},{"key":"hakim","label":"المستدرك على الصحيحين","number":2193,"n":2186}]},{"num":5725,"demo":false,"sanad":"","matn":["عن أبي المنهال قال: سألت البراء بن عازب وزيد بن أرقم عن الصرف، وكل واحد منهما يقول: هذا خير مني، فكلاهما يقول: (( نهى رسول اللّٰه ﷺ عن بيع الذهب بالورق دينًا ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٨٠، ٢١٨١)، ومسلم (١٥٨٩).","grade":"متفق عليه","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2180, 2181) and Muslim (1589).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal reported: I asked al-Bara ibn Azib and Zayd ibn Arqam about exchange, and each one of them said, “This one is better than me.” Yet both of them said: “The Messenger of Allah ﷺ forbade selling gold for silver on delayed payment.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2180},{"key":"muslim","label":"مسلم","number":1589}]},{"num":5726,"demo":false,"sanad":"","matn":["عن أبي المنهال عبد الرحمن بن مطعم قال: باع شريك لي دراهم في السوق نسيئة، قلت: سبحان الله! أيصلح هذا؟ فقال: سبحان الله! والله لقد بعتها في السوق فما عابه أحد، فسألت البراء بن عازب، فقال: قدم النبي ﷺ ونحن نتبايع هذا البيع، فقال: (( ما كان يدًا بيد فليس به بأس، وما كان نسيئة فلا يصلح )). وقال: ائت زيد بن أرقم، فاسأله؛ فإنه كان أعظمنا تجارة، فسألت زيد بن أرقم، فقال مثله."],"takhrij":"متفق عليه: رواه البخاري (٣٩٣٩، ٣٩٤٠)، ومسلم (١٥٨٩). ولفظهما سواء. ويحمل هذا على بيع الجنسين.","grade":"متفق عليه","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (3939, 3940) and Muslim (1589). Their wording is nearly the same. This is understood to refer to exchanging two different categories.","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal Abd al-Rahman ibn Mutim reported: A partner of mine sold silver coins in the market on delayed payment. I said: “Glory be to Allah, can this be valid?” He said: “Glory be to Allah, by Allah, I sold it in the market and no one criticized it.” So I asked al-Bara ibn Azib, and he said: “The Prophet ﷺ came to Madinah while we were doing this kind of transaction, and he said: ‘What is hand to hand is permissible, but what is delayed is not valid.’” Then he said: “Go to Zayd ibn Arqam and ask him, for he was greater than us in trade.” So I asked Zayd ibn Arqam, and he said the same."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3939},{"key":"muslim","label":"مسلم","number":1589}]},{"num":5727,"demo":false,"sanad":"","matn":["عن أبي المنهال قال: كنت أتجر في الصرف، فسألت البراء بن عازب، وزيد بن أرقم عن الصرف، فقالا: كنا تاجرين على عهد رسول اللّٰه ﷺ، فسألنا رسول اللّٰه ﷺ عن الصرف، فقال: (( إن كان يدًا بيد فلا بأس، وإن كان نَساءً فلا يصلح ))."],"takhrij":"صحيح: رواه البخاري (٢٠٦٠، ٢٠٦١).","grade":"صحيح","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2060, 2061).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal reported: I used to trade in currency exchange, so I asked al-Bara ibn Azib and Zayd ibn Arqam about exchange. They said: “We were traders in the time of the Messenger of Allah ﷺ, so we asked the Messenger of Allah ﷺ about exchange, and he said: ‘If it is hand to hand, there is no problem, but if it is delayed, it is not valid.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2060}]},{"num":5728,"demo":false,"sanad":"","matn":["عن أبي المنهال قال: إن زيد بن أرقم والبراء بن عازب كانا شريكين، فاشتريا فضة بنقد ونسيئة، فبلغ ذلك النبي ﷺ، فأمرهما أن ما كان بنقد فأجيزوه، وما كان نسيئة فردوه."],"takhrij":"صحيح: رواه الإمام أحمد (١٩٣٠٧).","grade":"صحيح","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Imam Ahmad (19307).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["Abu al-Minhal reported that Zayd ibn Arqam and al-Bara ibn Azib were partners, and they bought silver both for immediate payment and on delayed payment. That reached the Prophet ﷺ, so he ordered them to approve what had been done with immediate payment, and to return what had been done on delayed payment."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":19307},{"key":"ahmad","label":"مسند الإمام أحمد","number":19307,"n":19307}]},{"num":5729,"demo":false,"sanad":"","matn":["عن أبي هريرة، وأبي سعيد، وجابر - اثنين من هؤلاء الثلاثة - أن النبي ﷺ نهى عن الصرف."],"takhrij":"صحيح: رواه أحمد (٩٦٣٨). وقوله: (( نهى عن الصرف )) أي نسيئة أو زيادة مع اتحاد الجنسين.","grade":"صحيح","chapter_ar":"باب جواز بيع الذهب بالفضة أو العكس إذا كان يدًا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Ahmad (9638).","chapter_en":"The Permissibility of Selling Gold for Silver, or Silver for Gold, If It Is Hand to Hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":15,"content":{"translation":{"en":["It is reported from Abu Hurayrah, Abu Saeed, and Jabir, from two of these three, that the Prophet ﷺ forbade exchange."]},"buhuth":{"en":["Explanation:","His saying, “He forbade exchange,” means exchange with delay, or with increase when the two items are of the same kind."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":9638,"n":9638}]},{"num":5730,"demo":false,"sanad":"","matn":["عن فضالة بن عبيد الأنصاري قال: أتي رسول اللّٰه ﷺ - وهو بخيبر - بقلادة فيها خرز وذهب، وهي من المغانم تباع، فأمر رسول اللّٰه ﷺ بالذهب الذي في القلادة، فنزع وحده، ثم قال لهم رسول اللّٰه ﷺ: (( الذهب بالذهب وزنًا بوزن ))."],"takhrij":"صحيح: رواه مسلم (١٥٩١). ورواه من وجه آخر عن فضالة بن عبيد قال: اشتريت يوم خيبر قلادة باثني عشر دينارًا، فيها ذهب وخرز، ففصلتها فوجدت فيها أكثر من اثني عشر دينارًا، فذكرت ذلك للنبي ﷺ، فقال: (( لا تباع حتى تفصل )).","grade":"صحيح","chapter_ar":"باب النهي عن بيع القلادة فيها ذهب وخرز","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1591).","chapter_en":"The Prohibition of Selling a Necklace That Contains Gold and Beads","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":16,"content":{"translation":{"en":["Fadalah ibn Ubayd al-Ansari reported: A necklace containing beads and gold, from the spoils of war, was brought to the Messenger of Allah ﷺ at Khaybar to be sold. The Messenger of Allah ﷺ ordered that the gold in the necklace be removed and separated, then he said to them: “Gold for gold must be weight for weight.”"]},"buhuth":{"en":["In another narration from Fadalah ibn Ubayd: “On the day of Khaybar I bought a necklace for twelve dinars. It contained gold and beads. I separated it and found that the gold in it was worth more than twelve dinars. I mentioned that to the Prophet ﷺ, and he said: ‘It should not be sold until it is separated.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1591}]},{"num":5731,"demo":false,"sanad":"","matn":["عن حنش أنه قال: كنا مع فضالة بن عبيد في غزوة، فطارت لي ولأصحابي قلادة فيها ذهب وورق وجوهر، فأردت أن أشتريها، فسألت فضالة بن عبيد، فقال: انزع ذهبها، فاجعل في كفة، واجعل ذهبك في كفة، ثم لا تأخذن إلا مثلًا بمثل؛ فإني سمعت رسول اللّٰه ﷺ يقول: (( من كان يؤمن بالله واليوم الآخر فلا يأخذن إلا مثلًا بمثل ))."],"takhrij":"صحيح: رواه مسلم (١٥٩١: ٩٢).","grade":"صحيح","chapter_ar":"باب النهي عن بيع القلادة فيها ذهب وخرز","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1591, no. 92).","chapter_en":"The Prohibition of Selling a Necklace That Contains Gold and Beads","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":16,"content":{"translation":{"en":["Hanash reported: We were with Fadalah ibn Ubayd on a military expedition when a necklace containing gold, silver, and jewels was allotted to me and my companions from the booty. I wanted to buy it, so I asked Fadalah ibn Ubayd. He said: “Remove its gold, put it in one scale, and put your gold in another scale, then do not take except equal for equal, for I heard the Messenger of Allah ﷺ say: ‘Whoever believes in Allah and the Last Day must not take except equal for equal.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1591}]},{"num":5732,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: خطب النبي ﷺ يوم عرفة ببطن الوادي، فمما قال: (( وربا الجاهلية موضوع، وأول ربا أضع ربانا ربا عباس بن عبد المطلب، فإنه موضوع كله ))."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب وضع الربا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1218).","chapter_en":"The Cancellation of Usury","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":17,"content":{"translation":{"en":["Jabir ibn Abdullah reported: The Prophet ﷺ delivered a sermon on the Day of Arafah in the valley, and among what he said was: “The usury of the pre-Islamic period is abolished, and the first usury that I abolish is our usury, the usury of al-Abbas ibn Abd al-Muttalib. It is all abolished.”"]},"buhuth":{"ar":["ومعنى وضع الربا: أن يأخذ رأس المال، ويتنازل عن أخذ الربا إن كانت المعاملة بينه وبين شخص، فلا يأخذ منه زيادة على رأس المال، وإن كانت بينه وبين المؤسسات التجارية فيأخذها، ولا ينفقها على نفسه وأولاده، وإنما ينفقها على المصلحة العامة، أو على الكفار والمشركين الذين يرجى منهم الخير تأليفًا لقلوبهم."],"en":["The meaning of cancelling usury is that a person takes back only the principal amount and gives up the usurious increase if the deal was between him and another individual, so he does not take more than the original capital. If the matter is with commercial institutions, then he may take it but should not spend it on himself or his children. Rather, he should direct it to public welfare or to non-Muslims whose hearts may be inclined toward good."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":5733,"demo":false,"sanad":"","matn":["عن عمرو بن الأحوص قال: سمعت رسول اللّٰه ﷺ في حجة الوداع يقول: (( ألا إن كل ربا من ربا الجاهلية موضوع، لكم رؤوس أموالكم لا تظلمون، ولا تظلمون ))."],"takhrij":"حسن: رواه أبو داود (٣٣٣٤)، والترمذي (٣٠٨٧)، وأحمد (١٥٥٠٧). قال الترمذي: حسن صحيح.","grade":"حسن","chapter_ar":"باب وضع الربا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3334), al-Tirmidhi (3087), and Ahmad (15507). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"The Cancellation of Usury","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":17,"content":{"translation":{"en":["Amr ibn al-Ahwas reported: I heard the Messenger of Allah ﷺ say during the Farewell Pilgrimage: “Indeed, every form of usury from the pre-Islamic period is abolished. You shall have your principal sums. You will neither wrong nor be wronged.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3334},{"key":"tirmidhi","label":"الترمذي","number":3087},{"key":"ahmad","label":"مسند الإمام أحمد","number":15507,"n":15507}]},{"num":5734,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر أن رسول اللّٰه ﷺ نهى عن المزابنة. والمزابنة بيع الثمر بالتمر كيلًا، وبيع الكرم بالزبيب كيلًا."],"takhrij":"متفق عليه: رواه مالك (٢٣) والبخاري (٢١٨٥)، ومسلم (١٥٤٢). ورواه مسلم من وجه آخر: (( نهى رسول اللّٰه ﷺ عن المزابنة. والمزابنة بيع ثمر النخل بالتمر كيلًا، وبيع الزبيب بالعنب كيلًا، وعلى كل ثمر بخرصه )).","grade":"متفق عليه","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (23), al-Bukhari (2185), and Muslim (1542).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ forbade al-muzabanah. Al-muzabanah is selling fresh fruit for dried dates by measure, and selling grapes on the vine for raisins by measure."]},"buhuth":{"ar":["قوله: (( المزابنة )) مفاعلة من الزبن - بفتح الزاي، وسكون الموحدة -، وهو الدفع الشديد، ومنه سميت الحرب الزبون لشدة الدفع فيها. وقيل للبيع المخصوص المزابنة؛ لأن كل واحد من المتبايعين يدفع صاحبه عن حقه."],"en":["In another narration by Muslim: “The Messenger of Allah ﷺ forbade al-muzabanah. Al-muzabanah is selling the fruit of date palms for dates by measure, and selling raisins for grapes by measure, and every fruit according to estimation.”","The word muzabanah comes from a root meaning forceful pushing. War is sometimes described with this root because of the force and struggle in it. This type of sale was called muzabanah because each side, in a sense, pushes the other away from his proper right."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":23},{"key":"bukhari","label":"البخاري","number":2185},{"key":"muslim","label":"مسلم","number":1542}]},{"num":5735,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري أن رسول اللّٰه ﷺ نهى عن المزابنة والمحاقلة. والمزابنة اشتراء الثمر بالتمر في رؤوس النخل. والمحاقلة كراء الأرض بالحنطة."],"takhrij":"متفق عليه: رواه مالك (٢٤) والبخاري (٢١٨٦)، ومسلم (١٥٤٦).","grade":"متفق عليه","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (24), al-Bukhari (2186), and Muslim (1546).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abu Saeed al-Khudri reported that the Messenger of Allah ﷺ forbade al-muzabanah and al-muhaqalah. Al-muzabanah is buying fruit on the trees in exchange for dried dates. Al-muhaqalah is renting land in exchange for wheat."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":24},{"key":"bukhari","label":"البخاري","number":2186},{"key":"muslim","label":"مسلم","number":1546}]},{"num":5736,"demo":false,"sanad":"","matn":["عن ابن عباس قال: نهى النبي ﷺ عن المحاقلة، والمزابنة."],"takhrij":"صحيح: رواه البخاري (٢١٨٧).","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2187).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas reported: The Prophet ﷺ forbade al-muhaqalah and al-muzabanah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2187}]},{"num":5737,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أنه سمع رسول اللّٰه ﷺ ينهى عن المزابنة والحقول، فقال جابر بن عبد الله: المزابنة الثمر بالتمر، والحقول كراء الأرض."],"takhrij":"صحيح: رواه مسلم (١٥٣٦: ١٠٣).","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536, no. 103).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah reported that he heard the Messenger of Allah ﷺ forbid al-muzabanah and al-haqul. Jabir said: al-muzabanah is fruit for dates, and al-haqul means renting land."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1536}]},{"num":5738,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أن رسول اللّٰه ﷺ نهى عن المحاقلة، والمزابنة، والمخابرة، وأن تُشترى النخل حتى تُشْقِه - والإشقاه أن يحمر، أو يصفر، أو يؤكل منه شيء -. والمحاقلة أن يباع الحقل بكيل من الطعام معلوم. والمزابنة أن يباع النخل بأوساق من التمر. والمخابرة الثلث والربع وأشباه ذلك."],"takhrij":"صحيح: رواه مسلم (١٥٣٦: ٨٣).","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536, no. 83).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Jabir ibn Abdullah reported that the Messenger of Allah ﷺ forbade al-muhaqalah, al-muzabanah, and al-mukhabarah, and that palm trees should not be sold until their fruit becomes sound. Becoming sound means that it turns red or yellow, or that some of it is edible. Al-muhaqalah is selling a field for a known measured amount of food. Al-muzabanah is selling date palms for fixed measures of dates. Al-mukhabarah is an arrangement involving one-third, one-fourth, and similar shares."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1536}]},{"num":5739,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ عن المحاقلة والمزابنة."],"takhrij":"صحيح: رواه مسلم (١٥٤٥).","grade":"صحيح","chapter_ar":"باب في النهي عن بيع المزابنة والمحاقلة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1545).","chapter_en":"The Prohibition of al-Muzabanah and al-Muhaqalah","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported: The Messenger of Allah ﷺ forbade al-muhaqalah and al-muzabanah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1545}]},{"num":5740,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال:","نهى رسول الله ﷺ عن المحاقلة والمزابنة."],"takhrij":"حسن: رواه أبو داود (٣٤٠٠)، وابن ماجه (٢٢٦٧)، والنسائي (٣٨٩٠).","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3400), Ibn Mājah (2267), and al-Nasāʾī (3890).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Rāfiʿ ibn Khadīj reported:","The Messenger of Allah ﷺ prohibited muḥāqalah and muzābanah."]},"buhuth":{"ar":["وزادوا بعد قوله: نهى رسول الله ﷺ عن المحاقلة والمزابنة:","«إِنَّمَا يَزْرَعُ ثَلَاثَةٌ: رَجُلٌ لَهُ أَرْضٌ فَهُوَ يَزْرَعُهَا، وَرَجُلٌ مُنِحَ أَرْضًا فَهُوَ يَزْرَعُ مَا مُنِحَ، وَرَجُلٌ اسْتَكْرَى أَرْضًا بِذَهَبٍ أَوْ فِضَّةٍ».","والصحيح أنه تفسير من سعيد بن المسيب."],"en":["They also added after the statement that the Messenger of Allah ﷺ prohibited muḥāqalah and muzābanah:","“Only three types of people cultivate land: a man who owns land and cultivates it; a man who has been granted land and cultivates what he was granted; and a man who rents land for gold or silver.”","The correct view is that this statement is an explanation from Saʿīd ibn al-Musayyib."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3400},{"key":"ibnmajah","label":"ابن ماجه","number":2267},{"key":"nasai","label":"النسائي","number":3890}]},{"num":5741,"demo":false,"sanad":"","matn":["عن زيد بن ثابت أن رسول اللّٰه ﷺ أرخص لصاحب العرية أن يبيعها بخرصها."],"takhrij":"متفق عليه: رواه مالك (١٤) والبخاري (٢١٨٨) ومسلم (٦٠ : ١٥٣٩)، وزاد مسلم: ((من التمر)).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (14), al-Bukhari (2188), and Muslim (1539/60). Muslim added: “for dates.”","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Zayd ibn Thabit reported that the Messenger of Allah ﷺ gave permission to the owner of an ariyah to sell it according to its estimated measure."]},"buhuth":{"ar":["ورواه البخاري (٢١٩٢) من وجه آخر بلفظ: ((أن رسول اللّٰه ﷺ رخص في العرايا أن تباع بخرصها كيلاً)).","قال موسى بن عقبة: ((والعرايا نخلات معلومات، تأتيها، فتشتريها))."],"en":["Al-Bukhari also narrated through another chain with the wording: “The Messenger of Allah ﷺ allowed the araya to be sold according to their estimated measure by dry measure.”","Musa ibn ‘Uqbah said: “Araya are specific palm trees; one comes to buy them.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14},{"key":"bukhari","label":"البخاري","number":2188},{"key":"muslim","label":"مسلم","number":60}]},{"num":5742,"demo":false,"sanad":"","matn":["عن زيد بن ثابت أن رسول اللّٰه ﷺ رخص في بيع العرايا أن تباع بخرصها، ولم يرخص في غير ذلك."],"takhrij":"صحيح: رواه الإمام أحمد (٢١٥٨١)، والدارمي (٢٦٠٠)، وابن حبان (٥٠٠٩).","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (21581), al-Darimi (2600), and Ibn Hibban (5009).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Zayd ibn Thabit reported that the Messenger of Allah ﷺ permitted the sale of the araya according to estimate, and he did not permit that in anything else."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":21581},{"key":"darimi","label":"الدارمي","number":2600},{"key":"ahmad","label":"مسند الإمام أحمد","number":21581,"n":21581},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5621,"n":5617}]},{"num":5743,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: نهى رسول اللّٰه ﷺ عن المحاقلة، والمزابنة، والمعاومة، والمخابرة، وعن الثنيا، ورخص في العرايا."],"takhrij":"صحيح: رواه مسلم (٨٥ : ١٥٣٦).","grade":"صحيح","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1536/85).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, the sale of fresh produce for dried produce by estimate, multi-year fruit sales, sharecropping, and undefined exceptions in a sale, but he allowed the araya."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":85}]},{"num":5744,"demo":false,"sanad":"","matn":["عن سهل بن أبي حثمة أن رسول اللّٰه ﷺ نهى عن بيع الثمر بالتمر، وقال: ((ذلك الربا، تلك المزابنة)). إلا أنه رخص في بيع العرية، النخلة والنخلتين يأخذها أهل البيت بخرصها تمراً، يأكلونها رطباً."],"takhrij":"متفق عليه: رواه البخاري (٢١٩١)، ومسلم (٦٧ : ١٥٤٠). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2191) and Muslim (1540/67). The wording is Muslim’s.","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ forbade selling fresh dates for dried dates and said: “That is usury; that is the forbidden exchange.” But he permitted the sale of an ariyah: one or two palm trees whose estimated amount is taken in dried dates by a household so they may eat them fresh."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2191},{"key":"muslim","label":"مسلم","number":67}]},{"num":5745,"demo":false,"sanad":"","matn":["عن رافع بن خديج، وسهل بن أبي حثمة حدثا أن رسول اللّٰه ﷺ نهى عن المزابنة، بيع الثمر بالتمر إلا أصحاب العرايا، فإنه أذن لهم."],"takhrij":"متفق عليه: رواه البخاري في المساقاة (٢٣٨٤ ،٢٣٨٣)، ومسلم في البيوع (٧٠ : ١٥٤٠).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الرخصة في بيع العرايا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari in the chapter of irrigation-share contracts (2383, 2384) and Muslim in sales (1540/70).","chapter_en":"What has come regarding the concession for selling the araya","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":20,"content":{"translation":{"en":["Rafi‘ ibn Khadij and Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ forbade the sale of fruit for dried dates, except for the people of the araya, for he gave them permission."]},"buhuth":{"ar":["وقوله: ((العرية))، و((العرايا)) هي بيع ثمر نخلات معلومات بعد بدو الصلاح فيها خرصاً بالتمر الموضوع على وجه الأرض كيلاً، استثناه الشارع من المزابنة لحاجة الناس إلى ذلك. وسميت عرية؛ لأنها عريت من جملة التحريم، أي خرجت. فعيلة بمعنى فاعلة. ثم إن صور العرية كثيرة، وإليكم بعض ما ذكره الحافظ ابن حجر في الفتح:","منها: أن يقول الرجل لصاحب حائط: بعني ثمر نخلات بأعيانها بخرصها من التمر. فيخرصها، ويبيعه، ويقبض منه التمر، ويسلم إليه النخلات بالتخلية.","ومنها: أن يهب صاحب الحائط لرجل نخلات أو ثمر نخلات معلومة من حائطه، ثم يتضرر بدخوله عليه، فيخرصها، ويشتري منه رطبها بقدر خرصه بتمر يعجله له.","ومنها: أن يبيع الرجل تمر حائطه بعد بدو صلاحه، ويستثني منه نخلات معلومة يبقيها لنفسه ولعياله، وهي التي عفي له عن خرصها في الصدقة، فرخص لأهل الحاجة الذين لا نقد لهم، وعندهم فضول من تمر قوتهم أن يبتاعوا بذلك التمر من رطب تلك النخلات بخرصها."],"en":["His statement “ariyah” and “araya” refers to the sale of the fruit of specific palm trees, after its ripeness has appeared, estimated against dried dates measured on the ground. The Lawgiver exempted it from the general prohibition because people needed it. It is called ariyah because it was excluded from the general ruling of prohibition. The word carries the sense of “set apart.”","The forms of this transaction are many. Among what Ibn Hajar mentioned in al-Fath are:","One form is that a man says to the owner of an orchard: Sell me the fruit of certain named palm trees for an estimated amount of dried dates. The amount is estimated, the sale is concluded, the dried dates are received from him, and the trees are handed over by making them available.","Another form is that the orchard owner gifts a man certain palm trees, or the fruit of certain palm trees, from his orchard, then becomes inconvenienced by his repeated entry. So he estimates them and buys back their fresh fruit for the amount of dried dates corresponding to the estimate, paid immediately.","Another form is that a man sells the dates of his orchard after ripeness has appeared, but excludes certain known palm trees for himself and his family. These are the ones exempted from estimation in charity. So needy people who have no cash, but do have surplus dried dates for food, were allowed to buy the fresh fruit of those trees with dried dates according to estimate."]}},"tuhfa":{},"refs":[{"key":"bukhari/المساقاہ","label":"البخاري في المساقاة","number":2384},{"key":"muslim/البیوع","label":"مسلم في البيوع","number":70}]},{"num":5746,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ أرخص في بيع العرايا بخرصها فيما دون خمسة أوسق، أو في خمسة أوسق."],"takhrij":"متفق عليه: رواه مالك (١٤) والبخاري (٢١٩٠)، ومسلم (١٥٤١).","grade":"متفق عليه","chapter_ar":"باب جواز العرايا فيما دون خمسة أوسق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (14), al-Bukhari (2190), and Muslim (1541).","chapter_en":"The permissibility of araya in amounts under five wasqs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":21,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ permitted the sale of the araya according to estimate in amounts less than five wasqs, or up to five wasqs."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14},{"key":"bukhari","label":"البخاري","number":2190},{"key":"muslim","label":"مسلم","number":1541}]},{"num":5747,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه الأنصاري قال: سمعت رسول اللّٰه ﷺ حين أذن لأصحاب العرايا أن يبيعوها بخرصها يقول: ((الوسق، والوسقين، والثلاثة، والأربعة))."],"takhrij":"حسن: رواه الإمام أحمد (١٤٨٦٨)، وأبو يعلى (١٧٨٠)، وصححه ابن حبان (٥٠٠٨)، وابن خزيمة (٢٤٦٩).","grade":"حسن","chapter_ar":"باب جواز العرايا فيما دون خمسة أوسق","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14868), Abu Ya‘la (1780), and authenticated by Ibn Hibban (5008) and Ibn Khuzaymah (2469).","chapter_en":"The permissibility of araya in amounts under five wasqs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah al-Ansari said: I heard the Messenger of Allah ﷺ, when he permitted the people of the araya to sell them by estimate, say: “One wasq, two wasqs, three, and four.”"]},"buhuth":{"ar":["((والأوسق)) جمع وسق، وهو ستون صاعاً، والصاع خمسة أرطال وثلث، والمجموع ثلاث مائة صاع، وهي تساوي اليوم (٧٠٠) كيلو جرام تقريباً."],"en":["A wasq is sixty sa‘s. A sa‘ is five and one-third Iraqi pounds. The total comes to three hundred sa‘s, which is approximately 700 kilograms today."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":14868},{"key":"ابو_یعلی","label":"أبو يعلى","number":1780},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":5008},{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":2469},{"key":"ahmad","label":"مسند الإمام أحمد","number":14868,"n":14868}]},{"num":5748,"demo":false,"sanad":"","matn":["عن زيد أبي عياش أنه سأل سعد بن أبي وقاص عن البيضاء بالسلت، فقال له سعد: أيتها أفضل؟ قال: البيضاء. فنهاه عن ذلك. وقال سعد: سمعت رسول اللّٰه ﷺ يسأل عن اشتراء التمر بالرطب، فقال رسول اللّٰه ﷺ: ((أينقص الرطب إذا يبس؟)) فقالوا: نعم، فنهى عن ذلك."],"takhrij":"حسن: رواه مالك (٢٢) وأبو داود (٣٣٥٩)، والترمذي (١٢٢٥)، والنسائي (٤٥٤٩)، وابن ماجه (٢٢٦٤).","grade":"حسن","chapter_ar":"باب النهي عن بيع الرطب بالتمر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (22), Abu Dawud (3359), al-Tirmidhi (1225), al-Nasa’i (4549), and Ibn Majah (2264).","chapter_en":"The prohibition of selling fresh dates for dried dates","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":22,"content":{"translation":{"en":["Zayd Abu ‘Ayyash asked Sa‘d ibn Abi Waqqas about trading white grain for sult grain. Sa‘d said to him: “Which of them is better?” He replied: “The white one.” So Sa‘d forbade him from that. Sa‘d then said: I heard the Messenger of Allah ﷺ being asked about buying dried dates with fresh dates, and the Messenger of Allah ﷺ said: “Do the fresh dates decrease when they dry?” They said: “Yes.” So he forbade that."]},"buhuth":{"ar":["قوله: ((البيضاء)) نوع من البر أبيض اللون. و((السلت)) نوع آخر غير البر، وهو أدق حباً منه. وقال بعضهم: البيضاء هو الرطب من السلت، وهذا أليق بمعنى الحديث بدليل أنه شبهه بالرطب مع التمر، ولو اختلف الجنس لم يصح التشبيه."],"en":["“Al-bayda” is a type of wheat that is white in color. “Al-sult” is another type, different from wheat, with finer grain. Some said that “al-bayda” here means the fresh form of sult, and that fits the meaning of the hadith better, since it is compared to fresh dates versus dried dates. If the category were different, the comparison would not hold."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":22},{"key":"abudawud","label":"أبو داود","number":3359},{"key":"tirmidhi","label":"الترمذي","number":1225},{"key":"nasai","label":"النسائي","number":4549},{"key":"ibnmajah","label":"ابن ماجه","number":2264}]},{"num":5749,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ نهى عن بيع الثمار حتى يبدو صلاحها، نهى البائع والمشتري."],"takhrij":"متفق عليه: رواه مالك (١٠) والبخاري (٢١٩٤)، ومسلم (٤٩ :١٥٣٤).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (10), al-Bukhari (2194), and Muslim (1534/49).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ forbade selling fruits until their ripeness appears. He forbade both the seller and the buyer."]},"buhuth":{"ar":["ورواه البخاري (١٤٨٦) وزاد: ((وكان إذا سئل عن صلاحها قال: حتى تذهب عاهته))."],"en":["Al-Bukhari (1486) added: “When he was asked about their ripeness, he said: ‘Until their blight is gone.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":10},{"key":"bukhari","label":"البخاري","number":2194},{"key":"muslim","label":"مسلم","number":49}]},{"num":5750,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ نهى عن بيع النخل حتى يزهو، وعن السنبل حتى يبيض ويأمن العاهة، نهى البائع والمشتري."],"takhrij":"صحيح: رواه مسلم (١٥٣٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1535).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ forbade selling dates on the palm until they show ripeness, and grain in the ear until it turns white and is safe from blight. He forbade both the seller and the buyer."]},"buhuth":{"ar":["والزهو في التمر أن يحمر، أو يصفر، وذلك إمارة الصلاح فيها، ودليل سلامتها من الآفة.","وقوله: ((عن السنبل حتى يبيض)) ظاهره بيع الحب في السنبل إذا اشتد، وابيض."],"en":["Ripeness in dates means that they turn red or yellow. That is a sign that they have ripened and evidence that they are safe from damage.","His statement regarding grain “until it turns white” apparently refers to selling grain while still in the ear once it hardens and whitens."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1535}]},{"num":5751,"demo":false,"sanad":"","matn":["عن عثمان بن عبد اللّٰه بن سراقة قال: كنا في سفر، ومعنا ابن عمر، فسألته، فقال: رأيت رسول اللّٰه ﷺ لا يسبح في السفر قبل الصلاة، ولا بعدها. قال: وسألت ابن عمر عن بيع الثمار، فقال: نهى رسول اللّٰه عن بيع الثمار حتى تذهب العاهة. قلت: يا أبا عبد الرحمن، وما تذهب العاهة؟ وما العاهة؟ قال: طلوع الثريا."],"takhrij":"صحيح: رواه الإمام أحمد (٥٠١٥ ،٥٠١٢)، والطبراني في الكبير (١٣٢٨٧)، والبيهقي (٣٠٠/٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (5012, 5015), al-Tabarani in al-Kabir (13287), and al-Bayhaqi (5/300).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["‘Uthman ibn ‘Abd Allah ibn Suraqah said: We were on a journey with Ibn ‘Umar, and I asked him. He said: I saw the Messenger of Allah ﷺ not perform voluntary prayer before the prescribed prayer while traveling, nor after it. He said: And I asked Ibn ‘Umar about selling fruits, so he said: The Messenger of Allah ﷺ forbade selling fruits until the blight is gone. I said: O Abu ‘Abd al-Rahman, what does it mean for the blight to be gone? What is the blight? He said: The rising of the Pleiades."]},"buhuth":{"ar":["وقوله: ((طلوع الثريا)) هو علامة ذهاب عاهة الثمار، وسيأتي مثله عن زيد بن ثابت."],"en":["The rising of the Pleiades is a sign that the blight affecting fruits has passed. The same will also come from Zayd ibn Thabit."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":5015},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":13287},{"key":"البیہقی","label":"البيهقي","number":300},{"key":"ahmad","label":"مسند الإمام أحمد","number":5012,"n":5012}]},{"num":5752,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن النبي ﷺ نهى عن بيع ثمر النخل حتى تزهو. فقلنا لأنس: ما زهوها؟ قال: تحمر، وتصفر، أرأيت إن منع اللّٰه الثمرة بم تستحل مال أخيك."],"takhrij":"متفق عليه: رواه البخاري (٢٢٠٨)، ومسلم (١٥٥٥). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2208) and Muslim (1555). The wording is Muslim’s.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet ﷺ forbade selling the fruit of date palms until it shows ripeness. We asked Anas: What is its ripeness? He said: It turns red and yellow. “If Allah withholds the fruit, then by what right would one of you take his brother’s wealth?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2208},{"key":"muslim","label":"مسلم","number":1555}]},{"num":5753,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن رسول اللّٰه ﷺ نهى عن بيع الثمار حتى تُزهي. فقيل له: يا رسول الله، وما تزهي؟ فقال: ((حين تحمر)). وقال رسول اللّٰه ﷺ: ((أرأيت إذا منع اللّٰه الثمرة فبم يأخذ أحدكم مال أخيه))."],"takhrij":"متفق عليه: رواه مالك (١١) والبخاري (٢١٩٨)، ومسلم (١٥٥٥).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (11), al-Bukhari (2198), and Muslim (1555).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Malik reported that the Messenger of Allah ﷺ forbade selling fruits until they show ripeness. It was said to him: O Messenger of Allah ﷺ, what is their ripeness? He said: “When they turn red.” And the Messenger of Allah ﷺ said: “If Allah withholds the fruit, then by what right would one of you take his brother’s wealth?”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":11},{"key":"bukhari","label":"البخاري","number":2198},{"key":"muslim","label":"مسلم","number":1555}]},{"num":5754,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه يقول: قال رسول اللّٰه ﷺ: ((لو بعت من أخيك ثمراً، فأصابته جائحة، فلا يحل لك أن تأخذ منه شيئاً، بم تأخذ مال أخيك بغير حق؟))."],"takhrij":"صحيح: رواه مسلم (١٥٥٤).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1554).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ said: “If you sold fruit to your brother and then a calamity struck it, it is not lawful for you to take anything from him. By what right would you take your brother’s wealth without due right?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1554}]},{"num":5755,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: نهى النبي ﷺ أن تباع الثمرة حتى تُشقح. قال: فقلت لسعيد: وما تُشقح؟ قال: تحمار، وتصفار، ويؤكل منها."],"takhrij":"متفق عليه: رواه البخاري (٢١٩٦)، ومسلم (٨٤ :١٥٣٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2196) and Muslim (1536/84).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ forbade fruit from being sold until it ripens. I said to Sa‘id: What does ripening mean? He said: It becomes red, becomes yellow, and some of it is eaten."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2196},{"key":"muslim","label":"مسلم","number":84}]},{"num":5756,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: نهى النبي ﷺ عن بيع الثمر حتى يطيب، ولا يباع شيء منه إلا بالدينار والدرهم إلا العرايا."],"takhrij":"متفق عليه: رواه البخاري (٢١٨٩) ومسلم (٥٣ :١٥٣٦). وفي لفظ: نهى رسول اللّٰه عن بيع الثمر حتى يبدو صلاحه.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2189) and Muslim (1536/53). In another wording: The Messenger of Allah ﷺ forbade selling fruit until its ripeness appears.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ forbade selling fruit until it becomes wholesome, and nothing from it is to be sold except for gold and silver, except in the case of the araya."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2189},{"key":"muslim","label":"مسلم","number":53}]},{"num":5757,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: ((لا تبتاعوا الثمار حتى يبدو صلاحها))."],"takhrij":"صحيح: رواه مسلم (١٥٣٨). ورواه من وجه آخر، وزاد فيه: ((ولا تبتاعوا الثمر بالتمر)).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1538). Another chain adds: “And do not buy fruit with dried dates.”","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Do not buy fruits until their ripeness appears.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1538}]},{"num":5758,"demo":false,"sanad":"","matn":["عن أبي البختري قال: سألت ابن عباس عن بيع النخل، فقال: نهى رسول اللّٰه ﷺ عن بيع النخل حتى يأكل منه أو يؤكل، وحتى يوزن. قال: فقلت: ما يوزن؟ فقال رجل عنده: حتى يُحزَر."],"takhrij":"متفق عليه: رواه البخاري (٢٢٤٦)، ومسلم (١٥٣٧). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2246) and Muslim (1537). The wording is Muslim’s.","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Abu al-Bakhtari said: I asked Ibn ‘Abbas about selling date palms, and he said: The Messenger of Allah ﷺ forbade selling the dates on the palm until one may eat from them, or they are eaten, and until they are weighed. I said: What does “weighed” mean? A man beside him said: Until they can be estimated."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2246},{"key":"muslim","label":"مسلم","number":1537}]},{"num":5759,"demo":false,"sanad":"","matn":["عن ابن عباس كان يقول: قال رسول الله ﷺ: ((لا يباع الثمر حتى يُطعم))."],"takhrij":"صحيح: رواه أحمد (٢٢٤٧)، والطبراني في الكبير (١١٨٧ ،١١٨٨)، وصححه ابن حبان (٤٩٨٨).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (2247), al-Tabarani in al-Kabir (1187, 1188), and authenticated by Ibn Hibban (4988).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Abbas used to say: The Messenger of Allah ﷺ said: “Fruit is not to be sold until it can be eaten.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":1187},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4988},{"key":"ahmad","label":"مسند الإمام أحمد","number":2247,"n":2247}]},{"num":5760,"demo":false,"sanad":"","matn":["عن زيد بن ثابت قال: كان الناس في عهد رسول اللّٰه ﷺ يتبايعون الثمار، فإذا جذ الناس وحضر تقاضيهم قال المبتاع: إنه أصاب الثمر الدمان، أصابه مرض، أصابه قشام - عاهات يحتجون بها -، فقال رسول اللّٰه ﷺ لما كثرت عنده الخصومة في ذلك: ((فإما لا فلا تتبايعوا حتى يبدو صلاح الثمر)) كالمشورة يشير بها لكثرة خصومتهم."],"takhrij":"صحيح: رواه أبو داود (٣٣٧٢)، وأحمد (٢١٦٦٢)، والبيهقي (٣٠١-٣٠٢/٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (3372), Ahmad (21662), and al-Bayhaqi (5/301-302).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["Zayd ibn Thabit said: In the time of the Messenger of Allah ﷺ, people used to buy and sell fruits. When the people harvested them and the time for settlement came, the buyer would say: The fruit was struck by blight, or disease, or damage — defects they used as excuses. So when disputes over that became frequent before him, the Messenger of Allah ﷺ said: “Then, if you insist, do not trade in fruits until their ripeness appears,” as advice from him because of how much they were disputing."]},"buhuth":{"ar":["قوله: ((جذ الناس)) بالجيم والذال المعجمة الثقيلة، أي قطعوا ثمر النخل. والجذاذ صرام النخل، وهو قطع ثمرتها وأخذها من الشجر.","وقوله: ((الدمان)) فسر بفساد الطلع، وتعفنه، وسواده.","وقوله: ((قُشام)) فسر في رواية بأنه شيء يصيبه حتى لا يرطب. وقيل: أن ينتقص ثمر النخل قبل أن يصير بلحاً.","وقوله: ((فإما لا)) أصلها “إن” الشرطية، و”ما” زائدة، فأدغمت، والمعنى: إن لم تفعلوا كذا فافعلوا كذا.","وقوله: ((حتى تطلع الثريا)) أي مع الفجر في أول فصل الصيف، وذلك عند اشتداد الحر في بلاد الحجاز، فالمعتبر في الحقيقة النضج، وطلوع الثريا علامة له."],"en":["“Jadhdha” means the people cut the fruit from the date palms. “Jadhadh” means harvesting the date fruit by cutting and taking it from the tree.","“Al-daman” was explained as damage to the flower cluster, its decay, and blackening.","“Qusham” was explained in one narration as something that affects it so that it never becomes ripe. It was also said to mean that the fruit decreases before becoming firm unripe dates.","The phrase “fa imma la” means: if you do not do such-and-such, then do this instead.","The mention of the rising of the Pleiades means at dawn at the beginning of summer, when the heat intensifies in the Hijaz. What really matters is ripeness, and the rising of the Pleiades is simply a sign for it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3372},{"key":"ahmad","label":"أحمد","number":21662},{"key":"البیہقی","label":"البيهقي","number":301},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10605,"n":10694}]},{"num":5761,"demo":false,"sanad":"","matn":["عن أم المؤمنين عائشة، عن النبي ﷺ قال: ((لا تبيعوا ثماركم حتى يبدو صلاحها، وتنجو من العاهة))."],"takhrij":"حسن: رواه الإمام أحمد (٢٤٤٠٧)، والحارث في مسنده “بغية الباحث” (ص ٤٧٠).","grade":"حسن","chapter_ar":"باب النهي عن بيع الثمار حتى يبدو صلاحها","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (24407) and al-Harith in his Musnad, Bughyat al-Bahith (p. 470).","chapter_en":"The prohibition of selling fruits until their ripeness appears","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":23,"content":{"translation":{"en":["The Mother of the Believers, ‘A’ishah, reported that the Prophet ﷺ said: “Do not sell your fruits until their ripeness appears and they are safe from blight.”"]},"buhuth":{"ar":["فقه هذا الباب:","١- العمل على هذا عند أهل العلم، لا يرون بيع الثمار قبل بدو الصلاح للعلة التي ذكرت في الحديث.","٢- ولكن لو باع، واشترط القطع لجاز باتفاق أهل العلم؛ لأنه يأمن بالقطع من الهلاك بالآفة والعاهة. وفيه انتفاء العلة التي جاء النهي من أجلها.","٣- وبدو الصلاح يختلف باختلاف أنواع الثمرة، ففي الرطب حتى يصير بسرا، وهو أن يرى فيه نقط الحمرة، والسواد. وفي الخوخ والكمثرى والمشمش والتفاح بأن يطيب بحيث يستطاع أكله. وفي البطيخ بأن يرى فيه أثر النضج، وفي القثاء والباذنجان بأن يجتنى في الغالب.","٤- وطلوع النجم - هو الثريا - علامة بداية فصل الصيف، وهو ابتداء نضج الثمار، فالمعتبر في الحقيقة هو النضج، وطلوع النجم علامة له، كما جاء في الحديث: (( حتى يتبين الأصفر من الأحمر)).","٥- إذا بدا الصلاح في بعضه جاز بيع الكل إذا اتفق الجنس، فإن اختلف فالعبرة ببدء الصلاح في كل جنس، إلا إذا اشترط القطع فيما لم يبد فيه الصلاح، فجاز بيع الجميع.","٦- وكذلك لا يجوز بيع الزرع قبل اشتداد الحب في السنبل، كما جاء في حديث ابن عمر."],"en":["Understanding of this chapter:","The scholars act upon this and do not allow selling fruits before signs of ripeness appear, for the reason mentioned in the hadiths.","But if someone sells them on condition that they be cut immediately, then it is permissible by agreement of the scholars, because cutting removes the risk of destruction by blight or defect. In that case, the reason for the prohibition is no longer present.","The appearance of ripeness differs according to the type of fruit. In fresh dates, it is when they become unripe ripe dates and signs of red or black dots appear. In peaches, pears, apricots, and apples, it is when they become good enough to eat. In melons, it is when signs of ripeness appear. In cucumbers and eggplants, it is when they are usually ready to be picked.","The rising of the star — meaning the Pleiades — is a sign of the beginning of summer and the start of fruit ripening. What really matters is ripeness itself, and the rising of the star is only a sign of it, as came in the hadith: “until the yellow becomes distinct from the red.”","If ripeness appears in part of the crop, then selling all of it is allowed if it is all one kind. If the kinds differ, then each kind is judged by the appearance of ripeness in itself, unless cutting is stipulated for what has not yet ripened, in which case selling everything is allowed.","Likewise, it is not allowed to sell crops before the grain hardens in the ear, as came in the hadith of Ibn Umar."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":24407},{"key":"الحارث/مسندہ_بغیہ_الباحث","label":"الحارث في مسنده “بغية الباحث”","number":470},{"key":"ahmad","label":"مسند الإمام أحمد","number":24407,"n":24407}]},{"num":5762,"demo":false,"sanad":"","matn":["عن جابر أن النبي أمر بوضع الجوائح."],"takhrij":"صحيح: رواه مسلم (١٧ :١٥٥٤). ورواه الشافعي في الأم (٥٦/٣) وفيه: (( أن رسول اللّٰه ﷺ نهى عن بيع السنين، وأمر بوضع الجوائح)).","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1554/17). Al-Shafi‘i also narrated it in al-Umm (3/56), and in it is: “The Messenger of Allah ﷺ forbade selling for future years and ordered remission in cases of blight.”","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ ordered that losses caused by blight be remitted."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17},{"key":"ورواہ_الشافعی/الام","label":". ورواه الشافعي في الأم","number":56}]},{"num":5763,"demo":false,"sanad":"","matn":["عن جابر أن النبي ﷺ نهى عن بيعِ السنين، ووَضَعَ الجوائح."],"takhrij":"صحيح: رواه أبو داود (٣٣٧٤).","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3374).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ forbade selling fruit for future years and ruled that losses caused by blight be remitted."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3374}]},{"num":5764,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: قال رسول اللّٰه ﷺ: (( لو بعت من أخيك ثمرا فأصابته جائحة، فلا يحل لك أن تأخذ منه شيئا، بم تأخذ مال أخيك بغير حق؟ ))."],"takhrij":"صحيح: رواه مسلم (١٤ :١٥٥٤).","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1554/14).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ said, “If you sold fruit to your brother and then it was struck by a calamity, it is not lawful for you to take anything from him. With what right would you take your brother’s wealth without right?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":14}]},{"num":5765,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال:","أصيب رجل في عهد رسول الله ﷺ في ثمار ابتاعها، فكثر دينه، فقال رسول الله ﷺ:","«تَصَدَّقُوا عَلَيْهِ».","فتصدق الناس عليه، فلم يبلغ ذلك وفاء دينه.","فقال رسول الله ﷺ لغرمائه:","«خُذُوا مَا وَجَدْتُمْ، وَلَيْسَ لَكُمْ إِلَّا ذَلِكَ»."],"takhrij":"صحيح: رواه مسلم (١٥٥٦).","grade":"صحيح","chapter_ar":"باب ما جاء في وضع الجائحة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1556).","chapter_en":"What has come regarding remission in the case of a blight or calamity","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":24,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported:","A man during the lifetime of the Messenger of Allah ﷺ suffered a loss in fruits that he had purchased, and his debts became numerous.","The Messenger of Allah ﷺ said:","“Give charity to him.”","The people gave charity to him, but it was not enough to repay his debt fully.","The Messenger of Allah ﷺ then said to his creditors:","“Take whatever you find, and you are entitled to nothing beyond that.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1556}]},{"num":5766,"demo":false,"sanad":"","matn":["عن أبي هريرة قال:","نهى رسول الله ﷺ عن بيع الحصاة، وعن بيع الغرر."],"takhrij":"صحيح: رواه مسلم (١٥١٣).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الغرر، وبيع الحصاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1513).","chapter_en":"The prohibition of uncertain sales and pebble sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah reported:","The Messenger of Allah ﷺ prohibited the pebble sale and transactions involving excessive uncertainty."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1513}]},{"num":5767,"demo":false,"sanad":"","matn":["عن ابن عمر قال: نهى رسول اللّٰه ﷺ عن بيع الغرر."],"takhrij":"حسن: رواه الإمام أحمد (٦٣٠٧)، وابن حبان في صحيحه (٤٩٧٢).","grade":"حسن","chapter_ar":"باب النهي عن بيع الغرر، وبيع الحصاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6307) and Ibn Hibban in his Sahih (4972).","chapter_en":"The prohibition of uncertain sales and pebble sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":25,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ forbade uncertain sale."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":6307},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4972},{"key":"ahmad","label":"مسند الإمام أحمد","number":6307,"n":6307},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1932,"n":1929}]},{"num":5768,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر أن رسول اللّٰه ﷺ نهى عن بيع حبل الحبلة، وكان بيعا يتبايعه أهل الجاهلية، كان الرجل يبتاع الجزور إلى أن تنتج الناقة، ثم تنتج التي في بطنها."],"takhrij":"متفق عليه: رواه مالك (٦٢) والبخاري (٢١٤٣) ومسلم (١٥١٤).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع حبل الحبلة، والمضامين، والملاقيح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (62), al-Bukhari (2143), and Muslim (1514).","chapter_en":"The prohibition of selling habal al-habalah, unborn offspring, and what is still in the wombs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":26,"content":{"translation":{"en":["Abd Allah ibn Umar reported that the Messenger of Allah ﷺ forbade the sale of habal al-habalah. This was a sale practiced by the people of the pre-Islamic era: a man would buy a camel on delayed terms until a she-camel gave birth, and then until the one in her womb gave birth."]},"buhuth":{"ar":["والمراد بحبل الحبلة فقال النووي في شرح مسلم: “اختلف العلماء في المراد بالنهي عن بيع حبل الحبلة، فقال جماعة: هو البيع بثمن مؤجل إلى أن تلد الناقة، ويلد ولدها. وقال آخرون: هو بيع ولد الناقة الحامل في الحال، وهذا أقرب إلى اللغة”.","وقال ابن الأثير في النهاية: “الحبل الأول يراد به ما في بطون النوق من الحمل، والثاني حبل الذي في بطون النوق. وإنما نهي عنه لمعنيين: أحدهما أنه غرر، وبيع شيء لم يخلق بعد، وهو أن يبيع ما سوف يحمله الجنين الذي في بطن الناقة على تقدير أن تكون أنثى، فهو بيع نتاج النتاج. وقيل: أراد بحبل الحبلة أن يبيعه إلى أجل ينتج فيه الحمل الذي في بطن الناقة، فهو أجل مجهول، ولا يصح”. انتهى."],"en":["Explanation: Al-Nawawi said that scholars differed over what exactly is meant by habal al-habalah. Some said it means a sale with payment delayed until the she-camel gives birth and then its offspring gives birth. Others said it means selling the offspring of a pregnant she-camel immediately, and this is closer to the language. Ibn al-Athir said the first “habal” refers to the pregnancy in the bellies of the camels, and the second to the pregnancy of what is in those bellies. It was forbidden for two reasons: first, because it is uncertainty and the sale of something not yet created; second, because it may also refer to an unknown time limit, and that is invalid."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":62},{"key":"bukhari","label":"البخاري","number":2143},{"key":"muslim","label":"مسلم","number":1514}]},{"num":5769,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عباس، عن النبي ﷺ أنه قال: ((في السلف في حبل الحبل ربا))."],"takhrij":"صحيح: رواه النسائي (٤٦٢٢)، وأحمد (٢١٤٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع حبل الحبلة، والمضامين، والملاقيح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (4622) and Ahmad (2145).","chapter_en":"The prohibition of selling habal al-habalah, unborn offspring, and what is still in the wombs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":26,"content":{"translation":{"en":["Abd Allah ibn Abbas reported that the Prophet ﷺ said: “There is usury in an advance sale involving habal al-habal.”"]},"buhuth":{"ar":["وقوله: ((السلف)) هو أن يسلم المشتري الثمن إلى رجل عنده ناقة حبلى، ويقول: إذا ولدت هذه الناقة، ثم ولدت التي في بطنها، فقد اشتريت منك ولدها بهذا الثمن، فهذه المعاملة شبيهة بالربا؛ لكونها حراما كالربا من حيث إنه يبيع ما ليس عند البائع، وهو لا يقدر على تسليمه، ففيه غرر."],"en":["Explanation: Here, salaf means that the buyer pays the price in advance to a man who has a pregnant she-camel and says: when this camel gives birth, and then the one in her womb gives birth, I have bought that offspring from you for this price. This resembles usury in the sense that it is forbidden like usury, because the seller is selling what he does not possess and cannot deliver, so it contains uncertainty."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4622},{"key":"ahmad","label":"مسند الإمام أحمد","number":2145,"n":2145}]},{"num":5770,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّه قال: نهى رسول اللّٰه ﷺ عن المحاقلة والمزابنة والمعاومة والمخابرة - قال أحدهما: بيع السنين هي المعاومة - وعن الثنيا، ورخص في العرايا."],"takhrij":"صحيح: رواه مسلم (٨٥ :١٥٣٦)، ورواه من طريق آخر (٨٦) بلفظ: ((نهى رسول اللّٰه ﷺ عن كراء الأرض، وعن بيعها السنين، وعن بيع التمر حتى يرطب)).","grade":"صحيح","chapter_ar":"باب النهي عن بيع المعاومة والسنين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1536/85). In another chain (1536/86), the wording is: “The Messenger of Allah ﷺ forbade renting land, selling it for years, and selling dates until they become ripe.”","chapter_en":"The prohibition of multi-year fruit sales","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, fresh produce for dried produce by estimate, multi-year fruit sales, sharecropping, and undefined exceptions, and he allowed the araya. One of the narrators said: selling for years is the same as multi-year sale."]},"buhuth":{"en":["“Selling for years” means selling the fruit of a date palm for two or three years ahead. It is invalid by consensus because it is selling something that does not yet exist at the time of contract, and it contains uncertainty, ignorance, and inability to deliver if blight strikes."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":85}]},{"num":5771,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ نهى عن الملامسة والمنابذة."],"takhrij":"متفق عليه: رواه مالك (٧٦) والبخاري (٢١٤٦)، ومسلم (١٥١١).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (76), al-Bukhari (2146), and Muslim (1511).","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ forbade touch-sale and throw-sale."]},"buhuth":{"ar":["ورواه البخاري (٣٦٨)، ومسلم من طريق آخر بلفظ: ((نهى النبي ﷺ عن بيعتين: عن اللَّماس، والنَّباذ، وأن يشتمل الصماء، وأن يحتبي الرجل في ثوب واحد)). واللفظ للبخاري. وفي لفظ: ((نهى عن بيعتين الملامسة، والمنابذة)).","أما الملامسة فأن يلمس كل واحد منهما ثوب صاحبه بغير تأمل. والمنابذة أن ينبذ كل واحد منهما ثوبه إلى الآخر، ولم ينظر واحد منهما إلى ثوب صاحبه."],"en":["Al-Bukhari (368) and Muslim also narrated through another chain with the wording: “The Prophet ﷺ forbade two sales: touching and throwing, and he also forbade wrapping oneself tightly in one garment and sitting with one garment wrapped around the body.” Another wording says: “He forbade the two sales of touch-sale and throw-sale.”","Explanation: Touch-sale means that each of the two parties merely touches the other’s garment without careful inspection. Throw-sale means that each one throws his garment to the other, and neither one examines the other’s item."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":76},{"key":"bukhari","label":"البخاري","number":2146},{"key":"muslim","label":"مسلم","number":1511}]},{"num":5772,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: نهانا رسول اللّٰه ﷺ عن بيعتين ولبستين: نهى عن الملامسة والمنابذة في البيع. والملامسة: لمس الرجل ثوب الآخر بيده بالليل أو بالنهار، ولا يقلبه إلا بذلك. والمنابذة: أن ينبذ الرجل إلى الرجل بثوبه، وينبذ الآخر إليه ثوبه، ويكون ذلك بيعهما من غير نظر ولا تراض."],"takhrij":"متفق عليه: رواه البخاري (٥٨٢٠)، ومسلم (١٥١٢). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5820) and Muslim (1512). The wording is Muslim’s.","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ forbade us from two sales and two styles of dress. He forbade touch-sale and throw-sale in transactions. Touch-sale is when a man touches the garment of another with his hand at night or day and does not inspect it except by that. Throw-sale is when one man throws his garment to another, and the other throws his garment to him, and that becomes their sale without inspection and without mutual satisfaction."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5820},{"key":"muslim","label":"مسلم","number":1512}]},{"num":5773,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: نهى رسول اللّٰه عن المحاقلة، والمخاضرة، والملامسة، والمنابذة، والمزابنة."],"takhrij":"صحيح: رواه البخاري (٢٢٠٧).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الملامسة والمنابذة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2207).","chapter_en":"The prohibition of touch-sale and throw-sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":28,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ forbade selling standing crops for a measured amount of grain, selling green produce before ripeness, touch-sale, throw-sale, and fresh produce for dried produce by estimate."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2207}]},{"num":5774,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال:","«نَهَى رَسُولُ اللَّهِ ﷺ عَنْ بَيْعِ الصُّبْرَةِ مِنَ التَّمْرِ، لَا يُعْلَمُ كَيْلُهَا، بِالْكَيْلِ الْمُسَمَّى مِنَ التَّمْرِ»."],"takhrij":"صحيح: رواه مسلم (١٥٣٠).","grade":"صحيح","chapter_ar":"باب النهي عن بيع صبرة التمر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1530).","chapter_en":"The prohibition of selling a heap of dates","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":29,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported:","“The Messenger of Allah ﷺ prohibited selling a heap of dates whose measure is unknown in exchange for a specified measured quantity of dates.”"]},"buhuth":{"ar":["ورواه النسائي (٤٥٤٨) من وجه آخر بلفظ:","«لَا تُبَاعُ الصُّبْرَةُ مِنَ الطَّعَامِ بِالصُّبْرَةِ مِنَ الطَّعَامِ، وَلَا الصُّبْرَةُ مِنَ الطَّعَامِ بِالْكَيْلِ الْمُسَمَّى مِنَ الطَّعَامِ».","والصبرة هي الكومة، يقال: اشترى الشيء صبرة، أي بلا وزن ولا كيل."],"en":["Al-Nasāʾī (4548) narrated through another route:","“A heap of food is not to be sold for another heap of food, nor is a heap of food to be sold for a specified measured quantity of food.”","A ṣubrah is a pile or heap. To purchase something ṣubrah means to buy it without weighing or measuring it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1530}]},{"num":5775,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أنه سمع رسول اللّٰه ﷺ يقول وهو بمكة عام الفتح: (( إن اللّٰه ورسوله حرم بيع الخمر والميتة والخنزير والأصنام )). فقيل: يا رسول الله، أرأيت شحوم الميتة؛ فإنها تطلى بها السفن، ويدهن بها الجلود، ويستصبح بها الناس؟ فقال: (( لا، هو حرام )). ثم قال رسول اللّٰه ﷺ عند ذلك: (( قاتل اللّٰه اليهود، إن اللّٰه لما حرم شحومها جملوه، ثم باعوه، فأكلوا ثمنه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢٣٦)، ومسلم (١٥٨١).","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2236) and Muslim (1581).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Jabir ibn Abd Allah reported that he heard the Messenger of Allah ﷺ say in Makkah during the Year of the Conquest: “Allah and His Messenger have forbidden the sale of wine, carrion, pork, and idols.” It was said: O Messenger of Allah ﷺ, what about the fat of carrion, for ships are coated with it, skins are greased with it, and people use it for lamps? He said: “No, it is forbidden.” Then the Messenger of Allah ﷺ said: “May Allah destroy the Jews. When Allah forbade their fats, they melted them, then sold them, and consumed their price.”"]},"intro":{"ar":["قال اللّه تعالى: ( حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَالْمُنْخَنِقَةُ وَالْمَوْقُوذَةُ وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَن تَسْتَقْسِمُوا بِالْأَزْلَامِ ذَلِكُمْ فِسْقٌ ۗ الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ ۚ الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا ۚ فَمَنِ اضْطُرَّ فِي مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍ لِإِثْمٍ فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ )","[سورة المائدة: ٣]"],"en":["Allah the Exalted said: “Forbidden to you are carrion, blood, the flesh of swine, that which has been dedicated to other than Allah, the strangled animal, the beaten animal, the fallen animal, the gored animal, and that which has been eaten by a beast — except what you are able to slaughter properly — and that which is sacrificed on stone altars, and that you seek decision by divining arrows. That is grave disobedience. Today those who disbelieve have despaired of your religion, so do not fear them, but fear Me. Today I have perfected for you your religion, completed My favor upon you, and chosen submission to Allah as your religion. But whoever is forced by severe hunger, without inclining to sin, then indeed Allah is Forgiving and Merciful.”","[Surat al-Ma’idah: 3]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2236},{"key":"muslim","label":"مسلم","number":1581}]},{"num":5776,"demo":false,"sanad":"","matn":["عن ابن عباس قال: بلغ عمر أن فلانا باع خمرا، فقال: قاتل اللّٰه فلانا، ألم يعلم أن رسول اللّٰه ﷺ قال: (( قاتل اللّٰه اليهود، حرمت عليهم الشحوم، فجملوها، فباعوها ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢٢٣)، ومسلم (١٥٨٢). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2223) and Muslim (1582). This wording is from al-Bukhari.","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: Umar was informed that a certain man had sold wine, so he said: May Allah destroy that man. Does he not know that the Messenger of Allah ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, so they melted it and sold it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2223},{"key":"muslim","label":"مسلم","number":1582}]},{"num":5777,"demo":false,"sanad":"","matn":["عن ابن عباس قال: رأيت رسول اللّٰه ﷺ جالسا عند الركن، قال: فرفع بصره إلى السماء، فضحك، فقال: (( لعن اللّٰه اليهود ثلاثا، إن اللّٰه حرم عليهم الشحوم، فباعوها، وأكلوا أثمانها، وإن اللّٰه إذا حرم على قوم أكل شيء حرم عليهم ثمنه ))."],"takhrij":"صحيح: رواه أبو داود (٣٤٨٨)، وأحمد (٢٢٢١)، وابن حبان (٤٩٣٨)، والبيهقي (١٣/٦).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3488), Ahmad (2221), Ibn Hibban (4938), and al-Bayhaqi (6/13).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: I saw the Messenger of Allah ﷺ sitting by the corner of the Ka‘bah. He raised his sight to the sky and smiled, then said: “May Allah curse the Jews three times. Allah forbade fat to them, but they sold it and consumed its price. When Allah forbids a people from eating something, He forbids them from taking its price as well.”"]},"buhuth":{"ar":["وقوله: (( إن اللّٰه إذا حرم على قوم أكل شيء حرم عليهم ثمنه )) إن هذا العموم متروك باتفاق العلماء على جواز بيع الآدمي والحمار ونحوهما، وقد كان الناس يتبايعون السرجين للزرع في سائر الأزمان. انظر للمزيد “المنة الكبرى” (٥/٢٢٨)."],"en":["Explanation: His statement, “When Allah forbids a people from eating something, He forbids them from taking its price as well,” is not taken in a fully unrestricted sense. The scholars agreed that some things may not be eaten but may still be sold, such as human beings, donkeys, and similar matters. People also traded manure for farming use throughout the ages. See al-Minnah al-Kubra (5/228) for more detail."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3488},{"key":"ibnhibban","label":"ابن حبان","number":4938},{"key":"البیہقی","label":"البيهقي","number":13},{"key":"ahmad","label":"مسند الإمام أحمد","number":2221,"n":2221},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11051,"n":11145}]},{"num":5778,"demo":false,"sanad":"","matn":["عن ابن عباس قال: أهدى رجل لرسول اللّٰه ﷺ راوية خمر، فقال له رسول اللّٰه ﷺ: (( أما علمت أن اللّٰه حرمها ))؟ قال: لا. فساره رجل إلى جنبه، فقال له: (( بم ساررته؟ )) فقال: أمرته أن يبيعها. فقال له رسول اللّٰه ﷺ: (( إن الذي حرم شربها حرم بيعها )). ففتح الرجل المزادتين حتى ذهب ما فيهما."],"takhrij":"صحيح: رواه مالك (١٢) ومسلم (١٥٧٩).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (12) and Muslim (1579).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: A man gave the Messenger of Allah ﷺ a wineskin of wine. The Messenger of Allah ﷺ said to him: “Did you not know that Allah has forbidden it?” He said: No. A man next to him whispered to him, and the Prophet ﷺ said: “What did you whisper to him?” He said: I told him to sell it. The Messenger of Allah ﷺ said: “The One who forbade drinking it also forbade selling it.” So the man opened the two skins until all that was in them was poured out."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":12},{"key":"muslim","label":"مسلم","number":1579}]},{"num":5779,"demo":false,"sanad":"","matn":["عن ابن عباس يقول: سمعت رسول اللّٰه ﷺ يقول: (( أتاني جبريل، فقال: يا محمد، إن اللّٰه عز وجل لعن الخمر، وعاصرها، ومعتصرها، وشاربها، وحاملها، والمحمولة إليه، وبائعها، ومبتاعها، وساقيها، ومستقيها ))."],"takhrij":"حسن: رواه أحمد (٢٨٩٧)، والطبراني في الكبير (١٢٩٧٦)، وابن حبان (٥٣٥٦)، والحاكم (٣١/٢).","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2897), al-Tabarani in al-Kabir (12976), Ibn Hibban (5356), and al-Hakim (2/31).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas said: I heard the Messenger of Allah ﷺ say: “Gabriel came to me and said: O Muhammad, Allah has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, the one who serves it, and the one who asks for it to be served.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":12976},{"key":"ibnhibban","label":"ابن حبان","number":5356},{"key":"ahmad","label":"مسند الإمام أحمد","number":2897,"n":2897},{"key":"hakim","label":"المستدرك على الصحيحين","number":2234,"n":2226}]},{"num":5780,"demo":false,"sanad":"","matn":["عن ابن عباس، عن رسول اللّٰه ﷺ قال: (( إن اللّٰه حرم عليكم الخمر، والميسر، والكوبة )). وقال: (( كل مسكر حرام ))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٦٢٥)، والطحاوي في شرحه (٤/٢١٦)، والبيهقي (١٠/٢٢١).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2625), al-Tahawi in his commentary (4/216), and al-Bayhaqi (10/221).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Ibn Abbas reported that the Messenger of Allah ﷺ said: “Allah has forbidden for you wine, gambling, and the drum.” And he said: “Every intoxicant is forbidden.”"]},"buhuth":{"ar":["(( والكوبة )) هي النرد. وقيل: الطبل. وقيل: البربط. كذا في النهاية."],"en":["Explanation: The word used here has been explained as backgammon, and it has also been explained as a drum, and others said it means a stringed musical instrument. This is mentioned in al-Nihayah."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":2625},{"key":"الطحاوی/شرحہ","label":"الطحاوي في شرحه","number":4},{"key":"البیہقی","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":2625,"n":2625},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20943,"n":21101}]},{"num":5781,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( قاتل اللّٰه يهود، حرمت عليهم الشحوم، فباعوها، وأكلوا أثمانها ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢٢٤)، ومسلم (١٥٨٣).","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2224) and Muslim (1583).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, yet they sold it and consumed its price.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2224},{"key":"muslim","label":"مسلم","number":1583}]},{"num":5782,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( إن اللّٰه حرم الخمر وثمنها، وحرم الميتة وثمنها، وحرم الخنزير وثمنه ))."],"takhrij":"حسن: رواه أبو داود (٣٤٨٥).","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3485).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Allah has forbidden wine and its price, carrion and its price, and pork and its price.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3485}]},{"num":5783,"demo":false,"sanad":"","matn":["عن عون بن أبي جحيفة قال: رأيت أبي اشترى حجاما، فأمر بمحاجمه، فكسرت، فسألته عن ذلك، فقال: إن رسول اللّٰه ﷺ نهى عن ثمن الدم، وثمن الكلب، وكسب الأمة. ولعن الواشمة والمستوشمة، وآكل الربا ومؤكله، ولعن المصور."],"takhrij":"صحيح: رواه البخاري (٢٢٣٨).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2238).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Awn ibn Abi Juhayfah said: I saw my father buy a cupper, then he ordered that his instruments be broken. I asked him about that, and he said: The Messenger of Allah ﷺ forbade the price of blood, the price of a dog, and the earnings of a slave woman. He also cursed the woman who tattoos and the one who seeks tattooing, the one who consumes usury and the one who pays it, and he cursed the image-maker."]},"buhuth":{"ar":["قوله: (( نهى عن ثمن الدم )) قيل: معناه أجرة الحجامة، والصحيح هو بيع الدم نفسه؛ لأن أهل الجاهلية كانوا يجمدون الدم ويأكلونه، كما هو موجود إلى الآن في بعض المجتمعات الوثنية، وأما أجرة الحجامة فليست حراما، وأكثر ما قيل فيها إنها مكروهة."],"en":["Explanation: His saying, “He forbade the price of blood,” has been explained by some as the fee of cupping, but the sounder meaning is the sale of blood itself, because the people of the pre-Islamic period used to congeal blood and eat it. As for the wage of cupping, it is not forbidden; at most some scholars considered it disliked."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2238}]},{"num":5784,"demo":false,"sanad":"","matn":["عن عائشة قالت: لما نزلت الآيات من آخر سورة البقرة في الربا قالت: خرج رسول اللّٰه ﷺ إلى المسجد فحرم التجارة في الخمر."],"takhrij":"متفق عليه: رواه البخاري (٢٢٢٦)، ومسلم (١٥٨٠). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2226) and Muslim (1580). This wording is from Muslim.","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Aishah said: When the verses at the end of Surat al-Baqarah concerning usury were revealed, the Messenger of Allah ﷺ went out to the mosque and forbade trade in wine."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2226},{"key":"muslim","label":"مسلم","number":1580}]},{"num":5785,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: سمعت رسول اللّٰه ﷺ يخطب بالمدينة قال: (( يا أيها الناس، إن اللّه تعالى يعرض بالخمر، ولعل اللّٰه سينزل فيها أمرا، فمن كان عنده منها شيء فليبعه، ولينتفع به )). قال: فما لبثنا إلا يسيرا حتى قال النبي ﷺ: (( إن اللّٰه تعالى حرم الخمر، فمن أدركته هذه الآية، وعنده منها شيء فلا يشرب ولا يبع )). قال: فاستقبل الناس بما كان عندهم منها في طرق المدينة، فسفكوها."],"takhrij":"صحيح: رواه مسلم (١٥٧٨).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1578).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: I heard the Messenger of Allah ﷺ giving a sermon in Madinah and saying: “O people, Allah is indicating that wine will be forbidden, and perhaps Allah will soon reveal a command about it. Whoever has any of it should sell it and benefit from it.” We only waited a short while before the Prophet ﷺ said: “Allah has now forbidden wine. Whoever is reached by this verse while he still has any of it should neither drink it nor sell it.” The people then took what they had of it to the streets of Madinah and poured it out."]},"buhuth":{"ar":["قوله: (( يعرض بالخمر )) أي بحرمتها، والتعريض هو خلاف التصريح من القول، وهو قوله تعالى:","( يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ ۖ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإِثْمُهُمَا أَكْبَرُ مِن نَّفْعِهِمَا )","[البقرة: ٢١٩]","وقوله: (( فمن أدركته هذه الآية )) هي قوله تعالى:","( يَاأَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ )","[سورة المائدة: ٩٠]"],"en":["Explanation: His statement, “Allah is indicating concerning wine,” means He was hinting at its prohibition before the final explicit ruling. The verse referred to is: “They ask you about wine and gambling. Say: in them is great sin and some benefit for people, but their sin is greater than their benefit.”","[Surat al-Baqarah: 219]","And his saying, “Whoever is reached by this verse,” refers to the verse: “O you who believe, indeed wine, gambling, sacrificial stones, and divining arrows are filth from the work of Satan, so avoid them that you may succeed.”","[Surat al-Ma’idah: 90]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1578}]},{"num":5786,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن غنم أن الداري كان يهدي لرسول اللّٰه ﷺ كل عام راوية خمر، فلما كان عام حرمت جاء براوية، فلما نظر إليه نبي اللّٰه ﷺ ضحك، قال: (( هل شعرت أنها قد حرمت بعدك؟ )). قال: يا رسول الله، أفلا أبيعها فأنتفع بثمنها؟ فقال رسول اللّٰه ﷺ: (( لعن اللّٰه اليهود، انطلقوا إلى ما حرم عليهم من شحوم البقر والغنم، فأذابوه، فجعلوه ثمنا له، فباعوا به ما يأكلون، وإن الخمر حرام، وثمنها حرام، وإن الخمر حرام، وثمنها حرام، وإن الخمر حرام، وثمنها حرام ))."],"takhrij":"حسن: رواه أحمد (١٧٩٩٥).","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17995).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Rahman ibn Ghanm reported that al-Dari used to gift the Messenger of Allah ﷺ a skin of wine every year. When the year came in which it was forbidden, he brought one again. When the Prophet ﷺ saw it, he smiled and said: “Did you realize that it has been forbidden after your last visit?” He said: O Messenger of Allah ﷺ, may I not sell it and benefit from its price? The Messenger of Allah ﷺ said: “May Allah curse the Jews. They went to the fats of cattle and sheep that had been forbidden to them, melted them down, turned them into a saleable commodity, and used the money to buy what they ate. Wine is forbidden, and its price is forbidden.” He repeated that three times."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":17995,"n":17995}]},{"num":5787,"demo":false,"sanad":"","matn":["عن عامر بن ربيعة أن رجلا من ثقيف يكنى أبا تمام أهدى إلى رسول اللّٰه ﷺ راوية خمر، قال رسول اللّٰه ﷺ: (( إنها قد حرمت يا أبا تمام )). فقال له: يا رسول الله، أفأنفق ثمنها؟ فقال النبي ﷺ: (( إن الذي حرم شربها حرم ثمنها ))."],"takhrij":"صحيح: رواه الطبراني في الأوسط (٤٣٩).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat (439).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Amir ibn Rabi‘ah reported that a man from Thaqif, known as Abu Tammam, gave the Messenger of Allah ﷺ a skin of wine. The Messenger of Allah ﷺ said: “It has indeed been forbidden, O Abu Tammam.” He said: O Messenger of Allah ﷺ, may I at least spend its price? The Prophet ﷺ said: “The One who forbade drinking it also forbade its price.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":439},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":436,"n":434}]},{"num":5788,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: سمعت النبي ﷺ عام الفتح وهو بمكة يقول: (( إن اللّٰه ورسوله حرم بيع الخمر والميتة والخنزير )). فقيل: يا رسول الله، أرأيت شحوم الميتة فإنه يدهن بها السفن، ويدهن بها الجلود، ويستصبح بها الناس؟ فقال: (( لا، هي حرام )). ثم قال: (( قاتل اللّٰه يهود، إن اللّٰه لما حرم عليهم الشحوم جملوها، ثم باعوها، وأكلوا ثمنها ))."],"takhrij":"حسن: رواه أحمد (٦٩٩٧)، والبيهقي (٩/٣٥٥).","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6997) and al-Bayhaqi (9/355).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Amr ibn Shu‘ayb, from his father, from his grandfather, said: I heard the Prophet ﷺ say in Makkah during the Year of the Conquest: “Allah and His Messenger have forbidden the sale of wine, carrion, and pork.” It was said: O Messenger of Allah ﷺ, what about the fat of carrion, for ships are coated with it, skins are greased with it, and people use it for lamps? He said: “No, it is forbidden.” Then he said: “May Allah destroy the Jews. When Allah forbade fat to them, they melted it, sold it, and consumed its price.”"]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":9},{"key":"ahmad","label":"مسند الإمام أحمد","number":6997,"n":6997}]},{"num":5789,"demo":false,"sanad":"","matn":["عن عبد الواحد البناني قال: كنت مع ابن عمر، فجاءه رجل، فقال: يا أبا عبد الرحمن، إني أشتري هذه الحيطان تكون فيها الأعناب، فلا نستطيع أن نبيعها كلها عنبا حتى نعصره. قال: فمن ثمن الخمر تسألني؟ سأحدثك حديثا سمعته من رسول اللّٰه ﷺ، كنا جلوسا مع النبي ﷺ، إذ رفع رأسه إلى السماء، ثم أكب، ونكت في الأرض، وقال: (( الويل لبني إسرائيل )). فقال له عمر: يا نبي الله، لقد أفزعنا قولك لبني إسرائيل، فقال: (( ليس عليكم من ذلك بأس، إنهم لما حرمت عليهم الشحوم، فتواطئوه، فيبيعونه، فيأكلون ثمنه، وكذلك ثمن الخمر عليكم حرام ))."],"takhrij":"حسن: رواه أحمد (٥٩٨٢).","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (5982).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Wahid al-Banani said: I was with Ibn Umar when a man came to him and said: O Abu Abd al-Rahman, I buy vineyards with grapes on them, and we cannot sell all of them as grapes until we press them. He said: Are you asking me about the price of wine? I will tell you a hadith I heard from the Messenger of Allah ﷺ. We were sitting with the Prophet ﷺ when he raised his head to the sky, then lowered it and scratched the ground and said: “Woe to the Children of Israel.” Umar said: O Prophet ﷺ of Allah, your statement about the Children of Israel has alarmed us. He said: “That is not your issue. When fat was forbidden to them, they manipulated it, sold it, and consumed its price. Likewise, the price of wine is forbidden for you.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":5982,"n":5982}]},{"num":5790,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر قال: قال رسول اللّٰه ﷺ: (( لعنت الخمر على عشرة أوجه: بعينها، وعاصرها، ومعتصرها، وبائعها، ومبتاعها، وحاملها، والمحمولة إليه، وآكل ثمنها، وشاربها، وساقيها ))."],"takhrij":"حسن: رواه أبو داود (٣٦٧٤)، وابن ماجه (٣٣٨٠)، وأحمد (٤٧٨٧)، وابن أبي شيبة (٦/٤٤٧).","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3674), Ibn Majah (3380), Ahmad (4787), and Ibn Abi Shaybah (6/447).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd Allah ibn Umar reported that the Messenger of Allah ﷺ said: “Wine has been cursed in ten ways: in itself, the one who presses it, the one for whom it is pressed, the one who sells it, the one who buys it, the one who carries it, the one to whom it is carried, the one who consumes its price, the one who drinks it, and the one who serves it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3674},{"key":"ibnmajah","label":"ابن ماجه","number":3380},{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":4787,"n":4787},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":21625,"n":21608}]},{"num":5791,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن شريح الخولاني: أنه كان له عم يبيع الخمر، وكان يتصدق بثمنه، فنهيته عنها، فلم ينته، فقدمت المدينة، فلقيت ابن عباس، فسألته عن الخمر وثمنها، فقال: هي حرام، وثمنها حرام. ثم قال: يا معشر أمة محمد، إنه لو كان كتاب بعد كتابكم، أو نبي بعد نبيكم لأنزل فيكم، كما أنزل فيمن كان قبلكم، لكن لا كتاب بعد كتابكم، ولا نبي بعد نبيكم.","قال: ثم لقيت عبد اللّٰه بن عمر، فسألته عن ثمن الخمر، فقال: سأخبرك عن الخمر: أني كنت عند رسول اللّٰه ﷺ في المسجد، فبينما هو محتبي، حل حبوته، ثم قال: (( من كان عنده من الخمر شيء فليؤذني به )). فجعل الناس يأتونه، فيقول أحدهم: عندي راوية خمر، ويقول الآخر: عندي راوية، ويقول الآخر: عندي زق، أو ما شاء اللّٰه أن يكون عنده، فقال رسول اللّٰه ﷺ: (( اجمعوه ببقيع كذا وكذا ثم آذنوني ))، ففعلوا، ثم آذنوه. قال: فقمت، فمشيت - وهو متكئ علي -، فلحقنا أبو بكر، فأخذني رسول اللّٰه ﷺ فجعلني عن يساره، وجعل أبا بكر مكاني، ثم لحقنا عمر، فأخذني، وجعلني عن يساره، فمشى بينهما حتى إذا وقف على الخمر قال للناس: (( أتعرفون هذه؟ )) قالوا: نعم يا رسول الله، هذه الخمر. قال: (( صدقتم )). ثم قال: (( إن اللّٰه تعالى لعن الخمر، وعاصرها، ومعتصرها، وشاربها، وساقيها، وحاملها، والمحمولة إليه، وبائعها، ومشتريها، وآكل ثمنها )). ثم دعا بسكين، فقال: (( اشحذوها )). ففعلوا، ثم أخذها رسول اللّٰه ﷺ يخرق بها الزقاق. فقال الناس: إن في هذه الزقاق لمنفعة، فقال: (( أجل، ولكن إنما أفعل غضبا لله لما فيها من سخطه )). فقال عمر: أنا أكفيك يا رسول الله. قال: (( لا )). وبعضهم يزيد على بعض في الحديث."],"takhrij":"صحيح: رواه الحاكم (٧٢٢٨).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (7228).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Abd al-Rahman ibn Shurayh al-Khawlani said: I had an uncle who sold wine, and he used to give its price in charity. I forbade him from that, but he did not stop. Then I came to Madinah and met Ibn Abbas and asked him about wine and its price. He said: It is forbidden, and its price is forbidden. Then he said: O nation of Muhammad, if there had been another scripture after your scripture, or another prophet after your prophet, something like what was sent down upon those before you would have been sent down upon you. But there is no scripture after your scripture and no prophet after your prophet.","Then I met Abd Allah ibn Umar and asked him about the price of wine. He said: I will tell you about wine. I was with the Messenger of Allah ﷺ in the mosque. While he was sitting with his knees drawn up, he untied his posture and said: “Whoever has any wine should inform me of it.” People began coming to him. One said: I have a skin of wine. Another said: I have a container. Another said: I have a wineskin, or whatever Allah willed one of them to have. The Messenger of Allah ﷺ said: “Gather it in such-and-such place in the cemetery area, then inform me.” They did that and then informed him. I stood and walked while he was leaning on me. Abu Bakr joined us, so the Messenger of Allah ﷺ moved me to his left and put Abu Bakr in my place. Then Umar joined us, so he moved me to his left, and he walked between them until he stopped at the wine and said to the people: “Do you know what this is?” They said: Yes, O Messenger of Allah ﷺ, this is wine. He said: “You have spoken the truth.” Then he said: “Allah has cursed wine, the one who presses it, the one for whom it is pressed, the one who drinks it, the one who serves it, the one who carries it, the one to whom it is carried, the one who sells it, the one who buys it, and the one who consumes its price.” Then he asked for a knife and said: “Sharpen it.” They did so, and the Messenger of Allah ﷺ began cutting the wineskins open with it. The people said: There is some use in these skins. He said: “Yes, but I am only doing this out of anger for Allah because of what they contain of His displeasure.” Umar said: I will take care of it for you, O Messenger of Allah ﷺ. He said: “No.” Some narrators add more than others in this hadith."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":7228,"n":7231}]},{"num":5792,"demo":false,"sanad":"","matn":["عن أنس قال: لعن رسول اللّٰه ﷺ في الخمر عشرة: عاصرها، ومعتصرها، وشاربها، وحاملها، والمحمولة إليه، وساقيها، وبائعها، وآكل ثمنها، والمشتري لها، والمشتراة له."],"takhrij":"حسن: رواه الترمذي (١٢٩٥)، وابن ماجه (٣٣٨١). وقال الترمذي: “هذا حديث غريب”.","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1295) and Ibn Majah (3381). Al-Tirmidhi said: “This is a singularly transmitted hadith.”","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ cursed ten connected to wine: the one who presses it, the one for whom it is pressed, the one who drinks it, the one who carries it, the one to whom it is carried, the one who serves it, the one who sells it, the one who consumes its price, the one who buys it, and the one for whom it is bought."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1295},{"key":"ibnmajah","label":"ابن ماجه","number":3381}]},{"num":5793,"demo":false,"sanad":"","matn":["عن أنس قال: لما حرمت الخمر قال: إني يومئذ لأسقيهم، لأسقي أحد عشر رجلا، خمرا، فكفأتها وكفأ الناس آنيتهم بما فيها حتى كادت السكك أن تمتنع من ريحها.","قال أنس: وما خمرهم يومئذ إلا البسر والتمر مخلوطين.","قال: فجاء رجل إلى النبي ﷺ، فقال: إنه كان عندي مال يتيم فاشتريت به خمرا، أفتأذن لي أن أبيعها، فأرد على اليتيم ماله؟ فقال النبي ﷺ: (( قاتل اللّٰه اليهود، حرمت عليهم الثروب، فباعوها، وأحلوا أثمانها )). ولم يأذن لهم النبي ﷺ في بيع الخمر."],"takhrij":"صحيح: رواه أحمد (١٣٢٧٥)، وعبد الرزاق في مصنفه (١٦٩٧٠)، وابن حبان (٤٩٤٥).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (13275), Abd al-Razzaq in his Musannaf (16970), and Ibn Hibban (4945).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas said: When wine was forbidden, I was at that time serving it to them, serving eleven men. So I overturned it, and the people overturned their vessels with what was in them, until the streets almost became filled with its smell. Anas said: Their wine that day was only a mixture of unripe dates and dried dates.","Then a man came to the Prophet ﷺ and said: I had the wealth of an orphan, and I bought wine with it. Will you allow me to sell it so that I may return the orphan’s money? The Prophet ﷺ said: “May Allah destroy the Jews. Fat was forbidden to them, but they sold it and made its price lawful for themselves.” And the Prophet ﷺ did not permit them to sell wine."]},"buhuth":{"ar":["وقوله: (( الثروب )) جمع ثرب، وهو شحم رقيق."],"en":["Explanation: The word “al-thurub” refers to thin fat."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق/مصنفہ","label":"عبد الرزاق في مصنفه","number":16970},{"key":"ibnhibban","label":"ابن حبان","number":4945},{"key":"ahmad","label":"مسند الإمام أحمد","number":13275,"n":13275}]},{"num":5794,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن أبا طلحة سأل النبيَّ ﷺ عن أيتامٍ ورثوا خمرًا، فقال: (( أَهْرِيقُوهُ )). قال: أفلا نجعلها خَلًّا؟ قال: (( لا ))."],"takhrij":"حسن: رواه أبو داود (٣٦٧٥)، والترمذي (١٢٩٣) معلقًا، وأحمد (١٢١٨٩)، والطحاوي في مشكل الآثار (٣٣٣٧).","grade":"حسن","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3675), al-Tirmidhi (1293, suspended), Ahmad (12189), and al-Tahawi in Mushkil al-Athar (3337).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik reported that Abu Talhah asked the Prophet ﷺ about orphans who had inherited wine. He said, “Pour it out.” He asked, “May we not turn it into vinegar?” He said, “No.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3675},{"key":"tirmidhi","label":"الترمذي","number":1293},{"key":"الطحاوی/مشکل_الاثار","label":"الطحاوي في مشكل الآثار","number":3337},{"key":"ahmad","label":"مسند الإمام أحمد","number":12189,"n":12189}]},{"num":5795,"demo":false,"sanad":"","matn":["عن أسامة بن زيد قال: دخلنا على رسول اللّٰه ﷺ نعوده، وهو مريض، فوجدناه نائمًا، قد غطى وجهه ببُردٍ عدني، فكشف عن وجهه، ثم قال: (( لعن اللّٰه اليهود، يُحَرِّمُونَ شحوم الغنم، ويأكلون أثمانها ))."],"takhrij":"صحيح: رواه الحارث بن أبي أسامة -بغية الباحث (٤٣٣)-، وأبو نعيم في معرفة الصحابة (٢/١٨٣-١٨٤).","grade":"صحيح","chapter_ar":"باب تحريم بيع المحرمات من الخمر والخنزير والميتة والأصنام والدم! لأنها نجس عين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Harith ibn Abi Usamah in Bughyat al-Bahith (433), and Abu Nu‘aym in Ma‘rifat al-Sahabah (2/183–184).","chapter_en":"The prohibition of selling forbidden things such as wine, pork, carrion, idols, and blood, because they are inherently impure","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":30,"content":{"translation":{"en":["Usamah ibn Zayd said: We entered upon the Messenger of Allah ﷺ to visit him while he was ill. We found him sleeping, with his face covered by an Adeni cloak. He uncovered his face and then said, “May Allah curse the Jews. They make the fat of sheep unlawful, yet they consume its price.”"]}},"tuhfa":{},"refs":[{"key":"الحارث_بن_ابی_اسامہ_بغیہ_الباحث","label":"الحارث بن أبي أسامة -بغية الباحث","number":433},{"key":"ابو_نعیم/معرفہ_الصحابہ","label":"أبو نعيم في معرفة الصحابة","number":2}]},{"num":5796,"demo":false,"sanad":"","matn":["عن أبي مسعود الأنصاري أن رسول اللّٰه ﷺ نهى عن ثمن الكلب، ومهر البغي، وحلوان الكاهن."],"takhrij":"متفق عليه: رواه مالك (٦٨) والبخاري (٢٢٣٧)، ومسلم (١٥٦٧: ٣٩).","grade":"متفق عليه","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (68), al-Bukhari (2237), and Muslim (1567: 39).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari reported that the Messenger of Allah ﷺ forbade the price of a dog, the payment given to a prostitute, and the fee of a fortune-teller."]},"buhuth":{"ar":["وقوله: (( حلوان الكاهن )): الحلوان هو ما يُؤخذ بسهولة بلا تعب، والكاهن يأخذ أجرته على الكهانة بغير حق. ويقاس عليه كل مال يؤخذ بغير حق."],"en":["Explanation: “The fee of a fortune-teller” refers to money taken easily and wrongfully, without lawful effort. By analogy, this includes any unlawful payment taken without right."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":68},{"key":"bukhari","label":"البخاري","number":2237},{"key":"muslim","label":"مسلم","number":1567}]},{"num":5797,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال: سمعت رسول اللّٰه ﷺ يقول: (( شرُّ الكسب مهر البغي، وثمن الكلب، وكسب الحجام ))."],"takhrij":"صحيح: رواه مسلم (١٥٦٨). وفي رواية: (( ثمن الكلب خبيث، ومهر البغي خبيث، وكسب الحجام خبيث )).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1568). In another wording: “The price of a dog is filthy, the payment of a prostitute is filthy, and the earnings of a cupper are filthy.”","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Rafi‘ ibn Khadij reported that he heard the Messenger of Allah ﷺ say, “The worst earnings are the payment of a prostitute, the price of a dog, and the earnings of a cupper.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1568}]},{"num":5798,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس قال: نهى رسول اللّٰه ﷺ عن ثمن الكلب، وإن جاء يطلب ثمن الكلب فاملأ كفَّه ترابًا."],"takhrij":"صحيح: رواه أبو داود (٣٤٨٢)، وأحمد (٢٦٢٦، ٢٥١٢)، والبيهقي (٦/٦).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3482), Ahmad (2626, 2512), and al-Bayhaqi (6/6).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Messenger of Allah ﷺ forbade the price of a dog, and if its owner comes demanding its price, then fill his hands with dust."]},"buhuth":{"ar":["وفي لفظ: (( نهى رسول اللّٰه ﷺ عن ثمن الخمر، ومهر البغي، وثمن الكلب )). وقال: (( إذا جاء صاحبه يطلب ثمنه فاملأ كفيه ترابًا )).","ومعنى التراب: الحرمان والخيبة."],"en":["In another wording: “The Messenger of Allah ﷺ forbade the price of wine, the payment of a prostitute, and the price of a dog.” He said: “If its owner comes asking for its price, then fill his hands with dust.”","Explanation: The mention of dust means disappointment and deprivation."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3482},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":2626,"n":2626}]},{"num":5799,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى النبي ﷺ عن كسب الإماء."],"takhrij":"صحيح: رواه البخاري (٢٢٨٣).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2283).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ forbade the earnings of slave women."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2283}]},{"num":5800,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( لا يحل ثمن الكلب، ولا حلوان الكاهن، ولا مهر البغي ))."],"takhrij":"صحيح: رواه أبو داود (٣٤٨٤)، والنسائي (٤٢٩٣)، والبيهقي (٦/٦).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3484), al-Nasa’i (4293), and al-Bayhaqi (6/6).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said, “The price of a dog, the fee of a fortune-teller, and the payment of a prostitute are not lawful.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3484},{"key":"nasai","label":"النسائي","number":4293},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11010,"n":11104}]},{"num":5801,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ أنه نهى عن ثمن الكلب، ومهر البغي، وعَسْبِ الفحل."],"takhrij":"صحيح: رواه أحمد (١٠٤٩٠، ١٠٤٨٩)، وابن حبان (٤٩٤١).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (10490, 10489) and Ibn Hibban (4941).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ forbade the price of a dog, the payment of a prostitute, and the fee taken for the stud service of a male animal."]},"buhuth":{"ar":["وفي رواية زيادة: (( ثمن السنور )). وفي رواية أخرى زيادة: (( كسب الحجام ))."],"en":["In another narration there is an added wording: “the price of a cat.” In another: “the earnings of a cupper.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابن حبان","number":4941},{"key":"ahmad","label":"مسند الإمام أحمد","number":10490,"n":10490}]},{"num":5802,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ عن ثمن الكلب، وعَسْبِ الفحل."],"takhrij":"صحيح: رواه ابن ماجه (٢١٦٠)، والنسائي (٤٦٧٥).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2160) and al-Nasa’i (4675).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the price of a dog and the fee for the stud service of a male animal."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2160},{"key":"nasai","label":"النسائي","number":4675}]},{"num":5803,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبيَّ ﷺ نهى عن ثمن الكلب، وكسب الزمّارة."],"takhrij":"صحيح: رواه البغوي في شرح السنة (٢٠٣٨)، والبيهقي (٦/١٢٦).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Baghawi in Sharh al-Sunnah (2038) and al-Bayhaqi (6/126).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ forbade the price of a dog and the earnings of the woman who plays the pipe."]},"buhuth":{"ar":["وقوله: (( كسب الزمارة )): قيل هو مهر البغي، وقيل هو كسب المغنية بالمزمار."],"en":["Explanation: “The earnings of the pipe-player” has been explained as the payment of a prostitute, and it has also been explained as the earnings of a woman who sings with an instrument."]}},"tuhfa":{},"refs":[{"key":"البغوی/شرح_السنہ","label":"البغوي في شرح السنة","number":2038},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"sharhsunna","label":"شرح السنة للبغوي","number":2038,"n":2038}]},{"num":5804,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ عن كسب الأمة إلا أن يكون لها عمل حسن، أو كسب يعرف."],"takhrij":"حسن: رواه الطحاوي (١/٢٥٦)، والبيهقي (٨/٨).","grade":"حسن","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tahawi (1/256) and al-Bayhaqi (8/8).","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the earnings of a slave woman unless she had a respectable occupation or a known lawful trade."]},"buhuth":{"ar":["ويفهم من هذا الحديث أن المقصود بالنهي هو الكسب المحرم، أما إذا كانت تعمل عملا مباحا كالغزل والخياطة ونحوهما فلا بأس."],"en":["Explanation: This shows that the forbidden earning here is unlawful earning. If she works in a permissible trade such as spinning, sewing, and similar work, then there is no problem."]}},"tuhfa":{},"refs":[{"key":"الطحاوی","label":"الطحاوي","number":1},{"key":"البیہقی","label":"البيهقي","number":8},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15784,"n":15942}]},{"num":5805,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو قال: نهى رسول اللّٰه ﷺ عن ثمن الكلب، ومهر البغي، وأجر الكاهن، وكسب الحجام."],"takhrij":"صحيح: رواه الحاكم (٢٢٤٣). وكسب الحجام ليس بحرام، وإنما يحمل على كراهة التنزيه.","grade":"صحيح","chapter_ar":"باب النهي عن ثمن الكلب، ومهر البغي، وحلوان الكاهن، وأجر الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (2243). The earnings of a cupper are not considered unlawful; rather, this is understood as dislike, not prohibition.","chapter_en":"The prohibition of taking the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the wage of a cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":31,"content":{"translation":{"en":["Abdullah ibn Amr said: The Prophet ﷺ forbade the price of a dog, the payment of a prostitute, the fee of a fortune-teller, and the earnings of a cupper."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":2243,"n":2235}]},{"num":5806,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( خمس من الدواب ليس على المحرم في قتلهن جناح: الغراب، والحدأة، والعقرب، والفأرة، والكلب العقور ))."],"takhrij":"متفق عليه: رواه مالك (٨٨) والبخاري (١٨٢٦)، ومسلم (١١٩٩: ٧٦).","grade":"متفق عليه","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (88), al-Bukhari (1826), and Muslim (1199: 76).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “There is no sin upon a person in ihram in killing five harmful creatures: the crow, the kite, the scorpion, the rat, and the vicious dog.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":88},{"key":"bukhari","label":"البخاري","number":1826},{"key":"muslim","label":"مسلم","number":1199}]},{"num":5807,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر أن رسول اللّٰه ﷺ أمر بقتل الكلاب."],"takhrij":"متفق عليه: رواه مالك (١٤) والبخاري (٣٣٢٣)، ومسلم (١٥٧٠: ٤٣).","grade":"متفق عليه","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (14), al-Bukhari (3323), and Muslim (1570: 43).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ ordered that dogs be killed."]},"buhuth":{"ar":["ورواه مسلم من وجه آخر بلفظ: كان رسول اللّٰه ﷺ يأمر بقتل الكلاب، فننبعث في المدينة وأطرافها، فلا ندع كلبا إلا قتلناه، حتى إنا لتقتل كلب المرأة من أهل البادية يتبعها."],"en":["Muslim also narrates from another route: The Messenger of Allah ﷺ used to command the killing of dogs, so we would go through Madinah and its outskirts and would not leave any dog without killing it, until we even killed the dog belonging to a woman from the desert that followed her."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":14},{"key":"bukhari","label":"البخاري","number":3323},{"key":"muslim","label":"مسلم","number":1570}]},{"num":5808,"demo":false,"sanad":"","matn":["عن ابن عمر قال: أمر رسول اللّٰه ﷺ بقتل الكلاب، فأرسل في أقطار المدينة أن تُقتل."],"takhrij":"صحيح: رواه مسلم (١٥٧٠: ٤٤).","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1570: 44).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn Umar said: The Messenger of Allah ﷺ ordered dogs to be killed, and messengers were sent throughout the outskirts of Madinah for that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1570}]},{"num":5809,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ أمر بقتل الكلاب إلا كلب صيد، أو كلب غنم، أو ماشية. فقيل لابن عمر: إن أبا هريرة يقول: (( أو كلب زرع )). فقال ابن عمر: إن لأبي هريرة زرعًا."],"takhrij":"صحيح: رواه مسلم (١٥٧١).","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1571).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ ordered dogs to be killed except a hunting dog, or a dog for sheep, or livestock. It was said to Ibn Umar: Abu Hurayrah says, “or a dog for crops.” Ibn Umar replied: Abu Hurayrah had crops."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1571}]},{"num":5810,"demo":false,"sanad":"","matn":["عن جابر قال: أمرنا رسول اللّٰه ﷺ بقتل الكلاب، حتى إن المرأة تقدم من البادية بكلبها، فنقتله، ثم نهى النبي ﷺ عن قتلها، وقال: (( عليكم بالأسود البهيم ذي النقطتين؛ فإنه شيطان ))."],"takhrij":"صحيح: رواه مسلم (١٥٧٢).","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1572).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ commanded us to kill dogs, to the point that if a woman came from the desert with her dog, we would kill it. Then the Prophet ﷺ forbade killing them and said: “Kill the pure black one with the two spots, for it is a devil.”"]},"buhuth":{"ar":["وقوله: (( ذي النقطتين )): أي الذي له علامتان فوق عينيه."],"en":["Explanation: “The one with the two spots” means the dog that has two markings above its eyes."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1572}]},{"num":5811,"demo":false,"sanad":"","matn":["عن ابن المغفل قال: أمر رسول اللّٰه ﷺ بقتل الكلاب، ثم قال: (( ما بالهم، وبال الكلاب؟ )) ثم رخص في كلب الصيد والغنم."],"takhrij":"صحيح: رواه مسلم (١٥٧٣).","grade":"صحيح","chapter_ar":"باب الأمر بقتل الكلاب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1573).","chapter_en":"The command to kill dogs","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":32,"content":{"translation":{"en":["Ibn al-Mughaffal said: The Messenger of Allah ﷺ ordered that dogs be killed, then he said: “What is the matter with them and with dogs?” Then he allowed hunting dogs and dogs for sheep."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1573}]},{"num":5812,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( من اتخذ كلبا إلا كلب ماشية، أو صيد، أو زرع، انتقص من أجره كل يوم قيراط ))."],"takhrij":"صحيح: رواه مسلم (١٥٧٥: ٥٨).","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1575: 58).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog, except a dog for livestock, hunting, or crops, will have a qirat deducted from his reward every day.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1575}]},{"num":5813,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( من أمسك كلبا فإنه ينقص كل يوم من عمله قيراط إلا كلب حرث أو ماشية )).","وقال ابن سيرين وأبو صالح، عن أبي هريرة، عن النبي ﷺ: (( إلا كلب غنم، أو حرث، أو صيد )).","وقال أبو حازم، عن أبي هريرة، عن النبي ﷺ: (( كلب صيد أو ماشية ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٢٢)، ومسلم (١٥٧٥: ٥٩). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2322) and Muslim (1575: 59). This wording is from al-Bukhari.","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog will have a qirat deducted from his deeds every day, except a dog for farming or livestock.”","Ibn Sirin and Abu Salih narrated from Abu Hurayrah from the Prophet ﷺ: “except a dog for sheep, farming, or hunting.”","Abu Hazim narrated from Abu Hurayrah from the Prophet ﷺ: “a hunting dog or a dog for livestock.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2322},{"key":"muslim","label":"مسلم","number":1575}]},{"num":5814,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( من اقتنى كلبا إلا كلبا ضاريا، أو كلب ماشية، نقص من عمله كل يوم قيراطان ))."],"takhrij":"متفق عليه: رواه مالك (١٣) والبخاري (٥٤٨٢)، ومسلم (١٥٧٤).","grade":"متفق عليه","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (13), al-Bukhari (5482), and Muslim (1574).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog, except a trained hunting dog or a dog for livestock, will have two qirats deducted from his deeds every day.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":13},{"key":"bukhari","label":"البخاري","number":5482},{"key":"muslim","label":"مسلم","number":1574}]},{"num":5815,"demo":false,"sanad":"","matn":["عن ابن عمر، عن رسول اللّٰه ﷺ قال: (( من اقتنى كلبا إلا كلب ضار، أو ماشية، نقص من عمله كل يوم قيراطان ))."],"takhrij":"صحيح: رواه مسلم (١٥٧٤: ٥٤). والكلب الضاري هو الكلب المعلم للصيد.","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1574: 54).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “Whoever keeps a dog, except a trained hunting dog or a dog for livestock, will have two qirats deducted from his deeds every day.”"]},"buhuth":{"en":["The trained dog means the dog trained for hunting."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1574}]},{"num":5816,"demo":false,"sanad":"","matn":["عن ابن عمر يحدث عن النبي ﷺ قال: (( من اتخذ كلبا إلا كلب زرع، أو غنم، أو صيد، ينتقص من أجره كل يوم قيراط ))."],"takhrij":"صحيح: رواه مسلم (١٥٧٤: ٥٦).","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1574: 56).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Ibn Umar narrated from the Prophet ﷺ: “Whoever keeps a dog, except a dog for crops, sheep, or hunting, will have a qirat deducted from his reward every day.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1574}]},{"num":5817,"demo":false,"sanad":"","matn":["عن سفيان بن أبي زهير - وهو رجل من أزد شنوءة من أصحاب رسول اللّٰه ﷺ - وهو يحدث ناسا معه عند باب المسجد، فقال: سمعت رسول اللّٰه ﷺ يقول: (( من اقتنى كلبا لا يغني عنه زرعا، ولا ضرعا، نقص من عمله كل يوم قيراط )). قالوا: أنت سمعت هذا من رسول اللّٰه ﷺ؟ فقال: أي ورب هذا المسجد."],"takhrij":"متفق عليه: رواه مالك (١٢) والبخاري (٢٣٢٣)، ومسلم (١٥٧٦).","grade":"متفق عليه","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (12), al-Bukhari (2323), and Muslim (1576).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Sufyan ibn Abi Zuhayr, one of the Companions of the Messenger of Allah ﷺ from Azd Shanu’ah, was speaking to some people near the mosque door and said: I heard the Messenger of Allah ﷺ say: “Whoever keeps a dog that serves neither crops nor livestock will have a qirat deducted from his deeds every day.” They said: Did you hear this from the Messenger of Allah ﷺ? He said: Yes, by the Lord of this mosque."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":12},{"key":"bukhari","label":"البخاري","number":2323},{"key":"muslim","label":"مسلم","number":1576}]},{"num":5818,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مغفل قال: إني لممن يرفع أغصان الشجرة عن وجه رسول اللّٰه ﷺ وهو يخطب، فقال: (( لولا أن الكلاب أمة من الأمم لأمرت بقتلها، فاقتلوا منها كل أسود بهيم، وما من أهل بيت يرتبطون كلبا إلا نقص من عملهم كل يوم قيراط، إلا كلب صيد أو كلب حرث أو كلب غنم ))."],"takhrij":"صحيح: رواه أبو داود (٢٨٤٥)، والترمذي (١٤٨٦)، والنسائي (٤٢٨٠)، وابن ماجه (٣٢٠٥).","grade":"صحيح","chapter_ar":"باب تحريم اقتناء الكلب إلا كلب ماشية أو صيد أو زرع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2845), al-Tirmidhi (1486), al-Nasa’i (4280), and Ibn Majah (3205).","chapter_en":"The prohibition of keeping a dog except for livestock, hunting, or crops","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":33,"content":{"translation":{"en":["Abdullah ibn Mughaffal said: I was among those who used to lift tree branches away from the face of the Messenger of Allah ﷺ while he was giving a sermon. He said: “Were it not that dogs are a community among the communities, I would have commanded that they all be killed. So kill every completely black dog. No household keeps a dog except that a qirat is deducted from their deeds every day, except for a hunting dog, a farming dog, or a dog for sheep.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2845},{"key":"tirmidhi","label":"الترمذي","number":1486},{"key":"nasai","label":"النسائي","number":4280},{"key":"ibnmajah","label":"ابن ماجه","number":3205}]},{"num":5819,"demo":false,"sanad":"","matn":["عن أبي الزبير قال: سألت جابرًا عن ثمن الكلب والسنور، قال: زجر النبي ﷺ عن ذلك."],"takhrij":"صحيح: رواه مسلم (١٥٦٩).","grade":"صحيح","chapter_ar":"باب النهي عن ثمن السنور والكلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1569).","chapter_en":"The prohibition of the price of a cat and a dog","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":34,"content":{"translation":{"en":["Abu al-Zubayr said: I asked Jabir about the price of a dog and a cat. He said: The Prophet ﷺ strongly forbade that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1569}]},{"num":5820,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( والذي نفسي بيده ليوشكن أن ينزل فيكم ابن مريم حكما مقسطا، فيكسر الصليب، ويقتل الخنزير، ويضع الجزية، ويفيض المال حتى لا يقبله أحد ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢٢٢)، ومسلم (١٥٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتل الخنزير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2222) and Muslim (155).","chapter_en":"What has come regarding killing the pig","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":35,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “By the One in Whose hand is my soul, the son of Mary will soon descend among you as a just ruler. He will break the cross, kill the pig, abolish the tribute-tax, and wealth will become so abundant that no one will accept it.”"]},"buhuth":{"ar":["وقوله: (( ويضع الجزية )) أي لا يقبل إلا الإسلام."],"en":["Explanation: “He will abolish the tribute-tax” means that only Islam will be accepted then."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2222},{"key":"muslim","label":"مسلم","number":155}]},{"num":5821,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( قال الله: ثلاثة أنا خصمهم يوم القيامة: رجل أعطى بي ثم غدر، ورجل باع حرا فأكل ثمنه، ورجل استأجر أجيرا فاستوفى منه ولم يعطه أجره ))."],"takhrij":"صحيح: رواه البخاري (٢٢٢٧).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الإنسان الحر","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2227).","chapter_en":"The prohibition of selling a free person","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":36,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: Allah said: “There are three whose opponent I will be on the Day of Resurrection: a man who gives a pledge by Me and then betrays it, a man who sells a free person and consumes his price, and a man who hires a laborer, takes his full work, and does not give him his wage.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2227}]},{"num":5822,"demo":false,"sanad":"","matn":["عن سعيد بن أبي الحسن قال:","كنت عند ابن عباس رضي الله عنهما إذ أتاه رجل، فقال:","يا أبا عباس، إني إنسان إنما معيشتي من صنعة يدي، وإني أصنع هذه التصاوير.","فقال ابن عباس:","لا أحدثك إلا ما سمعت من رسول الله ﷺ يقول:","«مَنْ صَوَّرَ صُورَةً فَإِنَّ اللَّهَ مُعَذِّبُهُ حَتَّى يَنْفُخَ فِيهَا الرُّوحَ، وَلَيْسَ بِنَافِخٍ فِيهَا أَبَدًا».","فربا الرجل ربوة شديدة، واصفر وجهه.","فقال:","ويحك! إن أبيت إلا أن تصنع، فعليك بهذا الشجر، كل شيء ليس فيه روح."],"takhrij":"متفق عليه: رواه البخاري (٢٢٢٥)، ومسلم (٢١١٠/٩٩)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تحريم بيع الصور التي فيها روح","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2225) and Muslim (2110/99). This is the wording of al-Bukhārī.","chapter_en":"The prohibition of selling images of animate beings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":37,"content":{"translation":{"en":["Saʿīd ibn Abī al-Ḥasan reported:","I was with Ibn ʿAbbās, may Allah be pleased with them both, when a man came to him and said:","“O Abū ʿAbbās, I am a man whose livelihood comes only from the work of my hands, and I make these images.”","Ibn ʿAbbās said:","“I will tell you only what I heard the Messenger of Allah ﷺ say:","‘Whoever makes an image, Allah will punish him until he breathes a soul into it, and he will never be able to breathe a soul into it.’”","The man became extremely distressed and his face turned pale.","Ibn ʿAbbās said:","“Woe to you! If you insist on making something, then make trees and everything that does not possess a soul.”"]},"buhuth":{"ar":["ولفظ المرفوع عند مسلم:","«كُلُّ مُصَوِّرٍ فِي النَّارِ، يُجْعَلُ لَهُ بِكُلِّ صُورَةٍ صَوَّرَهَا نَفْسٌ فَتُعَذِّبُهُ فِي جَهَنَّمَ»."],"en":["The directly attributed wording in Muslim states:","“Every image-maker will be in the Fire. For every image he made, a soul will be created which will punish him in Hell.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2225},{"key":"muslim","label":"مسلم","number":2110}]},{"num":5823,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( لا يمنع فضل الماء ليمنع به الكلأ ))."],"takhrij":"متفق عليه: رواه مالك (٢٩) والبخاري (٢٣٥٣)، ومسلم (١٥٦٦: ٣٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (29), al-Bukhari (2353), and Muslim (1566: 36).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Surplus water must not be withheld in order to prevent access to pasture.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":29},{"key":"bukhari","label":"البخاري","number":2353},{"key":"muslim","label":"مسلم","number":1566}]},{"num":5824,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: نهى رسول اللّٰه ﷺ عن بيع فضل الماء."],"takhrij":"صحيح: رواه مسلم (١٥٦٥).","grade":"صحيح","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1565).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Jabir ibn Abd Allah said: The Messenger of Allah ﷺ forbade selling surplus water."]},"buhuth":{"ar":["ورواه أيضًا من طريق آخر بلفظ: (( نهى رسول اللّٰه ﷺ عن بيع ضراب الجمل، وعن بيع الماء والأرض لتحرث ))."],"en":["In another wording: “The Messenger of Allah ﷺ forbade selling the stud service of a camel, and selling water and land for cultivation.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1565}]},{"num":5825,"demo":false,"sanad":"","matn":["عن إياس بن عبد المزني وكان من أصحاب النبي ﷺ قال: نهى رسول اللّٰه ﷺ عن بيع فضل الماء."],"takhrij":"صحيح: رواه أبو داود (٣٤٧٨)، والترمذي (١٢٧١)، والنسائي (٤٦٦٢)، وابن ماجه (٢٤٧١)، والدارمي (٢٦٥٤).","grade":"صحيح","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3478), al-Tirmidhi (1271), al-Nasa’i (4662), Ibn Majah (2471), and al-Darimi (2654).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Iyas ibn Abd al-Muzani, who was one of the Companions of the Prophet ﷺ, said: The Messenger of Allah ﷺ forbade selling surplus water."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3478},{"key":"tirmidhi","label":"الترمذي","number":1271},{"key":"nasai","label":"النسائي","number":4662},{"key":"ibnmajah","label":"ابن ماجه","number":2471},{"key":"darimi","label":"الدارمي","number":2654}]},{"num":5826,"demo":false,"sanad":"","matn":["عن عائشة قالت: نهى رسول اللّٰه ﷺ أن يمنع نقع البئر، يعني فضل الماء."],"takhrij":"حسن: رواه أحمد (٢٦٣١١)، وابن حبان (٤٩٥٥).","grade":"حسن","chapter_ar":"باب النهي عن فضل الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (26311) and Ibn Hibban (4955).","chapter_en":"The prohibition regarding surplus water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":38,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ forbade preventing the use of the remaining water of a well, meaning its surplus water."]},"buhuth":{"ar":["وقوله: (( نقع البئر )) يعني ما بقي فيها من الماء بعد حاجة صاحبها."],"en":["Explanation: “The remaining water of the well” means the water left after the owner has taken what he needs."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":26311,"n":26311},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2371,"n":2368}]},{"num":5827,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ:","«ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلَا يَنْظُرُ إِلَيْهِمْ، وَلَا يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ: رَجُلٌ عَلَى فَضْلِ مَاءٍ بِالْفَلَاةِ يَمْنَعُهُ مِنِ ابْنِ السَّبِيلِ، وَرَجُلٌ بَايَعَ رَجُلًا بِسِلْعَةٍ بَعْدَ الْعَصْرِ فَحَلَفَ لَهُ بِاللَّهِ لَأَخَذَهَا بِكَذَا وَكَذَا فَصَدَّقَهُ وَهُوَ عَلَى غَيْرِ ذَلِكَ، وَرَجُلٌ بَايَعَ إِمَامًا لَا يُبَايِعُهُ إِلَّا لِدُنْيَا، فَإِنْ أَعْطَاهُ مِنْهَا وَفَى، وَإِنْ لَمْ يُعْطِهِ مِنْهَا لَمْ يَفِ»."],"takhrij":"متفق عليه: رواه البخاري (٢٣٥٨)، ومسلم (١٠٨)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب إثم من منع ابن السبيل من الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2358) and Muslim (108). This is Muslim’s wording.","chapter_en":"The sin of preventing a traveler from water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":39,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said:","“There are three whom Allah will neither speak to on the Day of Resurrection, nor look at, nor purify, and they will have a painful punishment: a man who has surplus water in the open desert and withholds it from a traveler; a man who sells merchandise to another man after ʿAṣr and swears by Allah that he had been offered such-and-such for it, so the buyer believes him although he is lying; and a man who pledges allegiance to a ruler only for worldly gain—if the ruler gives him something from it, he remains faithful, but if he does not give him anything from it, he does not remain faithful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2358},{"key":"muslim","label":"مسلم","number":108}]},{"num":5828,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال:","«ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ، وَلَا يَنْظُرُ إِلَيْهِمْ: رَجُلٌ حَلَفَ عَلَى سِلْعَةٍ لَقَدْ أُعْطِيَ بِهَا أَكْثَرَ مِمَّا أُعْطِيَ وَهُوَ كَاذِبٌ، وَرَجُلٌ حَلَفَ عَلَى يَمِينٍ كَاذِبَةٍ بَعْدَ الْعَصْرِ لِيَقْتَطِعَ بِهَا مَالَ رَجُلٍ مُسْلِمٍ، وَرَجُلٌ مَنَعَ فَضْلَ مَاءٍ، فَيَقُولُ اللَّهُ: الْيَوْمَ أَمْنَعُكَ فَضْلِي، كَمَا مَنَعْتَ فَضْلَ مَا لَمْ تَعْمَلْ يَدَاكَ»."],"takhrij":"صحيح: رواه البخاري (٧٤٤٦، ٢٣٦٩).","grade":"صحيح","chapter_ar":"باب إثم من منع ابن السبيل من الماء","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7446, 2369).","chapter_en":"The sin of preventing a traveler from water","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":39,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said:","“There are three whom Allah will neither speak to on the Day of Resurrection nor look at: a man who swears concerning merchandise that he was offered more for it than he actually was, while he is lying; a man who swears a false oath after ʿAṣr in order to wrongfully take the wealth of a Muslim; and a man who withholds surplus water.","Allah will say: ‘Today I will withhold My bounty from you, just as you withheld the surplus of that which your own hands did not produce.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7446}]},{"num":5829,"demo":false,"sanad":"","matn":["عن أبي خداش حبان بن زيد الشرعبي، عن رجل من قَرَن -وفي رواية: عن رجل من المهاجرين من أصحاب النبي ﷺ- قال: غزوت مع النبي ﷺ ثلاثا أسمعه يقول: (( المسلمون شركاء في ثلاث: في الكلأ، والماء، والنار ))."],"takhrij":"صحيح: رواه أبو داود (٣٤٧٧).","grade":"صحيح","chapter_ar":"باب المسلمون شركاء في ثلاثة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3477).","chapter_en":"Muslims are partners in three things","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":40,"content":{"translation":{"en":["Abu Khidash Hibban ibn Zayd al-Shara‘bi narrated from a man of Qaran — and in another narration, from a man among the Emigrants from the Companions of the Prophet ﷺ — who said: I went on three expeditions with the Prophet ﷺ, and I heard him say: “Muslims are partners in three things: pasture, water, and fire.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3477}]},{"num":5830,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال:","«ثَلَاثٌ لَا يُمْنَعْنَ: الْمَاءُ، وَالْكَلَأُ، وَالنَّارُ»."],"takhrij":"صحيح: رواه ابن ماجه (٢٤٧٣).","grade":"صحيح","chapter_ar":"باب المسلمون شركاء في ثلاثة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (2473).","chapter_en":"Muslims are partners in three things","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":40,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said:","“Three things are not to be withheld: water, pasture, and fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2473}]},{"num":5831,"demo":false,"sanad":"","matn":["عن رافع بن خديج قال: سمعت النبيَّ ﷺ يقول: (( شرُّ الكسب مهرُ البغي، وثمنُ الكلب، وكسبُ الحجام ))."],"takhrij":"صحيح: رواه مسلم (٤٠: ١٥٦٨)، ورواه (٤١) من وجه آخر بلفظ: (( ثمن الكلب خبيث، ومهر البغي خبيث، وكسب الحجام خبيث )).","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن كسب الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1568: 40). He also narrated it (41) through another route with the wording: “The price of a dog is vile, the payment of a prostitute is vile, and the earnings of a cupper are vile.”","chapter_en":"What has been narrated regarding the discouragement of the cupper’s earnings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":41,"content":{"translation":{"en":["Rafi‘ ibn Khadij said: I heard the Prophet ﷺ say, “The worst earnings are the payment of a prostitute, the price of a dog, and the earnings of a cupper.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":40},{"key":"رواہ","label":"رواه","number":41}]},{"num":5832,"demo":false,"sanad":"","matn":["عن أبي مسعود عقبة بن عمرو قال: نهى رسول اللّٰه ﷺ عن كسب الحجام."],"takhrij":"حسن: رواه ابن ماجه (٢١٦٥).","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن كسب الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2165).","chapter_en":"What has been narrated regarding the discouragement of the cupper’s earnings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":41,"content":{"translation":{"en":["Abu Mas‘ud ‘Uqbah ibn ‘Amr said: The Messenger of Allah ﷺ forbade the earnings of a cupper."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2165}]},{"num":5833,"demo":false,"sanad":"","matn":["عن جابر أن النبيَّ ﷺ سئل عن كسب الحجام، فقال: (( اعلفه ناضحك ))."],"takhrij":"صحيح: رواه أحمد (١٥٠٧٩، ١٤٢٩٠)، وأبو يعلى (٢١١٤). والناضح هو البعير.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن كسب الحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (15079, 14290) and Abu Ya‘la (2114).","chapter_en":"What has been narrated regarding the discouragement of the cupper’s earnings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":41,"content":{"translation":{"en":["Jabir reported that the Prophet ﷺ was asked about the earnings of a cupper, and he said, “Feed it to your water-carrying camel.”"]},"buhuth":{"en":["The word nadih means a camel used for drawing water."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":2114},{"key":"ahmad","label":"مسند الإمام أحمد","number":15079,"n":15079},{"key":"sh12520","label":"مسند أبي يعلى","number":2114,"n":2116}]},{"num":5834,"demo":false,"sanad":"","matn":["عن أنس أنه قال: احتجم رسول اللّٰه ﷺ حجمه أبو طيبة، فأمر له رسول اللّٰه ﷺ بصاع من تمر، وأمر أهله أن يُخَفِّفُوا عنه من خراجه."],"takhrij":"صحيح: رواه مالك (٢٦) والبخاري (٢٢١٠). ورواه مسلم (٦٢: ١٥٧٧) من وجه آخر عن أنس أنه سئل عن أجر الحجام؟ فقال: احتجم رسول اللّٰه ﷺ، حجمه أبو طيبة، وأعطاه صاعين من طعام، وكلم مواليه، فخففوا عنه، وقال: (( إن أمثل ما تداويتم به الحجامة، والقسط البحري )). واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (26) and al-Bukhari (2210). Muslim (1577: 62) also narrated through another route from Anas that he was asked about the wage of a cupper, so he said: The Messenger of Allah ﷺ had cupping done by Abu Taybah, and he gave him two sa‘s of food, and he spoke to his masters so they reduced his burden. He also said: “Among the best remedies you use are cupping and sea costus.” This wording is from al-Bukhari.","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ had cupping done, and Abu Taybah cupped him. The Messenger of Allah ﷺ ordered that he be given a sa‘ of dates, and he told his family to reduce his tax burden."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":26},{"key":"bukhari","label":"البخاري","number":2210},{"key":"ورواہ_مسلم","label":". ورواه مسلم","number":62}]},{"num":5835,"demo":false,"sanad":"","matn":["عن ابن عباس قال: حجم النبيَّ ﷺ عبدٌ لبني بياضة، فأعطاه النبيُّ ﷺ أجره، وكلم سيده، فخفف عنه من ضريبته، ولو كان سحتًا لم يعطه النبيُّ ﷺ."],"takhrij":"صحيح: رواه مسلم (٦٦: ١٢٠٢)، ورواه البخاري (٢١٠٣) بلفظ: احتجم النبي ﷺ، وأعطى الذي حجمه، ولو كان حرامًا لم يعطه.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1202: 66). Al-Bukhari (2103) narrated it with the wording: “The Prophet ﷺ had cupping done and gave the one who cupped him payment. If it had been unlawful, he would not have given it.”","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Ibn ‘Abbas said: A slave belonging to Banu Bayadah cupped the Prophet ﷺ, so the Prophet ﷺ gave him his wage and spoke to his master, who then reduced his levy. If it had been unlawful, the Prophet ﷺ would not have given it to him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":66},{"key":"bukhari","label":"البخاري","number":2103}]},{"num":5836,"demo":false,"sanad":"","matn":["عن محيصة أنه سأل النبيَّ ﷺ عن كسب حجامٍ له، فنهاه عنه. فلم يزل به يكلمه حتى قال: (( اعلفه ناضحك، وأطعمه رقيقك ))."],"takhrij":"صحيح: رواه أحمد (٢٣٦٩٣)، والشافعي في المسند (٢/١٦٦)، والحميدي (٨٧٨)، والبيهقي (٩/٣٣٧).","grade":"صحيح","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23693), al-Shafi‘i in al-Musnad (2/166), al-Humaydi (878), and al-Bayhaqi (9/337).","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Muhayyisah asked the Prophet ﷺ about the earnings of a cupper he had. He discouraged him from it. Muhayyisah kept speaking to him until he said, “Feed it to your camel and feed it to your servants.”"]}},"tuhfa":{},"refs":[{"key":"الشافعی/المسند","label":"الشافعي في المسند","number":2},{"key":"الحمیدی","label":"الحميدي","number":878},{"key":"البیہقی","label":"البيهقي","number":9},{"key":"ahmad","label":"مسند الإمام أحمد","number":23693,"n":23693}]},{"num":5837,"demo":false,"sanad":"","matn":["عن محيصة بن مسعود الأنصاري أنه كان له غلام حجام يقال له: نافع أبو طيبة، فانطلق إلى رسول اللّٰه ﷺ يسأله عن خراجه، فقال: (( لا تقربه )). فردد على رسول الله ﷺ فقال: (( اعلف به الناضح، واجعله في كِرَشه ))."],"takhrij":"حسن: رواه الإمام أحمد (٢٣٦٨٩) والطبراني في الكبير (٢٠/٣١٢) والبخاري في التاريخ الكبير (٨/٥٣-٥٤).","grade":"حسن","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23689), al-Tabarani in al-Kabir (20/312), and al-Bukhari in al-Tarikh al-Kabir (8/53–54).","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Muhayyisah ibn Mas‘ud al-Ansari had a slave cupper named Nafi‘ Abu Taybah. He went to the Messenger of Allah ﷺ to ask him about his earnings. He said, “Do not use it.” He kept repeating the question to the Messenger of Allah ﷺ, so he said, “Feed it to the water-carrying camel and put it into its fodder.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":23689},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":20},{"key":"bukhari/التاریخ_الکبیر","label":"البخاري في التاريخ الكبير","number":8},{"key":"ahmad","label":"مسند الإمام أحمد","number":23689,"n":23689}]},{"num":5838,"demo":false,"sanad":"","matn":["عن علي قال: احتجم رسول اللّٰه ﷺ وأمرني أن أعطي الحجام أجره."],"takhrij":"حسن: رواه أبو داود الطيالسي (١٤٨)، وابن ماجه (٢١٦٣)، وأحمد (٦٩٢)، والبيهقي (٩/٣٣٨).","grade":"حسن","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud al-Tayalisi (148), Ibn Majah (2163), Ahmad (692), and al-Bayhaqi (9/338).","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["‘Ali said: The Messenger of Allah ﷺ had cupping done and ordered me to give the cupper his wage."]}},"tuhfa":{},"refs":[{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسي","number":148},{"key":"ibnmajah","label":"ابن ماجه","number":2163},{"key":"البیہقی","label":"البيهقي","number":9},{"key":"ahmad","label":"مسند الإمام أحمد","number":692,"n":692}]},{"num":5839,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: دعا النبيُّ ﷺ أبا طيبة فحجمه، قال: فسأله: (( كم ضريبتك؟ )). قال: ثلاثة آصع. قال: فوضع عنه صاعًا."],"takhrij":"صحيح: رواه أحمد (١٤٨٠٩)، وأبو يعلى (١٧٧٧). ورواه ابن حبان في صحيحه (٣٥٣٦) من وجه آخر عن جابر بن عبد الله أن النبي ﷺ أمر أبا طيبة أن يأتيه مع غيبوبة الشمس، فأمره أن يضع المحاجم مع إفطار الصائم، فحجمه، ثم سأله: (( كم خراجك؟ )) قال: صاعين، فوضع النبي ﷺ عنه صاعًا.","grade":"صحيح","chapter_ar":"باب ما جاء في جواز إعطاء الأجرة للحجام","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (14809) and Abu Ya‘la (1777). Ibn Hibban also narrated it in his Sahih (3536) through another route from Jabir ibn ‘Abd Allah, stating that the Prophet ﷺ told Abu Taybah to come to him at sunset. He ordered him to place the cupping instruments at the time the fasting person breaks the fast, and he cupped him. Then he asked, “How much is your tax?” He replied, “Two sa‘s,” so the Prophet ﷺ reduced it by one sa‘.","chapter_en":"What has been narrated regarding the permissibility of paying the cupper","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":42,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ called Abu Taybah and he cupped him. Then he asked him, “How much is your levy?” He replied, “Three sa‘s.” So he reduced it for him by one sa‘."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":1777},{"key":"ورواہ_ابن_حبان/صحیحہ","label":". ورواه ابن حبان في صحيحه","number":3536},{"key":"ahmad","label":"مسند الإمام أحمد","number":14809,"n":14809},{"key":"sh12520","label":"مسند أبي يعلى","number":1777,"n":1776}]},{"num":5840,"demo":false,"sanad":"","matn":["عن ابن عمر قال: نهى النبيُّ ﷺ عن عسب الفحل."],"takhrij":"صحيح: رواه البخاري (٢٢٨٤).","grade":"صحيح","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2284).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ forbade taking payment for the stud service of a male animal."]},"buhuth":{"ar":["قوله: (( عسب الفحل )): الفحل هو الذكر من كل حيوان، فرسًا كان أو جملًا أو تيسًا أو غير ذلك، وعسبه هو ماؤه، ويطلق أيضًا على ضرابه."],"en":["Explanation: The male animal here means the male of any animal, whether a horse, camel, goat, or otherwise. Its stud service refers to its mating service."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2284}]},{"num":5841,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: نهى رسول اللّٰه ﷺ عن بيع ضراب الجمل، وعن بيع الماء والأرض لتُحرث. فعن ذلك نهى النبي ﷺ."],"takhrij":"صحيح: رواه مسلم (٣٥: ١٥٦٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1565: 35).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ forbade selling the mating service of a camel, and selling water and land for cultivation. It was this that the Prophet ﷺ forbade."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":35}]},{"num":5842,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ عن كسب الحجام، وكسب البغي، وثمن الكلب، وعسب الفحل."],"takhrij":"حسن: رواه النسائي (٤٦٧٣)، وأحمد (٧٩٧٦). واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4673) and Ahmad (7976). This wording is from Ahmad.","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the earnings of a cupper, the earnings of a prostitute, the price of a dog, and payment for the stud service of a male animal."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4673},{"key":"ahmad","label":"مسند الإمام أحمد","number":7976,"n":7976}]},{"num":5843,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ عن ثمن الكلب، وعسب الفحل."],"takhrij":"صحيح: رواه ابن ماجه (٢١٦٠)، والنسائي (٤٦٧٥)، والدارمي (٢٦٦٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2160), al-Nasa’i (4675), and al-Darimi (2665).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade the price of a dog and payment for the stud service of a male animal."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2160},{"key":"nasai","label":"النسائي","number":4675},{"key":"darimi","label":"الدارمي","number":2665}]},{"num":5844,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: نهى رسول اللّٰه ﷺ عن عسب الفحل."],"takhrij":"حسن: رواه النسائي (٤٦٧٤)، والدارقطني (٤٧١٣)، والبيهقي (٥/٣٣٩).","grade":"حسن","chapter_ar":"باب النهي عن بيع عسب الفحل وضرابه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4674), al-Daraqutni (4713), and al-Bayhaqi (5/339).","chapter_en":"The prohibition of selling the stud service of a male animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":43,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ forbade payment for the stud service of a male animal."]},"buhuth":{"ar":["قوله: (( عسب الفحل )): هو الأجرة على النزو، وهو محرم بالإجماع. وأما إعارة الفحل لذلك فجائزة، بل ثبت في الصحيح: (( من حق الإبل إعارة فحلها ))، وفي لفظ: (( إطراق فحلها ))."],"en":["Explanation: This means taking payment for the animal’s mating service, and it is prohibited by consensus. But lending the male animal for breeding without payment is permissible. It is authentically reported: “Among the rights of camels is lending their male for breeding,” and in another wording: “Allowing the use of their male for mating.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4674},{"key":"الدارقطنی","label":"الدارقطني","number":4713},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"sh9771","label":"سنن الدارقطني","number":2839,"n":2848},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10854,"n":10948}]},{"num":5845,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن رجلًا من كلاب سأل النبيَّ ﷺ عن عسب الفحل، فنهاه، قال: يا رسول الله، إنا نطرق الفحل فنكرم، فرخص له في الكرامة."],"takhrij":"صحيح: رواه الترمذي (١٢٧٤) وحسّنه، والنسائي (٤٦٧٢)، والبيهقي (٥/٣٣٩).","grade":"صحيح","chapter_ar":"باب ما جاء من الرخصة في ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1274), who graded it Hasan, al-Nasa’i (4672), and al-Bayhaqi (5/339).","chapter_en":"What has been narrated regarding a concession in that","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":44,"content":{"translation":{"en":["Anas ibn Malik reported that a man from Banu Kilab asked the Prophet ﷺ about payment for the stud service of a male animal, and he forbade it. The man said, “O Messenger of Allah ﷺ, we lend out the male animal, and then we are given a gift.” So he allowed him to accept a gift given out of generosity."]},"buhuth":{"ar":["يعني: إذا أهدى المستعير للمعير هدية بغير شرط، فلا بأس بأخذها."],"en":["Explanation: This means that if the borrower later gives the owner a gift without any prior condition, there is no harm in accepting it."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1274},{"key":"nasai","label":"النسائي","number":4672},{"key":"البیہقی","label":"البيهقي","number":5}]},{"num":5846,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( من ابتاع طعامًا فلا يبعه حتى يستوفيه ))."],"takhrij":"متفق عليه: رواه مالك (٤٠) والبخاري (٢١٢٦)، ومسلم (١٥٢٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (40), al-Bukhari (2126), and Muslim (1526).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “Whoever buys food should not sell it until he has fully taken possession of it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":40},{"key":"bukhari","label":"البخاري","number":2126},{"key":"muslim","label":"مسلم","number":1526}]},{"num":5847,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر أنه قال: كنا في زمان رسول اللّٰه ﷺ نبتاع الطعام، فيبعث علينا من يأمرنا بانتقاله من المكان الذي ابتعناه فيه إلى مكان سواه قبل أن نبيعه."],"takhrij":"متفق عليه: رواه مالك (٤٢)، ومسلم (٣٣: ١٥٢٧).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (42) and Muslim (1527: 33).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: During the time of the Messenger of Allah ﷺ, we used to buy food, and someone would be sent to us ordering us to move it from the place where we bought it to another place before selling it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":42},{"key":"muslim","label":"مسلم","number":33}]},{"num":5848,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر قال: كانوا يبتاعون الطعام في أعلى السوق، فيبيعونه في مكانهم، فنهاهم رسول اللّٰه ﷺ أن يبيعوه في مكانه حتى ينقلوه."],"takhrij":"متفق عليه: رواه البخاري (٢١٦٧)، ومسلم (١٥٢٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2167) and Muslim (1526).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: People used to buy food at the upper end of the market and sell it in the same place, so the Messenger of Allah ﷺ forbade them from selling it there until they had moved it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2167},{"key":"muslim","label":"مسلم","number":1526}]},{"num":5849,"demo":false,"sanad":"","matn":["عن ابن عمر أنهم كانوا يُضربون على عهد رسول اللّٰه ﷺ إذا اشتروا طعامًا جزافًا، أن يبيعوه في مكانهم حتى يؤووه إلى رحالهم."],"takhrij":"متفق عليه: رواه البخاري (٦٨٥٢)، ومسلم (٣٧: ١٥٢٧). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6852) and Muslim (1527: 37). This wording is from al-Bukhari.","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Ibn ‘Umar said that during the time of the Messenger of Allah ﷺ, people would be disciplined if they bought food without measuring it and then sold it in the same place before taking it to their residences."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6852},{"key":"muslim","label":"مسلم","number":37}]},{"num":5850,"demo":false,"sanad":"","matn":["عن زيد بن ثابت قال: نهى رسول اللّٰه ﷺ أن تباع السلع حيث تبتاع، حتى يحوزها التجار إلى رحالهم."],"takhrij":"حسن: رواه أبو داود (٣٤٩٩)، وأحمد (٢١٦٦٨)، والدارقطني (٢٨٣١)، والبيهقي (٥/٣١٤).","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3499), Ahmad (21668), al-Daraqutni (2831), and al-Bayhaqi (5/314).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Zayd ibn Thabit said: The Messenger of Allah ﷺ forbade goods from being sold in the place where they were bought until the traders had transferred them to their own premises."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3499},{"key":"الدارقطنی","label":"الدارقطني","number":2831},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":21668,"n":21668},{"key":"sh9771","label":"سنن الدارقطني","number":2831,"n":2840}]},{"num":5851,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول اللّٰه ﷺ قال: (( من ابتاع طعامًا فلا يبعه حتى يستوفيه )). قال ابن عباس: وأحسب كل شيء مثله."],"takhrij":"متفق عليه: رواه البخاري (٢١٣٥)، ومسلم (٢٩: ١٥٢٥). واللفظ لمسلم. وفي رواية: (( من ابتاع طعامًا فلا يبعه حتى يكتاله )). فقلت لابن عباس: لم؟ فقال: ألا تراهم يتبايعون بالذهب والطعام مرجأ.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2135) and Muslim (1525: 29). This wording is from Muslim. In another narration: “Whoever buys food should not sell it until he has measured it.” I asked Ibn ‘Abbas, “Why?” He said: “Do you not see that they exchange gold while the food remains deferred?”","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Whoever buys food should not sell it until he has fully taken possession of it.” Ibn ‘Abbas said: I think everything is similar to this."]},"buhuth":{"ar":["أي مؤخر."],"en":["Meaning: postponed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2135},{"key":"muslim","label":"مسلم","number":29}]},{"num":5852,"demo":false,"sanad":"","matn":["عن جابر قال: كان رسول اللّٰه ﷺ يقول: (( إذا ابتعت طعامًا فلا تبعه حتى تستوفيه ))."],"takhrij":"صحيح: رواه مسلم (١٥٢٩).","grade":"صحيح","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1529).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ used to say, “If you buy food, do not sell it until you have fully taken possession of it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1529}]},{"num":5853,"demo":false,"sanad":"","matn":["عن أبي هريرة أنه قال لمروان: أحللتَ بيع الربا. فقال مروان: ما فعلت. فقال أبو هريرة: أحللتَ بيع الصكاك، وقد نهى رسول اللّٰه ﷺ عن بيع الطعام حتى يستوفى. قال: فخطب مروان الناس، فنهى عن بيعها. قال سليمان: فنظرت إلى حرس يأخذونها من أيدي الناس."],"takhrij":"صحيح: رواه مسلم (١٥٢٨). وفي لفظ له: (( من اشترى طعامًا فلا يبعه حتى يكتاله )).","grade":"صحيح","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1528). In another wording: “Whoever buys food should not sell it until he measures it.”","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Abu Hurayrah said to Marwan: You have made usury lawful. Marwan said: I have not done that. Abu Hurayrah said: You have made the sale of vouchers lawful, while the Messenger of Allah ﷺ forbade selling food until it is fully received. So Marwan addressed the people and forbade their sale. Sulayman said: I then saw the guards taking them out of people’s hands."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1528}]},{"num":5854,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى النبيُّ ﷺ عن بيع الطعام حتى يجري فيه الصاعان، فيكون للبائع الزيادة، وعليه النقصان."],"takhrij":"حسن: رواه البزار -كشف الأستار (١٢٦٥)-، والبيهقي (٥/٣١٦).","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1265) and al-Bayhaqi (5/316).","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ forbade selling food until two separate measurements had been applied to it, so that the seller would bear any shortage and be entitled to any excess."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار -كشف الأستار","number":1265},{"key":"البیہقی","label":"البيهقي","number":5},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1265,"n":1266},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10701,"n":10791}]},{"num":5855,"demo":false,"sanad":"","matn":["عن حكيم بن حزام قال: قلت: يا رسول الله، إني رجل أشتري بيوعًا، فما يحل منها وما يحرم؟ قال: (( يا ابن أخي، إذا اشتريت بيعًا فلا تبعه حتى تقبضه ))."],"takhrij":"حسن: رواه ابن الجارود في المنتقى (٦٠٢)، وابن حبان (٤٩٨٣)، والدارقطني (٢٨٢٢). واللفظ لابن الجارود.","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Jarud in al-Muntaqa (602), Ibn Hibban (4983), and al-Daraqutni (2822). This wording is from Ibn al-Jarud.","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["Hakim ibn Hizam said: I said, “O Messenger of Allah ﷺ, I am a man who buys goods, so what of that is lawful and what is unlawful?” He said, “My nephew, if you buy something, do not sell it until you have taken possession of it.”"]}},"tuhfa":{},"refs":[{"key":"ابن_الجارود/المنتقی","label":"ابن الجارود في المنتقى","number":602},{"key":"ibnhibban","label":"ابن حبان","number":4983},{"key":"الدارقطنی","label":"الدارقطني","number":2822}]},{"num":5856,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو قال: قال رسول اللّٰه ﷺ: (( لا يحل سلف وبيع، ولا شرطان في بيع، ولا ربح ما لم يضمن، ولا بيع ما ليس عندك ))."],"takhrij":"حسن: رواه أبو داود (٣٥٠٤)، والترمذي (١٢٣٤)، والنسائي (٤٦١١). وقال الترمذي: حسن صحيح.","grade":"حسن","chapter_ar":"باب النهي عن بيع ما لم يقبض","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3504), al-Tirmidhi (1234), and al-Nasa’i (4611). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"The prohibition of selling what has not yet been received","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":45,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr said: The Messenger of Allah ﷺ said, “It is not lawful to combine a loan and a sale, nor two conditions in one sale, nor profit from what one has not guaranteed, nor the sale of what is not in your possession.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3504},{"key":"tirmidhi","label":"الترمذي","number":1234},{"key":"nasai","label":"النسائي","number":4611}]},{"num":5857,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّه أنه كان يسير على جمل له قد أعيا، فأراد أن يسيبه. قال: فلحقني النبيُّ ﷺ، فدعا لي، وضربه، فسار سيرًا لم يسر مثله. قال: (( بعنيه بوقية )). قلت: لا. ثم قال: (( بعنيه )). فبعته بوقية، واستثنيت عليه حملانه إلى أهلي. فلما بلغت أتيته بالجمل، فنقدني ثمنه، ثم رجعت. فأرسل في إثري، فقال: (( أتراني ماكستك لآخذ جملك، خذ جملك ودراهمك فهو لك ))."],"takhrij":"متفق عليه: رواه البخاري (٢٧١٨)، ومسلم (١٠٩: ٧١٥). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب جواز بعض الشروط في البيع إذا لم تكن منافية للبيع","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2718) and Muslim (715: 109). This wording is from Muslim.","chapter_en":"The permissibility of some conditions in a sale when they do not contradict the sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":46,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I was traveling on a camel that had become exhausted, and I wanted to let it go. Then the Prophet ﷺ caught up with me, supplicated for me, and struck it, so it moved in a way it had never moved before. He said, “Sell it to me for one uqiyyah.” I said, “No.” Then he said again, “Sell it to me.” So I sold it to him for one uqiyyah, on the condition that I could ride it back to my family. When I arrived, I brought him the camel, and he paid me its price. Then I turned back, and he sent after me, saying, “Did you think I bargained with you just to take your camel? Take your camel and your money, for it is yours.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2718},{"key":"muslim","label":"مسلم","number":109}]},{"num":5858,"demo":false,"sanad":"","matn":["عن عائشة قالت: جاءتني بريرة، فقالت: كاتبت أهلي على تسع أواق، في كل عام أوقية، فأعينيني. فقلت: إن أحب أهلك أن أعدها لهم، ويكون ولاؤك لي فعلت. فذهبت بريرة إلى أهلها، فقالت لهم، فأبوا ذلك عليها، فجاءت من عندهم ورسول اللّٰه ﷺ جالس، فقالت: إني قد عرضت ذلك عليهم، فأبوا إلا أن يكون الولاء لهم. فسمع النبيُّ ﷺ، فأخبرت عائشة النبيَّ ﷺ، فقال: (( خذيها، واشترطي لهم الولاء، فإنما الولاء لمن أعتق )). ففعلت عائشة، ثم قام رسول اللّٰه ﷺ في الناس، فحمد الله، وأثنى عليه، ثم قال: (( أما بعد: ما بال رجال يشترطون شروطًا ليست في كتاب الله؟ ما كان من شرط ليس في كتاب اللّٰه فهو باطل وإن كان مائة شرط، قضاء اللّٰه أحق، وشرط اللّٰه أوثق، وإنما الولاء لمن أعتق ))."],"takhrij":"متفق عليه: رواه مالك (١٧) والبخاري (٢١٦٨)، ومسلم (١٥٠٤).","grade":"متفق عليه","chapter_ar":"باب من اشترط شرطًا ليس في كتاب الله فالبيع صحيح، والشرط فاسد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (2168), and Muslim (1504).","chapter_en":"Whoever makes a condition not found in the Book of Allah, the sale is valid but the condition is invalid","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":47,"content":{"translation":{"en":["Aishah said: Barirah came to me and said: I have made an agreement with my family for nine uqiyyahs, one uqiyyah each year, so help me. I said: If your family would like me to pay it all to them and your right of wala’ (patronage) becomes mine, I will do so. Barirah went to her family and told them, but they refused unless the wala’ (patronage) remained theirs. She came back while the Messenger of Allah ﷺ was sitting there and said: I presented that to them, but they refused unless the wala’ (patronage) remains theirs. The Prophet ﷺ heard this, and Aishah informed him, so he said: “Take her and stipulate the wala’ (patronage) for them, for the wala’ belongs only to the one who frees.” So Aishah did that. Then the Messenger of Allah ﷺ stood before the people, praised Allah, and said: “What is the matter with people who stipulate conditions not found in the Book of Allah? Any condition not found in the Book of Allah is invalid, even if there are a hundred conditions. The decree of Allah has more right, and the condition of Allah is firmer. The right of wala’ (patronage) belongs only to the one who frees.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"bukhari","label":"البخاري","number":2168},{"key":"muslim","label":"مسلم","number":1504}]},{"num":5859,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: أرادت عائشة أن تشتري جارية تعتقها، فأبى أهلها إلا أن يكون لهم الولاء، فذكرت ذلك لرسول اللّٰه ﷺ فقال: (( لا يمنعك ذلك، فإنما الولاء لمن أعتق ))."],"takhrij":"صحيح: رواه مسلم (١٥٠٥).","grade":"صحيح","chapter_ar":"باب من اشترط شرطًا ليس في كتاب الله فالبيع صحيح، والشرط فاسد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1505).","chapter_en":"Whoever makes a condition not found in the Book of Allah, the sale is valid but the condition is invalid","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":47,"content":{"translation":{"en":["Abu Hurayrah said: Aishah wanted to buy a slave girl in order to free her, but her owners refused unless the wala’ (patronage) would remain theirs. She mentioned that to the Messenger of Allah ﷺ, and he said: “Do not let that prevent you, for the wala’ (patronage) belongs only to the one who frees.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1505}]},{"num":5860,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر أن رسول اللّٰه ﷺ قال: (( لا يبع بعضكم على بيع بعض ))."],"takhrij":"متفق عليه: رواه مالك (٩٥) والبخاري (٢١٣٩)، ومسلم (١٤١٢).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (95), al-Bukhari (2139), and Muslim (1412).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “None of you should sell over the sale of another.”"]},"buhuth":{"ar":["وزاد أبو داود: (( إلا بإذنه )). ولفظ النسائي: (( … حتى يبتاع أو يذر ))."],"en":["Additional wording: Abu Dawud adds: “except with his permission.” Al-Nasa’i’s wording is: “until he buys it or leaves it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":95},{"key":"bukhari","label":"البخاري","number":2139},{"key":"muslim","label":"مسلم","number":1412}]},{"num":5861,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ أن يبيع حاضر لباد، ولا تناجشوا، ولا يبيع الرجل على بيع أخيه، ولا يخطب على خطبة أخيه، ولا تسأل المرأة طلاق أختها لتكفأ ما في إنائها."],"takhrij":"متفق عليه: رواه البخاري (٢١٤٠)، ومسلم (١٤١٣).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2140) and Muslim (1413).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade a town-dweller from selling on behalf of a desert-dweller, forbade artificial bidding, forbade a man from selling over the sale of his brother, forbade proposing over the proposal of his brother, and forbade a woman from asking for her sister to be divorced so that she may take what is in her vessel."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2140},{"key":"muslim","label":"مسلم","number":1413}]},{"num":5862,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( لا يَسُم المسلم على سوم أخيه ))."],"takhrij":"صحيح: رواه مسلم (٩: ١٥١٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1515: 9).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “A Muslim must not outbid his brother in a transaction.”"]},"buhuth":{"ar":["ومعنى الحديث: إذا اتفق البائع والمشتري على البيع، ولم يعقداه بعد، فلا يجوز لآخر أن يدخل فيرفع السعر أو يفسد البيع. وأما المزايدة العامة فليست داخلة في هذا النهي."],"en":["Explanation: This means that when a seller and buyer have already agreed on a sale but have not yet concluded it, a third person must not step in to raise the price or spoil the sale. Open bidding in a public auction is not included in this prohibition."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":9}]},{"num":5863,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن شماسة أنه سمع عقبة بن عامر على المنبر يقول: إن رسول اللّٰه ﷺ قال: (( المؤمن أخو المؤمن؛ فلا يحل للمؤمن أن يبتاع على بيع أخيه، ولا يخطب على خطبة أخيه حتى يذر ))."],"takhrij":"صحيح: رواه مسلم (١٤١٤: ٥٦).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1414: 56).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["‘Abd al-Rahman ibn Shumasah said that he heard ‘Uqbah ibn ‘Amir say on the pulpit: The Messenger of Allah ﷺ said: “The believer is the brother of the believer. It is not lawful for a believer to outbid his brother in a sale or propose over his proposal until he leaves it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1414}]},{"num":5864,"demo":false,"sanad":"","matn":["عن سمرة بن جندب أن رسول اللّٰه ﷺ نهى أن يخطب الرجل على خطبة أخيه، أو يبتاع على بيعه."],"takhrij":"حسن: رواه أحمد (٢٠١١٥).","grade":"حسن","chapter_ar":"باب النهي عن بيع الرجل على بيع أخيه","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20115).","chapter_en":"The prohibition of a man selling over the sale of his brother","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":48,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Messenger of Allah ﷺ forbade a man from proposing over the proposal of his brother or buying over his sale."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":20115,"n":20115}]},{"num":5865,"demo":false,"sanad":"","matn":["عن أبي هريرة يبلغ به النبيَّ ﷺ قال: (( لا يبع حاضر لباد ))."],"takhrij":"متفق عليه: رواه البخاري (٢١٤٠)، ومسلم (١٥٢٠). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2140) and Muslim (1520). This wording is from Muslim.","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Abu Hurayrah, tracing it to the Prophet ﷺ, said: “A town-dweller must not sell on behalf of a desert-dweller.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2140},{"key":"muslim","label":"مسلم","number":1520}]},{"num":5866,"demo":false,"sanad":"","matn":["عن طاوس، عن ابن عباس قال: نهى رسول اللّٰه ﷺ أن تتلقى الركبان، وأن يبيع حاضر لباد. قال: فقلت لابن عباس: ما قوله (( حاضر لباد ))؟ قال: لا يكن له سمسارًا."],"takhrij":"متفق عليه: رواه البخاري (٢١٥٨)، ومسلم (١٥٢١).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2158) and Muslim (1521).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Tawus narrated from Ibn ‘Abbas that the Messenger of Allah ﷺ forbade meeting traders outside the market and forbade a town-dweller from selling for a desert-dweller. I said to Ibn ‘Abbas: What does “a town-dweller selling for a desert-dweller” mean? He said: He must not act as a broker for him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2158},{"key":"muslim","label":"مسلم","number":1521}]},{"num":5867,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: نُهينا أن يبيع حاضر لباد."],"takhrij":"متفق عليه: رواه البخاري (٢١٦١)، ومسلم (٢٢: ١٥٢٣).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2161) and Muslim (1523: 22). Muslim also narrated through another route with the addition: “even if he is his brother or his father.”","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Anas ibn Malik said: We were forbidden from a town-dweller selling on behalf of a desert-dweller."]},"buhuth":{"ar":["ورواه مسلم من وجه آخر، وزاد فيه: (( وإن كان أخاه أو أباه ))."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2161},{"key":"muslim","label":"مسلم","number":22}]},{"num":5868,"demo":false,"sanad":"","matn":["عن ابن عمر قال: نهى رسول اللّٰه ﷺ أن يبيع حاضر لباد."],"takhrij":"صحيح: رواه البخاري (٢١٥٩).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2159).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ forbade a town-dweller from selling on behalf of a desert-dweller."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2159}]},{"num":5869,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول اللّٰه ﷺ: (( لا يبع حاضر لباد، دعوا الناس يرزق الله بعضهم من بعض ))."],"takhrij":"صحيح: رواه مسلم (١٥٢٢).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1522).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “A town-dweller must not sell on behalf of a desert-dweller. Leave the people so that Allah may provide some of them through others.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1522}]},{"num":5870,"demo":false,"sanad":"","matn":["عن طلحة بن عبيد اللّٰه قال: إن النبيَّ ﷺ نهى أن يبيع حاضر لباد."],"takhrij":"حسن: رواه أبو داود (٣٤٤١)، والإمام أحمد (١٤٠٤).","grade":"حسن","chapter_ar":"باب النهي عن بيع الحاضر للبادي","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3441) and Ahmad (1404).","chapter_en":"The prohibition of a town-dweller selling for a desert-dweller","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":49,"content":{"translation":{"en":["Talhah ibn ‘Ubayd Allah said: The Prophet ﷺ forbade a town-dweller from selling on behalf of a desert-dweller."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3441},{"key":"الامام_احمد","label":"الإمام أحمد","number":1404},{"key":"ahmad","label":"مسند الإمام أحمد","number":1404,"n":1404}]},{"num":5871,"demo":false,"sanad":"","matn":["عن ابن مسعود، عن النبيِّ ﷺ أنه نهى عن تلقي البيوع."],"takhrij":"متفق عليه: رواه البخاري (٢١٦٤)، ومسلم (١٥١٨). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2164) and Muslim (1518). This wording is from Muslim.","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Ibn Mas‘ud reported that the Prophet ﷺ forbade intercepting traders before they reached the market."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2164},{"key":"muslim","label":"مسلم","number":1518}]},{"num":5872,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر أن رسول اللّٰه ﷺ قال: (( لا يبيع بعضكم على بيع بعض، ولا تلقوا السلع حتى يُهبط بها إلى السوق))."],"takhrij":"متفق عليه: رواه البخاري (٢١٦٥)، ورواه مسلم (١٥١٧) بلفظ: (( أن رسول اللّٰه ﷺ نهى أن تُتَلَقَّى السِّلَعُ حتى تبلغ الأسواق )).","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2165), and Muslim (1517) with the wording: “The Messenger of Allah ﷺ forbade that goods be met before they reach the markets.”","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ, said: “None of you should sell over the sale of another, and do not go out to meet goods before they are brought down into the market.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2165},{"key":"muslim","label":"مسلم","number":1517}]},{"num":5873,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ أن يُتَلَقّى الجَلَبُ."],"takhrij":"متفق عليه: رواه البخاري (٢١٦٢)، ومسلم (١٦ :١٥١٩). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (2162) and Muslim (1519:16). The wording is that of Muslim.","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, forbade going out to meet incoming merchandise before it reached the market."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2162},{"key":"muslim","label":"مسلم","number":16}]},{"num":5874,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( لا تلقوا الركبان للبيع، ولا يبع بعضكم على بيع بعض، ولا تناجشوا، ولا يبع حاضر لباد، ولا تصروا الإبل والغنم، فمن ابتاعها بعد ذلك فهو بخير النظرين بعد أن يحلبها: إن رضيها أمسكها، وإن سخطها ردها وصاعا من تمر ))."],"takhrij":"متفق عليه: رواه مالك (٩٦) والبخاري (٢١٥٠)، ومسلم (١١ :١٥١٥).","grade":"متفق عليه","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (96), al-Bukhari (2150), and Muslim (1515:11).","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ, said: “Do not meet riders bringing goods for sale before they arrive, and none of you should sell over the sale of another, and do not engage in artificial bidding, and a town-dweller must not sell on behalf of a desert-dweller, and do not withhold the milk of camels and sheep. Whoever buys one of them after that has the choice between two matters after milking it: if he is pleased with it, he may keep it; and if he is displeased with it, he may return it along with a sa‘ of dates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":96},{"key":"bukhari","label":"البخاري","number":2150},{"key":"muslim","label":"مسلم","number":11}]},{"num":5875,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: إن رسول اللّٰه ﷺ قال: (( لا تلقوا الجلب، فمن تلقاه فاشترى منه، فإذا أتى سيده السوق فهو بالخيار ))."],"takhrij":"صحيح: رواه مسلم (١٧ :١٥١٩).","grade":"صحيح","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1519:17).","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, said: “Do not meet incoming goods before they reach the market. Whoever meets them and buys from them, then when their owner reaches the market, he has the choice.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17}]},{"num":5876,"demo":false,"sanad":"","matn":["عن سمرة أن نبي اللّٰه ﷺ نهى أن تتلقَى الأجلاب حتى تبلغ الأسواق، أو يبيع حاضر لباد."],"takhrij":"حسن: رواه أحمد (٢٠١١٩)، والطبراني في الكبير (٦٩٢٩).","grade":"حسن","chapter_ar":"باب النهي عن تلقي الركبان والجلب","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Sound. Narrated by Ahmad (20119) and al-Tabarani in al-Kabir (6929).","chapter_en":"The prohibition of meeting caravans before they reach the market and intercepting incoming goods","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":50,"content":{"translation":{"en":["Samurah reported that the Prophet of Allah ﷺ, forbade that incoming merchandise be met before it reached the markets, or that a town-dweller sell on behalf of a desert-dweller."]},"buhuth":{"ar":["معنى الحديث: كان من عادة العرب أنهم كانوا يتلقون الركبان قبل أن يقدموا البلد، ويعرفوا سعر السوق، فيخبروهم بأن الأسعار ساقطة، والسوق كاسدة، والرغبة قليلة، ويبتاعونه منهم بالوكس من ثمن، وهو يشبه الغش؛ فنهاهم رسول اللّٰه ﷺ وخيرهم بأن من غُش بهذا الشكل فهو بالخيار، وظاهر الحديث يدل على ذلك. وقال بعض أهل العلم: إنما يكون للبائع الخيار إذا كان المتلقي قد ابتاعه بأقل من الثمن، فإذا ابتاعه بثمن مثله فلا خيار له حينئذ."],"en":["Meaning of this hadith: It was the custom of the Arabs to go out and meet the caravans before they entered the town and learned the market price. They would tell them that prices had fallen, that the market was weak, and that demand was low, then buy their goods from them at a reduced price. This resembles deception, so the Messenger of Allah ﷺ, forbade it. He gave the seller the option, so whoever was deceived in this way has the right to choose, and the apparent meaning of the hadith indicates this. Some scholars said that the seller only has this option if the one who met him bought the goods for less than the normal price. But if he bought them for their usual market value, then the seller has no option in that case."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":6929},{"key":"ahmad","label":"مسند الإمام أحمد","number":20119,"n":20119}]},{"num":5877,"demo":false,"sanad":"","matn":["عن معمر قال: قال رسول اللّٰه ﷺ: (( من احتكرَ فهو خاطئ)). فقيل لسعيد: فإنك تحتكر؟ قال سعيد: إن معمرا الذي كان يحدث هذا الحديث كان يحتكر."],"takhrij":"صحيح: رواه مسلم (١٢٩:١٦٠٥).","grade":"صحيح","chapter_ar":"باب ما جاء في الاحتكار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1605:129).","chapter_en":"What Has Been Narrated Regarding Hoarding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":51,"content":{"translation":{"en":["Ma‘mar reported that the Messenger of Allah ﷺ, said: “Whoever hoards is sinful.” It was said to Sa‘id: Then do you hoard? Sa‘id said: Ma‘mar, who used to narrate this hadith, also used to hoard."]},"buhuth":{"ar":["وكون الصحابي يروي الحديث، ثم يخالفه، وكذا التابعي يرويه، ويخالفه، ويستدل على مخالفته لمخالفة الصحابي، فكل هذا مشعر، كما قال البيهقي (٣٠/٥): “إنهما احتكرا على غير الوجه المنهي عنه”.","وقال الخطابي: “والحديث وإن جاء باللفظ العام، فاحتكار الراوي يدل على أنه مختص ببعض الأشياء، أو بعض الأحوال؛ إذ لا يظن بالصحابي أن يروي الحديث، ثم يخالفه، وكذلك سعيد بن المسيب لا يظن به في فضله وعلمه أنه يروي الحديث، ثم يخالفه، إلا أن يحمل الحديث على بعض الأشياء، فروي أنه كان يحتكر الزيت”. انتهى. وسيأتي كلام أهل العلم في آخر الباب."],"en":["The fact that a Companion may narrate a hadith and then appear to act contrary to it, and likewise a Successor may narrate it and then act differently, and even use the Companion’s differing practice as evidence, all of this suggests, as al-Bayhaqi said (5/30): “That the two of them hoarded in a manner other than the kind that was forbidden.”","Al-Khattabi said: “Although the hadith came in general wording, the narrator’s own hoarding indicates that it applies only to certain things or certain situations, because it is not to be assumed that a Companion would narrate a hadith and then oppose it. Likewise, Sa‘id ibn al-Musayyib, due to his virtue and knowledge, would not be expected to narrate a hadith and then oppose it, except that the hadith is to be understood as applying to some things and not others. It is reported that he used to hoard oil.” End quote. The discussion of the scholars on this issue will come later at the end of the chapter."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":129}]},{"num":5878,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب أن النبي ﷺ كان يبيع نخل بني النضير ويحبس لأهله قوت سنتهم"],"takhrij":"متفق عليه: رواه البخاري (٥٣٥٧) ومسلم (١٧٥٧). والسياق للبخاري، وحبس الطعام للأهل لا يسمى احتكارا.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الاحتكار","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by al-Bukhari (5357) and Muslim (1757). The wording here is that of al-Bukhari. Storing food for one’s family is not called hoarding.","chapter_en":"What Has Been Narrated Regarding Hoarding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":51,"content":{"translation":{"en":["Umar ibn al-Khattab reported that the Prophet ﷺ, used to sell the date-palms of Banu al-Nadir and store for his family their provisions for a year."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5357},{"key":"muslim","label":"مسلم","number":1757}]},{"num":5879,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر أن رسول اللّٰه ﷺ نهى عن النجش."],"takhrij":"متفق عليه: رواه مالك (٩٧) والبخاري (٢١٤٢)، ومسلم (١٥١٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن النَجْش","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (97), al-Bukhari (2142), and Muslim (1516).","chapter_en":"The Prohibition of Artificial Bidding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":52,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ, forbade artificial bidding."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":97},{"key":"bukhari","label":"البخاري","number":2142},{"key":"muslim","label":"مسلم","number":1516}]},{"num":5880,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن أبي أوفى قال: أقام رجل سلعته، فحلف بالله: لقد أعطى بها ما لم يعطها، فنزلت: (إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَٰنِهِمْ ثَمَنًا قَلِيلًا) [سورة آل عمران: ٧٧].","وقال ابن أبي أوفى: الناجش آكل ربا خائن."],"takhrij":"صحيح: رواه البخاري (٢٦٧٥).","grade":"صحيح","chapter_ar":"باب النهي عن النَجْش","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by al-Bukhari (2675).","chapter_en":"The Prohibition of Artificial Bidding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":52,"content":{"translation":{"en":["Abdullah ibn Abi Awfa said: A man displayed his goods and swore by Allah that he had been offered for them what in fact he had not been offered, so the verse was revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” [Surah Al Imran: 77].","Ibn Abi Awfa said: The one who engages in artificial bidding is a devourer of usury and a traitor."]},"buhuth":{"ar":["والنجش في اللغة تنفير الصيد واستثارته من مكانه ليصاد، يقال: نجشت الصيد، أنجُشه بالضم، نجشا.","قال مالك عقب الحديث: “والنجش أن تعطيه بسلعته أكثر من ثمنها، وليس في نفسك اشتراؤها، فيقتدي بك غيرك”.","وقال الترمذي: “والنجش أن يأتي الرجل الذي يفصل السلعة إلى صاحب السلعة، فيستام بأكثر مما تسوى، وذلك عندما يحضره المشتري، يريد أن يغتر المشتري به، وليس من رأيه الشراء، إنما يريد أن يخدع المشتري بما يستام”. انتهى.","وأما حكم النجش فقال الشافعي: “الناجش آثم فيما يصنع، والبيع جائز؛ لأن البائع غير الناجش”. ذكره الترمذي."],"en":["In Arabic, najsh means frightening game and stirring it from its place so that it may be hunted. It is said: “I stirred up the game.”","Malik said after this hadith: “Najsh is when a person offers more for an item than its value, while not actually intending to buy it, so that others follow his lead.”","Al-Tirmidhi said: “Najsh is when a man comes to the seller of a commodity and offers more than the item is worth while the real buyer is present, intending to deceive the buyer, not intending to purchase it himself, but only to trick the buyer by the false offer.” End quote.","As for the ruling on najsh, al-Shafi‘i said: “The one who practices najsh is sinful in what he does, but the sale itself remains valid, because the seller is not the one who committed the najsh.” This was mentioned by al-Tirmidhi."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2675}]},{"num":5881,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( لا تناجشوا ))."],"takhrij":"صحيح: رواه أبو داود (٣٤٣٨)، والترمذي (١٣٠٤)، والنسائي (٤٥٠٦)، وابن ماجه (٢١٧٤).","grade":"صحيح","chapter_ar":"باب النهي عن النَجْش","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Abu Dawud (3438), al-Tirmidhi (1304), al-Nasa’i (4506), and Ibn Majah (2174).","chapter_en":"The Prohibition of Artificial Bidding","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":52,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, said: “Do not engage in artificial bidding.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3438},{"key":"tirmidhi","label":"الترمذي","number":1304},{"key":"nasai","label":"النسائي","number":4506},{"key":"ibnmajah","label":"ابن ماجه","number":2174}]},{"num":5882,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّه قال: نهى رسول اللّٰه ﷺ عن المحاقلة، والمزابنة، والمعاومة، والمخابرة - قال أحدهما: بيع السنين هي المعاومة -، وعن الثنيا ورخص في العرايا."],"takhrij":"صحيح: رواه مسلم (٨٥ :١٥٣٦).","grade":"صحيح","chapter_ar":"باب النهي عن الاستثناء في عقد البيع شيئا مجهولا","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1536:85).","chapter_en":"The Prohibition of Making an Unspecified Exception in a Sale Contract","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":53,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ, forbade muhaqalah, muzabanah, mu‘awamah, and mukhabarah — one of the narrators said: “Selling for coming years is what mu‘awamah means” — and he also forbade an unspecified exception, while permitting ‘araya sales."]},"buhuth":{"ar":["ورواه أبو داود (٣٤٠٥)، والترمذي (١٢٩٠) وزادا فيه: (( والثنيا إلا أن تعلم)).","وبيع الثنيا المنهي عنه أن يبيع ثمر حائطه، ويستثني منه جزءا غير معلوم، ولكن لو استثنى منه جزءا معلوما لجاز البيع."],"en":["It was also narrated by Abu Dawud (3405) and al-Tirmidhi (1290), and they added: “And the exception is forbidden unless it is specified.”","The forbidden form of exception in a sale is when a person sells the fruit of his orchard but excludes from it an unknown portion. But if he excludes a known and specified portion, then the sale is valid."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":85}]},{"num":5883,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( لا تلقوا الركبان للبيع، ولا يَبعْ بعضُكم على بيعِ بعضٍ، ولا تناجشوا، ولا يَبعْ حاضرٌ لبادٍ، ولا تُصَرُّوا الإبلَ والغنمَ، فمن ابتاعَها بعد ذلك فهو بخيرِ النظرين بعد أن يحلبها: إنْ رَضِيَها أمسكَها، وإنْ سخطها ردّها وصاعًا من تمر))."],"takhrij":"متفق عليه: رواه مالك (٩٦) والبخاري (٢١٥٠)، ومسلم (١١ :١٥١٥).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Agreed upon. Narrated by Malik (96), al-Bukhari (2150), and Muslim (1515:11).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ, said: “Do not meet riders bringing goods for sale before they arrive, and none of you should sell over the sale of another, and do not engage in artificial bidding, and a town-dweller must not sell on behalf of a desert-dweller, and do not withhold the milk of camels and sheep. Whoever buys such an animal after that has the choice of two options after milking it: if he is pleased with it, he may keep it, and if he is displeased with it, he may return it along with a sa‘ of dates.”"]},"buhuth":{"ar":["ورواه مسلم أيضا (٢٨ :١٥٢٤) من طريق آخر وفيه : (( إذا ما أحدكم اشترى لقحةً مُصَرّاةً أو شاةً مُصَرّاةً، فهو بخير النظرين بعد أن يَحلبَها: إما هي، وإلا فَلْيَرُدَّها وصاعاً من تمرٍ ))."],"en":["Muslim also narrated it (1524:28) through another chain with the wording: “If one of you buys a milk-withheld she-camel or a milk-withheld sheep, then after milking it he has the choice of two options: he may keep it, or else he should return it along with a sa‘ of dates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":96},{"key":"bukhari","label":"البخاري","number":2150},{"key":"muslim","label":"مسلم","number":11}]},{"num":5884,"demo":false,"sanad":"","matn":["عن أبى هريرة أن رسول اللّٰه ﷺ قال: (( من ابتاع شاةً مُصَرّاة فهو فيها بالخيار ثلاثة أيام، إن شاء أمسكَها، وإن شاء ردّها، وردَّ معها صاعًا من تمر))."],"takhrij":"صحيح: رواه مسلم (٢٤:١٥٢٤). وفي رواية: (( فإن ردّها ردّ معها صاعًا من طعامٍ، لا سمراء)).","grade":"صحيح","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic. Narrated by Muslim (1524:24). In another narration: “If he returns it, he returns with it a sa‘ of food, not brown wheat.”","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ, said: “Whoever buys a milk-withheld sheep has the option for three days: if he wishes, he may keep it; and if he wishes, he may return it and return with it a sa‘ of dates.”"]},"buhuth":{"ar":["وفي رواية بلفظ: (( من اشترى شاةً مُصَرّاةً فهو بخير النظرين: إنْ شاء أمسكَها، وإنْ شاءَ ردّها وصاعًا من تمر لا سمراء ))."],"en":["And in another wording: “Whoever buys a milk-withheld sheep has the choice of two options: if he wishes, he may keep it; and if he wishes, he may return it along with a sa‘ of dates, not brown wheat.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":24}]},{"num":5885,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ:","«إِذَا بَاعَ أَحَدُكُمُ الشَّاةَ أَوِ اللِّقْحَةَ فَلَا يُحَفِّلْهَا»."],"takhrij":"صحيح: رواه النسائي (٤٤٨٦)، وأحمد (٧٦٩٩)، وابن حبان (٤٩٦٩).","grade":"صحيح","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (4486), Aḥmad (7699), and Ibn Ḥibbān (4969).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said:","“When one of you sells a sheep or a milch-camel, he must not withhold its milk in the udder in order to make it appear to contain more milk.”"]},"buhuth":{"ar":["وقال به جمهور أهل العلم، مالك والشافعي وأحمد وغيرهم: يرد صاعًا من تمر، كان اللبن قليلًا أو كثيرًا.","وخالفهم أهل العراق فقالوا: هو مخالف لقياس جلي، وقالوا: إن كان له مثل يرد مثله، وإن لم يكن له مثل يرد قيمته، وأما الرد بجنس آخر فهذا خلاف الأصول.","وأجاب الجمهور بأن فيه دفعًا للنزاع والخصام.","وحررت القول فيه بالتفصيل في المنة الكبرى (٥/١٢٥)."],"en":["The majority of the scholars, including Mālik, al-Shāfiʿī, Aḥmad, and others, held that the buyer returns one ṣāʿ of dates along with the animal, whether the amount of milk consumed was small or large.","The scholars of Iraq disagreed and said that this conflicts with clear analogy. They held that if the consumed item has an equivalent, its equivalent should be returned, and if it has no equivalent, its value should be returned. As for requiring compensation with a different type of commodity, they regarded that as contrary to the general legal principles.","The majority responded that this ruling prevents dispute and contention.","The matter is discussed in detail in al-Minnah al-Kubrā (5/125)."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4486},{"key":"ibnhibban","label":"ابن حبان","number":4969},{"key":"ahmad","label":"مسند الإمام أحمد","number":7699,"n":7699}]},{"num":5886,"demo":false,"sanad":"","matn":["عن رجلٍ من أصحاب النبي ﷺ، عن النبي ﷺ أنه قال: (( لا يُتَلَقَّى جَلَبٌ، ولا يبع حاضر لباد، ومن اشترى شاةً مُصَرَّاة أو ناقةً - قال شعبة: إنما قال: ناقة مرة واحدة - فهو فيها بخير النظرين إذا هو حلب، إن ردّها ردّ معها صاعًا من طعام». قال الحكم: أو قال: (( صاعا من تمر)."],"takhrij":"صحيح: رواه أحمد (١٨٨١٩)، والبيهقي (٣١٩/٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (18819) and al-Bayhaqi (5/319).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ, narrated from the Prophet that he said: “Incoming goods are not to be met before they reach the market, and a town-dweller must not sell on behalf of a desert-dweller. Whoever buys a milk-withheld sheep or a camel — Shu‘bah said: he only said ‘camel’ one time — then after he milks it, he has the choice of two options. If he returns it, he returns with it one sa‘ of food.” Al-Hakam said: Or he said: “One sa‘ of dates.”"]},"buhuth":{"ar":["وقوله: (( صاعًا من طعام، أو صاعًا من تمر )) شك من أحد الرواة، لا أنه على التخيير؛ ليكون موافقا للأحاديث الثابتة."],"en":["His statement, “a sa‘ of food, or a sa‘ of dates,” is uncertainty from one of the narrators, not that the buyer is given a choice between the two, so that the wording remains consistent with the firmly established narrations."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":319},{"key":"ahmad","label":"مسند الإمام أحمد","number":18819,"n":18819}]},{"num":5887,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مسعود قال: من اشترى شاةً محفّلةً فردّها، فليردّ معها صاعًا من تمرٍ،","ونهى النبيُّ ﷺ أن تُلَقَّى البيوعَ."],"takhrij":"صحيح: رواه البخاري (٢١٤٩) ومسلم (١٥١٨).","grade":"صحيح","chapter_ar":"باب النهي عن بيع المصَرَّاة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2149) and Muslim (1518).","chapter_en":"The Prohibition of Selling an Animal Whose Milk Has Been Withheld","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":54,"content":{"translation":{"en":["Abdullah ibn Mas‘ud said: Whoever buys a milk-filled sheep and then returns it should return with it one sa‘ of dates. And the Prophet ﷺ, forbade going out to meet goods before they reached the market."]},"buhuth":{"ar":["قوله: (( لا تُصَرُّوا)) بضم التاء وفتح الصاد، ويأتي معناه اللغوي. وفيه دليل على نهي التصرية، سواء قصد بها البيع أم لا؛ لما فيه من إيذاء الحيوان، وهو محرم. فإذا باع مع التصرية فإنه ارتكب المحظورين: إيذاء الحيوان، وغش المشتري. وما جاء بلفظ: (( لا تُصَرُّوا الإبلَ والغنمَ للبيع» فهو للغالب. وقيل: إن النهي خاص بالبيع، ويجوز تصرية الحيوان لغير البيع.","وقوله: (( فإنْ رَضِيَها أَمْسَكَها )) فيه دليل على صحة البيع مع التصرية إن رضي بها المشتري.","وقوله: (( وصاعًا مِنْ تمرٍ)) أي: ويردَّ صاعا من تمر.","اختلاف أهل العلم واللغة في اشتقاق المصراة","قال الشافعي: التصرية أن تربط أخلاف الناقة والشاة، وتترك من الحلب اليومين والثلاثة، حتى يجتمع اللبن، فيراه المشتري كثيرا، ويزيد في ثمنها؛ لما يرى من كثرة لبنها، فإذا حلبها بعد تلك الحلبة حلبة أو اثنتين عرف أن ذلك ليس بلبنها، وهذا غرور للمشتري.","وقال أبو عبيد: “قوله: (( مصرّاة)) يعني الناقة أو البقرة أو الشاة التي قد صري اللبن في ضرعها، يعني حُقن فيه، وجمع أياما، فلم تحلب أياما. وأصل التصرية حبس الماء وجمعه، يقال منه: صَرّيت الماء وصَرَيته.","والتصريةُ حرام فيه غشُّ وتدليسٌ لقوله ﷺ: ((لا تصرّوا الإبلَ والغنمَ)).","وحديث أبي هريرة صحيح عند أهل العلم بالحديث، رواه عنه جماعة، منهم: موسى بن يسار، وأبو صالح، وهمام بن منبه، ومحمد بن سيرين، ومحمد بن زياد بأسانيد صحاح كما قال ابن عبد البر في التمهيد (٢٠٣/١٨).","وأفتى به ابنُ مسعود كما ذكره البخاري بعد حديث أبي هريرة.","عمر بن الخطاب إلى حَمَل بن مالك وغيره في دية الجنين، وكما رجع زيد بن ثابت وغيره إلى امرأة من الأنصار في سقوط طواف الوداع عن الحائض. انتهى كلامه. مجموع الفتاوى (٥٣٢ /٤).","وقال الشيخ محمد أنور شاه الكشميري: والحديث واردٌ علينا، وأجاب عنه بعض الحنفية أن الحديث إذا رَوَاه راوٍ غير فقيهِ، وعَارَضَه القياسُ، يُثْرَكُ العملُ به، ويُعْمَلَ بالقياس. فلمَا كان حديثُ أبي هُرَيرة مخالفًا للقياس، ورواه من هو غير فقيهِ، عَدَلْنا إلى القياس، وعَمِلْنا به. ثم قال: وهذا الجواب باطلٌ لا يُلْتَفَتُ إليه، ولم يَزَلْ مَطْعَنًا للخصوم منذ زمنٍ قديم. ولمثل هذا اشتهر أن الحنفيةَ يُقَدِّمُون الرأيَ على الحديث، وحاشاهم أن يقولوا بمثله، فإن هذه المسألة لم يصح نقلها عن أبي حنيفة، ولا عن أحدٍ من أصحابه.","ثم قال: وبالجملة هذا الجواب أولى أن لا يُذكر في الكتب، وإن ذكره بعضهم، ومن يجترئ على أبي هريرة فيقول: إنه كان غير فقيه؟ ولو سلمنا، فقد يرويه أفقههم، أعني ابن مسعود أيضًا، فيعود المحذور.","انتهى. فيض الباري (٣/٢٢٩).","وزِدْ على هذا بأن أبا هريرة لم ينفرد في رواية هذا الحديث كما أنه لم ينفرد في معظم مروياته حسب دراستي، وإنْ كان في رواية الآخرين كلام إلا أن الأصل يدلّ على أنّ الحديث ورد من طرق شتى، وأبو هريرة ممن ضبط الحديث كما سمع، وغيره لعله لم يضبطه."],"en":["His statement, “Do not perform tasriyah,” with the letter ta pronounced with ḍammah and the letter ṣad with fatḥah, has a known linguistic meaning. It proves that tasriyah is forbidden, whether it is done for the purpose of sale or not, because it involves harming the animal, and that is prohibited. If someone sells after performing tasriyah, he has committed two wrongs: harming the animal and deceiving the buyer. The wording, “Do not perform tasriyah on camels and sheep for sale,” refers to the most common case. Some said the prohibition is specific to sale, and that doing so for a purpose other than sale would be allowed.","His statement, “If he is pleased with it, he may keep it,” indicates that the sale remains valid despite tasriyah if the buyer accepts it.","And his statement, “and a sa‘ of dates,” means that he returns one sa‘ of dates along with it.","The scholars and the linguists differed regarding the derivation of the word musarrah.","Al-Shafi‘i said: Tasriyah is when the teats of a she-camel or sheep are tied and it is left unmilked for two or three days until the milk gathers. Then the buyer sees much milk and increases the price because of what he sees of its abundance. When he milks it once or twice after that, he realizes that this is not its normal milk production, and this is deception of the buyer.","Abu ‘Ubayd said: “The word musarrah means a she-camel, cow, or sheep whose milk has been collected in its udder, meaning it has been held there and gathered for days without being milked. The root meaning of tasriyah is to hold back and collect water. One says: I collected and held back the water.","Tasriyah is forbidden because it involves cheating and deception, due to the Prophet’s statement: ‘Do not withhold the milk of camels and sheep.’","The hadith of Abu Hurayrah is authentic according to the scholars of hadith. A number of narrators reported it from him, including Musa ibn Yasar, Abu Salih, Hammam ibn Munabbih, Muhammad ibn Sirin, and Muhammad ibn Ziyad, through authentic chains, as Ibn Abd al-Barr said in al-Tamhid (18/203).","Ibn Mas‘ud also gave legal verdicts according to it, as al-Bukhari mentioned after the hadith of Abu Hurayrah.","And Umar ibn al-Khattab referred back to Ḥamal ibn Malik and others concerning the blood money for the fetus, just as Zayd ibn Thabit and others referred back to a woman from the Ansar concerning the falling of the farewell circumambulation from a menstruating woman.” End quote. Majmu‘ al-Fatawa (4/532).","Shaykh Muhammad Anwar Shah al-Kashmiri said: “This hadith stands as proof against us. Some Hanafis answered it by saying that if a hadith is narrated by someone who was not a jurist, and it conflicts with analogy, then the hadith is set aside and analogy is acted upon. Since the hadith of Abu Hurayrah conflicted with analogy, and was narrated by someone they claimed was not a jurist, they turned to analogy and acted by it.","He then said: This answer is invalid and should not be paid attention to. It has long been used by opponents as a point of criticism. Because of this, it became famous that the Hanafis give precedence to opinion over hadith, though they are far above saying such a thing. In truth, this principle is not authentically reported from Abu Hanifah or any of his companions.","Then he said: In summary, this answer is more deserving of being omitted from books altogether, even if some have mentioned it. And who would dare speak of Abu Hurayrah by saying he was not a jurist? Even if we granted that, the same hadith is also narrated by one who is more learned in jurisprudence, namely Ibn Mas‘ud, and then the same problem returns.” End quote. Fayd al-Bari (3/229).","Add to this that Abu Hurayrah was not alone in narrating this hadith, just as he was not alone in most of his narrations according to my study. Even if there is some discussion regarding the other reports, the foundation shows that this hadith came through multiple routes. Abu Hurayrah was one of those who preserved hadith exactly as he heard it, while others may not have preserved it with the same precision."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2149},{"key":"muslim","label":"مسلم","number":1518}]},{"num":5888,"demo":false,"sanad":"","matn":["عن ابن عباس، عن النبي ﷺ أنه نهى عن بيع الحيوان بالحيوان نسيئة."],"takhrij":"صحيح: رواه عبد الرزاق (١٤١٣٣)، وابن الجارود في المنتقى (٦١٠) ، والبيهقي (٢٨٩-٢٨٨/٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحيوان بالحيوان نسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abd al-Razzaq (14133), Ibn al-Jarud in al-Muntaqa (610), and al-Bayhaqi (5/288–289).","chapter_en":"The Prohibition of Selling an Animal for Another Animal on Deferred Terms","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":55,"content":{"translation":{"en":["Ibn Abbas reported from the Prophet ﷺ, that he forbade selling an animal for another animal on delayed payment terms."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":14133},{"key":"ابن_الجارود/المنتقی","label":"ابن الجارود في المنتقى","number":610},{"key":"البیہقی","label":"البيهقي","number":289},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10532,"n":10621}]},{"num":5889,"demo":false,"sanad":"","matn":["عن سمرة بن جندب أن النبي ﷺ نهى عن بيع الحيوان بالحيوان نسيئة."],"takhrij":"صحيح: رواه أبو داود (٣٣٥٦)، والترمذي (١٢٣٧)، والنسائي (٤٦٢٠)، وابن ماجه (٢٢٧٠)، وأحمد (٢٠١٤٣).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الحيوان بالحيوان نسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3356), al-Tirmidhi (1237), al-Nasa’i (4620), Ibn Majah (2270), and Ahmad (20143).","chapter_en":"The Prohibition of Selling an Animal for Another Animal on Deferred Terms","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":55,"content":{"translation":{"en":["Samurah ibn Jundub reported that the Prophet ﷺ, forbade selling an animal for another animal on deferred terms."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3356},{"key":"tirmidhi","label":"الترمذي","number":1237},{"key":"nasai","label":"النسائي","number":4620},{"key":"ibnmajah","label":"ابن ماجه","number":2270},{"key":"ahmad","label":"مسند الإمام أحمد","number":20143,"n":20143}]},{"num":5890,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أنه قال: نهى رسول اللّٰه ﷺ عن بيع الحيوان بالحيوان نسيئة، اثنين بواحد، ولا بأس به يدا بيد."],"takhrij":"حسن: رواه الترمذي (١٢٣٨)، وابن ماجه (٢٢٧١)، وأحمد (١٤٣٣١). وقال الترمذي: “حسن صحيح”.","grade":"حسن","chapter_ar":"باب النهي عن بيع الحيوان بالحيوان نسيئة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1238), Ibn Majah (2271), and Ahmad (14331). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Selling an Animal for Another Animal on Deferred Terms","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":55,"content":{"translation":{"en":["Jabir ibn Abdullah said: The Messenger of Allah ﷺ, forbade selling an animal for another animal on delayed terms, two for one, but there is no harm in it when it is hand to hand."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1238},{"key":"ibnmajah","label":"ابن ماجه","number":2271},{"key":"ahmad","label":"مسند الإمام أحمد","number":14331,"n":14331}]},{"num":5891,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو أن رسول اللّٰه ﷺ أمره أن يجهز جيشا، فنفدت الإبل، فأمره أن يأخذ في قِلاص الصدقة، فكان يأخذ البعير بالبعيرين إلى إبل الصدقة."],"takhrij":"حسن: رواه أبو داود (٣٣٥٧)، والدار قطني (٣٠٥٤)، والحاكم (٥٧-٥٦/٢)، والبيهقي (٢٨٩-٢٨٧/٥).","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في ذلك","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3357), al-Daraqutni (3054), al-Hakim (2/56–57), and al-Bayhaqi (5/287–289).","chapter_en":"What has been reported regarding the concession in that","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":56,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Messenger of Allah ﷺ, ordered him to equip an army. The camels ran short, so he ordered him to take from the young she-camels of the charity camels. Thus he would take one camel in exchange for two camels, to be delivered from the charity camels."]},"buhuth":{"ar":["وقلاص جمع قلوص، وهي الناقة الشابة."],"en":["And qilas is the plural of qalus, which is a young she-camel."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3357},{"key":"الدار_قطنی","label":"الدار قطني","number":3054},{"key":"hakim","label":"الحاكم","number":57},{"key":"البیہقی","label":"البيهقي","number":289},{"key":"sh9771","label":"سنن الدارقطني","number":3054,"n":3067}]},{"num":5892,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: جاء عبد، فبايع النبي ﷺ على الهجرة، ولم يشعر أنه عبد، فجاء سيده يريده، فقال له النبي ﷺ: (( بعنيه )). فاشتراه بعبدين أسودين، ثم لم يبايع أحدًا بعد حتى يسأله: (( أعبد هو؟ ))."],"takhrij":"صحيح: رواه مسلم ( ١٦٠٢).","grade":"صحيح","chapter_ar":"باب جواز التفاضل في بيع العبيد والإماء إذا كان يدا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1602).","chapter_en":"The permissibility of disparity in selling male and female slaves when it is hand to hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":57,"content":{"translation":{"en":["Jabir ibn Abdullah said: A slave came and pledged allegiance to the Prophet ﷺ, for migration, and he did not realize that he was a slave. Then his master came wanting him back, so the Prophet said to him, “Sell him to me.” He bought him for two black slaves. After that, he would not take anyone’s pledge until he asked, “Is he a slave?”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1602}]},{"num":5893,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: وقعت في سهم دحية جارية جميلة، فاشتراها رسول اللّٰه ﷺ بسبعة أرؤس، ثم دفعها إلى أم سليم تصنعها وتهيئها. قال: وأحسبه قال: وتعتد في بيتها، وهي صفية بنت حيي."],"takhrij":"صحيح: رواه مسلم (٨٧:١٣٦٥)، وأبو داود (٢٩٩٧)، وابن ماجه (٢٢٧٢)، والبيهقي (٣٠٤/٦).","grade":"صحيح","chapter_ar":"باب جواز التفاضل في بيع العبيد والإماء إذا كان يدا بيد","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1365:87), Abu Dawud (2997), Ibn Majah (2272), and al-Bayhaqi (6/304).","chapter_en":"The permissibility of disparity in selling male and female slaves when it is hand to hand","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":57,"content":{"translation":{"en":["Anas ibn Malik said: A beautiful slave-girl fell into the share of Dihyah. The Messenger of Allah ﷺ, bought her for seven slaves, then handed her over to Umm Sulaym to prepare and adorn her. He said: I think he also said: and to let her complete her waiting period in her house. She was Safiyyah bint Huyayy."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":87},{"key":"abudawud","label":"أبو داود","number":2997},{"key":"ibnmajah","label":"ابن ماجه","number":2272},{"key":"البیہقی","label":"البيهقي","number":304},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12756,"n":12882}]},{"num":5894,"demo":false,"sanad":"","matn":["عن سمرة أن النبي ﷺ نهى عن بيع الشاة باللحم."],"takhrij":"صحيح: رواه الحاكم (٣٥/٢)، والبيهقي ٢٩٦/٥).","grade":"صحيح","chapter_ar":"باب النهي عن بيع اللحم بالحيوان","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Hakim (2/35) and al-Bayhaqi (5/296).","chapter_en":"The prohibition of selling meat for a live animal","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":58,"content":{"translation":{"en":["Samurah reported that the Prophet ﷺ, forbade selling a sheep for meat."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":2251,"n":2243}]},{"num":5895,"demo":false,"sanad":"","matn":["عن أنس قال: قال الناس: يا رسول الله، غلا السعر؛ فسعّر لنا. فقال رسول اللّٰه ﷺ:","(( إن اللّٰه هو المسعر القابض الباسط الرزاق، وإني لأرجو أن ألقى الله، وليس أحد منكم يطالبني بمظلمة في دم ولا مال ))."],"takhrij":"صحيح: أخرجه أبو داود (٣٤٥١)، والترمذي (١٣١٤)، وابن ماجه (٢٢٠٠)، وأحمد (١٤٠٥٧ ،١٢٥٩١).","grade":"صحيح","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3451), al-Tirmidhi (1314), Ibn Majah (2200), and Ahmad (12591, 14057).","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Anas said: The people said, “O Messenger of Allah ﷺ, prices have risen, so fix prices for us.” The Messenger of Allah ﷺ, said: “Allah is the One who fixes prices, who withholds, who gives abundantly, and who provides. I truly hope to meet Allah while none of you has any claim against me for an injustice in blood or wealth.”"]},"buhuth":{"ar":["وقال الترمذي: “حسن صحيح”."],"en":["Al-Tirmidhi said: “Hasan Sahih.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3451},{"key":"tirmidhi","label":"الترمذي","number":1314},{"key":"ibnmajah","label":"ابن ماجه","number":2200},{"key":"ahmad","label":"مسند الإمام أحمد","number":14057,"n":14057}]},{"num":5896,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رجلا جاء، فقال: يا رسول الله، سعر. فقال: (( بل أدعو)). ثم جاءه رجل، فقال: يا رسول الله، سعر. فقال: (( بل اللّٰه يخفض ويرفع، وإني لأرجو أن ألقى اللّٰه وليس لأحد عندي مظلمة ))."],"takhrij":"صحيح: رواه أبو داود (٣٤٥٠)، وأحمد (٨٨٥٢ ،٨٤٤٨)، والبيهقي (٢٩/٦).","grade":"صحيح","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3450), Ahmad (8448, 8852), and al-Bayhaqi (6/29).","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Abu Hurayrah reported that a man came and said, “O Messenger of Allah ﷺ, fix prices.” He said, “Rather, I will supplicate.” Then another man came and said, “O Messenger of Allah ﷺ, fix prices.” He said, “Rather, Allah lowers and raises, and I hope to meet Allah while no one has any claim of injustice against me.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3450},{"key":"البیہقی","label":"البيهقي","number":29},{"key":"ahmad","label":"مسند الإمام أحمد","number":8852,"n":8852}]},{"num":5897,"demo":false,"sanad":"","matn":["عن أبي سعيد قال: غلا السعر على عهد رسول اللّٰه ﷺ، فقالوا: لو قوّمت يا رسول الله. قال: (( إني لأرجو أن أفارقكم، ولا يطلبني أحد منكم بمظلمة ظلمته ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٢٠١)، والإمام أحمد (١١٨٠٩)، والطبراني في الأوسط (٥٩٥٢).","grade":"صحيح","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2201), Ahmad (11809), and al-Tabarani in al-Awsat (5952).","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Abu Sa‘id said: Prices rose during the time of the Messenger of Allah ﷺ, so they said, “If only you would set prices, O Messenger of Allah ﷺ.” He said: “I truly hope to leave you while none of you seeks from me redress for any injustice I committed against him.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2201},{"key":"الامام_احمد","label":"الإمام أحمد","number":11809},{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":5952},{"key":"ahmad","label":"مسند الإمام أحمد","number":11809,"n":11809}]},{"num":5898,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري أن يهوديًا قدم زمن النبي ﷺ بثلاثين حمل شعير وتمر، فسعّر مدًّا بمد النبي ﷺ، وليس في الناس يومئذ طعام غيره، وكان قد أصاب الناس قبل ذلك جوع لا يجدون فيه طعامًا، فأتى الناسُ النبيَّ ﷺ يشكون إليه غلاء السعر، فصعد المنبر، فحمد الله وأثنى عليه، ثم قال: (( لا ألقين اللّٰه من قبل أن أعطي أحدًا من مال أحد من غير طيب نفس، إنما البيع عن تراض، ولكن في بيوعكم خصالًا أذكرها لكم: لا تضاغنوا، ولا تناجشوا، ولا تحاسدوا، ولا يسوم الرجل على سوم أخيه، ولا يبيعن حاضر لباد، والبيع عن تراض، وكونوا عباد اللّٰه إخوانًا ))."],"takhrij":"حسن: رواه ابن حبان (٤٩٦٧)، وأبو يعلى (١٣٥٤)، والبيهقي (١٧/٦). واللفظ لابن حبان.","grade":"حسن","chapter_ar":"باب ما جاء في التسعير","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4967), Abu Ya‘la (1354), and al-Bayhaqi (6/17). The wording is that of Ibn Hibban.","chapter_en":"What has been reported regarding price-fixing","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":59,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that during the time of the Prophet ﷺ, a Jew came with thirty loads of barley and dates, and he priced them at one mudd by the mudd of the Prophet, ﷺ. On that day the people had no food other than that, and before that they had been struck by hunger and could not find food. So the people came to the Prophet complaining to him about the high prices. He ascended the pulpit, praised Allah and glorified Him, then said: “I will not meet Allah after having given anyone the wealth of another person without his willing consent. Trade is only by mutual agreement. But in your sales there are practices that I will mention to you: do not nurse grudges, do not practice najsh, do not envy one another, let no man bargain over the bargain of his brother, let not a town-dweller sell for a desert-dweller, and trade is only by mutual consent. Be servants of Allah, brothers to one another.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":1354},{"key":"البیہقی","label":"البيهقي","number":17},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1930,"n":1927}]},{"num":5899,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول اللّٰه ﷺ عن بيعتين في بيعة."],"takhrij":"حسن: رواه الترمذي (١٢٣١)، والنسائي (٤٦٣٢)، وأحمد (٩٥٨٤)، وصحّحه ابن حبان (٤٩٧٣)، والبيهقي (٣٤٣/٥)، وفي رواية (( من باع بيعتين في بيعة فله أوكسهما أو الربا) رواه أبو داود (٣٤٦١) وابن حبان (٤٩٧٤) والحاكم (٤٥ /٢) وقال: صحيح على شرط مسلم.","grade":"حسن","chapter_ar":"باب فيمن باع بيعتين في بيعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1231), al-Nasa’i (4632), Ahmad (9584), authenticated by Ibn Hibban (4973), and al-Bayhaqi (5/343). In another narration: “Whoever conducts two sales in one sale will have either the lesser of the two prices or usury.” Narrated by Abu Dawud (3461), Ibn Hibban (4974), and al-Hakim (2/45), who said: “Authentic according to the conditions of Muslim.”","chapter_en":"Concerning one who conducts two sales in one sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":60,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ, forbade two sales in one sale."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1231},{"key":"nasai","label":"النسائي","number":4632},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4973},{"key":"البیہقی","label":"البيهقي","number":343},{"key":"abudawud","label":"أبو داود","number":3461},{"key":"ibnhibban","label":"ابن حبان","number":4974},{"key":"hakim","label":"الحاكم","number":45},{"key":"ahmad","label":"مسند الإمام أحمد","number":9584,"n":9584}]},{"num":5900,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر قال: قال رسول اللّٰه ﷺ: (( مطل الغني ظلم، وإذا أحلت على مليء فاتبعه، ولا تبع بيعتين في بيعة ))."],"takhrij":"صحيح: رواه الترمذي (١٣٠٩)، وابن ماجه (٢٤٠٤)، وأحمد (٥٣٩٥)، وابن الجارود (٥٩٩)، والبيهقي (٦/٧٧).","grade":"صحيح","chapter_ar":"باب فيمن باع بيعتين في بيعة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1309), Ibn Majah (2404), Ahmad (5395), Ibn al-Jarud (599), and al-Bayhaqi (6/77).","chapter_en":"Concerning one who conducts two sales in one sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":60,"content":{"translation":{"en":["Abdullah ibn Umar said: The Messenger of Allah ﷺ said: “Delay in payment by a wealthy person is injustice. If you are referred for payment to a solvent person, accept the transfer, and do not conduct two sales in one sale.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1309},{"key":"ibnmajah","label":"ابن ماجه","number":2404},{"key":"ابن_الجارود","label":"ابن الجارود","number":599},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":5395,"n":5395},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11390,"n":11494}]},{"num":5901,"demo":false,"sanad":"","matn":["عن ابن عمر قال: سمعت رسول اللّٰه ﷺ يقول: (( إذا تبايعتم بالعينة، وأخذتم أذناب البقر، ورضيتم بالزرع، وتركتم الجهاد سلّط اللّٰه عليكم ذُلَّ لا ينزعه حتى ترجعوا إلى دينكم))."],"takhrij":"حسن: رواه أبو داود (٣٤٦٢)، والبيهقي في الكبرى (٣١٦/٥).","grade":"حسن","chapter_ar":"باب ماجاء في النهي عن بيع العينة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3462) and al-Bayhaqi in al-Kubra (5/316).","chapter_en":"What has been reported regarding the prohibition of the ‘inah sale","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":61,"content":{"translation":{"en":["Ibn Umar said: I heard the Messenger of Allah ﷺ, say: “When you deal by ‘inah, hold onto the tails of cattle, become content with farming, and abandon jihad, Allah will place humiliation upon you, and He will not remove it until you return to your religion.”"]},"buhuth":{"ar":["« والعِينة ) -بكسر العين - هو أن يبيع شيئا من غيره بثمن مؤجل، ويسلم إلى المشتري، ثم يشتريه قبل قبض الثمن بثمن أقل مما باع به، وينقده الثمن. وأما إذا اشترك في البيع ثلاثة أطراف فيخرج من بيع العينة، وصورته: أن يشتري رجل من البائع سلعة مؤجلا، ويقبض على السلعة، ثم يبيعها لرجل ثالث غير البائع بأقل مما اشترى بنقد. فهذا جائز باتفاق أهل العلم لتوفر جميع شروط البيع فيه."],"en":["‘Inah — with the letter ‘ayn pronounced with kasrah — is when someone sells an item to another for a deferred price and delivers it to the buyer, then buys it back before receiving the deferred payment for a lower price, taking that lower price in cash.","But if three parties are involved, then it is no longer the ‘inah sale. Its form is that a man buys a commodity from the seller on deferred payment and takes possession of it, then sells it to a third person, other than the original seller, for less than what he bought it for, taking cash. This is permissible by agreement of the scholars because all the conditions of sale are fulfilled in it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3462},{"key":"البیہقی/الکبری","label":"البيهقي في الكبرى","number":316},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":10703,"n":10793}]},{"num":5902,"demo":false,"sanad":"","matn":["عن ابن عباس قال: نهى رسول الله ﷺ عن بيع المغانم حتى تقسم، وعن الحبالى أن يُوطأنَ حتى يضعن ما في بطونهن، ولحم كل ذي ناب من السباع."],"takhrij":"حسن: رواه النسائي ( ٤٦٤٥)، والدار قطني (٦٩-٦٨/٣)، والحاكم (١٣٧/٢).","grade":"حسن","chapter_ar":"باب النهي عن بيع المغانم حتى تقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4645), al-Daraqutni (3/68–69), and al-Hakim (2/137).","chapter_en":"The prohibition of selling war booty before it is divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":64,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ, forbade the sale of war booty before it is divided, and forbade pregnant women from being approached sexually until they deliver what is in their wombs, and forbade the meat of every beast with fangs."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4645},{"key":"الدار_قطنی","label":"الدار قطني","number":69},{"key":"sh9771","label":"سنن الدارقطني","number":3051,"n":3064},{"key":"hakim","label":"المستدرك على الصحيحين","number":2611,"n":2597}]},{"num":5903,"demo":false,"sanad":"","matn":["عن رويفع بن ثابت قال: أما إني لا أقول لكم إلا ما سمعت رسول اللّٰه ﷺ يقول يوم حنين قال: (( لا يحل لامرئ يؤمن بالله واليوم الآخر أن يسقي ماءه زرع غيره)). يعني إتيان الحبالى.","( ولا يحل لا مرئ يؤمن بالله واليوم الآخر أن يقع على امرأة من السبي حتى يستبرئها، ولا يحل لامرئ يؤمن بالله واليوم الآخر أن يبيع مغنما حتى يُقسم))."],"takhrij":"حسن: رواه أبو داود (٢٧٠٨ ،٢١٥٨)، وأحمد (١٦٩٩٧)، والدارمي (٢٥٢٠).","grade":"حسن","chapter_ar":"باب النهي عن بيع المغانم حتى تقسم","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2158, 2708), Ahmad (16997), and al-Darimi (2520).","chapter_en":"The prohibition of selling war booty before it is divided","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":64,"content":{"translation":{"en":["Ruwayfi‘ ibn Thabit said: I will only tell you what I heard the Messenger of Allah ﷺ, say on the day of Hunayn. He said: “It is not lawful for a man who believes in Allah and the Last Day to pour his water upon the crop of another,” meaning intercourse with pregnant captive women.","“And it is not lawful for a man who believes in Allah and the Last Day to have relations with a captive woman until she is cleared by waiting, and it is not lawful for a man who believes in Allah and the Last Day to sell war booty until it has been divided.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2708},{"key":"darimi","label":"الدارمي","number":2520},{"key":"ahmad","label":"مسند الإمام أحمد","number":16997,"n":16997}]},{"num":5904,"demo":false,"sanad":"","matn":["عن أبي أيوب قال: سمعت رسول اللّٰه ﷺ يقول: (( من فرق بين الوالدة وولدها فرق اللّٰه بينه وبين أحبته يوم القيامة ))."],"takhrij":"حسن: رواه الترمذي (١٢٨٣) وحسّنه، والدار قطني (٦٧ /٣)، والحاكم (٥٥ /٢)، وأحمد (٢٣٤٩٩).","grade":"حسن","chapter_ar":"باب كراهية التفريق بين الوالدة وولدها الصغير وبين الأخوين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1283), who graded it hasan, al-Daraqutni (3/67), al-Hakim (2/55), and Ahmad (23499).","chapter_en":"The dislike of separating a mother from her young child and separating two siblings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":66,"content":{"translation":{"en":["Abu Ayyub said: I heard the Messenger of Allah ﷺ, say: “Whoever separates a mother from her child, Allah will separate him from his loved ones on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1283},{"key":"الدار_قطنی","label":"الدار قطني","number":67},{"key":"hakim","label":"الحاكم","number":55},{"key":"sh9771","label":"سنن الدارقطني","number":3047,"n":3060},{"key":"ahmad","label":"مسند الإمام أحمد","number":23499,"n":23499}]},{"num":5905,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: قدم على النبي ﷺ سبي، فأمرني ببيع أخوين، فبعتهما وفرقت بينهما، ثم أتيت النبي ﷺ فأخبرته، فقال: (( أدركهما، فارتجعهما، وبعهما جميعًا، ولا تفرق بينهما ))."],"takhrij":"حسن: رواه الدار قطني (٣٠٤٠)، والحاكم (٥٤/٢)، والبيهقي (١٢٧/٩).","grade":"حسن","chapter_ar":"باب كراهية التفريق بين الوالدة وولدها الصغير وبين الأخوين","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (3040), al-Hakim (2/54), and al-Bayhaqi (9/127).","chapter_en":"The dislike of separating a mother from her young child and separating two siblings","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":66,"content":{"translation":{"en":["Ali ibn Abi Talib said: Some captives were brought to the Prophet ﷺ, and he ordered me to sell two brothers. So I sold them and separated them. Then I came to the Prophet and informed him, and he said: “Catch up with them, take them back, sell them together, and do not separate them.”"]}},"tuhfa":{},"refs":[{"key":"الدار_قطنی","label":"الدار قطني","number":3040},{"key":"البیہقی","label":"البيهقي","number":127},{"key":"sh9771","label":"سنن الدارقطني","number":3040,"n":3053},{"key":"hakim","label":"المستدرك على الصحيحين","number":2331,"n":2322}]},{"num":5906,"demo":false,"sanad":"","matn":["عن سلمة بن الأكوع قال: غزونا فزارة وعلينا أبو بكر، أمره رسول اللّٰه ﷺ علينا، فلما كان بيننا وبين الماء ساعة أمرنا أبو بكر فعرسنا، ثم شن الغارة، فورد الماء، فقتل من قتل عليه، وسبى، وأنظر إلى عنق من الناس فيهم الذراري، فخشيت أن يسبقوني إلى الجبل، فرميت بسهم بينهم وبين الجبل، فلما رأوا السهم وقفوا، فجئت بهم أسوقهم، وفيهم امرأة من بني فزارة عليها قشع من أدم - قال: القشع: النطع - معها ابنة لها من أحسن العرب، فسقتهم حتى أتيت بهم أبا بكر، فنفلني أبو بكر ابنتها، فقدمنا المدينة وما كشفت لها ثوبًا، فلقيني رسول اللّٰه ﷺ في السوق، فقال: (( يا سلمة، هب لي المرأة )). فقلت: يا رسول اللّٰه، والله لقد أعجبتني وما كشفت لها ثوبًا. ثم لقيني رسول اللّٰه ﷺ من الغد في السوق، فقال لي: (( يا سلمة، هب لي المرأة، لله أبوك )). فقلت: هي لك يا رسول اللّٰه، فوالله ما كشفت لها ثوبًا. فبعث بها رسول اللّٰه ﷺ إلى أهل مكة، ففدى بها ناسًا من المسلمين كانوا أسروا بمكة."],"takhrij":"صحيح: رواه مسلم (١٧٥٥).","grade":"صحيح","chapter_ar":"باب جواز التفريق بين الوالدة وولدها الكبير في البيع والهبة","chapter_ur":"","part_ar":"كتاب البيوع","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1755).","chapter_en":"The permissibility of separating a mother from her grown child in sale and gift","part_en":"The Book of Sales","group_ar":"جموع أبواب ما جاء في البيوع المنهي عنها","group_en":"Collection of reports regarding forbidden sales","part_no":17,"group_no":13,"chapter_no":67,"content":{"translation":{"en":["Salamah ibn al-Akwa‘ said: We fought against Fazarah with Abu Bakr over us, appointed over us by the Messenger of Allah, ﷺ. When there remained about an hour between us and the water, Abu Bakr ordered us, so we halted in the latter part of the night. Then he launched the raid, and we reached the water. Some were killed there, and some were taken captive. I saw a group of people among whom were children, and I feared they would reach the mountain before me, so I shot an arrow between them and the mountain. When they saw the arrow, they stopped. I came to them driving them along, and among them was a woman from Banu Fazarah wearing a leather covering — he said: al-qash‘ means a leather sheet — and with her was a daughter of hers who was among the most beautiful of the Arabs. I drove them until I brought them to Abu Bakr, and Abu Bakr gave me her daughter as an extra share. We then came to Madinah, and I had not had intercourse with her. Then the Messenger of Allah ﷺ, met me in the marketplace and said: “O Salamah, give me the woman.” I said: O Messenger of Allah ﷺ, by Allah, she pleased me, and I have not had intercourse with her. Then the Messenger of Allah ﷺ met me the next day in the market and said to me: “O Salamah, give me the woman. May your father be honored.” So I said: She is yours, O Messenger of Allah ﷺ. By Allah, I had not had intercourse with her. Then the Messenger of Allah ﷺ sent her to the people of Makkah, and by her he ransomed some Muslims who had been captured in Makkah."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1755}]},{"num":5907,"demo":false,"sanad":"","matn":["عن أبي ذر، عن النبي ﷺ فيما روى عن الله تبارك وتعالى أنه قال:","«يَا عِبَادِي، إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي، وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا، فَلَا تَظَالَمُوا.","يَا عِبَادِي، كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ، فَاسْتَهْدُونِي أَهْدِكُمْ.","يَا عِبَادِي، كُلُّكُمْ جَائِعٌ إِلَّا مَنْ أَطْعَمْتُهُ، فَاسْتَطْعِمُونِي أُطْعِمْكُمْ.","يَا عِبَادِي، كُلُّكُمْ عَارٍ إِلَّا مَنْ كَسَوْتُهُ، فَاسْتَكْسُونِي أَكْسُكُمْ.","يَا عِبَادِي، إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا، فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ.","يَا عِبَادِي، إِنَّكُمْ لَنْ تَبْلُغُوا ضَرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي.","يَا عِبَادِي، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ، وَإِنْسَكُمْ وَجِنَّكُمْ، كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا.","يَا عِبَادِي، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ، وَإِنْسَكُمْ وَجِنَّكُمْ، كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ، مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا.","يَا عِبَادِي، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ، وَإِنْسَكُمْ وَجِنَّكُمْ، قَامُوا فِي صَعِيدٍ وَاحِدٍ فَسَأَلُونِي، فَأَعْطَيْتُ كُلَّ إِنْسَانٍ مَسْأَلَتَهُ، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ.","يَا عِبَادِي، إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللَّهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ».","قال سعيد: كان أبو إدريس الخولاني إذا حدث بهذا الحديث جثا على ركبتيه."],"takhrij":"صحيح: رواه مسلم (٢٥٧٧).","grade":"صحيح","chapter_ar":"باب ماجاء في تحريم الظلم، وإن الله حرم الظلم على نفسه.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2577).","chapter_en":"What has been reported concerning the prohibition of injustice, and that Allah has forbidden injustice for Himself","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Dharr reported from the Prophet ﷺ concerning what he narrated from Allah, Blessed and Exalted, that He said:","“O My servants, I have forbidden injustice for Myself and have made it forbidden among you, so do not wrong one another.","O My servants, all of you are astray except those whom I guide, so ask Me for guidance and I will guide you.","O My servants, all of you are hungry except those whom I feed, so ask Me for food and I will feed you.","O My servants, all of you are unclothed except those whom I clothe, so ask Me for clothing and I will clothe you.","O My servants, you commit sins by night and by day, and I forgive all sins, so seek My forgiveness and I will forgive you.","O My servants, you can never attain the ability to harm Me so as to harm Me, nor can you attain the ability to benefit Me so as to benefit Me.","O My servants, if the first of you and the last of you, the human beings among you and the jinn among you, were all as righteous as the most righteous heart of one man among you, that would not increase My dominion in the least.","O My servants, if the first of you and the last of you, the human beings among you and the jinn among you, were all as wicked as the most wicked heart of one man among you, that would not diminish My dominion in the least.","O My servants, if the first of you and the last of you, the human beings among you and the jinn among you, all stood together on one plain and asked of Me, and I gave every person what he asked for, that would diminish what I possess no more than a needle diminishes the sea when it is dipped into it.","O My servants, they are only your deeds. I record them for you and then repay you for them in full. Whoever finds good, let him praise Allah, and whoever finds other than that, let him blame no one but himself.”","Saʿīd said: Whenever Abū Idrīs al-Khawlānī narrated this hadith, he would kneel down."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2577}]},{"num":5908,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: قال رسول اللّٰه ﷺ: (( إن الظلم ظلمات يوم القيامة ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٤٧)، ومسلم (٢٥٧٩).","grade":"متفق عليه","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2447) and Muslim (2579).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Umar said: The Messenger of Allah ﷺ said: “Indeed, injustice will be darknesses on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2447},{"key":"muslim","label":"مسلم","number":2579}]},{"num":5909,"demo":false,"sanad":"","matn":["عن جابر أن رسول اللّٰه ﷺ قال: (( اتقوا الظلم؛ فإن الظلم ظلمات يوم القيامة، واتقوا الشح؛ فإن الشح أهلك من كان قبلكم، حملهم على أن سفكوا دماءهم، واستحلوا محارمهم ))."],"takhrij":"صحيح: رواه مسلم (٢٥٧٨).","grade":"صحيح","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2578).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Jabir reported that the Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be darknesses on the Day of Resurrection. And beware of greed, for greed destroyed those before you. It drove them to shed their blood and make lawful their sacred things.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2578}]},{"num":5910,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( إياكم والظلم؛ فإن الظلم ظلمات عند اللّٰه يوم القيامة. وإياكم والفحش؛ فإن اللّٰه لا يحب الفحش والتفحش. وإياكم والشح؛ فإنه دعا من قبلكم، فاستحلوا محارمهم، وسفكوا دماءهم، وقطعوا أرحامهم ))."],"takhrij":"حسن: رواه أحمد (٩٥٧٠ ،٩٥٦٩)، وصحّحه ابن حبان (٦٢٤٨)، والحاكم (١٢/١).","grade":"حسن","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (9569, 9570), authenticated by Ibn Hibban (6248), and al-Hakim (1/12).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be darknesses before Allah on the Day of Resurrection. Beware of obscenity, for Allah does not love obscenity and shamelessness. And beware of greed, for it led those before you to make sacred things lawful, shed blood, and cut off family ties.”"]}},"tuhfa":{},"refs":[{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":6248},{"key":"hakim","label":"الحاكم","number":12},{"key":"ahmad","label":"مسند الإمام أحمد","number":9569,"n":9569}]},{"num":5911,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو أن رسول اللّٰه ﷺ قال: (( إياكم والظلم؛ فإن الظلم ظلمات يوم القيامة. وإياكم والفحش؛ فإن اللّه لا يحب الفحش ولا التفحش. وإياكم والشّح؛ فإنما أهلك من كان قبلكم الشُّح، أَمَرهم بالقطيعة، فقطعوا أرحامهم، وأَمَرهم بالفجور ففجروا، وأَمَرهم بالبخل فبخلوا)). فقال رجل: يا رسول اللّه، وأي الإسلام أفضل؟ قال: (( أن يسلم المسلمون من لسانك ويدك). قال يا رسول الله: فأي الهجرة أفضل؟ قال: (( أن تهجر ما كره ربك)). قال: وقال رسول اللّٰه ﷺ: (( الهجرة هجرتان: هجرة الحاضر، وهجرة البادي، أما البادي فيجيب إذا دعي، ويطيع إذا أُمِر. وأما الحاضر فهو أعظمهما بلية، وأعظمهما أجرا))."],"takhrij":"صحيح: رواه أحمد (٦٨٣٧)، وصحّحه ابن حبان (٥١٧٦)، والحاكم (١١/١).","grade":"صحيح","chapter_ar":"باب الظلم ظلمات يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (6837), authenticated by Ibn Hibban (5176), and al-Hakim (1/11).","chapter_en":"Injustice will be darknesses on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Messenger of Allah ﷺ said: “Beware of injustice, for injustice will be darknesses on the Day of Resurrection. Beware of obscenity, for Allah does not love obscenity or shameless conduct. Beware of greed, for greed is what destroyed those before you. It commanded them to sever ties, so they severed their family ties. It commanded them to commit immorality, so they committed immorality. It commanded them to be miserly, so they became miserly.” Then a man said: O Messenger of Allah ﷺ, which form of Islam is best? He said: “That the Muslims are safe from your tongue and your hand.” He said: O Messenger of Allah ﷺ, then which migration is best? He said: “That you abandon what your Lord dislikes.” And the Messenger of Allah ﷺ said: “Migration is of two kinds: the migration of the town-dweller and the migration of the desert-dweller. As for the desert-dweller, he responds when called and obeys when commanded. As for the town-dweller, his trial is greater of the two, and his reward is greater of the two.”"]}},"tuhfa":{},"refs":[{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5176},{"key":"hakim","label":"الحاكم","number":11},{"key":"ahmad","label":"مسند الإمام أحمد","number":6837,"n":6837},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1968,"n":1965}]},{"num":5912,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس أن النبي ﷺ بعث معاذا إلى اليمن، فقال: (( اتق دعوة المظلوم؛ فإنه ليس بينها وبين اللّٰه حجاب))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٤٨)، ومسلم (١٩).","grade":"متفق عليه","chapter_ar":"باب الاتقاء من دعوة المظلوم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2448) and Muslim (19).","chapter_en":"Guarding oneself against the supplication of the one who has been wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Abbas reported that the Prophet ﷺ sent Muadh to Yemen and said: “Beware of the supplication of the one who has been wronged, for there is no barrier between it and Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2448},{"key":"muslim","label":"مسلم","number":19}]},{"num":5913,"demo":false,"sanad":"","matn":["عن سعيد بن زيد بن نفيل يقول: سمعت رسول اللّٰه ﷺ يقول: (( من أخذ شبرا من الأرض ظلما طوقه إلى سبع أرضين))."],"takhrij":"متفق عليه: رواه البخاري (٣١٩٨)، ومسلم (١٣٩ :١٦١٠).","grade":"متفق عليه","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3198) and Muslim (1610:139).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Sa‘id ibn Zayd ibn Nufayl said: I heard the Messenger of Allah ﷺ say: “Whoever takes a handspan of land wrongfully will be encircled with it down to seven earths.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3198},{"key":"muslim","label":"مسلم","number":139}]},{"num":5914,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( لا يأخذ أحد شبرًا من الأرض بغير حقه إلا طوقه اللّٰه إلى سبع أرضين يوم القيامة ))."],"takhrij":"صحيح: رواه مسلم (١٦١١).","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1611).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “No one takes a handspan of land without right except that Allah will encircle him with it down to seven earths on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1611}]},{"num":5915,"demo":false,"sanad":"","matn":["عن أم المؤمنين عائشة قالت: قال رسول اللّٰه ﷺ: (( من ظلم قيد شبر من الأرض طوقه من سبع أرضين ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٥٣)، ومسلم (١٦١٢).","grade":"متفق عليه","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2453) and Muslim (1612).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["The Mother of the Believers, Aishah, said: The Messenger of Allah ﷺ said: “Whoever wrongfully takes even the measure of a handspan of land will be encircled with it from seven earths.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2453},{"key":"muslim","label":"مسلم","number":1612}]},{"num":5916,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال النبي ﷺ: (( من أخذ من الأرض شيئا بغير حق، خسف به يوم القيامة إلى سبع أرضين ))."],"takhrij":"صحيح: رواه البخاري (٢٤٥٤).","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2454).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ibn Umar said: The Prophet ﷺ said: “Whoever takes anything from land without right will be sunk with it on the Day of Resurrection down to seven earths.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2454}]},{"num":5917,"demo":false,"sanad":"","matn":["عن يعلى بن مرة الثقفي يقول: سمعت رسول اللّٰه ﷺ يقول: (( من أخذ أرضا بغير حق كلف أن يحمل ترابها إلى المحشر))."],"takhrij":"حسن: رواه أحمد (١٧٥٥٨).","grade":"حسن","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (17558).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ya‘la ibn Murrah al-Thaqafi said: I heard the Messenger of Allah ﷺ say: “Whoever takes land without right will be burdened with carrying its soil to the place of gathering.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":17558,"n":17558}]},{"num":5918,"demo":false,"sanad":"","matn":["عن أبي الطفيل قال: قلنا لعلي بن أبي طالب: أخبرنا بشيء أسره إليك رسول اللّٰه ﷺ، فقال: ما أسر إلي شيئا كتمه الناس، ولكني سمعته يقول: (( لعن اللّٰه من ذبح لغير الله، ولعن اللّٰه من آوى محدثا، ولعن اللّٰه من لعن والديه، ولعن اللّٰه من غير المنار))."],"takhrij":"صحيح: رواه مسلم (٤٤ :١٩٧٨).","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1978:44).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu al-Tufayl said: We said to Ali ibn Abi Talib: Tell us something the Messenger of Allah ﷺ, confided to you privately. He said: He did not confide to me anything that he concealed from the people, but I heard him say: “May Allah curse the one who sacrifices for other than Allah. May Allah curse the one who shelters an offender. May Allah curse the one who curses his parents. May Allah curse the one who changes boundary markers.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":44}]},{"num":5919,"demo":false,"sanad":"","matn":["عن الحارث بن البرصاء قال: سمعت رسول اللّٰه ﷺ يقول -وهو يمشي بين جمرتين من الجمار -، وهو يقول: (( من أخذ شبرا من مال امرئ مسلم بيمين فاجرة فليتبوأ بيتا من النار))."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (٥١٦٥).","grade":"صحيح","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban in his Sahih (5165).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Harith ibn al-Barsa’ said: I heard the Messenger of Allah ﷺ, while walking between two of the Jamarat, saying: “Whoever takes a handspan of a Muslim man’s property by a sinful oath, let him prepare for himself a house in the Fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":5165},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2825,"n":2822}]},{"num":5920,"demo":false,"sanad":"","matn":["عن وائل بن حجر قال: قال رسول اللّٰه ﷺ: (( من غَصَبَ رجلاً أرضاً ظلماً، لقيَ اللّهَ وهو عليه غضبانُ))."],"takhrij":"حسن: رواه الطبراني في الكبير (١٨/٢٢).","grade":"حسن","chapter_ar":"باب إثم من ظلم شيئا من الأرض","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (22/18).","chapter_en":"The sin of one who wrongfully takes any part of land","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Wa’il ibn Hujr said: The Messenger of Allah ﷺ said: “Whoever usurps a man’s land unjustly will meet Allah while He is angry with him.”"]},"buhuth":{"ar":["فقه الحديث:","ويكون حساب كل واحد حسب جريمته، فمنهم من يطوق به مثله من الأرض، ومنهم من يحاسب بحمل ترابها إلى المحشر، ومنهم من يحاسب بدخوله النار، ومنهم من يحاسب بغضب اللّٰه عليه، والنبي ﷺ بين هذه الأشكال من الجزاء في أوقات مختلفة."],"en":["Understanding of the hadith:","Each person’s reckoning will be according to his crime. Some will be encircled with the like of what they took from the land, some will be made to carry its soil to the gathering place, some will be punished by entering the Fire, and some will be punished by Allah’s anger against them. The Prophet ﷺ explained these different forms of punishment at different times."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":18}]},{"num":5921,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود قال: قال النبي ﷺ: (( أول ما يقضى بين الناس بالدماء))."],"takhrij":"متفق عليه: رواه البخاري (٦٥٣٣)، ومسلم (١٦٧٨).","grade":"متفق عليه","chapter_ar":"باب قصاص المظالم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6533) and Muslim (1678).","chapter_en":"Retribution for injustices on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abdullah ibn Mas‘ud said: The Prophet ﷺ said: “The first matter to be judged among the people will be bloodshed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6533},{"key":"muslim","label":"مسلم","number":1678}]},{"num":5922,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، عن رسول اللّٰه ﷺ قال: (( إذا خَلَص المؤمنون من النار حُبِسوا بقنطرة بين الجنة والنار، فيتقاصُّون مظالم كانت بينهم في الدنيا، حتى إذا نُقُّوا وهُذِّبوا أذن لهم بدخول الجنة، فوالذي نفس محمد بيده لأحدهم بمسكنه في الجنة أدلُّ بمنزله كان في الدنيا))."],"takhrij":"صحيح: رواه البخاري (٢٤٤٠).","grade":"صحيح","chapter_ar":"باب قصاص المظالم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2440).","chapter_en":"Retribution for injustices on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ said: “When the believers are delivered from the Fire, they will be stopped at a bridge between Paradise and the Fire, and they will settle the injustices that existed among them in the world. When they have been purified and refined, permission will be given to them to enter Paradise. By the One in whose hand is the soul of Muhammad, one of them will know his dwelling in Paradise better than he knew his home in the world.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2440}]},{"num":5923,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( من كانت له مظلمة لأحد من عرضه أو شيء فليتحلله منه اليوم قبل أن لا يكون دينار ولا درهم، إن كان له عمل صالح أخذ منه بقدر مظلمته، وإن لم تكن له حسنات أخذ من سيئات صاحبه فحمل عليه ))."],"takhrij":"صحيح: رواه البخاري (٢٤٤٩).","grade":"صحيح","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2449).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever has wronged someone with regard to his honor or anything else should seek his pardon today, before there will be neither dinar nor dirham. If he has righteous deeds, some of them will be taken from him according to the measure of his wrong. If he has no good deeds, sins from the wronged person will be taken and loaded upon him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2449}]},{"num":5924,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال: (( أتدرون ما المفلس؟». قالوا: المفلس فينا من لا درهم له ولا متاع. فقال: (( إن المفلس من أمتي يأتي يوم القيامة بصلاة وصيام وزكاة، ويأتي قد شتم هذا، وقذف هذا، وأكل مال هذا، وسفك دم هذا، وضرب هذا، فيُعْطَى هذا من حسناته، وهذا من حسناته، فإن فنيت حسناته قبل أن يقضى ما عليه أخذ من خطاياهم فطرحت عليه، ثم طرح في النار ))."],"takhrij":"صحيح: رواه مسلم (٢٥٨١).","grade":"صحيح","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2581).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Do you know who the bankrupt one is?” They said: The bankrupt among us is the one who has neither money nor goods. He said: “The bankrupt one from my nation is the one who comes on the Day of Resurrection with prayer, fasting, and zakah, but he comes having insulted this one, slandered this one, consumed the wealth of this one, shed the blood of this one, and struck this one. So this one will be given from his good deeds, and that one will be given from his good deeds. If his good deeds run out before what he owes is settled, some of their sins will be taken and cast upon him, then he will be thrown into the Fire.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2581}]},{"num":5925,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( لتؤدن الحقوق إلى أهلها يوم القيامة، حتى يقاد للشاة الجلْحاءِ من الشاة القَرْناءِ ))."],"takhrij":"صحيح: رواه مسلم (٢٥٨٢).","grade":"صحيح","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2582).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Rights will surely be returned to their owners on the Day of Resurrection, until retaliation will be taken for the hornless sheep against the horned sheep.”"]},"buhuth":{"ar":["( والجلحاء)) هي الجماء التي لا قرن لها، والقصاص من القرناء والجلحاء ليس هو من قصاص التكليف؛ إذ لا تكليف عليها، إنما هو قصاص مقابلة، وفيه تصريح بحشر البهائم يوم القيامة، ويدل عليه قوله تعالى: (وَإِذَا الْوُحُوشُ حُشِرَتْ) [سورة التكوير: ٥]. ولكن قال العلماء: ليس من شرط الحشر في القيامة المجازاة والعقاب والثواب، أفاده النووي باختصار. وفيه إظهار قدرة اللّٰه تعالى بأنه يستطيع أن يحشر البهائم يوم القيامة التي لا تكليف عليها، فكيف لا يحشر الآدميين."],"en":["The hornless sheep is the one with no horns. The retaliation between the horned and hornless sheep is not a matter of moral accountability, because animals are not legally accountable; rather, it is a form of exact compensation. It clearly shows that animals will be gathered on the Day of Resurrection, and this is indicated by the verse: “And when the wild beasts are gathered.” [Surat al-Takwir: 5]","But the scholars said that being gathered on the Day of Resurrection does not necessarily mean reward, punishment, or moral accountability. Al-Nawawi mentioned this briefly. It also shows Allah’s power: if He gathers animals on the Day of Resurrection, even though they are not morally accountable, then how could He not gather human beings?"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2582}]},{"num":5926,"demo":false,"sanad":"","matn":["عن عبد اللّٰه، عن النبي ﷺ قال: (( إن الشيطان قد يئس أن تعبد الأصنام في أرض العرب، ولكنه سيرضى منكم بدون ذلك بالمحقَّرات، وهي الموبقات يوم القيامة، اتقوا المظالم ما استطعتم؛ فإن العبد يجيء بالحسنات يوم القيامة يرى أنها ستنجيه، فما زال عبد يقوم، فيقول: يا رب، ظلمني عبدك مظلمة. فيقول: امحوا من حسناته. وما يزال كذلك حتى ما يبقى له حسنة من الذنوب، وإن مثل ذلك كسفر نزلوا بفلاة من الأرض ليس معهم حطب، فتفرق القوم ليحتطبوا، فلم يلبثوا أن حطبوا، فأعظموا النار، وطبخوا ما أرادوا، وكذلك الذنوب))."],"takhrij":"حسن: رواه أبو يعلى (٥١٢٢)، والإمام أحمد (٣٨١٨).","grade":"حسن","chapter_ar":"باب ماجاء في أخذ حسنات الظالم، وإعطائها للمظلوم يوم القيامة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Ya‘la (5122) and Ahmad (3818).","chapter_en":"What has been reported about taking the oppressor’s good deeds and giving them to the oppressed on the Day of Resurrection","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abdullah reported from the Prophet ﷺ that he said: “Satan has despaired of idols being worshipped in the land of the Arabs, but he will be content with lesser things from you, and they are the destructive sins on the Day of Resurrection. Avoid injustices as much as you can, for a servant will come on the Day of Resurrection with good deeds, thinking they will save him. Then one servant after another will stand and say: My Lord, Your servant wronged me. So it will be said: Wipe away from his good deeds. This will continue until not a single good deed remains for him because of those sins. The likeness of that is like travelers who stopped in a barren land with no firewood. The people dispersed to gather wood, and before long they had gathered enough, made a great fire, and cooked what they wished. That is how sins are.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":5122},{"key":"الامام_احمد","label":"الإمام أحمد","number":3818},{"key":"sh12520","label":"مسند أبي يعلى","number":5122,"n":5127}]},{"num":5927,"demo":false,"sanad":"","matn":["عن أبي موسى قال: قال رسول اللّٰه ﷺ: (( إن اللّٰه ليملي للظالم حتى إذا أخذه لم يفلته )).","قال: ثم قرأ: (وَكَذَلِكَ أَخْذُ رَبِّكَ إِذَا أَخَذَ الْقُرَى وَهِيَ ظَالِمَةٌ إِنَّ أَخْذَهُ أَلِيمٌ شَدِيدٌ) [سورة هود: ١٠٢]."],"takhrij":"متفق عليه: رواه البخاري (٤٦٨٦)، ومسلم (٢٥٨٣).","grade":"متفق عليه","chapter_ar":"باب إن الله يُملي الظالم ليرجع من ظلمه","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4686) and Muslim (2583).","chapter_en":"Allah gives respite to the wrongdoer so that he may return from his wrongdoing","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Musa said: The Messenger of Allah ﷺ said: “Indeed, Allah gives respite to the wrongdoer, but when He seizes him, He does not let him escape.” Then he recited: “And thus is the seizure of your Lord when He seizes the towns while they are committing wrong. Indeed, His seizure is painful and severe.” [Surat Hud: 102]"]},"intro":{"ar":["قال اللّه تعالى: (وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا عَمَّا يَعْمَلُ الظَّالِمُونَ إِنَّمَا يُؤَخِّرُهُمْ لِيَوْمٍ تَشْخَصُ فِيهِ الْأَبْصَارُ مُهْطِعِينَ مُقْنِعِي رُءُوسِهِمْ لَا يَرْتَدُّ إِلَيْهِمْ طَرْفُهُمْ وَأَفْئِدَتُهُمْ هَوَاءٌ) [سورة إبراهيم: ٤٢-٤٣]."],"en":["Allah the Exalted said: “Do not think that Allah is unaware of what the wrongdoers do. He only delays them until a Day when eyes will stare in horror, rushing forward, with heads raised up, their gaze not returning to them, and their hearts empty.” [Surat Ibrahim: 42–43]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4686},{"key":"muslim","label":"مسلم","number":2583}]},{"num":5928,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عمر أخبر أن رسول اللّٰه ﷺ قال: (( المسلم أخو المسلم، لا يظلمه، ولا يسلمه، ومن كان في حاجة أخيه كان اللّٰه في حاجته، ومن فرّج عن مسلم كربة فرّج اللّٰه عنه كربة من كربات يوم القيامة، ومن ستر مسلما ستره اللّٰه يوم القيامة ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٤٢)، ومسلم (٢٥٨٠).","grade":"متفق عليه","chapter_ar":"باب لا يظلم المسلم المسلم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2442) and Muslim (2580).","chapter_en":"A Muslim does not wrong another Muslim","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ said: “The Muslim is the brother of the Muslim. He does not wrong him, nor does he abandon him. Whoever is engaged in fulfilling his brother’s need, Allah will fulfill his need. Whoever relieves a Muslim of a hardship, Allah will relieve him of a hardship from the hardships of the Day of Resurrection. Whoever conceals a Muslim, Allah will conceal him on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2442},{"key":"muslim","label":"مسلم","number":2580}]},{"num":5929,"demo":false,"sanad":"","matn":["عن أنس قال: قال رسول اللّٰه ﷺ: (( انصر أخاك ظالمًا أو مظلومًا )). قالوا: يا رسول اللّٰه، هذا ننصره مظلومًا، فكيف ننصره ظالمًا؟ قال: (( تأخذ فوق يديه ))."],"takhrij":"صحيح: رواه البخاري (٢٤٤٤).","grade":"صحيح","chapter_ar":"باب نصر المسلم ظالما أو مظلوما.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2444).","chapter_en":"Helping a Muslim whether he is the wrongdoer or the one wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said, “Help your brother whether he is a wrongdoer or one who has been wronged.” They said: O Messenger of Allah ﷺ, we understand helping him when he is wronged, but how do we help him when he is the wrongdoer? He said, “By restraining his hands.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2444}]},{"num":5930,"demo":false,"sanad":"","matn":["عن جابر قال: اقتتل غلامان: غلام من المهاجرين، وغلام من الأنصار، فنادى المهاجر أو المهاجرون: يا للمهاجرين. ونادى الأنصاري: يا للأنصار. فخرج رسول اللّٰه ﷺ، فقال:","(( ما هذا دعوى أهل الجاهلية )). قالوا: لا، يا رسول اللّٰه إلا أن غلامين اقتتلا، فكسع أحدهما الآخر.","قال: (( فلا بأس، ولينصر الرجل أخاه ظالما أو مظلوما، إن كان ظالما فلينهه؛ فإنه له نصر، وإن كان مظلوما فلينصره ))."],"takhrij":"صحيح: رواه مسلم (٢٥٨٤).","grade":"صحيح","chapter_ar":"باب نصر المسلم ظالما أو مظلوما.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2584).","chapter_en":"Helping a Muslim whether he is the wrongdoer or the one wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Jabir said: Two boys fought, one from the Emigrants and one from the Helpers. The Emigrant, or the Emigrants, called out, “O Emigrants!” and the Helper called out, “O Helpers!” The Messenger of Allah ﷺ came out and said: “What is this call of the people of the age of ignorance?” They said: Nothing, O Messenger of Allah ﷺ, except that two boys fought and one of them struck the other on his backside. He said: “There is no harm, but let a man help his brother whether he is a wrongdoer or one who has been wronged. If he is a wrongdoer, then let him stop him, for that is helping him. And if he is wronged, then let him support him.”"]},"buhuth":{"ar":["وقوله: (( كسع )) أي ضرب دبره. وقوله: (( فلا بأس )) معناه لم يحصل من هذه القصة بأس مما كنت خفتُه."],"en":["His saying, “kas‘a,” means he struck his backside. And his saying, “There is no harm,” means that nothing harmful resulted from this incident of the kind I had feared."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2584}]},{"num":5931,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول الله ﷺ:","«انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا».","قيل:","يا رسول الله، هذا نصره مظلومًا، فكيف نصره ظالمًا؟","قال:","«تُمْسِكُهُ مِنَ الظُّلْمِ، فَذَاكَ نَصْرُكَ إِيَّاهُ»."],"takhrij":"حسن: رواه ابن حبان في صحيحه (٥١٦٦).","grade":"حسن","chapter_ar":"باب نصر المسلم ظالما أو مظلوما.","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (5166).","chapter_en":"Helping a Muslim whether he is the wrongdoer or the one wronged","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ said:","“Help your brother whether he is a wrongdoer or one who has been wronged.”","It was asked:","“O Messenger of Allah ﷺ, we understand helping him when he has been wronged, but how do we help him when he is a wrongdoer?”","He replied:","“You restrain him from injustice; that is how you help him.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":5166},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1401,"n":1398}]},{"num":5932,"demo":false,"sanad":"","matn":["عن البراء قال: أمرنا النبي ﷺ بسبع، ونهانا عن سبع: أمرنا باتباع الجنائز، وعيادة المريض، وإجابة الداعي، ونصر المظلوم، وإبرار القسم، ورد السلام، وتشميت العاطس. ونهانا عن سبع: آنية الفضة، وخاتم الذهب، والحرير، والديباج، والقسي، والإستبرق."],"takhrij":"متفق عليه: رواه البخاري (١٢٣٩)، ومسلم (٢٠٦٦). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب نصر المظلوم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1239) and Muslim (2066). The wording is that of al-Bukhari.","chapter_en":"Supporting the oppressed","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Al-Bara’ said: The Prophet ﷺ commanded us to do seven things and forbade us from seven things. He commanded us to follow funeral processions, visit the sick, respond to invitations, support the oppressed, fulfill oaths, return greetings of peace, and say “May Allah have mercy on you” to the one who sneezes. And he forbade us from seven things: silver vessels, gold rings, silk, brocade, qassiyy cloth, and istabraq."]},"buhuth":{"ar":["والسابع عنده هو (( المياثر ))، وهو جمع ميثرة - بكسر الميم -، وهو وطاء كانت النساء يصنعنه لأزواجهن على السروج، وكان من مراكب العجم، ويكون من الحرير، ويكون من الصوف وغيره، فإذا كان من الحرير فيكون منهيا عنه.","(( والقسي )) - بفتح القاف - هي ثياب مضلعة بالحرير، تعمل بالقس، وهو موضع ببلاد مصر."],"en":["The seventh item in his version is “al-mayathir,” the plural of “mitharah,” with a kasrah on the mim. It is a cushion women used to make for their husbands on saddles, and it was from the riding gear of the non-Arabs. It could be made of silk, or of wool and other materials. If it was made of silk, then it was prohibited.","And “al-qassiyy,” with a fathah on the qaf, are garments striped with silk, made in al-Qass, a place in Egypt."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1239},{"key":"muslim","label":"مسلم","number":2066}]},{"num":5933,"demo":false,"sanad":"","matn":["عن ثابت مولى عمر بن عبد الرحمن قال: إنه لما كان بين عبد الله بن عمرو وبين عنبسة بن أبي سفيان ما كان تيسروا للقتال، فركب خالد بن العاص إلى عبد اللّٰه بن عمرو، فوعظه خالد، فقال عبد اللّٰه بن عمرو: أما علمت أن رسول اللّٰه ﷺ قال: (( من قتل دون ماله فهو شهيد ))."],"takhrij":"صحيح: رواه مسلم (١٤١)، واللفظ له. ورواه البخاري (٢٤٨٠).","grade":"صحيح","chapter_ar":"باب من قاتل دون ماله فهو شهيد","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (141), and this is his wording. Also narrated by al-Bukhari (2480).","chapter_en":"Whoever is killed defending his wealth is a martyr","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Thabit, the freedman of Umar ibn Abd al-Rahman, said: When the dispute occurred between Abdullah ibn Amr and Anbasah ibn Abi Sufyan, they prepared themselves for fighting. Khalid ibn al-As rode to Abdullah ibn Amr and admonished him. Abdullah ibn Amr said: Do you not know that the Messenger of Allah ﷺ said, “Whoever is killed defending his wealth is a martyr”?"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":141},{"key":"اللفظ_لہ_ورواہ_البخاری","label":"اللفظ له. ورواه البخاري","number":2480}]},{"num":5934,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، عن رسول اللّٰه ﷺ قال: (( من حلف على يمين صبر يقتطع بها مال امرئ مسلم هو فيها فاجر، لقي اللّٰه وهو عليه غضبان )). قال: فدخل الأشعث بن قيس، فقال: ما يحدثكم أبو عبد الرحمن؟ قالوا كذا وكذا. قال: صدق أبو عبد الرحمن، فيَّ نزلت، كان بيني وبين رجل أرض باليمن، فخاصمته إلى النبي ﷺ، فقال: (( هل لك بينة؟ )). فقلت: لا. قال: (( فيمينه )).","قلت: إذن يحلف. فقال رسول اللّٰه عند ذلك: (( من حلف على يمين صبر يقتطع بها مال امرئ مسلم وهو فيها فاجر لقي اللّٰه وهو عليه غضبان )). فنزلت: (إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَنِهِمْ ثَمَنًا قَلِيلًا) [آل عمران: ٧٧] إلى آخر الآية."],"takhrij":"متفق عليه: رواه البخاري (٢٣٥٦)، ومسلم (١٣٨). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب وعيد من اقتطع حقه بيمين فاجرة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2356) and Muslim (138). The wording is that of Muslim.","chapter_en":"The warning against one who seizes another’s right with a sinful oath","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abdullah ibn Mas‘ud reported that the Messenger of Allah ﷺ said: “Whoever swears a binding oath in order to seize the wealth of a Muslim while he is sinful in that oath will meet Allah while He is angry with him.” Then al-Ash‘ath ibn Qays entered and said: What is Abu Abd al-Rahman narrating to you? They said: Such-and-such. He said: Abu Abd al-Rahman has spoken the truth. It was concerning me that this verse was revealed. There was a dispute between me and another man over land in Yemen, and I took the matter to the Prophet ﷺ. He said: “Do you have proof?” I said: No. He said: “Then his oath.” I said: Then he will simply swear. At that point the Messenger of Allah ﷺ said: “Whoever swears a binding oath to seize the wealth of a Muslim while he is sinful in it will meet Allah while He is angry with him.” Then the verse was revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” [Aal Imran: 77] to the end of the verse."]},"buhuth":{"ar":["وفي رواية عند البخاري (٢٥١٦): (( شاهداك أو يمينه ))."],"en":["In a narration in al-Bukhari (2516): “Your two witnesses, or else his oath.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2356},{"key":"muslim","label":"مسلم","number":138}]},{"num":5935,"demo":false,"sanad":"","matn":["عن وائل بن حجر، عن أبيه قال: جاء رجل من حضرموت، ورجل من كندة إلى النبي ﷺ، فقال الحضرمي: يا رسول اللّٰه إن هذا قد غلبني على أرض لي كانت لأبي. فقال الكندي: هي أرضي في يدي أزرعها ليس له فيها حق. فقال رسول اللّٰه ﷺ للحضرمي: (( ألك بيّنة؟ )). قال: لا. قال: (( فلك يمينه )). قال: يا رسول اللّٰه، إن الرجل فاجر لا يبالي على ما حلف عليه، وليس يتورع من شيء. فقال: (( ليس لك منه إلا ذلك )). فانطلق ليحلف، فقال رسول اللّٰه ﷺ لما أدبر: (( أما لئن حلف على ماله ليأكله ظلما ليلقين اللّٰه وهو عنه معرض ))."],"takhrij":"صحيح: رواه مسلم (١٣٩).","grade":"صحيح","chapter_ar":"باب وعيد من اقتطع حقه بيمين فاجرة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (139).","chapter_en":"The warning against one who seizes another’s right with a sinful oath","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Wa’il ibn Hujr, from his father, said: A man from Hadramawt and a man from Kindah came to the Prophet ﷺ. The Hadrami said: O Messenger of Allah ﷺ, this man has taken land from me that belonged to my father. The Kindi said: It is my land, it is in my possession, and I cultivate it. He has no right to it. The Messenger of Allah ﷺ said to the Hadrami: “Do you have proof?” He said: No. He said: “Then you have his oath.” He said: O Messenger of Allah ﷺ, the man is wicked. He does not care what he swears to, and he refrains from nothing. He said: “You have nothing from him except that.” As the man went away to swear, the Messenger of Allah ﷺ said when he turned away: “If he swears in order to consume that wealth unjustly, he will surely meet Allah while Allah is turned away from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":139}]},{"num":5936,"demo":false,"sanad":"","matn":["عن أبي أمامة أن رسول اللّٰه ﷺ قال: (( من اقتطع حق امرئ مسلم بيمينه فقد أوجب اللّٰه له النار، وحرم عليه الجنة )). فقال له رجل: وإن كان شيئًا يسيرًا يا رسول اللّٰه؟ قال: (( وإن قضيبًا من أراك ))."],"takhrij":"صحيح: رواه مسلم (١٣٧).","grade":"صحيح","chapter_ar":"باب وعيد من اقتطع حقه بيمين فاجرة","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (137).","chapter_en":"The warning against one who seizes another’s right with a sinful oath","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Umamah reported that the Messenger of Allah ﷺ said: “Whoever seizes the right of a Muslim by means of his oath, Allah has made the Fire obligatory for him and has forbidden Paradise for him.” A man said: Even if it is something small, O Messenger of Allah ﷺ? He said: “Even if it is a twig from an arak tree.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":137}]},{"num":5937,"demo":false,"sanad":"","matn":["عن عبد الله بن يزيد قال: نهى النبي ﷺ عن النهبى والمثلة."],"takhrij":"صحيح: رواه البخاري (٢٤٧٤). (( والنهبة )) هو أخذ المال قهرا.","grade":"صحيح","chapter_ar":"باب النهي عن النُّهبى","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2474).","chapter_en":"The prohibition of plunder","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abdullah ibn Yazid said: The Prophet ﷺ forbade plunder and mutilation."]},"buhuth":{"en":["“Al-nuhba” means taking wealth by force."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2474}]},{"num":5938,"demo":false,"sanad":"","matn":["عن عمران بن حصين، عن النبي ﷺ قال:","«لَا جَلَبَ، وَلَا جَنَبَ، وَلَا شِغَارَ فِي الْإِسْلَامِ، وَمَنِ انْتَهَبَ نُهْبَةً فَلَيْسَ مِنَّا»."],"takhrij":"صحيح: رواه أبو داود (٢٥٨١)، والترمذي (١١٢٣)، والنسائي (٦/١١١).","grade":"صحيح","chapter_ar":"باب النهي عن النُّهبى","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2581), al-Tirmidhī (1123), and al-Nasāʾī (6/111).","chapter_en":"The prohibition of plunder","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported that the Prophet ﷺ said:","“There is no jalab, no janab, and no shighār in Islam. Whoever forcibly seizes property as plunder is not one of us.”"]},"buhuth":{"ar":["قال الترمذي: «حسن صحيح»."],"en":["Al-Tirmidhī said: “Hasan Sahih.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2581},{"key":"tirmidhi","label":"الترمذي","number":1123},{"key":"nasai","label":"النسائي","number":6}]},{"num":5939,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول اللّٰه ﷺ: (( إن أبغض الرجال إلى اللّٰه الألد الخصم ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٥٧)، ومسلم (٢٦٦٨).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الألد الخصم","chapter_ur":"","part_ar":"كتاب المظالم والغصب","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2457) and Muslim (2668).","chapter_en":"What has been reported concerning the stubborn disputant","part_en":"Wrongs, Injustice, and Usurpation","group_ar":"","group_en":"","part_no":18,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Aishah said: The Messenger of Allah ﷺ said: “Indeed, the most hated of men to Allah is the stubborn, fiercely argumentative opponent.”"]},"buhuth":{"ar":["وقوله: (( الألد )) بمعنى شديد الخصومة، مأخوذ من لديدي الوادي، وهما جانباه، لأنه كلما احتج عليه بحجة أخذ في جانب آخر."],"en":["His saying, “al-aladd,” means one who is severe in argument and dispute. It is taken from the two sides of a valley, because whenever a proof is brought against him, he turns to another side."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2457},{"key":"muslim","label":"مسلم","number":2668}]},{"num":5940,"demo":false,"sanad":"","matn":["عن سويد بن غفلة قال: لقيت أبيَّ بن كعب، فقال: أخذتُ صرَّةً فيها مائة دينار، فأتيتُ النبيَّ ﷺ، فقال: (( عرِّفها حولًا )). فعرَّفتُها حولًا، فلم أجد من يعرفها، ثم أتيتُه، فقال: (( عرِّفها حولًا )). فعرَّفتُها، فلم أجد، ثم أتيتُه ثلاثًا، فقال: (( احفظ وعاءها وعددها ووكاءها؛ فإن جاء صاحبها، وإلا فاستمتع بها )). فاستمتعتُ، فلقيتُه بعدُ بمكة، فقال: لا أدري: ثلاثةَ أحوالٍ، أو حولًا واحدًا."],"takhrij":"متفق عليه: رواه البخاري (٢٤٢٦)، ومسلم (١٧٢٣)، واللفظ لمسلم. وفي صحيح مسلم: (( عرِّفها عامًا واحدًا )).","grade":"متفق عليه","chapter_ar":"باب التعريف باللقطة حولا واحدا","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2426) and Muslim (1723). The wording is that of Muslim. In Sahih Muslim it says: “Announce it for one year.”","chapter_en":"Announcing lost property for one full year","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Suwayd ibn Ghafalah said: I met Ubayy ibn Ka‘b, and he said: I found a purse containing one hundred dinars, so I went to the Prophet ﷺ, and he said, “Announce it for one year.” So I announced it for one year, but I did not find anyone who recognized it. Then I came to him again, and he said, “Announce it for one year.” So I announced it, but I did not find anyone. Then I came to him a third time, and he said, “Preserve its container, its amount, and its tying string. If its owner comes, then return it to him. Otherwise, make use of it.” So I made use of it. Later I met him in Makkah, and he said: I do not know whether it was for three years or for one year only."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2426},{"key":"muslim","label":"مسلم","number":1723}]},{"num":5941,"demo":false,"sanad":"","matn":["عن سفيان بن عبد الله بن ربيعة الثقفي أنه وجد عيبةً، فأتى بها عمر بن الخطاب، فقال: عرِّفها سنةً، فإن عُرفت فذاك، وإلا فهي لك، فلم تُعرَّف، فلقيه في العام المقبل في الموسم، فذكرها له، فقال عمر: هي لك، فإن رسول الله ﷺ أمرنا بذلك. قال: لا حاجة لي بها، فقبضها عمر، فجعلها في بيت المال."],"takhrij":"حسن: رواه الدارمي (٢٦٤١)، والطحاوي في شرح المشكل (٤٦٩٥)، والبيهقي (١٨٧/٦).","grade":"حسن","chapter_ar":"باب التعريف باللقطة حولا واحدا","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (2641), al-Tahawi in Sharh Mushkil al-Athar (4695), and al-Bayhaqi (6/187).","chapter_en":"Announcing lost property for one full year","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Sufyan ibn Abd Allah ibn Rabi‘ah al-Thaqafi found a pouch and brought it to Umar ibn al-Khattab. Umar said: Announce it for one year. If it is recognized, then that is that. Otherwise, it is yours. It was not recognized, and he met him in the following year during the pilgrimage season and mentioned it to him. Umar said: It is yours, for the Messenger of Allah ﷺ, commanded us to do that. He said: I have no need of it. So Umar took it and placed it in the public treasury."]},"buhuth":{"ar":["قوله: (( العيبة )) هي: وعاءٌ من أُدُم يكون فيها المتاع."],"en":["His statement, “al-‘aybah,” means a container made of leather in which belongings are kept."]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرح_المشکل","label":"الطحاوي في شرح المشكل","number":4695},{"key":"البیہقی","label":"البيهقي","number":187},{"key":"darimi","label":"سنن الدارمي","number":2519,"n":2519},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12059,"n":12171}]},{"num":5942,"demo":false,"sanad":"","matn":["عن سهل بن سعد أخبره أن عليَّ بن أبي طالب دخل على فاطمة، وحسنٌ وحسينٌ يبكيان، فقال: ما يُبكيهما؟ قالت: الجوع. فخرج عليٌّ، فوجد دينارًا بالسوق، فجاء إلى فاطمة، فأخبرها، فقالت: اذهب إلى فلان اليهودي، فخذ لنا دقيقًا. فجاء اليهودي، فاشترى به دقيقًا، فقال اليهودي: أنت ختن هذا الذي يزعم أنه رسول الله؟ قال: نعم. قال: فخذ دينارك، ولك الدقيق. فخرج عليٌّ حتى جاء به فاطمة، فأخبرها، فقالت: اذهب إلى فلان الجزار، فخذ بدرهمٍ لحمًا. فذهب، فرهن الدينار بدرهم لحم، فجاء به، فعجنت، ونصبت، وخبزت، وأرسلت إلى أبيها، فجاءهم، فقالت: يا رسول الله، أذكر لك، فإن رأيته لنا حلالًا أكلناه وأكلتَ، من شأنه كذا وكذا. فقال: (( كلوا باسم الله )). فأكلوا منه، فبينما هم مكانهم إذا غلام ينشد الله والإسلامَ الدينارَ، فأمر رسول الله ﷺ أن يُدعى له، فسأله، فقال: سقط مني في السوق. فقال النبي ﷺ: (( يا علي، اذهب إلى الجزار، فقل له: إن رسول الله ﷺ يقول لك: أرسل إليَّ بالدينار، ودرهمك عليَّ )). فأرسل به، فدفعه رسول الله ﷺ إليه."],"takhrij":"حسن: رواه أبو داود (١٧١٦).","grade":"حسن","chapter_ar":"باب جواز الأكل قبل التعريف للحاجة","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1716).","chapter_en":"The permissibility of eating from it before announcement in a case of need","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Sahl ibn Sa‘d reported that Ali ibn Abi Talib entered upon Fatimah while Hasan and Husayn were crying. He said: What is making them cry? She said: Hunger. So Ali went out and found a dinar in the marketplace. He came to Fatimah and told her. She said: Go to that Jewish man and get us some flour. So he went to the Jew and bought flour with it. The Jew said: Are you the son-in-law of the one who claims that he is the Messenger of Allah ﷺ? He said: Yes. He said: Take back your dinar, and keep the flour. Then Ali returned and brought it to Fatimah and told her. She said: Go to that butcher and get a dirham’s worth of meat. So he went and pawned the dinar for a dirham’s worth of meat, then brought it. She kneaded, set up the cooking pot, baked, and sent for her father. He came to them, and she said: O Messenger of Allah ﷺ, I will tell you about it, and if you see it as lawful for us, we will eat it and you will eat also. She told him what had happened. He said: “Eat in the name of Allah.” So they ate from it. While they were there, a young man came calling out by Allah and by Islam for the lost dinar. The Messenger of Allah ﷺ ordered that he be brought, and he asked him. The boy said: It fell from me in the marketplace. The Prophet ﷺ said: “O Ali, go to the butcher and say to him: The Messenger of Allah ﷺ says to you: Send me the dinar, and your dirham is due from me.” So he sent it, and the Messenger of Allah ﷺ handed it to him."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1716}]},{"num":5943,"demo":false,"sanad":"","matn":["عن زيد بن خالد الجهني أنه قال: جاء رجل إلى رسول الله ﷺ، فسأله عن اللقطة، فقال: (( اعرف عفاصها ووكاءها، ثم عرِّفها سنةً، فإن جاء صاحبها، وإلا فشأنك بها )). قال: فضالة الغنم يا رسول الله؟ قال: (( هي لك، أو لأخيك، أو للذئب )). قال: فضالة الإبل؟ قال: (( ما لك ولها؟ معها سقاؤها وحذاؤها، ترد الماء، وتأكل الشجر حتى يلقاها ربها ))."],"takhrij":"متفق عليه: رواه مالك (٤٨)، والبخاري (٢٣٧٢)، ومسلم (١٧٢٢).","grade":"متفق عليه","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (48), al-Bukhari (2372), and Muslim (1722).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: A man came to the Messenger of Allah ﷺ, and asked him about lost property. He said: “Recognize its container and its tying string, then announce it for a year. If its owner comes, then return it. Otherwise, it is yours to deal with.” He said: What about stray sheep, O Messenger of Allah ﷺ? He said: “It is for you, or for your brother, or for the wolf.” He said: What about stray camels? He said: “What have you to do with them? They have their water supply and their feet. They can reach water and eat from the trees until their owner finds them.”"]},"buhuth":{"ar":["(( والعِفاص )) الوعاء الذي تكون فيه النفقة من جلد أو خرقة أو غير ذلك، ولهذا يسمى الجلد الذي نلبسه رأس القارورة العِفاص. (( والوكاء )) الخيط الذي يشد به العِفاص.","وقوله: (( معها سقاؤها وحذاؤها )) أراد بالسقاء أنها إذا وردت الماء شربت منه ما يكون فيه ريُّها وظمؤها، وهي أطول البهائم ظمأً لكثرة ما تحمل من الماء. وأراد بالحذاء أخفافها، وأنها تقوى بها على السير، وقطع البلاد الشاسعة، وورود المياه النائية. انظر شرح السنة (٨/٢١٠)."],"en":["“Al-‘ifas” is the container in which money is kept, whether made of leather, cloth, or something else. For this reason, the leather covering placed over the mouth of a bottle is also called ‘ifas. “Al-wika’” is the string by which the container is tied.","His statement, “It has its water supply and its feet,” means by “water supply” that when it reaches water, it drinks enough to satisfy its thirst, and it is among the animals that can go the longest without water because of how much it can carry. By “feet,” he meant its hooves, by which it is able to travel, cross vast lands, and reach distant watering places. See Sharh al-Sunnah (8/210)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":48},{"key":"bukhari","label":"البخاري","number":2372},{"key":"muslim","label":"مسلم","number":1722}]},{"num":5944,"demo":false,"sanad":"","matn":["عن زيد بن خالد الجهني صاحب رسول اللّٰه ﷺ يقول: سئل رسول الله ﷺ عن اللقطة الذهب أو الورق، فقال: (( اعرف وكاءها وعفاصها، ثم عرِّفها سنةً، فإن لم تُعرف فاستنفقها، ولتكن وديعة عندك، فإن جاء طالبها يومًا من الدهر فأدها إليه )). وسأله عن ضالة الإبل، فقال: (( ما لك ولها؟ دعها؛ فإن معها حذاءها وسقاءها، ترد الماء، وتأكل الشجر حتى يجدها ربها )). وسأله عن الشاة، فقال: (( خذها؛ فإنما هي لك، أو لأخيك، أو للذئب ))."],"takhrij":"صحيح: رواه مسلم (٥ : ١٧٢٢).","grade":"صحيح","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1722:5).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani, a Companion of the Messenger of Allah ﷺ said: The Messenger of Allah ﷺ was asked about lost gold or silver. He said: “Recognize its tying string and its container, then announce it for a year. If it is not recognized, then spend it, but let it remain as a trust with you. If its claimant comes one day, then return it to him.” He was asked about stray camels, and he said: “What have you to do with them? Leave them, for they have their feet and their water supply. They can reach water and eat from the trees until their owner finds them.” He was asked about sheep, and he said: “Take it, for it is only for you, or for your brother, or for the wolf.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":5}]},{"num":5945,"demo":false,"sanad":"","matn":["عن زيد بن خالد الجهني أن رجلًا سأل رسول الله ﷺ عن اللقطة، فقال: (( عرِّفها سنةً، ثم اعرف وكاءها وعفاصها، ثم استنفق بها، فإن جاء ربها فأدِّها إليه )). فقال: يا رسول الله، فضالة الغنم؟ فقال: (( خذها؛ فإنما هي لك، أو لأخيك، أو للذئب )). قال: يا رسول الله، فضالة الإبل؟ فغضب رسول الله ﷺ حتى احمرَّت وجنتاه - أو احمر وجهه - وقال: (( ما لك ولها؟ معها حذاؤها وسقاؤها حتى يأتيها ربها ))."],"takhrij":"صحيح: رواه أبو داود (١٧٠٤)، والترمذي (١٣٧٣).","grade":"صحيح","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1704) and al-Tirmidhi (1373).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani reported that a man asked the Messenger of Allah ﷺ, about lost property. He said: “Announce it for one year, then remember its tying string and its container, then spend it. If its owner comes, then give it to him.” He said: O Messenger of Allah ﷺ, what about stray sheep? He said: “Take it, for it is only for you, or for your brother, or for the wolf.” He said: O Messenger of Allah ﷺ, what about stray camels? The Messenger of Allah ﷺ became angry until his cheeks became red—or his face became red—and he said: “What have you to do with them? They have their feet and their water supply until their owner comes to them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1704},{"key":"tirmidhi","label":"الترمذي","number":1373}]},{"num":5946,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص، عن رسول الله ﷺ أنه سئل عن الثمر المعلَّق، فقال: (( من أصاب بفيه من ذي حاجة غير متخذ خُبنةً فلا شيء عليه، ومن خرج بشيء منه فعليه غرامة مثليه والعقوبة، ومن سرق منه شيئًا بعد أن يؤويه الجرين، فبلغ ثمن المجن فعليه القطع )). وذكر في ضالة الإبل والغنم كما ذكره غيره. قال: وسئل عن اللقطة، فقال: (( ما كان منها في طريق الميتاء أو القرية الجامعة فعرِّفها سنةً، فإن جاء طالبها فادفعها إليه، وإن لم يأت فهي لك، وما كان في الخراب يعني ففيها وفي الركاز الخمس ))."],"takhrij":"حسن: رواه أبو داود (١٧١٠)، والترمذي (١٢٨٨)، والنسائي (٤٩٥٨)، وابن ماجه (٢٥٩٦)، واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1710), al-Tirmidhi (1288), al-Nasa’i (4958), and Ibn Majah (2596). The wording is that of Abu Dawud.","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As reported that the Messenger of Allah ﷺ was asked about fruit hanging on the trees. He said: “Whoever takes some with his mouth out of need, without taking any away in his garment, there is nothing due on him. But whoever takes some away, then upon him is double compensation and punishment. And whoever steals from it after it has been gathered in the storage place, and its value reaches the price of a shield, then the prescribed punishment of cutting applies.” He also mentioned the ruling of stray camels and sheep as others have mentioned. He said: And he was asked about lost property, and he said: “Whatever of it is found on a traveled road or in a settled village, announce it for a year. If its claimant comes, then hand it to him. If he does not come, then it is yours. But what is found in ruins, then regarding it and buried treasure one-fifth is due.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1710},{"key":"tirmidhi","label":"الترمذي","number":1288},{"key":"nasai","label":"النسائي","number":4958},{"key":"ibnmajah","label":"ابن ماجه","number":2596}]},{"num":5947,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: سمعت رجلًا من مزينة يسأل رسول الله ﷺ، قال: يا رسول الله، جئت أسألك عن الضالة من الإبل. قال: (( معها حذاؤها وسقاؤها، تأكل الشجر، وترد الماء، فدعها حتى يأتيها باغيها )). قال: الضالة من الغنم؟ قال: (( لك، أو لأخيك، أو للذئب، تجمعها حتى يأتيها باغيها )). قال: الحريسة التي توجد في مراتعها؟ قال: (( فيها ثمنها مرتين وضرب نكال، وما أُخذ من عطنه ففيه القطع إذا بلغ ما يؤخذ من ذلك ثمن المجن )). قال: يا رسول الله، فالثمار، وما أُخذ منها في أكمامها؟ قال: (( من أخذ بفمه ولم يتخذ خُبنة فليس عليه شيء، ومن احتمل فعليه ثمنه مرتين وضربًا ونكالًا، وما أُخذ من أجرانه ففيه القطع إذا بلغ ما يؤخذ من ذلك ثمن المجن )). قال: يا رسول الله، واللقطة نجدها في سبيل العامرة؟ قال: (( عرِّفها حولًا، فإن وجد باغيها فأدِّها إليه، وإلا فهي لك )). قال: ما يوجد في الخرب العادي؟ قال: (( فيه وفي الركاز الخمس ))."],"takhrij":"حسن: رواه الإمام أحمد (٦٦٨٣).","grade":"حسن","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (6683).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Amr ibn Shu‘ayb, from his father, from his grandfather, said: I heard a man from Muzaynah asking the Messenger of Allah ﷺ. He said: O Messenger of Allah ﷺ, I have come to ask you about stray camels. He said: “They have their feet and their water supply. They eat from the trees and go to water, so leave them until the one seeking them comes.” He said: What about stray sheep? He said: “It is for you, or for your brother, or for the wolf. Gather it until the one seeking it comes.” He said: What about livestock taken from their grazing places? He said: “For that there is double its value and a disciplinary punishment. And what is taken from its enclosure is subject to cutting off the hand if what is taken reaches the value of a shield.” He said: O Messenger of Allah ﷺ, what about fruits, and what is taken from them while still attached? He said: “Whoever takes with his mouth and does not carry anything away in his garment, there is nothing due on him. Whoever carries some away, then upon him is double its value and a disciplinary punishment. And what is taken from the drying area is subject to cutting off the hand if what is taken reaches the value of a shield.” He said: O Messenger of Allah ﷺ, what about lost property that we find on inhabited roads? He said: “Announce it for one year. If the one seeking it comes, then return it to him. Otherwise, it is yours.” He said: What about what is found in ancient ruins? He said: “Regarding it and buried treasure, one-fifth is due.”"]},"buhuth":{"ar":["وقوله: (( الحريسة التي توجد في مراتعها ))، وفي شرح السنة: (( حريسة الجبل )).","قال البغوي: “أراد بحريسة الجبل: البقر أو الشاة أو الإبل المأخوذة من المرعى، يقال: احترس الرجل إذا أخذ الشاة من المرعى. وإيجاب الثمن مرتين يشبه أن يكون على سبيل الوعيد والزجر، وإلا فالشيء المتلف لا يضمن أكثر من ثمن مثله، وكان عمر بن الخطاب يحكم به، وإليه ذهب أحمد بن حنبل، وقد قيل: كان في صدر الإسلام يقع بعض العقوبات في الأموال، ثم نسخ، والله أعلم”. انتهى."],"en":["His statement, “livestock taken from its pasture,” is referred to in Sharh al-Sunnah as “the guarded animal of the mountain.”","Al-Baghawi said: “What is meant by the guarded animal of the mountain is cattle, sheep, or camels taken from the grazing place. It is said: a man ‘ihtarasa’ when he took a sheep from the pasture. The imposition of double the value appears to be by way of threat and deterrence; otherwise, a damaged item is not usually compensated by more than its equivalent value. Umar ibn al-Khattab judged by this, and Ahmad ibn Hanbal held this view. It has also been said that in the early period of Islam, some financial punishments were imposed and were later abrogated. And Allah knows best.” End quote."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":6683},{"key":"ahmad","label":"مسند الإمام أحمد","number":6683,"n":6683}]},{"num":5948,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ، وسئل عن ضالة الغنم، فقال: (( هي لك، أو لأخيك، أو للذئب )). وسئل عن ضالة الإبل، فقال: (( ما لك ولها؟ معها سقاؤها، أو سقاؤه وحذاؤه، دعه حتى يجد ربه ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٣٦٤).","grade":"حسن","chapter_ar":"باب ضالة الإبل والغنم","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1364).","chapter_en":"Stray camels and sheep","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ was asked about stray sheep, and he said: “It is for you, or for your brother, or for the wolf.” And he was asked about stray camels, and he said: “What have you to do with them? They have their water supply—or its water supply—and their feet. Leave it until its owner finds it.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1364},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1364,"n":1365}]},{"num":5949,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( ضالة الإبل المكتومة غرامتها، ومثلها معها ))."],"takhrij":"حسن: رواه أبو داود (١٧١٨)، وعبد الرزاق في مصنفه (١٨٥٩٩).","grade":"حسن","chapter_ar":"باب الترهيب من كتم اللقطة وتغييبها","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (1718) and Abd al-Razzaq in his Musannaf (18599).","chapter_en":"The warning against concealing found property and hiding it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “A concealed stray camel requires compensation for it and another like it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1718},{"key":"عبد_الرزاق/مصنفہ","label":"عبد الرزاق في مصنفه","number":18599}]},{"num":5950,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لما فتح الله على رسوله مكة، فقام في الناس، فحمد الله، وأثنى عليه، ثم قال: (( ولا تحل ساقطتها إلا لمنشد ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٣٤)، ومسلم (١٣٥٥).","grade":"متفق عليه","chapter_ar":"باب لا تحل لقطة مكة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2434) and Muslim (1355).","chapter_en":"Lost property of Makkah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: When Allah granted His Messenger the conquest of Makkah, he stood among the people, praised Allah, and glorified Him, then said: “Its lost property is not lawful except for one who announces it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2434},{"key":"muslim","label":"مسلم","number":1355}]},{"num":5951,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسول الله ﷺ يوم فتح مكة: (( إن هذا البلد حرمه الله، لا يعضد شوكه، ولا ينفَّر صيده، ولا تُلتقط لقطته إلا من عرَّفها ))."],"takhrij":"متفق عليه: رواه البخاري (١٥٨٧)، ومسلم (١٣٥٣). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب لا تحل لقطة مكة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1587) and Muslim (1353). The wording is that of al-Bukhari.","chapter_en":"Lost property of Makkah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said on the day of the conquest of Makkah: “Indeed, Allah has made this town sacred. Its thorns are not to be cut, its game is not to be driven away, and its lost property is not to be picked up except by one who will announce it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1587},{"key":"muslim","label":"مسلم","number":1353}]},{"num":5952,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن عثمان التيمي أن رسول الله ﷺ نهى عن لقطة الحاج."],"takhrij":"صحيح: رواه مسلم (١٧٢٤).","grade":"صحيح","chapter_ar":"باب لا تحل لقطة مكة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1724).","chapter_en":"Lost property of Makkah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abd al-Rahman ibn Uthman al-Taymi reported that the Messenger of Allah ﷺ forbade taking the lost property of pilgrims."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1724}]},{"num":5953,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، عن النبي ﷺ قال: (( لا يُختلى خلاها، ولا يُنفَّر صيدها، ولا تُلتقط لقطتها إلا لمن أشاد بها ))."],"takhrij":"حسن: رواه أبو داود (٢٠٣٥).","grade":"حسن","chapter_ar":"باب لا تحل لقطة المدينة إلا لمنشد","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2035).","chapter_en":"Lost property of Madinah is not lawful except for one who publicly announces it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Ali ibn Abi Talib reported from the Prophet ﷺ that he said: “Its fresh herbage is not to be cut, its game is not to be driven away, and its lost property is not to be picked up except by one who publicizes it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2035}]},{"num":5954,"demo":false,"sanad":"","matn":["عن أنس قال: مرَّ النبي ﷺ بتمرة في الطريق، فقال: (( لولا أني أخاف أن تكون من صدقة لأكلتها ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٣١)، ومسلم (١٠٧١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في قليل اللقطة","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2431) and Muslim (1071).","chapter_en":"What has been reported regarding insignificant found items","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Anas said: The Prophet ﷺ passed by a date lying on the road and said: “Were it not that I fear it might be from charity, I would have eaten it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2431},{"key":"muslim","label":"مسلم","number":1071}]},{"num":5955,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( إني لأنقلب إلى أهلي، فأجد التمرة ساقطة على فراشي، فأرفعها لآكلها، ثم أخشى أن تكون من صدقة، فألقيها ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٣٢)، ومسلم (١٦٣ : ١٠٧٠).","grade":"متفق عليه","chapter_ar":"باب ما جاء في قليل اللقطة","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2432) and Muslim (1070:163).","chapter_en":"What has been reported regarding insignificant found items","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “I return to my family and find a date fallen on my bed. I pick it up to eat it, then I fear it may be from charity, so I throw it away.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2432},{"key":"muslim","label":"مسلم","number":163}]},{"num":5956,"demo":false,"sanad":"","matn":["عن زيد بن خالد الجهني، عن رسول الله ﷺ أنه قال: (( من أوى ضالة فهو ضال ما لم يعرفها ))."],"takhrij":"صحيح: رواه مسلم (١٧٢٥).","grade":"صحيح","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1725).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani reported that the Messenger of Allah ﷺ said: “Whoever takes possession of lost property is astray so long as he does not announce it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1725}]},{"num":5957,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: قال رسول اللّٰه ﷺ: (( لا يَحْلِبَنَّ أحدٌ ماشيةَ امرئٍ بغير إذنه، أيحبُّ أحدكم أن تُؤتى مشربتُه، فتُكسر خزانته، فيُنتقل طعامُه؟ فإنما تُخزن لهم ضروعُ مواشيهم أطعمتَهم، فلا يحلبنَّ أحدٌ ماشية أحدٍ إلا بإذنه ))."],"takhrij":"متفق عليه: رواه مالك (١٧)، والبخاري (٢٤٣٥)، ومسلم (١٧٢٦).","grade":"متفق عليه","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (2435), and Muslim (1726).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn Umar said: The Messenger of Allah ﷺ said: “Let none of you milk another man’s livestock without his permission. Would one of you like that someone come to his pantry, break open his storage place, and take away his food? Indeed, the udders of their animals store their food for them, so no one should milk another’s livestock except with his permission.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"bukhari","label":"البخاري","number":2435},{"key":"muslim","label":"مسلم","number":1726}]},{"num":5958,"demo":false,"sanad":"","matn":["عن عبد الله بن الشِّخير قال: قال رسول الله ﷺ: (( ضالة المسلم حرق النار ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٥٠٢)، وأحمد (١٦٣١٤)، وابن حبان (٤٨٨٨)، والبيهقي (١٩١/٦).","grade":"صحيح","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2502), Ahmad (16314), Ibn Hibban (4888), and al-Bayhaqi (6/191).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn al-Shikhkhir said: The Messenger of Allah ﷺ said: “Taking a Muslim’s stray animal for oneself leads to the Fire.”"]},"buhuth":{"ar":["وقوله: (( حرق النار )) أي سبب دخوله في النار إذا تملكها، ولم يعرف بها."],"en":["His statement, “the burning of the Fire,” means that it becomes a cause for entering the Fire if he takes ownership of it and does not announce it."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2502},{"key":"ibnhibban","label":"ابن حبان","number":4888},{"key":"البیہقی","label":"البيهقي","number":191},{"key":"ahmad","label":"مسند الإمام أحمد","number":16314,"n":16314}]},{"num":5959,"demo":false,"sanad":"","matn":["عن الجارود العبدي قال: بينما نحن مع رسول الله ﷺ في بعض أسفاره، وفي الظهر قلة، إذ تذاكر القوم الظهر، فقلت: يا رسول الله، قد علمتَ ما يكفينا من الظهر. فقال: (( وما يكفينا؟ )). قلت: ذود نأتي عليهن في جرف، فنستمتع بظهورهم. قال: (( لا، ضالة المسلم حرق النار، فلا تقربنها. ضالة المسلم حرق النار، فلا تقربنها. ضالة المسلم حرق النار، فلا تقربنها )).","وقال في اللقطة: (( الضالة تجدها فانشدنها، ولا تكتم، ولا تُغيب، فإن عُرفت فأدها، وإلا فمال الله يؤتيه من يشاء ))."],"takhrij":"حسن: رواه أحمد (٢٠٧٥٤)، والطبراني في الكبير (٢٩٨/٢)، والدارمي (٢٦٤٤، ٢٦٤٣)، وابن حبان (٤٨٨٧).","grade":"حسن","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (20754), al-Tabarani in al-Kabir (2/298), al-Darimi (2644, 2643), and Ibn Hibban (4887).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Jarud al-Abdi said: While we were with the Messenger of Allah ﷺ, on one of his journeys, our riding animals had become few. The people discussed the matter of mounts, so I said: O Messenger of Allah ﷺ, you know what would suffice us in mounts. He said: “And what would suffice us?” I said: A small group of animals that we pass by at al-Jurf, and we benefit from riding them. He said: “No. Taking a Muslim’s stray animal for oneself leads to the Fire, so do not go near it. Taking a Muslim’s stray animal for oneself leads to the Fire, so do not go near it. Taking a Muslim’s stray animal for oneself leads to the Fire, so do not go near it.” And regarding found property he said: “If you find lost property, then announce it. Do not conceal it and do not hide it. If it is recognized, then return it. Otherwise, it is the wealth of Allah which He gives to whom He wills.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":298},{"key":"darimi","label":"الدارمي","number":2644},{"key":"ibnhibban","label":"ابن حبان","number":4887},{"key":"ahmad","label":"مسند الإمام أحمد","number":20754,"n":20754}]},{"num":5960,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ سئل عن اللقطة، فقال: (( تُعرَّف، ولا تُغيب، ولا تُكتم، فإن جاء صاحبها، وإلا فهو مال الله يؤتيه من يشاء ))."],"takhrij":"صحيح: رواه البزار - كشف الأستار (١٣٦٧).","grade":"صحيح","chapter_ar":"باب الترهيب من أخذ ضالة المسلم بدون التعريف","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar in Kashf al-Astar (1367).","chapter_en":"The warning against taking a Muslim’s lost property without announcing it","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ was asked about found property, and he said: “It is to be announced. It is not to be hidden, nor concealed. If its owner comes, then return it. Otherwise, it is the wealth of Allah that He gives to whom He wills.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1367},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1367,"n":1368}]},{"num":5961,"demo":false,"sanad":"","matn":["عن عياض بن حمار قال: قال رسول الله ﷺ: (( من وجد لقطة فليشهد ذا عدل أو ذوي عدل، ولا يكتم، ولا يغيب، فإن وجد صاحبها فليردها عليه، وإلا فهو مال الله يؤتيه من يشاء ))."],"takhrij":"صحيح: رواه أبو داود (١٧٠٩)، وابن ماجه (٢٥٠٥)، وأحمد (١٧٤٨١)، وابن حبان (٤٨٩٤).","grade":"صحيح","chapter_ar":"باب جواز أخذ ضالة المسلم للتعريف بها ثم تملكها","chapter_ur":"","part_ar":"كتاب اللقطة واللقيط","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (1709), Ibn Majah (2505), Ahmad (17481), and Ibn Hibban (4894).","chapter_en":"The permissibility of taking a Muslim’s lost property in order to announce it, then owning it afterward","part_en":"The Book of Lost Property and Foundlings","group_ar":"","group_en":"","part_no":19,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Iyad ibn Himar said: The Messenger of Allah ﷺ said: “Whoever finds lost property should have one just person, or two just people, bear witness to it. He should neither conceal it nor hide it. If he finds its owner, he must return it to him. Otherwise, it is the wealth of Allah which He gives to whom He wills.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1709},{"key":"ibnmajah","label":"ابن ماجه","number":2505},{"key":"ibnhibban","label":"ابن حبان","number":4894},{"key":"ahmad","label":"مسند الإمام أحمد","number":17481,"n":17481}]},{"num":5962,"demo":false,"sanad":"","matn":["عن عائشة قالت لعروة: يا ابن أختي، إن كنا لننظر إلى الهلال، ثم الهلال، ثلاثة أهلة في شهرين، وما أُوقِدت في أبيات رسول اللّٰه ﷺ نار. فقلت: يا خالة، ما كان يُعيشكم؟ قالت: الأسودان: التمر والماء، إلا أنه قد كان لرسول اللّٰه ﷺ جيران من الأنصار كانت لهم منائح، وكانوا يمنحون رسول اللّٰه ﷺ من ألبانهم فيسقينا."],"takhrij":"متفق عليه: رواه البخاري (٢٥٦٧)، ومسلم (٢٩٧٢).","grade":"متفق عليه","chapter_ar":"باب الترغيب في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2567) and Muslim (2972).","chapter_en":"Encouragement to Give Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿĀʾishah said to ʿUrwah: “O son of my sister, we would indeed look at the new moon, then the next new moon, then the next—three new moons in two months—while no fire was kindled in the houses of the Messenger of Allāh ﷺ.” I said, “O aunt, what sustained you?” She replied, “The two black things: dates and water. Except that the Messenger of Allāh ﷺ had neighbors from among the Anṣār who owned milch animals that they lent for their milk, and they would give the Messenger of Allāh ﷺ some of their milk, and he would give it to us to drink.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2567},{"key":"muslim","label":"مسلم","number":2972}]},{"num":5963,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال النبي ﷺ: «يا نساء المسلمات، لا تحقرنّ جارةٌ لجارتها، ولو فِرْسِنَ شاةٍ»."],"takhrij":"متفق عليه: رواه البخاري (٦٠١٧)، ومسلم (١٠٣٠).","grade":"متفق عليه","chapter_ar":"باب الترغيب في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6017) and Muslim (1030).","chapter_en":"Encouragement to Give Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “O Muslim women, no woman should consider insignificant a gift to her neighbor, even if it is only the hoof of a sheep.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6017},{"key":"muslim","label":"مسلم","number":1030}]},{"num":5964,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: «تهادوا تحابوا»."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (٥٩٤)، والدولابي في الكنى (١٥٠/١)، والبيهقي (١٦٩/٦).","grade":"حسن","chapter_ar":"باب الترغيب في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (594), al-Dūlābī in al-Kunā (1/150), and al-Bayhaqī (6/169).","chapter_en":"Encouragement to Give Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “Exchange gifts, and you will love one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":594},{"key":"الدولابی/الکنی","label":"الدولابي في الكنى","number":150},{"key":"البیہقی","label":"البيهقي","number":169},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":11946,"n":12057}]},{"num":5965,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: «لو دُعيت إلى ذراع أو كراع لأجبت، ولو أُهدي إلي ذراع أو كراع لقبلت»."],"takhrij":"صحيح: رواه البخاري (٢٥٦٨). وقوله: «كراع» هو من الإنسان ما دون الركبة إلى الكعب، ومن البقر والغنم مستدق الساق العاري من اللحم، وهو المعروف اليوم بالمقادم.","grade":"صحيح","chapter_ar":"باب قبول القليل من الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2568).","chapter_en":"Accepting Even a Small Gift","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “If I were invited to a meal consisting of a foreleg or a lower leg, I would accept the invitation; and if a foreleg or a lower leg were given to me as a gift, I would accept it.”"]},"buhuth":{"en":["His saying, “kurāʿ”, refers in a human being to the portion below the knee down to the ankle, and in cattle and sheep to the thin lower part of the leg that has little flesh upon it. It is what is commonly known today as the feet or lower part of the leg."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2568}]},{"num":5966,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: أنفجنا أرنبًا بمرّ الظهران، فسعى القوم، فلغبوا، فأدركتها، فأخذتها، فأتيت بها أبا طلحة، فذبحها، وبعث بها إلى رسول اللّٰه ﷺ بوركها أو فخذيها. - قال: فخذيها، لا شك فيه - فقبله. قلت: وأكل منه؟ قال: وأكل منه، ثم قال بعدُ: قَبِله. (أي لم يأكل منه)."],"takhrij":"صحيح: رواه البخاري (٢٥٧٢)، ومسلم (١٩٥٣). واللفظ للبخاري. وقوله: «لغبوا» معناه: تعبوا.","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2572) and Muslim (1953). The wording is that of al-Bukhārī.","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik said: “We startled a rabbit at Marr al-Ẓahrān, and the people ran after it until they became exhausted. I caught up with it and seized it, then brought it to Abū Ṭalḥah. He slaughtered it and sent its hips—or its two thighs—to the Messenger of Allāh ﷺ.” He later said: “Its two thighs, without doubt.” The Prophet ﷺ accepted it.","I asked, “Did he eat from it?” He replied, “He ate from it,” but afterward he said, “He accepted it,” meaning that he did not eat from it."]},"buhuth":{"en":["His statement, “لغبوا” means: they became tired."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2572},{"key":"muslim","label":"مسلم","number":1953}]},{"num":5967,"demo":false,"sanad":"","matn":["عن الصعب بن جثامة: أنه أهدى لرسول اللّٰه ﷺ حمارًا وحشيًا، وهو بالأبواء أو بودّان، فرد عليه، فلما رأى ما في وجهه قال: «أما إنا لم نرده عليك إلا أنا حُرُم»."],"takhrij":"متفق عليه: رواه مالك، والبخاري (٢٥٧٣)، ومسلم (١١٩٢).","grade":"متفق عليه","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik, al-Bukhārī (2573), and Muslim (1192).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Ṣaʿb ibn Jaththāmah reported that he presented the Messenger of Allāh ﷺ with a wild donkey while he was at al-Abwāʾ or Waddān. The Prophet ﷺ returned it to him. When he saw the expression on his face, he said: “We only returned it to you because we are in the state of iḥrām.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2573},{"key":"muslim","label":"مسلم","number":1192}]},{"num":5968,"demo":false,"sanad":"","matn":["عن المغيرة بن شعبة: أهدى دحية الكلبي لرسول اللّٰه ﷺ خفين فلبسهما."],"takhrij":"صحيح: رواه الترمذي (١٧٦٩) وفي الشمائل (٧٠) وأبو الشيخ في أخلاق النبي ﷺ (ص: ١١٦).","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (1769), in al-Shamāʾil (70), and Abū al-Shaykh in Akhlāq al-Nabī ﷺ (p. 116).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported: Diḥyah al-Kalbī presented the Messenger of Allāh ﷺ with a pair of leather socks, and he wore them."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1769},{"key":"وفی_الشمایل","label":"وفي الشمائل","number":70},{"key":"ابو_الشیخ/اخلاق_النبی_ﷺ","label":"أبو الشيخ في أخلاق النبي ﷺ","number":116}]},{"num":5969,"demo":false,"sanad":"","matn":["عن المغيرة بن شعبة، أن رسول اللّٰه ﷺ توضأ ومسح على خفيه، قال: فقال رجل عند المغيرة بن شعبة: يا مغيرة، ومن أين كان للنبي ﷺ خفان؟ قال: فقال المغيرة: أهداهما إليه النجاشي."],"takhrij":"صحيح: رواه البيهقي (٢٨٣/١).","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bayhaqī (1/283).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported that the Messenger of Allāh ﷺ performed ablution and wiped over his leather socks. A man who was with al-Mughīrah ibn Shuʿbah said, “O Mughīrah, from where did the Prophet ﷺ obtain the two leather socks?” Al-Mughīrah replied, “The Negus presented them to him as a gift.”"]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":283},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":1346,"n":1359}]},{"num":5970,"demo":false,"sanad":"","matn":["عن بريدة بن الحصيب: أن النجاشي أهدى للنبي ﷺ خفين أسودين ساذجين، فلبسهما، ثم توضأ ومسح عليهما."],"takhrij":"حسن: رواه أبو داود (١٥٥) والترمذي (٢٨٢٠) وفي الشمائل (٦٩) وابن ماجه (٣٦٢٠)، (٥٤٩) وأحمد (٢٢٩٨١).","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (155), al-Tirmidhī (2820), in al-Shamāʾil (69), Ibn Mājah (3620), (549), and Aḥmad (22981).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb reported that the Negus presented the Prophet ﷺ with a pair of plain black leather socks. He put them on, then performed ablution and wiped over them."]},"buhuth":{"ar":["وقوله: «أسودين ساذجين»، السَّاذَج: بفتح الذال وكسرها، هو الخالص غير المشوب وغير المنقوش."],"en":["Regarding the expression “plain black” (ساذجين): sādhaj, with either a fatḥah or kasrah on the dhāl, means something pure and unmixed, without decoration or patterns."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":155},{"key":"tirmidhi","label":"الترمذي","number":2820},{"key":"وفی_الشمایل","label":"وفي الشمائل","number":69},{"key":"ibnmajah","label":"ابن ماجه","number":3620},{"key":"ahmad","label":"مسند الإمام أحمد","number":22981,"n":22981}]},{"num":5971,"demo":false,"sanad":"","matn":["عن أسامة بن زيد، قال: كساني رسول اللّٰه ﷺ قَبْطِيَّة كثيفة مما أهداها له دحية الكلبي، فكسوتها امرأتي، فقال: «ما لك لم تلبس القبطية؟» قلت: كسوتها امرأتي، فقال: «مرها لتجعل تحتها غلالة، فإني أخاف أن تصف عظامها»."],"takhrij":"حسن: رواه أحمد (٢١٧٨٨)، (٢١٧٨٦) والبيهقي (٢٣٤/٢) والضياء في المختارة (١٣٦٦-١٣٦٥).","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (21788, 21786), al-Bayhaqī (2/234), and al-Ḍiyāʾ in al-Mukhtārah (1365–1366).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Usāmah ibn Zayd said: “The Messenger of Allāh ﷺ clothed me in a thick Qibṭiyyah garment from among those that Diḥyah al-Kalbī had presented to him. I gave it to my wife to wear. He said, ‘Why have you not worn the Qibṭiyyah?’ I replied, ‘I gave it to my wife to wear.’ He said: ‘Tell her to wear an undergarment beneath it, for I fear that it may reveal the shape of her bones.’”"]},"buhuth":{"ar":["قوله: «القبطية» هي ثياب من كتان رقيق كانت تعمل بمصر، نسبة إلى القبط على غير القياس، فرقًا بينها وبين الإنسان.","وقوله: «غلالة» ثوب رقيق يلبس تحت الدثار."],"en":["His saying, “al-Qibṭiyyah” refers to garments of fine linen that were manufactured in Egypt. They are attributed to the Copts in this irregular linguistic form in order to distinguish the garment from a person of Coptic origin.","His saying, “ghilālah” refers to a thin garment worn underneath an outer garment."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":234},{"key":"الضیا/المختارہ","label":"الضياء في المختارة","number":1366},{"key":"ahmad","label":"مسند الإمام أحمد","number":21788,"n":21788},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":3262,"n":3275}]},{"num":5972,"demo":false,"sanad":"","matn":["عن العباس بن عبد المطلب قال: شهدت مع رسول اللّٰه ﷺ يوم حنين، فلزمت أنا وأبو سفيان بن الحارث بن عبد المطلب رسول اللّٰه ﷺ فلم نفارقه، ورسول اللّٰه ﷺ على بغلة له بيضاء أهداها له فروة بن نفاثة الجذامي… فذكر الحديث."],"takhrij":"صحيح: رواه مسلم (٧٦/١٧٧٥).","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1775/76).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-ʿAbbās ibn ʿAbd al-Muṭṭalib said: “I was present with the Messenger of Allāh ﷺ on the Day of Ḥunayn. Abū Sufyān ibn al-Ḥārith ibn ʿAbd al-Muṭṭalib and I remained close beside the Messenger of Allāh ﷺ and did not leave him. The Messenger of Allāh ﷺ was riding a white mule that Farwah ibn Nufāthah al-Judhāmī had presented to him as a gift…” Then he mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":76}]},{"num":5973,"demo":false,"sanad":"","matn":["عن ابن عمر قال: كساني رسول اللّٰه ﷺ حلة من حلل السيراء، أهداها له فيروز، فلبست الإزار، فأغرقني طولًا وعرضًا، فسحبته، ولبست الرداء، فتقنعت به، فأخذ رسول اللّٰه ﷺ بعاتقي، فقال: «يا عبد الله، ارفع الإزار؛ فإن ما مست الأرض من الإزار إلى ما أسفل من الكعبين في النار». قال عبد اللّٰه بن محمد: فلم أر إنسانًا قط أشد تشميرًا من عبد اللّٰه بن عمر."],"takhrij":"حسن: رواه أحمد (٥٧١٣) وأبو يعلى (٥٧١٤).","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (5713) and Abū Yaʿlā (5714).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar said: “The Messenger of Allāh ﷺ clothed me in one of the siyarāʾ garments that Fayrūz had presented to him. I put on the lower garment, but it overwhelmed me in both length and width, so I dragged it. I then put on the upper garment and wrapped it around myself. The Messenger of Allāh ﷺ took hold of my shoulder and said: ‘O ʿAbdullāh, raise your lower garment, for whatever part of the garment touches the ground below the ankles is in the Fire.’”","ʿAbdullāh ibn Muḥammad said: “I never saw anyone who kept his garment raised more strictly than ʿAbdullāh ibn ʿUmar.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":5714},{"key":"ahmad","label":"مسند الإمام أحمد","number":5713,"n":5713},{"key":"sh12520","label":"مسند أبي يعلى","number":5714,"n":5719}]},{"num":5974,"demo":false,"sanad":"","matn":["عن عبد الله بن بسر قال: كان رسول اللّٰه ﷺ يقبل الهدية، ولا يقبل الصدقة."],"takhrij":"حسن: رواه أحمد (١٧٦٨٨).","grade":"حسن","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17688).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Busr said: “The Messenger of Allāh ﷺ would accept gifts, but he would not accept charity.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":17688,"n":17688}]},{"num":5975,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: قال رسول اللّٰه ﷺ: «أجيبوا الداعي، ولا تردوا الهدية، ولا تضربوا المسلمين»."],"takhrij":"صحيح: رواه أحمد (٣٨٣٨) والبخاري في الأدب المفرد (١٥٧) والبزار - كشف الأستار (١٢٤٣).","grade":"صحيح","chapter_ar":"باب قبول هدايا المسلمين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (3838), al-Bukhārī in al-Adab al-Mufrad (157), and al-Bazzār in Kashf al-Astār (1243).","chapter_en":"Accepting the Gifts of Muslims","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn Masʿūd reported that the Messenger of Allāh ﷺ said: “Respond to the one who invites you, do not reject a gift, and do not strike the Muslims.”"]}},"tuhfa":{},"refs":[{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":157},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1243},{"key":"ahmad","label":"مسند الإمام أحمد","number":3838,"n":3838},{"key":"adab","label":"الأدب المفرد","number":157,"n":157},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1243,"n":1243}]},{"num":5976,"demo":false,"sanad":"","matn":["عن عائشة: أن الناس كانوا يتحرون بهداياهم يوم عائشة، يبتغون بذلك مرضاة رسول اللّٰه ﷺ."],"takhrij":"متفق عليه: رواه البخاري (٢٥٧٤)، ومسلم (٢٤٤١).","grade":"متفق عليه","chapter_ar":"باب من تحرى وجود النبي ﷺ عند بعض نسائه دون بعض لتقديم الهدايا له لا يخالف العدل","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2574) and Muslim (2441).","chapter_en":"Those Who Sought the Time When the Prophet ﷺ Was with Certain Wives Rather Than Others in Order to Present Their Gifts to Him — This Does Not Contradict Justice","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿĀʾishah reported that the people used to deliberately choose ʿĀʾishah’s day to present their gifts, seeking thereby to please the Messenger of Allāh ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2574},{"key":"muslim","label":"مسلم","number":2441}]},{"num":5977,"demo":false,"sanad":"","matn":["عن عائشة قالت: إن نساء رسول اللّٰه ﷺ كن حزبين: فحزب فيه عائشة وحفصة وصفية وسودة، والحزب الآخر أم سلمة وسائر نساء رسول اللّٰه ﷺ، وكان المسلمون قد علموا حبَّ رسول اللّٰه ﷺ عائشة، فإذا كانت عند أحدهم هدية يريد أن يهديها إلى رسول اللّٰه ﷺ أخرها، حتى إذا كان رسول اللّٰه ﷺ في بيت عائشة بعث صاحب الهدية إلى رسول اللّٰه ﷺ في بيت عائشة، فكلم حزب أم سلمة، فقلن لها: كلمي رسول اللّٰه ﷺ يكلم الناس فيقول: من أراد أن يهدي إلى رسول اللّٰه ﷺ هدية فليهدها حيث كان من بيوت نسائه، فكلمته أم سلمة بما قلن، فلم يقل لها شيئًا، فسألنها، فقالت: ما قال لي شيئًا، فقلن لها: فكلميه، قالت: فكلمته حين دار إليها أيضًا، فلم يقل لها شيئًا، فسألنها فقالت: ما قال لي شيئًا، فقلن لها: كلميه حتى يكلمك، فدار إليها، فكلمته، فقال لها: «لا تؤذيني في عائشة، فإن الوحي لم يأتني وأنا في ثوب امرأة إلا عائشة». قالت: أتوب إلى اللّٰه من أذاك، يا رسول الله. ثم إنهن دعون فاطمة بنت رسول اللّٰه ﷺ، فأرسلت إلى رسول اللّٰه ﷺ تقول: إن نساءك ينشدنك العدل في بنت أبي بكر، فكلمته، فقال: «يا بنية، ألا تحبين ما أحب؟» قالت: بلى. فرجعت إليهن، فأخبرتهن، فقلن: ارجعي إليه، فأبت أن ترجع. فأرسلن زينب بنت جحش، فأتته، فأغلظت، وقالت: إن نساءك ينشدنك اللّٰه العدل في بنت ابن أبي قحافة، فرفعت صوتها حتى تناولت عائشة وهي قاعدة، فسبتها، حتى إن رسول اللّٰه ﷺ لينظر إلى عائشة هل تكلم. قال: فتكلمت عائشة ترد على زينب حتى أسكتتها. قالت: فنظر النبي ﷺ إلى عائشة، وقال: «إنها بنت أبي بكر»."],"takhrij":"صحيح: رواه البخاري (٢٥٨١)، ومسلم (٢٤٤٢).","grade":"صحيح","chapter_ar":"باب من تحرى وجود النبي ﷺ عند بعض نسائه دون بعض لتقديم الهدايا له لا يخالف العدل","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2581) and Muslim (2442).","chapter_en":"Those Who Sought the Time When the Prophet ﷺ Was with Certain Wives Rather Than Others in Order to Present Their Gifts to Him — This Does Not Contradict Justice","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿĀʾishah said: “The wives of the Messenger of Allāh ﷺ were divided into two groups. One group consisted of ʿĀʾishah, Ḥafṣah, Ṣafiyyah, and Sawdah, while the other group consisted of Umm Salamah and the rest of the wives of the Messenger of Allāh ﷺ.","“The Muslims knew of the Messenger of Allāh’s ﷺ love for ʿĀʾishah. So whenever one of them had a gift that he wished to present to the Messenger of Allāh ﷺ, he would delay it until the Messenger of Allāh ﷺ was in ʿĀʾishah’s house; then the owner of the gift would send it to the Messenger of Allāh ﷺ while he was in ʿĀʾishah’s house.","“The group of Umm Salamah discussed the matter and said to her, ‘Speak to the Messenger of Allāh ﷺ and ask him to tell the people: Whoever wishes to present a gift to the Messenger of Allāh ﷺ should present it to him wherever he happens to be among the houses of his wives.’","“Umm Salamah spoke to him about what they had said, but he said nothing to her. They asked her what had happened, and she said, ‘He said nothing to me.’ They said, ‘Then speak to him again.’ She said, ‘I spoke to him again when my turn came, but he said nothing to me.’ They asked her, and she replied, ‘He said nothing to me.’ They said, ‘Keep speaking to him until he answers you.’","“When her turn came again, she spoke to him. He said to her: ‘Do not hurt me regarding ʿĀʾishah, for revelation never came to me while I was under the covering of any woman except ʿĀʾishah.’","“She said, ‘I repent to Allāh for causing you hurt, O Messenger of Allāh.’","“Then they called Fāṭimah, the daughter of the Messenger of Allāh ﷺ, and sent her to the Messenger of Allāh ﷺ saying, ‘Your wives adjure you to observe justice regarding the daughter of Abū Bakr.’ She spoke to him, and he said: ‘O my daughter, do you not love what I love?’ She replied, ‘Yes.’ She returned to them and informed them. They said, ‘Go back to him,’ but she refused to return.","“They then sent Zaynab bint Jaḥsh. She came to him and spoke harshly, saying, ‘Your wives adjure you by Allāh to observe justice regarding the daughter of Ibn Abī Quḥāfah.’ She raised her voice until she turned upon ʿĀʾishah, who was sitting there, and insulted her. The Messenger of Allāh ﷺ kept looking at ʿĀʾishah to see whether she would respond.","“ʿĀʾishah then spoke and replied to Zaynab until she silenced her. The Prophet ﷺ looked at ʿĀʾishah and said: ‘Indeed, she is the daughter of Abū Bakr.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2581},{"key":"muslim","label":"مسلم","number":2442}]},{"num":5978,"demo":false,"sanad":"","matn":["عن أنس قال: إن النبي ﷺ كان لا يردّ الطيب."],"takhrij":"صحيح: رواه البخاري (٢٥٨٢).","grade":"صحيح","chapter_ar":"باب ما لا يرد من الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2582).","chapter_en":"Gifts That Should Not Be Refused","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas said: “The Prophet ﷺ would not refuse perfume.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2582}]},{"num":5979,"demo":false,"sanad":"","matn":["عن مسلم بن جندب أنه دخل مع عبد اللّٰه بن عمر على ابن مطيع، فقال: السلام عليك، فقال: وعليك السلام ورحمة اللّٰه، ومرحبًا وأهلًا بأبي عبد الرحمن، ضعوا له وسادة. فقال ابن عمر: لولا أن سمعت رسول اللّٰه ﷺ يقول: «ثلاث لا ترد: اللبن، ولا الوسادة، ولا الدهن» ما جلست عليها."],"takhrij":"حسن: رواه الترمذي (٢٧٩٠)، والطبراني (٣٣٦/١٢) - والسياق له -، والبيهقي في الشعب (٥٦٧٧).","grade":"حسن","chapter_ar":"باب ما لا يرد من الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2790), al-Ṭabarānī (12/336)—whose wording this is—and al-Bayhaqī in al-Shuʿab (5677).","chapter_en":"Gifts That Should Not Be Refused","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Muslim ibn Jundub reported that he entered with ʿAbdullāh ibn ʿUmar upon Ibn Muṭīʿ. Ibn ʿUmar said, “Peace be upon you.” He replied, “And upon you be peace and the mercy of Allāh. Welcome, and greetings to Abū ʿAbd al-Raḥmān. Place a cushion for him.”","Ibn ʿUmar said: “Had I not heard the Messenger of Allāh ﷺ say, ‘Three things are not to be refused: milk, a cushion, and scented oil,’ I would not have sat upon it.”"]},"buhuth":{"ar":["قوله: «الدهن» المراد منه الطيب."],"en":["His saying, “al-duhn” here means perfume or scented oil."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2790},{"key":"الطبرانی","label":"الطبراني","number":336},{"key":"البیہقی/الشعب","label":"البيهقي في الشعب","number":5677}]},{"num":5980,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ قالت: كان رسول اللّٰه ﷺ يقبل الهدية، ويُثِيب عليها."],"takhrij":"صحيح: رواه البخاري (٢٥٨٥).","grade":"صحيح","chapter_ar":"باب المكافأة في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2585).","chapter_en":"Giving Something in Return for a Gift","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, said: “The Messenger of Allāh ﷺ would accept gifts and give something in return for them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2585}]},{"num":5981,"demo":false,"sanad":"","matn":["عن ابن عباس أن أعرابيًا وهب للنبي ﷺ هبة، فأثابه عليها، قال: «رضيت؟» قال: لا. قال: فزاده. قال: «رضيت؟» قال: لا. قال: فزاده. قال: «رضيت؟» قال: نعم. قال: فقال رسول اللّٰه ﷺ: «لقد هممت أن لا أتهب هبة إلا من قرشي، أو أنصاري، أو ثقفي»."],"takhrij":"صحيح: رواه أحمد (٢٦٨٧)، والطبراني في الكبير (١٠٨٩٧)، والبزار - كشف الأستار (١٩٣٨).","grade":"صحيح","chapter_ar":"باب ترك النبي ﷺ قبول الهدية إلا عن قبائل معروفة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (2687), al-Ṭabarānī in al-Kabīr (10897), and al-Bazzār in Kashf al-Astār (1938).","chapter_en":"The Prophet ﷺ Refraining from Accepting Gifts Except from Certain Well-Known Tribes","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported that a Bedouin gave the Prophet ﷺ a gift, and the Prophet ﷺ gave him something in return. He asked, “Are you satisfied?” The man replied, “No.” So he gave him more and asked, “Are you satisfied?” He replied, “No.” So he gave him still more and asked, “Are you satisfied?” He replied, “Yes.”","The Messenger of Allāh ﷺ then said: “I had considered not accepting a gift except from a Qurashī, an Anṣārī, or a Thaqafī.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":10897},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1938},{"key":"ahmad","label":"مسند الإمام أحمد","number":2687,"n":2687},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1938,"n":1939}]},{"num":5982,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: أهدى رجل من بني فزارة إلى النبي ﷺ ناقة من إبله التي كانوا أصابوا بالغابة، فعوضه منها بعض العوض، فتسخطه، فسمعت رسول اللّٰه ﷺ على هذا المنبر يقول: «إن رجالًا من العرب يهدي أحدهم الهدية، فأعوضه منها بقدر ما عندي، ثم يتسخطه، فيظل يتسخط فيه علي، وأيم اللّٰه لا أقبل بعد مقامي هذا من رجل من العرب هدية إلا من قرشي، أو أنصاري، أو ثقفي، أو دوسي»."],"takhrij":"حسن: رواه الترمذي (٣٩٤٦) والبخاري في الأدب المفرد (٥٩٦)، وأبو داود (٣٥٣٧).","grade":"حسن","chapter_ar":"باب ترك النبي ﷺ قبول الهدية إلا عن قبائل معروفة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3946), al-Bukhārī in al-Adab al-Mufrad (596), and Abū Dāwūd (3537).","chapter_en":"The Prophet ﷺ Refraining from Accepting Gifts Except from Certain Well-Known Tribes","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah said: “A man from Banū Fazārah presented the Prophet ﷺ with a she-camel from among the camels they had acquired at al-Ghābah. The Prophet ﷺ compensated him for it with something, but the man was displeased with the compensation.","“I then heard the Messenger of Allāh ﷺ say from this pulpit: ‘There are men among the Arabs, one of whom gives me a gift, and I compensate him according to what I have available, yet afterward he becomes displeased with it and continues expressing his dissatisfaction toward me. By Allāh, after this occasion of mine, I will not accept a gift from any Arab man except a Qurashī, an Anṣārī, a Thaqafī, or a Dawsī.’”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3946},{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":596},{"key":"abudawud","label":"أبو داود","number":3537},{"key":"adab","label":"الأدب المفرد","number":596,"n":596}]},{"num":5983,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: إن أباه بشيرًا أتى به إلى النبي ﷺ، فقال: إني نحلت ابني هذا غلامًا كان لي. فقال رسول اللّٰه ﷺ: «أكل ولدك نحلته مثل هذا؟» فقال: لا. فقال رسول اللّٰه ﷺ: «فارتجعه»."],"takhrij":"متفق عليه: رواه مالك (٤١) والبخاري (٢٥٨٦)، ومسلم (١٦٢٣).","grade":"متفق عليه","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (41), al-Bukhārī (2586), and Muslim (1623).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr reported that his father, Bashīr, brought him to the Prophet ﷺ and said, “I have given this son of mine a slave who belonged to me.”","The Messenger of Allāh ﷺ asked: “Have you given every one of your children something like this?”","He replied, “No.”","The Messenger of Allāh ﷺ said: “Then take it back.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":41},{"key":"bukhari","label":"البخاري","number":2586},{"key":"muslim","label":"مسلم","number":1623}]},{"num":5984,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: سألت أمي أبي بعض الموهبة لي من ماله، ثم بدا له، فوهبها لي، فقالت: لا أرضى حتى تشهد النبي ﷺ، فأخذ بيدي، وأنا غلام، فأتى بي النبي ﷺ، فقال: إن أمه بنت رواحة سألتني بعض الموهبة لهذا. قال: «ألك ولد سواه؟» قال: نعم. قال فأراه قال: «لا تشهدني على جور»."],"takhrij":"صحيح: رواه البخاري (٢٦٥٠)، ومسلم (١٤: ١٦٢٣) واللفظ للبخاري. ولفظ مسلم: «أكلهم وهبت له مثل هذا؟» قال: لا. قال: «فلا تشهدني إذًا، فإني لا أشهد على جور».","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2650) and Muslim (1623:14). The wording is that of al-Bukhārī.","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My mother asked my father to give me a gift from his property. After some time he decided to do so and gave it to me. She said, ‘I will not be satisfied until you make the Prophet ﷺ a witness to it.’","“So he took me by the hand while I was still a boy and brought me to the Prophet ﷺ. He said, ‘His mother, the daughter of Rawāḥah, asked me to give this child a gift.’","“He asked: ‘Do you have any other children besides him?’","“He replied, ‘Yes.’","“He said—and I believe these were his words—‘Do not make me a witness to injustice.’”"]},"buhuth":{"en":["The wording of Muslim is: “Have you given all of them the same as you gave him?” He replied, “No.” He said: “Then do not make me a witness, for I do not bear witness to injustice.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2650},{"key":"muslim","label":"مسلم","number":14}]},{"num":5985,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال - وهو على المنبر -: أعطاني أبي عطية، فقالت أمي عمرة بنت رواحة: لا أرضى حتى تشهد رسول اللّٰه ﷺ، فأتى رسول اللّٰه ﷺ فقال: إني أعطيت ابني من عمرة بنت رواحة عطية، فأمرتني أن أشهدك يا رسول الله. قال: «أعطيت سائر ولدك مثل هذا؟» قال: لا. قال: «فاتقوا الله، واعدلوا بين أولادكم». قال: فرجع، فرد عطيته."],"takhrij":"متفق عليه: رواه البخاري (٢٥٨٧)، ومسلم (١٣: ١٦٢٣).","grade":"متفق عليه","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2587) and Muslim (1623:13).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said while standing upon the pulpit: “My father gave me a gift. My mother, ʿAmrah bint Rawāḥah, said, ‘I will not be satisfied until you make the Messenger of Allāh ﷺ a witness.’","“So he went to the Messenger of Allāh ﷺ and said, ‘I have given this son of mine, from ʿAmrah bint Rawāḥah, a gift, and she instructed me to make you a witness to it, O Messenger of Allāh.’","“He asked: ‘Have you given the rest of your children the same as this?’","“He replied, ‘No.’","“He said: ‘Then fear Allāh and be just between your children.’","“So he returned and took back his gift.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2587},{"key":"muslim","label":"مسلم","number":13}]},{"num":5986,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: نحلني أبي نحلاً، ثم أتى بي إلى رسول اللّٰه ﷺ ليشهده، فقال: «أكل ولدك أعطيته هذا؟» قال: لا. قال: «أليس تريد منهم البر مثل ما تريد من ذا؟» قال: بلى. قال: «فإني لا أشهد»."],"takhrij":"صحيح: رواه مسلم (١٨: ١٦٢٣).","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1623:18).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father gave me a gift, then brought me to the Messenger of Allāh ﷺ to make him a witness to it. He asked: ‘Have you given this to every one of your children?’ He replied, ‘No.’ He said: ‘Do you not desire dutifulness from all of them just as you desire it from this one?’ He replied, ‘Yes.’ He said: ‘Then I will not bear witness to it.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18}]},{"num":5987,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: انطلق بي أبي يحملني إلى رسول اللّٰه ﷺ، فقال: يا رسول الله، اشهد أني قد نحلت النعمان كذا وكذا من مالي، فقال: «أكل بنيك قد نحلت مثل ما نحلت النعمان؟» قال: لا. قال: «فأشهد على هذا غيري». ثم قال: «أيسرك أن يكونوا إليك في البر سواء؟» قال: بلى. قال: «فلا إذًا»."],"takhrij":"صحيح: رواه مسلم (١٧: ١٦٢٣).","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1623:17).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father carried me to the Messenger of Allāh ﷺ and said, ‘O Messenger of Allāh, bear witness that I have given al-Nuʿmān such-and-such from my property.’","“He asked: ‘Have you given all your sons the same as you have given al-Nuʿmān?’","“He replied, ‘No.’","“He said: ‘Then make someone other than me a witness to this.’ Then he said: ‘Would it please you for them all to be equally dutiful toward you?’","“He replied, ‘Yes.’","“He said: ‘Then do not do this.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17}]},{"num":5988,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: أعطاه أبوه غلامًا، فقال له النبي ﷺ: «ما هذا الغلام؟» قال: أعطانيه أبي. قال: «فكل إخوته أعطيته كما أعطيت هذا؟» قال: لا. قال: «فرده»."],"takhrij":"صحيح: رواه مسلم (١٢: ١٦٢٣).","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1623:12).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr reported that his father gave him a slave. The Prophet ﷺ asked: “What is this slave?”","He replied, “My father gave him to me.”","He asked his father: “Have you given all his brothers the same as you have given him?”","He replied, “No.”","He said: “Then take him back.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":12}]},{"num":5989,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: نحلني أبي نحلاً. قال إسماعيل بن سالم من بين القوم: نحله غلامًا. قال: فقالت له أمي عمرة بنت رواحة: ائت النبي ﷺ فأشهده. قال: فأتى النبي ﷺ فذكر ذلك له، فقال: إني نحلت ابني النعمان نحلاً، وإن عمرة سألتني أن أشهدك على ذلك، فقال: «ألك ولد سواه؟» قال: قلت: نعم. قال: «فكلهم أعطيت مثل ما أعطيت النعمان؟» فقال: لا. فقال بعض هؤلاء المحدثين: «هذا جور». وقال بعضهم: «هذا تلجئة، فأشهد على هذا غيري». وقال مغيرة في حديثه: «أليس يسرك أن يكونوا لك في البر واللطف سواء؟» قال: نعم. قال: «فأشهد على هذا غيري». وذكر مجالد في حديثه: «إن لهم عليك من الحق أن تعدل بينهم كما أن لك عليهم من الحق أن يبروك»."],"takhrij":"صحيح: رواه أحمد (١٨٣٧٨)، وأبو داود (٣٥٤٢).","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (18378) and Abū Dāwūd (3542).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father gave me a gift.” Ismāʿīl ibn Sālim, among the narrators, said: “He gave him a slave.”","He continued: “My mother, ʿAmrah bint Rawāḥah, said to him, ‘Go to the Prophet ﷺ and make him a witness.’ So he went to the Prophet ﷺ and mentioned the matter to him, saying, ‘I have given my son al-Nuʿmān a gift, and ʿAmrah asked me to make you a witness to it.’","“He asked: ‘Do you have any child besides him?’","“He replied, ‘Yes.’","“He asked: ‘Have you given all of them the same as you gave al-Nuʿmān?’","“He replied, ‘No.’”","Some of the narrators transmitted: “This is injustice.” Others transmitted: “This is coercion, so make someone other than me a witness to it.”","In Mughīrah’s narration, he said: “Would it not please you for them all to be equal toward you in dutifulness and kindness?”","He replied, “Yes.”","He said: “Then make someone other than me a witness to this.”","Mujālid mentioned in his narration: “They have a right over you that you deal justly between them, just as you have a right over them that they be dutiful to you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3542},{"key":"ahmad","label":"مسند الإمام أحمد","number":18378,"n":18378}]},{"num":5990,"demo":false,"sanad":"","matn":["عن النعمان بن بشير يقول: قال رسول اللّٰه ﷺ: «اعدلوا بين أولادكم، اعدلوا بين أبنائكم»."],"takhrij":"حسن: رواه أبو داود (٣٥٤٤)، والنسائي (٣٦٨٧)، وأحمد (١٨٤٢٢).","grade":"حسن","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3544), al-Nasāʾī (3687), and Aḥmad (18422).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr reported that the Messenger of Allāh ﷺ said: “Be just between your children; be just between your sons.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3544},{"key":"nasai","label":"النسائي","number":3687},{"key":"ahmad","label":"مسند الإمام أحمد","number":18422,"n":18422}]},{"num":5991,"demo":false,"sanad":"","matn":["عن النعمان بن بشير يقول - وهو يخطب -: انطلق بي أبي إلى رسول الله ﷺ يشهده على عطية أعطانيها، فقال: «هل لك بنون سواه؟» قال: نعم. قال: «سَوِّ بينهم»."],"takhrij":"صحيح: رواه النسائي (٣٦٨٧)، وأحمد (١٨٣٥٩)، وصححه ابن حبان (٥٠٩٨).","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (3687) and Aḥmad (18359), and authenticated by Ibn Ḥibbān (5098).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said while delivering a sermon: “My father took me to the Messenger of Allāh ﷺ to make him a witness to a gift that he had given me.","“He asked: ‘Do you have sons besides him?’","“He replied, ‘Yes.’","“He said: ‘Treat them equally.’”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3687},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":5098},{"key":"ahmad","label":"مسند الإمام أحمد","number":18359,"n":18359},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1503,"n":1500}]},{"num":5992,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: إن والدي بشير بن سعد أتى رسول الله ﷺ قال: يا رسول الله، إن عمرة بنت رواحة نُفست بغلام، وإني سميته: نعمان، وإنها أبت أن تربيه، وحتى جعلت له حديقة لي أفضل مالي هو، وإنها قالت: أشهد النبي ﷺ على ذلك. فقال له النبي ﷺ: «هل لك ولد غيره؟» قال: نعم. قال: «لا تشهدني إلا على عدل، فإني لا أشهد على جور»."],"takhrij":"حسن: رواه ابن حبان (٥١٠٧).","grade":"حسن","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (5107).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Nuʿmān ibn Bashīr said: “My father, Bashīr ibn Saʿd, came to the Messenger of Allāh ﷺ and said, ‘O Messenger of Allāh, ʿAmrah bint Rawāḥah gave birth to a boy, whom I named al-Nuʿmān. She refused to nurse and raise him until I assigned to him a garden of mine, which was my finest property, and she said: Make the Prophet ﷺ a witness to it.’","“The Prophet ﷺ asked him: ‘Do you have any other children?’","“He replied, ‘Yes.’","“He said: ‘Do not make me a witness except to something just, for I do not bear witness to injustice.’”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1511,"n":1508}]},{"num":5993,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قالت امرأة بشير: انحل ابني غلامك، وأشهد لي رسول اللّٰه ﷺ، فأتى رسول الله ﷺ فقال: إن ابنة فلان سألتني أن أنحل ابنها غلامي، وقالت: أشهد لي رسول اللّٰه ﷺ، فقال: «أله إخوة؟» قال: نعم. قال: «أفكلهم أعطيت مثل ما أعطيته؟» قال: لا. قال: «فليس يصلح هذا، وإني لا أشهد إلا على حق»."],"takhrij":"صحيح: رواه مسلم (١٦٢٤).","grade":"صحيح","chapter_ar":"باب العدل بين الأولاد في الهبة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1624).","chapter_en":"Justice Between One’s Children in Giving Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that Bashīr’s wife said: “Give my son your slave as a gift and make the Messenger of Allāh ﷺ a witness for me.”","So he went to the Messenger of Allāh ﷺ and said: “The daughter of so-and-so asked me to give her son my slave, and she said, ‘Make the Messenger of Allāh ﷺ a witness for me.’”","He asked: “Does he have brothers?”","He replied, “Yes.”","He asked: “Have you given all of them the same as you gave him?”","He replied, “No.”","He said: “This is not right, and I bear witness only to what is right.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1624}]},{"num":5994,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس، عن رسول اللّٰه ﷺ قال: «العائد في هبته كالكلب يقيء، ثم يعود في قيئه»."],"takhrij":"متفق عليه: رواه البخاري (٢٥٨٩)، ومسلم (٨: ١٦٢٢).","grade":"متفق عليه","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2589) and Muslim (1622:8).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allāh ﷺ said: “The one who takes back his gift is like a dog that vomits and then returns to its vomit.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2589},{"key":"muslim","label":"مسلم","number":8}]},{"num":5995,"demo":false,"sanad":"","matn":["عن ابن عمر وابن عباس قالا: قال رسول اللّٰه ﷺ: «لا ينبغي لأحد أن يعطي عطية، فيرجع فيها إلا الوالد فيما يعطيه ولده، ومثل الذي يعطي العطية، ثم يرجع فيها كالكلب يأكل حتى إذا شبع تقيأ، ثم عاد، فرجع في قيئه»."],"takhrij":"حسن: رواه أبو داود (٣٥٣٩)، والترمذي (٢١٣٣)، والنسائي (٣٦٩٠)، وابن ماجه (٢٣٧٧).","grade":"حسن","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3539), al-Tirmidhī (2133), al-Nasāʾī (3690), and Ibn Mājah (2377).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar and Ibn ʿAbbās reported that the Messenger of Allāh ﷺ said: “It is not proper for anyone to give a gift and then take it back, except a parent regarding what he gives to his child. The example of one who gives a gift and then takes it back is like a dog that eats until it is full, then vomits, and afterward returns to its vomit.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3539},{"key":"tirmidhi","label":"الترمذي","number":2133},{"key":"nasai","label":"النسائي","number":3690},{"key":"ibnmajah","label":"ابن ماجه","number":2377}]},{"num":5996,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن رسول اللّٰه ﷺ قال: «مثل الذي يعود في عطيته، كمثل الكلب يأكل، حتى إذا شبع قاء، ثم عاد في قيئه، فأكله»."],"takhrij":"صحيح: رواه ابن ماجه (٢٣٨٤) والإمام أحمد (١٠٣٨٢، ١٠٣٨١، ٧٥٢٤).","grade":"صحيح","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (2384) and Imām Aḥmad (10382, 10381, 7524).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allāh ﷺ said: “The example of one who takes back his gift is like a dog that eats until it is full, then vomits, and afterward returns to its vomit and eats it.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2384},{"key":"الامام_احمد","label":"الإمام أحمد","number":10382},{"key":"ahmad","label":"مسند الإمام أحمد","number":10382,"n":10382}]},{"num":5997,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو، عن رسول اللّٰه ﷺ قال: «مثل الذي يسترد ما وهب كمثل الكلب يقيء، فيأكل قيئه، فإذا استرد الواهب فليُوقف، فليعرف بما استرد، ثم ليدفع إليه ما وهب»."],"takhrij":"حسن: رواه أبو داود (٣٥٤٠) وأحمد (٦٦٢٩).","grade":"حسن","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3540) and Aḥmad (6629).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr reported that the Messenger of Allāh ﷺ said: “The example of one who reclaims what he has given is like a dog that vomits and then eats its vomit. If the giver seeks to reclaim it, he should be stopped and made aware of what it is that he is reclaiming, then what he gave may be returned to him.”"]},"buhuth":{"ar":["وقوله: «فإذا استرد الواهب» أي بعد أن سمع مثل الكلب الذي يعود في قيئه، فإن الواهب أحق بهبته ما لم يثب منها، ولكنه كالكلب الذي يعود في قيئه، فإن شاء ارتجع، وإن شاء ترك، ففيه ترهيب وتحذير من العودة إلى الهبة."],"en":["His saying, “If the giver seeks to reclaim it,” means after he has heard the comparison with a dog returning to its vomit. The giver has a stronger claim to his gift so long as he has not received compensation for it, but he is likened to a dog returning to its vomit. If he wishes, he may reclaim it, and if he wishes, he may leave it. Thus, the hadith contains a severe deterrent and warning against taking back a gift."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3540},{"key":"ahmad","label":"مسند الإمام أحمد","number":6629,"n":6629}]},{"num":5998,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو بن العاص أن رسول اللّٰه ﷺ قال: «لا يرجع في هبته إلا الوالد من ولده. والعائد في هبته كالعائد في قيئه»."],"takhrij":"حسن: رواه النسائي (٣٦٨٩)، والدارقطني (٤٣/٣)، والبيهقي (١٧٩/٦)، وأحمد (٦٧٠٥).","grade":"حسن","chapter_ar":"باب النهي عن الرجوع في الهبة إلا للوالد","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasāʾī (3689), al-Dāraquṭnī (3/43), al-Bayhaqī (6/179), and Aḥmad (6705).","chapter_en":"The Prohibition of Taking Back a Gift, Except for a Parent","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ reported that the Messenger of Allāh ﷺ said: “No one may take back his gift except a parent from his child. The one who takes back his gift is like one who returns to his vomit.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3689},{"key":"الدارقطنی","label":"الدارقطني","number":43},{"key":"البیہقی","label":"البيهقي","number":179},{"key":"sh9771","label":"سنن الدارقطني","number":2968,"n":2980},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12013,"n":12125},{"key":"ahmad","label":"مسند الإمام أحمد","number":6705,"n":6705}]},{"num":5999,"demo":false,"sanad":"","matn":["عن أبي حميد الساعدي قال: استعمل رسول اللّٰه ﷺ رجلًا من الأسد - يقال له: ابن اللتبية -، فلما قدم قال: هذا لكم، وهذا لي، أُهدي لي. قال: فقام رسول اللّٰه ﷺ على المنبر، فحمد الله، وأثنى عليه وقال: «ما بال عامل أبعثه، فيقول: هذا لكم، وهذا أُهدي لي، أفلا قعد في بيت أبيه أو في بيت أمه حتى ينظر أيهدى إليه أم لا! والذي نفس محمد بيده لا ينال أحد منكم منها شيئًا إلا جاء به يوم القيامة يحمله على عنقه، بعير له رغاء، أو بقرة لها خوار، أو شاة تيعر»."],"takhrij":"متفق عليه: رواه البخاري (٦٦٣٦)، ومسلم (١٨٣٢).","grade":"متفق عليه","chapter_ar":"باب من يحرم عليه قبول الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6636) and Muslim (1832).","chapter_en":"Those for Whom It Is Forbidden to Accept Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abū Ḥumayd al-Sāʿidī said: “The Messenger of Allāh ﷺ appointed a man from al-Asd, called Ibn al-Lutbiyyah, to collect revenues. When he returned, he said, ‘This is for you, and this is for me; it was given to me as a gift.’","“The Messenger of Allāh ﷺ then stood upon the pulpit, praised Allāh and extolled Him, and said:","“‘What is the matter with an official whom I appoint, who then says: “This is for you, and this was given to me as a gift”? Why did he not sit in the house of his father or the house of his mother and see whether gifts would be given to him or not?","“‘By the One in Whose hand is the soul of Muḥammad, none of you takes anything from it unlawfully except that he will come carrying it upon his neck on the Day of Resurrection: a camel groaning, a cow lowing, or a sheep bleating.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6636},{"key":"muslim","label":"مسلم","number":1832}]},{"num":6000,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب قال: حملت على فرس في سبيل الله، فأضاعه الذي كان عنده، فأردت أن أشتريه منه، وظننت أنه بائعه برخص، فسألت عن ذلك النبي ﷺ فقال: «لا تشتره، وإن أعطاكه بدرهم واحد، فإن العائد في صدقته كالكلب يعود في قيئه»."],"takhrij":"متفق عليه: رواه مالك (٥٠) والبخاري (٢٦٢٣)، ومسلم (١٦٢٠).","grade":"متفق عليه","chapter_ar":"باب من يحرم عليه قبول الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (50), al-Bukhārī (2623), and Muslim (1620).","chapter_en":"Those for Whom It Is Forbidden to Accept Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb said: “I gave a horse for use in the cause of Allāh, but the man who had it neglected it. I wanted to buy it back from him, thinking that he would sell it cheaply. So I asked the Prophet ﷺ about it, and he said:","“‘Do not buy it, even if he offers it to you for a single dirham, for the one who takes back his charity is like a dog returning to its vomit.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":50},{"key":"bukhari","label":"البخاري","number":2623},{"key":"muslim","label":"مسلم","number":1620}]},{"num":6001,"demo":false,"sanad":"","matn":["عن أبي أمامة عن النبي ﷺ قال: «من شفع لأخيه بشفاعة، فأُهدي له هدية عليها، فقبلها، فقد أتى بابًا عظيمًا من أبواب الربا»."],"takhrij":"حسن: رواه أبو داود (٣٥٤١).","grade":"حسن","chapter_ar":"باب من يحرم عليه قبول الهدية","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3541).","chapter_en":"Those for Whom It Is Forbidden to Accept Gifts","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abū Umāmah reported that the Prophet ﷺ said: “Whoever intercedes on behalf of his brother, and a gift is then given to him because of that intercession and he accepts it, has entered through a great door of the doors of usury.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3541}]},{"num":6002,"demo":false,"sanad":"","matn":["عن جابر قال: قال لي رسول اللّٰه ﷺ: «لو جاء مال البحرين أعطيتك هكذا ثلاثًا». فلم يقدم حتى توفي النبي ﷺ، فأمر أبو بكر مناديًا فنادى: من كان له عند النبي ﷺ عدة أو دين فليأتنا. فأتيته، فقلت: إن النبي ﷺ وعدني، فحثا لي ثلاثًا."],"takhrij":"متفق عليه: رواه البخاري (٢٥٩٨)، ومسلم (٢٣١٤).","grade":"متفق عليه","chapter_ar":"باب إذا وهب هبة أو وعد ثم مات قبل الوفاء به يجوز لمن بعده أن يفيه","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2598) and Muslim (2314).","chapter_en":"If Someone Gives or Promises a Gift and Then Dies Before Fulfilling It, It Is Permissible for Those After Him to Fulfill It","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Jābir said: “The Messenger of Allāh ﷺ said to me: ‘If the wealth of Bahrain arrives, I will give you like this,’ and he gestured three times.","“But the wealth did not arrive until after the Prophet ﷺ had died. Abū Bakr then ordered a caller to announce: ‘Whoever has a promise or debt owed to him by the Prophet ﷺ should come to us.’","“So I went to him and said, ‘The Prophet ﷺ made me a promise.’ Abū Bakr then scooped out three handfuls for me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2598},{"key":"muslim","label":"مسلم","number":2314}]},{"num":6003,"demo":false,"sanad":"","matn":["عن المسور بن مخرمة قال: قسم رسول اللّٰه ﷺ أقبية، ولم يعط مخرمة منها شيئًا. فقال مخرمة: يا بني انطلق بنا إلى رسول اللّٰه ﷺ فانطلقت معه، فقال: ادخل، فادعه لي. قال: فدعوته له، فخرج إليه، وعليه قباء منها. فقال: «خبأنا هذا لك». قال: فنظر إليه، فقال: «رضي مخرمة»."],"takhrij":"متفق عليه: رواه البخاري (٢٥٩٩)، ومسلم (١٠٥٨). وفي رواية عند البخاري: «وكان في خلقه شدة».","grade":"متفق عليه","chapter_ar":"باب يجوز للإمام أن يخبئ هدية لمن غاب ولم يحضر القسمة","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2599) and Muslim (1058).","chapter_en":"It Is Permissible for the Leader to Reserve a Gift for One Who Is Absent and Did Not Attend the Distribution","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Al-Miswar ibn Makhramah said: “The Messenger of Allāh ﷺ distributed some cloaks but did not give Makhramah anything from them. Makhramah said, ‘My son, come with me to the Messenger of Allāh ﷺ.’","“So I went with him. He said to me, ‘Go inside and call him for me.’","“I called him, and he came out wearing one of the cloaks. He said: ‘We reserved this one for you.’","“Makhramah looked at it, and the Prophet ﷺ said: ‘Makhramah is pleased.’”"]},"buhuth":{"en":["In another narration in al-Bukhārī: “There was some severity in his character.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2599},{"key":"muslim","label":"مسلم","number":1058}]},{"num":6004,"demo":false,"sanad":"","matn":["عن ابن عمر أنه كان في سفر مع رسول الله ﷺ وكان على بكر صعب لعمر. فكان يتقدم النبي ﷺ، فيقول أبوه: يا عبد الله، لا يتقدم النبي ﷺ أحد. فقال له النبي ﷺ: «بعنيه». فقال عمر: هو لك، فاشتراه، ثم قال لعبد اللّه: «هو لك يا عبد الله، فاصنع به ما شئت»."],"takhrij":"صحيح: أخرجه البخاري (٢٦١٠).","grade":"صحيح","chapter_ar":"باب من وهب شيئًا وهو في تصرف الموهوب له فهو جائز","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2610).","chapter_en":"If Someone Gives Something That Is Already in the Possession of the Recipient, the Gift Is Valid","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar reported that he was traveling with the Messenger of Allāh ﷺ while riding a difficult young camel belonging to ʿUmar. The camel would move ahead of the Prophet ﷺ, so his father would say: “O ʿAbdullāh, no one should ride ahead of the Prophet ﷺ.”","The Prophet ﷺ then said to ʿUmar: “Sell it to me.”","ʿUmar replied, “It is yours.”","The Prophet ﷺ purchased it and then said to ʿAbdullāh: “It is yours, O ʿAbdullāh, so do with it whatever you wish.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2610}]},{"num":6005,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: أهدى إلي رسول اللّٰه ﷺ حلة سيراء، فلبستها، فرأيت الغضب في وجهه، فشققتها بين نسائي."],"takhrij":"متفق عليه: رواه البخاري (٢٦١٤)، ومسلم (١٩: ٢٠٧١).","grade":"متفق عليه","chapter_ar":"باب هدية يكره استعمالها","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2614) and Muslim (2071:19).","chapter_en":"A Gift Whose Use Is Disliked","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: “The Messenger of Allāh ﷺ presented me with a siyarāʾ garment. I wore it, but I saw anger on his face, so I tore it up and distributed it among my women.”"]},"buhuth":{"ar":["وفي رواية قال: «إني لم أبعث بها إليك لتلبسها، إنما بعثت بها إليك لتشققها خُمُرًا بين النساء»."],"en":["In another narration, he ﷺ said: “I did not send it to you so that you would wear it. I only sent it to you so that you would cut it into head-coverings for the women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2614},{"key":"muslim","label":"مسلم","number":19}]},{"num":6006,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عمر قال: رأى عمر عطارِدًا التميمي يقيم بالسوق حلة سيراء - وكان رجلًا يغشى الملوك ويصيب منهم - فقال عمر: يا رسول الله، إني رأيت عطارِدًا يقيم في السوق حلة سيراء، فلو اشتريتها، فلبستها لوفود العرب إذا قدموا عليك. وأظنه قال: ولبستها يوم الجمعة. فقال له رسول اللّٰه ﷺ: «إنما يلبس الحرير في الدنيا من لا خلاق له في الآخرة». فلما كان بعد ذلك أتي رسول اللّٰه ﷺ بحلل سيراء، فبعث إلى عمر بحلة، وبعث إلى أسامة بن زيد بحلة، وأعطى علي بن أبي طالب حلة، وقال: «شققها خُمُرًا بين نسائك». قال: فجاء عمر بحلته يحملها، فقال: يا رسول الله، بعثت إلي بهذه، وقد قلت بالأمس في حلة عطارد ما قلت. فقال: «إني لم أبعث بها إليك لتلبسها، ولكني بعثت بها إليك لتصيب بها». وأما أسامة فراح في حلته فنظر إليه رسول اللّه ﷺ نظرًا عرف أن رسول اللّٰه ﷺ قد أنكر ما صنع، فقال: يا رسول الله، ما تنظر إليَّ؟ فأنت بعثت إلي بها. فقال: «إني لم أبعث بها إليك لتلبسها، ولكني بعثت بها إليك لتشققها خُمُرًا بين نسائك»."],"takhrij":"صحيح: رواه مسلم (٧: ٢٠٦٨).","grade":"صحيح","chapter_ar":"باب هدية يكره استعمالها","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2068:7).","chapter_en":"A Gift Whose Use Is Disliked","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: “ʿUmar saw ʿUṭārid al-Tamīmī displaying a siyarāʾ garment in the marketplace. He was a man who used to frequent kings and receive things from them.","“ʿUmar said: ‘O Messenger of Allāh, I saw ʿUṭārid displaying a siyarāʾ garment in the marketplace. If only you would buy it and wear it when Arab delegations come to you.’ And I think he also said: ‘And wear it on Fridays.’","“The Messenger of Allāh ﷺ said to him: ‘Silk in this world is worn only by one who has no share in the Hereafter.’","“Later, some siyarāʾ garments were brought to the Messenger of Allāh ﷺ. He sent one garment to ʿUmar, one to Usāmah ibn Zayd, and gave one to ʿAlī ibn Abī Ṭālib, saying: ‘Cut it into head-coverings for your women.’","“ʿUmar came carrying his garment and said: ‘O Messenger of Allāh, you sent this to me, although yesterday you said what you said regarding ʿUṭārid’s garment.’","“He replied: ‘I did not send it to you so that you would wear it. I sent it to you so that you might derive benefit from it.’","“As for Usāmah, he went out wearing his garment. The Messenger of Allāh ﷺ looked at him in such a way that Usāmah realized that the Messenger of Allāh ﷺ disapproved of what he had done.","“He said: ‘O Messenger of Allāh, why are you looking at me? You are the one who sent it to me.’","“He replied: ‘I did not send it to you so that you would wear it. I sent it to you so that you would cut it into head-coverings for your women.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":7}]},{"num":6007,"demo":false,"sanad":"","matn":["عن عياض بن حمار قال: أهديت لرسول اللّٰه ﷺ ناقة - أو قال: هدية -، فقال: «أسلمتَ؟» قلت: لا. قال: «إني نهيت عن زَبْد المشركين»."],"takhrij":"حسن: رواه أبو داود (٣٠٥٧) والترمذي (١٥٧٧) والبيهقي (٢١٦/٩). قال الترمذي: «حسن صحيح».","grade":"حسن","chapter_ar":"باب ما جاء في رد هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3057), al-Tirmidhī (1577), and al-Bayhaqī (9/216). Al-Tirmidhī said: “Hasan Sahih.”","chapter_en":"What Has Been Reported Concerning Refusing the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿIyāḍ ibn Ḥimār said: “I presented the Messenger of Allāh ﷺ with a she-camel—or he said: a gift. He asked: ‘Have you embraced Islām?’","“I replied, ‘No.’","“He said: ‘I have been prohibited from accepting the gifts of the polytheists.’”"]},"buhuth":{"ar":["وقوله: «زبد المشركين» الزبد - بسكون الباء - الرفد والعطاء، والعرب تسمي الهدية الزبد. انظر: النهاية."],"en":["His saying, “zabd al-mushrikīn”: zabd, with a sākin bāʾ, means assistance or a gift. The Arabs call a gift zabd. See: al-Nihāyah."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3057},{"key":"tirmidhi","label":"الترمذي","number":1577},{"key":"البیہقی","label":"البيهقي","number":216},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":18793,"n":18951}]},{"num":6008,"demo":false,"sanad":"","matn":["عن عبيدالله بن المغيرة، عن عراك بن مالك، أن حكيم بن حزام قال: كان محمد ﷺ أحب رجل في الناس إليَّ في الجاهلية، فلما تنبأ وخرج إلى المدينة، شهد حكيم بن حزام الموسم وهو كافر، فوجد حلة لذي يزن تباع، فاشتراها بخمسين دينارًا ليهديها لرسول اللّٰه ﷺ، فقدم بها عليه المدينة، فأراده على قبضها هدية، فأبى. قال عبيدالله: حسبت أنه قال: «إنا لا نقبل شيئًا من المشركين، ولكن إن شئت أخذناها بالثمن» فأعطيته حين أبى علي الهدية."],"takhrij":"حسن: رواه أحمد (١٥٣٢٣).","grade":"حسن","chapter_ar":"باب ما جاء في رد هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15323).","chapter_en":"What Has Been Reported Concerning Refusing the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿUbaydullāh ibn al-Mughīrah reported from ʿIrāk ibn Mālik that Ḥakīm ibn Ḥizām said: “Muḥammad ﷺ was the most beloved of all people to me during the time of Jāhiliyyah. When he became a Prophet and departed for Madīnah, I attended the pilgrimage season while still an unbeliever.","“I found a garment that had belonged to Dhū Yazan being offered for sale, so I purchased it for fifty dinars in order to give it as a gift to the Messenger of Allāh ﷺ.","“I brought it to him in Madīnah and wanted him to accept it as a gift, but he refused.”","ʿUbaydullāh said: “I think he said: ‘We do not accept anything from the polytheists, but if you wish, we will take it for its price.’ So I gave it to him after he refused to accept it from me as a gift.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":15323,"n":15323}]},{"num":6009,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: أُهدي لرسول اللّٰه ﷺ جبة سندس، وكان ينهى عن الحرير، فعجب الناس منها، فقال: «والذي نفس محمد بيده إن مناديل سعد بن معاذ في الجنة أحسن من هذا»."],"takhrij":"متفق عليه: رواه البخاري (٢٦١٥)، ومسلم (٢٤٦٩).","grade":"متفق عليه","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2615) and Muslim (2469).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas ibn Mālik said: “A robe of fine silk was presented to the Messenger of Allāh ﷺ, while he used to forbid silk. The people were amazed by it, so he said:","‘By the One in Whose hand is the soul of Muḥammad, the handkerchiefs of Saʿd ibn Muʿādh in Paradise are finer than this.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2615},{"key":"muslim","label":"مسلم","number":2469}]},{"num":6010,"demo":false,"sanad":"","matn":["عن أنس أن يهودية أتت النبي ﷺ بشاة مسمومة، فأكل منها، فجيء بها، فقيل: ألا قتلها؟ قال: «لا». فما زلت أعرفها في لهوات رسول اللّٰه ﷺ."],"takhrij":"متفق عليه: رواه البخاري (٢٦١٧)، ومسلم (٢١٩٠). وقوله: «لهوات» جمع لهاة، وهي سقف الفم، أو اللحمة المشرفة على الحلق. وقيل: هي أقصى الحلق. وقيل: ما يبدو من الفم عند التبسم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2617) and Muslim (2190).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas reported that a Jewish woman brought the Prophet ﷺ a poisoned sheep, and he ate from it. She was brought before him, and it was said, “Should we not kill her?”","He replied: “No.”","Anas said: “I continued to recognize the effects of it in the soft tissues of the mouth and throat of the Messenger of Allāh ﷺ.”"]},"buhuth":{"en":["His saying, “lahawāt” is the plural of lahāh. It refers to the roof of the mouth or the fleshy part overlooking the throat. It has also been said to mean the furthest part of the throat, or that which becomes visible inside the mouth when a person smiles."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2617},{"key":"muslim","label":"مسلم","number":2190}]},{"num":6011,"demo":false,"sanad":"","matn":["عن أبي حميد الساعدي، قال: أهدى ملك أيلة للنبي ﷺ بغلة بيضاء، وكساه بردًا، وكتب له ببحرهم."],"takhrij":"متفق عليه: رواه البخاري (١٤٨١)، ومسلم (١١/١٣٩٢)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1481) and Muslim (1392/11). The wording is that of al-Bukhārī.","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Abū Ḥumayd al-Sāʿidī said: “The ruler of Aylah presented the Prophet ﷺ with a white mule and clothed him in a mantle, and the Prophet ﷺ wrote for him concerning their coastal territory.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1481},{"key":"muslim","label":"مسلم","number":11}]},{"num":6012,"demo":false,"sanad":"","matn":["عن بريدة بن الحصيب قال: أهدى أمير القبط لرسول اللّه ﷺ جاريتين أختين قبطيتين، وبغلة، فأما البغلة فكان رسول اللّه ﷺ يركبها، وأما إحدى الجاريتين فتسراها، فولدت له إبراهيم، وأما الأخرى فأعطاها حسان بن ثابت الأنصاري."],"takhrij":"حسن: رواه الحارث بن أبي أسامة في مسنده (٤٥٢ - بغية الباحث)، والطحاوي في شرح المشكل (٢٥٦٩).","grade":"حسن","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥārith ibn Abī Usāmah in his Musnad (452 — Bughyat al-Bāḥith) and al-Ṭaḥāwī in Sharḥ al-Mushkil (2569).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb said: “The ruler of the Copts presented the Messenger of Allāh ﷺ with two Coptic slave women who were sisters, together with a mule. As for the mule, the Messenger of Allāh ﷺ used to ride it. As for one of the two women, he took her as a concubine, and she bore him Ibrāhīm. The other he gave to Ḥassān ibn Thābit al-Anṣārī.”"]}},"tuhfa":{},"refs":[{"key":"الحارث_بن_ابی_اسامہ/مسندہ","label":"الحارث بن أبي أسامة في مسنده","number":452},{"key":"الطحاوی/شرح_المشکل","label":"الطحاوي في شرح المشكل","number":2569}]},{"num":6013,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن عبد القاري أن رسول اللّٰه ﷺ بعث حاطب بن أبي بلتعة إلى المقوقس صاحب الإسكندرية، يعني بكتابه معه إليه، فقبَّل كتابه، وأكرم حاطبًا، وأحسن نزله، ثم سرحه إلى رسول اللّٰه ﷺ، وأهدى له مع حاطب كسوة وبغلة شهباء بسرجها وجاريتين، إحداهما أم إبراهيم، وأما الأخرى فوهبها لجهم بن قيس العبدري، وهي أم زكريا بن جهم الذي كان خليفة عمرو بن العاص على مصر."],"takhrij":"صحيح: رواه الطحاوي في شرح المشكل (٤٣٤٩)، (٢٥٧٠).","grade":"صحيح","chapter_ar":"باب ما جاء في قبول هدية المشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ṭaḥāwī in Sharḥ al-Mushkil (4349, 2570).","chapter_en":"What Has Been Reported Concerning Accepting the Gifts of Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿAbd al-Qārī reported that the Messenger of Allāh ﷺ sent Ḥāṭib ibn Abī Baltaʿah to al-Muqawqis, the ruler of Alexandria, carrying his letter to him.","Al-Muqawqis received his letter respectfully, honored Ḥāṭib, provided him with excellent hospitality, and then sent him back to the Messenger of Allāh ﷺ. With Ḥāṭib he sent gifts for the Prophet ﷺ consisting of clothing, a grayish-white mule with its saddle, and two slave women. One of them was the mother of Ibrāhīm. As for the other, he gave her to Jahm ibn Qays al-ʿAbdarī. She was the mother of Zakariyyā ibn Jahm, who served as the deputy of ʿAmr ibn al-ʿĀṣ over Egypt."]},"buhuth":{"ar":["وقوله: «وأما الأخرى فوهبها لجهم بن قيس العبدري» فهو مخالف لما جاء في حديث بريدة: «وأما الأخرى فأعطاها حسان بن ثابت»، وما في حديث بريدة أصح، ولعل ما يخالفه وقع فيه وهم من بعض الرواة."],"en":["His statement, “As for the other, he gave her to Jahm ibn Qays al-ʿAbdarī,” conflicts with what appears in the hadith of Buraydah: “As for the other, he gave her to Ḥassān ibn Thābit.” What appears in the hadith of Buraydah is more authentic, and it is possible that the contradictory wording arose from an error by one of the narrators."]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرح_المشکل","label":"الطحاوي في شرح المشكل","number":4349}]},{"num":6014,"demo":false,"sanad":"","matn":["عن ابن عمر أن عمر بن الخطاب رأى حلة سيراء عند باب المسجد، فقال: يا رسول الله، لو اشتريت هذه، فلبستها يوم الجمعة، وللوفد إذا قدموا عليك. فقال رسول اللّٰه ﷺ: «إنما يلبس هذه من لا خلاق له في الآخرة». ثم جاءت رسول اللّٰه ﷺ منها حلل، فأعطى عمر بن الخطاب منها حلة، فقال عمر: يا رسول الله، كسوتنيها، وقد قلت في حلة عطارد ما قلت. قال رسول اللّٰه ﷺ: «إني لم أكسكها لتلبسها». فكساها عمر بن الخطاب أخًا له بمكة مشركًا."],"takhrij":"متفق عليه: رواه مالك (١٦٣٧)، والبخاري (٨٨٦)، ومسلم (٢٠٦٨).","grade":"متفق عليه","chapter_ar":"باب الهدية للمشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (1637), al-Bukhārī (886), and Muslim (2068).","chapter_en":"Giving Gifts to Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿUmar reported that ʿUmar ibn al-Khaṭṭāb saw a siyarāʾ garment by the door of the mosque and said, “O Messenger of Allāh, if only you would buy this and wear it on Friday and when delegations come to you.”","The Messenger of Allāh ﷺ said: “This is worn only by one who has no share in the Hereafter.”","Later, some garments of that kind were brought to the Messenger of Allāh ﷺ, and he gave one of them to ʿUmar ibn al-Khaṭṭāb. ʿUmar said, “O Messenger of Allāh, you have clothed me in this even though you said what you said about the garment of ʿUṭārid.”","The Messenger of Allāh ﷺ said: “I did not give it to you so that you would wear it.”","So ʿUmar ibn al-Khaṭṭāb gave it to a polytheist brother of his in Makkah."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿لَا يَنْهَاكُمُ اللّٰهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللّٰهَ يُحِبُّ الْمُقْسِطِينَ﴾ [سورة الممتحنة: ٨]."],"en":["Allāh Most High says: “Allāh does not forbid you from dealing kindly and justly with those who did not fight you because of religion and did not expel you from your homes. Indeed, Allāh loves those who act justly.”","[Surat al-Mumtaḥanah: 8]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1637},{"key":"bukhari","label":"البخاري","number":886},{"key":"muslim","label":"مسلم","number":2068}]},{"num":6015,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر قالت: قدمت علي أمي، وهي مشركة في عهد رسول اللّٰه ﷺ، فاستفتيت رسول اللّٰه ﷺ، قلت: وهي راغبة، أفأصل أمي؟ قال: «نعم، صلي أمك»."],"takhrij":"متفق عليه: رواه البخاري (٢٦٢٠)، ومسلم (١٠٠٣).","grade":"متفق عليه","chapter_ar":"باب الهدية للمشركين","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2620) and Muslim (1003).","chapter_en":"Giving Gifts to Polytheists","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr said: “My mother came to me while she was still a polytheist during the lifetime of the Messenger of Allāh ﷺ. I asked the Messenger of Allāh ﷺ for a ruling and said, ‘She has come seeking my favor; should I maintain ties with my mother?’","He said: ‘Yes, maintain ties with your mother.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2620},{"key":"muslim","label":"مسلم","number":1003}]},{"num":6016,"demo":false,"sanad":"","matn":["عن أيمن الحبشي المكي قال: دخلت على عائشة وعليها درع قطر، ثمن خمسة دراهم. فقالت: ارفع بصرك إلى جاريتي، انظر إليها فإنها تزهى أن تلبسه في البيت، وقد كان لي منهن درع على عهد رسول اللّٰه ﷺ، فما كانت امرأة تُقيَّنُ بالمدينة إلا أرسلت إلي تستعيره."],"takhrij":"صحيح: رواه البخاري (٢٦٢٨). وقوله: «تزهى»: إذا دخله الكبر. وقوله: «تُقيَّن» أي تُزين، من قان الشيء إذا أصلحه. وفيه أن عارية الثياب للعروس أمر معمول به، مرغب فيه، وأنه لا يعد من الشنع.","grade":"صحيح","chapter_ar":"باب استعارة الملابس للعروس عند البناء","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2628).","chapter_en":"Borrowing Clothes for a Bride at the Time of Consummation","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Ayman al-Ḥabashī al-Makkī said: “I entered upon ʿĀʾishah while she was wearing a striped garment worth five dirhams. She said, ‘Raise your gaze toward my slave girl and look at her, for she is too proud to wear it in the house. I had a garment like it during the time of the Messenger of Allāh ﷺ, and whenever any woman in Madīnah was being prepared and adorned as a bride, she would send to me asking to borrow it.’”"]},"buhuth":{"en":["His saying, “تزهى” means that pride or conceit enters a person.","His saying, “تُقيَّن” means “to be adorned,” from the expression qāna al-shayʾ, meaning to improve or beautify something.","This indicates that lending clothes to a bride was a customary practice, encouraged and accepted, and was not regarded as something shameful or objectionable."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2628}]},{"num":6017,"demo":false,"sanad":"","matn":["عن جابر قال: قضى النبي ﷺ بالعمرى، أنها لمن وهبت له."],"takhrij":"متفق عليه: رواه البخاري (٢٦٢٥)، ومسلم (٢٥: ١٦٢٥).","grade":"متفق عليه","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2625) and Muslim (1625:25).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir said: “The Prophet ﷺ ruled concerning ʿumrā that it belongs to the person to whom it was given.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2625},{"key":"muslim","label":"مسلم","number":25}]},{"num":6018,"demo":false,"sanad":"","matn":["عن جابر، عن النبي ﷺ قال: «العمرى جائزة»."],"takhrij":"متفق عليه: رواه مسلم (٣٠: ١٦٢٥)، والبخاري (٢٦٢٦).","grade":"متفق عليه","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1625:30) and al-Bukhārī (2626).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir reported that the Prophet ﷺ said: “ʿUmrā is valid.”"]},"buhuth":{"ar":["وقوله: «جائزة» أي صحيحة مستمرة لمن أعمر له، ولورثته من بعده."],"en":["His saying, “valid” means that it is legally effective and remains the property of the one to whom the ʿumrā was granted, and then of his heirs after him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":30},{"key":"bukhari","label":"البخاري","number":2626}]},{"num":6019,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أن رسول اللّٰه ﷺ قال: «أيما رجل أعمر عمرى له ولعقبه فإنما هي للذي أُعطيها، لا ترجع إلى الذي أعطاه، لأنه أعطى عطاءً وقعت فيه المواريث»."],"takhrij":"صحيح: رواه مالك (٤٥) ومسلم (١٦٢٥).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (45) and Muslim (1625).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Messenger of Allāh ﷺ said: “Any man who grants an ʿumrā to another person and to his descendants, it belongs to the one to whom it was given. It does not return to the one who gave it, because he has made a gift in which inheritance has taken effect.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":45},{"key":"muslim","label":"مسلم","number":1625}]},{"num":6020,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه الأنصاري أن رسول اللّه ﷺ قال: «أيما رجل أعمر رجلًا عمرى له ولعقبه، فقال: قد أعطيتكها وعقبك ما بقي منكم أحد، فإنها لمن أُعطيها، وإنها لا ترجع إلى صاحبها من أجل أنه أعطى عطاءً وقعت فيه المواريث»."],"takhrij":"صحيح: رواه مسلم (٢٢: ١٦٢٥).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:22).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh al-Anṣārī reported that the Messenger of Allāh ﷺ said: “Any man who grants another man an ʿumrā for himself and his descendants, saying, ‘I have given it to you and to your descendants for as long as any of you remains,’ then it belongs to the one to whom it was given and does not return to its original owner, because he gave a gift in which inheritance has taken effect.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":22}]},{"num":6021,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: قال رسول اللّٰه ﷺ: «أمسكوا عليكم أموالكم، ولا تعطوها أحدًا، فمن أعمر شيئًا فهو له»."],"takhrij":"صحيح: رواه الإمام أحمد (١٤١٢٦)، ورواه مسلم (٢٧: ١٦٢٥) مختصرًا.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (14126), and Muslim (1625:27) in an abbreviated form.","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said that the Messenger of Allāh ﷺ said: “Keep possession of your wealth and do not give it away. Whoever grants something as an ʿumrā, then it belongs to the one to whom it was granted.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":14126},{"key":"muslim","label":"مسلم","number":27},{"key":"ahmad","label":"مسند الإمام أحمد","number":14126,"n":14126}]},{"num":6022,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: قال رسول اللّٰه ﷺ: «أمسكوا عليكم أموالكم، ولا تفسدوها، فإنه من أُعمر عُمرى فهي للذي أعمرها حيًا وميتًا ولعقبه»."],"takhrij":"صحيح: رواه مسلم (٢٦: ١٦٢٥).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:26).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said that the Messenger of Allāh ﷺ said: “Keep your wealth and do not dispose of it in a way that causes you to lose it. For whoever is granted an ʿumrā, it belongs to the person to whom it was granted during his lifetime and after his death, and then to his descendants.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":26}]},{"num":6023,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أن رسول اللّٰه ﷺ قضى فيمن أُعمر عُمْرى له ولعقبه فهي له بَتْلة، لا يجوز للمعطي فيها شرط ولا ثنيا."],"takhrij":"صحيح: رواه مسلم (٢٤: ١٦٢٥). وقوله: «بتلة» أي عطية ماضية غير راجعة إلى الواهب.","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:24).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Messenger of Allāh ﷺ ruled that when a person is granted an ʿumrā for himself and his descendants, it belongs to him absolutely, and the giver may not attach any condition or exception to it."]},"buhuth":{"en":["His saying, “batlah” means an irrevocable gift that has taken effect and does not return to the giver."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":24}]},{"num":6024,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: سمعت رسول اللّٰه ﷺ قال: «من أعمر رجلًا عمرى له ولعقبه فقد قطع قوله حقه فيها، وهي لمن أُعمر ولعقبه»."],"takhrij":"صحيح: رواه مسلم (٢١: ١٦٢٥).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:21).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: “I heard the Messenger of Allāh ﷺ say: ‘Whoever grants a man an ʿumrā for himself and his descendants has, by his own statement, cut off his own right to it. It belongs to the one to whom it was granted and to his descendants.’”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21}]},{"num":6025,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: أعمرت امرأة بالمدينة حائطًا لها ابنًا لها، ثم توفي، وتوفيت بعده، وتركت ولدًا، وله إخوة بنون للمعمرة، فقال ولد المعمرة: رجع الحائط إلينا. وقال بنو المعمر: بل كان لأبينا حياته وموته. فاختصموا إلى طارق مولى عثمان، فدعا جابرًا، فشهد على رسول اللّٰه ﷺ بالعمرى لصاحبها، فقضى بذلك طارق، ثم كتب إلى عبد الملك، فأخبره ذلك، وأخبره بشهادة جابر، فقال عبد الملك: صدق جابر. فأمضى ذلك طارق، فإن ذلك الحائط لبني المعمر حتى اليوم."],"takhrij":"صحيح: رواه مسلم (٢٨: ١٦٢٥).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:28).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: “A woman in Madīnah granted a garden of hers as an ʿumrā to one of her sons. He later died leaving children, and she died after him. The deceased grantee also had brothers who were sons of the woman who had made the grant.","“The brothers of the deceased grantee said, ‘The garden has returned to us.’","“The sons of the man who had received the ʿumrā said, ‘Rather, it belonged to our father during his life and after his death.’","“They brought their dispute before Ṭāriq, the freedman of ʿUthmān. He summoned Jābir, who testified concerning the ruling of the Messenger of Allāh ﷺ that the ʿumrā belongs to its recipient.","“Ṭāriq ruled accordingly, then wrote to ʿAbd al-Malik informing him of the case and of Jābir’s testimony. ʿAbd al-Malik said, ‘Jābir has spoken the truth.’","“Ṭāriq therefore upheld the ruling, and that garden has remained with the descendants of the recipient of the ʿumrā until today.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":28}]},{"num":6026,"demo":false,"sanad":"","matn":["عن سليمان بن يسار أن طارقًا قضى بالعمرى للوارث لقول جابر بن عبد اللّٰه عن رسول اللّه ﷺ."],"takhrij":"صحيح: رواه مسلم (٢٩: ١٦٢٥).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:29).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Sulaymān ibn Yasār reported that Ṭāriq ruled that an ʿumrā passes to the heir, based on what Jābir ibn ʿAbdullāh narrated from the Messenger of Allāh ﷺ."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":29}]},{"num":6027,"demo":false,"sanad":"","matn":["عن جابر عن النبي ﷺ قال: «العمرى ميراث لأهلها»."],"takhrij":"صحيح: رواه مسلم (٣١: ١٦٢٥).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:31).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir reported that the Prophet ﷺ said: “ʿUmrā is an inheritance for its people.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":31}]},{"num":6028,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن النبي ﷺ قال: «لا ترقبوا، ولا تعمروا، فمن أرقب شيئًا أو أعمره فهو لورثته»."],"takhrij":"صحيح: رواه أبو داود (٣٥٥٦)، والنسائي (٣٧٣١)، والبيهقي في الكبرى (١٧٥/٦).","grade":"صحيح","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3556), al-Nasāʾī (3731), and al-Bayhaqī in al-Kubrā (6/175).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Prophet ﷺ said: “Do not make grants by way of ruqbā, and do not make grants by way of ʿumrā. Whoever grants something as a ruqbā or an ʿumrā, it belongs to the heirs of the one to whom it was granted.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3556},{"key":"nasai","label":"النسائي","number":3731},{"key":"البیہقی/الکبری","label":"البيهقي في الكبرى","number":175}]},{"num":6029,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: «العمرى جائزة»."],"takhrij":"متفق عليه: رواه البخاري (٢٦٢٦)، ومسلم (١٦٢٦).","grade":"متفق عليه","chapter_ar":"باب العمرى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2626) and Muslim (1626).","chapter_en":"ʿUmrā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “ʿUmrā is valid.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2626},{"key":"muslim","label":"مسلم","number":1626}]},{"num":6030,"demo":false,"sanad":"","matn":["عن جابر قال: إنما العمرى التي أجاز رسول اللّٰه ﷺ أن يقول: هي لك ولعقبك. فأما إذا قال: هي لك ما عشت، فإنها ترجع إلى صاحبها. قال معمر: وكان الزهري يفتي به."],"takhrij":"صحيح: رواه مسلم (٢٣: ١٦٢٥).","grade":"صحيح","chapter_ar":"باب من قال: هي ترجع إلى الواهب إذا لم يقل: هي لك ولعقبك","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1625:23).","chapter_en":"The View That It Returns to the Giver If He Does Not Say, “It Is Yours and Your Descendants’”","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Jābir said: “The ʿumrā that the Messenger of Allāh ﷺ declared valid is when a person says, ‘It is yours and belongs to your descendants.’ But if he says, ‘It is yours for as long as you live,’ then it returns to its original owner.”","Maʿmar said: “Al-Zuhrī used to issue legal rulings according to this.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":23}]},{"num":6031,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول اللّٰه ﷺ: «العمرى جائزة لأهلها، والرقبى جائزة لأهلها»."],"takhrij":"صحيح: رواه أبو داود (٣٥٥٨)، والترمذي (١٣٥١) وحسنه، وابن ماجه (٢٣٨٣)، والنسائي (٣٧٣٩).","grade":"صحيح","chapter_ar":"باب ما جاء في الرقبى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3558), al-Tirmidhī (1351), who graded it Hasan, Ibn Mājah (2383), and al-Nasāʾī (3739).","chapter_en":"What Has Been Reported Concerning Ruqbā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Jābir reported that the Messenger of Allāh ﷺ said: “ʿUmrā is valid for its recipients, and ruqbā is valid for its recipients.”"]},"buhuth":{"ar":["والرقبى: هي أن يجعلها الرجل على أن أيهما مات أولًا كان للآخر منهما، فكل واحد منهما يرقب موت صاحبه."],"en":["Ruqbā is when a person grants property on the condition that whichever of the two parties dies first, the property will belong to the other. Thus each of them waits for and watches for the death of the other."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3558},{"key":"tirmidhi","label":"الترمذي","number":1351},{"key":"ibnmajah","label":"ابن ماجه","number":2383},{"key":"nasai","label":"النسائي","number":3739}]},{"num":6032,"demo":false,"sanad":"","matn":["عن زيد بن ثابت قال: قال رسول اللّٰه ﷺ: «من أعمر شيئًا فهو لمعمره محياه ومماته، ولا ترقبوا، فمن أرقب شيئًا فهو سبيله»."],"takhrij":"حسن: رواه أبو داود (٣٥٥٩) والنسائي (٣٧١٨)، وابن ماجه (٢٣٨١)، وأحمد (٢١٥٨٦).","grade":"حسن","chapter_ar":"باب ما جاء في الرقبى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3559), al-Nasāʾī (3718), Ibn Mājah (2381), and Aḥmad (21586).","chapter_en":"What Has Been Reported Concerning Ruqbā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Zayd ibn Thābit reported that the Messenger of Allāh ﷺ said: “Whoever grants something as an ʿumrā, it belongs to the one to whom it was granted during his life and after his death. And do not make ruqbā grants; whoever grants something as a ruqbā, then it follows that course.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3559},{"key":"nasai","label":"النسائي","number":3718},{"key":"ibnmajah","label":"ابن ماجه","number":2381},{"key":"ahmad","label":"أحمد","number":21586}]},{"num":6033,"demo":false,"sanad":"","matn":["عن ابن عمر قال: نهى رسول اللّٰه ﷺ عن الرقبى وقال: «من أرقب رقبى فهو له»."],"takhrij":"صحيح: رواه النسائي (٣٧٣٤) - واللفظ له -، وأحمد (٤٨٠١).","grade":"صحيح","chapter_ar":"باب ما جاء في الرقبى","chapter_ur":"","part_ar":"كتاب الهبة، والهدية، والعمرى، والرقبى","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (3734)—and this is his wording—and Aḥmad (4801).","chapter_en":"What Has Been Reported Concerning Ruqbā","part_en":"The Book of Gifts, Presents, ʿUmrā, and Ruqbā","group_ar":"","group_en":"","part_no":20,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Ibn ʿUmar said: “The Messenger of Allāh ﷺ prohibited ruqbā and said: ‘Whoever grants something as a ruqbā, then it belongs to the one to whom it was granted.’”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3734},{"key":"ahmad","label":"مسند الإمام أحمد","number":4801,"n":4801}]},{"num":6034,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله يقول: مرضت فعادني رسول اللّٰه ﷺ وأبو بكر، وهما ماشيان، فأتاني، وقد أغمي علي، فتوضأ رسول اللّٰه ﷺ، فصب عليَّ وضوءه، فأفقت، فقلت: يا رسول الله، كيف أصنع في مالي؟ كيف أقضي في مالي؟ فلم يجبني بشيء حتى نزلت آية الميراث."],"takhrij":"صحيح: رواه البخاري (٦٧٢٣)، ومسلم (١٦١٦).","grade":"صحيح","chapter_ar":"باب ما جاء في نزول آية الميراث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6723) and Muslim (1616).","chapter_en":"What has been narrated regarding the revelation of the verse of inheritance","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: I became ill, and the Messenger of Allah ﷺ and Abu Bakr came walking to visit me. He came to me while I was unconscious. The Messenger of Allah ﷺ performed ablution, then poured some of his ablution water over me, and I regained consciousness. I said, “O Messenger of Allah ﷺ, what should I do regarding my wealth? How should I dispose of my wealth?” He did not answer me at all until the verse of inheritance was revealed."]},"intro":{"ar":["قال اللّٰه تعالى:","يُوصِيكُمُ ٱللَّهُ فِيٓ أَوْلَٰدِكُمْ ۖ لِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۚ فَإِن كُنَّ نِسَآءً فَوْقَ ٱثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ ۖ وَإِن كَانَتْ وَٰحِدَةً فَلَهَا ٱلنِّصْفُ ۚ وَلِأَبَوَيْهِ لِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُ وَلَدٌ ۚ فَإِن لَّمْ يَكُن لَّهُ وَلَدٌ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُ ۚ فَإِن كَانَ لَهُۥٓ إِخْوَةٌ فَلِأُمِّهِ ٱلسُّدُسُ ۚ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِي بِهَآ أَوْ دَيْنٍ ۗ ءَابَآؤُكُمْ وَأَبْنَآؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا ۚ فَرِيضَةً مِّنَ ٱللَّهِ ۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا ۝ وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَٰجُكُمْ إِن لَّمْ يَكُن لَّهُنَّ وَلَدٌ ۚ فَإِن كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكْنَ مِنۢ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَآ أَوْ دَيْنٍ ۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكْتُمْ إِن لَّمْ يَكُن لَّكُمْ وَلَدٌ ۚ فَإِن كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكْتُم مِّنۢ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَآ أَوْ دَيْنٍ ۗ وَإِن كَانَ رَجُلٌ يُورَثُ كَلَٰلَةً أَوِ ٱمْرَأَةٌ وَلَهُۥٓ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَٰحِدٍ مِّنْهُمَا ٱلسُّدُسُ ۚ فَإِن كَانُوٓا۟ أَكْثَرَ مِن ذَٰلِكَ فَهُمْ شُرَكَآءُ فِي ٱلثُّلُثِ مِنۢ بَعْدِ وَصِيَّةٍ يُوصَىٰ بِهَآ أَوْ دَيْنٍ غَيْرَ مُضَآرٍّ ۚ وَصِيَّةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَلِيمٌ","[سورة النساء: ١١-١٢]"],"en":["Allah the Most High said:","“Allah instructs you concerning your children: for the male is the portion of two females. But if there are only daughters, two or more, then for them is two-thirds of what he leaves. If there is only one, then for her is half. And for his parents, for each one of them is one-sixth of what he leaves if he had a child. But if he had no child and his parents inherit from him, then for his mother is one-third. But if he had siblings, then for his mother is one-sixth, after any bequest he may have made or debt. Your parents and your children—you do not know which of them are nearest to you in benefit. This is an obligation from Allah. Indeed, Allah is All-Knowing, All-Wise. And for you is half of what your wives leave if they have no child. But if they have a child, then for you is one-fourth of what they leave, after any bequest they may have made or debt. And for them is one-fourth of what you leave if you have no child. But if you have a child, then for them is one-eighth of what you leave, after any bequest you may have made or debt. And if a man or a woman leaves neither ascendants nor descendants, but has a brother or a sister, then for each one of them is one-sixth. But if they are more than that, then they share in one-third, after any bequest that may have been made or debt, without causing harm. This is an instruction from Allah, and Allah is All-Knowing, Forbearing.”","[Surat al-Nisa’: 11–12]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6723},{"key":"muslim","label":"مسلم","number":1616}]},{"num":6035,"demo":false,"sanad":"","matn":["عن معدان بن أبي طلحة:","أن عمر بن الخطاب خطب يوم الجمعة، فذكر نبي الله ﷺ، وذكر أبا بكر، ثم قال:","إني رأيت كأن ديكًا نقرني ثلاث نقرات، وإني لا أراه إلا حضور أجلي، وإن أقوامًا يأمرونني أن أستخلف، وإن الله لم يكن ليضيع دينه، ولا خلافته، ولا الذي بعث به نبيه ﷺ.","فإن عجل بي أمر فالخلافة شورى بين هؤلاء الستة الذين توفي رسول الله ﷺ وهو عنهم راض.","وإني قد علمت أن أقوامًا يطعنون في هذا الأمر، أنا ضربتهم بيدي هذه على الإسلام، فإن فعلوا ذلك فأولئك أعداء الله الكفرة الضلال.","ثم إني لا أدع بعدي شيئًا أهم عندي من الكلالة. ما راجعت رسول الله ﷺ في شيء ما راجعته في الكلالة، وما أغلظ لي في شيء ما أغلظ لي فيه، حتى طعن بإصبعه في صدري، فقال:","«يَا عُمَرُ، أَلَا تَكْفِيكَ آيَةُ الصَّيْفِ الَّتِي فِي آخِرِ سُورَةِ النِّسَاءِ؟»","وإني إن أعش أقض فيها بقضية يقضي بها من يقرأ القرآن ومن لا يقرأ القرآن.","ثم قال:","اللهم إني أشهدك على أمراء الأمصار، وإني إنما بعثتهم عليهم ليعدلوا عليهم، وليعلموا الناس دينهم وسنة نبيهم ﷺ، ويقسموا فيهم فيئهم، ويرفعوا إلي ما أشكل عليهم من أمرهم.","ثم إنكم أيها الناس تأكلون شجرتين لا أراهما إلا خبيثتين: هذا البصل والثوم. لقد رأيت رسول الله ﷺ إذا وجد ريحهما من الرجل في المسجد أمر به فأخرج إلى البقيع، فمن أكلهما فليمتهما طبخًا."],"takhrij":"صحيح: رواه مسلم (٥٦٧).","grade":"صحيح","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (567).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Maʿdān ibn Abī Ṭalḥah reported that ʿUmar ibn al-Khaṭṭāb delivered a sermon on Friday. He mentioned the Prophet of Allah ﷺ and Abū Bakr, then said:","“I saw in a dream as though a rooster pecked me three times, and I understand this to mean that my death is near. Some people are urging me to appoint a successor, but Allah will not allow His religion, His caliphate, or that with which He sent His Prophet ﷺ to be lost.","If death overtakes me soon, then the caliphate is to be decided by consultation among these six men with whom the Messenger of Allah ﷺ was pleased when he died.","I know that some people will criticize this matter—people whom I struck with this very hand for the sake of Islam. If they do so, then they are the enemies of Allah, disbelievers and misguided.","I leave behind nothing that concerns me more than the matter of kalālah. I never repeatedly questioned the Messenger of Allah ﷺ about anything as much as I questioned him about kalālah, and he was never as stern with me concerning anything as he was concerning it, until he poked me in the chest with his finger and said:","‘O ʿUmar, is the summer verse at the end of Sūrat al-Nisāʾ not sufficient for you?’","If I live, I will issue a ruling concerning it by which both the one who reads the Qurʾān and the one who does not read it will be able to judge.”","Then he said:","“O Allah, I call You to witness concerning the governors of the provinces. I sent them over the people only so that they would deal justly with them, teach them their religion and the Sunnah of their Prophet ﷺ, distribute their public wealth among them, and refer back to me whatever matters were unclear to them.","O people, you eat two plants that I consider foul: onions and garlic. I saw the Messenger of Allah ﷺ, when he detected their smell from a man in the mosque, order that he be taken out to al-Baqīʿ. Whoever eats them should remove their odor by cooking them.”"]},"buhuth":{"ar":["وقوله: «آية الصيف» معناه: الآية التي نزلت في الصيف.","قال الواحدي: أنزل الله في الكلالة آيتين: إحداهما في الشتاء، وهي التي في أول النساء، والأخرى في الصيف، وهي التي في آخرها."],"en":["“The summer verse” means the verse that was revealed during the summer.","Al-Wāḥidī said: Allah revealed two verses concerning kalālah: one in winter, which is near the beginning of Sūrat al-Nisāʾ, and the other in summer, which is at its end."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":567}]},{"num":6036,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب أنه سأل رسول اللّٰه ﷺ عن الكلالة؟ فقال له رسول اللّٰه ﷺ: (( يكفيك من ذلك الآية التي أنزلت في الصيف، آخر سورة النساء ))."],"takhrij":"صحيح: رواه مالك (٧).","grade":"صحيح","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (7).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["‘Umar ibn al-Khattab narrated that he asked the Messenger of Allah ﷺ about al-kalalah, so the Messenger of Allah ﷺ said to him: “The verse that was revealed in the summer at the end of Surat al-Nisa’ is sufficient for you concerning that.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":7}]},{"num":6037,"demo":false,"sanad":"","matn":["عن البراء قال: آخر سورة نزلت: (براءة)، وآخر آية نزلت: يَسْتَفْتُونَكَ."],"takhrij":"متفق عليه: رواه البخاري (٤٦٠٥)، ومسلم (١٦١٨).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4605) and Muslim (1618).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Bara’ said: The last surah to be revealed was Bara’ah, and the last verse to be revealed was: “They ask you for a legal ruling…”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4605},{"key":"muslim","label":"مسلم","number":1618}]},{"num":6038,"demo":false,"sanad":"","matn":["عن البراء بن عازب قال: جاء رجل إلى النبي ﷺ، فقال: يا رسول الله، يستفتونك في الكلالة فما الكلالة؟ قال: (( تجزيك آية الصيف ))."],"takhrij":"حسن: رواه أبو داود (٢٨٨٩)، والترمذي (٣٠٤٢)، وأحمد (١٨٦٠٧، ١٨٥٨٩).","grade":"حسن","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (2889), al-Tirmidhi (3042), and Ahmad (18607, 18589).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib said: A man came to the Prophet ﷺ and said, “O Messenger of Allah ﷺ, they ask you for a ruling concerning al-kalalah—what is al-kalalah?” He said: “The summer verse is sufficient for you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2889},{"key":"tirmidhi","label":"الترمذي","number":3042},{"key":"ahmad","label":"مسند الإمام أحمد","number":18607,"n":18607}]},{"num":6039,"demo":false,"sanad":"","matn":["عن جابر قال: اشتكيت وعندي سبع أخوات، فدخل علي رسول اللّٰه ﷺ، فنفخ في وجهي، فأفقت، فقلت: يا رسول الله، ألا أوصي لأخواتي بالثلث؟ قال: (( أحسن )). قلت: الشطر؟ قال: (( أحسن )). ثم خرج وتركني. فقال: (( يا جابر، لا أراك ميتًا من وجعك هذا، وإن الله قد أنزل، فبيَّن لأخواتك، فجعل لهن الثلثين )). قال: فكان جابر يقول: أنزلت هذه الآية فيَّ:","يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِي ٱلْكَلَٰلَةِ ۚ إِنِ ٱمْرُؤٌا۟ هَلَكَ لَيْسَ لَهُۥ وَلَدٌ وَلَهُۥٓ أُخْتٌ فَلَهَا نِصْفُ مَا تَرَكَ ۚ وَهُوَ يَرِثُهَآ إِن لَّمْ يَكُن لَّهَا وَلَدٌ ۚ فَإِن كَانَتَا ٱثْنَتَيْنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَ ۚ وَإِن كَانُوٓا۟ إِخْوَةً رِّجَالًا وَنِسَآءً فَلِلذَّكَرِ مِثْلُ حَظِّ ٱلْأُنثَيَيْنِ ۗ يُبَيِّنُ ٱللَّهُ لَكُمْ أَن تَضِلُّوا۟ ۗ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ","[سورة النساء: ١٧٦]"],"takhrij":"صحيح: رواه أبو داود (٢٨٨٧).","grade":"صحيح","chapter_ar":"باب ما جاء في الكلالة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2887).","chapter_en":"What has been narrated regarding al-kalalah","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Jabir said: I fell ill, and I had seven sisters. The Messenger of Allah ﷺ came to me and blew on my face, so I regained consciousness. I said, “O Messenger of Allah ﷺ, should I make a bequest of one-third for my sisters?” He said: “Do good.” I said: “Half?” He said: “Do good.” Then he left me and said: “O Jabir, I do not think you will die from this illness of yours, and Allah has revealed and clarified the matter of your sisters, making for them two-thirds.” Jabir used to say: This verse was revealed concerning me:","“They ask you for a legal ruling. Say: Allah gives you a ruling concerning one who leaves neither ascendants nor descendants. If a man dies leaving no child but has a sister, then for her is half of what he left. And he inherits from her if she has no child. But if there are two sisters, then for them is two-thirds of what he left. And if they are siblings, men and women, then for the male is the share of two females. Allah makes this clear to you so that you do not go astray, and Allah is Knowing of all things.”","[Surat al-Nisa’: 176]"]},"buhuth":{"ar":["والكلالة: قال أكثر الصحابة: من لا ولد، ولا والد. وقيل: من لا ولد له."],"en":["Al-kalalah: Most of the Companions said it refers to the one who leaves neither child nor parent. It was also said: the one who leaves no child."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2887}]},{"num":6040,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس قال: قال رسول الله ﷺ:","«أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا، فَمَا بَقِيَ فَهُوَ لِأَوْلَى رَجُلٍ ذَكَرٍ»."],"takhrij":"متفق عليه: رواه البخاري (٦٧٣٢)، ومسلم (١٦١٥).","grade":"متفق عليه","chapter_ar":"باب في ميراث العصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6732) and Muslim (1615).","chapter_en":"Regarding the inheritance of agnatic heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allah ﷺ said:","“Give the prescribed shares to those who are entitled to them, and whatever remains goes to the nearest male relative.”"]},"buhuth":{"ar":["قوله: «ألحقوا الفرائض بأهلها» أي: أعطوا ذوي السهام سهامهم.","وقوله: «لأولى رجل» أي: لأقرب رجل، والمراد قرب النسب."],"en":["“Give the prescribed shares to those entitled to them” means: give the holders of the fixed inheritance shares their allotted portions.","“The nearest male relative” means the male relative who is closest in lineage."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6732},{"key":"muslim","label":"مسلم","number":1615}]},{"num":6041,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس قال: قال رسول اللّٰه ﷺ: (( اقسموا المال بين أهل الفرائض على كتاب الله، فما تركت الفرائض فلأولى رجل ذكر ))."],"takhrij":"صحيح: رواه مسلم (٤ :١٦١٥).","grade":"صحيح","chapter_ar":"باب في ميراث العصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1615/4).","chapter_en":"Regarding the inheritance of agnatic heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas said: The Messenger of Allah ﷺ said: “Distribute the wealth among those entitled to the fixed shares according to the Book of Allah, and whatever the fixed shares leave, it goes to the nearest male agnatic heir.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":4}]},{"num":6042,"demo":false,"sanad":"","matn":["عن أبي هريرة أنه قال: قضى رسول اللّٰه ﷺ في جنين امرأة من بني لحيان سقط ميتًا بغرة: عبد أو أمة، ثم إن المرأة التي قضى عليها بالغرة توفيت، فقضى رسول اللّٰه ﷺ بأن ميراثها لبنيها وزوجها، وأن العقل على عصبتها."],"takhrij":"متفق عليه: رواه البخاري (٦٧٤٠)، ومسلم (٣٥ :١٦٨١).","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الأموال للورثة، والعقل على العصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6740) and Muslim (1681/35).","chapter_en":"What has been narrated that wealth belongs to the heirs, while blood-money liability is upon the agnatic relatives","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ ruled concerning the fetus of a woman from Banu Lihyan that was miscarried dead that its compensation was a male or female slave. Then the woman against whom the compensation had been ruled died, so the Messenger of Allah ﷺ ruled that her inheritance belonged to her children and her husband, while the blood-money liability was upon her agnatic relatives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6740},{"key":"muslim","label":"مسلم","number":35}]},{"num":6043,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ كان يؤتى بالرجل الميت عليه الدين، فيسأل: (( هل ترك لدينه من قضاء؟ )) فإن حدث أنه ترك وفاءً صلى عليه، وإلا قال: (( صلوا على صاحبكم )). فلما فتح اللّٰه عليه الفتوح قال: (( أنا أولى بالمؤمنين من أنفسهم، فمن توفي وعليه دين فعلي قضاؤه، ومن ترك مالا فهو لورثته ))."],"takhrij":"متفق عليه: رواه البخاري (٢٢٩٨)، ومسلم (١٦١٩).","grade":"متفق عليه","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2298) and Muslim (1619).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated that when a deceased man who owed debt was brought to the Messenger of Allah ﷺ, he would ask: “Has he left anything with which his debt can be paid?” If he was told that he had left enough to repay it, he would pray over him. Otherwise, he would say: “Pray over your companion.” Then when Allah granted him conquests, he said: “I am closer to the believers than their own selves. So whoever dies owing a debt, its repayment is upon me; and whoever leaves wealth, it belongs to his heirs.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2298},{"key":"muslim","label":"مسلم","number":1619}]},{"num":6044,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( من ترك مالا فلورثته، ومن ترك كلا فإلينا )). وفي رواية: (( ومن ترك كلا فإليَّ أو عليَّ ))."],"takhrij":"متفق عليه: رواه البخاري (٢٣٩٨)، ومسلم (١٧ : ١٦١٩).","grade":"متفق عليه","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2398) and Muslim (1619/17).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “Whoever leaves behind wealth, it belongs to his heirs; and whoever leaves behind dependents with no one to provide for them, then they are for us.” In another wording: “And whoever leaves behind dependents, then they are upon me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2398},{"key":"muslim","label":"مسلم","number":17}]},{"num":6045,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( ما من مؤمن إلا وأنا أولى به في الدنيا والآخرة، اقرؤوا إن شئتم: ٱلنَّبِيُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ [سورة الأحزاب: ٦]، فأيما مؤمن مات وترك مالا فليرثه عصبته من كانوا، ومن ترك دينا أو ضياعا فليأتني فأنا مولاه ))."],"takhrij":"صحيح: رواه البخاري (٢٣٩٩).","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2399).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “There is no believer except that I am closer to him in this world and the Hereafter. Recite, if you wish: ‘The Prophet is closer to the believers than their own selves’ [Surat al-Ahzab: 6]. So whichever believer dies and leaves wealth, let his relatives inherit him, whoever they may be. And whoever leaves behind debt or dependents in need, let them come to me, for I am his guardian.”"]},"buhuth":{"ar":["قوله: (( فليرثه عصبته )) أي الورثة، لا من يرث بالتعصيب فقط.","والمراد بالعصبة هنا قرابة الرجل، وهم من يلتقون مع الميت في أبٍ ولو علا، وسموا بذلك لأنهم يحيطون به."],"en":["His statement, “let his ‘asabah inherit him,” means his heirs generally, not only those who inherit through agnatic succession in the technical sense.","What is meant by ‘asabah here is a man’s relatives on the father’s side, those connected to the deceased through a male ancestor, near or far. They are called that because they surround and support him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2399}]},{"num":6046,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( أنا أولى بالمؤمنين من أنفسهم، فمن مات وترك مالا فماله لموالي العصبة، ومن ترك كلا أو ضياعا فأنا وليه فلأُدعى له ))."],"takhrij":"صحيح: رواه البخاري (٦٧٤٥).","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6745).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I am closer to the believers than their own selves. So whoever dies and leaves wealth, then his wealth belongs to his agnatic heirs. And whoever leaves behind dependents or helpless family members, then I am his guardian, so let me be called for him.”"]},"buhuth":{"ar":["وقوله: (( ضياعا )) أي ضائعين لا شيء لهم، فأنا أتولى أمرهم وأعولهم."],"en":["His statement, “dependents,” means needy people left behind with nothing, and I take charge of them and provide for them."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6745}]},{"num":6047,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: (( والذي نفس محمد بيده، إن على الأرض من مؤمن إلا أنا أولى الناس به، فأيكم ما ترك دينا أو ضياعا فأنا مولاه، وأيكم ترك مالا فإلى العصبة من كان ))."],"takhrij":"صحيح: رواه مسلم (١٥ : ١٦١٩).","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1619/15).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “By the One in whose hand is Muhammad’s soul, there is no believer on the face of the earth except that I am the closest of people to him. So whichever of you leaves behind debt or dependents, then I am his guardian; and whichever of you leaves behind wealth, then it goes to his agnatic heirs, whoever they may be.”"]},"buhuth":{"ar":["وقوله: (( إن على الأرض من مؤمن )) أي ما على الأرض من مؤمن، فـ(إن) هنا نافية، و(من) زائدة لتأكيد العموم.","وقوله: (( ضياعا )) أي أولادا أو عيالا محتاجين، لا شيء لهم."],"en":["His statement, “there is no believer on the earth,” means: there is not on the earth any believer. The particle here is used in the sense of negation, and “min” is added to emphasize universality.","And “dependents” means children or family members in need who have nothing."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":15}]},{"num":6048,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( أنا أولى الناس بالمؤمنين في كتاب اللّٰه عز وجل، فأيكم ما ترك دينا أو ضيعة فادعوني، فأنا وليه، وأيكم ما ترك مالا فليؤثر بماله عصبته من كان ))."],"takhrij":"صحيح: رواه مسلم (١٦ : ١٦١٩).","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1619/16).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I am the closest of people to the believers according to the Book of Allah, Mighty and Majestic. So whichever of you leaves behind debt or needy dependents, call me, for I am his guardian. And whichever of you leaves wealth, let his agnatic heirs inherit his wealth, whoever they may be.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16}]},{"num":6049,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول اللّٰه ﷺ: (( أنا أولى بكل مؤمن من نفسه، من ترك مالا فلأهله، ومن ترك دينا أو ضياعا فإليَّ وعليَّ ))."],"takhrij":"صحيح: رواه مسلم (٤٣ / ٨٦٧).","grade":"صحيح","chapter_ar":"باب من ترك مالا فهو لورثته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (867/43).","chapter_en":"Whoever leaves wealth, it belongs to his heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “I am closer to every believer than his own self. Whoever leaves behind wealth, it is for his family; and whoever leaves behind debt or dependents, then it is upon me and for me to take care of.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":43}]},{"num":6050,"demo":false,"sanad":"","matn":["عن عائشة أن فاطمة عليها السلام بنت النبي ﷺ أرسلت إلى أبي بكر تسأله ميراثها من رسول اللّٰه ﷺ مما أفاء اللّٰه عليه بالمدينة وفَدَك، وما بقي من خمس خيبر، فقال أبو بكر: إن رسول اللّٰه ﷺ قال: (( لا نورث، ما تركنا صدقة، إنما يأكل آل محمد ﷺ في هذا المال ))، وإني والله لا أغير شيئا من صدقة رسول اللّٰه ﷺ عن حالها التي كانت عليها في عهد رسول اللّٰه ﷺ، ولأعملن فيها بما عمل به رسول اللّٰه ﷺ. فأبى أبو بكر أن يدفع إلى فاطمة منها شيئا، فوجدت فاطمة على أبي بكر في ذلك فهجرته، فلم تكلمه حتى توفيت، وعاشت بعد النبي ﷺ ستة أشهر. فلما توفيت دفنها زوجها علي ليلا، ولم يؤذن بها أبا بكر، وصلى عليها، وكان لعلي من الناس وجه حياة فاطمة، فلما توفيت استنكر علي وجوه الناس، فالتمس مصالحة أبي بكر ومبايعته، ولم يكن يبايع تلك الأشهر، فأرسل إلى أبي بكر أن ائتنا، ولا يأتنا أحد معك، كراهية لمحضر عمر. فقال عمر: لا والله، لا تدخل عليهم وحدك. فقال أبو بكر: وما عسيتهم أن يفعلوا بي؟ والله لآتينهم. فدخل عليهم أبو بكر، فتشهد علي، فقال: إنا قد عرفنا فضلك وما أعطاك اللّٰه، ولم ننفس عليك خيرا ساقه اللّٰه إليك، ولكنك استبددت علينا بالأمر، وكنا نرى لقرابتنا من رسول اللّٰه ﷺ نصيبا. حتى فاضت عينا أبي بكر. فلما تكلم أبو بكر قال: والذي نفسي بيده، لقرابة رسول اللّٰه ﷺ أحب إلي أن أصل من قرابتي، وأما الذي شجر بيني وبينكم من هذه الأموال فلم آل فيها عن الخير، ولم أترك أمرا رأيت رسول اللّٰه ﷺ يصنعه فيها إلا صنعته. فقال علي لأبي بكر: موعدك العشية للبيعة. فلما صلى أبو بكر الظهر رقي على المنبر، فتشهد، وذكر شأن علي، وتخلفه عن البيعة، وعذره بالذي اعتذر إليه، ثم استغفر، وتشهد علي، فعظم حق أبي بكر، وحدث أنه لم يحمله على الذي صنع نفاسة على أبي بكر، ولا إنكارا للذي فضله اللّٰه به، ولكنا نرى لنا في هذا الأمر نصيبا، فاستبد علينا، فوجدنا في أنفسنا. فسر بذلك المسلمون، وقالوا: أصبت. وكان المسلمون إلى علي قريبا حين راجع الأمر بالمعروف."],"takhrij":"صحيح: رواه البخاري (٤٢٤٠، ٤٢٤١).","grade":"صحيح","chapter_ar":"باب قول النبي ﷺ: (( لا نورث ما تركنا صدقة ))","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4240, 4241).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah narrated that Fatimah, may Allah be pleased with her, the daughter of the Prophet ﷺ, sent to Abu Bakr asking for her inheritance from the Messenger of Allah ﷺ from what Allah had given him in Madinah, Fadak, and what remained from the fifth of Khaybar. Abu Bakr said: “The Messenger of Allah ﷺ said: ‘We are not inherited from; whatever we leave is charity. The family of Muhammad ﷺ only eat from this wealth.’ By Allah, I will not change anything from the charity of the Messenger of Allah ﷺ from the state it was in during the lifetime of the Messenger of Allah ﷺ, and I will certainly act concerning it as the Messenger of Allah ﷺ acted.” So Abu Bakr refused to hand any of it over to Fatimah. Fatimah felt upset with Abu Bakr over that and kept away from him, and did not speak to him until she died. She lived six months after the Prophet ﷺ. When she died, her husband ‘Ali buried her at night and did not inform Abu Bakr, and he prayed over her. ‘Ali had standing among the people while Fatimah was alive, but when she died, ‘Ali noticed a change in the people’s attitude, so he sought reconciliation with Abu Bakr and to give him the pledge, and he had not done so during those months. He sent to Abu Bakr, “Come to us, but do not bring anyone with you,” because he disliked the presence of ‘Umar. ‘Umar said, “No, by Allah, you should not enter upon them alone.” Abu Bakr said, “What could they possibly do to me? By Allah, I will go to them.” So Abu Bakr entered. ‘Ali recited the testimony and said: “We do recognize your virtue and what Allah has given you, and we do not envy you for any good Allah has brought to you. But you acted independently regarding this matter, while we believed that because of our kinship to the Messenger of Allah ﷺ we had a share in it.” At that Abu Bakr’s eyes overflowed with tears. Then Abu Bakr spoke and said: “By the One in whose hand is my soul, maintaining the kinship of the Messenger of Allah ﷺ is more beloved to me than maintaining my own kinship. As for what arose between me and you regarding these properties, I have not withheld any good in them, nor did I abandon anything I saw the Messenger of Allah ﷺ doing concerning them except that I did the same.” Then ‘Ali said to Abu Bakr: “Your appointment with us for the pledge is this evening.” After Abu Bakr prayed Zuhr, he ascended the pulpit, recited the testimony, mentioned the matter of ‘Ali and his delay in the pledge, and accepted his excuse, then sought forgiveness. ‘Ali also recited the testimony, magnified the right of Abu Bakr, and said that what had prevented him was not jealousy toward Abu Bakr, nor denial of what Allah had granted him, but rather that we believed we had a share in this matter, and it had been decided without us, so we felt something in ourselves. The Muslims were pleased with that and said: “You have done right.” And the Muslims drew close again to ‘Ali when he returned to the matter in the proper way."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4240}]},{"num":6051,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( لا يقسم ورثتي دنانير، ما تركت بعد نفقة نسائي ومؤونة عاملي، فهو صدقة ))."],"takhrij":"متفق عليه: رواه مالك (٢٨)، والبخاري (٦٧٢٩)، ومسلم (١٧٦٠).","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ: (( لا نورث ما تركنا صدقة ))","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (28), al-Bukhari (6729), and Muslim (1760).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “My heirs do not divide dinars. Whatever I leave after the maintenance of my wives and the expenses of my worker is charity.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":28},{"key":"bukhari","label":"البخاري","number":6729},{"key":"muslim","label":"مسلم","number":1760}]},{"num":6052,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: جاءت فاطمة إلى أبي بكر، فقالت: من يرثك؟ قال: أهلي وولدي. قالت: فما لي لا أرث أبي؟ فقال أبو بكر: سمعت رسول اللّٰه ﷺ يقول: (( لا نورث )). ولكني أعول من كان رسول اللّٰه ﷺ يعوله، وأنفق على من كان رسول اللّٰه ﷺ ينفق عليه."],"takhrij":"حسن: رواه الترمذي (١٦٠٨) وحسنه.","grade":"حسن","chapter_ar":"باب قول النبي ﷺ: (( لا نورث ما تركنا صدقة ))","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: narrated by al-Tirmidhi (1608), who graded it Hasan.","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: Fatimah came to Abu Bakr and said, “Who will inherit from you?” He said, “My family and my children.” She said, “Then why do I not inherit from my father?” Abu Bakr said, “I heard the Messenger of Allah ﷺ say: ‘We are not inherited from.’ But I do support those whom the Messenger of Allah ﷺ used to support, and I spend on those upon whom the Messenger of Allah ﷺ used to spend.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1608}]},{"num":6053,"demo":false,"sanad":"","matn":["عن مالك بن أوس بن الحدثان النصري قال:","إن عمر بن الخطاب دعاه، فانطلقت حتى دخلت عليه، فأتاه حاجبه يرفأ، فقال:","هل لك في عثمان وعبد الرحمن والزبير وسعد؟","قال: نعم.","فأذن لهم.","ثم قال:","هل لك في علي وعباس؟","قال: نعم.","قال عباس:","يا أمير المؤمنين، اقض بيني وبين هذا.","قال عمر:","أنشدكم بالله الذي بإذنه تقوم السماء والأرض، هل تعلمون أن رسول الله ﷺ قال:","«لَا نُورَثُ، مَا تَرَكْنَا صَدَقَةٌ».","يريد رسول الله ﷺ نفسه؟","فقال الرهط:","قد قال ذلك.","فأقبل على علي وعباس، فقال:","هل تعلمان أن رسول الله ﷺ قال ذلك؟","قالا:","قد قال ذلك.","قال عمر:","فإني أحدثكم عن هذا الأمر. إن الله قد كان خص رسوله ﷺ في هذا الفيء بشيء لم يعطه أحدًا غيره، فقال عز وجل:","{وَمَا أَفَاءَ اللَّهُ عَلَىٰ رَسُولِهِ مِنْهُمْ فَمَا أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَٰكِنَّ اللَّهَ يُسَلِّطُ رُسُلَهُ عَلَىٰ مَنْ يَشَاءُ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ}  [الحشر: ٦]","فكانت خالصة لرسول الله ﷺ.","والله ما احتازها دونكم، ولا استأثر بها عليكم، لقد أعطاكموها وبثها فيكم حتى بقي منها هذا المال.","فكان النبي ﷺ ينفق على أهله من هذا المال نفقة سنته، ثم يأخذ ما بقي فيجعله مجعل مال الله.","عمل بذلك رسول الله ﷺ حياته.","أنشدكم بالله، هل تعلمون ذلك؟","قالوا:","نعم.","ثم قال لعلي وعباس:","أنشدكما بالله، هل تعلمان ذلك؟","قالا:","نعم.","فتوفى الله نبيه ﷺ، فقال أبو بكر:","أنا ولي رسول الله ﷺ.","فقبضها، فعمل بما عمل به رسول الله ﷺ.","ثم توفى الله أبا بكر، فقلت:","أنا ولي ولي رسول الله ﷺ.","فقبضتها سنتين أعمل فيها بما عمل رسول الله ﷺ وأبو بكر.","ثم جئتماني وكلمتكما واحدة، وأمركما جميع. جئتني تسألني نصيبك من ابن أخيك، وأتاني هذا يسألني نصيب امرأته من أبيها.","فقلت:","إن شئتما دفعتها إليكما بذلك.","فتلتمسان مني قضاء غير ذلك؟","فوالله الذي بإذنه تقوم السماء والأرض، لا أقضي فيها قضاء غير ذلك حتى تقوم الساعة.","فإن عجزتما عنها فادفعاها إلي، فأنا أكفيكماها."],"takhrij":"متفق عليه: رواه البخاري (٤٠٣٣، ٦٧٢٨)، ومسلم (١٧٥٧/٤٩)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ: (( لا نورث ما تركنا صدقة ))","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4033, 6728) and Muslim (1757/49). This is the wording of al-Bukhārī.","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Mālik ibn Aws ibn al-Ḥadathān al-Naṣrī reported:","ʿUmar ibn al-Khaṭṭāb sent for him, so I went and entered upon him. His doorkeeper Yarfaʾ came and said:","“Will you admit ʿUthmān, ʿAbd al-Raḥmān, al-Zubayr, and Saʿd?”","He replied:","“Yes.”","So he admitted them.","Then he said:","“Will you admit ʿAlī and al-ʿAbbās?”","He replied:","“Yes.”","Al-ʿAbbās said:","“O Commander of the Believers, judge between me and this man.”","ʿUmar said:","“I adjure you by Allah, by whose permission the heaven and earth stand: do you know that the Messenger of Allah ﷺ said:","‘We prophets are not inherited from; whatever we leave is charity’?”","The group replied:","“Yes, he said that.”","Then he turned to ʿAlī and al-ʿAbbās and asked:","“Do you both know that the Messenger of Allah ﷺ said this?”","They replied:","“Yes, he said it.”","ʿUmar said:","“I will explain this matter to you. Allah singled out His Messenger ﷺ concerning this fayʾ with something He did not grant to anyone else.”","Then he recited:","“And whatever Allah restored to His Messenger from them—you did not spur any horses or camels against it; rather, Allah gives His messengers authority over whom He wills, and Allah is over all things powerful.” [Surah al-Ḥashr 59:6]","“So it belonged exclusively to the Messenger of Allah ﷺ.","By Allah, he did not keep it from you, nor did he prefer himself over you with it. Rather, he distributed it among you until only this property remained.","The Prophet ﷺ would spend from this property on his family for their yearly maintenance, then take whatever remained and place it where the wealth of Allah was to be placed.","The Messenger of Allah ﷺ did this throughout his lifetime.","I adjure you by Allah, do you know this?”","They replied:","“Yes.”","Then he said to ʿAlī and al-ʿAbbās:","“I adjure you both by Allah, do you know this?”","They replied:","“Yes.”","Then Allah took His Prophet ﷺ, and Abū Bakr said:","‘I am the successor responsible for the property of the Messenger of Allah ﷺ.’","He took possession of it and dealt with it just as the Messenger of Allah ﷺ had dealt with it.","Then Allah took Abū Bakr, and I said:","‘I am the successor of the successor of the Messenger of Allah ﷺ.’","I took possession of it for two years and administered it as the Messenger of Allah ﷺ and Abū Bakr had done.","Then you both came to me with the same claim and a united matter. You came asking for your share from your nephew, while this man came asking for his wife’s share from her father.","I said:","‘If you wish, I will hand it over to you on that condition.’","Are you now asking me for some judgment other than that?","By Allah, by whose permission the heaven and earth stand, I will not issue any ruling concerning it other than this until the Hour is established.","If you are unable to administer it, then return it to me and I will take care of it for you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4033},{"key":"muslim","label":"مسلم","number":1757}]},{"num":6054,"demo":false,"sanad":"","matn":["عن عائشة أن أزواج النبي ﷺ حين توفي رسول اللّٰه ﷺ أردن أن يبعثن عثمان بن عفان إلى أبي بكر الصديق، فيسألنه ميراثهن من رسول اللّٰه ﷺ، فقالت لهن عائشة: أليس قد قال رسول اللّٰه ﷺ: (( لا نورث، ما تركنا فهو صدقة ))؟"],"takhrij":"متفق عليه: رواه مالك (٢٧)، والبخاري (٦٧٣٠)، ومسلم (١٧٥٨).","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ: (( لا نورث ما تركنا صدقة ))","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (27), al-Bukhari (6730), and Muslim (1758).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah narrated that when the Messenger of Allah ﷺ died, the wives of the Prophet ﷺ wanted to send ‘Uthman ibn ‘Affan to Abu Bakr al-Siddiq to ask him for their inheritance from the Messenger of Allah ﷺ. ‘A’ishah said to them: “Did not the Messenger of Allah ﷺ say: ‘We are not inherited from; whatever we leave is charity’?”"]},"buhuth":{"ar":["ورواه أبو داود (٢٩٧٧) من طريق آخر قالت عائشة: ألا تتقين اللّٰه؟ ألم تسمعن رسول اللّٰه ﷺ يقول: (( لا نورث، ما تركنا فهو صدقة، وإنما هذا المال لآل محمد لنائبتهم وضيفهم، فإذا مت فهو إلى ولي الأمر من بعدي ))."],"en":["And Abu Dawud (2977) narrated through another route that ‘A’ishah said: “Will you not fear Allah? Did you not hear the Messenger of Allah ﷺ say: ‘We are not inherited from; whatever we leave is charity. This wealth is only for the family of Muhammad—for their emergent needs and their guests—and when I die it goes to the one in authority after me.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":27},{"key":"bukhari","label":"البخاري","number":6730},{"key":"muslim","label":"مسلم","number":1758}]},{"num":6055,"demo":false,"sanad":"","matn":["عن ابن عباس قال: لما قبض رسول اللّٰه ﷺ، واستخلف أبو بكر، خاصم العباسُ عليًّا في أشياء تركها رسول اللّٰه ﷺ، فقال أبو بكر: شيء تركه رسول اللّٰه ﷺ فلم يحركه فلا أحركه. فلما استخلف عمر اختصما إليه، فقال: شيء لم يحركه أبو بكر فلست أحركه. قال: فلما استخلف عثمان اختصما إليه، قال: فأسكت عثمان ونكس رأسه. قال ابن عباس: فخشيت أن يأخذه، فضربت بيدي بين كتفي العباس، فقلت: يا أبت، أقسمت عليك إلا سلمته لعلي. قال: فسلمه له."],"takhrij":"صحيح: رواه أحمد (٧٧)، وأبو يعلى (٢٦).","grade":"صحيح","chapter_ar":"باب قول النبي ﷺ: (( لا نورث ما تركنا صدقة ))","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (77) and Abu Ya‘la (26).","chapter_en":"The statement of the Prophet ﷺ: “We are not inherited from; whatever we leave is charity.”","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Abbas said: When the Messenger of Allah ﷺ passed away and Abu Bakr became caliph, al-‘Abbas and ‘Ali disputed concerning certain things the Messenger of Allah ﷺ had left. Abu Bakr said, “Anything the Messenger of Allah ﷺ left without changing, I will not change.” Then when ‘Umar became caliph, they brought their dispute to him, and he said, “Anything Abu Bakr did not alter, I will not alter.” Then when ‘Uthman became caliph, they brought the dispute to him. ‘Uthman remained silent and lowered his head. Ibn ‘Abbas said: I feared that he might decide to take it, so I struck al-‘Abbas between his shoulders with my hand and said, “O my father, I adjure you that you hand it over to ‘Ali.” So he handed it over to him."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":26},{"key":"ahmad","label":"مسند الإمام أحمد","number":77,"n":77}]},{"num":6056,"demo":false,"sanad":"","matn":["عن هزيل بن شرحبيل قال: سئل أبو موسى عن ابنة، وابنة ابن، وأخت. فقال: للابنة النصف، وللأخت النصف، وأتِ ابن مسعود، فسيتابعني. فسئل ابن مسعود، وأخبر بقول أبي موسى، فقال: لقد ضللت إذا، وما أنا من المهتدين، أقضي فيها بما قضى النبي ﷺ: للابنة النصف، ولابنة الابن السدس تكملة الثلثين، وما بقي فللأخت. فأتينا أبا موسى، فأخبرناه بقول ابن مسعود، فقال: لا تسألوني ما دام هذا الحبر فيكم."],"takhrij":"صحيح: رواه البخاري (٦٧٣٦).","grade":"صحيح","chapter_ar":"باب ميراث الأخوات مع البنات عصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6736).","chapter_en":"The inheritance of sisters together with daughters as residuary heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Huzayl ibn Shurahbil said: Abu Musa was asked about a daughter, a son’s daughter, and a sister. He said: “The daughter gets one-half, and the sister gets one-half. Go to Ibn Mas‘ud, and he will follow me.” Ibn Mas‘ud was then asked and was informed of Abu Musa’s answer. He said: “Then I would have gone astray and would not be among the rightly guided. I will judge in it as the Prophet ﷺ judged: the daughter gets one-half, the son’s daughter gets one-sixth completing two-thirds, and whatever remains goes to the sister.” So we went to Abu Musa and informed him of Ibn Mas‘ud’s statement, and he said: “Do not ask me while this learned man is among you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6736}]},{"num":6057,"demo":false,"sanad":"","matn":["عن الأسود بن يزيد قال: قضى فينا معاذ بن جبل على عهد رسول اللّٰه ﷺ: النصف للابنة، والنصف للأخت."],"takhrij":"صحيح: رواه البخاري (٦٧٤١).","grade":"صحيح","chapter_ar":"باب ميراث الأخوات مع البنات عصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6741).","chapter_en":"The inheritance of sisters together with daughters as residuary heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: Mu‘adh ibn Jabal judged among us during the lifetime of the Messenger of Allah ﷺ that one-half was for the daughter and one-half was for the sister."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6741}]},{"num":6058,"demo":false,"sanad":"","matn":["عن الأسود بن يزيد قال: أتانا معاذ بن جبل باليمن معلما وأميرا، فسألناه عن رجل توفي، وترك ابنته وأخته، فأعطى الابنة النصف، والأخت النصف."],"takhrij":"صحيح: رواه البخاري (٦٧٣٤).","grade":"صحيح","chapter_ar":"باب ميراث الأخوات مع البنات عصبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6734).","chapter_en":"The inheritance of sisters together with daughters as residuary heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: Mu‘adh ibn Jabal came to us in Yemen as a teacher and a governor. We asked him about a man who died and left behind a daughter and a sister, so he gave the daughter one-half and the sister one-half."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6734}]},{"num":6059,"demo":false,"sanad":"","matn":["عن ابن عمر أن رجلا لاعن امرأته في زمن النبي ﷺ، وانتفى من ولدها، ففرق النبي ﷺ بينهما، وألحق الولد بالمرأة."],"takhrij":"متفق عليه: رواه مالك (٤٠) والبخاري (٦٧٤٩)، ومسلم (١٤٩٤).","grade":"متفق عليه","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (40), al-Bukhari (6749), and Muslim (1494).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar narrated that a man performed li‘ān with his wife during the time of the Prophet ﷺ and denied her child, so the Prophet ﷺ separated them and attributed the child to the woman."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":40},{"key":"bukhari","label":"البخاري","number":6749},{"key":"muslim","label":"مسلم","number":1494}]},{"num":6060,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو بن العاص، عن النبي ﷺ قال: (( ميراث ابن الملاعنة لأمه، ولورثتها من بعدها ))."],"takhrij":"حسن: رواه أبو داود (٢٩٠٨).","grade":"حسن","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2908).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated from the Prophet ﷺ that he said: “The inheritance of the child of li‘ān belongs to his mother and to her heirs after her.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2908}]},{"num":6061,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول اللّٰه ﷺ قال: (( كل مستلحق استلحق بعد أبيه الذي يُدعى له، ادعاه ورثته من بعده، فقضى أن من كان من أمة يملكها يوم أصابها فقد لحق بمن استلحقه، وليس له فيما قسم قبله من الميراث شيء، وما أدرك من ميراث لم يقسم فله نصيبه، ولا يلحق إذا كان أبوه الذي يُدعى له أنكره. وإن كان من أمة لا يملكها، أو من حرة عاهر بها، فإنه لا يلحق، ولا يورث. وإن كان الذي يُدعى له هو ادعاه، فهو ولد زنا، لأهل أمه من كانوا، حرة أو أمة )).","قال محمد بن راشد: يعني بذلك ما قسم في الجاهلية قبل الإسلام."],"takhrij":"حسن: رواه أبو داود (٢٢٦٥)، وابن ماجه (٢٧٤٦)، وأحمد (٧٠٤٢)، والحاكم (٣٤٢/٤)، والبيهقي (٢٦٠/٦).","grade":"حسن","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2265), Ibn Majah (2746), Ahmad (7042), al-Hakim (4/342), and al-Bayhaqi (6/260).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “Any claimed child who is claimed after the death of the man to whom he is attributed, and whose heirs claim him afterward: it is ruled that if he was born from a slave woman whom that man owned on the day he had relations with her, then he is joined to the one who claimed him. But he has no share in any inheritance that was already divided before that, while whatever inheritance he reaches before division, he receives his share of it. He is not joined to him if the father to whom he is attributed had denied him. And if he was from a slave woman he did not own, or from a free woman with whom he committed fornication, then he is not joined to him and does not inherit. And if the man to whom he is attributed himself claims him in such a case, then he is a child of fornication, belonging to the family of his mother, whether she was free or a slave.”","Muhammad ibn Rashid said: This refers to what had been divided in the pre-Islamic period before Islam."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2265},{"key":"ibnmajah","label":"ابن ماجه","number":2746},{"key":"hakim","label":"الحاكم","number":342},{"key":"البیہقی","label":"البيهقي","number":260},{"key":"ahmad","label":"مسند الإمام أحمد","number":7042,"n":7042},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12504,"n":12627}]},{"num":6062,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول الله ﷺ قال: (( أيما رجل عاهر حرة أو أمة فالولد ولد زنا، لا يرث ولا يورث ))."],"takhrij":"حسن: رواه الترمذي (٢١١٣)، وابن ماجه (٢٧٤٥).","grade":"حسن","chapter_ar":"باب ميراث ابن الملاعنة وولد الزنا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2113) and Ibn Majah (2745).","chapter_en":"The inheritance of the child of mutual imprecation and the child of fornication","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “Any man who fornicates with a free woman or a slave woman, then the child is a child of fornication: he neither inherits nor is inherited from.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2113},{"key":"ibnmajah","label":"ابن ماجه","number":2745}]},{"num":6063,"demo":false,"sanad":"","matn":["عن عائشة أن رسول اللّٰه ﷺ قال: (( إنما الولاء لمن أعتق ))."],"takhrij":"متفق عليه: رواه البخاري (٢٥٦١)، ومسلم (٦ : ١٥٠٤).","grade":"متفق عليه","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2561) and Muslim (1504/6).","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah narrated that the Messenger of Allah ﷺ said: “Wala’ belongs only to the one who emancipates.”"]},"buhuth":{"ar":["وقوله: (( الولاء لمن أعتق )) أي أن من أعتق عبدا له، فإن ميراثه له إذا لم يكن له وارث، وأنه عصبة له إذا كان ورثته لا يحيطون بجميع ماله."],"en":["His statement, “Wala’ belongs only to the one who emancipates,” means that whoever frees his slave has the right to inherit from him if the freed person has no heir, and he is treated as his agnatic heir if the legal heirs do not encompass all of his estate."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2561},{"key":"muslim","label":"مسلم","number":6}]},{"num":6064,"demo":false,"sanad":"","matn":["عن أنس، عن النبي ﷺ قال: (( مولى القوم من أنفسهم )) أو كما قال."],"takhrij":"صحيح: رواه البخاري (٦٧٦١)، ورواه مسلم (١٣٣/١٠٥٩) من وجه آخر ولفظه: قال: جمع رسول اللّٰه ﷺ الأنصار، فقال: (( أفيكم أحد من غيركم؟ )) فقالوا: لا، إلا ابن أخت لنا. فقال رسول اللّٰه ﷺ: (( إن ابن أخت القوم منهم )). ثم ذكر بقية الحديث في فضائل الأنصار. وقوله: (( مولى القوم )) أي عتيقهم، ينسب إليهم، ويرثونه.","grade":"صحيح","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6761). Muslim also narrated it through another route (1059/133) with the wording: The Messenger of Allah ﷺ gathered the Ansar and said, “Is there anyone among you who is not from you?” They said, “No, except a son of our sister.” So the Messenger of Allah ﷺ said, “The son of a people’s sister is one of them.” Then he mentioned the rest of the hadith concerning the virtues of the Ansar.","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Anas narrated from the Prophet ﷺ that he said: “The freedman of a people is one of them,” or words to that effect."]},"buhuth":{"en":["And his statement, “the freedman of a people,” means their emancipated slave: he is affiliated with them and they inherit from him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6761},{"key":"muslim","label":"مسلم","number":133}]},{"num":6065,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: تزوج رئاب بن حذيفة بن سعيد بن سهم أم وائل بنت معمر الجمحية، فولدت له ثلاثة، فتوفيت أمهم، فورثها بنوها رباعا وولاء مواليها، فخرج بهم عمرو بن العاص إلى الشام، فماتوا في طاعون عمواس، فورثهم عمرو، وكان عصبتهم. فلما رجع عمرو بن العاص جاء بنو معمر يخاصمونه في ولاء أختهم إلى عمر، فقال عمرو: اقضي بينكم بما سمعت من رسول اللّٰه ﷺ، سمعته يقول: (( ما أحرز الولد والوالد فهو لعصبته من كان )). قال: فقضى لنا به، وكتب لنا به كتابا، فيه شهادة عبد الرحمن بن عوف وزيد بن ثابت وآخر. حتى إذا استخلف عبد الملك بن مروان توفي مولى لها، وترك ألفي دينار، فبلغني أن ذلك القضاء قد غُيِّر. فخاصموا إلى هشام بن إسماعيل، فرفعنا إلى عبد الملك، فأتيناه بكتاب عمر، فقال: إن كنت لأرى أن هذا من القضاء الذي لا يُشك فيه، وما كنت أرى أن أمر أهل المدينة بلغ هذا أن يشكوا في هذا القضاء، فقضى لنا فيه، فلم نزل فيه بعد."],"takhrij":"حسن: رواه أبو داود (٢٩١٧)، وابن ماجه (٢٧٣٢) - واللفظ له.","grade":"حسن","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2917) and Ibn Majah (2732), with the wording being Ibn Majah’s.","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, who said: Ri’ab ibn Hudhayfah ibn Sa‘id ibn Sahm married Umm Wa’il bint Ma‘mar al-Jumahiyyah, and she bore him three children. Then their mother died, so her sons inherited her homes and the wala’ of her freed slaves. ‘Amr ibn al-‘As took them with him to Syria, and they died in the plague of ‘Amwas, so ‘Amr inherited from them, as he was their agnatic relative. When ‘Amr ibn al-‘As returned, the sons of Ma‘mar came disputing with him before ‘Umar regarding the wala’ of their sister. ‘Amr said: “I will judge between you according to what I heard from the Messenger of Allah ﷺ. I heard him say: ‘Whatever is secured by the child and the parent belongs to his agnatic heirs, whoever they may be.’” He said: So he judged in our favor and wrote us a document to that effect, bearing the testimony of ‘Abd al-Rahman ibn ‘Awf, Zayd ibn Thabit, and another. Then when ‘Abd al-Malik ibn Marwan became caliph, one of her freed slaves died and left two thousand dinars, and I was informed that that judgment had been altered. So they brought the dispute to Hisham ibn Isma‘il, and we raised it to ‘Abd al-Malik. We brought him ‘Umar’s written document, and he said: “I had considered this to be among the rulings about which there is no doubt, and I never thought the matter of the people of Madinah had reached the point that they would doubt this ruling.” So he judged in our favor, and it remained so afterward."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2917},{"key":"ibnmajah","label":"ابن ماجه","number":2732}]},{"num":6066,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب قال: سمعت رسول اللّٰه ﷺ يقول: (( يرث الولاء من ورث المال من والد أو ولد ))."],"takhrij":"حسن: رواه أحمد (٣٢٤).","grade":"حسن","chapter_ar":"باب الميراث بالولاء","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (324).","chapter_en":"Inheritance through wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘Umar ibn al-Khattab said: I heard the Messenger of Allah ﷺ say: “The wala’ is inherited by whoever inherits the wealth through a parent or a child.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":324,"n":324}]},{"num":6067,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر: نهى رسول اللّٰه ﷺ عن بيع الولاء، وعن هبته."],"takhrij":"متفق عليه: رواه مالك (٢٠) والبخاري (٢٥٣٥، ٦٧٥٦)، ومسلم (١٥٠٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (2535, 6756), and Muslim (1506).","chapter_en":"The prohibition of selling wala’ or giving it away","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar narrated: The Messenger of Allah ﷺ forbade selling wala’ and forbade giving it away as a gift."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20},{"key":"bukhari","label":"البخاري","number":2535},{"key":"muslim","label":"مسلم","number":1506}]},{"num":6068,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول اللّٰه ﷺ: (( الولاء لحمة كلحمة النسب، لا يباع، ولا يوهب ))."],"takhrij":"صحيح: رواه ابن حبان (٤٩٥٠).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4950).","chapter_en":"The prohibition of selling wala’ or giving it away","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said, “Wala’ is a bond like the bond of lineage: it is neither sold nor given away.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1896,"n":1893}]},{"num":6069,"demo":false,"sanad":"","matn":["عن عائشة أن مولى للنبي ﷺ وقع من نخلة، فمات، وترك مالا، ولم يترك ولدا ولا حميما. فقال النبي ﷺ: (( أعطوا ميراثه رجلا من أهل قريته ))."],"takhrij":"حسن: رواه أبو داود (٢٩٠٢)، والترمذي (٢١٠٥) وحسنه، وابن ماجه (٢٧٣٣).","grade":"حسن","chapter_ar":"باب من مات، وليس له وارث، ولا ذو رحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2902), al-Tirmidhi (2105), who graded it Hasan, and Ibn Majah (2733).","chapter_en":"One who dies leaving neither an heir nor a relative","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah narrated that a freedman of the Prophet ﷺ fell from a palm tree and died, leaving wealth behind, but leaving neither a child nor a close relative. So the Prophet ﷺ said: “Give his inheritance to a man from the people of his village.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2902},{"key":"tirmidhi","label":"الترمذي","number":2105},{"key":"ibnmajah","label":"ابن ماجه","number":2733}]},{"num":6070,"demo":false,"sanad":"","matn":["عن ابن عباس: وَلِكُلٍّ جَعَلْنَا مَوَالِيَ قال: ورثة. وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ كان المهاجرون لما قدموا المدينة يرث المهاجر الأنصاري دون ذوي رحمه، للأخوة التي آخى النبي ﷺ بينهم، فلما نزلت: وَلِكُلٍّ جَعَلْنَا مَوَالِيَ نسخت. ثم قال: وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ من النصر، والرفادة، والنصيحة، وقد ذهب الميراث، ويوصى له."],"takhrij":"صحيح: رواه البخاري (٤٥٨٠).","grade":"صحيح","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4580).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Abbas said regarding the verse: “And for all We have appointed heirs” — meaning: inheritors. And regarding “and those with whom your right hands have made a pact”: when the Emigrants first came to Madinah, the Emigrant used to inherit from the Helper instead of his blood relatives, because of the brotherhood which the Prophet ﷺ established between them. But when the verse “And for all We have appointed heirs” was revealed, that was abrogated. Then he said that “and those with whom your right hands have made a pact” remained in terms of support, assistance, and sincere counsel, while inheritance had ended, though a bequest may still be made to him."]},"buhuth":{"ar":["مدلول: وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ أي الذين تحالفتموهم بالأيمان المؤكدة، فأتوهم نصيبهم من النصرة والرفادة والنصيحة كما وعدتموهم، وقد كان هذا في ابتداء الإسلام ثم نسخ بعد ذلك في الميراث."],"en":["Meaning of the verse “and those with whom your right hands have made a pact”: those with whom you entered into binding alliances by solemn oaths. So give them their due in support, hospitality, and sincere loyalty, as you promised them. This existed at the beginning of Islam, then inheritance through that pact was later abrogated."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4580}]},{"num":6071,"demo":false,"sanad":"","matn":["عن ابن عباس قال: وَٱلَّذِينَ عَقَدَتْ أَيْمَٰنُكُمْ فَـَٔاتُوهُمْ نَصِيبَهُمْ [سورة النساء: ٣٣] كان الرجل يحالف الرجل ليس بينهما نسب، فيرث أحدهما الآخر، فنسخ ذلك الأنفال. قال تعالى: وَأُولُوا ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ [سورة الأنفال: ٧٥]."],"takhrij":"حسن: رواه أبو داود (٢٩٢١).","grade":"حسن","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2921).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Abbas said regarding the verse: “And those with whom your right hands have made a pact, give them their share” [Surat al-Nisa’: 33]: a man used to enter an alliance with another man with no blood relationship between them, and one of them would inherit from the other. This was then abrogated by the verse in Surat al-Anfal: “And blood relatives are nearer to one another” [Surat al-Anfal: 75]."]},"buhuth":{"ar":["فالنسخ هو التوارث بالحلف، وأما التحالف على طاعة اللّٰه ونصر المظلوم والمؤاخاة في اللّٰه فهو أمر مرغوب، وقد جاء الأمر به في الأحاديث الكثيرة."],"en":["So what was abrogated was inheritance through alliance. As for forming pacts for obedience to Allah, helping the oppressed, and brotherhood for Allah’s sake, that remains encouraged, and many hadiths command it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2921}]},{"num":6072,"demo":false,"sanad":"","matn":["عن أنس بن مالك، عن النبي ﷺ قال: (( ابن أخت القوم منهم، أو من أنفسهم ))."],"takhrij":"صحيح: رواه البخاري (٦٧٦٢)، ومسلم (١٠٥٩) من طريق آخر بإسناده قال: جمع رسول اللّٰه ﷺ الأنصار، فقال: (( أفيكم أحد من غيركم؟ )) فقالوا: لا، إلا ابن أخت لنا. فقال رسول اللّٰه ﷺ: (( إن ابن أخت القوم منهم )). ثم ذكر فضائل الأنصار، وهو مذكور في موضعه.","grade":"صحيح","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6762). Muslim (1059) also narrated through another chain that the Messenger of Allah ﷺ gathered the Ansar and said: “Is there anyone among you who is not from you?” They said: “No, except the son of our sister.” So the Messenger of Allah ﷺ said: “The son of a people’s sister is one of them.” Then he mentioned the virtues of the Ansar, and that appears in its proper place.","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik narrated from the Prophet ﷺ that he said: “The son of a people’s sister is one of them,” or “from their own selves.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6762},{"key":"muslim","label":"مسلم","number":1059}]},{"num":6073,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري قال: قال رسول اللّٰه ﷺ: (( ابن أخت القوم منهم ))."],"takhrij":"حسن: رواه أبو داود (٥١٢٢)، وأحمد (١٩٥٤١).","grade":"حسن","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (5122) and Ahmad (19541).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said, “The son of a people’s sister is one of them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5122},{"key":"ahmad","label":"مسند الإمام أحمد","number":19541,"n":19541}]},{"num":6074,"demo":false,"sanad":"","matn":["عن جبير بن مطعم قال: قال النبي ﷺ: (( ابن الأخت منهم ))."],"takhrij":"حسن: رواه الطبراني (٢/١٤٢).","grade":"حسن","chapter_ar":"باب نسخ ميراث العقد والحلف بميراث الرحم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani (2/142).","chapter_en":"The abrogation of inheritance by pact and oath, replaced by inheritance through kinship","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jubayr ibn Mut‘im said: The Prophet ﷺ said, “The sister’s son is one of them.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی","label":"الطبراني","number":2}]},{"num":6075,"demo":false,"sanad":"","matn":["عن أبي أمامة بن سهل بن حنيف قال: كتب عمر بن الخطاب إلى أبي عبيدة أن رسول اللّٰه ﷺ قال: (( اللّٰه ورسوله مولى من لا مولى له، والخال وارث من لا وارث له ))."],"takhrij":"حسن: رواه الترمذي (٢١٠٣)، وابن ماجه (٢٧٣٧)، وأحمد (١٨٩). قال الترمذي: “حسن صحيح”.","grade":"حسن","chapter_ar":"باب ما جاء في ميراث الخال","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2103), Ibn Majah (2737), and Ahmad (189). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What has been reported regarding the inheritance of the maternal uncle","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Abu Umamah ibn Sahl ibn Hunayf said: ‘Umar ibn al-Khattab wrote to Abu ‘Ubaydah that the Messenger of Allah ﷺ said, “Allah and His Messenger are the guardians of the one who has no guardian, and the maternal uncle is the heir of the one who has no heir.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2103},{"key":"ibnmajah","label":"ابن ماجه","number":2737},{"key":"ahmad","label":"مسند الإمام أحمد","number":189,"n":189}]},{"num":6076,"demo":false,"sanad":"","matn":["عن المقدام الكندي قال: قال رسول اللّٰه ﷺ: (( أنا أولى بكل مؤمن من نفسه، فمن ترك دينا أو ضيعة فإليَّ، ومن ترك مالا فلورثته، وأنا مولى من لا مولى له، أرث ماله، وأفك عانه، والخال مولى من لا مولى له، يرث ماله، ويفك عانه ))."],"takhrij":"حسن: رواه أبو داود (٢٩٠٠)، وابن ماجه (٢٦٣٤). واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ما جاء في ميراث الخال","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2900) and Ibn Majah (2634). The wording is Abu Dawud’s.","chapter_en":"What has been reported regarding the inheritance of the maternal uncle","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Al-Miqdam al-Kindi said: The Messenger of Allah ﷺ said, “I am closer to every believer than his own self. Whoever leaves behind debt or needy dependents, then it is for me to take care of. Whoever leaves behind wealth, it belongs to his heirs. And I am the guardian of the one who has no guardian: I inherit his wealth and free his captive. And the maternal uncle is the guardian of the one who has no guardian: he inherits his wealth and frees his captive.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2900},{"key":"ibnmajah","label":"ابن ماجه","number":2634}]},{"num":6077,"demo":false,"sanad":"","matn":["عن أسامة بن زيد أن النبي ﷺ قال: (( لا يرث المسلم الكافر، ولا الكافر المسلم ))."],"takhrij":"متفق عليه: رواه البخاري (٦٧٦٤)، ومسلم (١٦١٤).","grade":"متفق عليه","chapter_ar":"باب لا يرث المسلم الكافر، ولا الكافر المسلم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6764) and Muslim (1614).","chapter_en":"A Muslim does not inherit from a disbeliever, nor does a disbeliever inherit from a Muslim","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Usamah ibn Zayd narrated that the Prophet ﷺ said: “A Muslim does not inherit from a disbeliever, nor does a disbeliever inherit from a Muslim.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6764},{"key":"muslim","label":"مسلم","number":1614}]},{"num":6078,"demo":false,"sanad":"","matn":["عن أسامة بن زيد أنه قال: يا رسول الله، أين تنزل في دارك بمكة؟ فقال: (( هل ترك عقيل من رباع أو دور؟ )). وكان عقيل ورث أبا طالب هو وطالب، ولم يرثه جعفر ولا علي شيئا لأنهما كانا مسلمين، وكان عقيل وطالب كافرين. فكان عمر بن الخطاب يقول: “لا يرث المؤمن الكافر”.","قال ابن شهاب: وكانوا يتأولون قول اللّٰه تعالى: إِنَّ ٱلَّذِينَ ءَامَنُوا وَهَاجَرُوا وَجَٰهَدُوا بِأَمْوَٰلِهِمْ وَأَنفُسِهِمْ فِى سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَوا وَنَصَرُوا أُو۟لَٰٓئِكَ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ [سورة الأنفال: ٧٢]."],"takhrij":"صحيح: رواه البخاري (١٥٨٨)، ومسلم (١٣٥١).","grade":"صحيح","chapter_ar":"باب لا يرث المسلم الكافر، ولا الكافر المسلم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1588) and Muslim (1351).","chapter_en":"A Muslim does not inherit from a disbeliever, nor does a disbeliever inherit from a Muslim","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Usamah ibn Zayd said: I said, “O Messenger of Allah ﷺ, where will you stay in your house in Makkah?” He said, “Has ‘Aqil left us any houses or dwellings?” ‘Aqil and Talib had inherited from Abu Talib, while Ja‘far and ‘Ali inherited nothing from him because they were Muslims, whereas ‘Aqil and Talib were disbelievers. So ‘Umar ibn al-Khattab used to say: “A believer does not inherit from a disbeliever.”","Ibn Shihab said: They used to understand this in light of the saying of Allah the Exalted: ‘Indeed, those who believed and emigrated and strove with their wealth and their lives in the path of Allah, and those who gave shelter and support—those are allies of one another’ [Surat al-Anfal: 72]."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1588},{"key":"muslim","label":"مسلم","number":1351}]},{"num":6079,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو قال: قال رسول اللّٰه ﷺ: (( لا يتوارث أهل ملتين شتى ))."],"takhrij":"حسن: رواه أبو داود (٢٩١١)، وأحمد (٦٦٦٤)، والبيهقي (٢١٨/٦).","grade":"حسن","chapter_ar":"باب ما جاء أن أهل ملتين لا يتوارثان","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2911), Ahmad (6664), and al-Bayhaqi (6/218).","chapter_en":"What has been reported that the followers of two different religions do not inherit from one another","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr said: The Messenger of Allah ﷺ said, “The followers of two different religions do not inherit from one another.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2911},{"key":"البیہقی","label":"البيهقي","number":218},{"key":"ahmad","label":"مسند الإمام أحمد","number":6664,"n":6664}]},{"num":6080,"demo":false,"sanad":"","matn":["عن عائشة قالت: وجدت في قائم سيف رسول اللّٰه ﷺ كتابا: (( إن أشد الناس عتوًّا من ضرب غير ضاربه، ورجل قتل غير قاتله، ورجل تولى غير أهل نعمته، فمن فعل ذلك فقد كفر بالله ورسوله، لا يقبل اللّٰه منه صرفًا ولا عدلًا، وفي الأجر المؤمنون تكافأ دماؤهم، ويسعى بذمتهم أدناهم، لا يُقتل مسلم بكافر، ولا ذو عهد في عهده، ولا يتوارث أهل ملتين، ولا تُنكح المرأة على عمتها ولا على خالتها، ولا صلاة بعد العصر حتى تغرب الشمس، ولا تسافر امرأة ثلاث ليالٍ مع غير ذي محرم ))."],"takhrij":"حسن: رواه أبو يعلى (٤٧٥٧)، والدارقطني (١٣١/٣)، والبيهقي (٨/٢٩-٣٠).","grade":"حسن","chapter_ar":"باب ما جاء أن أهل ملتين لا يتوارثان","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Ya‘la (4757), al-Daraqutni (3/131), and al-Bayhaqi (8/29–30).","chapter_en":"What has been reported that the followers of two different religions do not inherit from one another","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["‘A’ishah said: I found a written statement in the hilt of the sword of the Messenger of Allah ﷺ: “The most rebellious of people are: a man who strikes someone other than the one who struck him, a man who kills someone other than his killer, and a man who affiliates himself with people other than those to whom he owes his bond of loyalty. Whoever does that has disbelieved in Allah and His Messenger. Allah will accept from him neither obligatory nor voluntary deeds. As for retaliation, the blood of the believers is equal, and the least of them may extend protection on behalf of them. A Muslim is not to be killed for a disbeliever, nor a person under covenant while his covenant remains in force. The followers of two different religions do not inherit from one another. A woman may not be married together with her paternal aunt or her maternal aunt. There is no prayer after the afternoon prayer until the sun sets. And a woman must not travel for three nights except with a male guardian.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":4757},{"key":"الدارقطنی","label":"الدارقطني","number":131},{"key":"البیہقی","label":"البيهقي","number":8},{"key":"sh12520","label":"مسند أبي يعلى","number":4757,"n":4762}]},{"num":6081,"demo":false,"sanad":"","matn":["عن عمر قال: قال رسول اللّٰه ﷺ: (( ليس للقاتل شيء ))."],"takhrij":"حسن: رواه مالك (٢/٨٦٧).","grade":"حسن","chapter_ar":"باب ما جاء أن القاتل لا يرث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (2/867).","chapter_en":"What has been reported that the killer does not inherit","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["‘Umar said: The Messenger of Allah ﷺ said, “The killer gets nothing.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2}]},{"num":6082,"demo":false,"sanad":"","matn":["عن ابن عباس قال: كان المال للولد، وكانت الوصية للوالدين، فنسخ اللّٰه من ذلك ما أحب، فجعل للذكر مثل حظ الأنثيين، وجعل للأبوين لكل واحد منهما السدس، وجعل للمرأة الثمن والربع، وللزوج الشطر والربع."],"takhrij":"صحيح: أخرجه البخاري (٦٧٣٩).","grade":"صحيح","chapter_ar":"باب ميراث الأب والأم","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6739).","chapter_en":"The inheritance of the father and the mother","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Abbas said: Wealth used to go to the children, and the bequest was for the parents. Then Allah abrogated from that whatever He willed. So He made for the male the share of two females, made for each of the parents one-sixth, made for the wife one-eighth or one-fourth, and for the husband one-half or one-fourth."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿ وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ ۚ فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ ۚ فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ ۚ مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ ۗ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا ۚ فَرِيضَةً مِنَ اللَّهِ ۗ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا ﴾ [سورة النساء: ١١]"],"en":["Allah the Exalted said:","“And for his parents, to each one of them is a sixth of what he leaves if he had a child. But if he had no child and his parents alone inherit from him, then for his mother is one-third. But if he had brothers or sisters, then for his mother is one-sixth, after any bequest he may have made or debt. Your fathers and your sons—you do not know which of them are nearest to you in benefit. This is an obligation from Allah. Indeed, Allah is Ever-Knowing, All-Wise.” [Surat al-Nisa’: 11]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6739}]},{"num":6083,"demo":false,"sanad":"","matn":["عن تميم الداري قال: سألت رسول اللّٰه ﷺ عن الرجل يسلم على يدي الرجل. فقال: (( هو أولى الناس بمحياه ومماته ))."],"takhrij":"صحيح: رواه الطحاوي في مشكل الآثار (٢٨٥٢)، والدارمي (٣٠٧٦)، والبيهقي (١٠/٢٩٦).","grade":"صحيح","chapter_ar":"باب ميراث الذي يسلم على يدي الرجل","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tahawi in Mushkil al-Athar (2852), al-Darimi (3076), and al-Bayhaqi (10/296).","chapter_en":"The inheritance of the one who accepts Islam at the hands of a man","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Tamim al-Dari said: I asked the Messenger of Allah ﷺ about a man who accepts Islam at the hands of another man. He said, “He is the most entitled of people to him in his life and in his death.”"]}},"tuhfa":{},"refs":[{"key":"الطحاوی/مشکل_الاثار","label":"الطحاوي في مشكل الآثار","number":2852},{"key":"darimi","label":"الدارمي","number":3076},{"key":"البیہقی","label":"البيهقي","number":10}]},{"num":6084,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: جاءت امرأة سعد بن الربيع بابنتي سعد إلى النبي ﷺ، فقالت: يا رسول الله، هاتان ابنتا سعد، قتل معك يوم أحد، وإن عمهما أخذ جميع ما ترك أبوهما، وإن المرأة لا تُنكح إلا على مالها، فسكت رسول الله ﷺ حتى أنزلت آية الميراث، فدعا رسول اللّٰه ﷺ أخا سعد بن الربيع، فقال: (( أعط ابنتي سعد ثلثي ماله، وأعط امرأته الثمن، وخذ أنت ما بقي ))."],"takhrij":"حسن: رواه ابن ماجه (٢٧٢٠)، والترمذي (٢٠٩٢) وصححه، وأحمد (١٤٧٩٨)، والحاكم (٤/٣٣٣).","grade":"حسن","chapter_ar":"باب فرض الابنتين فصاعدا","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2720), al-Tirmidhi (2092) who authenticated it, Ahmad (14798), and al-Hakim (4/333).","chapter_en":"The fixed share of two daughters and more","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The wife of Sa‘d ibn al-Rabi‘ came to the Prophet ﷺ with Sa‘d’s two daughters and said, “O Messenger of Allah ﷺ, these are the two daughters of Sa‘d. He was killed with you on the Day of Uhud, and their uncle has taken all that their father left, while a woman is only married for her wealth.” So the Messenger of Allah ﷺ remained silent until the verse of inheritance was revealed. Then the Messenger of Allah ﷺ called the brother of Sa‘d ibn al-Rabi‘ and said, “Give the two daughters of Sa‘d two-thirds of his wealth, give his wife one-eighth, and take what remains yourself.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2720},{"key":"tirmidhi","label":"الترمذي","number":2092},{"key":"hakim","label":"الحاكم","number":4},{"key":"ahmad","label":"مسند الإمام أحمد","number":14798,"n":14798}]},{"num":6085,"demo":false,"sanad":"","matn":["عن قبيصة بن ذؤيب أنه قال: جاءت الجدة إلى أبي بكر الصديق تسأله ميراثها، فقال: مالك في كتاب اللّٰه تعالى شيء، وما علمت لك في سنة نبي اللّٰه ﷺ شيئًا، فارجعي حتى أسأل الناس. فسأل الناس، فقال المغيرة بن شعبة: حضرت رسول اللّٰه ﷺ أعطاها السدس. فقال أبو بكر: هل معك غيرك؟ فقام محمد بن مسلمة، فقال مثل ما قال المغيرة بن شعبة، فأنفذه لها أبو بكر. ثم جاءت الجدة الأخرى إلى عمر بن الخطاب تسأله ميراثها، فقال: مالك في كتاب اللّٰه تعالى شيء، وما كان القضاء الذي قضي به إلا لغيرك، وما أنا بزائد في الفرائض، ولكن هو ذلك السدس، فإن اجتمعتما فهو بينكما، وأيكما خلت به فهو لها."],"takhrij":"حسن: رواه مالك (٤)، وأبو داود (٢٨٩٤)، والترمذي (٢١٠١)، وابن ماجه (٢٧٢٤).","grade":"حسن","chapter_ar":"باب ما جاء في الجدة والجد","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Malik (4), Abu Dawud (2894), al-Tirmidhi (2101), and Ibn Majah (2724).","chapter_en":"What has been reported regarding the grandmother and the grandfather","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Qabisah ibn Dhu’ayb said: A grandmother came to Abu Bakr al-Siddiq asking for her inheritance. He said, “I do not find anything for you in the Book of Allah, and I do not know anything for you in the Sunnah of the Prophet ﷺ, so go back until I ask the people.” He asked the people, and al-Mughirah ibn Shu‘bah said, “I was present when the Messenger of Allah ﷺ gave her one-sixth.” Abu Bakr said, “Do you have anyone besides yourself?” Then Muhammad ibn Maslamah stood up and said the same as al-Mughirah ibn Shu‘bah, so Abu Bakr awarded it to her. Then the other grandmother came to ‘Umar ibn al-Khattab asking him for her inheritance. He said, “You have nothing specifically in the Book of Allah, and the judgment that was given was only for someone other than you. I am not going to add anything to the fixed shares. Rather, it is that same one-sixth. If both of you are present, then it is between you; and whichever of you is alone in receiving it, then it is hers.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4},{"key":"abudawud","label":"أبو داود","number":2894},{"key":"tirmidhi","label":"الترمذي","number":2101},{"key":"ibnmajah","label":"ابن ماجه","number":2724}]},{"num":6086,"demo":false,"sanad":"","matn":["عن بريدة بن الحصيب أن النبي ﷺ جعل للجدة السدس إذا لم تكن دونها أم."],"takhrij":"حسن: رواه أبو داود (٢٨٩٥)، والنسائي في الكبرى (٦٣٣٨).","grade":"حسن","chapter_ar":"باب ما جاء في الجدة والجد","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2895) and al-Nasa’i in al-Kubra (6338).","chapter_en":"What has been reported regarding the grandmother and the grandfather","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Prophet ﷺ gave the grandmother one-sixth if there was no mother between her and the deceased."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2895},{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":6338}]},{"num":6087,"demo":false,"sanad":"","matn":["عن معقل بن يسار المزني قال: سمعت النبي ﷺ أُتي بفريضة فيها جد، فأعطاه ثلثًا أو سدسًا."],"takhrij":"حسن: رواه ابن ماجه (٢٧٢٢)، وابن أبي شيبة (١١/٢٩١).","grade":"حسن","chapter_ar":"باب ما جاء في الجدة والجد","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2722) and Ibn Abi Shaybah (11/291).","chapter_en":"What has been reported regarding the grandmother and the grandfather","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Ma‘qil ibn Yasar al-Muzani said: I heard that a case of inheritance involving a grandfather was brought to the Prophet ﷺ, and he gave him either one-third or one-sixth."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2722},{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":11},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":31214,"n":31196}]},{"num":6088,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ أنه قال: (( إذا استهلّ المولود وُرِّث ))."],"takhrij":"حسن: رواه أبو داود (٢٩٢٠)، والبيهقي (٦/٢٥٧).","grade":"حسن","chapter_ar":"باب توريث المولود إذا استهل","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2920) and al-Bayhaqi (6/257).","chapter_en":"Inheriting for the newborn if he cries out at birth","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ that he said: “If the newborn gives a cry at birth, he is to inherit.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2920},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12485,"n":12608}]},{"num":6089,"demo":false,"sanad":"","matn":["عن المسور بن مخرمة وجابر بن عبد اللّٰه قالا: قال رسول اللّٰه ﷺ: (( لا يرث الصبي حتى يستهل صارخًا، واستهلاله أن يصيح، أو يبكي، أو يعطس ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٢/٢٠-٢١)، والأوسط (٤٥٩٦) كما في مجمع البحرين (٤/١٣٤).","grade":"حسن","chapter_ar":"باب توريث المولود إذا استهل","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (2/20–21) and al-Awsat (4596), as cited in Majma‘ al-Bahrayn (4/134).","chapter_en":"Inheriting for the newborn if he cries out at birth","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Al-Miswar ibn Makhramah and Jabir ibn ‘Abd Allah said: The Messenger of Allah ﷺ said, “The infant does not inherit until he cries out. His crying out is that he shouts, or cries, or sneezes.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":2},{"key":"الاوسط","label":"الأوسط","number":4596},{"key":"کما/مجمع_البحرین","label":"كما في مجمع البحرين","number":4}]},{"num":6090,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال النبي ﷺ: (( كل قسم قُسِم في الجاهلية فهو على ما قُسم، وكل قسم أدركه الإسلام فهو على قسم الإسلام ))."],"takhrij":"حسن: رواه أبو داود (٢٩١٤)، وابن ماجه (٢٤٨٥).","grade":"حسن","chapter_ar":"باب فيمن أسلم على ميراث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2914) and Ibn Majah (2485).","chapter_en":"Regarding one who becomes Muslim while an inheritance is pending","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Abbas said: The Prophet ﷺ said, “Every division that was made in the pre-Islamic period remains upon the way it was divided, and every division that Islam reached is to be according to the division of Islam.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2914},{"key":"ibnmajah","label":"ابن ماجه","number":2485}]},{"num":6091,"demo":false,"sanad":"","matn":["عن عبد اللّٰه قال: إن أهل الإسلام لا يُسَيِّبون، وإن أهل الجاهلية كانوا يُسَيِّبون."],"takhrij":"صحيح: رواه البخاري (٦٧٥٣).","grade":"صحيح","chapter_ar":"باب ميراث السائبة","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6753).","chapter_en":"The inheritance of the one set free without retaining wala’","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["‘Abd Allah said: The people of Islam do not practice sa’ibah, whereas the people of the pre-Islamic period used to do so."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6753}]},{"num":6092,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب أنه كان يقول: الدية للعاقلة، ولا ترث المرأة من دية زوجها شيئًا، حتى قال له الضحاك بن سفيان: كتب إلي رسول اللّٰه ﷺ أن أورّث امرأة أشيم الضبابي من دية زوجها."],"takhrij":"صحيح: رواه أبو داود (٢٩٢٧)، والترمذي (٢١١٠)، وابن ماجه (٢٦٤٢)، وأحمد (١٥٧٤٥).","grade":"صحيح","chapter_ar":"باب في المرأة ترث من دية زوجها","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2927), al-Tirmidhi (2110), Ibn Majah (2642), and Ahmad (15745).","chapter_en":"A woman inheriting from the blood money of her husband","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["‘Umar ibn al-Khattab used to say: The blood money belongs to the ‘aqilah, and a woman does not inherit anything from the blood money of her husband. Then al-Dahhak ibn Sufyan told him: “The Messenger of Allah ﷺ wrote to me instructing me to give the wife of Ashyam al-Dibabi inheritance from the blood money of her husband.”"]},"buhuth":{"ar":["و (( أشيم )) بفتح الهمزة وسكون الشين. والضبابي - بكسر الضاد - منسوب إلى ضِبَاب."],"en":["“Ashyam” is pronounced with a fathah on the hamzah and a sukun on the shin. “Al-Dibabi” is pronounced with a kasrah on the dad, meaning one affiliated with Dibab."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2927},{"key":"tirmidhi","label":"الترمذي","number":2110},{"key":"ibnmajah","label":"ابن ماجه","number":2642},{"key":"ahmad","label":"مسند الإمام أحمد","number":15745,"n":15745}]},{"num":6093,"demo":false,"sanad":"","matn":["عن زينب أنها كانت تفلي رأس رسول الله ﷺ، وعنده امرأة عثمان بن عفان، ونساء من المهاجرات يشكون منازلهن، وأنهن يخرجن منه، ويضيق عليهن فيه، فتكلمت زينب، وتركت رأس رسول الله ﷺ، فقال رسول اللّٰه ﷺ: (( إنك لست تكلمين بعينيك، تكلمي واعملي عملك )). فأمر رسول اللّٰه ﷺ يومئذ أن تُورَّث دور المهاجرين النساء. فمات عبد الله بن مسعود فورثته امرأته دارًا بالمدينة."],"takhrij":"حسن: رواه أبو داود (٣٠٨٠)، وأحمد (٢٧٠٥٠) واللفظ له. ورواه أحمد أيضًا (٢٧٠٤٩) من وجه آخر مختصرًا: أن النبي ﷺ ورَّث النساء خططهن.","grade":"حسن","chapter_ar":"باب توريث نساء المهاجرين منازل أزواجهن","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3080) and Ahmad (27050), and this is his wording. Ahmad also narrated it (27049) in another shorter form: that the Prophet ﷺ gave the women inheritance rights in their allocated properties.","chapter_en":"Women of the Emigrants inheriting the homes of their husbands","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Zaynab said: I was picking lice from the head of the Messenger of Allah ﷺ, and with him was the wife of ‘Uthman ibn ‘Affan and some of the emigrant women, who were complaining about their dwellings, that they were being turned out of them and that things had become tight for them. Zaynab spoke while she had left the hair of the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ said, “You are not speaking with your eyes; speak, and continue your work.” On that day, the Messenger of Allah ﷺ ordered that the houses of the Emigrants should be inherited by the women. So when ‘Abd Allah ibn Mas‘ud died, his wife inherited a house in Madinah."]},"buhuth":{"ar":["وقوله: (( خططهن )) الخطط هي الأرض التي توضع عليها العلامات لتملكها، مثل قطع الأراضي المخصصة للتمليك، سواء للدولة أو للأفراد."],"en":["His statement, “their allocated properties,” refers to plots of land marked out as owned property, like designated land grants for ownership, whether for the state or for individuals."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3080},{"key":"اللفظ_لہ_ورواہ_احمد_ایضا","label":"اللفظ له. ورواه أحمد أيضًا","number":27049},{"key":"ahmad","label":"مسند الإمام أحمد","number":27050,"n":27050}]},{"num":6094,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: توفي أبي وعليه دين، فعرضت على غرمائه أن يأخذوا التمر بما عليه، فأبوا، ولم يروا أن فيه وفاء، فأتيت النبي ﷺ، فذكرت ذلك له، فقال: (( إذا جَدَدْتَه فوضعته في المِرْبَد فآذنت رسول اللّٰه ﷺ )). فجاء ومعه أبو بكر وعمر، فجلس عليه، ودعا بالبركة، ثم قال: (( ادع غرماءك، فأوفهم )). فما تركت أحدًا له على أبي دين إلا قضيته، وفضل ثلاثة عشر وسقًا، سبعة عجوة وستة لون، أو ستة عجوة وسبعة لون. فوافيت مع رسول اللّٰه ﷺ المغرب، فذكرت ذلك له، فضحك، فقال: (( ائت أبا بكر وعمر فأخبرهما )). فقالا: لقد علمنا إذ صنع رسول اللّٰه ﷺ ما صنع أن سيكون ذلك."],"takhrij":"صحيح: رواه البخاري (٢٧٠٩).","grade":"صحيح","chapter_ar":"باب الصلح بين الغرماء وأصحاب الميراث","chapter_ur":"","part_ar":"كتاب الفرائض","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2709).","chapter_en":"Reconciliation between creditors and the heirs","part_en":"The Book of Inheritance","group_ar":"","group_en":"","part_no":21,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: My father died while he owed a debt. I offered his creditors that they take dates in place of what was owed to them, but they refused, not thinking that it would cover the debt. So I came to the Prophet ﷺ and mentioned that to him. He said, “When you gather the dates and place them in the drying area, then inform the Messenger of Allah ﷺ.” He came, along with Abu Bakr and ‘Umar, sat upon it, and prayed for blessing. Then he said, “Call your creditors and pay them.” I did not leave anyone to whom my father owed anything except that I paid him in full, and there remained thirteen wasqs: seven of ‘ajwah dates and six of lawn dates, or six of ‘ajwah and seven of lawn. Then I met the Messenger of Allah ﷺ at the sunset prayer and told him about it, and he smiled and said, “Go to Abu Bakr and ‘Umar and inform them.” They said, “We knew, when the Messenger of Allah ﷺ did what he did, that this would happen.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2709}]},{"num":6095,"demo":false,"sanad":"","matn":["عن ابن عباس في قوله عزَّ وجلَّ: ﴿ يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ ﴾ [سورة النساء: ١١] قال: كان الميراث للولد، وكانت الوصية للوالدين والأقربين، فنسخ اللّٰه من ذلك ما أحب، فجعل للولد الذكر مثل حظ الأنثيين، وجعل للوالدين لكل واحد منهما السدس، وجعل للمرأة الثمن والربع، وللزوج الشطر والربع."],"takhrij":"صحيح: رواه البخاري (٢٧٤٧). وفي رواية (٤٥٧٨): وجعل للأبوين لكل واحد منهما السدس والثلث.","grade":"صحيح","chapter_ar":"باب ما جاء في نسخ الوصية بآية الميراث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2747). In another narration (4578): “And He made for the two parents, for each of them, one-sixth and one-third.”","chapter_en":"What has been reported regarding the abrogation of the bequest by the verse of inheritance","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said regarding the saying of Allah, Most High:","“Allah instructs you concerning your children: for the male is a share equal to that of two females” [Surat al-Nisa’: 11]:","Inheritance used to belong to the children, and the bequest was for the parents and the close relatives. Then Allah abrogated from that whatever He willed. He made for the male child the share of two female children, made for each parent one-sixth, made for the wife one-eighth or one-fourth, and for the husband one-half or one-fourth."]},"intro":{"ar":["قال اللّٰه عز وجل:","﴿ كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ ۝ فَمَنْ بَدَّلَهُ بَعْدَ مَا سَمِعَهُ فَإِنَّمَا إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ ۚ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ ۝ فَمَنْ خَافَ مِنْ مُوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَا إِثْمَ عَلَيْهِ ۚ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ﴾","[سورة البقرة: ١٨٠-١٨٢]"],"en":["Allah, Mighty and Majestic, said:","“It is prescribed for you, when death approaches one of you, if he leaves wealth, that he make a bequest for parents and close relatives according to what is acceptable, as a duty upon the righteous. Then whoever alters it after hearing it, the sin is only upon those who alter it. Indeed, Allah is All-Hearing, All-Knowing. But whoever fears from the testator some error or sin and brings about reconciliation between them, there is no sin upon him. Indeed, Allah is Most Forgiving, Most Merciful.”","[Surat al-Baqarah: 180–182]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2747},{"key":"وفی_روایہ","label":". وفي رواية","number":4578}]},{"num":6096,"demo":false,"sanad":"","matn":["عن ابن عباس قال: ﴿ إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ ﴾ فكانت الوصية كذلك حتى نسختها آية الميراث."],"takhrij":"حسن: رواه أبو داود (٢٨٦٩)، والبيهقي (٦/٢٦٥).","grade":"حسن","chapter_ar":"باب ما جاء في نسخ الوصية بآية الميراث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2869) and al-Bayhaqi (6/265).","chapter_en":"What has been reported regarding the abrogation of the bequest by the verse of inheritance","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said:","“If he leaves wealth, then a bequest for the parents and close relatives…” This ruling remained as such until the verse of inheritance abrogated it."]},"buhuth":{"ar":["كانت الوصية قبل نزول آية الميراث واجبة، ثم نُسخت للوارثين، فبقيت في غير الوارثين مستحبة، وهو رأي جمهور أهل العلم، إلا أن يكون عليه دين، أو عنده أمانة، أو وديعة؛ فيجب عليه أن يوصي بذلك للحفاظ على حقوق الآخرين."],"en":["Before the revelation of the inheritance verse, the bequest was obligatory. Then it was abrogated for the heirs, while it remained recommended for non-heirs, and this is the view of the majority of scholars. However, if a person owes a debt, or has a trust, or property held in safekeeping, then he must make a bequest about it in order to preserve the rights of others."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2869},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12546,"n":12669}]},{"num":6097,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( ما حق امرئ مسلم له شيء يريد أن يوصي فيه يبيت ليلتين إلا ووصيته مكتوبة عنده ))."],"takhrij":"متفق عليه: رواه مالك (١) والبخاري (٢٧٣٨) ومسلم (١٦٢٧).","grade":"متفق عليه","chapter_ar":"باب استحباب الوصية لغير الوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (2738), and Muslim (1627).","chapter_en":"The recommendation of making a bequest for one who is not an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar narrated that the Messenger of Allah ﷺ said:","“It is not proper for a Muslim who has something he wishes to bequeath to stay for two nights except that his will is written and kept with him.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":2738},{"key":"muslim","label":"مسلم","number":1627}]},{"num":6098,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( إن الرجل ليعمل بعمل أهل الخير سبعين سنة، فإذا أوصى حاف في وصيته، فيختم له بشر عمله، فيدخل النار. وإن الرجل ليعمل بعمل أهل الشر سبعين سنة، فيعدل في وصيته، فيختم له بخير عمله، فيدخل الجنة )).","قال أبو هريرة: اقرؤوا إن شئتم: ﴿ تِلْكَ حُدُودُ اللَّهِ ﴾ إلى قوله ﴿ وَلَهُ عَذَابٌ مُهِينٌ ﴾ [سورة النساء: ١٣-١٤]."],"takhrij":"حسن: رواه أبو داود (٢٨٦٧)، وابن ماجه (٢٧٠٣)، والترمذي (٢١١٧) وحسّنه، وأحمد (٧٧٤٣) واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب كراهية الإضرار في الوصية","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2867), Ibn Majah (2703), al-Tirmidhi (2117), who graded it Hasan, and Ahmad (7743). The wording is Ahmad’s.","chapter_en":"The reprehensibility of causing harm in a bequest","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said:","“A man may perform the deeds of the people of goodness for seventy years, but when he makes a bequest he behaves unjustly in his bequest, so the end of his deeds is sealed with evil and he enters the Fire. And a man may perform the deeds of the people of evil for seventy years, but he is just in his bequest, so the end of his deeds is sealed with good and he enters Paradise.”","Abu Hurayrah said: Recite, if you wish: “These are the limits set by Allah…” to His saying, “…and for him is a humiliating punishment.” [Surat al-Nisa’: 13–14]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2867},{"key":"ibnmajah","label":"ابن ماجه","number":2703},{"key":"tirmidhi","label":"الترمذي","number":2117},{"key":"ahmad","label":"مسند الإمام أحمد","number":7742,"n":7742}]},{"num":6099,"demo":false,"sanad":"","matn":["عن أبي أمامة قال: سمعت رسول اللّٰه ﷺ يقول في خطبته عام حجة الوداع: (( إن اللّٰه قد أعطى كل ذي حق حقه، فلا وصية لوارث ))."],"takhrij":"صحيح: رواه أبو داود (٢٨٧٠)، والترمذي (٢١٢٠)، وابن ماجه (٢٧١٣)، وأحمد (٢٢٢٩٤)، والبيهقي (٦/٢٦٤، ٢٧٢).","grade":"صحيح","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2870), al-Tirmidhi (2120), Ibn Majah (2713), Ahmad (22294), and al-Bayhaqi (6/264, 272).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abu Umamah said: I heard the Messenger of Allah ﷺ say in his sermon during the Farewell Pilgrimage:","“Allah has given every person entitled to a right his due right, so there is no bequest for an heir.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2870},{"key":"tirmidhi","label":"الترمذي","number":2120},{"key":"ibnmajah","label":"ابن ماجه","number":2713},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":22294,"n":22294}]},{"num":6100,"demo":false,"sanad":"","matn":["عن عمرو بن خارجة، أن النبي ﷺ خطبهم وهو على راحلته، وإن راحلته لتقصع بجرتها، وإن لعابها ليسيل بين كتفي، قال: (( إن اللّٰه قسم لكل وارث نصيبه من الميراث، فلا تجوز لوارث وصية ))."],"takhrij":"حسن: رواه الترمذي (٢١٢١)، والنسائي (٦/٢٤٧)، وابن ماجه (٢٧١٢)، وأحمد (١٧٦٦٩).","grade":"حسن","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2121), al-Nasa’i (6/247), Ibn Majah (2712), and Ahmad (17669).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["‘Amr ibn Kharijah narrated: The Prophet ﷺ addressed them while on his mount, and its cud was moving in its mouth, and its saliva was flowing between my shoulders. He said:","“Allah has apportioned to every heir his share of the inheritance, so a bequest is not valid for an heir.”"]},"buhuth":{"ar":["قال الترمذي: “حسن صحيح”."],"en":["Al-Tirmidhi said: “Hasan Sahih.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2121},{"key":"nasai","label":"النسائي","number":6},{"key":"ibnmajah","label":"ابن ماجه","number":2712},{"key":"ahmad","label":"مسند الإمام أحمد","number":17669,"n":17669}]},{"num":6101,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال:","إني لتحت ناقة رسول الله ﷺ يسيل عليَّ لعابها، فسمعته يقول:","«إِنَّ اللَّهَ جَعَلَ لِكُلِّ ذِي حَقٍّ حَقَّهُ، أَلَا لَا وَصِيَّةَ لِوَارِثٍ…»"],"takhrij":"صحيح: رواه ابن ماجه (٢٧١٤).","grade":"صحيح","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (2714).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik reported:","I was beneath the she-camel of the Messenger of Allah ﷺ while its saliva was dripping upon me, and I heard him say:","“Indeed, Allah has assigned to every person entitled to a right his due right. Indeed, there is no bequest for an heir…”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2714}]},{"num":6102,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو بن العاص أن رسول اللّٰه ﷺ قال: (( لا تجوز وصية لوارث، والولد للفراش، وللعاهر حجر ))."],"takhrij":"حسن: رواه ابن عدي في الكامل (٢/٨١٧).","grade":"حسن","chapter_ar":"باب لا وصية لوارث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn ‘Adi in al-Kamil (2/817).","chapter_en":"There is no bequest for an heir","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated that the Messenger of Allah ﷺ said:","“A bequest for an heir is not valid; the child belongs to the bed, and the fornicator gets the stone [i.e., nothing].”"]}},"tuhfa":{},"refs":[{"key":"ابن_عدی/الکامل","label":"ابن عدي في الكامل","number":2}]},{"num":6103,"demo":false,"sanad":"","matn":["عن سعد بن أبي وقاص قال: كان رسول اللّٰه ﷺ يعودني عام حجة الوداع من وجع اشتد بي، فقلت: يا رسول اللّٰه، إني قد بلغ بي من الوجع، وأنا ذو مال، ولا يرثني إلا ابنة، أفأتصدق بثلثي مالي؟ قال: (( لا )). قلت: بالشطر؟ فقال: (( لا )). ثم قال: (( الثلث، والثلث كبير أو كثير، إنك أن تذر ورثتك أغنياء خير من أن تذرهم عالة يتكففون الناس ))."],"takhrij":"متفق عليه: رواه مالك (٤) والبخاري (١٢٩٥) ومسلم (١٦٢٨).","grade":"متفق عليه","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (4), al-Bukhari (1295), and Muslim (1628).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: The Messenger of Allah ﷺ came to visit me during the Farewell Pilgrimage because of an illness that had become severe. I said, “O Messenger of Allah ﷺ, my illness has reached a serious state, and I am a man of wealth, and none inherits from me except one daughter. Shall I give two-thirds of my wealth in charity?” He said, “No.” I said, “Then half?” He said, “No.” Then he said, “One-third, and one-third is much—or great. To leave your heirs wealthy is better than to leave them poor, begging from people.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4},{"key":"bukhari","label":"البخاري","number":1295},{"key":"muslim","label":"مسلم","number":1628}]},{"num":6104,"demo":false,"sanad":"","matn":["عن ابن عباس قال: لو أن الناس غضوا من الثلث إلى الربع؛ فإن رسول اللّٰه ﷺ قال: (( الثلث، والثلث كثير ))."],"takhrij":"متفق عليه: رواه البخاري (٢٧٤٣)، ومسلم (١٦٢٩).","grade":"متفق عليه","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2743) and Muslim (1629).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Abbas said: If people would reduce the bequest from one-third to one-fourth, that would be better, for the Messenger of Allah ﷺ said:","“One-third, and one-third is much.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2743},{"key":"muslim","label":"مسلم","number":1629}]},{"num":6105,"demo":false,"sanad":"","matn":["عن حنظلة بن حِذْيم أن جده حنيفة قال لحِذْيم: اجمع لي بَنيَّ؛ فإني أريد أن أوصي. فجمعهم، فقال: إن أول ما أوصي أن ليتيمي هذا الذي في حجري مائة من الإبل التي كنا نسميها في الجاهلية المطيَّبة. فقال حِذْيم: يا أبت، إني سمعت بنيك يقولون: إنما نقر بهذا عند أبينا، فإذا مات رجعنا فيه. قال: فبيني وبينكم رسول اللّٰه ﷺ. فقال حِذْيم: رضينا. فارتفع حِذْيم، وحنيفة، وحنظلة معهم غلام، وهو رديف لحِذْيم، فلما أتوا النبي ﷺ سلموا عليه، فقال النبي ﷺ: (( وما رفعك يا أبا حِذْيم؟ )) قال: هذا، وضرب بيده على فخذ حِذْيم. فقال: إني خشيت أن يفجأني الكبر أو الموت، فأردت أن أوصي، وإني قلت: إن أول ما أوصي أن ليتيمي هذا الذي في حجري مائة من الإبل، كنا نسميها في الجاهلية المطيبة. فغضب رسول اللّٰه ﷺ حتى رأينا الغضب في وجهه، وكان قاعدًا، فجثا على ركبتيه، وقال: (( لا، لا، لا، الصدقة خمس، وإلا فعشر، وإلا فخمس عشرة، وإلا فعشرون، وإلا فخمس وعشرون، وإلا فثلاثون، وإلا فخمس وثلاثون، فإن كثرت فأربعون )). قال: فودعوه، ومع اليتيم عصا، وهو يضرب جملاً، فقال النبي ﷺ: (( عظُمت هذه هِراوة يتيم )).","قال حنظلة: فدنا بي إلى النبي ﷺ، فقال: إن لي بنين ذوي لحى، ودون ذلك، وإن ذا أصغرهم، فادع اللّٰه له. فمسح رأسه، وقال: (( بارك اللّٰه فيك، أو بورك فيه )).","قال ذيال: فلقد رأيت حنظلة يؤتى بالإنسان الوارم وجهه، أو البهيمة الوارمة الضرع، فيتفل على يديه، ويقول: بسم الله، ويضع يده على رأسه، ويقول: على موضع كف رسول اللّٰه ﷺ، فيمسحه عليه، وقال ذيال: فيذهب الورم."],"takhrij":"صحيح: رواه أحمد (٢٠٦٦٥).","grade":"صحيح","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (20665).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Hanzalah ibn Hidhaym narrated from his grandfather Hunayfah: He said to Hidhaym, “Gather my sons for me, for I want to make a bequest.” So he gathered them, and he said, “The first thing I bequeath is one hundred camels to this orphan of mine who is under my care—camels that we used to call in the pre-Islamic period al-mutayyabah.” Hidhaym said, “Father, I have heard your sons saying: we only acknowledge this while our father is alive, but when he dies we will go back on it.” He said, “Then the Messenger of Allah ﷺ will judge between me and you.” Hidhaym said, “We accept.”","So Hidhaym, Hunayfah, and Hanzalah, along with a boy riding behind Hidhaym, went to the Prophet ﷺ. When they came to him and greeted him, the Prophet ﷺ said, “What has brought you here, O Abu Hidhaym?” He replied, pointing to Hidhaym’s thigh with his hand, “This one. I feared that old age or death might come upon me suddenly, so I wanted to make a bequest. I said that the first thing I bequeath is one hundred camels to this orphan of mine who is under my care, camels we used to call in the pre-Islamic period al-mutayyabah.” The Messenger of Allah ﷺ became angry until we saw anger in his face. He had been sitting, then he dropped to his knees and said: “No, no, no. Charity is five, or ten, or fifteen, or twenty, or twenty-five, or thirty, or thirty-five, and if it is more, then forty.”","Then they took leave of him, and the orphan had a stick with which he was striking a camel. The Prophet ﷺ said, “This is quite a large staff for an orphan.”","Hanzalah said: Then he brought me close to the Prophet ﷺ and said, “I have sons with beards, and others younger than that, and this is the youngest of them, so supplicate to Allah for him.” He wiped his head and said, “May Allah bless you,” or “May he be blessed.”","Dhiyal said: I indeed saw Hanzalah brought to a person whose face was swollen, or to an animal whose udder was swollen, and he would spit lightly on his hands, say “In the name of Allah,” place his hand upon his head and say, “Upon the place where the palm of the Messenger of Allah ﷺ rested,” then wipe over it. Dhiyal said: “Then the swelling would go away.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":20665,"n":20665}]},{"num":6106,"demo":false,"sanad":"","matn":["عن عمران بن حصين أن رجلاً أعتق ستة مملوكين له عند موته، لم يكن له مال غيرهم، فدعا بهم رسول اللّٰه ﷺ، فجزأهم أثلاثًا، ثم أقرع بينهم، فأعتق اثنين، وأرق أربعة، وقال له قولًا شديدًا."],"takhrij":"صحيح: رواه مسلم (١٦٦٨).","grade":"صحيح","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1668).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["‘Imran ibn Husayn narrated that a man freed six slaves of his at the time of his death, and he had no other wealth besides them. The Messenger of Allah ﷺ called for them, divided them into three groups, then cast lots among them, freed two, and left four in slavery, and he spoke sternly to him."]},"buhuth":{"ar":["وقوله: (( وقال له قولًا شديدًا )) هو كما جاء في السنن: (( لو شهدته قبل أن يدفن لم يُقبر في مقابر المسلمين ))."],"en":["His statement, “and he spoke sternly to him,” is explained in the Sunan as: “Had I been present before he was buried, he would not have been buried in the graveyards of the Muslims.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1668}]},{"num":6107,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رجلاً كان له ستة أعبد، فأعتقهم عند موته، فأقرع النبي ﷺ بينهم، فأعتق منهم اثنين، وأرق أربعة."],"takhrij":"صحيح: رواه ابن أبي شيبة (٢٣٨٤٧، ٣٧٢٣٩).","grade":"صحيح","chapter_ar":"باب الوصية بالثلث","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abi Shaybah (23847, 37239).","chapter_en":"Making a bequest of one-third","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated that a man had six slaves and freed them at his death, so the Prophet ﷺ cast lots among them, freed two of them, and left four in slavery."]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":23847},{"key":"sh9944","label":"المصنف لابن أبي شيبة","number":23381,"n":23364}]},{"num":6108,"demo":false,"sanad":"","matn":["عن عائشة قالت: ما ترك رسول اللّٰه ﷺ دينارًا ولا درهمًا، ولا شاةً ولا بعيرًا، ولا أوصى بشيء."],"takhrij":"صحيح: رواه مسلم (١٦٣٥).","grade":"صحيح","chapter_ar":"باب ما ترك رسول الله ﷺ دينارًا ولا درهمًا حتى يوصي به","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1635).","chapter_en":"The Messenger of Allah ﷺ did not leave behind a dinar or a dirham to make a bequest concerning","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ did not leave behind a dinar, nor a dirham, nor a sheep, nor a camel, nor did he make a bequest concerning anything."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1635}]},{"num":6109,"demo":false,"sanad":"","matn":["عن عمرو بن الحارث ختن رسول اللّٰه ﷺ أخي جويرية بنت الحارث قال: ما ترك رسول اللّٰه ﷺ عند موته درهمًا ولا دينارًا، ولا عبدًا ولا أمةً، ولا شيئًا، إلا بغلته البيضاء، وسلاحه، وأرضًا جعلها صدقة."],"takhrij":"صحيح: رواه البخاري (٢٧٣٩).","grade":"صحيح","chapter_ar":"باب ما ترك رسول الله ﷺ دينارًا ولا درهمًا حتى يوصي به","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2739).","chapter_en":"The Messenger of Allah ﷺ did not leave behind a dinar or a dirham to make a bequest concerning","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["‘Amr ibn al-Harith, the brother of Juwayriyyah bint al-Harith and the brother-in-law of the Messenger of Allah ﷺ, said: The Messenger of Allah ﷺ did not leave behind at his death a dirham, nor a dinar, nor a male slave, nor a female slave, nor anything at all, except his white mule, his weapons, and some land which he had made into charity."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2739}]},{"num":6110,"demo":false,"sanad":"","matn":["عن طلحة بن مصرف قال: سألت عبد اللّٰه بن أبي أوفى: هل كان النبي ﷺ أوصى؟ فقال: لا. فقلت: كيف كتب على الناس الوصية؟ أو أمروا بالوصية؟ قال: أوصى بكتاب اللّٰه."],"takhrij":"متفق عليه: رواه البخاري (٢٧٤٠) ومسلم (١٦٣٦).","grade":"متفق عليه","chapter_ar":"باب الوصية بالتمسك بالكتاب والسنة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2740) and Muslim (1636).","chapter_en":"The bequest to hold firmly to the Book and the Sunnah","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Talhah ibn Musarrif said: I asked ‘Abd Allah ibn Abi Awfa, “Did the Prophet ﷺ make a bequest?” He said, “No.” I said, “Then how was bequest prescribed for people, or how were they commanded to make a bequest?” He said, “He made a bequest with the Book of Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2740},{"key":"muslim","label":"مسلم","number":1636}]},{"num":6111,"demo":false,"sanad":"","matn":["عن علي قال: كان آخر كلام رسول اللّٰه ﷺ: (( الصلاةَ الصلاةَ، اتقوا اللّٰه فيما ملكت أيمانكم ))."],"takhrij":"حسن: رواه أبو داود (٥١٥٦)، وابن ماجه (٢٦٩٨).","grade":"حسن","chapter_ar":"باب في آخر وصية أوصى بها النبي ﷺ","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (5156) and Ibn Majah (2698).","chapter_en":"The last advice given by the Prophet ﷺ","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["‘Ali said: The last words of the Messenger of Allah ﷺ were:","“Prayer, prayer, and fear Allah regarding those whom your right hands possess.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5156},{"key":"ibnmajah","label":"ابن ماجه","number":2698}]},{"num":6112,"demo":false,"sanad":"","matn":["عن ابن عباس أنه قال: يوم الخميس، وما يوم الخميس؟ ثم بكى حتى خضب دمعُه الحصباء، فقال: اشتد برسول اللّٰه ﷺ وجعه يوم الخميس، فقال: (( ائتوني بكتاب، أكتب لكم كتابًا لن تضلوا بعده أبدًا)). فتنازعوا، ولا ينبغي عند نبي تنازع، فقالوا: هجر رسول اللّٰه ﷺ؟ قال: (( دعوني، فالذي أنا فيه خير مما تدعونني إليه )).","وأوصى عند موته بثلاث: (( أخرجوا المشركين من جزيرة العرب، وأجيزوا الوفد بنحو ما كنت أجيزهم )). ونسيت الثالثة.","قال يعقوب بن محمد: سألت المغيرة بن عبد الرحمن عن جزيرة العرب، فقال: مكة، والمدينة، واليمامة، واليمن. وقال يعقوب: والعرج أول تهامة."],"takhrij":"متفق عليه: رواه البخاري (٣٠٥٣)، ومسلم (١٦٣٧).","grade":"متفق عليه","chapter_ar":"باب وصية رسول الله ﷺ في المصلحة العامة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3053) and Muslim (1637).","chapter_en":"The Prophet’s bequest concerning the public welfare","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: Thursday — and what was Thursday? Then he wept until his tears soaked the pebbles. He said: The pain of the Messenger of Allah ﷺ became severe on Thursday, and he said, “Bring me writing material so I may write for you a document after which you will never go astray.” Then they disputed, and disputing should not take place in the presence of a prophet. They said, “Has the Messenger of Allah ﷺ become delirious?” He said, “Leave me, for what I am engaged in is better than what you are calling me to.”","At his death he gave three instructions: “Expel the polytheists from the Arabian Peninsula, and treat the delegations as generously as I used to treat them.” And I forgot the third.","Ya‘qub ibn Muhammad said: I asked al-Mughirah ibn ‘Abd al-Rahman about the Arabian Peninsula, and he said: Makkah, Madinah, al-Yamamah, and Yemen. Ya‘qub said: And al-‘Arj is the beginning of Tihamah."]},"buhuth":{"ar":["وقوله: (( هجر رسول اللّٰه ﷺ؟)) وفي صحيح مسلم: (( أهجر؟ استفهموه)). قال القاضي عياض: “وهو أصح من رواية من روى: هجر، يهجر؛ لأن هذا كله لا يصح منه ﷺ؛ لأن معنى هجر: هذى. وإنما جاء هذا من قائله استفهامًا للإنكار على من قال: لا تكتبوا؛ أي: لا تتركوا أمر رسول اللّٰه ﷺ، وتجعلوه كأمر من هجر في كلامه؛ لأنه ﷺ لا يهجر”.","وقوله: (( دعوني، فالذي أنا فيه خير )) معناه: دعوني من النزاع واللغط الذي شرعتم فيه، فالذي أنا فيه من مراقبة الله والتأهب للقائه أفضل مما أنتم فيه.","وقوله: (( وأجيزوا الوفد )) هذا أمر من رسول اللّٰه ﷺ بإجازة الوفود، وضيافتهم، وإكرامهم تطييبًا لنفوسهم، وترغيبًا لغيرهم من المؤلفة قلوبهم ونحوهم؛ لأن في آخر أيام رسول اللّٰه ﷺ كثرت الوفود من جميع النواحي للدخول في الإسلام.","وقوله: (( نسيت الثالثة )) وفي رواية: (( وسكت عن الثالثة، أو قالها فأنسيتها)). فقوله: “سكت” أي ابن عباس، فلم يذكر الثالثة. “أو قالها فأنسيتها” قائلها سعيد بن جبير. وقيل: الثالثة هي تجهيز جيش أسامة."],"en":["His statement, “Has the Messenger of Allah ﷺ become delirious?” In Sahih Muslim it is recorded as: “Has he become delirious? Ask him.” Al-Qadi ‘Iyad said: This wording is more accurate than the narration that states it plainly as “He is delirious,” because that would not be sound concerning him ﷺ, since the meaning of that word is incoherent speech. Rather, this came as a question from the speaker, expressing disapproval of those who said, “Do not write,” meaning: do not neglect the command of the Messenger of Allah ﷺ and treat it like the speech of someone speaking irrationally, for he ﷺ did not speak irrationally.","His statement, “Leave me, for what I am engaged in is better,” means: leave me from the dispute and noise that you have begun. What I am engaged in — being mindful of Allah and preparing to meet Him — is better than what you are occupied with.","His statement, “Treat the delegations generously,” is an instruction from the Messenger of Allah ﷺ to honor visiting delegations, host them, and show them generosity, in order to win their hearts and encourage others among those whose hearts were to be reconciled and others like them, because in the final days of the Messenger of Allah ﷺ many delegations were coming from all regions to enter Islam.","His statement, “I forgot the third,” and in another narration, “He remained silent about the third, or he mentioned it and I was caused to forget it,” means that Ibn ‘Abbas remained silent and did not mention the third. As for “or he mentioned it and I was caused to forget it,” that was said by Sa‘id ibn Jubayr. It was also said that the third instruction was the dispatch of Usamah’s army."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3053},{"key":"muslim","label":"مسلم","number":1637}]},{"num":6113,"demo":false,"sanad":"","matn":["عن ابن عباس أنه قال: يوم الخميس، وما يوم الخميس؟ ثم جعل تسيل دموعُه حتى رأيت على خديه كأنها نظام اللؤلؤ. قال: قال رسول اللّٰه ﷺ: (( ائتوني بالكتف والدواة - أو اللوح والدواة - أكتب لكم كتابًا لن تضلوا بعده أبدًا)). فقالوا: إن رسول اللّٰه ﷺ يهجر."],"takhrij":"صحيح: رواه مسلم (٢١:١٦٣٧).","grade":"صحيح","chapter_ar":"باب وصية رسول الله ﷺ في المصلحة العامة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (21:1637).","chapter_en":"The Prophet’s bequest concerning the public welfare","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: Thursday — and what was Thursday? Then his tears began to flow until I saw them on his cheeks like strings of pearls. He said: The Messenger of Allah ﷺ said, “Bring me a shoulder blade and an inkwell — or a tablet and an inkwell — so I may write for you a document after which you will never go astray.” Then they said: The Messenger of Allah ﷺ is delirious."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21}]},{"num":6114,"demo":false,"sanad":"","matn":["عن ابن عباس قال: لما حُضر رسول اللّٰه ﷺ، وفي البيت رجال، فقال النبي ﷺ: (( هلموا، أكتب لكم كتابًا لا تضلوا بعده )). فقال بعضهم: إن رسول اللّٰه ﷺ قد غلبه الوجع، وعندكم القرآن، حسبنا كتاب الله. فاختلف أهل البيت، واختصموا، فمنهم من يقول: قربوا يكتب لكم كتابًا لا تضلوا بعده. ومنهم من يقول غير ذلك. فلما أكثروا اللغو والاختلاف قال رسول اللّٰه ﷺ: (( قوموا )).","قال عبيد الله: فكان يقول ابن عباس: إن الرزية كل الرزية ما حال بين رسول اللّٰه ﷺ وبين أن يكتب لهم ذلك الكتاب لاختلافهم ولغطهم."],"takhrij":"متفق عليه: رواه البخاري (٤٤٣٢)، ومسلم (٢٢:١٦٣٧)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب وصية رسول الله ﷺ في المصلحة العامة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4432) and Muslim (22:1637), with the wording of al-Bukhari.","chapter_en":"The Prophet’s bequest concerning the public welfare","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: When the Messenger of Allah ﷺ was in his final illness, and there were men in the house, the Prophet ﷺ said, “Come, I will write for you a document after which you will not go astray.” Some of them said: The pain has overwhelmed the Messenger of Allah ﷺ, and you have the Qur’an, so the Book of Allah is sufficient for us. Then the people in the house differed and disputed. Some of them were saying: Bring it near so he may write for you a document after which you will not go astray. Others said something else. When their vain talk and disagreement increased, the Messenger of Allah ﷺ said, “Get up.”","‘Ubayd Allah said: Ibn ‘Abbas used to say: The true calamity, all calamity, was what prevented the Messenger of Allah ﷺ from writing that document for them because of their disagreement and noise."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4432},{"key":"muslim","label":"مسلم","number":22}]},{"num":6115,"demo":false,"sanad":"","matn":["عن الأسود بن يزيد قال: ذكروا عند عائشة أن عليًّا كان وصيًّا، فقالت: متى أوصى إليه؟ لقد كنت مسندته إلى صدري - أو قالت: حجري - فدعا بالطست، فلقد انخنث في حجري، وما شعرت أنه مات، فمتى أوصى إليه؟"],"takhrij":"متفق عليه: رواه البخاري (٢٧٤١)، ومسلم (١٦٣٦).","grade":"متفق عليه","chapter_ar":"باب لم يكن عليٌّ وصيًّا","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2741) and Muslim (1636).","chapter_en":"‘Ali was not appointed as executor","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: It was mentioned in the presence of ‘A’ishah that ‘Ali had been appointed as executor, so she said: When did he appoint him? I had him resting against my chest — or she said: in my lap — and he asked for a basin. He then leaned heavily in my lap, and I did not even realize that he had died. So when did he appoint him?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2741},{"key":"muslim","label":"مسلم","number":1636}]},{"num":6116,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو بن العاص: أن العاص بن وائل أوصى أن يعتق عنه مائة رقبة، فأعتق ابنه هشام خمسين رقبة، فأراد ابنه عمرو أن يعتق عنه الخمسين الباقية، فقال: حتى أسأل رسول اللّٰه ﷺ، فأتى النبي ﷺ، فقال: يا رسول اللّٰه، إن أبي أوصى بعتق مائة رقبة، وإن هشامًا أعتق عنه خمسين، وبقيت عليه خمسون رقبة، أفأعتق عنه؟ فقال رسول اللّٰه ﷺ: (( إنه لو كان مسلمًا فأعتقتم عنه، أو تصدقتم عنه، أو حججتم عنه بلغه ذلك ))."],"takhrij":"حسن: رواه أبو داود (٢٨٨٣)، وأحمد (٦٧٠٤)، والبيهقي (٦/٢٧٩).","grade":"حسن","chapter_ar":"باب لا تنفع تنفيذ وصية من مات كافرًا","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2883), Ahmad (6704), and al-Bayhaqi (6/279).","chapter_en":"Carrying out the bequest of one who died a disbeliever does not benefit him","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated: Al-‘As ibn Wa’il made a bequest that one hundred slaves be freed on his behalf. His son Hisham freed fifty slaves for him. Then his son ‘Amr wanted to free the remaining fifty on his behalf, but he said: Let me ask the Messenger of Allah ﷺ first. So he came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, my father made a bequest that one hundred slaves be freed on his behalf, and Hisham has freed fifty for him, and fifty remain. Shall I free them on his behalf? The Messenger of Allah ﷺ said: “If he had been a Muslim, then if you had freed slaves on his behalf, or given charity on his behalf, or performed pilgrimage on his behalf, that would have reached him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2883},{"key":"البیہقی","label":"البيهقي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":6704,"n":6704},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":12637,"n":12760}]},{"num":6117,"demo":false,"sanad":"","matn":["عن ابن عمر قال:","أصاب عمر أرضًا بخيبر، فأتى النبي ﷺ يستأمره فيها، فقال:","يا رسول الله، إني أصبت أرضًا بخيبر، لم أصب مالًا قط هو أنفس عندي منه، فما تأمرني به؟","قال:","«إِنْ شِئْتَ حَبَسْتَ أَصْلَهَا، وَتَصَدَّقْتَ بِهَا».","قال:","فتصدق بها عمر أنه لا يباع أصلها، ولا يبتاع، ولا يورث، ولا يوهب.","قال:","فتصدق عمر في الفقراء، وفي القربى، وفي الرقاب، وفي سبيل الله، وابن السبيل، والضيف.","لا جناح على من وليها أن يأكل منها بالمعروف، أو يطعم صديقًا غير متمول فيه.","قال:","فحدثت به ابن سيرين، فقال:","غير متأثل مالًا."],"takhrij":"متفق عليه: رواه البخاري (٢٧٣٧)، ومسلم (١٦٣٢).","grade":"متفق عليه","chapter_ar":"باب الوقف للغني والفقير والضيف، وأنه من وليه فليأكل بالمعروف بقدر عمله","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2737) and Muslim (1632).","chapter_en":"Endowment for the rich, the poor, and the guest, and that the one who oversees it may eat from it in a fair manner according to his work","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar reported:","ʿUmar acquired a piece of land at Khaybar. He came to the Prophet ﷺ seeking his instruction regarding it and said:","“O Messenger of Allah ﷺ, I have acquired land at Khaybar, and I have never acquired any wealth more precious to me than it. What do you command me to do with it?”","He said:","“If you wish, retain the original property and give its benefit in charity.”","So ʿUmar gave it in charity on the condition that its original property would neither be sold, purchased, inherited, nor gifted.","ʿUmar dedicated it for the poor, relatives, the freeing of slaves, the cause of Allah, the stranded traveler, and guests.","There is no blame upon the person administering it if he eats from it according to what is reasonable or feeds a friend, provided that he does not seek to accumulate wealth from it.","He said:","I narrated this to Ibn Sīrīn, and he said:","“Without accumulating wealth from it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2737},{"key":"muslim","label":"مسلم","number":1632}]},{"num":6118,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن النبي ﷺ رأى رجلًا يسوق بدنة، فقال: (( اركبها )). قال: إنها بدنة. قال: (( اركبها )). قال: إنها بدنة. قال: (( اركبها )) ثلاثًا."],"takhrij":"متفق عليه: رواه مالك (١٤٤) والبخاري (١٦٨٩)، ومسلم (١٣٢٢).","grade":"متفق عليه","chapter_ar":"باب هل ينتفع الواقف بوقفه","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (144), al-Bukhari (1689), and Muslim (1322).","chapter_en":"May the endower benefit from his endowment?","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik narrated that the Prophet ﷺ saw a man driving a sacrificial camel and said, “Ride it.” The man said: It is a sacrificial camel. He said, “Ride it.” He said: It is a sacrificial camel. He said, “Ride it,” three times."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":144},{"key":"bukhari","label":"البخاري","number":1689},{"key":"muslim","label":"مسلم","number":1322}]},{"num":6119,"demo":false,"sanad":"","matn":["عن كعب بن مالك قال: قلت: يا رسول الله، إن من توبتي أن أنخلع من مالي صدقة إلى الله، وإلى رسوله ﷺ، فقال: (( أمسك عليك بعض مالك فهو خير لك )). قلت: فإني أمسك سهمي الذي بخيبر."],"takhrij":"صحيح: رواه البخاري (٢٧٥٧).","grade":"صحيح","chapter_ar":"باب من الأفضل للواقف أن يمسك بعض أمواله","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2757).","chapter_en":"It is better for the one giving away property to keep some of his wealth","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ka‘b ibn Malik said: I said: O Messenger of Allah ﷺ, part of my repentance is that I give away all my wealth in charity for Allah and His Messenger ﷺ. He said: “Keep some of your wealth, for that is better for you.” I said: Then I will keep my share at Khaybar."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2757}]},{"num":6120,"demo":false,"sanad":"","matn":["عن ابن عباس أن سعد بن عبادة أخا بني ساعدة توفيت أمه، وهو غائب، فأتى النبي ﷺ، فقال: يا رسول الله، إن أمي توفيت، وأنا غائب عنها، فهل ينفعها شيء إن تصدقت به عنها؟ قال: (( نعم )). قال: فإني أشهدك أن حائطي المخراف صدقة عليها."],"takhrij":"صحيح: رواه البخاري (٢٧٦٢).","grade":"صحيح","chapter_ar":"باب الإشهاد في الوقف والصدقة","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2762).","chapter_en":"Having witnesses for an endowment and charity","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ‘Abbas narrated that Sa‘d ibn ‘Ubadah, the brother of Banu Sa‘idah, lost his mother while he was absent. He came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, my mother has died while I was absent. Will anything benefit her if I give charity on her behalf? He said, “Yes.” He said: Then I make you witness that my garden al-Mikhraf is charity on her behalf."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2762}]},{"num":6121,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: لما قدم رسول اللّٰه ﷺ المدينة أمر بالمسجد، وقال: (( يا بني النجار، ثامنوني بحائطكم هذا )). قالوا: لا، والله، لا نطلب ثمنه إلا إلى الله."],"takhrij":"متفق عليه: رواه البخاري (٢٧٧٤)، ومسلم (٥٢٤)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب وقف الأرض للمسجد","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2774) and Muslim (524), with the wording of al-Bukhari.","chapter_en":"Endowing land for a mosque","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas ibn Malik said: When the Messenger of Allah ﷺ arrived in Madinah, he ordered that the mosque be established and said: “O Banu al-Najjar, name me a price for this orchard of yours.” They said: No, by Allah, we seek no price for it except from Allah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2774},{"key":"muslim","label":"مسلم","number":524}]},{"num":6122,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو بن العاص أن رجلًا أتى النبي ﷺ، فقال: إني فقير، وليس لي شيء، ولي يتيم، فقال: (( كُلْ من مال يتيمك غير مسرف، ولا مبذر أو مبادر، ولا متأثل ))."],"takhrij":"حسن: رواه أبو داود (٢٨٧٢)، والنسائي (٦/٢٥٦)، وابن ماجه (٢٧١٨)، وأحمد (٢/١٨٦).","grade":"حسن","chapter_ar":"باب من ولي مال اليتيم ينال من ماله بقدر حاجته","chapter_ur":"","part_ar":"كتاب الوصية والوقف","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2872), al-Nasa’i (6/256), Ibn Majah (2718), and Ahmad (2/186).","chapter_en":"The guardian of an orphan’s wealth may take from it according to his need","part_en":"The Book of Bequests and Endowments","group_ar":"","group_en":"","part_no":22,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As narrated that a man came to the Prophet ﷺ and said: I am poor and I have nothing, but I have an orphan under my care. He said: “Eat from the wealth of your orphan without excess, without wastefulness or haste, and without building up wealth for yourself from it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2872},{"key":"nasai","label":"النسائي","number":6},{"key":"ibnmajah","label":"ابن ماجه","number":2718},{"key":"ahmad","label":"أحمد","number":2}]},{"num":6123,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال النبي ﷺ: (( أيما رجل أعتق امرأً مسلما، استنقذ اللّٰه بكل عضو منه عضوا منه من النار )). قال سعيد بن مرجانة: فانطلقت به إلى علي بن حسين، فعمد علي بن حسين -رضي اللّه عنهما- إلى عبد له قد أعطاه به عبد اللّٰه بن جعفر عشرة آلاف درهم أو ألف دينار، فأعتقه."],"takhrij":"متفق عليه: رواه البخاري (٢٥١٧)، ومسلم (٢٤: ١٥٠٩). ورواه أحمد (٩٤٤١)، وابن الجارود (٩٦٨)، والبيهقي (٢٧٣/٦) من طريق آخر وزاد فيه: (( حتى إنه ليعتق باليد اليدَ، وبالرجل الرجلَ، وبالفرج الفرجَ) ).","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2517) and Muslim (1509:24). Ahmad (9441), Ibn al-Jarud (968), and al-Bayhaqi (6/273) narrated it through another chain and added: “So much so that for the hand he frees a hand, for the foot a foot, and for the private part the private part.”","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said, “Whoever frees a Muslim slave, Allah will save from the Fire a limb of his for every limb of that slave.” Sa‘id ibn Marjanah said: I took this report to ‘Ali ibn al-Husayn, and ‘Ali ibn al-Husayn — may Allah be pleased with them both — went to a slave of his for whom ‘Abd Allah ibn Ja‘far had offered him ten thousand dirhams or one thousand dinars, and he set him free."]},"intro":{"ar":["قال اللّٰه تعالى:","(فَكُّ رَقَبَةٍ ۝ أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ ۝ يَتِيمًا ذَا مَقْرَبَةٍ) [البلد: ١٣ - ١٥]."],"en":["Allah Most High said:","“Freeing a slave, or feeding on a day of severe hunger, an orphan of near kin.” [Surah al-Balad, 90:13–15]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2517},{"key":"muslim","label":"مسلم","number":24},{"key":"ورواہ_احمد","label":". ورواه أحمد","number":9441},{"key":"ابن_الجارود","label":"ابن الجارود","number":968},{"key":"البیہقی","label":"البيهقي","number":273},{"key":"ahmad","label":"مسند الإمام أحمد","number":9441,"n":9441}]},{"num":6124,"demo":false,"sanad":"","matn":["عن أبي نجيح السلمي (هو عمرو بن عبسة) قال: حاصرنا مع رسول اللّٰه ﷺ بقصر الطائف - قال معاذ: سمعت أبي يقول: بقصر الطائف، بحصن الطائف، كل ذلك - فسمعت رسول اللّٰه ﷺ يقول: (( من بلغ بسهم فى سبيل اللّٰه عز وجل فله درجة )). وساق الحديث. وسمعت رسول اللّٰه ﷺ يقول: (( أيما رجل مسلم أعتق رجلا مسلما فإن اللّٰه عز وجل جاعل وقاء كل عظم من عظامه عظما من عظام محرَّره من النار. وأيما امرأة أعتقت امرأة مسلمة فإن اللّٰه جاعل وقاء كل عظم من عظامها عظما من عظام محررها من النار يوم القيامة ))."],"takhrij":"صحيح: رواه أبو داود (٣٩٦٥)، والترمذي (١٦٣٨) وصحّحه، والنسائي (٣١٤٣)، وصحّحه ابن حبان (٤٦١٥).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3965), al-Tirmidhi (1638), who authenticated it, al-Nasa’i (3143), and Ibn Hibban, who authenticated it (4615).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Najih al-Sulami, who is ‘Amr ibn ‘Abasah, said: We laid siege alongside the Messenger of Allah ﷺ at the fortress of al-Ta’if. Mu‘adh said: I heard my father say, “At the palace of al-Ta’if,” “at the fortress of al-Ta’if” — all of that was said. I heard the Messenger of Allah ﷺ say, “Whoever causes an arrow to reach its mark in the cause of Allah, Mighty and Majestic, will have one degree for it.” Then he mentioned the rest of the narration. And I heard the Messenger of Allah ﷺ say, “Any Muslim man who frees a Muslim man, Allah, Mighty and Majestic, will make each bone of the freed person a protection for each bone of his from the Fire. And any Muslim woman who frees a Muslim woman, Allah will make each bone of the freed woman a protection for each bone of her from the Fire on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3965},{"key":"tirmidhi","label":"الترمذي","number":1638},{"key":"nasai","label":"النسائي","number":3143},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4615}]},{"num":6125,"demo":false,"sanad":"","matn":["عن أبي أمامة وغيره من أصحاب النبي ﷺ، عن النبي ﷺ قال: (( أيما امرئ مسلم أعتق امرأ مسلما كان فكاكه من النار، يجزي كل عضو منه عضوا منه. وأيما امرئ مسلم أعتق امرأتين مسلمتين كانتا فكاكه من النار، يجزي كل عضو منهما عضوا منه. وأيما امرأة مسلمة أعتقت امرأة مسلمة كانت فكاكها من النار، يجزي كل عضو منها عضوا منها))."],"takhrij":"حسن: رواه الترمذي (١٥٤٧).","grade":"حسن","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1547).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Umamah and others among the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he said: “Any Muslim man who frees a Muslim man, that will be his ransom from the Fire; each limb of the slave will count for one of his limbs. Any Muslim man who frees two Muslim women, they will be his ransom from the Fire; each limb of the two will count for one of his limbs. And any Muslim woman who frees a Muslim woman, she will be her ransom from the Fire; each limb of the freed woman will count for one of her limbs.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1547}]},{"num":6126,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، عن رسول اللّٰه ﷺ قال: (( من أعتق رقبة مؤمنة وقى اللّٰه تعالى بكل عضو منها عضوا منه من النار))."],"takhrij":"حسن: رواه النسائي في الكبرى (٤٨٧٧)، والطحاوي في مشكله (٧١٥).","grade":"حسن","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (4877) and al-Tahawi in Mushkil al-Athar (715).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["‘Ali ibn Abi Talib narrated from the Messenger of Allah ﷺ that he said: “Whoever frees a believing slave, Allah Most High will protect from the Fire one of his limbs for every limb of that slave.”"]}},"tuhfa":{},"refs":[{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":4877},{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":715}]},{"num":6127,"demo":false,"sanad":"","matn":["عن الغريف بن الديلمي قال: أتينا واثلة بن الأسقع، فقلنا له: حدثنا حديثا ليس فيه زيادة، ولا نقصان، فغضب، وقال: إن أحدكم ليقرأ، ومصحفه معلق فى بيته، فيزيد وينقص. قلنا: إنما أردنا حديثا سمعته من النبي ﷺ. قال: أتينا رسول اللّٰه ﷺ في صاحب لنا أوجب - يعني النار - بالقتل، فقال: (( أعتقوا عنه يعتق اللّٰه بكل عضو منه عضوا منه من النار))."],"takhrij":"صحيح: رواه أبو داود (٣٩٦٤)، وأحمد (١٦٠١٢)، والحاكم (٢١٢/٢)، والبيهقي (٨/١٣٢-١٣٣).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3964), Ahmad (16012), al-Hakim (2/212), and al-Bayhaqi (8/132–133).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Ghurayf ibn al-Daylami said: We came to Wathilah ibn al-Asqa‘ and said to him: Narrate to us a report with neither addition nor omission. He became upset and said: One of you recites while his written copy hangs in his house, yet he still adds and omits. We said: We only want a report you heard from the Prophet ﷺ. He said: We came to the Messenger of Allah ﷺ concerning one of our companions who had made the Fire mandatory upon himself — meaning by killing — and he said: “Free a slave on his behalf, and Allah will free for every limb of that slave one of his limbs from the Fire.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3964},{"key":"hakim","label":"الحاكم","number":212},{"key":"البیہقی","label":"البيهقي","number":8},{"key":"ahmad","label":"مسند الإمام أحمد","number":16012,"n":16012}]},{"num":6128,"demo":false,"sanad":"","matn":["عن البراء قال: جاء أعرابي إلى النبي ﷺ، فقال: يا رسول الله، أخبرني بعمل يدخلني الجنة. قال: (( لئن قصَّرت في الخطبة لقد عرضت المسألة، أعتق النسمة وفك الرقبة )). قال: يا رسول الله، أوما هما سواء؟ قال: (( لا، عتق النسمة أن تفرد بها، وفك الرقبة أن تعين في ثمنها، والمنحة الوكوف، والفيء على ذي الرحم الظالم )). قال: فمن لم يطق ذلك؟ قال: (( فأطعم الجائع، واسق الظمآن )). قال: فإن لم أستطع؟ قال: (( مر بالمعروف، وانه عن المنكر )). قال: فمن لم يطق ذاك؟ قال: (( فكف لسانك إلا من خير ))."],"takhrij":"صحيح: رواه أحمد (١٨٦٤٧)، وأبو داود الطيالسي (٧٧٥)، والبخاري في الأدب المفرد (٦٩)، وابن حبان (٣٧٤).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (18647), Abu Dawud al-Tayalisi (775), al-Bukhari in al-Adab al-Mufrad (69), and Ibn Hibban (374).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Bara’ said: A Bedouin came to the Prophet ﷺ and said: O Messenger of Allah ﷺ, tell me of a deed that will admit me into Paradise. He said, “Though you made the speech brief, you have put the question clearly. Free a person from bondage and help free another from bondage.” He said: O Messenger of Allah ﷺ, are they not the same? He said: “No. Freeing a person from bondage means that you do it by yourself entirely, while helping free a person means that you assist in paying his price. Also, lending a milking animal, and showing kindness to a relative even when he is oppressive.” He said: What if I cannot do that? He said: “Then feed the hungry and give drink to the thirsty.” He said: What if I cannot? He said: “Then command what is right and forbid what is wrong.” He said: What if I cannot do that? He said: “Then restrain your tongue from everything except good.”"]}},"tuhfa":{},"refs":[{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسي","number":775},{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":69},{"key":"ibnhibban","label":"ابن حبان","number":374},{"key":"ahmad","label":"مسند الإمام أحمد","number":18647,"n":18647},{"key":"tayalisi","label":"مسند أبي داود الطيالسي","number":775,"n":775}]},{"num":6129,"demo":false,"sanad":"","matn":["عن أبي بردة بن أبي موسى قال: أي بني، ألا أحدثكم حديثا حدثني أبي عن رسول اللّٰه ﷺ قال: (( من أعتق رقبة أعتق اللّٰه عز وجل بكل عضو منها عضوا منه من النار))."],"takhrij":"حسن: رواه أحمد (١٩٦٢٣)، والحاكم (٢١١/٢)، والبيهقي (١٠/٢٧٢).","grade":"حسن","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (19623), al-Hakim (2/211), and al-Bayhaqi (10/272).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Burdah ibn Abi Musa said: My son, shall I not tell you a report that my father told me from the Messenger of Allah ﷺ? He said: “Whoever frees a slave, Allah, Mighty and Majestic, will free one of his limbs from the Fire for every limb of that slave.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":211},{"key":"البیہقی","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":19623,"n":19623}]},{"num":6130,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول اللّٰه ﷺ: (( من أعتق رقبة أعتق اللّٰه بكل عضو منه عضوا ))."],"takhrij":"صحيح: رواه الطحاوي في مشكله (٧١٦).","grade":"صحيح","chapter_ar":"باب ما جاء في فضل العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tahawi in Mushkil al-Athar (716).","chapter_en":"Chapter on the virtue of freeing slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said, “Whoever frees a slave, Allah will free a limb of his for every limb of that slave.”"]}},"tuhfa":{},"refs":[{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":716}]},{"num":6131,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( لا يجزي ولد والدا إلا أن يجده مملوكا، فيشتريه، فيُعتقه ))."],"takhrij":"صحيح: رواه مسلم (١٥١٠).","grade":"صحيح","chapter_ar":"باب فضل عتق الوالد","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1510).","chapter_en":"Chapter on the virtue of freeing one’s parent","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said, “A child cannot fully repay his parent except if he finds him enslaved, buys him, and sets him free.”"]},"buhuth":{"ar":["وقوله: (( فيشتريه، فيعتقه )) أي يقع العتق بالشراء مباشرة، ولا يحتاج إلى إنشاء العتق، فإن إنشاء العتق يستلزم إبقاءه تحت ملكه أيضًا إن شاء، ولم يقل أحد من أهل العلم أن يكون الأب مملوكًا لولده حتى يعتقه."],"en":["His statement, “then he buys him and frees him,” means that emancipation takes effect immediately upon purchase, and no separate declaration of freedom is needed. A separate declaration would imply that the parent remained under his ownership for some period if he wished, and no scholar has said that a father remains owned by his child until the child later frees him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1510}]},{"num":6132,"demo":false,"sanad":"","matn":["عن أبي ذر قال: سألت النبي ﷺ أي العمل أفضل؟ قال: (( إيمان بالله، وجهاد في سبيله )). قلت: فأي الرقاب أفضل؟ قال: (( أعلاها ثمنا، وأنفسها عند أهلها )). قلت: فإن لم أفعل؟ قال: (( تُعين صانعا، أو تصنع لأخرق )). قال: فإن لم أفعل؟ قال: (( تدع الناس من الشر، فإنها صدقة تصدق بها على نفسك ))."],"takhrij":"متفق عليه: رواه البخاري (٢٥١٨)، ومسلم (٨٤:١٣٦).","grade":"متفق عليه","chapter_ar":"باب فضل عتق الرقاب الثمينة والنفيسة","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2518) and Muslim (136:84).","chapter_en":"Chapter on the virtue of freeing valuable and precious slaves","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Dharr said: I asked the Prophet ﷺ: Which deed is best? He said, “Faith in Allah and striving in His path.” I said: Then which slaves are best to free? He said, “Those most expensive in price and most precious to their owners.” I said: What if I cannot do that? He said: “Help a worker, or work on behalf of one who is unskilled.” He said: What if I cannot do that? He said: “Then refrain from harming people, for that is a charity you give on your own behalf.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2518},{"key":"muslim","label":"مسلم","number":84}]},{"num":6133,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر قالت: أمر النبي ﷺ بالعتاقة في كسوف الشمس. وفي لفظ: كنا نؤمر عند الخسوف بالعتاقة."],"takhrij":"صحيح: رواه البخاري (٢٥١٩).","grade":"صحيح","chapter_ar":"باب الترغيب في العتق عند الكسوف والخسوف","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2519).","chapter_en":"Chapter on encouraging emancipation during a solar or lunar eclipse","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: The Prophet ﷺ commanded emancipation during a solar eclipse. In another wording: We were commanded to free slaves during an eclipse."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2519}]},{"num":6134,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر أن رسول اللّٰه ﷺ قال: (( من أعتق شركا له في عبد، فكان له مال بلغ ثمن العبد قُوِّم عليه قيمة العدل، فأعطى شركاءه حصصهم، وعتق عليه العبد، وإلا فقد عتق منه ما عتق ))."],"takhrij":"متفق عليه: رواه مالك (١) والبخاري (٢٥٢٢)، ومسلم (١:١٥٠١)، وفي (٤٧:١٥٠١).","grade":"متفق عليه","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (2522), and Muslim (1501:1 and 1501:47).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees his share in a slave, and has enough wealth to cover the price of the slave, then the slave is appraised fairly against him, he pays his partners their shares, and the slave becomes fully free through him. Otherwise, the portion already freed remains free.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":2522},{"key":"muslim","label":"مسلم","number":1},{"key":"وفی","label":"وفي","number":47}]},{"num":6135,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( من أعتق عبدا بينه وبين آخر قُوِّم عليه في ماله قيمة عدل، لا وكس، ولا شطط، ثم عتق عليه في ماله إن كان موسرا ))."],"takhrij":"متفق عليه: رواه البخاري (٢٥٢١)، ومسلم (٥٠: ١٥٠١). والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2521) and Muslim (1501:50). The wording is that of Muslim.","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees a slave jointly owned between him and another, the slave is appraised against him according to a fair value from his wealth, with neither undervaluation nor overvaluation, and then the slave becomes fully free through his wealth if he is well-off.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2521},{"key":"muslim","label":"مسلم","number":50}]},{"num":6136,"demo":false,"sanad":"","matn":["عن ابن عمر أنه كان يفتي في العبد أو الأمة يكون بين شركاء، فيعتق أحدهم نصيبه منه يقول: (( قد وجب عليه عتقه كله إذا كان للذي أعتق من المال ما يبلغ، يقوم من ماله قيمة العدل، ويدفع إلى الشركاء أنصباؤهم، ويخلى سبيل المعتق )) يخبر ذلك ابن عمر، عن النبي ﷺ."],"takhrij":"صحيح: رواه البخاري (٢٥٢٥).","grade":"صحيح","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2525).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar used to give legal rulings concerning a male or female slave jointly owned by partners, when one of them freed his share, saying: “It becomes binding upon him to free all of it if the one who freed his share has sufficient wealth. A fair valuation is made from his wealth, the partners are given their shares, and the freed person is released.” Ibn ‘Umar related this from the Prophet ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2525}]},{"num":6137,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: (( من أعتق نصيبا له في مملوك كُلِّف أن يتم عتقه بقيمة عدل ))."],"takhrij":"صحيح: رواه أحمد (٤٤٥١)، ورواه (٥٤٧٤)، وزاد فيه: (( فإن لم يكن له مال يعتقه به فقد جاز ما أعتق )).","grade":"صحيح","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (4451), and also by him in (5474), with the addition: “If he does not have wealth by which to free him completely, then what he has freed is valid.”","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Umar narrated that the Messenger of Allah ﷺ said: “Whoever frees a share he owns in a slave is required to complete his emancipation at a fair price.”"]}},"tuhfa":{},"refs":[{"key":"رواہ","label":"رواه","number":5474},{"key":"ahmad","label":"مسند الإمام أحمد","number":4451,"n":4451}]},{"num":6138,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال في المملوك بين الرجلين، فيعتق أحدهما قال: (( يضمن ))."],"takhrij":"صحيح: رواه مسلم (١٥٠٢).","grade":"صحيح","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1502).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ concerning a slave jointly owned by two men, one of whom frees his share. He said: “He is liable for the remainder.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1502}]},{"num":6139,"demo":false,"sanad":"","matn":["عن جابر - مقرونا بابن عمر - أن رسول اللّٰه ﷺ قال: (( من أعتق عبدا وله فيه شريك وله وفاءٌ فهو حُرٌّ، ويضمن نصيب شركائه بقيمة عدل لما أساء مشاركتهم، وليس على العبد شيء ))."],"takhrij":"حسن: رواه النسائي في الكبرى (٤٩٤٢)، وابن حبان في صحيحه (٤٣١٧).","grade":"حسن","chapter_ar":"باب العبد إذا كان بين شريكين فأكثر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i in al-Kubra (4942) and Ibn Hibban in his Sahih (4317).","chapter_en":"Chapter on a slave jointly owned by two or more partners","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Jabir, together with Ibn ‘Umar, narrated that the Messenger of Allah ﷺ said: “Whoever frees a slave in whom another person shares ownership, and he has the means, then the slave is free. He must guarantee the shares of his partners at a fair value because he has affected their partnership, and nothing is due from the slave.”"]}},"tuhfa":{},"refs":[{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":4942},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4317},{"key":"kubranasai","label":"السنن الكبرى للنسائي","number":4942,"n":4939},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4041,"n":4037}]},{"num":6140,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( من أعتق نصيبا، أو شقيصا في مملوك فخلاصه عليه في ماله إن كان له مال، وإلا قُوِّم عليه، فاستسعي به غير مشقوق عليه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٥٢٧)، ومسلم (٣:١٥٠٣). وقوله: (( شقيصا)) أي بعضه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الاستسعاء","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2527) and Muslim (1503:3). His statement, “or a portion,” means part of him.","chapter_en":"Chapter on the slave being required to earn his freedom","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Whoever frees a share, or a portion, in a slave, then the completion of his freedom is due from his wealth if he has wealth. Otherwise, the slave is fairly valued, and he is required to work to earn his freedom without hardship being imposed on him.”"]},"buhuth":{"ar":["والمعنى أنه إذا كان المعتق موسرًا لزمه أداء قيمة نصيب شريكه، فيعتق العبد كله، وإن لم يكن له مال قُوِّم العبد واستُسعي في قيمة نصيب الشريك غير مشقوق عليه."],"en":["The meaning is that if the emancipating partner has sufficient wealth, he must pay the fair value of his co-owner’s share, and the slave becomes fully free. If he does not have sufficient wealth, the slave is fairly valued and required to work toward paying the value of the remaining share, without undue hardship."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2527},{"key":"muslim","label":"مسلم","number":3}]},{"num":6141,"demo":false,"sanad":"","matn":["عن سلمان قال: كاتبت أهلي على أن أغرس لهم خمس مائة فسيلة، فإذا علِقت فأنا حر. قال: فأتيت النبي ﷺ، فذكرت ذلك له، فقال: (( اغرس، واشترط لهم، فإذا أردت أن تغرس فآذني)). قال: فآذنته. قال: فجاء، فجعل يغرس بيده إلا واحدة، غرستها بيدي، فعلقن إلا الواحدة."],"takhrij":"حسن: رواه أحمد (٢٣٧٣٠) والحاكم (٢١٨-٢١٧/٢)، والبيهقي (٣٢١/١٠).","grade":"حسن","chapter_ar":"باب ما جاء في إعانة المكاتب","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23730), al-Hakim (2/217–218), and al-Bayhaqi (10/321).","chapter_en":"Chapter on helping the contract slave","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Salman said: I made a contract with my masters that I would plant five hundred date-palms for them, and when they took root I would be free. He said: I came to the Prophet ﷺ and mentioned that to him. He said, “Plant them, and make the condition for them. When you want to plant them, inform me.” He said: So I informed him. He came and began planting them with his own hand, except for one which I planted with my own hand. They all took root except that one."]},"intro":{"ar":["قال الله عز وجل:","(وَٱلَّذِينَ يَبْتَغُونَ ٱلْكِتَابَ مِمَّا مَلَكَتْ أَيْمَٰنُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا) [النور: ٣٣]."],"en":["Allah, Mighty and Majestic, said:","“And those among your slaves who seek a contract of emancipation, then make such a contract with them if you know there is good in them.” [Surah al-Nur, 24:33]"]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":321},{"key":"ahmad","label":"مسند الإمام أحمد","number":23730,"n":23730},{"key":"hakim","label":"المستدرك على الصحيحين","number":2862,"n":2848},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":21624,"n":21781}]},{"num":6142,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده، عن النبي ﷺ قال: (( المكاتب عبد ما بقي من مكاتبته درهم)).","وفي لفظ: (( أيما عبد كاتب على مائة أوقية فأداها إلا عشرة أواق، فهو عبد، وأيما عبد كاتب على مائة دينار، فأداها إلا عشرة دنانير، فهو عبد ))."],"takhrij":"حسن: رواه أبو داود (٣٩٢٧، ٣٩٢٦)، والترمذي (١٢٦٠)، وابن ماجه (٢٥١٩)، وأحمد (٦٦٦٦).","grade":"حسن","chapter_ar":"باب المكاتب لا يزال عبدا ما بقي عليه درهم","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3926, 3927), al-Tirmidhi (1260), Ibn Majah (2519), and Ahmad (6666).","chapter_en":"Chapter that the contract slave remains a slave so long as even one dirham remains unpaid","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather, from the Prophet ﷺ that he said: “The contract slave remains a slave as long as even one dirham remains from his contracted amount.”","In another wording: “Any slave who contracts for one hundred ounces and pays all but ten ounces is still a slave; and any slave who contracts for one hundred dinars and pays all but ten dinars is still a slave.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3927},{"key":"tirmidhi","label":"الترمذي","number":1260},{"key":"ibnmajah","label":"ابن ماجه","number":2519},{"key":"ahmad","label":"مسند الإمام أحمد","number":6666,"n":6666}]},{"num":6143,"demo":false,"sanad":"","matn":["عن ابن عمر، عن النبي ﷺ قال: (( إنما الولاء لمن أعتق))."],"takhrij":"صحيح: رواه البخاري (٦٧٥٢).","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6752).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar narrated from the Prophet ﷺ that he said: “Clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6752}]},{"num":6144,"demo":false,"sanad":"","matn":["عن ابن عمر أن عائشة أم المؤمنين أرادت أن تشتري جارية تعتقها، فقال أهلها: نبيعكها على أن ولاءها لنا. فذكرت ذلك لرسول اللّٰه ﷺ، فقال: (( لا يمنعنك ذلك، فإنما الولاء لمن أعتق ))."],"takhrij":"متفق عليه: رواه مالك (١٨) والبخاري (٢٥٦٢)، ومسلم (٥:١٥٠٤).","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (18), al-Bukhari (2562), and Muslim (1504:5).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Umar said: The Mother of the Believers, ‘A’ishah, wanted to buy a slave girl in order to set her free, but her owners said: We will sell her to you on condition that her clientship remains with us. She mentioned that to the Messenger of Allah ﷺ, and he said, “That should not prevent you, for clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":18},{"key":"bukhari","label":"البخاري","number":2562},{"key":"muslim","label":"مسلم","number":5}]},{"num":6145,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ أنها قالت: جاءت بريرة، فقالت: إني كاتبت أهلي على تسع أواق، في كل عام أوقية، فأعينيني، فقالت عائشة: إن أحب أهلك أن أعدها لهم عنك عددتها، ويكون لي ولاؤك، فعلت. فذهبت بريرة إلى أهلها، فقالت لهم ذلك، فأبوا عليها، فجاءت من عند أهلها ورسول اللّٰه ﷺ جالس، فقالت لعائشة: إني قد عرضت عليهم ذلك، فأبوا علي إلا أن يكون الولاء لهم، فسمع ذلك رسول اللّٰه ﷺ، فسألها، فأخبرته عائشة، فقال رسول اللّٰه ﷺ: (( خذيها، واشترطي لهم الولاء، فإنما الولاء لمن أعتق )). ففعلت عائشة، ثم قام رسول اللّٰه ﷺ في الناس، فحمد الله، وأثنى عليه، ثم قال: (( أما بعد، فما بال رجال يشترطون شروطا ليست في كتاب الله، ما كان من شرط ليس في كتاب اللّٰه فهو باطل، وإن كان مائة شرط، قضاء اللّه أحق، وشرط اللّٰه أوثق، وإنما الولاء لمن أعتق ))."],"takhrij":"متفق عليه: رواه مالك (١٧) والبخاري (٢٧٢٩) ومسلم (٨:١٥٠٤).","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (17), al-Bukhari (2729), and Muslim (1504:8).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: Barirah came and said: I have made a contract with my family for nine ounces, one ounce each year, so help me. ‘A’ishah said: If your family would like me to count it out for them on your behalf, and your clientship will be mine, I will do it. So Barirah went to her family and told them that, but they refused. She returned while the Messenger of Allah ﷺ was sitting there and said to ‘A’ishah: I presented that to them, but they refused unless the clientship remains theirs. The Messenger of Allah ﷺ heard that and asked about it, so ‘A’ishah informed him. The Messenger of Allah ﷺ said: “Take her and stipulate clientship for them, for clientship belongs only to the one who emancipates.” So ‘A’ishah did that. Then the Messenger of Allah ﷺ stood before the people, praised Allah and extolled Him, then said: “Now then, what is the matter with people who make conditions not found in the Book of Allah? Any condition that is not in the Book of Allah is invalid, even if it be a hundred conditions. The decree of Allah has more right to be followed, and the condition of Allah is firmer. Clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"bukhari","label":"البخاري","number":2729},{"key":"muslim","label":"مسلم","number":8}]},{"num":6146,"demo":false,"sanad":"","matn":["عن عروة قال: إن عائشة أخبرته: أن بريرة جاءت عائشة تستعينها في كتابتها، ولم تكن قضت من كتابتها شيئا. فقالت لها عائشة: ارجعي إلى أهلك، فإن أحبوا أن أقضي عنك كتابتك، ويكون ولاؤك لي فعلت، فذكرت ذلك بريرة لأهلها، فأبوا، وقالوا: إن شاءت أن تحتسب عليك فلتفعل، ويكون لنا ولاؤك، فذكرت ذلك لرسول اللّٰه ﷺ، فقال لها رسول اللّٰه ﷺ: (( ابتاعي، فأعتقي، فإنما الولاء لمن أعتق )).","ثم قام رسول اللّٰه ﷺ، فقال: (( ما بال أناس يشترطون شروطا ليست فى كتاب الله، من اشترط شرطا ليس فى كتاب اللّٰه فليس له، وإن شرط مائة مرة، شرط اللّٰه أحق وأوثق ))."],"takhrij":"متفق عليه: رواه البخاري (٢٥٦١)، ومسلم (٦:١٥٠٤).","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2561) and Muslim (1504:6).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘Urwah said: ‘A’ishah told him that Barirah came to ‘A’ishah seeking her help with her contract of emancipation, and she had not yet paid anything of it. ‘A’ishah said to her: Return to your family; if they wish that I settle your contract for you and your clientship be mine, I will do so. Barirah mentioned that to her family, but they refused and said: If she wants to spend it for your sake as charity, let her do that, but your clientship will belong to us. She mentioned that to the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ said to her: “Buy her and free her, for clientship belongs only to the one who emancipates.”","Then the Messenger of Allah ﷺ stood and said: “What is the matter with people who stipulate conditions not found in the Book of Allah? Whoever stipulates a condition not found in the Book of Allah has no right to it, even if he stipulates it a hundred times. The condition of Allah is more rightful and more binding.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2561},{"key":"muslim","label":"مسلم","number":6}]},{"num":6147,"demo":false,"sanad":"","matn":["عن عائشة قالت: كان فى بريرة ثلاث قضيات: أراد أهلها أن يبيعوها، ويشترطوا ولاءها، فذكرت ذلك للنبي ﷺ فقال: (( اشتريها، وأعتقيها؛ فإن الولاء لمن أعتق )). قالت: وعتقت، فخيرها رسول اللّٰه ﷺ، فاختارت نفسها.","قالت: وكان الناس يتصدقون عليها، وتهدي لنا. فذكرت ذلك للنبي ﷺ، فقال: (( هو عليها صدقة، وهو لكم هدية، فكلوه ))."],"takhrij":"صحيح: رواه مسلم (١٠:١٥٠٤).","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1504:10).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah said: In the case of Barirah there were three rulings. Her owners wanted to sell her while stipulating that her clientship remain theirs, so I mentioned that to the Prophet ﷺ and he said: “Buy her and free her, for clientship belongs to the one who emancipates.” She was then freed, and the Messenger of Allah ﷺ gave her the choice, so she chose herself.","She said: People used to give charity to her, and she would give some of it to us as a gift. I mentioned that to the Prophet ﷺ, and he said: “For her it is charity, and for you it is a gift, so eat it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":10}]},{"num":6148,"demo":false,"sanad":"","matn":["عن عائشة أنها اشترت بريرة من أناس من الأنصار، واشترطوا الولاء، فقال رسول اللّٰه ﷺ: (( الولاء لمن ولي النعمة )). وخيرها رسول اللّه ﷺ، وكان زوجها عبدا، وأهدت لعائشة لحما، فقال رسول اللّٰه ﷺ: (( لو صنعتم لنا من هذا اللحم )). قالت عائشة: تصدق به على بريرة، فقال: (( هو لها صدقة، ولنا هدية ))."],"takhrij":"متفق عليه: رواه مسلم (١١:١٥٠٤)، والبخاري (٢٥٧٨).","grade":"متفق عليه","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1504:11) and al-Bukhari (2578).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah said: She bought Barirah from some of the Ansar, and they stipulated the clientship. The Messenger of Allah ﷺ said: “Clientship belongs to the one who bestowed the favor of emancipation.” The Messenger of Allah ﷺ gave her the choice, and her husband was a slave. Barirah gave meat as a gift to ‘A’ishah, so the Messenger of Allah ﷺ said: “If only you had prepared some of this meat for us.” ‘A’ishah said: It was given in charity to Barirah. He said: “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":11},{"key":"bukhari","label":"البخاري","number":2578}]},{"num":6149,"demo":false,"sanad":"","matn":["عن أيمن قال: دخلت على عائشة -رضي اللّٰه عنها-، فقلت: كنت غلاما لعتبة بن أبي لهب، ومات، وورثني بنوه، وإنهم باعوني من ابن أبي عمرو، فأعتقني ابن أبي عمرو، واشترط بنو عتبة الولاء، فقالت: دخلت بريرة، وهي مكاتبة، فقالت: اشتريني، وأعتقيني. قالت: نعم. قالت: لا يبيعوني حتى يشترطوا ولائي، فقالت: لا حاجة لي بذلك، فسمع بذلك النبي ﷺ، أو بلغه، فذكر لعائشة، فذكرت عائشة ما قالت لها، فقال: (( اشتريها، وأعتقيها، ودعيهم يشترطون ما شاؤوا )). فاشترتها عائشة، فأعتقتها، واشترط أهلها الولاء، فقال النبي ﷺ: (( الولاء لمن أعتق، وإن اشترطوا مائة شرط ))."],"takhrij":"صحيح: رواه البخاري (٢٥٦٥).","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2565).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Ayman said: I entered upon ‘A’ishah — may Allah be pleased with her — and said: I was a slave of ‘Utbah ibn Abi Lahab. He died, and his sons inherited me. They sold me to Ibn Abi ‘Amr, and Ibn Abi ‘Amr freed me, but the sons of ‘Utbah stipulated clientship. She said: Barirah once came in while she was under a contract of emancipation and said: Buy me and free me. I said: Yes. She said: They will not sell me unless they stipulate my clientship. So I said: I have no need for that. The Prophet ﷺ heard of this, or it reached him, and he mentioned it to ‘A’ishah. ‘A’ishah then told him what she had said to Barirah, so he said: “Buy her and free her, and let them stipulate whatever they wish.” So ‘A’ishah bought her and freed her, and her family stipulated the clientship. The Prophet ﷺ then said: “Clientship belongs to the one who emancipates, even if they stipulate a hundred conditions.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2565}]},{"num":6150,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: أرادت عائشة أن تشتري جارية تعتقها، فأبى أهلها إلا أن يكون لهم الولاء، فذكرت ذلك لرسول اللّٰه ﷺ فقال: (( لا يمنعك ذلك، فإنما الولاء لمن أعتق ))."],"takhrij":"صحيح: رواه مسلم (١٥٠٥).","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1505).","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah said: ‘A’ishah wanted to buy a slave girl in order to free her, but her family refused unless the clientship remained theirs. She mentioned that to the Messenger of Allah ﷺ, and he said: “That should not prevent you, for clientship belongs only to the one who emancipates.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1505}]},{"num":6151,"demo":false,"sanad":"","matn":["عن عائشة قالت: اشتريت بريرة، فاشترط أهلها ولاءها، فذكرت ذلك للنبي ﷺ فقال: (( أعتقيها؛ فإن الولاء لمن أعطى الورِق )). فأعتقتها، فدعاها النبي ﷺ، فخيرها من زوجها، فقالت: لو أعطاني كذا وكذا ما ثبتُّ عنده، فاختارت نفسها."],"takhrij":"صحيح: رواه البخاري (٢٥٣٦). وفي رواية عند البخاري (٦٧٦٠) وفيه: (( الولاء لمن أعطى الورق، ووَليَ النعمةَ )).","grade":"صحيح","chapter_ar":"باب إنما الولاء لمن أعتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2536). In another narration in al-Bukhari (6760), it says: “Clientship belongs to the one who paid the silver and bestowed the favor.”","chapter_en":"Chapter that clientship belongs only to the one who emancipates","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah said: I bought Barirah, and her family stipulated her clientship. I mentioned that to the Prophet ﷺ and he said: “Free her, for clientship belongs to the one who paid the silver.” So I freed her. Then the Prophet ﷺ called her and gave her the choice regarding her husband. She said: Even if he gave me such-and-such, I would not stay with him, so she chose herself."]},"buhuth":{"ar":["وقوله: (( ولي النعمة )) أي أعتق.","وفي الحديث دليل على أن الولاء لكل معتق، ذكرا كان، أو أنثى، وهو أمر يجمع عليه."],"en":["His statement, “bestowed the favor,” means: the one who emancipated.","This hadith is evidence that clientship belongs to every emancipator, whether male or female, and this is a matter of scholarly consensus."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2536},{"key":"وفی_روایہ_عند_البخاری","label":". وفي رواية عند البخاري","number":6760}]},{"num":6152,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عمر: أن رسول اللّٰه ﷺ نهى عن بيع الولاء، وعن هبته."],"takhrij":"متفق عليه: رواه مالك (٢٠) والبخاري (٢٥٣٥)، ومسلم (١٥٠٦).","grade":"متفق عليه","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (2535), and Muslim (1506).","chapter_en":"Chapter on the prohibition of selling or gifting clientship","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: The Messenger of Allah ﷺ forbade selling clientship and forbade gifting it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20},{"key":"bukhari","label":"البخاري","number":2535},{"key":"muslim","label":"مسلم","number":1506}]},{"num":6153,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول اللّٰه ﷺ: (( الولاء لحمة كلحمة النسب، لا يباع، ولا يوهب ))."],"takhrij":"صحيح: رواه ابن حبان (٤٩٥٠).","grade":"صحيح","chapter_ar":"باب النهي عن بيع الولاء وهبته","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban (4950).","chapter_en":"Chapter on the prohibition of selling or gifting clientship","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said, “Clientship is a bond like the bond of kinship; it is not to be sold and not to be gifted.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1896,"n":1893}]},{"num":6154,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: ما عندنا شيء إلا كتاب الله، وهذه الصحيفة عن النبي ﷺ: (( المدينة حرم ما بين عائر إلى كذا، من أحدث فيها حدثا، أو آوى محدثا فعليه لعنة اللّٰه والملائكة والناس أجمعين، لا يقبل منه صرف ولا عدل )).","وقال: (( ذمة المسلمين واحدة، فمن أخفر مسلما، فعليه لعنة اللّٰه والملائكة والناس أجمعين، لا يقبل منه صرف، ولا عدل، ومن تولى قوما بغير إذن مواليه فعليه لعنة اللّٰه والملائكة والناس أجمعين، لا يقبل منه صرف ولا عدل ))."],"takhrij":"متفق عليه: رواه البخاري (١٨٧٠)، ومسلم (٢٠:١٣٧٠). والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب الترهيب من أن ينتسب العتيق إلى غير مواليه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1870) and Muslim (1370:20). The wording is that of al-Bukhari.","chapter_en":"Chapter on the stern warning against a freed slave affiliating himself to other than his rightful patrons","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: We have nothing except the Book of Allah and this document from the Prophet ﷺ: “Madinah is a sanctuary between ‘Air and such-and-such. Whoever introduces an innovation in it or shelters an innovator, upon him is the curse of Allah, the angels, and all people together. No compulsory act nor voluntary ransom will be accepted from him.”","And he said: “The protection granted by the Muslims is one. Whoever violates the protection of a Muslim, upon him is the curse of Allah, the angels, and all people together. No compulsory act nor voluntary ransom will be accepted from him. And whoever affiliates himself with a people without the permission of his patrons, upon him is the curse of Allah, the angels, and all people together. No compulsory act nor voluntary ransom will be accepted from him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1870},{"key":"muslim","label":"مسلم","number":20}]},{"num":6155,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله قال: كتب النبي ﷺ على كل بطن عقوله، ثم كتب: (( أنه لا يحل لمسلم أن يتولى مولى رجل مسلم بغير إذنه )). ثم أخبرت أنه لعن فى صحيفته من فعل ذلك."],"takhrij":"صحيح: رواه مسلم (١٥٠٧).","grade":"صحيح","chapter_ar":"باب الترهيب من أن ينتسب العتيق إلى غير مواليه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1507).","chapter_en":"Chapter on the stern warning against a freed slave affiliating himself to other than his rightful patrons","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ prescribed the blood-money liabilities for every clan, then wrote: “It is not lawful for a Muslim to affiliate himself with the freedman of another Muslim without his permission.” Then I was informed that he cursed in his written document whoever does that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1507}]},{"num":6156,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( من تولى قوما بغير إذن مواليه فعليه لعنة اللّٰه والملائكة، لا يقبل منه عدل، ولا صرف ))."],"takhrij":"صحيح: رواه مسلم (١٨:١٥٠٨).","grade":"صحيح","chapter_ar":"باب الترهيب من أن ينتسب العتيق إلى غير مواليه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1508:18).","chapter_en":"Chapter on the stern warning against a freed slave affiliating himself to other than his rightful patrons","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever affiliates himself with a people without the permission of his patrons, upon him is the curse of Allah and the angels. No voluntary ransom nor obligatory compensation will be accepted from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18}]},{"num":6157,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله أن رجلا من الأنصار أعتق غلاما له عن دبر لم يكن له مال غيره، فبلغ ذلك النبي ﷺ، فقال: (( من يشتريه مني؟ )). فاشتراه نعيم بن عبد اللّٰه بثمانمائة درهم، فدفعها إليه. قال عمرو: سمعت جابر بن عبد الله يقول: عبدا قبطيا مات عام أول."],"takhrij":"متفق عليه: رواه البخاري (٢٥٣٤)، ومسلم (٥٨:٩٩٧). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في بيع المدبر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2534) and Muslim (997:58). The wording is that of Muslim.","chapter_en":"Chapter on selling a slave whose freedom is tied to the owner’s death","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: A man from the Ansar declared that his slave would be free after his death, and he had no wealth other than him. That reached the Prophet ﷺ, so he said: “Who will buy him from me?” Nu‘aym ibn ‘Abd Allah bought him for eight hundred dirhams, and he handed the money to the man. ‘Amr said: I heard Jabir ibn ‘Abd Allah say: He was a Coptic slave who died the previous year."]},"buhuth":{"ar":["قوله: ( عن دبر )) أي علق عتقه بموته؛ لأن الموت دبر الحياة."],"en":["His statement, “after his death,” means that he made the slave’s freedom conditional upon his death, because death comes at the end of life."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2534},{"key":"muslim","label":"مسلم","number":58}]},{"num":6158,"demo":false,"sanad":"","matn":["عن جابر قال: أعتق رجل من بني عُذْرة عبدا له عن دبر، فبلغ ذلك رسول اللّٰه ﷺ فقال: (( ألك مال غيره؟ )). فقال: لا. فقال: (( من يشتريه مني؟ )). فاشتراه نعيم بن عبد اللّٰه العدوي بثمانمائة درهم، فجاء بها رسول اللّٰه ﷺ، فدفعها إليه، ثم قال: (( ابدأ بنفسك، فتصدق عليها؛ فإن فضل شيء فلأهلك، فإن فضل عن أهلك شيء فلذي قرابتك، فإن فضل عن ذي قرابتك شيء فهكذا وهكذا )). يقول: فبين يديك، وعن يمينك، وشمالك."],"takhrij":"صحيح: رواه مسلم (٩٩٧)، والبخاري (٢٥٣٤) لأصل القصة.","grade":"صحيح","chapter_ar":"باب ما جاء في بيع المدبر","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (997), with al-Bukhari (2534) reporting the core incident.","chapter_en":"Chapter on selling a slave whose freedom is tied to the owner’s death","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Jabir said: A man from Banu ‘Udhrah declared his slave free after his death. That reached the Messenger of Allah ﷺ, so he said: “Do you have any wealth besides him?” He said: No. He said: “Who will buy him from me?” Nu‘aym ibn ‘Abd Allah al-‘Adawi bought him for eight hundred dirhams. The Messenger of Allah ﷺ brought the money and handed it to him, then said: “Begin with yourself and spend in charity on it. If anything remains, then it is for your family. If anything remains beyond your family, then for your relatives. If anything remains beyond your relatives, then like this and like this,” meaning in front of you, to your right, and to your left."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":997},{"key":"bukhari","label":"البخاري","number":2534}]},{"num":6159,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه يقول: كنا نبيع سرارينا، وأمهات أولادنا، والنبي ﷺ فينا، لا نرى بذلك بأسا."],"takhrij":"صحيح: رواه عبدالرزاق (١٣٢١١)، وعنه أحمد (١٤٤٤٦)، وابن ماجه (٢٥١٧)، وابن حبان (٤٣٢٣).","grade":"صحيح","chapter_ar":"باب بيع أمهات الأولاد","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by ‘Abd al-Razzaq (13211), from him Ahmad (14446), Ibn Majah (2517), and Ibn Hibban (4323).","chapter_en":"Chapter on selling slave mothers who bore children","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We used to sell our slave women and the slave mothers of our children while the Prophet ﷺ was among us, and we saw no harm in that."]},"buhuth":{"ar":["ورواه أبو داود (٣٩٥٠) من وجه آخر عن جابر بن عبد اللّٰه قال: بعنا أمهات الأولاد على عهد رسول اللّٰه وأبي بكر، فلما كان عمر نهانا فانتهينا."],"en":["Abu Dawud (3950) also narrated it through another route from Jabir ibn ‘Abd Allah, who said: We sold slave mothers during the time of the Messenger of Allah ﷺ and Abu Bakr, but when ‘Umar came, he forbade us, so we stopped."]}},"tuhfa":{},"refs":[{"key":"عبدالرزاق","label":"عبدالرزاق","number":13211},{"key":"عنہ_احمد","label":"عنه أحمد","number":14446},{"key":"ibnmajah","label":"ابن ماجه","number":2517},{"key":"ibnhibban","label":"ابن حبان","number":4323},{"key":"ahmad","label":"مسند الإمام أحمد","number":14446,"n":14446}]},{"num":6160,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه قال: كنا نبيع أمهات الأولاد على عهد رسول اللّٰه ﷺ وأبي بكر، فلما كان عمر نهى عن بيعهن."],"takhrij":"صحيح: رواه أبو داود (٣٩٥٤)، وابن حبان (٤٣٢٤)، والحاكم (٢١٩٠)، والبيهقي (١٠/٣٤٧).","grade":"صحيح","chapter_ar":"باب ما جاء أن عمر بن الخطاب هو الذي نهى عن بيع أمهات الأولاد","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3954), Ibn Hibban (4324), al-Hakim (2190), and al-Bayhaqi (10/347).","chapter_en":"Chapter stating that ‘Umar ibn al-Khattab was the one who forbade selling slave mothers","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We used to sell slave mothers during the time of the Messenger of Allah ﷺ and Abu Bakr. Then when ‘Umar came, he forbade selling them."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3954},{"key":"البیہقی","label":"البيهقي","number":10},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5968,"n":5965},{"key":"hakim","label":"المستدرك على الصحيحين","number":2190,"n":2182}]},{"num":6161,"demo":false,"sanad":"","matn":["عن حكيم بن حزام أنه أعتق في الجاهلية مائة رقبة، وحمل على مائة بعير، فلما أسلم حمل على مائة بعير، وأعتق مائة رقبة. قال: فسألت رسول اللّٰه ﷺ فقلت: يا رسول الله، أرأيت أشياء كنت أصنعها في الجاهلية كنت أتحنث بها، يعني أتبرر بها؟ قال: فقال رسول اللّٰه ﷺ: (( أسلمتَ على ما سلف لك من خير ))."],"takhrij":"متفق عليه: رواه البخاري (٢٥٣٨)، ومسلم (١٩٥:١٢٣)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب من أعتق في الجاهلية، ثم أسلم","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2538) and Muslim (123:195). The wording here is that of al-Bukhari.","chapter_en":"Chapter on one who freed slaves in the pre-Islamic period, then accepted Islam","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Hakim ibn Hizam reported that he freed one hundred slaves in the pre-Islamic period and provided one hundred camels for riding. Then when he accepted Islam, he again provided one hundred camels and freed one hundred slaves. He said: So I asked the Messenger of Allah ﷺ and said: O Messenger of Allah ﷺ, what do you think of things I used to do in the pre-Islamic period by which I sought devotion, meaning acts of righteousness? The Messenger of Allah ﷺ said: “You accepted Islam upon the good that had already passed for you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2538},{"key":"muslim","label":"مسلم","number":195}]},{"num":6162,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: خرجنا مع رسول اللّٰه ﷺ في غزوة بني المصطلق، فأصبنا سبيا من سبي العرب، فاشتهينا النساء، واشتدت علينا العزبة، وأحببنا الفداء، فأردنا أن نعزل، فقلنا: نعزل ورسول اللّٰه ﷺ بين أظهرنا قبل أن نسأله؟ فسألناه عن ذلك، فقال: (( ما عليكم أن لا تفعلوا، ما من نسمة كائنة إلى يوم القيامة إلا وهي كائنة ))."],"takhrij":"متفق عليه: رواه مالك (٩٥)، والبخاري (٢٥٤٢)، ومسلم (١٢٧:١٤٣٨).","grade":"متفق عليه","chapter_ar":"باب اتخاذ الرقيق من العرب","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (95), al-Bukhari (2542), and Muslim (1438:127).","chapter_en":"Chapter on taking slaves from among the Arabs","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: We went out with the Messenger of Allah ﷺ on the expedition of Banu al-Mustaliq, and we captured some Arab prisoners. We desired women, celibacy had become difficult for us, and we wanted ransom money, so we intended to practice withdrawal. Then we said: Shall we practice withdrawal while the Messenger of Allah ﷺ is among us before asking him? So we asked him about that, and he said: “There is no blame upon you if you do not do it. No soul that is to exist until the Day of Resurrection except that it will surely come into existence.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":95},{"key":"bukhari","label":"البخاري","number":2542},{"key":"muslim","label":"مسلم","number":127}]},{"num":6163,"demo":false,"sanad":"","matn":["عن ابن عون قال: كتبت إلى نافع، فكتب إلي أن النبي ﷺ أغار على بني المصطلق وهم غارون، وأنعامهم تُسقى على الماء، فقتل مقاتلتهم، وسبى ذراريهم، وأصاب يومئذ جويرية. حدثني به عبد الله بن عمر، وكان في ذلك الجيش."],"takhrij":"متفق عليه: رواه البخاري (٢٥٤١)، ومسلم (١٧٣٠)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب اتخاذ الرقيق من العرب","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2541) and Muslim (1730). The wording here is that of al-Bukhari.","chapter_en":"Chapter on taking slaves from among the Arabs","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Ibn ‘Awn said: I wrote to Nafi‘, and he wrote back to me that the Prophet ﷺ raided Banu al-Mustaliq while they were heedless and their livestock were being watered at the water source. He killed their fighters, took their children captive, and Juwayriyyah was taken that day. ‘Abd Allah ibn ‘Umar told me this, and he was in that army."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2541},{"key":"muslim","label":"مسلم","number":1730}]},{"num":6164,"demo":false,"sanad":"","matn":["عن أبي هريرة أنه لما أقبل يريد الإسلام، ومعه غلامه، ضل كل واحد منهما من صاحبه، فأقبل بعد ذلك، وأبو هريرة جالس مع النبي ﷺ، فقال النبي ﷺ: (( يا أبا هريرة، هذا غلامك قد أتاك )). فقال: أما إني أشهدك أنه حر. قال فهو حين يقول:","يا ليلةً من طولها وعنائها","على أنها من دارة الكفر نجت"],"takhrij":"صحيح: رواه البخاري (٢٥٣٠).","grade":"صحيح","chapter_ar":"باب الإشهاد في العتق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2530).","chapter_en":"Chapter on having witnesses for emancipation","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah reported that when he was coming to accept Islam, and his servant was with him, each of them lost the other. Later the servant came while Abu Hurayrah was sitting with the Prophet ﷺ, and the Prophet ﷺ said: “O Abu Hurayrah, this is your servant; he has come to you.” So he said: I make you my witness that he is free. Then he began reciting:","“What a night of its length and hardship,","yet it has been saved from the abode of disbelief.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2530}]},{"num":6165,"demo":false,"sanad":"","matn":["عن جرير بن عبد اللّٰه البجلي قال: قال رسول اللّٰه ﷺ: (( أيما عبد أبق من مواليه فقد كفر حتى يرجع إليهم )). وفي لفظ: (( أيما عبد أبق فقد برئت منه الذمة )). وفي لفظ آخر: (( إذا أبق العبد لم تقبل له صلاة ))."],"takhrij":"صحيح: رواه مسلم (٦٨)، واللفظ الثاني عنده (٦٩)، واللفظ الأخير عنده أيضا (٧٠).","grade":"صحيح","chapter_ar":"باب ما جاء في الوعيد الشديد في العبد الآبق","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (68). The second wording is also in Muslim (69), and the last wording is likewise in Muslim (70).","chapter_en":"Chapter on the severe warning concerning the runaway slave","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Jarir ibn ‘Abd Allah al-Bajali reported that the Messenger of Allah ﷺ said: “Any slave who runs away from his masters has committed disbelief until he returns to them.” In another wording: “Any slave who runs away is free of protection.” In yet another wording: “When a slave runs away, his prayer is not accepted.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":68},{"key":"اللفظ_الثانی_عندہ","label":"اللفظ الثاني عنده","number":69},{"key":"اللفظ_الاخیر_عندہ_ایضا","label":"اللفظ الأخير عنده أيضا","number":70}]},{"num":6166,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( ولد الزنا شر الثلاثة )). قال أبو هريرة: لأن أمتع بسوط في سبيل اللّٰه أحب إلي من أن أعتق ولد زنية."],"takhrij":"صحيح: رواه أبو داود (٣٩٦٣)، وأحمد (٨٠٩٨)، والحاكم (٢١٤/٢)، والبيهقي (١٠/٥٧، ٥٩).","grade":"صحيح","chapter_ar":"باب عتق ولد الزنا","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3963), Ahmad (8098), al-Hakim (2/214), and al-Bayhaqi (10/57, 59).","chapter_en":"Chapter on freeing the child of fornication","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The child of fornication is the worst of the three.” Abu Hurayrah said: That I provide a whip for use in the path of Allah is more beloved to me than that I free a child born of fornication."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3963},{"key":"البیہقی","label":"البيهقي","number":10},{"key":"ahmad","label":"مسند الإمام أحمد","number":8098,"n":8098},{"key":"hakim","label":"المستدرك على الصحيحين","number":2853,"n":2839},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":19991,"n":20149}]},{"num":6167,"demo":false,"sanad":"","matn":["عن أبي حبيبة الطائي قال: أوصى إليَّ أخي بطائفة من ماله، فلقيت أبا الدرداء، فقلت: إن أخي أوصى إليَّ بطائفة من ماله، فأين ترى لي وضعه: في الفقراء، أو المساكين، أو المجاهدين في سبيل اللّه؟ فقال: أما أنا فلو كنت لم أعدل بالمجاهدين. سمعت رسول اللّه ﷺ يقول: (( مثل الذي يعتق عند الموت كمثل الذي يهدي إذا شبع ))."],"takhrij":"حسن: رواه أبو داود (٣٩٦٨)، والترمذي (٢١٢٣)، والنسائي (٦/٢٣٨)، وأحمد (٢١٧١٨، ٢١٧١٩).","grade":"حسن","chapter_ar":"باب فضل العتق في الصحة","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3968), al-Tirmidhi (2123), al-Nasa’i (6/238), and Ahmad (21718, 21719).","chapter_en":"Chapter on the virtue of freeing slaves while one is healthy","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abu Habibah al-Ta’i said: My brother entrusted me with disposing of part of his wealth, so I met Abu al-Darda’ and said: My brother entrusted me with part of his wealth; where do you think I should place it: among the poor, the needy, or the fighters in the path of Allah? He said: As for me, if it were my choice, I would not prefer anyone over the fighters in the path of Allah. I heard the Messenger of Allah ﷺ say: “The one who frees a slave at the time of death is like one who gives a gift after becoming full.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3968},{"key":"tirmidhi","label":"الترمذي","number":2123},{"key":"nasai","label":"النسائي","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":21718,"n":21718}]},{"num":6168,"demo":false,"sanad":"","matn":["عن سفينة أبي عبد الرحمن قال: أعتقتني أم سلمة، فاشترطتْ عليَّ أن أخدم النبي ﷺ ما عاش."],"takhrij":"حسن: رواه أبو داود (٣٩٣٢)، وابن ماجه (٢٥٢٦)، وأحمد (٢١٩٢٧)، والحاكم (٢/٢١٣-٢١٤).","grade":"حسن","chapter_ar":"باب من أعتق عبدا واشترط خدمته","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3932), Ibn Majah (2526), Ahmad (21927), and al-Hakim (2/213–214).","chapter_en":"Chapter on one who frees a slave and stipulates his service","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["Safinah Abu ‘Abd al-Rahman said: Umm Salamah freed me, but stipulated that I would serve the Prophet ﷺ as long as he lived."]},"buhuth":{"ar":["الشرط على قسمين:","شرط يفي به العبد، سواء اشترط، أو لم يشترط، فقد روي عن سفينة قال: كنت مملوكا لأم سلمة فقالت: أعتقك، وأشترط عليك أن تخدم رسول اللّٰه ﷺ ما عشت. فقلت: إن لم تشترطي عليَّ ما فارقت رسول اللّٰه ﷺ ما عشت، فأعتقتني.","وشرط مخالف لحرية العبد، مثل أن يشترط أن يدفع كل شهر كذا من المال ما عاش، وأن لا يتزوج. فهذا شرط فاسد، سواء قبل، أو لم يقبل، وهو بمجرد النطق بالحرية يكون حرا، وليس عليه الوفاء بهذا الشرط؛ لأن الأصل في الإنسان الحرية. (انظر شرح السنة ٧٧/٩)."],"en":["Conditions are of two kinds:","A condition that the slave would fulfill whether it was stipulated or not. It is reported from Safinah that he said: I was owned by Umm Salamah, and she said: I free you, but I stipulate that you serve the Messenger of Allah ﷺ as long as you live. So I said: Even if you did not make that condition upon me, I would never leave the Messenger of Allah ﷺ as long as I lived. So she freed me.","And a condition that conflicts with the freedom of the slave, such as stipulating that he must pay a certain amount of money every month for life, or that he may not marry. This is an invalid condition whether he accepts it or not. Once freedom is declared, he becomes free immediately, and he is not required to fulfill such a condition, because the basic rule regarding a human being is freedom. (See Sharh al-Sunnah, 9/77)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3932},{"key":"ibnmajah","label":"ابن ماجه","number":2526},{"key":"ahmad","label":"مسند الإمام أحمد","number":21927,"n":21927},{"key":"hakim","label":"المستدرك على الصحيحين","number":6549,"n":6547}]},{"num":6169,"demo":false,"sanad":"","matn":["عن زاذان أبي عمر قال: أتيت ابن عمر، وقد أعتق مملوكا. قال: فأخذ من الأرض عودا أو شيئا، فقال: ما فيه من الأجر ما يساوي هذا، إلا أني سمعت رسول اللّٰه ﷺ يقول: (( من لطم مملوكه، أو ضربه فكفارته أن يعتقه ))."],"takhrij":"صحيح: رواه مسلم (١٦٥٧).","grade":"صحيح","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1657).","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Zadhan Abu ‘Umar said: I came to Ibn ‘Umar after he had freed a slave. He picked up a twig or something from the ground and said: The reward in it does not equal even this, except that I heard the Messenger of Allah ﷺ say: “Whoever slaps his slave or beats him, then the expiation for that is to free him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1657}]},{"num":6170,"demo":false,"sanad":"","matn":["عن معاوية بن سويد قال: لطمت مولى لنا فهربت، ثم جئت قبيل الظهر، فصليت خلف أبي، فدعاه ودعاني، ثم قال: امتثل منه. فعفا، ثم قال: كنا بني مقرن على عهد رسول اللّه ﷺ ليس لنا إلا خادم واحدة، فلطمها أحدنا، فبلغ ذلك النبي ﷺ، فقال: (( أعتقوها )). قالوا: ليس لهم خادم غيرها. قال: (( فليستخدموها، فإذا استغنوا عنها، فليخلوا سبيلها ))."],"takhrij":"صحيح: رواه مسلم (١٦٥٨).","grade":"صحيح","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1658).","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Mu‘awiyah ibn Suwayd said: I slapped a servant of ours, so I fled. Then I returned shortly before noon and prayed behind my father. He called him and called me, then said: Let him retaliate against you. But the servant forgave me. Then he said: We, the family of Muqarrin, only had one servant during the time of the Messenger of Allah ﷺ, and one of us slapped her. That reached the Prophet ﷺ, so he said: “Free her.” They said: They have no servant besides her. He said: “Then let them employ her, and when they no longer need her, let them set her free.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1658}]},{"num":6171,"demo":false,"sanad":"","matn":["عن أبي مسعود الأنصاري قال: كنت أضرب غلاما لي، فسمعت من خلفي صوتا: (( اعلم أبا مسعود، اللّٰه أقدر عليك منك عليه )). فالتفت، فإذا هو رسول اللّٰه ﷺ، فقلت: يا رسول الله، هو حر لوجه الله. فقال: (( أما لو لم تفعل للفحتك النار، أو لمستك النار ))."],"takhrij":"صحيح: رواه مسلم (٣٥:١٦٥٩). وفي رواية: (( اعلم أبا مسعود، إن اللّٰه أقدر عليك منك على هذا الغلام )).","grade":"صحيح","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1659:35). In another narration: “Know, O Abu Mas‘ud, Allah has more power over you than you have over this servant.”","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abu Mas‘ud al-Ansari said: I was beating a servant of mine when I heard a voice from behind me saying: “Know, O Abu Mas‘ud, Allah has more power over you than you have over him.” I turned and it was the Messenger of Allah ﷺ. So I said: O Messenger of Allah ﷺ, he is free for the sake of Allah. He said: “Had you not done so, the Fire would have scorched you,” or, “the Fire would have touched you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":35}]},{"num":6172,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: جاء رجل إلى النبي ﷺ صارخا، فقال له رسول اللّٰه ﷺ: (( مالك؟ )). قال: سيدي رآني أقبل جارية له فجبّ مذاكيري. فقال النبي ﷺ: (( عليَّ بالرجل )). فطلب، فلم يقدر عليه. فقال رسول اللّٰه ﷺ: (( اذهب، فأنت حر )). قال: على من نصرتي يا رسول اللّٰه؟ قال: يقول: أرأيت إن استرقني مولاي؟ فقال رسول اللّٰه ﷺ: (( على كل مؤمن، أو مسلم ))."],"takhrij":"حسن: رواه أبو داود (٤٥١٩)، وابن ماجه (٢٦٨٠).","grade":"حسن","chapter_ar":"باب كفارة من ظلم غلامه أن يعتقه","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4519) and Ibn Majah (2680).","chapter_en":"Chapter that the expiation for one who wrongs his servant is to free him","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb narrated from his father, from his grandfather: A man came to the Prophet ﷺ shouting. The Messenger of Allah ﷺ said to him: “What is the matter with you?” He said: My master saw me kissing a slave-girl of his, so he cut off my private parts. The Prophet ﷺ said: “Bring me the man.” They searched for him but could not find him. So the Messenger of Allah ﷺ said: “Go, for you are free.” He said: Upon whom is my support, O Messenger of Allah ﷺ? He meant: What if my master enslaves me again? The Messenger of Allah ﷺ said: “Upon every believer,” or, “every Muslim.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4519},{"key":"ibnmajah","label":"ابن ماجه","number":2680}]},{"num":6173,"demo":false,"sanad":"","matn":["عن ابن عمر قال قال رسول اللّٰه ﷺ: (( من أعتق عبدا وله مال، فمال العبد له إلا أن يشترط السيد ماله فيكون له ))."],"takhrij":"صحيح: رواه أبو داود (٣٩٦٢)، وابن ماجه (٢٥٢٩).","grade":"صحيح","chapter_ar":"باب من أعتق عبدا وله مال","chapter_ur":"","part_ar":"كتاب العتق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3962) and Ibn Majah (2529).","chapter_en":"Chapter on one who frees a slave who owns property","part_en":"The Book of Emancipation","group_ar":"","group_en":"","part_no":23,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “Whoever frees a slave who owns property, then the property of the slave belongs to the slave, unless the master stipulates his property, in which case it belongs to him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3962},{"key":"ibnmajah","label":"ابن ماجه","number":2529}]},{"num":6174,"demo":false,"sanad":"","matn":["عن ابن عباس أن النبي ﷺ قال: « الحمد لله نحمده ونستعينه، من يهده الله فلا مضل له، ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله وحده لا شريك له، وأن محمدا عبده ورسوله، أما بعد: »."],"takhrij":"صحيح: رواه مسلم (٨٦٨).","grade":"صحيح","chapter_ar":"باب خطبة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (868).","chapter_en":"Chapter on the marriage sermon","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ said:","“All praise is for Allah. We praise Him and seek His help. Whomever Allah guides, none can misguide; and whomever He leaves astray, none can guide. I bear witness that there is no god except Allah alone, without partner, and that Muhammad is His servant and His Messenger. To proceed:”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":868}]},{"num":6175,"demo":false,"sanad":"","matn":["عن ابن مسعود قال:","أوتي رسول الله ﷺ جوامع الخير وخواتمه، أو قال: فواتح الخير، فعلّمنا خطبة الصلاة وخطبة الحاجة.","خطبة الصلاة:","«التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ».","وخطبة الحاجة:","«إِنَّ الْحَمْدَ لِلَّهِ، نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ، وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ».","ثم تصل خطبتك بثلاث آيات من كتاب الله:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ﴾","[آل عمران: ١٠٢]","﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا﴾","[النساء: ١]","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا ۝ يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا﴾","[الأحزاب: ٧٠-٧١]"],"takhrij":"صحيح: رواه أبو داود (٢١١٨)، والترمذي (١١٠٥) وحسنه، والنسائي (٣٢٧٧)، وابن ماجه (١٨٩٢).","grade":"صحيح","chapter_ar":"باب خطبة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2118), al-Tirmidhī (1105), who graded it Hasan, al-Nasāʾī (3277), and Ibn Mājah (1892).","chapter_en":"Chapter on the marriage sermon","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd reported:","The Messenger of Allah ﷺ was given comprehensive expressions of goodness and their conclusions—or he said, their beginnings. He taught us the tashahhud of prayer and the sermon of need.","The tashahhud of prayer is:","“All greetings are for Allah, as are the prayers and all good things. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god except Allah, and I bear witness that Muhammad is His servant and Messenger.”","The sermon of need is:","“Indeed, all praise belongs to Allah. We praise Him, seek His help, and seek His forgiveness. We seek refuge in Allah from the evils within ourselves and from our bad deeds. Whomever Allah guides, none can misguide; and whomever He leaves astray, none can guide. I bear witness that there is no god except Allah alone, without partner, and I bear witness that Muhammad is His servant and Messenger.”","Then connect your sermon with three verses from the Book of Allah:","“O you who believe, fear Allah as He should truly be feared, and do not die except as Muslims.”","[Āl ʿImrān: 102]","“O mankind, fear your Lord, who created you from a single soul, and created from it its mate, and spread from the two many men and women. And fear Allah, through whom you ask one another, and the ties of kinship. Indeed, Allah is ever Watchful over you.”","[al-Nisāʾ: 1]","“O you who believe, fear Allah and speak words that are right. He will set right your deeds for you and forgive your sins. And whoever obeys Allah and His Messenger has certainly attained a great triumph.”","[al-Aḥzāb: 70–71]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2118},{"key":"tirmidhi","label":"الترمذي","number":1105},{"key":"nasai","label":"النسائي","number":3277},{"key":"ibnmajah","label":"ابن ماجه","number":1892}]},{"num":6176,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: (( كل خطبة ليس فيها تشهد فهي كاليد الجذماء ))."],"takhrij":"حسن: رواه أبو داود (٤٨٤١)، والترمذي (١١١٨)، وأحمد (٨٠١٨)، وابن حبان في صحيحه (٢٧٩٦).","grade":"حسن","chapter_ar":"باب خطبة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4841), al-Tirmidhi (1118), Ahmad (8018), and Ibn Hibban in his Sahih (2796).","chapter_en":"Chapter on the marriage sermon","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “Every sermon in which there is no declaration of faith is like a severed hand.”"]},"buhuth":{"ar":["والجذماء: المقطوعة أي اليد التي لا يستفاد منها."],"en":["“Severed” means cut off, meaning a hand from which no benefit is taken."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4841},{"key":"tirmidhi","label":"الترمذي","number":1118},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":2796},{"key":"ahmad","label":"مسند الإمام أحمد","number":8018,"n":8018},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4626,"n":4622}]},{"num":6177,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: جاء ثلاثة رهط إلى بيوت أزواج النبي ﷺ يسألون عن عبادة النبي ﷺ، فلما أخبروا كأنهم تقالّوها، فقالوا: وأين نحن من النبي ﷺ؟ قد غفر الله له ما تقدم من ذنبه وما تأخر. قال أحدهم: أما أنا فأصلي الليل أبدا. وقال آخر: وأنا أصوم الدهر ولا أفطر. وقال آخر: أنا أعتزل النساء فلا أتزوج أبدا. فجاء رسول الله ﷺ، فقال: (( أنتم الذين قلتم كذا وكذا؟ أما والله إني لأخشاكم لله وأتقاكم له، لكني أصوم وأفطر، وأصلي وأرقد، وأتزوج النساء، فمن رغب عن سنتي فليس مني ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٦٣)، ومسلم (١٤٠١).","grade":"متفق عليه","chapter_ar":"باب الزواج من سنن المرسلين والمتقين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5063) and Muslim (1401).","chapter_en":"Chapter on marriage being from the practice of the messengers and the righteous","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: Three men came to the houses of the wives of the Prophet ﷺ asking about the worship of the Prophet ﷺ. When they were informed, they seemed to think it little. They said: Where are we compared to the Prophet ﷺ, when Allah has forgiven his past and future sins? One of them said: As for me, I will pray all night forever. Another said: I will fast continuously and never break my fast. Another said: I will keep away from women and never marry. Then the Messenger of Allah ﷺ came and said: “Are you the ones who said such and such? By Allah, I am the one among you who fears Allah most and is most mindful of Him, but I fast and I break the fast, I pray and I sleep, and I marry women. So whoever turns away from my way is not of me.”"]},"intro":{"ar":["قال الله تعالى: (وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً) [الرعد: ٣٨]","وقال تعالى: (وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا) [الفرقان: ٧٤]"],"en":["Allah Most High said:","“And We certainly sent messengers before you, and We made for them wives and offspring.” [Al-Ra‘d: 38]","And He said:","“And those who say: Our Lord, grant us from our spouses and our offspring comfort to our eyes, and make us leaders for the righteous.” [Al-Furqan: 74]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5063},{"key":"muslim","label":"مسلم","number":1401}]},{"num":6178,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: قال لي ابن عباس: هل تزوجت؟ قلت: لا. قال: فتزوج؛ فإن خير هذه الأمة أكثرها نساء."],"takhrij":"صحيح: رواه البخاري (٥٠٦٩).","grade":"صحيح","chapter_ar":"باب الزواج من سنن المرسلين والمتقين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5069).","chapter_en":"Chapter on marriage being from the practice of the messengers and the righteous","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Sa‘id ibn Jubayr said: Ibn ‘Abbas said to me: Have you married? I said: No. He said: Then marry, for the best of this community were those who had the most wives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5069}]},{"num":6179,"demo":false,"sanad":"","matn":["عن علقمة قال: كنت أمشي مع عبد الله بمنى، فلقيه عثمان، فقام معه يحدثه. فقال له عثمان: يا أبا عبد الرحمن، ألا نزوجك جارية شابة لعلها تذكرك بعض ما مضى من زمانك. قال: فقال عبد الله: لئن قلت ذاك، لقد قال لنا رسول الله ﷺ: (( يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم، فإنه له وجاء ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٦٥)، ومسلم (١:١٤٠٠). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5065) and Muslim (1400:1). The wording here is that of Muslim.","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘Alqamah said: I was walking with ‘Abd Allah at Mina when ‘Uthman met him and stood speaking with him. ‘Uthman said to him: O Abu ‘Abd al-Rahman, shall we not marry you to a young woman? Perhaps she may remind you of some of what has passed from your earlier days. ‘Abd Allah said: If you say that, then indeed the Messenger of Allah ﷺ said to us: “O company of young men, whoever among you is able to marry, let him marry, for it is more effective in lowering the gaze and better in guarding chastity. And whoever is not able, then he should fast, for it is a restraint for him.”"]},"buhuth":{"ar":["والباءة معناها الجماع، وأصلها المكان الذي يأوي إليه الإنسان، وسمي النكاح بها؛ لأن من تزوج امرأة بوأها منزلا. (( شرح السنة )) (٤/٩)"],"en":["The word used here means sexual ability. Originally it refers to the place where a person resides, and marriage was called by this term because whoever marries a woman settles her in a home. (Sharh al-Sunnah, 4/9)"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5065},{"key":"muslim","label":"مسلم","number":1}]},{"num":6180,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: قال لي ابن عباس: هل تزوجت؟ قلت: لا، قال: فتزوج، فإن خير هذه الأمة أكثرها نساء."],"takhrij":"صحيح: رواه البخاري في النكاح (٥٠٦٩).","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari in the Book of Marriage (5069).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Sa‘id ibn Jubayr said: Ibn ‘Abbas said to me: Have you married? I said: No. He said: Then marry, for the best of this nation were those with the most wives."]}},"tuhfa":{},"refs":[{"key":"bukhari/النکاح","label":"البخاري في النكاح","number":5069}]},{"num":6181,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود قال: كنا نغزو مع رسول الله ﷺ وليس لنا شيء، فقلنا: ألا نستخصي؟ فنهانا عن ذلك، ثم رخص لنا أن ننكح المرأة بالثوب، ثم قرأ علينا: (يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللَّهُ لَكُمْ وَلَا تَعْتَدُوا ۚ إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ) [المائدة: ٨٧]"],"takhrij":"متفق عليه: رواه البخاري (٥٠٧٥)، ومسلم (١٤٠٤). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5075) and Muslim (1404). The wording here is that of al-Bukhari.","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘Abd Allah ibn Mas‘ud said: We used to go out in battle with the Messenger of Allah ﷺ while we had nothing, so we said: Should we not castrate ourselves? He forbade us from that. Then he permitted us to marry a woman in exchange for a garment. Then he recited to us:","“O you who believe, do not forbid the good things Allah has made lawful for you, and do not transgress. Surely Allah does not love the transgressors.” [Al-Ma’idah: 87]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5075},{"key":"muslim","label":"مسلم","number":1404}]},{"num":6182,"demo":false,"sanad":"","matn":["عن سعد بن أبي وقاص قال: رد رسول الله ﷺ على عثمان بن مظعون التبتل، ولو أذن له لاختصينا."],"takhrij":"متفق عليه: رواه البخاري (٥٠٧٣)، ومسلم (٧:١٤٠٢).","grade":"متفق عليه","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5073) and Muslim (1402:7).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: The Messenger of Allah ﷺ rejected celibacy for ‘Uthman ibn Maz‘un, and if he had allowed him, we would have castrated ourselves."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5073},{"key":"muslim","label":"مسلم","number":7}]},{"num":6183,"demo":false,"sanad":"","matn":["عن سعد بن أبي وقاص قال: لما كان من أمر عثمان بن مظعون الذي كان من ترك النساء بعث إليه رسول الله ﷺ فقال: (( يا عثمان، إني لم أؤمر بالرهبانية، أرغبت عن سنتي؟ )) قال: لا، يا رسول الله. قال: (( إن من سنتي أن أصلي وأنام، وأصوم وأطعم، وأنكح وأطلق، فمن رغب عن سنتي فليس مني، يا عثمان، إن لأهلك عليك حقا، ولنفسك عليك حقا )).","قال سعد: فوالله لقد كان أجمع رجال من المسلمين على أن رسول الله ﷺ إن هو أقر عثمان على ما هو عليه أن نختصي فنتبتل."],"takhrij":"حسن: رواه الدارمي (٢٢١٥).","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Darimi (2215).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: When the matter of ‘Uthman ibn Maz‘un occurred regarding his leaving women aside, the Messenger of Allah ﷺ sent for him and said: “O ‘Uthman, I was not commanded with monasticism. Have you turned away from my way?” He said: No, O Messenger of Allah. He said: “Part of my way is that I pray and I sleep, I fast and I eat, and I marry and divorce. Whoever turns away from my way is not of me. O ‘Uthman, your family has a right over you, and your own self has a right over you.”","Sa‘d said: By Allah, the Muslim men were on the verge of agreeing that if the Messenger of Allah ﷺ had approved ‘Uthman in what he was doing, we would have castrated ourselves and lived in celibacy."]},"buhuth":{"ar":["قوله: (( التبتل )) أصله القطع. والمراد الانقطاع عن النساء وترك النكاح انقطاعا إلى عبادة الله.","قوله: (( لاختصينا )) الخصاء هو نزع البيضتين من الخصيتين بشق جلدها."],"en":["His statement, “celibacy,” originally means cutting off. What is meant is cutting oneself off from women and leaving marriage in order to devote oneself entirely to worship of Allah.","His statement, “we would have castrated ourselves,” means removing the two testicles by cutting the skin covering them."]}},"tuhfa":{},"refs":[{"key":"darimi","label":"سنن الدارمي","number":2104,"n":2104}]},{"num":6184,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قلت يا رسول الله ﷺ إني رجل شاب، وأنا أخاف على نفسي العنت ولا أجد ما أتزوج به النساء، فسكت عني، ثم قلت مثل ذلك، فسكت عني، ثم قلت له مثل ذلك، فسكت عني. ثم قلت مثل ذلك. فقال النبي ﷺ: (( يا أبا هريرة، جف القلم بما أنت لاق، فاختص على ذلك أو ذر ))."],"takhrij":"صحيح: رواه البخاري (٥٠٧٦).","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5076).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: I said: O Messenger of Allah, I am a young man, and I fear hardship for myself, and I do not find what I can marry women with. He remained silent toward me. Then I said the same again, and he remained silent. Then I said it again, and he remained silent. Then I said it again, so the Prophet ﷺ said: “O Abu Hurayrah, the pen has dried regarding what you are going to meet, so castrate yourself on that basis or leave it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5076}]},{"num":6185,"demo":false,"sanad":"","matn":["عن أنس أن النبي ﷺ خرج على فتية من شباب قريش، فقال: (( يا معشر الشباب من استطاع منكم الطول فلينكح، أو فليتزوج، وإلا فعليه بالصوم، فإنه له وجاء ))."],"takhrij":"صحيح: رواه البزار - كشف الأستار (١٣٩٨).","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar in Kashf al-Astar (1398).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ came out to a group of young men from Quraysh and said: “O company of young men, whoever among you has the means, let him marry; otherwise he should fast, for it is a restraint for him.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1398},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1398,"n":1399}]},{"num":6186,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: كان رسول الله ﷺ يأمر بالباءة، وينهى عن التبتل نهيا شديدا، ويقول: (( تزوجوا الودود الولود، إني مكاثر الأنبياء يوم القيامة ))."],"takhrij":"حسن: رواه أحمد (١٢٦١٣)، والبزار - كشف الأستار (١٤٠٠).","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (12613) and al-Bazzar in Kashf al-Astar (1400).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Malik said: The Messenger of Allah ﷺ used to command marriage and strongly forbid celibacy, and he would say: “Marry the loving and fertile woman, for I will boast of your numbers before the prophets on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1400},{"key":"ahmad","label":"مسند الإمام أحمد","number":12613,"n":12613},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1400,"n":1401}]},{"num":6187,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسول الله ﷺ: (( يا شباب قريش، لا تزنوا، احفظوا فروجكم، ألا من حفظ فرجه فله الجنة ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٤٠١)، والطبراني في الكبير (١٢/١٦٥)، واللفظ للبزار.","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1401) and al-Tabarani in al-Kabir (12/165). The wording here is that of al-Bazzar.","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ said: “O youth of Quraysh, do not commit fornication. Guard your private parts. Indeed, whoever guards his chastity will have Paradise.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1401},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":12},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1401,"n":1402}]},{"num":6188,"demo":false,"sanad":"","matn":["عن سمرة أن النبي ﷺ نهى عن التبتل."],"takhrij":"صحيح: رواه الترمذي (١٠٨٢)، وابن ماجه (١٨٤٩)، والنسائي (٣٢١٤)، وأحمد (٢٠١٩٢).","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1082), Ibn Majah (1849), al-Nasa’i (3214), and Ahmad (20192).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Samurah reported that the Prophet ﷺ forbade celibacy."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1082},{"key":"ibnmajah","label":"ابن ماجه","number":1849},{"key":"nasai","label":"النسائي","number":3214},{"key":"ahmad","label":"مسند الإمام أحمد","number":20192,"n":20192}]},{"num":6189,"demo":false,"sanad":"","matn":["عن عائشة أن النبي ﷺ نهى عن التبتل."],"takhrij":"صحيح: رواه النسائي (٣٢١٣)، وأحمد (٢٤٩٤٣).","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3213) and Ahmad (24943).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ forbade celibacy."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3213},{"key":"ahmad","label":"مسند الإمام أحمد","number":24943,"n":24943}]},{"num":6190,"demo":false,"sanad":"","matn":["عن عائشة قالت: دخلت امرأة عثمان بن مظعون واسمها خولة بنت حكيم على عائشة وهي باذة الهيئة، فسألتها ما شأنك؟ فقالت: زوجي يقوم الليل، ويصوم النهار. فدخل النبي ﷺ فذكرت ذلك له عائشة. فلقي النبي ﷺ فقال: (( يا عثمان، إن الرهبانية لم تكتب علينا، أما لك في أسوة؟ فوالله إن أخشاكم لله، وأحفظكم لحدوده لأنا ))."],"takhrij":"صحيح: رواه عبد الرزاق (١٠٣٧٥)، والبزار - كشف الأستار (١٤٥٨)، وابن حبان (٩).","grade":"صحيح","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by ‘Abd al-Razzaq (10375), al-Bazzar in Kashf al-Astar (1458), and Ibn Hibban (9).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: The wife of ‘Uthman ibn Maz‘un, whose name was Khawlah bint Hakim, came to ‘A’ishah while she was in poor appearance. She asked her: What is the matter with you? She said: My husband stands in prayer all night and fasts all day. Then the Prophet ﷺ came in, and ‘A’ishah mentioned that to him. So the Prophet ﷺ met ‘Uthman and said: “O ‘Uthman, monasticism has not been prescribed for us. Do you not have an example in me? By Allah, I am the one among you who fears Allah most and guards His limits best.”"]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":10375},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1458},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":11217,"n":11309},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4658,"n":4654}]},{"num":6191,"demo":false,"sanad":"","matn":["عن عائشة قالت: كانت امرأة عثمان بن مظعون تختضب وتطيب، فتركته، فدخلت علي، فقلت لها: أمشهد أم مغيب؟ فقالت: مشهد كمغيب. قلت لها: مالك؟ قالت: عثمان لا يريد الدنيا، ولا يريد النساء. قالت عائشة: فدخل علي رسول الله ﷺ فأخبرته بذلك. فلقي عثمان فقال: (( يا عثمان، أتؤمن بما نؤمن به؟ )) قال: نعم يا رسول الله. قال: (( فاصنع كما نصنع ))."],"takhrij":"حسن: رواه الإمام أحمد (٢٤٧٥٤)، وأبو نعيم في الحلية (٦/٢٥٧).","grade":"حسن","chapter_ar":"باب ترغيب الشباب في الزواج وكراهية التبتل والخصاء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (24754) and Abu Nu‘aym in al-Hilyah (6/257).","chapter_en":"Chapter on encouraging young people to marry and disliking celibacy and castration","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: The wife of ‘Uthman ibn Maz‘un used to apply henna and perfume, then she stopped doing so. She came to me, and I said to her: Is your husband present or absent? She said: Present like absent. I said to her: What is wrong with you? She said: ‘Uthman has no desire for worldly life and no desire for women. ‘A’ishah said: Then the Messenger of Allah ﷺ came to me and I informed him of that. He met ‘Uthman and said: “O ‘Uthman, do you believe in what we believe in?” He said: Yes, O Messenger of Allah. He said: “Then do as we do.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":24754},{"key":"ابو_نعیم/الحلیہ","label":"أبو نعيم في الحلية","number":6},{"key":"ahmad","label":"مسند الإمام أحمد","number":24754,"n":24754}]},{"num":6192,"demo":false,"sanad":"","matn":["عن عقبة بن عامر قال: قال رسول الله ﷺ: (( أحق الشروط أن توفوا به ما استحللتم به الفروج ))."],"takhrij":"متفق عليه: رواه البخاري (٢٧٢١)، ومسلم (١٤١٨).","grade":"متفق عليه","chapter_ar":"باب في الوفاء بالشروط في عقد النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2721) and Muslim (1418).","chapter_en":"Chapter on fulfilling conditions in the marriage contract","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir reported that the Messenger of Allah ﷺ said: “The conditions most deserving to be fulfilled are those by which you made private relations lawful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2721},{"key":"muslim","label":"مسلم","number":1418}]},{"num":6193,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( ثلاثة كلهم حق على الله عونه: الغازي في سبيل الله، والمكاتب الذي يريد الأداء، والناكح الذي يريد التعفف ))."],"takhrij":"حسن: رواه الترمذي (١٦٥٥) وحسّنه، والنسائي (٣٢١٨، ٣١٢٠)، وابن ماجه (٢٥١٨)، وأحمد (٧٤١٦).","grade":"حسن","chapter_ar":"باب عون الله تعالى للناكح الذي يريد العفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1655), who graded it Hasan, al-Nasa’i (3218, 3120), Ibn Majah (2518), and Ahmad (7416).","chapter_en":"Chapter on Allah’s help for the one who marries seeking chastity","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Three people all have a right upon Allah that He help them: the fighter in the path of Allah, the contracted slave who wants to complete his payment, and the one who marries seeking chastity.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1655},{"key":"nasai","label":"النسائي","number":3218},{"key":"ibnmajah","label":"ابن ماجه","number":2518},{"key":"ahmad","label":"مسند الإمام أحمد","number":7416,"n":7416}]},{"num":6194,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أن النبي ﷺ قال: (( إذا دخلت ليلا، فلا تدخل على أهلك حتى تستحد المغيبة، وتمتشط الشعثة )). قال: قال رسول الله ﷺ: (( فعليك بالكيس الكيس ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٤٦)، ومسلم (٥٧:٧١٥).","grade":"متفق عليه","chapter_ar":"باب الحث على طلب الولد بالزواج، والترغيب في تزوج الولود الودود","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5246) and Muslim (715:57).","chapter_en":"Chapter on encouraging the seeking of children through marriage and encouraging marriage to a loving, fertile woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that the Prophet ﷺ said: “If you arrive at night, do not enter upon your family until the woman whose husband was absent removes her unwanted hair and the disheveled woman combs her hair.” Jabir said: The Messenger of Allah ﷺ said: “So hold fast to good sense, hold fast to good sense.”"]},"buhuth":{"ar":["قوله: (( فعليك بالكيس الكيس )) فسره البخاري في الحديث الذي قبله بالولد، يعني طلب الولد. وقال ابن الأعرابي: الكيس: الجماع. والكيس: العقل، والمراد حثه على ابتغاء الولد. انظر: شرح مسلم للنووي (١٠/٥٤)."],"en":["His statement, “So hold fast to good sense,” was explained by al-Bukhari in the preceding narration as referring to children, meaning seeking offspring. Ibn al-A‘rabi said: the word can mean intercourse. It also means intelligence. What is meant here is encouraging him to seek children. See Sharh Muslim by al-Nawawi (10/54)."]},"intro":{"ar":["قال الله تعالى: (هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُ ۖ قَالَ رَبِّ هَبْ لِي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ) [آل عمران: ٣٨]"],"en":["Allah Most High said:","“Thereupon Zechariah called upon his Lord. He said: My Lord, grant me from Yourself good offspring. Surely You are the Hearer of supplication.” [Aal ‘Imran: 38]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5246},{"key":"muslim","label":"مسلم","number":57}]},{"num":6195,"demo":false,"sanad":"","matn":["عن معقل بن يسار قال: جاء رجل إلى النبي ﷺ فقال: إني أصبت امرأة ذات حسب وجمال، إلا أنها لا تلد، أفأتزوجها؟ قال: (( لا )). ثم أتاه الثانية، فنهاه، ثم أتاه الثالثة، فقال: (( تزوجوا الودود الولود، فإني مكاثر بكم ))."],"takhrij":"حسن: رواه أبو داود (٢٠٥٠)، والنسائي (٣٢٢٧).","grade":"حسن","chapter_ar":"باب الحث على طلب الولد بالزواج، والترغيب في تزوج الولود الودود","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2050) and al-Nasa’i (3227).","chapter_en":"Chapter on encouraging the seeking of children through marriage and encouraging marriage to a loving, fertile woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ma‘qil ibn Yasar said: A man came to the Prophet ﷺ and said, “I have found a woman of noble lineage and beauty, but she does not bear children. Should I marry her?” He said, “No.” Then he came to him a second time, and he forbade him. Then he came a third time, and he said, “Marry the loving, fertile women, for I will boast of your numbers.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2050},{"key":"nasai","label":"النسائي","number":3227}]},{"num":6196,"demo":false,"sanad":"","matn":["عن ابن عمر أنه تزوج امرأة فأصابها شمطاء فطلقها، وقال: حصير في بيت خير من امرأة لا تلد. والله ما أقربكن شهوة، ولكني سمعت رسول الله ﷺ يقول: (( تزوجوا الودود الولود، فإني مكاثر بكم الأمم يوم القيامة ))."],"takhrij":"صحيح: رواه الخطيب في تاريخ بغداد (٦٧٨٢).","grade":"صحيح","chapter_ar":"باب الحث على طلب الولد بالزواج، والترغيب في تزوج الولود الودود","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Khatib in Tarikh Baghdad (6782).","chapter_en":"Chapter on encouraging the seeking of children through marriage and encouraging marriage to a loving, fertile woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Umar reported that he married a woman, then found her gray-haired, so he divorced her. He said:","“A mat in the house is better than a woman who does not bear children. By Allah, it is not desire for women that brings me near to you, but I heard the Messenger of Allah ﷺ say: ‘Marry the loving, fertile women, for I will boast of your numbers before the nations on the Day of Resurrection.’”"]}},"tuhfa":{},"refs":[{"key":"الخطیب/تاریخ_بغداد","label":"الخطيب في تاريخ بغداد","number":6782}]},{"num":6197,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال:","قفلنا مع النبي ﷺ من غزوة، فتعجلت على بعير لي قطوف، فلحقني راكب من خلفي، فنخس بعيري بعنزة كانت معه، فانطلق بعيري كأجود ما أنت راء من الإبل.","فإذا النبي ﷺ، فقال:","«مَا يُعْجِلُكَ؟»","قلت: كنت حديث عهد بعرس.","قال:","«أَبِكْرًا أَمْ ثَيِّبًا؟»","قلت: ثيبًا.","قال:","«فَهَلَّا جَارِيَةً تُلَاعِبُهَا وَتُلَاعِبُكَ؟»","قال: فلما ذهبنا لندخل قال:","«أَمْهِلُوا حَتَّى تَدْخُلُوا لَيْلًا - أَيْ عِشَاءً - لِكَيْ تَمْتَشِطَ الشَّعِثَةُ، وَتَسْتَحِدَّ الْمُغِيبَةُ»."],"takhrij":"متفق عليه: رواه البخاري (٥٠٧٩)، ومسلم (٧١٥/٥٧).","grade":"متفق عليه","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5079) and Muslim (715/57).","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported:","We were returning with the Prophet ﷺ from an expedition. I hurried ahead on a camel of mine that was slow in walking. A rider caught up with me from behind and prodded my camel with a stick that he had, whereupon my camel began moving as well as the best camel you could see.","It was the Prophet ﷺ. He asked:","“What is making you hurry?”","I replied:","“I have recently been married.”","He asked:","“A virgin or a previously married woman?”","I replied:","“A previously married woman.”","He said:","“Why not a young virgin whom you could play with and who could play with you?”","When we were about to enter Madinah, he said:","“Wait until you enter at night—that is, in the evening—so that the woman whose hair is disheveled may comb it, and the woman whose husband has been absent may remove her unwanted hair.”"]},"buhuth":{"ar":["قوله: «قطوف» أي بطيء المشي.","وقوله: «الشعثة» هي المرأة المتفرقة شعر الرأس، أي لتتزين هي لزوجها."],"en":["“Qaṭūf” means slow in walking.","“Al-shaʿithah” means a woman whose hair is disordered, so that she may beautify herself for her husband."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5079},{"key":"muslim","label":"مسلم","number":715}]},{"num":6198,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: هلك أبي وترك سبع بنات، أو تسع بنات، فتزوجت امرأة ثيباً، فقال لي رسول الله ﷺ: (( تزوجت يا جابر؟ )) فقلت: نعم. فقال: (( بكراً أم ثيباً؟ )) قلت: بل ثيباً. قال: (( فهلا جارية تلاعبها وتلاعبك، وتضاحكها وتضاحكك؟ )) قال: فقلت له: إن عبد الله هلك وترك بنات، وإني كرهت أن أجيئهن بمثلهن، فتزوجت امرأة تقوم عليهن وتصلحهن. فقال: (( بارك الله لك - أو قال: خيراً )).","وفي لفظ: فكرهت أن أجمع إليهن جارية خرقاء مثلهن، ولكن امرأة تمشطهن وتقوم عليهن."],"takhrij":"متفق عليه: رواه البخاري (٥٣٦٧)، ومسلم (٥٦:٧١٥). واللفظ الآخر للبخاري في المغازي (٤٠٥٢).","grade":"متفق عليه","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5367) and Muslim (715:56). The alternate wording is in al-Bukhari in the Book of Military Expeditions (4052).","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: My father died and left behind seven daughters, or nine daughters, so I married a previously married woman. The Messenger of Allah ﷺ said to me, “Have you married, O Jabir?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “Rather, a previously married woman.” He said, “Why not a young virgin, so that you may play with her and she may play with you, and make her laugh and she make you laugh?”","He said: I said to him, “ ‘Abd Allah died and left daughters, and I disliked bringing them someone like themselves, so I married a woman who would look after them and set their affairs right.” He said, “May Allah bless you,” or he said, “Good.”","And in another wording: “I disliked bringing together with them a young inexperienced girl like them; rather I wanted a woman who would comb their hair and take care of them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5367},{"key":"muslim","label":"مسلم","number":56},{"key":"واللفظ_الاخر_للبخاری/المغازی","label":". واللفظ الآخر للبخاري في المغازي","number":4052}]},{"num":6199,"demo":false,"sanad":"","matn":["عن جابر قال: تزوجت امرأة فقال لي رسول الله ﷺ: (( هل تزوجت؟ )) قلت: نعم. قال: (( أبكراً أم ثيباً؟ )) قلت: ثيباً. قال: (( فأين أنت من العذارى ولعابها؟ )).","قال شعبة: فذكرته لعمرو بن دينار، فقال: قد سمعته من جابر، وإنما قال: (( فهلا جارية تلاعبها وتلاعبك؟ ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٨٠)، ومسلم (٥٥:٧١٥). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5080) and Muslim (715:55). The wording here is that of Muslim.","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Jabir said: I married a woman, and the Messenger of Allah ﷺ said to me, “Have you married?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “A previously married woman.” He said, “Then where are you with young virgins and their playfulness?”","Shu‘bah said: I mentioned this to ‘Amr ibn Dinar, and he said: I heard it from Jabir, and he only said: “Why not a young girl that you may play with her and she may play with you?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5080},{"key":"muslim","label":"مسلم","number":55}]},{"num":6200,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ قالت: قلت: يا رسول الله، أرأيت لو نزلت وادياً وفيه شجرة قد أُكل منها، ووجدت شجراً لم يؤكل منها، في أيها كنت ترتع بعيرك؟ قال: (( في التي لم يرتع منها )) يعني أن رسول الله ﷺ لم يتزوج بكراً غيرها."],"takhrij":"صحيح: رواه البخاري (٥٠٧٧).","grade":"صحيح","chapter_ar":"باب تفضيل نكاح الأبكار على الثيبات إلا للمصلحة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5077).","chapter_en":"Chapter on preferring marriage to virgins over previously married women, except when there is a benefit in doing otherwise","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: I said, “O Messenger of Allah, if you were to camp in a valley in which there was a tree that had already been grazed from, and you found trees that had not been grazed from, which would you let your camel graze from?” He said, “From the one that has not been grazed from.” Meaning that the Messenger of Allah ﷺ did not marry any virgin besides her."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5077}]},{"num":6201,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: (( تنكح المرأة لأربع: لمالها، ولحسبها، وجمالها، ولدينها، فاظفر بذات الدين تربت يداك ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٩٠)، ومسلم (٥٣:١٤٦٦).","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5090) and Muslim (1466:53).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said:","“A woman is married for four things: for her wealth, her lineage, her beauty, and her religion. So attain the one with religion, may your hands be covered with dust.”"]},"intro":{"ar":["قال الله تعالى: (وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ) [الفرقان: ٧٤]"],"en":["Allah Most High said:","“And those who say: Our Lord, grant us from our spouses and our offspring comfort to our eyes.” [Al-Furqan: 74]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5090},{"key":"muslim","label":"مسلم","number":53}]},{"num":6202,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: تزوجت امرأة فقال لي رسول الله ﷺ: (( هل تزوجت؟ )) قلت: نعم. قال: (( أبكراً أم ثيباً؟ )) قلت: ثيباً. قال: (( فأين أنت من العذارى ولعابها؟ ))","قال شعبة: فذكرته لعمرو بن دينار. فقال: قد سمعته من جابر، وإنما قال: (( فهلا جارية تلاعبها وتلاعبك؟ ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٨٠)، ومسلم (٥٥:٧١٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5080) and Muslim (715:55).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I married a woman, so the Messenger of Allah ﷺ said to me, “Have you married?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “A previously married woman.” He said, “Then where are you with young virgins and their playfulness?”","Shu‘bah said: I mentioned it to ‘Amr ibn Dinar, and he said: I heard it from Jabir, and he only said: “Why not a young girl that you may play with her and she may play with you?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5080},{"key":"muslim","label":"مسلم","number":55}]},{"num":6203,"demo":false,"sanad":"","matn":["عن جابر قال: تزوجت امرأة في عهد رسول الله ﷺ فلقيت النبي ﷺ فقال: (( يا جابر تزوجت؟ )) قلت: نعم. قال: (( بكر أم ثيب؟ )) قلت: ثيب. قال: (( فهلا بكراً تلاعبها؟ )) قلت: يا رسول الله، إن لي أخوات فخشيت أن تدخل بيني وبينهن. قال: (( فذاك إذن، إن المرأة تنكح على دينها، ومالها، وجمالها، فعليك بذات الدين تربت يداك ))."],"takhrij":"صحيح: رواه مسلم (٥٤:٧١٥).","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (715:54).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Jabir said: I married a woman during the time of the Messenger of Allah ﷺ, and the Prophet ﷺ met me and said, “O Jabir, have you married?” I said, “Yes.” He said, “A virgin or a previously married woman?” I said, “A previously married woman.” He said, “Why not a virgin, so that you may play with her?” I said, “O Messenger of Allah, I have sisters, and I feared that she would come between me and them.” He said, “Then that is fine. A woman is married for her religion, her wealth, and her beauty, so hold fast to the one with religion, may your hands be covered with dust.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":54}]},{"num":6204,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: قال رسول الله ﷺ: (( تنكح المرأة على إحدى خصال ثلاث: تنكح المرأة على مالها، وتنكح المرأة على جمالها، وتنكح المرأة على دينها، فخذ ذات الدين والخلق تربت يمينك ))."],"takhrij":"حسن: رواه أحمد (١١٧٦٥)، وأبو يعلى (١٠١٢)، والبزار - كشف الأستار (١٤٠٣)، وصححه ابن حبان (٤٠٣٧).","grade":"حسن","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (11765), Abu Ya‘la (1012), al-Bazzar in Kashf al-Astar (1403), and authenticated by Ibn Hibban (4037).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said, “A woman is married for one of three qualities: she is married for her wealth, she is married for her beauty, and she is married for her religion. So take the one with religion and good character, may your right hand be covered with dust.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":1012},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1403},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4037},{"key":"ahmad","label":"مسند الإمام أحمد","number":11765,"n":11765},{"key":"sh12520","label":"مسند أبي يعلى","number":1012,"n":1010},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1403,"n":1404},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1219,"n":1216}]},{"num":6205,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو أن رسول الله ﷺ قال: (( الدنيا متاع، وخير متاع الدنيا المرأة الصالحة ))."],"takhrij":"صحيح: رواه مسلم (١٤٦٧).","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1467).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr reported that the Messenger of Allah ﷺ said:","“This world is a temporary enjoyment, and the best enjoyment of this world is a righteous woman.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1467}]},{"num":6206,"demo":false,"sanad":"","matn":["عن سهل بن سعد، قال: مر رجل على رسول الله ﷺ فقال: (( ما تقولون في هذا؟ )) قالوا: حري إن خطب أن ينكح، وإن شفع أن يشفع، وإن قال أن يستمع. قال: ثم سكت. فمر رجل من فقراء المسلمين، فقال: (( ما تقولون في هذا؟ )) قالوا: حري إن خطب أن لا ينكح، وإن شفع أن لا يشفع، وإن قال أن لا يستمع. فقال رسول الله ﷺ: (( هذا خير من ملء الأرض مثل هذا ))."],"takhrij":"صحيح: رواه البخاري (٥٠٩١).","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5091).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Sahl ibn Sa‘d said: A man passed by the Messenger of Allah ﷺ, and he said, “What do you say about this one?” They said: He is deserving, if he proposes, to be married to; if he intercedes, to have his intercession accepted; and if he speaks, to be listened to. Then he remained silent. Then a poor man from among the Muslims passed by, and he said, “What do you say about this one?” They said: He is deserving, if he proposes, not to be married to; if he intercedes, not to have his intercession accepted; and if he speaks, not to be listened to. So the Messenger of Allah ﷺ said, “This one is better than the whole earth filled with the likes of that one.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5091}]},{"num":6207,"demo":false,"sanad":"","matn":["عن سعد بن أبي وقاص قال: قال رسول الله ﷺ: (( أربع من السعادة: المرأة الصالحة، والمسكن الواسع، والجار الصالح، والمركب الهنيء. وأربع من الشقاوة: الجار السوء، والمرأة السوء، والمسكن الضيق، والمركب السوء ))."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (٤٠٣٢).","grade":"صحيح","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Hibban in his Sahih (4032).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: The Messenger of Allah ﷺ said, “Four things are from happiness: a righteous wife, a spacious home, a good neighbor, and a comfortable mount. And four things are from misery: a bad neighbor, a bad wife, a cramped home, and a bad mount.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4032},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4542,"n":4538}]},{"num":6208,"demo":false,"sanad":"","matn":["عن رجل من أصحاب النبي أن رسول الله ﷺ قال: (( تبا للذهب والفضة )). قال: فانطلقت مع عمر بن الخطاب، فقال: يا رسول الله، قولك: (( تبا للذهب والفضة )) ماذا؟ فقال: (( لساناً ذاكراً، وقلباً شاكراً، زوجة تعين على الآخرة ))."],"takhrij":"حسن: رواه أحمد (٢٣١٠١).","grade":"حسن","chapter_ar":"باب ما جاء أن الكفاءة هي الدين وحده، والترغيب في اختيار الزوجة الصالحة ذات الدين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23101).","chapter_en":"Chapter on what has been reported that compatibility is in religion alone, and encouraging the choice of a righteous, religious wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["A man from among the Companions of the Prophet ﷺ reported that the Messenger of Allah ﷺ said:","“Woe to gold and silver.”","He said: So I went with ‘Umar ibn al-Khattab, and he said: O Messenger of Allah, your statement, “Woe to gold and silver” - then what should one have? He said: “A tongue that remembers Allah, a grateful heart, a wife who helps one toward the Hereafter.”"]},"buhuth":{"ar":["قوله: (( تباً للذهب والفضة )) أي هلاكاً لمن ادخرهما ولم يؤد زكاتهما.","وقوله: (( ماذا )) أي ماذا نتخذ كما في رواية ثوبان الآتية."],"en":["His statement, “Woe to gold and silver,” means destruction for the one who hoards them and does not pay their due alms.","His statement, “then what?” means: then what should we acquire, as in the narration of Thawban that comes later."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23101,"n":23101}]},{"num":6209,"demo":false,"sanad":"","matn":["عن فاطمة بنت قيس أن أبا عمرو بن حفص طلقها البتة، فذكرت الحديث. قالت: فلما حللت ذكرت للنبي ﷺ أن معاوية بن أبي سفيان، وأبا جهم بن هشام خطباني. فقال رسول الله ﷺ: (( أما أبو جهم فلا يضع عصاه عن عاتقه، وأما معاوية فصعلوك لا مال له، أنكحي أسامة بن زيد )). قالت: فكرهته. ثم قال: (( أنكحي أسامة بن زيد )). فنكحته، فجعل الله في ذلك خيراً، واغتبطت به."],"takhrij":"صحيح: رواه مالك (٧٣)، ومسلم (١٤٨٠).","grade":"صحيح","chapter_ar":"باب تزوج المولى العربية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (73) and Muslim (1480).","chapter_en":"Chapter on a freedman marrying an Arab woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Fatimah bint Qays reported that Abu ‘Amr ibn Hafs divorced her irrevocably. She mentioned the rest of the narration and said: When my waiting period ended, I mentioned to the Prophet ﷺ that Mu‘awiyah ibn Abi Sufyan and Abu Jahm ibn Hisham had proposed to me. The Messenger of Allah ﷺ said: “As for Abu Jahm, he does not put down his staff from his shoulder; and as for Mu‘awiyah, he is poor and has no wealth. Marry Usamah ibn Zayd.”","She said: I disliked him. Then he said: “Marry Usamah ibn Zayd.” So I married him, and Allah placed much good in that, and I was pleased with it."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":73},{"key":"muslim","label":"مسلم","number":1480}]},{"num":6210,"demo":false,"sanad":"","matn":["عن عائشة أن أبا حذيفة بن عتبة بن ربيعة بن عبد شمس - وكان ممن شهد بدراً مع النبي ﷺ - تبنى سالماً، وأنكحه بنت أخيه - هند بنت الوليد بن عتبة بن ربيعة - وهو مولى لامرأة من الأنصار."],"takhrij":"صحيح: رواه البخاري (٥٠٨٨).","grade":"صحيح","chapter_ar":"باب تزوج المولى العربية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5088).","chapter_en":"Chapter on a freedman marrying an Arab woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah reported that Abu Hudhayfah ibn ‘Utbah ibn Rabi‘ah ibn ‘Abd Shams - and he was among those who witnessed Badr with the Prophet ﷺ - had adopted Salim and married him to the daughter of his brother, Hind bint al-Walid ibn ‘Utbah ibn Rabi‘ah, and he was the freedman of a woman from the Ansar."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5088}]},{"num":6211,"demo":false,"sanad":"","matn":["عن أبي هريرة أن أبا هند حجم النبي ﷺ في اليافوخ، فقال له النبي ﷺ: (( يا بني بياضة، أنكحوا أبا هند، أنكحوا إليه )). وقال: (( وإن كان في شيء مما تداوون به خير فالحجامة )). وفي رواية: (( كان حجاماً ))."],"takhrij":"حسن: رواه أبو داود (٢١٠٢)، والدارقطني (٣/٣٠٠-٣٠١)، وابن حبان (٤٠٦٧)، والحاكم (٢/١٦٤).","grade":"حسن","chapter_ar":"باب لا يرد نكاح غير الكفء إذا رضيت المرأة ووليها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2102), al-Daraqutni (3/300–301), Ibn Hibban (4067), and al-Hakim (2/164).","chapter_en":"Chapter on not rejecting the marriage of one who is not socially equal if the woman and her guardian are pleased","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that Abu Hind cupped the Prophet ﷺ on the crown of his head, so the Prophet ﷺ said to him:","“O Banu Bayadah, marry Abu Hind [to your women], and seek his daughters in marriage.”","And he said: “If there is any good in what you use for treatment, then it is cupping.”","And in one narration: “He was a cupper.”"]},"buhuth":{"ar":["وقوله: (( وأنكحوا إليه )) أي اخطبوا إليه بناته."],"en":["His statement, “and seek marriage from him,” means: ask for his daughters in marriage."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2102},{"key":"الدارقطنی","label":"الدارقطني","number":3},{"key":"ibnhibban","label":"ابن حبان","number":4067},{"key":"hakim","label":"الحاكم","number":2}]},{"num":6212,"demo":false,"sanad":"","matn":["عن عائشة أنها قالت: كان في بريرة ثلاث سنن: فكانت إحدى السنن الثلاث أنها أعتقت فخيرت في زوجها. وقال رسول الله ﷺ: (( الولاء لمن أعتق )). ودخل رسول الله ﷺ والبرمة تفور بلحم، فقرب إليه خبز وأدم من أدم البيت. فقال رسول الله ﷺ: (( ألم أر البرمة فيها لحم؟ )) فقالوا: بلى يا رسول الله، ولكن لحم تصدق به على بريرة، وأنت لا تأكل الصدقة. فقال رسول الله ﷺ: (( هو عليها صدقة، وهو لنا هدية ))."],"takhrij":"متفق عليه: رواه مالك (٢٩)، والبخاري (٥٢٧٩)، ومسلم (١٤:١٥٠٤).","grade":"متفق عليه","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (29), al-Bukhari (5279), and Muslim (1504:14).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah said: There were three legal rulings connected to Barirah. One of those three rulings was that when she was freed, she was given the choice regarding her husband. And the Messenger of Allah ﷺ said: “The right of patronage belongs to the one who frees.”","The Messenger of Allah ﷺ entered while a cooking pot was boiling with meat, and bread and ordinary household seasoning were brought near to him. The Messenger of Allah ﷺ said: “Did I not see the pot with meat in it?” They said: Yes, O Messenger of Allah, but it is meat that was given in charity to Barirah, and you do not eat charity. So the Messenger of Allah ﷺ said: “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":29},{"key":"bukhari","label":"البخاري","number":5279},{"key":"muslim","label":"مسلم","number":14}]},{"num":6213,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ قالت: كان زوج بريرة عبداً، فخيرها رسول الله ﷺ، فاختارت نفسها، ولو كان حراً لم يخيرها."],"takhrij":"صحيح: رواه مسلم (٩:١٥٠٤).","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1504:9).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The husband of Barirah was a slave, so the Messenger of Allah ﷺ gave her the choice, and she chose herself. If he had been a free man, he would not have given her that choice."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":9}]},{"num":6214,"demo":false,"sanad":"","matn":["عن ابن عباس أن زوج بريرة كان عبداً يقال له مغيث، كأني أنظر إليه يطوف خلفها يبكي ودموعه تسيل على لحيته. فقال النبي ﷺ لعباس: (( يا عباس، ألا تعجب من حب مغيث بريرة، ومن بغض بريرة مغيثاً؟ )). فقال النبي ﷺ: (( لو راجعته )). قالت: يا رسول الله، تأمرني؟ قال: (( إنما أنا أشفع )). قالت: لا حاجة لي فيه."],"takhrij":"صحيح: رواه البخاري (٥٢٨٣).","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5283).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas reported that the husband of Barirah was a slave named Mughith. It is as if I can still see him going around behind her, weeping, with tears flowing down his beard. Then the Prophet ﷺ said to al-‘Abbas:","“O ‘Abbas, are you not amazed at the love of Mughith for Barirah, and the dislike of Barirah for Mughith?”","Then the Prophet ﷺ said: “Why do you not return to him?” She said: O Messenger of Allah, are you commanding me? He said: “I am only interceding.” She said: I have no need of him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5283}]},{"num":6215,"demo":false,"sanad":"","matn":["عن ابن عباس قال: ذاك مغيث عبد بني فلان - يعني زوج بريرة - كأني أنظر إليه يتبعها في سكك المدينة يبكي عليها."],"takhrij":"صحيح: رواه البخاري (٥٢٨١).","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5281).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas said: That was Mughith, the slave of such-and-such people - meaning the husband of Barirah. It is as though I can still see him following her through the streets of Madinah, weeping over her."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5281}]},{"num":6216,"demo":false,"sanad":"","matn":["عن ابن عباس أن زوج بريرة كان عبدا أسود يسمى مُغيثا. قال: فكنت أراه يتبعها في سكك المدينة، يعصر عينيه عليها. قال: وقضى فيها النبي ﷺ أربع قضيات: إن مواليها اشترطوا الولاء، فقضى النبي ﷺ: (( الولاء لمن أعتق )). وخيّرها فاختارت نفسها، فأمرها أن تعتد. قال: وتُصُدِّقَ عليها بصدقة، فأهدت منها إلى عائشة، فذكرت ذلك للنبي ﷺ فقال: (( هو عليها صدقة، وإلينا هدية ))."],"takhrij":"صحيح: رواه أحمد (٢٥٤٢)، والطبراني (١١٨٢٦)، والبيهقي (٢٢٢-٢٢١/٧).","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2542), al-Tabarani (11826), and al-Bayhaqi (7/221–222).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Ibn ‘Abbas reported that the husband of Barirah was a black slave named Mughith. He said: I used to see him following her through the streets of Madinah, crying over her. He said: The Prophet ﷺ gave four rulings regarding her case: her masters had stipulated that the right of patronage would remain with them, so the Prophet ﷺ ruled, “The right of patronage belongs to the one who frees.” He gave her the choice, and she chose herself. He ordered her to observe her waiting period. And charity was given to her, then she gifted some of it to ‘A’ishah, and when that was mentioned to the Prophet ﷺ he said, “For her it is charity, and for us it is a gift.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی","label":"الطبراني","number":11826},{"key":"البیہقی","label":"البيهقي","number":222},{"key":"ahmad","label":"مسند الإمام أحمد","number":2542,"n":2542}]},{"num":6217,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ خيّر بريرة."],"takhrij":"صحيح: رواه ابن ماجه (٢٠٧٨).","grade":"صحيح","chapter_ar":"باب اعتبار الحرية في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2078).","chapter_en":"Chapter on considering freedom in compatibility","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ gave Barirah the choice."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2078}]},{"num":6218,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( لا عدوى، ولا طيرة، ولا هامة، ولا صفر، وفر من المجذوم كما تفر من الأسد ))."],"takhrij":"صحيح: رواه البخاري (٥٧٠٧).","grade":"صحيح","chapter_ar":"باب اعتبار السلامة من العيوب في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5707).","chapter_en":"Chapter on considering freedom from defects in suitability","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said, “There is no contagious transmission by itself, no evil omen, no owl-omen, and no bad luck in Safar; and flee from the leper as you would flee from a lion.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5707}]},{"num":6219,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( لا يورد ممرض على مصح ))."],"takhrij":"متفق عليه: رواه البخاري (٥٧٧٤)، ومسلم (٢٢٢١) في السلام.","grade":"متفق عليه","chapter_ar":"باب اعتبار السلامة من العيوب في الكفاءة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5774) and Muslim (2221) in the Book of Greetings.","chapter_en":"Chapter on considering freedom from defects in suitability","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said, “A diseased animal should not be brought to one that is healthy.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5774},{"key":"muslim","label":"مسلم","number":2221}]},{"num":6220,"demo":false,"sanad":"","matn":["عن فاطمة بنت قيس تقول: إن زوجها طلّقها ثلاثاً فلم يجعل لها رسول الله ﷺ سكنى ولا نفقة. قالت: قال لي رسول الله ﷺ: (( إذا حللت فآذنيني )). فآذنته. فخطبها معاوية وأبو جهم وأسامة بن زيد، فقال رسول الله ﷺ: (( أما معاوية فرجل ترب لا مال له، وأما أبو جهم فرجل ضرّاب، ولكن أسامة بن زيد ))."],"takhrij":"صحيح: رواه مسلم (٤٧ :١٤٨٠).","grade":"صحيح","chapter_ar":"باب الترغيب في اختيار الزوج الصالح سواء كان له مال أم لا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1480:47).","chapter_en":"Chapter on encouraging the choice of a righteous husband whether he has wealth or not","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Fatimah bint Qays said: Her husband divorced her with a final triple divorce, and the Messenger of Allah ﷺ did not assign for her housing or maintenance. She said: The Messenger of Allah ﷺ said to me, “When your waiting period ends, inform me.” So I informed him. Then Mu‘awiyah, Abu Jahm, and Usamah ibn Zayd proposed to her, and the Messenger of Allah ﷺ said, “As for Mu‘awiyah, he is a poor man with no wealth. As for Abu Jahm, he is a man who beats women. But Usamah ibn Zayd…”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":47}]},{"num":6221,"demo":false,"sanad":"","matn":["عن بريدة قال: قال رسول الله ﷺ: (( إن أحساب أهل الدنيا الذين يذهبون إليه، هذا المال ))."],"takhrij":"حسن: رواه النسائي (٣٢٢٥)، وأحمد (٢٢٩٩٠)، وصححه ابن حبان (٦٩٩).","grade":"حسن","chapter_ar":"باب الترغيب في اختيار الزوج الصالح سواء كان له مال أم لا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3225), Ahmad (22990), and authenticated by Ibn Hibban (699).","chapter_en":"Chapter on encouraging the choice of a righteous husband whether he has wealth or not","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Buraydah said: The Messenger of Allah ﷺ said, “What the people of this world regard as status is this wealth.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3225},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":699},{"key":"ahmad","label":"مسند الإمام أحمد","number":22990,"n":22990}]},{"num":6222,"demo":false,"sanad":"","matn":["عن مسروق وعمرو بن عتبة أنهما كتبا إلى سبيعة بنت الحارث يسألانها عن أمرها - فكتبت لهما الحديث مطولاً كما سيأتي -، وفي آخره أن رسول الله ﷺ قال: (( إن وجدتِ زوجاً صالحاً فتزوجي ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٠٢٨).","grade":"صحيح","chapter_ar":"باب الترغيب في اختيار الزوج الصالح سواء كان له مال أم لا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2028).","chapter_en":"Chapter on encouraging the choice of a righteous husband whether he has wealth or not","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Masruq and ‘Amr ibn ‘Utbah wrote to Subay‘ah bint al-Harith asking her about her case - and she wrote back to them the full narration, which will come later - and at its end the Messenger of Allah ﷺ said: “If you find a righteous husband, then marry.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2028}]},{"num":6223,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( خير نساء ركبن الإبل صالحو نساء قريش، أحناه على ولد في صغره، وأرعاه على زوج في ذات يده ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٨٢)، ومسلم (٢٥٢٧).","grade":"متفق عليه","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5082) and Muslim (2527).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “The best women who have ridden camels are the righteous women of Quraysh: the most compassionate toward a child in his young age, and the most careful regarding her husband’s wealth.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5082},{"key":"muslim","label":"مسلم","number":2527}]},{"num":6224,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن النبي ﷺ خطب أم هانئ بنت أبي طالب. فقالت: يا رسول الله، إني قد كبرت ولي عيال. فقال رسول الله ﷺ: (( خير نساء ركبْن الإبل نساء قريش، أحناه على ولد في صغره ))."],"takhrij":"صحيح: رواه مسلم (٢٠١ :٢٥٢٧).","grade":"صحيح","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2527:201).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ proposed to Umm Hani’ bint Abi Talib. She said: “O Messenger of Allah, I have grown old and I have dependents.” So the Messenger of Allah ﷺ said, “The best women who have ridden camels are the women of Quraysh, the most compassionate toward a child in his young age.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":201}]},{"num":6225,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قيل: يا رسول الله، أي النساء خير؟ قال: (( التي تسره إذا نظر، وتطيعه إذا أمر، ولا تخالفه في نفسها ومالها بما يكره ))."],"takhrij":"حسن: رواه النسائي (٣٢٣١)، وأحمد (٧٤٢١)، والبيهقي (٨٢/٧).","grade":"حسن","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3231), Ahmad (7421), and al-Bayhaqi (7/82).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said: It was said, “O Messenger of Allah, which women are best?” He said, “The one who pleases him when he looks at her, obeys him when he commands her, and does not oppose him concerning herself or his wealth in a way he dislikes.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3231},{"key":"البیہقی","label":"البيهقي","number":82},{"key":"ahmad","label":"مسند الإمام أحمد","number":7421,"n":7421}]},{"num":6226,"demo":false,"sanad":"","matn":["عن عبد الله بن سلام أن رسول الله ﷺ قال: (( خير النساء تسرك إذا أبصرت، وتطيعك إذا أمرت، وتحفظ غيبتك في نفسها ومالها ))."],"takhrij":"حسن: رواه الطبراني في الكبير (٣٣٨/١٤ رقم ١٤٩٦٩).","grade":"حسن","chapter_ar":"باب ذكر صفات خير النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Mu‘jam al-Kabir (14/338, no. 14969).","chapter_en":"Chapter on mentioning the qualities of the best women","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["‘Abd Allah ibn Salam reported that the Messenger of Allah ﷺ said: “The best of women is the one who pleases you when you see her, obeys you when you command her, and guards your absence regarding herself and your wealth.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":338}]},{"num":6227,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول الله ﷺ: (( أيما امرأة تزوجت بغير إذن وليها فنكاحها باطل، فإن دخل بها فلها المهر بما استحل من فرجها، وإن اشتجروا فالسلطان ولي من لا ولي له ))."],"takhrij":"حسن: رواه أبو داود (٢٠٨٣)، والترمذي (١١٠٢)، وابن ماجه (١٨٧٩)، وصححه ابن حبان (٤٠٧٤).","grade":"حسن","chapter_ar":"باب لا نكاح إلا بولي","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2083), al-Tirmidhi (1102), Ibn Majah (1879), and authenticated by Ibn Hibban (4074).","chapter_en":"There is no marriage except with a guardian","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said, “Any woman who marries without the permission of her guardian, then her marriage is invalid. If he has consummated the marriage with her, then she is entitled to the dowry because he made her private part lawful for himself. And if they dispute, then the ruler is the guardian of the one who has no guardian.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2083},{"key":"tirmidhi","label":"الترمذي","number":1102},{"key":"ibnmajah","label":"ابن ماجه","number":1879},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4074}]},{"num":6228,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري قال: قال رسول الله ﷺ: (( لا نكاح إلا بولي ))."],"takhrij":"صحيح: رواه أبو داود (٢٠٨٥)، والترمذي (١١٠١)، وابن ماجه (١٨٨١)، وصححه ابن حبان (٤٠٧٨، ٤٠٧٧).","grade":"صحيح","chapter_ar":"باب لا نكاح إلا بولي","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2085), al-Tirmidhi (1101), Ibn Majah (1881), and authenticated by Ibn Hibban (4078, 4077).","chapter_en":"There is no marriage except with a guardian","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said, “There is no marriage except with a guardian.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2085},{"key":"tirmidhi","label":"الترمذي","number":1101},{"key":"ibnmajah","label":"ابن ماجه","number":1881},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4078}]},{"num":6229,"demo":false,"sanad":"","matn":["عن أم حبيبة أنها كانت عند ابن جحش، فهلك عنها، وكان فيمن هاجر إلى أرض الحبشة، فزوّجها النجاشي رسول الله ﷺ وهي عندهم."],"takhrij":"صحيح: رواه أبو داود (٢٠٨٦).","grade":"صحيح","chapter_ar":"باب لا نكاح إلا بولي","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2086).","chapter_en":"There is no marriage except with a guardian","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Umm Habibah reported that she had been married to Ibn Jahsh, then he died while they were among those who had migrated to Abyssinia. Then the Negus married her to the Messenger of Allah ﷺ while she was there with them."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2086}]},{"num":6230,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول الله ﷺ: (( لا نكاح إلا بولي، وشاهدي عدل، وما كان من نكاح على غير ذلك فهو باطل، فإن تشاجروا فالسلطان ولي من لا ولي له ))."],"takhrij":"حسن: رواه ابن حبان (٤٠٧٥).","grade":"حسن","chapter_ar":"باب لا نكاح إلا بشاهدين عدلين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4075).","chapter_en":"There is no marriage except with two just witnesses","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said, “There is no marriage except with a guardian and two just witnesses. Any marriage other than that is invalid. If they dispute, then the ruler is the guardian of the one who has no guardian.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1364,"n":1361}]},{"num":6231,"demo":false,"sanad":"","matn":["عن سمرة، عن النبي ﷺ قال: (( أيما امرأة زوّجها وليان فهي للأول منهما، وأيما رجل باع بيعا من رجلين فهو للأول منهما ))."],"takhrij":"صحيح: رواه أبو داود (٢٠٨٨)، والترمذي (١١١٠)، وابن ماجه (٢١٩٠)، وأحمد (٢٠٠٨٥).","grade":"صحيح","chapter_ar":"باب إذا نكح وليّان","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2088), al-Tirmidhi (1110), Ibn Majah (2190), and Ahmad (20085).","chapter_en":"If two guardians marry off the same woman","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Samurah reported from the Prophet ﷺ that he said: “Any woman whom two guardians marry off, then she belongs to the first of them. And any man who sells one sale to two men, it belongs to the first of them.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2088},{"key":"tirmidhi","label":"الترمذي","number":1110},{"key":"ibnmajah","label":"ابن ماجه","number":2190},{"key":"ahmad","label":"مسند الإمام أحمد","number":20085,"n":20085}]},{"num":6232,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله أنه سمع عبد الله بن عمر رضي الله عنهما يحدث: (( إن عمر بن الخطاب حين تأيمت حفصة بنت عمر من خنيس بن حذافة السهمي - وكان من أصحاب رسول الله ﷺ فتوفي بالمدينة - فقال عمر بن الخطاب: أتيت عثمان بن عفان فعرضت عليه حفصة، فقال: سأنظر في أمري. فلبثت ليالي ثم لقيني فقال: قد بدا لي أن لا أتزوج يومي هذا. قال عمر: فلقيت أبا بكر الصديق فقلت: إن شئت زوجتك حفصة بنت عمر، فصمت أبو بكر فلم يرجع إلي شيئا، وكنت أوجد عليه مني على عثمان، فلبثت ليالي ثم خطبها رسول الله ﷺ فأنكحتها إياه، فلقيني أبو بكر فقال: لعلك وجدت علي حين عرضت علي حفصة فلم أرجع إليك شيئا؟ قال عمر: قلت نعم. قال أبو بكر: فإنه لم يمنعني أن أرجع إليك فيما عرضت علي إلا أني كنت علمت أن رسول الله ﷺ قد ذكرها، فلم أكن لأفشي سر رسول الله ﷺ، ولو تركها رسول الله ﷺ قبلتها ))"],"takhrij":"صحيح: رواه البخاري (٥١٢٢).","grade":"صحيح","chapter_ar":"باب عرض الإنسان ابنته أو أخته على أهل الصلاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5122).","chapter_en":"Chapter on a man offering his daughter or sister to righteous people","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Salim ibn ‘Abd Allah reported that he heard ‘Abd Allah ibn ‘Umar narrating: When Hafsah bint ‘Umar became widowed after Khunays ibn Hudhafah al-Sahmi - who had been one of the Companions of the Messenger of Allah ﷺ and had died in Madinah - ‘Umar ibn al-Khattab said: I went to ‘Uthman ibn ‘Affan and offered Hafsah to him, and he said: “I will consider my matter.” A few nights passed, then he met me and said: “It seems to me that I should not marry at this time.”","‘Umar said: Then I met Abu Bakr al-Siddiq and said: “If you wish, I will marry Hafsah bint ‘Umar to you.” Abu Bakr remained silent and gave me no reply, and I was more upset with him than with ‘Uthman. Then a few nights passed, and the Messenger of Allah ﷺ proposed to her, so I married her to him. Then Abu Bakr met me and said: “Perhaps you were upset with me when you offered Hafsah to me and I gave you no response?” ‘Umar said: I said, “Yes.” Abu Bakr said: “Nothing prevented me from replying to you except that I knew the Messenger of Allah ﷺ had mentioned her, and I would never disclose the secret of the Messenger of Allah ﷺ. Had the Messenger of Allah ﷺ left her, I would have accepted her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5122}]},{"num":6233,"demo":false,"sanad":"","matn":["عن أم حبيبة بنت أبي سفيان، قالت: دخل علي رسول الله ﷺ فقلت له: هل لك في أختي بنت أبي سفيان؟ فقال: (( أفعل ماذا؟ )) قلت: تنكحها. قال: (( أوتحبين ذلك؟ )) قلت: لست لك بمخلية، وأحب من شركني في الخير أختي … الحديث."],"takhrij":"متفق عليه: رواه البخاري (٥١٠١)، ومسلم (١٥ :١٤٤٩)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب عرض الإنسان ابنته أو أخته على أهل الصلاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5101) and Muslim (1449:15), and this wording is that of Muslim.","chapter_en":"Chapter on a man offering his daughter or sister to righteous people","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Umm Habibah bint Abi Sufyan said: The Messenger of Allah ﷺ entered upon me, and I said to him, “Would you like my sister, the daughter of Abu Sufyan?” He said, “What would I do?” I said, “Marry her.” He said, “Would you like that?” I said, “I am not the only one for you, and the one I would most love to share in good with me is my sister…”"]},"buhuth":{"ar":["قولها: (( لست لك بمخلية )) أي لست بمنفردة بك ولا خالية من ضرة."],"en":["Her saying, “I am not the only one for you,” means: I am not alone with you and not free from having a co-wife."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5101},{"key":"muslim","label":"مسلم","number":15}]},{"num":6234,"demo":false,"sanad":"","matn":["عن سهل بن سعد أن امرأة عرضت نفسها على النبي ﷺ فقال له رجل: يا رسول الله، زوجنيها. فقال: (( ما عندك؟ )) فقال: ما عندي شيء. قال: (( اذهب فالتمس ولو خاتماً من حديد )). فذهب ثم رجع فقال: لا والله ما وجدت شيئاً ولا خاتماً من حديد، ولكن هذا إزاري ولها نصفه. قال سهل: وماله رداء. فقال النبي ﷺ: (( وما تصنع بإزارك؟ إن لبسته لم يكن عليها منه شيء، وإن لبسته لم يكن عليك منه شيء )). فجلس الرجل حتى إذا طال مجلسه قام، فرآه النبي ﷺ فدعاه - أو دعي له - فقال له: (( ماذا معك من القرآن؟ )) فقال: معي سورة كذا وسورة كذا - لسور يعددها - فقال النبي ﷺ: (( أملكناكها بما معك من القرآن ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٢١)، ومسلم (١٤٢٥). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5121) and Muslim (1425). The wording here is that of al-Bukhari.","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Sahl ibn Sa‘d reported that a woman offered herself to the Prophet ﷺ. Then a man said to him: “O Messenger of Allah, marry her to me.” He said, “What do you have?” He said, “I have nothing.” He said, “Go and look, even if only for an iron ring.” So he went and returned and said, “No, by Allah, I found nothing, not even an iron ring. But this is my waist-wrapper, and she may have half of it.”","Sahl said: He did not even have an upper garment. So the Prophet ﷺ said, “What would she do with your waist-wrapper? If you wear it, she will have nothing of it, and if she wears it, you will have nothing of it.”","The man sat until his sitting became long, then he stood up. The Prophet ﷺ saw him and called him - or he was called for. He said to him, “What do you have from the Qur’an?” He said, “I have such-and-such surah and such-and-such surah,” listing several surahs. Then the Prophet ﷺ said, “We have married her to you in exchange for what you have of the Qur’an.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5121},{"key":"muslim","label":"مسلم","number":1425}]},{"num":6235,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: جاءت امرأة إلى رسول الله ﷺ تعرض عليه نفسها، قالت: يا رسول الله، ألك بي حاجة؟ فقالت بنت أنس: ما أقل حياءها، واسوأتاه. قال: هي خير منك، رغبت في النبي ﷺ فعرضت عليه نفسها."],"takhrij":"صحيح: رواه البخاري (٥١٢٠).","grade":"صحيح","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5120).","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Malik said: A woman came to the Messenger of Allah ﷺ offering herself to him. She said, “O Messenger of Allah, do you have any need of me?” The daughter of Anas said, “How little modesty she had! What a shame!” He said: She was better than you; she desired the Prophet ﷺ, so she offered herself to him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5120}]},{"num":6236,"demo":false,"sanad":"","matn":["عن عائشة قالت: كنت أغار على اللاتي وهبن أنفسهن لرسول الله ﷺ، وأقول: أتهب المرأة نفسها؟ فلما نزل قوله تعالى: (تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ) [الأحزاب: ٥١] قالت: قلت: والله ما أرى ربك إلا يسارع لك في هواك."],"takhrij":"متفق عليه: رواه البخاري (٤٧٨٨)، ومسلم (١٤٦٣).","grade":"متفق عليه","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4788) and Muslim (1463).","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["‘A’ishah said: I used to feel jealous of those women who offered themselves to the Messenger of Allah ﷺ, and I would say, “Does a woman offer herself?” Then when the saying of Allah Most High was revealed:","“You may defer whom you will of them and take to yourself whom you will, and whomever you desire of those you had set aside - there is no blame upon you.” [Al-Ahzab: 51]","she said: I said, “By Allah, I see that your Lord hastens to fulfill what pleases you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4788},{"key":"muslim","label":"مسلم","number":1463}]},{"num":6237,"demo":false,"sanad":"","matn":["عن عروة قال:","كانت خولة بنت حكيم من اللائي وهبن أنفسهن للنبي ﷺ.","فقالت عائشة:","أما تستحي المرأة أن تهب نفسها للرجل؟","فلما نزلت:","﴿تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ﴾","[الأحزاب: ٥١]","قلت:","يا رسول الله، ما أرى ربك إلا يسارع في هواك."],"takhrij":"متفق عليه: رواه البخاري (٥١١٣)، ومسلم (١٤٦٤/٥٠).","grade":"متفق عليه","chapter_ar":"باب عرض المرأة نفسها على النبي ﷺ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5113) and Muslim (1464/50).","chapter_en":"Chapter on a woman offering herself to the Prophet ﷺ","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["ʿUrwah reported:","Khawlah bint Ḥakīm was among the women who offered themselves in marriage to the Prophet ﷺ.","ʿĀʾishah said:","“Does a woman not feel shy to offer herself to a man?”","Then when the verse was revealed:","“You may defer whom you wish of them…”","[al-Aḥzāb: 51]","I said:","“O Messenger of Allah, I see that your Lord hastens to fulfill what pleases you.”"]},"buhuth":{"ar":["وقوله: ﴿تُرْجِي﴾ أي تؤخر من تشاء من الواهبات.","وقوله: ﴿وَتُؤْوِي﴾ أي تقبل من شئت من الواهبات، ورددت من شئت، ثم من رددتها فأنت فيها أيضًا بالخيار بعد ذلك، إن شئت عدت فيها فآويتها.","قولها: «هواك» أي رضاك، ولكن الغيرة جعلتها تقول: هواك؛ لأن إضافة الهوى إلى النبي ﷺ لا تحمل على ظاهرها، لأنه لا ينطق عن الهوى، ولا يفعل بالهوى."],"en":["The word “turjī” means: you may defer whichever of the women who offered themselves you wish.","“And you may take in” means: you may accept whichever of them you wish and put aside whichever you wish; and even one whom you previously put aside remains subject to your choice afterward—if you wish, you may return to her and accept her.","Her expression “what you desire” means what pleases you. Jealousy caused her to phrase it in that manner; attributing mere personal whim to the Prophet ﷺ is not intended literally, because he does not speak from whim nor act from whim."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5113},{"key":"muslim","label":"مسلم","number":1464}]},{"num":6238,"demo":false,"sanad":"","matn":["عن بريدة قال: خطب أبو بكر وعمر فاطمة، فقال رسول الله ﷺ: (( إنها صغيرة )). فخطبها علي، فزوجها منه."],"takhrij":"حسن: رواه النسائي (٣٢٢١).","grade":"حسن","chapter_ar":"باب استحباب تزوج المرأة مثلها في السن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3221).","chapter_en":"Chapter on the recommendation of marrying a woman near one’s age","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Buraydah said: Abu Bakr and ‘Umar proposed marriage to Fatimah, and the Messenger of Allah ﷺ said, “She is young.” Then ‘Ali proposed to her, and he married her to him."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3221}]},{"num":6239,"demo":false,"sanad":"","matn":["عن عائشة قالت: تزوجني رسول الله ﷺ وأنا بنت ست سنين، وبنى بي وأنا بنت تسع سنين، قالت: فقدمنا المدينة، فنزلنا في بني الحارث بن خزرج، فوعكت فتمزق شعري، فوفى جميمة، فأتتني أمي أم رومان، وأنا على أرجوحة، ومعي صواحبي، فصرخت بي فأتيتها، لا أدري ما تريد بي، فأخذت بيدي حتى أوقفتني على الباب. فقلت: هه هه، حتى ذهب نفسي فأدخلتني بيتا، فإذا نسوة من الأنصار، فقلن: على الخير والبركة، وعلى خير طائر، فأسلمتني إليهن، فغسلن رأسي وأصلحنني، فلم يرعني إلا رسول الله ﷺ ضحى. فأسلمتني إليه."],"takhrij":"متفق عليه: رواه البخاري (٣٨٩٤) ومسلم (١٤٢٢).","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح الصغيرة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3894) and Muslim (1422).","chapter_en":"Chapter on the Marriage of a Young Girl","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAʾishah reported: “The Messenger of Allah ﷺ married me when I was six years old and consummated the marriage with me when I was nine years old. We then came to Madinah and stayed among Banu al-Harith ibn Khazraj. I fell ill and my hair fell out, then it grew back to around ear-length. My mother, Umm Ruman, came to me while I was on a swing with some girl companions. She called me, so I went to her without knowing what she wanted. She took me by the hand until she made me stand at the door. I said, ‘Hah, hah,’ until my breath settled, then she brought me into a house. There were women from the Ansar inside, and they said: ‘With goodness and blessing, and with good fortune.’ She handed me over to them, and they washed my head and prepared me. Nothing startled me except the Messenger of Allah ﷺ coming in the forenoon. Then she handed me over to him.”"]},"buhuth":{"ar":["وقولها: \"جميمة\" تصغير جمة وهي الشعر النازل إلى الأذنين ونحوهما أي صار إلى هذا الحد بعد أن كان","قد ذهب بالمرض."],"en":["Her saying, “Jamima,” is the diminutive of “jamma,” which refers to hair that falls to the ears and the like—meaning it had grown to this length after having","fallen out due to illness."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3894},{"key":"muslim","label":"مسلم","number":1422}]},{"num":6240,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ أن النبي ﷺ تزوجها وهي بنت سبع سنين، وزُفَّت إليه وهي بنت تسع سنين، ولعبها معها، ومات عنها وهي بنت ثمان عشرة."],"takhrij":"صحيح: رواه مسلم (٧١ :١٤٢٢).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح الصغيرة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (71:1422).","chapter_en":"Chapter on the Marriage of a Young Girl","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["ʿAʾishah, the wife of the Prophet ﷺ, reported that the Prophet ﷺ married her when she was seven years old, and she was brought to him as a bride when she was nine years old, with her playthings with her, and he died when she was eighteen years old."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":71}]},{"num":6241,"demo":false,"sanad":"","matn":["عن أبي سلمة ويحيى قالا: لما هلكت خديجة، جاءت خولة بنت حكيم امرأة عثمان ابن مظعون قالت: يا رسول الله، ألا تزوج؟ قال: (( من؟ )) قالت: إن شئت بكراً، وإن شئت ثيّباً، قال: (( فمن البكر؟ )) قالت: ابنة أحب خلق الله عز وجل إليك: عائشة بنت أبي بكر. قال: (( ومن الثيب؟ )) قالت: سودة بنت زمعة، آمنت بك واتبعتك على ما تقول، قال: (( فاذهبي فاذكريهما عليَّ)).","فدخلت بيت أبي بكر، فقالت: يا أم رومان، ماذا أدخل الله عز وجل عليكم من الخير والبركة؟ قالت: وما ذاك؟ قالت: أرسلني رسول الله ﷺ أخطب عليه عائشة، قالت: انتظري أبا بكر حتى يأتي، فجاء أبو بكر، فقالت: يا أبا بكر، ماذا أدخل الله عز وجل عليكم من الخير والبركة؟ قال: وما ذاك؟ قالت: أرسلني رسول الله ﷺ أخطب عليه عائشة. قال: وهل تصلح له، إنما هي ابنة أخيه، فرجعت إلى رسول الله ﷺ فذكرت ذلك له. قال: (( ارجعي إليه فقولي له: أنا أخوك وأنت أخي في الإسلام، وابنتك تصلح لي)).","فرجعت، فذكرتْ ذلك له. قال: انتظري، وخرج. قالت أم رومان: إن مُطْعِم بن عدي قد كان ذكرها على ابنه، فوالله ما وعد وعداً قط فأخلفه لأبي بكر، فدخل أبو بكر على مطعم بن عدي، وعنده امرأته أم الفتى، فقالت: يا ابن أبي قحافة، لعلك مُصْبِئٌ صاحبنا، مُدْخِله في دينك الذي أنت عليه، إن تزوج إليك. قال أبو بكر للمطعم بن عدي: أقول هذه تقول؟ قال: إنها تقول ذلك، فخرج من عنده، وقد أذهب الله عز وجل ما كان في نفسه من عِدَته التي وعده، فرجع، فقال لخولة: ادعي لي رسول الله ﷺ، فدعته، فزوجها إياه، وعائشة يومئذ بنت ست سنين.","ثم خرجت، فدخلت على سودة بنت زمعة، فقالت: ماذا أدخل الله عز وجل عليك من الخير والبركة؟ قالت: وما ذاك؟ قالت: أرسلني رسول الله ﷺ أخطبك عليه. قالت: وددت، ادخلي إلى أبي، فاذكري ذاك له، وكان شيخاً كبيراً قد أدركته السن، قد تخلَّف عن الحج، فدخلت عليه، فحيته بتحية الجاهلية، فقال: من هذه؟ فقالت: خولة بنت حكيم، قال: فما شأنك؟ قالت: أرسلني محمد بن عبد الله، أخطب عليه سودة، قال: كفء كريم، ماذا تقول صاحبتك؟ قالت: تحب ذاك، قال: ادعها لي، فدعتها.","فقال: أي بنية، إن هذه تزعم أن محمد بن عبد الله بن عبد المطلب قد أرسل يخطبك وهو كفء كريم، أتحبين أن أزوجك به؟ قالت: نعم، قال: ادعيه لي، فجاء رسول الله ﷺ إليه، فزوّجها إياه، فجاءها أخوها عبد بن زمعة من الحج، فجعل يحثي على رأسه التراب، فقال بعد أن أسلم: لعمرك، إني لسفيه يوم أحثي في رأسي التراب أن تزوّج رسول الله ﷺ سودة بنت زمعة.","قالت عائشة: فقدمنا المدينة، فنزلنا في بني الحارث من الخزرج في السُّنْح، قالت: فجاء رسول الله ﷺ فدخل بيتنا، واجتمع إليه رجال من الأنصار ونساء، فجاءت بي أمي، وإني لفي أرجوحة بين عَذْقين ترجح بي، فأنزلتني من الأرجوحة، ولي جُميمة، ففرقتها، ومسحت وجهي بشيء من ماء، ثم أقبلت تقودني حتى وقفت بي عند الباب، وإني لأنهج، حتى سكن من نفسي، ثم دخلت بي، فإذا رسول الله ﷺ جالس على سرير في بيتنا، وعنده رجال ونساء من الأنصار، فأجلستني في حِجْره، ثم قالت: هؤلاء أهلك، فبارك الله لك فيهم، وبارك لهم فيك، فوثب الرجال والنساء، فخرجوا، وبنى بي رسول الله ﷺ في بيتنا، ما نُحِرت عليَّ جزور، ولا ذُبِحت عليَّ شاة، حتى أرسل إلينا سعد بن عبادة بجفنة كان يرسل بها إلى رسول الله ﷺ إذا دار إلى نسائه، وأنا يومئذ بنت تسع سنين."],"takhrij":"حسن: رواه الإمام أحمد (٢٥٧٦٩).","grade":"حسن","chapter_ar":"باب ما جاء في نكاح الصغيرة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (25769).","chapter_en":"Chapter on the Marriage of a Young Girl","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Abu Salamah and Yahya said: When Khadijah died, Khawlah bint Hakim, the wife of ‘Uthman ibn Maz‘un, came and said: O Messenger of Allah, will you not marry? He said, “Whom?” She said: If you wish, a virgin; and if you wish, a previously married woman. He said, “Who is the virgin?” She said: The daughter of the most beloved of Allah’s creation to you: ‘A’ishah daughter of Abu Bakr. He said, “And who is the previously married woman?” She said: Sawdah bint Zam‘ah. She believed in you and followed what you brought. He said, “Go and mention them to me.”","So she entered the house of Abu Bakr and said: O Umm Ruman, what goodness and blessing Allah has brought to your household. She said: And what is that? She said: The Messenger of Allah ﷺ has sent me to ask for ‘A’ishah in marriage for him. She said: Wait until Abu Bakr comes. When Abu Bakr came, she said: O Abu Bakr, what goodness and blessing Allah has brought to your household. He said: And what is that? She said: The Messenger of Allah ﷺ has sent me to ask for ‘A’ishah in marriage for him. He said: Is she suitable for him? She is the daughter of his brother. So she returned to the Messenger of Allah ﷺ and mentioned that to him. He said: “Go back to him and say: I am your brother and you are my brother in Islam, and your daughter is lawful for me.”","So she went back and mentioned that to him. He said: Wait. Then he went out. Umm Ruman said: Mut‘im ibn ‘Adi had already mentioned her for his son, and by Allah he had never made a promise to Abu Bakr and broken it. So Abu Bakr went to Mut‘im ibn ‘Adi, and with him was the boy’s mother. She said: O son of Abu Quhafah, perhaps you will turn our companion away from his religion and enter him into your religion if he marries into you. Abu Bakr said to Mut‘im ibn ‘Adi: Is this what she is saying? He said: She is saying that. So he left him, and Allah removed from his heart the matter of the promise he had made to him. Then he returned and said to Khawlah: Call the Messenger of Allah ﷺ for me. So she called him, and he married her to him, and ‘A’ishah was then six years old.","Then she went out and entered upon Sawdah bint Zam‘ah and said: What goodness and blessing Allah has brought to you. She said: And what is that? She said: The Messenger of Allah ﷺ has sent me to ask for you in marriage for him. She said: I would like that. Go in to my father and mention it to him. He was a very old man who had advanced in age and had stayed behind from Hajj. She entered upon him and greeted him with the greeting of the pre-Islamic period. He said: Who is this? She said: Khawlah bint Hakim. He said: What is your matter? She said: Muhammad ibn ‘Abdullah has sent me; he is asking for Sawdah in marriage. He said: A noble and suitable match. What does your companion say? She said: She would like that. He said: Call her for me. So she called her.","He said: My daughter, this woman claims that Muhammad ibn ‘Abdullah ibn ‘Abd al-Muttalib has sent to ask for your hand, and he is a noble and suitable match. Do you wish that I marry you to him? She said: Yes. He said: Call him for me. So the Messenger of Allah ﷺ came to him and he married her to him. Then her brother ‘Abd ibn Zam‘ah came back from Hajj and began throwing dust upon his own head. After he accepted Islam, he said: By your life, I was indeed foolish on the day I threw dust on my head because the Messenger of Allah ﷺ married Sawdah bint Zam‘ah.","‘A’ishah said: Then we came to Madinah and stayed among Banu al-Harith of al-Khazraj at al-Sunh. She said: Then the Messenger of Allah ﷺ came and entered our house, and men and women from the Ansar gathered there. My mother came to me while I was on a swing between two branches, swinging on it. She brought me down from the swing, and my hair had grown to around ear-length. She combed and arranged it and wiped my face with some water. Then she came leading me until she made me stand at the door while I was breathing heavily, until I calmed down. Then she took me in, and there was the Messenger of Allah ﷺ seated on a bed in our house, with men and women from the Ansar around him. She seated me in his lap, then said: These are your family. May Allah bless you in them, and bless them through you. Then the men and women stood up and left. The Messenger of Allah ﷺ consummated the marriage with me in our house. No camel was slaughtered for me and no sheep was slaughtered for me, until Sa‘d ibn ‘Ubadah sent us a large bowl which he used to send to the Messenger of Allah ﷺ whenever he was with one of his wives. I was nine years old at that time."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":25769},{"key":"ahmad","label":"مسند الإمام أحمد","number":25769,"n":25769}]},{"num":6242,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري قال: قال رسول الله ﷺ: (( ثلاثة لهم أجران: رجل من أهل الكتاب آمن بنبيه، وآمن بمحمد ﷺ، والعبد المملوك إذا أدّى حق الله وحق مواليه، ورجل كانت عنده أمة، فأدّبها فأحسن تأديبها، وعلّمها فأحسن تعليمها، ثم أعتقها فتزوجها له أجران))."],"takhrij":"متفق عليه: رواه البخاري (٩٧) ومسلم (١٥٤).","grade":"متفق عليه","chapter_ar":"باب أجر من أعتق أمته ثم تزوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (97) and Muslim (154).","chapter_en":"Chapter on the reward of the one who frees his female slave and then marries her","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said: “Three people will have a double reward: a man from the People of the Book who believed in his prophet and then believed in Muhammad ﷺ; a slave who fulfills the right of Allah and the right of his masters; and a man who has a slave woman, teaches her manners and does so well, and teaches her knowledge and does so well, then frees her and marries her. For him are two rewards.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":97},{"key":"muslim","label":"مسلم","number":154}]},{"num":6243,"demo":false,"sanad":"","matn":["عن جابر قال: قال لي رسول الله ﷺ: (( تزوجت يا جابر؟ )) فقلت: نعم، وفي آخره فقال: (( بارك الله لك )) أو قال: (( خيرًا ))"],"takhrij":"متفق عليه: رواه البخاري (٥٣٦٧)، ومسلم (٥٦:٧١٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5367) and Muslim (56:715).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said to me, “Have you married, O Jabir?” I said: Yes. And at the end of the narration he said: “May Allah bless you,” or he said: “Good.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5367},{"key":"muslim","label":"مسلم","number":56}]},{"num":6244,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: رأى النبي ﷺ على عبد الرحمن أثر صفرة فقال: (( مهيم، أو مه؟ )) قال: تزوجت امرأة على وزن نواة من ذهب، فقال: (( بارك الله لك، أولم ولو بشاة ))"],"takhrij":"متفق عليه: رواه البخاري (٦٣٨٦)، ومسلم (٧٩:١٤٢٧). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6386) and Muslim (79:1427). The wording is that of al-Bukhari.","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ saw on ‘Abd al-Rahman a trace of yellow perfume and said: “What is this?” or: “What happened?” He said: I married a woman for the weight of a date-stone of gold. He said: “May Allah bless you. Give a wedding feast, even if only with one sheep.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6386},{"key":"muslim","label":"مسلم","number":79}]},{"num":6245,"demo":false,"sanad":"","matn":["عن عائشة قالت: تزوجني رسول الله ﷺ، فأدخلتني أمي بيتًا فإذا نسوة من الأنصار قلن: (( على الخير والبركة، وعلى خير طائر ))"],"takhrij":"متفق عليه: رواه البخاري (٣٨٩٤)، ومسلم (١٤٢٢). وقولها: (( على خير طائر )) أي على أفضل حظ ونصيب.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3894) and Muslim (1422).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ married me, and my mother brought me into a house where there were women from the Ansar. They said: “With goodness and blessing, and with the best fortune.”"]},"buhuth":{"en":["Her statement, “with the best fortune,” means: with the best share and good lot."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3894},{"key":"muslim","label":"مسلم","number":1422}]},{"num":6246,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ كان إذا رفَّأ الإنسان - إذا تزوج - قال: (( بارك الله لك، وبارك عليك، وجمع بينكما في خير ))"],"takhrij":"حسن: رواه أبو داود (٢١٣٠)، والترمذي (١٠٩١)، وأحمد (٨٩٥٦). قال الترمذي: حسن صحيح.","grade":"حسن","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2130), al-Tirmidhi (1091), and Ahmad (8956). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abu Hurayrah said: When the Prophet ﷺ congratulated a person upon marriage, he would say: “May Allah bless you, and send blessing upon you, and join you both together in goodness.”"]},"buhuth":{"ar":["وقوله: (( رفَّأ )) - بتشديد الفاء - أي هنأ، وهي كلمة يقولها أهل الجاهلية، فجاء النهي عنها كما في الحديث الآتي؛ لأن فيه تخصيص الدعاء بالبنين دون البنات حسب عادات الجاهلية لكراهية البنات."],"en":["The phrase meaning “congratulated” refers to the old customary formula used in the pre-Islamic period. It was later discouraged, as in the next narration, because it singled out sons and excluded daughters in line with pre-Islamic dislike of girls."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2130},{"key":"tirmidhi","label":"الترمذي","number":1091},{"key":"ahmad","label":"مسند الإمام أحمد","number":8956,"n":8956}]},{"num":6247,"demo":false,"sanad":"","matn":["عن الحسن قال: تزوج عقيل بن أبي طالب امرأة من بني جشم، فقيل له: بالرفاء والبنين. قال: قولوا كما قال رسول الله ﷺ: (( بارك الله فيكم، وبارك لكم ))"],"takhrij":"صحيح: رواه النسائي (٣٣٧١) واللفظ له، وابن ماجه (١٩٠٦)، وأحمد (١٧٣٩)، والبيهقي (١٤٨/٧).","grade":"صحيح","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3371), and this is his wording, also Ibn Majah (1906), Ahmad (1739), and al-Bayhaqi (7/148).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Al-Hasan said: ‘Aqil ibn Abi Talib married a woman from Banu Jusham, and people said to him: “May you have harmony and sons.” He said: Say instead what the Messenger of Allah ﷺ said: “May Allah bless you, and bless for you.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3371},{"key":"ibnmajah","label":"ابن ماجه","number":1906},{"key":"البیہقی","label":"البيهقي","number":148},{"key":"ahmad","label":"مسند الإمام أحمد","number":1739,"n":1739}]},{"num":6248,"demo":false,"sanad":"","matn":["عن بريدة قال: قال نفر من الأنصار لعلي: عندك فاطمة. فأتى رسول الله ﷺ، فسلّم عليه فقال: (( ما حاجة ابن أبي طالب؟ )) قال: ذكرت فاطمة بنت محمد رسول الله ﷺ. فقال رسول الله ﷺ: (( مرحبًا وأهلاً )) لم يزده عليهما. فخرج علي على أولئك الرهط من الأنصار ينتظرونه. قالوا: ما وراءك؟ قال: ما أدري غير أنه قال لي: (( مرحبًا وأهلاً )). قالوا: يكفيك من رسول الله ﷺ إحداهما، أعطاك الأهل أعطاك المرحب. فلما كان بعدما زوجه قال: (( يا علي، إنه لا بد للعروس من وليمة )) فقال سعد: عندي كبش، وجمع له رهط من الأنصار آصعًا من ذرة. فلما كان ليلة البناء قال: (( لا تحدث شيئًا حتى تلقاني )). قال: فدعا رسول الله ﷺ بإناء فتوضأ منه، ثم أفرغه على علي، ثم قال: (( اللهم بارك فيهما، وبارك عليهما، وبارك لهما في نسلهما ))"],"takhrij":"حسن: رواه ابن سعد (٨/٢١)، والطبراني في الكبير (٢/٤)، والطحاوي في مشكل الآثار (٥٩٤٧).","grade":"حسن","chapter_ar":"باب ما جاء في صيغ تهنئة النكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Sa‘d (8/21), al-Tabarani in al-Kabir (2/4), and al-Tahawi in Mushkil al-Athar (5947).","chapter_en":"Chapter on the reported forms of congratulating someone on marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Buraydah said: Some men from the Ansar said to ‘Ali: You have a chance with Fatimah. So he came to the Messenger of Allah ﷺ and greeted him, and he said: “What does the son of Abu Talib seek?” He said: I mentioned Fatimah, the daughter of Muhammad, the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said: “Welcome and greetings,” and said nothing more. Then ‘Ali came out to those men from the Ansar who were waiting for him. They said: What happened? He said: I do not know except that he said to me: “Welcome and greetings.” They said: One of those two from the Messenger of Allah ﷺ is enough for you. He gave you family ties and welcome. Then after he married him to her, he said: “O ‘Ali, a bridegroom must have a wedding feast.” Sa‘d said: I have a sheep. And some men from the Ansar gathered several measures of grain for him. When it was the night of the marriage, he said: “Do not do anything until you meet me.” Then the Messenger of Allah ﷺ called for a vessel and performed ablution from it, then poured it over ‘Ali and said: “O Allah, bless them both, send blessing upon them, and bless them in their offspring.”"]}},"tuhfa":{},"refs":[{"key":"ابن_سعد","label":"ابن سعد","number":8},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":2},{"key":"الطحاوی/مشکل_الاثار","label":"الطحاوي في مشكل الآثار","number":5947}]},{"num":6249,"demo":false,"sanad":"","matn":["عن عائشة قالت: تزوجني رسول الله ﷺ في شوال، وبنى بي في شوال، فأي نساء رسول الله ﷺ كان أحظى عنده مني؟ قالت: وكانت عائشة تستحب أن تُدخل نساءها في شوال."],"takhrij":"صحيح: رواه مسلم (١٤٢٣).","grade":"صحيح","chapter_ar":"باب استحباب التزوج في شوال والدخول فيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1423).","chapter_en":"Chapter on the recommendation of marrying and consummating the marriage in Shawwal","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ married me in Shawwal and consummated the marriage with me in Shawwal. So which of the wives of the Messenger of Allah ﷺ was more favored by him than me? She said: And ‘A’ishah used to like that the women under her care be brought to their husbands in Shawwal."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1423}]},{"num":6250,"demo":false,"sanad":"","matn":["عن خنساء بنت خِدام الأنصارية، أن أباها زوّجها - وهي ثيب - فكرهت ذلك، فأتت رسول الله ﷺ فردّ نكاحه."],"takhrij":"صحيح: رواه مالك (٢٥)، والبخاري (٥١٣٨).","grade":"صحيح","chapter_ar":"باب ردّ زواج الثيب الكارهة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (25) and al-Bukhari (5138).","chapter_en":"Chapter on annulling the marriage of a previously married woman who dislikes it","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":27,"content":{"translation":{"en":["Khansa’ bint Khidam al-Ansariyyah said that her father married her off while she had previously been married, and she disliked that. So she came to the Messenger of Allah ﷺ, and he annulled that marriage."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":25},{"key":"bukhari","label":"البخاري","number":5138}]},{"num":6251,"demo":false,"sanad":"","matn":["إن امرأة من ولد جعفر، تخوّفت أن يزوّجها وليُّها وهي كارهة، فأرسلت إلى شيخين من الأنصار: عبد الرحمن ومجمّع ابني جارية، قالا: فلا تخشَين! فإن خنساء بنت خِدام أنكحها أبوها وهي كارهة، فردّ النبي ﷺ ذلك.","قال سفيان: وأما عبد الرحمن فسمعته يقول عن أبيه: (( إن خنساء ))"],"takhrij":"صحيح: رواه البخاري (٦٩٦٩).","grade":"صحيح","chapter_ar":"باب تخيير البكر البالغ زوجها أبوها وهي كارهة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6969).","chapter_en":"Chapter on giving an adult virgin the choice if her father marries her off while she dislikes it","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["A woman from the descendants of Ja‘far feared that her guardian would marry her off while she disliked it, so she sent to two elderly men from the Ansar: ‘Abd al-Rahman and Mujamma‘, the two sons of Jariyah. They said: Do not be afraid, for Khansa’ bint Khidam was married off by her father while she disliked it, and the Prophet ﷺ nullified that.","Sufyan said: As for ‘Abd al-Rahman, I heard him say from his father: “Indeed Khansa’…”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6969}]},{"num":6252,"demo":false,"sanad":"","matn":["عن ابن عباس أن جارية بكراً أتت النبي ﷺ فذكرت له أن أباها زوّجها وهي كارهة. فخيّرها النبي ﷺ."],"takhrij":"صحيح: رواه أبو داود (٢٠٩٦)، وابن ماجه (١٨٧٥)، وأحمد (٢٤٦٩)، والدارقطني (٣/٢٣٤-٢٣٥).","grade":"صحيح","chapter_ar":"باب تخيير البكر البالغ زوجها أبوها وهي كارهة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2096), Ibn Majah (1875), Ahmad (2469), and al-Daraqutni (3/234–235).","chapter_en":"Chapter on giving an adult virgin the choice if her father marries her off while she dislikes it","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":28,"content":{"translation":{"en":["Ibn ‘Abbas narrated that a virgin young woman came to the Prophet ﷺ and told him that her father had married her off while she disliked it, so the Prophet ﷺ gave her the choice."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2096},{"key":"ibnmajah","label":"ابن ماجه","number":1875},{"key":"الدارقطنی","label":"الدارقطني","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":2469,"n":2469}]},{"num":6253,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( لا تُنكح الأيم حتى تُستأمر، ولا تنكح البكر حتى تُستأذن )). قالوا: يا رسول الله، وكيف إذنها؟ قال: (( أن تسكت ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٣٦)، ومسلم (١٤١٩).","grade":"متفق عليه","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5136) and Muslim (1419).","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “A previously married woman must not be married until she is consulted, and a virgin must not be married until her permission is sought.” They said: O Messenger of Allah, how is her permission given? He said: “By her silence.”"]},"buhuth":{"ar":["النساء على قسمين: الثيب والبكر. وذكر الأيم بمقابل البكر دليل على أنه أراد بالأيم الثيب. وسكوت البكر عند الاستئذان دليل على رضاها، لأنها قد تستحي أن تُفصح بالنكاح، وتُظهر الرغبة فيه. بخلاف الثيب فقد تُظهر وتبدي الرغبة في النكاح من عدمه لزوال حياء البكر عنها، فتتكلم وتأمر وليها أن يزوجها."],"en":["Women are of two types: previously married and virgin. Mentioning “the previously married woman” in contrast to the virgin shows that what is meant here by al-ayyim is the previously married woman. The silence of the virgin when asked for permission is taken as a sign of her approval, because she may feel shy about stating it openly and expressing interest in marriage. As for the previously married woman, she may openly express whether she wants marriage or not, since the shyness of a virgin is no longer present, so she speaks and instructs her guardian to marry her as she wishes."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5136},{"key":"muslim","label":"مسلم","number":1419}]},{"num":6254,"demo":false,"sanad":"","matn":["عن أم سلمة قالت: أرسل إليّ رسولُ الله ﷺ حاطبَ بن أبي بلتعة يخطبني له. فقلتُ: إن لي بنتاً وأنا غيور. فقال: (( وأما ابنتها فندعو الله أن يُغنيها عنها، وأدعو الله أن يذهب بالغيرة ))."],"takhrij":"صحيح: رواه مسلم (٣:٩١٨).","grade":"صحيح","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3:918).","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ sent Hatib ibn Abi Balta‘ah to propose to me on his behalf. I said: I have a daughter, and I am a jealous woman. He said: “As for her daughter, we ask Allah to make her independent of her mother, and I ask Allah to remove jealousy.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":3}]},{"num":6255,"demo":false,"sanad":"","matn":["عن عائشة قالت: سألت رسول الله ﷺ عن الجارية يُنكحها أهلها، أتستأمر أم لا؟ فقال لها رسول الله ﷺ: (( نعم تُستأمر )). فقالت عائشة: فقلت له: فإنها تستحي. فقال رسول الله ﷺ: (( فذلك إذنها إذا هي سكتت ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٣٧)، ومسلم (١٤٢٠). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5137) and Muslim (1420). The wording is that of Muslim.","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["‘A’ishah said: I asked the Messenger of Allah ﷺ about a young woman whose family wants to marry her off: should her permission be sought or not? The Messenger of Allah ﷺ said to her: “Yes, her permission should be sought.” ‘A’ishah said: I said to him: But she feels shy. The Messenger of Allah ﷺ said: “That is her permission when she remains silent.”"]},"buhuth":{"ar":["ولفظ البخاري: أنها قالت: يا رسول الله، إن البكر تستحي. قال: (( رضاها صمتها )).","وفي روايات أخرى: (( استأمروا النساء في أبضاعهن )) رواه ابن حبان في صحيحه (٤٠٨٠)."],"en":["The wording in al-Bukhari is: She said, O Messenger of Allah, the virgin feels shy. He said: “Her consent is her silence.”","In other narrations: “Seek the women’s permission concerning their marriage.” Narrated by Ibn Hibban in his Sahih (4080)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5137},{"key":"muslim","label":"مسلم","number":1420}]},{"num":6256,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول الله ﷺ قال: (( الأيم أحق بنفسها من وليّها، والبكر تُستأذن في نفسها، وإذنها صُماتها ))."],"takhrij":"صحيح: رواه مالك (٤)، ومسلم (٦٦:١٤٢١).","grade":"صحيح","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (4) and Muslim (66:1421).","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Ibn ‘Abbas narrated that the Messenger of Allah ﷺ said: “The previously married woman has more right over herself than her guardian, and the virgin is asked for permission regarding herself, and her permission is her silence.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":4},{"key":"muslim","label":"مسلم","number":66}]},{"num":6257,"demo":false,"sanad":"","matn":["عن العُرس بن عُميرة قال: قال رسول الله ﷺ: (( آمروا النساء لتُعرب الثيب عن نفسها، وإذن البكر صماتها ))."],"takhrij":"حسن: رواه الطبراني في الكبير (١٧/١٣٨)، والطحاوي في شرح المعاني (٤/٣٦٨) واللفظ للطبراني.","grade":"حسن","chapter_ar":"باب الأيم أحق بنفسها، والبكر تستأذن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Kabir (17/138), and al-Tahawi in Sharh al-Ma‘ani (4/368). The wording is that of al-Tabarani.","chapter_en":"Chapter on the previously married woman having more right over herself, and the virgin being asked for permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":29,"content":{"translation":{"en":["Al-‘Urs ibn ‘Umayrah said: The Messenger of Allah ﷺ said: “Consult the women, so that the previously married woman may express her own view, and the permission of the virgin is her silence.”"]},"buhuth":{"ar":["ولفظ الطحاوي: (( الثيب تُعرب عن نفسها، والبكر رضاها صمتها )).","فقه الباب: في أحاديث الباب دليل على أن تزويج الثّيب لا يجوز إلا بإذنها.","فقوله ﷺ: (( الأيم أحق بنفسها )) أراد به أحق بنفسها من وليها في اختيار الأزواج من شاءت. فتقول مثلا: أنا أرضى فلانا، ولا أرضى فلانا. وعلى الولي أن يزوجها كما تشاء هي، وليس هي تباشر بتزويج نفسها.","وأما الاستدلال بهذه الأحاديث على انعقاد النكاح بدون ولي فليس بصحيح."],"en":["The wording of al-Tahawi is: “The previously married woman expresses her own view, and the approval of the virgin is her silence.”","Legal understanding of this chapter: The narrations in this chapter show that marrying off a previously married woman is not permissible except with her permission.","His statement ﷺ, “The previously married woman has more right over herself,” means that she has more right than her guardian in choosing whichever husband she wishes. So she may say, for example: I approve of so-and-so, and I do not approve of so-and-so. The guardian must marry her according to her choice, but she does not personally conduct her own marriage contract.","As for using these narrations as proof that a marriage is valid without a guardian, that is not correct."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":17},{"key":"الطحاوی/شرح_المعانی","label":"الطحاوي في شرح المعاني","number":4}]},{"num":6258,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، قال: تُوفي عثمان بن مظعون، وترك ابنة له من خويلة بنت حكيم بن أمية بن حارثة بن الأوقص، قال: وأوصى إلى أخيه قدامة بن مظعون. قال عبد الله: وهما خالاي. قال: فخطبت إلى قدامة بن مظعون ابنة عثمان بن مظعون، فزوّجنيها. ودخل المغيرة بن شعبة - يعني إلى أمها - فأرغبها في المال، فحطّت إليه، وحطّت الجارية إلى هوى أمها، فأبيا، حتى ارتفع أمرهما إلى رسول الله ﷺ. فقال قدامة بن مظعون: يا رسول الله، ابنة أخي، أوصى بها إليّ، فزوّجتها ابن عمّتها عبد الله بن عمر، فلم أقصر بها في الصلاح ولا في الكفاءة، ولكنها امرأة، وإنما حطّت إلى هوى أمها. قال: فقال رسول الله ﷺ: (( هي يتيمة، ولا تنكح إلا بإذنها )). قال: فانتزعت والله مني بعد أن ملكتها، فزوجوها المغيرة."],"takhrij":"حسن: رواه الإمام أحمد (٦١٣٦).","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6136).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: ‘Uthman ibn Maz‘un died and left behind a daughter from Khawlah bint Hakim ibn Umayyah ibn Harithah ibn al-Awqas. He said: And he entrusted her to his brother Qudamah ibn Maz‘un. ‘Abdullah said: They are both my maternal uncles. He said: So I proposed to Qudamah ibn Maz‘un for the daughter of ‘Uthman ibn Maz‘un, and he married her to me. Then al-Mughirah ibn Shu‘bah approached her mother and encouraged her with wealth, so the mother inclined toward him, and the girl followed the desire of her mother, and they both refused, until their matter was brought to the Messenger of Allah ﷺ. Qudamah ibn Maz‘un said: O Messenger of Allah, she is my brother’s daughter, and he entrusted her to me. I married her to her cousin ‘Abdullah ibn ‘Umar, and I was not lacking regarding her in righteousness or suitability, but she is a woman, and she merely followed the preference of her mother. The Messenger of Allah ﷺ then said: “She is an orphan girl, and she is not to be married except with her permission.” He said: By Allah, she was taken away from me after I had been given her in marriage, and they married her to al-Mughirah."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":6136},{"key":"ahmad","label":"مسند الإمام أحمد","number":6136,"n":6136}]},{"num":6259,"demo":false,"sanad":"","matn":["عن أبي موسى قال: قال رسول الله ﷺ: (( تُستأمر اليتيمة في نفسها، فإن سكتت فقد أذنتْ، وإن أبتْ لم تُكره ))."],"takhrij":"حسن: رواه أحمد (١٩٥١٦)، والبزار - كشف الأستار (١٤٢٣)، وصحّحه ابن حبان (٤٠٨٥)، والحاكم (٢٧٠٢).","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (19516), al-Bazzar in Kashf al-Astar (1423), authenticated by Ibn Hibban (4085), and al-Hakim (2702).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Abu Musa said: The Messenger of Allah ﷺ said: “The orphan girl is asked for her permission regarding herself. If she remains silent, then she has given permission, and if she refuses, she is not to be forced.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1423},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4085},{"key":"ahmad","label":"مسند الإمام أحمد","number":19516,"n":19516},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1422,"n":1423},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4073,"n":4069},{"key":"hakim","label":"المستدرك على الصحيحين","number":2702,"n":2688}]},{"num":6260,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( واليتيمة تستأمر في نفسها، فإن صمتت فهو إذنها، وإن أبتْ فلا جواز عليها )) يعني إذا أدركت فردّتْ."],"takhrij":"حسن: رواه أبو داود (٢٠٩٣)، والترمذي (١١٠٩)، والنسائي (٣٢٧٠)، وأحمد (٧٥١٩).","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2093), al-Tirmidhi (1109), al-Nasa’i (3270), and Ahmad (7519).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The orphan girl is asked for permission regarding herself. If she remains silent, that is her permission, and if she refuses, she is not to be forced.” Meaning: when she reaches maturity and rejects it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2093},{"key":"tirmidhi","label":"الترمذي","number":1109},{"key":"nasai","label":"النسائي","number":3270},{"key":"ahmad","label":"أحمد","number":7519}]},{"num":6261,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول الله ﷺ قال: (( الأيم أولى بأمرها، واليتيمة تُستأمر في نفسها، وإذنها صماتها ))."],"takhrij":"حسن: رواه النسائي (٣٢٦٢)، وأحمد (٢٣٦٥)، وابن أبي شيبة (٤/١٣٦)، والدارقطني (٣/٢٣٨-٢٣٩).","grade":"حسن","chapter_ar":"باب أن اليتيمة لا تنكح إلا بإذنها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3262), Ahmad (2365), Ibn Abi Shaybah (4/136), and al-Daraqutni (3/238–239).","chapter_en":"Chapter on the orphan girl not being married except with her permission","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["Ibn ‘Abbas narrated that the Messenger of Allah ﷺ said: “The previously married woman has more right concerning her affair, and the orphan girl is asked for permission regarding herself, and her permission is her silence.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3262},{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":4},{"key":"الدارقطنی","label":"الدارقطني","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":2365,"n":2365},{"key":"sh9771","label":"سنن الدارقطني","number":3575,"n":3588}]},{"num":6262,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال: (( لا تسأل المرأة طلاق أختها لتستفرغ صَحْفَتَها، ولتنكحْ، فإنما لها ما قُدّرَ لها ))."],"takhrij":"متفق عليه: رواه مالك (٧)، والبخاري (٦٦٠١)، ومسلم (٣٨:١٤٠٨).","grade":"متفق عليه","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (7), al-Bukhari (6601), and Muslim (38:1408).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “A woman must not ask for her sister to be divorced so that she may empty her bowl. Let her marry, for she will only have what has been decreed for her.”"]},"buhuth":{"ar":["وقوله: (( صحفتها )) الصحفة: إناء من آنية الطعام."],"en":["His saying, “her bowl,” refers to a dish from the dishes used for food."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":7},{"key":"bukhari","label":"البخاري","number":6601},{"key":"muslim","label":"مسلم","number":38}]},{"num":6263,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول الله ﷺ عن التلقي، وأن يبتاع المهاجر للأعراب، وأن تشترط المرأة طلاق أختها… الحديث."],"takhrij":"صحيح: رواه البخاري (٢٧٢٧).","grade":"صحيح","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2727).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade meeting traders before they reached the market, forbade a townsman from buying on behalf of a Bedouin, and forbade a woman from stipulating the divorce of her sister… the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2727}]},{"num":6264,"demo":false,"sanad":"","matn":["عن عائشة قالت: اختصم سعد بن أبي وقاص وعبد الله بن زمعة في غلام. فقال سعد: هذا يا رسولَ الله ابن أخي عتبة بن أبي وقاص، عَهِد إليَّ أنه ابنه، انظر إلى شبهه. وقال عبد بن زمعة: هذا أخي يا رسول الله، وُلِدَ على فراش أبي من وليدته. فنظر رسول الله ﷺ إلى شبهه، فرأى شبها بيّنا بعتبة، فقال: (( هو لك يا عبد بن زمعة، الولد للفراش، وللعاهر الحجر، واحتجبي منه يا سودة بنت زمعة )). فلم تره قط. وفي رواية زيادة: (( هو أخوك يا عبد ))."],"takhrij":"متفق عليه: رواه مالك (٢٢)، والبخاري (٢٢١٨)، ومسلم (١٤٥٧).","grade":"متفق عليه","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (22), al-Bukhari (2218), and Muslim (1457).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["‘A’ishah said: Sa‘d ibn Abi Waqqas and ‘Abdullah ibn Zam‘ah disputed over a boy. Sa‘d said: O Messenger of Allah, this is the son of my brother ‘Utbah ibn Abi Waqqas. He entrusted me that he was his son. Look at his resemblance. ‘Abd ibn Zam‘ah said: This is my brother, O Messenger of Allah. He was born on my father’s bed from his slave-woman. The Messenger of Allah ﷺ looked at his resemblance and saw a clear resemblance to ‘Utbah, so he said: “He is yours, O ‘Abd ibn Zam‘ah. The child belongs to the marriage bed, and the adulterer gets the stone. And veil yourself from him, O Sawdah bint Zam‘ah.” So she never saw him again. In another narration there is the addition: “He is your brother, O ‘Abd.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":22},{"key":"bukhari","label":"البخاري","number":2218},{"key":"muslim","label":"مسلم","number":1457}]},{"num":6265,"demo":false,"sanad":"","matn":["عن ابن عمر أن رجلاً من أهل البادية أتى النبي ﷺ فقال: يا رسول الله، إن امرأتي ولدتْ على فراشي غلاماً أسود، وإنا أهل بيت لم يكن فينا أسود قط. قال: (( هل لك من إبل؟ )) قال: نعم. قال: (( فما ألوانها؟ )) قال: حمر. قال: (( هل فيها أسود؟ )) قال: لا. قال: (( فيها أورق؟ )) قال: نعم. قال: (( فأنى كان ذلك؟ )) قال: عسى أن يكون نزعه عرق. قال: (( فلعل ابنك هذا نزعه عِرقٌ ))."],"takhrij":"حسن: رواه ابن ماجه (٢٠٠٣).","grade":"حسن","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2003).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Ibn ‘Umar narrated that a man from the desert came to the Prophet ﷺ and said: O Messenger of Allah, my wife has given birth on my bed to a black boy, and we are a household in which there has never been any black person. He said: “Do you have camels?” He said: Yes. He said: “What are their colors?” He said: Red. He said: “Are there any black among them?” He said: No. He said: “Are there any grayish ones among them?” He said: Yes. He said: “How did that happen?” He said: Perhaps some inherited trait drew it out. He said: “Then perhaps this son of yours was likewise drawn out by an inherited trait.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2003}]},{"num":6266,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال النبي ﷺ: (( الولد للفراش وللعاهر الحجر ))."],"takhrij":"متفق عليه: رواه البخاري (٦٨١٨)، ومسلم (١٤٥٨).","grade":"متفق عليه","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6818) and Muslim (1458).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “The child belongs to the marriage bed, and the adulterer gets the stone.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6818},{"key":"muslim","label":"مسلم","number":1458}]},{"num":6267,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: قال رسول الله ﷺ: (( الولد للفراش، وللعاهر الحجر ))."],"takhrij":"صحيح: رواه النسائي (٣٤٨٦)، وابن حبان (٤١٠٤).","grade":"صحيح","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3486) and Ibn Hibban (4104).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Ibn Mas‘ud said: The Messenger of Allah ﷺ said: “The child belongs to the marriage bed, and the adulterer gets the stone.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3486},{"key":"ibnhibban","label":"ابن حبان","number":4104}]},{"num":6268,"demo":false,"sanad":"","matn":["عن عمر أن رسول الله ﷺ قضى بالولد للفراش."],"takhrij":"صحيح: رواه ابن ماجه (٢٠٠٥)، وأحمد (١٧٣).","grade":"صحيح","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2005) and Ahmad (173).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["‘Umar narrated that the Messenger of Allah ﷺ ruled that the child belongs to the marriage bed."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2005},{"key":"ahmad","label":"مسند الإمام أحمد","number":173,"n":173}]},{"num":6269,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص قال: قام رجل فقال: يا رسول الله، إن فلاناً ابني، قد عاهرتُ بأمه في الجاهلية. فقال رسول الله ﷺ: (( لا دعوة في الإسلام، ذهب أمر الجاهلية، الولد للفراش، وللعاهر الحجر ))."],"takhrij":"حسن: رواه أبو داود (٢٢٧٤)، والإمام أحمد (٦٩٣٣).","grade":"حسن","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2274) and Imam Ahmad (6933).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said: A man stood up and said: O Messenger of Allah, so-and-so is my son; I committed fornication with his mother in the pre-Islamic period. The Messenger of Allah ﷺ said: “There is no such claim in Islam. The matter of the pre-Islamic period has passed. The child belongs to the marriage bed, and the adulterer gets the stone.”"]},"buhuth":{"ar":["والدِّعوة: بكسر الدال، وسكون العين. هو أن ينتسبَ الرجلُ إلى غير أبيه، وعشيرتِه، وقد كانوا يفعلونه في الجاهلية، فمنعه الإسلام، وجعل الولدَ للفراش."],"en":["The word translated here as “claim” refers to a man attributing himself to someone other than his real father and tribe. They used to do that in the pre-Islamic period. Islam prohibited it and assigned the child to the marriage bed."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2274},{"key":"الامام_احمد","label":"الإمام أحمد","number":6933},{"key":"ahmad","label":"مسند الإمام أحمد","number":6933,"n":6933}]},{"num":6270,"demo":false,"sanad":"","matn":["عن أبي أمامة الباهلي يقول: سمعت رسول الله ﷺ يقول في خطبة عام حجة الوداع: (( الولد للفراش وللعاهر الحجر ))."],"takhrij":"حسن: رواه الترمذي (٢١٢٠)، وأبو داود (٣٥٦٥)، وابن ماجه (٢٠٠٧)، وأحمد (٢٢٢٩٤).","grade":"حسن","chapter_ar":"باب اشتراط المرأة أن يطلق الزوجُ زوجتَه الأولى","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2120), Abu Dawud (3565), Ibn Majah (2007), and Ahmad (22294).","chapter_en":"Chapter on a woman stipulating that a husband divorce his first wife","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["Abu Umamah al-Bahili said: I heard the Messenger of Allah ﷺ say in the sermon of the Farewell Pilgrimage: “The child belongs to the marriage bed, and the adulterer gets the stone.”"]},"buhuth":{"ar":["فقه الباب: كان من عادات الجاهلية إلحاقُ النسب بالزنا، وكانوا يستأجرون الإماء للوَطْءِ، فإن اعترفت الأم بأن الولد له ألحقوه به، فجاء الإسلامُ وأبطلَ ذلك، وأمرَ بإلحاق الولد بالفراش، كما وقع في مخاصمة سعد بن أبي وقاص وعبد بن زمعة بن الأسود في ولدٍ، وذلك أنَّ عتبة بن أبي وقاص وقعَ على أمةِ زمعة بن الأسود، فحملت الأمةُ، وولدتْ غلامًا، فلما حضر وفاةُ عتبة عَهِدَ لأخيه سعد بأن يأخذ هذا الولد، ويلحقه به، ثم مات عتبةُ مشركًا، فحينئذِ تخاصمَ سعدٌ مع عبد بن زمعة في ذلك الغلام، فاحتجَّ سعدٌ لاستلحاق الغلام بأخيه عتبة على عاداتهم في استلحاق الولد بالزنا، وتمسَّكَ عبدُ بنُ زمعة بفراش أبيه، فقضى النبي ﷺ: (( الولدُ للفراشِ ))، وقطعَ الإلحاق بالزنا بقوله: (( وللعاهر الحجرُ ))."],"en":["Legal understanding of this chapter: It was among the customs of the pre-Islamic period to attach lineage through fornication. They used to hire slave women for intercourse, and if the mother acknowledged that the child belonged to a certain man, they would attach him to him. Islam came and abolished that, and commanded that the child be attributed to the marriage bed. This is what occurred in the dispute between Sa‘d ibn Abi Waqqas and ‘Abd ibn Zam‘ah ibn al-Aswad over a boy. ‘Utbah ibn Abi Waqqas had intercourse with the slave woman of Zam‘ah ibn al-Aswad, so she became pregnant and gave birth to a boy. When ‘Utbah was on his deathbed, he instructed his brother Sa‘d to take this boy and attribute him to him. ‘Utbah then died as a polytheist. After that, Sa‘d and ‘Abd ibn Zam‘ah disputed about the boy. Sa‘d argued for attributing the boy to his brother ‘Utbah according to their old custom of attributing children through fornication, while ‘Abd ibn Zam‘ah relied on his father’s marriage bed. So the Prophet ﷺ ruled: “The child belongs to the marriage bed,” and cut off attribution through fornication by saying: “and the adulterer gets the stone.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2120},{"key":"abudawud","label":"أبو داود","number":3565},{"key":"ibnmajah","label":"ابن ماجه","number":2007},{"key":"ahmad","label":"مسند الإمام أحمد","number":22294,"n":22294}]},{"num":6271,"demo":false,"sanad":"","matn":["عن عائشة قالت: إن رسول الله ﷺ دخل عليّ مسروراً تبرق أسارير وجهه فقال: (( ألم تري أن مجزّزاً نظر آنفا إلى زيد بن حارثة وأسامة بن زيد فقال: إن هذه الأقدام بعضها من بعض ))."],"takhrij":"متفق عليه: رواه البخاري (٦٧٧٠)، ومسلم (١٤٥٩).","grade":"متفق عليه","chapter_ar":"باب ثبوت النسب بالقافة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6770) and Muslim (1459).","chapter_en":"Chapter on establishing lineage through expert resemblance-tracing","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في النكاح وشروطه","group_en":"Collected chapters on what has been reported regarding marriage and its conditions","part_no":24,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ entered upon me happy, with the lines of his face shining, and said: “Did you not see that Mujazziz just now looked at Zayd ibn Harithah and Usamah ibn Zayd and said: These feet belong to one another?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6770},{"key":"muslim","label":"مسلم","number":1459}]},{"num":6272,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول الله ﷺ قال: (( لا يخطب أحدكم على خِطبة أخيه ))","وزاد في رواية: (( حتى يترك الخاطب قبله أو يأذن له الخاطب ))."],"takhrij":"متفق عليه: رواه مالك (٢) والبخاري (٥١٤٢) ومسلم (١٤١٢).","grade":"متفق عليه","chapter_ar":"باب النهي أن يخطب الرّجل على خِطبة أخيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (2), al-Bukhari (5142), and Muslim (1412).","chapter_en":"Chapter on the prohibition of a man proposing over his brother’s proposal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “None of you should propose over the proposal of his brother.”","In another narration there is an addition: “Until the first suitor leaves it or gives him permission.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2},{"key":"bukhari","label":"البخاري","number":5142},{"key":"muslim","label":"مسلم","number":1412}]},{"num":6273,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال: (( لا يخطب أحدكم على خطبة أخيه ))","وزاد في رواية: (( حتى ينكح أو يترك ))."],"takhrij":"متفق عليه: رواه مالك (١) والبخاري (٥١٤٣) ومسلم (١٤١٣).","grade":"متفق عليه","chapter_ar":"باب النهي أن يخطب الرّجل على خِطبة أخيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (5143), and Muslim (1413).","chapter_en":"Chapter on the prohibition of a man proposing over his brother’s proposal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “None of you should propose over the proposal of his brother.”","In another narration there is an addition: “Until he marries or leaves it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":5143},{"key":"muslim","label":"مسلم","number":1413}]},{"num":6274,"demo":false,"sanad":"","matn":["عن أبي بكر بن أبي الجهم بن صُخير العدوي قال: سمعت فاطمة بنت قيس تقول: إن زوجها طلّقها ثلاثا، فلم يجعل لها رسول الله ﷺ سكنى ولا نفقة، قالت: قال لي رسول الله ﷺ: (( إذا حللتِ فآذنيني )) فآذنته. فخطبها معاوية وأبو جهم وأسامة بن زيد. فقال رسول الله ﷺ: (( أما معاوية فرجل تَرِبٌ لا مال له، وأما أبو جهم فرجل ضرّاب للنساء، ولكن أسامة بن زيد )).","فقالت بيدها هكذا: أسامة! أسامة! فقال لها رسول الله ﷺ: (( طاعة الله وطاعة رسوله خير لك )).","قالت: فتزوجته فاغتبطتُ."],"takhrij":"صحيح: رواه مسلم (٤٧:١٤٨٠). وقوله: (( تَرِب )) يعني الفقير، لأنه من شدة فقره يكون ملصقا بالتراب.","grade":"صحيح","chapter_ar":"باب النهي أن يخطب الرّجل على خِطبة أخيه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (47:1480). His saying “tārib” means poor, because from the severity of his poverty he is as though attached to the dust.","chapter_en":"Chapter on the prohibition of a man proposing over his brother’s proposal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abu Bakr ibn Abi al-Jahm ibn Sukhayr al-‘Adawi said: I heard Fatimah bint Qays say that her husband divorced her three times, and the Messenger of Allah ﷺ did not assign for her any housing or maintenance. She said: The Messenger of Allah ﷺ said to me, “When you become lawful for marriage, inform me.” So I informed him. Then Mu‘awiyah, Abu Jahm, and Usamah ibn Zayd proposed to her. The Messenger of Allah ﷺ said: “As for Mu‘awiyah, he is a poor man with no wealth. As for Abu Jahm, he is a man who beats women. Rather, marry Usamah ibn Zayd.”","She gestured with her hand like this and said: Usamah? Usamah? So the Messenger of Allah ﷺ said to her: “Obedience to Allah and obedience to His Messenger are better for you.”","She said: So I married him and was greatly pleased."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":47}]},{"num":6275,"demo":false,"sanad":"","matn":["عن أبي سلمة، أن فاطمة بنت قيس - أخت الضحاك بن قيس - أخبرته أنّ أبا حفص بن المغيرة المخزومي طلّقها ثلاثاً، ثم انطلق إلى اليمن، فقال لها أهله: ليس لك علينا نفقة. فانطلق خالد بن الوليد في نفر، فأتوا رسول الله ﷺ في بيت ميمونة، فقالوا: إن أبا حفص طلّق امرأته ثلاثاً، فهل لها من نفقة؟ فقال رسول الله ﷺ: (( ليست لها نفقة، وعليها العدة )). وأرسل إليها: (( أن لا تسبقيني بنفسك … )) الحديث. وفي لفظ: (( لا تفوتينا بنفسك ))."],"takhrij":"صحيح: رواه مسلم (٣٨:١٤٨٠). وقوله: “لا تسبقيني” فيه التعريض بالخِطبة.","grade":"صحيح","chapter_ar":"باب التعريض لخطبة المرأة المتوفى عنها زوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (38:1480). His saying “Do not get ahead of us regarding yourself” contains an indirect indication of proposing.","chapter_en":"Chapter on indirect mention of proposing to a woman whose husband has died","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abu Salamah reported that Fatimah bint Qays, the sister of al-Dahhak ibn Qays, informed him that Abu Hafs ibn al-Mughirah al-Makhzumi divorced her three times, then left for Yemen. His family said to her: You have no maintenance due from us. So Khalid ibn al-Walid went with a group to the Messenger of Allah ﷺ in the house of Maymunah and said: Abu Hafs has divorced his wife three times, so does she have any maintenance? The Messenger of Allah ﷺ said: “She has no maintenance, but she must observe the waiting period.” And he sent word to her: “Do not get ahead of us regarding yourself…” in the rest of the hadith. In another wording: “Do not let us miss the chance regarding yourself.”"]},"intro":{"ar":["قال الله تعالى: ﴿ وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّسَاءِ أَوْ أَكْنَنْتُمْ فِي أَنْفُسِكُمْ ﴾ [البقرة: ٢٣٥]","قال ابن عباس: ( فِيمَا عَرَّضْتُمْ ) يقول: (( إني أريد التزويج، ولوددتُ أنه يُيسَّر لي امرأة صالحة )).","صحيح: رواه البخاري (٥١٢٤)."],"en":["Allah Most High said: “There is no blame upon you for what you indirectly allude to concerning a proposal to women, or what you keep concealed within yourselves.” [al-Baqarah: 235]","Ibn ‘Abbas said regarding “what you indirectly allude to”: It means saying, “I wish to marry, and I would like for a righteous woman to be made easy for me.”","Authentic: Narrated by al-Bukhari (5124)."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":38}]},{"num":6276,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال:","كان رسول الله ﷺ يعلمنا الاستخارة في الأمور كلها كما يعلمنا السورة من القرآن، يقول:","«إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ، فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ لِيَقُلْ:","اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ.","اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي - أَوْ قَالَ: عَاجِلِ أَمْرِي وَآجِلِهِ - فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ.","وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي - أَوْ قَالَ: فِي عَاجِلِ أَمْرِي وَآجِلِهِ - فَاصْرِفْهُ عَنِّي، وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي».","قال:","«وَيُسَمِّي حَاجَتَهُ»."],"takhrij":"صحيح: رواه البخاري (١١٦٢).","grade":"صحيح","chapter_ar":"باب الاستخارة في الخِطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1162).","chapter_en":"Chapter on seeking guidance in betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported:","The Messenger of Allah ﷺ used to teach us istikhārah concerning all matters just as he would teach us a surah from the Qurʾān. He would say:","“When one of you intends to undertake a matter, let him pray two rakʿahs other than the obligatory prayer, then say:","‘O Allah, I seek the better choice from You by Your knowledge, and I seek ability from You by Your power, and I ask You from Your immense bounty. You are able and I am not; You know and I do not know; and You are the Knower of the unseen.","O Allah, if You know that this matter is good for me in my religion, my livelihood, and the outcome of my affair—or he said: in the immediate and later parts of my affair—then decree it for me, make it easy for me, and then bless it for me.","And if You know that this matter is bad for me in my religion, my livelihood, and the outcome of my affair—or he said: in the immediate and later parts of my affair—then turn it away from me and turn me away from it, decree good for me wherever it may be, and then make me content with it.’”","He said:","“And he should mention his particular need.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1162}]},{"num":6277,"demo":false,"sanad":"","matn":["عن أيوب بن خالد بن أبي أيوب الأنصاري، حدثه عن أبيه، عن جده أبي أيوب أن رسول الله ﷺ قال: (( اكتم الخطبة، ثم توضأ فأحسن وضوءك، ثم صلِّ ما كتب الله لك، ثم احمد ربك، ومجِّده، ثم قل: اللهم إنك تقدر ولا أقدر، وتعلم ولا أعلم، وأنت علام الغيوب، فإن رأيت في فلانة - تسميها باسمها - خيراً لي في ديني ودنياي وآخرتي فاقدُرْها لي، وإن كان غيرُها خيراً لي منها في ديني ودنياي وآخرتي فاقض لي ذلك ))."],"takhrij":"حسن: رواه أحمد (٢٣٥٩٧)، وابن خزيمة (١٢٢٠)، وابن حبان (٤٠٤٠)، والحاكم (١١٨١).","grade":"حسن","chapter_ar":"باب الاستخارة في الخِطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23597), Ibn Khuzaymah (1220), Ibn Hibban (4040), and al-Hakim (1181).","chapter_en":"Chapter on seeking guidance in betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ayyub ibn Khalid ibn Abi Ayyub al-Ansari narrated from his father, from his grandfather Abu Ayyub, that the Messenger of Allah ﷺ said: “Keep the proposal concealed, then perform ablution and do it well, then pray whatever Allah has prescribed for you, then praise your Lord and glorify Him, then say: O Allah, You are able and I am not able, and You know and I do not know, and You are the Knower of the unseen. If You know that there is good for me in so-and-so — naming her by name — in my religion, my worldly life, and my Hereafter, then decree her for me. And if someone other than her is better for me than her in my religion, my worldly life, and my Hereafter, then decree that for me.”"]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ","label":"ابن خزيمة","number":1220},{"key":"ahmad","label":"مسند الإمام أحمد","number":23596,"n":23596},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1747,"n":1744},{"key":"hakim","label":"المستدرك على الصحيحين","number":1181,"n":1174}]},{"num":6278,"demo":false,"sanad":"","matn":["عن سهل بن سعد:","أن امرأة جاءت إلى رسول الله ﷺ فقالت:","يا رسول الله، جئت لأهب لك نفسي.","فنظر إليها رسول الله ﷺ، فصعّد النظر إليها وصوّبه، ثم طأطأ رأسه.","فلما رأت المرأة أنه لم يقض فيها شيئًا جلست… الحديث."],"takhrij":"متفق عليه: رواه البخاري (٥١٢٦)، ومسلم (١٤٢٥/٧٦).","grade":"متفق عليه","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5126) and Muslim (1425/76).","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Sahl ibn Saʿd reported:","A woman came to the Messenger of Allah ﷺ and said:","“O Messenger of Allah, I have come to offer myself to you.”","The Messenger of Allah ﷺ looked at her, looking her up and down, then lowered his head.","When the woman saw that he had not made any decision concerning her, she sat down… the remainder of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5126},{"key":"muslim","label":"مسلم","number":1425}]},{"num":6279,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: كنت عند النبي ﷺ فأتاه رجل فأخبره أنه تزوّج امرأة من الأنصار. فقال له رسول الله ﷺ: (( أنظرت إليها؟ )) قال: لا، قال: (( فاذهب فانظر إليها، فإن في أعين الأنصار شيئاً ))."],"takhrij":"صحيح: رواه مسلم (٧٤:١٤٢٤). قوله: (( في أعين الأنصار شيئاً )) قيل المراد بذلك صغر، وقيل زرقة.","grade":"صحيح","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (74:1424). His statement “there is something in the eyes of the Ansar” was said by some to mean smallness, and by others to mean a bluish tint.","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: I was with the Prophet ﷺ when a man came to him and informed him that he had married a woman from the Ansar. The Messenger of Allah ﷺ said to him: “Did you look at her?” He said: No. He said: “Then go and look at her, for there is something in the eyes of the Ansar.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":74}]},{"num":6280,"demo":false,"sanad":"","matn":["عن أبي حميد أو أبي حميدة - وقد رأى رسول الله ﷺ - قال: قال رسول الله ﷺ: (( إذا خطب أحدكم امرأة فلا جناح عليه أن ينظر إليها، إذا كان إنما ينظر لخطبة، وإن كانت لا تعلم ))."],"takhrij":"صحيح: رواه أحمد (٢٣٦٠٢).","grade":"صحيح","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (23602).","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Humayd, or Abu Humaydah — and he had seen the Messenger of Allah ﷺ — said: The Messenger of Allah ﷺ said: “When one of you proposes to a woman, there is no blame on him if he looks at her, so long as he is only looking for the sake of marriage, even if she does not know.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23602,"n":23602}]},{"num":6281,"demo":false,"sanad":"","matn":["عن المغيرة بن شعبة، قال: أتيت النبي ﷺ، فذكرت له امرأة أخطبها، فقال: (( اذهب فانظر إليها، فإنه أجدر أن يُؤدم بينكما )). قال: فأتيت امرأة من الأنصار، فخطبتها إلى أبويها، وأخبرتهما بقول رسول الله ﷺ، فكأنهما كرها ذلك. قال: فسمعت ذلك المرأة وهي في خدرها، فقالت: إنْ كان رسول الله ﷺ أمرك أن تنظر، فانظر، وإلا فإني أنشدك. كأنها عظَّمت ذلك عليه. قال: فنظرتُ إليها فتزوجتُها. فذكر من موافقتها."],"takhrij":"صحيح: رواه الترمذي (١٠٨٧)، والنسائي (٣٢٣٥)، وابن ماجه (١٨٦٦)، وأحمد (١٨١٣٧)، واللفظ له.","grade":"صحيح","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1087), al-Nasa’i (3235), Ibn Majah (1866), and Ahmad (18137). The wording is that of Ahmad.","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Al-Mughirah ibn Shu‘bah said: I came to the Prophet ﷺ and mentioned to him a woman whom I intended to propose to. He said: “Go and look at her, for that is more likely to bring harmony between you.” He said: So I went to a woman from the Ansar and proposed to her through her parents, and I informed them of the statement of the Messenger of Allah ﷺ. It was as if they disliked that. Then the woman heard that while she was in her private chamber, and she said: If the Messenger of Allah ﷺ commanded you to look, then look; otherwise, I place you under a solemn appeal. It was as though she regarded the matter as weighty for him. He said: So I looked at her and married her, and he mentioned her good compatibility."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1087},{"key":"nasai","label":"النسائي","number":3235},{"key":"ibnmajah","label":"ابن ماجه","number":1866},{"key":"ahmad","label":"مسند الإمام أحمد","number":18137,"n":18137}]},{"num":6282,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله الأنصاري قال: سمعت رسول الله ﷺ يقول: (( إذا خطب أحدكم المرأة، فقدر أن يرى منها بعض ما يدعوه إليها فليفعل ))."],"takhrij":"حسن: رواه الإمام أحمد (١٤٨٦٩).","grade":"حسن","chapter_ar":"باب النظر إلى المخطوبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (14869).","chapter_en":"Chapter on looking at the woman one intends to marry","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah al-Ansari said: I heard the Messenger of Allah ﷺ say: “When one of you proposes to a woman, if he is able to see something of her that will encourage him to marry her, then let him do so.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":14869},{"key":"ahmad","label":"مسند الإمام أحمد","number":14869,"n":14869}]},{"num":6283,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال النبي ﷺ: (( إن الله كتب على ابن آدم حظه من الزنا، أدرك ذلك لا محالة، فزنا العين النظر، وزنا اللسان المنطق، والنفس تمني وتشتهي، والفرج يصدق ذلك كله ويكذبه ))."],"takhrij":"متفق عليه: رواه البخاري (٦٢٤٣) ومسلم (٢٦٥٧).","grade":"متفق عليه","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6243) and Muslim (2657).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “Allah has decreed for the son of Adam his share of adultery, and he will inevitably reach it. The adultery of the eye is looking, the adultery of the tongue is speaking, and the soul wishes and desires, while the private part confirms all of that or denies it.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿ قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَٰلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ ﴾ [النور: ٣٠]"],"en":["Allah Most High said: “Tell the believing men to lower their gaze and guard their private parts. That is purer for them. Indeed Allah is fully aware of what they do.” [Al-Nur: 30]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6243},{"key":"muslim","label":"مسلم","number":2657}]},{"num":6284,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: (( كُتب على ابن آدم نصيبُه من الزنا، مدرك ذلك لا محالة، فالعينان زناهما النظر، والأذنان زناهما الاستماع، واللسان زناه الكلام، واليد زناها البطش، والرجل زناها الخطا، والقلب يهوى ويتمنى، ويصدق ذلك الفرج ويكذبه ))."],"takhrij":"صحيح: رواه مسلم (٢١:٢٦٥٧).","grade":"صحيح","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (21:2657).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “The share of adultery decreed for the son of Adam will inevitably reach him. The adultery of the eyes is looking, the adultery of the ears is listening, the adultery of the tongue is speech, the adultery of the hand is grasping, the adultery of the foot is walking, and the heart desires and wishes, while the private part confirms that or denies it.”"]},"buhuth":{"ar":["ورواه أبو داود (٢١٥٢) من وجه آخر به وزاد فيه: (( والفم يزني فزناه القبل ))."],"en":["Abu Dawud (2152) narrated it through another route and added: “And the mouth commits adultery, and its adultery is kissing.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21}]},{"num":6285,"demo":false,"sanad":"","matn":["عن جرير بن عبد الله قال: سألتُ رسول الله ﷺ عن نَظَرِ الفُجَاءةِ فأمرني أن أَصْرِف بصري."],"takhrij":"صحيح: رواه مسلم (٢١٥٩).","grade":"صحيح","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2159).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Jarir ibn ‘Abd Allah said: I asked the Messenger of Allah ﷺ about the accidental glance, and he ordered me to turn my gaze away."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2159}]},{"num":6286,"demo":false,"sanad":"","matn":["عن ابن بريدة، عن أبيه قال: قال رسول الله ﷺ: (( يا علي، لا تُتبع النظرةَ النظرة، فإن لك الأولى، وليست لك الآخرة ))."],"takhrij":"حسن: رواه أبو داود (٢١٤٨)، والترمذي (٢٧٧٧) وحسّنه، والحاكم (٢٧٨٨)، وأحمد (٢٢٩٧٤).","grade":"حسن","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2148), al-Tirmidhi (2777), who graded it Hasan, al-Hakim (2788), and Ahmad (22974).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ibn Buraydah narrated from his father that the Messenger of Allah ﷺ said: “O ‘Ali, do not follow one look with another, for you are allowed the first, but not the second.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2148},{"key":"tirmidhi","label":"الترمذي","number":2777},{"key":"hakim","label":"المستدرك على الصحيحين","number":2788,"n":2774},{"key":"ahmad","label":"مسند الإمام أحمد","number":22974,"n":22974}]},{"num":6287,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: قال لي رسول الله ﷺ: (( لا تُتبع النظرَ النظرَ، فإن الأولى لك، وليست لك الآخرة ))."],"takhrij":"حسن: رواه أحمد (١٣٦٩)، والبزار - كشف الأستار (٩٠٧)، والدارمي (٢٧٥١)، والطحاوي في مشكله (١٨٦٥).","grade":"حسن","chapter_ar":"باب في غض البصر وتحريم النظر إلى الأجنبية بغير قصد الخطبة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (1369), al-Bazzar in Kashf al-Astar (907), al-Darimi (2751), and al-Tahawi in Mushkil al-Athar (1865).","chapter_en":"Chapter on lowering the gaze and the prohibition of looking at a non-related woman without the intention of betrothal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ said to me: “Do not follow one look with another, for the first is for you, but the second is not for you.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":907},{"key":"darimi","label":"الدارمي","number":2751},{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":1865},{"key":"ahmad","label":"مسند الإمام أحمد","number":1369,"n":1369}]},{"num":6288,"demo":false,"sanad":"","matn":["عن أبي برزة الأسلمي: أن جُليبيباً كان امرأً يدخل على النساء ويلاعبهن، فقلت لامرأتي: لا تدخلنَّ عليكم جُليبيبٌ، فإنه إن دخل عليكم لأفعلنَّ ولأفعلنَّ. قال: وكانت الأنصار إذا كان لأحدهم أيم، لم يزوّجها حتى يعلم هل للنبي ﷺ فيها حاجة أم لا. فقال رسول الله ﷺ لرجل من الأنصار: (( زوّجني ابنتك )). فقال: نعم وكرامةً يا رسول الله، ونِعْمَ عيني. قال: (( إني لست أريدها لنفسي )). قال: فلمن يا رسول الله؟ قال: (( لجُليبيب )).","قال: فقال: يا رسول الله، أشاور أمّها. فأتى أمّها، فقال: رسول الله ﷺ يخطب ابنتك. فقالت: نعم ونعمة عيني. فقال: إنه ليس يخطبها لنفسه، إنما خطبها لجليبيب. فقالت: أجُليبيبٌ إنيهِ؟ أجُليبيبٌ إنيهِ؟ أجُليبيبٌ إنيهِ؟ لا لعمرُ الله، لا نزوّجه. فلما أراد أن يقوم ليأتي رسول الله ﷺ فيخبره بما قالت أمُّها، قالت الجارية: من خطبني إليكم؟ فأخبرتها أمُّها. فقالت: أتردّون على رسول الله ﷺ أمره؟ ادفعوني، فإنه لم يضيّعني. فانطلق أبوها إلى رسول الله ﷺ فأخبره، فقال: (( شأنك بها )). فزوّجها جليبيباً."],"takhrij":"صحيح: رواه الإمام أحمد (١٩٧٨٤).","grade":"صحيح","chapter_ar":"باب للإمام أن يخطب إلى من أحب على من أحب من رعيته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (19784).","chapter_en":"Chapter on the leader proposing on behalf of whomever he wishes among his subjects","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الخِطبة","group_en":"Collection of narrations regarding betrothal","part_no":24,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abu Barzah al-Aslami reported that Julaybib was a man who used to enter among the women and joke with them, so I said to my wife: Do not let Julaybib enter upon you, for if he enters, I will certainly do such-and-such. He said: The Ansar, if one of them had an unmarried woman, would not marry her until they knew whether the Prophet ﷺ had any interest in her or not. So the Messenger of Allah ﷺ said to a man from the Ansar: “Marry your daughter to me.” He said: Yes, with honor, O Messenger of Allah, and gladly. He said: “I do not want her for myself.” He said: Then for whom, O Messenger of Allah? He said: “For Julaybib.”","He said: So he said: O Messenger of Allah, let me consult her mother. He went to her mother and said: The Messenger of Allah ﷺ is proposing for your daughter. She said: Yes, gladly and with full welcome. He said: He is not proposing for himself; he is proposing for Julaybib. She said: Julaybib? Him? Julaybib? Him? Julaybib? Him? No, by Allah, we will not marry her to him. When the father was about to leave to go to the Messenger of Allah ﷺ and tell him what her mother had said, the girl said: Who has proposed for me through you? Her mother told her. She said: Are you rejecting the command of the Messenger of Allah ﷺ? Give me in marriage, for he will not neglect me. So her father went to the Messenger of Allah ﷺ and informed him, and he said: “The matter is yours with her.” So he married her to Julaybib."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":19784},{"key":"ahmad","label":"مسند الإمام أحمد","number":19784,"n":19784}]},{"num":6289,"demo":false,"sanad":"","matn":["عن عائشة قالت:","جلس إحدى عشرة امرأة، فتعاهدن وتعاقدن أن لا يكتمن من أخبار أزواجهن شيئًا.","قالت الأولى: زوجي لحم جمل غث، على رأس جبل، لا سهل فيرتقى، ولا سمين فينتقل.","قالت الثانية: زوجي لا أبث خبره، إني أخاف أن لا أذره؛ إن أذكره أذكر عجره وبجره.","قالت الثالثة: زوجي العشنق، إن أنطق أطلق، وإن أسكت أعلق.","قالت الرابعة: زوجي كليل تهامة، لا حر ولا قر، ولا مخافة ولا سآمة.","قالت الخامسة: زوجي إن دخل فهد، وإن خرج أسد، ولا يسأل عما عهد.","قالت السادسة: زوجي إن أكل لف، وإن شرب اشتف، وإن اضطجع التف، ولا يولج الكف ليعلم البث.","قالت السابعة: زوجي غياياء - أو عياياء - طباقاء، كل داء له داء، شجك أو فلك أو جمع كلًّا لك.","قالت الثامنة: زوجي المس مس أرنب، والريح ريح زرنب.","قالت التاسعة: زوجي رفيع العماد، طويل النجاد، عظيم الرماد، قريب البيت من الناد.","قالت العاشرة: زوجي مالك، وما مالك؟ مالك خير من ذلك؛ له إبل كثيرات المبارك، قليلات المسارح، وإذا سمعن صوت المزهر أيقن أنهن هوالك.","قالت الحادية عشرة: زوجي أبو زرع، فما أبو زرع؟ أناس من حلي أذني، وملأ من شحم عضدي، وبجحني فبجحت إلي نفسي. وجدني في أهل غنيمة بشق، فجعلني في أهل صهيل وأطيط، ودائس ومنق. فعنده أقول فلا أقبح، وأرقد فأتصبح، وأشرب فأتقنح.","أم أبي زرع، فما أم أبي زرع؟ عكومها رداح، وبيتها فساح.","ابن أبي زرع، فما ابن أبي زرع؟ مضجعه كمسل شطبة، ويشبعه ذراع الجفرة.","بنت أبي زرع، فما بنت أبي زرع؟ طوع أبيها، وطوع أمها، وملء كسائها، وغيظ جارتها.","جارية أبي زرع، فما جارية أبي زرع؟ لا تبث حديثنا تبثيثًا، ولا تنقث ميرتنا تنقيثًا، ولا تملأ بيتنا تعشيشًا.","قالت: خرج أبو زرع والأوطاب تمخض، فلقي امرأة معها ولدان لها كالفهدين، يلعبان من تحت خصرها برمانتين، فطلقني ونكحها.","فنكحت بعده رجلًا سريًّا، ركب شريًّا، وأخذ خطيًّا، وأراح علي نعمًا ثريًّا، وأعطاني من كل رائحة زوجًا، وقال: كلي أم زرع، وميري أهلك.","قالت: فلو جمعت كل شيء أعطانيه، ما بلغ أصغر آنية أبي زرع.","قالت عائشة: قال رسول الله ﷺ:","«كُنْتُ لَكِ كَأَبِي زَرْعٍ لِأُمِّ زَرْعٍ»."],"takhrij":"متفق عليه: رواه البخاري (٥١٨٩)، ومسلم (٢٤٤٨).","grade":"متفق عليه","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5189) and Muslim (2448).","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿĀʾishah reported:","Eleven women sat together and pledged to one another that they would conceal nothing concerning their husbands.","The first said: “My husband is like the meat of a lean camel on top of a mountain: the mountain is not easy to climb, nor is the meat fat enough to be worth carrying away.”","The second said: “I will not disclose the story of my husband, for I fear that if I begin, I will not finish. If I mention him, I will have to mention all his outward and inward faults.”","The third said: “My husband is tall and foolish. If I speak, I will be divorced; if I remain silent, I will be left suspended.”","The fourth said: “My husband is like the night of Tihāmah: neither hot nor cold, and there is neither fear nor weariness with him.”","The fifth said: “When my husband enters, he is like a leopard; when he goes out, he is like a lion, and he does not ask about what he has left behind.”","The sixth said: “When my husband eats, he devours everything; when he drinks, he drains it all; when he lies down, he wraps himself up, and he does not extend his hand to discover what troubles me.”","The seventh said: “My husband is foolish, helpless, and stupid. Every kind of defect is found in him. He may wound you, break you, or combine both against you.”","The eighth said: “The touch of my husband is like the touch of a rabbit, and his fragrance is like the fragrance of sweet basil.”","The ninth said: “My husband is lofty in his pillars, long in his sword-belt, great in his ashes, and his house is near the gathering place.”","The tenth said: “My husband is Mālik. And what is Mālik? Mālik is better than all that. He has many camels that remain near the house and few that are sent out to pasture. Whenever they hear the sound of the lute, they know that they are about to be slaughtered for guests.”","The eleventh said: “My husband is Abū Zarʿ. And what is Abū Zarʿ? He filled my ears with jewelry and filled my upper arms with flesh. He made me rejoice until I became pleased with myself. He found me among a poor family possessing only a few sheep in a narrow place, then brought me into a household of horses, camels, grain-threshing, and grain-cleaning. With him I speak and am not rebuked; I sleep until late in the morning; and I drink until I am completely satisfied.","The mother of Abū Zarʿ—and what is the mother of Abū Zarʿ? Her storage bags are large and full, and her house is spacious.","The son of Abū Zarʿ—and what is the son of Abū Zarʿ? His sleeping place is as slender as a drawn blade, and the foreleg of a young goat is enough to satisfy him.","The daughter of Abū Zarʿ—and what is the daughter of Abū Zarʿ? She is obedient to her father and obedient to her mother, fills out her garment, and causes her co-wife to feel jealous.","The servant-girl of Abū Zarʿ—and what is the servant-girl of Abū Zarʿ? She does not spread our secrets, does not waste our provisions, and does not fill our house with refuse.","Abū Zarʿ went out while the milk-skins were being churned and met a woman who had two children like little leopards, playing beneath her waist with two pomegranates. He divorced me and married her.","After him I married a noble man who rode a fine horse, carried an Indian spear, brought me abundant livestock, and gave me a pair of every kind. He said: ‘Eat, O Umm Zarʿ, and give provisions to your family.’","But even if I gathered together everything he gave me, it would not equal the smallest vessel of Abū Zarʿ.”","ʿĀʾishah said that the Messenger of Allah ﷺ said to her:","“I am to you as Abū Zarʿ was to Umm Zarʿ.”"]},"intro":{"ar":["قال تعالى: (وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ) [سورة النساء: ١٩]"],"en":["Allah Most High said: “And live with them in kindness.” [Surat al-Nisa’: 19]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5189},{"key":"muslim","label":"مسلم","number":2448}]},{"num":6290,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: استأذن أبو بكر على النبي ﷺ، فسمع صوت عائشة عاليا، فلما دخل تناولها ليلطمها، وقال: ألا أراك ترفعين صوتك على رسول الله ﷺ، فجعل النبي ﷺ يحجزه، وخرج أبو بكر مغضبا، فقال النبي ﷺ حين خرج أبو بكر: (( كيف رأيتني أنقذتك من الرجل؟ )) قال: فمكث أبو بكر أياما، ثم استأذن على رسول الله ﷺ فوجدهما قد اصطلحا، فقال لهما: أدخلاني في سلمكما كما أدخلتماني في حربكما. فقال النبي ﷺ: (( قد فعلنا، قد فعلنا ))."],"takhrij":"صحيح: رواه أبو داود (٤٩٩٩) وأحمد (١٨٣٩٤)، واللفظ لأبي داود. ولم يذكر أحمد قوله: (( قد فعلنا، قد فعلنا )).","grade":"صحيح","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4999) and Ahmad (18394). The wording is that of Abu Dawud. Ahmad did not mention the words, “We have done so, we have done so.”","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Al-Nu‘man ibn Bashir said: Abu Bakr asked permission to enter upon the Prophet ﷺ and heard the voice of ‘A’ishah raised. When he entered, he moved toward her to slap her and said: Do I see you raising your voice over the Messenger of Allah ﷺ? The Prophet ﷺ began restraining him, and Abu Bakr left angry. When Abu Bakr left, the Prophet ﷺ said: “How did you find that I rescued you from the man?” He said: Abu Bakr stayed away for some days, then asked permission to enter upon the Messenger of Allah ﷺ and found that the two had reconciled. So he said to them: Let me enter into your peace just as you made me enter into your conflict. The Prophet ﷺ said: “We have done so, we have done so.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4999},{"key":"ahmad","label":"مسند الإمام أحمد","number":18394,"n":18394}]},{"num":6291,"demo":false,"sanad":"","matn":["عن ابن عباس قال: جاء رجل إلى النبي ﷺ فقال: إن امرأتي لا تمنع يد لامس. فقال: (( غَرِّبْها إن شئت )). قال: إني أخاف أن تتبعها نفسي، قال: (( استمتع بها ))."],"takhrij":"حسن: رواه أبو داود (٢٠٤٩) والنسائي (٣٤٦٤) والبيهقي (٧/١٥٤).","grade":"حسن","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2049), al-Nasa’i (3464), and al-Bayhaqi (7/154).","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Abbas said: A man came to the Prophet ﷺ and said: My wife does not refuse the hand of one who touches. He said: “Divorce her if you wish.” The man said: I fear that my soul will still follow after her. He said: “Then continue to live with her.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2049},{"key":"nasai","label":"النسائي","number":3464},{"key":"البیہقی","label":"البيهقي","number":7}]},{"num":6292,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن رجلا أتى رسول الله ﷺ فقال: يا رسول الله ﷺ إن لي امرأة وهي لا تدفع يد لامس. قال: (( طلِّقها )). قال: إني أحبها وهي جميلة. قال: (( فاستمتع بها ))."],"takhrij":"حسن: رواه البيهقي في السنن الكبرى (٧/١٥٥-١٥٤).","grade":"حسن","chapter_ar":"باب حسن المعاشرة مع الأهل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi in al-Sunan al-Kubra (7/154–155).","chapter_en":"Chapter on good companionship with one’s family","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that a man came to the Messenger of Allah ﷺ and said: O Messenger of Allah, I have a wife and she does not push away the hand of one who touches. He said: “Divorce her.” The man said: I love her and she is beautiful. He said: “Then continue to live with her.”"]},"buhuth":{"ar":["وقوله: (( لا تمنع يدَ لامس )) معناه أن الرجل وقع في قلبه ريبة منها، وفي الوقت نفسه لا يستطيع مفارقتها، فأمر النبي ﷺ بالبقاء معها، والصبر عليها، لعلها يتحسن حالها.","وقول النبي ﷺ: (( استمتع بها )) إشارة إلى كثرة الجماع منها لكسر شهوتها. والله تعالى أعلم."],"en":["His statement, “she does not prevent the hand of one who touches,” means that suspicion had entered the man’s heart regarding her, while at the same time he could not bear to part from her. So the Prophet ﷺ instructed him to remain with her and be patient, in hopes that her condition might improve.","The Prophet’s ﷺ statement, “continue to live with her,” is an indication of increasing intimacy with her in order to restrain her desire. And Allah Most High knows best."]}},"tuhfa":{},"refs":[{"key":"البیہقی/السنن_الکبری","label":"البيهقي في السنن الكبرى","number":7},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":13873,"n":14001}]},{"num":6293,"demo":false,"sanad":"","matn":["عن أنس قال: قال رسول الله ﷺ: (( حُبِّبَ إليّ النساءُ، والطِّيبُ، وجُعِلَ قرةُ عيني في الصلاة ))."],"takhrij":"حسن: رواه النسائي (٣٩٣٩) وأحمد (١٣٠٥٧) والبيهقي (٧/٧٨).","grade":"حسن","chapter_ar":"باب حب النبي ﷺ للنساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3939), Ahmad (13057), and al-Bayhaqi (7/78).","chapter_en":"Chapter on the Prophet’s love for women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “Women and perfume have been made beloved to me, and the comfort of my eye has been placed in prayer.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3939},{"key":"البیہقی","label":"البيهقي","number":7},{"key":"ahmad","label":"مسند الإمام أحمد","number":13057,"n":13057}]},{"num":6294,"demo":false,"sanad":"","matn":["عن عائشة قالت: كنت ألعب بالبنات عند النبي ﷺ، وكان لي صواحب يلعبْنَ معي. فكان رسول الله ﷺ إذا دخل يتقَمّعْن منه، فيُسَرِّبُهُنَّ إليَّ فيلعبْن معي."],"takhrij":"متفق عليه: رواه البخاري (٦١٣٠) ومسلم (٢٤٤٠).","grade":"متفق عليه","chapter_ar":"باب انبساط الرجل إلى زوجته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6130) and Muslim (2440).","chapter_en":"Chapter on a man being open and easy with his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: I used to play with dolls in the presence of the Prophet ﷺ, and I had girl-friends who played with me. When the Messenger of Allah ﷺ entered, they would hide from him, and he would send them to me so they could play with me."]},"buhuth":{"ar":["وقولها: (( كنت ألعب بالبنات )) فيه جواز اللعب بالدُّمية.","وقولها: (( يتقَمّعْن )) أي يتغيَّبْن حياءً منه وهيبةً.","وقولها: (( يسربهنّ )) أي يرسلهن ويدفعهن إليّ."],"en":["Her statement, “I used to play with dolls,” shows the permissibility of playing with dolls.","Her statement, “they would hide,” means they would withdraw out of modesty and awe toward him.","Her statement, “he would send them,” means he would send them over and let them come to me."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6130},{"key":"muslim","label":"مسلم","number":2440}]},{"num":6295,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال:","«مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ، فَإِذَا شَهِدَ أَمْرًا فَلْيَتَكَلَّمْ بِخَيْرٍ أَوْ لِيَسْكُتْ، وَاسْتَوْصُوا بِالنِّسَاءِ، فَإِنَّ الْمَرْأَةَ خُلِقَتْ مِنْ ضِلَعٍ، وَإِنَّ أَعْوَجَ شَيْءٍ فِي الضِّلَعِ أَعْلَاهُ، إِنْ ذَهَبْتَ تُقِيمُهُ كَسَرْتَهُ، وَإِنْ تَرَكْتَهُ لَمْ يَزَلْ أَعْوَجَ، اسْتَوْصُوا بِالنِّسَاءِ خَيْرًا»."],"takhrij":"صحيح: رواه البخاري (٥١٨٥-٥١٨٦)، ومسلم (١٤٦٨/٦٠)، واللفظ لمسلم.","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5185–5186) and Muslim (1468/60). This is Muslim’s wording.","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said:","“Whoever believes in Allah and the Last Day, when he is present at a matter, let him speak good or remain silent. Treat women well, for woman was created from a rib, and the most crooked part of the rib is its upper part. If you try to straighten it, you will break it; and if you leave it, it will remain crooked. So treat women well.”"]},"buhuth":{"ar":["ورواه مسلم من وجه آخر بلفظ:","«إِنَّ الْمَرْأَةَ كَالضِّلَعِ، إِذَا ذَهَبْتَ تُقِيمُهَا كَسَرْتَهَا، وَإِنْ تَرَكْتَهَا اسْتَمْتَعْتَ بِهَا وَفِيهَا عِوَجٌ»."],"en":["Muslim also narrated through another route:","“Woman is like a rib. If you try to straighten her, you will break her; and if you leave her, you may enjoy life with her while crookedness remains in her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5185},{"key":"muslim","label":"مسلم","number":1468}]},{"num":6296,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( إن المرأة خُلقت من ضلع، لن تستقيم لك على طريقة، فإن استمتعت بها استمتعت بها وبها عوج، وإن ذهبت تقيمها كَسَرتها، وكسرها طلاقها ))."],"takhrij":"صحيح: رواه مسلم (٦١:١٤٦٨) والبخاري (٥١٨٤).","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (61:1468) and al-Bukhari (5184).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Woman was created from a rib. She will never become completely straight for you upon one manner. If you enjoy life with her, you enjoy life with her while some crookedness remains in her. And if you try to straighten her, you will break her, and breaking her is divorcing her.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":61},{"key":"bukhari","label":"البخاري","number":5184}]},{"num":6297,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( لا يَفْرَك مؤمن مؤمنةً، إن كره منها خُلُقاً رضي منها آخر أو قال: غيره ))."],"takhrij":"صحيح: رواه مسلم (١٤٦٩).","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1469).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “A believing man should not hate a believing woman. If he dislikes one trait in her, he will be pleased with another,” or he said, “with a different one.”"]},"buhuth":{"ar":["قوله: (( لا يفرك )) : أي لا يبغض، يقال: فرِكه يفرَكه إذا أبغضه."],"en":["His statement, “should not hate,” means should not loathe or detest. It is said in Arabic: he hated him, meaning he came to dislike him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1469}]},{"num":6298,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن رسول الله ﷺ قال: (( ولولا بنو إسرائيل لم يخبث الطعام، ولم يخنز اللّحم، ولو لا حواء لم تَخُنْ أنثى زوجَها أبدَ الدهر))."],"takhrij":"متفق عليه: رواه البخاري (٣٣٣٠)، ومسلم (٦٣:١٤٧٠) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3330) and Muslim (63:1470), with this wording from Muslim.","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Were it not for the Children of Israel, food would not spoil, and meat would not rot. And were it not for Hawwa’, no woman would ever betray her husband for all time.”"]},"buhuth":{"ar":["وقوله: (( ولم يخنز اللحم )) أي لم ينتن ويتغيّر."],"en":["His statement, “and meat would not rot,” means it would not become foul-smelling and change."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3330},{"key":"muslim","label":"مسلم","number":63}]},{"num":6299,"demo":false,"sanad":"","matn":["عن سمرة بن جندب قال: قال رسول الله ﷺ: (( إن المرأة خُلقت من ضلع، فإن أقمتها كسرتها، فدارها تعش بها))."],"takhrij":"صحيح: رواه البزار - كشف الأستار (١٤٧٦) والطبراني (٦٩٩٢) وابن حبان (٤١٧٨) والحاكم (١٧٤/٤).","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar in Kashf al-Astar (1476), al-Tabarani (6992), Ibn Hibban (4178), and al-Hakim (4/174).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Samurah ibn Jundub said: the Messenger of Allah ﷺ said: “Woman was created from a rib. If you try to straighten her, you will break her, so treat her gently and you will live with her.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1476},{"key":"الطبرانی","label":"الطبراني","number":6992},{"key":"hakim","label":"الحاكم","number":174},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1620,"n":1617}]},{"num":6300,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال في حديث حجة الوداع:","حتى إذا زاغت الشمس أمر بالقصواء، فرحلت له، فأتى بطن الوادي، فخطب الناس وقال:","«إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ حَرَامٌ عَلَيْكُمْ كَحُرْمَةِ يَوْمِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا.","أَلَا كُلُّ شَيْءٍ مِنْ أَمْرِ الْجَاهِلِيَّةِ تَحْتَ قَدَمَيَّ مَوْضُوعٌ، وَدِمَاءُ الْجَاهِلِيَّةِ مَوْضُوعَةٌ، وَإِنَّ أَوَّلَ دَمٍ أَضَعُ مِنْ دِمَائِنَا دَمُ ابْنِ رَبِيعَةَ بْنِ الْحَارِثِ - كَانَ يُسْتَرْضَعُ فِي بَنِي سَعْدٍ، فَقَتَلَتْهُ هُذَيْلٌ - وَرِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ، وَأَوَّلُ رِبًا أَضَعُ رِبَانَا، رِبَا عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، فَإِنَّهُ مَوْضُوعٌ كُلُّهُ.","فَاتَّقُوا اللَّهَ فِي النِّسَاءِ، فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانِ اللَّهِ، وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ، وَلَكُمْ عَلَيْهِنَّ أَنْ لَا يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ، فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ، وَلَهُنَّ عَلَيْكُمْ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ…»"],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported in the hadith of the Farewell Pilgrimage:","When the sun had passed its zenith, the Prophet ﷺ ordered that al-Qaṣwāʾ be saddled for him. He came to the middle of the valley and addressed the people, saying:","“Your blood and your wealth are sacred to one another, just as this day of yours is sacred, in this month of yours, in this land of yours.","Everything from the affairs of the pre-Islamic period is placed beneath my feet and abolished. The blood claims of the pre-Islamic period are abolished, and the first blood claim of ours that I abolish is that of the son of Rabīʿah ibn al-Ḥārith—he had been sent to be nursed among Banū Saʿd and was killed by Hudhayl.","The usury of the pre-Islamic period is abolished, and the first usury of ours that I abolish is that of al-ʿAbbās ibn ʿAbd al-Muṭṭalib. All of it is abolished.","Fear Allah regarding women, for you have taken them under the trust of Allah and made marital relations with them lawful by the word of Allah.","Your right over them is that they do not allow onto your bedding anyone whom you dislike. If they do so, then strike them in a manner that is not severe. Their right over you is that you provide them with food and clothing according to what is reasonable…”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":6301,"demo":false,"sanad":"","matn":["عن عائشة قالت: كنت أشرب وأنا حائض، ثم أناوله النبي ﷺ فيضع فاه موضع فيَّ، فيشرب وأتعرق العَرْق وأنا حائض، ثم أناوله النبي ﷺ فيضع فاه موضع فيَّ."],"takhrij":"صحيح: رواه مسلم (٣٠٠).","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (300).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: I would drink while menstruating, then hand it to the Prophet ﷺ, and he would place his mouth where mine had been and drink. And I would gnaw meat from a bone while menstruating, then hand it to the Prophet ﷺ, and he would place his mouth where mine had been."]},"buhuth":{"ar":["والعَرْق - بسكون الراء - إذا أخذ عنه معظم اللحم وجمعه عُراق. وقيل: هو العظم الذي عليه بقية من لحم. وفيه مداراة النبي ﷺ من مؤاكلة أهله وشربه."],"en":["The word ‘irq with a silent ra’ means a bone from which most of the meat has been taken, and its plural is ‘iraq. It was also said that it means a bone that still has some meat on it. In this is the Prophet’s ﷺ gentle companionship in eating and drinking with his family."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":300}]},{"num":6302,"demo":false,"sanad":"","matn":["عن عائشة قالت: سابقني النبي ﷺ فسبقته، فلبثنا حتى إذا أرهقني اللحم سابقني فسبقني. فقال النبي ﷺ: (( هذه بتلك))."],"takhrij":"صحيح: رواه أبو داود (٢٥٧٨) وابن ماجه (١٩٧٩) وصحّحه ابن حبان (٤٦٩١).","grade":"صحيح","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2578), Ibn Majah (1979), and authenticated by Ibn Hibban (4691).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ raced me, and I beat him. Then time passed until I had put on weight, and he raced me and beat me. So the Prophet ﷺ said: “This is for that.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2578},{"key":"ibnmajah","label":"ابن ماجه","number":1979},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4691},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5495,"n":5491}]},{"num":6303,"demo":false,"sanad":"","matn":["عن عائشة قالت: خرجت مع النبي ﷺ في بعض أسفاره وأنا جارية لم أحمل اللحم ولم أبدُنْ، فقال للناس: (( تقدموا )) فتقدموا. ثم قال لي: (( تعالي حتى أسابقك )) فسابقته فسبقته، فسكت عني حتى إذا حملت اللحم، وبدنت، ونسيت، خرجت معه في بعض أسفاره، فقال للناس: (( تقدموا )) فتقدموا ثم قال: (( تعالي حتى أسابقك )) فسابقته فسبقني، فجعل يضحك وهو يقول: (( هذه بتلك ))."],"takhrij":"حسن: رواه أحمد (٢٦٢٧٧).","grade":"حسن","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (26277).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: I went out with the Prophet ﷺ on one of his journeys while I was still a young girl, not carrying flesh and not heavy in body. He said to the people: “Go ahead,” so they went ahead. Then he said to me: “Come, so I may race you.” So I raced him and beat him. He said nothing to me about it until later, when I had put on flesh, gained weight, and forgotten about it. Then I went out with him on another journey, and he said to the people: “Go ahead,” so they went ahead. Then he said: “Come, so I may race you.” So I raced him and he beat me, and he began laughing, saying: “This is for that.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":26277,"n":26277}]},{"num":6304,"demo":false,"sanad":"","matn":["عن عائشة قالت: أتيت رسول الله ﷺ بخزيرة قد طبختُها له، فقلت لسودة - والنبي ﷺ بيني وبينها - كلي. فأبت. فقلت: لتأكلنَّ أو لألطخنّ وجهك. فأبت فوضعت يدي في الخزيرة فطليت وجهها. فضحك النبي ﷺ فوضع بيده لها. وقال لها: (( ألطخي وجهها )) فضحك النبي ﷺ لها. فمر عمر فقال: يا عبد الله يا عبد الله! فظن أنه سيدخل. فقال: (( قوما فاغسلا وجوهكما )). قالت عائشة: فما زلتُ أهاب عمر لهيبة رسول الله ﷺ."],"takhrij":"حسن: رواه أبو يعلى (٤٤٧٦) وأبو بكر الشافعي في الغيلانيات (١١٧).","grade":"حسن","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Ya‘la (4476) and Abu Bakr al-Shafi‘i in al-Ghaylaniyyat (117).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: I brought the Messenger of Allah ﷺ some khazirah that I had cooked for him, and I said to Sawdah—while the Prophet ﷺ was between me and her—“Eat.” She refused. I said: “Either you eat, or I will smear your face.” She still refused, so I put my hand in the khazirah and smeared her face. The Prophet ﷺ laughed, then he put his hand for her and said to her: “Smear her face.” So the Prophet ﷺ laughed with her. Then ‘Umar passed by and said: “O servant of Allah, O servant of Allah!” and he thought that he would come in. So he said: “Get up and wash your faces.” ‘A’ishah said: I continued to stand in awe of ‘Umar because of the Messenger of Allah’s ﷺ awe of him."]},"buhuth":{"ar":["والخزيرة: طعام يطبخ من اللحم والدقيق نحو قرصان."],"en":["Khazirah is a food cooked from meat and flour, somewhat like a thick porridge."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":4476},{"key":"ابو_بکر_الشافعی/الغیلانیات","label":"أبو بكر الشافعي في الغيلانيات","number":117},{"key":"sh12520","label":"مسند أبي يعلى","number":4476,"n":4481}]},{"num":6305,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول الله ﷺ قال: (( إن أعظم الذنوب عند الله رجل تزوج امرأة فلما قضى حاجته طَلَّقَها، فذهب بمهرها، ورجل استعمل رجلا فذهب بأجرته، وآخر يقتل دابة عبثا ))."],"takhrij":"حسن: رواه الحاكم (٢٧٤٣).","grade":"حسن","chapter_ar":"باب الوصية بالنساء خيرا ومداراتهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (2743).","chapter_en":"Chapter on enjoining good treatment of women and dealing gently with them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ said:","“Among the gravest sins in the sight of Allah is that a man marries a woman, then, after satisfying his desire with her, divorces her and takes away her dowry; that a man employs another man and then deprives him of his wages; and that a person kills an animal for no purpose.”"]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":2743,"n":2729}]},{"num":6306,"demo":false,"sanad":"","matn":["عن أبي ذر، عن النبي ﷺ قال: «وفي بُضع أحدكم صدقة». قالوا: يا رسول الله! أيأتي أحدنا شهوته، ويكون له فيه أجر؟ فقال: «أرأيتم لو وضعها في الحرام أكان عليه وزر؟ فكذلك إذا وضعها في الحلال، كان له أجر»."],"takhrij":"صحيح: رواه مسلم في الزكاة (١٠٠٦).","grade":"صحيح","chapter_ar":"باب إن الله عزوجل جعل مواقعة أهله صدقة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in The Book of Zakāh (1006).","chapter_en":"Chapter that Allah, Mighty and Majestic, has made intimacy with one’s wife an act of charity","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Dharr reported that the Prophet ﷺ said:","“And in the sexual intimacy of each one of you there is an act of charity.”","They said, “O Messenger of Allah! Does one of us fulfill his desire and receive a reward for it?”","He ﷺ said:","“Tell me, if he were to satisfy it in what is unlawful, would he bear a sin for that? Likewise, when he satisfies it in what is lawful, he receives a reward.”"]}},"tuhfa":{},"refs":[{"key":"muslim/الزکاہ","label":"مسلم في الزكاة","number":1006}]},{"num":6307,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص قال: قال رسول الله ﷺ: (( يا عبد الله، ألم أخبر أنك تصوم النهار وتقوم الليل؟ )) قلت: بلى يا رسول الله، قال: (( فلا تفعل، صُمْ وأفطر، وقُمْ ونَمْ، فإنَّ لجسدك عليك حقاً، وإن لعينك عليك حقاً، وإنّ لزوجك عليك حقاً ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٩٩)، ومسلم (١١٥٩).","grade":"متفق عليه","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5199) and Muslim (1159).","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As said: The Messenger of Allah ﷺ said: “O ‘Abd Allah, have I not been told that you fast by day and stand in prayer by night?” I said: Yes, O Messenger of Allah. He said: “Do not do that. Fast and break your fast. Stand in prayer and sleep. For your body has a right over you, your eyes have a right over you, and your wife has a right over you.”"]},"intro":{"ar":["قال تعالى: (وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ) [البقرة: ٢٢٨]"],"en":["Allah Most High said: “And for them is the like of what is upon them, according to what is fair.” [al-Baqarah: 228]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5199},{"key":"muslim","label":"مسلم","number":1159}]},{"num":6308,"demo":false,"sanad":"","matn":["عن أبي جُحيفة قال: آخى النبي ﷺ بين سلمان وأبي الدرداء، فزار سلمان أبا الدرداء فرأى أم الدرداء متبذّلة، فقال لها: ما شأنك؟ قالت: أخوك أبو الدرداء ليس له حاجة في الدنيا. فجاء أبو الدرداء فصنع له طعاماً، فقال: كل فإني صائم. قال: ما أنا بآكل حتى تأكل. فأكل، فلما كان الليل هب أبو الدرداء يقوم، قال: نمْ، فنام، ثم ذهب يقوم فقال: نَمْ. فلما كان آخر الليل قال سلمان: قمْ الآن. فصلّيا فقال له سلمان: إن لربك عليك حقا، ولنفسك عليك حقا، ولأهلك عليك حقا، فأعط كل ذي حق حقه. فأتى النبي ﷺ فذكر ذلك له، فقال النبي ﷺ: (( صدق سلمان ))."],"takhrij":"صحيح: رواه البخاري (١٩٦٨).","grade":"صحيح","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (1968).","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abu Juhayfah said: The Prophet ﷺ made Salman and Abu al-Darda’ brothers. Salman visited Abu al-Darda’ and saw Umm al-Darda’ in worn clothing, so he said to her: What is the matter with you? She said: Your brother Abu al-Darda’ has no interest in worldly things. Then Abu al-Darda’ came and prepared food for him. Abu al-Darda’ said: Eat, for I am fasting. Salman said: I will not eat until you eat. So Abu al-Darda’ ate. When night came, Abu al-Darda’ got up to pray, but Salman said: Sleep. So he slept. Then he got up again, and Salman said: Sleep. Then at the end of the night Salman said: Now get up. So they prayed. Then Salman said to him: Your Lord has a right over you, your self has a right over you, and your family has a right over you, so give each possessor of a right his right. Then Abu al-Darda’ came to the Prophet ﷺ and mentioned that to him, and the Prophet ﷺ said: “Salman has spoken the truth.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1968}]},{"num":6309,"demo":false,"sanad":"","matn":["عن عبد الله بن زمعة، عن النبي ﷺ قال: (( لا يجلد أحدكم امرأته جلدَ العبد ثم يجامعها في آخر اليوم ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٠٤)، ومسلم (٢٨٥٥)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5204) and Muslim (2855), with the wording from al-Bukhari.","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["‘Abd Allah ibn Zam‘ah reported that the Prophet ﷺ said: “Let none of you flog his wife like the flogging of a slave and then have relations with her at the end of the day.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5204},{"key":"muslim","label":"مسلم","number":2855}]},{"num":6310,"demo":false,"sanad":"","matn":["عن حكيم بن معاوية القُشيري، عن أبيه قال: قلت: يا رسول الله! ما حق زوجة أحدنا عليه؟ قال: (( أن تُطعمها إذا طعمتَ، وتكسوها إذا اكتسيت، ولا تضرب الوجه، ولا تُقبِّح، ولا تهجر إلا في البيت ))."],"takhrij":"حسن: رواه أبو داود (٢١٤٢) وابن ماجه (١٨٥٠) وصححه ابن حبان (٤١٧٥) والحاكم (٢٧٦٤).","grade":"حسن","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2142), Ibn Majah (1850), authenticated by Ibn Hibban (4175), and al-Hakim (2764).","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Hakim ibn Mu‘awiyah al-Qushayri reported from his father that he said: O Messenger of Allah, what is the right of one of our wives over him? He said: “That you feed her when you eat, clothe her when you clothe yourself, do not strike the face, do not revile her, and do not forsake her except within the house.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2142},{"key":"ibnmajah","label":"ابن ماجه","number":1850},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4175},{"key":"hakim","label":"المستدرك على الصحيحين","number":2764,"n":2750}]},{"num":6311,"demo":false,"sanad":"","matn":["عن عائشة قالت: جاءت هند بنتُ عتبة إلى النبي ﷺ، فقالت: يا رسول الله، والله ما كان على ظهر الأرض أهل خباء أحبّ إلي من أن يذلهم الله من أهل خبائك، وما على ظهر الأرض أهل خباء أحب إلي من أن يعزهم الله من أهل خبائك، فقال النبي ﷺ: (( وأيضا والذي نفسي بيده )) ثم قالت: يا رسول الله، إن أبا سفيان رجلٌ ممسكٌ، فهل عليَّ حرجٌ أن أُنفِقَ على عياله من ماله بغير إذنه؟ فقال النبي ﷺ: (( لا حرجَ عليكِ أن تنفقي عليهم بالمعروف ))."],"takhrij":"متفق عليه: رواه البخاري (٣٨٢٥)، ومسلم (٨:١٧١٤) والسياق لمسلم، وسياق البخاري قريب منه.","grade":"متفق عليه","chapter_ar":"باب حق الزوجة على الزوج","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3825) and Muslim (8:1714), with this wording from Muslim. Al-Bukhari’s wording is close to it.","chapter_en":"Chapter on the wife’s right over the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["‘A’ishah said: Hind bint ‘Utbah came to the Prophet ﷺ and said: O Messenger of Allah, by Allah, there was no household on the face of the earth more beloved to me that Allah should disgrace than your household, and now there is no household on the face of the earth more beloved to me that Allah should honor than your household. The Prophet ﷺ said: “And also, by the One in whose hand is my soul.” Then she said: O Messenger of Allah, Abu Sufyan is a stingy man. Is there any sin upon me if I spend on his dependents from his wealth without his permission? The Prophet ﷺ said: “There is no sin upon you to spend on them in a fair manner.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3825},{"key":"muslim","label":"مسلم","number":8}]},{"num":6312,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( أكمل المؤمنين إيماناً أحسنهم خلقاً، خياركم خياركم لنسائهم ))."],"takhrij":"حسن: رواه الترمذي (١١٦٢)، وأبو داود (٤٦٨٢) وصحّحه ابن حبان (٤١٧٦) والحاكم (١).","grade":"حسن","chapter_ar":"باب ما جاء في قوله: خياركم خياركم لأهله","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1162), Abu Dawud (4682), authenticated by Ibn Hibban (4176), and al-Hakim (1).","chapter_en":"Chapter on the saying: the best of you are the best to their families","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The most complete of the believers in faith are those best in character, and the best of you are the best of you to their women.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1162},{"key":"abudawud","label":"أبو داود","number":4682},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4176},{"key":"hakim","label":"المستدرك على الصحيحين","number":1,"n":1}]},{"num":6313,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول الله ﷺ:","«خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ، وَأَنَا خَيْرُكُمْ لِأَهْلِي، وَإِذَا مَاتَ صَاحِبُكُمْ فَدَعُوهُ»."],"takhrij":"صحيح: رواه الترمذي (٣٨٩٥)، وصححه ابن حبان (٤١٧٧)، وأبو نعيم في الحلية (٧/١٣٨).","grade":"صحيح","chapter_ar":"باب ما جاء في قوله: خياركم خياركم لأهله","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3895), authenticated by Ibn Ḥibbān (4177), and narrated by Abū Nuʿaym in al-Ḥilyah (7/138).","chapter_en":"Chapter on the saying: the best of you are the best to their families","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah reported that the Messenger of Allah ﷺ said:","“The best of you are those who are best to their families, and I am the best of you to my family. When your companion dies, leave him alone.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3895},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4177},{"key":"ابو_نعیم/الحلیہ","label":"أبو نعيم في الحلية","number":7},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":635,"n":635}]},{"num":6314,"demo":false,"sanad":"","matn":["عن أم سلمة، أن النبي ﷺ حلف لا يدخل على بعض أهله شهراً، فلما مضى تسعة وعشرون يوماً غدا عليهنّ أو راح، فقيل له: يا نبي الله، حلفت أن لا تدخل عليهن شهراً؟ قال: (( إن الشهر يكون تسعة وعشرين يوماً ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٠٢)، ومسلم (٢٥:١٠٨٥).","grade":"متفق عليه","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5202) and Muslim (25:1085).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah reported that the Prophet ﷺ swore that he would not enter upon some of his wives for one month. Then when twenty-nine days had passed, he came to them in the morning or evening. It was said to him: O Prophet of Allah, you swore that you would not enter upon them for a month. He said: “The month may be twenty-nine days.”"]},"intro":{"ar":["قال الله تعالى: ﴿وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا﴾ [النساء: ٣٤]"],"en":["Allah Most High said: “As for those women whose disobedience you fear, admonish them, leave them in the beds, and strike them. But if they obey you, then seek no way against them. Indeed, Allah is Most High, Most Great.” [Surat al-Nisa’: 34]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5202},{"key":"muslim","label":"مسلم","number":25}]},{"num":6315,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( إذا دعا الرجل امرأته إلى فراشه، فأبت أن تجيءَ لعنتها الملائكة حتى تصبح )). وفي رواية: (( إذا باتت المرأة مهاجرةً فراش زوجها، لعنتها الملائكة حتى ترجع ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٩٣)، ومسلم (١٢:١٤٣٦)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5193) and Muslim (12:1436), with the wording from al-Bukhari.","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “If a man calls his wife to his bed and she refuses to come, the angels curse her until morning.” In another narration: “If a woman spends the night forsaking her husband’s bed, the angels curse her until she returns.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5193},{"key":"muslim","label":"مسلم","number":12}]},{"num":6316,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن رسول الله ﷺ قال: (( لا يحل للمرأة أن تصوم وزوجها شاهد إلا بإذنه، ولا تأذن في بيته إلا بإذنه، وما أنفقتْ من نفقةٍ عن غير أمره فإنه يؤدّى إليه شطرُه ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٩٥)، ومسلم (١٠٢٦).","grade":"متفق عليه","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5195) and Muslim (1026).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “It is not lawful for a woman to fast while her husband is present except with his permission, and she must not allow anyone into his house except with his permission. Whatever she spends without his instruction, half of its reward goes to him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5195},{"key":"muslim","label":"مسلم","number":1026}]},{"num":6317,"demo":false,"sanad":"","matn":["عن طلق بن علي قال: قال رسول الله ﷺ: (( إذا الرجل دعا زوجته لحاجته فلتأته، وإن كانت على التنور ))."],"takhrij":"حسن: رواه الترمذي (١١٦٠)، وحسّنه، وابن حبان في صحيحه (٤١٦٥)، والبيهقي (٢٩٤/٧).","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1160), who graded it Hasan, Ibn Hibban in his Sahih (4165), and al-Bayhaqi (7/294).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Talq ibn ‘Ali said that the Messenger of Allah ﷺ said: “If a man calls his wife for his need, she should come to him, even if she is at the oven.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1160},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4165},{"key":"البیہقی","label":"البيهقي","number":294}]},{"num":6318,"demo":false,"sanad":"","matn":["عن زيد بن أرقم أن رسول الله ﷺ قال: (( إذا دعا الرجل امرأته فلتجب، وإن كانت على ظهر قتب ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٤٧٢)، والطبراني في المعجم الأوسط (٧٤٢٩).","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1472) and al-Tabarani in al-Mu‘jam al-Awsat (7429).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Zayd ibn Arqam reported that the Messenger of Allah ﷺ said: “If a man calls his wife, she should respond, even if she is on the back of a saddle.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1472},{"key":"الطبرانی/المعجم_الاوسط","label":"الطبراني في المعجم الأوسط","number":7429},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1472,"n":1473}]},{"num":6319,"demo":false,"sanad":"","matn":["عن الحصين بن محصن أن عمة له أتت النبي ﷺ في حاجة، ففرغت من حاجتها. فقال لها النبي ﷺ: (( أذات زوج أنتِ؟ )) قالت: نعم. قال: (( كيف أنتِ له؟ )) قالت: ما آلوه إلا ما عجزتُ عنه. قال: (( فانظري أين أنتِ منه، فإنما هو جنتك ونارك ))."],"takhrij":"صحيح: رواه الإمام أحمد (١٩٠٠٣)، والطبراني في الكبير (١٨٣/٢٥)، والأوسط (٥٣٢)، والحاكم (١٨٩/٣).","grade":"صحيح","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (19003), al-Tabarani in al-Kabir (25/183), al-Awsat (532), and al-Hakim (3/189).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Al-Husayn ibn Mihsan reported that an aunt of his came to the Prophet ﷺ regarding a need. When she had finished her need, the Prophet ﷺ said to her: “Do you have a husband?” She said: Yes. He said: “How are you with him?” She said: I do not fail him except in what I am unable to do. He said: “Then look at where you stand with respect to him, for he is your Paradise and your Fire.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":19003},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":183},{"key":"الاوسط","label":"الأوسط","number":532},{"key":"hakim","label":"الحاكم","number":189},{"key":"ahmad","label":"مسند الإمام أحمد","number":19003,"n":19003}]},{"num":6320,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( لو كنتُ آمراً أحداً أن يسجد لأحدٍ، لأمرتُ المرأة أن تسجد لزوجها ))."],"takhrij":"حسن: رواه الترمذي (١١٥٩)، والبيهقي (٢٩١/٧)، وابن أبي الدنيا في العيال (٥٣٤).","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1159), al-Bayhaqi (7/291), and Ibn Abi al-Dunya in al-‘Iyal (534).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported from the Prophet ﷺ that he said: “If I were to command anyone to prostrate to anyone, I would have commanded the woman to prostrate to her husband.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1159},{"key":"البیہقی","label":"البيهقي","number":291},{"key":"ابن_ابی_الدنیا/العیال","label":"ابن أبي الدنيا في العيال","number":534},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14704,"n":14851}]},{"num":6321,"demo":false,"sanad":"","matn":["عن سراقة بن مالك قال: قال رسول الله ﷺ: (( لو كنت آمراً أحداً أن يسجد لأحدٍ لأمرت المرأة أن تسجد لزوجها ))."],"takhrij":"صحيح: رواه الطبراني في الكبير (١٥٢/٧)، وابن أبي الدنيا في العيال (٥٣٧).","grade":"صحيح","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Kabir (7/152) and Ibn Abi al-Dunya in al-‘Iyal (537).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Suraqah ibn Malik said that the Messenger of Allah ﷺ said: “If I were to command anyone to prostrate to anyone, I would have commanded the woman to prostrate to her husband.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":152},{"key":"ابن_ابی_الدنیا/العیال","label":"ابن أبي الدنيا في العيال","number":537}]},{"num":6322,"demo":false,"sanad":"","matn":["عن عائشة أن رسول الله ﷺ قال: (( لو أمرت أحداً أن يسجد لأحدٍ لأمرت المرأة أن تسجد لزوجها، ولو أن رجلاً أمر امرأته أن تنقل من جبل أحمر إلى جبل أسود، ومن جبل أسود إلى جبل أحمر لكان نَولُها أن تفعل ))."],"takhrij":"حسن: رواه ابن ماجه (١٨٥٢)، وابن أبي شيبة في مصنفه (٢٠٦/٤)، وأحمد (٢٤٤٧١).","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1852), Ibn Abi Shaybah in his Musannaf (4/206), and Ahmad (24471).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ said: “If I were to command anyone to prostrate to anyone, I would have commanded the woman to prostrate to her husband. And if a man were to command his wife to move from a red mountain to a black mountain, and from a black mountain to a red mountain, it would be her duty to do so.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1852},{"key":"ابن_ابی_شیبہ/مصنفہ","label":"ابن أبي شيبة في مصنفه","number":206},{"key":"ahmad","label":"مسند الإمام أحمد","number":24471,"n":24471}]},{"num":6323,"demo":false,"sanad":"","matn":["عن ابن عباس، عن رسول الله ﷺ قال: (( ثلاثة لا تُرفع صلاتُهم فوق رؤوسهم شبراً: رجلٌ أمَّ قوماً وهم له كارهون، وامرأةٌ باتتْ وزوجُها عليها ساخطٌ، وأخوانِ متصارمان ))."],"takhrij":"حسن: رواه ابن ماجه (٩٧١).","grade":"حسن","chapter_ar":"باب حق الزوج على الزوجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (971).","chapter_en":"The husband’s right over his wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Messenger of Allah ﷺ said: “Three persons’ prayer does not rise even a handspan above their heads: a man who leads people in prayer while they dislike him, a woman who spends the night while her husband is angry with her, and two brothers who are in estrangement with one another.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":971}]},{"num":6324,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص قال: قال رسول الله ﷺ: (( لا ينظر الله إلى امرأة لا تشكر لزوجها، وهي لا تستغني عنه ))."],"takhrij":"صحيح: رواه النسائي في الكبرى (٩٠٨٦).","grade":"صحيح","chapter_ar":"باب استحباب شكر المرأة لزوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i in al-Kubra (9086).","chapter_en":"The recommendation that a woman be grateful to her husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr ibn al-‘As said: the Messenger of Allah ﷺ said: “Allah does not look at a woman who is ungrateful to her husband while she cannot do without him.”"]}},"tuhfa":{},"refs":[{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":9086},{"key":"kubranasai","label":"السنن الكبرى للنسائي","number":9086,"n":9082}]},{"num":6325,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( خير نساء رَكِبْن الإبل صالحو نساء قريش، أحناه على ولدٍ في صغره، وأرعاه على زوج في ذات يده ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٨٢)، ومسلم (٢٠٠:٢٥٢٧)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5082) and Muslim (200:2527), with the wording from al-Bukhari.","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “The best women who rode camels are the righteous women of Quraysh: the most tender toward a child in his young age, and the most careful in safeguarding her husband’s property.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5082},{"key":"muslim","label":"مسلم","number":200}]},{"num":6326,"demo":false,"sanad":"","matn":["عن أسماء بنت أبي بكر قالت: تزوجني الزبير وماله في الأرض من مالٍ ولا مملوك، ولا شيء غير ناضح وغير فرسه، فكنت أعلف فرسه وأستقي الماء، وأخرز غربه وأَعجن، ولم أكن أحسن أخبز، وكان يخبز جارات لي من الأنصار، وكن نسوة صدق، وكنت أنقل النوى من أرض الزبير التي أقطعه رسول الله ﷺ على رأسي، وهي مني على ثلثي فرسخ، فجئت يوما والنوى على رأسي، فلقيت رسول الله ﷺ ومعه نفر من الأنصار، فدعاني ثم قال: (( إخ إخ ))، ليحملني خلفه، فاستحييت أن أسير مع الرجال، وذكرت الزبير وغيرته، وكان أغير الناس، فعرف رسول الله ﷺ أني قد استحييت فمضى، فجئت الزبير فقلت: لقيني رسول الله ﷺ وعلى رأسي النوى، ومعه نفر من أصحابه، فأناخ لأركب، فاستحييت منه وعرفت غيرتك، فقال: والله لحملك النوى على رأسك كان أشد عليّ من ركوبك معه. قالت: حتى أرسل إليّ أبو بكر بعد ذلك بخادم يكفيني سياسة الفرس، فكأنما أعتقني."],"takhrij":"متفق عليه: رواه البخاري (٥٢٢٤)، ومسلم (٢١٨٢).","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5224) and Muslim (2182).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: Al-Zubayr married me when he had no wealth on earth, no servant, and nothing except a camel for drawing water and his horse. So I used to feed his horse, fetch water, stitch his water-skin, and knead dough. I was not good at baking bread, and some neighbor women from the Ansar used to bake for me, and they were truthful women. I used to carry date-stones on my head from the land of al-Zubayr that the Messenger of Allah ﷺ had granted him, and it was about two-thirds of a farsakh away. One day I came carrying date-stones on my head, and I met the Messenger of Allah ﷺ with a group of the Ansar. He called me and then said, “Ikh, ikh,” to make me ride behind him. But I felt shy to go with the men, and I remembered al-Zubayr and his jealousy, and he was the most jealous of people. So the Messenger of Allah ﷺ realized that I was shy and continued on. Then I came to al-Zubayr and said: The Messenger of Allah ﷺ met me while I had date-stones on my head, and he had some of his Companions with him, and he made his camel kneel so I could ride, but I felt shy before him and remembered your jealousy. He said: By Allah, your carrying date-stones on your head was harder on me than your riding with him. She said: Then later Abu Bakr sent me a servant who relieved me of tending the horse, and it was as if he had freed me."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5224},{"key":"muslim","label":"مسلم","number":2182}]},{"num":6327,"demo":false,"sanad":"","matn":["عن عليّ بن أبي طالب، أن فاطمة أتت النبي ﷺ تشكو إليه ما تلقى في يدها من الرَّحى، وبلغه أنه جاءه رقيق، فلم تصادفه، فذكرتْ ذلك لعائشة، فلما جاء أخبرته عائشة، قال: فجاءنا وقد أخذنا مضاجعنا، فذهبنا نقوم، فقال: (( على مكانكما )) فجاء فقعد بيني وبينها، حتى وجدت برد قدميه على بطني، فقال: (( ألا أدلّكما على خير مما سألتما؟ إذا أخذتما مضاجعكما، أو آويتما إلى فراشكما، فسبّحا ثلاثاً وثلاثين، واحمدا ثلاثاً وثلاثين، وكبّرا أربعاً وثلاثين، فهو خير لكما من خادم ))."],"takhrij":"متفق عليه: رواه البخاري (٥٣٦١)، ومسلم (٢٧٢٧).","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5361) and Muslim (2727).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported that Fatimah came to the Prophet ﷺ complaining about what her hands suffered from grinding with the millstone. News had reached her that some captives had come to him, but she did not find him, so she mentioned it to ‘A’ishah. When he came, ‘A’ishah informed him. He said: So he came to us after we had gone to our beds, and we started to get up, but he said: “Stay where you are.” Then he came and sat between me and her until I felt the coolness of his feet on my stomach. Then he said: “Shall I not direct you to something better than what you asked for? When you go to your beds, or lie down in your bed, say ‘Subhan Allah’ thirty-three times, ‘Alhamdulillah’ thirty-three times, and ‘Allahu Akbar’ thirty-four times. That is better for you than a servant.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5361},{"key":"muslim","label":"مسلم","number":2727}]},{"num":6328,"demo":false,"sanad":"","matn":["عن ابن عمر، عن النبي ﷺ قال: (( كلّكم راعٍ، وكلكم مسؤول عن رعيته، والأمير راعٍ، والرجل راعٍ على أهل بيته، والمرأة راعية على بيت زوجها وولده، فكلّكم راعٍ وكلكم مسؤول عن رعيته ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٠٠)، ومسلم (٢٠:١٨٢٩).","grade":"متفق عليه","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5200) and Muslim (20:1829).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Umar reported from the Prophet ﷺ that he said: “Each of you is a shepherd, and each of you is responsible for his flock. The ruler is a shepherd. A man is a shepherd over the people of his household. A woman is a shepherd over the house of her husband and his child. So each of you is a shepherd, and each of you is responsible for his flock.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5200},{"key":"muslim","label":"مسلم","number":20}]},{"num":6329,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( كُلُّ نفسٍ من بني آدم سيّدٌ، فالرجلُ سيّدُ أهله، والمرأةُ سيّدةُ بيتِها))."],"takhrij":"حسن: رواه ابنُ السنّي في عمل اليوم والليلة (٣٨٩)، وابنُ عدي في الكامل (١٥٢٠/٤).","grade":"حسن","chapter_ar":"باب رعاية المرأة لزوجها وولدها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Sunni in ‘Amal al-Yawm wa al-Laylah (389), and Ibn ‘Adi in al-Kamil (4/1520).","chapter_en":"A woman’s care for her husband and her child","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah said: the Messenger of Allah ﷺ said: “Every soul from the children of Adam is a master. So the man is the master of his family, and the woman is the lady of her house.”"]}},"tuhfa":{},"refs":[{"key":"ابن_السنی/عمل_الیوم_واللیلہ","label":"ابنُ السنّي في عمل اليوم والليلة","number":389},{"key":"ابن_عدی/الکامل","label":"ابنُ عدي في الكامل","number":1520}]},{"num":6330,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال لي رسول الله ﷺ: (( إني لأعلمُ إذا كنتِ عني راضية، وإذا كنتِ عليّ غَضْبى)). قالت: فقلتُ: من أين تعرف ذلك؟ فقال: (( أما إذا كنتِ عني راضية فإنك تقولين: لا ورب محمد، وإذا كنتِ غضبى قلتِ: لا ورب إبراهيم )). قالت: قلت: أجل والله يا رسول الله، ما أهجر إلا اسمك."],"takhrij":"متفق عليه: رواه البخاري (٥٢٢٨)، ومسلم (٨٠ :٢٤٣٩).","grade":"متفق عليه","chapter_ar":"باب غضب المرأة على زوجها وهجرها له","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5228) and Muslim (80:2439).","chapter_en":"A wife’s anger with her husband and her forsaking him","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["‘A’ishah said: the Messenger of Allah ﷺ said to me: “I certainly know when you are pleased with me and when you are angry with me.” She said: I said: How do you know that? He said: “When you are pleased with me, you say: ‘No, by the Lord of Muhammad,’ and when you are angry, you say: ‘No, by the Lord of Ibrahim.’” She said: I replied: Yes, by Allah, O Messenger of Allah, I do not forsake except your name."]},"buhuth":{"ar":["والغضب هنا: المراد منه الغيرة التي تلحق نساء النبي ﷺ، وأما الغضب بمعنى الكراهية فهي لا تُتصوَّر من عائشة في حق النبي ﷺ؛ لأنها كبيرة ومُحبِطة للأعمال، بخلاف غير النبي ﷺ فممكن."],"en":["The anger meant here is the jealousy that affected the wives of the Prophet ﷺ. As for anger in the sense of hatred, that cannot be imagined from ‘A’ishah toward the Prophet ﷺ, because that would be a grave matter and ruinous to deeds. As for someone other than the Prophet ﷺ, that is possible."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5228},{"key":"muslim","label":"مسلم","number":80}]},{"num":6331,"demo":false,"sanad":"","matn":["عن جابر قال: تزوجت امرأة فقال لي رسول الله ﷺ: (( هل تزوجت؟)) قلت: نعم. قال: (( أبكراً أم ثيّباً؟)) قلت: ثيّباً. قال: (( فأين أنت من العذارى ولعابها؟)).","قال شعبة: فذكرته لعمرو بن دينار، فقال: قد سمعته من جابر، وإنما قال: (( فهلا جارية تلاعبُها وتلاعبُك؟))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٨٠)، ومسلم (٥٥ :٧١٥)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ملاعبة الزوجة ومضاحكتها والانبساط إليها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5080) and Muslim (55:715), and the wording is that of Muslim.","chapter_en":"Playing with one’s wife, joking with her, and being relaxed and cheerful with her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Jabir said: I married a woman, so the Messenger of Allah ﷺ said to me: “Have you married?” I said: Yes. He said: “A virgin or a previously married woman?” I said: A previously married woman. He said: “Then why not a young virgin, so you could play with her and she could play with you?”","Shu‘bah said: I mentioned it to ‘Amr ibn Dinar, and he said: I heard it from Jabir. Rather, he said: “Why not a young girl whom you could amuse and who could amuse you?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5080},{"key":"muslim","label":"مسلم","number":55}]},{"num":6332,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: كنا نتقي الكلام والانبساط إلى نسائنا على عهد النبي ﷺ هيبة أن ينزل فينا شيء، فلما توفّي النبي ﷺ تكلّمنا وانبسطنا."],"takhrij":"صحيح: رواه البخاري (٥١٨٧).","grade":"صحيح","chapter_ar":"باب ملاعبة الزوجة ومضاحكتها والانبساط إليها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5187).","chapter_en":"Playing with one’s wife, joking with her, and being relaxed and cheerful with her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: During the lifetime of the Prophet ﷺ, we used to avoid speaking freely and being relaxed with our wives out of fear that something might be revealed concerning us. But when the Prophet ﷺ passed away, we spoke more openly and became relaxed."]},"buhuth":{"ar":["قوله: (( فلما توفي .. الخ )) قال ابن حجر: يشعر بأن الذي كانوا يتركونه كان من المباح تحت البراءة الأصلية، فكانوا يخافون أن ينزل في ذلك منع أو تحريم، وبعد وفاة النبي ﷺ أمِنوا ففعلوا تمسكاً بالبراءة الأصلية."],"en":["His saying, “When he passed away…” Ibn Hajar said: This indicates that what they had been leaving off was originally permissible under the basic presumption of permissibility. They had feared that a prohibition might be revealed concerning it. After the Prophet ﷺ passed away, they felt safe and did it, holding to the original presumption of permissibility."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5187}]},{"num":6333,"demo":false,"sanad":"","matn":["عن عائشة أن امرأة من الأنصار زوّجت ابنتها، فتمعَّط شعرُ رأسِها، فجاءت إلى النبي ﷺ فذكرت ذلك له، فقالتْ: إنّ زوجها أمرني أن أصل في شعرها. فقال: (( لا، إنه قد لُعن الموصلات ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٠٥)، ومسلم (١١٨ :٢١٢٣)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن وصل شعر المرأة، وإن أمر به زوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5205) and Muslim (118:2123), with the wording from al-Bukhari.","chapter_en":"The prohibition of adding hair to a woman’s hair, even if her husband commands it","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah reported that a woman from the Ansar married off her daughter, and the hair of her head fell out. So she came to the Prophet ﷺ and mentioned that to him, and said: Her husband has ordered me to add hair to hers. He said: “No. Indeed, those who add hair have been cursed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5205},{"key":"muslim","label":"مسلم","number":118}]},{"num":6334,"demo":false,"sanad":"","matn":["عن أنس قال: كان النبي ﷺ لا يطرق أهله. كان لا يدخل إلا غُدوةً أو عشيةً."],"takhrij":"متفق عليه: رواه البخاري (١٨٠٠)، ومسلم (١٨٠-١٩٢٨).","grade":"متفق عليه","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (1800) and Muslim (180:1928).","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Anas said: The Prophet ﷺ would not come suddenly upon his family at night. He would only enter in the morning or in the evening."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1800},{"key":"muslim","label":"مسلم","number":180}]},{"num":6335,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: كنا مع رسول الله ﷺ في غزاة، فلما قدمنا المدينة ذهبنا لندخل، فقال: (( أمهلوا حتى ندخل ليلاً ـ يعني عشاءً ـ كي تمتشط الشَّعِثةُ، وتستحدَّ المغيبة ))."],"takhrij":"متفق عليه: رواه البخاري (٥٠٧٩)، ومسلم (١٨١ :١٩٢٨)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5079) and Muslim (181:1928), with the wording from Muslim.","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We were with the Messenger of Allah ﷺ on an expedition. When we arrived at Madinah and were about to enter, he said: “Wait until we enter at night — meaning in the evening — so that the woman with disheveled hair may comb herself, and the woman whose husband has been absent may remove her unwanted hair.”"]},"buhuth":{"ar":["وفي رواية عند البخاري (٥٢٤٤): (( إذا طال أحدكم الغيبة فلا يطرق أهله ليلاً )).","وفي رواية عند أبي داود (٢٧٧٧) من وجه آخر: (( إن أحسن ما دخل الرجل على أهله إذا قدم من سفر أول الليل ))."],"en":["In a narration in al-Bukhari (5244): “If one of you has been away for a long time, he should not come to his family suddenly at night.”","And in a narration in Abu Dawud (2777) by another chain: “The best way for a man to enter upon his family when returning from a journey is at the beginning of the night.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5079},{"key":"muslim","label":"مسلم","number":181}]},{"num":6336,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: كان النبي ﷺ يكره أن يأتي الرجل أهله طروقاً. وزاد في رواية: يتخوّنهم أو يلتمِسُ عثراتهم."],"takhrij":"متفق عليه: رواه البخاري (٥٢٤٣)، ومسلم (١٨٥ :١٩٢٨)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5243) and Muslim (185:1928), with the wording from al-Bukhari.","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: The Prophet ﷺ disliked that a man should come upon his family suddenly at night. And in another narration there is an addition: seeking to suspect them of betrayal or looking for their faults."]},"buhuth":{"ar":["وقوله: (( يتخونهم… )) أي يلتمس خيانتها هل هي عفيفة أم لا؟ مع أن الأصل في المؤمنة أنها تكون عفيفة، فلا يجوز التجسُّس في عفتها، وهذه من الحكمة في النهي عن الدخول على النساء ليلاً."],"en":["His saying, “suspecting them…” means searching for betrayal and whether she is chaste or not. But the basic assumption regarding a believing woman is that she is chaste, so it is not permissible to spy concerning her chastity. This is one of the wisdoms behind the prohibition of entering upon women suddenly at night."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5243},{"key":"muslim","label":"مسلم","number":185}]},{"num":6337,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: كنا في غزوة، فقال رسول الله ﷺ: (( لا تطرقوا النساءَ )). وأرسلَ من يؤذِنُ الناسَ أنهم قادمون الغداة."],"takhrij":"صحيح: رواه ابن خزيمة كما في إتحاف المهرة (٢٤٩/٩)، وأبو عوانة (٧٥٣٦)، والبيهقي (١٧٤/٩).","grade":"صحيح","chapter_ar":"باب النهي أن يطرق الرجل أهله ليلاً","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah as cited in Ithaf al-Maharah (9/249), Abu ‘Awanah (7536), and al-Bayhaqi (9/174).","chapter_en":"The prohibition of a man arriving suddenly to his family at night","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar said: We were on an expedition, and the Messenger of Allah ﷺ said: “Do not come suddenly upon the women.” And he sent someone to announce to the people that they would be arriving the next morning."]}},"tuhfa":{},"refs":[{"key":"ابن_خزیمہ_کما/اتحاف_المہرہ","label":"ابن خزيمة كما في إتحاف المهرة","number":249},{"key":"ابو_عوانہ","label":"أبو عوانة","number":7536},{"key":"البیہقی","label":"البيهقي","number":174}]},{"num":6338,"demo":false,"sanad":"","matn":["عن ابن عباس، قال رسول الله ﷺ:","«إِنِّي رَأَيْتُ الْجَنَّةَ فَتَنَاوَلْتُ مِنْهَا عُنْقُودًا، وَلَوْ أَخَذْتُهُ لَأَكَلْتُمْ مِنْهُ مَا بَقِيَتِ الدُّنْيَا، وَرَأَيْتُ النَّارَ فَلَمْ أَرَ كَالْيَوْمِ مَنْظَرًا قَطُّ أَفْظَعَ، وَرَأَيْتُ أَكْثَرَهَا النِّسَاءَ».","قالوا:","لم يا رسول الله؟","قال:","«لِكُفْرِهِنَّ».","قيل:","أيكفرن بالله؟","قال:","«يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الْإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ كُلَّهُ، ثُمَّ رَأَتْ مِنْكَ شَيْئًا، قَالَتْ: مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ»."],"takhrij":"متفق عليه: رواه مالك (٢)، والبخاري (٥١٩٧)، ومسلم (٩٠٧).","grade":"متفق عليه","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (2), al-Bukhārī (5197), and Muslim (907).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ said:","“I saw Paradise and reached for a cluster from it. Had I taken it, you would have continued eating from it for as long as this world remained.","I also saw the Fire, and I have never seen a sight more terrifying than it today, and I saw that most of its inhabitants were women.”","They asked:","“Why, O Messenger of Allah?”","He said:","“Because of their ingratitude.”","It was asked:","“Do they disbelieve in Allah?”","He replied:","“They are ungrateful to their husbands and ungrateful for kindness. If you were good to one of them for an entire lifetime, then she saw one thing from you that displeased her, she would say: ‘I have never seen any good from you at all.’”"]},"buhuth":{"ar":["وقوله: «العشير» هو الزوج.","وقوله: «يكفرن» أي ينكرن، وفيه جواز إطلاق الكفر على كفران الحقوق، ولا يكون الإنسان بهذا كافرًا بالله تعالى. انظر تفصيل ذلك في كتاب الإيمان.","وقوله: «العنقود» من العنب ونحوه: ما تعقد وتراكم من ثمرة في أصل واحد، ويقال له أيضًا «القِطف»."],"en":["The word al-ʿashīr means the husband.","The expression “they commit kufr” means that they deny or show ingratitude. This demonstrates that the word kufr may be used for ingratitude toward rights without thereby making a person a disbeliever in Allah Most High. The detailed discussion appears in the Book of Faith.","The word “cluster” refers to grapes or similar fruit gathered together on a single stem; it is also called a qiṭf."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2},{"key":"bukhari","label":"البخاري","number":5197},{"key":"muslim","label":"مسلم","number":907}]},{"num":6339,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، قال: خرج رسول الله ﷺ في أضحى أو فطر إلى المصلى، فمرّ على النساء، فقال: (( يا معشر النساء تصدقن، فإني رأيتكن أكثر أهل النار )). فقلن: وبمَ يا رسول الله؟ قال: (( تكثرن اللعن، وتكفرن العشير… )) الحديث."],"takhrij":"متفق عليه: رواه البخاري (٣٠٤)، ومسلم (٨٠)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (304) and Muslim (80), and the wording is from al-Bukhari.","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ went out on the Day of Adha or Fitr to the prayer-place. He passed by the women and said: “O gathering of women, give charity, for I saw that you are the majority of the people of the Fire.” They said: Why is that, O Messenger of Allah? He said: “You frequently curse, and you are ungrateful to the husband…” to the end of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":304},{"key":"muslim","label":"مسلم","number":80}]},{"num":6340,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: شهدت مع رسول الله ﷺ الصلاة يوم العيد، فبدأ بالصلاة قبل الخطبة بغير أذان ولا إقامة، ثم قام متوكئاً على بلال، فأمر بتقوى الله وحث على طاعته، ووعظ الناس وذكرهم، ثم مضى حتى أتى النساء، فوعظهنّ وذكرهنّ، فقال: (( تصدقن فإن أكثركن حطب جهنم )). فقامت امرأة من سِطة النساء سفعاء الخدين، فقالت: لم يا رسول الله؟ قال: (( لأنكنَّ تكثرن الشكاة وتكفرن العشير )). قال: فجعلنَ يتصدقنَ من حليّهنَّ يلقينَ في ثوب بلالٍ من أقرطتِهنّ وخواتيمهنّ."],"takhrij":"صحيح: رواه مسلم (٤:٨٨٥)، والبخاري (٩٧٨).","grade":"صحيح","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (4:885) and al-Bukhari (978).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I witnessed the Eid prayer with the Messenger of Allah ﷺ. He began with the prayer before the sermon, without adhan or iqamah. Then he stood, leaning on Bilal, and commanded the people to fear Allah, urged them to obey Him, admonished them, and reminded them. Then he moved on until he came to the women, and he admonished and reminded them, saying: “Give charity, for most of you are the fuel of Hell.” Then a woman from the middle of the women stood up, with darkened cheeks, and said: Why, O Messenger of Allah? He said: “Because you complain much and are ungrateful to the husband.” He said: Then they began giving charity from their jewelry, throwing into Bilal’s cloth their earrings and rings."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":4},{"key":"bukhari","label":"البخاري","number":978}]},{"num":6341,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، عن رسول الله ﷺ أنه قال: (( يا معشر النساء تصدَّقْنَ وأكثرْنَ الاستغفارَ، فإني رأيتكنّ أكثرَ أهل النار )). فقالت امرأة منهنّ، جزلة: ومالنا يا رسول الله ﷺ أكثر أهل النار؟ قال: (( تُكثرن اللعن، وتكفُرْنَ العشيرَ )) الحديث."],"takhrij":"صحيح: رواه مسلم (٧٩).","grade":"صحيح","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (79).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["‘Abd Allah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “O gathering of women, give charity and seek forgiveness often, for I saw that you are the majority of the people of the Fire.” A strong-minded woman among them said: Why are we, O Messenger of Allah, the majority of the people of the Fire? He said: “You curse frequently and you are ungrateful to the husband,” to the end of the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":79}]},{"num":6342,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ بمثل معنى حديث ابن عمر عن النبي ﷺ كما قال مسلم."],"takhrij":"صحيح: رواه مسلم (٨٠).","grade":"صحيح","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (80).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ something with the same meaning as the hadith of Ibn ‘Umar from the Prophet ﷺ, as stated by Muslim."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":80}]},{"num":6343,"demo":false,"sanad":"","matn":["عن أسماء بنت يزيد - إحدى نساء بني عبد الأشهل - تقول:","مر بنا رسول الله ﷺ ونحن في نسوة، فسلم علينا، وقال:","«إِيَّاكُنَّ وَكُفْرَ الْمُنْعِمِينَ».","فقلنا:","يا رسول الله، وما كفر المنعمين؟","قال:","«لَعَلَّ إِحْدَاكُنَّ أَنْ تَطُولَ أَيْمَتُهَا بَيْنَ أَبَوَيْهَا، وَتَعْنَسَ، فَيَرْزُقَهَا اللَّهُ عَزَّ وَجَلَّ زَوْجًا، وَيَرْزُقَهَا مِنْهُ مَالًا وَوَلَدًا، فَتَغْضَبَ الْغَضْبَةَ، فَتَقُولَ: مَا رَأَيْتُ مِنْهُ يَوْمًا خَيْرًا قَطُّ»."],"takhrij":"حسن: رواه أحمد (٢٧٥٦١)، والطبراني في الكبير (٢٤/١٦٤).","grade":"حسن","chapter_ar":"باب نهي النساء عن كفر العشير","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27561) and al-Ṭabarānī in al-Kabīr (24/164).","chapter_en":"Warning women against ingratitude toward the husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Asmāʾ bint Yazīd, one of the women of Banū ʿAbd al-Ashhal, reported:","The Messenger of Allah ﷺ passed by us while we were with a group of women. He greeted us and said:","“Beware of ingratitude toward those who bestow favors upon you.”","We asked:","“O Messenger of Allah, what is ingratitude toward those who bestow favors?”","He said:","“One of you may remain unmarried for a long time in the house of her parents and grow older, then Allah, Mighty and Majestic, provides her with a husband and grants her through him wealth and children. Then she becomes angry on one occasion and says: ‘I have never seen any good from him at all.’”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":24},{"key":"ahmad","label":"مسند الإمام أحمد","number":27561,"n":27561}]},{"num":6344,"demo":false,"sanad":"","matn":["عن معاذ بن جبل قال: قال رسول الله ﷺ: (( لا تؤذي امرأة زوجها إلا قالت زوجتُه من الحور العين: لا تؤذيه قاتلكِ الله، فإنما هو عندك دخيل، أوشك أن يفارقكِ إلينا ))."],"takhrij":"حسن: رواه الترمذي (١١٧٤) وحسّنه، وابن ماجه (٢٠١٤)، وأحمد (٢٢١٠١).","grade":"حسن","chapter_ar":"باب النهي عن إيذاءِ المرأةِ زوجَها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1174), who graded it Hasan, Ibn Majah (2014), and Ahmad (22101).","chapter_en":"The prohibition of a woman harming her husband","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["Mu‘adh ibn Jabal said: the Messenger of Allah ﷺ said: “No woman harms her husband except that his wife from the women of Paradise says: ‘Do not harm him, may Allah fight you. He is only a temporary guest with you, and soon he will leave you and come to us.’”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1174},{"key":"ibnmajah","label":"ابن ماجه","number":2014},{"key":"ahmad","label":"مسند الإمام أحمد","number":22101,"n":22101}]},{"num":6345,"demo":false,"sanad":"","matn":["عن ابن عمر، عن النبي ﷺ قال: (( إذا استأذنت امرأة أحدكم المسجد فلا يمنعها )).","وزاد في رواية: فقال بلال بن عبد الله: والله لنمنعهنّ، قال: فأقبل عليه عبد الله فسبّه سبّاً سيئاً، ما سمعته سبّه مثله قط، وقال: أخبرُك عن رسول الله ﷺ وتقول: والله لنمنعهنّ."],"takhrij":"متفق عليه: رواه البخاري (٥٢٣٨)، ومسلم (١٣٤ :٤٤٢)، والزيادة في رواية مسلم (١٣٥ :٤٤٢).","grade":"متفق عليه","chapter_ar":"باب الإذن للنساء في الخروج إلى المسجد وقضاء حوائجهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5238) and Muslim (134:442), and the addition is in Muslim (135:442).","chapter_en":"Permission for women to go out to the mosque and to fulfill their needs","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Ibn ‘Umar reported from the Prophet ﷺ that he said: “If the wife of one of you asks permission to go to the mosque, he should not prevent her.”","And in an added narration: Bilal ibn ‘Abd Allah said: By Allah, we will surely prevent them. So ‘Abd Allah turned to him and rebuked him harshly, with a rebuke the like of which I had never heard from him, and said: I inform you from the Messenger of Allah ﷺ and you say: By Allah, we will surely prevent them?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5238},{"key":"muslim","label":"مسلم","number":134},{"key":"الزیادہ/روایہ_مسلم","label":"الزيادة في رواية مسلم","number":135}]},{"num":6346,"demo":false,"sanad":"","matn":["عن عائشة قالت:","خرجت سودة بنت زمعة ليلًا، فرآها عمر فعرفها، فقال:","إنك والله يا سودة ما تخفين علينا.","فرجعت إلى النبي ﷺ فذكرت ذلك له، وهو في حجرتي يتعشى، وإن في يده لَعَرْقًا، فأُنزل عليه، فرفع عنه، وهو يقول:","«قَدْ أُذِنَ لَكُنَّ أَنْ تَخْرُجْنَ لِحَوَائِجِكُنَّ»."],"takhrij":"متفق عليه: رواه البخاري (٥٢٣٧)، ومسلم (٢١٧٠/١٧)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الإذن للنساء في الخروج إلى المسجد وقضاء حوائجهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5237) and Muslim (2170/17). This is the wording of al-Bukhārī.","chapter_en":"Permission for women to go out to the mosque and to fulfill their needs","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["ʿĀʾishah reported:","Sawdah bint Zamʿah went out at night. ʿUmar saw her and recognized her, and said:","“By Allah, O Sawdah, you cannot remain unrecognized by us.”","She returned to the Prophet ﷺ and mentioned this to him while he was eating supper in my apartment, with a bone containing some meat still in his hand.","Revelation came down upon him. When it had ended, he said:","“Permission has been granted to you women to go out for your needs.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5237},{"key":"muslim","label":"مسلم","number":2170}]},{"num":6347,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود قال: قال النبي ﷺ: (( لا تُباشر المرأةُ المرأةَ، فتنعتها لزوجها كأنه ينظر إليها ))."],"takhrij":"صحيح: رواه البخاري (٥٢٤٠).","grade":"صحيح","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5240).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["‘Abd Allah ibn Mas‘ud said: the Prophet ﷺ said: “A woman should not closely examine another woman and then describe her to her husband as though he were looking at her.”"]},"buhuth":{"ar":["وقوله: (( تنعتها لزوجها )) وذلك خشية أن يعجب الزوج الوصف المذكور، فيطلّق زوجته، أو يفتن بالموصوفة."],"en":["His saying, “describe her to her husband,” is because of the fear that the husband may become taken by that description, then divorce his wife or become infatuated with the woman being described."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5240}]},{"num":6348,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( لا تباشر المرأةُ المرأة، ولا الرجلُ الرجلَ ))."],"takhrij":"حسن: رواه أحمد (٨٣١٨)، والطبراني في الصغير (٦٥٣)، والطحاوي في مشكل الآثار (٣٢٥٨).","grade":"حسن","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (8318), al-Tabarani in al-Saghir (653), and al-Tahawi in Mushkil al-Athar (3258).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Abu Hurayrah said: the Messenger of Allah ﷺ said: “A woman should not lie in close bodily contact with another woman, and a man should not lie in close bodily contact with another man.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الصغیر","label":"الطبراني في الصغير","number":653},{"key":"الطحاوی/مشکل_الاثار","label":"الطحاوي في مشكل الآثار","number":3258},{"key":"ahmad","label":"مسند الإمام أحمد","number":8318,"n":8318}]},{"num":6349,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسول الله ﷺ: (( لا يباشر الرجلُ الرجلَ، ولا المرأةُ المرأةَ ))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٧٧٣)، والطبراني في الكبير (١١٧٢٨)، والبزار - كشف الأستار - (٢٠٧٤).","grade":"صحيح","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (2773), al-Tabarani in al-Kabir (11728), and al-Bazzar in Kashf al-Astar (2074).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Abbas said: the Messenger of Allah ﷺ said: “A man should not lie in close bodily contact with another man, and a woman should not lie in close bodily contact with another woman.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":2773},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":11728},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار -","number":2074},{"key":"ahmad","label":"مسند الإمام أحمد","number":2773,"n":2773}]},{"num":6350,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: سمعت رسول الله ﷺ ينهى أن يباشر الرجلُ الرجلَ في ثوب واحد، والمرأةُ المرأةَ في ثوب واحد."],"takhrij":"حسن: رواه الحاكم (٢٨٧ /٤).","grade":"حسن","chapter_ar":"باب لا تباشر المرأة المرأة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Hakim (4/287).","chapter_en":"A woman must not closely expose another woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: I heard the Messenger of Allah ﷺ forbid that a man closely join another man under one garment, and that a woman closely join another woman under one garment."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"المستدرك على الصحيحين","number":7775,"n":7779}]},{"num":6351,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري أن رسول الله ﷺ قال: (( لا ينظر الرجل إلى عورة الرجل، ولا المرأة إلى عورة المرأة، ولا يُفضي الرجل إلى الرجل في ثوب واحد، ولا تُفضي المرأة إلى المرأة في الثوب الواحد ))."],"takhrij":"صحيح: رواه مسلم (٣٣٨).","grade":"صحيح","chapter_ar":"باب تحريم النظر إلى العورات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (338).","chapter_en":"The prohibition of looking at the private parts","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ said: “A man must not look at the private part of another man, and a woman must not look at the private part of another woman. A man must not lie closely with another man under one garment, and a woman must not lie closely with another woman under one garment.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":338}]},{"num":6352,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: قال رسول الله ﷺ: (( إن من أشرّ الناس يوم القيامة، الرجل يفضي إلى امرأته، وتفضي إليه ثم ينشر سرّها )).","وفي لفظ: (( إن من أعظم الأمانة عند الله يوم القيامة، الرجل يفضي إلى امرأته وتفضي إليه، ثم ينشر سرّها ))."],"takhrij":"حسن: رواه مسلم (١٢٣:١٤٣٧).","grade":"حسن","chapter_ar":"باب تحريم إفشاء أسرار الجماع بين الزوجين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Muslim (123:1437).","chapter_en":"The prohibition of disclosing the secrets of intimacy between spouses","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: the Messenger of Allah ﷺ said: “Among the worst of people on the Day of Resurrection is a man who goes in unto his wife and she goes in unto him, then he spreads her secret.”","And in another wording: “Among the greatest betrayals of trust before Allah on the Day of Resurrection is that a man goes in unto his wife and she goes in unto him, then he spreads her secret.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":123}]},{"num":6353,"demo":false,"sanad":"","matn":["عن أبي سعيد، عن النبي ﷺ قال: (( ألا عسى أحدُكم أن يخلوَ بأهلِه يُغلق بابًا، ثم يُرخي سترًا، ثم يقضي حاجتَه، ثم إذا خرجَ حدَّثَ أصحابه بذلك، ألا عسى إحداكنَّ أن تغلق بابها وترخي سترَها، فإذا قضتْ حاجتَها، حدّثتْ صواحبَها )). فقالت امرأةٌ سفعاءُ الخدّين: واللهِ يا رسولَ الله إنّهن ليفعلن، وإنّهم ليفعلون، قال: (( فلا تَفْعَلوا، فإنه مثلُ ذلك مثلُ شيطان، لَقِيَ شيطانة على قارعةِ الطريق، فقضَى حاجتَه منها، ثم انصرفَ وتركَها ))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٤٥٠).","grade":"حسن","chapter_ar":"باب تحريم إفشاء أسرار الجماع بين الزوجين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar in Kashf al-Astar (1450).","chapter_en":"The prohibition of disclosing the secrets of intimacy between spouses","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abu Sa‘id narrated from the Prophet ﷺ that he said: “Perhaps one of you is alone with his wife, closes the door, lets down the curtain, then fulfills his need, and when he comes out he tells his companions about it. And perhaps one of you women closes her door and lets down her curtain, then when she fulfills her need, she tells her female companions.” A dark-cheeked woman said: By Allah, O Messenger of Allah, the women do that, and the men do that too. He said: “Then do not do that, for the likeness of that is the likeness of a devil who met a she-devil on the roadside, fulfilled his need with her, then went away and left her.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1450},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1450,"n":1451}]},{"num":6354,"demo":false,"sanad":"","matn":["عن أبي هريرة -في حديث طويل كما ذُكِر-، وجاء فيه: (( هل فيكم رجل إذا أتى أهلَه أغلق بابه، وأرخى ستره، ثم يخرج فيحدث فيقول: فعلت بأهلي كذا، وفعلت بأهلي كذا؟ )) فسكنوا، فأقبل على النساء فقال: (( هل منكنّ من تحدّث؟ ))، فجثت فتاة كعاب على إحدى ركبتيها، وتطالت لرسول الله ﷺ ليراها ويسمع كلامها، فقالت: إي والله إنهم ليتحدثون، وإنهن ليُحدثن، قال: (( فهل تدرون ما مثل من فعل ذلك؟ إن مثل ذلك، مثل شيطان وشيطانة لقي أحدهما صاحبه بالسكة، فقضى حاجته منها والناس ينظرون إليه ))."],"takhrij":"حسن: رواه أحمد (١٠٩٧٧)، وأبو داود (٢١٧٤)، والخرائطي في مساوئ الأخلاق (٤٣٠).","grade":"حسن","chapter_ar":"باب تحريم إفشاء أسرار الجماع بين الزوجين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (10977), Abu Dawud (2174), and al-Khara’iti in Masawi’ al-Akhlaq (430).","chapter_en":"The prohibition of disclosing the secrets of intimacy between spouses","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah narrated — in a long hadith as previously mentioned — and in it there came: “Is there among you any man who, when he goes to his wife, closes his door and lets down his curtain, then goes out and says: I did such-and-such with my wife, and I did such-and-such with my wife?” They remained silent. Then he turned to the women and said: “Is there any among you who speaks of such things?” Then a young full-breasted girl knelt on one of her knees and stretched herself up so that the Messenger of Allah ﷺ could see her and hear her words. She said: Yes, by Allah, the men certainly speak of it, and the women certainly speak of it too. He said: “Do you know what the likeness of the one who does that is? The likeness of that is like a male devil and a female devil who met one another in the street, then he fulfilled his desire with her while the people were watching.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2174},{"key":"الخرایطی/مساوی_الاخلاق","label":"الخرائطي في مساوئ الأخلاق","number":430},{"key":"ahmad","label":"مسند الإمام أحمد","number":10977,"n":10977}]},{"num":6355,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو، عن النبي ﷺ قال: (( إذا تزوّج أحدُكم امرأةً، أو اشترى خادماً فليقل: اللهم إني أسألك خيرها، وخير ما جَبَلْتَها عليه، وأعوذُ بك من شرّها ومن شر ما جَبَلْتَها عليه، وإذا اشترى بعيراً فليأخذْ بذروةِ سَنَامه وليقلْ مثل ذلك )).","وفي لفظ: (( إذا أفاد أحدُكم امرأةً، أو خادماً، أو دابّةً، فليأخذ بناصيتها ))، وليقُلْ: فذكر الحديث."],"takhrij":"حسن: رواه أبو داود (٢١٦٠)، وابن ماجه (١٩١٨)، وابن السني (١٠٠)، والحاكم (١٨٥/٢).","grade":"حسن","chapter_ar":"باب ما يقول الرجل إذا دخل على عروسه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2160), Ibn Majah (1918), Ibn al-Sunni (100), and al-Hakim (2/185).","chapter_en":"What a man says when he enters upon his bride","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["‘Abd Allah ibn ‘Amr narrated from the Prophet ﷺ that he said: “When one of you marries a woman or buys a servant, let him say: O Allah, I ask You for her good and the good upon which You created her, and I seek refuge in You from her evil and the evil upon which You created her. And if he buys a camel, let him take hold of the top of its hump and say the same.”","And in another wording: “When one of you acquires a wife, a servant, or a riding beast, let him take hold of its forelock,” then let him say the supplication just mentioned."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2160},{"key":"ibnmajah","label":"ابن ماجه","number":1918},{"key":"ابن_السنی","label":"ابن السني","number":100},{"key":"hakim","label":"الحاكم","number":185}]},{"num":6356,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال النبي ﷺ: (( أما لو أنّ أحدكم يقول حين يأتي أهلَه: بسم الله، اللهم جنّبني الشيطان، وجنّب الشيطان ما رزقتنا، ثم قُدِّر بينهما في ذلك أو قُضي ولد لم يضُرّه شيطان أبداً )).","وفي لفظ: (( لو أن أحدهم إذا أراد أن يأتي أهله… ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٦٥)، ومسلم (١١٦:١٤٣٤)، واللفظ للبخاري، واللفظ الثاني لمسلم.","grade":"متفق عليه","chapter_ar":"باب استحباب التسمية عند الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5165) and Muslim (116:1434). The first wording is from al-Bukhari, and the second from Muslim.","chapter_en":"The recommendation to mention Allah’s name before intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":22,"content":{"translation":{"en":["Ibn ‘Abbas said: the Prophet ﷺ said: “If one of you were to say when he goes to his wife: In the name of Allah. O Allah, keep Satan away from me, and keep Satan away from what You provide us, then if it is decreed that a child be conceived between them in that act, Satan will never harm him.”","And in another wording: “If one of them, when he intends to go to his wife…”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5165},{"key":"muslim","label":"مسلم","number":116}]},{"num":6357,"demo":false,"sanad":"","matn":["عن بهز بن الحكيم، عن أبيه، عن جده قال: قلت: يا رسول الله! عوراتنا ما نأتي منها وما نذر؟ قال: (( احفظ عورتَك إلا من زوجتِك، أو ما ملكت يمينُك )). قلت: يا رسول الله! أرأيت إن كان القوم بعضهم في بعض؟ قال: (( إن استطعت أن لا يريَنَّها أحد، فلا يرينَّها )). قلت: يا رسول الله! إن كان أحدنا خالياً؟ قال: (( فالله أحق أن يُستحى منه من الناس ))."],"takhrij":"حسن: رواه أبو داود (٤٠١٧)، والترمذي (٢٧٦٩، ٢٧٩٤)، وابن ماجه (١٩٢٠)، والحاكم (٧٣٥٨).","grade":"حسن","chapter_ar":"باب استحباب التستر عند الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4017), al-Tirmidhi (2769, 2794), Ibn Majah (1920), and al-Hakim (7358).","chapter_en":"The recommendation of concealment during intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":23,"content":{"translation":{"en":["Bahz ibn Hakim, from his father, from his grandfather, said: I said: O Messenger of Allah, regarding our private parts, what may we uncover and what must we conceal? He said: “Guard your private part except from your wife or from what your right hand possesses.” I said: O Messenger of Allah, what if the people are among one another? He said: “If you are able that no one should see it, then let no one see it.” I said: O Messenger of Allah, what if one of us is alone? He said: “Then Allah has more right that one should be shy before Him than before people.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4017},{"key":"tirmidhi","label":"الترمذي","number":2769},{"key":"ibnmajah","label":"ابن ماجه","number":1920},{"key":"hakim","label":"المستدرك على الصحيحين","number":7358,"n":7361}]},{"num":6358,"demo":false,"sanad":"","matn":["عن جابر قال: كانت اليهود تقول: إذا أتى الرجلُ امرأته من دُبُرها في قُبلها، كان الولد أحول، فنزلت: (نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ)."],"takhrij":"متفق عليه: رواه البخاري في التفسير (٤٥٢٨)، ومسلم في النكاح (١١٧:١٤٣٥) كلاهما من طريق سفيان -هو الثوري- عن ابن المنكدر، سمع جابراً يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in al-Tafsir (4528) and Muslim in al-Nikah (117:1435), both by the route of Sufyan — that is, al-Thawri — from Ibn al-Munkadir, who heard Jabir say it.","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Jabir said: The Jews used to say: If a man comes to his wife from behind while entering in her front, the child will be cross-eyed. So this verse was revealed: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish.”"]},"intro":{"ar":["قال الله تعالى: (نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ) [البقرة: ٢٢٣]"],"en":["Allah Most High said: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish.” [al-Baqarah: 223]"]}},"tuhfa":{},"refs":[{"key":"bukhari/التفسیر","label":"البخاري في التفسير","number":4528},{"key":"muslim/النکاح","label":"مسلم في النكاح","number":117}]},{"num":6359,"demo":false,"sanad":"","matn":["عن جابر قال: قالت اليهود: إن الرجل إذا أتى امرأته وهي مُجَبَّية جاء ولده أحول، فنزلت: (نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ) [البقرة: ٢٢٣] إن شاء مجبّية وإن شاء غير مجبّية إذا كان في صمام واحد."],"takhrij":"صحيح: رواه مسلم (١١٩:١٤٣٥)، وابن حبان في صحيحه (٤١٦٦)، واللفظ لابن حبان.","grade":"صحيح","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (119:1435) and Ibn Hibban in his Sahih (4166), and the wording is that of Ibn Hibban.","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Jabir said: The Jews said: If a man comes to his wife while she is bent forward, the child will come out cross-eyed. So the verse was revealed: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish” [al-Baqarah: 223] — whether bent forward or otherwise, so long as it is in one opening."]},"buhuth":{"ar":["قوله: (( مُجبّية )) أي منكبّة على وجهها تشبيها بهيئة السجود. وقوله: (( صمام واحد )) أي ثقب واحد، والمراد به القُبُل."],"en":["His saying, “mujabbiyah,” means bent over on her face, resembling the posture of prostration. And his saying, “one opening,” means one orifice, namely the front passage."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":119},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4166},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4290,"n":4286}]},{"num":6360,"demo":false,"sanad":"","matn":["عن ابن عباس قال: جاء عمر إلى رسول الله ﷺ فقال: يا رسول الله! هلكت. قال: (( وما أهلكك؟ )) قال: حوَّلتُ رحلي الليلة. قال: فلم يرد عليه رسول الله ﷺ شيئاً، قال: فأنزلتْ على رسول الله ﷺ هذه الآية: (( نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ )) أقبل وأدبر، واتّقِ الدبرَ والحيضة."],"takhrij":"حسن: رواه الترمذي (٢٩٨٠)، وأحمد (٢٧٠٣)، والبيهقي (٧/١٩٧)، وصحّحه ابن حبان (٤٢٠٢).","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (2980), Ahmad (2703), al-Bayhaqi (7/197), and authenticated by Ibn Hibban (4202).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Ibn ‘Abbas said: ‘Umar came to the Messenger of Allah ﷺ and said: O Messenger of Allah, I am ruined. He said: “What has ruined you?” He said: I changed my position on my mount last night. He said: The Messenger of Allah ﷺ did not answer him with anything. Then this verse was revealed to the Messenger of Allah ﷺ: “Your wives are a place of cultivation for you, so go to your place of cultivation however you wish” — from the front or from behind, but avoid the anus and menstruation."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2980},{"key":"البیہقی","label":"البيهقي","number":7},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4202},{"key":"ahmad","label":"مسند الإمام أحمد","number":2703,"n":2703},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4291,"n":4287}]},{"num":6361,"demo":false,"sanad":"","matn":["عن ابن عباس قال:","إن ابن عمر - والله يغفر له - أوهم.","إنما كان هذا الحي من الأنصار - وهم أهل وثن - مع هذا الحي من يهود - وهم أهل كتاب - وكانوا يرون لهم فضلًا عليهم في العلم، فكانوا يقتدون بكثير من فعلهم.","وكان من أمر أهل الكتاب أن لا يأتوا النساء إلا على حرف، وذلك أستر ما تكون للمرأة.","فكان هذا الحي من الأنصار قد أخذوا بذلك من فعلهم.","وكان هذا الحي من قريش يشرحون النساء شرحًا منكرًا، ويتلذذون منهن مقبلات ومدبرات ومستلقيات.","فلما قدم المهاجرون المدينة، تزوج رجل منهم امرأة من الأنصار، فذهب يصنع بها ذلك، فأنكرته عليه وقالت:","إنما كنا نؤتى على حرف، فاصنع ذلك وإلا فاجتنبني.","حتى شري أمرهما، فبلغ ذلك رسول الله ﷺ، فأنزل الله عز وجل:","﴿نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ﴾  [البقرة: ٢٢٣]","أي: مقبلات، ومدبرات، ومستلقيات، يعني بذلك موضع الولد."],"takhrij":"حسن: رواه أبو داود (٢١٦٤).","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2164).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿAbbās reported:","Ibn ʿUmar—may Allah forgive him—was mistaken.","This group of the Anṣār had formerly been idol worshippers and lived alongside a group of Jews who were People of the Book. The Anṣār regarded them as superior to themselves in knowledge and therefore followed many of their practices.","Among the practices of the People of the Book was that they would approach women in only one position, considering that to be the most concealing position for the woman.","The Anṣār had adopted this practice from them.","The people of Quraysh, however, used to engage with women in a variety of positions, enjoying them facing them, from behind, and while lying down.","When the Emigrants came to Madinah, one of them married a woman from the Anṣār and wished to approach her in that way. She objected and said:","“We were approached only in one position. Either do that or keep away from me.”","Their dispute became serious and intensified, and the matter reached the Messenger of Allah ﷺ. Allah, Mighty and Majestic, then revealed:","“Your wives are a place of cultivation for you, so approach your place of cultivation however you wish.”  [al-Baqarah: 223]","Meaning: facing them, from behind, or while they are lying down, provided that it is in the place from which children are born."]},"buhuth":{"ar":["وقوله: «شري أمرهما» أي عظم أمرهما وتفاقم."],"en":["The phrase “their matter became serious” means that their dispute became grave and intensified."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2164}]},{"num":6362,"demo":false,"sanad":"","matn":["عن خزيمة بن ثابت قال: إن سائلاً سأل رسول الله ﷺ عن إتيان النساء في أدبارهن. فقال رسول الله ﷺ: (( حلال )). ثم دعاه، أو أمر به، فدعي فقال: (( كيف قلت؟ في أي الخربتين، أو في أي الخرزتين، أو في أي الخصفتين؟ أمن دبرها في قبلها فنعم، أم من دبرها في دبرها فلا، إن الله لا يستحي من الحق، لا تأتوا النساء في أدبارهن ))."],"takhrij":"صحيح: رواه الشافعي في الأم (٥/٩٤).","grade":"صحيح","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Shafi‘i in al-Umm (5/94).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Khuzaymah ibn Thabit said: A questioner asked the Messenger of Allah ﷺ about going to women in their backsides. The Messenger of Allah ﷺ said: “Lawful.” Then he called him back — or ordered that he be called — and when he was brought, he said: “How did you say it? In which of the two openings? Or which of the two parts? Or which of the two places? If from her back into her front, then yes. But if from her back into her back, then no. Indeed Allah is not shy of the truth. Do not go to women in their backsides.”"]}},"tuhfa":{},"refs":[{"key":"الشافعی/الام","label":"الشافعي في الأم","number":5}]},{"num":6363,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ: (( لا ينظرُ اللهُ إلى رجلٍ جامع امرأته في دُبُرِها ))."],"takhrij":"حسن: رواه أبو داود (٢١٦٢)، وابن ماجه (١٩٢٣)، وأحمد (٧٦٨٤).","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2162), Ibn Majah (1923), and Ahmad (7684).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “Allah will not look at a man who has intercourse with his wife in her anus.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2162},{"key":"ibnmajah","label":"ابن ماجه","number":1923},{"key":"ahmad","label":"مسند الإمام أحمد","number":7684,"n":7684}]},{"num":6364,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس قال: قال رسول الله ﷺ: (( لا ينظرُ اللهُ إلى رجلٍ أتى رجلاً، أو امرأةً في الدُّبر ))."],"takhrij":"حسن: رواه الترمذي (١١٦٥)، وأبو بكر بن أبي شيبة (٤/٢٥١-٢٥٢)، وصحّحه ابن حبان (٤٤١٨).","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1165), Abu Bakr ibn Abi Shaybah (4/251–252), and authenticated by Ibn Hibban (4418).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["‘Abd Allah ibn ‘Abbas said: the Messenger of Allah ﷺ said: “Allah will not look at a man who goes to a man, or to a woman, in the anus.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1165},{"key":"ابو_بکر_بن_ابی_شیبہ","label":"أبو بكر بن أبي شيبة","number":4},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4418},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2922,"n":2919}]},{"num":6365,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن النبي ﷺ نهى عن محاشِّ النساءِ."],"takhrij":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (٢٣٠٨).","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat — Majma‘ al-Bahrayn (2308).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah reported that the Prophet ﷺ forbade approaching the buttocks of women."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":2308}]},{"num":6366,"demo":false,"sanad":"","matn":["عن عقبة بن عامر الجهني قال: قال رسول الله ﷺ:","«لَعَنَ اللَّهُ الَّذِينَ يَأْتُونَ النِّسَاءَ فِي مَحَاشِّهِنَّ»."],"takhrij":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (٢٣٠٩).","grade":"حسن","chapter_ar":"باب إتيان المرأة في قبلها كيف ما شاء، إذا تجنب الإتيان في الدبر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Awsaṭ — Majmaʿ al-Baḥrayn (2309).","chapter_en":"Going to one’s wife in her front as one wishes, so long as anal intercourse is avoided","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":24,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī reported that the Messenger of Allah ﷺ said:","“May Allah curse those who have intercourse with women in their anuses.”"]},"buhuth":{"ar":["قال ابن القيم في الطب النبوي (ص ٣١٣):","«وأما الدبر فلم يُبح قط على لسان نبي من الأنبياء، ومن نسب إلى بعض السلف القول بإباحة وطء الزوجة في دبرها فقد غلط عليه».","وقال أيضًا:","«وإذا كان الله حرم الوطء في الفرج لأجل الأذى العارض، فما الظن بالمحل الذي هو محل الأذى اللازم مع زيادة المفسدة بالتعرض لانقطاع النسل»."],"en":["Ibn al-Qayyim said in al-Ṭibb al-Nabawī (p. 313):","“As for intercourse through the anus, it was never made permissible upon the tongue of any prophet. Whoever attributes to some of the early Muslims the view that intercourse with one’s wife through the anus is permissible has wrongly attributed that view to them.”","He also said:","“If Allah prohibited intercourse in the vagina because of temporary harm, then what should be thought of a place that is inherently a place of constant harm, in addition to the further corruption of exposing oneself to the cessation of offspring?”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":2309}]},{"num":6367,"demo":false,"sanad":"","matn":["عن عائشة قالت: كانت إحدانا إذا كانت حائضاً، فأراد رسول الله ﷺ أن يباشرها أمرها أن تتَّزر في فور حيضتها، ثم يباشرها. قالت: وأيكم يملك إربه كما كان رسول الله ﷺ يملك إربه."],"takhrij":"متفق عليه: رواه البخاري (٣٠٢)، ومسلم (٢٩٣).","grade":"متفق عليه","chapter_ar":"باب ما جاء في مباشرة الحائض دون الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (302) and Muslim (293).","chapter_en":"What has been reported about intimacy with a menstruating wife short of intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":25,"content":{"translation":{"en":["‘A’ishah said: When one of us was menstruating and the Messenger of Allah ﷺ wanted to enjoy her, he would command her to wrap a waistcloth around herself at the beginning of her menstruation, then he would enjoy her. She said: Which of you can control his desire as the Messenger of Allah ﷺ controlled his desire?"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":302},{"key":"muslim","label":"مسلم","number":293}]},{"num":6368,"demo":false,"sanad":"","matn":["عن ميمونة قالت: كان رسول الله ﷺ إذا أراد أن يباشر امرأة من نسائه أمرها فاتزرت، وهي حائض."],"takhrij":"متفق عليه: رواه البخاري (٣٠٣)، ومسلم (٢٩٤).","grade":"متفق عليه","chapter_ar":"باب ما جاء في مباشرة الحائض دون الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (303) and Muslim (294).","chapter_en":"What has been reported about intimacy with a menstruating wife short of intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":25,"content":{"translation":{"en":["Maymunah said: When the Messenger of Allah ﷺ wished to enjoy one of his wives, he would command her to wrap herself in a waistcloth while she was menstruating."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":303},{"key":"muslim","label":"مسلم","number":294}]},{"num":6369,"demo":false,"sanad":"","matn":["عن أنس أن اليهودَ كانوا إذا حاضت المرأةُ فيهم لم يؤاكلوها ولم يُجامعوهنّ في البيوت، فسأل أصحابُ النبيِّ النبيَّ ﷺ، فأنزل الله تعالى: (وَيَسْأَلُونَكَ عَنِ ٱلْمَحِيضِ قُلْ هُوَ أَذًى فَٱعْتَزِلُواْ النِّسَاءَ فِي ٱلْمَحِيضِ) إلى آخر الآية [البقرة: ٢٢٢] فقال رسول الله ﷺ: (( اصنعوا كلَّ شيء إلا النكاح )).","فبلغ ذلك اليهودَ فقالوا: ما يريد هذا الرجل أن يَدَعَ من أمرنا شيئاً إلا خالَفَنا فيه. فجاء أُسيدُ بن حُضير وعبّادُ بن بِشْر فقالا: يا رسولَ الله! إن اليهودَ تقول: كذا وكذا؛ أفلا نُجامِعهُنَّ؟ فتغيَّر وجهُ رسول الله ﷺ حتى ظننّا أن قد وجد عليهما، فخرجا فاستقبلهما هديةٌ من لَبَن إلى النبي ﷺ، فأرسل في آثارهما فسقاهما، فعرفا أن لم يجد عليهما."],"takhrij":"صحيح: رواه مسلم (٣٠٢).","grade":"صحيح","chapter_ar":"باب ما جاء في مباشرة الحائض دون الجماع","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (302).","chapter_en":"What has been reported about intimacy with a menstruating wife short of intercourse","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":25,"content":{"translation":{"en":["Anas said: The Jews, when a woman among them menstruated, would not eat with her and would not live with her in the houses. So the Companions of the Prophet ﷺ asked the Prophet ﷺ, and Allah Most High revealed: “And they ask you about menstruation. Say: It is harm, so keep away from women during menstruation” to the end of the verse [al-Baqarah: 222]. So the Messenger of Allah ﷺ said: “Do everything except intercourse.”","That reached the Jews, and they said: This man does not want to leave anything from our affairs except that he opposes us in it. Then Usayd ibn Hudayr and ‘Abbad ibn Bishr came and said: O Messenger of Allah, the Jews say such-and-such; should we then have intercourse with them? The face of the Messenger of Allah ﷺ changed until we thought that he was angry with them. Then they went out, and a gift of milk for the Prophet ﷺ met them, so he sent after them and gave them drink, and they knew that he had not been angry with them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":302}]},{"num":6370,"demo":false,"sanad":"","matn":["عن ابن محيريز، أنه قال: دخلت المسجد، فرأيت أبا سعيد الخدري، فجلست إليه، فسألته عن العزل؟ فقال: خرجنا مع رسول الله ﷺ في غزوة بني المصطلق، فأصبنا سبياً من سبي العرب، فاشتهينا النساء، واشتد علينا العُزْبة، وأحببنا الفداء، فأردنا أن نعزل، فقلنا: نعزل ورسول الله ﷺ بين أظهرنا قبل أن نسأله، فسألناه عن ذلك، فقال: (( ما عليكم أن لا تفعلوا، ما من نسمة كائنة إلى يوم القيامة إلا وهي كائنة ))."],"takhrij":"متفق عليه: رواه مالك (٩٥)، والبخاري (٢٥٤٢)، ومسلم (١٢٥:١٤٣٨).","grade":"متفق عليه","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (95), al-Bukhari (2542), and Muslim (125:1438).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Ibn Muhayriz said: I entered the mosque and saw Abu Sa‘id al-Khudri, so I sat with him and asked him about withdrawal. He said: We went out with the Messenger of Allah ﷺ on the expedition of Banu al-Mustaliq, and we obtained female captives from the Arab captives. We desired women, celibacy had become hard on us, and we wanted ransom money, so we intended to practice withdrawal. We said: Shall we practice withdrawal while the Messenger of Allah ﷺ is among us before asking him? So we asked him about that, and he said: “There is no blame upon you if you do not do it. There is no soul that will exist until the Day of Resurrection except that it will surely come into existence.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":95},{"key":"bukhari","label":"البخاري","number":2542},{"key":"muslim","label":"مسلم","number":125}]},{"num":6371,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: أصبنا سبايا، فكنا نعزل، فسألنا رسول الله ﷺ فقال: (( أوَإنكم لتفعلون؟ )) - قالها ثلاثاً - (( ما من نسمة كائنة إلى يوم القيامة إلا هي كائنة ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢١٠)، ومسلم (١٢٧:١٤٣٨).","grade":"متفق عليه","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5210) and Muslim (1438:127).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: We captured female prisoners, and we used to practice withdrawal, so we asked the Messenger of Allah about it. He said: “Do you really do that?” He said it three times. “There is no soul that is destined to exist until the Day of Resurrection except that it will surely come into existence.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5210},{"key":"muslim","label":"مسلم","number":127}]},{"num":6372,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري أن رجلا قال: يا رسول الله ﷺ إن لي جارية، وأنا أعزل عنها، وأنا أكره أن تحمل، وأنا أريد ما يريد الرجال، وإن اليهود تحدث أن العزل موؤدة صغرى. فقال: (( كذبت يهود، ولو أراد الله أن يخلقه ما استطعت أن تصرفه ))."],"takhrij":"حسن: رواه أبو داود (٢١٧١)، وأحمد (١١٤٧٧، ١١٢٨٨)، والطحاوي في مشكل الآثار (١٩١٧).","grade":"حسن","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2171), Ahmad (11477, 11288), and al-Tahawi in Mushkil al-Athar (1917).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that a man said: O Messenger of Allah, I have a slave-girl, and I withdraw from her. I dislike that she should become pregnant, though I desire what men desire. The Jews say that withdrawal is minor infanticide. He said: “The Jews have lied. If Allah intended to create it, you would not be able to turn it away.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2171},{"key":"الطحاوی/مشکل_الاثار","label":"الطحاوي في مشكل الآثار","number":1917},{"key":"ahmad","label":"مسند الإمام أحمد","number":11477,"n":11477}]},{"num":6373,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله، أن رجلاً أتى رسول الله ﷺ فقال: (( إن لي جارية هي خادمنا وسانيتنا، وأنا أطوف عليها، وأنا أكره أن تحمل )). فقال: (( اعزل عنها إن شئت، فإنه سيأتيها ما قُدِّر لها )). فلبث الرجل، ثم أتاه فقال: إن الجارية قد حبلت. فقال: (( قد أخبرتك أنه سيأتيها ما قُدِّر لها ))."],"takhrij":"صحيح: رواه مسلم (١٤٣٩). وفي رواية: (( إن ذلك لن يمنع شيئاً أراده الله )). قال: فجاء الرجل فقال: يا رسول الله، إن الجارية التي كنت ذكرتها لك حملت؟ فقال رسول الله ﷺ: (( أنا عبد الله ورسوله )).","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1439). In another narration: “That will not prevent anything Allah has intended.” Then the man came and said: O Messenger of Allah, the slave-girl I mentioned to you has become pregnant. So the Messenger of Allah ﷺ said: “I am the servant of Allah and His Messenger.”","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ʿAbdullah narrated that a man came to the Messenger of Allah ﷺ and said: “I have a slave-girl who serves us and waters our land, and I have relations with her, but I dislike that she should become pregnant.” He said: “Practice withdrawal from her if you wish, for what has been decreed for her will come to her.” The man stayed away for some time, then came back and said: The slave-girl has become pregnant. He said: “I told you that what had been decreed for her would come to her.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1439}]},{"num":6374,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: كنا نعزل والقرآن ينزل، لو كان شيئا يُنهى عنه لنهانا عنه القرآن.","وفي لفظ: كنا نعزل على عهد رسول الله ﷺ"],"takhrij":"متفق عليه: رواه البخاري في النكاح (٥٢٠٨)، ومسلم في النكاح (١٤٤٠).","grade":"متفق عليه","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5208) and Muslim (1440).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Jabir ibn ‘Abd Allah said: We used to practice withdrawal while the Qur’an was being revealed. If it had been something forbidden, the Qur’an would have forbidden us from it.","And in another wording: We used to practice withdrawal during the time of the Messenger of Allah."]}},"tuhfa":{},"refs":[{"key":"bukhari/النکاح","label":"البخاري في النكاح","number":5208},{"key":"muslim/النکاح","label":"مسلم في النكاح","number":1440}]},{"num":6375,"demo":false,"sanad":"","matn":["عن جابر قال: كنا نعزل على عهد رسول الله ﷺ ، فبلغ ذلك نبي الله ﷺ فلم ينهنا."],"takhrij":"صحيح: رواه مسلم (١٦٣:١٤٤٠).","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1440:163).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Jabir said: We used to practice withdrawal during the time of the Messenger of Allah ﷺ, and that reached the Prophet of Allah ﷺ, yet he did not forbid us."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":163}]},{"num":6376,"demo":false,"sanad":"","matn":["عن عامر بن سعد، أن أسامة بن زيد أخبر والده سعد بن أبي وقاص أن رجلاً جاء إلى رسول الله ﷺ فقال: إني أعزل عن امرأتي، قال له رسول الله ﷺ : (( لم تفعل ذلك؟ )) فقال الرجل أُشفق على ولدها أو على أولادها، فقال رسول الله ﷺ: (( لو كان ذلك ضارّاً لضر فارس والروم ))"],"takhrij":"صحيح: رواه مسلم في النكاح (١٤٣:١٤٤٣).","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1443:143).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["ʿAmir ibn Saʿd narrated that Usamah ibn Zayd informed his father Saʿd ibn Abi Waqqas that a man came to the Messenger of Allah ﷺ and said: I practice withdrawal from my wife. Allah’s Messenger ﷺ said to him: “Why do you do that?” The man said: I fear for her child, or for her children. So the Messenger of Allah ﷺ said: “If it were harmful, it would have harmed the Persians and the Romans.”"]}},"tuhfa":{},"refs":[{"key":"muslim/النکاح","label":"مسلم في النكاح","number":143}]},{"num":6377,"demo":false,"sanad":"","matn":["عن أبي ذر أن رسول الله ﷺ قال: (( لك في جماع زوجتك أجر )). فقيل: يا رسول الله، وفي شهوة يكون من أجر؟ قال: (( نعم، أرأيت لو كان لك ولد قد أدرك، ثم مات أكنت محتسبه؟ )) قال: نعم، قال: (( أنت كنت خلقته؟ )) قال: بل الله خلقه. قال: (( أنت كنت هديته؟ )) قال: بل الله هداه. قال: (( أكنت ترزقه؟ )) قال: بل الله كان رزقه. قال رسول الله ﷺ: (( فضعه في حلاله وجنبه حرامه، وأقرره، فإن شاء الله أحياه، وإن شاء أماته، ولك أجر ))."],"takhrij":"حسن: رواه ابن حبان (٤١٩٢).","grade":"حسن","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (4192).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Dharr narrated that the Messenger of Allah ﷺ said: “You have a reward in having intercourse with your wife.” It was said: O Messenger of Allah ﷺ, does one of us fulfill his desire and still get a reward for it? He said: “Yes. Tell me, if you had a child who reached maturity and then died, would you hope for reward for that?” He said: Yes. He said: “Did you create him?” He said: Rather, Allah created him. He said: “Did you guide him?” He said: Rather, Allah guided him. He said: “Did you provide for him?” He said: Rather, Allah provided for him. The Messenger of Allah ﷺ said: “Then place it in its lawful place, keep it away from what is unlawful, and let it take its course. If Allah wills, He will give it life, and if He wills, He will cause it to die, and you will have a reward.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2432,"n":2429}]},{"num":6378,"demo":false,"sanad":"","matn":["عن أبي ذر أنه قال:","على كل نفس في كل يوم طلعت فيه الشمس صدقة منه على نفسه.","قلت:","يا رسول الله، من أين أتصدق وليس لنا أموال؟","قال:","«لِأَنَّ مِنْ أَبْوَابِ الصَّدَقَةِ التَّكْبِيرَ، وَسُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَأَسْتَغْفِرُ اللَّهَ، وَتَأْمُرُ بِالْمَعْرُوفِ، وَتَنْهَى عَنِ الْمُنْكَرِ، وَتَعْزِلُ الشَّوْكَةَ عَنْ طَرِيقِ النَّاسِ وَالْعَظْمَ وَالْحَجَرَ، وَتَهْدِي الْأَعْمَى، وَتُسْمِعُ الصُّمَّ وَالْأَبْكَمَ حَتَّى يَفْقَهَ، وَتَدُلُّ الْمُسْتَدِلَّ عَلَى حَاجَةٍ لَهُ قَدْ عَلِمْتَ مَكَانَهَا، وَتَسْعَى بِشِدَّةِ سَاقَيْكَ إِلَى اللَّهْفَانِ الْمُسْتَغِيثِ، وَتَرْفَعُ بِشِدَّةِ ذِرَاعَيْكَ مَعَ الضَّعِيفِ، كُلُّ ذَلِكَ مِنْ أَبْوَابِ الصَّدَقَةِ مِنْكَ عَلَى نَفْسِكَ، وَلَكَ فِي جِمَاعِكَ زَوْجَتِكَ أَجْرٌ».","قال أبو ذر:","كيف يكون لي أجر في شهوتي؟","فقال رسول الله ﷺ:","«أَرَأَيْتَ لَوْ كَانَ لَكَ وَلَدٌ فَأَدْرَكَ وَرَجَوْتَ خَيْرَهُ فَمَاتَ، أَكُنْتَ تَحْتَسِبُ بِهِ؟»","قلت: نعم.","قال:","«فَأَنْتَ خَلَقْتَهُ؟»","قال: بل الله خلقه.","قال:","«فَأَنْتَ هَدَيْتَهُ؟»","قال: بل الله هداه.","قال:","«فَأَنْتَ تَرْزُقُهُ؟»","قال: بل الله كان يرزقه.","قال رسول الله ﷺ:","«كَذَلِكَ فَضَعْهُ فِي حَلَالِهِ وَجَنِّبْهُ حَرَامَهُ، فَإِنْ شَاءَ اللَّهُ أَحْيَاهُ، وَإِنْ شَاءَ أَمَاتَهُ، وَلَكَ أَجْرٌ»."],"takhrij":"صحيح: رواه أحمد (٢١٤٨٤).","grade":"صحيح","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (21484).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abū Dharr reported:","Every person owes a charity on behalf of himself on every day upon which the sun rises.","I asked:","“O Messenger of Allah, how can I give charity when we have no wealth?”","He said:","“Among the doors of charity are saying ‘Allahu Akbar,’ ‘Subḥān Allah,’ ‘al-ḥamdu lillāh,’ ‘lā ilāha illā Allah,’ and ‘astaghfirullāh’; commanding what is right and forbidding what is wrong; removing a thorn, a bone, or a stone from the path of the people; guiding the blind; helping the deaf and mute understand; directing someone seeking guidance to a need whose location you know; hurrying with the strength of your legs to aid a distressed person calling for help; and using the strength of your arms to assist someone weak. All of these are doors of charity that you perform on behalf of yourself, and you also receive a reward for intercourse with your wife.”","Abū Dharr asked:","“How can I receive a reward for fulfilling my desire?”","The Messenger of Allah ﷺ said:","“Suppose you had a child who reached maturity and you hoped for good from him, then he died. Would you seek reward from Allah for him?”","I said:","“Yes.”","He asked:","“Did you create him?”","He replied:","“Rather, Allah created him.”","He asked:","“Did you guide him?”","He replied:","“Rather, Allah guided him.”","He asked:","“Did you provide for him?”","He replied:","“Rather, Allah provided for him.”","The Messenger of Allah ﷺ said:","“Likewise, place your desire in what is lawful and keep it away from what is unlawful. If Allah wills, He gives life, and if He wills, He causes death, and you receive a reward.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":21484,"n":21484}]},{"num":6379,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: سئل رسول الله ﷺ عن العزل قالوا: إن اليهود تزعم أن العزل هو الموؤدة الصغرى قال: (( كذبت يهود))."],"takhrij":"حسن: رواه البزار - كشف الأستار (١٤٥١)، والبيهقي (٧/٢٣٠).","grade":"حسن","chapter_ar":"باب ما جاء في العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzar, Kashf al-Astar (1451), and al-Bayhaqi (7/230).","chapter_en":"What has been reported concerning withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":27,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ was asked about withdrawal. They said: The Jews claim that withdrawal is minor infanticide. He said: “The Jews have lied.”"]},"buhuth":{"ar":["فقه الباب: حكم العزل، لا أعرف من قال بتحريمه، وأما المكروه فنعم، قال به بعض الفقهاء، والأصل أنه جائزٌ لما عرفنا من تقرير القرآن والسنة.","والنساء على ثلاثة أنواع:","أن تكون مملوكةً، فضررها إنْ حملتْ ووضعتْ تكون أمُّ ولدٍ، وأمُّ ولدٍ لا يجوز بيعُها.","أن تكون أمةً ورقيقةً فضررُها في عدم عزلها إنْ حملتْ وولدتْ يكون ولدُها رقيقاً تبعاً لأمّه.","أن تكون زوجته حُرَّةً فلا يجوز معها العزل إلا بإذنها، بأن تكون مريضة فتأذن بالعزل خوفا من الحمل. وأما بدون إذنها فلا يجوز ذلك، لأن من حقها أن تستمتع وتحمل وتلد."],"en":["Jurisprudence of this chapter: Regarding the ruling on withdrawal, I do not know of anyone who said it is forbidden. As for it being disliked, yes, some jurists held that view. The basic principle is that it is permissible, based on what we know from the approval of the Qur’an and the Sunnah.","Women are of three types:","If she is owned, then the harm in her becoming pregnant and giving birth is that she becomes an umm walad, and an umm walad may not be sold.","If she is a female slave and bondwoman, then the harm in not practicing withdrawal from her is that if she becomes pregnant and gives birth, her child will be a slave following his mother.","If she is his free wife, then withdrawal with her is not permitted except with her permission, such as if she is ill and allows withdrawal for fear of pregnancy. But without her permission, that is not allowed, because it is her right to enjoy intimacy, become pregnant, and bear children."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1451},{"key":"البیہقی","label":"البيهقي","number":7},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14315,"n":14456}]},{"num":6380,"demo":false,"sanad":"","matn":["عن جدامة بنت وهب أخت عكاشة بن وهب قالت: حضرت رسول الله ﷺ وسألوه عن العزل فقال: (( الوأد الخفي))"],"takhrij":"صحيح: رواه مسلم في النكاح (١٤١:١٤٤٢).","grade":"صحيح","chapter_ar":"باب ماجاء في كراهية العزل","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1442:141).","chapter_en":"What Has Been Reported Regarding the Dislike of Withdrawal","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":28,"content":{"translation":{"en":["Judamah bint Wahb, the sister of ʿUkkashah ibn Wahb, said: I was present with the Messenger of Allah ﷺ, and they asked him about withdrawal, so he said: “It is hidden infanticide.”"]}},"tuhfa":{},"refs":[{"key":"muslim/النکاح","label":"مسلم في النكاح","number":141}]},{"num":6381,"demo":false,"sanad":"","matn":["عن عائشة، عن جدامة بنت وهب الأسدية، أنها أخبرتها أنها سمعت رسول الله ﷺ ، يقول: (( لقد هممت أن أنهى عن الغيلة، حتّى ذكرتُ أن الروم وفارس يصنعون ذلك، فلا يضر أولادهم))"],"takhrij":"صحيح: رواه مالك في الرضاع (١٦).","grade":"صحيح","chapter_ar":"باب ما جاء في الغيلة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (16) and Muslim (1442:140).","chapter_en":"What Has Been Reported Regarding Ghilah","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":29,"content":{"translation":{"en":["ʿA’ishah narrated from Judamah bint Wahb al-Asadiyyah that she informed her that she heard the Messenger of Allah ﷺ say: “I had intended to forbid ghilah, until I remembered that the Romans and Persians do that, and it does not harm their children.”"]}},"tuhfa":{},"refs":[{"key":"malik/الرضاع","label":"مالك في الرضاع","number":16}]},{"num":6382,"demo":false,"sanad":"","matn":["عن جدامة بنت وهب أخت عكاشة قالت: حضرت رسول الله ﷺ في أناس وهو يقول: (( لقد هممت أن أنهى عن الغِيلة، فنظرت في الروم وفارس، فإذا هم يُغيلون أولادهم، فلا يضر أولادهم ذلك شيئاً )) ثم سألوه عن العزل؟ فقال رسول الله ﷺ: (( ذلك الوأد الخفي )) زاد في رواية وهي (وَإِذَا الْمَوْءُودَةُ سُئِلَتْ) [التكوير: ٨]"],"takhrij":"صحيح: رواه مسلم في النكاح (١٤١:١٤٤٢).","grade":"صحيح","chapter_ar":"باب ما جاء في الغيلة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1442:141).","chapter_en":"What Has Been Reported Regarding Ghilah","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":29,"content":{"translation":{"en":["Judamah bint Wahb, the sister of ʿUkkashah, said: I was present with the Messenger of Allah ﷺ among some people while he was saying: “I had intended to forbid ghilah, but I looked at the Romans and Persians, and they practice ghilah with their children, yet that does not harm their children at all.” Then they asked him about withdrawal, so the Messenger of Allah ﷺ said: “That is hidden infanticide.” In one narration there is the addition: “And when the buried girl is asked” [Surat al-Takwir: 8]."]}},"tuhfa":{},"refs":[{"key":"muslim/النکاح","label":"مسلم في النكاح","number":141}]},{"num":6383,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس أن رسول الله ﷺ سئل عن الغيل فقال: (( لو كان ضاراً أحداً ضر فارس والروم))"],"takhrij":"صحيح: رواه البزار - كشف الأستار (١٤٥٤).","grade":"صحيح","chapter_ar":"باب ما جاء في الغيلة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzar, Kashf al-Astar (1454).","chapter_en":"What Has Been Reported Regarding Ghilah","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":29,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAbbas narrated that the Messenger of Allah ﷺ was asked about ghayl, and he said: “If it were harmful to anyone, it would have harmed the Persians and the Romans.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1454},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1454,"n":1455}]},{"num":6384,"demo":false,"sanad":"","matn":["عن عطاء قال: حضرنا مع ابن عباس جنازة ميمونة بسَرِف، فقال ابن عباس: هذه زوجة النبي ﷺ، فإذا رفعتم نعشَها فلا تُزعزعوها، ولا تزلزلوها، وارفقوا، فإنه كان عند النبي ﷺ تسع، كان يقسم لثمان ولا يقسم لواحدة."],"takhrij":"متفق عليه: رواه البخاري في النكاح (٥٠٦٧)، ومسلم في الرضاع (٥١:١٤٦٥).","grade":"متفق عليه","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5067) and Muslim (1465:51).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿAta’ said: We attended the funeral of Maymunah at Sarif with Ibn ʿAbbas, and Ibn ʿAbbas said: This is the wife of the Prophet ﷺ, so when you lift her bier, do not shake it or jolt it; be gentle, for the Prophet ﷺ had nine wives. He used to divide his time among eight and did not divide for one of them."]},"intro":{"ar":["قال الله تعالى: (فَانكِحُوا مَا طَابَ لَكُم مِّنَ النِّسَاءِ مَثْنَىٰ وَثُلَاثَ وَرُبَاعَ ۖ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً أَوْ مَا مَلَكَتْ أَيْمَانُكُمْ ۚ ذَٰلِكَ أَدْنَىٰ أَلَّا تَعُولُوا) [النساء: ٣]\\n\\nوقال تعالى: (وَلَن تَسْتَطِيعُوا أَن تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا كُلَّ الْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِ) [النساء: ١٢٩] قال ابن عباس: أي في الحب والجماع."],"en":["Allah the Exalted said: “Marry those women who are lawful for you, two, three, or four; but if you fear that you will not be just, then one, or those whom your right hands possess. That is more likely that you will not commit injustice.” [Surat al-Nisa’: 3]\\n\\nAnd He said: “You will never be able to be completely just between wives, even if you are eager. So do not incline completely toward one and leave another hanging.” [Surat al-Nisa’: 129]\\n\\nIbn ʿAbbas said: This means in love and intercourse."]}},"tuhfa":{},"refs":[{"key":"bukhari/النکاح","label":"البخاري في النكاح","number":5067},{"key":"muslim/الرضاع","label":"مسلم في الرضاع","number":51}]},{"num":6385,"demo":false,"sanad":"","matn":["عن صفية بنت حيي أن النبي ﷺ حج بنسائه، فلما كان في بعض الطريق نزل رجل، فساق بهن، فأسرع، فقال النبي ﷺ: (( كذاك سوقك بالقوارير )) يعني النساء، فبينا هم يسيرون برك بصفية بنت حيي جملها، وكانت من أحسنهن ظهراً، فبكت، فجاء رسول الله ﷺ حين أُخبر بذلك، فجعل يمسح دموعها بيده، وجعلت تزداد بكاء، وهو ينهاها، فلما أكثرت، زبرها، وانتهرها، وأمر الناس بالنزول فنزلوا، ولم يكن يريد أن ينزل. قالت: فنزلوا، وكان يومي، فلما نزلوا، ضُرب خباء النبي ﷺ ودخل فيه، قالت: فلم أدر علام أهجُم من رسول الله ﷺ، وخشيت أن يكون في نفسه شيء مني، فانطلقت إلى عائشة، فقلت لها: تعلمين أني لم أكن أبيع يومي من رسول الله ﷺ بشيء أبداً، وإني قد وهبت يومي لك على أن تُرضي رسول الله ﷺ عني. قالت: نعم. قالت: فأخذت عائشة خماراً لها قد ثردته بزعفران، فرشّته بالماء ليذكي ريحه، ثم لبست ثيابها، ثم انطلقت إلى رسول الله ﷺ فرفعت طرف الخباء، فقال لها: (( ما لك يا عائشة؟ إن هذا ليس بيومك )) قالت: ذلك فضل الله يؤتيه من يشاء. فقال مع أهله. فلما كان عند الرواح، قال لزينب بنت جحش: (( يا زينب، أفقري أختك صفية جملاً )) وكانت من أكثرهن ظهراً، فقالت: أنا أفقر يهوديتك؟ فغضب النبي حين سمع ذلك منها، فهجرها، فلم يكلمها حتى قدم مكة، وأيام منى في سفره، حتى رجع إلى المدينة والمحرم وصفر، فلم يأتها، ولم يقسم لها، ويئست منه. فلما كان شهر ربيع الأول دخل عليها، فرأت ظله، فقالت: إن هذا لظل رجل، وما يدخل علي النبي ﷺ، فمن هذا؟ فدخل النبي ﷺ، فلما رأته، قالت: يا رسول الله ﷺ ما أدري ما أصنع حين دخلت عليّ، قالت: وكانت لها جارية، وكانت تخبؤها من النبي ﷺ، فقالت: فلانة لك، فمشى النبي ﷺ إلى سرير زينب، وكان قد رُفع، فوضعه بيده، ثم أصاب أهله، ورضي عنهم."],"takhrij":"حسن: رواه الإمام أحمد (٢٦٨٦٦).","grade":"حسن","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (26866).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Safiyyah bint Huyayy narrated that the Prophet ﷺ performed Hajj with his wives. During part of the journey, a man came down and drove them on quickly, so the Prophet ﷺ said: “Take care when driving these glass vessels,” meaning the women. While they were traveling, Safiyyah bint Huyayy’s camel knelt down, and she was one of those with the best mounts, so she cried. The Messenger of Allah ﷺ came when he was informed of that and began wiping her tears with his hand, but she cried even more while he was trying to calm her. When she cried excessively, he rebuked her and scolded her, then ordered the people to halt, though he had not intended to stop. She said: So they stopped, and it was my day. The Prophet’s tent was pitched and he entered it. She said: I did not know why the Messenger of Allah had withdrawn from me, and I feared that something about me was in his heart. So I went to ʿA’ishah and said to her: You know that I would never give up my day with the Messenger of Allah for anything, but I have given my day to you on condition that you make the Messenger of Allah pleased with me. She said: Yes. She said: Then ʿA’ishah took a head-covering of hers which she had perfumed with saffron, sprinkled it with water so that its fragrance would be stronger, then put on her clothes and went to the Messenger of Allah and lifted the edge of the tent. He said to her: “What is the matter, O ʿA’ishah? This is not your day.” She said: That is the bounty of Allah; He gives it to whom He wills. So he remained with his family. Then when it was time to set out, he said to Zaynab bint Jahsh: “O Zaynab, lend your sister Safiyyah a camel.” Zaynab had more riding animals than any of them, but she said: Shall I lend my camel to your Jewish woman? The Prophet became angry when he heard that from her, and he forsook her and did not speak to her until he arrived in Makkah, and through the days of Mina on his journey, then until he returned to Madinah through Muharram and Safar. He did not go to her and did not allot her a turn, and she despaired of him. Then when the month of Rabiʿ al-Awwal came, he entered upon her. She saw his shadow and said: This is surely the shadow of a man, but the Prophet does not enter upon me, so who is this? Then the Prophet entered, and when she saw him, she said: O Messenger of Allah, I do not know what to do now that you have entered upon me. She said: She had a slave-girl whom she used to hide from the Prophet, so she said: So-and-so is yours. Then the Prophet went to Zaynab’s bed, which had been raised, lowered it with his own hand, then went in to his wife, and became pleased with them."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":26866},{"key":"ahmad","label":"مسند الإمام أحمد","number":26866,"n":26866}]},{"num":6386,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: إن نبي الله ﷺ كان يطوف على نسائه في الليلة الواحدة، وله يومئذ تسعُ نسوة.","وفي رواية: كان النبي ﷺ يدور على نسائه في الساعة الواحدة من الليل والنهار وهن إحدى عشرة. قال: قلتُ لأنس: أو كان يطيقه؟ قال: كنا نتحدث أنه أُعطي قوة ثلاثين."],"takhrij":"صحيح: رواه البخاري في النكاح (٥٢١٥).","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5215) and (268).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet of Allah ﷺ used to go around to his wives in a single night, and at that time he had nine wives.","In another narration: The Prophet ﷺ used to go around to his wives in a single hour of the night and day, and they were eleven. I said to Anas: Was he able to do that? He said: We used to say that he had been given the strength of thirty men."]}},"tuhfa":{},"refs":[{"key":"bukhari/النکاح","label":"البخاري في النكاح","number":5215}]},{"num":6387,"demo":false,"sanad":"","matn":["عن أنس قال: كان للنبي ﷺ تسع نسوة، فكان إذا قسم بينهن لا ينتهي إلى المرأة الأولى إلا في تسع، فكن يجتمعن كل ليلة في بيت التي يأتيها، فكان في بيت عائشة، فجاءت زينب فمد يده إليها. فقالت: هذه زينب، فكف النبي ﷺ يده، فتقاولتا حتى استخبتا، وأقيمت الصلاة، فمر أبو بكر على ذلك، فسمع أصواتهما، فقال: اخرج يا رسول الله ﷺ إلى الصلاة، واحْثُ في أفواههن التراب. فخرج النبي ﷺ، فقالت عائشة: الآن يقضي النبي ﷺ صلاته، فيجيء أبو بكر فيفعل بي ويفعل. فلما قضى النبي ﷺ صلاته أتاها أبو بكر، فقال لها قولًا شديدًا، وقال: أتصنعين هذا؟"],"takhrij":"صحيح: رواه مسلم في الرضاع (١٤٦٢).","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1462).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Anas said: The Prophet ﷺ had nine wives. When he divided his time among them, he would not return to the first wife until nine days had passed. They used to gather every night in the house of the one whose turn it was. It happened in the house of ʿA’ishah. Then Zaynab came, and the Prophet ﷺ extended his hand toward her. ʿA’ishah said: This is Zaynab. So the Prophet ﷺ withdrew his hand. Then the two exchanged words until their voices rose. The prayer was called, and Abu Bakr passed by and heard their voices, so he said: Go out, O Messenger of Allah, to the prayer, and throw dust into their mouths. The Prophet went out, and ʿA’ishah said: Now the Prophet will finish his prayer, and then Abu Bakr will come and do such-and-such to me. When the Prophet finished his prayer, Abu Bakr came to her, spoke to her harshly, and said: Do you do this?"]}},"tuhfa":{},"refs":[{"key":"muslim/الرضاع","label":"مسلم في الرضاع","number":1462}]},{"num":6388,"demo":false,"sanad":"","matn":["عن عائشة قالت:","كان رسول الله ﷺ إذا أراد سفرًا أقرع بين نسائه، فأيتهن خرج سهمها خرج بها معه، وكان يقسم لكل امرأة منهن يومها وليلتها، غير أن سودة بنت زمعة وهبت يومها وليلتها لعائشة زوج النبي ﷺ، تبتغي بذلك رضا رسول الله ﷺ."],"takhrij":"صحيح: رواه البخاري (٢٥٩٣).","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2593).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿĀʾishah reported:","Whenever the Messenger of Allah ﷺ intended to travel, he would draw lots among his wives. Whichever wife’s lot was drawn, he would take her with him.","He would allot each of his wives her own day and night, except that Sawdah bint Zamʿah gave her day and night to ʿĀʾishah, the wife of the Prophet ﷺ, seeking thereby the pleasure of the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2593}]},{"num":6389,"demo":false,"sanad":"","matn":["عن عائشة قالت: ما رأيت امرأة أحب إليّ أن أكون في مِسْلاخها من سودة بنت زمعة من امرأة فيها حدّة، قالت: فلما كبرت جعلتْ يومها من رسول الله ﷺ لعائشة، قالت: يا رسول الله، قد جعلت يومي منك لعائشة، فكان رسول الله ﷺ يقسم لعائشة يومين: يومَها، ويومَ سودة."],"takhrij":"متفق عليه: رواه البخاري (٥٢١٢)، ومسلم (٤٧:١٤٦٣)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5212) and Muslim (1463:47). The wording is from Muslim.","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿA’ishah said: I never saw a woman in whose place I would have preferred to be more than Sawdah bint Zamʿah, a woman who had some sharpness in her nature. When she grew older, she gave her day with the Messenger of Allah ﷺ to ʿA’ishah. She said: O Messenger of Allah, I have given my day with you to ʿA’ishah. So the Messenger of Allah ﷺ used to allot two days to ʿA’ishah: her own day and the day of Sawdah."]},"buhuth":{"ar":["قولها: في (( مِسْلاخها )) أي في جلدها، والمعنى أن أكون أنا هي."],"en":["Her words, “in her skin,” mean: in her place, meaning that I would be she."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5212},{"key":"muslim","label":"مسلم","number":47}]},{"num":6390,"demo":false,"sanad":"","matn":["عن معاذة، عن عائشة أن رسول الله ﷺ كان يستأذن في يوم المرأة منا، بعد أن أنزلت هذه الآية: ( تُرْجِي مَن تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَن تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ) [الأحزاب: ٥١] فقلت لها: ما كنت تقولين؟ قالت: كنت أقول له: إن كان ذلك إليّ فإني لا أريد يا رسول الله ﷺ أن أوثر عليك أحدًا."],"takhrij":"متفق عليه: رواه البخاري (٤٧٨٩)، ومسلم (١٤٧٦).","grade":"متفق عليه","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4789) and Muslim (1476).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Muʿadhah narrated from ʿA’ishah that the Messenger of Allah ﷺ used to ask permission on the day of each one of us, after this verse had been revealed: “You may defer whom you will of them and take to yourself whom you will, and whomever you desire of those you had set aside—there is no blame upon you.” [al-Ahzab: 51] I said to her: What did you used to say? She said: I used to say to him: If that were left to me, then, O Messenger of Allah, I would not wish to prefer anyone over you."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4789},{"key":"muslim","label":"مسلم","number":1476}]},{"num":6391,"demo":false,"sanad":"","matn":["عن عائشة قالت: يا ابن أختي كان رسول الله ﷺ لا يُفضّل بعضنا على بعض في القَسْم من مُكثِه عندنا، وكان قلّ يوم إلا وهو يطوف علينا جميعًا، فيدنو من كل امرأة من غير مسيس، حتى يبلغ إلى التي هو يومُها فيبيت عندها. ولقد قالت سودة بنت زمعة حين أسنّت، وفَرِقت أن يفارقها رسول الله ﷺ: يا رسول الله، يومي لعائشة. فقبل ذلك رسول الله ﷺ منها. قالت: نقول في ذلك أنزل الله عزوجل وفي أشباهها، أراه قال: ( وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا ) [النساء: ١٢٨]."],"takhrij":"حسن: رواه أبو داود (٢١٣٥)، ومن طريقه البيهقي (٤٧/٧)، والحاكم (١٨٦/٢).","grade":"حسن","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2135), and through him al-Bayhaqi (7/47), and al-Hakim (2/186).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["ʿA’ishah said: O son of my sister, the Messenger of Allah ﷺ did not favor some of us over others in how long he stayed with us when dividing his time. There was hardly a day when he would not go around to all of us, drawing near to each woman without intimacy, until he reached the one whose day it was, and then he would spend the night with her. Sawdah bint Zamʿah, when she grew old and feared that the Messenger of Allah ﷺ might separate from her, said: O Messenger of Allah, my day is for ʿA’ishah. So the Messenger of Allah ﷺ accepted that from her. She said: We say that regarding this, and similar cases, Allah the Mighty and Majestic revealed, as I think: “And if a woman fears ill-treatment or aversion from her husband…” [al-Nisa’: 128]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2135},{"key":"ومن_طریقہ_البیہقی","label":"ومن طريقه البيهقي","number":47},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":13434,"n":13562},{"key":"hakim","label":"المستدرك على الصحيحين","number":2760,"n":2746}]},{"num":6392,"demo":false,"sanad":"","matn":["عن ابن عباس قال: توفي رسول الله ﷺ وعنده تسعُ نسوة يُصيبهن إلا سودة فإنها وهبت يومَها وليلتها لعائشة."],"takhrij":"صحيح: رواه النسائي (٣١٩٧).","grade":"صحيح","chapter_ar":"باب العدل بين الزوجات في القسم إلا من وهبت نوبتها لضرتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3197).","chapter_en":"Justice Between Wives in Allotment, Except for the One Who Gives Her Turn to Her Co-Wife","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":30,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ died while he had nine wives with whom he had marital relations, except Sawdah, for she had given her day and night to ʿA’ishah."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3197}]},{"num":6393,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( من كانت له امرأتان يميل مع إحداهما على الأخرى، جاء يوم القيامة وأحد شقيه ساقط ))."],"takhrij":"صحيح: رواه أبو داود (٢١٣٣)، والترمذي (١١٤١)، والنسائي (٣٩٤٢)، وابن ماجه (١٩٦٩)، وابن الجارود (٧٢٢).","grade":"صحيح","chapter_ar":"باب ما جاء فيمن لم يعدل بين نسائه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2133), al-Tirmidhi (1141), al-Nasa’i (3942), Ibn Majah (1969), and Ibn al-Jarud (722).","chapter_en":"What Has Been Reported About One Who Does Not Deal Justly Between His Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":31,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Whoever has two wives and inclines toward one over the other will come on the Day of Resurrection with one side of his body fallen.”"]},"buhuth":{"ar":["قوله: (( يميل مع إحداهما على الأخرى )) يعني في الحقوق في العِشرة، من الأكل والشرب والملبس دون ميل القلب، فإن القلوب لا تُملك."],"en":["His words, “inclines toward one over the other,” mean in the rights of companionship, such as food, drink, and clothing, not the inclination of the heart, for hearts are not under one’s control."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2133},{"key":"tirmidhi","label":"الترمذي","number":1141},{"key":"nasai","label":"النسائي","number":3942},{"key":"ibnmajah","label":"ابن ماجه","number":1969},{"key":"ابن_الجارود","label":"ابن الجارود","number":722}]},{"num":6394,"demo":false,"sanad":"","matn":["عن عائشة قالت: ( وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا ) [النساء: ١٢٨] قالت: هي المرأة تكون عند الرجل لا يستكثر منها، فيريد طلاقها، ويتزوج غيرها، تقول له: أمسكني ولا تطلقني، ثم تزوج غيري، فأنت في حلٍّ من النفقة عليَّ والقِسْمَةِ لي، فذلك قوله تعالى: ( فَلَا جُنَاحَ عَلَيْهِمَا أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ ) [النساء: ١٢٨]."],"takhrij":"متفق عليه: رواه البخاري (٥٢٠٦)، ومسلم (٣٠٢١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في تصالح الزوجين على عدم النفقة والقسمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5206) and Muslim (3021).","chapter_en":"What Has Been Reported About a Husband and Wife Reconciling Over Waiving Maintenance and Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":33,"content":{"translation":{"en":["ʿA’ishah said concerning the verse, “And if a woman fears ill-treatment or aversion from her husband…” [al-Nisa’: 128]: It refers to a woman who is with a man who no longer has much desire for her, so he wants to divorce her and marry another. She says to him: Keep me and do not divorce me, then marry someone else; you are released from spending on me and from dividing your time for me. That is the meaning of His saying, Exalted is He: “Then there is no sin upon them if they make terms of settlement between them, and settlement is best.” [al-Nisa’: 128]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5206},{"key":"muslim","label":"مسلم","number":3021}]},{"num":6395,"demo":false,"sanad":"","matn":["عن ابن عباس قال: خشيت سودة أن يُطلّقها النبي ﷺ فقالت: لا تُطلّقني، وأمسكني، واجعلْ يومي لعائشة. ففعل. فنزلت: ( فَلَا جُنَاحَ عَلَيْهِمَا أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ ) [النساء: ١٢٨]."],"takhrij":"حسن: رواه الترمذي (٣٠٤٠)، والبيهقي (٢٩٧/٧). قال الترمذي: “حسن صحيح غريب”.","grade":"حسن","chapter_ar":"باب ما جاء في تصالح الزوجين على عدم النفقة والقسمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (3040) and al-Bayhaqi (7/297). Al-Tirmidhi said: “Hasan sahih gharib.”","chapter_en":"What Has Been Reported About a Husband and Wife Reconciling Over Waiving Maintenance and Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":33,"content":{"translation":{"en":["Ibn ʿAbbas said: Sawdah feared that the Prophet ﷺ might divorce her, so she said: Do not divorce me; keep me, and give my day to ʿA’ishah. So he did that. Then the verse was revealed: “Then there is no sin upon them if they make terms of settlement between them, and settlement is best.” [al-Nisa’: 128]"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3040},{"key":"البیہقی","label":"البيهقي","number":297}]},{"num":6396,"demo":false,"sanad":"","matn":["عن ابن عباس، عن عمر أنه دخل على حفصة، فقال: يا بُنية لا يُغرّنك هذه التي أعجبها حسنها حبّ رسول الله ﷺ إياها - يريد عائشة - فقصصت على رسول الله ﷺ فتبسّم."],"takhrij":"متفق عليه: أخرجه البخاري (٥٢١٨)، ومسلم (٣١/١٤٧٩).","grade":"متفق عليه","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5218) and Muslim (1479:31).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["Ibn ʿAbbas narrated from ʿUmar that he entered upon Hafsah and said: O my daughter, do not let that one whose beauty and the Messenger of Allah’s love for her have impressed her deceive you — meaning ʿA’ishah. I related that to the Messenger of Allah ﷺ, and he smiled."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5218},{"key":"muslim","label":"مسلم","number":31}]},{"num":6397,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ قالت: أرسل أزواج النبي ﷺ فاطمة - بنت رسول الله ﷺ - إلى رسول الله ﷺ. فاستأذنت عليه وهو مضطجع معي في مِرْطي. فأذن لها. فقالت: يا رسول الله، إن أزواجك أرسلنني إليك يسألنك العدل في ابنة أبي قُحافة. وأنا ساكتة. قالت: فقال لها رسول الله ﷺ: (( أي بنية ألستِ تحبين ما أحب؟ )) فقالت: بلى. قال: (( فأحبي هذه )). قالت: فقامت فاطمة حين سمعت ذلك من رسول الله ﷺ. فرجعت إلى أزواج النبي ﷺ فأخبرتهن بالذي قالت، وبالذي قال لها رسول الله ﷺ. فقلن لها: ما نراك أغنيتِ عنا من شيء. فارجعي إلى رسول الله ﷺ فقولي له: إن أزواجك ينشدنك العدل في ابنة أبي قحافة. فقالت فاطمة: والله لا أكلمه فيها أبدا. قالت عائشة: فأرسل أزواج النبي ﷺ زينب بنت جحش - زوج النبي ﷺ - وهي التي كانت تُساميني منهن في المنزلة عند رسول الله ﷺ - ولم أر امرأة قط خيرا في الدين من زينب، وأتقى لله، وأصدق حديثا، وأوصل للرحم، وأعظم صدقة، وأشد ابتذالا لنفسها في العمل الذي تصدق به، وتقرب به إلى الله تعالى، ما عدا سَوْرةً من حدّة كانت فيها، تُسرع منها الفَيْئَة. قالت: فاستأذنت على رسول الله ﷺ ورسول الله ﷺ مع عائشة في مرطها، على الحالة التي دخلت فاطمة عليها وهو بها. فأذن لها رسول الله ﷺ، فقالت: يا رسول الله، إن أزواجك أرسلْنني إليك يسألنك العدل في ابنة أبي قُحافة. قالت: ثم وقعت بي، فاستطالت علي، وأنا أرقب رسول الله ﷺ، وأرقب طرفه، هل يأذن لي فيها. قالت: فلم تبرح زينب حتى عرفت أن رسول الله ﷺ لا يكره أن أنتصر. قالت: فلما وقعت بها لم أنشبها حين أنحيت عليها. قالت: فقال رسول الله ﷺ وتبسم: (( إنها ابنة أبي بكر ))."],"takhrij":"صحيح: رواه مسلم (٢٤٤٢).","grade":"صحيح","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2442).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: The wives of the Prophet ﷺ sent Fatimah, the daughter of the Messenger of Allah ﷺ, to the Messenger of Allah ﷺ. She asked permission to enter while he was lying with me under my wrap, and he permitted her. She said: O Messenger of Allah, your wives have sent me to ask you to be fair regarding the daughter of Abu Quhafah. I remained silent. The Messenger of Allah ﷺ said to her: “O my daughter, do you not love whom I love?” She said: Yes. He said: “Then love this one.” So Fatimah got up when she heard that from the Messenger of Allah ﷺ. She returned to the wives of the Prophet ﷺ and informed them of what she had said and what the Messenger of Allah ﷺ had said to her. They said to her: We do not think you helped us at all. Go back to the Messenger of Allah ﷺ and tell him: Your wives ask you for fairness regarding the daughter of Abu Quhafah. Fatimah said: By Allah, I will never speak to him about her again. ʿA’ishah said: Then the wives of the Prophet ﷺ sent Zaynab bint Jahsh, the wife of the Prophet ﷺ, and she was the one among them who rivaled me in standing with the Messenger of Allah ﷺ. I never saw a woman better in religion than Zaynab, more mindful of Allah, more truthful in speech, more dutiful to kinship ties, greater in charity, and more willing to exert herself in deeds by which she gave charity and sought nearness to Allah the Exalted — except for some sharpness in her nature from which she would quickly return. She asked permission to enter upon the Messenger of Allah ﷺ while he was with ʿA’ishah under her wrap, in the same condition in which Fatimah had found him, and the Messenger of Allah ﷺ gave her permission. She said: O Messenger of Allah, your wives have sent me to ask you to be fair regarding the daughter of Abu Quhafah. Then she began attacking me and speaking at length against me, while I watched the Messenger of Allah ﷺ and watched his eyes to see whether he would allow me to answer her. Zaynab did not stop until I knew that the Messenger of Allah ﷺ would not dislike my defending myself. Then once I turned on her, I quickly silenced her. The Messenger of Allah ﷺ smiled and said: “She is the daughter of Abu Bakr.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2442}]},{"num":6398,"demo":false,"sanad":"","matn":["عن عائشة: أن نساء رسول الله ﷺ كن حزبين، فحزب فيه عائشة وحفصة وصفية وسودة، والحزب الآخر أم سلمة وسائر نساء رسول الله ﷺ. وكان المسلمون قد علموا حبَّ رسول الله ﷺ لعائشة، فإذا كانت عند أحدهم هدية يريد أن يهديها إلى رسول الله ﷺ أخرها، حتى إذا كان رسول الله ﷺ في بيت عائشة بعث صاحب الهدية إلى رسول الله في بيت عائشة. فكلم حزب أم سلمة، فقلن لها: كلمي رسول الله ﷺ يكلم الناس، فيقول: من أراد أن يهدي إلى رسول الله ﷺ هدية فليهدها إليه حيث كان من بيوت نسائه. فكلمته أم سلمة بما قلن، فلم يقل لها شيئا، فسألنها، فقالت: ما قال لي شيئا. فقلن لها: فكلميه. قالت: فكلمته حين دار إليها أيضا، فلم يقل لها شيئا. فسألنها فقالت: ما قال لي شيئا. فقلن لها: كلميه حتى يكلمك. فدار إليها فكلمته، فقال لها: (( لا تؤذيني في عائشة، فإن الوحي لم يأتني وأنا في ثوب امرأة إلا عائشة )). قالت: فقالت: أتوب إلى الله من أذاك يا رسول الله. ثم إنهن دعون فاطمة بنت رسول الله ﷺ، فأرسلت إلى رسول الله ﷺ تقول: إن نساءك ينشدنك الله العدل في بنت أبي بكر. فكلمته فقال: (( يا بنية ألا تحبين ما أحب؟ )) قالت: بلى. فرجعت إليهن فأخبرتهن. فقلن لها: ارجعي إليه. فأبت أن ترجع. فأرسلن زينب بنت جحش، فأتته فأغلظت، وقالت: إن نساءك ينشدنك الله العدل في بنت ابن أبي قحافة. فرفعت صوتها حتى تناولت عائشة وهي قاعدة فسبتها، حتى إن رسول الله ﷺ لينظر إلى عائشة هل تكلم؟ قال: فتكلمت عائشة ترد على زينب حتى أسكتتها. قالت: فنظر النبي ﷺ إلى عائشة، وقال: (( إنها بنت أبي بكر ))."],"takhrij":"صحيح: رواه البخاري (٢٥٨١).","grade":"صحيح","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2581).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah said: The wives of the Messenger of Allah ﷺ were two parties. One party included ʿA’ishah, Hafsah, Safiyyah, and Sawdah; and the other party was Umm Salamah and the rest of the wives of the Messenger of Allah ﷺ. The Muslims knew of the Messenger of Allah’s love for ʿA’ishah, so if one of them had a gift he wanted to present to the Messenger of Allah ﷺ, he would delay it until the Messenger of Allah ﷺ was in the house of ʿA’ishah. Then the giver would send the gift to the Messenger of Allah while he was in the house of ʿA’ishah. The party of Umm Salamah spoke to her and said: Speak to the Messenger of Allah ﷺ so that he may tell the people: Whoever wants to give a gift to the Messenger of Allah ﷺ should give it to him wherever he may be among the houses of his wives. Umm Salamah spoke to him with what they had said, but he said nothing to her. They asked her, and she said: He said nothing to me. They said: Speak to him again. She said: So I spoke to him again when it was her turn, and he said nothing to me. They asked her, and she said: He said nothing to me. They said: Keep speaking to him until he answers you. So when it was again her turn, she spoke to him, and he said to her: “Do not hurt me concerning ʿA’ishah, for revelation has never come to me while I was under the covering of any woman except ʿA’ishah.” She said: So Umm Salamah said: I repent to Allah from hurting you, O Messenger of Allah. Then they called Fatimah, the daughter of the Messenger of Allah ﷺ, and she sent word to the Messenger of Allah ﷺ saying: Your wives ask you by Allah to be fair regarding the daughter of Abu Bakr. He said to her: “O my daughter, do you not love whom I love?” She said: Yes. Then she returned to them and informed them. They said to her: Go back to him. But she refused to return. Then they sent Zaynab bint Jahsh, who came and spoke harshly, saying: Your wives ask you by Allah to be fair regarding the daughter of Ibn Abi Quhafah. She raised her voice until she turned on ʿA’ishah while she was sitting and insulted her, while the Messenger of Allah ﷺ was looking at ʿA’ishah to see whether she would respond. Then ʿA’ishah answered Zaynab until she silenced her. The Prophet ﷺ looked at ʿA’ishah and said: “She is the daughter of Abu Bakr.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2581}]},{"num":6399,"demo":false,"sanad":"","matn":["عن عائشة قالت: ما علمتُ حتى دخلتْ عليّ زينب بغير إذن، وهي غضبى، ثم قالت: يا رسول اللَّه، أحسبك إذا قلّبت لك بُنيّةُ أبي بكر ذُرَيْعَتَيْها؟ ثم أقبلتْ عليّ، فأعرضتُ عنها، حتى قال النبي ﷺ: (( دونك فانتصري )). فأقبلتُ عليها حتى رأيتُها وقد يبس ريقُها في فيها، ما تردُّ عليَّ شيئًا، فرأيت النبي ﷺ يتهلَّلُ وجهه."],"takhrij":"حسن: رواه ابن ماجه (١٩٨١)، والإمام أحمد (٢٤٦٢٠)، والبخاري في الأدب المفرد (٥٥٨).","grade":"حسن","chapter_ar":"باب جواز حب الرجل بعض زوجاته أكثر من بعض","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1981), Imam Ahmad (24620), and al-Bukhari in al-Adab al-Mufrad (558).","chapter_en":"The Permissibility of a Man Loving Some of His Wives More Than Others","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":34,"content":{"translation":{"en":["ʿA’ishah said: Before I realized it, Zaynab entered upon me without permission while she was angry. Then she said: O Messenger of Allah, is it enough for you that the young daughter of Abu Bakr waves her hands in front of you? Then she turned against me. I ignored her until the Prophet ﷺ said: “Go ahead and defend yourself.” So I turned on her until I saw that the saliva in her mouth had dried up and she was unable to answer me at all. Then I saw the Prophet’s face light up with joy."]},"buhuth":{"ar":["وقولها: (( ذُرَيْعَتَيْها )) تصغير ذراع."],"en":["Her word “dhurayʿatayha” is the diminutive form of dhiraʿ (arm)."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1981},{"key":"الامام_احمد","label":"الإمام أحمد","number":24620},{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":558},{"key":"ahmad","label":"مسند الإمام أحمد","number":24620,"n":24620}]},{"num":6400,"demo":false,"sanad":"","matn":["عن عائشة أن النبي ﷺ كان يمكث عند زينب بنت جحش ويشرب عندها عسلاً، فتواصيت أنا وحفصة أن أيتنا دخل عليها النبي ﷺ فلتقل: إني أجد منك ريح مغافير، أكلت مغافير؟ فدخل على إحداهما، فقالت له ذلك، فقال: (( بل شربتُ عسلاً عند زينب بنت جحش، ولن أعود له )). فنزلت: ( يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ ) [التحريم: ١] إلى قوله: ( إِن تَتُوبَا إِلَى اللَّهِ ) [التحريم: ٤] لعائشة وحفصة، ( وَإِذْ أَسَرَّ النَّبِيُّ إِلَىٰ بَعْضِ أَزْوَاجِهِ ) [التحريم: ٣] لقوله: (( بل شربت عسلاً ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٦٧)، ومسلم (٢٠:١٤٧٤).","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5267) and Muslim (1474:20).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: The Prophet ﷺ used to stay with Zaynab bint Jahsh and drink honey at her house. So Hafsah and I agreed that whichever of us the Prophet ﷺ entered upon should say: I smell on you the odor of maghafir; have you eaten maghafir? He entered upon one of them, and she said that to him. He said: “Rather, I drank honey at the house of Zaynab bint Jahsh, and I will never return to it.” Then the verse was revealed: “O Prophet, why do you forbid what Allah has made lawful for you…” [al-Tahrim: 1] up to His saying: “If you both repent to Allah…” [al-Tahrim: 4] referring to ʿA’ishah and Hafsah, and “And when the Prophet confided a statement to one of his wives…” [al-Tahrim: 3] referring to his saying: “Rather, I drank honey.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5267},{"key":"muslim","label":"مسلم","number":20}]},{"num":6401,"demo":false,"sanad":"","matn":["عن عائشة قالت: كان رسول الله ﷺ إذا خرج، أقرع بين نسائه، فطارت القرعة على عائشة وحفصة، فخرجتا معه جميعاً، وكان رسول الله ﷺ إذا كان بالليل، سار مع عائشة، يتحدث معها، فقالت حفصة لعائشة: ألا تركبين الليلة بعيري وأركب بعيرك، فتنظرين وأنظر؟ قالت: بلى. فركبت عائشة على بعير حفصة، وركبت حفصة على بعير عائشة. فجاء رسول الله ﷺ إلى جمل عائشة، وعليه حفصة، فسلّم ثم سار معها، حتى نزلوا، فافتقدته عائشةُ فغارتْ. فلما نزلوا جعلت تجعل رجلها بين الإذخر، وتقول: يا ربّ سلّط عليّ عقرباً أو حية تلدغني، رسولك ولا أستطيع أن أقول له شيئاً."],"takhrij":"متفق عليه: رواه البخاري (٥٢١١)، ومسلم (٢٤٤٥)، والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5211) and Muslim (2445). The wording is from Muslim.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: Whenever the Messenger of Allah ﷺ went out on a journey, he would cast lots among his wives. The lot fell to ʿA’ishah and Hafsah, so they both went with him. At night the Messenger of Allah ﷺ would travel with ʿA’ishah and speak with her. So Hafsah said to ʿA’ishah: Will you ride my camel tonight and I ride your camel, so you may look around and I may look around? She said: Yes. So ʿA’ishah rode on Hafsah’s camel, and Hafsah rode on ʿA’ishah’s camel. Then the Messenger of Allah ﷺ came to the camel of ʿA’ishah, but Hafsah was on it. He greeted her and traveled with her until they stopped. Then ʿA’ishah missed him and became jealous. When they stopped, she began putting her feet among the idhkhir grass and saying: O Lord, send against me a scorpion or a snake to bite me. He is Your Messenger, and I cannot say anything to him."]},"buhuth":{"ar":["وقولها: (( رسولك )) بالرفع على أنه خبر لمبتدأ محذوف تقديره: هو رسولك، ولا أستطيع أن أقول في حقه شيئاً، وكأنها خُدعت فدعت على نفسها لكثرة غيرتها على رسول الله ﷺ، ولم تقل في حفصة شيئاً؛ لأنها هي التي أجابتها طائعة فعادتْ على نفسها باللوم."],"en":["Her words “Your Messenger” are in the nominative, as the predicate of an omitted subject, meaning: He is Your Messenger, and I cannot say anything concerning him. It is as though she was overcome, so because of the intensity of her jealousy for the Messenger of Allah ﷺ, she ended up supplicating against herself and said nothing against Hafsah, since Hafsah had only done so after ʿA’ishah willingly agreed, so she turned the blame back upon herself."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5211},{"key":"muslim","label":"مسلم","number":2445}]},{"num":6402,"demo":false,"sanad":"","matn":["عن عائشة قالت: كان رسول الله ﷺ يحب العسل والحلواء، وكان إذا انصرف من العصر دخل على نسائه فيدنو من إحداهن، فدخل على حفصة بنت عمر فاحتبس أكثر ما كان يحتبس فغِرتُ فسألتُ عن ذلك، فقيل: أهدت لها امرأة من قومها عُكّةً من عسل، فسقت النبي ﷺ منه شربة، فقلتُ: أما والله لنحتالن له، فقلتُ لسودة بنت زمعة: إنه سيدنو منك فإذا دنا منك فقولي: أكلت مغافير؟ فإنه سيقول لك: لا، فقولي له: ما هذه الريح التي أجد منك؟ فإنه سيقول لك: سقتني حفصة شربة عسل، فقولي له: جرست نحلة العرفط، وسأقولُ ذلك، وقولي أنتِ يا صفية ذاك. قالت: تقول سودة: فو الله ما هو إلا أن قام على الباب فأردتُ أن أُباديه بما أمرتني به فرقا منك، فلما دنا منها قالت له سودة: يا رسول الله ﷺ أكلت مغافير؟ قال: (( لا )). قالت: فما هذه الريح التي أجد منك؟ قال: (( سقتني حفصة شربة عسل )). فقالت: جرست نحلة العرفط. فلما دار إلي قلت له نحو ذلك، فلما دار إلى صفية قالت له مثل ذلك، فلما دار إلى حفصة قالت: يا رسول الله ﷺ ألا أسقيك منه؟ قال: (( لا حاجة لي فيه )). قالت: تقول سودة: والله لقد حرَّمناه، قلت لها: اسكتي."],"takhrij":"متفق عليه: رواه البخاري (٥٢٦٨)، ومسلم (٢١:١٤٧٤). وقولها: “جرستْ”: أي أكلتْ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5268) and Muslim (1474:21). Her word “jarasat” means: it ate.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ loved honey and sweets. When he finished the ʿAsr prayer, he would go to his wives and draw near to one of them. He entered upon Hafsah bint ʿUmar and stayed longer than he usually stayed, so I became jealous and asked about that. It was said: A woman from her people had gifted her a small skin container of honey, and she gave the Prophet ﷺ a drink from it. I said: By Allah, we will devise a plan for him. So I said to Sawdah bint Zamʿah: He will come near you, and when he comes near you, say: “Have you eaten maghafir?” He will say to you: “No.” Then say to him: “What is this smell I notice from you?” He will say: “Hafsah gave me a drink of honey.” Then say to him: “The bee must have fed on the ʿurfut shrub.” I will say that too, and you too, O Safiyyah, say the same. Sawdah said: By Allah, as soon as he stood at the door I wanted to confront him with what you had instructed me, out of fear of you. When he drew near to her, Sawdah said: O Messenger of Allah, have you eaten maghafir? He said: “No.” She said: Then what is this smell I notice from you? He said: “Hafsah gave me a drink of honey.” She said: The bee must have fed on the ʿurfut shrub. Then when he came to me, I said something similar to him, and when he went to Safiyyah, she said the same to him. Then when he went to Hafsah, she said: O Messenger of Allah, shall I give you more of it to drink? He said: “I have no need for it.” Sawdah said: By Allah, we have made him forbid it. I said to her: Be quiet."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5268},{"key":"muslim","label":"مسلم","number":21}]},{"num":6403,"demo":false,"sanad":"","matn":["عن عائشة، أن رسول الله ﷺ خرج من عندها ليلا قالت: فغرتُ عليه فجاء فرأى ما أصنع فقال: (( مالكِ يا عائشة أغرتِ؟ )) فقلت: وما لي لا يُغار مثلي على مثلك؟ فقال رسول الله ﷺ: (( أقد جاءك شيطانكِ؟ )) قالت: يا رسول الله ﷺ أو معي شيطان؟ قال: (( نعم )). قلت: ومع كل إنسان؟ قال: (( نعم )). قلت: ومعك يا رسول الله؟ قال: (( نعم، ولكن ربي أعانني عليه حتى أسلم ))."],"takhrij":"صحيح: رواه مسلم (٢٨١٥).","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2815).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ went out from her at night. She said: I became jealous over him. Then he returned and saw what I was doing and said: “What is the matter, O ʿA’ishah? Have you become jealous?” I said: Why should someone like me not be jealous over someone like you? The Messenger of Allah ﷺ said: “Has your devil come to you?” She said: O Messenger of Allah, do I have a devil with me? He said: “Yes.” I said: And with every person? He said: “Yes.” I said: Even with you, O Messenger of Allah? He said: “Yes, but my Lord helped me against him until he submitted.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2815}]},{"num":6404,"demo":false,"sanad":"","matn":["عن عائشة قالت:","التمست رسول الله ﷺ، فأدخلت يدي في شعره.","فقال:","«قَدْ جَاءَكِ شَيْطَانُكِ».","فقلت:","أما لك شيطان؟","قال:","«بَلَى، وَلَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ»."],"takhrij":"صحيح: رواه النسائي (٣٩٦٠).","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (3960).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿĀʾishah reported:","I looked for the Messenger of Allah ﷺ and put my hand into his hair.","He said:","“Your devil has come to you.”","I asked:","“Do you also have a devil?”","He replied:","“Yes, but Allah helped me against him, so he submitted.”"]},"buhuth":{"ar":["وقولها: «فأدخلت يدي في شعره» لأعلم هل هي مبلولة بالغسل أو لا؟","وقوله: «جاءك شيطانك» أي أوقع عليك أني قد ذهبت إلى بعض أزواجي في نوبتك وليلتك."],"en":["Her statement, “I put my hand into his hair,” means that she wanted to determine whether his hair was wet from bathing or not.","His statement, “Your devil has come to you,” means that the devil caused her to think that he had gone to one of his other wives during her allotted turn and night."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3960}]},{"num":6405,"demo":false,"sanad":"","matn":["عن عائشة أنها قالت: ما غِرْتُ على امرأة لرسول الله ﷺ كما غرتُ على خديجة لكثرة ذكر رسول الله ﷺ إياها وثنائه عليها، وقد أُوحي إلى رسول الله ﷺ أن يبشّرها ببيتٍ لها في الجنة من قصب."],"takhrij":"متفق عليه: رواه البخاري (٥٢٢٩)، ومسلم (٢٤٣٥:٧٤)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5229) and Muslim (2435:74). The wording is from al-Bukhari.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: I was never jealous of any wife of the Messenger of Allah ﷺ as much as I was jealous of Khadijah, because the Messenger of Allah ﷺ mentioned her often and praised her greatly. And it was revealed to the Messenger of Allah ﷺ that he should give her glad tidings of a house for her in Paradise made of qasab."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5229},{"key":"muslim","label":"مسلم","number":2435}]},{"num":6406,"demo":false,"sanad":"","matn":["عن عائشة قالت: ألا أحدثكم عني وعن رسول الله ﷺ؟ قلنا: بلى. قالت: لما كانت ليلتي التي كان النبي ﷺ فيها عندي انقلب فوضع رداءه وخلع نعليه فوضعهما عند رجليه وبسط طرف إزاره على فراشه فاضطجع، فلم يلبث إلا ريثما ظن أن قد رقدت، فأخذ رداءه رويدًا، وانتعل رويدًا، وفتح الباب، فخرج ثم أجافه رويدًا، فجعلت درعي في رأسي، واختمرت، وتقنعت إزاري، ثم انطلقت على إثره حتى جاء البقيع، فقال: فأطال القيام ثم رفع يديه ثلاث مرات ثم انحرف فانحرفت، فأسرع فأسرعت، فهرول فهرولت، فأحضر فأحضرت، فسبقته، فدخلت فليس إلا أن اضطجعت، فدخل فقال: (( مالكِ يا عائشُ حشيا رابية؟ )) قالت: قلت: لا شيء. قال: (( لتخبريني أو ليخبرني اللطيف الخبير )). قالت: قلت: يا رسول الله ﷺ بأبي أنت وأمي، فأخبرته. قال: (( فأنتِ السواد الذي رأيتُ أمامي؟ )) قلت: نعم. فلهدني في صدري لهدة أوجعتني، ثم قال: (( أظننتِ أن يحيفَ الله عليك ورسوله؟ )) قالت: مهما يكتم الناس يعلمه الله، نعم. قال: (( فإن جبريل أتاني حين رأيتِ، فناداني فأخفاه منك، فأجبته فأخفيته منك، ولم يكن يدخل عليك وقد وضعتِ ثيابك، وظننت أن قد رقدتِ، فكرهت أن أوقظك، وخشيت أن تستوحشي، فقال: إن ربك يأمرك أن تأتي أهل البقيع فتستغفر لهم )). قالت: قلت: كيف أقول لهم يا رسول الله؟ قال: (( قولي: السلام على أهل الديار من المؤمنين والمسلمين، ويرحم الله المستقدمين منا والمستأخرين، وإنا إن شاء الله بكم للاحقون ))."],"takhrij":"صحيح: رواه مسلم (٩٧٤:١٠٣). قوله: (( حشيا )) بالشين: أي مرتفع النفس كما يحصل للمسرع في المشي. وقوله: (( رابية )) مرتفعة البطن. وقوله: (( يحيف الله عليك ورسوله )) من الحيف بمعنى الجور، أي أن يدخل الرسول في نوبتك على غيرك، وهذا أمر لا يمكن أن يحصل من النبي ﷺ الذي هو أسوة لجميع المؤمنين. وفيه دلالة على أن القسم عليه واجب، إذ لا يكون تركه جورًا إلا إذا كان واجبًا.","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (974:103). His word “hashyā” means, with the letter shīn: breathing heavily, as happens to one who walks quickly. “Rābiyah” means with the belly rising and falling. His words “that Allah and His Messenger would deal unjustly with you” come from ḥayf, meaning injustice — that the Messenger would go to another wife during your allotted turn. This is something impossible from the Prophet ﷺ, who is the example for all believers. This also indicates that division of turns was obligatory upon him, since abandoning it would not be called injustice unless it were obligatory.","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: Shall I not tell you about myself and the Messenger of Allah ﷺ? We said: Yes. She said: On my night, when the Prophet ﷺ was with me, he turned over, placed down his cloak, removed his sandals and placed them by his feet, spread the edge of his lower garment over his bed, and lay down. He stayed only until he thought I had fallen asleep. Then he took his cloak gently, put on his sandals gently, opened the door and went out, then closed it gently. I put my outer garment over my head, covered myself, and wrapped my waistcloth tightly, then went after him until he came to al-Baqiʿ. He stood for a long time, then raised his hands three times. Then he turned away, and I turned away. He hurried, and I hurried. He jogged, and I jogged. He went faster, and I went faster. Then I got there before him, entered, and had just lain down when he entered. He said: “What is the matter, O ʿA’ishah? Are you out of breath and heaving?” She said: I said: Nothing. He said: “You will tell me, or the Subtle, the All-Aware will tell me.” She said: I said: O Messenger of Allah, may my father and mother be sacrificed for you, and then I told him. He said: “So you were the dark figure I saw ahead of me?” I said: Yes. Then he struck me on the chest in a way that hurt me and said: “Did you think that Allah and His Messenger would deal unjustly with you?” She said: However much people hide, Allah knows it — yes. He said: “Jibril came to me when you saw me, and he called me quietly so that you would not hear, and I answered him quietly so that you would not hear. He would not enter upon you while you had taken off your clothes. I thought that you had gone to sleep, so I disliked waking you and feared that you might feel lonely. He said: Your Lord commands you to go to the people of al-Baqiʿ and seek forgiveness for them.” She said: I said: How should I speak to them, O Messenger of Allah? He said: “Say: Peace be upon the people of these dwellings from among the believers and Muslims. May Allah have mercy on those of us who have gone ahead and those who come later. And we, if Allah wills, will join you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":974}]},{"num":6407,"demo":false,"sanad":"","matn":["عن عائشة قالت: افتقدت النبي ﷺ ذات ليلة، فظننت أنه ذهب إلى بعض نسائه، فتحسست ثم رجعت، فإذا هو راكع أو ساجد يقول: (( سبحانك وبحمدك، لا إله إلا أنت )). فقلت: بأبي أنت وأمي، إني لفي شأن، وإنك لفي آخر."],"takhrij":"صحيح: رواه مسلم (٤٨٥).","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (485).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["ʿA’ishah said: I missed the Prophet ﷺ one night and thought that he had gone to one of his wives. So I began searching, then returned, and there he was bowing or prostrating, saying: “Glory be to You and praise be to You; there is no god but You.” So I said: May my father and mother be sacrificed for you — I was occupied with one matter while you were occupied with another."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":485}]},{"num":6408,"demo":false,"sanad":"","matn":["عن أنس قال: جاء زيد بن حارثة يشكو، فجعل النبي ﷺ يقول له: (( اتق الله وأمسك عليك زوجك )). قالت عائشة: لو كان رسول الله ﷺ كاتمًا شيئًا لكتم هذه. قال: فكانت زينب تفخر على أزواج النبي ﷺ تقول: زوّجكن أهاليكن، وزوّجني الله تعالى من فوق سبع سماوات."],"takhrij":"صحيح: رواه البخاري (٧٤٢٠).","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (7420).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Anas said: Zayd ibn Harithah came complaining, and the Prophet ﷺ kept saying to him: “Fear Allah and keep your wife.” ʿA’ishah said: If the Messenger of Allah ﷺ were to have concealed anything, he would have concealed this. Anas said: Zaynab used to boast to the wives of the Prophet ﷺ, saying: Your families married you off, but Allah married me from above seven heavens."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7420}]},{"num":6409,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: كان النبي ﷺ عند بعض نسائه، فأرسلت إحدى أمهات المؤمنين بصحفة فيها طعام، فضربت التي النبي ﷺ في بيتها يدَ الخادم، فسقطت الصحفة فانفلقت، فجمع النبي ﷺ فِلقَ الصحفة ثم جعل يجمع فيها الطعام الذي كان في الصحفة ويقول: (( غارت أمكم )). ثم حبس الخادم حتى أُتي بصحفة من عند التي هو في بيتها، فدفع الصحفة الصحيحة إلى التي كُسِرت صحفتُها، وأمسك المكسورة في بيت التي كُسرت فيه."],"takhrij":"صحيح: رواه البخاري (٥٢٢٥).","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5225).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ was with one of his wives when one of the Mothers of the Believers sent a bowl containing food. The wife in whose house the Prophet ﷺ was struck the servant’s hand, so the bowl fell and broke. The Prophet ﷺ gathered the broken pieces of the bowl and began collecting into it the food that had been in it, saying: “Your mother became jealous.” Then he kept the servant until another bowl was brought from the house of the wife with whom he was staying. He gave the sound bowl to the one whose bowl had been broken, and kept the broken one in the house where it had been broken."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5225}]},{"num":6410,"demo":false,"sanad":"","matn":["عن أم سلمة أنها أتت بطعام في صحفة لها إلى رسول الله ﷺ وأصحابه، فجاءت عائشة متزرة بكساء ومعها فهر، ففلقت به الصحفة، فجمع النبي ﷺ بين فلقتي الصحفة، ويقول: (( كلوا، غارت أمكم )) مرتين. ثم أخذ رسول الله ﷺ صحفة عائشة، فبعث بها إلى أم سلمة، وأعطى صحفة أم سلمة لعائشة."],"takhrij":"صحيح: رواه النسائي (٣٩٦٥).","grade":"صحيح","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3965).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Umm Salamah brought food in a bowl of hers to the Messenger of Allah ﷺ and his companions. Then ʿA’ishah came wrapped in a garment, carrying a stone, and she split the bowl with it. The Prophet ﷺ gathered the two broken pieces of the bowl together and said: “Eat; your mother has become jealous,” twice. Then the Messenger of Allah ﷺ took ʿA’ishah’s bowl and sent it to Umm Salamah, and gave Umm Salamah’s bowl to ʿA’ishah."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3965}]},{"num":6411,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( من الغيرة ما يحب الله، ومنها ما يكره الله، فأما ما يحب الله فالغيرة في الريبة، وأما ما يكره فالغيرة في غير ريبة ))."],"takhrij":"حسن: رواه ابن ماجه (١٩٩٦).","grade":"حسن","chapter_ar":"باب ما جاء في غيرة الضرائر ومنافستهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1996).","chapter_en":"What Has Been Reported About the Jealousy and Rivalry of Co-Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":35,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “Some jealousy is loved by Allah, and some of it is disliked by Allah. As for the jealousy that Allah loves, it is jealousy where there is reason for suspicion. As for the jealousy that Allah dislikes, it is jealousy where there is no reason for suspicion.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1996}]},{"num":6412,"demo":false,"sanad":"","matn":["عن عائشة قالت: لما ثقل رسول الله ﷺ واشتد به وجعه، استأذن أزواجه أن يمرض في بيتي، فأذنّ له، فخرج وهو بين الرجلين تخط رجلاه في الأرض، بين عباس بن عبد المطلب، وبين رجل آخر.","قال عبيد الله: فأخبرت عبد الله بالذي قالت عائشة، فقال لي عبد الله بن عباس: هل تدري من الرجل الآخر الذي لم تسمِّ عائشة؟ قال: قلت: لا، قال ابن عباس: هو علي."],"takhrij":"متفق عليه: رواه البخاري (٤٤٤٢)، ومسلم (٤١٨:٩١)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب استئذان الرجل نساءه أن يمرض عند إحداهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4442) and Muslim (418:91). The wording is from al-Bukhari.","chapter_en":"A Man Seeking His Wives’ Permission to Be Nursed During Illness in the House of One of Them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":36,"content":{"translation":{"en":["ʿA’ishah said: When the Messenger of Allah ﷺ became seriously ill and his pain intensified, he sought permission from his wives to be nursed in my house, and they gave him permission. So he went out between two men, his feet dragging on the ground, between al-ʿAbbas ibn ʿAbd al-Muttalib and another man.","ʿUbaydullah said: I informed ʿAbdullah of what ʿA’ishah had said, and ʿAbdullah ibn ʿAbbas said to me: Do you know who the other man was whom ʿA’ishah did not name? I said: No. Ibn ʿAbbas said: It was ʿAli."]},"buhuth":{"ar":["وعند مسلم قالت: (( أول ما اشتكى رسول الله ﷺ في بيت ميمونة، فاستأذن أزواجه أن يمرض في بيتها ))."],"en":["And in Muslim she said: “The Messenger of Allah ﷺ first became ill in the house of Maymunah, then he sought permission from his wives to be nursed in my house.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4442},{"key":"muslim","label":"مسلم","number":418}]},{"num":6413,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ أن رسول الله ﷺ كان يسأل في مرضه الذي مات فيه: (( أين أنا غدًا؟ أين أنا غدًا؟ )) يريد يوم عائشة، فأذن له أزواجه يكون حيث شاء، فكان في بيت عائشة حتى مات عندها.","قالت عائشة: فمات في اليوم الذي كان يدور عليّ فيه في بيتي، فقبضه الله وإن رأسه بين نحري وسحري، وخالط ريقه ريقي."],"takhrij":"متفق عليه: رواه البخاري (٥٢١٧)، ومسلم (٢٤٤٣).","grade":"متفق عليه","chapter_ar":"باب استئذان الرجل نساءه أن يمرض عند إحداهن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5217) and Muslim (2443).","chapter_en":"A Man Seeking His Wives’ Permission to Be Nursed During Illness in the House of One of Them","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":36,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: During the illness in which he died, the Messenger of Allah ﷺ would ask: “Where will I be tomorrow? Where will I be tomorrow?” wanting the day of ʿA’ishah. So his wives gave him permission to stay wherever he wished, and he remained in the house of ʿA’ishah until he died there.","She said: He died on the day that was mine, in my house. Allah took his soul while his head was between my chest and my throat, and his saliva mixed with mine."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5217},{"key":"muslim","label":"مسلم","number":2443}]},{"num":6414,"demo":false,"sanad":"","matn":["عن أنس قال: من السنة إذا تزوج الرجل البكر على الثيب أقام عندها سبعًا وقسم، وإذا تزوج الثيب على البكر أقام عندها ثلاثًا ثم قسم.","قال أبو قلابة: ولو شئت لقلت إن أنسًا رفعه إلى النبي ﷺ."],"takhrij":"متفق عليه: رواه البخاري (٥٢١٤)، ومسلم (١٤٦١:٤٥)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5214) and Muslim (1461:45). The wording is from al-Bukhari.","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["Anas said: It is from the Sunnah that when a man marries a virgin while already married to a previously married woman, he stays with her for seven days and then begins division. And if he marries a previously married woman while already married to a virgin, he stays with her for three days and then begins division.","Abu Qilabah said: If I wished, I could say that Anas attributed it to the Prophet ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5214},{"key":"muslim","label":"مسلم","number":1461}]},{"num":6415,"demo":false,"sanad":"","matn":["عن أنس قال: قال رسول الله ﷺ: (( إن للثيب ثلاثًا، وللبكر سبعًا ))."],"takhrij":"صحيح: رواه ابن ماجه (١٩١٦)، والدارمي (٢٢٥٥)، وابن حبان في صحيحه (٤٢٠٨).","grade":"صحيح","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (1916), al-Darimi (2255), and Ibn Hibban in his Sahih (4208).","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “The previously married woman has three days, and the virgin has seven.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1916},{"key":"darimi","label":"الدارمي","number":2255},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4208}]},{"num":6416,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: لما أخذ رسول الله ﷺ صفية أقام عندها ثلاثًا."],"takhrij":"صحيح: رواه أبو داود (٢١٢٣).","grade":"صحيح","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2123).","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["Anas ibn Malik said: When the Messenger of Allah ﷺ took Safiyyah, he stayed with her for three days."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2123}]},{"num":6417,"demo":false,"sanad":"","matn":["عن عبد الملك بن أبي بكر بن عبد الرحمن بن الحارث بن هشام، عن أبيه، عن أم سلمة، أن رسول الله ﷺ لما تزوج أم سلمة أقام عندها ثلاثًا وقال: (( إنه ليس بك على أهلك هوان، إن شئت سبّعت لكِ، وإن سبّعت لكِ سبّعت لنسائي ))."],"takhrij":"صحيح: رواه مسلم (١٤٦٠:٤١).","grade":"صحيح","chapter_ar":"باب إقامة الزوج سبعًا عند البكر على الثيب، وثلاثًا عند الثيب على البكر، ثم بدء القسم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1460:41).","chapter_en":"The Husband Staying Seven Days with a Virgin over a Previously Married Wife, and Three Days with a Previously Married Wife over a Virgin, Then Beginning the Regular Division","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":37,"content":{"translation":{"en":["ʿAbd al-Malik ibn Abi Bakr ibn ʿAbd al-Rahman ibn al-Harith ibn Hisham narrated from his father, from Umm Salamah, that when the Messenger of Allah ﷺ married Umm Salamah, he stayed with her for three days and said: “You are not held in low esteem by your husband. If you wish, I will stay seven days with you; but if I stay seven days with you, I will also stay seven days with my other wives.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1460}]},{"num":6418,"demo":false,"sanad":"","matn":["عن عبد الله بن زمعة أنه سمع النبي ﷺ يخطب وذكر الناقة، والذي عقر، فقال رسول الله ﷺ: ( إِذِ انْبَعَثَ أَشْقَاهَا ) [الشمس: ١٢] انبعث لها رجل عزيز عارم منيع في رهطه، مثل أبي زمعة. وذكر النساء فقال: (( يعمد أحدكم يجلد امرأته جلدَ العبد، فلعله يضاجعها من آخر يومه )). ثم وعظهم في ضحكهم من الضرطة وقال: (( لِمَ يضحك أحدكم مما يفعل؟ ))."],"takhrij":"متفق عليه: رواه البخاري (٤٩٤٢)، ومسلم (٢٨٥٥). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4942) and Muslim (2855). The wording is from al-Bukhari.","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["ʿAbdullah ibn Zamʿah said that he heard the Prophet ﷺ delivering a sermon and he mentioned the she-camel and the one who hamstrung it. The Messenger of Allah ﷺ said concerning the verse, “When the most wretched of them rose up” [al-Shams: 12]: A powerful, fierce man arose against it, strong among his people, like Abu Zamʿah. Then he mentioned women and said: “One of you beats his wife like a slave, then perhaps he will sleep with her at the end of the same day.” Then he admonished them about laughing at flatulence and said: “Why does one of you laugh at what he himself does?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4942},{"key":"muslim","label":"مسلم","number":2855}]},{"num":6419,"demo":false,"sanad":"","matn":["عن عائشة قالت: ما ضرب رسول الله ﷺ شيئًا قط بيده، ولا امرأة، ولا خادمًا، إلا أن يجاهد في سبيل الله، وما نيل منه شيء قط، فينتقم من صاحبه، إلا أن يُنتهك شيء من محارم الله عز وجل، فينتقم لله عز وجل."],"takhrij":"صحيح: رواه مسلم (٢٣٢٨).","grade":"صحيح","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2328).","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ never struck anything with his hand at all — neither a woman nor a servant — except while striving in the path of Allah. And nothing was ever done against him personally such that he took revenge on the one who did it, unless one of the sacred limits of Allah was violated, in which case he would take revenge for the sake of Allah, Mighty and Majestic."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2328}]},{"num":6420,"demo":false,"sanad":"","matn":["عن إياس بن أبي ذباب قال: قال رسول الله ﷺ:","«لَا تَضْرِبُوا إِمَاءَ اللَّهِ».","قال: فذئر النساء، وساءت أخلاقهن على أزواجهن.","فقال عمر بن الخطاب:","ذئر النساء، وساءت أخلاقهن على أزواجهن منذ نهيت عن ضربهن.","فقال النبي ﷺ:","«فَاضْرِبُوا».","فضرب الناس نساءهم تلك الليلة، فأتى نساء كثير يشتكين الضرب.","فقال النبي ﷺ حين أصبح:","«لَقَدْ طَافَ بِآلِ مُحَمَّدٍ اللَّيْلَةَ سَبْعُونَ امْرَأَةً، كُلُّهُنَّ يَشْتَكِينَ الضَّرْبَ، وَأَيْمُ اللَّهِ لَا تَجِدُونَ أُولَئِكَ خِيَارَكُمْ»."],"takhrij":"صحيح: رواه أبو داود (٢١٤٦)، وابن ماجه (١٩٨٥)، وصححه ابن حبان (٤١٨٩)، والحاكم (٢/١٨٨-١٩١).","grade":"صحيح","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2146) and Ibn Mājah (1985), and authenticated by Ibn Ḥibbān (4189) and al-Ḥākim (2/188–191).","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["Iyās ibn Abī Dhubāb reported that the Messenger of Allah ﷺ said:","“Do not strike the female servants of Allah.”","He said: The women then became emboldened, and their conduct toward their husbands worsened.","ʿUmar ibn al-Khaṭṭāb said:","“The women have become emboldened, and their conduct toward their husbands has worsened since you prohibited striking them.”","The Prophet ﷺ then said:","“Then strike them.”","So some men struck their wives that night, and many women came complaining about being struck.","The following morning, the Prophet ﷺ said:","“Seventy women have gone around the household of Muhammad tonight, all of them complaining about being struck. By Allah, you will not find those men to be the best among you.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2146},{"key":"ibnmajah","label":"ابن ماجه","number":1985},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4189},{"key":"hakim","label":"الحاكم","number":2},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2060,"n":2057}]},{"num":6421,"demo":false,"sanad":"","matn":["عن علي أن امرأة الوليد بن عقبة أتت النبي ﷺ فقالت: يا رسول الله ﷺ إن الوليد يضربها، فقال لها: (( قولي له: قد أجارني )). قال علي: فلم تلبث إلا يسيرا حتى رجعت فقالت: ما زادني إلا ضربا، فأخذ هُدبة من ثوبه، فدفعها إليها وقال: (( قولي له: إن رسول الله ﷺ قد أجارني )). فلم تلبث إلا يسيرا حتى رجعت فقالت: ما زادني إلا ضربا. فرفع يديه وقال: (( اللهم عليك الوليد، أثِمَ بي مرتين ))."],"takhrij":"حسن: رواه الإمام أحمد (١٣٠٤) وأبو يعلى (٣٥١) والبزار -كشف الأستار (٧٦٧).","grade":"حسن","chapter_ar":"باب النهي عن ضرب النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (1304), Abū Yaʿlā (351), and al-Bazzār in Kashf al-Astār (767).","chapter_en":"The Prohibition of Striking Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":38,"content":{"translation":{"en":["ʿAlī said: The wife of al-Walīd ibn ʿUqbah came to the Prophet ﷺ and said: O Messenger of Allah, al-Walīd beats me. So he said to her, “Say to him: The Messenger of Allah has granted me protection.” ʿAlī said: She stayed away only a little while, then returned and said: He only beat me more. So the Prophet took a fringe from his garment and gave it to her and said, “Say to him: The Messenger of Allah ﷺ has granted me protection.” She stayed away only a little while, then returned and said: He only beat me more. So he raised his hands and said, “O Allah, deal with al-Walīd. He has sinned against me twice.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":1304},{"key":"ابو_یعلی","label":"أبو يعلى","number":351},{"key":"البزار_کشف_الاستار","label":"البزار -كشف الأستار","number":767},{"key":"ahmad","label":"مسند الإمام أحمد","number":1304,"n":1304},{"key":"sh12520","label":"مسند أبي يعلى","number":351,"n":349}]},{"num":6422,"demo":false,"sanad":"","matn":["عن جابر، عن النبي ﷺ قال في خطبة حجة الوداع:","«اتَّقُوا اللَّهَ فِي النِّسَاءِ، فَإِنَّكُمْ أَخَذْتُمُوهُنَّ بِأَمَانِ اللَّهِ، وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ، وَلَكُمْ عَلَيْهِنَّ أَنْ لَا يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ، فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ»."],"takhrij":"صحيح: رواه مسلم (١٢١٨).","grade":"صحيح","chapter_ar":"باب ما جاء في النشوز","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"What Has Been Related Regarding Marital Rebellion","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":39,"content":{"translation":{"en":["Jābir reported that the Prophet ﷺ said during the sermon of the Farewell Pilgrimage:","“Fear Allah regarding women, for you have taken them under the trust of Allah and have made marital relations with them lawful by the word of Allah.","Your right over them is that they do not allow anyone whom you dislike onto your bedding. If they do that, then strike them in a manner that is not severe.”"]},"intro":{"ar":["قال الله تعالى: ( الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ وَبِمَا أَنْفَقُوا مِنْ أَمْوَالِهِمْ ۚ فَالصَّالِحَاتُ قَانِتَاتٌ حَافِظَاتٌ لِّلْغَيْبِ بِمَا حَفِظَ اللَّهُ ۚ وَاللَّاتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ ۖ فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا ۗ إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا ۝ وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا إِنْ يُرِيدَا إِصْلَاحًا ) [النساء: ٣٤-٣٥]"],"en":["Allah the Exalted said: “Men are caretakers of women because Allah has given one more than the other and because they spend from their wealth. So righteous women are devoutly obedient, guarding in the husband’s absence what Allah would have them guard. As for those from whom you fear rebellion, admonish them, leave them in the beds, and strike them. But if they obey you, then do not seek a way against them. Indeed, Allah is Most High, Most Great. And if you fear a breach between them, appoint an arbiter from his family and an arbiter from her family, if they both desire reconciliation…” [Surat al-Nisā’, 34–35]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1218}]},{"num":6423,"demo":false,"sanad":"","matn":["عن علي قال: لما تزوجت فاطمة فقلت: يا رسول الله ﷺ ابنِ لي، قال: (( أعطها شيئا )). قلت: ما عندي من شيء. قال: (( فأين درعك الحطمية؟ )). قلت: هي عندي. قال: (( فأعطها إياه ))."],"takhrij":"صحيح: رواه النسائي (٣٣٧٥) والبيهقي (٢٥٢/٧).","grade":"صحيح","chapter_ar":"باب ما جاء في النشوز","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3375) and al-Bayhaqī (7/252).","chapter_en":"What Has Been Related Regarding Marital Rebellion","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":39,"content":{"translation":{"en":["ʿAlī said: When I married Fāṭimah, I said: O Messenger of Allah, permit me to consummate the marriage. He said, “Give her something.” I said: I do not have anything. He said, “Where is your Ḥuṭamiyyah armor?” I said: I have it. He said, “Then give it to her.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3375},{"key":"البیہقی","label":"البيهقي","number":252}]},{"num":6424,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس قال: لما تزوج علي فاطمة قال له رسول الله ﷺ: (( أعطها شيئا )). قال: ما عندي شيء. قال: (( أين درعك الحطمية؟ ))."],"takhrij":"صحيح: رواه أبو داود (٢١٢٥) والنسائي (٣٣٧٦).","grade":"صحيح","chapter_ar":"باب لا يدخل بأهله قبل أن يُعطيها شيئا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2125) and al-Nasā’ī (3376).","chapter_en":"A man should not enter upon his wife before giving her something","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":40,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: When ʿAlī married Fāṭimah, the Messenger of Allah ﷺ said to him, “Give her something.” He said: I do not have anything. He said, “Where is your Ḥuṭamiyyah armor?”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2125},{"key":"nasai","label":"النسائي","number":3376}]},{"num":6425,"demo":false,"sanad":"","matn":["عن المسور بن مخرمة أن علي بن أبي طالب خطب بنت أبي جهل على فاطمة، فسمعت رسول الله ﷺ وهو يخطب الناس في ذلك، على منبره هذا، وأنا يومئذ محتلم، فقال: (( إن فاطمة مني، وإني أتخوف أن تفتن في دينها )). قال: ثم ذكر صهرا له من بني عبد شمس، فأثنى عليه في مصاهرته إياه فأحسن. قال: (( حدثني فصدقني، ووعدني فأوفى لي. وإني لست أحرم حلالاً ولا أحل حراما. ولكن والله لا تجتمع بنت رسول الله ﷺ وبنت عدو الله مكانا واحدا أبدا ))."],"takhrij":"متفق عليه: رواه البخاري (٣١١٠) ومسلم (٢٤٤٩:٩٥).","grade":"متفق عليه","chapter_ar":"باب ذبّ الرجل عن ابنته في الغيرة وطلب الإنصاف لها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3110) and Muslim (2449:95).","chapter_en":"A Man Defending His Daughter Out of Protective Jealousy and Seeking Fairness for Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":41,"content":{"translation":{"en":["Al-Miswar ibn Makhramah said: ʿAlī ibn Abī Ṭālib proposed to the daughter of Abū Jahl while married to Fāṭimah. I heard the Messenger of Allah ﷺ addressing the people about that from this pulpit of his, and at that time I had reached puberty. He said: “Fāṭimah is a part of me, and I fear that she may be tested in her religion.” Then he mentioned a son-in-law of his from Banū ʿAbd Shams and praised him highly regarding his marriage tie with him. He said: “He spoke to me and told me the truth, and he promised me and fulfilled his promise. I do not forbid what is lawful, nor do I make lawful what is forbidden. But by Allah, the daughter of the Messenger of Allah ﷺ and the daughter of the enemy of Allah will never be joined together in one place.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3110},{"key":"muslim","label":"مسلم","number":2449}]},{"num":6426,"demo":false,"sanad":"","matn":["عن المسور بن مخرمة قال:","سمعت رسول الله ﷺ يقول وهو على المنبر:","«إِنَّ بَنِي هِشَامِ بْنِ الْمُغِيرَةِ اسْتَأْذَنُوا فِي أَنْ يُنْكِحُوا ابْنَتَهُمْ عَلِيَّ بْنَ أَبِي طَالِبٍ، فَلَا آذَنُ، ثُمَّ لَا آذَنُ، ثُمَّ لَا آذَنُ، إِلَّا أَنْ يُرِيدَ ابْنُ أَبِي طَالِبٍ أَنْ يُطَلِّقَ ابْنَتِي، وَيَنْكِحَ ابْنَتَهُمْ؛ فَإِنَّمَا هِيَ بَضْعَةٌ مِنِّي، يَرِيبُنِي مَا أَرَابَهَا، وَيُؤْذِينِي مَا آذَاهَا»."],"takhrij":"متفق عليه: رواه البخاري (٥٢٣٠)، ومسلم (٢٤٤٩/٩٣).","grade":"متفق عليه","chapter_ar":"باب ذبّ الرجل عن ابنته في الغيرة وطلب الإنصاف لها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5230) and Muslim (2449/93).","chapter_en":"A Man Defending His Daughter Out of Protective Jealousy and Seeking Fairness for Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":41,"content":{"translation":{"en":["Al-Miswar ibn Makhramah reported:","I heard the Messenger of Allah ﷺ say while standing on the pulpit:","“The family of Hishām ibn al-Mughīrah have sought permission to marry their daughter to ʿAlī ibn Abī Ṭālib. I do not give permission, then I do not give permission, then I do not give permission—unless Ibn Abī Ṭālib wishes to divorce my daughter and marry their daughter.","She is a part of me. Whatever troubles her troubles me, and whatever harms her harms me.”"]},"buhuth":{"ar":["وقوله: «ابنتهم» وهي ابنة أبي جهل، وهو عمرو بن هشام بن المغيرة، عدو الله ورسوله، وأخواه الحارث بن هشام وسلمة بن هشام أسلما عام الفتح، وحسن إسلامهما."],"en":["The words “their daughter” refer to the daughter of Abū Jahl, whose name was ʿAmr ibn Hishām ibn al-Mughīrah, the enemy of Allah and His Messenger. His two brothers, al-Ḥārith ibn Hishām and Salamah ibn Hishām, accepted Islam in the year of the Conquest, and their Islam was good."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5230},{"key":"muslim","label":"مسلم","number":2449}]},{"num":6427,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله أن النبي ﷺ رأى امرأة فأتى امرأته زينب، وهي تمعس منيئة لها، فقضى حاجته، ثم خرج إلى أصحابه فقال: (( إن المرأة تقبل في صورة شيطان، وتدبر في صورة شيطان، فإذا أبصر أحدكم امرأة فليأت أهله، فإن ذلك يرد ما في نفسه ))."],"takhrij":"صحيح: رواه مسلم (١٤٠٣). وفي رواية: (( فليعمد إلى امرأته فليواقعها، فإن ذلك يرد ما في نفسه )).","grade":"صحيح","chapter_ar":"باب ندب من رأى امرأة، فوقعت في نفسه أن يأتي امرأته أو جاريته فيقضي حاجته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1403). In another wording: “Then let him go intentionally to his wife and have intercourse with her, for that will repel what is in his heart.”","chapter_en":"Recommendation for one who sees a woman and feels desire to go to his wife or slave woman and fulfill his need","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":42,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: The Prophet ﷺ saw a woman, so he went to his wife Zaynab while she was tanning a hide for her, and he fulfilled his need. Then he came out to his companions and said: “A woman comes in the form of a devil and goes away in the form of a devil. So if one of you sees a woman, let him go to his wife, for that will repel what is in his heart.”"]},"buhuth":{"ar":["وقوله: (( تمعس منيئة لها )) المعس الدلك، والمنيئة هو أول دباغ الجلد."],"en":["His words “she was tamʿasu manī’atan lahā” mean: al-maʿs is rubbing, and al-manī’ah is the first stage of tanning the hide."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1403}]},{"num":6428,"demo":false,"sanad":"","matn":["عن أبي كبشة الأنصاري قال: كان رسول الله ﷺ جالسا في أصحابه، فدخل، ثم خرج وقد اغتسل. فقلنا: يا رسول الله ﷺ قد كان شيء؟ قال: (( أجل، قد مرت بي فلانة، فوقع في قلبي شهوة نساء، فأتيت بعض أزواجي فأصبتها، فكذلك فافعلوا، فإنه من أماثل أعمالكم إتيان الحلال ))."],"takhrij":"حسن: رواه الإمام أحمد (١٨٠٢٨) والطبراني في الكبير (٢٢/٣٣٨-٣٣٩) وفي الأوسط (٣٢٧٥).","grade":"حسن","chapter_ar":"باب ندب من رأى امرأة، فوقعت في نفسه أن يأتي امرأته أو جاريته فيقضي حاجته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (18028), al-Ṭabarānī in al-Kabīr (22/338–339), and in al-Awsaṭ (3275).","chapter_en":"Recommendation for one who sees a woman and feels desire to go to his wife or slave woman and fulfill his need","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":42,"content":{"translation":{"en":["Abū Kabshah al-Anṣārī said: The Messenger of Allah ﷺ was sitting among his companions. Then he went in, and later came out having bathed. So we said: O Messenger of Allah, did something happen? He said: “Yes. A certain woman passed by me, and desire for women came into my heart. So I went to one of my wives and had relations with her. So do likewise, for among your best deeds is coming to the lawful.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":18028},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":22},{"key":"وفی_الاوسط","label":"وفي الأوسط","number":3275},{"key":"ahmad","label":"مسند الإمام أحمد","number":18027,"n":18027}]},{"num":6429,"demo":false,"sanad":"","matn":["عن ابن عباس قال: سمعت النبي ﷺ يخطب يقول: (( لا يخلون رجل بامرأة إلا ومعها ذو محرم، ولا تسافر المرأة إلا مع ذي محرم )). فقام رجل فقال: يا رسول الله، إن امرأتي خرجت حاجّة، وإني اكتتبت في غزوة كذا وكذا. قال: (( انطلق فحجَّ مع امرأتك ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٣٣)، ومسلم (١٣٤١). والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5233) and Muslim (1341). The wording is from Muslim.","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["Ibn ʿAbbās said: I heard the Prophet ﷺ giving a sermon saying: “No man should be alone with a woman unless she has a mahram with her, and no woman should travel except with a mahram.” Then a man stood and said: O Messenger of Allah, my wife has gone out for Hajj, and I have enlisted in such-and-such expedition. He said: “Go and perform Hajj with your wife.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5233},{"key":"muslim","label":"مسلم","number":1341}]},{"num":6430,"demo":false,"sanad":"","matn":["عن عقبة بن عامر أن رسول الله ﷺ قال: (( إياكم والدخول على النساء )). فقال رجل من الأنصار: يا رسول الله، أفرأيت الحمو؟ قال: (( الحمو الموت ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٣٢)، ومسلم (٢١٧٢).","grade":"متفق عليه","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5232) and Muslim (2172).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir said that the Messenger of Allah ﷺ said: “Beware of entering upon women.” A man from the Anṣār said: O Messenger of Allah, what about the in-law? He said: “The in-law is death.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5232},{"key":"muslim","label":"مسلم","number":2172}]},{"num":6431,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص، أن نفراً من بني هاشم دخلوا على أسماء بنت عميس، فدخل أبو بكر الصديق - وهي تحته - فرآهم فكره ذلك، فذكر ذلك لرسول الله ﷺ وقال: لم أر إلا خيراً، فقال رسول الله ﷺ: (( إن الله قد برأها من ذلك )). ثم قام رسول الله ﷺ على المنبر فقال: (( لا يدخلن رجل بعد يومي هذا على مغيبة إلا ومعه رجل أو اثنان ))."],"takhrij":"صحيح: رواه مسلم (٢١٧٣).","grade":"صحيح","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2173).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ said: A group from Banū Hāshim entered upon Asmā’ bint ʿUmays. Then Abū Bakr al-Ṣiddīq entered — and she was his wife — and he disliked that. So he mentioned it to the Messenger of Allah ﷺ and said: I saw nothing but good. Then the Messenger of Allah ﷺ said: “Allah has declared her innocent of that.” Then the Messenger of Allah ﷺ stood upon the pulpit and said: “After this day, no man should enter upon a woman whose husband is absent unless he is accompanied by one or two men.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2173}]},{"num":6432,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول الله ﷺ: (( ألا لا يبيتن رجل عند امرأةٍ ثيّب، إلا أن يكون ناكحا، أو ذا محرم ))."],"takhrij":"صحيح: رواه مسلم (٢١٧١).","grade":"صحيح","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2171).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["Jābir said: The Messenger of Allah ﷺ said: “No man should spend the night with a previously married woman unless he is her husband or a mahram.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2171}]},{"num":6433,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس أن رجلا قدم من سفر، فقال له النبي ﷺ: (( نزلتَ على فلانة، وأغلقتَ عليك بابها )). قال: نعم، فكره ذلك النبي ﷺ."],"takhrij":"صحيح: رواه البزار - كشف الأستار (١٤٨٨).","grade":"صحيح","chapter_ar":"باب تحريم الخلوة بالأجنبية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bazzār in Kashf al-Astār (1488).","chapter_en":"The Prohibition of Seclusion with a Non-Mahram Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":43,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said that a man returned from a journey, and the Prophet ﷺ said to him: “You stayed with a certain woman and closed the door upon yourselves?” He said: Yes. So the Prophet ﷺ disliked that."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1488},{"key":"sh12862","label":"كشف الأستار عن زوائد البزار","number":1488,"n":1489}]},{"num":6434,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: جاءت امرأة من الأنصار إلى رسول الله ﷺ، قال: فخلا بها رسول الله ﷺ وقال: (( والذي نفسي بيده إنكم لأحب الناس إليَّ )) ثلاث مرات."],"takhrij":"صحيح: رواه البخاري (٥٢٣٤) ومسلم (٢٥٠٩:١٧٥). قوله: (( خلا بها )) أي: ابتعد عن جلس الناس.","grade":"صحيح","chapter_ar":"باب جواز الخلوة بالمرأة عند الحاجة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5234) and Muslim (2509:175). His words “he was alone with her” mean: he moved away from the gathering of people.","chapter_en":"The Permissibility of Private Conversation with a Woman When There Is a Need","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":44,"content":{"translation":{"en":["Anas ibn Mālik said: A woman from the Anṣār came to the Messenger of Allah ﷺ. He said: Then the Messenger of Allah ﷺ spoke privately with her and said, “By the One in Whose hand is my soul, you are the most beloved people to me,” three times."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5234},{"key":"muslim","label":"مسلم","number":2509}]},{"num":6435,"demo":false,"sanad":"","matn":["عن أم سلمة قالت: دخل عليَّ رسول الله ﷺ وعندي مخنث، فسمعته يقول لعبد الله بن أبي أمية أخي أم سلمة: يا عبد الله، أرأيت إن فتح الله عليكم الطائف غداً، فعليك بابنة غيلان، فإنها تقبل بأربع وتدبر بثمان. فقال النبي ﷺ: (( لا يدخلن هؤلاء عليكن ))."],"takhrij":"متفق عليه: رواه البخاري (٥٨٨٧) ومسلم (٢١٨٠).","grade":"متفق عليه","chapter_ar":"باب منع دخول المخنث على النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5887) and Muslim (2180).","chapter_en":"Preventing the Effeminate Man from Entering upon Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":45,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ entered upon me while an effeminate man was with me. I heard him saying to ʿAbdullāh ibn Abī Umayyah, the brother of Umm Salamah: O ʿAbdullāh, if Allah grants you victory over Ṭā’if tomorrow, then take the daughter of Ghaylān, for she comes with four and goes with eight. Then the Prophet ﷺ said: “These people must not enter upon you.”"]},"buhuth":{"ar":["قال أبو عبد الله البخاري: “(( تقبل بأربع )) يعني أربع عُكن بطنها، فهي تُقبل بهن، وقوله: (( تدبر بثمان )) يعني أطراف هذه العكن الأربع، لأنها محيطة بالجنبين حتى لحقت”. قلت: والعُكن هو الطي الذي في البطن من السمن."],"en":["Abū ʿAbdullāh al-Bukhārī said: “His words ‘she comes with four’ mean the four folds of her belly, so she comes with them; and his words ‘she goes with eight’ mean the ends of those four folds, because they extend around both sides until they meet.” I say: ʿukan are the folds in the belly caused by fatness."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5887},{"key":"muslim","label":"مسلم","number":2180}]},{"num":6436,"demo":false,"sanad":"","matn":["عن عائشة قالت: كان يدخل على أزواج رسول الله ﷺ مخنث، فكانوا يعدونه من غير أولي الإربة. قال: فدخل النبي ﷺ يوما، وهو عند بعض نسائه، وهو ينعت امرأة قال: إذا أقبلت أقبلت بأربع، وإذا أدبرت أدبرت بثمان. فقال النبي ﷺ: (( ألا أرى هذا يعرف ما هنا، لا يدخلنّ عليكن )). قالت: فحجبوه."],"takhrij":"صحيح: رواه مسلم (٢١٨١).","grade":"صحيح","chapter_ar":"باب منع دخول المخنث على النساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2181).","chapter_en":"Preventing the Effeminate Man from Entering upon Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":45,"content":{"translation":{"en":["ʿA’ishah said: An effeminate man used to enter upon the wives of the Messenger of Allah ﷺ, and they used to count him among those who had no desire for women. One day the Prophet ﷺ entered while he was with one of his wives, and he was describing a woman, saying: When she comes forward, she comes with four, and when she turns away, she turns away with eight. So the Prophet ﷺ said: “Do I not see that this one knows what is here? He must not enter upon you.” She said: So they screened him off."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2181}]},{"num":6437,"demo":false,"sanad":"","matn":["عن ابن عباس قال: لعن النبي ﷺ المخنثين من الرجال، والمترجلات من النساء. وقال: (( أخرجوهن من بيوتكم )). قال: فأخرج النبي ﷺ فلانا، وأخرج عمر فلانا."],"takhrij":"صحيح: رواه البخاري (٥٨٨٦). وفي رواية عنده (٥٨٨٥): (( المتشبهين من الرجال بالنساء، والمتشبهات من النساء بالرجال )).","grade":"صحيح","chapter_ar":"باب النهي عن التشبه بالنساء والعكس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5886). In another wording with him (5885): “the men who imitate women and the women who imitate men.”","chapter_en":"The Prohibition of Men Resembling Women and Women Resembling Men","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":46,"content":{"translation":{"en":["Ibn ʿAbbās said: The Prophet ﷺ cursed the effeminate men and the women who imitate men. And he said: “Expel them from your houses.” He said: So the Prophet ﷺ expelled a certain man, and ʿUmar expelled a certain man."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5886},{"key":"وفی_روایہ_عندہ","label":". وفي رواية عنده","number":5885}]},{"num":6438,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لعن رسول الله ﷺ الرجل يلبس لبسة المرأة، والمرأة تلبس لبسة الرجل."],"takhrij":"صحيح: رواه أبو داود (٤٠٩٨) وابن ماجه (١٩٠٣) وأحمد (٨٣٠٩) وصحّحه ابن حبان (٥٧٥١).","grade":"صحيح","chapter_ar":"باب النهي عن التشبه بالنساء والعكس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4098), Ibn Mājah (1903), and Aḥmad (8309), and authenticated by Ibn Ḥibbān (5751).","chapter_en":"The Prohibition of Men Resembling Women and Women Resembling Men","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":46,"content":{"translation":{"en":["Abū Hurairah said: The Messenger of Allah ﷺ cursed the man who wears women’s clothing and the woman who wears men’s clothing."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4098},{"key":"ibnmajah","label":"ابن ماجه","number":1903},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5751},{"key":"ahmad","label":"مسند الإمام أحمد","number":8309,"n":8309},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2888,"n":2885}]},{"num":6439,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول الله ﷺ: (( ثلاثة لا يدخلون الجنة، ولا ينظر الله إليهم يوم القيامة: العاق بوالديه، والمرأة المترجلة المتشبهة بالرجال، والديوث. وثلاثة لا ينظر الله إليهم يوم القيامة: العاق بوالديه، والمدمن الخمر، والمنان بما أعطى ))."],"takhrij":"حسن: رواه النسائي (٢٥٦٢)، وأحمد (٦١٨٠) والبزار - كشف الأستار (١٨٧٦) وأبو يعلى (٥٥٥١).","grade":"حسن","chapter_ar":"باب النهي عن التشبه بالنساء والعكس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (2562), Aḥmad (6180), al-Bazzār in Kashf al-Astār (1876), and Abū Yaʿlā (5551).","chapter_en":"The Prohibition of Men Resembling Women and Women Resembling Men","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":46,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Three will not enter Paradise, and Allah will not look at them on the Day of Resurrection: the one undutiful to his parents, the woman who imitates men, and the dayyūth. And three Allah will not look at on the Day of Resurrection: the one undutiful to his parents, the habitual drinker of alcohol, and the one who reminds others of what he has given them.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":2562},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1876},{"key":"ابو_یعلی","label":"أبو يعلى","number":5551},{"key":"ahmad","label":"مسند الإمام أحمد","number":6180,"n":6180}]},{"num":6440,"demo":false,"sanad":"","matn":["عن صفية بنت حيي زوج النبي ﷺ أنها جاءت رسول الله ﷺ تزوره، وهو معتكف في المسجد في العشر الغوابر من رمضان، فتحدثت عنده ساعة من العشاء، ثم قامت تنقلب، فقام معها النبي ﷺ يقلبها حتى إذا بلغت باب المسجد الذي عند مسكن أم سلمة زوج النبي ﷺ، مر بهما رجلان من الأنصار، فسلما على رسول الله ﷺ، ثم نفذا، فقال لهما رسول الله ﷺ: (( على رسلكما، إنما هي صفية بنت حيي )). قالا: سبحان الله يا رسول الله، وكبر عليهما ما قال، قال: (( إن الشيطان يجري من ابن آدم مبلغ الدم، وإني خشيت أن يقذف في قلوبكما ))."],"takhrij":"متفق عليه: رواه البخاري (٦٢١٩) ومسلم (٢١٧٥:٢٥).","grade":"متفق عليه","chapter_ar":"باب سمر النبي ﷺ بنسائه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6219) and Muslim (2175:25).","chapter_en":"The Prophet ﷺ Spending the Evening in Conversation with His Wives","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":47,"content":{"translation":{"en":["Ṣafiyyah bint Ḥuyayy, the wife of the Prophet ﷺ, said that she came to the Messenger of Allah ﷺ to visit him while he was in iʿtikāf in the mosque during the last ten nights of Ramadan. She spoke with him for a while after ʿIshā’, then she stood to leave, and the Prophet ﷺ stood with her to escort her back. When she reached the door of the mosque near the dwelling of Umm Salamah, the wife of the Prophet ﷺ, two men from the Anṣār passed by her. They greeted the Messenger of Allah ﷺ and then continued on. The Messenger of Allah ﷺ said to them: “Slow down. This is only Ṣafiyyah bint Ḥuyayy.” They said: Glory be to Allah, O Messenger of Allah. What he said seemed very serious to them. He said: “Satan runs through the son of Adam as blood runs, and I feared that he might cast something into your hearts.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6219},{"key":"muslim","label":"مسلم","number":2175}]},{"num":6441,"demo":false,"sanad":"","matn":["عن أم كلثوم بنت عقبة أنها سمعت رسول الله ﷺ يقول: (( ليس الكذاب الذي يُصلح بين الناس، فينمي خيراً أو يقول خيراً ))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٩٢)، ومسلم (٢٦٠٥)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب الترخيص في الكذب من أجل الإصلاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2692) and Muslim (2605). The wording is from al-Bukhārī.","chapter_en":"The Concession of Using Untrue Speech for the Sake of Reconciliation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":48,"content":{"translation":{"en":["Umm Kulthūm bint ʿUqbah said that she heard the Messenger of Allah ﷺ say: “The one who reconciles between people and conveys good or says good is not a liar.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2692},{"key":"muslim","label":"مسلم","number":2605}]},{"num":6442,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر أن رسول الله ﷺ قال: (( كلكم راع، وكلكم مسئول عن رعيته، والمرأة راعية في بيت زوجها، ومسؤولة عن رعيتها ))."],"takhrij":"متفق عليه: رواه البخاري (٨٩٣) ومسلم (١٨٢٩).","grade":"متفق عليه","chapter_ar":"باب إن المرأة راعية البيت","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (893) and Muslim (1829).","chapter_en":"The Woman Is a Shepherd Over the Home","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":49,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said that the Messenger of Allah ﷺ said: “Each of you is a shepherd, and each of you will be questioned about his flock. And the woman is a shepherd in her husband’s house, and she is responsible for her flock.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":893},{"key":"muslim","label":"مسلم","number":1829}]},{"num":6443,"demo":false,"sanad":"","matn":["عن جابر إن امرأة قالت: يا رسول الله ﷺ صلّ عليّ وعلى زوجي صلى الله عليك. فقال: (( صلى الله عليكِ وعلى زوجكِ ))."],"takhrij":"صحيح: رواه أبو داود (١٥٣٣) وأحمد (١٥٢٨١).","grade":"صحيح","chapter_ar":"باب شفقة رسول الله ﷺ للنساء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1533) and Aḥmad (15281).","chapter_en":"The Compassion of the Messenger of Allah ﷺ Toward Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء عن حقوق المرأة المسلمة، وواجباتها، وحسن العشرة بها","group_en":"Collection of narrations regarding the rights of the Muslim woman, her duties, and kind treatment toward her","part_no":24,"group_no":3,"chapter_no":50,"content":{"translation":{"en":["Jābir said: A woman said: O Messenger of Allah, pray for me and for my husband — may Allah send blessings upon you. So he said: “May Allah send blessings upon you and upon your husband.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":1533},{"key":"ahmad","label":"مسند الإمام أحمد","number":15281,"n":15281}]},{"num":6444,"demo":false,"sanad":"","matn":["عن عروة بن الزبير: أن عائشة زوج النبي ﷺ أخبرته أن النكاح في الجاهلية كان على أربعة أنحاء: فنكاح منها نكاح الناس اليوم: يخطب الرجل إلى الرجل وليته أو ابنته، فيُصدقها ثم ينكحها. ونكاح آخر: كان الرجل يقول لامرأته إذا طهرت من طمثها: أرسلي إلى فلان فاستبضعي منه، ويعتزلها زوجها ولا يمسها أبدا، حتى يتبين حملها من ذلك الرجل الذي تستبضع منه، فإذا تبين حملها أصابها زوجها إذا أحب، وإنما يفعل ذلك رغبةً في نجابة الولد، فكان هذا النكاح نكاح الاستبضاع. ونكاح آخر: يجتمع الرهط ما دون العشرة، فيدخلون على المرأة كلهم يصيبها، فإذا حملت ووضعت، ومر عليها ليال بعد أن تضع حملها، أرسلت إليهم، فلم يستطع رجل منهم أن يمتنع، حتى يجتمعوا عندها، تقول لهم: قد عرفتم الذي كان من أمركم، وقد ولدتُ، فهو ابنك يا فلان، تسمي من أحبت باسمه فيلحق به ولدها، لا يستطيع أن يمتنع به الرجل. والنكاح الرابع: يجتمع الناس الكثير، فيدخلون على المرأة، لا تمتنع ممن جاءها، وهن البغايا، كن ينصبن على أبوابهن رايات تكون علماً، فمن أرادهن دخل عليهن، فإذا حملت إحداهن ووضعت حملها جمعوا لها، ودعوا لهم القافة، ثم ألحقوا ولدها بالذي يرون، فالتاطته به، ودعي ابنه، لا يمتنع من ذلك. فلما بعث محمد ﷺ بالحق، هدم نكاح الجاهلية كله إلا نكاح الناس اليوم."],"takhrij":"صحيح: رواه البخاري (٥١٢٧). وقولها: “فالتاطته” أي استلحقته به. وأصل اللوط: اللصوق.","grade":"صحيح","chapter_ar":"باب أنكحة أهل الجاهلية التي أقرها الإسلام","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5127). Her words “faltāṭat-hu” mean: she attached him to him as his child. The root meaning of lawṭ is attachment or sticking.","chapter_en":"The Forms of Marriage in the Pre-Islamic Period That Islam Approved","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr narrated that ʿA’ishah, the wife of the Prophet ﷺ, informed him that marriage in the pre-Islamic period was of four types. One type was like the marriage of people today: a man would propose to another man for his ward or daughter, give her a dowry, and then marry her. Another type was that a man would say to his wife, when she became pure from her menstruation: Send to so-and-so and seek seed from him. Her husband would then stay away from her and not touch her at all until her pregnancy from that man became clear. When it became clear that she was pregnant, her husband would have relations with her if he wished. They only did that out of desire for noble offspring. This marriage was called nikāḥ al-istibḍāʿ. Another type of marriage was that a group of men, fewer than ten, would gather and all go to one woman and have intercourse with her. If she became pregnant and then gave birth, and some nights passed after she had delivered, she would send for them, and no man among them could refuse until they had gathered with her. She would say to them: You know what happened among you, and now I have given birth, so he is your son, O so-and-so — naming whichever of them she wished — and her child would then be attached to him, and the man could not refuse. The fourth type of marriage was that many men would gather and enter upon a woman, and she would not prevent any who came to her. These were the prostitutes. They used to set up flags over their doors as a sign, and whoever wanted them entered upon them. If one of them became pregnant and then gave birth, they would gather for her and summon the physiognomists, then they would attribute her child to whichever man they thought fit. She would then attach him to that man, and he would be called his son, and he could not refuse that. But when Muhammad ﷺ was sent with the truth, he abolished all the forms of marriage from the pre-Islamic period except the marriage of people today."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5127}]},{"num":6445,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن رسول الله ﷺ قال: (( لا يجمع بين المرأة وعمتها، ولا بين المرأة وخالتها ))."],"takhrij":"متفق عليه: رواه مالك (٢٠) والبخاري (٥١٠٩)، ومسلم (٣٣:١٤٠٨).","grade":"متفق عليه","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (5109), and Muslim (1408 no. 33).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah narrated that the Messenger of Allah ﷺ said: “A woman must not be joined in marriage with her paternal aunt, nor with her maternal aunt.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20},{"key":"bukhari","label":"البخاري","number":5109},{"key":"muslim","label":"مسلم","number":33}]},{"num":6446,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: نهى رسول الله ﷺ أن تنكح المرأة على عمتها أو خالتها"],"takhrij":"صحيح: رواه البخاري (٥١٠٨)","grade":"صحيح","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5108).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["From Jabir ibn ʿAbdullah: The Messenger of Allah ﷺ forbade that a woman be married together with her paternal aunt or her maternal aunt."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5108}]},{"num":6447,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ نهى أن تُنكح المرأة على عمتها، أو العمة على ابنة أخيها، أو المرأة على خالتها، أو الخالة على ابنة أختها، ولا تُنكح الصغرى على الكبرى، ولا الكبرى على الصغرى."],"takhrij":"صحيح: رواه أبو داود (٢٠٦٥) والترمذي (١١٢٦) والنسائي (٣٢٩٦). قال الترمذي: “حسن صحيح”.","grade":"صحيح","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2065), al-Tirmidhi (1126), and al-Nasa’i (3296). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Hurairah narrated from the Prophet ﷺ that he forbade that a woman be married together with her paternal aunt, or that the aunt be married together with her brother’s daughter, or that a woman be married together with her maternal aunt, or that the maternal aunt be married together with her sister’s daughter. And the younger must not be married together with the elder, nor the elder together with the younger."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2065},{"key":"tirmidhi","label":"الترمذي","number":1126},{"key":"nasai","label":"النسائي","number":3296}]},{"num":6448,"demo":false,"sanad":"","matn":["عن ابن عباس أن النبي ﷺ نهى أن تُزوج المرأة على عمتها، أو على خالتها."],"takhrij":"صحيح: رواه الترمذي (١١٢٥). قال الترمذي: “حسن صحيح”.","grade":"صحيح","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1125). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Prophet ﷺ forbade that a woman be married together with her paternal aunt or her maternal aunt."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1125}]},{"num":6449,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: لما فتحت مكة على رسول الله ﷺ قال: فذكر الحديث بطوله وفيه: (( ولا تُنكح المرأة على عمتها، ولا على خالتها ))."],"takhrij":"حسن: رواه أحمد (٦٧١٢ ،٦٦٨١) وابن أبي شيبة (٢٤٧/٤) وعبد الرزاق (١٠٧٥٠).","grade":"حسن","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6712, 6681), Ibn Abi Shaybah (4/247), and ʿAbd al-Razzaq (10750).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: When Mecca was opened to the Messenger of Allah ﷺ, he said — then he mentioned the hadith in full, and in it was: “A woman must not be married together with her paternal aunt, nor together with her maternal aunt.”"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_شیبہ","label":"ابن أبي شيبة","number":247},{"key":"عبد_الرزاق","label":"عبد الرزاق","number":10750},{"key":"ahmad","label":"مسند الإمام أحمد","number":6712,"n":6712}]},{"num":6450,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: سمعت رسول الله ﷺ ينهى أن يجمع بين المرأة وخالتها، وبين المرأة وعمتها."],"takhrij":"حسن: رواه ابن ماجه (١٩٣٠) وأحمد (١١٦٣٧) وابن نصر المروزي في السنة (٢٤٢).","grade":"حسن","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1930), Ahmad (11637), and Ibn Nasr al-Marwazi in al-Sunnah (242).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: I heard the Messenger of Allah ﷺ forbidding that a woman be combined in marriage with her maternal aunt, and that a woman be combined with her paternal aunt."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1930},{"key":"ابن_نصر_المروزی/السنہ","label":"ابن نصر المروزي في السنة","number":242},{"key":"ahmad","label":"مسند الإمام أحمد","number":11637,"n":11637}]},{"num":6451,"demo":false,"sanad":"","matn":["عن عائشة قالت: وجدت في قائم سيف رسول الله ﷺ كتاباً: (( إن أشد الناس عُتواً من ضرب غير ضاربه، ورجل قتل غير قاتله، ورجل تولى غير أهل نعمته، فمن فعل ذلك فقد كفر بالله ورسوله، لا يقبل الله منه صرفاً، ولا عدلاً، وفي الأجر المؤمنون تكافأ دماؤهم، ويسعى بذمتهم أدناهم، لا يُقتل مسلم بكافر، ولا ذو عهد في عهده، ولا يتوارث أهلُ ملتين، ولا تُنكح المرأة على عمتها، ولا على خالتها، ولا صلاة بعد العصر حتى تغرب الشمس، ولا تسافر المرأة ثلاث ليال مع غير ذي محرم ))."],"takhrij":"حسن: رواه أبو يعلى (٤٧٥٧) والدار قطني (١٣١/٣) والحاكم (٣٤٩/٤) والبيهقي (٣٠-٢٩/٨).","grade":"حسن","chapter_ar":"باب النهي عن الجمع بين المرأة وعمتها أو خالتها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (4757), al-Daraqutni (3/131), al-Hakim (4/349), and al-Bayhaqi (8/29–30).","chapter_en":"The Prohibition of Combining a Woman with Her Paternal Aunt or Maternal Aunt in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah said: I found in the hilt of the sword of the Messenger of Allah ﷺ a written statement: “Among the most severe of people in transgression are: a man who strikes someone other than the one who struck him, a man who kills someone other than his killer, and a man who allies himself with people other than those who bestowed their patronage upon him. Whoever does that has disbelieved in Allah and His Messenger. Allah will accept from him neither compensation nor ransom. In retaliation, the believers’ blood is equal, and even the least of them may grant protection on their behalf. A Muslim is not to be killed for a disbeliever, nor one under covenant while he is under his covenant. The people of two different religions do not inherit from one another. A woman must not be married together with her paternal aunt, nor with her maternal aunt. There is no prayer after ʿAsr until the sun sets, and a woman must not travel for three nights without a mahram.”"]},"buhuth":{"ar":["وأما قوله تعالى بعد ذكر المحرمات من النساء: ( وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمْ ) [النساء: ٢٤] فهذا العموم مخصص بأحاديث الباب، ولم يختلف فيه أحد. وقد حكى الشافعي عن جميع المفتين تحريم الجمع بين من ذكر في أحاديث الباب.","وأما الجمع بين زوجة الرجل وبنته من غيرها فلا بأس به، كما جمع عبد الله بن جعفر بين زينب بنت علي - وفي رواية: بين أم كلثوم بنت علي - وبين زوجة علي وهي ليلى بنت مسعود النهشلية وكذلك لا بأس بالجمع بين ابنتي عمّ، كان الحسن بن الحسن بن علي جمع بين ابنتي عم في ليلة. (كل هذا ذكره البخاري معلقا في كتاب النكاح، باب ٢٤ ما يحل من النساء وما يحرم)."],"en":["As for His statement, after mentioning the women forbidden in marriage: “And lawful to you is whatever is beyond that” [Surat al-Nisa’ 4:24], this general wording is specified by the hadiths of this chapter, and no one has differed over that. Al-Shafiʿi reported from all the jurists that combining those mentioned in the hadiths of this chapter is forbidden.","As for combining a man’s wife with his daughter from another woman, there is no harm in that, just as ʿAbdullah ibn Jaʿfar combined Zaynab daughter of ʿAli — and in another narration, Umm Kulthum daughter of ʿAli — together with ʿAli’s wife, who was Layla bint Masʿud al-Nahshaliyyah. Likewise, there is no harm in combining two female cousins from paternal uncles. Al-Hasan ibn al-Hasan ibn ʿAli combined two daughters of paternal uncles in one night.","(All of this was mentioned by al-Bukhari in suspended form in the Book of Marriage, Chapter 24: What is lawful of women and what is forbidden.)"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":4757},{"key":"الدار_قطنی","label":"الدار قطني","number":131},{"key":"hakim","label":"الحاكم","number":349},{"key":"البیہقی","label":"البيهقي","number":30},{"key":"sh12520","label":"مسند أبي يعلى","number":4757,"n":4762}]},{"num":6452,"demo":false,"sanad":"","matn":["عن أم حبيبة زوج النبي ﷺ حدثتها أنها قالت لرسول الله ﷺ: يا رسول الله! انكح أختي عزَّة. فقال رسول الله ﷺ: (( أتحبين ذلك؟ )). فقالت: نعم. يا رسول الله! لست لك بمُخلية وأحب من شركني في خير أختي، فقال رسول الله ﷺ: (( فإن ذلك لا يحل لي )). قالت: فقلت: يا رسول الله! فإنا نتحدث أنك تريد أن تنكح دُرّة بنت أبي سلمة. قال: (( بنت أبي سلمة؟ )) قالت: نعم. قال رسول الله ﷺ: (( لو أنها لم تكن ربيبتي في حجري ما حلت لي. إنها ابنة أخي من الرضاعة، أرضعتني وأبا سلمة ثويبة. فلا تعرضنَّ علي بناتكنَّ ولا أخواتكنَّ ))."],"takhrij":"متفق عليه: رواه مسلم (١٦:١٤٤٩) والبخاري (٥١٠٧).","grade":"متفق عليه","chapter_ar":"باب النهي عن الجمع بين الأختين","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1449 no. 16) and al-Bukhari (5107).","chapter_en":"The Prohibition of Combining Two Sisters in Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Umm Habibah, the wife of the Prophet ﷺ, narrated that she said to the Messenger of Allah ﷺ: O Messenger of Allah, marry my sister ʿAzzah. The Messenger of Allah ﷺ said: “Would you like that?” She said: Yes, O Messenger of Allah. I am not exclusive to you, and the one I most love to share in good with me is my sister. The Messenger of Allah ﷺ said: “That is not lawful for me.” She said: Then I said: O Messenger of Allah, we hear that you want to marry Durrah, the daughter of Abu Salamah. He said: “The daughter of Abu Salamah?” She said: Yes. The Messenger of Allah ﷺ said: “If she were not my stepdaughter in my care, she still would not be lawful for me. She is the daughter of my brother through nursing. Thuwaybah nursed me and Abu Salamah. So do not offer your daughters or your sisters to me.”"]},"intro":{"ar":["قال الله تعالى: ( وَأَن تَجْمَعُوا بَيْنَ ٱلْأُخْتَيْنِ ) [النساء: ٢٣]"],"en":["Allah the Exalted said: “And that you combine two sisters in marriage.” [Surat al-Nisa’ 4:23]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16},{"key":"bukhari","label":"البخاري","number":5107}]},{"num":6453,"demo":false,"sanad":"","matn":["عن البراء بن عازب قال: لقيت عمي ومعه راية، فقلت له: أين تريد؟ قال: بعثني رسول الله ﷺ إلى رجل نكح امرأة أبيه، فأمرني أن أضرب عنقه، وآخذ ماله."],"takhrij":"صحيح: رواه أبو داود (٤٤٥٧) والنسائي (٣٣٣٢) وابن الجارود (٦٨١) والحاكم (٣٥٧/٤).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح ما نكح الآباءُ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (4457), al-Nasa’i (3332), Ibn al-Jarud (681), and al-Hakim (4/357).","chapter_en":"The Prohibition of Marrying the Women Whom One’s Fathers Married","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib said: I met my uncle while he had a banner with him, so I said to him: Where are you going? He said: The Messenger of Allah ﷺ sent me to a man who had married his father’s wife, and he ordered me to strike off his neck and take his wealth."]},"buhuth":{"ar":["وقوله: عمي، وفي رواية خالي لا منافاة بينهما، فهو قد يكون عمه من جهة النسب، وخاله من جهة الرضاعة، وكون اسمه جاء صريحا بأنه الحارث بن عمرو، أو أبو بردة بن نيار فالظاهر أنه خاله لا عمه."],"en":["His saying “my uncle,” and in another narration “my maternal uncle,” do not conflict. He may have been his paternal uncle by lineage and his maternal uncle by nursing. Since his name appears explicitly as al-Harith ibn ʿAmr, or Abu Burdah ibn Niyar, the more apparent view is that he was his maternal uncle, not his paternal uncle."]},"intro":{"ar":["قال الله تعالى: ( وَلَا تَنكِحُوا مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدْ سَلَفَ ) [النساء: ٢٢]","كان أهل الجاهلية يتزوجون بأزواج آبائهم، ويعدون ذلك من الإرث، فجاء النهي عن هذا وهو للتحريم."],"en":["Allah the Exalted said: “And do not marry those women whom your fathers married, except what has already passed.” [Surat al-Nisa’ 4:22]","The people of the pre-Islamic period used to marry the wives of their fathers and regarded that as part of inheritance. Then the prohibition came regarding this, and it is a prohibition of unlawfulness."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4457},{"key":"nasai","label":"النسائي","number":3332},{"key":"ابن_الجارود","label":"ابن الجارود","number":681},{"key":"hakim","label":"المستدرك على الصحيحين","number":8056,"n":8062}]},{"num":6454,"demo":false,"sanad":"","matn":["عن البراء بن عازب قال:","بينا أنا أطوف على إبل لي ضلّت، إذ أقبل ركب، أو فوارس، معهم لواء، فجعل الأعراب يطيفون بي لمنزلتي من النبي ﷺ، إذ أتوا قبة فاستخرجوا منها رجلًا فضربوا عنقه، فسألت عنه، فذكروا أنه أعرس بامرأة أبيه."],"takhrij":"صحيح: رواه أبو داود (٤٤٥٦)، وأحمد (١٨٦٠٩)، والطحاوي في شرح معاني الآثار (٣/١٤٩)، وسعيد بن منصور (٩٤٣).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح ما نكح الآباءُ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4456), Aḥmad (18609), al-Ṭaḥāwī in Sharḥ Maʿānī al-Āthār (3/149), and Saʿīd ibn Manṣūr (943).","chapter_en":"The Prohibition of Marrying the Women Whom One’s Fathers Married","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib reported:","While I was going around looking for some camels of mine that had strayed, a caravan—or some horsemen—approached carrying a banner. The Bedouins began gathering around me because of my position with the Prophet ﷺ.","They came to a domed structure, brought a man out of it, and struck off his neck. I asked about him, and they told me that he had married his father’s wife."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4456},{"key":"الطحاوی/شرح_معانی_الاثار","label":"الطحاوي في شرح معاني الآثار","number":3},{"key":"سعید_بن_منصور","label":"سعيد بن منصور","number":943},{"key":"ahmad","label":"مسند الإمام أحمد","number":18609,"n":18609}]},{"num":6455,"demo":false,"sanad":"","matn":["عن قرة قال: بعثني رسول الله ﷺ إلى رجل تزوج امرأة أبيه، أن أضرب عنقه وأُصَفِّيَ ماله."],"takhrij":"حسن: رواه ابن ماجه (٢٦٠٨) والدار قطني (٢٠٠/٣) والبيهقي (٢٠٨/٨).","grade":"حسن","chapter_ar":"باب النهي عن نكاح ما نكح الآباءُ","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2608), al-Daraqutni (3/200), and al-Bayhaqi (8/208).","chapter_en":"The Prohibition of Marrying the Women Whom One’s Fathers Married","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Qurrah said: The Messenger of Allah ﷺ sent me to a man who had married his father’s wife, ordering me to strike off his neck and confiscate his wealth."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2608},{"key":"الدار_قطنی","label":"الدار قطني","number":200},{"key":"البیہقی","label":"البيهقي","number":208}]},{"num":6456,"demo":false,"sanad":"","matn":["عن أم حبيبة زوج النبي ﷺ أنها قالت لرسول الله ﷺ:","يا رسول الله، انكح أختي عزة.","فقال رسول الله ﷺ:","«أَتُحِبِّينَ ذَلِكِ؟»","فقالت:","نعم يا رسول الله، لست لك بمخلية، وأحب من شركني في خير أختي.","فقال رسول الله ﷺ:","«فَإِنَّ ذَلِكَ لَا يَحِلُّ لِي».","قالت:","فقلت: يا رسول الله، فإنا نتحدث أنك تريد أن تنكح درة بنت أبي سلمة.","قال:","«بِنْتَ أَبِي سَلَمَةَ؟»","قالت: نعم.","قال رسول الله ﷺ:","«لَوْ أَنَّهَا لَمْ تَكُنْ رَبِيبَتِي فِي حِجْرِي مَا حَلَّتْ لِي، إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ، أَرْضَعَتْنِي وَأَبَا سَلَمَةَ ثُوَيْبَةُ، فَلَا تَعْرِضْنَ عَلَيَّ بَنَاتِكُنَّ وَلَا أَخَوَاتِكُنَّ»."],"takhrij":"متفق عليه: رواه البخاري (٥١٠٧)، ومسلم (١٤٤٩/١٦).","grade":"متفق عليه","chapter_ar":"باب تحريم نكاح الربيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5107) and Muslim (1449/16).","chapter_en":"The Prohibition of Marrying Stepdaughters","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Umm Ḥabībah, the wife of the Prophet ﷺ, reported that she said to the Messenger of Allah ﷺ:","“O Messenger of Allah, marry my sister ʿAzzah.”","The Messenger of Allah ﷺ asked:","“Would you like that?”","She replied:","“Yes, O Messenger of Allah. I am not your only wife, and the person I would most love to share this good with me is my sister.”","The Messenger of Allah ﷺ said:","“That is not lawful for me.”","She said:","“I said: O Messenger of Allah, we have been told that you intend to marry Durrah, the daughter of Abū Salamah.”","He asked:","“The daughter of Abū Salamah?”","She replied:","“Yes.”","The Messenger of Allah ﷺ said:","“Even if she were not my stepdaughter under my care, she would not be lawful for me. She is the daughter of my foster-brother. Thuwaybah nursed both me and Abū Salamah. So do not offer your daughters or your sisters to me.”"]},"buhuth":{"ar":["فصار النبي ﷺ وأبو سلمة وحمزة إخوة من الرضاعة."],"en":["Thus, the Prophet ﷺ, Abū Salamah, and Ḥamzah were brothers through breastfeeding."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5107},{"key":"muslim","label":"مسلم","number":1449}]},{"num":6457,"demo":false,"sanad":"","matn":["عن عروة أن النبي ﷺ خطب عائشة إلى أبي بكر. فقال له أبو بكر: إنما أنا أخوك، فقال: (( أنت أخي في دين الله وكتابه، وهي لي حلال ))."],"takhrij":"صحيح: رواه البخاري (٥٠٨١).","grade":"صحيح","chapter_ar":"باب بنت الأخ في الدين لا تحرم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5081).","chapter_en":"The daughter of one’s brother in religion is not forbidden in marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["ʿUrwah narrated that the Prophet ﷺ proposed for ʿA’ishah to Abu Bakr. Abu Bakr said to him: I am only your brother. He said: “You are my brother in the religion of Allah and His Book, and she is lawful for me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5081}]},{"num":6458,"demo":false,"sanad":"","matn":["عن ابن عمر أن غيلان بن سلمة الثقفي أسلم وعنده عشر نسوة، فأمره النبي ﷺ أن يمسك منهن أربعاً. فلما كان زمان عمر طلقهنَّ، فأمره عمر أن يرتجعهن. وقال: لو مت لورثتهن منك، ولأمرت بقبرك يرجم كما رجم قبر أبي رغال."],"takhrij":"حسن: رواه النسائي كما ذكره الحافظ في التلخيص (١٦٩/٣) والدار قطني (٢٧١/٣) والبيهقي (١٨٣/٧).","grade":"حسن","chapter_ar":"باب من أسلم وتحته أكثر من أربع نسوة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i as cited by al-Hafiz in al-Talkhis (3/169), al-Daraqutni (3/271), and al-Bayhaqi (7/183).","chapter_en":"One Who Accepts Islam While Married to More Than Four Women","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar narrated that Ghaylan ibn Salamah al-Thaqafi accepted Islam while he had ten wives, so the Prophet ﷺ ordered him to keep four of them. Then during the time of ʿUmar he divorced them, and ʿUmar ordered him to take them back. He said: If you were to die, they would inherit from you, and I would order your grave to be stoned just as the grave of Abu Righal was stoned."]},"buhuth":{"ar":["قوله: (( قبر أبي رِغالٍ )) - بكسر الراء - كان من ثمود، وكان بالحرم حين أصابت قومه الصيحةُ، فلما خرج من الحرم أصابه الهلاك كما أصاب قومه، فدُفن هناك وهو بين مكة والطائف، وكان عشَّارًا في الزمن الأول فرجم الناس قبره. قال جرير:","إذا مات الفرزدق فارجموه","كما ترجمون قبر أبي رغال"],"en":["His saying: “the grave of Abu Righal” — with the letter ra’ read with kasrah — refers to a man from Thamud. He was in the sanctuary when the cry struck his people. When he left the sanctuary, destruction struck him just as it struck his people. He was buried there between Mecca and Ta’if. He had been a tax collector in earlier times, so people stoned his grave. Jarir said:","“When al-Farazdaq dies, stone him","just as you stone the grave of Abu Righal.”"]},"intro":{"ar":["قال الله تعالى: ( فَٱنكِحُوا مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ ) [سورة النساء: ٣]"],"en":["Allah the Exalted said: “Then marry what seems good to you of women: two, three, or four.” [Surat al-Nisa’ 4:3]"]}},"tuhfa":{},"refs":[{"key":"النسایی_کما_ذکرہ_الحافظ/التلخیص","label":"النسائي كما ذكره الحافظ في التلخيص","number":169},{"key":"الدار_قطنی","label":"الدار قطني","number":271},{"key":"البیہقی","label":"البيهقي","number":183},{"key":"sh9771","label":"سنن الدارقطني","number":3694,"n":3706}]},{"num":6459,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: كنا نغزو مع رسول الله ﷺ ليس لنا نساء، فقلنا: ألا نستخصي؟ فنهانا عن ذلك. ثم رخّص لنا أن ننكح المرأة بالثوب إلى أجل. ثم قرأ عبد الله: ( يَأَيُّهَا ٱلَّذِينَ ءَامَنُوا لَا تُحَرِّمُوا طَيِّبَٰتِ مَآ أَحَلَّ ٱللَّهُ لَكُمْ وَلَا تَعْتَدُوا إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ ) [سورة المائدة: ٨٧]."],"takhrij":"متفق عليه: رواه البخاري (٥٠٧٥) ومسلم (١١:١٤٠٤). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5075) and Muslim (1404 no. 11). The wording is that of Muslim.","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Ibn Masʿud said: We used to go out in battle with the Messenger of Allah ﷺ while we had no women with us, so we said: Shall we castrate ourselves? He forbade us from that. Then he gave us permission to marry a woman for a fixed term in exchange for a garment. Then ʿAbdullah recited: “O you who believe, do not forbid the good things Allah has made lawful for you, and do not transgress. Indeed, Allah does not love the transgressors.” [Surat al-Ma’idah 5:87]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5075},{"key":"muslim","label":"مسلم","number":11}]},{"num":6460,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: كنا نغزو مع رسول الله ﷺ فتطول غُربتنا. فقلنا: ألا نستخصي يا رسول الله؟ فنهانا، ثم رخّص أن نتزوّج المرأةَ إلى أجلٍ بالشيء، ثم نهانا عنها يوم خيبر، وعن لحوم الحمر الأهلية."],"takhrij":"صحيح: رواه عبد الرزاق (١٤٠٤٨). وكان الترخيص في المتعة قبل خيبر.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzaq (14048). The permission for temporary marriage was before Khaybar.","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Ibn Masʿud said: We used to go out in battle with the Messenger of Allah ﷺ and our absence would become long. So we said: O Messenger of Allah, shall we castrate ourselves? He forbade us from that. Then he permitted us to marry a woman for a fixed term in exchange for something, then he forbade it on the day of Khaybar, and also forbade the meat of domesticated donkeys."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":14048},{"key":"abdrazzaq","label":"المصنف لعبد الرزاق","number":14981,"n":15074}]},{"num":6461,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود قال: كنا نغزو مع رسول الله ﷺ ونحن شباب، وليس لنا نساء، فقلنا: يا رسول الله ﷺ ألا نستخصي؟ فنهانا عن ذلك."],"takhrij":"صحيح: رواه أحمد (٣٧٠٦).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (3706).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud said: We used to go out in battle with the Messenger of Allah ﷺ while we were young men and had no women with us, so we said: O Messenger of Allah, shall we castrate ourselves? He forbade us from that."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":3706,"n":3706}]},{"num":6462,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، أن رسول الله ﷺ نهى عن متعة النساء يوم خيبر، وعن أكل لحوم الحمر الإنسيّة."],"takhrij":"متفق عليه: رواه مالك (٤١) والبخاري (٤٢١٦)، ومسلم (٢٩:١٤٠٧).","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (41), al-Bukhari (4216), and Muslim (1407 no. 29).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAli ibn Abi Talib narrated that the Messenger of Allah ﷺ forbade temporary marriage with women on the day of Khaybar, and also forbade eating the meat of domesticated donkeys."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":41},{"key":"bukhari","label":"البخاري","number":4216},{"key":"muslim","label":"مسلم","number":29}]},{"num":6463,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب أنه سمع ابن عباس يُليّن في متعة النساء. فقال: مهلاً يا ابن عباس! فإن رسول الله ﷺ نهى عنها يوم خيبر، وعن لحوم الحمر الأهلية."],"takhrij":"متفق عليه: رواه مسلم (٣١:١٤٠٧) والبخاري (٦٩٦١).","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1407 no. 31) and al-Bukhari (6961).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAli ibn Abi Talib heard Ibn ʿAbbas speaking leniently about temporary marriage with women, so he said: Take it easy, O Ibn ʿAbbas, for the Messenger of Allah ﷺ forbade it on the day of Khaybar, and he also forbade the meat of domesticated donkeys."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":31},{"key":"bukhari","label":"البخاري","number":6961}]},{"num":6464,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب يقول لابن عباس: إنك رجل تائه، إن رسول الله ﷺ نهى عن متعة النساء."],"takhrij":"صحيح: رواه الطحاوي في شرحه (٢٤/٣).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tahawi in his Sharh (3/24).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAli ibn Abi Talib said to Ibn ʿAbbas: You are a man who has erred. The Messenger of Allah ﷺ forbade temporary marriage with women."]}},"tuhfa":{},"refs":[{"key":"الطحاوی/شرحہ","label":"الطحاوي في شرحه","number":24}]},{"num":6465,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله وسلمة بن الأكوع قالا: كنا في جيش، فأتانا رسول الله ﷺ فقال: (( إنه قد أذن لكم أن تستمتعوا فاستمتعوا)). زاد مسلم: (( يعني متعة النساء))."],"takhrij":"متفق عليه: رواه البخاري (٥١١٧،٥١١٨)، ومسلم (١٣:١٤٠٥)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5117, 5118) and Muslim (1405 no. 13). The wording is that of al-Bukhari.","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah and Salamah ibn al-Akwaʿ said: We were in an army, and the Messenger of Allah ﷺ came to us and said: “Permission has been given to you to contract temporary marriage, so do so.” Muslim added: “meaning temporary marriage with women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5117},{"key":"muslim","label":"مسلم","number":13}]},{"num":6466,"demo":false,"sanad":"","matn":["عن سلمة بن الأكوع قال: رخص رسول الله ﷺ عام أوطاس في المتعة ثلاثا، ثم نهى عنها."],"takhrij":"صحيح: رواه مسلم (١٨:١٤٠٥).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1405 no. 18).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: The Messenger of Allah ﷺ allowed temporary marriage during the year of Awtas for three days, then forbade it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18}]},{"num":6467,"demo":false,"sanad":"","matn":["عن سلمة بن الأكوع، أن النبي ﷺ قال: (( أيما رجل وامرأة أيم تراضيا بعشرتهما ثلاث ليال، فإن أرادا أن يتزايدا تزايدا، وإن أرادا أن يتتاركا تتاركا ))."],"takhrij":"صحيح: رواه الطبراني في “المعجم الكبير” (٢٧/٧).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Muʿjam al-Kabir (7/27).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ narrated that the Prophet ﷺ said: “Any man and woman without spouses who mutually agree to live together for three nights, then if they wish to extend it, they may extend it, and if they wish to separate, they may separate.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/المعجم_الکبیر","label":"الطبراني في “المعجم الكبير”","number":27}]},{"num":6468,"demo":false,"sanad":"","matn":["عن سبرة الجهني أنه أذن لنا رسول الله ﷺ بالمتعة، فانطلقت أنا ورجل إلى امرأة من بني عامر، كأنها بكرة عيطاء، فعرضنا عليها أنفسنا. فقالت: ما تُعطي؟ فقلت: ردائي. وقال صاحبي: ردائي، وكان رداء صاحبي أجود من ردائي. وكنت أشبّ منه، فإذا نظرت إلى رداء صاحبي أعجبها، وإذا نظرت إلي أعجبتُها. ثم قالت: أنت ورداؤك يكفيني، فمكثت معها ثلاثاً. ثم إن رسول الله ﷺ قال: (( من كان عنده شيء من هذه النساء التي يتمتّع، فليخلّ سبيلها ))."],"takhrij":"صحيح: رواه مسلم (١٩:١٤٠٦). قوله: (( كأنها بكرة عيطاء)) البكرة: الشابة القوية. والعيطاء: هي الطويلة العنق في اعتدال وحسن قوام.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 19).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Sabrah al-Juhani said: The Messenger of Allah ﷺ gave us permission for temporary marriage. So I and another man went out to a woman from Banu ʿAmir, and she was like a young tall camel in beauty and stature. We offered ourselves to her. She said: What will you give? I said: My cloak. And my companion said: My cloak. My companion’s cloak was better than mine, but I was younger than him. When she looked at my companion’s cloak, she liked it, and when she looked at me, she liked me. Then she said: You and your cloak are enough for me. So I stayed with her for three nights. Then the Messenger of Allah ﷺ said: “Whoever has any of these women with whom he contracted temporary marriage, let him release her.”"]},"buhuth":{"en":["His saying, “as though she were a young tall camel”: al-bakrah means a young strong woman, and al-ʿayṭa’ means one with a long neck in proportion and fine form."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":19}]},{"num":6469,"demo":false,"sanad":"","matn":["عن الربيع بن سبرة، أن أباه غزا مع رسول الله ﷺ فتح مكة. قال: فأقمنا بها خمس عشرة. (ثلاثين بين ليلة ويوم) فأذن لنا رسول الله ﷺ في متعة النساء. فخرجت أنا ورجل من قومي، ولي عليه فضل في الجمال. وهو قريب من الدمامة. مع كل واحد منا بُرد. فبردي خَلَقٌ. وأما برد ابن عمي فبرد جديد غضّ. حتى إذا كنا بأسفل مكة، أو بأعلاها فتلقتنا فتاة مثل البِكرة العَنطنطة. فقلنا: هل لك أن يستمتع منك أحدنا؟ قالت: وماذا تبذلان؟ فنشر كل واحد منا برده. فجعلت تنظر إلى الرجلين. ويراها صاحبي تنظر إلى عِطْفها. فقال: إن بُرد هذا خلَقٌ وبُردي جديد غضّ. فتقول: برد هذا لا بأس به. ثلاث مرار أو مرتين. ثم استمتعت منها. فلم أخرج حتى حرمها رسول الله ﷺ."],"takhrij":"صحيح: رواه مسلم (٢٠:١٤٠٦). وقوله: (( الدمامة)) أي قبيح الصورة. و (( خلق)) أي قريب من البالي، وهو قديم. و (( العنطنطة)) طويلة القامة.","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 20).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Al-Rabiʿ ibn Sabrah narrated that his father fought with the Messenger of Allah ﷺ in the conquest of Mecca. He said: We stayed there for fifteen days — thirty, counting nights and days — and the Messenger of Allah ﷺ permitted us temporary marriage with women. So I and a man from my people went out. I was more handsome than him, while he was somewhat unattractive. Each of us had a cloak. My cloak was worn out, while my cousin’s cloak was new and fresh. When we were in the lower or upper part of Mecca, a girl met us, like a tall young camel in beauty. We said: Would one of us suit you for temporary marriage? She said: What will you give? Each of us spread out his cloak. She began looking at the two men, while my companion saw her looking to her side. So he said: This man’s cloak is worn out, but my cloak is new and fresh. Yet she would say: This man’s cloak is acceptable. She said that two or three times. Then I contracted temporary marriage with her. I had not yet left until the Messenger of Allah ﷺ forbade it."]},"buhuth":{"en":["His saying, “al-damamah,” means ugliness of appearance. “Khalaq” means worn and close to being shabby, that is, old. “Al-ʿanṭanṭah” means tall in stature."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":20}]},{"num":6470,"demo":false,"sanad":"","matn":["عن عبد الملك بن الربيع بن سبرة الجهني، عن أبيه، عن جده قال: أمرنا رسول الله ﷺ بالمتعة عام الفتح، حين دخلنا مكة، ثم لم نخرج منها حتى نهانا عنها."],"takhrij":"صحيح: رواه مسلم (٢٢:١٤٠٦).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 22).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿAbd al-Malik ibn al-Rabiʿ ibn Sabrah al-Juhani, from his father, from his grandfather, said: The Messenger of Allah ﷺ ordered us to contract temporary marriage in the year of the Conquest when we entered Mecca, then we did not leave it before he forbade us from it."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":22}]},{"num":6471,"demo":false,"sanad":"","matn":["عن سبرة الجهني أنه كان مع رسول الله ﷺ فقال: (( يا أيها الناس، إني قد كنت أذنت لكم في الاستمتاع من النساء، وإن الله قد حرم ذلك إلى يوم القيامة، فمن كان عنده منهن شيء فليخلّ سبيله، ولا تأخذوا مما آتيتموهن شيئا )).","وفي لفظ: رأيت رسول الله ﷺ قائما بين الركن والباب، وهو يقول: فذكره."],"takhrij":"صحيح: رواه مسلم (٢١:١٤٠٦).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406 no. 21).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Sabrah al-Juhani said that he was with the Messenger of Allah ﷺ, and he said: “O people, I had previously permitted you temporary marriage with women, but Allah has now forbidden that until the Day of Resurrection. So whoever has any of them with him, let him release her, and do not take back anything from what you gave them.”","And in another wording: I saw the Messenger of Allah ﷺ standing between the Corner and the Door saying this."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":21}]},{"num":6472,"demo":false,"sanad":"","matn":["عن عروة بن الزبير:","أن عبد الله بن الزبير قام بمكة فقال:","إن ناسًا أعمى الله قلوبهم كما أعمى أبصارهم، يفتون بالمتعة - يعرّض برجل - فناداه فقال:","إنك لجلف جاف، فلعمري لقد كانت المتعة تفعل على عهد إمام المتقين - يريد رسول الله ﷺ.","فقال له ابن الزبير:","فجرب بنفسك، فوالله لئن فعلتها لأرجمنك بأحجارك.","قال ابن شهاب:","فأخبرني خالد بن المهاجر بن سيف الله، أنه بينما هو جالس عند رجل، فاستفتاه في المتعة، فأمره بها.","فقال له ابن أبي عمرة الأنصاري:","مهلًا!","قال:","ما هي؟ والله لقد فُعِلتْ في عهد إمام المتقين.","قال ابن أبي عمرة:","إنها كانت رخصة في أول الإسلام لمن اضطر إليها، كالميتة والدم ولحم الخنزير، ثم أحكم الله الدين ونهى عنها."],"takhrij":"صحيح: رواه مسلم (١٤٠٦/٢٧).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1406/27).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr reported:","ʿAbdullāh ibn al-Zubayr stood in Makkah and said:","“There are people whose hearts Allah has blinded just as He has blinded their eyes, and they issue rulings permitting temporary marriage”—alluding to a certain man.","That man called out to him:","“You are a coarse and harsh man. By my life, temporary marriage was practiced during the lifetime of the leader of those who fear Allah,” meaning the Messenger of Allah ﷺ.","Ibn al-Zubayr said to him:","“Then try it yourself. By Allah, if you do it, I will stone you with your own stones.”","Ibn Shihāb said:","Khālid ibn al-Muhājir ibn Sayf Allah informed me that while he was sitting with a man, that man was asked for a ruling concerning temporary marriage and permitted it.","Ibn Abī ʿAmrah al-Anṣārī said to him:","“Wait!”","He said:","“What is the matter? By Allah, it was practiced during the time of the leader of those who fear Allah.”","Ibn Abī ʿAmrah said:","“It was only a concession during the early period of Islam for someone compelled by necessity, like carrion, blood, and pork. Then Allah perfected the religion and prohibited it.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1406}]},{"num":6473,"demo":false,"sanad":"","matn":["عن ابن عمر قال: لما ولي عمر بن الخطاب، خطب الناس فقال: إن رسول الله ﷺ أذن في المتعة ثلاثا، ثم حرمها. والله لا أعلم أحدا يتمتع وهو محصن إلا رجمته بالحجارة، إلا أن يأتيني بأربعة يشهدون أن رسول الله ﷺ أحلّها بعد إذ حرمها."],"takhrij":"حسن: رواه ابن ماجه (١٩٦٣).","grade":"حسن","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1963).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: When ʿUmar ibn al-Khattab became leader, he addressed the people and said: The Messenger of Allah ﷺ permitted temporary marriage three times, then he forbade it. By Allah, I do not know of anyone who engages in temporary marriage while married except that I would stone him, unless he brought me four witnesses testifying that the Messenger of Allah ﷺ made it lawful after having forbidden it."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1963}]},{"num":6474,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله، أن رجلا سأل عبد الله بن عمر عن المتعة، فقال: حرام، قال: فإن فلانا يقول فيها. فقال: والله لقد عُلم أن رسول الله ﷺ حرّمها يوم خيبر، وما كنا مسافحين."],"takhrij":"صحيح: رواه البيهقي (٢٠٢/٧).","grade":"صحيح","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bayhaqi (7/202).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salim ibn ʿAbd Allah narrated that a man asked ʿAbd Allah ibn ʿUmar about temporary marriage, and he said: It is forbidden. The man said: But so-and-so gives a ruling about it. He said: By Allah, it is certainly known that the Messenger of Allah ﷺ forbade it on the day of Khaybar, and we were not fornicators."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":202},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14148,"n":14284}]},{"num":6475,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله قال: أتي عبد الله بن عمر فقيل له: إن ابن عباس يأمر بنكاح المتعة، فقال ابن عمر: سبحان الله. ما أظن ابن عباس يفعل هذا. قالوا: بلى إنه يأمر به، فقال: وهل كان ابن عباس إلا غلاماً صغيراً إذ كان رسول الله ﷺ؟ ثم قال ابن عمر: نهانا عنها رسول الله ﷺ وما كنا مسافحين."],"takhrij":"حسن: رواه الطبراني في الأوسط (٩٢٩١).","grade":"حسن","chapter_ar":"باب ما جاء في نكاح المتعة وبيان نسخه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Awsat (9291).","chapter_en":"What Has Been Related About Temporary Marriage and the Clarification of Its Abrogation","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Salim ibn ʿAbd Allah said: ʿAbd Allah ibn ʿUmar was approached and told: Ibn ʿAbbas orders temporary marriage. Ibn ʿUmar said: Glory be to Allah. I do not think Ibn ʿAbbas would do this. They said: Yes, he does order it. So Ibn ʿUmar said: Was Ibn ʿAbbas anything but a young boy when the Messenger of Allah ﷺ was alive? Then Ibn ʿUmar said: The Messenger of Allah ﷺ forbade it, and we were not fornicators."]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":9291},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":9295,"n":9280}]},{"num":6476,"demo":false,"sanad":"","matn":["عن أبي الزبير قال: سمعت جابر بن عبد الله يقول: كنا نستمتع بالقبضة من التمر والدقيق الأيامَ على عهد رسول الله ﷺ وأبي بكر، حتى نهى عنه عمر في شأن عمرو بن حريث."],"takhrij":"صحيح: رواه مسلم (١٦:١٤٠٥).","grade":"صحيح","chapter_ar":"باب من قال: إن عمر بن الخطاب هو الذي نهى عن المتعة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1405 no. 16).","chapter_en":"Those Who Said That ʿUmar ibn al-Khattab Was the One Who Forbade Temporary Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["Abu al-Zubayr said: I heard Jabir ibn ʿAbd Allah say: We used to contract temporary marriage for a handful of dates and flour for a number of days during the time of the Messenger of Allah ﷺ and Abu Bakr, until ʿUmar forbade it in the case of ʿAmr ibn Hurayth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":16}]},{"num":6477,"demo":false,"sanad":"","matn":["عن عاصم بن أبي نضرة قال: كنت عند جابر بن عبد الله فأتاه آت فقال: ابن عباس وابن الزبير اختلفا في المستمتعين. فقال جابر: فعلناهما مع رسول الله ﷺ ثم نهانا عنهما عمر، فلم نَعُدْ لهما."],"takhrij":"صحيح: رواه مسلم (١٧:١٤٠٥).","grade":"صحيح","chapter_ar":"باب من قال: إن عمر بن الخطاب هو الذي نهى عن المتعة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1405 no. 17).","chapter_en":"Those Who Said That ʿUmar ibn al-Khattab Was the One Who Forbade Temporary Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":12,"content":{"translation":{"en":["ʿAsim ibn Abi Nadrah said: I was with Jabir ibn ʿAbd Allah when someone came to him and said: Ibn ʿAbbas and Ibn al-Zubayr have differed concerning the two temporary matters. Jabir said: We did both of them with the Messenger of Allah ﷺ, then ʿUmar forbade us from them, and we did not return to them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":17}]},{"num":6478,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، أن رسول الله ﷺ نهى عن الشغار. والشغار أن يُزوّج الرجل بنته على أن يُزوّجه الآخر ابنته. ليس بينهما صداق."],"takhrij":"متفق عليه: رواه مالك (٢٤) والبخاري (٥١١٢)، ومسلم (٥٧:١٤١٥).","grade":"متفق عليه","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (24), al-Bukhari (5112), and Muslim (1415 no. 57).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar narrated that the Messenger of Allah ﷺ forbade shighar. Shighar is when a man marries off his daughter on condition that the other man marries him his daughter, with no dowry between them."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":24},{"key":"bukhari","label":"البخاري","number":5112},{"key":"muslim","label":"مسلم","number":57}]},{"num":6479,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نهى رسول الله ﷺ عن الشغار.","زاد ابن نُمير: والشغار أن يقول الرجل للرجل: زوَّجني ابنتك، وأزوّجك ابنتي، أو زوّجني أختَك، وأزوّجك أختي."],"takhrij":"صحيح: رواه مسلم (١٤١٦).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1416).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ forbade shighar.","Ibn Numayr added: Shighar is that a man says to another man: Marry your daughter to me and I will marry my daughter to you; or marry your sister to me and I will marry my sister to you."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1416}]},{"num":6480,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: نهى رسول الله ﷺ عن الشغار."],"takhrij":"صحيح: رواه مسلم (١٤١٧).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1417).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: The Messenger of Allah ﷺ forbade shighar."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1417}]},{"num":6481,"demo":false,"sanad":"","matn":["عن أنس قال: قال رسول الله ﷺ: (( لا شغار في الإسلام ))."],"takhrij":"صحيح: رواه ابن ماجه (١٨٨٥) وابن حبان في صحيحه (٤١٥٤).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (1885) and Ibn Hibban in his Sahih (4154).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “There is no shighar in Islam.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1885},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4154}]},{"num":6482,"demo":false,"sanad":"","matn":["عن عمران بن حصين أن رسول الله ﷺ قال: (( لا شغار في الإسلام ))."],"takhrij":"صحيح: رواه الإمام أحمد (١٩٩٦٢).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Imam Ahmad (19962).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿImran ibn Husayn narrated that the Messenger of Allah ﷺ said: “There is no shighar in Islam.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":19962},{"key":"ahmad","label":"مسند الإمام أحمد","number":19962,"n":19962}]},{"num":6483,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: قضى رسول الله ﷺ قال: (( لا شغار في الإسلام ))."],"takhrij":"حسن: رواه أحمد (٧٠٢٧).","grade":"حسن","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (7027).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: The Messenger of Allah ﷺ ruled: “There is no shighar in Islam.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":7027,"n":7027}]},{"num":6484,"demo":false,"sanad":"","matn":["عن العباس بن عبد الله بن عباس:","أنه أنكح عبد الرحمن بن الحكم ابنته، وأنكحه عبد الرحمن ابنته، وقد كانا جعلا صداقًا.","فكتب معاوية بن أبي سفيان - وهو خليفة - إلى مروان يأمره بالتفريق بينهما، وقال في كتابه:","هذا الشغار الذي نهى عنه رسول الله ﷺ."],"takhrij":"حسن: رواه أبو داود (٢٠٧٥).","grade":"حسن","chapter_ar":"باب النهي عن نكاح الشغار","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2075).","chapter_en":"The Prohibition of Shighar Marriage","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":13,"content":{"translation":{"en":["Al-ʿAbbās ibn ʿAbdullāh ibn ʿAbbās reported:","He married his daughter to ʿAbd al-Raḥmān ibn al-Ḥakam, and ʿAbd al-Raḥmān married his daughter to him, and they had stipulated a dowry.","Muʿāwiyah ibn Abī Sufyān, who was the caliph at the time, wrote to Marwān ordering him to separate the two marriages. He wrote:","“This is the shighār that the Messenger of Allah ﷺ prohibited.”"]},"buhuth":{"ar":["وقوله: «وقد كانا جعلا صداقًا» أي جعلا مع الشغار صداقًا. ولكن إن أنكح ابنته وأنكحه ابنته مع الصداق، فخرج من الشغار المنهي عنه."],"en":["The statement, “they had stipulated a dowry,” means that they included a dowry together with the shighār arrangement. However, if each man marries his daughter to the other while each marriage has its own proper dowry, then it no longer falls under the prohibited form of shighār."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2075}]},{"num":6485,"demo":false,"sanad":"","matn":["عن نبيه بن وهب - أخي بني عبد الدار - : أن عمر بن عبيد الله أرسل إلى أبان بن عثمان - وأبان يومئذ أمير الحاج - : وهما محرمان إني قد أردت أن أنكح طلحةَ بنَ عمر بنت شيبة بن جبير وأردت أن تحضر، فأنكر ذلك عليه أبان وقال: سمعت عثمان بن عفان يقول: قال رسول الله ﷺ: (( لا يَنكح المحرم، ولا يُنكح، ولا يخطب ))."],"takhrij":"صحيح: رواه مالك (٧٠) ومسلم (١٤٠٩).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح المحرم وخطبته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (70) and Muslim (1409).","chapter_en":"The Prohibition of Marriage and Betrothal While in Ihram","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Nubayh ibn Wahb — the ally of Banu ʿAbd al-Dar — said: ʿUmar ibn ʿUbayd Allah sent a message to Aban ibn ʿUthman — and Aban was then the leader of the pilgrims — while both of them were in ihram: I wish to marry Talhah ibn ʿUmar to the daughter of Shaybah ibn Jubayr, and I want you to attend. Aban objected to that and said: I heard ʿUthman ibn ʿAffan say: The Messenger of Allah ﷺ said: “The one in ihram must neither marry, nor have someone married on his behalf, nor propose.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":70},{"key":"muslim","label":"مسلم","number":1409}]},{"num":6486,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول الله ﷺ قال: (( لا يَنكح المحرمُ ولا يخطبُ، ولا يُخطَب عليه، ولا يبع أحدُكم على بيع أخيه، ولا يخطبْ على خِطبة أخيه حتى يأذن له ))."],"takhrij":"صحيح: رواه الطبراني في الأوسط (٥١٤).","grade":"صحيح","chapter_ar":"باب النهي عن نكاح المحرم وخطبته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat (514).","chapter_en":"The Prohibition of Marriage and Betrothal While in Ihram","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “The one in ihram must neither marry nor propose, nor should a proposal be made on his behalf. And none of you should sell over the sale of his brother, nor propose over the proposal of his brother until he gives him permission.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط","label":"الطبراني في الأوسط","number":514},{"key":"sh28171","label":"المعجم الأوسط للطبراني","number":510,"n":504}]},{"num":6487,"demo":false,"sanad":"","matn":["عن عائشة قالت: جاءت امرأة رفاعة إلى النبي ﷺ فقالت: كنت عند رفاعة، فطلقني فبتّ طلاقي، فتزوجت عبد الرحمن بن الزبير، وإن ما معه مثل هدبة الثوب، فتبسم رسول الله ﷺ، فقال: (( أتريدين أن ترجعي إلى رفاعة؟ لا، حتى تذوقي عُسيلتَه، ويذوق عُسيلتَكِ )).","قالت: وأبو بكر عنده، وخالد بالباب ينتظر أن يؤذن له. فنادى: يا أبا بكر، ألا تسمعُ هذه ما تجهر به عند رسول الله ﷺ."],"takhrij":"متفق عليه: رواه البخاري (٥٢٦٠)، ومسلم (١١١:١٤٣٣) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم نكاح المطلقة البتة حتى تتزوج زوجا غيره ويطأها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5260) and Muslim (1433 no. 111). The wording is that of Muslim.","chapter_en":"The Prohibition of Remarrying a Woman Divorced Irrevocably Until She Marries Another Husband and He Has Intercourse with Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: The wife of Rifaʿah came to the Prophet ﷺ and said: I was married to Rifaʿah, and he divorced me with a final irrevocable divorce. Then I married ʿAbd al-Rahman ibn al-Zubayr, but what he has is like the fringe of a garment. The Messenger of Allah ﷺ smiled and said: “Do you want to return to Rifaʿah? No, not until you taste his sweetness and he tastes your sweetness.”","She said: Abu Bakr was with him, and Khalid was at the door waiting to be given permission. So he called out: O Abu Bakr, do you not hear what this woman says openly in front of the Messenger of Allah ﷺ?"]},"buhuth":{"ar":["وعبد الرحمن بن الزبير بن باطا القرظي قتل أبوه في غزوة بني قريظة، وعبد الرحمن صحابي صغير، ولم أجد له ذكرا في غير هذا الحديث.","وأما رفاعة فهو رفاعة بن سموأل القرظي."],"en":["ʿAbd al-Rahman ibn al-Zubayr ibn Bata al-Qurazi had a father who was killed during the campaign of Banu Qurayzah. ʿAbd al-Rahman was a young Companion, and I have not found mention of him outside this hadith.","As for Rifaʿah, he was Rifaʿah ibn Samu’al al-Qurazi."]},"intro":{"ar":["قال الله تعالى: ( فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ ) [البقرة: ٢٣٠]","قوله: ( حَتَّى تَنكِحَ زَوْجًا غَيْرَهُ ) مطلق، ويقيده حديث عائشة بأن المراد به الوطء على رأي الجمهور، ومن خالفه لا يعتد به."],"en":["Allah the Exalted said: “Then if he divorces her, she is not lawful for him afterward until she marries another husband.” [Surat al-Baqarah 2:230]","His statement, “until she marries another husband,” is general, and the hadith of ʿA’ishah qualifies it by showing that what is meant, according to the majority, is actual intercourse. The view of those who disagree is not given weight."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5260},{"key":"muslim","label":"مسلم","number":111}]},{"num":6488,"demo":false,"sanad":"","matn":["عن عائشة قالت: طلّق رجلٌ امرأته ثلاثاً، فتزوجها رجل ثم طلّقها قبل أن يدخل بها، فأراد زوجُها الأول أن يتزوّجها. فسئلَ رسول الله ﷺ عن ذلك؟ فقال: (( لا، حتى يذوق الآخر من عُسيلتها ما ذاق الأولُ ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٦١)، ومسلم (١١٥:١٤٣٣)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب تحريم نكاح المطلقة البتة حتى تتزوج زوجا غيره ويطأها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5261) and Muslim (1433 no. 115). The wording is that of Muslim.","chapter_en":"The Prohibition of Remarrying a Woman Divorced Irrevocably Until She Marries Another Husband and He Has Intercourse with Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["ʿA’ishah said: A man divorced his wife three times, then another man married her and divorced her before consummating the marriage. Her first husband wanted to marry her again, so the Messenger of Allah ﷺ was asked about that, and he said: “No, not until the latter tastes of her sweetness what the former tasted.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5261},{"key":"muslim","label":"مسلم","number":115}]},{"num":6489,"demo":false,"sanad":"","matn":["عن عكرمة، أن رفاعة طلق امرأته، فتزوجها عبد الرحمن بن الزبير القرظي، قالت عائشة: وعليها خمار أخضر، فشكتْ إليها، وأرتها خضرة بجلدِها، فلما جاء رسول الله ﷺ والنساء ينصر بعضُهن بعضا، قالت عائشة: ما رأيتُ مثل ما يلقى المؤمناتُ، لجلدُها أشدُّ خضرةً من ثوبها.","قال: وسمع أنها قد أتتْ رسول الله ﷺ فجاء، ومعه ابنان له من غيرها. قالت: والله مالي إليه من ذنب، إلا أن ما معه ليس بأغنى عني من هذه، وأخذتْ هدبةً من ثوبها. فقال: كذبتِ والله يا رسول الله، إني لأنفضها نفض الأديم، ولكنها ناشزٌ، تريد رفاعة، فقال رسول الله ﷺ: (( فإن كان ذلك لم تحلّي له، أو: لم تصلحي له، حتى يذوقَ من عسيلتك )). قال: وأبصر معه ابنين، فقال: (( بنوك هؤلاء؟ )) قال: نعم.","قال: (( هذا الذي تزعمين ما تزعمين، فوالله، لهم أشبه به من الغراب بالغراب )).","وقولها: “وأرتها خضرة بجلدِها” كان ذلك بضرب عبد الرحمن لها، وفيه أن للزوج ضرب زوجته عند نشوزها.","وقوله: (( فوالله، لهم أشبه به من الغراب بالغراب )) أي أن الابنين أشبه بعبد الرحمن من الغراب بالغراب، فأثبت النبي ﷺ فيه الحكم بالدليل حيث استدل بشبههما به على كذبها في دعواها.","وفيه دليل على الحكم بالقافة، وبه قال جمهور أهل العلم، وفيه أنه يستحب نكاح البكر؛ لأنها تظن كل الرجال سواءً بخلاف الثيب."],"takhrij":"صحيح: رواه البخاري (٥٨٢٥).","grade":"صحيح","chapter_ar":"باب تحريم نكاح المطلقة البتة حتى تتزوج زوجا غيره ويطأها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5825).","chapter_en":"The Prohibition of Remarrying a Woman Divorced Irrevocably Until She Marries Another Husband and He Has Intercourse with Her","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":15,"content":{"translation":{"en":["ʿIkrimah narrated that Rifaʿah divorced his wife, and then ʿAbd al-Rahman ibn al-Zubayr al-Qurazi married her. ʿA’ishah said: She was wearing a green veil, and she complained to her and showed her the green bruising on her skin. When the Messenger of Allah ﷺ came, and women were supporting one another, ʿA’ishah said: I have not seen anything like what believing women suffer; indeed, the skin of this woman was greener than her garment.","He said: He heard that she had come to the Messenger of Allah ﷺ, so he came, and he had with him two sons from another wife. She said: By Allah, I have no complaint against him except that what he has is no more useful to me than this, and she took a fringe from her garment. He said: You have lied, by Allah, O Messenger of Allah. Indeed I satisfy her fully like the shaking of a leather skin, but she is defiant and wants Rifaʿah. So the Messenger of Allah ﷺ said: “If that is so, then you are not lawful for him,” or, “you are not suitable for him, until he tastes your sweetness.” Then he saw that the man had two sons with him, so he said: “Are these your sons?” He said: Yes.","He said: “This is the one about whom you are claiming what you are claiming? By Allah, they resemble him more than one crow resembles another crow.”","Her statement, “and she showed her the green bruising on her skin,” means that this had been caused by ʿAbd al-Rahman beating her, and in it is evidence that a husband may strike his wife when she is defiantly disobedient.","And his statement, “By Allah, they resemble him more than one crow resembles another crow,” means that the two sons resembled ʿAbd al-Rahman more than one crow resembles another. So the Prophet ﷺ established the ruling here by evidence, since he used their resemblance to him as proof that she was lying in her claim.","And in it is evidence for judging by physical resemblance, and this is the view of the majority of the scholars. And in it is also evidence that marrying a virgin is recommended, because she assumes all men are alike, unlike a previously married woman."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5825}]},{"num":6490,"demo":false,"sanad":"","matn":["عن ابن عباس: كان المشركون على منزلتين من النبي ﷺ والمؤمنين، كانوا مشركي أهل حرب يقاتلهم ويقاتلونه، ومشركي أهل عهد لا يقاتلهم ولا يقاتلونه. وكان إذا هاجرتْ امرأة من أهل الحرب لم تُخطب حتى تحيض وتطهر، فإذا طهرتْ حل لها النكاح، فإن هاجر زوجُها قبل أن تُنكح رُدّت إليه، وإن هاجر عبد منهم أو أمة فهما حُرّان، ولهما ما للمهاجرين، وإن هاجر عبد أو أمة للمشركين أهل العهد لم يردوا، ورُدّت أثمانهم."],"takhrij":"صحيح: رواه البخاري (٥٢٨٦).","grade":"صحيح","chapter_ar":"باب جواز نكاح المشركة إذا أسلمت بعد انقضاء العدة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5286).","chapter_en":"The Permissibility of Marrying a Polytheist Woman If She Accepts Islam After the Waiting Period Ends","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿAbbas said: The polytheists were of two categories in relation to the Prophet ﷺ and the believers. They were either polytheists from the people of war, whom he fought and who fought him, or polytheists from the people of treaty, whom he did not fight and who did not fight him. If a woman emigrated from the people of war, she would not be proposed to until she menstruated and then became pure. Once she became pure, marriage to her became lawful. If her husband emigrated before she married, she was returned to him. If a male slave or female slave from them emigrated, then both became free and had the same rights as the emigrants. But if a male slave or female slave belonging to the treaty polytheists emigrated, they were not returned, though their price was returned."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5286}]},{"num":6491,"demo":false,"sanad":"","matn":["عن أبي الدرداء، عن النبي ﷺ أنه أتى بامرأة مُجِحٍّ على باب فسطاط، فقال: (( لعله يريد أن يلمّ بها؟ )) فقالوا: نعم، فقال رسول الله ﷺ: (( لقد هممت أن ألعنه لعناً يدخل معه قبره، كيف يورثه وهو لا يحل له، كيف يستخدمه وهو لا يحل له ))."],"takhrij":"صحيح: رواه مسلم (١٤٤١).","grade":"صحيح","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1441).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Abu al-Darda’ narrated that the Prophet ﷺ came upon a woman who was heavily pregnant at the door of a tent, and he said: “Perhaps he intends to have intercourse with her?” They said: Yes. So the Messenger of Allah ﷺ said: “I nearly cursed him with a curse that would enter with him into his grave. How can he make him inherit from him when he is not lawful for him? How can he enslave him when he is not lawful for him?”"]},"buhuth":{"ar":["قوله: (( مُجِحّ )) الحامل المقرب. وفيه بيان أن وطء الحبالى من السبايا لا يجوز حتى يضعن حملهن."],"en":["His statement, “mujih,” means a woman whose pregnancy is advanced. In this is clarification that intercourse with pregnant female captives is not permissible until they give birth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1441}]},{"num":6492,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، أن رسول الله ﷺ يوم حنين بعث جيشاً إلى أوطاس، فلقوا عدوًا فقاتلوهم، فظهروا عليهم، وأصابوا لهم سبايا، فكأن ناساً من أصحاب رسول الله ﷺ تحرّجوا من غشيانهن من أجل أزواجهن من المشركين، فأنزل الله عز وجل في ذلك: (وَٱلْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ) [النساء: ٢٤] أي فهن لكم حلال إذا انقضت عدتهن."],"takhrij":"صحيح: رواه مسلم (١٤٥٦).","grade":"صحيح","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1456).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that on the Day of Hunayn the Messenger of Allah ﷺ sent an army to Awtas. They met the enemy, fought them, prevailed over them, and took female captives from them. It was as though some of the Companions of the Messenger of Allah ﷺ felt uneasy about having intercourse with them because of their polytheist husbands. Then Allah, Mighty and Majestic, revealed concerning that: “And married women are forbidden to you except those whom your right hands possess” [al-Nisa’ 4:24], meaning that they become lawful for you once their waiting period has ended."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1456}]},{"num":6493,"demo":false,"sanad":"","matn":["عن ابن عباس قال: نهى رسول الله ﷺ عن بيع المغانم حتى تُقسم، وعن الحبالى أن يُوطأن، حتى يضعن ما في بطونهن، وعن لحم كل ذي ناب من السباع."],"takhrij":"حسن: رواه النسائي (٤٦٤٥) والدراقطني (٦٩-٦٨/٣) والحاكم (١٣٧/٢).","grade":"حسن","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (4645), al-Daraqutni (3/68–69), and al-Hakim (2/137).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿAbbas said: The Messenger of Allah ﷺ forbade the sale of war booty before it is divided, and he forbade pregnant women from being had intercourse with until they deliver what is in their wombs, and he forbade the meat of every beast with fangs."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4645},{"key":"الدراقطنی","label":"الدراقطني","number":69},{"key":"hakim","label":"المستدرك على الصحيحين","number":2611,"n":2597}]},{"num":6494,"demo":false,"sanad":"","matn":["عن رويفع بن ثابت الأنصاري عن النبي ﷺ قال: (( لا يحل لامرئ يؤمن بالله واليوم الآخر أن يقع على امرأة من السبي حتى يستبرئها ))."],"takhrij":"حسن: رواه أبو داود (٢٧٠٨) والترمذي (١١٣١) وحسّنه، وأحمد (١٦٩٩٢) وابن حبان (٤٨٥٠).","grade":"حسن","chapter_ar":"باب النهي عن وطء الحامل من السبايا والجارية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2708), al-Tirmidhi (1131), who graded it hasan, Ahmad (16992), and Ibn Hibban (4850).","chapter_en":"The Prohibition of Having Intercourse with a Pregnant Captive or Slave Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":18,"content":{"translation":{"en":["Ruwayfiʿ ibn Thabit al-Ansari narrated from the Prophet ﷺ that he said: “It is not lawful for a man who believes in Allah and the Last Day to have intercourse with a woman from the captives until he establishes that her womb is clear.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2708},{"key":"tirmidhi","label":"الترمذي","number":1131},{"key":"ibnhibban","label":"ابن حبان","number":4850},{"key":"ahmad","label":"مسند الإمام أحمد","number":16992,"n":16992}]},{"num":6495,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده:","أن مرثد بن أبي مرثد الغنوي، وكان رجلًا شديدًا، وكان يحمل الأسارى من مكة إلى المدينة، قال:","فدعوت رجلًا لأحمله، وكان بمكة بغي يقال لها: عناق، وكانت صديقته.","خرجت فرأت سوادي في ظل الحائط، فقالت:","من هذا؟ مرثد؟ مرحبًا وأهلًا يا مرثد. انطلق الليلة فبت عندنا في الرحل.","قلت:","يا عناق، إن رسول الله ﷺ حرم الزنا.","قالت:","يا أهل الخيام! هذا الدلدل الذي يحمل أسراءكم من مكة إلى المدينة.","فسلكت الخندمة، فطلبني ثمانية، فجاؤوا حتى قاموا على رأسي، فبالوا فطار بولهم علي، وأعماهم الله عني.","فجئت إلى صاحبي فحملته، فلما انتهيت به إلى الأراك، فككت عنه كبله.","فجئت إلى رسول الله ﷺ فقلت:","يا رسول الله، أنكح عناق؟","فسكت عني، فنزلت:","﴿وَالزَّانِيَةُ لَا يَنْكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ﴾  [النور: ٣]","فقرأها علي وقال:","«لَا تَنْكِحْهَا»."],"takhrij":"حسن: رواه أبو داود (٢٠٥١)، والنسائي (٣٢٢٨)، والترمذي (٣١٧٦) وحسنه، والطحاوي في مشكل الآثار (٤٥٥٢).","grade":"حسن","chapter_ar":"باب النهي عن نكاح الزانية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2051), al-Nasāʾī (3228), al-Tirmidhī (3176), who graded it Hasan, and al-Ṭaḥāwī in Mushkil al-Āthār (4552).","chapter_en":"The Prohibition of Marrying a Fornicating Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb reported from his father, from his grandfather:","Marthad ibn Abī Marthad al-Ghanawī was a strong man who used to carry Muslim captives from Makkah to Madinah.","He said:","I arranged to carry a man out, and in Makkah there was a prostitute called ʿAnāq who had formerly been my companion.","She came out and saw my silhouette in the shadow of the wall and said:","“Who is this? Marthad? Welcome, Marthad! Come tonight and spend the night with us at the camp.”","I replied:","“O ʿAnāq, the Messenger of Allah ﷺ has forbidden fornication.”","She cried out:","“O people of the tents! This is the duldul who carries your captives from Makkah to Madinah!”","I took the route of al-Khandamah, and eight men pursued me. They came until they stood directly above my head and urinated, and their urine splashed upon me, but Allah blinded them to my presence.","I then went to my companion and carried him away. When I reached al-Arāk, I removed his shackles.","Then I came to the Messenger of Allah ﷺ and asked:","“O Messenger of Allah, may I marry ʿAnāq?”","He remained silent until the verse was revealed:","“The fornicatress is not married except by a fornicator or a polytheist.”  [al-Nūr: 3]","He recited it to me and said:","“Do not marry her.”"]},"buhuth":{"ar":["قال الأزرقي:","«الدلدل»: القنفذ الذي أكثر ما يظهر في الليل، ويخفي رأسه.","و«الخندمة»: جبل في ظهر أبي قبيس."],"en":["Al-Azraqī said:","Al-duldul means a hedgehog, which most often appears at night and conceals its head.","Al-Khandamah is a mountain behind Abū Qubays."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2051},{"key":"nasai","label":"النسائي","number":3228},{"key":"tirmidhi","label":"الترمذي","number":3176},{"key":"الطحاوی/مشکل_الاثار","label":"الطحاوي في مشكل الآثار","number":4552}]},{"num":6496,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو أن رجلاً من المسلمين استأذن رسول الله ﷺ في امرأة يقال لها: “أم مهزول” وكانت تُسافح، وتشترط للرجل يتزوجها أن تكفيه النفقة، فاستأذن رسول الله ﷺ، أو ذكر له أمرها. قال: فقرأ عليه نبي الله ﷺ: (وَٱلزَّانِيَةُ لَا يَنكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ) [النور: ٣]."],"takhrij":"حسن: رواه أحمد (٦٤٨٠) والحاكم (١٩٤-١٩٣/٢) والبيهقي (١٥٣/٧).","grade":"حسن","chapter_ar":"باب النهي عن نكاح الزانية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (6480), al-Hakim (2/193–194), and al-Bayhaqi (7/153).","chapter_en":"The Prohibition of Marrying a Fornicating Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAmr narrated that a Muslim man sought the permission of the Messenger of Allah ﷺ regarding a woman named Umm Mahzul. She used to commit fornication, and she would stipulate to any man who married her that she would suffice him financially. So he sought the permission of the Messenger of Allah ﷺ, or her matter was mentioned to him. He said: Then the Prophet of Allah ﷺ recited to him: “The fornicatress — none marries her except a fornicator or a polytheist” [al-Nur 24:3]."]}},"tuhfa":{},"refs":[{"key":"hakim","label":"الحاكم","number":194},{"key":"البیہقی","label":"البيهقي","number":153},{"key":"ahmad","label":"مسند الإمام أحمد","number":6480,"n":6480}]},{"num":6497,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ: (( لا ينكح الزاني المجلود إلا مثله ))."],"takhrij":"حسن: رواه أبو داود (٢٠٥٢) وأحمد (٨٣٠٠) والحاكم (١٦٦/٢).","grade":"حسن","chapter_ar":"باب النهي عن نكاح الزانية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2052), Ahmad (8300), and al-Hakim (2/166).","chapter_en":"The Prohibition of Marrying a Fornicating Woman","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":19,"content":{"translation":{"en":["Abu Hurairah said: The Messenger of Allah ﷺ said: “A flogged fornicator marries none but one like himself.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2052},{"key":"ahmad","label":"مسند الإمام أحمد","number":8300,"n":8300},{"key":"hakim","label":"المستدرك على الصحيحين","number":2700,"n":2686}]},{"num":6498,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: قال النبي ﷺ: (( أيما عبد تزوج بغير إذن سيده، فهو عاهر ))."],"takhrij":"حسن: رواه أبو داود (٢٠٧٨) والترمذي (١١١١،١١١٢) وابن ماجه (١٩٥٩) وصحّحه الحاكم (١٩٤/٢).","grade":"حسن","chapter_ar":"باب لا يصح نكاح العبد بغير إذن سيده","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2078), al-Tirmidhi (1111, 1112), Ibn Majah (1959), and authenticated by al-Hakim (2/194).","chapter_en":"The Marriage of a Slave Is Not Valid Without the Permission of His Master","part_en":"The Book of Marriage","group_ar":"جموع ما جاء في الأنكحة المنهية في الإسلام","group_en":"Collection of What Has Been Related About Marriages Forbidden in Islam","part_no":24,"group_no":4,"chapter_no":20,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: The Prophet ﷺ said: “Any slave who marries without the permission of his master is a fornicator.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2078},{"key":"tirmidhi","label":"الترمذي","number":1111},{"key":"ibnmajah","label":"ابن ماجه","number":1959},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":194}]},{"num":6499,"demo":false,"sanad":"","matn":["عن أنس أن عبد الرحمن بن عوف تزوج امرأة على وزن نواة، فرأى النبي ﷺ بشاشة العُرس، فسأله، فقال: إني تزوجت امرأة على وزن نواة."],"takhrij":"متفق عليه: رواه البخاري (٥١٤٨)، ومسلم (٨٢:١٤٢٧). وزاد البخاري: على وزن نواة من ذهب.","grade":"متفق عليه","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5148) and Muslim (1427 no. 82). Al-Bukhari added: the weight of a date-stone of gold.","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Anas narrated that ʿAbd al-Rahman ibn ʿAwf married a woman for the weight of a date-stone. The Prophet ﷺ saw the signs of marriage happiness on him and asked him, and he said: I have married a woman for the weight of a date-stone."]},"buhuth":{"ar":["ونواة: قيمتها خمسة دراهم. وفي رواية قال أنس: فلقد رأيته قسّم لكل امرأة من نسائه بعد موته مائة ألف."],"en":["A date-stone was valued at five dirhams. In another narration, Anas said: I indeed saw that after his death, one hundred thousand was apportioned to each of his wives."]},"intro":{"ar":["قال الله تعالى: (وَءَاتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً) [النساء: ٤]","وقال تعالى: (وَإِنْ أَرَدتُّمُ ٱسْتِبْدَالَ زَوْجٍ مَّكَانَ زَوْجٍ وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُواْ مِنْهُ شَيْـًٔا) [النساء: ٢٠]","وقال تعالى: (وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ) [البقرة: ٢٣٧]"],"en":["Allah the Exalted said: “Give the women their dowries graciously.” [al-Nisa’ 4:4]","And He said: “And if you intend to replace one wife with another and you have given one of them a great amount, do not take anything from it.” [al-Nisa’ 4:20]","And He said: “And if you divorce them before you have touched them, while you have already specified for them an obligation, then half of what you specified is due.” [al-Baqarah 2:237]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5148},{"key":"muslim","label":"مسلم","number":82}]},{"num":6500,"demo":false,"sanad":"","matn":["عن سهل بن سعد قال:","جاءت امرأة إلى رسول الله ﷺ فقالت: يا رسول الله، جئت أهب لك نفسي.","فنظر إليها رسول الله ﷺ فصعّد النظر فيها وصوّبه، ثم طأطأ رأسه.","فلما رأت المرأة أنه لم يقض فيها شيئًا جلست، فقام رجل من أصحابه فقال: يا رسول الله، إن لم يكن لك بها حاجة فزوّجنيها.","فقال:","«هَلْ عِنْدَكَ شَيْءٌ؟»","قال: لا والله يا رسول الله.","قال:","«اذْهَبْ إِلَى أَهْلِكَ فَانْظُرْ هَلْ تَجِدُ شَيْئًا».","فذهب ثم رجع فقال: لا والله، ما وجدت شيئًا.","فقال رسول الله ﷺ:","«انْظُرْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ».","فذهب ثم رجع فقال: لا والله يا رسول الله، ولا خاتمًا من حديد، ولكن هذا إزاري - قال سهل: ما له رداء - فلها نصفه.","فقال رسول الله ﷺ:","«مَا تَصْنَعُ بِإِزَارِكَ؟ إِنْ لَبِسْتَهُ لَمْ يَكُنْ عَلَيْهَا مِنْهُ شَيْءٌ، وَإِنْ لَبِسَتْهُ لَمْ يَكُنْ عَلَيْكَ مِنْهُ شَيْءٌ».","فجلس الرجل، حتى إذا طال مجلسه قام، فرآه رسول الله ﷺ مولّيًا، فأمر به فدعي له.","فلما جاء قال:","«مَا مَعَكَ مِنَ الْقُرْآنِ؟»","قال: معي سورة كذا وسورة كذا، عدّدها.","فقال:","«تَقْرَؤُهُنَّ عَنْ ظَهْرِ قَلْبٍ؟»","قال: نعم.","قال:","«اذْهَبْ، فَقَدْ مَلَّكْتُكَهَا بِمَا مَعَكَ مِنَ الْقُرْآنِ»."],"takhrij":"متفق عليه: رواه البخاري (٥٠٨٧)، ومسلم (١٤٢٥).","grade":"متفق عليه","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5087) and Muslim (1425).","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd reported:","A woman came to the Messenger of Allah ﷺ and said:","“O Messenger of Allah, I have come to offer myself to you.”","The Messenger of Allah ﷺ looked at her, raising and lowering his gaze, then lowered his head.","When the woman saw that he had made no decision concerning her, she sat down.","A man from among his Companions stood up and said:","“O Messenger of Allah, if you have no need of her, then marry her to me.”","He asked:","“Do you have anything?”","He replied:","“No, by Allah, O Messenger of Allah.”","He said:","“Go to your family and see whether you can find anything.”","He went and then returned and said:","“No, by Allah, I found nothing.”","The Messenger of Allah ﷺ said:","“Look, even if it is only an iron ring.”","He went and returned and said:","“No, by Allah, O Messenger of Allah, not even an iron ring. But I have this lower garment”—Sahl said that he had no upper garment—“and she may have half of it.”","The Messenger of Allah ﷺ said:","“What would she do with your lower garment? If you wear it, she will have none of it; and if she wears it, you will have none of it.”","The man sat down. After he had remained seated for a long time, he got up to leave.","The Messenger of Allah ﷺ saw him turning away and ordered that he be called back.","When he returned, he asked:","“What do you know of the Qurʾān?”","He replied:","“I know such-and-such surah and such-and-such surah,” and he listed them.","He asked:","“Do you recite them from memory?”","He replied:","“Yes.”","He said:","“Go. I have married her to you for what you know of the Qurʾān.”"]},"buhuth":{"ar":["وفي لفظ مسلم:","«انْطَلِقْ، فَقَدْ زَوَّجْتُكَهَا، فَعَلِّمْهَا مِنَ الْقُرْآنِ»."],"en":["In Muslim’s wording:","“Go, for I have married her to you, so teach her from the Qurʾān.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5087},{"key":"muslim","label":"مسلم","number":1425}]},{"num":6501,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: جاء رجل إلى النبي ﷺ فقال: إني تزوجت امرأة من الأنصار. فقال له النبي ﷺ: (( هل نظرت إليها؟ فإن في عيون الأنصار شيئا )) قال: قد نظرت إليها. قال: (( على كم تزوجتها؟ )) قال: على أربع أواق، فقال له النبي ﷺ: (( على أربع أواق، كأنما تَنْحتون الفضة من عُرض هذا الجبل، ما عندنا ما نعطيك، ولكن عسى أن نبعثك في بعث تصيب منه )) قال: فبعث بعثاً إلى بني عبس، بعث ذلك الرجل فيهم."],"takhrij":"صحيح: رواه مسلم (٧٥:١٤٢٤). وفيه كراهية إكثار المهر بالنسبة إلى حال الزوج.","grade":"صحيح","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1424 no. 75). In this is evidence for the dislike of an excessive dowry relative to the husband’s condition.","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: A man came to the Prophet ﷺ and said: I have married a woman from the Ansar. The Prophet ﷺ said to him: “Did you look at her? For indeed there is something in the eyes of the Ansar.” He said: I did look at her. He said: “For how much did you marry her?” He said: For four uqiyyahs. The Prophet ﷺ said to him: “For four uqiyyahs? It is as though you are carving silver from the side of this mountain. We do not have anything to give you, but perhaps we may send you on an expedition from which you may obtain something.” He said: Then he sent an expedition to Banu ʿAbs, and sent that man among them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":75}]},{"num":6502,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: كان الصداق إذ كان رسول الله ﷺ فينا عشرة أواق. وطبق بيديه وذلك أربع مائة."],"takhrij":"صحيح: رواه النسائي (٣٣٤٨) وأحمد (٨٨٠٧) والدار قطني (٢٢٢/٣) وصحّحه ابن حبان (٤٠٩٧).","grade":"صحيح","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3348), Ahmad (8807), al-Daraqutni (3/222), and authenticated by Ibn Hibban (4097).","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Abu Hurairah said: The dowry, when the Messenger of Allah ﷺ was among us, was ten uqiyyahs. And he clapped his hands together, and that was four hundred."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3348},{"key":"الدار_قطنی","label":"الدار قطني","number":222},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4097},{"key":"ahmad","label":"مسند الإمام أحمد","number":8807,"n":8807}]},{"num":6503,"demo":false,"sanad":"","matn":["عن عقبة بن عامر قال: قال رسول الله ﷺ: (( أحق الشروط أن توفوا بها ما استحللتم به الفروج ))."],"takhrij":"صحيح: رواه البخاري (٢٧٢١). أي من المهور الخاصة.","grade":"صحيح","chapter_ar":"باب وجوب الصداق وأنه لا حد لأكثره ولا لأقله وجوازه بتعليم القرآن","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2721). That is, among the conditions connected to dowries and marriage arrangements.","chapter_en":"The Obligation of the Dowry, That There Is No Fixed Maximum or Minimum for It, and the Permissibility of Making Teaching the Qur’an a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: The Messenger of Allah ﷺ said: “The conditions most deserving to be fulfilled are those by which you made the private parts lawful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2721}]},{"num":6504,"demo":false,"sanad":"","matn":["عن أبي سلمة بن عبد الرحمن أنه قال: سألت عائشة زوج النبي ﷺ كم كان صداق رسول الله ﷺ؟ قالت: كان صداقه لأزواجه ثنتي عشرة أوقيةً ونشًّا. قالت: أتدري ما النشّ؟ قال: قلت: لا. قالت: نصف أوقية، فتلك خمسمائة درهم، فهذا صداقُ رسول الله ﷺ لأزواجه."],"takhrij":"صحيح: رواه مسلم (١٤٢٦). وقوله: (( نشًّا )) هو اسم لعشرين درهما، أو هو بمعنى النصف من كل شيء.","grade":"صحيح","chapter_ar":"باب ما يستحب من القصد في الصداق","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1426). His statement, “nashsh,” is a term for twenty dirhams, or it means half of something.","chapter_en":"What Is Recommended of Moderation in the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Abu Salamah ibn ʿAbd al-Rahman said: I asked ʿA’ishah, the wife of the Prophet ﷺ, how much the dowry of the Messenger of Allah ﷺ was. She said: His dowry to his wives was twelve uqiyyahs and a nashsh. She said: Do you know what a nashsh is? I said: No. She said: Half an uqiyyah. So that amounted to five hundred dirhams. That was the dowry of the Messenger of Allah ﷺ for his wives."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1426}]},{"num":6505,"demo":false,"sanad":"","matn":["عن أم حبيبة أنها كانت تحت عبيد الله بن جحش فمات بأرض الحبشة فزوّجها النجاشي النبيَّ ﷺ، وأمهرها عنه أربعة آلاف، وبعث بها إلى رسول الله ﷺ مع شرحبيل بن حسنة. ولم يبعث إليها رسول الله ﷺ بشيء، وكان مهر نسائه أربعمائة درهم.","قال أبو داود: حسنة هي أمه."],"takhrij":"صحيح: رواه أبو داود (٢١٠٧) والنسائي (٣٣٥٠) وأحمد (٢٧٤٠٨) والحاكم (١٨١/٢) والبيهقي (٢٣٢/٧).","grade":"صحيح","chapter_ar":"باب ما يستحب من القصد في الصداق","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2107), al-Nasa’i (3350), Ahmad (27408), al-Hakim (2/181), and al-Bayhaqi (7/232).","chapter_en":"What Is Recommended of Moderation in the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":2,"content":{"translation":{"en":["Umm Habibah had been married to ʿUbayd Allah ibn Jahsh, and he died in the land of Abyssinia. Then the Negus married her to the Prophet ﷺ and gave her, on his behalf, a dowry of four thousand. He sent her to the Messenger of Allah ﷺ with Sharhabil ibn Hasanah. The Messenger of Allah ﷺ did not send her anything, while the dowries of his other wives were four hundred dirhams.","Abu Dawud said: Hasanah was his mother."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2107},{"key":"nasai","label":"النسائي","number":3350},{"key":"hakim","label":"الحاكم","number":181},{"key":"البیہقی","label":"البيهقي","number":232},{"key":"ahmad","label":"مسند الإمام أحمد","number":27408,"n":27408}]},{"num":6506,"demo":false,"sanad":"","matn":["عن أنس أن رسول الله ﷺغزا، فصلينا عندها صلاةَ الغداة بغلس، فركب نبي الله ﷺ وركب أبو طلحة، وأنا رديفُ أبي طلحة، فأجرى نبي الله ﷺ في زقاق خيبر، وإنَّ ركبتي لتمسُّ فخذ نبي الله ﷺ ثم حسَر الإزار عن فخذه، حتى إني أنظرُ إلى بياض فخذ نبي الله ﷺ فلما دخل القرية قال: (( الله أكبر خربتْ خيبر، إنا إذا نزلنا بساحة قومٍ، فساء صباحُ المنذرين)). قالها ثلاثا، قال: وخرج القومُ إلى أعمالهم، فقالوا: محمد - قال عبد العزيز، وقال بعض أصحابنا: والخميس، يعني الجيشَ - فأصبناها عَنْوةً، فجُمعَ السبيُ، فجاء دحيةُ، فقال: يا نبي الله، أعطني جارية من السبّي، قال: (( اذهبُ فخُذْ جاريةً)) فأخذ صفيةَ بنت حُيَيّ، فجاء رجل إلى النبي ﷺ فقال: يا نبي الله، أعطيتَ دحيةً صفية بنت حيي، سيدةَ قريظة والنضير؟ لا تَصلح إلا لك، قال: (( ادعُوه بها )) فجاء بها، فلما نظر إليها النبي ﷺ قال: (( خُذْ جاريةً من السبي غيرها)) قال: فأعتقها النبي ﷺ وتزوّجها. فقال له ثابت: يا أباحمزة، ما أصدقها؟ قال: نفسها، أعتقها وتزوّجها، حتى إذا كان بالطريق جهّزتْها له أمُّ سُليم، فأهدتها له من الليل، فأصبح النبي ﷺ عروساً فقال: (( من كان عنده شيء فليجيء به )) وبسط نِطْعا، فجعل الرجل يجيء بالأقِط، وجعل الرجل يجيء بالتمر، وجعل الرجل يجيء بالسمن، قال: وأحسبه قد ذكر السويق، قال: فحاسوا حيْسا، فكانتْ وليمة رسول الله ﷺ عليها"],"takhrij":"متفق عليه: رواه البخاري (٣٧١)، ومسلم (٨٤:١٣٦٥).","grade":"متفق عليه","chapter_ar":"باب جعل العتق صداقا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (371) and Muslim (1365 no. 84).","chapter_en":"Making Emancipation the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ went out on a military expedition, and we prayed the dawn prayer there in the darkness before daylight. The Prophet of Allah ﷺ rode, and Abu Talhah rode, and I was riding behind Abu Talhah. The Prophet of Allah ﷺ urged his mount through the lanes of Khaybar, and my knee was touching the thigh of the Prophet of Allah ﷺ. Then he uncovered his thigh from his waist-wrapper until I could see the whiteness of the Prophet’s thigh. When he entered the town, he said, “Allah is the Greatest! Khaybar is ruined. When we descend in the courtyard of a people, evil is the morning of those who were warned.” He said this three times. The people had gone out to their work, and they said, “Muhammad!” ʿAbd al-ʿAziz said, and some of our companions said, “and the army,” meaning the army. So we conquered it by force, and the captives were gathered. Dihyah came and said, “O Prophet of Allah, give me a slave girl from the captives.” He said, “Go and take a slave girl.” So he took Safiyyah bint Huyayy. Then a man came to the Prophet ﷺ and said, “O Prophet of Allah, you gave Dihyah Safiyyah bint Huyayy, the chief lady of Qurayzah and al-Nadir. She is suitable for no one but you.” He said, “Bring him with her.” So he brought her. When the Prophet ﷺ looked at her, he said, “Take another slave girl from the captives besides her.” Then the Prophet ﷺ freed her and married her. Thabit said to him: O Abu Hamzah, what did he give her as her dowry? He said: Her own self. He freed her and married her. Then when they were on the road, Umm Sulaym prepared her for him and sent her to him at night. By morning, the Prophet ﷺ was a bridegroom, and he said, “Whoever has anything, let him bring it.” He spread out a leather cloth, and one man brought dried curds, another brought dates, and another brought clarified butter. I think he also mentioned roasted flour. Then they mixed it into a dish of hays, and that was the wedding feast of the Messenger of Allah ﷺ."]},"buhuth":{"ar":["والحيس: هو نوع من الطعام يصنع من الأقط والتمر والسمن يخلط ويُعجن، وربما يخلط فيه أيضا السويق."],"en":["Al-hays is a type of food made from dried curds, dates, and clarified butter, mixed and kneaded together, and sometimes roasted flour is also mixed into it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":371},{"key":"muslim","label":"مسلم","number":84}]},{"num":6507,"demo":false,"sanad":"","matn":["عن أنس قال: صَارَتْ صَفِيَّهُ لِدِحْيَةَ فِي مَقْسَمِهِ، وَجَعَلُوا يَمْدَحُونَها عِنْدَ رَسُولِ الله ﷺ قَالَ: وَيَقُولُونَ مَا رَأَيْنَا فِي السَّبْي مِثْلَهَا، قَالَ: فَبَعَثَ إِلَى دِحْيَةَ فَأَعْطَاهُ بِهَا مَا أَرَادَ، ثُمَّ دَفَعَهَا إِلَى أُمِّي، فَقَالَ: ((أَصْلِحِيهَا)). قَالَ: ثُمَّ خَرَجَ رَسُولُ الله ﷺ مِنْ خَيْبَرَ حَتَّى إِذَا جَعَلَهَا فِي ظَهْرِهِ، نَزَلَ، ثُمَّ ضَرَبَ عَلَيْهَا الْقُبَّةَ، فَلَمَا أَصْبَحَ قَالَ رَسُولُ الله ﷺ: (( مَنْ كَانَ عِنْدَهُ فَضْلُ زَادٍ فَلْيَأْتِنَا بِهِ )). قَالَ: فَجَعَلَ الرَّجُلُ يَجِيءُ بِفَضْلِ التَّمْرِ وَفَضْلِ السَّوِيقِ حَتَّى جَعَلُوا مِنْ ذَلِكَ سَوَادًا حَيْسًا، فَجَعَلُوا يَأْكُلُونَ مِنْ ذَلِكَ الحَيْسِ وَيَشْرَبُونَ مِنْ حِيَاضٍ إِلَى جَنْبِهِمْ مِنْ مَاءِ السَّمَاءِ، قَالَ: فَقَالَ أَنَسٌ: فَكَانَتْ تِلْكَ وَلِيمَةَ رَسُولِ الله ﷺ عَلَيْهَا، قَالَ: فَانْطَلَقْنَا حَتَّى إِذَا رَأَيْنَا جُدُرَ المدِينَةِ هَشِشْنَا إِلَيْهَا فَرَفَعْنَا مَطِيَّنَا وَرَفَعَ رَسُولُ الله ﷺ مَطِيَّتَهُ، قَالَ: وَصَفِيَّةُ خَلْفَهُ قَدْ أَرْدَفَهَا رَسُولُ الله ﷺ، قَالَ: فَعَثَرَتْ مَطِيَّةُ رَسُولِ الله ﷺ، فَصُرِعَ وَصُرِعَتْ، قَالَ: فَلَيْسَ أَحَدٌ مِنَ النَّاسِ يَنْظُرُ إِلَيْهِ وَلا إِلَيْهَا حَتَّى قَامَ رَسُولُ الله ﷺ فَسَتَرَهَا، قَالَ: فَأَتَيْنَاهُ، فَقَالَ: (( لَمْ نُضَرَّ )). قَالَ: فَدَخَلْنَا المدِينَةَ، فَخَرَجَ جَوَارِي نِسَائِهِ يَتَرَاءَيْنَهَا وَيَشْمَتْنَ بِصَرْعَتِهَا."],"takhrij":"صحيح: رواه مسلم في النكاح (٨٨ :١٣٦٥)","grade":"صحيح","chapter_ar":"باب جعل العتق صداقا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Marriage (1365 no. 88).","chapter_en":"Making Emancipation the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Anas said: Safiyyah fell to Dihyah in his allotted share, and they began praising her before the Messenger of Allah ﷺ, saying: We have not seen anyone like her among the captives. So he sent for Dihyah and gave him in exchange what he wished, then he handed her over to my mother and said, “Prepare her.” Then the Messenger of Allah ﷺ left Khaybar, and when he placed her behind him on his mount, he stopped and set up a tent over her. When morning came, the Messenger of Allah ﷺ said, “Whoever has extra provisions, let him bring them to us.” Then one man would bring extra dates, and another extra roasted flour, until they made from that a large amount of hays. They began eating from that hays and drinking from pools beside them filled with rainwater. Anas said: That was the wedding feast of the Messenger of Allah ﷺ for her. Then we proceeded on until, when we saw the walls of Madinah, we became eager for it and hastened our mounts, and the Messenger of Allah ﷺ also hastened his mount. Safiyyah was behind him, for the Messenger of Allah ﷺ had seated her behind him. Then the mount of the Messenger of Allah ﷺ stumbled, and he fell and she fell. No one among the people looked at him or at her until the Messenger of Allah ﷺ stood and covered her. Then we came to him, and he said, “We have not been harmed.” Then we entered Madinah, and the servant girls of his wives came out looking at her and gloating over her fall."]}},"tuhfa":{},"refs":[{"key":"muslim/النکاح","label":"مسلم في النكاح","number":88}]},{"num":6508,"demo":false,"sanad":"","matn":["عن جويرية بنت الحارث قالت لرسول الله ﷺ إن أزواجك يفخرن عليّ، يقلن: لم يتزوجك رسول الله ﷺ إنما أنت ملك يمين. فقال رسول الله ﷺ: (( ألم أعظم صداقك، ألم أعتق أربعين من قومك ))."],"takhrij":"صحيح: رواه إسحاق في مسنده (٢٥٥/٤) وعبد الرزاق (٢٧٢-٢٧١/٧) والحاكم (٢٥/٤).","grade":"صحيح","chapter_ar":"باب جعل العتق صداقا","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Ishaq in his Musnad (4/255), ʿAbd al-Razzaq (7/271–272), and al-Hakim (4/25).","chapter_en":"Making Emancipation the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Juwayriyyah bint al-Harith said to the Messenger of Allah ﷺ: Your wives boast over me and say: The Messenger of Allah did not really marry you; you are only a bondwoman. So the Messenger of Allah ﷺ said, “Did I not make your dowry great? Did I not free forty of your people?”"]}},"tuhfa":{},"refs":[{"key":"اسحاق/مسندہ","label":"إسحاق في مسنده","number":255},{"key":"عبد_الرزاق","label":"عبد الرزاق","number":272},{"key":"hakim","label":"المستدرك على الصحيحين","number":6778,"n":6776}]},{"num":6509,"demo":false,"sanad":"","matn":["عن أبي موسى قال: قال رسول الله ﷺ: (( ثلاثة لهم أجران)) منهم: (( رجل كانت عنده أمةٌ فأدّبَها فأحسن تأديبها، وعلّمها فأحسن تعليمها، ثم أعتَقها، فتزوَّجها، فله أجران ))"],"takhrij":"متفق عليه: رواه البخاري في العلم (٩٧) ومسلم في الإيمان (١٥٤). وقوله: “فتزوّجها”: أي بالمهر.","grade":"متفق عليه","chapter_ar":"باب فضل من أعتق ثم تزوجها","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in the Book of Knowledge (97) and Muslim in the Book of Faith (154).","chapter_en":"The Virtue of One Who Frees a Slave Woman and Then Marries Her","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abu Musa said: The Messenger of Allah ﷺ said, “Three people will have a double reward.” Among them is: “A man who had a slave woman, disciplined her and did so well, taught her and taught her well, then freed her and married her — he will have two rewards.”"]},"buhuth":{"en":["His statement, “then married her,” means with a dowry."]}},"tuhfa":{},"refs":[{"key":"bukhari/العلم","label":"البخاري في العلم","number":97},{"key":"muslim/الایمان","label":"مسلم في الإيمان","number":154}]},{"num":6510,"demo":false,"sanad":"","matn":["عن عائشة قالت: أتتْ جويريةُ بنت الحارث رسولَ الله ﷺ تستعينه في كتابتها، فو الله ما هو إلا أن وقفتْ على باب الحجرة، فرأيتها فكرهتُ مكانها، وعرفتُ أن رسول الله ﷺ سيرى منها مثل ما رأيتُ. فقالت جويرية: يا رسول الله ﷺ كان من الأمر ما قد عرفت، فكاتبت نفسي فجئت أستعينك. فقال رسول الله ﷺ: (( أو ما هو خير من ذلك؟ )) قالت: ما هو؟ قال: (( أتزوّجكِ وأقضي عنكِ كتابتكِ )) فقالت: نعم. قال: (( قد فعلتُ )). قالت: فبلغ المسلمين ذلك فقالوا: أصهار رسول الله ﷺ، فأرسلوا ما كان في أيديهم من سبايا بني المصطلق. قالت: فلقد عُتق بتزويجه مائة أهل بيت من بني المصطلق. قالت: فما أعلم امرأة كانت أعظم بركة على قومها منها."],"takhrij":"حسن: رواه أبو داود (٣٩٣١) وأحمد (٢٦٣٦٥) وابن حبان (٤٠٥٤) والحاكم (٢٦/٤).","grade":"حسن","chapter_ar":"باب جعل الصداق أداء ما كوتبت عليه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3931), Ahmad (26365), Ibn Hibban (4054), and al-Hakim (4/26).","chapter_en":"Making the Dowry the Payment of What She Had Contracted for Her Emancipation","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: Juwayriyyah bint al-Harith came to the Messenger of Allah ﷺ seeking his help regarding her emancipation contract. By Allah, as soon as she stood at the door of the room, I saw her and disliked her place there, for I knew that the Messenger of Allah ﷺ would see in her what I had seen. Juwayriyyah said: O Messenger of Allah, you know what has happened to me. I made a contract for my freedom, and I have come seeking your help. The Messenger of Allah ﷺ said, “Shall I not offer you something better than that?” She said: What is it? He said, “I will marry you and pay off your contract for you.” She said: Yes. He said: “I have done so.” She said: When the Muslims heard that, they said: They are the relatives by marriage of the Messenger of Allah ﷺ. So they released whatever captives of Banu al-Mustaliq were in their hands. She said: One hundred households of Banu al-Mustaliq were freed because of his marriage to her. She said: I do not know of any woman who brought a greater blessing upon her people than she did."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3931},{"key":"hakim","label":"الحاكم","number":26},{"key":"ahmad","label":"مسند الإمام أحمد","number":26365,"n":26365},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5658,"n":5654}]},{"num":6511,"demo":false,"sanad":"","matn":["عن عقبة بن عامر قال: قال رسول الله ﷺ: (( خيرُ النكاح أيسرُه ))."],"takhrij":"صحيح: رواه أبو داود (٢١١٧) وابن حبان في صحيحه (٤٠٧٢) والحاكم (١٨٢-١٨١/٢).","grade":"صحيح","chapter_ar":"باب خير النكاح أيسره نفقة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2117), Ibn Hibban in his Sahih (4072), and al-Hakim (2/181–182).","chapter_en":"The Best Marriage Is the One with the Least Expense","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: The Messenger of Allah ﷺ said, “The best marriage is the easiest one.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2117},{"key":"ibnhibban/صحیحہ","label":"ابن حبان في صحيحه","number":4072},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5659,"n":5655},{"key":"hakim","label":"المستدرك على الصحيحين","number":2841,"n":2827}]},{"num":6512,"demo":false,"sanad":"","matn":["عن عائشة أن رسول الله ﷺ قال: (( إن من يُمنِ المرأة تيسيرُ خِطبتها، وتيسيرُ صداقِها، وتيسيرُ رحمِها ))."],"takhrij":"حسن: رواه أحمد (٢٤٤٧٨) والبزار - كشف الأستار (١٤١٧) وابن حبان (٤٠٩٥) والحاكم (١٨١/٢).","grade":"حسن","chapter_ar":"باب خير النكاح أيسره نفقة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (24478), al-Bazzar in Kashf al-Astar (1417), Ibn Hibban (4095), and al-Hakim (2/181).","chapter_en":"The Best Marriage Is the One with the Least Expense","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ said, “Part of a woman’s blessing is the ease of her proposal, the ease of her dowry, and the ease of her womb.”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1417},{"key":"ibnhibban","label":"ابن حبان","number":4095},{"key":"hakim","label":"الحاكم","number":181},{"key":"ahmad","label":"مسند الإمام أحمد","number":24478,"n":24478}]},{"num":6513,"demo":false,"sanad":"","matn":["عن أبي العَجْفاء السُّلمي قال: خطبنا عمر فقال: ألا لا تغالوا بصُدق النساء، فإنها لو كانت مكرمةً في الدنيا، أو تقوى عند الله كان أولاكم بها النبي ﷺ. ما أصدق رسولُ الله ﷺ امرأة من نسائه، ولا أُصدِقتْ امرأةٌ من بناته أكثر من ثنتي عشرة أوقية."],"takhrij":"حسن: رواه أبو داود (٢١٠٦) والنسائي (٣٣٤٩) والترمذي (١١١٤) وابن ماجه (١٨٨٧) وأحمد (٣٤٠).","grade":"حسن","chapter_ar":"باب النهي عن الغلاء في المهور","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2106), al-Nasa’i (3349), al-Tirmidhi (1114), Ibn Majah (1887), and Ahmad (340).","chapter_en":"The Prohibition of Exaggeration in Dowries","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Abu al-ʿAjfa’ al-Sulami said: ʿUmar addressed us and said: Do not be excessive in the dowries of women, for if that were an honor in this world or a sign of piety before Allah, then the Prophet ﷺ would have been more entitled to it than you. The Messenger of Allah ﷺ did not give any of his wives as dowry, nor was any of his daughters given in marriage for more than twelve uqiyyahs."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2106},{"key":"nasai","label":"النسائي","number":3349},{"key":"tirmidhi","label":"الترمذي","number":1114},{"key":"ibnmajah","label":"ابن ماجه","number":1887},{"key":"ahmad","label":"مسند الإمام أحمد","number":340,"n":340}]},{"num":6514,"demo":false,"sanad":"","matn":["عن عقبة بن عامر أن النبي ﷺ قال لرجل: (( أترضى أن أزوجك فلانة؟ )) قال: نعم، وقال للمرأة: (( أترضين أن أزوجك فلاناً؟ )) قالت: نعم، فزوج أحدهما صاحبه، فدخل بها الرجل، ولم يفرض لها صداقاً، ولم يعطها شيئاً. وكان ممن شهد الحديبية له سهم خيبر. فلما حضرتُه الوفاةُ قال: إن رسول الله ﷺ زوجني فلانة، ولم أفرض لها صداقاً، ولم أُعطها شيئاً، وإني أُشْهِدكم أني أعطيتُها من صداقها سهْمي بخيبر، فأخذتْ سهماً فباعته بمائة ألف."],"takhrij":"صحيح: رواه أبو داود (٢١١٧) وصحّحه ابن حبان (٤٠٧٢) والحاكم (١٨٢-١٨١/٢).","grade":"صحيح","chapter_ar":"باب ينعقد النكاح بغير مهر","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2117), and authenticated by Ibn Hibban (4072) and al-Hakim (2/181–182).","chapter_en":"A Marriage Contract Is Valid Even Without Naming a Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir narrated that the Prophet ﷺ said to a man, “Are you pleased that I marry so-and-so to you?” He said: Yes. And he said to the woman, “Are you pleased that I marry so-and-so to you?” She said: Yes. So he married one of them to the other. The man consummated the marriage with her, but he had not specified any dowry for her and had not given her anything. He was among those who had witnessed al-Hudaybiyah and thus had a share from Khaybar. When death approached him, he said: The Messenger of Allah ﷺ married me to so-and-so, and I did not specify any dowry for her, nor did I give her anything. I make you witnesses that I have given her my share from Khaybar as her dowry. So she took the share and sold it for one hundred thousand."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2117},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4072},{"key":"hakim","label":"المستدرك على الصحيحين","number":2742,"n":2728}]},{"num":6515,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود في رجل تزوج امرأةً فمات عنها، ولم يَدخُل بها، ولم يَفْرِضُ لها الصداقَ. فقال: لها الصداقُ كاملاً، وعليها العدة، ولها الميراث.","قال معقل بن سنان: سمعتُ رسول الله ﷺ قضى في بروَع بنت واشق."],"takhrij":"صحيح: رواه أبو داود (٢١١٤) والنسائي (٣٣٥٦) وابن ماجه (١٨٩١) وصحّحه ابن حبان.","grade":"صحيح","chapter_ar":"باب فيمن تزوج ولم يسم صداقاً حتى مات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2114), al-Nasa’i (3356), Ibn Majah (1891), and authenticated by Ibn Hibban.","chapter_en":"Concerning One Who Married Without Naming a Dowry, Then Died","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["ʿAbd Allah ibn Masʿud gave judgment concerning a man who married a woman and then died before consummating the marriage and before specifying a dowry for her. He said: She is entitled to the full dowry, she must observe the waiting period, and she is entitled to inheritance. Maʿqil ibn Sinan said: I heard the Messenger of Allah ﷺ give judgment concerning Barwaʿ bint Washiq in that way."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2114},{"key":"nasai","label":"النسائي","number":3356},{"key":"ibnmajah","label":"ابن ماجه","number":1891}]},{"num":6516,"demo":false,"sanad":"","matn":["عن عروة بن الزبير يحدث أنه سأل عائشة: (وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِى الْيَتَمَىٰ فَانكِحُواْ مَا طَابَ لَكُمْ مِنَ النِّسَاءِ) [النساء: ٣] قالت: هي اليتيمة في حجر وليها، فيرغب في جمالها ومالها ويريد أن يتزوجها بأدنى من سنة نسائها، فنهوا عن نكاحهن، إلا أن يُقسطوا لهن في إكمال الصداق، وأمروا بنكاح من سواهن من النساء.","قالت عائشة: ثم استفتى الناس رسول الله ﷺ بعدُ، فأنزل الله عز وجل: (وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللَّهُ يُفْتِيكُمْ فِيهِنَّ) [النساء: ١٢٧] قالت: فبيَّن الله في هذه أن اليتيمة إذا كانت ذات جمال ومال، رغبوا في نكاحها، ولم يُلحقوها بسنتها في إكمال الصداق، فإذا كانت مرغوباً عنها في قلة المال والجمال تركوها، والتمسوا غيرها من النساء. قال: فكما يتركونها حين يرغبون عنها، فليس لهم أن ينكحوها إذا رغبوا فيها إلا أن يُقسطوا لها الأوفى من الصداق، ويُعطوها حقها."],"takhrij":"متفق عليه: رواه البخاري (٢٧٦٣) ومسلم (٦:٣٠١٨). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب إن كان الولي هو الخاطب فعليه أن يعدل في الصداق","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2763) and Muslim (3018 no. 6). The wording is that of al-Bukhari.","chapter_en":"If the Guardian Himself Wishes to Marry Her, He Must Be Fair Regarding the Dowry","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في الصداق","group_en":"Collection of Chapters on What Has Been Related About the Dowry","part_no":24,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr narrated that he asked ʿA’ishah about the verse: “And if you fear that you will not deal justly with the orphan girls, then marry those women who seem good to you” [al-Nisa’ 4:3]. She said: This refers to an orphan girl under the care of her guardian. He may be attracted to her beauty and wealth and want to marry her for less than the dowry normally given to women like her. So they were forbidden from marrying such girls unless they deal justly with them by giving them the full dowry, and they were instructed to marry other women besides them.","ʿA’ishah said: Then the people sought a ruling from the Messenger of Allah ﷺ after that, so Allah the Mighty and Majestic revealed: “And they ask you for a ruling concerning women. Say: Allah gives you a ruling concerning them” [al-Nisa’ 4:127]. She said: Allah made clear in this verse that when the orphan girl possessed beauty and wealth, they desired to marry her, but they would not give her what women like her deserved in full dowry. Yet when she was not desired because of little wealth or beauty, they would leave her and seek other women instead. So just as they leave her when they have no desire for her, they have no right to marry her when they do desire her unless they are fully just with her in the dowry and give her her due."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2763},{"key":"muslim","label":"مسلم","number":6}]},{"num":6517,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أن عبد الرحمن بن عوف جاء إلى رسول الله ﷺ وبه أثر صفرة، فسأله رسول الله ﷺ فأخبره أنه تزوج. فقال له رسول الله ﷺ: (( كم سُقت إليها؟ )) فقال: زنة نواة من ذهب. فقال له رسول الله ﷺ: (( أولِمْ ولو بشاةٍ ))"],"takhrij":"متفق عليه: رواه مالك (٤٧) والبخاري (٥١٥٣) ومسلم (٨١:١٤٢٧). وقوله: (( كم سُقْتَ إليها )): أي ما أمهرتها، وقيل للمهر: سوق؛ لأن العرب كانت أموالهم المواشي، فكان الرجلُ إذا تزوج ساق إليها الإبل والغنم مهراً.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الوليمة بالشاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (47), al-Bukhari (5153), and Muslim (1427 no. 81).","chapter_en":"What Has Been Related About Holding the Wedding Feast with a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik narrated that ʿAbd al-Rahman ibn ʿAwf came to the Messenger of Allah ﷺ with a trace of yellow perfume on him. The Messenger of Allah ﷺ asked him, and he informed him that he had married. So the Messenger of Allah ﷺ said to him, “What did you give her?” He said: The weight of a date-stone of gold. The Messenger of Allah ﷺ said to him, “Give a wedding feast, even if only with one sheep.”"]},"buhuth":{"ar":["وفي الحديث رخصة في استعمال الصفرة من الزعفران وغيره للعريس."],"en":["His statement, “What did you bring to her?” means: What did you give as her dowry? The dowry was called “bringing” because the Arabs’ wealth was mostly livestock, so when a man married, he would bring camels or sheep to her as dowry.","In this hadith is a concession for the bridegroom to use yellow coloring from saffron and similar things."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":47},{"key":"bukhari","label":"البخاري","number":5153},{"key":"muslim","label":"مسلم","number":81}]},{"num":6518,"demo":false,"sanad":"","matn":["عن عبد الرَّحْمَنِ بِن عَوْفٍ قَالَ: لما قَدِمْنَا المدِينَةَ آخَى رَسُولُ الله ﷺ بَيْنِي وَبَيْنَ سَعْدِ بْنِ الرَّبِيعِ، فَقَالَ سَعْدُ بْنُ الرَّبِيعِ: إِنِّي أَكْثَرُ الْأَنْصَارِ مَالاً، فَأَقْسِمُ لَكَ نِصْفَ مَالِي، وَانْظُرْ أَيَّ زَوْجَتَيَّ هَوِيتَ، نَزَلْتُ لَكَ عَنْهَا، فَإِذَا حَلَّتْ تَزَوَّجْتَهَا. قَالَ: فَقَالَ لَهُ عَبْدُ الرَّحْمَنِ: لَا حَاجَةَ لِي فِي ذَلِكَ، هَلْ مِنْ سُوقٍ فِيهِ تِجَارَةٌ؟ قَالَ: سُوقُ قَيْنُقَاعَ. قَالَ: فَغَدَا إِلَيْهِ عَبْدُ الرَّحْمَنِ، فَأَتَى بِأَقِطٍ وَسَمْنٍ، قَالَ: ثُمَّ تَابَعَ الغُدُوَّ، فَمَا لَبِثَ أَنْ جَاءَ عَبْدُ الرَّحْمَنِ عَلَيْهِ أَثَرُ صُفْرَةٍ، فَقَالَ رَسُولُ الله ﷺ: (( تَزَوَّجْتَ؟ )) قَالَ: نَعَمْ، قَالَ: (( وَمَنْ؟ )) قَالَ: امْرَأَةً مِنَ الْأَنْصَارِ. قَالَ: (( كَمْ سُقْتَ؟ )) قَالَ: زِنَةَ نَوَاةٍ مِنْ ذَهَبٍ أَوْ نَوَاةً مِنْ ذَهَبٍ. فَقَالَ لَهُ النَّبِيُّ ﷺ: (( أَوْلِمْ وَلَوْ بِشَاةٍ ))."],"takhrij":"صحيح: رواه البخاري (٢٠٤٨).","grade":"صحيح","chapter_ar":"باب ما جاء في الوليمة بالشاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2048).","chapter_en":"What Has Been Related About Holding the Wedding Feast with a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["ʿAbd al-Rahman ibn ʿAwf said: When we came to Madinah, the Messenger of Allah ﷺ established brotherhood between me and Saʿd ibn al-Rabiʿ. Saʿd ibn al-Rabiʿ said: I am one of the wealthiest of the Ansar, so I will divide my wealth in half for you, and look at whichever of my two wives you prefer, and I will part from her for you, and when her waiting period is over, you may marry her. ʿAbd al-Rahman said to him: I have no need of that. Is there a market where trade is conducted? He said: The market of Banu Qaynuqaʿ. He said: So ʿAbd al-Rahman went there in the morning and returned with dried curds and clarified butter. Then he kept going in the mornings, and before long ʿAbd al-Rahman came with a trace of yellow on him. The Messenger of Allah ﷺ said: “Have you married?” He said: Yes. He said: “Whom?” He said: A woman from the Ansar. He said: “How much did you give?” He said: The weight of a date-stone of gold, or a date-stone of gold. So the Prophet ﷺ said to him: “Give a wedding feast, even if only with one sheep.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2048}]},{"num":6519,"demo":false,"sanad":"","matn":["عن ثابت قال: ذُكرَ تزويجُ زينب بنت جحش عند أنس، فقال: ما رأيتُ النبي ﷺ أولمَ على أحد من نسائه ما أولمَ عليها، أولمَ بشاة."],"takhrij":"متفق عليه: رواه البخاري (٥١٧١) ومسلم (٩٠:١٤٢٨). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الوليمة بالشاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5171) and Muslim (1428 no. 90). The wording is that of al-Bukhari.","chapter_en":"What Has Been Related About Holding the Wedding Feast with a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Thabit said: The marriage of Zaynab bint Jahsh was mentioned in the presence of Anas, and he said: I did not see the Prophet ﷺ give a wedding feast for any of his wives as he did for her. He gave a feast with one sheep."]},"buhuth":{"ar":["وفي لفظ مسلم: ما أولَم رسول الله ﷺ على امرأة من نسائه أكثرَ وأفضلَ مما أولَم على زينب. فقال ثابت للبناني: بما أولَم؟ قال: “أطعمهم خبزاً ولحماً حتى تركوه”. وتفصيله عند البخاري (٤٧٩٣) قال: بُني على النبي ﷺ بزينب بخبز ولحم، فأرسلتُ على الطعام داعياً، فيجيء قوم فيأكلون ويخرجون، ثم يجيء قوم فيأكلون ويخرجون. فدعوتُ حتى ما أجد أحداً أدعوه. فقلت: يا نبي الله ما أجد أحداً أدعوه. قال: (( ارفعوا طعامكم ))."],"en":["In the wording of Muslim: The Messenger of Allah ﷺ did not give a larger or better wedding feast for any of his wives than the one he gave for Zaynab. Thabit al-Bunani asked: With what did he give the feast? He said: He fed them bread and meat until they left it. Its detail in al-Bukhari (4793) is: The Prophet ﷺ consummated his marriage with Zaynab, and bread and meat were served. I went calling people to the food. A group would come, eat, and leave; then another group would come, eat, and leave. I continued inviting until I could no longer find anyone to invite. So I said: O Prophet of Allah, I cannot find anyone else to invite. He said: “Remove your food.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5171},{"key":"muslim","label":"مسلم","number":90}]},{"num":6520,"demo":false,"sanad":"","matn":["عن صفية بنت شيبة قالت: أولم النبي ﷺ على بعض نسائه بمدين من شعير"],"takhrij":"صحيح: رواه البخاري (٥١٧٢)","grade":"صحيح","chapter_ar":"باب من أولم بأقل من شاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5172).","chapter_en":"One Who Gave a Wedding Feast with Less than a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Safiyyah bint Shaybah said: The Prophet ﷺ gave a wedding feast for one of his wives with two mudd measures of barley."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5172}]},{"num":6521,"demo":false,"sanad":"","matn":["عن أنس أن النبي ﷺ أوْلَمَ على صفية بسويق وتمر ."],"takhrij":"حسن: رواه أبو داود (٣٧٤٤) والترمذي (١٠٩٥) وحسِّنه، وابن ماجه (١٩٠٩) وصحّحه ابن حبان (٤٠٦١).","grade":"حسن","chapter_ar":"باب من أولم بأقل من شاة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3744), al-Tirmidhi (1095), who graded it Hasan, Ibn Majah (1909), and authenticated by Ibn Hibban (4061).","chapter_en":"One Who Gave a Wedding Feast with Less than a Sheep","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ held a wedding feast for Safiyyah with roasted flour and dates."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3744},{"key":"tirmidhi","label":"الترمذي","number":1095},{"key":"ibnmajah","label":"ابن ماجه","number":1909},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4061},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":1221,"n":1218}]},{"num":6522,"demo":false,"sanad":"","matn":["عن أنس قال: تزوج النبي ﷺ صفية، وجعل عتقها صداقها، وجعل الوليمة ثلاثة أيام، وبسط نطعا جاءت به أم سُليم، وألقى عليه أقطا وتمرا، وأطعم الناس ثلاثة أيام."],"takhrij":"حسن: رواه أبو يعلى (٣٨٣٤).","grade":"حسن","chapter_ar":"باب ما جاء في الوليمة أكثر من يوم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Yaʿla (3834).","chapter_en":"What Has Been Related About the Wedding Feast Lasting More Than One Day","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas said: The Prophet ﷺ married Safiyyah, made her emancipation her dowry, and made the wedding feast last three days. Umm Sulaym brought a leather mat, which he spread out, and he placed dried curds and dates on it, and he fed the people for three days."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":3834},{"key":"sh12520","label":"مسند أبي يعلى","number":3834,"n":3839}]},{"num":6523,"demo":false,"sanad":"","matn":["عن أنس قال: أقام النبي ﷺ بين خيبر والمدينة ثلاثا، يُبنى عليه بصفية بنت حيي. فدعوتُ المسلمين إلى وليمته، فما كان فيها من خبز ولا لحم، أمر بالأنطاع، فألقى فيها من التمر والأقط والسمن، فكانت وليمته."],"takhrij":"صحيح: رواه البخاري (٥٠٨٥).","grade":"صحيح","chapter_ar":"باب ما جاء في الوليمة أكثر من يوم","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5085).","chapter_en":"What Has Been Related About the Wedding Feast Lasting More Than One Day","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Anas said: The Prophet ﷺ stayed between Khaybar and Madinah for three days while consummating his marriage to Safiyyah bint Huyayy. I invited the Muslims to his wedding feast. There was neither bread nor meat in it. He ordered that leather cloths be spread, then dates, dried curds, and clarified butter were placed on them, and that was his wedding feast."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5085}]},{"num":6524,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: أعتق النبي ﷺ صفية بنت حيي سيدة قريظة والنضير، وتزوجها فأصبح عرُوسا فقال: (( من كان عنده شيء فليجيء به)). قال: وبسط نِطْعاً قال: فجعل الرجل يجيء بالأقط، وجعل الرجل يجيء بالتمر، وجعل الرجل يجيء بالسمن فحاسوا حيسا. فكانت وليمة رسول الله ﷺ."],"takhrij":"متفق عليه: رواه البخاري (٣٧١) ومسلم (٨٤:١٣٦٥).","grade":"متفق عليه","chapter_ar":"باب التعاون في إقامة الوليمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (371) and Muslim (1365 no. 84).","chapter_en":"Cooperation in Holding the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ freed Safiyyah bint Huyayy, the chief lady of Qurayzah and al-Nadir, and married her. In the morning, when he was a bridegroom, he said, “Whoever has anything, let him bring it.” He spread out a leather mat, and one man brought dried curds, another brought dates, and another brought clarified butter, and they mixed it into hays. That was the wedding feast of the Messenger of Allah ﷺ."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":371},{"key":"muslim","label":"مسلم","number":84}]},{"num":6525,"demo":false,"sanad":"","matn":["عن أنس قال: بنى النبي ﷺ بامرأة، فأرسلني فدعوت رجالاً إلى الطعام."],"takhrij":"صحيح: رواه البخاري (٥١٧٠).","grade":"صحيح","chapter_ar":"باب وقت الوليمة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5170).","chapter_en":"The Time of the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Anas said: The Prophet ﷺ consummated marriage with a woman, then sent me, and I invited men to the food."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5170}]},{"num":6526,"demo":false,"sanad":"","matn":["عن ابن عمر، أن رسول الله ﷺ قال: (( إذا دعي أحدكم إلى وليمةِ فليأتِها)).","وفي لفظ: (( إذا دعي أحدكم إلى وليمة عُرس فليُجِبْ))","وفي آخر: (( إذا دعا أحدُكم أخاه فليُجِبْ عُرسا كان أو نحوه))."],"takhrij":"صحيح: رواه مالك (٤٩) والبخاري (٥١٧٣)، ومسلم (٩٦:١٤٢٩).","grade":"صحيح","chapter_ar":"باب إجابة الدعوة إلى وليمة العُرس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (49), al-Bukhari (5173), and Muslim (1429 no. 96).","chapter_en":"Accepting the Invitation to the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said, “If one of you is invited to a wedding feast, let him attend it.”","In another wording: “If one of you is invited to a wedding feast, let him respond.”","And in another: “When one of you invites his brother, let him accept, whether it is for a wedding or something similar.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":49},{"key":"bukhari","label":"البخاري","number":5173},{"key":"muslim","label":"مسلم","number":96}]},{"num":6527,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: قال رسول الله ﷺ: (( أجيبوا هذه الدعوة إذا دعيتم لها)).","قال: كان عبد الله يأتي الدعوة في العُرس وغير العُرس وهو صائم."],"takhrij":"متفق عليه: رواه البخاري (٥١٧٩)، ومسلم (١٠٣:١٤٢٩).","grade":"متفق عليه","chapter_ar":"باب إجابة دعوة الوليمة لمن كان صائما","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5179) and Muslim (1429 no. 103).","chapter_en":"Responding to the Wedding Feast Invitation Even If One Is Fasting","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar said: The Messenger of Allah ﷺ said, “Respond to this invitation when you are invited to it.”","He said: ʿAbd Allah used to attend invitations, both for weddings and other than weddings, while fasting."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5179},{"key":"muslim","label":"مسلم","number":103}]},{"num":6528,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: ( رسول الرجل إلى الرجل إذنه )."],"takhrij":"صحيح: رواه أبو داود (٥١٨٩) والبخاري في الأدب المفرد (١٠٧٦).","grade":"صحيح","chapter_ar":"باب إجابة دعوة الوليمة لمن كان صائما","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (5189) and al-Bukhari in al-Adab al-Mufrad (1076).","chapter_en":"Responding to the Wedding Feast Invitation Even If One Is Fasting","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “A man’s messenger to another man is his permission.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5189},{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":1076},{"key":"adab","label":"الأدب المفرد","number":1076,"n":1076}]},{"num":6529,"demo":false,"sanad":"","matn":["عن أبي هريرة أنه كان يقول: ( شر الطعام طعام الوليمة، يُدعى لها الأغنياء، ويُترك المساكين، ومن لم يأت الدعوة فقد عصى الله ورسولَه )."],"takhrij":"متفق عليه: رواه مالك (٥٠) والبخاري (٥١٧٧) ومسلم (١٩٧:١٤٣٢).","grade":"متفق عليه","chapter_ar":"باب شرّ الطعام الذي يُدعى إليه الأغنياء دون الفقراء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (50), al-Bukhari (5177), and Muslim (1432 no. 197).","chapter_en":"The Worst Food Is the Wedding Feast to Which the Rich Are Invited While the Poor Are Left Out","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah used to say: “The worst food is the food of the wedding feast: the rich are invited to it, while the poor are left out. And whoever does not come to the invitation has disobeyed Allah and His Messenger.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":50},{"key":"bukhari","label":"البخاري","number":5177},{"key":"muslim","label":"مسلم","number":197}]},{"num":6530,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( شرُّ الطعام طعام الوليمة، يُمنعها من يأتيها، ويدعى إليها من يأباها، ومن لم يجب الدعوة، فقد عصى الله ورسوله ))."],"takhrij":"صحيح: رواه مسلم (١١٠ :١٤٣٢).","grade":"صحيح","chapter_ar":"باب شرّ الطعام الذي يُدعى إليه الأغنياء دون الفقراء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1432 no. 110).","chapter_en":"The Worst Food Is the Wedding Feast to Which the Rich Are Invited While the Poor Are Left Out","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “The worst food is the food of the wedding feast: the one who wants to come is prevented from it, and the one who refuses it is invited to it. And whoever does not answer the invitation has disobeyed Allah and His Messenger.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":110}]},{"num":6531,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: أبصر النبي ﷺ نساءً وصبيانًا مقبلين من عرس، فقام ممتنا، فقال: (( اللهم أنتم من أحب الناس إلي ))."],"takhrij":"متفق عليه: رواه البخاري (٥١٨٠) ومسلم (١٧٤:٢٥٠٨).","grade":"متفق عليه","chapter_ar":"باب دعوة النساء والصبيان إلى وليمة العُرس","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5180) and Muslim (2508 no. 174).","chapter_en":"Inviting Women and Children to the Wedding Feast","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ saw women and children coming from a wedding, so he stood up in honor and said, “By Allah, you are among the most beloved people to me.”"]},"buhuth":{"ar":["قوله: (( فقام ممتنا )) أي من الامتنان، فمن قام له النبيُّ ﷺ وأكرمه بذلك فقد امتنّ عليه بشيء لا أعظم منه."],"en":["His statement, “he stood up in honor,” means out of esteem and graciousness. Whoever the Prophet ﷺ stood for and honored in this way was honored with something beyond compare."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5180},{"key":"muslim","label":"مسلم","number":174}]},{"num":6532,"demo":false,"sanad":"","matn":["عن أبي مسعود الأنصاري قال:","جاء رجل من الأنصار يكنى أبا شعيب، فقال لغلام له قصاب - وفي رواية: لحام -:","اجعل لي طعامًا يكفي خمسة، فإني أريد أن أدعو النبي ﷺ خامس خمسة، فإني قد عرفت في وجهه الجوع.","فدعاهم، فجاء معهم رجل.","فقال النبي ﷺ:","«إِنَّ هَذَا قَدْ تَبِعَنَا، فَإِنْ شِئْتَ أَنْ تَأْذَنَ لَهُ فَأْذَنْ لَهُ، وَإِنْ شِئْتَ أَنْ يَرْجِعَ رَجَعَ».","فقال:","لا، بل قد أذنت له."],"takhrij":"متفق عليه: رواه البخاري (٢٠٨١)، ومسلم (٢٠٣٦).","grade":"متفق عليه","chapter_ar":"باب فيمن جاء إلى الوليمة من غير دعوة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2081) and Muslim (2036).","chapter_en":"Concerning One Who Comes to the Wedding Feast Without an Invitation","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Abū Masʿūd al-Anṣārī reported:","A man from the Anṣār known as Abū Shuʿayb said to a servant of his who was a butcher—and in another narration, a meat seller:","“Prepare food for me sufficient for five people, for I wish to invite the Prophet ﷺ as one of five, because I have noticed hunger in his face.”","He invited them, and another man came along with them.","The Prophet ﷺ said:","“This man has followed us. If you wish, you may give him permission to enter; and if you wish, he may return.”","The host replied:","“No, rather I give him permission.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2081},{"key":"muslim","label":"مسلم","number":2036}]},{"num":6533,"demo":false,"sanad":"","matn":["عن سهل قال:","لما عرّس أبو أسيد الساعدي، دعا النبي ﷺ وأصحابه، فما صنع لهم طعامًا، ولا قرّبه إليهم إلا امرأته أم أسيد.","بلّت تمرات في تور من حجارة من الليل، فلما فرغ النبي ﷺ من الطعام أماثته له، فسقته، تتحفه بذلك."],"takhrij":"متفق عليه: رواه البخاري (٥١٨٢)، ومسلم (٢٠٠٦/٨٧).","grade":"متفق عليه","chapter_ar":"باب ما جاء من قيام العروس على خدمة المدعوين عند الضرورة","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5182) and Muslim (2006/87).","chapter_en":"What Has Been Related About the Bride Serving the Invited Guests When Necessary","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["Sahl reported:","When Abū Usayd al-Sāʿidī got married, he invited the Prophet ﷺ and his Companions.","No one prepared food for them or served it to them except his wife, Umm Usayd.","She had soaked some dates overnight in a stone vessel. When the Prophet ﷺ finished eating, she dissolved and mixed them for him, then gave it to him to drink as a special offering."]},"buhuth":{"ar":["قوله: «أماثته» من ماثه وأماثه - ثلاثيًا ورباعيًا - أي أذابه.","وقوله: «تتحفه» من الإتحاف، وهو إعطاء التحفة."],"en":["The word “amāthathu” means that she dissolved or thoroughly mixed it.","The expression “tuḥtifuhu” means that she presented it to him as a special gift or offering."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5182},{"key":"muslim","label":"مسلم","number":2006}]},{"num":6534,"demo":false,"sanad":"","matn":["عن علي قال: صنعتُ طعاماً، فدعوت النبي ﷺ فجاء، فدخل فرأى ستراً، فيه تصاوير فرجع. قال: فقلت: يا رسول الله! ما رجعك بأبي أنت وأمي؟ قال: (( إن في البيتِ ستراً فيه تصاوير، وإن الملائكةَ لا تدخل بيتا فيه تصاوير ))."],"takhrij":"صحيح: رواه النسائي (٥٣٥١) واللفظ له، وابن ماجه (٣٣٥٩) وأبو يعلى (٤٣٦).","grade":"صحيح","chapter_ar":"باب ترك حضور الوليمة التي فيها معصية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5351), and this is his wording, also Ibn Majah (3359) and Abu Yaʿla (436).","chapter_en":"Refraining from Attending a Wedding Feast in Which There Is Disobedience","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["ʿAli said: I prepared food and invited the Prophet ﷺ. He came and entered, then saw a curtain with images on it and turned back. I said: O Messenger of Allah, what made you return? May my father and mother be sacrificed for you. He said, “There is a curtain in the house containing images, and the angels do not enter a house in which there are images.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5351},{"key":"ibnmajah","label":"ابن ماجه","number":3359},{"key":"ابو_یعلی","label":"أبو يعلى","number":436},{"key":"sh12520","label":"مسند أبي يعلى","number":436,"n":434}]},{"num":6535,"demo":false,"sanad":"","matn":["عن سفينة أبي عبد الرحمن، أن رجلا أضاف عليّ بن أبي طالب، فصنع له طعاماً. فقالتْ فاطمةُ: لو دعونا النبي ﷺ فأكل معنا. فدعوه فجاء، فوضع يده على عضادتي الباب، فرأى قراماً في ناحية البيت فرجع. فقالت فاطمة لعلي: الحق فقل له: ما رجعك؟ يا رسول الله! قال: (( إنه ليس لي أن أدخل بيتا مزوقا ))."],"takhrij":"حسن: رواه أبو داود (٣٧٥٥) وابن ماجه (٣٣٦٠) وصحّحه ابن حبان (٦٣٤٥) والحاكم (١٨٦/٢).","grade":"حسن","chapter_ar":"باب ترك حضور الوليمة التي فيها معصية","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3755), Ibn Majah (3360), and authenticated by Ibn Hibban (6345) and al-Hakim (2/186).","chapter_en":"Refraining from Attending a Wedding Feast in Which There Is Disobedience","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Safinah Abu ʿAbd al-Rahman narrated that a man hosted ʿAli ibn Abi Talib and prepared food for him. Fatimah said: If only we would invite the Prophet ﷺ to eat with us. So they invited him, and he came. He placed his hand on the side-posts of the door, then saw a decorated curtain in one part of the house and turned back. Fatimah said to ʿAli: Go after him and ask him, O Messenger of Allah, what made you return? He said, “It is not for me to enter a decorated house.”"]},"buhuth":{"ar":["والقرام: الستر الرقيم. والمزوق: النقش."],"en":["Al-qiram means a patterned curtain, and al-muzawwaq means adorned or decorated."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3755},{"key":"ibnmajah","label":"ابن ماجه","number":3360},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":6345},{"key":"hakim","label":"الحاكم","number":186}]},{"num":6536,"demo":false,"sanad":"","matn":["عن محمد بن حاطب قال: قال رسول الله ﷺ (( فصلٌ بين الحلال والحرام: الدفُّ والصوتُ في النكاح ))."],"takhrij":"حسن: رواه الترمذي (١٠٨٨) وحسّنه، والنسائي (٣٣٦٩) وابن ماجه (١٨٩٦) وصحّحه الحاكم (١٨٤/٢).","grade":"حسن","chapter_ar":"باب الإعلان بالنكاح","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1088), who graded it Hasan, al-Nasa’i (3369), Ibn Majah (1896), and authenticated by al-Hakim (2/184).","chapter_en":"Publicizing the Marriage","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Muhammad ibn Hatib said: The Messenger of Allah ﷺ said, “What distinguishes the lawful from the unlawful is the beating of the drum and the raising of the voice in marriage.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1088},{"key":"nasai","label":"النسائي","number":3369},{"key":"ibnmajah","label":"ابن ماجه","number":1896},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":184}]},{"num":6537,"demo":false,"sanad":"","matn":["عن الرُّبَيع بنت معوذ بن عفراء قالت: جاء النبي ﷺ فدخل حين بُنيَ عليّ، فجلس على فراشي كمجلسك مني. فجعلتْ جويريات لنا يضربن بالدف، ويندُبْنَ من قُتِلَ من آبائي يوم بدر، إذ قالت إحداهن: وفينا نبي يعلم ما في غد. فقال النبي ﷺ (( دعي هذه، وقولي بالذي كنتِ تقُولين ))."],"takhrij":"صحيح: رواه البخاري (٥١٤٧).","grade":"صحيح","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5147).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ said: The Prophet ﷺ came and entered when my marriage was consummated, and he sat on my bedding as you are sitting near me. Then some young girls of ours began beating the duff and singing elegies for those of my forefathers who had been killed at Badr, until one of them said: “And among us is a Prophet who knows what will happen tomorrow.” The Prophet ﷺ said, “Leave this and say what you were saying before.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5147}]},{"num":6538,"demo":false,"sanad":"","matn":["عن عائشة أنها زَفّتْ امرأةً من الأنصار، فقال نبي الله ﷺ (( يا عائشة، ما كان معكم من لهو، فإن الأنصار يُعجبهم اللهو ))."],"takhrij":"صحيح: رواه البخاري (٥١٦٢).","grade":"صحيح","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5162).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah narrated that she escorted a woman of the Ansar to her husband. The Prophet ﷺ said, “O ʿA’ishah, was there no amusement with you? For the Ansar are pleased by amusement.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5162}]},{"num":6539,"demo":false,"sanad":"","matn":["عن عائشة قالت: إن النبي ﷺ سمع أناسا يُغنُّون في عُرْسٍ، وهم يقولون:","وأهدى","لها أكبشا","تُبَحْبَحُ في","المربدِ","وزوجك في النادي","ويعلم ما","في غدِ","فقال النبي ﷺ: (( لا يعلم ما في غد إلا الله عز وجل ))."],"takhrij":"حسن: رواه الطبراني في الصغير (٣٤٣) والحاكم (١٨٦-١٧٥/٢) والبيهقي (٢٨٩/٧).","grade":"حسن","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tabarani in al-Saghir (343), al-Hakim (2/175–186), and al-Bayhaqi (7/289).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah said: The Prophet ﷺ heard some people singing at a wedding, saying:","“He gave her some rams,","that frolic in the pen,","and your husband is in the gathering,","and knows what is in tomorrow.”","So the Prophet ﷺ said, “No one knows what is in tomorrow except Allah, the Mighty and Majestic.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الصغیر","label":"الطبراني في الصغير","number":343},{"key":"hakim","label":"الحاكم","number":186},{"key":"البیہقی","label":"البيهقي","number":289},{"key":"sh13068","label":"المعجم الصغير للطبراني","number":343,"n":343}]},{"num":6540,"demo":false,"sanad":"","matn":["عن أنس بن مالك أن النبي ﷺ مرَّ ببعض المدينة فإذا هو بجوار يضربن بدفهن، ويتغنَّين ويقُلْنَ:","نحن جوارٍ من بني النجار","يا حبذا محمد من جار","فقال النبي ﷺ: (( الله يعلم إني لأحبكنَّ ))."],"takhrij":"حسن: رواه ابن ماجه (١٨٩٩).","grade":"حسن","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1899).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Malik narrated that the Prophet ﷺ passed by part of Madinah and saw some young girls beating their duffs, singing and saying:","“We are girls of Banu al-Najjar,","how wonderful Muhammad is as a neighbor.”","So the Prophet ﷺ said, “Allah knows that I truly love you.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1899}]},{"num":6541,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول الله ﷺ لعائشة: (( أهديتم الجارية إلى بيتها؟ )). قالت: نعم، قال: (( فهلا بعثتم معها من يُغنين يقول:","أتيناكم أتيناكم","فحيّونا نحييكم","فإن الأنصار قوم فيهم غزل ))."],"takhrij":"حسن: رواه أحمد (١٥٢٠٩) والبزار - كشف الأستار (١٤٣٢).","grade":"حسن","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (15209) and al-Bazzar in Kashf al-Astar (1432).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said to ʿA’ishah, “Have you escorted the young bride to her home?” She said: Yes. He said, “Why did you not send with her some who would sing, saying:","‘We have come to you, we have come to you,","so greet us and we will greet you,","for the Ansar are a people among whom there is love poetry.’”"]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار - كشف الأستار","number":1432},{"key":"ahmad","label":"مسند الإمام أحمد","number":15209,"n":15209}]},{"num":6542,"demo":false,"sanad":"","matn":["عن عامر بن سعد البجلي يقول: شهدت ثابت بن وديعة وقرظة بن كعب الأنصاري في عرس، وإذا غناء، فقلت لهما في ذلك فقالا: إنه رُخّصَ في الغناء في العُرس، والبكاء على الميت في غير نياحة."],"takhrij":"صحيح: رواه أبو داود الطيالسي (١٣١٧) والبيهقي (٢٨٩/٧).","grade":"صحيح","chapter_ar":"باب يُستحبّ اللهو، وضرب الدف في الزفاف","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud al-Tayalisi (1317) and al-Bayhaqi (7/289).","chapter_en":"Amusement and Beating the Duff at the Wedding Procession Are Recommended","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["ʿAmir ibn Saʿd al-Bajali said: I was present with Thabit ibn Wadiʿah and Qurzah ibn Kaʿb al-Ansari at a wedding, and there was singing. I spoke to them about that, and they said: Singing has been permitted at weddings, and weeping for the dead without wailing."]}},"tuhfa":{},"refs":[{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسي","number":1317},{"key":"البیہقی","label":"البيهقي","number":289},{"key":"tayalisi","label":"مسند أبي داود الطيالسي","number":1317,"n":1317},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14692,"n":14839}]},{"num":6543,"demo":false,"sanad":"","matn":["عن عقبة بن عامر أن رسول الله ﷺ قال: (( إياكم والدخولَ على النساء )). فقال: رجل من الأنصار: يا رسول الله ﷺ أفرأيت الحمو؟ قال: (( الحموُ موتٌ ))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٣٢) ومسلم (٢١٧٢). والحمْوُ: على وزن الدَلْو، قال النووي: “والمراد بالحمو هنا أقارب الزوج غير آبائه وأبنائه، فأما الآباء والأبناء فمحارم لزوجته، تجوز لهم الخلوة بها ولا يوصفون بالموت، وإنما المراد هو: الأخ وابن الأخ والعم وابنه ونحوهم ممن ليس بمحرم” اه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5232) and Muslim (2172).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir narrated that the Messenger of Allah ﷺ said, “Beware of entering upon women.” A man from the Ansar said: O Messenger of Allah, what about the in-law? He said, “The in-law is death.”"]},"buhuth":{"en":["Al-hamw means the husband’s male relatives other than his fathers and sons. Al-Nawawi said: What is meant here are the husband’s relatives other than his fathers and sons. As for fathers and sons, they are unmarriageable kin to the wife, and seclusion with them is permissible, so they are not described as “death.” Rather, what is meant is the brother, the brother’s son, the uncle, the uncle’s son, and the like among those who are not unmarriageable kin."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5232},{"key":"muslim","label":"مسلم","number":2172}]},{"num":6544,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول الله ﷺ: ( ألا لا يبيتنَّ رجل عند امرأة ثيب، إلا أن يكون ناكحاً، أو ذو محرم ))."],"takhrij":"صحيح: رواه مسلم (٢١٧١).","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2171).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said, “No man must spend the night with a previously married woman unless he is her husband or one who is a mahram to her.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2171}]},{"num":6545,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود قال: قال رسول الله ﷺ: (( ما منكم من أحد إلا وقد وُكِّل به قرينُه من الجن )). قالوا: وإياك يا رسول الله؟ قال: (( وإياي إلا أن الله أعانني عليه فأسلم فلا يأمرني إلا بخير ))."],"takhrij":"صحيح: رواه مسلم (٢٨١٤). فقوله: “أسلم” من الإسلام دون السلامة هذا الذي فسر به جمهور العلماء هذا الحديث إلا سفيان بن عيينة فإنه فسره بقوله: أسلم - أي أجد منه السلامة. يعني أن النبي ﷺ سالم من أن يجري الشيطان فيه مجرى الدم، وهذا لا يشاركه فيه غيره.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2814).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿAbd Allah ibn Masʿud said: The Messenger of Allah ﷺ said, “There is none among you except that his companion from among the jinn has been assigned to him.” They said: Even you, O Messenger of Allah? He said, “Even me, except that Allah helped me against him and he accepted Islam, so he does not command me except with good.”"]},"buhuth":{"en":["His statement, “he accepted Islam,” is understood by the majority of scholars literally as Islam, not merely safety. Sufyan ibn ʿUyaynah explained it as “I am safe from him,” meaning the Prophet ﷺ was protected from Satan flowing through him like blood, and no one shares that with him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2814}]},{"num":6546,"demo":false,"sanad":"","matn":["عن ابن عباس يقول: سمعت النبي ﷺ يقول: (( ألا لا يخلونَّ رجل بامرأةٍ، إلا ومعها ذو محرم ))."],"takhrij":"متفق عليه: رواه مسلم (١٣٤١) والبخاري (٣٠٠٦)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1341) and al-Bukhari (3006), and the wording is that of Muslim.","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbas said: I heard the Prophet ﷺ say, “No man should be alone with a woman unless she has with her a mahram.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1341},{"key":"bukhari","label":"البخاري","number":3006}]},{"num":6547,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص أن نفرا من بني هاشم دخلوا على أسماء بنت عميس، فدخل أبو بكر الصديق، وهي تحته يومئذ، فرآهم. فكره ذلك. فذكر ذلك للنبي ﷺ وقال: لم أر إلا خيراً فقال رسول الله ﷺ (( إن الله قد برأها من ذلك )). ثم قام رسول الله ﷺ على المنبر فقال: (( لا يدخلنَّ رجلٌ بعد يومي هذا على مغيبة إلا ومعه رجل أو اثنان ))."],"takhrij":"صحيح: رواه مسلم (٢١٧٣).","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الدخول على المغيبات","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2173).","chapter_en":"What Has Been Related About the Dislike of Entering Upon Women Whose Husbands Are Absent","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAmr ibn al-ʿAs narrated that a group from Banu Hashim entered upon Asma’ bint ʿUmays. Then Abu Bakr al-Siddiq entered, and she was his wife at that time, and he saw them and disliked that. He mentioned that to the Prophet ﷺ and said: I saw nothing but good. So the Messenger of Allah ﷺ said, “Allah has declared her free of that.” Then the Messenger of Allah ﷺ stood upon the pulpit and said, “No man is to enter upon a woman whose husband is absent after this day unless he is accompanied by one or two men.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2173}]},{"num":6548,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده، قال: قال رسول الله ﷺ (( أيما امرأةٍ نكحت على صداقٍ أو حِباء، أو عِدة قبل عصمة النكاح فهو لها، وما كان بعد عصمة النكاح فهو لمن أُعطيه، وأحق ما أُكرِمَ عليه الرجلُ ابنتُه أو أختُه ))."],"takhrij":"حسن: رواه أبو داود (٢١٢٩) وابن ماجه (١٩٥٥) والنسائي (٣٣٥٣) وأحمد (٦٧٠٩).","grade":"حسن","chapter_ar":"باب أن أحقَّ ما أُكرم عليه الرجلُ ابنتُه أو أختُه","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2129), Ibn Majah (1955), al-Nasa’i (3353), and Ahmad (6709).","chapter_en":"The One Most Deserving That a Man Be Honored Through Is His Daughter or His Sister","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: The Messenger of Allah ﷺ said, “Any woman who is married upon a dowry, or a gift, or a promise before the marriage bond is concluded, then it belongs to her. Whatever is given after the marriage bond is concluded belongs to the one to whom it is given. And the one most deserving that a man be honored through is his daughter or his sister.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2129},{"key":"ibnmajah","label":"ابن ماجه","number":1955},{"key":"nasai","label":"النسائي","number":3353},{"key":"ahmad","label":"مسند الإمام أحمد","number":6709,"n":6709}]},{"num":6549,"demo":false,"sanad":"","matn":["عن علي قال: جهز رسولُ الله ﷺ فاطمةَ في خَميل، وقربة، ووسادة أدم، حشوها ليف الإذخر."],"takhrij":"صحيح: رواه النسائي (٣٣٨٤) وأحمد (٦٤٣).","grade":"صحيح","chapter_ar":"باب جهاز الرجل ابنته","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3384) and Ahmad (643).","chapter_en":"A Man Preparing His Daughter’s Marriage Outfit","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["ʿAli said: The Messenger of Allah ﷺ prepared Fatimah with a velvet cloth, a waterskin, and a leather pillow stuffed with fibers of idhkhir grass."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3384},{"key":"ahmad","label":"مسند الإمام أحمد","number":643,"n":643}]},{"num":6550,"demo":false,"sanad":"","matn":["عن جابر قال: قال لي رسولُ الله ﷺ: (( هل لكم أنماط؟ )). قلت: وأنى يكون لنا الأنماط؟ قال: (( أما أنه سيكون لكم الأنماط )).","قال جابر: فأنا أقول لها - يعني امرأته - أخّري عني أنماطكِ، فتقول: ألم يقل النبي ﷺ: (( إنها ستكونُ لكم الأنماط؟ )) فأدعُها."],"takhrij":"متفق عليه: رواه البخاري (٣٦٣١) ومسلم (٢٠٨٣). واللفظ للبخاري. وقوله: (( الأنماط )): هو ضرب من البسط له حمل رقيق، يستعمل في الغالب في ليلة الزفاف، وفي الليالي التي تليها لاستقبال العروس.","grade":"متفق عليه","chapter_ar":"باب اتخاذ الأنماط ونحوها للعروس عند البناء","chapter_ur":"","part_ar":"كتاب النكاح","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3631) and Muslim (2083), and the wording is that of al-Bukhari.","chapter_en":"Using Carpets and Similar Things for the Bride at the Time of Consummation","part_en":"The Book of Marriage","group_ar":"جموع أبواب ما جاء في وليمة العرس","group_en":"Collection of Chapters on What Has Been Related About the Wedding Feast","part_no":24,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said to me, “Do you have carpets?” I said: How could we have carpets? He said, “But you will indeed have carpets.” Jabir said: So I say to her — meaning his wife — “Keep your carpets away from me,” and she says: Did not the Prophet ﷺ say, “You will indeed have carpets”? So I leave her alone."]},"buhuth":{"en":["Al-anmat are a kind of carpet or mat with a thin layer, generally used on the wedding night and the nights after it to receive the bride."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3631},{"key":"muslim","label":"مسلم","number":2083}]},{"num":6551,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال النبي ﷺ: (( ليس منا من خبّب امرأة على زوجها، أو عبداً على سيده ))."],"takhrij":"صحيح: رواه أبو داود (٢١٧٥) وأحمد (٩١٥٧) وصحّحه ابن حبان (٥٦٨،٥٥٦٠) والحاكم (١٩٦/٢).","grade":"صحيح","chapter_ar":"باب فيمن أفسد امرأة على زوجها","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2175), Ahmad (9157), and authenticated by Ibn Hibban (5560, 568) and al-Hakim (2/196).","chapter_en":"Concerning One Who Corrupts a Woman Against Her Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said, “He is not one of us who turns a woman against her husband, or a slave against his master.”"]},"buhuth":{"ar":["وقوله: (( خبّب)) معناه: أفسد، وخدع، وقد جاء بلفظ “أفسد” في بعض الروايات الأخرى."],"en":["His saying, “turns against,” means: corrupts and deceives. In some other narrations, the wording “corrupts” is used."]},"intro_kitab":{"ar":["بتميّزُ الإسلامُ في جميع شؤون الحياة بمميزاتٍ كثيرةٍ منها:","مشروعية الطلاق: فإنّ الأديانَ السابقةَ على الإسلام لا تعرِفُ الطلاقَ، بل إذا تزوّجَ الرجُلُ بامرأةٍ فعليهما أن يعيشا حياةً أبديةً، لا رجعةً فيها، ولو كانت الحياةُ فيها شقاوةٌ وبؤسّ، فإنهم كانوا يقولون: مَنْ ارتبطَ في الأرض فكأنها ارتبطَ في السماء .","فجاء الإسلامُ، وألْغَى هذه الأغلالَ ليتحرّر كلُّ من الزوجين عن الآخر إذا كانت الحياةُ لا ستقيمُ، فيبدأ كلِّ منهما حياةً جديدةً، وقد انتقدَ كثيرٌ من الباحثين غير المسلمين مشروعية الطلاق في الإسلام، لأنهم لم يعرفوا مقاصد الشريعة في مشروعية الطلاق، ثم إنّ الطلاق في الإسلام ليس بأمرٍ سهل كما يتصوّره البعض إلا أن تصرّف بعض الناس أساء إلى مشروعية الطلاق.","في الأسطر القادمة أوضَحُ لكم أن الطلاق لم يُشرع في الإسلام إلا في ظروفٍ معيّنةٍ ضيّقةٍ، ليس للزّوج مخرَجٌ منها إلا بالطلاق، فمن المعلوم أن عقد النكاح يتمَّ بالإيجاب والقبول مع الصداق والشاهدين، بخلاف الطلاق الشرعي فله عدّةُ مراحل، لَوْ لُوْحِظَتْ لقلَّما يقعُ الطلاقُ بين الزوجين، ومن هذه المراحل:","إنّ المفارقة بين الزوجين لا تكون بطلاقٍ واحدٍ، بل لا بد أن يطلق مرّتين، ثم لا تَبِيْنُ المرأةُ على الزوج حتى يطلّقَها الطلاقَ الثالثَ.","ومن شروط الطلاق أن يطلّق الزوج في طهر لم يجامع فيه، ويطلّق طلاقًا واحدًا رجعيًّا، وتبقى المرأة في بيت زوجها، ولا يجوز إخراجها منه، ثم على المرأة أيضًا أن لا تخرج إلى بيت أهلها، بل تبقى في بيت زوجها حتى تنقضي عدتها. قال تعالى: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ وَاتَّقُوا اللَّهَ رَبَّكُمْ لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ﴾ [الطلاق: ١].","في قضاء العدة في بيت الزوج حكمةً من الله تعالى، وهي أن يشعر الإنسان بخطئه، أو يتصالحان على نزاعهما، فيرجع عنه الزوجُ قبل انقضاء العدة، ولا يُقدِم على الطلاق الثاني.","إنْ أدركَ الزوجُ أنه إنْ طلَّقَ الطلاقَ الثالثَ، فالزوجةُ تبِيْنُ منه، ولا تحلُّ له حتى تنكحَ زوجًا آَخْرُ إنّ أرادَ الرجوعَ، فغيرتُه قد تمنعُ من إيقاع الطلاق الثالث، فيرجع قبل انقضاء العدة في الطلاق الثاني، وله أن يتزوّج بعد العدّة بنكاحِ جديدٍ وبمهر جديدٍ.","إذا كان للزوجين مولودٌ، فالغالب أنه يكون حِصنًا منيعًا من مفارقة الأبوين.","ومن أهم مراحل الطلاق إذا وقع الخصام بين الزوجين، فأمر الله تعالى بالإصلاح في قوله: ﴿وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا إِنْ يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا إِنَّ اللَّهَ كَانَ عَلِيمًا خَبِيرًا﴾ [النساء: ٣٥].","من الخطأ الذي يقع في الطلاق أن المرأة إذا طلقت تطليقة واحدة، تخرج من بيت زوجها إلى أهلها، ونساءُ أهلها يُنفّرنَ من الزوج، ويُقبّحن العمل الذي وقعَ منه، فلم يتمكّن الزوجُ من الرجوع عن طلاقه الأول لعدم وجود المرأة في بيته مما يزيده تنافرًا.","ومن الخطأ الشائع أيضا أن الزوج يطلّقها ثلاثا دفعةً واحدةً، ويُفَوِّت الفرصةَ للرجوع عن طلاقه فهو مخالفٌ لأمرين من أمر الله تعالى:","أولاً: أنه طلّق ثلاث تطليقات مرة واحدة، والله تعالى يقول: ﴿الطَّلَاقُ مَرَّتَانِ﴾ [البقرة: ٢٢٩].","ثانيا: أنه فوّتَ البقاء مع زوجها بعد طلاقه الأول.","ولا شك لو طُبّقت هذه الشروط لقلّما يقعُ الطلاق بين الزوجين. والله الموفق"],"en":["Islam is distinguished in all areas of life by many unique features, among them:","The lawfulness of divorce: the religions before Islam did not recognize divorce. Rather, if a man married a woman, they were expected to live together permanently with no return, even if that life was full of misery and hardship. They used to say: whoever is joined on earth is as though joined in heaven.","Then Islam came and removed these shackles, so that each spouse may be freed from the other if the marriage cannot continue, and each may begin a new life. Many non-Muslim researchers criticized the lawfulness of divorce in Islam because they did not understand the objectives of the Sacred Law in permitting divorce. Also, divorce in Islam is not something easy as some imagine, although some people’s conduct has harmed the proper understanding of its lawfulness.","In the coming lines, I will explain that divorce was only legislated in Islam in certain narrow circumstances in which the husband has no way out except divorce. It is known that the marriage contract is concluded by offer and acceptance along with the dowry and two witnesses. By contrast, a valid Islamic divorce has several stages, which, if observed, would make divorce between spouses very rare. Among these stages are:","Separation between spouses is not finalized with a single divorce. Rather, he must divorce twice, and the woman does not become fully separated from her husband until he gives the third divorce.","Among the conditions of divorce is that the husband divorce her in a state of purity in which he has not had intercourse with her, and that he give only one revocable divorce. The woman remains in her husband’s house, and it is not permissible to turn her out of it. Likewise, the woman should not leave to her family’s home, but remain in her husband’s home until her waiting period ends. Allah the Exalted said: “O Prophet, when you divorce women, divorce them for their waiting period, and count the waiting period, and fear Allah your Lord. Do not turn them out of their houses, nor should they leave…” [Surat al-Talaq: 1]","In completing the waiting period in the husband’s home, there is wisdom from Allah the Exalted: a person may realize his mistake, or the two may reconcile in their dispute, so the husband takes her back before the waiting period ends and does not proceed to the second divorce.","If the husband realizes that, should he pronounce the third divorce, the wife will become fully separated from him and will not be lawful for him until she marries another husband if he wants her back, then his jealousy may prevent him from issuing the third divorce. So he may take her back before the waiting period ends after the second divorce. After the waiting period, he may also remarry her through a new marriage contract and a new dowry.","If the couple have a child, that usually becomes a strong barrier against the parents separating.","Among the most important stages regarding divorce is when conflict occurs between the spouses. Allah the Exalted commanded reconciliation in His statement: “And if you fear a breach between them, appoint an arbitrator from his family and an arbitrator from her family. If they both desire reconciliation, Allah will cause harmony between them. Indeed, Allah is Knowing and Aware.” [Surat al-Nisa’: 35]","One mistake that occurs in divorce is that when a woman is given one divorce, she leaves her husband’s house and goes to her family, and the women of her family turn her away from her husband and make his action seem worse, so the husband is unable to take back his first divorce because the woman is no longer in his house, and this only increases estrangement.","Another common mistake is that the husband divorces her three times at once and loses the opportunity to take her back. In doing so, he opposes two commands of Allah the Exalted:","First: he pronounced three divorces in one sitting, while Allah the Exalted says: “Divorce is twice.”","Second: he lost the opportunity of remaining with his wife after the first divorce.","Without doubt, if these conditions were applied, divorce between spouses would rarely occur. And Allah is the Granter of success."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2175},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":568},{"key":"ahmad","label":"مسند الإمام أحمد","number":9157,"n":9157},{"key":"hakim","label":"المستدرك على الصحيحين","number":2795,"n":2781}]},{"num":6552,"demo":false,"sanad":"","matn":["عن بريدة بن حصيب قال: قال رسول الله ﷺ: (( ليس منا من حلف بالأمانة، ومن خبّب على امرئ زوجته، أو مملوكه )."],"takhrij":"صحيح: رواه ابو داود (٣٢٥٣) وأحمد (٢٢٩٨٠) وصحّحه ابن حبان (٤٣٦٣) والحاكم (٢٩٨/٤).","grade":"صحيح","chapter_ar":"باب فيمن أفسد امرأة على زوجها","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3253), Ahmad (22980), and authenticated by Ibn Hibban (4363) and al-Hakim (4/298).","chapter_en":"Concerning One Who Corrupts a Woman Against Her Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Buraydah ibn al-Husayb said: The Messenger of Allah ﷺ said, “He is not one of us who swears by trust, or who turns a man’s wife or slave against him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":3253},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4363},{"key":"hakim","label":"الحاكم","number":298},{"key":"ahmad","label":"مسند الإمام أحمد","number":22980,"n":22980}]},{"num":6553,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر قال: كانت تحتي امرأة، وكنت أحبها، وكان عمر يكرهها، فقال لي: طلِّقها، فأبيت، فأتى عمر رسول الله ﷺ فذكر ذلك له، فقال النبي ﷺ: (( طلِّقها )).","وفي رواية: (( أطعْ أباك)»."],"takhrij":"حسن: رواه أبو داود (٥١٣٨) والترمذي (١١٨٩) وابن ماجه (٢٠٨٨) وأحمد (٤٧١١) قال الترمذي: حسن صحيح.","grade":"حسن","chapter_ar":"باب طلاق المرء امرأته بأمر أبيه إذا لم يكن فيه مفسدة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (5138), al-Tirmidhi (1189), Ibn Majah (2088), and Ahmad (4711). Al-Tirmidhi said: Hasan Sahih.","chapter_en":"A Man Divorcing His Wife at His Father’s Command If There Is No Harm in It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar said: I had a wife whom I loved, but ʿUmar disliked her. He told me, “Divorce her,” but I refused. Then ʿUmar came to the Messenger of Allah ﷺ and mentioned that to him. The Prophet ﷺ said, “Divorce her.”","In another narration: “Obey your father.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5138},{"key":"tirmidhi","label":"الترمذي","number":1189},{"key":"ibnmajah","label":"ابن ماجه","number":2088},{"key":"ahmad","label":"مسند الإمام أحمد","number":4711,"n":4711}]},{"num":6554,"demo":false,"sanad":"","matn":["عن أبي الدرداء أن رجلا أتاه فقال: إن لي امرأة، وإن أمي تأمرني بطلاقها. قال أبو الدرداء: سمعت رسول الله ﷺ يقول: (( الوالد أوسط أبواب الجنة، فإن شئت فأضِعْ ذلك البابَ، أو احفظه »."],"takhrij":"صحيح: رواه الترمذي (١٩٠٠) وأحمد (٢٧٥١١) والحاكم (١٥٢/٤). قال الترمذي: “هذا حديث صحيح”.","grade":"صحيح","chapter_ar":"باب طلاق المرء امرأته بأمر أبيه إذا لم يكن فيه مفسدة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1900), Ahmad (27511), and al-Hakim (4/152). Al-Tirmidhi said: “This is an authentic hadith.”","chapter_en":"A Man Divorcing His Wife at His Father’s Command If There Is No Harm in It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abu al-Darda’ narrated that a man came to him and said: I have a wife, and my mother commands me to divorce her. Abu al-Darda’ said: I heard the Messenger of Allah ﷺ say, “The parent is the middle gate of Paradise, so if you wish, neglect that gate, or preserve it.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1900},{"key":"hakim","label":"الحاكم","number":152},{"key":"ahmad","label":"مسند الإمام أحمد","number":27511,"n":27511}]},{"num":6555,"demo":false,"sanad":"","matn":["عن جابر قال: قال رسول الله ﷺ: (( إن إبليس يضع عرشه على الماء، ثم يبعث سراياه، فأدناهم منه منزلة أعظمهم فتنة. يجيء أحدهم فيقول: فعلت كذا وكذا. فيقول: ما صنعت شيئا. قال: ثم يجيء أحدهم فيقول: ما تركته حتى فَرَّقْتُ بينه وبين امرأته. قال: فيدنيه منه، ويقول: نِعْمَ أنت ))."],"takhrij":"صحيح: رواه مسلم (٦٧/٢٨١٢).","grade":"صحيح","chapter_ar":"باب من أعظم فتنة الشيطان التفريق بين المرء وزوجه","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2812 no. 67).","chapter_en":"One of Satan’s Greatest Trials Is Causing Separation Between a Man and His Wife","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said, “Iblis places his throne upon the water, then sends out his detachments. The closest of them to him in rank is the one who causes the greatest trial. One of them comes and says: I did such-and-such. He says: You have done nothing. Then another comes and says: I did not leave him until I separated him from his wife. Then he draws him near and says: You are excellent.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":67}]},{"num":6556,"demo":false,"sanad":"","matn":["عن نافع، أن عبد الله بن عمر طلق امرأته وهي حائض على عهد رسول الله ﷺ فسأل عمر بن الخطاب رسول الله ﷺ عن ذلك. فقال رسول الله ﷺ: (( مُرْه فليراجِعْها، ثم يمسكها حتى تطهرَ، ثم تحيض، ثم تطهر، ثم إن شاء أمسك بعد وإن شاء طلّق قبل أن يمسّ، فتلك العدة التي أمر الله أن يطلق لها النساء ))."],"takhrij":"صحيح: رواه مالك (٥٣)، والبخاري (٥٢٥١)، ومسلم (١:١٤٧١).","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (53), al-Bukhari (5251), and Muslim (1471 no. 1).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Nafiʿ narrated that ʿAbd Allah ibn ʿUmar divorced his wife while she was menstruating during the time of the Messenger of Allah ﷺ. So ʿUmar ibn al-Khattab asked the Messenger of Allah ﷺ about that. The Messenger of Allah ﷺ said, “Command him to take her back, then keep her until she becomes pure, then menstruates, then becomes pure. Then if he wishes, he may keep her after that, or if he wishes, he may divorce her before touching her. That is the waiting period for which Allah commanded that women be divorced.”"]},"buhuth":{"ar":["ورواه مسلم أيضا من طريق آخر، عن ابن عمر قال: طلقت امرأتي على عهد رسول الله ﷺ وهي حائض، فذكر ذلك عمر لرسول الله ﷺ فقال: (( مُرْهُ فليراجعها، ثم ليدعها حتى تطهر، ثم تحيض حيضة أخرى، فإذا طهرت فليطلقها قبل أن يجامعها، أو يمسكها، فإنها العدة التي أمر الله أن يطلق لها النساء ))."],"en":["Muslim also narrated it through another route from Ibn ʿUmar, who said: I divorced my wife during the time of the Messenger of Allah ﷺ while she was menstruating. ʿUmar mentioned that to the Messenger of Allah ﷺ, and he said: “Command him to take her back, then let her remain until she becomes pure, then menstruates another menstruation. Then when she becomes pure, let him divorce her before having relations with her, or keep her, for that is the waiting period for which Allah commanded that women be divorced.”"]},"intro":{"ar":["قال الله تعالى: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾ [الطلاق: ١].","أي إذا أردتم تطليق النساء فطلقوهن مستقبلات العدة. والمطلقة تستقبل العدة إذا طلقت بعد أن تطهر من الحيض والنفاس قبل أن يمسها زوجها. وقيل: إن الحكمة في منع الطلاق في الحيض أو النفاس تطويل العدة، إن كانت الأقراء هي الأطهار. واللفظ الوارد في حديث عبد الله بن عمر جاء على أوجه:","الوجه الأول: “ثم يمسكها حتى تطهر، ثم تحيض، ثم تطهر، ثم إن شاء أمسك وإن شاء طلق قبل أن يمسها”.","ممن رواه عن عبد الله بن عمر الوجه الأول:"],"en":["Allah the Exalted said: “O Prophet, when you divorce women, divorce them for their waiting period” [Surat al-Talaq: 1]","Meaning: if you intend to divorce women, then divorce them at a time when they are beginning their waiting period. A divorced woman begins her waiting period properly if she is divorced after becoming pure from menstruation or postnatal bleeding and before her husband has relations with her. It is also said that the wisdom behind forbidding divorce during menstruation or postnatal bleeding is to prevent lengthening the waiting period, if the periods are counted as states of purity. The wording reported in the hadith of ʿAbd Allah ibn ʿUmar came in different forms:","First wording: “Then he should keep her until she becomes pure, then menstruates, then becomes pure, then if he wishes he may keep her, and if he wishes he may divorce her before touching her.”","Among those who narrated this first wording from ʿAbd Allah ibn ʿUmar:"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":53},{"key":"bukhari","label":"البخاري","number":5251},{"key":"muslim","label":"مسلم","number":1}]},{"num":6557,"demo":false,"sanad":"","matn":["عن سالم بن عبد الله أن عبد الله بن عمر قال: طلّقت امرأتي وهي حائض. فذكر ذلك عمر للنبي ﷺ، فتغيظ رسول الله ﷺ ثم قال: (( مره فليراجعها حتى تحيض حيضة أخرى مستقبلة، سوى حيضتها التي طلقها فيها، فإن بدا له أن يطلقها، فليطلقها طاهراً من حيضتها قبل أن يمسها، فذلك الطلاق للعدة كما أمر الله ) وكان عبد الله طلقها تطليقة واحدة، فحسبت من طلاقها، وراجعها عبد الله كما أمره رسول الله ﷺ."],"takhrij":"صحيح: رواه البخاري (٤٩٠٨)، ومسلم (٤:١٤٧١). واللفظ لمسلم.","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4908) and Muslim (1471 no. 4), and the wording is that of Muslim.","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Salim ibn ʿAbd Allah narrated that ʿAbd Allah ibn ʿUmar said: I divorced my wife while she was menstruating. ʿUmar mentioned that to the Prophet ﷺ. The Messenger of Allah ﷺ became angry, then said, “Command him to take her back until she menstruates another menstrual cycle, different from the one in which he divorced her. Then if he decides to divorce her, let him divorce her while she is pure from that menstruation before touching her. That is the divorce for the waiting period as Allah commanded.” Ibn ʿUmar had divorced her with one divorce, and it was counted as part of her divorces, and ʿAbd Allah took her back as the Messenger of Allah ﷺ commanded him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4908},{"key":"muslim","label":"مسلم","number":4}]},{"num":6558,"demo":false,"sanad":"","matn":["عن عبد الله بن دينار، عن ابن عمر أنه طلق امرأته وهي حائض، فسأل عمرُ عن ذلك رسول الله ﷺ فقال: (( مره فليراجعها حتى تطهر، ثم تحيض، ثم تطهر، ثم يطلق بعد أو يمسك ))."],"takhrij":"صحيح: رواه مسلم (٦:١٤٧١).","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1471 no. 6).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbd Allah ibn Dinar narrated from Ibn ʿUmar that he divorced his wife while she was menstruating. ʿUmar asked the Messenger of Allah ﷺ about that, and he said, “Command him to take her back until she becomes pure, then menstruates, then becomes pure, then after that he may divorce her or keep her.”"]},"buhuth":{"ar":["الوجه الثاني: إنه أمر بمراجعتها. فإذا طهرت فليطلقها لطهرها."],"en":["Second wording: he commanded that she be taken back, and when she becomes pure, he may divorce her in that state of purity."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":6}]},{"num":6559,"demo":false,"sanad":"","matn":["عن أنس بن سيرين قال: سألت ابن عمر عن امرأته التي طلق. فقال: طلقتها وهي حائض، فذُكر ذلك لعمر، فذكره للنبي ﷺ فقال: (( مره فليراجعها، فإذا طهرت فليطلقها لطهرها )) قال: فراجعتها ثم طلقتها لطهرها، قلت: فاعتددت بتلك التطليقة التي طلقت وهي حائض؟ قال: ((مالي لا أعتد بها؟ وإن كنت عجزت واستحمقت ))."],"takhrij":"صحيح: رواه البخاري (٥٢٥٢) ومسلم (١٢:١٤٧١). واللفظ لمسلم.","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5252) and Muslim (1471 no. 12), and the wording is that of Muslim.","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Sirin said: I asked Ibn ʿUmar about the wife whom he had divorced. He said: I divorced her while she was menstruating, and that was mentioned to ʿUmar, who mentioned it to the Prophet ﷺ. He said, “Command him to take her back, then when she becomes pure let him divorce her in her purity.” He said: So I took her back, then divorced her in her purity. I said: Did you count that divorce in which you divorced her while she was menstruating? He said: “Why would I not count it, even though I acted foolishly and ignorantly?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5252},{"key":"muslim","label":"مسلم","number":12}]},{"num":6560,"demo":false,"sanad":"","matn":["عن أبي الزبير أنه سمع عبد الله بن عبد الرحمن بن أيمن مولى عزة يسأل ابن عمر - وأبو الزبير يسمع ذلك -: كيف ترى في رجل طلق امرأته حائضاً؟ فقال: طلق ابن عمر امرأته وهي حائض على عهد رسول الله ﷺ فسأل عمر رسول الله ﷺ فقال: إن عبد الله بن عمر طلق امرأته وهي حائض، فقال له رسول الله ﷺ: (( ليراجعها )) فردها وقال: (( إذا طهرت فليطلق أو ليمسك ))","قال ابن عمر: وقرأ النبي ﷺ: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾ [الطلاق: ١]."],"takhrij":"صحيح: رواه مسلم (١٤:١٤٧١).","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1471 no. 14).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Abu al-Zubayr heard ʿAbd Allah ibn ʿAbd al-Rahman ibn Ayman, the freedman of ʿAzzah, asking Ibn ʿUmar — while Abu al-Zubayr was listening —: What do you think about a man who divorces his wife while she is menstruating? He replied: Ibn ʿUmar divorced his wife while she was menstruating in the time of the Messenger of Allah ﷺ. So ʿUmar asked the Messenger of Allah ﷺ and said: ʿAbd Allah ibn ʿUmar divorced his wife while she was menstruating. The Messenger of Allah ﷺ said, “Let him take her back.” So he returned her and said, “When she becomes pure, then let him divorce her or keep her.” Ibn ʿUmar said: The Prophet ﷺ recited: “O Prophet, when you divorce women, divorce them for their waiting period.” [Surat al-Talaq: 1]"]},"buhuth":{"ar":["الوجه الثالث: مجمل، وهو أنه طلق امرأته وهي حائض فأمر أن يراجعها. كما في الرواية الآتية:"],"en":["Third wording: concise, which is that he divorced his wife while she was menstruating, so he was ordered to take her back, as in the following narration:"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":14}]},{"num":6561,"demo":false,"sanad":"","matn":["عن ابن سيرين قال: مكثت عشرين سنة يحدثني من لا أتهم أن ابن عمر طلق امرأته ثلاثا وهي حائض. فأمر أن يراجعها. فجعلت لا أتهمهم ولا أعرف الحديث حتى لقيت أبا غلاّب يونس بن جبير الباهلي. وكان ذا ثبت فحدثني أنه سأل ابن عمر، فحدثه أنه طلق امرأته تطليقة وهي حائض، فأمر أن يَرجِعَها. قال: قلت: أفحسبت عليه؟ قال: فمه، أو إن عجز واستحمق؟"],"takhrij":"صحيح: رواه البخاري (٥٣٣٣)، ومسلم (٧:١٤٧١). واللفظ لمسلم.","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5333) and Muslim (1471 no. 7), and the wording is that of Muslim.","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Sirin said: For twenty years, trustworthy people told me that Ibn ʿUmar divorced his wife three times while she was menstruating, and that he was ordered to take her back. I did not suspect them, but I did not know the hadith properly until I met Abu Ghallab Yunus ibn Jubayr al-Bahili, who was reliable and precise. He told me that he had asked Ibn ʿUmar, and Ibn ʿUmar told him that he divorced his wife with one divorce while she was menstruating, and he was ordered to take her back. He said: I asked, Was it counted against him? He replied: “Of course — unless one is incapable and foolish?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5333},{"key":"muslim","label":"مسلم","number":7}]},{"num":6562,"demo":false,"sanad":"","matn":["عن عبد الله أنه قال: طلاق السنة تطليقة وهي طاهر، في غير جماع، فإذا حاضت، وطهرت طلّقها أخرى، فإذا حاضت وطهرت طلّقها أخرى، ثم تعتد بعد ذلك بحيضة."],"takhrij":"صحيح: رواه النسائي (٣٣٩٤) واللفظ له، وابن ماجه (٢٠٢١).","grade":"صحيح","chapter_ar":"باب طلاق السنة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3394), and this is his wording, and Ibn Majah (2021).","chapter_en":"Divorce According to the Sunnah","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbd Allah said: Divorce according to the Sunnah is one divorce while she is pure and without intercourse. Then if she menstruates and becomes pure, he divorces her a second time. Then if she menstruates and becomes pure, he divorces her a third time. Then after that she observes her waiting period with one menstrual cycle."]},"buhuth":{"ar":["طلاق السنة عند الأئمة إذا توفرت فيه أربعة شروط:","١- أن تكون طاهرا.","٢- لم يمسها في ذلك الطهر.","٣- أن يطلقها طلقة واحدة.","٤- أن لا يتبعها طلاقا آخر حتى تنقضي العدة."],"en":["According to the Imams, divorce according to the Sunnah is when four conditions are met:","1. She is in a state of purity.","2. He has not had intercourse with her in that state of purity.","3. He divorces her with one single divorce.","4. He does not follow it with another divorce until the waiting period has ended."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3394},{"key":"ibnmajah","label":"ابن ماجه","number":2021}]},{"num":6563,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: قال رسول الله ﷺ (( لا طلاق إلا فيما تملك، ولا عتق إلا فيما تملك، ولا بيع إلا فيما تملك، ولا وفاء نذر إلا فيما تملك»."],"takhrij":"حسن: رواه أبو داود (٢١٩٠) والترمذي (١١٨١) والنسائي (٤٦١٣) قال الترمذي: “حسن صحيح”","grade":"حسن","chapter_ar":"باب لا طلاق قبل النكاح","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2190), al-Tirmidhi (1181), and al-Nasa’i (4613). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"There Is No Divorce Before Marriage","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, said: The Messenger of Allah ﷺ said, “There is no divorce except regarding one whom you possess, no emancipation except of what you possess, no sale except of what you possess, and no fulfillment of a vow except regarding what you possess.”"]},"intro":{"ar":["قال الله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَكَحْتُمُ الْمُؤْمِنَاتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا﴾ [الأحزاب: ٤٩].","عن ابن عباس قال: “جعل الله الطلاق بعد النكاح”. ذكره البخاري تعليقا في الطلاق (٣٨١/٩-مع الفتح)"],"en":["Allah the Exalted said: “O you who believe, when you marry believing women and then divorce them before you have touched them, then there is no waiting period for you to count against them.” [Surat al-Ahzab: 49]","Ibn ʿAbbas said: “Allah placed divorce after marriage.” Al-Bukhari mentioned it in a suspended form in the Book of Divorce (9/381 with al-Fath)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2190},{"key":"tirmidhi","label":"الترمذي","number":1181},{"key":"nasai","label":"النسائي","number":4613}]},{"num":6564,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( إن الله تجاوز لأمتي ما حدّثت به أنفُسُها ما لم يتكلموا أو يعملوا))."],"takhrij":"متفق عليه: رواه البخاري (٢٥٢٨) ومسلم (١٢٧).","grade":"متفق عليه","chapter_ar":"باب الوسوسة في الطلاق","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2528) and Muslim (127).","chapter_en":"Misgivings and Whisperings Regarding Divorce","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said, “Allah has pardoned my nation for what their souls whisper to them, so long as they do not speak of it or act upon it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2528},{"key":"muslim","label":"مسلم","number":127}]},{"num":6565,"demo":false,"sanad":"","matn":["عن عائشة تقول: سمعت رسول الله ﷺ يقول: (( لا طلاق ولا عتاق في إغلاق))."],"takhrij":"حسن بالمتابعات: رواه أبو داود (٢١٩٣) وابن ماجه (٢٠٤٦) والدار قطني (٣٦/٤) والحاكم (١٩٨/٢).","grade":"حسن بالمتابعات","chapter_ar":"باب ما جاء في طلاق المُكرَه","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan through supporting narrations: Narrated by Abu Dawud (2193), Ibn Majah (2046), al-Daraqutni (4/36), and al-Hakim (2/198).","chapter_en":"What Has Been Related About the Divorce of One Who Is Forced","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿA’ishah said: I heard the Messenger of Allah ﷺ say, “There is no divorce and no emancipation in a state of coercion.”"]},"buhuth":{"ar":["وقوله: (( إغلاق)) فسروه بالإكراه، لأن المكره يغلق عليه أمره، وتصرفه، وقيل: كأن يغلق عليه الباب ويحبس، ويضيق عليه حتى يطلق. وقال الخطابي: “معنى “ الإغلاق” الإكراه، وكان عمر بن الخطاب، وعلي بن أبي طالب، وابن عمر، وابن عباس، رضي الله عنهم لا يرون طلاق المكره طلاقا”."],"en":["His saying, “in a state of coercion,” was explained as compulsion, because the compelled person is constrained in his judgment and action. It was also said to mean that the door is shut on him, he is confined, and pressured until he divorces. Al-Khattabi said: “The meaning of ‘closure’ is compulsion.” And ʿUmar ibn al-Khattab, ʿAli ibn Abi Talib, Ibn ʿUmar, and Ibn ʿAbbas, may Allah be pleased with them, did not regard the divorce of the compelled person as valid."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2193},{"key":"ibnmajah","label":"ابن ماجه","number":2046},{"key":"الدار_قطنی","label":"الدار قطني","number":36},{"key":"hakim","label":"المستدرك على الصحيحين","number":2802,"n":2788}]},{"num":6566,"demo":false,"sanad":"","matn":["عن عائشة أن رسول الله ﷺ قال: (( رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن الصغير حتى يكبر، وعن المجنون حتى يعقل أو يُفيق ))."],"takhrij":"حسن: رواه أبو داود (٤٣٩٨) والنسائي (١٥٦/٦) وابن ماجه (٢٠٤١) وأحمد (٢٤٦٩٤).","grade":"حسن","chapter_ar":"باب طلاق النائم والصغير والمعتوه","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (4398), al-Nasa’i (6/156), Ibn Majah (2041), and Ahmad (24694).","chapter_en":"The Divorce of the Sleeper, the Minor, and the Mentally Unsound","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿA’ishah narrated that the Messenger of Allah ﷺ said, “The pen has been lifted from three: from the sleeper until he wakes, from the child until he grows up, and from the insane person until he regains reason or recovers.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4398},{"key":"nasai","label":"النسائي","number":156},{"key":"ibnmajah","label":"ابن ماجه","number":2041},{"key":"ahmad","label":"مسند الإمام أحمد","number":24694,"n":24694}]},{"num":6567,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله ﷺ قال: (( ثلاثٌ جِدُّهن جِدٌّ، وهزلهن جِدٌّ، النكاحُ، والطلاقُ، والرجعةُ ))."],"takhrij":"حسن: رواه أبو داود (٢١٩٤) والترمذي (١١٨٤) وحسّنه، وابن ماجه (٢٠٣٩) وابن الجارود (٧١٢).","grade":"حسن","chapter_ar":"باب ما جاء في الجد والهزل في الطلاق","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2194), al-Tirmidhi (1184), who graded it Hasan, Ibn Majah (2039), and Ibn al-Jarud (712).","chapter_en":"What Has Been Related About Seriousness and Jesting in Divorce","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said, “Three matters whose seriousness is serious and whose joking is serious: marriage, divorce, and taking back one’s wife.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2194},{"key":"tirmidhi","label":"الترمذي","number":1184},{"key":"ibnmajah","label":"ابن ماجه","number":2039},{"key":"ابن_الجارود","label":"ابن الجارود","number":712}]},{"num":6568,"demo":false,"sanad":"","matn":["عن عمران بن حصين:","سُئل عن الرجل يطلق امرأته، ثم يقع بها، ولم يشهد على طلاقها ولا على رجعتها، فقال:","«طَلَّقْتَ لِغَيْرِ سُنَّةٍ، وَرَاجَعْتَ لِغَيْرِ سُنَّةٍ. أَشْهِدْ عَلَى طَلَاقِهَا، وَعَلَى رَجْعَتِهَا، وَلَا تَعُدْ»."],"takhrij":"حسن: رواه أبو داود (٢١٨٦)، وابن ماجه (٢٠٢٥).","grade":"حسن","chapter_ar":"باب الإشهاد على الطلاق والمراجعة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2186) and Ibn Mājah (2025).","chapter_en":"Having Witnesses for Divorce and Taking Back One’s Wife","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn was asked about a man who divorced his wife and then resumed marital relations with her without taking witnesses either for the divorce or for taking her back.","He said:","“You divorced contrary to the Sunnah, and you took her back contrary to the Sunnah. Take witnesses to her divorce and to taking her back, and do not do this again.”"]},"buhuth":{"ar":["وقوله تعالى:","﴿وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ﴾","[الطلاق: ٢]","على هذين الفعلين، وهما الطلاق والرجعة، والأمر للندب كقوله تعالى:","﴿وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ﴾","[البقرة: ٢٨٢]","وقوله تعالى:","﴿فَإِذَا دَفَعْتُمْ إِلَيْهِمْ أَمْوَالَهُمْ فَأَشْهِدُوا عَلَيْهِمْ﴾","[النساء: ٦]","لأن الإشهاد في المبايعة ليس بواجب، فكذلك في الطلاق والرجعة."],"en":["Allah Most High says:","“And call to witness two just men from among you.”","[al-Ṭalāq: 2]","This applies to both acts: divorce and taking the wife back. The command is understood as a recommendation, like His saying:","“And take witnesses when you conduct a transaction.”","[al-Baqarah: 282]","And His saying:","“Then when you hand over their wealth to them, take witnesses over them.”","[al-Nisāʾ: 6]","Since taking witnesses in a sale is not obligatory, likewise it is not obligatory in divorce and taking a wife back."]},"intro":{"ar":["قال تعالى: ﴿فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ﴾ [الطلاق: ٢]."],"en":["Allah the Exalted said: “Then retain them in a fair manner or part with them in a fair manner, and call to witness two just men from among you.” [Surat al-Talaq: 2]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2186},{"key":"ibnmajah","label":"ابن ماجه","number":2025}]},{"num":6569,"demo":false,"sanad":"","matn":["عن ابن عباس قال: كان الطلاق على عهد رسول الله ﷺ وأبي بكر وسنتين من خلافة عمر، طلاق الثلاث واحدة، فقال عمر بن الخطاب: إن الناس قد استعجلوا في أمر قد كانت لهم فيه أناة، فلو أمضيناه عليهم فأمضاه عليهم."],"takhrij":"صحيح: رواه مسلم (١٤٧٢).","grade":"صحيح","chapter_ar":"باب عدد الطلاق في عهد النبي ﷺ والخلفاء الراشدين","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1472).","chapter_en":"The Number of Divorces During the Time of the Prophet ﷺ and the Rightly Guided Caliphs","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: During the time of the Messenger of Allah ﷺ, Abu Bakr, and the first two years of ʿUmar’s caliphate, a threefold divorce counted as one. Then ʿUmar ibn al-Khattab said: “People have rushed into a matter in which they previously had time to reflect, so if we enforce it upon them…” So he enforced it upon them."]},"buhuth":{"ar":["وفي قول ابن عباس إشارة إلى إجماع الصحابة في عهد أبي بكر (وهو سنتان وكسور) وسنتين من خلافة عمر على أن الثلاث كانت واحدة، ثم أمضاه عمر بن الخطاب فجعل الثلاثة ثلاثة. ولكن لم تجتمع الأمة على هذا، فكان الذين خالفوه من الصحابة وأفتوا بخلافه: الزبير بن العوام، وعبد الرحمن بن عوف، وعلي بن أبي طالب، وابن مسعود، ومن التابعين عكرمة، وطاوس، ومن بعدهم: محمد بن إسحاق، وبعض أصحاب مالك، وبعض أصحاب أبي حنيفة، وبعض أصحاب أحمد، وأما الذين بعدهم فهم عدد لا يُحصَون، منهم شيخ الإسلام ابن تيمية، وتلميذه ابن القيم وغيرهم."],"en":["In the statement of Ibn ʿAbbas there is an indication of the consensus of the Companions during the time of Abu Bakr — which lasted two years and some months — and for two years of the caliphate of ʿUmar, that a triple divorce counted as one. Then ʿUmar ibn al-Khattab enforced it and made the three count as three. However, the Muslim community did not unanimously agree upon this. Among the Companions who differed with him and issued rulings contrary to it were al-Zubayr ibn al-ʿAwwam, ʿAbd al-Rahman ibn ʿAwf, ʿAli ibn Abi Talib, and Ibn Masʿud; among the Followers were ʿIkrimah and Tawus; and among those after them were Muhammad ibn Ishaq, some companions of Malik, some companions of Abu Hanifah, and some companions of Ahmad. As for those who came later, they are too numerous to count, among them Shaykh al-Islam Ibn Taymiyyah, his student Ibn al-Qayyim, and others."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1472}]},{"num":6570,"demo":false,"sanad":"","matn":["عن ابن عباس قال: طلق ركانة بن عبد يزيد أخو بني مطلب امرأته ثلاثا في مجلس واحد، فحزن عليها حزنا شديدا، قال: فسأله رسول الله ﷺ: (( كيف طلّقتها؟) قال: طلقتها ثلاثا.","قال: (( في مجلس واحد؟ )) قال: نعم، قال: (( فإنما تلك واحدة، فارجعها إن شئت)).","قال: فرجعها. فكان ابن عباس يرى أنما الطلاق عند كل طهر."],"takhrij":"حسن: رواه أحمد (٢٣٨٧) وأبو يعلى (٢٥٠٠) والبيهقي (٣٣٩/٧).","grade":"حسن","chapter_ar":"باب عدد الطلاق في عهد النبي ﷺ والخلفاء الراشدين","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (2387), Abu Yaʿla (2500), and al-Bayhaqi (7/339).","chapter_en":"The Number of Divorces During the Time of the Prophet ﷺ and the Rightly Guided Caliphs","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbas said: Rukanah ibn ʿAbd Yazid, the brother of Banu al-Muttalib, divorced his wife three times in one sitting, then became deeply grieved over her. The Messenger of Allah ﷺ asked him, “How did you divorce her?” He said: I divorced her three times. He said, “In one sitting?” He said: Yes. He said, “That counts only as one, so take her back if you wish.” So he took her back. Ibn ʿAbbas held that divorce is to be given at each state of purity."]},"buhuth":{"ar":["وإسناده حسن من أجل محمد بن إسحاق.","واجتماع الطريقين يحدث قوة لموافقتها على لفظ الحديث، بأنه طلّق ثلاثا في مجلس واحد فجعله النبي ﷺ واحدة، وأمره بالمراجعة. ورجّح الحافظ ابن حجر رواية ابن إسحاق وقال: هذا الحديث نص في المسألة لا يقبل التأويل الذي في غيره من الروايات الآتي ذكره.","ثم نقل ابن حجر هذا المذهب عن علي، وابن مسعود، وعبد الرحمن بن عوف، والزبير، ونقله ابن المنذر عن أصحاب ابن عباس كعطاء، وطاوس، وعمرو بن دينار.","اختلاف فتيا ابن عباس:","عن مجاهد قال: كنت عند ابن عباس فجاءه رجل فقال: إنه طلق امرأته ثلاثًا. قال: فسكت حتى ظننت أنه رادّها إليه، ثم قال: ينطلق أحدكم فيركب الحموقة ثم يقول: يا ابن عباس! يا ابن عباس! وإن الله قال: ﴿وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا﴾ [الطلاق: ٢] وإنك لم تتق الله، فلا أجد لك مخرجًا. عصيت ربك، وبانت منك امرأتك. وإن الله قال: ﴿يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ﴾ [الطلاق: ١]. رواه أبو داود (٢١٩٧) وإسناده صحيح.","ومعنى هذا أن في المسألة عنه قولين:","القول الأول: وهو ما رواه جمهور أصحابه أنه أجاز الثلاثة بلفظ الثلاث.","والقول الثاني: عدم وقوع الثلاث كما في رواية عكرمة عنه والجمع بينهما ممكن أنه كان يرى في أول الأمر إمضاء الثلاث ثم تبين له أنه واحدة فرجع إليه كما رجع في الصرف.","الفوائد المهمة:","الطلاق ثلاثة أنواع:","الطلاق الرجعي. وهو الذي يمكنه أن يرتجعها فيه بغير اختيارها، وإذا مات أحدُهما في العدة ورِثه الآخر.","الطلاق البائن: وهو ما يبقى به خاطبا، لا تباح له إلا بعقد جديد.","الطلاق المحرم لها: لا تحل له حتى تنكح زوجا غيره.","الطلاق في طهر واحد بكلمة واحدة أو كلمات:","مثل: أن يقول: أنت طالق ثلاثا.","أو: أنت طالق طالق طالق.","أو: أنت طالق، ثم طالق، ثم طالق.","أو: أنت طالق ثلاثا أو مائة، أو ألفا.","للعلماء فيه قولان:","أحدهما أنه طلاق لازم ثلاثا.","قال به أبو حنيفة ومالك والشافعي وأحمد في رواية عنه، واختارها أكثر أصحابه، وبه قال كثير من السلف من الصحابة والتابعين ومن بعدهم.","والثاني: لا يلزمه إلا طلقة واحدة.","قال به بعض أصحاب أبي حنيفة، ومالك، وأحمد. وهو منقول عن طائفة من السلف والخلف من أصحاب رسول الله ﷺ مثل علي، وابن مسعود، والزبير بن العوام، وعبد الرحمن بن عوف. ذكرها شيخ الإسلام في فتاواه.","والصواب في هذه المسألة أن الأفضل أن يرجع كل إنسان إلى دار الفتوى في بلاده حتى لا يقع في التناقض والحيرة في أمره، والله الهادي إلى سواء السبيل."],"en":["Its chain is Hasan because of Muhammad ibn Ishaq.","The two routes together strengthen the report because they agree that he pronounced three divorces in one sitting, the Prophet ﷺ treated them as one, and ordered him to take her back. Al-Hafiz Ibn Hajar preferred Ibn Ishaq’s narration and said that this hadith is explicit on the issue and does not admit the interpretation applied to other reports.","Ibn Hajar also transmitted this view from ʿAli, Ibn Masʿud, ʿAbd al-Rahman ibn ʿAwf, and al-Zubayr, while Ibn al-Mundhir transmitted it from students of Ibn ʿAbbas such as ʿAta’, Tawus, and ʿAmr ibn Dinar.","The differing verdicts of Ibn ʿAbbas:","Mujahid said: I was with Ibn ʿAbbas when a man came to him and said: He divorced his wife three times. Ibn ʿAbbas remained silent until I thought he would send her back to him, then he said: “One of you goes and behaves foolishly, then says: O Ibn ʿAbbas, O Ibn ʿAbbas! Allah says: ‘And whoever fears Allah, He will make for him a way out’ [al-Talaq: 2], but you did not fear Allah, so I find no way out for you. You disobeyed your Lord, and your wife has become separated from you. And Allah says: ‘O Prophet, when you divorce women, divorce them for their waiting period’ [al-Talaq: 1].” Narrated by Abu Dawud (2197), and its chain is authentic.","The meaning of this is that there are two views reported from him in this issue:","The first view: as narrated by most of his students, that he counted triple divorce uttered as three.","The second view: that the three do not take effect as three, as in the narration from ʿIkrimah from him. It is possible to reconcile the two by saying that at first he held that three were to be enforced as three, then it became clear to him that they count as one, so he returned to that view, just as he changed his opinion in another legal matter.","Important benefits:","Divorce is of three types:","Revocable divorce: in which he may take her back without her choice, and if one of them dies during the waiting period, the other inherits.","Irrevocable divorce: in which he remains only a suitor to her, and she is not lawful for him except through a new marriage contract.","Final prohibiting divorce: after which she is not lawful for him until she marries another husband.","Divorce in one state of purity with one expression or several expressions:","For example: “You are divorced three times.”","Or: “You are divorced, divorced, divorced.”","Or: “You are divorced, then divorced, then divorced.”","Or: “You are divorced three times, or a hundred times, or a thousand times.”","The scholars have two opinions on this:","The first: that it counts as three binding divorces.","This was held by Abu Hanifah, Malik, al-Shafiʿi, and Ahmad in one narration from him, and most of his companions chose it. It was also held by many of the early generations among the Companions, the Followers, and those after them.","The second: that it counts only as one divorce.","This was held by some companions of Abu Hanifah, Malik, and Ahmad. It is also reported from a group among the early and later scholars, including some of the Companions of the Messenger of Allah ﷺ, such as ʿAli, Ibn Masʿud, al-Zubayr ibn al-ʿAwwam, and ʿAbd al-Rahman ibn ʿAwf. Shaykh al-Islam mentioned this in his legal verdicts.","What is correct in this issue is that it is best for every person to refer to the official legal authority in his own country so that he does not fall into contradiction and confusion in his affair. And Allah guides to the straight path."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":2500},{"key":"البیہقی","label":"البيهقي","number":339},{"key":"ahmad","label":"مسند الإمام أحمد","number":2387,"n":2387},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14987,"n":15134}]},{"num":6571,"demo":false,"sanad":"","matn":["عن عائشة قالت: خيّرنا رسول الله ﷺ، فاخترنا الله ورسوله فلم يعد ذلك علينا شيئا."],"takhrij":"متفق عليه: رواه البخاري (٥٢٦٢)، ومسلم (٢٨:١٤٧٧).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخيار","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5262) and Muslim (1477 no. 28).","chapter_en":"What Has Been Related About Choice","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ gave us the choice, and we chose Allah and His Messenger, and he did not count that as anything against us."]},"buhuth":{"ar":["ورواه البخاري أيضاً (٥٢٦٣)، ومسلم (٢٥) من طريق آخر عن مسروق قال: ما أبالي خيّرتُ امرأتي واحدة أو مائة أو ألفا بعد أن تختارني، ولقد سألتُ عائشةَ فقالت: قد خيرنا رسولُ الله ﷺ أفكان طلاقاً؟ أي لم تكن طلاقا."],"en":["Al-Bukhari also narrated it (5263), and Muslim (no. 25), through another route from Masruq, who said: It does not matter to me whether I give my wife the choice once, a hundred times, or a thousand times, so long as she chooses me. I asked ʿA’ishah, and she said: The Messenger of Allah ﷺ gave us the choice — was that divorce? Meaning: it was not divorce."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5262},{"key":"muslim","label":"مسلم","number":28}]},{"num":6572,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله قال: دخل أبو بكر يستأذن على رسول الله ﷺ فوجد الناس جلوساً ببابه، لم يؤذن لأحد منهم، قال: فأذن لأبي بكر. فدخل، ثم أقبل عمر فاستأذن فأذن له، فوجد النبي ﷺ جالسًا حوله نساؤه واجماً ساكتاً قال: لأقولن شيئاً أُضحك النبي ﷺ فقال: يا رسول الله لو رأيت بنت خارجة! سألتني النفقة، فقمت إليها فوجأت عنقها. فضحِكَ رسول الله ﷺ وقال: ((هن حولي كما ترى. يسألنني النفقة) فقام أبو بكر إلى عائشة يجأُ عنقَها، فقام عمر إلى حفصة يجأُ عنقَها. كلاهما يقول: تسألن رسول الله ﷺ ما ليس عنده. فقلن: والله! لا نسأل رسول الله ﷺ شيئا أبدا ليس عنده. ثم اعتزلهن شهراً أو تسعا وعشرين. ثم نزلت عليه هذه الآية: (يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ) حتى بلغ: (لِلْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا) (الأحزاب :٢٩-٢٨) قال: فبدأ بعائشة. فقال: (( يا عائشة! إني أريد أن أعرض عليك أمراً أحب أن لا تعجلي فيه حتى تستشيري أبويك» قالت: وما هو؟ يا رسول الله! فتلا عليها الآية. قالت: أ فيك، يا رسول الله! أستشير أبوي؟ بل أختار الله ورسوله والدار الآخرة. وأسألك أن لا تخبر امرأة من نسائك بالذي قلت. قال: (( لا تسألني امرأة منهن إلا أخبرتها. إن الله لم يبعثني معنِّتًا ولا متعنِّتًا ولكن بعثني معلماً ميسراً)»."],"takhrij":"صحيح: رواه مسلم (١٤٧٨).","grade":"صحيح","chapter_ar":"باب ما جاء في الخيار","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1478).","chapter_en":"What Has Been Related About Choice","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: Abu Bakr came seeking permission to enter upon the Messenger of Allah ﷺ and found people sitting at his door, with none of them having been granted permission. Permission was granted to Abu Bakr, so he entered. Then ʿUmar came and sought permission, and it was granted to him. He found the Prophet ﷺ sitting silently and distressed, with his wives around him. He said: I will say something to make the Prophet ﷺ laugh. So he said: O Messenger of Allah, if only you had seen the daughter of Kharijah! She asked me for spending money, so I got up and struck her neck. The Messenger of Allah ﷺ laughed and said, “They are around me as you see, asking me for spending.” Then Abu Bakr stood up to strike ʿA’ishah on the neck, and ʿUmar stood up to strike Hafsah on the neck, both saying: You ask the Messenger of Allah ﷺ for what he does not have. They said: By Allah, we will never ask the Messenger of Allah ﷺ again for something he does not have. Then he stayed away from them for a month or twenty-nine days. Then this verse was revealed to him: “O Prophet, say to your wives…” until he reached: “…for the women among you who do good is a great reward.” [Surat al-Ahzab: 28–29] He began with ʿA’ishah and said, “O ʿA’ishah, I want to present you with a matter, and I would prefer that you do not hasten in it until you consult your parents.” She said: What is it, O Messenger of Allah? Then he recited the verse to her. She said: About you, O Messenger of Allah, should I consult my parents? Rather, I choose Allah, His Messenger, and the Hereafter. But I ask you not to tell any of your wives what I said. He said, “No woman among them asks me except that I tell her. Allah did not send me to be harsh or difficult, but He sent me as a teacher who makes matters easy.”"]},"buhuth":{"ar":["يستفاد من الحديث: بأن الرجل إذا خيّر امرأته فاختارته فلا شيء، كما دلَّ عليه حديث عائشة. ويفهم منه أنها لو اختارت نفسها أكان ذلك طلاقاً أم لا؟ فالصحيح أن ذلك طلاق. واختلفوا إذا اختارت نفسها فذهب الجمهور إلى أنها واحدة وهو أحق بها. وذهب بعضهم إلى أنها ثلاث. واختلفوا أيضا في مدة الخيار. فالصحيح الذي عليه أكثر أهل العلم أن الخيار إلى أن تقوم في مجلسها، فإذا قامت انتهى الخيار."],"en":["It is understood from this hadith that if a man gives his wife the choice and she chooses him, then nothing results from that, as shown by the hadith of ʿA’ishah. It is also understood from it that if she had chosen herself, would that have counted as divorce or not? The correct view is that it would count as divorce. They differed if she chose herself: the majority said it is one divorce, and he has the best right to take her back. Some said it is three. They also differed regarding the duration of the choice. The correct view, held by most scholars, is that the choice lasts only until she rises from her sitting place; once she rises, the option ends."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1478}]},{"num":6573,"demo":false,"sanad":"","matn":["عن كعب بن مالك قال في حديثه الطويل:","حتى إذا مضت أربعون ليلة من الخمسين، إذا رسولُ رسولِ الله ﷺ يأتيني فقال:","«إِنَّ رَسُولَ اللَّهِ ﷺ يَأْمُرُكَ أَنْ تَعْتَزِلَ امْرَأَتَكَ».","فقلت:","أطلقها أم ماذا أفعل؟","قال:","«لَا، بَلِ اعْتَزِلْهَا وَلَا تَقْرَبْهَا».","وأرسل إلى صاحبي مثل ذلك.","فقلت لامرأتي:","الحقي بأهلك، فتكوني عندهم حتى يقضي الله في هذا الأمر… الحديث."],"takhrij":"متفق عليه: رواه البخاري (٤٤١٨)، ومسلم (٢٧٦٩).","grade":"متفق عليه","chapter_ar":"باب إذا قال: فارقتك، أو سرّحتك، أو الحقي بأهلك، ونحو ذلك فهو طلاق إن نوى به ذلك","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4418) and Muslim (2769).","chapter_en":"If He Says: “I Have Left You,” or “I Have Released You,” or “Go Back to Your Family,” and Similar Expressions, Then It Counts as Divorce If He Intended It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Kaʿb ibn Mālik said in his lengthy hadith:","When forty nights out of the fifty had passed, a messenger of the Messenger of Allah ﷺ came to me and said:","“The Messenger of Allah ﷺ commands you to keep away from your wife.”","I asked:","“Should I divorce her, or what should I do?”","He replied:","“No. Rather, keep away from her and do not approach her.”","The same instruction was sent to my two companions.","So I said to my wife:","“Go to your family and remain with them until Allah decides this matter…” the remainder of the hadith."]},"intro":{"ar":["قال الله تعالى: ﴿وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا﴾ [الأحزاب: ٤٩].","وقال تعالى: ﴿فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ﴾ [البقرة: ٢٢٩].","وقال تعالى: ﴿أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ﴾ [الطلاق: ٢]."],"en":["Allah the Exalted said: “And release them with a gracious release.” [Surat al-Ahzab: 49]","And He said: “Then retain them in a fair manner or release them with excellence.” [Surat al-Baqarah: 229]","And He said: “Or part with them in a fair manner.” [Surat al-Talaq: 2]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4418},{"key":"muslim","label":"مسلم","number":2769}]},{"num":6574,"demo":false,"sanad":"","matn":["عن عائشة: أن ابنة الجون. لما أُدخلت على رسول الله ﷺ ودنا منها قالت: أعوذ بالله منك، فقال لها: (( لقد عُذْتِ بعظيم، الحقي بأهلك»."],"takhrij":"صحيح: رواه البخاري (٥٢٥٤). قولها: “أعوذ بالله منك” يدل على خفّة عقل المرأة.","grade":"صحيح","chapter_ar":"باب إذا قال: فارقتك، أو سرّحتك، أو الحقي بأهلك، ونحو ذلك فهو طلاق إن نوى به ذلك","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5254).","chapter_en":"If He Says: “I Have Left You,” or “I Have Released You,” or “Go Back to Your Family,” and Similar Expressions, Then It Counts as Divorce If He Intended It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah narrated that when the daughter of al-Jawn was brought to the Messenger of Allah ﷺ and he approached her, she said: I seek refuge in Allah from you. So he said to her, “You have sought refuge with the Greatest. Go back to your family.”"]},"buhuth":{"en":["Her saying, “I seek refuge in Allah from you,” indicates the woman’s lack of sound judgment."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5254}]},{"num":6575,"demo":false,"sanad":"","matn":["عن سهل بن سعد قال: ذكر للنبي ﷺ امرأة من العرب، فأمر أبا أسيد الساعدي أن يرسل إليها، فأرسل إليها، فقدمت، فنزلت في أجم بني ساعدة، فخرج النبي ﷺ حتى جاءها، فدخل عليها، فإذا امرأة منكسة رأسها، فلما كلمها النبي ﷺ قالت: أعوذ بالله منك، فقال: (( قد أعذتك مني )). فقالوا لها: أتدرين من هذا؟ قالت: لا. قالوا: هذا رسول الله ﷺ جاءك ليخطبك. قالت: أنا كنت أشقى من ذلك. قال سهل: فأقبل النبي ﷺ يومئذ حتى جلس في سقيفة بني ساعدة هو وأصحابه، ثم قال: (( اسقنا يا سهل )). قال: فأخرجت لهم هذا القدح فأسقيتهم فيه. قال أبو حازم: فأخرج لنا سهل ذلك القدح فشربنا فيه. قال: ثم استوهبه بعد ذلك عمر بن عبد العزيز، فوهبه له."],"takhrij":"متفق عليه: رواه البخاري (٥٦٣٧)، ومسلم (٢٠٠٧).","grade":"متفق عليه","chapter_ar":"باب إذا قال: فارقتك، أو سرّحتك، أو الحقي بأهلك، ونحو ذلك فهو طلاق إن نوى به ذلك","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5637) and Muslim (2007).","chapter_en":"If He Says: “I Have Left You,” or “I Have Released You,” or “Go Back to Your Family,” and Similar Expressions, Then It Counts as Divorce If He Intended It","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Sahl ibn Saʿd said: A woman from among the Arabs was mentioned to the Messenger of Allah ﷺ, so he ordered Abu Usayd to send for her. He sent for her, and she came and stayed in the enclosure of Banu Saʿidah. The Messenger of Allah ﷺ went out until he came to her.","He entered upon her and found a woman with her head lowered. When the Messenger of Allah ﷺ spoke to her, she said: “I seek refuge in Allah from you.” He said: “You have been granted refuge from me.” They said to her: “Do you know who this is?” She said: “No.” They said: “This is the Messenger of Allah ﷺ. He came to propose marriage to you.” She said: “I am more wretched than that.”","Sahl said: So the Messenger of Allah ﷺ came that day and sat in the shelter of Banu Saʿidah with his companions. Then he said to Sahl: “Give us something to drink.” He said: So I brought out for them this cup and gave them drink in it.","Abu Hazim said: Sahl brought out that cup for us and we drank from it. Then later ʿUmar ibn ʿAbd al-ʿAziz asked him to gift it to him, and he gave it to him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5637},{"key":"muslim","label":"مسلم","number":2007}]},{"num":6576,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس قال: إذا حرّم امرأته ليس بشيء وقال: (لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ) [الأحزاب: ٢١]."],"takhrij":"صحيح: رواه البخاري (٥٢٦٦)، ومسلم (١٩:١٤٧٣). واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب من قال لامرأته : أنت علي حرام ولم ينو الطلاق","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5266) and Muslim (1473 no. 19). This is the wording of al-Bukhari.","chapter_en":"Whoever Says to His Wife, “You Are Forbidden to Me,” Without Intending Divorce","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAbbas said: If a man declares his wife forbidden to himself, it is nothing. And he recited: “Indeed, in the Messenger of Allah you have an excellent example.” [Surat al-Ahzab: 21]"]},"buhuth":{"ar":["ولفظ مسلم: “إذا حرّم الرّجل عليه امرأته فهي يمين يكفّرها”"],"en":["In the wording of Muslim: “If a man makes his wife forbidden to himself, then it is an oath for which he must offer expiation.”"]},"intro":{"ar":["قال للّه تمالى: (ويَا  لَ  الَ لَهَلَ تِي يَات أروَيِكَ وَلّه عُوْ تَعِر ) (العرم :١)"],"en":["Allah the Exalted said: “O Prophet, why do you forbid what Allah has made lawful for you, seeking the pleasure of your wives?” [Surat al-Tahrim: 1]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5266},{"key":"muslim","label":"مسلم","number":19}]},{"num":6577,"demo":false,"sanad":"","matn":["عن عائشة: أن رجلاً طلّق امرأته ثلاثاً، فتزوجتْ فطلّق، فسئل النبي ﷺ أن تحل للأول؟ قال: لا حتى يذوق عسيلتها كما ذاق الأول."],"takhrij":"متفق عليه: رواه البخاري (٥٢٦١)، ومسلم (١١٥ :١٤٣٣).","grade":"متفق عليه","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5261) and Muslim (1433 no. 115).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿA’ishah narrated that a man divorced his wife three times, then she married another man and he divorced her. The Prophet ﷺ was asked whether she would become lawful for the first husband. He said: “No, not until he tastes her sweetness just as the first one tasted it.”"]},"buhuth":{"ar":["عموم خطاب قوله تعالى: (فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنَكِحَ زَوْجًا غَيْرَهُ ) [البقرة: ٢٣٠] أباح للٰه عز وجل للزوج الأول أن يتزوج بها بعد أن تزوجها زوج آخر. وفسرته السنة أنها لا تحل للزوج الأول حتى بكون بينها وبين الزوج الثاني وطء بذواق العُسيلة، ثم تبين عنه بطلاق أو وفاة. ثم تحل حينئذ للزوج الأول."],"en":["The general meaning of Allah’s statement, “If he divorces her, then she is not lawful for him afterward until she marries another husband” [al-Baqarah: 230], allows the first husband to marry her again after she has married another husband. The Sunnah explained that she does not become lawful for the first husband until intercourse takes place between her and the second husband, expressed as tasting the sweetness, and then she is separated from him by divorce or death. Then she becomes lawful for the first husband."]},"intro":{"ar":["قال الله تعالى: ﴿فَإِنْ طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ﴾ [البقرة: ٢٣٠]."],"en":["Allah the Exalted said: “If he divorces her, then she is not lawful for him afterward until she marries another husband.” [Surat al-Baqarah: 230]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5261},{"key":"muslim","label":"مسلم","number":115}]},{"num":6578,"demo":false,"sanad":"","matn":["عن عائشة قالت: جاءت امرأة رفاعة القرظي النبي ﷺ فقالت: كنتُ عند رفاعة طلقني، فأبتّ طلاقي، فتزوجت عبد الرحمن بن الزبير، إنما معه مثل هُدبة الثوب فقال: (( أتريدين أن ترجعي إلى رفاعة، لا، حتى تذوقي عسيلته ويذوق عسيلتك))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٣٩) ومسلم (١٤٣٣).","grade":"متفق عليه","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2639) and Muslim (1433).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿA’ishah said: The wife of Rifaʿah al-Qurazi came to the Prophet ﷺ and said: “I was married to Rifaʿah and he divorced me irrevocably. Then I married ʿAbd al-Rahman ibn al-Zubayr, but he has nothing more than something like the fringe of a garment.” So he said: “Do you want to return to Rifaʿah? No, not until you taste his sweetness and he tastes your sweetness.”"]},"buhuth":{"ar":["وفي رواية: والله ما معه إلا مثل الهدبة، وأخذت بهدبة من جلبابها. قال: فتبسم رسول الله ﷺ ضاحكا."],"en":["In another narration: “By Allah, he has nothing except like the fringe,” and she took hold of a fringe of her garment. The Messenger of Allah ﷺ smiled and laughed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2639},{"key":"muslim","label":"مسلم","number":1433}]},{"num":6579,"demo":false,"sanad":"","matn":["عن عكرمة أن رفاعة طلّق امرأته، فتزوّجها عبد الرحمن بن الزبير القرظي. قالت عائشة: وعليها خمار أخضر، فشكت إليها وأرتها خضرة بجلدها. فلما جاء رسول الله ﷺ - والنساء ينصر بعضهن بعضًا - قالت عائشة: ما رأيت مثل ما يلقى المؤمنات، لجلدها أشد خضرة من ثوبها. قال: وسمع أنها قد أتت رسول الله ﷺ، فجاء ومعه ابنان له من غيرها. قالت: والله ما لي إليه من ذنب، إلا أن ما معه ليس بأغنى عني من هذه - وأخذت هدبة من ثوبها. فقال: كذبت والله يا رسول الله، إني لأنفضها نفض الأديم، ولكنها ناشز تريد رفاعة. فقال رسول الله ﷺ: «فإن كان ذلك لم تحلي له، أو لم تصلحي له، حتى يذوق من عسيلتك». قال: وأبصر معه ابنين له، فقال: «بنوك هؤلاء؟» قال: نعم. قال: «هذا الذي تزعمين ما تزعمين؟ فوالله لهم أشبه به من الغراب بالغراب»."],"takhrij":"صحيح: رواه البخاري (٥٨٢٥).","grade":"صحيح","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5825).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿIkrimah narrated that Rifaʿah divorced his wife, and then ʿAbd al-Rahman ibn al-Zubayr al-Qurazi married her. ʿA’ishah said: She was wearing a green veil, and she complained to her and showed her green marks on her skin. When the Messenger of Allah ﷺ came — and women support one another — ʿA’ishah said: I have never seen anything like what believing women suffer; her skin was greener than her garment.","He heard that she had come to the Messenger of Allah ﷺ, so he came with two sons of his from another wife. She said: By Allah, I have no complaint against him except that what he has is no more useful to me than this — and she took hold of a fringe of her garment. He said: She is lying, by Allah, O Messenger of Allah. I truly shake her like leather is shaken, but she is disobedient and wants Rifaʿah. So the Messenger of Allah ﷺ said: “If that is the case, then you are not lawful for him — or: you are not fit for him — until he tastes your sweetness.” Then he saw two sons with him and said: “Are these your sons?” He said: Yes. He said: “Yet this is what she claims? By Allah, they resemble him more than one crow resembles another crow.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5825}]},{"num":6580,"demo":false,"sanad":"","matn":["عن الزبير بن عبد الرحمن بن الزَّبِيرِ، عن أبيه، أن رفاعة بن سموال طلق امرأته تميمة بنت وهب على عهد رسول الله ﷺ فنكحَها عبد الرحمن بن الزبير، فاعترض عنها، فلم يستطع أن يُصيبها، فطلّقها ولم يمسّها. فأراد رفاعة أن ينكحها، وهو زوجها الذي كان طلّقها قبل عبد الرحمن، فذكر ذلك لرسول الله ﷺ فنهاه عن تزويجها فقال: (( لا تحلّ لك حتى تذوقَ العسيلةَ))."],"takhrij":"حسن: رواه ابن الجارود في المنتقى (٦٨٢).","grade":"حسن","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Jarud in al-Muntaqa (682).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Al-Zubayr ibn ʿAbd al-Rahman ibn al-Zubayr narrated from his father that Rifaʿah ibn Samwal divorced his wife Tamimah bint Wahb during the time of the Messenger of Allah ﷺ. Then ʿAbd al-Rahman ibn al-Zubayr married her, but he turned away from her and was unable to have intercourse with her. Then he divorced her without touching her. Rifaʿah wanted to marry her again, and he was the husband who had divorced her before ʿAbd al-Rahman. This was mentioned to the Messenger of Allah ﷺ, and he forbade him from marrying her, saying: “She is not lawful for you until you taste the sweetness.”"]},"buhuth":{"ar":["وبعد جمع هذه الروايات يخلص منها ما يأتي:","إن المرأة لم تُمكِّنه من الجماع أو عُرض له عارض من المرض وغيره.","إن الرجل لم يكن بعنين، إذ لو ثبتت عنته عند النبي ﷺ لما أمرها بتذويق العسيلة كل منهما للآخر.","وقول المرأة كما في الصحيحين - البخاري (٥٢٦٥) ومسلم (١١٤:١٤٣٣) “ولم يقربني إلا هنة واحدة” كما في لفظ البخاري، ولم يذكره مسلم. وفي رواية عند أحمد (٢٥٩٢٠) “إلا هبة واحدة” والهبة هي هبات الفحل، وسفاده ومعناه أنه أتاها وقعة واحدة كما فسّره الخطابي في غريب الحديث (٥٤٦/١)","وظاهر المرفوع يعارض هذا، لأن النبي ﷺ قال: (( حتى تذوقي عسيلته، وتذوق عسيلتك)) فإن الرجل","لو تمكّنَ من الوطء ولو مرة واحدة لما أمرها النبي ﷺ بهذا الأمر. بل أجاز طلاقها.","فالمعنى الصحيح والله تعالى أعلم أن هذه الهبة الواحدة لم يحصل منها العسيلة المعروفة التي تكفي الطلاق، والرجوع إلى الزوج الأول، فكأن الرجل حاول الجماع، ولكن حصل له فتور مؤقت، فأمرها النبي ﷺ بالصبر حتى يذوق عسيلتها، وتذوق عسيلته.","ونُفيَ عنه العنَّةُ. لوجود بيّنة بقوله: (( هذا الذي تزعمين ما تزعمين، فوالله لهم أشبه به من الغراب بالغراب ))","والعسيلة: تصغير العسل والمراد منه حلاوة الجماع، فلعل الرجل كان أنزل قبل تمام الإيلاج، فلم يذق عسيلة صاحبته، كما لم تذق عسيلة صاحبها.","والعمل على هذا الحديث عند عامة أهل العلم من أصحاب النبي ﷺ وغيرهم، بأن وطء الزوج الثاني لا يكون محللاً لارتجاع الزوج الأول للمرأة إلا إذا كان حال وطئه منتشراً. فلو لم يكن كذلك، أو كان عنِّينا، أو طفلا لم يكف في أصح قولي أهل العلم.","وقوله: (( حتى تذوقي عسيلته… )) كناية عن الجماع، وهو تغييب حشفة الرجل في فرج المرأة. سواء أنزل أو لم ينزل. فإن التذوق يحصل بمجرد الإدخال، وإن كان كماله لا يكون إلا بالإنزال.","وفي قوله: (( حتى تذوقي عسيلته، ويذوق عسيلتك )) إشارة إلى استوائهما في إدراك لذّة الجماع، ولذا قال بعض العلماء: لو وطئها وهي نائمة، أو مغمى عليها لم تحلّ للأول، لأنها لم تذُق العُسيلة إذ لم تُدركها.","وهذه الأحاديث تُخصّص عموم قوله تعالى: حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ، فإنّ مجرّد عقد النكاح يطلق عليه حتى تنكح زوجا غيره، ولم يقل بهذا أحدٌ من العلماء إلا سعيد بن المسيب فإنه قال: مجرد عقد النكاح يحل أن ترجع إلى الزوج الأول، والجمهور على أنه لا بد من حصول لذة الجماع سواء أنزل أو لم ينزل إلا الحسن البصري، فإنه اشترط الإنزال.","وقوله: هدبة الثوب: هو طرف الثوب وهو كناية عن أن ذكر الرجل يشبه الهدبة في الاسترخاء، وعدم الانتشار."],"en":["After gathering these narrations, the following conclusions are drawn:","The woman did not enable him to have intercourse, or something prevented him from it, such as illness or something similar.","The man was not impotent, because if his impotence had been established before the Prophet ﷺ, he would not have instructed that each of them must taste the other’s sweetness.","As for the woman’s statement in the Two Sahihs — al-Bukhari (5265) and Muslim (1433 no. 114) — “He did not approach me except once,” this is in the wording of al-Bukhari and not mentioned by Muslim. In a narration with Ahmad (25920): “except one leap,” and “leap” refers to the mounting of the male and his attempt at intercourse. Its meaning is that he approached her one time, as explained by al-Khattabi in Gharib al-Hadith (1/546).","The apparent wording of the prophetic report seems to oppose this, because the Prophet ﷺ said: “until you taste his sweetness and he tastes your sweetness.” If the man had actually managed intercourse even once, the Prophet ﷺ would not have given this instruction, but would have allowed her to return after his divorce.","So the correct meaning — and Allah knows best — is that this one attempt did not produce the known “sweetness” that is sufficient for the divorce to count as making her lawful again for the first husband. It is as though the man attempted intercourse, but a temporary weakness occurred, so the Prophet ﷺ instructed her to wait until he tastes her sweetness and she tastes his.","And impotence was negated from him, due to the proof in the Prophet’s saying: “This one about whom you claim what you claim — by Allah, they resemble him more than one crow resembles another.”","“ʿUsaylah” is the diminutive of honey, and what is meant is the sweetness of intercourse. It may be that the man ejaculated before full penetration, so he did not taste the sweetness of his wife, just as she did not taste his sweetness.","The scholars among the Companions of the Prophet ﷺ and others acted upon this hadith, that the intercourse of the second husband does not make the woman lawful for the first husband unless it takes place with full arousal. If it is not so, or if the husband is impotent, or is a child, then it is not sufficient according to the sounder of the two scholarly opinions.","His saying, “until you taste his sweetness…” is a figurative expression for intercourse, which means the entry of the tip of the man’s organ into the woman’s private part, whether ejaculation occurs or not. The “tasting” is achieved by mere penetration, even though its completion is only with ejaculation.","And in his saying, “until you taste his sweetness and he tastes your sweetness,” there is an indication that both spouses share in experiencing the pleasure of intercourse. For this reason, some scholars said that if he had intercourse with her while she was asleep or unconscious, she would not become lawful for the first husband, because she did not taste the sweetness since she did not perceive it.","These hadiths specify the general wording of Allah’s statement, “until she marries another husband.” A mere marriage contract can be described as marriage, yet no scholar held that the mere contract makes her lawful to return to the first husband except Saʿid ibn al-Musayyib, who held that the contract alone permits her return to the first husband. The majority held that the pleasure of intercourse must occur, whether ejaculation takes place or not; al-Hasan al-Basri alone stipulated ejaculation.","And the phrase “the fringe of a garment” means the edge of a garment, and it is a figurative expression meaning that the man’s organ was like a limp fringe, without firmness or arousal."]}},"tuhfa":{},"refs":[{"key":"ابن_الجارود/المنتقی","label":"ابن الجارود في المنتقى","number":682}]},{"num":6581,"demo":false,"sanad":"","matn":["عن عبيد الله بن عباس قال: جاءت الغُميصاء -أو الرميصاء - إلى رسول الله ﷺ تشكو زوجها، وتزعم أنه لا يصل إليها. فما كان إلا يسيراً حتى جاء زوجها. فزعم أنها كاذبة. ولكنها تريد أن ترجع إلى زوجها الأول. فقال رسول الله ﷺ (( ليس لك ذلك، حتى يذوق عسيلتك رجل غيره»."],"takhrij":"صحيح: رواه النسائي (٣٤١٣) وأحمد (١٨٣٧) واللفظ لأحمد.","grade":"صحيح","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3413) and Ahmad (1837), and this is the wording of Ahmad.","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿUbayd Allah ibn ʿAbbas said: Al-Ghumaysa’ — or al-Rumaysa’ — came to the Messenger of Allah ﷺ complaining about her husband, claiming that he could not reach her. It was only a short while before her husband came and claimed that she was lying, but that she wanted to return to her first husband. So the Messenger of Allah ﷺ said: “That is not possible for you until another man tastes your sweetness.”"]},"buhuth":{"ar":["وفي لفظ النسائي: (( لا حتى يذوق عسيلتها كما ذاق الأول)) وإسناده صحيح."],"en":["In the wording of al-Nasa’i: “No, not until another man tastes her sweetness as the first did,” and its chain is authentic."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3413},{"key":"ahmad","label":"مسند الإمام أحمد","number":1837,"n":1837}]},{"num":6582,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر سئل رسول الله ﷺ عن رجل طلّق امرأته البتة - يعني ثلاثا - فتزوجتْ رجلاً، فطلقها قبل أن يدخل بها، أترجع إلى الأول؟ فقال: (( لا حتى يذوق من عُسيلتها ما ذاق صاحبه )."],"takhrij":"صحيح: رواه أبو يعلى (٤٠٦٦).","grade":"صحيح","chapter_ar":"باب لا تحل المبتوتة حتى تنكح زوجا غيره","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Yaʿla (4066).","chapter_en":"The Woman Irrevocably Divorced Does Not Become Lawful Until She Marries Another Husband","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["ʿAbd Allah ibn ʿUmar narrated that the Messenger of Allah ﷺ was asked about a man who divorced his wife completely — meaning three times — then she married another man, and he divorced her before consummating the marriage. Would she return to the first husband? He said: “No, not until he tastes from her sweetness what the first husband tasted.”"]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":4066},{"key":"sh12520","label":"مسند أبي يعلى","number":4964,"n":4969}]},{"num":6583,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول الله ﷺ ردَّ ابنته على أبي العاص بن الربيع بعد سنتين بنكاحها الأول.","وفي رواية: بعد ست سنين."],"takhrij":"حسن: رواه أبو داود (٢٢٤٠) والترمذي (١١٤٣،١١٤٤) وابن ماجه (٢٠٠٩) وأحمد (١٨٧٦).","grade":"حسن","chapter_ar":"باب إذا أسلم أحد الزوجين وتأخر الآخر","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2240), al-Tirmidhi (1143, 1144), Ibn Majah (2009), and Ahmad (1876).","chapter_en":"If One of the Spouses Accepts Islam and the Other Delays","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿAbbas narrated that the Messenger of Allah ﷺ returned his daughter to Abu al-ʿAs ibn al-Rabiʿ after two years with her first marriage contract.","In another narration: after six years."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2240},{"key":"tirmidhi","label":"الترمذي","number":1143},{"key":"ibnmajah","label":"ابن ماجه","number":2009},{"key":"ahmad","label":"مسند الإمام أحمد","number":1876,"n":1876}]},{"num":6584,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس، أن امرأة جاءت إلى النبي ﷺ فأسلمت، فتزوجها رجل، قال:","فجاء زوجها الأول فقال: يا رسول الله! إني كنت أسلمت معها، وعلمتْ بإسلامي، قال: فانتزعها رسول الله ﷺ من زوجها الآخر، وردّها إلى زوجها الأول."],"takhrij":"حسن: رواه أبو داود (٢٢٣٨،٢٢٣٩) والترمذي (١١٤٤) وصحّحه، وابن ماجه (٢٠٠٨) وابن","grade":"حسن","chapter_ar":"باب إذا أسلم أحد الزوجين وتأخر الآخر","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2238, 2239), al-Tirmidhi (1144), who authenticated it, Ibn Majah (2008), and Ibn Hibban (4159).","chapter_en":"If One of the Spouses Accepts Islam and the Other Delays","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAbbas narrated that a woman came to the Prophet ﷺ and accepted Islam, then another man married her. Her first husband came and said: “O Messenger of Allah, I had accepted Islam with her, and she knew of my Islam.” So the Messenger of Allah ﷺ took her away from the second husband and returned her to the first husband."]},"buhuth":{"ar":["حبان (٤١٥٩).","قال الحافظ ابن القيم في “زاده” (١٣٧/٥): “ولا نعلم أحدا جدَّدَ للإسلام نكاحه ألبتة، بل كان الواقع أحد أمرين: إما افتراقهما، ونكاحها غيره، وإما بقاؤها عليه، وإن تأخر إسلامها أو إسلامه” انظر للمزيد “المنة الكبرى” (١٨٠/٦)."],"en":["Al-Hafiz Ibn al-Qayyim said in Zad al-Maʿad (5/137): “We do not know of anyone who renewed a marriage because of Islam at all. Rather, what actually occurred was one of two things: either they separated and she married someone else, or she remained with him even if her Islam or his Islam came later.” For more, see al-Minnah al-Kubra (6/180)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2238},{"key":"tirmidhi","label":"الترمذي","number":1144},{"key":"ibnmajah","label":"ابن ماجه","number":2008}]},{"num":6585,"demo":false,"sanad":"","matn":["عن رافع بن سنان أنه أسلم، وأبت امرأته أن تسلم، فأتت النبي ﷺ فقالت: ابنتي وهي فطيم، أو شبهه، وقال رافع: ابنتي. فقال له النبي ﷺ: (( اقعد ناحية)) وقال لها: (( اقعدي ناحية) وأقعد الصبية بينهما، ثم قال: (( ادعواها)) فمالت الصبية إلى أمها. فقال النبي ﷺ: (( اللهم اهدها))","فمالت إلى أبيها فأخذها."],"takhrij":"صحيح: رواه أبو داود (٢٢٤٤) وأحمد (٢٣٧٥٧) والحاكم (٢٠٦/٢) والبيهقي (٣/٨).","grade":"صحيح","chapter_ar":"باب إذا أسلم أحد الأبوين مع من يكون الولد","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2244), Ahmad (23757), al-Hakim (2/206), and al-Bayhaqi (8/3).","chapter_en":"If One of the Parents Accepts Islam, With Whom Does the Child Remain","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["Rafiʿ ibn Sinan accepted Islam, but his wife refused to accept Islam. She came to the Prophet ﷺ and said: “My daughter — and she is newly weaned,” or something similar. Rafiʿ said: “My daughter.” The Prophet ﷺ said to him: “Sit to one side,” and to her: “Sit to one side,” and he seated the young girl between them. Then he said: “Call her.” The child inclined toward her mother. So the Prophet ﷺ said: “O Allah, guide her.” Then she inclined toward her father, and he took her."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2244},{"key":"البیہقی","label":"البيهقي","number":3},{"key":"ahmad","label":"مسند الإمام أحمد","number":23757,"n":23757},{"key":"hakim","label":"المستدرك على الصحيحين","number":2828,"n":2814},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15760,"n":15918}]},{"num":6586,"demo":false,"sanad":"","matn":["عن أبي ميمونة سُلمى - مولى من أهل المدينة، رجل صدق- قال: بينما أنا جالس مع أبي هريرة، جاءته امرأة فارسية معها ابن لها فادعياه. وقد طلقها زوجها فقالت: يا أبا هريرة - ورطنتْ له بالفارسية - زوجي يريد أن يذهب بابني؟ فقال أبو هريرة: استهما عليه. ورطن لها بذلك.","فجاء زوجها فقال: من يُحَاقني في ولدي؟ فقال أبو هريرة: اللهم إنى لا أقول هذا إلا أني سمعت امرأة جاءت إلى رسول الله ﷺ وأنا قاعد عنده- فقالت: يا رسول الله! إن زوجي يريد أن يذهب بابني، وقد سقاني من بئر أبي عنبة، وقد نفعني. فقال رسول الله ﷺ: (( استهما عليه» فقال زوجها: من يُحَاقَني في ولدي؟ فقال النبي ﷺ: (( هذا أبوك، وهذه أمك، فخذ بيد أيها شئت )) فأخذ بيد أمه فانطلقت به."],"takhrij":"صحيح: رواه أبو داود (٢٢٧٧) والنسائي (٣٤٩٦) وصحّحه الحاكم (٩٧/٤). قال الترمذي:","grade":"صحيح","chapter_ar":"باب تخيير الصبي بين أبويه الذين اقترقا","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2277), al-Nasa’i (3496), and authenticated by al-Hakim (4/97). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"Giving a Child the Choice Between His Separated Parents","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abu Maymunah Sulma — a client from the people of Madinah and a truthful man — said: While I was sitting with Abu Hurayrah, a Persian woman came with a son of hers, and both parents claimed him. Her husband had divorced her, and she said, speaking in Persian: “My husband wants to take my son.” Abu Hurayrah said: “Draw lots over him,” and he said that to her in Persian.","Then her husband came and said: “Who will dispute with me about my child?” Abu Hurayrah said: O Allah, I only say this because I heard a woman come to the Messenger of Allah ﷺ while I was sitting with him, and she said: “O Messenger of Allah, my husband wants to take my son, though he has given me water from the well of Abu ʿInabah and benefited me.” The Messenger of Allah ﷺ said: “Draw lots over him.” Her husband said: “Who will dispute with me about my child?” So the Prophet ﷺ said: “This is your father, and this is your mother, so take the hand of whichever of them you wish.” So he took his mother’s hand, and she left with him."]},"buhuth":{"ar":["“حسن صحيح”."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2277},{"key":"nasai","label":"النسائي","number":3496},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":97}]},{"num":6587,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص أن امرأة قالت: يا رسول الله! إن ابني هذا كان","بطني له وعاءً، وثديي له سقاءً، وحجري له حواءً، وإن أباه طلّقني، وأراد أن ينتزعه مني! فقال لها","رسول الله ﷺ : (( أنت أحق به ما لم تنكحي))."],"takhrij":"حسن: رواه أبو داود (٢٢٧٦) وأحمد (٦٧٠٧) والدار قطني (٣٠٥/٣) والحاكم (٢٠٧ /٢) وعن البيهقي (٥-٤/٨) كلهم من طرق عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب حضانة الأم المطلقة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2276), Ahmad (6707), al-Daraqutni (3/305), al-Hakim (2/207), and al-Bayhaqi (8/4–5), all through routes from ʿAmr ibn Shuʿayb, from his father, from his grandfather.","chapter_en":"The Custody of the Divorced Mother","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿAbd Allah ibn ʿAmr ibn al-ʿAs narrated that a woman said: “O Messenger of Allah, this son of mine — my womb was a vessel for him, my breasts were a drink for him, and my lap was a shelter for him. But now his father has divorced me and wants to take him away from me.” So the Messenger of Allah ﷺ said: “You have more right to him so long as you do not marry.”"]},"buhuth":{"ar":["لا خلاف بين أهل العلم أن الأم لها حضانة الطفل ما لم تتزوج، فإذا تزوجت فلا حق لها في حضانته.","فإن كانت لها أم فأمها تقوم مقامها، ثم الجدات من قبل الأم أحق به ما بقيت منهن واحدة."],"en":["There is no disagreement among the scholars that the mother has custody of the child so long as she does not marry. If she marries, then she no longer has the right of custody.","If her mother is present, then her mother takes her place, and then the maternal grandmothers have more right to him, so long as even one of them remains."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2276},{"key":"الدار_قطنی","label":"الدار قطني","number":305},{"key":"وعن_البیہقی","label":"وعن البيهقي","number":5},{"key":"ahmad","label":"مسند الإمام أحمد","number":6707,"n":6707},{"key":"hakim","label":"المستدرك على الصحيحين","number":2830,"n":2816},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15763,"n":15921}]},{"num":6588,"demo":false,"sanad":"","matn":["عن البراء قال:","اعتمر النبي ﷺ في ذي القعدة… الحديث، وفيه قصة ابنة حمزة، وأنها تبعتهم حين الخروج من مكة.","فتناولها علي، فأخذ بيدها، وقال لفاطمة:","دونك ابنة عمك، احمليها.","فاختصم فيها علي وزيد وجعفر.","فقال علي:","أنا أحق بها، وهي ابنة عمي.","وقال جعفر:","ابنة عمي، وخالتها تحتي.","وقال زيد:","ابنة أخي.","فقضى بها النبي ﷺ لخالتها، وقال:","«الْخَالَةُ بِمَنْزِلَةِ الْأُمِّ».","وقال لعلي:","«أَنْتَ مِنِّي وَأَنَا مِنْكَ».","وقال لجعفر:","«أَشْبَهْتَ خَلْقِي وَخُلُقِي».","وقال لزيد:","«أَنْتَ أَخُونَا وَمَوْلَانَا»."],"takhrij":"صحيح: رواه البخاري (٢٦٩٩).","grade":"صحيح","chapter_ar":"باب ما جاء في حضانة الخالة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2699).","chapter_en":"What Has Been Reported Regarding the Maternal Aunt Having Custody","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Al-Barāʾ reported:","The Prophet ﷺ performed ʿUmrah in Dhū al-Qaʿdah… the hadith includes the story of Ḥamzah’s daughter, who followed them as they were leaving Makkah.","ʿAlī took hold of her hand and said to Fāṭimah:","“Here is your cousin; take her.”","Then ʿAlī, Zayd, and Jaʿfar disputed over who should have custody of her.","ʿAlī said:","“I have the greatest right to her, for she is my paternal uncle’s daughter.”","Jaʿfar said:","“She is my paternal uncle’s daughter, and her maternal aunt is my wife.”","Zayd said:","“She is my brother’s daughter.”","The Prophet ﷺ awarded her custody to her maternal aunt and said:","“The maternal aunt is in the position of the mother.”","He said to ʿAlī:","“You are from me and I am from you.”","He said to Jaʿfar:","“You resemble me in appearance and character.”","And he said to Zayd:","“You are our brother and our freedman.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2699}]},{"num":6589,"demo":false,"sanad":"","matn":["عن علي قال: لما خرجنا من مكة اتبعتُنا ابنة حمزة تنادي: يا عمّ يا عمّ قال: فتناولتها بيدها، فدفعتها إلى فاطمة، فقلت: دونك ابنة عمك. قال: فلما قدمنا المدينة اختصمنا فيها أنا وجعفر وزيد بن حارثة. فقال جعفر: ابنة عمي، وخالتها عندي، يعني أسماء بنت عميس، وقال زيد: ابنة أخي، وقلت: أنا أخذتها وهي ابنة عمي. فقال رسول الله ﷺ: (( أما أنت يا جعفر فأشبهت خلقي وخلقي، وأما أنت يا علي فمني وأنا منك، وأما أنت يا زيد فأخونا ومولانا. والجارية عند خالتها، فإن الخالة والدة) قلت: يارسول الله! ألا تتزوجها؟ قال: (( إنها ابنة أخي من الرضاعة))."],"takhrij":"حسن: رواه أبو داود (٢٢٨٠) وأحمد (٧٧٠)، وصحّحه الحاكم (١٢٠/٣).","grade":"حسن","chapter_ar":"باب ما جاء في حضانة الخالة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2280) and Ahmad (770), and authenticated by al-Hakim (3/120).","chapter_en":"What Has Been Reported Regarding the Maternal Aunt Having Custody","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿAli said: When we left Makkah, Hamzah’s daughter followed us calling, “O uncle, O uncle.” He said: So I took her by the hand and handed her to Fatimah, saying: “Take your cousin.” When we arrived in Madinah, Jaʿfar, Zayd ibn Harithah, and I disputed over her. Jaʿfar said: “She is my uncle’s daughter, and her maternal aunt is with me,” meaning Asma’ bint ʿUmays. Zayd said: “She is my brother’s daughter.” And I said: “I took her, and she is my uncle’s daughter.” So the Messenger of Allah ﷺ said: “As for you, Jaʿfar, you resemble me in appearance and character. As for you, ʿAli, you are from me and I am from you. As for you, Zayd, you are our brother and our freedman. The girl is with her maternal aunt, for the maternal aunt is like a mother.” I said: “O Messenger of Allah, will you not marry her?” He said: “She is the daughter of my brother through breastfeeding.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2280},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":120},{"key":"ahmad","label":"مسند الإمام أحمد","number":770,"n":770}]},{"num":6590,"demo":false,"sanad":"","matn":["عن ابن عباس قال في هذه الآية: (يَاأَيُّهَا الَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمْ أَن تَرِثُوا النِّسَآءَ كَرْهَا وَلَا تَعْضُلُوهُنَّ) [النساء: ١٩] كانوا إذا مات الرجل كان أولياؤه أحقّ بامرأته. إن شاء بعضهم تزوّجها، وإن شاؤوا زوّجوها، وإن شاؤوا لم يُزوّجوها، فهم أحق بها من أهلها. فنزلت هذه الآية بذلك."],"takhrij":"صحيح: رواه البخاري (٦٩٤٨).","grade":"صحيح","chapter_ar":"باب قوله تعالى: ( لَا يَحِلَّ لَكُمْ أَن تَرِنُواْ النِّسَآءَ كَرَهَا وَلَا تَتْضُلُوهُنَّ (التساء: ١٩)","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (6948).","chapter_en":"The Saying of Allah the Exalted: “It is not lawful for you to inherit women by compulsion, nor should you prevent them” [al-Nisa’: 19]","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Ibn ʿAbbas said regarding this verse, “O you who believe, it is not lawful for you to inherit women by compulsion, nor should you prevent them” [al-Nisa’: 19]: When a man died, his heirs had more right to his wife. If one of them wished, he married her. If they wished, they married her off. If they wished, they did not marry her off at all. They had more right to her than her own family, so this verse was revealed concerning that."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6948}]},{"num":6591,"demo":false,"sanad":"","matn":["عن معقل بن يسار قال: كانت أخته تحت رجل فطلقها ثم خلّى عنها حتى انقضت عدتها، ثم خطبها، فحمى معقل من ذلك أنفاً. فقال: خلّى عنها، وهو يقدر عليها، ثم يخطبها. فحال بينه وبينها فأنزل الله: ﴿وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ﴾ [البقرة: ٢٣٢] إلى آخر الآية. فدعاه رسول الله ﷺ فقرأ عليه، فترك الحمية، واستقاد لأمر الله."],"takhrij":"صحيح: رواه البخاري (٥٣٣١).","grade":"صحيح","chapter_ar":"باب قوله تعالى: ( لَا يَحِلَّ لَكُمْ أَن تَرِنُواْ النِّسَآءَ كَرَهَا وَلَا تَتْضُلُوهُنَّ (التساء: ١٩)","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5331).","chapter_en":"The Saying of Allah the Exalted: “It is not lawful for you to inherit women by compulsion, nor should you prevent them” [al-Nisa’: 19]","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Maʿqil ibn Yasar said: His sister was married to a man who divorced her, then left her until her waiting period ended. After that he proposed to her again, but Maʿqil became angry about that. He said: “He left her while he had the ability to keep her, then he comes to propose to her again?” So he prevented him from marrying her. Then Allah revealed: “And when you divorce women and they have reached the end of their waiting period, do not prevent them” [al-Baqarah: 232] to the end of the verse. The Messenger of Allah ﷺ called him and recited it to him, so he gave up his anger and submitted to the command of Allah."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5331}]},{"num":6592,"demo":false,"sanad":"","matn":["عن ابن عباس في قوله: ﴿مَا نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِهَا نَأْتِ بِخَيْرٍ مِنْهَا أَوْ مِثْلِهَا﴾ [البقرة: ١٠٦]، وقال: ﴿وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ﴾ [النحل: ١٠١]، وقال: ﴿يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ﴾ [الرعد: ٣٩]. فأول ما نسخ من القرآن القبلة، وقال: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ﴾ [البقرة: ٢٢٨]، وقال: ﴿وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ﴾ [الطلاق: ٤]، فنسخ من ذلك فقال تعالى: ﴿ثُمَّ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا﴾ [الأحزاب: ٤٩]."],"takhrij":"حسن: رواه النسائي (٣٤٩٩) واللفظ له، وأبو داود (٢٢٨٢).","grade":"حسن","chapter_ar":"باب عدة المطلقات في صورها المختلفة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3499), and this is his wording, and Abu Dawud (2282).","chapter_en":"The Waiting Period of Divorced Women in Their Different Situations","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿAbbas said regarding the verse, “Whatever verse We abrogate or cause to be forgotten, We bring one better than it or similar to it” [al-Baqarah: 106], and the verse, “And when We replace one verse with another — and Allah knows best what He sends down” [al-Nahl: 101], and the verse, “Allah erases what He wills and confirms, and with Him is the Mother of the Book” [al-Raʿd: 39]: The first thing to be abrogated from the Qur’an was the qiblah. And Allah said, “Divorced women shall wait by themselves for three menstrual cycles” [al-Baqarah: 228], and He said, “And those who have despaired of menstruation among your women, if you doubt, then their waiting period is three months” [al-Talaq: 4]. Then from that was excepted His saying: “Then if you divorce them before you have touched them, then there is no waiting period for you to count against them” [al-Ahzab: 49]."]},"intro":{"ar":["قال الله تعالى: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ﴾ [البقرة: ٢٢٨]. هذه لعموم المطلقات.","وعِدّة الحامل المطلقة أو المتوفى عنها زوجها: ﴿وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ﴾ [الطلاق: ٤].","وعِدّة الآيسة والصغيرة: ﴿وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ وَاللَّائِي لَمْ يَحِضْنَ﴾ [الطلاق: ٤].","وعِدّةُ المطلقة قبل الدخول بها: ( إِذَا نَكَحْتُمُ المُؤْمِنَٰتِ ثُمَّطَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةِ تَعْتَدُّونَهَا ) [الأحزاب: ٤٩]."],"en":["Allah the Exalted said: “Divorced women shall wait by themselves for three menstrual cycles” [al-Baqarah: 228], and this applies generally to divorced women.","The waiting period of a pregnant woman, whether divorced or whose husband has died, is: “And for those who are pregnant, their term is until they deliver their burdens” [al-Talaq: 4].","The waiting period of the woman who no longer menstruates and the young girl is: “And those of your women who have despaired of menstruation, if you doubt, then their waiting period is three months, as well as those who have not menstruated” [al-Talaq: 4].","The waiting period of a divorced woman before consummation is: “If you marry believing women and then divorce them before you have touched them, then there is no waiting period for you to count against them” [al-Ahzab: 49]."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3499},{"key":"abudawud","label":"أبو داود","number":2282}]},{"num":6593,"demo":false,"sanad":"","matn":["عن ابن عباس قال: أتى النبي ﷺ رجل فقال: يا رسول الله ﷺ إن سيدي زوّجني أمته، وهو يريد أن يفرق بيني وبينها. قال: فصعد رسول الله ﷺ المنبر فقال: (( يا أيها الناس ما بالُ أحدكم يُزوج عبده أمته ثم يريد أن يفرق بينهما، إنما الطلاق لمن أخذ بالساق»."],"takhrij":"حسن: رواه ابن ماجه (٢٠٨١)، والدارقطني (٣٧/٤)، والبيهقي (٣٦٠/٧).","grade":"حسن","chapter_ar":"باب طلاق العبد","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2081), al-Daraqutni (4/37), and al-Bayhaqi (7/360).","chapter_en":"The Divorce of a Slave","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Ibn ʿAbbas said: A man came to the Prophet ﷺ and said: “O Messenger of Allah, my master married me to his slave woman, and now he wants to separate me from her.” So the Messenger of Allah ﷺ ascended the pulpit and said: “O people, why is it that one of you marries his slave to his slave woman, then wants to separate them? Divorce belongs only to the one who has taken hold of the leg.”"]},"buhuth":{"ar":["قوله: “الطلاق لمن أخذ بالساق” معناه أن الطلاق حقّ الزوج الذي له أن يأخذ بساق المرأة، وليس","ذلك بحق المولى."],"en":["His statement, “Divorce belongs to the one who has taken hold of the leg,” means that divorce is the husband’s right, the one who has marital access to the woman, and it is not the right of the master."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2081},{"key":"الدارقطنی","label":"الدارقطني","number":37},{"key":"البیہقی","label":"البيهقي","number":360}]},{"num":6594,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: لعن رسول الله ﷺ المحلِّل والمحلَّل له."],"takhrij":"صحيح: رواه الترمذي (١١٢٠) والنسائي (٣٤١٦) وأحمد (٤٢٤٨). قال الترمذي: “ حسن صحيح”.","grade":"صحيح","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1120), al-Nasa’i (3416), and Ahmad (4248). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Ibn Masʿud said: The Messenger of Allah ﷺ cursed the muhallil and the one for whom it is done."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1120},{"key":"nasai","label":"النسائي","number":3416},{"key":"ahmad","label":"مسند الإمام أحمد","number":3737,"n":3737}]},{"num":6595,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لعن رسول الله ﷺ المحلِّل والمحلَّل له."],"takhrij":"حسن: رواه أحمد (٨٢٨٧) وابن الجارود (٦٨٤) والبزار - كشف الاستار (١٤٤٢) والبيهقي (٢٠٨/٧).","grade":"حسن","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (8287), Ibn al-Jarud (684), al-Bazzar in Kashf al-Astar (1442), and al-Bayhaqi (7/208).","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ cursed the muhallil and the one for whom it is done."]}},"tuhfa":{},"refs":[{"key":"ابن_الجارود","label":"ابن الجارود","number":684},{"key":"البزار_کشف_الاستار","label":"البزار - كشف الاستار","number":1442},{"key":"البیہقی","label":"البيهقي","number":208},{"key":"ahmad","label":"مسند الإمام أحمد","number":8287,"n":8287}]},{"num":6596,"demo":false,"sanad":"","matn":["عن عقبة بن عامر، قال رسول الله ﷺ: «ألا أخبركم بالتيس المستعار؟» قالوا: بلى يا رسول الله. قال: «هو المحلِّل. لعن الله المحلِّل والمحلَّل له»."],"takhrij":"حسن: رواه ابن ماجه (١٩٣٦)، و الحاكم (١٩٩-١٩٨/٢)","grade":"حسن","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1936) and al-Hakim (2/198–199).","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿUqbah ibn ʿAmir said: The Messenger of Allah ﷺ said: “Shall I not tell you about the billy goat hired for use?” They said: “Yes, O Messenger of Allah.” He said: “It is the muhallil. Allah has cursed the muhallil and the one for whom it is done.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1936},{"key":"و_الحاکم","label":"و الحاكم","number":199}]},{"num":6597,"demo":false,"sanad":"","matn":["عن نافع أنه قال: جاء رجل إلى ابن عمر فسأله عن رجل طلّق امرأته ثلاثا، فتزوجها أخ له من غير موامرة منه ليُحلّها لأخيه، هل تحل للأول؟ قال: لا إلا نكاح رغبة. كنا نعد هذا سفاحاً على عهد رسول الله ﷺ."],"takhrij":"صحيح: رواه الطبراني في الأوسط - مجمع البحرين (٢٣٦٧) والحاكم (١٩٩/٢) والبيهقي (٢٠٨/٧).","grade":"صحيح","chapter_ar":"باب ما جاء في المحلّ والمحَلّل له","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tabarani in al-Awsat, Majmaʿ al-Bahrayn (2367), al-Hakim (2/199), and al-Bayhaqi (7/208).","chapter_en":"What Has Been Reported Regarding the Muhallil and the One for Whom He Is Made Muhallil","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Nafiʿ said: A man came to Ibn ʿUmar and asked him about a man who divorced his wife three times, then his brother married her without prior agreement with him in order to make her lawful again for his brother. Would she become lawful for the first husband? He said: “No, not unless it is a genuine marriage of desire. We used to regard this as fornication during the time of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الاوسط_مجمع_البحرین","label":"الطبراني في الأوسط - مجمع البحرين","number":2367},{"key":"البیہقی","label":"البيهقي","number":208},{"key":"hakim","label":"المستدرك على الصحيحين","number":2806,"n":2792},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14189,"n":14326}]},{"num":6598,"demo":false,"sanad":"","matn":["عن ابن عباس قال: ﴿وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ وَلَا يَحِلُّ لَهُنَّ أَنْ يَكْتُمْنَ مَا خَلَقَ اللَّهُ فِي أَرْحَامِهِنَّ﴾ [البقرة: ٢٢٨]. وذلك أن الرجل كان إذا طلق امرأته فهو أحق برجعتها وإن طلقها ثلاثاً، فنسخ ذلك فقال: ﴿الطَّلَاقُ مَرَّتَانِ﴾ [البقرة: ٢٢٩]."],"takhrij":"حسن: رواه أبو داود (٢١٩٥) والبيهقي (٣٣٧/٧) والنسائي (٣٥٥٤).","grade":"حسن","chapter_ar":"باب نسخ المراجعة بعد التطليقات الثلاث","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2195), al-Bayhaqi (7/337), and al-Nasa’i (3554).","chapter_en":"The Abrogation of Taking Back One’s Wife After Three Divorces","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Ibn ʿAbbas said regarding the verse, “Divorced women shall wait by themselves for three menstrual cycles, and it is not lawful for them to conceal what Allah has created in their wombs” [al-Baqarah: 228]: A man, if he divorced his wife, had more right to take her back even if he divorced her three times. Then that was abrogated by His saying: “Divorce is twice” [al-Baqarah: 229]."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2195},{"key":"البیہقی","label":"البيهقي","number":337},{"key":"nasai","label":"النسائي","number":3554},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14975,"n":15122}]},{"num":6599,"demo":false,"sanad":"","matn":["عن أبي أسيد قال: خرجنا مع النبي ﷺ حتى انطلقنا إلى حائط يقال له: الشوط، حتى انتهينا إلى حائطين فجلس بينهما، فقال النبي ﷺ: ( اجلسوا هاهنا» ودخل، وقد أتى بالجونية، فأُنزلتْ في بيت في نخل في بيت أميمة بنت النعمان بن شراحيل، ومعها دايتها حاضنة لها. فلما دخل عليها النبي ﷺ قال: (( هبي نفسك لي)) فقالت: وهل تَهَبُ الملكة نفسها للسوقة؟ قال: فأهوى بيده","يضع يده عليها لتسكن. فقالت: أعوذ بالله منك. فقال: (( قد عُذتِ بمعاذ ) ثم خرج علينا فقال: (( يا أبا أسيد اكسُها رازقيتين، وألْحِقها بأهلها)»."],"takhrij":"صحيح: رواه البخاري ( ٥٢٥٥).","grade":"صحيح","chapter_ar":"باب متعة المطلقة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5255).","chapter_en":"The Consolatory Gift for a Divorced Woman","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abu Usayd said: We went out with the Prophet ﷺ until we came to a garden called al-Shawt. When we reached two gardens, he sat between them and said: “Sit here.” Then he entered, and al-Jawniyyah had been brought and lodged in a house among date palms in the home of Umaymah bint al-Nuʿman ibn Sharahil, with her nurse caring for her. When the Prophet ﷺ entered upon her, he said: “Give yourself to me.” She said: “Does a queen give herself to a commoner?” He then moved his hand toward her to calm her. She said: “I seek refuge in Allah from you.” He said: “You have sought refuge with the One who grants refuge.” Then he came out to us and said: “O Abu Usayd, clothe her in two Raziqi garments (white linen garments) and send her back to her family.”"]},"buhuth":{"ar":["وقوله: (( داية): معرب يقال للممرضة والقابلة. والمراد هنا من كانت معها لإصلاح شأنها. وقولها:","((للسوقة): أي لواحد من الرعية. وهي جَهِلَتْ كونه نبي الله ﷺ لما علمت ذلك تأسفت وقالت: خُدِعتُ وأنا شَقية."],"en":["The word داية is an Arabized term used for a nurse or midwife. What is meant here is the woman who was with her to arrange her affairs. Her statement للسوقة means: to one of the common people. She did not know that he was the Prophet of Allah ﷺ. When she later learned that, she regretted it and said: “I was deceived, and I am wretched.”"]},"intro":{"ar":["قال الله تعالى: ﴿وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ﴾ [البقرة: ٢٤١]."],"en":["Allah the Exalted said: “And for divorced women is a provision according to what is fair, a duty upon the righteous.” [al-Baqarah: 241]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5255}]},{"num":6600,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: لما طلّق حفص بن المغيرة امرأته فاطمة أتت النبي ﷺ، فقال لزوجها: «متِّعها». قال: لا أجد ما أمتعها. قال: «فإنه لا بد من المتاع». قال: «متِّعها ولو نصف صاع من تمر»."],"takhrij":"حسن: رواه البيهقي (٢٥٧/٧).","grade":"حسن","chapter_ar":"باب متعة المطلقة","chapter_ur":"","part_ar":"كتاب الطلاق","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqi (7/257).","chapter_en":"The Consolatory Gift for a Divorced Woman","part_en":"The Book of Divorce","group_ar":"","group_en":"","part_no":25,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Jabir ibn ʿAbd Allah said: When Hafs ibn al-Mughirah divorced his wife Fatimah, she came to the Prophet ﷺ, and he said to her husband: “Give her a parting gift.” He said: “I do not find anything with which to give her a gift.” He said: “A gift is still necessary.” He said: “Give her a gift, even if it is half a saʿ of dates.”"]},"buhuth":{"ar":["قال سعيد بن المسيب: إنَّ عمرَ وعثمانَ قضيَا في المفقودِ، أنَّ امرأتَه تتربّصُ أربعَ سنينَ، وأربعةَ","أشهرٍ وعشرًا بعدَ ذلك، ثم تتزوّجُ، فإنْ جاءَ زوجُها الأولُ خُيِّرَ بين الصَّداقِ وبين امرأتِه.","رواه عبد الرزاق (١٢٣١٧) عن معمر، عن الزهري، عن ابن المسيب به. وإسناده صحيح.","وهذا أصحُّ ما رُويَ في هذا الباب، وبه قال ابنُ عمر، وابنُ عباس، وابنُ مسعود، واختار ابنُ المنذر","التأجيلَ لاتفاق خمسةٍ من الصحابة عليه.","وتُحتَسَبُ المدّهُ من يومِ رُفِعَ الأمرُ إلى الحاكمِ، وهذه المدّهُ التي ذكرَها عمرُ وعثمانُ في الأسفارِ التي","غالبها السَّلامةُ.","أما إذا خرج للقتال، فقال سعيد بن المسيب: “إذا فُقِدَ في الصفّ تربّصتْ سنةً، وإذا فُقِدَ في غير الصفّ فأربعُ سنين”. رواه عبد الرزاق (١٢٣٢٦) عن الثوري، عن داود بن أبي هند، عن ابن المسيب به. وإسناده صحيح أيضا.","ومن العلماء من قالوا: تأجيل المدّة يرجعُ إلى اجتهادِ الحاكم.","والمالكيةُ يرون أنَّ المرأةَ إذا تزوّجتْ بعد انقطاع عدّتها، ثم جاءَ زوجُها الأولُ فلا سبيلَ له عليها.","وفي المسألةِ خلافٌ بين أهل العلم، وموضوعُها كتب الفقه.","انظر للمزيد: المنّة الكبرى (٤٨١ /٦)."],"en":["Saʿid ibn al-Musayyib said: ʿUmar and ʿUthman ruled concerning the missing person that his wife should wait for four years, then observe a waiting period of four months and ten days after that, and then she may marry. If her first husband returns, he is given the choice between the dowry and his wife.","Narrated by ʿAbd al-Razzaq (12317) from Maʿmar, from al-Zuhri, from Ibn al-Musayyib with this wording. Its chain is authentic.","This is the strongest report narrated in this chapter, and this was also the view of Ibn ʿUmar, Ibn ʿAbbas, and Ibn Masʿud. Ibn al-Mundhir chose setting a time period because five of the Companions agreed upon it.","The period is counted from the day the matter is presented to the judge, and this time period mentioned by ʿUmar and ʿUthman applies to journeys in which safety is usually expected.","As for when he goes out for fighting, Saʿid ibn al-Musayyib said: “If he goes missing in battle lines, she waits one year, and if he goes missing outside battle lines, then four years.” Narrated by ʿAbd al-Razzaq (12326) from al-Thawri, from Dawud ibn Abi Hind, from Ibn al-Musayyib. Its chain is also authentic.","Some scholars said that setting the time period returns to the judgment of the ruler.","The Malikis hold that if the woman marries after the end of her waiting period, then the first husband returns, he has no right over her.","There is disagreement among the scholars on this matter, and its detailed discussion is found in the books of fiqh.","For more, see: al-Minnah al-Kubra (6/481)."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":257},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":14493,"n":14638}]},{"num":6601,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس أن امرأة ثابت بن قيس أتت النبي ﷺ فقالت: يا رسول الله، ثابت بن قيس ما أعتب عليه في خُلُق ولا دين، ولكني أكره الكفر في الإسلام، فقال رسول الله ﷺ ((أتردين عليه حديقتَه؟ )) قالت: نعم. قال رسول الله ﷺ: (( اقبل الحديقة وطلَقها تطليقةً))"],"takhrij":"صحيح: رواه البخاري (٥٢٧٣). وأخرج عبد الرزاق (١١٧٥٩)، عن معمر، قال: “بلغني أنها","grade":"صحيح","chapter_ar":"باب في جواز الخلع","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5273). ʿAbd al-Razzaq (11759) also narrated from Maʿmar, who said: “It reached me that she said: O Messenger of Allah, you can see the beauty I have, while Thabit is an unattractive man.”","chapter_en":"Chapter on the Permissibility of Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that the wife of Thabit ibn Qays came to the Prophet ﷺ and said: “O Messenger of Allah, I do not fault Thabit ibn Qays in his character or religion, but I dislike ingratitude in Islam.” So the Messenger of Allah ﷺ said: “Will you return his garden to him?” She said: “Yes.” The Messenger of Allah ﷺ said: “Accept the garden and divorce her with one divorce.”"]},"buhuth":{"ar":["قالت: يا رسول الله ﷺ إلي من الجمال ما ترى، وثابت رجل دميم”. دميم أي غير جميل."],"en":["“Unattractive” means not handsome."]},"intro":{"ar":["قال الله تعالى: ( فَإِنْ خِفْتُمْ أَلَّا يُقِيمَاحُدُودَ اللَّهِ لَا جُنَاحَ عَلَيْهِمَا فِيمَا أَقْتَدَتْ بِهِ ) (البقرة: ٢٢٩]"],"en":["Allah the Exalted said: “But if you fear that they will not keep within the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself.” [al-Baqarah: 229]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5273},{"key":"واخرج_عبد_الرزاق","label":". وأخرج عبد الرزاق","number":11759}]},{"num":6602,"demo":false,"sanad":"","matn":["عن حبيبة بنت سهل الأنصاري، أنها كانت تحت ثابت بن قيس بن شماس. وأن رسول الله ﷺ خرج إلى الصبح. فوجد حبيبة بنت سهل عند بابه في الغَلَس. فقال لها رسول الله ﷺ ((من هذه؟)) فقالت: أنا حبيبة بنت سهل يا رسول الله. قال: (( ما شأنك؟) قالت: لا أنا ولا ثابت بن قيس لزوجها، فلما جاء زوجُها ثابت بن قيس، قال له رسول الله ﷺ: (( هذه حبيبة بنت سهل، وذكرت ما شاء الله أن تذكر) فقالت حبيبة: يا رسول الله ﷺ ما أعطاني عندي. فقال رسول الله ﷺ لثابت بن قيس: (( خذ منها)) فأخذ منها وجلست في بيت أهلها."],"takhrij":"صحيح: رواه مالك (٢١) وأحمد (٢٧٤٤٤)، وأبو داود (٢٢٢٧)، والنسائي (٣٤٦٢).","grade":"صحيح","chapter_ar":"باب في جواز الخلع","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (21), Ahmad (27444), Abu Dawud (2227), al-Nasa’i (3462).","chapter_en":"Chapter on the Permissibility of Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Habibah bint Sahl al-Ansariyyah reported that she was married to Thabit ibn Qays ibn Shammās. The Messenger of Allah ﷺ went out for the dawn prayer and found Habibah bint Sahl at his door in the darkness before dawn. The Messenger of Allah ﷺ said to her: “Who is this?” She replied: “I am Habibah bint Sahl, O Messenger of Allah.” He said: “What is the matter?” She said: “Neither I nor Thabit ibn Qays can continue as husband and wife.” When her husband Thabit ibn Qays came, the Messenger of Allah ﷺ said to him: “This is Habibah bint Sahl, and she has mentioned what Allah willed her to mention.” Habibah said: “O Messenger of Allah, everything he gave me is still with me.” So the Messenger of Allah ﷺ said to Thabit ibn Qays: “Take it from her.” So he took it from her, and she stayed in her family’s home."]},"buhuth":{"ar":["وفي قوله: “جلستْ في بيت أهلها”: دليل على أنه لا سكن للمختلعة على الزوج."],"en":["In the phrase “she stayed in her family’s home” there is evidence that a woman who obtains khulʿ is not entitled to housing from the husband."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":21},{"key":"abudawud","label":"أبو داود","number":2227},{"key":"nasai","label":"النسائي","number":3462},{"key":"ahmad","label":"مسند الإمام أحمد","number":27444,"n":27444}]},{"num":6603,"demo":false,"sanad":"","matn":["عن عائشة أن حبيبة بنت سهل كانت عند ثابت بن قيس بن شماس، فضربها، فكسر بعضها، فأتت النبي ﷺ بعد الصبح، فاشتكته إليه. فدعا النبي ﷺ ثابتًا فقال: (( خُذْ بعضَ مالها وفارِقُها))، فقال: ويصلح ذلك يا رسول الله؟ قال: (( نعم)، قال: فإني أصدقتها حديقتين وهما بيدها.","فقال النبي ﷺ: (( خُذْهما وفارِقْها )) ففعل."],"takhrij":"صحيح: رواه أبو داود (٢٢٢٨). وفي قوله: (( خذهما وفارقها)): دليل على أن يأخذ الرجل كل ما أعطاها، ولكن في الرواية الثانية أنه أخذ إحداهما فلعله أخذ في أول الأمر كلتيهما ثم رد إحداهما تنزها منه.","grade":"صحيح","chapter_ar":"باب في جواز الخلع","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2228).","chapter_en":"Chapter on the Permissibility of Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah reported that Habibah bint Sahl was married to Thabit ibn Qays ibn Shammās. He struck her and broke one of her bones. So she came to the Prophet ﷺ after dawn and complained about him. The Prophet ﷺ called him and said: “Take some of her wealth and separate from her.” He said: “Is that acceptable, O Messenger of Allah?” He said: “Yes.” He said: “I gave her two gardens as her bridal gift, and they are in her possession.” So the Prophet ﷺ said: “Take them both and separate from her.” So he did that."]},"buhuth":{"en":["In his saying, “Take them both and separate from her,” there is evidence that a man may take back all that he gave her. But in the second narration he took one of them, so perhaps he first took both and then returned one out of scrupulousness."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2228}]},{"num":6604,"demo":false,"sanad":"","matn":["عن ثوبان قال: قال رسول الله ﷺ:","«أَيُّمَا امْرَأَةٍ سَأَلَتْ زَوْجَهَا الطَّلَاقَ فِي غَيْرِ مَا بَأْسٍ، فَحَرَامٌ عَلَيْهَا رَائِحَةُ الْجَنَّةِ»."],"takhrij":"صحيح: رواه أبو داود (٢٢٢٦)، والترمذي (١١٨٧)، وابن ماجه (٢٠٥٥)، وابن الجارود (٧٤٨).","grade":"صحيح","chapter_ar":"باب كراهية الخلع للمرأة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2226), al-Tirmidhī (1187), Ibn Mājah (2055), and Ibn al-Jārūd (748).","chapter_en":"Chapter on the Dislike of Khulʿ for a Woman","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Thawbān reported that the Messenger of Allah ﷺ said:","“Any woman who asks her husband for divorce without there being any valid harm or cause, the fragrance of Paradise is forbidden to her.”"]},"buhuth":{"ar":["وقوله: «سألت زوجها الطلاق» أي الخلع؛ لأن الطلاق بيد الرجل، وهو حق من حقوقه، وله أن يستعمله إذا لزم الأمر.","والخلع من حقوق المرأة، فإن رأت أن الحياة الزوجية لا تستقيم فلها أن تطلب الخلع من زوجها، ويجوز للزوج أن يطلب منها ما أنفق عليها من المهر، لقوله تعالى:","﴿فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ﴾","[البقرة: ٢٢٩]"],"en":["His statement, “asks her husband for divorce,” refers here to khulʿ, because divorce is in the husband’s hand and is one of his rights, which he may exercise when necessary.","Khulʿ is among the rights of a woman. If she sees that married life cannot continue properly, she may ask her husband for khulʿ. The husband may ask her to return what he gave her as dowry, because Allah Most High says:","“But if you fear that they will not keep within the limits of Allah, then there is no blame upon either of them concerning that by which she ransoms herself.”","[al-Baqarah: 229]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2226},{"key":"tirmidhi","label":"الترمذي","number":1187},{"key":"ibnmajah","label":"ابن ماجه","number":2055},{"key":"ابن_الجارود","label":"ابن الجارود","number":748}]},{"num":6605,"demo":false,"sanad":"","matn":["عن ابن عباس أن جميلة بنت سلول أتت النبيَّ ﷺ فقالت: والله ما أعتبُ ثابتا في دِين ولا خلق، ولكني أكره الكفر في الإسلام. لا أطيقه بغْضاً. فقال لها النبي ﷺ: (( أتردين عليه حديقتَهِ؟) قالت: نعم. فأمره النبي ﷺ أن يأخذ منها حديقته ولا يزداد."],"takhrij":"حسن: رواه ابن ماجه (٢٠٥٦)، والبيهقي (٣١٣/٧).","grade":"حسن","chapter_ar":"باب لا يجوز للزوج أن يأخذ أكثر مما أعطاها","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2056) and al-Bayhaqi (7/313).","chapter_en":"The Husband May Not Take More Than What He Gave Her","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas reported that Jamilah bint Salul came to the Prophet ﷺ and said: “By Allah, I do not fault Thabit in religion or character, but I dislike ingratitude in Islam. I cannot bear him out of dislike.” So the Prophet ﷺ said to her: “Will you return his garden to him?” She said: “Yes.” Then the Prophet ﷺ ordered him to take back his garden from her and not take any more."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2056},{"key":"البیہقی","label":"البيهقي","number":313}]},{"num":6606,"demo":false,"sanad":"","matn":["عن الربيع بنت معوذ بن عفراء أنها اختلعت على عهد النبي ﷺ فأمرها النبي ﷺ أو أُمِرَتْ أن تعتد بحيضة."],"takhrij":"صحيح: رواه الترمذي (١١٨٥) وصحّحه.","grade":"صحيح","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1185), who authenticated it.","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ reported that she obtained khulʿ during the time of the Prophet ﷺ, and the Prophet ﷺ ordered her, or she was ordered, to observe a waiting period of one menstrual cycle."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1185}]},{"num":6607,"demo":false,"sanad":"","matn":["عن عبادة بن الوليد بن عبادة بن الصامت، عن الربيع بنت معوذ بن عفراء قال:","قلت لها: حدَّثِيني حديثك قالت: اختلعتُ من زوجي ثم جئتُ عثمان فسألت: ماذا علي من العدة؟ فقال: لا عدة عليك، إلا أن تكوني حديثة عهد به، فتمكثي حتى تحيضي حيضة. قال: وأنا متبع في ذلك قضاء رسول الله ﷺ في مريم المغالية، وكانت تحت ثابت بن قيس فاختلعت منه."],"takhrij":"حسن: رواه النسائي (٣٤٩٨) وابن ماجه (٢٠٥٨).","grade":"حسن","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (3498) and Ibn Majah (2058).","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿUbadah ibn al-Walid ibn ʿUbadah ibn al-Samit reported from al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ that he said to her: “Tell me your story.” She said: “I obtained khulʿ from my husband, then I came to ʿUthman and asked: What waiting period is required of me?” He said: “There is no waiting period upon you unless you were recently with him, in which case remain until you menstruate one cycle.” He said: “I am following in this the ruling of the Messenger of Allah ﷺ regarding Maryam al-Mughaliyyah, who had been married to Thabit ibn Qays and obtained khulʿ from him.”"]},"buhuth":{"ar":["وقوله: لا عدة عليك إلا أن يكون حديث عهد بك: أي ليس على المختلعة عدة مثل عدة المطلقة إلا حيضة واحدة للاستبراء إن كانت حديث عهد بالزواج بدخوله عليك، أو بالجماع فتمكثين عنده، وإلا فلا عدة عليك، ولكن يعارض هذا ما جاء في حديث ابن عباس عند أبي داود وغيره أمرها أن تعتد بحيضة فيحمل هذا على الحكم الغالب بأن قد جامعها، فتعتد بحيضة للاستبراء."],"en":["His statement, “There is no waiting period upon you unless he has only recently been with you,” means that the woman who obtains khulʿ does not have a waiting period like that of a divorced woman, except one menstrual cycle for womb clearance if the marriage was recently consummated or intercourse had occurred, in which case she stays until she menstruates once. Otherwise there is no waiting period upon her. But this is opposed by what appears in the hadith of Ibn ʿAbbas in Abu Dawud and others, that she was ordered to observe one menstrual cycle, so this is understood according to the usual case that intercourse had occurred, and therefore she observes one cycle for womb clearance."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3498},{"key":"ibnmajah","label":"ابن ماجه","number":2058}]},{"num":6608,"demo":false,"sanad":"","matn":["عن الربيع بنت معوذ بن عفراء أخبرت أن ثابت بن قيس بن شماس ضرب امرأته فكسر يدها، وهي جميلة بنت عبد الله بن أُبيّ، فأتى أخوها يشتكيه إلى رسول الله ﷺ، فأرسل رسول الله ﷺ إلى ثابت فقال له: «خذ الذي لها عليك، وخل سبيلها». قال: نعم. فأمرها رسول الله ﷺ أن","تتربص حيضة واحدة، فتلحق بأهلها."],"takhrij":"صحيح: رواه النسائي (٣٤٩٧).","grade":"صحيح","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3497).","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Rubayyiʿ bint Muʿawwidh ibn ʿAfra’ reported that Thabit ibn Qays ibn Shammās struck his wife and broke her arm. She was Jamilah bint ʿAbdullah ibn Ubayy. Her brother came to complain about him to the Messenger of Allah ﷺ, so the Messenger of Allah ﷺ sent for Thabit and said to him: “Take what belongs to you from her and let her go.” He said: “Yes.” Then the Messenger of Allah ﷺ ordered her to wait for one menstrual cycle and then return to her family."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3497}]},{"num":6609,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس أن امرأة ثابت بن قيس اختلعت من زوجها على عهد رسول الله ﷺ فأمرها أن تعتد بحيضة."],"takhrij":"حسن: رواه أبو داود (٢٢٢٩) والترمذي (١١٨٥ المكرر) والحاكم (٢٠٦/٢).","grade":"حسن","chapter_ar":"باب عدة المختلعة","chapter_ur":"","part_ar":"كتاب الخلع","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2229), al-Tirmidhi (1185, repeated), and al-Hakim (2/206).","chapter_en":"The Waiting Period of the Woman Who Obtains Khulʿ","part_en":"The Book of Khulʿ","group_ar":"","group_en":"","part_no":26,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿAbbas reported that the wife of Thabit ibn Qays obtained khulʿ from her husband during the time of the Messenger of Allah ﷺ, and he ordered her to observe a waiting period of one menstrual cycle."]},"buhuth":{"ar":["قال الترمذي: “حسن غريب”.","قال شيخ الإسلام ابن تيمية رحمه الله تعالى: من نظر هذا القول وجده مقتضى قواعد الشريعة؛ فإن العدة إنما جعلت ثلاث حيض ليطول زمن الرجعة، ويتروى الزوج، ويتمكن من الرجعة في مدة العدة. فإذا لم تكن عليها رجعة فالمقصود براءة رحمها من الحمل، وذلك يكفي فيه حيضة كالاستبراء."],"en":["Al-Tirmidhi said: “Hasan Gharib.”","Shaykh al-Islam Ibn Taymiyyah, may Allah have mercy on him, said: Whoever considers this view will find that it accords with the principles of the Shariʿah. The waiting period was made three menstrual cycles only so that the time for possible return would be extended, the husband could reconsider, and he would be able to take her back during the waiting period. But when there is no right of return over her, then the purpose is only to make sure her womb is free from pregnancy, and one menstrual cycle is sufficient for that, just like womb clearance."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2229},{"key":"tirmidhi","label":"الترمذي","number":1185},{"key":"hakim","label":"الحاكم","number":206}]},{"num":6610,"demo":false,"sanad":"","matn":["عن سهل بن سعد الساعدي أخبره أن عويمراً العجلاني جاء إلى عاصم بن عدي الأنصاري. فقال له: يا عاصم. أرأيتَ رجلاً وجد مع امرأته رجلاً. أيقتله فتقتلونه؟ أم كيف يفعل؟ سل لي، يا عاصم، عن ذلك رسول الله ﷺ فسأل عاصم رسول الله ﷺ عن ذلك. فكره رسولُ الله المسائلَ وعابها. حتى كبر على عاصم ما سمع من رسول الله ﷺ . فلما رجع عاصم إلى أهله، جاءه عويمر. فقال: يا عاصم. ماذا قال لك رسول الله ﷺ؟ فقال عاصم لعويمر: لم تأتني بخير. قد كره رسول الله ﷺ المسألة التي سألته عنها. فقال عويمر: والله لا أنتهي حتى أسأله عنها. فأقبل عويمر حتى أتى رسولَ الله ﷺ وسط الناس. فقال: يا رسول الله. أرأيتَ رجلاً وجد مع امرأته رجلاً، أيقتله تقتلونه؟ أم كيف يفعل؟ فقال رسول الله ﷺ: (( قد نزل فيك وفي صاحبتك. فاذهب فأت بها) فقال سهل: فتلاعنا وأنا مع الناس، عند رسول الله ﷺ . فلما فرغا من تلاعنهما، قال عويمر: كذبت عليها يا رسول الله ﷺ إن أمسكتها. فطلقها ثلاثاً قبل أن يأمره رسول الله ﷺ.","قال مالك: قال ابن شهاب: فكانت تلك، بعد، سنة المتلاعنين."],"takhrij":"متفق عليه: رواه مالك (٣٤) والبخاري (٥٢٥٩)، ومسلم (١:١٤٩٢).","grade":"متفق عليه","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (34), al-Bukhari (5259), and Muslim (1492/1).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd al-Saʿidi reported to him that ʿUwaymir al-ʿAjlani came to ʿAsim ibn ʿAdi al-Ansari and said to him: “O ʿAsim, what do you think of a man who finds another man with his wife? Should he kill him so that you would kill him in retaliation, or what should he do? Ask the Messenger of Allah ﷺ about that for me.” So ʿAsim asked the Messenger of Allah ﷺ about it. The Messenger of Allah ﷺ disliked such questions and disapproved of them, until what ʿAsim heard from the Messenger of Allah ﷺ weighed heavily on him. When ʿAsim returned to his family, ʿUwaymir came to him and said: “O ʿAsim, what did the Messenger of Allah ﷺ say to you?” ʿAsim said to ʿUwaymir: “You did not bring me any good. The Messenger of Allah ﷺ disliked the question I asked him about.” So ʿUwaymir said: “By Allah, I will not stop until I ask him about it myself.” Then ʿUwaymir went until he came to the Messenger of Allah ﷺ among the people and said: “O Messenger of Allah, what do you think of a man who finds another man with his wife? Should he kill him so that you would kill him, or what should he do?” The Messenger of Allah ﷺ said: “Revelation has been sent down concerning you and your wife, so go and bring her.” Sahl said: So they performed liʿān while I was with the people in the presence of the Messenger of Allah ﷺ. When they finished their mutual oaths, ʿUwaymir said: “I would have lied against her, O Messenger of Allah, if I kept her.” Then he divorced her three times before the Messenger of Allah ﷺ commanded him.","Malik said: Ibn Shihab said: That thereafter became the established practice concerning those who engage in liʿān."]},"intro":{"ar":["قال الله تعالى: ﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ فَشَهَادَةُ أَحَدِهِمْ أَرْبَعُ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الصَّادِقِينَ ۝ وَالْخَامِسَةُ أَنَّ لَعْنَتَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ ۝ وَيَدْرَأُ عَنْهَا الْعَذَابَ أَنْ تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ ۝ وَالْخَامِسَةَ أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ﴾ [النور: ٦-٩]."],"en":["Allah the Exalted said: “And those who accuse their wives and have no witnesses except themselves, then the testimony of one of them shall be four testimonies by Allah that he is surely of the truthful, and the fifth that the curse of Allah be upon him if he is of the liars. And it shall avert the punishment from her if she bears witness four times by Allah that he is surely of the liars, and the fifth that the wrath of Allah be upon her if he is of the truthful.” [Surat al-Nur: 6–9]"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":34},{"key":"bukhari","label":"البخاري","number":5259},{"key":"muslim","label":"مسلم","number":1}]},{"num":6611,"demo":false,"sanad":"","matn":["عن سهل بن سعد أخي بني ساعدة، أن رجلاً من الأنصار جاء إلى رسول الله ﷺ فقال: يا رسول الله! أرأيت رجلاً وجد مع امرأته رجلاً، أيقتله أم كيف يفعل؟ فأنزل الله في شأنه ما ذكر في القرآن من أمر المتلاعنين فقال النبي ﷺ: (( قد قضى الله فيك وفي امرأتك) قال: فتلاعنا في المسجد وأنا شاهد. فلما فرغا قال: كذبت عليها يا رسول الله ﷺ إن أمسكتها، فطلّقها ثلاثا قبل أن يأمره رسول الله ﷺ حين فرغا من التلاعن، ففارقها عند النبي ﷺ فقال: (( ذاك تفريق بين كل متلاعنين)) متفق عليه: رواه البخاري (٥٣٠٩) ومسلم (٣:١٤٩٢). والسياق للبخاري.","والرجل المبهم من الأنصار هو : عويمر العجلاني.","وقوله: “ذاك تفريق بين كل متلاعنين” فيه أن المتلاعنين لا يجتمعان أبداً."],"takhrij":"","grade":"","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5309) and Muslim (1492/3). The wording is that of al-Bukhari.","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Saʿd, the brother of Banu Saʿidah, reported that a man from the Ansar came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, what do you think of a man who finds another man with his wife? Should he kill him, or what should he do?” So Allah sent down concerning his case what is mentioned in the Qur’an regarding those who perform liʿān. Then the Prophet ﷺ said: “Allah has judged regarding you and your wife.” He said: So they performed liʿān in the mosque while I was present as a witness. When they finished, he said: “I would have lied against her, O Messenger of Allah, if I kept her,” so he divorced her three times before the Messenger of Allah ﷺ instructed him. Thus he separated from her in the presence of the Prophet ﷺ, who said: “That is the separation between every pair who perform liʿān.”"]},"buhuth":{"en":["The unnamed man from the Ansar was ʿUwaymir al-ʿAjlani.","His saying, “That is the separation between every pair who perform liʿān,” indicates that two people who have performed liʿān never reunite."]}},"tuhfa":{},"refs":[]},{"num":6612,"demo":false,"sanad":"","matn":["عن عبد الله قال: كنا ليلة الجمعة في المسجد. إذ جاء رجل من الأنصار فقال: لو أن رجلا وجد مع امرأته رجلا فتكلَّم جلدتموه، أو قتل قتلتموه، وإن سكت سكت على غيظ. والله!","لأسألن عنه رسول الله ﷺ فلما كان من الغد أتى رسول الله ﷺ فسأله، فقال: لو أن رجلاً وجد مع امرأته رجلا فتكلَّم جلدتموه، أو قتل قتلتموه، أو سكت سكت على غيظ. فقال: (( اللهم افتح)","وجعل يدعو. فنزلت آية اللعان: ﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ وَلَمْ يَكُنْ لَهُمْ شُهَدَاءُ إِلَّا أَنْفُسُهُمْ﴾","[النور:٦ ] هذه الآيات. فابتلي به ذلك الرجل من بين الناس. فجاء هو وامرأته إلى رسول الله ﷺ فتلاعنا، فشهد الرجل أربع شهادات بالله إنه لمن الصادقين. ثم لعن الخامسة أن لعنة الله عليه إن كان من الكاذبين. فذهبت لتلعن. فقال لها رسول الله ﷺ (( مه) فأبت فلعنتْ. فلما أدبرا قال: (( لعلها أن تجيء به أسود جعدا) فجاءت به أسود جعدا."],"takhrij":"صحيح: رواه مسلم (١٤٩٥). والرجل المبهم من الأنصار هو: عويمر العجلاني.","grade":"صحيح","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1495).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah reported: We were in the mosque on Friday night when a man from the Ansar came and said: “If a man found another man with his wife and spoke about it, you would flog him; if he killed him, you would kill him; and if he remained silent, he would remain silent in rage. By Allah, I will ask the Messenger of Allah ﷺ about it.” The next day he went to the Messenger of Allah ﷺ and asked him, saying: “If a man found another man with his wife and spoke, you would flog him; if he killed him, you would kill him; and if he remained silent, he would remain silent in rage.” The Prophet ﷺ said: “O Allah, clarify,” and he kept supplicating. Then the verse of liʿān was revealed: “And those who accuse their wives…” [al-Nur: 6], these verses. Then that very man was tested with it from among the people. So he and his wife came to the Messenger of Allah ﷺ and performed liʿān. The man testified four times by Allah that he was indeed telling the truth, then on the fifth he invoked the curse of Allah upon himself if he were lying. Then she went to invoke her oath, so the Messenger of Allah ﷺ said to her: “Stop.” But she refused and proceeded. When they turned away, he said: “Perhaps she will bring forth a black, curly-haired child,” and she indeed gave birth to a black, curly-haired child."]},"buhuth":{"en":["The unnamed man from the Ansar was ʿUwaymir al-ʿAjlani."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1495}]},{"num":6613,"demo":false,"sanad":"","matn":["عن ابن عباس:","أن هلال بن أمية قذف امرأته عند النبي ﷺ بشريك بن سحماء.","فقال النبي ﷺ:","«الْبَيِّنَةُ أَوْ حَدٌّ فِي ظَهْرِكَ».","فقال:","يا رسول الله، إذا رأى أحدنا على امرأته رجلًا، ينطلق يلتمس البينة؟","فجعل النبي ﷺ يقول:","«الْبَيِّنَةُ أَوْ حَدٌّ فِي ظَهْرِكَ».","فقال هلال:","والذي بعثك بالحق إني لصادق، فلينزلن الله ما يبرئ ظهري من الحد.","فنزل جبريل، وأنزل عليه:","﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ﴾","[النور: ٦]","فقرأ حتى بلغ:","﴿إِنْ كَانَ مِنَ الصَّادِقِينَ﴾","[النور: ٩]"],"takhrij":"صحيح: رواه البخاري (٤٧٤٧).","grade":"صحيح","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4747).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās reported:","Hilāl ibn Umayyah accused his wife before the Prophet ﷺ of committing adultery with Sharīk ibn Saḥmāʾ.","The Prophet ﷺ said:","“Produce evidence, otherwise the prescribed punishment will be carried out upon your back.”","Hilāl said:","“O Messenger of Allah, if one of us sees a man with his wife, is he then expected to go off looking for evidence?”","The Prophet ﷺ continued saying:","“Evidence, otherwise the prescribed punishment will be upon your back.”","Hilāl said:","“By the One who sent you with the truth, I am certainly truthful, and Allah will surely reveal something that will clear my back from the prescribed punishment.”","Then Jibrīl descended and revealed:","“And those who accuse their wives…”","[al-Nūr: 6]","The Prophet ﷺ recited the verses until he reached:","“…if he is among the truthful.”","[al-Nūr: 9]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4747}]},{"num":6614,"demo":false,"sanad":"","matn":["عن أنس قال:","إن أول لعان كان في الإسلام أن هلال بن أمية قذف شريك بن السحماء بامرأته، فأتى النبي ﷺ فأخبره بذلك.","فقال له النبي ﷺ:","«أَرْبَعَةُ شُهَدَاءَ، وَإِلَّا فَحَدٌّ فِي ظَهْرِكَ».","يردد ذلك عليه مرارًا.","فقال له هلال:","والله يا رسول الله، إن الله عز وجل ليعلم أني صادق، ولينزلن الله عز وجل عليك ما يبرئ ظهري من الجلد.","فبينما هم كذلك إذ نزلت عليه آية اللعان:","﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ﴾","[النور: ٦]","إلى آخر الآية.","فدعا هلالًا، فشهد أربع شهادات بالله إنه لمن الصادقين، والخامسة أن لعنة الله عليه إن كان من الكاذبين.","ثم دعيت المرأة، فشهدت أربع شهادات بالله إنه لمن الكاذبين.","فلما أن كان في الرابعة أو الخامسة قال رسول الله ﷺ:","«وَقِّفُوهَا، فَإِنَّهَا مُوجِبَةٌ».","فتلكأت حتى ما كدنا أنها ستعترف، ثم قالت:","لا أفضح قومي سائر اليوم.","فمضت على اليمين.","فقال رسول الله ﷺ:","«انْظُرُوهَا، فَإِنْ جَاءَتْ بِهِ أَبْيَضَ سَبْطًا قَضِيءَ الْعَيْنَيْنِ فَهُوَ لِهِلَالِ بْنِ أُمَيَّةَ، وَإِنْ جَاءَتْ بِهِ آدَمَ جَعْدًا رَبْعًا حَمْشَ السَّاقَيْنِ فَهُوَ لِشَرِيكِ بْنِ السَّحْمَاءِ».","فجاءت به آدم جعدًا ربعًا حمش الساقين.","فقال رسول الله ﷺ:","«لَوْلَا مَا سَبَقَ فِيهَا مِنْ كِتَابِ اللَّهِ لَكَانَ لِي وَلَهَا شَأْنٌ»."],"takhrij":"صحيح: رواه النسائي (٣٤٦٩)، وأحمد (١٢٤٥٠)، وصححه ابن حبان (٤٤٥١).","grade":"صحيح","chapter_ar":"باب ما جاء في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasāʾī (3469), Aḥmad (12450), and authenticated by Ibn Ḥibbān (4451).","chapter_en":"Chapter on What Has Been Narrated Regarding Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Anas reported:","The first case of liʿān in Islam occurred when Hilāl ibn Umayyah accused his wife of committing adultery with Sharīk ibn al-Saḥmāʾ. He came to the Prophet ﷺ and informed him.","The Prophet ﷺ said to him:","“Four witnesses, otherwise the prescribed punishment will be upon your back.”","He repeated this to him several times.","Hilāl said:","“By Allah, O Messenger of Allah, Allah, Mighty and Majestic, knows that I am truthful, and Allah will surely reveal to you something that will clear my back from being flogged.”","While they were in that state, the verse of liʿān was revealed:","“And those who accuse their wives…”","[al-Nūr: 6]","to the end of the verses.","The Prophet ﷺ called Hilāl, and he testified four times by Allah that he was among the truthful, and the fifth time that the curse of Allah would be upon him if he were among the liars.","Then the woman was called. She testified four times by Allah that he was among the liars.","When she reached the fourth or fifth oath, the Messenger of Allah ﷺ said:","“Stop her, for this one is decisive.”","She hesitated until we almost thought she would confess. Then she said:","“I will not disgrace my people for the rest of this day.”","So she completed the oath.","The Messenger of Allah ﷺ said:","“Watch her. If she gives birth to a child who is fair-skinned, straight-haired, and with deeply set eyes, then he is from Hilāl ibn Umayyah. But if she gives birth to one who is dark-complexioned, curly-haired, of medium stature, and thin-legged, then he is from Sharīk ibn al-Saḥmāʾ.”","She gave birth to a dark-complexioned, curly-haired, medium-sized child with thin legs.","The Messenger of Allah ﷺ then said:","“Had it not been for what has already preceded concerning her in the Book of Allah, I would have had a matter with her.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3469},{"key":"صححہ_ابن_حبان","label":"صححه ابن حبان","number":4451},{"key":"ahmad","label":"مسند الإمام أحمد","number":12450,"n":12450}]},{"num":6615,"demo":false,"sanad":"","matn":["عن محمد بن سيرين قال: سألت أنس بن مالك، وأنا أرى أن عنده منه علماً، فقال:","إن هلال بن أمية قذف امرأته بشريك بن سَحْماء، وكان أخا البراء بن مالك لأمه، وكان أول رجل لاعَن في الإسلام. قال: فلاعَنها. فقال رسول الله ﷺ: (( أبصروها، فإن جاءتْ به أبيض سبطاً قضيءَ العينين فهو لهلال بن أمية، وإن جاءت به أكحلَ جَعْداً حَمْشَ الساقين فهو لشريك بن سحماء )). قال: فأنبئت أنها جاءت به أكحل جعداً حمش الساقين."],"takhrij":"صحيح: رواه مسلم (١٤٩٦).","grade":"صحيح","chapter_ar":"باب قذف الرجل زوجتَه برجل بعينه","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1496).","chapter_en":"A Man Accusing His Wife of Adultery with a Specific Man","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Muhammad ibn Sirin said: I asked Anas ibn Malik, thinking that he had knowledge of it. He said: Hilal ibn Umayyah accused his wife concerning Sharik ibn Sahma’, who was the maternal brother of al-Bara’ ibn Malik, and he was the first man to perform liʿān in Islam. He said: So he performed liʿān with her. Then the Messenger of Allah ﷺ said: “Watch her. If she brings forth a white child with straight hair and sunken eyes, then it belongs to Hilal ibn Umayyah. But if she brings forth a dark-eyed, curly-haired child with thin legs, then it belongs to Sharik ibn Sahma’.” He said: “I was informed that she gave birth to a dark-eyed, curly-haired child with thin legs.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1496}]},{"num":6616,"demo":false,"sanad":"","matn":["عن سهل بن سعد أن رجلاً أتى النبي ﷺ فقال: يا رسول الله! أرايتَ رجلاً رأى مع امرأته رجلاً أيقتله فتقتلونه أم كيف يفعل؟ فأنزل الله فيهما ما ذكر في القرآن. فقال له رسول الله ﷺ :","((قد قضي فيك وفي امرأتك)) قال: فتلاعَنَا وأنا شاهد عند رسول الله ﷺ فَفَارقها فكانتْ سُنَّة أن يُفَرّق بين المتلاعنين. وكانت حاملاً، فأنكر حملها. وكان ابنُها يُدعى إليها. ثم جرت السنة في الميراث أن يرثها، وترث منه ما فرض الله لها."],"takhrij":"صحيح: رواه البخاري (٤٧٤٦).","grade":"صحيح","chapter_ar":"باب في الملاعنة على الزنا ونفي الحمل","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4746).","chapter_en":"Chapter on Liʿān for Adultery and the Denial of Pregnancy","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a man came to the Prophet ﷺ and said: “O Messenger of Allah, what do you think of a man who sees another man with his wife? Should he kill him so that you would kill him, or what should he do?” So Allah revealed concerning them what is mentioned in the Qur’an. Then the Messenger of Allah ﷺ said to him: “Judgment has been given regarding you and your wife.” He said: So they performed liʿān while I was a witness in the presence of the Messenger of Allah ﷺ, and he separated from her. Then it became the established practice that those who perform liʿān are to be separated. She was pregnant, and he denied her pregnancy. Her son was then attributed to her. After that, the established practice in inheritance was that he would inherit from her, and she would inherit from him whatever Allah had assigned for her."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4746}]},{"num":6617,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول الله ﷺ لاعَنَ بين العَجْلاني وامرأتِه قال: وكانت حبلى.","فقال: والله ما قربتُها منذ عفَرْنا. قال: والعفرُ أن يُسْقَى النخلُ بعد أن يُتْرك من السقي بعد الإبار بشهرين."],"takhrij":"صحيح: رواه الإمام أحمد (٣١٠٦) والنسائي (٣٤٦٧).","grade":"صحيح","chapter_ar":"باب في الملاعنة على الزنا ونفي الحمل","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (3106) and al-Nasa’i (3467).","chapter_en":"Chapter on Liʿān for Adultery and the Denial of Pregnancy","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbas reported that the Messenger of Allah ﷺ conducted liʿān between al-ʿAjlani and his wife. He said: She was pregnant. So he said: “By Allah, I have not come near her since we fertilized the palm trees.” He said: And al-ʿafr is that the palm trees are watered after being left without watering for two months after pollination."]},"buhuth":{"ar":["وفي الحديث دليل على أن اللعان كان على الزنا وعلى نفي الحمل، فإن الظاهر من نفي حمله أن حمله كان","قديما، وكان الرجل يشك في امرأته، فلما تبين له أنها زانية أنكر حملها.","وفي ذلك تفصيل: فإن الحمل إن كان سابقا، ولم يشك فيه، وإنما لاعن على زناها فقط عندما رآها تزني، فالولد له؛ لأن الولد للفراش، ولا يجوز نفي الولد باللعان، وإن لم يعلم حملها حال زناها الذي قد قذفها به،","فهذا ينظر فيه، فإن جاءت بأقل من ستة أشهر من الزنا، فالولد له، ولا ينتفى عنه بلعانه، وإن ولدته لأكثر من ستة أشهر ونفاه، فالولد ينسب إلى أمه، والحكم النهائي يعود إلى القاضي."],"en":["In this hadith there is evidence that liʿān took place both for adultery and for denying pregnancy. The apparent meaning of his denial of the pregnancy is that the pregnancy was old, and the man had been suspicious of his wife. Then when it became clear to him that she had committed adultery, he denied the pregnancy.","There is further detail in this matter: if the pregnancy was already present and he had not doubted it, and he only performed liʿān because of her adultery after seeing her commit it, then the child is his, because the child belongs to the marriage bed, and it is not permissible to deny the child through liʿān. But if he did not know of her pregnancy at the time of the adultery for which he accused her, then this is to be examined: if she gives birth less than six months after the adultery, the child is his and is not negated by his liʿān. But if she gives birth after more than six months and he denies the child, then the child is attributed to the mother. The final ruling returns to the judge."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":3106},{"key":"nasai","label":"النسائي","number":3467},{"key":"ahmad","label":"مسند الإمام أحمد","number":3106,"n":3106}]},{"num":6618,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: سئلتُ عن المتلاعنين في إمرة مُصعَب، أيْفَرَّقُ بينهما؟ قال:","فما دريتُ ما أقول، فمضيتُ إلى منزل ابن عمر بمكة. فقلت للغلام: استأذن لي. قال: إنه قائلٌ. فسمعَ صوتي. قال: ابن جبير؟ قلت: نعم. قال: ادخل. فوالله! ما جاء بك هذه الساعة إلا حاجة. فدخلت، فإذا هو مفترِش بَرْذَعة، متوسِّدٌ وسادةً حشوُها ليف. قلت: أبا عبد الرحمن! المتلاعنان، أيُفَرَّق بينهما؟ قال: سبحان الله! نعم. إن أولَ من سأل عن ذلك فلانُ بن فلان. قال: يا رسول الله! أرأيت أن لو وَجَد أحدُنا امرأته على فاحشة، كيف يَصنع؟ إنْ تكلَّم تكلَّم بأمر عظيم، وإنْ سكتَ سكتَ على مثل ذلك. قال: فسكتَ النبي ﷺ فلم يُجِبْه. فلما كان بعد ذلك أتاه فقال: إن الذي سألتُك عنه قد أُبْتليتُ به. فأنزل الله عز وجل هؤلاء الآيات في سورة النور: ﴿وَالَّذِينَ يَرْمُونَ أَزْوَجَهُمْ﴾ [النور: ٦ ] فتلاهن عليه، ووعظَه وذَكَّره. وأخبره أن عذاب الدنيا أهونُ من عذاب الآخرة. قال: لا، والذي بعثك بالحق! ما كذبتُ عليها. ثم دعاها فوعظها وذكِّرها، وأخبرها أن عذابَ الدنيا أهونُ من عذاب الآخرة. قالت: لا، والذي بعثك بالحق! إنه لكاذب. فبدأ بالرجل فشهِدَ أربعَ شهاداتٍ بالله إنه لمن الصادقين. والخامسةُ أن لعنةَ الله عليه إن كان من الكاذبين. ثم ثنِّى بالمرأة فشَهِدتْ أربعَ شهاداتٍ بالله إنه لمن الكاذبين. والخامسةُ أن غَضبَ الله عليها إن كان من الصادقين. ثم فرَّقَ بينهما ."],"takhrij":"صحيح: رواه مسلم (٤:١٤٩٣).","grade":"صحيح","chapter_ar":"باب استحباب وعظ المتلاعنين وتذكيرهما بالله عند إرادة التلاعن","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1493/4).","chapter_en":"Chapter on the Recommendation to Admonish the Two Who Perform Liʿān and Remind Them of Allah When They Intend to Do So","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I was asked about two spouses who perform liʿān during the rule of Musʿab: are they to be separated? I did not know what to say, so I went to the home of Ibn ʿUmar in Makkah. I said to the servant: Ask permission for me. He said: He is resting at midday. Then he heard my voice and said: Ibn Jubayr? I said: Yes. He said: Enter. By Allah, nothing has brought you at this hour except some need. So I entered, and there he was reclining on a saddle-cloth, using a cushion stuffed with fiber as a pillow. I said: O Abu ʿAbd al-Rahman, the two who perform liʿān, are they separated? He said: Subhan Allah, yes. The first one to ask about that was so-and-so son of so-and-so. He said: O Messenger of Allah, what if one of us finds his wife committing an indecency? If he speaks, he speaks of a grave matter, and if he remains silent, he remains silent upon the like of it. The Prophet ﷺ remained silent and did not answer him. Then after that he came to him again and said: What I asked you about, I have now been tested with it. So Allah the Mighty and Majestic revealed these verses in Surat al-Nur: “And those who accuse their wives…” [al-Nur: 6]. Then he recited them to him, admonished him and reminded him, and informed him that the punishment of this world is lighter than the punishment of the Hereafter. He said: No, by the One who sent you with the truth, I have not lied against her. Then he called her, admonished her, reminded her, and informed her that the punishment of this world is lighter than the punishment of the Hereafter. She said: No, by the One who sent you with the truth, he is surely lying. So he began with the man, and he testified four times by Allah that he was surely of the truthful, and the fifth that the curse of Allah be upon him if he were lying. Then he turned to the woman, and she testified four times by Allah that he was surely of the liars, and the fifth that the wrath of Allah be upon her if he were of the truthful. Then he separated them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":4}]},{"num":6619,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: قلت لابن عمر: رجل قذف امرأته، فقال: فَرَّقَ النبي ﷺ بين أخوي بني العجلان، وقال: (( الله يعلم أن أحدكما كاذب فهل منكما من تائب؟ ) فأبيا وقال:","«الله يعلم أن أحدكما كاذب فهل منكما من تائب؟» فأبيا فقال: (( الله يعلم أن أحدكما كاذب فهل منكما من تائب؟ )) فأبيا ففَرَّق بينهما.","قال أيوب: فقال لي عمرو بن دينار: إن في الحديث شيئا لا أراك تحدثه؟ قال: قال الرجل: مالي؟","قال: قيل: (( لا مال لك إن كنت صادقا فقد دخلت بها، وإن كنت كاذبا فهو أبعد منك))."],"takhrij":"صحيح: رواه البخاري (٥٣١١).","grade":"صحيح","chapter_ar":"باب استحباب وعظ المتلاعنين وتذكيرهما بالله عند إرادة التلاعن","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5311).","chapter_en":"Chapter on the Recommendation to Admonish the Two Who Perform Liʿān and Remind Them of Allah When They Intend to Do So","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Saʿid ibn Jubayr said: I said to Ibn ʿUmar: A man accused his wife. He said: The Prophet ﷺ separated the two brothers from Banu al-ʿAjlan and said: “Allah knows that one of you is lying, so is either of you willing to repent?” But they refused. He then said: “Allah knows that one of you is lying, so is either of you willing to repent?” But they refused. Then he said: “Allah knows that one of you is lying, so is either of you willing to repent?” But they refused, so he separated them.","Ayyub said: ʿAmr ibn Dinar said to me: There is something in the hadith that I do not see you narrating. He said: The man asked: “What about my property?” It was said: “You have no claim to property. If you were truthful, then you have already consummated the marriage with her; and if you were lying, then it is even farther from you.”"]},"buhuth":{"ar":["فأنبئت أنها جاءت به أكحل جعداً حمش الساقين.","صحيح: رواه مسلم (١١:١٤٩٦)."],"en":["And I was informed that she gave birth to a dark-eyed, curly-haired child with thin legs.","Authentic: Narrated by Muslim (1496/11)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5311}]},{"num":6620,"demo":false,"sanad":"","matn":["عن ابن عباس قال: إن النبي ﷺ أمر رجلًا حين أمر المتلاعنين أن يتلاعنا أن يضع يده على فيه عند الخامسة، يقول: إنها موجبة."],"takhrij":"حسن: رواه أبو داود (٢٢٥٥) والنسائي (٣٤٧٢) والبيهقي (٤٠٥/٧). ولم يثبت في السنن وضع اليد على فم المرأة.","grade":"حسن","chapter_ar":"باب وضع اليد على فم الرجل عند الخامسة","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2255), al-Nasa’i (3472), and al-Bayhaqi (7/405). It is not established in the Sunan collections that the hand was placed over the woman’s mouth.","chapter_en":"Chapter on Placing the Hand over the Man’s Mouth at the Fifth Oath","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbas said: The Prophet ﷺ instructed a man, when he commanded the two spouses to perform liʿān, to place his hand over his mouth at the fifth oath, saying: “It is decisive.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2255},{"key":"nasai","label":"النسائي","number":3472},{"key":"البیہقی","label":"البيهقي","number":405}]},{"num":6621,"demo":false,"sanad":"","matn":["عن عبدالله بن عمر قال: قال رسول الله ﷺ للمتلاعنين: (( حِسابُكما على الله، أحدكما كاذب، لا سبيل لك عليها)) قال: يا رسول الله ﷺ مالي؟ قال: (( لا مال لك، إن كنتَ صدقتَ عليها فهو بما استحللتَ من فرجِها، وإن كنت كذبتَ عليها فذلك أبعد لك منها )."],"takhrij":"متفق عليه: رواه البخاري (٥٣١٢)، ومسلم (٥:١٤٩٢).","grade":"متفق عليه","chapter_ar":"باب تحريم أخذ صداق الملاعِنة","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5312) and Muslim (1492/5).","chapter_en":"Chapter on the Prohibition of Taking the Dowry of the Woman Involved in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar said: The Messenger of Allah ﷺ said to the two who performed liʿān: “Your reckoning is with Allah. One of you is lying. You have no right over her.” He said: “O Messenger of Allah, what about my property?” He said: “You have no claim to any property. If you were truthful against her, then it was in exchange for what you had lawfully enjoyed of her private part. And if you lied against her, then that makes her even farther from you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5312},{"key":"muslim","label":"مسلم","number":5}]},{"num":6622,"demo":false,"sanad":"","matn":["عن ابن عباس:","أنه ذُكر التلاعن عند النبي ﷺ، فقال عاصم بن عدي في ذلك قولًا ثم انصرف.","فأتاه رجل من قومه يشكو إليه أنه قد وجد مع امرأته رجلًا.","فقال عاصم:","ما ابتليت بهذا إلا لقولي.","فذهب به إلى النبي ﷺ، فأخبره بالذي وجد عليه امرأته.","وكان ذلك الرجل مصفرًا، قليل اللحم، سبط الشعر، وكان الذي ادعى عليه أنه وجده عند أهله آدم خدلًا كثير اللحم.","فقال النبي ﷺ:","«اللَّهُمَّ بَيِّنْ».","فلاعن النبي ﷺ بينهما.","فجاءت شبيهًا بالرجل الذي ذكر زوجها أنه وجده عندها.","قال رجل لابن عباس في المجلس:","هي التي قال النبي ﷺ:","«لَوْ رَجَمْتُ أَحَدًا بِغَيْرِ بَيِّنَةٍ لَرَجَمْتُ هَذِهِ»؟","فقال:","لا، تلك امرأة كانت تظهر في الإسلام السوء.","قال أبو صالح وعبد الله بن يوسف: خدلًا."],"takhrij":"متفق عليه: رواه البخاري (٥٣١٠)، ومسلم (١٤٩٧/١٢).","grade":"متفق عليه","chapter_ar":"باب لا تُرجم المرأةُ ولو كانتِ الأمارةُ تدل على كذبها في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5310) and Muslim (1497/12).","chapter_en":"Chapter on the Woman Not Being Stoned Even If the Indications Suggest She Lied in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported:","Liʿān was mentioned in the presence of the Prophet ﷺ, and ʿĀṣim ibn ʿAdī said something regarding it and then left.","A man from his people came to him complaining that he had found another man with his wife.","ʿĀṣim said:","“I have only been afflicted with this because of what I said.”","So he took the man to the Prophet ﷺ, and he informed him of what he had found concerning his wife.","The husband was yellowish in complexion, thin in build, and straight-haired, while the man whom he accused of being with his wife was dark-complexioned, well-built, and fleshy.","The Prophet ﷺ said:","“O Allah, make the matter clear.”","The Prophet ﷺ then conducted liʿān between the two of them.","She later gave birth to a child resembling the man whom her husband had said he found with her.","A man in the gathering asked Ibn ʿAbbās:","“Was she the woman concerning whom the Prophet ﷺ said, ‘If I were to stone anyone without evidence, I would have stoned this woman’?”","He replied:","“No. That was another woman who openly displayed evil conduct in Islam.”","Abū Ṣāliḥ and ʿAbdullāh ibn Yūsuf said: “khadlan.”"]},"buhuth":{"ar":["وقوله: «فلاعن النبي ﷺ بينهما» موضعه عقب قوله: فذهب به إلى النبي ﷺ فأخبره بالذي وجد عليه امرأته، فحصل في العبارة تقديم وتأخير؛ لأن اللعان وقع قبل الوضع، كما مضى في الأحاديث، ولا معنى لتأخير اللعان إلى ما بعد الولادة."],"en":["The words “the Prophet ﷺ conducted liʿān between them” belong immediately after the statement that the man was taken to the Prophet ﷺ and informed him of what he had found concerning his wife. The wording contains an inversion in sequence, because liʿān took place before the birth, as shown by the preceding hadiths; there would be no reason to postpone liʿān until after childbirth."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5310},{"key":"muslim","label":"مسلم","number":1497}]},{"num":6623,"demo":false,"sanad":"","matn":["عن سهل بن سعد أخي بني ساعدة، أن رجلاً من الأنصار جاء إلى رسول الله ﷺ فقال: يا رسول الله، أرأيت رجلاً وجد مع امرأته رجلاً أيقتله أم كيف يفعل؟ فأنزل الله في شأنه ما ذُكِر في القرآن من أمر المتلاعنين فقال النبي ﷺ: (( قد قضى الله فيكَ وفي امرأتِك )) قال: فتلاعنا في المسجد وأنا شاهد، فلما فرغا قال: كذبت عليها يا رسول الله ﷺ إن أمسكتُها، فطلّقها ثلاثاً قبل أن يأمره رسول الله ﷺ حين فرغا من التلاعن، ففارقها عند النبي ﷺ فقال: (( ذاك تفريق بين كل متلاعنين )).","قال ابن جريج، عن ابن شهاب، عن سهل بن سعد الساعدي في هذا الحديث إن النبي ﷺ قال:","(( إن جاءت به أحمر قصيراً، كأنه وحرة، فلا أراها إلا قد صدقتْ، وكذب عليها. وإن جاءت به أسود أعين، ذا أليتين فلا أراه إلا قد صدق عليها)) فجاءت به على المكروه من ذلك."],"takhrij":"صحيح: رواه البخاري (٥٣٠٩) ومسلم (٣:١٤٩٢). والسياق للبخاري.","grade":"صحيح","chapter_ar":"باب لا تُرجم المرأةُ ولو كانتِ الأمارةُ تدل على كذبها في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5309) and Muslim (1492/3). The wording is that of al-Bukhari.","chapter_en":"Chapter on the Woman Not Being Stoned Even If the Indications Suggest She Lied in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Sahl ibn Saʿd, the brother of Banu Saʿidah, said that a man from the Ansar came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, what do you think of a man who finds another man with his wife? Should he kill him, or what should he do?” So Allah revealed concerning him what was mentioned in the Qur’an regarding those who perform liʿān. Then the Prophet ﷺ said: “Allah has judged concerning you and your wife.” He said: So they performed liʿān in the mosque while I was a witness. When they finished, he said: “I have lied against her, O Messenger of Allah, if I keep her,” so he divorced her three times before the Messenger of Allah ﷺ commanded him when they had finished the liʿān. Thus he separated from her in the presence of the Prophet ﷺ, who said: “That is the separation between every two who perform liʿān.”","Ibn Jurayj said, from Ibn Shihab, from Sahl ibn Saʿd al-Saʿidi in this hadith, that the Prophet ﷺ said: “If she brings him forth reddish and short, as though he were a small lizard, then I only see that she has spoken the truth and he has lied against her. But if she brings him forth black, large-eyed, and with fleshy buttocks, then I only see that he has spoken truthfully against her.” Then she gave birth in the manner that was disliked of those two descriptions."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5309},{"key":"muslim","label":"مسلم","number":3}]},{"num":6624,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص عن رسول الله ﷺ : أن رجلا من الأنصار من بني زريق قذف امرأته، فأتى رسول الله ﷺ فردّدَ ذلك أربع مرات على رسول الله ﷺ فأنزل الله آية الملاعنة، فقال رسول الله ﷺ: (( أين السائل، إنه قد نزل من الله أمر عظيم، فأبى الرجل إلا أن يلاعنها، وأبتْ إلا أن تدرأ عن نفسها العذاب، فتلاعنا، فقال رسول الله ﷺ: (( إما هي تجيء به أصيفر أخينس منشول العظام فهو للملاعن، وإما تجيء به أسود كالجمل الأورق فهو لغيره))، فجاءتْ به أسود كالجمل الأورق فدعا به رسول الله ﷺ فجعله لعصبة أمه، وقال: (( لو ما الأيمان التي مضتْ لكان لي فيه كذا وكذا))"],"takhrij":"حسن: رواه النسائي (٦٣٢٨) والطحاوي في شرح المشكل (٥١٤٦)، والدار قطني (٣٧٠٣).","grade":"حسن","chapter_ar":"باب لا تُرجم المرأةُ ولو كانتِ الأمارةُ تدل على كذبها في اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasa’i (6328), al-Tahawi in Sharh al-Mushkil (5146), and al-Daraqutni (3703).","chapter_en":"Chapter on the Woman Not Being Stoned Even If the Indications Suggest She Lied in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr ibn al-ʿAs reported from the Messenger of Allah ﷺ that a man from the Ansar of Banu Zurayq accused his wife, so he came to the Messenger of Allah ﷺ and repeated that four times to him. Then Allah revealed the verse of liʿān. The Messenger of Allah ﷺ said: “Where is the questioner? A tremendous matter has indeed come down from Allah.” But the man insisted on performing liʿān against her, and she insisted on warding off the punishment from herself, so they performed liʿān. Then the Messenger of Allah ﷺ said: “Either she will bring him forth yellowish, with a small nose, thin-boned, and then he belongs to the man who performed liʿān, or she will bring him forth black like a gray camel, and then he belongs to someone else.” Then she gave birth to him black like a gray camel, so the Messenger of Allah ﷺ summoned him and assigned him to his mother’s relatives, and said: “Were it not for the oaths that have already passed, I would have had such-and-such to do regarding him.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":6328},{"key":"الطحاوی/شرح_المشکل","label":"الطحاوي في شرح المشكل","number":5146},{"key":"الدار_قطنی","label":"الدار قطني","number":3703},{"key":"sh9771","label":"سنن الدارقطني","number":3703,"n":3715}]},{"num":6625,"demo":false,"sanad":"","matn":["عن عباس بن سهل، عن أبيه، أن النبي ﷺ قال لعاصم بن عدي: (( أمسكِ المرأةَ عندك حتى تلدَ))"],"takhrij":"حسن: رواه أبو داود (٢٢٤٦).","grade":"حسن","chapter_ar":"باب السكنى للحامل الملاعنة","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2246).","chapter_en":"Chapter on Housing for the Pregnant Woman Involved in Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["ʿAbbas ibn Sahl, from his father, reported that the Prophet ﷺ said to ʿAsim ibn ʿAdi: “Keep the woman with you until she gives birth.”"]},"buhuth":{"ar":["والتحقيق في هذه المسألة إنْ كان اللعانُ على الحمل، فلا نفقةً ولا سكنى لها، وإنْ كان اللعان على غير","الحمل فللحامل النفقةُ والسكنى؛ لأن الحمل له، فعليه نفقته، فأشبهت المطلقة البائن الحامل."],"en":["The correct view in this matter is that if the liʿān concerns the pregnancy, then there is no maintenance or housing for her. But if the liʿān concerns something other than the pregnancy, then the pregnant woman has maintenance and housing, because the pregnancy belongs to him, so its maintenance is upon him. Thus she is like a pregnant woman divorced with an irrevocable divorce."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2246}]},{"num":6626,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: لم يفرّق المصعب بين المتلاعنين قال سعيد: ذكر ذلك لابن","عمر فقال: فرّق رسول الله ﷺ بين أخوي بني العجلان."],"takhrij":"صحيح: رواه مسلم (٧:١٤٩٣)، والنسائي (٣٤٧٤).","grade":"صحيح","chapter_ar":"باب تفريق الإمام بين المتلاعنين، وأنهما لا يجتمعان أبدا","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1493/7) and al-Nasa’i (3474).","chapter_en":"Chapter on the Ruler Separating the Two Who Perform Liʿān, and That They Never Reunite","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Saʿid ibn Jubayr said: Musʿab did not separate between the two who had performed liʿān. Saʿid said: That was mentioned to Ibn ʿUmar, so he said: The Messenger of Allah ﷺ separated the two brothers from Banu al-ʿAjlan."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":7},{"key":"nasai","label":"النسائي","number":3474}]},{"num":6627,"demo":false,"sanad":"","matn":["عن سهل بن سعد قال: فطلّقها ثلاث تطليقات عند رسول الله ﷺ فأنفذه رسولُ الله ﷺ.","وكان ما صُنع عند النبي ﷺ سنة.","قال سهل: حضرت هذا عند رسول الله ﷺ فمضت السنّةُ بعد في المتلاعنين أن يفرق بينهما، ثم","لا يجتمعان أبداً."],"takhrij":"حسن: رواه أبو داود (٢٢٥٠)، ومن طريقه البيهقي (٤٠١/٧).","grade":"حسن","chapter_ar":"باب من قال: يقع التفريق باللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2250), and through him by al-Bayhaqi (7/401).","chapter_en":"Chapter on Those Who Said That Separation Takes Place by Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Sahl ibn Saʿd said: He divorced her with three divorces in the presence of the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ let it stand. What was done in the presence of the Prophet ﷺ became established practice.","Sahl said: I was present for this with the Messenger of Allah ﷺ, and thereafter the established practice among those who perform liʿān was that they are separated and then never reunite."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2250},{"key":"ومن_طریقہ_البیہقی","label":"ومن طريقه البيهقي","number":401},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15322,"n":15473}]},{"num":6628,"demo":false,"sanad":"","matn":["عن سهل بن سعد أن رسول الله ﷺ لاعن بين عويمر وبين امرأته. فقال عويمر: إنْ انطلقتُ بها يا رسول الله ﷺ قد كذبتُ عليها. قال: ففارَقَها قبل أن يأمره رسول الله ﷺ، فصارت سنة المتلاعنين"],"takhrij":"صحيح: رواه الإمام أحمد (٢٢٨٣٠).","grade":"صحيح","chapter_ar":"باب من قال: يقع التفريق باللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (22830).","chapter_en":"Chapter on Those Who Said That Separation Takes Place by Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Sahl ibn Saʿd reported that the Messenger of Allah ﷺ made liʿān take place between ʿUwaymir and his wife. Then ʿUwaymir said: “If I go away with her, O Messenger of Allah, then I have lied against her.” He said: So he separated from her before the Messenger of Allah ﷺ commanded him, and that became the established practice for those who perform liʿān."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":22830},{"key":"ahmad","label":"مسند الإمام أحمد","number":22830,"n":22830}]},{"num":6629,"demo":false,"sanad":"","matn":["عن ابن عمر، أن رجلًا لاعن امرأته في زمان رسول الله ﷺ وانتفى من ولدها، ففرّق","رسول الله ﷺ بينهما، وألحق الولد بالمرأة."],"takhrij":"متفق عليه: رواه مالك (٣٥) والبخاري (٥٣١٥)، ومسلم (٨:١٤٩٤).","grade":"متفق عليه","chapter_ar":"باب إلحاق الولد بأمه في الملاعنة، وأنه يُدعى بها","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (35), al-Bukhari (5315), and Muslim (1494/8).","chapter_en":"Chapter on Attributing the Child to His Mother in Liʿān, and That He Is Called by Her Name","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar reported that a man performed liʿān against his wife in the time of the Messenger of Allah ﷺ and disowned her child. So the Messenger of Allah ﷺ separated them and attributed the child to the woman."]},"buhuth":{"ar":["قوله: (( وانتفل)) أي تبرأ. وفي البخاري: (( فانتفى))."],"en":["His saying, “wantaffala,” means that he disowned him. In al-Bukhari it appears as: “fantafā.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":35},{"key":"bukhari","label":"البخاري","number":5315},{"key":"muslim","label":"مسلم","number":8}]},{"num":6630,"demo":false,"sanad":"","matn":["عن سهل بن سعد أن رجلاً أتى النبي ﷺ فذكر الحديث وقال فيه: وكانت حاملاً.","فأنكر حملها، وكان ابنها يُدعى إليها."],"takhrij":"صحيح: رواه البخاري (٤٧٤٦) ومسلم (٢/١٤٩٢). وفي سنن أبي داود (٢٢٤٧) قال سهل:","grade":"صحيح","chapter_ar":"باب إلحاق الولد بأمه في الملاعنة، وأنه يُدعى بها","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4746) and Muslim (1492/2). In Sunan Abi Dawud (2247), Sahl said: I was present at her liʿān before the Messenger of Allah ﷺ when I was fifteen years old, and he narrated the hadith. In it he said: Then she left while pregnant, and the child used to be called by his mother.","chapter_en":"Chapter on Attributing the Child to His Mother in Liʿān, and That He Is Called by Her Name","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a man came to the Prophet ﷺ, and he mentioned the hadith, saying in it: She was pregnant, and he denied her pregnancy, and her son used to be attributed to her."]},"buhuth":{"ar":["حضرتُ لعانها عند رسول الله ﷺ وأنا ابن خمس عشرة سنة، وساق الحديث. قال فيه: ثم خرجتْ حاملاً.","فكان الولد يُدعَى إلى أمه."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4746},{"key":"muslim","label":"مسلم","number":2},{"key":"وفی_سنن_ابی_داود","label":". وفي سنن أبي داود","number":2247}]},{"num":6631,"demo":false,"sanad":"","matn":["عن ابن عباس:","أن هلال بن أمية قذف امرأته عند النبي ﷺ بشريك بن سحماء.","فقال له النبي ﷺ:","«الْبَيِّنَةُ أَوْ حَدٌّ فِي ظَهْرِكَ».","فقال:","يا رسول الله، إذا رأى أحدنا على امرأته رجلًا، ينطلق يلتمس البينة؟","فجعل النبي ﷺ يقول:","«الْبَيِّنَةُ أَوْ حَدٌّ فِي ظَهْرِكَ».","فقال هلال:","والذي بعثك بالحق إني لصادق، ولينزلن الله ما يبرئ ظهري من الحد.","فنزل جبريل، فأنزل عليه:","﴿وَالَّذِينَ يَرْمُونَ أَزْوَاجَهُمْ﴾","[النور: ٦]","حتى بلغ:","﴿إِنْ كَانَ مِنَ الصَّادِقِينَ﴾","[النور: ٩]"],"takhrij":"صحيح: رواه البخاري (٤٧٤٧).","grade":"صحيح","chapter_ar":"باب أن الزوج يُحَدّ إذا كذّب نفسه وتراجع عن اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4747).","chapter_en":"Chapter on the Husband Being Punished If He Declares Himself a Liar and Retracts from Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās reported:","Hilāl ibn Umayyah accused his wife before the Prophet ﷺ of committing adultery with Sharīk ibn Saḥmāʾ.","The Prophet ﷺ said to him:","“Produce evidence, otherwise the prescribed punishment will be upon your back.”","He said:","“O Messenger of Allah, if one of us sees a man with his wife, is he expected to go and search for evidence?”","The Prophet ﷺ continued saying:","“Evidence, otherwise the prescribed punishment will be upon your back.”","Hilāl said:","“By the One who sent you with the truth, I am certainly truthful, and Allah will surely reveal something that will clear my back from the prescribed punishment.”","Then Jibrīl descended and revealed:","“And those who accuse their wives…”","[al-Nūr: 6]","until he reached:","“…if he is among the truthful.”","[al-Nūr: 9]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4747}]},{"num":6632,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: جاء رجل من بني فزارة إلى النبي ﷺ فقال: إن امرأتي ولدتْ غلاماً أسودَ. فقال النبي ﷺ: (( هل لك من إبل؟ )) قال: نعم. قال: (( فما ألوانُها؟ )) قال: حمر. قال: ((هل فيها من أورق؟ )) قال: إن فيها لورقاً. قال: فأنى أتاها ذلك؟ قال: عسى أن يكون نزعه عرق، قال:","(( وهذا عسى أن يكون نزعه عرق)).","وزاد في رواية: ( ولم يرخّص له في الانتفاء منه))."],"takhrij":"صحيح: رواه البخاري (٥٣٠٥)، ومسلم (١٥٠٠). والسياق لمسلم.","grade":"صحيح","chapter_ar":"باب أن الزوج يُحَدّ إذا كذّب نفسه وتراجع عن اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5305) and Muslim (1500). The wording is that of Muslim.","chapter_en":"Chapter on the Husband Being Punished If He Declares Himself a Liar and Retracts from Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: A man from Banu Fazarah came to the Prophet ﷺ and said: “My wife has given birth to a black boy.” The Prophet ﷺ said: “Do you have camels?” He said: “Yes.” He said: “What colors are they?” He said: “Red.” He said: “Are there any grayish ones among them?” He said: “Indeed among them are some grayish ones.” He said: “How did that come about?” He said: “Perhaps a trait drew it out from ancestry.” He said: “And this too may have been drawn out by ancestry.”","And in one narration there is the addition: “And he did not permit him to disown him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5305},{"key":"muslim","label":"مسلم","number":1500}]},{"num":6633,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: بينما نحن عند رسول الله ﷺ قام رجل فقال: يا رسول الله، إني وُلِد لي غلام أسود. فقال رسول الله ﷺ: «فأنّى كان ذلك؟» قال: ما أدري. قال: «فهل لك من إبل؟» قال: نعم. قال: «فما ألوانها؟» قال: حمر. قال: «فهل فيها جمل أورق؟» قال: فيها إبل ورق. قال: «فأنّى كان ذلك؟» قال: ما أدري يا رسول الله، إلا أن يكون نزعه عِرق. قال: «وهذا لعله نزعه عِرق». فمن أجله قضى رسول الله ﷺ: «هذا لا يجوز لرجل أن ينتفي من ولد وُلِد على فراشه إلا أن يزعم أنه رأى فاحشة»."],"takhrij":"صحيح: رواه النسائي (٣٤٨٠).","grade":"صحيح","chapter_ar":"باب أن الزوج يُحَدّ إذا كذّب نفسه وتراجع عن اللعان","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3480).","chapter_en":"Chapter on the Husband Being Punished If He Declares Himself a Liar and Retracts from Liʿān","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah said: While we were with the Messenger of Allah ﷺ, a man stood up and said: “O Messenger of Allah, a black boy has been born to me.” The Messenger of Allah ﷺ said: “How did that happen?” He said: “I do not know.” He said: “Do you have camels?” He said: “Yes.” He said: “What colors are they?” He said: “Red.” He said: “Are there any grayish camels among them?” He said: “There are grayish camels among them.” He said: “How did that happen?” He said: “I do not know, O Messenger of Allah, except that perhaps a hereditary strain brought it out.” He said: “And perhaps this one too was brought out by a hereditary strain.” Because of this, the Messenger of Allah ﷺ ruled: “It is not permissible for a man to disown a child born on his marriage bed unless he claims that he witnessed an indecency.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3480}]},{"num":6634,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن النبي ﷺ قال: (( كفرٌ بامرئ ادعاءُ نسب لا يعرفه، أو جحدُه وإن دقّ )."],"takhrij":"حسن: رواه ابن ماجه (٢٧٤٤)، وأحمد (٧٠١٩).","grade":"حسن","chapter_ar":"باب التغليظ في الانتفاءِ من الولد","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2744) and Ahmad (7019).","chapter_en":"Chapter on the Severe Warning Regarding Disowning One’s Child","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, reported that the Prophet ﷺ said: “It is an act of disbelief for a person to claim a lineage he does not know, or to deny it, even if slight.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2744},{"key":"ahmad","label":"مسند الإمام أحمد","number":7019,"n":7019}]},{"num":6635,"demo":false,"sanad":"","matn":["عن أبي هريرة أنه سمع رسول الله ﷺ يقول حين نزلتْ آية الملاعنة: (( أيما امرأة أدْخلتْ على قومٍ من ليس منهم، فليستْ من الله في شيء، ولن يُدخلها الله جنّتَه، وأيما رجلٍ جحَدَ ولدَه وهو ينظر إليه احتجب الله تعالى منه، وفَضَحه على رُؤوسِ الأولين والآخرين))."],"takhrij":"حسن: رواه أبو داود (٢٢٦٣) والنسائي (٣٤٨١) وصحّحه ابن حبان (٤١٠٨) وابن ماجه (٢٧٤٣).","grade":"حسن","chapter_ar":"باب التغليظ في الانتفاءِ من الولد","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2263), al-Nasa’i (3481), authenticated by Ibn Hibban (4108), and Ibn Majah (2743).","chapter_en":"Chapter on the Severe Warning Regarding Disowning One’s Child","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah said that he heard the Messenger of Allah ﷺ say when the verse of liʿān was revealed: “Any woman who introduces into a people one who is not from them, she has nothing to do with Allah, and Allah will not admit her into His Paradise. And any man who denies his child while he is looking at him, Allah the Exalted will screen Himself from him and disgrace him before the first and the last.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2263},{"key":"nasai","label":"النسائي","number":3481},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4108},{"key":"ibnmajah","label":"ابن ماجه","number":2743},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2917,"n":2914}]},{"num":6636,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول الله ﷺ ( من انتفى من ولده ليفضحه في الدنيا، فَضَحه اللهُ يوم القيامة على رؤوسِ الأشهاد، قصاص بقصاص)"],"takhrij":"حسن: رواه الإمام أحمد (٤٧٩٥) والطبراني في الكبير (٤٠٠ /١٢).","grade":"حسن","chapter_ar":"باب التغليظ في الانتفاءِ من الولد","chapter_ur":"","part_ar":"كتاب اللعان","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (4795) and al-Tabarani in al-Kabir (12/400).","chapter_en":"Chapter on the Severe Warning Regarding Disowning One’s Child","part_en":"The Book of Liʿān","group_ar":"","group_en":"","part_no":27,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “Whoever disowns his child in order to disgrace him in this world, Allah will disgrace him on the Day of Resurrection before the heads of all witnesses, requital for requital.”"]},"buhuth":{"ar":["وقوله: (( قصاص بقصاص)): أي يؤخذ منه قصاص في الآخرة بمقابل ما فعله بولده من انتفاء نسبه","وفضيحته في الدنيا."],"en":["His saying, “requital for requital,” means that retribution will be taken from him in the Hereafter corresponding to what he did to his child by denying his lineage and disgracing him in this world."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":4795},{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":400},{"key":"ahmad","label":"مسند الإمام أحمد","number":4795,"n":4795}]},{"num":6637,"demo":false,"sanad":"","matn":["عن عائشة قالت: الحمد لله الذي وسع سمعه الأصوات، لقد جاءت خولة بنت ثعلبة إلى رسول الله ﷺ تشكو زوجها، فكان يخفى عليَّ كلامهما، فأنزل الله عز وجل: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ [المجادلة: ١]."],"takhrij":"صحيح: رواه النسائي (٣٤٦٠) وابن ماجه (٢٠٦٣) (١٨٨) والإمام أحمد ( ٢٤١٩٥) والحاكم","grade":"صحيح","chapter_ar":"باب ما جاء في الظهار","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3460), Ibn Majah (2063), Ahmad (24195), and al-Hakim (2/481).","chapter_en":"Chapter on What Has Been Reported Regarding Zihār","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah said: Praise be to Allah whose hearing encompasses all voices. Khawlah bint Thaʿlabah came to the Messenger of Allah ﷺ complaining about her husband, and some of their conversation was hidden from me. Then Allah, Mighty and Exalted, revealed: “Allah has certainly heard the statement of the woman who disputes with you concerning her husband and complains to Allah, and Allah hears your exchange. Indeed, Allah is All-Hearing, All-Seeing.” [Surat al-Mujādilah: 1]"]},"buhuth":{"ar":["(٤٨١/٢).","وزاد الحاكم في أوله من كلام المجادلة الذي سمعته عائشة وهو قولها: “يا رسول الله! أكلَ شَبابي،","ونشرتُ له بطني، حتى إذا كبرتْ سِنّي وانقطع له ولدي، ظاهرَ مني، اللهم إني أشكو إليك”."],"en":["Al-Hakim added at the beginning part of the woman’s words that ʿA’ishah heard: “O Messenger of Allah, he consumed my youth and I bore children for him. Then when I became old and my childbearing ended for him, he pronounced zihār against me. O Allah, I complain to You.”"]},"intro":{"ar":["قال الله تعالى: ( وَٱلَّذِينَ يُظَهِرُونَ مِن نِسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحْرِيرُ رَقَبَةٍ مِن قَبْلِ أَن بَتَمَاسَّا) [سورة المجادلة: ٣]"],"en":["Allah the Exalted said: “Those who pronounce zihār against their wives and then go back on what they said must free a slave before the two touch one another.” [Surat al-Mujādilah: 3]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3460},{"key":"ibnmajah","label":"ابن ماجه","number":2063},{"key":"الامام_احمد","label":"الإمام أحمد","number":24195},{"key":"ahmad","label":"مسند الإمام أحمد","number":24195,"n":24195}]},{"num":6638,"demo":false,"sanad":"","matn":["عن عائشة أن جميلة كانت امرأة أوس بن الصامت، وكان أوس امرءا به لَممّ، فإذا اشتدَّ لممُه ظاهرَ من امرأته، فأنزل الله فيه كفارة الظهار."],"takhrij":"صحيح: رواه أبو داود (٢٢٢٠) والحاكم (٤٨١/٢) والبيهقي (٣٨٢/٧).","grade":"صحيح","chapter_ar":"باب ما جاء في الظهار","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2220), al-Hakim (2/481), and al-Bayhaqi (7/382).","chapter_en":"Chapter on What Has Been Reported Regarding Zihār","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah said that Jamilah was the wife of Aws ibn al-Samit, and Aws was a man who had a mental disturbance. Whenever his condition worsened, he would pronounce zihār against his wife. Then Allah revealed regarding him the expiation for zihār."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2220},{"key":"البیہقی","label":"البيهقي","number":382},{"key":"hakim","label":"المستدرك على الصحيحين","number":3792,"n":3779},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15244,"n":15395}]},{"num":6639,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس: أن رجلا ظاهرَ من امرأته، فغَشِيَها قبل أن يُكفِّر، فأتى النبي ﷺ، فذكر ذلك، فقال: (( ما حملك على ذلك؟) فقال: يا رسول الله! رأيت بياض حِجْلَيْها في القمر، فلم أملك نفسي أن وقعتُ عليها، فضحك النبي ﷺ وأمره ألا يقرُبَها حتى يُكفَّرَ ."],"takhrij":"حسن: رواه الترمذي (١١٩٩) وابن ماجه (٢٠٦٥) والنسائي (٣٤٥٧) وأبو داود (٢٢٢٣،٢٢٢٥).","grade":"حسن","chapter_ar":"باب المظاهر يجامع قبل أن يكفر","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1199), Ibn Majah (2065), al-Nasa’i (3457), and Abu Dawud (2223, 2225).","chapter_en":"Chapter on the One Who Pronounces Zihār Having Intercourse Before Making Expiation","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas reported that a man pronounced zihār against his wife, then had intercourse with her before making expiation. He came to the Prophet ﷺ and mentioned that, and he said: “What led you to do that?” He said: “O Messenger of Allah, I saw the whiteness of her anklets in the moonlight, and I could not control myself, so I fell upon her.” The Prophet ﷺ laughed and ordered him not to go near her until he had made expiation."]},"buhuth":{"ar":["وقال الترمذي: “حسن غريب صحيح”."],"en":["Al-Tirmidhi said: “Hasan, gharib, sahih.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1199},{"key":"ibnmajah","label":"ابن ماجه","number":2065},{"key":"nasai","label":"النسائي","number":3457},{"key":"abudawud","label":"أبو داود","number":2223}]},{"num":6640,"demo":false,"sanad":"","matn":["عن خولة بنت ثعلبة قالت: فيَّ والله، وفي أوس بن صامت أنزل الله عز وجل صدر سورة المجادلة. قالت: كنت عنده، وكان شيخاً كبيراً قد ساء خلقه وضجر. قالت: فدخل عليَّ يوماً، فراجعتُه بشيء، فغضب فقال: أنتِ عليَّ كظهر أمي. قالت: ثم خرج فجلس في نادي قومه ساعة،","ثم دخل عليَّ فإذا هو يريدني على نفسي. قالت: فقلت: كلا، والذي نفس خويلة بيده، لا تخلص إليَّ وقد قلت ما قلت، حتى يحكم الله ورسوله فينا بحكمه. قالت: فواثبني وامتنعت منه، فغلبته بما تغلب به المرأة الشيخ الضعيف، فألقيته عني. قالت: ثم خرجت إلى بعض جاراتي فاستعرت منها ثيابها، ثم خرجت حتى جئت رسول الله ﷺ، فجلست بين يديه، فذكرت له ما لقيت منه، فجعلت أشكو إليه ما ألقى من سوء خلقه. قالت: فجعل رسول الله ﷺ يقول: «يا خويلة، ابن عمك شيخ كبير، فاتقي الله فيه». قالت: فوالله ما برحت حتى نزل في القرآن، فتغشى رسول الله ﷺ ما كان يتغشاه، ثم سُرّي عنه، فقال لي: «يا خويلة، قد أنزل الله فيك وفي صاحبك». ثم قرأ عليَّ: ﴿قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ وَاللَّهُ يَسْمَعُ تَحَاوُرَكُمَا إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ إلى قوله: ﴿وَلِلْكَافِرِينَ عَذَابٌ أَلِيمٌ﴾ [المجادلة: ١-٤].","فقال لي رسول الله ﷺ: «مُريه فليعتق رقبة». قالت: فقلت: والله يا رسول الله، ما عنده ما يعتق. قال: «فليصم شهرين متتابعين». قالت: فقلت: والله يا رسول الله، إنه شيخ كبير ما به من صيام. قال: «فليطعم ستين مسكيناً وسقاً من تمر». قالت: فقلت: والله يا رسول الله، ما ذاك عنده. قالت: فقال رسول الله ﷺ: «فإنا سنعينه بعَرَق من تمر». قالت: قلت: وأنا يا رسول الله سأعينه بعَرَق آخر. قال: «قد أصبت وأحسنت، فاذهبي فتصدقي عنه، ثم استوصي بابن عمك خيراً». قالت: ففعلت.","قال عبد الله: قال أبي: قال سعد: العَرَق: الصن."],"takhrij":"حسن: رواه أحمد (٢٧٣١٩) واللفظ له، وأبو داود (٢٢١٤،٢٢١٥) وصحّحه ابن حبان (٤٢٧٩).","grade":"حسن","chapter_ar":"باب المظاهر يجامع قبل أن يكفر","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27319), and this is his wording, Abu Dawud (2214, 2215), and authenticated by Ibn Hibban (4279).","chapter_en":"Chapter on the One Who Pronounces Zihār Having Intercourse Before Making Expiation","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Khawlah bint Thaʿlabah said: By Allah, the opening of Surat al-Mujādilah was revealed concerning me and Aws ibn Samit. She said: I was with him, and he was an old man whose character had become bad and who had become irritable. One day he came in to me, and I answered him back about something, so he became angry and said: “You are to me like my mother’s back.” Then he went out and sat for a while in the gathering place of his people. Then he came back to me and wanted me physically. I said: No, by the One in whose hand is the soul of Khuwaylah, you shall not have access to me after what you have said, until Allah and His Messenger judge between us with His judgment. She said: He tried to force himself on me, and I resisted him, and I overcame him in the way a woman overcomes a weak old man, and I pushed him away from me. Then I went to one of my neighbors and borrowed her clothes, then went until I came to the Messenger of Allah ﷺ and sat before him. I mentioned to him what I had suffered from him, and I kept complaining to him about his bad character. The Messenger of Allah ﷺ kept saying: “O Khawlah, your cousin is an old man, so fear Allah regarding him.” She said: By Allah, I had not moved when the Qur’an was revealed. The Messenger of Allah ﷺ was overtaken by what used to overtake him, then it was lifted from him, and he said to me: “O Khawlah, Allah has revealed concerning you and your companion.” Then he recited to me: “Allah has certainly heard the statement of the woman who disputes with you concerning her husband…” up to His saying: “And for the disbelievers is a painful punishment.” [al-Mujādilah: 1–4]","Then the Messenger of Allah ﷺ said to me: “Command him to free a slave.” She said: I said, “By Allah, O Messenger of Allah, he has nothing with which to free a slave.” He said: “Then let him fast two consecutive months.” She said: I said, “By Allah, O Messenger of Allah, he is an old man and unable to fast.” He said: “Then let him feed sixty poor people a wasq of dates.” She said: I said, “By Allah, O Messenger of Allah, he does not have that.” She said: Then the Messenger of Allah ﷺ said: “We will help him with a basket of dates.” I said: “And I, O Messenger of Allah, will help him with another basket.” He said: “You have done right and done well. Go, then give charity on his behalf, and advise your cousin well.” She said: So I did.","ʿAbdullah said: My father said: Saʿd said: al-ʿaraq means al-ṣann (a large basket)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2214},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4279},{"key":"ahmad","label":"مسند الإمام أحمد","number":27319,"n":27319},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":7191,"n":7191}]},{"num":6641,"demo":false,"sanad":"","matn":["عن سلمة بن صخر البياضي قال: كنت امرأً أستكثر من النساء، لا أرى رجلًا كان يصيب من ذلك ما أصيب، فلما دخل رمضان ظاهرت من امرأتي حتى ينسلخ رمضان، فبينما هي تحدثني ذات ليلة انكشف لي منها شيء، فوثبت عليها فواقعتها. فلما أصبحت غدوت على قومي، فأخبرتهم خبري، وقلت لهم: سلوا لي رسول الله ﷺ. فقالوا: ما كنا نفعل، إذًا ينزل الله فينا كتابًا، أو يكون فينا من رسول الله ﷺ قول، فيبقى علينا عاره، ولكن سوف نسلمك بجريرتك، اذهب أنت فاذكر شأنك لرسول الله ﷺ. قال: فخرجت حتى جئته فأخبرته الخبر، فقال رسول الله ﷺ: «أنت بذاك؟» قلت: أنا بذاك، وها أنا يا رسول الله صابر لحكم الله علي. قال: «فأعتق رقبة». قال:","قلت: والذي بعثك بالحق، ما أصبحت أملك إلا رقبتي هذه. قال: «فصم شهرين متتابعين». قلت:","يا رسول الله، وهل دخل علي ما دخل من البلاء إلا بالصوم؟ قال: «فتصدق أو أطعم ستين مسكينًا». قال: قلت: والذي بعثك بالحق، لقد بتنا ليلتنا هذه ما لنا عشاء. قال: «فاذهب إلى صاحب","صدقة بني رُزيق فقل له، فليدفعها إليك، وأطعِمْ ستين مسكيناً. وانتفِعْ ببقيتها ))."],"takhrij":"حسن: رواه أبو داود (٢٢١٣) وابن ماجه (٢٠٦٢) والترمذي (٣٢٩٩) وحسّنه، وصحّحه ابن خزيمة","grade":"حسن","chapter_ar":"باب المظاهر يجامع قبل أن يكفر","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2213), Ibn Majah (2062), al-Tirmidhi (3299), who graded it hasan, and authenticated by Ibn Khuzaymah (2378).","chapter_en":"Chapter on the One Who Pronounces Zihār Having Intercourse Before Making Expiation","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Salamah ibn Sakhr al-Bayadi said: I was a man very given to women; I do not think any man had as much desire in that regard as I had. When Ramadan entered, I pronounced zihār against my wife until Ramadan was over. Then one night while she was speaking to me, something of her became uncovered to me, so I sprang upon her and had intercourse with her. When morning came, I went early to my people and informed them of my situation, and I said to them: Ask the Messenger of Allah ﷺ for me. They said: We will not do that, lest Allah reveal something concerning us, or a statement about us come from the Messenger of Allah ﷺ and its disgrace remain upon us. Rather, we will leave you to bear your own offense. Go yourself and mention your case to the Messenger of Allah ﷺ. So I went until I came to him and informed him of the matter. The Messenger of Allah ﷺ said: “Was it you who did that?” I said: It was I, and here I am, O Messenger of Allah, content to bear Allah’s judgment upon me. He said: “Then free a slave.” I said: By the One who sent you with the truth, I own nothing this morning except this neck of mine. He said: “Then fast two consecutive months.” I said: O Messenger of Allah, was it not from fasting that what befell me befell me? He said: “Then give charity or feed sixty poor people.” I said: By the One who sent you with the truth, we spent this night without any supper. He said: “Go to the custodian of the charity of Banu Zurayq and tell him to give it to you. Feed sixty poor people, and benefit from what remains.”"]},"buhuth":{"ar":["(٢٣٧٨)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2213},{"key":"ibnmajah","label":"ابن ماجه","number":2062},{"key":"tirmidhi","label":"الترمذي","number":3299}]},{"num":6642,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول الله ﷺ (( لم يكذب إبراهيم عليه السلام إلا ثلاث كذبات، ثنتين منهن في ذات الله عز وجل. وقوله لسارة: أختي))."],"takhrij":"متفق عليه: رواه البخاري (٣٣٥٨) ومسلم (٢٣٧١).","grade":"متفق عليه","chapter_ar":"باب ليس من الظهار أن يقول الرجل لامرأته : يا أختي","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (3358) and Muslim (2371).","chapter_en":"Chapter on It Not Being Zihār for a Man to Say to His Wife: “My Sister”","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Ibrahim, peace be upon him, did not utter an untruth except three times, two of them for the sake of Allah, Mighty and Exalted. And one of them was his statement to Sarah: ‘She is my sister.’”"]},"buhuth":{"ar":["وفيه من الفقه: أن من قال لزوجته: أنتِ أختي ولم ينو الظهار، وإنما نوى الكرامة والتوقير أو التورية فهو ليس بظهار، وأما إذا نوى الظهار فهو مثل قوله: أنتِ كأمي.","وأما كذب إبراهيم فيحمل على التورية. وقد أشكل على الناس تسميتها كذبة لكون المتكلم إنما أراد باللفظ المعنى الذي قصده، فكيف يكون كذبا. والتحقيق في ذلك أنها كذب بالنسبة على إفهام المخاطب، لا بالنسبة إلى غاية المتكلم. فإن الكلام له نسبتان: نسبة إلى المتكلم، ونسبة إلى المخاطب، فلما أراد الموري أن يفهمَ المخاطبُ خلاف ما قصده بلفظه أطلق الكذب عليه بهذا الاعتبار، وإن كان المتكلم صادقاً باعتبار قصده ومراده” قاله الحافظ ابن القيم في “تهذيب السنن” (١٣٧ /٣)"],"en":["The legal understanding is that whoever says to his wife, “You are my sister,” without intending zihār, but rather intending honor, respect, or indirect speech, then it is not zihār. But if he intends zihār, then it is like his saying: “You are like my mother.”","As for Ibrahim’s “untruth,” it is understood as indirect speech. People found it difficult that it was called a lie although the speaker intended by the wording the meaning he meant, so how could it be a lie? The correct understanding is that it was a lie in relation to what the listener understood, not in relation to the speaker’s intended meaning. Speech has two relations: one to the speaker and one to the listener. So when the one speaking indirectly intended the listener to understand something other than what he meant by his wording, it was called a lie from that perspective, even though the speaker was truthful in terms of his intention and meaning. This was stated by al-Hafiz Ibn al-Qayyim in Tahdhib al-Sunan (3/137)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3358},{"key":"muslim","label":"مسلم","number":2371}]},{"num":6643,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر كان يقول في الإيلاء الذي سمى الله: ( لا يحلُّ لأحد بعد الأجل إلا أن يُمْسِك بالمعروف، أو يعزم الطلاق كما أمرَ اللهُ عز وجل)."],"takhrij":"صحيح: رواه البخاري ( ٥٢٩٠).","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5290).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar used to say regarding the īlāʾ that Allah mentioned: “It is not lawful for anyone after the period has ended except that he either keep her honorably or resolve upon divorce as Allah, Mighty and Exalted, has commanded.”"]},"buhuth":{"ar":["والإيلاء: الحلف، جمعه ألايا، وهو أن يحلف ألا يدخل على أهله شهراً فجعل الله المدة القصوى أربعة أشهر، وفي خلال هذه المدة إما أن يرجع عن حلفه ويُكفر، أو يطلق. فإنه لا يجوز له أن يجعل المرأة معلقة، لا يُجامعها ولا يُطلقها. فإن رفض الأمرين فإن القاضي يُطلق عليه، أو يفسخ"],"en":["Īlāʾ means swearing an oath, and its plural is alayā. It is for a man to swear that he will not go in to his wife. Allah made the maximum period four months. During this period, he must either go back on his oath and make expiation, or divorce. It is not permissible for him to leave the woman suspended, neither having intercourse with her nor divorcing her. If he refuses both, then the judge divorces on his behalf or annuls the marriage."]},"intro":{"ar":["قال الله تعالى: ( لَِّذِينَ يُؤْلُونَ مِن نسَآبِهِمْ تَرْبُصُ أَرْبَعَةِ أَشْهُرِ فَإِن فَآءُو فَإِنَّ اللَّهَ غَفُورٌ زَحِيمٌ (٦) وَانْ عَزَمُوا الطَّلَقَ فَإِنَّ للَّهَ سَمِيعٌ عَلِيمٌ } [البقرة: ٢٢٧ - ٢٢٦ ]"],"en":["Allah the Exalted said: “For those who swear abstinence from their wives is a waiting period of four months. But if they return, then indeed Allah is Forgiving, Merciful. And if they resolve upon divorce, then indeed Allah is All-Hearing, All-Knowing.” [al-Baqarah: 226–227]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5290}]},{"num":6644,"demo":false,"sanad":"","matn":["عن ابن عباس قال: لم أزل حريصا على أن أسأل عمر بن الخطاب عن المرأتين من أزواج النبي ﷺ اللتين قال الله تعالى: ( إِن تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ) [التحريم: ٤ ] حتى حجَّ وحججتُ معه، وعدل وعدلتُ معه بإداوة، فتبرزَ ثم جاء فسكبتُ على يديه منها فتوضاً، فقلت له: يا","أمير المؤمنين! من المرأتان من أزواج النبي ﷺ اللتان قال الله تعالى: (إِن تَتُوبَا إلى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ) [التحريم: ٤ ]؟ قال: واعجبا لك يا ابن عباس، هما عائشة وحفصة، ثم استقبل عمر الحديث يسوقه قال: كنت أنا وجار لي من الأنصار في بني أمية بن زيد وهم من عوالي المدينة، وكنا نتناوب النزول على النبي ﷺ، فينزل يوما وأنزل يوما، فإذا نزلت جئته بما حدث من خبر ذلك اليوم من الوحي أو غيره، وإذا نزل فعل مثل ذلك، وكنا معشر قريش نَغلب النساء، فلما قدمنا على الأنصار، إذا قوم تغلبهم نساؤُهم، فطفق نساؤُنا يأخذن من أدب نساء الأنصار. فصخبتُ على امرأتي فراجعتني، فأنكرتُ أن تراجعني قالت: ولم تُنكر أن أراجعك؟ فو الله إن أزواج النبي ليراجعنه، وإن إحداهن لتهجره اليوم حتى الليل. فأفزعني ذلك فقلت لها: قد خاب من فعل ذلك منهن. ثم جمعتُ علي ثيابي، فنزلت حتى دخلتُ على حفصة فقلت لها: أي حفصة أتُغاضب إحداكن النبي ﷺ اليوم حتى الليل؟ قالت: نعم، فقلت: قد خبتِ وخسرتِ، أفتأمنين أن يغضب الله لغضب رسول الله ﷺ فتهلكي؟ لا تستكثري النبي ﷺ ولا تراجعيه في شيء ولا تهجريه، وسَليني ما بدا لكِ، ولا يغرنك أن كانت جارتُك أوضأ منك، وأحب إلى النبي ﷺ - يريد عائشة - قال عمر: وكنا قد تحدثنا أن غسان تنعل الخيل لتغزونا، فنزل صاحبي الأنصاري يومَ نوبتِه، فرجع إلينا عشاءً فضرب بابي ضرباً شديداً وقال: أثم هو؟ ففزعتُ فخرجتُ إليه، فقال: قد حدثَ اليوم أمرٌ عظيم، قلت: ما هو؟ أجاء غسان؟ قال: لا، بل أعظم من ذلك وأهول، طلّق النبي ﷺ نساءه.","وقال عبيد بن حنين: سمع ابن عباس عن عمر فقال: اعتزل النبي ﷺ أزواجه، فقلت: خابت حفصةُ وخسرتْ، وقد كنت أظنُّ هذا يوشك أن يكون، فجمعتُ عليّ ثيابي، فصليتُ صلاة الفجر مع النبي ﷺ، فدخل النبي ﷺ مشربةً له فاعتزل فيها، ودخلت على حفصة فإذا هي تبكي، فقلت: ما يُبكيك؟ ألم أكن حذّرتك هذا، أطلّقكن النبي ﷺ؟ قالت: لا أدري، ها هو ذا معتزل في المشربة.","فخرجت فجئت إلى المنبر فإذا حوله رهط يبكي بعضهم، فجلستُ معهم قليلا، ثم غلبني ما أجد فجئتُ المشربةَ التي فيها النبي ﷺ فقلتُ لغلام أسود: استأذنْ لعمر. فدخل الغلام فكلّم النبي ﷺ ثم رجع فقال: كلّمتُ النبي ﷺ وذكرتُك له فصمتَ، فانصرفتُ حتى جلستُ مع الرهط الذين عند المنبر. ثم غلبني ما أجدُ فجئت فقلت للغلام: استأذن لعمر، فدخل ثم رجع فقال: قد ذكرتك له فصمتَ، فرجعتُ فجلست مع الرهط مع المنبر، ثم غلبني ما أجد، فجئت الغلام فقلت: استأذن لعمر، فدخل ثم رجع إليَّ فقال: قد ذكرتك له فصمَتَ، فلما ولَّيتُ منصرفا قال: إذا الغلام يدعوني","فقال: قد أذنَ لك النبي ﷺ فدخلت على رسول الله ﷺ فإذا هو مُضطجع على رمال حصير ليس بينه وبينه فراش قد أثر الرمال بجنبه، متكئا على وسادة من أدم حشوها ليف، فسلّمتُ عليه. ثم قلت وأنا قائم: يا رسول الله أطلقتَ نساءك؟ فرفع إليَّ بصره فقال: (( لا)). فقلت: الله أكبر. ثم قلت وأنا قائم أستأنس: يا رسولَ الله لو رأيتني وكنا معشر قريش نغلبُ النساءَ، فلما قدمنا المدينة إذا قوم تغلبهم نساؤُهم، فتبسّم النبي ﷺ ثم قلت: يا رسول الله ﷺ رأيتني ودخلت على حفصة فقلت لها: لا يغرنّك أن كانت جارتُك أوضأ منك وأحب إلى النبي ﷺ يريد عائشة. فتبسّم النبي ﷺ تبسمة أخرى.","جلستُ حين رأيته تبسَّم، فرفعت بصري في بيته فو الله ما رأيت في بيته شيئا يرد البصر غير أهبة ثلاثة، فقلت: يا رسول الله! ادع الله فليُوسّع على أمتك، فإن فارس والروم قد وُسّعَ عليهم، وأعطوا الدنيا وهم لا يعبدون الله. فجلس النبي ﷺ وكان متكئا فقال: (( أوفي هذا أنت يا ابن الخطاب؟ إن أولئك قوم قد عُجِّلُوا طيباتهم في الحياة الدنيا)) فقلت: يا رسول الله ﷺ استغفر لي.","فاعتزل النبي ﷺ نساءَه من أجل ذلك الحديث حين أفشته حفصةُ إلى عائشة تسعا وعشرين ليلة، وكان قال: (( ما أنا بداخل عليهن شهراً) من شدة موجدتِه عليهن حين عاتبه الله عز وجل، فلما مضت تسعٌ وعشرون ليلة دخل على عائشة فبدأ بها، فقالت له عائشة: يا رسول الله! إنك كنتَ قد أقسمتَ أن لا تدخل علينا شهرا، وإنما أصبحت من تسع وعشرين ليلة أعدها عداً، فقال: الشهر تسع وعشرون ليلة، فكان ذلك الشهر تسعا وعشرين ليلة، قالت عائشة: ثم أنزل الله تعالى آية التخيير فبدأ بي أول امرأة من نسائه فاخترتُه، ثم خيّر نساءه كلهن فقلن مثل ما قالت عائشة."],"takhrij":"متفق عليه: رواه البخاري (٥١٩١) ومسلم (٣٤:١٤٧٩).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5191) and Muslim (1479/34).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbas said: I remained eager to ask ʿUmar ibn al-Khattab about the two women among the wives of the Prophet ﷺ concerning whom Allah the Exalted said: “If you two repent to Allah, then indeed your hearts have inclined.” [al-Tahrim: 4] This continued until he went for Hajj and I went with him. He moved aside and I moved aside with him carrying a water vessel. He relieved himself, then came back, and I poured water from it over his hands, and he performed wudu’. Then I said to him: O Commander of the Believers, who are the two women among the wives of the Prophet ﷺ concerning whom Allah the Exalted said: “If you two repent to Allah, then indeed your hearts have inclined”? He said: How strange of you, O Ibn ʿAbbas. They are ʿA’ishah and Hafsah. Then ʿUmar began narrating the story. He said: I and a neighbor of mine from the Ansar among Banu Umayyah ibn Zayd, from the high area of Madinah, used to alternate going down to the Prophet ﷺ. He would go down one day and I another day. When I went down, I would bring him the news of that day—revelation or anything else—and when he went down he would do the same. We, the Quraysh, used to dominate women, but when we came to the Ansar, they were a people whose women dominated them. Our women then began to adopt the manners of the women of the Ansar. I shouted at my wife and she answered me back, and I objected that she would answer me back. She said: Why do you object that I answer you back? By Allah, the wives of the Prophet ﷺ answer him back, and one of them may avoid him the whole day until night. That alarmed me, and I said to her: Whoever among them does that has failed. Then I gathered my clothes and went down until I entered upon Hafsah and said to her: O Hafsah, does one of you anger the Prophet ﷺ the whole day until night? She said: Yes. I said: You have failed and lost. Do you feel safe that Allah may become angry because of the anger of the Messenger of Allah ﷺ and you be ruined? Do not ask too much of the Prophet ﷺ, do not answer him back in anything, and do not abandon him. Ask me for whatever you need. And do not let it deceive you that your neighbor is more beautiful than you and more beloved to the Prophet ﷺ—meaning ʿA’ishah.","ʿUmar said: We had been speaking that Ghassan were shoeing their horses to attack us. Then my Ansari companion came down on his day and returned to us at evening, striking my door violently and saying: Is he there? I was alarmed and went out to him. He said: Today a great matter has occurred. I said: What is it? Have Ghassan come? He said: No, rather greater and more serious than that: the Prophet ﷺ has divorced his wives.","ʿUbayd ibn Hunayn said: Ibn ʿAbbas heard from ʿUmar, and he said: The Prophet ﷺ withdrew from his wives, so I said: Hafsah has failed and lost, and I had thought this was likely to happen. I gathered my clothes, prayed Fajr with the Prophet ﷺ, then the Prophet ﷺ entered an upper room of his and secluded himself there. I entered upon Hafsah and found her weeping. I said: Why are you weeping? Did I not warn you about this? Has the Prophet ﷺ divorced you? She said: I do not know. There he is, withdrawn in the upper room.","So I went out and came to the pulpit, and around it was a group, some of whom were weeping. I sat with them for a little while, then what I felt overcame me, so I came to the upper room where the Prophet ﷺ was and said to a black servant: Ask permission for ʿUmar. The servant entered and spoke to the Prophet ﷺ, then returned and said: I mentioned you to the Prophet ﷺ and he remained silent. So I went back and sat with the people near the pulpit. Then what I felt overcame me again, so I came and said to the servant: Ask permission for ʿUmar. He entered and then returned and said: I mentioned you to him and he remained silent. So I returned and sat again with the group near the pulpit. Then what I felt overcame me once more, so I came to the servant and said: Ask permission for ʿUmar. He entered, then returned to me and said: I mentioned you to him and he remained silent. As I turned to leave, the servant called me and said: The Prophet ﷺ has given you permission.","So I entered upon the Messenger of Allah ﷺ, and there he was lying on a woven mat with no mattress between him and it, and the marks of the mat had appeared on his side. He was reclining on a leather pillow stuffed with palm fiber. I greeted him, then I said while standing: O Messenger of Allah, have you divorced your wives? He raised his gaze to me and said: “No.” I said: Allah is greatest. Then I said while still standing, trying to bring ease: O Messenger of Allah, if only you had seen me. We Quraysh used to dominate women, but when we came to Madinah we found a people whose women dominated them. So the Prophet ﷺ smiled. Then I said: O Messenger of Allah, if only you had seen me when I entered upon Hafsah and said to her: Do not let it deceive you that your neighbor is more beautiful than you and more beloved to the Prophet ﷺ—meaning ʿA’ishah. The Prophet ﷺ smiled a second time.","When I saw him smile, I sat down. Then I raised my eyes in his room, and by Allah, I saw nothing in his room that could draw the eye except three tanned hides. So I said: O Messenger of Allah, supplicate to Allah to grant abundance to your nation, for Persia and Rome have been given abundance and granted the worldly life while they do not worship Allah. The Prophet ﷺ sat up, having been reclining, and said: “Are you in this state of mind, O son of al-Khattab? Those are a people whose good things have been hastened for them in the worldly life.” I said: O Messenger of Allah, ask forgiveness for me.","The Prophet ﷺ withdrew from his wives because of that matter when Hafsah disclosed it to ʿA’ishah for twenty-nine nights. He had said: “I will not enter upon them for a month,” because of how angry he was with them when Allah the Exalted reproved him. Then when twenty-nine nights had passed, he entered upon ʿA’ishah and began with her. ʿA’ishah said to him: O Messenger of Allah, you had sworn not to enter upon us for a month, but you came after twenty-nine nights, which I counted carefully. He said: “The month is twenty-nine nights.” And that month was twenty-nine nights. ʿA’ishah said: Then Allah the Exalted revealed the verse of giving the choice, so he began with me, the first of his wives, and I chose him. Then he gave all his wives the choice, and they all said what ʿA’ishah said."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5191},{"key":"muslim","label":"مسلم","number":34}]},{"num":6645,"demo":false,"sanad":"","matn":["عن أم سلمة: أن النبي ﷺ حلف أن لا يدخل على بعض أهله شهراً، فلما مضى تسعة وعشرون يوماً غدا عليهن - أو راح - فقيل له: يا نبي الله حَلفتَ أن لا تدخل عليهن شهراً؟ قال: (( إن الشهر يكون تسعةً وعشرين يوماً))."],"takhrij":"متفق عليه: رواه البخاري (٥٢٠٢) ومسلم (١٠٨٥).","grade":"متفق عليه","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5202) and Muslim (1085).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah reported that the Prophet ﷺ swore that he would not enter upon some of his wives for a month. Then when twenty-nine days had passed, he went to them in the morning—or in the afternoon. It was said to him: O Prophet of Allah, you swore not to enter upon them for a month. He said: “A month may be twenty-nine days.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5202},{"key":"muslim","label":"مسلم","number":1085}]},{"num":6646,"demo":false,"sanad":"","matn":["عن أنس قال: آلَى رسولُ الله ﷺ من نسائه، وكان انفكَّتْ رجلُه، فأقام في مشربة له تسعاً وعشرين، ثم نزل، فقالوا: يا رسول الله، آليت شهراً؟ فقال: (( الشهر يكون تسعا وعشرون))."],"takhrij":"صحيح: رواه البخاري (٥٢٨٩).","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5289).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ made īlāʾ from his wives, and his leg had become injured, so he stayed in an upper room for twenty-nine days. Then he came down, and they said: O Messenger of Allah, you took an oath for a month. He said: “The month may be twenty-nine days.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5289}]},{"num":6647,"demo":false,"sanad":"","matn":["عن جابر قال: كان رسول الله ﷺ اعتزل نساءه شهراً، فخرج إلينا في تسع وعشرين، فقلنا: إنما اليوم تسع وعشرون. فقال: «إنما الشهر هكذا»، وصفق بيديه ثلاث مرات، وحبس إصبعاً واحدة في الآخرة."],"takhrij":"صحيح: رواه مسلم (١٠٨٤).","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1084).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ withdrew from his wives for a month. Then he came out to us after twenty-nine days, and we said: It is only the twenty-ninth day. He said: “The month is like this,” and he clapped his hands three times, withholding one finger on the last time."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1084}]},{"num":6648,"demo":false,"sanad":"","matn":["عن الزهري قال: إن النبي ﷺ أقسم أن لا يدخل على أزواجه شهراً. قال الزهري: فأخبرني عروة، عن عائشة قالت: لما مضت تسع وعشرون ليلة أعدهن، دخل عليَّ رسول الله ﷺ - قالت: بدأ بي - فقلت: يا رسول الله، إنك أقسمت أن لا تدخل علينا شهراً، وإنك دخلت من تسع وعشرين أعدهن. فقال: «إن الشهر تسع وعشرون»."],"takhrij":"صحيح: رواه مسلم (١٠٨٣).","grade":"صحيح","chapter_ar":"باب ما جاء في الإيلاء","chapter_ur":"","part_ar":"كتاب الظهار والإيلاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1083).","chapter_en":"Chapter on What Has Been Reported Regarding Īlāʾ","part_en":"Book of Zihār and Īlāʾ","group_ar":"","group_en":"","part_no":28,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Al-Zuhri said: The Prophet ﷺ swore that he would not enter upon his wives for a month. Al-Zuhri said: ʿUrwah informed me from ʿA’ishah that when twenty-nine nights had passed, counting them carefully, the Messenger of Allah ﷺ entered upon me. She said: He began with me. So I said: O Messenger of Allah, you swore that you would not enter upon us for a month, yet you entered after twenty-nine nights which I counted. He said: “The month is twenty-nine.”"]},"buhuth":{"ar":["وقال: “والإيلاء هو: أن يحلف الرجل أن لا يقرب امرأته أربعة أشهر فأكثر”."],"en":["And he said: Īlāʾ is for a man to swear that he will not approach his wife for four months or more."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1083}]},{"num":6649,"demo":false,"sanad":"","matn":["عن أبي سلمة قال: جاء رجل إلى ابن عباس، وأبو هريرة جالس عنده فقال: أفْتِني في امرأة ولدت بعد زوجها بأربعين ليلة، فقال ابن عباس: آخر الأجلين. قلت أنا: (وَأُوْلَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ) [الطلاق: ٤ ] قال أبو هريرة: أنا مع ابن أخي، يعني أبا سلمة، فأرسل ابن عباس كُريباً إلى أم سلمة، يسألها، فقالت: قُتل زوجُ سُبَيْعة الأسلمية وهي حُبلى، فوضعت بعد موته بأربعين ليلة، فخُطِبتْ، فأنكحَها رسول الله ﷺ وكان أبو السَّنابل فيمن خَطَبَها."],"takhrij":"متفق عليه: رواه البخاري (٤٩٠٩)، ومسلم (١٤٨٥).","grade":"متفق عليه","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (4909) and Muslim (1485).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Salamah said: A man came to Ibn ʿAbbas, while Abu Hurayrah was sitting with him, and said: “Give me a ruling about a woman who gave birth forty nights after her husband died.” Ibn ʿAbbas said: “The later of the two terms.” I said: “But Allah says: ‘And for those who are pregnant, their term is until they deliver their burden.’” [al-Talaq: 4] Abu Hurayrah said: “I am with my nephew,” meaning Abu Salamah. So Ibn ʿAbbas sent Kurayb to Umm Salamah to ask her, and she said: “The husband of Subayʿah al-Aslamiyyah was killed while she was pregnant, and she gave birth forty nights after his death. Then she was proposed to, and the Messenger of Allah ﷺ married her off. Abu al-Sanabil was among those who proposed to her.”"]},"intro":{"ar":["قال الله تعالى: (وَأُولَٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ) [سورة الطلاق: ٤]","الآية شاملة للحامل المطلقة، والحامل المتوفى عنها زوجُها فعدتُهن وضع حملهن على أي صفة كان حيا","أو ميتا، تام الخِلقة أو ناقصُها."],"en":["Allah the Exalted said: “And for those who are pregnant, their term is until they deliver their burden.” [Surat al-Talaq: 4]","This verse includes both the pregnant divorced woman and the pregnant woman whose husband has died. Their waiting period ends when they deliver their pregnancy, in whatever form it may be: alive or dead, fully formed or incompletely formed."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4909},{"key":"muslim","label":"مسلم","number":1485}]},{"num":6650,"demo":false,"sanad":"","matn":["عن أبي سلمة بن عبد الرحمن أنه قال: سُئل عبد الله بن عباس، وأبو هريرة عن المرأة الحامل يتوفى عنها زوجُها؟ فقال ابن عباس: آخر الأجلين. وقال أبو هريرة: إذا ولدتْ فقد حلَّتْ.","فدخل أبو سلمة بن عبد الرحمن على أم سلمة زوج النبي ﷺ فسألها عن ذلك، فقالت أم سلمة: ولدتْ سُبَيْعة الأسلمية بعد وفاة زوجها بنصف شهر، فخطبها رجلان، أحدهما شابٌّ، والآخر كهلّ، فحطّتْ إلى الشاب، فقال الشيخ: لم تَحِلّي بعد، وكان أهلُها غيباً، ورجا إذا جاء أهلُها أن يؤثروه بها، فجاءتْ رسول الله ﷺ فقال: (( قد حللتِ فانكِحي من شئت))."],"takhrij":"صحيح: رواه مالك (٨٣) والنسائي (٣٥١٠)","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (83) and al-Nasa’i (3510).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu Salamah ibn ʿAbd al-Rahman said: Ibn ʿAbbas and Abu Hurayrah were asked about a pregnant woman whose husband dies. Ibn ʿAbbas said: “The later of the two terms.” Abu Hurayrah said: “Once she gives birth, she becomes lawful to marry.” Then Abu Salamah ibn ʿAbd al-Rahman entered upon Umm Salamah, the wife of the Prophet ﷺ, and asked her about that. Umm Salamah said: “Subayʿah al-Aslamiyyah gave birth half a month after her husband’s death. Then two men proposed to her, one young and the other older. She inclined toward the younger man, so the older man said: ‘You have not yet become lawful.’ Her family was absent, and he hoped that when her family arrived they would prefer him for her. So she came to the Messenger of Allah ﷺ and he said: ‘You have become lawful, so marry whomever you wish.’”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":83},{"key":"nasai","label":"النسائي","number":3510}]},{"num":6651,"demo":false,"sanad":"","matn":["عن أم سلمة: أن امرأة من أسلم يقال لها سُبَيْعة كان تحت زوجها توفي عنها وهي حُبلى، وخطبها أبو السنابل بن بعكك، فأبتْ أن تنكحه، فقال: والله ما يصلح أن تَنْكِحيه حتى تعتدِّيْ آخر الأجلين، فمكثت قريبا من عشر ليال، ثم جاء النبي ﷺ فقال: (( انكحي ))."],"takhrij":"صحيح: رواه البخاري (٥٣١٨).","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5318).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Umm Salamah reported that a woman from Aslam named Subayʿah had been married to a husband who died while she was pregnant. Abu al-Sanabil ibn Baʿkak proposed to her, but she refused to marry him. He said: “By Allah, it is not proper for you to marry until you observe the later of the two terms.” So she remained for around ten nights, then she came to the Prophet ﷺ, and he said: “Marry.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5318}]},{"num":6652,"demo":false,"sanad":"","matn":["عن عبد الله بن عتبة بن مسعود أن أباه كتب إلى عمر بن عبد الله بن الأرقم الزهري، يأمره أن يدخل على سُبيعة بنت الحارث الأسلمية، فيسألها عن حَديثها وعما قال لها رسول الله ﷺ حين استفتته. فكتب عمر بن عبد الله إلى عبد الله بن عتبة يخبره، أن سبيعة أخبرته، أنها كانت تحت سعد بن خولة. وهو في بني عامر بن لُؤي. وكان ممن شهد بدراً. فتوفي عنها في حجة الوداع وهي حامل. فلم تَنْشبْ أن وضعتْ حملَها بعد وفاته. فلما تعلّتْ من نفاسها تجمَّلتْ للخُطّاب. فدخل عليها أبو السَّنابل بن بعكك (رجل من بني عبد الدار) فقال لها: ما لي أراك متجمّلة؟ لعلكِ ترْجِين النكاح. إنك، والله! ما أنتِ بناكح حتى تمر عليك أربعة أشهر وعشر. قالت سُبيعة: فلما قال لي ذلك، جمعتُ عليَّ ثيابي حين أمسيتُ. فأتيتُ رسول الله ﷺ فسألته عن ذلك؟ فأفتاني بأني قد حللتُ حين وضعتُ حملي. وأمرني بالتزوج إن بدا لي.","قال ابن شهاب: فلا أرى بأسا أن تتزوج حين وضعتْ. وإن كانت في دمها. غير أن لا يقربها زوجُها حتى تطهر."],"takhrij":"متفق عليه: رواه البخاري (٥٣١٩)، ومسلم (١٤٨٤)، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5319) and Muslim (1484), and this is the wording of Muslim.","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿUtbah ibn Masʿud reported that his father wrote to ʿUmar ibn ʿAbdullah ibn al-Arqam al-Zuhri, instructing him to enter upon Subayʿah bint al-Harith al-Aslamiyyah and ask her about her account and what the Messenger of Allah ﷺ said to her when she asked him for a ruling. So ʿUmar ibn ʿAbdullah wrote back to ʿAbdullah ibn ʿUtbah informing him that Subayʿah told him that she had been married to Saʿd ibn Khawlah, from Banu ʿAmir ibn Lu’ayy, and he had been among those who witnessed Badr. He died during the Farewell Pilgrimage while she was pregnant. Soon after his death, she delivered her child. When she became pure from her postnatal bleeding, she beautified herself for suitors. Abu al-Sanabil ibn Baʿkak, a man from Banu ʿAbd al-Dar, entered upon her and said: “Why do I see you beautified? Perhaps you are hoping for marriage. By Allah, you are not to marry until four months and ten days have passed over you.” Subayʿah said: “When he said that to me, I gathered my clothes around me that evening and went to the Messenger of Allah ﷺ and asked him about that. He gave me the ruling that I had become lawful when I delivered my pregnancy, and he ordered me to marry if I wished.”","Ibn Shihab said: “So I see no harm in her marrying once she has delivered, even if she is still in her blood, except that her husband should not approach her until she becomes pure.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5319},{"key":"muslim","label":"مسلم","number":1484}]},{"num":6653,"demo":false,"sanad":"","matn":["عن محمد بن سيرين قال: جلست إلى مجلس فيه عُظم من الأنصار، وفيهم عبد الرحمن بن أبي ليلى، فذكرتُ حديث عبد الله بن عتبة في شأن سُبيعة بنت الحارث. فقال عبد الرحمن:","ولكن عمّه كان لا يقول ذلك فقلت: إني لجرئ إن كذبتُ على رجل في جانب الكوفة، ورفع صوته، قال: ثم خرجتُ، فلقيتُ مالك بن عامر أو مالك بن عوف. قلت: كيف كان قول ابن مسعود في المتوفى عنها زوجُها وهي حامل؟ فقال: قال ابن مسعود: أتجعلون عليها التغليظ، ولا تجعلون لها الرخصة؟ لنزلتْ سورةُ النساء القصرى بعد الطولى."],"takhrij":"صحيح: رواه البخاري (٤٥٣٢).","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (4532).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Muhammad ibn Sirin said: I sat in a gathering in which there were leading men from the Ansar, among them ʿAbd al-Rahman ibn Abi Layla, and I mentioned the hadith of ʿAbdullah ibn ʿUtbah concerning Subayʿah bint al-Harith. ʿAbd al-Rahman said: “But his uncle did not used to say that.” I said: “How bold I would be if I lied against a man in the region of Kufah,” and I raised my voice. Then I went out and met Malik ibn ʿAmir—or Malik ibn ʿAwf. I said: “What was Ibn Masʿud’s opinion concerning a woman whose husband dies while she is pregnant?” He said: Ibn Masʿud said: “Do you make things more difficult for her and do not give her the concession? The shorter Surat al-Nisa’ was revealed after the longer one.”"]},"buhuth":{"ar":["وقوله: “عمه كان لا يقول ذلك” المراد به عبد الله بن مسعود، ما كان يقول بهذا في شأن سُبيعة بنت الحارث، إلا أن هذا النقل منه ليس بصحيح، فإن ابن مسعود كان يقول خلاف ذلك، فلعله كان يقول أولاً ثم رجع عنه، أو وهم الناقل عنه كذا قاله ابن حجر. وقوله: سورة النساء القصرى - أي سورة الطلاق. وقوله: بعد الطولى: أي بعد البقرة.","ففي سورة البقرة: ( وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَجًا يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرِ وَعَشْرًا )","[البقرة: ٢٣٤] وفي سورة الطلاق: (وَأَوْلَٰتُ ٱلْأَحْمَالِ أجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ) ومراد ابن مسعود أنه وقع نسخ، فالمتأخر هو الناسخ. وإلى هذا يُشير ابن مسعود بقوله: “ من شاء لاعنتُه لأنزلتْ سورة النساء","القصرى بعد الأربعة الأشهر وعشرا” والملاعنة هنا بمعنى: المباهلة، رواه أبو داود (٢٣٠٧) وابن ماجه","(٢٠٣٠) بإسناد صحيح","قال الحافظ ابن حجر: “وإلا فالتحقيقُ أن لا نسخ هناك، بل عموم آية البقرة مخصوص بآية الطلاق”. قاله في “الفتح” (٨/٦٥٦)."],"en":["His statement, “his uncle did not used to say that,” refers to ʿAbdullah ibn Masʿud. It means that he was reported not to have given the ruling of Subayʿah bint al-Harith. But this report from him is not correct, for Ibn Masʿud actually held the opposite view. Perhaps he first held one opinion and then changed it, or the narrator erred regarding him, as Ibn Hajar said.","And “the shorter Surat al-Nisa’” means Surat al-Talaq, while “the longer one” means Surat al-Baqarah.","In Surat al-Baqarah is: “And those among you who die and leave wives behind—they shall wait by themselves for four months and ten days.” [al-Baqarah: 234]","And in Surat al-Talaq is: “And for those who are pregnant, their term is until they deliver their burden.”","Ibn Masʿud intended that there had been abrogation, so the later verse would be the abrogating one. This is what Ibn Masʿud pointed to by his statement: “Whoever wishes, I will invoke mutual imprecation with him that the shorter Surat al-Nisa’ was revealed after the verse of four months and ten.” Here, mulaʿanah means mutual invocation. This was narrated by Abu Dawud (2307) and Ibn Majah (2030) with an authentic chain.","Al-Hafiz Ibn Hajar said: “But the correct view is that there is no abrogation here. Rather, the general wording of the verse in al-Baqarah is specified by the verse of al-Talaq.” (Fath al-Bari, 8/656)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4532}]},{"num":6654,"demo":false,"sanad":"","matn":["عن المسور بن مخرمة أنه أخبره أن سُبيعة الأسلمية نُفِسَتْ بعد وفاة زوجها بليال، فقال لها رسول الله ﷺ: (( قد حللتِ فانكِحي من شئتِ ))"],"takhrij":"صحيح: رواه البخاري (٥٣٢٠).","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5320).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Miswar ibn Makhramah reported that Subayʿah al-Aslamiyyah gave birth a few nights after her husband’s death, and the Messenger of Allah ﷺ said to her: “You have become lawful, so marry whomever you wish.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5320}]},{"num":6655,"demo":false,"sanad":"","matn":["عن أم الطفيل امرأة أُبيّ بن كعب قالت: إنها سمعت عمر بن الخطاب وأُبي بن كعب يختصمان، فقالت أم الطفيل: أفلا يسأل عمر بن الخطاب سبيعة الأسلمية؟ توفي عنها زوجها وهي حامل، فوضعت بعد ذلك بأيام، فأنكحها رسول الله ﷺ."],"takhrij":"حسن: رواه أحمد (٢٧١٠٩).","grade":"حسن","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (27109).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Umm al-Tufayl, the wife of Ubayy ibn Kaʿb, said: She heard ʿUmar ibn al-Khattab and Ubayy ibn Kaʿb disputing, so Umm al-Tufayl said: “Why does ʿUmar ibn al-Khattab not ask Subayʿah al-Aslamiyyah? Her husband died while she was pregnant, then she gave birth a few days later, and the Messenger of Allah ﷺ married her off.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":27109,"n":27109}]},{"num":6656,"demo":false,"sanad":"","matn":["عن أبي السنابل بن بعكك قال: وضعتْ سُبيعةُ بعد وفاة زوجها بثلاثة وعشرين، أو خمسة وعشرين يوماً. فلما تعلّتْ تشوَّفتْ للنكاح فأنكر عليها. فذُكِر ذلك للنبي ﷺ فقال: (( إن تفعل فقد حلَّ أجلُها ))"],"takhrij":"صحيح: رواه الترمذي (١١٩٣) والنسائي (٣٥٠٨) وابن ماجه (٢٠٢٧) وأحمد (١٨٧١٣).","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1193), al-Nasa’i (3508), Ibn Majah (2027), and Ahmad (18713).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Abu al-Sanabil ibn Baʿkak said: Subayʿah gave birth twenty-three or twenty-five days after her husband’s death. When she became pure, she desired marriage, and I objected to that. Then that was mentioned to the Prophet ﷺ and he said: “If she does so, then her term has indeed ended.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1193},{"key":"nasai","label":"النسائي","number":3508},{"key":"ibnmajah","label":"ابن ماجه","number":2027},{"key":"ahmad","label":"مسند الإمام أحمد","number":18713,"n":18713}]},{"num":6657,"demo":false,"sanad":"","matn":["عن مسروق وعمرو بن عتبة، أنهما كتبا إلى سُبيعة بنت الحارث يسألانها عن أمرها.","فكتبت إليهما: أنها وضعت بعد وفاة زوجها بخمسة وعشرين. فتهيأت تطلب الخير. فمَرَّ بها أبو السنابل بن بعكك. فقال: قد أسرعت. اعتدي آخر الأجلين، أربعة أشهر وعشرا. فأتيتُ النبي ﷺ.","فقلتُ: يا رسول الله استغفر لي. قال: (( وفيم ذاك؟ )) فأخبرته. فقال: (( إن وجدت زوجا صالحا فتزوجي ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٠٢٨).","grade":"صحيح","chapter_ar":"باب عدّة الحامل المطلقة والمتوفى عنها زوجها وضع الحمل","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Majah (2028).","chapter_en":"The waiting period of a pregnant divorced woman and a pregnant widow is until delivery","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Masruq and ʿAmr ibn ʿUtbah wrote to Subayʿah bint al-Harith asking her about her case. She wrote back to them that she had given birth twenty-five days after her husband’s death. Then she prepared herself seeking marriage. Abu al-Sanabil ibn Baʿkak passed by her and said: “You have hastened. Observe the later of the two terms: four months and ten days.” So I went to the Prophet ﷺ and said: “O Messenger of Allah, ask forgiveness for me.” He said: “And why is that?” So I informed him, and he said: “If you find a righteous husband, then marry.”"]},"buhuth":{"ar":["وقوله: “تعلّت” أي ارتفعتْ بمعنى طهرتْ من النفاس. وقوله: “فتشوّفت” بالفاء أي طمعت","وتشوقت للنكاح.","والحامل المطلقة حكمها حكمُ الحامل المتوفى عنها زوجُها. والحداد تابع للعدة، فإن كانت المرأةُ الحامل المتوفى عنها زوجُها في الأشهر الأول من الحمل، فحدادها يستمر إلى الوضع، ولو بلغ تسعة أشهر أو زيادة"],"en":["His statement, “taʿallat”, means she rose up, meaning she became pure from postnatal bleeding. And “fatashawwafat” means she longed and hoped for marriage.","The ruling of a pregnant divorced woman is the same as that of a pregnant widow. Mourning follows the waiting period, so if a woman whose husband died is in the early months of pregnancy, then her mourning continues until delivery, even if that reaches nine months or more."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2028}]},{"num":6658,"demo":false,"sanad":"","matn":["عن عائشة وحفصة زوجي النبي ﷺ، أن رسول الله ﷺ قال: (( لا يحلّ لامرأةٍ تؤمن بالله واليوم الآخرِ أن تُحِدَّ على ميتٍ فوق ثلاث ليالٍ إلا على زوج ))."],"takhrij":"صحيح: رواه مالك (١٠٤) ومسلم (١٤٩٠). وزاد في رواية: (( فإنها تُحِدّ عليه أربعة أشهر وعشراً )).","grade":"صحيح","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (104) and Muslim (1490). In another narration there is the addition: “For she mourns him for four months and ten days.”","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿA’ishah and Hafsah, the two wives of the Prophet ﷺ, reported that the Messenger of Allah ﷺ said: “It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three nights, except for a husband.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":104},{"key":"muslim","label":"مسلم","number":1490}]},{"num":6659,"demo":false,"sanad":"","matn":["عن زينب ابنة أبي سلمة قالت:","لما جاء نعي أبي سفيان من الشام، دعت أم حبيبة بصفرة في اليوم الثالث، فمسحت عارضيها وذراعيها، وقالت:","إني كنت عن هذا لغنية، لولا أني سمعت النبي ﷺ يقول:","«لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ تُحِدَّ عَلَى مَيِّتٍ فَوْقَ ثَلَاثٍ، إِلَّا عَلَى زَوْجٍ، فَإِنَّهَا تُحِدُّ عَلَيْهِ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا»."],"takhrij":"متفق عليه: رواه البخاري (١٢٨٠)، ومسلم (١٤٨٦).","grade":"متفق عليه","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1280) and Muslim (1486).","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Zaynab, the daughter of Abū Salamah, reported: When news of Abū Sufyān’s death came from Syria, Umm Ḥabībah called for some yellow perfume on the third day. She applied it to her cheeks and forearms and said: “I had no need for this, were it not that I heard the Prophet ﷺ say: ‘It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three days, except for her husband, for whom she must mourn for four months and ten days.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1280},{"key":"muslim","label":"مسلم","number":1486}]},{"num":6660,"demo":false,"sanad":"","matn":["عن أم عطية قالت: كنا نُنْهى أن نُحِدّ على ميت فوق ثلاث إلا على زوج أربعة أشهر وعشراً، ولا نكتحلُ ولا نتطيبُ ولا نلبسُ ثوباً مصبوغاً إلا ثوب عصب.","وقد رُخِّصَ لنا عند الطهر إذا اغتسلت إحدانا من محيضها في نبذة من كُستِ أظفار. وكُنَّا نُنْهى عن اتباع الجنائز. وفي رواية: عن محمد بن سيرين قال: تُوفي ابن لأم عطية. فلما كان اليوم الثالث دعتْ بصفرةٍ فتمسحتْ به وقالت: نُهينا أن نُحِدّ أكثر من ثلاثٍ إلا بزوج."],"takhrij":"صحيح: رواه البخاري (٣١٣)، ومسلم (٩٣٨) والرواية الثانية عند البخاري (١٢٧٩).","grade":"صحيح","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (313) and Muslim (938). The second narration is in al-Bukhari (1279).","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Umm ʿAtiyyah said: We were forbidden to mourn for a deceased person for more than three days, except for a husband: four months and ten days. We were not to apply kohl, use perfume, or wear dyed garments except a striped cloth. We were allowed, when one of us became pure and had washed after her menstruation, to use a small amount of costus and azfar. We were also forbidden from following funerals.","And in another narration, Muhammad ibn Sirin said: A son of Umm ʿAtiyyah died. On the third day she called for yellow perfume, wiped herself with it, and said: “We were forbidden to mourn more than three days except for a husband.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":313},{"key":"muslim","label":"مسلم","number":938},{"key":"الروایہ_الثانیہ_عند_البخاری","label":"الرواية الثانية عند البخاري","number":1279}]},{"num":6661,"demo":false,"sanad":"","matn":["عن حُميد بن نافع، عن زينب بنت أبي سلمة، أنها أخبرته هذه الأحاديث الثلاثة.","قالت زينب: دخلتُ على أم حبيبة، زوج النبي ﷺ حين توفي أبوها أبو سفيان بن حرب. فدعتْ أمُّ حبيبة بطيب فيه صفرةٌ خلوقٌ أو غيره. فدهنتْ به جاريةً. ثم مسحتْ بعارضَيْها. ثم قالت: والله، ما لي بالطيب من حاجةٍ، غير أني سمعت رسول الله ﷺ يقول: (( لا يحل لامرأة تؤمن بالله واليوم الآخر أن تُحِدَّ على ميت فوق ثلاث ليال. إلا على زوج أربعة أشهرٍ وعشراً )) (هذا أولها) قالت زينب: ثم دخلت على زينب بنت جحش، زوج النبي ﷺ حين تُوُفّي أخوها، فدعتْ بطيب فمسّت منه. ثم قالت: والله ما لي بالطيب من حاجة غير أني سمعتُ رسول الله ﷺ يقول: (( لا يحل لامرأة تُؤمن بالله واليوم الآخر أن تُحِدَّ على ميت فوق ثلاث ليال، إلا على زوج أربعة أشهر وعشراً ))","(هذا ثانيها)"],"takhrij":"متفق عليه: رواه مالك (١٠٢-١٠١) والبخاري (٥٣٣٤،٥٣٣٥) ومسلم (١٤٨٩-١٤٨٦).","grade":"متفق عليه","chapter_ar":"باب الإحداد ثلاثة أيام، إلا على الزوج فهي أربعة أشهر وعشراً","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (101–102), al-Bukhari (5334, 5335), and Muslim (1486–1489).","chapter_en":"Mourning is three days, except for a husband, in which case it is four months and ten days","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Humayd ibn Nafiʿ narrated from Zaynab bint Abi Salamah that she told him these three hadiths. Zaynab said: I entered upon Umm Habibah, the wife of the Prophet ﷺ, when her father Abu Sufyan ibn Harb had died. Umm Habibah called for perfume containing yellow khaluq or something else. She applied it to a servant girl, then wiped some on her own cheeks. Then she said: “By Allah, I have no need for perfume, except that I heard the Messenger of Allah ﷺ say: ‘It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three nights, except for a husband: four months and ten days.’” (This is the first of them.)","Zaynab said: Then I entered upon Zaynab bint Jahsh, the wife of the Prophet ﷺ, when her brother died. She called for perfume and touched some of it. Then she said: “By Allah, I have no need for perfume, except that I heard the Messenger of Allah ﷺ say: ‘It is not lawful for a woman who believes in Allah and the Last Day to mourn for a deceased person for more than three nights, except for a husband: four months and ten days.’” (This is the second of them.)"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":102},{"key":"bukhari","label":"البخاري","number":5334},{"key":"muslim","label":"مسلم","number":1489}]},{"num":6662,"demo":false,"sanad":"","matn":["عن زينب قالت: سمعتُ أمي أم سلمة زوج النبي ﷺ تقول: جاءت امرأة إلى رسول الله ﷺ فقالت: يا رسول الله. إن ابنتي تُوفّي عنها زوجها. وقد اشتكتْ عينَيْها. أفتَكْحَلُهما؟ فقال رسول الله ﷺ: «لا» مرتين أو ثلاثا. كل ذلك يقول: «لا» ثم قال: (( إنما هي أربعة أشهر وعشراً. وقد كانت إحداكن في الجاهلية ترمي بالبعرة على رأس الحول )) قال حميد: فقلت لزينب: وما ترمي البعرة على رأس الحول؟ فقالت زينب: كانت المرأة إذا توفي عنها زوجُها. دخلت حِفْشاً ولبستْ شر ثيابها. ولم تمس طيباً ولا شيئاً حتى تمر بها سنة، ثم تؤتى بدابةٍ، حمارٍ أو شاةٍ أو طيرٍ، فتفتضُّ به، فقلما تفتضُ بشيء إلا مات، ثم تخرج، فتُعطى بعرة فترمي بها، ثم تُراجع بعد ما شاءت من طيبٍ أو غيره. (وهذا ثالثُها)"],"takhrij":"متفق عليه: رواه مالك (١٠٣) والبخاري (٥٣٣٦) ومسلم (١٤٨٨).","grade":"متفق عليه","chapter_ar":"باب النهي عن الاكتحال في الإحداد","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (103), al-Bukhari (5336), and Muslim (1488).","chapter_en":"The prohibition of using kohl during mourning","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Zaynab said: I heard my mother, Umm Salamah, the wife of the Prophet ﷺ, say: A woman came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, my daughter’s husband has died, and her eyes are hurting. May she apply kohl to them?” The Messenger of Allah ﷺ said: “No,” two or three times, each time saying: “No.” Then he said: “It is only four months and ten days, whereas in the pre-Islamic period one of you used to throw dung at the end of a year.”","Humayd said: I said to Zaynab: “What does ‘throwing dung at the end of the year’ mean?” Zaynab said: When a woman’s husband died, she would enter a shabby shelter and wear her worst clothes. She would not touch perfume or anything else until a year had passed. Then an animal would be brought to her—a donkey, a sheep, or a bird—and she would rub herself with it, and whatever she rubbed herself with would hardly survive. Then she would come out and be given a piece of dung which she would throw away. After that, she could return to using whatever perfume or other things she wished. (This is the third of them.)"]},"buhuth":{"ar":["قال مالك: “الحِفْش: البيت الردئ، وتفتضَّ - بتشديد الضاد تمسح به جلدها كالنُّشرة” أي تأخذ طائراً، فتمسح به فرجها، وتنبذه، فلا يكاد يعيش من الفض. كذا في “النهاية”."],"en":["Malik said: al-hifsh means a poor-quality house, and taftaddu—with a doubled dad—means she would rub her skin with it like a cleansing rite. That is, she would take a bird, wipe her private area with it, and cast it away, and it would hardly survive after that, as stated in al-Nihayah."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":103},{"key":"bukhari","label":"البخاري","number":5336},{"key":"muslim","label":"مسلم","number":1488}]},{"num":6663,"demo":false,"sanad":"","matn":["عن أم سلمة، أن امرأة تُوفي عنها زوجُها، فخَشوا عينيها فأتوا رسولَ الله فاستأذنوه في الكحل فقال: (( لا تكحِّل، قد كانت إحداكن تمكثُ في شرّ أحلاسها، أو شرّ بيتها، فإذا كان حول فمرَّ كلب رمت ببعرة، فلا حتى تمضي أربعة أشهر وعشراً ))."],"takhrij":"متفق عليه: رواه البخاري (٥٣٣٨) ومسلم (٦٠:١٤٨٨).","grade":"متفق عليه","chapter_ar":"باب النهي عن الاكتحال في الإحداد","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5338) and Muslim (60:1488).","chapter_en":"The prohibition of using kohl during mourning","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Umm Salamah reported that a woman’s husband died, and they became concerned about her eyes, so they came to the Messenger of Allah and asked his permission for her to use kohl. He said: “She must not apply kohl. In the pre-Islamic period one of you would remain in her worst clothes, or in the worst part of her house, and when a year passed and a dog went by, she would throw dung. No, not until four months and ten days have passed.”"]},"buhuth":{"ar":["وقولها: (( شر أحلاسها)) بفتح همزة، جمع حلس وهو كساء يلي ظهر البعير، أي شر ثيابها، مأخوذ من","حلس البعير."],"en":["Her statement: “the worst of her coverings” means her worst garments. The word refers to the cloth placed on a camel’s back."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5338},{"key":"muslim","label":"مسلم","number":60}]},{"num":6664,"demo":false,"sanad":"","matn":["عن أم عطية أن رسول الله ﷺ قال: (( لا تُحِدُّ المرأة على ميت فوق ثلاث، إلا على زوج أربعة أشهر وعشراً، ولا تلبس ثوباً مصبوغاً إلا ثوب عَصْبٍ، ولا تَكْتَحِل، ولا تمس طيباً، إلا عند طهرها حين تطهر: نبذة من قسط وأظفار))"],"takhrij":"متفق عليه: رواه البخاري (٣١٣) ومسلم (٩٣٨).","grade":"متفق عليه","chapter_ar":"باب اجتناب الحادة من الثياب المصبغة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (313) and Muslim (938).","chapter_en":"The mourning woman must avoid dyed clothing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm ʿAtiyyah reported that the Messenger of Allah ﷺ said: “A woman must not mourn for a deceased person for more than three days, except for a husband: four months and ten days. She must not wear dyed clothing except striped Yemeni cloth, must not apply kohl, and must not touch perfume, except when she becomes pure after menstruation, when she may use a small amount of costus and aromatic nail-like incense.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":313},{"key":"muslim","label":"مسلم","number":938}]},{"num":6665,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي ﷺ عن النبي ﷺ أنه قال: (( المتوفى عنها زوجُها لا تلبس المعَصْفر من الثياب، ولا الممشقة، ولا الحليّ، ولا تَخْتضب، ولا تكْتَحِل ))"],"takhrij":"صحيح: رواه أبو داود (٢٣٠٤) والنسائي (٣٥٣٥) وأحمد (٢٦٥٨١) وصحّحه ابن حبان (٤٣٠٦).","grade":"صحيح","chapter_ar":"باب اجتناب الحادة من الثياب المصبغة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2304), al-Nasa’i (3535), Ahmad (26581), and authenticated by Ibn Hibban (4306).","chapter_en":"The mourning woman must avoid dyed clothing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet, reported that the Prophet ﷺ said: “A woman whose husband has died must not wear safflower-dyed clothing, nor yellow-dyed clothing, nor jewelry, nor apply henna, nor use kohl.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2304},{"key":"nasai","label":"النسائي","number":3535},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4306},{"key":"ahmad","label":"مسند الإمام أحمد","number":26581,"n":26581},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2093,"n":2090}]},{"num":6666,"demo":false,"sanad":"","matn":["عن زينب بنت كعب بن عُجْرة، أن الفُريعة بنت مالك بن سنان - وهي أخت أبي سعيد الخدري - أخبرتها أنها جاءتْ رسولَ الله ﷺ تسأله أن ترجع إلى أهلها في بني خُدرة، وأن زوجَها خرج في طلب أعبدٍ له أبقوا، حتى إذا كان بطرف القَدوم لَحِقهم فقتلوه. قالت: فسألتُ رسول الله ﷺ أن أرجع إلى أهلي، فإن زوجي لم يترك لي مسكنا يملكه، ولا نفقة. قالت: فقال رسول الله ﷺ: «نعم» قالت: فانصرفت، حتى إذا كنتُ في الحجرة أو في المسجد ناداني رسولُ الله ﷺ أو أمر بي فنوديتُ له، فقال: «كيف قلت؟» قالت: فرددت عليه القصة التي ذكرت له من شأن زوجي. قال: «امكثي في بيتك حتى يبلغ الكتاب أجله» قالت: فاعتددتُ فيه أربعةَ أشهر وعشراً.","قالت: فلما كان عثمان، أرسل إليَّ فسألني عن ذلك فأخبرته، فاتبعه وقضى به."],"takhrij":"صحيح: رواه مالك (٩٦)، وأبو داود (٢٣٠٠) والترمذي (١٢٠٤) وابن ماجه (٢٠٣١) والنسائي","grade":"صحيح","chapter_ar":"باب اعتداد المتوفّى عنها زوجها في البيت الذي جاء فيه نعيُه","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (96), Abu Dawud (2300), al-Tirmidhi (1204), Ibn Majah (2031), and al-Nasa’i (3528).","chapter_en":"A widow observes her waiting period in the house where the news of her husband’s death reached her","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Zaynab bint Kaʿb ibn ʿUjrah reported that al-Furayʿah bint Malik ibn Sinan, the sister of Abu Saʿid al-Khudri, told her that she came to the Messenger of Allah ﷺ asking permission to return to her family among Banu Khudrah, because her husband had gone out seeking some runaway servants of his, and when he reached the edge of al-Qadum they caught up with him and killed him. She said: “I asked the Messenger of Allah ﷺ if I could return to my family, for my husband had not left me a house he owned nor any maintenance.” The Messenger of Allah ﷺ said: “Yes.” She said: “So I turned away, until when I was in the courtyard or in the mosque, the Messenger of Allah ﷺ called me back, or ordered that I be called, and he said: ‘What did you say?’ I repeated to him the story I had mentioned about my husband. He said: ‘Remain in your house until the prescribed term reaches its end.’ So I observed my waiting period there for four months and ten days.”","She said: Then during the caliphate of ʿUthman, he sent for me and asked me about that, so I informed him, and he followed it and ruled by it."]},"buhuth":{"ar":["(٣٥٢٨).","فقه الحديث: المرأة تعتدُّ في بيتِ زوجِها، ولا يجوزُ لأهلها إخراجها منه، وإنْ خرجتْ لحاجةٍ أو ضرورةٍ مثلَ أن تخافَ على نفسِها، أو يكونَ البيتُ مستأجرًا أو غير ذلك من الأعذار الضرورية، فلها أن تخرج، وتنتقل من بيت زوجها، لقوله تعالى: (فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِيَ أَنْفُسِهِنَّ مِن مَعْرُوفٍ) ففي هذه الحالة لا يجوزُ لأهلها أن يمنعوها."],"en":["Legal note: A woman observes her waiting period in her husband’s house, and her family may not remove her from it. But if she leaves for a need or necessity, such as fearing for her safety, or if the house is rented, or due to other necessary excuses, then she may leave and move from her husband’s house. Allah the Exalted said: “Then there is no blame upon you for what they do concerning themselves in an appropriate manner.” In such a case, her family may not prevent her."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":96},{"key":"abudawud","label":"أبو داود","number":2300},{"key":"tirmidhi","label":"الترمذي","number":1204},{"key":"ibnmajah","label":"ابن ماجه","number":2031}]},{"num":6667,"demo":false,"sanad":"","matn":["عن فاطمة بنت قَيس، أن أبا عمرو بن حفص طلَّقها البتَّة - وهو غائب بالشام - فأرسلَ إليها وكيلَه بشعير، فسخطَتْه. فقال: والله مالكِ علينا من شيء، فجاءت إلى رسول الله ﷺ فذكرتْ ذلك له. فقال: (( ليس لك عليه نفقة )) وأمرها أن تعتدَّ في بيتِ أم شريك، ثم قال: (( تلك امرأة يَغْشَاها أصحابي، اعتدَيْ عند عبد الله بن أم مكتوم، فإنه رجل أعمى، تضعين ثيابكِ عنده، فإذا حللتِ فآذنيني )) قالت: فلما حللتُ ذكرتُ له أن معاوية بن أبي سفيان، وأبا جهم بن هشام خَطباني.","فقال رسول الله ﷺ: «أما أبو جهم فلا يضع عصاه عن عاتقه، وأما معاوية فصعلوك لا مال له، انكحي أسامة بن زيد». قالت: فكرهته، ثم قال: «انكحي أسامة بن زيد». فنكحته، فجعل الله في ذلك خيرًا واغتبطت به."],"takhrij":"صحيح: رواه مالك (٦٧) ومسلم (٣٦:١٤٨٠). رواه مسلم (٣٧) من وجه آخر وفيه قوله : (( لا","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (67) and Muslim (36:1480). Muslim also narrated it through another route with the wording: “You have no maintenance and no housing.” And through another route: “She has no maintenance, but she must observe the waiting period.” His statement regarding Abu Jahm, “he does not put down his staff from his shoulder,” is a metaphor for his harshness toward women and his beating them, as is explicitly stated in some narrations.","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Fatimah bint Qays reported that Abu ʿAmr ibn Hafs gave her an irrevocable divorce while he was absent in Syria, and he sent his agent to her with barley. She was displeased with it. The agent said: “By Allah, you have no right against us to anything.” So she came to the Messenger of Allah ﷺ and mentioned that to him. He said: “You have no maintenance from him.” He ordered her to observe her waiting period in the house of Umm Sharik, then said: “That is a woman frequently visited by my companions. Observe your waiting period with ʿAbdullah ibn Umm Maktum, for he is a blind man, and you may place your garments there. When you become lawful, inform me.” She said: “When I became lawful, I informed him that Muʿawiyah ibn Abi Sufyan and Abu Jahm ibn Hisham had proposed to me.” The Messenger of Allah ﷺ said: “As for Abu Jahm, he never puts down his staff from his shoulder. As for Muʿawiyah, he is poor and has no wealth. Marry Usamah ibn Zayd.” She said: “I disliked him.” Then he said: “Marry Usamah ibn Zayd.” So I married him, and Allah placed much good in that for me, and I was pleased with it."]},"buhuth":{"ar":["نفقةَ لكِ ولا سُكُنى)). ورواه (٣٨) من طريق آخر وفيه: (( ليست لها نفقةٌ، وعليها العدّةُ )) وقوله ﷺ في أبي جهم: (( لا يضعُ عصاه عن عاتقِه )) كناية عن شدته على النساء وضربه إياهن، كما جاء مُصرّحًا به في بعض الروايات."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":67},{"key":"muslim","label":"مسلم","number":36},{"key":"رواہ_مسلم","label":". رواه مسلم","number":37}]},{"num":6668,"demo":false,"sanad":"","matn":["عن أبي بكر بن أبي الجهم قال: سمعت فاطمةً بنت قيس تقول: أرسلَ إليَّ زَوجي أبو عمرو بن حفص بن المغيرة بن عياش بن أبي ربيعة بطلاقي، وأرسل إليّ بخمس آصع تمر، وخمسٍ آصع شعير. فقلت: ما لي نفقة إلا هذا؟ ولا أعتد في بيتكم؟ قال: لا. فشددتُ عليّ ثياب، ثم أتيتُ النبي ﷺ فذكرتُ له ذلك، فقال: (( كم طلَّقَكِ؟)) قلت: ثلاثاً، قال: (( صدق، ليس لكِ نفقةٌ، واعتدِّي في بيت ابن عمك ابن أم مكتوم، فإنه ضرير البصر، تلقين ثيابكِ عنكِ، فإذا انقضتْ عدّتُكِ فآذنيني)","قالت: فخطبني خُطّابٌ، فيهم معاوية وأبوجهم، فقال رسول الله ﷺ: (( إن معاويةً تَرِبٌ خفيفُ الحال، وأبوجهم يضرب النساء - أي - فيه شدة على النساء - ولكن عليكِ أسامةَ بن زيد). أو قال: (( انكحيْ أسامةَ بن زيد )"],"takhrij":"صحيح: رواه مسلم ( ٤٨:١٤٨٠).","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (48:1480).","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abu Bakr ibn Abi al-Jahm said: I heard Fatimah bint Qays say: My husband Abu ʿAmr ibn Hafs ibn al-Mughirah ibn ʿAyyash ibn Abi Rabiʿah sent me my divorce, and he sent me five measures of dates and five measures of barley. I said: “Do I have no maintenance except this? And am I not to observe my waiting period in your house?” He said: “No.” So I wrapped my clothes around me, then I came to the Prophet ﷺ and mentioned that to him. He said: “How many times did he divorce you?” I said: “Three.” He said: “He has spoken the truth. You have no maintenance. Observe your waiting period in the house of your cousin Ibn Umm Maktum, for he is blind, and you may remove your garments there. When your waiting period ends, inform me.” She said: Then suitors proposed to me, among them Muʿawiyah and Abu Jahm, so the Messenger of Allah ﷺ said: “Muʿawiyah is poor and in straitened means, and Abu Jahm beats women—that is, he is harsh with women—but you should marry Usamah ibn Zayd.” Or he said: “Marry Usamah ibn Zayd.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":48}]},{"num":6669,"demo":false,"sanad":"","matn":["عن فاطمة بنت قيس قالت: طلّقني زوجي ثلاثاً، فلم يجعل لي رسولُ الله ﷺ سُكنى ولا نفقة."],"takhrij":"صحيح: رواه مسلم (٥١:١٤٨٠).","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (51:1480).","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Fatimah bint Qays said: My husband divorced me three times, and the Messenger of Allah ﷺ did not assign for me any housing or maintenance."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":51}]},{"num":6670,"demo":false,"sanad":"","matn":["عن فاطمة بنت قيس، عن النبي ﷺ في المطلقة ثلاثاً قال: (( ليس لها سُكنى ولا نفقة))."],"takhrij":"صحيح: رواه مسلم (٤٤:١٤٨٠).","grade":"صحيح","chapter_ar":"باب قصة فاطمة بنت قيس: لا نفقة لها ولا سكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (44:1480).","chapter_en":"The story of Fatimah bint Qays: she has no maintenance and no housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Fatimah bint Qays reported from the Prophet ﷺ concerning a woman divorced three times: “She has no housing and no maintenance.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":44}]},{"num":6671,"demo":false,"sanad":"","matn":["عن عروة قال: تزوج يحيى بن سعيد بن العاص بنتَ عبد الرحمن بن الحكم، فطلّقها، فأخرجَها من عنده، فعاب ذلك عليهم عروة. فقالوا: إن فاطمة قد خرجتْ. قال عروة: فأتيت عائشة فأخبرتها بذلك، فقالت: ما لفاطمة بنت قيس خير في أن تذكر هذا الحديث."],"takhrij":"متفق عليه: رواه مسلم (٥٢:١٤٨١)، والبخاري (٥٣٢٤،٥٣٢٦). وقوله تعالى: (إِلَّا أَن يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ ) قال ابن عباس: أن تبذو على أهلها، فإذا بذتْ عليهم فقد حل لهم إخراجها. ذكره البيهقي","grade":"متفق عليه","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (52:1481) and al-Bukhari (5324, 5326).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿUrwah said: Yahya ibn Saʿid ibn al-ʿAs married the daughter of ʿAbd al-Rahman ibn al-Hakam, then divorced her, and he turned her out from his place. ʿUrwah criticized them for that. They said: “Fatimah had gone out.” ʿUrwah said: So I went to ʿA’ishah and told her about that, and she said: “There is no good for Fatimah bint Qays in mentioning this hadith.”"]},"buhuth":{"ar":["(٤٣١/٧)."],"en":["Regarding the verse, “unless they commit a clear indecency,” Ibn ʿAbbas said: It means that she speaks offensively to her household, and if she does so, then it becomes lawful for them to remove her. This was mentioned by al-Bayhaqi (7/431)."]},"intro":{"ar":["قال الله تعالى: (أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ وَلَا تُضَارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ) [الطلاق: ٦]"],"en":["Allah the Exalted said: “Lodge them [during their waiting period] where you dwell, according to your means, and do not harm them in order to oppress them.” [al-Talaq: 6]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":52},{"key":"bukhari","label":"البخاري","number":5324}]},{"num":6672,"demo":false,"sanad":"","matn":["عن عائشة قالت: ما لفاطمة - ألا تتقي الله يعني في قولها: لا سكنى ولا نفقة."],"takhrij":"متفق عليه: رواه البخاري (٥٣٢٣) ومسلم (٥٤:١٤٨١).","grade":"متفق عليه","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5323) and Muslim (54:1481).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿA’ishah said: “What is the matter with Fatimah—does she not fear Allah?” meaning in her statement: “There is no housing and no maintenance.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5323},{"key":"muslim","label":"مسلم","number":54}]},{"num":6673,"demo":false,"sanad":"","matn":["عن القاسم بن محمد، وسليمان بن يسار، أنه سَمِعَهما يذكُران، أن يحيى بن سعيد بن العاص طلّق ابنة عبد الرحمن بن الحكم البتة. فانتقلها عبد الرحمن بن الحكم فأرسلت عائشة أم المؤمنين إلى مروان بن الحكم، وهو يومئذ أمير المدينة. فقالت: اتق الله واردد المرأة إلى بيتها. فقال مروان، في حديث سليمان: إن عبد الرحمن غلبني. وقال مروان في حديث القاسم: أو ما بلغك شأن فاطمة بنت قيس؟ فقالت عائشة: لا يضرك أن لا تذكر حديث فاطمة. فقال مروان: إن كان بك الشرُّ فحسبُك ما بين هذَين من الشر."],"takhrij":"صحيح: رواه مالك (٣٦) والبخاري (٥٣٢١،٥٣٢٢).","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (36) and al-Bukhari (5321, 5322).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Al-Qasim ibn Muhammad and Sulayman ibn Yasar reported that they heard that Yahya ibn Saʿid ibn al-ʿAs divorced the daughter of ʿAbd al-Rahman ibn al-Hakam with an irrevocable divorce. Then ʿAbd al-Rahman ibn al-Hakam moved her away. So ʿA’ishah, the Mother of the Believers, sent to Marwan ibn al-Hakam, who was then the governor of Madinah, saying: “Fear Allah and return the woman to her house.” Marwan said, in Sulayman’s narration: “ʿAbd al-Rahman overpowered me.” And Marwan said in al-Qasim’s narration: “Has the matter of Fatimah bint Qays not reached you?” ʿA’ishah said: “It will not harm you not to mention the hadith of Fatimah.” Marwan said: “If you mean that Fatimah moved because of the harm involved, then the harm between these two is sufficient justification.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":36},{"key":"bukhari","label":"البخاري","number":5321}]},{"num":6674,"demo":false,"sanad":"","matn":["عن أبي إسحاق قال: كنت مع الأسود بن يزيد جالسًا في المسجد الأعظم ومعنا الشعبي، فحدَّث الشعبي بحديث فاطمة بنت قيس أن رسول الله ﷺ لم يجعل لها سكنى ولا نفقة، ثم أخذ الأسود كفًّا من حصى فحصبه به، فقال: ويلك! تحدث بمثل هذا؟! قال عمر: لا نترك كتاب الله وسنة نبيه ﷺ لقول امرأة لا ندري لعلها حفظت أو نسيت، لها السكنى والنفقة. قال الله عز وجل:","﴿لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ﴾ [الطلاق: ١]."],"takhrij":"صحيح: رواه مسلم (٤٦:١٤٨٠).","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (46:1480).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Abu Ishaq said: I was sitting with al-Aswad ibn Yazid in the main mosque, and al-Shaʿbi was with us. Al-Shaʿbi narrated the hadith of Fatimah bint Qays, that the Messenger of Allah ﷺ did not assign for her housing or maintenance. Then al-Aswad took a handful of pebbles and threw them at him and said: “Woe to you! You narrate something like this?” ʿUmar said: “We do not leave the Book of Allah and the Sunnah of our Prophet ﷺ because of the statement of a woman when we do not know whether she remembered correctly or forgot. She has housing and maintenance.” Allah the Exalted said: “Do not turn them out of their houses, nor should they leave, unless they commit a clear indecency.” [Surat al-Talaq: 1]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":46}]},{"num":6675,"demo":false,"sanad":"","matn":["عن الشعبي، عن فاطمة بنت قيس قالت:","طلقني زوجي، فأردت النقلة، فأتيت رسول الله ﷺ فقال:","«انْتَقِلِي إِلَى بَيْتِ ابْنِ عَمِّكِ عَمْرِو بْنِ أُمِّ مَكْتُومٍ، فَاعْتَدِّي فِيهِ».","فحصبه الأسود وقال:","ويلك، لِمَ تفتي بمثل هذا؟","قال عمر:","إن جئت بشاهدين يشهدان أنهما سمعاه من رسول الله ﷺ، وإلا لم نترك كتاب الله لقول امرأة:","﴿لَا تُخْرِجُوهُنَّ مِنْ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ﴾","[الطلاق: ١]"],"takhrij":"صحيح: رواه النسائي (٣٥٤٩)، والدارقطني، ومن طريقه البيهقي (٧/٤٣١).","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3549), al-Dāraquṭnī, and through him al-Bayhaqī (7/431).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["Al-Shaʿbī reported from Fāṭimah bint Qays that she said: “My husband divorced me, and I wanted to move. So I came to the Messenger of Allah ﷺ, and he said: ‘Move to the house of your cousin ʿAmr ibn Umm Maktūm and observe your waiting period there.’” Al-Aswad threw pebbles at him and said: “Woe to you! Why do you give a ruling like this?” ʿUmar said: “If you bring two witnesses who testify that they heard this from the Messenger of Allah ﷺ, then we will accept it. Otherwise, we will not abandon the Book of Allah because of the statement of one woman: ‘Do not turn them out of their houses, nor should they leave, unless they commit a clear indecency.’”","[al-Ṭalāq: 1]"]},"buhuth":{"ar":["إنكار عمر بن الخطاب على فاطمة بنت قيس مبني على موقفه من السنة النبوية، بأنه كان يحتاط في قبولها، ولذا كان يطلب من يشهد له، لا أنه كان منكرًا لها. وقد ذهب بعض أهل العلم إلى أن قوله هذا لم يصح، كما نقل أبو داود عن الإمام أحمد في مسائل أحمد (ص ١٨٤)."],"en":["ʿUmar ibn al-Khaṭṭāb’s objection to the report of Fāṭimah bint Qays was based on his caution in accepting reports of the Prophetic Sunnah, which is why he sought supporting witnesses; it was not because he rejected the Sunnah. Some scholars also held that this statement from him was not authentically established, as Abū Dāwūd transmitted from Imām Aḥmad in Masāʾil Aḥmad (p. 184)."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3549},{"key":"ومن_طریقہ_البیہقی","label":"ومن طريقه البيهقي","number":7}]},{"num":6676,"demo":false,"sanad":"","matn":["عن عبيد الله بن عبد الله بن عتبة أن أبا عمرو بن حفص بن المغيرة خرج مع علي بن أبي طالب إلى اليمن، فأرسل إلى امرأته فاطمة بنت قيس بتطليقة كانت بقيت من طلاقها، وأمر لها الحارث بن هشام وعياش بن أبي ربيعة بنفقة، فقالا لها: والله ما لك نفقة إلا أن تكوني حاملًا. فأتت النبي ﷺ فذكرت له قولهما، فقال: «لا نفقة لك». فاستأذنته في الانتقال فأذن لها."],"takhrij":"صحيح: رواه مسلم (٤١:١٤٨٠).","grade":"صحيح","chapter_ar":"باب من أنكر على فاطمة بنت قيس وقال: إن المبتوتة لها النفقةُ والسُّكنى","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (41:1480).","chapter_en":"Those who objected to the report of Fatimah bint Qays and said that a woman with an irrevocable divorce is entitled to maintenance and housing","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿUbaydullah ibn ʿAbdullah ibn ʿUtbah reported that Abu ʿAmr ibn Hafs ibn al-Mughirah went out with ʿAli ibn Abi Talib to Yemen and sent to his wife Fatimah bint Qays the final divorce that remained from his divorces. He instructed al-Harith ibn Hisham and ʿAyyash ibn Abi Rabiʿah to give her maintenance, but they said to her: “By Allah, you have no maintenance unless you are pregnant.” So she came to the Prophet ﷺ and mentioned their statement to him. He said: “You have no maintenance.” Then she asked his permission to move, and he permitted her."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":41}]},{"num":6677,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: طُلِّقت خالتي، فأرادت أن تَجُدَّ نخلها، فزجرها رجل أن تخرج، فأتت النبي ﷺ فقال: «بلى، فجُدِّي نخلَكِ، فإنك عسى أن تصدَّقي أو تفعلي معروفًا»."],"takhrij":"صحيح: رواه مسلم (١٤٨٣).","grade":"صحيح","chapter_ar":"باب في خروج المعتدة من بيتها للحاجة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1483).","chapter_en":"A woman in her waiting period may leave her house for a need","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn ʿAbdullah said: My maternal aunt was divorced, and she wanted to cut the dates from her palm trees, but a man scolded her for going out. So she came to the Prophet ﷺ, and he said: “Rather, go and cut your palm trees, for perhaps you may give charity or do some good.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1483}]},{"num":6678,"demo":false,"sanad":"","matn":["عن فاطمة بنت قيس قالت: قلت: يا رسول الله، زوجي طلَّقني ثلاثا، وأخاف أن يُقْتَحم عليّ. قال: فأمرها فتحوّلتْ."],"takhrij":"صحيح: رواه مسلم (١٤٨٢).","grade":"صحيح","chapter_ar":"باب في خروج المعتدة من بيتها للحاجة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1482).","chapter_en":"A woman in her waiting period may leave her house for a need","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Fatimah bint Qays said: I said, “O Messenger of Allah, my husband has divorced me three times, and I fear that someone may force his way in upon me.” So he ordered her, and she moved."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1482}]},{"num":6679,"demo":false,"sanad":"","matn":["عن عائشة قالت: إن فاطمة كانت في مسكن وحش، فخيف عليها، فلذلك أرخص","لها رسول الله ﷺ."],"takhrij":"حسن: رواه أبو داود (٢٢٩٢) وابن ماجه (٢٠٣٢).","grade":"حسن","chapter_ar":"باب في خروج المعتدة من بيتها للحاجة","chapter_ur":"","part_ar":"كتاب العِدَد، والإحدادِ، والنفقاتِ","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (2292) and Ibn Majah (2032).","chapter_en":"A woman in her waiting period may leave her house for a need","part_en":"Book of Waiting Periods, Mourning, and Maintenance","group_ar":"","group_en":"","part_no":29,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿA’ishah said: Fatimah was living in a lonely place, and there was fear for her safety. For that reason, the Messenger of Allah ﷺ allowed her the concession."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2292},{"key":"ibnmajah","label":"ابن ماجه","number":2032}]},{"num":6680,"demo":false,"sanad":"","matn":["عن عائشة أم المؤمنين أن رسول الله ﷺ قال: «يحرم من الرضاعة ما يحرم من الولادة»."],"takhrij":"صحيح: رواه مالك (١٦)، وأبو داود (٢٠٥٥)، والترمذي (١١٤٧). وقال الترمذي: “هذا حديث","grade":"صحيح","chapter_ar":"باب النساء اللاتي يحرم نكاحهن بالنسب والمصاهرة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (16), Abu Dawud (2055), and al-Tirmidhi (1147). Al-Tirmidhi said: “This is a hasan sahih hadith.”","chapter_en":"Women whose marriage is forbidden due to blood relation and marital relation","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["ʿA’ishah, the Mother of the Believers, reported that the Messenger of Allah ﷺ said: “Breastfeeding makes unlawful what birth makes unlawful.”"]},"buhuth":{"ar":["حسن صحيح”."]},"intro":{"ar":["قال الله تعالى: ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْأَخِ وَبَنَاتُ الْأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ وَأُمَّهَاتُ نِسَائِكُمْ وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ وَأَنْ تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا﴾ [النساء: ٢٣].","قال ابن عباس: “حرُمَ من النسب سبعٌ، ومن الصهر سبعٌ، ثم قرأ (حُرِّمَتْ عَلَيْكُمْ أُمَّهَٰتُكُمْ)","[سورة النساء: ٢٣] رواه البخاري (٥١٠٥)"],"en":["Allah the Exalted said: “Forbidden to you are your mothers, your daughters, your sisters, your paternal aunts, your maternal aunts, the daughters of your brother, the daughters of your sister, your mothers who nursed you, your sisters through nursing, the mothers of your wives, your stepdaughters under your care born of your wives with whom you have consummated marriage—though if you have not consummated marriage with them, there is no blame upon you—the wives of your sons who are from your own loins, and that you combine two sisters in marriage, except what has already passed. Indeed, Allah is Ever-Forgiving, Most Merciful.” [Surat al-Nisa’: 23]","Ibn ʿAbbas said: “Seven are forbidden through blood relation, and seven through marriage relation,” then he recited: “Forbidden to you are your mothers…” [Surat al-Nisa’: 23].","Narrated by al-Bukhari (5105)."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":16},{"key":"abudawud","label":"أبو داود","number":2055},{"key":"tirmidhi","label":"الترمذي","number":1147}]},{"num":6681,"demo":false,"sanad":"","matn":["عن أم حبيبة بنت أبي سفيان قالت: يا رسول الله! انكح أختي بنت أبي سفيان. فقال:","«أَوَتُحِبِّينَ ذَلِكِ؟» فقلت: نعم، لست لك بمخلية، وأحب من شاركني في خير أختي. فقال النبي ﷺ: «إن ذلك لا يحل لي». قلت: فإنا نُحدَّث أنك تريد أن تنكح بنت أبي سلمة. قال: «بنت أم سلمة؟» قلت: نعم. فقال: «لو أنها لم تكن ربيبتي في حجري ما حلَّت لي؛ إنها ابنة أخي من الرضاعة، أرضعتني وأبا سلمة ثويبة، فلا تعرضن علي بناتكن ولا أخواتكن»."],"takhrij":"متفق عليه: رواه البخاري (٥١٠١) ومسلم (١٦:١٤٤٩) واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5101) and Muslim (16:1449), and this wording is from al-Bukhari.","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Umm Habibah bint Abi Sufyan said: “O Messenger of Allah, marry my sister, the daughter of Abu Sufyan.” He said: “Would you like that?” I said: “Yes. I am not the only one with you, and I would most like that my sister share with me in goodness.” The Prophet ﷺ said: “That is not lawful for me.” I said: “But we hear that you want to marry the daughter of Abu Salamah.” He said: “The daughter of Umm Salamah?” I said: “Yes.” He said: “Even if she were not my stepdaughter under my care, she would still not be lawful for me. She is the daughter of my brother through breastfeeding. Thuwaybah nursed me and Abu Salamah. So do not offer your daughters or your sisters to me.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5101},{"key":"muslim","label":"مسلم","number":16}]},{"num":6682,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قيل للنبي ﷺ: ألا تتزوج ابنة حمزة؟ قال: «إنها ابنة أخي من الرضاعة».","وزاد في رواية: “وإنه يَحرُم من الرضاعة ما يَحرُم من النَّسب”."],"takhrij":"صحيح: رواه البخاري (٥١٠٠)، ومسلم (١٣:١٤٤٧). واللفظ للبخاري. والرواية الأخرى لمسلم.","grade":"صحيح","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5100) and Muslim (13:1447). This wording is from al-Bukhari, and the additional wording is in Muslim.","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbas said: It was said to the Prophet ﷺ, “Will you not marry the daughter of Hamzah?” He said: “She is the daughter of my brother through breastfeeding.”","In another narration he added: “Breastfeeding makes unlawful what lineage makes unlawful.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5100},{"key":"muslim","label":"مسلم","number":13}]},{"num":6683,"demo":false,"sanad":"","matn":["عن علي قال:","قلت:","يا رسول الله، ما لك تنوّق في قريش وتدعنا؟","فقال:","«وَعِنْدَكُمْ شَيْءٌ؟»","قلت:","نعم، بنت حمزة.","فقال رسول الله ﷺ:","«إِنَّهَا لَا تَحِلُّ لِي، إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ»."],"takhrij":"صحيح: رواه مسلم (١٤٤٦).","grade":"صحيح","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1446).","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAlī reported: I said: “O Messenger of Allah, why do you carefully choose from among Quraysh and leave us?” He asked: “Do you have someone?” I replied: “Yes, the daughter of Ḥamzah.” The Messenger of Allah ﷺ said: “She is not lawful for me. She is the daughter of my brother through breastfeeding.”"]},"buhuth":{"ar":["قوله: «تنوّق» أي تختار وتبالغ في الاختيار من قريش، وتدعنا، يعني بني هاشم.","وضبط بعضهم بتاءين مثناتين، الثانية مضمومة: «تتوق»، من التوق، وهو الشوق والميل."],"en":["The word “tanawwaqu” means to choose carefully and with particular preference from among Quraysh, while leaving us—that is, Banū Hāshim.","Some scholars vocalized it as “tatūqu,” from tawq, meaning longing and inclination."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1446}]},{"num":6684,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي ﷺ قالت: قيل لرسول الله ﷺ: أين أنت يا رسول الله عن ابنة حمزة؟ أو قيل: ألا تخطب بنت حمزة بنت عبد المطلب؟ قال: «إن حمزة أخي من الرضاعة»."],"takhrij":"صحيح: رواه مسلم (١٤٤٨).","grade":"صحيح","chapter_ar":"باب في تحريم ابنة الأخ من الرضاعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1448).","chapter_en":"The prohibition of marrying a niece through breastfeeding","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, said: It was said to the Messenger of Allah ﷺ, “Why do you not marry the daughter of Hamzah?” Or it was said: “Will you not propose to the daughter of Hamzah, daughter of ʿAbd al-Muttalib?” He said: “Hamzah is my brother through breastfeeding.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1448}]},{"num":6685,"demo":false,"sanad":"","matn":["عن عائشة أم المؤمنين، أن رسول الله ﷺ كان عندها، وأنها سمعت صوت رجل يستأذن في بيت حفصة. قالت عائشة: فقلت: يا رسول الله، هذا رجل يستأذن في بيتك. فقال رسول الله ﷺ: «أراه فلانًا»، لعمٍّ لحفصة من الرضاعة. فقالت عائشة: يا رسول الله، لو كان فلان حيًّا - لعمها من الرضاعة - دخل علي؟ فقال رسول الله ﷺ: «نعم، إن الرضاعة تحرِّم ما تحرِّم الولادة»."],"takhrij":"متفق عليه: رواه مالك في الرضاع (١)، والبخاري (٢٦٤٦)، ومسلم (١:١٤٤٤).","grade":"متفق عليه","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik in the chapter of breastfeeding (1), al-Bukhari (2646), and Muslim (1:1444).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah, the Mother of the Believers, reported that the Messenger of Allah ﷺ was with her, and she heard the voice of a man asking permission to enter Hafsah’s house. ʿA’ishah said: I said, “O Messenger of Allah, this is a man asking permission to enter your house.” The Messenger of Allah ﷺ said: “I think he is so-and-so,” the paternal uncle of Hafsah through breastfeeding. ʿA’ishah said: “O Messenger of Allah, if so-and-so were alive”—meaning her own uncle through breastfeeding—“would he be allowed to enter upon me?” The Messenger of Allah ﷺ said: “Yes. Breastfeeding makes unlawful what birth makes unlawful.”"]}},"tuhfa":{},"refs":[{"key":"malik/الرضاع","label":"مالك في الرضاع","number":1},{"key":"bukhari","label":"البخاري","number":2646},{"key":"muslim","label":"مسلم","number":1}]},{"num":6686,"demo":false,"sanad":"","matn":["عن عائشة أم المؤمنين قالت: جاء عمي من الرضاعة يستأذن علي، فأبيت أن آذن له حتى أسأل رسول الله ﷺ عن ذلك. فجاء رسول الله ﷺ فسألته عن ذلك، فقال: «إنه عمك فأذني له». قالت: فقلت: يا رسول الله، إنما أرضعتني المرأة ولم يرضعني الرجل. فقال: «إنه عمك فليلج عليك».","قالت عائشة: وذلك بعد ما ضرب علينا الحجاب.","وقالت عائشة: يَحرُم من الرضاعة ما يَحرُم من الولادة."],"takhrij":"متفق عليه: رواه مالك (٢) والبخاري (٥٢٣٩) ومسلم (٧:١٤٤٥).","grade":"متفق عليه","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (2), al-Bukhari (5239), and Muslim (7:1445).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah, Mother of the Believers, said: My uncle through breastfeeding came asking permission to enter upon me, but I refused to allow him until I asked the Messenger of Allah about it. When the Messenger of Allah came, I asked him about that. He said: “He is your uncle, so allow him.” She said: I said, “O Messenger of Allah, it was the woman who nursed me; the man did not nurse me.” He said: “He is your uncle, so let him enter upon you.”","ʿA’ishah said: That was after hijab had been made obligatory upon us. And ʿA’ishah said: What is unlawful through breastfeeding is unlawful just as through birth."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":2},{"key":"bukhari","label":"البخاري","number":5239},{"key":"muslim","label":"مسلم","number":7}]},{"num":6687,"demo":false,"sanad":"","matn":["عن عائشة قالت: استأذن علي أفلح بن قعيس فأبيتُ أن آذن، فأرسل: إني عمّك،","أرضعتك امرأة أخي، فأبيت أن آذن له، فجاء رسول الله ﷺ فذكرت ذلك له فقال: «ليدخل عليك،","فإنه عمك»."],"takhrij":"صحيح: رواه مسلم في الرضاع (١٠:١٤٤٥)","grade":"صحيح","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the chapter of breastfeeding (10:1445).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah said: Aflah ibn Quʿays asked permission to enter upon me, but I refused. He sent word: “I am your uncle. The wife of my brother nursed you.” But I still refused to allow him. Then the Messenger of Allah came, and I mentioned that to him. He said: “Let him enter upon you, for he is your uncle.”"]}},"tuhfa":{},"refs":[{"key":"muslim/الرضاع","label":"مسلم في الرضاع","number":10}]},{"num":6688,"demo":false,"sanad":"","matn":["عن عائشة أم المؤمنين أنها أخبرتْ أن أفلح أخا أبي القُعَيْس جاء يستأذن عليها - وهو عمها من الرضاعة - بعد أن أنزل الحجاب، قالت: فأبيتُ أن آذن له عليَّ، فلما جاء رسول الله ﷺ أخبرته بالذي صنعتُ، فأمرني أن آذن له عليَّ."],"takhrij":"متفق عليه: رواه مالك (٣)، والبخاري (٥١٠٣)، ومسلم (٣:١٤٤٥).","grade":"متفق عليه","chapter_ar":"باب في لبن الفحل","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (3), al-Bukhari (5103), and Muslim (3:1445).","chapter_en":"Concerning the milk of the husband","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿA’ishah, the Mother of the Believers, reported that Aflah, the brother of Abu al-Quʿays, came asking permission to enter upon her—and he was her uncle through breastfeeding—after hijab had been revealed. She said: I refused to allow him in. When the Messenger of Allah came, I told him what I had done, and he ordered me to let him enter."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":3},{"key":"bukhari","label":"البخاري","number":5103},{"key":"muslim","label":"مسلم","number":3}]},{"num":6689,"demo":false,"sanad":"","matn":["عن عائشة زوج النبي ﷺ أنها قالت: كان فيما أُنزل من القرآن عشر رضعات معلومات يُحرِّمن، ثم نُسخن بخمس معلومات، فتوفي رسول الله ﷺ وهن فيما يُقرأ من القرآن."],"takhrij":"صحيح: رواه مالك (١٧) ومسلم (٢٤:١٤٥٢).","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (17) and Muslim (24:1452).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah, the wife of the Prophet ﷺ, said: Among what was revealed in the Qur’an was that ten known feedings made marriage unlawful, then that was abrogated by five known feedings. The Messenger of Allah ﷺ passed away while that was still being recited in the Qur’an."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":17},{"key":"muslim","label":"مسلم","number":24}]},{"num":6690,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول الله ﷺ: «لا تُحرِّم المصة والمصتان»."],"takhrij":"صحيح: رواه مسلم (١٤٥٠).","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1450).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “One suckling and two sucklings do not make marriage unlawful.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1450}]},{"num":6691,"demo":false,"sanad":"","matn":["عن عائشة قالت: دخل علي رسول الله ﷺ وعندي رجل قاعد، فاشتد ذلك عليه، ورأيت الغضب في وجهه. قالت: فقلت: يا رسول الله، إنه أخي من الرضاعة. فقال: «انظرن إخوتكن من الرضاعة، فإنما الرضاعة من المجاعة»."],"takhrij":"متفق عليه: رواه البخاري (٥١٠٢)، ومسلم (١٤٥٥)، والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5102) and Muslim (1455), and this wording is from Muslim.","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ entered upon me while a man was sitting with me. He disliked that strongly, and I saw anger on his face. I said: “O Messenger of Allah, he is my brother through breastfeeding.” He said: “Be careful in identifying who your brothers through breastfeeding are, for breastfeeding only counts when it is due to hunger.”"]},"buhuth":{"ar":["قوله: «فإنما الرضاعة من المجاعة»: أي أن الرضاعة التي تثبت بها الحرمة، وتحل بها الخلوة هي حيث يكون الرضيع طفلًا، ويكون اللبن هو غذاءه، ويسد به جوعه، ويكون هذا الإرضاع خلال السنتين الأوليين من عمر الرضيع؛ لقوله تعالى: ﴿وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ﴾ [البقرة: ٢٣٣]،","مع قوله تعالى: ﴿وَفِصَالُهُ فِي عَامَيْنِ﴾ [لقمان: ١٤]. وعليه يدل حديث أم سلمة."],"en":["His statement, “Breastfeeding only counts when it is due to hunger,” means that the breastfeeding which establishes prohibition and allows seclusion is when the child is still an infant, and the milk serves as nourishment and satisfies hunger. This is during the first two years of the child’s life, as Allah said: “Mothers shall breastfeed their children for two complete years for whoever wishes to complete the nursing period” [al-Baqarah: 233], together with His saying: “And his weaning is in two years” [Luqman: 14]. The hadith of Umm Salamah also indicates this."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5102},{"key":"muslim","label":"مسلم","number":1455}]},{"num":6692,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول الله ﷺ: «لا تُحرِّم الخطفة والخطفتان»."],"takhrij":"صحيح: رواه النسائي (٣٣١١).","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3311).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿA’ishah said: The Messenger of Allah ﷺ said: “One quick suckling and two quick sucklings do not make marriage unlawful.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3311}]},{"num":6693,"demo":false,"sanad":"","matn":["عن عبد الله بن الزبير أن النبي ﷺ قال: ((لا يُحرِّم من الرضاعة المصَّةُ والمصتان))."],"takhrij":"صحيح: رواه النسائي (٣٣٠٩) وأحمد (١٦١١٠) وعبد الرزاق (٤٦٩/٧) والبيهقي (٤٥٤/٧).","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (3309), Ahmad (16110), ʿAbd al-Razzaq (7/469), and al-Bayhaqi (7/454).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn al-Zubayr reported that the Prophet ﷺ said: “One suckling and two sucklings do not make marriage unlawful through breastfeeding.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3309},{"key":"عبد_الرزاق","label":"عبد الرزاق","number":469},{"key":"البیہقی","label":"البيهقي","number":454},{"key":"ahmad","label":"مسند الإمام أحمد","number":16110,"n":16110}]},{"num":6694,"demo":false,"sanad":"","matn":["عن عبد الله بن الزبير أن رسول الله ﷺ قال: «لا رضاع إلا ما فتق الأمعاء»."],"takhrij":"حسن: رواه ابن ماجه (١٩٤٦).","grade":"حسن","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (1946).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn al-Zubayr reported that the Messenger of Allah ﷺ said: “There is no breastfeeding that counts except that which fills the stomach.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":1946}]},{"num":6695,"demo":false,"sanad":"","matn":["عن أم الفضل قالت: دخل أعرابي على نبي الله ﷺ وهو في بيتي، فقال: يا نبي الله، إني كانت لي امرأة فتزوجت عليها أخرى، فزعمت امرأتي الأولى أنها أرضعت امرأتي الحُدثى رضعة أو رضعتين. فقال نبي الله ﷺ: «لا تُحرِّم الإملاجة والإملاجتان»."],"takhrij":"صحيح: رواه مسلم (١٨:١٤٥١).","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (18:1451).","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm al-Fadl said: A bedouin entered upon the Prophet ﷺ while he was in my house and said: “O Prophet of Allah, I had a wife, then I married another woman besides her. My first wife claims that she nursed my new wife once or twice.” The Prophet ﷺ said: “One suckling or two sucklings do not make marriage unlawful.”"]},"buhuth":{"ar":["وفي رواية: ((لا تُحرم الرضعةُ أو الرضعتان، أو المصةُ أو المصتان)).","وفي رواية: «ولا الرضعتان والمصتان».","وفي رواية: «هل تُحرِّم الرضعة الواحدة؟» قال: «لا».","قوله: «الإملاجة» هي المصة، يقال: ملج الصبي أمه إذا رضعها، وأملجته أمه أي أرضعته."],"en":["In another narration: “One feeding or two feedings, or one suckling or two sucklings, do not make marriage unlawful.”","In another narration: “Nor do two feedings and two sucklings make marriage unlawful.”","And in another narration: “Does one single feeding make marriage unlawful?” He said: “No.”","His statement, “imlajah,” means one suckling. It is said: the child “malaja” his mother when he suckled from her, and “amljat-hu ummuhu” means his mother nursed him."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":18}]},{"num":6696,"demo":false,"sanad":"","matn":["عن أم سلمة قالت: قال رسول الله ﷺ:","«لَا يُحَرِّمُ مِنَ الرَّضَاعَةِ إِلَّا مَا فَتَقَ الْأَمْعَاءَ فِي الثَّدْيِ، وَكَانَ قَبْلَ الْفِطَامِ»."],"takhrij":"صحيح: رواه الترمذي (١١٥٢)، والنسائي في الكبرى (٥٤٤١). وقال الترمذي: حسن صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء أن الرضعات المحرّمة هي الخمس للصغير دون الحولين","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1152) and al-Nasā’ī in al-Sunan al-Kubrā (5441). Al-Tirmidhī said: Hasan Sahih.","chapter_en":"The breastfeeding that causes prohibition is five feedings for the young child under two years","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah reported that the Messenger of Allah ﷺ said: “Breastfeeding does not establish the prohibition of marriage except that which reaches and nourishes the intestines during the period of breastfeeding and occurs before weaning.”"]},"buhuth":{"ar":["وقوله: «فتق الأمعاء» أي شقها ودخل فيها بحيث صار غذاء للولد.","وقوله: «في الثدي» أي في زمن الثدي.","قال الحافظ ابن القيم في زاد المعاد (٥/٥٨٠):","«وهذه لغة معروفة عند العرب، فإن العرب يقولون: فلان مات في الثدي، أي: في زمن الرضاع قبل الفطام»."],"en":["The phrase “opens the intestines” means that the milk enters them in such a way that it becomes nourishment for the child.","The phrase “during breastfeeding” means during the nursing period.","Al-Ḥāfiẓ Ibn al-Qayyim said in Zād al-Maʿād (5/580):","“This is a well-known expression among the Arabs. They say, ‘So-and-so died while at the breast,’ meaning during the nursing period before weaning.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1152},{"key":"nasai/الکبری","label":"النسائي في الكبرى","number":5441},{"key":"kubranasai","label":"السنن الكبرى للنسائي","number":5441,"n":5437}]},{"num":6697,"demo":false,"sanad":"","matn":["عن عائشة أن أبا حذيفة بن عتبة بن ربيعة بن عبد شمس - وكان ممن شهد بدرًا مع النبي ﷺ - تبنّى سالمًا، وأنكحه بنت أخيه هند بنت الوليد بن عتبة بن ربيعة، وهو مولى لامرأة من الأنصار، كما تبنّى النبي ﷺ زيدًا. وكان من تبنّى رجلًا في الجاهلية دعاه الناس إليه وورث من ميراثه، حتى أنزل الله: ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ﴾ [الأحزاب: ٥]، فردوا إلى آبائهم، فمن لم يُعلم له أب كان مولى وأخًا في الدين. فجاءت سهلة بنت سهيل بن عمرو القرشية العامرية - وهي امرأة أبي حذيفة بن عتبة - إلى النبي ﷺ فقالت: يا رسول الله، إنا كنا نرى سالمًا ولدًا، وقد أنزل الله فيه ما قد علمت. فذكرت الحديث."],"takhrij":"صحيح: رواه البخاري (٥٠٨٨).","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5088).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah reported that Abu Hudhayfah ibn ʿUtbah ibn Rabiʿah ibn ʿAbd Shams—who was among those who witnessed Badr with the Prophet ﷺ—had adopted Salim, and married him to the daughter of his brother, Hind bint al-Walid ibn ʿUtbah ibn Rabiʿah. Salim had been the freed slave of a woman from the Ansar, just as the Prophet had adopted Zayd. In the pre-Islamic period, when a man adopted someone, people would call him by the adopter’s name and he would inherit from him, until Allah revealed: “Call them by their fathers’ names; that is more just in the sight of Allah. But if you do not know their fathers, then they are your brothers in religion and your clients.” [al-Ahzab: 5] So they were returned to their fathers, and whoever had no known father was regarded as a client and a brother in faith. Then Sahlah bint Suhayl ibn ʿAmr al-Qurashiyyah al-ʿAmiriyyah—the wife of Abu Hudhayfah ibn ʿUtbah—came to the Prophet and said: “O Messenger of Allah, we used to regard Salim as a son, and Allah has now revealed concerning him what you know,” and then she mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5088}]},{"num":6698,"demo":false,"sanad":"","matn":["عن ابن شهاب قال: أخبرني عروة بن الزبير أن أبا حذيفة بن عتبة بن ربيعة، وكان من أصحاب رسول الله ﷺ وكان قد شهد بدرًا، وكان تبنّى سالمًا الذي يقال له سالم مولى أبي حذيفة، كما تبنّى رسول الله ﷺ زيد بن حارثة. وأنكح أبو حذيفة سالمًا، وهو يرى أنه ابنه، أنكحه بنت أخيه فاطمة بنت الوليد بن عتبة بن ربيعة، وهي يومئذ من المهاجرات الأُوَل، وهي من أفضل أيامى قريش. فلما أنزل الله في كتابه: ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ فَإِنْ لَمْ تَعْلَمُوا آبَاءَهُمْ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ﴾ [الأحزاب: ٥] رُدَّ كل واحد من أولئك إلى أبيه، فإن لم يُعلم أبوه رُدَّ إلى مولاه.","فجاءت سهلة بنت سهيل - وهي امرأة أبي حذيفة، وهي من بني عامر بن لؤي - إلى رسول الله ﷺ فقالت: يا رسول الله، كنا نرى سالمًا ولدًا، وكان يدخل علي وأنا فُضُل، وليس لنا إلا بيت واحد، فماذا ترى في شأنه؟ فقال لها رسول الله ﷺ: «أرضعيه خمس رضعات فيحرم بلبنها». وكانت تراه ابنًا من الرضاعة. فأخذت بذلك عائشة أم المؤمنين فيمن كانت تحب أن يدخل عليها من الرجال، فكانت تأمر أختها أم كلثوم بنت أبي بكر الصديق وبنات أخيها أن يرضعن من أحبت أن يدخل عليها من الرجال. وأبى سائر أزواج النبي ﷺ أن يدخل عليهن بتلك الرضاعة أحد من الناس، وقلن: لا، ما نرى الذي أمر به رسول الله ﷺ إلا رخصة من رسول الله ﷺ في رضاعة سالم وحده. لا والله، لا","يدخل علينا بهذه الرضاعة أحد.","فعلى هذا كان أزواج النبي ﷺ يَرَيْنَ رضاعة الكبير خاصة بسالم."],"takhrij":"صحيح: رواه مالك (١٢) وعبد الرزاق (١٣٨٨٦).","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (12) and ʿAbd al-Razzaq (13886).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Ibn Shihab said: ʿUrwah ibn al-Zubayr informed me that Abu Hudhayfah ibn ʿUtbah ibn Rabiʿah, who was among the Companions of the Messenger of Allah and had witnessed Badr, had adopted Salim, who was known as Salim the freed slave of Abu Hudhayfah, just as the Messenger of Allah had adopted Zayd ibn Harithah. Abu Hudhayfah, regarding Salim as his son, married him to the daughter of his brother, Fatimah bint al-Walid ibn ʿUtbah ibn Rabiʿah, who was then among the earliest female emigrants and one of the finest unmarried women of Quraysh.","When Allah revealed in His Book: “Call them by their fathers’ names; that is more just in the sight of Allah. But if you do not know their fathers, then they are your brothers in religion and your clients” [al-Ahzab: 5], each of them was returned to his real father, and whoever had no known father was returned to his patron. Then Sahlah bint Suhayl—the wife of Abu Hudhayfah, who was from Banu ʿAmir ibn Lu’ayy—came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, we used to regard Salim as a son. He used to enter upon me while I was in an informal state of dress, and we have only one house. What do you think about his case?” The Messenger of Allah ﷺ said to her: “Breastfeed him five times, and he will become unlawful to you through that milk.” So she regarded him as a son through breastfeeding.","ʿA’ishah, Mother of the Believers, adopted that view regarding those men whom she wished to be able to enter upon her. She would instruct her sister Umm Kulthum bint Abi Bakr al-Siddiq and the daughters of her brother to breastfeed those whom she wished to enter upon her among the men. But the rest of the wives of the Prophet refused to allow anyone to enter upon them through such breastfeeding, and they said: “No, by Allah, we do not regard what the Messenger of Allah ordered except as a special concession from the Messenger of Allah concerning Salim alone. No, by Allah, no one will enter upon us through this kind of breastfeeding.”","So based on this, the wives of the Prophet held that the breastfeeding of an adult was specific to Salim."]},"buhuth":{"ar":["وقول سهلة بنت سهيل: «يدخل علي وأنا فُضُل» قال ابن عبد البر: «معنى الحديث عندي أنه كان يدخل عليها، وهي متكشفة بعضها، مثل الشعر واليد والوجه». وقال في صفة إرضاع الكبير: هو أن يُحلب له اللبن فيُسقاه. قال: وأما أن تلقمه المرأة ثديها كما تصنع بالطفل فلا؛ لأن ذلك لا يحل عند جماعة العلماء. انتهى."],"en":["As for the statement of Sahlah bint Suhayl, “He used to enter upon me while I was in an informal state of dress,” Ibn ʿAbd al-Barr said: “The meaning of the hadith, in my view, is that he used to enter upon her while some part of her was uncovered, such as the hair, hand, and face.” He also said regarding how an adult would be breastfed: the milk would be expressed for him and then given to him to drink. As for the woman putting her breast directly in his mouth as is done with an infant, that is not lawful according to a group of scholars. End quote."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":12},{"key":"عبد_الرزاق","label":"عبد الرزاق","number":13886}]},{"num":6699,"demo":false,"sanad":"","matn":["عن عائشة قالت: جاءت سهلة بنت سهيل إلى النبي ﷺ فقالت: يا رسول الله، إني أرى في وجه أبي حذيفة من دخول سالم - وهو حليفه - فقال النبي ﷺ: «أرضعيه». قالت: وكيف أرضعه وهو رجل كبير؟ فتبسم رسول الله ﷺ وقال: «قد علمت أنه رجل كبير».","وفي رواية: ((أرْضِعيه تحرُمي عليه، ويذهبُ الذي في نفس أبي حذيفة)) فرجعت فقالت: إني قد","أرضعتُه، فذهب الذي في نفس أبي حذيفة."],"takhrij":"صحيح: رواه مسلم (١٤٥٣).","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1453).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: Sahlah bint Suhayl came to the Prophet ﷺ and said: “O Messenger of Allah, I can see displeasure on the face of Abu Hudhayfah because of Salim entering upon us, and he is his client.” So the Prophet ﷺ said: “Breastfeed him.” She said: “How can I breastfeed him when he is a grown man?” The Messenger of Allah ﷺ smiled and said: “I know that he is a grown man.”","In another narration: “Breastfeed him, and he will become unlawful for you, and what is in the heart of Abu Hudhayfah will go away.” She then returned and said: “I have breastfed him, and what was in the heart of Abu Hudhayfah has gone away.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1453}]},{"num":6700,"demo":false,"sanad":"","matn":["عن عائشة قالت: جاءت سهلة بنت سهيل إلى رسول الله ﷺ فقالت: يا رسول الله، إن سالمًا يُدعى لأبي حذيفة، ويأوي معه، ويدخل علي وأنا فُضُل، ونحن في منزل ضيق. وقال الله تعالى: ﴿ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ﴾ [الأحزاب: ٥]. فقال: «أرضعيه تحرمي عليه»."],"takhrij":"صحيح: رواه عبد الرزاق (١٣٨٨٥).","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzaq (13885).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿA’ishah said: Sahlah bint Suhayl came to the Messenger of Allah and said: “O Messenger of Allah, Salim is attributed to Abu Hudhayfah, lives with him, and enters upon me while I am in an informal state of dress, and we live in a small dwelling. And Allah the Exalted has said: ‘Call them by their fathers’ names; that is more just in the sight of Allah.’” [al-Ahzab: 5] So he said: “Breastfeed him, and he will become unlawful for you.”"]},"buhuth":{"ar":["قال الزهري: “قالت بعض أزواج النبي ﷺ لا ندري لعل هذه كانت رخصة لسالم خاصة. وقال","الزهري: “وكانت عائشةُ تُفتي بأنه يُحرّم الرضاع بعد الفصال حتى ماتت”.","وقولها: ((فُضُل)) أي مبتذلة وهي المرأة إذا لبستْ ثيابَ مهنتِها."],"en":["Al-Zuhri said: “Some of the wives of the Prophet said: We do not know; perhaps this was a special concession for Salim alone.”","Al-Zuhri also said: “ʿA’ishah continued to give legal rulings that breastfeeding after weaning could establish prohibition until she died.”","Her statement, “fudul,” means dressed informally, that is, when a woman is wearing her ordinary working clothes."]}},"tuhfa":{},"refs":[{"key":"عبد_الرزاق","label":"عبد الرزاق","number":13885}]},{"num":6701,"demo":false,"sanad":"","matn":["عن زينب بنت أم سلمة قالت: قالت أم سلمة لعائشة: إنه يدخل عليك الغلام الأيفعُ الذي ما أحب أن يدخل عليّ. قال: فقالت عائشة: أما لك في رسول الله ﷺ أسوة؟ قالت: إن امرأة أبي حذيفة قالت: يا رسول الله! إن سالماً يدخل عليّ وهو رجل، وفي نفس أبي حذيفة منه شيء.","فقال رسول الله ﷺ: ((أرْضِعيه حتى يدخلَ عليكِ))"],"takhrij":"صحيح: رواه مسلم (٢٩:١٤٥٣).","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (29:1453).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Zaynab bint Umm Salamah said: Umm Salamah said to ʿA’ishah: “A nearly grown boy enters upon you, and I would not like such a one to enter upon me.” ʿA’ishah said: “Do you not have in the Messenger of Allah ﷺ an example?” The wife of Abu Hudhayfah said: “O Messenger of Allah, Salim enters upon me while he is a grown man, and Abu Hudhayfah feels something about that.” So the Messenger of Allah said: “Breastfeed him so that he may enter upon you.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":29}]},{"num":6702,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي ﷺ أنها كانت تقول: أبى سائرُ أزواج النبي ﷺ أن يُدخِلْنَ","عليهن أحدًا بتلك الرضاعة، وقلن لعائشة: والله ما نرى هذه إلا رخصة أرخصها رسول الله ﷺ لسالم","خاصة، فما هو بداخل علينا أحدٌ بهذه الرضاعة، ولا رائينا."],"takhrij":"صحيح: رواه مسلم (١٤٥٤).","grade":"صحيح","chapter_ar":"باب ما جاء في رضاعة الكبير","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1454).","chapter_en":"Chapter on what has been reported concerning the breastfeeding of an adult","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, used to say: The rest of the wives of the Prophet ﷺ refused to allow anyone to enter upon them through that kind of breastfeeding, and they said to ʿA’ishah: “By Allah, we do not see this except as a special concession given by the Messenger of Allah ﷺ for Salim alone. No one will enter upon us through such breastfeeding, nor will we hold that view.”"]},"buhuth":{"ar":["أحاديث الباب تدل على أنه لا يثبت التحريم برضاعة الكبير، وقصة سالم مولى أبي حذيفة خاصة به، وهي رخصة أرخصها رسول الله ﷺ لسالم. وكانت عائشة ترى أن رضاعة الكبير تُحرِّم، وخالفها سائر أمهات المؤمنين، ولم يوافقها عليها أحد من الصحابة."],"en":["The hadiths of this chapter indicate that prohibition is not established by the breastfeeding of an adult, and the story of Salim, the freed slave of Abu Hudhayfah, was specific to him. It was a special concession granted by the Messenger of Allah for Salim. ʿA’ishah held that adult breastfeeding established prohibition, but the rest of the Mothers of the Believers disagreed with her, and no other Companion agreed with her on that."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1454}]},{"num":6703,"demo":false,"sanad":"","matn":["عن عقبة بن الحارث قال: تزوجت امرأة، فجاءتنا امرأة سوداء فقالت: أرضعتكما. فأتيت النبي ﷺ فقلت: تزوجت فلانة بنت فلان، فجاءتنا امرأة سوداء فقالت لي: إني قد أرضعتكما، وهي كاذبة. فأعرض، فأتيته من قِبَل وجهه، قلت: إنها كاذبة. قال: «كيف بها وقد زعمت أنها قد أرضعتكما؟ دعها عنك»."],"takhrij":"صحيح: رواه البخاري (٥١٠٤).","grade":"صحيح","chapter_ar":"باب شهادة المرضِعة","chapter_ur":"","part_ar":"كتاب الرضاعة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5104).","chapter_en":"The testimony of the woman who breastfed","part_en":"Book of Breastfeeding","group_ar":"","group_en":"","part_no":30,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿUqbah ibn al-Harith said: I married a woman, then a black woman came to us and said: “I breastfed both of you.” So I came to the Prophet ﷺ and said: “I married so-and-so, daughter of so-and-so, and a black woman came to us and told me that she had breastfed both of us, but she is lying.” He turned away. Then I came to him again from the other side and said: “She is lying.” He said: “How can you remain with her after she has claimed that she breastfed both of you? Leave her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5104}]},{"num":6704,"demo":false,"sanad":"","matn":["عن أبي هريرة عن النبي ﷺ قال: (( سبعة يظلهم اللّٰه يوم القيامة في ظله يومَ لا ظلَّ إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل ذكر اللّٰه في خلاء، ففاضت عيناه، ورجل قلبه معلق في المسجد، ورجلان تحابا في الله، ورجل دعته امرأة ذات منصب وجمالٍ إلى نفسها، قال: إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما صنعت يمينه )."],"takhrij":"متفق عليه: رواه البخاري (٦٨٠٦)، ومسلم (١٠٣١:٩١).","grade":"متفق عليه","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6806) and Muslim (1031:91).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “There are seven whom Allah will shade in His Shade on the Day of Resurrection when there is no shade except His Shade: a just ruler; a youth who grew up in the worship of Allah; a man who remembered Allah in private and his eyes overflowed with tears; a man whose heart is attached to the mosque; two men who love each other for the sake of Allah; a man whom a woman of position and beauty invited to herself, and he said, ‘Indeed, I fear Allah’; and a man who gave charity and hid it so that his left hand did not know what his right hand had spent.”"]},"intro":{"ar":["قال تعالى: ( إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا الْأَمَانَاتِ إِلَىٰ أَهْلِهَا وَإِذَا حَكَمْتُم بَيْنَ النَّاسِ أَن تَحْكُمُوا بِالْعَدْلِ) [النساء: ٥٨]","وقال لنبيه: ﴿وَأَنِ احْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ وَاحْذَرْهُمْ أَن يَفْتِنُوكَ عَن بَعْضِ مَا أَنزَلَ اللَّهُ إِلَيْكَ﴾ [المائدة: ٤٩]","وقال تعالى: ( وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قومٍ عَلَىٰ أَلَّا تَعْدِلُوا ۚ اعْدِلُوا هُوَ أَقْرَبُ لِلتَّقْوَىٰ) [المائدة: ٨]"],"en":["Allah the Exalted said: “Indeed, Allah commands you to render trusts to their owners and when you judge between people to judge with justice.” [Surat al-Nisa’: 58]","And He said to His Prophet ﷺ: “And judge between them by what Allah has revealed and do not follow their inclinations and beware of them, lest they tempt you away from some of what Allah has revealed to you.” [Surat al-Ma’idah: 49]","And the Exalted said: “And do not let the hatred of a people lead you to not be just. Be just; that is nearer to righteousness.” [Surat al-Ma’idah: 8]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6806},{"key":"muslim","label":"مسلم","number":1031}]},{"num":6705,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو قال: قال رسول اللّٰه ﷺ: (( إن المقسطين عند اللّٰه على منابر من نور، عن يمين الرحمن عز وجل، وكلتا يديه يمينٌ، الذين يعدلون في حكمهم وأهليهم وما ولوا))."],"takhrij":"صحيح: رواه مسلم (١٨٢٧).","grade":"صحيح","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1827).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “Indeed, the just will be with Allah on thrones of light, at the right hand of the Most Merciful, the Mighty and Sublime—and both of His hands are right hands—those who are just in their ruling, with their families, and in what they have been placed in charge of.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1827}]},{"num":6706,"demo":false,"sanad":"","matn":["عن عياض بن حمار المجاشعي أن نبي اللّٰه ﷺ قال ذات يوم في خطبته فذكر الحديث: قال: (( أهل الجنة ثلاثة: ذو سلطان مقسط متصدق موفق، ورجل رحيم رقيق القلب لكل ذي قربى ومسلم، وعفيف متعفف ذو عيال... )) فذكر الحديث."],"takhrij":"صحيح: رواه مسلم (٢٨٦٥).","grade":"صحيح","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2865).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿIyad ibn Himar al-Mujashiʿi narrated that the Prophet of Allah ﷺ said one day in his sermon, and he mentioned the hadith: He said: “The people of Paradise are three types: a person of authority who is just, gives charity, and is guided to success; a merciful man who is soft-hearted to every relative and Muslim; and a chaste man who refrains from begging despite having a family…” and he mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":2865}]},{"num":6707,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( ثلاثة لا ترد دعوتهم: الإمام العادل، والصائم حتى يُفطر، ودعوة المظلوم تحمل على الغمام، وتُفتح لها أبوابُ السماء، ويقول الرب: وعزتي لأنصرنك ولو بعد حين ))."],"takhrij":"حسن: رواه الترمذي (٣٥٩٨)، وابن ماجه (١٧٥٢)، وأبوداود الطيالسي (٢٧٠٧) وصحّحه ابن حبان (٣٤٢٨).","grade":"حسن","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (3598), Ibn Majah (1752), and Abu Dawud al-Tayalisi (2707), and graded authentic (Sahih) by Ibn Hibban (3428).","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “There are three whose supplication is not rejected: the just ruler, the fasting person until he breaks his fast, and the supplication of the oppressed person, which is raised above the clouds and the gates of heaven are opened for it, and the Lord says: ‘By My Might, I will surely grant you victory, even if it is after some time.’”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":3598},{"key":"ibnmajah","label":"ابن ماجه","number":1752},{"key":"ابوداود_الطیالسی","label":"أبوداود الطيالسي","number":2707},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":3428},{"key":"tayalisi","label":"مسند أبي داود الطيالسي","number":2707,"n":2707},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":5179,"n":5175}]},{"num":6708,"demo":false,"sanad":"","matn":["عن أبي أيوب قال: قال رسول اللّٰه ﷺ: (( يد اللّه مع القاضي حين يقضي، ويد اللّٰه مع القاسم حين يَقسم )."],"takhrij":"حسن: رواه أحمد (٢٣٥١١). وقوله: ((يد اللّه مع القاضي)): يعني إذا قضى بالعدل.","grade":"حسن","chapter_ar":"باب العدل في القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ahmad (23511). His saying, “The hand of Allah is with the judge,” means when he judges with justice.","chapter_en":"Justice in Judgement","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Ayyub said: The Messenger of Allah ﷺ said: “The hand of Allah is with the judge when he judges, and the hand of Allah is with the distributor when he distributes.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":23511,"n":23511}]},{"num":6709,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: قال رسول اللّٰه ﷺ: (( لا حسدَ إلا في اثنتين: رجلٌ آتاه الله مالاً، فسلّطه على هلكته في الحق، وآخر آتاه اللّٰه حكمةً فهو يقضي بها ويعلِّمها ))."],"takhrij":"متفق عليه: رواه البخاري (٧١٤١)، ومسلم (٨١٦).","grade":"متفق عليه","chapter_ar":"باب فضل من أوتي الحكمة فقضى بها","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7141) and Muslim (816).","chapter_en":"The virtue of one who is granted wisdom and judges by it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn Masʿud said: The Messenger of Allah ﷺ said: “There is no envy except in two cases: a man whom Allah has given wealth and empowered him to spend it entirely in the cause of truth, and a man whom Allah has given wisdom and he judges by it and teaches it.”"]},"buhuth":{"ar":["قال الحافظ: \"وفي الحديث الترغيب في ولاية القضاء لمن استجمع شروطه، وقوي على أعمال الحق، ووجد له أعوانا لما فيه من الأمر بالمعروف ونصر المظلوم، وأداء الحق لمستحقه وكف يد الظالم والإصلاح بين الناس، وكل ذلك من القربات، ولذلك تولاه الأنبياء ومن بعدهم من الخلفاء الراشدين، ومن ثمّ اتفقوا على أنه من فروض الكفاية؛ لأن أمر الناس لا يستقيم بدونه\". الفتح (١٢١/١٣)."],"en":["Al-Hafiz (Ibn Hajar) said: “In this hadith, there is an encouragement to assume the position of judgeship for whoever meets its conditions, is strong enough to implement the truth, and finds helpers for it, because it involves enjoining what is right, assisting the oppressed, delivering rights to those entitled to them, restraining the hand of the oppressor, and making peace between people. All of these are acts of drawing near to Allah. For this reason, it was undertaken by the Prophets and after them by the Rightly Guided Caliphs. Hence, they agreed that it is a communal obligation (Fard Kifayah), because the affairs of people cannot be set straight without it.” Fath al-Bari (13/121)."]},"intro":{"ar":["قال اللّٰه تعالى: ( يُؤْتَى الْحِكْمَةَ مَن يَشَاءُ ۚ وَمَن يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْرًا كَثِيرًا ) [البقرة: ٢٦٩]"],"en":["Allah the Exalted said: “He gives wisdom to whom He wills, and whoever has been given wisdom has certainly been given much good.” [Surat al-Baqarah: 269]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7141},{"key":"muslim","label":"مسلم","number":816}]},{"num":6710,"demo":false,"sanad":"","matn":["عن عبد الله بن أبي أوفى قال: قال رسول اللّه ﷺ (( إن اللّه مع القاضي ما لم يَجُر، فإذا جار تخلى عنه، ولزمه الشيطان )."],"takhrij":"حسن: رواه الترمذي (١٣٣٠) وحسّنه، وصحّحه ابن حبان (٥٠٦٢)، والحاكم (٩٣/٤) والبيهقي (٨٨/١٠).","grade":"حسن","chapter_ar":"باب أن الله مع القاضي العدل، فإذا جار تخلّى عنه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1330) who graded it Hasan, and authenticated (Sahih) by Ibn Hibban (5062), al-Hakim (4/93), and al-Bayhaqi (10/88).","chapter_en":"Indeed, Allah is with the just judge, but if he acts unjustly, Allah leaves him","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn Abi Awfa said: The Messenger of Allah ﷺ said: “Indeed, Allah is with the judge as long as he does not tyrannize. If he acts unjustly, Allah leaves him and the Devil stays with him.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1330},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5062},{"key":"hakim","label":"الحاكم","number":93},{"key":"البیہقی","label":"البيهقي","number":88},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20451,"n":20609}]},{"num":6711,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو قال: قال رسول اللّٰه ﷺ: (( لعنة اللّٰه على الراشي والمرتشي))."],"takhrij":"حسن: رواه أبو داود (٣٥٨٠)، والترمذي (١٣٣٧)، وابن ماجه (٢٣١٣)، قال الترمذي: \"حسن صحيح\".","grade":"حسن","chapter_ar":"باب التغليظ من قبول الرشوة في الحكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3580), al-Tirmidhi (1337), and Ibn Majah (2313). Al-Tirmidhi said: “Hasan Sahih.”","chapter_en":"The severe warning against accepting bribes in judgment","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullah ibn ʿAmr said: The Messenger of Allah ﷺ said: “The curse of Allah is upon the one who offers a bribe and the one who takes it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3580},{"key":"tirmidhi","label":"الترمذي","number":1337},{"key":"ibnmajah","label":"ابن ماجه","number":2313}]},{"num":6712,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لعن رسول اللّٰه ﷺ الراشي والمرتشي في الحكم."],"takhrij":"حسن: رواه الترمذي (١٣٣٦)، وأحمد (٩٠٢٣)، وابن الجارود (٥٨٥) وصحّحه ابن حبان (٥٠٧٦).","grade":"حسن","chapter_ar":"باب التغليظ من قبول الرشوة في الحكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhi (1336), Ahmad (9023), and Ibn al-Jarud (585), and authenticated (Sahih) by Ibn Hibban (5076).","chapter_en":"The severe warning against accepting bribes in judgment","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ cursed the one who offers a bribe and the one who takes it in judgment."]},"buhuth":{"ar":["وقوله: (( الراشي)) وهو المعطي، و(( المرتشي)) وهو الآخذ، وإنما يلحقهما العقوبة معا إذا استويا في القصد والإرادة، فرشا المعطي لينال به باطلا، ويتوصل به إلى ظلم، وأما إذا أعطى ليتوصل به إلى حق، أو يدفع عن نفسه ظلما فإنه غير داخل في هذا الوعيد\" ذكره الخطابي."],"en":["His saying: “‘al-Rashi’ (the briber) is the giver, and ‘al-Murtashi’ (the bribed) is the taker. The punishment only applies to both of them together when they are equal in intent and will, meaning the giver offers the bribe to obtain something false or to commit an injustice. However, if he gives it to reach a right or to fend off an injustice from himself, then he is not included in this threat.” This was mentioned by al-Khattabi."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1336},{"key":"ابن_الجارود","label":"ابن الجارود","number":585},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5076},{"key":"ahmad","label":"مسند الإمام أحمد","number":9023,"n":9023}]},{"num":6713,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( من وليَ القضاء، فقد ذبح بغير سكين ))."],"takhrij":"حسن: رواه أبوداود (٣٥٧١)، والترمذي (١٣٢٥) وحسّنه، والدارقطني (٢٠٤/٤)، والبيهقي (٩٦/١٠).","grade":"حسن","chapter_ar":"باب الترهيب من تولى القضاء لمن لا يثق بنفسه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3571), and al-Tirmidhi (1325) who graded it Hasan, al-Daraqutni (4/204), and al-Bayhaqi (10/96).","chapter_en":"Warning against assuming judgeship for one who does not trust himself","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever is appointed as a judge has been slaughtered without a knife.”"]}},"tuhfa":{},"refs":[{"key":"ابوداود","label":"أبوداود","number":3571},{"key":"tirmidhi","label":"الترمذي","number":1325},{"key":"الدارقطنی","label":"الدارقطني","number":204},{"key":"البیہقی","label":"البيهقي","number":96},{"key":"sh9771","label":"سنن الدارقطني","number":4462,"n":4474},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20220,"n":20378}]},{"num":6714,"demo":false,"sanad":"","matn":["عن عمرو بن العاص أنه سمع رسول اللّٰه ﷺ يقول: (( إذا حكم الحاكم فاجتهد ثم أصاب فله أجران، وإذا حكم فاجتهد ثم أخطأ فله أجر )."],"takhrij":"متفق عليه: رواه البخاري في الاعتصام بالكتاب والسنة (٧٣٥٢) ومسلم في الأقضية (١٧١٦:١٥).","grade":"متفق عليه","chapter_ar":"باب في القاضي يخطئ","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari in the Chapter of Adherence to the Book and Sunnah (7352) and Muslim in the Chapter of Judgments (1716:15).","chapter_en":"Regarding the judge who makes a mistake","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn al-ʿAs narrated that he heard the Messenger of Allah ﷺ saying: “If a judge passes judgment having striven to reach the correct decision (ijtihad) and is correct, he will have a double reward; and if he passes judgment having striven to reach the correct decision and makes a mistake, he will have a single reward.”"]}},"tuhfa":{},"refs":[{"key":"bukhari/الاعتصام_بالکتاب_والسنہ","label":"البخاري في الاعتصام بالكتاب والسنة","number":7352},{"key":"muslim/الاقضیہ","label":"مسلم في الأقضية","number":1716}]},{"num":6715,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( إذا حكم الحاكم فاجتهد فأصاب فله أجران، وإذا حكم فأخطأ فله أجر واحد))."],"takhrij":"صحيح: رواه الترمذي (١٣٢٦) وحسّنه، والنسائي (٥٣٨١)، وابن الجارود (٩٩٦)، وصحّحه ابن حبان (٥٠٦٠).","grade":"صحيح","chapter_ar":"باب في القاضي يخطئ","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1326) who graded it Hasan, al-Nasa’i (5381), Ibn al-Jarud (996), and authenticated (Sahih) by Ibn Hibban (5060).","chapter_en":"Regarding the judge who makes a mistake","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “If a judge passes judgment having striven to reach the correct decision and is correct, he will have a double reward; and if he passes judgment and makes a mistake, he will have a single reward.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1326},{"key":"nasai","label":"النسائي","number":5381},{"key":"ابن_الجارود","label":"ابن الجارود","number":996},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5060},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":720,"n":720}]},{"num":6716,"demo":false,"sanad":"","matn":["عن بريدة بن الحصيب عن النبي ﷺ قال: (( القضاة ثلاثة، واحد في الجنة، واثنان في النار: فأما الذي في الجنة فرجل عرف الحق فقضى به، ورجل عرف الحق فجار في الحكم فهو في النار، ورجل قضى للناس على جهل فهو في النار))."],"takhrij":"حسن: رواه أبوداود (٣٥٧٣)، وابن ماجه (٢٣١٥)، والطحاوي في مشكله (٥٥)، والبيهقي (١١٦/١٠).","grade":"حسن","chapter_ar":"باب في القاضي يخطئ","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3573), Ibn Majah (2315), al-Tahawi in Mushkil al-Athar (55), and al-Bayhaqi (10/116).","chapter_en":"Regarding the judge who makes a mistake","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Buraydah ibn al-Husayb narrated that the Prophet ﷺ said: “Judges are of three types: one will be in Paradise and two in the Fire. As for the one in Paradise, he is a man who knew the truth and judged according to it. A man who knew the truth but acted unjustly in his judgment will be in the Fire. And a man who judged for the people out of ignorance will be in the Fire.”"]}},"tuhfa":{},"refs":[{"key":"ابوداود","label":"أبوداود","number":3573},{"key":"ibnmajah","label":"ابن ماجه","number":2315},{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":55},{"key":"البیہقی","label":"البيهقي","number":116}]},{"num":6717,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن سمرة قال: قال النبي ﷺ: (( يا عبد الرحمن بن سمرة لا تسأل الإمارة، فإنك إن أوتيتها عن مسألة وكلت إليها، وإن أوتيتها من غير مسألة أعنت عليها))."],"takhrij":"متفق عليه: رواه البخاري (٦٦٢٢) ومسلم (١٦٥٢).","grade":"متفق عليه","chapter_ar":"باب من ولي القضاء بدون طلب منه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6622) and Muslim (1652).","chapter_en":"One who is appointed to judgeship without requesting it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Samurah said: The Prophet ﷺ said: “O ʿAbd al-Rahman ibn Samurah, do not ask for leadership, for if you are given it as a result of asking, you will be left to deal with it alone; but if you are given it without asking, you will be helped in it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6622},{"key":"muslim","label":"مسلم","number":1652}]},{"num":6718,"demo":false,"sanad":"","matn":["عن عائشة قالت: قال رسول اللّٰه ﷺ: (( إذا أراد اللّه بالأمير خيراً جعل له وزير صدق، إن نسي ذكّره، وإن ذكر أعانه، وإذا أراد اللّٰه به غير ذلك جعل له وزير سوء، إن نسي لم يذكّره، وإن ذكر لم يُعنه )."],"takhrij":"صحيح: رواه أبو داود (٢٩٣٢) واللفظ له، والنسائي (٤٢٠٤) وأحمد (٢٤٤١٤) وابن حبان (٤٤٩٤).","grade":"صحيح","chapter_ar":"باب من ولي القضاء بدون طلب منه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (2932) and the wording is his, al-Nasa’i (4204), Ahmad (24414), and Ibn Hibban (4494).","chapter_en":"One who is appointed to judgeship without requesting it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAishah said: The Messenger of Allah ﷺ said: “If Allah intends good for a leader, He appoints for him a truthful minister (advisor); if he forgets, he reminds him, and if he remembers, he helps him. But if Allah intends otherwise for him, He appoints for him an evil minister; if he forgets, he does not remind him, and if he remembers, he does not help him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2932},{"key":"nasai","label":"النسائي","number":4204},{"key":"ahmad","label":"مسند الإمام أحمد","number":24414,"n":24414},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4517,"n":4513}]},{"num":6719,"demo":false,"sanad":"","matn":["عن عائشة أنها قالت: كان عتبة بن أبي وقاص، عهد إلى أخيه سعد بن أبي وقاص، أن ابن وليدة زمعة مني، فاقبضه إليك، قالت: فلما كان عام الفتح أخذه سعد. وقال: ابن أخي، قد كان عهد إلي فيه، فقام إليه عبد بن زمعة فقال: أخي، وابن وليدة أبي، ولد على فراشه، فتساوقا إلى رسول اللّٰه ﷺ فقال سعد: يا رسول الله ﷺ! ابن أخي، قد كان عهد إليّ فيه، وقال عبد بن زمعة: أخي، وابن وليدة أبي، ولد على فراشه، فقال رسول اللّٰه ﷺ: (( هو لك يا عبد بن زمعة )) ثم قال رسول اللّٰه ﷺ: (( الولد للفراش وللعاهر الحجر )) ثم قال لسودة بنت زمعة: (( احتجبي منه )) لما رأى من شبهه بعتبة ابن أبي وقاص. قالت: فما رآها حتى لقي اللّٰه عز وجل."],"takhrij":"متفق عليه: رواه مالك (٢٠) والبخاري (٧١٨٢) ومسلم (٣٦:١٤٥٧).","grade":"متفق عليه","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (20), al-Bukhari (7182), and Muslim (1457:36).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿAishah said: ʿUtbah ibn Abi Waqqas entrusted his brother, Saʿd ibn Abi Waqqas, saying, “The son of the slave-girl of Zamʿah is my son, so take custody of him.” She said: In the year of the Conquest (of Makkah), Saʿd took him and said, “He is my nephew; my brother entrusted him to me.” ʿAbd ibn Zamʿah stood up and said, “He is my brother and the son of my father’s slave-girl, born on his bed.” They both rushed to the Messenger of Allah ﷺ. Saʿd said, “O Messenger of Allah ﷺ! He is my nephew; my brother entrusted him to me.” And ʿAbd ibn Zamʿah said, “He is my brother and the son of my father’s slave-girl, born on his bed.” The Messenger of Allah ﷺ said, “He is for you, O ʿAbd ibn Zamʿah.” Then the Messenger of Allah ﷺ said, “The child belongs to the bed (marriage), and for the adulterer is the stone.” Then he said to Sawdah bint Zamʿah, “Observe hijab before him,” due to the resemblance he saw in him to ʿUtbah ibn Abi Waqqas. She said: He never saw her until he met Allah, the Mighty and Sublime."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":20},{"key":"bukhari","label":"البخاري","number":7182},{"key":"muslim","label":"مسلم","number":36}]},{"num":6720,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي ﷺ، أن رسول اللّٰه ﷺ قال: (( إنما أنا بشر، وإنكم تختصمون إليّ، فلعل بعضكم أن يكون ألحن بحجته من بعض، فأقضي له على نحو ما أسمع منه، فمن قضيت له بشيء من حق أخيه، فلا يأخذن منه شيئاً، فإنما أقطع له قطعة من النار))."],"takhrij":"متفق عليه: رواه مالك (١) والبخاري (٧١٦٩) ومسلم (٤:١٧١٣).","grade":"متفق عليه","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (1), al-Bukhari (7169), and Muslim (1713:4).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated that the Messenger of Allah ﷺ said: “I am only a human being, and you bring your disputes to me. Perhaps some of you are more eloquent in presenting their argument than others, so I judge in his favor based on what I hear from him. Therefore, if I judge in anyone’s favor concerning something that belongs to his brother, he must not take any of it, for I am only cutting out for him a piece of the Fire.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":7169},{"key":"muslim","label":"مسلم","number":4}]},{"num":6721,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي ﷺ أن رسول اللّٰه ﷺ سمع خصومة بباب حجرته، فخرج إليهم فقال: (( إنما أنا بشر، وإنه يأتيني الخصم، فلعلّ بعضكم أن يكون أبلغ من بعض، فأحسب أنه صادق فأقضي له بذلك، فمن قضيت له بحق مسلم، فإنما هي قطعة من النار، فليأخذها أو ليتركها ))."],"takhrij":"متفق عليه: رواه البخاري (٧١٨١)، ومسلم (٥:١٧١٣).","grade":"متفق عليه","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7181) and Muslim (1713:5).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated that the Messenger of Allah ﷺ heard a dispute at the door of his room, so he came out to them and said: “I am only a human being, and disputants come to me. Perhaps some of you are more eloquent than others, so I think he is truthful and judge in his favor accordingly. Therefore, if I judge in anyone’s favor concerning the right of a Muslim, it is only a piece of the Fire, so let him take it or leave it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7181},{"key":"muslim","label":"مسلم","number":5}]},{"num":6722,"demo":false,"sanad":"","matn":["عن أم سلمة قالت: جاء رجلان من الأنصار إلى رسول اللّٰه ﷺ يختصمان في مواريث بينهما قد درست، ليس بينهما بينة، فقال النبي ﷺ: (( إنكم تختصمون إلي، وإنما أنا بشر، ولعل بعضكم أن يكون ألحن بحجته من بعض، وإنما أقضي بينكم على نحو ما أسمع منكم، فمن قضيت له من أخيه شيئا فلا يأخذه، فإنما أقطع له قطعة من النار، يأتي به إسطاما في عنقه يوم القيامة ))، قال: فبكى الرجلان،","وقال كل واحد منهما: حقي لأخي، فقال رسول اللّٰه ﷺ: (( أما إذ فعلتما هذا، فاذهبا فاقتسما وتوخيا الحق، ثم استهما، ثم يتحلل كل واحد منكما صاحبه ))."],"takhrij":"حسن: رواه أبو داود (٣٥٨٤،٣٥٨٥) وأحمد (٢٦٧١٧) والدارقطني (٢٣٨/٤-٢٣٩) والحاكم (٩٥/٤).","grade":"حسن","chapter_ar":"باب حكم القاضي لا يُحِلّ حراماً، ولا يُحَرِّمُ حلالاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3584, 3585), Ahmad (26717), al-Daraqutni (4/238-239), and al-Hakim (4/95).","chapter_en":"The judge’s ruling does not make a forbidden thing lawful, nor does it make a lawful thing forbidden","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Umm Salamah said: Two men from the Ansar came to the Messenger of Allah ﷺ disputing over old inheritance shares between them that had worn away, and they had no proof. The Prophet ﷺ said: “You bring your disputes to me, and I am only a human being. Perhaps some of you are more eloquent in presenting their argument than others, and I only judge between you based on what I hear from you. Therefore, if I judge in anyone’s favor concerning something belonging to his brother, he must not take it, for I am only cutting out for him a piece of the Fire, which he will bring as a yoke around his neck on the Day of Resurrection.” She said: The two men wept, and each of them said, “My right is for my brother.” The Messenger of Allah ﷺ said: “Since you have done this, go and divide it, seek what is right, then draw lots, and let each of you declare the other free of blame.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3584},{"key":"الدارقطنی","label":"الدارقطني","number":238},{"key":"hakim","label":"الحاكم","number":95},{"key":"ahmad","label":"مسند الإمام أحمد","number":26717,"n":26717}]},{"num":6723,"demo":false,"sanad":"","matn":["عن أبي هريرة، أن رسول اللّٰه ﷺ قال: (( كانت امرأتان معهما ابناهما، جاء الذئب، فذهب بابن إحداهما، فقالت لصاحبتها: إنما ذهب بابنك، وقالت الأخرى: إنما ذهب بابنك، فتحاكما إلى داود عليه السلام، فقضى به للكبرى، فخرجتا على سليمان بن داود عليهما السلام، فأخبرتاه، فقال: ائتوني بالسّكين أشقه بينهما، فقالت الصغرى: لا تفعلْ يرحمك اللّٰه هو ابنها، فقضى به للصغرى))."],"takhrij":"متفق عليه: رواه البخاري (٦٧٦٩)، ومسلم (١٧٢٠).","grade":"متفق عليه","chapter_ar":"باب نقض حكم القاضي إذا ظهر الحق بخلافه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6769) and Muslim (1720).","chapter_en":"Overturning the judge’s ruling if the truth appears contrary to it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated that the Messenger of Allah ﷺ said: “There were two women who had their two sons with them. A wolf came and took away the son of one of them. She said to her companion, ‘It took your son!’ The other said, ‘No, it took your son!’ So they took their case to David (peace be upon him), and he judged in favor of the elder woman. They left and went to Solomon, the son of David (peace be upon them both), and informed him. He said, ‘Bring me a knife so I may cut him in half between the two of you.’ The younger woman said, ‘Do not do that, may Allah have mercy on you! It is her son.’ So he judged in favor of the younger woman.”"]},"buhuth":{"ar":["قال ابن الجوزي: \"استنبط سليمان لما رأى الأمر محتملاً فأجاد، وكلاهما حكما بالاجتهاد، لأنه لو كان داود حكم بالنص لما ساغ لسليمان أن يحكم بخلافه\" فتح الباري (٤٦٥/٦)."],"en":["Ibn al-Jawzi said: “Solomon deduced the truth when he saw the matter was ambiguous, and he did excellently. Both of them judged by independent reasoning (ijtihad), because if David had judged based on a direct textual revelation, it would not have been permissible for Solomon to judge contrary to it.” Fath al-Bari (6/465)."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَدَاوُودَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ فِي الْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ وَكُنَّا لِحُكْمِهِمْ شَاهِدِينَ ۝ فَفَهَّمْنَاهَا سُلَيْمَانَ ۚ وَكُلًّا آتَيْنَا حُكْمًا وَعِلْمًا﴾ [الأنبياء: ٧٨-٧٩]"],"en":["Allah the Exalted said: “And David and Solomon, when they gave judgment concerning the field when the sheep of a people pastured therein at night, and We were witness to their judgment. And We gave understanding of the case to Solomon, and to each of them We gave judgment and knowledge.” [Surat al-Anbiya’: 78-79]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6769},{"key":"muslim","label":"مسلم","number":1720}]},{"num":6724,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( إنما أنا بشر، ولعل بعضكم أن يكون ألحن بحجته من بعض، فمن قطعت له من حق أخيه قطعة فإنما أقطع له قطعة من النار))."],"takhrij":"حسن: رواه ابن ماجه (٢٣١٨) وأحمد (٨٣٩٤) وصحّحه ابن حبان (٥٠٧١).","grade":"حسن","chapter_ar":"باب نقض حكم القاضي إذا ظهر الحق بخلافه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (2318) and Ahmad (8394), and authenticated (Sahih) by Ibn Hibban (5071).","chapter_en":"Overturning the judge’s ruling if the truth appears contrary to it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I am only a human being, and perhaps some of you are more eloquent in presenting their argument than others. Therefore, if I cut off a piece from the right of his brother for him, I am only cutting out for him a piece of the Fire.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2318},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5071},{"key":"ahmad","label":"مسند الإمام أحمد","number":8394,"n":8394},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":2045,"n":2042}]},{"num":6725,"demo":false,"sanad":"","matn":["عن أبي ذر قال: قلت: يا رسول الله ﷺ! ألا تستعملني؟ قال: فضرب بيده على منكبي ثم قال: (( يا أبا ذر إنك ضعيف، وإنها أمانة، وإنها يوم القيامة خزي وندامة إلا من أخذها بحقها، وأدى الذي عليه فيها))."],"takhrij":"صحيح: رواه مسلم (١٨٢٥).","grade":"صحيح","chapter_ar":"باب في التوجيهات النبوية لمن يطلب القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1825).","chapter_en":"Regarding prophetic directives for whoever seeks judgeship","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu Dharr said: I said, “O Messenger of Allah ﷺ! Will you not appoint me to a position of authority?” He tapped my shoulder with his hand and then said: “O Abu Dharr, you are weak, and it is a trust, and on the Day of Resurrection it will be a cause of disgrace and regret, except for the one who takes it rightfully and fulfills the duty imposed upon him therein.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1825}]},{"num":6726,"demo":false,"sanad":"","matn":["عن أبي ذر أن رسول اللّٰه ﷺ قال: (( يا أبا ذر إني أراك ضعيفا، وإني أحب لك ما أحب لنفسي، لا تأمرنّ على اثنين، ولا تُولينّ مال يتيم))."],"takhrij":"صحيح: رواه مسلم (١٨٢٦). قال النووي: \"هذا الحديث أصل عظيم في اجتناب الولايات، لا سيما لمن كان فيه ضعف عن القيام بوظائف تلك الولاية. وأما الخزي والندامة فهو في حق من لم يكن أهلاً لها، أو كان أهلاً ولم يعدل فيها، فيخزيه اللّه تعالى يوم القيامة ويفضحه، ويندم على ما فرّط. وأما من كان أهلا للولاية، وعدل فيها فله فضل عظيم، تظاهرت به الأحاديث الصحيحة \" انتهى.","grade":"صحيح","chapter_ar":"باب في التوجيهات النبوية لمن يطلب القضاء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1826). Al-Nawawi said: “This hadith is a great foundational principle for avoiding public offices, especially for one who is weak in carrying out the duties of that position. As for the disgrace and regret, it applies to whoever is not qualified for it, or was qualified but failed to act with justice; Allah the Exalted will disgrace and expose him on the Day of Resurrection, and he will regret what he neglected. However, whoever is qualified for leadership and acts with justice will have an immense virtue, as supported by numerous authentic hadiths.” End quote.","chapter_en":"Regarding prophetic directives for whoever seeks judgeship","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abu Dharr narrated that the Messenger of Allah ﷺ said: “O Abu Dharr, I see that you are weak, and I love for you what I love for myself: do not rule over even two people, and do not manage the property of an orphan.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1826}]},{"num":6727,"demo":false,"sanad":"","matn":["عن ابن عمر قال: قال رسول اللّٰه ﷺ: (( الناس كالإبل المائة لا يجد الرجل فيها راحلة))."],"takhrij":"متفق عليه: رواه البخاري (٦٤٩٨) ومسلم (٢٥٤٧).","grade":"متفق عليه","chapter_ar":"باب لا فضل لشريف على مشروف في الدين","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (6498) and Muslim (2547).","chapter_en":"No virtue for a person of noble status over a common person in the rulings of the religion","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ said: “People are like a hundred camels; a man can hardly find a single riding camel among them.”"]},"buhuth":{"ar":["قال البيهقي (١٣٥/١٠): \"هذا الحديث قد يتأول على أن الناس في أحكام الدين سواء، لا فضل فيها لشريف على مشروف، ولا لرفيع منهم على وضيع، كالإبل المائة، لا تكون فيها راحلة، وهي الذلول التي ترحل وتركب، وجاءت فاعلة بمعنى مفعولة\". وقيل: معناه أن الناس كثير، والمرضيُّ منهم قليل قاله ابن بطال أي الذين يتحملون عن الناس، ويكشفون كربهم وهم قليلون."],"en":["Al-Bayhaqi said (10/135): “This hadith may be interpreted to mean that people are equal in the rulings of religion; there is no preference therein for a person of noble status over a common person, nor for an elevated person over a lowly one, just like a hundred camels in which there is no riding camel—which is the submissive camel that is saddled and ridden, and the active participle ‘raahilah’ here functions as a passive participle meaning ridden. And it was said: its meaning is that people are many, but those who are pleasing among them are few, as stated by Ibn Battal, meaning those who carry the burdens of people and relieve their distress are few.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6498},{"key":"muslim","label":"مسلم","number":2547}]},{"num":6728,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن أبي بكرة قال: كتب أبو بكرة إلى ابنه - وكان بسجستان - بأن لا تقضي بين اثنين وأنت غضبان، فإني سمعت النبي ﷺ يقول: (( لا يقضين حَكَمٌ بين اثنين وهو غضبان))."],"takhrij":"متفق عليه: رواه البخاري (٧١٥٨)، ومسلم (١٧١٧:١٦).","grade":"متفق عليه","chapter_ar":"باب كراهة قضاء القاضي في حال الغضب","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (7158) and Muslim (1717:16).","chapter_en":"The detestability of a judge passing judgment while angry","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["ʿAbd al-Rahman ibn Abi Bakrah said: Abu Bakrah wrote to his son—who was in Sijistan—instructing him not to judge between two people while being angry, saying, “For I heard the Prophet ﷺ saying: ‘A judge must not pass judgment between two people while he is angry.’”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7158},{"key":"muslim","label":"مسلم","number":1717}]},{"num":6729,"demo":false,"sanad":"","matn":["عن أم سلمة زوج النبي ﷺ عن النبي ﷺ أنه قال: (( إذا ابتلي أحدكم بالقضاء بين المسلمين فلا يقضين وهو غضبان، فليسوّ بينهم بالنظر والمجلس والإشارة، ولا يرفع صوته على أحد الخصمين))."],"takhrij":"حسن: رواه الدارقطني (٢٠٥/٤) والبيهقي (١٣٥/١٠) وأبو يعلى (٥٨٦٧) وإسحاق بن راهويه (١٨٤٦).","grade":"حسن","chapter_ar":"باب التسوية في النظر والإشارة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Daraqutni (4/205), al-Bayhaqi (10/135), Abu Yaʿla (5867), and Ishaq ibn Rahwayh (1846).","chapter_en":"Maintaining equality in gaze and gesturing","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated that the Prophet ﷺ said: “If one of you is tested with judging between Muslims, he must not judge while he is angry, and he must treat them equally in his gaze, his seating arrangement, and his gesturing, and he must not raise his voice against one of the two disputants.”"]}},"tuhfa":{},"refs":[{"key":"الدارقطنی","label":"الدارقطني","number":205},{"key":"البیہقی","label":"البيهقي","number":135},{"key":"ابو_یعلی","label":"أبو يعلى","number":5867},{"key":"اسحاق_بن_راہویہ","label":"إسحاق بن راهويه","number":1846},{"key":"sh12520","label":"مسند أبي يعلى","number":5867,"n":5873},{"key":"sh13159","label":"مسند إسحاق بن راهويه","number":1846,"n":1793}]},{"num":6730,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: بعثني رسول اللّٰه ﷺ إلى اليمن قاضياً. فقلت: يا رسول اللّٰه ﷺ ترسلني، وأنا حديث السن، ولا علم لي بالقضاء؟ فقال: (( إن اللّٰه عز وجل سيهدي قلبك، ويثبّت لسانك، فإذا جلس بين يديك الخصمان فلا تقضين حتى تسمع من الآخر كما سمعت من الأول. فإنه أحرى أن يتبين لك القضاء )) قال: فما زلت قاضياً، أو ما شككت في قضاء بعد."],"takhrij":"حسن: رواه أبو داود (٣٥٨٢) واللفظ له، والترمذي (١٣٣١) والبيهقي (١٣٧/١٠).","grade":"حسن","chapter_ar":"باب لا يقضي القاضي حتى يسمع من الخصمين","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3582) and the wording is his, al-Tirmidhi (1331), and al-Bayhaqi (10/137).","chapter_en":"A judge must not pass judgment until he hears from both disputants","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿAli ibn Abi Talib said: The Messenger of Allah ﷺ sent me to Yemen as a judge. I said, “O Messenger of Allah ﷺ! You are sending me while I am young in age and have no knowledge of judging?” He said: “Indeed, Allah the Mighty and Sublime will guide your heart and make your tongue firm. When the two disputants sit before you, do not judge until you hear from the second one just as you heard from the first. For that is more likely to make the correct judgment clear to you.” ʿAli said: After that, I never ceased to be a judge, or I never doubted a judgment since."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3582},{"key":"tirmidhi","label":"الترمذي","number":1331},{"key":"البیہقی","label":"البيهقي","number":137},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20487,"n":20645}]},{"num":6731,"demo":false,"sanad":"","matn":["عن أبي هريرة وزيد بن خالد الجهني، أنهما أخبراه أن رجلين اختصما إلى رسول اللّٰه ﷺ فقال أحدهما: يا رسول اللّٰه ﷺ اقض بيننا بكتاب الله. وقال الآخر، وهو أفقههما: أجل يا رسول اللّٰه ﷺ فاقض بيننا بكتاب الله. وائذن لي أن أتكلم قال: (( تكلم)) فقال: إن ابني كان عسيفا على هذا فزنى بامرأته. فأخبرني أن على ابني الرجم. فافتديت منه بمائة شاة وبجارية لي. ثم إني سألت أهل العلم فأخبروني: أن ما على ابني جلدُ مائة، وتغريب عام. وأخبروني أنما الرجم على امرأته. فقال رسول اللّٰه ﷺ: (( أما والذي نفسي بيده، لأقضين بينكما بكتاب الله. أما غنمك وجاريتك فرد عليك )) وجلد ابنه مائة. وغرّبه عاماً. وأمر أنيساً الأسلمي أن يأتي امرأة الآخر. فإن اعترفت، رجمها، فاعترفت فرجمها."],"takhrij":"متفق عليه: رواه مالك (٦) والبخاري (٦٦٣٣،٦٦٣٤) ومسلم (١٦٩٧،١٦٩٨).","grade":"متفق عليه","chapter_ar":"باب في ردّ الحكم إلى الكتاب والسنة معاً","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Malik (6), al-Bukhari (6633, 6634), and Muslim (1697, 1698).","chapter_en":"Referring judgment back to both the Book and the Sunnah together","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah and Zayd ibn Khalid al-Juhani narrated that they informed him that two men brought a dispute to the Messenger of Allah ﷺ. One of them said, “O Messenger of Allah ﷺ! Judge between us according to the Book of Allah.” The other, who was the wiser of the two, said, “Yes, O Messenger of Allah ﷺ, judge between us according to the Book of Allah, and permit me to speak.” He said, “Speak.” The man said, “My son was hired as a laborer by this man and he committed adultery with his wife. I was told that my son was to be stoned to death, so I ransomed him with one hundred sheep and a slave-girl of mine. Afterward, I asked the people of knowledge, and they informed me that my son is only to receive one hundred lashes and a year of exile, and they informed me that stoning is only for his wife.” The Messenger of Allah ﷺ said: “By the One in Whose Hand is my soul, I will surely judge between you according to the Book of Allah. As for your sheep and your slave-girl, they are to be returned to you.” Then he ordered his son to be lashed one hundred times and exiled for a year. He then commanded Unays al-Aslami to go to the wife of the other man, and if she confessed, to stone her. She confessed, so he stoned her."]},"intro":{"ar":["قال اللّٰه عز وجل: (يَأَيُّهَا الَّذِينَ ءَامَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الْأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرَدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا ) [النساء: ٥٩]","والمراد بالسنة: السنة الصحيحة الثابتة، وأما الضعيفة والمنكرة والموضوعة فلا يجوز الردّ إليها."],"en":["Allah the Mighty and Sublime said: “O you who have believed, obey Allah and obey the Messenger and those in authority among you. And if you disagree over anything, refer it back to Allah and the Messenger, if you should believe in Allah and the Last Day. That is the best way and best in result.” [Surat al-Nisa’: 59]","What is meant by the Sunnah is the authentic, established Sunnah; as for the weak (daʿif), rejected (munkar), and fabricated (mawdu’) narrations, it is not permissible to refer back to them."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":6},{"key":"bukhari","label":"البخاري","number":6633},{"key":"muslim","label":"مسلم","number":1697}]},{"num":6732,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( اللهم إني أحرّج حق الضعيفين: اليتيم والمرأة)). وفي رواية: (( مال الضعيفين))."],"takhrij":"حسن: رواه ابن ماجه (٣٦٧٨) وصحّحه ابن حبان (٥٥٦٥) والحاكم (١٢٨/٤ ،٦٣/١) وأحمد (٩٦٦٦).","grade":"حسن","chapter_ar":"باب الحفاظ على حقوق الأيتام والنساء","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Majah (3678), and authenticated (Sahih) by Ibn Hibban (5565), al-Hakim (4/128, 1/63), and Ahmad (9666).","chapter_en":"Safeguarding the rights of orphans and women","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “O Allah, I declare inviolable the right of the two weak ones: the orphan and the woman.” And in another narration: “the property of the two weak ones.”"]},"buhuth":{"ar":["وقوله: ((أحرج حق الضعيفين)) أي أحرم مالهما على من ظلمهما."],"en":["His saying: “‘Uharriju’ (I declare inviolable) the right of the two weak ones” means: I make their wealth forbidden to whoever oppresses them."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":3678},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5565},{"key":"hakim","label":"الحاكم","number":128},{"key":"ahmad","label":"مسند الإمام أحمد","number":9666,"n":9666}]},{"num":6733,"demo":false,"sanad":"","matn":["عن شريح بن هانئ، عن أبيه، أنه لما وفد إلى رسول اللّٰه ﷺ وسمعه وهم يكنون هانئا أبا الحكم. فدعاه رسول اللّٰه ﷺ فقال له: (( إن اللّٰه هو الحكم، وإليه الحكم، فلم تكنى أبا الحكم؟ )) قال: إن قومي إذا اختلفوا في شيء أتوني فحكمت بينهم، فرضي كلا الطرفين. قال: (( ما أحسن من هذا، فمالك من الولد؟)). قال: لي شريح، وعبدالله، ومسلم، قال: (( فمن أكبرهم؟)) قال: شريح، قال: (( فأنت أبو شريح)) فدعا له ولولده."],"takhrij":"صحيح: رواه النسائي (٥٣٨٧). قد ثبت التحكيم في شأن الزوجين، وجزاء الصيد، وتحكيم سعد في قضية بني قريظة.","grade":"صحيح","chapter_ar":"باب القضاء بالتحكيم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasa’i (5387). Arbitration has been established in the matter of spouses (in marital discord), the compensation for hunting (while in Ihram), and the arbitration of Saʿd in the case of Banu Qurayzah.","chapter_en":"Passing judgment through arbitration","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Shurayh ibn Hani narrated on the authority of his father that when he came as a delegate to the Messenger of Allah ﷺ, the Prophet ﷺ heard them calling Hani by the kunyah (honorific nickname) ‘Abu al-Hakam’. So the Messenger of Allah ﷺ called him and said to him, “Indeed, Allah is the Judge (al-Hakam), and to Him belongs all judgment, so why are you called Abu al-Hakam?” He said, “When my people dispute over something, they come to me and I judge between them, and both parties are pleased.” He said, “How excellent this is! What do you have of children?” He replied, “I have Shurayh, ʿAbdullah, and Muslim.” He said, “Who is the eldest of them?” He replied, “Shurayh.” He said, “Then you are Abu Shurayh,” and he supplicated for him and his children."]},"buhuth":{"ar":["والتحكيم جائز غير لازم، وإنما هو فتوى للطرفين إذا شاؤوا أخذوا به، وإن لم يشاؤوا لجأوا إلى السلطان."],"en":["Arbitration is permissible but not legally binding; rather, it is like a legal advisory for both parties—if they wish, they may accept it, and if they do not wish, they may resort to the ruler (ruling authority)."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":5387}]},{"num":6734,"demo":false,"sanad":"","matn":["عن وائل بن حجر قال: إني لقاعد مع النبي ﷺ إذ جاء رجل يقود آخر بنسعة فقال: يا رسول الله ﷺ! هذا قتل أخي. فقال رسول اللّٰه ﷺ: (( أقتلته؟)) قال: نعم قتلته. قال: (( كيف قتلته؟)) قال: كنت أنا وهو نتخبط من شجرة، فسبّني فأغضبني فضربته بالفأس على قرنه فقتلته. فقال له النبي ﷺ: (( هل لك من شيء تؤديه عن نفسك؟)) قال: مالي إلا كسائي وفأسي. قال: (( فترى قومك يشترونك؟)) قال: أنا أهون على قومي من ذاك. فرمى إليه بنسعته وقال: (( دونك صاحبك)) فانطلق به الرجل. فلما ولى قال رسول اللّٰه ﷺ: (( إن قتله فهو مثله)) فرجع فقال: يا رسول اللّٰه ﷺ إنه بلغني أنك قلت: (( إن قتله فهو مثله ))، وأخذته بأمرك. فقال رسول اللّٰه ﷺ: (( أما تريد أن يبوء بإثمك وإثم صاحبك؟)). قال: يا نبي الله، بلى. قال: (( فإن ذاك كذاك )) قال: فرمى بنسعته وخلّى سبيله."],"takhrij":"صحيح: رواه مسلم (١٦٨٠). وقوله: (( نسعة)): وهي حبل من جلود. وقوله: (( نتخبط)): أي نجمع الخبط، وهو ورق الشجر. وقوله: (( إن قتله فهو مثله)): أي أنه لا فضل ولا منة لأحدهما على الآخر، لأنه استوفى حقه منه بخلاف ما لو عفا عنه، فإنه كان له الفضل والمنة وجزيل ثواب الآخرة، وجميل الثناء في الدنيا.","grade":"صحيح","chapter_ar":"باب طلب الحاكم من الخصم العفو","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1680). His saying: “‘nisʿah’” refers to a rope made of leather strips. His saying: “‘natakhabat’” means: we were gathering ‘khabt’, which is tree leaves. His saying: “‘If he kills him, he will be just like him’” means: neither of them will hold any virtue or favor over the other because he has fully exacted his right from him—unlike the case if he were to pardon him, for then he would have the virtue, favor, immense reward in the Hereafter, and beautiful praise in this world.","chapter_en":"The judge requesting the disputant to grant a pardon","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Wa’il ibn Hujr said: I was sitting with the Prophet ﷺ when a man came leading another man with a leather strap and said, “O Messenger of Allah ﷺ! This man killed my brother.” The Messenger of Allah ﷺ said, “Did you kill him?” He replied, “Yes, I killed him.” He asked, “How did you kill him?” He replied, “He and I were hitting a tree to shake down its leaves, then he insulted me and made me angry, so I struck him with the axe on his temple and killed him.” The Prophet ﷺ said to him, “Do you have anything to pay as blood money for yourself?” He replied, “I have nothing except my cloak and my axe.” He asked, “Do you think your people will ransom you?” He replied, “I am of less value to my people than that.” So the Prophet ﷺ threw his strap to the claimant and said, “Take your companion.” The man went away with him. When he turned back, the Messenger of Allah ﷺ said, “If he kills him, he will be just like him.” The man returned and said, “O Messenger of Allah ﷺ! It has reached me that you said, ‘If he kills him, he will be just like him,’ yet I took him by your command.” The Messenger of Allah ﷺ said, “Do you not want him to bear your sin and the sin of your companion (brother)?” He said, “O Prophet of Allah, yes indeed.” He said, “Then let it be so.” The man then threw away the strap and let him go his way."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1680}]},{"num":6735,"demo":false,"sanad":"","matn":["عن ابن عباس قال: كان زوج بريرة عبداً يقال له: مُغيث، كأني أنظر إليه يطوف خلفها يبكي، ودموعه تسيل على لحيته. فقال النبي ﷺ لعباس: (( يا عباس ألا تعجب من حب مغيث لبريرة، ومن بغض بريرة مغيثاً ))، فقال النبي ﷺ: (( لو راجعتِه )) قالت: يا رسول اللّٰه ﷺ تأمرني؟ قال: (( إنما أنا أشفع )) قالت: لا حاجة لي فيه."],"takhrij":"صحيح: رواه البخاري (٥٢٨٣).","grade":"صحيح","chapter_ar":"باب شفاعة الحاكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (5283).","chapter_en":"The intercession of the judge","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿAbbas said: The husband of Barirah was a slave called Mughith. It is as if I can see him walking behind her, weeping, with his tears flowing down his beard. The Prophet ﷺ said to ʿAbbas, “O ʿAbbas, are you not amazed by Mughith’s love for Barirah and Barirah’s hatred for Mughith?” Then the Prophet ﷺ said to her, “If only you would go back to him.” She said, “O Messenger of Allah ﷺ, are you commanding me?” He said, “I am only interceding.” She said, “I have no need for him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5283}]},{"num":6736,"demo":false,"sanad":"","matn":["عن ابن عمر قال: سمعت رسول اللّٰه ﷺ يقول: (( من حالت شفاعته دون حد من حدود اللّه فهو مضاد لله في أمره))."],"takhrij":"صحيح: رواه أبو داود (٣٥٩٧) وأحمد (٥٣٨٥) والحاكم (٢٧/٢) وجاء فيه: (( ومن مات وعليه دين فليس بالدينار ولا بالدرهم ولكنها الحسنات والسيئات. ومن خاصم في باطل وهو يعلمه لم يزل في سخط اللّٰه حتى ينزع، ومن قال في مؤمن ما ليس فيه أسكنه اللّٰه ردغة الخبال حتى يخرج مما قال)).","grade":"صحيح","chapter_ar":"باب شفاعة الحاكم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3597), Ahmad (5385), and al-Hakim (2/27). And in it (the narration) it adds: “And whoever dies while owing a debt, it will not be paid with dinars or dirhams, but rather with good deeds and bad deeds. And whoever disputes in a falsehood while he knows it, he remains under the wrath of Allah until he desists. And whoever speaks about a believer that which is not true, Allah will lodge him in the mud of discharge (Radghat al-Khabal) until he retracts what he said.”","chapter_en":"The intercession of the judge","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿUmar said: I heard the Messenger of Allah ﷺ saying: “Whoever’s intercession prevents one of the prescribed punishments (hudud) of Allah from being executed, he has opposed Allah in His command.”"]},"buhuth":{"ar":["وقوله: \"من حالت شفاعته\" : أي من ثبت في حقه حد من حدود الله، وبلغ ذلك إلى السلطان، وأما قبل البلوغ إلى السلطان أو ما كان من حق الآدميين فللحاكم أن يشفع، بل يستحب له ذلك ولو ببذل المال، كما كان النبي ﷺ يفعل. قيل لعلي، وقد شفع لسارق: أتشفع لسارق؟ فقال: نعم، إن ذلك يفعل ما لم يبلغ به الإمام. فإذا بُلغ به الإمام فلا أعفاه اللّٰه إن أعفاه. رواه ابن أبي شيبة (٢٨٦٥٩). وعن الزبيد بن الصلت قال: سمعت أبا بكر الصديق يقول: لو أخذت شارباً لأحببت أن يستره الله، ولو أخذت سارقاً لأحببت أن يستره الله. رواه ابن أبي شيبة (٢٨٦٦٤)."],"en":["His saying: “‘Whoever’s intercession prevents’” means: whoever has a prescribed punishment of Allah proven against him, and it has reached the ruler. However, before reaching the ruler, or in matters concerning human rights, it is permissible for the judge to intercede; rather, it is recommended for him to do so, even by spending wealth, just as the Prophet ﷺ used to do. It was said to ʿAli, when he interceded for a thief, “Do you intercede for a thief?” He replied, “Yes, that may be done as long as it has not reached the ruler. But if it has reached the ruler, then may Allah not forgive him if he forgives him.” Narrated by Ibn Abi Shaybah (28659). And on the authority of al-Zubayd ibn al-Salt, who said: I heard Abu Bakr al-Siddiq saying, “If I caught a drinker, I would prefer that Allah conceals him, and if I caught a thief, I would prefer that Allah conceals him.” Narrated by Ibn Abi Shaybah (28664)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3597},{"key":"hakim","label":"الحاكم","number":27},{"key":"ahmad","label":"مسند الإمام أحمد","number":5385,"n":5385}]},{"num":6737,"demo":false,"sanad":"","matn":["عن بهز بن حكيم بن معاوية، عن أبيه، عن جده قال: أخذ النبي ﷺ ناسا من قومي في تهمة فحبسهم، فجاء رجلٌ من قومي إلى النبي ﷺ وهو يخطب، فقال: يا محمد علامَ تحبس جيرتي؟ فصمت النبي ﷺ فقال: إن ناسا ليقولون إنك تنهى عن الشر، وتستخلي به! فقال النبي ﷺ: (( ما يقول؟ )) قال: فجعلت أُعرِّض بينهما بالكلام مخافة أن يسمعَها، فيدعوَ على قومي دعوةً لا يفلحون بعدها أبدا، فلم يزل النبي ﷺ به حتى فهِمَها فقال: (( قد قالوها أو قائلُها منهم؟، والله لو فعلت لكان عليَّ وما كان عليهم، خلوا له عن جيرانه))."],"takhrij":"حسن: رواه أبو داود (٣٦٣٠)، والترمذي (١٤١٧)، والنسائي (٤٨٧٥)، وأحمد (٢٠٠١٩).","grade":"حسن","chapter_ar":"باب ما جاء في اتخاذ السجن","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3630), al-Tirmidhi (1417), al-Nasa’i (4875), and Ahmad (20019).","chapter_en":"What has been narrated regarding establishing a prison","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أدب القاضي","group_en":"Collection of what has been narrated regarding the etiquette of the judge","part_no":31,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Bahz ibn Hakim ibn Muʿawiyah narrated on the authority of his father, from his grandfather, who said: The Prophet ﷺ detained some people from my tribe on suspicion and imprisoned them. A man from my tribe came to the Prophet ﷺ while he was delivering a sermon and said, “O Muhammad! On what grounds are you detaining my neighbors?” The Prophet ﷺ remained silent. The man then said, “Some people say that you forbid evil but practice it in private!” The Prophet ﷺ said, “What is he saying?” The narrator said: I began to obscure the words between them, fearing that the Prophet ﷺ would hear it and supplicate against my tribe a supplication from which they would never prosper. But the Prophet ﷺ kept questioning him until he understood it, so he said, “Have they really said it, or is the one saying it from among them? By Allah, if I were to do that, the sin would be upon me and not upon them. Release his neighbors for him.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3630},{"key":"tirmidhi","label":"الترمذي","number":1417},{"key":"nasai","label":"النسائي","number":4875},{"key":"ahmad","label":"مسند الإمام أحمد","number":20019,"n":20019}]},{"num":6738,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب قال: إن أناسا كانوا يؤخذون بالوحي في عهد رسول اللّٰه ﷺ وإن الوحي قد انقطع، وإنما نأخذ الآن بما ظهر لنا من أعمالكم، فمن أظهر لنا خيراً آمنّاه وقرّبناه، وليس لنا من سريرته شيء، اللّٰه يحاسبه في سريرته، ومن أظهر لنا سوءاً لم نأمنه ولم نصدقه، وإن قال: إن سريرته حسنة."],"takhrij":"صحيح: رواه البخاري (٢٦٤١).","grade":"صحيح","chapter_ar":"باب اشتراط العدالة في الشهادة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2641).","chapter_en":"The condition of upright character (ʿadalah) in testimony","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khattab said: People used to be judged by the revelation during the lifetime of the Messenger of Allah ﷺ, but now the revelation has ceased. We judge you now only by what is manifest to us of your deeds. Whoever shows us good, we will trust him and bring him close, and we have nothing to do with his inner secrets; Allah will call him to account for his inner secrets. But whoever shows us evil, we will not trust him and we will not believe him, even if he claims that his inner secret is good."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ ذَٰلِكُمْ يُوعَظُ بِهِ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ) [الطلاق: ٢ ]","وقال تعالى: (يَأَيُّهَا الَّذِينَ ءَامَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ اثْنَانِ ذَوَا عَدْلٍ مِنْكُمْ ) [المائدة: ١٠٦ ]"],"en":["Allah the Exalted said: “And take to witness two just men from among you and establish the testimony for [the acceptance of] Allah. That is instructed to whoever should believe in Allah and the Last Day. And whoever fears Allah - He will make for him a way out.” [Surat al-Talaq: 2]","And the Exalted said: “O you who have believed, testimony [should be taken] among you when death approaches one of you at the time of bequest - two just men from among you.” [Surat al-Ma’idah: 106]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2641}]},{"num":6739,"demo":false,"sanad":"","matn":["عن أنس قال: مرّ على النبي ﷺ بجنازة فأثنوا عليها خيراً، فقال: (( وجبت )) ثم مُرّ بأخرى فأثنوا عليها شراً - أو قال غير ذلك - فقال: (( وجبت )) فقيل: يا رسول اللّٰه ﷺ قلت لهذا وجبت ولهذا وجبت؟! قال: (( شهادة القوم، المؤمنون شهداء اللّٰه في الأرض))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٤٢)، ومسلم (٩٤٩:٦٠)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب المؤمنون شهداء الله في الأرض","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2642) and Muslim (949:60), and the wording is that of al-Bukhari.","chapter_en":"The believers are the witnesses of Allah on earth","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas said: A funeral procession passed by the Prophet ﷺ and the people praised the deceased. He said, “It has become binding.” Then another procession passed by and they spoke ill of the deceased—or said something else—and he said, “It has become binding.” It was said, “O Messenger of Allah ﷺ, you said ‘It has become binding’ for this one and ‘It has become binding’ for that one?!” He said, “It is the testimony of the people; the believers are the witnesses of Allah on earth.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَكَذَٰلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا) [البقرة: ١٤٣]","وقال تعالى: (هُوَ سَمَّاكُمُ الْمُسْلِمِينَ مِنْ قَبْلُ وَفِي هَٰذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ) [الحج: ٧٨]"],"en":["Allah the Exalted said: “And thus we have made you a just community that you will be witnesses over the people and the Messenger will be a witness over you.” [Surat al-Baqarah: 143]","And the Exalted said: “He named you Muslims before and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people.” [Surat al-Hajj: 78]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2642},{"key":"muslim","label":"مسلم","number":949}]},{"num":6740,"demo":false,"sanad":"","matn":["عن عمران بن حصين قال: قال النبي ﷺ: (( خيركم قرني ثم الذين يلونهم، ثم الذين يلونهم )) قال عمران: لا أدري، أذكر النبي ﷺ بعد قرنين أو ثلاثة، قال النبي ﷺ: (( إن بعدكم قوماً يخونون ولا يؤتمنون، ويشهدون ولا يستشهدون، وينذرون ولا يفون، ويظهر فيهم السمن ))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٥١) ومسلم (٢٥٣٥:٢١٤).","grade":"متفق عليه","chapter_ar":"باب في ذم المبادرة إلى الشهادة قبل أن يسألها","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2651) and Muslim (2535:214).","chapter_en":"Regarding the condemnation of rushing to give testimony before being asked for it","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿImran ibn Husayn said: The Prophet ﷺ said: “The best of you is my generation, then those who follow them, then those who follow them.” ʿImran said: I do not know whether the Prophet ﷺ mentioned two or three generations after his generation. The Prophet ﷺ said: “Indeed, after you there will be a people who will betray and will not be trusted, they will bear witness without being asked to bear witness, they will make vows and not fulfill them, and obesity will appear among them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2651},{"key":"muslim","label":"مسلم","number":2535}]},{"num":6741,"demo":false,"sanad":"","matn":["عن عبد اللّه بن مسعود، عن النبي ﷺ قال: (( خير الناس قرني، ثم الذين يلونهم، ثم الذين يلونهم، ثم يجئ أقوام تسبق شهادة أحدهم يمينه، ويمينه شهادته)) قال إبراهيم: وكانوا يضربوننا على الشهادة والعهد."],"takhrij":"متفق عليه: رواه البخاري (٢٦٥٢) ومسلم (٢٥٣٣:٢١).","grade":"متفق عليه","chapter_ar":"باب في ذم المبادرة إلى الشهادة قبل أن يسألها","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2652) and Muslim (2533:21).","chapter_en":"Regarding the condemnation of rushing to give testimony before being asked for it","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullah ibn Masʿud narrated that the Prophet ﷺ said: “The best of people are those of my generation, then those who follow them, then those who follow them, then there will come people whose testimony will precede their oath, and their oath will precede their testimony.” Ibrahim said: They used to strike us for giving testimony and making covenants (when we were young, to teach us seriousness)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2652},{"key":"muslim","label":"مسلم","number":2533}]},{"num":6742,"demo":false,"sanad":"","matn":["عن زيد بن خالد الجهني، أن رسول اللّٰه ﷺ قال: (( ألا أخبركم بخير الشهداء؟ الذي يأتي بشهادته قبل أن يُسألها، أو يخبر بشهادته قبل أن يسألها ))."],"takhrij":"صحيح: رواه مالك (٣) ومسلم (١٧١٩).","grade":"صحيح","chapter_ar":"باب خير الشهود الذي يأتي بشهادته قبل أن يُسألها خوفا من ضياع الحقوق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Malik (3) and Muslim (1719).","chapter_en":"The best of witnesses is the one who brings his testimony before he is asked for it out of fear of rights being lost","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani narrated that the Messenger of Allah ﷺ said: “Shall I not inform you of the best of witnesses? It is the one who brings his testimony before he is asked for it, or informs of his testimony before he is asked for it.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":3},{"key":"muslim","label":"مسلم","number":1719}]},{"num":6743,"demo":false,"sanad":"","matn":["عن ابن مسعود، عن النبي ﷺ قال: (( إن من بين يدي الساعة، التسليم على الخاصة، وفشو التجارة، وظهور شهادة الزور، وكتمان شهادة الحق))"],"takhrij":"حسن: رواه البخاري في التاريخ الكبير (١٠٤٩) وأحمد (٣٩٨٢) والطحاوي في مشكله (١٥٩٠) والحاكم (٤٤٥/٤).","grade":"حسن","chapter_ar":"باب إثم كتمان شهادة الحق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhari in al-Tarikh al-Kabir (1049), Ahmad (3982), al-Tahawi in Mushkil al-Athar (1590), and al-Hakim (4/445).","chapter_en":"The sin of concealing the testimony of truth","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ibn Masʿud narrated that the Prophet ﷺ said: “Indeed, before the Hour there will be the greeting of only those one knows, the widespread expansion of trade, the prevalence of false testimony, and the concealment of the testimony of truth.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَلَا تَكْتُمُوا الشَّهَادَةَ وَمَنْ يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ ) [ البقرة: ٢٨٣]"],"en":["Allah the Exalted said: “And do not conceal testimony, for whoever conceals it - his heart is indeed sinful, and Allah is Knowing of what you do.” [Surat al-Baqarah: 283]"]}},"tuhfa":{},"refs":[{"key":"bukhari/التاریخ_الکبیر","label":"البخاري في التاريخ الكبير","number":1049},{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":1590},{"key":"hakim","label":"الحاكم","number":445},{"key":"ahmad","label":"مسند الإمام أحمد","number":3982,"n":3982}]},{"num":6744,"demo":false,"sanad":"","matn":["عن أنس قال: سئل النبي ﷺ عن الكبائر قال: (( الإشراك بالله، وعقوق الوالدين، وقتل النفس، وشهادة الزور ))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٥٣) ومسلم (٨٨:١٤٤).","grade":"متفق عليه","chapter_ar":"باب الترهيب من شهادة الزور","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2653) and Muslim (88:144).","chapter_en":"Severe warning against bearing false witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas said: The Prophet ﷺ was asked about the major sins. He said: “Associating partners with Allah, disobedience to parents, killing a soul, and bearing false witness.”"]},"intro":{"ar":["قال تعالى: (وَالَّذِينَ لَا يَشْهَدُونَ الزُّورَ) [الفرقان: ٧٢]"],"en":["Allah the Exalted said: “And those who do not bear witness to falsehood.” [Surat al-Furqan: 72]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2653},{"key":"muslim","label":"مسلم","number":88}]},{"num":6745,"demo":false,"sanad":"","matn":["عن أبي بكرة قال: كنا عند رسول اللّٰه ﷺ فقال: (( ألا أنبئكم بأكبر الكبائر؟ ثلاثاً: الإشراك بالله، وعقوق الوالدين، وشهادة الزور أو قول الزور))"],"takhrij":"متفق عليه: رواه البخاري (٢٦٥٤)، ومسلم (٨٧:١٤٣) واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الترهيب من شهادة الزور","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2654) and Muslim (87:143), and the wording is that of Muslim.","chapter_en":"Severe warning against bearing false witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abu Bakrah said: We were with the Messenger of Allah ﷺ when he said: “Shall I not inform you of the greatest of major sins? (repeating it three times): Associating partners with Allah, disobedience to parents, and bearing false witness—or speaking falsehood.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2654},{"key":"muslim","label":"مسلم","number":87}]},{"num":6746,"demo":false,"sanad":"","matn":["عن عائشة قالت في حديث الإفك: فدعا رسول اللّٰه ﷺ بريرة، فقال: (( يا بريرة، هل رأيتِ فيها شيئا يريبكِ؟ )) فقالت بريرة: لا والذي بعثك بالحق، إن رأيت منها أمراً أغمصه عليها قط أكثر من أنها جارية حديثة السن، تنام عن العجين، فتأتي الداجن فتأكله. وجاء في آخره: وكان رسول اللّٰه ﷺ يسأل زينبَ بنت جحش عن أمري، فقال: (( يا زينبُ، ما علمتِ ما رأيتِ؟ )) فقالت: يا رسول الله ﷺ، أحمي سمعي وبصري، والله ما علمتُ عليها إلا خيراً، قالت (أي عائشة): وهي التي كانت تساميني، فعصمها اللّٰه بالورع."],"takhrij":"متفق عليه: رواه البخاري (٢٦٦١)، ومسلم (٢٧٧٠).","grade":"متفق عليه","chapter_ar":"باب تعديل النساء بعضهن بعضا","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2661) and Muslim (2770).","chapter_en":"Women verifying the upright character of one another","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAishah said in the narration of the slander (al-Ifk): The Messenger of Allah ﷺ called Barirah and said, “O Barirah, have you seen anything in her that arouses your suspicion?” Barirah said, “No, by the One Who sent you with the truth, I have never seen any fault in her for which I could blame her, other than that she is a young girl who falls asleep leaving her family’s dough, and the domestic goat comes and eats it.” And it states at the end of it: And the Messenger of Allah ﷺ used to ask Zaynab bint Jahsh about my matter, saying, “O Zaynab, what did you know? What did you see?” She replied, “O Messenger of Allah ﷺ, I protect my hearing and my sight; by Allah, I know nothing of her but good.” ʿAishah said: She was the one who used to compete with me (in status), yet Allah protected her because of her piety."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2661},{"key":"muslim","label":"مسلم","number":2770}]},{"num":6747,"demo":false,"sanad":"","matn":["عن عبد الله بن عمر، عن رسول اللّٰه ﷺ أنه قال: (( يا معشر النساء تصدقن وأكثرن الاستغفار، فإني رأيتكن أكثر أهل النار)) فقالت امرأة منهن، جزلة: وما لنا يا رسول اللّٰه ﷺ أكثر أهل النار؟! قال: (( تكثرن اللعن، وتكفرن العشير، وما رأيت من ناقصات عقل ودين أغلب لذي لبّ منكن)) قالت: يا رسول اللّٰه ﷺ وما نقصان العقل والدين؟ قال: (( أما نقصان العقل فشهادة امرأتين تعدل شهادة رجل، فهذا نقصان العقل، وتمكث الليالي ما تصلي وتُفطر في رمضان، فهذا نقصان الدين))."],"takhrij":"صحيح: رواه مسلم (٧٩).","grade":"صحيح","chapter_ar":"باب تعديل النساء بعضهن بعضا","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (79).","chapter_en":"Women verifying the upright character of one another","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullah ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “O assembly of women, give charity and seek forgiveness frequently, for I have seen that you form the majority of the people of the Fire.” A wise woman among them said, “Why is it, O Messenger of Allah ﷺ, that we form the majority of the people of the Fire?” He said, “You curse frequently and you are ungrateful to your husbands. I have not seen anyone deficient in intelligence and religion more capable of overcoming a wise man than one of you.” She said, “O Messenger of Allah ﷺ, what is the deficiency in intelligence and religion?” He said, “As for the deficiency in intelligence, the testimony of two women equals the testimony of one man; this is the deficiency in intelligence. And she spends nights without praying and breaks her fast in Ramadan (due to menses); this is the deficiency in religion.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":79}]},{"num":6748,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، عن النبي ﷺ قال: (( أليس شهادة المرأة مثل نصف شهادة الرجل؟ قلنا: بلى)) قال: (( فذلك من نقصان عقلها))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٥٨)، ومسلم (٨٠)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب شهادة امرأتين تعادل شهادة رجل واحد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2658) and Muslim (80), and the wording is that of al-Bukhari.","chapter_en":"The testimony of two women equals the testimony of one man","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abu Saʿid al-Khudri narrated that the Prophet ﷺ said: “Is not the testimony of a woman equal to half the testimony of a man?” We said, “Yes.” He said, “That is due to the deficiency in her intelligence.”"]},"intro":{"ar":["قال تعالى: ( فَإِنْ لَمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتَانِ) [البقرة: ٢٨٢]"],"en":["Allah the Exalted said: “And if there are not two men [available], then a man and two women.” [Surat al-Baqarah: 282]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2658},{"key":"muslim","label":"مسلم","number":80}]},{"num":6749,"demo":false,"sanad":"","matn":["عن عقبة بن الحارث أنه تزوج أم يحيى بنت أبي إهاب، قال: فجاءت أمة سوداء فقالت: قد أرضعتكما، فذكرت ذلك للنبي ﷺ فأعرض عني، قال: فتنحيت فذكرت ذلك له، قال: (( وكيف وقد زعمت أن قد أرضعتكما )) فنهاه عنها. وفي رواية: (( وكيف وقد قيل! دَعْها عنك))."],"takhrij":"صحيح: رواه البخاري (٢٦٥٩)، والرواية الأخرى عنده أيضا (٢٦٦٠).","grade":"صحيح","chapter_ar":"باب الشهادة على الرضاعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2659), and the other narration is also with him (2660).","chapter_en":"Bearing witness regarding breast-feeding","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["ʿUqbah ibn al-Harith narrated that he married Umm Yahya bint Abi Ihab. He said: A black slave-girl came and said, “I have breast-fed both of you.” I mentioned that to the Prophet ﷺ, but he turned his face away from me. I moved to face him and mentioned it to him again. He said, “How can you remain with her when she has claimed that she breast-fed both of you?” So he forbade him from remaining with her. And in another narration: “How can you when it has been said! Leave her.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2659},{"key":"الروایہ_الاخری_عندہ_ایضا","label":"الرواية الأخرى عنده أيضا","number":2660}]},{"num":6750,"demo":false,"sanad":"","matn":["عن عَبْدِ اللهِ بْنِ عُبَيْدِ اللهِ بْنِ أَبِي مُلَيْكَةَ أَنَّ بَنِي صُهَيْبٍ مَوْلَى ابْنِ جُدْعَانَ ادَّعَوْا بَيْتَيْنِ وَحُجْرَةً أَنَّ رَسُولَ اللٰهِ أَعْطَى ذَلِكَ صُهَيْبًا، فَقَالَ مَرْوَانُ: مَنْ يَشْهَدُ لَكُمَا عَلَى ذَلِكَ؟ قَالُوا: ابْنُ عُمَرَ. فَدَعَاهُ، فَشَهِدَ لَأَعْطَى رَسُولُ اللٰهِ ﷺ صُهَيْبًا بَيْتَيْنِ وَحُجْرَةً، فَقَضَى مَرْوَانُ بِشَهَادَتِهِ لَهُمْ."],"takhrij":"صحيح: رواه البخاري (٢٦٢٤).","grade":"صحيح","chapter_ar":"باب طلب الشهادة على الهدية","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2624).","chapter_en":"Requesting testimony regarding a gift","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullah ibn ʿUbaydullah ibn Abi Mulaykah narrated that the sons of Suhayb, the freed slave of Ibn Judʿan, claimed two houses and a room, stating that the Messenger of Allah ﷺ had given that to Suhayb. Marwan asked, “Who will bear witness for you to that effect?” They said, “Ibn ʿUmar.” So Marwan called him, and he bore witness that the Messenger of Allah ﷺ had indeed given Suhayb two houses and a room. Marwan then passed judgment in their favor based on his testimony."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2624}]},{"num":6751,"demo":false,"sanad":"","matn":["عن النعمان بن بشير قال: سألت أمي أبي بعض الموهبة لي من ماله، ثم بدا له فوهبها لي، فقالت: لا أرضى حتى تشهد النبي ﷺ فأخذ بيدي وأنا غلام، فأتى بي النبي ﷺ فقال: إن أمه بنت رواحة سألتني بعض الموهبة لهذا؟ قال: (( ألك ولد سواه؟ )) قال: نعم. قال: فأراه قال: (( لا تُشهدني على جور ))."],"takhrij":"متفق عليه: رواه البخاري (٢٦٥٠)، ومسلم (١٦٢٣:١٤).","grade":"متفق عليه","chapter_ar":"باب الترهيب من الشهادة على الجور","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2650) and Muslim (1623:14).","chapter_en":"Warning against bearing witness to an injustice","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Al-Nuʿman ibn Bashir said: My mother asked my father to grant me a gift from his wealth, then it occurred to him and he gifted it to me. She said, “I will not be pleased until you take the Prophet ﷺ as a witness.” So he took me by my hand while I was a young boy, and brought me to the Prophet ﷺ and said, “His mother, the daughter of Rawahah, asked me to grant a gift to this boy.” The Prophet ﷺ asked, “Do you have any children other than him?” He replied, “Yes.” He said, and I think he said: “Do not make me a witness to an injustice.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2650},{"key":"muslim","label":"مسلم","number":1623}]},{"num":6752,"demo":false,"sanad":"","matn":["عن عروة بن الزبير: أن امرأة سرقت في غزوة الفتح، فأتي بها رسول اللّٰه ﷺ ثم أمر فقطعت يدها. قالت عائشة: فحسنت توبتها وتزوّجت، وكانت تأتي بعد ذلك فأرفع حاجتها إلى رسول اللّٰه ﷺ."],"takhrij":"متفق عليه: رواه البخاري (٢٦٤٨) ومسلم (١٦٨٨:٩) والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب قبول شهادة الفاسق إذا تاب","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2648) and Muslim (1688:9), and the wording is that of al-Bukhari.","chapter_en":"Acceptance of the testimony of an evildoer (fasiq) if he repents","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr narrated that a woman committed theft during the expedition of the Conquest (of Makkah). She was brought to the Messenger of Allah ﷺ, who ordered that her hand be amputated. ʿAishah said: Her repentance became excellent afterward and she married, and she used to come to me after that so that I could convey her needs to the Messenger of Allah ﷺ."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلَا تَقْبَلُوا لَهُمْ شَهَادَةً أَبَدًا وَأُولَٰئِكَ هُمُ الْفَاسِقُونَ ۝ إِلَّا الَّذِينَ تَابُوا﴾ [النور: ٤-٥]"],"en":["Allah the Exalted said: “And never accept their testimony, and those are the defiantly disobedient. Except for those who repent.” [Surat al-Nur: 4-5]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2648},{"key":"muslim","label":"مسلم","number":1688}]},{"num":6753,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول اللّٰه ﷺ رد شهادة الخائن والخائنة، وذي الغِمرة على أخيه، ورد شهادة القانع لأهل البيت، وأجازها لغيرهم."],"takhrij":"حسن: رواه أبو داود (٣٦٠٠)، وأحمد (٦٨٩٨)، والدارقطني (٢٤٣/٤)، والبيهقي (٢٠٠/١٠).","grade":"حسن","chapter_ar":"باب من ترد شهادته","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abu Dawud (3600), Ahmad (6898), al-Daraqutni (4/243), and al-Bayhaqi (10/200).","chapter_en":"Those whose testimony is rejected","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Amr ibn Shuʿayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ rejected the testimony of a dishonest man and a dishonest woman, and of a person bearing rancor against his brother, and he rejected the testimony of a dependent servant for the household, while allowing it for others."]},"buhuth":{"ar":["قال أبو داود: الغِمْر: الحِنَة والشحناء، والقانع: الأجير التابع مثل الأجير الخاص."],"en":["Abu Dawud said: al-ghimr means malice and enmity. Al-qaniʿ means the dependent hired servant, such as a personal servant."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3600},{"key":"الدارقطنی","label":"الدارقطني","number":243},{"key":"البیہقی","label":"البيهقي","number":200},{"key":"ahmad","label":"مسند الإمام أحمد","number":6898,"n":6898},{"key":"sh9771","label":"سنن الدارقطني","number":4600,"n":4612},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20854,"n":21012}]},{"num":6754,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: قال رسول اللّٰه ﷺ: (( من حلف على يمين- وهو فيها فاجر - ليقتطع بها مال امرئ مسلم لقي اللّٰه وهو عليه غضبان )) قال: فقال الأشعث بن قيس فيّ والله كان ذلك، كان بيني وبين رجل من اليهود أرض فجحدني، فقدّمته إلى النبي ﷺ، فقال لي رسول اللّٰه ﷺ:","(( ألك بيّنة؟ )) قلت: لا، قال: فقال لليهودي: احلف. قال: قلت: يا رسول اللّٰه ﷺ إذن يحلف ويذهب بمالي. قال: فأنزل اللّٰه تعالى: ( إِنَّ ٱلَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَٰنِهِمْ ثَمَنَا قَلِيلًا) إلى آخر الآية.","[آل عمران: ٧٧ ] وفي رواية: (( شاهداك أو يمينه )."],"takhrij":"متفق عليه: رواه البخاري (٢٦٦٦،٢٦٦٧) ومسلم (٢٢٠ :١٣٨).","grade":"متفق عليه","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2666, 2667) and Muslim (220:138).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Masʿud reported that the Messenger of Allah ﷺ said: “Whoever swears an oath while lying in it in order to unlawfully take the wealth of a Muslim will meet Allah while He is angry with him.” Al-Ashʿath ibn Qays said: By Allah, this was about me. There was a dispute between me and a Jewish man concerning land, and he denied my claim. So I brought him to the Prophet ﷺ, and the Messenger of Allah ﷺ said to me: “Do you have proof?” I said: No. He then said to the Jew: “Swear an oath.” I said: O Messenger of Allah ﷺ, then he will swear and take my property. Then Allah revealed: “Indeed, those who exchange the covenant of Allah and their oaths for a small price…” to the end of the verse [Aal Imran: 77].","In another narration: “Your two witnesses, or else his oath.”"]},"buhuth":{"ar":["والرواية الأخرى عند البخاري (٢٦٦٩،٢٦٧٠) ومسلم (٢٢١:١٣٨)."],"en":["The other wording is in al-Bukhari (2669, 2670) and Muslim (221:138)."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2666},{"key":"muslim","label":"مسلم","number":220}]},{"num":6755,"demo":false,"sanad":"","matn":["عن وائل بن حجر قال: جاء رجل من حضرموت ورجل من كندة إلى النبي ﷺ فقال الحضرمي: يا رسول الله ﷺ، إن هذا قد غلبني على أرض كانت لأبي. فقال الكندي: هي أرضي في يدي أزرعها ليس له فيها حق. فقال رسول اللّٰه ﷺ للحضرمي: (( ألك بينة؟ )) قال: لا. قال: (( فلك بيمينه )) قال: يا رسول اللّٰه ﷺ إن الرجل فاجر لا يبالي على ما حلف عليه، وليس يتورّع من شيء. فقال:","(( ليس لك منه إلا ذلك ))، فانطلق ليحلف، فقال رسول اللّٰه ﷺ لما أدبر: (( أما لئن حلف على ماله ليأكله ظلماً، ليلقين اللّٰه وهو عنه مُعْرِض ))."],"takhrij":"صحيح: رواه مسلم (٢٢٣:١٣٩).","grade":"صحيح","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (223:139).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Wa’il ibn Hujr said: A man from Hadramawt and a man from Kindah came to the Prophet ﷺ. The Hadrami said: O Messenger of Allah ﷺ, this man has seized land that belonged to my father. The Kindi said: It is my land, in my possession, and I cultivate it; he has no right to it. The Messenger of Allah ﷺ said to the Hadrami: “Do you have proof?” He said: No. He said: “Then you are entitled to his oath.” He said: O Messenger of Allah ﷺ, the man is wicked; he does not care what he swears upon and he refrains from nothing. He said: “You have no right against him except that.”","So the man went off to swear, and when he turned away the Messenger of Allah ﷺ said: “If he swears to seize his property unjustly, he will surely meet Allah while Allah is turned away from him.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":223}]},{"num":6756,"demo":false,"sanad":"","matn":["عن أبي موسى قال: اختصم رجلان إلى النبي ﷺ في أرض، أحدهما من","أهل حضرموت. قال: فجعل يمين أحدهما، قال: فضج الآخر، وقال: إنه إذا يذهب بأرضي، فقال:","(( إن هو اقتطعها بيمينه ظلماً، كان ممن لا ينظر اللّٰه عز وجل إليه يوم القيامة، ولا يزكيه، وله عذاب أليم)) قال: وورع الآخر فردّها."],"takhrij":"صحيح: رواه أحمد (١٩٥١٤) والبزار -كشف الأستار (١٣٥٩) وأبو يعلى (٧٢٧٤).","grade":"صحيح","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Ahmad (19514), al-Bazzar in Kashf al-Astar (1359), and Abu Yaʿla (7274).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Abu Musa said: Two men brought a dispute over land to the Prophet ﷺ, one of them being from Hadramawt. He ruled that one of them should swear an oath. The other cried out and said: Then he will take my land! He said: “If he takes it by his oath unjustly, he will be among those at whom Allah will not look on the Day of Resurrection, nor will He purify him, and he will have a painful punishment.” The other man then refrained and returned it."]}},"tuhfa":{},"refs":[{"key":"البزار_کشف_الاستار","label":"البزار -كشف الأستار","number":1359},{"key":"ابو_یعلی","label":"أبو يعلى","number":7274},{"key":"ahmad","label":"مسند الإمام أحمد","number":19514,"n":19514}]},{"num":6757,"demo":false,"sanad":"","matn":["عن ابن أبي مليكة:","أن امرأتين كانتا تخرزان في بيت - أو في الحجرة - فخرجت إحداهما وقد أُنفذ بإشفى في كفها، فادعت على الأخرى، فرفع إلى ابن عباس.","فقال ابن عباس: قال رسول اللّٰه ﷺ:","«لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَذَهَبَ دِمَاءُ قَوْمٍ وَأَمْوَالُهُمْ».","ذكّروها بالله، واقرؤوا عليها:","﴿إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ﴾","[آل عمران: ٧٧]","فذكروها، فاعترفت.","فقال ابن عباس: قال النبي ﷺ:","«الْيَمِينُ عَلَى الْمُدَّعَى عَلَيْهِ»."],"takhrij":"متفق عليه: رواه البخاري (٤٥٥٢)، ومسلم (١٧١١/١)، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4552) and Muslim (1711/1). This is the wording of al-Bukhārī.","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Abī Mulaykah reported: Two women were sewing leather in a house—or in a room—when one of them came out with an awl driven into the palm of her hand. She accused the other woman, and the matter was brought before Ibn ʿAbbās. Ibn ʿAbbās said that the Messenger of Allah ﷺ said: “If people were granted what they claimed merely on the basis of their claims, the blood and wealth of people would be lost.” He said: “Remind her of Allah and recite to her: ‘Indeed, those who exchange the covenant of Allah…’”","[Āl ʿImrān: 77] They reminded her, and she confessed. Then Ibn ʿAbbās said that the Prophet ﷺ said: “The oath is upon the one against whom the claim is made.”"]},"buhuth":{"ar":["قوله: «بإشفى» بكسر الهمزة، مقصور، وهي الحديدة التي يخرز بها."],"en":["The word ishfā means the pointed iron tool used for piercing leather while sewing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4552},{"key":"muslim","label":"مسلم","number":1711}]},{"num":6758,"demo":false,"sanad":"","matn":["عن ابن أبي مليكة قال: كتب ابن عباس رضي اللّٰه عنهما: أن النبي ﷺ قضى باليمين على المدعَى عليه."],"takhrij":"متفق عليه: رواه البخاري (٢٦٦٨) ومسلم (٢:١٧١١).","grade":"متفق عليه","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (2668) and Muslim (2:1711).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Abi Mulaykah said: Ibn Abbas wrote that the Prophet ﷺ judged that the oath is upon the one against whom the claim is made."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2668},{"key":"muslim","label":"مسلم","number":2}]},{"num":6759,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: قال رسول اللّٰه ﷺ: (( المدّعى عليه أولى باليمين إذا لم تكن بيّنة ))."],"takhrij":"حسن: رواه عبدالرزاق في المصنف (١٥١٨٤)","grade":"حسن","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abd al-Razzaq in al-Musannaf (15184).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Amr ibn Shuʿayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ said: “The one against whom the claim is made has more right to the oath when there is no proof.”"]}},"tuhfa":{},"refs":[{"key":"عبدالرزاق/المصنف","label":"عبدالرزاق في المصنف","number":15184}]},{"num":6760,"demo":false,"sanad":"","matn":["عن ابن عمر أن رسول اللّٰه ﷺ قال: ((المدَّعى عليه أولى باليمين إلا أن تقوم بيّنةٌ))."],"takhrij":"حسن: رواه ابنُ حبان (٥٩٩٦) في سياق طويل، والدار قطني (٤٥١١)","grade":"حسن","chapter_ar":"باب البينة على المدعي واليمين على من أنكر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Hibban (5996) in a longer narration, and al-Daraqutni (4511).","chapter_en":"The proof is upon the claimant, and the oath is upon the one who denies","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn Umar reported that the Messenger of Allah ﷺ said: “The one against whom the claim is made has more right to the oath unless proof is established.”"]}},"tuhfa":{},"refs":[{"key":"ibnhibban","label":"ابنُ حبان","number":5996},{"key":"الدار_قطنی","label":"الدار قطني","number":4511},{"key":"sh9771","label":"سنن الدارقطني","number":4511,"n":4523}]},{"num":6761,"demo":false,"sanad":"","matn":["عن ابن عباس أن رسول اللّٰه ﷺ قضى بيمين وشاهد."],"takhrij":"صحيح: رواه مسلم (١٧١٢).","grade":"صحيح","chapter_ar":"باب القضاء باليمين والشاهد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1712).","chapter_en":"Judging by an oath together with one witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Ibn Abbas reported that the Messenger of Allah ﷺ gave judgment based on an oath and one witness."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1712}]},{"num":6762,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قضى باليمين مع الشاهد الواحد."],"takhrij":"صحيح: رواه أبو داود (٣٦١٠).","grade":"صحيح","chapter_ar":"باب القضاء باليمين والشاهد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3610).","chapter_en":"Judging by an oath together with one witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ gave judgment based on an oath together with a single witness."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3610}]},{"num":6763,"demo":false,"sanad":"","matn":["عن جابر بن عبد اللّٰه أن النبي ﷺ قضى باليمين مع الشاهد."],"takhrij":"صحيح: رواه الترمذي (١٣٤٤)، وابن ماجه (٢٣٦٩)، وأحمد (١٤٢٧٨)، وابن الجارود (١٠٠٨).","grade":"صحيح","chapter_ar":"باب القضاء باليمين والشاهد","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhi (1344), Ibn Majah (2369), Ahmad (14278), and Ibn al-Jarud (1008).","chapter_en":"Judging by an oath together with one witness","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Jabir ibn Abdullah reported that the Prophet ﷺ gave judgment based on an oath together with a witness."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1344},{"key":"ibnmajah","label":"ابن ماجه","number":2369},{"key":"ابن_الجارود","label":"ابن الجارود","number":1008},{"key":"ahmad","label":"مسند الإمام أحمد","number":14278,"n":14278}]},{"num":6764,"demo":false,"sanad":"","matn":["عن عائشة أن النبي ﷺ كان إذا خرج أقرع بين نسائه."],"takhrij":"متفق عليه: رواه البخاري (٥٢١١) ومسلم ( ٢٤٤٥).","grade":"متفق عليه","chapter_ar":"باب القضاء بالقرعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5211) and Muslim (2445).","chapter_en":"Judging by drawing lots","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿA’ishah reported that whenever the Prophet ﷺ went on a journey, he would draw lots among his wives."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5211},{"key":"muslim","label":"مسلم","number":2445}]},{"num":6765,"demo":false,"sanad":"","matn":["عن عمران بن الحصين:","أن رجلًا أعتق ستة مملوكين له عند موته، لم يكن له مال غيرهم، فدعا بهم رسول اللّٰه ﷺ، فجزأهم أثلاثًا، ثم أقرع بينهم، فأعتق اثنين وأرق أربعة، وقال له قولًا شديدًا."],"takhrij":"صحيح: رواه مسلم (١٦٦٨/٥٦).","grade":"صحيح","chapter_ar":"باب القضاء بالقرعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1668/56).","chapter_en":"Judging by drawing lots","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported: A man freed six slaves of his at the time of his death, and he had no property other than them. The Messenger of Allah ﷺ summoned them, divided them into three groups, and then drew lots among them. He freed two and kept four in servitude, and he spoke sternly concerning the man."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1668}]},{"num":6766,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رجلين اختصما في متاع إلى النبي ﷺ، ليس لواحد منهما بينة، فقال النبي ﷺ: ((استهما على اليمين ما كان، أحبا ذلك أو كرها))."],"takhrij":"صحيح: رواه أبو داود (٣٦١٦) وابن ماجه (٢٣٢٩) وأحمد (١٠٣٤٧) والدارقطني (٢١١/٤).","grade":"صحيح","chapter_ar":"باب القضاء بالقرعة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3616), Ibn Majah (2329), Ahmad (10347), and al-Daraqutni (4/211).","chapter_en":"Judging by drawing lots","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abu Hurayrah reported that two men brought a dispute over some goods to the Prophet ﷺ, and neither of them had proof. So he said: “Draw lots regarding the oath, whatever the case may be, whether they like it or dislike it.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3616},{"key":"ibnmajah","label":"ابن ماجه","number":2329},{"key":"الدارقطنی","label":"الدارقطني","number":211},{"key":"ahmad","label":"مسند الإمام أحمد","number":10347,"n":10347}]},{"num":6767,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ عرض على قوم اليمين، فأسرعوا، فأمر أن يُسهم بينهم في اليمين أيهم يحلف."],"takhrij":"صحيح: رواه البخاري (٢٦٧٤).","grade":"صحيح","chapter_ar":"باب إذا تسارع قوم في اليمين أقرع بينهم","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2674).","chapter_en":"If several people hasten to swear an oath, lots are drawn among them","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ offered an oath to some people, and they hastened toward it, so he ordered that lots be drawn among them to determine which of them would swear."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2674}]},{"num":6768,"demo":false,"sanad":"","matn":["عن عمارة بن خزيمة أن عمه حدّثه - وهو من أصحاب النبي ﷺ - أن النبي ﷺ ابتاع فرساً من أعرابي، فاستتبعه النبي ﷺ ليقضيه ثمن فرسه، فأسرع رسول اللّٰه ﷺ المشي وأبطأ الأعرابي، فطفق رجال يعترضون الأعرابي فيساومونه بالفرس، ولا يشعرون أن النبي ﷺ ابتاعه، فنادى الأعرابي رسول اللّٰه ﷺ فقال: إن كنت مبتاعاً هذا الفرس وإلا بعته. فقام النبي ﷺ حين سمع نداء الأعرابي فقال: (( أوليس قد ابتعته منك؟ )) فقال الأعرابي: لا، والله ما بعتكه. فقال النبي ﷺ: (( بلى، قد ابتعته منك )). فطفق الأعرابي يقول: هلم شهيداً. فقال خزيمة بن ثابت: أنا أشهد أنك قد بايعته. فأقبل النبي ﷺ على خزيمة فقال: (( بم تشهد؟ )) فقال: بتصديقك يا رسول الله ﷺ. فجعل رسول اللّٰه ﷺ شهادة خزيمة بشهادة رجلين."],"takhrij":"صحيح: رواه أبو داود (٣٦٠٧)، والنسائي (٤٦٤٧)، وأحمد (٢١٨٨٣)، والحاكم (١٧-١٨/٢).","grade":"صحيح","chapter_ar":"باب جعل شهادة خزيمة بن ثابت شهادة رجلين","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abu Dawud (3607), al-Nasa’i (4647), Ahmad (21883), and al-Hakim (2/17–18).","chapter_en":"Making the testimony of Khuzaymah ibn Thabit equal to the testimony of two men","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Umarah ibn Khuzaymah reported that his uncle—who was one of the Companions of the Prophet ﷺ—said that the Prophet ﷺ bought a horse from a Bedouin. Then the Prophet ﷺ asked him to follow so he could pay him the price of the horse. The Prophet ﷺ walked quickly while the Bedouin lagged behind. Men began approaching the Bedouin and bargaining with him over the horse, not realizing that the Prophet ﷺ had already bought it. The Bedouin then called out to the Messenger of Allah ﷺ and said: If you are buying this horse, then buy it, otherwise I will sell it. When the Prophet ﷺ heard the call of the Bedouin, he stood and said: “Have I not already bought it from you?” The Bedouin said: No, by Allah, I have not sold it to you. The Prophet ﷺ said: “Rather, I have bought it from you.” The Bedouin then kept saying: Bring a witness. Khuzaymah ibn Thabit said: I testify that you did indeed make the sale with him.","The Prophet ﷺ turned to Khuzaymah and said: “On what basis do you testify?” He said: By believing you, O Messenger of Allah ﷺ. So the Prophet ﷺ made the testimony of Khuzaymah equal to the testimony of two men."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3607},{"key":"nasai","label":"النسائي","number":4647},{"key":"hakim","label":"الحاكم","number":17},{"key":"ahmad","label":"مسند الإمام أحمد","number":21883,"n":21883}]},{"num":6769,"demo":false,"sanad":"","matn":["عن ابن عباس قال: خرج رجل من بني سَهُم مع تميم الداري وعدي بن بداء. فمات السهمي بأرض ليس بها مسلم. فلما قدما بتركته فقدوا جاماً من فضة مخوّصا بالذهب. فأحلفهما رسول اللّٰه ﷺ، ثم وجدوا الجام بمكة، فقيل: اشتريناه من عدي وتميم، فقام رجلان من أولياء السهمي، فحلفا بالله: لشهادتنا أحق من شهادتهما. وإن الجام لصاحبهم. قال: وفيهم نزلت: (يَأْيُّهَا ٱلَّذِينَ ءَامَنُوا شَهَٰدَةُ بَيْنِكُمْ إِذَا حَضَرَأَحَدَكُمُ ٱلْمَوْتُ حِينَ ٱلْوَصِيَّةِ ٱثْنَانِ ذَوَا عَدْلٍ مِنكُمْ أَوْ ءَاخَرَانٍ مِنْ غَيْرِكُمْ) [ المائدة: ١٠٦ ]"],"takhrij":"صحيح: رواه البخاري (٢٧٨٠).","grade":"صحيح","chapter_ar":"باب شهادة أهل الذمة على وصية المسلم في السفر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhari (2780).","chapter_en":"The testimony of non-Muslim protected people concerning the will of a Muslim while traveling","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Ibn Abbas said: A man from Banu Sahm traveled with Tamim al-Dari and ʿAdi ibn Badda’. The Sahmi man died in a land where there were no Muslims. When they returned with his estate, they were found missing a silver cup ornamented with gold. The Messenger of Allah ﷺ made the two of them swear an oath. Then the cup was later found in Makkah, and it was said: We bought it from ʿAdi and Tamim. So two men from the heirs of the Sahmi stood and swore by Allah: Our testimony is more entitled to be accepted than their testimony, and the cup belongs to their relative. He said: Regarding them was revealed: “O you who believe, when death approaches one of you at the time of making a bequest, let there be two just men from among you, or two others from outside you…” [al-Ma’idah: 106]."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2780}]},{"num":6770,"demo":false,"sanad":"","matn":["عن الشعبي:","أن رجلًا من المسلمين حضرته الوفاة بدقوقاء هذه، ولم يجد أحدًا من المسلمين يشهده على وصيته، فأشهد رجلين من أهل الكتاب.","فقدما الكوفة، فأتيا أبا موسى الأشعري فأخبراه، وقدما بتركته ووصيته.","فقال الأشعري:","هذا أمر لم يكن بعد الذي كان في عهد رسول اللّٰه ﷺ.","فأحلفهما بعد العصر بالله ما خانا، ولا كذبا، ولا بدلا، ولا كتما، ولا غيرا، وإنها لوصية الرجل وتركته.","فأمضى شهادتهما."],"takhrij":"صحيح: رواه أبو داود (٣٦٠٥)، والبيهقي (١٠/١٦٥).","grade":"صحيح","chapter_ar":"باب شهادة أهل الذمة على وصية المسلم في السفر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3605) and al-Bayhaqī (10/165).","chapter_en":"The testimony of non-Muslim protected people concerning the will of a Muslim while traveling","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Al-Shaʿbī reported: A Muslim man was near death in Daqūqāʾ and could not find any Muslims to witness his will, so he called two men from the People of the Book as witnesses. They later came to Kūfah and went to Abū Mūsā al-Ashʿarī. They informed him of what had happened and brought with them the man’s estate and his will. Al-Ashʿarī said: “This is a matter that has not occurred since the case that occurred during the lifetime of the Messenger of Allah ﷺ.”","After the ʿAṣr prayer, he made the two men swear by Allah that they had neither betrayed the trust, lied, altered anything, concealed anything, nor changed anything, and that this was truly the man’s will and estate. He then accepted their testimony."]},"buhuth":{"ar":["ودقوقاء - بفتح الدال المهملة، وضم القاف، وبالقاف المقصورة - وهي بلد بين بغداد وإربل."],"en":["Daqūqāʾ is a town situated between Baghdad and Irbil."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3605},{"key":"البیہقی","label":"البيهقي","number":10},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":20626,"n":20784}]},{"num":6771,"demo":false,"sanad":"","matn":["عن البراء بن عازب أن رسول اللّٰه ﷺ دعا رجلاً من علماء اليهود فقال: (( أنشدك باللّٰه الذي أنزل التوراة على موسى ))."],"takhrij":"صحيح: رواه مسلم (١٧٠٠).","grade":"صحيح","chapter_ar":"باب شهادة أهل الذمة على وصية المسلم في السفر","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1700).","chapter_en":"The testimony of non-Muslim protected people concerning the will of a Muslim while traveling","part_en":"The Book of Judgement","group_ar":"مجموع أبواب ما جاء في الشهادات","group_en":"Collection of chapters regarding what has been narrated about testimonies","part_no":31,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Al-Bara’ ibn ʿAzib reported that the Messenger of Allah ﷺ called for a Jewish scholar and said: “I adjure you by Allah, the One who revealed the Torah to Musa.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1700}]},{"num":6772,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( إذا اختلفتم في الطريق جُعل عرضه سبع أذرع))."],"takhrij":"متفق عليه: رواه مسلم (١٦١٣)، والبخاري (٢٤٧٣) ولفظه: قضى النبي ﷺ إذا تشاجروا في الطريق سبعة أذرع.","grade":"متفق عليه","chapter_ar":"باب قدر الطريق إذا اختلفوا فيه","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1613), and al-Bukhari (2473), whose wording is: The Prophet ﷺ ruled, when they disputed over a road, that it should be seven cubits.","chapter_en":"The width of a road when people dispute over it","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “If you dispute concerning the road, its width is to be made seven cubits.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1613},{"key":"bukhari","label":"البخاري","number":2473}]},{"num":6773,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال:","اختصم إلى رسول اللّٰه ﷺ رجلان في حريم نخلة، فأمر بها فذرعت، فوجدت سبعة أذرع.","وفي رواية: خمسة أذرع.","فقضى بذلك."],"takhrij":"حسن: رواه أبو داود (٣٦٤٠).","grade":"حسن","chapter_ar":"باب القضاء في حريم النخلة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3640).","chapter_en":"Judgment concerning the protected surrounding space of a date palm","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported: Two men brought a dispute before the Messenger of Allah ﷺ concerning the protected surrounding space of a date palm. He ordered that it be measured, and it was found to be seven cubits.","In another narration: five cubits. He then gave judgment accordingly."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3640}]},{"num":6774,"demo":false,"sanad":"","matn":["عن عمير مولى آبي اللحم قال: أقبلت مع سادتي نريد الهجرة حتى إذا دنونا من المدينة، قال: فدخلوا المدينة وخلفوني في ظهورهم، قال: فأصابني مجاعة شديدة، قال: فمر بي بعض من يخرج من المدينة، فقالوا لي: لو دخلت المدينة، فأصبت من ثمر حوائطها، فدخلت حائطاً فقطعت منه قنوين، فأتاني صاحب الحائط، فأتى بي إلى رسول اللّٰه ﷺ وأخبره خبري، وعليَّ ثوبان، فقال لي: ((أيهما أفضل؟)) فأشرت له إلى أحدهما، فقال: ((خذه))، وأعطى صاحب الحائط الآخر، وخلى سبيلي."],"takhrij":"حسن: رواه الإمام أحمد (٢١٩٤٢).","grade":"حسن","chapter_ar":"باب القضاء في حريم النخلة","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Imam Ahmad (21942).","chapter_en":"Judgment concerning the protected surrounding space of a date palm","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["ʿUmayr, the freedman of Abi al-Lahm, said: I came with my masters intending hijrah, and when we drew near to Madinah, they entered the city and left me behind with their baggage. Then severe hunger struck me. Some people passing by me on their way out of Madinah said to me: “If you entered Madinah, you could get some fruit from its orchards.” So I entered an orchard and cut two clusters from it. Then the owner of the orchard came, took me to the Messenger of Allah ﷺ, and informed him of my case. I had two garments on me. He said to me: “Which of them is better?” I pointed to one of them, so he said: “Take it,” and he gave the other one to the owner of the orchard and let me go."]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":21942},{"key":"ahmad","label":"مسند الإمام أحمد","number":21942,"n":21942}]},{"num":6775,"demo":false,"sanad":"","matn":["عن عبد الله بن الزبير:","أن رجلًا من الأنصار خاصم الزبير عند رسول اللّٰه ﷺ في شراج الحرة التي يسقون بها النخل.","فقال الأنصاري:","سرح الماء يمر.","فأبى عليه، فاختصما إلى رسول اللّٰه ﷺ.","فقال رسول اللّٰه ﷺ للزبير:","«اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ».","فغضب الأنصاري فقال:","أن كان ابن عمتك؟","فتلون وجه رسول اللّٰه ﷺ، ثم قال:","«اسْقِ يَا زُبَيْرُ، ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ».","فقال الزبير:","والله إني لأحسب هذه الآية نزلت في ذلك:","﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ﴾","[النساء: ٦٥]"],"takhrij":"متفق عليه: رواه البخاري (٢٣٥٩)، ومسلم (٢٣٥٧).","grade":"متفق عليه","chapter_ar":"باب القضاء في سقي النخيل","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2359) and Muslim (2357).","chapter_en":"Judgement regarding irrigation of date palms","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn al-Zubayr reported: A man from the Anṣār disputed with al-Zubayr before the Messenger of Allah ﷺ concerning the water channels of al-Ḥarrah by which they irrigated their date palms. The Anṣārī said: “Let the water flow onward.” Al-Zubayr refused, so they brought their dispute before the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said to al-Zubayr: “Water your land, O Zubayr, then release the water to your neighbor.” The Anṣārī became angry and said: “Is it because he is your maternal aunt’s son?”","The face of the Messenger of Allah ﷺ changed color. He then said: “Water your land, O Zubayr, then retain the water until it reaches the wall.”","Al-Zubayr said: “By Allah, I believe this verse was revealed concerning that: ‘But no, by your Lord, they will not truly believe until they make you judge concerning that over which they dispute among themselves.’” [al-Nisāʾ: 65]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2359},{"key":"muslim","label":"مسلم","number":2357}]},{"num":6776,"demo":false,"sanad":"","matn":["عن ثعلبة بن أبي مالك أنه سمع كبراءهم يذكرون أن رجلاً من قريش كان له سهم في بني قريظة، فخاصم إلى رسول اللّٰه ﷺ في مهزور - يعني السيل الذي يقتسمون ماءه. فقضى بينهم رسول اللّٰه ﷺ أن الماء إلى الكعبين، ولا يحبس الأعلى على الأسفل."],"takhrij":"حسن: رواه أبو داود (٣٦٣٨)، وابن ماجه (٢٤٨١).","grade":"حسن","chapter_ar":"باب القضاء في سقي النخيل","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (3638) and Ibn Majah (2481).","chapter_en":"Judgement regarding irrigation of date palms","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Thaʿlabah ibn Abi Malik reported that he heard their elders mention that a man from Quraysh had a share among Banu Qurayzah, and he brought a dispute before the Messenger of Allah ﷺ regarding Mahzur — meaning the floodwater whose water they divided among themselves. The Messenger of Allah ﷺ judged between them that the water should be kept up to the ankles, and that the upper landowner should not hold it back from the lower one beyond that."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3638},{"key":"ibnmajah","label":"ابن ماجه","number":2481}]},{"num":6777,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول اللّٰه ﷺ قضى في سيل مهزور أن يُمسك حتى يبلغ الكعبين، ثم يرسل الماء."],"takhrij":"حسن: رواه أبو داود (٣٦٣٩) وابن ماجه (٢٤٨٢).","grade":"حسن","chapter_ar":"باب القضاء في سقي النخيل","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (3639) and Ibn Majah (2482).","chapter_en":"Judgement regarding irrigation of date palms","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb, from his father, from his grandfather, reported that the Messenger of Allah ﷺ judged concerning the floodwater of Mahzur that it should be held until it reached the ankles, then the water should be released."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":3639},{"key":"ibnmajah","label":"ابن ماجه","number":2482}]},{"num":6778,"demo":false,"sanad":"","matn":["عن أنس أن النبي ﷺ كان عند بعض نسائه، فأرسلت إحدى أمهات المؤمنين مع خادم بقصعة فيها طعام، فضربت بيدها فكسرت القصعة، فضمها وجعل فيها الطعام. وقال: ((كلوا)). وحبس الرسولَ والقصعة حتى فرغوا. فدفع القصعة الصحيحة، وحبس المكسورة."],"takhrij":"صحيح: رواه البخاري (٢٤٨١) و (٥٢٢٥).","grade":"صحيح","chapter_ar":"باب الحكم فيمن كسر شيئا","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (2481) and (5225).","chapter_en":"Judgement regarding one who breaks something","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ was with one of his wives, and one of the Mothers of the Believers sent, through a servant, a bowl containing food. The wife who was with him struck it with her hand and broke the bowl. He gathered its pieces together and placed the food in it, then said: “Eat.” He kept the servant and the bowl until they had finished, then he gave the sound bowl and kept the broken one."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2481},{"key":"و","label":"و","number":5225}]},{"num":6779,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( لا يمنع أحدكم جاره خشبة يغرزها في جداره)). ثم يقول أبو هريرة: مالي أراكم عنها معرضين، والله لأرمين بها بين أكتافكم."],"takhrij":"متفق عليه: رواه مالك (٣٤) والبخاري (٢٤٦٣) ومسلم (١٦٠٩).","grade":"متفق عليه","chapter_ar":"باب القضاء في المرفق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (34), al-Bukhari (2463), and Muslim (1609).","chapter_en":"Judgement regarding shared utility rights","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “None of you should prevent his neighbor from placing a piece of wood into his wall.” Then Abu Hurayrah would say: “Why do I see you turning away from this? By Allah, I will surely cast it between your shoulders.”"]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":34},{"key":"bukhari","label":"البخاري","number":2463},{"key":"muslim","label":"مسلم","number":1609}]},{"num":6780,"demo":false,"sanad":"","matn":["عن ابن عباس: أن رسول اللّٰه ﷺ قال:","«لَا يَمْنَعْ أَحَدُكُمْ أَخَاهُ مَرْفِقَهُ أَنْ يَضَعَ عَلَى جِدَارِهِ»."],"takhrij":"حسن: رواه أحمد (٢٣٠٧)، وابن ماجه (٢٣٣٧).","grade":"حسن","chapter_ar":"باب القضاء في المرفق","chapter_ur":"","part_ar":"كتاب القضاء","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (2307) and Ibn Mājah (2337).","chapter_en":"Judgement regarding shared utility rights","part_en":"The Book of Judgement","group_ar":"جموع ما جاء في أقضية النبي ﷺ","group_en":"Collection of what has come regarding the judgments of the Prophet ﷺ","part_no":31,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ said: “None of you should prevent his brother from making use of his wall for something from which he may benefit.”"]},"buhuth":{"ar":["ولفظ ابن ماجه:","«لَا يَمْنَعْ أَحَدُكُمْ جَارَهُ أَنْ يَغْرِزَ خَشَبَةً عَلَى جِدَارِهِ».","وقوله: «المرفق» هو كل ما يُرتفق به، أي يُنتفع به."],"en":["The wording of Ibn Mājah is:","“None of you should prevent his neighbor from placing a piece of wood upon his wall.”","The word al-mirfaq refers to anything by which benefit or practical use is obtained."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2337},{"key":"ahmad","label":"مسند الإمام أحمد","number":2307,"n":2307}]},{"num":6781,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: قال رسول اللّٰه ﷺ: (( لا يحل دم امرئ مسلم يشهد أن لا إله إلا الله، وأني رسول اللّٰه ﷺ إلا بإحدى ثلاث: النفس بالنفس، والثيّب الزاني، والتارك لدينه المفارق للجماعة ))."],"takhrij":"متفق عليه: رواه البخاري (٦٨٧٨) ومسلم (١٦٧٦).","grade":"متفق عليه","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6878) and Muslim (1676).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd said: The Messenger of Allah ﷺ said, “The blood of a Muslim who testifies that there is no god but Allah and that I am the Messenger of Allah ﷺ is not lawful except in one of three cases: a life for a life, a previously married adulterer, and the one who abandons his religion and separates from the community.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6878},{"key":"muslim","label":"مسلم","number":1676}]},{"num":6782,"demo":false,"sanad":"","matn":["عن أبي أمامة بن سهل قال:","كنا مع عثمان وهو محصور في الدار، وكان في الدار مدخل من دخله سمع كلام من على البلاط، فدخله عثمان، فخرج إلينا وهو متغير لونه، فقال:","إنهم ليتواعدوني بالقتل آنفًا.","قلنا:","يكفيكهم الله يا أمير المؤمنين.","قال:","ولم يقتلونني؟ سمعت رسول اللّٰه ﷺ يقول:","«لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلَاثٍ: كُفْرٌ بَعْدَ إِسْلَامٍ، أَوْ زِنًا بَعْدَ إِحْصَانٍ، أَوْ قَتْلُ نَفْسٍ بِغَيْرِ نَفْسٍ».","فوالله ما زنيت في جاهلية ولا إسلام قط، ولا أحببت أن لي بديني بدلًا منذ هداني الله، ولا قتلت نفسًا، فبم يقتلونني؟"],"takhrij":"صحيح: رواه أبو داود (٤٥٠٢)، والترمذي (٢١٥٨) وحسنه، والنسائي (٤٠١٩)، وابن ماجه (٢٥٣٣).","grade":"صحيح","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4502), al-Tirmidhī (2158), who graded it good, al-Nasā’ī (4019), and Ibn Mājah (2533).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah ibn Sahl reported: We were with ʿUthmān while he was besieged in his house. There was an entrance in the house through which whoever entered could hear the speech of those outside on the paved area. ʿUthmān entered it and then came out to us with his complexion changed. He said: “They have just threatened to kill me.” We said: “Allah will suffice you against them, O Commander of the Believers.” He said: “Why would they kill me? I heard the Messenger of Allah ﷺ say: ‘The blood of a Muslim is not lawful except in one of three cases: disbelief after Islam, adultery after having been married, or killing a person without a right of retaliation.’","By Allah, I never committed adultery either in the pre-Islamic period or in Islam; I have never wished to exchange my religion for another since Allah guided me; and I have never killed anyone. So for what reason would they kill me?”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4502},{"key":"tirmidhi","label":"الترمذي","number":2158},{"key":"nasai","label":"النسائي","number":4019},{"key":"ibnmajah","label":"ابن ماجه","number":2533}]},{"num":6783,"demo":false,"sanad":"","matn":["عن ابن عمر أن عثمان أشرف على أصحابه وهو محصور فقال: علامَ تقتلوني؟ فإني سمعت رسول اللّٰه ﷺ يقول: (( لا يحل دم امرئ مسلم إلا بإحدى ثلاث: رجل زنى بعد إحصانه فعليه الرجم، أو قتل عمداً فعليه القود، أو ارتدّ بعد إسلامه فعليه القتل)).","فو الله ما زنيت في جاهلية ولا في إسلام، ولا قتلت أحداً فأقيد نفسي منه، ولا ارتددت منذ أسلمت، إني أشهد أن لا إله إلا الله، وأن محمداً عبده ورسوله."],"takhrij":"حسن: رواه أحمد (٤٥٢) واللفظ له، والنسائي (٤٠٥٧) والبزار في مسنده (٩/٢) وأبو عاصم في الديات (١١١).","grade":"حسن","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Aḥmad (452), and this is his wording, al-Nasā’ī (4057), al-Bazzār in his Musnad (9/2), and Abū ʿĀṣim in al-Diyāt (111).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar reported that ʿUthmān looked out over his companions while under siege and said, “Why are you killing me? I heard the Messenger of Allah ﷺ say: ‘The blood of a Muslim is not lawful except in one of three cases: a man who commits adultery after marriage, so he is to be stoned; one who kills deliberately, so retaliation is due from him; or one who apostasizes after Islam, so he is to be killed.’ By Allah, I never committed adultery in ignorance or in Islam, nor have I killed anyone such that retaliation would be due from me, nor have I apostatized since I accepted Islam. I testify that there is no god but Allah and that Muhammad is His servant and Messenger.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4057},{"key":"البزار/مسندہ","label":"البزار في مسنده","number":9},{"key":"ابو_عاصم/الدیات","label":"أبو عاصم في الديات","number":111},{"key":"ahmad","label":"مسند الإمام أحمد","number":452,"n":452}]},{"num":6784,"demo":false,"sanad":"","matn":["عن عقبة بن مالك قال: بعث رسول اللّٰه ﷺ سرية، قال: فأغارت على قوم، قال: فشذ من القوم رجل، قال: فأتبعه رجل من السرية شاهراً سيفه، قال: فقال الشاذ من القوم، إني مسلم، قال: فلم ينظر فيما قال، فضربه فقتله، قال: فنمى الحديث إلى رسول اللّٰه ﷺ، قال: فقال فيه قولاً شديداً، فبلغ القاتل، قال: فبينا رسول اللّٰه ﷺ يخطب إذ قال القاتل: يا رسول الله ﷺ، والله ما قال الذي قال إلا تعوذا من القتل. قال: فأعرض عنه، وعمن قبله من الناس، وأخذ في خطبته، ثم قال أيضا: يا رسول الله ﷺ، ما قال الذي قال إلا تعوذاً من القتل. فأعرض عنه وعمن قبله من الناس وأخذ في خطبته، ثم لم يصبر، فقال الثالثة: يا رسول الله ﷺ، والله ما قال إلا تعوذا من القتل. فأقبل عليه رسول اللّٰه ﷺ، تُعرف المساءة في وجهه. فقال له: (( إن اللّٰه عز وجل أبى عليّ أن أقتل مؤمناً ))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٢٤٩٠) وأبو يعلى (٦٨٢٩) والطبراني (٣٥٥/١٧) وابن أبي عاصم في الديات (٤٠).","grade":"صحيح","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Imām Aḥmad (22490), Abū Yaʿlā (6829), al-Ṭabarānī (17/355), and Ibn Abī ʿĀṣim in al-Diyāt (40).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn Mālik said: The Messenger of Allah ﷺ sent a military detachment. It raided a people, and one man from them fled. A man from the detachment pursued him with his sword drawn. The fleeing man said, “I am Muslim.” But he paid no attention to what he said and struck him, killing him. The report reached the Messenger of Allah ﷺ, and he spoke very sternly about it. This reached the killer. Then while the Messenger of Allah ﷺ was delivering a sermon, the killer said, “O Messenger of Allah ﷺ, by Allah, he only said what he said to seek protection from being killed.” The Prophet ﷺ turned away from him and from the people in front of him and continued his sermon. Then he said again, “O Messenger of Allah ﷺ, he only said it to escape being killed.” The Prophet ﷺ again turned away from him and continued. Then he could not restrain himself and said it a third time. The Messenger of Allah ﷺ then turned to him, with displeasure visible on his face, and said, “Allah, Mighty and Majestic, has refused to allow me to kill a believer.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":22490},{"key":"ابو_یعلی","label":"أبو يعلى","number":6829},{"key":"الطبرانی","label":"الطبراني","number":355},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":40},{"key":"ahmad","label":"مسند الإمام أحمد","number":22490,"n":22490},{"key":"sh12520","label":"مسند أبي يعلى","number":6829,"n":6835}]},{"num":6785,"demo":false,"sanad":"","matn":["عن عبد اللّه بن عدي الأنصاري حدّث أن رسول اللّٰه ﷺ، بينا هو جالس بين ظهراني الناس جاءه رجل يستأذنه - أو يشاوره - يسارّه في قتل رجل من المنافقين يستأذن فيه. فجهر رسول اللّٰه ﷺ كلامه فقال: (( أليس يشهد أن لا إله إلا اللّٰه )) قال: بلى، ولكن لا شهادة له، قال: (( أليس يشهد أني رسول الله ﷺ؟ )) قال: بلى، ولا شهادة له، قال: (( أليس يصلي؟ )) قال: بلى، ولا صلاة له، قال: (( أولئك الذين نُهيت عنهم))."],"takhrij":"صحيح: رواه الإمام أحمد (٢٣٦٧١) والبيهقي (١٩٦/٨) وصحّحه ابن حبان (٥٩٧١).","grade":"صحيح","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Imām Aḥmad (23671), al-Bayhaqī (8/196), and authenticated by Ibn Ḥibbān (5971).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAdī al-Anṣārī narrated that while the Messenger of Allah ﷺ was sitting among the people, a man came to him seeking permission, or consulting him privately, about killing a certain hypocrite. The Messenger of Allah ﷺ then spoke aloud and said, “Does he not testify that there is no god but Allah?” He said, “Yes, but his testimony carries no weight.” He said, “Does he not testify that I am the Messenger of Allah ﷺ?” He said, “Yes, but his testimony carries no weight.” He said, “Does he not pray?” He said, “Yes, but there is no prayer in him.” He said, “Those are the ones I have been forbidden to kill.”"]}},"tuhfa":{},"refs":[{"key":"الامام_احمد","label":"الإمام أحمد","number":23671},{"key":"البیہقی","label":"البيهقي","number":196},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5971},{"key":"ahmad","label":"مسند الإمام أحمد","number":23671,"n":23671},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":6502,"n":6536}]},{"num":6786,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ أُتي بمخنث قد خضب يديه، ورجليه بالحناء، فقال رسول اللّٰه ﷺ: ((ما بال هذا؟)) فقيل: يارسول اللّٰه ﷺ يتشبه بالنساء، فأمر به فنُفي إلى النقيع. قالوا: يا رسول اللّٰه ﷺ ألا نقتله. قال: (( إني نهيت عن قتل المصلين ))"],"takhrij":"حسن: رواه أبو داود (٤٩٢٨) وأبو يعلى (٦١٢٦) والبيهقي (٢٢٢/٨).","grade":"حسن","chapter_ar":"باب لا يحل دم امرى مسلم إلا في ثلاث","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abū Dāwūd (4928), Abū Yaʿlā (6126), and al-Bayhaqī (8/222).","chapter_en":"The blood of a Muslim is not lawful except in three cases","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ was brought a feminine man whose hands and feet had been dyed with henna. The Messenger of Allah ﷺ said, “What is the matter with this one?” It was said, “O Messenger of Allah ﷺ, he imitates women.” So he ordered that he be banished to al-Naqīʿ. They said, “O Messenger of Allah ﷺ, should we not kill him?” He said, “I have been forbidden from killing those who pray.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4928},{"key":"ابو_یعلی","label":"أبو يعلى","number":6126},{"key":"البیہقی","label":"البيهقي","number":222},{"key":"sh12520","label":"مسند أبي يعلى","number":6126,"n":6132},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":16987,"n":17145}]},{"num":6787,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: أمرني عبد الرحمن بن أبزى قال: سل ابن عباس عن هاتين الآيتين ما أمرهما: (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ [الأنعام: ١٥١، الإسراء: ٣٣] (وَمَن يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا [النساء: ٩٣ ] فسألت ابن عباس فقال: لما أنزلت التي في الفرقان وهي قوله تعالى: (وَٱلَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهَا ءَاخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا ) [الفرقان: ٦٨] قال مشركوا أهل مكة: فقد قتلنا النفس التي حرم الله، ودعونا مع اللّٰه إلها آخر. وقد أتينا الفواحش فأنزل اللّٰه تعالى: ( إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُورًا رَحِيمَا) [الفرقان: ٧٠]","فهذه لأولئك، وأما التي في النساء: [٩٣] فالرجل إذا عرف الإسلام وشرائعه، ثم قتل فجزاؤه جهنم. فذكرته لمجاهد فقال: إلا من ندم."],"takhrij":"متفق عليه: رواه البخاري (٣٨٥٥)، ومسلم (١٨:٣٠٢٣).","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (3855) and Muslim (3023, no. 18).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿīd ibn Jubayr said: ʿAbd al-Raḥmān ibn Abzā instructed me, saying: Ask Ibn ʿAbbās about these two verses and what their ruling is: “Do not kill the soul which Allah has forbidden” [al-Anʿām: 151; al-Isrāʾ: 33] and “Whoever kills a believer intentionally…” [al-Nisāʾ: 93]. So I asked Ibn ʿAbbās. He said: When the verse in Sūrat al-Furqān was revealed—“Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery…” [al-Furqān: 68]—the polytheists of Makkah said: We have killed the soul Allah has forbidden, called upon another god besides Allah, and committed immoral deeds. So Allah revealed: “Except for those who repent, believe, and do righteous deeds; for them Allah will replace their evil deeds with good deeds, and Allah is Ever-Forgiving, Most Merciful.” [al-Furqān: 70] This was for them. But as for the verse in Sūrat al-Nisāʾ [93], it concerns the man who knew Islam and its laws and then killed; his recompense is Hell. I mentioned this to Mujāhid, and he said: except the one who repents."]},"intro":{"ar":["قال اللّٰه تعالى: (وَمَن يَقَّتُّلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَآؤُهُ جَهَنَّمُ خَٰلِدًا فِيهَا وَعَضِبَ اللَّهُ عَيدِوَنَهُ وَأَعَدَّلَهُ عَذَابًا عَظِيمًا [سورة النساء: ٩٣ )","وقال تعالى: (وَٱلّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إلَهَا ءَاخَرَ وَلَا يَقْتُلُونَ ٱلنَّفْسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُنٌ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَئَامًا (٦ يُضَعَفْ لَهُ ٱلْعَذَابُ يَوْمَ ٱلْقِيَمَةِ وَيَخْلُدْ فِيهِ مُهَانًا (١) إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلًا صَالِحًا) [ الفرقان: ٧٠ - ٦٨]"],"en":["Allah Most High said: “Whoever kills a believer intentionally, his recompense is Hell, abiding therein; and Allah is angry with him, has cursed him, and prepared for him a tremendous punishment.” [Sūrat al-Nisāʾ: 93]","And He said: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery. Whoever does that will meet a penalty. The punishment will be multiplied for him on the Day of Resurrection, and he will abide therein humiliated, except for those who repent, believe, and do righteous deeds.” [Sūrat al-Furqān: 68–70]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3855},{"key":"muslim","label":"مسلم","number":18}]},{"num":6788,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: اختلف أهل الكوفة في هذه الآية: (وَمَن يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ [النساء: ٩٣ ] فرحلت إلى ابن عباس فسألته عنها فقال: لقد أنزلت آخر ما أنزل، ثم ما نسخها شيء."],"takhrij":"متفق عليه: رواه البخاري (٤٥٩٠) ومسلم (٣٠٣٢).","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (4590) and Muslim (3032).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿīd ibn Jubayr said: The people of Kūfah differed concerning this verse: “Whoever kills a believer intentionally, his recompense is Hell…” [al-Nisāʾ: 93]. So I traveled to Ibn ʿAbbās and asked him about it. He said: It was among the last things revealed, and nothing abrogated it."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4590},{"key":"muslim","label":"مسلم","number":3032}]},{"num":6789,"demo":false,"sanad":"","matn":["عن سعيد بن جبير قال: قلت لابن عباس: ألمن قتل مؤمنا متعمدا من توبة؟ قال:","لا. قال: فتلوت عليه هذه الآية التي في الفرقان: (وَٱلَّذِينَ لَا يَدْعُونَ مَعَ اللَّه إِلَهًا ءَاخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ [الفرقان: ٦٨] إلى آخر الآية قال: هذه آية مكية، نسختها آية مدنية (وَمَن يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَآؤُهُ جَهَنَّمُ خَالِدًا) [النساء: ٩٣]."],"takhrij":"متفق عليه: رواه مسلم (٢٠:٣٠٢٣) والبخاري (٤٧٦٢).","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Muslim (3023, no. 20) and al-Bukhārī (4762).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿīd ibn Jubayr said: I asked Ibn ʿAbbās, “Is there repentance for the one who kills a believer intentionally?” He said, “No.” I then recited to him the verse in Sūrat al-Furqān: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right…” [al-Furqān: 68] through the end of the passage. He said: That is a Makkan verse, and it was superseded by the Madinan verse: “Whoever kills a believer intentionally, his recompense is Hell, abiding therein.” [al-Nisāʾ: 93]"]},"buhuth":{"en":["Al-Nawawī said in his commentary on Muslim: This is the well-known view reported from Ibn ʿAbbās. It is also reported from him that such a person may repent, and that forgiveness is possible, based on the saying of Allah Most High: “Whoever does evil or wrongs himself, then seeks Allah’s forgiveness, will find Allah Forgiving and Merciful.” [al-Nisāʾ: 110] This second narration is the position of all the people of Sunnah, the Companions, the Followers, and those after them. Whatever has been reported from some of the early Muslims contrary to this is understood as severe warning and deterrence from killing, and not as an absolute denial of repentance. Moreover, the verse cited by Ibn ʿAbbās does not explicitly state that he will certainly remain forever; it only says that Hell is his recompense, and that does not necessarily mean the recompense must be executed. Others said that the verse, “Whoever kills a believer intentionally,” is general and should be understood as referring to the one who does not repent, since the other verse is restricted by repentance. Also, Allah Most High said: “Indeed, Allah does not forgive associating partners with Him, but He forgives what is less than that for whom He wills.” [al-Nisāʾ: 48] Thus non-forgiveness is confined to polytheism alone."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":20},{"key":"bukhari","label":"البخاري","number":4762}]},{"num":6790,"demo":false,"sanad":"","matn":["عن ابن عباس أن قوماً كانوا قتلوا فأكثروا، وزنوا فأكثروا، وانتهكوا، فأتوا النبي ﷺ فقالوا: يا محمد، إن الذي تقول وتدعو إليه لحسن، لو تخبرنا أن لما عملنا كفارة. فأنزل اللّٰه عز وجل: ﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَٰهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا ۝ إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَٰئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ﴾ [الفرقان: ٦٨-٧٠]. قال: يبدل اللّٰه شركهم إيماناً، وزناهم إحصاناً. ونزلت: ﴿قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ﴾ [الزمر: ٥٣]."],"takhrij":"حسن: أخرجه النسائي (٤٠٠٣)، والحاكم (٣٥٢٢).","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: recorded by al-Nasā’ī (4003) and al-Ḥākim (3522).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās said: Some people had committed many killings, much adultery, and many grave violations. Then they came to the Prophet ﷺ and said: “O Muhammad, what you say and call to is good. If only you could tell us whether there is an expiation for what we have done.” So Allah, Mighty and Majestic, revealed: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery… except for those who repent, believe, and do righteous deeds; for them Allah will replace their evil deeds with good deeds.” [al-Furqān: 68–70] He said: Allah would replace their polytheism with faith, and their adultery with chastity. And this was also revealed: “Say: O My servants who have transgressed against themselves, do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Truly He is the Forgiving, the Merciful.” [al-Zumar: 53]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4003},{"key":"hakim","label":"الحاكم","number":3522}]},{"num":6791,"demo":false,"sanad":"","matn":["عبد الله بن عمر قال: قال رسول اللّٰه ﷺ: (( لن يزال المؤمن في فسحة من دينه ما لم يصب دماً حراماً ))."],"takhrij":"صحيح: رواه البخاري (٦٨٦٢).","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (6862).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: The Messenger of Allah ﷺ said, “A believer remains within spaciousness in his religion so long as he does not shed unlawful blood.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6862}]},{"num":6792,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو قال: قال رسول اللّٰه ﷺ: (( أكبر الكبائر الإشراك بالله، وقتل النفس، وعقوق الوالدين ))."],"takhrij":"صحيح: رواه البخاري (٦٨٧٠).","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (6870).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr said: The Messenger of Allah ﷺ said, “The greatest of the major sins are associating partners with Allah, killing a soul, and disobeying one’s parents.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6870}]},{"num":6793,"demo":false,"sanad":"","matn":["عن أبي أيوب أن رسول اللّٰه ﷺ قال: (( من جاء يعبد الله، لا يشرك به شيئاً، ويقيم الصلاة، ويؤتي الزكاة، ويصوم رمضان، ويجتنب الكبائر فإن له الجنة )) وسألوه ما الكبائر؟ قال:","(( الإشراك بالله، وقتل النفس المسلمة، وفرار يوم الزحف ))"],"takhrij":"حسن: رواه النسائي (٤٠٠٩) وأحمد (٢٣٥٠٢) والطحاوي في مشكله (٨٩٦).","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (4009), Aḥmad (23502), and al-Ṭaḥāwī in Mushkil al-Āthār (896).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abū Ayyūb reported that the Messenger of Allah ﷺ said, “Whoever comes worshipping Allah without associating anything with Him, establishes prayer, gives zakāh, fasts Ramadan, and avoids the major sins will have Paradise.” They asked him, “What are the major sins?” He said, “Associating partners with Allah, killing a Muslim soul, and fleeing on the day of battle.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4009},{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":896},{"key":"ahmad","label":"مسند الإمام أحمد","number":23502,"n":23502}]},{"num":6794,"demo":false,"sanad":"","matn":["عن الأحنف بن قيس قال: ذهبت لأنصر هذا الرجل فلقيني أبو بكرة فقال: أين تريد؟ قلت: أنصر هذا الرجل. قال: ارجع، فإني سمعت رسول اللّٰه ﷺ يقول: (( إذا التقى المسلمان بسيفيهما فالقاتل والمقتول في النار )) فقلت: يا رسول اللّٰه ﷺ هذا القاتل، فما بال المقتول؟ قال: (( إنه كان حريصاً على قتل صاحبه ))."],"takhrij":"صحيح: رواه البخاري (٣١) ومسلم (٢٨٨٨). ورواه مسلم من طريق آخر بلفظ: (( إذا المسلمان حمل أحدهما علي أخيه السلاح، فهما على جرف جهنم، فإذا قتل أحدهما صاحبه دخلاها جميعا )). يقول النووي رحمه اللّٰه تعالى في شرح مسلم: “واعلم أن الدماء التي جرت بين الصحابة، رضي اللّٰه عنهم ليست بداخلة في هذا الوعيد. ومذهب أهل السنة والحق إحسان الظن بهم، والإمساك عما شجر بينهم، وتأويل قتالهم أنهم مجتهدون”.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (31) and Muslim (2888). Muslim also narrated by another route with the wording: “When two Muslims raise weapons against one another, both are on the brink of Hell; if one kills the other, they both enter it.”","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["al-Aḥnaf ibn Qays said: I went out intending to support this man, but Abū Bakrah met me and said, “Where are you going?” I said, “To support this man.” He said, “Go back, for I heard the Messenger of Allah ﷺ say: ‘When two Muslims confront each other with their swords, both the killer and the one killed are in the Fire.’” I said, “O Messenger of Allah ﷺ, this is the killer—but what about the one killed?” He said, “He was eager to kill his companion.”"]},"buhuth":{"en":["Al-Nawawī, may Allah have mercy on him, said in his commentary on Muslim: Know that the bloodshed that occurred among the Companions, may Allah be pleased with them, is not included in this warning. The position of the people of Sunnah, and the truth, is to maintain good opinion of them, refrain from discussing the conflicts that took place among them, and interpret their fighting as the result of sincere legal reasoning."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":31},{"key":"muslim","label":"مسلم","number":2888}]},{"num":6795,"demo":false,"sanad":"","matn":["عن عمرو بن الحِمَق الخزاعي قال: سمعت رسول اللّٰه ﷺ يقول: (( من أمن رجلاً على دمه، فقتله، فإنه يحمل لواء غدر يوم القيامة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٦٨٨)، وأحمد (٢١٩٤٦) واللفظ لابن ماجه.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Mājah (2688) and Aḥmad (21946), with the wording here from Ibn Mājah.","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAmr ibn al-Ḥimaq al-Khuzāʿī said: I heard the Messenger of Allah ﷺ say, “Whoever grants a man safety regarding his life and then kills him will carry the banner of treachery on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2688},{"key":"ahmad","label":"مسند الإمام أحمد","number":21946,"n":21946}]},{"num":6796,"demo":false,"sanad":"","matn":["عن خالد بن دِهقان قال: كنا في غزوة القسطنطينية بذلقية، فأقبل رجل من أهل فلسطين من أشرافهم وخيارهم، يعرفون ذلك له، يقال له هانئ بن كلثوم بن شريك الكناني، فسلم على عبد اللّه بن أبي زكريا - وكان يعرف له حقه - فقال لنا خالد: فحدثنا عبدالله بن أبي زكريا قال:","سمعت أم الدرداء تقول: سمعت أبا الدرداء يقول: سمعت رسول اللّٰه ﷺ يقول: (( كل ذنب عسى اللّٰه أن يغفره، إلا من مات مشركاً، أو من قتل مؤمنا متعمداً )) فقال هانئ بن كلثوم: سمعت محمود بن الربيع يحدث عن عبادة بن الصامت، أنه سمعه يحدث عن رسول اللّٰه ﷺ أنه قال: (( من قتل مؤمنا فاغتبط بقتله لم يقبل اللّٰه منه صرفا ولا عدلاً )) قال لنا خالد: ثم حدثني ابن أبي زكريا، عن أم الدرداء، عن أبي الدرداء، عن رسول اللّٰه ﷺ أنه قال: (( لا يزال المؤمن معنقاً صالحاً ما لم يصب دماً حراماً، فإذا أصاب دماً حراماً بلّح )) وحدّث هانئ بن كلثوم، عن محمود بن الربيع، عن عبادة بن الصامت، عن رسول اللّٰه ﷺ مثله سواء."],"takhrij":"صحيح: رواه أبو داود (٤٢٧٠) وصحّحه ابن حبان (٥٩٨٠) والحاكم (٣٥١/٤) وابن أبي عاصم في الديات (٢٩).","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abū Dāwūd (4270), authenticated by Ibn Ḥibbān (5980) and al-Ḥākim (4/351), and also by Ibn Abī ʿĀṣim in al-Diyāt (29).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Khālid ibn Dihqān said: We were on the campaign to Constantinople at Dhalqiyyah when a man from the people of Palestine approached. He was one of their nobles and best men, known among them for that, and he was called Hānī ibn Kulthūm ibn Sharīk al-Kinānī. He greeted ʿAbdullāh ibn Abī Zakariyyā, who was recognized as having a right over him. Khālid said: Then ʿAbdullāh ibn Abī Zakariyyā narrated to us, saying: I heard Umm al-Dardāʾ say: I heard Abū al-Dardāʾ say: I heard the Messenger of Allah ﷺ say, “Every sin may be forgiven by Allah, except for one who dies as a polytheist, or one who kills a believer deliberately.” Then Hānī ibn Kulthūm said: I heard Maḥmūd ibn al-Rabīʿ narrating from ʿUbādah ibn al-Ṣāmit that he heard the Messenger of Allah ﷺ say, “Whoever kills a believer and is pleased with having killed him, Allah will not accept from him any compensation or ransom.” Khālid said: Then Ibn Abī Zakariyyā also narrated to me from Umm al-Dardāʾ, from Abū al-Dardāʾ, that the Messenger of Allah ﷺ said, “A believer continues advancing in goodness so long as he does not shed unlawful blood; once he sheds unlawful blood, he is ruined.” And Hānī ibn Kulthūm narrated from Maḥmūd ibn al-Rabīʿ, from ʿUbādah ibn al-Ṣāmit, from the Messenger of Allah ﷺ, something to the same effect."]},"buhuth":{"ar":["وقوله: بلح: أي بلح الرجل إذا انقطع من الإعياء، فلم يقدر أن يتحرك. وقد أبلحه السير فانقطع فيه، يريد به وقوعه في الهلاك بإصابة الدم الحرام.","قال خالد بن دهقان: سألت يحيى بن يحيى الغسّاني عن قوله: (( فاغتبط بقتله )) قال: الذين يقاتلون في الفتنة فيقتل أحدهم فيرى أنه على هدى لا يستغفر الله، يعني من ذلك. ذكره أبو داود (٤٢٧١) وقال: فاغتبط يصب دمه صبّا."],"en":["The phrase “he is ruined” means that a person becomes exhausted and cut off, unable to move onward. The intended meaning is that he falls into destruction by shedding unlawful blood.","Khālid ibn Dihqān said: I asked Yaḥyā ibn Yaḥyā al-Ghassānī about the phrase “and is pleased with killing him.” He said: It refers to those who fight during civil strife, and one of them kills another while thinking he is rightly guided, so he does not seek Allah’s forgiveness for it. Abū Dāwūd mentioned this (4271) and said it means he pours out his blood deliberately."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4270},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5980},{"key":"hakim","label":"الحاكم","number":351},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":29}]},{"num":6797,"demo":false,"sanad":"","matn":["عن معاوية قال: سمعت رسول اللّٰه ﷺ يقول: (( كل ذنب عسى اللّٰه أن يغفره إلا الرجل يقتل المؤمن متعمداً، أو الرجل يموت كافراً ))."],"takhrij":"حسن: رواه النسائي (٣٩٨٤) وأحمد (١٦٩٠٧) وابن أبي عاصم في الديات (٢٧) وصحّحه الحاكم (٣٥١/٤).","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3984), Aḥmad (16907), and Ibn Abī ʿĀṣim in al-Diyāt (27), and authenticated by al-Ḥākim (4/351).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Muʿāwiyah said: I heard the Messenger of Allah ﷺ say, “Every sin may be forgiven by Allah except for a man who kills a believer deliberately, or a man who dies as a disbeliever.”"]},"buhuth":{"ar":["وقوله: (( الرجل يقتل )) ظاهر هذا الحديث موافق للقرآن، وبه قال غير واحد من السلف، والجمهور على أنه محمول على التغليظ لقوله تعالى: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ﴾ [النساء: ١١٦]."],"en":["The apparent meaning of this report agrees with the Qur’an, and a number of the early scholars held to it. The majority, however, understood it as severe warning, based on the verse: “Indeed, Allah does not forgive associating partners with Him, but He forgives what is less than that for whom He wills.” [al-Nisāʾ: 116]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3984},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":27},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":351},{"key":"ahmad","label":"مسند الإمام أحمد","number":16907,"n":16907}]},{"num":6798,"demo":false,"sanad":"","matn":["عن عقبة بن عامر الجهني قال: قال رسول اللّٰه ﷺ: ((من لقي اللّٰه لا يشرك به شيئاً، لم يتندَّ بدم حرام، دخل الجنة))."],"takhrij":"صحيح: رواه ابن ماجه (٢٦١٨) وأحمد ( ١٧٣٨١) وصحّحه الحاكم (٣٥٢-٣٥١/٤).","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Mājah (2618) and Aḥmad (17381), and authenticated by al-Ḥākim (4/351–352).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī said: The Messenger of Allah ﷺ said, “Whoever meets Allah without associating anything with Him and without staining himself with unlawful blood will enter Paradise.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2618},{"key":"صححہ_الحاکم","label":"صحّحه الحاكم","number":352},{"key":"ahmad","label":"مسند الإمام أحمد","number":17381,"n":17381}]},{"num":6799,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مسعود أن النبي ﷺ قال: (( سباب المسلم فسوق وقتاله كفر))."],"takhrij":"متفق عليه: رواه البخاري (٤٨) ومسلم (٦٤).","grade":"متفق عليه","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (48) and Muslim (64).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported that the Prophet ﷺ said, “Insulting a Muslim is sinful rebellion, and fighting him is disbelief.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":48},{"key":"muslim","label":"مسلم","number":64}]},{"num":6800,"demo":false,"sanad":"","matn":["عن سعد بن أبي وقاص أن النبي ﷺ قال: (( قتال المسلم كفر، وسبابه فسق))."],"takhrij":"صحيح: رواه أحمد (١٥٣٧) والبخاري في الأدب المفرد (٤٢٩) وابن نصر في تعظيم قدر الصلاة (١٠٩٩).","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Aḥmad (1537), al-Bukhārī in al-Adab al-Mufrad (429), and Ibn Naṣr in Taʿẓīm Qadr al-Ṣalāh (1099).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ reported that the Prophet ﷺ said, “Fighting a Muslim is disbelief, and insulting him is sinful rebellion.”"]}},"tuhfa":{},"refs":[{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":429},{"key":"ابن_نصر/تعظیم_قدر_الصلاہ","label":"ابن نصر في تعظيم قدر الصلاة","number":1099},{"key":"ahmad","label":"مسند الإمام أحمد","number":1537,"n":1537}]},{"num":6801,"demo":false,"sanad":"","matn":["عن ابن مسعود، عن النبي ﷺ قال: ( يجيء الرجل آخذاً بيد الرجل، فيقول: يا رب هذا قتلني، فيقول اللّٰه له: لم قتلته؟ فيقول: قتلته لتكون العزة لك. فيقول: فإنها لي، ويجيء الرجل آخذاً بيد الرجل فيقول: إن هذا قتلني. فيقول اللّٰه له: لم قتلته؟ فيقول: لتكون العزة لفلان. فيقول:","إنها ليست لفلان فيبوء بإثمه )."],"takhrij":"صحيح: رواه النسائي (٣٩٩٧) والبيهقي (١٩١/٨).","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3997) and al-Bayhaqī (8/191).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn Masʿūd reported that the Prophet ﷺ said, “A man will come holding another man by the hand and say: ‘My Lord, this one killed me.’ Allah will say to him: ‘Why did you kill him?’ He will say: ‘I killed him so that honor would belong to You.’ Allah will say: ‘Indeed, it belongs to Me.’ Another man will come holding another by the hand and say: ‘This one killed me.’ Allah will say to him: ‘Why did you kill him?’ He will say: ‘So that honor would belong to so-and-so.’ Allah will say: ‘It does not belong to so-and-so,’ and he will return bearing his sin.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3997},{"key":"البیہقی","label":"البيهقي","number":191}]},{"num":6802,"demo":false,"sanad":"","matn":["عن أبي عمران قال: قلت لجندب: إني قد بايعت هؤلاء- يعني ابن الزبير - وإنهم يريدون أن أخرج معهم إلى الشام. فقال: أمسك. فقلت: إنهم يأبون. فقال: افتدِ بمالك. قال: قلت:","إنهم يأبون إلا أن أضرب معهم بالسيف. فقال جندب: حدثني فلان أن رسول اللّٰه ﷺ قال: (( يجيء المقتول بقاتله يوم القيامة. فيقول: يا رب سلّ هذا فيم قتلني؟)) قال شعبة: فأحسبه قال: (( فيقول:","علام قتلته؟ فيقول: قتلته على ملك فلان )) فقال جندب: فاتقها."],"takhrij":"صحيح: رواه النسائي (٣٩٩٨)، وأحمد (١٦٦٠٠) واللفظ لأحمد.","grade":"صحيح","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3998) and Aḥmad (16600), with the wording here from Aḥmad.","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abū ʿImrān said: I said to Jundub, “I have pledged allegiance to these people”—meaning Ibn al-Zubayr—“and they want me to go out with them to Syria.” He said: “Hold back.” I said: “They refuse.” He said: “Ransom yourself with your wealth.” I said: “They refuse unless I fight with them by the sword.” Jundub then said: So-and-so narrated to me that the Messenger of Allah ﷺ said, “The one who was killed will come on the Day of Resurrection holding his killer and saying: ‘My Lord, ask this one why he killed me.’” Shuʿbah said: I think he also said: “Allah will say: ‘For what did you kill him?’ He will reply: ‘I killed him for the rule of so-and-so.’” Jundub then said: “So beware of that.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3998},{"key":"ahmad","label":"مسند الإمام أحمد","number":16600,"n":16600}]},{"num":6803,"demo":false,"sanad":"","matn":["عن ابن عباس أنه سئل عن رجل قتل مؤمناً، ثم تاب، وآمن وعمل صالحاً ثم اهتدى قال: ويحك وانى له الهدى؟ سمعت نبيكم يقول: (( يجيء المقتول متعلقا بالقاتل يقول: يارب سل هذا فيم قتلني؟ )) والله لقد أنزلها اللّٰه على نبيكم، وما نسخها بعد إذ أنزلها. قال: ويحك، وأنى له الهدى؟"],"takhrij":"حسن: رواه ابن ماجه (٢٦٢١) والنسائي (٣٩٩٩) وأحمد (١٩٤١) والترمذي (٣٠٢٩) وحسّنه","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Mājah (2621), al-Nasā’ī (3999), Aḥmad (1941), and al-Tirmidhī (3029), who graded it sound.","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās was asked about a man who killed a believer, then repented, believed, did righteous deeds, and was rightly guided. He said: “Woe to you—how can guidance be his after that? I heard your Prophet ﷺ say: ‘The slain person will come clinging to his killer, saying: My Lord, ask this man why he killed me.’ By Allah, Allah revealed that verse to your Prophet ﷺ, and it was never abrogated after being revealed.” Then he said again: “Woe to you—how can guidance be his?”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2621},{"key":"nasai","label":"النسائي","number":3999},{"key":"tirmidhi","label":"الترمذي","number":3029},{"key":"ahmad","label":"مسند الإمام أحمد","number":1941,"n":1941}]},{"num":6804,"demo":false,"sanad":"","matn":["عن بريدة قال: قال رسول اللّٰه ﷺ : (( قتل المؤمن أعظم عند اللّٰه من زوال الدنيا ))."],"takhrij":"حسن: رواه النسائي (٣٩٩٠).","grade":"حسن","chapter_ar":"باب الترهيب من قتل المؤمن","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasā’ī (3990).","chapter_en":"Severe warning against killing a believer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Buraydah said: The Messenger of Allah ﷺ said, “The killing of a believer is greater in the sight of Allah than the passing away of the whole world.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":3990}]},{"num":6805,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مسعود، قال: قال رسول اللّٰه ﷺ: (( لا تقتل نفس ظلماً، إلا كان على ابن آدم الأول كفل من دمها، لأنه كان أول من سنّ القتل))."],"takhrij":"متفق عليه: رواه البخاري (٦٨٦٧) ومسلم (٢٧:١٦٧٧).","grade":"متفق عليه","chapter_ar":"باب أول من سن القتل وبيان إثمه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6867) and Muslim (1677, no. 27).","chapter_en":"The first one to initiate killing and the explanation of his sin","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: The Messenger of Allah ﷺ said, “No soul is killed unjustly except that a share of its blood is upon the first son of Adam, because he was the first to establish killing.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَاتْلُ عَلَيْهِمْ نَبَأَ ابْنَيْ آدَمَ بِالْحَقِّ إِذْ قَرَّبَا قُرْبَانًا فَتُقُبِّلَ مِنْ أَحَدِهِمَا وَلَمْ يُتَقَبَّلْ مِنَ الْآخَرِ قَالَ لَأَقْتُلَنَّكَ قَالَ إِنَّمَا يَتَقَبَّلُ اللَّهُ مِنَ الْمُتَّقِينَ ۝ لَئِنْ بَسَطتَ إِلَيَّ يَدَكَ لِتَقْتُلَنِي مَا أَنَا بِبَاسِطٍ يَدِيَ إِلَيْكَ لِأَقْتُلَكَ إِنِّي أَخَافُ اللَّهَ رَبَّ الْعَالَمِينَ ۝ إِنِّي أُرِيدُ أَنْ تَبُوءَ بِإِثْمِي وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحَابِ النَّارِ وَذَٰلِكَ جَزَاءُ الظَّالِمِينَ ۝ فَطَوَّعَتْ لَهُ نَفْسُهُ قَتْلَ أَخِيهِ فَقَتَلَهُ فَأَصْبَحَ مِنَ الْخَاسِرِينَ ۝ فَبَعَثَ اللَّهُ غُرَابًا يَبْحَثُ فِي الْأَرْضِ لِيُرِيَهُ كَيْفَ يُوَارِي سَوْءَةَ أَخِيهِ قَالَ يَا وَيْلَتَا أَعَجَزْتُ أَنْ أَكُونَ مِثْلَ هَٰذَا الْغُرَابِ فَأُوَارِيَ سَوْءَةَ أَخِي فَأَصْبَحَ مِنَ النَّادِمِينَ﴾ [المائدة: ٢٧-٣١]"],"en":["Allah Most High said: “And recite to them the story of the two sons of Adam in truth: when they both offered a sacrifice, and it was accepted from one of them and not accepted from the other. He said: I will surely kill you. He said: Allah only accepts from the Allah-fearing. If you stretch out your hand against me to kill me, I will not stretch out my hand against you to kill you. Indeed, I fear Allah, Lord of the worlds. I want you to return bearing my sin and your sin, so that you will be among the people of the Fire, and that is the recompense of the wrongdoers. Then his soul prompted him to kill his brother, so he killed him and became one of the losers. Then Allah sent a crow scratching in the earth to show him how to conceal the body of his brother. He said: Woe to me! Am I unable to be like this crow and hide the body of my brother? So he became one of the regretful.” [al-Māʾidah: 27–31]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6867},{"key":"muslim","label":"مسلم","number":27}]},{"num":6806,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مسعود قال: قال النبي ﷺ: (( أول ما يُقضى بين الناس في الدماء ))."],"takhrij":"متفق عليه: رواه البخاري (٦٨٦٤) ومسلم (١٦٧٨).","grade":"متفق عليه","chapter_ar":"باب أن أول ما يُقضى بين الناس يوم القيامة في الدماء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6864) and Muslim (1678).","chapter_en":"The first matter judged among people on the Day of Resurrection will be bloodshed","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: The Prophet ﷺ said, “The first matter to be judged among people will be bloodshed.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6864},{"key":"muslim","label":"مسلم","number":1678}]},{"num":6807,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن مسعود قال: قال رجل: يا رسول اللّٰه ﷺ، أي الذنب أكبر عند اللّٰه؟ قال: (( أن تدعو لله نداً وهو خلقك )). قال: ثم أي؟ قال: (( ثم أن تقتل ولدك خشية أن يطعم معك )). قال: ثم أي؟ قال: (( ثم أن تزاني حليلة جارك )). فأنزل اللّٰه تصديقها: ﴿وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَٰهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا﴾ [الفرقان: ٦٨]."],"takhrij":"متفق عليه: رواه البخاري (٦٨٦١) ومسلم (١٤٢:٨٦).","grade":"متفق عليه","chapter_ar":"باب تحريم قتل الأولاد خوفا من الفقر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6861) and Muslim (86, no. 142).","chapter_en":"The prohibition of killing children out of fear of poverty","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported: A man asked, “O Messenger of Allah ﷺ, which sin is greatest in the sight of Allah?” He said, “That you set up a rival to Allah while He created you.” He said, “Then what?” He said, “Then that you kill your child out of fear that he will eat with you.” He said, “Then what?” He said, “Then that you commit adultery with your neighbor’s wife.” Then Allah revealed, confirming this: “Those who do not call upon another god with Allah, nor kill the soul which Allah has forbidden except with right, nor commit adultery…” [al-Furqān: 68]"]},"intro":{"ar":["قال الله تعالى: ﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ مِنْ إِمْلَاقٍ نَحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ﴾ [الأنعام: ١٥١]","وقال تعالى: ﴿قَدْ خَسِرَ الَّذِينَ قَتَلُوا أَوْلَادَهُمْ سَفَهًا بِغَيْرِ عِلْمٍ﴾ [الأنعام: ١٤٠]"],"en":["Allah Most High said: “Do not kill your children because of poverty; We provide for you and for them.” [Sūrat al-Anʿām: 151]","And He said: “Lost indeed are those who killed their children foolishly without knowledge.” [Sūrat al-Anʿām: 140]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6861},{"key":"muslim","label":"مسلم","number":142}]},{"num":6808,"demo":false,"sanad":"","matn":["عن المغيرة بن شعبة قال: قال النبي ﷺ: (( إن اللّٰه حرم عليكم عقوق الأمهات، ووأد البنات، ومنعاً وهات. وكره لكم قيل وقال، وكثرة السؤال، وإضاعة المال ))."],"takhrij":"متفق عليه: رواه البخاري (٢٤٠٨) ومسلم (١٢:٥٩٣).","grade":"متفق عليه","chapter_ar":"باب تحريم وأد البنات وأنه من أفعال الجاهلية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (2408) and Muslim (593, no. 12).","chapter_en":"The prohibition of burying daughters alive, and that it was among the practices of the pre-Islamic age","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["al-Mughīrah ibn Shuʿbah said: The Prophet ﷺ said, “Allah has forbidden for you disobedience to mothers, burying daughters alive, and withholding what should be given while demanding what is not yours. And He has disliked for you idle talk, excessive questioning, and wasting wealth.”"]},"buhuth":{"ar":["قوله: (( وأد البنات )) هو دفنهن في حياتهن، فيمتن تحت التراب."],"en":["The phrase “burying daughters alive” means burying them while they are still alive so that they die beneath the earth."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَإِذَا بُشِّرَ أَحَدُهُمْ بِالْأُنْثَىٰ ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ ۝ يَتَوَارَىٰ مِنَ الْقَوْمِ مِنْ سُوءِ مَا بُشِّرَ بِهِ أَيُمْسِكُهُ عَلَىٰ هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ أَلَا سَاءَ مَا يَحْكُمُونَ﴾ [النحل: ٥٨-٥٩]","وقال تعالى: ﴿وَإِذَا الْمَوْءُودَةُ سُئِلَتْ ۝ بِأَيِّ ذَنْبٍ قُتِلَتْ﴾ [التكوير: ٨-٩]"],"en":["Allah Most High said: “When one of them is given news of a female child, his face darkens and he is filled with grief. He hides himself from the people because of the evil of what he was given news of: should he keep her in humiliation or bury her in the dust? Evil indeed is what they judge.” [al-Naḥl: 58–59]","And He said: “And when the girl buried alive is asked: for what sin was she killed?” [al-Takwīr: 8–9]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2408},{"key":"muslim","label":"مسلم","number":12}]},{"num":6809,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( اجتنبوا السبع الموبقات )). قالوا: يا رسول الله ﷺ، وما هن؟ قال: (( الشرك بالله، والسحر، وقتل النفس التي حرم اللّٰه إلا بالحق، وأكل الربا، وأكل مال اليتيم، والتولي يوم الزحف، وقذف المحصنات المؤمنات الغافلات ))."],"takhrij":"متفق عليه: رواه البخاري (٦٨٥٧)، ومسلم (٨٩).","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6857) and Muslim (89).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said, “Avoid the seven destructive sins.” They said, “O Messenger of Allah ﷺ, what are they?” He said, “Associating partners with Allah, sorcery, killing the soul which Allah has forbidden except with right, consuming usury, consuming the wealth of an orphan, fleeing on the day of battle, and slandering chaste, believing, unsuspecting women.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6857},{"key":"muslim","label":"مسلم","number":89}]},{"num":6810,"demo":false,"sanad":"","matn":["عن أنس بن مالك، عن النبي ﷺ قال: (( أكبر الكبائر الإشراك بالله، وقتل النفس، وعقوق الوالدين، وقول الزور - أو قال: وشهادة الزور ))."],"takhrij":"متفق عليه: رواه البخاري (٦٨٧١) ومسلم (٨٨).","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6871) and Muslim (88).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ said, “The greatest of the major sins are associating partners with Allah, killing a soul, disobeying one’s parents, and false speech,” or he said, “false testimony.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6871},{"key":"muslim","label":"مسلم","number":88}]},{"num":6811,"demo":false,"sanad":"","matn":["عن ابن عباس، أن النبي ﷺ قال: (( أبغض الناس إلى اللّٰه ثلاثة: ملحد في الحرم، ومبتغ في الإسلام سنة الجاهلية، ومطَّلِب دم امرئ بغير حق ليهريق دمه ))."],"takhrij":"صحيح: رواه البخاري (٦٨٨٢).","grade":"صحيح","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (6882).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Prophet ﷺ said, “The most hateful of people to Allah are three: one who commits deviation in the Sacred Precinct, one who seeks to revive a practice of the pre-Islamic age in Islam, and one who seeks the blood of a person without right in order to shed it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6882}]},{"num":6812,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود، عن النبي ﷺ قال: (( سباب المسلم فسوق، وقتاله كفر ))."],"takhrij":"متفق عليه: رواه البخاري (٤٨) ومسلم (٦٤).","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (48) and Muslim (64).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported that the Prophet ﷺ said, “Insulting a Muslim is sinful rebellion, and fighting him is disbelief.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":48},{"key":"muslim","label":"مسلم","number":64}]},{"num":6813,"demo":false,"sanad":"","matn":["عن جرير، أن النبي ﷺ قال له في حجة الوداع: (( استنصت الناس )) فقال: (( لا ترجعوا بعدي كفارًا، يضرب بعضكم رقاب بعض ))."],"takhrij":"متفق عليه: رواه البخاري (١٢١) ومسلم (٦٥).","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (121) and Muslim (65).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Jarīr reported that the Prophet ﷺ said to him during the Farewell Pilgrimage, “Tell the people to listen,” then said: “Do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":121},{"key":"muslim","label":"مسلم","number":65}]},{"num":6814,"demo":false,"sanad":"","matn":["عن ابن عمر، عن النبي ﷺ قال: (( ويلكم - أو ويحكم، قال شعبة: شك هو - لا ترجعوا بعدي كفارًا، يضرب بعضكم رقاب بعض ))."],"takhrij":"متفق عليه: رواه البخاري (٦١٦٦) ومسلم (٦٦).","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (6166) and Muslim (66).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar reported that the Prophet ﷺ said, “Woe to you,” or “May Allah have mercy on you”—Shuʿbah said he was uncertain which one—“do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6166},{"key":"muslim","label":"مسلم","number":66}]},{"num":6815,"demo":false,"sanad":"","matn":["عن أبي بكرة، قال: خطبنا النبي ﷺ يوم النحر، فذكر الحديث، وفي آخره قال: (( اللهم اشهد، فليبلغ الشاهد الغائب، فرب مبلغ أوعى من سامع، فلا ترجعوا بعدي كفارًا، يضرب بعضكم رقاب بعض ))."],"takhrij":"متفق عليه: رواه البخاري (١٧٤١) ومسلم (٣١:١٦٧٩).","grade":"متفق عليه","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1741) and Muslim (1679, no. 31).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abū Bakrah said: The Prophet ﷺ gave us a sermon on the Day of Sacrifice, and at the end of it he said, “O Allah, bear witness. Let the one present convey to the one absent, for perhaps the one informed may understand better than the one who heard directly. Do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1741},{"key":"muslim","label":"مسلم","number":31}]},{"num":6816,"demo":false,"sanad":"","matn":["عن ابن عباس، أن رسول اللّٰه ﷺ خطب الناس يوم النحر، فذكر الحديث، وفي آخره قال ابن عباس رضي اللّٰه عنهما: فو الذي نفسي بيده، إنها لوصيته إلى أمته: (( فليبلغ الشاهد الغائب، لا ترجعوا بعدي كفارًا، يضرب بعضكم رقاب بعض ))."],"takhrij":"صحيح: رواه البخاري (١٧٣٩).","grade":"صحيح","chapter_ar":"باب قتل النفس بغير حق من أكبر الكبائر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhārī (1739).","chapter_en":"Killing a soul without right is among the gravest major sins","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ addressed the people on the Day of Sacrifice, and at the end of the report Ibn ʿAbbās said: By the One in whose hand is my soul, this was indeed his final instruction to his community: “Let the one present convey to the one absent. Do not revert after me to disbelief, striking the necks of one another.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1739}]},{"num":6817,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لما توفي رسول اللّٰه ﷺ وكان أبو بكر رضي اللّٰه عنه، وكفر من كفر من العرب، فقال عمر رضي اللّٰه عنه: كيف تقاتل الناس؟! وقد قال رسول اللّٰه ﷺ: (( أُمرت أن أقاتل الناس حتى يقولوا: لا إله إلا الله، فمن قالها فقد عصم مني ماله ونفسه إلا بحقه، وحسابه على اللّٰه ))."],"takhrij":"متفق عليه: رواه البخاري (١٣٩٩) ومسلم (٢٠)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhārī (1399) and Muslim (20), with the wording here from al-Bukhārī.","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah said: When the Messenger of Allah ﷺ passed away and Abū Bakr became leader, some of the Arabs fell into disbelief. ʿUmar said, “How can you fight the people when the Messenger of Allah ﷺ said: ‘I have been commanded to fight the people until they say: There is no god but Allah. Whoever says it has protected from me his wealth and his life except by its due right, and his reckoning is with Allah’?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":1399},{"key":"muslim","label":"مسلم","number":20}]},{"num":6818,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( أُمرت أن أقاتل الناس حتى يقولوا: لا إله إلا الله، فمن قال: لا إله إلا اللّٰه فقد عصم مني نفسه وماله إلا بحقه، وحسابه على اللّٰه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٩٤٦) ومسلم (٢١).","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2946) and Muslim (21).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “I have been commanded to fight the people until they say: There is no god but Allah. Whoever says: There is no god but Allah has protected his life and wealth from me, except by its due right, and his reckoning is with Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":2946},{"key":"muslim","label":"مسلم","number":21}]},{"num":6819,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمر، أن رسول اللّٰه ﷺ قال: (( أُمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا اللّٰه وأن محمدًا رسول الله ﷺ، ويقيموا الصلاة، ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام، وحسابهم على اللّٰه ))."],"takhrij":"متفق عليه: رواه البخاري (٢٥) ومسلم (٢٢).","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (25) and Muslim (22).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abdullah ibn Umar reported that the Messenger of Allah ﷺ said: “I have been commanded to fight the people until they testify that there is no god but Allah and that Muhammad is the Messenger of Allah ﷺ, establish the prayer, and give the alms. If they do that, they have protected their blood and wealth from me except by the right of Islam, and their reckoning is with Allah.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":25},{"key":"muslim","label":"مسلم","number":22}]},{"num":6820,"demo":false,"sanad":"","matn":["عن أبي مالك الأشجعي، عن أبيه قال: سمعت رسول اللّٰه ﷺ يقول: (( من قال لا إله إلا الله، وكفر بما يُعبد من دون الله، حَرُم ماله ودمه، وحسابه على اللّٰه ))."],"takhrij":"صحيح: رواه مسلم (٢٣).","grade":"صحيح","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (23).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abu Malik al-Ashjaʿi narrated from his father, who said: I heard the Messenger of Allah ﷺ say: “Whoever says: There is no god but Allah, and rejects whatever is worshipped besides Allah, his wealth and blood become inviolable, and his reckoning is with Allah.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":23}]},{"num":6821,"demo":false,"sanad":"","matn":["عن المقداد بن عمرو الكندي - وكان حليفاً لبني زهرة، وكان ممن شهد بدراً مع رسول اللّٰه ﷺ - أنه قال لرسول اللّٰه ﷺ: أرأيت إن لقيت رجلاً من الكفار فاقتتلنا، فضرب إحدى يدي بالسيف فقطعها، ثم لاذ مني بشجرة فقال: أسلمت لله، أأقتله يا رسول اللّٰه ﷺ بعد أن قالها؟ فقال رسول اللّٰه ﷺ: (( لا تقتله )). فقال: يا رسول الله ﷺ، إنه قطع إحدى يدي، ثم قال ذلك بعد ما قطعها؟! فقال رسول اللّٰه ﷺ: (( لا تقتله، فإن قتلته فإنه بمنزلتك قبل أن تقتله، وإنك بمنزلته قبل أن يقول كلمته التي قال ))."],"takhrij":"متفق عليه: رواه البخاري (٤٠١٩، ٦٨٦٥) ومسلم (٩٥).","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4019, 6865) and Muslim (95).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Al-Miqdad ibn ʿAmr al-Kindi — who was an ally of Banu Zuhrah and one of those who witnessed Badr with the Messenger of Allah ﷺ — said to the Messenger of Allah ﷺ: “What do you think if I meet a man from the disbelievers and we fight, and he strikes one of my hands with the sword and cuts it off, then takes shelter from me behind a tree and says, ‘I have submitted myself to Allah’? May I kill him after he says that, O Messenger of Allah ﷺ?” The Messenger of Allah ﷺ said: “Do not kill him.” He said: “O Messenger of Allah ﷺ, he cut off one of my hands, then only said that after cutting it off!” The Messenger of Allah ﷺ said: “Do not kill him. If you kill him, then he will be in your position before you killed him, and you will be in his position before he said the words that he said.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4019},{"key":"muslim","label":"مسلم","number":95}]},{"num":6822,"demo":false,"sanad":"","matn":["عن أسامة بن زيد يقول: بعثنا رسول اللّٰه ﷺ إلى الحرقة، فصبحنا القوم فهزمناهم، ولحقت أنا ورجل من الأنصار رجلاً منهم فلما غشيناه قال: لا إله إلا الله. فكف عنه الأنصاري، فطعنته برمحي حتى قتلته، فلما قدمنا بلغ ذلك النبي ﷺ فقال: (( يا أسامة، أقتلته بعد ما قال: لا إله إلا اللّٰه )) قلت: كان متعوذاً! فما زال يكررها حتى تمنيت أني لم أكن أسلمت قبل ذلك اليوم."],"takhrij":"متفق عليه: رواه البخاري (٤٢٦٩) ومسلم (١٥٩:٩٦).","grade":"متفق عليه","chapter_ar":"باب تغليظ تحريم قتل الكافر إذا أسلم ونطق بالشهادتين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (4269) and Muslim (96, no. 159).","chapter_en":"The severe prohibition of killing a disbeliever once he accepts Islam and pronounces the two testimonies","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Usamah ibn Zayd said: The Messenger sent us to al-Huraqah. We attacked the people in the morning and defeated them. I and a man from the Ansar caught up with one of them, and when we closed in on him he said: There is no god but Allah. The Ansari held back from him, but I struck him with my spear and killed him. When we returned, news of that reached the Prophet ﷺ, and he said: “O Usamah, did you kill him after he said: There is no god but Allah?” I said: “He only said it seeking protection.” He kept repeating it until I wished I had not accepted Islam before that day."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4269},{"key":"muslim","label":"مسلم","number":159}]},{"num":6823,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو بن العاص، عن النبي ﷺ قال: (( من قتل نفساً معاهداً لم يرح رائحة الجنة، وإن ريحها ليوجد من مسيرة أربعين عاماً ))."],"takhrij":"صحيح: رواه البخاري ( ٦٩١٤).","grade":"صحيح","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6914).","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abdullah ibn Amr ibn al-As reported that the Prophet ﷺ said: “Whoever kills a person under covenant will not smell the fragrance of Paradise, though its fragrance can be found from a distance of forty years.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6914}]},{"num":6824,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( ألا من قتل نفساً معاهدة له ذمة الله، وذمة رسوله فقد أخفر بذمة الله، فلا يرح رائحة الجنة، وإن ريحها ليوجد من مسيرة سبعين خريفاً ))."],"takhrij":"حسن: رواه الترمذي (١٤٠٣) وابن ماجه (٢٦٨٧). قال الترمذي: “هذا حديث حسن صحيح”.","grade":"حسن","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1403) and Ibn Majah (2687). Al-Tirmidhi said: “This is a sound authentic hadith.”","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Indeed, whoever kills a person under covenant who is under the protection of Allah and the protection of His Messenger has violated the protection of Allah. He will not smell the fragrance of Paradise, though its fragrance can be found from a distance of seventy years.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1403},{"key":"ibnmajah","label":"ابن ماجه","number":2687}]},{"num":6825,"demo":false,"sanad":"","matn":["عن أبي بكرة قال: قال رسول اللّٰه ﷺ: (( من قتل معاهداً في غير كنهه حرّم اللّٰه عليه الجنة ))."],"takhrij":"حسن: رواه أبو داود (٢٧٦٠) والنسائي (٤٧٤٧) وأحمد (٢٠٣٧٧) وصححه الحاكم (١٤٢/٢).","grade":"حسن","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2760), al-Nasa’i (4747), and Ahmad (20377), and authenticated by al-Hakim (2/142).","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["Abu Bakrah said: The Messenger of Allah ﷺ said: “Whoever kills a person under covenant without right, Allah has forbidden Paradise for him.”"]},"buhuth":{"ar":["وقوله: (( في غير كنهه )) أي في غير حقه."],"en":["The phrase “without right” means: without any lawful justification."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2760},{"key":"nasai","label":"النسائي","number":4747},{"key":"صححہ_الحاکم","label":"صححه الحاكم","number":142},{"key":"ahmad","label":"مسند الإمام أحمد","number":20377,"n":20377},{"key":"hakim","label":"المستدرك على الصحيحين","number":2631,"n":2617}]},{"num":6826,"demo":false,"sanad":"","matn":["عن رجل، عن النبي ﷺ أنه قال: (( سيكون قوم لهم عهد، فمن قتل رجلا منهم لم يرح رائحة الجنة، وإن ريحها ليوجد من مسيرة سبعين عاما))."],"takhrij":"صحيح: رواه أحمد ( ١٦٥٩٠).","grade":"صحيح","chapter_ar":"باب إثم من قتل ذمياً أو معاهدا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (16590).","chapter_en":"The sin of killing a protected non-Muslim or one under covenant","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["A man narrated from the Prophet ﷺ that he said: “There will be a people who have a covenant. Whoever kills a man from among them will not smell the fragrance of Paradise, though its fragrance can be found from a distance of seventy years.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":16590,"n":16590}]},{"num":6827,"demo":false,"sanad":"","matn":["عن رفاعة بن شداد الفتياني قال: لولا كلمة سمعتُها من عمرو بن الحمِق الخزاعي لمشيت فيما بين رأس المختار وجسده، سمعته يقول: (( من أمن رجلاً على دمه، فقتله فإنه يحمل لواء غدر يوم القيامة ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٦٨٨) وأحمد (٢١٩٤٦) وأبو داود الطيالسي (١٢٨٥) وابن حبان (٥٩٨٢).","grade":"صحيح","chapter_ar":"باب الرجل يأمن الرجل على دمه ثم يقتله","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2688), Ahmad (21946), Abu Dawud al-Tayalisi (1285), and Ibn Hibban (5982).","chapter_en":"A man grants another safety regarding his life and then kills him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Rifaʿah ibn Shaddad al-Fityani said: Were it not for a statement I heard from ʿAmr ibn al-Hamiq al-Khuzaʿi, I would have walked between the head of al-Mukhtar and his body. I heard him say: “Whoever grants a man safety regarding his life and then kills him will carry the banner of treachery on the Day of Resurrection.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2688},{"key":"ابو_داود_الطیالسی","label":"أبو داود الطيالسي","number":1285},{"key":"ibnhibban","label":"ابن حبان","number":5982},{"key":"ahmad","label":"مسند الإمام أحمد","number":21946,"n":21946}]},{"num":6828,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: شهدنا مع رسول اللّٰه ﷺ خيبر، فقال لرجل ممن يدعي الإسلام: (( هذا من أهل النار )). فلما حضر القتال قاتل الرجل قتالاً شديداً فأصابته جراحة، فقيل: يا رسول الله ﷺ! الذي قلت إنه من أهل النار، فإنه قد قاتل اليوم قتالاً شديداً وقد مات؟ فقال النبي ﷺ: (( إلى النار )). قال: فكاد بعض الناس أن يرتاب، فبينما هم على ذلك إذ قيل: إنه لم يمت، ولكن به جراحاً شديداً، فلما كان من الليل لم يصبر على الجراح فقتل نفسه، فأُخبر النبي ﷺ بذلك فقال: (( اللّٰه أكبر، أشهد أني عبد اللّٰه ورسوله )). ثم أمر بلالاً فنادى بالناس: (( إنه لا يدخل الجنة إلا نفس مسلمة، وإن اللّٰه ليؤيد هذا الدين بالرجل الفاجر ))."],"takhrij":"متفق عليه: رواه البخاري (٣٠٦٢) ومسلم (١١١).","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3062) and Muslim (111).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: We were present with the Messenger of Allah ﷺ at Khaybar, and he said about a man who claimed to be Muslim: “This man is among the people of the Fire.” When fighting began, the man fought fiercely and was wounded. It was said: “O Messenger of Allah ﷺ, the one you said was among the people of the Fire fought fiercely today and has died.” The Prophet ﷺ said: “To the Fire.” Some people were almost doubtful because of that. While they were in that state, it was said: “He has not died, but he has severe wounds.” When night came, he could not bear the pain of his wounds and killed himself. The Prophet ﷺ was informed of that and said: “Allah is greatest. I bear witness that I am the servant of Allah and His Messenger.” Then he ordered Bilal to call out to the people: “None enters Paradise except a Muslim soul, and Allah may support this religion through a wicked man.”"]},"intro":{"ar":["قال اللّٰه تعالى: (وَلَا تَقْتُلُواْ أَنْفُسَكُمْ نَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا ) [سورة النساء: ٢٩]","وقال تعالى: (وَلَا تُلْقُواْ بِأَيْدِيكُم إلى التَّهْلُكَةِ) [البقرة: ١٩٥]"],"en":["Allah Most High said: “Do not kill yourselves. Indeed, Allah is ever Merciful to you.” [Surat al-Nisa’: 29]","And He said: “Do not throw yourselves into destruction with your own hands.” [al-Baqarah: 195]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3062},{"key":"muslim","label":"مسلم","number":111}]},{"num":6829,"demo":false,"sanad":"","matn":["عن ثابت بن الضحاك، عن النبي ﷺ قال: (( من حلف بملة غير الإسلام كاذباً فهو كما قال، ومن قتل نفسه بشيء عذّب به في نار جهنم، ولعن المؤمن كقتله، ومن رمى مؤمنا بكفر فهو كقتله )."],"takhrij":"متفق عليه: رواه البخاري (٦١٠٥) ومسلم (١١٠)، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6105) and Muslim (110), with the wording here from al-Bukhari.","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Thabit ibn al-Dahhak reported that the Prophet ﷺ said: “Whoever falsely swears by a religion other than Islam is as he said. Whoever kills himself with something will be punished with it in the Fire of Hell. Cursing a believer is like killing him, and accusing a believer of disbelief is like killing him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6105},{"key":"muslim","label":"مسلم","number":110}]},{"num":6830,"demo":false,"sanad":"","matn":["عن الحسن قال: حدثنا جندب بن عبد اللّٰه في هذا المسجد، وما نسينا منذ حدّثنا، وما نخشى أن يكون جندب كذب على النبي ﷺ. قال: قال رسول اللّٰه ﷺ: (( كان فيمن كان قبلكم رجل به جرح فجزع، فأخذ سكيناً فحزّ بها يده، فما رقأ الدم حتى مات. قال اللّٰه تعالى: بادرني عبدي بنفسه، حرمت عليه الجنة )).","وفي رواية: خرج برجل خُرّاج - أي القرحة."],"takhrij":"متفق عليه: رواه البخاري (٣٤٦٣) ومسلم (١١٣: ١٨١). وقوله: (( فما رقأ الدم )) أي: لم ينقطع.","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3463) and Muslim (113, no. 181).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Al-Hasan said: Jundub ibn Abdullah narrated to us in this mosque, and we have not forgotten since he narrated to us, nor do we fear that Jundub lied against the Prophet ﷺ. He said: The Messenger of Allah ﷺ said: “Among those before you there was a man who had a wound. He became distressed, so he took a knife and cut his hand with it. The blood did not stop until he died. Allah Most High said: My servant hastened his own end before Me, so I have forbidden Paradise for him.”","In another narration: it was because of a swelling or ulcer."]},"buhuth":{"en":["The phrase “the blood did not stop” means: it did not cease flowing."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3463},{"key":"muslim","label":"مسلم","number":113}]},{"num":6831,"demo":false,"sanad":"","matn":["عن أبي هريرة، عن النبي ﷺ قال: (( من تردّى من جبل فقتل نفسه فهو في نار جهنم يتردّى فيه خالداً مخلداً فيها أبداً، ومن تحسّى سماً فقتل نفسه فسمّه في يده يتحسّاه في نار جهنم خالداً مخلداً فيها أبداً، ومن قتل نفسه بحديدة فحديدته في يده يجأ بها في بطنه في نار جهنم خالداً مخلداً فيها أبداً ))."],"takhrij":"متفق عليه: رواه البخاري (٥٧٧٨) ومسلم (١٠٩).","grade":"متفق عليه","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (5778) and Muslim (109).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Whoever throws himself from a mountain and kills himself will be falling in the Fire of Hell forever, abiding therein eternally. Whoever drinks poison and kills himself, his poison will be in his hand and he will be drinking it in the Fire of Hell forever, abiding therein eternally. Whoever kills himself with an iron weapon, his weapon will be in his hand and he will be stabbing himself in the belly with it in the Fire of Hell forever, abiding therein eternally.”"]},"buhuth":{"ar":["وأما معنى قوله: (( فهو في نار جهنم خالداً مخلداً فيها أبداً )) فقال النووي في شرح مسلم فيها أقوال:","أحدها: أنه محمول على من فعل ذلك مستحلا مع علمه بالتحريم. فهذا كافر. وهذه عقوبته.","والثاني: أن المراد بالخلود طول المدة، والإقامة المتطاولة لا حقيقة الدوام. كما يقال: خلّد اللّٰه ملك السلطان.","والثالث: أن هذا جزاءه، ولكن تكرم اللّٰه سبحانه وتعالى فأخبر أنه لا يخلد في النار من مات مسلماً انتهى.","والدليل على أن قاتل النفس لا يكفر الحديث الآتي:"],"en":["As for the meaning of the phrase “forever, abiding therein eternally”, al-Nawawi said in his commentary on Muslim that there are several interpretations:","The first is that it applies to one who did this while declaring it lawful despite knowing it is forbidden. Such a person is a disbeliever, and this is his punishment.","The second is that permanence here means a very long stay, not actual endlessness, just as people say: “May Allah make the ruler’s kingdom everlasting.”","The third is that this is the punishment he deserves, but Allah, out of grace, has informed us that one who dies as a Muslim will not remain forever in the Fire. End quote.","The proof that a person who kills himself does not become a disbeliever is the hadith that follows."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5778},{"key":"muslim","label":"مسلم","number":109}]},{"num":6832,"demo":false,"sanad":"","matn":["عن جابر، أن الطفيل بن عمرو الدوسي أتى النبي ﷺ فقال: يا رسول الله ﷺ! هل لك في حصن حصين ومنعة؟ (قال: حصن كان لدوس في الجاهلية) فأبى ذلك النبي ﷺ للذي ذخر اللّٰه للأنصار. فلما هاجر النبي ﷺ إلى المدينة هاجر إليه الطفيل بن عمرو، وهاجر معه رجل من قومه، فاجتووا المدينة، فمرض فجزع، فأخذ مشاقص له، فقطع بها براجمه، فشخبت يداه حتى مات. فرآه الطفيل بن عمرو في منامه، فرآه وهيئته حسنة، ورآه مغطياً يديه، فقال له: ما صنع بك ربك؟ فقال: غفر لي بهجرتي إلى نبيه ﷺ. فقال: ما لي أراك مغطياً يديك؟ قال: قيل لي: لن نصلح منك ما أفسدت. فقصها الطفيل على رسول اللّٰه ﷺ فقال رسول اللّٰه ﷺ: (( اللهم! وليديه فاغفر ))."],"takhrij":"صحيح: رواه مسلم (١١٦). وقوله: (( فاجتووا المدينة )) معناه كرهوا المقام بها لضجر ونوع من السقم.","grade":"صحيح","chapter_ar":"باب غلظ تحريم قتل الإنسان نفسه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (116).","chapter_en":"The severe prohibition of a person killing himself","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Jabir reported that al-Tufayl ibn Amr al-Dawsi came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, would you like a fortified stronghold and protection?” It was a fort that belonged to Daws in the pre-Islamic period. The Prophet ﷺ declined that because of what Allah had reserved for the Ansar. When the Prophet ﷺ migrated to Madinah, al-Tufayl ibn Amr also migrated there, and a man from his people migrated with him. They found Madinah difficult to live in. The man became ill and grew distressed, so he took some arrowheads and cut his finger joints with them. His hands bled profusely until he died. Al-Tufayl ibn Amr later saw him in a dream. He saw him in a good state, but with his hands covered. He said to him: “What did your Lord do with you?” He replied: “He forgave me because of my migration to His Prophet ﷺ.” He said: “Then why do I see your hands covered?” He replied: “I was told: We will not repair from you what you yourself ruined.” Al-Tufayl told this to the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ said: “O Allah, forgive even his hands.”"]},"buhuth":{"ar":["وقوله: (( مشاقص )) جمع مشقص، وهو سهم فيه نصل عريض. وقوله: (( براجم )) جمع برجمة، وهي مفاصل الإصبع. وقوله: (( شخبت يداه )) أي سال دمهما بقوة.","وفيه أن من قتل نفسه ومات من غير توبة فليس بكافر، ولا يقطع له بالنار، بل هو في حكم المشيئة."],"en":["The phrase “they found Madinah difficult to live in” means they disliked staying there because of discomfort and a kind of illness.","Mashaqis is the plural of mishqas, an arrow with a broad blade.","Barajim is the plural of barjumah, meaning the finger joints.","His hands bled profusely means that the blood flowed strongly.","This hadith shows that whoever kills himself and dies without repentance is not a disbeliever, and it cannot be decisively said that he is in the Fire forever. Rather, his matter is subject to the divine will."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":116}]},{"num":6833,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري قال: لا أحدثكم إلا ما سمعت من رسول اللّٰه ﷺ، سمعته أذناي، ووعاه قلبي: (( إن عبداً قتل تسعة وتسعين نفساً، ثم عرضتْ له التوبة، فسأل عن أعلم أهل الأرض، فدُلّ على رجل، فأتاه فقال: إني قتلت تسعة وتسعين نفساً، فهل لي من توبة؟ قال: بعد قتل تسعة وتسعين نفساً؟ قال: فانتضى سيفَه فقتله به، فأكمل به مئة، ثم عرضتْ له التوبة، فسأل عن أعلم أهل الأرض، فدُلَ على رجل، فأتاه فقال: إني قتلت مئة نفس، فهل لي من توبة؟ فقال: ومن يحول بينك وبين التوبة، اخرج من القرية الخبيثة التي أنت فيها إلى القرية الصالحة قرية كذا وكذا، فاعبد ربك فيها، قال: فخرج إلى القرية الصالحة، فعرض له أجله في الطريق قال: فاختصمت فيه ملائكة الرحمة وملائكة العذاب قال: فقال إبليس: أنا أولى به، إنه لم يعصني ساعة قط. قال: فقالت ملائكة الرحمة: إنه خرج تائباً ))","قال همام: فحدثني حميد الطويل، عن بكر بن عبد اللّٰه المزني، عن أبي رافع قال: (( فبعث اللّٰه عز وجل له ملكاً فاختصموا إليه )) ثم رجع إلى حديث قتادة، قال: فقال: (( انظروا أي القريتين كان أقرب إليه، فألحقوه بأهلها )) قال قتادة: فحدثنا الحسن قال: (( لما عرف الموت احتفز بنفسه، فقرب اللّٰه عز وجل منه القرية الصالحة، وباعد منه القرية الخبيثة، فألحقوه بأهل القرية الصالحة ))"],"takhrij":"صحيح: رواه البخاري (٣٤٧٠) ومسلم (٢٧٦٦) ورواه أحمد (١١١٥٤) ، واللفظ له لأنه أطول.","grade":"صحيح","chapter_ar":"باب توبة القاتل","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (3470) and Muslim (2766). It was also narrated by Ahmad (11154), and this is his wording because it is longer.","chapter_en":"The repentance of a killer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abu Saʿid al-Khudri said: I will only tell you what I heard from the Messenger of Allah ﷺ, which my ears heard and my heart retained: “A servant killed ninety-nine people. Then repentance came to his mind, so he asked about the most knowledgeable person on earth. He was directed to a man, and he came to him and said: I have killed ninety-nine people; do I have any chance of repentance? He said: After killing ninety-nine people? Then the man drew his sword and killed him, completing a hundred. Then repentance again came to his mind, so he asked about the most knowledgeable person on earth. He was directed to a man, and he came to him and said: I have killed one hundred people; do I have any chance of repentance? He said: And who can stand between you and repentance? Leave the evil town you are in and go to the righteous town, such-and-such a place, and worship your Lord there. So he set out for the righteous town, but death came to him on the way. Then the angels of mercy and the angels of punishment disputed over him. Iblis said: I have more right to him, for he never disobeyed me for even an hour. The angels of mercy said: He went out in repentance.”","Hammam said: Humayd al-Tawil narrated to me from Bakr ibn Abdullah al-Muzani, from Abu Rafiʿ, who said: “So Allah sent an angel to judge between them.” Then he returned to the narration of Qatadah, who said: “He said: Look to which of the two towns he was closer, and attach him to its people.” Qatadah said: Al-Hasan narrated to us, saying: “When he realized death was near, he drew himself forward with effort, so Allah brought the righteous town nearer to him and made the evil town farther away from him, and they attached him to the people of the righteous town.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3470},{"key":"muslim","label":"مسلم","number":2766},{"key":"ahmad","label":"مسند الإمام أحمد","number":11154,"n":11154}]},{"num":6834,"demo":false,"sanad":"","matn":["عن سلمة قال: خرجنا مع النبي ﷺ إلى خيبر، فقال رجل منهم: أسمعنا يا عامر من هنياتك، فحدا بهم، فقال النبي ﷺ: (( من السائق؟ )) قالوا: عامر، فقال: (( رحمه اللّٰه )). فقالوا: يا رسول اللّٰه ﷺ، هلا أمتعتنا به؟ فأصيب صبيحة ليلته، فقال القوم: حبط عمله، قتل نفسه. فلما رجعت","وهم يتحدثون أن عامراً حبط عمله - فجئت إلى النبي ﷺ فقلت: يا نبي اللّٰه فداك أبي وأمي، زعموا أن عامراً حبط عمله، فقال: كذب من قالها، إن له لأجرين اثنين، إنه لجاهدٌ مجاهدٌ، وأي قتل يزيده عليه."],"takhrij":"متفق عليه: رواه البخاري (٦٨٩١) ومسلم (١٨٠٢). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب من قتل نفسه خطأ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6891) and Muslim (1802), with the wording here from al-Bukhari.","chapter_en":"One who kills himself by mistake","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Salamah said: We went out with the Prophet ﷺ to Khaybar. One of the people said: “Let us hear some of your verses, O Amir.” So he chanted for them. The Prophet ﷺ said: “Who is the one driving the camels?” They said: “Amir.” He said: “May Allah have mercy on him.” They said: “O Messenger of Allah ﷺ, if only you had allowed us to benefit from him longer.” He was then struck down the next morning. The people said: “His deeds are lost; he killed himself.” When I returned — and the people were talking that Amir’s deeds had been lost — I came to the Prophet ﷺ and said: “O Prophet of Allah, may my father and mother be sacrificed for you, they claim that Amir’s deeds are lost.” He said: “Whoever said that has lied. He will have a double reward. He was a striving fighter in the path of Allah. And what death could be greater than this for him?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6891},{"key":"muslim","label":"مسلم","number":1802}]},{"num":6835,"demo":false,"sanad":"","matn":["عن أبي شريح قال: قال رسول اللّٰه ﷺ: (( إن أعتى الناس على اللّٰه من قتل غير قاتله، ومن طلب بدم الجاهلية من أهل الإسلام، ومن بصّر عينيه في المنام ما لم تَبصر ))"],"takhrij":"حسن: رواه أحمد (١٦٣٧٨) والطبراني في الكبير (١٩١/٢٢) وابن أبي عاصم في الديات (٢٢٥).","grade":"حسن","chapter_ar":"باب من قتل غير قاتله","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (16378), al-Tabarani in al-Kabir (22/191), and Ibn Abi Asim in al-Diyat (225).","chapter_en":"One who kills someone other than his killer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abu Shurayh said: The Messenger of Allah ﷺ said: “Among the most defiant people against Allah is one who kills someone other than the one who killed him, one who seeks vengeance for bloodshed from the pre-Islamic age among the people of Islam, and one who claims that his eyes saw in a dream what they did not see.”"]}},"tuhfa":{},"refs":[{"key":"الطبرانی/الکبیر","label":"الطبراني في الكبير","number":191},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":225},{"key":"ahmad","label":"مسند الإمام أحمد","number":16378,"n":16378}]},{"num":6836,"demo":false,"sanad":"","matn":["عن عائشة قالت: وجد في قائم سيف رسول اللّٰه ﷺ كتابان: (( إن من أشد الناس عتواً رجل ضرب غير ضاربه، ورجل قتل غير قاتله، ورجل تولى غير أهل نعمته. فمن فعل ذلك فقد كفر بالله ورسوله، لا يُقبل منه صرف ولا عدل ))."],"takhrij":"حسن: رواه ابن أبي عاصم في الديات (٢٢٨) واللفظ له، وأبو يعلى (٤٧٥٧) والدارقطني (١٣١/٣).","grade":"حسن","chapter_ar":"باب من قتل غير قاتله","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Abi Asim in al-Diyat (228), and this is his wording, as well as Abu Yaʿla (4757) and al-Daraqutni (3/131).","chapter_en":"One who kills someone other than his killer","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ماجاء في تحريم الدماء المعصومة","group_en":"Sections on the prohibition of unlawfully shedding protected blood","part_no":32,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah said: Two writings were found in the hilt of the sword of the Messenger of Allah ﷺ: “Among the people who are most defiant toward Allah are: a man who strikes someone other than the one who struck him, a man who kills someone other than the one who killed him, and a man who ascribes himself to other than those who bestowed favor upon him. Whoever does that has indeed disbelieved in Allah and His Messenger. No obligatory act or voluntary act will be accepted from him.”"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":228},{"key":"ابو_یعلی","label":"أبو يعلى","number":4757},{"key":"الدارقطنی","label":"الدارقطني","number":131},{"key":"sh12520","label":"مسند أبي يعلى","number":4757,"n":4762},{"key":"sh9771","label":"سنن الدارقطني","number":3249,"n":3263}]},{"num":6837,"demo":false,"sanad":"","matn":["عن ابن عباس قال: كان قريظة والنضير، وكان النضير أشرف من قريظة، فكان إذا قتل رجل من قريظة رجلاً من النضير قُتل به، وإذا قتل رجل من النضير رجلاً من قريظة فُدي بمائة وسق من تمر. فلما بعث النبي ﷺ قتل رجل من النضير رجلاً من قريظة، فقالوا: ادفعوه إلينا نقتله. فقالوا: بيننا وبينكم النبي ﷺ. فأتوه، فنزلت: ﴿وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ﴾ [المائدة: ٤٢]، والقسط: النفس بالنفس. ثم نزلت: ﴿أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ﴾ [المائدة: ٥٠]."],"takhrij":"حسن: رواه أبو داود (٤٤٩٤)، والنسائي (٤٧٣٢)، وابن الجارود (٧٧٢)، وصحّحه ابن حبان (٥٠٥٧).","grade":"حسن","chapter_ar":"باب النفس بالنفس","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4494), al-Nasa’i (4732), and Ibn al-Jarud (772), and authenticated by Ibn Hibban (5057).","chapter_en":"A life for a life","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn Abbas said: Qurayzah and Nadir were two tribes, and Nadir was nobler than Qurayzah. So when a man from Qurayzah killed a man from Nadir, he would be killed for him; but when a man from Nadir killed a man from Qurayzah, a ransom of one hundred wasqs of dates would be paid for him. Then when the Prophet ﷺ was sent, a man from Nadir killed a man from Qurayzah. They said: Hand him over to us so we may kill him. The others said: Let the Prophet ﷺ judge between us and you. So they came to him, and Allah revealed: “And if you judge, then judge between them with justice.” [al-Ma’idah: 42] And justice here means: a life for a life. Then Allah revealed: “Is it the judgment of the Age of Ignorance that they seek?” [al-Ma’idah: 50]"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4494},{"key":"nasai","label":"النسائي","number":4732},{"key":"ابن_الجارود","label":"ابن الجارود","number":772},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":5057},{"key":"ibnhibban","label":"صحيح ابن حبان (التقاسيم والأنواع)","number":4308,"n":4304}]},{"num":6838,"demo":false,"sanad":"","matn":["عن عبادة بن الصامت قال: كنا عند النبي ﷺ في مجلس فقال: (( بايعوني على أن لا تشركوا بالله شيئاً ولا تسرقوا ولا تزنوا - وقرأ هذه الآية كلها - فمن وفى منكم فأجره على الله، ومن أصاب من ذلك شيئاً فعوقب به فهو كفارته، ومن أصاب من ذلك شيئاً فستره اللّٰه عليه إن شاء غفر له وإن شاء عذبه))"],"takhrij":"متفق عليه: رواه البخاري (٦٧٨٤) ومسلم (٤١:١٧٠٩).","grade":"متفق عليه","chapter_ar":"باب أن القصاص والحدود كفّاراتٌ لأهلها","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6784) and Muslim (1709, no. 41).","chapter_en":"Retaliation and prescribed punishments are expiations for those upon whom they are carried out","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Ubadah ibn al-Samit said: We were with the Prophet ﷺ in a gathering, and he said: “Pledge allegiance to me that you will not associate anything with Allah, nor steal, nor commit adultery” — and he recited the entire verse. “Whoever among you fulfills that, his reward is with Allah. Whoever does any of that and is punished for it, then it is an expiation for him. And whoever does any of that and Allah conceals it for him, then if Allah wills He will forgive him, and if He wills He will punish him.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6784},{"key":"muslim","label":"مسلم","number":41}]},{"num":6839,"demo":false,"sanad":"","matn":["عن ابن مسعود قال: قال رسول اللّٰه ﷺ: (( لا يحل دم امرئ مسلم يشهد أن لا إله إلا الله وأني رسول اللّٰه ﷺ إلا بإحدى ثلاث: النفس بالنفس، والثيب الزاني، والمفارق لدينه التارك للجماعة ))"],"takhrij":"متفق عليه: رواه البخاري (٦٨٧٨)، ومسلم ( ١٦٧٦).","grade":"متفق عليه","chapter_ar":"باب القصاص في قتل العمد إلا إذا عفا أولياء المقتول","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6878) and Muslim (1676).","chapter_en":"Retaliation in intentional killing, unless the heirs of the slain pardon","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ibn Masud said: The Messenger of Allah ﷺ said: “The blood of a Muslim man who testifies that there is no god but Allah and that I am the Messenger of Allah ﷺ is not lawful except for one of three: a life for a life, a previously married adulterer, and one who leaves his religion and separates from the community.”"]},"intro":{"ar":["قال اللّٰه تعالى: ( أَنَّ النَّفْسَ بِالنَّفْسِ) [المائدة: ٤٥]","وقال تعالى: ( كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِي الْقَتْلَى) [البقرة: ١٧٨ ]"],"en":["Allah Most High said: “A life for a life.” [al-Ma’idah: 45]","And He said: “Prescribed for you is legal retaliation in cases of those killed.” [al-Baqarah: 178]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6878},{"key":"muslim","label":"مسلم","number":1676}]},{"num":6840,"demo":false,"sanad":"","matn":["عن وائل بن حجر قال: إني لقاعد مع النبي ﷺ إذ جاء رجل يقود آخر بنسعة فقال: يا رسول اللّٰه ﷺ! هذا قتل أخي. فقال رسول اللّٰه ﷺ: (( أقتلته؟ )) - فقال: إنه لو لم يعترف أقمت عليه البينة - قال: نعم قتلته. قال: (( كيف قتلته؟ )) قال: كنت أنا وهو نختبط من شجرة، فسبّني فأغضبني، فضربته بالفأس على قرنه فقتلته. فقال له النبي ﷺ: (( هل لك من شيء تؤديه عن نفسك؟ )) قال: ما لي مال إلا كسائي وفأسي. قال: (( فترى قومك يشترونك؟ )) قال: أنا أهون على قومي من ذاك. فرمى إليه بنسعته وقال: (( دونك صاحبك )). فانطلق به الرجل، فلما ولّى قال رسول اللّٰه ﷺ: (( إن قتله فهو مثله )). فرجع فقال: يا رسول اللّٰه ﷺ، إنه بلغني أنك قلت: (( إن قتله فهو مثله ))، وأخذته بأمرك. فقال رسول اللّٰه ﷺ: (( أما تريد أن يبوء بإثمك وإثم صاحبك؟ )) قال: يا نبي اللّٰه - لعله قال -: بلى. قال: (( فإن ذاك كذاك )). قال: فرمى بنسعته وخلى سبيله."],"takhrij":"صحيح: رواه مسلم (١٦٨٠).","grade":"صحيح","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1680, no. 32).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Wa’il ibn Hujr said: I was sitting with the Prophet ﷺ when a man came leading another man with a strap and said: O Messenger of Allah ﷺ, this man killed my brother. The Messenger of Allah ﷺ said: “Did you kill him?” He said: Had he not confessed, I would have produced evidence against him. He said: Yes, I killed him. He said: “How did you kill him?” He said: He and I were beating tree branches for fodder. He insulted me and made me angry, so I struck him on the head with an axe and killed him. The Prophet ﷺ said to him: “Do you have anything with which you can ransom yourself?” He said: I own nothing except my cloak and my axe. He said: “Do you think your people would buy you back?” He said: I am too insignificant among my people for that. So he threw the strap to the heir and said: “Take your companion.” The man went away with him. When he turned to leave, the Messenger of Allah ﷺ said: “If he kills him, then he is like him.” The man returned and said: O Messenger of Allah ﷺ, I was told that you said: “If he kills him, then he is like him,” yet I took him by your order. The Messenger of Allah ﷺ said: “Do you not want him to bear your sin and the sin of your companion?” He said: Yes, O Prophet of Allah. He said: “Then that is how it will be.” So he threw away the strap and let him go."]},"intro":{"ar":["قال اللّٰه تعالى: (فَمَن تَصَدَّقَ بِهِ، فَهُوَ كَفَّارَةٌ لَهُ ) [المائدة : ٤٥]"],"en":["Allah Most High said: “But whoever gives it up in charity, it will be an expiation for him.” [al-Ma’idah: 45]"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1680}]},{"num":6841,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قُتل رجل على عهد رسول اللّٰه ﷺ، فرفع ذلك إلى النبي ﷺ، فدفعه إلى ولي المقتول. فقال القاتل: يا رسول اللّٰه ﷺ، والله ما أردت قتله. فقال رسول اللّٰه ﷺ لولي المقتول: (( أما إنه إن كان صادقاً ثم قتلته دخلت النار )). فخلّى سبيله. قال: وكان مكتوفاً بنسعة، فخرج يجر نسعته، فسُمّي ذا النسعة."],"takhrij":"صحيح: رواه أبو داود (٤٤٩٨)، والترمذي (١٤٠٧)، والنسائي (٤٧٢٢)، وابن ماجه (٢٦٩٠). قال الترمذي: حسن صحيح. والنسعة: حبل.","grade":"صحيح","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4498), al-Tirmidhi (1407), al-Nasa’i (4722), and Ibn Majah (2690). Al-Tirmidhi said: “Sound authentic.”","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah said: A man was killed during the time of the Messenger of Allah ﷺ, so the matter was brought to the Prophet ﷺ, and he handed the killer over to the heir of the slain. The killer said: O Messenger of Allah ﷺ, by Allah, I did not intend to kill him. The Messenger of Allah ﷺ then said to the heir: “If he is truthful and you still kill him, you will enter the Fire.” So he let him go. He had been bound with a leather rope and left dragging it behind him, and so he was called “the man of the rope.”"]},"buhuth":{"en":["The word nisʿah means a rope."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4498},{"key":"tirmidhi","label":"الترمذي","number":1407},{"key":"nasai","label":"النسائي","number":4722},{"key":"ibnmajah","label":"ابن ماجه","number":2690}]},{"num":6842,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: أتى رجل بقاتل وليه إلى رسول اللّٰه ﷺ، فقال له النبي ﷺ: (( اعفُ )). فأبى. فقال: (( خذ أرشك )). فأبى. قال: (( اذهب فاقتله، فإنك مثله )). قال: فلُحق به، فقيل له: إن رسول اللّٰه ﷺ قد قال: (( اقتله فإنك مثله )). فخلّى سبيله. قال: فرُئي يجر نسعته ذاهباً إلى أهله. قال: كأنه قد كان أوثقه."],"takhrij":"حسن: رواه ابن ماجه (٢٦٩١)، والنسائي (٤٧٣٠)، وابن أبي عاصم في الديات (١٠١، ٢٢١).","grade":"حسن","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2691), al-Nasa’i (4730), and Ibn Abi Asim in al-Diyat (101, 221).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: A man brought the killer of his relative to the Messenger of Allah ﷺ. The Prophet ﷺ said to him: “Pardon him.” He refused. He said: “Then take the blood-money.” He refused. He said: “Then go and kill him, for you will be like him.” The man then set out with him. He was caught up with and told: The Messenger of Allah ﷺ has said: “Kill him and you will be like him.” So he let him go. He was later seen dragging his rope as he returned to his family, as though he had been tied with it."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2691},{"key":"nasai","label":"النسائي","number":4730},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":101}]},{"num":6843,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: ما رفع إلى رسول اللّٰه ﷺ أمر فيه القصاص، إلا أمر فيه بالعفو."],"takhrij":"حسن: رواه أبو داود (٤٤٩٧) والنسائي (٤٧٨٣،٤٧٨٤) وابن ماجه (٢٦٩٢) وأحمد ( ١٣٢٢٠).","grade":"حسن","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4497), al-Nasa’i (4783, 4784), Ibn Majah (2692), and Ahmad (13220).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Malik said: No case involving retaliation was ever brought to the Messenger of Allah ﷺ except that he would encourage pardon in it."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4497},{"key":"nasai","label":"النسائي","number":4783},{"key":"ibnmajah","label":"ابن ماجه","number":2692},{"key":"ahmad","label":"مسند الإمام أحمد","number":13220,"n":13220}]},{"num":6844,"demo":false,"sanad":"","matn":["عن رجل من أصحاب النبي ﷺ، عن النبي ﷺ قال: (( من أُصيب بشيء في جسده فتركه لله، كان كفارة له ))."],"takhrij":"حسن: رواه أحمد (٢٣٤٩٤) وابن أبي شيبة في مسنده كما في المطالب العالية (١٩٠٨).","grade":"حسن","chapter_ar":"باب الترغيب في العفو عن القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (23494) and Ibn Abi Shaybah in his Musnad, as cited in al-Matalib al-ʿAliyah (1908).","chapter_en":"Encouragement to pardon instead of demanding retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["A man from among the Companions of the Prophet ﷺ narrated from the Prophet ﷺ that he said: “Whoever is afflicted by an injury in his body and then forgoes retaliation for the sake of Allah, it will be an expiation for him.”"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_شیبہ/مسندہ_کما_فی_المطالب_العالیہ","label":"ابن أبي شيبة في مسنده كما في المطالب العالية","number":1908},{"key":"ahmad","label":"مسند الإمام أحمد","number":23494,"n":23494}]},{"num":6845,"demo":false,"sanad":"","matn":["عن أنس قال: كان رسول اللّٰه ﷺ يحث في خطبته على الصدقة، وينهى عن المثلة."],"takhrij":"صحيح: رواه النسائي (٤٠٤٧)، وابن أبي عاصم في الديات (٣٢٤)، والضياء في المختارة (٧/٦٨).","grade":"صحيح","chapter_ar":"باب الإحسان في القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (4047), Ibn Abi Asim in al-Diyat (324), and al-Diya’ in al-Mukhtarah (7/68).","chapter_en":"Excellence and restraint in retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ used to encourage charity in his sermons and forbid mutilation."]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4047},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":324},{"key":"الضیا/المختارہ","label":"الضياء في المختارة","number":7}]},{"num":6846,"demo":false,"sanad":"","matn":["عن الحسن البصري قال: جاءه رجل فقال: إن عبداً له أبق، وإنه نذر إن قدر عليه أن يقطع يده. فقال الحسن: حدثنا سمرة قال: قلما خطب النبي ﷺ خطبة إلا أمر فيها بالصدقة، ونهى فيها عن المثلة."],"takhrij":"صحيح: رواه أحمد ( ٢٠١٣٦).","grade":"صحيح","chapter_ar":"باب الإحسان في القصاص","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (20136).","chapter_en":"Excellence and restraint in retaliation","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Al-Hasan al-Basri said: A man came to him and said: I had a slave who ran away, and I vowed that if I caught him I would cut off his hand. Al-Hasan said: Samurah narrated to us that the Prophet ﷺ rarely gave a sermon except that he encouraged charity in it and forbade mutilation."]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":20136,"n":20136}]},{"num":6847,"demo":false,"sanad":"","matn":["عن أنس أن رسول اللّٰه ﷺ قضى بالقصاص في السن، وقال رسول اللّٰه ﷺ: (( كتاب اللّٰه القصاص ))."],"takhrij":"صحيح: رواه النسائي (٤٧٥٢)، وابن أبي عاصم في الديات (١٢٦)، وابن الجارود (٨٤١).","grade":"صحيح","chapter_ar":"باب القصاص في السِّنَّ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasa’i (4752), Ibn Abi Asim in al-Diyat (126), and Ibn al-Jarud (841).","chapter_en":"Retaliation regarding a tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas reported that the Messenger of Allah ﷺ ruled that retaliation applies in the case of a tooth, and the Messenger of Allah ﷺ said: “The Book of Allah prescribes retaliation.”"]},"intro":{"ar":["قال تعالى: ﴿وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالْأَنْفَ بِالْأَنْفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ﴾ [المائدة: ٤٥]"],"en":["Allah Most High said: “And We prescribed for them in it: a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, and a tooth for a tooth.” [al-Ma’idah: 45]"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4752},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":126},{"key":"ابن_الجارود","label":"ابن الجارود","number":841}]},{"num":6848,"demo":false,"sanad":"","matn":["عن أنس أن الربيع - وهي ابنة النضر - كسرت ثنية جارية، فطلبوا الأرش، وطلبوا العفو فأبوا، فأتوا النبي ﷺ فأمرهم بالقصاص. فقال أنس بن النضر: أتكسر ثنية الربيع يا رسول الله ﷺ؟ لا والذي بعثك بالحق لا تكسر ثنيتها! فقال: (( يا أنس، كتاب اللّٰه القصاص )). فرضي القوم وعفوا، فقال النبي ﷺ: (( إن من عباد اللّٰه من لو أقسم على اللّٰه لأبره )). زاد الفزاري، عن حميد، عن أنس: (( فرضي القوم وقبلوا الأرش ))."],"takhrij":"صحيح: رواه البخاري (٤٦١١، ٢٧٠٣).","grade":"صحيح","chapter_ar":"باب القصاص في السِّنَّ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (4611, 2703).","chapter_en":"Retaliation regarding a tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas reported that al-Rabiʿ — the daughter of al-Nadr — broke the front tooth of a young woman. They asked for compensation, and they also asked for pardon, but the people refused. So they brought the matter to the Prophet ﷺ, and he ordered retaliation. Anas ibn al-Nadr said: O Messenger of Allah ﷺ, will the tooth of al-Rabiʿ be broken? No, by the One who sent you with the truth, her tooth will not be broken. The Prophet ﷺ said: “O Anas, the Book of Allah prescribes retaliation.” Then the people were pleased and pardoned her, and the Prophet ﷺ said: “Among the servants of Allah are those who, if they swear by Allah, He fulfills it for them.”","Al-Fazari added, from Humayd, from Anas: “The people were pleased and accepted the compensation.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":4611}]},{"num":6849,"demo":false,"sanad":"","matn":["عن أنس أن أخت الربيع أم حارثة جرحت إنساناً، فاختصموا إلى النبي ﷺ، فقال رسول اللّٰه ﷺ: (( القصاص، القصاص )). فقالت أم الربيع: يا رسول الله ﷺ! أيقتص من فلانة؟ والله لا يقتص منها. فقال النبي ﷺ: (( سبحان اللّٰه! يا أم الربيع، القصاص كتاب اللّٰه )). قالت: لا والله لا يقتص منها أبداً. قال: فما زالت حتى قبلوا الدية. فقال رسول اللّٰه ﷺ: (( إن من عباد اللّٰه من لو أقسم على اللّٰه لأبره ))."],"takhrij":"صحيح: رواه مسلم (١٦٧٥).","grade":"صحيح","chapter_ar":"باب القصاص في السِّنَّ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1675).","chapter_en":"Retaliation regarding a tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas reported that the sister of al-Rabiʿ, the mother of Harithah, injured a person, and they took their dispute to the Prophet ﷺ. The Messenger of Allah ﷺ said: “Retaliation, retaliation.” The mother of al-Rabiʿ said: O Messenger of Allah ﷺ, will retaliation be taken from so-and-so? By Allah, retaliation will never be taken from her. The Messenger of Allah ﷺ said: “Glory be to Allah, O mother of al-Rabiʿ, retaliation is in the Book of Allah.” She said: No, by Allah, retaliation will never be taken from her. She continued until they accepted the blood-money. Then the Messenger of Allah ﷺ said: “Among the servants of Allah are those who, if they swear by Allah, He fulfills it for them.”"]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1675}]},{"num":6850,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: خرجت جارية عليها أوضاح بالمدينة، فرماها يهودي بحجر، فجيء بها إلى النبي ﷺ وبها رمق، فقال لها رسول اللّٰه ﷺ: (( فلان قتلك؟ )) فرفعت رأسها، فأعاد عليها، فقال: (( فلان قتلك؟ )) فرفعت رأسها، فقال لها في الثالثة: (( فلان قتلك؟ )) فخفضت رأسها، فدعا به رسول اللّٰه ﷺ فقتله بين الحجرين. وفي رواية: فأخذ فأُتي به رسول اللّٰه ﷺ، فأمر به أن يرجم حتى يموت، فرجم حتى مات."],"takhrij":"صحيح: رواه البخاري (٦٨٧٧) ومسلم (١٥:١٦٧٢)، والرواية الثانية عند مسلم.","grade":"صحيح","chapter_ar":"باب من القود يُقتل القاتل بمثل القتلة التي قتلها","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6877) and Muslim (1672, no. 15). The second wording is in Muslim.","chapter_en":"In retaliation, the killer may be killed in the same manner in which he killed","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Malik said: A young girl wearing silver ornaments went out in Madinah, and a Jew struck her with a stone. She was brought to the Prophet ﷺ while she still had a faint sign of life. The Messenger of Allah ﷺ asked her, “Did so-and-so kill you?” She raised her head. He asked her again, “Did so-and-so kill you?” She raised her head again. Then he asked her the third time, “Did so-and-so kill you?” She lowered her head. So the Messenger of Allah ﷺ called for him, and he was crushed between two stones.","In another narration: He was seized and brought to the Messenger of Allah ﷺ, who ordered that stones be thrown at him until he died, and so he was stoned until he died."]},"intro":{"ar":["قال اللّٰه تعالى: ( وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُم بِهِه وَلَيِن صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّبِرِينَ ) [سورة النحل: ١٢٦]","وقال تعالى: (وَجَزَوُا سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا) [الشورى: ٤٠]"],"en":["Allah Most High said: “If you punish, then punish with the like of that with which you were harmed; but if you are patient, it is better for those who are patient.” [al-Nahl: 126]","And He said: “The recompense of an evil is an evil like it.” [al-Shura: 40]"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6877},{"key":"muslim","label":"مسلم","number":15}]},{"num":6851,"demo":false,"sanad":"","matn":["عن ابن عمر أَنَّ غُلَامًا قُتِلَ غِيلَةً فَقَالَ عُمَرُ: لَو اشْتَرَكَ فِيهَا أَهْلُ صَنْعَاءَ لَقَتَلْتُهُمْ."],"takhrij":"صحيح: رواه البخاري (٦٨٩٦).","grade":"صحيح","chapter_ar":"باب إذا اشترك جماعة في القتل يُقتَصَّ منهم جميعا","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6896).","chapter_en":"If a group shares in a killing, retaliation is taken from all of them","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Ibn Umar reported that a boy was killed treacherously, and Umar said: “If all the people of Sana’a had shared in it, I would have killed them all for it.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6896}]},{"num":6852,"demo":false,"sanad":"","matn":["عن أبي جحيفة قال: سألت عليّاً رضي اللّٰه عنه: هل عندكم شيء مما ليس في القرآن؟ وقال ابن عيينة مرة: ما ليس عند الناس؟ فقال: والذي فلق الحبة وبرأ النسمة ما عندنا إلا ما في القرآن، إلا فهماً يعطى الرجل في كتابه، وما في الصحيفة. قلت: وما في","الصحيفة؟ قال: العقل،","وفكاك الأسير، وأن لا يُقتل مسلم بكافر."],"takhrij":"صحيح: رواه البخاري (٦٩١٥).","grade":"صحيح","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6915).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abu Juhayfah said: I asked Ali, may Allah be pleased with him, “Do you have anything that is not in the Qur’an?” Ibn Uyaynah once worded it, “Anything that the people do not have?” He replied, “By the One who splits the grain and creates the soul, we have nothing except what is in the Qur’an, except an understanding Allah gives a man of His Book, and what is in this written sheet.” I said, “What is in the sheet?” He said: “The blood-money, the ransom of captives, and that a Muslim is not to be killed for a disbeliever.”"]},"buhuth":{"ar":["وقوله: (( لا يقتل مؤمن بكافر)) لشرف الإسلام ونقص الكفر، والقصاص يُشعر بالمساواة، ولا مساواة بين الكافر والمسلم، لكن يجوز للإمام وولي الأمر أن يقتل القاتل المسلم تعزيرًا لحفظ الأمن."],"en":["Its meaning is that a believer is not killed in retaliation for a disbeliever, because of the honor of Islam and the deficiency of disbelief. Retaliation implies equality, and there is no equality between a disbeliever and a Muslim. However, the ruler may execute a Muslim killer as a discretionary punishment in order to preserve public safety."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6915}]},{"num":6853,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب قال: ما كتبنا عن النبي ﷺ إلا القرآن وما في هذه الصحيفة، قال النبي ﷺ: (( المدينة حرام ما بين عائر إلى كذا. فمن أحدث حدثاً أو آوى محدثاً فعليه لعنة اللّٰه والملائكة والناس أجمعين، لا يقبل منه عدل ولا صرف، وذمة المسلمين واحدة، يسعى بها أدناهم، فمن أخفر مسلماً فعليه لعنة اللّٰه والملائكة والناس أجمعين.. )) الحديث."],"takhrij":"متفق عليه: رواه البخاري (٣١٧٩) ومسلم (٤٦٨:١٣٧٠) والسياق للبخاري. قوله: (( أخفر)) أي","grade":"متفق عليه","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (3179) and Muslim (1370, no. 468), with this wording from al-Bukhari.","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Ali ibn Abi Talib said: We did not write down from the Prophet ﷺ anything except the Qur’an and what is in this sheet. The Prophet ﷺ said: “Madinah is sacred between Ayr and such-and-such. Whoever introduces an offense there or shelters an offender, upon him is the curse of Allah, the angels, and all people. No obligatory act or voluntary act will be accepted from him. The protection granted by the Muslims is one, and even the lowest among them may grant it. Whoever violates the protection granted by a Muslim, upon him is the curse of Allah, the angels, and all people…”"]},"buhuth":{"ar":["نقض عهده."],"en":["The phrase “akhfara” means: he violated his covenant."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3179},{"key":"muslim","label":"مسلم","number":468}]},{"num":6854,"demo":false,"sanad":"","matn":["عن إبراهيم التيمي، عن أبيه قال: خطبنا علي بن أبي طالب فقال: من زعم أن عندنا شيئا نقرأه إلا كتاب اللّه وهذه الصحيفة فقد كذب. فيها أسنان الإبل، وأشياء من الجراحات، وذمة المسلمين واحد يسعى بها أدناهم …… وذكر بقية الحديث."],"takhrij":"متفق عليه: رواه البخاري (٧٣٠٠) ومسلم (١٣٧٠).","grade":"متفق عليه","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (7300) and Muslim (1370).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Ibrahim al-Taymi narrated from his father, who said: Ali ibn Abi Talib addressed us and said: “Whoever claims that we possess anything to read besides the Book of Allah and this sheet has lied. In it are the ages and values of camels for compensation, rulings concerning certain wounds, and that the protection of the Muslims is one, and even the lowest among them may grant it…” Then he mentioned the rest of the hadith."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":7300},{"key":"muslim","label":"مسلم","number":1370}]},{"num":6855,"demo":false,"sanad":"","matn":["عن أبي حسان أن عليا رضي اللّٰه عنه كان يأمر بالأمر فيؤتى، فيقال: قد فعلنا كذا وكذا، فيقول: صدق اللّٰه ورسوله. قال: فقال له الأشتر: إن هذا الذي تقول قد تفشغ في الناس، أفشيء عهده إليك رسول اللّٰه ﷺ؟ قال عليٌّ رضي اللّٰه عنه: ما عهد إليَّ رسول اللّٰه ﷺ شيئاً خاصة دون الناس إلا شيء سمعته منه فهو في صحيفة في قراب سيفي، قال: فلم يزالوا به حتى أخرج الصحيفة، قال: فإذا فيها: ((من أحدث حدثاً أو آوى محدثاً فعليه لعنة اللّٰه والملائكة والناس أجمعين، لا يقبل منه صرف ولا عدل)). قال: وإذا فيها: ((إن إبراهيم حرم مكة وإني أحرم المدينة حراماً ما بين حرتيها، وحماها كله، لا يختلى خلاها، ولا ينفر صيدها، ولا تلتقط لقطتها إلا لمن أشار بها، ولا تقطع منها شجرة إلا أن يعلف رجل بعيره، ولا يحمل فيها السلاح لقتال)). قال: وإذا فيها: ((المؤمنون تتكافأ دماؤهم ويسعى بذمتهم أدناهم، وهم يد على من سواهم، ألا لا يقتل مؤمن بكافر، ولا ذو عهد في عهده)). وقوله: تفشّغ - أي فشا وانتشر. صحيح: رواه الإمام أحمد (٩٥٩)، والنسائي (٤٧٤٦)، وأبو داود (٢٠٣٥)، والنسائي (٤٧٤٥)."],"takhrij":"","grade":"","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (959), al-Nasa’i (4746, 4745), and Abu Dawud (2035).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abu Hassan said: Ali, may Allah be pleased with him, would command something, and then when people came to him and said, “We have done such-and-such,” he would say, “Allah and His Messenger have spoken the truth.” Al-Ashtar said to him: “What you keep saying has spread widely among the people. Is it something the Messenger of Allah ﷺ entrusted to you in particular?” Ali, may Allah be pleased with him, said: “The Messenger of Allah ﷺ did not entrust me with anything exclusive over the people, except something I heard from him and it is written on a sheet in the sheath of my sword.” They continued asking him until he took out the sheet. In it was written: “Whoever introduces an offense or shelters an offender, upon him is the curse of Allah, the angels, and all people. No obligatory act or voluntary act will be accepted from him.” And in it was written: “Abraham made Makkah sacred, and I make Madinah sacred between its two lava tracts and all its protected land. Its fresh herbage is not to be cut, its game is not to be driven away, its lost property is not to be picked up except by one who announces it, and none of its trees are to be cut except for a man feeding his camel. Weapons are not to be carried in it for fighting.” And in it was written: “The believers’ blood is equal, the lowest among them may grant protection on behalf of them all, and they are united against others. A believer is not to be killed for a disbeliever, nor one under covenant while he remains under his covenant.”","The phrase tafashshagha means: it became widespread and public."]}},"tuhfa":{},"refs":[]},{"num":6856,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول اللّٰه ﷺ قال: (( لا يقتل مسلم بكافر، وقال: دية عقل الكافر نصف دية عقل المؤمن )). حسن: رواه الترمذي (١٤١٣) واللفظ له، وأحمد (٦٦٩٢)."],"takhrij":"","grade":"","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1413), and this is his wording, and Ahmad (6692).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “A Muslim is not killed for a disbeliever.” And he also said: “The blood-money of a disbeliever is half the blood-money of a believer.”"]}},"tuhfa":{},"refs":[]},{"num":6857,"demo":false,"sanad":"","matn":["عن عائشة قالت: وجدت في قائم سيف رسول اللّٰه ﷺ كتاباً: (( إن أشد الناس عُتواً من ضرب غير ضاربه، ورجل قتل غير قاتله، ورجل تولّى غير أهل نعمته، فمن فعل ذلك فقد كفر بالله ورسوله، لا يقبل اللّٰه منه صرفاً، ولا عدلاً، وفي الأجر المؤمنون تكافأ دماؤهم، ويسعى بذمتهم أدناهم، لا يقتل مسلم بكافر، ولا ذو عهد في عهده، ولا يتوارث أهل ملتين، ولا تُنكح المرأة على عمتها، ولا على خالتها، ولا صلاة بعد العصر حتى تغرب الشمس، ولا تسافر امرأة ثلاث ليال مع غير ذي محرم))."],"takhrij":"حسن: رواه أبو يعلى (٤٧٥٧) وابن أبي عاصم في الديات (١٠٧) والدار قطني (١٣١/٣) والبيهقي","grade":"حسن","chapter_ar":"باب المسلمون تتكافأ دماؤهم وذمتهم واحدة ولا يقتل مؤمن بكافر","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Yaʿla (4757), Ibn Abi Asim in al-Diyat (107), al-Daraqutni (3/131), and al-Bayhaqi (8/29–30).","chapter_en":"The blood of Muslims is equal, their pledge of protection is one, and a believer is not killed for a disbeliever","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["ʿA’ishah said: A written document was found in the hilt of the sword of the Messenger of Allah ﷺ which said: “Among the people most defiant are: a man who strikes someone other than the one who struck him, a man who kills someone other than the one who killed him, and a man who allies himself with other than those who bestowed favor upon him. Whoever does that has disbelieved in Allah and His Messenger. Allah will accept from him neither obligatory nor voluntary deeds. In retribution, the believers’ blood is equal, and the lowest among them may grant protection on behalf of them all. A Muslim is not killed for a disbeliever, nor one under covenant while he remains under his covenant. The followers of two different religions do not inherit from one another. A woman is not married together with her paternal aunt nor with her maternal aunt. There is no prayer after the afternoon prayer until the sun sets. And no woman may travel for three nights without a close male relative.”"]},"buhuth":{"ar":["(٣٠-٢٩/٨)","وقوله: (( تتكافأ دماؤهم)) التكافؤ التساوي أي الشريف والوضيع تتساوى في القصاص. معناه: إن دماء المسلمين متساوية في القصاص، يقاد الشريف بالوضيع، والكبير بالصغير فلا يقتل غير قاتله وإن كان المقتول شريفاً، أو ثرياً، بخلاف ما كان يفعله أهل الجاهلية. ما كانوا يرضون في دم الشريف بقاتله فقط بل كانوا يقتلون عددا من قبيلة القاتل.","وقوله: (( يسعى بذمتهم أدناهم)): الذمة هي الأمان أي إن أدنى رجل من المسلمين إذا أعطى أمانا","فليس للباقين إخفاره كالعبد والمرأة وغيرهما.","وقوله: (( المؤمنون يد على من سواهم)): أي أن المسلمين إخوة يعاون بعضهم بعضا على غيرهم من","الكفار والمشركين."],"en":["The phrase “their blood is equal” means equality: the noble and the lowly are equal in retaliation. In other words, the blood of Muslims is equal in legal retaliation, so a noble person is retaliated against for killing a humble person, and an older person for a younger one. No one other than the killer is to be killed, even if the slain person was noble or wealthy. This is unlike the practice of the people of the pre-Islamic era, who would not be satisfied with killing only the killer of a nobleman, but would kill several people from the killer’s tribe.","The phrase “the lowest among them may grant protection” means that even the humblest Muslim, if he grants safety or protection, the rest may not violate it, whether that person is a slave, a woman, or otherwise.","And the phrase “the believers are united against others” means that the Muslims are brothers who support one another against disbelievers and idolaters."]}},"tuhfa":{},"refs":[{"key":"ابو_یعلی","label":"أبو يعلى","number":4757},{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":107},{"key":"الدار_قطنی","label":"الدار قطني","number":131},{"key":"sh12520","label":"مسند أبي يعلى","number":4757,"n":4762}]},{"num":6858,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رجلا قتل عبده متعمداً، فجلده النبي ﷺ مائة جلدة، ونفاه سنة، ومحا سهمه من المسلمين، ولم يقده به، وأمره أن يعتق رقبة."],"takhrij":"حسن: رواه الدار قطني (١٤٤-١٤٣/٣) وعنه البيهقي (٣٦/٨) والطحاوي في شرحه (١٣٧/٣ -","grade":"حسن","chapter_ar":"باب من قال : لا يقتل السيد بالعبد","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Daraqutni (3/143–144), and through him al-Bayhaqi (8/36), and al-Tahawi in his commentary (3/137–138).","chapter_en":"Those who said that the master is not killed for the slave","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that a man intentionally killed his slave. The Prophet ﷺ flogged him one hundred lashes, exiled him for one year, removed his share/allotment from among the Muslims, did not execute him in retaliation for the slave, and ordered him to free a slave."]},"buhuth":{"ar":["١٣٨)."]}},"tuhfa":{},"refs":[{"key":"الدار_قطنی","label":"الدار قطني","number":144},{"key":"عنہ_البیہقی","label":"عنه البيهقي","number":36},{"key":"sh9771","label":"سنن الدارقطني","number":3282,"n":3296},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15951,"n":16109}]},{"num":6859,"demo":false,"sanad":"","matn":["عن عبد الله بن عمرو قال: جاء رجل إلى النبي ﷺ صارخاً، فقال له رسول اللّٰه ﷺ: (( ما لك؟ )) قال: سيدي رآني أقبّل جارية له، فجبّ مذاكيري. فقال النبي ﷺ: (( عليّ بالرجل )). فطلب، فلم يقدر عليه. فقال رسول اللّٰه ﷺ: (( اذهب فأنت حر )). قال: على من نصرتي يا رسول الله ﷺ؟ قال: يقول: أرأيت إن استرقني مولاي؟ فقال رسول اللّٰه ﷺ: (( على كل مؤمن أو مسلم )). حسن: رواه أبو داود (٤٥١٩)، وابن ماجه (٢٦٨٠)، وأحمد (٦٧١٠)، وعبد الرزاق (١٧٩٣٢)."],"takhrij":"","grade":"","chapter_ar":"باب من قال : لا يقتل السيد بالعبد","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4519), Ibn Majah (2680), Ahmad (6710), and Abd al-Razzaq (17932).","chapter_en":"Those who said that the master is not killed for the slave","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Abdullah ibn Amr said: A man came to the Prophet ﷺ crying out. The Messenger of Allah ﷺ said to him, “What is wrong with you?” He said: My master saw me kissing a slave girl of his, so he cut off my private parts. The Prophet ﷺ said: “Bring me the man.” He was sought, but they could not catch him. So the Messenger of Allah ﷺ said: “Go, you are free.” The man said: Who will support me, O Messenger of Allah ﷺ? He meant: What if my master enslaves me again? The Messenger of Allah ﷺ said: “That is upon every believer,” or he said, “upon every Muslim.”"]}},"tuhfa":{},"refs":[]},{"num":6860,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن عبد اللّه بن عمرو بن العاص قال: نحلت لرجل من بني مدلج جارية، فأصاب منها ابنا، فكان يستخدمها، فلما شب الغلام دعاها يوماً فقال: اصنعي كذا وكذا. فقال: لا تأتيك، حتى متى تستأمي أمي؟ قال: فغضب فحذفه بسيفه. فأصاب رجله.","فنزف الغلام فمات. فانطلق في رهط من قومه إلى عمر. فقال: يا عدو نفسه أنت الذي قتلت ابنك، لو لا أني سمعت رسول اللّٰه ﷺ يقول: (( لا يقاد الأب من ابنه )) لقتلتك. هلم ديته. قال: فأتاه بعشرين أو ثلاثين ومائة بعير. قال: فخيّر منها مائة فدفعها إلى ورثته، وترك أباه."],"takhrij":"حسن: رواه البيهقي (٣٨/٨) وابن الجارود (٧٨٨) والدار قطني (١٤٠/٣) واللفظ للبيهقي وابن الجارود.","grade":"حسن","chapter_ar":"باب لا يقاد الأب من ابنه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bayhaqi (8/38), Ibn al-Jarud (788), and al-Daraqutni (3/140). This wording is from al-Bayhaqi and Ibn al-Jarud.","chapter_en":"A father is not subject to retaliation for killing his son","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع أبواب ما جاء في القصاص","group_en":"Collection of Chapters on Retaliation","part_no":32,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from Abdullah ibn Amr ibn al-As, who said: A man from Banu Mudlij was given a slave-woman as a gift, and he had a son from her. He used to make her serve him. When the boy grew up, he called her one day and said, “Do such-and-such.” The boy said, “She will not come to you. How long will you keep using my mother as a servant?” The man became angry and threw a sword at him, striking his leg. The boy bled until he died. Then the man went with a group from his people to Umar. Umar said, “Enemy of himself, you are the one who killed your own son. Had I not heard the Messenger of Allah ﷺ say, ‘A father is not executed in retaliation for his son,’ I would have killed you. Bring his blood-money.” So he brought one hundred and twenty or one hundred and thirty camels. Umar selected one hundred from them and gave them to the heirs, excluding the father."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":38},{"key":"ابن_الجارود","label":"ابن الجارود","number":788},{"key":"الدار_قطنی","label":"الدار قطني","number":140},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":15964,"n":16122}]},{"num":6861,"demo":false,"sanad":"","matn":["عن ابن عباس يقول: كان في بني إسرائيل القصاص، ولم تكن فيهم الدية. فقال اللّٰه تعالى لهذه الأمة: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنثَىٰ بِالْأُنثَىٰ فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ﴾ [البقرة: ١٧٨] فالعفو أن يقبل الدية في العمد. ﴿فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ﴾ [البقرة: ١٧٨] يتبع بالمعروف ويؤدي بإحسان. ﴿ذَٰلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ﴾ مما كتب على من كان قبلكم. ﴿فَمَنِ اعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُ عَذَابٌ أَلِيمٌ﴾ [البقرة: ١٧٨] أي قتل بعد قبول الدية. صحيح: رواه البخاري (٤٤٩٨)."],"takhrij":"","grade":"","chapter_ar":"باب ما جاء في الدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (4498).","chapter_en":"What has come regarding blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn Abbas said: Among the Children of Israel there was retaliation, but there was no blood-money among them. Then Allah said to this nation: “O you who believe, retaliation is prescribed for you in cases of murder…” up to His saying: “whoever is pardoned anything by his brother…” [al-Baqarah: 178]. The pardon means that blood-money may be accepted in a case of intentional killing. “Then there should be a fair follow-up and payment to him with excellence” means that the claim should be pursued in a fair manner and the payment made properly. “That is a lightening from your Lord and a mercy” means in comparison to what was prescribed on those before you. “So whoever transgresses after that, for him is a painful punishment” [al-Baqarah: 178], meaning whoever kills after accepting the blood-money."]},"intro":{"ar":["قال تمالى: ( يَأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيْكُمْ ٱلْقِصَاصُ فِى الْقَتْلَ الحُرِّبِٱلْحَرِ وَٱلْعَبْدُ بِٱلْعَبْدِ وَالأُنَ","بِٱلْأُنتَى فَمَنْ عُفِى لَهُ من أَخِيهِ شَي تبَاع بِلْمَعْرُونِ وَاء لَيْهِ بإحسَن) [البقرة: ١٧٨ ]"],"en":["Allah Most High said: “O you who believe, retaliation is prescribed for you in cases of murder: the free for the free, the slave for the slave, and the female for the female. But whoever is pardoned anything by his brother, then there should be a fair follow-up and payment to him with excellence.” [al-Baqarah: 178]"]}},"tuhfa":{},"refs":[]},{"num":6862,"demo":false,"sanad":"","matn":["عن أبي جحيفة قال: سألت علياً رضي اللّٰه عنه: هل عندكم شيء ما ليس في القرآن.","وقال مرة: ما ليس عند الناس؟ فقال: والذي فلق الحبة وبرأ النسمة ما عندنا إلا ما في القرآن - إلا فهماً يعطى رجل في كتابه - وما في الصحيفة. قلت: وما في الصحيفة؟ قال: العقل، وفكاك الأسير، وأن لا يقتل مسلم بكافر."],"takhrij":"صحيح: رواه البخاري (٦٩٠٣).","grade":"صحيح","chapter_ar":"باب ما جاء في الدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6903).","chapter_en":"What has come regarding blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abu Juhayfah said: I asked Ali, may Allah be pleased with him, “Do you have anything that is not in the Qur’an?” In another wording: “Anything the people do not have?” He replied, “By the One who splits the grain and creates the soul, we have nothing except what is in the Qur’an, except an understanding that a man may be given regarding His Book, and what is in the written sheet.” I said, “What is in the sheet?” He said: “The blood-money, the ransom of captives, and that a Muslim is not to be killed for a disbeliever.”"]},"buhuth":{"ar":["قوله: (( العقل )): أي الدية. وسميت الدية عقلاً تسميةً بالمصدر. لأن الإبل كانت تعقل بفناء ولي القتيل، ثم كثر الاستعمال حتى أطلق العقل على الدية ولو لم تكن إبلاً. فتح الباري (٢٤٦/١٢)"],"en":["The word al-aql here means blood-money. It was called that because camels used to be tied at the courtyard of the slain person’s guardian as payment, and then the term came to be used for blood-money in general, even if it was not paid in camels."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6903}]},{"num":6863,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: لما فتح اللّٰه على رسوله مكة قام في الناس، فحمد اللّٰه وأثنى عليه ثم قال: …. (( ومن قتل له قتيل فهو بخير النظرين: إما أن يُفدى وإما أن يُقيد )) متفق عليه: رواه البخاري (٢٤٣٤)، ومسلم (١٣٥٥)."],"takhrij":"","grade":"","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (2434) and Muslim (1355).","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: When Allah granted His Messenger the conquest of Makkah, he stood among the people, praised Allah, and extolled Him, then said: “Whoever has had a relative killed has the better of two choices: either he may accept compensation, or he may demand retaliation.”"]}},"tuhfa":{},"refs":[]},{"num":6864,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: قال رسول اللّٰه ﷺ: (( من قتل عمداً دفع إلى أولياء القتيل، فإن شاؤوا قتلوا، وإن شاؤوا أخذوا الدية. وذلك ثلاثون حقة، وثلاثون جذعة، وأربعون خلفة. وذلك عقل العمد، وما صولحوا فهو لهم، وذلك تشديد العقل ))"],"takhrij":"حسن: رواه الترمذي (١٣٨٧) وابن ماجه (٢٦٢٦) وأبو داود (٤٥٠٦). قال الترمذي:","grade":"حسن","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1387), Ibn Majah (2626), and Abu Dawud (4506). Al-Tirmidhi said: “Sound and singular.”","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “Whoever is killed intentionally, his killer is handed over to the heirs of the slain. If they wish, they may kill him, and if they wish, they may take the blood-money. That blood-money is thirty hiqqahs, thirty jadhaʿahs, and forty pregnant she-camels. That is the blood-money for intentional killing. Whatever amount they agree upon in settlement belongs to them, and that is the stricter blood-money.”"]},"buhuth":{"ar":["“حسن غريب”."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1387},{"key":"ibnmajah","label":"ابن ماجه","number":2626},{"key":"abudawud","label":"أبو داود","number":4506}]},{"num":6865,"demo":false,"sanad":"","matn":["عن أبي شريح الكعبي يقول: قال رسول اللّٰه ﷺ: (( ألا إنكم معشر خُزاعة قتلتم هذا لقتيل من هُذيل، وإني عاقله. فمن قتل له بعد مقالتي هذه قتيل فأهله بين خيرين. أن يأخذوا العقل، أو يقتلوه ))."],"takhrij":"صحيح: رواه أبو داود (٤٥٠٤) والترمذي (١٤٣٩) وأحمد (٢٧١٦٠) والدار قطني (٩٦-٩٥/٣).","grade":"صحيح","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4504), al-Tirmidhi (1439), Ahmad (27160), and al-Daraqutni (3/95–96). Al-Tirmidhi said: “This is a sound authentic hadith.”","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu Shurayh al-Kaʿbi said: The Messenger of Allah ﷺ said: “O people of Khuzaʿah, you have killed this man in return for one slain from Hudhayl, and I will pay his blood-money. So whoever has someone killed after this statement of mine, his family has two choices: either they take the blood-money or they kill the killer.”"]},"buhuth":{"ar":["قال الترمذي: “هذا حديث حسن صحيح”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4504},{"key":"tirmidhi","label":"الترمذي","number":1439},{"key":"الدار_قطنی","label":"الدار قطني","number":96},{"key":"ahmad","label":"مسند الإمام أحمد","number":27160,"n":27160}]},{"num":6866,"demo":false,"sanad":"","matn":["عن أبي شُريح الخزاعي قال: لما بعث عمرو بن سعيد إلى مكة بعثه يغزو ابن الزبير، أتاه أبو شريح فكلمه، وأخبره بما سمع رسول اللّٰه ﷺ فمما قال: (( يا معشر خزاعة ارفعوا أيديكم عن القتل، فقد كثر أن يقع، لئن قتلتم قتيلاً لأدينه. فمن قتل بعد مقامي هذا فأهله بخير النظرين: إن شاؤوا فدم قاتله، وإن شاؤوا فعقله ))."],"takhrij":"حسن: رواه أحمد (١٦٣٧٧).","grade":"حسن","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ahmad (16377).","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abu Shurayh al-Khuzaʿi said: When Amr ibn Saʿid sent forces to Makkah against Ibn al-Zubayr, Abu Shurayh came to him, spoke to him, and informed him of what he had heard from the Messenger of Allah ﷺ. Among what he said was: “O people of Khuzaʿah, keep your hands back from killing, for killing has become excessive. If you kill someone, I will indeed pay his blood-money. Whoever is killed after this statement of mine, then his family has the better of two choices: if they wish, they may take the blood of his killer, and if they wish, they may take his blood-money.”"]}},"tuhfa":{},"refs":[{"key":"ahmad","label":"مسند الإمام أحمد","number":16377,"n":16377}]},{"num":6867,"demo":false,"sanad":"","matn":["عن ابن عباس أن النبي ﷺ قال: (( من قتل في عميّة، أو عصبية بحجر أو سوط أو عصا، فعليه عقل الخطأ، ومن قتل عمداً فهو قود، ومن حال بينه وبينه، فعليه لعنة اللّٰه والملائكة والناس أجمعين، لا يُقبل منه صرف، ولا عدل)). وفي رواية: (( من قتل عمداً فقود يده ))"],"takhrij":"حسن: رواه أبو داود (٤٥٤٠) والنسائي (٤٧٨٩)، وابن ماجه (٢٦٣٥) والطحاوي في مشكله","grade":"حسن","chapter_ar":"باب ولي العمد مخير بين التل أو العفأ لدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4540), al-Nasa’i (4789), Ibn Majah (2635), and al-Tahawi in Mushkil al-Athar (4900).","chapter_en":"The guardian in an intentional killing has the choice between retaliation or pardoning in exchange for blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Ibn Abbas reported that the Prophet ﷺ said: “Whoever is killed in blind fighting or tribal partisanship by a stone, a whip, or a stick, then the blood-money of accidental killing is due. Whoever is killed intentionally, then retaliation applies. And whoever comes between the killer and that retaliation, upon him is the curse of Allah, the angels, and all people; neither obligatory nor voluntary deeds will be accepted from him.”","In another narration: “Whoever kills intentionally, then his hand is liable to retaliation.”"]},"buhuth":{"ar":["(٤٩٠٠).","وأما معنى الحديث في قوله: “من قتل عمداً فهو قود”. أي أن الواجب هو القود، ولكن إذا تنازل","أولياء المقتول عن القود فلهم ذلك إما العفو وإما الدية، فلا تعارض بين القود وقبول الدية.","وقوله: (( لا يقبل منه صرف )) أي توبة. وقوله: (( ولا عدل )) أي فدية."],"en":["The meaning of the phrase “whoever kills intentionally, then retaliation applies” is that retaliation is the original ruling. But if the heirs of the slain person waive retaliation, they may do so, either by pardoning or by accepting blood-money, so there is no contradiction between retaliation and accepting compensation.","The phrase “no sarf will be accepted from him” means no repentance, and “nor ʿadl” means no ransom."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4540},{"key":"nasai","label":"النسائي","number":4789},{"key":"ibnmajah","label":"ابن ماجه","number":2635}]},{"num":6868,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله يقول:","كتب النبي ﷺ على كل بطن عقوله."],"takhrij":"صحيح: رواه مسلم (١٥٠٧).","grade":"صحيح","chapter_ar":"باب ما جاء من الديات على البطون","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1507).","chapter_en":"Reports regarding blood-money upon the clans","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: The Prophet ﷺ assigned the blood-money obligations to each clan."]},"buhuth":{"ar":["والعقول: الديات، واحدها عقل كفلس وفلوس.","ومعناه: أن الدية في قتل الخطأ وشبه العمد تجب على العاقلة، وهم العصبات، سواء الآباء والأبناء وإن علوا أو سفلوا.","والبطن دون القبيلة، والفخذ دون البطن."],"en":["The word al-ʿuqūl means blood-money payments; its singular is ʿaql.","The meaning is that the blood-money for accidental killing and quasi-intentional killing is borne by the ʿāqilah, meaning the agnatic relatives, including fathers and sons, whether ascending or descending.","A baṭn is a subdivision below the tribe, and a fakhdh is a subdivision below the baṭn."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1507}]},{"num":6869,"demo":false,"sanad":"","matn":["عن أبي هريرة أن امرأتين من هذيل رمت إحداهما الأخرى، فطرحتْ جنينها، فقضى فيه رسول اللّٰه ﷺ غرة عبد أو وليدة."],"takhrij":"متفق عليه: رواه مالك (٥)، والبخاري (٦٩٠٤)، ومسلم (١٦٨١).","grade":"متفق عليه","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (5), al-Bukhari (6904), and Muslim (1681).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that two women from Hudhayl fought, and one of them threw something at the other, causing her to miscarry her fetus. The Messenger of Allah ﷺ ruled that compensation for it was a male slave or a female slave."]},"buhuth":{"ar":["و أصل الغرة: بياض في الوجه، فعبر بذلك عن الجسم كله كإطلاق الرقبة على العبد المملوك."],"en":["The original meaning of ghurrah is whiteness in the face, but it came to refer to the whole person, just as “neck” is used to mean a slave."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":5},{"key":"bukhari","label":"البخاري","number":6904},{"key":"muslim","label":"مسلم","number":1681}]},{"num":6870,"demo":false,"sanad":"","matn":["عن أبي هريرة قال:","اقتتلت امرأتان من هذيل، فرمت إحداهما الأخرى بحجر فقتلتها وما في بطنها، فاختصموا إلى رسول اللّٰه ﷺ.","فقضى رسول اللّٰه ﷺ أن دية جنينها غرة: عبد أو وليدة، وقضى بدية المرأة على عاقلتها، وورثها ولدها ومن معهم.","فقال حمل بن النابغة الهذلي:","يا رسول الله ﷺ، كيف أغرم من لا شرب ولا أكل، ولا نطق ولا استهل؟ فمثل ذلك يطل.","فقال رسول اللّٰه ﷺ:","«إِنَّمَا هَذَا مِنْ إِخْوَانِ الْكُهَّانِ».","من أجل سجعه الذي سجع."],"takhrij":"صحيح: رواه البخاري (٦٩١٠)، ومسلم (١٦٨١/٣٦)، واللفظ لمسلم.","grade":"صحيح","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6910) and Muslim (1681/36). This is Muslim’s wording.","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported: Two women from Hudhayl fought, and one of them threw a stone at the other, killing her and the fetus in her womb. Their dispute was brought before the Messenger of Allah ﷺ. The Messenger of Allah ﷺ ruled that the compensation for the fetus was a ghurrah—a male or female slave. He ruled that the blood-money for the woman was to be paid by the killer’s ʿāqilah, and he assigned her inheritance to her children and the other heirs with them.","Ḥamal ibn al-Nābighah al-Hudhalī said: “O Messenger of Allah ﷺ, how can I be made to pay compensation for one who neither drank nor ate, neither spoke nor cried at birth? Such a case should be disregarded.” The Messenger of Allah ﷺ said: “This man is only one of the brothers of the soothsayers,” because of the rhyming manner in which he spoke."]},"buhuth":{"ar":["قوله: «على عاقلتها»: عاقلة الرجل قراباته من قبل الأب، وهم عصبته، وفيه أن الولد ليس من العاقلة، وأن العاقلة لا ترث إلا ما فضل عن أصحاب الفروض.","وقوله: «يطل»: أي يهدر ولا يضمن.","وفيه دليل على أن دية شبه العمد على العاقلة، بخلاف دية العمد فإنها على الجاني في ماله."],"en":["The expression “upon her ʿāqilah” refers to the paternal relatives who form the agnatic kin. This indicates that the child is not part of the ʿāqilah, and that the ʿāqilah inherits only what remains after the fixed-share heirs.","The word “yuṭall” means that it would be left without compensation.","It also shows that the blood-money for quasi-intentional killing is borne by the ʿāqilah, whereas the blood-money for intentional killing is borne by the offender from his own wealth."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6910},{"key":"muslim","label":"مسلم","number":1681}]},{"num":6871,"demo":false,"sanad":"","matn":["عن المغيرة بن شعبة، عن عمر رضي اللّٰه عنه:","أنه استشارهم في إملاص المرأة للمرأة.","فقال المغيرة:","قضى النبي ﷺ بالغرة: عبد أو أمة.","قال:","ائت بمن يشهد معك.","فشهد محمد بن مسلمة أنه شهد النبي ﷺ قضى به."],"takhrij":"متفق عليه: رواه البخاري (٦٩٠٥-٦٩٠٨)، ومسلم (١٦٨٩).","grade":"متفق عليه","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6905–6908) and Muslim (1689).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah reported that ʿUmar may Allah be pleased with him consulted the people concerning the case of one woman causing another woman to miscarry. Al-Mughīrah said: “The Prophet ﷺ ruled that the compensation was a ghurrah: a male or female slave.” ʿUmar said: “Bring someone who can testify along with you.” Muḥammad ibn Maslamah then testified that he had witnessed the Prophet ﷺ give that ruling."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6905},{"key":"muslim","label":"مسلم","number":1689}]},{"num":6872,"demo":false,"sanad":"","matn":["عن المغيرة بن شعبة قال: ضربت امرأة ضرّتها بعمود فُسطاط وهي حبلى، فقتلتها قال: وإحداهما لِحْيانية. قال: فجعل رسول اللّٰه ﷺ دية المقتولة على عصبة القاتلة. وغرةً لما في بطنها.","فقال رجل من عصبة القاتلة: أنغرم دية من لا أكل ولا شرب ولا استهل؟ فمثل ذلك يطلّ! فقال رسول اللّٰه ﷺ: (( أسجع كسجع الأعراب! )) قال: وجعل عليهم الدية."],"takhrij":"صحيح: رواه مسلم (٣٧:١٦٨٢).","grade":"صحيح","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1682, no. 37).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Al-Mughirah ibn Shuʿbah said: A woman struck her co-wife with a tent pole while she was pregnant and killed her. One of the two women was from Lihyan. The Messenger of Allah ﷺ ruled that the blood-money of the slain woman was upon the killer’s agnate relatives, and that there was a ghurrah for what was in her womb. A man from the killer’s agnate relatives said: “Are we to pay compensation for one who neither ate nor drank nor cried at birth? Such a thing should be disregarded.” The Messenger of Allah ﷺ said: “Rhymed speech like the rhymed speech of the Bedouins?” Then he imposed the blood-money upon them."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":37}]},{"num":6873,"demo":false,"sanad":"","matn":["عن أسامة بن عمير الهذلي. وكان قد صحب النبي ﷺ قال: كانت فينا امرأتان، فضربت إحداهما الأخرى بعمود، فقتلتها، وقتلت ما فيه بطنها، فقضى النبي ﷺ في المرأة بالدية، وقضى بدية الغرة لزوجها، وقضى بالعقل على عصبة القاتلة، وقضى في الجنين بغرة عبد، أو أمة."],"takhrij":"صحيح: رواه ابن أبي عاصم في الديات (١٧١) والطحاوي في مشكله (٤٥٢١) والطبراني في الكبير","grade":"صحيح","chapter_ar":"باب دية الجنين","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Abi Asim in al-Diyat (171), al-Tahawi in Mushkil al-Athar (4521), and al-Tabarani in al-Kabir (1/160).","chapter_en":"The blood-money for a fetus","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Usamah ibn Umair al-Hudhali, who had accompanied the Prophet ﷺ, said: There were two women among us, and one of them struck the other with a pole and killed her and the child in her womb. The Prophet ﷺ ruled that the woman’s case required blood-money, that the compensation for the fetus was for her husband, that the blood-money was due upon the killer’s agnate relatives, and that the fetus required a ghurrah, either a male slave or a female slave."]},"buhuth":{"ar":["(١٦٠ /١)"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":171},{"key":"الطحاوی/مشکلہ","label":"الطحاوي في مشكله","number":4521}]},{"num":6874,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: قضى رسول اللّٰه ﷺ أن يعقل المرأة عصبتها من كانوا، ولا يرثون منها شيئاً إلا ما فَضل عن ورثتها، وإن قُتلت فعقلها بين ورثتها، فهم يقتلون قاتلها."],"takhrij":"حسن: رواه ابن ماجه (٢٦٤٧).","grade":"حسن","chapter_ar":"باب عقل المرأة على عصبتها، وميراثها لورثتها","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2647).","chapter_en":"A woman’s blood-money is borne by her agnate relatives, and her estate goes to her heirs","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ ruled that a woman’s blood-money liability is borne by her agnate relatives, whoever they may be, and they inherit nothing from her except what remains after her heirs have received their shares. And if she is killed, then her blood-money goes among her heirs, and they are the ones entitled to retaliation against her killer."]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2647}]},{"num":6875,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال:","كان رسول اللّٰه ﷺ يقوّم دية الخطأ على أهل القرى أربعمائة دينار، أو عدلها من الورق، ويقوّمها على أثمان الإبل؛ إذا غلت رفع في قيمتها، وإذا هاجت رخصاً نقص من قيمتها.","وبلغت على عهد رسول اللّٰه ﷺ ما بين أربعمائة دينار إلى ثمانمائة دينار، وعدلها من الورق ثمانية آلاف درهم.","وقضى رسول اللّٰه ﷺ على أهل البقر مائتي بقرة، ومن كان دية عقله في الشاء فألفي شاة.","وقضى رسول اللّٰه ﷺ أن العقل ميراث بين ورثة القتيل على قرابتهم، فما فضل فللعصبة.","وقضى رسول اللّٰه ﷺ في الأنف إذا جدع الدية كاملة، وإن جدعت ثندوته فنصف العقل: خمسون من الإبل، أو عدلها من الذهب أو الورق، أو مائة بقرة، أو ألف شاة.","وفي اليد إذا قطعت نصف العقل.","وفي الرجل نصف العقل.","وفي المأمومة ثلث العقل: ثلاث وثلاثون من الإبل وثلث، أو قيمتها من الذهب أو الورق أو البقر أو الشاء.","والجائفة مثل ذلك.","وفي الأصابع في كل إصبع عشر من الإبل، وفي الأسنان في كل سن خمس من الإبل.","وقضى رسول اللّٰه ﷺ أن عقل المرأة بين عصبتها من كانوا، لا يرثون منها شيئًا إلا ما فضل عن ورثتها، وإن قتلت فعقلها بين ورثتها، وهم يقتلون قاتلهم.","وقال رسول اللّٰه ﷺ:","«لَيْسَ لِلْقَاتِلِ شَيْءٌ، وَإِنْ لَمْ يَكُنْ لَهُ وَارِثٌ فَوَارِثُهُ أَقْرَبُ النَّاسِ إِلَيْهِ، وَلَا يَرِثُ الْقَاتِلُ شَيْئًا».","قال محمد:","هذا كله حدثني به سليمان بن موسى، عن عمرو بن شعيب، عن أبيه، عن جده، عن النبي ﷺ.","قال أبو داود:","محمد بن راشد من أهل دمشق، هرب إلى البصرة من القتل."],"takhrij":"حسن: رواه أبو داود (٤٥٦٤)، والبيهقي (٦/٢٢٠)، واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ديات الأعضاء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4564) and al-Bayhaqī (6/220). This is the wording of Abū Dāwūd.","chapter_en":"The blood-money for body parts","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb reported from his father, from his grandfather: The Messenger of Allah ﷺ used to assess the blood-money for accidental killing for the people of settled towns at four hundred dinars, or its equivalent in silver. He assessed it according to the market value of camels: when camels became expensive, he increased the amount, and when their prices fell, he reduced it. During the lifetime of the Messenger of Allah ﷺ, it ranged from four hundred dinars to eight hundred dinars, with its equivalent in silver being eight thousand dirhams.","He ruled that for people whose wealth consisted of cattle, the blood-money was two hundred cows, and for those whose wealth consisted of sheep, two thousand sheep. He ruled that blood-money is inherited among the heirs of the slain person according to their degrees of kinship, and whatever remains goes to the agnatic relatives. He ruled that if the nose is completely cut off, the full blood-money is due. If only the soft end of the nose is severed, half the blood-money is due: fifty camels, or their equivalent in gold or silver, or one hundred cows, or one thousand sheep.","For a severed hand, half the blood-money is due. For one leg, half the blood-money is due. For a head wound reaching the membrane surrounding the brain, one-third of the blood-money is due: thirty-three and one-third camels, or their equivalent in gold, silver, cattle, or sheep. A penetrating wound into the body cavity carries the same amount. For each finger, ten camels are due, and for each tooth, five camels. The Messenger of Allah ﷺ also ruled that a woman’s blood-money liability is borne by her agnatic relatives, whoever they may be. They do not inherit from her except what remains after her heirs have received their shares. If she is killed, her blood-money belongs to her heirs, and they have the right of retaliation against her killer.","The Messenger of Allah ﷺ also said: “The killer receives nothing. If the deceased has no heir, then his heir is the closest person to him, and the killer inherits nothing.” Muḥammad said: “Sulaimān ibn Mūsā narrated all of this to me from ʿAmr ibn Shuʿayb, from his father, from his grandfather, from the Prophet ﷺ.” Abū Dāwūd said: “Muḥammad ibn Rāshid was from the people of Damascus and fled to Baṣrah because of a killing.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4564},{"key":"البیہقی","label":"البيهقي","number":6}]},{"num":6876,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول اللّٰه ﷺ قضى في العين العوراء السادة لمكانها إذا طُمست بثلث ديتها، وفي اليد الشلاء إذا قطعت بثلث ديتها، وفي السن السوداء إذا نُزعت بثلث ديتها. حسن: رواه النسائي (٤٨٤٠) وأبو داود (٤٥٦٧)."],"takhrij":"","grade":"","chapter_ar":"باب دية العين العوراء، واليد الشلاء، والسن السوداء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasai (4840) and Abu Dawud (4567).","chapter_en":"The blood-money for a blind eye, a paralyzed hand, and a blackened tooth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ ruled that for the blind eye which remains in place, if it is destroyed, one-third of its blood-money is due. For a paralyzed hand, if it is cut off, one-third of its blood-money is due. And for a blackened tooth, if it is removed, one-third of its blood-money is due."]}},"tuhfa":{},"refs":[]},{"num":6877,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن النبي ﷺ قال: (( في المواضح خمس))."],"takhrij":"حسن: رواه أبو داود (٤٥٦٦) والترمذي (١٣٩٠) وحسّنه، والنسائي (٤٨٥٢) وابن ماجه (٢٦٥٥).","grade":"حسن","chapter_ar":"باب ما جاء في الموضحة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4566), al-Tirmidhi (1390), who graded it sound, al-Nasai (4852), and Ibn Majah (2655).","chapter_en":"What has come regarding the wound that exposes the bone","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Prophet ﷺ said: “For the wound that exposes the bone, there are five.”"]},"buhuth":{"ar":["خمس من الإبل.","والموضحة هي الشجة التي توضح العظم - أي تظهره. وهي في الغالب ما تكون في الوجه والرأس."],"en":["That means five camels.","A muwaddihah is a head or facial wound that exposes the bone, meaning it makes it visible. It is usually found on the face or head."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4566},{"key":"tirmidhi","label":"الترمذي","number":1390},{"key":"nasai","label":"النسائي","number":4852},{"key":"ibnmajah","label":"ابن ماجه","number":2655}]},{"num":6878,"demo":false,"sanad":"","matn":["عن ابن عباس، عن النبي ﷺ قال: (( هذه وهذه سواء ))، يعني الخنصر والإبهام. وفي رواية: (( الأصابع سواء، والأسنان سواء، الثنية والضرس سواء، هذه وهذه سواء )). صحيح: رواه البخاري (٦٨٩٥). ورواه أبو داود (٤٥٥٩) وابن الجارود (٧٨٣)."],"takhrij":"","grade":"","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6895). It was also narrated by Abu Dawud (4559) and Ibn al-Jarud (783), and in that wording it says: “The fingers are equal.”","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Ibn Abbas narrated from the Prophet ﷺ that he said: “This and this are equal,” meaning the little finger and the thumb are equal. “The teeth are equal as well; the front tooth and the molar are equal. This and this are equal.”"]}},"tuhfa":{},"refs":[]},{"num":6879,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس قال: قال رسول اللّٰه ﷺ: (( دية الأصابع اليدين والرجلين","سواء. عشرة من الإبل لكل أصبع ))."],"takhrij":"صحيح: رواه الترمذي (١٣٩١) واللفظ له، وأبو داود (٤٥٦٠،٤٥٦١) والنسائي (٤٨٤٩) وابن","grade":"صحيح","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (1391), and this is his wording, as well as Abu Dawud (4560, 4561), al-Nasai (4849), and Ibn al-Jarud (780).","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abdullah ibn Abbas said: The Messenger of Allah ﷺ said: “The blood-money for the fingers of the hands and feet is equal: ten camels for each finger.”"]},"buhuth":{"ar":["الجارود (٧٨٠)."]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":1391},{"key":"abudawud","label":"أبو داود","number":4560},{"key":"nasai","label":"النسائي","number":4849}]},{"num":6880,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن النبي ﷺ قال في خطبته - وهو مسند ظهره إلى الكعبة - ( في الأصابع عشر عشر))."],"takhrij":"حسن: رواه أبو داود (٤٥٦٢) وابن ماجه (٢٦٥٣) والنسائي (٤٨٥٠) وأحمد (٧٠١٣) والدار قطني","grade":"حسن","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4562), Ibn Majah (2653), al-Nasai (4850), Ahmad (7013), and al-Daraqutni (3/210).","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Prophet ﷺ said in his sermon, while leaning his back against the Kaʿbah: “For the fingers, ten each.”"]},"buhuth":{"ar":["(٢١٠/٣)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4562},{"key":"ibnmajah","label":"ابن ماجه","number":2653},{"key":"nasai","label":"النسائي","number":4850},{"key":"ahmad","label":"مسند الإمام أحمد","number":7013,"n":7013}]},{"num":6881,"demo":false,"sanad":"","matn":["عن أبي موسى الأشعري، عن النبي ﷺ قال: (( الأصابع سواء، عشر عشر من الإبل )). حسن: رواه أبو داود (٤٥٥٧)، وأحمد (١٩٥٥٠)، والدارقطني (٣/٢١١)، والدارمي (٢٤١٤)، وصحّحه ابن حبان (٦٠١٣)."],"takhrij":"","grade":"","chapter_ar":"باب دية الأصابع","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4557), Ahmad (19550), al-Daraqutni (3/211), and al-Darimi (2414). It was authenticated by Ibn Hibban (6013).","chapter_en":"The blood-money for fingers","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abu Musa al-Ashari narrated from the Prophet ﷺ that he said: “The fingers are equal: ten camels for each one.”"]}},"tuhfa":{},"refs":[]},{"num":6882,"demo":false,"sanad":"","matn":["عن ابن عباس قال: قال رسول اللّٰه ﷺ: (( الأسنان سواء، والأصابع سواء )). صحيح: رواه أبو داود (٤٥٦٠)، وأحمد (٢٦٢٤)، والبيهقي (٨/٩٠). ورواه ابن ماجه (٢٦٥١) وفيه: (( قضى النبي ﷺ في السن خمساً من الإبل ))."],"takhrij":"","grade":"","chapter_ar":"باب ما جاء في دية الأسنان","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4560), Ahmad (2624), and al-Bayhaqi (8/90).","chapter_en":"What has come regarding the blood-money for teeth","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Ibn Abbas said: The Messenger of Allah ﷺ said: “The teeth are equal, and the fingers are equal.”"]},"buhuth":{"en":["Ibn Majah (2651) also narrated it with the wording: “The Prophet ﷺ ruled that for a tooth there are five camels.”"]}},"tuhfa":{},"refs":[]},{"num":6883,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عمرو أن رسول اللّٰه ﷺ خطب يوم فتح مكة، فكبّر ثلاثا ثم قال: (( لا إله إلا اللّٰه وحده، صدق وعده، ونصر عبده، وهزم الأحزاب وحده، ألا إن كل مأثرةٍ كانت في الجاهلية تذكر وتُدعى من دم، أو مال تحت قدميَّ، إلا ماكان من سقاية الحاج، وسدانة البيت)). ثم قال: (( ألا إن دية الخطأ شبه العمد ما كان بالسوط والعصا مائة من الإبل: منها أربعون في بطونها أولادها ))."],"takhrij":"حسن: رواه أبو داود (٤٥٤٧) وابن ماجه (٢٦٢٧) وابن الجارود (٧٧٣) وصحّحه ابن حبان","grade":"حسن","chapter_ar":"باب السوط والعصا خطأ شبه العمد","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4547), Ibn Majah (2627), and Ibn al-Jarud (773), and authenticated by Ibn Hibban (6011).","chapter_en":"Killing with a whip or a stick is quasi-intentional mistaken killing","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Abdullah ibn Amr reported that the Messenger of Allah ﷺ delivered a sermon on the day of the conquest of Makkah. He said the takbir three times, then said: “There is no god but Allah alone. He fulfilled His promise, gave victory to His servant, and defeated the confederates alone. Indeed, every claim of distinction from the pre-Islamic period, whether in blood or wealth, is beneath my feet, except the giving of water to the pilgrims and the custodianship of the House.” Then he said: “Indeed, the blood-money for quasi-intentional mistaken killing, when done with a whip or a stick, is one hundred camels, forty of which are pregnant.”"]},"buhuth":{"ar":["(٦٠١١)."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4547},{"key":"ibnmajah","label":"ابن ماجه","number":2627},{"key":"ابن_الجارود","label":"ابن الجارود","number":773}]},{"num":6884,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده أن رسول اللّٰه ﷺ قضى أن من قتل خطأ فديته مائة من الإبل: ثلاثون بنت مخاض، وثلاثون بنت لبون، وثلاثون حقة، وعشر بنو لبون ذكر."],"takhrij":"حسن: رواه أبو داود (٤٥٤١) وابن ماجه ( ٢٦٣٠) والدار قطني (٩٥ /٣) واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب دية الخطأ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4541), Ibn Majah (2630), and al-Daraqutni (3/95). This wording is from Abu Dawud.","chapter_en":"The blood-money for accidental killing","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ ruled that whoever kills by mistake, his blood-money is one hundred camels: thirty bint makhad, thirty bint labun, thirty hiqqah, and ten male banu labun."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4541},{"key":"ibnmajah","label":"ابن ماجه","number":2630},{"key":"الدار_قطنی","label":"الدار قطني","number":95}]},{"num":6885,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده قال: كانت قيمة الدية في عهد رسول اللّٰه ﷺ ثمانمائة دينار، أو ثمانية آلاف درهم، ودية أهل الكتاب يومئذ النصف من دية المسلمين. قال: فكان ذلك كذلك حتى استخلف عمر فقام خطيباً فقال: ألا إن الإبل قد غلتْ، ففرضها عمر على أهل الذهب ألف دينار، وعلى أهل الورق اثني عشر ألف درهم، وعلى أهل البقر مائتي بقرة، وعلى أهل الشاء ألفي شاة، وعلى أهل الحلل مائتي حلة، قال: وترك دية أهل الذمة لم يرفعها فيما رفع من الدية."],"takhrij":"حسن: رواه ابو داود ( ٤٥٤٢).","grade":"حسن","chapter_ar":"باب دية الخطأ","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4542).","chapter_en":"The blood-money for accidental killing","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, who said: The value of the blood-money during the time of the Messenger of Allah ﷺ was eight hundred dinars or eight thousand dirhams, and the blood-money of the People of the Book at that time was half that of the Muslims. This remained so until Umar became caliph. Then he stood and addressed the people, saying: “Indeed, camels have become expensive.” So Umar fixed it for the people of gold at one thousand dinars, for the people of silver at twelve thousand dirhams, for the people of cattle at two hundred cows, for the people of sheep at two thousand sheep, and for the people of garments at two hundred garments. He left the blood-money of the protected non-Muslims unchanged and did not raise it as he raised the blood-money."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"ابو داود","number":4542}]},{"num":6886,"demo":false,"sanad":"","matn":["عن عمرو بن شعيب، عن أبيه، عن جده، قال: قال رسول اللّٰه ﷺ (( المسلمون تتكافأ دماؤهم: يسعى بذمتهم أدناهم، ويجير عليه أقصاهم، وهم يد على من سواهم، يرد مشدهم على مُضْعفهم، ومتسريهم على قاعدهم، لا يُقتل مؤمن بكافر، ولا ذو عهد في عهده ))","وفي رواية: (( دية عقل الكافر نصف دية عقل المؤمن ))"],"takhrij":"حسن: رواه أبو داود (٢٧٥١) والترمذي (١٤١٣) وحسّنه، والنسائي (٤٨٠٦) والرواية الثانية عند الترمذي.","grade":"حسن","chapter_ar":"باب دية أهل الذمة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (2751), al-Tirmidhi (1413), who graded it sound, and al-Nasai (4806). The second narration is in al-Tirmidhi.","chapter_en":"The blood-money of the protected non-Muslims","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["Amr ibn Shuayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “The blood of the Muslims is equal. The lowest among them may grant protection on behalf of them all, and the farthest among them may guarantee protection. They are united against others. Those with quick mounts should return to those with slow mounts, and those who go out with a detachment should return to those who remain stationed. A believer is not killed in retaliation for a disbeliever, nor one under covenant while he remains under his covenant.”","In another narration: “The blood-money of a disbeliever is half the blood-money of a believer.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":2751},{"key":"tirmidhi","label":"الترمذي","number":1413},{"key":"nasai","label":"النسائي","number":4806}]},{"num":6887,"demo":false,"sanad":"","matn":["عن عائشة، أن رسول اللّٰه ﷺ بعث أبا جهم بن حذيفة مصدقا، فلاجَّه رجل في صدقته، فضربه أبو جهم، فشجَّه، فأتوا النبي ﷺ فقالوا: القودَ يا رسول الله ﷺ! فقال النبي ﷺ: (( لكم","كذا وكذا)) فلم يرضوا، فقال: (( لكم كذا وكذا)) فرضوا، فقال النبي ﷺ: (( إني خاطب العشية على الناس ومخبرهم برضاكم؟ )) قالوا: نعم. فخطب النبي ﷺ قال: (( إن هؤلاء الليثيين أتوني يريدون القود، فعرضت عليهم كذا وكذا فرضوا، أرضيتم؟ )) قالوا: لا. فهم بهم المهاجرون، فأمر النبي ﷺ أن يكفوا عنهم، فكفوا، ثم دعاهم فزادهم، فقال: (( أرضيتم؟ )) قالوا: نعم، قال: (( إني خاطب على الناس ومخبرهم برضاكم)) قالوا: نعم، فخطب النبي ﷺ فقال: (( أرضيتم؟ )) قالوا: نعم."],"takhrij":"صحيح: رواه أبو داود (٤٥٣٤) والنسائي (٤٧٧٨) وابن ماجه (٢٦٣٨) وصحّحه ابن حبان (٤٤٨٧).","grade":"صحيح","chapter_ar":"باب حثِّ الإمام على قبول الدية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4534), al-Nasai (4778), Ibn Majah (2638), and authenticated by Ibn Hibban (4487).","chapter_en":"The ruler’s encouragement to accept blood-money","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["ʿA’ishah reported that the Messenger of Allah ﷺ sent Abu Jahm ibn Hudhayfah as a collector. A man disputed with him over his due, so Abu Jahm struck him and wounded his head. They came to the Prophet ﷺ and said: “Retaliation, O Messenger of Allah ﷺ.” The Prophet ﷺ said: “You will have such-and-such,” but they were not satisfied. Then he said: “You will have such-and-such,” and they were satisfied. Then the Prophet ﷺ said: “I will address the people this evening and inform them of your acceptance. Is that agreeable to you?” They said: “Yes.” So the Prophet ﷺ addressed the people and said: “These people from Layth came to me wanting retaliation, and I offered them such-and-such and they accepted. Are you satisfied?” They said: “No.” The Emigrants moved toward them, but the Prophet ﷺ ordered them to leave them alone, so they stopped. Then he called them again and increased the offer to them, and said: “Are you satisfied?” They said: “Yes.” He said: “I will address the people and inform them of your acceptance.” They said: “Yes.” So he addressed the people and said: “Are you satisfied?” They said: “Yes.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4534},{"key":"nasai","label":"النسائي","number":4778},{"key":"ibnmajah","label":"ابن ماجه","number":2638},{"key":"صححہ_ابن_حبان","label":"صحّحه ابن حبان","number":4487}]},{"num":6888,"demo":false,"sanad":"","matn":["عن أبي رِمثة قال: انطلقت مع أبي نحو النبي ﷺ، فقال رسول اللّٰه ﷺ لأبي: (( ابنك هذا؟ )) قال: إي ورب الكعبة. قال: (( حقاً؟ )) قال: أشهد به. فتبسم رسول اللّٰه ﷺ ضاحكاً من ثَبَت شبهي في أبي، ومن حلف أبي عليّ. ثم قال: (( أما إنه لا يجني عليك ولا تجني عليه )) وقرأ: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ﴾ [فاطر: ١٨]. صحيح: رواه أبو داود (٤٤٩٥)، والنسائي (١٥٧٢)، والترمذي (٢٨١٢)، وأحمد (٧١٠٩). واللفظ لأبي داود."],"takhrij":"","grade":"","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (4495), al-Nasai (1572), al-Tirmidhi (2812), and Ahmad (7109). This wording is from Abu Dawud.","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Abu Rimthah said: I went with my father to the Prophet ﷺ. The Messenger of Allah ﷺ said to my father: “Is this your son?” He said: “Yes, by the Lord of the Kaʿbah.” He said: “Truly?” He said: “I bear witness to it.” The Messenger of Allah ﷺ smiled, laughing at my resemblance to my father and at my father’s oath concerning me. Then he said: “Indeed, he does not bear your crime, nor do you bear his crime.” Then he recited: “No bearer of burdens shall bear the burden of another.” [Fatir: 18]"]}},"tuhfa":{},"refs":[]},{"num":6889,"demo":false,"sanad":"","matn":["عن الخشخاش العنبري، قال: أتيت النبي ﷺ ومعي ابن لي، قال: فقال: (( ابنك هذا؟ )) قال: قلت: نعم، قال: (( لا يجني عليك، ولا تجني عليه ))."],"takhrij":"صحيح: رواه ابن ماجه (٢٦٧١) وأحمد (١٩٠٣١).","grade":"صحيح","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2671) and Ahmad (19031).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Al-Khashkhash al-Anbari said: I came to the Prophet ﷺ with a son of mine. He said: “Is this your son?” I said: “Yes.” He said: “He does not bear your crime, and you do not bear his.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2671},{"key":"ahmad","label":"مسند الإمام أحمد","number":19031,"n":19031}]},{"num":6890,"demo":false,"sanad":"","matn":["عن طارق المحاربي أن رجلاً قال: يا رسول اللّٰه ﷺ هؤلاء بنو ثعلبة الذين قتلوا فلانا في الجاهلية فخذ لنا بثأرنا. فرفع يديه حتى رأيت بياض إبطيه وهو يقول: (( لا تجني أم على ولد مرتين))."],"takhrij":"حسن: رواه النسائي (٤٨٣٩) وابن ماجه (٢٦٧٠) واللفظ لهما وصحّحه ابن حبان (٦٥٦٢).","grade":"حسن","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasai (4839) and Ibn Majah (2670), and authenticated by Ibn Hibban (6562).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Tariq al-Muharibi reported that a man said: “O Messenger of Allah ﷺ, these are Banu Thaʿlabah who killed so-and-so in the pre-Islamic period, so take revenge for us.” The Prophet ﷺ raised his hands until I could see the whiteness of his armpits and said: “A mother is not held liable for her child twice.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4839},{"key":"ibnmajah","label":"ابن ماجه","number":2670},{"key":"اللفظ_لہما_وصححہ_ابن_حبان","label":"اللفظ لهما وصحّحه ابن حبان","number":6562}]},{"num":6891,"demo":false,"sanad":"","matn":["عن أسامة بن شريك قال: قال رسول اللّٰه ﷺ: (( لا تجني نفس على أخرى))"],"takhrij":"حسن: رواه ابن ماجه (٢٦٧٢).","grade":"حسن","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Ibn Majah (2672).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Usamah ibn Sharik said: The Messenger of Allah ﷺ said: “No soul bears the crime of another.”"]}},"tuhfa":{},"refs":[{"key":"ibnmajah","label":"ابن ماجه","number":2672}]},{"num":6892,"demo":false,"sanad":"","matn":["عن ثعلبة بن زهدم اليربوعي قال: كان رسول اللّٰه ﷺ يخطب في أناس من الأنصار.","فقالوا: يا رسول اللّٰه ﷺ هؤلاء بنو ثعلبة بن يربوع قتلوا فلانا في الجاهلية فقال النبي ﷺ وهتف بصوته:","(( ألا لا تجني نفس على الأخرى ))"],"takhrij":"صحيح: رواه النسائي (٤٨٣٣)، وأحمد (١٦٦١٣).","grade":"صحيح","chapter_ar":"باب لا يؤخذ أحدّ من جناية أحد ولوكان من أبيه أو أخيه","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Nasai (4833) and Ahmad (16613).","chapter_en":"No one is taken for the crime of another, even if it is his father or brother","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Thaʿlabah ibn Zahdam al-Yarbuʿi said: The Messenger of Allah ﷺ was delivering a sermon among some of the Ansar. They said: “O Messenger of Allah ﷺ, these are Banu Thaʿlabah ibn Yarbuʿ who killed so-and-so in the pre-Islamic period.” The Prophet ﷺ raised his voice and said: “Indeed, no soul bears the crime of another.”"]}},"tuhfa":{},"refs":[{"key":"nasai","label":"النسائي","number":4833},{"key":"ahmad","label":"مسند الإمام أحمد","number":16613,"n":16613}]},{"num":6893,"demo":false,"sanad":"","matn":["عن عمران بن الحصين:","أن غلامًا لأناس فقراء قطع أذن غلام لأناس أغنياء، فأتى أهله النبي ﷺ فقالوا:","يا رسول الله ﷺ، إنا أناس فقراء.","فلم يجعل عليه شيئًا."],"takhrij":"صحيح: رواه أبو داود (٤٥٩٠)، والنسائي (٤٧٥١).","grade":"صحيح","chapter_ar":"باب التماس إسقاط الدية من الغلام الصغير إذا كان أهله من الفقراء","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4590) and al-Nasā’ī (4751).","chapter_en":"Seeking to waive the blood-money for a small boy when his family is poor","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["ʿImrān ibn al-Ḥuṣayn reported: A young boy belonging to some poor people cut off the ear of a boy belonging to some wealthy people. His family came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, we are poor people.” So he imposed nothing upon him."]},"buhuth":{"ar":["والغلام معناه الولد الصغير، والظاهر من السياق أنه كان حرًّا، وجنايته كانت خطأ، وكانت عاقلته فقراء. وكذلك الغلام المجني عليه كان حرًّا؛ لأنه لو كان عبدًا لم يكن لاعتذار أهله بالفقر معنى، لأن العاقلة لا تحمل عبدًا، كما لا تحمل عمدًا ولا اعترافًا، في قول أكثر أهل العلم كما قال الخطابي.","وقد فهم النسائي وأبو داود أن المراد بالغلام العبد، فلو كان هذا صحيحًا فإن الغلام المملوك إذا جنى على عبد أو حر فجنايته في رقبته، في قول عامة الفقهاء."],"en":["The word ghulām means a young boy. The apparent meaning of the context is that he was free and that his offense was accidental, while his ʿāqilah were poor. The injured boy likewise appears to have been free; had he been a slave, there would have been no point in the family pleading poverty, because the ʿāqilah does not bear liability for injury to a slave, nor for an intentional offense, nor for liability established by confession, according to most scholars, as al-Khaṭṭābī stated.","Al-Nasā’ī and Abū Dāwūd understood ghulām here as meaning a slave. If that understanding is correct, then when an enslaved boy injures a slave or a free person, the liability is attached to his person, according to the majority of jurists."]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":4590},{"key":"nasai","label":"النسائي","number":4751}]},{"num":6894,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول اللّٰه ﷺ قال: (( جرح العجماء جبار، والبئر جبار، والمعدن جبار، وفي الركاز الخمس ))."],"takhrij":"متفق عليه: رواه مالك (٤٢)، والبخاري (٦٩١٢)، ومسلم (١٧١٠).","grade":"متفق عليه","chapter_ar":"باب جرح العجماء جبار","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (42), al-Bukhari (6912), and Muslim (1710).","chapter_en":"Injury caused by an animal is without liability","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The injury caused by an animal is without liability, a well is without liability, a mine is without liability, and one-fifth is due on buried treasure.”"]},"buhuth":{"ar":["والعجماء: البهيمة، وسميت العجماء لأنها لا تتكلم. وقوله: جبار أي هدر، لا دية فيه.","وقوله: البئر جبار: أي أن الإنسان لو حفر بئراً في مِلكه أو في موات فوقع فيها إنسان فلا ضمان عليه."],"en":["The word al-ajma’ means an animal, and it is called that because it does not speak. The phrase jubar means it is not subject to compensation, with no blood-money due for it.","The phrase “a well is without liability” means that if a person digs a well on his own property or in unused land and someone falls into it, he is not liable."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":42},{"key":"bukhari","label":"البخاري","number":6912},{"key":"muslim","label":"مسلم","number":1710}]},{"num":6895,"demo":false,"sanad":"","matn":["عن عمران بن الحصين:","أن رجلًا عض يد رجل، فنزع يده من فمه فوقعت ثنيتاه، فاختصموا إلى النبي ﷺ فقال:","«يَعَضُّ أَحَدُكُمْ أَخَاهُ كَمَا يَعَضُّ الْفَحْلُ؟ لَا دِيَةَ لَهُ».","وفي لفظ: فرفع إلى النبي ﷺ فأبطله، وقال:","«أَرَدْتَ أَنْ تَأْكُلَ لَحْمَهُ؟!»"],"takhrij":"صحيح: رواه البخاري (٦٨٩٢)، ومسلم (١٦٧٣/١٨). واللفظ الثاني رواه مسلم من وجه آخر.","grade":"صحيح","chapter_ar":"باب إذا عض رجلا فوقعت ثناياه فلادية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6892) and Muslim (1673/18). The second wording was narrated by Muslim through another route.","chapter_en":"If a man bites another man and his front teeth fall out, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported: A man bit another man’s hand. The other man pulled his hand from the biter’s mouth, causing the biter’s two front teeth to fall out. They brought their dispute before the Prophet ﷺ, who said: “Would one of you bite his brother as a stallion bites? He is entitled to no blood-money.”","In another wording, the matter was brought before the Prophet ﷺ, and he dismissed the claim and said: “Did you intend to eat his flesh?!”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6892},{"key":"muslim","label":"مسلم","number":1673}]},{"num":6896,"demo":false,"sanad":"","matn":["عن عمران بن الحصين:","أن رجلًا عض يد رجل، فانتزع يده، فسقطت ثنيته أو ثناياه، فاستعدى رسول اللّٰه ﷺ.","فقال رسول اللّٰه ﷺ:","«مَا تَأْمُرُنِي؟ تَأْمُرُنِي أَنْ آمُرَهُ أَنْ يَدَعَ يَدَهُ فِي فِيكَ تَقْضَمُهَا كَمَا يَقْضَمُ الْفَحْلُ؟! ادْفَعْ يَدَكَ حَتَّى يَعَضَّهَا ثُمَّ انْتَزِعْهَا»."],"takhrij":"صحيح: رواه مسلم (١٦٧٣/٢١).","grade":"صحيح","chapter_ar":"باب إذا عض رجلا فوقعت ثناياه فلادية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1673/21).","chapter_en":"If a man bites another man and his front teeth fall out, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn reported: A man bit another man’s hand. The man pulled his hand away, causing one or more of the biter’s front teeth to fall out. The biter then sought judgment from the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said: “What do you want me to order? Do you want me to order him to leave his hand in your mouth so that you may bite it as a stallion bites? Put your hand forward until he bites it, then pull it away.”"]},"buhuth":{"ar":["وأشار الحافظ إلى هذه الرواية في الفتح (١٢/٢٢١)، ثم قال: وعند أبي نعيم في المستخرج من الوجه الذي أخرجه مسلم:","«إِنْ شِئْتَ أَمَرْنَاهُ فَعَضَّ يَدَكَ ثُمَّ انْتَزَعْهَا أَنْتَ».","والأمر الوارد في رواية مسلم على التخيير وليس على الإلزام، ثم أهدر النبي ﷺ ثنيته."],"en":["Al-Ḥāfiẓ referred to this narration in Fatḥ al-Bārī (12/221) and stated that Abū Nuʿaym’s al-Mustakhraj, through the same route as Muslim, has the wording:","“If you wish, we will order him to let you bite his hand, then you may pull it away yourself.”","The command in Muslim’s narration indicates an option, not an obligation. The Prophet ﷺ then ruled that no compensation was due for the biter’s tooth."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1673}]},{"num":6897,"demo":false,"sanad":"","matn":["عن يعلى بن أمية، قال: أتى النبي ﷺ رجل، وقد عضّ يد رجل، فانتزع يده فسقطت ثنيتاه (يعني الذي عضّه) قال: فأبطلها النبي ﷺ، وقال: (( أردْت أن تقضمه كما يقضم الفحل؟ ))."],"takhrij":"متفق عليه: رواه البخاري (٦٨٩٣) ومسلم (٢٢:١٦٧٤). واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب إذا عض رجلا فوقعت ثناياه فلادية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6893) and Muslim (22:1674). This wording is from Muslim.","chapter_en":"If a man bites another man and his front teeth fall out, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Yaʿla ibn Umayyah reported that a man came to the Prophet ﷺ after he had bitten another man’s hand, and when the other man pulled his hand away, the biter’s two front teeth fell out. The Prophet ﷺ dismissed his claim and said: “Did you want to chew him as a stallion chews?”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6893},{"key":"muslim","label":"مسلم","number":22}]},{"num":6898,"demo":false,"sanad":"","matn":["عن أنس بن مالك، أن رجلاً اطلع في بعض حُجر النبي ﷺ فقام إليه بمشقص - أو مشاقص - ، وجعل يختِله ليطعنه."],"takhrij":"متفق عليه: رواه البخاري (٦٩٠٠) ومسلم (٢١٥٨).","grade":"متفق عليه","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6900) and Muslim (2158).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Anas ibn Malik reported that a man peeped into one of the rooms of the Prophet ﷺ, so the Prophet ﷺ got up toward him with a broad arrowhead, trying to catch him off guard in order to stab him."]},"buhuth":{"ar":["قوله: “مشاقص “ جمع مشقص وهو نصل عريض للسهم. وقوله: “ويختله” بفتح أوله وكسر التاء أي يراوغه ويستغفله."],"en":["The word mashaqis is the plural of mishqas, which is a broad arrowhead. The phrase yakhtiluhu means he was trying to catch him by surprise and outmaneuver him."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6900},{"key":"muslim","label":"مسلم","number":2158}]},{"num":6899,"demo":false,"sanad":"","matn":["عن سهل بن سعد أخبره أن رجلاً اطّلع في جحر في باب رسول اللّٰه ﷺ، ومع رسول اللّٰه ﷺ مِدرى يحك به رأسه، فلما رآه رسول اللّٰه ﷺ قال: (( لو أعلم أنك تنتظرني لطعنت به في عينيك )). وقال رسول اللّٰه ﷺ: (( إنما جعل الإذن من قبل البصر )). متفق عليه: رواه البخاري (٦٩٠١) ومسلم (٢١٥٦). قوله: (( جحر )) أي الخرق. وقوله: (( إنما جعل الإذن )) أي أن الاستئذان مشروع مأمور به، وإنما جعل لئلا يقع البصر على الحرام، فلا يحل لأحد أن ينظر في جحر باب وغيره. وفي هذا الحديث جواز رمي عين المتطلع بشيء خفيف، فلو رماه ففقأها فلا ضمان عليه."],"takhrij":"","grade":"","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6901) and Muslim (2156).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Sahl ibn Saʿd reported that a man peeped through a hole in the door of the Messenger of Allah ﷺ while the Messenger of Allah ﷺ had a comb-like tool with which he was scratching his head. When the Messenger of Allah ﷺ saw him, he said: “Had I known that you were looking at me, I would have thrust this into your eyes.” The Messenger of Allah ﷺ also said: “Permission was only prescribed because of the gaze.”"]},"buhuth":{"en":["The word juhr means a hole or opening. The phrase “Permission was only prescribed” means that asking permission before entering was legislated in order to prevent unlawful looking. So it is not permissible for anyone to look through a door hole or any similar opening. This hadith also indicates that it is allowed to strike the eye of a peeper with something light, and if his eye is put out, there is no liability."]}},"tuhfa":{},"refs":[]},{"num":6900,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال أبو القاسم : (( لو أن امرءاً اطلع عليك بغير إذن فحذفته حصاة ففقأت عينه لم يكن عليك جناح))."],"takhrij":"صحيح: رواه البخاري (٦٩٠٢) ومسلم (٤٤:٢١٥٨). ورواه مسلم في الآداب (٤٤:٢١٥٨) من طريق آخر بلفظ: (( من اطلع في بيت قوم بغير إذنهم، فقد حلّ لهم أن يفقؤوا عينه ))","grade":"صحيح","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (6902) and Muslim (44:2158). Muslim also narrated through another chain in the Book of Manners: “Whoever looks into the house of people without their permission, it becomes lawful for them to put out his eye.”","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported that Abu al-Qasim said: “If a person were to look at you without permission and you threw a pebble at him and put out his eye, there would be no blame upon you.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6902},{"key":"muslim","label":"مسلم","number":44},{"key":"ورواہ_مسلم/الاداب","label":". ورواه مسلم في الآداب","number":44}]},{"num":6901,"demo":false,"sanad":"","matn":["عن أبي هريرة أن النبي ﷺ قال: (( إذا دخل البصر فلا إذن))."],"takhrij":"حسن: رواه أبو داود (٥١٧٣) والبخاري في الأدب المفرد (١٠٨٢) والبيهقي (٣٣٩/٨).","grade":"حسن","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Abu Dawud (5173), al-Bukhari in al-Adab al-Mufrad (1082), and al-Bayhaqi (8/339).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Once the gaze has entered, there is no permission.”"]}},"tuhfa":{},"refs":[{"key":"abudawud","label":"أبو داود","number":5173},{"key":"bukhari/الادب_المفرد","label":"البخاري في الأدب المفرد","number":1082},{"key":"البیہقی","label":"البيهقي","number":339},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":17660,"n":17818}]},{"num":6902,"demo":false,"sanad":"","matn":["عن أبي ذر قال: قال رسول اللّٰه ﷺ: (( من كشف ستراً فأدخل بصره في البيت قبل أن يؤذن له، فرأى عورة أهله، فقد أتى حداً لا يحل له أن يأتيه، لو أنه حين أدخل بصره استقبله رجل ففقأ عينيه ما عيّرت عليه. وإن مر الرجل على باب لا ستر له غير مغلق فنظر، فلا خطيئة عليه، إنما الخطيئة على أهل البيت))."],"takhrij":"حسن: رواه الترمذي (٢٧٠٧) وأحمد (٢١٣٥٩،٢١٥٧٢).","grade":"حسن","chapter_ar":"باب من اطلع في بيت قوم ففقؤوا عينه فلا دية له","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (2707) and Ahmad (21359, 21572).","chapter_en":"Whoever peeps into people’s house and they put out his eye, there is no blood-money for him","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في الديات","group_en":"Collection of reports regarding blood-money","part_no":32,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abu Dharr reported that the Messenger of Allah ﷺ said: “Whoever uncovers a curtain and looks into a house before being given permission, and sees the private part of its occupants, has committed a violation that is not lawful for him to commit. If a man were to confront him at that moment and put out his eyes, there would be no blame upon him. But if a man passes by a door that has no curtain and is not closed, and he looks in, then there is no sin upon him. The sin is only upon the people of the house.”"]},"buhuth":{"ar":["وقوله: (( أتى حداً )). أي يستحق أن يعزر، لأنه أتى أمراً منكراً، لا يحل له أن يأتيه.","وقوله: ما عيّرت عليه. وفي مسند أحمد: لهدرت: أي لا دية عليه."],"en":["The phrase “has committed a violation” means that he deserves disciplinary punishment, because he has committed a forbidden and reprehensible act.","The phrase “there would be no blame upon him” means there would be no liability or blood-money upon the one who injured him. In Musnad Ahmad the wording is: “his eye would be forfeit.”"]}},"tuhfa":{},"refs":[{"key":"tirmidhi","label":"الترمذي","number":2707},{"key":"ahmad","label":"مسند الإمام أحمد","number":21359,"n":21359}]},{"num":6903,"demo":false,"sanad":"","matn":["عن عبد اللّٰه بن عباس قال: إن أولَ قسامة كانت في الجاهلية لفينا بني هاشم، كان رجل من بني هاشم استأجره رجل من قريش من فخذٍ أخرى، فانطلق معه في إبله، فمرَّ رجلٌ به من بني هاشم قد انقطعت عروة جوالقه فقال: أغثني بعقال أشدُّ به عروة جوالقي لا تنفر الإبل. فأعطاه عقالا، فشد به عروة جوالقه ، فلما نزلوا عقلت الإبل إلا بعيرا واحدا، فقال الذى استأجره: ما شأن هذا البعير لم يعقل من بين الإبل؟ قال: ليس له عقال. قال: فأين عقاله؟ قال: فحذفه بعصا كان فيها أجلُه، فمرَّ به رجلٌ من أهل اليمن، فقال: أتشهد الموسم؟ قال: ما أشهد، وربما شهدته. قال هل أنت مبلغ عني رسالة مرةً من الدهر قال: نعم.","قال: فكنت إذا أنت شهدت الموسم فناد يا آل قريش، فإذا أجابوك، فناد يا آل بني هاشم. فإن أجابوك فسل عن أبي طالب، فأخبره أن فلانا قتلني فى عقال، ومات المستأجر، فلما قدم الذي استأجره أتاه أبو طالب فقال: ما فعل صاحبنا؟ قال: مرض، فأحسنتُ القيام عليه، فولِيتُ دفنه. قال: قد كان أهلَ ذاك منك. فمكث حيناً، ثم إن الرجل الذي أوصى إليه أن يُبلغ عنه وافى الموسم فقال: يا آل قريش. قالوا: هذه قريش. قال: يا آل بني هاشم. قالوا: هذه بنو هاشم. قال: أين أبو طالب؟ قالوا: هذا أبو طالب. قال: أمرني فلان أن أبلغك رسالة أن فلانا قتله في عقال. فأتاه أبو طالب فقال له: اختر منا إحدى ثلاث، إن شئت أن تؤدي مائة من الإبل، فإنك قتلت صاحبنا، وإن شئت حلف خمسون من قومك أنك لم تقتله، فإن أبيت قتلناك به، فأتى قومه، فقالوا: نحلف. فأتته امرأةٌ من بني هاشم كانت تحت رجل منهم قد ولدت له. فقالت: يا أبا طالب أُحِبُّ أن تجيز ابني هذا برجل من الخمسين ولا تُصبر يمينُه حيث تُصبر الأيمان. ففعل فأتاه رجل منهم فقال: يا أبا طالب ، أردتَ خمسين رجلا أن يحلفوا مكان مائة من الإبل ، يصيب كل رجل بعيران ، هذان بعيران فاقبلهما عني ولا تصبر يميني حيث تصبر الأيمان. فقبِلَهما، وجاء ثمانيةٌ وأربعون فحلفوا. قال ابن عباس: فوالذي نفسى بيده، ما حال الحول ومن الثمانية وأربعين عينٌ تطرِفُ."],"takhrij":"صحيح: رواه البخاري (٣٨٤٥)","grade":"صحيح","chapter_ar":"باب القسامة في الجاهلية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bukhari (3845).","chapter_en":"Al-qasamah in the pre-Islamic period","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Abdullah ibn Abbas said: The first qasamah in the pre-Islamic period among us, Banu Hashim, was that a man from Banu Hashim had been hired by a man from Quraysh, from another clan, and he went off with him among his camels. Then a man from Banu Hashim passed by him whose saddlebag strap had snapped, and he said: “Help me with a rope with which I may tie my saddlebag, so the camels do not scatter.” So he gave him a rope, and he tied his saddlebag with it. When they camped and hobbled the camels, one camel alone remained unhobbled. The man who had hired him said: “What is the matter with this camel that it alone has not been hobbled?” He replied: “It has no rope.” He said: “Where is its rope?” Then he struck him with a staff, and that was the cause of his death. A man from Yemen passed by him, and the injured man said: “Will you attend the pilgrimage season?” He said: “Usually I do not, though I may attend it.” He said: “Will you deliver a message for me at some point?” He said: “Yes.”","He said: “When you attend the pilgrimage season, call out: O Quraysh. When they answer you, call out: O Banu Hashim. When they answer you, ask for Abu Talib and tell him that so-and-so killed me over a rope.” Then the hired man died. When the man who had hired him returned, Abu Talib came to him and said: “What happened to our companion?” He said: “He became ill, so I took good care of him and handled his burial.” Abu Talib said: “You were fit to do that.” Some time passed, then the man to whom he had entrusted the message came during the pilgrimage season and called out: “O Quraysh.” They said: “This is Quraysh.” Then he called: “O Banu Hashim.” They said: “This is Banu Hashim.” He said: “Where is Abu Talib?” They said: “Here is Abu Talib.” He said: “So-and-so told me to convey a message to you: so-and-so killed me over a rope.”","Abu Talib then came to the accused and said: “Choose one of three options: either you pay one hundred camels, for you killed our companion; or fifty men from your people swear that you did not kill him; if you refuse, we will kill you in retaliation.” So he went to his people, and they said: “We will swear.” Then a woman from Banu Hashim came, married to one of those men and having borne him a child. She said: “O Abu Talib, I would like you to excuse my son from being one of the fifty and not make him swear where the oaths are sworn.” So he did. Then one of them came and said: “O Abu Talib, you wanted fifty men to swear in place of one hundred camels, which means each man’s share is two camels. Here are two camels, so accept them from me and do not make me swear where the oaths are sworn.” So he accepted them, and forty-eight men came and swore. Ibn Abbas said: By the One in whose hand is my soul, before a year had passed, not one eye among those forty-eight was still blinking."]},"intro_majmu":{"ar":["القسامة: لغةً: مصدر بمعنى القسم، أي اليمين. وشرعاً: هي الأيمان المكررة في دعوى القتل، وهي خمسون يميناً من خمسين رجلاً. والقسامة من طرق إثبات القتل أو نفيه إذا لم تتوفر وسائل الإثبات الأخرى، وهي ثابتة بالكتاب والسنة والإجماع. أما الكتاب فقوله تعالى: ﴿وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَمَنْ قُتِلَ مَظْلُومًا فَقَدْ جَعَلْنَا لِوَلِيِّهِ سُلْطَانًا﴾ [الإسراء: ٣٣]. ووكّل الله بيان هذا السلطان إلى النبي ﷺ، فبيّنه بأنه القسامة. وأما السنة فهي كثيرة كما سيأتي."],"en":["Al-qasamah in language means an oath. In legal usage, it means repeated oaths in a murder claim, namely fifty oaths from fifty men.","It is one of the legal methods for establishing or denying liability in a killing case when other means of proof are not available.","It is established by the Qur’an, the Sunnah, and consensus.","As for the Qur’an, Allah says: “Do not kill the soul which Allah has forbidden except with right, and whoever is killed wrongfully, We have given his heir authority.” [Al-Isra: 33]","Allah left the explanation of this authority to the Prophet ﷺ, and he explained that it includes al-qasamah.","As for the Sunnah, the reports on it are many, as will follow."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":3845}]},{"num":6904,"demo":false,"sanad":"","matn":["عن رجل من أصحاب النبي ﷺ من الأنصار، أن رسول اللّٰه ﷺ أقرّ القسامة على ما كانت عليه في الجاهلية. وزاد في رواية: وقضى بها رسول اللّٰه ﷺ بين ناس من الأنصار في قتيل ادعوه على اليهود."],"takhrij":"صحيح: رواه مسلم (١٦٧٠).","grade":"صحيح","chapter_ar":"باب ما جاء في إقرار النبي ﷺ القسامة على ما كانت عليه في الجاهلية","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by Muslim (1670).","chapter_en":"What has come regarding the Prophet ﷺ’s approval of al-qasamah as it existed in the pre-Islamic period","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ, from the Ansar, reported that the Messenger of Allah ﷺ confirmed al-qasamah upon the way it had been in the pre-Islamic period. In another narration it adds: The Messenger of Allah ﷺ judged by it between some men of the Ansar regarding a slain man whose killing they claimed against the Jews."]}},"tuhfa":{},"refs":[{"key":"muslim","label":"مسلم","number":1670}]},{"num":6905,"demo":false,"sanad":"","matn":["عن سهل بن أبي حثمة، أنه أخبره رجال من كبراء قومه: أن عبد اللّٰه بن سهل ومحيصة خرجا إلى خيبر من جهد أصابهم. فأُتي محيصة فأُخبر أن عبد اللّٰه بن سهل قد قُتل وطُرح في فقير بئر أو عين، فأتى يهود فقال: أنتم والله قتلتموه. فقالوا: والله ما قتلناه. فأقبل حتى قدم على قومه فذكر لهم ذلك. ثم أقبل هو وأخوه حويصة - وهو أكبر منه - وعبد الرحمن. فذهب محيصة ليتكلم، وهو الذي كان بخيبر، فقال له رسول اللّٰه ﷺ: (( كبر، كبر )) يريد السن. فتكلم حويصة، ثم تكلم محيصة. فقال رسول اللّٰه ﷺ: (( إما أن يدوا صاحبكم وإما أن يؤذنوا بحرب )). فكتب إليهم رسول اللّٰه ﷺ في ذلك، فكتبوا: إنا والله ما قتلناه. فقال رسول اللّٰه ﷺ لحويصة ومحيصة وعبد الرحمن: (( أتحلفون وتستحقون دم صاحبكم؟ )) فقالوا: لا. قال: (( أفتحلف لكم يهود؟ )) قالوا: ليسوا بمسلمين. فوداه رسول اللّٰه ﷺ من عنده، فبعث إليهم بمائة ناقة حتى أُدخلت عليهم الدار. قال سهل: لقد ركضتني منها ناقة حمراء. قال مالك: الفقير هو البئر."],"takhrij":"متفق عليه: رواه مالك (١)، والبخاري (٧١٩٢)، ومسلم (١٦٦٩/٦).","grade":"متفق عليه","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by Malik (1), al-Bukhari (7192), and Muslim (6:1669).","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Abi Hathmah reported that some of the elders of his people informed him that Abdullah ibn Sahl and Muhayyisah went out to Khaybar because of hardship that had befallen them. Then Muhayyisah was informed that Abdullah ibn Sahl had been killed and thrown into a pit or a well. He went to the Jews and said: “By Allah, you killed him.” They said: “By Allah, we did not kill him.” He returned to his people and informed them of that. Then he came with his brother Huwayyisah, who was older than him, and Abd al-Rahman. Muhayyisah, being the one who had been at Khaybar, moved to speak, but the Messenger of Allah ﷺ said to him: “Let the elder speak, let the elder speak,” meaning with respect to age. So Huwayyisah spoke, then Muhayyisah spoke.","The Messenger of Allah ﷺ then said: “Either they pay blood-money for your companion, or they are notified of war.” The Messenger of Allah ﷺ wrote to them about this, and they wrote back: “By Allah, we did not kill him.” So the Messenger of Allah ﷺ said to Huwayyisah, Muhayyisah, and Abd al-Rahman: “Will you swear and thereby deserve the blood of your companion?” They said: “No.” He said: “Then will the Jews swear for you?” They said: “They are not Muslims.” So the Messenger of Allah ﷺ paid his blood-money from his own side. He sent them one hundred she-camels that were brought into their yard. Sahl said: One red she-camel among them kicked me. Malik said: al-faqir means a well."]}},"tuhfa":{},"refs":[{"key":"malik","label":"مالك","number":1},{"key":"bukhari","label":"البخاري","number":7192},{"key":"muslim","label":"مسلم","number":1669}]},{"num":6906,"demo":false,"sanad":"","matn":["عن بُشير بن يسار مولى الأنصار، عن رافع بن خديج وسهل بن أبي حثمة أنهما حدثاه: أن عبد اللّٰه بن سهل ومحيصة بن مسعود أتيا خيبر، فتفرقا في النخل، فقُتل عبد اللّٰه بن سهل. فجاء عبد الرحمن بن سهل وحويصة ومحيصة ابنا مسعود إلى النبي ﷺ، فتكلموا في أمر صاحبهم. فبدأ عبد الرحمن، وكان أصغر القوم، فقال النبي ﷺ: (( كبر الكبر )). قال يحيى: يعني ليلي الكلام الأكبر. فتكلموا في أمر صاحبهم، فقال النبي ﷺ: (( أتستحقون قتيلكم - أو قال: صاحبكم - بأيمان خمسين منكم؟ )) قالوا: يا رسول الله ﷺ، أمر لم نره. قال: (( فتبرئكم يهود بأيمان خمسين منهم؟ )) قالوا: يا رسول الله ﷺ، قوم كفار. فوداه رسول اللّٰه ﷺ من قبله. قال سهل: فأدركت ناقة من تلك الإبل فدخلت مربداً فركضتني برجلها."],"takhrij":"متفق عليه: رواه البخاري (٦١٤٢، ٦١٤٣)، ومسلم (١٦٦٩/٢). واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6142, 6143) and Muslim (2:1669). This wording is from al-Bukhari.","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Bushayr ibn Yasar, the freedman of the Ansar, reported from Rafi ibn Khadij and Sahl ibn Abi Hathmah that Abdullah ibn Sahl and Muhayyisah ibn Masud came to Khaybar and then separated among the palm groves. Abdullah ibn Sahl was killed. Then Abd al-Rahman ibn Sahl, Huwayyisah, and Muhayyisah, the sons of Masud, came to the Prophet ﷺ and spoke regarding their companion. Abd al-Rahman began speaking, and he was the youngest of the group, so the Prophet ﷺ said: “Let the elder speak, let the elder speak.” Yahya said: This means the oldest should be the one to speak first.","Then they spoke regarding their companion, and the Prophet ﷺ said: “Will you establish your claim to your slain man,” or he said, “your companion,” “by fifty oaths from among you?” They said: “O Messenger of Allah ﷺ, this is something we did not witness.” He said: “Then the Jews will clear themselves by fifty oaths from among them.” They said: “O Messenger of Allah ﷺ, they are disbelieving people.” So the Messenger of Allah ﷺ paid the blood-money himself.","Sahl said: One she-camel from those camels caught up with me, entered an enclosure, and kicked me with its leg."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6142},{"key":"muslim","label":"مسلم","number":1669}]},{"num":6907,"demo":false,"sanad":"","matn":["عن بشير بن يسار، زعم أن رجلاً من الأنصار يقال له سهل بن أبي حثمة أخبره أن نفراً من قومه انطلقوا إلى خيبر فتفرقوا فيها، ووجدوا أحدهم قتيلاً. فقالوا للذين وُجد فيهم: قد قتلتم صاحبنا. قالوا: ما قتلنا وما علمنا قاتلاً. فانطلقوا إلى النبي ﷺ فقالوا: يا رسول الله ﷺ، انطلقنا إلى خيبر فوجدنا أحدنا قتيلاً. فقال: (( الكبر الكبر )). فقال لهم: (( تأتون بالبينة على من قتله؟ )) قالوا: ما لنا بينة. قال: (( فيحلفون )). قالوا: لا نرضى بأيمان اليهود. فكره رسول اللّٰه ﷺ أن يُبطل دمه، فوداه مائة من إبل الصدقة."],"takhrij":"متفق عليه: رواه البخاري (٦٨٩٨)، ومسلم (١٦٦٩/٥). هذا الحديث فيه اختصار من الرواة، وتفصيله أن النبي ﷺ طلب أولاً البينة من الأنصار، فقالوا: ما لنا بينة. فقال لهم: (( إذاً تحلفون وتستحقون دم صاحبكم )). فقالوا: كيف نحلف؟ فقال: (( فيحلفون )). فبهذا استقام معنى الحديث ولم يخالف بعضه بعضاً.","grade":"متفق عليه","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Agreed upon: narrated by al-Bukhari (6898) and Muslim (5:1669).","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Bushayr ibn Yasar claimed that a man from the Ansar called Sahl ibn Abi Hathmah informed him that some men from his people went to Khaybar and separated there. They found one of them murdered, and they said to those among whom he was found: “You killed our companion.” They said: “We did not kill him, nor do we know any killer.” So they went to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, we went to Khaybar and found one of us murdered.” He said: “Let the elders speak, let the elders speak.” Then he said to them: “Will you bring proof against the one who killed him?” They said: “We have no proof.” He said: “Then they will swear.” They said: “We do not accept the oaths of the Jews.” The Messenger of Allah ﷺ disliked allowing his blood to go to waste, so he paid his blood-money with one hundred camels from the alms camels."]},"buhuth":{"en":["This report is abbreviated by some narrators. Its fuller meaning is that the Prophet ﷺ first asked the Ansar for evidence. When they said they had none, he then said: “Then you may swear and deserve the blood of your companion.” They said: “How can we swear?” So he said: “Then they will swear.” In this way, the meaning is complete and the reports do not contradict one another."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6898},{"key":"muslim","label":"مسلم","number":1669}]},{"num":6908,"demo":false,"sanad":"","matn":["عن أبي قلابة:","أن عمر بن عبد العزيز أبرز سريره يومًا للناس، ثم أذن لهم فدخلوا، فقال:","ما تقولون في القسامة؟","قالوا:","نقول: القسامة القود بها حق، وقد أقادت بها الخلفاء.","قال لي:","ما تقول يا أبا قلابة؟","ونصبني للناس.","فقلت:","يا أمير المؤمنين، عندك رؤوس الأجناد وأشراف العرب، أرأيت لو أن خمسين منهم شهدوا على رجل محصن بدمشق أنه قد زنى، لم يروه، أكنت ترجمه؟","قال:","لا.","قلت:","أرأيت لو أن خمسين منهم شهدوا على رجل بحمص أنه سرق، أكنت تقطعه ولم يروه؟","قال:","لا.","قلت:","فوالله ما قتل رسول اللّٰه ﷺ قط إلا في إحدى ثلاث خصال: رجل قتل بجريرة نفسه فقتل، أو رجل زنى بعد إحصان، أو رجل حارب الله ورسوله وارتد عن الإسلام.","فقال القوم:","أوليس قد حدث أنس بن مالك أن رسول اللّٰه ﷺ قطع في السرق، وسمر الأعين، ثم نبذهم في الشمس؟","فقلت:","أنا أحدثكم حديث أنس.","حدثني أنس أن نفرًا من عكل، ثمانية، قدموا على رسول اللّٰه ﷺ فبايعوه على الإسلام، فاستوخموا الأرض فسقمت أجسامهم، فشكوا ذلك إلى رسول اللّٰه ﷺ.","قال:","«أَفَلَا تَخْرُجُونَ مَعَ رَاعِينَا فِي إِبِلِهِ، فَتُصِيبُونَ مِنْ أَلْبَانِهَا وَأَبْوَالِهَا؟»","قالوا:","بلى.","فخرجوا، فشربوا من ألبانها وأبوالها فصحوا، فقتلوا راعي رسول اللّٰه ﷺ وأطردوا النعم.","فبلغ ذلك رسول اللّٰه ﷺ، فأرسل في آثارهم، فأدركوا فجيء بهم، فأمر بهم، فقطعت أيديهم وأرجلهم، وسمرت أعينهم، ثم نبذوا في الشمس حتى ماتوا.","قلت:","وأي شيء أشد مما صنع هؤلاء؟ ارتدوا عن الإسلام، وقتلوا، وسرقوا.","فقال عنبسة بن سعيد:","والله إن سمعت كاليوم قط.","فقلت:","أترد علي حديثي يا عنبسة؟","قال:","لا، ولكن جئت بالحديث على وجهه. والله لا يزال هذا الجند بخير ما عاش هذا الشيخ بين أظهرهم.","قلت:","وقد كان في هذا سنة من رسول اللّٰه ﷺ: دخل عليه نفر من الأنصار فتحدثوا عنده، فخرج رجل منهم بين أيديهم فقتل، فخرجوا بعده، فإذا هم بصاحبهم يتشحط في الدم.","فرجعوا إلى رسول اللّٰه ﷺ فقالوا:","يا رسول الله ﷺ، صاحبنا كان يتحدث معنا، فخرج بين أيدينا، فإذا نحن به يتشحط في الدم.","فخرج رسول اللّٰه ﷺ فقال:","«بِمَنْ تَظُنُّونَ، أَوْ تَرَوْنَ، قَتَلَهُ؟»","قالوا:","نرى أن اليهود قتلته.","فأرسل إلى اليهود فدعاهم، فقال:","«أَنْتُمْ قَتَلْتُمْ هَذَا؟»","قالوا:","لا.","قال:","«أَتَرْضَوْنَ نَفْلَ خَمْسِينَ مِنَ الْيَهُودِ مَا قَتَلُوهُ؟»","فقالوا:","ما يبالون أن يقتلونا أجمعين ثم ينتفلون.","قال:","«أَفَتَسْتَحِقُّونَ الدِّيَةَ بِأَيْمَانِ خَمْسِينَ مِنْكُمْ؟»","قالوا:","ما كنا لنحلف.","فوداه من عنده.","قلت:","وقد كانت هذيل خلعوا خليعًا لهم في الجاهلية، فطرق أهل بيت من اليمن بالبطحاء، فانتبه له رجل منهم فحذفه بالسيف فقتله.","فجاءت هذيل فأخذوا اليماني، فرفعوه إلى عمر بالموسم، وقالوا:","قتل صاحبنا.","فقال:","إنهم قد خلعوه.","فقال:","يقسم خمسون من هذيل ما خلعوه.","فأقسم منهم تسعة وأربعون رجلًا، وقدم رجل منهم من الشام، فسألوه أن يقسم، فافتدى يمينه منهم بألف درهم، فأدخلوا مكانه رجلًا آخر.","فدفعه إلى أخي المقتول، فقرنت يده بيده.","قالوا:","فانطلقا والخمسون الذين أقسموا، حتى إذا كانوا بنخلة أخذتهم السماء، فدخلوا في غار في الجبل، فانهجم الغار على الخمسين الذين أقسموا فماتوا جميعًا.","وأفلت القرينان، واتبعهما حجر فكسر رجل أخي المقتول، فعاش حولًا ثم مات.","قلت:","وقد كان عبد الملك بن مروان أقاد رجلًا بالقسامة، ثم ندم بعد ما صنع، فأمر بالخمسين الذين أقسموا فمحوا من الديوان، وسيرهم إلى الشام."],"takhrij":"صحيح: رواه البخاري (٦٨٩٩)، ومسلم (١٦٧١/١٠)، والسياق للبخاري.","grade":"صحيح","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6899) and Muslim (1671/10). This is the wording of al-Bukhārī.","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Abū Qilābah reported: One day ʿUmar ibn ʿAbd al-ʿAzīz brought out his couch for the people and then permitted them to enter. He asked: “What do you say concerning al-qasāmah?” They replied: “We hold that retaliation may validly be established through al-qasāmah, and the caliphs have carried out retaliation by means of it.” He asked me: “What do you say, O Abū Qilābah?” And he brought me forward before the people. I said: “O Commander of the Believers, you have with you the commanders of the armies and the nobles of the Arabs. Suppose fifty of them testified against a previously married man in Damascus that he had committed adultery, although they had not actually seen it. Would you stone him?”","He replied: “No.” I said: “Suppose fifty of them testified against a man in Ḥimṣ that he had stolen, although they had not seen him do it. Would you cut off his hand?” He replied: “No.” I said: “By Allah, the Messenger of Allah ﷺ never put anyone to death except for one of three matters: a man who killed and was killed for his own crime; a man who committed adultery after having been married; or a man who fought Allah and His Messenger and apostatized from Islam.”","The people said: “Did Anas ibn Mālik not report that the Messenger of Allah ﷺ cut off hands and branded eyes, then left those people in the sun?” I said: “I will relate to you the hadith of Anas.” Anas told me that eight men from ʿUkl came to the Messenger of Allah ﷺ and pledged allegiance to Islam. They found the climate unhealthy, and their bodies became ill, so they complained to the Messenger of Allah ﷺ. He said: “Why do you not go out with our shepherd among his camels and drink some of their milk and urine?”","They replied: “Yes.” They went out, drank their milk and urine, and recovered. Then they killed the shepherd of the Messenger of Allah ﷺ and drove away the camels. When the Messenger of Allah ﷺ learned of this, he sent men after them. They were caught and brought back. He ordered that their hands and feet be cut off and their eyes branded, and then they were left in the sun until they died. I said: “What could be more serious than what these people did? They apostatized from Islam, killed, and stole.”","ʿAnbasah ibn Saʿīd said: “By Allah, I have never heard anything like what I heard today.” I asked: “Are you rejecting my hadith, O ʿAnbasah?” He replied: “No. Rather, you have presented the hadith in its complete form. By Allah, this army will remain upon good so long as this old man remains among them.” I said: “There was also a precedent from the Messenger of Allah ﷺ concerning this matter. A group of the Anṣār entered upon him and spoke with him. One of them left ahead of the others and was killed. When the others went out, they found their companion writhing in his blood.","They returned to the Messenger of Allah ﷺ and said: ‘O Messenger of Allah ﷺ, our companion was speaking with us, then he went out ahead of us, and we found him writhing in his blood.’ The Messenger of Allah ﷺ went out and asked: ‘Whom do you suspect—or whom do you think—killed him?’ They replied: ‘We think the Jews killed him.’ He sent for the Jews and summoned them, then asked: ‘Did you kill this man?’ They replied: ‘No.’ He asked the Anṣār: ‘Would you accept fifty Jews swearing that they did not kill him?’","They replied: ‘They would not care if they killed all of us and then swore falsely.’ He said: ‘Then will you become entitled to the blood-money by fifty oaths from among yourselves?’ They replied: ‘We would not swear.’ So the Messenger of Allah ﷺ paid his blood-money himself. I also said: “In the pre-Islamic period, Hudhayl had formally disowned one of their men. He came by night to a household from Yemen at al-Baṭḥāʾ. A man among them awoke and struck him with a sword, killing him.","Hudhayl seized the Yemeni and brought him before ʿUmar during the pilgrimage season, saying: ‘He killed our companion.’ ʿUmar said: ‘They had disowned him.’ He then ordered: ‘Let fifty men from Hudhayl swear that they had not disowned him.’ Forty-nine men swore. Then a man among them arrived from Syria, and they asked him to swear. He bought himself out of taking the oath by giving them one thousand dirhams, so they substituted another man in his place.","That man was handed over to the murdered man’s brother, and their hands were tied together. They set out together with the fifty men who had sworn. When they reached Nakhlah, a storm overtook them, so they entered a cave in the mountain. The cave collapsed upon the fifty men who had sworn, and all of them died. The two men tied together escaped, but a rock followed them and broke the leg of the murdered man’s brother. He lived for one year and then died.”","I also said: “ʿAbd al-Malik ibn Marwān once executed a man on the basis of al-qasāmah, but afterward regretted what he had done. He ordered that the fifty men who had sworn be removed from the official register and sent away to Syria.”"]},"buhuth":{"ar":["وطريق الجمع بين هذا الحديث والأحاديث التي قبله أن يقال: حفظ بعضهم ما لم يحفظ الآخر. وتفصيله أن النبي ﷺ طلب البينة أولًا من المدعين وهم الأنصار، فلما لم تكن عندهم البينة عرض عليهم الأيمان فامتنعوا، ثم عرض عليهم تحليف اليهود فأبوا، فوداه رسول اللّٰه ﷺ من عنده من بيت المال، حتى لا يتعارض بعض الحديث مع بعض، والقصة واحدة."],"en":["The way to reconcile this hadith with the preceding reports is that some narrators preserved details that others did not. The complete sequence is that the Prophet ﷺ first asked the claimants—the Anṣār—for evidence. When they had no evidence, he offered them the option of taking the oaths, but they refused. He then offered to have the Jews swear, but they refused to accept their oaths. The Messenger of Allah ﷺ therefore paid the blood-money himself from the public treasury. In this way the narrations do not contradict one another; they concern the same incident."]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":6899},{"key":"muslim","label":"مسلم","number":1671}]},{"num":6909,"demo":false,"sanad":"","matn":["عن بُشير بن يسار مولى بني حارثة الأنصاريين، وكان شيخاً كبيراً فقيهاً، وكان قد أدرك من أهل داره من بني حارثة من أصحاب النبي ﷺ رجالاً، منهم رافع بن خديج، وسهل بن أبي حثمة، وسويد بن النعمان. حدثوه أن القسامة كانت فيهم في بني حارثة بن الحارث في رجل من الأنصار يُدعى عبد اللّٰه بن سهل قُتل بخيبر، وأن رسول اللّٰه ﷺ قال لهم: (( تحلفون لخمسين فتستحقون قاتلكم )) أو قال: (( صاحبكم )). قالوا: يا رسول الله ﷺ، ما شهدنا ولا حضرنا. فزعم بُشير أن رسول اللّٰه ﷺ قال لهم: (( فتبرئكم يهود بخمسين )) فذكره."],"takhrij":"حسن: رواه البيهقي (٨/١١٩).","grade":"حسن","chapter_ar":"باب تبدئة أهل الدم في القسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Authentic: narrated by al-Bayhaqi (8/119).","chapter_en":"Beginning with the claimants in al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Bushayr ibn Yasar, the freedman of Banu Harithah of the Ansar, who was an elderly and learned man, reported that he had met among the people of his district from Banu Harithah some Companions of the Prophet ﷺ, including Rafi ibn Khadij, Sahl ibn Abi Hathmah, and Suwayd ibn al-Nuʿman. They told him that al-qasamah was applied among them, in Banu Harithah ibn al-Harith, regarding a man from the Ansar called Abdullah ibn Sahl who was killed at Khaybar. The Messenger of Allah ﷺ said to them: “Will fifty of you swear so that you may deserve your slain man,” or he said, “your companion?” They said: “O Messenger of Allah ﷺ, we neither witnessed nor were present.” Bushayr claimed that the Messenger of Allah ﷺ then said to them: “Then the Jews will clear themselves by fifty oaths,” and then he mentioned the rest of the story."]}},"tuhfa":{},"refs":[{"key":"البیہقی","label":"البيهقي","number":8},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":16435,"n":16593}]},{"num":6910,"demo":false,"sanad":"","matn":["عن سهل بن أبي حثمة أن رسول اللّٰه ﷺ قال: (( تسمون قاتلكم، ثم تحلفون عليه خمسين يميناً فنسلمه إليكم ))."],"takhrij":"حسن: رواه ابن أبي عاصم في الديات (٢٥٩) واللفظ له، وأحمد (١٦٠٩٦)، والبيهقي (٨/١٢٦).","grade":"حسن","chapter_ar":"باب ماجاء في القتل بالقسامة","chapter_ur":"","part_ar":"كتاب القصاص والجنايات","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abi Asim in al-Diyat (259), and this is his wording, as well as Ahmad (16096) and al-Bayhaqi (8/126).","chapter_en":"What has come regarding execution based on al-qasamah","part_en":"The Book of Retaliation and Criminal Offenses","group_ar":"جموع ما جاء في القسامة","group_en":"Collection of chapters on al-qasamah","part_no":32,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Sahl ibn Abi Hathmah reported that the Messenger of Allah ﷺ said: “You will name your killer, then swear fifty oaths against him, and we will hand him over to you.”"]}},"tuhfa":{},"refs":[{"key":"ابن_ابی_عاصم/الدیات","label":"ابن أبي عاصم في الديات","number":259},{"key":"البیہقی","label":"البيهقي","number":8},{"key":"ahmad","label":"مسند الإمام أحمد","number":16096,"n":16096},{"key":"kubrabayhaqi","label":"السنن الكبرى للبيهقي","number":16456,"n":16614}]},{"num":6911,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: قال رسول اللّٰه ﷺ: (( لا يزني الزاني حين يزني وهو مؤمن، ولا يسرق حين يسرق وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن))."],"takhrij":"متفق عليه: رواه البخاري (٥٥٧٨) ومسلم (٥٧).","grade":"متفق عليه","chapter_ar":"باب ما جاء من المحرمات","chapter_ur":"","part_ar":"كتاب الحدود","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhari (5578) and Muslim (57).","chapter_en":"What Has Been Reported Regarding Forbidden Acts","part_en":"Book of Legal Punishments","group_ar":"جموع ما جاء في الحدود عامة","group_en":"General Narrations Regarding Legal Punishments","part_no":33,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “The adulterer is not a believer at the moment he commits adultery, the thief is not a believer at the moment he steals, and the one who drinks intoxicants is not a believer at the moment he drinks them.”"]}},"tuhfa":{},"refs":[{"key":"bukhari","label":"البخاري","number":5578},{"key":"muslim","label":"مسلم","number":57}]}]);
